import type { BankQuestion } from "@/lib/bank";

/** Pedagogy of Maths, EVS and Languages (Child Development & Pedagogy): 2000 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"cdp-pedagogy-subjects-1","question":"In the Van Hiele model of geometric thinking, the basic level at which a child recognises shapes by their overall appearance (\"it looks like a door, so it is a rectangle\") is called:","options":["Visualisation","Informal deduction","Analysis","Rigour"],"answer":0,"explanation":"Level 0 (visualisation, or recognition) is based on the look of the whole shape. Analysis (Level 1) is the next level, where children describe a shape by its properties.","difficulty":"easy","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"ज्यामितीय चिंतन के वान हील मॉडल में वह आधारभूत स्तर, जिसमें बच्चा आकृतियों को उनके समग्र रूप से पहचानता है (“यह दरवाज़े जैसा दिखता है, इसलिए यह आयत है”), कहलाता है:","optionsHi":["दृश्यीकरण","अनौपचारिक निगमन","विश्लेषण","कठोरता (रिगर)"],"explanationHi":"स्तर 0 (दृश्यीकरण या पहचान) पूरी आकृति के रूप-रंग पर आधारित होता है। विश्लेषण (स्तर 1) अगला स्तर है, जिसमें बच्चे किसी आकृति का वर्णन उसके गुणों के आधार पर करते हैं।"},
  {"id":"cdp-pedagogy-subjects-2","question":"According to the NCF 2005 position on mathematics, the main goal of school mathematics is to develop the child's:","options":["speed and accuracy in mechanical calculation","memory for formulae and standard procedures","ability to score well in board and competitive examinations","ability to think mathematically (mathematisation of thought)"],"answer":3,"explanation":"NCF 2005 names the 'mathematisation' of the child's thinking as the main goal, ahead of narrow goals such as computation speed or rote formulae.","difficulty":"easy","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"गणित पर NCF 2005 के दृष्टिकोण के अनुसार, विद्यालयी गणित का मुख्य लक्ष्य बच्चे में किसका विकास करना है?","optionsHi":["यांत्रिक गणना में गति और शुद्धता","सूत्रों और मानक विधियों को याद रखने की क्षमता","बोर्ड और प्रतियोगी परीक्षाओं में अच्छे अंक पाने की क्षमता","गणितीय ढंग से सोचने की क्षमता (चिंतन का गणितीकरण)"],"explanationHi":"NCF 2005 बच्चे की सोच के ‘गणितीकरण’ को मुख्य लक्ष्य मानता है, जो गणना की गति या रटे हुए सूत्रों जैसे संकीर्ण लक्ष्यों से ऊपर है।"},
  {"id":"cdp-pedagogy-subjects-3","question":"As recommended by NCF 2005, Environmental Studies (EVS) for Classes III to V is an integrated subject that draws on:","options":["language and art education, taught through stories and drawing","history, geography and civics, as in the middle-school syllabus","physics, chemistry and biology, simplified for young children","science, social science and environmental education"],"answer":3,"explanation":"Primary EVS weaves together concerns of science, social science and environmental education instead of teaching them as separate disciplines.","difficulty":"easy","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"NCF 2005 की अनुशंसा के अनुसार, कक्षा III से V के लिए पर्यावरण अध्ययन (EVS) एक एकीकृत विषय है, जो किन पर आधारित है?","optionsHi":["भाषा और कला शिक्षा, जो कहानियों और चित्रकारी के माध्यम से पढ़ाई जाती है","इतिहास, भूगोल और नागरिक शास्त्र, जैसा मध्य विद्यालय के पाठ्यक्रम में होता है","भौतिकी, रसायन विज्ञान और जीव विज्ञान, जिन्हें छोटे बच्चों के लिए सरल बनाया गया हो","विज्ञान, सामाजिक विज्ञान और पर्यावरण शिक्षा"],"explanationHi":"प्राथमिक स्तर का EVS विज्ञान, सामाजिक विज्ञान और पर्यावरण शिक्षा की चिंताओं को अलग-अलग विषयों के रूप में पढ़ाने के बजाय एक साथ पिरोता है।"},
  {"id":"cdp-pedagogy-subjects-4","question":"The four basic language skills, in the order in which a child naturally acquires them, are:","options":["Listening, Speaking, Reading, Writing","Reading, Writing, Listening, Speaking","Listening, Reading, Speaking, Writing","Speaking, Listening, Reading, Writing"],"answer":0,"explanation":"Children listen before they speak, and learn to read before they write: the LSRW sequence. Receptive skills come before productive ones in each pair.","difficulty":"easy","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"भाषा के चार मूल कौशल, उस क्रम में जिसमें बच्चा उन्हें स्वाभाविक रूप से अर्जित करता है, हैं:","optionsHi":["सुनना, बोलना, पढ़ना, लिखना","पढ़ना, लिखना, सुनना, बोलना","सुनना, पढ़ना, बोलना, लिखना","बोलना, सुनना, पढ़ना, लिखना"],"explanationHi":"बच्चे बोलने से पहले सुनते हैं और लिखने से पहले पढ़ना सीखते हैं: यही LSRW क्रम है। हर जोड़ी में ग्रहणशील कौशल उत्पादक कौशल से पहले आते हैं।"},
  {"id":"cdp-pedagogy-subjects-5","question":"A Class II child writes 25 + 17 = 312. The error most likely shows that the child:","options":["does not yet know the number names and numerals beyond 50","cannot reliably add single-digit numbers such as 5 and 7","adds the digits correctly but does not regroup (carry) the ten","has a reading disability that makes the digits appear reversed to him"],"answer":2,"explanation":"5 + 7 = 12 is written in full and 2 + 1 = 3 is written beside it, giving 312. The child adds digits correctly but has not grasped place value and carrying.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कक्षा II का एक बच्चा 25 + 17 = 312 लिखता है। यह त्रुटि सबसे अधिक संभावना से दर्शाती है कि बच्चा:","optionsHi":["50 से आगे की संख्या-नाम और अंक अभी नहीं जानता","5 और 7 जैसी एक अंक की संख्याओं को भी विश्वसनीय ढंग से नहीं जोड़ पाता","अंकों को सही जोड़ता है, लेकिन दहाई का पुनर्समूहन (हासिल) नहीं करता","उसे पठन अक्षमता है, जिसके कारण उसे अंक उलटे दिखाई देते हैं"],"explanationHi":"5 + 7 = 12 पूरा लिखा गया है और 2 + 1 = 3 उसके बगल में लिखा गया है, जिससे 312 बनता है। बच्चा अंकों को सही जोड़ता है, लेकिन स्थानीय मान और हासिल की अवधारणा नहीं समझ पाया है।"},
  {"id":"cdp-pedagogy-subjects-6","question":"Which is the most appropriate way to introduce fractions to Class III children?","options":["Writing 1/2 and 1/4 on the board and reading them aloud","Giving worksheets on adding unlike fractions to build speed","Defining the numerator and denominator before any examples","Sharing a roti or a sheet of paper equally among children"],"answer":3,"explanation":"Fractions grow out of the everyday experience of equal sharing. Concrete sharing should come before symbols and definitions.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कक्षा III के बच्चों को भिन्न से परिचित कराने का सबसे उपयुक्त तरीका कौन-सा है?","optionsHi":["श्यामपट्ट पर 1/2 और 1/4 लिखकर उन्हें ज़ोर से पढ़ना","गति बढ़ाने के लिए असमान हर वाली भिन्नों के योग के अभ्यास-पत्र देना","किसी भी उदाहरण से पहले अंश और हर की परिभाषा बताना","बच्चों के बीच एक रोटी या कागज़ की एक शीट को बराबर-बराबर बाँटना"],"explanationHi":"भिन्न की समझ बराबर बाँटने के रोज़मर्रा के अनुभव से विकसित होती है। प्रतीकों और परिभाषाओं से पहले मूर्त बँटवारे का अनुभव कराना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-7","question":"The NCERT EVS textbooks for Classes III to V, prepared after NCF 2005, are organised around themes such as:","options":["Family and Friends, Food, Shelter, Water, Travel, Things We Make and Do","Grammar, Composition, Comprehension, Poetry, Prose and Letter Writing","Physics, Chemistry, Biology, Geography and Civics as separate units","Ancient, Medieval and Modern History, with maps and civic institutions"],"answer":0,"explanation":"The primary EVS syllabus uses six child-centred themes: Family and Friends (relationships, work and play, animals, plants), Food, Shelter, Water, Travel, and Things We Make and Do. It avoids subject divisions.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"NCF 2005 के बाद तैयार की गई कक्षा III से V की NCERT EVS पाठ्यपुस्तकें किन विषय-वस्तुओं (थीम) के आधार पर संगठित हैं?","optionsHi":["परिवार और मित्र, भोजन, आवास, जल, यात्रा, हम क्या बनाते और करते हैं","व्याकरण, रचना, बोध, कविता, गद्य और पत्र-लेखन","भौतिकी, रसायन विज्ञान, जीव विज्ञान, भूगोल और नागरिक शास्त्र अलग-अलग इकाइयों के रूप में","प्राचीन, मध्यकालीन और आधुनिक इतिहास, मानचित्रों और नागरिक संस्थाओं के साथ"],"explanationHi":"प्राथमिक EVS पाठ्यक्रम छह बाल-केंद्रित थीम पर आधारित है: परिवार और मित्र (संबंध, काम और खेल, पशु, पौधे), भोजन, आवास, जल, यात्रा, और हम क्या बनाते और करते हैं। इसमें विषयों का विभाजन नहीं किया गया है।"},
  {"id":"cdp-pedagogy-subjects-8","question":"A teacher asks children to run their eyes quickly over a passage only to find the year in which a dam was built. The reading strategy being practised is:","options":["scanning","intensive reading","extensive reading","skimming"],"answer":0,"explanation":"Scanning means searching a text quickly for one specific piece of information, such as a date or name. Skimming means reading quickly to get the general idea.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"एक शिक्षक बच्चों से कहता है कि वे किसी अनुच्छेद पर तेज़ी से नज़र दौड़ाएँ, केवल यह पता लगाने के लिए कि कोई बाँध किस वर्ष बना था। यहाँ किस पठन-रणनीति का अभ्यास कराया जा रहा है?","optionsHi":["स्कैनिंग (खोजपूर्वक पठन)","गहन पठन","विस्तृत पठन","स्किमिंग (सरसरी पठन)"],"explanationHi":"स्कैनिंग का अर्थ है किसी पाठ में कोई एक विशिष्ट जानकारी, जैसे तारीख या नाम, तेज़ी से खोजना। स्किमिंग का अर्थ है सामान्य विचार जानने के लिए तेज़ी से पढ़ना।"},
  {"id":"cdp-pedagogy-subjects-9","question":"Which classroom practice best reflects the multilingual approach recommended by NCF 2005?","options":["Teaching only in English from Class I so that children pick it up faster","Translating every textbook sentence word for word into the home language","Letting children use their home language as a bridge to the school language","Fining children who speak their mother tongue so that they practise English"],"answer":2,"explanation":"NCF 2005 treats multilingualism as a resource. The child's home language is a bridge to the school language, not something to suppress.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कौन-सी कक्षा-गतिविधि NCF 2005 द्वारा अनुशंसित बहुभाषिक दृष्टिकोण को सबसे अच्छे ढंग से दर्शाती है?","optionsHi":["कक्षा I से ही केवल अंग्रेज़ी में पढ़ाना ताकि बच्चे उसे जल्दी सीख लें","पाठ्यपुस्तक के हर वाक्य का घरेलू भाषा में शब्द-दर-शब्द अनुवाद करना","बच्चों को घरेलू भाषा को विद्यालयी भाषा तक पहुँचने के सेतु के रूप में उपयोग करने देना","मातृभाषा बोलने वाले बच्चों पर जुर्माना लगाना ताकि वे अंग्रेज़ी का अभ्यास करें"],"explanationHi":"NCF 2005 बहुभाषिकता को एक संसाधन मानता है। बच्चे की घरेलू भाषा विद्यालयी भाषा तक पहुँचने का सेतु है, उसे दबाने की चीज़ नहीं।"},
  {"id":"cdp-pedagogy-subjects-10","question":"Using mathematical puzzles and games in a primary class mainly helps to:","options":["build logical reasoning and reduce fear of mathematics","replace the textbook entirely with play-based activities","test how well children have memorised tables and formulae","keep children busy and quiet when the teacher is absent"],"answer":0,"explanation":"Puzzles and games make children reason, try strategies and enjoy mathematics, which counters maths anxiety. They add to the textbook; they do not replace it.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"प्राथमिक कक्षा में गणितीय पहेलियों और खेलों का उपयोग मुख्य रूप से किसमें सहायक होता है?","optionsHi":["तार्किक चिंतन विकसित करने और गणित के भय को कम करने में","पाठ्यपुस्तक को पूरी तरह खेल-आधारित गतिविधियों से बदलने में","यह जाँचने में कि बच्चों ने पहाड़े और सूत्र कितने अच्छे से याद किए हैं","शिक्षक की अनुपस्थिति में बच्चों को व्यस्त और शांत रखने में"],"explanationHi":"पहेलियाँ और खेल बच्चों को तर्क करने, रणनीतियाँ आज़माने और गणित का आनंद लेने का अवसर देते हैं, जिससे गणित-चिंता कम होती है। ये पाठ्यपुस्तक के पूरक हैं, उसका स्थान नहीं लेते।"},
  {"id":"cdp-pedagogy-subjects-11","question":"Which approach to teaching reading begins with whole, meaningful texts such as stories and rhymes and treats reading as making meaning, not decoding isolated letters?","options":["Phonics approach","Alphabetic method","Whole language approach","Grammar-translation method"],"answer":2,"explanation":"The whole language approach starts from meaningful text and the child's experience. Phonics and the alphabetic method build up from sounds or letters.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"पठन शिक्षण का कौन-सा उपागम कहानियों और तुकबंदियों जैसे पूर्ण, अर्थपूर्ण पाठों से शुरू होता है और पठन को अलग-अलग अक्षरों को डिकोड करने के बजाय अर्थ-निर्माण मानता है?","optionsHi":["ध्वनि-विज्ञान (फ़ोनिक्स) उपागम","वर्णमाला विधि","समग्र भाषा उपागम","व्याकरण-अनुवाद विधि"],"explanationHi":"समग्र भाषा उपागम अर्थपूर्ण पाठ और बच्चे के अनुभव से शुरू होता है। फ़ोनिक्स और वर्णमाला विधि ध्वनियों या अक्षरों से आगे की ओर निर्माण करती हैं।"},
  {"id":"cdp-pedagogy-subjects-12","question":"A Class IV teacher takes children to a nearby pond as part of an EVS lesson. The main value of this field visit is that it:","options":["gives children a relaxing break from textbook-based studies","replaces the need for any further assessment of the chapter","helps the teacher finish the syllabus faster by covering it outdoors","lets children observe first-hand and link learning to their surroundings"],"answer":3,"explanation":"EVS aims to link classroom knowledge with the child's environment. First-hand observation and exploration on a field visit serve exactly that.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कक्षा IV का एक शिक्षक EVS के पाठ के भाग के रूप में बच्चों को पास के तालाब पर ले जाता है। इस क्षेत्र-भ्रमण का मुख्य मूल्य यह है कि वह:","optionsHi":["बच्चों को पाठ्यपुस्तक-आधारित पढ़ाई से आराम देने वाला अवकाश देता है","अध्याय के आगे के किसी भी आकलन की आवश्यकता को समाप्त कर देता है","पाठ्यक्रम को बाहर पूरा करके शिक्षक को उसे जल्दी समाप्त करने में मदद करता है","बच्चों को प्रत्यक्ष अवलोकन करने और सीखने को अपने परिवेश से जोड़ने का अवसर देता है"],"explanationHi":"EVS का उद्देश्य कक्षा के ज्ञान को बच्चे के परिवेश से जोड़ना है। क्षेत्र-भ्रमण में प्रत्यक्ष अवलोकन और खोजबीन ठीक यही उद्देश्य पूरा करते हैं।"},
  {"id":"cdp-pedagogy-subjects-13","question":"According to the Van Hiele model, a child who explains that 'a square is also a rectangle, because it has four right angles and its opposite sides are equal' is at the level of:","options":["Visualisation","Formal deduction","Informal deduction","Analysis"],"answer":2,"explanation":"Seeing class inclusion (every square is a rectangle) by relating properties is Level 2, informal deduction (also called abstraction or ordering). At the analysis level, children list properties but treat squares and rectangles as separate.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"वान हील मॉडल के अनुसार, जो बच्चा समझाता है कि ‘वर्ग भी एक आयत है, क्योंकि उसके चारों कोण समकोण हैं और आमने-सामने की भुजाएँ बराबर हैं’, वह किस स्तर पर है?","optionsHi":["दृश्यीकरण","औपचारिक निगमन","अनौपचारिक निगमन","विश्लेषण"],"explanationHi":"गुणों को आपस में जोड़कर वर्ग-समावेशन (हर वर्ग एक आयत है) को देख पाना स्तर 2, अनौपचारिक निगमन (जिसे अमूर्तीकरण या क्रमबद्धता भी कहते हैं) है। विश्लेषण स्तर पर बच्चे गुणों की सूची बनाते हैं, लेकिन वर्ग और आयत को अलग-अलग मानते हैं।"},
  {"id":"cdp-pedagogy-subjects-14","question":"Many Class V children say that 0.25 is greater than 0.5 'because 25 is more than 5'. The most effective teaching response is to:","options":["ask them to memorise the rule 'compare digit by digit' and apply it","show tenths and hundredths on place-value charts or 10 × 10 grids","give them more practice on the same kind of sums until errors stop","tell them they are being careless and ask them to check their work"],"answer":1,"explanation":"The error comes from treating decimals as whole numbers, which is a misconception, not carelessness. Visual models of tenths and hundredths rebuild the concept. Drill or rules alone leave the misconception in place.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कक्षा V के कई बच्चे कहते हैं कि 0.25, 0.5 से बड़ा है ‘क्योंकि 25, 5 से अधिक है’। सबसे प्रभावी शिक्षण-प्रतिक्रिया क्या होगी?","optionsHi":["उनसे नियम ‘अंक-दर-अंक तुलना करो’ को याद करने और लागू करने को कहना","स्थानीय मान चार्ट या 10 × 10 ग्रिड पर दशमांश और सौवाँ भाग दिखाना","उन्हें उसी प्रकार के और प्रश्न तब तक हल कराना जब तक गलतियाँ बंद न हो जाएँ","उनसे कहना कि वे लापरवाही कर रहे हैं और अपना काम जाँचें"],"explanationHi":"यह त्रुटि दशमलव को पूर्ण संख्या मान लेने से आती है, जो एक भ्रांत धारणा है, लापरवाही नहीं। दशमांश और सौवें भाग के दृश्य मॉडल अवधारणा को फिर से बनाते हैं। केवल अभ्यास या नियम भ्रांत धारणा को बनाए रखते हैं।"},
  {"id":"cdp-pedagogy-subjects-15","question":"According to NCF 2005, the concerns of EVS in Classes I and II should be:","options":["taught as formal science, with simple experiments and definitions","integrated with language and mathematics, not a separate subject","left out entirely, since young children are not ready for it","taught as a separate subject with its own EVS textbook and tests"],"answer":1,"explanation":"NCF 2005 says that in Classes I and II the EVS themes should be integrated with language and mathematics. EVS becomes a separate subject from Class III.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"NCF 2005 के अनुसार, कक्षा I और II में EVS की विषय-वस्तु कैसे होनी चाहिए?","optionsHi":["सरल प्रयोगों और परिभाषाओं के साथ औपचारिक विज्ञान के रूप में पढ़ाई जाए","भाषा और गणित के साथ एकीकृत हो, अलग विषय के रूप में नहीं","पूरी तरह छोड़ दी जाए, क्योंकि छोटे बच्चे इसके लिए तैयार नहीं होते","अपनी EVS पाठ्यपुस्तक और परीक्षाओं के साथ अलग विषय के रूप में पढ़ाई जाए"],"explanationHi":"NCF 2005 के अनुसार कक्षा I और II में EVS की विषय-वस्तु भाषा और गणित के साथ एकीकृत होनी चाहिए। EVS कक्षा III से अलग विषय बनता है।"},
  {"id":"cdp-pedagogy-subjects-16","question":"A Class III child insists that 'the sun moves around the earth, because I can see it moving across the sky'. In a constructivist EVS classroom, the teacher should treat this as:","options":["evidence of a learning disability needing referral to a specialist","a sign of low intelligence that calls for extra drill on facts","a wrong answer to be crossed out at once and replaced with the correct fact","an alternative conception from experience, to build on through exploration"],"answer":3,"explanation":"Children build ideas from experience. Constructivist teaching draws out such alternative conceptions and uses activities and discussion to rebuild them, instead of dismissing them.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कक्षा III का एक बच्चा ज़ोर देकर कहता है कि ‘सूर्य पृथ्वी के चारों ओर घूमता है, क्योंकि मैं उसे आसमान में चलते देख सकता हूँ’। एक रचनावादी EVS कक्षा में शिक्षक को इसे किस रूप में लेना चाहिए?","optionsHi":["अधिगम अक्षमता का प्रमाण, जिसके लिए किसी विशेषज्ञ के पास भेजना आवश्यक है","कम बुद्धि का संकेत, जिसके लिए तथ्यों का अतिरिक्त अभ्यास कराना ज़रूरी है","गलत उत्तर, जिसे तुरंत काटकर सही तथ्य से बदल देना चाहिए","अनुभव से बनी एक वैकल्पिक अवधारणा, जिस पर खोजबीन के माध्यम से आगे बढ़ना चाहिए"],"explanationHi":"बच्चे अनुभव से विचार बनाते हैं। रचनावादी शिक्षण ऐसी वैकल्पिक अवधारणाओं को सामने लाता है और उन्हें खारिज करने के बजाय गतिविधियों और चर्चा के माध्यम से उनका पुनर्निर्माण करता है।"},
  {"id":"cdp-pedagogy-subjects-17","question":"Stephen Krashen's input hypothesis states that a second language is acquired when the learner:","options":["gets comprehensible input just beyond the current level (i + 1)","is corrected on every error at once so that mistakes do not fossilise","is taught explicit grammar rules first and then applies them in speech","repeats pattern drills until correct responses become automatic habits"],"answer":0,"explanation":"Krashen argued that acquisition happens through understanding messages slightly beyond one's level (i + 1). Drills and constant correction belong to behaviourist methods.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"स्टीफ़न क्रैशेन की निवेश परिकल्पना (इनपुट हाइपोथीसिस) के अनुसार, द्वितीय भाषा तब अर्जित होती है जब अधिगमकर्ता:","optionsHi":["वर्तमान स्तर से थोड़ा आगे का बोधगम्य निवेश (i + 1) पाता है","हर त्रुटि पर तुरंत सुधारा जाता है ताकि गलतियाँ पक्की न हों","पहले स्पष्ट व्याकरण-नियम सीखता है और फिर उन्हें बोलचाल में लागू करता है","पैटर्न-अभ्यास तब तक दोहराता है जब तक सही उत्तर स्वचालित आदत न बन जाएँ"],"explanationHi":"क्रैशेन का तर्क था कि अर्जन अपने स्तर से थोड़ा आगे (i + 1) के संदेशों को समझने से होता है। अभ्यास-कवायद और निरंतर सुधार व्यवहारवादी विधियों के अंग हैं।"},
  {"id":"cdp-pedagogy-subjects-18","question":"A four-year-old says, 'I goed to the market and buyed two mangoes.' From the viewpoint of language development, this shows that the child:","options":["has a speech disorder that needs early referral for therapy","should be corrected sharply so that the error does not become fixed","is overgeneralising the past-tense rule, a normal sign of learning","is copying the incorrect speech of adults around the child"],"answer":2,"explanation":"Overgeneralisation shows the child has worked out the past-tense rule and is applying it to irregular verbs too. Children never hear adults say 'goed', so it is not imitation. It is a normal stage.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"चार वर्ष का एक बच्चा कहता है, ‘I goed to the market and buyed two mangoes.’ भाषा विकास की दृष्टि से यह दर्शाता है कि बच्चा:","optionsHi":["उसे वाक् विकार है, जिसके लिए चिकित्सा हेतु शीघ्र किसी विशेषज्ञ के पास भेजना चाहिए","उसे कड़ाई से सुधारना चाहिए ताकि त्रुटि पक्की न हो जाए","भूतकाल के नियम का अतिसामान्यीकरण कर रहा है, जो सीखने का एक सामान्य लक्षण है","अपने आसपास के वयस्कों की गलत बोली की नकल कर रहा है"],"explanationHi":"अतिसामान्यीकरण दर्शाता है कि बच्चे ने भूतकाल का नियम समझ लिया है और उसे अनियमित क्रियाओं पर भी लागू कर रहा है। बच्चे वयस्कों को ‘goed’ कहते कभी नहीं सुनते, इसलिए यह नकल नहीं है। यह एक सामान्य अवस्था है।"},
  {"id":"cdp-pedagogy-subjects-19","question":"Which assessment task is most suitable for assessing the speaking skill of Class IV children?","options":["An oral narration or role-play assessed with a simple rubric","A multiple-choice test on grammar and correct sentence forms","A dictation exercise read out slowly by the teacher","A fill-in-the-blanks worksheet on useful spoken phrases"],"answer":0,"explanation":"Speaking is a productive oral skill, so it is assessed through actual speaking tasks. The other options assess grammar knowledge, listening-and-writing or reading-and-writing.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कक्षा IV के बच्चों के बोलने के कौशल का आकलन करने के लिए कौन-सा कार्य सबसे उपयुक्त है?","optionsHi":["एक सरल रूब्रिक से आँका गया मौखिक वर्णन या भूमिका-निर्वाह","व्याकरण और सही वाक्य-रूपों पर बहुविकल्पीय परीक्षण","शिक्षक द्वारा धीरे-धीरे बोला गया श्रुतलेख अभ्यास","उपयोगी बोलचाल के वाक्यांशों पर रिक्त स्थान भरने का अभ्यास-पत्र"],"explanationHi":"बोलना एक उत्पादक मौखिक कौशल है, इसलिए उसका आकलन वास्तविक बोलने के कार्यों से किया जाता है। अन्य विकल्प व्याकरण के ज्ञान, सुनने-और-लिखने या पढ़ने-और-लिखने का आकलन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-20","question":"George Pólya's four steps of problem solving, in order, are:","options":["Devise a plan, understand the problem, look back, carry out the plan","Guess, check, revise, conclude","Understand the problem, devise a plan, carry out the plan, look back","Read, memorise, calculate, check"],"answer":2,"explanation":"Pólya's How to Solve It gives understand, plan, carry out and look back (review). The 'look back' step is often skipped in classrooms.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"जॉर्ज पोल्या के समस्या-समाधान के चार चरण, क्रम से, हैं:","optionsHi":["योजना बनाना, समस्या को समझना, पीछे मुड़कर देखना, योजना पर कार्य करना","अनुमान लगाना, जाँचना, संशोधित करना, निष्कर्ष निकालना","समस्या को समझना, योजना बनाना, योजना पर कार्य करना, पीछे मुड़कर देखना","पढ़ना, याद करना, गणना करना, जाँचना"],"explanationHi":"पोल्या की पुस्तक How to Solve It में समझना, योजना बनाना, योजना पर कार्य करना और पीछे मुड़कर देखना (पुनरावलोकन) के चरण दिए गए हैं। कक्षाओं में ‘पीछे मुड़कर देखना’ चरण अक्सर छोड़ दिया जाता है।"},
  {"id":"cdp-pedagogy-subjects-21","question":"To teach place value, a teacher first lets children bundle sticks into tens, then shows pictures of the bundles, and finally writes numerals such as 34. This sequence follows:","options":["the Van Hiele levels of geometric thought, from visual to formal","Vygotsky's zone of proximal development and scaffolding","Bruner's enactive, iconic and symbolic modes of representation","Piaget's idea of conservation of number and quantity"],"answer":2,"explanation":"Handling sticks is enactive, pictures are iconic and numerals are symbolic. This concrete–pictorial–abstract progression comes from Jerome Bruner.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"स्थानीय मान सिखाने के लिए एक शिक्षक पहले बच्चों से तीलियों के दहाई के बंडल बनवाता है, फिर बंडलों के चित्र दिखाता है, और अंत में 34 जैसी संख्याएँ लिखता है। यह क्रम किसका अनुसरण करता है?","optionsHi":["ज्यामितीय चिंतन के वान हील स्तर, दृश्य से औपचारिक तक","वाइगोत्स्की का निकटस्थ विकास का क्षेत्र और पाड़ (स्कैफ़ोल्डिंग)","ब्रूनर के निरूपण के क्रियात्मक, प्रतिबिंबात्मक और सांकेतिक रूप","पियाजे की संख्या और मात्रा के संरक्षण की अवधारणा"],"explanationHi":"तीलियों को हाथ में लेना क्रियात्मक है, चित्र प्रतिबिंबात्मक हैं और अंक सांकेतिक हैं। मूर्त–चित्रात्मक–अमूर्त का यह क्रम जेरोम ब्रूनर से आता है।"},
  {"id":"cdp-pedagogy-subjects-22","question":"The idea of 'language across the curriculum' means that:","options":["every subject lesson also builds the language and vocabulary of that subject","children should study as many languages as possible in school","English should be the medium of instruction for all subjects","language should be taught only in the language period, by language teachers"],"answer":0,"explanation":"Language and learning are inseparable. In a science or mathematics lesson, children also learn to describe, explain and argue in the language of that subject.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"‘पाठ्यचर्या में भाषा’ (language across the curriculum) के विचार का अर्थ है कि:","optionsHi":["हर विषय का पाठ उस विषय की भाषा और शब्दावली का भी निर्माण करता है","बच्चों को विद्यालय में अधिक से अधिक भाषाएँ पढ़नी चाहिए","सभी विषयों के लिए शिक्षा का माध्यम अंग्रेज़ी होना चाहिए","भाषा केवल भाषा के कालांश में, भाषा-शिक्षकों द्वारा पढ़ाई जानी चाहिए"],"explanationHi":"भाषा और अधिगम अविभाज्य हैं। विज्ञान या गणित के पाठ में भी बच्चे उस विषय की भाषा में वर्णन करना, समझाना और तर्क करना सीखते हैं।"},
  {"id":"cdp-pedagogy-subjects-23","question":"In mathematics pedagogy, 'mathematical communication' refers to children's ability to:","options":["talk freely with friends during the mathematics period","recite multiplication tables and formulae aloud fluently in chorus","write answers neatly, in the prescribed steps, in the notebook","explain and justify mathematical ideas using precise terms and symbols"],"answer":3,"explanation":"Mathematical communication means explaining one's reasoning, using correct terms and symbols, and justifying solutions to others. It is not just talking or neat writing.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"गणित शिक्षण में ‘गणितीय संप्रेषण’ से तात्पर्य बच्चों की किस क्षमता से है?","optionsHi":["गणित के कालांश में मित्रों से खुलकर बातें करने की","पहाड़े और सूत्र समूह में ज़ोर से धाराप्रवाह दोहराने की","उत्तर कॉपी में साफ़-सुथरे ढंग से, निर्धारित चरणों में लिखने की","सटीक पदों और प्रतीकों का उपयोग करके गणितीय विचारों को समझाने और उनका औचित्य बताने की"],"explanationHi":"गणितीय संप्रेषण का अर्थ है अपने तर्क को समझाना, सही पदों और प्रतीकों का उपयोग करना और दूसरों के सामने हल का औचित्य बताना। यह केवल बात करना या साफ़ लिखना नहीं है।"},
  {"id":"cdp-pedagogy-subjects-24","question":"NEP 2020 recommends that, wherever possible, the medium of instruction until at least Grade 5, and preferably till Grade 8 and beyond, should be:","options":["Hindi, as the most widely spoken language across the country","Sanskrit, as the classical root of most Indian languages","the home language, mother tongue or local/regional language","English, so that children are ready for higher education"],"answer":2,"explanation":"NEP 2020 (para 4.11) recommends the home language, mother tongue or local/regional language as the medium of instruction at least till Grade 5, preferably till Grade 8 and beyond.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"NEP 2020 अनुशंसा करती है कि जहाँ भी संभव हो, कम से कम कक्षा 5 तक, और अधिमानतः कक्षा 8 तथा उसके बाद भी, शिक्षा का माध्यम होना चाहिए:","optionsHi":["हिंदी, क्योंकि यह देश भर में सबसे अधिक बोली जाने वाली भाषा है","संस्कृत, क्योंकि यह अधिकांश भारतीय भाषाओं की शास्त्रीय जड़ है","घरेलू भाषा, मातृभाषा या स्थानीय/क्षेत्रीय भाषा","अंग्रेज़ी, ताकि बच्चे उच्च शिक्षा के लिए तैयार हो सकें"],"explanationHi":"NEP 2020 (अनुच्छेद 4.11) कम से कम कक्षा 5 तक, और अधिमानतः कक्षा 8 तथा उसके बाद भी, घरेलू भाषा, मातृभाषा या स्थानीय/क्षेत्रीय भाषा को शिक्षा का माध्यम बनाने की अनुशंसा करती है।"},
  {"id":"cdp-pedagogy-subjects-25","question":"How many of the following match the NCF 2005 position on school mathematics? I. The focus should shift from procedures to problem solving and mathematisation. II. Children should see mathematics as something to talk about, communicate and discuss. III. Mathematics should be taught only to children who show an aptitude for it. IV. Algorithms should be taught before children understand the concepts behind them.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II reflect NCF 2005, which wants children to enjoy, discuss and reason about mathematics. III goes against its 'mathematics for all' view, and IV goes against its focus on understanding. So only two match.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"विद्यालयी गणित पर NCF 2005 के दृष्टिकोण से निम्नलिखित में से कितने कथन मेल खाते हैं? I. ध्यान विधियों से हटकर समस्या-समाधान और गणितीकरण पर होना चाहिए। II. बच्चों को गणित को ऐसी चीज़ के रूप में देखना चाहिए जिसके बारे में बात की जाए, संप्रेषण किया जाए और चर्चा की जाए। III. गणित केवल उन्हीं बच्चों को पढ़ाया जाना चाहिए जो इसके लिए अभिरुचि दिखाते हैं। IV. बच्चों के अवधारणाएँ समझने से पहले उन्हें एल्गोरिदम सिखाए जाने चाहिए।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II NCF 2005 को दर्शाते हैं, जो चाहता है कि बच्चे गणित का आनंद लें, उस पर चर्चा करें और तर्क करें। III उसके ‘सबके लिए गणित’ के दृष्टिकोण के विरुद्ध है, और IV उसके समझ पर ज़ोर के विरुद्ध है। इसलिए केवल दो मेल खाते हैं।"},
  {"id":"cdp-pedagogy-subjects-26","question":"How many of the following statements about the National Curriculum Framework for School Education (NCF-SE) 2023 are correct? I. The Foundational Stage covers ages 3 to 6 (three years of pre-school plus Grades 1 and 2). II. Board examinations are to be offered at least twice a year. III. In Grades 9 and 10 students study two languages, at least two of which are native to India. IV. In Grades 11 and 12 students must study three languages.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only II is correct. The Foundational Stage covers ages 3 to 8, Grades 9 and 10 study three languages (at least two native to India), and Grades 11 and 12 study two languages (at least one native to India).","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"स्कूली शिक्षा के लिए राष्ट्रीय पाठ्यचर्या की रूपरेखा (NCF-SE) 2023 के बारे में निम्नलिखित में से कितने कथन सही हैं? I. आधारभूत चरण 3 से 6 वर्ष की आयु को कवर करता है (तीन वर्ष की पूर्व-विद्यालय शिक्षा तथा कक्षा 1 और 2)। II. बोर्ड परीक्षाएँ वर्ष में कम से कम दो बार आयोजित की जानी हैं। III. कक्षा 9 और 10 में विद्यार्थी दो भाषाएँ पढ़ते हैं, जिनमें से कम से कम दो भारत की मूल भाषाएँ हैं। IV. कक्षा 11 और 12 में विद्यार्थियों को तीन भाषाएँ पढ़नी होंगी।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल II सही है। आधारभूत चरण 3 से 8 वर्ष की आयु को कवर करता है, कक्षा 9 और 10 में तीन भाषाएँ पढ़ाई जाती हैं (कम से कम दो भारत की मूल भाषाएँ), और कक्षा 11 और 12 में दो भाषाएँ पढ़ाई जाती हैं (कम से कम एक भारत की मूल भाषा)।"},
  {"id":"cdp-pedagogy-subjects-27","question":"Match the teaching aid with its main use in mathematics: 1. Napier's bones 2. Geoboard 3. Dienes (base-ten) blocks 4. Tangram; a. Place value b. Multiplication c. Making figures from seven geometric pieces d. Area and perimeter using pegs and rubber bands","options":["1-a, 2-d, 3-b, 4-c","1-d, 2-b, 3-c, 4-a","1-b, 2-c, 3-a, 4-d","1-b, 2-d, 3-a, 4-c"],"answer":3,"explanation":"Napier's bones are rods for multiplication. A geoboard uses pegs and rubber bands to explore area and perimeter. Dienes blocks (units, longs, flats) model place value. A tangram has seven pieces for composing figures.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"गणित में शिक्षण-सहायक सामग्री का उसके मुख्य उपयोग से मिलान कीजिए: 1. नेपियर की छड़ें 2. जियोबोर्ड 3. डीन्स (आधार-दस) ब्लॉक 4. टैनग्राम; a. स्थानीय मान b. गुणा c. सात ज्यामितीय टुकड़ों से आकृतियाँ बनाना d. खूँटियों और रबर-बैंड की सहायता से क्षेत्रफल और परिमाप","optionsHi":["1-a, 2-d, 3-b, 4-c","1-d, 2-b, 3-c, 4-a","1-b, 2-c, 3-a, 4-d","1-b, 2-d, 3-a, 4-c"],"explanationHi":"नेपियर की छड़ें गुणा के लिए उपयोग की जाने वाली छड़ें हैं। जियोबोर्ड में खूँटियों और रबर-बैंड की सहायता से क्षेत्रफल और परिमाप की खोजबीन की जाती है। डीन्स ब्लॉक (इकाई, लॉन्ग, फ़्लैट) स्थानीय मान को निरूपित करते हैं। टैनग्राम में आकृतियाँ बनाने के लिए सात टुकड़े होते हैं।"},
  {"id":"cdp-pedagogy-subjects-28","question":"Assertion (A): Teachers should encourage children to estimate an answer before working it out. Reason (R): Estimation helps children judge whether an answer is reasonable and builds number sense.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true, and R explains A: estimating first gives a benchmark for spotting unreasonable answers and strengthens number sense, which is why it is encouraged.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): शिक्षकों को बच्चों को उत्तर निकालने से पहले उसका अनुमान लगाने के लिए प्रोत्साहित करना चाहिए। कारण (R): अनुमान लगाने से बच्चों को यह आँकने में मदद मिलती है कि उत्तर तर्कसंगत है या नहीं और संख्या-बोध विकसित होता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"दोनों सत्य हैं, और R, A की व्याख्या करता है: पहले अनुमान लगाने से अतार्किक उत्तरों को पहचानने का एक मानदंड मिलता है और संख्या-बोध मज़बूत होता है, इसीलिए इसे प्रोत्साहित किया जाता है।"},
  {"id":"cdp-pedagogy-subjects-29","question":"Assertion (A): Correcting every error a child makes while speaking a new language is the best way to ensure accuracy. Reason (R): Errors are a natural part of language learning and reveal the child's developing ideas about how the language works.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"R is true: errors are windows into the learner's developing grammar. A is false, because constant correction discourages children from speaking and harms fluency. Errors call for selective, sensitive feedback.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): नई भाषा बोलते समय बच्चे की हर त्रुटि को सुधारना शुद्धता सुनिश्चित करने का सबसे अच्छा तरीका है। कारण (R): त्रुटियाँ भाषा सीखने का स्वाभाविक हिस्सा हैं और यह दर्शाती हैं कि बच्चा भाषा की कार्यप्रणाली के बारे में क्या विचार बना रहा है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"R सत्य है: त्रुटियाँ अधिगमकर्ता के विकसित होते व्याकरण की झलक देती हैं। A असत्य है, क्योंकि लगातार सुधार करने से बच्चे बोलने से हतोत्साहित होते हैं और प्रवाह को नुकसान पहुँचता है। त्रुटियों पर चयनात्मक और संवेदनशील प्रतिपुष्टि देनी चाहिए।"},
  {"id":"cdp-pedagogy-subjects-30","question":"How many of the following statements about EVS at the primary level, as envisaged in NCF 2005, are correct? I. EVS is taught as a separate subject with its own textbook from Class I onwards. II. It aims to connect children's learning in school with their life outside school. III. It is to be assessed mainly through written tests of definitions. IV. Its themes are presented from the child's point of view rather than through subject divisions.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and IV are correct. I is wrong, because EVS is a separate subject only from Class III (it is integrated with language and maths in Classes I–II). III is wrong, because NCF 2005 wants continuous assessment through observation, activities and projects, not tests of definitions. So only two.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"NCF 2005 में परिकल्पित प्राथमिक स्तर पर EVS के बारे में निम्नलिखित में से कितने कथन सही हैं? I. EVS कक्षा I से ही अपनी पाठ्यपुस्तक के साथ अलग विषय के रूप में पढ़ाया जाता है। II. इसका उद्देश्य बच्चों की विद्यालय की सीख को विद्यालय के बाहर के जीवन से जोड़ना है। III. इसका आकलन मुख्य रूप से परिभाषाओं की लिखित परीक्षाओं से किया जाना है। IV. इसकी विषय-वस्तुएँ विषय-विभाजन के बजाय बच्चे के दृष्टिकोण से प्रस्तुत की जाती हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"II और IV सही हैं। I गलत है, क्योंकि EVS केवल कक्षा III से अलग विषय है (कक्षा I–II में यह भाषा और गणित के साथ एकीकृत है)। III गलत है, क्योंकि NCF 2005 परिभाषाओं की परीक्षाओं के बजाय अवलोकन, गतिविधियों और परियोजनाओं के माध्यम से सतत आकलन चाहता है। इसलिए केवल दो सही हैं।"},
  {"id":"cdp-pedagogy-subjects-31","question":"Which of the following is NOT a feature of the communicative approach to language teaching?","options":["A focus on meaning and fluency over perfect accuracy","Mechanical grammar drills for accuracy before any real use","Using real-life tasks such as asking for directions","Plenty of pair and group work for genuine interaction among learners"],"answer":1,"explanation":"The communicative approach puts meaningful use first, through real tasks, interaction and fluency. Mechanical drilling for accuracy before use belongs to the structural or audio-lingual methods.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"निम्नलिखित में से कौन-सी भाषा शिक्षण के संप्रेषणात्मक उपागम की विशेषता नहीं है?","optionsHi":["पूर्ण शुद्धता की तुलना में अर्थ और प्रवाह पर ध्यान","किसी वास्तविक उपयोग से पहले शुद्धता के लिए यांत्रिक व्याकरण-अभ्यास","रास्ता पूछने जैसे वास्तविक जीवन के कार्यों का उपयोग","अधिगमकर्ताओं के बीच वास्तविक अंतःक्रिया के लिए प्रचुर जोड़ी और समूह कार्य"],"explanationHi":"संप्रेषणात्मक उपागम वास्तविक कार्यों, अंतःक्रिया और प्रवाह के माध्यम से अर्थपूर्ण उपयोग को प्राथमिकता देता है। उपयोग से पहले शुद्धता के लिए यांत्रिक अभ्यास संरचनात्मक या श्रव्य-भाषिक विधियों का अंग है।"},
  {"id":"cdp-pedagogy-subjects-32","question":"While counting six marbles, a child says 'one, two, three, four, five, six, seven' in the correct order but touches one marble twice. Which counting principle has the child not yet mastered?","options":["One-to-one correspondence","Cardinality principle","Stable-order principle","Order-irrelevance principle"],"answer":0,"explanation":"Each object must get exactly one number word (one-to-one correspondence), and touching a marble twice breaks this. The number words came in the right order, so the stable-order principle is intact.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"छह कंचे गिनते समय एक बच्चा सही क्रम में ‘एक, दो, तीन, चार, पाँच, छह, सात’ बोलता है, लेकिन एक कंचे को दो बार छू लेता है। बच्चे ने गिनती के किस सिद्धांत में अभी दक्षता प्राप्त नहीं की है?","optionsHi":["एक-से-एक संगतता","गणनांक (कार्डिनैलिटी) का सिद्धांत","स्थिर क्रम का सिद्धांत","क्रम की अप्रासंगिकता का सिद्धांत"],"explanationHi":"हर वस्तु को ठीक एक संख्या-नाम मिलना चाहिए (एक-से-एक संगतता), और किसी कंचे को दो बार छूने से यह टूट जाता है। संख्या-नाम सही क्रम में आए, इसलिए स्थिर क्रम का सिद्धांत अक्षुण्ण है।"},
  {"id":"cdp-pedagogy-subjects-33","question":"After correctly counting seven pencils, a child is asked 'So how many pencils are there?' and starts counting all over again instead of answering 'seven'. The child has not yet grasped the principle of:","options":["cardinality","abstraction","one-to-one correspondence","stable order"],"answer":0,"explanation":"Cardinality means the last number word said gives the size of the whole set. A child who recounts has not linked 'seven' to the total, even though the counting itself was correct.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"सात पेंसिलों को सही गिनने के बाद एक बच्चे से पूछा जाता है, ‘तो कुल कितनी पेंसिलें हैं?’ और वह ‘सात’ कहने के बजाय फिर से शुरू से गिनने लगता है। बच्चे ने किस सिद्धांत को अभी नहीं समझा है?","optionsHi":["गणनांक (कार्डिनैलिटी)","अमूर्तीकरण","एक-से-एक संगतता","स्थिर क्रम"],"explanationHi":"गणनांक का अर्थ है कि अंतिम बोला गया संख्या-नाम पूरे समुच्चय का आकार बताता है। जो बच्चा दोबारा गिनता है, उसने ‘सात’ को कुल संख्या से नहीं जोड़ा है, भले ही गिनती स्वयं सही थी।"},
  {"id":"cdp-pedagogy-subjects-34","question":"Phonemic awareness is best shown when a child can:","options":["copy words neatly and correctly from the board","say that 'cat' without its first sound /k/ becomes 'at'","name the letter C when it is shown on a card","read a short printed sentence aloud fluently and clearly"],"answer":1,"explanation":"Phonemic awareness is the ability to hear and handle individual sounds in spoken words, e.g. taking away the first sound. Naming letters is letter knowledge, and fluent reading is a later skill.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"ध्वनि-स्वनिम जागरूकता (फ़ोनेमिक अवेयरनेस) सबसे अच्छे ढंग से तब प्रदर्शित होती है जब बच्चा:","optionsHi":["श्यामपट्ट से शब्दों को साफ़ और सही-सही नकल कर सके","यह बता सके कि ‘cat’ से पहली ध्वनि /k/ हटा देने पर ‘at’ बनता है","कार्ड पर दिखाने पर अक्षर C का नाम बता सके","एक छोटे मुद्रित वाक्य को ज़ोर से धाराप्रवाह और स्पष्ट पढ़ सके"],"explanationHi":"फ़ोनेमिक अवेयरनेस बोले गए शब्दों की अलग-अलग ध्वनियों को सुनने और उनमें हेरफेर करने की क्षमता है, जैसे पहली ध्वनि हटाना। अक्षरों के नाम बताना अक्षर-ज्ञान है, और धाराप्रवाह पढ़ना बाद का कौशल है।"},
  {"id":"cdp-pedagogy-subjects-35","question":"Which question best assesses a Class V child's conceptual understanding of fractions rather than procedural skill?","options":["Without calculating, explain why 3/4 is greater than 3/5","Convert 3/4 into a decimal and then into a percentage","Add 3/4 and 3/5 and write the answer in lowest terms","Find the LCM of 4 and 5 and use it to compare 3/4 and 3/5"],"answer":0,"explanation":"Explaining that the same number of larger parts (quarters are bigger than fifths) makes a larger fraction needs understanding. The other tasks can be done by following a learned procedure.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कौन-सा प्रश्न कक्षा V के बच्चे की प्रक्रियात्मक कुशलता के बजाय भिन्नों की अवधारणात्मक समझ का सबसे अच्छा आकलन करता है?","optionsHi":["गणना किए बिना समझाइए कि 3/4, 3/5 से बड़ा क्यों है","3/4 को दशमलव में और फिर प्रतिशत में बदलिए","3/4 और 3/5 को जोड़िए और उत्तर को सरलतम रूप में लिखिए","4 और 5 का LCM ज्ञात कीजिए और उसकी सहायता से 3/4 और 3/5 की तुलना कीजिए"],"explanationHi":"यह समझाने के लिए कि बड़े भागों की समान संख्या (चौथाई पाँचवें भाग से बड़ा होता है) बड़ी भिन्न बनाती है, समझ की आवश्यकता होती है। अन्य कार्य सीखी हुई प्रक्रिया का पालन करके किए जा सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-36","question":"An EVS chapter for Class IV asks children: 'Who cooks food in your family? Who fetches water? Why?' The main purpose of such questions is to:","options":["test children's memory of the names and ages of family members","teach children recipes and household skills such as cooking","help children reflect on gender roles and division of work at home","collect data on household chores for the school's records"],"answer":2,"explanation":"Primary EVS uses open questions from the child's own life to raise social issues such as gender, work and equity, so children think critically about everyday roles.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कक्षा IV का एक EVS अध्याय बच्चों से पूछता है: ‘आपके परिवार में खाना कौन पकाता है? पानी कौन लाता है? क्यों?’ ऐसे प्रश्नों का मुख्य उद्देश्य है:","optionsHi":["परिवार के सदस्यों के नाम और उम्र की बच्चों की स्मृति की जाँच करना","बच्चों को खाना पकाने जैसी विधियाँ और घरेलू कौशल सिखाना","बच्चों को घर में लैंगिक भूमिकाओं और कार्य-विभाजन पर चिंतन करने में मदद करना","विद्यालय के अभिलेख के लिए घरेलू कामों का आँकड़ा एकत्र करना"],"explanationHi":"प्राथमिक EVS बच्चे के अपने जीवन से जुड़े खुले प्रश्नों का उपयोग लिंग, कार्य और समानता जैसे सामाजिक मुद्दे उठाने के लिए करता है, ताकि बच्चे रोज़मर्रा की भूमिकाओं के बारे में आलोचनात्मक ढंग से सोचें।"},
  {"id":"cdp-pedagogy-subjects-37","question":"How many of the following statements about NEP 2020 are correct? I. It gives the highest priority to achieving universal foundational literacy and numeracy in primary school by 2030. II. The NIPUN Bharat mission was launched to work towards foundational literacy and numeracy goals. III. It keeps the three-language formula but adds flexibility, saying no language will be imposed on any state. IV. It makes English the compulsory medium of instruction from Grade 1.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"II and III are correct (NIPUN Bharat was launched in 2021 to pursue FLN). I is wrong: NEP 2020 sets 2025 as the target for universal FLN. IV is wrong: NEP prefers the mother tongue or regional language as the early medium of instruction.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"NEP 2020 के बारे में निम्नलिखित में से कितने कथन सही हैं? I. यह 2030 तक प्राथमिक विद्यालय में सार्वभौमिक आधारभूत साक्षरता और संख्या-ज्ञान प्राप्त करने को सर्वोच्च प्राथमिकता देती है। II. आधारभूत साक्षरता और संख्या-ज्ञान के लक्ष्यों की दिशा में कार्य करने के लिए निपुण भारत मिशन शुरू किया गया था। III. यह त्रि-भाषा सूत्र को बनाए रखती है लेकिन लचीलापन जोड़ती है, और कहती है कि किसी भी राज्य पर कोई भाषा थोपी नहीं जाएगी। IV. यह कक्षा 1 से अंग्रेज़ी को शिक्षा का अनिवार्य माध्यम बनाती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"II और III सही हैं (निपुण भारत 2021 में FLN को आगे बढ़ाने के लिए शुरू किया गया था)। I गलत है: NEP 2020 सार्वभौमिक FLN के लिए 2025 का लक्ष्य रखती है। IV गलत है: NEP प्रारंभिक माध्यम के रूप में मातृभाषा या क्षेत्रीय भाषा को प्राथमिकता देती है।"},
  {"id":"cdp-pedagogy-subjects-38","question":"How many of the following statements about teaching reading and writing in the primary grades are correct? I. The aim of reading instruction is reading with comprehension, not just decoding. II. Using children's literature in class supports language development. III. A print-rich classroom environment supports emergent literacy. IV. A child's home language is a resource for learning the school language.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four reflect current language pedagogy (NCF 2005, NCF-FS 2022 and NEP 2020). Reading is meaning-making, children's literature and print-rich classrooms support literacy, and the home language is a bridge, not a barrier.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"प्राथमिक कक्षाओं में पढ़ना और लिखना सिखाने के बारे में निम्नलिखित में से कितने कथन सही हैं? I. पठन-शिक्षण का उद्देश्य केवल डिकोडिंग नहीं, बल्कि बोध सहित पढ़ना है। II. कक्षा में बाल-साहित्य का उपयोग भाषा विकास में सहायक होता है। III. मुद्रित सामग्री से समृद्ध कक्षा-वातावरण उदीयमान साक्षरता में सहायक होता है। IV. बच्चे की घरेलू भाषा विद्यालयी भाषा सीखने का एक संसाधन है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों कथन वर्तमान भाषा शिक्षाशास्त्र (NCF 2005, NCF-FS 2022 और NEP 2020) को दर्शाते हैं। पठन अर्थ-निर्माण है, बाल-साहित्य और मुद्रित सामग्री से समृद्ध कक्षाएँ साक्षरता में सहायक हैं, और घरेलू भाषा एक सेतु है, बाधा नहीं।"},
  {"id":"cdp-pedagogy-subjects-39","question":"Which sequence is most appropriate for teaching the measurement of length in the primary classes?","options":["The need for a standard unit, then using a ruler, then direct comparison, then non-standard units","Non-standard units, then using a ruler, then direct comparison, then the need for a standard unit","Direct comparison, then non-standard units, then the need for a standard unit, then using a ruler","Using a ruler, then non-standard units, then direct comparison, then the need for a standard unit"],"answer":2,"explanation":"Children first compare lengths directly (longer or shorter), then measure with body or object units. They see that different hand spans give different answers, which creates the need for a standard unit, and only then use the ruler.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"प्राथमिक कक्षाओं में लंबाई के मापन को सिखाने के लिए कौन-सा क्रम सबसे उपयुक्त है?","optionsHi":["मानक इकाई की आवश्यकता, फिर पैमाने का उपयोग, फिर प्रत्यक्ष तुलना, फिर अमानक इकाइयाँ","अमानक इकाइयाँ, फिर पैमाने का उपयोग, फिर प्रत्यक्ष तुलना, फिर मानक इकाई की आवश्यकता","प्रत्यक्ष तुलना, फिर अमानक इकाइयाँ, फिर मानक इकाई की आवश्यकता, फिर पैमाने का उपयोग","पैमाने का उपयोग, फिर अमानक इकाइयाँ, फिर प्रत्यक्ष तुलना, फिर मानक इकाई की आवश्यकता"],"explanationHi":"बच्चे पहले लंबाइयों की सीधी तुलना करते हैं (अधिक लंबा या छोटा), फिर शरीर या वस्तुओं की इकाइयों से मापते हैं। वे देखते हैं कि अलग-अलग बित्तों से अलग-अलग उत्तर आते हैं, जिससे मानक इकाई की आवश्यकता पैदा होती है, और उसके बाद ही पैमाने का उपयोग करते हैं।"},
  {"id":"cdp-pedagogy-subjects-40","question":"Which of the following is NOT one of the five guiding principles of NCF 2005?","options":["Making board examinations compulsory at the end of Class VIII","Making examinations more flexible and integrated with classroom life","Moving learning away from rote methods","Connecting knowledge to life outside the school"],"answer":0,"explanation":"The five guiding principles are: connecting knowledge to life outside school, moving away from rote learning, enriching the curriculum beyond textbooks, making examinations flexible and integrated with classroom life, and nurturing an overriding identity informed by caring concerns within the democratic polity. A Class VIII board exam is not one of them.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"निम्नलिखित में से कौन-सा NCF 2005 के पाँच मार्गदर्शक सिद्धांतों में से एक नहीं है?","optionsHi":["कक्षा VIII के अंत में बोर्ड परीक्षाओं को अनिवार्य बनाना","परीक्षाओं को अधिक लचीला बनाना और कक्षा के जीवन से जोड़ना","अधिगम को रटने की विधियों से दूर ले जाना","ज्ञान को विद्यालय के बाहर के जीवन से जोड़ना"],"explanationHi":"पाँच मार्गदर्शक सिद्धांत हैं: ज्ञान को विद्यालय के बाहर के जीवन से जोड़ना, रटने की प्रवृत्ति से दूर जाना, पाठ्यचर्या को पाठ्यपुस्तकों से आगे समृद्ध बनाना, परीक्षाओं को लचीला बनाना और कक्षा के जीवन से जोड़ना, तथा लोकतांत्रिक राजनीतिक व्यवस्था के भीतर देखभाल की चिंताओं से सूचित एक सर्वोपरि पहचान का पोषण करना। कक्षा VIII की बोर्ड परीक्षा उनमें से नहीं है।"},
  {"id":"cdp-pedagogy-subjects-41","question":"The NCERT textbooks for Environmental Studies (Classes III to V) are titled:","options":["Looking Around","Rimjhim","Math-Magic","Marigold"],"answer":0,"explanation":"“Looking Around” is the NCERT EVS series. Rimjhim is the Hindi reader, Math-Magic the mathematics series and Marigold the English reader for the primary classes.","difficulty":"easy","source":"CTET · State TETs","questionHi":"पर्यावरण अध्ययन (कक्षा III से V) की NCERT पाठ्यपुस्तकों का नाम है:","optionsHi":["Looking Around","Rimjhim","Math-Magic","Marigold"],"explanationHi":"“Looking Around” NCERT की EVS शृंखला है। रिमझिम हिंदी की पाठ्यपुस्तक है, Math-Magic गणित की शृंखला है और Marigold प्राथमिक कक्षाओं की अंग्रेज़ी की पाठ्यपुस्तक है।"},
  {"id":"cdp-pedagogy-subjects-42","question":"A specific learning disability that mainly affects understanding numbers and doing calculations is called:","options":["Dyslexia","Dysgraphia","Dyscalculia","Dyspraxia"],"answer":2,"explanation":"Dyscalculia affects number sense and calculation. Dyslexia affects reading, dysgraphia writing, and dyspraxia motor coordination.","difficulty":"easy","source":"CTET · State TETs","questionHi":"वह विशिष्ट अधिगम अक्षमता, जो मुख्य रूप से संख्याओं को समझने और गणना करने को प्रभावित करती है, कहलाती है:","optionsHi":["डिस्लेक्सिया","डिस्ग्राफ़िया","डिस्कैल्कुलिया","डिस्प्रैक्सिया"],"explanationHi":"डिस्कैल्कुलिया संख्या-बोध और गणना को प्रभावित करती है। डिस्लेक्सिया पढ़ने को, डिस्ग्राफ़िया लिखने को और डिस्प्रैक्सिया गामक समन्वय को प्रभावित करती है।"},
  {"id":"cdp-pedagogy-subjects-43","question":"Which is the most suitable way to begin addition with Class I children?","options":["Memorising addition tables up to 10 by recitation","Writing long columns of sums on the board to copy","Practising abstract symbols such as 3 + 2 = 5","Joining and counting real objects such as pebbles"],"answer":3,"explanation":"Young children are at a concrete stage; joining real collections and counting gives meaning to “adding” before symbols are introduced.","difficulty":"easy","source":"CTET · State TETs","questionHi":"कक्षा I के बच्चों के साथ जोड़ शुरू करने का सबसे उपयुक्त तरीका कौन-सा है?","optionsHi":["दोहराकर 10 तक के जोड़ के पहाड़े याद करना","नकल करने के लिए श्यामपट्ट पर जोड़ के लंबे स्तंभ लिखना","3 + 2 = 5 जैसे अमूर्त प्रतीकों का अभ्यास करना","कंकड़ जैसी वास्तविक वस्तुओं को जोड़ना और गिनना"],"explanationHi":"छोटे बच्चे मूर्त अवस्था में होते हैं; वास्तविक वस्तुओं के समूहों को जोड़ने और गिनने से प्रतीकों के परिचय से पहले ही “जोड़ने” को अर्थ मिलता है।"},
  {"id":"cdp-pedagogy-subjects-44","question":"A Class III child writes 52 − 27 = 35. What is the most likely reason for this error?","options":["Carelessness while copying the numbers from the board into the notebook","Subtracting the smaller digit from the larger in each column","Not yet knowing the basic subtraction facts up to 10","Adding the two numbers instead of subtracting them"],"answer":1,"explanation":"In the ones place the child did 7 − 2 = 5 instead of regrouping, then 5 − 2 = 3. This systematic “smaller-from-larger” error shows a gap in understanding place value and borrowing.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा III का एक बच्चा 52 − 27 = 35 लिखता है। इस त्रुटि का सबसे संभावित कारण क्या है?","optionsHi":["श्यामपट्ट से संख्याएँ कॉपी में उतारते समय लापरवाही","हर स्तंभ में छोटे अंक को बड़े अंक से घटाना","10 तक के घटाव के मूल तथ्य अभी न जानना","दोनों संख्याओं को घटाने के बजाय जोड़ देना"],"explanationHi":"इकाई के स्थान पर बच्चे ने पुनर्समूहन करने के बजाय 7 − 2 = 5 किया, फिर 5 − 2 = 3। यह व्यवस्थित “छोटे को बड़े से घटाने” की त्रुटि स्थानीय मान और उधार लेने की समझ में कमी दर्शाती है।"},
  {"id":"cdp-pedagogy-subjects-45","question":"A teacher shows children many triangles, has them measure the angles, and helps them conclude that the angles of a triangle add up to 180°. This is the:","options":["Deductive method","Lecture method","Inductive method","Analytic method"],"answer":2,"explanation":"The inductive method moves from specific examples to a general rule, which suits young learners. The deductive method starts with the rule and then applies it.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"एक शिक्षक बच्चों को कई त्रिभुज दिखाता है, उनसे कोण मापवाता है और उन्हें इस निष्कर्ष तक पहुँचने में मदद करता है कि त्रिभुज के कोणों का योग 180° होता है। यह है:","optionsHi":["निगमन विधि","व्याख्यान विधि","आगमन विधि","विश्लेषण विधि"],"explanationHi":"आगमन विधि विशिष्ट उदाहरणों से सामान्य नियम की ओर बढ़ती है, जो छोटे अधिगमकर्ताओं के लिए उपयुक्त है। निगमन विधि नियम से शुरू करके फिर उसे लागू करती है।"},
  {"id":"cdp-pedagogy-subjects-46","question":"Which of these is NOT one of the six themes around which the NCERT EVS books for Classes III–V are organised?","options":["Water","Travel","Things We Make and Do","Our Solar System"],"answer":3,"explanation":"The six themes are Family and Friends, Food, Shelter, Water, Travel, and Things We Make and Do. The books deliberately avoid organising content by disciplines such as astronomy.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"इनमें से कौन-सी उन छह थीम में से एक नहीं है, जिनके आधार पर कक्षा III–V की NCERT EVS पुस्तकें संगठित हैं?","optionsHi":["जल","यात्रा","हम क्या बनाते और करते हैं","हमारा सौरमंडल"],"explanationHi":"छह थीम हैं: परिवार और मित्र, भोजन, आवास, जल, यात्रा, और हम क्या बनाते और करते हैं। पुस्तकें जानबूझकर खगोल विज्ञान जैसे विषयों के आधार पर सामग्री को संगठित करने से बचती हैं।"},
  {"id":"cdp-pedagogy-subjects-47","question":"In the 5E model of inquiry-based teaching used in science and EVS, the phases occur in which order?","options":["Engage, Explore, Explain, Elaborate, Evaluate","Explain, Engage, Explore, Evaluate, Elaborate","Explore, Engage, Explain, Evaluate, Elaborate","Engage, Explain, Explore, Elaborate, Evaluate"],"answer":0,"explanation":"Children are first engaged by a question, then explore, then explain what they found, elaborate by applying it, and finally evaluate their understanding.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"विज्ञान और EVS में उपयोग किए जाने वाले अन्वेषण-आधारित शिक्षण के 5E मॉडल में चरण किस क्रम में आते हैं?","optionsHi":["Engage, Explore, Explain, Elaborate, Evaluate","Explain, Engage, Explore, Evaluate, Elaborate","Explore, Engage, Explain, Evaluate, Elaborate","Engage, Explain, Explore, Elaborate, Evaluate"],"explanationHi":"बच्चे पहले किसी प्रश्न से जुड़ते हैं (Engage), फिर खोजबीन करते हैं (Explore), फिर जो पाया उसे समझाते हैं (Explain), उसे लागू करके विस्तार देते हैं (Elaborate), और अंत में अपनी समझ का मूल्यांकन करते हैं (Evaluate)।"},
  {"id":"cdp-pedagogy-subjects-48","question":"The project method of teaching, built on Dewey's ideas of learning by doing, was developed by:","options":["Maria Montessori","W. H. Kilpatrick","H. E. Armstrong","Friedrich Froebel"],"answer":1,"explanation":"William Heard Kilpatrick proposed the project method (1918). Armstrong is linked with the heuristic method and Froebel with the kindergarten.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"डेवी के करके सीखने के विचारों पर आधारित शिक्षण की प्रोजेक्ट (परियोजना) विधि किसने विकसित की?","optionsHi":["मारिया मॉन्टेसरी","डब्ल्यू. एच. किलपैट्रिक","एच. ई. आर्मस्ट्रांग","फ्रेडरिक फ्रोबेल"],"explanationHi":"विलियम हेयर्ड किलपैट्रिक ने प्रोजेक्ट विधि (1918) प्रस्तावित की। आर्मस्ट्रांग हूरिस्टिक (ह्यूरिस्टिक) विधि से और फ्रोबेल किंडरगार्टन से जुड़े हैं।"},
  {"id":"cdp-pedagogy-subjects-49","question":"Richard Skemp distinguished “relational understanding” from “instrumental understanding”. Relational understanding means:","options":["Knowing a rule and how to apply it quickly","Knowing both what to do and why it works","Memorising formulae through repeated practice","Relating mathematics only to daily life examples"],"answer":1,"explanation":"Instrumental understanding is “rules without reasons”; relational understanding connects procedures to the underlying concepts, so it transfers better to new problems.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"रिचर्ड स्केम्प ने “संबंधात्मक समझ” को “साधनात्मक समझ” से अलग बताया। संबंधात्मक समझ का अर्थ है:","optionsHi":["कोई नियम जानना और उसे शीघ्रता से लागू करना","यह दोनों जानना कि क्या करना है और वह क्यों काम करता है","बार-बार अभ्यास से सूत्रों को याद करना","गणित को केवल दैनिक जीवन के उदाहरणों से जोड़ना"],"explanationHi":"साधनात्मक समझ “बिना कारण के नियम” है; संबंधात्मक समझ प्रक्रियाओं को अंतर्निहित अवधारणाओं से जोड़ती है, इसलिए वह नई समस्याओं में बेहतर ढंग से स्थानांतरित होती है।"},
  {"id":"cdp-pedagogy-subjects-50","question":"To study the theme “Water” in Class IV, which activity best fits the approach of NCF 2005?","options":["Copying the definition of the water cycle five times for practice","Reading the chapter aloud and answering the textbook questions","Surveying local water sources and discussing who fetches water","Memorising the names of major rivers of India and the world"],"answer":2,"explanation":"A local survey links the theme to children's own lives, involves observation and recording, and raises issues of access and equity, as NCF 2005 recommends.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा IV में “जल” थीम का अध्ययन कराने के लिए NCF 2005 के दृष्टिकोण के अनुरूप कौन-सी गतिविधि सबसे उपयुक्त है?","optionsHi":["अभ्यास के लिए जल-चक्र की परिभाषा पाँच बार उतारना","अध्याय को ज़ोर से पढ़ना और पाठ्यपुस्तक के प्रश्नों के उत्तर देना","स्थानीय जल-स्रोतों का सर्वेक्षण करना और इस पर चर्चा करना कि पानी कौन लाता है","भारत और विश्व की प्रमुख नदियों के नाम याद करना"],"explanationHi":"स्थानीय सर्वेक्षण थीम को बच्चों के अपने जीवन से जोड़ता है, उसमें अवलोकन और अभिलेखन शामिल है, और NCF 2005 की अनुशंसा के अनुसार पहुँच और समानता के मुद्दे उठाता है।"},
  {"id":"cdp-pedagogy-subjects-51","question":"Zoltan Dienes's “perceptual variability” (multiple embodiment) principle means that a mathematical concept should be:","options":["Taught through one well-chosen model so children are not confused","Presented through several different materials and situations","Introduced first as a formal definition, then illustrated","Practised with one material until answers become automatic"],"answer":1,"explanation":"Meeting the same idea, such as place value, in sticks, beads and blocks helps children abstract what is common and not tie the concept to one material.","difficulty":"hard","source":"CTET · State TETs","questionHi":"ज़ोल्टन डीन्स का “अवबोधात्मक विविधता” (बहु-निरूपण) सिद्धांत बताता है कि किसी गणितीय अवधारणा को:","optionsHi":["एक भली-भाँति चुने गए मॉडल से पढ़ाना चाहिए ताकि बच्चे भ्रमित न हों","कई अलग-अलग सामग्रियों और स्थितियों के माध्यम से प्रस्तुत करना चाहिए","पहले औपचारिक परिभाषा के रूप में प्रस्तुत करना चाहिए, फिर उदाहरण देना चाहिए","एक ही सामग्री से तब तक अभ्यास कराना चाहिए जब तक उत्तर स्वचालित न हो जाएँ"],"explanationHi":"एक ही विचार, जैसे स्थानीय मान, को तीलियों, मनकों और ब्लॉकों में देखने से बच्चों को जो समान है उसका अमूर्तीकरण करने में मदद मिलती है और अवधारणा किसी एक सामग्री से बँधी नहीं रहती।"},
  {"id":"cdp-pedagogy-subjects-52","question":"Many children think that multiplying always gives a bigger number, so they are puzzled that 1/2 × 1/4 = 1/8. The best teaching response is to:","options":["Tell them the rule and ask them to memorise it for the test","Use area models to show that a part of a part is smaller","Avoid fraction multiplication until they reach Class VIII","Give a large number of similar sums for drill and practice"],"answer":1,"explanation":"The belief comes from experience with whole numbers. An area or paper-folding model shows that “half of a quarter” is smaller than both, correcting the misconception through meaning.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कई बच्चे सोचते हैं कि गुणा करने पर हमेशा बड़ी संख्या मिलती है, इसलिए वे इस बात से हैरान होते हैं कि 1/2 × 1/4 = 1/8। सबसे अच्छी शिक्षण-प्रतिक्रिया है:","optionsHi":["उन्हें नियम बता देना और परीक्षा के लिए याद करने को कहना","क्षेत्रफल मॉडल का उपयोग करके दिखाना कि भाग का भाग छोटा होता है","कक्षा VIII तक पहुँचने तक भिन्नों का गुणा न कराना","अभ्यास के लिए बड़ी संख्या में एक जैसे प्रश्न देना"],"explanationHi":"यह धारणा पूर्ण संख्याओं के अनुभव से आती है। क्षेत्रफल या कागज़ मोड़ने का मॉडल दिखाता है कि “चौथाई का आधा” दोनों से छोटा होता है, और इस प्रकार अर्थ के माध्यम से भ्रांत धारणा को ठीक करता है।"},
  {"id":"cdp-pedagogy-subjects-53","question":"A child correctly lists the properties of a square (four equal sides, four right angles) but insists that a square is not a rectangle. According to Van Hiele, the child is at the level of:","options":["Visualisation","Analysis","Informal deduction","Rigour"],"answer":1,"explanation":"At the analysis level children describe shapes by their properties but do not yet see relationships between classes of shapes, which comes at informal deduction.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक बच्चा वर्ग के गुणों (चार समान भुजाएँ, चार समकोण) को सही गिनाता है, लेकिन ज़ोर देकर कहता है कि वर्ग आयत नहीं है। वान हील के अनुसार, बच्चा किस स्तर पर है?","optionsHi":["दृश्यीकरण","विश्लेषण","अनौपचारिक निगमन","कठोरता (रिगर)"],"explanationHi":"विश्लेषण स्तर पर बच्चे आकृतियों का वर्णन उनके गुणों से करते हैं, लेकिन आकृतियों के वर्गों के बीच संबंध नहीं देख पाते, जो अनौपचारिक निगमन के स्तर पर आता है।"},
  {"id":"cdp-pedagogy-subjects-54","question":"The heuristic method, in which the learner is put in the position of a discoverer, was advocated by:","options":["H. E. Armstrong","W. H. Kilpatrick","J. S. Bruner","B. F. Skinner"],"answer":0,"explanation":"Henry Edward Armstrong promoted the heuristic method in science teaching. Bruner is linked with discovery learning more generally and Skinner with programmed instruction.","difficulty":"hard","source":"CTET · State TETs","questionHi":"हूरिस्टिक (ह्यूरिस्टिक) विधि, जिसमें अधिगमकर्ता को खोजकर्ता की स्थिति में रखा जाता है, का समर्थन किसने किया?","optionsHi":["एच. ई. आर्मस्ट्रांग","डब्ल्यू. एच. किलपैट्रिक","जे. एस. ब्रूनर","बी. एफ़. स्किनर"],"explanationHi":"हेनरी एडवर्ड आर्मस्ट्रांग ने विज्ञान शिक्षण में हूरिस्टिक विधि को बढ़ावा दिया। ब्रूनर सामान्यतः खोज द्वारा अधिगम से और स्किनर क्रमादेशित अनुदेशन से जुड़े हैं।"},
  {"id":"cdp-pedagogy-subjects-55","question":"Concept maps, used in EVS and science to show how ideas are linked, were developed by:","options":["Jean Piaget","Joseph Novak","Howard Gardner","Benjamin Bloom"],"answer":1,"explanation":"Joseph Novak developed concept mapping in the 1970s, building on Ausubel's idea that meaningful learning links new ideas to existing knowledge.","difficulty":"hard","source":"CTET · State TETs","questionHi":"EVS और विज्ञान में विचारों के आपसी जुड़ाव को दिखाने के लिए उपयोग किए जाने वाले संप्रत्यय मानचित्र (कॉन्सेप्ट मैप) किसने विकसित किए?","optionsHi":["जीन पियाजे","जोसेफ़ नोवाक","हॉवर्ड गार्डनर","बेंजामिन ब्लूम"],"explanationHi":"जोसेफ़ नोवाक ने 1970 के दशक में संप्रत्यय मानचित्रण विकसित किया, जो ऑसुबेल के इस विचार पर आधारित था कि सार्थक अधिगम नए विचारों को पहले से मौजूद ज्ञान से जोड़ता है।"},
  {"id":"cdp-pedagogy-subjects-56","question":"Which of these is an open-ended task in mathematics?","options":["What is 12 + 8? Show your working in the notebook.","Find as many number pairs as you can that add up to 20.","Write the multiplication table of 4 up to 4 × 10.","Copy the numbers from 1 to 50 neatly into your notebook."],"answer":1,"explanation":"An open-ended task has many correct answers and lets children use different strategies and reasoning. The other tasks have a single fixed answer.","difficulty":"hard","source":"CTET · State TETs","questionHi":"इनमें से गणित का खुला (मुक्त-उत्तर वाला) कार्य कौन-सा है?","optionsHi":["12 + 8 कितना होता है? अपना कार्य कॉपी में दिखाइए।","जितने हो सकें उतने संख्या-युग्म ढूँढ़िए जिनका योग 20 हो।","4 का पहाड़ा 4 × 10 तक लिखिए।","1 से 50 तक की संख्याएँ अपनी कॉपी में साफ़-साफ़ उतारिए।"],"explanationHi":"खुले कार्य के कई सही उत्तर होते हैं और वह बच्चों को अलग-अलग रणनीतियाँ और तर्क अपनाने देता है। अन्य कार्यों का एक ही निश्चित उत्तर होता है।"},
  {"id":"cdp-pedagogy-subjects-57","question":"NCERT's indicators for assessing learning in EVS include all of the following EXCEPT:","options":["Observation, recording and discussion","Questioning, analysis and experimentation","Concern for justice and equality","Reproducing definitions word for word"],"answer":3,"explanation":"The EVS indicators include observation and recording, discussion, expression, explanation, classification, questioning, analysis, experimentation, concern for justice and equality, and cooperation. Rote reproduction is not an indicator.","difficulty":"hard","source":"CTET · State TETs","questionHi":"EVS में अधिगम के आकलन के NCERT के संकेतकों में निम्नलिखित सभी शामिल हैं, सिवाय:","optionsHi":["अवलोकन, अभिलेखन और चर्चा","प्रश्न पूछना, विश्लेषण और प्रयोग","न्याय और समानता के प्रति सरोकार","परिभाषाओं को शब्दशः दोहराना"],"explanationHi":"EVS के संकेतकों में अवलोकन और अभिलेखन, चर्चा, अभिव्यक्ति, व्याख्या, वर्गीकरण, प्रश्न पूछना, विश्लेषण, प्रयोग, न्याय और समानता के प्रति सरोकार, तथा सहयोग शामिल हैं। रटकर दोहराना संकेतक नहीं है।"},
  {"id":"cdp-pedagogy-subjects-58","question":"In a geometry proof, working backwards from what is to be proved towards what is already known is called the:","options":["Synthetic method","Inductive method","Analytic method","Laboratory method"],"answer":2,"explanation":"The analytic method goes from the unknown to the known and helps children discover the proof. The synthetic method presents the proof from known facts to the conclusion.","difficulty":"hard","source":"CTET · State TETs","questionHi":"ज्यामिति के किसी उपपत्ति (प्रूफ़) में, जो सिद्ध करना है उससे शुरू करके पहले से ज्ञात की ओर पीछे की तरफ़ बढ़ना कहलाता है:","optionsHi":["संश्लेषण विधि","आगमन विधि","विश्लेषण विधि","प्रयोगशाला विधि"],"explanationHi":"विश्लेषण विधि अज्ञात से ज्ञात की ओर जाती है और बच्चों को उपपत्ति खोजने में मदद करती है। संश्लेषण विधि उपपत्ति को ज्ञात तथ्यों से निष्कर्ष की ओर प्रस्तुत करती है।"},
  {"id":"cdp-pedagogy-subjects-59","question":"Which is a major limitation of using the deductive method alone with young children in mathematics?","options":["It takes far too long to complete the prescribed syllabus in the year","Children may use formulae without knowing where they come from","It needs costly laboratory equipment in every classroom","It cannot be used for teaching geometry or measurement"],"answer":1,"explanation":"Starting with a ready-made rule is quick, but children may apply it mechanically. Combining it with the inductive method builds understanding first.","difficulty":"hard","source":"CTET · State TETs","questionHi":"गणित में छोटे बच्चों के साथ केवल निगमन विधि का उपयोग करने की एक प्रमुख सीमा क्या है?","optionsHi":["वर्ष में निर्धारित पाठ्यक्रम पूरा करने में बहुत अधिक समय लगता है","बच्चे सूत्रों का उपयोग यह जाने बिना कर सकते हैं कि वे कहाँ से आते हैं","इसके लिए हर कक्षा में महँगे प्रयोगशाला उपकरणों की आवश्यकता होती है","इसका उपयोग ज्यामिति या मापन पढ़ाने के लिए नहीं किया जा सकता"],"explanationHi":"बना-बनाया नियम लेकर शुरू करना तेज़ होता है, लेकिन बच्चे उसे यांत्रिक ढंग से लागू कर सकते हैं। इसे आगमन विधि के साथ मिलाने से पहले समझ का निर्माण होता है।"},
  {"id":"cdp-pedagogy-subjects-60","question":"Activities in which children extend number and shape patterns (2, 4, 6, 8, …) mainly help them to develop:","options":["Speed and accuracy in written computation","Generalisation and early algebraic thinking","Neat and correctly formed handwriting of numerals","Memory of multiplication tables and number facts"],"answer":1,"explanation":"Recognising and describing a rule behind a pattern is the root of algebraic thinking; NCF 2005 gives patterns a place from the early grades.","difficulty":"hard","source":"CTET · State TETs","questionHi":"जिन गतिविधियों में बच्चे संख्या और आकृति के पैटर्न (2, 4, 6, 8, …) को आगे बढ़ाते हैं, वे मुख्य रूप से उनमें किसके विकास में सहायक होती हैं?","optionsHi":["लिखित गणना में गति और शुद्धता","सामान्यीकरण और प्रारंभिक बीजीय चिंतन","अंकों की साफ़ और सही बनावट वाली लिखावट","पहाड़ों और संख्या-तथ्यों की स्मृति"],"explanationHi":"किसी पैटर्न के पीछे के नियम को पहचानना और बताना बीजीय चिंतन की जड़ है; NCF 2005 प्रारंभिक कक्षाओं से ही पैटर्न को स्थान देता है।"},
  {"id":"cdp-pedagogy-subjects-61","question":"Assertion (A): EVS in the primary classes should begin from the child's immediate surroundings. Reason (R): Children construct new knowledge by linking new experiences to what they already know.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A. Starting from home, family and neighbourhood gives children a base of experience to build on, in line with constructivism.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): प्राथमिक कक्षाओं में EVS की शुरुआत बच्चे के निकटतम परिवेश से होनी चाहिए। कारण (R): बच्चे नए अनुभवों को अपने पहले से ज्ञात से जोड़कर नया ज्ञान निर्मित करते हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"दोनों सत्य हैं और R, A की व्याख्या करता है। घर, परिवार और पड़ोस से शुरू करने से बच्चों को अनुभव का आधार मिलता है, जिस पर वे निर्माण कर सकें, जो रचनावाद के अनुरूप है।"},
  {"id":"cdp-pedagogy-subjects-62","question":"Consider the following statements about the NCERT EVS books for Classes III–V: 1. They follow a thematic organisation rather than separate science and social science chapters. 2. Their exercises are designed mainly for rote recall of definitions. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Only 1 is correct. The exercises ask children to observe, discuss, find out from elders and express their views, not to reproduce definitions.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"कक्षा III–V की NCERT EVS पुस्तकों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. वे अलग-अलग विज्ञान और सामाजिक विज्ञान के अध्यायों के बजाय थीम-आधारित संगठन का पालन करती हैं। 2. उनके अभ्यास मुख्य रूप से परिभाषाओं को रटकर याद करने के लिए बनाए गए हैं। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"केवल 1 सही है। अभ्यास बच्चों से अवलोकन करने, चर्चा करने, बड़ों से पता लगाने और अपने विचार व्यक्त करने को कहते हैं, परिभाषाएँ दोहराने को नहीं।"},
  {"id":"cdp-pedagogy-subjects-63","question":"Arrange these Van Hiele levels in the order in which they develop: 1. Deduction 2. Analysis 3. Rigour 4. Informal deduction","options":["2, 4, 1, 3","2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1"],"answer":0,"explanation":"After visualisation come analysis, informal deduction (abstraction), formal deduction and finally rigour.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"इन वान हील स्तरों को उस क्रम में व्यवस्थित कीजिए जिसमें वे विकसित होते हैं: 1. निगमन 2. विश्लेषण 3. कठोरता 4. अनौपचारिक निगमन","optionsHi":["2, 4, 1, 3","2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1"],"explanationHi":"दृश्यीकरण के बाद विश्लेषण, अनौपचारिक निगमन (अमूर्तीकरण), औपचारिक निगमन और अंत में कठोरता आती है।"},
  {"id":"cdp-pedagogy-subjects-64","question":"How many of these statements about the NIPUN Bharat Mission are correct? I. It was launched in 2021. II. It aims for every child to achieve foundational literacy and numeracy by the end of Grade 3. III. Its target year is 2026–27. IV. It covers children in the age group of 3 to 9 years.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. NIPUN Bharat implements the NEP 2020 priority on foundational literacy and numeracy.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"निपुण भारत मिशन के बारे में इनमें से कितने कथन सही हैं? I. इसे 2021 में शुरू किया गया था। II. इसका लक्ष्य है कि कक्षा 3 के अंत तक हर बच्चा आधारभूत साक्षरता और संख्या-ज्ञान प्राप्त कर ले। III. इसका लक्ष्य वर्ष 2026–27 है। IV. यह 3 से 9 वर्ष आयु-वर्ग के बच्चों को शामिल करता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। निपुण भारत आधारभूत साक्षरता और संख्या-ज्ञान पर NEP 2020 की प्राथमिकता को लागू करता है।"},
  {"id":"cdp-pedagogy-subjects-65","question":"Consider the following statements: 1. Vidya Pravesh is a three-month, play-based school preparation module for children entering Grade 1. 2. It was launched as part of implementing NEP 2020. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. Vidya Pravesh eases the move to school through play, stories and activities before formal instruction.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. विद्या प्रवेश कक्षा 1 में प्रवेश करने वाले बच्चों के लिए तीन महीने का खेल-आधारित विद्यालय-पूर्व तैयारी मॉड्यूल है। 2. इसे NEP 2020 को लागू करने के भाग के रूप में शुरू किया गया था। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। विद्या प्रवेश औपचारिक अनुदेशन से पहले खेल, कहानियों और गतिविधियों के माध्यम से विद्यालय में प्रवेश को आसान बनाता है।"},
  {"id":"cdp-pedagogy-subjects-66","question":"Assertion (A): Children should be allowed to use their own informal strategies for addition before the standard algorithm is taught. Reason (R): Standard algorithms are always inefficient and should be avoided.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true: invented strategies build number sense and make the algorithm meaningful later. R is false: standard algorithms are efficient tools once understood.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): मानक एल्गोरिदम सिखाए जाने से पहले बच्चों को जोड़ के लिए अपनी अनौपचारिक रणनीतियाँ अपनाने की अनुमति दी जानी चाहिए। कारण (R): मानक एल्गोरिदम हमेशा अकुशल होते हैं और उनसे बचना चाहिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"A सत्य है: स्वयं गढ़ी रणनीतियाँ संख्या-बोध का निर्माण करती हैं और बाद में एल्गोरिदम को अर्थपूर्ण बनाती हैं। R असत्य है: मानक एल्गोरिदम समझ लेने के बाद कुशल उपकरण होते हैं।"},
  {"id":"cdp-pedagogy-subjects-67","question":"A Class V child writes 1/2 + 1/3 = 2/5. Which response best addresses the misconception?","options":["Make the child repeat the rule for finding the LCM","Use fraction strips to show why equal-sized parts are needed","Mark the answer wrong and move on to the next topic","Give twenty similar sums for homework to build speed and accuracy"],"answer":1,"explanation":"The child is treating numerators and denominators as separate whole numbers. Models show why common-sized parts (sixths) are needed, giving meaning to the procedure.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"कक्षा V का एक बच्चा 1/2 + 1/3 = 2/5 लिखता है। कौन-सी प्रतिक्रिया इस भ्रांत धारणा का सबसे अच्छा समाधान करती है?","optionsHi":["बच्चे से LCM निकालने का नियम दोहरवाना","भिन्न-पट्टियों का उपयोग करके दिखाना कि समान आकार के भाग क्यों ज़रूरी हैं","उत्तर को गलत चिह्नित करके अगले विषय पर बढ़ जाना","गति और शुद्धता बढ़ाने के लिए गृहकार्य में बीस एक जैसे प्रश्न देना"],"explanationHi":"बच्चा अंशों और हरों को अलग-अलग पूर्ण संख्याएँ मान रहा है। मॉडल दिखाते हैं कि समान आकार के भाग (छठे भाग) क्यों आवश्यक हैं, जिससे प्रक्रिया को अर्थ मिलता है।"},
  {"id":"cdp-pedagogy-subjects-68","question":"Which question in an EVS lesson on houses most encourages higher-order thinking?","options":["Name two types of houses you saw in the chapter.","What is a house made of mud called in the textbook?","Why do many houses in Rajasthan have thick walls and small windows?","Which material is used for the roofs of the houses in your textbook picture?"],"answer":2,"explanation":"Asking “why” makes children link climate and building design, which calls for reasoning and inference rather than recall.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"घरों पर आधारित EVS के पाठ में कौन-सा प्रश्न उच्च-स्तरीय चिंतन को सबसे अधिक प्रोत्साहित करता है?","optionsHi":["अध्याय में देखे गए दो प्रकार के घरों के नाम बताइए।","मिट्टी से बने घर को पाठ्यपुस्तक में क्या कहा गया है?","राजस्थान के कई घरों में मोटी दीवारें और छोटी खिड़कियाँ क्यों होती हैं?","आपकी पाठ्यपुस्तक के चित्र में घरों की छतों के लिए किस सामग्री का उपयोग हुआ है?"],"explanationHi":"“क्यों” पूछने से बच्चे जलवायु और भवन-डिज़ाइन को जोड़ते हैं, जिसके लिए स्मरण के बजाय तर्क और अनुमान की आवश्यकता होती है।"},
  {"id":"cdp-pedagogy-subjects-69","question":"Consider the following statements: 1. Formative assessment in mathematics can include observing the strategies children use during group work. 2. Summative assessment results should be used to label children as slow learners. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Only 1 is correct. Assessment is meant to improve teaching and learning; labelling children harms their confidence and is discouraged by NCF 2005.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. गणित में रचनात्मक आकलन में समूह कार्य के दौरान बच्चों द्वारा अपनाई गई रणनीतियों का अवलोकन शामिल हो सकता है। 2. योगात्मक आकलन के परिणामों का उपयोग बच्चों को मंद अधिगमकर्ता का नाम देने के लिए किया जाना चाहिए। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"केवल 1 सही है। आकलन का उद्देश्य शिक्षण और अधिगम में सुधार करना है; बच्चों पर ठप्पा लगाना उनके आत्मविश्वास को हानि पहुँचाता है और NCF 2005 में इसे हतोत्साहित किया गया है।"},
  {"id":"cdp-pedagogy-subjects-70","question":"In the grammar-translation method of teaching a language:","options":["Only the target language is used in class, and translation is banned","Learning happens through pattern drills and habit formation","Children learn mainly through real-life communicative tasks","Explicit grammar rules and translation using the mother tongue"],"answer":3,"explanation":"Grammar-translation relies on rules, vocabulary lists and translation, with little speaking practice. The direct method bans translation; audio-lingual uses drills.","difficulty":"easy","source":"CTET · State TETs","questionHi":"भाषा शिक्षण की व्याकरण-अनुवाद विधि में:","optionsHi":["कक्षा में केवल लक्ष्य भाषा का उपयोग होता है, और अनुवाद प्रतिबंधित होता है","अधिगम पैटर्न-अभ्यास और आदत-निर्माण के माध्यम से होता है","बच्चे मुख्य रूप से वास्तविक जीवन के संप्रेषणात्मक कार्यों से सीखते हैं","स्पष्ट व्याकरण-नियम और मातृभाषा के माध्यम से अनुवाद होता है"],"explanationHi":"व्याकरण-अनुवाद विधि नियमों, शब्द-सूचियों और अनुवाद पर निर्भर करती है, जिसमें बोलने का अभ्यास कम होता है। प्रत्यक्ष विधि अनुवाद को प्रतिबंधित करती है; श्रव्य-भाषिक विधि अभ्यास-कवायद का उपयोग करती है।"},
  {"id":"cdp-pedagogy-subjects-71","question":"A child who has persistent difficulty in forming letters, spacing words and writing legibly may have:","options":["Dysgraphia","Dyscalculia","Aphasia","Dyslexia"],"answer":0,"explanation":"Dysgraphia is a learning disability affecting handwriting and written expression. Dyslexia affects reading; aphasia is loss of language ability, usually after brain injury.","difficulty":"easy","source":"CTET · State TETs","questionHi":"जिस बच्चे को अक्षर बनाने, शब्दों के बीच दूरी रखने और सुपाठ्य लिखने में लगातार कठिनाई होती है, उसे यह हो सकता है:","optionsHi":["डिस्ग्राफ़िया","डिस्कैल्कुलिया","वाचाघात (अफ़ेज़िया)","डिस्लेक्सिया"],"explanationHi":"डिस्ग्राफ़िया एक अधिगम अक्षमता है जो हस्तलेखन और लिखित अभिव्यक्ति को प्रभावित करती है। डिस्लेक्सिया पढ़ने को प्रभावित करती है; वाचाघात भाषा-क्षमता का ह्रास है, जो प्रायः मस्तिष्क की चोट के बाद होता है।"},
  {"id":"cdp-pedagogy-subjects-72","question":"A teacher asks children to read a passage quickly to get its general idea before reading it closely. This reading strategy is called:","options":["Scanning","Intensive reading","Loud reading","Skimming"],"answer":3,"explanation":"Skimming is quick reading for the gist; scanning is searching for a specific detail such as a name or date.","difficulty":"easy","source":"CTET · State TETs","questionHi":"एक शिक्षक बच्चों से कहता है कि वे किसी अनुच्छेद को ध्यान से पढ़ने से पहले उसका सामान्य विचार जानने के लिए उसे तेज़ी से पढ़ें। इस पठन-रणनीति को क्या कहते हैं?","optionsHi":["स्कैनिंग (खोजपूर्वक पठन)","गहन पठन","सस्वर पठन","स्किमिंग (सरसरी पठन)"],"explanationHi":"स्किमिंग सार जानने के लिए तेज़ी से पढ़ना है; स्कैनिंग किसी विशिष्ट ब्योरे, जैसे नाम या तारीख, को खोजना है।"},
  {"id":"cdp-pedagogy-subjects-73","question":"Noam Chomsky held that children learn language easily because they are born with:","options":["A blank slate shaped wholly by reinforcement","A Language Acquisition Device","A fixed vocabulary of a few hundred words","An ability that appears only after schooling"],"answer":1,"explanation":"Chomsky argued for an innate Language Acquisition Device and a universal grammar, against Skinner's view that language is learnt only through imitation and reinforcement.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"नोम चॉम्स्की का मत था कि बच्चे भाषा आसानी से इसलिए सीख लेते हैं क्योंकि वे जन्म से ही रखते हैं:","optionsHi":["एक कोरी स्लेट, जो पूरी तरह पुनर्बलन से आकार लेती है","एक भाषा अर्जन युक्ति (लैंग्वेज एक्विज़िशन डिवाइस)","कुछ सौ शब्दों की एक निश्चित शब्दावली","एक ऐसी क्षमता जो केवल विद्यालयी शिक्षा के बाद प्रकट होती है"],"explanationHi":"चॉम्स्की ने जन्मजात भाषा अर्जन युक्ति और सार्वभौमिक व्याकरण का पक्ष लिया, जो स्किनर के इस मत के विरुद्ध था कि भाषा केवल अनुकरण और पुनर्बलन से सीखी जाती है।"},
  {"id":"cdp-pedagogy-subjects-74","question":"According to B. F. Skinner, children acquire language mainly through:","options":["An innate universal grammar","Social interaction within the zone of proximal development","Imitation and reinforcement","Biological maturation alone"],"answer":2,"explanation":"Skinner's behaviourist view (Verbal Behavior, 1957) explains language as habits shaped by reinforcement. Chomsky criticised it for not explaining children's novel sentences.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"बी. एफ़. स्किनर के अनुसार, बच्चे भाषा मुख्य रूप से किसके माध्यम से अर्जित करते हैं?","optionsHi":["जन्मजात सार्वभौमिक व्याकरण","निकटस्थ विकास के क्षेत्र में सामाजिक अंतःक्रिया","अनुकरण और पुनर्बलन","केवल जैविक परिपक्वता"],"explanationHi":"स्किनर का व्यवहारवादी मत (Verbal Behavior, 1957) भाषा को पुनर्बलन से बनी आदतों के रूप में समझाता है। चॉम्स्की ने इसकी आलोचना इस आधार पर की कि यह बच्चों के नए वाक्यों की व्याख्या नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-75","question":"A test in which children fill in words deleted at regular intervals from a passage is called a:","options":["Dictation test","Cloze test","True–false test","Matching test"],"answer":1,"explanation":"A cloze test checks comprehension and language knowledge, since filling the gaps needs understanding of the context and grammar.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"वह परीक्षण, जिसमें बच्चे किसी अनुच्छेद से नियमित अंतराल पर हटाए गए शब्दों को भरते हैं, कहलाता है:","optionsHi":["श्रुतलेख परीक्षण","क्लोज़ परीक्षण (Cloze test)","सही–गलत परीक्षण","मिलान परीक्षण"],"explanationHi":"क्लोज़ परीक्षण बोध और भाषा-ज्ञान की जाँच करता है, क्योंकि रिक्त स्थानों को भरने के लिए संदर्भ और व्याकरण की समझ आवश्यक होती है।"},
  {"id":"cdp-pedagogy-subjects-76","question":"In the process approach to writing, which sequence is correct?","options":["Editing, drafting, brainstorming, revising","Drafting, brainstorming, editing, revising","Brainstorming, editing, drafting, revising","Brainstorming, drafting, revising, editing"],"answer":3,"explanation":"Writers first generate ideas, then write a draft, revise its content and organisation, and finally edit for language and mechanics before publishing.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"लेखन के प्रक्रिया उपागम में कौन-सा क्रम सही है?","optionsHi":["संपादन, प्रारूप लेखन, विचार-मंथन, संशोधन","प्रारूप लेखन, विचार-मंथन, संपादन, संशोधन","विचार-मंथन, संपादन, प्रारूप लेखन, संशोधन","विचार-मंथन, प्रारूप लेखन, संशोधन, संपादन"],"explanationHi":"लेखक पहले विचार उत्पन्न करते हैं, फिर प्रारूप लिखते हैं, उसकी विषय-वस्तु और संगठन को संशोधित करते हैं, और प्रकाशन से पहले अंत में भाषा और यांत्रिकी के लिए संपादन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-77","question":"The phonics approach to teaching reading focuses on:","options":["Guessing unknown words from pictures and context only","Memorising whole texts and reciting them from memory","Teaching how letters relate to the sounds they stand for","Reading silently from the start to build comprehension"],"answer":2,"explanation":"Phonics teaches sound–symbol correspondence so that children can decode new words. It works best alongside meaningful reading, not in isolation.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"पठन सिखाने का ध्वनि-विज्ञान (फ़ोनिक्स) उपागम किस पर ध्यान केंद्रित करता है?","optionsHi":["केवल चित्रों और संदर्भ से अज्ञात शब्दों का अनुमान लगाना","पूरे पाठों को याद करना और स्मृति से सुनाना","यह सिखाना कि अक्षर किन ध्वनियों का प्रतिनिधित्व करते हैं","बोध विकसित करने के लिए शुरू से ही मौन पठन करना"],"explanationHi":"फ़ोनिक्स ध्वनि–प्रतीक संगति सिखाता है ताकि बच्चे नए शब्दों को डिकोड कर सकें। यह अर्थपूर्ण पठन के साथ सबसे अच्छा काम करता है, अकेले नहीं।"},
  {"id":"cdp-pedagogy-subjects-78","question":"Which is the most effective way to build the vocabulary of young learners?","options":["Meeting new words again and again in stories, songs and talk","Giving lists of words with meanings to memorise each week","Testing the spellings of new words every single day","Asking them to copy dictionary entries into a notebook"],"answer":0,"explanation":"Words are learnt best in meaningful context with repeated exposure; isolated lists are quickly forgotten.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"छोटे अधिगमकर्ताओं की शब्दावली बढ़ाने का सबसे प्रभावी तरीका कौन-सा है?","optionsHi":["कहानियों, गीतों और बातचीत में नए शब्दों से बार-बार मिलना","हर सप्ताह याद करने के लिए अर्थ सहित शब्दों की सूचियाँ देना","हर दिन नए शब्दों की वर्तनी की परीक्षा लेना","उनसे शब्दकोश की प्रविष्टियाँ कॉपी में उतारने को कहना"],"explanationHi":"शब्द सबसे अच्छी तरह अर्थपूर्ण संदर्भ में बार-बार सामना होने से सीखे जाते हैं; अलग-थलग सूचियाँ जल्दी भुला दी जाती हैं।"},
  {"id":"cdp-pedagogy-subjects-79","question":"Who held that thought and language develop from separate roots and come together at about the age of two, when thought becomes verbal and speech becomes rational?","options":["Jean Piaget","Noam Chomsky","B. F. Skinner","Lev Vygotsky"],"answer":3,"explanation":"Vygotsky (Thought and Language) described this meeting of thought and speech. Piaget saw language as reflecting thought, and Chomsky stressed innate grammar.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"किसका मत था कि चिंतन और भाषा अलग-अलग जड़ों से विकसित होते हैं और लगभग दो वर्ष की आयु में मिलते हैं, जब चिंतन शाब्दिक और वाणी तर्कसंगत हो जाती है?","optionsHi":["जीन पियाजे","नोम चॉम्स्की","बी. एफ़. स्किनर","लेव वाइगोत्स्की"],"explanationHi":"वाइगोत्स्की (Thought and Language) ने चिंतन और वाणी के इस मिलन का वर्णन किया। पियाजे भाषा को चिंतन का प्रतिबिंब मानते थे, और चॉम्स्की ने जन्मजात व्याकरण पर ज़ोर दिया।"},
  {"id":"cdp-pedagogy-subjects-80","question":"According to Krashen's affective filter hypothesis, a learner's acquisition of a second language is blocked mainly by:","options":["Too much comprehensible input given at one time","Anxiety, low motivation and low self-confidence","Learning grammar rules before learning vocabulary","Using the mother tongue at home with family"],"answer":1,"explanation":"A high affective filter keeps input from being acquired. A relaxed classroom where mistakes are accepted lowers the filter.","difficulty":"hard","source":"CTET · State TETs","questionHi":"क्रैशेन की भावात्मक छन्नी परिकल्पना (अफ़ेक्टिव फ़िल्टर हाइपोथीसिस) के अनुसार, अधिगमकर्ता के द्वितीय भाषा अर्जन में मुख्य रूप से बाधा किससे आती है?","optionsHi":["एक समय में बहुत अधिक बोधगम्य निवेश दिया जाना","चिंता, कम अभिप्रेरणा और कम आत्मविश्वास","शब्दावली सीखने से पहले व्याकरण के नियम सीखना","घर पर परिवार के साथ मातृभाषा का उपयोग करना"],"explanationHi":"ऊँची भावात्मक छन्नी निवेश को अर्जित होने से रोकती है। ऐसी शांत कक्षा, जिसमें गलतियाँ स्वीकार की जाती हैं, छन्नी को कम करती है।"},
  {"id":"cdp-pedagogy-subjects-81","question":"Consider the following statements based on Krashen's theory: 1. Acquisition is a subconscious process similar to how children pick up their first language. 2. Learning refers to conscious knowledge of the rules of a language. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. Krashen argued that fluency comes mainly from acquisition, while consciously learnt rules mostly serve as a monitor.","difficulty":"hard","source":"CTET · State TETs","questionHi":"क्रैशेन के सिद्धांत के आधार पर निम्नलिखित कथनों पर विचार कीजिए: 1. अर्जन एक अवचेतन प्रक्रिया है, जैसे बच्चे अपनी प्रथम भाषा सीख लेते हैं। 2. अधिगम का अर्थ भाषा के नियमों का सचेत ज्ञान है। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। क्रैशेन का तर्क था कि प्रवाह मुख्यतः अर्जन से आता है, जबकि सचेत रूप से सीखे गए नियम अधिकांशतः एक निगरानीकर्ता (मॉनिटर) का काम करते हैं।"},
  {"id":"cdp-pedagogy-subjects-82","question":"After a story, which question checks inferential comprehension?","options":["What was the name of the old man in the story?","Where did the old man live with his family?","How many goats did the old man have at the start?","Why do you think the old man smiled at the end?"],"answer":3,"explanation":"Inferential questions need children to read between the lines. The others are literal questions whose answers are stated in the text.","difficulty":"hard","source":"CTET · State TETs","questionHi":"किसी कहानी के बाद कौन-सा प्रश्न अनुमानात्मक बोध की जाँच करता है?","optionsHi":["कहानी में बूढ़े आदमी का नाम क्या था?","बूढ़ा आदमी अपने परिवार के साथ कहाँ रहता था?","शुरुआत में बूढ़े आदमी के पास कितनी बकरियाँ थीं?","आपको क्या लगता है कि अंत में बूढ़ा आदमी क्यों मुस्कुराया?"],"explanationHi":"अनुमानात्मक प्रश्नों में बच्चों को पंक्तियों के बीच का अर्थ पढ़ना होता है। अन्य प्रश्न शाब्दिक हैं, जिनके उत्तर पाठ में सीधे दिए गए हैं।"},
  {"id":"cdp-pedagogy-subjects-83","question":"The three-language formula was recommended by the Kothari Commission and adopted in the:","options":["National Policy on Education, 1968","National Policy on Education, 1986","Right to Education Act, 2009","National Curriculum Framework, 2005"],"answer":0,"explanation":"The Education Commission (1964–66) recommended it and the 1968 policy adopted it. NCF 2005 and NEP 2020 reaffirmed it with flexibility.","difficulty":"hard","source":"CTET · State TETs","questionHi":"त्रि-भाषा सूत्र की अनुशंसा कोठारी आयोग ने की थी और इसे किसमें अपनाया गया?","optionsHi":["राष्ट्रीय शिक्षा नीति, 1968","राष्ट्रीय शिक्षा नीति, 1986","शिक्षा का अधिकार अधिनियम, 2009","राष्ट्रीय पाठ्यचर्या की रूपरेखा, 2005"],"explanationHi":"शिक्षा आयोग (1964–66) ने इसकी अनुशंसा की और 1968 की नीति ने इसे अपनाया। NCF 2005 और NEP 2020 ने इसे लचीलेपन के साथ दोहराया।"},
  {"id":"cdp-pedagogy-subjects-84","question":"Which Article of the Constitution asks every State to provide facilities for instruction in the mother tongue at the primary stage to children of linguistic minority groups?","options":["Article 350B","Article 29","Article 21A","Article 350A"],"answer":3,"explanation":"Article 350A, added in 1956, deals with mother-tongue instruction at the primary stage. Article 350B provides a Special Officer for linguistic minorities, Article 29 protects culture and language, and Article 21A is the right to education.","difficulty":"hard","source":"CTET · State TETs","questionHi":"संविधान का कौन-सा अनुच्छेद प्रत्येक राज्य से भाषाई अल्पसंख्यक समूहों के बच्चों को प्राथमिक स्तर पर मातृभाषा में शिक्षा की सुविधाएँ उपलब्ध कराने को कहता है?","optionsHi":["अनुच्छेद 350B","अनुच्छेद 29","अनुच्छेद 21A","अनुच्छेद 350A"],"explanationHi":"1956 में जोड़ा गया अनुच्छेद 350A प्राथमिक स्तर पर मातृभाषा में शिक्षा से संबंधित है। अनुच्छेद 350B भाषाई अल्पसंख्यकों के लिए विशेष अधिकारी का प्रावधान करता है, अनुच्छेद 29 संस्कृति और भाषा की रक्षा करता है, और अनुच्छेद 21A शिक्षा का अधिकार है।"},
  {"id":"cdp-pedagogy-subjects-85","question":"A Class I teacher labels objects in the room, displays children's names, charts and posters at their eye level. The main purpose is to:","options":["Decorate the classroom so it looks attractive for inspections","Create a print-rich setting that supports early literacy","Make children copy the labels as handwriting practice","Test children's spelling of common classroom objects"],"answer":1,"explanation":"Seeing meaningful print around them helps children notice that print carries meaning and supports early reading and writing.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा I की एक शिक्षिका कमरे की वस्तुओं पर नाम-पर्चियाँ लगाती है और बच्चों की आँखों के स्तर पर उनके नाम, चार्ट और पोस्टर प्रदर्शित करती है। इसका मुख्य उद्देश्य है:","optionsHi":["निरीक्षण के लिए कक्षा को आकर्षक दिखाने हेतु सजाना","ऐसा मुद्रित-सामग्री से समृद्ध वातावरण बनाना जो प्रारंभिक साक्षरता में सहायक हो","बच्चों से हस्तलेखन अभ्यास के रूप में नाम-पर्चियाँ उतरवाना","कक्षा की सामान्य वस्तुओं की वर्तनी की जाँच करना"],"explanationHi":"अपने आसपास अर्थपूर्ण मुद्रित सामग्री देखने से बच्चों को यह समझने में मदद मिलती है कि छपे हुए का अर्थ होता है, और यह प्रारंभिक पठन और लेखन में सहायक होता है।"},
  {"id":"cdp-pedagogy-subjects-86","question":"“Big Books” in early-grade classrooms are mainly used for:","options":["Silent individual reading by each child at the desk","Shared reading, with the whole class able to see the text","Testing spellings of new words shown in large print","Copying large-print text into notebooks from a distance"],"answer":1,"explanation":"Big Books let the teacher model reading, point to words and invite predictions, so children join in reading together.","difficulty":"hard","source":"CTET · State TETs","questionHi":"प्रारंभिक कक्षाओं में “बिग बुक” का उपयोग मुख्य रूप से किसके लिए किया जाता है?","optionsHi":["हर बच्चे द्वारा अपनी मेज़ पर मौन व्यक्तिगत पठन के लिए","साझा पठन के लिए, जिसमें पूरी कक्षा पाठ को देख सके","बड़े अक्षरों में दिखाए गए नए शब्दों की वर्तनी की जाँच के लिए","दूर से बड़े अक्षरों वाले पाठ को कॉपियों में उतारने के लिए"],"explanationHi":"बिग बुक शिक्षक को पठन का आदर्श प्रस्तुत करने, शब्दों की ओर इशारा करने और अनुमान लगाने के लिए आमंत्रित करने देती हैं, जिससे बच्चे साथ मिलकर पढ़ने में शामिल होते हैं।"},
  {"id":"cdp-pedagogy-subjects-87","question":"A child often reverses letters such as b and d. Which remedial approach is most suitable?","options":["Making the child write each letter a hundred times","Scolding the child for carelessness so that the habit finally stops","Tracing letters in sand or air while saying their sounds","Moving the child to a lower class to repeat basics"],"answer":2,"explanation":"Multisensory methods link sight, sound, movement and touch, which helps children with reversal difficulties; punishment and drills do not.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक बच्चा अक्सर b और d जैसे अक्षरों को उलट देता है। कौन-सा उपचारात्मक उपागम सबसे उपयुक्त है?","optionsHi":["बच्चे से हर अक्षर सौ बार लिखवाना","बच्चे को लापरवाही के लिए डाँटना ताकि यह आदत आखिरकार रुक जाए","अक्षरों की ध्वनियाँ बोलते हुए उन्हें रेत में या हवा में बनवाना","बच्चे को मूल बातें दोहराने के लिए निचली कक्षा में भेजना"],"explanationHi":"बहु-संवेदी विधियाँ दृष्टि, ध्वनि, गति और स्पर्श को जोड़ती हैं, जिससे अक्षर उलटने की कठिनाई वाले बच्चों को मदद मिलती है; दंड और बार-बार अभ्यास से नहीं।"},
  {"id":"cdp-pedagogy-subjects-88","question":"Which task is most suitable for assessing the listening skill of Class III children?","options":["Copying a paragraph from the board into the notebook","Writing a short essay on “My School” in the notebook","Reading a passage aloud to the class with expression","Answering questions on a short announcement heard aloud"],"answer":3,"explanation":"A listening task needs a spoken input and a response that shows understanding. The other tasks assess writing or reading.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा III के बच्चों के सुनने के कौशल का आकलन करने के लिए कौन-सा कार्य सबसे उपयुक्त है?","optionsHi":["श्यामपट्ट से एक अनुच्छेद कॉपी में उतारना","कॉपी में “मेरा विद्यालय” पर एक छोटा निबंध लिखना","कक्षा के सामने भाव सहित एक अनुच्छेद ज़ोर से पढ़ना","ज़ोर से सुनाई गई एक छोटी घोषणा पर प्रश्नों के उत्तर देना"],"explanationHi":"सुनने के कार्य में बोला हुआ निवेश और ऐसी प्रतिक्रिया चाहिए जो समझ को दर्शाए। अन्य कार्य लेखन या पठन का आकलन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-89","question":"While reading a story aloud, a teacher stops and asks, “What do you think will happen next?” This mainly develops children's:","options":["Handwriting, by noting key words from the story","Prediction and active engagement with the text","Memory for the spellings of new words in the story","Speed of silent reading and word recognition"],"answer":1,"explanation":"Predicting makes children use clues from the text and their own experience, which builds active comprehension.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कहानी ज़ोर से पढ़ते समय एक शिक्षक रुककर पूछता है, “तुम्हें क्या लगता है आगे क्या होगा?” यह मुख्य रूप से बच्चों में किसका विकास करता है?","optionsHi":["हस्तलेखन, कहानी के मुख्य शब्दों को नोट करने के द्वारा","पूर्वानुमान और पाठ के साथ सक्रिय जुड़ाव","कहानी के नए शब्दों की वर्तनी की स्मृति","मौन पठन की गति और शब्द-पहचान"],"explanationHi":"पूर्वानुमान लगाने से बच्चे पाठ के संकेतों और अपने अनुभव का उपयोग करते हैं, जिससे सक्रिय बोध का निर्माण होता है।"},
  {"id":"cdp-pedagogy-subjects-90","question":"Consider the following statements based on Krashen's theory: 1. The monitor hypothesis says consciously learnt rules act as an editor on what the learner produces. 2. The natural order hypothesis says grammatical structures are acquired in a broadly predictable order. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. Together with the input, acquisition–learning and affective filter hypotheses, these make up Krashen's five hypotheses.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"क्रैशेन के सिद्धांत के आधार पर निम्नलिखित कथनों पर विचार कीजिए: 1. निगरानी परिकल्पना (मॉनिटर हाइपोथीसिस) कहती है कि सचेत रूप से सीखे गए नियम अधिगमकर्ता की प्रस्तुति पर संपादक का काम करते हैं। 2. प्राकृतिक क्रम परिकल्पना कहती है कि व्याकरणिक संरचनाएँ मोटे तौर पर पूर्वानुमेय क्रम में अर्जित की जाती हैं। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। निवेश, अर्जन–अधिगम और भावात्मक छन्नी परिकल्पनाओं के साथ मिलकर ये क्रैशेन की पाँच परिकल्पनाएँ बनाती हैं।"},
  {"id":"cdp-pedagogy-subjects-91","question":"Match the language teaching method with its feature: A. Grammar-translation B. Direct method C. Audio-lingual method D. Communicative approach — 1. Drills and habit formation 2. Meaningful interaction through real-life tasks 3. Translation and explicit rules 4. Target language only, no translation","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"answer":3,"explanation":"Grammar-translation uses translation and rules, the direct method avoids the mother tongue, the audio-lingual method uses behaviourist drills, and the communicative approach stresses meaningful use.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"भाषा शिक्षण विधि का उसकी विशेषता से मिलान कीजिए: A. व्याकरण-अनुवाद B. प्रत्यक्ष विधि C. श्रव्य-भाषिक विधि D. संप्रेषणात्मक उपागम — 1. अभ्यास-कवायद और आदत-निर्माण 2. वास्तविक जीवन के कार्यों के माध्यम से अर्थपूर्ण अंतःक्रिया 3. अनुवाद और स्पष्ट नियम 4. केवल लक्ष्य भाषा, अनुवाद नहीं","optionsHi":["A-3, B-4, C-2, D-1","A-4, B-3, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"explanationHi":"व्याकरण-अनुवाद में अनुवाद और नियमों का उपयोग होता है, प्रत्यक्ष विधि मातृभाषा से बचती है, श्रव्य-भाषिक विधि व्यवहारवादी अभ्यास-कवायद का उपयोग करती है, और संप्रेषणात्मक उपागम अर्थपूर्ण उपयोग पर ज़ोर देता है।"},
  {"id":"cdp-pedagogy-subjects-92","question":"How many of these statements about language policy in education are correct? I. The Kothari Commission recommended the three-language formula. II. Article 350A concerns mother-tongue instruction at the primary stage. III. Article 351 directs the Union to promote the spread of Hindi. IV. NEP 2020 makes it compulsory for every State to teach a particular language.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. NEP 2020 states that no language will be imposed on any State; the choice of languages rests with States and students.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"शिक्षा में भाषा नीति के बारे में इनमें से कितने कथन सही हैं? I. कोठारी आयोग ने त्रि-भाषा सूत्र की अनुशंसा की। II. अनुच्छेद 350A प्राथमिक स्तर पर मातृभाषा में शिक्षा से संबंधित है। III. अनुच्छेद 351 संघ को हिंदी के प्रसार को बढ़ावा देने का निर्देश देता है। IV. NEP 2020 हर राज्य के लिए किसी विशेष भाषा को पढ़ाना अनिवार्य बनाती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। NEP 2020 कहती है कि किसी भी राज्य पर कोई भाषा थोपी नहीं जाएगी; भाषाओं का चयन राज्यों और विद्यार्थियों पर निर्भर है।"},
  {"id":"cdp-pedagogy-subjects-93","question":"Arrange these levels of reading comprehension in increasing order of cognitive demand: 1. Evaluative (critical) 2. Literal 3. Inferential","options":["2, 3, 1","3, 2, 1","2, 1, 3","1, 3, 2"],"answer":0,"explanation":"Literal comprehension recalls what is stated, inferential reads between the lines, and evaluative comprehension judges the text against one's own values and knowledge.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"पठन-बोध के इन स्तरों को संज्ञानात्मक माँग के बढ़ते क्रम में व्यवस्थित कीजिए: 1. मूल्यांकनात्मक (आलोचनात्मक) 2. शाब्दिक 3. अनुमानात्मक","optionsHi":["2, 3, 1","3, 2, 1","2, 1, 3","1, 3, 2"],"explanationHi":"शाब्दिक बोध में जो कहा गया है उसे याद किया जाता है, अनुमानात्मक बोध पंक्तियों के बीच का अर्थ पढ़ता है, और मूल्यांकनात्मक बोध पाठ को अपने मूल्यों और ज्ञान की कसौटी पर परखता है।"},
  {"id":"cdp-pedagogy-subjects-94","question":"Consider the following statements: 1. Dictation can assess listening and writing together. 2. A cloze test assesses only spelling. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":0,"explanation":"Only 1 is correct. A cloze test checks comprehension, vocabulary and grammar, since the missing words must fit the meaning of the passage.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. श्रुतलेख सुनने और लिखने का आकलन एक साथ कर सकता है। 2. क्लोज़ परीक्षण केवल वर्तनी का आकलन करता है। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"केवल 1 सही है। क्लोज़ परीक्षण बोध, शब्दावली और व्याकरण की जाँच करता है, क्योंकि छूटे हुए शब्द अनुच्छेद के अर्थ में फिट होने चाहिए।"},
  {"id":"cdp-pedagogy-subjects-95","question":"Assertion (A): Children should learn the whole alphabet in order before they are exposed to any meaningful text. Reason (R): Reading is mainly the decoding of letters and has little to do with meaning.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","Both A and R are false"],"answer":3,"explanation":"Both are false. Reading is making meaning from text; children benefit from stories and print from the start, with decoding skills taught alongside, not before.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): बच्चों को किसी भी अर्थपूर्ण पाठ से परिचित कराए जाने से पहले पूरी वर्णमाला क्रम से सीख लेनी चाहिए। कारण (R): पठन मुख्यतः अक्षरों का डिकोडिंग है और उसका अर्थ से बहुत कम संबंध है।","optionsHi":["A और R दोनों सत्य हैं और R, A की व्याख्या करता है","A और R दोनों सत्य हैं, लेकिन R, A की व्याख्या नहीं करता","A सत्य है, लेकिन R असत्य है","A और R दोनों असत्य हैं"],"explanationHi":"दोनों असत्य हैं। पठन पाठ से अर्थ निर्माण है; बच्चों को शुरू से ही कहानियों और मुद्रित सामग्री से लाभ होता है, और डिकोडिंग कौशल साथ-साथ सिखाए जाते हैं, उससे पहले नहीं।"},
  {"id":"cdp-pedagogy-subjects-96","question":"A Class II child reads a story aloud fluently but cannot answer simple questions about it. What should the teacher focus on?","options":["More practice in loud, fast reading to build speed and fluency","Comprehension, through talk and links to the child's life","Spelling tests on the difficult words from the story","Copying the story into the notebook for handwriting"],"answer":1,"explanation":"The child can decode but is not making meaning. Talking about the story, predicting and connecting it to life build comprehension.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"कक्षा II का एक बच्चा कहानी को धाराप्रवाह ज़ोर से पढ़ लेता है, लेकिन उसके बारे में सरल प्रश्नों के उत्तर नहीं दे पाता। शिक्षक को किस पर ध्यान देना चाहिए?","optionsHi":["गति और प्रवाह बढ़ाने के लिए ज़ोर से, तेज़ पठन का और अभ्यास","बोध, बातचीत और बच्चे के जीवन से जोड़ने के माध्यम से","कहानी के कठिन शब्दों पर वर्तनी की परीक्षाएँ","हस्तलेखन के लिए कहानी को कॉपी में उतारना"],"explanationHi":"बच्चा डिकोड कर सकता है, लेकिन अर्थ का निर्माण नहीं कर रहा है। कहानी पर बातचीत करने, पूर्वानुमान लगाने और उसे जीवन से जोड़ने से बोध का निर्माण होता है।"},
  {"id":"cdp-pedagogy-subjects-97","question":"Which classroom arrangement best supports a child with a hearing impairment in a language class?","options":["Seating the child at the back to avoid distraction","Speaking faster so that the whole lesson gets covered","Turning to the board while speaking, to model the writing clearly","Seating the child to see the teacher's face, with visual aids"],"answer":3,"explanation":"Seeing the speaker's face helps lip-reading, and visual support makes content accessible, in line with inclusive education under the RPwD Act, 2016.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"भाषा की कक्षा में श्रवण-बाधित बच्चे के लिए कौन-सी कक्षा-व्यवस्था सबसे अधिक सहायक है?","optionsHi":["बच्चे को ध्यान भटकने से बचाने के लिए पीछे बिठाना","पूरा पाठ पूरा करने के लिए तेज़ बोलना","लेखन को स्पष्ट रूप से दिखाने के लिए बोलते समय श्यामपट्ट की ओर मुड़ना","बच्चे को शिक्षक का चेहरा दिखाई दे, ऐसे बिठाना और दृश्य सामग्री का उपयोग करना"],"explanationHi":"वक्ता का चेहरा देखने से होंठ-पठन में मदद मिलती है, और दृश्य सहायता विषय-वस्तु को सुलभ बनाती है, जो RPwD अधिनियम, 2016 के अंतर्गत समावेशी शिक्षा के अनुरूप है।"},
  {"id":"cdp-pedagogy-subjects-98","question":"How many of these statements about the process approach to writing are correct? I. It focuses mainly on the grammatical accuracy of the finished text. II. Feedback from peers is discouraged. III. Only the final product is assessed. IV. Drafts are revised before the final version.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only IV is correct. The process approach focuses on the stages of composing (accuracy of the final text is the product approach), values peer feedback, and assesses drafts and revisions, not just the final product.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"लेखन के प्रक्रिया उपागम के बारे में इनमें से कितने कथन सही हैं? I. यह मुख्य रूप से तैयार पाठ की व्याकरणिक शुद्धता पर ध्यान देता है। II. सहपाठियों से प्रतिपुष्टि को हतोत्साहित किया जाता है। III. केवल अंतिम उत्पाद का आकलन किया जाता है। IV. अंतिम रूप से पहले प्रारूपों का संशोधन किया जाता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल IV सही है। प्रक्रिया उपागम लेखन-रचना के चरणों पर ध्यान देता है (अंतिम पाठ की शुद्धता उत्पाद उपागम है), सहपाठियों की प्रतिपुष्टि को महत्त्व देता है, और केवल अंतिम उत्पाद का नहीं, बल्कि प्रारूपों और संशोधनों का भी आकलन करता है।"},
  {"id":"cdp-pedagogy-subjects-99","question":"Consider the following statements: 1. Phonemic awareness is an oral skill and can be developed without print, for example through rhymes and sound games. 2. Phonics connects sounds with written letters. Which of the above is/are correct?","options":["1 only","2 only","Both 1 and 2","Neither 1 nor 2"],"answer":2,"explanation":"Both are correct. Phonemic awareness (hearing and playing with sounds) usually comes first and supports later phonics instruction.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. ध्वनि-स्वनिम जागरूकता (फ़ोनेमिक अवेयरनेस) एक मौखिक कौशल है और इसे मुद्रित सामग्री के बिना भी विकसित किया जा सकता है, जैसे तुकबंदियों और ध्वनि-खेलों के माध्यम से। 2. फ़ोनिक्स ध्वनियों को लिखित अक्षरों से जोड़ता है। उपर्युक्त में से कौन-सा/से सही है/हैं?","optionsHi":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1 और न ही 2"],"explanationHi":"दोनों सही हैं। फ़ोनेमिक अवेयरनेस (ध्वनियों को सुनना और उनसे खेलना) प्रायः पहले आती है और बाद के फ़ोनिक्स शिक्षण में सहायक होती है।"},
  {"id":"cdp-pedagogy-subjects-100","question":"A teacher lets children answer in their home language during an English lesson and then helps them express the same idea in English. This practice is best described as:","options":["Using the mother tongue as a resource for learning English","Lowering the standard of English teaching in the class","The grammar-translation method of language teaching","Avoiding the target language to keep children comfortable"],"answer":0,"explanation":"NCF 2005 treats multilingualism as a resource; building on the home language lets children participate and gradually move to English.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षक अंग्रेज़ी के पाठ में बच्चों को घरेलू भाषा में उत्तर देने देता है और फिर उसी विचार को अंग्रेज़ी में व्यक्त करने में उनकी मदद करता है। इस अभ्यास का सबसे अच्छा वर्णन है:","optionsHi":["मातृभाषा का अंग्रेज़ी सीखने के संसाधन के रूप में उपयोग","कक्षा में अंग्रेज़ी शिक्षण का स्तर गिराना","भाषा शिक्षण की व्याकरण-अनुवाद विधि","बच्चों को सहज रखने के लिए लक्ष्य भाषा से बचना"],"explanationHi":"NCF 2005 बहुभाषिकता को एक संसाधन मानता है; घरेलू भाषा पर आधारित होने से बच्चे भाग ले पाते हैं और धीरे-धीरे अंग्रेज़ी की ओर बढ़ते हैं।"},
  {"id":"cdp-pedagogy-subjects-101","question":"A Class 6 child writes 0.3 × 0.2 = 0.6. Which teaching response best addresses the misconception behind this answer?","options":["Tell the child to count the total decimal places and practise twenty such sums","Use a 10 × 10 grid to show that 3 tenths of 2 tenths is 6 hundredths","Explain that the decimal point in a product stays where it is in the numbers","Convert both numbers to whole numbers, multiply, and ignore the decimal point"],"answer":1,"explanation":"The child is treating decimal multiplication like addition of tenths. An area model shows the answer is 6 hundredths (0.06) and builds the reasoning that taking part of a part gives something smaller; a rule alone leaves the misconception intact.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 6 का एक बच्चा 0.3 × 0.2 = 0.6 लिखता है। कौन-सी शिक्षण-प्रतिक्रिया इस उत्तर के पीछे की भ्रांत धारणा का सबसे अच्छा समाधान करती है?","optionsHi":["बच्चे से कुल दशमलव स्थान गिनने को कहना और ऐसे बीस प्रश्नों का अभ्यास कराना","10 × 10 ग्रिड का उपयोग करके दिखाना कि 3 दशमांश और 2 दशमांश का गुणनफल 6 सौवाँ भाग होता है","समझाना कि गुणनफल में दशमलव बिंदु वहीं रहता है जहाँ वह संख्याओं में होता है","दोनों संख्याओं को पूर्ण संख्या में बदलना, गुणा करना और दशमलव बिंदु को अनदेखा करना"],"explanationHi":"बच्चा दशमलव के गुणा को दशमांशों के जोड़ की तरह मान रहा है। क्षेत्रफल मॉडल दिखाता है कि उत्तर 6 सौवाँ भाग (0.06) है और यह तर्क निर्मित करता है कि भाग का भाग लेने पर छोटी चीज़ मिलती है; केवल नियम भ्रांत धारणा को बनाए रखता है।"},
  {"id":"cdp-pedagogy-subjects-102","question":"Asked to fill the box in 5 + ☐ = 12, several Class 2 children write 17. The most likely reason, and the best response, is that the children:","options":["Cannot yet add within 20, so they need more daily addition drill","Did not read the question, so they need to be told to be careful next time","Read ‘=’ as ‘write the answer’; use a balance to show it means ‘the same as’","Are confused by the box, so it should be replaced by a blank line or a letter"],"answer":2,"explanation":"Children often hold an operational view of the equals sign (‘do the sum’). Activities with balances and varied forms of equations develop the relational meaning needed for later algebra.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"5 + ☐ = 12 में खाना भरने को कहने पर कक्षा 2 के कई बच्चे 17 लिखते हैं। इसका सबसे संभावित कारण और सबसे अच्छी प्रतिक्रिया यह है कि बच्चे:","optionsHi":["अभी 20 के भीतर जोड़ नहीं कर सकते, इसलिए उन्हें रोज़ जोड़ का और अभ्यास चाहिए","प्रश्न पढ़ते ही नहीं हैं, इसलिए अगली बार सावधान रहने को कहना चाहिए","‘=’ को ‘उत्तर लिखो’ पढ़ते हैं; तुला (बैलेंस) से दिखाइए कि इसका अर्थ ‘के बराबर’ है","खाने से भ्रमित हैं, इसलिए उसे रिक्त रेखा या अक्षर से बदल देना चाहिए"],"explanationHi":"बच्चों में प्रायः बराबर-चिह्न की संक्रियात्मक समझ (‘जोड़ करो’) होती है। तुला की गतिविधियाँ और समीकरणों के विविध रूप बाद के बीजगणित के लिए आवश्यक संबंधात्मक अर्थ विकसित करते हैं।"},
  {"id":"cdp-pedagogy-subjects-103","question":"A Class 4 child insists that 1/8 is bigger than 1/6 ‘because 8 is bigger than 6’. Which activity is most likely to change this idea?","options":["Sharing equal rotis among 6 and among 8 friends and comparing the shares","Making the child write ‘1/6 > 1/8’ ten times in the notebook","Teaching the rule ‘bigger denominator, smaller fraction’ to be memorised","Converting both fractions to decimals with a calculator and comparing"],"answer":0,"explanation":"The child is applying whole-number ordering to fractions. Fair-sharing experience shows that more sharers make smaller pieces, giving meaning to the rule instead of a memorised statement.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 4 का एक बच्चा ज़ोर देकर कहता है कि 1/8, 1/6 से बड़ा है ‘क्योंकि 8, 6 से बड़ा है’। कौन-सी गतिविधि इस विचार को बदलने की सबसे अधिक संभावना रखती है?","optionsHi":["6 और 8 मित्रों के बीच बराबर रोटियाँ बाँटना और हिस्सों की तुलना करना","बच्चे से कॉपी में ‘1/6 > 1/8’ दस बार लिखवाना","‘बड़ा हर, छोटी भिन्न’ का नियम याद करने के लिए सिखाना","कैलकुलेटर से दोनों भिन्नों को दशमलव में बदलना और तुलना करना"],"explanationHi":"बच्चा भिन्नों पर पूर्ण संख्याओं का क्रम लागू कर रहा है। बराबर बँटवारे का अनुभव दिखाता है कि अधिक बाँटने वालों से टुकड़े छोटे बनते हैं, जिससे रटे हुए कथन के बजाय नियम को अर्थ मिलता है।"},
  {"id":"cdp-pedagogy-subjects-104","question":"Many Class 5 children believe that two rectangles with the same perimeter must have the same area. Which activity best challenges this belief?","options":["Giving the formulas for perimeter and area to memorise and apply","Asking them to find the area and perimeter of a single 6 cm × 6 cm square","Telling them clearly that area and perimeter are different ideas","Making different rectangles from a 24 cm string loop and comparing areas"],"answer":3,"explanation":"With a perimeter of 24 cm they can make 1 × 11 (area 11), 2 × 10 (area 20) or 6 × 6 (area 36): same perimeter, very different areas. Discovering this first-hand changes the belief.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"कक्षा 5 के कई बच्चे मानते हैं कि समान परिमाप वाले दो आयतों का क्षेत्रफल भी समान होना चाहिए। कौन-सी गतिविधि इस धारणा को सबसे अच्छी तरह चुनौती देती है?","optionsHi":["परिमाप और क्षेत्रफल के सूत्र याद करने और लागू करने के लिए देना","उनसे केवल एक 6 cm × 6 cm वर्ग का क्षेत्रफल और परिमाप निकालने को कहना","उन्हें स्पष्ट रूप से बताना कि क्षेत्रफल और परिमाप अलग-अलग विचार हैं","24 cm की डोरी के फंदे से अलग-अलग आयत बनाना और क्षेत्रफलों की तुलना करना"],"explanationHi":"24 cm परिमाप से वे 1 × 11 (क्षेत्रफल 11), 2 × 10 (क्षेत्रफल 20) या 6 × 6 (क्षेत्रफल 36) बना सकते हैं: परिमाप समान, क्षेत्रफल बहुत भिन्न। इसे स्वयं खोजने से धारणा बदलती है।"},
  {"id":"cdp-pedagogy-subjects-105","question":"A child measures a pencil by placing its end at the ‘1’ mark of a ruler and reads ‘8 cm’ at the other end; the pencil is actually 7 cm long. The child most likely:","options":["Has poor eyesight and needs a ruler with larger numbers","Reads the number at the end instead of counting the unit spaces","Does not know the numbers up to 10 in the right order","Has been taught the wrong length of a centimetre in an earlier class"],"answer":1,"explanation":"Measuring means counting units (spaces) from a zero point; children who see the ruler as a list of numbers make this error. Measuring with unit strips or ‘broken rulers’ builds the idea.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक बच्चा पेंसिल को मापने के लिए उसका सिरा पैमाने के ‘1’ के निशान पर रखता है और दूसरे सिरे पर ‘8 cm’ पढ़ता है; पेंसिल वास्तव में 7 cm लंबी है। बच्चा संभवतः:","optionsHi":["की आँखें कमज़ोर हैं और उसे बड़े अंकों वाला पैमाना चाहिए","इकाई-अंतरालों को गिनने के बजाय अंत पर लिखी संख्या पढ़ता है","10 तक की संख्याओं का सही क्रम नहीं जानता","को पहले की किसी कक्षा में सेंटीमीटर की गलत लंबाई सिखाई गई है"],"explanationHi":"मापन का अर्थ है शून्य बिंदु से इकाइयों (अंतरालों) को गिनना; जो बच्चे पैमाने को संख्याओं की सूची मानते हैं, वे यह त्रुटि करते हैं। इकाई-पट्टियों या ‘टूटे पैमाने’ से मापने पर यह विचार बनता है।"},
  {"id":"cdp-pedagogy-subjects-106","question":"A teacher first lets children measure the length of the classroom with their own footsteps and hand spans, and only later introduces the metre. The main purpose is to:","options":["Make children see the need for a standard unit when results differ","Avoid teaching standard units altogether in primary classes","Save the cost of buying metre scales for every child","Show that body measures are more accurate than rulers for length"],"answer":0,"explanation":"When different children get different numbers of hand spans for the same length, they see why a common, standard unit is needed; this gives meaning to the metre.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"एक शिक्षक पहले बच्चों से कक्षा की लंबाई उनके अपने कदमों और बित्तों से नपवाता है, और बाद में ही मीटर से परिचित कराता है। इसका मुख्य उद्देश्य है:","optionsHi":["परिणाम अलग-अलग आने पर बच्चों को मानक इकाई की आवश्यकता दिखाना","प्राथमिक कक्षाओं में मानक इकाइयों को बिल्कुल न पढ़ाना","हर बच्चे के लिए मीटर-पैमाने खरीदने का खर्च बचाना","यह दिखाना कि लंबाई के लिए शारीरिक माप पैमानों से अधिक सटीक होते हैं"],"explanationHi":"जब अलग-अलग बच्चों को एक ही लंबाई के लिए बित्तों की अलग-अलग संख्या मिलती है, तो वे देखते हैं कि एक सामान्य, मानक इकाई क्यों ज़रूरी है; इससे मीटर को अर्थ मिलता है।"},
  {"id":"cdp-pedagogy-subjects-107","question":"Which response by a Class 4 child shows the best number sense?","options":["Writing 99 + 47 in columns and carrying the ones carefully","Counting on from 99 one by one up to 146","Saying ‘99 + 47 is the same as 100 + 46, so it’s 146’","Using a calculator to work out and check 99 + 47"],"answer":2,"explanation":"Number sense is flexible understanding of numbers and their relationships; seeing 99 as 1 less than 100 and adjusting shows it. The column method is correct but procedural.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 4 के बच्चे की कौन-सी प्रतिक्रिया सबसे अच्छा संख्या-बोध दर्शाती है?","optionsHi":["99 + 47 को स्तंभों में लिखकर इकाई का हासिल सावधानी से लगाना","99 से एक-एक करके 146 तक आगे गिनना","यह कहना कि ‘99 + 47, 100 + 46 के बराबर है, इसलिए यह 146 है’","99 + 47 को निकालने और जाँचने के लिए कैलकुलेटर का उपयोग करना"],"explanationHi":"संख्या-बोध संख्याओं और उनके संबंधों की लचीली समझ है; 99 को 100 से 1 कम देखना और समायोजन करना इसे दर्शाता है। स्तंभ विधि सही है, लेकिन प्रक्रियात्मक है।"},
  {"id":"cdp-pedagogy-subjects-108","question":"A child works out 298 + 165 by thinking ‘300 + 165 = 465, and I added 2 too many, so 463.’ This mental strategy is called:","options":["Partitioning by place value","Counting on in ones","Using the standard algorithm","Compensation"],"answer":3,"explanation":"Compensation rounds one number to a friendly value and then adjusts for the change. It reflects a sound understanding of how numbers can be rearranged.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक बच्चा 298 + 165 को यह सोचकर निकालता है: ‘300 + 165 = 465, और मैंने 2 अधिक जोड़ दिए, इसलिए 463।’ इस मानसिक रणनीति को क्या कहते हैं?","optionsHi":["स्थानीय मान के अनुसार विभाजन","इकाइयों में आगे गिनना","मानक एल्गोरिदम का उपयोग","प्रतिपूरण (कम्पेन्सेशन)"],"explanationHi":"प्रतिपूरण में एक संख्या को सुविधाजनक मान तक पूर्णांकित करके फिर परिवर्तन के लिए समायोजन किया जाता है। यह दर्शाता है कि संख्याओं को किस प्रकार पुनर्व्यवस्थित किया जा सकता है, इसकी ठोस समझ है।"},
  {"id":"cdp-pedagogy-subjects-109","question":"Squares are made in a row with matchsticks: 1 square needs 4 sticks, 2 squares need 7, 3 squares need 10. A child says 10 squares need 40 sticks. The child’s error and the correct number are:","options":["Counted each square separately, ignoring shared sides; 31 sticks","Added 3 sticks for every square including the first; 30 sticks","Multiplied correctly by 4 sticks per square; 40 sticks is right","Forgot to add the first starting stick of the row; 41 sticks"],"answer":0,"explanation":"After the first square each new square needs only 3 sticks, so n squares need 3n + 1 = 31. Asking children to explain the rule from the figure moves them from counting to algebraic generalisation.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"माचिस की तीलियों से एक पंक्ति में वर्ग बनाए जाते हैं: 1 वर्ग के लिए 4 तीलियाँ चाहिए, 2 वर्गों के लिए 7, 3 वर्गों के लिए 10। एक बच्चा कहता है कि 10 वर्गों के लिए 40 तीलियाँ चाहिए। बच्चे की त्रुटि और सही संख्या हैं:","optionsHi":["हर वर्ग को अलग-अलग गिना, साझा भुजाओं को अनदेखा किया; 31 तीलियाँ","पहले वर्ग सहित हर वर्ग के लिए 3 तीलियाँ जोड़ीं; 30 तीलियाँ","प्रति वर्ग 4 तीलियों से सही गुणा किया; 40 तीलियाँ सही है","पंक्ति की शुरुआती पहली तीली जोड़ना भूल गया; 41 तीलियाँ"],"explanationHi":"पहले वर्ग के बाद हर नए वर्ग के लिए केवल 3 तीलियाँ चाहिए, इसलिए n वर्गों के लिए 3n + 1 = 31 तीलियाँ चाहिए। बच्चों से आकृति के आधार पर नियम समझाने को कहने से वे गिनने से बीजीय सामान्यीकरण की ओर बढ़ते हैं।"},
  {"id":"cdp-pedagogy-subjects-110","question":"In a pictograph where one 🙂 stands for 5 children, a Class 3 child reads 4 symbols as ‘4 children like mangoes’. The child has difficulty with:","options":["Counting the symbols correctly up to 5","Collecting the data through tally marks first","Interpreting the key (scale) of the pictograph","Drawing the symbols neatly and of equal size"],"answer":2,"explanation":"The child reads each symbol as one item. Building pictographs themselves with a one-to-many key helps children understand scale (4 symbols × 5 = 20 children).","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक चित्रालेख (पिक्टोग्राफ़) में, जहाँ एक 🙂 का मान 5 बच्चे है, कक्षा 3 का एक बच्चा 4 प्रतीकों को ‘4 बच्चों को आम पसंद हैं’ पढ़ता है। बच्चे को किसमें कठिनाई है?","optionsHi":["5 तक प्रतीकों को सही गिनने में","पहले टैली चिह्नों से आँकड़े इकट्ठा करने में","चित्रालेख की कुंजी (पैमाने) की व्याख्या करने में","प्रतीकों को साफ़-सुथरा और समान आकार का बनाने में"],"explanationHi":"बच्चा हर प्रतीक को एक वस्तु पढ़ता है। एक-से-अनेक कुंजी वाले चित्रालेख स्वयं बनाने से बच्चों को पैमाना समझने में मदद मिलती है (4 प्रतीक × 5 = 20 बच्चे)।"},
  {"id":"cdp-pedagogy-subjects-111","question":"Shown a triangle standing on one of its corners, several Class 2 children say, ‘That is not a triangle, it is upside down.’ The best teaching response is to:","options":["Tell them that it is a triangle and move on to the next shape","Avoid showing shapes in unusual positions until children reach higher classes","Teach the formal definition of a triangle for them to memorise","Let them make triangles in varied positions and discuss what they share"],"answer":3,"explanation":"Children’s idea of a shape is often tied to a prototype seen in books. Varied examples and attention to defining properties (three straight sides, closed) broaden the concept.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"एक कोने पर खड़ा त्रिभुज दिखाए जाने पर कक्षा 2 के कई बच्चे कहते हैं, ‘यह त्रिभुज नहीं है, यह उलटा है।’ सबसे अच्छी शिक्षण-प्रतिक्रिया है:","optionsHi":["उन्हें बताना कि यह त्रिभुज है और अगली आकृति पर बढ़ जाना","बच्चों के ऊँची कक्षाओं में पहुँचने तक आकृतियों को असामान्य स्थितियों में न दिखाना","याद करने के लिए त्रिभुज की औपचारिक परिभाषा सिखाना","बच्चों को अलग-अलग स्थितियों में त्रिभुज बनाने देना और इस पर चर्चा करना कि उनमें क्या समान है"],"explanationHi":"बच्चों की किसी आकृति की धारणा प्रायः पुस्तकों में देखे प्रारूप से बँधी होती है। विविध उदाहरण और परिभाषित गुणों (तीन सीधी भुजाएँ, बंद) पर ध्यान अवधारणा को व्यापक बनाते हैं।"},
  {"id":"cdp-pedagogy-subjects-112","question":"Shown two angles of the same size, one drawn with long arms and one with short arms, a child says the one with longer arms is bigger. Which activity best addresses this?","options":["Making the child memorise that an angle is measured in degrees","Show with hinged strips that angle is the turn, not the arm length","Asking the child to draw the arms more carefully and evenly","Telling the child to always use a protractor, without any discussion"],"answer":1,"explanation":"The misconception confuses angle with arm length. Seeing an angle as an amount of turn, with arms that can be extended without changing it, builds the correct concept.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"समान माप के दो कोण दिखाए जाने पर, जिनमें से एक की भुजाएँ लंबी और दूसरे की छोटी बनी हैं, एक बच्चा कहता है कि जिसकी भुजाएँ लंबी हैं वह बड़ा है। कौन-सी गतिविधि इसका सबसे अच्छा समाधान करती है?","optionsHi":["बच्चे से यह याद कराना कि कोण को अंशों में मापा जाता है","कब्ज़ेदार पट्टियों से दिखाना कि कोण घुमाव है, भुजा की लंबाई नहीं","बच्चे से भुजाएँ अधिक ध्यान से और समान बनाने को कहना","बिना किसी चर्चा के बच्चे को हमेशा चाँदा (प्रोट्रैक्टर) उपयोग करने को कहना"],"explanationHi":"यह भ्रांत धारणा कोण को भुजा की लंबाई से मिला देती है। कोण को घुमाव की मात्रा के रूप में देखना, जिसकी भुजाएँ बिना कोण बदले बढ़ाई जा सकती हैं, सही अवधारणा बनाता है।"},
  {"id":"cdp-pedagogy-subjects-113","question":"Asked to write ‘four hundred and five’ in numerals, a Class 3 child writes 4005. The error most clearly shows that the child:","options":["Writes the number as it sounds, without grasping place value","Cannot yet write the digit 5 in the correct form","Does not know the number name ‘four hundred’ at all","Is careless and needs to be told to check the answer again"],"answer":0,"explanation":"Children who write ‘400’ and ‘5’ side by side are transcribing the spoken form. Place value mats and expanded forms (400 + 0 + 5) build the idea that zero holds the tens place.","difficulty":"hard","source":"CTET · State TETs","questionHi":"‘चार सौ पाँच’ को अंकों में लिखने को कहने पर कक्षा 3 का एक बच्चा 4005 लिखता है। यह त्रुटि सबसे स्पष्ट रूप से दर्शाती है कि बच्चा:","optionsHi":["संख्या को वैसे ही लिखता है जैसी वह सुनाई देती है, स्थानीय मान को समझे बिना","अंक 5 को अभी सही रूप में नहीं लिख सकता","संख्या-नाम ‘चार सौ’ को बिल्कुल नहीं जानता","लापरवाह है और उसे उत्तर को फिर से जाँचने को कहना चाहिए"],"explanationHi":"जो बच्चे ‘400’ और ‘5’ को साथ-साथ लिखते हैं, वे बोले गए रूप को उतार रहे होते हैं। स्थानीय मान की पट्टी और विस्तारित रूप (400 + 0 + 5) यह विचार बनाते हैं कि शून्य दहाई का स्थान रखता है।"},
  {"id":"cdp-pedagogy-subjects-114","question":"A child works out 23 × 14 as 23 × 4 = 92 and 23 × 1 = 23, then adds to get 115. The real source of the error is that the child:","options":["Cannot multiply a two-digit number by 4 correctly","Does not know the multiplication table of 23 by heart, so guesses","Treats the 1 in 14 as one, not one ten, so never forms 23 × 10","Adds 23 and 14 at some step instead of multiplying"],"answer":2,"explanation":"The correct product is 92 + 230 = 322. The ‘shift’ in the algorithm stands for multiplying by ten; an area or grid method (20 × 10, 3 × 10, 20 × 4, 3 × 4) makes this visible.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक बच्चा 23 × 14 को इस प्रकार निकालता है: 23 × 4 = 92 और 23 × 1 = 23, फिर जोड़कर 115 पाता है। त्रुटि का वास्तविक स्रोत यह है कि बच्चा:","optionsHi":["दो अंकों की संख्या को 4 से सही गुणा नहीं कर सकता","23 का पहाड़ा कंठस्थ नहीं जानता, इसलिए अनुमान लगाता है","1 को, जो 14 में है, एक मानता है, एक दहाई नहीं, इसलिए कभी 23 × 10 नहीं बनाता","किसी चरण पर गुणा करने के बजाय 23 और 14 को जोड़ देता है"],"explanationHi":"सही गुणनफल 92 + 230 = 322 है। एल्गोरिदम में ‘खिसकाव’ दस से गुणा को दर्शाता है; क्षेत्रफल या ग्रिड विधि (20 × 10, 3 × 10, 20 × 4, 3 × 4) इसे दृश्य बना देती है।"},
  {"id":"cdp-pedagogy-subjects-115","question":"A Class 4 child divides 728 by 7 and writes the quotient as 14. The most likely misconception and the correct quotient are:","options":["The child cannot do 7 ÷ 7 correctly; the answer is 140","The child divided by 2 instead of 7; the answer is 104","The child made an error in the table of 7 while dividing; the answer is 114","Skips the 0 in the tens place when 2 tens cannot be divided by 7; 104"],"answer":3,"explanation":"7 hundreds ÷ 7 = 1 hundred, 2 tens ÷ 7 = 0 tens (carry 20), 28 ones ÷ 7 = 4, so 104. Estimating first (700 ÷ 7 = 100) would show that 14 is far too small.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 4 का एक बच्चा 728 को 7 से विभाजित करता है और भागफल 14 लिखता है। सबसे संभावित भ्रांत धारणा और सही भागफल हैं:","optionsHi":["बच्चा 7 ÷ 7 सही नहीं कर सकता; उत्तर 140 है","बच्चे ने 2 से भाग दिया, 7 से नहीं; उत्तर 104 है","भाग देते समय बच्चे ने 7 के पहाड़े में त्रुटि की; उत्तर 114 है","दहाई के स्थान का 0 छोड़ देता है, जब 2 दहाई को 7 से विभाजित नहीं किया जा सकता; 104"],"explanationHi":"7 सैकड़ा ÷ 7 = 1 सैकड़ा, 2 दहाई ÷ 7 = 0 दहाई (20 हासिल), 28 इकाई ÷ 7 = 4, इसलिए 104। पहले अनुमान लगाने (700 ÷ 7 = 100) से पता चलता कि 14 बहुत छोटा है।"},
  {"id":"cdp-pedagogy-subjects-116","question":"A teacher asks Class 4 children to make up their own word problems for 24 ÷ 4 and share them. The main pedagogical value of this task is that it:","options":["Reduces the teacher’s work in preparing practice questions","Shows whether children know what division means in real life","Is mainly a test of children’s handwriting and spelling","Helps children memorise the division table of 4 faster"],"answer":1,"explanation":"Problem posing reveals whether children can connect the symbol to meaning; it often exposes children who can calculate but cannot tell when division applies.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षक कक्षा 4 के बच्चों से 24 ÷ 4 के लिए अपने शब्द-प्रश्न बनाने और उन्हें साझा करने को कहता है। इस कार्य का मुख्य शैक्षिक मूल्य यह है कि वह:","optionsHi":["अभ्यास-प्रश्न तैयार करने में शिक्षक का काम कम करता है","दिखाता है कि बच्चे जानते हैं या नहीं कि वास्तविक जीवन में भाग का क्या अर्थ है","मुख्य रूप से बच्चों की हस्तलिपि और वर्तनी की परीक्षा है","बच्चों को 4 का भाग-पहाड़ा अधिक तेज़ी से याद करने में मदद करता है"],"explanationHi":"प्रश्न-निर्माण यह प्रकट करता है कि बच्चे प्रतीक को अर्थ से जोड़ सकते हैं या नहीं; यह प्रायः उन बच्चों को उजागर कर देता है जो गणना कर सकते हैं, लेकिन यह नहीं बता सकते कि भाग कब लागू होता है।"},
  {"id":"cdp-pedagogy-subjects-117","question":"Which problem models division as grouping (measurement or quotitive division) rather than as equal sharing?","options":["12 sweets are shared equally among 3 children. How many does each child get?","A ribbon of 12 m is cut into 3 equal pieces. How long is each piece?","There are 12 sweets and each child gets 3. How many children get sweets?","12 apples are put equally into 3 baskets. How many are in each basket?"],"answer":2,"explanation":"In grouping, the size of each group is known and the number of groups is asked; in sharing, the number of groups is known and the size of each is asked. Children need experience of both.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"कौन-सी समस्या भाग को बराबर बाँटने के बजाय समूहन (मापन या मात्रात्मक भाग) के रूप में निरूपित करती है?","optionsHi":["12 मिठाइयाँ 3 बच्चों में बराबर बाँटी जाती हैं। प्रत्येक बच्चे को कितनी मिलती हैं?","12 m का एक फ़ीता 3 बराबर टुकड़ों में काटा जाता है। प्रत्येक टुकड़ा कितना लंबा है?","12 मिठाइयाँ हैं और प्रत्येक बच्चे को 3 मिलती हैं। कितने बच्चों को मिठाई मिलेगी?","12 सेब 3 टोकरियों में बराबर-बराबर रखे जाते हैं। प्रत्येक टोकरी में कितने हैं?"],"explanationHi":"समूहन में प्रत्येक समूह का आकार ज्ञात होता है और समूहों की संख्या पूछी जाती है; बँटवारे में समूहों की संख्या ज्ञात होती है और प्रत्येक का आकार पूछा जाता है। बच्चों को दोनों का अनुभव चाहिए।"},
  {"id":"cdp-pedagogy-subjects-118","question":"Which assessment item would give a teacher the MOST diagnostic information about children’s understanding of subtraction?","options":["Ten sums like 64 − 28, each marked simply as right or wrong","A timed test of fifty basic subtraction facts up to 20","A multiple-choice question on the rule for borrowing","Solving 64 − 28 and explaining the method in words or drawings"],"answer":3,"explanation":"An explanation shows the strategy and reasoning behind the answer, revealing specific misconceptions; right/wrong marks show only whether the result was correct.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कौन-सा आकलन-प्रश्न घटाव की बच्चों की समझ के बारे में शिक्षक को सबसे अधिक निदानात्मक जानकारी देगा?","optionsHi":["64 − 28 जैसे दस प्रश्न, जिन्हें केवल सही या गलत चिह्नित किया जाए","20 तक के पचास मूल घटाव-तथ्यों की समयबद्ध परीक्षा","उधार लेने के नियम पर एक बहुविकल्पीय प्रश्न","64 − 28 हल करना और विधि को शब्दों या चित्रों में समझाना"],"explanationHi":"स्पष्टीकरण उत्तर के पीछे की रणनीति और तर्क दिखाता है और विशिष्ट भ्रांत धारणाओं को प्रकट करता है; सही/गलत के अंक केवल यह दिखाते हैं कि परिणाम सही था या नहीं।"},
  {"id":"cdp-pedagogy-subjects-119","question":"The NCF 2005 position paper on mathematics distinguishes a ‘narrow aim’ and a ‘higher aim’ of school mathematics. The higher aim is to:","options":["Develop mathematical thinking: reasoning, logic and handling abstraction","Teach useful numeracy for daily life, such as calculation and measurement","Prepare every child for competitive and entrance examinations later","Complete the syllabus on time with plenty of drill and practice"],"answer":0,"explanation":"The narrow aim is useful numeracy; the higher aim is to develop mathematical thinking itself, which NCF 2005 calls the main goal (mathematisation).","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"गणित पर NCF 2005 का पोज़ीशन पेपर विद्यालयी गणित के ‘संकीर्ण उद्देश्य’ और ‘उच्च उद्देश्य’ में अंतर करता है। उच्च उद्देश्य है:","optionsHi":["गणितीय चिंतन विकसित करना: तर्क, युक्ति और अमूर्तन को सँभालना","दैनिक जीवन के लिए उपयोगी संख्यात्मकता सिखाना, जैसे गणना और मापन","हर बच्चे को आगे चलकर प्रतियोगी और प्रवेश परीक्षाओं के लिए तैयार करना","भरपूर अभ्यास और दोहराव के साथ पाठ्यक्रम समय पर पूरा करना"],"explanationHi":"संकीर्ण उद्देश्य उपयोगी संख्यात्मकता है; उच्च उद्देश्य स्वयं गणितीय चिंतन का विकास करना है, जिसे NCF 2005 मुख्य लक्ष्य (गणितीकरण) कहता है।"},
  {"id":"cdp-pedagogy-subjects-120","question":"Children can correctly show 42 − 17 with base-ten blocks by exchanging a ten for ten ones, but they still make errors in the written column method. The teacher’s best next step is to:","options":["Stop using blocks because they are confusing the children","Have children record each step on paper as they do it with the blocks","Teach the written method separately as a fixed set of rules to follow","Give them more practice with the blocks alone, without writing"],"answer":1,"explanation":"Concrete materials help only when connected to the symbols; recording alongside the action builds the bridge from the enactive to the symbolic form.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"बच्चे आधार-दस ब्लॉकों से एक दहाई को दस इकाइयों में बदलकर 42 − 17 सही दिखा सकते हैं, लेकिन लिखित स्तंभ विधि में अब भी त्रुटियाँ करते हैं। शिक्षक का सबसे अच्छा अगला कदम है:","optionsHi":["ब्लॉकों का उपयोग बंद करना, क्योंकि वे बच्चों को भ्रमित कर रहे हैं","बच्चों से ब्लॉकों से करते समय हर चरण को कागज़ पर दर्ज करवाना","लिखित विधि को अनुसरण करने के लिए नियमों के निश्चित समूह के रूप में अलग से सिखाना","बिना लिखे केवल ब्लॉकों के साथ और अभ्यास कराना"],"explanationHi":"मूर्त सामग्री तभी सहायक होती है जब वह प्रतीकों से जुड़ी हो; क्रिया के साथ-साथ दर्ज करने से क्रियात्मक रूप से सांकेतिक रूप तक का सेतु बनता है।"},
  {"id":"cdp-pedagogy-subjects-121","question":"Exploring a calendar, children find that in several 3 × 3 blocks the sum of the nine dates equals 9 times the middle date. One child says, ‘If the middle is n, the dates are n − 8, n − 7, n − 6, n − 1, n, n + 1, n + 6, n + 7, n + 8, and they add up to 9n.’ This child has moved from:","options":["Rote recall of calendar facts to quick and accurate mental calculation","Measurement of time to rough estimation of the totals","Checking examples to a general argument for why it always holds","Algebraic reasoning back to plain arithmetic on dates"],"answer":2,"explanation":"Testing cases is inductive; using a variable to show the pattern holds for every block is generalisation and justification, a key step towards algebraic reasoning.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कैलेंडर की खोजबीन करते हुए बच्चे पाते हैं कि कई 3 × 3 खंडों में नौ तारीखों का योग बीच की तारीख का 9 गुना होता है। एक बच्चा कहता है, ‘यदि बीच की तारीख n है, तो तारीखें n − 8, n − 7, n − 6, n − 1, n, n + 1, n + 6, n + 7, n + 8 हैं, और उनका योग 9n होता है।’ इस बच्चे ने किससे किस ओर प्रगति की है?","optionsHi":["कैलेंडर के तथ्यों को रटने से तेज़ और सटीक मानसिक गणना की ओर","समय के मापन से योगों के मोटे अनुमान की ओर","उदाहरणों की जाँच से इस सामान्य तर्क की ओर कि यह हमेशा क्यों सही होता है","बीजीय तर्क से वापस तारीखों के साधारण अंकगणित की ओर"],"explanationHi":"मामलों की जाँच करना आगमनात्मक है; चर का उपयोग करके दिखाना कि पैटर्न हर खंड के लिए सही है, सामान्यीकरण और औचित्य है, जो बीजीय तर्क की ओर एक महत्त्वपूर्ण कदम है।"},
  {"id":"cdp-pedagogy-subjects-122","question":"A Class 3 child shades one part of a circle divided into four unequal parts and calls it ‘one-fourth’. The child has not yet understood that:","options":["Fractions can only be shown using circles, not other shapes","The parts must be equal for each to be a fourth of the whole","A fraction must always have 1 as its numerator, as in 1/4","Shading must always start from the top part of the circle"],"answer":1,"explanation":"A fraction names one of several equal parts. Folding paper strips into equal and unequal parts and comparing helps children see this.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 3 का एक बच्चा चार असमान भागों में बँटे वृत्त के एक भाग पर रंग भरता है और उसे ‘एक-चौथाई’ कहता है। बच्चे ने अभी यह नहीं समझा है कि:","optionsHi":["भिन्नों को केवल वृत्तों से दिखाया जा सकता है, अन्य आकृतियों से नहीं","भाग बराबर होने चाहिए, तभी प्रत्येक पूरे का चौथाई होगा","भिन्न का अंश हमेशा 1 होना चाहिए, जैसे 1/4","रंग भरना हमेशा वृत्त के ऊपरी भाग से शुरू होना चाहिए"],"explanationHi":"भिन्न कई बराबर भागों में से एक का नाम बताती है। कागज़ की पट्टियों को बराबर और असमान भागों में मोड़ना और तुलना करना बच्चों को यह देखने में मदद करता है।"},
  {"id":"cdp-pedagogy-subjects-123","question":"When the clock shows 3:45, a child reads it as ‘4:45’ because the hour hand is almost at 4. What does the child not yet understand?","options":["How to count minutes in fives around the clock face","That the minute hand is the longer one and shows the minutes passed","How many minutes make one complete hour on a clock","That the hour hand moves slowly between numbers during the hour"],"answer":3,"explanation":"Reading time needs coordinating both hands; using a geared clock to watch the hour hand travel between numbers as the minute hand goes round builds this understanding.","difficulty":"hard","source":"CTET · State TETs","questionHi":"जब घड़ी में 3:45 बजा है, एक बच्चा उसे ‘4:45’ पढ़ता है क्योंकि घंटे की सुई लगभग 4 पर है। बच्चा अभी क्या नहीं समझा है?","optionsHi":["घड़ी के डायल पर पाँच-पाँच करके मिनट कैसे गिने जाते हैं","कि मिनट की सुई लंबी होती है और बीते हुए मिनट दिखाती है","घड़ी में कितने मिनट मिलकर एक पूरा घंटा बनाते हैं","कि घंटे की सुई घंटे के दौरान संख्याओं के बीच धीरे-धीरे चलती है"],"explanationHi":"समय पढ़ने के लिए दोनों सुइयों में समन्वय आवश्यक है; गियर वाली घड़ी से, जिसमें मिनट की सुई के घूमने के साथ घंटे की सुई को संख्याओं के बीच चलते देखा जा सके, यह समझ बनती है।"},
  {"id":"cdp-pedagogy-subjects-124","question":"‘Ram has 5 more marbles than Shyam. Ram has 12 marbles. How many does Shyam have?’ Many children answer 17, explaining ‘more means add’. The best teaching response is to:","options":["Ask children to model the situation with bars, not rely on key words","Give a list of key words for each operation to memorise","Tell children to always subtract in word problems that have two numbers","Avoid such problems because they are confusing for children"],"answer":0,"explanation":"The key-word strategy fails whenever the language is ‘inconsistent’ with the operation. Representing the relationship (Shyam = 12 − 5 = 7) builds real problem comprehension.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"‘राम के पास श्याम से 5 कंचे अधिक हैं। राम के पास 12 कंचे हैं। श्याम के पास कितने हैं?’ कई बच्चे 17 उत्तर देते हैं और कहते हैं ‘अधिक का मतलब जोड़’। सबसे अच्छी शिक्षण-प्रतिक्रिया है:","optionsHi":["बच्चों से स्थिति को पट्टियों (बार) से निरूपित करवाना, कुंजी-शब्दों पर निर्भर न रहना","हर संक्रिया के लिए कुंजी-शब्दों की सूची याद करने को देना","बच्चों से कहना कि दो संख्याओं वाले शब्द-प्रश्नों में हमेशा घटाएँ","ऐसे प्रश्नों से बचना क्योंकि वे बच्चों को भ्रमित करते हैं"],"explanationHi":"कुंजी-शब्द की रणनीति तब विफल हो जाती है जब भाषा संक्रिया से ‘असंगत’ होती है। संबंध को निरूपित करना (श्याम = 12 − 5 = 7) वास्तविक समस्या-बोध का निर्माण करता है।"},
  {"id":"cdp-pedagogy-subjects-125","question":"In mathematics education, a task is a genuine ‘problem’ for a learner (rather than an exercise) when:","options":["It contains large numbers or many steps of calculation","It is taken from the end-of-chapter section of the textbook","The learner does not already know a method and must work one out","It has first been solved by the teacher on the board as a model"],"answer":2,"explanation":"A problem requires the learner to devise an approach; an exercise practises a method already known. The same task can be a problem for one child and an exercise for another.","difficulty":"hard","source":"CTET · State TETs","questionHi":"गणित शिक्षा में कोई कार्य अधिगमकर्ता के लिए वास्तविक ‘समस्या’ (अभ्यास के बजाय) तब होता है जब:","optionsHi":["उसमें बड़ी संख्याएँ या गणना के कई चरण हों","वह पाठ्यपुस्तक के अध्याय-अंत वाले भाग से लिया गया हो","अधिगमकर्ता पहले से कोई विधि न जानता हो और उसे स्वयं कोई विधि निकालनी पड़े","उसे पहले शिक्षक द्वारा श्यामपट्ट पर आदर्श के रूप में हल किया जा चुका हो"],"explanationHi":"समस्या में अधिगमकर्ता को कोई उपागम स्वयं गढ़ना पड़ता है; अभ्यास पहले से ज्ञात विधि का अभ्यास कराता है। एक ही कार्य एक बच्चे के लिए समस्या और दूसरे के लिए अभ्यास हो सकता है।"},
  {"id":"cdp-pedagogy-subjects-126","question":"A Class 6 student checks that 3 + 5, 7 + 9, 11 + 13, 1 + 1 and 15 + 21 are all even, and says she has ‘proved’ that the sum of two odd numbers is always even. The best teacher response is to:","options":["Accept it as a proof, since five varied examples are enough","Tell her the statement is false, as some odd sums are odd","Ask her to test fifty more examples so that the proof becomes complete","Show that examples cannot cover every case and build a general argument"],"answer":3,"explanation":"Examples support a conjecture but cannot cover every case. A general argument (for example 2m + 1 + 2n + 1 = 2(m + n + 1)) shows why it must always hold, introducing children to mathematical proof.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 6 की एक छात्रा जाँचती है कि 3 + 5, 7 + 9, 11 + 13, 1 + 1 और 15 + 21 सभी सम हैं, और कहती है कि उसने ‘सिद्ध’ कर दिया है कि दो विषम संख्याओं का योग हमेशा सम होता है। शिक्षक की सबसे अच्छी प्रतिक्रिया है:","optionsHi":["इसे उपपत्ति मान लेना, क्योंकि पाँच विविध उदाहरण पर्याप्त हैं","उसे बताना कि कथन गलत है, क्योंकि कुछ विषम योग विषम होते हैं","उससे पचास और उदाहरण जाँचने को कहना ताकि उपपत्ति पूरी हो जाए","दिखाना कि उदाहरण हर स्थिति को कवर नहीं कर सकते, और एक सामान्य तर्क बनाना"],"explanationHi":"उदाहरण किसी अनुमान का समर्थन करते हैं, लेकिन हर स्थिति को कवर नहीं कर सकते। एक सामान्य तर्क (उदाहरण के लिए 2m + 1 + 2n + 1 = 2(m + n + 1)) दिखाता है कि यह हमेशा क्यों सही होना चाहिए, और बच्चों को गणितीय उपपत्ति से परिचित कराता है।"},
  {"id":"cdp-pedagogy-subjects-127","question":"A Class 5 student who is blind is learning about shapes and number operations in an inclusive class. Which resources are most suitable?","options":["Coloured charts and printed worksheets in a large font","Tactile shapes, geoboards and an abacus, with written work read aloud","Asking a classmate to do all the written work on her behalf","Exempting her from geometry, since the topic is mainly visual in nature"],"answer":1,"explanation":"Tactile materials and an abacus give access to geometry and calculation; exemption or having others do the work denies her the learning the RPwD Act aims to secure.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 5 की एक नेत्रहीन छात्रा समावेशी कक्षा में आकृतियों और संख्या-संक्रियाओं के बारे में सीख रही है। कौन-से संसाधन सबसे उपयुक्त हैं?","optionsHi":["रंगीन चार्ट और बड़े अक्षरों वाले छपे अभ्यास-पत्र","स्पर्श-योग्य आकृतियाँ, जियोबोर्ड और अबेकस, तथा लिखित कार्य को ज़ोर से पढ़कर सुनाना","एक सहपाठी से उसकी ओर से सारा लिखित कार्य करवाना","उसे ज्यामिति से छूट देना, क्योंकि यह विषय मुख्यतः दृश्य प्रकृति का है"],"explanationHi":"स्पर्श-योग्य सामग्री और अबेकस ज्यामिति और गणना तक पहुँच देते हैं; छूट देना या दूसरों से कार्य करवाना उसे उस अधिगम से वंचित करता है जिसे RPwD अधिनियम सुनिश्चित करना चाहता है।"},
  {"id":"cdp-pedagogy-subjects-128","question":"Which practice is most likely to REDUCE mathematics anxiety among children?","options":["Daily timed tests with the results read out in class","Insisting on one ‘correct’ method so children are not confused","Valuing varied methods and treating errors as part of learning","Making slow children stand until they answer correctly"],"answer":2,"explanation":"Fear of public failure and speed pressure feed maths anxiety; an environment that values reasoning over speed and accepts multiple methods reduces it, as NCF 2005 urges.","difficulty":"hard","source":"CTET · State TETs","questionHi":"बच्चों में गणित-चिंता को कम करने की सबसे अधिक संभावना किस अभ्यास में है?","optionsHi":["हर दिन समयबद्ध परीक्षाएँ, जिनके परिणाम कक्षा में पढ़कर सुनाए जाएँ","एक ही ‘सही’ विधि पर ज़ोर देना ताकि बच्चे भ्रमित न हों","विविध विधियों को महत्त्व देना और त्रुटियों को अधिगम का भाग मानना","धीमे बच्चों को तब तक खड़ा रखना जब तक वे सही उत्तर न दें"],"explanationHi":"सार्वजनिक रूप से असफल होने का भय और गति का दबाव गणित-चिंता को बढ़ाते हैं; जो वातावरण गति से अधिक तर्क को महत्त्व देता है और कई विधियों को स्वीकार करता है, वह इसे कम करता है, जैसा NCF 2005 आग्रह करता है।"},
  {"id":"cdp-pedagogy-subjects-129","question":"Asked, ‘What is the difference between 15 and 9?’, a child says, ‘15 has a 1 and 5, and 9 has only one digit.’ The teacher should recognise that:","options":["The child lacks number knowledge and must go back to counting","The child is being deliberately cheeky to the teacher","The question is too difficult for children at the primary level","The child is using the everyday meaning of the word ‘difference’"],"answer":3,"explanation":"Words such as difference, product, table and volume have different everyday meanings. Making the mathematical meaning explicit is part of developing the language of mathematics.","difficulty":"hard","source":"CTET · State TETs","questionHi":"‘15 और 9 में अंतर क्या है?’ पूछे जाने पर एक बच्चा कहता है, ‘15 में 1 और 5 हैं, और 9 में केवल एक अंक है।’ शिक्षक को यह पहचानना चाहिए कि:","optionsHi":["बच्चे में संख्या-ज्ञान की कमी है और उसे गिनती पर वापस जाना चाहिए","बच्चा जानबूझकर शिक्षक से ढिठाई कर रहा है","प्राथमिक स्तर के बच्चों के लिए प्रश्न बहुत कठिन है","बच्चा ‘अंतर’ शब्द के दैनिक जीवन के अर्थ का उपयोग कर रहा है"],"explanationHi":"अंतर, गुणनफल, तालिका और आयतन जैसे शब्दों के दैनिक जीवन में अलग अर्थ होते हैं। गणितीय अर्थ को स्पष्ट करना गणित की भाषा के विकास का भाग है।"},
  {"id":"cdp-pedagogy-subjects-130","question":"During an EVS lesson on families, a Class 3 child says, ‘I live only with my mother and grandmother.’ Some classmates laugh. The most appropriate response of the teacher is to:","options":["Tell the class that a ‘proper’ family has a father, mother and children","Ignore the remark and continue with the textbook picture of a family","Ask the child to sit quietly so that she is not embarrassed further","Discuss how families differ, inviting children to share without judgement"],"answer":3,"explanation":"EVS aims to help children appreciate diversity in families and lifestyles; building on the child’s experience respectfully counters stereotypes and teasing.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"परिवारों पर EVS के पाठ के दौरान कक्षा 3 की एक बच्ची कहती है, ‘मैं केवल अपनी माँ और दादी के साथ रहती हूँ।’ कुछ सहपाठी हँसते हैं। शिक्षक की सबसे उपयुक्त प्रतिक्रिया है:","optionsHi":["कक्षा को बताना कि ‘उचित’ परिवार में पिता, माता और बच्चे होते हैं","टिप्पणी को अनदेखा करके परिवार के पाठ्यपुस्तक वाले चित्र के साथ आगे बढ़ना","बच्ची से चुपचाप बैठने को कहना ताकि वह और शर्मिंदा न हो","इस पर चर्चा करना कि परिवार कैसे अलग-अलग होते हैं, और बच्चों को बिना किसी निर्णय के अपनी बात साझा करने के लिए आमंत्रित करना"],"explanationHi":"EVS का उद्देश्य बच्चों को परिवारों और जीवन-शैलियों की विविधता की सराहना करने में मदद करना है; बच्ची के अनुभव का सम्मानपूर्वक उपयोग करना रूढ़िबद्ध धारणाओं और चिढ़ाने का प्रतिकार करता है।"},
  {"id":"cdp-pedagogy-subjects-131","question":"Many questions in the NCERT EVS books (‘Have you ever seen…?’, ‘What do people in your family do when…?’) have no answer printed in the chapter. The main reason is that:","options":["The answers were left out to keep the books short and light","They draw on children’s own experiences, so many answers can be right","Children are expected to find the single correct answer from a guidebook","Teachers are expected to dictate model answers for children to memorise"],"answer":1,"explanation":"The books treat children as sources of knowledge; open questions link EVS to the child’s life and require teachers to accept varied responses rather than one ‘right’ answer.","difficulty":"hard","source":"CTET · State TETs","questionHi":"NCERT EVS पुस्तकों के कई प्रश्नों (‘क्या आपने कभी देखा है…?’, ‘आपके परिवार के लोग क्या करते हैं जब…?’) का उत्तर अध्याय में छपा नहीं होता। इसका मुख्य कारण यह है कि:","optionsHi":["पुस्तकों को छोटा और हल्का रखने के लिए उत्तर छोड़ दिए गए","वे बच्चों के अपने अनुभवों पर आधारित हैं, इसलिए कई उत्तर सही हो सकते हैं","बच्चों से अपेक्षा है कि वे गाइड-पुस्तक से एकमात्र सही उत्तर ढूँढ़ें","शिक्षकों से अपेक्षा है कि वे आदर्श उत्तर लिखवाएँ ताकि बच्चे उन्हें याद करें"],"explanationHi":"पुस्तकें बच्चों को ज्ञान का स्रोत मानती हैं; खुले प्रश्न EVS को बच्चे के जीवन से जोड़ते हैं और शिक्षकों से अपेक्षा करते हैं कि वे एक ‘सही’ उत्तर के बजाय विविध प्रतिक्रियाएँ स्वीकार करें।"},
  {"id":"cdp-pedagogy-subjects-132","question":"In an EVS activity, children collect leaves and group them by shape, edge and texture, explaining their groups. Which NCERT indicator of EVS learning is mainly being assessed?","options":["Classification","Concern for justice and equality","Experimentation","Cooperation"],"answer":0,"explanation":"Grouping objects by observed features and explaining the basis of grouping is the indicator ‘classification’; it also draws on observation.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक EVS गतिविधि में बच्चे पत्तियाँ इकट्ठा करके उन्हें आकार, किनारे और बनावट के आधार पर समूहों में बाँटते हैं और अपने समूहों को समझाते हैं। EVS अधिगम के किस NCERT संकेतक का मुख्य रूप से आकलन हो रहा है?","optionsHi":["वर्गीकरण","न्याय और समानता के प्रति सरोकार","प्रयोग","सहयोग"],"explanationHi":"देखी गई विशेषताओं के आधार पर वस्तुओं को समूहों में बाँटना और समूहन का आधार समझाना ‘वर्गीकरण’ संकेतक है; इसमें अवलोकन भी शामिल है।"},
  {"id":"cdp-pedagogy-subjects-133","question":"Match the EVS classroom behaviour with the NCERT learning indicator it best shows: 1. A child asks, ‘Why do some birds have long, thin beaks?’ 2. A child objects that a chapter’s story treats a girl unfairly. 3. A child tries soaking seeds in different amounts of water to see what happens. 4. A child explains in her own words why clothes dry faster on a windy day; a. Explanation b. Experimentation c. Concern for justice and equality d. Questioning","options":["1-d, 2-c, 3-b, 4-a","1-a, 2-c, 3-b, 4-d","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-a, 4-b"],"answer":0,"explanation":"Asking ‘why’ is questioning, objecting to unfair treatment shows concern for justice and equality, trying out conditions is experimentation, and accounting for a phenomenon in one’s words is explanation.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"EVS की कक्षा के व्यवहार का उस NCERT अधिगम संकेतक से मिलान कीजिए जिसे वह सबसे अच्छा दर्शाता है: 1. एक बच्चा पूछता है, ‘कुछ पक्षियों की चोंच लंबी और पतली क्यों होती है?’ 2. एक बच्चा आपत्ति करता है कि किसी अध्याय की कहानी में एक लड़की के साथ अन्याय हुआ है। 3. एक बच्चा बीजों को अलग-अलग मात्रा के पानी में भिगोकर देखता है कि क्या होता है। 4. एक बच्ची अपने शब्दों में समझाती है कि हवा वाले दिन कपड़े जल्दी क्यों सूखते हैं; a. व्याख्या b. प्रयोग c. न्याय और समानता के प्रति सरोकार d. प्रश्न पूछना","optionsHi":["1-d, 2-c, 3-b, 4-a","1-a, 2-c, 3-b, 4-d","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-a, 4-b"],"explanationHi":"‘क्यों’ पूछना प्रश्न पूछना है, अनुचित व्यवहार पर आपत्ति न्याय और समानता के प्रति सरोकार दिखाती है, परिस्थितियों को आज़माना प्रयोग है, और किसी परिघटना का अपने शब्दों में कारण बताना व्याख्या है।"},
  {"id":"cdp-pedagogy-subjects-134","question":"A teacher holds up a cricket ball and a tennis ball and asks, ‘If I drop them together from this height, which will land first? Write down your guess and why.’ She then drops them, and the class discusses why the result differed from many predictions. This strategy is called:","options":["Concept mapping exercise","Brainstorming session","Predict–Observe–Explain","Programmed instruction"],"answer":2,"explanation":"POE makes children commit to a prediction, which brings out their ideas (heavier falls faster), then uses observation and discussion to challenge and reconstruct them.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"एक शिक्षिका क्रिकेट की गेंद और टेनिस की गेंद ऊपर उठाकर पूछती है, ‘यदि मैं इन्हें इस ऊँचाई से एक साथ गिराऊँ, तो कौन-सी पहले ज़मीन पर पहुँचेगी? अपना अनुमान और कारण लिखिए।’ फिर वह उन्हें गिराती है, और कक्षा इस पर चर्चा करती है कि परिणाम कई पूर्वानुमानों से अलग क्यों रहा। इस युक्ति को क्या कहते हैं?","optionsHi":["संप्रत्यय मानचित्रण अभ्यास","विचार-मंथन सत्र","पूर्वानुमान–अवलोकन–व्याख्या (Predict–Observe–Explain)","क्रमादेशित अनुदेशन"],"explanationHi":"POE में बच्चे किसी पूर्वानुमान पर प्रतिबद्ध होते हैं, जिससे उनके विचार (भारी चीज़ तेज़ गिरती है) सामने आते हैं; फिर अवलोकन और चर्चा के माध्यम से उन्हें चुनौती देकर पुनर्निर्मित किया जाता है।"},
  {"id":"cdp-pedagogy-subjects-135","question":"A Class 7 student explains that it is winter in December ‘because the earth is then farthest from the sun’. Which piece of evidence would best challenge this idea?","options":["The earth moves in an orbit around the sun, taking one year","When India has winter, Australia has summer","The sun appears smaller and paler in the sky during winter","Days are shorter and nights are longer in India during winter"],"answer":1,"explanation":"If distance caused seasons, both hemispheres would have the same season at once. Opposite seasons in the two hemispheres point to the tilt of the earth’s axis as the cause.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 7 का एक विद्यार्थी समझाता है कि दिसंबर में सर्दी ‘इसलिए होती है क्योंकि तब पृथ्वी सूर्य से सबसे दूर होती है’। कौन-सा प्रमाण इस विचार को सबसे अच्छी तरह चुनौती देगा?","optionsHi":["पृथ्वी सूर्य के चारों ओर कक्षा में घूमती है, जिसमें एक वर्ष लगता है","जब भारत में सर्दी होती है, तब ऑस्ट्रेलिया में गर्मी होती है","सर्दियों में आकाश में सूर्य छोटा और फीका दिखाई देता है","भारत में सर्दियों में दिन छोटे और रातें लंबी होती हैं"],"explanationHi":"यदि दूरी से मौसम बनते, तो दोनों गोलार्धों में एक साथ एक ही मौसम होता। दोनों गोलार्धों में विपरीत मौसम इस बात का संकेत देते हैं कि कारण पृथ्वी के अक्ष का झुकाव है।"},
  {"id":"cdp-pedagogy-subjects-136","question":"A Class 4 child says, ‘A bus is living because it moves, but a tree is not living because it does not move.’ Which teaching approach best addresses this idea?","options":["Make the child memorise the definition of a living thing","Tell the child that only animals and humans are living things","Show a video of a moving bus and a still tree for comparison","Apply several life features, like growth, to the tree and the bus"],"answer":3,"explanation":"The child is using one feature (movement) as the test of life. Considering several characteristics together lets children see why a tree is living and a bus is not.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 4 का एक बच्चा कहता है, ‘बस सजीव है क्योंकि वह चलती है, लेकिन पेड़ सजीव नहीं है क्योंकि वह चलता नहीं।’ कौन-सा शिक्षण उपागम इस विचार का सबसे अच्छा समाधान करता है?","optionsHi":["बच्चे से सजीव की परिभाषा याद करवाना","बच्चे को बताना कि केवल पशु और मनुष्य ही सजीव होते हैं","तुलना के लिए चलती बस और स्थिर पेड़ का वीडियो दिखाना","पेड़ और बस, दोनों पर वृद्धि जैसे सजीवता के कई लक्षण लागू करना"],"explanationHi":"बच्चा जीवन की जाँच के लिए एक ही लक्षण (गति) का उपयोग कर रहा है। कई लक्षणों पर एक साथ विचार करने से बच्चे देख पाते हैं कि पेड़ सजीव क्यों है और बस क्यों नहीं।"},
  {"id":"cdp-pedagogy-subjects-137","question":"To find out whether seeds need water to sprout, a child puts seeds on wet cotton in one bowl and on dry sand in another. The main flaw in this test is that:","options":["Water and the material were both changed, so water alone is not tested","Seeds should be planted in a pot of soil, not in a bowl","Only one bowl should have been used, with more seeds placed in it together","The child should have used a microscope to watch the seeds"],"answer":0,"explanation":"A fair test changes only the factor under study and keeps everything else the same; here cotton should be used in both bowls, one wet and one dry.","difficulty":"hard","source":"CTET · State TETs","questionHi":"यह पता लगाने के लिए कि बीजों को अंकुरित होने के लिए पानी चाहिए या नहीं, एक बच्चा बीजों को एक कटोरे में गीली रुई पर और दूसरे में सूखी रेत पर रखता है। इस परीक्षण की मुख्य कमी यह है कि:","optionsHi":["पानी और सामग्री दोनों बदल दिए गए, इसलिए केवल पानी का परीक्षण नहीं हुआ","बीजों को कटोरे में नहीं, मिट्टी के गमले में बोना चाहिए था","केवल एक कटोरा उपयोग करना चाहिए था, जिसमें अधिक बीज एक साथ रखे जाते","बच्चे को बीजों को देखने के लिए सूक्ष्मदर्शी का उपयोग करना चाहिए था"],"explanationHi":"निष्पक्ष परीक्षण में केवल अध्ययन किए जा रहे कारक को बदला जाता है और बाकी सब कुछ समान रखा जाता है; यहाँ दोनों कटोरों में रुई का उपयोग होना चाहिए था, एक गीली और एक सूखी।"},
  {"id":"cdp-pedagogy-subjects-138","question":"Class 8 students decide on their own question (‘Does the colour of a cloth affect how fast it dries?’), plan their own method, collect data and present conclusions, with the teacher only facilitating. This is best described as:","options":["Confirmation inquiry","Structured inquiry","Open inquiry","Teacher demonstration"],"answer":2,"explanation":"In open inquiry students frame the question and design the investigation themselves. In structured inquiry the teacher gives the question and procedure, and in confirmation inquiry students verify a known result.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 8 के विद्यार्थी अपना प्रश्न स्वयं तय करते हैं (‘क्या कपड़े का रंग उसके सूखने की गति को प्रभावित करता है?’), अपनी विधि स्वयं बनाते हैं, आँकड़े इकट्ठा करते हैं और निष्कर्ष प्रस्तुत करते हैं, जबकि शिक्षक केवल सुगमकर्ता है। इसका सबसे अच्छा वर्णन है:","optionsHi":["पुष्टिकारक अन्वेषण","संरचित अन्वेषण","मुक्त अन्वेषण","शिक्षक प्रदर्शन"],"explanationHi":"मुक्त अन्वेषण में विद्यार्थी स्वयं प्रश्न बनाते हैं और अन्वेषण की रूपरेखा तैयार करते हैं। संरचित अन्वेषण में शिक्षक प्रश्न और प्रक्रिया देता है, और पुष्टिकारक अन्वेषण में विद्यार्थी किसी ज्ञात परिणाम का सत्यापन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-139","question":"The NCF 2005 position paper on science lists criteria a good science curriculum must meet. Including the story of how scientific ideas changed over time, such as the shift from an earth-centred to a sun-centred view, mainly serves:","options":["Cognitive validity","Ethical validity","Environmental validity","Historical validity"],"answer":3,"explanation":"Historical validity means the curriculum shows how science developed and changed, showing it as a social enterprise. The other criteria are cognitive, content, process, environmental and ethical validity.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"विज्ञान पर NCF 2005 का पोज़ीशन पेपर उन मानदंडों को सूचीबद्ध करता है जिन्हें एक अच्छे विज्ञान पाठ्यक्रम को पूरा करना चाहिए। वैज्ञानिक विचारों के समय के साथ बदलने की कहानी को शामिल करना, जैसे पृथ्वी-केंद्रित से सूर्य-केंद्रित दृष्टिकोण की ओर बदलाव, मुख्य रूप से किसकी पूर्ति करता है?","optionsHi":["संज्ञानात्मक वैधता","नैतिक वैधता","पर्यावरणीय वैधता","ऐतिहासिक वैधता"],"explanationHi":"ऐतिहासिक वैधता का अर्थ है कि पाठ्यक्रम दिखाए कि विज्ञान कैसे विकसित हुआ और बदला, और उसे एक सामाजिक उद्यम के रूप में प्रस्तुत करे। अन्य मानदंड संज्ञानात्मक, विषय-वस्तु, प्रक्रिया, पर्यावरणीय और नैतिक वैधता हैं।"},
  {"id":"cdp-pedagogy-subjects-140","question":"Under the NCF 2005 science criteria, a curriculum has ‘process validity’ when it:","options":["Is suited to the age and cognitive level of the learners","Engages learners in the methods by which science builds knowledge","Presents scientifically correct and significant content","Promotes values of honesty, objectivity and a concern for all forms of life"],"answer":1,"explanation":"Process validity concerns learning how scientific knowledge is generated, through observation, experiment and reasoning. The other options describe cognitive, content and ethical validity.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"NCF 2005 के विज्ञान मानदंडों के अंतर्गत, पाठ्यक्रम में ‘प्रक्रिया वैधता’ तब होती है जब वह:","optionsHi":["अधिगमकर्ताओं की आयु और संज्ञानात्मक स्तर के अनुकूल हो","अधिगमकर्ताओं को उन विधियों में संलग्न करे जिनसे विज्ञान ज्ञान का निर्माण करता है","वैज्ञानिक रूप से सही और महत्त्वपूर्ण विषय-वस्तु प्रस्तुत करे","ईमानदारी, वस्तुनिष्ठता और सभी जीव-रूपों के प्रति सरोकार के मूल्यों को बढ़ावा दे"],"explanationHi":"प्रक्रिया वैधता का संबंध इस सीखने से है कि वैज्ञानिक ज्ञान कैसे उत्पन्न होता है: अवलोकन, प्रयोग और तर्क के माध्यम से। अन्य विकल्प संज्ञानात्मक, विषय-वस्तु और नैतिक वैधता का वर्णन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-141","question":"Class 5 children interview their grandparents about where the family got drinking water fifty years ago and compare it with today. The main learning purpose of this activity in EVS is to help children:","options":["Understand change over time and link it with people’s lives","Improve their handwriting through careful note-taking","Memorise the names of different old and new water sources","Learn that old practices were always better than new ones"],"answer":0,"explanation":"Oral history surveys link the present to the past and show how environment and society shape each other, an integrated EVS aim; they also develop questioning and recording skills.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 5 के बच्चे अपने दादा-दादी का साक्षात्कार लेते हैं कि पचास वर्ष पहले परिवार को पीने का पानी कहाँ से मिलता था, और उसकी आज से तुलना करते हैं। EVS में इस गतिविधि का मुख्य अधिगम-उद्देश्य बच्चों की किसमें सहायता करना है?","optionsHi":["समय के साथ परिवर्तन को समझना और उसे लोगों के जीवन से जोड़ना","ध्यानपूर्वक नोट्स लेने से अपनी हस्तलिपि सुधारना","पानी के पुराने और नए स्रोतों के नाम याद करना","यह सीखना कि पुरानी प्रथाएँ हमेशा नई प्रथाओं से बेहतर थीं"],"explanationHi":"मौखिक इतिहास के सर्वेक्षण वर्तमान को अतीत से जोड़ते हैं और दिखाते हैं कि पर्यावरण और समाज एक-दूसरे को कैसे आकार देते हैं, जो एक एकीकृत EVS उद्देश्य है; ये प्रश्न पूछने और अभिलेखन के कौशल भी विकसित करते हैं।"},
  {"id":"cdp-pedagogy-subjects-142","question":"Children draw a map of their route from home to school, marking landmarks such as a temple, a shop and a pond. This activity mainly helps them to:","options":["Learn the scale and projection used in standard printed maps","Memorise the names of shops and buildings on the way","Develop a sense of space and direction, the basis of map reading","Improve their drawing and colouring as an art activity"],"answer":2,"explanation":"Drawing familiar routes builds spatial understanding, perspective and the use of symbols, the foundation of mapping skills developed later in EVS.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"बच्चे घर से विद्यालय के अपने रास्ते का नक्शा बनाते हैं, जिसमें मंदिर, दुकान और तालाब जैसे चिह्न अंकित करते हैं। यह गतिविधि मुख्य रूप से उन्हें किसमें सहायता करती है?","optionsHi":["मानक छपे नक्शों में उपयोग होने वाला पैमाना और प्रक्षेपण सीखना","रास्ते की दुकानों और इमारतों के नाम याद करना","स्थान और दिशा की समझ विकसित करना, जो नक्शा पढ़ने का आधार है","कला-गतिविधि के रूप में अपनी चित्रकारी और रंग भरना सुधारना"],"explanationHi":"परिचित रास्तों को बनाने से स्थानिक समझ, परिप्रेक्ष्य और प्रतीकों का उपयोग विकसित होता है, जो बाद में EVS में विकसित होने वाले मानचित्र-कौशलों की नींव है।"},
  {"id":"cdp-pedagogy-subjects-143","question":"A teacher fills her science periods with activities: children float objects, mix colours and grow seeds, but she moves straight on to the next activity without any discussion. What is most clearly missing?","options":["More activities, so that children are kept busy and interested","A written test after every activity to check the facts","Strict silence during the activities so children concentrate","Discussion that helps children make sense of what they observed"],"answer":3,"explanation":"Activities lead to learning only when children are helped to think about what happened, explain it and connect it to concepts; activity alone does not build understanding.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"एक शिक्षिका अपने विज्ञान के कालांशों को गतिविधियों से भर देती है: बच्चे वस्तुओं को तैराते हैं, रंग मिलाते हैं और बीज उगाते हैं, लेकिन वह बिना किसी चर्चा के सीधे अगली गतिविधि पर चली जाती है। सबसे स्पष्ट रूप से क्या कमी है?","optionsHi":["और अधिक गतिविधियाँ, ताकि बच्चे व्यस्त और रुचि में बने रहें","तथ्यों की जाँच के लिए हर गतिविधि के बाद लिखित परीक्षा","गतिविधियों के दौरान कड़ी चुप्पी, ताकि बच्चे ध्यान लगाएँ","ऐसी चर्चा जो बच्चों को उनके देखे हुए का अर्थ समझने में मदद करे"],"explanationHi":"गतिविधियाँ तभी अधिगम तक ले जाती हैं जब बच्चों को यह सोचने में मदद की जाए कि क्या हुआ, उसे समझाने और अवधारणाओं से जोड़ने में सहायता मिले; केवल गतिविधि से समझ नहीं बनती।"},
  {"id":"cdp-pedagogy-subjects-144","question":"In a school without a science laboratory, a teacher uses plastic bottles, straws, balloons and old cells to teach ideas about air pressure and electricity. This practice is best described as:","options":["Poor teaching, because real laboratory apparatus is always needed","Improvisation with low-cost local materials, as NCF 2005 urges","A waste of class time that should go to the textbook","Suitable only for children who cannot afford books"],"answer":1,"explanation":"Low-cost, improvised materials make hands-on science possible everywhere and help children see science in everyday objects.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"विज्ञान प्रयोगशाला के बिना एक विद्यालय में एक शिक्षक वायु दाब और विद्युत के विचार सिखाने के लिए प्लास्टिक की बोतलों, स्ट्रॉ, गुब्बारों और पुराने सेलों का उपयोग करता है। इस अभ्यास का सबसे अच्छा वर्णन है:","optionsHi":["खराब शिक्षण, क्योंकि वास्तविक प्रयोगशाला उपकरण हमेशा आवश्यक होते हैं","कम लागत की स्थानीय सामग्रियों से जुगाड़, जैसा NCF 2005 आग्रह करता है","कक्षा के समय की बर्बादी, जो पाठ्यपुस्तक को दिया जाना चाहिए","केवल उन बच्चों के लिए उपयुक्त जो पुस्तकें नहीं खरीद सकते"],"explanationHi":"कम लागत की, जुगाड़ से बनी सामग्री हर जगह हाथों से करके विज्ञान सीखना संभव बनाती है और बच्चों को रोज़मर्रा की वस्तुओं में विज्ञान देखने में मदद करती है।"},
  {"id":"cdp-pedagogy-subjects-145","question":"To explain an electric circuit, a teacher compares electric current to water flowing in pipes. Which follow-up best uses this analogy responsibly?","options":["Discussing where the analogy works and where it breaks down","Avoiding analogies altogether, since they always cause misconceptions","Telling children that electricity is a kind of water","Using the analogy only in tests and not in teaching"],"answer":0,"explanation":"Analogies help children grasp abstract ideas, but learners can transfer irrelevant features; making the limits explicit prevents new misconceptions.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"विद्युत परिपथ को समझाने के लिए एक शिक्षक विद्युत धारा की तुलना पाइपों में बहते पानी से करता है। कौन-सा अनुवर्ती कार्य इस सादृश्य (एनालॉजी) का सबसे ज़िम्मेदारी से उपयोग करता है?","optionsHi":["इस पर चर्चा करना कि सादृश्य कहाँ ठीक बैठता है और कहाँ विफल हो जाता है","सादृश्यों से पूरी तरह बचना, क्योंकि वे हमेशा भ्रांत धारणाएँ पैदा करते हैं","बच्चों को बताना कि बिजली एक प्रकार का पानी है","सादृश्य का उपयोग केवल परीक्षाओं में करना, शिक्षण में नहीं"],"explanationHi":"सादृश्य बच्चों को अमूर्त विचार समझने में मदद करते हैं, लेकिन अधिगमकर्ता अप्रासंगिक विशेषताएँ भी स्थानांतरित कर सकते हैं; सीमाओं को स्पष्ट करना नई भ्रांत धारणाओं को रोकता है।"},
  {"id":"cdp-pedagogy-subjects-146","question":"A teacher shows a cartoon in which three children give different views about why a snowman wrapped in a coat will melt faster, slower or at the same rate, and asks the class whom they agree with and why. The main purpose of such a concept cartoon is to:","options":["Entertain children before the real lesson begins","Test whether children can read and understand speech bubbles","Draw out children’s ideas and get them to argue and test them","Give the correct answer in an attractive, memorable form"],"answer":2,"explanation":"Concept cartoons present competing ideas, including common misconceptions, to provoke discussion and investigation (here, a coat insulates and slows melting).","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"एक शिक्षक एक कार्टून दिखाता है जिसमें तीन बच्चे इस बारे में अलग-अलग राय देते हैं कि कोट पहनाया गया स्नोमैन तेज़, धीमे या उसी गति से पिघलेगा, और कक्षा से पूछता है कि वे किससे सहमत हैं और क्यों। ऐसे संप्रत्यय कार्टून (कॉन्सेप्ट कार्टून) का मुख्य उद्देश्य है:","optionsHi":["असली पाठ शुरू होने से पहले बच्चों का मनोरंजन करना","यह जाँचना कि बच्चे संवाद-बुलबुले पढ़-समझ सकते हैं या नहीं","बच्चों के विचारों को सामने लाना और उन्हें तर्क करने तथा परखने के लिए प्रेरित करना","सही उत्तर को आकर्षक, यादगार रूप में देना"],"explanationHi":"संप्रत्यय कार्टून परस्पर विरोधी विचार, सामान्य भ्रांत धारणाओं सहित, प्रस्तुत करते हैं ताकि चर्चा और अन्वेषण को प्रेरित किया जा सके (यहाँ, कोट रोधन करता है और पिघलने को धीमा करता है)।"},
  {"id":"cdp-pedagogy-subjects-147","question":"An EVS discussion asks who in the neighbourhood cleans drains and collects garbage, how they are treated, and how the children would feel doing that work. The main aim of such a discussion is to:","options":["Teach children the correct steps of cleaning a drain safely","Discourage children from keeping their surroundings clean","Show that such work belongs to particular communities by tradition","Sensitise children to the dignity of labour and inequities in work"],"answer":3,"explanation":"EVS includes the social environment; examining who does what work and how they are treated promotes empathy, equality and respect for labour.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक EVS चर्चा में पूछा जाता है कि पड़ोस में नालियाँ कौन साफ़ करता है और कचरा कौन इकट्ठा करता है, उनके साथ कैसा व्यवहार किया जाता है, और बच्चों को वह काम करना कैसा लगेगा। ऐसी चर्चा का मुख्य उद्देश्य है:","optionsHi":["बच्चों को नाली को सुरक्षित ढंग से साफ़ करने के सही चरण सिखाना","बच्चों को अपने परिवेश को साफ़ रखने से हतोत्साहित करना","यह दिखाना कि ऐसा काम परंपरा से कुछ विशेष समुदायों का है","बच्चों को श्रम की गरिमा और काम में असमानताओं के प्रति संवेदनशील बनाना"],"explanationHi":"EVS में सामाजिक पर्यावरण शामिल है; यह जाँचना कि कौन-सा काम कौन करता है और उनके साथ कैसा व्यवहार होता है, सहानुभूति, समानता और श्रम के प्रति सम्मान को बढ़ावा देता है।"},
  {"id":"cdp-pedagogy-subjects-148","question":"A Class 3 child who cannot yet write well draws a detailed picture of how her family stores water at home and explains it orally. As an EVS assessment, the teacher should:","options":["Give no marks, because nothing has been written down","Accept the drawing and explanation as valid evidence of learning","Ask her to copy a written answer from the board instead","Mark her down for not using the textbook answer and its exact words"],"answer":1,"explanation":"Assessment in EVS should allow varied forms of expression; drawing and speaking are valid ways to show observation and understanding, especially in early grades.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 3 की एक बच्ची, जो अभी अच्छा लिख नहीं पाती, अपने परिवार द्वारा घर में पानी संग्रहित करने के तरीके का विस्तृत चित्र बनाती है और उसे मौखिक रूप से समझाती है। EVS आकलन के रूप में शिक्षक को चाहिए कि:","optionsHi":["कोई अंक न दे, क्योंकि कुछ लिखा नहीं गया है","चित्र और स्पष्टीकरण को अधिगम के वैध प्रमाण के रूप में स्वीकार करे","इसके बजाय उससे श्यामपट्ट से लिखित उत्तर उतारने को कहे","पाठ्यपुस्तक के उत्तर और उसके सटीक शब्दों का उपयोग न करने पर उसके अंक काटे"],"explanationHi":"EVS में आकलन को अभिव्यक्ति के विविध रूपों की अनुमति देनी चाहिए; चित्र बनाना और बोलना अवलोकन और समझ दिखाने के वैध तरीके हैं, विशेषकर प्रारंभिक कक्षाओं में।"},
  {"id":"cdp-pedagogy-subjects-149","question":"Class 6 students can recite that ‘photosynthesis is the process by which green plants make food using sunlight’, but cannot explain why a plant kept in a dark cupboard for a week has become pale and weak. This shows that their learning is mainly:","options":["Rote, without understanding that applies to new situations","Conceptual, because they can state the definition accurately","Experiential, since they have seen plants growing at home","Complete, as the definition they recite is correct"],"answer":0,"explanation":"Applying an idea to explain a new situation is a test of understanding; reproducing a definition shows only memorisation.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 6 के विद्यार्थी रटकर बोल सकते हैं कि ‘प्रकाश संश्लेषण वह प्रक्रिया है जिसके द्वारा हरे पौधे सूर्य के प्रकाश से भोजन बनाते हैं’, लेकिन यह नहीं समझा सकते कि एक सप्ताह तक अँधेरी अलमारी में रखा पौधा पीला और कमज़ोर क्यों हो गया है। इससे पता चलता है कि उनका अधिगम मुख्यतः है:","optionsHi":["रटा हुआ, ऐसी समझ के बिना जो नई स्थितियों में लागू हो","अवधारणात्मक, क्योंकि वे परिभाषा सटीक बता सकते हैं","अनुभवजन्य, क्योंकि उन्होंने घर पर पौधों को उगते देखा है","पूर्ण, क्योंकि वे जो परिभाषा सुनाते हैं वह सही है"],"explanationHi":"किसी नई स्थिति को समझाने के लिए किसी विचार को लागू करना समझ की कसौटी है; परिभाषा दोहराना केवल याद करना दर्शाता है।"},
  {"id":"cdp-pedagogy-subjects-150","question":"Which behaviour of a student best shows a scientific attitude?","options":["Changing her readings so that they match the textbook value","Accepting a claim because it was made by an elder or a book","Recording a surprising result honestly and repeating the test","Refusing to consider a classmate’s explanation that differs from hers"],"answer":2,"explanation":"Honesty in recording data, scepticism and willingness to check results are the core of scientific attitude; fudging data or accepting authority uncritically are not.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"किसी विद्यार्थी का कौन-सा व्यवहार वैज्ञानिक दृष्टिकोण को सबसे अच्छी तरह दर्शाता है?","optionsHi":["अपनी रीडिंग बदल देना ताकि वे पाठ्यपुस्तक के मान से मेल खाएँ","किसी दावे को इसलिए मान लेना कि वह किसी बड़े या किसी पुस्तक ने किया है","किसी आश्चर्यजनक परिणाम को ईमानदारी से दर्ज करना और परीक्षण दोहराना","किसी सहपाठी के अलग स्पष्टीकरण पर विचार करने से इनकार करना"],"explanationHi":"आँकड़े दर्ज करने में ईमानदारी, संशयशीलता और परिणामों की जाँच करने की इच्छा वैज्ञानिक दृष्टिकोण का मूल है; आँकड़ों में हेरफेर करना या सत्ता को बिना आलोचना के मान लेना नहीं।"},
  {"id":"cdp-pedagogy-subjects-151","question":"Asked to group pictures of 12 animals, one group sorts by ‘lives on land / in water’, another by ‘has legs / no legs’ and a third by ‘eats plants / eats animals’. The teacher should:","options":["Accept only the textbook grouping and mark the others wrong","Choose the ‘best’ grouping and ask the other groups to copy it","Tell children that classification can only be done properly by scientists","Accept every grouping based on a clear, consistently applied criterion"],"answer":3,"explanation":"Classification depends on the criterion chosen; what matters is that it is clearly stated and applied consistently. Discussing different schemes deepens understanding.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"12 जानवरों के चित्रों को समूहों में बाँटने को कहने पर एक समूह ‘ज़मीन पर रहता है / पानी में’ के आधार पर, दूसरा ‘पैर हैं / पैर नहीं हैं’ के आधार पर और तीसरा ‘पौधे खाता है / जानवर खाता है’ के आधार पर बाँटता है। शिक्षक को चाहिए कि:","optionsHi":["केवल पाठ्यपुस्तक के वर्गीकरण को स्वीकार करे और अन्य को गलत चिह्नित करे","‘सबसे अच्छा’ वर्गीकरण चुने और बाकी समूहों से उसे उतारने को कहे","बच्चों को बताए कि वर्गीकरण ठीक से केवल वैज्ञानिक ही कर सकते हैं","हर उस वर्गीकरण को स्वीकार करे जो स्पष्ट, लगातार लागू किए गए मानदंड पर आधारित हो"],"explanationHi":"वर्गीकरण चुने गए मानदंड पर निर्भर करता है; महत्त्वपूर्ण यह है कि वह स्पष्ट रूप से बताया गया हो और लगातार लागू किया गया हो। विभिन्न योजनाओं पर चर्चा समझ को गहरा करती है।"},
  {"id":"cdp-pedagogy-subjects-152","question":"In an EVS lesson on food, a teacher encourages children to use the local names of grains, vegetables and dishes eaten at home. The main reason is that this:","options":["Connects classroom learning with children’s home knowledge","Avoids the need for any standard names in later classes","Saves the time needed to teach the standard names of foods","Shows the teacher which children come from rural families"],"answer":0,"explanation":"Using children’s own words and experiences validates home knowledge and helps them link new learning to what they already know.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"भोजन पर EVS के पाठ में एक शिक्षक बच्चों को घर में खाए जाने वाले अनाजों, सब्ज़ियों और व्यंजनों के स्थानीय नाम उपयोग करने के लिए प्रोत्साहित करता है। इसका मुख्य कारण यह है कि यह:","optionsHi":["कक्षा के अधिगम को बच्चों के घर के ज्ञान से जोड़ता है","बाद की कक्षाओं में किसी भी मानक नाम की आवश्यकता से बचाता है","भोजन के मानक नाम सिखाने में लगने वाला समय बचाता है","शिक्षक को दिखाता है कि कौन-से बच्चे ग्रामीण परिवारों से आते हैं"],"explanationHi":"बच्चों के अपने शब्दों और अनुभवों का उपयोग घर के ज्ञान को मान्यता देता है और उन्हें नई सीख को उस ज्ञान से जोड़ने में मदद करता है जो उनके पास पहले से है।"},
  {"id":"cdp-pedagogy-subjects-153","question":"Many Class 7 students believe that electric current ‘gets used up’ in a bulb, so less current returns to the cell. Which activity best challenges this idea?","options":["Telling them that energy is always conserved in a circuit","Measuring the current with an ammeter on both sides of the bulb","Making them memorise the definition of current and its unit","Showing that a bulb gets hot, so something is used up"],"answer":1,"explanation":"In a series circuit the current is the same everywhere; equal ammeter readings on both sides of the bulb directly contradict the ‘used up’ model. Energy, not charge, is transferred in the bulb.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 7 के कई विद्यार्थी मानते हैं कि विद्युत धारा बल्ब में ‘खर्च हो जाती है’, इसलिए सेल में कम धारा लौटती है। कौन-सी गतिविधि इस विचार को सबसे अच्छी तरह चुनौती देती है?","optionsHi":["उन्हें बताना कि परिपथ में ऊर्जा हमेशा संरक्षित रहती है","अमीटर से बल्ब के दोनों ओर धारा मापना","उनसे धारा की परिभाषा और उसकी इकाई याद करवाना","दिखाना कि बल्ब गरम हो जाता है, इसलिए कुछ खर्च होता है"],"explanationHi":"श्रेणी परिपथ में धारा हर जगह समान होती है; बल्ब के दोनों ओर अमीटर की समान रीडिंग ‘खर्च हो गई’ वाले मॉडल का सीधा खंडन करती हैं। बल्ब में आवेश नहीं, ऊर्जा स्थानांतरित होती है।"},
  {"id":"cdp-pedagogy-subjects-154","question":"A teacher holds an open-book test in EVS. Which kind of question suits it best?","options":["‘List the six themes of EVS given in the textbook.’","‘Write the definition of a food chain as given in the book.’","‘Name three sources of water mentioned in the book.’","‘Give two reasons why the school pond may have dried up.’"],"answer":3,"explanation":"Open-book tests are meant to assess application, analysis and reasoning; recall questions would only reward copying from the book.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षक EVS में खुली-पुस्तक परीक्षा लेता है। कौन-सा प्रकार का प्रश्न इसके लिए सबसे उपयुक्त है?","optionsHi":["‘पाठ्यपुस्तक में दी गई EVS की छह थीम की सूची बनाइए।’","‘पुस्तक में दी गई खाद्य श्रृंखला की परिभाषा लिखिए।’","‘पुस्तक में उल्लिखित जल के तीन स्रोतों के नाम बताइए।’","‘दो कारण बताइए कि विद्यालय का तालाब क्यों सूख गया होगा।’"],"explanationHi":"खुली-पुस्तक परीक्षाएँ अनुप्रयोग, विश्लेषण और तर्क का आकलन करने के लिए होती हैं; स्मरण वाले प्रश्न केवल पुस्तक से नकल करने को पुरस्कृत करेंगे।"},
  {"id":"cdp-pedagogy-subjects-155","question":"A teacher wants to show a reaction that involves heating a strong acid. The most suitable method is:","options":["A teacher demonstration with safety measures, then discussion","Letting each child do it alone to build their confidence","Skipping the topic altogether because it is unsafe","Only reading about it in the textbook, with no demonstration"],"answer":0,"explanation":"Demonstration is appropriate when materials are dangerous, expensive or scarce; children can still predict, observe and explain, keeping it inquiry-oriented.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"एक शिक्षक किसी तीव्र अम्ल को गरम करने वाली अभिक्रिया दिखाना चाहता है। सबसे उपयुक्त तरीका है:","optionsHi":["सुरक्षा उपायों के साथ शिक्षक द्वारा प्रदर्शन, फिर चर्चा","हर बच्चे को अकेले करने देना ताकि उसका आत्मविश्वास बढ़े","विषय को पूरी तरह छोड़ देना क्योंकि यह असुरक्षित है","केवल पाठ्यपुस्तक में इसके बारे में पढ़ना, कोई प्रदर्शन नहीं"],"explanationHi":"प्रदर्शन तब उपयुक्त होता है जब सामग्री खतरनाक, महँगी या दुर्लभ हो; बच्चे फिर भी अनुमान लगा सकते हैं, अवलोकन कर सकते हैं और व्याख्या कर सकते हैं, जिससे यह अन्वेषण-उन्मुख बना रहता है।"},
  {"id":"cdp-pedagogy-subjects-156","question":"Which question in an EVS lesson on water best promotes critical thinking about the social environment?","options":["‘What colour is water, and what does it taste like?’","‘Name two rivers of India and the states they flow through.’","‘In your area, who walks farthest to fetch water, and why?’","‘How many glasses of water do you drink a day?’"],"answer":2,"explanation":"This question asks children to notice and reason about unequal access to resources (by gender, place or class), linking science and social issues as EVS intends.","difficulty":"hard","source":"CTET · State TETs","questionHi":"जल पर EVS के पाठ में कौन-सा प्रश्न सामाजिक पर्यावरण के बारे में आलोचनात्मक चिंतन को सबसे अधिक बढ़ावा देता है?","optionsHi":["‘पानी का रंग क्या होता है, और उसका स्वाद कैसा होता है?’","‘भारत की दो नदियों के नाम बताइए और वे किन राज्यों से होकर बहती हैं।’","‘आपके क्षेत्र में पानी लाने के लिए सबसे दूर कौन चलता है, और क्यों?’","‘आप दिन में कितने गिलास पानी पीते हैं?’"],"explanationHi":"यह प्रश्न बच्चों से संसाधनों तक असमान पहुँच (लिंग, स्थान या वर्ग के आधार पर) को देखने और उस पर तर्क करने को कहता है, जिससे विज्ञान और सामाजिक मुद्दे जुड़ते हैं, जैसा EVS का उद्देश्य है।"},
  {"id":"cdp-pedagogy-subjects-157","question":"How many of the following are consistent with the NCF 2005 view of science teaching at the upper primary stage? I. Learning science through familiar experiences and simple experiments. II. Treating science as a fixed set of facts to be memorised. III. Discouraging questions until children have mastered the basic facts. IV. Focusing mainly on preparation for competitive examinations.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I matches NCF 2005, which sees science as inquiry through familiar experiences. Memorising fixed facts, discouraging questions and exam-oriented teaching are what it argues against.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"उच्च प्राथमिक स्तर पर विज्ञान शिक्षण के NCF 2005 के दृष्टिकोण से निम्नलिखित में से कितने मेल खाते हैं? I. परिचित अनुभवों और सरल प्रयोगों के माध्यम से विज्ञान सीखना। II. विज्ञान को याद किए जाने वाले तथ्यों का निश्चित समूह मानना। III. जब तक बच्चे मूल तथ्यों में निपुण न हो जाएँ, प्रश्न पूछने को हतोत्साहित करना। IV. मुख्य रूप से प्रतियोगी परीक्षाओं की तैयारी पर ध्यान देना।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I NCF 2005 से मेल खाता है, जो विज्ञान को परिचित अनुभवों के माध्यम से अन्वेषण के रूप में देखता है। निश्चित तथ्यों को रटना, प्रश्नों को हतोत्साहित करना और परीक्षा-केंद्रित शिक्षण वे बातें हैं जिनके विरुद्ध वह तर्क देता है।"},
  {"id":"cdp-pedagogy-subjects-158","question":"Which of the following is the most suitable way to begin a Class 4 EVS lesson on ‘Our Food’?","options":["Dictating notes on carbohydrates, proteins and fats","Asking children what they ate yesterday and how it was cooked","Giving a short written test on food nutrients and vitamins","Writing the chapter summary on the board for children to copy"],"answer":1,"explanation":"Starting from children’s own experience (their meals) makes the topic meaningful and lets the teacher build on prior knowledge, as EVS pedagogy recommends.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 4 के EVS पाठ ‘हमारा भोजन’ को शुरू करने का निम्नलिखित में से सबसे उपयुक्त तरीका कौन-सा है?","optionsHi":["कार्बोहाइड्रेट, प्रोटीन और वसा पर नोट्स लिखवाना","बच्चों से पूछना कि उन्होंने कल क्या खाया और वह कैसे पकाया गया था","खाद्य पोषक तत्त्वों और विटामिनों पर एक छोटी लिखित परीक्षा देना","बच्चों के उतारने के लिए श्यामपट्ट पर अध्याय का सार लिखना"],"explanationHi":"बच्चों के अपने अनुभव (उनके भोजन) से शुरुआत करने से विषय अर्थपूर्ण बनता है और शिक्षक पूर्व ज्ञान पर आधारित निर्माण कर सकता है, जैसा EVS शिक्षाशास्त्र अनुशंसित करता है।"},
  {"id":"cdp-pedagogy-subjects-159","question":"After reading a story, a teacher writes five sentences from it on the board (‘The fox jumped…’, ‘The crow dropped…’) and asks children what they notice about the action words and when the events happened. The children work out how the past tense is formed. This way of teaching grammar is:","options":["Deductive, because the rule comes first","Inductive, in context, because learners discover the rule from examples","Grammar-translation, because sentences are compared with the mother tongue","Audio-lingual, because it relies on pattern drills"],"answer":1,"explanation":"In the inductive approach, learners observe examples in meaningful context and infer the rule, which leads to better understanding than memorising a rule first.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कहानी पढ़ने के बाद एक शिक्षिका उसमें से पाँच वाक्य श्यामपट्ट पर लिखती है (‘The fox jumped…’, ‘The crow dropped…’) और बच्चों से पूछती है कि वे क्रिया-शब्दों और घटनाओं के घटित होने के समय के बारे में क्या देखते हैं। बच्चे स्वयं निकाल लेते हैं कि भूतकाल कैसे बनता है। व्याकरण पढ़ाने का यह तरीका है:","optionsHi":["निगमनात्मक, क्योंकि नियम पहले आता है","आगमनात्मक, संदर्भ में, क्योंकि अधिगमकर्ता उदाहरणों से नियम खोजते हैं","व्याकरण-अनुवाद, क्योंकि वाक्यों की मातृभाषा से तुलना की जाती है","श्रव्य-भाषिक, क्योंकि यह पैटर्न-अभ्यास पर निर्भर है"],"explanationHi":"आगमनात्मक उपागम में अधिगमकर्ता अर्थपूर्ण संदर्भ में उदाहरणों का अवलोकन करते हैं और नियम का अनुमान लगाते हैं, जो पहले नियम याद करने की तुलना में बेहतर समझ की ओर ले जाता है।"},
  {"id":"cdp-pedagogy-subjects-160","question":"A learner of English regularly writes ‘He go to school daily’, but once, while hurrying, wrote ‘They was late’ although she normally writes ‘They were’. In S. P. Corder’s terms:","options":["Both are mistakes, since she generally knows English well","Both are errors, since both forms are grammatically incorrect","The first is a mistake (a slip) and the second an error (systematic)","The first is an error (systematic) and the second a mistake (a slip)"],"answer":3,"explanation":"Corder distinguished systematic errors, which reveal the learner’s current rule system, from occasional mistakes, which she can self-correct. Errors are useful evidence of what to teach next.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"अंग्रेज़ी की एक अधिगमकर्ता नियमित रूप से ‘He go to school daily’ लिखती है, लेकिन एक बार जल्दी में उसने ‘They was late’ लिख दिया, जबकि वह सामान्यतः ‘They were’ लिखती है। एस. पी. कॉर्डर के शब्दों में:","optionsHi":["दोनों भूलें (मिस्टेक) हैं, क्योंकि वह आमतौर पर अंग्रेज़ी अच्छी तरह जानती है","दोनों त्रुटियाँ (एरर) हैं, क्योंकि दोनों रूप व्याकरण की दृष्टि से गलत हैं","पहली भूल (चूक) है और दूसरी त्रुटि (व्यवस्थित)","पहली त्रुटि (व्यवस्थित) है और दूसरी भूल (चूक)"],"explanationHi":"कॉर्डर ने व्यवस्थित त्रुटियों को, जो अधिगमकर्ता की वर्तमान नियम-प्रणाली को प्रकट करती हैं, कभी-कभार होने वाली भूलों से अलग किया, जिन्हें वह स्वयं सुधार सकती है। त्रुटियाँ इस बात का उपयोगी प्रमाण हैं कि आगे क्या सिखाना है।"},
  {"id":"cdp-pedagogy-subjects-161","question":"A Class 6 learner of English consistently says ‘He no like mango’ and ‘She no coming today’. Language teachers would describe this as:","options":["Interlanguage: the learner’s own rule-governed, developing system","Proof that the learner cannot learn English properly at this late age","Deliberate carelessness that should be firmly punished","A speech disorder needing therapy from a specialist"],"answer":0,"explanation":"Selinker’s interlanguage is the learner’s own evolving grammar; using ‘no’ before the verb for all negatives is a normal stage that changes with rich input and feedback.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 6 की अंग्रेज़ी की एक अधिगमकर्ता लगातार ‘He no like mango’ और ‘She no coming today’ कहती है। भाषा-शिक्षक इसे क्या कहेंगे?","optionsHi":["अंतरभाषा (इंटरलैंग्वेज): अधिगमकर्ता की अपनी नियम-शासित, विकसित होती प्रणाली","इस बात का प्रमाण कि अधिगमकर्ता इस देर की उम्र में अंग्रेज़ी ठीक से नहीं सीख सकती","जानबूझकर की गई लापरवाही, जिसे कड़ाई से दंडित किया जाना चाहिए","वाक् विकार, जिसके लिए विशेषज्ञ से चिकित्सा की आवश्यकता है"],"explanationHi":"सेलिंकर की अंतरभाषा अधिगमकर्ता का अपना विकसित होता व्याकरण है; सभी निषेधों के लिए क्रिया से पहले ‘no’ का उपयोग एक सामान्य अवस्था है, जो समृद्ध निवेश और प्रतिपुष्टि से बदलती है।"},
  {"id":"cdp-pedagogy-subjects-162","question":"A child whose home language does not allow words to begin with ‘sk’ says ‘iskool’ for ‘school’. The best teacher response is to:","options":["Correct the child sharply in front of the class every time","Model the word naturally, treating it as normal first-language influence","Ask the child to stop speaking English until the pronunciation is perfect","Ignore spoken English and focus only on written English instead"],"answer":1,"explanation":"Transfer of first-language sound patterns is natural; plenty of input, modelling and low-anxiety practice help, while public correction raises the affective filter.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक बच्चा, जिसकी घरेलू भाषा में शब्द ‘sk’ से शुरू नहीं हो सकते, ‘school’ को ‘iskool’ कहता है। शिक्षक की सबसे अच्छी प्रतिक्रिया है:","optionsHi":["हर बार कक्षा के सामने बच्चे को कड़ाई से सुधारना","शब्द को स्वाभाविक रूप से उच्चरित करके दिखाना और इसे प्रथम भाषा का सामान्य प्रभाव मानना","बच्चे से उच्चारण पूर्ण होने तक अंग्रेज़ी बोलना बंद करने को कहना","बोली जाने वाली अंग्रेज़ी को अनदेखा करके केवल लिखित अंग्रेज़ी पर ध्यान देना"],"explanationHi":"प्रथम भाषा के ध्वनि-प्रतिरूपों का स्थानांतरण स्वाभाविक है; पर्याप्त निवेश, आदर्श प्रस्तुति और कम-चिंता वाला अभ्यास सहायक होते हैं, जबकि सार्वजनिक सुधार भावात्मक छन्नी को ऊँचा कर देता है।"},
  {"id":"cdp-pedagogy-subjects-163","question":"A four-year-old turns the pages of a picture book and ‘reads’ the story aloud from the pictures, though she cannot yet decode the words. This behaviour should be seen as:","options":["Cheating, because she is not actually reading the printed words","A sign of a reading disability that needs early testing","Emergent literacy, to be encouraged as real progress towards reading","Proof that she has memorised the book and so needs no further help now"],"answer":2,"explanation":"Pretend reading shows growing concepts about print, story structure and book handling; the emergent literacy view treats such behaviour as real progress towards reading.","difficulty":"hard","source":"CTET · State TETs","questionHi":"चार वर्ष की एक बच्ची चित्र-पुस्तक के पन्ने पलटती है और चित्रों के आधार पर कहानी ज़ोर से ‘पढ़ती’ है, जबकि वह अभी शब्दों को डिकोड नहीं कर सकती। इस व्यवहार को किस रूप में देखा जाना चाहिए?","optionsHi":["धोखा, क्योंकि वह वास्तव में छपे शब्द नहीं पढ़ रही है","पठन अक्षमता का संकेत, जिसकी शीघ्र जाँच आवश्यक है","उदीयमान साक्षरता, जिसे पठन की ओर वास्तविक प्रगति मानकर प्रोत्साहित किया जाना चाहिए","इस बात का प्रमाण कि उसने पुस्तक याद कर ली है, इसलिए अब उसे और सहायता की आवश्यकता नहीं"],"explanationHi":"नाटकीय पठन मुद्रित सामग्री, कहानी की संरचना और पुस्तक सँभालने की बढ़ती समझ को दर्शाता है; उदीयमान साक्षरता का दृष्टिकोण ऐसे व्यवहार को पठन की ओर वास्तविक प्रगति मानता है।"},
  {"id":"cdp-pedagogy-subjects-164","question":"A Class 1 child writes, ‘I wnt to skool on my sikl.’ From the perspective of early writing development, the teacher should recognise that:","options":["The child must be stopped from writing until spelling is correct","The child is careless and needs to copy each word correctly five times","The spellings show that the child has not learnt the alphabet properly","Invented spelling from sound–letter knowledge, a normal stage to value"],"answer":3,"explanation":"Invented spellings like ‘skool’ and ‘sikl’ show the child hearing sounds and mapping them to letters. Encouraging writing for meaning, with gentle modelling, builds both fluency and accuracy.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"कक्षा 1 का एक बच्चा लिखता है, ‘I wnt to skool on my sikl.’ प्रारंभिक लेखन विकास के दृष्टिकोण से शिक्षक को यह पहचानना चाहिए कि:","optionsHi":["वर्तनी सही होने तक बच्चे को लिखने से रोकना चाहिए","बच्चा लापरवाह है और उसे हर शब्द सही-सही पाँच बार उतारना चाहिए","वर्तनी दिखाती है कि बच्चे ने वर्णमाला ठीक से नहीं सीखी है","यह ध्वनि–अक्षर ज्ञान से बनी स्वनिर्मित वर्तनी है, जो एक सामान्य अवस्था है और जिसे महत्त्व देना चाहिए"],"explanationHi":"‘skool’ और ‘sikl’ जैसी स्वनिर्मित वर्तनियाँ दिखाती हैं कि बच्चा ध्वनियाँ सुनकर उन्हें अक्षरों से जोड़ रहा है। अर्थ के लिए लिखने को प्रोत्साहित करना, कोमल आदर्श प्रस्तुति के साथ, प्रवाह और शुद्धता दोनों का निर्माण करता है।"},
  {"id":"cdp-pedagogy-subjects-165","question":"Before reading a chapter on bees, students fill in what they already know and what they want to know, and after reading they note what they have learnt. This reading strategy is:","options":["SQ3R","The KWL chart","The cloze procedure","Skimming"],"answer":1,"explanation":"KWL (Know, Want to know, Learnt) activates prior knowledge, sets a purpose for reading and supports reflection on learning.","difficulty":"hard","source":"CTET · State TETs","questionHi":"मधुमक्खियों पर अध्याय पढ़ने से पहले विद्यार्थी भरते हैं कि वे पहले से क्या जानते हैं और क्या जानना चाहते हैं, और पढ़ने के बाद नोट करते हैं कि उन्होंने क्या सीखा। यह पठन-रणनीति है:","optionsHi":["SQ3R","KWL चार्ट","क्लोज़ प्रक्रिया","स्किमिंग (सरसरी पठन)"],"explanationHi":"KWL (Know, Want to know, Learnt) पूर्व ज्ञान को सक्रिय करता है, पढ़ने का उद्देश्य निर्धारित करता है और अधिगम पर चिंतन में सहायक होता है।"},
  {"id":"cdp-pedagogy-subjects-166","question":"In a weekly library period, children choose storybooks they like and read many of them for pleasure, without answering questions afterwards. This is an example of:","options":["Extensive reading","Intensive reading","Scanning","Choral reading"],"answer":0,"explanation":"Extensive reading means reading a lot of self-chosen material for enjoyment and general understanding; it builds fluency, vocabulary and the reading habit. Intensive reading studies a short text closely.","difficulty":"hard","source":"CTET · State TETs","questionHi":"साप्ताहिक पुस्तकालय कालांश में बच्चे अपनी पसंद की कहानी की पुस्तकें चुनते हैं और आनंद के लिए उनमें से कई पढ़ते हैं, बाद में प्रश्नों के उत्तर दिए बिना। यह किसका उदाहरण है?","optionsHi":["विस्तृत पठन","गहन पठन","स्कैनिंग (खोजपूर्वक पठन)","सामूहिक पठन"],"explanationHi":"विस्तृत पठन का अर्थ है आनंद और सामान्य समझ के लिए स्वयं चुनी हुई बहुत-सी सामग्री पढ़ना; यह प्रवाह, शब्दावली और पढ़ने की आदत का निर्माण करता है। गहन पठन किसी छोटे पाठ का बारीकी से अध्ययन करता है।"},
  {"id":"cdp-pedagogy-subjects-167","question":"Which is the most suitable way to teach a poem to Class 5 children?","options":["Explaining the meaning line by line for children to memorise","Asking children to write meanings of hard words before hearing it","Testing them on the poet’s life and other famous works","Reading it aloud with expression and inviting children’s responses"],"answer":3,"explanation":"Poetry is first to be enjoyed and responded to; line-by-line paraphrase and memorised meanings kill the pleasure and personal response that literature aims to develop.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 5 के बच्चों को कविता पढ़ाने का सबसे उपयुक्त तरीका कौन-सा है?","optionsHi":["पंक्ति-दर-पंक्ति अर्थ समझाना ताकि बच्चे उसे याद करें","बच्चों से सुनने से पहले कठिन शब्दों के अर्थ लिखने को कहना","उनसे कवि के जीवन और अन्य प्रसिद्ध रचनाओं पर परीक्षा लेना","भाव सहित ज़ोर से पढ़ना और बच्चों की प्रतिक्रियाओं को आमंत्रित करना"],"explanationHi":"कविता का पहले आनंद लिया जाना चाहिए और उस पर प्रतिक्रिया दी जानी चाहिए; पंक्ति-दर-पंक्ति भावार्थ और रटे हुए अर्थ उस आनंद और व्यक्तिगत प्रतिक्रिया को नष्ट कर देते हैं जिसे साहित्य विकसित करना चाहता है।"},
  {"id":"cdp-pedagogy-subjects-168","question":"A teacher gives each essay a single overall grade based on her general impression of its quality, rather than separate marks for content, organisation, vocabulary and grammar. Which statement is correct?","options":["Analytic scoring, which gives detailed diagnostic feedback on each part","Holistic scoring: quick, but less diagnostic than analytic scoring","Checklist scoring, ticking features present or absent","Norm-referenced scoring, ranking essays against each other"],"answer":1,"explanation":"Holistic scoring rates the whole piece at once; analytic scoring rates separate components and so shows learners exactly where to improve.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक शिक्षिका हर निबंध को विषय-वस्तु, संगठन, शब्दावली और व्याकरण के अलग-अलग अंक देने के बजाय उसकी गुणवत्ता के अपने सामान्य प्रभाव के आधार पर एक समग्र ग्रेड देती है। कौन-सा कथन सही है?","optionsHi":["विश्लेषणात्मक अंकन, जो प्रत्येक भाग पर विस्तृत निदानात्मक प्रतिपुष्टि देता है","समग्र अंकन: तेज़, लेकिन विश्लेषणात्मक अंकन की तुलना में कम निदानात्मक","जाँच-सूची अंकन, जिसमें मौजूद या अनुपस्थित विशेषताओं पर निशान लगाया जाता है","मानक-संदर्भित अंकन, जो निबंधों को एक-दूसरे के विरुद्ध क्रमबद्ध करता है"],"explanationHi":"समग्र अंकन पूरी रचना को एक साथ आँकता है; विश्लेषणात्मक अंकन अलग-अलग घटकों को आँकता है और इसलिए अधिगमकर्ताओं को ठीक-ठीक दिखाता है कि कहाँ सुधार करना है।"},
  {"id":"cdp-pedagogy-subjects-169","question":"Students work in pairs: one has a picture of a room and the other a slightly different picture. Without showing their pictures, they talk to find the differences. This kind of task is called:","options":["A substitution drill in pairs","Choral repetition","An information-gap activity","Picture dictation"],"answer":2,"explanation":"In an information-gap activity each learner has information the other needs, so they must communicate for a real purpose, a core technique of the communicative approach.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"विद्यार्थी जोड़ियों में काम करते हैं: एक के पास किसी कमरे का चित्र है और दूसरे के पास थोड़ा अलग चित्र। अपने चित्र दिखाए बिना वे अंतर खोजने के लिए बातचीत करते हैं। इस प्रकार के कार्य को क्या कहते हैं?","optionsHi":["जोड़ी में प्रतिस्थापन अभ्यास","सामूहिक दोहराव","सूचना-अंतराल गतिविधि (इन्फ़ॉर्मेशन-गैप एक्टिविटी)","चित्र श्रुतलेख"],"explanationHi":"सूचना-अंतराल गतिविधि में हर अधिगमकर्ता के पास ऐसी जानकारी होती है जिसकी दूसरे को आवश्यकता है, इसलिए उन्हें वास्तविक उद्देश्य के लिए संप्रेषण करना पड़ता है, जो संप्रेषणात्मक उपागम की एक मूल तकनीक है।"},
  {"id":"cdp-pedagogy-subjects-170","question":"A teacher of young learners says, ‘Stand up! Touch your nose! Hop three times! Sit down!’ and children respond with actions, without being required to speak yet. This method is:","options":["The grammar-translation method","The silent way","The direct method using reading aloud","Total Physical Response (TPR)"],"answer":3,"explanation":"Asher’s TPR links language with physical action, lets learners first show understanding through movement, and keeps anxiety low before speaking is expected.","difficulty":"hard","source":"CTET · State TETs","questionHi":"छोटे बच्चों की एक शिक्षिका कहती है, ‘खड़े हो जाओ! अपनी नाक छुओ! तीन बार कूदो! बैठ जाओ!’ और बच्चे क्रियाओं से प्रतिक्रिया देते हैं, अभी बोलना आवश्यक नहीं है। यह विधि है:","optionsHi":["व्याकरण-अनुवाद विधि","मौन विधि (साइलेंट वे)","ज़ोर से पढ़ने वाली प्रत्यक्ष विधि","पूर्ण शारीरिक प्रतिक्रिया (Total Physical Response, TPR)"],"explanationHi":"आशर की TPR भाषा को शारीरिक क्रिया से जोड़ती है, अधिगमकर्ताओं को पहले गति के माध्यम से समझ दिखाने देती है, और बोलने की अपेक्षा से पहले चिंता को कम रखती है।"},
  {"id":"cdp-pedagogy-subjects-171","question":"A Class 3 child reads very slowly, word by word with a finger under each word, though he decodes accurately. Which strategy is most likely to improve his reading fluency?","options":["Repeated reading of familiar texts, with paired reading","More phonics worksheets on letter sounds and blends","Asking him to read only silently, so no one hears him","Giving him longer and harder texts so that he is challenged"],"answer":0,"explanation":"He already decodes; what he lacks is automaticity. Re-reading familiar texts and hearing fluent models build speed, phrasing and expression.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 3 का एक बच्चा बहुत धीरे पढ़ता है, हर शब्द के नीचे उँगली रखकर शब्द-दर-शब्द, हालाँकि वह सटीक डिकोड करता है। कौन-सी रणनीति उसके पठन-प्रवाह को सुधारने की सबसे अधिक संभावना रखती है?","optionsHi":["परिचित पाठों का बार-बार पठन, जोड़ी में पठन के साथ","अक्षर-ध्वनियों और संयुक्त ध्वनियों पर और अधिक फ़ोनिक्स अभ्यास-पत्र","उससे केवल मौन पठन कराना, ताकि कोई उसे सुन न सके","उसे लंबे और कठिन पाठ देना ताकि उसे चुनौती मिले"],"explanationHi":"वह पहले से डिकोड कर लेता है; उसमें स्वचालन की कमी है। परिचित पाठों को दोबारा पढ़ना और धाराप्रवाह आदर्श पठन सुनना गति, वाक्यांश-विभाजन और भाव का निर्माण करता है।"},
  {"id":"cdp-pedagogy-subjects-172","question":"While reading, a child meets the word ‘parched’ in ‘After weeks without rain, the parched fields cracked open.’ Which strategy should the teacher encourage first?","options":["Stop reading and look up the word in the dictionary at once","Skip the word, since one word does not affect the meaning","Guess from clues like ‘weeks without rain’, then check","Ask the teacher at once for the meaning of every new word"],"answer":2,"explanation":"Guessing meaning from context keeps reading fluent and builds independent word learning; the dictionary can confirm the guess later.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"पढ़ते समय एक बच्चा ‘After weeks without rain, the parched fields cracked open.’ में शब्द ‘parched’ से मिलता है। शिक्षक को पहले कौन-सी रणनीति प्रोत्साहित करनी चाहिए?","optionsHi":["पढ़ना रोककर तुरंत शब्दकोश में शब्द देखना","शब्द को छोड़ देना, क्योंकि एक शब्द से अर्थ पर प्रभाव नहीं पड़ता","‘weeks without rain’ जैसे संकेतों से अनुमान लगाना, फिर जाँचना","हर नए शब्द का अर्थ तुरंत शिक्षक से पूछना"],"explanationHi":"संदर्भ से अर्थ का अनुमान लगाना पठन को प्रवाहमय बनाए रखता है और स्वतंत्र शब्द-अधिगम का निर्माण करता है; शब्दकोश बाद में अनुमान की पुष्टि कर सकता है।"},
  {"id":"cdp-pedagogy-subjects-173","question":"A three-year-old points at a new object and keeps asking, ‘What’s that? Why?’ In Michael Halliday’s account of children’s language functions, this use of language is:","options":["Instrumental","Regulatory","Imaginative","Heuristic"],"answer":3,"explanation":"Halliday’s heuristic function is using language to explore and learn about the world. Instrumental is getting things (‘I want…’), regulatory is controlling others, and imaginative is creating pretend worlds.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"तीन वर्ष का एक बच्चा किसी नई वस्तु की ओर इशारा करता है और बार-बार पूछता है, ‘वह क्या है? क्यों?’ माइकल हैलिडे के बच्चों के भाषा-प्रकार्यों के विवरण में भाषा का यह उपयोग है:","optionsHi":["साधनात्मक","नियामक","कल्पनात्मक","अन्वेषणात्मक (हूरिस्टिक)"],"explanationHi":"हैलिडे का अन्वेषणात्मक प्रकार्य भाषा का उपयोग दुनिया की खोजबीन करने और उसके बारे में सीखने के लिए करना है। साधनात्मक चीज़ें पाना है (‘मुझे चाहिए…’), नियामक दूसरों को नियंत्रित करना है, और कल्पनात्मक काल्पनिक संसार रचना है।"},
  {"id":"cdp-pedagogy-subjects-174","question":"A Class 8 student writes a leave application to the principal beginning, ‘Hey Sir! Can’t come tomorrow, got stuff to do.’ The student mainly needs help with:","options":["Spelling of everyday words used in letters","Register: language suited to purpose and audience","Handwriting and neat layout of the letter page","Grammar of the past and future tenses in letters"],"answer":1,"explanation":"The sentence is grammatical but too informal for a formal letter. Comparing texts for different audiences builds awareness of register.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 8 का एक विद्यार्थी प्रधानाचार्य को अवकाश-आवेदन इस प्रकार शुरू करता है, ‘Hey Sir! Can’t come tomorrow, got stuff to do.’ विद्यार्थी को मुख्य रूप से किस में सहायता चाहिए?","optionsHi":["पत्रों में प्रयुक्त रोज़मर्रा के शब्दों की वर्तनी","प्रयुक्ति (रजिस्टर): उद्देश्य और पाठक के अनुरूप भाषा","पत्र के पृष्ठ की हस्तलिपि और साफ़-सुथरा विन्यास","पत्रों में भूतकाल और भविष्यकाल का व्याकरण"],"explanationHi":"वाक्य व्याकरण की दृष्टि से सही है, लेकिन औपचारिक पत्र के लिए बहुत अनौपचारिक है। अलग-अलग पाठकों के लिए लिखे पाठों की तुलना प्रयुक्ति के प्रति जागरूकता का निर्माण करती है।"},
  {"id":"cdp-pedagogy-subjects-175","question":"A Class 5 teacher has children write their own stories, revise them with peer feedback and publish them in a class magazine read by other classes and parents. The main pedagogical value of publishing is that it:","options":["Gives children a real audience and purpose for careful writing","Saves the teacher from correcting all the stories herself","Helps children memorise their own and others’ stories","Allows the teacher to rank children by their writing ability"],"answer":0,"explanation":"Writing for real readers gives purpose, raises motivation and makes revision meaningful, a key idea of the process and whole-language approaches.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 5 की एक शिक्षिका बच्चों से अपनी कहानियाँ लिखवाती है, सहपाठियों की प्रतिपुष्टि से उन्हें संशोधित करवाती है और उन्हें एक कक्षा पत्रिका में प्रकाशित करती है, जिसे अन्य कक्षाएँ और अभिभावक पढ़ते हैं। प्रकाशन का मुख्य शैक्षिक मूल्य यह है कि वह:","optionsHi":["बच्चों को सावधानी से लिखने के लिए वास्तविक पाठक-वर्ग और उद्देश्य देता है","शिक्षिका को सभी कहानियाँ स्वयं जाँचने से बचाता है","बच्चों को अपनी और दूसरों की कहानियाँ याद करने में मदद करता है","शिक्षिका को बच्चों को उनकी लेखन-क्षमता के आधार पर क्रमबद्ध करने देता है"],"explanationHi":"वास्तविक पाठकों के लिए लिखना उद्देश्य देता है, अभिप्रेरणा बढ़ाता है और संशोधन को अर्थपूर्ण बनाता है, जो प्रक्रिया और समग्र भाषा उपागमों का एक प्रमुख विचार है।"},
  {"id":"cdp-pedagogy-subjects-176","question":"Which item from a Class 4 language test best assesses creative and divergent thinking?","options":["‘Who was the king in the story, and where did he live?’","‘Write the meaning of the word “brave” as used in the story.’","‘Rewrite the ending so the king learns his lesson in a new way.’","‘Fill in the blank with the correct form of the verb.’"],"answer":2,"explanation":"Rewriting the ending is open-ended, allows many acceptable answers and requires imagination; the others check recall or a single correct form.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 4 की भाषा परीक्षा का कौन-सा प्रश्न रचनात्मक और अपसारी चिंतन का सबसे अच्छा आकलन करता है?","optionsHi":["‘कहानी में राजा कौन था, और वह कहाँ रहता था?’","‘कहानी में प्रयुक्त शब्द “बहादुर” का अर्थ लिखिए।’","‘अंत को इस प्रकार दोबारा लिखिए कि राजा नए ढंग से सबक सीखे।’","‘क्रिया के सही रूप से रिक्त स्थान भरिए।’"],"explanationHi":"अंत को दोबारा लिखना मुक्त-उत्तर वाला कार्य है, जिसमें कई स्वीकार्य उत्तर हो सकते हैं और कल्पना की आवश्यकता होती है; अन्य प्रश्न स्मरण या एक सही रूप की जाँच करते हैं।"},
  {"id":"cdp-pedagogy-subjects-177","question":"Which task integrates listening, speaking, reading and writing most fully?","options":["Copying a paragraph from the board into the notebook","Hearing a weather report, discussing it, then reading and writing forecasts","Reading a lesson silently and answering questions in one word","Reciting a learnt poem from memory, with actions, in front of the whole class"],"answer":1,"explanation":"Language skills develop best together through meaningful tasks; this sequence uses all four in a connected way, unlike tasks that isolate one skill.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कौन-सा कार्य सुनने, बोलने, पढ़ने और लिखने को सबसे पूर्ण रूप से एकीकृत करता है?","optionsHi":["श्यामपट्ट से एक अनुच्छेद कॉपी में उतारना","मौसम का समाचार सुनना, उस पर चर्चा करना, फिर पूर्वानुमान पढ़ना और लिखना","पाठ को मौन पढ़कर प्रश्नों के एक-एक शब्द में उत्तर देना","सीखी हुई कविता को स्मृति से, क्रियाओं के साथ, पूरी कक्षा के सामने सुनाना"],"explanationHi":"भाषा-कौशल अर्थपूर्ण कार्यों के माध्यम से साथ-साथ सबसे अच्छी तरह विकसित होते हैं; यह क्रम चारों का परस्पर जुड़े ढंग से उपयोग करता है, उन कार्यों के विपरीत जो एक कौशल को अलग कर देते हैं।"},
  {"id":"cdp-pedagogy-subjects-178","question":"Assertion (A): Grammar should be taught through rules and exercises in isolation before children start using the language for communication. Reason (R): Knowing grammar rules is the main way children acquire the ability to speak a language.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","Both A and R are false"],"answer":3,"explanation":"Children acquire language mainly through meaningful use and rich input; grammar is better learnt in context alongside use, not as a precondition for it.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): बच्चों द्वारा संप्रेषण के लिए भाषा का उपयोग शुरू करने से पहले व्याकरण को अलग-थलग नियमों और अभ्यासों के माध्यम से पढ़ाया जाना चाहिए। कारण (R): व्याकरण के नियम जानना ही बच्चों द्वारा भाषा बोलने की क्षमता अर्जित करने का मुख्य तरीका है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A और R दोनों असत्य हैं"],"explanationHi":"बच्चे भाषा मुख्यतः अर्थपूर्ण उपयोग और समृद्ध निवेश से अर्जित करते हैं; व्याकरण उपयोग के साथ-साथ संदर्भ में बेहतर सीखा जाता है, उसकी पूर्व-शर्त के रूप में नहीं।"},
  {"id":"cdp-pedagogy-subjects-179","question":"A Class 2 child reads the sentence ‘The boy ran to his house’ aloud as ‘The boy ran to his home’. In miscue analysis this miscue suggests that the child:","options":["Cannot read and needs to start again with the alphabet","Is careless and should be stopped and corrected at once, each and every time","Is reading for meaning, though attention to the print can be sharpened","Has a visual problem and needs an eye test before reading"],"answer":2,"explanation":"Goodman’s miscue analysis treats reading errors as windows into the strategies a reader uses. A substitution that keeps the meaning shows the child is reading for sense.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 2 का एक बच्चा वाक्य ‘The boy ran to his house’ को ज़ोर से ‘The boy ran to his home’ पढ़ता है। मिसक्यू विश्लेषण में यह मिसक्यू संकेत करता है कि बच्चा:","optionsHi":["पढ़ नहीं सकता और उसे वर्णमाला से फिर शुरू करना चाहिए","लापरवाह है और उसे हर बार तुरंत रोककर सुधारना चाहिए","अर्थ के लिए पढ़ रहा है, हालाँकि छपे हुए पर उसका ध्यान और तेज़ किया जा सकता है","दृष्टि की समस्या है और पढ़ने से पहले उसकी आँखों की जाँच होनी चाहिए"],"explanationHi":"गुडमैन का मिसक्यू विश्लेषण पठन-त्रुटियों को इस बात की खिड़की मानता है कि पाठक कौन-सी रणनीतियाँ अपना रहा है। अर्थ को बनाए रखने वाला प्रतिस्थापन दिखाता है कि बच्चा भाव के लिए पढ़ रहा है।"},
  {"id":"cdp-pedagogy-subjects-180","question":"Which classroom plan best reflects a balanced approach to early literacy?","options":["Phonics drills only, with no stories until the child can decode","Stories only, with no direct attention to letters and sounds","Read-alouds and shared reading plus systematic phonics and daily writing","Copying letters and words from the board for most of every language period"],"answer":2,"explanation":"Balanced literacy combines meaning-centred reading and writing with explicit teaching of the sound–letter system, rather than either alone.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कौन-सी कक्षा-योजना प्रारंभिक साक्षरता के संतुलित उपागम को सबसे अच्छा दर्शाती है?","optionsHi":["केवल फ़ोनिक्स अभ्यास, जब तक बच्चा डिकोड न कर सके तब तक कोई कहानी नहीं","केवल कहानियाँ, अक्षरों और ध्वनियों पर कोई प्रत्यक्ष ध्यान नहीं","ज़ोर से पढ़कर सुनाना और साझा पठन, साथ में व्यवस्थित फ़ोनिक्स और दैनिक लेखन","हर भाषा-कालांश का अधिकांश समय श्यामपट्ट से अक्षर और शब्द उतारना"],"explanationHi":"संतुलित साक्षरता अर्थ-केंद्रित पठन और लेखन को ध्वनि–अक्षर प्रणाली के स्पष्ट शिक्षण के साथ जोड़ती है, किसी एक के अकेले उपयोग के बजाय।"},
  {"id":"cdp-pedagogy-subjects-181","question":"For a student with a visual impairment in a language class, the most suitable support is:","options":["Exempting her from reading and writing tasks altogether","Audio books, Braille or large print, and reading the board aloud","Asking a friend to do her reading and written homework","Seating her at the back of the class to avoid disturbing other children"],"answer":1,"explanation":"Accessible formats and oral support let her take full part in reading and writing; exemption or dependence on others denies her learning.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"भाषा की कक्षा में दृष्टिबाधित विद्यार्थी के लिए सबसे उपयुक्त सहायता है:","optionsHi":["उसे पढ़ने और लिखने के कार्यों से पूरी तरह छूट देना","ऑडियो पुस्तकें, ब्रेल या बड़े अक्षर, और श्यामपट्ट को ज़ोर से पढ़कर सुनाना","किसी मित्र से उसका पढ़ना और लिखित गृहकार्य करवाना","दूसरे बच्चों को परेशानी न हो, इसलिए उसे कक्षा में पीछे बिठाना"],"explanationHi":"सुलभ प्रारूप और मौखिक सहायता उसे पठन और लेखन में पूरी तरह भाग लेने देते हैं; छूट या दूसरों पर निर्भरता उसे सीखने से वंचित करती है।"},
  {"id":"cdp-pedagogy-subjects-182","question":"Regular storytelling in the early grades mainly helps children to:","options":["Prepare for written examinations through model answers","Learn grammar rules explicitly through the teacher’s explanation","Improve their handwriting by writing the stories down","Develop listening, vocabulary, imagination and a sense of story"],"answer":3,"explanation":"Stories expose children to rich language in meaningful context and build listening comprehension, vocabulary, prediction and narrative sense, the base for reading.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"प्रारंभिक कक्षाओं में नियमित कहानी सुनाना मुख्य रूप से बच्चों को किसमें सहायता करता है?","optionsHi":["आदर्श उत्तरों के माध्यम से लिखित परीक्षाओं की तैयारी में","शिक्षक की व्याख्या के माध्यम से व्याकरण के नियम स्पष्ट रूप से सीखने में","कहानियाँ लिखकर अपनी हस्तलिपि सुधारने में","सुनने, शब्दावली, कल्पना और कहानी की समझ के विकास में"],"explanationHi":"कहानियाँ बच्चों को अर्थपूर्ण संदर्भ में समृद्ध भाषा से परिचित कराती हैं और सुनकर बोध, शब्दावली, पूर्वानुमान और कथा-बोध का निर्माण करती हैं, जो पठन का आधार है।"},
  {"id":"cdp-pedagogy-subjects-183","question":"A teacher keeps a folder for each child with dated samples of writing from the year, a reading log, an audio recording of the child reading, and the child’s comments on her own progress. This tool is a:","options":["Portfolio","Cumulative record","Rating scale","Question bank"],"answer":0,"explanation":"A language portfolio is a purposeful collection showing growth over time with the learner’s reflection; it supports continuous, comprehensive assessment.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"एक शिक्षिका हर बच्चे के लिए एक फ़ोल्डर रखती है, जिसमें वर्ष भर के लेखन के दिनांकित नमूने, पठन-लॉग, बच्चे के पढ़ने की ऑडियो रिकॉर्डिंग, और बच्चे की अपनी प्रगति पर टिप्पणियाँ होती हैं। यह उपकरण है:","optionsHi":["पोर्टफ़ोलियो","संचयी अभिलेख","मापनी (रेटिंग स्केल)","प्रश्न बैंक"],"explanationHi":"भाषा पोर्टफ़ोलियो समय के साथ विकास दिखाने वाला उद्देश्यपूर्ण संग्रह है, जिसमें अधिगमकर्ता का चिंतन भी होता है; यह सतत और व्यापक आकलन में सहायक है।"},
  {"id":"cdp-pedagogy-subjects-184","question":"Which question about a story checks evaluative (critical) comprehension?","options":["‘Where did the farmer go in the morning?’","‘Why do you think the farmer did not tell anyone about the treasure?’","‘How many sons did the farmer have?’","‘Do you think the farmer was fair to his sons? Give reasons.’"],"answer":3,"explanation":"Evaluative questions ask readers to judge ideas or actions using their own values and reasoning. ‘Why do you think…’ asks for an inference, and the others check literal recall.","difficulty":"hard","source":"CTET · State TETs","questionHi":"किसी कहानी के बारे में कौन-सा प्रश्न मूल्यांकनात्मक (आलोचनात्मक) बोध की जाँच करता है?","optionsHi":["‘किसान सुबह कहाँ गया?’","‘आपको क्यों लगता है कि किसान ने खज़ाने के बारे में किसी को नहीं बताया?’","‘किसान के कितने बेटे थे?’","‘क्या आपको लगता है कि किसान अपने बेटों के साथ न्यायपूर्ण था? कारण दीजिए।’"],"explanationHi":"मूल्यांकनात्मक प्रश्न पाठकों से अपने मूल्यों और तर्क का उपयोग करके विचारों या कार्यों का निर्णय करने को कहते हैं। ‘आपको क्यों लगता है…’ अनुमान माँगता है, और अन्य शाब्दिक स्मरण की जाँच करते हैं।"},
  {"id":"cdp-pedagogy-subjects-185","question":"According to NCF 2005, the main aim of teaching a second language such as English in the early years is that children should:","options":["Communicate naturally in it, using the home language as a resource","Learn grammar rules thoroughly before using the language at all","Read only the prescribed textbooks with full accuracy","Translate texts word by word into the mother tongue to check meaning"],"answer":0,"explanation":"NCF 2005 stresses acquiring the second language through rich, comprehensible input and meaningful use, with multilingualism as a resource, rather than through grammar and translation.","difficulty":"hard","source":"CTET · State TETs","questionHi":"NCF 2005 के अनुसार, प्रारंभिक वर्षों में अंग्रेज़ी जैसी द्वितीय भाषा को पढ़ाने का मुख्य उद्देश्य यह है कि बच्चे:","optionsHi":["घरेलू भाषा को संसाधन के रूप में उपयोग करते हुए उसमें स्वाभाविक रूप से संप्रेषण करें","भाषा का उपयोग करने से पहले व्याकरण के नियम भली-भाँति सीखें","केवल निर्धारित पाठ्यपुस्तकें पूरी शुद्धता के साथ पढ़ें","अर्थ जाँचने के लिए पाठों का शब्द-दर-शब्द मातृभाषा में अनुवाद करें"],"explanationHi":"NCF 2005 द्वितीय भाषा को व्याकरण और अनुवाद के बजाय समृद्ध, बोधगम्य निवेश और अर्थपूर्ण उपयोग के माध्यम से अर्जित करने पर ज़ोर देता है, और बहुभाषिकता को एक संसाधन मानता है।"},
  {"id":"cdp-pedagogy-subjects-186","question":"A Class 7 teacher asks students to record a conversation in the market, transcribe it, and compare it with a dialogue in their textbook. The main learning outcome is awareness of:","options":["How spoken language differs from written language","The spelling of difficult words used in markets","The history and economics of the local market","Handwriting speed when transcribing quickly"],"answer":0,"explanation":"Analysing real speech helps learners notice how spoken language differs from written dialogue, building language awareness and sensitivity to how language is used.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 7 का एक शिक्षक विद्यार्थियों से बाज़ार में एक बातचीत रिकॉर्ड करने, उसे लिपिबद्ध करने और अपनी पाठ्यपुस्तक के किसी संवाद से उसकी तुलना करने को कहता है। मुख्य अधिगम-परिणाम किसके प्रति जागरूकता है?","optionsHi":["बोली जाने वाली भाषा लिखित भाषा से कैसे भिन्न होती है","बाज़ारों में प्रयुक्त कठिन शब्दों की वर्तनी","स्थानीय बाज़ार का इतिहास और अर्थशास्त्र","तेज़ी से लिपिबद्ध करते समय हस्तलेखन की गति"],"explanationHi":"वास्तविक बोलचाल का विश्लेषण अधिगमकर्ताओं को यह देखने में मदद करता है कि बोली जाने वाली भाषा लिखित संवाद से कैसे अलग है, जिससे भाषा-जागरूकता और भाषा के उपयोग के प्रति संवेदनशीलता का निर्माण होता है।"},
  {"id":"cdp-pedagogy-subjects-187","question":"Which practice in a language class is LEAST consistent with treating errors as part of learning?","options":["Noting common errors and addressing them later through practice","Recasting a child’s incorrect sentence correctly in the reply","Interrupting a child mid-story to correct every error","Encouraging peers to give each other feedback on drafts"],"answer":2,"explanation":"Constant interruption focuses on form over meaning, raises anxiety and discourages speaking; the other practices give feedback without blocking communication.","difficulty":"hard","source":"CTET · State TETs","questionHi":"भाषा की कक्षा में कौन-सा अभ्यास त्रुटियों को अधिगम का भाग मानने के सबसे कम अनुरूप है?","optionsHi":["सामान्य त्रुटियों को नोट करना और बाद में अभ्यास के माध्यम से उन्हें संबोधित करना","बच्चे के गलत वाक्य को उत्तर में सही रूप में दोहराना (रीकास्ट)","कहानी के बीच में बच्चे को टोककर हर त्रुटि सुधारना","सहपाठियों को प्रारूपों पर एक-दूसरे को प्रतिपुष्टि देने के लिए प्रोत्साहित करना"],"explanationHi":"लगातार टोकना अर्थ के बजाय रूप पर ध्यान देता है, चिंता बढ़ाता है और बोलने को हतोत्साहित करता है; अन्य अभ्यास संप्रेषण को रोके बिना प्रतिपुष्टि देते हैं।"},
  {"id":"cdp-pedagogy-subjects-188","question":"A Class 7 student simplifies 2a + 3b as 5ab. Which teacher response is most likely to help her see the error for herself?","options":["Tell her unlike terms can never be added and ask her to memorise it","Give her ten more sums of the same kind for practice","Ask her to put a = 2, b = 3 into both expressions and compare","Explain that ‘ab’ means a times b, not a plus b"],"answer":2,"explanation":"Substituting numbers shows that the two expressions are not equal, which creates cognitive conflict and builds the idea that letters stand for numbers; a rule alone does not.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 7 की एक छात्रा 2a + 3b को 5ab के रूप में सरल करती है। कौन-सी शिक्षक-प्रतिक्रिया उसे त्रुटि स्वयं देखने में सबसे अधिक सहायक होगी?","optionsHi":["उसे बताना कि असमान पदों को कभी जोड़ा नहीं जा सकता और उसे याद करने को कहना","उसे अभ्यास के लिए इसी प्रकार के दस और प्रश्न देना","उससे दोनों व्यंजकों में a = 2, b = 3 रखकर तुलना करने को कहना","समझाना कि ‘ab’ का अर्थ a गुणा b है, a जमा b नहीं"],"explanationHi":"संख्याएँ रखकर देखने से पता चलता है कि दोनों व्यंजक बराबर नहीं हैं, जो संज्ञानात्मक संघर्ष पैदा करता है और यह विचार बनाता है कि अक्षर संख्याओं का प्रतिनिधित्व करते हैं; केवल नियम ऐसा नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-189","question":"Asked to write an expression for ‘the cost of 3 pens and 2 books’, a student writes ‘3p + 2b’ and explains, ‘p means pens and b means books.’ The teacher’s main concern should be that the student:","options":["Has written a wrong expression for the total cost","Sees letters as labels for objects, not as numbers (prices)","Does not know how multiplication is shown in algebra","Should have used x and y, the standard letters for unknowns"],"answer":1,"explanation":"The expression is right, but the ‘letter as object’ (fruit-salad) view causes later errors, such as reading 3p as ‘3 pens’. The teacher should stress that p stands for the price of one pen.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"‘3 कलमों और 2 किताबों की लागत’ के लिए व्यंजक लिखने को कहने पर एक विद्यार्थी ‘3p + 2b’ लिखता है और समझाता है, ‘p का अर्थ कलम और b का अर्थ किताब है।’ शिक्षक की मुख्य चिंता यह होनी चाहिए कि विद्यार्थी:","optionsHi":["ने कुल लागत का गलत व्यंजक लिखा है","अक्षरों को वस्तुओं के लेबल के रूप में देखता है, संख्याओं (कीमतों) के रूप में नहीं","नहीं जानता कि बीजगणित में गुणा कैसे दर्शाया जाता है","को अज्ञात के मानक अक्षर x और y का उपयोग करना चाहिए था"],"explanationHi":"व्यंजक सही है, लेकिन ‘अक्षर को वस्तु’ (फल-सलाद) मानने का दृष्टिकोण बाद में त्रुटियाँ पैदा करता है, जैसे 3p को ‘3 कलम’ पढ़ना। शिक्षक को ज़ोर देना चाहिए कि p एक कलम की कीमत का प्रतिनिधित्व करता है।"},
  {"id":"cdp-pedagogy-subjects-190","question":"A Class 6 student says −5 is greater than −2 ‘because 5 is greater than 2’. Which context best helps correct this idea?","options":["A thermometer: −5 °C is colder, so lower, than −2 °C","Telling the student that the rule for negatives is the opposite","Counting objects in groups of 5 and 2 and comparing the groups","Adding −5 and −2 on paper and comparing with 5 + 2"],"answer":0,"explanation":"A vertical number line such as a thermometer shows that numbers further below zero are smaller, giving meaning to the order of negative integers.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 6 का एक विद्यार्थी कहता है कि −5, −2 से बड़ा है ‘क्योंकि 5, 2 से बड़ा है’। कौन-सा संदर्भ इस विचार को ठीक करने में सबसे अधिक सहायक है?","optionsHi":["थर्मामीटर: −5 °C, −2 °C से अधिक ठंडा है, इसलिए नीचे है","विद्यार्थी को बताना कि ऋणात्मक संख्याओं का नियम उलटा होता है","5 और 2 के समूहों में वस्तुएँ गिनना और समूहों की तुलना करना","कागज़ पर −5 और −2 को जोड़ना और 5 + 2 से तुलना करना"],"explanationHi":"थर्मामीटर जैसी ऊर्ध्वाधर संख्या-रेखा दिखाती है कि शून्य से जितनी नीचे संख्या होती है, वह उतनी छोटी होती है, जिससे ऋणात्मक पूर्णांकों के क्रम को अर्थ मिलता है।"},
  {"id":"cdp-pedagogy-subjects-191","question":"Most students in a class claim that if a price is increased by 20% and then decreased by 20%, it returns to the original price. The best teaching move is to:","options":["Tell them they are wrong and give the formula to apply","Skip the problem as too advanced for this class level","Ask them to memorise that successive changes are not additive","Ask them to try it with ₹100 (→ ₹120 → ₹96) and explain why"],"answer":3,"explanation":"Working with a concrete value reveals the result and shows why: the 20% decrease is taken on ₹120, not ₹100. Students then construct the idea of a changing base themselves.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा के अधिकांश विद्यार्थी दावा करते हैं कि यदि किसी कीमत को 20% बढ़ाया जाए और फिर 20% घटाया जाए, तो वह मूल कीमत पर लौट आती है। सबसे अच्छा शिक्षण-कदम है:","optionsHi":["उन्हें बताना कि वे गलत हैं और लागू करने के लिए सूत्र देना","समस्या को इस कक्षा-स्तर के लिए बहुत उन्नत मानकर छोड़ देना","उनसे याद करने को कहना कि क्रमिक परिवर्तन योगात्मक नहीं होते","उनसे ₹100 (→ ₹120 → ₹96) के साथ करके देखने और कारण समझाने को कहना"],"explanationHi":"मूर्त मान के साथ काम करने से परिणाम और उसका कारण दोनों सामने आ जाते हैं: 20% की कमी ₹120 पर ली जाती है, ₹100 पर नहीं। इस प्रकार विद्यार्थी बदलते आधार का विचार स्वयं निर्मित करते हैं।"},
  {"id":"cdp-pedagogy-subjects-192","question":"A recipe for 4 people needs 6 cups of rice. Asked how much is needed for 6 people, a child says 8 cups ‘because 2 more people means 2 more cups’. The correct amount and the child’s difficulty are:","options":["9 cups; the child is adding instead of reasoning proportionally","8 cups; the child is right, since 2 more people need 2 more cups","10 cups; the child has made a counting error of two cups","12 cups; the child should double the amount for more people"],"answer":0,"explanation":"Each person needs 6 ÷ 4 = 1.5 cups, so 6 people need 9 cups. Adding a fixed difference instead of keeping the ratio is the most common error in proportional reasoning.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"4 लोगों के लिए एक व्यंजन-विधि में 6 कप चावल चाहिए। 6 लोगों के लिए कितना चाहिए, यह पूछने पर एक बच्चा 8 कप कहता है ‘क्योंकि 2 लोग और, यानी 2 कप और’। सही मात्रा और बच्चे की कठिनाई हैं:","optionsHi":["9 कप; बच्चा समानुपातिक तर्क करने के बजाय जोड़ रहा है","8 कप; बच्चा सही है, क्योंकि 2 और लोगों के लिए 2 कप और चाहिए","10 कप; बच्चे ने दो कप की गिनती की त्रुटि की है","12 कप; अधिक लोगों के लिए बच्चे को मात्रा दोगुनी करनी चाहिए"],"explanationHi":"प्रत्येक व्यक्ति को 6 ÷ 4 = 1.5 कप चाहिए, इसलिए 6 लोगों को 9 कप चाहिए। अनुपात बनाए रखने के बजाय एक निश्चित अंतर जोड़ना समानुपातिक तर्क में सबसे आम त्रुटि है।"},
  {"id":"cdp-pedagogy-subjects-193","question":"To help Class 4 children understand symmetry, the most suitable activity is:","options":["Writing the definition of a line of symmetry five times","Folding cut-outs and ink-blot patterns to see if the halves match","Reading the chapter on symmetry silently and underlining terms","Measuring the angles of a square and a rectangle with a protractor"],"answer":1,"explanation":"Folding and matching halves gives a direct, hands-on experience of reflection symmetry that children can then look for in letters, leaves and rangoli.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 4 के बच्चों को सममिति समझाने के लिए सबसे उपयुक्त गतिविधि है:","optionsHi":["सममिति रेखा की परिभाषा पाँच बार लिखना","कटे हुए आकारों और स्याही के धब्बों के प्रतिरूपों को मोड़कर देखना कि दोनों भाग मिलते हैं या नहीं","सममिति के अध्याय को मौन पढ़ना और पदों को रेखांकित करना","चाँदे से वर्ग और आयत के कोण मापना"],"explanationHi":"मोड़कर भागों को मिलाना परावर्तन सममिति का प्रत्यक्ष, हाथों से किया जाने वाला अनुभव देता है, जिसे बच्चे फिर अक्षरों, पत्तियों और रंगोली में खोज सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-194","question":"A child finds the area of a 4 cm by 3 cm rectangle and writes ‘12 cm’. The teacher’s best response is to:","options":["Deduct a mark for the wrong unit and move on to the next sum","Explain again that the formula for area is length × breadth","Let her tile it with 1 cm squares and count, to see units of area","Ask her to measure the sides again more carefully with a ruler"],"answer":2,"explanation":"The number is right but the unit shows she does not yet see area as the number of unit squares covering a surface; tiling builds this meaning of cm².","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक बच्ची 4 cm × 3 cm के आयत का क्षेत्रफल निकालती है और ‘12 cm’ लिखती है। शिक्षक की सबसे अच्छी प्रतिक्रिया है:","optionsHi":["गलत इकाई के लिए एक अंक काटकर अगले प्रश्न पर बढ़ जाना","फिर से समझाना कि क्षेत्रफल का सूत्र लंबाई × चौड़ाई है","उसे 1 cm के वर्गों से उसे ढकने और गिनने देना, ताकि वह क्षेत्रफल की इकाइयाँ देख सके","उससे पैमाने से भुजाएँ फिर से अधिक सावधानी से मापने को कहना"],"explanationHi":"संख्या सही है, लेकिन इकाई दिखाती है कि वह अभी क्षेत्रफल को किसी सतह को ढकने वाले इकाई वर्गों की संख्या के रूप में नहीं देखती; टाइलिंग से cm² का यह अर्थ बनता है।"},
  {"id":"cdp-pedagogy-subjects-195","question":"A teacher studies symmetry and patterns through the rangoli, kolam and weaving designs that children’s families make at home. This approach is best described as:","options":["Rote learning of geometric terms through a few cultural examples","Recreational mathematics with no link to the syllabus","Avoiding formal geometry in favour of craft activities","Ethnomathematics, linking school maths with cultural practices"],"answer":3,"explanation":"Ethnomathematics recognises mathematical ideas in everyday cultural practices; using them links school maths to children’s lives, as NCF 2005 recommends.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षक सममिति और पैटर्न का अध्ययन रंगोली, कोलम और बुनाई के उन डिज़ाइनों के माध्यम से कराता है जो बच्चों के परिवार घर पर बनाते हैं। इस उपागम का सबसे अच्छा वर्णन है:","optionsHi":["कुछ सांस्कृतिक उदाहरणों के माध्यम से ज्यामितीय पदों को रटना","मनोरंजक गणित, जिसका पाठ्यक्रम से कोई संबंध नहीं","औपचारिक ज्यामिति से बचकर शिल्प-गतिविधियों को प्राथमिकता देना","नृ-गणित (एथनोमैथेमैटिक्स), जो विद्यालयी गणित को सांस्कृतिक प्रथाओं से जोड़ता है"],"explanationHi":"नृ-गणित रोज़मर्रा की सांस्कृतिक प्रथाओं में गणितीय विचारों को पहचानता है; उनका उपयोग विद्यालयी गणित को बच्चों के जीवन से जोड़ता है, जैसा NCF 2005 अनुशंसित करता है।"},
  {"id":"cdp-pedagogy-subjects-196","question":"A shop offers ‘Buy 2, get 1 free’ while another offers ‘30% off’ on the same item. Which question built on this situation best assesses application and reasoning in Class 7?","options":["‘Which offer is better on 3 items? Show your reasoning.’","‘Define percentage and give one example of it.’","‘Write 30% as a fraction in its lowest terms.’","‘What is 30% of ₹100? Write the answer in rupees and paise.’"],"answer":0,"explanation":"Comparing offers needs students to see that ‘buy 2, get 1 free’ is a 1/3 (about 33.3%) discount on 3 items, better than 30%; the other items test recall or routine calculation.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"एक दुकान ‘2 खरीदें, 1 मुफ़्त पाएँ’ का प्रस्ताव देती है जबकि दूसरी उसी वस्तु पर ‘30% छूट’ देती है। इस स्थिति पर आधारित कौन-सा प्रश्न कक्षा 7 में अनुप्रयोग और तर्क का सबसे अच्छा आकलन करता है?","optionsHi":["‘3 वस्तुओं पर कौन-सा प्रस्ताव बेहतर है? अपना तर्क दिखाइए।’","‘प्रतिशत की परिभाषा दीजिए और उसका एक उदाहरण दीजिए।’","‘30% को उसके सरलतम रूप में भिन्न के रूप में लिखिए।’","‘30% की गणना ₹100 पर कीजिए। उत्तर को रुपये और पैसे में लिखिए।’"],"explanationHi":"प्रस्तावों की तुलना के लिए विद्यार्थियों को यह देखना होता है कि ‘2 खरीदें, 1 मुफ़्त’ 3 वस्तुओं पर 1/3 (लगभग 33.3%) की छूट है, जो 30% से बेहतर है; अन्य प्रश्न स्मरण या नियमित गणना की जाँच करते हैं।"},
  {"id":"cdp-pedagogy-subjects-197","question":"At the end of a maths lesson, each child writes on a slip one thing she learnt and one question she still has, and hands it to the teacher on the way out. The teacher uses the slips to plan the next lesson. This practice is:","options":["A summative assessment at the end of the unit","A norm-referenced test comparing children","An exit slip used for formative assessment","A diagnostic test of general intelligence"],"answer":2,"explanation":"Exit slips give quick evidence of what children understood and where they are stuck, which the teacher uses to adjust teaching, the defining use of formative assessment.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"गणित के पाठ के अंत में हर बच्ची एक पर्ची पर लिखती है कि उसने एक चीज़ क्या सीखी और उसका एक प्रश्न क्या है, और बाहर जाते समय उसे शिक्षक को दे देती है। शिक्षक पर्चियों का उपयोग अगले पाठ की योजना बनाने के लिए करता है। यह अभ्यास है:","optionsHi":["इकाई के अंत में योगात्मक आकलन","बच्चों की तुलना करने वाला मानक-संदर्भित परीक्षण","रचनात्मक आकलन के लिए प्रयुक्त निकास-पर्ची (एग्ज़िट स्लिप)","सामान्य बुद्धि का निदानात्मक परीक्षण"],"explanationHi":"निकास-पर्चियाँ इस बात का त्वरित प्रमाण देती हैं कि बच्चों ने क्या समझा और वे कहाँ अटके हैं, जिसका शिक्षक शिक्षण को समायोजित करने के लिए उपयोग करता है; यही रचनात्मक आकलन का निर्णायक उपयोग है।"},
  {"id":"cdp-pedagogy-subjects-198","question":"In a Class 5 class of mixed abilities, which task is best suited to engage all learners in mathematics?","options":["A worksheet of 30 identical sums for everyone to finish","A low-floor, high-ceiling task, such as making rectangles from 24 tiles","Separate worksheets for ‘weak’ and ‘bright’ students with no shared work","A speed test of multiplication tables for the whole class"],"answer":1,"explanation":"Low-floor, high-ceiling tasks let every child start easily and allow able learners to go much deeper (all factor pairs, patterns in perimeter), supporting inclusion without labelling.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"कक्षा 5 की मिश्रित क्षमताओं वाली कक्षा में गणित में सभी अधिगमकर्ताओं को जोड़ने के लिए कौन-सा कार्य सबसे उपयुक्त है?","optionsHi":["सभी के पूरा करने के लिए 30 एक जैसे प्रश्नों का अभ्यास-पत्र","निम्न-आरंभ, उच्च-सीमा (लो-फ़्लोर, हाई-सीलिंग) वाला कार्य, जैसे 24 टाइलों से आयत बनाना","‘कमज़ोर’ और ‘तेज़’ विद्यार्थियों के लिए अलग-अलग अभ्यास-पत्र, बिना किसी साझा कार्य के","पूरी कक्षा के लिए पहाड़ों की गति-परीक्षा"],"explanationHi":"निम्न-आरंभ, उच्च-सीमा वाले कार्य हर बच्चे को आसानी से शुरू करने देते हैं और सक्षम अधिगमकर्ताओं को बहुत गहराई तक जाने देते हैं (सभी गुणनखंड-युग्म, परिमाप में पैटर्न), जिससे बिना ठप्पा लगाए समावेशन को सहारा मिलता है।"},
  {"id":"cdp-pedagogy-subjects-199","question":"Many Class 7 students believe that ‘plants breathe in carbon dioxide in the day and respire only at night’. Which statement should the teacher help them reach?","options":["Plants photosynthesise only at night, when it is cool","Plants do not respire at all, they only photosynthesise","The students are right: plants respire only after dark","Plants respire day and night; in light, photosynthesis is faster"],"answer":3,"explanation":"Respiration goes on continuously in all living cells; in daylight it is masked by faster photosynthesis. The misconception confuses net gas exchange with the processes themselves.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 7 के कई विद्यार्थी मानते हैं कि ‘पौधे दिन में कार्बन डाइऑक्साइड लेते हैं और केवल रात में श्वसन करते हैं’। शिक्षक को उन्हें किस कथन तक पहुँचने में सहायता करनी चाहिए?","optionsHi":["पौधे केवल रात में प्रकाश संश्लेषण करते हैं, जब ठंडक होती है","पौधे श्वसन बिल्कुल नहीं करते, वे केवल प्रकाश संश्लेषण करते हैं","विद्यार्थी सही हैं: पौधे केवल अँधेरा होने के बाद श्वसन करते हैं","पौधे दिन-रात श्वसन करते हैं; प्रकाश में प्रकाश संश्लेषण तेज़ होता है"],"explanationHi":"श्वसन सभी जीवित कोशिकाओं में निरंतर चलता रहता है; दिन के प्रकाश में वह तेज़ प्रकाश संश्लेषण के कारण दब जाता है। यह भ्रांत धारणा गैसों के शुद्ध विनिमय को स्वयं प्रक्रियाओं से मिला देती है।"},
  {"id":"cdp-pedagogy-subjects-200","question":"A Class 6 student explains that we see a book because ‘light goes out from our eyes to the book’. Which activity best challenges this idea?","options":["Reading and copying the definition of reflection of light","Telling the student that the idea is ancient and wrong","Looking at objects in a totally dark room with eyes open","Drawing the eye and labelling its parts correctly"],"answer":2,"explanation":"If eyes sent out light, we could see in total darkness. The experience leads to the idea that light from a source is reflected by objects into our eyes.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 6 का एक विद्यार्थी समझाता है कि हम पुस्तक इसलिए देखते हैं क्योंकि ‘प्रकाश हमारी आँखों से निकलकर पुस्तक तक जाता है’। कौन-सी गतिविधि इस विचार को सबसे अच्छी तरह चुनौती देती है?","optionsHi":["प्रकाश के परावर्तन की परिभाषा पढ़ना और उतारना","विद्यार्थी को बताना कि यह विचार प्राचीन और गलत है","पूर्णतः अँधेरे कमरे में आँखें खोलकर वस्तुओं को देखने का प्रयास करना","आँख का चित्र बनाना और उसके भागों को सही-सही नामांकित करना"],"explanationHi":"यदि आँखें प्रकाश बाहर भेजतीं, तो हम पूर्ण अंधकार में भी देख पाते। यह अनुभव इस विचार तक ले जाता है कि किसी स्रोत का प्रकाश वस्तुओं से परावर्तित होकर हमारी आँखों में पहुँचता है।"},
  {"id":"cdp-pedagogy-subjects-201","question":"Which school practice best develops children’s concern for the environment, as intended in EVS?","options":["A school garden, waste segregation and tracking water use","Children copy a list of ‘do’s and don’ts’ for the environment","Children write an essay on pollution from a guidebook","Children memorise the names of environmental laws"],"answer":0,"explanation":"Attitudes develop through participation and reflection on real action; copying rules or memorising information rarely changes behaviour.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"EVS में अभिप्रेत बच्चों में पर्यावरण के प्रति सरोकार को कौन-सी विद्यालयी गतिविधि सबसे अच्छी तरह विकसित करती है?","optionsHi":["विद्यालय की बगिया, कचरे का पृथक्करण और जल-उपयोग का आकलन","बच्चे पर्यावरण के लिए ‘क्या करें, क्या न करें’ की सूची उतारें","बच्चे किसी गाइड-पुस्तक से प्रदूषण पर निबंध लिखें","बच्चे पर्यावरण संबंधी कानूनों के नाम याद करें"],"explanationHi":"दृष्टिकोण वास्तविक कार्य में भागीदारी और उस पर चिंतन से विकसित होते हैं; नियम उतारने या जानकारी रटने से व्यवहार शायद ही बदलता है।"},
  {"id":"cdp-pedagogy-subjects-202","question":"Class 5 children prepare a puppet show to explain the water cycle, writing the dialogue and making the puppets themselves. Under NEP 2020, this is an example of:","options":["Rote learning through repeated rehearsal of lines","Art-integrated learning, using an art form to learn a concept","Co-scholastic activity that is unrelated to the EVS concept itself","Summative assessment of the water cycle unit"],"answer":1,"explanation":"NEP 2020 recommends art-integrated education, using the arts as a medium for learning concepts across subjects, which also builds creativity and communication.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 5 के बच्चे जल-चक्र समझाने के लिए कठपुतली का खेल तैयार करते हैं, संवाद लिखते हैं और कठपुतलियाँ स्वयं बनाते हैं। NEP 2020 के अंतर्गत यह किसका उदाहरण है?","optionsHi":["संवादों के बार-बार अभ्यास से रटकर सीखना","कला-एकीकृत अधिगम, जिसमें किसी संप्रत्यय को सीखने के लिए कला-रूप का उपयोग किया जाता है","सह-शैक्षिक गतिविधि जिसका EVS की अवधारणा से कोई संबंध नहीं है","जल-चक्र इकाई का योगात्मक आकलन"],"explanationHi":"NEP 2020 कला-एकीकृत शिक्षा की अनुशंसा करती है, जिसमें विषयों में संप्रत्ययों को सीखने के माध्यम के रूप में कलाओं का उपयोग किया जाता है, जो रचनात्मकता और संप्रेषण भी विकसित करता है।"},
  {"id":"cdp-pedagogy-subjects-203","question":"Which practice best reflects the play-based and toy-based pedagogy that NEP 2020 recommends for the foundational stage?","options":["Daily worksheets of letter and number writing for regular practice","Long lectures followed by question-answer sessions","Learning counting and sorting with local toys, games and puzzles","Homework with copying of textbook pages each evening"],"answer":2,"explanation":"For ages 3–8 NEP 2020 favours flexible, play-, toy- and activity-based learning in which concepts grow through hands-on exploration and talk.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कौन-सा अभ्यास आधारभूत चरण के लिए NEP 2020 द्वारा अनुशंसित खेल-आधारित और खिलौना-आधारित शिक्षाशास्त्र को सबसे अच्छी तरह दर्शाता है?","optionsHi":["नियमित अभ्यास के लिए अक्षर और संख्या लिखने के दैनिक अभ्यास-पत्र","लंबे व्याख्यान, जिनके बाद प्रश्नोत्तर सत्र","स्थानीय खिलौनों, खेलों और पहेलियों से गिनती और छँटाई सीखना","हर शाम पाठ्यपुस्तक के पन्ने उतारने का गृहकार्य"],"explanationHi":"3–8 वर्ष की आयु के लिए NEP 2020 लचीले, खेल-, खिलौना- और गतिविधि-आधारित अधिगम का पक्ष लेती है, जिसमें अवधारणाएँ हाथों से करने की खोजबीन और बातचीत से विकसित होती हैं।"},
  {"id":"cdp-pedagogy-subjects-204","question":"Why does NCF 2005 stress oral language development in the early grades before and alongside reading and writing?","options":["Because reading and writing should not be taught before Class 3","Because oral work keeps children busy and the class orderly","Because oral language is easier to assess than written work","Because spoken vocabulary and listening are the base for literacy"],"answer":3,"explanation":"Children understand in print what they already understand in speech; talk, stories and discussion build the vocabulary and comprehension that literacy depends on.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"NCF 2005 प्रारंभिक कक्षाओं में पठन और लेखन से पहले तथा उनके साथ-साथ मौखिक भाषा के विकास पर ज़ोर क्यों देता है?","optionsHi":["क्योंकि कक्षा 3 से पहले पठन और लेखन नहीं सिखाया जाना चाहिए","क्योंकि मौखिक कार्य बच्चों को व्यस्त और कक्षा को व्यवस्थित रखता है","क्योंकि मौखिक भाषा का आकलन लिखित कार्य से आसान होता है","क्योंकि बोली जाने वाली शब्दावली और सुनना साक्षरता का आधार हैं"],"explanationHi":"बच्चे छपे हुए में वही समझते हैं जो वे बोलचाल में पहले से समझते हैं; बातचीत, कहानियाँ और चर्चा वह शब्दावली और बोध निर्मित करती हैं जिन पर साक्षरता निर्भर है।"},
  {"id":"cdp-pedagogy-subjects-205","question":"A Class 7 teacher regularly reads aloud chapters from a novel that is somewhat above her students’ independent reading level. The main purpose of this practice is to:","options":["Model rich language and fluent reading, and motivate reading","Test their spelling of the new words in the novel","Replace the need for students to read independently","Fill time at the end of the day when the regular lessons are over"],"answer":0,"explanation":"Read-alouds model fluency and expression and give access to vocabulary and ideas beyond what children can yet read alone, building interest in reading.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 7 की एक शिक्षिका नियमित रूप से किसी उपन्यास के अध्याय ज़ोर से पढ़कर सुनाती है, जो उसके विद्यार्थियों के स्वतंत्र पठन-स्तर से कुछ ऊपर है। इस अभ्यास का मुख्य उद्देश्य है:","optionsHi":["समृद्ध भाषा और धाराप्रवाह पठन का आदर्श प्रस्तुत करना और पढ़ने के लिए प्रेरित करना","उपन्यास के नए शब्दों की वर्तनी की जाँच करना","विद्यार्थियों के स्वतंत्र रूप से पढ़ने की आवश्यकता को समाप्त करना","दिन के अंत में, जब नियमित पाठ समाप्त हो जाएँ, समय भरना"],"explanationHi":"ज़ोर से पढ़कर सुनाना प्रवाह और भाव का आदर्श प्रस्तुत करता है और बच्चों को उस शब्दावली और विचारों तक पहुँच देता है जो वे अभी अकेले नहीं पढ़ सकते, जिससे पढ़ने में रुचि बनती है।"},
  {"id":"cdp-pedagogy-subjects-206","question":"A Class 3 child asks, ‘Why does the moon change its shape?’ The teacher is not sure of the answer. The most appropriate response is:","options":["‘That is not in our syllabus, so focus on the lesson.’","‘You will learn it in higher classes, when you are a little older.’","‘It is God’s wish, and we should not question it.’","‘I am not sure. Let us watch the moon each night and find out.’"],"answer":3,"explanation":"Valuing questions, admitting uncertainty and investigating together models a scientific attitude and encourages children’s curiosity.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 3 का एक बच्चा पूछता है, ‘चाँद अपना आकार क्यों बदलता है?’ शिक्षक को उत्तर पक्का पता नहीं है। सबसे उपयुक्त प्रतिक्रिया है:","optionsHi":["‘यह हमारे पाठ्यक्रम में नहीं है, इसलिए पाठ पर ध्यान दो।’","‘जब तुम थोड़े बड़े हो जाओगे, तब ऊँची कक्षाओं में सीखोगे।’","‘यह ईश्वर की इच्छा है, और हमें प्रश्न नहीं करना चाहिए।’","‘मुझे पक्का नहीं पता। आओ हम हर रात चाँद को देखें और पता लगाएँ।’"],"explanationHi":"प्रश्नों को महत्त्व देना, अनिश्चितता स्वीकार करना और साथ मिलकर खोजबीन करना वैज्ञानिक दृष्टिकोण का आदर्श प्रस्तुत करता है और बच्चों की जिज्ञासा को प्रोत्साहित करता है।"},
  {"id":"cdp-pedagogy-subjects-207","question":"Class 4 children count and record the kinds of trees around the school in a table and then make a simple bar graph. Which statement best describes the pedagogy?","options":["It is purely an EVS activity unrelated to mathematics","It integrates EVS and mathematics through real data handling","It is mainly a handwriting and table-drawing exercise","It should be done only after children learn graphs formally"],"answer":1,"explanation":"Collecting real data about their environment and representing it links EVS content with data handling, giving meaning to both.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 4 के बच्चे विद्यालय के आसपास के पेड़ों के प्रकार गिनकर एक तालिका में दर्ज करते हैं और फिर एक सरल दंड आलेख बनाते हैं। कौन-सा कथन इस शिक्षाशास्त्र का सबसे अच्छा वर्णन करता है?","optionsHi":["यह पूरी तरह EVS की गतिविधि है, जिसका गणित से कोई संबंध नहीं","यह वास्तविक आँकड़ों के प्रबंधन के माध्यम से EVS और गणित को एकीकृत करता है","यह मुख्य रूप से हस्तलेखन और तालिका बनाने का अभ्यास है","इसे बच्चों के आलेख औपचारिक रूप से सीखने के बाद ही करना चाहिए"],"explanationHi":"अपने पर्यावरण के बारे में वास्तविक आँकड़े इकट्ठा करना और उन्हें निरूपित करना EVS की विषय-वस्तु को आँकड़ा-प्रबंधन से जोड़ता है, जिससे दोनों को अर्थ मिलता है।"},
  {"id":"cdp-pedagogy-subjects-208","question":"During a Class 8 practical on preparing a slide of onion peel, which tool would best assess students’ practical skills?","options":["A multiple-choice test on the parts of a plant cell","An essay on the history and parts of the microscope","An observation checklist used while students do the practical","Asking students to copy the onion-peel diagram from the book"],"answer":2,"explanation":"Practical skills are best judged as they are performed; a checklist of key steps makes such observation systematic. Written tests check knowledge about the practical, not the skill.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"प्याज़ के छिलके की स्लाइड तैयार करने के कक्षा 8 के प्रायोगिक कार्य के दौरान, विद्यार्थियों के प्रायोगिक कौशल का आकलन करने के लिए कौन-सा उपकरण सबसे उपयुक्त होगा?","optionsHi":["पादप कोशिका के भागों पर बहुविकल्पीय परीक्षण","सूक्ष्मदर्शी के इतिहास और भागों पर निबंध","विद्यार्थियों के प्रायोगिक कार्य करते समय प्रयुक्त अवलोकन जाँच-सूची","विद्यार्थियों से पुस्तक से प्याज़ के छिलके का चित्र उतारने को कहना"],"explanationHi":"प्रायोगिक कौशल का मूल्यांकन उन्हें करते समय ही सबसे अच्छी तरह किया जाता है; मुख्य चरणों की जाँच-सूची ऐसे अवलोकन को व्यवस्थित बनाती है। लिखित परीक्षाएँ प्रयोग के बारे में ज्ञान जाँचती हैं, कौशल नहीं।"},
  {"id":"cdp-pedagogy-subjects-209","question":"When asked to draw a scientist, most children in a class draw an old man in a white coat. The teacher’s most suitable follow-up is to:","options":["Accept it, since most scientists are men anyway","Ignore the drawings, as they are not part of the prescribed syllabus","Ask only the girls to draw a woman scientist instead","Share stories of diverse scientists and discuss who can be one"],"answer":3,"explanation":"‘Draw-a-scientist’ reveals stereotypes; showing diverse role models helps all children, especially girls, see science as something they can do.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"वैज्ञानिक का चित्र बनाने को कहने पर कक्षा के अधिकांश बच्चे सफ़ेद कोट पहने एक बूढ़े आदमी का चित्र बनाते हैं। शिक्षक का सबसे उपयुक्त अनुवर्ती कदम है:","optionsHi":["इसे स्वीकार करना, क्योंकि अधिकांश वैज्ञानिक वैसे भी पुरुष होते हैं","चित्रों को अनदेखा करना, क्योंकि वे निर्धारित पाठ्यक्रम का भाग नहीं हैं","केवल लड़कियों से इसके बजाय महिला वैज्ञानिक का चित्र बनाने को कहना","विविध वैज्ञानिकों की कहानियाँ साझा करना और चर्चा करना कि कौन वैज्ञानिक बन सकता है"],"explanationHi":"‘वैज्ञानिक का चित्र बनाओ’ रूढ़ियों को प्रकट करता है; विविध आदर्श व्यक्तित्व दिखाने से सभी बच्चों को, विशेषकर लड़कियों को, विज्ञान को ऐसी चीज़ के रूप में देखने में मदद मिलती है जो वे कर सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-210","question":"Class 5 students who read stories easily struggle with an EVS text explaining how the monsoon causes floods. The most useful support is to:","options":["Teach cause–effect text structure using a graphic organiser","Tell them to read the text three more times until it is clear","Replace the text with a story on the same topic","Ask them to memorise the paragraph for the test"],"answer":0,"explanation":"Expository texts are organised differently from stories; explicitly teaching text structures with graphic organisers improves comprehension of informational writing.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 5 के जो विद्यार्थी कहानियाँ आसानी से पढ़ लेते हैं, उन्हें यह समझाने वाले EVS पाठ में कठिनाई होती है कि मानसून बाढ़ का कारण कैसे बनता है। सबसे उपयोगी सहायता है:","optionsHi":["ग्राफ़िक आयोजक की सहायता से कारण–प्रभाव पाठ-संरचना सिखाना","उनसे कहना कि पाठ को तीन बार और पढ़ें जब तक स्पष्ट न हो जाए","पाठ को उसी विषय की कहानी से बदल देना","उनसे परीक्षा के लिए अनुच्छेद याद करने को कहना"],"explanationHi":"सूचनात्मक पाठ कहानियों से भिन्न ढंग से संगठित होते हैं; ग्राफ़िक आयोजकों के साथ पाठ-संरचनाओं को स्पष्ट रूप से सिखाने से सूचनात्मक लेखन का बोध बेहतर होता है।"},
  {"id":"cdp-pedagogy-subjects-211","question":"A Class 2 teacher shows ‘5 − 3’ with five beads, removing three, and later a child is puzzled by ‘Raju has 5 marbles and Sita has 3. How many more does Raju have?’ The teacher should realise that:","options":["The child cannot subtract and needs more drill","Subtraction also means comparing, not only taking away","The comparison problem is too hard for Class 2 and should be removed","Beads should never be used for teaching subtraction"],"answer":1,"explanation":"Take-away, comparison (difference) and missing-addend situations all use subtraction; children who meet only take-away often cannot recognise the others.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 2 का एक शिक्षक पाँच मनकों से ‘5 − 3’ दिखाता है, उनमें से तीन हटाकर, और बाद में एक बच्चा ‘राजू के पास 5 कंचे हैं और सीता के पास 3। राजू के पास कितने अधिक हैं?’ से उलझन में पड़ जाता है। शिक्षक को यह समझना चाहिए कि:","optionsHi":["बच्चा घटा नहीं सकता और उसे और अभ्यास चाहिए","घटाव का अर्थ तुलना करना भी है, केवल हटाना नहीं","तुलना वाली समस्या कक्षा 2 के लिए बहुत कठिन है और उसे हटा देना चाहिए","घटाव सिखाने के लिए मनकों का उपयोग कभी नहीं करना चाहिए"],"explanationHi":"हटाना, तुलना (अंतर) और लुप्त योज्य की स्थितियाँ सभी घटाव का उपयोग करती हैं; जो बच्चे केवल हटाने वाली स्थिति से मिले हैं, वे अक्सर अन्य स्थितियों को पहचान नहीं पाते।"},
  {"id":"cdp-pedagogy-subjects-212","question":"Which of these is the strongest reason for using a number line when teaching addition of fractions such as 1/4 + 1/2?","options":["It avoids the need for a common denominator when adding","It is easier and quicker to draw than circles or rectangular strips","It shows fractions as numbers with size, so sums can be judged","It is what the textbook uses, so it must be followed"],"answer":2,"explanation":"Area models present fractions as parts of shapes; the number line shows them as numbers on a continuum, supporting estimation and reasoning about the size of sums.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"1/4 + 1/2 जैसी भिन्नों के योग को सिखाते समय संख्या-रेखा के उपयोग का इनमें से सबसे मज़बूत कारण क्या है?","optionsHi":["यह जोड़ते समय समान हर की आवश्यकता से बचाती है","इसे वृत्तों या आयताकार पट्टियों की तुलना में बनाना आसान और तेज़ है","यह भिन्नों को आकार वाली संख्याओं के रूप में दिखाती है, जिससे योगों का आकलन किया जा सकता है","पाठ्यपुस्तक इसी का उपयोग करती है, इसलिए इसका पालन करना चाहिए"],"explanationHi":"क्षेत्रफल मॉडल भिन्नों को आकृतियों के भागों के रूप में प्रस्तुत करते हैं; संख्या-रेखा उन्हें सतत रेखा पर संख्याओं के रूप में दिखाती है, जिससे योगों के आकार के अनुमान और तर्क को सहारा मिलता है।"},
  {"id":"cdp-pedagogy-subjects-213","question":"How many of the following match the NCF 2005 recommendations for assessment in mathematics? I. Assess the processes children use, not only the final answer. II. Use mainly speed tests of procedures. III. Include tasks that ask children to explain and justify. IV. Use assessment to understand children’s thinking and plan teaching.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV are recommended. NCF 2005 criticises assessment that rewards only speed and memorised procedures.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"गणित में आकलन के लिए NCF 2005 की सिफ़ारिशों से निम्नलिखित में से कितने मेल खाते हैं? I. बच्चों द्वारा उपयोग की गई प्रक्रियाओं का आकलन करें, केवल अंतिम उत्तर का नहीं। II. मुख्य रूप से प्रक्रियाओं की गति-परीक्षाओं का उपयोग करें। III. ऐसे कार्य शामिल करें जिनमें बच्चों से समझाने और औचित्य बताने को कहा जाए। IV. बच्चों की सोच को समझने और शिक्षण की योजना बनाने के लिए आकलन का उपयोग करें।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, III और IV की अनुशंसा की गई है। NCF 2005 उस आकलन की आलोचना करता है जो केवल गति और रटी हुई प्रक्रियाओं को पुरस्कृत करता है।"},
  {"id":"cdp-pedagogy-subjects-214","question":"Assertion (A): In the primary classes, children should be allowed to solve word problems using drawings and their own methods before formal symbols are required. Reason (R): Representing a situation in their own way helps children understand the problem and connect it later to standard notation.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Children’s own representations (drawings, objects, informal notation) build understanding of the structure of a problem, which then gives meaning to formal symbols.","difficulty":"hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): प्राथमिक कक्षाओं में बच्चों को औपचारिक प्रतीकों की आवश्यकता से पहले चित्रों और अपनी विधियों से शब्द-प्रश्न हल करने की अनुमति दी जानी चाहिए। कारण (R): किसी स्थिति को अपने तरीके से निरूपित करने से बच्चों को समस्या समझने और बाद में उसे मानक संकेतन से जोड़ने में मदद मिलती है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"बच्चों के अपने निरूपण (चित्र, वस्तुएँ, अनौपचारिक संकेतन) समस्या की संरचना की समझ बनाते हैं, जो फिर औपचारिक प्रतीकों को अर्थ देती है।"},
  {"id":"cdp-pedagogy-subjects-215","question":"A Class 8 science teacher wants students to understand how a hypothesis differs from a guess. Which task serves this best?","options":["Writing and learning the definition of a hypothesis","Reading about famous inventions and their inventors","Framing a testable ‘if…then’ statement and designing a fair test","Memorising the steps of the scientific method in the correct order"],"answer":2,"explanation":"A hypothesis is a testable, reasoned prediction about a relationship between variables; framing one and planning how to test it shows the difference from a mere guess.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 8 का एक विज्ञान शिक्षक चाहता है कि विद्यार्थी समझें कि परिकल्पना अनुमान से कैसे भिन्न है। कौन-सा कार्य इसमें सबसे अधिक सहायक है?","optionsHi":["परिकल्पना की परिभाषा लिखना और सीखना","प्रसिद्ध आविष्कारों और उनके आविष्कारकों के बारे में पढ़ना","परीक्षण-योग्य ‘यदि…तो’ कथन बनाना और निष्पक्ष परीक्षण की रूपरेखा तैयार करना","वैज्ञानिक विधि के चरणों को सही क्रम में याद करना"],"explanationHi":"परिकल्पना चरों के बीच संबंध के बारे में परीक्षण-योग्य, तर्कसंगत पूर्वानुमान है; एक बनाना और उसे परखने की योजना बनाना इसे मात्र अनुमान से अलग दिखाता है।"},
  {"id":"cdp-pedagogy-subjects-216","question":"Which of the following is the best example of a ‘higher-order’ EVS question for Class 5 on the topic of animals?","options":["‘Name three animals that live in water, like the fish and the crab.’","‘Which animal is known as the ship of the desert?’","‘How many legs does an insect such as an ant have?’","‘If a pond’s frogs vanished, what might happen to its insects?’"],"answer":3,"explanation":"Predicting the effect of a change on a food web requires analysis and reasoning about relationships, unlike recall questions.","difficulty":"hard","source":"CTET · State TETs","questionHi":"जानवरों के विषय पर कक्षा 5 के लिए ‘उच्च-स्तरीय’ EVS प्रश्न का सबसे अच्छा उदाहरण निम्नलिखित में से कौन-सा है?","optionsHi":["‘पानी में रहने वाले तीन जानवरों के नाम बताइए, जैसे मछली और केकड़ा।’","‘किस जानवर को रेगिस्तान का जहाज़ कहा जाता है?’","‘चींटी जैसे कीट के कितने पैर होते हैं?’","‘यदि किसी तालाब के मेंढक गायब हो जाएँ, तो उसके कीटों का क्या हो सकता है?’"],"explanationHi":"किसी परिवर्तन का खाद्य जाल पर प्रभाव पूर्वानुमानित करने के लिए संबंधों पर विश्लेषण और तर्क की आवश्यकता होती है, स्मरण वाले प्रश्नों के विपरीत।"},
  {"id":"cdp-pedagogy-subjects-217","question":"A teacher asks Class 6 students to estimate the number of beans in a jar before counting them, and then discuss how close each estimate was and how they made it. The main value of this activity is that it:","options":["Builds estimation strategies and number sense, like sampling","Teaches exact and careful counting of large sets","Is a time-filler with no real mathematical value","Helps the teacher find the fastest and most accurate counter"],"answer":0,"explanation":"Estimating and comparing strategies (counting a layer and multiplying, for example) builds number sense and reasoning about quantity that exact calculation alone does not.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"एक शिक्षक कक्षा 6 के विद्यार्थियों से एक मर्तबान में सेम के बीजों की संख्या गिनने से पहले उसका अनुमान लगाने को कहता है, और फिर चर्चा करवाता है कि हर अनुमान कितना सटीक था और उन्होंने उसे कैसे लगाया। इस गतिविधि का मुख्य मूल्य यह है कि वह:","optionsHi":["प्रतिचयन जैसी अनुमान की रणनीतियाँ और संख्या-बोध विकसित करती है","बड़े समूहों की सटीक और सावधानीपूर्ण गिनती सिखाती है","समय भरने वाली है, जिसका कोई वास्तविक गणितीय मूल्य नहीं","शिक्षक को सबसे तेज़ और सबसे सटीक गिनने वाले को खोजने में मदद करती है"],"explanationHi":"अनुमान लगाना और रणनीतियों की तुलना करना (उदाहरण के लिए, एक परत गिनकर गुणा करना) संख्या-बोध और मात्रा के बारे में तर्क का निर्माण करता है, जो केवल सटीक गणना नहीं करती।"},
  {"id":"cdp-pedagogy-subjects-218","question":"How many of these statements about the Van Hiele model are correct? I. The levels are not sequential, so a learner can reach a level without passing through the earlier ones. II. Progress from one level to the next depends more on age than on instruction and experience. III. If a teacher teaches at a level above the learners’, they may only memorise without understanding. IV. All children reach the deduction level automatically by the age of 12.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only III reflects the Van Hieles’ view. The levels are sequential, progress depends more on instruction than on age, and advancement is not automatic: many adults never reach formal deduction.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"वान हील मॉडल के बारे में इन कथनों में से कितने सही हैं? I. स्तर क्रमिक नहीं हैं, इसलिए अधिगमकर्ता पहले वाले स्तरों से गुज़रे बिना किसी स्तर तक पहुँच सकता है। II. एक स्तर से अगले स्तर तक प्रगति अनुदेशन और अनुभव की तुलना में आयु पर अधिक निर्भर करती है। III. यदि शिक्षक अधिगमकर्ताओं के स्तर से ऊपर के स्तर पर पढ़ाता है, तो वे समझे बिना केवल याद कर सकते हैं। IV. सभी बच्चे 12 वर्ष की आयु तक स्वतः निगमन स्तर तक पहुँच जाते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल III वान हील दंपति के मत को दर्शाता है। स्तर क्रमिक हैं, प्रगति आयु की तुलना में अनुदेशन पर अधिक निर्भर करती है, और उन्नति स्वतः नहीं होती: कई वयस्क कभी औपचारिक निगमन तक नहीं पहुँचते।"},
  {"id":"cdp-pedagogy-subjects-219","question":"Assertion (A): Children who are taught the long-division algorithm as a set of steps, without understanding, often make errors such as leaving out zeros in the quotient. Reason (R): Standard algorithms are efficient methods for calculation.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Both statements are true, but efficiency does not explain the errors; they arise because the steps are followed without understanding of place value and of what each step means.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"अभिकथन (A): जिन बच्चों को लंबी भाग विधि का एल्गोरिदम बिना समझे चरणों के समूह के रूप में सिखाया जाता है, वे अक्सर भागफल में शून्य छोड़ देने जैसी त्रुटियाँ करते हैं। कारण (R): मानक एल्गोरिदम गणना की कुशल विधियाँ हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"दोनों कथन सत्य हैं, लेकिन कुशलता त्रुटियों की व्याख्या नहीं करती; वे इसलिए होती हैं कि चरणों का पालन स्थानीय मान और प्रत्येक चरण के अर्थ की समझ के बिना किया जाता है।"},
  {"id":"cdp-pedagogy-subjects-220","question":"A Class 3 child writes 7 × 0 = 7. Which approach best helps the child understand the correct answer?","options":["Telling the child the rule ‘anything times zero is zero’ to remember","Asking the child to write the zero table ten times over","Asking the child to check the answer on a calculator","Using a story: ‘7 plates with no laddoos on each; how many in all?’"],"answer":3,"explanation":"Seeing 7 × 0 as 7 groups of nothing (0 + 0 + … + 0) shows why the product is 0; the error often comes from treating ×0 like +0.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 3 का एक बच्चा 7 × 0 = 7 लिखता है। कौन-सा उपागम बच्चे को सही उत्तर समझने में सबसे अधिक सहायता करता है?","optionsHi":["बच्चे को याद रखने के लिए नियम ‘किसी भी संख्या को शून्य से गुणा करने पर शून्य’ बताना","बच्चे से शून्य का पहाड़ा दस बार लिखवाना","बच्चे से कैलकुलेटर पर उत्तर जाँचने को कहना","कहानी का उपयोग करना: ‘7 थालियाँ, जिनमें से हर एक में एक भी लड्डू नहीं; कुल कितने?’"],"explanationHi":"7 × 0 को 7 समूह जिनमें कुछ नहीं है (0 + 0 + … + 0) के रूप में देखना दिखाता है कि गुणनफल 0 क्यों है; यह त्रुटि अक्सर ×0 को +0 की तरह मानने से आती है।"},
  {"id":"cdp-pedagogy-subjects-221","question":"A Class 5 child writes 0.5 + 0.25 = 0.30. What has the child most likely done?","options":["Added 5 + 25 as whole numbers, ignoring place value; correct sum 0.75","Added correctly but forgot to carry; the correct sum is 0.80","Subtracted instead of adding the two decimals; the correct sum is 0.25","Misread 0.25 as 0.025 while adding; the correct sum is 0.525"],"answer":0,"explanation":"0.5 is 5 tenths, which is 50 hundredths; 50 + 25 = 75 hundredths = 0.75. Money (₹0.50 + ₹0.25) or a hundred-square makes the place values visible.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"कक्षा 5 का एक बच्चा 0.5 + 0.25 = 0.30 लिखता है। बच्चे ने सबसे अधिक संभावना से क्या किया है?","optionsHi":["5 + 25 को पूर्ण संख्याओं के रूप में जोड़ दिया, स्थानीय मान को अनदेखा किया; सही योग 0.75","सही जोड़ा लेकिन हासिल लगाना भूल गया; सही योग 0.80 है","दोनों दशमलवों को जोड़ने के बजाय घटा दिया; सही योग 0.25 है","जोड़ते समय 0.25 को 0.025 पढ़ लिया; सही योग 0.525 है"],"explanationHi":"0.5 का अर्थ 5 दशमांश है, जो 50 सौवें भाग हैं; 50 + 25 = 75 सौवें भाग = 0.75। धन (₹0.50 + ₹0.25) या सौ-वर्ग (हंड्रेड-स्क्वेयर) स्थानीय मान को दृश्य बना देते हैं।"},
  {"id":"cdp-pedagogy-subjects-222","question":"A Class 2 child insists that a large balloon must be heavier than a small stone. The best way to address this is to:","options":["Tell the child that size and weight are not the same thing","Let her compare them on a simple balance and discuss it","Ask the child to draw both objects and label them","Explain the scientific meaning of mass and weight"],"answer":1,"explanation":"Young children often judge weight by size; direct comparison on a balance gives evidence that challenges the idea and builds the concept of weight.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 2 की एक बच्ची ज़ोर देकर कहती है कि बड़ा गुब्बारा छोटे पत्थर से भारी होना चाहिए। इसका समाधान करने का सबसे अच्छा तरीका है:","optionsHi":["बच्ची को बताना कि आकार और भार एक ही चीज़ नहीं हैं","उसे एक सरल तुला पर उनकी तुलना करने देना और उस पर चर्चा करना","बच्ची से दोनों वस्तुओं का चित्र बनाने और नामांकित करने को कहना","द्रव्यमान और भार का वैज्ञानिक अर्थ समझाना"],"explanationHi":"छोटे बच्चे अक्सर आकार से भार का निर्णय करते हैं; तुला पर सीधी तुलना ऐसा प्रमाण देती है जो इस विचार को चुनौती देता है और भार की अवधारणा बनाता है।"},
  {"id":"cdp-pedagogy-subjects-223","question":"A Class 6 student says that any arrangement of six joined squares can be folded into a cube. The best teaching response is to:","options":["Tell the student that only some arrangements work and give the list","Show a finished cube and move on to its properties","Let students predict which six-square nets fold into a cube, then test","Ask students to memorise the faces, edges and vertices of a cube"],"answer":2,"explanation":"Predicting and testing nets develops spatial visualisation and reasoning; students discover that only some arrangements (11 in all) fold into a cube and can explain why others overlap.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 6 का एक विद्यार्थी कहता है कि छह जुड़े वर्गों की कोई भी व्यवस्था मोड़कर घन बनाई जा सकती है। सबसे अच्छी शिक्षण-प्रतिक्रिया है:","optionsHi":["विद्यार्थी को बताना कि केवल कुछ व्यवस्थाएँ काम करती हैं और सूची देना","बना-बनाया घन दिखाकर उसके गुणों पर आगे बढ़ना","विद्यार्थियों को अनुमान लगाने देना कि छह वर्गों के कौन-से जाल (नेट) मोड़कर घन बनते हैं, फिर परखना","विद्यार्थियों से घन के फलक, किनारे और शीर्ष याद करने को कहना"],"explanationHi":"जालों का पूर्वानुमान लगाना और परखना स्थानिक दृश्यीकरण और तर्क का विकास करता है; विद्यार्थी खोजते हैं कि केवल कुछ व्यवस्थाएँ (कुल 11) मोड़कर घन बनती हैं और समझा सकते हैं कि अन्य क्यों एक-दूसरे पर चढ़ जाती हैं।"},
  {"id":"cdp-pedagogy-subjects-224","question":"A child says, ‘Maths makes sense to me. If I keep trying, I can work out problems.’ Among the strands of mathematical proficiency (conceptual understanding, procedural fluency, strategic competence, adaptive reasoning and productive disposition), this mainly reflects:","options":["Procedural fluency","Strategic competence","Adaptive reasoning","Productive disposition"],"answer":3,"explanation":"Productive disposition is seeing mathematics as sensible and worthwhile and believing in one’s own effort; it supports and is supported by the other strands.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक बच्चा कहता है, ‘मुझे गणित समझ में आता है। अगर मैं कोशिश करता रहूँ, तो समस्याएँ हल कर सकता हूँ।’ गणितीय दक्षता के सूत्रों (अवधारणात्मक समझ, प्रक्रियात्मक प्रवाह, रणनीतिक सक्षमता, अनुकूली तर्क और उत्पादक अभिवृत्ति) में, यह मुख्य रूप से किसे दर्शाता है?","optionsHi":["प्रक्रियात्मक प्रवाह","रणनीतिक सक्षमता","अनुकूली तर्क","उत्पादक अभिवृत्ति"],"explanationHi":"उत्पादक अभिवृत्ति गणित को समझने योग्य और सार्थक के रूप में देखना और अपने प्रयास में विश्वास रखना है; यह अन्य सूत्रों को सहारा देती है और उनसे सहारा पाती है।"},
  {"id":"cdp-pedagogy-subjects-225","question":"A teacher takes a common wrong solution from the class test, removes the name, puts it on the board and asks students to find and explain the mistake. The main value of this practice is that it:","options":["Uses a common error as a resource for analysing reasoning","Embarrasses students who make mistakes so they are careful","Saves the teacher from correcting every student’s copy","Shows students which answers will lose marks in the exam"],"answer":0,"explanation":"NCF 2005 urges teachers to treat errors as windows into thinking; analysing an anonymous error is safe and makes the misconception explicit for everyone.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षक कक्षा-परीक्षा से एक आम गलत हल लेता है, नाम हटाकर उसे श्यामपट्ट पर लगाता है और विद्यार्थियों से गलती खोजने और समझाने को कहता है। इस अभ्यास का मुख्य मूल्य यह है कि वह:","optionsHi":["एक आम त्रुटि को तर्क का विश्लेषण करने के संसाधन के रूप में उपयोग करता है","गलती करने वाले विद्यार्थियों को शर्मिंदा करता है ताकि वे सावधान रहें","शिक्षक को हर विद्यार्थी की कॉपी जाँचने से बचाता है","विद्यार्थियों को दिखाता है कि परीक्षा में किन उत्तरों पर अंक कटेंगे"],"explanationHi":"NCF 2005 शिक्षकों से आग्रह करता है कि वे त्रुटियों को सोच की खिड़की मानें; किसी अनाम त्रुटि का विश्लेषण सुरक्षित है और भ्रांत धारणा को सभी के लिए स्पष्ट कर देता है।"},
  {"id":"cdp-pedagogy-subjects-226","question":"A Class 4 teacher plans a ‘water’ theme in which children sing songs about rain in language class, measure rainfall in mathematics, and study water sources in EVS. This approach is called:","options":["The subject-centred approach","The thematic (integrated) approach","The lecture method","The project method in its original form"],"answer":1,"explanation":"A thematic approach organises learning across subjects around one theme, helping children see knowledge as connected rather than in separate compartments.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 4 का एक शिक्षक ‘जल’ थीम की योजना बनाता है, जिसमें बच्चे भाषा की कक्षा में बारिश के गीत गाते हैं, गणित में वर्षा मापते हैं और EVS में जल-स्रोतों का अध्ययन करते हैं। इस उपागम को क्या कहते हैं?","optionsHi":["विषय-केंद्रित उपागम","थीम-आधारित (एकीकृत) उपागम","व्याख्यान विधि","अपने मूल रूप में प्रोजेक्ट विधि"],"explanationHi":"थीम-आधारित उपागम एक थीम के आसपास विषयों में अधिगम को संगठित करता है, जिससे बच्चे ज्ञान को अलग-अलग खानों के बजाय जुड़ा हुआ देख पाते हैं।"},
  {"id":"cdp-pedagogy-subjects-227","question":"NCERT’s Learning Outcomes for the elementary stage (2017) for EVS are best described as:","options":["A list of chapters and topics to be completed in each class","A set of questions to be asked in the final examination","Process-based statements of what children should be able to do","Guidelines on school infrastructure and teacher numbers"],"answer":2,"explanation":"Learning outcomes describe what children should be able to do (e.g. ‘identifies simple features of animals’, ‘records observations’), guiding teaching and assessment rather than listing content.","difficulty":"hard","source":"CTET · State TETs","questionHi":"प्रारंभिक चरण (2017) के लिए EVS के NCERT के अधिगम प्रतिफल का सबसे अच्छा वर्णन है:","optionsHi":["प्रत्येक कक्षा में पूरे किए जाने वाले अध्यायों और विषयों की सूची","अंतिम परीक्षा में पूछे जाने वाले प्रश्नों का समूह","प्रक्रिया-आधारित कथन कि बच्चे क्या कर पाने में सक्षम होने चाहिए","विद्यालय के बुनियादी ढाँचे और शिक्षकों की संख्या पर दिशानिर्देश"],"explanationHi":"अधिगम प्रतिफल बताते हैं कि बच्चे क्या कर पाने में सक्षम होने चाहिए (जैसे ‘जानवरों की सरल विशेषताओं की पहचान करता है’, ‘अवलोकन दर्ज करता है’), और विषय-वस्तु की सूची देने के बजाय शिक्षण और आकलन का मार्गदर्शन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-228","question":"A Class 3 child says a seed is ‘non-living, because it does not move or eat’. Which activity best challenges this idea?","options":["Telling the child firmly that seeds are living things","Showing a picture of a big tree grown from a seed","Asking the child to memorise the seven features of living things","Soaking some seeds, keeping others dry, and watching for a week"],"answer":3,"explanation":"Watching soaked seeds swell and germinate shows that a seed holds a living embryo that grows under suitable conditions, giving evidence instead of a statement.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 3 का एक बच्चा कहता है कि बीज ‘निर्जीव है, क्योंकि वह न चलता है न खाता है’। कौन-सी गतिविधि इस विचार को सबसे अच्छी तरह चुनौती देती है?","optionsHi":["बच्चे को दृढ़ता से बताना कि बीज सजीव होते हैं","बीज से उगे बड़े पेड़ का चित्र दिखाना","बच्चे से सजीवों के सात लक्षण याद करने को कहना","कुछ बीजों को भिगोना, कुछ को सूखा रखना, और एक सप्ताह तक देखना"],"explanationHi":"भीगे बीजों को फूलते और अंकुरित होते देखना दिखाता है कि बीज में एक जीवित भ्रूण होता है जो उपयुक्त परिस्थितियों में बढ़ता है, जो कथन के बजाय प्रमाण देता है।"},
  {"id":"cdp-pedagogy-subjects-229","question":"A Class 6 student predicts that a magnet will attract ‘all metals’. The best activity to test this is to let students:","options":["Test a steel spoon, aluminium foil, copper wire and brass key","Read the textbook definition of magnetic materials aloud in class","Watch the teacher pick up iron nails with a magnet","Memorise a list of magnetic materials from the book"],"answer":0,"explanation":"Testing several metals shows that only some (iron, steel, nickel, cobalt) are attracted, while aluminium, copper and brass are not, so students revise the overgeneralisation from evidence.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 6 का एक विद्यार्थी पूर्वानुमान लगाता है कि चुंबक ‘सभी धातुओं’ को आकर्षित करेगा। इसे परखने की सबसे अच्छी गतिविधि है विद्यार्थियों को:","optionsHi":["स्टील की चम्मच, ऐल्युमिनियम की पन्नी, ताँबे का तार और पीतल की चाबी का परीक्षण करने देना","कक्षा में चुंबकीय पदार्थों की पाठ्यपुस्तक वाली परिभाषा ज़ोर से पढ़ना","शिक्षक को चुंबक से लोहे की कीलें उठाते देखना","पुस्तक से चुंबकीय पदार्थों की सूची याद करना"],"explanationHi":"कई धातुओं का परीक्षण दिखाता है कि केवल कुछ (लोहा, स्टील, निकल, कोबाल्ट) आकर्षित होती हैं, जबकि ऐल्युमिनियम, ताँबा और पीतल नहीं, इसलिए विद्यार्थी प्रमाण से अतिसामान्यीकरण को संशोधित करते हैं।"},
  {"id":"cdp-pedagogy-subjects-230","question":"In an EVS lesson on local self-government, Class 5 children role-play a gram sabha meeting where villagers discuss a broken hand pump. The main learning purpose is to help children:","options":["Memorise the names and duties of panchayat officials","See how people take part in decisions about common resources","Practise acting for the school’s annual day function","Learn that only elected members are allowed to speak in a meeting"],"answer":1,"explanation":"Role-play makes democratic processes concrete and lets children experience participation, negotiation and civic responsibility.","difficulty":"hard","source":"CTET · State TETs","questionHi":"स्थानीय स्वशासन पर EVS के पाठ में कक्षा 5 के बच्चे ग्राम सभा की बैठक का भूमिका-निर्वाह करते हैं, जिसमें ग्रामीण एक टूटे हैंडपंप पर चर्चा करते हैं। मुख्य अधिगम-उद्देश्य बच्चों की किसमें सहायता करना है?","optionsHi":["पंचायत अधिकारियों के नाम और कर्तव्य याद करना","यह देखना कि लोग साझा संसाधनों के बारे में निर्णयों में कैसे भाग लेते हैं","विद्यालय के वार्षिकोत्सव के लिए अभिनय का अभ्यास करना","यह सीखना कि बैठक में केवल निर्वाचित सदस्यों को बोलने की अनुमति होती है"],"explanationHi":"भूमिका-निर्वाह लोकतांत्रिक प्रक्रियाओं को मूर्त बनाता है और बच्चों को भागीदारी, परस्पर बातचीत और नागरिक उत्तरदायित्व का अनुभव करने देता है।"},
  {"id":"cdp-pedagogy-subjects-231","question":"Assertion (A): NCF 2005 treats the multilingual nature of Indian classrooms as a resource for learning. Reason (R): Research links bilingual proficiency with cognitive flexibility, greater awareness of language, and good academic achievement.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"NCF 2005 cites research associating bilingualism with cognitive growth and scholastic achievement, which is why it urges teachers to use children’s languages as a resource.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"अभिकथन (A): NCF 2005 भारतीय कक्षाओं की बहुभाषिक प्रकृति को अधिगम के लिए एक संसाधन मानता है। कारण (R): शोध द्विभाषी दक्षता को संज्ञानात्मक लचीलेपन, भाषा के प्रति अधिक जागरूकता और अच्छी शैक्षणिक उपलब्धि से जोड़ते हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"NCF 2005 उन शोधों का हवाला देता है जो द्विभाषिकता को संज्ञानात्मक विकास और शैक्षणिक उपलब्धि से जोड़ते हैं, इसीलिए वह शिक्षकों से बच्चों की भाषाओं को संसाधन के रूप में उपयोग करने का आग्रह करता है।"},
  {"id":"cdp-pedagogy-subjects-232","question":"Before reading a story titled ‘The Lost Kite’, a teacher shows the cover picture and asks, ‘What do you think will happen in this story?’ This is an example of a:","options":["While-reading comprehension check on the plot","Post-reading evaluation activity on the story","Pre-reading activity to activate prior knowledge","Grammar exercise based on the title"],"answer":2,"explanation":"Predicting from the title and pictures before reading arouses interest, activates what children know and gives them a purpose for reading.","difficulty":"hard","source":"CTET · State TETs","questionHi":"‘The Lost Kite’ शीर्षक की कहानी पढ़ने से पहले, एक शिक्षिका आवरण का चित्र दिखाती है और पूछती है, ‘तुम्हें क्या लगता है इस कहानी में क्या होगा?’ यह किसका उदाहरण है?","optionsHi":["कथानक पर पठन-दौरान बोध की जाँच","कहानी पर पठनोत्तर मूल्यांकन गतिविधि","पूर्व ज्ञान को सक्रिय करने वाली पठन-पूर्व गतिविधि","शीर्षक पर आधारित व्याकरण अभ्यास"],"explanationHi":"पढ़ने से पहले शीर्षक और चित्रों से अनुमान लगाना रुचि जगाता है, बच्चों के ज्ञात को सक्रिय करता है और उन्हें पढ़ने का उद्देश्य देता है।"},
  {"id":"cdp-pedagogy-subjects-233","question":"Match each writing activity with the stage of the process approach it belongs to: 1. Drawing a mind-map of ideas 2. Writing a first version quickly without worrying about errors 3. Changing the order of ideas after peer feedback 4. Correcting spelling and punctuation before display; a. Revising b. Editing c. Pre-writing d. Drafting","options":["1-c, 2-a, 3-d, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a","1-c, 2-d, 3-a, 4-b"],"answer":3,"explanation":"Planning ideas is pre-writing, the first version is drafting, changing content and organisation is revising, and correcting surface errors is editing.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"प्रत्येक लेखन गतिविधि का उस प्रक्रिया उपागम के चरण से मिलान कीजिए, जिससे वह संबंधित है: 1. विचारों का माइंड-मैप बनाना 2. त्रुटियों की चिंता किए बिना पहला प्रारूप तेज़ी से लिखना 3. सहपाठियों की प्रतिपुष्टि के बाद विचारों का क्रम बदलना 4. प्रदर्शन से पहले वर्तनी और विराम-चिह्न सुधारना; a. संशोधन b. संपादन c. पूर्व-लेखन d. प्रारूप लेखन","optionsHi":["1-c, 2-a, 3-d, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a","1-c, 2-d, 3-a, 4-b"],"explanationHi":"विचारों की योजना बनाना पूर्व-लेखन है, पहला प्रारूप प्रारूप लेखन है, विषय-वस्तु और संगठन में परिवर्तन संशोधन है, और सतही त्रुटियाँ सुधारना संपादन है।"},
  {"id":"cdp-pedagogy-subjects-234","question":"Which approach to spelling is most effective for Class 3 children?","options":["Learning a list of 20 unrelated words by heart every week for a test","Writing each misspelt word 50 times as a correction","Exploring word families (cat, hat, mat) and children’s own writing","Avoiding any attention to spelling until Class 5 or later"],"answer":2,"explanation":"Spelling develops through noticing patterns and meaningful use; rote lists and punitive repetition rarely transfer to children’s actual writing.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 3 के बच्चों के लिए वर्तनी का कौन-सा उपागम सबसे प्रभावी है?","optionsHi":["परीक्षा के लिए हर सप्ताह 20 असंबद्ध शब्दों की सूची रटना","सुधार के रूप में हर गलत वर्तनी वाले शब्द को 50 बार लिखना","शब्द-परिवारों (cat, hat, mat) और बच्चों के अपने लेखन की खोजबीन करना","कक्षा 5 या उसके बाद तक वर्तनी पर कोई ध्यान न देना"],"explanationHi":"वर्तनी पैटर्न को देखने और अर्थपूर्ण उपयोग से विकसित होती है; रटी हुई सूचियाँ और दंडात्मक दोहराव बच्चों के वास्तविक लेखन में शायद ही स्थानांतरित होते हैं।"},
  {"id":"cdp-pedagogy-subjects-235","question":"To assess the listening comprehension of Class 1 children, a teacher reads a short story aloud and asks them to put four picture cards from the story in order. Why is this a suitable task?","options":["It tests handwriting and drawing along with listening","It is quicker and easier to mark than an oral test","It shows which children can read the words on the cards","It tests what was heard without needing reading or writing"],"answer":3,"explanation":"A valid listening test should not be contaminated by other skills; sequencing pictures lets young children show comprehension directly.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"कक्षा 1 के बच्चों के श्रवण-बोध का आकलन करने के लिए एक शिक्षिका एक छोटी कहानी ज़ोर से पढ़ती है और उनसे कहानी के चार चित्र-कार्डों को क्रम में लगाने को कहती है। यह कार्य उपयुक्त क्यों है?","optionsHi":["यह सुनने के साथ हस्तलेखन और चित्रकारी की भी जाँच करता है","इसे मौखिक परीक्षा की तुलना में जाँचना तेज़ और आसान है","यह दिखाता है कि कौन-से बच्चे कार्डों पर लिखे शब्द पढ़ सकते हैं","यह बिना पढ़ने या लिखने की आवश्यकता के जो सुना गया उसकी जाँच करता है"],"explanationHi":"वैध श्रवण-परीक्षा अन्य कौशलों से दूषित नहीं होनी चाहिए; चित्रों को क्रम में लगाने से छोटे बच्चे सीधे बोध दिखा पाते हैं।"},
  {"id":"cdp-pedagogy-subjects-236","question":"Regular use of short dramas and dialogues in a Class 4 English class mainly helps children to:","options":["Memorise grammar rules through repeated lines","Use language in meaningful situations, building spoken fluency","Improve their handwriting by copying the scripts","Prepare mainly for written examinations and class tests in English"],"answer":1,"explanation":"Drama provides context, purpose and emotion for language use, lowering anxiety and developing spoken fluency.","difficulty":"moderate","source":"CTET · State TETs","questionHi":"कक्षा 4 की अंग्रेज़ी की कक्षा में छोटे नाटकों और संवादों का नियमित उपयोग मुख्य रूप से बच्चों को किसमें सहायता करता है?","optionsHi":["बार-बार संवाद दोहराकर व्याकरण के नियम याद करना","अर्थपूर्ण स्थितियों में भाषा का उपयोग करना, जिससे मौखिक प्रवाह का विकास होता है","पटकथाएँ उतारकर अपनी हस्तलिपि सुधारना","मुख्य रूप से अंग्रेज़ी की लिखित परीक्षाओं और कक्षा-परीक्षणों की तैयारी करना"],"explanationHi":"नाटक भाषा के उपयोग के लिए संदर्भ, उद्देश्य और भाव प्रदान करता है, जिससे चिंता कम होती है और मौखिक प्रवाह का विकास होता है।"},
  {"id":"cdp-pedagogy-subjects-237","question":"A child who speaks a regional dialect at home is laughed at by classmates for ‘speaking wrongly’. The most appropriate response of a language teacher is to:","options":["Explain that all dialects are rule-governed and value the child’s speech","Tell the child firmly to stop using the dialect anywhere in school from now on","Correct the child’s speech in front of the class each time","Ignore the incident, as children will settle it themselves"],"answer":0,"explanation":"Linguistically, dialects are systematic, not ‘wrong’; respecting them protects children’s identity and confidence, while the standard form can be added for formal use.","difficulty":"hard","source":"CTET · State TETs","questionHi":"जो बच्चा घर पर क्षेत्रीय बोली बोलता है, उसकी ‘गलत बोलने’ के लिए सहपाठी हँसी उड़ाते हैं। भाषा-शिक्षक की सबसे उपयुक्त प्रतिक्रिया है:","optionsHi":["समझाना कि सभी बोलियाँ नियम-शासित होती हैं, और बच्चे की बोली को महत्त्व देना","बच्चे को दृढ़ता से कहना कि अब से विद्यालय में कहीं भी बोली का उपयोग बंद करे","हर बार कक्षा के सामने बच्चे की बोली सुधारना","घटना को अनदेखा करना, क्योंकि बच्चे इसे स्वयं सुलझा लेंगे"],"explanationHi":"भाषावैज्ञानिक दृष्टि से बोलियाँ व्यवस्थित होती हैं, ‘गलत’ नहीं; उनका सम्मान करना बच्चों की पहचान और आत्मविश्वास की रक्षा करता है, जबकि औपचारिक उपयोग के लिए मानक रूप जोड़ा जा सकता है।"},
  {"id":"cdp-pedagogy-subjects-238","question":"A teacher writes ‘happy, unhappy, happiness, happily’ on the board and asks children to find other words that change in the same way. This activity mainly develops:","options":["Phonemic awareness of sounds in spoken words","Handwriting and copying of new words from the board","Morphological awareness of how word parts build words","Listening skill through attention to the teacher"],"answer":2,"explanation":"Knowing how word parts combine helps children work out the meanings of many new words, a strong support for vocabulary and reading.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक शिक्षिका श्यामपट्ट पर ‘happy, unhappy, happiness, happily’ लिखती है और बच्चों से ऐसे अन्य शब्द ढूँढ़ने को कहती है जो उसी प्रकार बदलते हैं। यह गतिविधि मुख्य रूप से किसका विकास करती है?","optionsHi":["बोले गए शब्दों की ध्वनियों की स्वनिमिक जागरूकता","हस्तलेखन और श्यामपट्ट से नए शब्द उतारना","रूपिमिक जागरूकता, कि शब्द के भाग मिलकर शब्द कैसे बनाते हैं","शिक्षिका पर ध्यान देने के माध्यम से सुनने का कौशल"],"explanationHi":"यह जानना कि शब्द के भाग कैसे जुड़ते हैं, बच्चों को अनेक नए शब्दों के अर्थ निकालने में मदद करता है, जो शब्दावली और पठन के लिए मज़बूत सहारा है।"},
  {"id":"cdp-pedagogy-subjects-239","question":"Kenneth Goodman described reading as a ‘psycholinguistic guessing game’. This view implies that skilled readers:","options":["Read every letter of every word in strict order, left to right","Predict meaning and sample only as much print as they need","Read mainly by memorising whole texts and pages","Depend only on phonics rules to decode each word"],"answer":1,"explanation":"Goodman’s top-down view sees reading as an active process of predicting, sampling and confirming meaning, in contrast to a purely letter-by-letter (bottom-up) process.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"केनेथ गुडमैन ने पठन को ‘मनोभाषावैज्ञानिक अनुमान का खेल’ बताया। इस मत का आशय है कि कुशल पाठक:","optionsHi":["हर शब्द का हर अक्षर बाएँ से दाएँ क्रम से पढ़ते हैं","अर्थ का पूर्वानुमान लगाते हैं और केवल उतना ही मुद्रित पाठ देखते हैं जितने की उन्हें आवश्यकता होती है","मुख्य रूप से पूरे पाठों और पन्नों को याद करके पढ़ते हैं","हर शब्द को डिकोड करने के लिए केवल फ़ोनिक्स के नियमों पर निर्भर रहते हैं"],"explanationHi":"गुडमैन का ऊपर-से-नीचे का दृष्टिकोण पठन को अर्थ का पूर्वानुमान लगाने, नमूना लेने और पुष्टि करने की सक्रिय प्रक्रिया मानता है, जो पूरी तरह अक्षर-दर-अक्षर (नीचे-से-ऊपर) प्रक्रिया के विपरीत है।"},
  {"id":"cdp-pedagogy-subjects-240","question":"Which question asked by a teacher in an English class is a ‘referential’ question rather than a ‘display’ question?","options":["‘What is the past tense of “go” in this sentence?’","‘Who wrote this story that we just read in class?’","‘How many characters are there in the story that we just read?’","‘What would you have done if you were in the boy’s place?’"],"answer":3,"explanation":"Display questions ask for answers the teacher already knows, to check knowledge; referential questions seek genuine information or opinion and lead to more authentic communication.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"अंग्रेज़ी की कक्षा में शिक्षक द्वारा पूछा गया कौन-सा प्रश्न ‘प्रदर्शन’ (डिस्प्ले) प्रश्न के बजाय ‘संदर्भात्मक’ (रेफ़रेंशियल) प्रश्न है?","optionsHi":["‘इस वाक्य में “go” का भूतकाल क्या है?’","‘कक्षा में अभी पढ़ी गई यह कहानी किसने लिखी?’","‘अभी पढ़ी गई कहानी में कितने पात्र हैं?’","‘यदि आप उस लड़के की जगह होते, तो आप क्या करते?’"],"explanationHi":"प्रदर्शन प्रश्न ऐसे उत्तर माँगते हैं जो शिक्षक को पहले से पता होते हैं, ज्ञान की जाँच के लिए; संदर्भात्मक प्रश्न वास्तविक जानकारी या राय माँगते हैं और अधिक प्रामाणिक संप्रेषण की ओर ले जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-241","question":"Which practice is most in line with NEP 2020’s guidance on languages in the classroom?","options":["Punishing children for speaking their home language in school","Using only English textbooks from the foundational stage onwards","Using bilingual materials where the home language differs from the medium","Teaching the home language only as an optional subject after Class 8 or later"],"answer":2,"explanation":"NEP 2020 encourages teachers to use a bilingual approach, including bilingual materials, for students whose home language differs from the medium of instruction.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा में भाषाओं के बारे में NEP 2020 के मार्गदर्शन के सबसे अनुरूप कौन-सा अभ्यास है?","optionsHi":["बच्चों को विद्यालय में घरेलू भाषा बोलने पर दंडित करना","आधारभूत चरण से ही केवल अंग्रेज़ी पाठ्यपुस्तकों का उपयोग करना","जहाँ घरेलू भाषा माध्यम से भिन्न है, वहाँ द्विभाषिक सामग्री का उपयोग करना","घरेलू भाषा को केवल कक्षा 8 या उसके बाद वैकल्पिक विषय के रूप में पढ़ाना"],"explanationHi":"NEP 2020 शिक्षकों को उन विद्यार्थियों के लिए, जिनकी घरेलू भाषा शिक्षा के माध्यम से भिन्न है, द्विभाषिक सामग्री सहित द्विभाषिक उपागम अपनाने के लिए प्रोत्साहित करती है।"},
  {"id":"cdp-pedagogy-subjects-242","question":"Class 6 students measure the distance around and across several round objects (bangles, plates, lids) and find that the ratio is close to 3.1 every time. The main value of this activity is that it:","options":["Proves the exact value of π to two decimal places","Shows that measurement of round objects is always inaccurate","Replaces the need to learn the circumference formula","Lets students discover π as a constant ratio before the formula"],"answer":3,"explanation":"Measuring many circles shows a constant ratio, making π a discovered relationship rather than a memorised number; measurement cannot prove its exact value.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 6 के विद्यार्थी कई गोल वस्तुओं (चूड़ियों, थालियों, ढक्कनों) की परिधि और व्यास मापते हैं और पाते हैं कि अनुपात हर बार लगभग 3.1 के निकट होता है। इस गतिविधि का मुख्य मूल्य यह है कि वह:","optionsHi":["π का सटीक मान दशमलव के दो स्थानों तक सिद्ध करती है","दिखाती है कि गोल वस्तुओं का मापन हमेशा गलत होता है","परिधि के सूत्र को सीखने की आवश्यकता को समाप्त कर देती है","विद्यार्थियों को सूत्र से पहले π को एक अचर अनुपात के रूप में खोजने देती है"],"explanationHi":"कई वृत्तों को मापने से एक अचर अनुपात दिखता है, जिससे π रटी हुई संख्या के बजाय खोजा हुआ संबंध बनता है; मापन से उसका सटीक मान सिद्ध नहीं किया जा सकता।"},
  {"id":"cdp-pedagogy-subjects-243","question":"A Class 6 student says 6 ÷ 1/2 = 3. Which question best helps the student make sense of the correct answer?","options":["‘How many half-rotis can you make from 6 rotis?’","‘What is half of 6?’","‘What is the rule for dividing a number by a fraction?’","‘What is 6 × 2?’"],"answer":0,"explanation":"The student has found half of 6. Interpreting division as ‘how many halves fit into 6’ shows that the answer is 12 and gives meaning to the invert-and-multiply rule.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 6 का एक विद्यार्थी कहता है कि 6 ÷ 1/2 = 3। कौन-सा प्रश्न विद्यार्थी को सही उत्तर का अर्थ समझने में सबसे अधिक सहायता करता है?","optionsHi":["‘6 रोटियों से आप कितनी आधी रोटियाँ बना सकते हैं?’","‘6 का आधा क्या है?’","‘किसी संख्या को भिन्न से भाग देने का नियम क्या है?’","‘6 × 2 कितना होता है?’"],"explanationHi":"विद्यार्थी ने 6 का आधा निकाल दिया है। भाग को ‘6 में कितने आधे समाते हैं’ के रूप में समझने से पता चलता है कि उत्तर 12 है और ‘उलटो और गुणा करो’ वाले नियम को अर्थ मिलता है।"},
  {"id":"cdp-pedagogy-subjects-244","question":"A shopkeeper gives change for a ₹100 note on a ₹63 purchase by saying ‘63… 64, 65, 70, 100’ while handing over ₹1, ₹1, ₹5 and ₹30. Using this method in class mainly helps children to understand:","options":["Multiplication of money in rupees and paise","Subtraction by counting up from 63 to 100","Division of the money into equal shares","Rounding amounts to the nearest ten rupees"],"answer":1,"explanation":"Counting up from the smaller number to the larger is a powerful informal strategy for subtraction (100 − 63 = 37) that connects school maths to everyday practice.","difficulty":"hard","source":"CTET · State TETs","questionHi":"एक दुकानदार ₹63 की खरीद पर ₹100 के नोट का शेष लौटाते समय ‘63… 64, 65, 70, 100’ कहते हुए ₹1, ₹1, ₹5 और ₹30 देता है। कक्षा में इस विधि का उपयोग मुख्य रूप से बच्चों को किसे समझने में सहायता करता है?","optionsHi":["रुपये और पैसे में धन का गुणा","63 से 100 तक आगे गिनकर घटाव","धन को बराबर हिस्सों में बाँटना","राशियों को निकटतम दस रुपये तक पूर्णांकित करना"],"explanationHi":"छोटी संख्या से बड़ी संख्या तक आगे गिनना घटाव की एक शक्तिशाली अनौपचारिक रणनीति है (100 − 63 = 37), जो विद्यालयी गणित को रोज़मर्रा के व्यवहार से जोड़ती है।"},
  {"id":"cdp-pedagogy-subjects-245","question":"A Class 5 child says that when a wet cloth dries, ‘the water just goes into the cloth and disappears’. Which activity best helps the child build the idea of evaporation?","options":["Telling the child that water becomes vapour in the sun","Showing and explaining a diagram of the water cycle","Comparing a covered and an open plate of water left in the sun","Asking the child to memorise the definition of evaporation"],"answer":2,"explanation":"The open plate loses water while the covered one does not, showing that the water goes into the air rather than vanishing. A follow-up with droplets forming on a cold glass shows the vapour is still there. Evidence builds the idea that water changes state.","difficulty":"very-hard","source":"CTET · State TETs","questionHi":"कक्षा 5 का एक बच्चा कहता है कि जब गीला कपड़ा सूखता है, तो ‘पानी बस कपड़े में चला जाता है और गायब हो जाता है’। कौन-सी गतिविधि बच्चे को वाष्पन का विचार बनाने में सबसे अधिक सहायता करती है?","optionsHi":["बच्चे को बताना कि धूप में पानी वाष्प बन जाता है","जल-चक्र का आरेख दिखाना और समझाना","धूप में रखी ढकी हुई और खुली थाली के पानी की तुलना करना","बच्चे से वाष्पन की परिभाषा याद करने को कहना"],"explanationHi":"खुली थाली का पानी घटता है जबकि ढकी हुई का नहीं, जो दिखाता है कि पानी गायब होने के बजाय हवा में चला जाता है। ठंडे गिलास पर बूँदें बनने की अनुवर्ती गतिविधि दिखाती है कि वाष्प अब भी मौजूद है। प्रमाण यह विचार बनाता है कि पानी अवस्था बदलता है।"},
  {"id":"cdp-pedagogy-subjects-246","question":"A teacher uses phonics drills to build word recognition and also asks children to predict words from the story context and pictures. Which statement best describes this?","options":["It is purely a bottom-up approach to reading, from letters up","It is purely a top-down approach to reading, from meaning down","It mixes up two incompatible methods and will confuse children","An interactive model, combining decoding with use of context"],"answer":3,"explanation":"Interactive models hold that readers use letter–sound information and contextual knowledge together; good teaching develops both.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक शिक्षक शब्द-पहचान बनाने के लिए फ़ोनिक्स अभ्यास का उपयोग करता है और बच्चों से कहानी के संदर्भ और चित्रों से शब्दों का अनुमान लगाने को भी कहता है। कौन-सा कथन इसका सबसे अच्छा वर्णन करता है?","optionsHi":["यह पठन का पूरी तरह नीचे-से-ऊपर उपागम है, अक्षरों से ऊपर की ओर","यह पठन का पूरी तरह ऊपर-से-नीचे उपागम है, अर्थ से नीचे की ओर","यह दो असंगत विधियों को मिला देता है और बच्चों को भ्रमित करेगा","एक अंतःक्रियात्मक मॉडल, जो डिकोडिंग को संदर्भ के उपयोग के साथ जोड़ता है"],"explanationHi":"अंतःक्रियात्मक मॉडल मानते हैं कि पाठक अक्षर–ध्वनि की जानकारी और संदर्भ-ज्ञान का एक साथ उपयोग करते हैं; अच्छा शिक्षण दोनों का विकास करता है।"},
  {"id":"cdp-pedagogy-subjects-247","question":"A Class 8 student writes (a + b)² = a² + b². Which activity best helps the student see why this is wrong?","options":["Drawing a square of side (a + b) split into a², b² and two ab parts","Making the student memorise the identity by writing it out many times","Telling the student that brackets cannot be removed","Giving ten more expansions to practise the same way"],"answer":0,"explanation":"The area model shows the two missing ab rectangles, and the numerical check (5² = 25, but 9 + 4 = 13) confirms it, building understanding instead of rote recall.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 8 का एक विद्यार्थी (a + b)² = a² + b² लिखता है। कौन-सी गतिविधि विद्यार्थी को यह देखने में सबसे अधिक सहायता करती है कि यह गलत क्यों है?","optionsHi":["भुजा (a + b) वाला वर्ग बनाना, जो a², b² और दो ab भागों में विभाजित हो","विद्यार्थी से सर्वसमिका को कई बार लिखकर याद करवाना","विद्यार्थी को बताना कि कोष्ठक हटाए नहीं जा सकते","उसी तरीके से अभ्यास के लिए दस और प्रसार (एक्सपैंशन) देना"],"explanationHi":"क्षेत्रफल मॉडल दो छूटे हुए ab आयतों को दिखाता है, और संख्यात्मक जाँच (5² = 25, लेकिन 9 + 4 = 13) इसकी पुष्टि करती है, जो रटने के बजाय समझ का निर्माण करती है।"},
  {"id":"cdp-pedagogy-subjects-248","question":"In an EVS lesson on houses, a child from a migrant family says her family has lived in a tent, a hut and now a room in the city. The teacher should:","options":["Move on quickly to avoid embarrassing the child","Invite her to share it as an example of how shelters change","Tell the class that tents are not real or proper houses for families","Ask her to describe the house in the textbook instead"],"answer":1,"explanation":"Children’s varied lives are rich resources for EVS; valuing them builds inclusion and helps all children understand the links between shelter, livelihood and migration.","difficulty":"hard","source":"CTET · State TETs","questionHi":"घरों पर EVS के पाठ में प्रवासी परिवार की एक बच्ची कहती है कि उसका परिवार तंबू में, झोपड़ी में और अब शहर के एक कमरे में रहा है। शिक्षक को चाहिए कि:","optionsHi":["बच्ची को शर्मिंदगी से बचाने के लिए जल्दी आगे बढ़ जाए","उसे इसे इस उदाहरण के रूप में साझा करने के लिए आमंत्रित करे कि आवास कैसे बदलते हैं","कक्षा को बताए कि तंबू परिवारों के लिए असली या उचित घर नहीं होते","इसके बजाय उससे पाठ्यपुस्तक के घर का वर्णन करने को कहे"],"explanationHi":"बच्चों का विविध जीवन EVS के लिए समृद्ध संसाधन है; उसे महत्त्व देना समावेशन का निर्माण करता है और सभी बच्चों को आवास, आजीविका और प्रवासन के बीच संबंध समझने में मदद करता है।"},
  {"id":"cdp-pedagogy-subjects-249","question":"Class 4 children find it hard to read maps. The teacher asks them to draw how a pencil box, a bottle and a book on the desk look from directly above. The main purpose of this activity is to develop:","options":["Drawing and shading skills for the weekly art period in school","Knowledge of standard map symbols and colours","The idea of a top (bird’s-eye) view, the basis of maps","Measurement of length of objects on the desk"],"answer":2,"explanation":"Maps show places as seen from above; drawing top views of familiar objects helps children make the shift from side views to the plan view that maps use.","difficulty":"hard","source":"CTET · State TETs","questionHi":"कक्षा 4 के बच्चों को नक्शे पढ़ने में कठिनाई होती है। शिक्षक उनसे बनवाता है कि मेज़ पर रखा पेंसिल-बॉक्स, बोतल और किताब ठीक ऊपर से कैसे दिखते हैं। इस गतिविधि का मुख्य उद्देश्य किसका विकास करना है?","optionsHi":["विद्यालय के साप्ताहिक कला-कालांश के लिए चित्रकारी और छायांकन कौशल","मानक मानचित्र-प्रतीकों और रंगों का ज्ञान","ऊपर से देखने (पक्षी-दृष्टि) का विचार, जो नक्शों का आधार है","मेज़ पर रखी वस्तुओं की लंबाई का मापन"],"explanationHi":"नक्शे स्थानों को ऊपर से देखे जाने के रूप में दिखाते हैं; परिचित वस्तुओं के ऊपरी दृश्य बनाने से बच्चों को पार्श्व दृश्यों से उस योजना-दृश्य तक पहुँचने में मदद मिलती है जिसका नक्शे उपयोग करते हैं।"},
  {"id":"cdp-pedagogy-subjects-250","question":"A Class 7 student with a locomotor disability uses a wheelchair. Which arrangement best supports her in science practicals?","options":["Letting her only watch while others perform the experiments","An accessible table, apparatus within reach and a hands-on role","Asking her to write the record while others do the practical","Exempting her from practical work and its assessment"],"answer":1,"explanation":"Reasonable accommodation, such as accessible furniture and placement of apparatus, lets her take part fully; being only an observer or recorder denies her the practical learning.","difficulty":"moderate","source":"CTET Paper II · KVS · DSSSB","questionHi":"कक्षा 7 की गामक अक्षमता वाली एक छात्रा व्हीलचेयर का उपयोग करती है। विज्ञान के प्रायोगिक कार्यों में कौन-सी व्यवस्था उसे सबसे अधिक सहायता देती है?","optionsHi":["उसे केवल देखने देना जबकि अन्य प्रयोग करें","सुलभ मेज़, पहुँच में रखे उपकरण और हाथों से करने वाली भूमिका","उससे रिकॉर्ड लिखने को कहना जबकि अन्य प्रायोगिक कार्य करें","उसे प्रायोगिक कार्य और उसके आकलन से छूट देना"],"explanationHi":"उचित सुविधा, जैसे सुलभ फ़र्नीचर और उपकरणों की व्यवस्था, उसे पूरी तरह भाग लेने देती है; केवल पर्यवेक्षक या अभिलेखक होना उसे प्रायोगिक अधिगम से वंचित करता है।"},
  {"id":"cdp-pedagogy-subjects-251","question":"A Class 3 teacher in a village in western Rajasthan opens the EVS theme ‘Water’ by asking: ‘Where does the water in your home come from? Who brings it? How far do they walk?’ The strongest pedagogical justification for this opening is that it:","options":["quickly checks prior knowledge so that children can be ranked by ability before the unit begins","shows that the textbook can be set aside, since it is not written for rural children","starts from children’s lived experience and links the natural and social sides of water","fills the first period with talk until children are ready for the textbook definitions"],"answer":2,"explanation":"NCF 2005 asks EVS to begin from the child’s own context; the questions tie a natural resource to who labours for it and how access differs. Ranking, replacing the textbook or delaying ‘definitions’ all misread the intent.","difficulty":"moderate","source":"CTET Paper 1 · REET Level 1","questionHi":"पश्चिमी राजस्थान के एक गाँव में कक्षा 3 की शिक्षिका EVS की थीम ‘जल’ की शुरुआत यह पूछकर करती है: ‘आपके घर का पानी कहाँ से आता है? उसे कौन लाता है? वे कितनी दूर चलते हैं?’ इस शुरुआत का सबसे मज़बूत शैक्षिक औचित्य यह है कि वह:","optionsHi":["पूर्व ज्ञान की शीघ्र जाँच करती है ताकि इकाई शुरू होने से पहले बच्चों को क्षमता के आधार पर क्रमबद्ध किया जा सके","दिखाती है कि पाठ्यपुस्तक को एक ओर रखा जा सकता है, क्योंकि वह ग्रामीण बच्चों के लिए नहीं लिखी गई","बच्चों के जिए हुए अनुभव से शुरू होती है और जल के प्राकृतिक तथा सामाजिक पक्षों को जोड़ती है","पहला कालांश बातचीत से तब तक भरती है जब तक बच्चे पाठ्यपुस्तक की परिभाषाओं के लिए तैयार न हों"],"explanationHi":"NCF 2005 चाहता है कि EVS बच्चे के अपने संदर्भ से शुरू हो; प्रश्न एक प्राकृतिक संसाधन को इससे जोड़ते हैं कि उसके लिए श्रम कौन करता है और पहुँच कैसे भिन्न होती है। क्रमबद्ध करना, पाठ्यपुस्तक को बदलना या ‘परिभाषाओं’ में देरी करना, सब आशय को गलत समझना है।"},
  {"id":"cdp-pedagogy-subjects-252","question":"Consider these statements about EVS in Classes I and II as envisaged in NCF 2005: I. A separate EVS textbook is prescribed from Class I. II. Environmental concerns are woven into language and mathematics. III. Children engage with their surroundings mainly through activities, talk and stories. Which are correct?","options":["I and II only","II and III only","I and III only","I, II and III all"],"answer":1,"explanation":"In Classes I–II there is no separate EVS book; its concerns are integrated with language and mathematics and approached through activities and conversation. Statement I is the trap.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"NCF 2005 में परिकल्पित कक्षा I और II में EVS के बारे में इन कथनों पर विचार कीजिए: I. कक्षा I से अलग EVS पाठ्यपुस्तक निर्धारित है। II. पर्यावरणीय चिंताएँ भाषा और गणित में पिरोई गई हैं। III. बच्चे अपने परिवेश से मुख्य रूप से गतिविधियों, बातचीत और कहानियों के माध्यम से जुड़ते हैं। कौन-से सही हैं?","optionsHi":["केवल I और II","केवल II और III","केवल I और III","I, II और III सभी"],"explanationHi":"कक्षा I–II में कोई अलग EVS पुस्तक नहीं है; इसकी चिंताएँ भाषा और गणित के साथ एकीकृत हैं और गतिविधियों तथा बातचीत के माध्यम से अपनाई जाती हैं। कथन I जाल है।"},
  {"id":"cdp-pedagogy-subjects-253","question":"Assertion (A): The NCERT EVS syllabus for Classes III–V is organised around themes rather than around chapters of science and social science. Reason (R): Young children perceive their surroundings as a whole and do not divide experience into disciplinary compartments. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The thematic organisation (Family and Friends, Food, Shelter, Water, Travel, Things We Make and Do) exists precisely because children experience the world holistically, so R explains A.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"अभिकथन (A): कक्षा III–V का NCERT EVS पाठ्यक्रम विज्ञान और सामाजिक विज्ञान के अध्यायों के बजाय थीम के आसपास संगठित है। कारण (R): छोटे बच्चे अपने परिवेश को संपूर्ण रूप में देखते हैं और अनुभव को विषय-आधारित खानों में नहीं बाँटते। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"थीम-आधारित संगठन (परिवार और मित्र, भोजन, आवास, जल, यात्रा, हम क्या बनाते और करते हैं) ठीक इसलिए है कि बच्चे दुनिया को समग्र रूप में अनुभव करते हैं, इसलिए R, A की व्याख्या करता है।"},
  {"id":"cdp-pedagogy-subjects-254","question":"Which of the following is NOT an objective of primary EVS as laid down in the NCERT syllabus that followed NCF 2005?","options":["To help children relate the natural, social and cultural environment to one another","To develop awareness of environmental issues through the child’s own context","To build skills such as observing, classifying and inferring through hands-on exploration","To give children an early, formal introduction to physics, chemistry and biology"],"answer":3,"explanation":"Primary EVS deliberately avoids splitting knowledge into formal disciplines; the other three are stated objectives. Early disciplinary teaching is the very approach NCF 2005 moved away from.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"NCF 2005 के बाद बने NCERT पाठ्यक्रम में निर्धारित प्राथमिक EVS के उद्देश्यों में निम्नलिखित में से कौन-सा उद्देश्य नहीं है?","optionsHi":["बच्चों को प्राकृतिक, सामाजिक और सांस्कृतिक पर्यावरण को एक-दूसरे से जोड़ने में सहायता करना","बच्चे के अपने संदर्भ के माध्यम से पर्यावरणीय मुद्दों के प्रति जागरूकता विकसित करना","हाथों से करके खोजबीन के माध्यम से अवलोकन, वर्गीकरण और अनुमान जैसे कौशल निर्मित करना","बच्चों को भौतिकी, रसायन विज्ञान और जीव विज्ञान से शीघ्र, औपचारिक परिचय देना"],"explanationHi":"प्राथमिक EVS जानबूझकर ज्ञान को औपचारिक विषयों में बाँटने से बचता है; अन्य तीन कथित उद्देश्य हैं। विषयों की शीघ्र शिक्षा वही उपागम है जिससे NCF 2005 दूर हटा।"},
  {"id":"cdp-pedagogy-subjects-255","question":"A senior teacher tells a trainee, ‘EVS in Class 4 is just science with a bit of geography added.’ Which response best corrects this view?","options":["EVS is really a social studies subject, since most of its chapters are about families, people and the work they do","The view is right, because the EVS books contain far more science content than history, and geography fills the rest","EVS integrates science, social science and environmental education, and aims at sensitivity and values in the child’s context","EVS is mainly about pollution and its control, so it sits closer to environmental science than to either science or geography"],"answer":2,"explanation":"EVS is not a sum of two subjects; it weaves several areas into themes and aims at awareness, concern and skills. Each distractor reduces it to a single discipline or a single issue.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक वरिष्ठ शिक्षक एक प्रशिक्षु से कहता है, ‘कक्षा 4 में EVS बस विज्ञान है, जिसमें थोड़ा भूगोल जोड़ दिया गया है।’ कौन-सी प्रतिक्रिया इस दृष्टिकोण को सबसे अच्छी तरह सुधारती है?","optionsHi":["EVS वास्तव में सामाजिक अध्ययन का विषय है, क्योंकि इसके अधिकांश अध्याय परिवारों, लोगों और उनके काम के बारे में हैं","यह दृष्टिकोण सही है, क्योंकि EVS की पुस्तकों में इतिहास की तुलना में कहीं अधिक विज्ञान की सामग्री है, और बाकी भूगोल भरता है","EVS विज्ञान, सामाजिक विज्ञान और पर्यावरण शिक्षा को एकीकृत करता है, और बच्चे के संदर्भ में संवेदनशीलता और मूल्यों का लक्ष्य रखता है","EVS मुख्यतः प्रदूषण और उसके नियंत्रण के बारे में है, इसलिए वह विज्ञान या भूगोल की तुलना में पर्यावरण विज्ञान के अधिक निकट है"],"explanationHi":"EVS दो विषयों का योग नहीं है; यह कई क्षेत्रों को थीम में पिरोता है और जागरूकता, सरोकार तथा कौशल का लक्ष्य रखता है। हर विकर्षक उसे एक ही विषय या एक ही मुद्दे तक सीमित कर देता है।"},
  {"id":"cdp-pedagogy-subjects-256","question":"In the NCERT EVS framework, ‘Animals’ and ‘Plants’ appear as sub-themes under ‘Family and Friends’. The best explanation for this placement is that it:","options":["follows the legal status of pets as members of a household, so animals are taught as relatives of the family","shows plants and animals as part of the child’s web of relationships, building sensitivity, not mere classification","signals that biology is not really part of EVS, so plants and animals are treated only as social topics","keeps difficult biological content such as classification and life processes out of Classes III–V altogether, by design"],"answer":1,"explanation":"Placing plants and animals beside relationships and work and play signals that children should relate to them with care and curiosity. Biology is present, but approached through relationship, not taxonomy.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"NCERT EVS ढाँचे में ‘जानवर’ और ‘पौधे’ ‘परिवार और मित्र’ के अंतर्गत उप-थीम के रूप में आते हैं। इस स्थान-निर्धारण की सबसे अच्छी व्याख्या यह है कि वह:","optionsHi":["पालतू जानवरों की घर के सदस्यों के रूप में कानूनी स्थिति का अनुसरण करता है, इसलिए जानवर परिवार के संबंधियों के रूप में पढ़ाए जाते हैं","दिखाता है कि पौधे और जानवर बच्चे के संबंधों के जाल का भाग हैं, जो केवल वर्गीकरण नहीं, बल्कि संवेदनशीलता का निर्माण करता है","संकेत देता है कि जीव विज्ञान वास्तव में EVS का भाग नहीं है, इसलिए पौधों और जानवरों को केवल सामाजिक विषयों के रूप में लिया जाता है","वर्गीकरण और जैव प्रक्रियाओं जैसी कठिन जैविक सामग्री को कक्षा III–V से जानबूझकर पूरी तरह बाहर रखता है"],"explanationHi":"पौधों और जानवरों को संबंधों और काम तथा खेल के साथ रखना संकेत देता है कि बच्चों को उनसे देखभाल और जिज्ञासा के साथ जुड़ना चाहिए। जीव विज्ञान मौजूद है, लेकिन संबंध के माध्यम से अपनाया गया है, वर्गीकरण-विज्ञान के माध्यम से नहीं।"},
  {"id":"cdp-pedagogy-subjects-257","question":"A Class 4 teacher in a hill district of Uttarakhand is starting the theme ‘Travel’. Which opening is most appropriate?","options":["Showing a video of metro and bullet trains first, so that children see the most modern transport of the country","Listing land, water and air transport from the textbook for children to copy and memorise before any discussion","Defining transport and asking children to sort pictures of vehicles into land, water and air groups","Asking children how their families reach the market, hospital and school, and what difficulties they face"],"answer":3,"explanation":"Starting from local journeys and their difficulties connects travel to geography, access and livelihood in the child’s own world. Videos of distant transport, memorised lists and definitions begin far from experience.","difficulty":"moderate","source":"CTET Paper 1 · UKTET","questionHi":"उत्तराखंड के एक पहाड़ी ज़िले में कक्षा 4 का एक शिक्षक थीम ‘यात्रा’ शुरू कर रहा है। कौन-सी शुरुआत सबसे उपयुक्त है?","optionsHi":["पहले मेट्रो और बुलेट ट्रेनों का वीडियो दिखाना, ताकि बच्चे देश का सबसे आधुनिक परिवहन देख सकें","किसी भी चर्चा से पहले बच्चों को उतारने और याद करने के लिए पाठ्यपुस्तक से स्थल, जल और वायु परिवहन की सूची देना","परिवहन की परिभाषा देना और बच्चों से वाहनों के चित्रों को स्थल, जल और वायु समूहों में छाँटने को कहना","बच्चों से पूछना कि उनके परिवार बाज़ार, अस्पताल और विद्यालय कैसे पहुँचते हैं, और उन्हें क्या कठिनाइयाँ होती हैं"],"explanationHi":"स्थानीय यात्राओं और उनकी कठिनाइयों से शुरू करना यात्रा को बच्चे की अपनी दुनिया के भूगोल, पहुँच और आजीविका से जोड़ता है। दूर के परिवहन के वीडियो, रटी हुई सूचियाँ और परिभाषाएँ अनुभव से बहुत दूर से शुरू होती हैं।"},
  {"id":"cdp-pedagogy-subjects-258","question":"Which of the following practices goes AGAINST the thematic approach in EVS?","options":["Teaching ‘Water’ in one science period on its states and a separate, unconnected period on scarcity","Exploring how water is used at home, in the fields and during festivals in the children’s own village","Tracing how water reaches the village, who carries it and who decides who gets how much of it","Drawing how the family’s water use changes between the dry summer months and the monsoon season"],"answer":0,"explanation":"A theme loses its point if it is split back into disconnected disciplinary periods. The other three keep the natural and social aspects of water together.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"निम्नलिखित में से कौन-सा अभ्यास EVS में थीम-आधारित उपागम के विरुद्ध जाता है?","optionsHi":["‘जल’ को एक विज्ञान-कालांश में उसकी अवस्थाओं पर और एक अलग, असंबद्ध कालांश में उसकी कमी पर पढ़ाना","बच्चों के अपने गाँव में घर में, खेतों में और त्योहारों के दौरान जल के उपयोग की खोजबीन करना","यह पता लगाना कि पानी गाँव तक कैसे पहुँचता है, उसे कौन ढोता है और कौन तय करता है कि किसे कितना मिलेगा","शुष्क गर्मी के महीनों और मानसून के मौसम के बीच परिवार के जल-उपयोग में आए बदलाव का चित्र बनाना"],"explanationHi":"थीम का उद्देश्य तब खो जाता है जब उसे वापस असंबद्ध विषय-आधारित कालांशों में बाँट दिया जाए। अन्य तीन जल के प्राकृतिक और सामाजिक पक्षों को साथ रखते हैं।"},
  {"id":"cdp-pedagogy-subjects-259","question":"‘Water’ appears in the NCERT EVS books of Classes III, IV and V, moving from water in daily life to its sources, and then to access, scarcity and conservation. This organisation best reflects:","options":["drill through repetition of the same content in the same way each year","sequencing from abstract ideas in Class III to concrete examples in Class V","a spiral curriculum in which a theme is revisited at greater depth","a strictly subject-centred, linear sequence that never returns to a topic"],"answer":2,"explanation":"Revisiting the same theme with increasing complexity is Bruner’s spiral idea. It is not mere repetition, and it moves from concrete to abstract, not the reverse.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"‘जल’ कक्षा III, IV और V की NCERT EVS पुस्तकों में आता है, जो दैनिक जीवन में जल से उसके स्रोतों की ओर, और फिर पहुँच, कमी और संरक्षण की ओर बढ़ता है। यह संगठन सबसे अच्छी तरह दर्शाता है:","optionsHi":["हर वर्ष एक ही सामग्री को एक ही तरीके से दोहराकर अभ्यास कराना","कक्षा III में अमूर्त विचारों से कक्षा V में मूर्त उदाहरणों की ओर क्रम","सर्पिल पाठ्यचर्या, जिसमें थीम को अधिक गहराई के साथ फिर से देखा जाता है","कड़ाई से विषय-केंद्रित, रैखिक क्रम जो किसी विषय पर कभी वापस नहीं लौटता"],"explanationHi":"बढ़ती जटिलता के साथ उसी थीम पर लौटना ब्रूनर का सर्पिल विचार है। यह मात्र दोहराव नहीं है, और यह मूर्त से अमूर्त की ओर जाता है, उलटा नहीं।"},
  {"id":"cdp-pedagogy-subjects-260","question":"A Class 5 teacher in a coastal village of Kerala begins a lesson on deserts by asking children to compare their own houses, seasons and water with photographs of a family in Jaisalmer. Which principle is she mainly using?","options":["From abstract to concrete, by starting with an unseen place","From the known to the unknown, by contrast with the familiar","From the whole to its parts, by treating India as one region","From rote recall to understanding, by testing desert facts first"],"answer":1,"explanation":"The familiar coastal life is the anchor against which the unfamiliar desert is understood. ‘Abstract to concrete’ reverses the accepted maxim.","difficulty":"moderate","source":"CTET Paper 1 · Kerala TET","questionHi":"केरल के तटीय गाँव में कक्षा 5 की एक शिक्षिका रेगिस्तानों पर पाठ की शुरुआत बच्चों से उनके अपने घरों, मौसमों और पानी की तुलना जैसलमेर के एक परिवार की तस्वीरों से करवाकर करती है। वह मुख्य रूप से किस सिद्धांत का उपयोग कर रही है?","optionsHi":["अमूर्त से मूर्त की ओर, एक न देखे हुए स्थान से शुरू करके","ज्ञात से अज्ञात की ओर, परिचित के साथ विरोधाभास के द्वारा","संपूर्ण से अंशों की ओर, भारत को एक क्षेत्र मानकर","रटने से समझ की ओर, पहले रेगिस्तान के तथ्यों की जाँच करके"],"explanationHi":"परिचित तटीय जीवन वह आधार है जिसके सहारे अपरिचित रेगिस्तान को समझा जाता है। ‘अमूर्त से मूर्त’ स्वीकृत सूत्र को उलट देता है।"},
  {"id":"cdp-pedagogy-subjects-261","question":"Which question by a teacher during the theme ‘Food’ is most in the spirit of the NCERT EVS books?","options":["Define a balanced diet and list all the nutrients it must contain in the right amounts.","Name five foods that give us protein and five that give us carbohydrates.","Write the full form of ORS and the steps for preparing it as given in the chapter.","In your family, who decides what is cooked? Has it always been the same person? Why?"],"answer":3,"explanation":"The question draws on the child’s home, has no single textbook answer and opens up issues of roles and gender. The others call for recall of definitions or lists.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"थीम ‘भोजन’ के दौरान शिक्षक का कौन-सा प्रश्न NCERT EVS पुस्तकों की भावना के सबसे अनुरूप है?","optionsHi":["संतुलित आहार की परिभाषा दीजिए और उन सभी पोषक तत्त्वों की सूची बनाइए जो उसमें सही मात्रा में होने चाहिए।","प्रोटीन देने वाले पाँच और कार्बोहाइड्रेट देने वाले पाँच खाद्य पदार्थों के नाम बताइए।","ORS का पूरा नाम और अध्याय में दिए अनुसार उसे बनाने के चरण लिखिए।","आपके परिवार में क्या पकेगा, यह कौन तय करता है? क्या यह हमेशा वही व्यक्ति रहा है? क्यों?"],"explanationHi":"यह प्रश्न बच्चे के घर से लिया गया है, इसका कोई एक पाठ्यपुस्तकीय उत्तर नहीं है और यह भूमिकाओं तथा लिंग के मुद्दे खोलता है। अन्य परिभाषाओं या सूचियों का स्मरण माँगते हैं।"},
  {"id":"cdp-pedagogy-subjects-262","question":"Match each NCERT EVS theme with the classroom example that best belongs to it: 1. Shelter 2. Things We Make and Do 3. Travel 4. Water. a. Why houses in parts of Assam stand on bamboo stilts. b. How a potter shapes clay on a wheel. c. A family’s train journey from Kolkata to Chennai. d. Who built the old village stepwell and who was allowed to use it.","options":["1-a, 2-c, 3-b, 4-d","1-d, 2-b, 3-c, 4-a","1-a, 2-b, 3-c, 4-d","1-b, 2-a, 3-c, 4-d"],"answer":2,"explanation":"Stilt houses answer to climate (Shelter), pottery is a craft (Things We Make and Do), the journey is Travel and the stepwell raises questions of water and access (Water).","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"प्रत्येक NCERT EVS थीम का उस कक्षा-उदाहरण से मिलान कीजिए जो उससे सबसे अच्छी तरह संबंधित है: 1. आवास 2. हम क्या बनाते और करते हैं 3. यात्रा 4. जल। a. असम के कुछ भागों में घर बाँस के खंभों पर क्यों खड़े होते हैं। b. कुम्हार चाक पर मिट्टी को कैसे आकार देता है। c. एक परिवार की कोलकाता से चेन्नई की रेल यात्रा। d. गाँव की पुरानी बावड़ी किसने बनाई और उसका उपयोग करने की अनुमति किसे थी।","optionsHi":["1-a, 2-c, 3-b, 4-d","1-d, 2-b, 3-c, 4-a","1-a, 2-b, 3-c, 4-d","1-b, 2-a, 3-c, 4-d"],"explanationHi":"खंभों वाले घर जलवायु के अनुकूल हैं (आवास), मिट्टी के बर्तन बनाना एक शिल्प है (हम क्या बनाते और करते हैं), यात्रा यात्रा है और बावड़ी जल और पहुँच के प्रश्न उठाती है (जल)।"},
  {"id":"cdp-pedagogy-subjects-263","question":"Assertion (A): EVS is not taught as a separate subject with its own textbook in Classes I and II. Reason (R): Children of this age cannot learn anything meaningful about their environment. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true, but the reason is that young children learn about their surroundings best through language, mathematics and activity, not that they cannot learn about it. R is false.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): कक्षा I और II में EVS अपनी अलग पाठ्यपुस्तक के साथ अलग विषय के रूप में नहीं पढ़ाया जाता। कारण (R): इस आयु के बच्चे अपने पर्यावरण के बारे में कुछ भी सार्थक नहीं सीख सकते। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"A सत्य है, लेकिन कारण यह है कि छोटे बच्चे अपने परिवेश के बारे में भाषा, गणित और गतिविधि के माध्यम से सबसे अच्छा सीखते हैं, यह नहीं कि वे उसके बारे में सीख नहीं सकते। R असत्य है।"},
  {"id":"cdp-pedagogy-subjects-264","question":"Which statement about the EVS textbook is consistent with NCF 2005?","options":["The textbook is one resource among many; children’s experience, the local environment and the community are others","The textbook is the final authority and must be completed page by page, since examinations are set from it","Teachers should not bring in local examples that are not printed in the textbook, as they may confuse children","Every question in the textbook should have a single correct answer printed in the chapter, so that marking stays fair"],"answer":0,"explanation":"NCF 2005 asks teachers to move beyond the textbook and treat it as one resource among many. The other options describe the textbook-centred culture it criticised.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"EVS पाठ्यपुस्तक के बारे में कौन-सा कथन NCF 2005 के अनुरूप है?","optionsHi":["पाठ्यपुस्तक कई संसाधनों में से एक है; बच्चों का अनुभव, स्थानीय पर्यावरण और समुदाय अन्य संसाधन हैं","पाठ्यपुस्तक अंतिम प्रमाण है और उसे पन्ना-दर-पन्ना पूरा करना चाहिए, क्योंकि परीक्षाएँ उसी से बनती हैं","शिक्षकों को स्थानीय उदाहरण नहीं लाने चाहिए जो पाठ्यपुस्तक में छपे नहीं हैं, क्योंकि वे बच्चों को भ्रमित कर सकते हैं","पाठ्यपुस्तक के हर प्रश्न का एक ही सही उत्तर अध्याय में छपा होना चाहिए, ताकि अंकन निष्पक्ष रहे"],"explanationHi":"NCF 2005 शिक्षकों से पाठ्यपुस्तक से आगे जाने और उसे अनेक संसाधनों में से एक मानने को कहता है। अन्य विकल्प उस पाठ्यपुस्तक-केंद्रित संस्कृति का वर्णन करते हैं जिसकी उसने आलोचना की।"},
  {"id":"cdp-pedagogy-subjects-265","question":"A Class 3 teacher asks, ‘Which animals live around your village? Which have you seen up close? Which ones do people fear?’ She writes every answer on a chart, including local names, without correcting them. The main purpose of this is to:","options":["delay scientific names until Class 6, because using them early confuses young learners","value children’s knowledge and local vocabulary as a base for further exploration","identify which children come from farming families so that they can be grouped together","replace the need for first-hand observation, since children have already seen the animals"],"answer":1,"explanation":"Recording local names and experiences without judgement legitimises children’s knowledge and gives the teacher a starting point. It neither forbids scientific names nor replaces observation.","difficulty":"hard","source":"CTET Paper 1 · NVS PRT","questionHi":"कक्षा 3 की एक शिक्षिका पूछती है, ‘आपके गाँव के आसपास कौन-से जानवर रहते हैं? आपने किन्हें पास से देखा है? किनसे लोग डरते हैं?’ वह हर उत्तर को, स्थानीय नामों सहित, बिना सुधारे एक चार्ट पर लिखती है। इसका मुख्य उद्देश्य है:","optionsHi":["वैज्ञानिक नामों को कक्षा 6 तक टालना, क्योंकि उन्हें जल्दी उपयोग करने से छोटे अधिगमकर्ता भ्रमित होते हैं","बच्चों के ज्ञान और स्थानीय शब्दावली को आगे की खोजबीन के आधार के रूप में महत्त्व देना","यह पहचानना कि कौन-से बच्चे किसान परिवारों से आते हैं ताकि उन्हें साथ समूहित किया जा सके","प्रत्यक्ष अवलोकन की आवश्यकता को समाप्त करना, क्योंकि बच्चे जानवरों को पहले ही देख चुके हैं"],"explanationHi":"स्थानीय नामों और अनुभवों को बिना निर्णय के दर्ज करना बच्चों के ज्ञान को वैधता देता है और शिक्षक को आरंभ-बिंदु देता है। यह न वैज्ञानिक नामों को रोकता है और न अवलोकन को प्रतिस्थापित करता है।"},
  {"id":"cdp-pedagogy-subjects-266","question":"Which of the following fall within the scope of primary EVS as envisaged by NCF 2005? I. Caste-based discrimination in access to a village well. II. Simple estimation and measurement. III. Memorising chemical formulae of common substances. IV. Local crafts and occupations.","options":["I and II only","II and IV only","I, III and IV only","I, II and IV only"],"answer":3,"explanation":"EVS includes social issues of equity, process skills like estimating and measuring, and local work and crafts. Chemical formulae are outside the primary stage and against the spirit of EVS.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"NCF 2005 में परिकल्पित प्राथमिक EVS के दायरे में निम्नलिखित में से कौन-से आते हैं? I. गाँव के कुएँ तक पहुँच में जाति-आधारित भेदभाव। II. सरल अनुमान और मापन। III. सामान्य पदार्थों के रासायनिक सूत्रों को याद करना। IV. स्थानीय शिल्प और व्यवसाय।","optionsHi":["केवल I और II","केवल II और IV","केवल I, III और IV","केवल I, II और IV"],"explanationHi":"EVS में समानता के सामाजिक मुद्दे, अनुमान लगाने और मापने जैसे प्रक्रिया कौशल, तथा स्थानीय कार्य और शिल्प शामिल हैं। रासायनिक सूत्र प्राथमिक चरण के बाहर हैं और EVS की भावना के विरुद्ध हैं।"},
  {"id":"cdp-pedagogy-subjects-267","question":"During a Class 4 discussion on festival food, a child says, ‘People who eat meat are dirty.’ The most appropriate response of the teacher is to:","options":["ignore the remark so that the discussion does not turn controversial and hurt the feelings of the other children present","ask the child to apologise to the class at once and then move on quickly to the next topic in the chapter","open a discussion on how food habits depend on region, culture and availability, and why no habit makes anyone dirty","agree in part, saying vegetarian food is healthier, so the child’s remark contains some truth worth keeping"],"answer":2,"explanation":"EVS aims at respect for diversity, so the prejudice must be examined, not silenced or endorsed. A forced apology closes thinking without changing the belief.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"त्योहारों के भोजन पर कक्षा 4 की चर्चा के दौरान एक बच्चा कहता है, ‘जो लोग मांस खाते हैं वे गंदे होते हैं।’ शिक्षक की सबसे उपयुक्त प्रतिक्रिया है:","optionsHi":["टिप्पणी को अनदेखा करना ताकि चर्चा विवादास्पद न हो जाए और उपस्थित अन्य बच्चों की भावनाएँ आहत न हों","बच्चे से तुरंत कक्षा से माफ़ी माँगने को कहना और फिर अध्याय के अगले विषय पर जल्दी बढ़ जाना","इस पर चर्चा खोलना कि खान-पान की आदतें क्षेत्र, संस्कृति और उपलब्धता पर कैसे निर्भर करती हैं, और कोई आदत किसी को गंदा क्यों नहीं बनाती","आंशिक रूप से सहमत होना, यह कहकर कि शाकाहारी भोजन अधिक स्वस्थ है, ताकि बच्चे की टिप्पणी में कुछ सच्चाई बची रहे"],"explanationHi":"EVS का उद्देश्य विविधता के प्रति सम्मान है, इसलिए पूर्वाग्रह की जाँच की जानी चाहिए, उसे न दबाया जाए न समर्थन दिया जाए। ज़बरदस्ती की माफ़ी सोच को बिना धारणा बदले बंद कर देती है।"},
  {"id":"cdp-pedagogy-subjects-268","question":"Many chapters of the NCERT EVS books are written as stories, letters, diary entries and interviews rather than as descriptive information. The main reason is to:","options":["connect with children’s experience, carry the social context and invite them to think, not to supply facts to memorise","improve reading speed and fluency so that children score better in their language tests and reading assessments","follow an RTE rule that bans purely informational text in primary classes and requires stories in every single subject","reduce the number of pages in each book, since stories pack more information into less space than descriptions"],"answer":0,"explanation":"Narratives place ideas within people’s lives and prompt children to relate, question and express. There is no RTE ban on informational text; reading speed and page count are not the aim.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"NCERT EVS पुस्तकों के कई अध्याय वर्णनात्मक जानकारी के बजाय कहानियों, पत्रों, डायरी-प्रविष्टियों और साक्षात्कारों के रूप में लिखे गए हैं। इसका मुख्य कारण है:","optionsHi":["बच्चों के अनुभव से जुड़ना, सामाजिक संदर्भ को साथ लाना और उन्हें सोचने के लिए आमंत्रित करना, न कि याद करने के लिए तथ्य देना","पठन-गति और प्रवाह सुधारना ताकि बच्चे अपनी भाषा-परीक्षाओं और पठन-आकलनों में बेहतर अंक पाएँ","RTE के उस नियम का पालन करना जो प्राथमिक कक्षाओं में पूरी तरह सूचनात्मक पाठ पर रोक लगाता है और हर विषय में कहानियाँ अनिवार्य करता है","हर पुस्तक के पन्नों की संख्या कम करना, क्योंकि कहानियाँ वर्णनों की तुलना में कम जगह में अधिक जानकारी समेटती हैं"],"explanationHi":"कथाएँ विचारों को लोगों के जीवन में रखती हैं और बच्चों को जुड़ने, प्रश्न करने और अभिव्यक्त करने के लिए प्रेरित करती हैं। सूचनात्मक पाठ पर RTE का कोई प्रतिबंध नहीं है; पठन-गति और पन्नों की संख्या उद्देश्य नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-269","question":"A teacher in a tribal area of Jharkhand finds that the EVS chapter on farming describes crops that are not grown locally. The best course of action is to:","options":["teach the chapter exactly as it is written, since the examinations are based only on the textbook content","skip the chapter entirely because its crops do not suit the children and will not interest them","ask children to memorise the textbook crops first and then the local crops as additional work","adapt the lesson to local crops, farming practices and children’s knowledge, comparing with the textbook"],"answer":3,"explanation":"Contextualising meets the same learning goals through what children know and adds a comparison. Skipping loses the goals; teaching unchanged or doubling the memory load misses the point of EVS.","difficulty":"hard","source":"CTET Paper 1 · JTET","questionHi":"झारखंड के एक आदिवासी क्षेत्र का एक शिक्षक पाता है कि खेती पर EVS का अध्याय ऐसी फ़सलों का वर्णन करता है जो स्थानीय रूप से नहीं उगाई जातीं। सबसे अच्छा कदम है:","optionsHi":["अध्याय को ठीक वैसे ही पढ़ाना जैसा लिखा है, क्योंकि परीक्षाएँ केवल पाठ्यपुस्तक की सामग्री पर आधारित हैं","अध्याय को पूरी तरह छोड़ देना क्योंकि उसकी फ़सलें बच्चों के अनुकूल नहीं हैं और उनकी रुचि नहीं जगाएँगी","बच्चों से पहले पाठ्यपुस्तक की फ़सलें याद करने को कहना और फिर अतिरिक्त कार्य के रूप में स्थानीय फ़सलें","पाठ को स्थानीय फ़सलों, खेती की पद्धतियों और बच्चों के ज्ञान के अनुसार ढालना, पाठ्यपुस्तक से तुलना करते हुए"],"explanationHi":"संदर्भीकरण वही अधिगम-लक्ष्य उस ज्ञान के माध्यम से पूरे करता है जो बच्चों के पास है और तुलना जोड़ता है। छोड़ने से लक्ष्य खो जाते हैं; अपरिवर्तित पढ़ाना या स्मृति का भार दोगुना करना EVS के उद्देश्य से चूक जाता है।"},
  {"id":"cdp-pedagogy-subjects-270","question":"Which of the following is the best example of meaningful integration of EVS with mathematics in Class 4?","options":["Children solve textbook sums in which the names of animals and plants replace the usual numbers","Children measure a stick’s shadow at different times of day, record the lengths and compare them","Children count the pictures of animals printed in the EVS textbook and write the totals in a table","Children copy multiplication tables onto a large chart decorated with drawings of trees and birds"],"answer":1,"explanation":"Measuring and recording a real phenomenon uses mathematics to make sense of the environment. The others are cosmetic: EVS words or pictures are pasted onto routine maths.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 में EVS और गणित के सार्थक एकीकरण का सबसे अच्छा उदाहरण निम्नलिखित में से कौन-सा है?","optionsHi":["बच्चे पाठ्यपुस्तक के ऐसे प्रश्न हल करते हैं जिनमें सामान्य संख्याओं की जगह जानवरों और पौधों के नाम होते हैं","बच्चे दिन के अलग-अलग समय पर किसी छड़ी की छाया मापते हैं, लंबाइयाँ दर्ज करते हैं और उनकी तुलना करते हैं","बच्चे EVS पाठ्यपुस्तक में छपे जानवरों के चित्र गिनते हैं और कुल संख्याएँ तालिका में लिखते हैं","बच्चे पेड़ों और पक्षियों के चित्रों से सजे बड़े चार्ट पर पहाड़े उतारते हैं"],"explanationHi":"किसी वास्तविक परिघटना को मापना और दर्ज करना पर्यावरण को समझने के लिए गणित का उपयोग करता है। अन्य सतही हैं: नियमित गणित पर EVS के शब्द या चित्र चिपका दिए गए हैं।"},
  {"id":"cdp-pedagogy-subjects-271","question":"Consider these statements about the NCERT EVS syllabus for Classes III–V: 1. Each sub-theme is opened up through ‘key questions’ rather than a list of content to be covered. 2. Definitions and technical terms are discouraged at this stage. 3. The experiences of children and their communities are treated as valid knowledge. Which are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 only"],"answer":2,"explanation":"The syllabus is laid out as key questions, key concepts, resources and activities; it avoids definitions and treats lived experience as knowledge. All three statements hold.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा III–V के NCERT EVS पाठ्यक्रम के बारे में इन कथनों पर विचार कीजिए: 1. प्रत्येक उप-थीम को पूरी की जाने वाली सामग्री की सूची के बजाय ‘मुख्य प्रश्नों’ के माध्यम से खोला जाता है। 2. इस चरण पर परिभाषाओं और तकनीकी शब्दों को हतोत्साहित किया जाता है। 3. बच्चों और उनके समुदायों के अनुभवों को वैध ज्ञान माना जाता है। कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","1, 2 और 3","केवल 1"],"explanationHi":"पाठ्यक्रम मुख्य प्रश्नों, मुख्य संप्रत्ययों, संसाधनों और गतिविधियों के रूप में रखा गया है; वह परिभाषाओं से बचता है और जिए हुए अनुभव को ज्ञान मानता है। तीनों कथन सही हैं।"},
  {"id":"cdp-pedagogy-subjects-272","question":"Which is the WEAKEST justification for teaching EVS through activities?","options":["Activities keep children busy, so the class stays quiet and disciplined","Activities let children build ideas through their own direct experience","Activities let children with different abilities take part in learning together","Activities develop process skills such as observing and predicting"],"answer":0,"explanation":"Activities are meant to drive thinking, not to manage behaviour; ‘busy work’ with no learning aim is a known misuse. The other three are genuine pedagogical reasons.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"गतिविधियों के माध्यम से EVS पढ़ाने के पक्ष में सबसे कमज़ोर औचित्य कौन-सा है?","optionsHi":["गतिविधियाँ बच्चों को व्यस्त रखती हैं, इसलिए कक्षा शांत और अनुशासित रहती है","गतिविधियाँ बच्चों को अपने प्रत्यक्ष अनुभव से विचार बनाने देती हैं","गतिविधियाँ अलग-अलग क्षमताओं वाले बच्चों को साथ मिलकर सीखने में भाग लेने देती हैं","गतिविधियाँ अवलोकन और पूर्वानुमान जैसे प्रक्रिया कौशल विकसित करती हैं"],"explanationHi":"गतिविधियों का उद्देश्य चिंतन को आगे बढ़ाना है, व्यवहार को सँभालना नहीं; बिना किसी अधिगम-उद्देश्य के ‘व्यस्त रखने वाला काम’ एक ज्ञात दुरुपयोग है। अन्य तीन वास्तविक शैक्षिक कारण हैं।"},
  {"id":"cdp-pedagogy-subjects-273","question":"Assertion (A): EVS uses the child’s local environment as a major learning resource. Reason (R): The NCERT EVS books contain a large number of pictures. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Both are true, but the use of the local environment rests on constructivism and contextual learning, not on the books having pictures.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): EVS बच्चे के स्थानीय पर्यावरण को एक प्रमुख अधिगम संसाधन के रूप में उपयोग करता है। कारण (R): NCERT EVS पुस्तकों में बड़ी संख्या में चित्र हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"दोनों सत्य हैं, लेकिन स्थानीय पर्यावरण का उपयोग रचनावाद और संदर्भगत अधिगम पर आधारित है, पुस्तकों में चित्र होने पर नहीं।"},
  {"id":"cdp-pedagogy-subjects-274","question":"Class 5 children of a fishing village in Odisha are studying ‘Travel’. The teacher invites fishermen parents to explain how they find their way at sea using wind, stars and birds. This mainly shows:","options":["the community being used as a learning resource and local knowledge being valued","a way to reduce the teacher’s workload by letting parents take the lesson","traditional belief being taught in place of scientific knowledge of navigation","early vocational training so that the children can later join the family trade in fishing"],"answer":0,"explanation":"Navigation by wind and stars is real, tested local knowledge, and bringing parents in links school with community. It is not a replacement for science, nor vocational training.","difficulty":"hard","source":"CTET Paper 1 · OTET","questionHi":"ओडिशा के एक मछुआरा गाँव के कक्षा 5 के बच्चे ‘यात्रा’ का अध्ययन कर रहे हैं। शिक्षक मछुआरे अभिभावकों को आमंत्रित करता है कि वे समझाएँ कि वे समुद्र में हवा, तारों और पक्षियों से रास्ता कैसे खोजते हैं। यह मुख्य रूप से दर्शाता है:","optionsHi":["समुदाय को अधिगम संसाधन के रूप में उपयोग करना और स्थानीय ज्ञान को महत्त्व देना","अभिभावकों से पाठ पढ़वाकर शिक्षक का कार्यभार घटाने का तरीका","दिशा-ज्ञान के वैज्ञानिक ज्ञान के स्थान पर पारंपरिक विश्वास पढ़ाना","प्रारंभिक व्यावसायिक प्रशिक्षण ताकि बच्चे आगे चलकर परिवार के मछली पकड़ने के व्यवसाय में जा सकें"],"explanationHi":"हवा और तारों से दिशा पहचानना वास्तविक, परखा हुआ स्थानीय ज्ञान है, और अभिभावकों को लाना विद्यालय को समुदाय से जोड़ता है। यह विज्ञान का प्रतिस्थापन नहीं है, न ही व्यावसायिक प्रशिक्षण।"},
  {"id":"cdp-pedagogy-subjects-275","question":"A head teacher lists claims to show that her school follows an ‘integrated approach’ to EVS. Which claim actually reflects integration?","options":["EVS, Hindi and Mathematics are all taught by the same class teacher, so she can link them whenever she likes","The EVS period is combined with the art period to save time, and children draw whatever the chapter shows","Science and social science chapters are printed together in one EVS book, although each of them is still taught separately","A theme such as ‘Shelter’ is explored through materials, climate, the people who build houses and those with no home"],"answer":3,"explanation":"Integration is about ideas: one theme viewed through natural, social and ethical lenses. One teacher, merged periods or a combined binding do not integrate knowledge.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक प्रधानाध्यापिका यह दिखाने के लिए दावे गिनाती है कि उसका विद्यालय EVS के प्रति ‘एकीकृत उपागम’ अपनाता है। कौन-सा दावा वास्तव में एकीकरण को दर्शाता है?","optionsHi":["EVS, हिंदी और गणित सब एक ही कक्षा-शिक्षक पढ़ाता है, इसलिए वह जब चाहे उन्हें जोड़ सकती है","समय बचाने के लिए EVS का कालांश कला के कालांश के साथ मिला दिया गया है, और बच्चे वही बनाते हैं जो अध्याय में दिखाया गया है","विज्ञान और सामाजिक विज्ञान के अध्याय एक EVS पुस्तक में साथ-साथ छापे गए हैं, हालाँकि उनमें से प्रत्येक अब भी अलग पढ़ाया जाता है","‘आवास’ जैसी थीम की खोजबीन सामग्री, जलवायु, घर बनाने वाले लोगों और बेघर लोगों के माध्यम से की जाती है"],"explanationHi":"एकीकरण विचारों का होता है: एक थीम को प्राकृतिक, सामाजिक और नैतिक दृष्टियों से देखना। एक शिक्षक, मिले हुए कालांश या साझा जिल्द ज्ञान को एकीकृत नहीं करते।"},
  {"id":"cdp-pedagogy-subjects-276","question":"A Class VII social science teacher in Jaipur tells her students, 'This subject is only facts and dates, so learn the question bank by heart before the test.' Which position of NCF 2005 does her remark most directly contradict?","options":["Social science should build conceptual understanding and the ability to question social reality, not the memorising of facts","Social science should be merged into science in the upper primary classes so that it becomes more useful for careers","Social science should be taught only from the prescribed board textbook so that all schools stay uniform in content","Social science should mainly train students to obey rules and be loyal to the state, as good and dutiful citizens are expected to"],"answer":0,"explanation":"NCF 2005 wants social science to move from loading information to building concepts and a critical, questioning outlook. Obedience-centred 'civics' and textbook-only teaching are the very things the framework criticises.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"जयपुर में कक्षा VII की एक सामाजिक विज्ञान शिक्षिका अपने विद्यार्थियों से कहती है, ‘यह विषय केवल तथ्यों और तिथियों का है, इसलिए परीक्षा से पहले प्रश्न-बैंक को कंठस्थ कर लो।’ उसकी यह टिप्पणी NCF 2005 के किस मत का सबसे सीधा खंडन करती है?","optionsHi":["सामाजिक विज्ञान को वैचारिक समझ और सामाजिक यथार्थ पर प्रश्न उठाने की क्षमता विकसित करनी चाहिए, तथ्यों को रटने की नहीं","उच्च प्राथमिक कक्षाओं में सामाजिक विज्ञान को विज्ञान में मिला देना चाहिए ताकि वह कॅरियर के लिए अधिक उपयोगी बने","सामाजिक विज्ञान केवल निर्धारित बोर्ड की पाठ्यपुस्तक से पढ़ाया जाना चाहिए ताकि सभी विद्यालयों में सामग्री एकसमान रहे","सामाजिक विज्ञान को मुख्य रूप से विद्यार्थियों को नियमों का पालन करना और राज्य के प्रति निष्ठावान होना सिखाना चाहिए, जैसा अच्छे और कर्तव्यनिष्ठ नागरिकों से अपेक्षित है"],"explanationHi":"NCF 2005 चाहता है कि सामाजिक विज्ञान सूचना लादने से हटकर संप्रत्यय और आलोचनात्मक, प्रश्न करने वाला दृष्टिकोण निर्मित करे। आज्ञाकारिता-केंद्रित ‘नागरिक शास्त्र’ और केवल पाठ्यपुस्तक से शिक्षण वही चीज़ें हैं जिनकी रूपरेखा आलोचना करती है।"},
  {"id":"cdp-pedagogy-subjects-277","question":"Assertion (A): NCF 2005 recommends using the term 'political science' in place of 'civics' for the upper primary and secondary stages.\nReason (R): 'Civics' carried a colonial association with training loyal, obedient subjects, whereas the aim now is to prepare thinking citizens of a democracy.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The position paper argues that civics grew in the colonial period to stress obedience and loyalty; political science is meant to build an understanding of democratic institutions and the ability to question them. R gives the actual reason for A.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"अभिकथन (A): NCF 2005 उच्च प्राथमिक और माध्यमिक चरणों के लिए ‘नागरिक शास्त्र’ के स्थान पर ‘राजनीति विज्ञान’ शब्द के उपयोग की अनुशंसा करता है। कारण (R): ‘नागरिक शास्त्र’ में निष्ठावान, आज्ञाकारी प्रजा तैयार करने का औपनिवेशिक संबंध था, जबकि अब उद्देश्य लोकतंत्र के चिंतनशील नागरिक तैयार करना है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"पोज़ीशन पेपर तर्क देता है कि नागरिक शास्त्र औपनिवेशिक काल में आज्ञाकारिता और निष्ठा पर ज़ोर देने के लिए विकसित हुआ; राजनीति विज्ञान का उद्देश्य लोकतांत्रिक संस्थाओं की समझ और उन पर प्रश्न उठाने की क्षमता निर्मित करना है। R, A का वास्तविक कारण देता है।"},
  {"id":"cdp-pedagogy-subjects-278","question":"Which of the following statements reflect the NCF 2005 view of social science?\n1. Social science lays the foundation for an analytical and creative mindset.\n2. Because social science is non-utilitarian, it deserves less curriculum time than science.\n3. A gender perspective should run through the content of social science rather than sit in one chapter.","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"NCF 2005 rejects the common belief that social science is 'non-utilitarian' and less important; it argues the subject builds analytical, creative thinking. It also asks for gender to be integrated across themes, so 1 and 3 are correct.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"निम्नलिखित में से कौन-से कथन सामाजिक विज्ञान के बारे में NCF 2005 के दृष्टिकोण को दर्शाते हैं? 1. सामाजिक विज्ञान विश्लेषणात्मक और रचनात्मक मानसिकता की नींव रखता है। 2. क्योंकि सामाजिक विज्ञान अनुपयोगितावादी है, वह विज्ञान से कम पाठ्यचर्या-समय का हकदार है। 3. लैंगिक परिप्रेक्ष्य को सामाजिक विज्ञान की विषय-वस्तु में एक अध्याय तक सीमित रहने के बजाय पूरे में चलना चाहिए।","optionsHi":["केवल 1 और 2","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"NCF 2005 इस सामान्य धारणा को अस्वीकार करता है कि सामाजिक विज्ञान ‘अनुपयोगितावादी’ और कम महत्त्वपूर्ण है; वह तर्क देता है कि यह विषय विश्लेषणात्मक, रचनात्मक चिंतन निर्मित करता है। वह यह भी चाहता है कि लिंग को सभी थीम में समाहित किया जाए, इसलिए 1 और 3 सही हैं।"},
  {"id":"cdp-pedagogy-subjects-279","question":"Before introducing the term 'market', a Class VII teacher in a Bihar town asks pupils to find out where a vegetable seller at the weekly haat buys her stock, how much she pays and what she earns in a day. This choice best reflects which approach recommended for economics?","options":["Replacing economic concepts with stories so that no formal economic theory is taught at this stage","Postponing all economic ideas to Class XI, when students are mature enough to handle abstract theory","Studying economic life from the point of view of ordinary people and their everyday experience","Training pupils to recite definitions of demand and supply accurately before they observe any market"],"answer":2,"explanation":"NCF 2005 asks that economics be approached from the perspective of people, such as the vendor, the farmer and the consumer, so that concepts grow out of lived experience. The concept is still taught; it simply begins from what children can observe.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"‘बाज़ार’ शब्द से परिचित कराने से पहले, बिहार के एक कस्बे की कक्षा VII की शिक्षिका विद्यार्थियों से पता लगाने को कहती है कि साप्ताहिक हाट में सब्ज़ी बेचने वाली महिला अपना माल कहाँ से खरीदती है, कितना देती है और एक दिन में कितना कमाती है। यह चुनाव अर्थशास्त्र के लिए अनुशंसित किस उपागम को सबसे अच्छी तरह दर्शाता है?","optionsHi":["आर्थिक संप्रत्ययों को कहानियों से बदलना ताकि इस चरण पर कोई औपचारिक आर्थिक सिद्धांत न पढ़ाया जाए","सभी आर्थिक विचारों को कक्षा XI तक टालना, जब विद्यार्थी अमूर्त सिद्धांत सँभालने के लिए पर्याप्त परिपक्व हों","आर्थिक जीवन का अध्ययन साधारण लोगों के दृष्टिकोण और उनके रोज़मर्रा के अनुभव से करना","विद्यार्थियों को किसी भी बाज़ार का अवलोकन करने से पहले माँग और आपूर्ति की परिभाषाएँ सटीक रूप से दोहराने का प्रशिक्षण देना"],"explanationHi":"NCF 2005 चाहता है कि अर्थशास्त्र को लोगों, जैसे विक्रेता, किसान और उपभोक्ता, के दृष्टिकोण से अपनाया जाए, ताकि संप्रत्यय जिए हुए अनुभव से उभरें। संप्रत्यय फिर भी पढ़ाया जाता है; वह बस उससे शुरू होता है जो बच्चे देख सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-280","question":"For a Class VIII lesson on the Revolt of 1857, a teacher gives groups a British official's report, a petition written by a sepoy, and a song remembered in a village of the region. What is the main learning she intends?","options":["Students should conclude that since the accounts disagree, none of them can be trusted as evidence","Students should rely on the teacher to tell them which of the three accounts is the correct, official one","Students should cover more of the syllabus in less time by dividing the sources among the groups","Students should see that the past is reconstructed from varied sources reflecting different viewpoints"],"answer":3,"explanation":"Using several sources teaches that history is an interpretation built from evidence and that each source carries its author's position. The trap is relativism: disagreement among sources calls for weighing them, not rejecting all of them.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"1857 के विद्रोह पर कक्षा VIII के पाठ के लिए, एक शिक्षिका समूहों को एक ब्रिटिश अधिकारी की रिपोर्ट, एक सिपाही द्वारा लिखा गया प्रार्थना-पत्र और क्षेत्र के एक गाँव में याद किया जाने वाला गीत देती है। उसका मुख्य अधिगम-उद्देश्य क्या है?","optionsHi":["विद्यार्थी यह निष्कर्ष निकालें कि चूँकि विवरण आपस में असहमत हैं, उनमें से कोई भी प्रमाण के रूप में भरोसेमंद नहीं है","विद्यार्थी यह बताने के लिए शिक्षिका पर निर्भर रहें कि तीनों में से कौन-सा विवरण सही, आधिकारिक है","विद्यार्थी समूहों में स्रोत बाँटकर कम समय में अधिक पाठ्यक्रम पूरा करें","विद्यार्थी देखें कि अतीत का पुनर्निर्माण विभिन्न दृष्टिकोणों को दर्शाने वाले विविध स्रोतों से किया जाता है"],"explanationHi":"कई स्रोतों का उपयोग सिखाता है कि इतिहास प्रमाणों पर बनी व्याख्या है और हर स्रोत अपने लेखक की स्थिति लिए होता है। जाल सापेक्षवाद है: स्रोतों में असहमति उन्हें तौलने की माँग करती है, सभी को अस्वीकार करने की नहीं।"},
  {"id":"cdp-pedagogy-subjects-281","question":"A Class VI history unit on the Mauryas in a Kendriya Vidyalaya covers only Ashoka's conquests, edicts and administration. A reviewer asks the teacher to add how farmers, crafts-people and traders lived and paid taxes. The reviewer's suggestion best addresses which concern of NCF 2005?","options":["History should be reduced to fewer chapters so that the syllabus becomes lighter","History must include the lives of ordinary people and not only rulers and wars","History should avoid ancient periods because the available sources are limited","History should be taught through dates arranged in a clear chronological chart"],"answer":1,"explanation":"NCF 2005 criticises history taught as a chronicle of kings and battles and asks that the everyday lives of common people, including peasants, artisans and women, be part of the story.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"केंद्रीय विद्यालय में मौर्यों पर कक्षा VI की इतिहास इकाई केवल अशोक की विजयों, शिलालेखों और प्रशासन को कवर करती है। एक समीक्षक शिक्षक से कहता है कि वह जोड़े कि किसान, शिल्पकार और व्यापारी कैसे रहते थे और कर कैसे चुकाते थे। समीक्षक का सुझाव NCF 2005 की किस चिंता का सबसे अच्छा समाधान करता है?","optionsHi":["इतिहास को कम अध्यायों तक सीमित किया जाना चाहिए ताकि पाठ्यक्रम हल्का हो जाए","इतिहास में केवल शासकों और युद्धों का नहीं, बल्कि आम लोगों का जीवन भी शामिल होना चाहिए","इतिहास को प्राचीन कालों से बचना चाहिए क्योंकि उपलब्ध स्रोत सीमित हैं","इतिहास को स्पष्ट कालक्रम चार्ट में व्यवस्थित तिथियों के माध्यम से पढ़ाया जाना चाहिए"],"explanationHi":"NCF 2005 राजाओं और युद्धों के वृत्तांत के रूप में पढ़ाए जाने वाले इतिहास की आलोचना करता है और माँग करता है कि किसानों, कारीगरों और महिलाओं सहित आम लोगों का रोज़मर्रा का जीवन कहानी का भाग हो।"},
  {"id":"cdp-pedagogy-subjects-282","question":"A teacher plans a four-week theme 'Water' for Class VIII: rainfall patterns (geography), stepwells of Gujarat (history), who decides on water supply in the city (political science) and the cost of buying water (economics). Which evaluation of this plan is the most accurate?","options":["It goes against NCF 2005, which wants every social science discipline taught in strict isolation from Class VI","It suits only primary EVS and is unsuitable once separate textbooks begin","It turns social science into science and should be shifted to the science period","It lets students see one issue through several disciplines, an interdisciplinary approach NCF 2005 supports"],"answer":3,"explanation":"NCF 2005 favours examining important issues such as water across disciplines while still keeping disciplinary perspectives. The plan does exactly this; nothing in the framework forbids themes after the primary stage.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"एक शिक्षक कक्षा VIII के लिए चार सप्ताह की थीम ‘जल’ की योजना बनाता है: वर्षा के प्रतिरूप (भूगोल), गुजरात की बावड़ियाँ (इतिहास), शहर में जल-आपूर्ति के बारे में कौन निर्णय लेता है (राजनीति विज्ञान) और पानी खरीदने की लागत (अर्थशास्त्र)। इस योजना का कौन-सा मूल्यांकन सबसे सटीक है?","optionsHi":["यह NCF 2005 के विरुद्ध है, जो कक्षा VI से हर सामाजिक विज्ञान विषय को कड़ाई से अलग-थलग पढ़ाना चाहता है","यह केवल प्राथमिक EVS के लिए उपयुक्त है और अलग पाठ्यपुस्तकें शुरू होने के बाद अनुपयुक्त है","यह सामाजिक विज्ञान को विज्ञान बना देती है और इसे विज्ञान के कालांश में स्थानांतरित कर देना चाहिए","यह विद्यार्थियों को एक मुद्दे को कई विषयों से देखने देती है, जो NCF 2005 द्वारा समर्थित अंतर-अनुशासनिक उपागम है"],"explanationHi":"NCF 2005 जल जैसे महत्त्वपूर्ण मुद्दों की विषयों के आर-पार जाँच का पक्ष लेता है, साथ ही अनुशासनात्मक दृष्टिकोणों को भी बनाए रखता है। योजना ठीक यही करती है; रूपरेखा में प्राथमिक चरण के बाद थीम को रोकने वाली कोई बात नहीं है।"},
  {"id":"cdp-pedagogy-subjects-283","question":"While teaching secularism in Class VIII, Mr. Rawat notices some students voicing strong opinions about other communities. Which response is most in line with the normative role of social science described in NCF 2005?","options":["Tell students his own religious views clearly so that they know what the correct opinion is","Skip the chapter, because religion is too sensitive a subject to discuss in a classroom of mixed communities","Use real cases to help students reflect on equality, dignity and the constitutional idea of secularism","Ask students to memorise the textbook definition of secularism and reproduce it in the test"],"answer":2,"explanation":"Social science has a normative responsibility to help students engage with constitutional values, but through reflection and evidence, not preaching. Avoiding the topic or reducing it to a definition loses the very learning the chapter is meant for.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा VIII में धर्मनिरपेक्षता पढ़ाते समय श्री रावत देखते हैं कि कुछ विद्यार्थी अन्य समुदायों के बारे में तीखी राय व्यक्त कर रहे हैं। NCF 2005 में वर्णित सामाजिक विज्ञान की मानकीय भूमिका के सबसे अनुरूप प्रतिक्रिया कौन-सी है?","optionsHi":["विद्यार्थियों को अपने धार्मिक विचार स्पष्ट रूप से बताना ताकि वे जान सकें कि सही राय क्या है","अध्याय छोड़ देना, क्योंकि मिश्रित समुदायों की कक्षा में धर्म चर्चा के लिए बहुत संवेदनशील विषय है","समानता, गरिमा और धर्मनिरपेक्षता के संवैधानिक विचार पर चिंतन में विद्यार्थियों की मदद करने के लिए वास्तविक उदाहरणों का उपयोग करना","विद्यार्थियों से धर्मनिरपेक्षता की पाठ्यपुस्तक वाली परिभाषा याद करने और परीक्षा में दोहराने को कहना"],"explanationHi":"सामाजिक विज्ञान का मानकीय दायित्व है कि वह विद्यार्थियों को संवैधानिक मूल्यों से जोड़े, लेकिन चिंतन और प्रमाण के माध्यम से, उपदेश से नहीं। विषय से बचना या उसे परिभाषा तक सीमित करना उस अधिगम को खो देता है जिसके लिए अध्याय है।"},
  {"id":"cdp-pedagogy-subjects-284","question":"At a parent-teacher meeting in a Pune school, parents ask the Class IX teacher to cut social science homework because 'it will not help in any career'. Which reply is best grounded in NCF 2005?","options":["Social science builds the inquiry, analysis and judgement that every citizen and profession needs in a democracy","They are right, and the school will reduce social science periods to give more time to science and mathematics","Social science matters only because its marks count in the board examination total and affect the percentage","Social science is useful only for students who will later sit the civil services or other competitive examinations"],"answer":0,"explanation":"NCF 2005 names the belief that social science is non-utilitarian as a problem and argues that the subject builds critical, analytical capacities needed by all. Answers based only on marks or one career accept the narrow view instead of correcting it.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"पुणे के एक विद्यालय में अभिभावक-शिक्षक बैठक में अभिभावक कक्षा IX के शिक्षक से सामाजिक विज्ञान का गृहकार्य घटाने को कहते हैं क्योंकि ‘इससे किसी कॅरियर में मदद नहीं मिलेगी’। NCF 2005 पर सबसे अच्छी तरह आधारित उत्तर कौन-सा है?","optionsHi":["सामाजिक विज्ञान वह अन्वेषण, विश्लेषण और विवेक निर्मित करता है जिसकी लोकतंत्र में हर नागरिक और हर पेशे को आवश्यकता होती है","वे सही हैं, और विद्यालय विज्ञान और गणित को अधिक समय देने के लिए सामाजिक विज्ञान के कालांश घटा देगा","सामाजिक विज्ञान केवल इसलिए मायने रखता है कि उसके अंक बोर्ड परीक्षा के कुल योग में गिने जाते हैं और प्रतिशत को प्रभावित करते हैं","सामाजिक विज्ञान केवल उन विद्यार्थियों के लिए उपयोगी है जो आगे सिविल सेवा या अन्य प्रतियोगी परीक्षाओं में बैठेंगे"],"explanationHi":"NCF 2005 इस धारणा को एक समस्या बताता है कि सामाजिक विज्ञान अनुपयोगितावादी है, और तर्क देता है कि यह विषय आलोचनात्मक, विश्लेषणात्मक क्षमताएँ निर्मित करता है जिनकी सभी को आवश्यकता है। केवल अंकों या एक कॅरियर पर आधारित उत्तर संकीर्ण दृष्टिकोण को सुधारने के बजाय स्वीकार कर लेते हैं।"},
  {"id":"cdp-pedagogy-subjects-285","question":"Assertion (A): Beginning a Class VI lesson on diversity by asking children to list the languages, foods and festivals of their own lane makes the idea more meaningful.\nReason (R): Children construct new understanding by linking it with what they already know and have experienced.","options":["Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Starting from children's own surroundings makes an abstract idea concrete, and it works precisely because learners build knowledge on their prior experience, as constructivism holds. R therefore explains A.","difficulty":"moderate","source":"CTET Paper 2 · NVS · KVS PRT","questionHi":"अभिकथन (A): कक्षा VI के विविधता पर पाठ की शुरुआत बच्चों से उनकी अपनी गली की भाषाओं, भोजन और त्योहारों की सूची बनवाकर करना विचार को अधिक अर्थपूर्ण बनाता है। कारण (R): बच्चे नई समझ को अपने पहले से ज्ञात और अनुभव किए हुए से जोड़कर निर्मित करते हैं।","optionsHi":["A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"बच्चों के अपने परिवेश से शुरू करना अमूर्त विचार को मूर्त बनाता है, और यह ठीक इसलिए काम करता है कि अधिगमकर्ता अपने पूर्व अनुभव पर ज्ञान निर्मित करते हैं, जैसा रचनावाद मानता है। इसलिए R, A की व्याख्या करता है।"},
  {"id":"cdp-pedagogy-subjects-286","question":"Which of the following statements about NCF 2005 and social science are correct?\n1. Textbooks should give one authoritative interpretation so that children are not confused.\n2. Teachers should be free to bring in local examples and resources beyond the textbook.\n3. Children's experiences are a starting point but must be linked to wider concepts.\n4. Content should be cut down to essential facts that can be memorised easily.","options":["1, 2 and 3 only","2, 3 and 4 only","2 and 3 only","1 and 4 only"],"answer":2,"explanation":"NCF 2005 values multiple perspectives and local resources and wants experience linked to concepts. Statement 1 opposes its call for plural views, and statement 4 confuses 'reducing load' with reducing learning to memorised facts.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"NCF 2005 और सामाजिक विज्ञान के बारे में निम्नलिखित में से कौन-से कथन सही हैं? 1. पाठ्यपुस्तकों को एक आधिकारिक व्याख्या देनी चाहिए ताकि बच्चे भ्रमित न हों। 2. शिक्षकों को पाठ्यपुस्तक से परे स्थानीय उदाहरण और संसाधन लाने की स्वतंत्रता होनी चाहिए। 3. बच्चों के अनुभव एक आरंभ-बिंदु हैं, लेकिन उन्हें व्यापक संप्रत्ययों से जोड़ा जाना चाहिए। 4. सामग्री को उन आवश्यक तथ्यों तक घटा देना चाहिए जिन्हें आसानी से याद किया जा सके।","optionsHi":["केवल 1, 2 और 3","केवल 2, 3 और 4","केवल 2 और 3","केवल 1 और 4"],"explanationHi":"NCF 2005 बहुल दृष्टिकोणों और स्थानीय संसाधनों को महत्त्व देता है और चाहता है कि अनुभव को संप्रत्ययों से जोड़ा जाए। कथन 1 उसकी बहुलवादी दृष्टिकोणों की माँग के विपरीत है, और कथन 4 ‘बोझ घटाने’ को अधिगम को रटे हुए तथ्यों तक सीमित करने से मिला देता है।"},
  {"id":"cdp-pedagogy-subjects-287","question":"In a discussion on poverty, a Class IX student says, 'People are poor because they do not work hard.' What should the teacher do to best serve the aims of social science?","options":["Tell the student that the remark is rude and offensive, and move on quickly to the next topic","Accept it without discussion, since every opinion in social science is equally valid","Give a lecture on the official definition of the poverty line and how the government calculates it","Ask the class to examine data and case studies on wages, land, health and schooling to test it"],"answer":3,"explanation":"Social science aims to replace prejudice with reasoning based on evidence. Testing the claim against data about structural causes builds critical thinking; silencing or merely accepting the view does not change the misconception.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"गरीबी पर चर्चा में कक्षा IX का एक विद्यार्थी कहता है, ‘लोग इसलिए गरीब हैं क्योंकि वे कड़ी मेहनत नहीं करते।’ सामाजिक विज्ञान के उद्देश्यों की सबसे अच्छी पूर्ति के लिए शिक्षक को क्या करना चाहिए?","optionsHi":["विद्यार्थी को बताना कि यह टिप्पणी अशिष्ट और आपत्तिजनक है, और जल्दी अगले विषय पर बढ़ जाना","इसे बिना चर्चा के स्वीकार कर लेना, क्योंकि सामाजिक विज्ञान में हर राय समान रूप से वैध है","गरीबी रेखा की आधिकारिक परिभाषा और सरकार उसकी गणना कैसे करती है, इस पर व्याख्यान देना","कक्षा से मज़दूरी, भूमि, स्वास्थ्य और स्कूली शिक्षा पर आँकड़ों और केस अध्ययनों की जाँच करके इसे परखने को कहना"],"explanationHi":"सामाजिक विज्ञान का उद्देश्य पूर्वाग्रह को प्रमाण पर आधारित तर्क से बदलना है। संरचनात्मक कारणों के आँकड़ों के सामने दावे को परखना आलोचनात्मक चिंतन निर्मित करता है; चुप कराना या केवल स्वीकार कर लेना भ्रांत धारणा नहीं बदलता।"},
  {"id":"cdp-pedagogy-subjects-288","question":"While teaching colonial forest laws in Class VIII, a teacher in Jharkhand includes oral accounts of how Adivasi families lost the right to collect forest produce. What is the main purpose of adding these voices?","options":["To show that one policy affected groups very differently and that history includes the experience of the marginalised","To prove that colonial rule brought no real change at all to the life of people living in forest areas","To replace the textbook chapter with local folklore, which children usually find more interesting than written history","To make the chapter shorter and easier for slower learners by telling it through simple family stories"],"answer":0,"explanation":"NCF 2005 asks that the perspectives of marginalised groups such as Adivasis, Dalits and women be part of social science. Their accounts show who gained and who lost from a policy, something an account from the rulers' side alone would hide.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VIII में औपनिवेशिक वन कानून पढ़ाते समय झारखंड का एक शिक्षक इस बारे में मौखिक वृत्तांत शामिल करता है कि आदिवासी परिवारों ने वन उपज इकट्ठा करने का अधिकार कैसे खो दिया। इन आवाज़ों को जोड़ने का मुख्य उद्देश्य क्या है?","optionsHi":["यह दिखाना कि एक ही नीति ने समूहों को बहुत अलग-अलग तरह से प्रभावित किया और इतिहास में हाशिये के लोगों का अनुभव भी शामिल है","यह सिद्ध करना कि औपनिवेशिक शासन ने वन क्षेत्रों में रहने वाले लोगों के जीवन में कोई वास्तविक बदलाव नहीं किया","पाठ्यपुस्तक के अध्याय को स्थानीय लोककथाओं से बदलना, जो बच्चों को लिखित इतिहास से अधिक रोचक लगती हैं","अध्याय को सरल पारिवारिक कहानियों के माध्यम से सुनाकर धीमे अधिगमकर्ताओं के लिए छोटा और आसान बनाना"],"explanationHi":"NCF 2005 माँग करता है कि आदिवासियों, दलितों और महिलाओं जैसे हाशिये के समूहों के दृष्टिकोण सामाजिक विज्ञान का भाग हों। उनके वृत्तांत दिखाते हैं कि किसी नीति से किसे लाभ हुआ और किसे हानि, जिसे केवल शासकों की ओर का वृत्तांत छिपा देता है।"},
  {"id":"cdp-pedagogy-subjects-289","question":"Assertion (A): Two historians working with the same set of sources may reach different conclusions about an event.\nReason (R): Historical facts do not exist; history is only a matter of personal opinion.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"Historians select and interpret evidence, so conclusions can differ. But interpretation is bound by evidence; it is not mere opinion, and facts such as dates and documents do exist. So A is true and R is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"अभिकथन (A): एक ही स्रोत-समूह के साथ काम करने वाले दो इतिहासकार किसी घटना के बारे में अलग-अलग निष्कर्ष पर पहुँच सकते हैं। कारण (R): ऐतिहासिक तथ्य मौजूद नहीं होते; इतिहास केवल व्यक्तिगत राय का विषय है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"इतिहासकार प्रमाणों का चयन और व्याख्या करते हैं, इसलिए निष्कर्ष भिन्न हो सकते हैं। लेकिन व्याख्या प्रमाण से बँधी होती है; वह मात्र राय नहीं है, और तिथियों और दस्तावेज़ों जैसे तथ्य मौजूद हैं। इसलिए A सत्य है और R असत्य है।"},
  {"id":"cdp-pedagogy-subjects-290","question":"A Class VI geography teacher spends most periods on quizzes about state capitals and the longest rivers. Which change would best bring her teaching in line with the aims of geography in NCF 2005?","options":["Add more quizzes on state capitals and rivers so that students can remember even more names and facts","Have students study how people of a region adapt their houses, crops and work to its climate and land","Drop maps entirely, since map work mostly encourages rote learning of places and boundaries","Replace geography periods with general knowledge periods that cover a wider range of facts"],"answer":1,"explanation":"Geography in NCF 2005 is about the relation between people and their environment, studied from local to global. A list of names is information, not geographical understanding, while maps remain a central tool rather than something to drop.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VI की एक भूगोल शिक्षिका अधिकांश कालांश राज्यों की राजधानियों और सबसे लंबी नदियों पर प्रश्नोत्तरी में बिताती है। कौन-सा परिवर्तन उसके शिक्षण को NCF 2005 में भूगोल के उद्देश्यों के अनुरूप सबसे अच्छी तरह लाएगा?","optionsHi":["राज्यों की राजधानियों और नदियों पर और प्रश्नोत्तरियाँ जोड़ना ताकि विद्यार्थी और भी अधिक नाम और तथ्य याद रख सकें","विद्यार्थियों से अध्ययन करवाना कि किसी क्षेत्र के लोग अपने घरों, फ़सलों और कार्य को वहाँ की जलवायु और भूमि के अनुसार कैसे ढालते हैं","मानचित्रों को पूरी तरह छोड़ देना, क्योंकि मानचित्र कार्य अधिकतर स्थानों और सीमाओं को रटने को बढ़ावा देता है","भूगोल के कालांशों को सामान्य ज्ञान के कालांशों से बदलना, जो तथ्यों की व्यापक शृंखला को कवर करते हैं"],"explanationHi":"NCF 2005 में भूगोल लोगों और उनके पर्यावरण के संबंध का विषय है, जिसका अध्ययन स्थानीय से वैश्विक तक किया जाता है। नामों की सूची सूचना है, भौगोलिक समझ नहीं, जबकि मानचित्र छोड़ने की चीज़ नहीं, बल्कि केंद्रीय उपकरण बने रहते हैं।"},
  {"id":"cdp-pedagogy-subjects-291","question":"An NCERT Social and Political Life chapter explains equality through the story of a man who is refused entry to a place because of his caste. Why do such textbooks use narratives of individual lives?","options":["Stories are easier to memorise than definitions, so students can reproduce them and improve board results","Narratives avoid the need to discuss constitutional provisions, which are too difficult for Class VII students","Narratives replace concepts, so students need not learn a formal meaning of equality at this stage at all","A real-life situation makes an abstract idea like equality concrete and lets children feel its human meaning"],"answer":3,"explanation":"Case studies and narratives anchor abstract political ideas in situations children can relate to, after which the concept and the relevant constitutional value are discussed. The story leads to the concept; it does not replace it.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"NCERT का एक ‘सामाजिक एवं राजनीतिक जीवन’ अध्याय एक ऐसे व्यक्ति की कहानी के माध्यम से समानता समझाता है जिसे जाति के कारण किसी स्थान पर प्रवेश से मना कर दिया जाता है। ऐसी पाठ्यपुस्तकें व्यक्तिगत जीवन की कथाओं का उपयोग क्यों करती हैं?","optionsHi":["कहानियाँ परिभाषाओं की तुलना में याद करना आसान होता है, इसलिए विद्यार्थी उन्हें दोहरा सकते हैं और बोर्ड परिणाम सुधार सकते हैं","कथाएँ संवैधानिक प्रावधानों की चर्चा की आवश्यकता से बचाती हैं, जो कक्षा VII के विद्यार्थियों के लिए बहुत कठिन हैं","कथाएँ संप्रत्ययों का स्थान लेती हैं, इसलिए इस चरण पर विद्यार्थियों को समानता का औपचारिक अर्थ सीखने की आवश्यकता ही नहीं","वास्तविक जीवन की स्थिति समानता जैसे अमूर्त विचार को मूर्त बनाती है और बच्चों को उसका मानवीय अर्थ महसूस करने देती है"],"explanationHi":"केस अध्ययन और कथाएँ अमूर्त राजनीतिक विचारों को उन स्थितियों में स्थापित करती हैं जिनसे बच्चे जुड़ सकते हैं, जिसके बाद संप्रत्यय और संबंधित संवैधानिक मूल्य पर चर्चा की जाती है। कहानी संप्रत्यय तक ले जाती है; उसका स्थान नहीं लेती।"},
  {"id":"cdp-pedagogy-subjects-292","question":"Which of these questions best reflects the NCF 2005 idea of connecting social science with children's lives in a Class VI lesson on local government?","options":["List five functions of the gram panchayat given in the chapter, with an example of each","Define 'local self-government' in your own words and give its meaning in one line","Find out one problem your gram panchayat or ward office handled recently, and how","Write the year in which panchayats received constitutional status and the amendment number"],"answer":2,"explanation":"The investigative task links the concept to the child's own locality and requires inquiry. The other options test recall of textbook information or dates, even when phrased as 'in your own words'.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"स्थानीय सरकार पर कक्षा VI के पाठ में सामाजिक विज्ञान को बच्चों के जीवन से जोड़ने के NCF 2005 के विचार को इनमें से कौन-सा प्रश्न सबसे अच्छी तरह दर्शाता है?","optionsHi":["अध्याय में दिए ग्राम पंचायत के पाँच कार्यों की सूची बनाइए, प्रत्येक का एक उदाहरण देते हुए","‘स्थानीय स्वशासन’ को अपने शब्दों में परिभाषित कीजिए और उसका अर्थ एक पंक्ति में बताइए","पता लगाइए कि आपकी ग्राम पंचायत या वार्ड कार्यालय ने हाल में कौन-सी एक समस्या सुलझाई, और कैसे","वह वर्ष लिखिए जिसमें पंचायतों को संवैधानिक दर्जा मिला और संशोधन की संख्या"],"explanationHi":"अन्वेषणात्मक कार्य संप्रत्यय को बच्चे के अपने क्षेत्र से जोड़ता है और अन्वेषण की माँग करता है। अन्य विकल्प पाठ्यपुस्तक की जानकारी या तिथियों के स्मरण की जाँच करते हैं, भले ही ‘अपने शब्दों में’ कहा गया हो।"},
  {"id":"cdp-pedagogy-subjects-293","question":"Two Class VIII teachers plan a lesson on citizenship. Teacher P stresses that good citizens pay taxes, obey laws and respect the flag. Teacher Q asks students why some colonies in their city get water daily while others get it twice a week, and what citizens could do about it. Which judgement fits NCF 2005 best?","options":["Teacher P, because obedience to laws and authority is the core aim of political science at this stage","Teacher Q, because it builds the ability to question social reality and to take part in democracy","Both are equally aligned, since NCF 2005 gives no preference between the two kinds of lesson","Neither, because social science should not take up problems from the students' own city or colony"],"answer":1,"explanation":"NCF 2005 wants learners who can critically examine social reality and participate in democracy, not merely obey. Teacher P's content is not wrong, but limiting citizenship to obedience is the old 'civics' view the framework moves away from.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा VIII के दो शिक्षक नागरिकता पर पाठ की योजना बनाते हैं। शिक्षक P ज़ोर देता है कि अच्छे नागरिक कर चुकाते हैं, कानूनों का पालन करते हैं और ध्वज का सम्मान करते हैं। शिक्षक Q विद्यार्थियों से पूछता है कि उनके शहर की कुछ कॉलोनियों में रोज़ पानी क्यों आता है जबकि अन्य में सप्ताह में दो बार, और नागरिक इसके बारे में क्या कर सकते हैं। कौन-सा निर्णय NCF 2005 के सबसे अनुरूप है?","optionsHi":["शिक्षक P, क्योंकि कानूनों और सत्ता का पालन इस चरण पर राजनीति विज्ञान का मूल उद्देश्य है","शिक्षक Q, क्योंकि यह सामाजिक यथार्थ पर प्रश्न उठाने और लोकतंत्र में भाग लेने की क्षमता निर्मित करता है","दोनों समान रूप से अनुरूप हैं, क्योंकि NCF 2005 दोनों प्रकार के पाठों के बीच कोई वरीयता नहीं देता","दोनों में से कोई नहीं, क्योंकि सामाजिक विज्ञान को विद्यार्थियों के अपने शहर या कॉलोनी की समस्याएँ नहीं उठानी चाहिए"],"explanationHi":"NCF 2005 ऐसे अधिगमकर्ता चाहता है जो सामाजिक यथार्थ की आलोचनात्मक जाँच कर सकें और लोकतंत्र में भाग ले सकें, केवल आज्ञापालन नहीं। शिक्षक P की सामग्री गलत नहीं है, लेकिन नागरिकता को आज्ञापालन तक सीमित करना पुराना ‘नागरिक शास्त्र’ का दृष्टिकोण है जिससे रूपरेखा दूर जाती है।"},
  {"id":"cdp-pedagogy-subjects-294","question":"Assertion (A): Social science uses systematic methods of inquiry such as gathering evidence, comparing cases and examining sources.\nReason (R): Social phenomena can always be tested through controlled laboratory experiments, just as in physics.","options":["Both A and R are true and R is the correct explanation of A","A is false but R is true","Both A and R are true but R is not the correct explanation of A","A is true but R is false"],"answer":3,"explanation":"Social sciences are rigorous in their own way through evidence, comparison and interpretation, but most social phenomena cannot be put through controlled experiments. So A is true and R is false.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): सामाजिक विज्ञान प्रमाण इकट्ठा करने, मामलों की तुलना करने और स्रोतों की जाँच करने जैसी अन्वेषण की व्यवस्थित विधियों का उपयोग करता है। कारण (R): सामाजिक परिघटनाओं को हमेशा नियंत्रित प्रयोगशाला प्रयोगों से परखा जा सकता है, जैसे भौतिकी में।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A असत्य है, लेकिन R सत्य है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है"],"explanationHi":"सामाजिक विज्ञान प्रमाण, तुलना और व्याख्या के माध्यम से अपने ढंग से कठोर हैं, लेकिन अधिकांश सामाजिक परिघटनाओं को नियंत्रित प्रयोगों से नहीं गुज़ारा जा सकता। इसलिए A सत्य है और R असत्य है।"},
  {"id":"cdp-pedagogy-subjects-295","question":"Which of the following is NOT an aim of teaching social science according to the spirit of NCF 2005?","options":["Developing a critical understanding of society","Nurturing constitutional values such as justice, liberty and equality","Building the ability to question and investigate","Getting all students to hold the same opinion on political issues"],"answer":3,"explanation":"The framework values independent thinking and respect for multiple perspectives. Producing uniform opinions is indoctrination, which is the opposite of the critical, democratic aims it sets out.","difficulty":"moderate","source":"CTET Paper 2 · NVS · KVS","questionHi":"NCF 2005 की भावना के अनुसार निम्नलिखित में से कौन-सा सामाजिक विज्ञान पढ़ाने का उद्देश्य नहीं है?","optionsHi":["समाज की आलोचनात्मक समझ विकसित करना","न्याय, स्वतंत्रता और समानता जैसे संवैधानिक मूल्यों का पोषण करना","प्रश्न करने और अन्वेषण करने की क्षमता निर्मित करना","सभी विद्यार्थियों को राजनीतिक मुद्दों पर एक ही राय रखवाना"],"explanationHi":"रूपरेखा स्वतंत्र चिंतन और बहुल दृष्टिकोणों के सम्मान को महत्त्व देती है। एकसमान राय पैदा करना विचारधारा थोपना है, जो उसके द्वारा निर्धारित आलोचनात्मक, लोकतांत्रिक उद्देश्यों के विपरीत है।"},
  {"id":"cdp-pedagogy-subjects-296","question":"In a Class VI lesson on 'family', the textbook shows a father, mother and two children. Sonu, whose family migrates every season to work at brick kilns, says, 'My family is not like this.' What should the teacher do?","options":["Use Sonu's experience to discuss the many forms families take and why some families move for work","Tell Sonu kindly that the textbook shows the correct and normal family that most children have","Ask Sonu to speak to the teacher after class so that the lesson for the others is not disturbed","Explain that migrant families are a topic for higher classes and will be taught in a later chapter"],"answer":0,"explanation":"NCF 2005 wants children's lives, especially those of marginalised children, to be treated as valid sources of knowledge. Sonu's experience widens the class's understanding and shows that a textbook image is one example, not a norm.","difficulty":"hard","source":"CTET Paper 2 · state TETs · KVS PRT","questionHi":"कक्षा VI के ‘परिवार’ पर पाठ में पाठ्यपुस्तक एक पिता, माता और दो बच्चे दिखाती है। सोनू, जिसका परिवार ईंट-भट्ठों पर काम के लिए हर मौसम में प्रवास करता है, कहता है, ‘मेरा परिवार ऐसा नहीं है।’ शिक्षक को क्या करना चाहिए?","optionsHi":["सोनू के अनुभव का उपयोग करके चर्चा करना कि परिवार कितने रूप ले सकते हैं और कुछ परिवार काम के लिए क्यों चलते रहते हैं","सोनू को स्नेह से बताना कि पाठ्यपुस्तक सही और सामान्य परिवार दिखाती है जो अधिकांश बच्चों का होता है","सोनू से कक्षा के बाद शिक्षक से बात करने को कहना ताकि दूसरों का पाठ बाधित न हो","समझाना कि प्रवासी परिवार ऊँची कक्षाओं का विषय हैं और बाद के अध्याय में पढ़ाए जाएँगे"],"explanationHi":"NCF 2005 चाहता है कि बच्चों के जीवन को, विशेषकर हाशिये के बच्चों के जीवन को, ज्ञान के वैध स्रोत माना जाए। सोनू का अनुभव कक्षा की समझ को व्यापक बनाता है और दिखाता है कि पाठ्यपुस्तक का चित्र एक उदाहरण है, मानदंड नहीं।"},
  {"id":"cdp-pedagogy-subjects-297","question":"A Class X student asks, 'Why did the Non-Cooperation Movement mean different things to different groups?' The teacher replies by dictating four points to memorise. Which criticism of this response is the most accurate?","options":["It is correct, since dictated notes ensure that all students write the same answer in the board examination","It shuts down inquiry; groups could compare accounts of peasants, tribal people and urban traders to build the answer","It is wrong only because the dictated points may not match the exact wording given in the textbook chapter","It is wrong because Class X students should not be raising questions that go beyond what the prescribed chapter actually covers"],"answer":1,"explanation":"The student's question is an opening for inquiry into multiple perspectives. Comparing how different social groups understood the movement builds historical reasoning, whereas dictation turns an inquiry question into recall.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा X का एक विद्यार्थी पूछता है, ‘असहयोग आंदोलन का अलग-अलग समूहों के लिए अलग-अलग अर्थ क्यों था?’ शिक्षक चार बिंदु याद करने के लिए लिखवाकर उत्तर देता है। इस प्रतिक्रिया की कौन-सी आलोचना सबसे सटीक है?","optionsHi":["यह सही है, क्योंकि लिखवाए गए नोट्स सुनिश्चित करते हैं कि बोर्ड परीक्षा में सभी विद्यार्थी एक ही उत्तर लिखें","यह अन्वेषण को बंद कर देती है; समूह किसानों, आदिवासियों और शहरी व्यापारियों के वृत्तांतों की तुलना करके उत्तर बना सकते थे","यह केवल इसलिए गलत है कि लिखवाए गए बिंदु पाठ्यपुस्तक के अध्याय में दिए गए सटीक शब्दों से मेल न खाएँ","यह गलत है क्योंकि कक्षा X के विद्यार्थियों को ऐसे प्रश्न नहीं उठाने चाहिए जो निर्धारित अध्याय के वास्तविक दायरे से आगे जाते हों"],"explanationHi":"विद्यार्थी का प्रश्न बहुल दृष्टिकोणों की जाँच का द्वार है। अलग-अलग सामाजिक समूहों ने आंदोलन को कैसे समझा, इसकी तुलना ऐतिहासिक तर्क निर्मित करती है, जबकि लिखवाना अन्वेषण-प्रश्न को स्मरण में बदल देता है।"},
  {"id":"cdp-pedagogy-subjects-298","question":"A teacher of Class VII in Kerala introduces climate by first asking how the monsoon affects paddy sowing and fishing in pupils' own village, and only then moves to world climate regions. Which maxim of teaching is she mainly following?","options":["From abstract to concrete and from the theory to the example","From the whole to its parts and the world to the village","From the known to the unknown and the local to the global","From analysis to synthesis and from rules to examples"],"answer":2,"explanation":"She starts from what children know in their own surroundings and moves outward to the wider world, the 'known to unknown' and 'local to global' progression NCF 2005 recommends for geography.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"केरल में कक्षा VII की एक शिक्षिका जलवायु का परिचय यह पूछकर कराती है कि मानसून विद्यार्थियों के अपने गाँव में धान की बुवाई और मछली पकड़ने को कैसे प्रभावित करता है, और उसके बाद ही विश्व के जलवायु क्षेत्रों पर जाती है। वह मुख्य रूप से शिक्षण के किस सूत्र का पालन कर रही है?","optionsHi":["अमूर्त से मूर्त की ओर और सिद्धांत से उदाहरण की ओर","संपूर्ण से अंशों की ओर और विश्व से गाँव की ओर","ज्ञात से अज्ञात की ओर और स्थानीय से वैश्विक की ओर","विश्लेषण से संश्लेषण की ओर और नियमों से उदाहरणों की ओर"],"explanationHi":"वह उससे शुरू करती है जो बच्चे अपने परिवेश में जानते हैं और बाहर की ओर व्यापक दुनिया तक बढ़ती है, यानी ‘ज्ञात से अज्ञात’ और ‘स्थानीय से वैश्विक’ क्रम, जिसकी NCF 2005 भूगोल के लिए अनुशंसा करता है।"},
  {"id":"cdp-pedagogy-subjects-299","question":"A school adds a separate chapter titled 'Women in Indian History' to its Class VIII syllabus and leaves every other chapter unchanged. Which critique is most in line with NCF 2005?","options":["The change is enough, since one dedicated chapter fully covers the gender requirement of the curriculum","Gender belongs in home science and should be removed from social science, where it only distracts from the main political story","Gender should be a lens across all themes, asking how women experienced work, law and change, not a one-chapter add-on","The topic should be avoided altogether because it may cause controversy among parents and the local community"],"answer":2,"explanation":"NCF 2005 asks for a gender perspective integrated across social science, not a single 'women' chapter beside an otherwise male-centred narrative. An add-on chapter keeps women at the margins of the main story.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"एक विद्यालय अपने कक्षा VIII के पाठ्यक्रम में ‘भारतीय इतिहास में महिलाएँ’ शीर्षक का एक अलग अध्याय जोड़ता है और बाकी हर अध्याय को अपरिवर्तित छोड़ देता है। NCF 2005 के सबसे अनुरूप आलोचना कौन-सी है?","optionsHi":["परिवर्तन पर्याप्त है, क्योंकि एक समर्पित अध्याय पाठ्यचर्या की लैंगिक आवश्यकता को पूरी तरह कवर कर देता है","लिंग का संबंध गृह विज्ञान से है और उसे सामाजिक विज्ञान से हटा देना चाहिए, जहाँ वह मुख्य राजनीतिक कथा से ध्यान भटकाता है","लिंग को सभी थीम में एक दृष्टि होना चाहिए, जो पूछे कि महिलाओं ने काम, कानून और परिवर्तन को कैसे अनुभव किया, न कि एक अध्याय का परिशिष्ट","इस विषय से पूरी तरह बचना चाहिए क्योंकि इससे अभिभावकों और स्थानीय समुदाय में विवाद हो सकता है"],"explanationHi":"NCF 2005 सामाजिक विज्ञान में सभी विषयों में एकीकृत लैंगिक परिप्रेक्ष्य माँगता है, एक अन्यथा पुरुष-केंद्रित कथा के बगल में एक ‘महिला’ अध्याय नहीं। जोड़ा गया अध्याय महिलाओं को मुख्य कहानी के हाशिये पर रखता है।"},
  {"id":"cdp-pedagogy-subjects-300","question":"Which of the following statements about the nature of social science are correct?\n1. It deals with human beings in society, so values and perspectives enter into it.\n2. Its concepts, such as democracy or market, are best learnt as fixed definitions.\n3. It helps students understand how society came to be what it is and how it can change.","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Social science studies people in society, involves values and perspectives, and explains how society is shaped and can change. Treating its concepts as fixed definitions to memorise is the rote approach NCF 2005 criticises.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"सामाजिक विज्ञान की प्रकृति के बारे में निम्नलिखित में से कौन-से कथन सही हैं? 1. यह समाज में मनुष्यों से संबंधित है, इसलिए मूल्य और दृष्टिकोण इसमें प्रवेश करते हैं। 2. इसके संप्रत्यय, जैसे लोकतंत्र या बाज़ार, निश्चित परिभाषाओं के रूप में सबसे अच्छी तरह सीखे जाते हैं। 3. यह विद्यार्थियों को समझने में मदद करता है कि समाज जैसा है वैसा कैसे बना और कैसे बदल सकता है।","optionsHi":["केवल 1 और 3","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"सामाजिक विज्ञान समाज में लोगों का अध्ययन करता है, उसमें मूल्य और दृष्टिकोण शामिल होते हैं, और वह बताता है कि समाज कैसे गढ़ा जाता है और कैसे बदल सकता है। इसके संप्रत्ययों को याद करने के लिए निश्चित परिभाषाएँ मानना वह रटंत उपागम है जिसकी NCF 2005 आलोचना करता है।"},
  {"id":"cdp-pedagogy-subjects-301","question":"Consider the following statements about reading aloud to young children: 1. Choosing books with repetitive, predictable patterns helps children join in and anticipate words. 2. Showing the pictures and inviting children's talk interrupts the story and should be avoided. 3. Re-reading a favourite book several times can deepen understanding and vocabulary. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Predictable texts and repeated reading both support early readers. Talk about pictures is a core part of interactive read-aloud, so statement 2 is false.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"छोटे बच्चों को ज़ोर से पढ़कर सुनाने के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. दोहराव वाले, पूर्वानुमेय पैटर्न वाली पुस्तकें चुनने से बच्चे साथ जुड़ पाते हैं और शब्दों का पूर्वानुमान लगा पाते हैं। 2. चित्र दिखाना और बच्चों की बातचीत को आमंत्रित करना कहानी में बाधा डालता है और इससे बचना चाहिए। 3. किसी पसंदीदा पुस्तक को कई बार दोबारा पढ़ने से समझ और शब्दावली गहरी हो सकती है। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"पूर्वानुमेय पाठ और बार-बार पढ़ना दोनों शुरुआती पाठकों की सहायता करते हैं। चित्रों पर बातचीत अंतःक्रियात्मक ज़ोर से पढ़कर सुनाने का मूल भाग है, इसलिए कथन 2 गलत है।"},
  {"id":"cdp-pedagogy-subjects-302","question":"To make a Class 7 chapter 'easier', a textbook writer replaces 'Green plants make their food from carbon dioxide and water in the presence of sunlight' with 'Plants eat sunlight'. Judged against the NCF 2005 criteria for a science curriculum, this change most directly violates:","options":["Cognitive validity, because the new sentence is pitched below the learner's level","Content validity, because the simplification has made the science wrong","Process validity, because no experiment accompanies the statement","Environmental validity, because the plant is not shown in its local setting"],"answer":1,"explanation":"Content validity requires that simplification for the learner's level must not make the information incorrect; 'plants eat sunlight' is simply wrong. The writer's motive (cognitive reach) does not rescue a factually false statement.","difficulty":"very-hard","source":"CTET Paper 2 · KVS PRT/TGT · DSSSB","questionHi":"कक्षा 7 के अध्याय को ‘आसान’ बनाने के लिए एक पाठ्यपुस्तक-लेखक ‘हरे पौधे सूर्य के प्रकाश की उपस्थिति में कार्बन डाइऑक्साइड और पानी से अपना भोजन बनाते हैं’ को ‘पौधे सूर्य का प्रकाश खाते हैं’ से बदल देता है। विज्ञान पाठ्यक्रम के NCF 2005 मानदंडों की कसौटी पर, यह परिवर्तन सबसे सीधे किसका उल्लंघन करता है?","optionsHi":["संज्ञानात्मक वैधता, क्योंकि नया वाक्य अधिगमकर्ता के स्तर से नीचे का है","विषय-वस्तु वैधता, क्योंकि सरलीकरण ने विज्ञान को गलत बना दिया है","प्रक्रिया वैधता, क्योंकि कथन के साथ कोई प्रयोग नहीं है","पर्यावरणीय वैधता, क्योंकि पौधे को उसके स्थानीय परिवेश में नहीं दिखाया गया है"],"explanationHi":"विषय-वस्तु वैधता की माँग है कि अधिगमकर्ता के स्तर के लिए सरलीकरण से जानकारी गलत नहीं होनी चाहिए; ‘पौधे सूर्य का प्रकाश खाते हैं’ बस गलत है। लेखक का उद्देश्य (संज्ञानात्मक पहुँच) तथ्यतः गलत कथन को नहीं बचाता।"},
  {"id":"cdp-pedagogy-subjects-303","question":"Match the NCF 2005 validity criterion with the curriculum feature that best illustrates it. P. Cognitive validity  Q. Process validity  R. Historical validity  S. Ethical validity. 1. Students plan their own test of whether sugar dissolves faster in warm water  2. Students discuss why Mendel's findings were ignored for decades  3. Students record data honestly even when it contradicts the textbook value  4. The idea of the atom's inner structure is kept for a later stage when learners can handle abstraction","options":["P-1, Q-4, R-2, S-3","P-4, Q-3, R-2, S-1","P-4, Q-1, R-2, S-3","P-2, Q-1, R-4, S-3"],"answer":2,"explanation":"Age-appropriate sequencing is cognitive validity (P-4); designing a test is learning the methods of science, process validity (Q-1); how an idea was received over time is historical validity (R-2); honesty in data is ethical validity (S-3).","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · KVS","questionHi":"NCF 2005 की वैधता कसौटी का उस पाठ्यचर्या-विशेषता से मिलान कीजिए जो उसे सबसे अच्छी तरह दर्शाती है। P. संज्ञानात्मक वैधता Q. प्रक्रिया वैधता R. ऐतिहासिक वैधता S. नैतिक वैधता। 1. विद्यार्थी अपना परीक्षण स्वयं योजनाबद्ध करते हैं कि चीनी गर्म पानी में तेज़ी से घुलती है या नहीं 2. विद्यार्थी चर्चा करते हैं कि मेंडल की खोजों को दशकों तक क्यों अनदेखा किया गया 3. विद्यार्थी आँकड़े ईमानदारी से दर्ज करते हैं, भले ही वे पाठ्यपुस्तक के मान के विपरीत हों 4. परमाणु की आंतरिक संरचना का विचार बाद के चरण के लिए रखा जाता है जब अधिगमकर्ता अमूर्तन सँभाल सकें","optionsHi":["P-1, Q-4, R-2, S-3","P-4, Q-3, R-2, S-1","P-4, Q-1, R-2, S-3","P-2, Q-1, R-4, S-3"],"explanationHi":"आयु-उपयुक्त क्रमण संज्ञानात्मक वैधता है (P-4); परीक्षण की रूपरेखा बनाना विज्ञान की विधियाँ सीखना है, प्रक्रिया वैधता (Q-1); किसी विचार का समय के साथ स्वागत कैसे हुआ, यह ऐतिहासिक वैधता है (R-2); आँकड़ों में ईमानदारी नैतिक वैधता है (S-3)।"},
  {"id":"cdp-pedagogy-subjects-304","question":"Assertion (A): Introducing the quantum-mechanical model of the atom in Class 6 would weaken the science curriculum even though the model is scientifically correct. Reason (R): NCF 2005 requires that the content, process, language and pedagogy of science be within the cognitive reach of the learner.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Correct content alone is not enough; cognitive validity demands that it suit the learner's age and level of abstraction, which is exactly why the model would weaken a Class 6 curriculum.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT · state TETs","questionHi":"अभिकथन (A): कक्षा 6 में परमाणु का क्वांटम-यांत्रिकी मॉडल पेश करना विज्ञान पाठ्यक्रम को कमज़ोर करेगा, भले ही मॉडल वैज्ञानिक रूप से सही हो। कारण (R): NCF 2005 माँग करता है कि विज्ञान की विषय-वस्तु, प्रक्रिया, भाषा और शिक्षाशास्त्र अधिगमकर्ता की संज्ञानात्मक पहुँच के भीतर हों।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"केवल सही विषय-वस्तु पर्याप्त नहीं है; संज्ञानात्मक वैधता माँगती है कि वह अधिगमकर्ता की आयु और अमूर्तन-स्तर के अनुरूप हो, और ठीक इसीलिए मॉडल कक्षा 6 के पाठ्यक्रम को कमज़ोर करेगा।"},
  {"id":"cdp-pedagogy-subjects-305","question":"While teaching malaria in Class 8, a teacher narrates how the disease was once blamed on 'bad air' and how Ronald Ross, working in India, showed that mosquitoes carry the malaria parasite. Which NCF 2005 criterion does this narrative serve most directly?","options":["Environmental validity, because malaria is a local health problem in many parts of India","Historical validity, because it shows how a scientific idea changed over time","Ethical validity, because the story promotes concern for human life and public health","Content validity, because the present cause of malaria is stated correctly at the end"],"answer":1,"explanation":"Telling how an earlier explanation was replaced by a better-evidenced one shows the learner how scientific concepts evolve, which is historical validity. The health link alone would not need the story of the change.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS TGT","questionHi":"कक्षा 8 में मलेरिया पढ़ाते समय एक शिक्षक बताता है कि इस रोग को कभी ‘ख़राब हवा’ का परिणाम माना जाता था और भारत में काम करते हुए रोनाल्ड रॉस ने कैसे दिखाया कि मच्छर मलेरिया परजीवी के वाहक हैं। यह वृत्तांत NCF 2005 की किस कसौटी की सबसे सीधी पूर्ति करता है?","optionsHi":["पर्यावरणीय वैधता, क्योंकि मलेरिया भारत के कई भागों में स्थानीय स्वास्थ्य समस्या है","ऐतिहासिक वैधता, क्योंकि यह दिखाता है कि कोई वैज्ञानिक विचार समय के साथ कैसे बदला","नैतिक वैधता, क्योंकि कहानी मानव जीवन और जन स्वास्थ्य के प्रति सरोकार को बढ़ावा देती है","विषय-वस्तु वैधता, क्योंकि अंत में मलेरिया का वर्तमान कारण सही बताया गया है"],"explanationHi":"यह बताना कि पहले की व्याख्या को बेहतर प्रमाणित व्याख्या ने कैसे बदला, अधिगमकर्ता को दिखाता है कि वैज्ञानिक संप्रत्यय कैसे विकसित होते हैं, जो ऐतिहासिक वैधता है। केवल स्वास्थ्य संबंध के लिए परिवर्तन की कहानी की आवश्यकता नहीं होती।"},
  {"id":"cdp-pedagogy-subjects-306","question":"In a germination experiment, Ravi's seeds fail to sprout, and he is tempted to copy his friend's 'all seeds sprouted' result. The teacher holds a discussion on why an honestly reported failure is valuable in science. Which NCF 2005 criterion is the teacher mainly addressing?","options":["Process validity, since the episode arose during an experiment","Cognitive validity, since Ravi must understand germination at his level","Ethical validity, since it promotes honesty and objectivity","Content validity, since the correct germination result must be known"],"answer":2,"explanation":"Ethical validity asks the curriculum to promote values such as honesty, objectivity and freedom from fear and prejudice. The episode happened during an experiment, but the lesson drawn is about integrity, not method.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB · state TETs","questionHi":"अंकुरण के एक प्रयोग में रवि के बीज नहीं उगते, और वह अपने मित्र के ‘सभी बीज उगे’ परिणाम को उतारने के लिए प्रलोभित होता है। शिक्षक इस पर चर्चा करवाता है कि ईमानदारी से बताई गई विफलता विज्ञान में मूल्यवान क्यों है। शिक्षक मुख्य रूप से NCF 2005 की किस कसौटी को संबोधित कर रहा है?","optionsHi":["प्रक्रिया वैधता, क्योंकि प्रसंग एक प्रयोग के दौरान उठा","संज्ञानात्मक वैधता, क्योंकि रवि को अंकुरण को अपने स्तर पर समझना है","नैतिक वैधता, क्योंकि यह ईमानदारी और वस्तुनिष्ठता को बढ़ावा देती है","विषय-वस्तु वैधता, क्योंकि अंकुरण का सही परिणाम ज्ञात होना चाहिए"],"explanationHi":"नैतिक वैधता माँगती है कि पाठ्यचर्या ईमानदारी, वस्तुनिष्ठता और भय तथा पूर्वाग्रह से मुक्ति जैसे मूल्यों को बढ़ावा दे। प्रसंग प्रयोग के दौरान हुआ, लेकिन निकाला गया सबक विधि का नहीं, निष्ठा का है।"},
  {"id":"cdp-pedagogy-subjects-307","question":"Consider these statements about the nature of science. 1. Scientific knowledge is tentative and may change in the light of new evidence. 2. A well-tested theory eventually gets promoted to a law. 3. What a scientist observes is partly shaped by what she already knows and expects. 4. All scientists follow one fixed, step-by-step 'scientific method'. Which are correct?","options":["1, 2 and 3 only","1 and 4 only","2, 3 and 4 only","1 and 3 only"],"answer":3,"explanation":"Science is tentative and observation is theory-laden. Theories and laws are different kinds of knowledge (a theory explains, a law describes a pattern), so one does not grow into the other, and there is no single universal method.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"विज्ञान की प्रकृति के बारे में इन कथनों पर विचार कीजिए। 1. वैज्ञानिक ज्ञान अस्थायी है और नए प्रमाणों के प्रकाश में बदल सकता है। 2. भली-भाँति परखा गया सिद्धांत अंततः नियम में पदोन्नत हो जाता है। 3. वैज्ञानिक जो अवलोकन करता है, वह आंशिक रूप से इससे आकार लेता है कि वह पहले से क्या जानती है और क्या अपेक्षा रखती है। 4. सभी वैज्ञानिक एक निश्चित, चरण-दर-चरण ‘वैज्ञानिक विधि’ का पालन करते हैं। कौन-से सही हैं?","optionsHi":["केवल 1, 2 और 3","केवल 1 और 4","केवल 2, 3 और 4","केवल 1 और 3"],"explanationHi":"विज्ञान अस्थायी है और अवलोकन सिद्धांत-प्रभावित होता है। सिद्धांत और नियम ज्ञान के भिन्न प्रकार हैं (सिद्धांत व्याख्या करता है, नियम किसी पैटर्न का वर्णन करता है), इसलिए एक दूसरे में नहीं बदलता, और कोई एक सार्वभौमिक विधि नहीं है।"},
  {"id":"cdp-pedagogy-subjects-308","question":"After a lesson on the solar system, a Class 6 student says, 'Pluto used to be a planet and now it is not, so science keeps getting things wrong and cannot be trusted.' The response that best builds an understanding of the nature of science is:","options":["Explaining that new discoveries and an agreed definition led to the change, and that such self-correction is a strength of science","Telling the student that earlier scientists were careless and that today's scientists are correct for ever, so the new list is final","Saying that scientific facts never change once they are proved, and that Pluto was just a rare exception to this rule","Asking the student to note the new list of planets and move on, since only the current list is in the syllabus"],"answer":0,"explanation":"Science revises its claims when new evidence appears; the Pluto reclassification shows this self-correcting character. Calling earlier work careless or science unchanging both distort its nature.","difficulty":"hard","source":"CTET Paper 2 · NVS · state TETs","questionHi":"सौरमंडल पर पाठ के बाद कक्षा 6 का एक विद्यार्थी कहता है, ‘प्लूटो पहले ग्रह था और अब नहीं है, इसलिए विज्ञान बार-बार गलत हो जाता है और उस पर भरोसा नहीं किया जा सकता।’ वह प्रतिक्रिया जो विज्ञान की प्रकृति की समझ को सबसे अच्छी तरह निर्मित करती है:","optionsHi":["यह समझाना कि नई खोजों और एक सर्वसम्मत परिभाषा के कारण बदलाव हुआ, और ऐसा आत्म-सुधार विज्ञान की शक्ति है","विद्यार्थी को बताना कि पहले के वैज्ञानिक लापरवाह थे और आज के वैज्ञानिक सदा के लिए सही हैं, इसलिए नई सूची अंतिम है","यह कहना कि वैज्ञानिक तथ्य एक बार सिद्ध होने पर कभी नहीं बदलते, और प्लूटो इस नियम का बस एक दुर्लभ अपवाद था","विद्यार्थी से ग्रहों की नई सूची नोट करने और आगे बढ़ने को कहना, क्योंकि पाठ्यक्रम में केवल वर्तमान सूची है"],"explanationHi":"विज्ञान नए प्रमाण आने पर अपने दावों को संशोधित करता है; प्लूटो का पुनर्वर्गीकरण इसका आत्म-सुधारक स्वरूप दिखाता है। पहले के कार्य को लापरवाह या विज्ञान को अपरिवर्तनीय कहना, दोनों उसकी प्रकृति को विकृत करते हैं।"},
  {"id":"cdp-pedagogy-subjects-309","question":"Rina observes a lit candle placed under an inverted glass tumbler and writes four statements. Which one is an inference rather than an observation?","options":["The flame went out about twenty seconds after the glass was placed over it.","Tiny water droplets appeared on the inside of the glass near the top.","The flame went out because the air needed for burning ran short inside.","The candle had become slightly shorter by the end than it was at the start."],"answer":2,"explanation":"An inference is an explanation drawn from observations; the 'because' statement interprets why the flame died. The others report what was directly seen or measured.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"रीना एक उलटे काँच के गिलास के नीचे रखी जलती मोमबत्ती का अवलोकन करती है और चार कथन लिखती है। इनमें से कौन-सा अवलोकन के बजाय अनुमान है?","optionsHi":["गिलास को लौ पर रखने के लगभग बीस सेकंड बाद लौ बुझ गई।","गिलास के भीतर ऊपर की ओर पानी की छोटी बूँदें दिखाई दीं।","लौ इसलिए बुझ गई क्योंकि जलने के लिए आवश्यक हवा भीतर कम पड़ गई।","अंत तक मोमबत्ती शुरुआत की तुलना में थोड़ी छोटी हो गई थी।"],"explanationHi":"अनुमान अवलोकनों से निकाली गई व्याख्या है; ‘इसलिए’ वाला कथन व्याख्या करता है कि लौ क्यों बुझी। अन्य कथन वह बताते हैं जो सीधे देखा या मापा गया।"},
  {"id":"cdp-pedagogy-subjects-310","question":"Class 7 students want to test whether the amount of water given daily affects the growth of moong seedlings. Which plan controls the variables correctly?","options":["Three pots get 20, 40 and 60 mL daily; the 60 mL pot is kept in the sunniest corner since it needs the most energy","Three pots with the same soil, the same number of seeds and the same sunlight get 20, 40 and 60 mL of water daily","Three pots get different amounts of water, and each pot has a different kind of seed to make the test more interesting","One pot gets 20 mL daily and the other two get no water at all, so the difference is clearest"],"answer":1,"explanation":"A fair test changes only the independent variable (amount of water) and keeps soil, seeds and light the same. Changing sunlight or seed type with water confounds the result.","difficulty":"moderate","source":"CTET Paper 2 · KVS · state TETs","questionHi":"कक्षा 7 के विद्यार्थी परखना चाहते हैं कि प्रतिदिन दिए गए पानी की मात्रा मूँग के पौधों की वृद्धि को प्रभावित करती है या नहीं। कौन-सी योजना चरों को सही ढंग से नियंत्रित करती है?","optionsHi":["तीन गमलों को प्रतिदिन 20, 40 और 60 mL मिलता है; 60 mL वाला गमला सबसे धूप वाले कोने में रखा जाता है क्योंकि उसे सबसे अधिक ऊर्जा चाहिए","एक जैसी मिट्टी, बीजों की एक जैसी संख्या और एक जैसी धूप वाले तीन गमलों को प्रतिदिन 20, 40 और 60 mL पानी मिलता है","तीन गमलों को अलग-अलग मात्रा में पानी मिलता है, और परीक्षण को अधिक रोचक बनाने के लिए हर गमले में अलग प्रकार का बीज है","एक गमले को प्रतिदिन 20 mL मिलता है और अन्य दो को बिल्कुल पानी नहीं मिलता, ताकि अंतर सबसे स्पष्ट हो"],"explanationHi":"निष्पक्ष परीक्षण केवल स्वतंत्र चर (पानी की मात्रा) को बदलता है और मिट्टी, बीज तथा प्रकाश को समान रखता है। पानी के साथ धूप या बीज का प्रकार बदलने से परिणाम उलझ जाता है।"},
  {"id":"cdp-pedagogy-subjects-311","question":"Which classroom task demands an integrated science process skill rather than only a basic one?","options":["Sorting fallen leaves of the school garden into groups by the shape of their margins","Measuring the length of a bean shoot every morning with a ruler and recording it","Describing the colour change when turmeric paper touches soap solution in a dish","Proposing that warmer soil makes seeds sprout sooner and planning how to check it"],"answer":3,"explanation":"Formulating a hypothesis and designing a test are integrated process skills that combine several basic ones. Classifying, measuring and observing are basic process skills.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs","questionHi":"कौन-सा कक्षा-कार्य केवल आधारभूत प्रक्रिया कौशल के बजाय एकीकृत विज्ञान प्रक्रिया कौशल की माँग करता है?","optionsHi":["विद्यालय की बगिया की गिरी हुई पत्तियों को उनके किनारों के आकार के आधार पर समूहों में छाँटना","मूँग के अंकुर की लंबाई हर सुबह पैमाने से मापना और दर्ज करना","हल्दी के कागज़ के साबुन के घोल से छूने पर प्लेट में होने वाले रंग-परिवर्तन का वर्णन करना","यह प्रस्ताव करना कि गर्म मिट्टी में बीज जल्दी अंकुरित होते हैं और इसे जाँचने की योजना बनाना"],"explanationHi":"परिकल्पना बनाना और परीक्षण की रूपरेखा बनाना एकीकृत प्रक्रिया कौशल हैं जो कई आधारभूत कौशलों को जोड़ते हैं। वर्गीकरण, मापन और अवलोकन आधारभूत प्रक्रिया कौशल हैं।"},
  {"id":"cdp-pedagogy-subjects-312","question":"Before a plant-growth project, a Class 8 group agrees: 'A plant will count as healthier if, after two weeks, it is taller in cm and has more leaves.' Which process skill have they used?","options":["Predicting the outcome","Defining operationally","Inferring from data","Communicating results"],"answer":1,"explanation":"An operational definition states how a vague idea ('healthier') will be measured in the investigation. It is not a prediction about what will happen.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"पौधे की वृद्धि की परियोजना से पहले कक्षा 8 का एक समूह सहमत होता है: ‘यदि दो सप्ताह बाद कोई पौधा cm में अधिक लंबा है और उसमें अधिक पत्तियाँ हैं, तो वह अधिक स्वस्थ माना जाएगा।’ उन्होंने किस प्रक्रिया कौशल का उपयोग किया है?","optionsHi":["परिणाम का पूर्वानुमान लगाना","संक्रियात्मक परिभाषा देना","आँकड़ों से अनुमान निकालना","परिणामों का संप्रेषण करना"],"explanationHi":"संक्रियात्मक परिभाषा बताती है कि अन्वेषण में किसी अस्पष्ट विचार (‘स्वस्थ’) को कैसे मापा जाएगा। यह इस बारे में पूर्वानुमान नहीं है कि क्या होगा।"},
  {"id":"cdp-pedagogy-subjects-313","question":"In a 5E lesson on air pressure, students have played with syringes and suction cups and recorded what they noticed. The teacher has then introduced the term 'atmospheric pressure' and helped them explain their observations. What should the next phase involve?","options":["A surprising demonstration, such as a crushed can, to raise fresh curiosity about air","A unit test on atmospheric pressure, since the concept has now been explained","More free play with syringes and suction cups so that every child gets a turn","Applying the idea to new situations, such as how a drinking straw or dropper works"],"answer":3,"explanation":"After Engage, Explore and Explain comes Elaborate, where learners extend the concept to new contexts. Evaluation follows, and a demonstration to raise curiosity belongs to the Engage phase.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"वायु दाब पर 5E पाठ में विद्यार्थियों ने सिरिंजों और सक्शन कपों से खेला है और जो देखा उसे दर्ज किया है। फिर शिक्षक ने ‘वायुमंडलीय दाब’ शब्द प्रस्तुत किया है और उन्हें अपने अवलोकनों की व्याख्या करने में मदद की है। अगले चरण में क्या शामिल होना चाहिए?","optionsHi":["हवा के बारे में नई जिज्ञासा जगाने के लिए पिचका हुआ कैन जैसा आश्चर्यजनक प्रदर्शन","वायुमंडलीय दाब पर इकाई-परीक्षा, क्योंकि संप्रत्यय अब समझाया जा चुका है","सिरिंजों और सक्शन कपों के साथ और स्वतंत्र खेल ताकि हर बच्चे को अवसर मिले","विचार को नई स्थितियों में लागू करना, जैसे पीने की स्ट्रॉ या ड्रॉपर कैसे काम करता है"],"explanationHi":"Engage, Explore और Explain के बाद Elaborate आता है, जहाँ अधिगमकर्ता संप्रत्यय को नए संदर्भों में विस्तार देते हैं। मूल्यांकन उसके बाद आता है, और जिज्ञासा जगाने वाला प्रदर्शन Engage चरण का है।"},
  {"id":"cdp-pedagogy-subjects-314","question":"A teacher begins the chapter on acids and bases by writing the definitions of acid, base and indicator on the board, and then gives students turmeric and litmus to test household substances. A teacher using the 5E model would most likely suggest:","options":["Letting students test substances first and introducing the terms after they try to explain their results","Dropping the activity altogether, because the definitions already cover what students need to know","Giving the definitions twice, once before and once after the activity, so that they are firmly fixed in memory","Replacing the testing with a teacher demonstration so that no class time is lost to student handling"],"answer":0,"explanation":"In the 5E sequence, formal terms come in the Explain phase, after learners have explored; definitions first turn the activity into mere confirmation.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"एक शिक्षक अम्ल और क्षार के अध्याय की शुरुआत श्यामपट्ट पर अम्ल, क्षार और सूचक की परिभाषाएँ लिखकर करता है, और फिर विद्यार्थियों को घरेलू पदार्थों का परीक्षण करने के लिए हल्दी और लिटमस देता है। 5E मॉडल का उपयोग करने वाला शिक्षक सबसे अधिक संभावना से क्या सुझाएगा?","optionsHi":["विद्यार्थियों को पहले पदार्थों का परीक्षण करने देना और अपने परिणामों की व्याख्या का प्रयास करने के बाद शब्द प्रस्तुत करना","गतिविधि को पूरी तरह छोड़ देना, क्योंकि परिभाषाएँ पहले ही वह सब कवर कर देती हैं जो विद्यार्थियों को जानना है","परिभाषाएँ दो बार देना, एक बार गतिविधि से पहले और एक बार बाद में, ताकि वे स्मृति में पक्की हो जाएँ","परीक्षण को शिक्षक के प्रदर्शन से बदल देना ताकि विद्यार्थियों के छूने-सँभालने में कक्षा का समय न जाए"],"explanationHi":"5E क्रम में औपचारिक शब्द Explain चरण में आते हैं, अधिगमकर्ताओं के खोजबीन करने के बाद; पहले परिभाषाएँ देना गतिविधि को मात्र पुष्टि बना देता है।"},
  {"id":"cdp-pedagogy-subjects-315","question":"A teacher gives Class 8 the question, 'Does the colour of a cloth affect how fast it dries in the sun?' The students themselves decide the materials, the method and how to record results. This is best described as:","options":["Confirmation inquiry","Structured inquiry","Guided inquiry","Open inquiry"],"answer":2,"explanation":"In guided inquiry the teacher supplies the question and students design the procedure. In structured inquiry the teacher also gives the procedure, and in open inquiry students frame the question too.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"एक शिक्षक कक्षा 8 को प्रश्न देता है, ‘क्या कपड़े का रंग इस पर असर डालता है कि वह धूप में कितनी जल्दी सूखता है?’ विद्यार्थी स्वयं सामग्री, विधि और परिणाम दर्ज करने का तरीका तय करते हैं। इसका सबसे अच्छा वर्णन है:","optionsHi":["पुष्टिकारक अन्वेषण","संरचित अन्वेषण","निर्देशित अन्वेषण","मुक्त अन्वेषण"],"explanationHi":"निर्देशित अन्वेषण में शिक्षक प्रश्न देता है और विद्यार्थी प्रक्रिया की रूपरेखा बनाते हैं। संरचित अन्वेषण में शिक्षक प्रक्रिया भी देता है, और मुक्त अन्वेषण में विद्यार्थी प्रश्न भी स्वयं बनाते हैं।"},
  {"id":"cdp-pedagogy-subjects-316","question":"Arjun says a cup of boiling water has 'more heat' than a full bucket of lukewarm water because it is hotter. Which statement should the teacher help him reach?","options":["The cup has the higher temperature, but the bucket holds more thermal energy and could melt more ice","The cup has both the higher temperature and more heat, since heat and temperature are the same thing","The bucket has the higher temperature because it contains more water","Both contain the same heat, because heat depends only on the kind of substance"],"answer":0,"explanation":"Temperature is a measure of hotness; the total thermal energy also depends on the amount of matter. A large mass of lukewarm water can hold far more energy than a small cup of boiling water.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"अर्जुन कहता है कि उबलते पानी के एक कप में गुनगुने पानी की पूरी बाल्टी से ‘अधिक ऊष्मा’ है क्योंकि वह अधिक गर्म है। शिक्षक को उसे किस कथन तक पहुँचने में मदद करनी चाहिए?","optionsHi":["कप का तापमान अधिक है, लेकिन बाल्टी में अधिक ऊष्मीय ऊर्जा है और वह अधिक बर्फ़ पिघला सकती है","कप में तापमान और ऊष्मा दोनों अधिक हैं, क्योंकि ऊष्मा और तापमान एक ही चीज़ हैं","बाल्टी का तापमान अधिक है क्योंकि उसमें अधिक पानी है","दोनों में समान ऊष्मा है, क्योंकि ऊष्मा केवल पदार्थ के प्रकार पर निर्भर करती है"],"explanationHi":"तापमान गर्माहट का माप है; कुल ऊष्मीय ऊर्जा पदार्थ की मात्रा पर भी निर्भर करती है। गुनगुने पानी की बड़ी मात्रा में उबलते पानी के छोटे कप से कहीं अधिक ऊर्जा हो सकती है।"},
  {"id":"cdp-pedagogy-subjects-317","question":"Most of a Class 7 class believes that a woollen sweater keeps us warm because it 'produces heat'. Which strategy is most likely to change this idea?","options":["Writing the correct reason on the board and asking students to learn it by heart for the next unit test","Letting the idea pass, since the belief does no harm in daily life and will surely correct itself in the later classes","Having students predict, then check with a thermometer inside a folded sweater for an hour, and explain the result","Listing more examples of warm clothes such as shawls, blankets and jackets so that the idea becomes clearer"],"answer":2,"explanation":"Predict-Observe-Explain creates a conflict between expectation and evidence: the thermometer reading does not rise, so wool must be insulating rather than producing heat. Telling or ignoring leaves the misconception intact.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs","questionHi":"कक्षा 7 के अधिकांश बच्चे मानते हैं कि ऊनी स्वेटर हमें इसलिए गर्म रखता है क्योंकि वह ‘ऊष्मा पैदा करता है’। कौन-सी रणनीति इस विचार को बदलने की सबसे अधिक संभावना रखती है?","optionsHi":["सही कारण श्यामपट्ट पर लिखना और विद्यार्थियों से अगली इकाई-परीक्षा के लिए उसे कंठस्थ करने को कहना","विचार को जाने देना, क्योंकि यह मान्यता दैनिक जीवन में कोई हानि नहीं करती और बाद की कक्षाओं में निश्चय ही अपने आप सुधर जाएगी","विद्यार्थियों से पूर्वानुमान लगवाना, फिर मुड़े हुए स्वेटर के अंदर एक घंटे तक थर्मामीटर रखकर जाँचना, और परिणाम समझाना","गर्म कपड़ों के और उदाहरण, जैसे शॉल, कंबल और जैकेट, सूचीबद्ध करना ताकि विचार अधिक स्पष्ट हो"],"explanationHi":"पूर्वानुमान–अवलोकन–व्याख्या अपेक्षा और प्रमाण के बीच संघर्ष पैदा करता है: थर्मामीटर की रीडिंग नहीं बढ़ती, इसलिए ऊन ऊष्मा पैदा करने के बजाय रोधन करता होगा। बता देना या अनदेखा करना भ्रांत धारणा को वैसा ही रहने देता है।"},
  {"id":"cdp-pedagogy-subjects-318","question":"Meena insists that while a ball thrown straight up is rising, an upward force from the throw is still acting on it. Which teacher question best creates productive cognitive conflict?","options":["'Can you write out the textbook definition of force and give one example of it?'","'If an upward force were acting, why does the ball keep slowing down until it stops?'","'Will you throw the ball up a few more times, watching closely until you see the force?'","'Can you solve v = u - gt for this ball and find the height it reaches?'"],"answer":1,"explanation":"Meena holds the common 'motion needs a force in its direction' (impetus) idea. Asking her to reconcile it with the steady slowing makes the idea fail on its own terms; definitions and formulae can be repeated without changing the belief.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS","questionHi":"मीना ज़ोर देकर कहती है कि सीधे ऊपर फेंकी गई गेंद जब ऊपर जा रही होती है, तब भी फेंकने से मिला ऊपर की ओर का बल उस पर कार्य कर रहा होता है। शिक्षक का कौन-सा प्रश्न उत्पादक संज्ञानात्मक संघर्ष सबसे अच्छी तरह पैदा करता है?","optionsHi":["‘क्या आप बल की पाठ्यपुस्तकीय परिभाषा लिखकर उसका एक उदाहरण दे सकती हैं?’","‘यदि ऊपर की ओर बल कार्य कर रहा होता, तो गेंद रुकने तक लगातार धीमी क्यों होती जाती है?’","‘क्या आप गेंद को कुछ बार और ऊपर फेंकेंगी और ध्यान से देखेंगी जब तक बल दिखाई न दे?’","‘क्या आप इस गेंद के लिए v = u - gt हल करके उसकी पहुँचने वाली ऊँचाई निकाल सकती हैं?’"],"explanationHi":"मीना ‘गति के लिए उसकी दिशा में बल चाहिए’ (आवेग) का सामान्य विचार रखती है। उससे इसे लगातार धीमे होने से मिलाने को कहना विचार को उसके अपने ही आधार पर विफल कर देता है; परिभाषाएँ और सूत्र बिना मान्यता बदले दोहराए जा सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-319","question":"Most students in a Class 7 class say that plants take their food from the soil. Which historical investigation, retold and discussed, would most directly challenge this idea?","options":["Pasteur's swan-neck flask experiment, which showed that broth spoils only from outside","Mendel's crosses of pea plants, which showed how traits pass from parent to offspring","Van Helmont's willow, which gained much mass while its soil lost very little","Jenner's work on cowpox and smallpox, which led to the first vaccine against disease"],"answer":2,"explanation":"Van Helmont found that a willow grew heavier by many kilograms over five years while its soil lost only about 60 grams, so the plant's mass could not have come from the soil. The other experiments address different questions.","difficulty":"hard","source":"CTET Paper 2 · state TETs · KVS","questionHi":"कक्षा 7 की कक्षा के अधिकांश विद्यार्थी कहते हैं कि पौधे अपना भोजन मिट्टी से लेते हैं। कौन-सा ऐतिहासिक अन्वेषण, दोबारा सुनाया और चर्चित किया जाए, तो इस विचार को सबसे सीधे चुनौती देगा?","optionsHi":["पाश्चर का हंस-गर्दन फ़्लास्क प्रयोग, जिसने दिखाया कि शोरबा केवल बाहर से खराब होता है","मेंडल के मटर के पौधों के संकरण, जिन्होंने दिखाया कि गुण माता-पिता से संतान में कैसे जाते हैं","वैन हेलमॉन्ट का विलो, जिसका द्रव्यमान बहुत बढ़ा जबकि उसकी मिट्टी में बहुत कम कमी आई","जेनर का गोशीतला और चेचक पर कार्य, जिससे रोग का पहला टीका बना"],"explanationHi":"वैन हेलमॉन्ट ने पाया कि पाँच वर्षों में एक विलो कई किलोग्राम भारी हो गया जबकि उसकी मिट्टी में केवल लगभग 60 ग्राम की कमी आई, इसलिए पौधे का द्रव्यमान मिट्टी से नहीं आ सकता था। अन्य प्रयोग अलग प्रश्नों को संबोधित करते हैं।"},
  {"id":"cdp-pedagogy-subjects-320","question":"Students believe that a bulb 'uses up' current, so less current returns to the cell than leaves it. Which activity gives the most direct evidence against this belief?","options":["Adding a second cell so that the bulb glows more brightly","Explaining that energy, not current, is used in the bulb, and asking them to copy it","Showing a video of lightning to show how strong current can be","Placing identical ammeters on both sides of the bulb and comparing the readings"],"answer":3,"explanation":"Equal readings before and after the bulb show that current is the same all round a series circuit; what the bulb converts is energy. Telling the correct idea without evidence rarely shifts a misconception.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT · state TETs","questionHi":"विद्यार्थी मानते हैं कि बल्ब धारा ‘खर्च कर देता है’, इसलिए सेल में जितनी धारा जाती है उससे कम लौटती है। कौन-सी गतिविधि इस मान्यता के विरुद्ध सबसे सीधा प्रमाण देती है?","optionsHi":["दूसरा सेल जोड़ना ताकि बल्ब अधिक चमकीला जले","समझाना कि बल्ब में धारा नहीं, ऊर्जा खर्च होती है, और उन्हें उसे उतारने को कहना","तेज़ धारा कितनी प्रबल हो सकती है यह दिखाने के लिए बिजली गिरने का वीडियो दिखाना","बल्ब के दोनों ओर समान अमीटर लगाना और रीडिंग की तुलना करना"],"explanationHi":"बल्ब से पहले और बाद में समान रीडिंग दिखाती है कि श्रेणी परिपथ में धारा हर जगह समान होती है; बल्ब जिसे रूपांतरित करता है वह ऊर्जा है। प्रमाण के बिना सही विचार बता देना शायद ही भ्रांत धारणा को हिलाता है।"},
  {"id":"cdp-pedagogy-subjects-321","question":"Assertion (A): A science teacher should present the structure of the atom as a series of models that were revised over time. Reason (R): Once scientific knowledge is accepted by the scientific community, it is absolute and final.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Showing successive atomic models conveys the tentative, evolving nature of science, so A is sound. R is false: accepted knowledge is still open to revision when new evidence arrives.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): विज्ञान शिक्षक को परमाणु की संरचना को ऐसे मॉडलों की शृंखला के रूप में प्रस्तुत करना चाहिए जो समय के साथ संशोधित होते रहे। कारण (R): एक बार वैज्ञानिक समुदाय द्वारा स्वीकार कर लिए जाने पर वैज्ञानिक ज्ञान निरपेक्ष और अंतिम होता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"क्रमिक परमाणु मॉडल दिखाना विज्ञान की अस्थायी, विकसित होती प्रकृति को व्यक्त करता है, इसलिए A उचित है। R असत्य है: स्वीकृत ज्ञान भी नए प्रमाण आने पर संशोधन के लिए खुला रहता है।"},
  {"id":"cdp-pedagogy-subjects-322","question":"A Class 8 class studies a proposed dam in their district: students collect data on irrigation and power benefits, forest loss and displacement, and role-play farmers, engineers and displaced families. The main learning outcome intended is the ability to:","options":["Memorise the types of dams and their parts so that they can label diagrams accurately","Take informed, reasoned positions on issues where science, technology and society meet","Conclude that all development projects harm the environment and so should be stopped","Accept that such decisions are purely technical and are best left to trained engineers"],"answer":1,"explanation":"A socio-scientific issue taught this way builds evidence-based decision-making that weighs scientific, social and ethical aspects. Treating such issues as purely technical, or opposing all development, are both one-sided views.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS","questionHi":"कक्षा 8 की एक कक्षा अपने ज़िले में प्रस्तावित बाँध का अध्ययन करती है: विद्यार्थी सिंचाई और बिजली के लाभों, वन-हानि और विस्थापन पर आँकड़े इकट्ठा करते हैं, और किसानों, इंजीनियरों तथा विस्थापित परिवारों की भूमिका निभाते हैं। अभिप्रेत मुख्य अधिगम-परिणाम किस क्षमता का है?","optionsHi":["बाँधों के प्रकार और उनके भाग याद करना ताकि वे आरेखों को सही नामांकित कर सकें","उन मुद्दों पर सुविचारित, तर्कसंगत मत बनाना जहाँ विज्ञान, प्रौद्योगिकी और समाज मिलते हैं","यह निष्कर्ष निकालना कि सभी विकास परियोजनाएँ पर्यावरण को हानि पहुँचाती हैं और इसलिए उन्हें रोक देना चाहिए","यह स्वीकार करना कि ऐसे निर्णय पूरी तरह तकनीकी हैं और प्रशिक्षित इंजीनियरों पर छोड़ना सबसे अच्छा है"],"explanationHi":"इस तरह पढ़ाया गया सामाजिक-वैज्ञानिक मुद्दा प्रमाण-आधारित निर्णय-क्षमता निर्मित करता है जो वैज्ञानिक, सामाजिक और नैतिक पक्षों को तौलती है। ऐसे मुद्दों को पूरी तरह तकनीकी मानना, या सभी विकास का विरोध करना, दोनों एकतरफ़ा दृष्टिकोण हैं।"},
  {"id":"cdp-pedagogy-subjects-323","question":"A solar eclipse is due during school hours, and several families have told their children not to eat or step out during it. The most appropriate step for the science teacher is to:","options":["Ridicule the families' beliefs in class so that students give them up quickly and accept the scientific view instead","Avoid the topic altogether, since discussing it could upset families and create conflict with the school","Allow students to view the eclipse through dark sunglasses so that they can see the event for themselves","Arrange safe pinhole viewing, explain the event and invite students to weigh evidence against beliefs respectfully"],"answer":3,"explanation":"Safe observation plus explanation builds a scientific temper without humiliating families. Sunglasses do not protect the eyes from the sun, and avoiding or mocking the topic both fail as teaching.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"विद्यालय के समय के दौरान सूर्य ग्रहण होने वाला है, और कई परिवारों ने अपने बच्चों से कहा है कि उस दौरान न खाएँ और न बाहर निकलें। विज्ञान शिक्षक के लिए सबसे उपयुक्त कदम है:","optionsHi":["कक्षा में परिवारों की मान्यताओं का उपहास करना ताकि विद्यार्थी उन्हें जल्दी छोड़ दें और वैज्ञानिक दृष्टिकोण अपना लें","विषय से पूरी तरह बचना, क्योंकि इस पर चर्चा परिवारों को परेशान कर सकती है और विद्यालय के साथ टकराव पैदा कर सकती है","विद्यार्थियों को काले धूप के चश्मे से ग्रहण देखने देना ताकि वे घटना को स्वयं देख सकें","सुरक्षित पिनहोल-दर्शन की व्यवस्था करना, घटना को समझाना और विद्यार्थियों को सम्मानपूर्वक प्रमाणों को मान्यताओं के सामने तौलने के लिए आमंत्रित करना"],"explanationHi":"सुरक्षित अवलोकन और व्याख्या परिवारों को अपमानित किए बिना वैज्ञानिक चेतना निर्मित करते हैं। धूप के चश्मे आँखों को सूर्य से नहीं बचाते, और विषय से बचना या उसका मज़ाक उड़ाना, दोनों शिक्षण के रूप में विफल हैं।"},
  {"id":"cdp-pedagogy-subjects-324","question":"A teacher introduces the Mitticool clay refrigerator, a grassroots innovation that keeps vegetables cool without electricity. Which follow-up task best develops students' own capacity to innovate?","options":["Designing a better cooler from local materials and measuring how far it lowers the temperature","Writing an essay on the life of the inventor and the many hardships he faced while building it","Memorising that the cooler works on the principle of evaporation, for use in the test","Drawing and labelling a neat diagram of the cooler, showing each of its parts clearly"],"answer":0,"explanation":"Innovation is developed by designing, testing and improving a product, which uses the evaporative-cooling idea in a new way. Biographies, memorising and diagrams leave students as passive receivers.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"एक शिक्षक मिट्टीकूल मिट्टी के रेफ़्रिजरेटर का परिचय देता है, जो एक जमीनी स्तर का नवाचार है और बिजली के बिना सब्ज़ियों को ठंडा रखता है। कौन-सा अनुवर्ती कार्य विद्यार्थियों की स्वयं नवाचार करने की क्षमता को सबसे अच्छी तरह विकसित करता है?","optionsHi":["स्थानीय सामग्रियों से बेहतर कूलर डिज़ाइन करना और मापना कि वह तापमान को कितना घटाता है","आविष्कारक के जीवन और उसे बनाते समय उसके सामने आई अनेक कठिनाइयों पर निबंध लिखना","परीक्षा में उपयोग के लिए याद करना कि कूलर वाष्पन के सिद्धांत पर काम करता है","कूलर का साफ़ आरेख बनाना और उसके हर भाग को स्पष्ट रूप से नामांकित करना"],"explanationHi":"नवाचार किसी उत्पाद को डिज़ाइन करने, परखने और सुधारने से विकसित होता है, जो वाष्पीकरणीय शीतलन के विचार को नए ढंग से उपयोग करता है। जीवनियाँ, याद करना और आरेख विद्यार्थियों को निष्क्रिय ग्राहक बनाए रखते हैं।"},
  {"id":"cdp-pedagogy-subjects-325","question":"A teacher's test item asks students to pick the correct answer and then, in a second part, to choose the reason for their answer from four given reasons. The chief advantage of this two-tier format is that it:","options":["Reduces the time needed to mark the test, since both tiers can be checked by machine","Allows the teacher to award more marks to every student, since there are two parts","Reveals students who give the right answer for a wrong reason, exposing hidden misconceptions","Replaces the need for any practical assessment, because reasoning is already being tested on paper"],"answer":2,"explanation":"Two-tier items are diagnostic: the reason tier separates true understanding from guessing or a correct answer held for a faulty reason, which a single-tier MCQ cannot show.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"एक शिक्षक की परीक्षा-इकाई विद्यार्थियों से सही उत्तर चुनने को कहती है और फिर दूसरे भाग में दिए गए चार कारणों में से अपने उत्तर का कारण चुनने को कहती है। इस द्वि-स्तरीय प्रारूप का मुख्य लाभ यह है कि यह:","optionsHi":["परीक्षा जाँचने का समय घटाता है, क्योंकि दोनों स्तर मशीन से जाँचे जा सकते हैं","शिक्षक को हर विद्यार्थी को अधिक अंक देने देता है, क्योंकि इसके दो भाग हैं","उन विद्यार्थियों को प्रकट करता है जो गलत कारण से सही उत्तर देते हैं, और छिपी भ्रांत धारणाओं को उजागर करता है","किसी भी प्रायोगिक आकलन की आवश्यकता को समाप्त कर देता है, क्योंकि तर्क की जाँच पहले ही कागज़ पर हो रही है"],"explanationHi":"द्वि-स्तरीय प्रश्न निदानात्मक होते हैं: कारण का स्तर सच्ची समझ को अनुमान या दोषपूर्ण कारण से रखे गए सही उत्तर से अलग करता है, जो एकल-स्तरीय बहुविकल्पीय प्रश्न नहीं दिखा सकता।"},
  {"id":"cdp-pedagogy-subjects-326","question":"A Class 6 chapter on fibres takes students to a local handloom weavers' cluster, where they observe the process and ask how power looms have affected the weavers' livelihoods. Which NCF 2005 criterion does this most directly reflect?","options":["Historical validity","Cognitive validity","Content validity","Environmental validity"],"answer":3,"explanation":"Environmental validity places science in the learner's wider environment, local and global, including issues of technology, society and the world of work. The visit is about present livelihoods, not the history of an idea.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"रेशों पर कक्षा 6 का एक अध्याय विद्यार्थियों को स्थानीय हथकरघा बुनकरों के समूह में ले जाता है, जहाँ वे प्रक्रिया का अवलोकन करते हैं और पूछते हैं कि बिजली-करघों ने बुनकरों की आजीविका को कैसे प्रभावित किया है। यह NCF 2005 की किस कसौटी को सबसे सीधे दर्शाता है?","optionsHi":["ऐतिहासिक वैधता","संज्ञानात्मक वैधता","विषय-वस्तु वैधता","पर्यावरणीय वैधता"],"explanationHi":"पर्यावरणीय वैधता विज्ञान को अधिगमकर्ता के व्यापक परिवेश, स्थानीय और वैश्विक, में रखती है, जिसमें प्रौद्योगिकी, समाज और कार्य-जगत के मुद्दे शामिल हैं। भ्रमण वर्तमान आजीविकाओं के बारे में है, किसी विचार के इतिहास के बारे में नहीं।"},
  {"id":"cdp-pedagogy-subjects-327","question":"A Class I teacher in Bhopal first asks children to clap once for every beat in their names (Ra-hul: two claps, Ka-ma-la: three claps). A month later she asks, 'What is left if we take the /m/ sound away from mat?' Which statement best describes what she is doing?","options":["Both tasks build phonological awareness, first at the syllable level and then at the harder, later-developing phoneme level","Both tasks are phonics, because the children are linking spoken sounds with the letters that stand for them on paper","The first task builds print awareness and the second builds phonological awareness, so they target different skills","The second task is easier than the first, because a single sound is shorter and much simpler to pick out than a whole syllable"],"answer":0,"explanation":"Both tasks are purely oral, so they are phonological awareness, not phonics (which needs letters). Syllable awareness develops before phoneme manipulation, so moving from clapping beats to deleting /m/ follows the normal developmental order.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"भोपाल में कक्षा I की एक शिक्षिका पहले बच्चों से अपने नामों की हर ताल पर एक बार ताली बजाने को कहती है (रा-हुल: दो ताली, क-म-ला: तीन ताली)। एक माह बाद वह पूछती है, ‘अगर हम mat से /m/ ध्वनि हटा दें तो क्या बचेगा?’ कौन-सा कथन उसके कार्य का सबसे अच्छा वर्णन करता है?","optionsHi":["दोनों कार्य ध्वनि-जागरूकता (फ़ोनोलॉजिकल अवेयरनेस) का निर्माण करते हैं, पहले अक्षर (सिलेबल) के स्तर पर और फिर अधिक कठिन, बाद में विकसित होने वाले स्वनिम (फ़ोनीम) के स्तर पर","दोनों कार्य फ़ोनिक्स हैं, क्योंकि बच्चे बोली गई ध्वनियों को कागज़ पर उनका प्रतिनिधित्व करने वाले अक्षरों से जोड़ रहे हैं","पहला कार्य मुद्रित सामग्री की जागरूकता का निर्माण करता है और दूसरा ध्वनि-जागरूकता का, इसलिए वे अलग-अलग कौशलों को लक्ष्य करते हैं","दूसरा कार्य पहले से आसान है, क्योंकि एक अकेली ध्वनि पूरे अक्षर से छोटी और पहचानने में कहीं सरल होती है"],"explanationHi":"दोनों कार्य पूरी तरह मौखिक हैं, इसलिए वे ध्वनि-जागरूकता हैं, फ़ोनिक्स नहीं (जिसमें अक्षर चाहिए)। अक्षर-जागरूकता स्वनिम-हेरफेर से पहले विकसित होती है, इसलिए ताल पर ताली बजाने से /m/ हटाने तक जाना सामान्य विकास-क्रम का अनुसरण करता है।"},
  {"id":"cdp-pedagogy-subjects-328","question":"Consider the following statements about how children learn to read and write: 1. In the emergent literacy view, literacy begins long before formal schooling, through scribbling, pretend reading and talk about books. 2. In the emergent literacy view, a child's 'pretend reading' of a memorised picture book is mere imitation that the teacher should correct. 3. The older reading readiness view held that reading instruction should wait until the child has acquired certain prerequisite skills. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":2,"explanation":"Emergent literacy treats pretend reading as a genuine early literacy behaviour to be encouraged, so statement 2 is false. Statements 1 and 3 correctly contrast the emergent literacy view with the older readiness view.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"बच्चे पढ़ना-लिखना कैसे सीखते हैं, इस बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. उदीयमान साक्षरता के दृष्टिकोण में साक्षरता औपचारिक विद्यालयी शिक्षा से बहुत पहले, आड़ी-तिरछी रेखाएँ खींचने, नाटकीय पठन और पुस्तकों के बारे में बातचीत से शुरू होती है। 2. उदीयमान साक्षरता के दृष्टिकोण में, याद की हुई चित्र-पुस्तक का बच्चे का ‘नाटकीय पठन’ मात्र नकल है जिसे शिक्षक को सुधारना चाहिए। 3. पुराना पठन-तत्परता दृष्टिकोण मानता था कि पठन-शिक्षण तब तक रुकना चाहिए जब तक बच्चे ने कुछ पूर्वापेक्षित कौशल अर्जित न कर लिए हों। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"उदीयमान साक्षरता नाटकीय पठन को वास्तविक प्रारंभिक साक्षरता व्यवहार मानती है जिसे प्रोत्साहित किया जाना चाहिए, इसलिए कथन 2 गलत है। कथन 1 और 3 उदीयमान साक्षरता दृष्टिकोण की पुराने तत्परता दृष्टिकोण से सही तुलना करते हैं।"},
  {"id":"cdp-pedagogy-subjects-329","question":"Seven-year-old Meenu in a Class II classroom in Lucknow writes in her journal: 'I wnt to skul with my frnd.' What is the most appropriate response from the teacher?","options":["Circle each wrong word in red and ask Meenu to write the correct spelling five times so that the errors do not stick in her mind","Respond to the message first, note that Meenu writes the main sounds she hears, and model standard spellings in a reply","Stop journal writing for Meenu until she has learnt the spellings of common words from the textbook","Ignore spelling completely in every class up to Class V, since correct spelling always develops on its own over time"],"answer":1,"explanation":"Invented spelling shows the child's growing sound-letter knowledge; responding to meaning while modelling conventional forms supports progress without killing the urge to write. Endless drill or banning writing harms motivation, while 'never attend to spelling' ignores the need for gradual guidance.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"लखनऊ की कक्षा II में सात वर्ष की मीनू अपनी डायरी में लिखती है: ‘I wnt to skul with my frnd.’ शिक्षक की सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["हर गलत शब्द को लाल घेरे में लेना और मीनू से सही वर्तनी पाँच बार लिखवाना ताकि त्रुटियाँ उसके मन में पक्की न हो जाएँ","पहले संदेश का उत्तर देना, यह नोट करना कि मीनू मुख्य सुनी हुई ध्वनियाँ लिखती है, और उत्तर में मानक वर्तनियाँ आदर्श रूप में प्रस्तुत करना","मीनू का डायरी-लेखन तब तक रोक देना जब तक वह पाठ्यपुस्तक के सामान्य शब्दों की वर्तनी न सीख ले","कक्षा V तक हर कक्षा में वर्तनी को पूरी तरह अनदेखा करना, क्योंकि सही वर्तनी समय के साथ हमेशा अपने आप विकसित होती है"],"explanationHi":"स्वनिर्मित वर्तनी बच्चे के बढ़ते ध्वनि-अक्षर ज्ञान को दिखाती है; अर्थ पर प्रतिक्रिया देते हुए परंपरागत रूप आदर्श प्रस्तुत करना लिखने की इच्छा को मारे बिना प्रगति में सहायक है। अंतहीन अभ्यास या लेखन पर रोक अभिप्रेरणा को हानि पहुँचाते हैं, जबकि ‘वर्तनी पर कभी ध्यान न दो’ क्रमिक मार्गदर्शन की आवश्यकता को अनदेखा करता है।"},
  {"id":"cdp-pedagogy-subjects-330","question":"A Class I teacher proudly shows a visitor her 'print-rich' classroom: the walls are covered with glossy commercially printed English alphabet and fruit charts, fixed high above the blackboard, and she rarely refers to them. Which evaluation is most accurate?","options":["The room is print-rich, because constant exposure to printed charts is by itself enough for young children to learn to read and write on their own","The charts should be removed altogether, because print on the walls distracts young children from the teacher and the lesson","The room would be better if the fruit charts were replaced with more alphabet charts, since letters must come before words","It is not print-rich in the real sense: print should be at eye level, include children's writing and home languages, and be used daily"],"answer":3,"explanation":"A print-rich environment is about meaningful, accessible print that children interact with (labels, names, their own charts, local languages), not decoration. Passive exposure alone does not teach reading, and more alphabet charts only repeat the same mistake.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"कक्षा I की एक शिक्षिका एक आगंतुक को गर्व से अपनी ‘मुद्रित सामग्री से समृद्ध’ कक्षा दिखाती है: दीवारें अंग्रेज़ी वर्णमाला और फलों के चमकीले, व्यावसायिक रूप से छपे चार्टों से ढकी हैं, जो श्यामपट्ट के ऊपर ऊँचाई पर लगे हैं, और वह उनका शायद ही कभी उल्लेख करती है। कौन-सा मूल्यांकन सबसे सटीक है?","optionsHi":["कक्ष मुद्रित सामग्री से समृद्ध है, क्योंकि छपे चार्टों का निरंतर संपर्क ही छोटे बच्चों के लिए अपने आप पढ़ना-लिखना सीखने के लिए पर्याप्त है","चार्ट पूरी तरह हटा देने चाहिए, क्योंकि दीवारों पर छपी सामग्री छोटे बच्चों का ध्यान शिक्षक और पाठ से भटकाती है","कक्ष तब बेहतर होगा जब फल-चार्टों की जगह और वर्णमाला-चार्ट लगाए जाएँ, क्योंकि अक्षर शब्दों से पहले आने चाहिए","यह वास्तविक अर्थ में मुद्रित सामग्री से समृद्ध नहीं है: मुद्रित सामग्री आँखों के स्तर पर होनी चाहिए, उसमें बच्चों का लेखन और घरेलू भाषाएँ शामिल हों, और उसका दैनिक उपयोग हो"],"explanationHi":"मुद्रित सामग्री से समृद्ध वातावरण का अर्थ अर्थपूर्ण, सुलभ मुद्रित सामग्री है जिससे बच्चे जुड़ते हैं (नाम-पर्चियाँ, नाम, उनके अपने चार्ट, स्थानीय भाषाएँ), सजावट नहीं। निष्क्रिय संपर्क अकेले पठन नहीं सिखाता, और और अधिक वर्णमाला-चार्ट वही गलती दोहराते हैं।"},
  {"id":"cdp-pedagogy-subjects-331","question":"While reading aloud a picture storybook to Class II in a Pune school, which teacher practice is most likely to develop children's comprehension?","options":["Reading the whole story without any pause so that fluency is not broken, then asking factual questions from the text","Asking each child to read one line aloud in turn so that everybody in the class gets an equal chance to read","Pausing at key points so children predict what happens, connect events to their lives and talk about the pictures","Translating each sentence word by word into the children's home language right after reading it aloud"],"answer":2,"explanation":"Interactive read-aloud (predicting, connecting, discussing) makes children active meaning-makers. Round-robin reading is a performance exercise, word-by-word translation fragments meaning, and only factual recall questions miss higher-level comprehension.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"पुणे के एक विद्यालय में कक्षा II को चित्र-कथा-पुस्तक ज़ोर से पढ़कर सुनाते समय शिक्षक का कौन-सा अभ्यास बच्चों के बोध को विकसित करने की सबसे अधिक संभावना रखता है?","optionsHi":["पूरी कहानी बिना रुके पढ़ना ताकि प्रवाह न टूटे, फिर पाठ से तथ्यात्मक प्रश्न पूछना","हर बच्चे से बारी-बारी एक पंक्ति ज़ोर से पढ़वाना ताकि कक्षा में सभी को पढ़ने का समान अवसर मिले","प्रमुख बिंदुओं पर रुकना ताकि बच्चे अनुमान लगाएँ कि क्या होगा, घटनाओं को अपने जीवन से जोड़ें और चित्रों के बारे में बात करें","ज़ोर से पढ़ने के तुरंत बाद हर वाक्य का बच्चों की घरेलू भाषा में शब्द-दर-शब्द अनुवाद करना"],"explanationHi":"अंतःक्रियात्मक ज़ोर से पढ़ना (पूर्वानुमान, जुड़ाव, चर्चा) बच्चों को सक्रिय अर्थ-निर्माता बनाता है। बारी-बारी से पढ़ना प्रदर्शन का अभ्यास है, शब्द-दर-शब्द अनुवाद अर्थ को खंडित करता है, और केवल तथ्यात्मक स्मरण के प्रश्न उच्च-स्तरीय बोध को चूक जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-332","question":"Assertion (A): Round-robin reading, in which each child reads one sentence aloud in turn, is not recommended as the main reading practice in the early grades. Reason (R): It gives each child very little actual reading time, focuses attention on oral performance rather than meaning, and can embarrass struggling readers.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Round-robin reading keeps most children idle while one reads, turns reading into a test of pronunciation, and creates anxiety; these are exactly why it is discouraged, so R explains A.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"अभिकथन (A): बारी-बारी से पढ़ना, जिसमें हर बच्चा बारी-बारी से एक वाक्य ज़ोर से पढ़ता है, प्रारंभिक कक्षाओं में मुख्य पठन-अभ्यास के रूप में अनुशंसित नहीं है। कारण (R): यह हर बच्चे को वास्तविक पठन का बहुत कम समय देता है, ध्यान अर्थ के बजाय मौखिक प्रदर्शन पर केंद्रित करता है, और कमज़ोर पाठकों को शर्मिंदा कर सकता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"बारी-बारी से पढ़ना अधिकांश बच्चों को निष्क्रिय रखता है जबकि एक पढ़ता है, पठन को उच्चारण की परीक्षा बना देता है और चिंता पैदा करता है; ठीक इन्हीं कारणों से इसे हतोत्साहित किया जाता है, इसलिए R, A की व्याख्या करता है।"},
  {"id":"cdp-pedagogy-subjects-333","question":"Five-year-old Arjun tells the whole story of a picture book fluently while turning its pages, but he holds the book upside down and starts from the last page. His teacher concludes, 'He cannot read at all.' What is the most appropriate interpretation?","options":["Arjun lacks phonemic awareness and needs daily drills on letter sounds before he is allowed to handle books again","Arjun has good oral narrative skill but not yet concepts about print, such as orientation and direction, which shared reading can model","Arjun may have a visual-perceptual disorder, so he should be referred to a specialist before any further reading instruction in class can begin","Arjun has only memorised the story, so his narration has no real value for his literacy development and can be ignored"],"answer":1,"explanation":"Narrating from pictures is a real emergent literacy strength; what is missing is concepts about print (which way up, front to back, left to right), best taught by modelling with big books. Referral or dismissing his narration misreads normal development.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"पाँच वर्ष का अर्जुन चित्र-पुस्तक के पन्ने पलटते हुए पूरी कहानी धाराप्रवाह सुनाता है, लेकिन वह पुस्तक को उलटी पकड़ता है और आखिरी पन्ने से शुरू करता है। उसकी शिक्षिका निष्कर्ष निकालती है, ‘यह बिल्कुल पढ़ नहीं सकता।’ सबसे उपयुक्त व्याख्या क्या है?","optionsHi":["अर्जुन में स्वनिमिक जागरूकता नहीं है और उसे पुस्तकों को फिर से छूने देने से पहले अक्षर-ध्वनियों का दैनिक अभ्यास चाहिए","अर्जुन में अच्छा मौखिक वर्णन-कौशल है, लेकिन मुद्रित सामग्री की अवधारणाएँ, जैसे दिशा और अभिविन्यास, अभी नहीं हैं, जिन्हें साझा पठन आदर्श रूप में दिखा सकता है","अर्जुन को दृश्य-प्रत्यक्षण विकार हो सकता है, इसलिए कक्षा में आगे कोई पठन-शिक्षण शुरू होने से पहले उसे विशेषज्ञ के पास भेजना चाहिए","अर्जुन ने केवल कहानी याद कर ली है, इसलिए उसके वर्णन का उसके साक्षरता-विकास के लिए कोई वास्तविक मूल्य नहीं है और उसे अनदेखा किया जा सकता है"],"explanationHi":"चित्रों से कहानी सुनाना उदीयमान साक्षरता की वास्तविक शक्ति है; जो कमी है वह मुद्रित सामग्री की अवधारणाएँ हैं (कौन-सा ऊपर है, आगे से पीछे, बाएँ से दाएँ), जो बिग बुक के साथ आदर्श प्रस्तुति से सबसे अच्छी तरह सिखाई जाती हैं। विशेषज्ञ के पास भेजना या उसके वर्णन को खारिज करना सामान्य विकास को गलत समझना है।"},
  {"id":"cdp-pedagogy-subjects-334","question":"During shared reading with a big book, a Class I teacher slides her finger under each word as she reads. The main purpose of this action is to:","options":["make children memorise the text faster so that they can recite the whole book from memory by the end of the week","check whether children are pronouncing every word correctly as they read along with her","keep children's eyes fixed on the book so that attention and discipline are maintained","show the one-to-one match between spoken and written words and the direction in which print runs"],"answer":3,"explanation":"Finger tracking demonstrates concepts about print: each spoken word matches a written word, with spaces between words, read left to right and top to bottom. It is a teaching move, not a memory or discipline device.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"बिग बुक के साथ साझा पठन के दौरान कक्षा I की शिक्षिका पढ़ते समय हर शब्द के नीचे अपनी उँगली सरकाती है। इस क्रिया का मुख्य उद्देश्य है:","optionsHi":["बच्चों को पाठ जल्दी याद करवाना ताकि वे सप्ताह के अंत तक पूरी पुस्तक स्मृति से सुना सकें","जाँचना कि बच्चे उसके साथ पढ़ते हुए हर शब्द का उच्चारण सही कर रहे हैं या नहीं","बच्चों की आँखें पुस्तक पर टिकाए रखना ताकि ध्यान और अनुशासन बना रहे","बोले गए और लिखे गए शब्दों के बीच एक-से-एक मेल और मुद्रित सामग्री के चलने की दिशा दिखाना"],"explanationHi":"उँगली से अनुसरण करना मुद्रित सामग्री की अवधारणाएँ दिखाता है: हर बोला गया शब्द एक लिखे गए शब्द से मेल खाता है, शब्दों के बीच खाली स्थान होते हैं, और पाठ बाएँ से दाएँ तथा ऊपर से नीचे पढ़ा जाता है। यह एक शिक्षण-क्रिया है, स्मृति या अनुशासन का साधन नहीं।"},
  {"id":"cdp-pedagogy-subjects-335","question":"In a Class I classroom in Bastar, almost all children speak Gondi at home, while the school textbook and the teacher use Hindi. In line with NEP 2020 and multilingual education, what should the teacher do?","options":["Ban Gondi in the classroom so that children get the maximum possible exposure to Hindi, the language of the textbook","Postpone all reading and writing until the children have become fluent speakers of Hindi, the medium of instruction","Begin with Gondi for talk, concepts and early literacy, and gradually bridge to Hindi by building on what children know","Teach Gondi and Hindi as two separate subjects in separate periods, with no link at all being made between the two languages"],"answer":2,"explanation":"Children learn concepts and literacy best in a language they understand; a planned bridge then transfers these skills to the school language. Banning the home language (submersion) causes failure and alienation, and postponing literacy wastes the foundational years.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"बस्तर की कक्षा I में लगभग सभी बच्चे घर पर गोंडी बोलते हैं, जबकि विद्यालय की पाठ्यपुस्तक और शिक्षक हिंदी का उपयोग करते हैं। NEP 2020 और बहुभाषिक शिक्षा के अनुरूप शिक्षक को क्या करना चाहिए?","optionsHi":["कक्षा में गोंडी पर प्रतिबंध लगाना ताकि बच्चों को पाठ्यपुस्तक की भाषा हिंदी का अधिकतम संभव संपर्क मिले","सभी पठन और लेखन तब तक टालना जब तक बच्चे शिक्षा के माध्यम हिंदी में धाराप्रवाह वक्ता न बन जाएँ","बातचीत, संप्रत्ययों और प्रारंभिक साक्षरता के लिए गोंडी से शुरू करना, और बच्चे जो पहले से जानते हैं उसी के आधार पर धीरे-धीरे हिंदी तक सेतु बनाना","गोंडी और हिंदी को अलग-अलग कालांशों में दो अलग विषयों के रूप में पढ़ाना, दोनों भाषाओं के बीच कोई संबंध बनाए बिना"],"explanationHi":"बच्चे संप्रत्यय और साक्षरता उस भाषा में सबसे अच्छा सीखते हैं जिसे वे समझते हैं; फिर एक नियोजित सेतु इन कौशलों को विद्यालयी भाषा में स्थानांतरित करता है। घरेलू भाषा पर प्रतिबंध (सबमर्शन) असफलता और अलगाव लाता है, और साक्षरता टालना आधारभूत वर्षों को व्यर्थ करता है।"},
  {"id":"cdp-pedagogy-subjects-336","question":"In a well-planned mother-tongue-based multilingual education (MTB-MLE) programme, which sequence of the bridge to the school language is most appropriate?","options":["Oral home language and home-language literacy first, then oral school language, then school-language literacy built on the first","Reading and writing in the school language first, then oral home language, and only then the oral school language","Oral school language first, then reading and writing in the school language, with the home language used only to explain the textbook","Literacy in the home language and the school language both started together on the first day, with oral work added later on"],"answer":0,"explanation":"MTB-MLE moves from the known to the unknown: oral home language, home-language literacy, oral second language, then second-language literacy that transfers already-learnt skills. Starting with literacy in an unfamiliar language reverses this logic.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"एक सुनियोजित मातृभाषा-आधारित बहुभाषिक शिक्षा (MTB-MLE) कार्यक्रम में, विद्यालयी भाषा तक सेतु का कौन-सा क्रम सबसे उपयुक्त है?","optionsHi":["पहले मौखिक घरेलू भाषा और घरेलू भाषा की साक्षरता, फिर मौखिक विद्यालयी भाषा, फिर पहले पर आधारित विद्यालयी भाषा की साक्षरता","पहले विद्यालयी भाषा में पढ़ना और लिखना, फिर मौखिक घरेलू भाषा, और उसके बाद ही मौखिक विद्यालयी भाषा","पहले मौखिक विद्यालयी भाषा, फिर विद्यालयी भाषा में पढ़ना-लिखना, घरेलू भाषा केवल पाठ्यपुस्तक समझाने के लिए","घरेलू भाषा और विद्यालयी भाषा दोनों की साक्षरता पहले दिन एक साथ शुरू करना, और मौखिक कार्य बाद में जोड़ना"],"explanationHi":"MTB-MLE ज्ञात से अज्ञात की ओर बढ़ता है: मौखिक घरेलू भाषा, घरेलू भाषा की साक्षरता, मौखिक द्वितीय भाषा, फिर द्वितीय भाषा की साक्षरता जो पहले से सीखे कौशलों को स्थानांतरित करती है। किसी अपरिचित भाषा की साक्षरता से शुरू करना इस तर्क को उलट देता है।"},
  {"id":"cdp-pedagogy-subjects-337","question":"Assertion (A): Children who first learn to read well in their mother tongue usually find it easier to learn to read in a second language. Reason (R): Literacy skills and conceptual knowledge, once acquired in one language, can largely transfer to another language.","options":["Both A and R are true, but R is not the correct explanation of A","Both A and R are true, and R is the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Cummins' idea of a common underlying proficiency holds that reading strategies and concepts learnt in one language are available in another; this transfer is exactly why strong mother-tongue literacy helps second-language reading.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): जो बच्चे पहले अपनी मातृभाषा में अच्छी तरह पढ़ना सीखते हैं, उन्हें प्रायः द्वितीय भाषा में पढ़ना सीखना आसान लगता है। कारण (R): एक भाषा में अर्जित साक्षरता कौशल और संप्रत्ययात्मक ज्ञान काफ़ी हद तक दूसरी भाषा में स्थानांतरित हो सकते हैं।","optionsHi":["A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"कमिन्स का साझा अंतर्निहित दक्षता का विचार मानता है कि एक भाषा में सीखी गई पठन-रणनीतियाँ और संप्रत्यय दूसरी भाषा में उपलब्ध होते हैं; ठीक यही स्थानांतरण बताता है कि सशक्त मातृभाषा साक्षरता द्वितीय भाषा पठन में क्यों सहायक है।"},
  {"id":"cdp-pedagogy-subjects-338","question":"A Class I teacher has planned four oral activities: P. splitting sun into its three separate sounds; Q. counting the words in a spoken sentence; R. noticing that cat and hat end with the same chunk -at; S. clapping the syllables in banana. In which order should they ideally be introduced, from easiest to hardest?","options":["S, Q, R, P","Q, S, P, R","R, Q, S, P","Q, S, R, P"],"answer":3,"explanation":"Phonological awareness usually develops from larger to smaller units: words in a sentence, syllables, onset and rime (rhyme families), and finally individual phonemes. So Q, S, R, P.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा I की एक शिक्षिका ने चार मौखिक गतिविधियाँ नियोजित की हैं: P. sun को उसकी तीन अलग ध्वनियों में तोड़ना; Q. बोले गए वाक्य में शब्द गिनना; R. यह देखना कि cat और hat का अंत एक ही खंड -at से होता है; S. banana के अक्षरों (सिलेबल) पर ताली बजाना। इन्हें सबसे आसान से सबसे कठिन के क्रम में किस क्रम में प्रस्तुत किया जाना चाहिए?","optionsHi":["S, Q, R, P","Q, S, P, R","R, Q, S, P","Q, S, R, P"],"explanationHi":"ध्वनि-जागरूकता प्रायः बड़ी इकाइयों से छोटी इकाइयों की ओर विकसित होती है: वाक्य में शब्द, अक्षर, आरंभ और अंत-खंड (तुकांत परिवार), और अंत में अलग-अलग स्वनिम। इसलिए Q, S, R, P।"},
  {"id":"cdp-pedagogy-subjects-339","question":"Consider the following statements: 1. A teacher asking 'What is the first sound in pen?' with children's eyes closed is developing phonemic awareness. 2. Phonics instruction teaches the relationship between sounds and the letters or akshar that represent them. 3. Phonemic awareness cannot be developed until children know the letters of the alphabet. Which of these are correct?","options":["1 and 3 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Phonemic awareness is an oral skill and can be built without any print, so statement 3 is false. Phonics adds the link to written symbols, as statement 2 says.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"निम्नलिखित कथनों पर विचार कीजिए: 1. जब बच्चों की आँखें बंद हों, तब शिक्षक का पूछना ‘pen में पहली ध्वनि क्या है?’ स्वनिमिक जागरूकता का विकास करता है। 2. फ़ोनिक्स शिक्षण ध्वनियों और उन्हें दर्शाने वाले अक्षरों या अक्षर-चिह्नों के बीच संबंध सिखाता है। 3. स्वनिमिक जागरूकता तब तक विकसित नहीं की जा सकती जब तक बच्चे वर्णमाला के अक्षर न जान लें। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 2 और 3","केवल 1 और 2","1, 2 और 3"],"explanationHi":"स्वनिमिक जागरूकता एक मौखिक कौशल है और इसे बिना किसी मुद्रित सामग्री के निर्मित किया जा सकता है, इसलिए कथन 3 गलत है। फ़ोनिक्स लिखित प्रतीकों से संबंध जोड़ता है, जैसा कथन 2 कहता है।"},
  {"id":"cdp-pedagogy-subjects-340","question":"After a visit to a mango orchard, a Class II teacher in Ratnagiri writes on chart paper the sentences children dictate about the trip, reads them back with the class, and uses the chart for reading practice over the next week. Why is this approach particularly effective for beginning readers?","options":["The text is in the children's own words about their own trip, so its meaning is predictable and they see speech become print","It guarantees that children will learn the correct spelling of every word on the chart, since they copy and read it every day of the week","It removes the need for any explicit teaching of letters and sounds, because children learn them from the chart","It makes sure all children learn exactly the same vocabulary as the textbook, so the syllabus is covered faster"],"answer":0,"explanation":"The language experience approach turns the child's own talk into reading material, so familiar meaning supports decoding and links oral and written language. It complements, not replaces, sound-letter teaching.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"आम के बाग की सैर के बाद रत्नागिरी में कक्षा II की एक शिक्षिका सैर के बारे में बच्चों द्वारा बोले गए वाक्यों को चार्ट-पेपर पर लिखती है, उन्हें कक्षा के साथ दोहराकर पढ़ती है, और अगले सप्ताह पठन-अभ्यास के लिए उस चार्ट का उपयोग करती है। शुरुआती पाठकों के लिए यह उपागम विशेष रूप से प्रभावी क्यों है?","optionsHi":["पाठ बच्चों के अपने शब्दों में उनकी अपनी सैर के बारे में है, इसलिए उसका अर्थ पूर्वानुमेय है और वे बोलचाल को मुद्रित रूप लेते देखते हैं","यह गारंटी देता है कि बच्चे चार्ट के हर शब्द की सही वर्तनी सीख लेंगे, क्योंकि वे सप्ताह के हर दिन उसे उतारते और पढ़ते हैं","यह अक्षरों और ध्वनियों के किसी भी स्पष्ट शिक्षण की आवश्यकता को समाप्त कर देता है, क्योंकि बच्चे उन्हें चार्ट से सीख लेते हैं","यह सुनिश्चित करता है कि सभी बच्चे बिल्कुल वही शब्दावली सीखें जो पाठ्यपुस्तक में है, ताकि पाठ्यक्रम जल्दी पूरा हो"],"explanationHi":"भाषा-अनुभव उपागम बच्चे की अपनी बातचीत को पठन-सामग्री में बदल देता है, इसलिए परिचित अर्थ डिकोडिंग को सहारा देता है और मौखिक तथा लिखित भाषा को जोड़ता है। यह ध्वनि-अक्षर शिक्षण का पूरक है, उसका स्थान नहीं लेता।"},
  {"id":"cdp-pedagogy-subjects-341","question":"Reading the sentence 'I live in a big house', a Class II child says 'I live in a big home' and carries on. What should the teacher conclude and do?","options":["The child has a visual processing problem and should be referred for a detailed assessment before reading further","The child uses meaning and first letters but not the whole word; prompt cross-checking: 'It makes sense, but does it look right?'","The child is guessing randomly, so the teacher should stop the story at once and drill the isolated letter sounds until they are secure","The child is reading word by word without understanding, so comprehension questions should be dropped for now"],"answer":1,"explanation":"A miscue that keeps the meaning shows the child is reading for sense; the gap is in attending to the whole printed word. Prompting the child to check meaning against print strengthens both cue systems without treating the miscue as a random error.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"वाक्य ‘I live in a big house’ पढ़ते समय कक्षा II का एक बच्चा ‘I live in a big home’ कहता है और आगे बढ़ जाता है। शिक्षक को क्या निष्कर्ष निकालना और क्या करना चाहिए?","optionsHi":["बच्चे को दृश्य प्रसंस्करण की समस्या है और आगे पढ़ने से पहले उसे विस्तृत आकलन के लिए भेजना चाहिए","बच्चा अर्थ और पहले अक्षरों का उपयोग करता है, लेकिन पूरे शब्द का नहीं; पारस्परिक जाँच के लिए प्रेरित करें: ‘इसका अर्थ बनता है, लेकिन क्या यह सही दिखता है?’","बच्चा यूँ ही अनुमान लगा रहा है, इसलिए शिक्षक को कहानी तुरंत रोककर अलग-अलग अक्षर-ध्वनियों का तब तक अभ्यास कराना चाहिए जब तक वे पक्की न हो जाएँ","बच्चा बिना समझे शब्द-दर-शब्द पढ़ रहा है, इसलिए बोध-प्रश्न अभी छोड़ देने चाहिए"],"explanationHi":"अर्थ को बनाए रखने वाला मिसक्यू दिखाता है कि बच्चा भाव के लिए पढ़ रहा है; कमी पूरे मुद्रित शब्द पर ध्यान देने में है। बच्चे को अर्थ की जाँच मुद्रित पाठ से करने को प्रेरित करना मिसक्यू को यादृच्छिक त्रुटि माने बिना दोनों संकेत-प्रणालियों को मज़बूत करता है।"},
  {"id":"cdp-pedagogy-subjects-342","question":"Which sequence correctly shows how young children's writing usually develops?","options":["Random letter strings, scribbling, letter-like shapes, invented spelling, conventional spelling","Scribbling, invented spelling, letter-like shapes, random letter strings, conventional spelling","Letter-like shapes, scribbling, invented spelling, random letter strings, conventional spelling","Scribbling, letter-like shapes, random letter strings, invented spelling, conventional spelling"],"answer":3,"explanation":"Children move from scribbles to mock letters, then to strings of real letters without sound links, then to spelling by sound, and finally to conventional spelling. Seeing these stages helps teachers value early writing.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कौन-सा क्रम सही दर्शाता है कि छोटे बच्चों का लेखन सामान्यतः कैसे विकसित होता है?","optionsHi":["अक्षरों की यादृच्छिक शृंखलाएँ, आड़ी-तिरछी रेखाएँ, अक्षर-जैसी आकृतियाँ, स्वनिर्मित वर्तनी, परंपरागत वर्तनी","आड़ी-तिरछी रेखाएँ, स्वनिर्मित वर्तनी, अक्षर-जैसी आकृतियाँ, अक्षरों की यादृच्छिक शृंखलाएँ, परंपरागत वर्तनी","अक्षर-जैसी आकृतियाँ, आड़ी-तिरछी रेखाएँ, स्वनिर्मित वर्तनी, अक्षरों की यादृच्छिक शृंखलाएँ, परंपरागत वर्तनी","आड़ी-तिरछी रेखाएँ, अक्षर-जैसी आकृतियाँ, अक्षरों की यादृच्छिक शृंखलाएँ, स्वनिर्मित वर्तनी, परंपरागत वर्तनी"],"explanationHi":"बच्चे आड़ी-तिरछी रेखाओं से नकली अक्षरों की ओर, फिर ध्वनि-संबंध के बिना वास्तविक अक्षरों की शृंखलाओं की ओर, फिर ध्वनि के आधार पर वर्तनी की ओर, और अंत में परंपरागत वर्तनी की ओर बढ़ते हैं। इन चरणों को देखना शिक्षकों को प्रारंभिक लेखन को महत्त्व देने में मदद करता है।"},
  {"id":"cdp-pedagogy-subjects-343","question":"Assertion (A): A teacher should continue reading aloud to children in Classes IV and V, even after they can read independently. Reason (R): Read-alouds let children enjoy and understand texts that are richer in vocabulary and structure than what they can yet read on their own.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Listening comprehension runs ahead of reading level for years, so read-alouds expose children to harder language and model fluent, expressive reading. This is precisely why they remain useful in upper primary.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"अभिकथन (A): शिक्षक को कक्षा IV और V के बच्चों को, उनके स्वतंत्र रूप से पढ़ पाने के बाद भी, ज़ोर से पढ़कर सुनाना जारी रखना चाहिए। कारण (R): ज़ोर से पढ़कर सुनाना बच्चों को उन पाठों का आनंद लेने और समझने देता है जो शब्दावली और संरचना में उससे अधिक समृद्ध हैं जितना वे अभी स्वयं पढ़ सकते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"श्रवण-बोध वर्षों तक पठन-स्तर से आगे चलता है, इसलिए ज़ोर से पढ़कर सुनाना बच्चों को कठिन भाषा से परिचित कराता है और धाराप्रवाह, भावपूर्ण पठन का आदर्श प्रस्तुत करता है। ठीक इसीलिए वे उच्च प्राथमिक में भी उपयोगी बने रहते हैं।"},
  {"id":"cdp-pedagogy-subjects-344","question":"A district resource group is designing early-grade reading lessons under NIPUN Bharat. Which plan best reflects a balanced approach to early literacy?","options":["Only phonics drills until decoding is perfect, after which stories and books are gradually introduced for enjoyment","Only exposure to stories and books, with no explicit teaching of letters and sounds, since children pick up decoding naturally by themselves","Daily read-alouds, talk and children's books combined with explicit, systematic sound-symbol work and plenty of meaningful writing","Rote recitation of the full varnamala in its fixed order before any words, stories or books are introduced to children"],"answer":2,"explanation":"A balanced approach combines meaning-making (oral language, read-aloud, books) with explicit decoding instruction and writing. The two extremes (only drills or only exposure) and rote alphabet recitation each leave out a vital strand.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"एक ज़िला संसाधन समूह निपुण भारत के अंतर्गत प्रारंभिक कक्षाओं के पठन-पाठ तैयार कर रहा है। कौन-सी योजना प्रारंभिक साक्षरता के संतुलित उपागम को सबसे अच्छी तरह दर्शाती है?","optionsHi":["डिकोडिंग के पूर्ण होने तक केवल फ़ोनिक्स अभ्यास, जिसके बाद आनंद के लिए धीरे-धीरे कहानियाँ और पुस्तकें लाई जाएँ","केवल कहानियों और पुस्तकों का संपर्क, अक्षरों और ध्वनियों का कोई स्पष्ट शिक्षण नहीं, क्योंकि बच्चे डिकोडिंग अपने आप स्वाभाविक रूप से सीख लेते हैं","दैनिक ज़ोर से पढ़कर सुनाना, बातचीत और बच्चों की पुस्तकें, साथ में स्पष्ट, व्यवस्थित ध्वनि-प्रतीक कार्य और प्रचुर अर्थपूर्ण लेखन","बच्चों को किसी भी शब्द, कहानी या पुस्तक से परिचित कराने से पहले पूरी वर्णमाला को उसके निश्चित क्रम में रटकर दोहराना"],"explanationHi":"संतुलित उपागम अर्थ-निर्माण (मौखिक भाषा, ज़ोर से पढ़ना, पुस्तकें) को स्पष्ट डिकोडिंग शिक्षण और लेखन के साथ जोड़ता है। दोनों अतिवाद (केवल अभ्यास या केवल संपर्क) और वर्णमाला की रटंत हर एक एक महत्त्वपूर्ण सूत्र को छोड़ देते हैं।"},
  {"id":"cdp-pedagogy-subjects-345","question":"A Class I Hindi teacher teaches one letter of the varnamala each week, strictly in alphabetical order, through chanting and copying, and introduces words only after all letters are covered. Which criticism is most valid?","options":["The pace is too fast; two weeks per letter would give children enough time to master each letter fully before moving on to the next one","Letters are taught in isolation and too slowly; children should meet common letters in meaningful words and read simple words early","Matras should be taught first, before any consonants, since they occur in almost every word children will read","Chanting is good, but the teacher should first insist on neat handwriting of every letter before any reading is attempted"],"answer":1,"explanation":"Decontextualised, letter-a-week teaching delays reading for months and gives no meaning; starting with high-utility letters and blending them into words quickly lets children read early. Slowing down or adding handwriting prerequisites makes the problem worse.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा I की एक हिंदी शिक्षिका हर सप्ताह वर्णमाला का एक अक्षर, कड़ाई से वर्णानुक्रम में, दोहराने और उतारने के माध्यम से सिखाती है, और सभी अक्षर पूरे होने के बाद ही शब्द प्रस्तुत करती है। कौन-सी आलोचना सबसे वैध है?","optionsHi":["गति बहुत तेज़ है; प्रति अक्षर दो सप्ताह बच्चों को अगले अक्षर पर जाने से पहले हर अक्षर में पूरी तरह दक्ष होने का पर्याप्त समय देंगे","अक्षर अलग-थलग और बहुत धीरे पढ़ाए जाते हैं; बच्चों को सामान्य अक्षर अर्थपूर्ण शब्दों में मिलने चाहिए और उन्हें सरल शब्द जल्दी पढ़ने चाहिए","मात्राएँ व्यंजनों से पहले सिखानी चाहिए, क्योंकि वे बच्चों द्वारा पढ़े जाने वाले लगभग हर शब्द में आती हैं","दोहराना अच्छा है, लेकिन किसी भी पठन का प्रयास करने से पहले शिक्षिका को हर अक्षर की साफ़ लिखावट पर ज़ोर देना चाहिए"],"explanationHi":"संदर्भ से कटा, सप्ताह में एक अक्षर वाला शिक्षण महीनों तक पठन में देरी करता है और कोई अर्थ नहीं देता; उच्च-उपयोगिता वाले अक्षरों से शुरू करके उन्हें जल्दी शब्दों में जोड़ना बच्चों को जल्दी पढ़ने देता है। गति धीमी करना या हस्तलेखन की पूर्वापेक्षाएँ जोड़ना समस्या को और बढ़ाता है।"},
  {"id":"cdp-pedagogy-subjects-346","question":"While reading a Hindi passage aloud, a Class III child in a Bihar village pronounces several words the way they are spoken in Bhojpuri, but answers every comprehension question correctly. What is the most appropriate teacher response?","options":["Stop the child at every such word and insist on the standard pronunciation before letting her move on in the passage","Record each dialect pronunciation as a reading error in the child's assessment so that progress can be tracked","Refer the child to a speech therapist, since the repeated mispronunciations suggest an articulation problem","Accept the dialect pronunciations as part of the child's language, since she is decoding and understanding the text"],"answer":3,"explanation":"Dialect features are not reading errors; the child is decoding and comprehending. Constant correction marks the home language as inferior and discourages reading, while referral confuses dialect with a disorder.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"बिहार के एक गाँव में हिंदी का अनुच्छेद ज़ोर से पढ़ते समय कक्षा III की एक बच्ची कई शब्दों का उच्चारण वैसे करती है जैसे वे भोजपुरी में बोले जाते हैं, लेकिन बोध के हर प्रश्न का सही उत्तर देती है। शिक्षक की सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["अनुच्छेद में आगे बढ़ने देने से पहले ऐसे हर शब्द पर बच्ची को रोकना और मानक उच्चारण पर ज़ोर देना","बच्ची के आकलन में हर बोली-उच्चारण को पठन-त्रुटि के रूप में दर्ज करना ताकि प्रगति का पता लगाया जा सके","बच्ची को वाक्-चिकित्सक के पास भेजना, क्योंकि बार-बार के गलत उच्चारण उच्चारण-समस्या का संकेत देते हैं","बोली के उच्चारणों को बच्ची की भाषा का भाग मानकर स्वीकार करना, क्योंकि वह पाठ को डिकोड कर रही है और समझ रही है"],"explanationHi":"बोली की विशेषताएँ पठन-त्रुटियाँ नहीं हैं; बच्ची डिकोड कर रही है और समझ रही है। लगातार सुधार घरेलू भाषा को हीन चिह्नित करता है और पढ़ने को हतोत्साहित करता है, जबकि विशेषज्ञ के पास भेजना बोली को विकार से मिला देता है।"},
  {"id":"cdp-pedagogy-subjects-347","question":"A Class IV teacher wants her library period to build a lasting reading habit. Which practice is most suitable?","options":["Children choose their own books, including books in home languages, and read for pleasure with no test afterwards","All children read the same book and write a summary that is marked for grammar, so that reading is checked","Only textbook chapters are read in the library period so that the syllabus is completed well before the annual exams","Children are allowed into the library only after finishing their classwork, so that reading becomes a reward"],"answer":0,"explanation":"Free voluntary reading with choice and no testing builds motivation and volume of reading, which drive fluency and vocabulary. Turning reading into a test or a reward makes it an assignment rather than a habit.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा IV की एक शिक्षिका चाहती है कि उसका पुस्तकालय-कालांश स्थायी पठन-आदत निर्मित करे। कौन-सा अभ्यास सबसे उपयुक्त है?","optionsHi":["बच्चे अपनी पुस्तकें स्वयं चुनते हैं, जिनमें घरेलू भाषाओं की पुस्तकें भी शामिल हैं, और आनंद के लिए पढ़ते हैं, बाद में कोई परीक्षा नहीं","सभी बच्चे एक ही पुस्तक पढ़ते हैं और सार लिखते हैं जिसे व्याकरण के लिए जाँचा जाता है, ताकि पठन की जाँच हो","पुस्तकालय-कालांश में केवल पाठ्यपुस्तक के अध्याय पढ़े जाते हैं ताकि वार्षिक परीक्षाओं से बहुत पहले पाठ्यक्रम पूरा हो जाए","बच्चों को पुस्तकालय में केवल कक्षा-कार्य पूरा करने के बाद आने दिया जाता है, ताकि पढ़ना पुरस्कार बन जाए"],"explanationHi":"चयन के साथ और बिना परीक्षा के स्वतंत्र स्वैच्छिक पठन अभिप्रेरणा और पठन की मात्रा बढ़ाता है, जो प्रवाह और शब्दावली को आगे बढ़ाते हैं। पठन को परीक्षा या पुरस्कार बना देना उसे आदत के बजाय एक कार्य बना देता है।"},
  {"id":"cdp-pedagogy-subjects-348","question":"Match each Class I activity with the early literacy skill it mainly targets. Activities: P. Picking the odd one out by first sound (bat, ball, cup); Q. Showing where to start reading on a page; R. Re-reading a familiar poem with expression until it flows; S. Retelling a story in one's own words. Skills: 1. Fluency; 2. Phonological awareness; 3. Comprehension; 4. Concepts about print.","options":["P-2, Q-1, R-4, S-3","P-4, Q-2, R-1, S-3","P-2, Q-4, R-1, S-3","P-2, Q-4, R-3, S-1"],"answer":2,"explanation":"Odd-one-out by sound is phonological awareness; knowing where to start is a concept about print; repeated expressive reading builds fluency; retelling shows comprehension.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा I की हर गतिविधि का उस प्रारंभिक साक्षरता कौशल से मिलान कीजिए जिसे वह मुख्य रूप से लक्ष्य करती है। गतिविधियाँ: P. पहली ध्वनि के आधार पर बेमेल निकालना (bat, ball, cup); Q. यह दिखाना कि पृष्ठ पर पढ़ना कहाँ से शुरू करना है; R. किसी परिचित कविता को भाव सहित तब तक दोबारा पढ़ना जब तक वह प्रवाहित न हो जाए; S. किसी कहानी को अपने शब्दों में दोबारा सुनाना। कौशल: 1. प्रवाह; 2. ध्वनि-जागरूकता; 3. बोध; 4. मुद्रित सामग्री की अवधारणाएँ।","optionsHi":["P-2, Q-1, R-4, S-3","P-4, Q-2, R-1, S-3","P-2, Q-4, R-1, S-3","P-2, Q-4, R-3, S-1"],"explanationHi":"ध्वनि के आधार पर बेमेल निकालना ध्वनि-जागरूकता है; यह जानना कि कहाँ से शुरू करना है मुद्रित सामग्री की अवधारणा है; बार-बार भावपूर्ण पठन प्रवाह बनाता है; और दोबारा सुनाना बोध दर्शाता है।"},
  {"id":"cdp-pedagogy-subjects-349","question":"A teacher wants to check the phonological awareness of a Class I child who cannot yet read. Which task is the valid one for this purpose?","options":["Dictating five simple words for the child to write","Asking the child to say kamal without the ka sound","Showing letter cards and asking the child to name each letter","Asking the child to copy a sentence from the blackboard"],"answer":1,"explanation":"Phonological awareness is oral, so it must be assessed without print; sound deletion does this. The other tasks test letter knowledge, spelling or copying, which a non-reader would fail for different reasons.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"एक शिक्षिका कक्षा I के उस बच्चे की ध्वनि-जागरूकता जाँचना चाहती है जो अभी पढ़ नहीं सकता। इस उद्देश्य के लिए कौन-सा कार्य वैध है?","optionsHi":["बच्चे को लिखने के लिए पाँच सरल शब्द श्रुतलेख में बोलना","बच्चे से kamal को ka ध्वनि के बिना बोलने को कहना","अक्षर-कार्ड दिखाना और बच्चे से हर अक्षर का नाम बताने को कहना","बच्चे से श्यामपट्ट से एक वाक्य उतारने को कहना"],"explanationHi":"ध्वनि-जागरूकता मौखिक है, इसलिए उसका आकलन बिना मुद्रित सामग्री के होना चाहिए; ध्वनि-लोपन यही करता है। अन्य कार्य अक्षर-ज्ञान, वर्तनी या नकल की जाँच करते हैं, जिनमें एक अपठित बच्चा अलग कारणों से असफल होगा।"},
  {"id":"cdp-pedagogy-subjects-350","question":"Parents of four-year-olds in an Anganwadi-cum-preschool want daily worksheets for tracing and writing the alphabet. Following NCF for the Foundational Stage 2022, what should the teacher explain and do?","options":["Agree, and start daily cursive writing practice at once, since early neat handwriting is widely said to predict later success at school","Refuse to show children any print at all until they turn six, because early print exposure causes stress and confusion","Agree to daily alphabet tracing so that the parents are satisfied, while continuing play-based activities separately","Explain that at this age the focus is talk, stories, songs, drawing, emergent writing and fine-motor play, not formal writing drills"],"answer":3,"explanation":"NCF-FS 2022 stresses oral language, storytelling, print exposure and emergent writing through play for ages 3-6, not formal writing drills. Hiding all print is the opposite extreme and wrong too.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs","questionHi":"आँगनवाड़ी-सह-पूर्व-विद्यालय में चार वर्ष के बच्चों के अभिभावक वर्णमाला पर अनुरेखण और लिखने के दैनिक अभ्यास-पत्र चाहते हैं। आधारभूत चरण के लिए NCF 2022 के अनुसार, शिक्षिका को क्या समझाना और करना चाहिए?","optionsHi":["सहमत होना और तुरंत दैनिक हस्तलिपि-अभ्यास शुरू करना, क्योंकि प्रारंभिक साफ़ लिखावट के बारे में व्यापक रूप से कहा जाता है कि वह विद्यालय में बाद की सफलता का पूर्वानुमान देती है","बच्चों के छह वर्ष का होने तक उन्हें कोई मुद्रित सामग्री बिल्कुल न दिखाने से इनकार करना, क्योंकि प्रारंभिक मुद्रित सामग्री का संपर्क तनाव और भ्रम पैदा करता है","अभिभावकों को संतुष्ट रखने के लिए दैनिक वर्णमाला-अनुरेखण से सहमत होना, जबकि खेल-आधारित गतिविधियाँ अलग से जारी रखना","समझाना कि इस आयु में ध्यान बातचीत, कहानियों, गीतों, चित्रकारी, उदीयमान लेखन और सूक्ष्म-गामक खेल पर है, औपचारिक लेखन-अभ्यास पर नहीं"],"explanationHi":"NCF-FS 2022 3-6 वर्ष की आयु के लिए खेल के माध्यम से मौखिक भाषा, कहानी सुनाना, मुद्रित सामग्री का संपर्क और उदीयमान लेखन पर ज़ोर देता है, औपचारिक लेखन-अभ्यास पर नहीं। सारी मुद्रित सामग्री को छिपाना उलटा अतिवाद है और वह भी गलत है।"},
  {"id":"cdp-pedagogy-subjects-351","question":"A Class 3 child works out 503 − 178 and gets 335. Her working shows: ones, 13 − 8 = 5; the 0 in the tens place crossed out and written as 10, then 10 − 7 = 3; hundreds, 4 − 1 = 3. What is the precise misconception?","options":["She subtracts the smaller digit from the larger digit in each column, whatever its position","She does not yet know the subtraction facts 13 − 8 and 10 − 7, so each column result is a guess","She turns the 0 tens into 10 tens, forgetting that one ten went to the ones, so it should be 9","She borrows from the hundreds twice, once for the ones and again for the tens, losing one hundred"],"answer":2,"explanation":"503 regroups as 4 hundreds, 9 tens and 13 ones, giving 325. Writing the tens as 10 instead of 9 counts one ten twice, so the answer is exactly 10 too big; the facts themselves are correct.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"कक्षा 3 की एक बच्ची 503 − 178 निकालती है और 335 पाती है। उसके कार्य में दिखता है: इकाई, 13 − 8 = 5; दहाई के स्थान के 0 को काटकर 10 लिखा गया, फिर 10 − 7 = 3; सैकड़ा, 4 − 1 = 3। सटीक भ्रांत धारणा क्या है?","optionsHi":["वह हर स्तंभ में, उसकी स्थिति की परवाह किए बिना, छोटे अंक को बड़े अंक से घटाती है","वह घटाव के मूल तथ्य 13 − 8 और 10 − 7 अभी नहीं जानती, इसलिए हर स्तंभ का परिणाम अनुमान है","वह 0 दहाई को 10 दहाई में बदल देती है, यह भूलकर कि एक दहाई इकाई में चली गई, इसलिए वह 9 होना चाहिए","वह सैकड़े से दो बार उधार लेती है, एक बार इकाई के लिए और फिर दहाई के लिए, जिससे एक सैकड़ा खो जाता है"],"explanationHi":"503 का पुनर्समूहन 4 सैकड़ा, 9 दहाई और 13 इकाई के रूप में होता है, जिससे 325 मिलता है। दहाई को 9 के बजाय 10 लिखना एक दहाई को दो बार गिनता है, इसलिए उत्तर ठीक 10 अधिक है; तथ्य स्वयं सही हैं।"},
  {"id":"cdp-pedagogy-subjects-352","question":"A Class 5 child multiplies 23 × 14 in columns and writes: 23 × 4 = 92, then 23 × 1 = 23, then 92 + 23 = 115. Which diagnosis is accurate?","options":["She treats the 1 in 14 as one, not one ten, so the second partial product should be 230, not 23","She does not know the fact 3 × 4 and has carried wrongly into the tens of the first partial product","She has added the tens digits where she should have multiplied them, which shrinks the final answer","She multiplied the digits in the wrong order, which changes the product in column multiplication"],"answer":0,"explanation":"The partial product for the tens digit is 23 × 10 = 230, and 92 + 230 = 322. Her facts are correct (23 × 4 = 92); the error is about the place value of the multiplier's digit, which an area or grid model makes visible.","difficulty":"hard","source":"CTET Paper 1 · state TETs · KVS PRT","questionHi":"कक्षा 5 की एक बच्ची 23 × 14 को स्तंभों में गुणा करती है और लिखती है: 23 × 4 = 92, फिर 23 × 1 = 23, फिर 92 + 23 = 115। कौन-सा निदान सटीक है?","optionsHi":["वह 1 को, जो 14 में है, एक मानती है, एक दहाई नहीं, इसलिए दूसरा आंशिक गुणनफल 230 होना चाहिए, 23 नहीं","वह तथ्य 3 × 4 नहीं जानती और पहले आंशिक गुणनफल की दहाई में गलत हासिल लगा दिया है","उसने दहाई के अंकों को गुणा करने के बजाय जोड़ दिया है, जिससे अंतिम उत्तर छोटा हो जाता है","उसने अंकों को गलत क्रम में गुणा किया है, जिससे स्तंभ गुणन में गुणनफल बदल जाता है"],"explanationHi":"दहाई के अंक का आंशिक गुणनफल 23 × 10 = 230 है, और 92 + 230 = 322। उसके तथ्य सही हैं (23 × 4 = 92); त्रुटि गुणक के अंक के स्थानीय मान की है, जिसे क्षेत्रफल या ग्रिड मॉडल दृश्य बना देता है।"},
  {"id":"cdp-pedagogy-subjects-353","question":"A Class 4 child divides 624 by 6 using long division and writes the quotient as 14. Which explanation and follow-up are most appropriate?","options":["She does not know that 6 goes into 24 four times, so she should practise the 6 times table every day this week","She divided from right to left; insist that long division must always start from the leftmost digit","She subtracted at each step instead of dividing, so the meaning of division needs to be revised first","She skipped the 0 when 6 would not go into 2 tens; estimating 600 ÷ 6 = 100 shows 14 is far too small"],"answer":3,"explanation":"624 ÷ 6 = 104. Skipping the 0 for the tens collapses the place value of the 1. Asking for an estimate first is the strongest check, since 14 × 6 is only 84.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"कक्षा 4 की एक बच्ची 624 को 6 से लंबी भाग विधि से भाग देती है और भागफल 14 लिखती है। कौन-सी व्याख्या और अनुवर्ती कार्य सबसे उपयुक्त हैं?","optionsHi":["वह नहीं जानती कि 6, 24 में चार बार समाता है, इसलिए इस सप्ताह उसे रोज़ 6 का पहाड़ा दोहराना चाहिए","उसने दाएँ से बाएँ भाग दिया; ज़ोर दीजिए कि लंबी भाग विधि हमेशा सबसे बाएँ अंक से शुरू होनी चाहिए","उसने भाग देने के बजाय हर चरण में घटाया, इसलिए पहले भाग का अर्थ दोहराना होगा","उसने 0 छोड़ दिया जब 6, 2 दहाई में नहीं समाया; 600 ÷ 6 = 100 का अनुमान दिखाता है कि 14 बहुत छोटा है"],"explanationHi":"624 ÷ 6 = 104। दहाई के लिए 0 छोड़ देना 1 के स्थानीय मान को सिकोड़ देता है। पहले अनुमान माँगना सबसे मज़बूत जाँच है, क्योंकि 14 × 6 केवल 84 है।"},
  {"id":"cdp-pedagogy-subjects-354","question":"Asked ‘How many tens are there in 352?’, a Class 4 child answers ‘5’. Which interpretation and next step are most appropriate?","options":["The child is right; the tens digit is the only correct answer to this question, so no follow-up is needed at all","She reads only the tens digit; 352 has 35 tens in all, so let her unbundle 3 hundreds into 30 tens and count","The child confuses tens with hundreds, so she should be drilled on naming the places from right to left","The child cannot count beyond 100 and should go back to counting objects one by one before place value"],"answer":1,"explanation":"‘How many tens in 352’ asks for the total number of tens, which is 35 (with 2 ones left). Seeing that 1 hundred = 10 tens by regrouping bundles builds the flexible place value that later supports division.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · NVS PRT","questionHi":"‘352 में कितनी दहाइयाँ हैं?’ पूछे जाने पर कक्षा 4 की एक बच्ची उत्तर देती है ‘5’। कौन-सी व्याख्या और अगला कदम सबसे उपयुक्त हैं?","optionsHi":["बच्ची सही है; इस प्रश्न का केवल दहाई का अंक ही सही उत्तर है, इसलिए किसी अनुवर्ती कार्य की आवश्यकता नहीं","वह केवल दहाई का अंक पढ़ती है; 352 में कुल 35 दहाई हैं, इसलिए उसे 3 सैकड़ों को 30 दहाई में खोलने और गिनने दें","बच्ची दहाई को सैकड़े से मिला देती है, इसलिए उसे दाएँ से बाएँ स्थानों के नाम बोलने का अभ्यास कराना चाहिए","बच्ची 100 से आगे गिन नहीं सकती और स्थानीय मान से पहले वस्तुओं को एक-एक करके गिनने पर लौटना चाहिए"],"explanationHi":"‘352 में कितनी दहाइयाँ’ दहाइयों की कुल संख्या पूछता है, जो 35 है (2 इकाई बची रहती हैं)। बंडलों को पुनर्समूहित करके देखना कि 1 सैकड़ा = 10 दहाई है, वह लचीला स्थानीय मान निर्मित करता है जो बाद में भाग को सहारा देता है।"},
  {"id":"cdp-pedagogy-subjects-355","question":"A Class 1 child correctly says ‘sixteen’ when shown 16 counters but writes the number as 61. The most likely reason is that:","options":["the child has a visual-perception disorder that reverses digits and should be referred for assessment","the child has not yet memorised the written numerals beyond 10, so she writes any two digits she knows","in ‘sixteen’ the ones word comes first, so she writes the digits in the order she hears them","the child is used to writing from right to left, as in the Urdu script she sees at home"],"answer":2,"explanation":"Teen number names are irregular: ‘six-teen’ says the ones before the ten. Children who write what they hear produce 61; bundling one ten and six loose sticks shows that the ten is written first.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"16 गिनतियाँ दिखाने पर कक्षा 1 की एक बच्ची अंग्रेज़ी में सही ‘sixteen’ बोलती है, लेकिन संख्या को 61 लिखती है। सबसे संभावित कारण यह है कि:","optionsHi":["बच्ची को दृश्य-प्रत्यक्षण विकार है जो अंकों को उलट देता है और आकलन के लिए भेजा जाना चाहिए","बच्ची ने 10 से आगे के लिखित अंक अभी याद नहीं किए हैं, इसलिए वह कोई भी दो अंक लिख देती है जो वह जानती है","अंग्रेज़ी शब्द ‘sixteen’ में इकाई (six) पहले बोली जाती है, इसलिए वह अंक उसी क्रम में लिखती है जिसमें सुनती है","बच्ची दाएँ से बाएँ लिखने की आदी है, जैसा उर्दू लिपि में होता है जो वह घर पर देखती है"],"explanationHi":"अंग्रेज़ी में 13 से 19 तक के संख्या-नाम अनियमित हैं: ‘six-teen’ में इकाई पहले बोली जाती है, दहाई बाद में। जो बच्चे सुना हुआ क्रम लिखते हैं, वे 61 लिख देते हैं; एक दहाई का बंडल और छह खुली तीलियाँ दिखाने से समझ आता है कि दहाई पहले लिखी जाती है।"},
  {"id":"cdp-pedagogy-subjects-356","question":"To find 3 + 8, a Class 1 child counts out three fingers, then eight fingers, and counts all of them from one. Which step by the teacher is most likely to move her to a more efficient strategy?","options":["Hide eight counters under a cloth, say ‘there are eight here’, and ask her to count on using the three she can see","Give her flash cards so that she memorises all the addition facts up to 20 and no longer needs to count at all","Tell her that counting on fingers is babyish and must stop, so that she is pushed to use mental methods instead","Give her the same kind of sum with much larger numbers, so that counting all becomes too slow and she gives it up herself"],"answer":0,"explanation":"Hiding the larger set pushes the child to start from 8 and count on (‘nine, ten, eleven’), the natural next stage after counting all. Banning fingers or drilling facts skips the understanding that makes counting on possible.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"3 + 8 निकालने के लिए कक्षा 1 की एक बच्ची तीन उँगलियाँ गिनकर निकालती है, फिर आठ उँगलियाँ, और उन सबको एक से गिनती है। शिक्षक का कौन-सा कदम उसे अधिक कुशल रणनीति की ओर ले जाने की सबसे अधिक संभावना रखता है?","optionsHi":["आठ गिनतियाँ कपड़े के नीचे छिपाना, कहना ‘यहाँ आठ हैं’, और उससे अपने दिखाई देने वाले तीन के सहारे आगे गिनने को कहना","उसे फ़्लैश कार्ड देना ताकि वह 20 तक के सभी जोड़ के तथ्य याद कर ले और उसे गिनने की आवश्यकता ही न रहे","उसे बताना कि उँगलियों पर गिनना बचकाना है और बंद होना चाहिए, ताकि वह मानसिक विधियों का उपयोग करने को विवश हो","उसे उसी प्रकार का जोड़ कहीं बड़ी संख्याओं के साथ देना, ताकि सब गिनना बहुत धीमा हो जाए और वह उसे स्वयं छोड़ दे"],"explanationHi":"बड़े समूह को छिपाने से बच्ची 8 से शुरू करके आगे गिनने (‘नौ, दस, ग्यारह’) को प्रेरित होती है, जो सब गिनने के बाद का स्वाभाविक चरण है। उँगलियों पर रोक लगाना या तथ्य रटाना उस समझ को छोड़ देता है जो आगे गिनना संभव बनाती है।"},
  {"id":"cdp-pedagogy-subjects-357","question":"A teacher flashes a card with five dots for two seconds. A child says, ‘Five, because I saw three on top and two below.’ This shows:","options":["perceptual subitising, recognising a small set at a glance without any parts","rote counting, saying number names in order","one-to-one correspondence between dots and number names","conceptual subitising, seeing small parts at once and combining them"],"answer":3,"explanation":"The child saw 3 and 2 instantly and put them together: conceptual subitising. Perceptual subitising is seeing the whole small set at once; there was no time to count one by one.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"एक शिक्षक पाँच बिंदुओं वाला कार्ड दो सेकंड के लिए दिखाता है। एक बच्चा कहता है, ‘पाँच, क्योंकि मैंने ऊपर तीन और नीचे दो देखे।’ यह दर्शाता है:","optionsHi":["अवबोधात्मक तात्क्षणिक संख्या-बोध (परसेप्चुअल सबिटाइज़िंग), बिना भागों के एक नज़र में छोटे समूह को पहचानना","रटकर गिनना, संख्या-नाम क्रम से बोलना","बिंदुओं और संख्या-नामों के बीच एक-से-एक संगतता","संप्रत्ययात्मक तात्क्षणिक संख्या-बोध (कॉन्सेप्चुअल सबिटाइज़िंग), छोटे भागों को एक साथ देखना और उन्हें जोड़ना"],"explanationHi":"बच्चे ने 3 और 2 को तुरंत देखा और उन्हें जोड़ा: संप्रत्ययात्मक तात्क्षणिक संख्या-बोध। अवबोधात्मक तात्क्षणिक संख्या-बोध पूरे छोटे समूह को एक साथ देखना है; यहाँ एक-एक करके गिनने का समय नहीं था।"},
  {"id":"cdp-pedagogy-subjects-358","question":"Two rows of seven bottle caps are laid out one-to-one. When the teacher spreads one row out, a five-year-old says that row now has more. What is the most appropriate conclusion?","options":["The child cannot yet count to seven correctly and needs daily counting drills before any number work","She judges quantity by length and has not yet conserved number; let her re-match and re-count after each change","The child shows early signs of dyscalculia and should be referred to a specialist for a full assessment","The child should be told the rule ‘spreading never changes the number’ and repeat it aloud until she can remember it"],"answer":1,"explanation":"Judging number by the space a row takes up is typical before conservation (Piaget). Re-matching and re-counting the same caps lets her build the idea that number stays the same; telling her a rule does not.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"सात-सात बोतल-ढक्कनों की दो पंक्तियाँ एक-से-एक रखी गई हैं। जब शिक्षक एक पंक्ति को फैला देता है, तो पाँच वर्ष की एक बच्ची कहती है कि अब उस पंक्ति में अधिक हैं। सबसे उपयुक्त निष्कर्ष क्या है?","optionsHi":["बच्ची अभी सात तक सही नहीं गिन सकती और किसी भी संख्या-कार्य से पहले उसे दैनिक गिनती अभ्यास चाहिए","वह मात्रा का निर्णय लंबाई से करती है और उसने अभी संख्या का संरक्षण नहीं सीखा है; हर परिवर्तन के बाद उसे फिर से मिलाने और गिनने दें","बच्ची में डिस्कैल्कुलिया के शुरुआती संकेत हैं और पूर्ण आकलन के लिए उसे विशेषज्ञ के पास भेजना चाहिए","बच्ची को नियम ‘फैलाने से संख्या कभी नहीं बदलती’ बताना चाहिए और उससे तब तक ज़ोर से दोहरवाना चाहिए जब तक वह उसे याद न कर ले"],"explanationHi":"किसी पंक्ति द्वारा घेरी गई जगह से संख्या का निर्णय करना संरक्षण (पियाजे) से पहले की अवस्था में सामान्य है। उन्हीं ढक्कनों को फिर से मिलाने और गिनने से वह यह विचार बनाती है कि संख्या वही रहती है; नियम बताने से नहीं।"},
  {"id":"cdp-pedagogy-subjects-359","question":"For 8 + 4 = ☐ + 5, most children in a Class 2 class write 12 in the box and a few write 17. What does this most likely show, and what helps?","options":["They cannot add 8 and 4 reliably, so they should be given more practice with single-digit addition facts","They did not read the whole number sentence, so they should be asked to read every question slowly and carefully at least twice","They read ‘=’ as ‘the answer comes next’, not ‘has the same value as’; use a pan balance and true/false sentences","They have not yet learnt subtraction, so they cannot work out a missing addend on the right-hand side"],"answer":2,"explanation":"Both 12 and 17 come from an operational view of ‘=’ (calculate and write the result). Balancing both sides on a pan balance and judging sentences like 7 + 2 = 6 + 3 builds the relational meaning needed for algebra.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"8 + 4 = ☐ + 5 के लिए कक्षा 2 की कक्षा के अधिकांश बच्चे खाने में 12 लिखते हैं और कुछ 17 लिखते हैं। यह सबसे अधिक संभावना से क्या दर्शाता है, और क्या मदद करता है?","optionsHi":["वे 8 और 4 को विश्वसनीय ढंग से नहीं जोड़ सकते, इसलिए उन्हें एक अंक के जोड़ के तथ्यों का और अभ्यास दिया जाना चाहिए","उन्होंने पूरा संख्या-वाक्य नहीं पढ़ा, इसलिए उनसे हर प्रश्न को धीरे और ध्यान से कम से कम दो बार पढ़ने को कहना चाहिए","वे ‘=’ को ‘अगला उत्तर आता है’ पढ़ते हैं, ‘के बराबर मान’ नहीं; पलड़े वाली तुला और सत्य/असत्य वाक्यों का उपयोग करें","उन्होंने अभी घटाव नहीं सीखा है, इसलिए वे दाएँ पक्ष का लुप्त योज्य नहीं निकाल सकते"],"explanationHi":"12 और 17 दोनों ‘=’ के संक्रियात्मक दृष्टिकोण (गणना करो और परिणाम लिखो) से आते हैं। पलड़े वाली तुला पर दोनों पक्षों को संतुलित करना और 7 + 2 = 6 + 3 जैसे वाक्यों का निर्णय करना बीजगणित के लिए आवश्यक संबंधात्मक अर्थ निर्मित करता है।"},
  {"id":"cdp-pedagogy-subjects-360","question":"A teacher wants true/false number sentences that best test whether children understand ‘=’ as a relation. Which set should she choose?","options":["5 + 3 = 8; 9 + 1 = 10; 6 + 2 = 8; 4 + 4 = 8; 7 + 1 = 9","8 + 0 = 8; 0 + 8 = 8; 8 − 0 = 8; 8 + 1 = 9; 9 − 1 = 7","12 − 4 = 8; 15 − 7 = 8; 10 − 2 = 8; 11 − 3 = 8; 9 − 2 = 6","7 + 2 = 9; 9 = 7 + 2; 7 + 2 = 6 + 3; 7 + 2 = 9 + 4"],"answer":3,"explanation":"Only the last set breaks the ‘sum on the left, answer on the right’ pattern: 9 = 7 + 2 and 7 + 2 = 6 + 3 are true, and 7 + 2 = 9 + 4 is false. Children who see ‘=’ as ‘write the answer’ wrongly judge these.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"एक शिक्षिका ऐसे सत्य/असत्य संख्या-वाक्य चाहती है जो यह सबसे अच्छी तरह जाँचें कि बच्चे ‘=’ को संबंध के रूप में समझते हैं या नहीं। उसे कौन-सा समूह चुनना चाहिए?","optionsHi":["5 + 3 = 8; 9 + 1 = 10; 6 + 2 = 8; 4 + 4 = 8; 7 + 1 = 9","8 + 0 = 8; 0 + 8 = 8; 8 − 0 = 8; 8 + 1 = 9; 9 − 1 = 7","12 − 4 = 8; 15 − 7 = 8; 10 − 2 = 8; 11 − 3 = 8; 9 − 2 = 6","7 + 2 = 9; 9 = 7 + 2; 7 + 2 = 6 + 3; 7 + 2 = 9 + 4"],"explanationHi":"केवल अंतिम समूह ‘बाएँ योग, दाएँ उत्तर’ के पैटर्न को तोड़ता है: 9 = 7 + 2 और 7 + 2 = 6 + 3 सत्य हैं, और 7 + 2 = 9 + 4 असत्य है। जो बच्चे ‘=’ को ‘उत्तर लिखो’ मानते हैं, वे इनका गलत निर्णय करते हैं।"},
  {"id":"cdp-pedagogy-subjects-361","question":"On a number line a child does 3 + 4 by putting her finger on 3, saying ‘one’, then ‘two, three, four’ on 4, 5 and 6, and answers 6. What is she missing?","options":["That we count the jumps (spaces) from the starting point, not the marks","The basic fact 3 + 4 = 7, which she should already have memorised by now","That addition on a number line always means moving to the left","That the number line must start at 1, not 0, for counting to work"],"answer":0,"explanation":"She counted the starting point as a step, so she made only three jumps. A number line models numbers as distances from zero, so 3 + 4 means four jumps starting from 3, landing on 7.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs","questionHi":"संख्या-रेखा पर एक बच्ची 3 + 4 इस प्रकार करती है कि 3 पर उँगली रखती है, ‘एक’ कहती है, फिर 4, 5 और 6 पर ‘दो, तीन, चार’ कहती है, और उत्तर 6 बताती है। उसे क्या समझ नहीं आ रहा?","optionsHi":["कि हम प्रारंभिक बिंदु से कूदों (अंतरालों) को गिनते हैं, निशानों को नहीं","मूल तथ्य 3 + 4 = 7, जो उसे अब तक याद हो जाना चाहिए था","कि संख्या-रेखा पर जोड़ का अर्थ हमेशा बाईं ओर बढ़ना होता है","कि गिनने के लिए संख्या-रेखा 1 से शुरू होनी चाहिए, 0 से नहीं"],"explanationHi":"उसने प्रारंभिक बिंदु को एक कदम के रूप में गिन लिया, इसलिए उसने केवल तीन कूदें लगाईं। संख्या-रेखा संख्याओं को शून्य से दूरी के रूप में निरूपित करती है, इसलिए 3 + 4 का अर्थ 3 से शुरू करके चार कूदें हैं, जो 7 पर पहुँचती हैं।"},
  {"id":"cdp-pedagogy-subjects-362","question":"A Class 5 child writes 49 × 21 = 1229. Which response by the teacher best builds number sense?","options":["Mark it wrong and ask her to redo it carefully with the standard column method in her notebook","Ask her to estimate 50 × 20, judge if 1229 is reasonable, then find where the extra came from","Give her a calculator so that she can check every answer herself before handing in her work","Tell her the correct answer is 1029 and move on quickly to the next sum in the exercise"],"answer":1,"explanation":"49 × 21 = 1029, close to the estimate 50 × 20 = 1000. Asking the child to compare her result with an estimate teaches her to check reasonableness herself, which redoing or being told the answer does not.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक बच्ची 49 × 21 = 1229 लिखती है। शिक्षक की कौन-सी प्रतिक्रिया संख्या-बोध का सबसे अच्छा निर्माण करती है?","optionsHi":["इसे गलत चिह्नित करना और उससे अपनी कॉपी में मानक स्तंभ विधि से ध्यानपूर्वक फिर से करने को कहना","उससे 50 × 20 का अनुमान लगाने, यह आँकने कि 1229 तर्कसंगत है या नहीं, और फिर खोजने को कहना कि अतिरिक्त कहाँ से आया","उसे कैलकुलेटर देना ताकि वह अपना काम जमा करने से पहले हर उत्तर स्वयं जाँच सके","उसे बताना कि सही उत्तर 1029 है और अभ्यास के अगले प्रश्न पर जल्दी आगे बढ़ जाना"],"explanationHi":"49 × 21 = 1029, जो अनुमान 50 × 20 = 1000 के निकट है। बच्ची से उसके परिणाम की अनुमान से तुलना करवाना उसे तर्कसंगतता स्वयं जाँचना सिखाता है, जो दोबारा करने या उत्तर बता देने से नहीं होता।"},
  {"id":"cdp-pedagogy-subjects-363","question":"A Class 4 child who helps at her family's vegetable stall works out the cost of 3 kg at ₹35 a kg in her head (‘35, 70, 105’) but gets 35 × 3 wrong in her notebook. What should the teacher conclude?","options":["The written algorithm does not suit her, so she should be excused from it and allowed to use mental methods only","She has a memory problem that shows only in school, where she cannot recall the steps of the method","Her informal, context-based strategy is real mathematics, and the written method should be linked to it","Market mathematics is unreliable and informal, and should be discouraged in class in favour of the textbook"],"answer":2,"explanation":"Studies of street mathematics (Nunes and Carraher) show children reason well in real contexts. The teacher should build on this repeated-addition reasoning to give meaning to the written method, not dismiss either.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कक्षा 4 की एक बच्ची, जो अपने परिवार की सब्ज़ी की दुकान पर हाथ बँटाती है, ₹35 प्रति किलो के हिसाब से 3 किलो की कीमत मन में निकाल लेती है (‘35, 70, 105’), लेकिन अपनी कॉपी में 35 × 3 गलत कर देती है। शिक्षक को क्या निष्कर्ष निकालना चाहिए?","optionsHi":["लिखित एल्गोरिदम उसके अनुकूल नहीं है, इसलिए उसे इससे छूट देनी चाहिए और केवल मानसिक विधियों की अनुमति देनी चाहिए","उसे स्मृति की समस्या है जो केवल विद्यालय में दिखती है, जहाँ वह विधि के चरण याद नहीं कर पाती","उसकी अनौपचारिक, संदर्भ-आधारित रणनीति वास्तविक गणित है, और लिखित विधि को उससे जोड़ा जाना चाहिए","बाज़ार का गणित अविश्वसनीय और अनौपचारिक है, और कक्षा में पाठ्यपुस्तक के पक्ष में उसे हतोत्साहित करना चाहिए"],"explanationHi":"गली-बाज़ार के गणित के अध्ययन (नून्स और कैराहर) दिखाते हैं कि बच्चे वास्तविक संदर्भों में अच्छा तर्क करते हैं। शिक्षक को इस बार-बार जोड़ने के तर्क पर निर्माण करके लिखित विधि को अर्थ देना चाहिए, किसी को खारिज नहीं करना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-364","question":"Which of these statements about teaching place value are correct? I. Bundles of sticks help because each bundle keeps ten visible as one unit. II. A bead on the tens rod of an abacus looks like a bead on the ones rod, so the abacus is a more abstract model than bundles. III. Zero is best taught as ‘nothing’, so children can ignore it when reading numbers. IV. Writing numbers in expanded form (300 + 50 + 2) helps children see the value of each digit.","options":["I and III only","II and IV only","I, III and IV","I, II and IV"],"answer":3,"explanation":"Bundles are proportional models (a ten is ten times as big); an abacus is non-proportional, so it should come later. Zero is a place holder that changes value (405 vs 45), so III is wrong.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"स्थानीय मान पढ़ाने के बारे में इनमें से कौन-से कथन सही हैं? I. तीलियों के बंडल सहायक हैं क्योंकि हर बंडल दस को एक इकाई के रूप में दृश्य रखता है। II. अबेकस की दहाई वाली छड़ पर मनका इकाई वाली छड़ के मनके जैसा दिखता है, इसलिए अबेकस बंडलों से अधिक अमूर्त मॉडल है। III. शून्य को सबसे अच्छा ‘कुछ नहीं’ के रूप में पढ़ाया जाता है, ताकि बच्चे संख्याएँ पढ़ते समय उसे अनदेखा कर सकें। IV. संख्याओं को विस्तारित रूप (300 + 50 + 2) में लिखना बच्चों को प्रत्येक अंक का मान देखने में मदद करता है।","optionsHi":["केवल I और III","केवल II और IV","I, III और IV","I, II और IV"],"explanationHi":"बंडल समानुपाती मॉडल हैं (दस, एक से दस गुना बड़ा है); अबेकस असमानुपाती है, इसलिए वह बाद में आना चाहिए। शून्य एक स्थान-धारक है जो मान बदलता है (405 बनाम 45), इसलिए III गलत है।"},
  {"id":"cdp-pedagogy-subjects-365","question":"Which of these is a non-proportional model of place value, best used only after children are confident with proportional ones?","options":["₹10 notes and ₹1 coins","A bundle of ten sticks tied with a rubber band","A base-ten rod made of ten unit cubes joined together","A string of ten beads with each bead visible"],"answer":0,"explanation":"A ₹10 note is not ten times the size of a ₹1 coin; its value is given by agreement, just like a digit's place. Bundles, rods and bead strings physically contain ten ones, so they are proportional.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"इनमें से कौन-सा स्थानीय मान का असमानुपाती मॉडल है, जिसे बच्चों के समानुपाती मॉडलों में आश्वस्त हो जाने के बाद ही उपयोग करना सबसे अच्छा है?","optionsHi":["₹10 के नोट और ₹1 के सिक्के","रबर-बैंड से बँधा दस तीलियों का बंडल","दस इकाई-घनों को जोड़कर बनी आधार-दस छड़","प्रत्येक मनके के दिखाई देने वाली दस मनकों की माला"],"explanationHi":"₹10 का नोट ₹1 के सिक्के से दस गुना बड़ा नहीं होता; उसका मान सहमति से तय होता है, ठीक अंक के स्थान की तरह। बंडल, छड़ और मनकों की मालाएँ भौतिक रूप से दस इकाइयाँ समाए होती हैं, इसलिए वे समानुपाती हैं।"},
  {"id":"cdp-pedagogy-subjects-366","question":"A Class 3 child works out 63 − 28 like this: ‘60 − 20 = 40. 3 − 8 is five less. 40 − 5 = 35.’ The teacher should:","options":["mark it wrong, because 3 − 8 cannot be done in Class 3 and negative ideas only confuse children","accept it as a valid partitioning strategy and ask her to explain to the class why ‘five less’ works","insist that she use borrowing instead, since it is the standard method expected in the final examination","tell her it gave the right answer only by luck for these numbers and will fail with other numbers"],"answer":1,"explanation":"Splitting both numbers into tens and ones is valid for any numbers: 63 − 28 = (60 − 20) + (3 − 8) = 40 − 5 = 35. Inviting her to explain respects her reasoning and helps classmates think flexibly.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 3 की एक बच्ची 63 − 28 इस प्रकार निकालती है: ‘60 − 20 = 40। 3 − 8 पाँच कम है। 40 − 5 = 35।’ शिक्षक को चाहिए कि:","optionsHi":["इसे गलत चिह्नित करे, क्योंकि 3 − 8 कक्षा 3 में नहीं किया जा सकता और ऋणात्मक विचार बच्चों को केवल भ्रमित करते हैं","इसे वैध विभाजन रणनीति के रूप में स्वीकार करे और उससे कक्षा को समझाने को कहे कि ‘पाँच कम’ क्यों काम करता है","ज़ोर दे कि वह उधार लेने की विधि का उपयोग करे, क्योंकि अंतिम परीक्षा में मानक विधि ही अपेक्षित है","उसे बताए कि इन संख्याओं के लिए यह केवल संयोग से सही उत्तर दे गया और अन्य संख्याओं के साथ असफल होगा"],"explanationHi":"दोनों संख्याओं को दहाई और इकाई में तोड़ना किसी भी संख्या के लिए वैध है: 63 − 28 = (60 − 20) + (3 − 8) = 40 − 5 = 35। उसे समझाने के लिए आमंत्रित करना उसके तर्क का सम्मान करता है और सहपाठियों को लचीले ढंग से सोचने में मदद करता है।"},
  {"id":"cdp-pedagogy-subjects-367","question":"Which situation best models 4 × 6 so that children can also see why 4 × 6 = 6 × 4?","options":["Four children each get six sweets, making twenty-four sweets in all","A ribbon 6 m long is cut into 4 equal pieces of the same length","Chairs set in 4 rows of 6, which can also be seen as 6 columns of 4","The price of a pen rises from ₹6 to ₹24 after a few years"],"answer":2,"explanation":"An array can be read by rows or by columns, so the same 24 chairs show both 4 × 6 and 6 × 4. Equal groups (four children with six sweets) do not show commutativity at a glance.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कौन-सी स्थिति 4 × 6 को इस प्रकार निरूपित करती है कि बच्चे यह भी देख सकें कि 4 × 6 = 6 × 4 क्यों है?","optionsHi":["चार बच्चों को छह-छह मिठाइयाँ मिलती हैं, जिससे कुल चौबीस मिठाइयाँ होती हैं","6 m लंबे फ़ीते को 4 बराबर, समान लंबाई के टुकड़ों में काटा जाता है","कुर्सियाँ 4 पंक्तियों में लगी हैं, हर पंक्ति में 6, जिन्हें 6 स्तंभों के रूप में भी देखा जा सकता है, हर स्तंभ में 4","कलम की कीमत कुछ वर्षों बाद ₹6 से बढ़कर ₹24 हो जाती है"],"explanationHi":"किसी सारणी (ऐरे) को पंक्तियों या स्तंभों से पढ़ा जा सकता है, इसलिए वही 24 कुर्सियाँ 4 × 6 और 6 × 4 दोनों दिखाती हैं। समान समूह (छह मिठाइयों वाले चार बच्चे) एक नज़र में क्रमविनिमेयता नहीं दिखाते।"},
  {"id":"cdp-pedagogy-subjects-368","question":"A Class 5 child says 5 ÷ 0 = 0 ‘because anything with zero is zero’. Which response best helps her make sense of it?","options":["Ask her to learn the rule ‘division by zero is not defined’ and repeat it until it finally sticks","Point out that 5 × 0 = 0, so her answer 5 ÷ 0 = 0 fits the related multiplication fact","Tell her the answer is 5, because dividing by nothing means nothing is taken away from 5","Ask: ‘What number times 0 gives 5?’ and ‘How many groups of 0 can you make from 5 sweets?’"],"answer":3,"explanation":"Linking division to multiplication shows no number works, since any number × 0 is 0, not 5; so 5 ÷ 0 has no answer. Option B uses the same faulty link, and option C confuses division with subtraction.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कक्षा 5 की एक बच्ची कहती है कि 5 ÷ 0 = 0 ‘क्योंकि शून्य वाली कोई भी चीज़ शून्य होती है’। कौन-सी प्रतिक्रिया उसे इसे समझने में सबसे अच्छी तरह सहायता करती है?","optionsHi":["उससे नियम ‘शून्य से भाग परिभाषित नहीं है’ सीखने को कहना और उसे तब तक दोहराना जब तक वह पक्का न हो जाए","यह बताना कि 5 × 0 = 0, इसलिए उसका उत्तर 5 ÷ 0 = 0 संबंधित गुणन-तथ्य से मेल खाता है","उसे बताना कि उत्तर 5 है, क्योंकि कुछ नहीं से भाग देने का अर्थ है कि 5 में से कुछ नहीं निकाला गया","पूछना: ‘कौन-सी संख्या गुणा 0 करने पर 5 देती है?’ और ‘0 वाले कितने समूह 5 मिठाइयों से बन सकते हैं?’"],"explanationHi":"भाग को गुणा से जोड़ने पर दिखता है कि कोई संख्या काम नहीं करती, क्योंकि कोई भी संख्या × 0 शून्य होती है, 5 नहीं; इसलिए 5 ÷ 0 का कोई उत्तर नहीं है। विकल्प 2 उसी दोषपूर्ण संबंध का उपयोग करता है, और विकल्प 3 भाग को घटाव से मिला देता है।"},
  {"id":"cdp-pedagogy-subjects-369","question":"‘A school bus holds 40 children. 130 children are going on a trip. How many buses are needed?’ A child writes ‘130 ÷ 40 = 3 remainder 10, so 3 buses.’ What is the correct diagnosis?","options":["The division is right, but she did not interpret the remainder in context; 4 buses are needed","She made an error in the division itself, since 130 ÷ 40 does not really leave a remainder of 10","She should have multiplied 130 by 40 instead of dividing, since buses carry many children","The question is ambiguous, so 3 buses is also acceptable if the extra children squeeze in"],"answer":0,"explanation":"130 ÷ 40 = 3 remainder 10, and the 10 children left over still need a bus. Children need practice deciding whether a remainder is dropped, rounded up or written as a fraction, depending on the context.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"‘एक विद्यालय की बस में 40 बच्चे बैठते हैं। 130 बच्चे सैर पर जा रहे हैं। कितनी बसों की आवश्यकता है?’ एक बच्ची लिखती है ‘130 ÷ 40 = 3 शेष 10, इसलिए 3 बसें।’ सही निदान क्या है?","optionsHi":["भाग सही है, लेकिन उसने शेषफल की व्याख्या संदर्भ में नहीं की; 4 बसों की आवश्यकता है","उसने भाग में ही त्रुटि की, क्योंकि 130 ÷ 40 वास्तव में 10 शेष नहीं छोड़ता","उसे भाग देने के बजाय 130 को 40 से गुणा करना चाहिए था, क्योंकि बसें कई बच्चों को ले जाती हैं","प्रश्न अस्पष्ट है, इसलिए 3 बसें भी स्वीकार्य हैं यदि अतिरिक्त बच्चे ठुँसकर बैठ जाएँ"],"explanationHi":"130 ÷ 40 = 3 शेष 10, और बचे हुए 10 बच्चों को भी बस चाहिए। बच्चों को यह तय करने का अभ्यास चाहिए कि संदर्भ के अनुसार शेषफल को छोड़ा जाए, ऊपर पूर्णांकित किया जाए या भिन्न के रूप में लिखा जाए।"},
  {"id":"cdp-pedagogy-subjects-370","question":"A Class 3 child says 0 is neither even nor odd ‘because it is nothing’. What is the best response?","options":["Tell her firmly that 0 is even, because the textbook and the teacher's guide both say so, and that settles it","Ask whether 0 fits the even–odd pattern on the number line and whether 0 sweets can be shared equally by two","Accept her answer, since 0 is a special number that does not behave like the other whole numbers in any way","Agree that even and odd apply only to counting numbers, so 0 is neither, and move on to the next topic"],"answer":1,"explanation":"0 sits between the odd numbers −1 and 1 in the alternating pattern and can be split into two equal groups of 0, so it is even. Letting her test the definition builds reasoning instead of relying on authority.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 3 की एक बच्ची कहती है कि 0 न सम है न विषम ‘क्योंकि वह कुछ नहीं है’। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["उसे दृढ़ता से बताना कि 0 सम है, क्योंकि पाठ्यपुस्तक और शिक्षक-पुस्तिका दोनों यही कहती हैं, और बात खत्म","पूछना कि क्या 0 संख्या-रेखा पर सम–विषम के पैटर्न में बैठता है और क्या 0 मिठाइयों को दो में बराबर बाँटा जा सकता है","उसका उत्तर स्वीकार करना, क्योंकि 0 एक विशेष संख्या है जो किसी भी तरह अन्य पूर्ण संख्याओं जैसा व्यवहार नहीं करती","सहमत होना कि सम और विषम केवल गिनती की संख्याओं पर लागू होते हैं, इसलिए 0 न सम है न विषम, और अगले विषय पर बढ़ जाना"],"explanationHi":"0 बारी-बारी वाले पैटर्न में विषम संख्याओं −1 और 1 के बीच आता है और 0 के दो बराबर समूहों में बाँटा जा सकता है, इसलिए वह सम है। उसे परिभाषा परखने देना सत्ता पर निर्भर रहने के बजाय तर्क निर्मित करता है।"},
  {"id":"cdp-pedagogy-subjects-371","question":"A teacher uses a 100-bead string (ganit mala) whose colour changes after every ten beads. What is its main advantage?","options":["It makes rote counting from 1 to 100 faster, since children can slide the beads quickly","It removes the need for written numerals, since children can show every number with beads","It lets children see and move in tens and ones, e.g. 38 + 10 by jumping one colour block","It helps children learn multiplication tables by heart by counting the beads in each block"],"answer":2,"explanation":"Colour blocks of ten make the structure of numbers visible, so children can count on in tens and link counting with place value and mental addition.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · NVS PRT","questionHi":"एक शिक्षक 100 मनकों की माला (गणित माला) का उपयोग करता है, जिसका रंग हर दस मनकों के बाद बदलता है। इसका मुख्य लाभ क्या है?","optionsHi":["यह 1 से 100 तक रटकर गिनने को तेज़ बनाती है, क्योंकि बच्चे मनकों को तेज़ी से सरका सकते हैं","यह लिखित अंकों की आवश्यकता को समाप्त कर देती है, क्योंकि बच्चे हर संख्या को मनकों से दिखा सकते हैं","यह बच्चों को दहाई और इकाई में देखने और चलने देती है, जैसे एक रंग-खंड कूदकर 38 + 10","यह प्रत्येक खंड के मनके गिनकर बच्चों को पहाड़े कंठस्थ करने में मदद करती है"],"explanationHi":"दस-दस के रंगीन खंड संख्याओं की संरचना को दृश्य बनाते हैं, इसलिए बच्चे दहाई में आगे गिन सकते हैं और गिनती को स्थानीय मान तथा मानसिक जोड़ से जोड़ सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-372","question":"In a ‘number talk’ the teacher writes 25 × 4. Children share 25 + 25 + 25 + 25, ‘four quarters make 100’, and 20 × 4 + 5 × 4. What is the teacher's main role?","options":["Pick the quickest strategy and ask everyone to use it from now on, for the sake of efficiency","Correct wrong answers at once and move on, so that no child is left holding on to a wrong method","Write only the correct answers on the board, so that wrong strategies do not confuse others","Record each strategy, ask children to explain a classmate's method, and compare the strategies"],"answer":3,"explanation":"Number talks build flexible mental strategies through discussion. The teacher records ideas, including wrong ones to be examined, and gets children to explain and compare, rather than imposing one method.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"एक ‘संख्या-वार्ता’ (नंबर टॉक) में शिक्षक 25 × 4 लिखता है। बच्चे 25 + 25 + 25 + 25, ‘चार चौथाई मिलकर 100 बनाते हैं’, और 20 × 4 + 5 × 4 साझा करते हैं। शिक्षक की मुख्य भूमिका क्या है?","optionsHi":["सबसे तेज़ रणनीति चुनना और कुशलता के लिए सभी से कहना कि वे अब से उसी का उपयोग करें","गलत उत्तरों को तुरंत सुधारना और आगे बढ़ जाना, ताकि कोई बच्चा गलत विधि पर टिका न रहे","श्यामपट्ट पर केवल सही उत्तर लिखना, ताकि गलत रणनीतियाँ दूसरों को भ्रमित न करें","हर रणनीति को दर्ज करना, बच्चों से सहपाठी की विधि समझाने को कहना, और रणनीतियों की तुलना करना"],"explanationHi":"संख्या-वार्ताएँ चर्चा के माध्यम से लचीली मानसिक रणनीतियाँ निर्मित करती हैं। शिक्षक विचारों को दर्ज करता है, जिनमें जाँचे जाने वाले गलत विचार भी शामिल हैं, और एक विधि थोपने के बजाय बच्चों से समझाने और तुलना करने को कहता है।"},
  {"id":"cdp-pedagogy-subjects-373","question":"Assertion (A): A teacher should ask ‘How did you get it?’ after both right and wrong answers in mathematics. Reason (R): A right answer can come from a faulty method, and a wrong answer can hide mostly correct reasoning.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because answers alone hide the thinking behind them, asking children to explain their method is how a teacher diagnoses understanding; R is exactly why A is good practice.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): गणित में शिक्षक को सही और गलत दोनों उत्तरों के बाद ‘तुमने यह कैसे निकाला?’ पूछना चाहिए। कारण (R): सही उत्तर दोषपूर्ण विधि से आ सकता है, और गलत उत्तर अधिकांशतः सही तर्क को छिपा सकता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"चूँकि उत्तर अकेले उनके पीछे की सोच को छिपाते हैं, बच्चों से अपनी विधि समझाने को कहना ही शिक्षक द्वारा समझ का निदान करने का तरीका है; R ही कारण है कि A अच्छा अभ्यास है।"},
  {"id":"cdp-pedagogy-subjects-374","question":"Assertion (A): Children should be taught the standard written algorithms before they are allowed to try their own methods. Reason (R): Children's own methods often reveal how well they understand place value.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Invented strategies are valuable both as learning and as a window into the child's place-value understanding, so they should come before, not after, the standard algorithm. A is false; R is true.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): बच्चों को अपनी विधियाँ आज़माने की अनुमति देने से पहले उन्हें मानक लिखित एल्गोरिदम सिखाए जाने चाहिए। कारण (R): बच्चों की अपनी विधियाँ अक्सर प्रकट करती हैं कि वे स्थानीय मान को कितनी अच्छी तरह समझते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"स्वयं गढ़ी रणनीतियाँ सीखने के रूप में भी और बच्चे की स्थानीय मान की समझ की खिड़की के रूप में भी मूल्यवान हैं, इसलिए उन्हें मानक एल्गोरिदम से बाद में नहीं, पहले आना चाहिए। A असत्य है; R सत्य है।"},
  {"id":"cdp-pedagogy-subjects-375","question":"To assess Class 4 children's understanding of multiplication rather than recall, which task is best?","options":["Write out the tables of 6 to 9 correctly within five minutes","Solve twenty sums of the type 2-digit × 1-digit without any errors","Write a story for 6 × 4, draw it, and explain why 6 × 4 = 4 × 6","Match multiplication facts with their answers in a timed quiz"],"answer":2,"explanation":"Making a story and a picture shows whether the child knows what multiplication means, and explaining commutativity shows reasoning. The other tasks test speed and memory.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 4 के बच्चों की गुणा की समझ का, स्मरण के बजाय, आकलन करने के लिए कौन-सा कार्य सबसे अच्छा है?","optionsHi":["पाँच मिनट के भीतर 6 से 9 तक के पहाड़े सही-सही लिखना","2 अंक × 1 अंक प्रकार के बीस प्रश्न बिना किसी त्रुटि के हल करना","6 × 4 के लिए कहानी लिखना, उसका चित्र बनाना, और समझाना कि 6 × 4 = 4 × 6 क्यों है","समयबद्ध प्रश्नोत्तरी में गुणन-तथ्यों को उनके उत्तरों से मिलाना"],"explanationHi":"कहानी और चित्र बनाना दिखाता है कि बच्चा जानता है कि गुणा का क्या अर्थ है, और क्रमविनिमेयता समझाना तर्क दिखाता है। अन्य कार्य गति और स्मृति की जाँच करते हैं।"},
  {"id":"cdp-pedagogy-subjects-376","question":"Riya, a Class 9 student in Patna, can state the rule for the present perfect continuous, yet in class discussion she says ‘I am waiting here since morning’. In a written grammar test with plenty of time she correctly writes ‘I have been waiting here since morning’. Which of Krashen’s hypotheses best explains this gap?","options":["Natural order hypothesis: the present perfect continuous is always acquired before the simple present continuous","Monitor hypothesis: learnt rules can edit output only when there is time, a focus on form and knowledge of the rule","Input hypothesis: she has received input at exactly the i+1 level for this structure, but only ever in its written form","Affective filter hypothesis: written tests raise her anxiety and so block the use of her acquired knowledge"],"answer":1,"explanation":"Fast speech leaves no time to consult learnt rules, so her acquired system (which still says ‘am waiting since’) shows; with time in a written test the monitor edits the sentence. Option D reverses what actually happens.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"पटना की कक्षा 9 की छात्रा रिया वर्तमान पूर्ण-निरंतर काल का नियम बता सकती है, फिर भी कक्षा-चर्चा में वह कहती है ‘I am waiting here since morning’। भरपूर समय वाले लिखित व्याकरण परीक्षण में वह सही लिखती है ‘I have been waiting here since morning’। क्रैशेन की कौन-सी परिकल्पना इस अंतर की सबसे अच्छी व्याख्या करती है?","optionsHi":["प्राकृतिक क्रम परिकल्पना: वर्तमान पूर्ण-निरंतर काल हमेशा साधारण वर्तमान निरंतर काल से पहले अर्जित होता है","निगरानी परिकल्पना: सीखे हुए नियम तभी प्रस्तुति का संपादन कर सकते हैं जब समय हो, रूप पर ध्यान हो और नियम का ज्ञान हो","निवेश परिकल्पना: उसे इस संरचना के लिए ठीक i+1 स्तर पर निवेश मिला है, लेकिन केवल उसके लिखित रूप में","भावात्मक छन्नी परिकल्पना: लिखित परीक्षाएँ उसकी चिंता बढ़ाती हैं और इसलिए उसके अर्जित ज्ञान के उपयोग को रोकती हैं"],"explanationHi":"तेज़ बोलचाल में सीखे हुए नियमों को देखने का समय नहीं रहता, इसलिए उसकी अर्जित प्रणाली (जो अब भी ‘am waiting since’ कहती है) दिखती है; लिखित परीक्षा में समय मिलने पर मॉनिटर वाक्य का संपादन कर देता है। विकल्प D जो वास्तव में होता है उसे उलट देता है।"},
  {"id":"cdp-pedagogy-subjects-377","question":"Which of the following statements would Stephen Krashen NOT accept?","options":["Acquisition is a subconscious process that gives the learner a ‘feel’ for what is correct","Learning produces conscious knowledge about the rules of a language, useful mainly for editing","Rules that are consciously learnt and practised enough eventually turn into acquired competence","Adults as well as children keep the ability to acquire a second language through comprehensible input"],"answer":2,"explanation":"Krashen held a ‘non-interface’ position: learnt knowledge does not convert into acquired knowledge. He also insisted adults keep the capacity to acquire, so the other three fit his model.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"निम्नलिखित में से किस कथन को स्टीफ़न क्रैशेन स्वीकार नहीं करेंगे?","optionsHi":["अर्जन एक अवचेतन प्रक्रिया है जो अधिगमकर्ता को यह ‘अनुभूति’ देती है कि क्या सही है","अधिगम भाषा के नियमों के बारे में सचेत ज्ञान उत्पन्न करता है, जो मुख्यतः संपादन के काम आता है","जो नियम सचेत रूप से सीखे और पर्याप्त अभ्यास किए जाते हैं, वे अंततः अर्जित दक्षता में बदल जाते हैं","वयस्क भी बच्चों की तरह बोधगम्य निवेश के माध्यम से द्वितीय भाषा अर्जित करने की क्षमता बनाए रखते हैं"],"explanationHi":"क्रैशेन का ‘गैर-अंतरापृष्ठ’ (नॉन-इंटरफ़ेस) मत था: सीखा हुआ ज्ञान अर्जित ज्ञान में नहीं बदलता। उन्होंने यह भी ज़ोर दिया कि वयस्क अर्जित करने की क्षमता बनाए रखते हैं, इसलिए अन्य तीन उनके मॉडल से मेल खाते हैं।"},
  {"id":"cdp-pedagogy-subjects-378","question":"A Class 3 teacher taught the third-person ‘-s’ (‘She plays’) in July and the ‘-ing’ form (‘She is playing’) in October. By December most children use ‘-ing’ correctly but still say ‘She play’. Which conclusion is most consistent with Krashen’s natural order hypothesis?","options":["The ‘-s’ lesson was badly taught and should simply be repeated with many more substitution and pattern drills","The pattern reflects only interference from the mother tongue and says nothing about any general order","The ‘-ing’ form should never have been taught until the third-person ‘-s’ was fully mastered by every child in the class","Some structures are acquired before others whatever the teaching order, so instant mastery should not be expected"],"answer":3,"explanation":"Morpheme-order studies found ‘-ing’ is acquired early and third-person ‘-s’ late, whatever the order of teaching. Krashen argued this is why rich input matters more than grammatical sequencing.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 3 के एक शिक्षक ने जुलाई में तृतीय पुरुष का ‘-s’ (‘She plays’) और अक्टूबर में ‘-ing’ रूप (‘She is playing’) पढ़ाया। दिसंबर तक अधिकांश बच्चे ‘-ing’ सही उपयोग करते हैं लेकिन अब भी ‘She play’ कहते हैं। क्रैशेन की प्राकृतिक क्रम परिकल्पना से कौन-सा निष्कर्ष सबसे अधिक मेल खाता है?","optionsHi":["‘-s’ का पाठ खराब पढ़ाया गया था और उसे और अधिक प्रतिस्थापन तथा पैटर्न-अभ्यास के साथ बस दोहराया जाना चाहिए","यह पैटर्न केवल मातृभाषा के हस्तक्षेप को दर्शाता है और किसी सामान्य क्रम के बारे में कुछ नहीं कहता","‘-ing’ रूप तब तक कभी नहीं पढ़ाया जाना चाहिए था जब तक कक्षा का हर बच्चा तृतीय पुरुष के ‘-s’ में पूरी तरह दक्ष न हो जाता","कुछ संरचनाएँ शिक्षण-क्रम चाहे जो हो, दूसरों से पहले अर्जित होती हैं, इसलिए तुरंत दक्षता की अपेक्षा नहीं करनी चाहिए"],"explanationHi":"रूपिम-क्रम के अध्ययनों ने पाया कि ‘-ing’ जल्दी और तृतीय पुरुष का ‘-s’ देर से अर्जित होता है, चाहे पढ़ाने का क्रम कुछ भी हो। क्रैशेन ने तर्क दिया कि यही कारण है कि व्याकरणिक क्रमण से अधिक समृद्ध निवेश मायने रखता है।"},
  {"id":"cdp-pedagogy-subjects-379","question":"A teacher is choosing stories for Class 5 learners in a Hindi-medium school in Jaipur. According to Krashen’s input hypothesis, the best choice is texts that are:","options":["Entirely at the learners’ present level, so that no word or structure in them is at all unfamiliar","A little beyond the learners’ present level but made understandable through pictures and context","Preceded by a full grammar explanation of every new structure that appears in them","Advanced authentic texts such as newspaper editorials, so that learners are fully stretched"],"answer":1,"explanation":"Acquisition happens through input at ‘i+1’ that is still comprehensible. Input at ‘i’ adds nothing new, input far beyond the learner is noise, and grammar explanation is learning, not acquisition.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"एक शिक्षक जयपुर के हिंदी-माध्यम विद्यालय में कक्षा 5 के अधिगमकर्ताओं के लिए कहानियाँ चुन रहा है। क्रैशेन की निवेश परिकल्पना के अनुसार, सबसे अच्छा चुनाव वे पाठ हैं जो:","optionsHi":["पूरी तरह अधिगमकर्ताओं के वर्तमान स्तर पर हों, ताकि उनमें कोई शब्द या संरचना बिल्कुल भी अपरिचित न हो","अधिगमकर्ताओं के वर्तमान स्तर से थोड़े आगे हों, लेकिन चित्रों और संदर्भ के माध्यम से बोधगम्य बनाए गए हों","जिनसे पहले उनमें आने वाली हर नई संरचना का पूरा व्याकरण-स्पष्टीकरण दिया जाए","समाचार-पत्र के संपादकीय जैसे उन्नत प्रामाणिक पाठ हों, ताकि अधिगमकर्ताओं को पूरी तरह चुनौती मिले"],"explanationHi":"अर्जन ‘i+1’ स्तर के उस निवेश से होता है जो फिर भी बोधगम्य हो। ‘i’ स्तर का निवेश कुछ नया नहीं जोड़ता, अधिगमकर्ता से बहुत आगे का निवेश शोर है, और व्याकरण का स्पष्टीकरण अधिगम है, अर्जन नहीं।"},
  {"id":"cdp-pedagogy-subjects-380","question":"A shy Class 7 girl from a tribal community in Jharkhand follows English instructions well but freezes whenever she is asked to read aloud, and some classmates giggle. In the light of Krashen’s theory, the best teacher action is to:","options":["Ask her to read aloud before the class every day so that she slowly gets used to the attention","Give her extra grammar worksheets so that knowing the rules well builds up her confidence to speak","Stop the ridicule, begin with pair or choral reading and accept early answers in her home language","Excuse her from English lessons for some months until she becomes more confident on her own"],"answer":2,"explanation":"A high affective filter (anxiety, low self-confidence) blocks input from being acquired. Forcing public performance raises the filter, and excusing her cuts off input altogether.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"झारखंड के एक आदिवासी समुदाय की कक्षा 7 की एक संकोची लड़की अंग्रेज़ी निर्देश अच्छी तरह समझती है, लेकिन जब उससे ज़ोर से पढ़ने को कहा जाता है तो जम जाती है, और कुछ सहपाठी हँस पड़ते हैं। क्रैशेन के सिद्धांत के आलोक में, शिक्षक की सबसे अच्छी कार्रवाई है:","optionsHi":["उससे हर दिन कक्षा के सामने ज़ोर से पढ़ने को कहना ताकि वह धीरे-धीरे ध्यान की अभ्यस्त हो जाए","उसे अतिरिक्त व्याकरण अभ्यास-पत्र देना ताकि नियमों को अच्छी तरह जानना उसके बोलने का आत्मविश्वास बढ़ाए","उपहास रोकना, जोड़ी या सामूहिक पठन से शुरू करना, और उसके आरंभिक उत्तर उसकी घरेलू भाषा में स्वीकार करना","उसे कुछ महीनों के लिए अंग्रेज़ी के कालांशों से छूट देना जब तक वह स्वयं अधिक आत्मविश्वासी न हो जाए"],"explanationHi":"ऊँची भावात्मक छन्नी (चिंता, कम आत्मविश्वास) निवेश को अर्जित होने से रोकती है। सार्वजनिक प्रदर्शन के लिए बाध्य करना छन्नी को ऊँचा करता है, और छूट देना निवेश को पूरी तरह काट देता है।"},
  {"id":"cdp-pedagogy-subjects-381","question":"A Class 1 child in a Bengaluru school, whose home language is Tamil, has not spoken a word of English in two months, but he follows every classroom instruction correctly. The most appropriate teacher response is to:","options":["Treat it as a normal silent period, keep giving comprehensible input and accept non-verbal responses","Refer the child to a speech therapist, since two months of silence signals a language delay","Insist that he answer every question in a complete English sentence so that he is pushed to start speaking","Shift him to a lower class where the English used is simpler and the pressure is less"],"answer":0,"explanation":"Many second-language learners go through a silent period in which they build competence through listening; his correct responses to instructions show comprehension. Forcing speech raises the affective filter.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"बेंगलुरु के एक विद्यालय में कक्षा 1 का एक बच्चा, जिसकी घरेलू भाषा तमिल है, दो महीने में अंग्रेज़ी का एक शब्द नहीं बोला है, लेकिन कक्षा के हर निर्देश का सही पालन करता है। शिक्षक की सबसे उपयुक्त प्रतिक्रिया है:","optionsHi":["इसे सामान्य मौन-अवधि मानना, बोधगम्य निवेश देते रहना और अशाब्दिक प्रतिक्रियाओं को स्वीकार करना","बच्चे को वाक्-चिकित्सक के पास भेजना, क्योंकि दो महीने की चुप्पी भाषा-विलंब का संकेत है","ज़ोर देना कि वह हर प्रश्न का उत्तर पूरे अंग्रेज़ी वाक्य में दे ताकि वह बोलना शुरू करने को विवश हो","उसे निचली कक्षा में भेजना जहाँ अंग्रेज़ी सरल है और दबाव कम है"],"explanationHi":"कई द्वितीय भाषा अधिगमकर्ता मौन-अवधि से गुज़रते हैं जिसमें वे सुनकर दक्षता निर्मित करते हैं; निर्देशों पर उसकी सही प्रतिक्रियाएँ बोध दर्शाती हैं। बोलने को बाध्य करना भावात्मक छन्नी को ऊँचा करता है।"},
  {"id":"cdp-pedagogy-subjects-382","question":"Assertion (A): Krashen held that formal grammar teaching contributes little to a learner’s fluency in speaking. Reason (R): According to the monitor hypothesis, fluent utterances are initiated by the acquired system, and learnt rules can only edit them.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"In Krashen’s model acquired competence initiates speech and learnt knowledge only monitors it, which is exactly why he saw grammar teaching as having limited value for fluency.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"अभिकथन (A): क्रैशेन का मत था कि औपचारिक व्याकरण शिक्षण अधिगमकर्ता के बोलने के प्रवाह में बहुत कम योगदान देता है। कारण (R): निगरानी परिकल्पना के अनुसार, धाराप्रवाह कथन अर्जित प्रणाली से शुरू होते हैं, और सीखे हुए नियम केवल उनका संपादन कर सकते हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"क्रैशेन के मॉडल में अर्जित दक्षता वाणी को आरंभ करती है और सीखा हुआ ज्ञान केवल उसकी निगरानी करता है, ठीक इसीलिए उन्होंने व्याकरण शिक्षण को प्रवाह के लिए सीमित मूल्य का माना।"},
  {"id":"cdp-pedagogy-subjects-383","question":"Arjun speaks English very haltingly, pausing to check each sentence against a grammar rule before he says it. Farhan chats fluently, makes many errors and never thinks about rules. In Krashen’s terms:","options":["Arjun is a monitor under-user and Farhan is a monitor over-user","Both are optimal monitor users who apply rules when appropriate","Arjun is a monitor over-user and Farhan is a monitor under-user","Arjun has simply received more comprehensible input than Farhan"],"answer":2,"explanation":"Over-users rely so heavily on learnt rules that their speech becomes hesitant; under-users rely only on acquired competence. The optimal user applies the monitor when it does not hinder communication, for example while editing writing.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"अर्जुन बहुत रुक-रुककर अंग्रेज़ी बोलता है, हर वाक्य को बोलने से पहले व्याकरण के नियम से जाँचने के लिए रुकता है। फ़रहान धाराप्रवाह बातचीत करता है, कई त्रुटियाँ करता है और नियमों के बारे में कभी नहीं सोचता। क्रैशेन के शब्दों में:","optionsHi":["अर्जुन मॉनिटर का अल्प-उपयोगकर्ता है और फ़रहान मॉनिटर का अति-उपयोगकर्ता है","दोनों इष्टतम मॉनिटर उपयोगकर्ता हैं जो उचित होने पर नियम लागू करते हैं","अर्जुन मॉनिटर का अति-उपयोगकर्ता है और फ़रहान मॉनिटर का अल्प-उपयोगकर्ता है","अर्जुन को बस फ़रहान से अधिक बोधगम्य निवेश मिला है"],"explanationHi":"अति-उपयोगकर्ता सीखे हुए नियमों पर इतना निर्भर करते हैं कि उनकी वाणी हिचकिचाहट भरी हो जाती है; अल्प-उपयोगकर्ता केवल अर्जित दक्षता पर निर्भर करते हैं। इष्टतम उपयोगकर्ता मॉनिटर तब लगाता है जब वह संप्रेषण में बाधक न हो, जैसे लेखन का संपादन करते समय।"},
  {"id":"cdp-pedagogy-subjects-384","question":"In which situation is a learner most likely to use Krashen’s ‘monitor’ effectively?","options":["Answering rapid-fire questions in the buzzer round of an inter-school quiz","Revising a formal letter at leisure, checking a rule she already knows","Chatting with friends in the canteen about yesterday’s cricket match","Listening carefully to a news bulletin on All India Radio"],"answer":1,"explanation":"The monitor needs three conditions together: enough time, a focus on form, and knowledge of the rule. Only careful editing of writing meets all three; listening is comprehension, not monitoring of output.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"किस स्थिति में अधिगमकर्ता द्वारा क्रैशेन के ‘मॉनिटर’ का प्रभावी उपयोग करने की सबसे अधिक संभावना है?","optionsHi":["अंतर-विद्यालयी प्रश्नोत्तरी के बज़र राउंड में तेज़ी से प्रश्नों के उत्तर देना","किसी औपचारिक पत्र को फ़ुर्सत से दोहराना, किसी ऐसे नियम की जाँच करना जिसे वह पहले से जानती है","कैंटीन में मित्रों के साथ कल के क्रिकेट मैच के बारे में गपशप करना","ऑल इंडिया रेडियो के समाचार बुलेटिन को ध्यान से सुनना"],"explanationHi":"मॉनिटर को तीन शर्तें एक साथ चाहिए: पर्याप्त समय, रूप पर ध्यान और नियम का ज्ञान। केवल लेखन का सावधान संपादन तीनों को पूरा करता है; सुनना बोध है, प्रस्तुति की निगरानी नहीं।"},
  {"id":"cdp-pedagogy-subjects-385","question":"Students in an English-immersion school in Kochi understand spoken and written English very well, yet their own speech and writing remain inaccurate after years. Their teacher therefore designs tasks that push them to speak and write, notice gaps in what they produce, and reformulate. Which idea most directly supports her plan?","options":["Krashen’s input hypothesis","Skinner’s theory of reinforcement","Chomsky’s language acquisition device","Swain’s output hypothesis"],"answer":3,"explanation":"Merrill Swain, studying Canadian immersion learners, argued that comprehension alone is not enough; ‘pushed output’ makes learners notice gaps and test hypotheses. The input hypothesis alone would not predict this gap.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कोच्चि के एक अंग्रेज़ी-निमज्जन (इमर्शन) विद्यालय के विद्यार्थी बोली और लिखी अंग्रेज़ी बहुत अच्छी तरह समझते हैं, फिर भी वर्षों बाद उनकी अपनी बोली और लेखन अशुद्ध बने रहते हैं। इसलिए उनकी शिक्षिका ऐसे कार्य बनाती है जो उन्हें बोलने और लिखने, अपनी प्रस्तुति में अंतराल देखने, और पुनः-सूत्रबद्ध करने के लिए प्रेरित करें। कौन-सा विचार उसकी योजना को सबसे सीधे समर्थन देता है?","optionsHi":["क्रैशेन की निवेश परिकल्पना","स्किनर का पुनर्बलन सिद्धांत","चॉम्स्की की भाषा अर्जन युक्ति","स्वेन की निर्गत परिकल्पना (आउटपुट हाइपोथीसिस)"],"explanationHi":"कनाडा के निमज्जन अधिगमकर्ताओं का अध्ययन करने वाली मेरिल स्वेन ने तर्क दिया कि केवल बोध पर्याप्त नहीं है; ‘प्रेरित निर्गत’ अधिगमकर्ताओं को अंतराल देखने और परिकल्पनाओं को परखने के लिए प्रेरित करता है। अकेली निवेश परिकल्पना इस अंतर का पूर्वानुमान नहीं देती।"},
  {"id":"cdp-pedagogy-subjects-386","question":"During pair work, Meena says, ‘Then the man cut the kite.’ Her partner asks, ‘Cut? You mean with scissors, or the thread broke?’ Meena replies, ‘No, in the kite fight, he cut the thread of my kite.’ This exchange best illustrates:","options":["Negotiation of meaning, which Long’s interaction hypothesis links to acquisition","Pattern practice of the kind used in the audio-lingual method of teaching","Use of the monitor to edit a grammatical form carefully before speaking aloud","Fossilisation of an incorrect structure that is reinforced through peer interaction"],"answer":0,"explanation":"Clarification requests and reformulation during interaction adjust the input until it is understood; Long argued this negotiation is a key route to acquisition.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"जोड़ी में कार्य के दौरान मीना कहती है, ‘Then the man cut the kite.’ उसका साथी पूछता है, ‘Cut? You mean with scissors, or the thread broke?’ मीना उत्तर देती है, ‘No, in the kite fight, he cut the thread of my kite.’ यह संवाद सबसे अच्छी तरह दर्शाता है:","optionsHi":["अर्थ की समझौता-वार्ता (नेगोशिएशन ऑफ़ मीनिंग), जिसे लॉन्ग की अंतःक्रिया परिकल्पना अर्जन से जोड़ती है","श्रव्य-भाषिक शिक्षण विधि में प्रयुक्त प्रकार का पैटर्न-अभ्यास","ज़ोर से बोलने से पहले किसी व्याकरणिक रूप को सावधानी से संपादित करने के लिए मॉनिटर का उपयोग","किसी गलत संरचना का जीवाश्मीकरण (फ़ॉसिलाइज़ेशन), जो सहपाठी अंतःक्रिया से पुष्ट होती है"],"explanationHi":"अंतःक्रिया के दौरान स्पष्टीकरण के अनुरोध और पुनः-सूत्रीकरण निवेश को तब तक समायोजित करते हैं जब तक वह समझ में न आ जाए; लॉन्ग ने तर्क दिया कि यह समझौता-वार्ता अर्जन का एक प्रमुख मार्ग है।"},
  {"id":"cdp-pedagogy-subjects-387","question":"A shopkeeper in Agra has used English with tourists for twenty years. He communicates well but still says ‘He don’t know’ and ‘You are coming tomorrow, no?’, and these forms have not changed despite constant exposure. This phenomenon is called:","options":["The silent period","Overgeneralisation","Code-mixing","Fossilisation"],"answer":3,"explanation":"Fossilisation (Selinker) is the stabilisation of interlanguage features that persist despite continued input. Overgeneralisation is a temporary developmental stage, not a permanent plateau.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"आगरा का एक दुकानदार बीस वर्षों से पर्यटकों के साथ अंग्रेज़ी का उपयोग कर रहा है। वह अच्छी तरह संप्रेषण करता है, लेकिन अब भी ‘He don’t know’ और ‘You are coming tomorrow, no?’ कहता है, और निरंतर संपर्क के बावजूद ये रूप नहीं बदले हैं। इस परिघटना को क्या कहते हैं?","optionsHi":["मौन-अवधि","अतिसामान्यीकरण","कोड-मिश्रण","जीवाश्मीकरण (फ़ॉसिलाइज़ेशन)"],"explanationHi":"जीवाश्मीकरण (सेलिंकर) अंतरभाषा की उन विशेषताओं का स्थिर हो जाना है जो निरंतर निवेश के बावजूद बनी रहती हैं। अतिसामान्यीकरण एक अस्थायी विकासात्मक अवस्था है, स्थायी स्थिरता नहीं।"},
  {"id":"cdp-pedagogy-subjects-388","question":"Sunita, a Class 5 child who migrated from Odisha to a Delhi English-medium school, chats easily in English with friends within a year but struggles with her science textbook. Using Jim Cummins’ ideas, the teacher should conclude that:","options":["Her fluent chatting shows she has full proficiency, so the difficulty must be lack of effort","Her pattern points to a specific reading disability that needs early referral","She has conversational fluency (BICS), but academic language (CALP) takes years to develop","She should be moved back to a school that teaches in her home language"],"answer":2,"explanation":"Cummins found that playground fluency develops in about two years but context-reduced academic language takes five to seven. Mistaking BICS for full proficiency leads to wrong labels such as ‘lazy’ or ‘learning disabled’.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"सुनीता, कक्षा 5 की एक बच्ची, जो ओडिशा से दिल्ली के अंग्रेज़ी-माध्यम विद्यालय में आई है, एक वर्ष के भीतर मित्रों से अंग्रेज़ी में आसानी से बातचीत करने लगती है, लेकिन अपनी विज्ञान की पाठ्यपुस्तक में कठिनाई महसूस करती है। जिम कमिन्स के विचारों का उपयोग करते हुए, शिक्षक को यह निष्कर्ष निकालना चाहिए कि:","optionsHi":["उसकी धाराप्रवाह बातचीत दिखाती है कि उसमें पूर्ण दक्षता है, इसलिए कठिनाई प्रयास की कमी होगी","उसका प्रतिरूप किसी विशिष्ट पठन-अक्षमता की ओर संकेत करता है जिसके लिए शीघ्र विशेषज्ञ के पास भेजना आवश्यक है","उसमें बातचीत की प्रवाहशीलता (BICS) है, लेकिन शैक्षणिक भाषा (CALP) को विकसित होने में वर्षों लगते हैं","उसे ऐसे विद्यालय में वापस भेजना चाहिए जो उसकी घरेलू भाषा में पढ़ाता हो"],"explanationHi":"कमिन्स ने पाया कि खेल के मैदान की प्रवाहशीलता लगभग दो वर्षों में विकसित हो जाती है लेकिन संदर्भ-रहित शैक्षणिक भाषा में पाँच से सात वर्ष लगते हैं। BICS को पूर्ण दक्षता मान लेने से ‘आलसी’ या ‘अधिगम-अक्षम’ जैसे गलत ठप्पे लगते हैं।"},
  {"id":"cdp-pedagogy-subjects-389","question":"A Class 4 child reads and writes fluently in Marathi and is now learning English. According to Cummins’ ‘common underlying proficiency’ (iceberg) model, which implication is correct?","options":["Literacy skills built in Marathi transfer to English, so strengthening Marathi also supports English","Marathi and English are stored separately, so time spent on Marathi takes away from English","She should stop using Marathi at school so that her English can develop faster and cleaner","Only knowledge of letters transfers between the two languages; reading strategies must be learnt anew"],"answer":0,"explanation":"Cummins showed that the two languages share an underlying proficiency; skills such as predicting, inferring and knowing how texts work transfer. Option B is the discredited ‘separate underlying proficiency’ view.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 4 की एक बच्ची मराठी में धाराप्रवाह पढ़ती-लिखती है और अब अंग्रेज़ी सीख रही है। कमिन्स के ‘साझा अंतर्निहित दक्षता’ (हिमशैल) मॉडल के अनुसार, कौन-सा निहितार्थ सही है?","optionsHi":["मराठी में निर्मित साक्षरता कौशल अंग्रेज़ी में स्थानांतरित होते हैं, इसलिए मराठी को मज़बूत करना अंग्रेज़ी में भी सहायक है","मराठी और अंग्रेज़ी अलग-अलग संग्रहित हैं, इसलिए मराठी पर बिताया गया समय अंग्रेज़ी से घटता है","उसे विद्यालय में मराठी का उपयोग बंद कर देना चाहिए ताकि उसकी अंग्रेज़ी तेज़ी से और अधिक शुद्ध विकसित हो","दोनों भाषाओं के बीच केवल अक्षरों का ज्ञान स्थानांतरित होता है; पठन-रणनीतियाँ फिर से सीखनी पड़ती हैं"],"explanationHi":"कमिन्स ने दिखाया कि दोनों भाषाएँ एक साझा अंतर्निहित दक्षता रखती हैं; पूर्वानुमान, अनुमान और पाठ कैसे काम करते हैं जैसे कौशल स्थानांतरित होते हैं। विकल्प B वह खारिज किया गया ‘अलग अंतर्निहित दक्षता’ वाला मत है।"},
  {"id":"cdp-pedagogy-subjects-390","question":"Consider these statements: I. Chomsky’s language acquisition device helps explain why children everywhere pass through similar stages of language development. II. Skinner explained language development through imitation, reinforcement and habit formation. III. Vygotsky saw language as a social tool that later turns into inner speech and guides thought. IV. Krashen’s ‘acquisition’ is essentially the same as Skinner’s conditioning. Which are correct?","options":["I and III only","I, II and III only","II and IV only","All four: I, II, III and IV"],"answer":1,"explanation":"I, II and III describe the nativist, behaviourist and socio-cultural views correctly. Krashen’s acquisition is a subconscious, input-driven process in the nativist tradition, not habit formation, so IV is false.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"इन कथनों पर विचार कीजिए: I. चॉम्स्की की भाषा अर्जन युक्ति इसे समझाने में मदद करती है कि हर जगह बच्चे भाषा-विकास की समान अवस्थाओं से क्यों गुज़रते हैं। II. स्किनर ने भाषा-विकास की व्याख्या अनुकरण, पुनर्बलन और आदत-निर्माण से की। III. वाइगोत्स्की भाषा को एक सामाजिक उपकरण मानते थे जो बाद में आंतरिक वाणी बन जाती है और चिंतन का मार्गदर्शन करती है। IV. क्रैशेन का ‘अर्जन’ मूलतः स्किनर के अनुबंधन के समान है। कौन-से सही हैं?","optionsHi":["केवल I और III","केवल I, II और III","केवल II और IV","चारों: I, II, III और IV"],"explanationHi":"I, II और III जन्मजातवादी, व्यवहारवादी और सामाजिक-सांस्कृतिक मतों का सही वर्णन करते हैं। क्रैशेन का अर्जन जन्मजातवादी परंपरा में एक अवचेतन, निवेश-चालित प्रक्रिया है, आदत-निर्माण नहीं, इसलिए IV गलत है।"},
  {"id":"cdp-pedagogy-subjects-391","question":"Which classroom practice is most consistent with Krashen’s view of errors in a beginner English class?","options":["Correcting every spoken error at once so that the wrong forms are never acquired by the class","Keeping the focus on meaningful communication and leaving error work mainly for edited writing","Teaching the rule for each structure before students are allowed to use it in their own speech","Having students memorise model dialogues until they can say them without any errors"],"answer":1,"explanation":"For Krashen, acquisition comes from understood input in a low-anxiety setting; constant correction raises the filter and only feeds the monitor. Rule-first teaching and dialogue memorisation reflect learning or habit formation.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"प्रारंभिक अंग्रेज़ी कक्षा में त्रुटियों के बारे में क्रैशेन के दृष्टिकोण के सबसे अनुरूप कक्षा-अभ्यास कौन-सा है?","optionsHi":["हर बोली गई त्रुटि को तुरंत सुधारना ताकि कक्षा कभी गलत रूप अर्जित न करे","ध्यान को अर्थपूर्ण संप्रेषण पर रखना और त्रुटि संबंधी कार्य को मुख्यतः संपादित लेखन के लिए छोड़ना","हर संरचना का नियम सिखाना, उससे पहले कि विद्यार्थियों को अपनी बोली में उसका उपयोग करने दिया जाए","विद्यार्थियों से आदर्श संवाद तब तक याद करवाना जब तक वे उन्हें बिना किसी त्रुटि के बोल न सकें"],"explanationHi":"क्रैशेन के लिए अर्जन कम-चिंता वाले वातावरण में समझे गए निवेश से आता है; निरंतर सुधार छन्नी को ऊँचा करता है और केवल मॉनिटर को पोषित करता है। नियम-पहले शिक्षण और संवाद-रटंत अधिगम या आदत-निर्माण को दर्शाते हैं।"},
  {"id":"cdp-pedagogy-subjects-392","question":"In the Natural Approach of Krashen and Terrell, a Class 2 learner who answers questions with single words or short phrases such as ‘Yes’, ‘Red one’ and ‘Two mango’ is at the stage of:","options":["Early production","Speech emergence","Intermediate fluency","Pre-production"],"answer":0,"explanation":"Pre-production is the silent comprehension stage; early production has one- or two-word answers and yes/no responses; speech emergence brings longer phrases and simple sentences.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"क्रैशेन और टेरेल के प्राकृतिक उपागम (नैचुरल अप्रोच) में, कक्षा 2 का वह अधिगमकर्ता जो ‘Yes’, ‘Red one’ और ‘Two mango’ जैसे एक शब्द या छोटे वाक्यांशों में प्रश्नों के उत्तर देता है, किस चरण पर है?","optionsHi":["प्रारंभिक उत्पादन","वाणी का उद्भव","मध्यवर्ती प्रवाह","पूर्व-उत्पादन"],"explanationHi":"पूर्व-उत्पादन मौन बोध का चरण है; प्रारंभिक उत्पादन में एक या दो शब्दों के उत्तर और हाँ/नहीं प्रतिक्रियाएँ होती हैं; वाणी के उद्भव में लंबे वाक्यांश और सरल वाक्य आते हैं।"},
  {"id":"cdp-pedagogy-subjects-393","question":"Which of these activities is most likely to promote acquisition rather than learning, in Krashen’s sense?","options":["Underlining all the verbs in a passage and labelling each one’s tense","Converting ten sentences from the active into the passive voice","Memorising the rules for changing direct into indirect speech","Listening to a funny picture story and talking about what happens"],"answer":3,"explanation":"Acquisition happens when attention is on understanding a meaningful message; the other three focus attention on form and rules, which builds conscious learning.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"क्रैशेन के अर्थ में, इनमें से कौन-सी गतिविधि अधिगम के बजाय अर्जन को बढ़ावा देने की सबसे अधिक संभावना रखती है?","optionsHi":["किसी अनुच्छेद की सभी क्रियाओं को रेखांकित करना और हर एक का काल नामांकित करना","दस वाक्यों को कर्तृवाच्य से कर्मवाच्य में बदलना","प्रत्यक्ष कथन को अप्रत्यक्ष कथन में बदलने के नियम याद करना","एक मज़ेदार चित्र-कथा सुनना और इस पर बात करना कि क्या होता है"],"explanationHi":"अर्जन तब होता है जब ध्यान किसी अर्थपूर्ण संदेश को समझने पर होता है; अन्य तीन ध्यान को रूप और नियमों पर केंद्रित करते हैं, जो सचेत अधिगम का निर्माण करता है।"},
  {"id":"cdp-pedagogy-subjects-394","question":"A school in Lucknow introduces a daily 20-minute period in which every child reads a book of her own choice, with no questions, marks or reports afterwards. Krashen would justify this practice mainly because it:","options":["Teaches grammar rules more efficiently than the prescribed textbook and its exercises can","Lets the teacher quietly check each child’s reading level and progress every day","Gives plenty of comprehensible input in a relaxed setting, from which language is acquired","Trains children to apply the monitor carefully to every sentence they read, checking each rule"],"answer":2,"explanation":"Krashen saw free voluntary reading as one of the most powerful sources of comprehensible input, building vocabulary, grammar and spelling. Its value comes precisely from the absence of testing and rule focus.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"लखनऊ का एक विद्यालय प्रतिदिन 20 मिनट का एक कालांश शुरू करता है जिसमें हर बच्ची अपनी पसंद की पुस्तक पढ़ती है, बाद में कोई प्रश्न, अंक या रिपोर्ट नहीं। क्रैशेन इस अभ्यास का औचित्य मुख्य रूप से इसलिए बताते कि यह:","optionsHi":["व्याकरण के नियम निर्धारित पाठ्यपुस्तक और उसके अभ्यासों से अधिक कुशलता से सिखाता है","शिक्षक को हर दिन चुपचाप हर बच्चे का पठन-स्तर और प्रगति जाँचने देता है","आरामदेह वातावरण में प्रचुर बोधगम्य निवेश देता है, जिससे भाषा अर्जित होती है","बच्चों को हर नियम की जाँच करते हुए, पढ़े गए हर वाक्य पर मॉनिटर को सावधानी से लागू करने का प्रशिक्षण देता है"],"explanationHi":"क्रैशेन स्वतंत्र स्वैच्छिक पठन को बोधगम्य निवेश के सबसे शक्तिशाली स्रोतों में से एक मानते थे, जो शब्दावली, व्याकरण और वर्तनी का निर्माण करता है। इसका मूल्य ठीक परीक्षा और नियम-केंद्रितता के अभाव से आता है।"},
  {"id":"cdp-pedagogy-subjects-395","question":"Which of the following is a well-known criticism of Krashen’s theory of second language acquisition?","options":["Its key constructs, such as acquisition versus learning and ‘i+1’, are hard to test","It gives too much importance to grammar drills and to pattern practice in the classroom","It largely ignores the role that input and exposure play in a learner's language development","It is built on the behaviourist idea that language is a set of habits"],"answer":0,"explanation":"Critics such as McLaughlin argued that ‘acquisition’, ‘learning’ and ‘i+1’ cannot be measured, so the hypotheses are hard to falsify. The other options describe the opposite of Krashen’s position.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"द्वितीय भाषा अर्जन के क्रैशेन के सिद्धांत की निम्नलिखित में से कौन-सी एक सुविख्यात आलोचना है?","optionsHi":["इसकी मुख्य संरचनाएँ, जैसे अर्जन बनाम अधिगम और ‘i+1’, परखना कठिन है","यह कक्षा में व्याकरण-अभ्यास और पैटर्न-अभ्यास को बहुत अधिक महत्त्व देता है","यह अधिगमकर्ता के भाषा-विकास में निवेश और संपर्क की भूमिका को काफ़ी हद तक अनदेखा करता है","यह इस व्यवहारवादी विचार पर बना है कि भाषा आदतों का समूह है"],"explanationHi":"मैकलॉफ़लिन जैसे आलोचकों ने तर्क दिया कि ‘अर्जन’, ‘अधिगम’ और ‘i+1’ को मापा नहीं जा सकता, इसलिए परिकल्पनाओं को असत्य सिद्ध करना कठिन है। अन्य विकल्प क्रैशेन के मत के विपरीत का वर्णन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-396","question":"A Class 4 child can write a sentence about her family only with help. Her teacher pairs her with a more capable classmate and gives her sentence starters (‘My mother likes…’) that are withdrawn over the next weeks as she gains control. This practice is best described as:","options":["Providing input at i+1, as Krashen suggested","Shaping through reinforcement, as Skinner suggested","Scaffolding within the zone of proximal development","Activating the monitor to edit written output"],"answer":2,"explanation":"Temporary, gradually withdrawn support from a more knowledgeable other, within what the child can do with help, is Vygotskian scaffolding. Krashen’s i+1 concerns input, not assisted performance.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 4 की एक बच्ची अपने परिवार के बारे में वाक्य केवल सहायता से लिख पाती है। उसकी शिक्षिका उसे अधिक सक्षम सहपाठी के साथ जोड़ती है और उसे वाक्य-आरंभ (‘My mother likes…’) देती है, जो अगले सप्ताहों में हटा लिए जाते हैं क्योंकि वह नियंत्रण पा लेती है। इस अभ्यास का सबसे अच्छा वर्णन है:","optionsHi":["i+1 स्तर पर निवेश देना, जैसा क्रैशेन ने सुझाया","पुनर्बलन के माध्यम से आकार देना, जैसा स्किनर ने सुझाया","निकटस्थ विकास के क्षेत्र में पाड़ (स्कैफ़ोल्डिंग)","लिखित प्रस्तुति के संपादन के लिए मॉनिटर को सक्रिय करना"],"explanationHi":"अधिक ज्ञानी व्यक्ति से मिलने वाला अस्थायी, धीरे-धीरे हटाया जाने वाला सहारा, उस दायरे में जो बच्चा सहायता से कर सकता है, वाइगोत्स्कीय पाड़ है। क्रैशेन का i+1 निवेश से संबंधित है, सहायता-प्राप्त प्रदर्शन से नहीं।"},
  {"id":"cdp-pedagogy-subjects-397","question":"A Class 3 child writes ‘childs’, ‘mouses’ and ‘sheeps’ in a story. Such errors are best classified as:","options":["Interlingual errors caused by transfer from the mother tongue","Intralingual errors caused by overgeneralising an English rule","Performance slips that the child would notice and correct on her own","Spelling errors that point to a problem with hearing"],"answer":1,"explanation":"The child applies the regular ‘-s’ plural rule to irregular nouns, a developmental error within English itself. It shows rule learning in progress, not mother-tongue interference.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"कक्षा 3 का एक बच्चा कहानी में ‘childs’, ‘mouses’ और ‘sheeps’ लिखता है। ऐसी त्रुटियों का सबसे अच्छा वर्गीकरण है:","optionsHi":["मातृभाषा से स्थानांतरण के कारण अंतरभाषी (इंटरलिंग्वल) त्रुटियाँ","अंग्रेज़ी के नियम के अतिसामान्यीकरण के कारण अंतःभाषी (इंट्रालिंग्वल) त्रुटियाँ","प्रदर्शन की भूलें, जिन्हें बच्ची स्वयं देखकर सुधार लेगी","वर्तनी की त्रुटियाँ जो श्रवण में समस्या की ओर संकेत करती हैं"],"explanationHi":"बच्चा नियमित ‘-s’ बहुवचन नियम को अनियमित संज्ञाओं पर लागू करता है, जो अंग्रेज़ी के भीतर की ही विकासात्मक त्रुटि है। यह नियम-अधिगम की प्रगति दर्शाती है, मातृभाषा का हस्तक्षेप नहीं।"},
  {"id":"cdp-pedagogy-subjects-398","question":"Consider these statements about Krashen’s affective filter: I. A high filter can stop comprehensible input from being used for acquisition. II. Motivation, self-confidence and low anxiety help to lower the filter. III. According to Krashen, the filter is generally stronger in young children than in adolescents. Which are correct?","options":["I only","I, II and III","II and III only","I and II only"],"answer":3,"explanation":"Krashen suggested the filter grows stronger around puberty, which helps explain why adolescents are often more self-conscious learners. So III is reversed, while I and II are correct.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"क्रैशेन की भावात्मक छन्नी के बारे में इन कथनों पर विचार कीजिए: I. ऊँची छन्नी बोधगम्य निवेश को अर्जन के लिए उपयोग होने से रोक सकती है। II. अभिप्रेरणा, आत्मविश्वास और कम चिंता छन्नी को कम करने में सहायक हैं। III. क्रैशेन के अनुसार, छन्नी सामान्यतः किशोरों की तुलना में छोटे बच्चों में अधिक प्रबल होती है। कौन-से सही हैं?","optionsHi":["केवल I","I, II और III","केवल II और III","केवल I और II"],"explanationHi":"क्रैशेन ने सुझाया कि छन्नी यौवन के आसपास प्रबल होती है, जो यह समझाने में मदद करता है कि किशोर अक्सर अधिक आत्म-सचेत अधिगमकर्ता क्यों होते हैं। इसलिए III उलटा है, जबकि I और II सही हैं।"},
  {"id":"cdp-pedagogy-subjects-399","question":"Match each of Krashen’s hypotheses with the classroom implication it most directly supports: 1. Input hypothesis 2. Affective filter hypothesis 3. Natural order hypothesis 4. Monitor hypothesis; a. Do not expect a structure to be mastered just because it has been taught b. Keep the classroom relaxed and non-threatening c. Provide plenty of understandable reading and listening d. Give learners time to edit their written work","options":["1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-a, 4-d","1-c, 2-a, 3-b, 4-d","1-c, 2-b, 3-a, 4-d"],"answer":3,"explanation":"Input calls for plenty of comprehensible input, the filter for low anxiety, natural order for not equating teaching with acquisition, and the monitor for using learnt rules while editing.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"क्रैशेन की प्रत्येक परिकल्पना का उस कक्षा-निहितार्थ से मिलान कीजिए जिसका वह सबसे सीधा समर्थन करती है: 1. निवेश परिकल्पना 2. भावात्मक छन्नी परिकल्पना 3. प्राकृतिक क्रम परिकल्पना 4. निगरानी परिकल्पना; a. यह अपेक्षा न करें कि कोई संरचना केवल इसलिए सीख ली गई कि वह पढ़ाई गई b. कक्षा को आरामदेह और भय-रहित रखें c. प्रचुर समझ में आने वाला पठन और श्रवण दें d. अधिगमकर्ताओं को अपने लिखित कार्य के संपादन का समय दें","optionsHi":["1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-a, 4-d","1-c, 2-a, 3-b, 4-d","1-c, 2-b, 3-a, 4-d"],"explanationHi":"निवेश प्रचुर बोधगम्य निवेश माँगता है, छन्नी कम चिंता, प्राकृतिक क्रम पढ़ाने को अर्जन के बराबर न मानना, और मॉनिटर संपादन करते समय सीखे हुए नियमों का उपयोग।"},
  {"id":"cdp-pedagogy-subjects-400","question":"To teach ‘The farmer is ploughing the field’ to Class 3 children in a village in Assam, a teacher shows a picture, mimes the action and quickly gives the Assamese word for ‘plough’. Which evaluation of her practice is most appropriate?","options":["Using Assamese is a mistake, since English must be taught only through English","It makes the input comprehensible and uses the home language as a resource","Miming distracts the children from the language and should be avoided","It is the grammar-translation method, because a translation was given"],"answer":1,"explanation":"Pictures, gestures and a brief home-language gloss make input understandable, and NCF 2005 treats children’s languages as a resource. One gloss does not make a lesson grammar-translation, which centres on rules and written translation.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"असम के एक गाँव में कक्षा 3 के बच्चों को ‘The farmer is ploughing the field’ सिखाने के लिए एक शिक्षिका चित्र दिखाती है, क्रिया का अभिनय करती है और ‘plough’ के लिए असमिया शब्द जल्दी से बता देती है। उसके अभ्यास का कौन-सा मूल्यांकन सबसे उपयुक्त है?","optionsHi":["असमिया का उपयोग एक गलती है, क्योंकि अंग्रेज़ी केवल अंग्रेज़ी के माध्यम से ही पढ़ाई जानी चाहिए","यह निवेश को बोधगम्य बनाता है और घरेलू भाषा को संसाधन के रूप में उपयोग करता है","अभिनय बच्चों को भाषा से भटकाता है और इससे बचना चाहिए","यह व्याकरण-अनुवाद विधि है, क्योंकि अनुवाद दिया गया"],"explanationHi":"चित्र, भाव-भंगिमाएँ और घरेलू भाषा का संक्षिप्त अर्थ निवेश को समझने योग्य बनाते हैं, और NCF 2005 बच्चों की भाषाओं को संसाधन मानता है। एक अर्थ दे देने से पाठ व्याकरण-अनुवाद नहीं बन जाता, जो नियमों और लिखित अनुवाद पर केंद्रित होता है।"},
  {"id":"cdp-pedagogy-subjects-401","question":"A Class 4 teacher plans a visit to the local post office. Which sequence will make the visit most useful for learning?","options":["Visit the post office → children write a long essay on it at home → a written test on the essay the next day","Read the textbook chapter → visit the post office → children copy a note dictated by the teacher into their books","Visit without any preparation so that children are surprised by everything they see → a surprise class test on what they remember","Children frame what they want to find out → observe and interview during the visit → share, record and reflect afterwards"],"answer":3,"explanation":"A field visit works when it has a pre-visit stage (purpose and questions), an active visit stage and a post-visit stage of sharing and reflection. The other sequences reduce it to a trip followed by recall.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 की एक शिक्षिका स्थानीय डाकघर की सैर की योजना बनाती है। कौन-सा क्रम सैर को सीखने के लिए सबसे उपयोगी बनाएगा?","optionsHi":["डाकघर की सैर → बच्चे घर पर उस पर लंबा निबंध लिखें → अगले दिन निबंध पर लिखित परीक्षा","पाठ्यपुस्तक का अध्याय पढ़ना → डाकघर की सैर → बच्चे शिक्षिका द्वारा लिखवाया गया नोट अपनी कॉपियों में उतारें","बिना किसी तैयारी के सैर ताकि बच्चे जो देखें उस सब से चकित हों → उन्हें जो याद है उस पर अचानक कक्षा-परीक्षा","बच्चे तय करें कि वे क्या पता लगाना चाहते हैं → सैर के दौरान अवलोकन और साक्षात्कार करें → बाद में साझा करें, दर्ज करें और चिंतन करें"],"explanationHi":"क्षेत्र-भ्रमण तब काम करता है जब उसमें भ्रमण-पूर्व चरण (उद्देश्य और प्रश्न), सक्रिय भ्रमण चरण और साझा करने तथा चिंतन का भ्रमण-पश्चात चरण हो। अन्य क्रम उसे एक यात्रा और उसके बाद स्मरण तक सीमित कर देते हैं।"},
  {"id":"cdp-pedagogy-subjects-402","question":"Class 5 children enjoyed a trip to a dairy farm, but the next week few of them could explain anything they had seen. The most likely reason is that:","options":["the visit had no pre-visit discussion of purpose and no follow-up discussion afterwards","children of this age are still too young to learn much from field visits outside school","a dairy farm is not related to any EVS theme, so children had nothing to connect it to","the visit was too short for the children to see the cows and the milking properly"],"answer":0,"explanation":"Without a purpose before and reflection after, a visit stays an outing. Dairy links to the ‘Food’ theme, and Class 5 children learn well from visits that are properly planned.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 5 के बच्चों को डेयरी फ़ार्म की सैर में आनंद आया, लेकिन अगले सप्ताह उनमें से कम ही अपने देखे हुए के बारे में कुछ समझा पाए। सबसे संभावित कारण यह है कि:","optionsHi":["सैर से पहले उद्देश्य पर कोई चर्चा नहीं थी और बाद में कोई अनुवर्ती चर्चा नहीं हुई","इस आयु के बच्चे अभी विद्यालय के बाहर क्षेत्र-भ्रमणों से बहुत कुछ सीखने के लिए बहुत छोटे हैं","डेयरी फ़ार्म का किसी EVS थीम से कोई संबंध नहीं है, इसलिए बच्चों के पास जोड़ने के लिए कुछ नहीं था","सैर बहुत छोटी थी, इसलिए बच्चे गायों और दूध निकालने को ठीक से नहीं देख पाए"],"explanationHi":"पहले उद्देश्य और बाद में चिंतन के बिना सैर बस एक सैर बनी रहती है। डेयरी ‘भोजन’ थीम से जुड़ती है, और कक्षा 5 के बच्चे उन भ्रमणों से अच्छा सीखते हैं जो ठीक से नियोजित हों।"},
  {"id":"cdp-pedagogy-subjects-403","question":"Class 5 children survey 30 households in their basti to find which fuel each family uses for cooking: LPG, firewood or cow-dung cakes. Which follow-up question best moves the survey from collecting data to analysing it?","options":["How many families in the basti use LPG, and how many use each of the other two fuels?","Why do some families still use firewood though they know the smoke harms them?","Name the three fuels found in the survey and write one use of each fuel.","Draw an LPG cylinder and a chulha in your notebook and label their parts."],"answer":1,"explanation":"Asking ‘why’ about a pattern in the data calls for reasoning about cost, access and choice: analysis. Counting is recording, naming is recall and drawing is expression.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 5 के बच्चे अपनी बस्ती के 30 घरों का सर्वेक्षण करते हैं कि हर परिवार खाना पकाने के लिए कौन-सा ईंधन उपयोग करता है: LPG, लकड़ी या उपले। कौन-सा अनुवर्ती प्रश्न सर्वेक्षण को आँकड़े इकट्ठा करने से उनका विश्लेषण करने की ओर सबसे अच्छी तरह ले जाता है?","optionsHi":["बस्ती में कितने परिवार LPG का उपयोग करते हैं, और अन्य दो ईंधनों में से हर एक का कितने?","कुछ परिवार अब भी लकड़ी क्यों जलाते हैं, जबकि वे जानते हैं कि धुआँ हानिकारक है?","सर्वेक्षण में मिले तीन ईंधनों के नाम बताइए और हर ईंधन का एक उपयोग लिखिए।","अपनी कॉपी में LPG सिलेंडर और चूल्हे का चित्र बनाइए और उनके भाग नामांकित कीजिए।"],"explanationHi":"आँकड़ों के किसी पैटर्न के बारे में ‘क्यों’ पूछना लागत, पहुँच और चुनाव पर तर्क माँगता है: यही विश्लेषण है। गिनना अभिलेखन है, नाम बताना स्मरण है और चित्र बनाना अभिव्यक्ति है।"},
  {"id":"cdp-pedagogy-subjects-404","question":"Before Class 4 children test which substances dissolve in water, the teacher hands out a worksheet with the ‘result’ column already filled in. The main problem with this is that it:","options":["wastes paper that could be used for other activities, since children could simply write in their notebooks","makes the activity too difficult for slower learners, who cannot read the filled-in column","turns the experiment into a confirmation exercise, discouraging real prediction and observation","is against the rule that worksheets must not be used in EVS classes at the primary stage"],"answer":2,"explanation":"If the answers are given, children copy rather than observe, and any surprising observation is treated as an error. Worksheets themselves are fine; it is the pre-filled results that defeat inquiry.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 के बच्चों के यह परखने से पहले कि कौन-से पदार्थ पानी में घुलते हैं, शिक्षिका एक अभ्यास-पत्र देती है जिसमें ‘परिणाम’ वाला स्तंभ पहले से भरा हुआ है। इसमें मुख्य समस्या यह है कि यह:","optionsHi":["उस कागज़ को बर्बाद करता है जो अन्य गतिविधियों में काम आ सकता था, क्योंकि बच्चे बस अपनी कॉपियों में लिख सकते थे","गतिविधि को धीमे अधिगमकर्ताओं के लिए बहुत कठिन बना देता है, जो भरे हुए स्तंभ को पढ़ नहीं सकते","प्रयोग को पुष्टि का अभ्यास बना देता है, जो वास्तविक पूर्वानुमान और अवलोकन को हतोत्साहित करता है","इस नियम के विरुद्ध है कि प्राथमिक स्तर पर EVS की कक्षाओं में अभ्यास-पत्रों का उपयोग नहीं होना चाहिए"],"explanationHi":"यदि उत्तर दिए गए हों, तो बच्चे अवलोकन करने के बजाय नकल करते हैं, और कोई आश्चर्यजनक अवलोकन त्रुटि माना जाता है। अभ्यास-पत्र स्वयं ठीक हैं; पहले से भरे परिणाम अन्वेषण को विफल करते हैं।"},
  {"id":"cdp-pedagogy-subjects-405","question":"Before soaking moong seeds, a teacher asks Class 3 children to predict what will happen to soaked and dry seeds over three days and to write their guesses. Asking for predictions first mainly helps to:","options":["find out who guesses correctly so that marks can be given for all the right predictions made","make children’s existing ideas explicit so that they can test them against what they see","save time, because children who have predicted need not observe the seeds closely","make the lesson enjoyable and lively, which is the only real purpose of predicting"],"answer":1,"explanation":"A prediction surfaces the child’s current idea and creates a reason to observe; comparing prediction and result is where learning happens. It is not for grading guesses.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"मूँग के बीजों को भिगोने से पहले एक शिक्षक कक्षा 3 के बच्चों से तीन दिनों में भीगे और सूखे बीजों का क्या होगा, इसका पूर्वानुमान लगाने और अपने अनुमान लिखने को कहता है। पहले पूर्वानुमान माँगना मुख्य रूप से किसमें सहायक है?","optionsHi":["यह पता लगाना कि कौन सही अनुमान लगाता है ताकि सभी सही पूर्वानुमानों के लिए अंक दिए जा सकें","बच्चों के मौजूदा विचारों को स्पष्ट करना ताकि वे उन्हें अपने देखे हुए के विरुद्ध परख सकें","समय बचाना, क्योंकि जिन बच्चों ने पूर्वानुमान लगा लिया है उन्हें बीजों को ध्यान से देखने की आवश्यकता नहीं","पाठ को आनंददायक और जीवंत बनाना, जो पूर्वानुमान लगाने का एकमात्र वास्तविक उद्देश्य है"],"explanationHi":"पूर्वानुमान बच्चे के वर्तमान विचार को सतह पर लाता है और अवलोकन का कारण बनाता है; पूर्वानुमान और परिणाम की तुलना में ही अधिगम होता है। यह अनुमानों को अंक देने के लिए नहीं है।"},
  {"id":"cdp-pedagogy-subjects-406","question":"To find out whether plants need sunlight, Class 5 children keep one potted plant in sunlight and water it daily, and another in a dark cupboard and water it once a week. After ten days the cupboard plant is wilted. The most serious flaw in this investigation is that:","options":["the plants should have been of different kinds to make the comparison more interesting","the teacher should have done it as a demonstration instead, to save time and avoid mess","the children should have read the answer in the textbook first, so they knew what to expect","more than one condition was changed, so the wilting cannot be put down to darkness alone"],"answer":3,"explanation":"Light and water were both varied, so it is not a fair test. Using different kinds of plants would add yet another variable, which is the opposite of what is needed.","difficulty":"very-hard","source":"CTET Paper 1 · NVS PRT","questionHi":"यह पता लगाने के लिए कि पौधों को सूर्य के प्रकाश की आवश्यकता है या नहीं, कक्षा 5 के बच्चे एक गमले का पौधा धूप में रखते हैं और उसे रोज़ पानी देते हैं, और दूसरा एक अँधेरी अलमारी में रखते हैं और उसे सप्ताह में एक बार पानी देते हैं। दस दिन बाद अलमारी का पौधा मुरझा गया है। इस अन्वेषण में सबसे गंभीर कमी यह है कि:","optionsHi":["तुलना को अधिक रोचक बनाने के लिए पौधे अलग-अलग प्रकार के होने चाहिए थे","शिक्षक को समय बचाने और गंदगी से बचने के लिए इसे प्रदर्शन के रूप में करना चाहिए था","बच्चों को पहले पाठ्यपुस्तक में उत्तर पढ़ लेना चाहिए था, ताकि वे जानें कि क्या अपेक्षा करें","एक से अधिक स्थितियाँ बदली गईं, इसलिए मुरझाने का कारण अकेले अँधेरे को नहीं बताया जा सकता"],"explanationHi":"प्रकाश और पानी दोनों बदले गए, इसलिए यह निष्पक्ष परीक्षण नहीं है। अलग-अलग प्रकार के पौधे उपयोग करने से एक और चर जुड़ जाता, जो आवश्यकता के विपरीत है।"},
  {"id":"cdp-pedagogy-subjects-407","question":"Class 5 children spend four weeks on ‘Trees of our school’: they choose questions, measure trunk girths, note birds and insects on each tree, interview the gardener and present a booklet. What mainly makes this a project rather than a one-period activity?","options":["It is a long investigation of a real question, planned and done mainly by the children, ending in a shared product","It takes place outside the classroom, in the school grounds, so that learning moves well beyond the four walls of the class","It uses tools such as measuring tapes, notebooks and interviews that ordinary lessons do not use","It is assessed with marks at the end, on the basis of the booklet that each group presents to the class"],"answer":0,"explanation":"Kilpatrick’s project method stresses purposeful, child-directed work on a real problem over time. Going outdoors, using tools or marking can happen in ordinary activities too.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के बच्चे ‘हमारे विद्यालय के पेड़’ पर चार सप्ताह बिताते हैं: वे प्रश्न चुनते हैं, तनों की मोटाई मापते हैं, हर पेड़ पर पक्षियों और कीटों को नोट करते हैं, माली का साक्षात्कार लेते हैं और एक पुस्तिका प्रस्तुत करते हैं। इसे एक कालांश की गतिविधि के बजाय परियोजना मुख्य रूप से क्या बनाता है?","optionsHi":["यह किसी वास्तविक प्रश्न की लंबी जाँच है, जिसकी योजना और कार्यान्वयन मुख्यतः बच्चे करते हैं, और जो साझा उत्पाद पर समाप्त होती है","यह कक्षा के बाहर, विद्यालय के प्रांगण में होती है, जिससे सीखना कक्षा की चार दीवारों से बहुत आगे चला जाता है","यह मापने के फ़ीते, कॉपियों और साक्षात्कार जैसे उन उपकरणों का उपयोग करती है जो सामान्य पाठ नहीं करते","अंत में उसका आकलन अंकों से होता है, उस पुस्तिका के आधार पर जो हर समूह कक्षा के सामने प्रस्तुत करता है"],"explanationHi":"किलपैट्रिक की प्रोजेक्ट विधि समय के साथ किसी वास्तविक समस्या पर उद्देश्यपूर्ण, बाल-निर्देशित कार्य पर ज़ोर देती है। बाहर जाना, उपकरणों का उपयोग या अंक देना सामान्य गतिविधियों में भी हो सकता है।"},
  {"id":"cdp-pedagogy-subjects-408","question":"Consider these statements about classroom discussion in EVS: I. It helps children put their ideas into words and revise them. II. The teacher should give the correct answer at the start so that the discussion stays on track. III. Disagreements among children can be used as a resource for learning. Which are correct?","options":["I only","I and II only","I and III only","I, II and III all"],"answer":2,"explanation":"Giving the ‘right answer’ first closes the discussion; differing views are what drive reasoning. Statements I and III describe the role of discussion in EVS.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"EVS में कक्षा-चर्चा के बारे में इन कथनों पर विचार कीजिए: I. यह बच्चों को अपने विचार शब्दों में व्यक्त करने और उन्हें संशोधित करने में मदद करती है। II. शिक्षक को शुरुआत में सही उत्तर दे देना चाहिए ताकि चर्चा पटरी पर रहे। III. बच्चों के बीच असहमतियों का उपयोग अधिगम के संसाधन के रूप में किया जा सकता है। कौन-से सही हैं?","optionsHi":["केवल I","केवल I और II","केवल I और III","I, II और III सभी"],"explanationHi":"पहले ‘सही उत्तर’ देना चर्चा को बंद कर देता है; भिन्न मत ही तर्क को आगे बढ़ाते हैं। कथन I और III EVS में चर्चा की भूमिका का वर्णन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-409","question":"Class 3 children cut pictures of animals from old magazines and paste them in a scrapbook. The teacher then collects the scrapbooks and gives stars for neatness. The best evaluation of this activity is that it is:","options":["an ideal EVS activity, because children were busy with their hands and clearly enjoyed the work","inappropriate, because cutting and pasting is an art activity and has no place in EVS","complete as it is, since neatness is the main learning indicator for EVS at this stage","hands-on but not minds-on; it needs sorting, questioning or explaining to become learning"],"answer":3,"explanation":"Cutting and pasting can be a good start, but without children grouping animals, asking questions or giving reasons, there is little thinking. Neatness is not an EVS indicator.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 3 के बच्चे पुरानी पत्रिकाओं से जानवरों के चित्र काटकर स्क्रैपबुक में चिपकाते हैं। फिर शिक्षिका स्क्रैपबुक इकट्ठी करती है और सफ़ाई के लिए सितारे देती है। इस गतिविधि का सबसे अच्छा मूल्यांकन है कि यह:","optionsHi":["एक आदर्श EVS गतिविधि है, क्योंकि बच्चे हाथों से व्यस्त थे और उन्होंने स्पष्ट रूप से काम का आनंद लिया","अनुपयुक्त है, क्योंकि काटना और चिपकाना कला की गतिविधि है और EVS में इसका कोई स्थान नहीं है","जैसी है वैसी पूर्ण है, क्योंकि इस चरण पर EVS के लिए सफ़ाई ही मुख्य अधिगम-संकेतक है","हाथों से करने वाली है लेकिन मन से सोचने वाली नहीं; इसे अधिगम बनने के लिए छँटाई, प्रश्न पूछने या समझाने की आवश्यकता है"],"explanationHi":"काटना और चिपकाना अच्छी शुरुआत हो सकती है, लेकिन बच्चों के जानवरों को समूहों में बाँटे, प्रश्न पूछे या कारण दिए बिना, सोच बहुत कम है। सफ़ाई EVS का संकेतक नहीं है।"},
  {"id":"cdp-pedagogy-subjects-410","question":"Class 4 children role-play a family whose village will be submerged by a new dam. The main learning aim of this role play is to help children:","options":["develop their acting and public speaking skills so that the role play can be staged at the school annual day","understand how displaced people feel and see that development affects different people differently","memorise the names and locations of India's major dams and the rivers on which they are built","conclude that all dams are harmful to people and should therefore be opposed by everyone"],"answer":1,"explanation":"Role play builds empathy and shows several perspectives. Pushing a single conclusion (‘all dams are bad’) would be indoctrination, not EVS.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 के बच्चे ऐसे परिवार का भूमिका-निर्वाह करते हैं जिसका गाँव नए बाँध से डूबने वाला है। इस भूमिका-निर्वाह का मुख्य अधिगम-उद्देश्य बच्चों की किसमें सहायता करना है?","optionsHi":["अपने अभिनय और सार्वजनिक वक्तृत्व कौशल का विकास करना ताकि भूमिका-निर्वाह विद्यालय के वार्षिकोत्सव में मंचित किया जा सके","यह समझना कि विस्थापित लोग कैसा महसूस करते हैं और देखना कि विकास अलग-अलग लोगों को अलग-अलग तरह से प्रभावित करता है","भारत के प्रमुख बाँधों और उन नदियों के नाम और स्थान याद करना जिन पर वे बने हैं","यह निष्कर्ष निकालना कि सभी बाँध लोगों के लिए हानिकारक हैं और इसलिए सभी को उनका विरोध करना चाहिए"],"explanationHi":"भूमिका-निर्वाह सहानुभूति निर्मित करता है और कई दृष्टिकोण दिखाता है। एक ही निष्कर्ष (‘सभी बाँध बुरे हैं’) थोपना विचारधारा थोपना होगा, EVS नहीं।"},
  {"id":"cdp-pedagogy-subjects-411","question":"Class 5 children draw the shape of the moon every night for a month. Later, using their drawings, they say what the moon will look like a week from today. In NCERT’s list of EVS learning indicators, this final step mainly shows:","options":["Observation and recording, through drawing nightly","Classification, through sorting the moon's shapes","Analysis, through predicting from a pattern","Expression, through drawing and describing the moon"],"answer":2,"explanation":"Drawing the moon nightly is observation and recording, but using the records to predict is analysis (predicting, inferring, hypothesising). That is the trap.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 5 के बच्चे एक माह तक हर रात चाँद का आकार बनाते हैं। बाद में, अपने चित्रों का उपयोग करके, वे बताते हैं कि आज से एक सप्ताह बाद चाँद कैसा दिखेगा। EVS अधिगम के NCERT संकेतकों की सूची में, यह अंतिम चरण मुख्य रूप से क्या दर्शाता है?","optionsHi":["अवलोकन और अभिलेखन, हर रात चित्र बनाने के माध्यम से","वर्गीकरण, चाँद के आकारों को छाँटने के माध्यम से","विश्लेषण, किसी पैटर्न से पूर्वानुमान लगाने के माध्यम से","अभिव्यक्ति, चाँद का चित्र बनाने और वर्णन करने के माध्यम से"],"explanationHi":"हर रात चाँद का चित्र बनाना अवलोकन और अभिलेखन है, लेकिन अभिलेखों का उपयोग पूर्वानुमान लगाने के लिए करना विश्लेषण (पूर्वानुमान, अनुमान, परिकल्पना) है। यही जाल है।"},
  {"id":"cdp-pedagogy-subjects-412","question":"Assertion (A): In an EVS experiment, a result that does not match the children’s expectation can be a valuable learning moment. Reason (R): Understanding grows when learners examine why what they observe differs from what they expected. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Mismatch between expectation and observation creates cognitive conflict, which is what pushes children to revise their ideas. R directly explains A.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): किसी EVS प्रयोग में, ऐसा परिणाम जो बच्चों की अपेक्षा से मेल नहीं खाता, एक मूल्यवान अधिगम-क्षण हो सकता है। कारण (R): समझ तब बढ़ती है जब अधिगमकर्ता यह जाँचते हैं कि वे जो देखते हैं वह उनकी अपेक्षा से अलग क्यों है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"अपेक्षा और अवलोकन के बीच बेमेल संज्ञानात्मक संघर्ष पैदा करता है, जो बच्चों को अपने विचार संशोधित करने के लिए प्रेरित करता है। R सीधे A की व्याख्या करता है।"},
  {"id":"cdp-pedagogy-subjects-413","question":"A government school has only one magnifying glass, and the Class 4 teacher wants all children to observe the parts of a flower. The best approach is to:","options":["show the flower under the glass herself and describe each part clearly and slowly to the whole class","drop the activity, since there are not enough magnifying glasses for every child to use","let small groups take turns, each with a specific thing to look for, and pool their findings","show textbook pictures instead, which are clearer and more detailed than real flowers"],"answer":2,"explanation":"Rotating groups with focused tasks lets every child observe and turns scarcity into collaboration. Demonstration or pictures replace the child’s own observation.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"एक सरकारी विद्यालय में केवल एक आवर्धक लेंस है, और कक्षा 4 का शिक्षक चाहता है कि सभी बच्चे फूल के भागों का अवलोकन करें। सबसे अच्छा उपागम है:","optionsHi":["स्वयं लेंस के नीचे फूल दिखाना और पूरी कक्षा को हर भाग स्पष्ट और धीरे-धीरे समझाना","गतिविधि छोड़ देना, क्योंकि हर बच्चे के उपयोग के लिए पर्याप्त आवर्धक लेंस नहीं हैं","छोटे समूहों को बारी-बारी से लेने देना, हर एक के पास देखने के लिए एक विशिष्ट चीज़ हो, और उनके निष्कर्ष एकत्र करना","इसके बजाय पाठ्यपुस्तक के चित्र दिखाना, जो असली फूलों से अधिक स्पष्ट और विस्तृत होते हैं"],"explanationHi":"केंद्रित कार्यों के साथ समूहों का बारी-बारी से घूमना हर बच्चे को अवलोकन करने देता है और कमी को सहयोग में बदल देता है। प्रदर्शन या चित्र बच्चे के अपने अवलोकन का स्थान ले लेते हैं।"},
  {"id":"cdp-pedagogy-subjects-414","question":"A Class 5 teacher is planning a visit to a temple on a hillside. One child in the class uses crutches. The most appropriate step is to:","options":["leave the child in school with a worksheet on the same topic, so that he does not miss out","choose an accessible site or plan the route and roles so that the child takes part fully","ask the parents to decide whether the child should come, since they know his needs best","cancel the visit altogether so that no child in the class feels left out or different"],"answer":1,"explanation":"Inclusion means planning so that every child participates, not excluding one child or depriving everyone. Leaving the decision to parents avoids the teacher’s responsibility to adapt.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 का एक शिक्षक पहाड़ी की एक ढलान पर स्थित मंदिर की सैर की योजना बना रहा है। कक्षा का एक बच्चा बैसाखियों का उपयोग करता है। सबसे उपयुक्त कदम है:","optionsHi":["बच्चे को उसी विषय के अभ्यास-पत्र के साथ विद्यालय में छोड़ देना, ताकि वह कुछ छूट न जाए","कोई सुलभ स्थल चुनना या मार्ग और भूमिकाओं की योजना बनाना ताकि बच्चा पूरी तरह भाग ले सके","अभिभावकों से तय करने को कहना कि बच्चा आए या नहीं, क्योंकि वे उसकी आवश्यकताओं को सबसे अच्छी तरह जानते हैं","सैर पूरी तरह रद्द कर देना ताकि कक्षा के किसी बच्चे को छूटा या अलग न लगे"],"explanationHi":"समावेशन का अर्थ है इस प्रकार योजना बनाना कि हर बच्चा भाग ले सके, किसी एक बच्चे को बाहर करना या सबको वंचित करना नहीं। निर्णय अभिभावकों पर छोड़ना शिक्षक की अनुकूलन करने की ज़िम्मेदारी से बचना है।"},
  {"id":"cdp-pedagogy-subjects-415","question":"Class 4 children will interview a local mason about how houses are built. Which preparation is most important?","options":["The teacher writes all the questions in advance so that nothing goes wrong on the day","Children memorise the answers the mason is likely to give, so the interview runs smoothly","Children read the textbook chapter thoroughly so that they need not ask much","Children discuss in groups what they want to find out and frame their own questions"],"answer":3,"explanation":"Children’s own questions give the interview purpose and build questioning skill. If the teacher writes the questions or children ‘pre-learn’ answers, the inquiry is lost.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 4 के बच्चे घर कैसे बनते हैं, इस बारे में स्थानीय राजमिस्त्री का साक्षात्कार लेंगे। कौन-सी तैयारी सबसे महत्त्वपूर्ण है?","optionsHi":["शिक्षक सभी प्रश्न पहले से लिख देता है ताकि उस दिन कुछ गलत न हो","बच्चे वे उत्तर याद कर लेते हैं जो राजमिस्त्री के देने की संभावना है, ताकि साक्षात्कार सुचारु चले","बच्चे पाठ्यपुस्तक का अध्याय ध्यान से पढ़ लेते हैं ताकि उन्हें अधिक पूछने की आवश्यकता न पड़े","बच्चे समूहों में चर्चा करते हैं कि वे क्या पता लगाना चाहते हैं और अपने प्रश्न स्वयं बनाते हैं"],"explanationHi":"बच्चों के अपने प्रश्न साक्षात्कार को उद्देश्य देते हैं और प्रश्न पूछने का कौशल निर्मित करते हैं। यदि शिक्षक प्रश्न लिखता है या बच्चे उत्तर ‘पहले से सीख लेते’ हैं, तो अन्वेषण खो जाता है।"},
  {"id":"cdp-pedagogy-subjects-416","question":"Class 5 children survey their own classmates about their favourite food and conclude, ‘Children of India like noodles best.’ The teacher’s most useful response is to:","options":["discuss whether a conclusion about 40 classmates can be stretched to all children in India","accept the conclusion, since the data were collected honestly and counted correctly","say that noodles are junk food, so the survey result must be wrong and should be changed","ask them to repeat the same survey in the same class to make sure that the result is really reliable"],"answer":0,"explanation":"The flaw is over-generalising from a small, particular group. Repeating it in the same class keeps the same bias, and judging the food misses the reasoning issue.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 5 के बच्चे अपने सहपाठियों से उनके पसंदीदा भोजन के बारे में सर्वेक्षण करते हैं और निष्कर्ष निकालते हैं, ‘भारत के बच्चों को नूडल्स सबसे अधिक पसंद हैं।’ शिक्षक की सबसे उपयोगी प्रतिक्रिया है:","optionsHi":["इस पर चर्चा करना कि क्या 40 सहपाठियों के बारे में निष्कर्ष को भारत के सभी बच्चों तक खींचा जा सकता है","निष्कर्ष स्वीकार करना, क्योंकि आँकड़े ईमानदारी से इकट्ठा किए गए और सही गिने गए","यह कहना कि नूडल्स जंक फ़ूड हैं, इसलिए सर्वेक्षण का परिणाम गलत होगा और उसे बदलना चाहिए","उनसे उसी कक्षा में वही सर्वेक्षण दोहराने को कहना ताकि परिणाम वास्तव में विश्वसनीय हो"],"explanationHi":"कमी एक छोटे, विशिष्ट समूह से अतिसामान्यीकरण करने की है। उसी कक्षा में दोहराने से वही पक्षपात रहता है, और भोजन का मूल्यांकन तर्क के मुद्दे को चूक जाता है।"},
  {"id":"cdp-pedagogy-subjects-417","question":"Which sequence best reflects experiential learning in a Class 4 EVS lesson on houses?","options":["The teacher lists the properties of mud, brick and cement, and children copy them neatly into their notebooks","Children build a mud house model, test it under sprinkled ‘rain’, think about why it fell and redesign it","Children watch a video on different kinds of houses and then answer ten objective questions","Children learn a poem about houses by heart and recite it together at the morning assembly"],"answer":1,"explanation":"Doing, observing, reflecting and trying again is the experiential cycle (Dewey, Kolb). The others are transmission or recall.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 के EVS के घरों वाले पाठ में कौन-सा क्रम अनुभवजन्य अधिगम को सबसे अच्छी तरह दर्शाता है?","optionsHi":["शिक्षक मिट्टी, ईंट और सीमेंट के गुण सूचीबद्ध करता है, और बच्चे उन्हें साफ़-साफ़ अपनी कॉपियों में उतारते हैं","बच्चे मिट्टी के घर का मॉडल बनाते हैं, उसे छिड़की गई ‘बारिश’ में परखते हैं, सोचते हैं कि वह क्यों गिरा, और उसका नया डिज़ाइन बनाते हैं","बच्चे अलग-अलग प्रकार के घरों पर वीडियो देखते हैं और फिर दस वस्तुनिष्ठ प्रश्नों के उत्तर देते हैं","बच्चे घरों पर एक कविता कंठस्थ करते हैं और सुबह की सभा में साथ मिलकर सुनाते हैं"],"explanationHi":"करना, अवलोकन करना, चिंतन करना और फिर से प्रयास करना अनुभवजन्य चक्र है (डेवी, कोल्ब)। अन्य संप्रेषण या स्मरण हैं।"},
  {"id":"cdp-pedagogy-subjects-418","question":"A Class 4 teacher invites a local basket weaver, who shows how baskets are made, and then children try weaving with paper strips. From an EVS point of view, the most important outcome is:","options":["early vocational training so that the children can earn a living from this craft later on in life","producing baskets of good quality that can be sold at the school fair to raise funds","a grade in art education for the neatness and design of the woven paper strips","respect for the skill and work of artisans, and an understanding of the materials they use"],"answer":3,"explanation":"‘Things We Make and Do’ aims at valuing work and workers and understanding materials and processes. It is not vocational training or a sales activity.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 4 का एक शिक्षक स्थानीय टोकरी-बुनकर को आमंत्रित करता है, जो दिखाता है कि टोकरियाँ कैसे बनती हैं, और फिर बच्चे कागज़ की पट्टियों से बुनने का प्रयास करते हैं। EVS की दृष्टि से, सबसे महत्त्वपूर्ण परिणाम है:","optionsHi":["प्रारंभिक व्यावसायिक प्रशिक्षण ताकि बच्चे आगे चलकर जीवन में इस शिल्प से आजीविका कमा सकें","अच्छी गुणवत्ता की टोकरियाँ बनाना जो विद्यालय मेले में धन जुटाने के लिए बेची जा सकें","बुनी हुई कागज़ की पट्टियों की सफ़ाई और डिज़ाइन के लिए कला-शिक्षा में एक ग्रेड","कारीगरों के कौशल और काम के प्रति सम्मान, और जिन सामग्रियों का वे उपयोग करते हैं उनकी समझ"],"explanationHi":"‘हम क्या बनाते और करते हैं’ का उद्देश्य काम और कामगारों को महत्त्व देना और सामग्रियों तथा प्रक्रियाओं को समझना है। यह व्यावसायिक प्रशिक्षण या बिक्री की गतिविधि नहीं है।"},
  {"id":"cdp-pedagogy-subjects-419","question":"Class 3 children predict that a large log will sink and a small iron nail will float, because ‘heavy things sink and light things float’. Testing shows the opposite. The teacher’s best next step is to:","options":["write the definition of density on the board for children to copy and learn by heart","tell them their prediction was wrong and give them the correct scientific answer straight away","ask why their prediction failed, and let them test big and small pieces of one material","move on, since floating and sinking is too difficult a topic for Class 3 children"],"answer":2,"explanation":"Testing big and small pieces of the same material challenges the ‘heavy sinks’ idea with fresh evidence; asking ‘why’ invites revision. A copied definition does not change the underlying idea.","difficulty":"hard","source":"CTET Paper 1 · NVS PRT","questionHi":"कक्षा 3 के बच्चे पूर्वानुमान लगाते हैं कि एक बड़ा लट्ठा डूबेगा और लोहे की छोटी कील तैरेगी, क्योंकि ‘भारी चीज़ें डूबती हैं और हल्की चीज़ें तैरती हैं’। परीक्षण उलटा दिखाता है। शिक्षक का सबसे अच्छा अगला कदम है:","optionsHi":["घनत्व की परिभाषा श्यामपट्ट पर लिखना ताकि बच्चे उसे उतारें और कंठस्थ करें","उन्हें बताना कि उनका पूर्वानुमान गलत था और तुरंत सही वैज्ञानिक उत्तर देना","पूछना कि उनका पूर्वानुमान क्यों विफल हुआ, और उन्हें एक ही पदार्थ के बड़े और छोटे टुकड़ों का परीक्षण करने देना","आगे बढ़ जाना, क्योंकि तैरना और डूबना कक्षा 3 के बच्चों के लिए बहुत कठिन विषय है"],"explanationHi":"एक ही पदार्थ के बड़े और छोटे टुकड़ों का परीक्षण ‘भारी डूबता है’ के विचार को नए प्रमाण से चुनौती देता है; ‘क्यों’ पूछना संशोधन को आमंत्रित करता है। उतारी गई परिभाषा अंतर्निहित विचार को नहीं बदलती।"},
  {"id":"cdp-pedagogy-subjects-420","question":"Which of the following is NOT a strength of using surveys in primary EVS?","options":["Children learn to collect and record information from people around them","Surveys give exact conclusions that are true for society everywhere","Children learn to organise data in tables and simple graphs","Surveys connect classroom learning with the community"],"answer":1,"explanation":"A small class survey describes only the group surveyed; claiming universal truth is a misuse. The other three are real benefits.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"प्राथमिक EVS में सर्वेक्षणों के उपयोग की निम्नलिखित में से कौन-सी एक शक्ति नहीं है?","optionsHi":["बच्चे अपने आसपास के लोगों से जानकारी इकट्ठा करना और दर्ज करना सीखते हैं","सर्वेक्षण सटीक निष्कर्ष देते हैं जो हर जगह समाज के लिए सत्य हैं","बच्चे आँकड़ों को तालिकाओं और सरल आलेखों में व्यवस्थित करना सीखते हैं","सर्वेक्षण कक्षा के अधिगम को समुदाय से जोड़ते हैं"],"explanationHi":"कक्षा का एक छोटा सर्वेक्षण केवल उसी समूह का वर्णन करता है जिसका सर्वेक्षण हुआ; सार्वभौमिक सत्य का दावा करना दुरुपयोग है। अन्य तीन वास्तविक लाभ हैं।"},
  {"id":"cdp-pedagogy-subjects-421","question":"A teacher says, ‘Since EVS is activity-based, I will not intervene at all. Children must discover everything on their own.’ The best critique of this view is that:","options":["unguided discovery can leave misconceptions in place; the teacher should guide with questions and scaffolding","the teacher should instead explain everything first and only then give activities to confirm it","activities are useful only for children who are already good at EVS and can work on their own","the statement is correct, because constructivism forbids any form of teacher intervention in children's learning"],"answer":0,"explanation":"Constructivism does not mean leaving children alone; Vygotskian scaffolding and guided questioning help children reach ideas they would not reach unaided. Telling everything first is the opposite error.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षक कहता है, ‘चूँकि EVS गतिविधि-आधारित है, मैं बिल्कुल हस्तक्षेप नहीं करूँगा। बच्चों को सब कुछ अपने आप खोजना चाहिए।’ इस दृष्टिकोण की सबसे अच्छी आलोचना यह है कि:","optionsHi":["निर्देशन-रहित खोज भ्रांत धारणाओं को बनाए रख सकती है; शिक्षक को प्रश्नों और पाड़ के साथ मार्गदर्शन करना चाहिए","शिक्षक को इसके बजाय पहले सब कुछ समझाना चाहिए और उसके बाद ही पुष्टि के लिए गतिविधियाँ देनी चाहिए","गतिविधियाँ केवल उन बच्चों के लिए उपयोगी हैं जो पहले से EVS में अच्छे हैं और अपने आप कार्य कर सकते हैं","कथन सही है, क्योंकि रचनावाद बच्चों के सीखने में शिक्षक के किसी भी प्रकार के हस्तक्षेप को वर्जित करता है"],"explanationHi":"रचनावाद का अर्थ बच्चों को अकेला छोड़ देना नहीं है; वाइगोत्स्कीय पाड़ और निर्देशित प्रश्न बच्चों को ऐसे विचारों तक पहुँचने में मदद करते हैं जहाँ वे अकेले नहीं पहुँच पाते। पहले सब कुछ बता देना उलटी त्रुटि है।"},
  {"id":"cdp-pedagogy-subjects-422","question":"During EVS group work on measuring rainfall, a teacher notices that one confident child does all the work while others watch. The most effective strategy is to:","options":["make the confident child work alone from now on so that the others in the group finally get a fair chance to do the work","let the groups continue as they are, since the task is getting done and the results are correct","replace group work with individual worksheets so that every child has to do the measuring","give each member a role such as measurer, recorder or reporter, rotate the roles, and check individual contributions"],"answer":3,"explanation":"Defined, rotating roles and individual accountability are the standard ways to make cooperative learning work. Removing group work loses the benefits of cooperation.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"वर्षा मापने पर EVS के समूह-कार्य के दौरान एक शिक्षक देखता है कि एक आत्मविश्वासी बच्चा सारा काम कर रहा है जबकि अन्य देख रहे हैं। सबसे प्रभावी रणनीति है:","optionsHi":["आत्मविश्वासी बच्चे को अब से अकेले काम करने देना ताकि समूह के अन्य बच्चों को अंततः काम करने का उचित अवसर मिले","समूहों को जैसे हैं वैसे चलने देना, क्योंकि कार्य हो रहा है और परिणाम सही हैं","समूह-कार्य को व्यक्तिगत अभ्यास-पत्रों से बदलना ताकि हर बच्चे को मापना पड़े","प्रत्येक सदस्य को मापक, अभिलेखक या प्रतिवेदक जैसी भूमिका देना, भूमिकाओं को बारी-बारी से बदलना, और व्यक्तिगत योगदान की जाँच करना"],"explanationHi":"परिभाषित, बारी-बारी से बदलने वाली भूमिकाएँ और व्यक्तिगत जवाबदेही सहकारी अधिगम को काम करने योग्य बनाने के मानक तरीके हैं। समूह-कार्य हटाने से सहयोग के लाभ खो जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-423","question":"Two plates with equal water are kept, one in the sun and one in shade. The plate in the sun dries first, and a child concludes, ‘The sun destroys the water.’ The teacher’s best next step is to:","options":["tell the child the word ‘evaporation’ and ask her to learn its textbook definition by heart for the next test","ask where the water could have gone, and let children hold a cold lid over warm water to see drops form","praise the conclusion, since the water did disappear and the child observed it correctly","tell the child that the conclusion is wrong and move on to the next topic in the chapter"],"answer":1,"explanation":"The child holds the idea that water vanishes. An experience in which the ‘lost’ water reappears as droplets challenges it directly, which a new word alone cannot do.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"बराबर पानी वाली दो थालियाँ रखी गई हैं, एक धूप में और एक छाया में। धूप वाली थाली पहले सूख जाती है, और एक बच्ची निष्कर्ष निकालती है, ‘सूरज पानी को नष्ट कर देता है।’ शिक्षक का सबसे अच्छा अगला कदम है:","optionsHi":["बच्ची को शब्द ‘वाष्पन’ बताना और उससे अगली परीक्षा के लिए उसकी पाठ्यपुस्तकीय परिभाषा कंठस्थ करने को कहना","पूछना कि पानी कहाँ जा सकता है, और बच्चों को गर्म पानी के ऊपर ठंडा ढक्कन पकड़कर बूँदें बनते देखने देना","निष्कर्ष की प्रशंसा करना, क्योंकि पानी वास्तव में गायब हो गया और बच्ची ने उसे सही देखा","बच्ची को बताना कि निष्कर्ष गलत है और अध्याय के अगले विषय पर बढ़ जाना"],"explanationHi":"बच्ची यह विचार रखती है कि पानी गायब हो जाता है। ऐसा अनुभव जिसमें ‘खोया’ हुआ पानी बूँदों के रूप में फिर प्रकट होता है, इसे सीधे चुनौती देता है, जो अकेला नया शब्द नहीं कर सकता।"},
  {"id":"cdp-pedagogy-subjects-424","question":"Match each EVS method with its main purpose: 1. Survey 2. Field visit 3. Experiment 4. Role play. a. Testing a prediction under controlled conditions. b. Collecting information from many people. c. Understanding the feelings and viewpoints of others. d. Observing directly in a real setting.","options":["1-d, 2-b, 3-a, 4-c","1-b, 2-a, 3-d, 4-c","1-b, 2-d, 3-a, 4-c","1-c, 2-d, 3-a, 4-b"],"answer":2,"explanation":"Surveys gather information from many people, field visits allow direct observation, experiments test predictions, and role play builds empathy.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"प्रत्येक EVS विधि का उसके मुख्य उद्देश्य से मिलान कीजिए: 1. सर्वेक्षण 2. क्षेत्र-भ्रमण 3. प्रयोग 4. भूमिका-निर्वाह। a. नियंत्रित स्थितियों में किसी पूर्वानुमान को परखना। b. कई लोगों से जानकारी इकट्ठा करना। c. दूसरों की भावनाओं और दृष्टिकोणों को समझना। d. वास्तविक परिवेश में प्रत्यक्ष अवलोकन करना।","optionsHi":["1-d, 2-b, 3-a, 4-c","1-b, 2-a, 3-d, 4-c","1-b, 2-d, 3-a, 4-c","1-c, 2-d, 3-a, 4-b"],"explanationHi":"सर्वेक्षण कई लोगों से जानकारी इकट्ठा करते हैं, क्षेत्र-भ्रमण प्रत्यक्ष अवलोकन की अनुमति देते हैं, प्रयोग पूर्वानुमानों को परखते हैं, और भूमिका-निर्वाह सहानुभूति निर्मित करता है।"},
  {"id":"cdp-pedagogy-subjects-425","question":"Class 5 children grow a kitchen garden over two months as an EVS project. Which evidence best shows what they have learnt?","options":["Their dated observations, the questions they raised and their explanations of changes in a project file","The final height and yield of the plants, which show how well the garden was looked after","How neat, complete and colourful the project file is when it is handed in at the end","Praise from the parents who visited the garden and saw the healthy, well-watered and flowering plants for themselves"],"answer":0,"explanation":"Learning shows in the process: records, questions and reasoning over time. Plant height depends on soil and weather; neatness and praise say little about understanding.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के बच्चे EVS परियोजना के रूप में दो महीने तक रसोई-बगिया उगाते हैं। कौन-सा प्रमाण सबसे अच्छी तरह दिखाता है कि उन्होंने क्या सीखा?","optionsHi":["उनके दिनांकित अवलोकन, उनके उठाए प्रश्न और परियोजना-फ़ाइल में परिवर्तनों की उनकी व्याख्याएँ","पौधों की अंतिम ऊँचाई और उपज, जो दिखाती है कि बगिया की कितनी अच्छी देखभाल की गई","अंत में जमा करते समय परियोजना-फ़ाइल कितनी साफ़, पूर्ण और रंगीन है","अभिभावकों की प्रशंसा, जिन्होंने बगिया देखी और स्वस्थ, अच्छी तरह सींचे और फूलों वाले पौधों को स्वयं देखा"],"explanationHi":"अधिगम प्रक्रिया में दिखता है: समय के साथ अभिलेख, प्रश्न और तर्क। पौधे की ऊँचाई मिट्टी और मौसम पर निर्भर करती है; सफ़ाई और प्रशंसा समझ के बारे में बहुत कम बताती हैं।"},
  {"id":"cdp-pedagogy-subjects-426","question":"A Class VII teacher in Hyderabad takes her section to Golconda Fort. Last year's trip to the same fort became a picnic and students learnt little. What single change would most turn the visit into a learning experience?","options":["Take a larger group this time so that more students benefit from seeing the fort in person","Give students guiding questions and observation tasks before the visit and hold a follow-up discussion","Hire a trained guide so that students hear the full history of the fort in one long and detailed lecture","Allow students to photograph whatever they like during the visit and submit the photos later"],"answer":1,"explanation":"A field trip teaches when it is planned around questions before, focused observation during, and analysis after the visit. A guide's lecture or a free photo collection keeps students passive or aimless.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"हैदराबाद की कक्षा VII की एक शिक्षिका अपने वर्ग को गोलकुंडा किले ले जाती है। पिछले वर्ष उसी किले की सैर पिकनिक बन गई थी और विद्यार्थियों ने कम सीखा। कौन-सा एक परिवर्तन इस भ्रमण को सीखने के अनुभव में सबसे अधिक बदलेगा?","optionsHi":["इस बार बड़ा समूह ले जाना ताकि अधिक विद्यार्थियों को किले को प्रत्यक्ष देखने का लाभ मिले","भ्रमण से पहले विद्यार्थियों को मार्गदर्शक प्रश्न और अवलोकन-कार्य देना और बाद में अनुवर्ती चर्चा करना","प्रशिक्षित गाइड को बुलाना ताकि विद्यार्थी एक लंबे और विस्तृत व्याख्यान में किले का पूरा इतिहास सुनें","विद्यार्थियों को भ्रमण के दौरान जो चाहें फ़ोटो खींचने देना और फ़ोटो बाद में जमा करना"],"explanationHi":"क्षेत्र-भ्रमण तब सिखाता है जब वह पहले प्रश्नों, दौरान केंद्रित अवलोकन और बाद में विश्लेषण के आसपास नियोजित हो। गाइड का व्याख्यान या मनचाही फ़ोटो विद्यार्थियों को निष्क्रिय या लक्ष्यहीन रखते हैं।"},
  {"id":"cdp-pedagogy-subjects-427","question":"After a visit to the vegetable mandi, Class VII students compare the wholesale price of tomatoes they recorded with prices at a shop near the school and discuss why the two differ. This post-visit task mainly develops the ability to:","options":["recall the names of all the vegetables sold in the mandi on that day","draw an accurate, labelled sketch of the layout of the mandi","analyse observations and link them to the concept of a chain of markets","memorise the definition of a wholesale trader for the next class test on markets"],"answer":2,"explanation":"Comparing data from two points in the chain and explaining the gap turns raw observation into conceptual understanding of how goods pass through traders. The other options stay at recall or description.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"सब्ज़ी मंडी की सैर के बाद, कक्षा VII के विद्यार्थी टमाटर के उस थोक मूल्य की तुलना, जो उन्होंने दर्ज किया था, विद्यालय के पास की दुकान के मूल्यों से करते हैं और चर्चा करते हैं कि दोनों में अंतर क्यों है। यह भ्रमण-पश्चात कार्य मुख्य रूप से किस क्षमता का विकास करता है?","optionsHi":["उस दिन मंडी में बिकने वाली सभी सब्ज़ियों के नाम याद करना","मंडी के विन्यास का सटीक, नामांकित रेखाचित्र बनाना","अवलोकनों का विश्लेषण करना और उन्हें बाज़ारों की शृंखला की अवधारणा से जोड़ना","बाज़ारों पर अगली कक्षा-परीक्षा के लिए थोक व्यापारी की परिभाषा याद करना"],"explanationHi":"शृंखला के दो बिंदुओं के आँकड़ों की तुलना करना और अंतर को समझाना कच्चे अवलोकन को इस बात की संप्रत्ययात्मक समझ में बदल देता है कि माल व्यापारियों के बीच से कैसे गुज़रता है। अन्य विकल्प स्मरण या वर्णन पर रुकते हैं।"},
  {"id":"cdp-pedagogy-subjects-428","question":"Which of the following statements about project work in social science are correct?\n1. A good project arises from a question that is real and meaningful to the students.\n2. The teacher should complete the difficult parts so that the final product is of good quality.\n3. Assessment should consider planning, data collection and teamwork, not only the final chart or report.","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 and 3 only"],"answer":3,"explanation":"Projects work when students own a meaningful question and when the process is assessed alongside the product. A teacher doing the hard parts takes away the very learning the project was meant to create.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"सामाजिक विज्ञान में परियोजना कार्य के बारे में निम्नलिखित में से कौन-से कथन सही हैं? 1. अच्छी परियोजना ऐसे प्रश्न से उठती है जो विद्यार्थियों के लिए वास्तविक और सार्थक हो। 2. शिक्षक को कठिन भाग पूरे कर देने चाहिए ताकि अंतिम उत्पाद अच्छी गुणवत्ता का हो। 3. आकलन में योजना, आँकड़े इकट्ठा करना और टीम-कार्य पर विचार किया जाना चाहिए, केवल अंतिम चार्ट या रिपोर्ट पर नहीं।","optionsHi":["केवल 1 और 2","केवल 2 और 3","1, 2 और 3","केवल 1 और 3"],"explanationHi":"परियोजनाएँ तब काम करती हैं जब विद्यार्थी किसी सार्थक प्रश्न के स्वामी हों और प्रक्रिया का आकलन उत्पाद के साथ हो। शिक्षक द्वारा कठिन भाग करना उसी अधिगम को छीन लेता है जिसे परियोजना रचना चाहती थी।"},
  {"id":"cdp-pedagogy-subjects-429","question":"Class VII students in Nagpur talk with their teacher and decide that they want to find out where the water in their homes comes from and why some lanes get less. In Kilpatrick's project method, this stage is called:","options":["Planning","Purposing","Executing","Judging"],"answer":1,"explanation":"Kilpatrick's stages are purposing, planning, executing and judging. Choosing what to find out and why it matters is purposing; deciding how to collect information comes next, under planning.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"नागपुर में कक्षा VII के विद्यार्थी अपनी शिक्षिका से बात करके तय करते हैं कि वे पता लगाना चाहते हैं कि उनके घरों का पानी कहाँ से आता है और कुछ गलियों में कम क्यों आता है। किलपैट्रिक की प्रोजेक्ट विधि में इस चरण को क्या कहते हैं?","optionsHi":["योजना बनाना","प्रयोजन निर्धारित करना (परपज़िंग)","क्रियान्वयन","मूल्यांकन"],"explanationHi":"किलपैट्रिक के चरण हैं: प्रयोजन निर्धारित करना, योजना बनाना, क्रियान्वयन और मूल्यांकन। यह चुनना कि क्या पता लगाना है और क्यों महत्त्वपूर्ण है, प्रयोजन निर्धारण है; जानकारी कैसे इकट्ठा करनी है यह तय करना योजना के अंतर्गत अगला आता है।"},
  {"id":"cdp-pedagogy-subjects-430","question":"During a Class IX discussion on 'Should a factory be set up near our village?', four confident students do all the talking while most others stay silent. What is the best step for the teacher?","options":["End the discussion and give a lecture listing the pros and cons of the factory for the village","Let the four students continue, since they clearly know the topic and keep the whole discussion moving along","Give marks only to students who speak, so that the silent ones are pushed into talking","Set ground rules, move into small groups with assigned roles, and bring each group's view to the class"],"answer":3,"explanation":"Structured small groups with roles such as recorder and reporter widen participation, and ground rules make it safe to speak. Marking speech pressures anxious students without helping them, and a lecture abandons discussion altogether.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"‘क्या हमारे गाँव के पास कारखाना लगना चाहिए?’ पर कक्षा IX की चर्चा के दौरान चार आत्मविश्वासी विद्यार्थी सारी बातचीत करते हैं जबकि अधिकांश अन्य चुप रहते हैं। शिक्षक का सबसे अच्छा कदम क्या है?","optionsHi":["चर्चा समाप्त करना और गाँव के लिए कारखाने के पक्ष-विपक्ष की सूची वाला व्याख्यान देना","चारों विद्यार्थियों को जारी रखने देना, क्योंकि वे स्पष्ट रूप से विषय जानते हैं और पूरी चर्चा को चलाए रखते हैं","केवल बोलने वाले विद्यार्थियों को अंक देना, ताकि चुप रहने वालों को बोलने के लिए बाध्य किया जा सके","नियम तय करना, निर्धारित भूमिकाओं के साथ छोटे समूहों में जाना, और हर समूह का मत कक्षा के सामने लाना"],"explanationHi":"अभिलेखक और प्रतिवेदक जैसी भूमिकाओं वाले संरचित छोटे समूह भागीदारी को विस्तृत करते हैं, और नियम बोलना सुरक्षित बनाते हैं। बोलने पर अंक देना बिना मदद किए चिंतित विद्यार्थियों पर दबाव डालता है, और व्याख्यान चर्चा को ही छोड़ देता है।"},
  {"id":"cdp-pedagogy-subjects-431","question":"Assertion (A): At the end of a class discussion on whether mobile towers should be allowed on school roofs, the teacher should summarise the different viewpoints rather than declare one side the winner.\nReason (R): The purpose of a classroom discussion is to deepen understanding of an issue, not to defeat opponents.","options":["Both A and R are true but R is not the correct explanation of A","A is true but R is false","Both A and R are true and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"Discussion, unlike a competitive debate, aims at shared understanding of the reasons behind different positions. That purpose is precisely why the teacher closes by drawing views together rather than announcing a winner.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): स्कूल की छतों पर मोबाइल टावर की अनुमति दी जानी चाहिए या नहीं, इस पर कक्षा-चर्चा के अंत में शिक्षक को किसी एक पक्ष को विजेता घोषित करने के बजाय विभिन्न दृष्टिकोणों का सार प्रस्तुत करना चाहिए। कारण (R): कक्षा-चर्चा का उद्देश्य किसी मुद्दे की समझ को गहरा करना है, विरोधियों को हराना नहीं।","optionsHi":["A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"चर्चा, प्रतिस्पर्धी वाद-विवाद के विपरीत, विभिन्न मतों के पीछे के कारणों की साझा समझ का लक्ष्य रखती है। ठीक इसी उद्देश्य के कारण शिक्षक विजेता घोषित करने के बजाय विचारों को एक साथ लाकर समापन करता है।"},
  {"id":"cdp-pedagogy-subjects-432","question":"Class VIII students role-play a court hearing in which a construction worker claims unpaid wages. Which step after the performance matters most for learning?","options":["Debriefing: discussing what happened, how each character felt and how it links to courts and the right to justice","Giving marks for acting and dialogue delivery so that students take all future role plays in class much more seriously","Repeating the performance at the annual function so that parents can also see what was learnt","Moving on to the next chapter, since the role play has already covered the topic of courts fully"],"answer":0,"explanation":"Role play generates experience; the debrief turns that experience into understanding by linking it to concepts. Without it the activity remains a performance, however lively.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा VIII के विद्यार्थी अदालत की उस सुनवाई का भूमिका-निर्वाह करते हैं जिसमें एक निर्माण-मज़दूर बकाया मज़दूरी का दावा करता है। प्रदर्शन के बाद कौन-सा कदम अधिगम के लिए सबसे अधिक महत्त्वपूर्ण है?","optionsHi":["विचार-विमर्श (डीब्रीफ़िंग): क्या हुआ, हर पात्र ने कैसा महसूस किया और यह अदालतों तथा न्याय के अधिकार से कैसे जुड़ता है, इस पर चर्चा करना","अभिनय और संवाद-प्रस्तुति के अंक देना ताकि विद्यार्थी कक्षा के सभी भावी भूमिका-निर्वाहों को कहीं अधिक गंभीरता से लें","वार्षिक समारोह में प्रदर्शन दोहराना ताकि अभिभावक भी देख सकें कि क्या सीखा गया","अगले अध्याय पर बढ़ जाना, क्योंकि भूमिका-निर्वाह ने अदालतों का विषय पहले ही पूरी तरह कवर कर दिया है"],"explanationHi":"भूमिका-निर्वाह अनुभव उत्पन्न करता है; विचार-विमर्श उस अनुभव को संप्रत्ययों से जोड़कर समझ में बदलता है। उसके बिना गतिविधि एक प्रदर्शन बनी रहती है, चाहे वह कितनी भी जीवंत हो।"},
  {"id":"cdp-pedagogy-subjects-433","question":"A Kendriya Vidyalaya organises a youth parliament in which Class IX students introduce a bill, debate it and vote. What does this simulation mainly help students learn?","options":["The names and portfolios of current Union ministers and their many departments","How laws are made, and the democratic skills of debate, listening and voting","How to win elections by making persuasive promises to voters in a campaign","The exact text of the rules of procedure followed in the Lok Sabha"],"answer":1,"explanation":"A simulation gives first-hand experience of a process, here law-making, along with democratic habits such as argument and respect for the majority decision. Names of office-holders or verbatim rules are recall, not what the simulation is for.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · NVS","questionHi":"एक केंद्रीय विद्यालय युवा संसद आयोजित करता है जिसमें कक्षा IX के विद्यार्थी विधेयक प्रस्तुत करते हैं, उस पर बहस करते हैं और मतदान करते हैं। यह अनुकरण मुख्य रूप से विद्यार्थियों को क्या सीखने में मदद करता है?","optionsHi":["वर्तमान केंद्रीय मंत्रियों के नाम और उनके विभाग तथा अनेक मंत्रालय","कानून कैसे बनते हैं, और बहस, सुनने तथा मतदान के लोकतांत्रिक कौशल","चुनाव अभियान में मतदाताओं से प्रभावशाली वादे करके चुनाव कैसे जीतें","लोकसभा में अपनाए जाने वाले प्रक्रिया-नियमों का सटीक पाठ"],"explanationHi":"अनुकरण किसी प्रक्रिया का प्रत्यक्ष अनुभव देता है, यहाँ कानून-निर्माण का, साथ में तर्क और बहुमत के निर्णय के सम्मान जैसी लोकतांत्रिक आदतें भी। पदाधिकारियों के नाम या शब्दशः नियम स्मरण हैं, अनुकरण का उद्देश्य नहीं।"},
  {"id":"cdp-pedagogy-subjects-434","question":"A teacher in a Rajasthan village school plans a role play on untouchability for Class VIII. Several children in the class belong to Dalit families. Which precaution is most important?","options":["Assign roles strictly by lottery so that no one can complain of any bias or favouritism shown by the class teacher","Ask the Dalit children to play the victims, since they can act the part most realistically and with feeling","Avoid casting any child in a role that mirrors or mocks their own identity, and debrief on dignity and rights","Cancel the role play altogether and only read the chapter aloud to avoid any risk of hurt"],"answer":2,"explanation":"Role play on discrimination can hurt children whose own lives it touches. Thoughtful casting and a debrief centred on dignity keep the activity safe; a lottery could still put a child in a painful role, and cancelling loses a powerful method.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"राजस्थान के एक गाँव के विद्यालय में एक शिक्षक कक्षा VIII के लिए अस्पृश्यता पर भूमिका-निर्वाह की योजना बनाता है। कक्षा में कई बच्चे दलित परिवारों से हैं। कौन-सी सावधानी सबसे महत्त्वपूर्ण है?","optionsHi":["भूमिकाएँ कड़ाई से लॉटरी से बाँटना ताकि कक्षा-शिक्षक द्वारा किसी पक्षपात या तरफ़दारी की शिकायत कोई न कर सके","दलित बच्चों से पीड़ितों की भूमिका निभाने को कहना, क्योंकि वे उस भाग का सबसे यथार्थपूर्ण और भावपूर्ण अभिनय कर सकते हैं","किसी बच्चे को ऐसी भूमिका न देना जो उसकी अपनी पहचान को प्रतिबिंबित या उसका उपहास करे, और गरिमा तथा अधिकारों पर विचार-विमर्श करना","किसी भी चोट के जोखिम से बचने के लिए भूमिका-निर्वाह पूरी तरह रद्द करना और केवल अध्याय ज़ोर से पढ़ना"],"explanationHi":"भेदभाव पर भूमिका-निर्वाह उन बच्चों को आहत कर सकता है जिनके अपने जीवन को वह छूता है। सोच-समझकर भूमिका-वितरण और गरिमा पर केंद्रित विचार-विमर्श गतिविधि को सुरक्षित रखते हैं; लॉटरी फिर भी किसी बच्चे को पीड़ादायक भूमिका में डाल सकती है, और रद्द करना एक शक्तिशाली विधि को खो देता है।"},
  {"id":"cdp-pedagogy-subjects-435","question":"A teacher asks, 'What is fair?' A student answers. The teacher then asks, 'Would it be fair if everyone got the same tiffin, even the child who had no breakfast?' and keeps probing until students refine their idea of fairness. Which method is she using?","options":["Inductive method of teaching","Lecture method","Drill method","Socratic questioning"],"answer":3,"explanation":"Socratic questioning uses a chain of probing questions that exposes gaps in an answer and leads learners to sharper ideas. The inductive method moves from examples to a rule, which is not what is happening here.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · DSSSB","questionHi":"एक शिक्षिका पूछती है, ‘न्यायपूर्ण क्या है?’ एक विद्यार्थी उत्तर देता है। फिर शिक्षिका पूछती है, ‘क्या यह न्यायपूर्ण होगा यदि सभी को वही टिफ़िन मिले, उस बच्चे को भी जिसने नाश्ता नहीं किया था?’ और तब तक पूछती रहती है जब तक विद्यार्थी न्याय के अपने विचार को परिष्कृत नहीं कर लेते। वह कौन-सी विधि का उपयोग कर रही है?","optionsHi":["शिक्षण की आगमन विधि","व्याख्यान विधि","अभ्यास (ड्रिल) विधि","सुकराती प्रश्नोत्तर (सॉक्रेटिक क्वेश्चनिंग)"],"explanationHi":"सुकराती प्रश्नोत्तर खोजी प्रश्नों की शृंखला का उपयोग करता है जो उत्तर में कमियों को उजागर करती है और अधिगमकर्ताओं को अधिक सटीक विचारों तक ले जाती है। आगमन विधि उदाहरणों से नियम की ओर जाती है, जो यहाँ नहीं हो रहा।"},
  {"id":"cdp-pedagogy-subjects-436","question":"Which evaluation of the lecture method in social science is the most balanced?","options":["It should never be used in social science, because it is always teacher-centred and one-way","It is the best method for social science, because it covers the long syllabus fastest of all","It is useful for setting context or narrating, but used alone leaves learners passive, so it needs active methods too","It is suitable only for the primary classes, where children cannot yet read and understand the textbook by themselves"],"answer":2,"explanation":"A short lecture can set context, tell a story or clarify a difficult idea. The problem lies in relying on it alone, which makes students passive listeners. Rejecting it outright is as one-sided as praising it for speed.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"सामाजिक विज्ञान में व्याख्यान विधि का सबसे संतुलित मूल्यांकन कौन-सा है?","optionsHi":["इसका कभी उपयोग नहीं होना चाहिए, क्योंकि यह हमेशा शिक्षक-केंद्रित और एकतरफ़ा होती है","यह सामाजिक विज्ञान के लिए सबसे अच्छी विधि है, क्योंकि यह लंबे पाठ्यक्रम को सबसे तेज़ी से पूरा करती है","यह संदर्भ तय करने या वर्णन करने के लिए उपयोगी है, लेकिन अकेले उपयोग करने पर अधिगमकर्ताओं को निष्क्रिय छोड़ती है, इसलिए सक्रिय विधियाँ भी चाहिए","यह केवल प्राथमिक कक्षाओं के लिए उपयुक्त है, जहाँ बच्चे अभी पाठ्यपुस्तक स्वयं पढ़-समझ नहीं सकते"],"explanationHi":"छोटा व्याख्यान संदर्भ तय कर सकता है, कहानी सुना सकता है या कठिन विचार स्पष्ट कर सकता है। समस्या केवल उसी पर निर्भर रहने में है, जो विद्यार्थियों को निष्क्रिय श्रोता बनाता है। उसे पूरी तरह अस्वीकार करना उतना ही एकतरफ़ा है जितना उसकी गति के लिए प्रशंसा करना।"},
  {"id":"cdp-pedagogy-subjects-437","question":"A Class VI teacher narrates the life of a Gupta ruler as a vivid story, adding imagined conversations in the court. What should she do to keep it a sound history lesson?","options":["Point out which parts rest on evidence such as inscriptions and coins and which are her own reconstruction","Avoid stories altogether, since imagined details have no place at all in a history lesson","Tell students that every detail is true, so that they take the story and the ruler seriously","Ask students to memorise the court dialogues, since they will surely be asked about them in the coming test"],"answer":0,"explanation":"Storytelling engages young learners, but history depends on evidence. Marking the line between what the sources tell us and what is imagined builds early historical thinking, and banning stories gives up a strong tool.","difficulty":"very-hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"कक्षा VI की एक शिक्षिका गुप्त शासक के जीवन को दरबार में कल्पित बातचीत जोड़कर जीवंत कहानी के रूप में सुनाती है। इसे एक सही इतिहास-पाठ बनाए रखने के लिए उसे क्या करना चाहिए?","optionsHi":["बताना कि कौन-से भाग शिलालेखों और सिक्कों जैसे प्रमाणों पर आधारित हैं और कौन-से उसका अपना पुनर्निर्माण","कहानियों से पूरी तरह बचना, क्योंकि इतिहास-पाठ में कल्पित ब्योरों का कोई स्थान नहीं है","विद्यार्थियों को बताना कि हर ब्योरा सच है, ताकि वे कहानी और शासक को गंभीरता से लें","विद्यार्थियों से दरबार के संवाद याद करने को कहना, क्योंकि आगामी परीक्षा में उनसे निश्चय ही पूछा जाएगा"],"explanationHi":"कहानी सुनाना छोटे अधिगमकर्ताओं को जोड़ता है, लेकिन इतिहास प्रमाणों पर निर्भर करता है। स्रोत हमें जो बताते हैं और जो कल्पित है, इनके बीच रेखा खींचना प्रारंभिक ऐतिहासिक चिंतन निर्मित करता है, और कहानियों पर रोक एक मज़बूत उपकरण छोड़ देती है।"},
  {"id":"cdp-pedagogy-subjects-438","question":"Class VII students survey 30 households in their basti about the fuel used for cooking, put the results in a table and write what they notice. Which skill does this activity develop most?","options":["Reading maps using scale and direction","Collecting, organising and interpreting data","Arranging historical events in chronological order","Judging the reliability of an ancient inscription"],"answer":1,"explanation":"A survey trains students to gather data, tabulate it and draw inferences, which are core social science skills. The other options are real skills too, but they belong to geography mapping or history, not to this task.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VII के विद्यार्थी अपनी बस्ती के 30 घरों का खाना पकाने के ईंधन के बारे में सर्वेक्षण करते हैं, परिणामों को तालिका में रखते हैं और लिखते हैं कि उन्होंने क्या देखा। यह गतिविधि सबसे अधिक किस कौशल का विकास करती है?","optionsHi":["पैमाने और दिशा का उपयोग करके मानचित्र पढ़ना","आँकड़ों को इकट्ठा करना, व्यवस्थित करना और उनकी व्याख्या करना","ऐतिहासिक घटनाओं को कालक्रम में व्यवस्थित करना","किसी प्राचीन शिलालेख की विश्वसनीयता का निर्णय करना"],"explanationHi":"सर्वेक्षण विद्यार्थियों को आँकड़े इकट्ठा करने, उन्हें तालिकाबद्ध करने और अनुमान निकालने का प्रशिक्षण देता है, जो सामाजिक विज्ञान के मूल कौशल हैं। अन्य विकल्प भी वास्तविक कौशल हैं, लेकिन वे भूगोल के मानचित्रण या इतिहास के हैं, इस कार्य के नहीं।"},
  {"id":"cdp-pedagogy-subjects-439","question":"Assertion (A): Accounts collected from elderly people in the locality are valuable sources for writing local history.\nReason (R): Oral accounts are always more accurate than written records, because they come from people who were present.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is false but R is true","A is true but R is false"],"answer":3,"explanation":"Oral history captures voices that written records often leave out, which makes it valuable. But memory can be selective or altered over time, so oral accounts must be checked against other sources; R is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"अभिकथन (A): स्थानीय इतिहास लिखने के लिए इलाके के बुज़ुर्गों से इकट्ठा किए गए वृत्तांत मूल्यवान स्रोत हैं। कारण (R): मौखिक वृत्तांत हमेशा लिखित अभिलेखों से अधिक सटीक होते हैं, क्योंकि वे उन लोगों से आते हैं जो वहाँ मौजूद थे।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A असत्य है, लेकिन R सत्य है","A सत्य है, लेकिन R असत्य है"],"explanationHi":"मौखिक इतिहास उन आवाज़ों को पकड़ता है जिन्हें लिखित अभिलेख अक्सर छोड़ देते हैं, जो उसे मूल्यवान बनाता है। लेकिन स्मृति चयनात्मक हो सकती है या समय के साथ बदल सकती है, इसलिए मौखिक वृत्तांतों की अन्य स्रोतों से जाँच होनी चाहिए; R असत्य है।"},
  {"id":"cdp-pedagogy-subjects-440","question":"A Class IX teacher divides 'Forest Society and Colonialism' into four parts. Each student in a group of four studies one part with members of other groups who have the same part, then returns and teaches it to the home group. This strategy is:","options":["Think-pair-share","Brainstorming","Jigsaw","Fishbowl"],"answer":2,"explanation":"In jigsaw, each member becomes an 'expert' on one piece by meeting the other experts, then teaches the home group, so every member depends on every other. Think-pair-share and fishbowl do not divide content this way.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा IX का एक शिक्षक ‘वन समाज और उपनिवेशवाद’ को चार भागों में बाँटता है। चार के समूह का हर विद्यार्थी एक भाग का अध्ययन अन्य समूहों के उन सदस्यों के साथ करता है जिनके पास वही भाग है, फिर लौटकर अपने मूल समूह को उसे पढ़ाता है। यह रणनीति है:","optionsHi":["सोचो-जोड़ी बनाओ-साझा करो (थिंक-पेयर-शेयर)","विचार-मंथन","जिगसॉ (Jigsaw)","फ़िशबोल"],"explanationHi":"जिगसॉ में हर सदस्य अन्य विशेषज्ञों से मिलकर एक भाग का ‘विशेषज्ञ’ बनता है, फिर मूल समूह को पढ़ाता है, इसलिए हर सदस्य हर अन्य पर निर्भर होता है। थिंक-पेयर-शेयर और फ़िशबोल विषय-वस्तु को इस प्रकार नहीं बाँटते।"},
  {"id":"cdp-pedagogy-subjects-441","question":"A Class VI teacher opens with, 'Why were so many early cities built beside rivers?' Students then examine maps, pictures of archaeological sites and short readings to build and test their explanations. This lesson follows which approach?","options":["Inquiry-based learning","Expository teaching","Programmed instruction","Rote learning through repetition"],"answer":0,"explanation":"The lesson starts with a genuine question, and students gather and weigh evidence to construct an answer, which is the core of inquiry-based learning. In expository teaching the teacher gives the explanation directly.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"कक्षा VI की एक शिक्षिका यह कहकर शुरुआत करती है, ‘शुरुआती शहर इतनी बड़ी संख्या में नदियों के किनारे क्यों बने?’ फिर विद्यार्थी अपनी व्याख्याएँ बनाने और परखने के लिए मानचित्रों, पुरातात्त्विक स्थलों के चित्रों और छोटे पाठों की जाँच करते हैं। यह पाठ किस उपागम का अनुसरण करता है?","optionsHi":["अन्वेषण-आधारित अधिगम","व्याख्यात्मक शिक्षण","क्रमादेशित अनुदेशन","दोहराव द्वारा रटकर सीखना"],"explanationHi":"पाठ एक वास्तविक प्रश्न से शुरू होता है, और विद्यार्थी उत्तर बनाने के लिए प्रमाण इकट्ठा करते और तौलते हैं, जो अन्वेषण-आधारित अधिगम का मूल है। व्याख्यात्मक शिक्षण में शिक्षक सीधे व्याख्या देता है।"},
  {"id":"cdp-pedagogy-subjects-442","question":"To teach credit, a Class X teacher uses the detailed account of a small farmer in Andhra Pradesh who borrows from a moneylender, the terms of the loan and what happens after a crop failure. What is the main strength of this case study method?","options":["It covers a large number of facts about credit in a short time, so that the long syllabus moves faster","It removes the need to discuss general concepts of credit, since the story says everything","It ensures that every student reaches the same conclusion about moneylenders and banks","It gives a concrete, in-depth situation from which students draw general ideas about credit and debt"],"answer":3,"explanation":"A case study gives a real context in depth, letting students examine causes and consequences and then generalise to concepts such as collateral and terms of credit. The concepts still have to be drawn out; the case does not replace them.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"ऋण पढ़ाने के लिए कक्षा X का एक शिक्षक आंध्र प्रदेश के एक छोटे किसान का विस्तृत वृत्तांत उपयोग करता है जो साहूकार से उधार लेता है, ऋण की शर्तें और फ़सल-विफलता के बाद क्या होता है। इस केस अध्ययन विधि की मुख्य शक्ति क्या है?","optionsHi":["यह थोड़े समय में ऋण के बारे में बड़ी संख्या में तथ्य कवर करती है, जिससे लंबा पाठ्यक्रम तेज़ी से आगे बढ़ता है","यह ऋण के सामान्य संप्रत्ययों की चर्चा की आवश्यकता को समाप्त कर देती है, क्योंकि कहानी सब कुछ कह देती है","यह सुनिश्चित करती है कि हर विद्यार्थी साहूकारों और बैंकों के बारे में एक ही निष्कर्ष पर पहुँचे","यह एक मूर्त, गहन स्थिति देती है जिससे विद्यार्थी ऋण और कर्ज़ के बारे में सामान्य विचार निकालते हैं"],"explanationHi":"केस अध्ययन गहराई में एक वास्तविक संदर्भ देता है, जिससे विद्यार्थी कारणों और परिणामों की जाँच कर सकते हैं और फिर जमानत और ऋण की शर्तों जैसे संप्रत्ययों तक सामान्यीकरण कर सकते हैं। संप्रत्ययों को फिर भी निकालना होता है; केस उनका स्थान नहीं लेता।"},
  {"id":"cdp-pedagogy-subjects-443","question":"Which of the following statements about organising a field trip are correct?\n1. The teacher should visit the site beforehand where possible.\n2. Students should go with specific tasks to observe and record.\n3. A field trip is complete once students return safely to school.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"A preliminary visit and clear observation tasks make the trip purposeful. Statement 3 is wrong because the follow-up, where observations are discussed and connected to concepts, is an essential part of the trip.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT","questionHi":"क्षेत्र-भ्रमण आयोजित करने के बारे में निम्नलिखित में से कौन-से कथन सही हैं? 1. शिक्षक को जहाँ संभव हो पहले से स्थल का दौरा करना चाहिए। 2. विद्यार्थियों को अवलोकन और अभिलेखन के विशिष्ट कार्यों के साथ जाना चाहिए। 3. क्षेत्र-भ्रमण तब पूरा हो जाता है जब विद्यार्थी सुरक्षित विद्यालय लौट आते हैं।","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"पूर्व-निरीक्षण और स्पष्ट अवलोकन-कार्य भ्रमण को उद्देश्यपूर्ण बनाते हैं। कथन 3 गलत है क्योंकि अनुवर्ती कार्य, जिसमें अवलोकनों पर चर्चा होती है और उन्हें संप्रत्ययों से जोड़ा जाता है, भ्रमण का आवश्यक भाग है।"},
  {"id":"cdp-pedagogy-subjects-444","question":"A Class VIII teacher shows two newspaper reports of the same farmers' protest. One headline reads 'Farmers block highway, commuters suffer'; the other reads 'Farmers demand fair price for crops'. What is the main learning objective?","options":["To teach students that newspapers are biased and should never be used as sources in class","To help students find out which of the two newspapers is the more popular and widely read","To make students see that word choice and focus reflect a perspective, and to read news critically","To prove that one of the two newspapers is printing false news about the protest and should be avoided"],"answer":2,"explanation":"Both headlines may be factually accurate yet frame the event differently. Comparing them builds media literacy and an awareness of perspective, a key critical-thinking aim of social science, without reducing the lesson to 'true versus false'.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VIII का एक शिक्षक एक ही किसान प्रदर्शन की दो समाचार-पत्र रिपोर्टें दिखाता है। एक शीर्षक है ‘किसानों ने राजमार्ग रोका, यात्री परेशान’; दूसरा है ‘किसान फ़सलों का उचित मूल्य माँगते हैं’। मुख्य अधिगम-उद्देश्य क्या है?","optionsHi":["विद्यार्थियों को सिखाना कि समाचार-पत्र पक्षपाती होते हैं और कक्षा में कभी स्रोत के रूप में उपयोग नहीं होने चाहिए","विद्यार्थियों को यह पता लगाने में मदद करना कि दोनों में से कौन-सा समाचार-पत्र अधिक लोकप्रिय और अधिक पढ़ा जाने वाला है","विद्यार्थियों को यह दिखाना कि शब्द-चयन और ध्यान किसी दृष्टिकोण को दर्शाते हैं, और समाचार को आलोचनात्मक रूप से पढ़ना","यह सिद्ध करना कि दोनों में से एक समाचार-पत्र प्रदर्शन के बारे में झूठी खबर छाप रहा है और उससे बचना चाहिए"],"explanationHi":"दोनों शीर्षक तथ्यात्मक रूप से सही हो सकते हैं लेकिन घटना को अलग ढंग से प्रस्तुत करते हैं। उनकी तुलना मीडिया-साक्षरता और दृष्टिकोण के प्रति जागरूकता निर्मित करती है, जो सामाजिक विज्ञान का एक प्रमुख आलोचनात्मक-चिंतन लक्ष्य है, पाठ को ‘सच बनाम झूठ’ तक सीमित किए बिना।"},
  {"id":"cdp-pedagogy-subjects-445","question":"In a Class IX project on 'Changes in our town's livelihoods', one student did all the work while three group members signed the report. Which redesign would best prevent this next time?","options":["Ban group projects and give only individual written tests, since only they show each student's own work clearly","Give each member a defined role, ask for a process diary, and add peer assessment and a short viva","Give the whole group the same marks so that the members learn to share responsibility fairly","Ask parents to sign a form certifying that their child contributed equally to the project"],"answer":1,"explanation":"Clear roles, a record of the process and individual accountability through peer review and a viva make each student's contribution visible. Identical group marks reward free-riding, and banning projects throws away their value.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"‘हमारे शहर की आजीविकाओं में परिवर्तन’ पर कक्षा IX की परियोजना में, एक विद्यार्थी ने सारा काम किया जबकि तीन समूह-सदस्यों ने रिपोर्ट पर हस्ताक्षर कर दिए। अगली बार इसे सबसे अच्छी तरह रोकने के लिए कौन-सा पुनःडिज़ाइन होगा?","optionsHi":["समूह परियोजनाओं पर रोक लगाना और केवल व्यक्तिगत लिखित परीक्षाएँ देना, क्योंकि केवल वही हर विद्यार्थी का अपना काम स्पष्ट दिखाती हैं","हर सदस्य को परिभाषित भूमिका देना, प्रक्रिया-डायरी माँगना, और सहपाठी-आकलन तथा संक्षिप्त मौखिक परीक्षा जोड़ना","पूरे समूह को समान अंक देना ताकि सदस्य ज़िम्मेदारी को निष्पक्ष रूप से साझा करना सीखें","अभिभावकों से प्रमाणित करने वाले फ़ॉर्म पर हस्ताक्षर करवाना कि उनके बच्चे ने परियोजना में समान योगदान दिया"],"explanationHi":"स्पष्ट भूमिकाएँ, प्रक्रिया का अभिलेख, और सहपाठी समीक्षा तथा मौखिक परीक्षा के माध्यम से व्यक्तिगत जवाबदेही हर विद्यार्थी के योगदान को दृश्य बनाती हैं। समान समूह-अंक मुफ़्तखोरी को पुरस्कृत करते हैं, और परियोजनाओं पर रोक उनका मूल्य छीन लेती है।"},
  {"id":"cdp-pedagogy-subjects-446","question":"Class VIII students investigating 'Why is the lake in our town shrinking?' list possible reasons: less rainfall, construction on its banks, and too many borewells nearby. In the problem-solving method, this step is:","options":["Identifying the problem","Collecting data","Drawing conclusions","Forming hypotheses"],"answer":3,"explanation":"Possible explanations proposed before evidence is gathered are hypotheses. The problem was already identified, and data collection will now test which of these reasons holds.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"‘हमारे शहर की झील सिकुड़ क्यों रही है?’ की जाँच करने वाले कक्षा VIII के विद्यार्थी संभावित कारणों की सूची बनाते हैं: कम वर्षा, किनारों पर निर्माण, और पास में बहुत अधिक बोरवेल। समस्या-समाधान विधि में यह चरण है:","optionsHi":["समस्या की पहचान करना","आँकड़े इकट्ठा करना","निष्कर्ष निकालना","परिकल्पनाएँ बनाना"],"explanationHi":"प्रमाण इकट्ठा करने से पहले प्रस्तावित संभावित व्याख्याएँ परिकल्पनाएँ हैं। समस्या की पहचान पहले ही हो चुकी थी, और आँकड़े इकट्ठा करना अब परखेगा कि इनमें से कौन-सा कारण सही है।"},
  {"id":"cdp-pedagogy-subjects-447","question":"A Class VI teacher spends three periods having students colour the states of India on outline maps with crayons. Which critique of this activity is the most accurate?","options":["It is ideal as it is, since any activity that keeps children's hands busy makes learning child-centred and enjoyable for them","It lacks a thinking purpose; it would gain value if students, say, located states and asked why some are larger or have more rivers","Colouring maps is harmful because it wastes time, and it should be banned from social science altogether","Maps should be introduced only in Class IX, when students are old enough to understand scale, direction and map projection properly on their own"],"answer":1,"explanation":"Activity-based learning needs a cognitive purpose; hands busy is not the same as minds active. Tying the map work to questions turns colouring into geographical thinking, without throwing away a useful tool.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"कक्षा VI की एक शिक्षिका तीन कालांश विद्यार्थियों से भारत के राज्यों को रेखा-मानचित्रों पर रंगीन पेंसिलों से रंगवाने में बिताती है। इस गतिविधि की कौन-सी आलोचना सबसे सटीक है?","optionsHi":["यह जैसी है वैसी आदर्श है, क्योंकि कोई भी गतिविधि जो बच्चों के हाथों को व्यस्त रखती है, अधिगम को बाल-केंद्रित और उनके लिए आनंददायक बनाती है","इसमें चिंतन का उद्देश्य नहीं है; यदि विद्यार्थी, जैसे, राज्यों की स्थिति पता करें और पूछें कि कुछ बड़े क्यों हैं या उनमें अधिक नदियाँ क्यों हैं, तो इसका मूल्य बढ़ेगा","मानचित्र रंगना हानिकारक है क्योंकि यह समय बर्बाद करता है, और इसे सामाजिक विज्ञान से पूरी तरह प्रतिबंधित कर देना चाहिए","मानचित्र केवल कक्षा IX में पेश किए जाने चाहिए, जब विद्यार्थी पैमाना, दिशा और मानचित्र प्रक्षेपण को अपने आप ठीक से समझने की आयु के हों"],"explanationHi":"गतिविधि-आधारित अधिगम को संज्ञानात्मक उद्देश्य चाहिए; हाथ व्यस्त होना मन सक्रिय होने के समान नहीं है। मानचित्र-कार्य को प्रश्नों से जोड़ने पर रंगना भौगोलिक चिंतन में बदल जाता है, एक उपयोगी उपकरण को त्यागे बिना।"},
  {"id":"cdp-pedagogy-subjects-448","question":"Which of the following pairs of a teaching method and its main use in social science are correctly matched?\n1. Role play – experiencing a situation from another person's viewpoint\n2. Field trip – first-hand observation of places, people and processes\n3. Brainstorming – testing a hypothesis against collected evidence\n4. Debate – examining opposing arguments on an issue","options":["1, 2 and 4 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"Brainstorming generates many ideas quickly without judging them; testing hypotheses against evidence belongs to the problem-solving or inquiry method. The other three pairs are correctly matched.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"शिक्षण-विधि और सामाजिक विज्ञान में उसके मुख्य उपयोग के निम्नलिखित में से कौन-से युग्म सही मिलाए गए हैं? 1. भूमिका-निर्वाह – किसी स्थिति को दूसरे व्यक्ति के दृष्टिकोण से अनुभव करना 2. क्षेत्र-भ्रमण – स्थानों, लोगों और प्रक्रियाओं का प्रत्यक्ष अवलोकन 3. विचार-मंथन – एकत्र प्रमाणों के विरुद्ध परिकल्पना की जाँच 4. बहस – किसी मुद्दे पर विरोधी तर्कों की जाँच","optionsHi":["केवल 1, 2 और 4","केवल 1, 2 और 3","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"विचार-मंथन बिना निर्णय किए तेज़ी से कई विचार उत्पन्न करता है; प्रमाणों के विरुद्ध परिकल्पनाओं की जाँच समस्या-समाधान या अन्वेषण विधि की है। अन्य तीन युग्म सही मिलाए गए हैं।"},
  {"id":"cdp-pedagogy-subjects-449","question":"A Class VII teacher in Assam asks students to interview a local weaver about how she buys yarn, how long a mekhela chador takes and who buys it, then to compare her earnings with the final selling price. Which aim of economics teaching does this best serve?","options":["Memorising the definition of the putting-out system accurately so that it can be written word for word in the examination","Understanding production and markets through a real producer's experience, and asking who gains at each stage","Learning to weave from her so that students gain a vocational skill they can later use to earn a living","Finding out which state of India produces the most silk and where it is exported"],"answer":1,"explanation":"Interviewing a producer and comparing her earnings with the selling price connects economic ideas to lived experience and raises questions of fairness in the chain. Learning the craft or memorising terms misses that purpose.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"असम में कक्षा VII की एक शिक्षिका विद्यार्थियों से स्थानीय बुनकर का साक्षात्कार लेने को कहती है कि वह धागा कैसे खरीदती है, मेखला चादर बनाने में कितना समय लगता है और उसे कौन खरीदता है, फिर उसकी कमाई की अंतिम विक्रय-मूल्य से तुलना करने को। यह अर्थशास्त्र शिक्षण के किस उद्देश्य की सबसे अच्छी पूर्ति करता है?","optionsHi":["पुट-आउट प्रणाली की परिभाषा को सटीक रूप से याद करना ताकि परीक्षा में उसे शब्दशः लिखा जा सके","वास्तविक उत्पादक के अनुभव के माध्यम से उत्पादन और बाज़ारों को समझना, और यह पूछना कि हर चरण पर किसे लाभ होता है","उससे बुनाई सीखना ताकि विद्यार्थी व्यावसायिक कौशल पा सकें जिसका बाद में आजीविका कमाने में उपयोग हो","यह पता लगाना कि भारत का कौन-सा राज्य सबसे अधिक रेशम उत्पादित करता है और कहाँ निर्यात होता है"],"explanationHi":"किसी उत्पादक का साक्षात्कार लेना और उसकी कमाई की विक्रय-मूल्य से तुलना करना आर्थिक विचारों को जिए हुए अनुभव से जोड़ता है और शृंखला में निष्पक्षता के प्रश्न उठाता है। शिल्प सीखना या शब्द याद करना उस उद्देश्य से चूक जाता है।"},
  {"id":"cdp-pedagogy-subjects-450","question":"A teacher drops a cricket ball and a much lighter rubber ball of the same size together from the first-floor balcony; they land together. Pooja still says, 'The cricket ball fell faster, it was just too quick to see.' Her reaction best illustrates that:","options":["Prior ideas are robust, and learners may reinterpret evidence to fit what they believe","The demonstration was faulty, since heavier objects really do fall faster when dropped together","Pooja lacks the intelligence needed for physics at this stage and should not be pressed further","Demonstrations confuse children and should be avoided in science in favour of textbook reading"],"answer":0,"explanation":"Misconceptions resist change; a single demonstration may not create real dissatisfaction, so the teacher needs repetition with careful observation, discussion and a plausible alternative idea. Air resistance is negligible here, so the balls do land together.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"एक शिक्षक पहली मंज़िल की बालकनी से एक क्रिकेट की गेंद और उसी आकार की बहुत हल्की रबर की गेंद एक साथ गिराता है; वे साथ-साथ गिरती हैं। पूजा फिर भी कहती है, ‘क्रिकेट की गेंद तेज़ गिरी, बस इतनी तेज़ थी कि दिखी नहीं।’ उसकी प्रतिक्रिया सबसे अच्छी तरह दर्शाती है कि:","optionsHi":["पूर्व विचार प्रबल होते हैं, और अधिगमकर्ता जो मानते हैं उसके अनुरूप प्रमाणों की पुनर्व्याख्या कर सकते हैं","प्रदर्शन दोषपूर्ण था, क्योंकि भारी वस्तुएँ साथ गिराने पर वास्तव में तेज़ गिरती हैं","पूजा में इस चरण पर भौतिकी के लिए आवश्यक बुद्धि नहीं है और उसे आगे दबाव नहीं देना चाहिए","प्रदर्शन बच्चों को भ्रमित करते हैं और विज्ञान में उनसे बचकर पाठ्यपुस्तक पढ़ने को प्राथमिकता देनी चाहिए"],"explanationHi":"भ्रांत धारणाएँ बदलने का प्रतिरोध करती हैं; एक प्रदर्शन वास्तविक असंतोष पैदा नहीं कर सकता, इसलिए शिक्षक को सावधान अवलोकन के साथ दोहराव, चर्चा और एक विश्वसनीय वैकल्पिक विचार चाहिए। यहाँ वायु-प्रतिरोध नगण्य है, इसलिए गेंदें साथ ही गिरती हैं।"},
  {"id":"cdp-pedagogy-subjects-451","question":"According to the conceptual change model, which conditions are needed for a student to give up 'the bulb uses up current' in favour of 'current is the same all round the circuit'? 1. She is dissatisfied with her existing idea. 2. The new idea is intelligible to her. 3. The new idea appears plausible. 4. The new idea is fruitful in explaining new situations. 5. The teacher declares the old idea wrong.","options":["1, 2 and 5 only","2, 3 and 4 only","All five: 1, 2, 3, 4 and 5","1, 2, 3 and 4 only"],"answer":3,"explanation":"Posner and colleagues named dissatisfaction, intelligibility, plausibility and fruitfulness as the conditions for conceptual change. An authority simply declaring the old idea wrong does not by itself change it.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"संप्रत्यय-परिवर्तन मॉडल के अनुसार, किसी विद्यार्थी को ‘बल्ब धारा खर्च कर देता है’ को छोड़कर ‘परिपथ में हर जगह धारा समान है’ को अपनाने के लिए कौन-सी शर्तें आवश्यक हैं? 1. वह अपने मौजूदा विचार से असंतुष्ट है। 2. नया विचार उसके लिए बोधगम्य है। 3. नया विचार विश्वसनीय लगता है। 4. नया विचार नई स्थितियों की व्याख्या करने में फलदायी है। 5. शिक्षक पुराने विचार को गलत घोषित करता है।","optionsHi":["केवल 1, 2 और 5","केवल 2, 3 और 4","सभी पाँच: 1, 2, 3, 4 और 5","केवल 1, 2, 3 और 4"],"explanationHi":"पोस्नर और उनके सहयोगियों ने असंतोष, बोधगम्यता, विश्वसनीयता और फलदायिता को संप्रत्यय-परिवर्तन की शर्तें बताया। किसी सत्ता का पुराने विचार को गलत घोषित कर देना अपने आप में उसे नहीं बदलता।"},
  {"id":"cdp-pedagogy-subjects-452","question":"On a winter morning, Class 7 students say the school's iron gate is 'colder' than the wooden door beside it. Which statement should the teacher help them arrive at, after measuring with a thermometer?","options":["The iron gate is at a lower temperature, because metals always stay colder than wood in winter","Both are at about the same temperature; iron feels colder as it conducts heat from the hand faster","Iron attracts cold from the surrounding air at night, while the wood keeps the cold out of its fibres","The wood produces a little heat of its own, so it is always warmer than the iron gate"],"answer":1,"explanation":"Objects left in the same surroundings reach the same temperature. Metal feels colder because it is a better conductor and draws heat from the skin faster; 'cold flowing in' is a common misconception.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"सर्दी की एक सुबह कक्षा 7 के विद्यार्थी कहते हैं कि विद्यालय का लोहे का फाटक उसके बगल के लकड़ी के दरवाज़े से ‘अधिक ठंडा’ है। थर्मामीटर से मापने के बाद, शिक्षक को उन्हें किस कथन तक पहुँचने में मदद करनी चाहिए?","optionsHi":["लोहे के फाटक का तापमान कम है, क्योंकि सर्दियों में धातुएँ हमेशा लकड़ी से अधिक ठंडी रहती हैं","दोनों का तापमान लगभग समान है; लोहा इसलिए ठंडा लगता है कि वह हाथ से ऊष्मा तेज़ी से चालित करता है","लोहा रात को आसपास की हवा से ठंड खींचता है, जबकि लकड़ी ठंड को अपने रेशों के बाहर रखती है","लकड़ी अपनी कुछ ऊष्मा स्वयं पैदा करती है, इसलिए वह हमेशा लोहे के फाटक से गर्म रहती है"],"explanationHi":"एक ही परिवेश में छोड़ी गई वस्तुएँ समान तापमान पर पहुँच जाती हैं। धातु इसलिए ठंडी लगती है कि वह बेहतर चालक है और त्वचा से ऊष्मा तेज़ी से खींचती है; ‘ठंड का भीतर आना’ एक सामान्य भ्रांत धारणा है।"},
  {"id":"cdp-pedagogy-subjects-453","question":"A student explains that it is summer in India in May because the earth is then closest to the sun. Which fact, brought into discussion, would create the strongest conflict with her idea?","options":["The sun rises in the east and sets in the west in every season","The moon also goes round the earth once in about a month","When it is summer in India, it is winter in Australia","The earth takes about 365 days to go round the sun"],"answer":2,"explanation":"If distance from the sun caused summer, both hemispheres would have summer together. Opposite seasons in the two hemispheres point to the tilt of the earth's axis instead.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"एक विद्यार्थी समझाती है कि मई में भारत में गर्मी इसलिए होती है क्योंकि तब पृथ्वी सूर्य के सबसे निकट होती है। चर्चा में लाया गया कौन-सा तथ्य उसके विचार से सबसे तीव्र संघर्ष पैदा करेगा?","optionsHi":["हर मौसम में सूर्य पूर्व में उगता है और पश्चिम में अस्त होता है","चंद्रमा भी लगभग एक माह में एक बार पृथ्वी की परिक्रमा करता है","जब भारत में गर्मी होती है, तब ऑस्ट्रेलिया में सर्दी होती है","पृथ्वी को सूर्य की परिक्रमा में लगभग 365 दिन लगते हैं"],"explanationHi":"यदि सूर्य से दूरी गर्मी का कारण होती, तो दोनों गोलार्धों में एक साथ गर्मी होती। दोनों गोलार्धों में विपरीत मौसम इसके बजाय पृथ्वी के अक्ष के झुकाव की ओर संकेत करते हैं।"},
  {"id":"cdp-pedagogy-subjects-454","question":"After stirring sugar into water, many Class 6 students say the sugar has 'disappeared', so the solution must weigh less than the water and sugar did before. Which activity directly tests their claim?","options":["Tasting the solution to show that the sugar is still present in the water","Weighing the water and the sugar separately, mixing them, and weighing the solution","Heating the solution until the water evaporates to show that sugar can be recovered","Telling them that matter can neither be created nor destroyed in any change"],"answer":1,"explanation":"Their claim is about mass, so weighing before and after gives direct evidence that the mass is unchanged. Tasting shows the sugar is present but does not address the claim about weight.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"पानी में चीनी घोलने के बाद, कक्षा 6 के कई विद्यार्थी कहते हैं कि चीनी ‘गायब’ हो गई है, इसलिए घोल का भार पहले के पानी और चीनी के भार से कम होना चाहिए। कौन-सी गतिविधि उनके दावे को सीधे परखती है?","optionsHi":["घोल को चखकर दिखाना कि चीनी अब भी पानी में मौजूद है","पानी और चीनी को अलग-अलग तौलना, उन्हें मिलाना, और घोल को तौलना","घोल को तब तक गरम करना जब तक पानी वाष्पित न हो जाए, ताकि दिखे कि चीनी वापस पाई जा सकती है","उन्हें बताना कि किसी भी परिवर्तन में पदार्थ न बनाया जा सकता है न नष्ट किया जा सकता है"],"explanationHi":"उनका दावा द्रव्यमान के बारे में है, इसलिए पहले और बाद में तौलना सीधा प्रमाण देता है कि द्रव्यमान अपरिवर्तित है। चखना दिखाता है कि चीनी मौजूद है, लेकिन भार के बारे में दावे को संबोधित नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-455","question":"A student writes, 'Sugar melts in hot tea.' What is the most appropriate teacher response?","options":["Accept it, because the exact word does not matter as long as the student's underlying idea about sugar is right","Mark it wrong and ask the student to write the word 'dissolves' ten times in the notebook so that the correct term sticks","Explain that sugar melts only in hot tea and not in cold water, so the sentence is correct","Contrast it with heating sugar alone in a pan, where it does melt, so the student sees that dissolving is different"],"answer":3,"explanation":"Everyday language hides a real conceptual confusion between melting (a change of state on heating) and dissolving (mixing into a solvent). Experiencing both makes the difference meaningful; drill or ignoring it does not.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"एक विद्यार्थी लिखता है, ‘चीनी गर्म चाय में पिघलती है।’ शिक्षक की सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["इसे स्वीकार करना, क्योंकि जब तक चीनी के बारे में विद्यार्थी का अंतर्निहित विचार सही है तब तक सटीक शब्द मायने नहीं रखता","इसे गलत चिह्नित करना और विद्यार्थी से कॉपी में शब्द ‘घुलती है’ दस बार लिखवाना ताकि सही शब्द पक्का हो जाए","समझाना कि चीनी केवल गर्म चाय में पिघलती है, ठंडे पानी में नहीं, इसलिए वाक्य सही है","इसकी तुलना केवल कड़ाही में चीनी को गरम करने से करना, जहाँ वह वास्तव में पिघलती है, ताकि विद्यार्थी देखे कि घुलना अलग है"],"explanationHi":"रोज़मर्रा की भाषा पिघलने (गरम करने पर अवस्था-परिवर्तन) और घुलने (विलायक में मिल जाना) के बीच वास्तविक संप्रत्ययात्मक भ्रम को छिपाती है। दोनों का अनुभव करना अंतर को अर्थपूर्ण बनाता है; अभ्यास या उसे अनदेखा करना नहीं।"},
  {"id":"cdp-pedagogy-subjects-456","question":"Students believe that the water droplets outside a glass of iced water have seeped through the glass. Which change to the activity would best test this idea?","options":["Colouring the water inside with ink and checking whether the outside droplets are coloured","Using a bigger glass with more ice so that more droplets form and are much easier for all to see","Wiping the glass dry and asking students to watch the outside more carefully this time","Repeating the activity on a hotter day, when the droplets form more quickly"],"answer":0,"explanation":"If water were seeping through, the droplets would carry the ink's colour; clear droplets show they came from water vapour in the air. The other changes do not distinguish between the two explanations.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"विद्यार्थी मानते हैं कि बर्फ़ीले पानी के गिलास के बाहर की पानी की बूँदें गिलास से रिसकर आई हैं। गतिविधि में कौन-सा परिवर्तन इस विचार को सबसे अच्छी तरह परखेगा?","optionsHi":["भीतर के पानी को स्याही से रंगना और जाँचना कि बाहर की बूँदें रंगीन हैं या नहीं","अधिक बर्फ़ वाला बड़ा गिलास उपयोग करना ताकि अधिक बूँदें बनें और सभी को देखना बहुत आसान हो","गिलास को सुखाकर पोंछना और विद्यार्थियों से इस बार बाहर को अधिक ध्यान से देखने को कहना","गतिविधि को अधिक गर्म दिन दोहराना, जब बूँदें अधिक तेज़ी से बनती हैं"],"explanationHi":"यदि पानी रिसकर आ रहा होता, तो बूँदों में स्याही का रंग होता; साफ़ बूँदें दिखाती हैं कि वे हवा की जलवाष्प से आईं। अन्य परिवर्तन दोनों व्याख्याओं में अंतर नहीं करते।"},
  {"id":"cdp-pedagogy-subjects-457","question":"Assertion (A): Plants respire both during the day and at night. Reason (R): In bright daylight, the gas exchange of photosynthesis is much larger than that of respiration and masks it.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Plants respire all the time because every living cell needs energy; that is why A is true. R is also true, but it explains why respiration seems to stop in daytime (the common misconception), not why plants respire.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"अभिकथन (A): पौधे दिन में भी और रात में भी श्वसन करते हैं। कारण (R): तेज़ दिन के प्रकाश में प्रकाश संश्लेषण का गैस-विनिमय श्वसन के गैस-विनिमय से बहुत अधिक होता है और उसे ढक देता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"पौधे हर समय श्वसन करते हैं क्योंकि हर जीवित कोशिका को ऊर्जा चाहिए; इसीलिए A सत्य है। R भी सत्य है, लेकिन यह बताता है कि श्वसन दिन में रुका हुआ क्यों लगता है (सामान्य भ्रांत धारणा), यह नहीं कि पौधे श्वसन क्यों करते हैं।"},
  {"id":"cdp-pedagogy-subjects-458","question":"Children in a Class 6 class say that 'heavy things sink and light things float'. Which pair of objects, tried in a tub of water, would best challenge this idea?","options":["A plastic button and a large smooth pebble","A light feather and a heavy steel coin","A big wooden log and a small iron nail","A dry leaf and a heavy glass marble"],"answer":2,"explanation":"The heavy log floats and the light nail sinks, which contradicts 'heavy sinks'. The other pairs fit the children's rule and would only confirm the misconception.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"कक्षा 6 की कक्षा के बच्चे कहते हैं कि ‘भारी चीज़ें डूबती हैं और हल्की चीज़ें तैरती हैं’। पानी के टब में आज़माई गई वस्तुओं का कौन-सा युग्म इस विचार को सबसे अच्छी तरह चुनौती देगा?","optionsHi":["प्लास्टिक का बटन और एक बड़ा चिकना कंकड़","हल्का पंख और भारी स्टील का सिक्का","लकड़ी का बड़ा लट्ठा और लोहे की छोटी कील","सूखी पत्ती और भारी काँच की गोली"],"explanationHi":"भारी लट्ठा तैरता है और हल्की कील डूबती है, जो ‘भारी डूबता है’ का खंडन करता है। अन्य युग्म बच्चों के नियम के अनुरूप हैं और केवल भ्रांत धारणा की पुष्टि करेंगे।"},
  {"id":"cdp-pedagogy-subjects-459","question":"A student believes that we see objects because something goes out of our eyes to the objects. Which experience would most directly challenge this idea?","options":["Looking at a small object closely through a magnifying glass in good light","Comparing how far away different students can read the small letters on an eye chart","Drawing and labelling a neat diagram of the human eye and all its parts","Sitting in a completely dark room with eyes wide open, trying to see objects"],"answer":3,"explanation":"If seeing depended only on something leaving the eye, open eyes would see in the dark. Failing to see shows that light must come from the object (or a source) into the eye.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"एक विद्यार्थी मानता है कि हम वस्तुओं को इसलिए देखते हैं क्योंकि हमारी आँखों से कुछ निकलकर वस्तुओं तक जाता है। कौन-सा अनुभव इस विचार को सबसे सीधे चुनौती देगा?","optionsHi":["अच्छे प्रकाश में आवर्धक लेंस से किसी छोटी वस्तु को पास से देखना","तुलना करना कि अलग-अलग विद्यार्थी नेत्र-चार्ट के छोटे अक्षर कितनी दूर से पढ़ सकते हैं","मानव आँख का साफ़ आरेख बनाना और उसके सभी भागों को नामांकित करना","पूर्णतः अँधेरे कमरे में आँखें पूरी खोलकर बैठना और वस्तुओं को देखने का प्रयास करना"],"explanationHi":"यदि देखना केवल आँख से कुछ निकलने पर निर्भर होता, तो खुली आँखें अँधेरे में देख पातीं। न देख पाना दिखाता है कि प्रकाश वस्तु (या स्रोत) से आँख में आना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-460","question":"Several students explain the phases of the moon as 'the earth's shadow falling on the moon'. Which teaching approach would best address this?","options":["Telling them that the shadow explanation is correct but applies only to some of the phases","Using a lamp, a ball on a stick and each student's head as the earth to model the moon's positions","Showing photographs of the full moon and the new moon and asking them to note the difference between the two","Asking students to memorise the names of the eight phases in their correct order"],"answer":1,"explanation":"Moving the ball round one's own head in lamplight shows the lit part seen from the earth changing with position, without the earth's shadow being involved. The shadow idea actually explains a lunar eclipse.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs","questionHi":"कई विद्यार्थी चंद्रमा की कलाओं को ‘पृथ्वी की छाया चंद्रमा पर पड़ना’ के रूप में समझाते हैं। कौन-सा शिक्षण उपागम इसका सबसे अच्छा समाधान करेगा?","optionsHi":["उन्हें बताना कि छाया वाली व्याख्या सही है लेकिन केवल कुछ कलाओं पर लागू होती है","चंद्रमा की स्थितियों का मॉडल बनाने के लिए दीपक, डंडी पर गेंद और पृथ्वी के रूप में हर विद्यार्थी के सिर का उपयोग करना","पूर्णिमा और अमावस्या के चित्र दिखाना और उनसे दोनों के बीच का अंतर नोट करने को कहना","विद्यार्थियों से आठ कलाओं के नाम उनके सही क्रम में याद करने को कहना"],"explanationHi":"दीपक की रोशनी में अपने सिर के चारों ओर गेंद घुमाना दिखाता है कि पृथ्वी से दिखने वाला प्रकाशित भाग स्थिति के साथ बदलता है, बिना पृथ्वी की छाया को शामिल किए। छाया का विचार वास्तव में चंद्र ग्रहण को समझाता है।"},
  {"id":"cdp-pedagogy-subjects-461","question":"Many students in a class call a spider an insect and a whale a fish. The best strategy to address both errors is to:","options":["Have students list the defining features of each group (body parts, legs, breathing, feeding young) and test the animals","Give students a long list of correct examples of insects, spiders, fish and mammals to learn by heart","Tell students that spiders and whales are simply exceptions to the usual rules of classification and need not be explained","Show pictures of spiders and whales and simply tell students which group each belongs to"],"answer":0,"explanation":"Both errors come from judging by surface features (small and crawling, lives in water). Classifying by defining characteristics builds the right criteria, which then transfer to new animals.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा के कई विद्यार्थी मकड़ी को कीट और व्हेल को मछली कहते हैं। दोनों त्रुटियों का समाधान करने की सबसे अच्छी रणनीति है:","optionsHi":["विद्यार्थियों से हर समूह की परिभाषित विशेषताओं (शरीर के भाग, पैर, श्वसन, बच्चों को दूध पिलाना) की सूची बनवाना और जानवरों को परखना","विद्यार्थियों को कीटों, मकड़ियों, मछलियों और स्तनधारियों के सही उदाहरणों की लंबी सूची रटने को देना","विद्यार्थियों को बताना कि मकड़ियाँ और व्हेल वर्गीकरण के सामान्य नियमों के अपवाद हैं और उन्हें समझाने की आवश्यकता नहीं","मकड़ियों और व्हेल के चित्र दिखाना और बस बता देना कि हर एक किस समूह का है"],"explanationHi":"दोनों त्रुटियाँ सतही विशेषताओं (छोटा और रेंगने वाला, पानी में रहने वाला) से निर्णय करने से आती हैं। परिभाषित लक्षणों से वर्गीकरण सही मानदंड बनाता है, जो फिर नए जानवरों पर लागू होते हैं।"},
  {"id":"cdp-pedagogy-subjects-462","question":"A teacher has to give a demonstration to a class of 48 students. Which plan reflects good demonstration practice?","options":["Performing it quickly at the teacher's table while students copy the notes written on the board to save time","Performing it while students watch silently and carefully, and then explaining the result afterwards","Placing it where all can see, asking for predictions, letting some students handle it, and discussing the result","Showing it only to the front rows, since the students at the back can read about it in the textbook at home later"],"answer":2,"explanation":"A good demonstration is visible to all, engages thinking through prediction and student participation, and ends with discussion. A silent show with explanation afterwards turns students into passive spectators.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS","questionHi":"एक शिक्षक को 48 विद्यार्थियों की कक्षा को प्रदर्शन देना है। कौन-सी योजना अच्छे प्रदर्शन-अभ्यास को दर्शाती है?","optionsHi":["इसे शिक्षक की मेज़ पर जल्दी से करना, जबकि विद्यार्थी समय बचाने के लिए श्यामपट्ट पर लिखे नोट उतारें","इसे तब करना जब विद्यार्थी चुपचाप और ध्यान से देखें, और बाद में परिणाम समझाना","इसे ऐसी जगह रखना जहाँ सभी देख सकें, पूर्वानुमान माँगना, कुछ विद्यार्थियों को उसे छूने देना, और परिणाम पर चर्चा करना","इसे केवल आगे की पंक्तियों को दिखाना, क्योंकि पीछे के विद्यार्थी बाद में घर पर पाठ्यपुस्तक में पढ़ सकते हैं"],"explanationHi":"अच्छा प्रदर्शन सभी को दिखाई देता है, पूर्वानुमान और विद्यार्थी-भागीदारी से चिंतन को जोड़ता है, और चर्चा पर समाप्त होता है। चुप दिखाना और बाद में स्पष्टीकरण देना विद्यार्थियों को निष्क्रिय दर्शक बना देता है।"},
  {"id":"cdp-pedagogy-subjects-463","question":"For a Class 8 class, which of the following is better done as a teacher demonstration than as individual student lab work?","options":["Testing household substances with turmeric paper","Testing whether materials conduct electricity with a cell and bulb tester","Germinating seeds on moist cotton","Showing the reaction of a small piece of sodium with water"],"answer":3,"explanation":"Sodium reacts violently with water, so safety demands that only the teacher handle it in a controlled way. The other activities are safe and are best done by students themselves.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा 8 के लिए, निम्नलिखित में से कौन-सी गतिविधि व्यक्तिगत विद्यार्थी प्रयोगशाला कार्य के बजाय शिक्षक प्रदर्शन के रूप में बेहतर की जाती है?","optionsHi":["हल्दी के कागज़ से घरेलू पदार्थों का परीक्षण करना","सेल और बल्ब परीक्षक से यह जाँचना कि पदार्थ बिजली चालित करते हैं या नहीं","नम रुई पर बीज अंकुरित करना","सोडियम के छोटे टुकड़े की पानी के साथ अभिक्रिया दिखाना"],"explanationHi":"सोडियम पानी के साथ तीव्र अभिक्रिया करता है, इसलिए सुरक्षा के लिए केवल शिक्षक को उसे नियंत्रित ढंग से सँभालना चाहिए। अन्य गतिविधियाँ सुरक्षित हैं और विद्यार्थियों द्वारा स्वयं करना सबसे अच्छा है।"},
  {"id":"cdp-pedagogy-subjects-464","question":"While preparing safety rules for the Class 8 laboratory, a teacher drafts four instructions. Which one is unsafe and must be removed?","options":["Smell a substance by gently wafting its vapour towards the nose","Always add water slowly to concentrated acid while diluting it","Never taste any chemical in the laboratory","Point the mouth of a test tube being heated away from yourself and others"],"answer":1,"explanation":"To dilute an acid, the acid is added slowly to water with stirring; adding water to concentrated acid can make it boil and splash. The other three are standard safe practices.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा 8 की प्रयोगशाला के लिए सुरक्षा नियम तैयार करते हुए एक शिक्षक चार निर्देश लिखता है। इनमें से कौन-सा असुरक्षित है और हटाया जाना चाहिए?","optionsHi":["किसी पदार्थ की वाष्प को धीरे से नाक की ओर पंखा झलकर सूँघना","तनुकरण करते समय हमेशा सांद्र अम्ल में पानी धीरे-धीरे डालना","प्रयोगशाला में किसी भी रसायन को कभी न चखना","गरम की जा रही परखनली का मुँह अपनी और दूसरों की ओर से दूर रखना"],"explanationHi":"अम्ल का तनुकरण करने के लिए अम्ल को पानी में धीरे-धीरे हिलाते हुए डाला जाता है; सांद्र अम्ल में पानी डालने से वह उबल सकता है और छलक सकता है। अन्य तीन मानक सुरक्षित अभ्यास हैं।"},
  {"id":"cdp-pedagogy-subjects-465","question":"A teacher's lab worksheet lists every step and also states the result students are 'supposed to get'. Which single change would best turn it into an inquiry activity?","options":["Adding more detailed steps so that students make fewer mistakes and reliably get the right result","Asking students to copy the expected result into their notebooks before they start","Removing the expected result, posing a question, and asking students to predict and then explain","Doing the activity as a teacher demonstration so that the result is certain and quick"],"answer":2,"explanation":"Stating the answer in advance turns practical work into confirmation. Posing a question and asking for prediction and explanation makes students reason from evidence.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"एक शिक्षक का प्रयोगशाला अभ्यास-पत्र हर चरण सूचीबद्ध करता है और वह परिणाम भी बताता है जो विद्यार्थियों को ‘मिलना चाहिए’। कौन-सा एक परिवर्तन इसे अन्वेषण गतिविधि में सबसे अच्छी तरह बदल देगा?","optionsHi":["और अधिक विस्तृत चरण जोड़ना ताकि विद्यार्थी कम गलतियाँ करें और भरोसेमंद ढंग से सही परिणाम पाएँ","विद्यार्थियों से शुरू करने से पहले अपेक्षित परिणाम कॉपी में उतारने को कहना","अपेक्षित परिणाम हटाना, एक प्रश्न रखना, और विद्यार्थियों से पूर्वानुमान लगाने और फिर व्याख्या करने को कहना","गतिविधि को शिक्षक प्रदर्शन के रूप में करना ताकि परिणाम निश्चित और शीघ्र हो"],"explanationHi":"उत्तर पहले से बता देना प्रायोगिक कार्य को पुष्टि में बदल देता है। प्रश्न रखना और पूर्वानुमान तथा व्याख्या माँगना विद्यार्थियों को प्रमाण से तर्क करने को प्रेरित करता है।"},
  {"id":"cdp-pedagogy-subjects-466","question":"To assess students' practical skills, such as handling apparatus and taking readings, the most valid method is:","options":["Marking only the neatness and completeness of each student's written practical record","A written test asking students to list the steps of each experiment in order","An oral quiz on the names and uses of the laboratory apparatus","Observing students while they perform the task, using a checklist or rating scale"],"answer":3,"explanation":"Skills are shown in performance, so they are validly judged by observing the performance against clear criteria. Written records and quizzes measure recall, not skill.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"उपकरण सँभालने और रीडिंग लेने जैसे विद्यार्थियों के प्रायोगिक कौशल का आकलन करने की सबसे वैध विधि है:","optionsHi":["केवल हर विद्यार्थी के लिखित प्रायोगिक अभिलेख की सफ़ाई और पूर्णता पर अंक देना","लिखित परीक्षा जिसमें विद्यार्थियों से हर प्रयोग के चरण क्रम से सूचीबद्ध करने को कहा जाए","प्रयोगशाला उपकरणों के नाम और उपयोग पर मौखिक प्रश्नोत्तरी","विद्यार्थियों को कार्य करते हुए देखना, जाँच-सूची या मापनी (रेटिंग स्केल) का उपयोग करते हुए"],"explanationHi":"कौशल प्रदर्शन में दिखते हैं, इसलिए उनका स्पष्ट मानदंडों के विरुद्ध प्रदर्शन को देखकर मूल्यांकन करना वैध है। लिखित अभिलेख और प्रश्नोत्तरी स्मरण को मापते हैं, कौशल को नहीं।"},
  {"id":"cdp-pedagogy-subjects-467","question":"A Class 7 class decides to set up a vermicompost pit in the school garden and plans the materials, roles and timeline. Following the project method, what should come next?","options":["Executing the plan, and then judging the work and the result","Judging the plan, and then purposing a new project","Purposing again to make sure all students agree","A written test on vermicompost, followed by executing the plan"],"answer":0,"explanation":"The project method runs through purposing, planning, executing and judging (evaluating). Having purposed and planned, the class must carry out the plan and then review it.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs","questionHi":"कक्षा 7 की एक कक्षा विद्यालय की बगिया में केंचुआ-खाद का गड्ढा बनाने का निर्णय लेती है और सामग्री, भूमिकाओं और समय-सारणी की योजना बनाती है। प्रोजेक्ट विधि के अनुसार, आगे क्या आना चाहिए?","optionsHi":["योजना को क्रियान्वित करना, और फिर कार्य तथा परिणाम का मूल्यांकन करना","योजना का मूल्यांकन करना, और फिर नई परियोजना का प्रयोजन निर्धारित करना","यह सुनिश्चित करने के लिए फिर से प्रयोजन निर्धारित करना कि सभी विद्यार्थी सहमत हैं","केंचुआ-खाद पर लिखित परीक्षा, उसके बाद योजना का क्रियान्वयन"],"explanationHi":"प्रोजेक्ट विधि प्रयोजन निर्धारण, योजना, क्रियान्वयन और मूल्यांकन के चरणों से गुज़रती है। प्रयोजन और योजना हो जाने के बाद कक्षा को योजना पूरी करनी चाहिए और फिर उसकी समीक्षा करनी चाहिए।"},
  {"id":"cdp-pedagogy-subjects-468","question":"A teacher lets students test an iron nail, a copper wire and aluminium foil (all conduct) and a plastic scale and a wooden stick (neither conducts). Students conclude that metals conduct electricity, and then predict whether a steel spoon will conduct. The lesson moved:","options":["From deductive to inductive reasoning","From inductive to deductive reasoning","Only by deductive reasoning throughout","Only by rote learning of the rule"],"answer":1,"explanation":"Generalising from particular cases to a rule is induction; applying the rule to a new case (the steel spoon) is deduction. Good science lessons often use both in this order.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"एक शिक्षक विद्यार्थियों को लोहे की कील, ताँबे का तार और ऐल्युमिनियम की पन्नी (सभी चालक) तथा प्लास्टिक का पैमाना और लकड़ी की डंडी (दोनों अचालक) परखने देता है। विद्यार्थी निष्कर्ष निकालते हैं कि धातुएँ बिजली चालित करती हैं, और फिर पूर्वानुमान लगाते हैं कि स्टील की चम्मच चालित करेगी या नहीं। पाठ किस ओर बढ़ा?","optionsHi":["निगमनात्मक से आगमनात्मक तर्क की ओर","आगमनात्मक से निगमनात्मक तर्क की ओर","पूरे समय केवल निगमनात्मक तर्क से","केवल नियम को रटकर सीखने से"],"explanationHi":"विशिष्ट मामलों से नियम तक सामान्यीकरण करना आगमन है; नियम को नए मामले (स्टील की चम्मच) पर लागू करना निगमन है। अच्छे विज्ञान-पाठ प्रायः दोनों का इसी क्रम में उपयोग करते हैं।"},
  {"id":"cdp-pedagogy-subjects-469","question":"A teacher uses a bell jar model, with balloons for lungs and a rubber sheet for the diaphragm, to teach breathing. Which follow-up best prevents the model from creating new misconceptions?","options":["Telling students that the model works exactly as the body does, so that they can trust every part of it fully","Not showing the model again, as models only confuse learners once the idea is explained","Letting students play freely with the model without any discussion, so they discover it alone","Asking which parts correspond to the body and where the model differs, e.g. the rigid jar unlike the rib cage"],"answer":3,"explanation":"Models help visualise, but learners may take every feature literally. Mapping the parts and discussing the model's limits keeps the useful idea and prevents new errors.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"एक शिक्षक श्वसन सिखाने के लिए बेल जार मॉडल का उपयोग करता है, जिसमें फेफड़ों के लिए गुब्बारे और डायाफ़्राम के लिए रबर की चादर है। कौन-सा अनुवर्ती कार्य मॉडल से नई भ्रांत धारणाएँ बनने को सबसे अच्छी तरह रोकता है?","optionsHi":["विद्यार्थियों को बताना कि मॉडल ठीक वैसे ही काम करता है जैसे शरीर, ताकि वे उसके हर भाग पर पूरा भरोसा कर सकें","मॉडल को फिर कभी न दिखाना, क्योंकि विचार समझाए जाने के बाद मॉडल केवल अधिगमकर्ताओं को भ्रमित करते हैं","विद्यार्थियों को बिना किसी चर्चा के मॉडल से खुलकर खेलने देना, ताकि वे अकेले खोजें","पूछना कि कौन-से भाग शरीर के अनुरूप हैं और मॉडल कहाँ भिन्न है, जैसे कठोर जार वक्ष-पिंजर के विपरीत है"],"explanationHi":"मॉडल दृश्य बनाने में सहायक हैं, लेकिन अधिगमकर्ता हर विशेषता को शाब्दिक रूप से ले सकते हैं। भागों का मिलान और मॉडल की सीमाओं पर चर्चा उपयोगी विचार को बनाए रखती है और नई त्रुटियों को रोकती है।"},
  {"id":"cdp-pedagogy-subjects-470","question":"A teacher plans a field visit to a village pond with Class 7. Which plan is most likely to lead to learning?","options":["A visit with no preparation at all, so that students are not biased by what they expect to see there","A visit where the teacher explains everything about the pond while the students listen quietly and walk around it with her","Preparing questions and recording sheets beforehand, collecting data at the pond, and discussing findings in class","A visit followed by an essay on 'My trip to the pond', marked for language and neatness"],"answer":2,"explanation":"A field trip teaches well when it has a purpose (pre-visit), active observation and recording (visit) and sense-making afterwards (post-visit). Unprepared outings or lecture-walks make it a picnic.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"एक शिक्षक कक्षा 7 के साथ गाँव के तालाब की क्षेत्र-यात्रा की योजना बनाता है। कौन-सी योजना सीखने की ओर ले जाने की सबसे अधिक संभावना रखती है?","optionsHi":["बिना किसी तैयारी की यात्रा, ताकि विद्यार्थी इससे पूर्वाग्रहग्रस्त न हों कि वे वहाँ क्या देखने की अपेक्षा रखते हैं","ऐसी यात्रा जहाँ शिक्षक तालाब के बारे में सब कुछ समझाती है जबकि विद्यार्थी चुपचाप सुनते हैं और उसके साथ तालाब के चारों ओर चलते हैं","पहले से प्रश्न और अभिलेखन-पत्र तैयार करना, तालाब पर आँकड़े इकट्ठा करना, और कक्षा में निष्कर्षों पर चर्चा करना","यात्रा के बाद ‘तालाब की मेरी सैर’ पर निबंध, जिसे भाषा और सफ़ाई के लिए जाँचा जाए"],"explanationHi":"क्षेत्र-भ्रमण तब अच्छा सिखाता है जब उसमें उद्देश्य (भ्रमण-पूर्व), सक्रिय अवलोकन और अभिलेखन (भ्रमण) और बाद में अर्थ-निर्माण (भ्रमण-पश्चात) हो। बिना तैयारी की सैर या व्याख्यान-टहलना उसे पिकनिक बना देते हैं।"},
  {"id":"cdp-pedagogy-subjects-471","question":"A diagnostic test shows that many Class 8 students confuse mass and weight. The most appropriate remedial step is to:","options":["Repeat the same lecture more slowly and loudly, so that every student can follow each definition this time around","Give extra homework with the definitions of mass and weight to copy out several times","Use a new approach, such as comparing spring balance readings with the object's mass and discussing what changes on the moon","Move on to the next chapter for now and revisit the topic just before the final examination as part of the general revision plan"],"answer":2,"explanation":"Remedial teaching targets the specific difficulty found in diagnosis and uses a new, more concrete approach. Repeating the same explanation that failed rarely helps.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"एक निदानात्मक परीक्षण दिखाता है कि कक्षा 8 के कई विद्यार्थी द्रव्यमान और भार को मिला देते हैं। सबसे उपयुक्त उपचारात्मक कदम है:","optionsHi":["वही व्याख्यान और धीरे तथा ज़ोर से दोहराना, ताकि हर विद्यार्थी इस बार हर परिभाषा समझ सके","द्रव्यमान और भार की परिभाषाओं को कई बार उतारने के लिए अतिरिक्त गृहकार्य देना","नया उपागम अपनाना, जैसे स्प्रिंग-तुला की रीडिंग की वस्तु के द्रव्यमान से तुलना करना और चर्चा करना कि चंद्रमा पर क्या बदलता है","अभी अगले अध्याय पर बढ़ जाना और सामान्य पुनरावृत्ति योजना के भाग के रूप में अंतिम परीक्षा से ठीक पहले उस विषय पर लौटना"],"explanationHi":"उपचारात्मक शिक्षण निदान में पाई गई विशिष्ट कठिनाई को लक्ष्य बनाता है और नया, अधिक मूर्त उपागम अपनाता है। जो स्पष्टीकरण विफल रहा उसे दोहराना शायद ही कभी मदद करता है।"},
  {"id":"cdp-pedagogy-subjects-472","question":"Which question best assesses the application of knowledge rather than recall, after a Class 7 lesson on thermometers?","options":["What is the range of a clinical thermometer, in degrees Celsius?","Name the liquid used in most clinical and laboratory thermometers.","What is the normal temperature of the human body, in degrees Celsius and Fahrenheit?","Why does a clinical thermometer have a kink, while a laboratory one does not?"],"answer":3,"explanation":"Explaining why the kink suits clinical use (it stops the mercury falling back before the reading is taken) requires relating structure to function. The other questions can be answered from memory.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB · state TETs","questionHi":"कक्षा 7 के तापमापी पर पाठ के बाद कौन-सा प्रश्न स्मरण के बजाय ज्ञान के अनुप्रयोग का सबसे अच्छा आकलन करता है?","optionsHi":["डॉक्टरी तापमापी की सीमा सेल्सियस अंशों में क्या होती है?","अधिकांश डॉक्टरी और प्रयोगशाला तापमापियों में प्रयुक्त द्रव का नाम बताइए।","मानव शरीर का सामान्य तापमान सेल्सियस और फ़ारेनहाइट में क्या होता है?","डॉक्टरी तापमापी में मोड़ (किंक) क्यों होता है, जबकि प्रयोगशाला वाले में नहीं?"],"explanationHi":"यह समझाना कि मोड़ डॉक्टरी उपयोग के लिए क्यों उपयुक्त है (वह रीडिंग लेने से पहले पारे को वापस गिरने से रोकता है), संरचना को कार्य से जोड़ने की माँग करता है। अन्य प्रश्न स्मृति से उत्तर दिए जा सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-473","question":"When students in a Class 6 class are asked why things fall, many write 'because of air pressure pushing them down'. The teacher's first step should be to:","options":["Find out what experiences and reasoning lie behind this idea before planning activities","Mark the answer wrong and give the correct textbook answer for students to learn","Ignore the answer, since gravitation is taught properly only in the higher classes","Tell students firmly that air has nothing at all to do with motion or with falling objects"],"answer":0,"explanation":"Constructivist teaching begins by probing the reasoning behind a misconception so that the teacher can design experiences that challenge it. Simply marking it wrong leaves the reasoning untouched.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा 6 के विद्यार्थियों से पूछा जाता है कि चीज़ें क्यों गिरती हैं, तो कई लिखते हैं ‘क्योंकि वायु का दाब उन्हें नीचे धकेलता है’। शिक्षक का पहला कदम होना चाहिए:","optionsHi":["गतिविधियों की योजना बनाने से पहले यह पता लगाना कि इस विचार के पीछे कौन-से अनुभव और तर्क हैं","उत्तर को गलत चिह्नित करना और विद्यार्थियों को सीखने के लिए पाठ्यपुस्तक का सही उत्तर देना","उत्तर को अनदेखा करना, क्योंकि गुरुत्वाकर्षण ठीक से केवल ऊँची कक्षाओं में पढ़ाया जाता है","विद्यार्थियों को दृढ़ता से बताना कि हवा का गति या गिरती वस्तुओं से कोई संबंध नहीं है"],"explanationHi":"रचनावादी शिक्षण भ्रांत धारणा के पीछे के तर्क की जाँच से शुरू होता है ताकि शिक्षक ऐसे अनुभव बना सके जो उसे चुनौती दें। उसे बस गलत चिह्नित करना तर्क को अछूता छोड़ देता है।"},
  {"id":"cdp-pedagogy-subjects-474","question":"In which situation is a teacher using the heuristic approach, in the spirit of its original proposal?","options":["Explaining the working of an electric bell step by step with the help of a labelled wall chart","Giving students a dry cell, wire and nail to find out how to make the nail attract pins, with hints only when stuck","Showing a video on electromagnets, followed by a question-answer session on what was seen","Asking students to read the textbook section on electromagnets carefully and then summarise it in their own words"],"answer":1,"explanation":"In the heuristic approach the learner is put in the position of a discoverer and finds things out by her own effort, with the teacher giving minimal guidance. The others transmit ready-made knowledge.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"किस स्थिति में शिक्षक अपने मूल प्रस्ताव की भावना में हूरिस्टिक (ह्यूरिस्टिक) उपागम का उपयोग कर रहा है?","optionsHi":["नामांकित दीवार चार्ट की सहायता से बिजली की घंटी के कार्य को चरण-दर-चरण समझाना","विद्यार्थियों को एक शुष्क सेल, तार और कील देना कि वे पता लगाएँ कि कील को पिनें आकर्षित करने वाली कैसे बनाई जाए, केवल अटकने पर संकेतों के साथ","विद्युत-चुंबकों पर वीडियो दिखाना, जिसके बाद जो देखा गया उस पर प्रश्नोत्तर सत्र","विद्यार्थियों से विद्युत-चुंबकों वाला पाठ्यपुस्तक का भाग ध्यान से पढ़ने और फिर उसे अपने शब्दों में सारांशित करने को कहना"],"explanationHi":"हूरिस्टिक उपागम में अधिगमकर्ता को खोजकर्ता की स्थिति में रखा जाता है और वह अपने प्रयास से चीज़ें खोजती है, जबकि शिक्षक न्यूनतम मार्गदर्शन देता है। अन्य बने-बनाए ज्ञान का संचार करते हैं।"},
  {"id":"cdp-pedagogy-subjects-475","question":"In a Class V EVS lesson in Guwahati, Pranjal explains why the pond dried up partly in Assamese, mixing in a few English words from the textbook. What is the most appropriate response from the teacher?","options":["Tell Pranjal to repeat his answer only in English, since both the textbook and the final exam are in English","Value his reasoning, accept the mixed answer, then help the class say the key idea in English too","Accept the answer but give him lower marks for not using English, so he tries harder next time","Ignore the content of his answer and focus on correcting his English pronunciation and grammar"],"answer":1,"explanation":"Using all of a child's languages (translanguaging) lets him show real understanding; the teacher then builds the school-language version from it. Rejecting or penalising the home language suppresses thinking and participation.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"गुवाहाटी में कक्षा V के EVS पाठ में प्रांजल यह समझाता है कि तालाब आंशिक रूप से क्यों सूख गया, असमिया में, पाठ्यपुस्तक के कुछ अंग्रेज़ी शब्द मिलाकर। शिक्षक की सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["प्रांजल से अपना उत्तर केवल अंग्रेज़ी में दोहराने को कहना, क्योंकि पाठ्यपुस्तक और अंतिम परीक्षा दोनों अंग्रेज़ी में हैं","उसके तर्क को महत्त्व देना, मिश्रित उत्तर को स्वीकार करना, फिर कक्षा को मुख्य विचार अंग्रेज़ी में भी कहने में मदद करना","उत्तर स्वीकार करना लेकिन अंग्रेज़ी का उपयोग न करने के लिए उसे कम अंक देना, ताकि वह अगली बार अधिक प्रयास करे","उसके उत्तर की विषय-वस्तु को अनदेखा करना और उसकी अंग्रेज़ी के उच्चारण और व्याकरण को सुधारने पर ध्यान देना"],"explanationHi":"बच्चे की सभी भाषाओं का उपयोग (ट्रांसलैंग्वेजिंग) उसे वास्तविक समझ दिखाने देता है; शिक्षक फिर उसी से विद्यालयी भाषा का रूप बनाता है। घरेलू भाषा को अस्वीकार या दंडित करना चिंतन और भागीदारी को दबाता है।"},
  {"id":"cdp-pedagogy-subjects-476","question":"Consider the following statements about language in education under NEP 2020: 1. Wherever possible, the medium of instruction until at least Grade 5, and preferably till Grade 8 and beyond, should be the home language, mother tongue, local language or regional language. 2. NEP 2020 bans the teaching of English as a subject in all schools until Grade 8. 3. Under the three-language formula, no language will be imposed on any State. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 and 3 only"],"answer":3,"explanation":"NEP 2020 recommends the home or local language as medium and keeps the three-language formula flexible with no imposition. It does not ban English as a subject, so statement 2 is false.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"NEP 2020 के अंतर्गत शिक्षा में भाषा के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. जहाँ भी संभव हो, कम से कम कक्षा 5 तक, और अधिमानतः कक्षा 8 तथा उसके बाद भी, शिक्षा का माध्यम घरेलू भाषा, मातृभाषा, स्थानीय भाषा या क्षेत्रीय भाषा होना चाहिए। 2. NEP 2020 सभी विद्यालयों में कक्षा 8 तक एक विषय के रूप में अंग्रेज़ी पढ़ाने पर रोक लगाती है। 3. त्रि-भाषा सूत्र के अंतर्गत किसी भी राज्य पर कोई भाषा नहीं थोपी जाएगी। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","1, 2 और 3","केवल 1 और 3"],"explanationHi":"NEP 2020 घरेलू या स्थानीय भाषा को माध्यम के रूप में अनुशंसित करती है और त्रि-भाषा सूत्र को बिना किसी थोपने के लचीला रखती है। वह अंग्रेज़ी को विषय के रूप में प्रतिबंधित नहीं करती, इसलिए कथन 2 गलत है।"},
  {"id":"cdp-pedagogy-subjects-477","question":"A Class III teacher in a Delhi resettlement colony has children whose home languages are Bhojpuri, Bengali, Punjabi and Haryanvi. Which strategy best treats this diversity as a resource?","options":["Use only the language spoken by the majority of children, so that the largest group learns the most","Use only English in the classroom, so that no child's home language gets an unfair advantage over another","Invite children to share words, songs and stories in their languages, compare how each says the same idea, and build a word wall","Seat children in fixed language groups for the whole year so that each group can work comfortably together in its own home language"],"answer":2,"explanation":"Comparing languages builds metalinguistic awareness and makes every child's language visible and valued. Picking one language, imposing English, or segregating children by language each excludes or isolates some learners.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"दिल्ली की एक पुनर्वास कॉलोनी में कक्षा III की एक शिक्षिका के पास ऐसे बच्चे हैं जिनकी घरेलू भाषाएँ भोजपुरी, बांग्ला, पंजाबी और हरियाणवी हैं। कौन-सी रणनीति इस विविधता को सबसे अच्छी तरह संसाधन मानती है?","optionsHi":["केवल उस भाषा का उपयोग करना जो अधिकांश बच्चे बोलते हैं, ताकि सबसे बड़ा समूह सबसे अधिक सीखे","कक्षा में केवल अंग्रेज़ी का उपयोग करना, ताकि किसी बच्चे की घरेलू भाषा को दूसरे पर अनुचित लाभ न मिले","बच्चों को अपनी भाषाओं के शब्द, गीत और कहानियाँ साझा करने के लिए आमंत्रित करना, तुलना करना कि हर भाषा में वही विचार कैसे कहा जाता है, और शब्द-दीवार बनाना","बच्चों को पूरे वर्ष निश्चित भाषा-समूहों में बिठाना ताकि हर समूह अपनी घरेलू भाषा में सहजता से साथ काम कर सके"],"explanationHi":"भाषाओं की तुलना मेटाभाषिक जागरूकता निर्मित करती है और हर बच्चे की भाषा को दृश्य और मूल्यवान बनाती है। एक भाषा चुनना, अंग्रेज़ी थोपना, या बच्चों को भाषा के आधार पर अलग करना, हर एक कुछ अधिगमकर्ताओं को बाहर या अलग-थलग कर देता है।"},
  {"id":"cdp-pedagogy-subjects-478","question":"Assertion (A): Forbidding children to speak their home language from the first day of school is the quickest way to make them proficient in the school language. Reason (R): A new language is acquired mainly through understandable input in meaningful contexts.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Input in a language children do not yet understand is not comprehensible, so a home-language ban slows rather than speeds learning, and harms confidence. R states the accepted principle, which actually argues against A.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): विद्यालय के पहले दिन से बच्चों को घरेलू भाषा बोलने से रोकना उन्हें विद्यालयी भाषा में दक्ष बनाने का सबसे तेज़ तरीका है। कारण (R): नई भाषा मुख्य रूप से अर्थपूर्ण संदर्भों में समझ में आने वाले निवेश से अर्जित होती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"जिस भाषा को बच्चे अभी नहीं समझते उसमें निवेश बोधगम्य नहीं होता, इसलिए घरेलू भाषा पर प्रतिबंध अधिगम को तेज़ करने के बजाय धीमा करता है और आत्मविश्वास को हानि पहुँचाता है। R स्वीकृत सिद्धांत बताता है, जो वास्तव में A के विरुद्ध तर्क देता है।"},
  {"id":"cdp-pedagogy-subjects-479","question":"Fatima joined an English-medium Class I in Bengaluru from a Dakhini-speaking home. For six weeks she has spoken almost no English, though she follows instructions, points and joins in actions. What is the most appropriate step for the teacher?","options":["Treat it as a normal silent period, keep up rich input with gestures and pictures, and accept gestures and home-language replies","Make Fatima answer one question in English aloud every day in front of the class so that she is forced to break her silence soon","Note in her record that she may have a learning disability and refer her for a formal assessment","Seat her with the slowest group until she starts speaking English, so that she is not under pressure"],"answer":0,"explanation":"Many second-language learners go through a silent period in which they are absorbing the language; following instructions shows comprehension is growing. Forcing speech or labelling her raises anxiety and is a misdiagnosis.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"फ़ातिमा बेंगलुरु में अंग्रेज़ी-माध्यम कक्षा I में दक्कनी बोलने वाले घर से आई है। छह सप्ताह से उसने लगभग कोई अंग्रेज़ी नहीं बोली है, हालाँकि वह निर्देशों का पालन करती है, इशारे करती है और क्रियाओं में शामिल होती है। शिक्षक का सबसे उपयुक्त कदम क्या है?","optionsHi":["इसे सामान्य मौन-अवधि मानना, इशारों और चित्रों के साथ समृद्ध निवेश बनाए रखना, और इशारे तथा घरेलू भाषा के उत्तर स्वीकार करना","फ़ातिमा से हर दिन कक्षा के सामने अंग्रेज़ी में एक प्रश्न का ज़ोर से उत्तर दिलवाना ताकि वह जल्द ही अपनी चुप्पी तोड़ने को बाध्य हो","उसके अभिलेख में लिखना कि उसे अधिगम अक्षमता हो सकती है और उसे औपचारिक आकलन के लिए भेजना","जब तक वह अंग्रेज़ी बोलना शुरू न करे, उसे सबसे धीमे समूह के साथ बिठाना ताकि उस पर दबाव न पड़े"],"explanationHi":"कई द्वितीय भाषा अधिगमकर्ता मौन-अवधि से गुज़रते हैं जिसमें वे भाषा को आत्मसात् कर रहे होते हैं; निर्देशों का पालन करना बोध बढ़ने का संकेत है। बोलने को बाध्य करना या उस पर ठप्पा लगाना चिंता बढ़ाता है और गलत निदान है।"},
  {"id":"cdp-pedagogy-subjects-480","question":"Children of a Class II class in Koraput make a picture dictionary in which each page shows a drawing with the word in Desia (their home language), Odia and English. What is the main pedagogical value of this activity?","options":["It replaces the need to teach Odia and English separately, since all three appear on one page","It mainly improves children's drawing and colouring skills, which matter most in Class II","It helps the teacher finish the textbook vocabulary list faster by covering all three languages together on each page","It bridges from the known home language to the school languages, using children's own knowledge and experience"],"answer":3,"explanation":"Linking the same concept across languages lets children map new words onto meanings they already have, which is the essence of bridging in multilingual education. It supports, not replaces, systematic language teaching.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कोरापुट में कक्षा II के बच्चे एक चित्र-शब्दकोश बनाते हैं जिसके हर पृष्ठ पर एक चित्र है और शब्द देसिया (उनकी घरेलू भाषा), ओड़िया और अंग्रेज़ी में है। इस गतिविधि का मुख्य शैक्षिक मूल्य क्या है?","optionsHi":["यह ओड़िया और अंग्रेज़ी को अलग-अलग पढ़ाने की आवश्यकता को समाप्त कर देती है, क्योंकि तीनों एक पृष्ठ पर आती हैं","यह मुख्य रूप से बच्चों की चित्रकारी और रंग भरने के कौशल को सुधारती है, जो कक्षा II में सबसे अधिक मायने रखते हैं","यह प्रत्येक पृष्ठ पर तीनों भाषाओं को साथ कवर करके शिक्षक को पाठ्यपुस्तक की शब्दावली-सूची जल्दी पूरी करने में मदद करती है","यह बच्चों के अपने ज्ञान और अनुभव का उपयोग करके ज्ञात घरेलू भाषा से विद्यालयी भाषाओं तक सेतु बनाती है"],"explanationHi":"एक ही संप्रत्यय को भाषाओं के आर-पार जोड़ना बच्चों को नए शब्दों को उन अर्थों पर आरोपित करने देता है जो उनके पास पहले से हैं, जो बहुभाषिक शिक्षा में सेतु-निर्माण का सार है। यह व्यवस्थित भाषा-शिक्षण का सहायक है, उसका स्थान नहीं लेता।"},
  {"id":"cdp-pedagogy-subjects-481","question":"In the Anganwadi's play corner set up as a vegetable market, the teacher joins in as a customer and asks, 'I need two tomatoes and three onions. How many vegetables is that?' This is best described as:","options":["guided play, where the teacher enters the play to extend thinking without taking over","free play, because the children chose the market theme themselves and the teacher only joined in as a customer","a formal mathematics lesson disguised as play, which spoils the play and should be avoided","teacher-directed instruction, which is not appropriate in the foundational stage at all"],"answer":0,"explanation":"Guided play keeps the child's agency and the play context while the adult scaffolds learning goals (here, combining quantities). It is neither unstructured free play nor direct instruction.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"आँगनवाड़ी के खेल-कोने में, जिसे सब्ज़ी-बाज़ार बनाया गया है, शिक्षिका ग्राहक बनकर शामिल होती है और पूछती है, ‘मुझे दो टमाटर और तीन प्याज़ चाहिए। यह कुल कितनी सब्ज़ियाँ हुईं?’ इसका सबसे अच्छा वर्णन है:","optionsHi":["निर्देशित खेल, जहाँ शिक्षिका खेल में प्रवेश करके सोच को बढ़ाती है, उस पर नियंत्रण किए बिना","मुक्त खेल, क्योंकि बच्चों ने बाज़ार की थीम स्वयं चुनी और शिक्षिका केवल ग्राहक बनकर शामिल हुई","खेल के रूप में छिपाया गया औपचारिक गणित-पाठ, जो खेल को बिगाड़ता है और जिससे बचना चाहिए","शिक्षक-निर्देशित अनुदेशन, जो आधारभूत चरण में बिल्कुल उपयुक्त नहीं है"],"explanationHi":"निर्देशित खेल बच्चे की स्वायत्तता और खेल का संदर्भ बनाए रखता है जबकि वयस्क अधिगम-लक्ष्यों (यहाँ, मात्राओं को जोड़ना) के लिए पाड़ देता है। यह न तो असंरचित मुक्त खेल है और न प्रत्यक्ष अनुदेशन।"},
  {"id":"cdp-pedagogy-subjects-482","question":"Consider the following statements about play-based learning in the foundational stage: 1. Play supports physical, cognitive, language, social and emotional development together. 2. Play-based learning means children play all day without any planning by the teacher. 3. Both free play and teacher-planned, structured play have a place in the curriculum. Which of these are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Play-based pedagogy is deliberately planned: the teacher designs materials, spaces and guided activities alongside free play. So statement 2 misreads the idea; 1 and 3 are correct.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"आधारभूत चरण में खेल-आधारित अधिगम के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. खेल शारीरिक, संज्ञानात्मक, भाषाई, सामाजिक और भावनात्मक विकास को एक साथ सहारा देता है। 2. खेल-आधारित अधिगम का अर्थ है कि बच्चे दिन भर खेलते हैं, शिक्षक की कोई योजना नहीं होती। 3. पाठ्यचर्या में मुक्त खेल और शिक्षक-नियोजित, संरचित खेल, दोनों का स्थान है। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"खेल-आधारित शिक्षाशास्त्र सुविचारित रूप से नियोजित होता है: शिक्षक मुक्त खेल के साथ-साथ सामग्री, स्थान और निर्देशित गतिविधियाँ डिज़ाइन करता है। इसलिए कथन 2 विचार को गलत समझता है; 1 और 3 सही हैं।"},
  {"id":"cdp-pedagogy-subjects-483","question":"A father complains to a pre-primary teacher in Jaipur: 'My child just plays all day here. When will real learning start?' What is the most professional response?","options":["Promise to replace play time with daily writing worksheets so that the father is satisfied with the school","Explain that play is only for fun at this age and that real learning will begin once the child reaches Class I next year","Share observation notes, photographs and work samples showing what the child has learnt through play, linked to goals","Reduce play to the recess period and start rote learning of tables and rhymes to show visible progress"],"answer":2,"explanation":"Documented evidence (anecdotal records, portfolios) shows parents how play builds language, number sense and social skills. Abandoning play misreads early learning, and calling it 'only fun' undermines the teacher's own practice.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"जयपुर में एक पिता पूर्व-प्राथमिक शिक्षिका से शिकायत करते हैं: ‘मेरा बच्चा यहाँ बस दिन भर खेलता है। असली पढ़ाई कब शुरू होगी?’ सबसे पेशेवर प्रतिक्रिया क्या है?","optionsHi":["खेल के समय को दैनिक लेखन अभ्यास-पत्रों से बदलने का वादा करना ताकि पिता विद्यालय से संतुष्ट हों","समझाना कि इस आयु में खेल केवल मनोरंजन के लिए है और असली पढ़ाई तब शुरू होगी जब बच्चा अगले वर्ष कक्षा I में पहुँचेगा","अवलोकन-नोट्स, फ़ोटो और कार्य के नमूने साझा करना जो दिखाएँ कि बच्चे ने खेल के माध्यम से लक्ष्यों से जुड़ा क्या सीखा है","खेल को अवकाश तक सीमित करना और दृश्य प्रगति दिखाने के लिए पहाड़ों और कविताओं की रटंत शुरू करना"],"explanationHi":"प्रलेखित प्रमाण (उपाख्यानात्मक अभिलेख, पोर्टफ़ोलियो) अभिभावकों को दिखाते हैं कि खेल भाषा, संख्या-बोध और सामाजिक कौशल कैसे निर्मित करता है। खेल छोड़ देना प्रारंभिक अधिगम को गलत समझना है, और उसे ‘केवल मनोरंजन’ कहना शिक्षिका के अपने अभ्यास को कमज़ोर करता है।"},
  {"id":"cdp-pedagogy-subjects-484","question":"In pretend play, four-year-old Kavya uses a stick as a thermometer, plays the 'doctor' role and insists that the 'patient' must lie still until she has finished. From a Vygotskian view, what does this play most strongly show?","options":["Only gross motor development, since she is moving around and using her body in the game","Mere imitation of the adults around her, which does not by itself contribute anything to her learning","A lack of imagination, because she is only copying a real-life situation she has seen at the local clinic with her mother","Growing symbolic thought and self-regulation, as she lets one object stand for another and keeps to role rules"],"answer":3,"explanation":"Vygotsky saw make-believe play as a leading activity: using objects as symbols separates meaning from things, and keeping to role rules builds self-control. In play the child acts 'beyond her average age'.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कल्पनात्मक खेल में चार वर्ष की काव्या एक डंडी को तापमापी के रूप में उपयोग करती है, ‘डॉक्टर’ की भूमिका निभाती है और ज़ोर देती है कि ‘मरीज़’ को तब तक स्थिर लेटे रहना चाहिए जब तक वह पूरा न कर ले। वाइगोत्स्कीय दृष्टि से, यह खेल सबसे अधिक क्या दर्शाता है?","optionsHi":["केवल स्थूल गामक विकास, क्योंकि वह खेल में इधर-उधर घूम रही है और अपने शरीर का उपयोग कर रही है","अपने आसपास के वयस्कों की मात्र नकल, जो अपने आप में उसके अधिगम में कुछ योगदान नहीं देती","कल्पनाशीलता की कमी, क्योंकि वह केवल उस वास्तविक स्थिति की नकल कर रही है जो उसने अपनी माँ के साथ स्थानीय क्लिनिक में देखी","बढ़ती प्रतीकात्मक सोच और आत्म-नियमन, क्योंकि वह एक वस्तु को दूसरे का प्रतीक बनने देती है और भूमिका के नियमों का पालन करती है"],"explanationHi":"वाइगोत्स्की कल्पनात्मक खेल को अग्रणी गतिविधि मानते थे: वस्तुओं को प्रतीक के रूप में उपयोग करना अर्थ को चीज़ों से अलग करता है, और भूमिका के नियमों का पालन आत्म-नियंत्रण निर्मित करता है। खेल में बच्चा ‘अपनी औसत आयु से आगे’ कार्य करता है।"},
  {"id":"cdp-pedagogy-subjects-485","question":"In the blocks corner, five-year-old Rohan always grabs most of the blocks and pushes others out. Which teacher action best fits a play-based, inclusive classroom?","options":["Ban Rohan from the blocks corner for a week, so that he learns that grabbing has consequences","Do nothing, since free play must never be interrupted by adults, and children will sort it out among themselves","Remove the blocks from the classroom altogether, since they keep causing quarrels among children","Join the play, introduce simple turn-taking and sharing routines, and coach Rohan to build jointly with others"],"answer":3,"explanation":"Play is a key setting for learning social skills, and the adult's role includes coaching them in context. Exclusion, total non-intervention, or removing materials all miss the learning opportunity.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"ब्लॉक-कोने में पाँच वर्ष का रोहन हमेशा अधिकांश ब्लॉक पकड़ लेता है और दूसरों को धकेलकर बाहर कर देता है। शिक्षक की कौन-सी कार्रवाई खेल-आधारित, समावेशी कक्षा के सबसे अनुरूप है?","optionsHi":["रोहन को एक सप्ताह के लिए ब्लॉक-कोने से रोकना, ताकि वह सीखे कि पकड़ने के परिणाम होते हैं","कुछ न करना, क्योंकि मुक्त खेल में वयस्कों द्वारा कभी बाधा नहीं डाली जानी चाहिए, और बच्चे आपस में सुलझा लेंगे","ब्लॉकों को कक्षा से पूरी तरह हटा देना, क्योंकि वे बच्चों में झगड़े पैदा करते रहते हैं","खेल में शामिल होना, बारी-बारी से और बाँटने की सरल दिनचर्याएँ लाना, और रोहन को दूसरों के साथ मिलकर बनाने के लिए प्रशिक्षित करना"],"explanationHi":"खेल सामाजिक कौशल सीखने का प्रमुख परिवेश है, और वयस्क की भूमिका में संदर्भ में उनका प्रशिक्षण देना शामिल है। बहिष्कार, पूरी तरह हस्तक्षेप न करना, या सामग्री हटाना, सभी अधिगम के अवसर को चूक जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-486","question":"Assertion (A): Observing children closely during play can give a teacher valid information for assessing their development in the foundational stage. Reason (R): During play, children show their language, problem-solving and social skills naturally, without the stress of a test.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"NCF-FS 2022 favours observation and documentation over tests for young children because play shows authentic competence; R gives exactly this reason.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"अभिकथन (A): खेल के दौरान बच्चों का निकट से अवलोकन करना शिक्षक को आधारभूत चरण में उनके विकास का आकलन करने के लिए वैध जानकारी दे सकता है। कारण (R): खेल के दौरान बच्चे परीक्षा के तनाव के बिना स्वाभाविक रूप से अपनी भाषा, समस्या-समाधान और सामाजिक कौशल दिखाते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"explanationHi":"NCF-FS 2022 छोटे बच्चों के लिए परीक्षाओं की तुलना में अवलोकन और प्रलेखन का पक्ष लेता है क्योंकि खेल प्रामाणिक दक्षता दिखाता है; R ठीक यही कारण देता है।"},
  {"id":"cdp-pedagogy-subjects-487","question":"A teacher in a pre-primary class keeps the sand and water trays covered because they are 'messy and teach nothing'. Which statement best counters her view?","options":["Pouring, filling and moulding build sensory experience, early ideas of volume and cause-effect, and descriptive language","Sand and water play is useful only as a short break to calm restless children between lessons","Sand and water play should be allowed only after children finish their writing work, as a reward","Sand and water play builds only fine-motor control in the hands and fingers, and has no real cognitive or language value of its own"],"answer":0,"explanation":"Exploratory play with sand and water lays foundations for measurement concepts and scientific thinking, and prompts rich talk. Treating it as a break or a reward misses its learning value.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"एक पूर्व-प्राथमिक कक्षा की शिक्षिका रेत और पानी की ट्रे को ढककर रखती है क्योंकि वे ‘गंदगी फैलाती हैं और कुछ नहीं सिखातीं’। कौन-सा कथन उसके दृष्टिकोण का सबसे अच्छा प्रतिवाद करता है?","optionsHi":["उँड़ेलना, भरना और ढालना संवेदी अनुभव, आयतन और कारण-प्रभाव के प्रारंभिक विचार, और वर्णनात्मक भाषा का निर्माण करते हैं","रेत और पानी का खेल केवल पाठों के बीच बेचैन बच्चों को शांत करने के लिए छोटे अवकाश के रूप में उपयोगी है","रेत और पानी का खेल केवल तब अनुमत होना चाहिए जब बच्चे अपना लेखन-कार्य पूरा कर लें, पुरस्कार के रूप में","रेत और पानी का खेल केवल हाथों और उँगलियों के सूक्ष्म गामक नियंत्रण का निर्माण करता है, और उसका अपना कोई वास्तविक संज्ञानात्मक या भाषाई मूल्य नहीं है"],"explanationHi":"रेत और पानी के साथ अन्वेषणात्मक खेल मापन-संप्रत्ययों और वैज्ञानिक चिंतन की नींव रखता है, और समृद्ध बातचीत को प्रेरित करता है। इसे अवकाश या पुरस्कार मानना उसके अधिगम-मूल्य को चूक जाता है।"},
  {"id":"cdp-pedagogy-subjects-488","question":"A Class IV teacher in Wardha helps children make paper pinwheels and asks them to find out when the pinwheel spins faster, then try changes to the blades. What makes this a genuine example of toy-based pedagogy rather than a craft activity?","options":["The pinwheels are made from low-cost paper, so every child in the class can afford to make one","Children use the toy to ask questions, predict, test and explain how moving air spins it, linking play to concepts","Children can take the pinwheels home as a reward for good behaviour and finishing their work","The activity keeps children busy and quiet while the teacher completes the attendance registers and other paperwork"],"answer":1,"explanation":"Toy-based pedagogy uses toys as tools for inquiry and conceptual understanding, not as rewards or time-fillers. Low cost is helpful but is not what makes it pedagogy.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"वर्धा में कक्षा IV की एक शिक्षिका बच्चों को कागज़ की फिरकियाँ बनाने में मदद करती है और उनसे पता लगाने को कहती है कि फिरकी कब तेज़ घूमती है, फिर पंखों में बदलाव आज़माने को। इसे केवल शिल्प-गतिविधि के बजाय खिलौना-आधारित शिक्षाशास्त्र का वास्तविक उदाहरण क्या बनाता है?","optionsHi":["फिरकियाँ कम लागत वाले कागज़ से बनी हैं, इसलिए कक्षा का हर बच्चा एक बना सकता है","बच्चे खिलौने का उपयोग प्रश्न पूछने, पूर्वानुमान लगाने, परखने और यह समझाने के लिए करते हैं कि चलती हवा उसे कैसे घुमाती है, खेल को संप्रत्ययों से जोड़ते हुए","बच्चे अच्छे व्यवहार और अपना काम पूरा करने के पुरस्कार के रूप में फिरकियाँ घर ले जा सकते हैं","यह गतिविधि बच्चों को व्यस्त और शांत रखती है जबकि शिक्षिका उपस्थिति-पंजिका और अन्य कागज़ी काम पूरा करती है"],"explanationHi":"खिलौना-आधारित शिक्षाशास्त्र खिलौनों को अन्वेषण और संप्रत्ययात्मक समझ के उपकरण के रूप में उपयोग करता है, पुरस्कार या समय भरने के साधन के रूप में नहीं। कम लागत सहायक है लेकिन वह इसे शिक्षाशास्त्र नहीं बनाती।"},
  {"id":"cdp-pedagogy-subjects-489","question":"Class VI children make rubber-band-powered cotton-reel toys; several toys fail to move. Which next step adds the most learning?","options":["The teacher fixes the toys herself so that every child has a working toy to take home and show parents","The teacher gives marks only to the children whose toys worked properly the very first time","Children discuss why some toys failed, change one thing at a time, test again and record changes","The activity is closed at this point, since the concept is already explained in the textbook"],"answer":2,"explanation":"The design-make-test-improve cycle, with analysis of failure and changing one variable at a time, builds scientific and engineering thinking. Fixing toys for children or rewarding only first-time success removes this learning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VI के बच्चे रबर-बैंड से चलने वाले सूती रील के खिलौने बनाते हैं; कई खिलौने नहीं चलते। कौन-सा अगला कदम सबसे अधिक अधिगम जोड़ता है?","optionsHi":["शिक्षिका खिलौने स्वयं ठीक कर देती है ताकि हर बच्चे के पास घर ले जाने और अभिभावकों को दिखाने के लिए चलने वाला खिलौना हो","शिक्षिका केवल उन बच्चों को अंक देती है जिनके खिलौने बिल्कुल पहली बार में ठीक से चले","बच्चे चर्चा करते हैं कि कुछ खिलौने क्यों विफल हुए, एक बार में एक चीज़ बदलते हैं, फिर परखते हैं और बदलाव दर्ज करते हैं","गतिविधि को यहीं समाप्त कर दिया जाता है, क्योंकि संप्रत्यय पाठ्यपुस्तक में पहले ही समझाया जा चुका है"],"explanationHi":"डिज़ाइन-बनाओ-परखो-सुधारो चक्र, विफलता के विश्लेषण और एक बार में एक चर बदलने के साथ, वैज्ञानिक और अभियांत्रिकी चिंतन निर्मित करता है। बच्चों के लिए खिलौने ठीक कर देना या केवल पहली बार की सफलता को पुरस्कृत करना इस अधिगम को हटा देता है।"},
  {"id":"cdp-pedagogy-subjects-490","question":"In a Class VII social science lesson, a teacher shows Channapatna wooden toys from Karnataka and Kondapalli toys from Andhra Pradesh and asks children where the materials come from, who makes them and how they reach markets. What is the strongest pedagogic justification for this?","options":["The toys make the class colourful and attractive so that children do not get bored or restless during the long lesson","It covers part of the art syllabus as well, so that a separate art period is no longer needed","It helps the teacher finish the long geography chapter quickly by using objects instead of text","Local toys link crafts, culture, resources and livelihoods across subjects, rooted in children's own context"],"answer":3,"explanation":"Indigenous toys connect to geography (resources), economics (livelihoods, markets), history and culture, which is the cross-curricular, context-based learning NEP 2020 encourages. Colour alone or saving time is not a pedagogic reason.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VII के सामाजिक विज्ञान के पाठ में एक शिक्षक कर्नाटक के चन्नापटना लकड़ी के खिलौने और आंध्र प्रदेश के कोंडापल्ली खिलौने दिखाता है और बच्चों से पूछता है कि सामग्री कहाँ से आती है, उन्हें कौन बनाता है और वे बाज़ारों तक कैसे पहुँचते हैं। इसका सबसे मज़बूत शैक्षिक औचित्य क्या है?","optionsHi":["खिलौने कक्षा को रंगीन और आकर्षक बनाते हैं ताकि बच्चे लंबे पाठ के दौरान ऊबें या बेचैन न हों","यह कला के पाठ्यक्रम का भाग भी कवर करता है, इसलिए अलग कला-कालांश की आवश्यकता नहीं रहती","यह पाठ के बजाय वस्तुओं का उपयोग करके शिक्षक को लंबा भूगोल का अध्याय जल्दी समाप्त करने में मदद करता है","स्थानीय खिलौने बच्चों के अपने संदर्भ में निहित, विषयों के आर-पार शिल्प, संस्कृति, संसाधनों और आजीविकाओं को जोड़ते हैं"],"explanationHi":"देशी खिलौने भूगोल (संसाधन), अर्थशास्त्र (आजीविका, बाज़ार), इतिहास और संस्कृति से जुड़ते हैं, जो NEP 2020 द्वारा प्रोत्साहित बहु-विषयक, संदर्भ-आधारित अधिगम है। केवल रंग या समय बचाना शैक्षिक कारण नहीं है।"},
  {"id":"cdp-pedagogy-subjects-491","question":"Assertion (A): Giving a toy car as a prize to the child who scores highest in a test is an example of toy-based pedagogy. Reason (R): Toys can raise children's interest and motivation.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is false, but R is true","A is true, but R is false"],"answer":2,"explanation":"Toy-based pedagogy uses toys as learning tools for all children; a toy as a prize is an extrinsic reward, not pedagogy. R is true in general but does not make A true.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): परीक्षा में सर्वाधिक अंक पाने वाले बच्चे को पुरस्कार के रूप में खिलौना कार देना खिलौना-आधारित शिक्षाशास्त्र का उदाहरण है। कारण (R): खिलौने बच्चों की रुचि और अभिप्रेरणा बढ़ा सकते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A असत्य है, लेकिन R सत्य है","A सत्य है, लेकिन R असत्य है"],"explanationHi":"खिलौना-आधारित शिक्षाशास्त्र खिलौनों को सभी बच्चों के लिए अधिगम-उपकरण के रूप में उपयोग करता है; पुरस्कार के रूप में खिलौना बाह्य प्रोत्साहन है, शिक्षाशास्त्र नहीं। R सामान्यतः सत्य है लेकिन A को सत्य नहीं बनाता।"},
  {"id":"cdp-pedagogy-subjects-492","question":"In a Class I classroom in Indore, the teacher notices that boys always take the toy cars and building sets while girls take the dolls and kitchen sets. What is the most appropriate action?","options":["Leave it as it is, since children naturally prefer the toys that are suited to their own gender","Rotate every child through all toy areas and use stories and talk to question 'boys' toys' and 'girls' toys'","Remove the dolls and kitchen sets from the class so that the girls also start using building sets","Buy separate sets of toys for the boys' and girls' sections of the class so that nobody has to share or quarrel"],"answer":1,"explanation":"Toy preferences are shaped by social messages, and an inclusive teacher widens every child's experiences. Removing toys or separating children reinforces rather than challenges stereotypes.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"इंदौर की कक्षा I में शिक्षिका देखती है कि लड़के हमेशा खिलौना कारें और निर्माण-सेट ले लेते हैं जबकि लड़कियाँ गुड़ियाँ और रसोई-सेट ले लेती हैं। सबसे उपयुक्त कार्रवाई क्या है?","optionsHi":["इसे जैसा है वैसा छोड़ देना, क्योंकि बच्चे स्वाभाविक रूप से वे खिलौने पसंद करते हैं जो उनके अपने लिंग के अनुरूप हैं","हर बच्चे को सभी खिलौना-क्षेत्रों में घुमाना और कहानियों तथा बातचीत से ‘लड़कों के खिलौने’ और ‘लड़कियों के खिलौने’ पर प्रश्न उठाना","कक्षा से गुड़ियाँ और रसोई-सेट हटा देना ताकि लड़कियाँ भी निर्माण-सेट का उपयोग करने लगें","कक्षा के लड़कों और लड़कियों के भाग के लिए खिलौनों के अलग-अलग सेट खरीदना ताकि किसी को बाँटना या झगड़ना न पड़े"],"explanationHi":"खिलौनों की पसंद सामाजिक संदेशों से आकार लेती है, और समावेशी शिक्षक हर बच्चे के अनुभवों को व्यापक बनाता है। खिलौने हटाना या बच्चों को अलग करना रूढ़ियों को चुनौती देने के बजाय पुष्ट करता है।"},
  {"id":"cdp-pedagogy-subjects-493","question":"Shy Class II child Sunaina never speaks in class, but when the teacher hands her a sock puppet she talks to the puppet's 'friend' at length. What best explains this?","options":["The puppet acts as a safe mask, lowering her anxiety so she can use language without feeling exposed","Sunaina is only pretending, so what she says through the puppet has no value for assessing her language","Puppets work only for children with speech disorders","Sunaina speaks only because the puppet is a new object, and the effect will disappear within a day or two"],"answer":0,"explanation":"Puppets let children speak through a character, which reduces the fear of being judged; this is why they are widely used for oral language in early grades. What she says is real evidence of her language ability.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"संकोची कक्षा II की बच्ची सुनैना कक्षा में कभी नहीं बोलती, लेकिन जब शिक्षिका उसे मोज़े की कठपुतली देती है तो वह कठपुतली के ‘मित्र’ से लंबी बातचीत करती है। इसकी सबसे अच्छी व्याख्या क्या है?","optionsHi":["कठपुतली एक सुरक्षित मुखौटे का काम करती है, जो उसकी चिंता कम करती है ताकि वह बिना उजागर महसूस किए भाषा का उपयोग कर सके","सुनैना केवल दिखावा कर रही है, इसलिए कठपुतली के माध्यम से वह जो कहती है उसका उसकी भाषा के आकलन के लिए कोई मूल्य नहीं","कठपुतलियाँ केवल वाक् विकार वाले बच्चों के लिए काम करती हैं","सुनैना केवल इसलिए बोलती है कि कठपुतली नई वस्तु है, और यह प्रभाव एक-दो दिन में समाप्त हो जाएगा"],"explanationHi":"कठपुतलियाँ बच्चों को किसी पात्र के माध्यम से बोलने देती हैं, जिससे आकलित होने का भय कम होता है; इसीलिए प्रारंभिक कक्षाओं में मौखिक भाषा के लिए उनका व्यापक उपयोग होता है। वह जो कहती है वह उसकी भाषा-क्षमता का वास्तविक प्रमाण है।"},
  {"id":"cdp-pedagogy-subjects-494","question":"Consider the following statements about Jadui Pitara, introduced by the Ministry of Education in 2023: 1. It is a play-based learning-teaching kit for children of the foundational stage (ages 3 to 8). 2. It includes items such as toys, puzzles, puppets, storybooks and activity books. 3. It is meant to replace teacher-child interaction with self-learning material. Which of these are correct?","options":["1 and 3 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Jadui Pitara supports NCF-FS 2022 with play materials for ages 3-8 that teachers and parents use with children. It is a resource for interaction and play, not a replacement for it, so statement 3 is false.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"शिक्षा मंत्रालय द्वारा 2023 में शुरू किए गए जादुई पिटारा के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह आधारभूत चरण (आयु 3 से 8 वर्ष) के बच्चों के लिए खेल-आधारित शिक्षण-अधिगम किट है। 2. इसमें खिलौने, पहेलियाँ, कठपुतलियाँ, कहानी की पुस्तकें और गतिविधि-पुस्तकें जैसी सामग्री शामिल है। 3. इसका उद्देश्य शिक्षक-बच्चे की अंतःक्रिया को स्व-अधिगम सामग्री से बदलना है। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 2 और 3","केवल 1 और 2","1, 2 और 3"],"explanationHi":"जादुई पिटारा NCF-FS 2022 को 3-8 वर्ष की आयु के लिए खेल-सामग्री के साथ सहारा देता है, जिसे शिक्षक और अभिभावक बच्चों के साथ उपयोग करते हैं। यह अंतःक्रिया और खेल का संसाधन है, उसका स्थान नहीं, इसलिए कथन 3 गलत है।"},
  {"id":"cdp-pedagogy-subjects-495","question":"A teacher of Class III has a child with low vision. She is planning a toy-based activity on shapes. Which choice best ensures the child takes part fully?","options":["Let the child watch from the side while the others handle the toys, so that she is not hurt or left feeling embarrassed","Give the child a separate worksheet with large print instead of the toys, to work on alone","Excuse the child from the activity, since it depends entirely on being able to see the shapes","Use toys and shape blocks with clear textures and edges to explore by touch, and describe actions aloud for all"],"answer":3,"explanation":"Inclusive design (tactile materials, verbal description) lets the child learn alongside peers through the same activity. Watching from the side, separate work or exclusion denies equal participation.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"कक्षा III की एक शिक्षिका के पास कम दृष्टि वाला एक बच्चा है। वह आकृतियों पर खिलौना-आधारित गतिविधि की योजना बना रही है। कौन-सा चुनाव यह सबसे अच्छी तरह सुनिश्चित करता है कि बच्चा पूरी तरह भाग ले?","optionsHi":["बच्चे को एक ओर से देखने देना जबकि अन्य खिलौने सँभालें, ताकि उसे चोट न लगे और शर्मिंदगी न हो","खिलौनों के बजाय बच्चे को अकेले काम करने के लिए बड़े अक्षरों वाला अलग अभ्यास-पत्र देना","बच्चे को गतिविधि से छूट देना, क्योंकि वह पूरी तरह आकृतियों को देख पाने पर निर्भर है","स्पष्ट बनावट और किनारों वाले खिलौनों और आकृति-ब्लॉकों का उपयोग करना ताकि स्पर्श से खोजबीन हो सके, और सभी के लिए क्रियाओं का वर्णन ज़ोर से करना"],"explanationHi":"समावेशी डिज़ाइन (स्पर्श-योग्य सामग्री, मौखिक वर्णन) बच्चे को उसी गतिविधि के माध्यम से सहपाठियों के साथ सीखने देता है। एक ओर से देखना, अलग कार्य या बहिष्कार समान भागीदारी से वंचित करता है।"},
  {"id":"cdp-pedagogy-subjects-496","question":"A Class II teacher in Hubli uses traditional games such as hopscotch (kunte bille) and a pebble game for counting and grouping. Which statement best evaluates this choice?","options":["Traditional games are useful only for physical education and cannot be used to teach any concepts at all","Familiar games link learning to children's culture and give natural contexts for counting, grouping, turn-taking and rules","Traditional games should be avoided in class because children already play them at home and in the street with their friends","Using games for maths makes children dependent on play and unable to do written sums in their notebooks later"],"answer":1,"explanation":"Culturally familiar games give meaningful, low-cost contexts for number work and social skills, building a bridge from home to school. They complement written work rather than preventing it.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"हुबली में कक्षा II की एक शिक्षिका गिनती और समूहन के लिए पारंपरिक खेलों, जैसे कुंटे बिल्ले (लँगड़ी का खेल) और कंकड़ के खेल, का उपयोग करती है। कौन-सा कथन इस चुनाव का सबसे अच्छा मूल्यांकन करता है?","optionsHi":["पारंपरिक खेल केवल शारीरिक शिक्षा के लिए उपयोगी हैं और किसी संप्रत्यय को पढ़ाने में नहीं लगाए जा सकते","परिचित खेल अधिगम को बच्चों की संस्कृति से जोड़ते हैं और गिनती, समूहन, बारी-बारी और नियमों के लिए स्वाभाविक संदर्भ देते हैं","पारंपरिक खेलों से कक्षा में बचना चाहिए क्योंकि बच्चे उन्हें पहले से घर पर और सड़क पर मित्रों के साथ खेलते हैं","गणित के लिए खेलों का उपयोग बच्चों को खेल पर निर्भर बना देता है और वे बाद में अपनी कॉपियों में लिखित प्रश्न हल नहीं कर पाते"],"explanationHi":"सांस्कृतिक रूप से परिचित खेल संख्या-कार्य और सामाजिक कौशल के लिए अर्थपूर्ण, कम लागत वाले संदर्भ देते हैं और घर से विद्यालय तक सेतु बनाते हैं। वे लिखित कार्य के पूरक हैं, उसे रोकते नहीं।"},
  {"id":"cdp-pedagogy-subjects-497","question":"A Class V teacher says, 'I use toys in class: on Fridays children may play with them if they have finished all their work.' A teacher educator says this is not toy-based pedagogy. Which reason best supports the teacher educator?","options":["Toys should never be used beyond the pre-primary stage, so a Class V teacher should not be using them in class at all","Toy-based pedagogy requires costly factory-made educational toys rather than ordinary toys","In toy-based pedagogy, toys are tools for exploring concepts within learning objectives, not a leisure reward","Letting children play with toys on Fridays goes against the RTE Act and the school's timetable rules"],"answer":2,"explanation":"The key feature of toy-based pedagogy is that toys serve the learning goal, often made by children from local materials; using them only as a reward separates play from learning. Cost and grade level are not the issue.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कक्षा V की एक शिक्षिका कहती है, ‘मैं कक्षा में खिलौनों का उपयोग करती हूँ: शुक्रवार को बच्चे उनसे खेल सकते हैं यदि उन्होंने अपना सारा काम पूरा कर लिया हो।’ एक शिक्षक-प्रशिक्षक कहता है कि यह खिलौना-आधारित शिक्षाशास्त्र नहीं है। प्रशिक्षक का सबसे अच्छा समर्थन कौन-सा कारण करता है?","optionsHi":["खिलौनों का उपयोग पूर्व-प्राथमिक चरण से आगे कभी नहीं होना चाहिए, इसलिए कक्षा V की शिक्षिका को उन्हें कक्षा में बिल्कुल नहीं उपयोग करना चाहिए","खिलौना-आधारित शिक्षाशास्त्र के लिए साधारण खिलौनों के बजाय महँगे कारखाने में बने शैक्षिक खिलौने आवश्यक हैं","खिलौना-आधारित शिक्षाशास्त्र में खिलौने अधिगम-उद्देश्यों के भीतर संप्रत्ययों की खोजबीन के उपकरण होते हैं, अवकाश का पुरस्कार नहीं","शुक्रवार को बच्चों को खिलौनों से खेलने देना RTE अधिनियम और विद्यालय के समय-सारणी नियमों के विरुद्ध है"],"explanationHi":"खिलौना-आधारित शिक्षाशास्त्र की मुख्य विशेषता यह है कि खिलौने अधिगम-लक्ष्य की सेवा करते हैं, अक्सर बच्चों द्वारा स्थानीय सामग्री से बनाए जाते हैं; उन्हें केवल पुरस्कार के रूप में उपयोग करना खेल को अधिगम से अलग कर देता है। लागत और कक्षा-स्तर मुद्दा नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-498","question":"Consider the following about a teacher's role during children's free play in a pre-primary class: 1. Observing and recording what children do is part of the teacher's role. 2. The teacher should frequently stop play to ask questions so that learning is not wasted. 3. The teacher arranges materials and space so that play invites exploration. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"During free play the teacher prepares the environment and observes, intervening sensitively; constantly stopping play turns it into a lesson and kills its value, so statement 2 is wrong.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"पूर्व-प्राथमिक कक्षा में बच्चों के मुक्त खेल के दौरान शिक्षक की भूमिका के बारे में निम्नलिखित पर विचार कीजिए: 1. बच्चे क्या करते हैं, इसका अवलोकन करना और अभिलेखन शिक्षक की भूमिका का भाग है। 2. शिक्षक को खेल को बार-बार रोककर प्रश्न पूछने चाहिए ताकि अधिगम व्यर्थ न जाए। 3. शिक्षक सामग्री और स्थान को इस प्रकार व्यवस्थित करता है कि खेल खोजबीन को आमंत्रित करे। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"मुक्त खेल के दौरान शिक्षक परिवेश तैयार करता है और अवलोकन करता है, संवेदनशील ढंग से हस्तक्षेप करता है; खेल को लगातार रोकना उसे पाठ में बदल देता है और उसका मूल्य नष्ट कर देता है, इसलिए कथन 2 गलत है।"},
  {"id":"cdp-pedagogy-subjects-499","question":"A Class VIII teacher in Kerala wants to use a spinning top (pambaram) to start a lesson. Which use is the most pedagogically sound?","options":["Show the top spinning and then dictate the definition of rotation for the children to copy down neatly into their own notebooks","Let groups spin tops on different surfaces, observe how long they spin, ask questions and link it to friction and motion","Spin the top once to get the children's attention and then proceed with the textbook reading","Hold a spinning competition among the children and give a prize to the one whose top keeps spinning the longest"],"answer":1,"explanation":"Children's own observations and questions about the toy lead to concepts such as friction, which is the core of toy-based and experiential learning. An attention-grabber or competition alone does not lead to concepts.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"केरल में कक्षा VIII का एक शिक्षक पाठ शुरू करने के लिए लट्टू (पंबरम) का उपयोग करना चाहता है। कौन-सा उपयोग शैक्षिक दृष्टि से सबसे सही है?","optionsHi":["लट्टू को घूमते दिखाना और फिर बच्चों के अपनी कॉपियों में साफ़-साफ़ उतारने के लिए घूर्णन की परिभाषा लिखवाना","समूहों को अलग-अलग सतहों पर लट्टू घुमाने देना, यह अवलोकन करना कि वे कितनी देर घूमते हैं, प्रश्न पूछना और उसे घर्षण तथा गति से जोड़ना","बच्चों का ध्यान आकर्षित करने के लिए लट्टू को एक बार घुमाना और फिर पाठ्यपुस्तक के पठन पर आगे बढ़ना","बच्चों के बीच लट्टू घुमाने की प्रतियोगिता करना और जिसका लट्टू सबसे देर तक घूमता रहे उसे पुरस्कार देना"],"explanationHi":"खिलौने के बारे में बच्चों के अपने अवलोकन और प्रश्न घर्षण जैसे संप्रत्ययों तक ले जाते हैं, जो खिलौना-आधारित और अनुभवजन्य अधिगम का मूल है। केवल ध्यान खींचना या प्रतियोगिता संप्रत्ययों तक नहीं ले जाती।"},
  {"id":"cdp-pedagogy-subjects-500","question":"A Class 5 child says 3/4 and 4/5 are equal ‘because each is just one piece short of a whole’. Which teaching move best addresses this?","options":["Agree, since both fractions are exactly one piece less than one whole, so they must be equal","Lay strips of fourths and fifths under a whole strip so she sees that the missing quarter is bigger than the missing fifth","Teach her to cross-multiply and compare 15 and 16, which gives the correct answer quickly and reliably every single time it is used","Tell her to compare the denominators, since the bigger denominator always gives the bigger fraction"],"answer":1,"explanation":"This is ‘gap thinking’: she compares the number of missing pieces, not their size. Strips show 1/4 > 1/5, so 3/4 leaves a bigger gap and is smaller. Cross-multiplying gives the answer without fixing the idea; D is a new misconception.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"कक्षा 5 की एक बच्ची कहती है कि 3/4 और 4/5 बराबर हैं ‘क्योंकि दोनों में पूरे से बस एक टुकड़ा कम है’। कौन-सा शिक्षण-कदम इसका सबसे अच्छा समाधान करता है?","optionsHi":["सहमत होना, क्योंकि दोनों भिन्न ठीक एक टुकड़ा पूरे से कम हैं, इसलिए वे बराबर होनी चाहिए","पूरी पट्टी के नीचे चौथाई और पाँचवें भाग की पट्टियाँ रखना ताकि वह देखे कि छूटा हुआ चौथाई छूटे हुए पाँचवें भाग से बड़ा है","उसे तिर्यक गुणा करके 15 और 16 की तुलना करना सिखाना, जो हर बार उपयोग करने पर सही उत्तर शीघ्र और विश्वसनीय ढंग से देता है","उसे हरों की तुलना करने को कहना, क्योंकि बड़ा हर हमेशा बड़ी भिन्न देता है"],"explanationHi":"यह ‘अंतराल-चिंतन’ है: वह छूटे हुए टुकड़ों की संख्या की तुलना करती है, उनके आकार की नहीं। पट्टियाँ दिखाती हैं कि 1/4 > 1/5, इसलिए 3/4 बड़ा अंतराल छोड़ती है और छोटी है। तिर्यक गुणा विचार को ठीक किए बिना उत्तर देता है; D एक नई भ्रांत धारणा है।"},
  {"id":"cdp-pedagogy-subjects-501","question":"Asked to shade 1/3 of a row of 12 stars, a Class 4 child shades 3 stars. What has she most likely done?","options":["Read the denominator as the number of stars to shade, instead of making 3 equal groups","Miscounted while shading, though she meant to shade one-third of the twelve stars","Shaded 1/4 on purpose, believing a quarter and a third of 12 are the same","Understood one-third correctly but took a different set of stars as the whole"],"answer":0,"explanation":"1/3 of 12 means split 12 into 3 equal groups of 4 and take one group, so 4 stars. Reading the ‘3’ as ‘shade three’ shows she has not yet linked fractions of a set to equal grouping.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"12 सितारों की एक पंक्ति के 1/3 भाग पर रंग भरने को कहा गया, तो कक्षा 4 की एक बच्ची ने 3 सितारों पर रंग भर दिया। उसने सबसे संभावित रूप से क्या किया है?","optionsHi":["उसने 3 बराबर समूह बनाने के बजाय हर को ही रंगने वाले सितारों की संख्या पढ़ लिया","रंग भरते समय उसने गिनती में गलती की, जबकि वह बारह सितारों का एक-तिहाई रंगना चाहती थी","उसने जानबूझकर 1/4 रंगा, यह मानकर कि 12 का चौथाई और तिहाई एक ही होते हैं","उसने एक-तिहाई को सही समझा, पर पूर्ण के रूप में सितारों का कोई दूसरा समूह ले लिया"],"explanationHi":"12 का 1/3 अर्थात 12 को 3 बराबर समूहों में बाँटकर एक समूह लेना, यानी 4 सितारे। ‘3’ को ‘तीन रंगो’ पढ़ लेना दर्शाता है कि वह समूह के भिन्न को बराबर समूहीकरण से अभी जोड़ नहीं पाई है।"},
  {"id":"cdp-pedagogy-subjects-502","question":"A Class 5 child writes 2/5 + 1/5 = 3/10. Which response is most likely to change her thinking?","options":["Remind her of the rule ‘add the numerators only’ and set ten more practice sums","Tell her to find the LCM of the denominators first, then add the converted numerators","Shade 2/5 and then 1/5 on one fifths strip and ask what part of the strip is now shaded","Explain that 3/10 cannot be right because 10 is not a factor of 5, so it is not allowed"],"answer":2,"explanation":"She is treating numerators and denominators as separate whole numbers. Shading on one strip shows the pieces are still fifths, so 3 fifths are shaded; the rule alone does not repair the meaning, and LCM is not the issue with like denominators.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 5 की एक बच्ची लिखती है 2/5 + 1/5 = 3/10। कौन-सी प्रतिक्रिया उसकी सोच बदलने में सबसे अधिक सहायक होगी?","optionsHi":["उसे नियम ‘केवल अंशों को जोड़ो’ याद दिलाना और दस और प्रश्न हल करने को देना","उससे कहना कि पहले हरों का LCM निकालो, फिर बदले हुए अंशों को जोड़ो","पाँचवें भाग की एक पट्टी पर 2/5 और फिर 1/5 पर रंग भरवाना और पूछना कि पट्टी का अब कितना भाग रंगा है","यह समझाना कि 3/10 सही नहीं हो सकता क्योंकि 10, 5 का गुणनखंड नहीं है, इसलिए यह अनुमत नहीं है"],"explanationHi":"वह अंश और हर को अलग-अलग पूर्ण संख्याएँ मान रही है। एक पट्टी पर रंग भरने से दिखता है कि टुकड़े अब भी पाँचवें भाग हैं, इसलिए 3 पाँचवें भाग रंगे गए हैं; केवल नियम बताने से अर्थ की समझ नहीं बनती, और समान हर होने पर LCM की कोई समस्या नहीं है।"},
  {"id":"cdp-pedagogy-subjects-503","question":"A Class 6 child says 2/3 = 4/5 ‘because I added 2 to the top and 2 to the bottom’. What is the underlying misconception?","options":["She does not yet know how to simplify fractions to lowest terms before comparing them","She has confused the numerator with the denominator while writing the new fraction","She thinks adding the same number to top and bottom always makes a fraction bigger","She uses additive thinking where equivalence needs multiplication, as in 2/3 = 4/6"],"answer":3,"explanation":"Equivalent fractions come from multiplying (or dividing) both parts by the same number, which keeps the ratio. Adding changes the ratio: 2/3 ≈ 0.67 but 4/5 = 0.8.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा 6 की एक बच्ची कहती है 2/3 = 4/5 ‘क्योंकि मैंने ऊपर 2 जोड़ा और नीचे भी 2 जोड़ा’। इसके पीछे की मूल भ्रांति क्या है?","optionsHi":["उसे अभी तुलना से पहले भिन्नों को सरलतम रूप में लाना नहीं आता","नई भिन्न लिखते समय उसने अंश और हर को आपस में उलझा दिया है","उसे लगता है कि अंश और हर में समान संख्या जोड़ने से भिन्न हमेशा बड़ी हो जाती है","वह योगात्मक सोच अपना रही है जबकि तुल्यता के लिए गुणा चाहिए, जैसे 2/3 = 4/6"],"explanationHi":"तुल्य भिन्न अंश और हर दोनों को एक ही संख्या से गुणा (या भाग) करने पर मिलती हैं, जिससे अनुपात बना रहता है। जोड़ने से अनुपात बदल जाता है: 2/3 ≈ 0.67 जबकि 4/5 = 0.8।"},
  {"id":"cdp-pedagogy-subjects-504","question":"Match each situation with the meaning of 3/4 it uses. 1. Three rotis shared equally among four children 2. Marking 3/4 on a number line 3. Finding 3/4 of ₹200 4. Three boys for every four girls in a class; a. ratio b. operator c. measure d. quotient","options":["1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-b, 2-c, 3-d, 4-a"],"answer":0,"explanation":"Sharing 3 among 4 gives 3/4 each (quotient); a point on the line is a measure from 0; ‘3/4 of’ acts on a quantity (operator); 3 boys to 4 girls compares two quantities (ratio).","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"प्रत्येक स्थिति का मिलान उसमें प्रयुक्त 3/4 के अर्थ से कीजिए। 1. तीन रोटियाँ चार बच्चों में बराबर बाँटना 2. संख्या रेखा पर 3/4 अंकित करना 3. ₹200 का 3/4 ज्ञात करना 4. कक्षा में हर चार लड़कियों पर तीन लड़के; a. अनुपात b. संक्रियक c. माप d. भागफल","optionsHi":["1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-b, 2-c, 3-d, 4-a"],"explanationHi":"3 को 4 में बाँटने पर प्रत्येक को 3/4 मिलता है (भागफल); रेखा पर बिंदु 0 से माप है (माप); ‘का 3/4’ किसी राशि पर क्रिया करता है (संक्रियक); 3 लड़के और 4 लड़कियाँ दो राशियों की तुलना करते हैं (अनुपात)।"},
  {"id":"cdp-pedagogy-subjects-505","question":"Why do many maths educators recommend equal-sharing problems (‘share 4 rotis equally among 3 children’) as an early entry into fractions?","options":["They let children learn the written symbols for fractions first, before the ideas behind them","They draw on children's sense of fairness and naturally produce amounts such as 1 1/3 to name","They avoid the need for drawings or objects, so children can work with numbers alone","They are the only correct way to introduce unit fractions such as 1/2 and 1/3 in school"],"answer":1,"explanation":"Children already care about fair shares, so they partition and name the pieces themselves; the problem also gives fractions greater than one and the quotient meaning (4 ÷ 3), not only part-whole.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"अनेक गणित शिक्षक भिन्न सिखाने की शुरुआत के लिए बराबर बाँटने वाले प्रश्न (‘4 रोटियाँ 3 बच्चों में बराबर बाँटो’) क्यों सुझाते हैं?","optionsHi":["इनसे बच्चे भिन्न के पीछे के विचार समझने से पहले उसके लिखित प्रतीक सीख लेते हैं","ये बच्चों की न्याय की भावना पर आधारित हैं और स्वाभाविक रूप से 1 1/3 जैसी राशियाँ देते हैं जिन्हें नाम देना होता है","इनमें चित्रों या वस्तुओं की आवश्यकता नहीं रहती, इसलिए बच्चे केवल संख्याओं से काम कर सकते हैं","विद्यालय में 1/2 और 1/3 जैसी इकाई भिन्नों को पढ़ाने का यही एकमात्र सही तरीका है"],"explanationHi":"बच्चे पहले से ही उचित हिस्से की परवाह करते हैं, इसलिए वे स्वयं बाँटते हैं और टुकड़ों को नाम देते हैं; इस प्रश्न से एक से बड़ी भिन्नें और भागफल का अर्थ (4 ÷ 3) भी मिलता है, केवल भाग-पूर्ण का अर्थ नहीं।"},
  {"id":"cdp-pedagogy-subjects-506","question":"Riya says she got half of a big roti and Aman got half of a small roti, so they ‘got the same, because half is half’. The idea the teacher most needs to bring out is that:","options":["half of anything is always the same amount, so both children really did get equal shares","fractions can be compared only when the shapes being divided are of the same kind","a fraction is relative to its own whole, so halves of different wholes can differ","Aman's share is not really a half, because a small roti cannot be divided equally"],"answer":2,"explanation":"The fraction is always relative to a whole. Both shares are halves, but of different wholes, so the amounts differ. Comparing fractions as amounts needs the same whole.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"रिया कहती है कि उसे बड़ी रोटी का आधा मिला और अमन को छोटी रोटी का आधा मिला, इसलिए दोनों को ‘बराबर मिला, क्योंकि आधा तो आधा ही होता है’। शिक्षक को जो विचार सबसे अधिक उभारना चाहिए, वह है कि:","optionsHi":["किसी भी चीज़ का आधा हमेशा समान मात्रा होता है, इसलिए दोनों बच्चों को सचमुच बराबर हिस्सा मिला","भिन्नों की तुलना तभी हो सकती है जब बाँटी जा रही आकृतियाँ एक ही प्रकार की हों","भिन्न अपने पूर्ण के सापेक्ष होती है, इसलिए अलग-अलग पूर्णों के आधे भिन्न हो सकते हैं","अमन का हिस्सा वास्तव में आधा नहीं है, क्योंकि छोटी रोटी को बराबर नहीं बाँटा जा सकता"],"explanationHi":"भिन्न हमेशा किसी पूर्ण के सापेक्ष होती है। दोनों हिस्से आधे हैं, पर अलग-अलग पूर्णों के, इसलिए मात्राएँ भिन्न हैं। भिन्नों की मात्रा के रूप में तुलना के लिए पूर्ण समान होना आवश्यक है।"},
  {"id":"cdp-pedagogy-subjects-507","question":"A number line is drawn from 0 to 2 with only 0, 1 and 2 labelled. Asked to mark 2/3, a Class 5 child divides the whole line from 0 to 2 into three equal parts and marks the second division. What does this show?","options":["She knows that 2/3 lies between 1 and 2, so she marks a point inside that interval","She has confused the numerator and denominator, so she has really marked 3/2","She marks the correct point, since any line can be divided into three equal thirds","She takes the whole line, not the length from 0 to 1, as the unit, so she marks 4/3"],"answer":3,"explanation":"On a number line the unit is the length from 0 to 1. Dividing 0–2 into thirds makes each part 2/3, so the second mark is at 4/3. Children used to ‘the whole shape’ in area models often make this error.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"0 से 2 तक एक संख्या रेखा खींची गई है जिसमें केवल 0, 1 और 2 अंकित हैं। 2/3 अंकित करने को कहने पर कक्षा 5 की एक बच्ची 0 से 2 तक की पूरी रेखा को तीन बराबर भागों में बाँटकर दूसरे विभाजन-चिह्न पर निशान लगाती है। यह क्या दर्शाता है?","optionsHi":["वह जानती है कि 2/3, 1 और 2 के बीच स्थित है, इसलिए उस अंतराल के भीतर बिंदु अंकित करती है","उसने अंश और हर को उलझा दिया है, इसलिए वास्तव में उसने 3/2 अंकित किया है","उसने सही बिंदु अंकित किया है, क्योंकि किसी भी रेखा को तीन बराबर तिहाइयों में बाँटा जा सकता है","वह 0 से 1 की लंबाई के बजाय पूरी रेखा को इकाई मान रही है, इसलिए वह 4/3 अंकित करती है"],"explanationHi":"संख्या रेखा पर इकाई 0 से 1 की लंबाई होती है। 0–2 को तिहाइयों में बाँटने पर प्रत्येक भाग 2/3 का होता है, इसलिए दूसरा निशान 4/3 पर आता है। क्षेत्रफल मॉडल में ‘पूरी आकृति’ के आदी बच्चे अक्सर यह गलती करते हैं।"},
  {"id":"cdp-pedagogy-subjects-508","question":"A Class 5 child writes 3.7 + 2 = 3.9. Which explanation and response are most appropriate?","options":["She aligns last digits as in whole numbers; writing 2 as 2.0 shows the 2 is ones, giving 5.7","She does not know the basic fact 7 + 2, so she needs more drill on addition facts","She has added the digits correctly but placed the decimal point in the wrong position","She should be taught to ignore the decimal point while adding and insert it at the end"],"answer":0,"explanation":"Right-aligning digits works for whole numbers but not decimals. Putting the 2 in the ones column (2.0) shows ones must be added to ones: 3.7 + 2.0 = 5.7.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा 5 की एक बच्ची लिखती है 3.7 + 2 = 3.9। कौन-सी व्याख्या और प्रतिक्रिया सबसे उपयुक्त है?","optionsHi":["वह पूर्ण संख्याओं की तरह अंतिम अंकों को सीध में रखती है; 2 को 2.0 लिखने से दिखता है कि 2 इकाई है, जिससे 5.7 मिलता है","उसे आधारभूत तथ्य 7 + 2 नहीं आता, इसलिए उसे जोड़ के तथ्यों का और अभ्यास चाहिए","उसने अंकों को सही जोड़ा है पर दशमलव बिंदु गलत स्थान पर लगाया है","उसे सिखाना चाहिए कि जोड़ते समय दशमलव बिंदु को अनदेखा करे और अंत में लगा दे"],"explanationHi":"अंकों को दाईं ओर सीध में रखना पूर्ण संख्याओं में चलता है, दशमलव में नहीं। 2 को इकाई के स्तंभ में (2.0) रखने से दिखता है कि इकाई को इकाई में जोड़ना है: 3.7 + 2.0 = 5.7।"},
  {"id":"cdp-pedagogy-subjects-509","question":"A Class 6 child says 0.36 is less than 0.3 ‘because hundredths are smaller than tenths’. Which statement best describes her thinking?","options":["She uses the ‘longer is larger’ rule carried over from comparing whole numbers","She uses ‘shorter is larger’: hundredths are smaller parts, so she ignores how many","She compares only the digits after the point and decides that 36 is greater than 3","She has made a careless slip, since she clearly knows that 36 is more than 30"],"answer":1,"explanation":"0.36 = 36 hundredths and 0.3 = 30 hundredths, so 0.36 is bigger. Thinking that more decimal places means smaller pieces, and so a smaller number, is the ‘shorter is larger’ misconception, the opposite of ‘longer is larger’.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा 6 की एक बच्ची कहती है कि 0.36, 0.3 से छोटा है ‘क्योंकि सौवें भाग दसवें भाग से छोटे होते हैं’। उसकी सोच का सबसे अच्छा वर्णन कौन-सा कथन है?","optionsHi":["वह पूर्ण संख्याओं की तुलना से लाया गया ‘जो लंबा वही बड़ा’ नियम लगा रही है","वह ‘जो छोटा वही बड़ा’ लगा रही है: सौवें भाग छोटे टुकड़े हैं, इसलिए वह यह नहीं देखती कि कितने हैं","वह केवल बिंदु के बाद के अंकों की तुलना करती है और मानती है कि 36, 3 से बड़ा है","यह असावधानी की भूल है, क्योंकि वह स्पष्ट रूप से जानती है कि 36, 30 से अधिक है"],"explanationHi":"0.36 = 36 सौवें भाग और 0.3 = 30 सौवें भाग, इसलिए 0.36 बड़ा है। यह सोचना कि दशमलव के अधिक स्थान का अर्थ छोटे टुकड़े और इसलिए छोटी संख्या है, ‘जो छोटा वही बड़ा’ की भ्रांति है, जो ‘जो लंबा वही बड़ा’ के उलट है।"},
  {"id":"cdp-pedagogy-subjects-510","question":"A Class 6 child writes 2.5 × 10 = 2.50, explaining ‘to multiply by 10 you put a zero at the end’. What is the best response?","options":["Tell her the ‘add a zero’ rule works only for whole numbers, and move on to the next sum","Ask her to work out 25 × 10 instead and then put the decimal point back at the end","Use a place-value chart to show each digit moving one place left, so 2.5 becomes 25","Ask her to memorise the new rule ‘move the decimal point one place to the right’"],"answer":2,"explanation":"‘Add a zero’ is a whole-number shortcut that fails for decimals (2.50 = 2.5). Seeing digits shift one place left in a chart explains why the value becomes ten times larger; a new rule to memorise does not.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक बच्ची लिखती है 2.5 × 10 = 2.50 और समझाती है ‘10 से गुणा करने के लिए अंत में एक शून्य लगा देते हैं’। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["उसे बता देना कि ‘शून्य जोड़ने’ का नियम केवल पूर्ण संख्याओं पर चलता है, और अगले प्रश्न पर बढ़ जाना","उससे इसके बजाय 25 × 10 हल करवाना और फिर अंत में दशमलव बिंदु वापस लगवाना","स्थानीय मान तालिका से दिखाना कि प्रत्येक अंक एक स्थान बाईं ओर खिसकता है, जिससे 2.5 से 25 बनता है","उससे नया नियम ‘दशमलव बिंदु को एक स्थान दाईं ओर खिसकाओ’ रटवाना"],"explanationHi":"‘शून्य जोड़ना’ पूर्ण संख्याओं का शॉर्टकट है जो दशमलव में विफल होता है (2.50 = 2.5)। तालिका में अंकों को एक स्थान बाईं ओर खिसकते देखने से समझ आता है कि मान दस गुना क्यों हो जाता है; एक और रटने वाला नियम यह नहीं समझाता।"},
  {"id":"cdp-pedagogy-subjects-511","question":"A child converts 2 m 5 cm into metres and writes 2.5 m. What does the error reveal?","options":["She does not know that 1 m = 100 cm, so she cannot convert between the two units","She has confused metres with kilometres and divided by 1000 instead of by 100","She has made a slip in copying, though she knows the answer should be 2.05 m","She puts the centimetres straight after the point, not seeing 5 cm is 0.05 m"],"answer":3,"explanation":"5 cm = 5/100 m = 0.05 m, so 2 m 5 cm = 2.05 m. Writing 2.5 m (= 2 m 50 cm) shows a weak link between decimal places and measurement units.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक बच्ची 2 m 5 cm को मीटर में बदलकर 2.5 m लिखती है। यह त्रुटि क्या प्रकट करती है?","optionsHi":["उसे नहीं पता कि 1 m = 100 cm, इसलिए वह दोनों इकाइयों के बीच रूपांतरण नहीं कर सकती","उसने मीटर को किलोमीटर समझ लिया है और 1000 से भाग दे दिया है, 100 से नहीं","उतारने में उससे भूल हुई है, जबकि वह जानती है कि उत्तर 2.05 m होना चाहिए","वह सेंटीमीटर को सीधे बिंदु के बाद लिख देती है, यह नहीं देखती कि 5 cm = 0.05 m होता है"],"explanationHi":"5 cm = 5/100 m = 0.05 m, इसलिए 2 m 5 cm = 2.05 m। 2.5 m (= 2 m 50 cm) लिखना दशमलव स्थानों और मापन इकाइयों के बीच कमज़ोर संबंध दर्शाता है।"},
  {"id":"cdp-pedagogy-subjects-512","question":"A shopkeeper raises a ₹100 price by 20% and later reduces the new price by 20%. A Class 8 student says the price is back to ₹100. Which response best uncovers the misconception?","options":["Ask her to work out each step in rupees and note what each 20% is taken of","Tell her that percentages can never be added to or subtracted from each other","Ask her to use the formula for successive change without explaining it","Agree with her, since a 20% rise and a 20% fall of the same price cancel out"],"answer":0,"explanation":"The rise is 20% of ₹100 (₹20, giving ₹120), but the fall is 20% of ₹120 (₹24), leaving ₹96. Working it out shows that a percentage depends on its base, which is exactly what she missed.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"एक दुकानदार ₹100 के मूल्य को 20% बढ़ाता है और बाद में नए मूल्य को 20% घटाता है। कक्षा 8 की एक छात्रा कहती है कि मूल्य फिर ₹100 हो गया। भ्रांति को उजागर करने के लिए कौन-सी प्रतिक्रिया सबसे अच्छी है?","optionsHi":["उससे प्रत्येक चरण रुपयों में हल करवाना और यह नोट करवाना कि हर 20% किसका लिया गया है","उसे बताना कि प्रतिशतों को आपस में कभी जोड़ा या घटाया नहीं जा सकता","उससे क्रमिक परिवर्तन का सूत्र बिना समझाए प्रयोग करवाना","उससे सहमत हो जाना, क्योंकि एक ही मूल्य की 20% वृद्धि और 20% कमी एक-दूसरे को निरस्त कर देती हैं"],"explanationHi":"वृद्धि ₹100 का 20% (₹20, जिससे ₹120) है, पर कमी ₹120 का 20% (₹24) है, जिससे ₹96 बचता है। हल करने से दिखता है कि प्रतिशत अपने आधार पर निर्भर करता है, जिसे वह चूक गई।"},
  {"id":"cdp-pedagogy-subjects-513","question":"A recipe uses 2 cups of rice with 3 cups of water. For 6 cups of rice a child says 7 cups of water ‘because water is always 1 more than rice’. The child's reasoning is:","options":["correct, since the difference between rice and water stays the same at every scale","additive where it should be multiplicative: rice is tripled, so water must be 9 cups","correct for small amounts of rice, but it would not work for much larger amounts","wrong only because she did not use the unitary method to find water for one cup"],"answer":1,"explanation":"Proportional situations keep the ratio, not the difference: 6 is 3 × 2, so water is 3 × 3 = 9 cups. Using a constant difference is the classic additive error in ratio problems.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"एक विधि में 3 कप पानी के साथ 2 कप चावल लगता है। 6 कप चावल के लिए एक बच्चा 7 कप पानी बताता है ‘क्योंकि पानी हमेशा चावल से 1 अधिक होता है’। बच्चे का तर्क है:","optionsHi":["सही, क्योंकि चावल और पानी का अंतर हर मात्रा पर वही रहता है","जहाँ गुणात्मक होना चाहिए वहाँ योगात्मक है: चावल तीन गुना हुआ, इसलिए पानी 9 कप होना चाहिए","थोड़े चावल के लिए सही है, पर बहुत अधिक मात्रा के लिए नहीं चलेगा","केवल इसलिए गलत है कि उसने एक कप के लिए पानी निकालने हेतु ऐकिक विधि नहीं अपनाई"],"explanationHi":"समानुपाती स्थितियों में अनुपात स्थिर रहता है, अंतर नहीं: 6 = 3 × 2, इसलिए पानी 3 × 3 = 9 कप। स्थिर अंतर का प्रयोग अनुपात के प्रश्नों में सबसे आम योगात्मक त्रुटि है।"},
  {"id":"cdp-pedagogy-subjects-514","question":"A Class 7 student says there is no fraction between 2/5 and 3/5 ‘because they come one after the other’. Which question helps her most?","options":["‘What is the next whole number after 2, and the one after 3?’","‘Can you list all the fractions between 0 and 1 for me?’","‘Can you write 2/5 and 3/5 with denominator 10 and look again?’","‘Is 3/5 bigger than 2/5, and how do you know that it is?’"],"answer":2,"explanation":"Renaming as 4/10 and 6/10 reveals 5/10 between them, and again with 20ths, and so on. She is carrying over the whole-number idea of a ‘next’ number; fractions are dense.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक छात्रा कहती है कि 2/5 और 3/5 के बीच कोई भिन्न नहीं है ‘क्योंकि वे एक के बाद एक आती हैं’। कौन-सा प्रश्न उसकी सबसे अधिक मदद करेगा?","optionsHi":["‘2 के बाद की पूर्ण संख्या क्या है, और 3 के बाद की क्या है?’","‘क्या तुम मुझे 0 और 1 के बीच की सभी भिन्नों की सूची बना सकती हो?’","‘क्या तुम 2/5 और 3/5 को हर 10 के साथ लिखकर फिर से देख सकती हो?’","‘क्या 3/5, 2/5 से बड़ा है, और तुम यह कैसे जानती हो?’"],"explanationHi":"4/10 और 6/10 के रूप में बदलने पर उनके बीच 5/10 दिखता है, और 20वें भागों के साथ फिर इसी तरह, और आगे भी। वह पूर्ण संख्याओं के ‘अगली’ संख्या वाले विचार को ले आई है; भिन्नें सघन होती हैं।"},
  {"id":"cdp-pedagogy-subjects-515","question":"After learning that 3x means 3 × x, a Class 7 student reads the mixed number 2 1/3 as 2 × 1/3 = 2/3. Which response best addresses this?","options":["Tell her that mixed numbers are no longer used once algebra begins in Class 7","Ask her to always convert mixed numbers into decimals so the confusion goes away","Mark it wrong and ask her to learn the rule for converting mixed numbers by heart","Explain that 2 1/3 means 2 + 1/3, unlike the algebra convention, and check with drawings"],"answer":3,"explanation":"Here she is wrongly transferring the algebra convention (side by side means multiply). 2 1/3 means 2 + 1/3 = 7/3. Naming the clash between the two conventions and checking with a picture fixes it.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"यह सीखने के बाद कि 3x का अर्थ 3 × x है, कक्षा 7 की एक छात्रा मिश्रित संख्या 2 1/3 को 2 × 1/3 = 2/3 पढ़ती है। इसे संबोधित करने के लिए कौन-सी प्रतिक्रिया सबसे अच्छी है?","optionsHi":["उसे बताना कि कक्षा 7 में बीजगणित शुरू होने के बाद मिश्रित संख्याओं का प्रयोग नहीं होता","उससे कहना कि भ्रम दूर करने के लिए मिश्रित संख्याओं को हमेशा दशमलव में बदले","इसे गलत चिह्नित करना और मिश्रित संख्याओं को बदलने का नियम रटने को कहना","समझाना कि 2 1/3 का अर्थ 2 + 1/3 है, जो बीजगणित की परिपाटी से भिन्न है, और चित्रों से जाँच करवाना"],"explanationHi":"यहाँ वह बीजगणित की परिपाटी (अगल-बगल लिखने का अर्थ गुणा) को गलत जगह लागू कर रही है। 2 1/3 का अर्थ 2 + 1/3 = 7/3 है। दोनों परिपाटियों के टकराव को नाम देना और चित्र से जाँचना इसे ठीक करता है।"},
  {"id":"cdp-pedagogy-subjects-516","question":"Which representation best helps Class 6 children see why 2/3 × 3/4 = 6/12?","options":["Fold a strip into fourths, shade 3/4, then fold into thirds the other way and shade 2/3 of it","Draw 2/3 and 3/4 on two separate number lines and then add the two lengths together","Write the rule ‘multiply tops, multiply bottoms’ on the board and practise it with sums","Cut one roti into 3 parts and another into 4 parts and compare the sizes of the pieces"],"answer":0,"explanation":"Folding both ways gives 12 equal parts, of which 6 are double-shaded: 2/3 of 3/4 is 6/12. The area model shows both the meaning of ‘of’ and why the denominators multiply.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 के बच्चों को यह देखने में कि 2/3 × 3/4 = 6/12 क्यों है, कौन-सा निरूपण सबसे अधिक सहायक है?","optionsHi":["एक पट्टी को चौथाइयों में मोड़ना, 3/4 पर रंग भरना, फिर दूसरी दिशा में तिहाइयों में मोड़कर उसके 2/3 पर रंग भरना","2/3 और 3/4 को दो अलग संख्या रेखाओं पर दर्शाना और फिर दोनों लंबाइयों को जोड़ना","बोर्ड पर नियम ‘अंश को अंश से, हर को हर से गुणा करो’ लिखना और प्रश्नों से उसका अभ्यास कराना","एक रोटी को 3 भागों में और दूसरी को 4 भागों में काटना और टुकड़ों के आकार की तुलना करना"],"explanationHi":"दोनों दिशाओं में मोड़ने पर 12 बराबर भाग बनते हैं, जिनमें 6 पर दोहरा रंग होता है: 3/4 का 2/3 अर्थात 6/12। क्षेत्रफल मॉडल ‘का’ का अर्थ और हरों के गुणा होने का कारण दोनों दिखाता है।"},
  {"id":"cdp-pedagogy-subjects-517","question":"Which story fits the calculation 1 1/2 ÷ 1/4?","options":["What is 1/4 of a ribbon 1 1/2 m long?","How many pieces of 1/4 m can be cut from a ribbon 1 1/2 m long?","A ribbon 1 1/2 m long is shared equally among 4 children. How long is each piece?","A ribbon is 1 1/2 m long and another is 1/4 m. What is their total length?"],"answer":1,"explanation":"‘How many quarters fit into one and a half?’ is the measurement meaning of division, giving 6 pieces. Option A is multiplication by 1/4, and option C is division by 4; both are common mix-ups.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कौन-सी कहानी गणना 1 1/2 ÷ 1/4 पर सटीक बैठती है?","optionsHi":["उस रिबन का 1/4 भाग कितना लंबा होगा, जो 1 1/2 m लंबा है?","1/4 m के कितने टुकड़े 1 1/2 m लंबे रिबन से काटे जा सकते हैं?","1 1/2 m लंबा रिबन 4 बच्चों में बराबर बाँटा गया। प्रत्येक टुकड़ा कितना लंबा है?","एक रिबन 1 1/2 m लंबा है और दूसरा 1/4 m का। उनकी कुल लंबाई कितनी है?"],"explanationHi":"‘डेढ़ में कितने चौथाई समाते हैं?’ भाग का मापन वाला अर्थ है, जिसका उत्तर 6 टुकड़े है। विकल्प A, 1/4 से गुणा है और विकल्प C, 4 से भाग है; दोनों आम गड़बड़ियाँ हैं।"},
  {"id":"cdp-pedagogy-subjects-518","question":"A teacher used money to introduce decimals. Later a child reads ₹2.5 as ‘two rupees and five paise’. What does this most clearly show?","options":["She has not yet learnt that 100 paise make a rupee, so she cannot convert between them","She is careless with the decimal point and needs reminders to read numbers slowly","The money model tied decimals to two places, so she reads the 5 as paise, not as 5 tenths","She has confused rupees with paise and so reads the whole amount in the wrong unit"],"answer":2,"explanation":"Money always shows two decimal places, so children may read digits after the point as a whole-number count of paise. A place-value chart showing 2.5 = 2.50 corrects this limitation of the model.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"एक शिक्षक ने दशमलव समझाने के लिए पैसे का प्रयोग किया। बाद में एक बच्ची ₹2.5 को ‘दो रुपये और पाँच पैसे’ पढ़ती है। यह सबसे स्पष्ट रूप से क्या दर्शाता है?","optionsHi":["उसने अभी तक नहीं सीखा कि 100 पैसे का एक रुपया होता है, इसलिए वह उनके बीच रूपांतरण नहीं कर सकती","वह दशमलव बिंदु के प्रति लापरवाह है और उसे संख्याएँ धीरे पढ़ने की याद दिलानी पड़ती है","पैसे के मॉडल ने दशमलव को दो स्थानों से बाँध दिया, इसलिए वह 5 को 5 दसवें भाग के बजाय पैसे पढ़ती है","उसने रुपये और पैसे को उलझा दिया है और इसलिए पूरी राशि गलत इकाई में पढ़ती है"],"explanationHi":"पैसे में हमेशा दशमलव के दो स्थान दिखते हैं, इसलिए बच्चे बिंदु के बाद के अंकों को पैसों की पूर्ण संख्या की गिनती के रूप में पढ़ सकते हैं। 2.5 = 2.50 दिखाने वाली स्थानीय मान तालिका इस मॉडल की सीमा को ठीक करती है।"},
  {"id":"cdp-pedagogy-subjects-519","question":"Asked to find 35% of 240, four Class 7 students explain their thinking. Whose explanation shows the strongest understanding of percent?","options":["‘35 by 100 into 240 is 84, because that is the percentage formula.’","‘35% means 35 out of 240, so the answer is simply 35.’","‘Multiply 35 by 240 and divide by 10 to get the answer.’","‘10% is 24, so 30% is 72; 5% is half of 24, which is 12. So 84.’"],"answer":3,"explanation":"Building 35% from 10% and 5% shows that percent means ‘per hundred of this quantity’ and uses relationships flexibly. The formula answer is right but unexplained; B and C show misconceptions.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"240 का 35% ज्ञात करने को कहने पर कक्षा 7 के चार विद्यार्थी अपनी सोच समझाते हैं। किसकी व्याख्या प्रतिशत की सबसे मज़बूत समझ दिखाती है?","optionsHi":["‘35 बटा 100 गुणा 240 है 84, क्योंकि यही प्रतिशत का सूत्र है।’","‘35% का अर्थ है 35, जो 240 में से लिया गया है, इसलिए उत्तर सीधे 35 है।’","‘35 को 240 से गुणा करो और 10 से भाग दो तो उत्तर मिल जाएगा।’","‘10% है 24, तो 30% है 72; 5% है 24 का आधा, यानी 12। तो 84।’"],"explanationHi":"35% को 10% और 5% से बनाना दिखाता है कि प्रतिशत का अर्थ ‘इस राशि के प्रति सौ’ है और संबंधों का लचीला प्रयोग करता है। सूत्र वाला उत्तर सही है पर अव्याख्यायित; B और C भ्रांतियाँ दर्शाते हैं।"},
  {"id":"cdp-pedagogy-subjects-520","question":"Which of these statements about teaching fractions are correct? I. Fractions can be introduced through equal sharing of real things such as rotis. II. Children should learn that the fraction with the bigger denominator is always the smaller one. III. Placing fractions on a number line helps children see them as numbers. IV. Showing shapes cut into unequal parts, and asking why they are not quarters, deepens understanding.","options":["I, III and IV","I, II and III","II and IV only","I and III only"],"answer":0,"explanation":"Statement II is true only when the numerators are equal (3/4 > 2/3 although 4 > 3), so teaching it as a rule creates a new misconception. Non-examples, as in IV, sharpen the idea of equal parts.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"भिन्न पढ़ाने के बारे में इनमें से कौन-से कथन सही हैं? I. भिन्न को रोटियों जैसी वास्तविक वस्तुओं के बराबर बाँटने से परिचित कराया जा सकता है। II. बच्चों को सीखना चाहिए कि बड़े हर वाली भिन्न हमेशा छोटी होती है। III. भिन्नों को संख्या रेखा पर रखने से बच्चों को उन्हें संख्याओं के रूप में देखने में मदद मिलती है। IV. असमान भागों में कटी आकृतियाँ दिखाना और पूछना कि वे चौथाई क्यों नहीं हैं, समझ को गहरा करता है।","optionsHi":["I, III और IV","I, II और III","केवल II और IV","केवल I और III"],"explanationHi":"कथन II केवल तब सत्य है जब अंश बराबर हों (3/4 > 2/3 यद्यपि 4 > 3), इसलिए इसे नियम के रूप में पढ़ाने से नई भ्रांति बनती है। IV की तरह गैर-उदाहरण बराबर भागों के विचार को तीक्ष्ण करते हैं।"},
  {"id":"cdp-pedagogy-subjects-521","question":"Assertion (A): Children who know only that ‘a fraction is a part of a whole’ often struggle with fractions such as 5/4. Reason (R): With only the part-whole view, they ask how 5 parts can be taken from a whole that has 4.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Improper fractions make sense as measures (5 quarter-lengths) or quotients (5 ÷ 4), not within a single whole. R explains why a narrow part-whole view causes the difficulty in A.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): जो बच्चे केवल यह जानते हैं कि ‘भिन्न पूर्ण का एक भाग है’, उन्हें अक्सर 5/4 जैसी भिन्नों में कठिनाई होती है। कारण (R): केवल भाग-पूर्ण दृष्टि से वे पूछते हैं कि 4 भागों वाले पूर्ण में से 5 भाग कैसे लिए जा सकते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"विषम भिन्न माप (5 चौथाई-लंबाइयाँ) या भागफल (5 ÷ 4) के रूप में अर्थपूर्ण होती हैं, किसी एक पूर्ण के भीतर नहीं। R बताता है कि संकीर्ण भाग-पूर्ण दृष्टि A में वर्णित कठिनाई क्यों पैदा करती है।"},
  {"id":"cdp-pedagogy-subjects-522","question":"A Class 6 child writes 0.6 ÷ 3 = 2. What is the best first question for the teacher to ask?","options":["‘Did you remember to put the decimal point in your answer?’","‘What is 6 ÷ 3, and where should the point go now?’","‘If 0.6 kg of sugar is shared by 3 people, can each get 2 kg?’","‘Can you show 3 × 2 on a number line and check your answer?’"],"answer":2,"explanation":"A sense-making context shows at once that each share must be less than 0.6 kg; in fact it is 0.2 kg. The child has ignored the point and divided 6 by 3. Checking reasonableness is better than a reminder about the point.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 6 की एक बच्ची लिखती है 0.6 ÷ 3 = 2। शिक्षक के पूछने के लिए सबसे अच्छा पहला प्रश्न क्या है?","optionsHi":["‘क्या तुमने अपने उत्तर में दशमलव बिंदु लगाना याद रखा?’","‘6 ÷ 3 कितना होता है, और अब बिंदु कहाँ लगेगा?’","‘यदि 0.6 kg चीनी 3 लोगों में बाँटी जाए, तो क्या प्रत्येक को 2 kg मिल सकती है?’","‘क्या तुम संख्या रेखा पर 3 × 2 दिखाकर अपने उत्तर की जाँच कर सकती हो?’"],"explanationHi":"अर्थपूर्ण संदर्भ तुरंत दिखा देता है कि प्रत्येक हिस्सा 0.6 kg से कम होना चाहिए; वास्तव में यह 0.2 kg है। बच्ची ने बिंदु को अनदेखा करके 6 को 3 से भाग दे दिया है। औचित्य की जाँच करना बिंदु की याद दिलाने से बेहतर है।"},
  {"id":"cdp-pedagogy-subjects-523","question":"Which task best checks whether a Class 5 child sees a fraction as a number with a size, not just as shaded pieces?","options":["Shade 3/8 of a rectangle divided into eight equal parts","Write the fraction for the shaded part of a circle drawn on the board","Name the numerator and denominator of 7/8 and say what each means","Is 7/8 closer to 0, to 1/2 or to 1? Explain how you know"],"answer":3,"explanation":"Judging closeness to benchmarks (7/8 is only 1/8 short of 1) needs a sense of the fraction's size. Shading and naming test part-whole pictures and vocabulary only.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कौन-सा कार्य सबसे अच्छी तरह जाँचता है कि कक्षा 5 की बच्ची भिन्न को केवल रंगे हुए टुकड़ों के रूप में नहीं, बल्कि आकार वाली संख्या के रूप में देखती है?","optionsHi":["आठ बराबर भागों में बँटे आयत के 3/8 भाग पर रंग भरना","बोर्ड पर बने वृत्त के रंगे हुए भाग के लिए भिन्न लिखना","7/8 के अंश और हर के नाम बताना और यह कहना कि प्रत्येक का क्या अर्थ है","क्या 7/8, 0, 1/2 या 1 में से किसके अधिक निकट है? बताओ कि तुम यह कैसे जानती हो"],"explanationHi":"मानक संख्याओं से निकटता का निर्णय करने (7/8, 1 से केवल 1/8 कम है) के लिए भिन्न के आकार की समझ चाहिए। रंग भरना और नाम बताना केवल भाग-पूर्ण चित्रों और शब्दावली की जाँच करते हैं।"},
  {"id":"cdp-pedagogy-subjects-524","question":"A Class 5 child writes 1/4 = 0.4 and 1/5 = 0.5. What is she doing?","options":["Dividing the denominator by the numerator and writing the result as a decimal","Writing the denominator after the point, not seeing 1/4 as 25 hundredths","Rounding each fraction to one decimal place, as she was taught for measurement","Confusing fractions with percentages, so she reads 1/4 as 4 per cent of a whole"],"answer":1,"explanation":"1/4 = 0.25 and 1/5 = 0.2. Copying the visible digit after the point shows she has not linked decimals to tenths and hundredths; a 10 × 10 grid shading 1/4 helps.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक बच्ची लिखती है 1/4 = 0.4 और 1/5 = 0.5। वह क्या कर रही है?","optionsHi":["हर को अंश से भाग देकर परिणाम को दशमलव के रूप में लिख रही है","हर को ही बिंदु के बाद लिख रही है, 1/4 को 25 सौवें भाग के रूप में नहीं देख रही","प्रत्येक भिन्न को एक दशमलव स्थान तक पूर्णांकित कर रही है, जैसा उसे मापन के लिए सिखाया गया था","भिन्नों को प्रतिशतों से उलझा रही है, इसलिए 1/4 को पूर्ण का 4 प्रतिशत पढ़ती है"],"explanationHi":"1/4 = 0.25 और 1/5 = 0.2। दिखाई देने वाले अंक को बिंदु के बाद उतार देना दर्शाता है कि उसने दशमलव को दसवें और सौवें भागों से नहीं जोड़ा है; 1/4 को 10 × 10 ग्रिड पर रंगने से मदद मिलती है।"},
  {"id":"cdp-pedagogy-subjects-525","question":"A Class 8 English teacher in a Gorakhpur school reads each sentence of the lesson aloud, gives its Hindi meaning, makes students copy word lists with Hindi equivalents and sets passages for translation. Her students score well in written tests but cannot hold a simple conversation. Which method is she using, and what is its main weakness here?","options":["Bilingual method; it allows the mother tongue only at sentence level and so slows comprehension","Grammar-translation method; it neglects listening and speaking and treats language as knowledge","Direct method; using the target language only makes the lessons too difficult for these learners","Audio-lingual method; its heavy oral drilling leaves students little time to read or write anything"],"answer":1,"explanation":"Sentence-by-sentence translation, bilingual word lists and written translation are the hallmarks of grammar-translation, which develops reading and accuracy but not spoken communication.","difficulty":"moderate","source":"CTET Paper II · State TETs","questionHi":"गोरखपुर के एक विद्यालय में कक्षा 8 की अंग्रेज़ी की शिक्षिका पाठ का प्रत्येक वाक्य ज़ोर से पढ़ती है, उसका हिंदी अर्थ बताती है, विद्यार्थियों से हिंदी पर्यायों वाली शब्द-सूचियाँ उतरवाती है और अनुवाद के लिए गद्यांश देती है। उसके विद्यार्थी लिखित परीक्षाओं में अच्छे अंक लाते हैं पर एक सामान्य बातचीत नहीं कर पाते। वह कौन-सी विधि अपना रही है, और यहाँ उसकी मुख्य कमज़ोरी क्या है?","optionsHi":["द्विभाषिक विधि; यह मातृभाषा को केवल वाक्य स्तर तक अनुमति देती है और इसलिए बोध को धीमा करती है","व्याकरण-अनुवाद विधि; यह सुनने और बोलने की उपेक्षा करती है तथा भाषा को ज्ञान के रूप में देखती है","प्रत्यक्ष विधि; केवल लक्ष्य भाषा के प्रयोग से इन शिक्षार्थियों के लिए पाठ बहुत कठिन हो जाते हैं","श्रव्य-भाषिक विधि; इसका भारी मौखिक अभ्यास विद्यार्थियों को पढ़ने-लिखने का बहुत कम समय देता है"],"explanationHi":"वाक्य-दर-वाक्य अनुवाद, द्विभाषिक शब्द-सूचियाँ और लिखित अनुवाद व्याकरण-अनुवाद विधि की पहचान हैं, जो पठन और शुद्धता विकसित करती है पर बोलचाल का संप्रेषण नहीं।"},
  {"id":"cdp-pedagogy-subjects-526","question":"A teacher using the direct method never uses the mother tongue, teaches ‘window’ by pointing, and lets children work out grammar from oral examples. Which criticism of this method is most valid in a typical Indian government school?","options":["It neglects oral skills because it gives most class time to reading and to written grammar exercises","Abstract words are hard to convey without the mother tongue, and it needs very fluent teachers","It teaches grammar deductively, with rules first, which young learners find hard to follow","It depends on translation, so learners never start thinking directly in the target language"],"answer":1,"explanation":"Mime and realia work for ‘window’ but not for ‘honesty’ or ‘although’, and the method assumes teachers with native-like fluency. Options A to C describe grammar-translation, not the direct method.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"प्रत्यक्ष विधि अपनाने वाला एक शिक्षक कभी मातृभाषा का प्रयोग नहीं करता, ‘window’ को इशारा करके सिखाता है और बच्चों को मौखिक उदाहरणों से व्याकरण स्वयं निकालने देता है। एक सामान्य भारतीय सरकारी विद्यालय में इस विधि की कौन-सी आलोचना सबसे अधिक उचित है?","optionsHi":["यह मौखिक कौशलों की उपेक्षा करती है क्योंकि कक्षा का अधिकांश समय पठन और लिखित व्याकरण अभ्यासों को देती है","मातृभाषा के बिना अमूर्त शब्दों को समझाना कठिन है, और इसके लिए अत्यंत धाराप्रवाह शिक्षक चाहिए","यह व्याकरण निगमनात्मक ढंग से, पहले नियम देकर, सिखाती है, जिसे छोटे शिक्षार्थी समझने में कठिनाई पाते हैं","यह अनुवाद पर निर्भर है, इसलिए शिक्षार्थी लक्ष्य भाषा में सीधे सोचना कभी शुरू नहीं करते"],"explanationHi":"अभिनय और वास्तविक वस्तुएँ ‘window’ के लिए काम करती हैं, पर ‘honesty’ या ‘although’ के लिए नहीं, और यह विधि मानती है कि शिक्षक मातृभाषी जैसे धाराप्रवाह हैं। विकल्प A से C व्याकरण-अनुवाद विधि का वर्णन करते हैं, प्रत्यक्ष विधि का नहीं।"},
  {"id":"cdp-pedagogy-subjects-527","question":"A Pune teacher says, ‘I go to school. He…’ and students respond, ‘He goes to school.’ She then says ‘They…’, and so on. Students also memorise dialogues, and she corrects errors at once and praises correct responses. The theoretical basis of this method is:","options":["Cognitive psychology and the idea that learners test hypotheses about rules","Vygotsky’s socio-cultural theory and learning through social interaction with peers","Chomsky’s nativism and the language acquisition device","Behaviourist psychology and structural linguistics, treating language as habit"],"answer":3,"explanation":"Drills, dialogue memorisation, immediate correction and reinforcement mark the audio-lingual method, built on Skinnerian habit formation and structural descriptions of language.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"पुणे की एक शिक्षिका कहती है, ‘I go to school. He…’ और विद्यार्थी उत्तर देते हैं, ‘He goes to school.’ फिर वह कहती है ‘They…’, और इसी तरह आगे। विद्यार्थी संवाद भी याद करते हैं, और वह त्रुटियाँ तुरंत सुधारती है तथा सही उत्तरों की प्रशंसा करती है। इस विधि का सैद्धांतिक आधार है:","optionsHi":["संज्ञानात्मक मनोविज्ञान और यह विचार कि शिक्षार्थी नियमों के बारे में परिकल्पनाओं का परीक्षण करते हैं","वाइगोत्स्की का सामाजिक-सांस्कृतिक सिद्धांत और साथियों के साथ सामाजिक अंतःक्रिया से सीखना","चॉम्स्की का जन्मजातवाद और भाषा अर्जन युक्ति","व्यवहारवादी मनोविज्ञान और संरचनात्मक भाषाविज्ञान, जो भाषा को आदत मानते हैं"],"explanationHi":"अभ्यास, संवाद कंठस्थ करना, तुरंत सुधार और पुनर्बलन श्रव्य-भाषिक विधि की पहचान हैं, जो स्किनर की आदत निर्माण और भाषा के संरचनात्मक वर्णन पर आधारित है।"},
  {"id":"cdp-pedagogy-subjects-528","question":"To help learners say a long sentence, a teacher has them repeat ‘…to the market’, then ‘…going to the market’, then ‘…am going to the market’ and finally ‘I am going to the market.’ This audio-lingual technique is called:","options":["Backward build-up drill","Sentence transformation drill","Substitution drill","Chain drill"],"answer":0,"explanation":"In backward build-up the sentence is built from the end so that learners always finish on the familiar, correctly stressed part. A substitution drill swaps one word; a transformation drill changes the structure; a chain drill passes a question from learner to learner.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"शिक्षार्थियों को एक लंबा वाक्य बोलने में मदद देने के लिए एक शिक्षक उनसे ‘…to the market’, फिर ‘…going to the market’, फिर ‘…am going to the market’ और अंत में ‘I am going to the market.’ दोहरवाता है। इस श्रव्य-भाषिक तकनीक को कहते हैं:","optionsHi":["पश्च निर्माण अभ्यास (Backward build-up drill)","वाक्य रूपांतरण अभ्यास","प्रतिस्थापन अभ्यास","शृंखला अभ्यास"],"explanationHi":"पश्च निर्माण में वाक्य अंत से बनाया जाता है ताकि शिक्षार्थी हमेशा परिचित और सही बलाघात वाले भाग पर समाप्त करें। प्रतिस्थापन अभ्यास में एक शब्द बदला जाता है; रूपांतरण अभ्यास में संरचना बदली जाती है; शृंखला अभ्यास में प्रश्न एक शिक्षार्थी से दूसरे को दिया जाता है।"},
  {"id":"cdp-pedagogy-subjects-529","question":"Class 7 students plan a class trip to Jaipur. In groups they compare train timings, work out a budget and write an email to the principal asking for permission; the teacher looks mainly at whether each plan is clear and complete, and takes up useful language afterwards. This lesson is best described as:","options":["Situational language teaching, since a new structure is presented through a real situation","Audio-lingual teaching, since the groups repeat useful phrases until they become habits","Task-based language teaching, organised around a meaningful task with a real outcome","Grammar-translation, since the email is written and checked for correctness at the end"],"answer":2,"explanation":"The lesson centres on a task with a non-linguistic outcome (a workable plan), meaning comes first, and attention to form follows the task, as in TBLT.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 7 के विद्यार्थी जयपुर की कक्षा यात्रा की योजना बनाते हैं। समूहों में वे रेल समय-सारणियों की तुलना करते हैं, बजट बनाते हैं और अनुमति माँगते हुए प्रधानाचार्य को ईमेल लिखते हैं; शिक्षक मुख्यतः यह देखता है कि प्रत्येक योजना स्पष्ट और पूर्ण है या नहीं, और बाद में उपयोगी भाषा पर चर्चा करता है। इस पाठ का सबसे अच्छा वर्णन है:","optionsHi":["परिस्थितिजन्य भाषा शिक्षण, क्योंकि नई संरचना एक वास्तविक परिस्थिति के माध्यम से प्रस्तुत की जाती है","श्रव्य-भाषिक शिक्षण, क्योंकि समूह उपयोगी वाक्यांशों को तब तक दोहराते हैं जब तक वे आदत न बन जाएँ","कार्य-आधारित भाषा शिक्षण, जो वास्तविक परिणाम वाले सार्थक कार्य के इर्द-गिर्द संगठित है","व्याकरण-अनुवाद, क्योंकि ईमेल लिखा जाता है और अंत में शुद्धता के लिए जाँचा जाता है"],"explanationHi":"पाठ एक ऐसे कार्य पर केंद्रित है जिसका परिणाम भाषाई नहीं है (एक व्यावहारिक योजना), अर्थ पहले आता है, और रूप पर ध्यान कार्य के बाद दिया जाता है, जैसा TBLT में होता है।"},
  {"id":"cdp-pedagogy-subjects-530","question":"In Jane Willis’s task-based framework, after groups have presented their survey results to the class, the teacher draws attention to phrases they used or needed (‘Most of us…’, ‘Only a few…’) and gives brief practice. This stage is called:","options":["The pre-task (introduction to the topic and task)","The planning stage of the task cycle","The language focus (analysis and practice)","The report stage of the task cycle"],"answer":2,"explanation":"Willis’s framework runs pre-task, task cycle (task, planning, report) and then language focus, where learners analyse and practise forms that arose during the task.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"जेन विलिस के कार्य-आधारित ढाँचे में, समूहों द्वारा कक्षा के सामने अपने सर्वेक्षण के परिणाम प्रस्तुत करने के बाद, शिक्षक उन वाक्यांशों (‘Most of us…’, ‘Only a few…’) की ओर ध्यान दिलाता है जिनका उन्होंने प्रयोग किया या जिनकी उन्हें आवश्यकता थी, और संक्षिप्त अभ्यास कराता है। इस चरण को कहते हैं:","optionsHi":["पूर्व-कार्य (विषय और कार्य का परिचय)","कार्य चक्र का योजना चरण","भाषा पर ध्यान (विश्लेषण और अभ्यास)","कार्य चक्र का प्रतिवेदन चरण"],"explanationHi":"विलिस का ढाँचा पूर्व-कार्य, कार्य चक्र (कार्य, योजना, प्रतिवेदन) और फिर भाषा पर ध्यान के क्रम में चलता है, जहाँ शिक्षार्थी कार्य के दौरान आए रूपों का विश्लेषण और अभ्यास करते हैं।"},
  {"id":"cdp-pedagogy-subjects-531","question":"Assertion (A): In task-based language teaching, explicit work on grammar usually comes after the task rather than before it. Reason (R): Learners notice the forms they need more readily after trying to communicate a message with their own resources.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Unlike present-practise-produce, TBLT puts form-focus after the task because the attempt to communicate makes learners aware of gaps, so the language focus meets a felt need.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"अभिकथन (A): कार्य-आधारित भाषा शिक्षण में व्याकरण पर स्पष्ट कार्य प्रायः कार्य से पहले नहीं, बल्कि बाद में आता है। कारण (R): शिक्षार्थी अपने संसाधनों से कोई संदेश संप्रेषित करने का प्रयास करने के बाद अपनी आवश्यकता के रूपों पर अधिक सहजता से ध्यान देते हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"प्रस्तुत-अभ्यास-उत्पादन विधि के विपरीत, TBLT रूप पर ध्यान कार्य के बाद रखता है, क्योंकि संप्रेषण का प्रयास शिक्षार्थियों को अपनी कमियों के प्रति जागरूक करता है, इसलिए भाषा पर ध्यान एक अनुभव की गई आवश्यकता को पूरा करता है।"},
  {"id":"cdp-pedagogy-subjects-532","question":"Consider these statements about Total Physical Response: I. It links language with physical movement, which helps memory. II. It lets beginners show understanding before they are expected to speak. III. It is best suited to teaching abstract vocabulary and complex grammar to advanced learners. Which are correct?","options":["I, II and III","I and II only","II and III only","I only"],"answer":1,"explanation":"Asher’s TPR builds comprehension through commands and actions and allows a silent period. It is hard to use for abstract ideas and advanced structures, so III is false.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"पूर्ण शारीरिक प्रतिक्रिया (Total Physical Response) के बारे में इन कथनों पर विचार कीजिए: I. यह भाषा को शारीरिक गति से जोड़ती है, जो स्मृति में सहायक होती है। II. यह आरंभिक शिक्षार्थियों को बोलने की अपेक्षा से पहले अपनी समझ दिखाने देती है। III. यह उन्नत शिक्षार्थियों को अमूर्त शब्दावली और जटिल व्याकरण सिखाने के लिए सबसे उपयुक्त है। कौन-से सही हैं?","optionsHi":["I, II और III","केवल I और II","केवल II और III","केवल I"],"explanationHi":"आशर की TPR आदेशों और क्रियाओं से बोध विकसित करती है और मौन अवधि की अनुमति देती है। अमूर्त विचारों और उन्नत संरचनाओं के लिए इसका प्रयोग कठिन है, इसलिए III असत्य है।"},
  {"id":"cdp-pedagogy-subjects-533","question":"Which practice is LEAST consistent with the whole language approach in a Class 1 classroom?","options":["Shared reading of a big book, pointing to words while reading the story together","Linking reading and writing to the theme children are exploring in EVS","Children writing greeting cards and notes for real readers at home and school","Daily worksheets of isolated letter sounds before children see any real story"],"answer":3,"explanation":"Whole language moves from whole, meaningful texts to parts, so isolating sounds before any real reading contradicts it. The other practices use authentic texts and purposes.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"कक्षा 1 की कक्षा में समग्र भाषा उपागम के साथ कौन-सा अभ्यास सबसे कम संगत है?","optionsHi":["बड़ी पुस्तक का साझा पठन, कहानी को साथ-साथ पढ़ते हुए शब्दों की ओर संकेत करना","पठन और लेखन को उस विषय से जोड़ना जिसे बच्चे EVS में खोज रहे हैं","बच्चों द्वारा घर और विद्यालय के वास्तविक पाठकों के लिए बधाई कार्ड और नोट लिखना","बच्चों के कोई वास्तविक कहानी देखने से पहले अलग-थलग अक्षर-ध्वनियों की दैनिक कार्यपत्रिकाएँ"],"explanationHi":"समग्र भाषा संपूर्ण, अर्थपूर्ण पाठों से अंशों की ओर बढ़ती है, इसलिए किसी वास्तविक पठन से पहले ध्वनियों को अलग करना इसके विरुद्ध है। अन्य अभ्यास प्रामाणिक पाठों और उद्देश्यों का प्रयोग करते हैं।"},
  {"id":"cdp-pedagogy-subjects-534","question":"A teacher draws a table on the board with columns ‘This / That’, ‘is’, ‘a / an’ and ‘pen / umbrella / bag’, and children make as many correct sentences as they can. This practice belongs to:","options":["The structural approach, which drills graded sentence patterns through substitution","Communicative language teaching, which builds fluency through information-gap activities","Task-based teaching, which organises learning around tasks with real outcomes","The whole language approach, which teaches language through authentic texts"],"answer":0,"explanation":"Substitution tables are a typical tool of the structural approach, widely used in Indian schools, which grades and drills sentence patterns one at a time, largely orally.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"एक शिक्षक बोर्ड पर स्तंभों ‘This / That’, ‘is’, ‘a / an’ और ‘pen / umbrella / bag’ वाली तालिका बनाता है, और बच्चे जितने अधिक से अधिक सही वाक्य बना सकते हैं, बनाते हैं। यह अभ्यास किससे संबंधित है?","optionsHi":["संरचनात्मक उपागम, जो प्रतिस्थापन द्वारा श्रेणीबद्ध वाक्य-प्रतिरूपों का अभ्यास कराता है","संप्रेषणात्मक भाषा शिक्षण, जो सूचना-अंतराल गतिविधियों से प्रवाह विकसित करता है","कार्य-आधारित शिक्षण, जो वास्तविक परिणाम वाले कार्यों के इर्द-गिर्द अधिगम को संगठित करता है","समग्र भाषा उपागम, जो प्रामाणिक पाठों के माध्यम से भाषा सिखाता है"],"explanationHi":"प्रतिस्थापन तालिकाएँ संरचनात्मक उपागम का विशिष्ट साधन हैं, जिसका भारतीय विद्यालयों में व्यापक प्रयोग होता है और जो वाक्य-प्रतिरूपों को एक-एक करके, मुख्यतः मौखिक रूप से, श्रेणीबद्ध करके अभ्यास कराता है।"},
  {"id":"cdp-pedagogy-subjects-535","question":"A teacher reads an English sentence aloud, gives its Telugu equivalent once to make the meaning clear, and then has learners practise only the English sentence orally in many variations. Learners themselves never translate. This is closest to:","options":["C. J. Dodson’s bilingual method","The direct method","The audio-lingual (oral drill) method","The grammar-translation method"],"answer":0,"explanation":"In Dodson’s bilingual method only the teacher uses the mother tongue, at sentence level, to convey meaning; practice is in English. Grammar-translation makes learners translate texts, and the direct method bans the mother tongue.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"एक शिक्षक अंग्रेज़ी का वाक्य ज़ोर से पढ़ता है, अर्थ स्पष्ट करने के लिए एक बार उसका तेलुगु समतुल्य बताता है, और फिर शिक्षार्थियों से केवल अंग्रेज़ी वाक्य का ही अनेक रूपों में मौखिक अभ्यास कराता है। शिक्षार्थी स्वयं कभी अनुवाद नहीं करते। यह किसके सबसे निकट है?","optionsHi":["सी. जे. डॉडसन की द्विभाषिक विधि","प्रत्यक्ष विधि","श्रव्य-भाषिक (मौखिक अभ्यास) विधि","व्याकरण-अनुवाद विधि"],"explanationHi":"डॉडसन की द्विभाषिक विधि में केवल शिक्षक मातृभाषा का प्रयोग, वाक्य स्तर पर, अर्थ समझाने के लिए करता है; अभ्यास अंग्रेज़ी में होता है। व्याकरण-अनुवाद में शिक्षार्थी पाठों का अनुवाद करते हैं, और प्रत्यक्ष विधि मातृभाषा पर रोक लगाती है।"},
  {"id":"cdp-pedagogy-subjects-536","question":"Match each method with its typical feature: 1. Silent Way 2. Suggestopedia 3. Community Language Learning 4. Total Physical Response; a. The teacher acts as a counsellor and helps translate what learners want to say b. A relaxed setting with music and comfortable seating removes mental barriers c. The teacher speaks very little and uses coloured rods and charts d. Learners respond to commands with actions","options":["1-a, 2-b, 3-c, 4-d","1-c, 2-a, 3-b, 4-d","1-c, 2-b, 3-a, 4-d","1-c, 2-b, 3-d, 4-a"],"answer":2,"explanation":"Gattegno’s Silent Way uses rods and teacher silence; Lozanov’s Suggestopedia uses music and relaxation; Curran’s CLL casts the teacher as counsellor; Asher’s TPR pairs commands with actions.","difficulty":"very-hard","source":"DSSSB · KVS TGT · CTET Paper II","questionHi":"प्रत्येक विधि का मिलान उसकी विशिष्ट विशेषता से कीजिए: 1. मौन पथ (Silent Way) 2. सुझावशास्त्र (Suggestopedia) 3. सामुदायिक भाषा अधिगम (Community Language Learning) 4. पूर्ण शारीरिक प्रतिक्रिया (Total Physical Response); a. शिक्षक परामर्शदाता के रूप में कार्य करता है और शिक्षार्थी जो कहना चाहते हैं उसका अनुवाद करने में मदद करता है b. संगीत और आरामदायक बैठक वाला शांत वातावरण मानसिक बाधाएँ दूर करता है c. शिक्षक बहुत कम बोलता है और रंगीन छड़ों तथा चार्टों का उपयोग करता है d. शिक्षार्थी आदेशों पर क्रियाओं से प्रतिक्रिया देते हैं","optionsHi":["1-a, 2-b, 3-c, 4-d","1-c, 2-a, 3-b, 4-d","1-c, 2-b, 3-a, 4-d","1-c, 2-b, 3-d, 4-a"],"explanationHi":"गैटेग्नो का मौन पथ छड़ों और शिक्षक की चुप्पी का प्रयोग करता है; लोज़ानोव का सुझावशास्त्र संगीत और विश्राम का; कुरैन का CLL शिक्षक को परामर्शदाता बनाता है; आशर की TPR आदेशों को क्रियाओं से जोड़ती है।"},
  {"id":"cdp-pedagogy-subjects-537","question":"Which feature is shared by the direct method and the audio-lingual method?","options":["Both teach grammar deductively by stating the rule before examples","Both are based on the cognitive view that learners form and test hypotheses","Both rely on translation to check that learners have understood","Both give priority to speech and keep the mother tongue out of class"],"answer":3,"explanation":"Both put spoken language first and avoid the mother tongue; both also treat grammar inductively. Translation belongs to grammar-translation, and the audio-lingual method is behaviourist, not cognitive.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"प्रत्यक्ष विधि और श्रव्य-भाषिक विधि में कौन-सी विशेषता समान है?","optionsHi":["दोनों उदाहरणों से पहले नियम बताकर व्याकरण निगमनात्मक ढंग से सिखाती हैं","दोनों इस संज्ञानात्मक दृष्टि पर आधारित हैं कि शिक्षार्थी परिकल्पनाएँ बनाते और परखते हैं","दोनों यह जाँचने के लिए अनुवाद पर निर्भर हैं कि शिक्षार्थियों ने समझा या नहीं","दोनों बोली जाने वाली भाषा को प्राथमिकता देती हैं और मातृभाषा को कक्षा से बाहर रखती हैं"],"explanationHi":"दोनों बोलचाल की भाषा को पहले रखती हैं और मातृभाषा से बचती हैं; दोनों व्याकरण को आगमनात्मक ढंग से भी देखती हैं। अनुवाद व्याकरण-अनुवाद विधि का अंग है, और श्रव्य-भाषिक विधि व्यवहारवादी है, संज्ञानात्मक नहीं।"},
  {"id":"cdp-pedagogy-subjects-538","question":"A Class 10 student writes a flawless application but begins it ‘Hi Principal buddy’. In Canale and Swain’s model of communicative competence, the component he most needs to develop is:","options":["Grammatical competence","Discourse competence","Sociolinguistic competence","Strategic competence"],"answer":2,"explanation":"Sociolinguistic competence is using language appropriately for the setting, relationship and purpose. His grammar is fine; the problem is appropriacy.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 10 का एक विद्यार्थी त्रुटिहीन आवेदन लिखता है, पर उसे ‘Hi Principal buddy’ से आरंभ करता है। कैनेल और स्वेन के संप्रेषणात्मक सक्षमता के मॉडल में, उसे जिस घटक को सबसे अधिक विकसित करने की आवश्यकता है, वह है:","optionsHi":["व्याकरणिक सक्षमता","प्रवचन सक्षमता","सामाजिक-भाषाई सक्षमता","रणनीतिक सक्षमता"],"explanationHi":"सामाजिक-भाषाई सक्षमता का अर्थ है स्थिति, संबंध और उद्देश्य के अनुसार भाषा का उपयुक्त प्रयोग करना। उसका व्याकरण ठीक है; समस्या औचित्य की है।"},
  {"id":"cdp-pedagogy-subjects-539","question":"A Class 6 learner who does not know the word ‘ladle’ tells her partner, ‘You know, the big spoon with a long handle for serving dal.’ This shows her:","options":["Grammatical competence","Strategic competence","Discourse competence","Sociolinguistic competence"],"answer":1,"explanation":"Strategic competence covers the strategies, such as paraphrase and circumlocution, that learners use to keep communication going when their language falls short.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 6 की एक शिक्षार्थी, जिसे ‘ladle’ शब्द नहीं आता, अपनी साथी से कहती है, ‘You know, the big spoon with a long handle for serving dal.’ यह उसकी किस सक्षमता को दर्शाता है?","optionsHi":["व्याकरणिक सक्षमता","रणनीतिक सक्षमता","प्रवचन सक्षमता","सामाजिक-भाषाई सक्षमता"],"explanationHi":"रणनीतिक सक्षमता में वे युक्तियाँ आती हैं, जैसे अन्य शब्दों में कहना और घुमा-फिराकर कहना, जिनका प्रयोग शिक्षार्थी भाषा कम पड़ने पर संप्रेषण जारी रखने के लिए करते हैं।"},
  {"id":"cdp-pedagogy-subjects-540","question":"A Class 9 student’s essay has correct sentences, yet the ideas do not connect: there are no linking words, ‘it’ and ‘they’ refer to unclear things, and paragraphs jump between points. In communicative-competence terms the student mainly needs to develop:","options":["Strategic competence: ways to repair breakdowns in talk","Grammatical competence: accuracy in forming sentences","Discourse competence: cohesion and coherence across sentences","Sociolinguistic competence: matching style and register to the reader"],"answer":2,"explanation":"Discourse competence is the ability to combine sentences into a unified, connected text through cohesive devices and logical organisation. Each of his sentences is already accurate.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 9 के एक विद्यार्थी के निबंध में वाक्य सही हैं, फिर भी विचार आपस में नहीं जुड़ते: जोड़ने वाले शब्द नहीं हैं, ‘it’ और ‘they’ अस्पष्ट वस्तुओं की ओर संकेत करते हैं, और अनुच्छेद एक बिंदु से दूसरे पर कूद जाते हैं। संप्रेषणात्मक सक्षमता की दृष्टि से विद्यार्थी को मुख्यतः किसे विकसित करने की आवश्यकता है?","optionsHi":["रणनीतिक सक्षमता: बातचीत में आई रुकावटों को सुधारने के तरीके","व्याकरणिक सक्षमता: वाक्य बनाने में शुद्धता","प्रवचन सक्षमता: वाक्यों के बीच संसक्ति और सुसंगति","सामाजिक-भाषाई सक्षमता: पाठक के अनुरूप शैली और प्रयुक्ति का मेल"],"explanationHi":"प्रवचन सक्षमता वाक्यों को संसक्ति साधनों और तार्किक संगठन के द्वारा एक एकीकृत, जुड़े हुए पाठ में मिलाने की योग्यता है। उसका प्रत्येक वाक्य पहले से शुद्ध है।"},
  {"id":"cdp-pedagogy-subjects-541","question":"During a group discussion meant to build fluency, a teacher hears many grammatical errors. In communicative language teaching, her best course of action is to:","options":["Stop each group whenever an error occurs and have the speaker repeat it correctly","Note the common errors quietly and deal with them after the activity is over","Allow students to continue only if they can speak in complete, correct sentences","Award marks for grammar during the discussion so that students take more care"],"answer":1,"explanation":"Fluency activities aim at keeping communication going; interrupting shifts attention to form and raises anxiety. Delayed feedback on recurring errors keeps both fluency and accuracy in view.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"प्रवाह विकसित करने के उद्देश्य से हो रही समूह चर्चा के दौरान एक शिक्षिका को अनेक व्याकरणिक त्रुटियाँ सुनाई देती हैं। संप्रेषणात्मक भाषा शिक्षण में उसकी सबसे अच्छी कार्रवाई है:","optionsHi":["त्रुटि होते ही हर समूह को रोकना और वक्ता से उसे सही ढंग से दोहरवाना","सामान्य त्रुटियों को चुपचाप नोट करना और गतिविधि समाप्त होने के बाद उन्हें सुधारना","विद्यार्थियों को तभी आगे बोलने देना जब वे पूर्ण, शुद्ध वाक्यों में बोल सकें","चर्चा के दौरान व्याकरण के अंक देना ताकि विद्यार्थी अधिक सावधानी बरतें"],"explanationHi":"प्रवाह की गतिविधियों का लक्ष्य संप्रेषण को चलते रहने देना है; टोकने से ध्यान रूप की ओर चला जाता है और चिंता बढ़ती है। बार-बार होने वाली त्रुटियों पर विलंबित प्रतिपुष्टि प्रवाह और शुद्धता दोनों को ध्यान में रखती है।"},
  {"id":"cdp-pedagogy-subjects-542","question":"A Class 4 teacher uses TPR for classroom commands, a short pattern drill to practise ‘Can you…?’, and role plays at a vegetable stall, choosing each according to the aim of the lesson. The best description of her practice is:","options":["Principled eclecticism: choosing techniques from several methods to suit learners and aims","A confused mixture of methods that will leave children unsure of what is expected of them","Essentially the audio-lingual method, since a pattern drill for ‘Can you…?’ appears in the lesson","Essentially grammar-translation, since a particular structure is being practised"],"answer":0,"explanation":"Eclecticism is principled when techniques are selected because they serve specific learning aims and learners. One drill does not turn a lesson into the audio-lingual method.","difficulty":"moderate","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कक्षा 4 की एक शिक्षिका कक्षा के आदेशों के लिए TPR, ‘Can you…?’ के अभ्यास के लिए एक छोटा प्रतिरूप अभ्यास, और सब्ज़ी की दुकान पर भूमिका-अभिनय का प्रयोग करती है, प्रत्येक को पाठ के उद्देश्य के अनुसार चुनती है। उसके अभ्यास का सबसे अच्छा वर्णन है:","optionsHi":["सैद्धांतिक चयनवाद: शिक्षार्थियों और उद्देश्यों के अनुरूप अनेक विधियों से तकनीकें चुनना","विधियों का भ्रमित मिश्रण, जिससे बच्चे अनिश्चित रहेंगे कि उनसे क्या अपेक्षित है","मूलतः श्रव्य-भाषिक विधि, क्योंकि पाठ में ‘Can you…?’ का प्रतिरूप अभ्यास आता है","मूलतः व्याकरण-अनुवाद, क्योंकि एक विशेष संरचना का अभ्यास कराया जा रहा है"],"explanationHi":"चयनवाद तब सैद्धांतिक होता है जब तकनीकें इसलिए चुनी जाती हैं कि वे विशिष्ट अधिगम उद्देश्यों और शिक्षार्थियों के काम आती हैं। एक अभ्यास किसी पाठ को श्रव्य-भाषिक विधि नहीं बना देता।"},
  {"id":"cdp-pedagogy-subjects-543","question":"A teacher in a rural Chhattisgarh school with 60 children and few resources finds that no textbook method fits her class. She studies her learners, tries strategies, reflects on what works, and builds her own approach guided by aims such as maximising learning opportunities and promoting learner autonomy. Her stance is closest to:","options":["The audio-lingual method, which offers one fixed set of procedures that works for any class","The natural approach, which prescribes a silent period followed by early production in speech","Grammar-translation, which suits large classes because it needs little oral interaction","Kumaravadivelu’s post-method pedagogy, based on particularity, practicality and possibility"],"answer":3,"explanation":"Post-method pedagogy rejects the search for one best method and asks teachers to theorise from practice, using macro-strategies sensitive to their particular context.","difficulty":"very-hard","source":"KVS TGT · DSSSB · CTET Paper II","questionHi":"छत्तीसगढ़ के एक ग्रामीण विद्यालय की एक शिक्षिका, जिसकी कक्षा में 60 बच्चे हैं और संसाधन कम हैं, पाती है कि कोई पाठ्यपुस्तकीय विधि उसकी कक्षा पर फिट नहीं बैठती। वह अपने शिक्षार्थियों का अध्ययन करती है, रणनीतियाँ आज़माती है, चिंतन करती है कि क्या कारगर है, और अधिकतम अधिगम अवसर तथा शिक्षार्थी स्वायत्तता को बढ़ावा देने जैसे उद्देश्यों से निर्देशित होकर अपना उपागम बनाती है। उसका रुख किसके सबसे निकट है?","optionsHi":["श्रव्य-भाषिक विधि, जो एक निश्चित प्रक्रिया-समूह देती है जो किसी भी कक्षा में काम करता है","प्राकृतिक उपागम, जो मौन अवधि के बाद वाणी में शीघ्र उत्पादन निर्धारित करता है","व्याकरण-अनुवाद, जो बड़ी कक्षाओं के अनुकूल है क्योंकि इसमें मौखिक अंतःक्रिया कम चाहिए","कुमारवडिवेलु की उत्तर-विधि शिक्षणशास्त्र, जो विशिष्टता, व्यावहारिकता और संभाव्यता पर आधारित है"],"explanationHi":"उत्तर-विधि शिक्षणशास्त्र एकमात्र सर्वश्रेष्ठ विधि की खोज को अस्वीकार करता है और शिक्षकों से अपेक्षा करता है कि वे अभ्यास से सिद्धांत गढ़ें, अपने विशिष्ट संदर्भ के प्रति संवेदनशील व्यापक रणनीतियों का प्रयोग करते हुए।"},
  {"id":"cdp-pedagogy-subjects-544","question":"A teacher stops her class in the middle of a drill to correct each error at once and insists on perfect repetition, saying, ‘If a wrong form is repeated, it becomes a habit.’ Her view of errors reflects:","options":["Communicative language teaching","The audio-lingual method","The natural approach","The whole language approach"],"answer":1,"explanation":"In the behaviourist audio-lingual method, errors are bad habits to be prevented and corrected immediately. The other approaches see errors as a natural, informative part of development.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"एक शिक्षिका अभ्यास के बीच में कक्षा को रोककर हर त्रुटि को तुरंत सुधारती है और पूर्ण शुद्ध दोहराव पर ज़ोर देती है, यह कहते हुए, ‘गलत रूप दोहराया गया तो वह आदत बन जाएगा।’ त्रुटियों के बारे में उसका दृष्टिकोण किसे दर्शाता है?","optionsHi":["संप्रेषणात्मक भाषा शिक्षण","श्रव्य-भाषिक विधि","प्राकृतिक उपागम","समग्र भाषा उपागम"],"explanationHi":"व्यवहारवादी श्रव्य-भाषिक विधि में त्रुटियाँ बुरी आदतें हैं जिन्हें रोका और तुरंत सुधारा जाना चाहिए। अन्य उपागम त्रुटियों को विकास का स्वाभाविक, सूचनाप्रद अंग मानते हैं।"},
  {"id":"cdp-pedagogy-subjects-545","question":"Assertion (A): In the whole language approach, children must master all the letter–sound correspondences before they are given real books. Reason (R): The whole language approach moves from the parts of language to the whole.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","Both A and R are false"],"answer":3,"explanation":"Whole language moves from whole to part: children meet real, meaningful texts from the start, and sound–letter work is embedded in them. Both statements describe a bottom-up view, not whole language.","difficulty":"very-hard","source":"CTET Paper I · State TETs","questionHi":"अभिकथन (A): समग्र भाषा उपागम में बच्चों को वास्तविक पुस्तकें देने से पहले उन्हें सभी अक्षर-ध्वनि संबंधों में निपुण होना चाहिए। कारण (R): समग्र भाषा उपागम भाषा के अंशों से संपूर्ण की ओर बढ़ता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A और R दोनों असत्य हैं"],"explanationHi":"समग्र भाषा संपूर्ण से अंश की ओर चलती है: बच्चे आरंभ से ही वास्तविक, अर्थपूर्ण पाठों से मिलते हैं, और ध्वनि–अक्षर कार्य उन्हीं में समाया होता है। दोनों कथन निम्न-से-उच्च (बॉटम-अप) दृष्टि का वर्णन करते हैं, समग्र भाषा का नहीं।"},
  {"id":"cdp-pedagogy-subjects-546","question":"After a class visit to a dairy, Class 2 children tell the teacher what they saw, she writes their own sentences on chart paper, and the chart becomes their reading text for the week. This is the:","options":["Language experience approach, using the children’s own words as text","Look-and-say method, since words on the chart are learnt as wholes","Grammar-translation method, since speech is converted into writing","Phonics approach, since the chart is mainly used to practise letter sounds"],"answer":0,"explanation":"The language experience approach turns children’s shared experiences and their own language into reading material, so texts are meaningful and predictable for them.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"एक डेयरी की कक्षा-भ्रमण के बाद कक्षा 2 के बच्चे शिक्षिका को बताते हैं कि उन्होंने क्या देखा, वह उनके अपने वाक्य चार्ट पेपर पर लिखती है, और वह चार्ट सप्ताह भर के लिए उनका पठन-पाठ बन जाता है। यह है:","optionsHi":["भाषा अनुभव उपागम, जो बच्चों के अपने शब्दों को पाठ के रूप में प्रयोग करता है","देखो और बोलो विधि, क्योंकि चार्ट के शब्द संपूर्ण रूप में सीखे जाते हैं","व्याकरण-अनुवाद विधि, क्योंकि वाणी को लेखन में बदला जाता है","ध्वनि-विज्ञान उपागम (फोनिक्स), क्योंकि चार्ट का उपयोग मुख्यतः अक्षर-ध्वनियों के अभ्यास के लिए होता है"],"explanationHi":"भाषा अनुभव उपागम बच्चों के साझा अनुभवों और उनकी अपनी भाषा को पठन-सामग्री में बदल देता है, इसलिए पाठ उनके लिए अर्थपूर्ण और पूर्वानुमेय होते हैं।"},
  {"id":"cdp-pedagogy-subjects-547","question":"A Class 1 teacher teaches reading only through flash cards of whole words with pictures (‘bus’, ‘cow’, ‘tree’), which children learn to recognise by shape. If this is the only method used, the main problem is likely to be that children:","options":["Cannot learn any sight words at all through flash cards","Will learn too many letter sounds too early to manage","Will be unable to work out unfamiliar words on their own","Will lose interest, since pictures make reading too easy"],"answer":2,"explanation":"The look-and-say method builds a sight vocabulary quickly, but without sound–letter knowledge children have no strategy for new words, which is why it is combined with phonics.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 1 की एक शिक्षिका पठन केवल चित्रों वाले संपूर्ण शब्दों (‘bus’, ‘cow’, ‘tree’) के फ्लैश कार्ड से सिखाती है, जिन्हें बच्चे आकृति से पहचानना सीखते हैं। यदि केवल यही विधि अपनाई जाए, तो मुख्य समस्या संभवतः यह होगी कि बच्चे:","optionsHi":["फ्लैश कार्ड से कोई भी दृश्य शब्द बिल्कुल नहीं सीख सकेंगे","बहुत जल्दी बहुत अधिक अक्षर-ध्वनियाँ सीख लेंगे जिन्हें सँभालना कठिन होगा","अपरिचित शब्दों को स्वयं पढ़ने में असमर्थ रहेंगे","रुचि खो देंगे, क्योंकि चित्र पठन को बहुत आसान बना देते हैं"],"explanationHi":"देखो और बोलो विधि दृश्य शब्दावली शीघ्र बनाती है, पर ध्वनि–अक्षर ज्ञान के बिना बच्चों के पास नए शब्दों के लिए कोई युक्ति नहीं होती, इसीलिए इसे फोनिक्स के साथ मिलाया जाता है।"},
  {"id":"cdp-pedagogy-subjects-548","question":"Which of the following is a ‘task’ in the sense used in task-based language teaching?","options":["Pairs read a passage on railways and translate it, line by line, into their home language","Pairs fill in the blanks in ten sentences about the station with the correct prepositions of place","Pairs repeat the sentence ‘The station is near the school’ until they can say it fluently","Pairs use a town map to agree on the shortest route from school to the station and present it"],"answer":3,"explanation":"A task has a primary focus on meaning, a gap to close, learners using their own resources, and a clear non-linguistic outcome. The others are form-focused exercises.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कार्य-आधारित भाषा शिक्षण के अर्थ में निम्नलिखित में से कौन-सा एक ‘कार्य’ है?","optionsHi":["जोड़े रेलवे पर एक गद्यांश पढ़ते हैं और पंक्ति-दर-पंक्ति उसका अपनी घर की भाषा में अनुवाद करते हैं","जोड़े स्टेशन के बारे में दस वाक्यों में स्थान-बोधक संबंधबोधकों से रिक्त स्थान भरते हैं","जोड़े वाक्य ‘The station is near the school’ को तब तक दोहराते हैं जब तक वे उसे धाराप्रवाह न बोल सकें","जोड़े नगर के मानचित्र का उपयोग करके विद्यालय से स्टेशन तक सबसे छोटे मार्ग पर सहमत होते हैं और उसे प्रस्तुत करते हैं"],"explanationHi":"कार्य में अर्थ पर मुख्य ध्यान, भरने के लिए एक अंतराल, शिक्षार्थियों द्वारा अपने संसाधनों का उपयोग, और एक स्पष्ट गैर-भाषाई परिणाम होता है। अन्य रूप-केंद्रित अभ्यास हैं।"},
  {"id":"cdp-pedagogy-subjects-549","question":"A Kolkata teacher brings a real railway timetable, a restaurant menu and a newspaper weather report to her Class 7 English class. Which reason best justifies the use of such materials?","options":["They are strictly graded by grammar, so each one teaches one structure","They show language as it is actually used for real purposes in daily life","They should replace the textbook altogether, since textbooks are never authentic","They are easier for learners than the textbook, so they reduce effort"],"answer":1,"explanation":"Authentic materials expose learners to real language for real purposes, increase motivation and help transfer to life outside school. They are not graded by structure and supplement, rather than replace, the textbook.","difficulty":"moderate","source":"CTET Paper II · State TETs","questionHi":"कोलकाता की एक शिक्षिका अपनी कक्षा 7 की अंग्रेज़ी कक्षा में असली रेलवे समय-सारणी, रेस्तराँ का मेन्यू और अखबार की मौसम रिपोर्ट लाती है। ऐसी सामग्री के प्रयोग को कौन-सा कारण सबसे अच्छी तरह उचित ठहराता है?","optionsHi":["वे व्याकरण के अनुसार कठोरता से श्रेणीबद्ध हैं, इसलिए प्रत्येक एक संरचना सिखाती है","वे दिखाती हैं कि भाषा वास्तव में दैनिक जीवन में वास्तविक उद्देश्यों के लिए कैसे प्रयुक्त होती है","उन्हें पाठ्यपुस्तक का पूरी तरह स्थान ले लेना चाहिए, क्योंकि पाठ्यपुस्तकें कभी प्रामाणिक नहीं होतीं","वे शिक्षार्थियों के लिए पाठ्यपुस्तक से आसान हैं, इसलिए प्रयास कम करती हैं"],"explanationHi":"प्रामाणिक सामग्री शिक्षार्थियों को वास्तविक उद्देश्यों के लिए वास्तविक भाषा से परिचित कराती है, अभिप्रेरणा बढ़ाती है और विद्यालय के बाहर के जीवन में स्थानांतरण में मदद करती है। वे संरचना के अनुसार श्रेणीबद्ध नहीं होतीं और पाठ्यपुस्तक की पूरक होती हैं, उसका स्थान नहीं लेतीं।"},
  {"id":"cdp-pedagogy-subjects-550","question":"A Class VII teacher asks students to sort these materials for studying the Delhi Sultanate:\n1. Ibn Battuta's account of his travels in 14th-century India\n2. A book on the Sultanate written by a historian in the 1990s\n3. Silver coins issued by Alauddin Khalji\n4. A documentary on the Sultanate made in 2010\nWhich of them are primary sources?","options":["1 and 2 only","3 and 4 only","1 and 3 only","1, 3 and 4 only"],"answer":2,"explanation":"Primary sources come from the period being studied: a contemporary traveller's account and the coins of the time. A modern historian's book and a recent documentary interpret the past from a later vantage point, so they are secondary.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VII का एक शिक्षक विद्यार्थियों से दिल्ली सल्तनत के अध्ययन के लिए इन सामग्रियों को छाँटने को कहता है:\n1. इब्न बतूता का 14वीं शताब्दी के भारत की यात्राओं का वृत्तांत\n2. 1990 के दशक में एक इतिहासकार द्वारा सल्तनत पर लिखी गई पुस्तक\n3. अलाउद्दीन खिलजी द्वारा जारी चाँदी के सिक्के\n4. 2010 में बनी सल्तनत पर एक वृत्तचित्र\nइनमें से कौन-से प्राथमिक स्रोत हैं?","optionsHi":["केवल 1 और 2","केवल 3 और 4","केवल 1 और 3","केवल 1, 3 और 4"],"explanationHi":"प्राथमिक स्रोत अध्ययन किए जा रहे काल के ही होते हैं: समकालीन यात्री का वृत्तांत और उस समय के सिक्के। आधुनिक इतिहासकार की पुस्तक और हाल का वृत्तचित्र बाद के दृष्टिकोण से अतीत की व्याख्या करते हैं, इसलिए वे द्वितीयक हैं।"},
  {"id":"cdp-pedagogy-subjects-551","question":"A Class VII student says, 'The Akbarnama was written by Akbar's own courtier, so it must be a perfect and unbiased account of his reign.' What is the best response?","options":["Agree, because a primary source written by an eyewitness at court is always objective and complete in detail","Disagree, and tell the class that court chronicles are propaganda and should not be used at all","Note that it is valuable, but was written to praise the emperor, so its claims must be cross-checked","Tell the student to rely only on the textbook, since it has already removed all bias from sources"],"answer":2,"explanation":"Being close to events makes a source valuable, not neutral. Court chronicles reflect the patron's view, so historians ask who wrote them, why and for whom, and they cross-check. Rejecting such sources is as mistaken as trusting them blindly.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा VII का एक विद्यार्थी कहता है, ‘अकबरनामा अकबर के अपने दरबारी ने लिखा था, इसलिए यह उसके शासनकाल का पूर्ण और निष्पक्ष वृत्तांत होगा।’ सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["सहमत होना, क्योंकि दरबार में प्रत्यक्षदर्शी द्वारा लिखा गया प्राथमिक स्रोत सदैव वस्तुनिष्ठ और विवरण में पूर्ण होता है","असहमत होना, और कक्षा को बताना कि दरबारी इतिवृत्त प्रचार हैं और उनका बिल्कुल प्रयोग नहीं करना चाहिए","यह नोट करना कि यह मूल्यवान है, पर सम्राट की प्रशंसा के लिए लिखा गया था, इसलिए इसके दावों की क्रॉस-जाँच होनी चाहिए","विद्यार्थी से कहना कि केवल पाठ्यपुस्तक पर निर्भर रहे, क्योंकि उसने स्रोतों का सारा पक्षपात पहले ही हटा दिया है"],"explanationHi":"घटनाओं के निकट होना किसी स्रोत को मूल्यवान बनाता है, तटस्थ नहीं। दरबारी इतिवृत्त संरक्षक का दृष्टिकोण दर्शाते हैं, इसलिए इतिहासकार पूछते हैं कि इन्हें किसने, क्यों और किसके लिए लिखा, और वे क्रॉस-जाँच करते हैं। ऐसे स्रोतों को ठुकराना उन पर आँख मूँदकर भरोसा करने जितना ही गलत है।"},
  {"id":"cdp-pedagogy-subjects-552","question":"Students reading an extract from an indigo cultivator's petition are asked: 'Who wrote this? When? To whom? What did the writer want?' These questions mainly build the skill of:","options":["memorising key dates and events of the colonial period","summarising a text in fewer words","translating old documents into modern everyday language","evaluating a source's origin, purpose and reliability"],"answer":3,"explanation":"Questions about author, date, audience and intention are the core of source criticism, sometimes called 'sourcing'. They help students judge what a document can and cannot tell us.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"नील की खेती करने वाले किसान की याचिका का एक अंश पढ़ रहे विद्यार्थियों से पूछा जाता है: ‘इसे किसने लिखा? कब? किसे? लेखक क्या चाहता था?’ ये प्रश्न मुख्यतः किस कौशल का निर्माण करते हैं?","optionsHi":["औपनिवेशिक काल की प्रमुख तिथियों और घटनाओं को याद करना","किसी पाठ को कम शब्दों में सारांशित करना","पुराने दस्तावेज़ों का आधुनिक रोज़मर्रा की भाषा में अनुवाद करना","किसी स्रोत की उत्पत्ति, उद्देश्य और विश्वसनीयता का मूल्यांकन करना"],"explanationHi":"लेखक, तिथि, श्रोता और मंतव्य के बारे में प्रश्न स्रोत-आलोचना के केंद्र में हैं, जिसे कभी-कभी ‘सोर्सिंग’ कहा जाता है। वे विद्यार्थियों को यह आँकने में मदद करते हैं कि कोई दस्तावेज़ हमें क्या बता सकता है और क्या नहीं।"},
  {"id":"cdp-pedagogy-subjects-553","question":"Assertion (A): A newspaper printed in August 1947 is a primary source for studying Partition.\nReason (R): Primary sources are materials produced at or near the time of the events, by people who took part in or observed them.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A newspaper of that month was produced while the events were unfolding, which is exactly what makes it primary under R's definition. R therefore explains A.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"अभिकथन (A): अगस्त 1947 में छपा अखबार विभाजन के अध्ययन के लिए प्राथमिक स्रोत है।\nकारण (R): प्राथमिक स्रोत वे सामग्रियाँ हैं जो घटनाओं के समय या उनके निकट, उनमें भाग लेने या उन्हें देखने वाले लोगों द्वारा निर्मित हुईं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"उस महीने का अखबार तब बना जब घटनाएँ घट रही थीं, और यही R की परिभाषा के अनुसार उसे प्राथमिक बनाता है। इसलिए R, A की व्याख्या करता है।"},
  {"id":"cdp-pedagogy-subjects-554","question":"An NCERT history textbook printed in 1975 is a secondary source for the Mughal period. A researcher, however, uses it as a primary source. Which research question would justify this?","options":["How was the Mughal revenue system organised under Akbar's rule?","How was Indian history presented to school students in the 1970s?","What did foreign travellers write about Mughal cities and markets?","Which coins did Shah Jahan issue, and in what metals?"],"answer":1,"explanation":"Whether a source is primary or secondary depends on the question being asked. For the Mughals the 1975 book is a later interpretation, but for the history of school education in the 1970s it is itself evidence from that time.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"1975 में छपी NCERT की इतिहास की पाठ्यपुस्तक मुग़ल काल के लिए द्वितीयक स्रोत है। फिर भी एक शोधकर्ता उसे प्राथमिक स्रोत के रूप में प्रयोग करता है। कौन-सा शोध प्रश्न इसे उचित ठहराएगा?","optionsHi":["अकबर के शासन में मुग़ल राजस्व प्रणाली कैसे संगठित थी?","1970 के दशक में विद्यालय के विद्यार्थियों के सामने भारतीय इतिहास कैसे प्रस्तुत किया जाता था?","विदेशी यात्रियों ने मुग़ल नगरों और बाज़ारों के बारे में क्या लिखा?","शाहजहाँ ने कौन-से सिक्के जारी किए, और किन धातुओं में?"],"explanationHi":"कोई स्रोत प्राथमिक है या द्वितीयक, यह पूछे जा रहे प्रश्न पर निर्भर करता है। मुग़लों के लिए 1975 की पुस्तक बाद की व्याख्या है, पर 1970 के दशक में विद्यालयी शिक्षा के इतिहास के लिए वह स्वयं उस समय का साक्ष्य है।"},
  {"id":"cdp-pedagogy-subjects-555","question":"Which sequence is the most suitable for developing map skills from Class III to Class VI?","options":["World map → map of India → map of the state → sketch of the classroom","Globe → physical map of the world → atlas reading → map of the village","Route from home to school → school plan → village map → maps of state and country","Political map of India → physical map of India → thematic maps → sketch of the neighbourhood"],"answer":2,"explanation":"Map skills grow from children's own space, from a sketch of a known route to a plan drawn to scale and then to maps of larger and more distant areas. Starting with the world map reverses the 'known to unknown' order.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा III से कक्षा VI तक मानचित्र कौशल विकसित करने के लिए कौन-सा क्रम सबसे उपयुक्त है?","optionsHi":["विश्व मानचित्र → भारत का मानचित्र → राज्य का मानचित्र → कक्षा का रेखाचित्र","ग्लोब → विश्व का भौतिक मानचित्र → एटलस पढ़ना → गाँव का मानचित्र","घर से विद्यालय का मार्ग → विद्यालय की योजना → गाँव का मानचित्र → राज्य और देश के मानचित्र","भारत का राजनीतिक मानचित्र → भारत का भौतिक मानचित्र → विषयगत मानचित्र → पड़ोस का रेखाचित्र"],"explanationHi":"मानचित्र कौशल बच्चों के अपने स्थान से बढ़ते हैं, ज्ञात मार्ग के रेखाचित्र से पैमाने पर बनी योजना तक और फिर बड़े और दूर के क्षेत्रों के मानचित्रों तक। विश्व मानचित्र से शुरू करना ‘ज्ञात से अज्ञात’ का क्रम उलट देता है।"},
  {"id":"cdp-pedagogy-subjects-556","question":"A Class VI student measures her classroom and draws its layout using 1 cm on paper for 1 m on the floor, marking the desks and the door. What has she drawn?","options":["A sketch, because it is drawn freehand by the student","A map, because it shows the positions of objects","A globe projection, because it is drawn to a scale","A plan, because it shows a small area drawn to scale"],"answer":3,"explanation":"A plan is a drawing of a small area to scale. A sketch is not drawn to scale, even if neat, and a map normally covers a larger area. Being hand-drawn does not decide the category; using a scale does.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"कक्षा VI की एक विद्यार्थी अपनी कक्षा को नापती है और फर्श के 1 m के लिए कागज़ पर 1 cm लेकर उसका नक्शा खींचती है, जिसमें डेस्क और दरवाज़ा दिखाए गए हैं। उसने क्या बनाया है?","optionsHi":["रेखाचित्र (स्केच), क्योंकि इसे विद्यार्थी ने हाथ से बनाया है","मानचित्र, क्योंकि यह वस्तुओं की स्थितियाँ दर्शाता है","ग्लोब प्रक्षेप, क्योंकि यह पैमाने पर बना है","योजना (प्लान), क्योंकि यह पैमाने पर बने एक छोटे क्षेत्र को दर्शाती है"],"explanationHi":"योजना किसी छोटे क्षेत्र का पैमाने पर बना चित्र होती है। रेखाचित्र पैमाने पर नहीं बनता, भले ही साफ-सुथरा हो, और मानचित्र सामान्यतः बड़े क्षेत्र को दर्शाता है। हाथ से बना होना श्रेणी तय नहीं करता; पैमाने का प्रयोग करना तय करता है।"},
  {"id":"cdp-pedagogy-subjects-557","question":"A teacher wants Class VI students in a Himachal village to locate their houses, the village well and the temple on a map. Which kind of map should she use?","options":["A large-scale map, which shows a small area in great detail","A small-scale map, which shows a small area in great detail","A small-scale map, because larger areas give more detail","A physical map of India, because it shows relief"],"answer":0,"explanation":"Large-scale maps (for example 1:5,000) show small areas with much detail; small-scale maps show large areas with little detail. The common trap is to think 'large scale' means 'large area'.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"एक शिक्षिका चाहती है कि हिमाचल के एक गाँव के कक्षा VI के विद्यार्थी मानचित्र पर अपने घर, गाँव का कुआँ और मंदिर ढूँढ़ें। उसे किस प्रकार का मानचित्र प्रयोग करना चाहिए?","optionsHi":["बड़े पैमाने का मानचित्र, जो छोटे क्षेत्र को बहुत विस्तार से दर्शाता है","छोटे पैमाने का मानचित्र, जो छोटे क्षेत्र को बहुत विस्तार से दर्शाता है","छोटे पैमाने का मानचित्र, क्योंकि बड़े क्षेत्र अधिक विवरण देते हैं","भारत का भौतिक मानचित्र, क्योंकि यह उच्चावच दर्शाता है"],"explanationHi":"बड़े पैमाने के मानचित्र (उदाहरण के लिए 1:5,000) छोटे क्षेत्रों को बहुत विवरण के साथ दर्शाते हैं; छोटे पैमाने के मानचित्र बड़े क्षेत्रों को कम विवरण के साथ दर्शाते हैं। आम भूल यह सोचना है कि ‘बड़ा पैमाना’ का अर्थ ‘बड़ा क्षेत्र’ है।"},
  {"id":"cdp-pedagogy-subjects-558","question":"Many Class VI students in a Lucknow school believe that 'north' means 'the top of the wall' or 'up the stairs'. Which activity best corrects this misconception?","options":["Ask them to memorise the rule that north is always at the top of every map they will ever use","Take them outdoors with a compass, find north, and turn the map to match the real directions","Show them the north arrow on a wall map and ask them to copy it into their notebooks","Tell them that directions do not really matter for reading a map correctly"],"answer":1,"explanation":"Directions are real orientations on the ground, not positions on a page. Finding north outdoors and orienting a map to it builds the concept, whereas 'north is at the top' merely restates the misconception in map form.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT","questionHi":"लखनऊ के एक विद्यालय के कक्षा VI के अनेक विद्यार्थी मानते हैं कि ‘उत्तर’ का अर्थ ‘दीवार का ऊपरी भाग’ या ‘सीढ़ियों के ऊपर’ है। इस भ्रांति को कौन-सी गतिविधि सबसे अच्छी तरह सुधारती है?","optionsHi":["उनसे नियम रटवाना कि उत्तर हमेशा हर उस मानचित्र के ऊपर होता है जिसका वे कभी प्रयोग करेंगे","उन्हें दिशासूचक यंत्र के साथ बाहर ले जाना, उत्तर ढूँढ़ना, और मानचित्र को वास्तविक दिशाओं के अनुसार घुमाना","उन्हें दीवार के मानचित्र पर उत्तर-संकेत तीर दिखाना और अपनी कॉपियों में उसे उतारने को कहना","उन्हें बताना कि मानचित्र को सही ढंग से पढ़ने के लिए दिशाएँ वास्तव में मायने नहीं रखतीं"],"explanationHi":"दिशाएँ ज़मीन पर वास्तविक अभिविन्यास हैं, पन्ने पर स्थितियाँ नहीं। बाहर उत्तर ढूँढ़ना और मानचित्र को उसके अनुसार रखना अवधारणा बनाता है, जबकि ‘उत्तर ऊपर होता है’ भ्रांति को ही मानचित्र के रूप में दोहराता है।"},
  {"id":"cdp-pedagogy-subjects-559","question":"Looking at a wall map of the world, a Class VII student asks why Greenland looks almost as big as Africa. What is the most appropriate response?","options":["Explain that Greenland really is about the size of Africa, so the map shows it correctly","Explain that the map printer made a mistake and that the map should be replaced","Tell the student that the size of countries is not an important matter in geography lessons","Compare them on a globe: flat maps distort size, especially far from the equator"],"answer":3,"explanation":"Every flat map distorts something. Projections such as Mercator's enlarge areas far from the equator, which makes Greenland look huge though it is much smaller than Africa. The globe shows true relative size.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"विश्व का दीवार मानचित्र देखते हुए कक्षा VII का एक विद्यार्थी पूछता है कि ग्रीनलैंड लगभग अफ्रीका जितना बड़ा क्यों दिखता है। सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["समझाना कि ग्रीनलैंड वास्तव में अफ्रीका जितना ही बड़ा है, इसलिए मानचित्र उसे सही दिखाता है","समझाना कि मानचित्र छापने वाले से गलती हुई है और मानचित्र बदल देना चाहिए","विद्यार्थी को बताना कि भूगोल के पाठों में देशों का आकार कोई महत्त्वपूर्ण विषय नहीं है","ग्लोब पर उनकी तुलना करना: समतल मानचित्र आकार को विकृत करते हैं, विशेषकर भूमध्य रेखा से दूर"],"explanationHi":"हर समतल मानचित्र कुछ न कुछ विकृत करता है। मर्केटर जैसे प्रक्षेप भूमध्य रेखा से दूर के क्षेत्रों को बड़ा कर देते हैं, जिससे ग्रीनलैंड विशाल दिखता है जबकि वह अफ्रीका से बहुत छोटा है। ग्लोब वास्तविक सापेक्ष आकार दिखाता है।"},
  {"id":"cdp-pedagogy-subjects-560","question":"A Class VI student insists that 500 BCE came after 200 BCE 'because 500 is a bigger number'. Which is the most effective remedy?","options":["Ask the student to memorise a list of important BCE dates in their correct order","Explain that BCE dates are not very important for understanding history at school level","Tell the student to avoid BCE dates altogether, since they confuse most learners","Use a timeline that counts down to the Common Era and then up, and place both dates"],"answer":3,"explanation":"The error comes from applying ordinary counting to years that run backwards before the Common Era. A visible timeline shows that 500 BCE lies further back, so it happened earlier.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"कक्षा VI का एक विद्यार्थी आग्रह करता है कि 500 ई.पू. 200 ई.पू. के बाद आया ‘क्योंकि 500 बड़ी संख्या है’। सबसे प्रभावी उपचार कौन-सा है?","optionsHi":["विद्यार्थी से महत्त्वपूर्ण ई.पू. तिथियों की सूची उनके सही क्रम में रटवाना","समझाना कि विद्यालय स्तर पर इतिहास समझने के लिए ई.पू. तिथियाँ बहुत महत्त्वपूर्ण नहीं हैं","विद्यार्थी से ई.पू. तिथियों से पूरी तरह बचने को कहना, क्योंकि वे अधिकांश शिक्षार्थियों को भ्रमित करती हैं","ऐसी समय-रेखा का प्रयोग करना जो सामान्य युग तक घटती और फिर बढ़ती गिनती दिखाए, और दोनों तिथियाँ उस पर रखना"],"explanationHi":"त्रुटि उन वर्षों पर सामान्य गिनती लगाने से आती है जो सामान्य युग से पहले उलटी दिशा में चलते हैं। दृश्य समय-रेखा दिखाती है कि 500 ई.पू. और पीछे है, इसलिए वह पहले घटित हुआ।"},
  {"id":"cdp-pedagogy-subjects-561","question":"A Class VIII teacher draws two parallel timelines, one for events in India and one for events in Europe, from 1750 to 1900. What does this mainly help students understand?","options":["That Indian history is less important than European history during this whole period","The exact dates of every battle so that they can be recalled for the test","Simultaneity: what happened in different places at the same time, and how it linked","That timelines should only show political events, such as wars and treaties"],"answer":2,"explanation":"Parallel timelines develop the sense that events in different regions happened together and could influence each other, an important part of chronological thinking beyond sequence alone.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VIII का एक शिक्षक 1750 से 1900 तक दो समानांतर समय-रेखाएँ खींचता है, एक भारत की घटनाओं की और एक यूरोप की। यह मुख्यतः विद्यार्थियों को क्या समझने में मदद करता है?","optionsHi":["कि इस पूरे काल में भारतीय इतिहास यूरोपीय इतिहास से कम महत्त्वपूर्ण है","हर युद्ध की सटीक तिथियाँ, ताकि परीक्षा के लिए याद रखी जा सकें","समकालिकता: अलग-अलग स्थानों पर एक ही समय में क्या हुआ, और वे कैसे जुड़ी थीं","कि समय-रेखाओं में केवल राजनीतिक घटनाएँ, जैसे युद्ध और संधियाँ, ही दिखाई जानी चाहिए"],"explanationHi":"समानांतर समय-रेखाएँ यह बोध विकसित करती हैं कि अलग-अलग क्षेत्रों की घटनाएँ साथ-साथ घटीं और एक-दूसरे को प्रभावित कर सकती थीं, जो केवल क्रम से आगे बढ़कर कालानुक्रमिक चिंतन का महत्त्वपूर्ण अंग है।"},
  {"id":"cdp-pedagogy-subjects-562","question":"A Class VIII student writes, 'The Revolt of 1857 took place in the 18th century.' What is the most likely source of the error, and how can the teacher address it?","options":["The student has misread the date; the teacher should make her write ‘1857’ correctly ten times","The student reads ‘18’ as the century; a timeline of centuries shows the 1800s are the 19th","The student does not know about 1857; the teacher should retell the full story of the revolt","The student is right, since 1857 begins with 18, so the teacher need only praise the answer"],"answer":1,"explanation":"Children often take '18' in 1857 as the century number. Counting centuries on a timeline from the 1st century onwards shows that the 1800s form the 19th century. The error is about the concept of a century, not about the event.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा VIII की एक विद्यार्थी लिखती है, ‘1857 का विद्रोह 18वीं शताब्दी में हुआ था।’ त्रुटि का सबसे संभावित स्रोत क्या है, और शिक्षक इसे कैसे संबोधित कर सकता है?","optionsHi":["विद्यार्थी ने तिथि गलत पढ़ी है; शिक्षक को उससे ‘1857’ दस बार सही लिखवाना चाहिए","विद्यार्थी ‘18’ को शताब्दी पढ़ती है; शताब्दियों की समय-रेखा दिखाती है कि 1800 के दशक 19वीं शताब्दी हैं","विद्यार्थी को 1857 के बारे में पता नहीं है; शिक्षक को विद्रोह की पूरी कहानी फिर सुनानी चाहिए","विद्यार्थी सही है, क्योंकि 1857 18 से शुरू होता है, इसलिए शिक्षक को केवल उत्तर की प्रशंसा करनी चाहिए"],"explanationHi":"बच्चे अक्सर 1857 के ‘18’ को शताब्दी की संख्या मान लेते हैं। पहली शताब्दी से आगे समय-रेखा पर शताब्दियाँ गिनने से दिखता है कि 1800 के दशक 19वीं शताब्दी बनाते हैं। त्रुटि शताब्दी की अवधारणा के बारे में है, घटना के बारे में नहीं।"},
  {"id":"cdp-pedagogy-subjects-563","question":"A Class VII teacher shows a 12th-century Arab geographer's map of the Indian subcontinent in which south appears at the top, beside a modern map. What is the main purpose?","options":["To prove that old maps are useless and too inaccurate to be used for studying the past","To show that maps reflect the knowledge and conventions of their time, which change","To test whether students can spot which of the two maps is drawn wrongly","To show that north was not discovered until modern times by European sailors"],"answer":1,"explanation":"Maps are historical sources shaped by their makers' knowledge and conventions; placing north at the top is itself a convention. Comparing maps from different periods builds an awareness of how representations change.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VII का एक शिक्षक 12वीं शताब्दी के एक अरब भूगोलवेत्ता द्वारा बनाया गया भारतीय उपमहाद्वीप का मानचित्र, जिसमें दक्षिण दिशा ऊपर है, एक आधुनिक मानचित्र के साथ दिखाता है। इसका मुख्य उद्देश्य क्या है?","optionsHi":["यह सिद्ध करना कि पुराने मानचित्र बेकार हैं और अतीत के अध्ययन में प्रयोग के लिए बहुत अशुद्ध हैं","यह दिखाना कि मानचित्र अपने समय के ज्ञान और परिपाटियों को दर्शाते हैं, जो बदलती रहती हैं","यह परखना कि विद्यार्थी पहचान सकते हैं या नहीं कि दोनों में से कौन-सा मानचित्र गलत बना है","यह दिखाना कि उत्तर दिशा की खोज यूरोपीय नाविकों द्वारा आधुनिक काल तक नहीं हुई थी"],"explanationHi":"मानचित्र ऐतिहासिक स्रोत हैं जो अपने निर्माताओं के ज्ञान और परिपाटियों से आकार लेते हैं; उत्तर को ऊपर रखना स्वयं एक परिपाटी है। अलग-अलग कालों के मानचित्रों की तुलना यह जागरूकता बनाती है कि निरूपण कैसे बदलते हैं।"},
  {"id":"cdp-pedagogy-subjects-564","question":"To teach about early hunter-gatherers, a Class VI teacher shows stone tools and pictures of cave paintings and asks, 'What can these tell us about how these people lived?' This mainly develops the skill of:","options":["making inferences from material evidence where no written records exist","memorising the names and locations of important prehistoric sites in India","drawing and painting in the style of prehistoric cave artists","reading and decoding the scripts used by ancient peoples"],"answer":0,"explanation":"For periods without writing, historians infer ways of life from objects and art. Asking what the evidence reveals builds inference from material remains, the basic method of archaeology.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"आरंभिक शिकारी-संग्राहकों के बारे में पढ़ाने के लिए कक्षा VI का एक शिक्षक पत्थर के औज़ार और गुफा-चित्रों के चित्र दिखाता है और पूछता है, ‘ये हमें इन लोगों के जीवन-यापन के बारे में क्या बता सकते हैं?’ यह मुख्यतः किस कौशल का विकास करता है?","optionsHi":["जहाँ लिखित अभिलेख नहीं हैं वहाँ भौतिक साक्ष्य से अनुमान लगाना","भारत के महत्त्वपूर्ण प्रागैतिहासिक स्थलों के नाम और स्थान याद करना","प्रागैतिहासिक गुफा-चित्रकारों की शैली में चित्र बनाना और रंगना","प्राचीन लोगों द्वारा प्रयुक्त लिपियों को पढ़ना और उनका अर्थ निकालना"],"explanationHi":"जिन कालों में लेखन नहीं था, उनके लिए इतिहासकार वस्तुओं और कला से जीवन-शैली का अनुमान लगाते हैं। यह पूछना कि साक्ष्य क्या प्रकट करता है, भौतिक अवशेषों से अनुमान लगाने का कौशल बनाता है, जो पुरातत्त्व की मूल विधि है।"},
  {"id":"cdp-pedagogy-subjects-565","question":"After reading a prashasti composed by a court poet in praise of a Gupta king, a student concludes that the king never lost a single battle. What should the teacher help the student understand?","options":["That a prashasti is written to praise, so its claims need checking against other evidence","That inscriptions on stone pillars are always accurate, because they are permanent and official","That prashastis are later forgeries and must be ignored when studying the Guptas","That only coins, not inscriptions, are reliable sources for the reigns of ancient kings"],"answer":0,"explanation":"A prashasti is a eulogy whose purpose shapes what it says and leaves out. It is valuable evidence, but its claims must be weighed against other sources. Treating it as fact or as worthless are both errors.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"एक दरबारी कवि द्वारा गुप्त राजा की प्रशंसा में रची गई प्रशस्ति पढ़ने के बाद एक विद्यार्थी निष्कर्ष निकालता है कि राजा कभी एक भी युद्ध नहीं हारा। शिक्षक को विद्यार्थी को क्या समझने में मदद करनी चाहिए?","optionsHi":["कि प्रशस्ति प्रशंसा के लिए लिखी जाती है, इसलिए उसके दावों को अन्य साक्ष्यों से जाँचना चाहिए","कि पत्थर के स्तंभों पर लिखे अभिलेख हमेशा सटीक होते हैं, क्योंकि वे स्थायी और आधिकारिक होते हैं","कि प्रशस्तियाँ बाद के जाली दस्तावेज़ हैं और गुप्तों के अध्ययन में उन्हें अनदेखा करना चाहिए","कि प्राचीन राजाओं के शासनकाल के लिए केवल सिक्के ही विश्वसनीय स्रोत हैं, अभिलेख नहीं"],"explanationHi":"प्रशस्ति एक स्तुति-गान है जिसका उद्देश्य तय करता है कि वह क्या कहती है और क्या छोड़ देती है। यह मूल्यवान साक्ष्य है, पर उसके दावों को अन्य स्रोतों के साथ तौलना चाहिए। उसे तथ्य मानना या व्यर्थ मानना, दोनों गलतियाँ हैं।"},
  {"id":"cdp-pedagogy-subjects-566","question":"A Class VIII teacher shows a painting by a British artist that presents an Indian village as calm, picturesque and timeless. Which question should she ask students first, to build critical reading of visual sources?","options":["‘How many colours has the artist used, and which is the brightest?’","‘Is the painting beautiful, and would you hang it at home?’","‘Who painted this, for whom, and what might it leave out?’","‘How much would this painting sell for at an auction today?’"],"answer":2,"explanation":"Like written documents, images carry the viewpoint and purpose of their makers. Asking about creator, audience and omissions reveals the colonial gaze that a purely aesthetic question would miss.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा VIII की एक शिक्षिका एक ब्रिटिश कलाकार का चित्र दिखाती है जो भारतीय गाँव को शांत, मनोरम और कालातीत प्रस्तुत करता है। दृश्य स्रोतों का आलोचनात्मक पठन विकसित करने के लिए उसे विद्यार्थियों से सबसे पहले कौन-सा प्रश्न पूछना चाहिए?","optionsHi":["‘कलाकार ने कितने रंगों का प्रयोग किया है, और कौन-सा सबसे चमकीला है?’","‘क्या चित्र सुंदर है, और क्या तुम इसे घर में लगाओगे?’","‘इसे किसने बनाया, किसके लिए, और यह क्या छोड़ सकता है?’","‘आज नीलामी में यह चित्र कितने में बिकेगा?’"],"explanationHi":"लिखित दस्तावेज़ों की तरह चित्र भी अपने निर्माताओं का दृष्टिकोण और उद्देश्य लिए होते हैं। रचयिता, दर्शकों और छूटी हुई बातों के बारे में पूछना उस औपनिवेशिक दृष्टि को उजागर करता है जिसे केवल सौंदर्यपरक प्रश्न चूक जाता।"},
  {"id":"cdp-pedagogy-subjects-567","question":"Assertion (A): A map drawn to scale shows every feature at its true size.\nReason (R): Scale is the ratio between a distance on the map and the corresponding distance on the ground.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"R correctly defines scale. But a scale reduces sizes; it does not show them at true size. Many features, such as roads, are drawn wider than scale or as symbols, so A is false.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): पैमाने पर बना मानचित्र प्रत्येक विशेषता को उसके वास्तविक आकार में दर्शाता है।\nकारण (R): पैमाना मानचित्र पर की दूरी और ज़मीन पर की संगत दूरी के बीच का अनुपात है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"R पैमाने को सही परिभाषित करता है। परंतु पैमाना आकारों को घटाता है; वह उन्हें वास्तविक आकार में नहीं दिखाता। अनेक विशेषताएँ, जैसे सड़कें, पैमाने से अधिक चौड़ी या प्रतीकों के रूप में बनाई जाती हैं, इसलिए A असत्य है।"},
  {"id":"cdp-pedagogy-subjects-568","question":"When Class IV children in Bhopal draw their neighbourhood from memory, they draw their own house and the sweet shop very large and the bank very small. How should the teacher use these drawings?","options":["Mark them wrong, since the buildings are not drawn to the correct scale","Ignore them, since children of this age are too young to draw real maps","Use them to see how children perceive space, and build the idea of scale from there","Ask the children to trace a printed map of the neighbourhood instead of drawing from memory"],"answer":2,"explanation":"Mental maps show what matters to the child; they are a starting point, not an error to punish. Comparing them with measured distances leads naturally to the idea of scale.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"जब भोपाल की कक्षा IV के बच्चे अपना पड़ोस याद से बनाते हैं, तो वे अपना घर और मिठाई की दुकान बहुत बड़े और बैंक बहुत छोटा बनाते हैं। शिक्षक को इन चित्रों का उपयोग कैसे करना चाहिए?","optionsHi":["उन्हें गलत चिह्नित करना, क्योंकि इमारतें सही पैमाने पर नहीं बनाई गई हैं","उन्हें अनदेखा करना, क्योंकि इस आयु के बच्चे असली मानचित्र बनाने के लिए बहुत छोटे हैं","उनसे यह देखना कि बच्चे स्थान को कैसे अनुभव करते हैं, और वहीं से पैमाने का विचार बनाना","बच्चों से याद से बनाने के बजाय पड़ोस के छपे मानचित्र की अनुरेखित प्रति बनवाना"],"explanationHi":"मानसिक मानचित्र दर्शाते हैं कि बच्चे के लिए क्या मायने रखता है; वे आरंभ-बिंदु हैं, दंडित करने योग्य त्रुटि नहीं। उनकी तुलना नापी हुई दूरियों से करना स्वाभाविक रूप से पैमाने के विचार तक ले जाता है।"},
  {"id":"cdp-pedagogy-subjects-569","question":"Why should students of colonial India be taught to treat official British records with caution?","options":["They were all written in English, a language that most Indians of the time could not read","They are forgeries, made later by British historians to justify colonial rule","They were mostly destroyed in 1857, so only unreliable later copies now remain","They reflect officials' concerns and viewpoint, and may not show how others saw events"],"answer":3,"explanation":"Administrative records are rich sources, but they record what the state wanted to know and how officials understood things. The voices of peasants, workers and women often have to be found elsewhere.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"औपनिवेशिक भारत के विद्यार्थियों को आधिकारिक ब्रिटिश अभिलेखों को सावधानी से लेना क्यों सिखाया जाना चाहिए?","optionsHi":["वे सभी अंग्रेज़ी में लिखे थे, जिसे उस समय के अधिकांश भारतीय पढ़ नहीं सकते थे","वे जाली हैं, जिन्हें बाद में ब्रिटिश इतिहासकारों ने औपनिवेशिक शासन को उचित ठहराने के लिए बनाया","वे अधिकांशतः 1857 में नष्ट हो गए थे, इसलिए अब केवल अविश्वसनीय बाद की प्रतियाँ बची हैं","वे अधिकारियों की चिंताओं और दृष्टिकोण को दर्शाते हैं, और संभव है कि दूसरों ने घटनाओं को कैसे देखा, यह न दिखाएँ"],"explanationHi":"प्रशासनिक अभिलेख समृद्ध स्रोत हैं, पर वे वही दर्ज करते हैं जो राज्य जानना चाहता था और जैसा अधिकारी चीज़ों को समझते थे। किसानों, श्रमिकों और महिलाओं की आवाज़ें अक्सर अन्यत्र ढूँढ़नी पड़ती हैं।"},
  {"id":"cdp-pedagogy-subjects-570","question":"Before teaching historical timelines, a Class VI teacher asks each child to make a timeline of their own life: birth, first day at school, a move to a new house, a sibling's birth. What is the main reason?","options":["To introduce sequence and duration through the child's own familiar past","To collect personal information about the families for the school's records","To fill the time before the actual history chapter begins","To test children's handwriting and their neatness in drawing lines"],"answer":0,"explanation":"Personal timelines build ideas of sequence, intervals and change on familiar ground before students apply them to distant periods, following the 'known to unknown' principle.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"ऐतिहासिक समय-रेखाएँ पढ़ाने से पहले कक्षा VI का एक शिक्षक प्रत्येक बच्चे से अपने जीवन की समय-रेखा बनवाता है: जन्म, विद्यालय का पहला दिन, नए घर में जाना, किसी भाई-बहन का जन्म। इसका मुख्य कारण क्या है?","optionsHi":["बच्चे के अपने परिचित अतीत के माध्यम से क्रम और अवधि का परिचय देना","विद्यालय के अभिलेखों के लिए परिवारों की व्यक्तिगत जानकारी एकत्र करना","वास्तविक इतिहास के अध्याय के शुरू होने से पहले समय भरना","बच्चों की लिखावट और रेखाएँ खींचने में सफाई की परीक्षा लेना"],"explanationHi":"व्यक्तिगत समय-रेखाएँ विद्यार्थियों के दूर के कालों पर इन्हें लागू करने से पहले, परिचित धरातल पर क्रम, अंतराल और परिवर्तन के विचार बनाती हैं, जो ‘ज्ञात से अज्ञात’ के सिद्धांत का पालन है।"},
  {"id":"cdp-pedagogy-subjects-571","question":"Class VII students bring old objects from home, such as a hurricane lantern, an inland letter, a brass lota and an old coin, to set up a class museum. Each object gets a label with what it was used for and what replaced it. What is the main learning?","options":["Learning to arrange and label objects neatly and attractively for a school exhibition","Seeing everyday objects as evidence of change and continuity in daily life","Learning the market value of antiques and how to price old objects","Proving that life in the past was always harder than life today"],"answer":1,"explanation":"Material objects are sources; asking how they were used and what replaced them develops ideas of change and continuity in everyday life. 'Life was harder then' is a judgement the evidence alone does not establish.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VII के विद्यार्थी कक्षा संग्रहालय सजाने के लिए घर से पुरानी वस्तुएँ, जैसे लालटेन, अंतर्देशीय पत्र, पीतल का लोटा और पुराना सिक्का, लाते हैं। प्रत्येक वस्तु पर एक लेबल लगता है जिसमें उसका उपयोग और उसकी जगह किसने ली, लिखा होता है। मुख्य अधिगम क्या है?","optionsHi":["विद्यालय की प्रदर्शनी के लिए वस्तुओं को साफ-सुथरे और आकर्षक ढंग से सजाना और लेबल लगाना सीखना","रोज़मर्रा की वस्तुओं को दैनिक जीवन में परिवर्तन और निरंतरता के साक्ष्य के रूप में देखना","प्राचीन वस्तुओं का बाज़ार मूल्य और पुरानी वस्तुओं का मूल्य लगाना सीखना","यह सिद्ध करना कि अतीत में जीवन हमेशा आज के जीवन से कठिन था"],"explanationHi":"भौतिक वस्तुएँ स्रोत हैं; यह पूछना कि वे कैसे प्रयुक्त होती थीं और उनकी जगह क्या आया, रोज़मर्रा के जीवन में परिवर्तन और निरंतरता की समझ विकसित करता है। ‘तब जीवन कठिन था’ ऐसा निर्णय है जिसे केवल साक्ष्य स्थापित नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-572","question":"Which of the following statements about using primary sources with Class VIII students are correct?\n1. Short, carefully chosen extracts with guiding questions work better than long documents.\n2. Students should be encouraged to ask who produced a source and why.\n3. Primary sources should replace the textbook entirely, since textbooks are secondary.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Manageable extracts and questions about authorship make sources accessible and build critical skills. Statement 3 goes too far: sources and textbooks complement each other, and a textbook gives the framework within which sources make sense.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा VIII के विद्यार्थियों के साथ प्राथमिक स्रोतों के प्रयोग के बारे में निम्नलिखित में से कौन-से कथन सही हैं?\n1. मार्गदर्शक प्रश्नों के साथ छोटे, सावधानी से चुने अंश लंबे दस्तावेज़ों से बेहतर काम करते हैं।\n2. विद्यार्थियों को यह पूछने के लिए प्रोत्साहित करना चाहिए कि स्रोत किसने और क्यों बनाया।\n3. प्राथमिक स्रोतों को पाठ्यपुस्तक का पूरी तरह स्थान ले लेना चाहिए, क्योंकि पाठ्यपुस्तकें द्वितीयक हैं।","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"प्रबंधनीय अंश और लेखक के बारे में प्रश्न स्रोतों को सुलभ बनाते हैं और आलोचनात्मक कौशल विकसित करते हैं। कथन 3 हद से आगे जाता है: स्रोत और पाठ्यपुस्तकें एक-दूसरे की पूरक हैं, और पाठ्यपुस्तक वह ढाँचा देती है जिसमें स्रोत अर्थपूर्ण बनते हैं।"},
  {"id":"cdp-pedagogy-subjects-573","question":"A Class VIII teacher gives students census tables showing the literacy rates of boys and girls in their state over several decades and asks what changed and why. What does this activity mainly develop?","options":["The ability to memorise statistical figures for use in examinations","Map-drawing skills, by plotting the literacy figures on a map","Reading data as evidence of social change, including gender gaps","Knowledge of how the census is conducted and who collects data"],"answer":2,"explanation":"Interpreting data over time shows trends and inequalities, such as the gap between boys' and girls' literacy, and invites students to explain them. Memorising figures or census procedures misses the point.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VIII की एक शिक्षिका विद्यार्थियों को कई दशकों में उनके राज्य में लड़कों और लड़कियों की साक्षरता दर दर्शाती जनगणना सारणियाँ देती है और पूछती है कि क्या बदला और क्यों। यह गतिविधि मुख्यतः क्या विकसित करती है?","optionsHi":["परीक्षाओं में उपयोग के लिए सांख्यिकीय आँकड़े याद करने की योग्यता","साक्षरता के आँकड़ों को मानचित्र पर अंकित करके मानचित्र बनाने का कौशल","आँकड़ों को सामाजिक परिवर्तन के साक्ष्य के रूप में पढ़ना, लैंगिक अंतराल सहित","जनगणना कैसे की जाती है और आँकड़े कौन एकत्र करता है, इसका ज्ञान"],"explanationHi":"समय के साथ आँकड़ों की व्याख्या प्रवृत्तियाँ और असमानताएँ दिखाती है, जैसे लड़कों और लड़कियों की साक्षरता का अंतर, और विद्यार्थियों को उन्हें समझाने के लिए आमंत्रित करती है। आँकड़े याद करना या जनगणना की प्रक्रियाएँ जानना मूल बात से चूक जाता है।"},
  {"id":"cdp-pedagogy-subjects-574","question":"Assertion (A): Conventional symbols are used on topographical maps.\nReason (R): Agreed symbols let anyone who knows the convention read a map without long written labels.","options":["A is true but R is false","Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is false but R is true"],"answer":1,"explanation":"Standard symbols are used because they form a shared language that saves space and is understood across maps and readers. R is the reason for A.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"अभिकथन (A): स्थलाकृतिक मानचित्रों पर परंपरागत चिह्नों का प्रयोग किया जाता है।\nकारण (R): सर्वसम्मत चिह्न परिपाटी जानने वाले किसी भी व्यक्ति को लंबे लिखित लेबलों के बिना मानचित्र पढ़ने देते हैं।","optionsHi":["A सत्य है परंतु R असत्य है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A असत्य है परंतु R सत्य है"],"explanationHi":"मानक चिह्नों का प्रयोग इसलिए होता है कि वे एक साझा भाषा बनाते हैं जो स्थान बचाती है और सभी मानचित्रों तथा पाठकों द्वारा समझी जाती है। R, A का कारण है।"},
  {"id":"cdp-pedagogy-subjects-575","question":"A Class 5 child firmly says, ‘Plants eat soil. That is why we put them in pots of soil.’ Which teaching move is most likely to bring about real conceptual change?","options":["Writing ‘Plants make their food in the leaves’ on the board and asking children to learn it","Telling the child the idea is wrong and giving her a lower grade so that she remembers next time","Growing a money plant in a bottle of plain water for weeks and asking where its food comes from","Skipping the topic until Class 7, when photosynthesis is formally taught in the syllabus"],"answer":2,"explanation":"A plant thriving without soil directly contradicts the child’s idea and pushes her to look for another explanation. Restating the textbook line or penalising does not shift a belief rooted in experience.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक बच्ची दृढ़ता से कहती है, ‘पौधे मिट्टी खाते हैं। इसीलिए हम उन्हें मिट्टी के गमलों में लगाते हैं।’ कौन-सा शिक्षण कदम वास्तविक अवधारणात्मक परिवर्तन लाने की सबसे अधिक संभावना रखता है?","optionsHi":["बोर्ड पर ‘पौधे अपना भोजन पत्तियों में बनाते हैं’ लिखना और बच्चों से उसे याद करने को कहना","बच्ची को बताना कि विचार गलत है और उसे कम अंक देना ताकि वह अगली बार याद रखे","मनी प्लांट को कई सप्ताह तक सादे पानी की बोतल में उगाना और पूछना कि उसका भोजन कहाँ से आता है","विषय को कक्षा 7 तक छोड़ देना, जब पाठ्यक्रम में प्रकाश संश्लेषण औपचारिक रूप से पढ़ाया जाता है"],"explanationHi":"मिट्टी के बिना पनपता पौधा बच्ची के विचार का सीधा खंडन करता है और उसे दूसरी व्याख्या ढूँढ़ने को प्रेरित करता है। पाठ्यपुस्तक की पंक्ति दोहराना या दंड देना अनुभव में जड़ें जमाए विश्वास को नहीं बदलता।"},
  {"id":"cdp-pedagogy-subjects-576","question":"Consider these statements about children’s alternative conceptions in EVS: I. They are often consistent and make sense to the child. II. They disappear once the teacher states the correct fact clearly. III. Many of them are found among children across different regions and cultures. IV. They are a sign of low intelligence. Which are correct?","options":["I and III only","I, II and III only","II and IV only","I and IV only"],"answer":0,"explanation":"Alternative conceptions are reasoned, widely shared and resistant to mere telling. They come from experience and language, not from low intelligence.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"EVS में बच्चों की वैकल्पिक अवधारणाओं के बारे में इन कथनों पर विचार कीजिए: I. वे प्रायः संगत होती हैं और बच्चे को अर्थपूर्ण लगती हैं। II. शिक्षक द्वारा सही तथ्य स्पष्ट रूप से बता देने पर वे समाप्त हो जाती हैं। III. उनमें से अनेक विभिन्न क्षेत्रों और संस्कृतियों के बच्चों में पाई जाती हैं। IV. वे निम्न बुद्धि का संकेत हैं। कौन-से सही हैं?","optionsHi":["केवल I और III","केवल I, II और III","केवल II और IV","केवल I और IV"],"explanationHi":"वैकल्पिक अवधारणाएँ तर्कसंगत, व्यापक रूप से साझा और केवल बता देने से न बदलने वाली होती हैं। वे अनुभव और भाषा से आती हैं, निम्न बुद्धि से नहीं।"},
  {"id":"cdp-pedagogy-subjects-577","question":"Children believe that ‘heavy things sink’. The teacher shows that a large, heavy wooden log floats while a small iron nail sinks, and the children are puzzled because their rule fails. In the conceptual-change model, this step mainly serves to:","options":["show that the new idea is useful in fresh situations","create dissatisfaction with the children’s existing idea","make the new idea clear and easy to understand","reward the children who gave the correct answer earlier on"],"answer":1,"explanation":"Posner and colleagues held that conceptual change begins when learners become dissatisfied with their current idea; the new one must then be intelligible, plausible and fruitful. This demonstration creates the dissatisfaction.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"बच्चे मानते हैं कि ‘भारी चीज़ें डूबती हैं’। शिक्षक दिखाता है कि एक बड़ा, भारी लकड़ी का लट्ठा तैरता है जबकि एक छोटी लोहे की कील डूबती है, और बच्चे हैरान हैं क्योंकि उनका नियम विफल हो गया। अवधारणात्मक परिवर्तन मॉडल में, यह चरण मुख्यतः क्या करता है?","optionsHi":["यह दिखाना कि नया विचार नई परिस्थितियों में उपयोगी है","बच्चों के मौजूदा विचार के प्रति असंतोष पैदा करना","नए विचार को स्पष्ट और समझने में आसान बनाना","पहले सही उत्तर देने वाले बच्चों को पुरस्कृत करना"],"explanationHi":"पॉस्नर और सहयोगियों के अनुसार अवधारणात्मक परिवर्तन तब शुरू होता है जब शिक्षार्थी अपने वर्तमान विचार से असंतुष्ट हो जाते हैं; फिर नया विचार बोधगम्य, विश्वसनीय और फलदायी होना चाहिए। यह प्रदर्शन असंतोष पैदा करता है।"},
  {"id":"cdp-pedagogy-subjects-578","question":"A Class 3 child says, ‘A car is living because it moves, but a tree is non-living because it does not move.’ The teacher’s best response is to:","options":["tell the child that cars are machines made in factories and therefore can never be living things","ask the child to memorise the textbook list of characteristics of living things","ignore it, since the child will understand the idea properly in a higher class","have children list what living things do (grow, feed, reproduce) and test the car and tree"],"answer":3,"explanation":"The child is using one criterion (movement). Having children examine several features themselves widens the concept through reasoning, which a bare correction or a memorised list does not.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 3 का एक बच्चा कहता है, ‘कार सजीव है क्योंकि वह चलती है, पर पेड़ निर्जीव है क्योंकि वह नहीं चलता।’ शिक्षक की सबसे अच्छी प्रतिक्रिया है:","optionsHi":["बच्चे को बताना कि कारें कारख़ानों में बनी मशीनें हैं और इसलिए कभी सजीव नहीं हो सकतीं","बच्चे से सजीवों के लक्षणों की पाठ्यपुस्तक की सूची रटवाना","इसे अनदेखा करना, क्योंकि बच्चा ऊँची कक्षा में यह विचार ठीक से समझ लेगा","बच्चों से सजीव जो करते हैं (वृद्धि, भोजन, जनन) उसकी सूची बनवाना और कार तथा पेड़ को उन पर परखना"],"explanationHi":"बच्चा एक ही कसौटी (गति) का प्रयोग कर रहा है। बच्चों से अनेक लक्षणों की स्वयं जाँच करवाना तर्क के माध्यम से अवधारणा को विस्तृत करता है, जो सीधा सुधार या रटी हुई सूची नहीं करती।"},
  {"id":"cdp-pedagogy-subjects-579","question":"Asked to circle the animals in a picture of a village, most Class 3 children circle the cow, the buffalo and the dog but not the ant, the crow or the boy. This most likely shows that:","options":["the children cannot see small creatures such as ants clearly in a printed picture","the children use a narrow everyday sense of ‘animal’, unlike the scientific one","the picture was badly drawn, so the smaller animals were hard to recognise","the children have not studied insects and birds yet, so the question is unfair"],"answer":1,"explanation":"In everyday use ‘animal’ often means a four-legged mammal, so insects, birds and humans are left out. This is a classic language-based alternative conception.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"गाँव के चित्र में जानवरों पर घेरा लगाने को कहने पर कक्षा 3 के अधिकांश बच्चे गाय, भैंस और कुत्ते पर घेरा लगाते हैं, पर चींटी, कौए या लड़के पर नहीं। यह सबसे संभावित रूप से दर्शाता है कि:","optionsHi":["बच्चे छपे चित्र में चींटी जैसे छोटे जीवों को स्पष्ट रूप से नहीं देख पाते","बच्चे ‘जानवर’ के वैज्ञानिक अर्थ के विपरीत उसके संकीर्ण दैनिक अर्थ का प्रयोग करते हैं","चित्र खराब बना था, इसलिए छोटे जानवरों को पहचानना कठिन था","बच्चों ने अभी कीटों और पक्षियों का अध्ययन नहीं किया है, इसलिए प्रश्न अनुचित है"],"explanationHi":"दैनिक प्रयोग में ‘जानवर’ का अर्थ अक्सर चार पैरों वाला स्तनधारी होता है, इसलिए कीट, पक्षी और मनुष्य छूट जाते हैं। यह भाषा-आधारित वैकल्पिक अवधारणा का क्लासिक उदाहरण है।"},
  {"id":"cdp-pedagogy-subjects-580","question":"Several Class 3 children in an industrial town say that clouds are made of smoke from factory chimneys. Which teaching sequence best addresses this idea?","options":["Telling them clouds are made of water and asking them to write the correct answer five times","Showing a labelled diagram of the water cycle and naming each of its stages in order","Letting them see steam from boiling water form drops on a cold plate, then discussing clouds","Agreeing with them, since factories do pollute the air and smoke does rise into the sky"],"answer":2,"explanation":"The child’s idea comes from what she sees. Seeing water vapour condense gives a new, concrete experience from which she can build a better idea, before any diagram or term is used.","difficulty":"hard","source":"CTET Paper 1 · NVS PRT","questionHi":"एक औद्योगिक नगर के कक्षा 3 के कई बच्चे कहते हैं कि बादल कारख़ानों की चिमनियों के धुएँ से बने होते हैं। इस विचार को कौन-सा शिक्षण क्रम सबसे अच्छी तरह संबोधित करता है?","optionsHi":["उन्हें बताना कि बादल पानी के बने होते हैं और सही उत्तर पाँच बार लिखवाना","जल चक्र का नामांकित आरेख दिखाना और क्रम से उसके प्रत्येक चरण का नाम बताना","उबलते पानी की भाप को ठंडी प्लेट पर बूँदें बनाते देखने देना, फिर बादलों पर चर्चा करना","उनसे सहमत हो जाना, क्योंकि कारख़ाने सचमुच हवा को प्रदूषित करते हैं और धुआँ आकाश में उठता है"],"explanationHi":"बच्ची का विचार उसके देखे हुए से आता है। जलवाष्प को संघनित होते देखना एक नया, मूर्त अनुभव देता है जिससे वह कोई आरेख या शब्द आने से पहले बेहतर विचार बना सकती है।"},
  {"id":"cdp-pedagogy-subjects-581","question":"A Class 4 child walking home at night says, ‘The moon follows me wherever I go.’ Which activity best helps the child rethink this idea?","options":["Telling the child that the moon is very far away and actually moves around the earth, not her","Asking the child to read the chapter on the moon again and answer its questions","Asking the child to draw the moon in her notebook every night for a month","Having two children walk opposite ways at night and asking if the moon can follow both"],"answer":3,"explanation":"The activity creates a contradiction the child can see for herself and leads her to think about distance. Telling a fact does not engage the reasoning behind the belief.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"रात में घर लौटता कक्षा 4 का एक बच्चा कहता है, ‘चाँद मेरे पीछे-पीछे चलता है, मैं जहाँ भी जाऊँ।’ कौन-सी गतिविधि बच्चे को इस विचार पर पुनर्विचार करने में सबसे अच्छी तरह मदद करती है?","optionsHi":["बच्चे को बताना कि चाँद बहुत दूर है और वास्तव में पृथ्वी के चारों ओर घूमता है, उसके नहीं","बच्चे से चाँद वाला अध्याय फिर पढ़ने और उसके प्रश्नों के उत्तर देने को कहना","बच्चे से एक महीने तक हर रात अपनी कॉपी में चाँद का चित्र बनवाना","रात में दो बच्चों को विपरीत दिशाओं में चलवाना और पूछना कि क्या चाँद दोनों का पीछा कर सकता है"],"explanationHi":"यह गतिविधि ऐसा विरोधाभास पैदा करती है जिसे बच्चा स्वयं देख सकता है और उसे दूरी के बारे में सोचने की ओर ले जाती है। तथ्य बता देना विश्वास के पीछे के तर्क को नहीं छूता।"},
  {"id":"cdp-pedagogy-subjects-582","question":"A Class 5 child believes that ‘a sweater gives out heat and that is why it keeps us warm.’ Which activity most directly challenges this idea?","options":["Wrapping one ice cube in wool, leaving another bare, and comparing which melts first","Asking children to touch a sweater and say whether it feels warm or cold to their hands","Reading a passage on wool production by shepherds in Ladakh and Himachal","Asking children to list the woollen clothes their families wear in winter"],"answer":0,"explanation":"If the sweater gave out heat, the wrapped ice would melt faster; it melts more slowly, because wool slows the movement of heat. The prediction-contradiction is what challenges the idea.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 5 की एक बच्ची मानती है कि ‘स्वेटर गर्मी देता है और इसीलिए हमें गर्म रखता है।’ कौन-सी गतिविधि इस विचार को सबसे सीधे चुनौती देती है?","optionsHi":["एक बर्फ़ के टुकड़े को ऊन में लपेटना, दूसरे को खुला छोड़ना, और तुलना करना कि कौन पहले पिघलता है","बच्चों से स्वेटर छूकर बताने को कहना कि उनके हाथों को वह गर्म लगता है या ठंडा","लद्दाख और हिमाचल में चरवाहों द्वारा ऊन उत्पादन पर एक गद्यांश पढ़ना","बच्चों से उनके परिवारों द्वारा सर्दियों में पहने जाने वाले ऊनी कपड़ों की सूची बनवाना"],"explanationHi":"यदि स्वेटर गर्मी देता, तो लिपटी हुई बर्फ़ तेज़ी से पिघलती; वह धीरे पिघलती है, क्योंकि ऊन ऊष्मा की गति को धीमा करती है। पूर्वानुमान और विरोधाभास ही विचार को चुनौती देता है।"},
  {"id":"cdp-pedagogy-subjects-583","question":"Which demonstration most directly challenges a child’s belief that ‘heavier things always fall faster’?","options":["Dropping a brick and a feather together from the same height on the school playground","Dropping a flat sheet of paper and an identical sheet crumpled into a ball together","Dropping a heavy stone and a light dry leaf together from a rooftop","Dropping a cricket ball and an inflated balloon together from the same height"],"answer":1,"explanation":"The flat and crumpled sheets weigh the same yet fall differently, so weight cannot be the deciding factor. The other pairs seem to confirm the child’s belief.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कौन-सा प्रदर्शन बच्चे की इस धारणा को सबसे सीधे चुनौती देता है कि ‘भारी चीज़ें हमेशा तेज़ी से गिरती हैं’?","optionsHi":["विद्यालय के खेल के मैदान में एक ही ऊँचाई से एक ईंट और एक पंख को साथ गिराना","एक समतल कागज़ की शीट और उसी के समान दूसरी शीट को गोला बनाकर साथ गिराना","छत से एक भारी पत्थर और एक हल्की सूखी पत्ती को साथ गिराना","एक ही ऊँचाई से एक क्रिकेट गेंद और एक फुलाए हुए गुब्बारे को साथ गिराना"],"explanationHi":"समतल और मुड़ी हुई शीट का वज़न समान है फिर भी वे अलग तरह से गिरती हैं, इसलिए वज़न निर्णायक कारक नहीं हो सकता। अन्य जोड़े बच्चे की धारणा की पुष्टि करते प्रतीत होते हैं।"},
  {"id":"cdp-pedagogy-subjects-584","question":"Before teaching about rain, a Class 3 teacher wants to know what ideas children already hold. The most useful tool is to:","options":["give a ten-question multiple-choice test based on the textbook chapter","ask the textbook question ‘What is rain?’ and check answers against the book","ask children to draw ‘where rain comes from’ and explain their drawings","explain the water cycle first and then ask whether anyone has any doubts"],"answer":2,"explanation":"Open drawings with explanations reveal children’s own ideas, including unexpected ones. Closed tests and textbook questions check recall and hide alternative conceptions.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"वर्षा के बारे में पढ़ाने से पहले कक्षा 3 की एक शिक्षिका जानना चाहती है कि बच्चों के पास पहले से कौन-से विचार हैं। सबसे उपयोगी साधन है:","optionsHi":["पाठ्यपुस्तक के अध्याय पर आधारित दस प्रश्नों की बहुविकल्पीय परीक्षा देना","पाठ्यपुस्तक का प्रश्न ‘वर्षा क्या है?’ पूछना और उत्तरों को पुस्तक से मिलाना","बच्चों से ‘वर्षा कहाँ से आती है’ का चित्र बनवाना और उनके चित्रों की व्याख्या करवाना","पहले जल चक्र समझाना और फिर पूछना कि किसी को कोई शंका है क्या"],"explanationHi":"व्याख्या सहित खुले चित्र बच्चों के अपने विचार, अप्रत्याशित विचारों सहित, प्रकट करते हैं। बंद परीक्षाएँ और पाठ्यपुस्तक के प्रश्न स्मरण की जाँच करते हैं और वैकल्पिक अवधारणाओं को छिपा देते हैं।"},
  {"id":"cdp-pedagogy-subjects-585","question":"A teacher shows a picture in which three cartoon children give different reasons why a puddle has dried up, and asks the class whom they agree with and why. The main purpose of such a ‘concept cartoon’ is to:","options":["test how quickly and accurately children can read the speech bubbles","find out which children can draw and colour cartoon characters well","entertain children for a few minutes before the real lesson starts","bring out and discuss children’s ideas without fear of being personally wrong"],"answer":3,"explanation":"Concept cartoons present competing views so that children can argue for one without exposing their ‘own’ wrong answer, which makes it safe to reveal and examine alternative ideas.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षक एक ऐसा चित्र दिखाता है जिसमें तीन कार्टून बच्चे यह अलग-अलग कारण बताते हैं कि एक गड्ढे का पानी क्यों सूख गया, और कक्षा से पूछता है कि वे किससे सहमत हैं और क्यों। ऐसे ‘संप्रत्यय कार्टून’ का मुख्य उद्देश्य है:","optionsHi":["यह परखना कि बच्चे संवाद-बुलबुले कितनी जल्दी और सही पढ़ सकते हैं","यह पता लगाना कि कौन-से बच्चे कार्टून पात्र अच्छी तरह बना और रंग सकते हैं","असली पाठ शुरू होने से पहले बच्चों का कुछ मिनट मनोरंजन करना","व्यक्तिगत रूप से गलत होने के डर के बिना बच्चों के विचारों को सामने लाना और उन पर चर्चा करना"],"explanationHi":"संप्रत्यय कार्टून प्रतिस्पर्धी विचार प्रस्तुत करते हैं ताकि बच्चे अपना ‘स्वयं का’ गलत उत्तर उजागर किए बिना किसी एक के पक्ष में तर्क दे सकें, जिससे वैकल्पिक विचारों को प्रकट करना और जाँचना सुरक्षित हो जाता है।"},
  {"id":"cdp-pedagogy-subjects-586","question":"Assertion (A): Children’s alternative conceptions are a hindrance and should be wiped out before any teaching begins. Reason (R): Children form ideas about the world through their own interaction with the environment. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"Children’s ideas do come from experience (R is true), but they are the starting point for teaching, not something to ‘wipe out’ first; constructivist teaching builds on and reworks them.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"अभिकथन (A): बच्चों की वैकल्पिक अवधारणाएँ बाधा हैं और किसी भी शिक्षण से पहले उन्हें मिटा देना चाहिए। कारण (R): बच्चे पर्यावरण के साथ अपनी अंतःक्रिया से दुनिया के बारे में विचार बनाते हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"बच्चों के विचार वास्तव में अनुभव से आते हैं (R सत्य है), पर वे शिक्षण का आरंभ-बिंदु हैं, पहले ‘मिटाने’ की चीज़ नहीं; रचनावादी शिक्षण उन्हीं पर निर्माण करता है और उन्हें पुनर्गठित करता है।"},
  {"id":"cdp-pedagogy-subjects-587","question":"A Class 4 child says that the drops on the outside of a glass of iced water have ‘leaked through the glass’. Which test best challenges this?","options":["Explaining to the child that glass has no holes through which water could pass","Adding ink to the water and checking whether the drops outside turn coloured","Wiping the drops away and asking the child to taste the water inside","Using a steel glass instead and simply telling the child the right answer"],"answer":1,"explanation":"If water leaked, the outside drops would carry the ink colour; they stay clear, so they must come from somewhere else (the air). The test lets evidence, not authority, settle the matter.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 का एक बच्चा कहता है कि बर्फ़ के पानी के गिलास के बाहर की बूँदें ‘गिलास से रिसकर आई हैं’। कौन-सा परीक्षण इसे सबसे अच्छी तरह चुनौती देता है?","optionsHi":["बच्चे को समझाना कि काँच में कोई छेद नहीं होते जिनसे पानी निकल सके","पानी में स्याही डालना और जाँचना कि बाहर की बूँदें रंगीन हो जाती हैं या नहीं","बूँदों को पोंछ देना और बच्चे से अंदर का पानी चखने को कहना","इसके बजाय स्टील का गिलास लेना और बच्चे को सीधे सही उत्तर बता देना"],"explanationHi":"यदि पानी रिसता, तो बाहर की बूँदों में स्याही का रंग होता; वे साफ रहती हैं, इसलिए वे कहीं और से (हवा से) आई होंगी। परीक्षण में साक्ष्य निर्णय करता है, अधिकार नहीं।"},
  {"id":"cdp-pedagogy-subjects-588","question":"A teacher sticks a piece of dry paper to the bottom inside of a glass, turns the glass upside down and pushes it straight down into a bucket of water. The paper stays dry. This activity is mainly meant to challenge the idea that:","options":["water is lighter than the air above it","paper does not absorb water at all","an ‘empty’ glass contains nothing","glass is not a living thing"],"answer":2,"explanation":"Air trapped in the glass keeps the water out, showing that the ‘empty’ glass is full of air, which takes up space. Children commonly think empty means nothing is there.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"एक शिक्षक सूखे कागज़ का टुकड़ा गिलास के भीतरी तल पर चिपकाता है, गिलास को उलटा करता है और उसे सीधे पानी की बाल्टी में दबाता है। कागज़ सूखा रहता है। यह गतिविधि मुख्यतः किस विचार को चुनौती देने के लिए है कि:","optionsHi":["पानी अपने ऊपर की हवा से हल्का है","कागज़ पानी को बिल्कुल सोखता नहीं","‘खाली’ गिलास में कुछ नहीं होता","काँच सजीव वस्तु नहीं है"],"explanationHi":"गिलास में फँसी हवा पानी को अंदर आने से रोकती है, जिससे दिखता है कि ‘खाली’ गिलास हवा से भरा है, जो स्थान घेरती है। बच्चे प्रायः मानते हैं कि खाली का अर्थ है कि वहाँ कुछ नहीं है।"},
  {"id":"cdp-pedagogy-subjects-589","question":"Class 3 children classify a seed as non-living because ‘it does not move or eat’. The best response is to:","options":["sow soaked seeds and keep others dry, then watch over days for signs of life","tell them that seeds are living things and ask them to remember the fact","show them a picture of a big tree and say that it grew from a small seed","accept their answer, since seeds really do not move, eat or breathe"],"answer":0,"explanation":"Seeing seeds germinate under the right conditions, unlike the dry ones, gives evidence that seeds are alive but dormant. Simply stating it does not shift the child’s criterion.","difficulty":"hard","source":"CTET Paper 1 · NVS PRT","questionHi":"कक्षा 3 के बच्चे बीज को निर्जीव वर्गीकृत करते हैं क्योंकि ‘वह न चलता है, न खाता है’। सबसे अच्छी प्रतिक्रिया है:","optionsHi":["भिगोए हुए बीज बोना और दूसरे सूखे रखना, फिर कई दिनों तक जीवन के लक्षणों को देखना","उन्हें बताना कि बीज सजीव होते हैं और इस तथ्य को याद रखने को कहना","उन्हें बड़े पेड़ का चित्र दिखाना और कहना कि वह छोटे बीज से उगा है","उनका उत्तर स्वीकार कर लेना, क्योंकि बीज सचमुच न चलते हैं, न खाते हैं, न साँस लेते हैं"],"explanationHi":"सही परिस्थितियों में बीजों को अंकुरित होते देखना, सूखे बीजों के विपरीत, यह साक्ष्य देता है कि बीज सजीव हैं पर सुप्त अवस्था में हैं। केवल कह देने से बच्चे की कसौटी नहीं बदलती।"},
  {"id":"cdp-pedagogy-subjects-590","question":"Which of the following can be sources of children’s alternative conceptions? I. Everyday language, such as ‘the sun rises’. II. Direct sensory experience. III. Textbook illustrations and over-simplified statements. IV. The teacher’s own explanations.","options":["I and II only","I, II and III only","II and IV only","I, II, III and IV"],"answer":3,"explanation":"Alternative conceptions arise from everyday talk and experience, but also from simplified textbook material and from teachers who hold the same ideas. All four are sources.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"निम्नलिखित में से कौन बच्चों की वैकल्पिक अवधारणाओं के स्रोत हो सकते हैं? I. दैनिक भाषा, जैसे ‘सूरज उगता है’। II. प्रत्यक्ष संवेदी अनुभव। III. पाठ्यपुस्तक के चित्र और अति-सरलीकृत कथन। IV. शिक्षक की अपनी व्याख्याएँ।","optionsHi":["केवल I और II","केवल I, II और III","केवल II और IV","I, II, III और IV"],"explanationHi":"वैकल्पिक अवधारणाएँ दैनिक बातचीत और अनुभव से तो आती ही हैं, पर सरलीकृत पाठ्यपुस्तक सामग्री से और उन शिक्षकों से भी, जो स्वयं वही विचार रखते हैं। चारों स्रोत हैं।"},
  {"id":"cdp-pedagogy-subjects-591","question":"To check whether Class 5 children really understand why wet clothes dry, which question is best?","options":["What is evaporation? Write its definition from the textbook.","Name the process by which wet clothes dry, and write its definition in one line.","Will clothes dry faster on a windy day or a still day, if both are sunny? Why?","Do clothes dry in the sun? Write yes or no and name the process."],"answer":2,"explanation":"Applying the idea to a new situation and giving a reason shows understanding; the others can be answered by recalling a word.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"यह जाँचने के लिए कि कक्षा 5 के बच्चे वास्तव में समझते हैं कि गीले कपड़े क्यों सूखते हैं, कौन-सा प्रश्न सबसे अच्छा है?","optionsHi":["वाष्पन क्या है? पाठ्यपुस्तक से उसकी परिभाषा लिखो।","वह प्रक्रिया बताओ जिससे गीले कपड़े सूखते हैं, और उसकी परिभाषा एक पंक्ति में लिखो।","यदि दोनों दिन धूप है, तो कपड़े हवादार दिन में जल्दी सूखेंगे या शांत दिन में? क्यों?","क्या कपड़े धूप में सूखते हैं? हाँ या नहीं लिखो और प्रक्रिया का नाम बताओ।"],"explanationHi":"विचार को नई स्थिति में लागू करना और कारण देना समझ दिखाता है; अन्य प्रश्नों का उत्तर केवल एक शब्द याद करके दिया जा सकता है।"},
  {"id":"cdp-pedagogy-subjects-592","question":"After a lesson with several floating and sinking activities, many Class 4 children still say that ‘heavy things sink’. The best interpretation for the teacher is that:","options":["the children were not paying attention during the activities and need to be warned firmly","alternative conceptions resist change and need repeated experiences in varied contexts","the activities were the wrong choice and should be replaced with clear lectures","these children are not yet ready for EVS and need separate remedial classes first"],"answer":1,"explanation":"Research on alternative conceptions shows they persist after a single lesson; children need repeated, varied encounters and discussion. Blaming the children or going back to lectures misreads this.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs","questionHi":"तैरने और डूबने की कई गतिविधियों वाले पाठ के बाद भी कक्षा 4 के कई बच्चे कहते हैं कि ‘भारी चीज़ें डूबती हैं’। शिक्षक के लिए सबसे अच्छी व्याख्या है कि:","optionsHi":["बच्चे गतिविधियों के दौरान ध्यान नहीं दे रहे थे और उन्हें सख़्ती से चेतावनी देनी चाहिए","वैकल्पिक अवधारणाएँ परिवर्तन का प्रतिरोध करती हैं और विविध संदर्भों में बार-बार अनुभव माँगती हैं","गतिविधियाँ गलत चुनाव थीं और उनकी जगह स्पष्ट व्याख्यान दिए जाने चाहिए","ये बच्चे अभी EVS के लिए तैयार नहीं हैं और पहले उन्हें अलग उपचारात्मक कक्षाएँ चाहिए"],"explanationHi":"वैकल्पिक अवधारणाओं पर शोध दिखाता है कि वे एक पाठ के बाद भी बनी रहती हैं; बच्चों को बार-बार, विविध अनुभव और चर्चा चाहिए। बच्चों को दोष देना या व्याख्यानों पर लौटना इसे गलत समझना है।"},
  {"id":"cdp-pedagogy-subjects-593","question":"A Class 1 child says, ‘The sun is sad today, so it has hidden behind the clouds.’ This kind of thinking is best described as:","options":["animism, typical of Piaget’s pre-operational stage","egocentrism, typical of the formal operational stage","conservation, typical of the concrete operational stage","hypothetical reasoning, typical of the formal operational stage"],"answer":0,"explanation":"Giving feelings and intentions to non-living things is animism, characteristic of the pre-operational stage (about 2–7 years). The other options name the wrong process or the wrong stage.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 1 की एक बच्ची कहती है, ‘सूरज आज उदास है, इसलिए वह बादलों के पीछे छिप गया है।’ इस प्रकार की सोच का सबसे अच्छा वर्णन है:","optionsHi":["जीववाद (animism), जो पियाजे की पूर्व-संक्रियात्मक अवस्था की विशेषता है","अहंकेंद्रिता, जो औपचारिक संक्रियात्मक अवस्था की विशेषता है","संरक्षण (conservation), जो मूर्त संक्रियात्मक अवस्था की विशेषता है","परिकल्पनात्मक तर्क, जो औपचारिक संक्रियात्मक अवस्था की विशेषता है"],"explanationHi":"निर्जीव वस्तुओं को भावनाएँ और इरादे देना जीववाद है, जो पूर्व-संक्रियात्मक अवस्था (लगभग 2–7 वर्ष) की विशेषता है। अन्य विकल्प गलत प्रक्रिया या गलत अवस्था का नाम लेते हैं।"},
  {"id":"cdp-pedagogy-subjects-594","question":"A teacher asks Class 5 children what will happen when the ice in a glass of water filled to the brim melts. Most predict that it will overflow. They watch, see that it does not, and then try to explain why. This strategy is called:","options":["Drill and practice method","Programmed instruction","Predict–Observe–Explain","Advance organiser"],"answer":2,"explanation":"Predict–Observe–Explain brings out children’s ideas (predict), confronts them with evidence (observe) and pushes for reconciliation (explain).","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक शिक्षक कक्षा 5 के बच्चों से पूछता है कि किनारे तक भरे पानी के गिलास में बर्फ़ पिघलने पर क्या होगा। अधिकांश अनुमान लगाते हैं कि पानी छलक जाएगा। वे देखते हैं, पाते हैं कि ऐसा नहीं होता, और फिर कारण समझाने का प्रयास करते हैं। इस युक्ति को कहते हैं:","optionsHi":["अभ्यास और पुनरावृत्ति विधि","अभिक्रमित अनुदेशन","पूर्वानुमान–अवलोकन–व्याख्या (Predict–Observe–Explain)","अग्र-आयोजक (Advance organiser)"],"explanationHi":"पूर्वानुमान–अवलोकन–व्याख्या बच्चों के विचारों को सामने लाता है (पूर्वानुमान), उन्हें साक्ष्य से रूबरू कराता है (अवलोकन) और समाधान के लिए प्रेरित करता है (व्याख्या)।"},
  {"id":"cdp-pedagogy-subjects-595","question":"A Class 4 child draws the sun as a small circle next to a large earth. The teacher’s most appropriate response is to:","options":["mark the drawing wrong and draw the correct sizes beside it","ask the child to explain her drawing and use it to understand how she is thinking","praise the drawing for its colours and move on","tell the class that the sun is much bigger than the earth and ask them to copy the line"],"answer":1,"explanation":"A drawing is a window into the child’s ideas; asking her to explain it reveals the reasoning (the sun looks small) that the teacher must work with. Marking it wrong closes that window.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 4 की एक बच्ची सूरज को एक बड़ी पृथ्वी के पास छोटे वृत्त के रूप में बनाती है। शिक्षक की सबसे उपयुक्त प्रतिक्रिया है:","optionsHi":["चित्र को गलत चिह्नित करना और उसके पास सही आकार बनाकर दिखाना","बच्ची से अपने चित्र की व्याख्या करवाना और उससे समझना कि वह कैसे सोच रही है","चित्र के रंगों की प्रशंसा करना और आगे बढ़ जाना","कक्षा को बताना कि सूरज पृथ्वी से बहुत बड़ा है और उनसे यह पंक्ति उतारने को कहना"],"explanationHi":"चित्र बच्ची के विचारों की खिड़की है; उससे व्याख्या करवाना वह तर्क (सूरज छोटा दिखता है) प्रकट करता है जिसके साथ शिक्षक को काम करना है। गलत चिह्नित करना वह खिड़की बंद कर देता है।"},
  {"id":"cdp-pedagogy-subjects-596","question":"Class 4 children studying houses in Ladakh say, ‘The roofs are flat because the people there are too poor to make sloping roofs.’ The teacher should:","options":["agree, because Ladakh is a remote area where families have little money","tell them the correct reason about the climate and move on to the next chapter","avoid the topic, since it may hurt the feelings of children from Ladakh","guide them to find out how little rain falls there and how flat roofs are used"],"answer":3,"explanation":"The remark is a social-science alternative conception built on stereotype. Linking house design to climate and use replaces the assumption with reasoning and builds respect for other ways of life.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"लद्दाख के घरों का अध्ययन करते हुए कक्षा 4 के बच्चे कहते हैं, ‘छतें सपाट हैं क्योंकि वहाँ के लोग ढालू छतें बनाने के लिए बहुत गरीब हैं।’ शिक्षक को चाहिए कि:","optionsHi":["सहमत हो जाए, क्योंकि लद्दाख दूरस्थ क्षेत्र है जहाँ परिवारों के पास कम पैसा है","उन्हें जलवायु के बारे में सही कारण बताए और अगले अध्याय पर चले","विषय से बचे, क्योंकि इससे लद्दाख के बच्चों की भावनाएँ आहत हो सकती हैं","उन्हें यह खोजने के लिए मार्गदर्शन दे कि वहाँ कितनी कम वर्षा होती है और सपाट छतों का उपयोग कैसे होता है"],"explanationHi":"यह टिप्पणी रूढ़िबद्ध धारणा पर बनी सामाजिक विज्ञान की वैकल्पिक अवधारणा है। घर की बनावट को जलवायु और उपयोग से जोड़ना धारणा की जगह तर्क रखता है और अन्य जीवन-शैलियों के प्रति सम्मान बनाता है।"},
  {"id":"cdp-pedagogy-subjects-597","question":"Which of the following is LEAST useful for finding out the ideas children bring to an EVS topic?","options":["A true/false test whose statements are taken word for word from the textbook","Asking children to draw what they think happens and then explain it to the class","An open discussion in which the teacher asks ‘What do you think, and why?’","A concept cartoon showing different views for children to argue about"],"answer":0,"explanation":"Textbook-based true/false items test recognition of book statements and give no reasons, so they hide the child’s own ideas. The others are open and reveal reasoning.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"EVS के किसी विषय पर बच्चे जो विचार लेकर आते हैं उन्हें जानने के लिए निम्नलिखित में से कौन सबसे कम उपयोगी है?","optionsHi":["सही/गलत परीक्षा जिसके कथन पाठ्यपुस्तक से शब्दशः लिए गए हों","बच्चों से यह चित्र बनवाना कि उनके अनुसार क्या होता है और फिर कक्षा को समझाने को कहना","खुली चर्चा जिसमें शिक्षक पूछता है ‘तुम क्या सोचते हो, और क्यों?’","संप्रत्यय कार्टून जो बच्चों के बहस करने के लिए अलग-अलग दृष्टिकोण दिखाता हो"],"explanationHi":"पाठ्यपुस्तक पर आधारित सही/गलत प्रश्न पुस्तक के कथनों की पहचान जाँचते हैं और कारण नहीं देते, इसलिए बच्चे के अपने विचार छिपे रहते हैं। अन्य खुले हैं और तर्क प्रकट करते हैं।"},
  {"id":"cdp-pedagogy-subjects-598","question":"A Class 3 child says, ‘A hen is not an animal, because animals give birth to babies and hens lay eggs.’ The best response of the teacher is to:","options":["have children list many animals, find how the young of each are born or hatched, and rethink ‘animal’","tell the child that hens are birds, and that birds are not counted as animals","explain the scientific classification of vertebrates into five classes, with examples of each","correct the child and give a lower grade, so that the mistake is not repeated"],"answer":0,"explanation":"Exploring many examples widens the child’s narrow category. Saying ‘birds are not animals’ is itself a misconception, and formal classification is beyond the stage.","difficulty":"very-hard","source":"CTET Paper 1 · NVS PRT","questionHi":"कक्षा 3 की एक बच्ची कहती है, ‘मुर्गी जानवर नहीं है, क्योंकि जानवर बच्चों को जन्म देते हैं और मुर्गी अंडे देती है।’ शिक्षक की सबसे अच्छी प्रतिक्रिया है:","optionsHi":["बच्चों से अनेक जानवरों की सूची बनवाना, यह खोजना कि प्रत्येक के बच्चे कैसे जन्म लेते या अंडे से निकलते हैं, और ‘जानवर’ पर पुनर्विचार करना","बच्ची को बताना कि मुर्गी पक्षी है और पक्षी जानवर नहीं गिने जाते","पाँच वर्गों में कशेरुकियों का वैज्ञानिक वर्गीकरण, प्रत्येक के उदाहरणों सहित, समझाना","बच्ची को सुधारना और कम अंक देना, ताकि गलती दोहराई न जाए"],"explanationHi":"अनेक उदाहरण खोजना बच्ची की संकीर्ण श्रेणी को विस्तृत करता है। ‘पक्षी जानवर नहीं हैं’ कहना स्वयं एक भ्रांति है, और औपचारिक वर्गीकरण इस अवस्था से आगे की बात है।"},
  {"id":"cdp-pedagogy-subjects-599","question":"After a lesson on how leaves make food, a Class 5 child writes, ‘Plants take food from the soil and then cook it in the leaves.’ This answer best shows that the child has:","options":["joined the new information to her old idea, so her conception has changed only partly","fully understood how plants make food, and simply expressed it in her own everyday words","not listened in class at all and is repeating what she believed before","copied the answer from another child without understanding it herself"],"answer":0,"explanation":"Such ‘hybrid’ answers are common: new words are attached to an old framework. The teacher should probe further rather than treat it as either complete success or plain failure.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"पत्तियाँ भोजन कैसे बनाती हैं इस पाठ के बाद कक्षा 5 की एक बच्ची लिखती है, ‘पौधे मिट्टी से भोजन लेते हैं और फिर उसे पत्तियों में पकाते हैं।’ यह उत्तर सबसे अच्छी तरह दिखाता है कि बच्ची ने:","optionsHi":["नई जानकारी को अपने पुराने विचार से जोड़ लिया है, इसलिए उसकी अवधारणा केवल आंशिक रूप से बदली है","पौधे भोजन कैसे बनाते हैं यह पूरी तरह समझ लिया है, और उसे बस अपने दैनिक शब्दों में व्यक्त किया है","कक्षा में बिल्कुल नहीं सुना और वही दोहरा रही है जो पहले मानती थी","किसी दूसरे बच्चे का उत्तर बिना स्वयं समझे नकल कर लिया है"],"explanationHi":"ऐसे ‘संकर’ उत्तर आम हैं: नए शब्द पुराने ढाँचे से जुड़ जाते हैं। शिक्षक को इसे पूर्ण सफलता या सीधी विफलता मानने के बजाय आगे जाँच करनी चाहिए।"},
  {"id":"cdp-pedagogy-subjects-600","question":"Which of the following does NCF 2005 recommend for the secondary stage rather than for the upper primary stage of science?","options":["Learning the principles of science through familiar experiences and simple experiments","Designing simple technological units and modules with one's own hands","Learning about environment and health through activities and local surveys","Studying science as disciplines, stressing abstraction and quantitative reasoning"],"answer":3,"explanation":"NCF 2005 keeps upper primary science close to familiar experience, hands-on technology, activities and surveys; abstraction, quantitative reasoning and disciplinary treatment begin at the secondary stage.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"विज्ञान के उच्च प्राथमिक स्तर के बजाय माध्यमिक स्तर के लिए NCF 2005 निम्नलिखित में से किसकी अनुशंसा करता है?","optionsHi":["परिचित अनुभवों और सरल प्रयोगों के माध्यम से विज्ञान के सिद्धांत सीखना","अपने हाथों से सरल प्रौद्योगिकी इकाइयाँ और मॉड्यूल बनाना","गतिविधियों और स्थानीय सर्वेक्षणों के माध्यम से पर्यावरण और स्वास्थ्य के बारे में सीखना","विज्ञान को विषयों के रूप में पढ़ना, जिसमें अमूर्तन और मात्रात्मक तर्क पर बल हो"],"explanationHi":"NCF 2005 उच्च प्राथमिक विज्ञान को परिचित अनुभव, हाथ से प्रौद्योगिकी, गतिविधियों और सर्वेक्षणों के निकट रखता है; अमूर्तन, मात्रात्मक तर्क और विषयगत प्रस्तुति माध्यमिक स्तर से शुरू होती है।"},
  {"id":"cdp-pedagogy-subjects-601","question":"Assertion (A): At the upper primary stage, scientific concepts should be arrived at mainly through activities and experiments. Reason (R): Children at this stage can learn science only by memorising definitions and laws.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"NCF 2005 wants concepts at this stage to come mainly from activities and experiments, so A is true. R contradicts this view; memorising definitions is what it argues against.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): उच्च प्राथमिक स्तर पर वैज्ञानिक संप्रत्यय मुख्यतः गतिविधियों और प्रयोगों से प्राप्त किए जाने चाहिए। कारण (R): इस स्तर के बच्चे विज्ञान केवल परिभाषाएँ और नियम रटकर ही सीख सकते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"NCF 2005 चाहता है कि इस स्तर पर संप्रत्यय मुख्यतः गतिविधियों और प्रयोगों से आएँ, इसलिए A सत्य है। R इस दृष्टि का खंडन करता है; परिभाषाएँ रटने का ही वह विरोध करता है।"},
  {"id":"cdp-pedagogy-subjects-602","question":"A Class 7 teacher wants students to understand pollination. Going by Edgar Dale's Cone of Experience, which option gives the most concrete experience?","options":["Watching a close-up documentary film on how bees and butterflies pollinate different flowers","Watching bees visit flowers in the school garden and examining the flowers with a hand lens","Studying a large labelled wall chart of the parts of a flower and pollination","Listening to the teacher's detailed explanation of pollination with examples"],"answer":1,"explanation":"Dale's Cone places direct, purposeful experience at the base (most concrete) and verbal symbols at the top (most abstract), with films and charts in between.","difficulty":"moderate","source":"CTET Paper 2 · state TETs · NVS","questionHi":"कक्षा 7 का एक शिक्षक चाहता है कि विद्यार्थी परागण को समझें। एडगर डेल के अनुभव शंकु (Cone of Experience) के अनुसार कौन-सा विकल्प सबसे मूर्त अनुभव देता है?","optionsHi":["इस पर निकट-दृश्य वृत्तचित्र देखना कि मधुमक्खियाँ और तितलियाँ विभिन्न फूलों का परागण कैसे करती हैं","विद्यालय के बगीचे में मधुमक्खियों को फूलों पर आते देखना और आवर्धक लेंस से फूलों की जाँच करना","फूल के भागों और परागण का बड़ा नामांकित दीवार चार्ट पढ़ना","परागण की शिक्षक की विस्तृत व्याख्या उदाहरणों सहित सुनना"],"explanationHi":"डेल का शंकु प्रत्यक्ष, उद्देश्यपूर्ण अनुभव को आधार पर (सबसे मूर्त) और शाब्दिक प्रतीकों को शीर्ष पर (सबसे अमूर्त) रखता है, और फिल्में तथा चार्ट बीच में आते हैं।"},
  {"id":"cdp-pedagogy-subjects-603","question":"In which of the following situations is a computer simulation more suitable than a real activity for Class 8 students?","options":["Finding the boiling point of water using a thermometer in the laboratory","Testing which classroom objects a bar magnet attracts","Showing how the positions of the planets change over several years","Observing the germination of gram seeds on wet cotton over a week"],"answer":2,"explanation":"Simulations are best for what cannot be observed directly in class because of scale, time or danger. Boiling, magnetism and germination can and should be experienced first-hand.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा 8 के विद्यार्थियों के लिए निम्नलिखित में से किस स्थिति में वास्तविक गतिविधि की तुलना में कंप्यूटर अनुकरण (सिमुलेशन) अधिक उपयुक्त है?","optionsHi":["प्रयोगशाला में थर्मामीटर से पानी का क्वथनांक ज्ञात करना","यह परखना कि छड़ चुंबक कक्षा की किन वस्तुओं को आकर्षित करता है","यह दिखाना कि कई वर्षों में ग्रहों की स्थितियाँ कैसे बदलती हैं","एक सप्ताह में गीली रुई पर चने के बीजों का अंकुरण देखना"],"explanationHi":"अनुकरण उन चीज़ों के लिए सबसे अच्छे हैं जिन्हें पैमाने, समय या खतरे के कारण कक्षा में सीधे नहीं देखा जा सकता। उबलना, चुंबकत्व और अंकुरण प्रत्यक्ष रूप से अनुभव किए जा सकते हैं और पहले किए जाने चाहिए।"},
  {"id":"cdp-pedagogy-subjects-604","question":"After rumours spread in a town that idols were 'drinking' milk, a science teacher shows how a liquid rises up through a thin tube and a lump of sugar, and asks students to explain the rumour. Which constitutional fundamental duty is she most directly promoting?","options":["To develop the scientific temper, humanism and the spirit of inquiry and reform","To protect and improve the natural environment including forests, lakes, rivers and wild life","To safeguard public property and to abjure violence","To value and preserve the rich heritage of our composite culture"],"answer":0,"explanation":"Article 51A(h) asks citizens to develop the scientific temper, humanism and the spirit of inquiry and reform. Explaining a 'miracle' by capillary action does exactly this.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"किसी नगर में अफवाह फैलने के बाद कि मूर्तियाँ दूध ‘पी’ रही हैं, एक विज्ञान शिक्षिका दिखाती है कि कैसे कोई द्रव पतली नली और चीनी की डली से ऊपर चढ़ता है, और विद्यार्थियों से अफवाह की व्याख्या करने को कहती है। वह सबसे सीधे किस संवैधानिक मौलिक कर्तव्य को बढ़ावा दे रही है?","optionsHi":["वैज्ञानिक दृष्टिकोण, मानववाद तथा ज्ञानार्जन और सुधार की भावना का विकास करना","वनों, झीलों, नदियों और वन्य जीवों सहित प्राकृतिक पर्यावरण की रक्षा और संवर्धन करना","सार्वजनिक संपत्ति को सुरक्षित रखना और हिंसा से दूर रहना","हमारी सामासिक संस्कृति की गौरवशाली परंपरा का महत्त्व समझना और उसका परिरक्षण करना"],"explanationHi":"अनुच्छेद 51A(h) नागरिकों से वैज्ञानिक दृष्टिकोण, मानववाद तथा ज्ञानार्जन और सुधार की भावना विकसित करने को कहता है। किसी ‘चमत्कार’ की केशिकत्व क्रिया से व्याख्या करना ठीक यही करता है।"},
  {"id":"cdp-pedagogy-subjects-605","question":"In mixed groups during science practicals, a teacher notices that boys always handle the apparatus while girls only record the readings. The most suitable action is to:","options":["Leave the groups as they are, since students have chosen their own roles freely","Form separate groups for boys and girls so that the girls also get a chance to handle apparatus","Ask the girls to be more confident, without changing anything else in the groups","Assign rotating roles so that every student handles apparatus, records and reports"],"answer":3,"explanation":"Rotating roles ensures equal hands-on experience and challenges gender stereotypes within the group. Leaving it alone or blaming the girls preserves the inequity.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs","questionHi":"विज्ञान प्रायोगिक कार्य के दौरान मिश्रित समूहों में एक शिक्षिका देखती है कि लड़के हमेशा उपकरण सँभालते हैं जबकि लड़कियाँ केवल पाठ्यांक दर्ज करती हैं। सबसे उपयुक्त कार्रवाई है:","optionsHi":["समूहों को जैसे हैं वैसे रहने देना, क्योंकि विद्यार्थियों ने अपनी भूमिकाएँ स्वतंत्र रूप से चुनी हैं","लड़कों और लड़कियों के अलग-अलग समूह बनाना ताकि लड़कियों को भी उपकरण सँभालने का अवसर मिले","लड़कियों से अधिक आत्मविश्वासी होने को कहना, समूहों में और कुछ बदले बिना","भूमिकाएँ बदल-बदलकर देना ताकि प्रत्येक विद्यार्थी उपकरण सँभाले, आँकड़े दर्ज करे और प्रतिवेदन दे"],"explanationHi":"भूमिकाओं का चक्रीकरण समान प्रायोगिक अनुभव सुनिश्चित करता है और समूह के भीतर लैंगिक रूढ़ियों को चुनौती देता है। उसे जैसा है वैसा छोड़ देना या लड़कियों को दोष देना असमानता को बनाए रखता है।"},
  {"id":"cdp-pedagogy-subjects-606","question":"In a school in a tribal district, Class 6 students know many local plants by their Gondi names but not by their textbook names. The teacher's best approach is to:","options":["Insist that students use only the textbook names in class, to avoid confusion","Use the local names as a starting point and link them to the textbook names","Avoid discussing local plants, since they are not part of the prescribed syllabus","Teach only the scientific names, since they are the same all over the world"],"answer":1,"explanation":"NCF 2005 treats the learner's language and local knowledge as resources; connecting known names to new terms builds understanding and respect. Excluding them alienates learners.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"एक जनजातीय ज़िले के विद्यालय में कक्षा 6 के विद्यार्थी अनेक स्थानीय पौधों को उनके गोंडी नामों से जानते हैं पर पाठ्यपुस्तक के नामों से नहीं। शिक्षक का सबसे अच्छा उपाय है:","optionsHi":["भ्रम से बचने के लिए आग्रह करना कि विद्यार्थी कक्षा में केवल पाठ्यपुस्तक के नामों का प्रयोग करें","स्थानीय नामों को आरंभ-बिंदु बनाना और उन्हें पाठ्यपुस्तक के नामों से जोड़ना","स्थानीय पौधों की चर्चा से बचना, क्योंकि वे निर्धारित पाठ्यक्रम का हिस्सा नहीं हैं","केवल वैज्ञानिक नाम पढ़ाना, क्योंकि वे पूरे विश्व में एक जैसे हैं"],"explanationHi":"NCF 2005 शिक्षार्थी की भाषा और स्थानीय ज्ञान को संसाधन मानता है; जाने-पहचाने नामों को नए शब्दों से जोड़ना समझ और सम्मान दोनों बनाता है। उन्हें बाहर करना शिक्षार्थियों को पराया कर देता है।"},
  {"id":"cdp-pedagogy-subjects-607","question":"Which question asked in a Class 7 lesson on food preservation is the most divergent?","options":["At what temperature does a household refrigerator usually keep food fresh?","What is the chemical name of the common salt that is used to preserve fish?","How many ways could a village family without electricity keep milk from spoiling?","Which preservative is commonly used in pickles made at home?"],"answer":2,"explanation":"A divergent question admits many valid answers and invites creative thinking; the others have a single expected answer (convergent).","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"खाद्य परिरक्षण पर कक्षा 7 के पाठ में पूछा गया कौन-सा प्रश्न सबसे अपसारी है?","optionsHi":["घरेलू रेफ्रिजरेटर सामान्यतः किस तापमान पर भोजन को ताज़ा रखता है?","मछली को परिरक्षित करने में प्रयुक्त होने वाले सामान्य नमक का रासायनिक नाम क्या है?","बिजली के बिना कोई गाँव का परिवार दूध को खराब होने से कितने तरीकों से बचा सकता है?","घर पर बने अचार में सामान्यतः कौन-सा परिरक्षक प्रयोग होता है?"],"explanationHi":"अपसारी प्रश्न के अनेक वैध उत्तर हो सकते हैं और वह रचनात्मक चिंतन को आमंत्रित करता है; अन्य का एक ही अपेक्षित उत्तर है (अभिसारी)।"},
  {"id":"cdp-pedagogy-subjects-608","question":"A teacher asks, 'Why do we sweat more on a hot day?' and immediately calls on the first student whose hand goes up. Classroom research suggests she would get more thoughtful answers from more students if she:","options":["Asked only the brightest students, who are likely to answer correctly","Repeated the question quickly in different words","Gave the answer herself to save time","Waited a few seconds after asking before calling on anyone"],"answer":3,"explanation":"Increasing wait time to three to five seconds leads to longer, better-reasoned answers and more students taking part. Instant calling rewards only the fastest.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs","questionHi":"एक शिक्षिका पूछती है, ‘गर्म दिन में हमें अधिक पसीना क्यों आता है?’ और तुरंत पहला हाथ उठाने वाले विद्यार्थी को बुला लेती है। कक्षा-शोध सुझाता है कि उसे अधिक विद्यार्थियों से अधिक विचारपूर्ण उत्तर मिलते यदि वह:","optionsHi":["केवल सबसे तेज़ विद्यार्थियों से पूछती, जिनके सही उत्तर देने की संभावना है","प्रश्न को अलग शब्दों में जल्दी से दोहराती","समय बचाने के लिए स्वयं उत्तर दे देती","प्रश्न पूछने के बाद किसी को बुलाने से पहले कुछ सेकंड प्रतीक्षा करती"],"explanationHi":"प्रतीक्षा-समय को तीन से पाँच सेकंड तक बढ़ाने से लंबे, बेहतर तर्कयुक्त उत्तर आते हैं और अधिक विद्यार्थी भाग लेते हैं। तुरंत बुलाना केवल सबसे तेज़ को पुरस्कृत करता है।"},
  {"id":"cdp-pedagogy-subjects-609","question":"A teacher asks students to draw a concept map linking 'photosynthesis, chlorophyll, sunlight, glucose, respiration, energy'. Compared with an MCQ test on the same topic, the main advantage of the concept map is that it:","options":["Is quicker and easier to mark objectively, using a fixed answer key for all","Reveals how the student links the ideas, including missing or wrong links","Covers more facts in less time than an MCQ test can","Avoids the need for any further assessment of the topic later"],"answer":1,"explanation":"A concept map makes the structure of a learner's understanding visible: which concepts are linked, how, and where the links are faulty. MCQs show only isolated right or wrong answers.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"एक शिक्षिका विद्यार्थियों से ‘प्रकाश संश्लेषण, क्लोरोफिल, सूर्य का प्रकाश, ग्लूकोज़, श्वसन, ऊर्जा’ को जोड़ता हुआ संप्रत्यय मानचित्र बनाने को कहती है। उसी विषय पर MCQ परीक्षा की तुलना में संप्रत्यय मानचित्र का मुख्य लाभ यह है कि वह:","optionsHi":["सबके लिए एक निश्चित उत्तर कुंजी से वस्तुनिष्ठ रूप से जाँचने में तेज़ और आसान है","प्रकट करता है कि विद्यार्थी विचारों को कैसे जोड़ता है, छूटे हुए या गलत संबंधों सहित","MCQ परीक्षा की तुलना में कम समय में अधिक तथ्यों को समेटता है","बाद में उस विषय के किसी और आकलन की आवश्यकता समाप्त कर देता है"],"explanationHi":"संप्रत्यय मानचित्र शिक्षार्थी की समझ की संरचना को दृश्य बनाता है: कौन-से संप्रत्यय जुड़े हैं, कैसे, और संबंध कहाँ दोषपूर्ण हैं। MCQ केवल अलग-अलग सही या गलत उत्तर दिखाते हैं।"},
  {"id":"cdp-pedagogy-subjects-610","question":"Throughout the year, a Class 8 student keeps her observation records, project reports, drawings and reflections on what she learned in a file, which the teacher reviews periodically. This assessment tool is a:","options":["Portfolio, which shows progress over time","Anecdotal record, which notes significant incidents","Rating scale, which grades a single performance","Achievement test, which measures learning at the end"],"answer":0,"explanation":"A portfolio is a purposeful collection of a learner's work over time, which shows growth and allows reflection. An anecdotal record is the teacher's note of specific incidents.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"पूरे वर्ष कक्षा 8 की एक विद्यार्थी अपने अवलोकन अभिलेख, परियोजना प्रतिवेदन, चित्र और जो उसने सीखा उस पर चिंतन एक फ़ाइल में रखती है, जिसकी शिक्षक समय-समय पर समीक्षा करता है। यह आकलन साधन है:","optionsHi":["पोर्टफोलियो, जो समय के साथ प्रगति दिखाता है","उपाख्यानात्मक अभिलेख, जो महत्त्वपूर्ण घटनाओं को दर्ज करता है","निर्धारण मापनी (रेटिंग स्केल), जो किसी एक प्रदर्शन का मूल्यांकन करती है","उपलब्धि परीक्षण, जो अंत में अधिगम को मापता है"],"explanationHi":"पोर्टफोलियो समय के साथ शिक्षार्थी के कार्य का उद्देश्यपूर्ण संग्रह है, जो विकास दिखाता है और चिंतन का अवसर देता है। उपाख्यानात्मक अभिलेख विशिष्ट घटनाओं का शिक्षक का नोट है।"},
  {"id":"cdp-pedagogy-subjects-611","question":"Before Class 8 students begin a project on water quality in their locality, the teacher shares a rubric listing criteria (data collection, analysis, presentation) and what each level of performance looks like. The main benefit of sharing it in advance is that:","options":["The teacher can then award marks without having to read the reports in detail","Students will all get the same marks if they follow it","Students know what good work looks like and can check their own progress","It removes the need to give any feedback after the project is over"],"answer":2,"explanation":"A rubric shared in advance makes expectations transparent and supports self-assessment, making it a tool for learning and not just grading.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा 8 के विद्यार्थियों के अपने क्षेत्र में जल की गुणवत्ता पर परियोजना शुरू करने से पहले शिक्षिका एक रूब्रिक साझा करती है, जिसमें मानदंड (आँकड़ा संग्रह, विश्लेषण, प्रस्तुति) और प्रदर्शन के प्रत्येक स्तर का स्वरूप सूचीबद्ध है। इसे पहले साझा करने का मुख्य लाभ यह है कि:","optionsHi":["शिक्षिका प्रतिवेदन विस्तार से पढ़े बिना अंक दे सकती है","यदि विद्यार्थी इसका पालन करें तो सबको समान अंक मिलेंगे","विद्यार्थी जानते हैं कि अच्छा कार्य कैसा दिखता है और अपनी प्रगति स्वयं जाँच सकते हैं","परियोजना समाप्त होने के बाद कोई प्रतिपुष्टि देने की आवश्यकता समाप्त हो जाती है"],"explanationHi":"पहले से साझा किया गया रूब्रिक अपेक्षाओं को पारदर्शी बनाता है और स्व-आकलन में सहायक होता है, जिससे वह केवल अंक देने का नहीं बल्कि सीखने का साधन बनता है।"},
  {"id":"cdp-pedagogy-subjects-612","question":"At the end of each science period, a teacher asks students to write one thing they understood and one question they still have on a slip of paper, and uses the slips to plan the next lesson. This practice is best described as:","options":["Assessment of learning, since it comes at the end of the period","Summative assessment, since it covers the whole of the day's lesson","Norm-referenced testing, since slips are compared across students","Assessment for learning, since it guides the next steps of teaching"],"answer":3,"explanation":"Exit slips give ongoing feedback used to adjust teaching, which is formative assessment (assessment for learning). Its timing at the end of the period does not make it summative.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"प्रत्येक विज्ञान पीरियड के अंत में एक शिक्षक विद्यार्थियों से पर्ची पर एक बात जो उन्होंने समझी और एक प्रश्न जो अब भी बाकी है, लिखने को कहता है, और पर्चियों का उपयोग अगले पाठ की योजना बनाने में करता है। इस अभ्यास का सबसे अच्छा वर्णन है:","optionsHi":["अधिगम का आकलन, क्योंकि यह पीरियड के अंत में आता है","योगात्मक आकलन, क्योंकि यह दिन के पूरे पाठ को समेटता है","मानक-संदर्भित परीक्षण, क्योंकि पर्चियों की विद्यार्थियों में तुलना होती है","अधिगम के लिए आकलन, क्योंकि यह शिक्षण के अगले कदमों का मार्गदर्शन करता है"],"explanationHi":"निकास-पर्चियाँ सतत प्रतिपुष्टि देती हैं जिसका उपयोग शिक्षण को समायोजित करने में होता है, यही रचनात्मक आकलन (अधिगम के लिए आकलन) है। पीरियड के अंत में होने से यह योगात्मक नहीं हो जाता।"},
  {"id":"cdp-pedagogy-subjects-613","question":"Sana has measured a bean plant every day: it has grown about 1 cm each day and is now 9 cm tall. She says, 'It will be about 15 cm tall six days from now.' Which process skill is she using?","options":["Inferring","Predicting","Classifying","Hypothesising"],"answer":1,"explanation":"Forecasting a future observation from a pattern in data is predicting. She offers no explanation of why the plant grows, so it is not a hypothesis.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"सना ने हर दिन एक सेम के पौधे को नापा है: वह लगभग 1 cm प्रतिदिन बढ़ा है और अब 9 cm ऊँचा है। वह कहती है, ‘छह दिन बाद वह लगभग 15 cm ऊँचा होगा।’ वह कौन-सा प्रक्रिया कौशल प्रयोग कर रही है?","optionsHi":["अनुमान लगाना (Inferring)","पूर्वानुमान लगाना (Predicting)","वर्गीकरण करना","परिकल्पना बनाना"],"explanationHi":"आँकड़ों में किसी पैटर्न से भविष्य के अवलोकन का अनुमान लगाना पूर्वानुमान है। वह यह कारण नहीं देती कि पौधा क्यों बढ़ता है, इसलिए यह परिकल्पना नहीं है।"},
  {"id":"cdp-pedagogy-subjects-614","question":"After an experiment on the solubility of salt at different temperatures, a group presents its results as a bar graph and explains it to the class. Which process skill is mainly being developed?","options":["Communicating","Controlling variables","Measuring","Observing"],"answer":0,"explanation":"Presenting data through graphs, tables and explanations so that others can understand it is communicating. Measuring and observing came earlier, while collecting the data.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"अलग-अलग तापमान पर नमक की विलेयता के प्रयोग के बाद एक समूह अपने परिणाम दंड आलेख के रूप में प्रस्तुत करता है और कक्षा को समझाता है। मुख्यतः कौन-सा प्रक्रिया कौशल विकसित हो रहा है?","optionsHi":["संप्रेषण करना","चरों को नियंत्रित करना","मापना","अवलोकन करना"],"explanationHi":"आँकड़ों को आलेखों, सारणियों और व्याख्याओं के माध्यम से प्रस्तुत करना ताकि दूसरे उसे समझ सकें, संप्रेषण है। मापना और अवलोकन करना आँकड़े एकत्र करते समय पहले आ चुके थे।"},
  {"id":"cdp-pedagogy-subjects-615","question":"A teacher presents legends about ancient flying machines as established scientific fact, without any evidence. From the point of view of the NCF 2005 science criteria, the main problem is that:","options":["It violates historical validity, because history should not be taught in science","It violates cognitive validity, because the legends are too complex for children","It violates content validity, because unsupported claims are presented as correct science","It violates environmental validity, because the flying machines are not part of the local environment"],"answer":2,"explanation":"Content validity requires that what is taught as science be correct and significant. Historical validity welcomes the real history of science, but presenting unverified claims as fact distorts both history and science.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"एक शिक्षक प्राचीन उड़ने वाली मशीनों की दंतकथाओं को बिना किसी साक्ष्य के स्थापित वैज्ञानिक तथ्य के रूप में प्रस्तुत करता है। NCF 2005 के विज्ञान मानदंडों की दृष्टि से मुख्य समस्या यह है कि:","optionsHi":["यह ऐतिहासिक वैधता का उल्लंघन है, क्योंकि विज्ञान में इतिहास नहीं पढ़ाना चाहिए","यह संज्ञानात्मक वैधता का उल्लंघन है, क्योंकि दंतकथाएँ बच्चों के लिए बहुत जटिल हैं","यह विषयवस्तु वैधता का उल्लंघन है, क्योंकि असमर्थित दावे सही विज्ञान के रूप में प्रस्तुत किए जा रहे हैं","यह पर्यावरणीय वैधता का उल्लंघन है, क्योंकि उड़ने वाली मशीनें स्थानीय पर्यावरण का हिस्सा नहीं हैं"],"explanationHi":"विषयवस्तु वैधता की माँग है कि विज्ञान के रूप में जो पढ़ाया जाए वह सही और महत्त्वपूर्ण हो। ऐतिहासिक वैधता विज्ञान के वास्तविक इतिहास का स्वागत करती है, पर असत्यापित दावों को तथ्य के रूप में प्रस्तुत करना इतिहास और विज्ञान दोनों को विकृत करता है।"},
  {"id":"cdp-pedagogy-subjects-616","question":"Which of the following fall under environmental validity as described in the NCF 2005 position paper on science? 1. Placing science in the wider context of the learner's environment, local and global. 2. Helping learners appreciate issues at the interface of science, technology and society. 3. Equipping learners with knowledge and skills to enter the world of work. 4. Promoting honesty and objectivity in the conduct of science.","options":["1 and 2 only","1, 2 and 3 only","1, 2, 3 and 4","2, 3 and 4 only"],"answer":1,"explanation":"Environmental validity covers the learner's environment, science-technology-society issues and preparation for the world of work. Honesty and objectivity come under ethical validity.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"विज्ञान पर NCF 2005 के स्थिति-पत्र में वर्णित पर्यावरणीय वैधता के अंतर्गत निम्नलिखित में से कौन-से आते हैं? 1. विज्ञान को शिक्षार्थी के व्यापक, स्थानीय और वैश्विक पर्यावरण के संदर्भ में रखना। 2. शिक्षार्थियों को विज्ञान, प्रौद्योगिकी और समाज के अंतरापृष्ठ के मुद्दों की सराहना करने में सहायता करना। 3. शिक्षार्थियों को कार्य-जगत में प्रवेश के लिए ज्ञान और कौशल से लैस करना। 4. विज्ञान के संचालन में ईमानदारी और वस्तुनिष्ठता को बढ़ावा देना।","optionsHi":["केवल 1 और 2","केवल 1, 2 और 3","1, 2, 3 और 4","केवल 2, 3 और 4"],"explanationHi":"पर्यावरणीय वैधता में शिक्षार्थी का पर्यावरण, विज्ञान-प्रौद्योगिकी-समाज के मुद्दे और कार्य-जगत की तैयारी आते हैं। ईमानदारी और वस्तुनिष्ठता नैतिक वैधता के अंतर्गत आती हैं।"},
  {"id":"cdp-pedagogy-subjects-617","question":"A Class 6 chapter on food from plants introduces photosynthesis using terms such as 'thylakoid', 'light reactions' and 'Calvin cycle', all stated correctly. Judged by the NCF 2005 criteria, the chapter is weakest in:","options":["Content validity","Historical validity","Ethical validity","Cognitive validity"],"answer":3,"explanation":"The content is correct, so content validity is met, but the terms and abstraction are beyond the reach of eleven-year-olds, which violates cognitive validity.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs","questionHi":"पौधों से प्राप्त भोजन पर कक्षा 6 का एक अध्याय ‘थाइलेकॉइड’, ‘प्रकाश अभिक्रियाएँ’ और ‘केल्विन चक्र’ जैसे शब्दों के साथ प्रकाश संश्लेषण का परिचय देता है, जो सभी सही कहे गए हैं। NCF 2005 के मानदंडों से आँकने पर अध्याय सबसे कमज़ोर किसमें है?","optionsHi":["विषयवस्तु वैधता","ऐतिहासिक वैधता","नैतिक वैधता","संज्ञानात्मक वैधता"],"explanationHi":"विषयवस्तु सही है, इसलिए विषयवस्तु वैधता पूरी होती है, पर शब्द और अमूर्तन ग्यारह वर्ष के बच्चों की पहुँच से बाहर हैं, जो संज्ञानात्मक वैधता का उल्लंघन है।"},
  {"id":"cdp-pedagogy-subjects-618","question":"A science textbook chapter gives correct, well-organised facts about magnets, but contains no activities, no open questions and no tasks in which students observe or test anything themselves. It is weakest in:","options":["Process validity","Content validity","Cognitive validity","Ethical validity"],"answer":0,"explanation":"Process validity requires that learners engage in the methods and processes of science, such as observing, testing and reasoning from evidence. Correct facts alone satisfy content validity only.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS","questionHi":"विज्ञान की एक पाठ्यपुस्तक का अध्याय चुंबकों के बारे में सही, सुव्यवस्थित तथ्य देता है, पर उसमें कोई गतिविधि, कोई खुले प्रश्न और कोई ऐसा कार्य नहीं है जिसमें विद्यार्थी स्वयं कुछ अवलोकन या परीक्षण करें। यह सबसे कमज़ोर किसमें है?","optionsHi":["प्रक्रिया वैधता","विषयवस्तु वैधता","संज्ञानात्मक वैधता","नैतिक वैधता"],"explanationHi":"प्रक्रिया वैधता की माँग है कि शिक्षार्थी विज्ञान की विधियों और प्रक्रियाओं, जैसे अवलोकन, परीक्षण और साक्ष्य से तर्क करना, में संलग्न हों। केवल सही तथ्य विषयवस्तु वैधता को ही पूरा करते हैं।"},
  {"id":"cdp-pedagogy-subjects-619","question":"In a Class 7 class there is a student with low vision. For a lesson on the structure of a flower, the teacher's most suitable arrangement is:","options":["Excusing her from the lesson and giving her printed notes to read later at home","Providing large real flowers and a tactile model to explore, with clear oral description","Seating her at the back so that she does not disturb others who can see the board","Giving her the same small textbook diagram as everyone else, so that all are treated equally"],"answer":1,"explanation":"Inclusive science uses multi-sensory resources such as real specimens, tactile models and verbal description so that every learner takes part in the same lesson. Excusing or ignoring her denies her the learning.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा 7 की एक कक्षा में कम दृष्टि वाली एक विद्यार्थी है। फूल की संरचना के पाठ के लिए शिक्षक की सबसे उपयुक्त व्यवस्था है:","optionsHi":["उसे पाठ से छूट देना और बाद में घर पर पढ़ने के लिए छपे नोट्स देना","उसे खोजने के लिए बड़े असली फूल और स्पर्शीय मॉडल देना, साथ में स्पष्ट मौखिक वर्णन","उसे पीछे बैठाना ताकि वह बोर्ड देखने वाले अन्य बच्चों को बाधित न करे","उसे वही छोटा पाठ्यपुस्तक का आरेख देना जो सबको मिला है, ताकि सबके साथ समान व्यवहार हो"],"explanationHi":"समावेशी विज्ञान बहु-संवेदी संसाधनों, जैसे असली नमूनों, स्पर्शीय मॉडलों और मौखिक वर्णन का प्रयोग करता है ताकि हर शिक्षार्थी उसी पाठ में भाग ले सके। छूट देना या अनदेखा करना उसे सीखने से वंचित करता है।"},
  {"id":"cdp-pedagogy-subjects-620","question":"Consider the following statements about the science textbook in the light of NCF 2005. 1. It is one of several resources and not the only source of knowledge. 2. A teacher should never go beyond the textbook in class. 3. Questions in it should include some that have no single 'right' answer. 4. Its activities should be done, not just read about.","options":["1 and 2 only","2 and 4 only","1, 3 and 4 only","1, 2, 3 and 4"],"answer":2,"explanation":"NCF 2005 discourages treating the textbook as the sole authority and encourages open-ended questions and doing the activities. Statement 2 contradicts its call to link learning to life outside school.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"NCF 2005 के आलोक में विज्ञान की पाठ्यपुस्तक के बारे में निम्नलिखित कथनों पर विचार कीजिए। 1. यह कई संसाधनों में से एक है, ज्ञान का एकमात्र स्रोत नहीं। 2. शिक्षक को कक्षा में कभी पाठ्यपुस्तक से आगे नहीं जाना चाहिए। 3. इसके प्रश्नों में कुछ ऐसे होने चाहिए जिनका कोई एक ‘सही’ उत्तर न हो। 4. इसकी गतिविधियाँ की जानी चाहिए, केवल उनके बारे में पढ़ा नहीं जाना चाहिए।","optionsHi":["केवल 1 और 2","केवल 2 और 4","केवल 1, 3 और 4","1, 2, 3 और 4"],"explanationHi":"NCF 2005 पाठ्यपुस्तक को एकमात्र प्राधिकार मानने को हतोत्साहित करता है और खुले प्रश्नों तथा गतिविधियाँ करने को प्रोत्साहित करता है। कथन 2 सीखने को विद्यालय के बाहर के जीवन से जोड़ने के उसके आह्वान का खंडन करता है।"},
  {"id":"cdp-pedagogy-subjects-621","question":"A Class 8 teacher finds that her students can recite the definition of friction but cannot say why a matchstick lights only when rubbed on the side of the box. This most clearly shows that:","options":["The students need to memorise the definition more thoroughly before tests","The topic of friction is too difficult for Class 8","The students have not paid attention in class","Learning was rote and had not been connected to everyday experience"],"answer":3,"explanation":"Being able to recite a definition but not apply it to a familiar situation is the mark of rote learning. More memorising will not help; linking concepts to experience will.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs","questionHi":"कक्षा 8 की एक शिक्षिका पाती है कि उसके विद्यार्थी घर्षण की परिभाषा सुना सकते हैं पर यह नहीं बता सकते कि माचिस की तीली केवल डिब्बे के किनारे पर रगड़ने से ही क्यों जलती है। यह सबसे स्पष्ट रूप से दर्शाता है कि:","optionsHi":["विद्यार्थियों को परीक्षा से पहले परिभाषा और अच्छी तरह रटनी चाहिए","घर्षण का विषय कक्षा 8 के लिए बहुत कठिन है","विद्यार्थियों ने कक्षा में ध्यान नहीं दिया है","अधिगम रटंत था और उसे दैनिक अनुभव से नहीं जोड़ा गया था"],"explanationHi":"परिभाषा सुना पाना पर उसे किसी परिचित स्थिति में लागू न कर पाना रटंत अधिगम का लक्षण है। और रटने से मदद नहीं मिलेगी; संप्रत्ययों को अनुभव से जोड़ने से मिलेगी।"},
  {"id":"cdp-pedagogy-subjects-622","question":"In a lesson on magnets, a student asks, 'Why do two north poles push each other away?' The teacher replies, 'That is just how it is; it will come in the exam.' The main weakness of this reply is that it:","options":["Encourages accepting claims on authority and discourages students' curiosity","Gives the student too much information at once, so the main idea is lost","Is too difficult for the student to understand at this stage of learning","Shows that the teacher relied only on the textbook rather than on her own notes"],"answer":0,"explanation":"Science teaching should nurture curiosity and reasoning from evidence. Answering on authority teaches students that questions are unwelcome; the teacher could instead invite them to explore magnets and find patterns.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"चुंबकों के पाठ में एक विद्यार्थी पूछता है, ‘दो उत्तरी ध्रुव एक-दूसरे को क्यों दूर धकेलते हैं?’ शिक्षक उत्तर देता है, ‘बस ऐसा ही होता है; यह परीक्षा में आएगा।’ इस उत्तर की मुख्य कमज़ोरी यह है कि यह:","optionsHi":["अधिकार के आधार पर दावों को स्वीकार करने को प्रोत्साहित करता है और विद्यार्थियों की जिज्ञासा को हतोत्साहित करता है","विद्यार्थी को एक साथ बहुत अधिक जानकारी देता है, जिससे मुख्य विचार खो जाता है","अधिगम की इस अवस्था में विद्यार्थी के समझने के लिए बहुत कठिन है","दर्शाता है कि शिक्षक केवल पाठ्यपुस्तक पर निर्भर रहा, अपने नोट्स पर नहीं"],"explanationHi":"विज्ञान शिक्षण को जिज्ञासा और साक्ष्य से तर्क को पोषित करना चाहिए। अधिकार के आधार पर उत्तर देना विद्यार्थियों को सिखाता है कि प्रश्नों का स्वागत नहीं है; शिक्षक इसके बजाय उन्हें चुंबकों की खोजबीन करने और पैटर्न खोजने के लिए आमंत्रित कर सकता था।"},
  {"id":"cdp-pedagogy-subjects-623","question":"A teacher in a Class 8 class of 60 students says she cannot do any activities because the class is too big and there is no laboratory. Which response best addresses the problem?","options":["Teaching only through lectures, since activities are impossible in large classes","Doing all activities as teacher demonstrations at the front, with no student involvement","Organising small groups with low-cost materials and clear roles within each group","Asking only a few students to do the activities while others watch"],"answer":2,"explanation":"Group work with low-cost materials and clear roles makes activity-based learning possible even in large classes without a laboratory. Lectures or demonstrations alone leave most students passive.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा 8 की 60 विद्यार्थियों वाली एक कक्षा में शिक्षिका कहती है कि वह कोई गतिविधि नहीं करा सकती क्योंकि कक्षा बहुत बड़ी है और कोई प्रयोगशाला नहीं है। कौन-सी प्रतिक्रिया समस्या को सबसे अच्छी तरह संबोधित करती है?","optionsHi":["केवल व्याख्यान से पढ़ाना, क्योंकि बड़ी कक्षाओं में गतिविधियाँ असंभव हैं","सभी गतिविधियाँ सामने शिक्षक प्रदर्शन के रूप में करना, विद्यार्थियों की भागीदारी के बिना","कम लागत की सामग्री के साथ छोटे समूह बनाना और प्रत्येक समूह में स्पष्ट भूमिकाएँ तय करना","गतिविधियाँ केवल कुछ विद्यार्थियों से करवाना जबकि बाकी देखते रहें"],"explanationHi":"कम लागत की सामग्री और स्पष्ट भूमिकाओं के साथ समूह कार्य प्रयोगशाला के बिना बड़ी कक्षाओं में भी गतिविधि-आधारित अधिगम को संभव बनाता है। अकेले व्याख्यान या प्रदर्शन अधिकांश विद्यार्थियों को निष्क्रिय छोड़ देते हैं।"},
  {"id":"cdp-pedagogy-subjects-624","question":"While teaching nutrition, a teacher asks students to find out what their families eat in a week, compare meals across households of different income, and discuss why some families cannot afford a balanced diet. Which NCF 2005 criteria does this activity serve most clearly?","options":["Cognitive validity and content validity","Historical validity and ethical validity","Process validity and historical validity","Environmental validity and ethical validity"],"answer":3,"explanation":"Relating nutrition to households and income places science in the learner's social environment (environmental validity), and discussing why some cannot afford food builds concern for others (ethical validity).","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"पोषण पढ़ाते समय एक शिक्षक विद्यार्थियों से पता लगाने को कहता है कि उनके परिवार सप्ताह भर में क्या खाते हैं, अलग-अलग आय वाले परिवारों के भोजन की तुलना करने को कहता है, और इस पर चर्चा करवाता है कि कुछ परिवार संतुलित आहार का खर्च क्यों नहीं उठा सकते। यह गतिविधि NCF 2005 के किन मानदंडों की सबसे स्पष्ट रूप से पूर्ति करती है?","optionsHi":["संज्ञानात्मक वैधता और विषयवस्तु वैधता","ऐतिहासिक वैधता और नैतिक वैधता","प्रक्रिया वैधता और ऐतिहासिक वैधता","पर्यावरणीय वैधता और नैतिक वैधता"],"explanationHi":"पोषण को परिवारों और आय से जोड़ना विज्ञान को शिक्षार्थी के सामाजिक पर्यावरण में रखता है (पर्यावरणीय वैधता), और इस पर चर्चा कि कुछ लोग भोजन का खर्च क्यों नहीं उठा सकते, दूसरों के प्रति चिंता पैदा करती है (नैतिक वैधता)।"},
  {"id":"cdp-pedagogy-subjects-625","question":"A Class VI teacher in Palghar wants to use Warli painting in a science unit on the water cycle. Which activity is a true example of art-integrated learning?","options":["Children colour a printed water-cycle diagram and decorate it with Warli-style borders","After the science period, children have a separate art period in which they copy a Warli painting","Children make a Warli-style mural of evaporation, condensation and rain, and explain each stage","The teacher shows a short video on Warli art at the end of the lesson as a reward"],"answer":2,"explanation":"In art-integrated learning the art form is the medium through which children explore and express the concept, and the explanation shows their understanding. Colouring a diagram, a separate art period or a video reward keeps art and concept apart.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"पालघर की कक्षा VI की एक शिक्षिका जल चक्र की विज्ञान इकाई में वारली चित्रकला का उपयोग करना चाहती है। कौन-सी गतिविधि कला-समेकित अधिगम का सच्चा उदाहरण है?","optionsHi":["बच्चे छपे हुए जल-चक्र आरेख में रंग भरते हैं और उसे वारली शैली की किनारियों से सजाते हैं","विज्ञान के पीरियड के बाद बच्चों का अलग कला पीरियड होता है जिसमें वे वारली चित्र की नकल करते हैं","बच्चे वाष्पन, संघनन और वर्षा का वारली शैली का भित्तिचित्र बनाते हैं और प्रत्येक चरण को समझाते हैं","शिक्षिका पाठ के अंत में पुरस्कार के रूप में वारली कला पर एक छोटा वीडियो दिखाती है"],"explanationHi":"कला-समेकित अधिगम में कला का रूप वह माध्यम है जिसके द्वारा बच्चे संप्रत्यय की खोज और अभिव्यक्ति करते हैं, और व्याख्या उनकी समझ दिखाती है। आरेख में रंग भरना, अलग कला पीरियड या वीडियो का पुरस्कार कला और संप्रत्यय को अलग रखते हैं।"},
  {"id":"cdp-pedagogy-subjects-626","question":"Consider the following statements about art-integrated learning (AIL): 1. Visual and performing arts are used as tools to learn concepts of other subjects. 2. It expects every child to produce artwork of professional quality. 3. Local and regional art forms of the children's area can be used. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"AIL values the process of learning through art and draws on local art traditions; it does not demand professional-quality products, so statement 2 is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कला-समेकित अधिगम (AIL) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. दृश्य और प्रदर्शन कलाओं का उपयोग अन्य विषयों के संप्रत्यय सीखने के साधनों के रूप में किया जाता है। 2. यह अपेक्षा करता है कि हर बच्चा व्यावसायिक गुणवत्ता की कलाकृति बनाए। 3. बच्चों के क्षेत्र की स्थानीय और क्षेत्रीय कला-रूपों का उपयोग किया जा सकता है। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"AIL कला के माध्यम से सीखने की प्रक्रिया को महत्त्व देता है और स्थानीय कला परंपराओं का उपयोग करता है; वह व्यावसायिक गुणवत्ता के उत्पादों की माँग नहीं करता, इसलिए कथन 2 असत्य है।"},
  {"id":"cdp-pedagogy-subjects-627","question":"Assertion (A): In art-integrated learning, children should be assessed mainly on how beautiful their final artwork looks. Reason (R): Art-integrated learning aims at experiential learning of concepts through art forms.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Since AIL is about learning concepts through art, assessment should look at the process, the child's understanding and expression, not only the beauty of the product. R is true and actually contradicts A.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): कला-समेकित अधिगम में बच्चों का आकलन मुख्यतः इस आधार पर होना चाहिए कि उनकी अंतिम कलाकृति कितनी सुंदर दिखती है। कारण (R): कला-समेकित अधिगम का उद्देश्य कला-रूपों के माध्यम से संप्रत्ययों का अनुभवजन्य अधिगम है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"चूँकि AIL कला के माध्यम से संप्रत्यय सीखने के बारे में है, आकलन में प्रक्रिया, बच्चे की समझ और अभिव्यक्ति को देखना चाहिए, केवल उत्पाद की सुंदरता को नहीं। R सत्य है और वास्तव में A का खंडन करता है।"},
  {"id":"cdp-pedagogy-subjects-628","question":"A Class VIII teacher organises a role play of a Constituent Assembly debate on official language, with groups representing different regions. What is the main learning this role play is designed to produce?","options":["Memorising the dialogues and speeches of famous leaders word for word for the test","Seeing the Constitution as shaped by negotiation, and viewing the issue from others' perspectives","Improving children's acting and speaking skills for the annual day function","Covering the chapter quickly and in an entertaining way, without the need for any discussion afterwards"],"answer":1,"explanation":"Drama in social science builds perspective-taking and shows that decisions came out of debate and compromise. Rote dialogue or performance alone misses this purpose.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VIII का एक शिक्षक राजभाषा पर संविधान सभा की बहस का भूमिका-अभिनय करवाता है, जिसमें समूह विभिन्न क्षेत्रों का प्रतिनिधित्व करते हैं। यह भूमिका-अभिनय मुख्यतः कौन-सा अधिगम उत्पन्न करने के लिए बनाया गया है?","optionsHi":["परीक्षा के लिए प्रसिद्ध नेताओं के संवाद और भाषण शब्दशः याद करना","संविधान को वार्ता से आकार लेते देखना, और मुद्दे को दूसरों के दृष्टिकोण से देखना","वार्षिकोत्सव के कार्यक्रम के लिए बच्चों का अभिनय और वक्तृत्व कौशल सुधारना","अध्याय को शीघ्रता से और मनोरंजक ढंग से पूरा करना, बाद में किसी चर्चा की आवश्यकता के बिना"],"explanationHi":"सामाजिक विज्ञान में नाटक दृष्टिकोण-ग्रहण की क्षमता बनाता है और दिखाता है कि निर्णय बहस और समझौते से निकले। रटे हुए संवाद या केवल प्रस्तुति इस उद्देश्य से चूक जाती है।"},
  {"id":"cdp-pedagogy-subjects-629","question":"A Class II child in Shimla draws the sun purple and the trees blue. Which response from the teacher is most appropriate?","options":["'The sun is yellow and trees are green. Please colour it again correctly.'","'Very nice' without looking closely, and move on to the next child","Display the drawing as an example of what not to do","'Tell me about your picture. Why did you choose purple for the sun?'"],"answer":3,"explanation":"Children's art is self-expression; inviting the child to talk about choices values creativity and builds language. Correcting colours to 'real' ones or empty praise both fail the child.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"शिमला की कक्षा II की एक बच्ची सूरज को बैंगनी और पेड़ों को नीला बनाती है। शिक्षक की कौन-सी प्रतिक्रिया सबसे उपयुक्त है?","optionsHi":["‘सूरज पीला होता है और पेड़ हरे होते हैं। कृपया इसे फिर से सही रंग दो।’","बिना ध्यान से देखे ‘बहुत अच्छा’ कहना, और अगले बच्चे पर चले जाना","चित्र को ‘क्या नहीं करना चाहिए’ के उदाहरण के रूप में प्रदर्शित करना","‘मुझे अपने चित्र के बारे में बताओ। तुमने सूरज के लिए बैंगनी क्यों चुना?’"],"explanationHi":"बच्चों की कला आत्म-अभिव्यक्ति है; बच्चे को अपने चुनावों के बारे में बोलने के लिए आमंत्रित करना रचनात्मकता को महत्त्व देता है और भाषा बनाता है। रंगों को ‘असली’ रंगों में सुधारना या खोखली प्रशंसा दोनों बच्चे को विफल करती हैं।"},
  {"id":"cdp-pedagogy-subjects-630","question":"A Class III teacher in Jorhat plays a Bihu song and asks children to clap its repeating beat, show the beat with shapes, and then invent and clap their own repeating patterns for classmates to continue. What is the most important learning in this activity?","options":["Learning the words of the Bihu song by heart so it can be sung in the assembly","Practising clapping in rhythm together for a cultural programme at the end of the term","Recognising, extending and creating patterns, a key maths idea, through a familiar art","Relaxing and energising children before the real maths lesson begins"],"answer":2,"explanation":"Here music is the medium for pattern recognition and generalisation, which is central to early mathematical thinking. Remembering lyrics or rehearsing for a programme is not the goal.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"जोरहाट में कक्षा III की एक शिक्षिका बिहू गीत बजाती है और बच्चों से उसकी दोहराई जाने वाली ताल पर ताली बजवाती है, ताल को आकृतियों से दिखवाती है, और फिर उनसे अपने दोहराए जाने वाले प्रतिरूप बनाने और ताली से बजाने को कहती है ताकि सहपाठी उन्हें आगे बढ़ाएँ। इस गतिविधि में सबसे महत्त्वपूर्ण अधिगम क्या है?","optionsHi":["बिहू गीत के बोल कंठस्थ करना ताकि उसे सभा में गाया जा सके","सत्र के अंत के सांस्कृतिक कार्यक्रम के लिए साथ मिलकर लय में ताली बजाने का अभ्यास करना","एक परिचित कला के माध्यम से प्रतिरूपों को पहचानना, बढ़ाना और रचना करना, जो गणित का एक प्रमुख विचार है","असली गणित का पाठ शुरू होने से पहले बच्चों को आराम देना और ऊर्जावान बनाना"],"explanationHi":"यहाँ संगीत प्रतिरूप पहचान और सामान्यीकरण का माध्यम है, जो आरंभिक गणितीय चिंतन का केंद्र है। गीत के बोल याद रखना या किसी कार्यक्रम की तैयारी करना लक्ष्य नहीं है।"},
  {"id":"cdp-pedagogy-subjects-631","question":"A Class IV teacher pins only the five 'best' drawings on the display board each week. What is the most valid criticism of this practice?","options":["It signals that most children's work is not valued; every child's work should be displayed","Five drawings are too few; the ten best drawings should be displayed each week instead","Drawings should not be displayed at all, as a busy board distracts children during lessons","The teacher should display her own drawings as a model for children to copy instead"],"answer":0,"explanation":"Displaying everyone's work builds belonging and confidence, which matters especially in art. Expanding the 'best' list keeps the same exclusion, and hiding all work loses the motivation display gives.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"कक्षा IV की एक शिक्षिका हर सप्ताह प्रदर्शन-पट पर केवल पाँच ‘सर्वश्रेष्ठ’ चित्र लगाती है। इस अभ्यास की सबसे वैध आलोचना क्या है?","optionsHi":["यह संकेत देता है कि अधिकांश बच्चों के काम को महत्त्व नहीं दिया जाता; हर बच्चे का काम प्रदर्शित होना चाहिए","पाँच चित्र बहुत कम हैं; इसके बजाय हर सप्ताह दस सर्वश्रेष्ठ चित्र प्रदर्शित होने चाहिए","चित्र बिल्कुल प्रदर्शित नहीं होने चाहिए, क्योंकि भरा हुआ पट पाठ के दौरान बच्चों का ध्यान भटकाता है","इसके बजाय शिक्षिका को अपने चित्र बच्चों के नकल करने के लिए आदर्श के रूप में प्रदर्शित करने चाहिए"],"explanationHi":"सबके काम का प्रदर्शन अपनत्व और आत्मविश्वास बनाता है, जो कला में विशेष रूप से मायने रखता है। ‘सर्वश्रेष्ठ’ सूची बढ़ाने से वही बहिष्कार बना रहता है, और सारा काम छिपा देने से प्रदर्शन से मिलने वाली प्रेरणा खो जाती है।"},
  {"id":"cdp-pedagogy-subjects-632","question":"A Class VII teacher in Madhubani district wants to integrate the local painting style into a lesson on line symmetry. Which task shows the deepest integration of art and mathematics?","options":["Children colour a photocopied Madhubani painting using the traditional colours","Children read a paragraph on the history of Madhubani painting and answer questions on it","Children design a Madhubani-style border with a set line of symmetry and test it with a mirror","Children copy any Madhubani painting freehand as homework and bring it to class"],"answer":2,"explanation":"Designing to a symmetry condition, testing it and explaining it requires the mathematical idea to shape the artwork. Colouring, copying or reading history do not engage the concept of symmetry.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"मधुबनी ज़िले का कक्षा VII का एक शिक्षक रेखा सममिति के पाठ में स्थानीय चित्रकला शैली को समेकित करना चाहता है। कौन-सा कार्य कला और गणित का सबसे गहरा समेकन दिखाता है?","optionsHi":["बच्चे फोटोकॉपी किए हुए मधुबनी चित्र में परंपरागत रंग भरते हैं","बच्चे मधुबनी चित्रकला के इतिहास पर एक अनुच्छेद पढ़ते हैं और उस पर प्रश्नों के उत्तर देते हैं","बच्चे निर्धारित सममिति रेखा वाली मधुबनी शैली की किनारी बनाते हैं और दर्पण से उसकी जाँच करते हैं","बच्चे गृहकार्य के रूप में कोई भी मधुबनी चित्र हाथ से नकल करके कक्षा में लाते हैं"],"explanationHi":"सममिति की शर्त के अनुसार रचना करना, उसकी जाँच करना और उसे समझाना यह माँग करता है कि गणितीय विचार कलाकृति को आकार दे। रंग भरना, नकल करना या इतिहास पढ़ना सममिति के संप्रत्यय को नहीं छूते।"},
  {"id":"cdp-pedagogy-subjects-633","question":"In a Class I craft period, the teacher shows a finished paper boat and has all children fold identical boats step by step after her. A teacher educator suggests a more open approach. Which suggestion best fits the spirit of art education in NCF?","options":["Give children paper and a few folds, let them invent their own floating objects, then test them","Continue the step-by-step copying, but award marks for the neatness and accuracy of each fold","Let only the children who can already fold neatly take part in the craft activity","Replace craft with drawing, since drawing is easier to teach to young children"],"answer":0,"explanation":"Art education aims at exploration, imagination and self-expression, not identical reproduction of a model. Testing their own designs also adds inquiry. Marking neatness or excluding children moves further away from this aim.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा I के शिल्प पीरियड में शिक्षिका एक बनी हुई कागज़ की नाव दिखाती है और सभी बच्चों से अपने पीछे-पीछे चरण-दर-चरण एक जैसी नावें मोड़वाती है। एक शिक्षक-प्रशिक्षक अधिक खुला उपागम सुझाता है। NCF में कला शिक्षा की भावना के सबसे अनुकूल सुझाव कौन-सा है?","optionsHi":["बच्चों को कागज़ और कुछ मोड़ देना, उन्हें अपनी तैरने वाली वस्तुएँ गढ़ने देना, फिर उन्हें परखना","चरण-दर-चरण नकल जारी रखना, पर हर मोड़ की सफाई और सटीकता के अंक देना","केवल उन बच्चों को शिल्प गतिविधि में भाग लेने देना जो पहले से साफ-सुथरा मोड़ना जानते हैं","शिल्प की जगह चित्रकला लाना, क्योंकि छोटे बच्चों को चित्रकला सिखाना आसान है"],"explanationHi":"कला शिक्षा का लक्ष्य अन्वेषण, कल्पना और आत्म-अभिव्यक्ति है, किसी नमूने का एक जैसा पुनरुत्पादन नहीं। अपने बनाए डिज़ाइनों को परखना जिज्ञासा-आधारित खोज भी जोड़ता है। सफाई के अंक देना या बच्चों को बाहर रखना इस उद्देश्य से और दूर ले जाता है।"},
  {"id":"cdp-pedagogy-subjects-634","question":"A Class VII class visits a milk cooperative in Anand. Back in school: P. children write what they noticed and discuss what surprised them; Q. the teacher helps them form the general idea of a cooperative and how it differs from a private dairy; R. children plan and run a small class cooperative stall. In Kolb's experiential learning cycle, P, Q and R are respectively:","options":["active experimentation, reflective observation, abstract conceptualisation","reflective observation, active experimentation, abstract conceptualisation","abstract conceptualisation, reflective observation, active experimentation","reflective observation, abstract conceptualisation, active experimentation"],"answer":3,"explanation":"Kolb's cycle runs: concrete experience (the visit), reflective observation (P), abstract conceptualisation (Q, forming the general idea), and active experimentation (R, trying it out).","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VII की एक कक्षा आणंद में एक दुग्ध सहकारी समिति का भ्रमण करती है। विद्यालय लौटकर: P. बच्चे लिखते हैं कि उन्होंने क्या देखा और किस बात ने उन्हें चकित किया, इस पर चर्चा करते हैं; Q. शिक्षक उन्हें सहकारी समिति का सामान्य विचार बनाने और यह कि वह निजी डेयरी से कैसे भिन्न है, इसमें मदद करता है; R. बच्चे एक छोटी कक्षा सहकारी दुकान की योजना बनाते हैं और चलाते हैं। कोल्ब के अनुभवजन्य अधिगम चक्र में P, Q और R क्रमशः हैं:","optionsHi":["सक्रिय प्रयोग, चिंतनशील अवलोकन, अमूर्त संप्रत्ययीकरण","चिंतनशील अवलोकन, सक्रिय प्रयोग, अमूर्त संप्रत्ययीकरण","अमूर्त संप्रत्ययीकरण, चिंतनशील अवलोकन, सक्रिय प्रयोग","चिंतनशील अवलोकन, अमूर्त संप्रत्ययीकरण, सक्रिय प्रयोग"],"explanationHi":"कोल्ब का चक्र इस प्रकार चलता है: मूर्त अनुभव (भ्रमण), चिंतनशील अवलोकन (P), अमूर्त संप्रत्ययीकरण (Q, सामान्य विचार बनाना), और सक्रिय प्रयोग (R, उसे आज़माना)।"},
  {"id":"cdp-pedagogy-subjects-635","question":"Assertion (A): Every hands-on activity in a classroom is an example of experiential learning. Reason (R): Experiential learning requires learners to reflect on their experience and draw meaning from it.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is false, but R is true","A is true, but R is false"],"answer":2,"explanation":"Doing an activity is not enough; without reflection and conceptualisation it remains 'activity for activity's sake'. R is true and shows why A is false.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): कक्षा में प्रत्येक प्रत्यक्ष गतिविधि अनुभवजन्य अधिगम का उदाहरण है। कारण (R): अनुभवजन्य अधिगम में शिक्षार्थियों से अपेक्षा होती है कि वे अपने अनुभव पर चिंतन करें और उससे अर्थ निकालें।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A असत्य है, परंतु R सत्य है","A सत्य है, परंतु R असत्य है"],"explanationHi":"गतिविधि करना पर्याप्त नहीं है; चिंतन और संप्रत्ययीकरण के बिना वह ‘गतिविधि के लिए गतिविधि’ ही रह जाती है। R सत्य है और दिखाता है कि A असत्य क्यों है।"},
  {"id":"cdp-pedagogy-subjects-636","question":"Consider the following statements about Edgar Dale's Cone of Experience: 1. Direct, purposeful experiences form its base and verbal symbols are at its top. 2. It provides research-proven percentages showing that learners remember 10% of what they read and 90% of what they do. 3. Dale did not claim that abstract experiences are useless; he saw the cone as moving between concrete and abstract as learners need. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 and 3 only"],"answer":3,"explanation":"The retention percentages often printed with the cone were added later by others and are not part of Dale's work or backed by his research, so statement 2 is false. Statements 1 and 3 describe the cone correctly.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"एडगर डेल के अनुभव शंकु (Cone of Experience) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. प्रत्यक्ष, उद्देश्यपूर्ण अनुभव इसका आधार बनाते हैं और शाब्दिक प्रतीक इसके शीर्ष पर हैं। 2. यह शोध-प्रमाणित प्रतिशत देता है जो दर्शाते हैं कि शिक्षार्थी जो पढ़ते हैं उसका 10% और जो करते हैं उसका 90% याद रखते हैं। 3. डेल ने यह दावा नहीं किया कि अमूर्त अनुभव बेकार हैं; वे शंकु को शिक्षार्थियों की आवश्यकता के अनुसार मूर्त और अमूर्त के बीच गतिमान मानते थे। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","1, 2 और 3","केवल 1 और 3"],"explanationHi":"शंकु के साथ अक्सर छपने वाले स्मरण-प्रतिशत बाद में दूसरों द्वारा जोड़े गए थे और डेल के कार्य का हिस्सा नहीं हैं, न उनके शोध से समर्थित हैं, इसलिए कथन 2 असत्य है। कथन 1 और 3 शंकु का सही वर्णन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-637","question":"For a Class V project on 'Water sources in our village' in a Rajasthan school, which design best reflects project-based, experiential learning?","options":["Children copy information about water sources in India from the internet and paste pictures into a neat file","Children survey local wells and tanks, interview elders, record data and present findings to the panchayat","Parents prepare attractive project files at home, which are displayed at the school exhibition","The teacher dictates notes on water sources and children write them neatly in a project file"],"answer":1,"explanation":"A real project involves inquiry into a local, authentic question, first-hand data and a product shared with a real audience. Copying, parental work or dictated notes keep the child passive.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"राजस्थान के एक विद्यालय में ‘हमारे गाँव के जल स्रोत’ पर कक्षा V की परियोजना के लिए कौन-सी योजना परियोजना-आधारित, अनुभवजन्य अधिगम को सबसे अच्छी तरह दर्शाती है?","optionsHi":["बच्चे इंटरनेट से भारत के जल स्रोतों की जानकारी की नकल करते हैं और चित्र चिपकाकर साफ-सुथरी फ़ाइल बनाते हैं","बच्चे स्थानीय कुओं और टंकियों का सर्वेक्षण करते हैं, बुज़ुर्गों से साक्षात्कार लेते हैं, आँकड़े दर्ज करते हैं और निष्कर्ष पंचायत के सामने प्रस्तुत करते हैं","अभिभावक घर पर आकर्षक परियोजना फ़ाइलें तैयार करते हैं, जो विद्यालय की प्रदर्शनी में लगाई जाती हैं","शिक्षक जल स्रोतों पर नोट्स लिखवाता है और बच्चे उन्हें परियोजना फ़ाइल में साफ-साफ लिखते हैं"],"explanationHi":"वास्तविक परियोजना में किसी स्थानीय, प्रामाणिक प्रश्न की जाँच, प्रत्यक्ष आँकड़े और असली श्रोताओं के साथ साझा किया गया उत्पाद शामिल होता है। नकल, अभिभावकों का काम या लिखाए गए नोट्स बच्चे को निष्क्रिय रखते हैं।"},
  {"id":"cdp-pedagogy-subjects-638","question":"A Class IV teacher is planning a visit to a local post office. Which plan is most likely to turn the visit into real learning?","options":["Children frame questions before, observe and record during, and discuss findings after the visit","The visit itself is enough, since children learn automatically just by seeing new places and people","Children are told to remain silent and only listen to the postmaster to avoid indiscipline","After the visit children write a 200-word essay titled 'A Visit to the Post Office'"],"answer":0,"explanation":"Field trips work when framed by pre-visit questions, focused observation and post-visit reflection. Simply going, listening passively or writing a generic essay misses the inquiry cycle.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"कक्षा IV का एक शिक्षक स्थानीय डाकघर की यात्रा की योजना बना रहा है। कौन-सी योजना यात्रा को वास्तविक अधिगम में बदलने की सबसे अधिक संभावना रखती है?","optionsHi":["बच्चे यात्रा से पहले प्रश्न बनाते हैं, उसके दौरान अवलोकन और अभिलेखन करते हैं, और बाद में निष्कर्षों पर चर्चा करते हैं","यात्रा ही पर्याप्त है, क्योंकि बच्चे नई जगहों और लोगों को देखने मात्र से स्वतः सीख जाते हैं","अनुशासनहीनता से बचने के लिए बच्चों को चुप रहने और केवल पोस्टमास्टर को सुनने को कहा जाता है","यात्रा के बाद बच्चे ‘डाकघर की यात्रा’ शीर्षक पर 200 शब्दों का निबंध लिखते हैं"],"explanationHi":"क्षेत्र-भ्रमण तब काम करते हैं जब वे यात्रा-पूर्व प्रश्नों, केंद्रित अवलोकन और यात्रा-पश्चात चिंतन से ढाँचाबद्ध हों। केवल जाना, निष्क्रिय सुनना या सामान्य निबंध लिखना जिज्ञासा-चक्र से चूक जाता है।"},
  {"id":"cdp-pedagogy-subjects-639","question":"A Class VI PE teacher and maths teacher jointly plan a sports-integrated lesson: children run a 50 m race in groups, time it, and then work out averages and compare speeds. According to the idea of sports-integrated learning promoted in NEP 2020, which statement is most accurate?","options":["It is only a PE activity, since the maths is incidental and can be ignored","Sports should be kept separate from academic subjects to avoid wasting class time","Physical activity becomes a real context for learning concepts, while building teamwork and fitness","Only children who are good at sports benefit, so the slow runners should just record the times instead"],"answer":2,"explanation":"NEP 2020 lists sports-integrated learning as a cross-curricular approach: real data from physical activity makes averages and speed meaningful and builds life skills. Excluding slower runners would defeat its inclusive purpose.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VI का एक शारीरिक शिक्षा शिक्षक और एक गणित शिक्षक मिलकर खेल-समेकित पाठ की योजना बनाते हैं: बच्चे समूहों में 50 m की दौड़ लगाते हैं, उसे समयबद्ध करते हैं, और फिर औसत निकालकर चालों की तुलना करते हैं। NEP 2020 द्वारा प्रोत्साहित खेल-समेकित अधिगम के विचार के अनुसार कौन-सा कथन सबसे सटीक है?","optionsHi":["यह केवल शारीरिक शिक्षा की गतिविधि है, क्योंकि गणित आकस्मिक है और उसे अनदेखा किया जा सकता है","खेल को शैक्षणिक विषयों से अलग रखना चाहिए ताकि कक्षा का समय बर्बाद न हो","शारीरिक गतिविधि संप्रत्यय सीखने का वास्तविक संदर्भ बन जाती है, साथ ही टीम-भावना और फिटनेस बनाती है","केवल खेल में अच्छे बच्चों को लाभ होता है, इसलिए धीमे धावक बस समय दर्ज करें"],"explanationHi":"NEP 2020 खेल-समेकित अधिगम को एक अंतर-पाठ्यचर्या उपागम के रूप में सूचीबद्ध करती है: शारीरिक गतिविधि के वास्तविक आँकड़े औसत और चाल को अर्थपूर्ण बनाते हैं और जीवन कौशल बनाते हैं। धीमे धावकों को बाहर रखना इसके समावेशी उद्देश्य को विफल कर देगा।"},
  {"id":"cdp-pedagogy-subjects-640","question":"A school in Satara has a vegetable garden. Which way of using it is closest to John Dewey's idea of learning by doing?","options":["The school gardener tends the garden while children watch from the classroom window during EVS","Children read the chapter on plants and then visit the garden once to see and name the plants growing there","Children copy notes on gardening and are then tested on the names of the vegetables","Children plan beds, sow and water seeds, measure growth, tackle pests and discuss what they learn"],"answer":3,"explanation":"Dewey saw learning as growing out of purposeful, real activity in which children face genuine problems and reflect on them. Watching or reading about a garden keeps them as spectators.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"सतारा के एक विद्यालय में सब्ज़ी का बगीचा है। इसे प्रयोग करने का कौन-सा तरीका जॉन डेवी के ‘करके सीखने’ के विचार के सबसे निकट है?","optionsHi":["EVS के दौरान विद्यालय का माली बगीचा सँभालता है और बच्चे कक्षा की खिड़की से देखते हैं","बच्चे पौधों का अध्याय पढ़ते हैं और फिर वहाँ उग रहे पौधों को देखने और नाम बताने के लिए एक बार बगीचे जाते हैं","बच्चे बागवानी के नोट्स उतारते हैं और फिर सब्ज़ियों के नामों पर उनकी परीक्षा ली जाती है","बच्चे क्यारियों की योजना बनाते हैं, बीज बोते और सींचते हैं, वृद्धि मापते हैं, कीटों से निपटते हैं और जो सीखते हैं उस पर चर्चा करते हैं"],"explanationHi":"डेवी अधिगम को उद्देश्यपूर्ण, वास्तविक गतिविधि से उपजा मानते थे जिसमें बच्चे वास्तविक समस्याओं का सामना करते हैं और उन पर चिंतन करते हैं। बगीचे को देखना या उसके बारे में पढ़ना उन्हें दर्शक बनाए रखता है।"},
  {"id":"cdp-pedagogy-subjects-641","question":"A Class VII social science teacher holds a mock election in school, with nominations, campaigning, secret ballot and counting. Which follow-up makes the experience most educational?","options":["Announcing the winner in the assembly and moving straight on to the next chapter","A discussion comparing it with real elections: fairness, secret ballot and the Election Commission","Giving a prize to the winning candidate to motivate others to stand next time","Asking children to write the definition of 'election' five times in their notebooks for homework"],"answer":1,"explanation":"Simulation becomes learning when children reflect on it and link it to the real institution. Announcing results or giving prizes leaves the experience unprocessed.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VII का एक सामाजिक विज्ञान शिक्षक विद्यालय में नामांकन, प्रचार, गुप्त मतदान और मतगणना सहित नकली चुनाव कराता है। कौन-सा अनुवर्ती कार्य अनुभव को सबसे अधिक शैक्षिक बनाता है?","optionsHi":["सभा में विजेता की घोषणा करना और सीधे अगले अध्याय पर चले जाना","इसकी असली चुनावों से तुलना करते हुए चर्चा: निष्पक्षता, गुप्त मतदान और निर्वाचन आयोग","विजेता प्रत्याशी को पुरस्कार देना ताकि दूसरे अगली बार खड़े होने को प्रेरित हों","बच्चों से गृहकार्य में कॉपियों में ‘चुनाव’ की परिभाषा पाँच बार लिखवाना"],"explanationHi":"अनुकरण तब अधिगम बनता है जब बच्चे उस पर चिंतन करते हैं और उसे असली संस्था से जोड़ते हैं। परिणाम घोषित करना या पुरस्कार देना अनुभव को असंसाधित छोड़ देता है।"},
  {"id":"cdp-pedagogy-subjects-642","question":"While writing on the blackboard, Ms Rao says without turning around, 'Ravi and Imran, please put that away and finish the sum.' The children are surprised that she knew. In Kounin's terms this teacher behaviour is called:","options":["Ripple effect","Withitness","Overlapping","Group alerting"],"answer":1,"explanation":"Withitness is the teacher's awareness of everything happening in the room, communicated to students so they know she 'has eyes at the back of her head'. Overlapping is attending to two things at once; the ripple effect is how correcting one child affects others.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"ब्लैकबोर्ड पर लिखते हुए, बिना मुड़े, श्रीमती राव कहती हैं, ‘रवि और इमरान, कृपया उसे हटाओ और प्रश्न पूरा करो।’ बच्चे हैरान हैं कि उन्हें कैसे पता चला। कौनिन की शब्दावली में शिक्षक के इस व्यवहार को कहते हैं:","optionsHi":["तरंग प्रभाव (Ripple effect)","सर्वज्ञता-बोध (Withitness)","अतिव्यापन (Overlapping)","समूह सतर्कन (Group alerting)"],"explanationHi":"Withitness शिक्षक की कक्षा में हो रही हर बात के प्रति जागरूकता है, जिसे विद्यार्थियों तक पहुँचाया जाता है ताकि वे जानें कि उसकी ‘आँखें पीछे भी हैं’। अतिव्यापन एक साथ दो चीज़ों पर ध्यान देना है; तरंग प्रभाव यह है कि एक बच्चे को सुधारना दूसरों को कैसे प्रभावित करता है।"},
  {"id":"cdp-pedagogy-subjects-643","question":"In the first week of a new session, a Class V teacher wants to set classroom rules that children will actually follow. Which approach is best?","options":["Display a long list of 'Do nots' prepared by the teacher and read it aloud to the class every morning","Avoid rules altogether, since children of this age will learn to regulate themselves","Copy the rules from the previous year's class and announce the punishment for each","Discuss why rules are needed, agree on a few positive rules together, and revisit them as needed"],"answer":3,"explanation":"Rules that children help make, that are few, positive and explained, are owned and followed. Imposed lists of prohibitions invite resistance, and having no rules leaves children without structure.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"नए सत्र के पहले सप्ताह में कक्षा V की एक शिक्षिका कक्षा के ऐसे नियम बनाना चाहती है जिनका बच्चे वास्तव में पालन करें। सबसे अच्छा उपागम कौन-सा है?","optionsHi":["शिक्षिका द्वारा तैयार ‘क्या न करें’ की लंबी सूची लगाना और हर सुबह कक्षा को ज़ोर से पढ़कर सुनाना","नियमों से पूरी तरह बचना, क्योंकि इस आयु के बच्चे स्वयं को नियंत्रित करना सीख जाएँगे","पिछले वर्ष की कक्षा के नियम उतार लेना और प्रत्येक के लिए दंड घोषित करना","नियमों की आवश्यकता पर चर्चा करना, मिलकर कुछ सकारात्मक नियमों पर सहमत होना, और आवश्यकतानुसार उन पर पुनर्विचार करना"],"explanationHi":"जो नियम बच्चों की सहभागिता से बनें, थोड़े हों, सकारात्मक हों और समझाए गए हों, उन्हें वे अपना मानते और पालन करते हैं। थोपी गई निषेधों की सूचियाँ प्रतिरोध को न्योता देती हैं, और नियम न होने से बच्चों के पास कोई ढाँचा नहीं रहता।"},
  {"id":"cdp-pedagogy-subjects-644","question":"A colleague advises a new teacher: 'Making a child stand outside the class on one leg is fine, because you are not touching the child.' Which statement is correct?","options":["It is allowed, because the law prohibits only physical beating, not other forms of punishment","It is allowed if the parents have given the school their written consent for such punishments","It is not allowed: the RTE Act 2009 bans physical punishment and mental harassment of children","It is allowed for serious misbehaviour, but not for minor mistakes such as forgetting homework"],"answer":2,"explanation":"Section 17 of the RTE Act bans physical punishment and mental harassment; making a child stand outside on one leg is both painful and humiliating. Parental consent or seriousness of misbehaviour does not make it legal.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"एक सहकर्मी नए शिक्षक को सलाह देता है: ‘बच्चे को एक टाँग पर कक्षा के बाहर खड़ा करना ठीक है, क्योंकि तुम बच्चे को छू नहीं रहे।’ कौन-सा कथन सही है?","optionsHi":["यह अनुमत है, क्योंकि कानून केवल शारीरिक पिटाई को रोकता है, अन्य प्रकार के दंड को नहीं","यह अनुमत है यदि अभिभावकों ने विद्यालय को ऐसे दंडों के लिए लिखित सहमति दी हो","यह अनुमत नहीं है: RTE अधिनियम 2009 बच्चों को शारीरिक दंड और मानसिक उत्पीड़न देने पर रोक लगाता है","यह गंभीर दुराचरण के लिए अनुमत है, पर गृहकार्य भूलने जैसी छोटी गलतियों के लिए नहीं"],"explanationHi":"RTE अधिनियम की धारा 17 शारीरिक दंड और मानसिक उत्पीड़न पर रोक लगाती है; बच्चे को एक टाँग पर बाहर खड़ा करना पीड़ादायक और अपमानजनक दोनों है। अभिभावकों की सहमति या दुराचरण की गंभीरता इसे वैध नहीं बनाती।"},
  {"id":"cdp-pedagogy-subjects-645","question":"During a Class III lesson, Sameer keeps tapping his pencil loudly, looking around to see who notices. No one else is disturbed much and no one is at risk. Which teacher response is most appropriate first?","options":["Ignore the tapping on purpose and praise Sameer as soon as he is back on task","Stop the lesson and scold Sameer in front of the class so that others also learn","Send Sameer to the principal's office so that the lesson is not disturbed","Take away his pencil for the rest of the day as a firm consequence"],"answer":0,"explanation":"For low-level attention-seeking behaviour, planned ignoring combined with attention for appropriate behaviour removes the payoff of misbehaving. Public scolding gives exactly the attention sought and disrupts everyone.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"कक्षा III के एक पाठ के दौरान समीर बार-बार अपनी पेंसिल ज़ोर से ठोकता है और देखता है कि कौन ध्यान देता है। और किसी को बहुत परेशानी नहीं हो रही और कोई जोखिम में नहीं है। शिक्षक की कौन-सी प्रतिक्रिया सबसे पहले उपयुक्त है?","optionsHi":["ठोकने को जानबूझकर अनदेखा करना और समीर के काम पर लौटते ही उसकी प्रशंसा करना","पाठ रोक देना और कक्षा के सामने समीर को डाँटना ताकि दूसरे भी सीखें","समीर को प्रधानाचार्य के कमरे में भेज देना ताकि पाठ में बाधा न हो","शेष दिन के लिए दृढ़ परिणाम के रूप में उसकी पेंसिल ले लेना"],"explanationHi":"निम्न-स्तर के ध्यानाकर्षी व्यवहार के लिए, नियोजित अनदेखी के साथ उचित व्यवहार पर ध्यान देना दुर्व्यवहार का लाभ समाप्त कर देता है। सार्वजनिक डाँट ठीक वही ध्यान देती है जो वह चाहता है और सबको बाधित करती है।"},
  {"id":"cdp-pedagogy-subjects-646","question":"In Ms Thomas's Class IV, a lot of time is lost and noise rises every time the class moves from one activity to another. Which strategy is most likely to solve this?","options":["Cut out group activities altogether and keep the children in a single whole-class activity all day","Raise her voice at each transition until the whole class settles down again","Set clear routines and a signal for transitions, keep materials ready, and practise the routine","Give extra homework to the whole class whenever the noise level rises"],"answer":2,"explanation":"Smooth transitions depend on predictable routines, signals and preparation (Kounin's momentum and smoothness). Abandoning active work, shouting or collective punishment treat symptoms and harm learning.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"श्रीमती थॉमस की कक्षा IV में हर बार जब कक्षा एक गतिविधि से दूसरी पर जाती है, बहुत समय नष्ट होता है और शोर बढ़ जाता है। इसे हल करने की सबसे अधिक संभावना किस युक्ति में है?","optionsHi":["समूह गतिविधियाँ पूरी तरह बंद कर देना और बच्चों को दिन भर एक ही पूरी कक्षा की गतिविधि में रखना","हर बदलाव पर आवाज़ ऊँची करना जब तक पूरी कक्षा फिर शांत न हो जाए","बदलाव के लिए स्पष्ट दिनचर्या और संकेत तय करना, सामग्री तैयार रखना, और दिनचर्या का अभ्यास करना","जब भी शोर का स्तर बढ़े पूरी कक्षा को अतिरिक्त गृहकार्य देना"],"explanationHi":"सहज बदलाव पूर्वानुमेय दिनचर्याओं, संकेतों और तैयारी पर निर्भर करते हैं (कौनिन का संवेग और सहजता)। सक्रिय कार्य छोड़ देना, चिल्लाना या सामूहिक दंड लक्षणों का इलाज करते हैं और अधिगम को हानि पहुँचाते हैं।"},
  {"id":"cdp-pedagogy-subjects-647","question":"Arrange these teacher responses to a minor disturbance by two talkative Class VI students from the least intrusive to the most intrusive: P. a private conversation after class; Q. a meaningful look; R. moving to stand near them while teaching; S. using a student's name naturally in the lesson ('Suppose Neha has 3 apples...').","options":["R, Q, S, P","Q, S, R, P","Q, R, S, P","S, Q, R, P"],"answer":2,"explanation":"Effective managers begin with the least disruptive interventions: non-verbal look, proximity, then drawing the student in by name, and only then a private talk. Each step keeps the lesson flowing as long as possible.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"दो बातूनी कक्षा VI के विद्यार्थियों की छोटी-सी गड़बड़ी पर शिक्षक की इन प्रतिक्रियाओं को सबसे कम दखल देने वाली से सबसे अधिक दखल देने वाली के क्रम में लगाइए: P. कक्षा के बाद निजी बातचीत; Q. अर्थपूर्ण नज़र; R. पढ़ाते हुए उनके पास जाकर खड़े होना; S. पाठ में स्वाभाविक रूप से किसी विद्यार्थी का नाम लेना (‘मान लो नेहा के पास 3 सेब हैं...’)।","optionsHi":["R, Q, S, P","Q, S, R, P","Q, R, S, P","S, Q, R, P"],"explanationHi":"प्रभावी प्रबंधक सबसे कम बाधा डालने वाले हस्तक्षेपों से शुरू करते हैं: अशाब्दिक नज़र, निकटता, फिर नाम लेकर विद्यार्थी को जोड़ना, और उसके बाद ही निजी बातचीत। प्रत्येक चरण पाठ को यथासंभव प्रवाहमान रखता है।"},
  {"id":"cdp-pedagogy-subjects-648","question":"A Class VI teacher loudly and harshly humiliates one child for chewing gum. Afterwards the rest of the class is quiet but anxious, and fewer children volunteer answers. Which conclusion is best supported by research on classroom management?","options":["Harsh public correction is effective, since the whole class became quiet and orderly straight afterwards","Corrections ripple to onlookers: firm, clear ones help, but harsh, humiliating ones breed anxiety","The teacher should have ignored the gum-chewing completely, since it was not disturbing anyone","Quiet classes always show that learning is taking place, so the correction worked as intended"],"answer":1,"explanation":"Kounin found that corrections affect onlookers (the ripple effect); clarity and firmness improve behaviour, but roughness mostly produces fear rather than better conduct. A quiet room is not evidence of learning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VI का एक शिक्षक च्युइंग गम चबाने के लिए एक बच्चे को ज़ोर से और कठोरता से अपमानित करता है। बाद में शेष कक्षा शांत पर चिंतित है, और उत्तर देने के लिए कम बच्चे स्वेच्छा से आगे आते हैं। कक्षा-प्रबंधन पर शोध से कौन-सा निष्कर्ष सबसे अच्छी तरह समर्थित है?","optionsHi":["कठोर सार्वजनिक सुधार प्रभावी है, क्योंकि पूरी कक्षा उसके तुरंत बाद शांत और व्यवस्थित हो गई","सुधार दर्शकों तक लहरों की तरह पहुँचते हैं: दृढ़ और स्पष्ट सुधार मदद करते हैं, पर कठोर, अपमानजनक सुधार चिंता को जन्म देते हैं","शिक्षक को च्युइंग गम चबाने को पूरी तरह अनदेखा करना चाहिए था, क्योंकि वह किसी को परेशान नहीं कर रहा था","शांत कक्षाएँ हमेशा दिखाती हैं कि अधिगम हो रहा है, इसलिए सुधार इच्छित रूप से काम कर गया"],"explanationHi":"कौनिन ने पाया कि सुधार दर्शकों को प्रभावित करते हैं (तरंग प्रभाव); स्पष्टता और दृढ़ता व्यवहार सुधारती हैं, पर कठोरता अधिकतर बेहतर आचरण के बजाय भय पैदा करती है। शांत कमरा अधिगम का प्रमाण नहीं है।"},
  {"id":"cdp-pedagogy-subjects-649","question":"While working with a small reading group, a Class II teacher notices a child at another table looking lost. Without leaving the group, she signals him to start the next task and keeps the group reading. In Kounin's terms, she is showing:","options":["Overlapping","Withitness only","Satiation","The ripple effect"],"answer":0,"explanation":"Overlapping is the ability to handle two classroom matters at the same time without breaking the flow. Withitness is awareness; she shows it too, but the skill of dealing with both together is overlapping.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"एक छोटे पठन समूह के साथ काम करते हुए कक्षा II की एक शिक्षिका देखती है कि दूसरी मेज़ पर एक बच्चा भटका हुआ दिख रहा है। समूह को छोड़े बिना वह उसे अगला कार्य शुरू करने का संकेत देती है और समूह का पठन चलाए रखती है। कौनिन की शब्दावली में वह दर्शा रही है:","optionsHi":["अतिव्यापन (Overlapping)","केवल सर्वज्ञता-बोध (Withitness)","तृप्ति (Satiation)","तरंग प्रभाव"],"explanationHi":"अतिव्यापन प्रवाह तोड़े बिना कक्षा के दो मामलों को एक साथ सँभालने की योग्यता है। सर्वज्ञता-बोध जागरूकता है; वह भी दर्शाती है, पर दोनों को साथ सँभालने का कौशल अतिव्यापन है।"},
  {"id":"cdp-pedagogy-subjects-650","question":"When the teacher turns a square cut-out so that it stands on a corner, several Class 3 children say ‘Now it is a diamond, not a square.’ What is the best way to respond?","options":["Tell them that ‘diamond’ is the correct name for a square only when it is tilted on a corner","Ask them to learn the definition of a square by heart and to repeat it whenever they see a tilted one","Show squares in many sizes and positions, and let children check that sides and corners stay the same","Use only upright squares in class from now on, so that the children are not confused again"],"answer":2,"explanation":"At the visual level children judge shapes by overall look and by the usual textbook position. Varied orientations plus checking properties moves them towards analysis; showing only upright squares makes the problem worse.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"जब शिक्षक वर्गाकार कटे-आउट को घुमाकर कोने पर खड़ा करता है, तो कक्षा 3 के कई बच्चे कहते हैं, ‘अब यह समचतुर्भुज (डायमंड) है, वर्ग नहीं।’ प्रतिक्रिया देने का सबसे अच्छा तरीका क्या है?","optionsHi":["उन्हें बताना कि ‘डायमंड’ वर्ग का सही नाम केवल तब है जब वह कोने पर झुका हो","उनसे वर्ग की परिभाषा रटवाना और जब भी वे झुका हुआ वर्ग देखें उसे दोहराने को कहना","अनेक आकारों और स्थितियों में वर्ग दिखाना, और बच्चों को जाँचने देना कि भुजाएँ और कोने वही रहते हैं","अब से कक्षा में केवल सीधे खड़े वर्ग प्रयोग करना, ताकि बच्चे फिर भ्रमित न हों"],"explanationHi":"दृश्य स्तर पर बच्चे आकृतियों को समग्र रूप और पाठ्यपुस्तक की सामान्य स्थिति से आँकते हैं। विविध अभिविन्यास और गुणों की जाँच उन्हें विश्लेषण की ओर ले जाती है; केवल सीधे वर्ग दिखाने से समस्या बढ़ती है।"},
  {"id":"cdp-pedagogy-subjects-651","question":"A Class 6 student says two lines crossing at a right angle are ‘not perpendicular’ because neither of them is standing straight up. What has shaped this idea?","options":["Lines are nearly always drawn one flat and one upright, so she takes position as part of the meaning","Not yet knowing how to place a protractor to measure the angle between two crossing lines","Confusing perpendicular lines with parallel lines, which never meet","A correct understanding, since ‘perpendicular’ simply means vertical, as with a builder's plumb line"],"answer":0,"explanation":"A standard textbook picture (one vertical line on a horizontal one) gets mistaken for the definition. Perpendicular means meeting at 90°, in any position, so tilted examples must be shown.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक विद्यार्थी कहती है कि समकोण पर काटती दो रेखाएँ ‘लंब नहीं हैं’ क्योंकि उनमें से कोई भी सीधी खड़ी नहीं है। इस विचार को किसने आकार दिया है?","optionsHi":["रेखाएँ लगभग हमेशा इस तरह खींची जाती हैं कि एक आड़ी और एक खड़ी हो, इसलिए वह स्थिति को अर्थ का भाग मान लेती है","अभी यह न जानना कि दो काटती रेखाओं के बीच का कोण नापने के लिए चाँदा कैसे रखें","लंब रेखाओं को समांतर रेखाओं से उलझाना, जो कभी नहीं मिलतीं","सही समझ, क्योंकि ‘लंब’ का अर्थ केवल ऊर्ध्वाधर है, जैसे राज मिस्त्री की साहुल रेखा"],"explanationHi":"मानक पाठ्यपुस्तक का चित्र (आड़ी रेखा पर एक ऊर्ध्वाधर रेखा) परिभाषा समझ लिया जाता है। लंब का अर्थ किसी भी स्थिति में 90° पर मिलना है, इसलिए झुके हुए उदाहरण दिखाए जाने चाहिए।"},
  {"id":"cdp-pedagogy-subjects-652","question":"A Class 8 student explains, ‘A rhombus is a special kite, because a kite needs two pairs of equal sides next to each other, and a rhombus has that.’ In the Van Hiele model this student is reasoning at the level of:","options":["visualisation (recognition)","informal deduction (order)","analysis (description)","formal deduction (proof)"],"answer":1,"explanation":"Using the defining properties to place one class of shapes inside another (class inclusion) is informal deduction. At analysis, students list properties but do not yet relate one class of shapes to another.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा 8 का एक विद्यार्थी समझाता है, ‘समचतुर्भुज एक विशेष पतंग (काइट) है, क्योंकि पतंग में बराबर भुजाओं के दो जोड़े एक-दूसरे के निकट होने चाहिए, और समचतुर्भुज में यह है।’ वान हिलि मॉडल में यह विद्यार्थी किस स्तर पर तर्क कर रहा है?","optionsHi":["दृश्यीकरण (पहचान)","अनौपचारिक निगमन (क्रम)","विश्लेषण (वर्णन)","औपचारिक निगमन (उपपत्ति)"],"explanationHi":"परिभाषित गुणों का उपयोग करके आकृतियों के एक वर्ग को दूसरे के भीतर रखना (वर्ग-समावेशन) अनौपचारिक निगमन है। विश्लेषण पर विद्यार्थी गुणों की सूची बनाते हैं पर अभी एक वर्ग को दूसरे से नहीं जोड़ते।"},
  {"id":"cdp-pedagogy-subjects-653","question":"Children fold and cut paper kites by following the teacher's step-by-step instructions, and each step leads them to discover that the diagonals cross at a right angle. Which Van Hiele phase of learning is this?","options":["Inquiry (information)","Explicitation","Free orientation (open tasks)","Directed orientation"],"answer":3,"explanation":"In directed orientation, carefully sequenced tasks set by the teacher lead students to the key properties. Free orientation comes later, with open, many-step tasks that students solve their own way.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"बच्चे शिक्षक के चरण-दर-चरण निर्देशों का पालन करते हुए कागज़ की पतंगें मोड़ते और काटते हैं, और प्रत्येक चरण उन्हें यह खोजने की ओर ले जाता है कि विकर्ण समकोण पर काटते हैं। यह अधिगम का कौन-सा वान हिलि चरण है?","optionsHi":["पूछताछ (सूचना)","स्पष्टीकरण (Explicitation)","मुक्त अभिविन्यास (खुले कार्य)","निर्देशित अभिविन्यास"],"explanationHi":"निर्देशित अभिविन्यास में शिक्षक द्वारा निर्धारित सावधानी से क्रमबद्ध कार्य विद्यार्थियों को मुख्य गुणों तक ले जाते हैं। मुक्त अभिविन्यास बाद में आता है, खुले, अनेक चरणों वाले कार्यों के साथ जिन्हें विद्यार्थी अपने ढंग से हल करते हैं।"},
  {"id":"cdp-pedagogy-subjects-654","question":"After exploring kites, children describe in their own words what they noticed, and only then does the teacher give the word ‘diagonal’. In the Van Hiele phases of learning this is:","options":["integration","inquiry (information)","explicitation","free orientation"],"answer":2,"explanation":"Explicitation is when learners put their observations into words and the teacher introduces the technical terms. Integration is the final phase, when students summarise and connect what they have learnt.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"पतंगों की खोजबीन के बाद बच्चे अपने शब्दों में बताते हैं कि उन्होंने क्या देखा, और तभी शिक्षक ‘विकर्ण’ शब्द देता है। वान हिलि के अधिगम चरणों में यह है:","optionsHi":["समाकलन","पूछताछ (सूचना)","स्पष्टीकरण (Explicitation)","मुक्त अभिविन्यास"],"explanationHi":"स्पष्टीकरण वह चरण है जब शिक्षार्थी अपने अवलोकनों को शब्द देते हैं और शिक्षक तकनीकी शब्द प्रस्तुत करता है। समाकलन अंतिम चरण है, जब विद्यार्थी जो सीखा उसका सार निकालते और उसे जोड़ते हैं।"},
  {"id":"cdp-pedagogy-subjects-655","question":"A Class 9 teacher writes formal two-column proofs for students who still reason at the analysis level. According to the Van Hiele theory, the most likely result is that:","options":["students memorise the proofs without understanding, as the language is above their level","students quickly move up to the deduction level because they see proofs modelled","students skip the informal deduction level and go straight on to formal proof","students lose the properties they learnt at the analysis level and have to relearn them later"],"answer":0,"explanation":"Van Hiele stressed that each level has its own language; teaching above the learner's level leads to rote learning. Levels are not skipped, and learners do not lose earlier levels.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा 9 का एक शिक्षक उन विद्यार्थियों के लिए औपचारिक दो-स्तंभ उपपत्तियाँ लिखता है जो अब भी विश्लेषण स्तर पर तर्क करते हैं। वान हिलि सिद्धांत के अनुसार सबसे संभावित परिणाम यह है कि:","optionsHi":["विद्यार्थी उपपत्तियों को बिना समझे रट लेते हैं, क्योंकि भाषा उनके स्तर से ऊपर है","विद्यार्थी शीघ्र निगमन स्तर पर पहुँच जाते हैं क्योंकि वे उपपत्तियों का आदर्श देखते हैं","विद्यार्थी अनौपचारिक निगमन स्तर छोड़कर सीधे औपचारिक उपपत्ति पर पहुँच जाते हैं","विद्यार्थी विश्लेषण स्तर पर सीखे गुण खो देते हैं और उन्हें बाद में फिर सीखना पड़ता है"],"explanationHi":"वान हिलि ने ज़ोर दिया कि प्रत्येक स्तर की अपनी भाषा होती है; शिक्षार्थी के स्तर से ऊपर पढ़ाने से रटंत अधिगम होता है। स्तर छोड़े नहीं जाते, और शिक्षार्थी पहले के स्तर नहीं खोते।"},
  {"id":"cdp-pedagogy-subjects-656","question":"Which of these statements about the Van Hiele levels are correct? I. Moving up depends more on teaching and experience than on age. II. Each level has its own language and symbols. III. A good student can skip a level if taught well. IV. Two people reasoning at different levels may fail to understand each other.","options":["I and III only","I, II and IV","II, III and IV","I, II, III and IV"],"answer":1,"explanation":"The levels are sequential, so none can be skipped (III is false). Progress depends on instruction, not age, and each level has its own language, which is why teacher and student can talk past each other.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"वान हिलि स्तरों के बारे में इनमें से कौन-से कथन सही हैं? I. ऊपर बढ़ना आयु से अधिक शिक्षण और अनुभव पर निर्भर करता है। II. प्रत्येक स्तर की अपनी भाषा और प्रतीक होते हैं। III. अच्छी तरह पढ़ाए जाने पर एक अच्छा विद्यार्थी किसी स्तर को छोड़ सकता है। IV. अलग-अलग स्तरों पर तर्क करने वाले दो व्यक्ति एक-दूसरे को समझने में विफल हो सकते हैं।","optionsHi":["केवल I और III","I, II और IV","II, III और IV","I, II, III और IV"],"explanationHi":"स्तर क्रमिक हैं, इसलिए कोई भी छोड़ा नहीं जा सकता (III असत्य है)। प्रगति आयु पर नहीं, अनुदेशन पर निर्भर करती है, और प्रत्येक स्तर की अपनी भाषा होती है, इसीलिए शिक्षक और विद्यार्थी एक-दूसरे की बात से हटकर बोल सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-657","question":"A student agrees that ‘a quadrilateral with four right angles’ is enough to define a rectangle, because equal opposite sides then follow. Which Van Hiele level does this show?","options":["Visualisation (recognition)","Analysis","Informal deduction","Formal deduction"],"answer":2,"explanation":"Seeing that some properties imply others, and so accepting a minimal definition, marks informal deduction. At analysis a student insists on listing every property.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक विद्यार्थी सहमत है कि ‘चार समकोण वाला चतुर्भुज’ आयत को परिभाषित करने के लिए पर्याप्त है, क्योंकि तब सम्मुख भुजाओं का बराबर होना स्वतः निकल आता है। यह वान हिलि के किस स्तर को दर्शाता है?","optionsHi":["दृश्यीकरण (पहचान)","विश्लेषण","अनौपचारिक निगमन","औपचारिक निगमन"],"explanationHi":"यह देखना कि कुछ गुण अन्य गुणों को निहित करते हैं, और इस प्रकार न्यूनतम परिभाषा स्वीकार करना, अनौपचारिक निगमन का लक्षण है। विश्लेषण पर विद्यार्थी हर गुण की सूची बनाने पर ज़ोर देता है।"},
  {"id":"cdp-pedagogy-subjects-658","question":"Shown two angles, a Class 5 child says the one with longer arms is bigger, though it is actually smaller. Which activity best addresses this?","options":["Ask her to measure both angles with a protractor and write the two readings neatly side by side","Give her the definition ‘an angle is formed by two rays with a common end-point’","Draw both angles with arms of the same length from now on so that she is not confused","Let her open a pair of hinged strips by different amounts and compare turns, varying the arms"],"answer":3,"explanation":"Seeing an angle as an amount of turn, and noticing that changing arm length does not change the turn, targets the misconception. Making the arms equal removes the very thing she needs to reason about.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"दो कोण दिखाने पर कक्षा 5 की एक बच्ची कहती है कि जिसकी भुजाएँ लंबी हैं वह बड़ा है, जबकि वास्तव में वह छोटा है। कौन-सी गतिविधि इसे सबसे अच्छी तरह संबोधित करती है?","optionsHi":["उससे दोनों कोणों को चाँदे से नापने और दोनों पाठ्यांकों को साफ-साफ साथ-साथ लिखने को कहना","उसे परिभाषा देना ‘कोण उभयनिष्ठ अंत-बिंदु वाली दो किरणों से बनता है’","अब से दोनों कोणों को एक ही लंबाई की भुजाओं से बनाना ताकि वह भ्रमित न हो","उसे कब्ज़ेदार पट्टियों के जोड़े को अलग-अलग मात्रा में खोलने देना और भुजाओं की लंबाई बदलते हुए घुमाव की तुलना करने देना"],"explanationHi":"कोण को घुमाव की मात्रा के रूप में देखना, और यह ध्यान देना कि भुजा की लंबाई बदलने से घुमाव नहीं बदलता, भ्रांति को लक्षित करता है। भुजाओं को बराबर करना उसी चीज़ को हटा देता है जिसके बारे में उसे तर्क करना है।"},
  {"id":"cdp-pedagogy-subjects-659","question":"A Class 6 student measures an angle that is clearly less than a right angle and writes 130°. What is the most likely cause, and the best habit to build?","options":["She read the wrong scale; she should first estimate whether the angle is acute or obtuse","She does not know what a right angle is, so she cannot tell acute from obtuse","She placed the centre of the protractor away from the vertex, so the whole reading shifted","She has misread 30° as 130°, and simply needs to read the numbers more carefully"],"answer":0,"explanation":"Angles of 50° and 130° sit on the same mark of the two scales. Estimating first (‘less than 90°, so 50°’) catches this error, which is the most common one with protractors.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक विद्यार्थी एक ऐसे कोण को नापती है जो स्पष्ट रूप से समकोण से छोटा है और 130° लिखती है। सबसे संभावित कारण क्या है, और बनाने के लिए सबसे अच्छी आदत क्या है?","optionsHi":["उसने गलत मापनी पढ़ी; उसे पहले अनुमान लगाना चाहिए कि कोण न्यून है या अधिक कोण","उसे नहीं पता कि समकोण क्या है, इसलिए वह न्यून और अधिक कोण में अंतर नहीं कर पाती","उसने चाँदे का केंद्र शीर्ष से दूर रखा, इसलिए पूरा पाठ्यांक खिसक गया","उसने 30° को 130° पढ़ लिया है, और उसे बस संख्याएँ अधिक सावधानी से पढ़नी चाहिए"],"explanationHi":"50° और 130° के कोण चाँदे की दोनों मापनियों के एक ही चिह्न पर पड़ते हैं। पहले अनुमान लगाना (‘90° से कम, इसलिए 50°’) इस त्रुटि को पकड़ लेता है, जो चाँदे से सबसे आम त्रुटि है।"},
  {"id":"cdp-pedagogy-subjects-660","question":"Children think that rectangles with the same perimeter must have the same area. Which activity best challenges this?","options":["Give them the formulas for area and perimeter to memorise and practise on ten sums","Let them make rectangles from a 12 cm loop of string on squared paper and count the squares","Ask them to find the area of one rectangle in two different ways and compare the two answers","Show them that a square has the largest perimeter for a given area, using examples"],"answer":1,"explanation":"With perimeter 12 cm, a 1 × 5 rectangle encloses 5 squares, 2 × 4 encloses 8 and 3 × 3 encloses 9. Children see the area change while the perimeter stays fixed. Option D is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"बच्चे सोचते हैं कि समान परिमाप वाले आयतों का क्षेत्रफल भी समान होना चाहिए। कौन-सी गतिविधि इसे सबसे अच्छी तरह चुनौती देती है?","optionsHi":["उन्हें क्षेत्रफल और परिमाप के सूत्र रटने को देना और दस प्रश्नों पर अभ्यास कराना","उन्हें वर्गाकित कागज़ पर 12 cm की धागे की लूप से आयत बनाने देना और वर्ग गिनने देना","उनसे एक आयत का क्षेत्रफल दो अलग-अलग तरीकों से निकालने और दोनों उत्तरों की तुलना करने को कहना","उदाहरणों से दिखाना कि दिए गए क्षेत्रफल के लिए वर्ग का परिमाप सबसे अधिक होता है"],"explanationHi":"परिमाप 12 cm होने पर 1 × 5 का आयत 5 वर्गों को घेरता है, 2 × 4 का 8 को और 3 × 3 का 9 को। बच्चे देखते हैं कि परिमाप स्थिर रहते हुए क्षेत्रफल बदलता है। विकल्प D असत्य है।"},
  {"id":"cdp-pedagogy-subjects-661","question":"A child cuts a triangle off one end of a paper rectangle and sticks it on the other end to make a parallelogram, then says the new shape has a bigger area ‘because it is longer and slanting’. What has the child not yet understood?","options":["The formula for finding the area of a parallelogram, which is base times height","How to measure the length of slanting sides with a ruler","That area stays the same when a shape is cut and rearranged without overlap","That a parallelogram is a kind of rectangle with slanting sides"],"answer":2,"explanation":"The pieces are the same, so the area is the same; this is conservation of area. Judging area by length or appearance is the misconception, and it is the idea behind deriving the parallelogram formula.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक बच्चा कागज़ के आयत के एक सिरे से त्रिभुज काटकर उसे दूसरे सिरे पर चिपकाकर समांतर चतुर्भुज बनाता है, फिर कहता है कि नई आकृति का क्षेत्रफल अधिक है ‘क्योंकि वह लंबी और तिरछी है’। बच्चे ने अभी क्या नहीं समझा है?","optionsHi":["समांतर चतुर्भुज का क्षेत्रफल निकालने का सूत्र, जो आधार गुणा ऊँचाई है","तिरछी भुजाओं की लंबाई पैमाने से कैसे नापी जाए","कि किसी आकृति को काटकर बिना अतिव्यापन पुनर्व्यवस्थित करने पर क्षेत्रफल वही रहता है","कि समांतर चतुर्भुज तिरछी भुजाओं वाला एक प्रकार का आयत है"],"explanationHi":"टुकड़े वही हैं, इसलिए क्षेत्रफल वही है; यह क्षेत्रफल का संरक्षण है। क्षेत्रफल को लंबाई या रूप से आँकना भ्रांति है, और यही समांतर चतुर्भुज के सूत्र की व्युत्पत्ति के पीछे का विचार है।"},
  {"id":"cdp-pedagogy-subjects-662","question":"Measuring a table with her hand span, a child leaves gaps between spans in some places and overlaps them in others. Which measurement principle is she missing?","options":["That the unit must be a standard unit such as a centimetre or a metre","That the measure must start from zero","That longer units give smaller numbers","That equal units must be laid end to end with no gaps or overlaps"],"answer":3,"explanation":"Unit iteration means repeating the same unit without gaps or overlaps; without it the count does not represent length. This is basic to all measurement, whatever unit is used.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"अपनी हथेली के बित्ते से मेज़ नापते हुए एक बच्ची कुछ जगहों पर बित्तों के बीच खाली स्थान छोड़ देती है और कुछ में उन्हें एक-दूसरे पर चढ़ा देती है। वह मापन का कौन-सा सिद्धांत चूक रही है?","optionsHi":["कि इकाई सेंटीमीटर या मीटर जैसी मानक इकाई होनी चाहिए","कि माप शून्य से शुरू होना चाहिए","कि लंबी इकाइयाँ छोटी संख्याएँ देती हैं","कि बराबर इकाइयाँ बिना खाली स्थान या अतिव्यापन के सिरे से सिरा मिलाकर रखी जानी चाहिए"],"explanationHi":"इकाई-पुनरावृत्ति का अर्थ है एक ही इकाई को बिना खाली स्थान या अतिव्यापन के दोहराना; इसके बिना गिनती लंबाई को निरूपित नहीं करती। यह सभी मापन के लिए मूलभूत है, चाहे कोई भी इकाई हो।"},
  {"id":"cdp-pedagogy-subjects-663","question":"Ravi measures a bench as 8 hand spans and Meena measures the same bench as 12 hand spans. Asked whose hand is bigger, a child says ‘Meena's, because she got the bigger number.’ The child has not understood that:","options":["the bigger the unit, the fewer of them are needed for the same length","hand spans are not reliable units, so the comparison is meaningless","both children must have measured carelessly, since the bench is the same","the same bench can have only one correct measurement"],"answer":0,"explanation":"Unit size and the count are inversely related: Ravi needed fewer spans, so his span is longer. This relationship is an important outcome of measuring with non-standard units.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"रवि एक बेंच को 8 बित्तों में नापता है और मीना उसी बेंच को 12 बित्तों में नापती है। पूछा गया कि किसका हाथ बड़ा है, एक बच्चा कहता है ‘मीना का, क्योंकि उसे बड़ी संख्या मिली।’ बच्चे ने यह नहीं समझा है कि:","optionsHi":["इकाई जितनी बड़ी होती है, उसी लंबाई के लिए उतनी ही कम इकाइयाँ चाहिए","बित्ते विश्वसनीय इकाइयाँ नहीं हैं, इसलिए तुलना अर्थहीन है","दोनों बच्चों ने लापरवाही से नापा होगा, क्योंकि बेंच तो वही है","एक ही बेंच का केवल एक ही सही माप हो सकता है"],"explanationHi":"इकाई का आकार और गिनती व्युत्क्रमानुपाती हैं: रवि को कम बित्ते चाहिए थे, इसलिए उसका बित्ता लंबा है। यह संबंध अमानक इकाइयों से मापन का एक महत्त्वपूर्ण परिणाम है।"},
  {"id":"cdp-pedagogy-subjects-664","question":"A Class 7 student writes 1 m² = 100 cm². Which response best helps her see why this is wrong?","options":["Tell her the rule ‘multiply by 100 twice when changing square units’ and set some practice sums","Ask her to picture a 1 m square as 100 cm by 100 cm and count how many 1 cm squares fill it","Remind her that 1 m = 100 cm and ask her to write the conversion again carefully","Ask her to convert 1 m³ into cm³ as well, so that she sees the pattern"],"answer":1,"explanation":"A 1 m square is 100 cm on each side, so it holds 100 × 100 = 10,000 squares of 1 cm². She applied the length conversion to area. Picturing the square builds the reason, not just a new rule.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक विद्यार्थी लिखती है 1 m² = 100 cm²। कौन-सी प्रतिक्रिया उसे यह देखने में सबसे अच्छी तरह मदद करती है कि यह गलत क्यों है?","optionsHi":["उसे नियम ‘वर्ग इकाइयाँ बदलते समय दो बार 100 से गुणा करो’ बताना और कुछ प्रश्न अभ्यास के लिए देना","उससे 1 m के वर्ग को 100 cm गुणा 100 cm के रूप में कल्पना करने और गिनने को कहना कि उसे कितने 1 cm के वर्ग भरते हैं","उसे याद दिलाना कि 1 m = 100 cm और उससे रूपांतरण फिर सावधानी से लिखने को कहना","उससे 1 m³ को cm³ में भी बदलने को कहना ताकि वह पैटर्न देख सके"],"explanationHi":"1 m के वर्ग की प्रत्येक भुजा 100 cm है, इसलिए उसमें 1 cm² के 100 × 100 = 10,000 वर्ग आते हैं। उसने लंबाई के रूपांतरण को क्षेत्रफल पर लगा दिया। वर्ग की कल्पना कारण बनाती है, केवल नया नियम नहीं।"},
  {"id":"cdp-pedagogy-subjects-665","question":"A Class 6 student is shown a drawing of a cuboid made of unit cubes, 2 cubes high, 3 wide and 4 long. She counts the cubes she can see on the three visible faces and says the volume is 18 cubes. What has she missed?","options":["The cubes on the edges, which she has counted twice on two faces","That volume is measured in square units, not by counting cubes","The hidden cubes; counting layer by layer (2 layers of 12) gives 24","That the length should be multiplied by the height only, which gives 8"],"answer":2,"explanation":"Counting visible faces leaves out the 6 hidden cubes (a 1 × 2 × 3 block), so she gets 18 instead of 24. Building the cuboid and counting it in layers gives meaning to length × breadth × height.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा 6 की एक विद्यार्थी को इकाई घनों से बने घनाभ का चित्र दिखाया गया है, जो 2 घन ऊँचा, 3 चौड़ा और 4 लंबा है। वह तीन दिखाई देने वाले फलकों के घन गिनती है और कहती है कि आयतन 18 घन है। उसने क्या चूक की है?","optionsHi":["किनारों के घन, जिन्हें उसने दो फलकों पर दो बार गिना है","कि आयतन वर्ग इकाइयों में मापा जाता है, घन गिनकर नहीं","छिपे हुए घन; परत-दर-परत गिनने पर (2 परतें, प्रत्येक में 12) 24 मिलता है","कि लंबाई को केवल ऊँचाई से गुणा करना चाहिए, जिससे 8 मिलता है"],"explanationHi":"दिखाई देने वाले फलक गिनने से 6 छिपे हुए घन (1 × 2 × 3 का खंड) छूट जाते हैं, इसलिए उसे 24 के बजाय 18 मिलता है। घनाभ बनाना और उसे परतों में गिनना लंबाई × चौड़ाई × ऊँचाई को अर्थ देता है।"},
  {"id":"cdp-pedagogy-subjects-666","question":"A Class 6 child believes any six squares joined edge to edge will fold into a cube. What is the best way to deal with this?","options":["Give her the list of all 11 cube nets to learn by heart and then draw them from memory in her notebook","Tell her that only the cross-shaped net can fold into a cube, and ask her to draw it neatly","Show a video of a cube being unfolded into a net, and then move on","Have her predict which six-square shapes will fold into a cube, then cut and fold them to check"],"answer":3,"explanation":"Predicting and then testing builds spatial visualisation and lets her see that some six-square shapes (such as six in a row) do not close. The cross is only one of 11 nets, so option B is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक बच्ची मानती है कि किनारे से किनारा जुड़े कोई भी छह वर्ग मोड़ने पर घन बन जाएँगे। इससे निपटने का सबसे अच्छा तरीका क्या है?","optionsHi":["उसे सभी 11 घन-जालों की सूची रटने को देना और फिर कॉपी में उन्हें याद से बनाने को कहना","उसे बताना कि केवल क्रॉस आकार का जाल ही घन में मुड़ सकता है, और उसे साफ-साफ बनाने को कहना","घन को जाल के रूप में खुलते हुए का वीडियो दिखाना, और फिर आगे बढ़ जाना","उससे अनुमान लगवाना कि छह वर्गों की कौन-सी आकृतियाँ घन में मुड़ेंगी, फिर उन्हें काटकर और मोड़कर जाँचना"],"explanationHi":"अनुमान लगाना और फिर परखना स्थानिक दृश्यीकरण बनाता है और उसे देखने देता है कि छह वर्गों की कुछ आकृतियाँ (जैसे एक पंक्ति में छह) बंद नहीं होतीं। क्रॉस 11 जालों में से केवल एक है, इसलिए विकल्प B असत्य है।"},
  {"id":"cdp-pedagogy-subjects-667","question":"A Class 5 child marks four lines of symmetry on a rectangle that is not a square: two through the midpoints of the sides and the two diagonals. Which response is best?","options":["Let her fold a paper rectangle along a diagonal and see whether the two halves match","Accept it, since every rectangle has four lines of symmetry, just as a square has","Tell her that only squares have diagonals","Ask her to count the corners, since the number of lines of symmetry equals the number of corners"],"answer":0,"explanation":"Folding along a diagonal shows the halves do not fit on each other, so a non-square rectangle has only two lines of symmetry. Diagonals split it into two congruent triangles, but that is not reflection symmetry.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा 5 की एक बच्ची उस आयत पर, जो वर्ग नहीं है, सममिति की चार रेखाएँ अंकित करती है: दो भुजाओं के मध्य-बिंदुओं से होकर और दो विकर्ण। कौन-सी प्रतिक्रिया सबसे अच्छी है?","optionsHi":["उसे कागज़ का आयत विकर्ण के अनुदिश मोड़ने देना और देखने देना कि दोनों भाग मिलते हैं या नहीं","इसे स्वीकार कर लेना, क्योंकि प्रत्येक आयत की चार सममिति रेखाएँ होती हैं, जैसे वर्ग की","उसे बताना कि केवल वर्ग के विकर्ण होते हैं","उससे कोने गिनने को कहना, क्योंकि सममिति रेखाओं की संख्या कोनों की संख्या के बराबर होती है"],"explanationHi":"विकर्ण के अनुदिश मोड़ने पर दिखता है कि दोनों भाग एक-दूसरे पर नहीं बैठते, इसलिए वर्ग-भिन्न आयत की केवल दो सममिति रेखाएँ होती हैं। विकर्ण उसे दो सर्वांगसम त्रिभुजों में बाँटते हैं, पर यह परावर्तन सममिति नहीं है।"},
  {"id":"cdp-pedagogy-subjects-668","question":"A child says the letter N ‘has no symmetry at all’ because no fold line works. What is the best response?","options":["Agree, because N has no line of symmetry and so it cannot have any symmetry","Ask her to trace N, turn the tracing half a turn about its centre, and see if it fits","Tell her that every capital letter of the alphabet has at least one line of symmetry somewhere","Ask her to fold N along its slanting stroke and check the two halves again"],"answer":1,"explanation":"N has no line of symmetry, but it fits on itself after a half turn, so it has rotational symmetry of order 2. The child has taken ‘symmetry’ to mean only line symmetry.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"एक बच्ची कहती है कि अक्षर N में ‘कोई सममिति है ही नहीं’ क्योंकि कोई मोड़ने की रेखा काम नहीं करती। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["सहमत होना, क्योंकि N की कोई सममिति रेखा नहीं है और इसलिए उसमें कोई सममिति नहीं हो सकती","उससे N का अनुरेखण करने, अनुरेखण को उसके केंद्र के चारों ओर आधा चक्कर घुमाने, और देखने को कहना कि क्या वह बैठता है","उसे बताना कि वर्णमाला के प्रत्येक बड़े अक्षर में कहीं न कहीं कम से कम एक सममिति रेखा होती है","उससे N को उसकी तिरछी रेखा के अनुदिश मोड़ने और दोनों भागों को फिर जाँचने को कहना"],"explanationHi":"N की कोई सममिति रेखा नहीं है, पर आधा चक्कर घुमाने के बाद वह स्वयं पर बैठ जाता है, इसलिए उसमें कोटि 2 की घूर्णन सममिति है। बच्ची ने ‘सममिति’ का अर्थ केवल रेखा सममिति मान लिया है।"},
  {"id":"cdp-pedagogy-subjects-669","question":"To build spatial thinking in Class 5, which activity is most suitable?","options":["Copying the names and pictures of 3-D shapes from the board neatly into their notebooks","Learning the number of faces, edges and corners of each solid by heart for a weekly class quiz","Building block models, drawing their top, front and side views, and having a partner rebuild them","Colouring pictures of cubes, cones and cylinders in the textbook"],"answer":2,"explanation":"Moving between a solid and its views, in both directions, develops spatial visualisation, which NCERT's primary maths books emphasise. Memorising counts of faces does not.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 में स्थानिक चिंतन बनाने के लिए कौन-सी गतिविधि सबसे उपयुक्त है?","optionsHi":["बोर्ड से 3-D आकृतियों के नाम और चित्र अपनी कॉपियों में साफ-साफ उतारना","साप्ताहिक कक्षा प्रश्नोत्तरी के लिए प्रत्येक ठोस के फलकों, किनारों और कोनों की संख्या रटना","ब्लॉक मॉडल बनाना, उनके ऊपर, सामने और बगल के दृश्य बनाना, और साथी से उन्हें फिर बनवाना","पाठ्यपुस्तक में घनों, शंकुओं और बेलनों के चित्रों में रंग भरना"],"explanationHi":"ठोस और उसके दृश्यों के बीच, दोनों दिशाओं में, आना-जाना स्थानिक दृश्यीकरण विकसित करता है, जिस पर NCERT की प्राथमिक गणित की पुस्तकें बल देती हैं। फलकों की गिनती रटने से यह नहीं होता।"},
  {"id":"cdp-pedagogy-subjects-670","question":"A teacher asks, ‘On this dot grid, make as many different triangles as you can that each have an area of 2 square units.’ What kind of task is this, and what is its main value?","options":["A closed drill that builds speed and accuracy in finding the areas of triangles","A memory task that checks whether children recall the area formula for triangles","A test item meant only for the fastest learners, to keep them busy while the others catch up","An open-ended task with many answers, inviting exploration and reasoning at different levels"],"answer":3,"explanation":"With many correct solutions, every child can enter at her own level, and comparing triangles leads naturally to the idea that the same base and height give the same area.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"एक शिक्षिका कहती है, ‘इस बिंदु-जाल पर जितने अलग-अलग त्रिभुज बना सको बनाओ, जिनमें से प्रत्येक का क्षेत्रफल 2 वर्ग इकाई हो।’ यह किस प्रकार का कार्य है, और इसका मुख्य मूल्य क्या है?","optionsHi":["बंद अभ्यास, जो त्रिभुजों के क्षेत्रफल निकालने में गति और शुद्धता बनाता है","स्मृति कार्य, जो जाँचता है कि बच्चे त्रिभुज के क्षेत्रफल का सूत्र याद करते हैं या नहीं","केवल सबसे तेज़ शिक्षार्थियों के लिए प्रश्न, जिससे वे व्यस्त रहें जब तक दूसरे साथ पकड़ें","अनेक उत्तरों वाला खुला कार्य, जो अलग-अलग स्तरों पर खोजबीन और तर्क को आमंत्रित करता है"],"explanationHi":"अनेक सही हलों के साथ, प्रत्येक बच्चा अपने स्तर पर प्रवेश कर सकता है, और त्रिभुजों की तुलना स्वाभाविक रूप से इस विचार की ओर ले जाती है कि समान आधार और ऊँचाई समान क्षेत्रफल देते हैं।"},
  {"id":"cdp-pedagogy-subjects-671","question":"Children use the seven tangram pieces and find that each large triangle covers exactly a quarter of the full square. Which mathematical process is the activity mainly developing?","options":["Connecting geometry and fractions through visualisation","Memorising the names and shapes of the seven tangram pieces","Practising measurement of the pieces with standard units such as cm","Learning the formula for the area of a triangle and applying it"],"answer":0,"explanation":"Comparing the pieces to the whole links shape with fraction (a quarter) and with area, the kind of connection NCF 2005 lists among the processes of mathematics.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"बच्चे सात टैनग्राम टुकड़ों का उपयोग करते हैं और पाते हैं कि प्रत्येक बड़ा त्रिभुज पूरे वर्ग का ठीक एक चौथाई ढकता है। यह गतिविधि मुख्यतः किस गणितीय प्रक्रिया को विकसित कर रही है?","optionsHi":["दृश्यीकरण के माध्यम से ज्यामिति और भिन्नों को जोड़ना","सात टैनग्राम टुकड़ों के नाम और आकार याद करना","cm जैसी मानक इकाइयों से टुकड़ों के मापन का अभ्यास करना","त्रिभुज के क्षेत्रफल का सूत्र सीखना और लगाना"],"explanationHi":"टुकड़ों की पूर्ण से तुलना आकृति को भिन्न (एक चौथाई) और क्षेत्रफल से जोड़ती है, ऐसा संबंध जिसे NCF 2005 गणित की प्रक्रियाओं में गिनाता है।"},
  {"id":"cdp-pedagogy-subjects-672","question":"Assertion (A): Children should sort and handle many real objects and shapes before they are given definitions of shapes. Reason (R): At the visual level, children recognise shapes by their appearance and need varied experiences to begin noticing properties.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Van Hiele's model says that properties grow out of varied experience with shapes; definitions given too early are only memorised. R gives the reason for A.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"अभिकथन (A): बच्चों को आकृतियों की परिभाषाएँ देने से पहले उन्हें अनेक वास्तविक वस्तुओं और आकृतियों को छाँटने और सँभालने देना चाहिए। कारण (R): दृश्य स्तर पर बच्चे आकृतियों को उनके रूप से पहचानते हैं और गुणों पर ध्यान देना शुरू करने के लिए उन्हें विविध अनुभव चाहिए।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"वान हिलि का मॉडल कहता है कि गुण आकृतियों के विविध अनुभव से विकसित होते हैं; बहुत जल्दी दी गई परिभाषाएँ केवल रटी जाती हैं। R, A का कारण देता है।"},
  {"id":"cdp-pedagogy-subjects-673","question":"Class 7 students measure the angles of three triangles and get totals of 179°, 181° and 180°. One says, ‘So the angle sum is only about 180°.’ What should the teacher do?","options":["Tell them to measure more carefully, again and again, until they all get exactly 180°","Discuss measurement error, then show the sum is exactly 180° by tearing off the corners and later by proof","Accept ‘about 180°’ as the right answer at this stage, since measurement is never exact","Tell them the angle sum differs slightly for different kinds of triangles, such as obtuse or right ones"],"answer":1,"explanation":"Measurement suggests a result but cannot prove it. Moving from measuring to a general argument, first by arranging the torn corners and then by a proof, shows the difference between checking examples and proving.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 के विद्यार्थी तीन त्रिभुजों के कोण नापते हैं और योग 179°, 181° और 180° पाते हैं। एक कहता है, ‘तो कोणों का योग केवल लगभग 180° है।’ शिक्षक को क्या करना चाहिए?","optionsHi":["उन्हें बार-बार अधिक सावधानी से नापने को कहना जब तक सबको ठीक 180° न मिले","मापन त्रुटि पर चर्चा करना, फिर कोने फाड़कर और बाद में उपपत्ति से दिखाना कि योग ठीक 180° है","इस चरण पर ‘लगभग 180°’ को सही उत्तर मान लेना, क्योंकि मापन कभी सटीक नहीं होता","उन्हें बताना कि कोणों का योग अलग-अलग प्रकार के त्रिभुजों, जैसे अधिक कोण या समकोण वाले, में थोड़ा भिन्न होता है"],"explanationHi":"मापन परिणाम का संकेत देता है पर उसे सिद्ध नहीं कर सकता। मापन से सामान्य तर्क की ओर जाना, पहले फाड़े हुए कोनों को जमाकर और फिर उपपत्ति से, उदाहरणों की जाँच और सिद्ध करने के बीच का अंतर दिखाता है।"},
  {"id":"cdp-pedagogy-subjects-674","question":"A Class 4 child finds the perimeter of a rectangle 8 cm long and 5 cm wide as 8 + 5 = 13 cm. What is the most suitable next step?","options":["Give her the formula 2 × (l + b) to memorise and practise on similar sums","Tell her that she has found the area instead of the perimeter of the rectangle","Ask her to trace the whole edge with a finger or string and say which sides she added","Ask her to measure the rectangle again carefully with a ruler and then add the two numbers once more"],"answer":2,"explanation":"She added only the two labelled sides. Tracing the whole boundary shows that perimeter is the full distance around, 8 + 5 + 8 + 5 = 26 cm, and gives the formula its meaning.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 की एक बच्ची 8 cm लंबे और 5 cm चौड़े आयत का परिमाप 8 + 5 = 13 cm निकालती है। अगला सबसे उपयुक्त कदम क्या है?","optionsHi":["उसे सूत्र 2 × (l + b) रटने को देना और ऐसे ही प्रश्नों का अभ्यास कराना","उसे बताना कि उसने आयत का परिमाप नहीं, बल्कि क्षेत्रफल निकाला है","उससे उंगली या धागे से पूरे किनारे का अनुरेखण करने और बताने को कहना कि उसने कौन-सी भुजाएँ जोड़ीं","उससे आयत को पैमाने से फिर सावधानी से नापने और फिर दोनों संख्याओं को एक बार और जोड़ने को कहना"],"explanationHi":"उसने केवल दो लिखी हुई भुजाएँ जोड़ीं। पूरी सीमा का अनुरेखण दिखाता है कि परिमाप चारों ओर की पूरी दूरी है, 8 + 5 + 8 + 5 = 26 cm, और सूत्र को अर्थ देता है।"},
  {"id":"cdp-pedagogy-subjects-675","question":"A Class 8 student preparing for a debate on banning single-use plastic is handed a six-page magazine feature. Which sequence of reading strategies would be most efficient for her purpose?","options":["Scan each line for the word ‘plastic’ and copy out every sentence in which it appears","Read every page carefully from the beginning so that no point is missed, and then make notes","Skim to find relevant sections, scan them for figures, then read the useful parts closely","Read only the final paragraph, since articles always put their main argument at the end"],"answer":2,"explanation":"Skilled readers match strategy to purpose: skimming locates what is relevant, scanning picks out data, and intensive reading is kept for the parts that matter. Reading everything closely wastes time.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"एकल-उपयोग प्लास्टिक पर प्रतिबंध पर वाद-विवाद की तैयारी कर रही कक्षा 8 की एक विद्यार्थी को छह पृष्ठों का एक पत्रिका-फ़ीचर दिया गया है। उसके उद्देश्य के लिए पठन युक्तियों का कौन-सा क्रम सबसे कुशल होगा?","optionsHi":["हर पंक्ति में ‘प्लास्टिक’ शब्द के लिए स्कैन करना और जिस भी वाक्य में वह आए उसे उतार लेना","हर पृष्ठ को शुरू से ध्यान से पढ़ना ताकि कोई बिंदु न छूटे, और फिर नोट्स बनाना","प्रासंगिक खंडों को खोजने के लिए सरसरी तौर पर देखना (स्किम), उन्हें आँकड़ों के लिए स्कैन करना, फिर उपयोगी भागों को ध्यान से पढ़ना","केवल अंतिम अनुच्छेद पढ़ना, क्योंकि लेख हमेशा अपना मुख्य तर्क अंत में रखते हैं"],"explanationHi":"कुशल पाठक युक्ति को उद्देश्य से मिलाते हैं: स्किमिंग प्रासंगिक को खोजती है, स्कैनिंग आँकड़े चुनती है, और गहन पठन उन भागों के लिए रखा जाता है जो मायने रखते हैं। सब कुछ ध्यान से पढ़ना समय बर्बाद करता है।"},
  {"id":"cdp-pedagogy-subjects-676","question":"Consider these statements: I. Skimming is used to get the gist, often by reading headings and the first sentences of paragraphs. II. Scanning requires reading every word of the text carefully. III. In both skimming and scanning, the reader deliberately ignores much of the text according to her purpose. Which are correct?","options":["I and II only","I and III only","II and III only","I, II and III"],"answer":1,"explanation":"Scanning is a rapid search for a specific item, such as a date or name, so it does not involve reading every word. Both skimming and scanning are selective, purpose-driven reading.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"इन कथनों पर विचार कीजिए: I. स्किमिंग (सरसरी पठन) का उपयोग मोटा सार पाने के लिए होता है, प्रायः शीर्षकों और अनुच्छेदों के पहले वाक्यों को पढ़कर। II. स्कैनिंग (खोजी पठन) में पाठ के हर शब्द को ध्यान से पढ़ना आवश्यक है। III. स्किमिंग और स्कैनिंग दोनों में पाठक अपने उद्देश्य के अनुसार पाठ के बड़े भाग को जानबूझकर छोड़ देता है। कौन-से सही हैं?","optionsHi":["केवल I और II","केवल I और III","केवल II और III","I, II और III"],"explanationHi":"स्कैनिंग किसी विशिष्ट वस्तु, जैसे तिथि या नाम, की तीव्र खोज है, इसलिए उसमें हर शब्द पढ़ना शामिल नहीं है। स्किमिंग और स्कैनिंग दोनों चयनात्मक, उद्देश्य-प्रेरित पठन हैं।"},
  {"id":"cdp-pedagogy-subjects-677","question":"Class 6 children in a coastal Kerala village easily follow an English story about fishing boats in the monsoon, but children in a desert school in Rajasthan, who decode just as well, struggle with the same story. The most likely explanation is:","options":["The Rajasthan children have weaker phonics skills and need more decoding practice","The grammar of the story is beyond the level that the Rajasthan children have reached","The Kerala children are simply more intelligent readers than the others","The two groups differ in the background knowledge (schema) they bring to the text"],"answer":3,"explanation":"Schema theory holds that readers build meaning by linking text to what they already know. Since decoding is equal, the difference lies in prior knowledge, which a teacher can build through pictures, videos and talk before reading.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"केरल के एक तटीय गाँव की कक्षा 6 के बच्चे मानसून में मछली पकड़ने की नावों की अंग्रेज़ी कहानी आसानी से समझ लेते हैं, पर राजस्थान के रेगिस्तानी विद्यालय के बच्चे, जो उतना ही अच्छा वाचन (डिकोडिंग) करते हैं, उसी कहानी में संघर्ष करते हैं। सबसे संभावित स्पष्टीकरण है:","optionsHi":["राजस्थान के बच्चों का ध्वनि-विज्ञान (फोनिक्स) कौशल कमज़ोर है और उन्हें डिकोडिंग का और अभ्यास चाहिए","कहानी का व्याकरण उस स्तर से परे है जहाँ राजस्थान के बच्चे पहुँचे हैं","केरल के बच्चे दूसरों से बस अधिक बुद्धिमान पाठक हैं","दोनों समूह पाठ के साथ जो पृष्ठभूमि ज्ञान (स्कीमा) लाते हैं, उसमें भिन्न हैं"],"explanationHi":"स्कीमा सिद्धांत मानता है कि पाठक पाठ को अपने पहले से ज्ञात से जोड़कर अर्थ बनाते हैं। चूँकि डिकोडिंग समान है, अंतर पूर्व ज्ञान में है, जिसे शिक्षक पढ़ने से पहले चित्रों, वीडियो और बातचीत से बना सकता है।"},
  {"id":"cdp-pedagogy-subjects-678","question":"A Class 3 child reads ‘The horse jumped over the fence’ as ‘The house jumped over the fence’ and carries on without pausing. The most useful teacher prompt is:","options":["‘Sound out every letter of each word again from the start.’","‘Look only at the picture and guess the word from it.’","‘Does that make sense? Read the sentence again and check.’","‘Skip any word you are not sure of and keep reading.’"],"answer":2,"explanation":"The miscue matches the letters but not the meaning, showing reliance on visual cues without monitoring sense. Prompting the child to cross-check with meaning builds self-monitoring, which further sounding out would not.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कक्षा 3 का एक बच्चा ‘The horse jumped over the fence’ को ‘The house jumped over the fence’ पढ़ता है और बिना रुके आगे बढ़ जाता है। शिक्षक का सबसे उपयोगी संकेत है:","optionsHi":["‘हर शब्द के हर अक्षर की ध्वनि शुरू से फिर बोलो।’","‘केवल चित्र देखो और उससे शब्द का अनुमान लगाओ।’","‘क्या यह अर्थपूर्ण लगता है? वाक्य को फिर पढ़ो और जाँचो।’","‘जिस शब्द के बारे में पक्का न हो उसे छोड़ दो और पढ़ते रहो।’"],"explanationHi":"यह पठन-भूल अक्षरों से मेल खाती है पर अर्थ से नहीं, जो अर्थ की निगरानी किए बिना दृश्य संकेतों पर निर्भरता दर्शाती है। बच्चे को अर्थ से मिलान करने का संकेत देना आत्म-निगरानी बनाता है, जो और अधिक ध्वनि बोलने से नहीं होता।"},
  {"id":"cdp-pedagogy-subjects-679","question":"In groups of four, Class 6 students read a text section by section. One student predicts what comes next, another asks questions, a third clears up confusing words or ideas, and a fourth summarises; the roles rotate and the teacher gradually withdraws her support. This technique is:","options":["SQ3R","Jigsaw reading","Directed Reading-Thinking Activity","Reciprocal teaching"],"answer":3,"explanation":"Palincsar and Brown’s reciprocal teaching trains four strategies, predicting, questioning, clarifying and summarising, through dialogue in which students gradually take over the teacher’s role.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"चार-चार के समूहों में कक्षा 6 के विद्यार्थी पाठ को खंड-दर-खंड पढ़ते हैं। एक विद्यार्थी अनुमान लगाता है कि आगे क्या आएगा, दूसरा प्रश्न पूछता है, तीसरा भ्रमित करने वाले शब्दों या विचारों को स्पष्ट करता है, और चौथा सार बनाता है; भूमिकाएँ बदलती रहती हैं और शिक्षिका धीरे-धीरे अपना सहयोग हटा लेती है। यह तकनीक है:","optionsHi":["SQ3R","जिगसॉ पठन","निर्देशित पठन-चिंतन गतिविधि (DRTA)","पारस्परिक शिक्षण (Reciprocal teaching)"],"explanationHi":"पैलिंकसर और ब्राउन का पारस्परिक शिक्षण चार युक्तियों, अनुमान, प्रश्न, स्पष्टीकरण और सारांशीकरण, का प्रशिक्षण संवाद के माध्यम से देता है, जिसमें विद्यार्थी धीरे-धीरे शिक्षक की भूमिका स्वयं सँभाल लेते हैं।"},
  {"id":"cdp-pedagogy-subjects-680","question":"Preparing a history chapter, a Class 9 student first glances over the headings and pictures, turns each heading into a question, reads to answer it, and then closes the book and answers her questions aloud from memory. In SQ3R, this last step is:","options":["Survey","Recite","Review","Question"],"answer":1,"explanation":"SQ3R runs Survey, Question, Read, Recite, Review. Answering the questions from memory after reading a section is Recite; Review is the later revision of the whole chapter.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"इतिहास का अध्याय तैयार करते हुए कक्षा 9 की एक विद्यार्थी पहले शीर्षकों और चित्रों पर नज़र डालती है, प्रत्येक शीर्षक को प्रश्न में बदलती है, उत्तर देने के लिए पढ़ती है, और फिर किताब बंद करके अपने प्रश्नों के उत्तर याद से ज़ोर से देती है। SQ3R में यह अंतिम चरण है:","optionsHi":["सर्वेक्षण (Survey)","सस्वर दोहराना (Recite)","पुनरावलोकन (Review)","प्रश्न (Question)"],"explanationHi":"SQ3R का क्रम है सर्वेक्षण, प्रश्न, पठन, सस्वर दोहराना, पुनरावलोकन। किसी खंड को पढ़ने के बाद याद से प्रश्नों के उत्तर देना सस्वर दोहराना (Recite) है; पुनरावलोकन पूरे अध्याय का बाद का दोहराव है।"},
  {"id":"cdp-pedagogy-subjects-681","question":"A teacher reads a story in parts. At each pause she asks, ‘What do you think will happen next, and why?’, students read on to check, and then say which clues in the text confirmed or changed their predictions. This procedure is known as:","options":["Round-robin reading","Language experience approach","Directed Reading-Thinking Activity","Shared reading"],"answer":2,"explanation":"Stauffer’s DRTA cycles through predict, read, and prove with evidence from the text, making reading an active process of hypothesis and confirmation.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"एक शिक्षिका कहानी को भागों में पढ़ती है। हर ठहराव पर वह पूछती है, ‘तुम्हें क्या लगता है आगे क्या होगा, और क्यों?’, विद्यार्थी जाँचने के लिए आगे पढ़ते हैं, और फिर बताते हैं कि पाठ के कौन-से संकेतों ने उनके अनुमानों की पुष्टि की या उन्हें बदला। यह प्रक्रिया जानी जाती है:","optionsHi":["बारी-बारी पठन (Round-robin reading) के रूप में","भाषा अनुभव उपागम के रूप में","निर्देशित पठन-चिंतन गतिविधि (DRTA) के रूप में","साझा पठन के रूप में"],"explanationHi":"स्टॉफ़र का DRTA अनुमान लगाने, पढ़ने और पाठ के साक्ष्य से सिद्ध करने के चक्र से गुज़रता है, जिससे पठन परिकल्पना और पुष्टि की सक्रिय प्रक्रिया बन जाता है।"},
  {"id":"cdp-pedagogy-subjects-682","question":"Passage: ‘Raju looked at the dark clouds, picked up his umbrella and hurried out.’ Which question is inferential?","options":["‘What did Raju pick up before he left?’","‘Why did Raju take his umbrella with him?’","‘Was Raju right to hurry out in such weather?’","‘What were the clouds like when Raju looked?’"],"answer":1,"explanation":"The text never says it was about to rain; the reader must infer it from the dark clouds. The question about whether he was right asks for a judgement, which makes it evaluative, not inferential.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"गद्यांश: ‘Raju looked at the dark clouds, picked up his umbrella and hurried out.’ कौन-सा प्रश्न अनुमानात्मक है?","optionsHi":["‘राजू ने जाने से पहले क्या उठाया?’","‘राजू अपने साथ छाता क्यों ले गया?’","‘क्या राजू का ऐसे मौसम में जल्दी बाहर निकलना सही था?’","‘जब राजू ने देखा तो बादल कैसे थे?’"],"explanationHi":"पाठ कहीं नहीं कहता कि बारिश होने वाली थी; पाठक को इसका अनुमान काले बादलों से लगाना होता है। क्या वह सही था, यह प्रश्न निर्णय माँगता है, जो इसे मूल्यांकनात्मक बनाता है, अनुमानात्मक नहीं।"},
  {"id":"cdp-pedagogy-subjects-683","question":"After reading a newspaper report on a new dam, a Class 8 teacher wants to develop critical literacy. Which question best serves this aim?","options":["‘In which district is the dam being built, and by whom?’","‘How many villages will get water from the new dam each year?’","‘What is the meaning of the word “reservoir” in the report?’","‘Whose views are missing from this report, and why?’"],"answer":3,"explanation":"Critical literacy asks readers to examine whose perspective a text presents or leaves out and why. The other questions check literal information or vocabulary.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"एक नए बाँध पर अख़बार की रिपोर्ट पढ़ने के बाद कक्षा 8 की एक शिक्षिका आलोचनात्मक साक्षरता विकसित करना चाहती है। इस उद्देश्य की सबसे अच्छी पूर्ति कौन-सा प्रश्न करता है?","optionsHi":["‘बाँध किस ज़िले में और किसके द्वारा बनाया जा रहा है?’","‘नए बाँध से हर साल कितने गाँवों को पानी मिलेगा?’","‘रिपोर्ट में “जलाशय” शब्द का क्या अर्थ है?’","‘इस रिपोर्ट में किसके विचार गायब हैं, और क्यों?’"],"explanationHi":"आलोचनात्मक साक्षरता पाठकों से जाँचने को कहती है कि पाठ किसका दृष्टिकोण प्रस्तुत करता है या छोड़ देता है और क्यों। अन्य प्रश्न शाब्दिक जानकारी या शब्दावली की जाँच करते हैं।"},
  {"id":"cdp-pedagogy-subjects-684","question":"For which purpose is intensive reading most appropriate?","options":["Studying the steps of a science experiment to carry it out exactly","Choosing a library novel by flipping quickly through a few of its pages","Reading comics on a holiday afternoon purely for fun","Finding a relative’s number in a telephone directory"],"answer":0,"explanation":"Intensive reading means careful, detailed reading for full understanding, needed when every step matters. The other purposes call for scanning, skimming and extensive reading respectively.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"गहन पठन किस उद्देश्य के लिए सबसे उपयुक्त है?","optionsHi":["विज्ञान के किसी प्रयोग के चरणों को ठीक वैसे ही करने के लिए पढ़ना","पुस्तकालय का उपन्यास चुनने के लिए उसके कुछ पृष्ठ जल्दी-जल्दी पलटना","छुट्टी की दोपहर में केवल मनोरंजन के लिए कॉमिक्स पढ़ना","टेलीफोन डायरेक्टरी में किसी रिश्तेदार का नंबर ढूँढ़ना"],"explanationHi":"गहन पठन का अर्थ है पूर्ण समझ के लिए सावधान, विस्तृत पठन, जो तब आवश्यक है जब हर चरण मायने रखता हो। अन्य उद्देश्य क्रमशः स्कैनिंग, स्किमिंग और विस्तृत पठन माँगते हैं।"},
  {"id":"cdp-pedagogy-subjects-685","question":"In a Class 6 English class, children take turns reading the lesson aloud one paragraph each while the rest follow along, and this is the main reading activity every day. What is the main problem with this practice?","options":["It is a problem only because silent reading should not start before Class 8","It is the only reliable way for the teacher to check whether children have understood the text","Its only drawback is that the weaker readers take too much of the class’s time","It stresses performance over comprehension, and the listeners often lose the meaning"],"answer":3,"explanation":"Round-robin reading makes children anxious about pronunciation, engages one reader at a time, and does not show comprehension. Silent reading with a purpose is better suited to understanding at this stage.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 6 की अंग्रेज़ी कक्षा में बच्चे बारी-बारी से पाठ का एक-एक अनुच्छेद ज़ोर से पढ़ते हैं जबकि बाकी साथ-साथ अनुसरण करते हैं, और यही प्रतिदिन की मुख्य पठन गतिविधि है। इस अभ्यास की मुख्य समस्या क्या है?","optionsHi":["यह केवल इसलिए समस्या है कि मौन पठन कक्षा 8 से पहले शुरू नहीं होना चाहिए","शिक्षक के लिए यह जाँचने का एकमात्र विश्वसनीय तरीका है कि बच्चों ने पाठ समझा या नहीं","इसकी एकमात्र कमी यह है कि कमज़ोर पाठक कक्षा का बहुत अधिक समय ले लेते हैं","यह बोध के बजाय प्रदर्शन पर ज़ोर देता है, और श्रोता अक्सर अर्थ खो देते हैं"],"explanationHi":"बारी-बारी पठन बच्चों को उच्चारण के बारे में चिंतित करता है, एक समय में केवल एक पाठक को संलग्न करता है, और बोध नहीं दिखाता। इस अवस्था में उद्देश्य सहित मौन पठन समझ के लिए अधिक उपयुक्त है।"},
  {"id":"cdp-pedagogy-subjects-686","question":"Which of these tasks demands the most advanced level of phonological awareness in a Class 1 child?","options":["Saying whether ‘cat’ and ‘hat’ rhyme","Clapping the number of syllables in ‘banana’","Saying ‘stop’ without the /s/ sound","Telling the first sound in ‘mango’"],"answer":2,"explanation":"Deleting a phoneme and blending the rest (‘top’) is phoneme manipulation, the most demanding level. Rhyme, syllables and initial sounds are earlier skills.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कक्षा 1 के बच्चे के लिए इनमें से कौन-सा कार्य ध्वनि-जागरूकता का सबसे उन्नत स्तर माँगता है?","optionsHi":["यह बताना कि ‘cat’ और ‘hat’ तुकांत हैं या नहीं","‘banana’ में अक्षरांशों (सिलेबल) की संख्या ताली बजाकर बताना","/s/ ध्वनि के बिना ‘stop’ बोलना","‘mango’ की पहली ध्वनि बताना"],"explanationHi":"किसी स्वनिम को हटाकर शेष को मिलाना (‘top’) स्वनिम-हेरफेर है, जो सबसे कठिन स्तर है। तुक, अक्षरांश और आरंभिक ध्वनियाँ पहले के कौशल हैं।"},
  {"id":"cdp-pedagogy-subjects-687","question":"A Class 1 teacher first teaches the sounds /s/, /a/, /t/, /p/ and then has children blend them to read ‘sat’, ‘pat’ and ‘tap’. This approach is:","options":["Synthetic phonics, which builds words by blending individual sounds","Analytic phonics, which begins with whole words and studies their parts","The look-and-say method, which teaches whole words by their shape","The whole language approach, which teaches sounds only inside stories"],"answer":0,"explanation":"Synthetic phonics teaches letter–sound links first and then blends (synthesises) them into words. Analytic phonics starts from known words and analyses their shared sounds.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कक्षा 1 की एक शिक्षिका पहले ध्वनियाँ /s/, /a/, /t/, /p/ सिखाती है और फिर बच्चों से उन्हें मिलाकर ‘sat’, ‘pat’ और ‘tap’ पढ़वाती है। यह उपागम है:","optionsHi":["संश्लेषणात्मक ध्वनि-विज्ञान (Synthetic phonics), जो अलग-अलग ध्वनियों को मिलाकर शब्द बनाता है","विश्लेषणात्मक ध्वनि-विज्ञान (Analytic phonics), जो संपूर्ण शब्दों से शुरू होकर उनके अंशों का अध्ययन करता है","देखो और बोलो विधि, जो संपूर्ण शब्दों को उनकी आकृति से सिखाती है","समग्र भाषा उपागम, जो ध्वनियाँ केवल कहानियों के भीतर सिखाता है"],"explanationHi":"संश्लेषणात्मक फोनिक्स पहले अक्षर–ध्वनि संबंध सिखाता है और फिर उन्हें मिलाकर (संश्लेषित करके) शब्द बनाता है। विश्लेषणात्मक फोनिक्स ज्ञात शब्दों से शुरू होकर उनकी साझा ध्वनियों का विश्लेषण करता है।"},
  {"id":"cdp-pedagogy-subjects-688","question":"High-frequency words such as ‘the’, ‘was’, ‘said’ and ‘one’ are hard for Class 1 children to sound out. They are best taught:","options":["By asking children to sound them out letter by letter like all other words","As sight words, through repeated meeting in texts, games and word walls","By delaying them until children have learnt all the letter sounds","By having children copy each word twenty times in a notebook"],"answer":1,"explanation":"Irregular high-frequency words do not follow simple sound rules, so children learn to recognise them instantly through frequent meaningful exposure; they are too common to postpone.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"‘the’, ‘was’, ‘said’ और ‘one’ जैसे उच्च-आवृत्ति वाले शब्दों को कक्षा 1 के बच्चों के लिए ध्वनि से पढ़ना कठिन है। इन्हें सबसे अच्छी तरह सिखाया जाता है:","optionsHi":["बच्चों से इन्हें अन्य सभी शब्दों की तरह अक्षर-दर-अक्षर ध्वनि बोलकर पढ़वाकर","दृश्य शब्दों के रूप में, पाठों, खेलों और शब्द-दीवारों में बार-बार मिलने के माध्यम से","जब तक बच्चे सारी अक्षर-ध्वनियाँ न सीख लें तब तक उन्हें टालकर","बच्चों से हर शब्द को कॉपी में बीस बार उतरवाकर"],"explanationHi":"अनियमित उच्च-आवृत्ति शब्द सरल ध्वनि-नियमों का पालन नहीं करते, इसलिए बच्चे अर्थपूर्ण बार-बार संपर्क से उन्हें तुरंत पहचानना सीखते हैं; वे इतने आम हैं कि उन्हें टाला नहीं जा सकता।"},
  {"id":"cdp-pedagogy-subjects-689","question":"While teaching a passage on the causes and effects of floods in Assam, a Class 7 teacher asks students to fill in a chart with ‘Cause’ and ‘Effect’ boxes linked by arrows. The main purpose is to help students:","options":["Copy the passage in a shorter and neater form for revision later","See the structure of the text, which aids understanding and recall","Memorise the difficult words that appear in the passage on floods","Practise drawing neat diagrams for their geography examination answers"],"answer":1,"explanation":"Graphic organisers make a text’s organisation (cause–effect, compare–contrast, sequence) visible, so students see how ideas relate and remember them better.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"असम में बाढ़ के कारणों और प्रभावों पर एक गद्यांश पढ़ाते हुए कक्षा 7 की शिक्षिका विद्यार्थियों से तीरों से जुड़े ‘कारण’ और ‘प्रभाव’ वाले खानों का चार्ट भरवाती है। मुख्य उद्देश्य विद्यार्थियों की किसमें मदद करना है?","optionsHi":["बाद में दोहराने के लिए गद्यांश को संक्षिप्त और साफ रूप में उतारना","पाठ की संरचना देखना, जो समझ और स्मरण में सहायक होती है","बाढ़ वाले गद्यांश में आए कठिन शब्दों को याद करना","भूगोल की परीक्षा के उत्तरों के लिए साफ आरेख बनाने का अभ्यास करना"],"explanationHi":"ग्राफ़िक आयोजक पाठ के संगठन (कारण–प्रभाव, तुलना–विरोध, क्रम) को दृश्य बनाते हैं, ताकि विद्यार्थी देखें कि विचार कैसे संबंधित हैं और उन्हें बेहतर याद रखें।"},
  {"id":"cdp-pedagogy-subjects-690","question":"A teacher divides a text about Pongal into four parts. Each group reads a different part, then members regroup so that each new group has one person from every part, and they must put the whole account together by talking. The main benefit of this jigsaw reading is that it:","options":["Creates an information gap, giving speaking and listening a real purpose","Lets the teacher finish the lesson faster by dividing the reading work","Ensures that every child reads the full text closely and on her own","Reduces the need for any whole-class discussion after the reading is over"],"answer":0,"explanation":"Since each learner holds information the others need, the task creates genuine interdependence and purposeful communication, integrating reading with speaking and listening.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"एक शिक्षक पोंगल के बारे में एक पाठ को चार भागों में बाँटता है। प्रत्येक समूह एक अलग भाग पढ़ता है, फिर सदस्य इस तरह पुनः समूहबद्ध होते हैं कि प्रत्येक नए समूह में हर भाग का एक व्यक्ति हो, और उन्हें बातचीत से पूरा वृत्तांत जोड़ना होता है। इस जिगसॉ पठन का मुख्य लाभ यह है कि यह:","optionsHi":["सूचना-अंतराल बनाता है, जिससे बोलने और सुनने को वास्तविक उद्देश्य मिलता है","पठन का कार्य बाँटकर शिक्षक को पाठ जल्दी समाप्त करने देता है","सुनिश्चित करता है कि हर बच्चा पूरा पाठ स्वयं ध्यान से पढ़े","पठन समाप्त होने के बाद पूरी कक्षा की किसी चर्चा की आवश्यकता घटा देता है"],"explanationHi":"चूँकि प्रत्येक शिक्षार्थी के पास ऐसी जानकारी है जो दूसरों को चाहिए, कार्य वास्तविक अन्योन्याश्रितता और उद्देश्यपूर्ण संप्रेषण बनाता है, पठन को बोलने और सुनने से एकीकृत करता है।"},
  {"id":"cdp-pedagogy-subjects-691","question":"Reading a story aloud, a teacher pauses to say, ‘Hmm, I don’t know this word, so I’ll read on to see if the next sentence helps… The author keeps mentioning the cracked wall; I think it’s a clue.’ The main purpose of this think-aloud is to:","options":["Show children that even teachers make mistakes and get stuck while reading","Fill time so that children can rest between parts of the story","Test whether children are listening carefully to the story","Make visible the mental strategies a skilled reader uses to understand"],"answer":3,"explanation":"Think-alouds model metacognitive comprehension strategies, such as reading on, predicting and noticing clues, which are otherwise invisible to learners.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कहानी ज़ोर से पढ़ते हुए एक शिक्षिका रुककर कहती है, ‘हम्म, मुझे यह शब्द नहीं आता, तो मैं आगे पढ़ती हूँ कि अगला वाक्य मदद करता है या नहीं… लेखक बार-बार टूटी दीवार का ज़िक्र करता है; मुझे लगता है यह एक संकेत है।’ इस थिंक-अलाउड (सोचकर बोलना) का मुख्य उद्देश्य है:","optionsHi":["बच्चों को दिखाना कि शिक्षक भी पढ़ते समय गलतियाँ करते और अटकते हैं","समय भरना ताकि बच्चे कहानी के भागों के बीच आराम कर सकें","यह परखना कि बच्चे कहानी को ध्यान से सुन रहे हैं या नहीं","उन मानसिक युक्तियों को दृश्य बनाना जो कुशल पाठक समझने के लिए प्रयोग करता है"],"explanationHi":"थिंक-अलाउड अधिबोधात्मक बोध-युक्तियों, जैसे आगे पढ़ना, अनुमान लगाना और संकेतों पर ध्यान देना, का आदर्श प्रस्तुत करता है, जो अन्यथा शिक्षार्थियों को दिखाई नहीं देतीं।"},
  {"id":"cdp-pedagogy-subjects-692","question":"Which behaviour best shows that a pre-school child has developed ‘concepts about print’?","options":["She can sing the whole alphabet song from A to Z without a single mistake","She can copy capital letters neatly from the board into her notebook","She knows English print runs left to right and that spaces separate words","She can name ten colours and match each colour to a picture"],"answer":2,"explanation":"Concepts about print include directionality, the idea that print carries meaning, and what words and letters are. Reciting the alphabet or copying letters can happen without this understanding.","difficulty":"moderate","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कौन-सा व्यवहार सबसे अच्छी तरह दर्शाता है कि पूर्व-विद्यालयी बच्ची ने ‘मुद्रण की अवधारणाएँ’ (concepts about print) विकसित कर ली हैं?","optionsHi":["वह वर्णमाला का पूरा गीत A से Z तक बिना एक भी गलती के गा सकती है","वह बोर्ड से बड़े अक्षर अपनी कॉपी में साफ-साफ उतार सकती है","वह जानती है कि अंग्रेज़ी मुद्रण बाएँ से दाएँ चलता है और रिक्त स्थान शब्दों को अलग करते हैं","वह दस रंगों के नाम बता सकती है और प्रत्येक रंग को चित्र से मिला सकती है"],"explanationHi":"मुद्रण की अवधारणाओं में दिशात्मकता, यह विचार कि मुद्रित सामग्री अर्थ वहन करती है, और शब्द तथा अक्षर क्या हैं, शामिल हैं। वर्णमाला दोहराना या अक्षर उतारना इस समझ के बिना भी हो सकता है।"},
  {"id":"cdp-pedagogy-subjects-693","question":"All the questions a Class 5 teacher sets on a passage can be answered by copying one sentence from the text. Using the Question–Answer Relationship (QAR) framework, which kind of question should she add to deepen comprehension?","options":["‘Think and search’ and ‘On my own’ questions that link ideas and prior knowledge","More ‘Right there’ questions, but taken from less obvious parts of the text","Only multiple-choice questions, so that the answers are quicker and easier to mark","Questions that ask for the meanings of difficult words listed in the glossary"],"answer":0,"explanation":"Raphael’s QAR separates ‘Right there’ answers from those that require putting ideas together across the text or combining it with the reader’s own knowledge, which build deeper comprehension.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 5 की एक शिक्षिका द्वारा किसी गद्यांश पर बनाए गए सभी प्रश्नों के उत्तर पाठ से एक वाक्य उतारकर दिए जा सकते हैं। प्रश्न-उत्तर संबंध (QAR) ढाँचे का प्रयोग करते हुए, बोध को गहरा करने के लिए उसे किस प्रकार का प्रश्न जोड़ना चाहिए?","optionsHi":["‘सोचो और खोजो’ तथा ‘अपने आप’ प्रश्न, जो विचारों और पूर्व ज्ञान को जोड़ते हैं","अधिक ‘सीधे वहीं’ प्रश्न, पर पाठ के कम स्पष्ट भागों से लिए गए","केवल बहुविकल्पीय प्रश्न, ताकि उत्तर जाँचना तेज़ और आसान हो","शब्दकोश में दिए कठिन शब्दों के अर्थ पूछने वाले प्रश्न"],"explanationHi":"रैफ़ेल का QAR ‘सीधे वहीं’ उत्तरों को उन उत्तरों से अलग करता है जिनके लिए पाठ भर के विचारों को जोड़ना या उसे पाठक के अपने ज्ञान से मिलाना पड़ता है, जो गहरे बोध का निर्माण करते हैं।"},
  {"id":"cdp-pedagogy-subjects-694","question":"A lesson in a Class 6 reader has 25 new words. Before reading, the teacher writes all 25 on the board with their meanings and has students copy them. A better plan would be to:","options":["Avoid all vocabulary work, since students should never be made to meet any unknown words","Continue with all 25 words, but also give their Hindi meanings for greater clarity","Pre-teach only the few words needed for the gist; let others be worked out from context","Make students learn all 25 meanings by heart and test them before reading begins"],"answer":2,"explanation":"Pre-teaching a long list overloads memory and takes away the chance to infer meaning. Pre-teaching only key words supports the gist and leaves room for building word-learning strategies.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 6 की पाठ्यपुस्तक के एक पाठ में 25 नए शब्द हैं। पढ़ने से पहले शिक्षिका सभी 25 को उनके अर्थों सहित बोर्ड पर लिखती है और विद्यार्थियों से उतरवाती है। एक बेहतर योजना होगी:","optionsHi":["शब्दावली का सारा काम टाल देना, क्योंकि विद्यार्थियों को कभी किसी अज्ञात शब्द से सामना नहीं कराना चाहिए","सभी 25 शब्दों के साथ आगे बढ़ना, पर अधिक स्पष्टता के लिए उनके हिंदी अर्थ भी देना","केवल सार के लिए आवश्यक कुछ शब्द पहले सिखाना; बाकी को संदर्भ से समझने देना","विद्यार्थियों से सभी 25 अर्थ कंठस्थ करवाना और पढ़ना शुरू होने से पहले उनकी परीक्षा लेना"],"explanationHi":"लंबी सूची पहले सिखाने से स्मृति पर बोझ पड़ता है और अर्थ का अनुमान लगाने का अवसर छिन जाता है। केवल मुख्य शब्द पहले सिखाना सार में सहायक है और शब्द-सीखने की युक्तियाँ बनाने के लिए जगह छोड़ता है।"},
  {"id":"cdp-pedagogy-subjects-695","question":"Assertion (A): A reader with rich knowledge of a topic can often understand a text about it even when she does not know some of the words. Reason (R): In top-down processing, readers use prior knowledge and expectations to construct meaning from a text.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Top-down processing lets background knowledge fill gaps and guide interpretation, which is exactly why a well-informed reader can cope with some unknown words.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"अभिकथन (A): किसी विषय का समृद्ध ज्ञान रखने वाला पाठक उस पर आधारित पाठ को प्रायः तब भी समझ सकता है जब वह कुछ शब्द नहीं जानता। कारण (R): ऊपर-से-नीचे (टॉप-डाउन) प्रक्रमण में पाठक पाठ से अर्थ बनाने के लिए पूर्व ज्ञान और अपेक्षाओं का प्रयोग करते हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"टॉप-डाउन प्रक्रमण में पृष्ठभूमि ज्ञान अंतराल भरता है और व्याख्या का मार्गदर्शन करता है, इसीलिए सुसूचित पाठक कुछ अज्ञात शब्दों से निपट सकता है।"},
  {"id":"cdp-pedagogy-subjects-696","question":"Match each comprehension question with the reading sub-skill it mainly tests: 1. ‘Choose the most suitable title for the passage.’ 2. ‘Find a word in paragraph 3 that means “tired”.’ 3. ‘What does “it” in line 5 refer to?’ 4. ‘Why does the writer mention her grandmother?’; a. Understanding reference (cohesion) b. Vocabulary in context c. Getting the gist d. Inferring the writer’s purpose","options":["1-c, 2-b, 3-a, 4-d","1-c, 2-a, 3-b, 4-d","1-d, 2-b, 3-a, 4-c","1-b, 2-c, 3-a, 4-d"],"answer":0,"explanation":"A title tests the gist, a synonym hunt tests vocabulary in context, a pronoun’s referent tests cohesion, and ‘why does the writer…’ requires inferring purpose.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"प्रत्येक बोध-प्रश्न का मिलान उस पठन उप-कौशल से कीजिए जिसकी वह मुख्यतः जाँच करता है: 1. ‘गद्यांश के लिए सबसे उपयुक्त शीर्षक चुनिए।’ 2. ‘अनुच्छेद 3 में वह शब्द ढूँढ़िए जिसका अर्थ ‘थका हुआ’ है।’ 3. ‘पंक्ति 5 में “it” किसकी ओर संकेत करता है?’ 4. ‘लेखिका अपनी दादी का उल्लेख क्यों करती है?’; a. संदर्भ समझना (संसक्ति) b. संदर्भ में शब्दावली c. सार ग्रहण करना d. लेखिका के उद्देश्य का अनुमान लगाना","optionsHi":["1-c, 2-b, 3-a, 4-d","1-c, 2-a, 3-b, 4-d","1-d, 2-b, 3-a, 4-c","1-b, 2-c, 3-a, 4-d"],"explanationHi":"शीर्षक सार की जाँच करता है, पर्यायवाची खोजना संदर्भ में शब्दावली की, सर्वनाम का संदर्भ संसक्ति की, और ‘लेखिका क्यों…’ उद्देश्य का अनुमान माँगता है।"},
  {"id":"cdp-pedagogy-subjects-697","question":"For small-group guided reading sessions, in which the teacher supports children as they read, the texts chosen should be at the children’s:","options":["Independent level, which they can read easily with no help at all","Instructional level, challenging but manageable with some support","Frustration level, so that the teacher has plenty to correct","Grade level, whatever their actual reading ability may be"],"answer":1,"explanation":"Guided reading uses instructional-level texts, which stretch readers but remain understandable with teacher support. Independent-level texts suit free reading; frustration-level texts break down comprehension.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"छोटे समूह के निर्देशित पठन सत्रों के लिए, जिनमें शिक्षक बच्चों के पढ़ते समय उनकी सहायता करता है, चुने गए पाठ बच्चों के किस स्तर के होने चाहिए?","optionsHi":["स्वतंत्र स्तर, जिसे वे बिना किसी सहायता के आसानी से पढ़ सकें","अनुदेशनात्मक स्तर, जो कुछ सहायता से चुनौतीपूर्ण पर सँभालने योग्य हो","निराशा स्तर, ताकि शिक्षक के पास सुधारने के लिए बहुत कुछ हो","कक्षा-स्तर, चाहे उनकी वास्तविक पठन-क्षमता कुछ भी हो"],"explanationHi":"निर्देशित पठन अनुदेशनात्मक स्तर के पाठ प्रयोग करता है, जो पाठकों को खींचते हैं पर शिक्षक की सहायता से बोधगम्य रहते हैं। स्वतंत्र स्तर के पाठ मुक्त पठन के लिए उपयुक्त हैं; निराशा स्तर के पाठ बोध को तोड़ देते हैं।"},
  {"id":"cdp-pedagogy-subjects-698","question":"A Class 7 teacher asks students to write a single-sentence summary of each paragraph of a long passage. This mainly develops the ability to:","options":["Copy sentences quickly and accurately from a printed text into notes","Learn the spelling of the difficult words that are used in each paragraph","Count how many sentences a well-built paragraph should contain","Separate the main idea of each paragraph from its supporting details"],"answer":3,"explanation":"Summarising forces readers to decide what is central and what is detail, a core comprehension skill that also helps them follow the overall structure of a text.","difficulty":"moderate","source":"CTET Paper II · State TETs","questionHi":"कक्षा 7 की एक शिक्षिका विद्यार्थियों से लंबे गद्यांश के प्रत्येक अनुच्छेद का एक वाक्य में सार लिखने को कहती है। यह मुख्यतः किस योग्यता को विकसित करता है?","optionsHi":["छपे पाठ से नोट्स में वाक्य तेज़ी से और सही उतारना","प्रत्येक अनुच्छेद में प्रयुक्त कठिन शब्दों की वर्तनी सीखना","गिनना कि एक सुगठित अनुच्छेद में कितने वाक्य होने चाहिए","प्रत्येक अनुच्छेद के मुख्य विचार को उसके सहायक विवरणों से अलग करना"],"explanationHi":"सारांशीकरण पाठकों को तय करने को बाध्य करता है कि क्या केंद्रीय है और क्या विवरण, जो बोध का मूल कौशल है और पाठ की समग्र संरचना को समझने में भी मदद करता है।"},
  {"id":"cdp-pedagogy-subjects-699","question":"A Class 4 child often reads by guessing from the pictures and the first letter: for ‘The dog is bad’ she reads ‘The dog is big’, and for ‘pony’ she reads ‘pond’. The most suitable support is to:","options":["Remove all pictures from her books so that she cannot guess any more","Strengthen her letter–sound decoding while keeping attention on meaning","Ask her to read faster, so that guessing gives way naturally to fluent reading","Accept these miscues, since guessing is always a sign of a good reader"],"answer":1,"explanation":"Over-reliance on top-down guessing without full decoding produces meaning-changing errors. Building decoding while asking ‘Does it look right and make sense?’ develops balanced, interactive reading.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कक्षा 4 की एक बच्ची अक्सर चित्रों और पहले अक्षर से अनुमान लगाकर पढ़ती है: ‘The dog is bad’ को वह ‘The dog is big’ पढ़ती है, और ‘pony’ को ‘pond’। सबसे उपयुक्त सहायता है:","optionsHi":["उसकी किताबों से सारे चित्र हटा देना ताकि वह अनुमान न लगा सके","उसका अक्षर–ध्वनि डिकोडिंग सुदृढ़ करना, साथ ही ध्यान अर्थ पर बनाए रखना","उससे तेज़ पढ़ने को कहना, ताकि अनुमान लगाना स्वाभाविक रूप से धाराप्रवाह पठन को जगह दे","इन पठन-भूलों को स्वीकार कर लेना, क्योंकि अनुमान लगाना हमेशा अच्छे पाठक की निशानी है"],"explanationHi":"पूर्ण डिकोडिंग के बिना टॉप-डाउन अनुमान पर अत्यधिक निर्भरता अर्थ बदल देने वाली त्रुटियाँ पैदा करती है। डिकोडिंग बनाना और साथ में पूछना ‘क्या यह सही दिखता है और अर्थपूर्ण लगता है?’ संतुलित, अंतःक्रियात्मक पठन विकसित करता है।"},
  {"id":"cdp-pedagogy-subjects-700","question":"A Class X class in Delhi wants to discuss whether reservation in jobs should continue in its present form, and feelings run high. Which approach should the teacher take?","options":["Refuse the discussion, since the topic is political and too divisive for a classroom","State her own view clearly at the start, so that the students learn the one correct position on it","Let students argue freely without any rules or structure, so that no one feels restricted","Hold a structured discussion with ground rules, present positions with evidence, and not impose her view"],"answer":3,"explanation":"Controversial issues are part of social science learning, but they need structure: ground rules, balanced evidence and the constitutional framework. Avoiding the issue, imposing a view or allowing an unruly free-for-all each defeats critical thinking.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"दिल्ली की कक्षा X एक चर्चा करना चाहती है कि क्या नौकरियों में आरक्षण अपने वर्तमान रूप में जारी रहना चाहिए, और भावनाएँ उफान पर हैं। शिक्षिका को कौन-सा उपागम अपनाना चाहिए?","optionsHi":["चर्चा से इनकार करना, क्योंकि विषय राजनीतिक है और कक्षा के लिए बहुत विभाजनकारी है","आरंभ में अपना मत स्पष्ट रूप से बताना, ताकि विद्यार्थी इस पर एकमात्र सही स्थिति सीख लें","विद्यार्थियों को बिना किसी नियम या ढाँचे के खुलकर बहस करने देना, ताकि कोई सीमित महसूस न करे","ज़मीनी नियमों के साथ संरचित चर्चा कराना, साक्ष्य के साथ पक्ष प्रस्तुत कराना, और अपना मत न थोपना"],"explanationHi":"विवादास्पद मुद्दे सामाजिक विज्ञान सीखने का हिस्सा हैं, पर उन्हें संरचना चाहिए: ज़मीनी नियम, संतुलित साक्ष्य और संवैधानिक ढाँचा। मुद्दे से बचना, मत थोपना या अराजक खुली बहस की अनुमति देना, तीनों आलोचनात्मक चिंतन को विफल करते हैं।"},
  {"id":"cdp-pedagogy-subjects-701","question":"During a discussion on caste, a Class IX student uses a slur and says people of a certain caste 'deserve' to do cleaning work. What should the teacher do?","options":["Stay neutral, since every opinion in a class discussion is equally valid and must be respected","Firmly point out that the remark denies equal dignity, then help the class examine its roots","Send the student out of class at once and carry on with the chapter without comment","Ignore the remark, so that the discussion does not become tense or divided"],"answer":1,"explanation":"Openness to different views does not extend to views that deny others' dignity; equality and dignity are constitutional values the classroom must uphold. Examining the prejudice teaches far more than silence or expulsion.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"जाति पर चर्चा के दौरान कक्षा IX का एक विद्यार्थी अपशब्द का प्रयोग करता है और कहता है कि किसी विशेष जाति के लोग सफाई का काम करने ‘योग्य’ हैं। शिक्षक को क्या करना चाहिए?","optionsHi":["तटस्थ रहना, क्योंकि कक्षा चर्चा में हर मत समान रूप से वैध है और उसका सम्मान होना चाहिए","दृढ़ता से बताना कि यह टिप्पणी समान गरिमा को नकारती है, फिर कक्षा को उसकी जड़ों की जाँच करने में मदद करना","विद्यार्थी को तुरंत कक्षा से बाहर भेज देना और बिना टिप्पणी के अध्याय जारी रखना","टिप्पणी को अनदेखा करना, ताकि चर्चा तनावपूर्ण या विभाजित न हो जाए"],"explanationHi":"भिन्न मतों के प्रति खुलापन उन मतों तक नहीं फैलता जो दूसरों की गरिमा को नकारते हैं; समानता और गरिमा संवैधानिक मूल्य हैं जिन्हें कक्षा को बनाए रखना है। पूर्वाग्रह की जाँच करना चुप्पी या निष्कासन से कहीं अधिक सिखाता है।"},
  {"id":"cdp-pedagogy-subjects-702","question":"Which of the following statements about handling controversial issues in social science are correct?\n1. Ground rules for respectful talk should be agreed before the discussion.\n2. Students should be helped to separate facts, opinions and values.\n3. The teacher must make sure that every student reaches the same conclusion by the end.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Ground rules make the space safe, and separating facts from opinions and values sharpens reasoning. Forcing a common conclusion turns discussion into indoctrination, which is why statement 3 is wrong.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"सामाजिक विज्ञान में विवादास्पद मुद्दों को सँभालने के बारे में निम्नलिखित में से कौन-से कथन सही हैं?\n1. चर्चा से पहले सम्मानजनक बातचीत के लिए ज़मीनी नियम तय होने चाहिए।\n2. विद्यार्थियों को तथ्यों, मतों और मूल्यों को अलग करने में मदद की जानी चाहिए।\n3. शिक्षक को सुनिश्चित करना चाहिए कि अंत तक प्रत्येक विद्यार्थी एक ही निष्कर्ष पर पहुँचे।","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"ज़मीनी नियम स्थान को सुरक्षित बनाते हैं, और तथ्यों को मतों और मूल्यों से अलग करना तर्क को तीक्ष्ण करता है। साझा निष्कर्ष थोपना चर्चा को विचारधारा-रोपण बना देता है, इसीलिए कथन 3 गलत है।"},
  {"id":"cdp-pedagogy-subjects-703","question":"A Class VII student's essay on the Constitution contains these sentences. Which one is an opinion presented as though it were a fact?","options":["The Constitution of India came into force on 26 January 1950.","The Constitution of India is the best constitution in the world.","The Constitution provides for elections to Parliament.","The Constitution has been amended several times since it came into force."],"answer":1,"explanation":"'Best in the world' is a value judgement that cannot be checked like a date or a provision, even if many people hold it. Telling such claims apart from facts is a basic critical-thinking skill.","difficulty":"moderate","source":"CTET Paper 2 · NVS · KVS PRT","questionHi":"संविधान पर कक्षा VII के एक विद्यार्थी के निबंध में ये वाक्य हैं। इनमें से कौन-सा मत है जिसे तथ्य की तरह प्रस्तुत किया गया है?","optionsHi":["भारत का संविधान 26 जनवरी 1950 को लागू हुआ।","भारत का संविधान विश्व का सर्वश्रेष्ठ संविधान है।","संविधान संसद के लिए चुनावों का प्रावधान करता है।","संविधान लागू होने के बाद से कई बार संशोधित किया गया है।"],"explanationHi":"‘विश्व में सर्वश्रेष्ठ’ मूल्य-निर्णय है जिसे किसी तिथि या प्रावधान की तरह जाँचा नहीं जा सकता, भले ही अनेक लोग उसे मानते हों। ऐसे दावों को तथ्यों से अलग पहचानना आलोचनात्मक चिंतन का मूल कौशल है।"},
  {"id":"cdp-pedagogy-subjects-704","question":"Which question on Panchayati Raj is most likely to develop critical thinking in Class VIII?","options":["How many seats in panchayats are reserved for women under the 73rd Constitutional Amendment Act?","Who heads the gram panchayat, and for how many years is she elected?","Why might a woman sarpanch's husband attend meetings in her place, and what could change this?","Name the three tiers of Panchayati Raj and the body at each level."],"answer":2,"explanation":"The third question asks students to explain a gap between the law and practice and to suggest remedies, which calls for analysis and evaluation. The others ask for facts given in the textbook.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"पंचायती राज पर कक्षा VIII में कौन-सा प्रश्न आलोचनात्मक चिंतन विकसित करने की सबसे अधिक संभावना रखता है?","optionsHi":["73वें संविधान संशोधन अधिनियम के अंतर्गत पंचायतों में महिलाओं के लिए कितनी सीटें आरक्षित हैं?","ग्राम पंचायत का प्रधान कौन होता है, और वह कितने वर्षों के लिए चुना जाता है?","महिला सरपंच के स्थान पर उसका पति बैठकों में क्यों जाता होगा, और इसे क्या बदल सकता है?","पंचायती राज के तीन स्तरों के नाम बताइए और प्रत्येक स्तर पर निकाय का नाम बताइए।"],"explanationHi":"तीसरा प्रश्न विद्यार्थियों से कानून और व्यवहार के बीच के अंतर की व्याख्या करने और उपाय सुझाने को कहता है, जिसके लिए विश्लेषण और मूल्यांकन चाहिए। अन्य प्रश्न पाठ्यपुस्तक में दिए तथ्य माँगते हैं।"},
  {"id":"cdp-pedagogy-subjects-705","question":"A Class VII teacher asks, 'Should our town allow a shopping mall to replace the weekly market? Give reasons for your answer.' In Bloom's revised taxonomy, this question is mainly at which level?","options":["Remembering","Understanding","Applying","Evaluating"],"answer":3,"explanation":"The question asks students to judge between alternatives and justify their stand, which is evaluation. It cannot be answered by recalling or explaining information alone.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा VII का एक शिक्षक पूछता है, ‘क्या हमारे कस्बे को साप्ताहिक बाज़ार की जगह शॉपिंग मॉल की अनुमति देनी चाहिए? अपने उत्तर के कारण दीजिए।’ ब्लूम के संशोधित वर्गीकरण में यह प्रश्न मुख्यतः किस स्तर का है?","optionsHi":["याद करना","समझना","अनुप्रयोग","मूल्यांकन"],"explanationHi":"प्रश्न विद्यार्थियों से विकल्पों के बीच निर्णय करने और अपने पक्ष को उचित ठहराने को कहता है, जो मूल्यांकन है। इसका उत्तर केवल जानकारी याद करके या समझाकर नहीं दिया जा सकता।"},
  {"id":"cdp-pedagogy-subjects-706","question":"Assertion (A): A social science teacher should not use the classroom to promote any particular political party.\nReason (R): Social science should avoid discussing current political issues altogether.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"Partisan teaching violates the student's right to reach independent views, so A is true. But current political issues are legitimate and valuable content when handled fairly, so R is false.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): सामाजिक विज्ञान के शिक्षक को कक्षा का उपयोग किसी विशेष राजनीतिक दल को बढ़ावा देने के लिए नहीं करना चाहिए।\nकारण (R): सामाजिक विज्ञान को वर्तमान राजनीतिक मुद्दों की चर्चा से पूरी तरह बचना चाहिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"पक्षपातपूर्ण शिक्षण विद्यार्थी के स्वतंत्र विचार बनाने के अधिकार का उल्लंघन करता है, इसलिए A सत्य है। परंतु वर्तमान राजनीतिक मुद्दे निष्पक्षता से सँभाले जाने पर वैध और मूल्यवान विषयवस्तु हैं, इसलिए R असत्य है।"},
  {"id":"cdp-pedagogy-subjects-707","question":"Assertion (A): Avoiding every controversial issue does not make a social science classroom neutral.\nReason (R): Silence on social issues leaves prejudices unexamined and quietly accepts the way things are.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Choosing not to discuss inequality or conflict is itself a choice with consequences: existing prejudices go unchallenged. That is exactly why avoidance is not neutral, so R explains A.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"अभिकथन (A): हर विवादास्पद मुद्दे से बचना सामाजिक विज्ञान की कक्षा को तटस्थ नहीं बनाता।\nकारण (R): सामाजिक मुद्दों पर चुप्पी पूर्वाग्रहों को अजाँचा छोड़ देती है और चीज़ें जैसी हैं उन्हें चुपचाप स्वीकार कर लेती है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"असमानता या संघर्ष की चर्चा न करना स्वयं एक चुनाव है जिसके परिणाम होते हैं: मौजूदा पूर्वाग्रहों को चुनौती नहीं मिलती। इसीलिए बचना तटस्थ नहीं है, इसलिए R, A की व्याख्या करता है।"},
  {"id":"cdp-pedagogy-subjects-708","question":"Class XII history students in an Amritsar school are studying Partition. Several students' grandparents lived through it. Which approach is the most appropriate?","options":["Use only official statistics and records, so that emotions do not enter the lesson at all","Present the account of one community, since it is closest to the students' own families","Use personal accounts from different sides, focus on human experience, and avoid blaming communities today","Skip Partition, since it is too painful a topic for students with family connections to it"],"answer":2,"explanation":"Testimonies from several sides build empathy and an understanding of Partition's human cost, while avoiding blame on today's communities prevents old wounds from becoming new prejudice. One-sided accounts or omission both fail the learners.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"अमृतसर के एक विद्यालय में कक्षा XII के इतिहास के विद्यार्थी विभाजन का अध्ययन कर रहे हैं। कई विद्यार्थियों के दादा-दादी ने उसे झेला है। कौन-सा उपागम सबसे उपयुक्त है?","optionsHi":["केवल आधिकारिक आँकड़ों और अभिलेखों का प्रयोग करना, ताकि भावनाएँ पाठ में बिल्कुल न आएँ","एक समुदाय का वृत्तांत प्रस्तुत करना, क्योंकि वह विद्यार्थियों के अपने परिवारों के सबसे निकट है","विभिन्न पक्षों के व्यक्तिगत वृत्तांतों का प्रयोग करना, मानवीय अनुभव पर ध्यान देना, और आज के समुदायों को दोष देने से बचना","विभाजन को छोड़ देना, क्योंकि जिन विद्यार्थियों के परिवार उससे जुड़े हैं उनके लिए यह बहुत पीड़ादायक विषय है"],"explanationHi":"कई पक्षों की गवाहियाँ सहानुभूति और विभाजन की मानवीय कीमत की समझ बनाती हैं, जबकि आज के समुदायों को दोष देने से बचना पुराने घावों को नए पूर्वाग्रह में बदलने से रोकता है। एकतरफा वृत्तांत या चूक दोनों शिक्षार्थियों को विफल करते हैं।"},
  {"id":"cdp-pedagogy-subjects-709","question":"A Class VIII teacher asks students to write a diary entry as a Bengal indigo cultivator of the 1850s, using details from the sources they have studied. Which aim does this activity serve best?","options":["Historical empathy: understanding past people in their own context, based on evidence","Creative writing practice, without any need for the details to be historically accurate","Judging the cultivators of the 1850s by today's values and standards","Memorising the chronology and main leaders of the Indigo Revolt"],"answer":0,"explanation":"Historical empathy means reconstructing how people saw their world, anchored in sources. It is neither free fiction nor 'presentism', which judges the past only by present standards.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा VIII का एक शिक्षक विद्यार्थियों से अध्ययन किए गए स्रोतों के विवरणों का उपयोग करते हुए 1850 के दशक के बंगाल के नील किसान के रूप में डायरी प्रविष्टि लिखने को कहता है। यह गतिविधि किस उद्देश्य की सबसे अच्छी पूर्ति करती है?","optionsHi":["ऐतिहासिक सहानुभूति: अतीत के लोगों को उनके अपने संदर्भ में, साक्ष्य के आधार पर समझना","रचनात्मक लेखन का अभ्यास, विवरणों के ऐतिहासिक रूप से सटीक होने की किसी आवश्यकता के बिना","1850 के दशक के किसानों को आज के मूल्यों और मानकों से आँकना","नील विद्रोह का कालक्रम और प्रमुख नेता याद करना"],"explanationHi":"ऐतिहासिक सहानुभूति का अर्थ है यह पुनर्निर्मित करना कि लोग अपने संसार को कैसे देखते थे, स्रोतों में टिकाकर। यह न मुक्त कल्पना है, न ‘वर्तमानवाद’ (presentism), जो अतीत को केवल वर्तमान मानकों से आँकता है।"},
  {"id":"cdp-pedagogy-subjects-710","question":"A Class VI student remarks that people in the 16th century 'were foolish because they did not use electricity'. What thinking skill should the teacher help the student develop?","options":["Memorising the date on which electricity was discovered and by whom","Understanding people of the past in their own context, not by present-day knowledge","Accepting that people in the past were less intelligent than people today","Comparing the prices of everyday goods in the past and present to see how life has changed"],"answer":1,"explanation":"The remark judges the past by present standards, an error called presentism. Seeing what people knew and could do in their own time is the basis of historical understanding.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"कक्षा VI का एक विद्यार्थी टिप्पणी करता है कि 16वीं शताब्दी के लोग ‘मूर्ख थे क्योंकि वे बिजली का उपयोग नहीं करते थे’। शिक्षक को विद्यार्थी में कौन-सा चिंतन कौशल विकसित करने में मदद करनी चाहिए?","optionsHi":["वह तिथि और किसके द्वारा बिजली की खोज हुई, यह याद करना","अतीत के लोगों को उनके अपने संदर्भ में समझना, आज के ज्ञान से नहीं","यह स्वीकार करना कि अतीत के लोग आज के लोगों से कम बुद्धिमान थे","अतीत और वर्तमान में दैनिक वस्तुओं के दामों की तुलना करना यह देखने के लिए कि जीवन कैसे बदला है"],"explanationHi":"यह टिप्पणी अतीत को वर्तमान मानकों से आँकती है, जिस त्रुटि को वर्तमानवाद कहते हैं। यह देखना कि लोग अपने समय में क्या जानते और कर सकते थे, ऐतिहासिक समझ का आधार है।"},
  {"id":"cdp-pedagogy-subjects-711","question":"A textbook picture shows an Adivasi man only in traditional dress at a festival dance. A student in a Bhubaneswar school asks, 'Do Adivasis go to college?' What should the teacher do?","options":["Say that Adivasis mostly prefer to stay in forest villages and so do not need to go to college","Move on, since the question is not in the syllabus and may distract the class","Correct the student for asking a rude question about a community in class","Discuss how one image can create a stereotype, and show the varied lives of Adivasis today"],"answer":3,"explanation":"The question reveals a stereotype built from limited images. Showing diverse, contemporary Adivasi lives challenges it, which is part of NCF 2005's concern with representing marginalised groups fairly.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"पाठ्यपुस्तक का एक चित्र एक आदिवासी पुरुष को केवल उत्सव नृत्य में पारंपरिक पोशाक में दिखाता है। भुवनेश्वर के एक विद्यालय का विद्यार्थी पूछता है, ‘क्या आदिवासी कॉलेज जाते हैं?’ शिक्षक को क्या करना चाहिए?","optionsHi":["कहना कि आदिवासी अधिकतर जंगल के गाँवों में रहना पसंद करते हैं और इसलिए उन्हें कॉलेज जाने की आवश्यकता नहीं है","आगे बढ़ जाना, क्योंकि प्रश्न पाठ्यक्रम में नहीं है और कक्षा का ध्यान भटका सकता है","कक्षा में एक समुदाय के बारे में अशिष्ट प्रश्न पूछने के लिए विद्यार्थी को डाँटना","चर्चा करना कि एक चित्र कैसे रूढ़िबद्ध धारणा बना सकता है, और आज के आदिवासियों के विविध जीवन दिखाना"],"explanationHi":"प्रश्न सीमित चित्रों से बनी रूढ़िबद्ध धारणा को प्रकट करता है। आदिवासियों के विविध, समकालीन जीवन दिखाना उसे चुनौती देता है, जो हाशिये के समूहों को निष्पक्ष रूप से प्रस्तुत करने की NCF 2005 की चिंता का हिस्सा है।"},
  {"id":"cdp-pedagogy-subjects-712","question":"A student brings a viral WhatsApp message making dramatic claims about a historical figure. What is the most suitable classroom response?","options":["Ban mobile phones in school so that such messages never reach the classroom","Accept the claims, since the message has been forwarded by so many people","Have students check its author, sources and dates against reliable accounts","Tell students the message is false and move on to the lesson"],"answer":2,"explanation":"Teaching students to verify claims builds a lasting critical skill. Simply declaring the message false still asks students to rely on authority, and popularity is no evidence of truth.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक विद्यार्थी किसी ऐतिहासिक व्यक्तित्व के बारे में नाटकीय दावे करने वाला वायरल व्हाट्सऐप संदेश लाता है। सबसे उपयुक्त कक्षा-प्रतिक्रिया क्या है?","optionsHi":["विद्यालय में मोबाइल फ़ोन प्रतिबंधित करना ताकि ऐसे संदेश कक्षा तक कभी न पहुँचें","दावे स्वीकार कर लेना, क्योंकि संदेश इतने लोगों ने आगे भेजा है","विद्यार्थियों से उसके लेखक, स्रोतों और तिथियों को विश्वसनीय वृत्तांतों से जँचवाना","विद्यार्थियों को बताना कि संदेश झूठा है और पाठ पर आगे बढ़ना"],"explanationHi":"विद्यार्थियों को दावों का सत्यापन करना सिखाना स्थायी आलोचनात्मक कौशल बनाता है। केवल संदेश को झूठा घोषित कर देना भी विद्यार्थियों से अधिकार पर निर्भर रहने को कहता है, और लोकप्रियता सत्य का प्रमाण नहीं है।"},
  {"id":"cdp-pedagogy-subjects-713","question":"Which teacher behaviour most fosters critical thinking during a social science discussion?","options":["Giving the correct answer right after asking a question, to save time for covering more content","Pausing after questions and probing with ‘Why do you think so?’ and ‘What is your evidence?’","Praising only the answers that match the textbook, so students learn what is correct","Calling only on students who have raised their hands quickly, to keep up the pace"],"answer":1,"explanation":"Wait time gives students room to think, and probing for reasons and evidence pushes them beyond first answers. Quick answers, textbook-matching praise and favouring fast responders all reward recall over reasoning.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"सामाजिक विज्ञान की चर्चा के दौरान शिक्षक का कौन-सा व्यवहार आलोचनात्मक चिंतन को सबसे अधिक बढ़ावा देता है?","optionsHi":["प्रश्न पूछने के तुरंत बाद सही उत्तर दे देना, ताकि अधिक विषयवस्तु पूरी करने का समय बचे","प्रश्नों के बाद रुकना और ‘तुम ऐसा क्यों सोचते हो?’ तथा ‘तुम्हारा साक्ष्य क्या है?’ से जाँच करना","केवल उन उत्तरों की प्रशंसा करना जो पाठ्यपुस्तक से मेल खाते हों, ताकि विद्यार्थी जानें कि क्या सही है","केवल उन विद्यार्थियों को बुलाना जिन्होंने जल्दी हाथ उठाया हो, ताकि गति बनी रहे"],"explanationHi":"प्रतीक्षा-समय विद्यार्थियों को सोचने की जगह देता है, और कारण तथा साक्ष्य की जाँच उन्हें पहले उत्तरों से आगे ले जाती है। त्वरित उत्तर, पाठ्यपुस्तक से मेल खाने की प्रशंसा और तेज़ उत्तर देने वालों को प्राथमिकता, सब तर्क के बजाय स्मरण को पुरस्कृत करते हैं।"},
  {"id":"cdp-pedagogy-subjects-714","question":"For a Class X lesson on large dams, a teacher gives groups role cards: a family displaced by the reservoir, a farmer in the irrigated area downstream, a city water board official and an environmental scientist. What is the main learning goal?","options":["To decide which group is right, so that the debate can end with a clear winner","To show that development projects such as large dams bring no real benefits to anyone at all","To memorise the heights and locations of India's major dams","To see that a development project affects groups differently and involves trade-offs"],"answer":3,"explanation":"Stakeholder role cards reveal who gains, who loses and what is traded off, which is central to thinking critically about development. The aim is not to declare a winner or to reject development outright.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा X के बड़े बाँधों के पाठ के लिए एक शिक्षक समूहों को भूमिका-कार्ड देता है: जलाशय से विस्थापित एक परिवार, निचले प्रवाह के सिंचित क्षेत्र का एक किसान, नगर जल बोर्ड का एक अधिकारी और एक पर्यावरण वैज्ञानिक। मुख्य अधिगम लक्ष्य क्या है?","optionsHi":["यह तय करना कि कौन-सा समूह सही है, ताकि बहस एक स्पष्ट विजेता के साथ समाप्त हो","यह दिखाना कि बड़े बाँध जैसी विकास परियोजनाएँ किसी को भी कोई वास्तविक लाभ नहीं देतीं","भारत के प्रमुख बाँधों की ऊँचाइयाँ और स्थान याद करना","यह देखना कि विकास परियोजना अलग-अलग समूहों को अलग तरह से प्रभावित करती है और उसमें समझौते शामिल होते हैं"],"explanationHi":"हितधारक भूमिका-कार्ड प्रकट करते हैं कि किसे लाभ होता है, किसे हानि, और किस चीज़ का समझौता होता है, जो विकास के बारे में आलोचनात्मक रूप से सोचने का केंद्र है। लक्ष्य विजेता घोषित करना या विकास को पूरी तरह नकारना नहीं है।"},
  {"id":"cdp-pedagogy-subjects-715","question":"After a structured discussion on whether exams should be replaced by projects, students ask the Class IX teacher for her own opinion. Which response is most appropriate?","options":["Share her view as one perspective, with reasons, making clear that students may disagree","Refuse ever to share any opinion on any issue, so that she stays neutral","Share her view and tell students to write it in their notebooks as the correct answer for exams","Pretend to agree with whatever the majority of the class thinks, to keep the peace"],"answer":0,"explanation":"After students have reasoned for themselves, a teacher may offer a view if it is clearly one perspective open to challenge. Imposing it, or hiding behind false agreement, undermines honest inquiry.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"इस पर संरचित चर्चा के बाद कि क्या परीक्षाओं की जगह परियोजनाएँ होनी चाहिए, विद्यार्थी कक्षा IX की शिक्षिका से उनकी अपनी राय माँगते हैं। सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["अपना मत एक दृष्टिकोण के रूप में कारणों सहित साझा करना, यह स्पष्ट करते हुए कि विद्यार्थी असहमत हो सकते हैं","किसी भी मुद्दे पर कभी कोई राय साझा करने से इनकार करना, ताकि वह तटस्थ रहे","अपना मत साझा करना और विद्यार्थियों से उसे परीक्षा के सही उत्तर के रूप में अपनी कॉपियों में लिखने को कहना","कक्षा के बहुमत की सोच से सहमत होने का दिखावा करना, ताकि शांति बनी रहे"],"explanationHi":"जब विद्यार्थी स्वयं तर्क कर चुके हों, तब शिक्षक अपना मत दे सकता है, यदि वह स्पष्ट रूप से चुनौती योग्य एक दृष्टिकोण हो। उसे थोपना, या झूठी सहमति के पीछे छिपना ईमानदार जिज्ञासा को कमज़ोर करता है।"},
  {"id":"cdp-pedagogy-subjects-716","question":"A teacher drafts ground rules for discussing sensitive topics in Class VIII. Which proposed rule should she NOT adopt?","options":["Criticise ideas, not the people who hold them","Anyone may say 'pass' when asked about a personal experience","Back your claims with reasons or evidence","Every student must state their family's views on each issue"],"answer":3,"explanation":"Forcing students to reveal personal or family positions can expose and hurt them; the right to pass protects them. The other rules keep discussion respectful and reasoned.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS","questionHi":"एक शिक्षिका कक्षा VIII में संवेदनशील विषयों पर चर्चा के लिए ज़मीनी नियम बनाती है। उसे कौन-सा प्रस्तावित नियम नहीं अपनाना चाहिए?","optionsHi":["विचारों की आलोचना करो, उन्हें रखने वाले लोगों की नहीं","व्यक्तिगत अनुभव के बारे में पूछे जाने पर कोई भी ‘पास’ कह सकता है","अपने दावों को कारणों या साक्ष्य से पुष्ट करो","प्रत्येक विद्यार्थी को हर मुद्दे पर अपने परिवार के विचार बताने होंगे"],"explanationHi":"विद्यार्थियों को व्यक्तिगत या पारिवारिक मत बताने के लिए बाध्य करना उन्हें उजागर कर सकता है और आहत कर सकता है; ‘पास’ कहने का अधिकार उनकी रक्षा करता है। अन्य नियम चर्चा को सम्मानजनक और तर्कसंगत रखते हैं।"},
  {"id":"cdp-pedagogy-subjects-717","question":"After communal violence in their district, Class IX students in a government school start talking about it angrily in class. What is the most appropriate response for the social science teacher?","options":["Gently return to the syllabus and suggest that students talk it over calmly with their families","Acknowledge feelings, keep to verified facts and constitutional values, blame no community","Hold a class debate on which side was more at fault, so that every view gets a hearing","Ask the school counsellor to handle the matter so that the lesson is not disturbed"],"answer":1,"explanation":"A safe, fact-based discussion anchored in constitutional values helps students process real events without deepening divisions. A debate on which side was at fault seems fair but invites blaming communities, while redirecting or handing over to the counsellor leaves rumours unaddressed in the classroom.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"अपने ज़िले में सांप्रदायिक हिंसा के बाद एक सरकारी विद्यालय की कक्षा IX के विद्यार्थी कक्षा में उस पर क्रोध से बात करने लगते हैं। सामाजिक विज्ञान के शिक्षक की सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["धीरे से पाठ्यक्रम पर लौटना और सुझाव देना कि विद्यार्थी परिवारों के साथ शांति से इस पर बात करें","भावनाओं को स्वीकार करना, सत्यापित तथ्यों और संवैधानिक मूल्यों पर टिके रहना, किसी समुदाय को दोष न देना","कक्षा में बहस कराना कि कौन-सा पक्ष अधिक दोषी था, ताकि हर मत को सुना जाए","विद्यालय के परामर्शदाता से मामला सँभालने को कहना ताकि पाठ में बाधा न आए"],"explanationHi":"संवैधानिक मूल्यों पर टिकी सुरक्षित, तथ्य-आधारित चर्चा विद्यार्थियों को विभाजन गहरा किए बिना वास्तविक घटनाओं को समझने में मदद करती है। कौन-सा पक्ष दोषी था इस पर बहस निष्पक्ष लगती है पर समुदायों को दोष देने को आमंत्रित करती है, जबकि विषय बदलना या परामर्शदाता को सौंपना अफवाहों को कक्षा में अनसुलझा छोड़ देता है।"},
  {"id":"cdp-pedagogy-subjects-718","question":"A Class VIII teacher, while teaching about caste discrimination, also covers the work of Jotirao Phule, Savitribai Phule and B. R. Ambedkar and the movements against untouchability. Why is this important?","options":["It shows that marginalised groups were not only victims but also resisted and worked for change","It proves that caste discrimination ended completely once these reform movements had finally succeeded","It lets the teacher skip the uncomfortable discussion of discrimination itself","It is required only because these names appear often in examination questions"],"answer":0,"explanation":"Presenting resistance and reform restores agency to marginalised people and shows how social change happens. Claiming that discrimination simply ended would be historically untrue.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"जातिगत भेदभाव पढ़ाते हुए कक्षा VIII का एक शिक्षक जोतिराव फुले, सावित्रीबाई फुले और बी. आर. आंबेडकर के कार्य तथा अस्पृश्यता के विरुद्ध आंदोलनों को भी शामिल करता है। यह महत्त्वपूर्ण क्यों है?","optionsHi":["यह दिखाता है कि हाशिये के समूह केवल पीड़ित नहीं थे, बल्कि उन्होंने प्रतिरोध किया और परिवर्तन के लिए काम किया","यह सिद्ध करता है कि इन सुधार आंदोलनों के अंततः सफल होने पर जातिगत भेदभाव पूरी तरह समाप्त हो गया","यह शिक्षक को भेदभाव की असुविधाजनक चर्चा को ही छोड़ देने देता है","यह केवल इसलिए आवश्यक है कि ये नाम परीक्षा प्रश्नों में अक्सर आते हैं"],"explanationHi":"प्रतिरोध और सुधार को प्रस्तुत करना हाशिये के लोगों को कर्तृत्व वापस देता है और दिखाता है कि सामाजिक परिवर्तन कैसे होता है। यह कहना कि भेदभाव बस समाप्त हो गया, ऐतिहासिक रूप से असत्य होगा।"},
  {"id":"cdp-pedagogy-subjects-719","question":"A Class IX teacher shows a political cartoon on the Emergency and asks students to identify its symbols, its message and whose viewpoint it represents. Which skill is mainly being developed?","options":["Drawing skills for making cartoons","Memorising the dates and events of the Emergency","Critical reading of a visual text and its perspective","Appreciation of humour and satire purely for its own sake"],"answer":2,"explanation":"Cartoons are compressed arguments. Decoding symbols, message and viewpoint is critical visual reading, a skill that transfers to all media.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा IX का एक शिक्षक आपातकाल पर एक राजनीतिक कार्टून दिखाता है और विद्यार्थियों से उसके प्रतीक, उसका संदेश और वह किसका दृष्टिकोण प्रस्तुत करता है, पहचानने को कहता है। मुख्यतः कौन-सा कौशल विकसित हो रहा है?","optionsHi":["कार्टून बनाने के लिए चित्रांकन कौशल","आपातकाल की तिथियाँ और घटनाएँ याद करना","दृश्य पाठ और उसके दृष्टिकोण का आलोचनात्मक पठन","हास्य और व्यंग्य की केवल उसके अपने लिए सराहना"],"explanationHi":"कार्टून संक्षिप्त तर्क होते हैं। प्रतीकों, संदेश और दृष्टिकोण को पढ़ना आलोचनात्मक दृश्य पठन है, एक ऐसा कौशल जो सभी माध्यमों में स्थानांतरित होता है।"},
  {"id":"cdp-pedagogy-subjects-720","question":"In a Class VII discussion on banning plastic bags in the market, one student argues, 'Shopkeepers will lose customers.' The teacher asks, 'What are you assuming about customers?' The teacher is mainly helping students to:","options":["Memorise the arguments for and against the ban","Avoid taking any position on the issue","Identify the hidden assumptions in an argument","Agree with the shopkeepers' point of view"],"answer":2,"explanation":"The argument assumes customers will go elsewhere rather than carry their own bags. Bringing such assumptions to the surface is a key critical-thinking skill.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"बाज़ार में प्लास्टिक की थैलियों पर प्रतिबंध की कक्षा VII की चर्चा में एक विद्यार्थी तर्क देता है, ‘दुकानदारों के ग्राहक कम हो जाएँगे।’ शिक्षक पूछता है, ‘तुम ग्राहकों के बारे में क्या मान रहे हो?’ शिक्षक मुख्यतः विद्यार्थियों की किसमें मदद कर रहा है?","optionsHi":["प्रतिबंध के पक्ष और विपक्ष के तर्क याद करना","मुद्दे पर कोई भी पक्ष लेने से बचना","किसी तर्क की छिपी हुई धारणाओं को पहचानना","दुकानदारों के दृष्टिकोण से सहमत होना"],"explanationHi":"तर्क मानता है कि ग्राहक अपने थैले लाने के बजाय कहीं और चले जाएँगे। ऐसी धारणाओं को सतह पर लाना आलोचनात्मक चिंतन का प्रमुख कौशल है।"},
  {"id":"cdp-pedagogy-subjects-721","question":"Which of the following statements describe a critical pedagogy approach in social science?\n1. Students are encouraged to question the textbook as well.\n2. Learning is related to the social context of the children.\n3. The teacher's word is the final authority on every interpretation.","options":["1 and 3 only","2 and 3 only","1, 2 and 3","1 and 2 only"],"answer":3,"explanation":"Critical pedagogy invites questioning of all texts and roots learning in students' social reality. Treating the teacher as the final authority is the 'banking' model it rejects.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"निम्नलिखित में से कौन-से कथन सामाजिक विज्ञान में आलोचनात्मक शिक्षणशास्त्र उपागम का वर्णन करते हैं?\n1. विद्यार्थियों को पाठ्यपुस्तक पर भी प्रश्न उठाने के लिए प्रोत्साहित किया जाता है।\n2. अधिगम को बच्चों के सामाजिक संदर्भ से जोड़ा जाता है।\n3. शिक्षक का शब्द प्रत्येक व्याख्या पर अंतिम प्राधिकार है।","optionsHi":["केवल 1 और 3","केवल 2 और 3","1, 2 और 3","केवल 1 और 2"],"explanationHi":"आलोचनात्मक शिक्षणशास्त्र सभी पाठों पर प्रश्न उठाने को आमंत्रित करता है और अधिगम को विद्यार्थियों की सामाजिक वास्तविकता में जमाता है। शिक्षक को अंतिम प्राधिकार मानना ‘बैंकिंग’ मॉडल है जिसे वह अस्वीकार करता है।"},
  {"id":"cdp-pedagogy-subjects-722","question":"Which question would best develop critical thinking in a Class VI lesson on diversity?","options":["Why do people sometimes form wrong ideas about speakers of other languages, and how can these change?","Name the folk dances of any four states of India and the occasions for each.","How many languages are spoken in India, and which are listed in the Constitution?","Which festival is celebrated in Punjab in April, and what crop does it mark?"],"answer":0,"explanation":"Exploring how prejudice forms and changes requires reasoning about causes and solutions. The other questions ask for facts about diversity rather than thinking about it.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT","questionHi":"विविधता पर कक्षा VI के पाठ में कौन-सा प्रश्न आलोचनात्मक चिंतन को सबसे अच्छी तरह विकसित करेगा?","optionsHi":["लोग कभी-कभी दूसरी भाषाएँ बोलने वालों के बारे में गलत धारणाएँ क्यों बना लेते हैं, और ये कैसे बदल सकती हैं?","भारत के किन्हीं चार राज्यों के लोक नृत्यों के नाम और प्रत्येक के अवसर बताइए।","भारत में कितनी भाषाएँ बोली जाती हैं, और संविधान में कौन-सी सूचीबद्ध हैं?","अप्रैल में पंजाब में कौन-सा त्योहार मनाया जाता है, और वह किस फ़सल को चिह्नित करता है?"],"explanationHi":"यह खोजना कि पूर्वाग्रह कैसे बनता और बदलता है, कारणों और समाधानों के बारे में तर्क करने की माँग करता है। अन्य प्रश्न विविधता के बारे में सोचने के बजाय उसके बारे में तथ्य माँगते हैं।"},
  {"id":"cdp-pedagogy-subjects-723","question":"A Class X student studying district data notices that districts with more roads have higher average incomes and concludes, 'Building roads makes people richer.' What should the teacher help the student consider?","options":["That the conclusion is fully proven, because the data come from an official government source","That correlation alone does not prove cause; richer districts may build more roads instead","That roads have no connection with incomes at all, so the data must be wrong","That data should never be used in social science, since numbers can mislead"],"answer":1,"explanation":"A relationship in data can run in either direction or come from a third factor, such as industry or nearness to cities. Spotting this is high-level critical thinking. Denying any link is also an overreach.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"ज़िलेवार आँकड़े पढ़ता कक्षा X का एक विद्यार्थी देखता है कि अधिक सड़कों वाले ज़िलों में औसत आय अधिक है और निष्कर्ष निकालता है, ‘सड़कें बनाने से लोग अमीर होते हैं।’ शिक्षक को विद्यार्थी को क्या विचार करने में मदद करनी चाहिए?","optionsHi":["कि निष्कर्ष पूरी तरह सिद्ध है, क्योंकि आँकड़े आधिकारिक सरकारी स्रोत से आए हैं","कि केवल सहसंबंध कारण सिद्ध नहीं करता; इसके बजाय अमीर ज़िले अधिक सड़कें बना सकते हैं","कि सड़कों का आय से कोई संबंध ही नहीं है, इसलिए आँकड़े गलत होंगे","कि सामाजिक विज्ञान में आँकड़ों का कभी उपयोग नहीं करना चाहिए, क्योंकि संख्याएँ भ्रमित कर सकती हैं"],"explanationHi":"आँकड़ों में संबंध किसी भी दिशा में चल सकता है या किसी तीसरे कारक, जैसे उद्योग या शहरों से निकटता, से आ सकता है। इसे पहचानना उच्च स्तर का आलोचनात्मक चिंतन है। किसी भी संबंध को नकारना भी अतिशयोक्ति है।"},
  {"id":"cdp-pedagogy-subjects-724","question":"A teacher wants to help Class VIII students judge competing claims about why a river in their state is polluted. Which activity is most effective?","options":["A field visit to the river to record its colour, smell and visible waste in a diary","A class debate in which each team argues the side assigned to it by the teacher","Testing river water with a simple kit and graphing the pH readings over a week","Groups compare claims and evidence from the factory, farmers, board and residents"],"answer":3,"explanation":"Judging competing claims needs students to set each party's claim against evidence. A debate is tempting but rewards persuading for an assigned side rather than weighing evidence, and the field visit and water test show that the river is polluted, not who is responsible.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"एक शिक्षक कक्षा VIII के विद्यार्थियों को यह परखने में मदद करना चाहता है कि उनके राज्य की एक नदी प्रदूषित क्यों है, इसके प्रतिस्पर्धी दावों में से किसे सही माना जाए। कौन-सी गतिविधि सबसे प्रभावी है?","optionsHi":["नदी का क्षेत्र-भ्रमण, डायरी में उसका रंग, गंध और दिखाई देने वाला कचरा दर्ज करना","कक्षा बहस जिसमें प्रत्येक दल शिक्षक द्वारा सौंपे गए पक्ष का तर्क देता है","सरल किट से नदी के पानी की जाँच करना और एक सप्ताह तक pH पाठ्यांकों का आलेख बनाना","समूह कारखाने, किसानों, बोर्ड और निवासियों के दावों और साक्ष्य की तुलना करते हैं"],"explanationHi":"प्रतिस्पर्धी दावों को परखने के लिए विद्यार्थियों को प्रत्येक पक्ष के दावे को साक्ष्य के सामने रखना होता है। बहस आकर्षक है पर साक्ष्य तौलने के बजाय सौंपे गए पक्ष के लिए मनाने को पुरस्कृत करती है, और क्षेत्र-भ्रमण तथा जल-परीक्षण दिखाते हैं कि नदी प्रदूषित है, यह नहीं कि ज़िम्मेदार कौन है।"},
  {"id":"cdp-pedagogy-subjects-725","question":"At the end of the ‘Water’ unit, a Class 5 teacher gives children the words rain, well, river, drinking, farming and scarcity, and asks each child to arrange them as a concept map with linking words on the lines. The main value of this as an assessment is that it:","options":["checks whether children can spell all the key words of the unit correctly","shows how each child links the ideas, including missing or wrong links","produces a neat and colourful chart for the classroom wall","replaces the need for any other assessment for the rest of the unit"],"answer":1,"explanation":"A concept map makes the learner’s web of relationships visible, so gaps and wrong links show up. Spelling and display are incidental, and no single tool should replace all others.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"‘जल’ इकाई के अंत में कक्षा 5 की एक शिक्षिका बच्चों को शब्द वर्षा, कुआँ, नदी, पीने, खेती और कमी देती है और प्रत्येक बच्चे से उन्हें रेखाओं पर जोड़ने वाले शब्दों सहित संप्रत्यय मानचित्र के रूप में व्यवस्थित करने को कहती है। आकलन के रूप में इसका मुख्य मूल्य यह है कि यह:","optionsHi":["जाँचता है कि बच्चे इकाई के सभी मुख्य शब्दों की वर्तनी सही लिख सकते हैं या नहीं","दिखाता है कि प्रत्येक बच्चा विचारों को कैसे जोड़ता है, छूटे या गलत संबंधों सहित","कक्षा की दीवार के लिए साफ और रंगीन चार्ट बनाता है","इकाई के शेष भाग के लिए किसी अन्य आकलन की आवश्यकता समाप्त कर देता है"],"explanationHi":"संप्रत्यय मानचित्र शिक्षार्थी के संबंधों का जाल दृश्य बनाता है, इसलिए कमियाँ और गलत संबंध दिख जाते हैं। वर्तनी और प्रदर्शन आकस्मिक हैं, और कोई एक साधन अन्य सभी की जगह नहीं ले सकता।"},
  {"id":"cdp-pedagogy-subjects-726","question":"In a concept map, the basic unit of meaning, such as ‘Plants → give → oxygen’, is formed by:","options":["a single concept written inside a box or circle","a branch drawn from a central word without any label on it","a line that joins two different maps on one page","two concepts joined by a line with a linking word"],"answer":3,"explanation":"Two concepts plus a labelled link make a proposition, which is what distinguishes a concept map from an unlabelled web. A single box carries no relationship.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"संप्रत्यय मानचित्र में अर्थ की मूल इकाई, जैसे ‘पौधे → देते हैं → ऑक्सीजन’, किससे बनती है?","optionsHi":["किसी खाने या वृत्त के भीतर लिखे एक संप्रत्यय से","केंद्रीय शब्द से खींची गई उस शाखा से जिस पर कोई नामांकन न हो","एक पृष्ठ पर दो अलग मानचित्रों को जोड़ने वाली रेखा से","दो संप्रत्ययों से जो जोड़ने वाले शब्द सहित रेखा से जुड़े हों"],"explanationHi":"दो संप्रत्यय और नामांकित कड़ी एक प्रस्ताव बनाते हैं, जो संप्रत्यय मानचित्र को बिना नामांकन वाले जाल से अलग करता है। अकेला खाना कोई संबंध नहीं रखता।"},
  {"id":"cdp-pedagogy-subjects-727","question":"Consider these statements about concept maps: I. Lines between concepts carry linking words that state the relationship. II. Joseph Novak developed them, drawing on Ausubel’s theory of meaningful learning. III. They should always be drawn by the teacher and only copied by children. Which are correct?","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":0,"explanation":"Novak built concept mapping on Ausubel’s idea that new knowledge must be linked to existing knowledge. Children making their own maps is the point, so III is wrong.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"संप्रत्यय मानचित्रों के बारे में इन कथनों पर विचार कीजिए: I. संप्रत्ययों के बीच की रेखाएँ संबंध बताने वाले जोड़ने वाले शब्द रखती हैं। II. इन्हें जोसेफ नोवाक ने विकसित किया, ऑसुबेल के सार्थक अधिगम के सिद्धांत पर आधारित। III. इन्हें हमेशा शिक्षक को बनाना चाहिए और बच्चों को केवल उतारना चाहिए। कौन-से सही हैं?","optionsHi":["केवल I और II","केवल II और III","केवल I और III","I, II और III"],"explanationHi":"नोवाक ने ऑसुबेल के इस विचार पर संप्रत्यय मानचित्रण बनाया कि नया ज्ञान मौजूदा ज्ञान से जुड़ना चाहिए। बच्चों का अपने मानचित्र बनाना ही मूल बात है, इसलिए III गलत है।"},
  {"id":"cdp-pedagogy-subjects-728","question":"In a Class 4 child’s concept map on water, the only source shown is ‘Water → comes from → tap’, with nothing beyond the tap. The teacher should best treat this as a sign that:","options":["the child is careless and should redo the map neatly, adding many more words to it","the child has fully understood the sources of water, since taps supply most homes","the child's idea of water's source stops at the tap, so tracing tap water back is needed","concept maps are unsuitable for Class 4 children and should be dropped"],"answer":2,"explanation":"The map shows where the child’s understanding ends. A follow-up (tracing pipes to a tank, well or river) can extend it; the map has done its diagnostic job.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"जल पर कक्षा 4 के एक बच्चे के संप्रत्यय मानचित्र में दिखाया गया एकमात्र स्रोत ‘पानी → आता है → नल से’ है, नल से आगे कुछ नहीं। शिक्षक को इसे सबसे अच्छी तरह किसका संकेत मानना चाहिए?","optionsHi":["बच्चा लापरवाह है और उसे मानचित्र साफ-साफ फिर बनाना चाहिए, उसमें बहुत से और शब्द जोड़कर","बच्चे ने पानी के स्रोत पूरी तरह समझ लिए हैं, क्योंकि अधिकांश घरों में नल से पानी आता है","बच्चे का पानी के स्रोत का विचार नल पर रुक जाता है, इसलिए नल के पानी को उसके मूल तक खोजना आवश्यक है","संप्रत्यय मानचित्र कक्षा 4 के बच्चों के लिए अनुपयुक्त हैं और उन्हें छोड़ देना चाहिए"],"explanationHi":"मानचित्र दिखाता है कि बच्चे की समझ कहाँ समाप्त होती है। अनुवर्ती कार्य (पाइपों को टंकी, कुएँ या नदी तक खोजना) उसे बढ़ा सकता है; मानचित्र ने अपना निदानात्मक काम कर दिया है।"},
  {"id":"cdp-pedagogy-subjects-729","question":"In a concept map on ‘Food’, a Class 5 child draws a line from ‘Farmer’, under the branch ‘Where food comes from’, to ‘Hunger’, under the branch ‘Who does not get enough food’, labelled ‘sometimes also faces’. Such a cross-link mainly shows:","options":["the ability to connect ideas across branches, a sign of deeper, integrated understanding","confusion, since each branch of a concept map should always stay separate from the others","a drawing mistake that the teacher should erase so the map looks tidy","memorisation of a textbook sentence about farmers and food"],"answer":0,"explanation":"Novak treated meaningful cross-links between branches as evidence of integrative, creative thinking. Here the child sees the irony that food producers may go hungry.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"‘भोजन’ पर संप्रत्यय मानचित्र में कक्षा 5 की एक बच्ची शाखा ‘भोजन कहाँ से आता है’ के अंतर्गत ‘किसान’ से शाखा ‘किसे पर्याप्त भोजन नहीं मिलता’ के अंतर्गत ‘भूख’ तक ‘कभी-कभी सामना भी करता है’ नामांकित रेखा खींचती है। ऐसी अंतर-कड़ी मुख्यतः क्या दर्शाती है?","optionsHi":["शाखाओं के पार विचारों को जोड़ने की क्षमता, जो गहरी, एकीकृत समझ का संकेत है","भ्रम, क्योंकि संप्रत्यय मानचित्र की प्रत्येक शाखा को हमेशा दूसरों से अलग रहना चाहिए","चित्रांकन की गलती जिसे शिक्षक को मिटा देना चाहिए ताकि मानचित्र साफ दिखे","किसानों और भोजन के बारे में पाठ्यपुस्तक के वाक्य का स्मरण"],"explanationHi":"नोवाक शाखाओं के बीच अर्थपूर्ण अंतर-कड़ियों को एकीकृत, रचनात्मक चिंतन का साक्ष्य मानते थे। यहाँ बच्ची विडंबना देखती है कि भोजन उत्पादक भूखे भी रह सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-730","question":"Before beginning the theme ‘Shelter’, a teacher draws a web around the word with branches such as materials, climate, people who build, animal homes and people without homes. The main purpose of this web is to:","options":["give children a ready-made summary of the whole theme to memorise for the test","decide which pages of the textbook can safely be skipped this term","test whether children already know the meanings of these words","plan links and activities across the natural and social sides of the theme"],"answer":3,"explanation":"A thematic web is a planning tool for the teacher to see how a theme branches into science, social and ethical questions and to design activities that link them.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"‘आश्रय’ विषय शुरू करने से पहले एक शिक्षक शब्द के चारों ओर सामग्री, जलवायु, बनाने वाले लोग, पशुओं के घर और बेघर लोग जैसी शाखाओं वाला जाल बनाता है। इस जाल का मुख्य उद्देश्य है:","optionsHi":["बच्चों को परीक्षा के लिए रटने हेतु पूरे विषय का तैयार सार देना","यह तय करना कि इस सत्र में पाठ्यपुस्तक के कौन-से पृष्ठ सुरक्षित रूप से छोड़े जा सकते हैं","यह परखना कि बच्चे इन शब्दों के अर्थ पहले से जानते हैं या नहीं","विषय के प्राकृतिक और सामाजिक पक्षों के पार संबंधों और गतिविधियों की योजना बनाना"],"explanationHi":"विषयगत जाल शिक्षक के लिए योजना का साधन है, यह देखने के लिए कि कोई विषय विज्ञान, समाज और नैतिक प्रश्नों में कैसे शाखित होता है और उन्हें जोड़ने वाली गतिविधियाँ बनाना।"},
  {"id":"cdp-pedagogy-subjects-731","question":"A Class 3 teacher wants children who cannot yet write fluently to make concept maps. The best adaptation is to:","options":["leave concept maps aside until the children can write full sentences fluently on their own","let children arrange picture cards and say the links aloud while the teacher writes them","give them a completed map drawn by the teacher to colour in","let only the good writers make maps while the others watch and learn"],"answer":1,"explanation":"The thinking in a concept map is about relationships, not writing. Pictures and spoken links keep the thinking while removing the writing barrier, and every child takes part.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 3 की एक शिक्षिका चाहती है कि जो बच्चे अभी धाराप्रवाह नहीं लिख सकते वे संप्रत्यय मानचित्र बनाएँ। सबसे अच्छा अनुकूलन है:","optionsHi":["संप्रत्यय मानचित्र तब तक किनारे रखना जब तक बच्चे स्वयं पूरे वाक्य धाराप्रवाह न लिख सकें","बच्चों को चित्र-कार्ड व्यवस्थित करने देना और कड़ियाँ ज़ोर से बोलने देना जबकि शिक्षिका उन्हें लिखती है","उन्हें शिक्षिका द्वारा बनाया पूरा मानचित्र देना जिसमें वे रंग भरें","केवल अच्छा लिखने वालों को मानचित्र बनाने देना जबकि बाकी देखकर सीखें"],"explanationHi":"संप्रत्यय मानचित्र की सोच संबंधों के बारे में है, लिखने के बारे में नहीं। चित्र और बोली गई कड़ियाँ सोच को बनाए रखती हैं और लेखन की बाधा हटाती हैं, और हर बच्चा भाग लेता है।"},
  {"id":"cdp-pedagogy-subjects-732","question":"Which activity best uses the school’s surroundings for learning about plants in Class 3?","options":["Copying the names of ten common trees from the textbook into notebooks","Showing photographs of famous trees from other countries on a screen","Each group ‘adopting’ a tree in the compound and recording its changes through the year","Learning the parts of a plant from a labelled chart and drawing them"],"answer":2,"explanation":"Sustained observation of a real tree across seasons builds observation, recording and questioning, all rooted in the local environment. The others are second-hand.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 में पौधों के बारे में सीखने के लिए विद्यालय के परिवेश का उपयोग किस गतिविधि से सबसे अच्छी तरह होता है?","optionsHi":["पाठ्यपुस्तक से दस आम पेड़ों के नाम कॉपियों में उतारना","स्क्रीन पर अन्य देशों के प्रसिद्ध पेड़ों की तस्वीरें दिखाना","प्रत्येक समूह द्वारा परिसर के एक पेड़ को ‘गोद लेना’ और वर्ष भर उसके परिवर्तन दर्ज करना","नामांकित चार्ट से पौधे के भाग सीखना और उन्हें बनाना"],"explanationHi":"ऋतुओं भर एक वास्तविक पेड़ का निरंतर अवलोकन अवलोकन, अभिलेखन और प्रश्न पूछने की क्षमता बनाता है, जो सब स्थानीय पर्यावरण में जड़ें रखता है। अन्य गतिविधियाँ अप्रत्यक्ष हैं।"},
  {"id":"cdp-pedagogy-subjects-733","question":"Class 4 children visit the weekly haat and note where each vegetable comes from and how its price changes from season to season. The main EVS learning here is the link between:","options":["food, farmers, transport and the seasons","shopping and good manners in the market","prices and profit making in a business","vegetables and their scientific names in Latin"],"answer":0,"explanation":"Tracing vegetables from field to haat and across seasons connects the ‘Food’ theme to work, travel and climate. It is not about trade profits or naming.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 4 के बच्चे साप्ताहिक हाट जाते हैं और नोट करते हैं कि प्रत्येक सब्ज़ी कहाँ से आती है और ऋतु-दर-ऋतु उसका दाम कैसे बदलता है। यहाँ का मुख्य EVS अधिगम किनके बीच का संबंध है?","optionsHi":["भोजन, किसान, परिवहन और ऋतुएँ","खरीदारी और बाज़ार में अच्छा व्यवहार","दाम और व्यापार में लाभ कमाना","सब्ज़ियाँ और लैटिन में उनके वैज्ञानिक नाम"],"explanationHi":"सब्ज़ियों को खेत से हाट तक और ऋतुओं भर खोजना ‘भोजन’ विषय को काम, यात्रा और जलवायु से जोड़ता है। यह व्यापार के लाभ या नाम देने के बारे में नहीं है।"},
  {"id":"cdp-pedagogy-subjects-734","question":"Class 5 children ask their grandparents how water was collected and stored in the village in the past, such as in johads and kunds. Which of these is NOT a benefit of this activity?","options":["It shows children how life and resources have changed over time","It values the knowledge of elders in the community","It connects traditional practices with present water problems","It makes the EVS textbook unnecessary for the rest of the year"],"answer":3,"explanation":"Elders’ knowledge enriches the textbook but does not replace it. Change over time, respect for community knowledge and links to present issues are real benefits.","difficulty":"hard","source":"CTET Paper 1 · REET Level 1","questionHi":"कक्षा 5 के बच्चे अपने दादा-दादी से पूछते हैं कि अतीत में गाँव में पानी कैसे इकट्ठा और संग्रहित किया जाता था, जैसे जोहड़ों और कुंडों में। इनमें से कौन-सा इस गतिविधि का लाभ नहीं है?","optionsHi":["यह बच्चों को दिखाता है कि जीवन और संसाधन समय के साथ कैसे बदले हैं","यह समुदाय के बुज़ुर्गों के ज्ञान को महत्त्व देता है","यह पारंपरिक प्रथाओं को वर्तमान जल समस्याओं से जोड़ता है","यह वर्ष के शेष भाग के लिए EVS पाठ्यपुस्तक को अनावश्यक बना देता है"],"explanationHi":"बुज़ुर्गों का ज्ञान पाठ्यपुस्तक को समृद्ध करता है पर उसकी जगह नहीं लेता। समय के साथ परिवर्तन, सामुदायिक ज्ञान के प्रति सम्मान और वर्तमान मुद्दों से जुड़ाव वास्तविक लाभ हैं।"},
  {"id":"cdp-pedagogy-subjects-735","question":"Assertion (A): Drawing on the local environment in EVS helps children who have little exposure to books take part meaningfully. Reason (R): Children from every background come to school with rich knowledge of their own surroundings. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Because every child knows her surroundings, starting from them gives first-generation learners a voice that a book-centred class may deny them. R explains A.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): EVS में स्थानीय पर्यावरण का उपयोग उन बच्चों को सार्थक रूप से भाग लेने में मदद करता है जिनका पुस्तकों से कम संपर्क है। कारण (R): हर पृष्ठभूमि के बच्चे अपने परिवेश का समृद्ध ज्ञान लेकर विद्यालय आते हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"क्योंकि हर बच्चा अपने परिवेश को जानता है, उससे शुरू करना पहली पीढ़ी के शिक्षार्थियों को वह आवाज़ देता है जो पुस्तक-केंद्रित कक्षा उन्हें नकार सकती है। R, A की व्याख्या करता है।"},
  {"id":"cdp-pedagogy-subjects-736","question":"A teacher in a chawl-area school in Mumbai says, ‘There is no environment here to study, only buildings and traffic.’ The best response to this view is that:","options":["she is right, so EVS should be taught mainly through videos of forests, rivers and wildlife","the environment includes built and social surroundings: trains, markets, water supply and work","she should take the children to a national park or a forest every month instead","EVS in cities should be limited to the textbook, since there is no real environment outside to study"],"answer":1,"explanation":"EVS treats the environment as natural, social and cultural. A city neighbourhood is full of material for every theme; ‘environment equals forests’ is a narrow misconception.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"मुंबई के चॉल क्षेत्र के एक विद्यालय की शिक्षिका कहती है, ‘यहाँ अध्ययन करने के लिए कोई पर्यावरण नहीं है, केवल इमारतें और यातायात हैं।’ इस विचार का सबसे अच्छा उत्तर यह है कि:","optionsHi":["वह सही है, इसलिए EVS मुख्यतः जंगलों, नदियों और वन्य जीवों के वीडियो से पढ़ाया जाना चाहिए","पर्यावरण में निर्मित और सामाजिक परिवेश भी शामिल है: रेलगाड़ियाँ, बाज़ार, जल आपूर्ति और काम","उसे इसके बजाय हर महीने बच्चों को राष्ट्रीय उद्यान या जंगल ले जाना चाहिए","शहरों में EVS पाठ्यपुस्तक तक सीमित रहना चाहिए, क्योंकि बाहर अध्ययन के लिए कोई वास्तविक पर्यावरण नहीं है"],"explanationHi":"EVS पर्यावरण को प्राकृतिक, सामाजिक और सांस्कृतिक मानता है। शहर का मोहल्ला हर विषय की सामग्री से भरा है; ‘पर्यावरण का अर्थ जंगल’ एक संकीर्ण भ्रांति है।"},
  {"id":"cdp-pedagogy-subjects-737","question":"A teacher in Tamil Nadu uses Pongal to discuss the harvest, the crops grown locally and the season in which they are reaped. This practice is best described as:","options":["mixing religion into a secular subject, which should be avoided in school","a celebration activity with no real link to EVS learning","linking cultural practice with the natural cycles of crops and seasons","teaching the history of festivals so that it can be tested in examinations"],"answer":2,"explanation":"Harvest festivals mark agricultural and seasonal cycles; using them connects culture with nature in a way children already know. Exploring a festival’s link with farming is not religious instruction.","difficulty":"hard","source":"CTET Paper 1 · TNTET","questionHi":"तमिलनाडु का एक शिक्षक पोंगल के माध्यम से फ़सल कटाई, स्थानीय रूप से उगाई जाने वाली फ़सलों और जिस ऋतु में वे काटी जाती हैं, उस पर चर्चा करता है। इस अभ्यास का सबसे अच्छा वर्णन है:","optionsHi":["धर्म को एक धर्मनिरपेक्ष विषय में मिलाना, जिससे विद्यालय में बचना चाहिए","उत्सव की गतिविधि जिसका EVS अधिगम से कोई वास्तविक संबंध नहीं","सांस्कृतिक प्रथा को फ़सलों और ऋतुओं के प्राकृतिक चक्रों से जोड़ना","त्योहारों का इतिहास पढ़ाना ताकि परीक्षाओं में उसकी जाँच हो सके"],"explanationHi":"फ़सल कटाई के त्योहार कृषि और ऋतु चक्रों को चिह्नित करते हैं; उनका प्रयोग संस्कृति को प्रकृति से उस तरह जोड़ता है जिसे बच्चे पहले से जानते हैं। किसी त्योहार का खेती से संबंध खोजना धार्मिक शिक्षा नहीं है।"},
  {"id":"cdp-pedagogy-subjects-738","question":"Class 5 children make a map of their mohalla, marking the hand pumps, wells and taps and noting which families use each one. Besides map skills such as symbols and direction, this activity helps children to:","options":["memorise the official names of all the local streets, lanes and landmarks by heart","become skilled in land surveying, which may help them get a future job","practise neat colouring within the lines of a drawn map","see how access to water is spread across the area and who must walk farther"],"answer":3,"explanation":"A water-source map turns into a tool for social inquiry about distance, access and fairness, linking spatial skills with the social environment.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के बच्चे अपने मोहल्ले का मानचित्र बनाते हैं, जिसमें हैंडपंप, कुएँ और नल दर्शाते हैं और नोट करते हैं कि कौन-से परिवार प्रत्येक का उपयोग करते हैं। चिह्नों और दिशा जैसे मानचित्र कौशलों के अतिरिक्त, यह गतिविधि बच्चों की किसमें मदद करती है?","optionsHi":["स्थानीय सड़कों, गलियों और स्थलों के आधिकारिक नाम कंठस्थ करना","भूमि सर्वेक्षण में कुशल बनना, जो भविष्य में नौकरी पाने में मदद कर सकता है","बने मानचित्र की रेखाओं के भीतर साफ-सुथरा रंग भरने का अभ्यास","यह देखना कि क्षेत्र में पानी की पहुँच कैसे फैली है और किसे अधिक दूर चलना पड़ता है"],"explanationHi":"जल-स्रोत का मानचित्र दूरी, पहुँच और निष्पक्षता के बारे में सामाजिक जिज्ञासा का साधन बन जाता है, जो स्थानिक कौशलों को सामाजिक पर्यावरण से जोड़ता है।"},
  {"id":"cdp-pedagogy-subjects-739","question":"On a neighbourhood walk, Class 4 children notice that one hand pump is used ‘only by some families’ and that others are not allowed to use it. The teacher should:","options":["move on quickly, since the matter is too sensitive for children","hold a careful discussion on fairness and everyone’s equal right to water","tell the children that this is a local custom that must be respected by all","ask the children to report the families to the police"],"answer":1,"explanation":"EVS aims at concern for justice and equality, and the Constitution forbids denying public water on the basis of caste. A sensitive discussion builds this concern; silence or approval would endorse discrimination.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"पड़ोस की सैर पर कक्षा 4 के बच्चे देखते हैं कि एक हैंडपंप ‘केवल कुछ परिवारों’ द्वारा प्रयोग होता है और दूसरों को उसे प्रयोग करने की अनुमति नहीं है। शिक्षक को चाहिए कि:","optionsHi":["जल्दी आगे बढ़ जाए, क्योंकि मामला बच्चों के लिए बहुत संवेदनशील है","निष्पक्षता और पानी पर सबके समान अधिकार पर सावधानी से चर्चा करे","बच्चों को बताए कि यह स्थानीय प्रथा है जिसका सबको सम्मान करना चाहिए","बच्चों से इन परिवारों की पुलिस में शिकायत करने को कहे"],"explanationHi":"EVS का उद्देश्य न्याय और समानता के प्रति चिंता है, और संविधान जाति के आधार पर सार्वजनिक जल से वंचित करने पर रोक लगाता है। संवेदनशील चर्चा यह चिंता बनाती है; चुप्पी या अनुमोदन भेदभाव का समर्थन करेगा।"},
  {"id":"cdp-pedagogy-subjects-740","question":"Class 5 children prepare a large chart showing, month by month, the local crops sown and harvested, festivals, birds seen and weather. This seasonal calendar mainly helps children to:","options":["integrate observations of the natural and social world over time","memorise the names of the Indian months in order","practise writing information in a table format only","compare their own village with the illustrations given in the textbook"],"answer":0,"explanation":"The calendar brings crops, culture, wildlife and weather together across the year, showing how they depend on one another. That is integration, not rote naming.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 5 के बच्चे एक बड़ा चार्ट तैयार करते हैं जिसमें महीने-दर-महीने स्थानीय फ़सलों की बुवाई और कटाई, त्योहार, देखे गए पक्षी और मौसम दिखाए गए हैं। यह ऋतु-पंचांग मुख्यतः बच्चों की किसमें मदद करता है?","optionsHi":["समय के साथ प्राकृतिक और सामाजिक संसार के अवलोकनों को एकीकृत करना","भारतीय महीनों के नाम क्रम से याद करना","केवल सारणी के रूप में सूचना लिखने का अभ्यास करना","अपने गाँव की तुलना पाठ्यपुस्तक में दिए चित्रों से करना"],"explanationHi":"पंचांग फ़सलों, संस्कृति, वन्य जीवन और मौसम को वर्ष भर एक साथ लाता है, दिखाते हुए कि वे एक-दूसरे पर कैसे निर्भर हैं। यह एकीकरण है, रटकर नाम बताना नहीं।"},
  {"id":"cdp-pedagogy-subjects-741","question":"Consider these statements about using low-cost local materials such as clay, waste cloth and bamboo in EVS: I. They make learning accessible in schools with few resources. II. They connect learning with local crafts and skills. III. They are inferior to commercial kits and should be used only when kits are not available. Which are correct?","options":["I only","III only","I and II only","I, II and III"],"answer":2,"explanation":"Local materials are valued for their own sake, not as a poor substitute: they are accessible, familiar and linked to local work. III expresses a common but wrong assumption.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"EVS में मिट्टी, बेकार कपड़े और बाँस जैसी कम लागत की स्थानीय सामग्रियों के उपयोग के बारे में इन कथनों पर विचार कीजिए: I. वे कम संसाधनों वाले विद्यालयों में अधिगम को सुलभ बनाती हैं। II. वे अधिगम को स्थानीय शिल्पों और कौशलों से जोड़ती हैं। III. वे व्यावसायिक किटों से हीन हैं और केवल तभी प्रयोग की जानी चाहिए जब किट उपलब्ध न हों। कौन-से सही हैं?","optionsHi":["केवल I","केवल III","केवल I और II","I, II और III"],"explanationHi":"स्थानीय सामग्रियाँ अपने आप में मूल्यवान हैं, खराब विकल्प के रूप में नहीं: वे सुलभ, परिचित और स्थानीय कार्य से जुड़ी हैं। III एक आम पर गलत धारणा व्यक्त करता है।"},
  {"id":"cdp-pedagogy-subjects-742","question":"A Class 4 teacher in a flood-prone district of Assam is teaching ‘Shelter’. Which question best uses the local environment to develop analysis?","options":["What is a stilt house? Write its definition in your notebook.","Name the kinds of houses found in different states of India and the materials used in each.","Draw a picture of your house and colour it neatly.","Why do many houses in our village stand on stilts, and what might happen if they did not?"],"answer":3,"explanation":"The question asks children to reason about cause and consequence from what they see every day. The others call for a definition, a list or a drawing.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"असम के बाढ़-प्रवण ज़िले की कक्षा 4 की एक शिक्षिका ‘आश्रय’ पढ़ा रही है। कौन-सा प्रश्न विश्लेषण विकसित करने के लिए स्थानीय पर्यावरण का सबसे अच्छा उपयोग करता है?","optionsHi":["स्टिल्ट घर क्या होता है? अपनी कॉपी में उसकी परिभाषा लिखो।","भारत के विभिन्न राज्यों में पाए जाने वाले घरों के प्रकार और प्रत्येक में प्रयुक्त सामग्री के नाम बताओ।","अपने घर का चित्र बनाओ और उसमें साफ-साफ रंग भरो।","हमारे गाँव में बहुत से घर खंभों पर क्यों खड़े हैं, और यदि न होते तो क्या हो सकता था?"],"explanationHi":"प्रश्न बच्चों से रोज़ देखी चीज़ों से कारण और परिणाम पर तर्क करने को कहता है। अन्य परिभाषा, सूची या चित्र माँगते हैं।"},
  {"id":"cdp-pedagogy-subjects-743","question":"On a nature walk, a Class 2 teacher asks children to describe the sounds and colours they notice and then to make up a short song about them. This is in line with NCF 2005 because in Classes I and II:","options":["EVS is a separate subject that must be assessed through songs and rhymes","children are too young for any form of observation, so songs are used to replace it","EVS concerns are taught through language and activity, not a separate textbook","music is the main subject of the curriculum in the early primary classes"],"answer":2,"explanation":"In Classes I–II, EVS concerns are woven into language and activities. Observing and then expressing in song does exactly this.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"प्रकृति की सैर पर कक्षा 2 की एक शिक्षिका बच्चों से जो ध्वनियाँ और रंग उन्होंने देखे उनका वर्णन करने और फिर उन पर एक छोटा गीत बनाने को कहती है। यह NCF 2005 के अनुरूप है क्योंकि कक्षा I और II में:","optionsHi":["EVS एक अलग विषय है जिसका आकलन गीतों और तुकबंदियों से होना चाहिए","बच्चे किसी भी प्रकार के अवलोकन के लिए बहुत छोटे हैं, इसलिए उसकी जगह गीत प्रयोग होते हैं","EVS की चिंताएँ भाषा और गतिविधि के माध्यम से पढ़ाई जाती हैं, अलग पाठ्यपुस्तक से नहीं","आरंभिक प्राथमिक कक्षाओं में संगीत पाठ्यचर्या का मुख्य विषय है"],"explanationHi":"कक्षा I–II में EVS की चिंताएँ भाषा और गतिविधियों में बुनी जाती हैं। अवलोकन करना और फिर गीत में अभिव्यक्त करना यही करता है।"},
  {"id":"cdp-pedagogy-subjects-744","question":"Class 4 children interview their parents about the work they do. The most suitable follow-up activity is to:","options":["rank the jobs from most to least respectable, so that children understand society","display all kinds of work and discuss how each is needed, building respect for all labour","praise the children whose parents have office jobs, to motivate the others","ask children what job they will do when they grow up, so that they can be grouped by their choice"],"answer":1,"explanation":"EVS aims at dignity of labour and sensitivity to all workers. Ranking jobs or praising some parents reinforces the very hierarchies EVS seeks to question.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 के बच्चे अपने माता-पिता से उनके काम के बारे में साक्षात्कार लेते हैं। सबसे उपयुक्त अनुवर्ती गतिविधि है:","optionsHi":["नौकरियों को सबसे अधिक से सबसे कम सम्माननीय के क्रम में रखना, ताकि बच्चे समाज को समझें","सभी प्रकार के कामों को प्रदर्शित करना और चर्चा करना कि प्रत्येक की आवश्यकता कैसे है, जिससे सभी श्रम के प्रति सम्मान बने","उन बच्चों की प्रशंसा करना जिनके माता-पिता की दफ़्तर की नौकरियाँ हैं, ताकि दूसरों को प्रेरणा मिले","बच्चों से पूछना कि बड़े होकर वे कौन-सा काम करेंगे, ताकि उन्हें उनकी पसंद के अनुसार समूहों में बाँटा जा सके"],"explanationHi":"EVS का उद्देश्य श्रम की गरिमा और सभी कामगारों के प्रति संवेदनशीलता है। नौकरियों को क्रमबद्ध करना या कुछ माता-पिता की प्रशंसा करना उन्हीं पदानुक्रमों को पुष्ट करता है जिन पर EVS प्रश्न उठाना चाहता है।"},
  {"id":"cdp-pedagogy-subjects-745","question":"During a lesson on plants, a Class 4 child says her grandmother uses neem leaves to keep insects away from stored grain. The teacher should best:","options":["treat it as local knowledge worth recording, and help children think how it could be checked","dismiss it, since only the knowledge given in the textbook counts as proper scientific knowledge","tell the class to use neem leaves for every problem with insects at home","note it but tell the child not to bring practices from home into the school"],"answer":0,"explanation":"Local knowledge is a resource in EVS, and children can learn to test claims too. Dismissing it alienates the child; uncritical promotion is equally poor.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"पौधों के पाठ के दौरान कक्षा 4 की एक बच्ची कहती है कि उसकी दादी भंडारित अनाज से कीड़े दूर रखने के लिए नीम की पत्तियों का उपयोग करती हैं। शिक्षक को सबसे अच्छा क्या करना चाहिए?","optionsHi":["इसे स्थानीय ज्ञान मानकर दर्ज करने योग्य समझना, और बच्चों को सोचने में मदद करना कि इसे कैसे जाँचा जा सकता है","इसे खारिज कर देना, क्योंकि केवल पाठ्यपुस्तक में दिया ज्ञान ही उचित वैज्ञानिक ज्ञान माना जाता है","कक्षा से कहना कि घर पर कीड़ों की हर समस्या के लिए नीम की पत्तियों का प्रयोग करें","इसे नोट करना पर बच्ची से कहना कि घर की प्रथाएँ विद्यालय में न लाए"],"explanationHi":"स्थानीय ज्ञान EVS में संसाधन है, और बच्चे दावों को परखना भी सीख सकते हैं। उसे खारिज करना बच्ची को पराया बनाता है; बिना जाँचे बढ़ावा देना भी उतना ही कमज़ोर है।"},
  {"id":"cdp-pedagogy-subjects-746","question":"Instead of giving a talk on saving water, a Class 5 teacher has children check every tap in the school for leaks for a week, measure the water lost in buckets and present their suggestions to the head teacher. This mainly shows:","options":["a punishment activity for children who have wasted water","a mathematics lesson on measurement, unrelated to EVS","a survey whose only aim is to produce a neat chart for the classroom display","learning through action on a real local problem, building responsibility"],"answer":3,"explanation":"Children investigate, measure, analyse and act on their own surroundings, which develops concern and responsibility far better than a lecture.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"जल बचाने पर भाषण देने के बजाय कक्षा 5 की एक शिक्षिका बच्चों से एक सप्ताह तक विद्यालय के हर नल में रिसाव की जाँच करवाती है, खोए पानी को बाल्टियों में मापवाती है और अपने सुझाव प्रधानाध्यापक के सामने प्रस्तुत करवाती है। यह मुख्यतः क्या दर्शाता है?","optionsHi":["पानी बर्बाद करने वाले बच्चों के लिए दंड की गतिविधि","मापन पर गणित का पाठ, जिसका EVS से कोई संबंध नहीं","एक सर्वेक्षण जिसका एकमात्र उद्देश्य कक्षा के प्रदर्शन के लिए साफ चार्ट बनाना है","वास्तविक स्थानीय समस्या पर कार्रवाई के माध्यम से अधिगम, जो उत्तरदायित्व बनाता है"],"explanationHi":"बच्चे अपने परिवेश की जाँच करते, मापते, विश्लेषण करते और उस पर कार्य करते हैं, जो भाषण से कहीं बेहतर चिंता और उत्तरदायित्व विकसित करता है।"},
  {"id":"cdp-pedagogy-subjects-747","question":"Which plan makes the best use of a village pond as an EVS resource for Class 4?","options":["One visit to draw the pond, followed by a written test on pond life","Reading about ponds in the textbook and listing the animals that are usually found in them","Visiting the pond across seasons to record water and birds, who uses it, and what pollutes it","Telling children to stay away from the pond because it is unsafe for them"],"answer":2,"explanation":"Repeated seasonal visits link change over time, living things, human use and pollution, connecting several themes through one local resource.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 4 के लिए EVS के संसाधन के रूप में गाँव के तालाब का सबसे अच्छा उपयोग कौन-सी योजना करती है?","optionsHi":["तालाब का चित्र बनाने के लिए एक यात्रा, उसके बाद तालाब के जीवन पर लिखित परीक्षा","पाठ्यपुस्तक में तालाबों के बारे में पढ़ना और उनमें सामान्यतः पाए जाने वाले जानवरों की सूची बनाना","ऋतुओं भर तालाब जाकर पानी और पक्षियों, उसका उपयोग कौन करता है, और उसे क्या प्रदूषित करता है, यह दर्ज करना","बच्चों से तालाब से दूर रहने को कहना क्योंकि वह उनके लिए असुरक्षित है"],"explanationHi":"बार-बार की ऋतुगत यात्राएँ समय के साथ परिवर्तन, जीवित प्राणियों, मानवीय उपयोग और प्रदूषण को जोड़ती हैं, एक स्थानीय संसाधन के माध्यम से कई विषयों को जोड़ती हैं।"},
  {"id":"cdp-pedagogy-subjects-748","question":"Which statement about using the local environment in EVS is NOT correct?","options":["It helps children build new ideas on what they already know from daily life","Since EVS starts from the local, children need not learn about distant people and places","It allows children to observe, question and investigate things around them directly for themselves","It connects school learning with the life and work of the community"],"answer":1,"explanation":"EVS starts from the local but widens to the distant, so that children can appreciate diversity across India and beyond. Staying only local would keep horizons narrow.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"EVS में स्थानीय पर्यावरण के उपयोग के बारे में कौन-सा कथन सही नहीं है?","optionsHi":["यह बच्चों को दैनिक जीवन से पहले से जानी बातों पर नए विचार बनाने में मदद करता है","चूँकि EVS स्थानीय से शुरू होता है, बच्चों को दूर के लोगों और स्थानों के बारे में सीखने की आवश्यकता नहीं है","यह बच्चों को अपने आसपास की चीज़ों का सीधे स्वयं अवलोकन, प्रश्न और जाँच करने देता है","यह विद्यालयी अधिगम को समुदाय के जीवन और कार्य से जोड़ता है"],"explanationHi":"EVS स्थानीय से शुरू होता है पर दूर की ओर फैलता है, ताकि बच्चे भारत और उससे परे की विविधता की सराहना कर सकें। केवल स्थानीय रहना क्षितिज को संकीर्ण रखेगा।"},
  {"id":"cdp-pedagogy-subjects-749","question":"On a walk through the village, Class 4 children sort the houses they see into kachcha, pucca and mixed, and say what each type is made of. In NCERT’s list of EVS learning indicators, this mainly shows:","options":["Experimentation","Concern for justice and equality","Classification","Questioning"],"answer":2,"explanation":"Grouping things by shared features and comparing them is classification. Observation precedes it, but the sorting itself is the classification indicator.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"गाँव में सैर के दौरान कक्षा 4 के बच्चे जो घर देखते हैं उन्हें कच्चे, पक्के और मिश्रित में छाँटते हैं और बताते हैं कि प्रत्येक प्रकार किससे बना है। NCERT की EVS अधिगम संकेतकों की सूची में यह मुख्यतः क्या दर्शाता है?","optionsHi":["प्रयोग करना","न्याय और समानता के प्रति चिंता","वर्गीकरण","प्रश्न पूछना"],"explanationHi":"वस्तुओं को साझा विशेषताओं के आधार पर समूहबद्ध करना और तुलना करना वर्गीकरण है। अवलोकन उससे पहले आता है, पर छाँटना स्वयं वर्गीकरण का संकेतक है।"},
  {"id":"cdp-pedagogy-subjects-750","question":"Kabir says that no force acts on a book lying on the table, because it is not moving. Which activity makes the 'hidden' upward force most perceptible to him?","options":["Dropping the book from a height and watching it fall, to show that gravity always pulls on it","Placing the book on a thick sponge on his palm and feeling his hand push up as it squashes","Sliding the book across the table to show the force of friction","Weighing the book on a spring balance to find its weight"],"answer":1,"explanation":"Kabir thinks 'at rest' means 'no forces'. Feeling his own hand push up through a squashed sponge makes the supporting force real, so he can see that gravity is balanced, not absent.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कबीर कहता है कि मेज़ पर रखी किताब पर कोई बल नहीं लगता, क्योंकि वह चल नहीं रही। कौन-सी गतिविधि उसके लिए ‘छिपे’ ऊर्ध्वाधर ऊपर की ओर लगने वाले बल को सबसे अधिक अनुभव योग्य बनाती है?","optionsHi":["किताब को ऊँचाई से गिराकर उसे गिरते देखना, यह दिखाने के लिए कि गुरुत्व हमेशा उस पर खिंचाव डालता है","किताब को अपनी हथेली पर रखे मोटे स्पंज पर रखना और उसके दबने पर हाथ को ऊपर धक्का देते महसूस करना","किताब को मेज़ पर सरकाना ताकि घर्षण बल दिखे","किताब को कमानीदार तराज़ू पर तौलकर उसका भार ज्ञात करना"],"explanationHi":"कबीर सोचता है कि ‘विराम’ का अर्थ ‘कोई बल नहीं’ है। दबे हुए स्पंज के माध्यम से अपने हाथ को ऊपर धक्का देते महसूस करना सहारा देने वाले बल को वास्तविक बनाता है, जिससे वह देख सकता है कि गुरुत्व संतुलित है, अनुपस्थित नहीं।"},
  {"id":"cdp-pedagogy-subjects-751","question":"Students believe a rolling ball stops because 'its force gets used up'. The teacher has them roll the same ball with the same push on a carpet, a cement floor and a polished stone floor, measuring how far it goes each time. Which conclusion should the discussion lead them to extend from this pattern?","options":["On a perfectly frictionless surface the ball would stop sooner","On any surface the ball stops at the same point, since its force is fixed","On a perfectly frictionless surface the ball would keep moving without slowing","On a smoother surface the ball would gradually speed up on its own as it rolls along"],"answer":2,"explanation":"Less friction gives a longer run, so extrapolating to zero friction suggests that the ball would not slow down at all. Slowing is caused by an opposing force, not by force 'running out', which is Galileo's line of reasoning.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"विद्यार्थी मानते हैं कि लुढ़कती गेंद इसलिए रुकती है क्योंकि ‘उसका बल खत्म हो जाता है’। शिक्षक उनसे एक ही गेंद को एक ही धक्के से कालीन, सीमेंट के फ़र्श और चमकदार पत्थर के फ़र्श पर लुढ़कवाता है, हर बार मापते हुए कि वह कितनी दूर जाती है। इस पैटर्न से चर्चा को उन्हें कौन-सा निष्कर्ष आगे बढ़ाने की ओर ले जाना चाहिए?","optionsHi":["पूर्णतः घर्षणरहित सतह पर गेंद जल्दी रुक जाएगी","किसी भी सतह पर गेंद उसी बिंदु पर रुकेगी, क्योंकि उसका बल निश्चित है","पूर्णतः घर्षणरहित सतह पर गेंद बिना धीमी हुए चलती रहेगी","अधिक चिकनी सतह पर गेंद लुढ़कते हुए अपने आप धीरे-धीरे तेज़ होती जाएगी"],"explanationHi":"कम घर्षण से दूरी अधिक होती है, इसलिए शून्य घर्षण तक एक्स्ट्रापोलेट करने से संकेत मिलता है कि गेंद बिल्कुल धीमी नहीं होगी। धीमा होना विरोधी बल से होता है, बल ‘खत्म होने’ से नहीं, जो गैलीलियो का तर्क है।"},
  {"id":"cdp-pedagogy-subjects-752","question":"To challenge the belief that 'supplying heat always raises the temperature', a teacher heats crushed ice steadily and has students record its temperature every minute. Which observation directly challenges the belief?","options":["The thermometer stays near 0 °C while the ice melts, even though heat is supplied throughout","The temperature rises steadily from the first minute, showing that heat and temperature always go together","Water droplets collect on the outside of the beaker, showing that heat is passing out through the glass","The ice at the bottom melts faster than the ice at the top, since it is closer to the flame"],"answer":0,"explanation":"While ice melts, the heat supplied goes into changing its state, so the temperature does not rise until all the ice has melted. This breaks the link students make between heat and temperature.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"इस विश्वास को चुनौती देने के लिए कि ‘ऊष्मा देने से तापमान हमेशा बढ़ता है’, एक शिक्षक कुचली बर्फ़ को लगातार गर्म करता है और विद्यार्थियों से हर मिनट उसका तापमान दर्ज करवाता है। कौन-सा अवलोकन इस विश्वास को सीधे चुनौती देता है?","optionsHi":["बर्फ़ के पिघलने के दौरान तापमापी लगभग 0 °C पर बना रहता है, जबकि पूरे समय ऊष्मा दी जा रही है","पहले मिनट से तापमान लगातार बढ़ता है, जो दिखाता है कि ऊष्मा और तापमान हमेशा साथ चलते हैं","बीकर के बाहर पानी की बूँदें जमा हो जाती हैं, जो दिखाता है कि ऊष्मा काँच से बाहर जा रही है","नीचे की बर्फ़ ऊपर की बर्फ़ से तेज़ पिघलती है, क्योंकि वह लौ के अधिक निकट है"],"explanationHi":"जब बर्फ़ पिघलती है, दी गई ऊष्मा उसकी अवस्था बदलने में लगती है, इसलिए सारी बर्फ़ पिघलने तक तापमान नहीं बढ़ता। यह उस संबंध को तोड़ता है जो विद्यार्थी ऊष्मा और तापमान के बीच बनाते हैं।"},
  {"id":"cdp-pedagogy-subjects-753","question":"While teaching about thermometers, a teacher hears students say that 'the thermometer tells us how much heat there is in the water'. Which statement should she help them reach?","options":["A thermometer measures the total heat in the water, so a bucket of water gives a higher reading than a cup","A thermometer measures heat only in liquids, since the mercury must touch the liquid to take its heat","A thermometer measures how much cold is present, while heat itself can only be felt by touching","A thermometer measures temperature, the degree of hotness, which is not the same as the quantity of heat"],"answer":3,"explanation":"A bucket and a cup of water at the same temperature give the same reading although the bucket holds far more heat, so a thermometer reads temperature, not quantity of heat.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs","questionHi":"तापमापी के बारे में पढ़ाते हुए एक शिक्षिका विद्यार्थियों को कहते सुनती है कि ‘तापमापी हमें बताता है कि पानी में कितनी ऊष्मा है’। उसे उन्हें किस कथन तक पहुँचाने में मदद करनी चाहिए?","optionsHi":["तापमापी पानी में कुल ऊष्मा मापता है, इसलिए पानी की बाल्टी का पाठ्यांक कप से अधिक आता है","तापमापी केवल द्रवों में ऊष्मा मापता है, क्योंकि पारे को उसकी ऊष्मा लेने के लिए द्रव को छूना पड़ता है","तापमापी यह मापता है कि कितना ठंडापन मौजूद है, जबकि ऊष्मा केवल छूकर महसूस की जा सकती है","तापमापी तापमान, अर्थात गर्माहट की मात्रा (डिग्री), मापता है, जो ऊष्मा की मात्रा के समान नहीं है"],"explanationHi":"समान तापमान पर पानी की बाल्टी और कप एक ही पाठ्यांक देते हैं, भले ही बाल्टी में कहीं अधिक ऊष्मा हो, इसलिए तापमापी तापमान पढ़ता है, ऊष्मा की मात्रा नहीं।"},
  {"id":"cdp-pedagogy-subjects-754","question":"To show that leaves make starch only in light, a teacher keeps a potted plant in a dark cupboard for two to three days before covering part of a leaf with black paper and placing the plant in sunlight. Why is the plant first kept in the dark?","options":["To make the plant hungry, so that it photosynthesises faster and more strongly once it is placed in light","To use up the starch already present, so that any starch found later must have been newly made","To kill germs on the leaves, so that they do not feed on the starch during the experiment","To soften the leaves in the cool dark, so that the iodine solution can enter them more easily"],"answer":1,"explanation":"Destarching removes old starch; otherwise starch found in the covered part could be left over from before, and the result would not show that light is needed. The 'hungry plant' idea is a misconception.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"यह दिखाने के लिए कि पत्तियाँ मंड केवल प्रकाश में बनाती हैं, एक शिक्षक गमले के पौधे को दो-तीन दिन तक अँधेरी अलमारी में रखता है, फिर पत्ती के एक भाग को काले कागज़ से ढककर पौधे को धूप में रखता है। पौधे को पहले अँधेरे में क्यों रखा जाता है?","optionsHi":["पौधे को भूखा बनाने के लिए, ताकि प्रकाश में रखे जाने पर वह तेज़ और अधिक प्रकाश संश्लेषण करे","पहले से मौजूद मंड को समाप्त करने के लिए, ताकि बाद में मिला कोई भी मंड नया बना हो","पत्तियों पर कीटाणु मारने के लिए, ताकि वे प्रयोग के दौरान मंड न खाएँ","ठंडे अँधेरे में पत्तियों को मुलायम करने के लिए, ताकि आयोडीन विलयन उनमें आसानी से प्रवेश कर सके"],"explanationHi":"मंड-रहित करना पुराने मंड को हटाता है; अन्यथा ढके भाग में मिला मंड पहले का बचा हो सकता है, और परिणाम यह नहीं दिखाएगा कि प्रकाश चाहिए। ‘भूखा पौधा’ का विचार एक भ्रांति है।"},
  {"id":"cdp-pedagogy-subjects-755","question":"Many Class 6 students say that seeds need sunlight to germinate, because 'plants need sunlight to grow'. The most suitable way for the teacher to respond is to:","options":["Have students test soaked seeds kept in light and in a dark box, and compare what happens","Tell them clearly that seeds do not need light, so that the wrong idea is corrected at once","Accept the idea for now, since it is true for grown plants and the difference is too subtle","Show a picture of a seedling growing in sunlight, so that they see where plants grow best"],"answer":0,"explanation":"Letting students test their own idea with a fair comparison turns the misconception into an investigation; seeds germinate in the dark, though the seedlings later need light to make food.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"कक्षा 6 के अनेक विद्यार्थी कहते हैं कि बीजों को अंकुरित होने के लिए सूर्य के प्रकाश की आवश्यकता होती है, क्योंकि ‘पौधों को बढ़ने के लिए सूर्य का प्रकाश चाहिए’। शिक्षक के प्रतिक्रिया देने का सबसे उपयुक्त तरीका है:","optionsHi":["विद्यार्थियों से प्रकाश में और अँधेरे डिब्बे में रखे भीगे बीजों की जाँच करवाना, और क्या होता है उसकी तुलना करना","उन्हें साफ-साफ बताना कि बीजों को प्रकाश नहीं चाहिए, ताकि गलत विचार तुरंत सुधर जाए","विचार को फ़िलहाल स्वीकार कर लेना, क्योंकि यह उगे हुए पौधों के लिए सत्य है और अंतर बहुत सूक्ष्म है","धूप में उगते अंकुर का चित्र दिखाना, ताकि वे देखें कि पौधे सबसे अच्छे कहाँ उगते हैं"],"explanationHi":"विद्यार्थियों को अपने विचार की उचित तुलना से जाँच करने देना भ्रांति को जाँच में बदल देता है; बीज अँधेरे में अंकुरित होते हैं, यद्यपि अंकुरों को बाद में भोजन बनाने के लिए प्रकाश चाहिए।"},
  {"id":"cdp-pedagogy-subjects-756","question":"A teacher gives each group one cell, one bulb and a single piece of wire, and challenges them to light the bulb. Many groups first connect the wire from one terminal of the cell to the bulb and expect it to glow. The main value of this challenge is that it:","options":["Saves the cost of extra wires, so that every group can do the activity with very little material","Shows students that some bulbs are faulty, so they learn to check each part before building a circuit","Exposes the 'one wire is enough' idea and lets students discover that a complete loop is needed","Teaches students the correct symbols for circuit diagrams before they draw their own circuits"],"answer":2,"explanation":"The task brings the students' own model into the open and lets it fail; working out that the bulb lights only when cell and bulb form a complete path builds the concept of a closed circuit.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"एक शिक्षक प्रत्येक समूह को एक सेल, एक बल्ब और तार का एक टुकड़ा देता है और उन्हें बल्ब जलाने की चुनौती देता है। कई समूह पहले तार को सेल के एक टर्मिनल से बल्ब तक जोड़ते हैं और उम्मीद करते हैं कि वह जलेगा। इस चुनौती का मुख्य मूल्य यह है कि यह:","optionsHi":["अतिरिक्त तारों की लागत बचाती है, ताकि हर समूह बहुत कम सामग्री से गतिविधि कर सके","विद्यार्थियों को दिखाती है कि कुछ बल्ब खराब होते हैं, ताकि वे परिपथ बनाने से पहले हर भाग की जाँच करना सीखें","‘एक तार पर्याप्त है’ के विचार को उजागर करती है और विद्यार्थियों को खोजने देती है कि पूर्ण लूप चाहिए","विद्यार्थियों को अपने परिपथ आरेख बनाने से पहले उनके सही चिह्न सिखाती है"],"explanationHi":"कार्य विद्यार्थियों के अपने मॉडल को सामने लाता है और उसे विफल होने देता है; यह समझ लेना कि बल्ब तभी जलता है जब सेल और बल्ब पूर्ण पथ बनाते हैं, बंद परिपथ की अवधारणा बनाता है।"},
  {"id":"cdp-pedagogy-subjects-757","question":"Arrange the phases of the constructivist teaching sequence proposed by Rosalind Driver and colleagues in the correct order: P. Restructuring of ideas  Q. Elicitation of students' ideas  R. Orientation  S. Application of ideas  T. Review of change in ideas","options":["Q, R, P, S, T","R, Q, S, P, T","R, P, Q, S, T","R, Q, P, S, T"],"answer":3,"explanation":"The sequence begins with orientation (arousing interest), then elicits existing ideas, restructures them through conflict and new ideas, applies them, and finally reviews how the ideas have changed.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"रोज़ालिंड ड्राइवर और सहयोगियों द्वारा प्रस्तावित रचनावादी शिक्षण क्रम के चरणों को सही क्रम में लगाइए: P. विचारों का पुनर्गठन  Q. विद्यार्थियों के विचारों का उद्घाटन  R. अभिविन्यास  S. विचारों का अनुप्रयोग  T. विचारों में परिवर्तन की समीक्षा","optionsHi":["Q, R, P, S, T","R, Q, S, P, T","R, P, Q, S, T","R, Q, P, S, T"],"explanationHi":"क्रम अभिविन्यास (रुचि जगाना) से शुरू होता है, फिर मौजूदा विचारों का उद्घाटन होता है, फिर विरोध और नए विचारों से उनका पुनर्गठन, फिर उनका अनुप्रयोग, और अंत में यह समीक्षा कि विचार कैसे बदले हैं।"},
  {"id":"cdp-pedagogy-subjects-758","question":"A teacher fixes a funnel into the mouth of a bottle and seals the gap with clay. When she pours water into the funnel, the water barely goes in. She asks, 'What is stopping the water?' This discrepant event is best used to:","options":["Arouse curiosity and make students question their ideas about air at the start of the lesson","Test students at the end of the lesson on what they have already learnt about air and air pressure","Entertain the class with a magic trick that has no scientific explanation behind it","Replace discussion about air, since students can see the answer for themselves directly"],"answer":0,"explanation":"A discrepant event produces a surprising outcome that conflicts with expectations, motivating inquiry. Here the trapped air takes up space and stops the water from entering.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"एक शिक्षिका बोतल के मुँह में कीप लगाकर खाली जगह को मिट्टी से बंद कर देती है। जब वह कीप में पानी डालती है, तो पानी मुश्किल से अंदर जाता है। वह पूछती है, ‘पानी को क्या रोक रहा है?’ इस विसंगत घटना का सबसे अच्छा उपयोग है:","optionsHi":["पाठ के आरंभ में जिज्ञासा जगाना और विद्यार्थियों को वायु के बारे में अपने विचारों पर प्रश्न उठाने को प्रेरित करना","पाठ के अंत में विद्यार्थियों की वायु और वायुदाब के बारे में जो उन्होंने पहले सीखा है उस पर परीक्षा लेना","जादू के करतब से कक्षा का मनोरंजन करना जिसकी कोई वैज्ञानिक व्याख्या नहीं है","वायु पर चर्चा की जगह लेना, क्योंकि विद्यार्थी उत्तर स्वयं सीधे देख सकते हैं"],"explanationHi":"विसंगत घटना ऐसा आश्चर्यजनक परिणाम उत्पन्न करती है जो अपेक्षाओं से टकराता है, जिससे जिज्ञासा को प्रेरणा मिलती है। यहाँ फँसी हुई हवा स्थान घेरती है और पानी को अंदर आने से रोकती है।"},
  {"id":"cdp-pedagogy-subjects-759","question":"In a Predict-Observe-Explain task, the teacher insists that students write the reason for their prediction before the demonstration. Why is this step important?","options":["It helps the teacher award marks fairly to students whose predictions turn out to be correct","It makes students' existing ideas explicit, so any conflict with the observation is noticed and discussed","It saves time later, since students then do not need to explain anything at all after seeing the demonstration","It ensures that all students think carefully enough to predict the correct answer beforehand"],"answer":1,"explanation":"Committing to a reasoned prediction surfaces the learner's prior idea; when the observation contradicts it, the learner can recognise exactly which idea needs to change.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"पूर्वानुमान-अवलोकन-व्याख्या (Predict-Observe-Explain) कार्य में शिक्षक आग्रह करता है कि विद्यार्थी प्रदर्शन से पहले अपने पूर्वानुमान का कारण लिखें। यह चरण महत्त्वपूर्ण क्यों है?","optionsHi":["यह शिक्षक को उन विद्यार्थियों को निष्पक्ष अंक देने में मदद करता है जिनके पूर्वानुमान सही निकलते हैं","यह विद्यार्थियों के मौजूदा विचारों को स्पष्ट करता है, इसलिए अवलोकन से किसी भी टकराव पर ध्यान जाता है और उस पर चर्चा होती है","यह बाद में समय बचाता है, क्योंकि प्रदर्शन देखने के बाद विद्यार्थियों को कुछ समझाना नहीं पड़ता","यह सुनिश्चित करता है कि सभी विद्यार्थी पहले से सही उत्तर का अनुमान लगाने के लिए पर्याप्त ध्यान से सोचें"],"explanationHi":"तर्कसहित पूर्वानुमान के प्रति प्रतिबद्ध होना शिक्षार्थी के पूर्व विचार को सतह पर लाता है; जब अवलोकन उसका खंडन करता है, तो शिक्षार्थी पहचान सकता है कि ठीक किस विचार को बदलने की आवश्यकता है।"},
  {"id":"cdp-pedagogy-subjects-760","question":"A teacher narrates how Jagadish Chandra Bose designed sensitive instruments such as the crescograph to record tiny responses of plants, and how other scientists examined his claims. Which aspect of the nature of science does this narrative bring out best?","options":["Science is a fixed body of facts that great scientists discover once and for all","Scientific claims are accepted on the reputation of the scientist who makes them","Science needs creativity in designing ways to observe, and claims are tested by the wider community","Science is done mainly in expensive laboratories abroad, using costly equipment that few can access"],"answer":2,"explanation":"Bose's work shows imagination in building new instruments and the role of the scientific community in scrutinising claims, which is science as a human and social enterprise.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs","questionHi":"एक शिक्षक बताता है कि जगदीश चंद्र बोस ने पौधों की सूक्ष्म प्रतिक्रियाओं को दर्ज करने के लिए क्रेस्कोग्राफ जैसे संवेदनशील यंत्र कैसे बनाए, और अन्य वैज्ञानिकों ने उनके दावों की कैसे जाँच की। यह वृत्तांत विज्ञान की प्रकृति के किस पहलू को सबसे अच्छी तरह सामने लाता है?","optionsHi":["विज्ञान तथ्यों का एक निश्चित भंडार है जिसे महान वैज्ञानिक एक बार और हमेशा के लिए खोज लेते हैं","वैज्ञानिक दावे उस वैज्ञानिक की प्रतिष्ठा के आधार पर स्वीकार किए जाते हैं जो उन्हें करता है","विज्ञान को अवलोकन के तरीके गढ़ने में रचनात्मकता चाहिए, और दावों की जाँच व्यापक समुदाय करता है","विज्ञान मुख्यतः विदेश की महँगी प्रयोगशालाओं में, महँगे उपकरणों से किया जाता है जिन तक कम लोग पहुँच सकते हैं"],"explanationHi":"बोस का कार्य नए यंत्र बनाने में कल्पनाशीलता और दावों की जाँच में वैज्ञानिक समुदाय की भूमिका दिखाता है, जो विज्ञान को एक मानवीय और सामाजिक उपक्रम के रूप में दर्शाता है।"},
  {"id":"cdp-pedagogy-subjects-761","question":"Consider these statements about science, technology and society (STS) in the upper primary curriculum. 1. Science is value-neutral, so citizens need not debate how it is used. 2. Technological decisions often involve trade-offs between benefits and risks. 3. Local communities' knowledge and concerns can be relevant to such decisions. 4. Only scientists are competent to judge any issue involving technology. Which are consistent with the NCF 2005 view?","options":["1 and 4 only","2 and 3 only","1, 2 and 3 only","2, 3 and 4 only"],"answer":1,"explanation":"NCF 2005 wants learners to weigh benefits and risks and to see the social side of science. Treating science as value-free or leaving all judgments to experts goes against its aim of informed citizenship.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"उच्च प्राथमिक पाठ्यचर्या में विज्ञान, प्रौद्योगिकी और समाज (STS) के बारे में निम्नलिखित कथनों पर विचार कीजिए। 1. विज्ञान मूल्य-निरपेक्ष है, इसलिए नागरिकों को इस पर बहस करने की आवश्यकता नहीं कि इसका उपयोग कैसे हो। 2. प्रौद्योगिकी संबंधी निर्णयों में अक्सर लाभों और जोखिमों के बीच समझौते शामिल होते हैं। 3. स्थानीय समुदायों का ज्ञान और चिंताएँ ऐसे निर्णयों के लिए प्रासंगिक हो सकती हैं। 4. केवल वैज्ञानिक ही प्रौद्योगिकी से जुड़े किसी भी मुद्दे को आँकने में सक्षम हैं। इनमें से कौन-से NCF 2005 के दृष्टिकोण के अनुरूप हैं?","optionsHi":["केवल 1 और 4","केवल 2 और 3","केवल 1, 2 और 3","केवल 2, 3 और 4"],"explanationHi":"NCF 2005 चाहता है कि शिक्षार्थी लाभों और जोखिमों को तौलें और विज्ञान का सामाजिक पक्ष देखें। विज्ञान को मूल्य-मुक्त मानना या सारे निर्णय विशेषज्ञों पर छोड़ना उसके सुसूचित नागरिकता के उद्देश्य के विरुद्ध है।"},
  {"id":"cdp-pedagogy-subjects-762","question":"Students report that their grandparents use neem leaves to protect stored grain from insects. The most scientific response from the teacher is to:","options":["Accept the practice as true, since traditional knowledge has been tested over generations","Dismiss it as superstition, since it is not mentioned anywhere in the science textbook","Tell students that only chemical pesticides can really protect stored grain from insects","Help students design a test comparing grain stored with and without neem leaves"],"answer":3,"explanation":"Traditional practices deserve neither blind acceptance nor rejection; a scientific attitude tests them with evidence. A fair comparison lets students judge the claim for themselves.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS","questionHi":"विद्यार्थी बताते हैं कि उनके दादा-दादी भंडारित अनाज को कीड़ों से बचाने के लिए नीम की पत्तियों का प्रयोग करते हैं। शिक्षक की सबसे वैज्ञानिक प्रतिक्रिया है:","optionsHi":["प्रथा को सत्य मान लेना, क्योंकि पारंपरिक ज्ञान पीढ़ियों से परखा गया है","इसे अंधविश्वास कहकर खारिज करना, क्योंकि यह विज्ञान की पाठ्यपुस्तक में कहीं नहीं है","विद्यार्थियों को बताना कि केवल रासायनिक कीटनाशक ही भंडारित अनाज को कीड़ों से वास्तव में बचा सकते हैं","विद्यार्थियों को नीम की पत्तियों सहित और रहित रखे अनाज की तुलना करने वाला परीक्षण डिज़ाइन करने में मदद करना"],"explanationHi":"पारंपरिक प्रथाएँ न अंधी स्वीकृति की, न अस्वीकृति की हकदार हैं; वैज्ञानिक दृष्टिकोण उन्हें साक्ष्य से परखता है। उचित तुलना विद्यार्थियों को दावे का स्वयं निर्णय करने देती है।"},
  {"id":"cdp-pedagogy-subjects-763","question":"A unit test shows that many Class 7 students cannot read a temperature-time graph. The most effective remedial activity is to:","options":["Have students record the temperature of cooling tea every two minutes, plot their own graph and discuss its shape","Give many more graphs from the textbook to copy into notebooks, so that practice builds familiarity","Explain the same graph again on the board, more slowly and in the same way, until students remember it","Drop graph questions from future tests, since graph reading can be taken up again in higher classes"],"answer":0,"explanation":"Remedial teaching works best with a fresh, concrete approach; plotting data they collected themselves connects each point and the curve's shape to a real event.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"एक इकाई परीक्षा दिखाती है कि कक्षा 7 के अनेक विद्यार्थी तापमान-समय आलेख पढ़ नहीं पाते। सबसे प्रभावी उपचारात्मक गतिविधि है:","optionsHi":["विद्यार्थियों से हर दो मिनट पर ठंडी होती चाय का तापमान दर्ज करवाना, अपना आलेख बनवाना और उसके आकार पर चर्चा करना","पाठ्यपुस्तक के और बहुत से आलेख कॉपियों में उतारने को देना, ताकि अभ्यास से परिचय बने","उसी आलेख को बोर्ड पर, उसी तरीके से, और धीरे समझाना जब तक विद्यार्थी उसे याद न कर लें","भविष्य की परीक्षाओं से आलेख के प्रश्न हटा देना, क्योंकि आलेख पढ़ना ऊँची कक्षाओं में फिर लिया जा सकता है"],"explanationHi":"उपचारात्मक शिक्षण नए, मूर्त उपागम से सबसे अच्छा काम करता है; स्वयं एकत्र किए आँकड़ों का आलेख बनाना प्रत्येक बिंदु और वक्र के आकार को वास्तविक घटना से जोड़ता है।"},
  {"id":"cdp-pedagogy-subjects-764","question":"A teacher wants her MCQ test on light to be diagnostic rather than only a measure of achievement. The distractors she writes should be:","options":["Obviously wrong, so that weaker students are not confused and the test measures only what they know","Taken from the textbook's end-of-chapter answers, so that every option is familiar to the students","Based on common wrong ideas students hold, so that each wrong choice points to a particular misconception","Random words or numbers of similar length, so that no option gives away the answer by its length or appearance"],"answer":2,"explanation":"In a diagnostic test, each distractor matches a known misconception, so a student's choice tells the teacher what she is thinking and what to remediate.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"एक शिक्षिका चाहती है कि प्रकाश पर उसकी MCQ परीक्षा केवल उपलब्धि का माप नहीं, बल्कि निदानात्मक हो। उसके द्वारा लिखे गए विकल्प-भ्रामक (distractors) होने चाहिए:","optionsHi":["स्पष्ट रूप से गलत, ताकि कमज़ोर विद्यार्थी भ्रमित न हों और परीक्षा केवल यह मापे कि वे क्या जानते हैं","पाठ्यपुस्तक के अध्याय-अंत के उत्तरों से लिए गए, ताकि हर विकल्प विद्यार्थियों को परिचित हो","विद्यार्थियों की आम गलत धारणाओं पर आधारित, ताकि प्रत्येक गलत चुनाव किसी विशेष भ्रांति की ओर संकेत करे","समान लंबाई के यादृच्छिक शब्द या संख्याएँ, ताकि कोई विकल्प अपनी लंबाई या रूप से उत्तर न बता दे"],"explanationHi":"निदानात्मक परीक्षा में प्रत्येक भ्रामक विकल्प किसी ज्ञात भ्रांति से मेल खाता है, इसलिए विद्यार्थी का चुनाव शिक्षिका को बताता है कि वह क्या सोच रही है और किसका उपचार करना है।"},
  {"id":"cdp-pedagogy-subjects-765","question":"A teacher wants to assess how far students show curiosity, cooperation and open-mindedness during group investigations over a term. The most suitable tool is:","options":["A written test with questions on scientific attitude, given at the end of the term","A single end-of-term practical examination in which each student works alone","An essay on 'The qualities of a scientist', marked for the attitudes it describes","Anecdotal records and an observation checklist maintained during the activities"],"answer":3,"explanation":"Attitudes are shown in behaviour over time, so they are best captured by systematic observation and records of significant incidents. A written test shows what students know about attitudes, not whether they have them.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"एक शिक्षिका एक सत्र में समूह जाँचों के दौरान आकलन करना चाहती है कि विद्यार्थी कितनी जिज्ञासा, सहयोग और खुलापन दिखाते हैं। सबसे उपयुक्त साधन है:","optionsHi":["वैज्ञानिक अभिवृत्ति पर प्रश्नों वाली लिखित परीक्षा, जो सत्र के अंत में दी जाए","एकल सत्रांत प्रायोगिक परीक्षा जिसमें प्रत्येक विद्यार्थी अकेले काम करे","‘वैज्ञानिक के गुण’ पर निबंध, जिसे उसमें वर्णित अभिवृत्तियों के लिए जाँचा जाए","गतिविधियों के दौरान रखे गए उपाख्यानात्मक अभिलेख और अवलोकन जाँच-सूची"],"explanationHi":"अभिवृत्तियाँ समय के साथ व्यवहार में दिखती हैं, इसलिए उन्हें व्यवस्थित अवलोकन और महत्त्वपूर्ण घटनाओं के अभिलेखों से सबसे अच्छी तरह पकड़ा जाता है। लिखित परीक्षा दिखाती है कि विद्यार्थी अभिवृत्तियों के बारे में क्या जानते हैं, यह नहीं कि उनमें वे हैं या नहीं।"},
  {"id":"cdp-pedagogy-subjects-766","question":"After an experiment, students in each group assess their own contribution and that of their group mates against criteria the class agreed upon. The main purpose of this practice in science is to:","options":["Reduce the teacher's work of marking, since students check their own work","Help students reflect on their learning and take responsibility for it","Rank students fairly for the final result using many judges","Replace the teacher's assessment completely with the students' judgement"],"answer":1,"explanation":"Self- and peer-assessment against shared criteria build reflection, metacognition and ownership of learning; they support, not replace, the teacher's assessment.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"एक प्रयोग के बाद प्रत्येक समूह के विद्यार्थी अपने और अपने समूह-साथियों के योगदान का मूल्यांकन उन मानदंडों के आधार पर करते हैं जिन पर कक्षा सहमत हुई थी। विज्ञान में इस अभ्यास का मुख्य उद्देश्य है:","optionsHi":["शिक्षक का जाँचने का काम घटाना, क्योंकि विद्यार्थी अपना कार्य स्वयं जाँचते हैं","विद्यार्थियों को अपने अधिगम पर चिंतन करने और उसकी ज़िम्मेदारी लेने में मदद करना","अनेक न्यायाधीशों से अंतिम परिणाम के लिए विद्यार्थियों को निष्पक्ष रूप से श्रेणीबद्ध करना","शिक्षक के आकलन को विद्यार्थियों के निर्णय से पूरी तरह बदल देना"],"explanationHi":"साझा मानदंडों पर स्व- और सहपाठी-आकलन चिंतन, अधिबोध और अधिगम के स्वामित्व को बढ़ाते हैं; वे शिक्षक के आकलन के पूरक हैं, उसका स्थान नहीं लेते।"},
  {"id":"cdp-pedagogy-subjects-767","question":"A curriculum committee removes dissection of animals from the upper primary practicals, and replaces it with models and observation of living organisms in their natural surroundings, citing respect for life. This decision most clearly reflects:","options":["Environmental validity, because organisms are observed in their surroundings","Cognitive validity, because dissection is too difficult for children","Ethical validity, because it promotes concern for living beings","Content validity, because models are more accurate than real organisms"],"answer":2,"explanation":"The stated reason is respect for life, which falls under ethical validity. Observing organisms in their surroundings is how the change is carried out, not why it was made.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"एक पाठ्यचर्या समिति जीवन के प्रति सम्मान का हवाला देते हुए उच्च प्राथमिक प्रायोगिक कार्य से जंतुओं का विच्छेदन हटा देती है और उसकी जगह मॉडल तथा जीवों का उनके प्राकृतिक परिवेश में अवलोकन रखती है। यह निर्णय सबसे स्पष्ट रूप से क्या दर्शाता है?","optionsHi":["पर्यावरणीय वैधता, क्योंकि जीवों का उनके परिवेश में अवलोकन किया जाता है","संज्ञानात्मक वैधता, क्योंकि विच्छेदन बच्चों के लिए बहुत कठिन है","नैतिक वैधता, क्योंकि यह जीवित प्राणियों के प्रति चिंता को बढ़ावा देता है","विषयवस्तु वैधता, क्योंकि मॉडल असली जीवों से अधिक सटीक होते हैं"],"explanationHi":"बताया गया कारण जीवन के प्रति सम्मान है, जो नैतिक वैधता के अंतर्गत आता है। जीवों का उनके परिवेश में अवलोकन परिवर्तन करने का तरीका है, उसका कारण नहीं।"},
  {"id":"cdp-pedagogy-subjects-768","question":"A Class 7 science book contains correct information, but is written in long passive sentences full of technical words, which most students cannot follow even after reading it twice. By the NCF 2005 criteria, the book most needs improvement in:","options":["Cognitive validity, since language must also suit the learner","Content validity, since the information must be made more accurate","Historical validity, since the book lacks the history of each idea","Process validity, since the book needs more experiments"],"answer":0,"explanation":"Cognitive validity covers content, process, language and pedagogy being within the learner's reach. Here the content is accurate; it is the language that puts it out of reach.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा 7 की एक विज्ञान पुस्तक में सही जानकारी है, पर वह लंबे कर्मवाच्य वाक्यों और तकनीकी शब्दों से भरी है, जिसे अधिकांश विद्यार्थी दो बार पढ़कर भी नहीं समझ पाते। NCF 2005 के मानदंडों के अनुसार पुस्तक में सबसे अधिक सुधार की आवश्यकता किसमें है?","optionsHi":["संज्ञानात्मक वैधता, क्योंकि भाषा भी शिक्षार्थी के अनुरूप होनी चाहिए","विषयवस्तु वैधता, क्योंकि जानकारी को और सटीक बनाया जाना चाहिए","ऐतिहासिक वैधता, क्योंकि पुस्तक में प्रत्येक विचार का इतिहास नहीं है","प्रक्रिया वैधता, क्योंकि पुस्तक में और प्रयोग चाहिए"],"explanationHi":"संज्ञानात्मक वैधता में विषयवस्तु, प्रक्रिया, भाषा और शिक्षण-विधि का शिक्षार्थी की पहुँच के भीतर होना शामिल है। यहाँ विषयवस्तु सटीक है; भाषा उसे पहुँच से बाहर कर रही है।"},
  {"id":"cdp-pedagogy-subjects-769","question":"Assertion (A): Hands-on activity by itself does not guarantee conceptual understanding in science. Reason (R): Learners interpret what they observe through the ideas they already hold.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because observations are read through prior ideas, students can do an activity and still hold their misconception; the activity has to be followed by discussion that challenges and reconstructs those ideas.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"अभिकथन (A): विज्ञान में केवल प्रत्यक्ष गतिविधि अवधारणात्मक समझ की गारंटी नहीं देती। कारण (R): शिक्षार्थी जो देखते हैं उसकी व्याख्या उन विचारों के माध्यम से करते हैं जो उनके पास पहले से हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"क्योंकि अवलोकन पूर्व विचारों के माध्यम से पढ़े जाते हैं, विद्यार्थी गतिविधि करके भी अपनी भ्रांति रख सकते हैं; गतिविधि के बाद ऐसी चर्चा होनी चाहिए जो उन विचारों को चुनौती दे और उनका पुनर्निर्माण करे।"},
  {"id":"cdp-pedagogy-subjects-770","question":"After a lesson on reflection has stated the rule, students follow a printed procedure with a plane mirror and pins to show that the angle of incidence equals the angle of reflection. This is an example of:","options":["Open inquiry","Guided inquiry","Structured inquiry","Confirmation inquiry"],"answer":3,"explanation":"When the result is known in advance and students follow given steps to verify it, it is confirmation inquiry. In structured inquiry the procedure is given but the result is not known beforehand.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"परावर्तन के पाठ में नियम बताए जाने के बाद विद्यार्थी समतल दर्पण और पिनों के साथ छपी हुई प्रक्रिया का पालन करके दिखाते हैं कि आपतन कोण परावर्तन कोण के बराबर होता है। यह किसका उदाहरण है?","optionsHi":["खुली जाँच (Open inquiry)","निर्देशित जाँच (Guided inquiry)","संरचित जाँच (Structured inquiry)","पुष्टिकारक जाँच (Confirmation inquiry)"],"explanationHi":"जब परिणाम पहले से ज्ञात हो और विद्यार्थी उसे सत्यापित करने के लिए दिए गए चरणों का पालन करें, तो यह पुष्टिकारक जाँच है। संरचित जाँच में प्रक्रिया दी जाती है पर परिणाम पहले से ज्ञात नहीं होता।"},
  {"id":"cdp-pedagogy-subjects-771","question":"Students are asked to choose a hypothesis for their science fair project that can actually be tested in school. Which one should the teacher accept?","options":["Plants feel happy and grow better when they are watered regularly","Some unknown force that cannot be detected by any instrument makes plants grow","Gram seeds soaked overnight germinate sooner than unsoaked gram seeds","Plants are the most important living things on earth"],"answer":2,"explanation":"A testable hypothesis names variables that can be measured and compared. Feelings of plants, undetectable forces and value judgments cannot be tested by a school investigation.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"विद्यार्थियों से अपनी विज्ञान मेला परियोजना के लिए ऐसी परिकल्पना चुनने को कहा जाता है जिसे विद्यालय में वास्तव में परखा जा सके। शिक्षक को कौन-सी स्वीकार करनी चाहिए?","optionsHi":["पौधे खुश महसूस करते हैं और नियमित रूप से पानी देने पर बेहतर बढ़ते हैं","कोई अज्ञात बल, जिसे किसी यंत्र से पहचाना नहीं जा सकता, पौधों को उगाता है","रात भर भिगोए चने के बीज बिना भिगोए चने के बीजों से जल्दी अंकुरित होते हैं","पौधे पृथ्वी पर सबसे महत्त्वपूर्ण जीवित वस्तुएँ हैं"],"explanationHi":"परीक्षणीय परिकल्पना ऐसे चरों का नाम लेती है जिन्हें मापा और तुलना किया जा सके। पौधों की भावनाएँ, अपहचाने जाने योग्य बल और मूल्य-निर्णय विद्यालय की जाँच से परखे नहीं जा सकते।"},
  {"id":"cdp-pedagogy-subjects-772","question":"A Class 8 class of a school with an Atal Tinkering Lab builds a small device to remind elderly people to take their medicines on time. The pedagogic value of such work lies mainly in:","options":["Preparing students for the board examination through extra practice in applied science","Developing creativity, design thinking and the ability to apply science to real problems","Teaching students to follow written instructions exactly, step by step, as given in a manual","Replacing classroom science teaching with hands-on work in the lab"],"answer":1,"explanation":"Tinkering and design tasks develop innovation: students identify a problem, design, build, test and improve a solution, using science purposefully.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"अटल टिंकरिंग लैब वाले विद्यालय की कक्षा 8 के विद्यार्थी बुज़ुर्गों को समय पर दवा लेने की याद दिलाने के लिए एक छोटा उपकरण बनाते हैं। ऐसे कार्य का शैक्षिक मूल्य मुख्यतः किसमें है?","optionsHi":["अनुप्रयुक्त विज्ञान में अतिरिक्त अभ्यास से विद्यार्थियों को बोर्ड परीक्षा के लिए तैयार करना","रचनात्मकता, डिज़ाइन चिंतन और विज्ञान को वास्तविक समस्याओं पर लागू करने की क्षमता का विकास","विद्यार्थियों को मैनुअल में दिए अनुसार लिखित निर्देशों का चरण-दर-चरण ठीक पालन करना सिखाना","कक्षा के विज्ञान शिक्षण की जगह प्रयोगशाला के प्रत्यक्ष कार्य को लाना"],"explanationHi":"टिंकरिंग और डिज़ाइन कार्य नवाचार विकसित करते हैं: विद्यार्थी समस्या पहचानते, समाधान डिज़ाइन करते, बनाते, परखते और सुधारते हैं, विज्ञान का उद्देश्यपूर्ण उपयोग करते हुए।"},
  {"id":"cdp-pedagogy-subjects-773","question":"In a Class 8 class, a student claims that a heavier stone and a lighter stone dropped together will 'obviously' land at different times. Instead of answering, the teacher asks him to imagine the two stones tied together by a string: would the lighter one slow the heavier one down, or would the pair, being heavier, fall faster? The teacher is using:","options":["A thought experiment that exposes a contradiction in the student's own reasoning","A lecture method in which the correct answer is transmitted to the student directly","Rote memorisation of the law of falling bodies through repeated recall","A demonstration in which the stones are dropped to prove the result by observation"],"answer":0,"explanation":"Galileo's tied-stones argument shows that 'heavier falls faster' leads to two contradictory predictions, so the idea cannot be right. A thought experiment uses reasoning, not apparatus, to create cognitive conflict.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा 8 की एक कक्षा में एक विद्यार्थी दावा करता है कि साथ गिराए गए भारी पत्थर और हल्के पत्थर ‘ज़ाहिर है’ अलग-अलग समय पर पहुँचेंगे। उत्तर देने के बजाय शिक्षक उससे दोनों पत्थरों को एक धागे से बँधा हुआ कल्पना करने को कहता है: क्या हल्का पत्थर भारी को धीमा कर देगा, या जोड़ी, भारी होने के कारण, तेज़ गिरेगी? शिक्षक किसका प्रयोग कर रहा है?","optionsHi":["विचार प्रयोग, जो विद्यार्थी के अपने तर्क में विरोधाभास उजागर करता है","व्याख्यान विधि, जिसमें सही उत्तर विद्यार्थी तक सीधे पहुँचाया जाता है","बार-बार स्मरण से गिरते पिंडों के नियम का रटना","प्रदर्शन, जिसमें पत्थर गिराकर अवलोकन से परिणाम सिद्ध किया जाता है"],"explanationHi":"गैलीलियो का बँधे पत्थरों का तर्क दिखाता है कि ‘भारी तेज़ गिरता है’ दो परस्पर विरोधी पूर्वानुमानों की ओर ले जाता है, इसलिए यह विचार सही नहीं हो सकता। विचार प्रयोग उपकरण नहीं, तर्क से संज्ञानात्मक संघर्ष उत्पन्न करता है।"},
  {"id":"cdp-pedagogy-subjects-774","question":"While teaching the water cycle, a teacher has Class 6 students keep a covered dish of water in the sun and observe droplets on the lid, then asks them to relate it to clouds and rain in their village. This sequence moves:","options":["From the abstract idea of evaporation to concrete observation","From the general principle of the water cycle to a particular example","From the known and concrete to the unknown and abstract","From the whole cycle to its separate parts, one at a time"],"answer":2,"explanation":"Beginning with a direct, observable experience and then relating it to large-scale processes follows the maxims 'known to unknown' and 'concrete to abstract'.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"जल चक्र पढ़ाते हुए एक शिक्षक कक्षा 6 के विद्यार्थियों से धूप में ढके हुए पानी के बर्तन को रखवाता है और ढक्कन पर बूँदों का अवलोकन करवाता है, फिर उनसे इसे अपने गाँव के बादलों और वर्षा से जोड़ने को कहता है। यह क्रम किस ओर बढ़ता है?","optionsHi":["वाष्पन के अमूर्त विचार से मूर्त अवलोकन की ओर","जल चक्र के सामान्य सिद्धांत से एक विशिष्ट उदाहरण की ओर","ज्ञात और मूर्त से अज्ञात और अमूर्त की ओर","पूरे चक्र से उसके अलग-अलग भागों की ओर, एक-एक करके"],"explanationHi":"प्रत्यक्ष, अवलोकन योग्य अनुभव से शुरू करके उसे बड़े पैमाने की प्रक्रियाओं से जोड़ना ‘ज्ञात से अज्ञात’ और ‘मूर्त से अमूर्त’ के सूत्रों का पालन करता है।"},
  {"id":"cdp-pedagogy-subjects-775","question":"After a unit on plants, a Class V teacher in Mysuru lets each child show what they learnt through a labelled poster, an oral explanation recorded on the class phone, or a short written note. Which principle of Universal Design for Learning (UDL) does this mainly apply?","options":["Multiple means of representation of content","Multiple means of engagement","Multiple means of action and expression","Reasonable accommodation for one child"],"answer":2,"explanation":"Offering different ways for learners to show what they know is 'action and expression'. 'Representation' is about presenting content in varied forms, a common confusion; this is a design for all, not an individual accommodation.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"पौधों की इकाई के बाद मैसूरु में कक्षा V की एक शिक्षिका प्रत्येक बच्चे को यह दिखाने देती है कि उसने क्या सीखा: नामांकित पोस्टर से, कक्षा के फ़ोन पर रिकॉर्ड की गई मौखिक व्याख्या से, या छोटे लिखित नोट से। यह मुख्यतः सार्वभौमिक अधिगम अभिकल्प (UDL) के किस सिद्धांत को लागू करता है?","optionsHi":["विषयवस्तु के निरूपण के अनेक साधन","संलग्नता के अनेक साधन","कार्रवाई और अभिव्यक्ति के अनेक साधन","किसी एक बच्चे के लिए उचित समायोजन"],"explanationHi":"शिक्षार्थियों को यह दिखाने के अलग-अलग तरीके देना कि वे क्या जानते हैं, ‘कार्रवाई और अभिव्यक्ति’ है। ‘निरूपण’ विषयवस्तु को विविध रूपों में प्रस्तुत करने के बारे में है, जो एक आम भ्रम है; यह सबके लिए अभिकल्प है, किसी एक के लिए समायोजन नहीं।"},
  {"id":"cdp-pedagogy-subjects-776","question":"In a Class IV maths lesson on division, all children work towards the same goal of sharing equally. Some use bottle caps and plates, some draw pictures, and some work only with numbers. What is the teacher differentiating here?","options":["The content, because each group is learning a different topic suited to its level","The process, because children reach the same goal by different routes suited to their readiness","The product, because each group submits a different kind of final assignment at the end of the lesson","The learning environment, because the furniture and seating have been rearranged for groups"],"answer":1,"explanation":"In Tomlinson's model, differentiating process means varying how learners make sense of the same content. The learning goal (content) is common here, and the outputs are not what is being varied.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा IV के भाग के पाठ में सभी बच्चे बराबर बाँटने के एक ही लक्ष्य की ओर काम करते हैं। कुछ बोतल के ढक्कन और प्लेटों का प्रयोग करते हैं, कुछ चित्र बनाते हैं, और कुछ केवल संख्याओं से काम करते हैं। शिक्षक यहाँ किसमें विभेदन कर रहा है?","optionsHi":["विषयवस्तु में, क्योंकि प्रत्येक समूह अपने स्तर के अनुरूप अलग विषय सीख रहा है","प्रक्रिया में, क्योंकि बच्चे अपनी तत्परता के अनुरूप अलग-अलग मार्गों से एक ही लक्ष्य तक पहुँचते हैं","उत्पाद में, क्योंकि पाठ के अंत में प्रत्येक समूह अलग प्रकार का अंतिम कार्य जमा करता है","अधिगम परिवेश में, क्योंकि समूहों के लिए फ़र्नीचर और बैठक पुनर्व्यवस्थित की गई है"],"explanationHi":"टॉमलिंसन के मॉडल में प्रक्रिया का विभेदन का अर्थ है कि शिक्षार्थी एक ही विषयवस्तु को कैसे समझते हैं, इसमें विविधता लाना। यहाँ अधिगम लक्ष्य (विषयवस्तु) समान है, और बदली जा रही चीज़ उत्पादन नहीं है।"},
  {"id":"cdp-pedagogy-subjects-777","question":"Consider the following statements about the Rights of Persons with Disabilities Act, 2016: 1. It recognises 21 types of disabilities. 2. It describes inclusive education as a system in which students with and without disabilities learn together, with teaching and learning suitably adapted. 3. It requires children with disabilities to study only in special schools. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The RPwD Act 2016 lists 21 disabilities and promotes inclusive education in regular schools with adaptations; it does not confine children to special schools, so statement 3 is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"दिव्यांगजन अधिकार अधिनियम, 2016 के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह 21 प्रकार की दिव्यांगताओं को मान्यता देता है। 2. यह समावेशी शिक्षा को ऐसी प्रणाली के रूप में वर्णित करता है जिसमें दिव्यांग और गैर-दिव्यांग विद्यार्थी साथ सीखते हैं, शिक्षण और अधिगम को उचित रूप से अनुकूलित करके। 3. यह माँग करता है कि दिव्यांग बच्चे केवल विशेष विद्यालयों में पढ़ें। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"RPwD अधिनियम 2016 21 दिव्यांगताओं को सूचीबद्ध करता है और अनुकूलनों के साथ नियमित विद्यालयों में समावेशी शिक्षा को बढ़ावा देता है; वह बच्चों को विशेष विद्यालयों तक सीमित नहीं करता, इसलिए कथन 3 असत्य है।"},
  {"id":"cdp-pedagogy-subjects-778","question":"Asha, who has cerebral palsy and uses a wheelchair, is admitted to Class III of a regular school. She sits at the back because the aisles are narrow, no materials are adapted, and she does not join group work. Which description fits this situation best?","options":["Full inclusion, because Asha is in a regular classroom alongside other children of her own age and locality","Exclusion, because she has not been placed in a special school suited to her disability","Inclusion, because the school has met the RTE Act requirement simply by admitting her","Integration without inclusion, since the classroom and teaching have not been adapted for her to take part"],"answer":3,"explanation":"Inclusion means the school changes its space, materials and teaching so every child participates fully. Merely placing the child in a regular room while expecting her to fit in is integration, not inclusion.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"आशा, जिसे प्रमस्तिष्कीय पक्षाघात (सेरेब्रल पाल्सी) है और जो व्हीलचेयर का प्रयोग करती है, एक नियमित विद्यालय की कक्षा III में प्रवेश पाती है। वह पीछे बैठती है क्योंकि गलियारे संकरे हैं, कोई सामग्री अनुकूलित नहीं है, और वह समूह कार्य में भाग नहीं लेती। कौन-सा वर्णन इस स्थिति पर सबसे अच्छा बैठता है?","optionsHi":["पूर्ण समावेशन, क्योंकि आशा अपनी आयु और इलाके के अन्य बच्चों के साथ नियमित कक्षा में है","बहिष्करण, क्योंकि उसे उसकी दिव्यांगता के अनुरूप विशेष विद्यालय में नहीं रखा गया है","समावेशन, क्योंकि विद्यालय ने उसे केवल प्रवेश देकर RTE अधिनियम की आवश्यकता पूरी कर दी है","समावेशन के बिना एकीकरण, क्योंकि उसके भाग लेने के लिए कक्षा और शिक्षण को अनुकूलित नहीं किया गया है"],"explanationHi":"समावेशन का अर्थ है कि विद्यालय अपना स्थान, सामग्री और शिक्षण बदलता है ताकि हर बच्चा पूरी तरह भाग ले सके। केवल बच्चे को नियमित कक्ष में रखकर यह अपेक्षा करना कि वह स्वयं ढल जाए, एकीकरण है, समावेशन नहीं।"},
  {"id":"cdp-pedagogy-subjects-779","question":"Karan, a Class VI student with partial hearing loss, relies partly on lip-reading. Which set of classroom adjustments is most appropriate?","options":["Seat him at the back so that loud voices do not hurt his ears, and speak much louder than usual whenever addressing him","Seat him near the front with a well-lit view of the teacher's face, and write key words and instructions on the board","Seat him near the window for fresh air and light, and give him extra written homework in place of oral work","Excuse him from all discussions and oral activities so that he is not embarrassed in front of others"],"answer":1,"explanation":"A child who lip-reads needs a clear, well-lit view of the speaker's face and visual support for key information. Shouting distorts lip patterns, and excluding him from oral work denies participation.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"करण, कक्षा VI का एक विद्यार्थी जिसे आंशिक श्रवण-हानि है, आंशिक रूप से होंठ-पठन पर निर्भर है। कक्षा के समायोजनों का कौन-सा समूह सबसे उपयुक्त है?","optionsHi":["उसे पीछे बैठाना ताकि ज़ोर की आवाज़ें उसके कानों को चोट न पहुँचाएँ, और जब भी उससे बात करें सामान्य से बहुत ज़ोर से बोलना","उसे आगे बैठाना जहाँ से शिक्षक का चेहरा अच्छी रोशनी में दिखे, और मुख्य शब्द तथा निर्देश बोर्ड पर लिखना","उसे ताज़ा हवा और रोशनी के लिए खिड़की के पास बैठाना, और मौखिक कार्य की जगह अतिरिक्त लिखित गृहकार्य देना","उसे सभी चर्चाओं और मौखिक गतिविधियों से छूट देना ताकि वह दूसरों के सामने शर्मिंदा न हो"],"explanationHi":"जो बच्चा होंठ-पठन करता है उसे वक्ता के चेहरे का स्पष्ट, अच्छी रोशनी वाला दृश्य और मुख्य जानकारी के लिए दृश्य सहायता चाहिए। चिल्लाना होंठ की आकृतियों को विकृत करता है, और उसे मौखिक कार्य से बाहर रखना भागीदारी से वंचित करता है।"},
  {"id":"cdp-pedagogy-subjects-780","question":"Imran in Class IV narrates stories brilliantly and solves oral maths problems, but reads very slowly, confuses b and d, and his written answers are short and full of errors. Which response is most appropriate?","options":["Make him copy two pages from the textbook daily, so that steady practice improves his reading and writing","Treat him as lazy and careless, since a child who speaks so well could clearly write well if he tried","Recommend that he repeat Class IV, so that his reading and writing can catch up with his speaking","Suspect dyslexia; use multisensory methods, allow oral answers and extra time, and seek an assessment"],"answer":3,"explanation":"A gap between strong oral ability and weak reading and writing is typical of dyslexia, which needs multisensory methods and accommodations. Copying, labelling or retention punish the child for a learning difference.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा IV का इमरान कहानियाँ शानदार ढंग से सुनाता है और मौखिक गणित के प्रश्न हल करता है, पर बहुत धीरे पढ़ता है, b और d में भ्रमित होता है, और उसके लिखित उत्तर छोटे और त्रुटियों से भरे हैं। सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["उससे रोज़ पाठ्यपुस्तक के दो पृष्ठ उतरवाना, ताकि लगातार अभ्यास से उसका पठन और लेखन सुधरे","उसे आलसी और लापरवाह मानना, क्योंकि जो बच्चा इतना अच्छा बोलता है वह कोशिश करे तो अच्छा लिख भी सकता है","सुझाव देना कि वह कक्षा IV दोहराए, ताकि उसका पठन और लेखन उसकी बोलचाल के बराबर आ सके","डिस्लेक्सिया की आशंका करना; बहु-संवेदी विधियों का प्रयोग करना, मौखिक उत्तर और अतिरिक्त समय की अनुमति देना, और आकलन करवाना"],"explanationHi":"मज़बूत मौखिक क्षमता और कमज़ोर पठन-लेखन के बीच का अंतर डिस्लेक्सिया की विशिष्ट पहचान है, जिसे बहु-संवेदी विधियाँ और समायोजन चाहिए। नकल करना, ठप्पा लगाना या रोक देना बच्चे को सीखने के अंतर के लिए दंडित करता है।"},
  {"id":"cdp-pedagogy-subjects-781","question":"Riya, diagnosed with ADHD, finds it very hard to stay seated through long written tasks in Class III. Which strategy is best?","options":["Give short tasks with checkpoints, build in movement, and seat her near the teacher away from distractions","Seat her near the window so that she can look outside whenever she feels restless and calm herself down quietly","Give her longer tasks every day so that she gradually trains herself to sit still for long periods","Keep her inside during recess to finish incomplete work, so that she learns that tasks must be completed"],"answer":0,"explanation":"Short, structured tasks, purposeful movement and reduced distraction work with how ADHD affects attention. Longer tasks or losing recess increase the very restlessness they target.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"रिया, जिसे ADHD का निदान हुआ है, कक्षा III में लंबे लिखित कार्यों के दौरान बैठे रहना बहुत कठिन पाती है। सबसे अच्छी युक्ति कौन-सी है?","optionsHi":["जाँच-बिंदुओं के साथ छोटे कार्य देना, गति को शामिल करना, और उसे ध्यान भटकाने वाली चीज़ों से दूर शिक्षक के पास बैठाना","उसे खिड़की के पास बैठाना ताकि जब भी बेचैनी हो वह बाहर देखकर चुपचाप स्वयं को शांत कर सके","उसे हर दिन लंबे कार्य देना ताकि वह धीरे-धीरे लंबे समय तक स्थिर बैठना सीख ले","अधूरे काम को पूरा करने के लिए उसे अवकाश में अंदर रखना ताकि वह सीखे कि कार्य पूरे होने चाहिए"],"explanationHi":"छोटे, संरचित कार्य, उद्देश्यपूर्ण गति और कम विकर्षण उस तरीके के साथ काम करते हैं जिससे ADHD ध्यान को प्रभावित करता है। लंबे कार्य या अवकाश खोना उसी बेचैनी को बढ़ाता है जिसे वह लक्षित करता है।"},
  {"id":"cdp-pedagogy-subjects-782","question":"A Class VI teacher finds that a group of students has been calling Deepika names because of her dark skin. What is the most appropriate course of action?","options":["Tell Deepika to ignore them, since such teasing is a normal part of growing up and usually stops once it gets no reaction","Make the bullies apologise in the morning assembly in front of the whole school, so that others are warned too","Support Deepika privately, talk firmly with the bullies about the harm caused, and discuss respect and colourism in class","Move Deepika to another section so that she is kept away from the bullies and can study in peace"],"answer":2,"explanation":"Effective anti-bullying work protects the target, holds the bullies accountable in a way that changes behaviour, and addresses the prejudice with the whole class. Ignoring it, moving the victim or public shaming leaves the cause untouched.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कक्षा VI की एक शिक्षिका पाती है कि विद्यार्थियों का एक समूह दीपिका को उसके साँवले रंग के कारण चिढ़ाता है। सबसे उपयुक्त कार्रवाई क्या है?","optionsHi":["दीपिका से कहना कि उन्हें अनदेखा करे, क्योंकि ऐसा चिढ़ाना बड़े होने का सामान्य हिस्सा है और प्रतिक्रिया न मिलने पर आमतौर पर रुक जाता है","धौंस जमाने वालों से सुबह की सभा में पूरे विद्यालय के सामने माफ़ी मँगवाना, ताकि दूसरों को भी चेतावनी मिले","दीपिका को निजी तौर पर सहारा देना, धौंस जमाने वालों से हुए नुकसान के बारे में दृढ़ता से बात करना, और कक्षा में सम्मान तथा रंगभेद पर चर्चा करना","दीपिका को दूसरे खंड में भेज देना ताकि वह धौंस जमाने वालों से दूर रहे और शांति से पढ़ सके"],"explanationHi":"प्रभावी धौंस-विरोधी कार्य लक्ष्य की रक्षा करता है, धौंस जमाने वालों को इस तरह जवाबदेह ठहराता है कि व्यवहार बदले, और पूरी कक्षा के साथ पूर्वाग्रह को संबोधित करता है। अनदेखा करना, पीड़ित को हटाना या सार्वजनिक शर्मिंदगी कारण को अछूता छोड़ देती है।"},
  {"id":"cdp-pedagogy-subjects-783","question":"During the mid-day meal in a village school, a few children refuse to sit next to classmates from a Scheduled Caste community. What should the teacher do?","options":["Arrange separate rows for the two groups, so that the meal goes on peacefully and no family's beliefs are offended","Seat all children together, firmly stop the discrimination, and take up the prejudice with the class and parents","Ignore it for now, since these are views children bring from home and the school cannot change them","Let the children who object eat in another room, so that the others can have their meal without any trouble"],"answer":1,"explanation":"Untouchability is abolished under Article 17 and any discriminatory practice in school must be stopped; the teacher must also work on the attitudes behind it. Separate seating accepts and reinforces discrimination.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"गाँव के विद्यालय में मध्याह्न भोजन के दौरान कुछ बच्चे अनुसूचित जाति समुदाय के सहपाठियों के पास बैठने से मना कर देते हैं। शिक्षक को क्या करना चाहिए?","optionsHi":["दोनों समूहों की अलग पंक्तियाँ लगाना, ताकि भोजन शांति से चले और किसी परिवार की मान्यताएँ आहत न हों","सभी बच्चों को साथ बैठाना, भेदभाव को दृढ़ता से रोकना, और कक्षा तथा अभिभावकों के साथ पूर्वाग्रह पर काम करना","अभी इसे अनदेखा करना, क्योंकि ये वे विचार हैं जो बच्चे घर से लाते हैं और विद्यालय उन्हें बदल नहीं सकता","आपत्ति करने वाले बच्चों को दूसरे कमरे में खाने देना, ताकि बाकी बिना किसी परेशानी के भोजन कर सकें"],"explanationHi":"अनुच्छेद 17 के अंतर्गत अस्पृश्यता समाप्त की गई है और विद्यालय में किसी भी भेदभावपूर्ण प्रथा को रोकना होगा; शिक्षक को उसके पीछे के दृष्टिकोणों पर भी काम करना चाहिए। अलग बैठक भेदभाव को स्वीकार और पुष्ट करती है।"},
  {"id":"cdp-pedagogy-subjects-784","question":"In a Class V classroom, girls are always asked to sweep and decorate the board, while boys move benches and fetch the sports kit. Which change best reflects a gender-sensitive classroom?","options":["Continue as before, since these tasks suit the natural abilities and interests of girls and boys respectively","Ask only for volunteers each day, so that every child freely picks the duties he or she prefers to do","Hire a helper for all such tasks, so that no child has to spend class time on chores at all","Rotate all duties among all children, and discuss why tasks should not be divided by gender"],"answer":3,"explanation":"Assigning tasks by gender teaches stereotypes through the 'hidden curriculum'. Rotating duties for everyone, with discussion, makes equality visible; volunteering alone often reproduces the same pattern.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"कक्षा V की एक कक्षा में लड़कियों से हमेशा झाड़ू लगाने और बोर्ड सजाने को कहा जाता है, जबकि लड़के बेंच हिलाते और खेल-सामग्री लाते हैं। कौन-सा परिवर्तन लैंगिक-संवेदनशील कक्षा को सबसे अच्छी तरह दर्शाता है?","optionsHi":["पहले की तरह जारी रखना, क्योंकि ये कार्य क्रमशः लड़कियों और लड़कों की स्वाभाविक क्षमताओं और रुचियों के अनुकूल हैं","हर दिन केवल स्वयंसेवक माँगना, ताकि हर बच्चा अपनी पसंद के कर्तव्य स्वतंत्र रूप से चुने","ऐसे सभी कार्यों के लिए सहायक रखना, ताकि किसी बच्चे को कक्षा का समय कामों में बिताना ही न पड़े","सभी कर्तव्यों को सब बच्चों में बारी-बारी से बाँटना, और चर्चा करना कि कार्य लिंग के आधार पर क्यों नहीं बाँटे जाने चाहिए"],"explanationHi":"लिंग के आधार पर कार्य बाँटना ‘छिपी पाठ्यचर्या’ के माध्यम से रूढ़ियाँ सिखाता है। सबके लिए कर्तव्यों का चक्रीकरण, चर्चा के साथ, समानता को दृश्य बनाता है; केवल स्वयंसेवा अक्सर वही पैटर्न दोहराती है।"},
  {"id":"cdp-pedagogy-subjects-785","question":"Assertion (A): Children learn more in a classroom where mistakes are treated as a normal part of learning. Reason (R): When children fear being wrong, they avoid taking risks and hide what they do not understand.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Fear of error leads to silence and hiding confusion, so the teacher never sees what needs fixing. Treating errors as information makes it safe to try, which is why A follows from R.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): बच्चे उस कक्षा में अधिक सीखते हैं जहाँ गलतियों को सीखने का सामान्य हिस्सा माना जाता है। कारण (R): जब बच्चे गलत होने से डरते हैं, तो वे जोखिम लेने से बचते हैं और जो नहीं समझते उसे छिपाते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"भूल का डर चुप्पी और भ्रम छिपाने की ओर ले जाता है, इसलिए शिक्षक कभी नहीं देख पाता कि क्या सुधारना है। त्रुटियों को सूचना मानना प्रयास करना सुरक्षित बनाता है, इसीलिए A, R से निकलता है।"},
  {"id":"cdp-pedagogy-subjects-786","question":"A Class VII teacher routinely refers to Section C as 'the weak section' in front of the students and gives them easier work and fewer questions. Over the year their results fall further. Which phenomenon best explains this?","options":["The Hawthorne effect, since the students knew they were being watched and labelled by the teacher all year","Self-fulfilling prophecy, where low teacher expectations shape treatment and then students' performance","The halo effect, since one trait of the section shaped the teacher's overall judgement of it","Regression to the mean, since extreme scores tend to move towards the average over a year"],"answer":1,"explanation":"Rosenthal and Jacobson's Pygmalion research showed that teacher expectations affect how students are treated and how they perform. Labelling plus reduced challenge turned the low expectation into reality.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VII की एक शिक्षिका नियमित रूप से विद्यार्थियों के सामने खंड C को ‘कमज़ोर खंड’ कहती है और उन्हें आसान काम और कम प्रश्न देती है। वर्ष भर में उनके परिणाम और गिर जाते हैं। कौन-सी परिघटना इसे सबसे अच्छी तरह समझाती है?","optionsHi":["हॉथोर्न प्रभाव, क्योंकि विद्यार्थी जानते थे कि शिक्षिका पूरे वर्ष उन्हें देख रही है और उन पर ठप्पा लगा रही है","स्व-पूर्ति भविष्यवाणी, जहाँ शिक्षक की निम्न अपेक्षाएँ व्यवहार को और फिर विद्यार्थियों के प्रदर्शन को आकार देती हैं","प्रभामंडल प्रभाव, क्योंकि खंड के एक लक्षण ने शिक्षिका के उसके बारे में समग्र निर्णय को आकार दिया","माध्य की ओर प्रतिगमन, क्योंकि चरम अंक एक वर्ष में औसत की ओर बढ़ जाते हैं"],"explanationHi":"रोज़ेंथल और जैकबसन के पिग्मेलियन शोध ने दिखाया कि शिक्षक की अपेक्षाएँ विद्यार्थियों के साथ व्यवहार और उनके प्रदर्शन को प्रभावित करती हैं। ठप्पा लगाने और चुनौती घटाने ने निम्न अपेक्षा को वास्तविकता बना दिया।"},
  {"id":"cdp-pedagogy-subjects-787","question":"Somu, a first-generation learner from a tribal family in Dantewada, rarely completes homework, and there is no one at home who can read. What is the most appropriate response?","options":["Punish Somu each time he misses homework, so that he builds the habit of completing it regularly","Ask his parents to arrange private tuition, so that someone can help him with homework every evening","Understand his home situation, set homework he can do alone or with peers, and give support time in school","Stop expecting any homework from Somu, since his home cannot support him and he should not be put under stress"],"answer":2,"explanation":"Homework that assumes literate adults at home disadvantages first-generation learners; adjusting tasks and giving school-based support is equitable. Punishing or giving up both fail the child.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"दंतेवाड़ा के एक जनजातीय परिवार का पहली पीढ़ी का शिक्षार्थी सोमू शायद ही कभी गृहकार्य पूरा करता है, और घर पर कोई पढ़ना-लिखना जानने वाला नहीं है। सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["सोमू के गृहकार्य छूटने पर हर बार उसे दंड देना, ताकि वह नियमित रूप से उसे पूरा करने की आदत बनाए","उसके माता-पिता से निजी ट्यूशन की व्यवस्था करने को कहना, ताकि कोई हर शाम उसके गृहकार्य में मदद कर सके","उसकी घरेलू स्थिति को समझना, ऐसा गृहकार्य देना जो वह अकेले या साथियों के साथ कर सके, और विद्यालय में सहयोग का समय देना","सोमू से गृहकार्य की अपेक्षा ही छोड़ देना, क्योंकि उसका घर उसे सहारा नहीं दे सकता और उसे तनाव में नहीं डालना चाहिए"],"explanationHi":"जो गृहकार्य मानता है कि घर पर साक्षर वयस्क हैं, वह पहली पीढ़ी के शिक्षार्थियों को हानि पहुँचाता है; कार्यों को समायोजित करना और विद्यालय-आधारित सहयोग देना न्यायसंगत है। दंड देना या हार मान लेना दोनों बच्चे को विफल करते हैं।"},
  {"id":"cdp-pedagogy-subjects-788","question":"Twelve-year-old Lakshmi, the child of seasonal migrant brick-kiln workers, has never attended school. Her parents seek admission in a government school in October. Under the RTE Act 2009, what should the school do?","options":["Admit her to an age-appropriate class (around Class VI) and give special training to help her catch up","Admit her to Class I, since a child who has never been to school must begin from the first class","Refuse admission for now, since the session has already started, and ask the family to come back next April","Ask for her birth certificate and refuse admission until it is produced, as proof of age is required"],"answer":0,"explanation":"Section 4 of the RTE Act requires a child who has not been admitted or has dropped out to be placed in an age-appropriate class with special training. Admission cannot be denied for the time of year or lack of age proof.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"बारह वर्ष की लक्ष्मी, मौसमी प्रवासी ईंट-भट्ठा मज़दूरों की संतान, कभी विद्यालय नहीं गई। उसके माता-पिता अक्टूबर में एक सरकारी विद्यालय में प्रवेश माँगते हैं। RTE अधिनियम 2009 के अंतर्गत विद्यालय को क्या करना चाहिए?","optionsHi":["उसे आयु-उपयुक्त कक्षा (लगभग कक्षा VI) में प्रवेश देना और उसे पकड़ बनाने के लिए विशेष प्रशिक्षण देना","उसे कक्षा I में प्रवेश देना, क्योंकि जो बच्चा कभी विद्यालय नहीं गया उसे पहली कक्षा से शुरू करना चाहिए","फ़िलहाल प्रवेश से इनकार करना, क्योंकि सत्र शुरू हो चुका है, और परिवार से अगले अप्रैल में आने को कहना","उसका जन्म प्रमाणपत्र माँगना और जब तक वह प्रस्तुत न हो प्रवेश से इनकार करना, क्योंकि आयु का प्रमाण आवश्यक है"],"explanationHi":"RTE अधिनियम की धारा 4 के अनुसार जिस बच्चे को प्रवेश नहीं मिला या जिसने पढ़ाई छोड़ दी, उसे विशेष प्रशिक्षण के साथ आयु-उपयुक्त कक्षा में रखा जाना चाहिए। वर्ष के समय या आयु-प्रमाण के अभाव में प्रवेश से इनकार नहीं किया जा सकता।"},
  {"id":"cdp-pedagogy-subjects-789","question":"A Class IV child quietly tells her teacher that a relative touches her in ways that make her uncomfortable, and begs her not to tell anyone. What is the correct response?","options":["Promise to keep it a secret, so that the child continues to trust her and shares more in the future","Call the relative to school and question him in front of the child, so that the truth comes out at once and he is warned","Ask the child to describe the incidents in detail several times, to check whether her story stays the same","Listen calmly, believe her, tell her it is not her fault, explain that she must be helped, and report it under POCSO"],"answer":3,"explanation":"The POCSO Act 2012 makes reporting of suspected child sexual abuse mandatory; the teacher must not promise secrecy, must avoid repeated questioning that re-traumatises the child, and must not confront the alleged abuser herself.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा IV की एक बच्ची चुपचाप अपनी शिक्षिका को बताती है कि एक रिश्तेदार उसे ऐसे छूता है जिससे वह असहज होती है, और विनती करती है कि वह किसी को न बताए। सही प्रतिक्रिया क्या है?","optionsHi":["इसे गुप्त रखने का वादा करना, ताकि बच्ची उस पर भरोसा बनाए रखे और भविष्य में और बताए","रिश्तेदार को विद्यालय बुलाना और बच्ची के सामने उससे पूछताछ करना, ताकि सच्चाई तुरंत सामने आए और उसे चेतावनी मिले","बच्ची से घटनाओं का कई बार विस्तार से वर्णन करवाना, यह जाँचने के लिए कि उसकी कहानी वैसी ही रहती है या नहीं","शांति से सुनना, उस पर विश्वास करना, उसे बताना कि यह उसकी गलती नहीं है, समझाना कि उसकी मदद होनी चाहिए, और POCSO के अंतर्गत रिपोर्ट करना"],"explanationHi":"POCSO अधिनियम 2012 बाल यौन शोषण की आशंका की रिपोर्ट करना अनिवार्य बनाता है; शिक्षिका को गोपनीयता का वादा नहीं करना चाहिए, बार-बार पूछताछ से बचना चाहिए जो बच्ची को फिर से आघात पहुँचाती है, और कथित अपराधी का स्वयं सामना नहीं करना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-790","question":"In a Class V classroom, the teacher always seats the highest scorers in the front rows and the 'slow' children at the back. Which change best supports an inclusive classroom?","options":["Keep the arrangement, since toppers deserve to sit in front and it motivates others to work harder","Move the slow children to the front and the toppers to the back, so that the weak get more attention","Rotate seating and use mixed-ability groups, placing children with specific needs where they are best supported","Let children choose their own seats for the whole year, so that they can sit with their friends and feel comfortable"],"answer":2,"explanation":"Fixed seating by ability signals the teacher's expectations and isolates some children. Rotation and mixed groups widen interaction; individual needs, such as hearing or vision, still guide where a child sits.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"कक्षा V की एक कक्षा में शिक्षक हमेशा सबसे अधिक अंक पाने वालों को आगे की पंक्तियों में और ‘धीमे’ बच्चों को पीछे बैठाता है। कौन-सा परिवर्तन समावेशी कक्षा को सबसे अच्छी तरह सहारा देता है?","optionsHi":["व्यवस्था को बनाए रखना, क्योंकि टॉपर आगे बैठने के हकदार हैं और इससे दूसरे अधिक मेहनत करने को प्रेरित होते हैं","धीमे बच्चों को आगे और टॉपर्स को पीछे बैठाना, ताकि कमज़ोरों पर अधिक ध्यान दिया जा सके","बैठक का चक्रीकरण और मिश्रित-क्षमता समूहों का प्रयोग करना, विशिष्ट आवश्यकताओं वाले बच्चों को वहाँ बैठाना जहाँ उन्हें सबसे अच्छा सहारा मिले","बच्चों को पूरे वर्ष के लिए अपनी सीट चुनने देना, ताकि वे अपने दोस्तों के साथ बैठ सकें और सहज महसूस करें"],"explanationHi":"क्षमता के आधार पर तय बैठक शिक्षक की अपेक्षाओं का संकेत देती है और कुछ बच्चों को अलग-थलग करती है। चक्रीकरण और मिश्रित समूह अंतःक्रिया बढ़ाते हैं; श्रवण या दृष्टि जैसी व्यक्तिगत आवश्यकताएँ अब भी तय करती हैं कि बच्चा कहाँ बैठे।"},
  {"id":"cdp-pedagogy-subjects-791","question":"Consider the following statements about teaching mathematics to a child who is blind in a Class VI inclusive classroom: 1. A Taylor frame or an abacus can be used for calculation. 2. Tactile diagrams with raised lines can be used for geometry. 3. The child should be excused from geometry, since it depends entirely on vision. Which of these are correct?","options":["1 and 3 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Tactile and assistive tools let a blind child learn the same concepts, including geometry, through touch. Excusing the child from geometry is exclusion, so statement 3 is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VI की समावेशी कक्षा में दृष्टिहीन बच्चे को गणित पढ़ाने के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. गणना के लिए टेलर फ़्रेम या अबेकस का प्रयोग किया जा सकता है। 2. ज्यामिति के लिए उभरी रेखाओं वाले स्पर्शीय आरेख प्रयोग किए जा सकते हैं। 3. बच्चे को ज्यामिति से छूट दी जानी चाहिए, क्योंकि वह पूरी तरह दृष्टि पर निर्भर है। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 2 और 3","केवल 1 और 2","1, 2 और 3"],"explanationHi":"स्पर्शीय और सहायक साधन दृष्टिहीन बच्चे को ज्यामिति सहित वही संप्रत्यय स्पर्श के माध्यम से सीखने देते हैं। बच्चे को ज्यामिति से छूट देना बहिष्करण है, इसलिए कथन 3 असत्य है।"},
  {"id":"cdp-pedagogy-subjects-792","question":"Gopal, a Class III child with a mild intellectual disability, cannot follow a multi-step task such as 'measure the table, record it and compare it with your friend's table'. Which teacher action is most appropriate?","options":["Repeat the full instruction more loudly and slowly until he can follow all of it in one go without help","Break the task into small steps with concrete materials and demonstration, giving feedback after each step","Give him a colouring sheet instead while the others measure, so that he does not feel left behind","Ask a classmate to do the task for him, so that the group's table is completed on time"],"answer":1,"explanation":"Task analysis (smaller steps, concrete support, immediate feedback) lets children with intellectual disability learn the same skill. Substituting a different activity or letting peers do it removes the learning opportunity.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"गोपाल, कक्षा III का हल्की बौद्धिक अक्षमता वाला बच्चा, ‘मेज़ नापो, उसे दर्ज करो और अपने दोस्त की मेज़ से तुलना करो’ जैसे बहु-चरणीय कार्य का पालन नहीं कर पाता। शिक्षक की कौन-सी कार्रवाई सबसे उपयुक्त है?","optionsHi":["पूरा निर्देश और ज़ोर से तथा धीरे दोहराना जब तक वह बिना मदद के एक ही बार में पूरा पालन न कर ले","कार्य को मूर्त सामग्री और प्रदर्शन के साथ छोटे चरणों में बाँटना, और प्रत्येक चरण के बाद प्रतिपुष्टि देना","जब बाकी नापें तब उसे रंग भरने की शीट देना, ताकि वह पीछे छूटा महसूस न करे","किसी सहपाठी से उसके लिए कार्य करवाना, ताकि समूह की मेज़ समय पर पूरी हो जाए"],"explanationHi":"कार्य-विश्लेषण (छोटे चरण, मूर्त सहारा, तत्काल प्रतिपुष्टि) बौद्धिक अक्षमता वाले बच्चों को वही कौशल सीखने देता है। अलग गतिविधि थमाना या साथियों से करवाना सीखने का अवसर छीन लेता है।"},
  {"id":"cdp-pedagogy-subjects-793","question":"Pooja in Class V finishes every maths task in minutes and then disturbs others out of boredom. What is the most appropriate step for the teacher?","options":["Give her more problems of the same type, so that she stays busy and gets extra practice in the meantime","Make her sit quietly until the others finish, as a useful lesson in patience and in respecting her slower classmates","Promote her to Class VI immediately, since the Class V syllabus is clearly too easy for her","Offer enrichment: deeper, open-ended problems on the same concept, and at times let her explain solutions to peers"],"answer":3,"explanation":"Gifted learners need greater depth and complexity, not more of the same, which feels like a penalty. Enrichment keeps her engaged while the class continues; skipping a grade is a much bigger decision than the problem needs.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा V की पूजा हर गणित कार्य मिनटों में पूरा कर लेती है और फिर ऊब के कारण दूसरों को परेशान करती है। शिक्षक के लिए सबसे उपयुक्त कदम क्या है?","optionsHi":["उसे उसी प्रकार के और प्रश्न देना, ताकि वह व्यस्त रहे और इस बीच अतिरिक्त अभ्यास पा ले","उसे तब तक चुपचाप बैठाना जब तक बाकी पूरा न कर लें, धैर्य और धीमे सहपाठियों के सम्मान के उपयोगी पाठ के रूप में","उसे तुरंत कक्षा VI में पदोन्नत कर देना, क्योंकि कक्षा V का पाठ्यक्रम स्पष्ट रूप से उसके लिए बहुत आसान है","संवर्धन देना: उसी संप्रत्यय पर गहरे, खुले प्रश्न, और कभी-कभी उसे साथियों को हल समझाने देना"],"explanationHi":"प्रतिभाशाली शिक्षार्थियों को अधिक गहराई और जटिलता चाहिए, उसी का और अधिक नहीं, जो दंड जैसा लगता है। संवर्धन उसे संलग्न रखता है जबकि कक्षा आगे बढ़ती है; कक्षा छोड़ना समस्या की आवश्यकता से कहीं बड़ा निर्णय है।"},
  {"id":"cdp-pedagogy-subjects-794","question":"Arif in Class II stammers. When he answers, some classmates laugh and the teacher often finishes his sentences to save time. What should the teacher do instead?","options":["Let Arif finish, keep natural eye contact, never complete his words, and set a norm that nobody laughs","Stop asking Arif to answer orally, so that he is not embarrassed and his confidence is protected","Ask Arif to speak faster and to take a deep breath before every sentence so that the words come out","Let Arif answer only in writing for the rest of the year, so that his ideas are heard without pressure"],"answer":0,"explanation":"Patience and an accepting climate reduce the pressure that makes stammering worse; finishing sentences or telling him to 'breathe' increases it. Removing oral participation excludes him from talk, which every child needs.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा II का आरिफ़ हकलाता है। जब वह उत्तर देता है, तो कुछ सहपाठी हँसते हैं और शिक्षक समय बचाने के लिए अक्सर उसके वाक्य पूरे कर देता है। शिक्षक को इसके बजाय क्या करना चाहिए?","optionsHi":["आरिफ़ को पूरा करने देना, स्वाभाविक नज़र मिलाए रखना, कभी उसके शब्द पूरे न करना, और ऐसा मानदंड बनाना कि कोई न हँसे","आरिफ़ से मौखिक उत्तर माँगना बंद करना, ताकि वह शर्मिंदा न हो और उसका आत्मविश्वास सुरक्षित रहे","आरिफ़ से तेज़ बोलने और हर वाक्य से पहले गहरी साँस लेने को कहना ताकि शब्द निकल सकें","आरिफ़ को वर्ष के शेष भाग में केवल लिखकर उत्तर देने देना, ताकि उसके विचार बिना दबाव के सुने जाएँ"],"explanationHi":"धैर्य और स्वीकार करने वाला वातावरण उस दबाव को कम करता है जो हकलाने को बदतर बनाता है; वाक्य पूरे करना या उसे ‘साँस लो’ कहना उसे बढ़ाता है। मौखिक भागीदारी हटाना उसे बातचीत से बाहर करता है, जो हर बच्चे को चाहिए।"},
  {"id":"cdp-pedagogy-subjects-795","question":"Assertion (A): Providing a scribe in examinations for a Class VIII student with dysgraphia gives him an unfair advantage over other students. Reason (R): Accommodations change the way a student shows learning, not the learning outcome being assessed.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"A scribe removes the barrier of handwriting so the test measures what it is meant to measure; the standard of answers is the same. R is true and it shows why A is false.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"अभिकथन (A): लेखन-अक्षमता (डिसग्राफ़िया) वाले कक्षा VIII के विद्यार्थी को परीक्षाओं में लेखक (स्क्राइब) देना उसे दूसरे विद्यार्थियों पर अनुचित लाभ देता है। कारण (R): समायोजन विद्यार्थी के सीखने को दिखाने का तरीका बदलते हैं, मूल्यांकित किए जा रहे अधिगम परिणाम को नहीं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"लेखक हस्तलेखन की बाधा हटाता है ताकि परीक्षा वही मापे जो उसे मापना चाहिए; उत्तरों का स्तर वही रहता है। R सत्य है और दिखाता है कि A असत्य क्यों है।"},
  {"id":"cdp-pedagogy-subjects-796","question":"A Class IV teacher in Hyderabad gives all examples in her lessons from one community's festivals, food and names. Children from other backgrounds stay quiet. Which step would best make the classroom more inclusive?","options":["Avoid examples from any community at all, so that no child feels singled out or left out of the lesson","Ask children from other communities to learn about the majority festivals, so that they can fit in better with others","Draw examples from the festivals, food, names and languages of all the children, and invite them to share","Use examples only from the textbook, since these have been chosen to be neutral for every region"],"answer":2,"explanation":"Seeing their own lives in lessons gives children a sense of belonging and makes learning relevant. Removing all culture or expecting assimilation leaves minority children invisible.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"हैदराबाद की कक्षा IV की एक शिक्षिका अपने पाठों में सभी उदाहरण एक समुदाय के त्योहारों, भोजन और नामों से देती है। अन्य पृष्ठभूमियों के बच्चे चुप रहते हैं। कौन-सा कदम कक्षा को सबसे अधिक समावेशी बनाएगा?","optionsHi":["किसी भी समुदाय के उदाहरण पूरी तरह छोड़ देना, ताकि कोई बच्चा अलग या पाठ से बाहर महसूस न करे","अन्य समुदायों के बच्चों से बहुसंख्यक त्योहारों के बारे में सीखने को कहना, ताकि वे दूसरों के साथ बेहतर घुल-मिल सकें","सभी बच्चों के त्योहारों, भोजन, नामों और भाषाओं से उदाहरण लेना, और उन्हें साझा करने के लिए आमंत्रित करना","केवल पाठ्यपुस्तक के उदाहरणों का प्रयोग करना, क्योंकि वे हर क्षेत्र के लिए तटस्थ चुने गए हैं"],"explanationHi":"पाठों में अपना जीवन देखना बच्चों को अपनत्व का बोध देता है और अधिगम को प्रासंगिक बनाता है। सारी संस्कृति हटाना या आत्मसात्करण की अपेक्षा करना अल्पसंख्यक बच्चों को अदृश्य छोड़ देता है।"},
  {"id":"cdp-pedagogy-subjects-797","question":"A Class VII teacher notices that several girls are absent for a few days every month, and learns it is linked to menstruation and lack of facilities. What is the most appropriate response?","options":["Mark them absent without comment, since menstruation is a private matter the school should not discuss","Press the head and SMC for private toilets and sanitary support, and hold stigma-free talks on menstrual health","Advise the girls to rest and cope at home on those days, and borrow notes from classmates afterwards","Tell only the girls' mothers to send them to school regularly, since attendance is the family's duty"],"answer":1,"explanation":"Absence linked to menstruation is a barrier the school can address through facilities and by breaking stigma; a safe school includes these needs. Treating it as only a private or family issue leaves the barrier in place.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VII की एक शिक्षिका देखती है कि कई लड़कियाँ हर महीने कुछ दिन अनुपस्थित रहती हैं, और पता चलता है कि यह मासिक धर्म और सुविधाओं की कमी से जुड़ा है। सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["बिना टिप्पणी के उन्हें अनुपस्थित अंकित करना, क्योंकि मासिक धर्म निजी मामला है जिस पर विद्यालय को चर्चा नहीं करनी चाहिए","प्रधानाध्यापक और SMC पर निजी शौचालयों और सैनिटरी सहायता के लिए दबाव डालना, और मासिक धर्म स्वास्थ्य पर कलंक-मुक्त चर्चाएँ करना","लड़कियों को सलाह देना कि उन दिनों घर पर आराम करें और सँभालें, और बाद में सहपाठियों से नोट्स ले लें","केवल लड़कियों की माताओं से कहना कि उन्हें नियमित रूप से विद्यालय भेजें, क्योंकि उपस्थिति परिवार का कर्तव्य है"],"explanationHi":"मासिक धर्म से जुड़ी अनुपस्थिति ऐसी बाधा है जिसे विद्यालय सुविधाओं और कलंक तोड़कर संबोधित कर सकता है; सुरक्षित विद्यालय में ये आवश्यकताएँ शामिल हैं। इसे केवल निजी या पारिवारिक मुद्दा मानना बाधा को बनाए रखता है।"},
  {"id":"cdp-pedagogy-subjects-798","question":"Consider the following statements about inclusive education: 1. Inclusion means changing the school to fit the child rather than expecting the child to fit the school. 2. Inclusion is concerned only with children with disabilities. 3. Inclusive classrooms also benefit children without disabilities. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Inclusion covers all forms of diversity (disability, gender, caste, language, poverty) and benefits all learners through empathy and flexible teaching. Statement 2 wrongly narrows it to disability.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"समावेशी शिक्षा के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. समावेशन का अर्थ है विद्यालय को बच्चे के अनुरूप बदलना, न कि बच्चे से विद्यालय के अनुरूप ढलने की अपेक्षा करना। 2. समावेशन केवल दिव्यांग बच्चों से संबंधित है। 3. समावेशी कक्षाएँ दिव्यांगता-रहित बच्चों को भी लाभ पहुँचाती हैं। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"समावेशन विविधता के सभी रूपों (दिव्यांगता, लिंग, जाति, भाषा, गरीबी) को शामिल करता है और सहानुभूति तथा लचीले शिक्षण द्वारा सभी शिक्षार्थियों को लाभ पहुँचाता है। कथन 2 इसे गलत ढंग से केवल दिव्यांगता तक सीमित करता है।"},
  {"id":"cdp-pedagogy-subjects-799","question":"Eight-year-old Nisha, usually cheerful, has become withdrawn and tearful since her parents separated. Which response by the class teacher is best?","options":["Mention her family situation in class so that her classmates understand and are extra kind to her","Ignore it, since family matters are outside a teacher's role and children usually settle down in time on their own","Talk to her privately and warmly, keep a calm routine, involve the counsellor with care, and keep it confidential","Give her extra work to keep her mind busy, so that she has less time to think about the separation"],"answer":2,"explanation":"Emotional safety needs a caring adult, predictability, professional support and confidentiality. Disclosing her situation in class or ignoring her distress would harm her further.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"आठ वर्ष की निशा, जो सामान्यतः प्रसन्न रहती है, अपने माता-पिता के अलग होने के बाद से अलग-थलग और रुआँसी हो गई है। कक्षा-शिक्षक की कौन-सी प्रतिक्रिया सबसे अच्छी है?","optionsHi":["कक्षा में उसकी पारिवारिक स्थिति का उल्लेख करना ताकि उसके सहपाठी समझें और उसके प्रति विशेष रूप से दयालु हों","इसे अनदेखा करना, क्योंकि पारिवारिक मामले शिक्षक की भूमिका से बाहर हैं और बच्चे आमतौर पर समय के साथ स्वयं सँभल जाते हैं","उससे निजी तौर पर और स्नेह से बात करना, शांत दिनचर्या बनाए रखना, सावधानी से परामर्शदाता को शामिल करना, और इसे गोपनीय रखना","उसे अतिरिक्त काम देना ताकि उसका मन व्यस्त रहे और अलगाव के बारे में सोचने का कम समय मिले"],"explanationHi":"भावनात्मक सुरक्षा के लिए स्नेही वयस्क, पूर्वानुमेयता, व्यावसायिक सहयोग और गोपनीयता चाहिए। कक्षा में उसकी स्थिति उजागर करना या उसके कष्ट को अनदेखा करना उसे और हानि पहुँचाएगा।"},
  {"id":"cdp-pedagogy-subjects-800","question":"Asked ‘Which is larger, 2n or n + 2?’, a Class 7 student answers at once, ‘2n, because multiplying makes things bigger.’ What should the teacher help her see?","options":["She is right, because doubling a number always gives at least as much as adding 2 to it","She is wrong, because for whole numbers adding 2 always gives more than doubling the number","It depends on n: 2n is larger if n > 2, they are equal at n = 2, and n + 2 is larger if n < 2","The question cannot be answered, because letters stand for objects and so cannot be compared in size"],"answer":2,"explanation":"Trying n = 1, 2 and 5 shows that the answer changes. The student treats n as a fixed number and uses the false idea that multiplying always makes bigger; seeing n as any number is the heart of algebraic thinking.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"पूछे जाने पर ‘2n और n + 2 में कौन बड़ा है?’, कक्षा 7 की एक विद्यार्थी तुरंत उत्तर देती है, ‘2n, क्योंकि गुणा करने से चीज़ें बड़ी हो जाती हैं।’ शिक्षक को उसे क्या देखने में मदद करनी चाहिए?","optionsHi":["वह सही है, क्योंकि किसी संख्या को दोगुना करने पर हमेशा उसमें 2 जोड़ने से कम से कम उतना मिलता है","वह गलत है, क्योंकि पूर्ण संख्याओं के लिए 2 जोड़ना हमेशा संख्या को दोगुना करने से अधिक देता है","यह n पर निर्भर करता है: यदि n > 2 तो 2n बड़ा है, n = 2 पर बराबर हैं, और यदि n < 2 तो n + 2 बड़ा है","प्रश्न का उत्तर नहीं दिया जा सकता, क्योंकि अक्षर वस्तुओं के लिए होते हैं और इसलिए उनके आकार की तुलना नहीं हो सकती"],"explanationHi":"n = 1, 2 और 5 आज़माने से दिखता है कि उत्तर बदलता है। विद्यार्थी n को निश्चित संख्या मान रही है और इस गलत विचार का प्रयोग कर रही है कि गुणा हमेशा बड़ा करता है; n को कोई भी संख्या मानना बीजगणितीय चिंतन का मर्म है।"},
  {"id":"cdp-pedagogy-subjects-801","question":"Asked to ‘add 5 to x’, a Class 6 student says the question is incomplete ‘because x + 5 is not an answer; we must get a number’. This difficulty is known as:","options":["lack of closure, not accepting an expression as a complete answer","letter as object, where the letter x is read as a name for a thing","reversal error, where the order of words is copied into the symbols","over-generalising the distributive law to every kind of bracket"],"answer":0,"explanation":"From arithmetic, children expect every answer to be a single number. Accepting x + 5 as both a process and an answer (an object) is a key step towards algebra.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"‘x में 5 जोड़ो’ कहने पर कक्षा 6 की एक विद्यार्थी कहती है कि प्रश्न अधूरा है ‘क्योंकि x + 5 उत्तर नहीं है; हमें संख्या मिलनी चाहिए’। इस कठिनाई को कहते हैं:","optionsHi":["संवरण का अभाव (lack of closure), किसी व्यंजक को पूर्ण उत्तर के रूप में स्वीकार न करना","अक्षर वस्तु के रूप में, जहाँ अक्षर x को किसी वस्तु का नाम समझा जाता है","उत्क्रमण त्रुटि, जहाँ शब्दों का क्रम प्रतीकों में उतार दिया जाता है","वितरण नियम का हर प्रकार के कोष्ठक पर अति-सामान्यीकरण"],"explanationHi":"अंकगणित से बच्चे अपेक्षा करते हैं कि हर उत्तर एक संख्या हो। x + 5 को प्रक्रिया और उत्तर (वस्तु) दोनों के रूप में स्वीकार करना बीजगणित की ओर एक मुख्य कदम है।"},
  {"id":"cdp-pedagogy-subjects-802","question":"‘At a school there are 6 times as many students as teachers.’ Using S for students and T for teachers, a Class 8 student writes 6S = T. What is the best way to help her?","options":["Tell her to write the letters in the same order in which the words appear in the sentence","Ask her to test it with numbers: if there are 10 teachers, does 6S = T give 60 students?","Give her the rule ‘the bigger group always gets the number’ so that she can check quickly","Accept it, since it uses both letters correctly and matches the wording of the sentence"],"answer":1,"explanation":"This is the classic reversal error: S and T are read as labels (‘6 students for each teacher’), not as numbers. Testing with T = 10 shows 6S = 10 is absurd; the correct equation is S = 6T.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"‘एक विद्यालय में शिक्षकों से 6 गुना विद्यार्थी हैं।’ विद्यार्थियों के लिए S और शिक्षकों के लिए T का प्रयोग करते हुए, कक्षा 8 की एक विद्यार्थी 6S = T लिखती है। उसकी मदद करने का सबसे अच्छा तरीका क्या है?","optionsHi":["उससे कहना कि अक्षरों को उसी क्रम में लिखे जिस क्रम में वे वाक्य में आते हैं","उससे संख्याओं से जाँचने को कहना: यदि 10 शिक्षक हैं, तो क्या 6S = T से 60 विद्यार्थी मिलते हैं?","उसे नियम देना ‘बड़े समूह को हमेशा संख्या मिलती है’ ताकि वह जल्दी जाँच सके","इसे स्वीकार कर लेना, क्योंकि यह दोनों अक्षरों का सही प्रयोग करता है और वाक्य के शब्दों से मेल खाता है"],"explanationHi":"यह क्लासिक उत्क्रमण त्रुटि है: S और T को संख्याओं के बजाय लेबल (‘प्रत्येक शिक्षक पर 6 विद्यार्थी’) पढ़ा गया है। T = 10 से जाँचने पर 6S = 10 बेतुका दिखता है; सही समीकरण S = 6T है।"},
  {"id":"cdp-pedagogy-subjects-803","question":"A Class 7 student solves 3x = 12 and writes x = 9. What has she most likely done?","options":["Divided 12 by 3 and made a slip in the division","Confused 3x with x³","Subtracted 12 from 3 and dropped the sign","Read 3x as 3 + x and subtracted 3 from 12"],"answer":3,"explanation":"Getting 9 from 12 means she ‘undid’ an addition, so she read 3x as 3 + x. Asking ‘what does 3x mean?’ and checking 3 × 9 = 27 ≠ 12 by substitution exposes this.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक विद्यार्थी 3x = 12 हल करके x = 9 लिखती है। उसने सबसे संभावित रूप से क्या किया है?","optionsHi":["12 को 3 से भाग दिया और भाग में चूक कर दी","3x को x³ से उलझा दिया","12 को 3 में से घटाया और चिह्न छोड़ दिया","3x को 3 + x पढ़ा और 3 को 12 में से घटाया"],"explanationHi":"12 से 9 पाना दर्शाता है कि उसने एक योग को ‘उलटा’ किया, इसलिए उसने 3x को 3 + x पढ़ा। ‘3x का अर्थ क्या है?’ पूछना और प्रतिस्थापन से 3 × 9 = 27 ≠ 12 जाँचना इसे उजागर करता है।"},
  {"id":"cdp-pedagogy-subjects-804","question":"A Class 8 student writes (a + b)² = a² + b². Which response is most likely to change her understanding?","options":["Draw a square of side a + b, split it into parts and ask her to find each part's area","Ask her to learn the identity (a + b)² = a² + 2ab + b² by heart and recite it daily","Tell her that the power cannot be given to each term separately and must be applied whole","Give her ten more expansions to practise, so that the correct form becomes a habit"],"answer":0,"explanation":"The area model shows a² and b² plus two rectangles of area ab, giving a² + 2ab + b². Checking with a = 2 and b = 3 (25 versus 13) also shows the error. She has over-generalised the distributive law.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा 8 की एक विद्यार्थी (a + b)² = a² + b² लिखती है। कौन-सी प्रतिक्रिया उसकी समझ को बदलने की सबसे अधिक संभावना रखती है?","optionsHi":["भुजा a + b का वर्ग बनाना, उसे भागों में बाँटना और उससे प्रत्येक भाग का क्षेत्रफल निकालने को कहना","उससे सर्वसमिका (a + b)² = a² + 2ab + b² कंठस्थ करने और रोज़ दोहराने को कहना","उसे बताना कि घात प्रत्येक पद को अलग-अलग नहीं दी जा सकती और पूरे पर लगानी होती है","उसे दस और प्रसार अभ्यास के लिए देना, ताकि सही रूप आदत बन जाए"],"explanationHi":"क्षेत्रफल मॉडल a² और b² के साथ ab क्षेत्रफल के दो आयत दिखाता है, जिससे a² + 2ab + b² मिलता है। a = 2 और b = 3 से जाँचना (25 बनाम 13) भी त्रुटि दिखाता है। उसने वितरण नियम का अति-सामान्यीकरण किया है।"},
  {"id":"cdp-pedagogy-subjects-805","question":"Asked to find the value of 2x² when x = 3, a Class 7 student writes 36. What is the error?","options":["She has added instead of multiplying at some step of the work","She has calculated 2 × 3 × 2, doubling the power instead of squaring","She has squared 2x instead of only x; it should be 2 × 9 = 18","She has substituted the wrong value of x into the expression"],"answer":2,"explanation":"In 2x² the power belongs only to x, so 2x² = 2 × 3² = 18. Her answer 36 is (2 × 3)². Writing 2 × x × x helps students see what the power applies to.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"x = 3 होने पर 2x² का मान निकालने को कहने पर कक्षा 7 की एक विद्यार्थी 36 लिखती है। त्रुटि क्या है?","optionsHi":["उसने कार्य के किसी चरण में गुणा के बजाय जोड़ दिया है","उसने 2 × 3 × 2 की गणना की है, घात का वर्ग करने के बजाय उसे दोगुना कर दिया","उसने केवल x की बजाय 2x का वर्ग कर दिया; यह 2 × 9 = 18 होना चाहिए","उसने व्यंजक में x का गलत मान रखा है"],"explanationHi":"2x² में घात केवल x की है, इसलिए 2x² = 2 × 3² = 18। उसका उत्तर 36 (2 × 3)² है। 2 × x × x लिखना विद्यार्थियों को दिखाता है कि घात किस पर लागू होती है।"},
  {"id":"cdp-pedagogy-subjects-806","question":"For a tile pattern of 5, 8, 11, 14, … tiles, a student finds the 20th figure by adding 3 again and again in a table. Which next step by the teacher best moves her towards algebraic thinking?","options":["Tell her that her method is wrong and that adding again and again is not proper mathematics","Ask her to continue the table carefully up to the 50th figure, so that she becomes fully fluent in the pattern","Give her the formula for the nth term of an arithmetic progression and ask her to apply it","Ask how the number of tiles is linked to the figure number, such as how to find the 100th figure directly"],"answer":3,"explanation":"Adding 3 each time is recursive thinking; linking tiles to the figure number (3n + 2) is functional thinking, which lets her generalise. A large figure number makes the step-by-step table impractical and invites the rule.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"5, 8, 11, 14, … टाइलों वाले टाइल प्रतिरूप के लिए एक विद्यार्थी सारणी में बार-बार 3 जोड़कर 20वीं आकृति निकालती है। शिक्षक का कौन-सा अगला कदम उसे बीजगणितीय चिंतन की ओर सबसे अच्छी तरह ले जाता है?","optionsHi":["उसे बताना कि उसकी विधि गलत है और बार-बार जोड़ना उचित गणित नहीं है","उससे सारणी को ध्यान से 50वीं आकृति तक जारी रखने को कहना, ताकि वह प्रतिरूप में पूरी तरह धाराप्रवाह हो जाए","उसे समांतर श्रेढ़ी के nवें पद का सूत्र देना और उसे लगाने को कहना","पूछना कि टाइलों की संख्या आकृति क्रमांक से कैसे जुड़ी है, जैसे 100वीं आकृति सीधे कैसे निकालें"],"explanationHi":"हर बार 3 जोड़ना पुनरावर्ती चिंतन है; टाइलों को आकृति क्रमांक से जोड़ना (3n + 2) फलनात्मक चिंतन है, जो उसे सामान्यीकरण करने देता है। बड़ा आकृति क्रमांक चरण-दर-चरण सारणी को अव्यावहारिक बनाता है और नियम को आमंत्रित करता है।"},
  {"id":"cdp-pedagogy-subjects-807","question":"For the number of border tiles around an n × n square of tiles, students give 4n + 4, 2n + 2(n + 2), 4(n + 1) and (n + 2)² − n². What should the teacher do?","options":["Accept only 4n + 4, since it is the simplest form and the others are needlessly long","Have each student link their expression to how they saw the figure, then show that all four are equal","Accept only (n + 2)² − n², since it is the only one that uses the area of the squares","Tell the class that more than one formula means some students must have counted the tiles wrongly"],"answer":1,"explanation":"All four expressions simplify to 4n + 4, and each comes from seeing the border differently. Linking every expression to the figure, and then proving them equivalent, gives meaning to algebraic manipulation.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"टाइलों के n × n वर्ग के चारों ओर किनारे की टाइलों की संख्या के लिए विद्यार्थी 4n + 4, 2n + 2(n + 2), 4(n + 1) और (n + 2)² − n² देते हैं। शिक्षक को क्या करना चाहिए?","optionsHi":["केवल 4n + 4 स्वीकार करना, क्योंकि यह सबसे सरल रूप है और अन्य अनावश्यक रूप से लंबे हैं","प्रत्येक विद्यार्थी से अपने व्यंजक को इस बात से जोड़ने को कहना कि उसने आकृति कैसे देखी, फिर दिखाना कि चारों बराबर हैं","केवल (n + 2)² − n² स्वीकार करना, क्योंकि यह एकमात्र है जो वर्गों के क्षेत्रफल का प्रयोग करता है","कक्षा को बताना कि एक से अधिक सूत्र का अर्थ है कि कुछ विद्यार्थियों ने टाइलें गलत गिनी होंगी"],"explanationHi":"चारों व्यंजक 4n + 4 में सरल हो जाते हैं, और प्रत्येक किनारे को अलग तरह से देखने से आता है। हर व्यंजक को आकृति से जोड़ना और फिर उनकी तुल्यता सिद्ध करना बीजगणितीय हेरफेर को अर्थ देता है।"},
  {"id":"cdp-pedagogy-subjects-808","question":"Match each statement with the role the letter plays in it. 1. x + 3 = 8 2. a + b = b + a 3. y = 2x + 1 4. A = l × b; a. a formula linking measures b. a generalised number (true for every value) c. a specific unknown d. a quantity that varies with another","options":["1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-b, 2-c, 3-d, 4-a","1-c, 2-b, 3-a, 4-d"],"answer":0,"explanation":"In x + 3 = 8 the letter has one value; in a + b = b + a it stands for any numbers; in y = 2x + 1, y changes as x changes; A = l × b links area to length and breadth. Students need to meet all these uses.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"प्रत्येक कथन का मिलान उस भूमिका से कीजिए जो उसमें अक्षर निभाता है। 1. x + 3 = 8 2. a + b = b + a 3. y = 2x + 1 4. A = l × b; a. मापों को जोड़ने वाला सूत्र b. सामान्यीकृत संख्या (प्रत्येक मान के लिए सत्य) c. विशिष्ट अज्ञात d. दूसरी राशि के साथ बदलने वाली राशि","optionsHi":["1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-b, 2-c, 3-d, 4-a","1-c, 2-b, 3-a, 4-d"],"explanationHi":"x + 3 = 8 में अक्षर का एक मान है; a + b = b + a में वह कोई भी संख्या दर्शाता है; y = 2x + 1 में x के बदलने पर y बदलता है; A = l × b क्षेत्रफल को लंबाई और चौड़ाई से जोड़ता है। विद्यार्थियों को इन सभी प्रयोगों से मिलना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-809","question":"Which statement about using a pan balance to teach equations is correct?","options":["It cannot model any equation that has the unknown on both sides, such as 3x + 2 = x + 8","It is meant mainly to teach the rule ‘change the side, change the sign’ in a concrete way","It shows ‘do the same to both sides’ well, but is awkward for subtraction or negatives, as in 2x − 3 = 7","It should replace written symbols completely in Class 7, since the physical model is much easier for children to grasp"],"answer":2,"explanation":"Removing equal weights from both pans models solving well, and it handles unknowns on both sides. But you cannot place negative weights in a pan, so the model has limits; that is why teachers also use other models.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"समीकरण पढ़ाने के लिए पलड़े वाली तराज़ू के प्रयोग के बारे में कौन-सा कथन सही है?","optionsHi":["यह 3x + 2 = x + 8 जैसे किसी भी ऐसे समीकरण का मॉडल नहीं बना सकती जिसमें अज्ञात दोनों ओर हो","इसका उद्देश्य मुख्यतः मूर्त रूप में नियम ‘पक्ष बदलो, चिह्न बदलो’ सिखाना है","यह ‘दोनों पक्षों में समान करो’ को अच्छी तरह दिखाती है, पर 2x − 3 = 7 जैसे घटाव या ऋणात्मकों के लिए असुविधाजनक है","इसे कक्षा 7 में लिखित प्रतीकों की जगह पूरी तरह ले लेनी चाहिए, क्योंकि भौतिक मॉडल बच्चों के लिए बहुत आसान है"],"explanationHi":"दोनों पलड़ों से समान भार हटाना हल करने का अच्छा मॉडल है, और यह दोनों ओर अज्ञात को भी सँभालता है। पर पलड़े में ऋणात्मक भार नहीं रखे जा सकते, इसलिए मॉडल की सीमाएँ हैं; इसीलिए शिक्षक अन्य मॉडल भी प्रयोग करते हैं।"},
  {"id":"cdp-pedagogy-subjects-810","question":"A Class 7 student solves x − 5 = 12 as ‘x = 12 − 5 = 7, because I moved the 5 across’. Which response best helps?","options":["Repeat the rule ‘change side, change sign’ more firmly until she applies it correctly","Give her ten similar equations to practise, so that the correct move becomes automatic","Tell her to always add the numbers that appear on both sides of an equation","Ask her to put x = 7 back into x − 5 = 12, then think of adding 5 to both sides"],"answer":3,"explanation":"Substitution shows 7 − 5 = 2, not 12. Seeing ‘add 5 to both sides’ (x = 17) gives meaning to the move; the rote ‘move across’ rule is exactly what she has misapplied.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक विद्यार्थी x − 5 = 12 को इस तरह हल करती है ‘x = 12 − 5 = 7, क्योंकि मैंने 5 को उस पार ले जाया’। कौन-सी प्रतिक्रिया सबसे अधिक मदद करती है?","optionsHi":["नियम ‘पक्ष बदलो, चिह्न बदलो’ को और दृढ़ता से दोहराना जब तक वह उसे सही ढंग से न लगाए","उसे दस ऐसे ही समीकरण अभ्यास के लिए देना, ताकि सही चाल स्वचालित हो जाए","उससे कहना कि समीकरण के दोनों ओर दिखने वाली संख्याओं को हमेशा जोड़े","उससे x = 7 को x − 5 = 12 में वापस रखने को कहना, फिर दोनों पक्षों में 5 जोड़ने के बारे में सोचने को कहना"],"explanationHi":"प्रतिस्थापन दिखाता है कि 7 − 5 = 2, 12 नहीं। ‘दोनों पक्षों में 5 जोड़ो’ (x = 17) देखना चाल को अर्थ देता है; ‘उस पार ले जाओ’ का रटा नियम ही वह है जिसे उसने गलत लगाया है।"},
  {"id":"cdp-pedagogy-subjects-811","question":"Assertion (A): Students should be asked to substitute their solution back into the original equation. Reason (R): Substituting checks whether the value makes the equation true and builds the habit of self-checking.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"A solution is, by definition, a value that makes the equation true, so substitution is a natural check; R explains why the practice in A is valuable.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): विद्यार्थियों से अपना हल मूल समीकरण में वापस प्रतिस्थापित करने को कहा जाना चाहिए। कारण (R): प्रतिस्थापन जाँचता है कि मान समीकरण को सत्य बनाता है या नहीं और स्वयं जाँचने की आदत बनाता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"हल, परिभाषा से, वह मान है जो समीकरण को सत्य बनाए, इसलिए प्रतिस्थापन स्वाभाविक जाँच है; R बताता है कि A का अभ्यास मूल्यवान क्यों है।"},
  {"id":"cdp-pedagogy-subjects-812","question":"‘Without adding, is 37 + 48 = 38 + 47 true or false?’ Which student answer shows relational thinking?","options":["‘True, because I worked out both sides and got 85 on each side of the sign.’","‘True, because 38 is one more than 37 and 47 is one less than 48.’","‘False, because the numbers on the two sides are different, so the sums must differ.’","‘True, because both sides have two numbers and the same kind of sum.’"],"answer":1,"explanation":"Relational thinking compares the structure of both sides (one more, one less) without calculating, which is the kind of reasoning algebra needs. Option A is correct but computational.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"‘जोड़े बिना बताइए, क्या 37 + 48 = 38 + 47 सत्य है या असत्य?’ कौन-सा विद्यार्थी उत्तर संबंधपरक चिंतन दर्शाता है?","optionsHi":["‘सत्य, क्योंकि मैंने दोनों पक्ष निकाले और चिह्न के दोनों ओर 85 मिला।’","‘सत्य, क्योंकि 38, 37 से एक अधिक है और 47, 48 से एक कम है।’","‘असत्य, क्योंकि दोनों ओर की संख्याएँ अलग हैं, इसलिए योग भिन्न होंगे।’","‘सत्य, क्योंकि दोनों ओर दो संख्याएँ हैं और एक ही प्रकार का योग है।’"],"explanationHi":"संबंधपरक चिंतन गणना किए बिना दोनों पक्षों की संरचना (एक अधिक, एक कम) की तुलना करता है, जो बीजगणित के लिए आवश्यक तर्क का प्रकार है। विकल्प A सही है पर गणनात्मक है।"},
  {"id":"cdp-pedagogy-subjects-813","question":"Asked to show that the sum of any three consecutive numbers is divisible by 3, which student response shows algebraic generalisation?","options":["‘4 + 5 + 6 = 15 and 10 + 11 + 12 = 33, and both of these sums divide exactly by 3.’","‘I tried twenty different sets of three numbers and every single one of them worked.’","‘If the middle number is n, the sum is (n − 1) + n + (n + 1) = 3n, a multiple of 3.’","‘It is true because 3 is an odd number, and three odd steps always give a multiple of 3.’"],"answer":2,"explanation":"Writing the numbers in terms of n covers every case and explains why it works. Any number of examples only supports the claim; it does not prove it.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"यह दिखाने को कहने पर कि किन्हीं तीन क्रमागत संख्याओं का योग 3 से विभाज्य है, कौन-सा विद्यार्थी उत्तर बीजगणितीय सामान्यीकरण दर्शाता है?","optionsHi":["‘4 + 5 + 6 = 15 और 10 + 11 + 12 = 33, और ये दोनों योग 3 से ठीक-ठीक विभाजित होते हैं।’","‘मैंने तीन संख्याओं के बीस अलग-अलग समूह आज़माए और हर एक में यह सही निकला।’","‘यदि बीच की संख्या n है, तो योग (n − 1) + n + (n + 1) = 3n है, जो 3 का गुणज है।’","‘यह सत्य है क्योंकि 3 विषम संख्या है, और तीन विषम कदम हमेशा 3 का गुणज देते हैं।’"],"explanationHi":"संख्याओं को n के पदों में लिखना हर स्थिति को समेटता है और बताता है कि यह क्यों काम करता है। उदाहरणों की कोई भी संख्या दावे का समर्थन करती है; सिद्ध नहीं करती।"},
  {"id":"cdp-pedagogy-subjects-814","question":"A Class 7 student writes 2(x + 3) = 2x + 3. Which representation best shows her the error?","options":["A balance with 2 on one pan and x + 3 on the other, to show both sides are equal","Expanding brackets with the rule ‘multiply only the first term inside by the number’","A number line from 0 to x + 3, marking x first and then the 3","A rectangle 2 wide and x + 3 long, split into a 2 × x part and a 2 × 3 part"],"answer":3,"explanation":"The area model shows both parts are multiplied by 2: 2x + 6. Testing x = 1 (8 versus 5) also exposes it. Option B states her own wrong rule.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक विद्यार्थी 2(x + 3) = 2x + 3 लिखती है। कौन-सा निरूपण उसे त्रुटि सबसे अच्छी तरह दिखाता है?","optionsHi":["एक पलड़े पर 2 और दूसरे पर x + 3 वाली तराज़ू, यह दिखाने के लिए कि दोनों पक्ष बराबर हैं","नियम ‘कोष्ठक के भीतर केवल पहले पद को संख्या से गुणा करो’ से कोष्ठक खोलना","0 से x + 3 तक की संख्या रेखा, जिसमें पहले x और फिर 3 अंकित हो","2 चौड़ा और x + 3 लंबा आयत, जो 2 × x और 2 × 3 के भागों में बँटा हो"],"explanationHi":"क्षेत्रफल मॉडल दिखाता है कि दोनों भाग 2 से गुणा होते हैं: 2x + 6। x = 1 से जाँचना (8 बनाम 5) भी इसे उजागर करता है। विकल्प B उसका अपना गलत नियम बताता है।"},
  {"id":"cdp-pedagogy-subjects-815","question":"A student writes 3x + 2 = 5x. The teacher wants to show the error by substituting a value for x. Which value would NOT reveal the error?","options":["x = 1","x = 2","x = 0","x = 10"],"answer":0,"explanation":"At x = 1 both sides are 5, so the wrong statement looks true. At x = 2 it gives 8 against 10, at x = 0 gives 2 against 0, and at x = 10 gives 32 against 50. Teachers must choose test values with care.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"एक विद्यार्थी 3x + 2 = 5x लिखता है। शिक्षक x का मान रखकर त्रुटि दिखाना चाहता है। कौन-सा मान त्रुटि को प्रकट नहीं करेगा?","optionsHi":["x = 1","x = 2","x = 0","x = 10"],"explanationHi":"x = 1 पर दोनों पक्ष 5 हैं, इसलिए गलत कथन सत्य लगता है। x = 2 पर यह 10 के सामने 8 देता है, x = 0 पर 0 के सामने 2, और x = 10 पर 50 के सामने 32। शिक्षकों को परीक्षण-मान सावधानी से चुनने चाहिए।"},
  {"id":"cdp-pedagogy-subjects-816","question":"A Class 7 student writes (−3) − (−5) = −8. Which model best helps her make sense of the correct answer?","options":["The rule ‘two negatives make a positive’, applied to the two minus signs in the question","Counters: start with 3 red (negative), add two zero pairs, take away 5 red, and see what is left","A thermometer that reads −3 degrees and then falls by a further 5 degrees during the night","The rule that subtraction always gives an answer smaller than the starting number"],"answer":1,"explanation":"Adding two zero pairs (a red and a yellow) lets her remove 5 reds, leaving 2 yellows, so the answer is +2. A falling thermometer models subtracting a positive, and ‘two negatives make a positive’ is misapplied everywhere.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक विद्यार्थी (−3) − (−5) = −8 लिखती है। कौन-सा मॉडल सही उत्तर को समझने में उसकी सबसे अच्छी मदद करता है?","optionsHi":["नियम ‘दो ऋणात्मक मिलकर धनात्मक बनाते हैं’, जो प्रश्न के दो ऋण चिह्नों पर लगाया जाए","काउंटर: 3 लाल (ऋणात्मक) से शुरू करना, दो शून्य-युग्म जोड़ना, 5 लाल हटाना, और देखना कि क्या बचता है","एक तापमापी जो −3 डिग्री पढ़ता है और फिर रात में 5 डिग्री और गिर जाता है","यह नियम कि घटाव हमेशा आरंभिक संख्या से छोटा उत्तर देता है"],"explanationHi":"दो शून्य-युग्म (एक लाल और एक पीला) जोड़ने से वह 5 लाल हटा सकती है, जिससे 2 पीले बचते हैं, इसलिए उत्तर +2 है। गिरता तापमापी धनात्मक के घटाव का मॉडल है, और ‘दो ऋणात्मक मिलकर धनात्मक’ हर जगह गलत लगाया जाता है।"},
  {"id":"cdp-pedagogy-subjects-817","question":"Which approach best helps Class 7 students see why (−1) × (−2) = 2?","options":["State the rule that a negative times a negative is positive, and drill it with many examples","Explain that two wrongs make a right, so two negative signs together become a positive one","Extend the pattern 2 × (−2) = −4, 1 × (−2) = −2, 0 × (−2) = 0 and ask what comes next","Tell them it is a convention that cannot be explained at school level and must be accepted"],"answer":2,"explanation":"Each step adds 2, so extending the pattern gives (−1) × (−2) = 2. The pattern keeps the rule consistent with what students already know; ‘two wrongs make a right’ is a misleading slogan.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कौन-सा उपागम कक्षा 7 के विद्यार्थियों को यह देखने में सबसे अच्छी तरह मदद करता है कि (−1) × (−2) = 2 क्यों है?","optionsHi":["नियम बताना कि ऋणात्मक गुणा ऋणात्मक धनात्मक होता है, और अनेक उदाहरणों से उसका अभ्यास कराना","समझाना कि दो गलतियाँ मिलकर सही बन जाती हैं, इसलिए दो ऋण चिह्न साथ आकर धनात्मक बन जाते हैं","प्रतिरूप 2 × (−2) = −4, 1 × (−2) = −2, 0 × (−2) = 0 को आगे बढ़ाना और पूछना कि आगे क्या आता है","उन्हें बताना कि यह एक परिपाटी है जिसे विद्यालय स्तर पर समझाया नहीं जा सकता और स्वीकार करना होगा"],"explanationHi":"प्रत्येक चरण में 2 जुड़ता है, इसलिए प्रतिरूप को आगे बढ़ाने पर (−1) × (−2) = 2 मिलता है। प्रतिरूप नियम को उससे संगत रखता है जो विद्यार्थी पहले से जानते हैं; ‘दो गलतियाँ सही बनाती हैं’ भ्रामक नारा है।"},
  {"id":"cdp-pedagogy-subjects-818","question":"A Class 6 student writes 2³ = 6. What should the teacher focus on?","options":["Telling her to memorise powers of 2","Explaining that powers are not part of the Class 6 syllabus","Giving her a calculator to check","The meaning of the power: 2³ means 2 × 2 × 2, not 2 × 3"],"answer":3,"explanation":"She has multiplied the base by the exponent. Writing the power as repeated multiplication (2 × 2 × 2 = 8) fixes the meaning, which memorising answers does not.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक विद्यार्थी 2³ = 6 लिखती है। शिक्षक को किस पर ध्यान केंद्रित करना चाहिए?","optionsHi":["उससे 2 की घातें कंठस्थ करने को कहना","समझाना कि घातें कक्षा 6 के पाठ्यक्रम का हिस्सा नहीं हैं","उसे जाँचने के लिए कैलकुलेटर देना","घात का अर्थ: 2³ का अर्थ 2 × 2 × 2 है, 2 × 3 नहीं"],"explanationHi":"उसने आधार को घातांक से गुणा कर दिया है। घात को बार-बार गुणा के रूप में लिखना (2 × 2 × 2 = 8) अर्थ ठीक करता है, जो उत्तर रटने से नहीं होता।"},
  {"id":"cdp-pedagogy-subjects-819","question":"A Class 8 student writes a³ × a² = a⁶. Which response is most useful?","options":["Ask her to write both powers out in full as a × a × a and a × a and count the factors","Tell her that powers are added, not multiplied, when the bases are the same, and move on","Ask her to practise twenty such questions until the rule for indices becomes automatic","Accept it, since 3 × 2 = 6 and the index rules are only a matter of convention"],"answer":0,"explanation":"Writing out the factors shows five a's in all, so a³ × a² = a⁵. Expanding gives a reason she can use again, rather than a rule she may confuse with (a³)² = a⁶.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 की एक विद्यार्थी a³ × a² = a⁶ लिखती है। कौन-सी प्रतिक्रिया सबसे उपयोगी है?","optionsHi":["उससे दोनों घातों को a × a × a और a × a के रूप में पूरा लिखने और गुणनखंड गिनने को कहना","उसे बताना कि समान आधार होने पर घातें जोड़ी जाती हैं, गुणा नहीं, और आगे बढ़ जाना","उससे ऐसे बीस प्रश्नों का अभ्यास कराना जब तक घातांक का नियम स्वचालित न हो जाए","इसे स्वीकार कर लेना, क्योंकि 3 × 2 = 6 और घातांक के नियम केवल परिपाटी का मामला हैं"],"explanationHi":"गुणनखंड लिखने पर कुल पाँच a दिखते हैं, इसलिए a³ × a² = a⁵। विस्तार करना ऐसा कारण देता है जिसे वह फिर प्रयोग कर सकती है, ऐसे नियम की जगह जिसे वह (a³)² = a⁶ से उलझा सकती है।"},
  {"id":"cdp-pedagogy-subjects-820","question":"A teacher plays ‘think of a number, add 5, double it, subtract 10, halve it, and you get your number back’. What is the main value of then asking the class to explain the trick with a letter?","options":["It gives quick practice in the four operations through a game that students enjoy","It shows that a letter can stand for any number, so it explains why the trick always works","It shows that number tricks are often a quicker route than algebra for such problems","It helps students learn how to guess the numbers other people are thinking of"],"answer":1,"explanation":"With n: ((n + 5) × 2 − 10) ÷ 2 = n. The letter covers every possible number at once, which is exactly why algebra is useful for proving general results.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षक खेल खेलता है ‘कोई संख्या सोचो, 5 जोड़ो, दोगुना करो, 10 घटाओ, आधा करो, और तुम्हें अपनी संख्या वापस मिल जाएगी’। फिर कक्षा से इस चाल को अक्षर से समझाने को कहने का मुख्य मूल्य क्या है?","optionsHi":["यह एक ऐसे खेल के माध्यम से चार संक्रियाओं का त्वरित अभ्यास देता है जिसका विद्यार्थी आनंद लेते हैं","यह दिखाता है कि अक्षर कोई भी संख्या दर्शा सकता है, इसलिए यह समझाता है कि चाल हमेशा क्यों काम करती है","यह दिखाता है कि ऐसी समस्याओं के लिए संख्या की चालें अक्सर बीजगणित से तेज़ तरीका हैं","यह विद्यार्थियों को दूसरों की सोची संख्याओं का अनुमान लगाना सीखने में मदद करता है"],"explanationHi":"n के साथ: ((n + 5) × 2 − 10) ÷ 2 = n। अक्षर एक साथ हर संभव संख्या को समेटता है, ठीक यही कारण है कि बीजगणित सामान्य परिणाम सिद्ध करने के लिए उपयोगी है।"},
  {"id":"cdp-pedagogy-subjects-821","question":"For a function machine whose input-output table is 1 → 5, 2 → 8, 3 → 11, 4 → 14, a student says the rule is ‘add 3’. Which question best moves her towards a rule linking input and output?","options":["‘Is the output always an odd number, or does it change?’","‘What is the next output after 14, if you add 3 again?’","‘What would the output be if the input were 100?’","‘Can you add up all the outputs and find their total?’"],"answer":2,"explanation":"‘Add 3’ describes how the outputs change, not how each output depends on its input. Asking for input 100 forces a direct rule: output = 3 × input + 2, so 302.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक फलन मशीन के लिए, जिसकी निवेश-निर्गत सारणी 1 → 5, 2 → 8, 3 → 11, 4 → 14 है, एक विद्यार्थी कहती है कि नियम ‘3 जोड़ो’ है। कौन-सा प्रश्न उसे निवेश और निर्गत को जोड़ने वाले नियम की ओर सबसे अच्छी तरह ले जाता है?","optionsHi":["‘क्या निर्गत हमेशा विषम संख्या होता है, या बदलता है?’","‘14 के बाद अगला निर्गत क्या है, यदि फिर 3 जोड़ें?’","‘यदि निवेश 100 हो तो निर्गत क्या होगा?’","‘क्या तुम सभी निर्गतों को जोड़कर उनका कुल योग निकाल सकती हो?’"],"explanationHi":"‘3 जोड़ो’ बताता है कि निर्गत कैसे बदलते हैं, यह नहीं कि प्रत्येक निर्गत अपने निवेश पर कैसे निर्भर है। निवेश 100 पूछना सीधा नियम माँगता है: निर्गत = 3 × निवेश + 2, अर्थात 302।"},
  {"id":"cdp-pedagogy-subjects-822","question":"Given a + b = 10, a Class 7 student refuses to accept a = 5, b = 5 ‘because different letters must have different values’. What is the best response?","options":["Agree with her, since different letters in algebra always stand for different numbers","Tell her that a and b must always be equal, since they appear in the same equation","Tell her that letters cannot have fixed values at all, since in algebra they only stand for unknown things","Ask whether 5 + 5 makes it true, and discuss that different letters may, but need not, have the same value"],"answer":3,"explanation":"Different letters can stand for the same number; the only rule is that one letter keeps one value within a problem. Checking 5 + 5 = 10 lets her see this for herself.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"a + b = 10 दिए जाने पर कक्षा 7 की एक विद्यार्थी a = 5, b = 5 को स्वीकार करने से इनकार करती है ‘क्योंकि अलग-अलग अक्षरों के मान अलग होने चाहिए’। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["उससे सहमत होना, क्योंकि बीजगणित में अलग-अलग अक्षर हमेशा अलग-अलग संख्याएँ दर्शाते हैं","उसे बताना कि a और b हमेशा बराबर होने चाहिए, क्योंकि वे एक ही समीकरण में हैं","उसे बताना कि अक्षरों के निश्चित मान हो ही नहीं सकते, क्योंकि बीजगणित में वे केवल अज्ञात चीज़ों के लिए होते हैं","पूछना कि क्या 5 + 5 इसे सत्य बनाता है, और चर्चा करना कि अलग-अलग अक्षरों का एक ही मान हो सकता है, पर होना आवश्यक नहीं"],"explanationHi":"अलग-अलग अक्षर एक ही संख्या दर्शा सकते हैं; एकमात्र नियम यह है कि एक समस्या में एक अक्षर एक ही मान रखता है। 5 + 5 = 10 जाँचना उसे स्वयं यह देखने देता है।"},
  {"id":"cdp-pedagogy-subjects-823","question":"Solving x + x = 10, a student offers x = 3 and x = 7 ‘because 3 + 7 is 10’. Which idea does she lack?","options":["That one letter must stand for the same value everywhere in a statement","That x can only be a whole number, so fractions and decimals are not allowed","That two letters can never be added together unless their values are known","That an equation has no solution unless it is first written in the form 2x = 10"],"answer":0,"explanation":"Within one statement, each x stands for the same number, so x + x = 2x = 10 gives x = 5. She is treating each x as a separate unknown.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"x + x = 10 हल करते हुए एक विद्यार्थी x = 3 और x = 7 देती है ‘क्योंकि 3 + 7 है 10’। उसमें कौन-सा विचार नहीं है?","optionsHi":["कि एक अक्षर को एक कथन में हर जगह एक ही मान दर्शाना चाहिए","कि x केवल पूर्ण संख्या हो सकता है, इसलिए भिन्न और दशमलव अनुमत नहीं हैं","कि दो अक्षरों को तब तक जोड़ा नहीं जा सकता जब तक उनके मान ज्ञात न हों","कि समीकरण का कोई हल नहीं होता जब तक उसे पहले 2x = 10 के रूप में न लिखा जाए"],"explanationHi":"एक कथन में प्रत्येक x एक ही संख्या दर्शाता है, इसलिए x + x = 2x = 10 से x = 5 मिलता है। वह प्रत्येक x को अलग अज्ञात मान रही है।"},
  {"id":"cdp-pedagogy-subjects-824","question":"Which of these statements about preparing children for algebra are correct? I. Pattern work in the primary classes lays a foundation for algebra. II. Children should not meet letters for numbers before Class 8. III. Understanding ‘=’ as ‘has the same value as’ is needed for solving equations. IV. Teaching that ‘a stands for apple’ helps build the idea of a variable.","options":["I, III and IV","I and III only","II and IV only","I, II and III"],"answer":1,"explanation":"Patterns and a relational ‘=’ prepare children for algebra. ‘a for apple’ makes the letter a label for objects, not a number, which causes later errors; and letters appear from Class 6, not Class 8.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"बच्चों को बीजगणित के लिए तैयार करने के बारे में इनमें से कौन-से कथन सही हैं? I. प्राथमिक कक्षाओं में प्रतिरूप कार्य बीजगणित की नींव रखता है। II. बच्चों को कक्षा 8 से पहले संख्याओं के लिए अक्षरों से नहीं मिलना चाहिए। III. ‘=’ को ‘का समान मान है’ के रूप में समझना समीकरण हल करने के लिए आवश्यक है। IV. यह सिखाना कि ‘a का अर्थ सेब है’ चर के विचार को बनाने में मदद करता है।","optionsHi":["I, III और IV","केवल I और III","केवल II और IV","I, II और III"],"explanationHi":"प्रतिरूप और संबंधपरक ‘=’ बच्चों को बीजगणित के लिए तैयार करते हैं। ‘a का अर्थ सेब’ अक्षर को वस्तुओं का लेबल बनाता है, संख्या नहीं, जिससे आगे त्रुटियाँ होती हैं; और अक्षर कक्षा 6 से आते हैं, कक्षा 8 से नहीं।"},
  {"id":"cdp-pedagogy-subjects-825","question":"Class VII students list the work done by each family member. Several write about their mothers, 'She does nothing; she is a housewife.' What should the teacher help them recognise?","options":["That housewives do no productive work, since they are not employed, so the entries are correct","That only work done outside the home for a salary or wage can properly be counted as work","That cooking, cleaning, fetching water and caring are work, though unpaid and often undervalued","That the activity should be dropped, since it touches on private family matters best left alone"],"answer":2,"explanation":"Household and care work takes long hours and keeps families running, yet because it is unpaid it is often treated as 'nothing'. Making this work visible is a key gender concern of the social science curriculum.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा VII के विद्यार्थी परिवार के प्रत्येक सदस्य द्वारा किए जाने वाले कार्य की सूची बनाते हैं। कई अपनी माँओं के बारे में लिखते हैं, ‘वह कुछ नहीं करती; वह गृहिणी है।’ शिक्षक को उन्हें क्या पहचानने में मदद करनी चाहिए?","optionsHi":["कि गृहिणियाँ कोई उत्पादक कार्य नहीं करतीं, क्योंकि वे नियोजित नहीं हैं, इसलिए प्रविष्टियाँ सही हैं","कि केवल वेतन या मज़दूरी के लिए घर के बाहर किए गए कार्य को ही उचित रूप से कार्य गिना जा सकता है","कि खाना बनाना, सफाई, पानी लाना और देखभाल करना कार्य हैं, भले ही अवैतनिक और अक्सर कम आँके जाते हों","कि गतिविधि छोड़ देनी चाहिए, क्योंकि वह निजी पारिवारिक मामलों को छूती है जिन्हें अकेला छोड़ना बेहतर है"],"explanationHi":"घरेलू और देखभाल का कार्य लंबे घंटे लेता है और परिवारों को चलाए रखता है, फिर भी अवैतनिक होने के कारण उसे अक्सर ‘कुछ नहीं’ माना जाता है। इस कार्य को दृश्य बनाना सामाजिक विज्ञान पाठ्यचर्या की प्रमुख लैंगिक चिंता है।"},
  {"id":"cdp-pedagogy-subjects-826","question":"A teacher replaces the phrase 'early man' with 'early people' or 'early humans' throughout her Class VI history notes. What is the best justification?","options":["The new phrase is shorter, simpler and easier for young children to spell correctly","Language shapes how we imagine the past, and 'man' tends to hide women's roles","The textbook does not use the word 'man' anywhere, so notes must match the textbook","Historians have proved that early societies were led by women rather than by men"],"answer":1,"explanation":"Gendered language quietly suggests that the past was made only by men. Inclusive terms let children picture women gathering, making tools and raising families as part of early human life.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"एक शिक्षिका अपने कक्षा VI के इतिहास के नोट्स में ‘early man’ वाक्यांश की जगह पूरे नोट्स में ‘early people’ या ‘early humans’ लिखती है। इसका सबसे अच्छा औचित्य क्या है?","optionsHi":["नया वाक्यांश छोटा, सरल है और छोटे बच्चों के लिए सही वर्तनी लिखना आसान है","भाषा हमारी अतीत की कल्पना को आकार देती है, और ‘man’ महिलाओं की भूमिकाओं को छिपाने की प्रवृत्ति रखता है","पाठ्यपुस्तक में कहीं भी ‘man’ शब्द का प्रयोग नहीं हुआ है, इसलिए नोट्स पाठ्यपुस्तक से मेल खाने चाहिए","इतिहासकारों ने सिद्ध किया है कि आरंभिक समाजों का नेतृत्व पुरुषों के बजाय महिलाएँ करती थीं"],"explanationHi":"लिंग-आधारित भाषा चुपचाप संकेत देती है कि अतीत केवल पुरुषों ने बनाया। समावेशी शब्द बच्चों को आरंभिक मानव जीवन के भाग के रूप में महिलाओं को संग्रह करते, औज़ार बनाते और परिवार पालते हुए कल्पना करने देते हैं।"},
  {"id":"cdp-pedagogy-subjects-827","question":"In a Class VI lesson on livelihoods, a teacher's examples are a male farmer, a male doctor, a female nurse and a female teacher. Which critique is the most accurate?","options":["The examples are fine, since they match the occupations most commonly seen in society","The examples should avoid all mention of gender, so that children do not notice it at all","The lesson should focus only on men's occupations, since men are usually the main earners for most families","The examples reinforce stereotypes about work; women farmers and men in caring jobs should also appear"],"answer":3,"explanation":"Women do a large share of farm work, and men can be nurses and teachers. Examples that always pair jobs with one gender teach children a narrow, stereotyped picture of who can do what.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"आजीविका के कक्षा VI के पाठ में एक शिक्षक के उदाहरण हैं: पुरुष किसान, पुरुष डॉक्टर, महिला नर्स और महिला शिक्षिका। कौन-सी आलोचना सबसे सटीक है?","optionsHi":["उदाहरण ठीक हैं, क्योंकि वे समाज में सबसे अधिक दिखने वाले व्यवसायों से मेल खाते हैं","उदाहरणों में लिंग का कोई उल्लेख नहीं होना चाहिए, ताकि बच्चे उसे बिल्कुल न देखें","पाठ को केवल पुरुषों के व्यवसायों पर केंद्रित होना चाहिए, क्योंकि अधिकांश परिवारों में पुरुष ही मुख्य कमाने वाले होते हैं","उदाहरण कार्य के बारे में रूढ़ियों को पुष्ट करते हैं; महिला किसान और देखभाल वाले कामों में पुरुष भी दिखने चाहिए"],"explanationHi":"खेती के काम का बड़ा हिस्सा महिलाएँ करती हैं, और पुरुष नर्स और शिक्षक हो सकते हैं। जो उदाहरण हमेशा काम को एक ही लिंग से जोड़ते हैं, वे बच्चों को इस बारे में संकीर्ण, रूढ़िबद्ध तस्वीर सिखाते हैं कि कौन क्या कर सकता है।"},
  {"id":"cdp-pedagogy-subjects-828","question":"In a co-educational Class VIII, boys answer most questions while girls speak only when called upon. Which strategy best ensures equitable participation?","options":["Allow boys to continue answering, since they are more confident and keep the lesson moving","Ask girls to sit in the front rows, so that the teacher can see them and call on them more","Use structured turn-taking, give thinking time, and form mixed groups with rotating roles such as reporter","Hold separate discussions for boys and girls on different days, so that girls feel free to speak"],"answer":2,"explanation":"Wait time, deliberate turn-taking and rotating roles in mixed groups give every learner a fair chance to speak. Separating boys and girls avoids the problem instead of addressing it.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"सह-शिक्षा की कक्षा VIII में लड़के अधिकांश प्रश्नों के उत्तर देते हैं जबकि लड़कियाँ केवल बुलाए जाने पर बोलती हैं। कौन-सी युक्ति समान भागीदारी को सबसे अच्छी तरह सुनिश्चित करती है?","optionsHi":["लड़कों को उत्तर देते रहने देना, क्योंकि वे अधिक आत्मविश्वासी हैं और पाठ को चलाते रहते हैं","लड़कियों से आगे की पंक्तियों में बैठने को कहना, ताकि शिक्षक उन्हें देख सके और उन्हें अधिक बुलाए","संरचित बारी-बारी का प्रयोग करना, सोचने का समय देना, और प्रतिवेदक जैसी बदलती भूमिकाओं वाले मिश्रित समूह बनाना","लड़कों और लड़कियों के लिए अलग-अलग दिनों में अलग चर्चाएँ करना, ताकि लड़कियाँ बोलने में सहज महसूस करें"],"explanationHi":"प्रतीक्षा-समय, सोचे-समझे बारी-बारी और मिश्रित समूहों में बदलती भूमिकाएँ प्रत्येक शिक्षार्थी को बोलने का उचित अवसर देती हैं। लड़कों और लड़कियों को अलग करना समस्या को संबोधित करने के बजाय उससे बचता है।"},
  {"id":"cdp-pedagogy-subjects-829","question":"Assertion (A): Women's history in the classroom should not be limited to famous queens and freedom fighters.\nReason (R): The work, lives and struggles of ordinary women are also part of how society changed.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A list of 'great women' adds a few names but leaves the main story unchanged. Including ordinary women's experience, such as in farming, factories or reform movements, is why women's history must go beyond famous figures.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): कक्षा में महिलाओं का इतिहास प्रसिद्ध रानियों और स्वतंत्रता सेनानियों तक सीमित नहीं होना चाहिए।\nकारण (R): साधारण महिलाओं का कार्य, जीवन और संघर्ष भी इसका हिस्सा हैं कि समाज कैसे बदला।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"‘महान महिलाओं’ की सूची कुछ नाम जोड़ती है पर मुख्य कहानी को अपरिवर्तित छोड़ देती है। साधारण महिलाओं के अनुभव, जैसे खेती, कारख़ानों या सुधार आंदोलनों में, को शामिल करना ही कारण है कि महिलाओं का इतिहास प्रसिद्ध हस्तियों से आगे जाना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-830","question":"Which of the following statements about gender are correct?\n1. Gender roles are shaped by society and differ across places and periods.\n2. Differences between the roles of boys and girls are entirely biological.\n3. Textbooks and classroom practices can either reinforce or challenge gender stereotypes.","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Sex is biological, but gender roles are social constructions that vary across societies and times. Schools, through texts and practice, can strengthen stereotypes or question them; statement 2 confuses gender with sex.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"लिंग के बारे में निम्नलिखित में से कौन-से कथन सही हैं?\n1. लैंगिक भूमिकाएँ समाज द्वारा आकार पाती हैं और स्थानों तथा कालों में भिन्न होती हैं।\n2. लड़कों और लड़कियों की भूमिकाओं के बीच के अंतर पूरी तरह जैविक हैं।\n3. पाठ्यपुस्तकें और कक्षा के अभ्यास लैंगिक रूढ़ियों को या तो पुष्ट कर सकते हैं या चुनौती दे सकते हैं।","optionsHi":["केवल 1 और 2","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"लिंग (सेक्स) जैविक है, पर लैंगिक भूमिकाएँ (जेंडर) सामाजिक रचनाएँ हैं जो समाजों और कालों में भिन्न होती हैं। विद्यालय, पाठों और अभ्यास के माध्यम से, रूढ़ियों को मज़बूत कर सकते हैं या उन पर प्रश्न उठा सकते हैं; कथन 2 जेंडर को सेक्स से उलझाता है।"},
  {"id":"cdp-pedagogy-subjects-831","question":"A Class VII chapter compares how boys and girls grew up in a Pacific island society in the 1920s with how they grew up in an Indian town in the 1960s. What is the main purpose of this comparison?","options":["To show that one society treated its children better and more fairly than the other did","To teach students the geography and way of life of the Pacific islands in some detail","To prove that boys and girls are naturally suited to different tasks, whatever the society","To show that what is expected of boys and girls differs with society and time"],"answer":3,"explanation":"Seeing that childhood roles were organised differently elsewhere and at another time shows that gender roles are socially made, which opens them to questioning. The comparison argues against the 'natural' view, not for it.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा VII का एक अध्याय 1920 के दशक में प्रशांत द्वीप के एक समाज में लड़कों और लड़कियों के बड़े होने की तुलना 1960 के दशक में एक भारतीय कस्बे में उनके बड़े होने से करता है। इस तुलना का मुख्य उद्देश्य क्या है?","optionsHi":["यह दिखाना कि एक समाज ने अपने बच्चों के साथ दूसरे से बेहतर और अधिक न्यायपूर्ण व्यवहार किया","विद्यार्थियों को प्रशांत द्वीपों का भूगोल और जीवन-शैली कुछ विस्तार से सिखाना","यह सिद्ध करना कि लड़के और लड़कियाँ स्वाभाविक रूप से अलग-अलग कार्यों के उपयुक्त हैं, चाहे समाज कोई भी हो","यह दिखाना कि लड़कों और लड़कियों से जो अपेक्षित है वह समाज और समय के अनुसार भिन्न होता है"],"explanationHi":"यह देखना कि बचपन की भूमिकाएँ कहीं और और दूसरे समय में अलग ढंग से संगठित थीं, दिखाता है कि लैंगिक भूमिकाएँ सामाजिक रूप से बनी हैं, जो उन पर प्रश्न उठाने का रास्ता खोलता है। तुलना ‘स्वाभाविक’ दृष्टि के विरुद्ध तर्क देती है, उसके पक्ष में नहीं।"},
  {"id":"cdp-pedagogy-subjects-832","question":"A Class VI student with a visual impairment is in a lesson on reading the physical map of India. What is the best adaptation?","options":["Exempt her from map work, since maps are visual and she can make up the marks elsewhere","Use a raised-relief map, describe features aloud, and let a peer guide her hands across it","Ask her to listen carefully while the others read the map aloud and name its features","Give her a written list of rivers and mountains to memorise in place of the map work"],"answer":1,"explanation":"Inclusive education adapts the material so that the learner meets the same goal. Tactile maps with verbal support let her explore relief and location; exemption or rote lists deny her the learning.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VI की एक दृष्टिबाधित विद्यार्थी भारत का भौतिक मानचित्र पढ़ने के पाठ में है। सबसे अच्छा अनुकूलन क्या है?","optionsHi":["उसे मानचित्र कार्य से छूट देना, क्योंकि मानचित्र दृश्य हैं और वह अंक कहीं और से पूरे कर सकती है","उभरे उच्चावच वाले मानचित्र का प्रयोग करना, विशेषताओं का मौखिक वर्णन करना, और किसी साथी को उसके हाथों को उस पर चलाने देना","उससे ध्यान से सुनने को कहना जबकि बाकी मानचित्र को ज़ोर से पढ़ते और उसकी विशेषताओं के नाम बताते हैं","मानचित्र कार्य के बदले उसे नदियों और पर्वतों की लिखित सूची याद करने को देना"],"explanationHi":"समावेशी शिक्षा सामग्री को अनुकूलित करती है ताकि शिक्षार्थी उसी लक्ष्य तक पहुँचे। मौखिक सहायता के साथ स्पर्शीय मानचित्र उसे उच्चावच और स्थिति खोजने देते हैं; छूट या रटी सूचियाँ उसे सीखने से वंचित करती हैं।"},
  {"id":"cdp-pedagogy-subjects-833","question":"Mamata has recently moved with her family from Odisha to a Gujarati-medium school in Surat. She understands little Gujarati and stays silent in social science. What should the teacher do?","options":["Wait until she learns Gujarati fully before involving her in lessons, so that she is not confused or embarrassed","Seat her at the back for now so that she does not slow the class while she picks up the language","Use visuals and peer support, let her share ideas in her home language, and draw on her knowledge of Odisha","Give her lower-level work permanently, since she cannot follow the language used in the lessons"],"answer":2,"explanation":"Language is a bridge, not a barrier to be cleared first. Visuals, peer help and valuing her own language and experience bring her into learning now and enrich the class.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"ममता हाल ही में अपने परिवार के साथ ओडिशा से सूरत के गुजराती-माध्यम विद्यालय में आई है। वह गुजराती बहुत कम समझती है और सामाजिक विज्ञान में चुप रहती है। शिक्षक को क्या करना चाहिए?","optionsHi":["उसे पाठों में शामिल करने से पहले उसके गुजराती पूरी तरह सीख लेने की प्रतीक्षा करना, ताकि वह भ्रमित या शर्मिंदा न हो","फ़िलहाल उसे पीछे बैठाना ताकि भाषा सीखते समय वह कक्षा को धीमा न करे","चित्रों और साथियों के सहयोग का प्रयोग करना, उसे अपनी घर की भाषा में विचार साझा करने देना, और उसके ओडिशा के ज्ञान का उपयोग करना","उसे स्थायी रूप से निम्न-स्तर का काम देना, क्योंकि वह पाठों में प्रयुक्त भाषा का पालन नहीं कर सकती"],"explanationHi":"भाषा एक पुल है, ऐसी बाधा नहीं जिसे पहले पार करना हो। चित्र, साथियों की मदद, और उसकी अपनी भाषा तथा अनुभव को महत्त्व देना उसे अभी अधिगम में लाता है और कक्षा को समृद्ध करता है।"},
  {"id":"cdp-pedagogy-subjects-834","question":"A Class VI teacher's examples of festivals in a lesson on diversity come only from the majority religion, though the class has Muslim, Sikh and Christian students. What should she change?","options":["Include festivals and practices of different communities, including those of her own students","Remove all festivals from the lesson, so that religion does not enter the classroom at all","Ask minority students to explain their festivals, but only if they volunteer after school hours","Keep the examples as they are, since the textbook already lists them and they are widely known"],"answer":0,"explanation":"A lesson on diversity must reflect the diversity it describes. Showing only one community's practices makes others invisible; dropping the topic loses a meaningful link to children's lives.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VI की एक शिक्षिका के विविधता पर पाठ में त्योहारों के उदाहरण केवल बहुसंख्यक धर्म से हैं, जबकि कक्षा में मुस्लिम, सिख और ईसाई विद्यार्थी हैं। उसे क्या बदलना चाहिए?","optionsHi":["विभिन्न समुदायों के त्योहारों और प्रथाओं को शामिल करना, जिनमें उसके अपने विद्यार्थियों के भी हों","पाठ से सभी त्योहार हटा देना, ताकि धर्म कक्षा में बिल्कुल न आए","अल्पसंख्यक विद्यार्थियों से अपने त्योहार समझाने को कहना, पर केवल तब जब वे स्कूल के बाद स्वेच्छा से करें","उदाहरणों को जैसा है वैसा रखना, क्योंकि पाठ्यपुस्तक उन्हें पहले से सूचीबद्ध करती है और वे व्यापक रूप से ज्ञात हैं"],"explanationHi":"विविधता पर पाठ को उस विविधता को प्रतिबिंबित करना चाहिए जिसका वह वर्णन करता है। केवल एक समुदाय की प्रथाएँ दिखाना दूसरों को अदृश्य बनाता है; विषय छोड़ देना बच्चों के जीवन से एक सार्थक संबंध खो देता है।"},
  {"id":"cdp-pedagogy-subjects-835","question":"Which explanation of why many Adivasi communities in India are considered marginalised best fits the social science approach?","options":["Their cultures are primitive and have not developed in step with the rest of modern, urban Indian society","They prefer to stay away from mainstream society and so choose not to take up its benefits","They are fewer in number, and small groups are always marginalised in a large democracy","They have been pushed out of economic and political power, through loss of land and forest rights"],"answer":3,"explanation":"Marginalisation is a process of exclusion from resources and power, not a feature of a community's culture. Calling a culture 'primitive' is the very prejudice that social science teaching should question.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"भारत में अनेक आदिवासी समुदायों को हाशिये का क्यों माना जाता है, इसकी कौन-सी व्याख्या सामाजिक विज्ञान के उपागम पर सबसे अच्छी बैठती है?","optionsHi":["उनकी संस्कृतियाँ आदिम हैं और शेष आधुनिक, शहरी भारतीय समाज के साथ कदम मिलाकर विकसित नहीं हुईं","वे मुख्यधारा के समाज से दूर रहना पसंद करते हैं और इसलिए उसके लाभ न लेना चुनते हैं","उनकी संख्या कम है, और बड़े लोकतंत्र में छोटे समूह हमेशा हाशिये पर रहते हैं","उन्हें भूमि और वन अधिकारों की हानि के माध्यम से आर्थिक और राजनीतिक शक्ति से बाहर धकेल दिया गया है"],"explanationHi":"हाशियाकरण संसाधनों और शक्ति से बहिष्कार की प्रक्रिया है, किसी समुदाय की संस्कृति की विशेषता नहीं। किसी संस्कृति को ‘आदिम’ कहना वही पूर्वाग्रह है जिस पर सामाजिक विज्ञान शिक्षण को प्रश्न उठाना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-836","question":"While teaching the growth of Bombay, a Class VIII teacher spends time on the lives of mill workers, dock labourers and migrants from the Konkan, not only on the merchants and colonial officials. This reflects which approach to history?","options":["Great-man history","History from below","Diplomatic history","Dynastic history"],"answer":1,"explanation":"'History from below' tells the past through the experience of ordinary and working people. The other approaches centre on rulers, elites or relations between states.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"बंबई के विकास को पढ़ाते हुए कक्षा VIII का एक शिक्षक केवल व्यापारियों और औपनिवेशिक अधिकारियों पर नहीं, बल्कि मिल मज़दूरों, गोदी श्रमिकों और कोंकण से आए प्रवासियों के जीवन पर भी समय देता है। यह इतिहास के किस उपागम को दर्शाता है?","optionsHi":["महापुरुष इतिहास","नीचे से इतिहास (History from below)","कूटनीतिक इतिहास","राजवंशीय इतिहास"],"explanationHi":"‘नीचे से इतिहास’ अतीत को साधारण और श्रमिक लोगों के अनुभव के माध्यम से बताता है। अन्य उपागम शासकों, अभिजनों या राज्यों के बीच संबंधों पर केंद्रित हैं।"},
  {"id":"cdp-pedagogy-subjects-837","question":"A teacher prides herself on 'finishing the textbook line by line' every year and never using anything else. Which statement best evaluates this practice in light of NCF 2005?","options":["It makes the textbook the sole source, whereas NCF 2005 treats it as one resource among many","It is ideal, since the textbook contains everything the examination will ask about","It is acceptable only if she also gives notes from guidebooks to cover extra questions","It is wrong, because textbooks should not be used in social science teaching at all"],"answer":0,"explanation":"NCF 2005 asks teachers to go beyond the textbook and draw on the child's surroundings and other sources. Rejecting textbooks altogether is a different mistake; they remain a useful resource.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षिका को इस पर गर्व है कि वह हर वर्ष ‘पाठ्यपुस्तक को पंक्ति-दर-पंक्ति पूरा’ करती है और कभी कुछ और प्रयोग नहीं करती। NCF 2005 के आलोक में कौन-सा कथन इस अभ्यास का सबसे अच्छा मूल्यांकन करता है?","optionsHi":["यह पाठ्यपुस्तक को एकमात्र स्रोत बना देता है, जबकि NCF 2005 उसे अनेक संसाधनों में से एक मानता है","यह आदर्श है, क्योंकि पाठ्यपुस्तक में वह सब है जो परीक्षा में पूछा जाएगा","यह तभी स्वीकार्य है यदि वह अतिरिक्त प्रश्नों के लिए गाइडबुक से नोट्स भी दे","यह गलत है, क्योंकि सामाजिक विज्ञान शिक्षण में पाठ्यपुस्तकों का प्रयोग बिल्कुल नहीं होना चाहिए"],"explanationHi":"NCF 2005 शिक्षकों से पाठ्यपुस्तक से आगे जाने और बच्चे के परिवेश तथा अन्य स्रोतों का उपयोग करने को कहता है। पाठ्यपुस्तकों को पूरी तरह अस्वीकार करना अलग गलती है; वे उपयोगी संसाधन बनी रहती हैं।"},
  {"id":"cdp-pedagogy-subjects-838","question":"A Class VI geography textbook illustrates rivers with examples from the plains. A teacher in Leh uses the streams, glaciers and irrigation channels around the town for the same lesson. What does this show?","options":["She is departing from the prescribed syllabus and should go back to the textbook's own examples of rivers","She is filling a gap a national textbook cannot avoid, with local examples that give the concepts meaning","She is using local examples, which are useful only in primary classes, not in Class VI","She is right only because students in Leh do not need to learn about rivers in the plains"],"answer":1,"explanation":"A national textbook cannot cover every region. Using local geography teaches the same concepts through what the children see, and they can then compare it with other regions.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VI की एक भूगोल पाठ्यपुस्तक नदियों को मैदानों के उदाहरणों से समझाती है। लेह की एक शिक्षिका उसी पाठ के लिए कस्बे के आसपास की धाराओं, हिमनदों और सिंचाई नालियों का उपयोग करती है। यह क्या दर्शाता है?","optionsHi":["वह निर्धारित पाठ्यक्रम से हट रही है और उसे नदियों के पाठ्यपुस्तक के अपने उदाहरणों पर लौटना चाहिए","वह उस अंतराल को भर रही है जिससे एक राष्ट्रीय पाठ्यपुस्तक बच नहीं सकती, स्थानीय उदाहरणों से जो संप्रत्ययों को अर्थ देते हैं","वह स्थानीय उदाहरणों का प्रयोग कर रही है, जो केवल प्राथमिक कक्षाओं में उपयोगी हैं, कक्षा VI में नहीं","वह तभी सही है क्योंकि लेह के विद्यार्थियों को मैदानों की नदियों के बारे में सीखने की आवश्यकता नहीं है"],"explanationHi":"एक राष्ट्रीय पाठ्यपुस्तक हर क्षेत्र को नहीं समेट सकती। स्थानीय भूगोल का उपयोग वही संप्रत्यय बच्चों के देखे हुए के माध्यम से सिखाता है, और वे फिर उसकी अन्य क्षेत्रों से तुलना कर सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-839","question":"Assertion (A): NCF 2005 favours a variety of textbooks and learning materials rather than one prescribed book.\nReason (R): A single textbook can make knowledge look fixed and final and may not suit local contexts.","options":["Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"NCF 2005 encourages multiple materials because one authoritative book presents knowledge as closed and cannot reflect every region's context. R explains A.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"अभिकथन (A): NCF 2005 एक निर्धारित पुस्तक के बजाय अनेक प्रकार की पाठ्यपुस्तकों और अधिगम सामग्रियों का समर्थन करता है।\nकारण (R): एक अकेली पाठ्यपुस्तक ज्ञान को निश्चित और अंतिम दिखा सकती है और स्थानीय संदर्भों के अनुकूल नहीं हो सकती।","optionsHi":["A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है"],"explanationHi":"NCF 2005 अनेक सामग्रियों को प्रोत्साहित करता है क्योंकि एक आधिकारिक पुस्तक ज्ञान को बंद के रूप में प्रस्तुत करती है और हर क्षेत्र के संदर्भ को प्रतिबिंबित नहीं कर सकती। R, A की व्याख्या करता है।"},
  {"id":"cdp-pedagogy-subjects-840","question":"A Class VIII teacher asks students to read a textbook paragraph on the building of a railway line and to answer: 'From whose point of view is this written? Whose experience is missing?' What is she mainly teaching?","options":["That the textbook is full of errors and should be set aside in favour of other books","How to summarise a paragraph by picking out the main points of the author","That textbooks too present events from particular perspectives and can be read critically","How railways were built and who planned and paid for the railway lines"],"answer":2,"explanation":"Textbooks are not neutral windows on the past. Asking whose view is present and whose is absent, for example the labourers or the people displaced, builds critical reading without dismissing the text.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा VIII की एक शिक्षिका विद्यार्थियों से रेल लाइन के निर्माण पर पाठ्यपुस्तक का एक अनुच्छेद पढ़ने और उत्तर देने को कहती है: ‘यह किसके दृष्टिकोण से लिखा गया है? किसका अनुभव गायब है?’ वह मुख्यतः क्या सिखा रही है?","optionsHi":["कि पाठ्यपुस्तक त्रुटियों से भरी है और उसे दूसरी पुस्तकों के पक्ष में अलग रख देना चाहिए","लेखक के मुख्य बिंदुओं को चुनकर अनुच्छेद का सार कैसे बनाया जाए","कि पाठ्यपुस्तकें भी घटनाओं को विशेष दृष्टिकोणों से प्रस्तुत करती हैं और उन्हें आलोचनात्मक रूप से पढ़ा जा सकता है","रेल कैसे बनाई गई और रेल लाइनों की योजना और भुगतान किसने किया"],"explanationHi":"पाठ्यपुस्तकें अतीत की तटस्थ खिड़कियाँ नहीं हैं। यह पूछना कि किसका दृष्टिकोण मौजूद है और किसका अनुपस्थित, जैसे मज़दूरों या विस्थापित लोगों का, पाठ को खारिज किए बिना आलोचनात्मक पठन बनाता है।"},
  {"id":"cdp-pedagogy-subjects-841","question":"A Class VIII textbook's table on literacy uses census figures that are more than a decade old. What should the teacher do?","options":["Teach the figures as current, since the textbook is officially approved and the examination follows it","Skip the table altogether, since outdated data can only confuse students and waste class time","Tell students that data in textbooks are never reliable and should not be studied","Point out the year of the data, compare it with newer official figures, and discuss what has changed"],"answer":3,"explanation":"Data are always tied to a date. Noting the year and comparing with newer figures teaches students to read data critically and shows trends, rather than treating the textbook figure as timeless.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा VIII की पाठ्यपुस्तक की साक्षरता की सारणी ऐसे जनगणना आँकड़े प्रयोग करती है जो एक दशक से अधिक पुराने हैं। शिक्षक को क्या करना चाहिए?","optionsHi":["आँकड़ों को वर्तमान मानकर पढ़ाना, क्योंकि पाठ्यपुस्तक आधिकारिक रूप से स्वीकृत है और परीक्षा उसी का अनुसरण करती है","सारणी को पूरी तरह छोड़ देना, क्योंकि पुराने आँकड़े केवल विद्यार्थियों को भ्रमित और कक्षा का समय बर्बाद कर सकते हैं","विद्यार्थियों को बताना कि पाठ्यपुस्तकों के आँकड़े कभी विश्वसनीय नहीं होते और उनका अध्ययन नहीं करना चाहिए","आँकड़ों का वर्ष बताना, उनकी नए आधिकारिक आँकड़ों से तुलना करना, और चर्चा करना कि क्या बदला है"],"explanationHi":"आँकड़े हमेशा किसी तिथि से बँधे होते हैं। वर्ष को नोट करना और नए आँकड़ों से तुलना करना विद्यार्थियों को आँकड़ों को आलोचनात्मक रूप से पढ़ना सिखाता है और प्रवृत्तियाँ दिखाता है, बजाय पाठ्यपुस्तक के आँकड़े को कालातीत मानने के।"},
  {"id":"cdp-pedagogy-subjects-842","question":"To finish the syllabus on time, a Class VII teacher skips all the in-text boxes and 'Let's discuss' questions in the NCERT social science book and teaches only the main text. What is the main loss?","options":["Students miss prompts that link ideas to their own lives and make them think and discuss","Students lose information that appears often in board examination questions","Students miss pictures and boxes that are mainly decorative and add little","There is no real loss, since the boxes are optional and are not part of the syllabus"],"answer":0,"explanation":"In-text questions and boxes are designed to pause the reading for reflection, discussion and connection with students' experience. Skipping them turns an inquiry-oriented book into a reader of facts.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"पाठ्यक्रम समय पर पूरा करने के लिए कक्षा VII का एक शिक्षक NCERT सामाजिक विज्ञान पुस्तक के सभी पाठ-बीच के बॉक्स और ‘आओ चर्चा करें’ प्रश्न छोड़ देता है और केवल मुख्य पाठ पढ़ाता है। मुख्य हानि क्या है?","optionsHi":["विद्यार्थी उन संकेतों से वंचित रहते हैं जो विचारों को उनके अपने जीवन से जोड़ते हैं और उन्हें सोचने और चर्चा करने को प्रेरित करते हैं","विद्यार्थी वह जानकारी खो देते हैं जो बोर्ड परीक्षा के प्रश्नों में अक्सर आती है","विद्यार्थी उन चित्रों और बॉक्सों से वंचित रहते हैं जो मुख्यतः सजावटी हैं और कम जोड़ते हैं","कोई वास्तविक हानि नहीं है, क्योंकि बॉक्स वैकल्पिक हैं और पाठ्यक्रम का हिस्सा नहीं हैं"],"explanationHi":"पाठ-बीच के प्रश्न और बॉक्स पठन को चिंतन, चर्चा और विद्यार्थियों के अनुभव से जोड़ने के लिए रोकने को बनाए गए हैं। उन्हें छोड़ना जाँच-उन्मुख पुस्तक को तथ्यों के पाठक में बदल देता है।"},
  {"id":"cdp-pedagogy-subjects-843","question":"Class VI students in a tribal-area school in Chhattisgarh find the language of the social science textbook difficult. Which response is most suitable?","options":["Make students copy the chapter twice so that they become familiar with its language","Ask students to memorise the difficult words with their meanings before each chapter","Explain in the children's own language, add local stories and visuals, then return to the text","Skip the difficult chapters, since the children cannot follow them in any case"],"answer":2,"explanation":"Using the home language and local context as a bridge makes concepts accessible, after which the textbook becomes readable. Copying or rote vocabulary lists do not build understanding.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"छत्तीसगढ़ के एक जनजातीय क्षेत्र के विद्यालय के कक्षा VI के विद्यार्थियों को सामाजिक विज्ञान पाठ्यपुस्तक की भाषा कठिन लगती है। कौन-सी प्रतिक्रिया सबसे उपयुक्त है?","optionsHi":["विद्यार्थियों से अध्याय दो बार उतरवाना ताकि वे उसकी भाषा से परिचित हो जाएँ","विद्यार्थियों से हर अध्याय से पहले कठिन शब्द अर्थों सहित याद करवाना","बच्चों की अपनी भाषा में समझाना, स्थानीय कहानियाँ और चित्र जोड़ना, फिर पाठ पर लौटना","कठिन अध्याय छोड़ देना, क्योंकि बच्चे वैसे भी उन्हें समझ नहीं सकते"],"explanationHi":"घर की भाषा और स्थानीय संदर्भ को पुल के रूप में प्रयोग करना संप्रत्ययों को सुलभ बनाता है, जिसके बाद पाठ्यपुस्तक पठनीय हो जाती है। उतारना या रटी शब्द-सूचियाँ समझ नहीं बनातीं।"},
  {"id":"cdp-pedagogy-subjects-844","question":"Many Class IX students in a Patna school memorise answers from guidebooks. Which assessment practice would best discourage this and promote thinking?","options":["Asking questions copied directly from the end of the textbook chapter, so that all are prepared","Banning guidebooks in school and checking bags regularly for copies","Giving more marks for longer answers, so that students write in more detail","Asking questions that apply concepts to new situations, local cases or source extracts"],"answer":3,"explanation":"When questions need application to unfamiliar contexts, memorised answers stop working and students must think. Banning guidebooks treats the symptom; textbook-copied questions reward the very habit to be changed.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"पटना के एक विद्यालय में कक्षा IX के अनेक विद्यार्थी गाइडबुक से उत्तर रटते हैं। कौन-सी आकलन प्रथा इसे सबसे अच्छी तरह हतोत्साहित करेगी और चिंतन को बढ़ावा देगी?","optionsHi":["पाठ्यपुस्तक के अध्याय के अंत से सीधे उतारे गए प्रश्न पूछना, ताकि सब तैयार हों","विद्यालय में गाइडबुक पर प्रतिबंध लगाना और प्रतियों के लिए नियमित रूप से बैग जाँचना","लंबे उत्तरों के लिए अधिक अंक देना, ताकि विद्यार्थी अधिक विस्तार से लिखें","ऐसे प्रश्न पूछना जो संप्रत्ययों को नई स्थितियों, स्थानीय मामलों या स्रोत-अंशों पर लागू करें"],"explanationHi":"जब प्रश्नों में अपरिचित संदर्भों में अनुप्रयोग चाहिए, तो रटे उत्तर काम करना बंद कर देते हैं और विद्यार्थियों को सोचना पड़ता है। गाइडबुक पर प्रतिबंध लक्षण का इलाज करता है; पाठ्यपुस्तक से उतारे प्रश्न उसी आदत को पुरस्कृत करते हैं जिसे बदलना है।"},
  {"id":"cdp-pedagogy-subjects-845","question":"Which of the following statements about good social science textbooks are correct?\n1. They present information in a way that invites questioning.\n2. They include open-ended activities that can be linked to the local context.\n3. They mark the boundary beyond which the teacher should not go, since examinations are set from them.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"A good textbook invites inquiry and adaptation to local contexts. It is a starting point; treating it as a fence that limits teaching is the textbook-centred culture NCF 2005 criticises.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अच्छी सामाजिक विज्ञान पाठ्यपुस्तकों के बारे में निम्नलिखित में से कौन-से कथन सही हैं?\n1. वे जानकारी को ऐसे ढंग से प्रस्तुत करती हैं जो प्रश्न उठाने को आमंत्रित करे।\n2. उनमें ऐसी खुली गतिविधियाँ होती हैं जिन्हें स्थानीय संदर्भ से जोड़ा जा सकता है।\n3. वे उस सीमा को चिह्नित करती हैं जिसके आगे शिक्षक को नहीं जाना चाहिए, क्योंकि परीक्षाएँ उन्हीं से बनती हैं।","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"अच्छी पाठ्यपुस्तक जाँच और स्थानीय संदर्भों के अनुकूलन को आमंत्रित करती है। वह आरंभ-बिंदु है; उसे ऐसी बाड़ मानना जो शिक्षण को सीमित करे, वही पाठ्यपुस्तक-केंद्रित संस्कृति है जिसकी NCF 2005 आलोचना करता है।"},
  {"id":"cdp-pedagogy-subjects-846","question":"A teacher says, 'The textbook is the curriculum; what is not in it is not my job.' What is the misconception?","options":["She is right, since the curriculum and the textbook are simply two names for the same thing","The curriculum is a wider plan of aims, content, methods and assessment; the textbook is one tool for it","The syllabus is broader than the curriculum, so she should follow the syllabus document instead of either","The textbook is actually broader than the curriculum, so she should teach even more from it than she does"],"answer":1,"explanation":"Curriculum includes goals, experiences, methods and evaluation; the syllabus lists content; the textbook is a resource that serves both. Equating the textbook with the curriculum narrows teaching to one book.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"एक शिक्षिका कहती है, ‘पाठ्यपुस्तक ही पाठ्यचर्या है; जो उसमें नहीं है वह मेरा काम नहीं।’ भ्रांति क्या है?","optionsHi":["वह सही है, क्योंकि पाठ्यचर्या और पाठ्यपुस्तक एक ही चीज़ के दो नाम हैं","पाठ्यचर्या उद्देश्यों, विषयवस्तु, विधियों और आकलन की व्यापक योजना है; पाठ्यपुस्तक उसका एक साधन है","पाठ्यक्रम (syllabus) पाठ्यचर्या से व्यापक है, इसलिए उसे दोनों के बजाय पाठ्यक्रम दस्तावेज़ का अनुसरण करना चाहिए","पाठ्यपुस्तक वास्तव में पाठ्यचर्या से व्यापक है, इसलिए उसे उससे और भी अधिक पढ़ाना चाहिए"],"explanationHi":"पाठ्यचर्या में लक्ष्य, अनुभव, विधियाँ और मूल्यांकन शामिल हैं; पाठ्यक्रम विषयवस्तु सूचीबद्ध करता है; पाठ्यपुस्तक एक संसाधन है जो दोनों के काम आती है। पाठ्यपुस्तक को पाठ्यचर्या के बराबर मानना शिक्षण को एक पुस्तक तक सीमित कर देता है।"},
  {"id":"cdp-pedagogy-subjects-847","question":"A Class VII teacher in Madurai finds that the textbook says little about the everyday life of people under the southern kingdoms of the period. What is the most suitable response?","options":["Teach only regional history, and drop the textbook chapters on other regions of the subcontinent","Ignore the gap, since the examination follows the textbook and extra material adds to the load","Add regional sources such as temple inscriptions, and link them to the textbook's larger story","Tell students that the southern kingdoms were less important, which is why they get less space"],"answer":2,"explanation":"Supplementing the textbook with regional material fills its gaps and makes history relevant, while linking back keeps the larger picture. Replacing the textbook with regional history or ignoring the gap are both one-sided responses.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS","questionHi":"मदुरै की कक्षा VII की एक शिक्षिका पाती है कि पाठ्यपुस्तक उस काल के दक्षिणी राज्यों के अधीन लोगों के दैनिक जीवन के बारे में बहुत कम बताती है। सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["केवल क्षेत्रीय इतिहास पढ़ाना, और उपमहाद्वीप के अन्य क्षेत्रों के पाठ्यपुस्तक अध्याय छोड़ देना","अंतराल को अनदेखा करना, क्योंकि परीक्षा पाठ्यपुस्तक का अनुसरण करती है और अतिरिक्त सामग्री बोझ बढ़ाती है","मंदिर अभिलेखों जैसे क्षेत्रीय स्रोत जोड़ना, और उन्हें पाठ्यपुस्तक की बड़ी कहानी से जोड़ना","विद्यार्थियों को बताना कि दक्षिणी राज्य कम महत्त्वपूर्ण थे, इसीलिए उन्हें कम जगह मिलती है"],"explanationHi":"पाठ्यपुस्तक को क्षेत्रीय सामग्री से पूरक करना उसके अंतराल भरता है और इतिहास को प्रासंगिक बनाता है, जबकि वापस जोड़ना बड़ी तस्वीर बनाए रखता है। पाठ्यपुस्तक की जगह क्षेत्रीय इतिहास रखना या अंतराल को अनदेखा करना, दोनों एकतरफा प्रतिक्रियाएँ हैं।"},
  {"id":"cdp-pedagogy-subjects-848","question":"Assertion (A): Including Dalit autobiographies as source extracts enriches the teaching of caste in Class VIII.\nReason (R): First-person accounts let students understand discrimination from the perspective of those who experienced it.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Autobiographies bring the experience of discrimination into the classroom in the voice of those who lived it, which a general description cannot. That is why they enrich the lesson; R explains A.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): स्रोत-अंशों के रूप में दलित आत्मकथाओं को शामिल करना कक्षा VIII में जाति के शिक्षण को समृद्ध करता है।\nकारण (R): प्रथम-पुरुष वृत्तांत विद्यार्थियों को भेदभाव को उन लोगों के दृष्टिकोण से समझने देते हैं जिन्होंने उसे अनुभव किया।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"आत्मकथाएँ भेदभाव के अनुभव को उन लोगों की आवाज़ में कक्षा में लाती हैं जिन्होंने उसे जिया, जो सामान्य वर्णन नहीं कर सकता। इसीलिए वे पाठ को समृद्ध करती हैं; R, A की व्याख्या करता है।"},
  {"id":"cdp-pedagogy-subjects-849","question":"Which of these exercises best represents the voices of marginalised people in a Class VIII lesson on urban development?","options":["Reading a newspaper editorial that criticises the project on behalf of the city's poor","A role-play in which students imagine how a slum family feels about the project","Studying government data on how many families the project had to resettle","Interviewing a waste-picker or street vendor on how a city project affected work"],"answer":3,"explanation":"Only the interview lets marginalised people speak for themselves. The role-play and the editorial are tempting, but they speak about or for the poor through others' imagination or words, and resettlement data reduces people to numbers.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"शहरी विकास पर कक्षा VIII के पाठ में इनमें से कौन-सा अभ्यास हाशिये के लोगों की आवाज़ों का सबसे अच्छा प्रतिनिधित्व करता है?","optionsHi":["शहर के गरीबों की ओर से परियोजना की आलोचना करने वाला अख़बार का संपादकीय पढ़ना","एक भूमिका-अभिनय जिसमें विद्यार्थी कल्पना करते हैं कि झुग्गी का परिवार परियोजना के बारे में कैसा महसूस करता है","सरकारी आँकड़ों का अध्ययन कि परियोजना को कितने परिवारों को पुनर्वासित करना पड़ा","कूड़ा बीनने वाले या रेहड़ी वाले का साक्षात्कार लेना कि शहर की परियोजना ने उनके काम को कैसे प्रभावित किया"],"explanationHi":"केवल साक्षात्कार हाशिये के लोगों को स्वयं बोलने देता है। भूमिका-अभिनय और संपादकीय आकर्षक हैं, पर वे गरीबों के बारे में या उनकी ओर से दूसरों की कल्पना या शब्दों के माध्यम से बोलते हैं, और पुनर्वास के आँकड़े लोगों को संख्याओं में घटा देते हैं।"},
  {"id":"cdp-pedagogy-subjects-850","question":"A Class 8 teacher hands out a model leave letter, has students underline its fixed phrases and sentence patterns, and then asks them to write a similar letter changing only the names, dates and reasons. Marks are given for how closely the letter follows the model without errors. This reflects the:","options":["Process approach, which values drafting, feedback and revision","Product approach, centred on accurately imitating a model text","Genre approach, which explores the social purpose of a text type","Whole language approach, which uses writing for real readers"],"answer":1,"explanation":"Analysing and imitating a model and judging the finished text for accuracy is the product approach. The genre approach also uses models, but focuses on purpose, audience and context and moves through joint construction.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 8 की एक शिक्षिका अवकाश-पत्र का आदर्श नमूना बाँटती है, विद्यार्थियों से उसके निश्चित वाक्यांश और वाक्य-प्रतिरूपों को रेखांकित करवाती है, और फिर उनसे केवल नाम, तिथियाँ और कारण बदलकर वैसा ही पत्र लिखने को कहती है। अंक इस बात पर दिए जाते हैं कि पत्र त्रुटिरहित होकर आदर्श का कितना निकट अनुसरण करता है। यह किसे दर्शाता है?","optionsHi":["प्रक्रिया उपागम, जो प्रारूप बनाने, प्रतिपुष्टि और संशोधन को महत्त्व देता है","उत्पाद उपागम, जो आदर्श पाठ की सटीक नकल पर केंद्रित है","शैली (genre) उपागम, जो पाठ-प्रकार के सामाजिक उद्देश्य की खोज करता है","समग्र भाषा उपागम, जो वास्तविक पाठकों के लिए लेखन का प्रयोग करता है"],"explanationHi":"आदर्श का विश्लेषण और नकल करना तथा तैयार पाठ को शुद्धता के लिए आँकना उत्पाद उपागम है। शैली उपागम भी आदर्शों का प्रयोग करता है, पर उद्देश्य, श्रोता और संदर्भ पर केंद्रित होता है और संयुक्त रचना से होकर गुज़रता है।"},
  {"id":"cdp-pedagogy-subjects-851","question":"A teacher shows Class 9 students several real complaint letters, discusses who writes them, to whom and why, and how they usually move from background to problem to request. She then writes one together with the class before students write their own. This approach is:","options":["The genre-based approach, linking text structure to social purpose","The product approach, since a model text is used throughout","The audio-lingual approach, since a fixed pattern is practised","The free-writing approach, since students then write their own letters"],"answer":0,"explanation":"The genre approach studies how a text type achieves its social purpose, then moves through modelling, joint construction and independent writing (the teaching–learning cycle).","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"एक शिक्षिका कक्षा 9 के विद्यार्थियों को कई असली शिकायत-पत्र दिखाती है, चर्चा करती है कि उन्हें कौन लिखता है, किसे और क्यों, और वे आमतौर पर पृष्ठभूमि से समस्या और फिर अनुरोध की ओर कैसे बढ़ते हैं। फिर विद्यार्थियों के अपना लिखने से पहले वह कक्षा के साथ मिलकर एक लिखती है। यह उपागम है:","optionsHi":["शैली-आधारित उपागम, जो पाठ की संरचना को सामाजिक उद्देश्य से जोड़ता है","उत्पाद उपागम, क्योंकि पूरे समय एक आदर्श पाठ का प्रयोग होता है","श्रव्य-भाषिक उपागम, क्योंकि एक निश्चित प्रतिरूप का अभ्यास होता है","मुक्त-लेखन उपागम, क्योंकि विद्यार्थी फिर अपने पत्र लिखते हैं"],"explanationHi":"शैली उपागम अध्ययन करता है कि कोई पाठ-प्रकार अपना सामाजिक उद्देश्य कैसे पूरा करता है, फिर आदर्श प्रस्तुत करने, संयुक्त रचना और स्वतंत्र लेखन से होकर गुज़रता है (शिक्षण–अधिगम चक्र)।"},
  {"id":"cdp-pedagogy-subjects-852","question":"Which activity is an example of guided (rather than controlled or free) writing?","options":["Copying a paragraph from the board neatly, without making any change","Filling in blanks in a paragraph with words chosen from a given list","Writing about one’s village from a given outline and word bank","Writing about any topic of the learner’s own choice, with no help"],"answer":2,"explanation":"Guided writing gives support such as an outline, prompts or useful words but leaves learners to compose their own sentences. Copying and gap-filling are controlled; an open topic with no support is free writing.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कौन-सी गतिविधि निर्देशित (न कि नियंत्रित या मुक्त) लेखन का उदाहरण है?","optionsHi":["बोर्ड से बिना कोई बदलाव किए अनुच्छेद साफ-साफ उतारना","दी गई सूची से चुने शब्दों से अनुच्छेद में रिक्त स्थान भरना","दी गई रूपरेखा और शब्द-बैंक से अपने गाँव के बारे में लिखना","बिना किसी मदद के शिक्षार्थी की अपनी पसंद के किसी भी विषय पर लिखना"],"explanationHi":"निर्देशित लेखन रूपरेखा, संकेत या उपयोगी शब्दों जैसा सहारा देता है पर शिक्षार्थियों को अपने वाक्य रचने देता है। उतारना और रिक्त स्थान भरना नियंत्रित हैं; बिना सहायता का खुला विषय मुक्त लेखन है।"},
  {"id":"cdp-pedagogy-subjects-853","question":"A Class 5 child’s first draft about the day her goat ran away has an interesting story but many spelling mistakes. In a writing conference, the teacher’s best first response is to:","options":["Circle every spelling mistake in red so that she notices each one of them","Respond to the ideas first, e.g. ‘Tell me more about where you found her’","Give a mark out of ten so that she knows exactly how good the draft is","Ask her to copy the draft out again neatly before discussing anything"],"answer":1,"explanation":"In the process approach, early conferences focus on content and organisation; surface errors are handled later at the editing stage. Starting with red marks tells the child that only correctness matters.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 5 की एक बच्ची के उस दिन के बारे में पहले प्रारूप में, जब उसकी बकरी भाग गई थी, रोचक कहानी है पर वर्तनी की अनेक गलतियाँ हैं। लेखन-परामर्श में शिक्षक की सबसे अच्छी पहली प्रतिक्रिया है:","optionsHi":["हर वर्तनी की गलती को लाल घेरे में रखना ताकि वह उनमें से हर एक पर ध्यान दे","पहले विचारों पर प्रतिक्रिया देना, जैसे ‘मुझे और बताओ कि तुम्हें वह कहाँ मिली’","दस में से अंक देना ताकि वह ठीक-ठीक जाने कि प्रारूप कितना अच्छा है","कुछ भी चर्चा करने से पहले उसे प्रारूप साफ-साफ फिर उतारने को कहना"],"explanationHi":"प्रक्रिया उपागम में आरंभिक परामर्श विषयवस्तु और संगठन पर केंद्रित होते हैं; सतही त्रुटियाँ बाद में संपादन चरण में सँभाली जाती हैं। लाल निशानों से शुरू करना बच्ची को बताता है कि केवल शुद्धता मायने रखती है।"},
  {"id":"cdp-pedagogy-subjects-854","question":"A Class 8 teacher wants peer review of story drafts to be genuinely useful. The most effective step is to:","options":["Ask students to exchange notebooks and give each draft a mark","Let peers correct only spelling, since they know little about content","Give guiding questions and model how to give specific, kind feedback","Avoid peer review, since classmates know less than the teacher"],"answer":2,"explanation":"Without guidance peer feedback tends to be vague or limited to spelling. A short checklist and teacher modelling show students what to look for and how to comment helpfully.","difficulty":"moderate","source":"CTET Paper II · State TETs","questionHi":"कक्षा 8 का एक शिक्षक चाहता है कि कहानी-प्रारूपों की सहपाठी-समीक्षा वास्तव में उपयोगी हो। सबसे प्रभावी कदम है:","optionsHi":["विद्यार्थियों से कॉपियाँ आपस में बदलने और हर प्रारूप को अंक देने को कहना","सहपाठियों को केवल वर्तनी सुधारने देना, क्योंकि वे विषयवस्तु के बारे में कम जानते हैं","मार्गदर्शक प्रश्न देना और विशिष्ट, दयालु प्रतिपुष्टि देने का आदर्श प्रस्तुत करना","सहपाठी-समीक्षा से बचना, क्योंकि सहपाठी शिक्षक से कम जानते हैं"],"explanationHi":"मार्गदर्शन के बिना सहपाठी-प्रतिपुष्टि अस्पष्ट या केवल वर्तनी तक सीमित रहती है। एक छोटी जाँच-सूची और शिक्षक का आदर्श प्रस्तुत करना विद्यार्थियों को दिखाता है कि क्या देखना है और उपयोगी टिप्पणी कैसे करनी है।"},
  {"id":"cdp-pedagogy-subjects-855","question":"Before writing on ‘The first rain’, Class 7 students write non-stop for five minutes, putting down whatever comes to mind without worrying about spelling or grammar. This technique mainly serves to:","options":["Produce a final draft quickly for display on the class board","Practise handwriting speed for the board examinations","Test how many spelling errors students make under pressure","Generate ideas and overcome the block of a blank page"],"answer":3,"explanation":"Freewriting is a pre-writing technique that releases ideas and builds fluency by suspending judgement; the material is later shaped through drafting and revision.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"‘पहली बारिश’ पर लिखने से पहले कक्षा 7 के विद्यार्थी पाँच मिनट तक बिना रुके लिखते हैं, जो भी मन में आए वह लिखते हैं, वर्तनी या व्याकरण की चिंता किए बिना। यह तकनीक मुख्यतः किसके काम आती है?","optionsHi":["कक्षा के बोर्ड पर प्रदर्शन के लिए शीघ्र अंतिम प्रारूप तैयार करना","बोर्ड परीक्षाओं के लिए लिखावट की गति का अभ्यास करना","यह परखना कि दबाव में विद्यार्थी कितनी वर्तनी की गलतियाँ करते हैं","विचार उत्पन्न करना और खाली पन्ने की बाधा को पार करना"],"explanationHi":"मुक्त लेखन पूर्व-लेखन तकनीक है जो निर्णय को स्थगित करके विचारों को मुक्त करती है और प्रवाह बनाती है; सामग्री को बाद में प्रारूप बनाने और संशोधन से आकार दिया जाता है।"},
  {"id":"cdp-pedagogy-subjects-856","question":"A teacher reads a short text twice at normal speed. Students jot down key words, then work in groups to rebuild the text so that it is as close as possible in meaning and grammar to the original, and compare versions. This technique is:","options":["Dictogloss","Traditional dictation","The cloze procedure","Précis writing"],"answer":0,"explanation":"In dictogloss learners reconstruct a text from notes through discussion, which integrates listening, speaking and writing and draws attention to grammar in context. Traditional dictation is word-for-word transcription.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"एक शिक्षक एक छोटा पाठ सामान्य गति से दो बार पढ़ता है। विद्यार्थी मुख्य शब्द लिख लेते हैं, फिर समूहों में पाठ को इस तरह फिर बनाते हैं कि वह अर्थ और व्याकरण में मूल के यथासंभव निकट हो, और संस्करणों की तुलना करते हैं। यह तकनीक है:","optionsHi":["डिक्टोग्लॉस (Dictogloss)","पारंपरिक श्रुतलेख","क्लोज़ प्रक्रिया (Cloze procedure)","सार-लेखन (précis writing)"],"explanationHi":"डिक्टोग्लॉस में शिक्षार्थी नोट्स से चर्चा करके पाठ का पुनर्निर्माण करते हैं, जो सुनने, बोलने और लिखने को एकीकृत करता है और संदर्भ में व्याकरण की ओर ध्यान खींचता है। पारंपरिक श्रुतलेख शब्द-दर-शब्द प्रतिलेखन है।"},
  {"id":"cdp-pedagogy-subjects-857","question":"Class 8 students are given a bar graph showing monthly rainfall in Cherrapunji and asked to write a paragraph describing what it shows. This activity develops:","options":["Free composition on a topic of the learner's own choice","Précis writing by shortening a long passage of text","Information transfer from non-verbal to verbal form","Paraphrasing a written text in simpler words of one's own"],"answer":2,"explanation":"Information transfer involves converting information between forms, here from a graph to prose, which requires interpreting data and choosing language to compare and describe.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 8 के विद्यार्थियों को चेरापूंजी में मासिक वर्षा दर्शाने वाला दंड आलेख दिया जाता है और उससे यह बताते हुए अनुच्छेद लिखने को कहा जाता है कि वह क्या दर्शाता है। यह गतिविधि क्या विकसित करती है?","optionsHi":["शिक्षार्थी की अपनी पसंद के विषय पर मुक्त रचना","लंबे गद्यांश को छोटा करके सार-लेखन","अशाब्दिक से शाब्दिक रूप में सूचना-स्थानांतरण","लिखित पाठ को अपने सरल शब्दों में भावार्थ करना"],"explanationHi":"सूचना-स्थानांतरण में सूचना को एक रूप से दूसरे में बदलना शामिल है, यहाँ आलेख से गद्य में, जिसके लिए आँकड़ों की व्याख्या और तुलना व वर्णन के लिए भाषा चुनना आवश्यक है।"},
  {"id":"cdp-pedagogy-subjects-858","question":"A Class 6 teacher asks students to write about the school sports day three times: as a diary entry, as a notice for the board and as a report for the school magazine. The main learning aim is that students realise:","options":["A good piece of writing can be reused for any reader with no change","Notices and reports are less important than diary entries","Writing the same thing three times improves handwriting","Layout, content and language change with purpose and audience"],"answer":3,"explanation":"Comparing text types on one topic shows how purpose and audience shape format, level of formality and what is included.","difficulty":"moderate","source":"CTET Paper II · State TETs","questionHi":"कक्षा 6 की एक शिक्षिका विद्यार्थियों से विद्यालय के खेल दिवस के बारे में तीन बार लिखने को कहती है: डायरी प्रविष्टि के रूप में, बोर्ड के लिए सूचना के रूप में और विद्यालय पत्रिका के लिए प्रतिवेदन के रूप में। मुख्य अधिगम उद्देश्य यह है कि विद्यार्थी समझें:","optionsHi":["अच्छा लेखन किसी भी पाठक के लिए बिना किसी बदलाव के दोबारा प्रयोग किया जा सकता है","सूचनाएँ और प्रतिवेदन डायरी प्रविष्टियों से कम महत्त्वपूर्ण हैं","एक ही बात को तीन बार लिखने से लिखावट सुधरती है","रूपरेखा, विषयवस्तु और भाषा उद्देश्य और श्रोता के साथ बदलती हैं"],"explanationHi":"एक विषय पर पाठ-प्रकारों की तुलना दिखाती है कि उद्देश्य और श्रोता प्रारूप, औपचारिकता के स्तर और क्या शामिल हो, इसे कैसे आकार देते हैं।"},
  {"id":"cdp-pedagogy-subjects-859","question":"Several Class 4 children cannot begin a story on their own. Their teacher gives them a sheet with ‘One day…’, ‘Then…’, ‘After that…’ and ‘In the end…’ as starters. This support is best described as:","options":["A writing frame that scaffolds structure and is withdrawn later","Controlled dictation in which the teacher supplies all the words","Copying practice that develops neat handwriting","A test that checks whether children already know linking words"],"answer":0,"explanation":"Writing frames give a skeleton of connectives and sentence starters, letting learners compose while seeing how a text is organised; the support is reduced as they gain confidence.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 4 के कई बच्चे अपने आप कहानी शुरू नहीं कर पाते। उनकी शिक्षिका उन्हें ‘One day…’, ‘Then…’, ‘After that…’ और ‘In the end…’ आरंभकों वाली शीट देती है। इस सहायता का सबसे अच्छा वर्णन है:","optionsHi":["लेखन-ढाँचा जो संरचना को सहारा देता है और बाद में हटा लिया जाता है","नियंत्रित श्रुतलेख जिसमें शिक्षिका सारे शब्द देती है","उतारने का अभ्यास जो साफ लिखावट विकसित करता है","एक परीक्षा जो जाँचती है कि बच्चे जोड़ने वाले शब्द पहले से जानते हैं या नहीं"],"explanationHi":"लेखन-ढाँचे संयोजकों और वाक्य-आरंभकों का कंकाल देते हैं, शिक्षार्थियों को रचना करने देते हैं और साथ ही दिखाते हैं कि पाठ कैसे संगठित है; आत्मविश्वास बढ़ने पर सहायता घटा दी जाती है।"},
  {"id":"cdp-pedagogy-subjects-860","question":"A Class 7 student writes in her notebook every week about whatever she likes, and the teacher replies in writing to what she says, without marking errors, though her replies naturally use correct forms. The main value of such a dialogue journal is that it:","options":["Lets the teacher grade each student's written grammar more often and more closely","Gives a real reader and purpose without anxiety, while correct forms are modelled","Replaces the need for any other kind of writing practice in the classroom","Gives the teacher a detailed record of each student’s private life at home"],"answer":1,"explanation":"Dialogue journals turn writing into genuine communication; students write more freely, and the teacher’s replies give implicit models of correct language without discouraging the writer.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 7 की एक विद्यार्थी हर सप्ताह अपनी कॉपी में जो चाहे लिखती है, और शिक्षिका उसके लिखे पर लिखित उत्तर देती है, त्रुटियाँ चिह्नित किए बिना, यद्यपि उसके उत्तरों में स्वाभाविक रूप से सही रूप आते हैं। ऐसी संवाद-पत्रिका का मुख्य मूल्य यह है कि वह:","optionsHi":["शिक्षिका को प्रत्येक विद्यार्थी के लिखित व्याकरण को अधिक बार और निकट से अंकित करने देती है","चिंता के बिना वास्तविक पाठक और उद्देश्य देती है, जबकि सही रूपों का आदर्श प्रस्तुत होता है","कक्षा में अन्य किसी प्रकार के लेखन अभ्यास की आवश्यकता समाप्त कर देती है","शिक्षिका को प्रत्येक विद्यार्थी के घर के निजी जीवन का विस्तृत अभिलेख देती है"],"explanationHi":"संवाद-पत्रिकाएँ लेखन को वास्तविक संप्रेषण बनाती हैं; विद्यार्थी अधिक स्वतंत्रता से लिखते हैं, और शिक्षिका के उत्तर लेखक को हतोत्साहित किए बिना सही भाषा के अप्रत्यक्ष आदर्श देते हैं।"},
  {"id":"cdp-pedagogy-subjects-861","question":"A Class 7 paragraph titled ‘Why trees matter’ opens with a long description of a school picnic, and only the last sentence mentions trees. The teacher’s feedback should focus mainly on:","options":["Spelling, since several words in the paragraph are misspelt","Punctuation, since the sentences are long and run together","Unity: a clear topic sentence and relevant supporting sentences","Handwriting, since neat presentation strongly affects the reader"],"answer":2,"explanation":"A paragraph needs a controlling idea, usually in a topic sentence, with every other sentence supporting it. Surface matters can be handled after this larger problem.","difficulty":"moderate","source":"CTET Paper II · State TETs","questionHi":"‘पेड़ क्यों मायने रखते हैं’ शीर्षक वाला कक्षा 7 का एक अनुच्छेद विद्यालय की पिकनिक के लंबे वर्णन से शुरू होता है, और केवल अंतिम वाक्य में पेड़ों का उल्लेख है। शिक्षिका की प्रतिपुष्टि मुख्यतः किस पर केंद्रित होनी चाहिए?","optionsHi":["वर्तनी, क्योंकि अनुच्छेद में कई शब्द गलत लिखे हैं","विराम-चिह्न, क्योंकि वाक्य लंबे हैं और आपस में मिल गए हैं","एकता: स्पष्ट विषय-वाक्य और प्रासंगिक सहायक वाक्य","लिखावट, क्योंकि साफ प्रस्तुति पाठक को बहुत प्रभावित करती है"],"explanationHi":"अनुच्छेद को नियंत्रक विचार चाहिए, प्रायः विषय-वाक्य में, और हर अन्य वाक्य उसका समर्थन करे। इस बड़ी समस्या के बाद सतही बातें सँभाली जा सकती हैं।"},
  {"id":"cdp-pedagogy-subjects-862","question":"Assertion (A): Using linking words such as ‘however’ and ‘therefore’ is enough by itself to make a piece of writing coherent. Reason (R): Coherence depends on the logical organisation and connection of ideas, not only on surface linking words.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"Cohesive devices can be scattered through a text whose ideas still do not hang together; coherence comes from logical organisation of meaning, so A is false and R is true.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"अभिकथन (A): ‘however’ और ‘therefore’ जैसे जोड़ने वाले शब्दों का प्रयोग अपने आप में लेखन को सुसंगत बनाने के लिए पर्याप्त है। कारण (R): सुसंगति विचारों के तार्किक संगठन और संबंध पर निर्भर करती है, केवल सतही जोड़ने वाले शब्दों पर नहीं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"संसक्ति साधन किसी ऐसे पाठ में बिखरे हो सकते हैं जिसके विचार फिर भी आपस में नहीं जुड़ते; सुसंगति अर्थ के तार्किक संगठन से आती है, इसलिए A असत्य और R सत्य है।"},
  {"id":"cdp-pedagogy-subjects-863","question":"A Class 3 teacher gives a set of four pictures showing a boy, a kite, a tree and a ladder, and wants children to write a story. The most effective way to begin is to:","options":["Ask children to start writing at once, so that their ideas stay fully original","Talk about the pictures, build useful words on the board, then let them write","Give children a model story to copy beneath the pictures for practice","Teach the past tense rule thoroughly before even showing the pictures"],"answer":1,"explanation":"Oral discussion before writing builds ideas and vocabulary, so children have something to say and words to say it with. Copying a model removes composition altogether.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कक्षा 3 की एक शिक्षिका एक लड़के, एक पतंग, एक पेड़ और एक सीढ़ी दिखाने वाले चार चित्रों का सेट देती है और चाहती है कि बच्चे कहानी लिखें। शुरू करने का सबसे प्रभावी तरीका है:","optionsHi":["बच्चों से तुरंत लिखना शुरू करने को कहना, ताकि उनके विचार पूरी तरह मौलिक रहें","चित्रों पर बातचीत करना, बोर्ड पर उपयोगी शब्द बनाना, फिर उन्हें लिखने देना","बच्चों को अभ्यास के लिए चित्रों के नीचे उतारने हेतु एक आदर्श कहानी देना","चित्र दिखाने से पहले भी भूतकाल का नियम अच्छी तरह सिखाना"],"explanationHi":"लिखने से पहले मौखिक चर्चा विचार और शब्दावली बनाती है, ताकि बच्चों के पास कहने को कुछ हो और कहने के लिए शब्द हों। आदर्श को उतारना रचना को पूरी तरह हटा देता है।"},
  {"id":"cdp-pedagogy-subjects-864","question":"A Class 8 teacher shares the rubric for a descriptive essay (ideas, organisation, vocabulary, accuracy) with students before they begin writing. The main advantage is that it:","options":["Turns the essay into a test of memory rather than a test of writing","Means the teacher no longer needs to read the essays carefully","Ensures that every student will get the same mark for the essay","Makes criteria clear, so students can plan and check their own work"],"answer":3,"explanation":"Transparent criteria tell learners what quality looks like, guide their planning and revision, and support self- and peer assessment, a core idea of assessment for learning.","difficulty":"moderate","source":"CTET Paper II · State TETs","questionHi":"कक्षा 8 का एक शिक्षक वर्णनात्मक निबंध के लिए रूब्रिक (विचार, संगठन, शब्दावली, शुद्धता) को विद्यार्थियों के लिखना शुरू करने से पहले उनके साथ साझा करता है। मुख्य लाभ यह है कि वह:","optionsHi":["निबंध को लेखन की परीक्षा के बजाय स्मृति की परीक्षा बना देता है","इसका अर्थ है कि शिक्षक को अब निबंध ध्यान से पढ़ने की आवश्यकता नहीं","सुनिश्चित करता है कि प्रत्येक विद्यार्थी को निबंध के लिए समान अंक मिलेंगे","मानदंड स्पष्ट करता है, ताकि विद्यार्थी अपना कार्य योजनाबद्ध कर सकें और जाँच सकें"],"explanationHi":"पारदर्शी मानदंड शिक्षार्थियों को बताते हैं कि गुणवत्ता कैसी दिखती है, उनकी योजना और संशोधन का मार्गदर्शन करते हैं, और स्व- तथा सहपाठी-आकलन में सहायक होते हैं, जो अधिगम के लिए आकलन का मूल विचार है।"},
  {"id":"cdp-pedagogy-subjects-865","question":"Instead of writing corrections, a teacher underlines errors in Class 9 compositions and writes codes such as ‘Sp’ (spelling), ‘T’ (tense) and ‘WO’ (word order) in the margin, and students correct their own work. The main aim is to:","options":["Promote self-correction and make learners notice their errors","Avoid giving any feedback that might upset or discourage students","Show students how many errors they made so they try harder","Reduce the time the teacher spends reading the compositions"],"answer":0,"explanation":"Indirect, coded feedback makes learners think about the rule involved and fix the error themselves, which builds awareness and responsibility more than receiving ready corrections.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"सुधार लिखने के बजाय एक शिक्षिका कक्षा 9 की रचनाओं में त्रुटियों को रेखांकित करती है और हाशिये में ‘Sp’ (वर्तनी), ‘T’ (काल) और ‘WO’ (शब्द-क्रम) जैसे कोड लिखती है, और विद्यार्थी अपना कार्य स्वयं सुधारते हैं। मुख्य उद्देश्य है:","optionsHi":["स्व-सुधार को बढ़ावा देना और शिक्षार्थियों को अपनी त्रुटियों पर ध्यान देने के लिए प्रेरित करना","कोई भी ऐसी प्रतिपुष्टि देने से बचना जो विद्यार्थियों को दुखी या हतोत्साहित कर सकती है","विद्यार्थियों को दिखाना कि उन्होंने कितनी त्रुटियाँ कीं ताकि वे अधिक प्रयास करें","शिक्षिका द्वारा रचनाएँ पढ़ने में लगने वाला समय घटाना"],"explanationHi":"अप्रत्यक्ष, कोडित प्रतिपुष्टि शिक्षार्थियों को संबंधित नियम के बारे में सोचने और त्रुटि स्वयं सुधारने को प्रेरित करती है, जो तैयार सुधार पाने से अधिक जागरूकता और ज़िम्मेदारी बनाती है।"},
  {"id":"cdp-pedagogy-subjects-866","question":"For three weeks, a teacher’s written feedback on Class 6 stories focuses only on errors in past-tense verbs, the target of current lessons, and ignores most other errors. Which statement best supports her choice?","options":["Feedback on a few patterns is easier to act on than marking everything","Other errors do not matter, since only verbs really affect the meaning","Children should never be told about any error other than the tense taught","Ignoring errors always produces faster learning than correcting them"],"answer":0,"explanation":"Marking every error overwhelms learners and hides patterns. Selective, focused feedback on a target area helps them notice and fix it, while other areas are taken up in turn.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"तीन सप्ताह तक एक शिक्षिका की कक्षा 6 की कहानियों पर लिखित प्रतिपुष्टि केवल भूतकाल की क्रियाओं की त्रुटियों पर केंद्रित रहती है, जो वर्तमान पाठों का लक्ष्य है, और अधिकांश अन्य त्रुटियों को अनदेखा करती है। कौन-सा कथन उसके चुनाव का सबसे अच्छा समर्थन करता है?","optionsHi":["कुछ प्रतिरूपों पर प्रतिपुष्टि सब कुछ जाँचने से अधिक आसानी से अपनाई जा सकती है","अन्य त्रुटियाँ मायने नहीं रखतीं, क्योंकि केवल क्रियाएँ ही अर्थ को वास्तव में प्रभावित करती हैं","बच्चों को पढ़ाए गए काल के अलावा किसी भी त्रुटि के बारे में कभी नहीं बताना चाहिए","त्रुटियों को अनदेखा करने से हमेशा उन्हें सुधारने की तुलना में तेज़ अधिगम होता है"],"explanationHi":"हर त्रुटि को चिह्नित करना शिक्षार्थियों पर बोझ डालता है और प्रतिरूप छिपा देता है। लक्ष्य क्षेत्र पर चयनात्मक, केंद्रित प्रतिपुष्टि उन्हें उसे पहचानने और सुधारने में मदद करती है, जबकि अन्य क्षेत्र बारी-बारी से लिए जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-867","question":"In a Class 2 classroom, most of the writing period is spent copying sentences from the board into notebooks. The main weakness of this practice is that it:","options":["Develops composition too early, before children can form their letters properly","Makes the children’s handwriting worse, since copying is done in a hurry","Builds handwriting but gives no chance to write down their own ideas","Is too difficult for Class 2 children and should wait until they reach Class 5"],"answer":2,"explanation":"Writing is composing meaning, not only forming letters. Copying has a place for handwriting, but children also need early chances to write their own messages, lists and stories.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 2 की एक कक्षा में लेखन पीरियड का अधिकांश समय बोर्ड से वाक्य कॉपियों में उतारने में जाता है। इस अभ्यास की मुख्य कमज़ोरी यह है कि यह:","optionsHi":["रचना को बहुत जल्दी विकसित करता है, इससे पहले कि बच्चे अपने अक्षर ठीक से बना सकें","बच्चों की लिखावट को और बिगाड़ता है, क्योंकि उतारना जल्दबाज़ी में होता है","लिखावट तो बनाता है पर अपने विचार लिखने का अवसर नहीं देता","कक्षा 2 के बच्चों के लिए बहुत कठिन है और कक्षा 5 तक प्रतीक्षा करनी चाहिए"],"explanationHi":"लेखन केवल अक्षर बनाना नहीं, अर्थ की रचना है। उतारने का लिखावट के लिए स्थान है, पर बच्चों को अपने संदेश, सूचियाँ और कहानियाँ लिखने के आरंभिक अवसर भी चाहिए।"},
  {"id":"cdp-pedagogy-subjects-868","question":"Which writing task is the most authentic for Class 5 children?","options":["Writing out the memorised essay ‘My Cow’ from the guidebook for the unit test","Writing to the panchayat about the school's broken handpump, and sending it","Copying a model letter from the textbook neatly into the notebook","Filling in the blanks in an incomplete letter on a printed worksheet"],"answer":1,"explanation":"Authentic writing has a real purpose and a real reader, which gives children a reason to make their writing clear and correct. The other tasks are exercises with no actual audience.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"कक्षा 5 के बच्चों के लिए कौन-सा लेखन कार्य सबसे प्रामाणिक है?","optionsHi":["इकाई परीक्षा के लिए गाइडबुक से रटे निबंध ‘मेरी गाय’ को लिख देना","विद्यालय के टूटे हैंडपंप के बारे में पंचायत को पत्र लिखना और उसे भेजना","पाठ्यपुस्तक से आदर्श पत्र को कॉपी में साफ-साफ उतारना","छपी कार्यपत्रिका पर अधूरे पत्र में रिक्त स्थान भरना"],"explanationHi":"प्रामाणिक लेखन का वास्तविक उद्देश्य और वास्तविक पाठक होता है, जो बच्चों को अपना लेखन स्पष्ट और शुद्ध बनाने का कारण देता है। अन्य कार्य बिना वास्तविक श्रोता के अभ्यास हैं।"},
  {"id":"cdp-pedagogy-subjects-869","question":"Which statement about the process approach to writing is NOT correct?","options":["Writing is recursive: writers move back and forth between planning, drafting and revising","Feedback is given while the text is still being developed, not only at the end","Learners usually produce more than one draft of the same piece","The main emphasis is on the grammatical correctness of the final product"],"answer":3,"explanation":"The process approach shifts attention from the finished product to how writers generate, draft and revise ideas; correctness matters but is handled at the editing stage.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"लेखन के प्रक्रिया उपागम के बारे में कौन-सा कथन सही नहीं है?","optionsHi":["लेखन आवर्ती है: लेखक योजना, प्रारूप और संशोधन के बीच आगे-पीछे जाते हैं","पाठ के विकसित होते समय प्रतिपुष्टि दी जाती है, केवल अंत में नहीं","शिक्षार्थी प्रायः एक ही रचना के एक से अधिक प्रारूप बनाते हैं","मुख्य बल अंतिम उत्पाद की व्याकरणिक शुद्धता पर है"],"explanationHi":"प्रक्रिया उपागम ध्यान तैयार उत्पाद से हटाकर इस पर लाता है कि लेखक विचार कैसे उत्पन्न करते, प्रारूपित करते और संशोधित करते हैं; शुद्धता मायने रखती है पर संपादन चरण में सँभाली जाती है।"},
  {"id":"cdp-pedagogy-subjects-870","question":"Four pre-school children are asked to write ‘kite’. P draws wavy lines; Q writes ‘KT’; R writes a random string ‘AOTMB’; S writes ‘kite’. Arrange them from the earliest to the most advanced stage of writing development.","options":["P, Q, R, S","P, R, Q, S","R, P, Q, S","P, R, S, Q"],"answer":1,"explanation":"Children move from scribbles to random strings of letters (no sound link), then to invented spelling that records some sounds (‘KT’), and then to conventional spelling.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"चार पूर्व-विद्यालयी बच्चों से ‘kite’ लिखने को कहा जाता है। P लहरदार रेखाएँ खींचता है; Q ‘KT’ लिखता है; R अक्षरों की यादृच्छिक शृंखला ‘AOTMB’ लिखता है; S ‘kite’ लिखता है। उन्हें लेखन विकास के सबसे आरंभिक से सबसे उन्नत चरण के क्रम में लगाइए।","optionsHi":["P, Q, R, S","P, R, Q, S","R, P, Q, S","P, R, S, Q"],"explanationHi":"बच्चे घसीट-रेखाओं से अक्षरों की यादृच्छिक शृंखलाओं (ध्वनि से कोई संबंध नहीं) की ओर बढ़ते हैं, फिर आविष्कृत वर्तनी की ओर जो कुछ ध्वनियाँ दर्ज करती है (‘KT’), और फिर परंपरागत वर्तनी की ओर।"},
  {"id":"cdp-pedagogy-subjects-871","question":"In a ‘running dictation’, a short text is pinned on the wall; one partner runs to it, reads and remembers a chunk, returns and dictates it, and the other partner writes it down. Which skills does this activity practise?","options":["Reading, speaking, listening and writing together","Only listening and writing, since one partner dictates","Only reading and writing, since the text is read and copied","Only writing, since the outcome is a written text"],"answer":0,"explanation":"The runner reads and speaks, the writer listens and writes, and partners often switch roles, so all four skills are integrated in one lively activity.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"‘रनिंग डिक्टेशन’ में एक छोटा पाठ दीवार पर लगाया जाता है; एक साथी उसकी ओर दौड़ता है, एक खंड पढ़कर याद रखता है, लौटकर उसे बोलता है, और दूसरा साथी उसे लिखता है। यह गतिविधि कौन-से कौशलों का अभ्यास कराती है?","optionsHi":["पठन, वाचन, श्रवण और लेखन साथ-साथ","केवल श्रवण और लेखन, क्योंकि एक साथी बोलकर लिखवाता है","केवल पठन और लेखन, क्योंकि पाठ पढ़ा और उतारा जाता है","केवल लेखन, क्योंकि परिणाम एक लिखित पाठ है"],"explanationHi":"दौड़ने वाला पढ़ता और बोलता है, लिखने वाला सुनता और लिखता है, और साथी अक्सर भूमिकाएँ बदलते हैं, इसलिए चारों कौशल एक जीवंत गतिविधि में एकीकृत होते हैं।"},
  {"id":"cdp-pedagogy-subjects-872","question":"Which prompt is most likely to encourage creative, original writing from Class 6 students?","options":["‘Write ten lines on the school bell, in your best handwriting.’","‘Copy and complete the given paragraph on the school bell.’","‘If the school bell could talk, what would it say about our day?’","‘Describe the school bell in five sentences, using the words given below.’"],"answer":2,"explanation":"An imaginative prompt invites a fresh point of view and divergent ideas, whereas the others lead to predictable, formulaic or controlled writing.","difficulty":"moderate","source":"CTET Paper II · State TETs","questionHi":"कक्षा 6 के विद्यार्थियों से रचनात्मक, मौलिक लेखन को प्रोत्साहित करने की सबसे अधिक संभावना किस निर्देश में है?","optionsHi":["‘विद्यालय की घंटी पर दस पंक्तियाँ अपनी सबसे अच्छी लिखावट में लिखो।’","‘विद्यालय की घंटी पर दिए गए अनुच्छेद को उतारो और पूरा करो।’","‘यदि विद्यालय की घंटी बोल सकती, तो वह हमारे दिन के बारे में क्या कहती?’","‘नीचे दिए शब्दों का प्रयोग करके विद्यालय की घंटी का पाँच वाक्यों में वर्णन करो।’"],"explanationHi":"कल्पनाशील निर्देश नया दृष्टिकोण और अपसारी विचार आमंत्रित करता है, जबकि अन्य पूर्वानुमेय, साँचेबद्ध या नियंत्रित लेखन की ओर ले जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-873","question":"A teacher marks only the final version of each composition with a grade and brief comments. Students look at the grade and put the work away. Which change would make her feedback most useful for learning?","options":["Displaying only the best compositions on the class board as models","Writing much longer, more detailed comments on the final version only","Replacing the comments with a percentage score for each piece","Giving feedback on drafts while students can still use it to revise"],"answer":3,"explanation":"Feedback improves writing when learners can act on it. Comments on drafts during the process are used; comments on a finished, graded piece are mostly ignored.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"एक शिक्षिका प्रत्येक रचना के केवल अंतिम संस्करण को ग्रेड और संक्षिप्त टिप्पणियों से जाँचती है। विद्यार्थी ग्रेड देखकर कार्य को रख देते हैं। कौन-सा परिवर्तन उसकी प्रतिपुष्टि को अधिगम के लिए सबसे उपयोगी बनाएगा?","optionsHi":["केवल सर्वश्रेष्ठ रचनाओं को आदर्श के रूप में कक्षा के बोर्ड पर प्रदर्शित करना","केवल अंतिम संस्करण पर बहुत लंबी, अधिक विस्तृत टिप्पणियाँ लिखना","टिप्पणियों की जगह प्रत्येक रचना के लिए प्रतिशत अंक देना","प्रारूपों पर प्रतिपुष्टि देना जब विद्यार्थी अब भी उसे संशोधन में प्रयोग कर सकते हों"],"explanationHi":"प्रतिपुष्टि लेखन तब सुधारती है जब शिक्षार्थी उस पर कार्य कर सकें। प्रक्रिया के दौरान प्रारूपों पर टिप्पणियाँ प्रयोग होती हैं; तैयार, ग्रेड की गई रचना पर टिप्पणियाँ अधिकतर अनदेखी रह जाती हैं।"},
  {"id":"cdp-pedagogy-subjects-874","question":"A Class 4 child in Manipur cannot yet write a story in English but writes vividly in Meitei. Her teacher lets her plan and draft in Meitei and then helps her write the story in English. Which statement best supports this practice?","options":["It is unhelpful, since thinking in Meitei will slow down her progress in English","It should be stopped once she reaches Class 5, whatever progress she has made by then","It is acceptable only for children with a learning disability, not for others","Planning skills transfer across languages, and using Meitei reduces the load"],"answer":3,"explanation":"Composing skills are shared across languages (Cummins’ common underlying proficiency), and planning in the stronger language frees attention for expressing ideas in English, a translanguaging practice.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"मणिपुर की कक्षा 4 की एक बच्ची अभी अंग्रेज़ी में कहानी नहीं लिख सकती पर मैतेई में सजीव लिखती है। उसकी शिक्षिका उसे मैतेई में योजना और प्रारूप बनाने देती है और फिर अंग्रेज़ी में कहानी लिखने में उसकी मदद करती है। कौन-सा कथन इस अभ्यास का सबसे अच्छा समर्थन करता है?","optionsHi":["यह अनुपयोगी है, क्योंकि मैतेई में सोचना अंग्रेज़ी में उसकी प्रगति को धीमा करेगा","कक्षा 5 में पहुँचने पर इसे रोक देना चाहिए, तब तक की प्रगति चाहे जो हो","यह केवल सीखने की अक्षमता वाले बच्चों के लिए स्वीकार्य है, दूसरों के लिए नहीं","योजना बनाने के कौशल भाषाओं के पार स्थानांतरित होते हैं, और मैतेई का प्रयोग बोझ घटाता है"],"explanationHi":"रचना-कौशल भाषाओं में साझा होते हैं (कमिंस की साझा अंतर्निहित प्रवीणता), और अधिक मज़बूत भाषा में योजना बनाना अंग्रेज़ी में विचार व्यक्त करने के लिए ध्यान मुक्त करता है, जो ट्रांसलैंग्वेजिंग का अभ्यास है।"},
  {"id":"cdp-pedagogy-subjects-875","question":"An older EVS workbook used in a school shows a woman cooking while a man reads the newspaper. The most appropriate way for the Class 3 teacher to use this picture is to:","options":["skip the page, so that children do not notice the stereotype and pick it up","tell children that the picture shows how most families organise their work","ask children who does which work in their homes, and whether it could be different","replace the picture with one showing only men at work, both in the home and outside"],"answer":2,"explanation":"Turning the picture into a discussion makes children notice and question gender roles. Skipping hides the issue, and swapping in another one-sided picture repeats the problem.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक विद्यालय में प्रयुक्त पुरानी EVS कार्यपुस्तिका में एक महिला को खाना बनाते और पुरुष को अख़बार पढ़ते दिखाया गया है। कक्षा 3 की शिक्षिका के लिए इस चित्र का उपयोग करने का सबसे उपयुक्त तरीका है:","optionsHi":["पृष्ठ छोड़ देना, ताकि बच्चे रूढ़ि पर ध्यान न दें और उसे न अपनाएँ","बच्चों को बताना कि चित्र दिखाता है कि अधिकांश परिवार अपना काम कैसे संगठित करते हैं","बच्चों से पूछना कि उनके घरों में कौन-सा काम कौन करता है, और क्या वह अलग हो सकता है","चित्र की जगह ऐसा चित्र लगाना जिसमें केवल पुरुष काम करते दिखें, घर में और बाहर दोनों"],"explanationHi":"चित्र को चर्चा में बदलना बच्चों को लैंगिक भूमिकाओं पर ध्यान देने और प्रश्न उठाने देता है। छोड़ देना मुद्दे को छिपाता है, और किसी दूसरे एकतरफा चित्र से बदलना समस्या दोहराता है।"},
  {"id":"cdp-pedagogy-subjects-876","question":"The NCERT EVS books deliberately show girls climbing trees, men cooking and women driving vehicles. The main purpose is to:","options":["challenge gender stereotypes and widen what children think anyone can do","make the illustrations look modern and attractive to young readers","show that household work is unimportant compared with outside work","suggest that men should do housework instead of outside work"],"answer":0,"explanation":"Counter-stereotypical images are a conscious choice to question fixed gender roles. They do not devalue household work or reverse roles.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"NCERT की EVS पुस्तकें जानबूझकर लड़कियों को पेड़ पर चढ़ते, पुरुषों को खाना बनाते और महिलाओं को वाहन चलाते दिखाती हैं। मुख्य उद्देश्य है:","optionsHi":["लैंगिक रूढ़ियों को चुनौती देना और बच्चों की इस सोच को व्यापक करना कि कोई भी क्या कर सकता है","चित्रों को युवा पाठकों के लिए आधुनिक और आकर्षक बनाना","यह दिखाना कि घरेलू कार्य बाहरी कार्य की तुलना में महत्त्वहीन है","यह सुझाव देना कि पुरुषों को बाहरी कार्य के बजाय घर का काम करना चाहिए"],"explanationHi":"रूढ़ि-विरोधी चित्र निश्चित लैंगिक भूमिकाओं पर प्रश्न उठाने का सचेत चुनाव हैं। वे घरेलू कार्य का अवमूल्यन नहीं करते, न भूमिकाएँ पलटते हैं।"},
  {"id":"cdp-pedagogy-subjects-877","question":"Consider these statements about gender sensitivity in an EVS classroom: I. Always asking girls to sweep and boys to lift benches reinforces stereotypes. II. Gender sensitivity means treating girls as weaker and keeping them away from difficult activities. III. Discussing who does unpaid work at home helps children see the value of that work. Which are correct?","options":["I only","I and III only","II and III only","I, II and III"],"answer":1,"explanation":"Fixed chores reinforce roles, and discussing unpaid work makes it visible. ‘Protecting’ girls from activities is itself a stereotype, so II is wrong.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"EVS कक्षा में लैंगिक संवेदनशीलता के बारे में इन कथनों पर विचार कीजिए: I. हमेशा लड़कियों से झाड़ू लगाने और लड़कों से बेंच उठाने को कहना रूढ़ियों को पुष्ट करता है। II. लैंगिक संवेदनशीलता का अर्थ है लड़कियों को कमज़ोर मानना और उन्हें कठिन गतिविधियों से दूर रखना। III. घर में अवैतनिक कार्य कौन करता है, इस पर चर्चा बच्चों को उस कार्य का मूल्य देखने में मदद करती है। कौन-से सही हैं?","optionsHi":["केवल I","केवल I और III","केवल II और III","I, II और III"],"explanationHi":"निश्चित काम भूमिकाओं को पुष्ट करते हैं, और अवैतनिक कार्य पर चर्चा उसे दृश्य बनाती है। लड़कियों को गतिविधियों से ‘बचाना’ स्वयं एक रूढ़ि है, इसलिए II गलत है।"},
  {"id":"cdp-pedagogy-subjects-878","question":"After reading an EVS story about a visually challenged child who plays chess, a teacher has children cover their eyes and identify objects by touch and smell, and then discuss the experience. The main aim is to:","options":["test which children have the sharpest sense of touch and smell in the class","show children that people with disabilities need our pity and help in everything they do","practise the names and uses of common objects found in the classroom","build empathy and respect for how people with disabilities use other abilities"],"answer":3,"explanation":"The activity moves children from pity to understanding and respect for different abilities. It is not a test of senses or a vocabulary drill.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"शतरंज खेलने वाले दृष्टिबाधित बच्चे की EVS कहानी पढ़ने के बाद एक शिक्षिका बच्चों से आँखें ढककर स्पर्श और गंध से वस्तुएँ पहचानने को कहती है, और फिर अनुभव पर चर्चा करवाती है। मुख्य उद्देश्य है:","optionsHi":["यह परखना कि कक्षा में किन बच्चों की स्पर्श और गंध की इंद्रियाँ सबसे तेज़ हैं","बच्चों को दिखाना कि दिव्यांग लोगों को हर काम में हमारी दया और मदद चाहिए","कक्षा में पाई जाने वाली सामान्य वस्तुओं के नाम और उपयोग का अभ्यास करना","इस बात के प्रति सहानुभूति और सम्मान बनाना कि दिव्यांग लोग अन्य क्षमताओं का उपयोग कैसे करते हैं"],"explanationHi":"गतिविधि बच्चों को दया से समझ और भिन्न क्षमताओं के प्रति सम्मान की ओर ले जाती है। यह इंद्रियों की परीक्षा या शब्दावली का अभ्यास नहीं है।"},
  {"id":"cdp-pedagogy-subjects-879","question":"During a lesson on water, a Class 4 girl says that on some days she misses school because she has to fetch water. The teacher’s best response is to:","options":["tell her that school must come first, and that she should simply refuse to fetch water on school days","discuss why the task falls on girls and how it affects schooling, and raise it with parents and SMC","say nothing in class, since it is a family matter that the school has no part in","mark her absent and inform the head teacher about her irregular attendance for action"],"answer":1,"explanation":"The girl’s experience reveals a gendered burden; EVS aims to help children understand such realities, and the teacher can also work with the community. Ignoring or blaming her helps no one.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"जल के पाठ के दौरान कक्षा 4 की एक बच्ची कहती है कि कुछ दिन वह विद्यालय नहीं आती क्योंकि उसे पानी भरना पड़ता है। शिक्षिका की सबसे अच्छी प्रतिक्रिया है:","optionsHi":["उसे बताना कि विद्यालय पहले आना चाहिए, और उसे विद्यालय के दिनों में पानी भरने से बस इनकार कर देना चाहिए","चर्चा करना कि यह कार्य लड़कियों पर क्यों पड़ता है और यह पढ़ाई को कैसे प्रभावित करता है, और इसे अभिभावकों तथा SMC के सामने उठाना","कक्षा में कुछ न कहना, क्योंकि यह पारिवारिक मामला है जिसमें विद्यालय का कोई स्थान नहीं","उसे अनुपस्थित अंकित करना और उसकी अनियमित उपस्थिति के बारे में कार्रवाई के लिए प्रधानाध्यापक को सूचित करना"],"explanationHi":"बच्ची का अनुभव लैंगिक बोझ प्रकट करता है; EVS का उद्देश्य बच्चों को ऐसी वास्तविकताओं को समझने में मदद करना है, और शिक्षिका समुदाय के साथ भी काम कर सकती है। अनदेखा करना या उसे दोष देना किसी की मदद नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-880","question":"Assertion (A): EVS should take up issues such as child labour and caste discrimination even at the primary level. Reason (R): Many children directly experience these realities, and EVS aims to develop concern for justice and equality. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"NCF 2005 wants EVS to connect with children’s real lives, including unjust ones, and to build sensitivity and concern. R gives exactly that reason.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"अभिकथन (A): EVS को प्राथमिक स्तर पर भी बाल श्रम और जातिगत भेदभाव जैसे मुद्दे उठाने चाहिए। कारण (R): अनेक बच्चे इन वास्तविकताओं का प्रत्यक्ष अनुभव करते हैं, और EVS का उद्देश्य न्याय और समानता के प्रति चिंता विकसित करना है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"NCF 2005 चाहता है कि EVS बच्चों के वास्तविक जीवन, अन्यायपूर्ण जीवन सहित, से जुड़े और संवेदनशीलता तथा चिंता बनाए। R ठीक यही कारण देता है।"},
  {"id":"cdp-pedagogy-subjects-881","question":"Asked to draw ‘a family’, nearly every Class 3 child draws a father, a mother and two children. The teacher’s best next step is to:","options":["praise the drawings, since a father, mother and two children is the ideal family","ask children to add grandparents, so that every drawing shows a proper joint family","share stories and pictures of many kinds of families, such as single-parent ones, and discuss them","tell children their drawings are wrong, because most families in India are bigger than this"],"answer":2,"explanation":"Children draw the image they see everywhere. Exposure to the real variety of families widens the idea and makes children from other families feel included; no form should be called ‘ideal’ or ‘wrong’.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"‘एक परिवार’ बनाने को कहने पर कक्षा 3 का लगभग हर बच्चा एक पिता, एक माँ और दो बच्चे बनाता है। शिक्षिका का सबसे अच्छा अगला कदम है:","optionsHi":["चित्रों की प्रशंसा करना, क्योंकि पिता, माँ और दो बच्चे आदर्श परिवार है","बच्चों से दादा-दादी जोड़ने को कहना, ताकि हर चित्र उचित संयुक्त परिवार दिखाए","अनेक प्रकार के परिवारों की कहानियाँ और चित्र साझा करना, जैसे एकल-अभिभावक वाले, और उन पर चर्चा करना","बच्चों को बताना कि उनके चित्र गलत हैं, क्योंकि भारत में अधिकांश परिवार इससे बड़े हैं"],"explanationHi":"बच्चे वही छवि बनाते हैं जो वे हर जगह देखते हैं। परिवारों की वास्तविक विविधता से परिचय विचार को व्यापक करता है और अन्य परिवारों के बच्चों को शामिल महसूस कराता है; किसी रूप को ‘आदर्श’ या ‘गलत’ नहीं कहना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-882","question":"In every EVS activity a teacher says, ‘Boys, bring the soil; girls, decorate the chart.’ This is best described as:","options":["efficient division of labour suited to children’s abilities","a neutral classroom routine with no effect on learning","a reflection of children’s natural interests","the hidden curriculum transmitting gender stereotypes"],"answer":3,"explanation":"Routine messages that are never stated as lessons still teach children ‘what boys and girls do’. Assuming natural interests is the stereotype itself.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"हर EVS गतिविधि में एक शिक्षक कहता है, ‘लड़के, मिट्टी लाओ; लड़कियाँ, चार्ट सजाओ।’ इसका सबसे अच्छा वर्णन है:","optionsHi":["बच्चों की क्षमताओं के अनुरूप श्रम का कुशल विभाजन","अधिगम पर कोई प्रभाव न डालने वाली तटस्थ कक्षा-दिनचर्या","बच्चों की स्वाभाविक रुचियों का प्रतिबिंब","छिपी पाठ्यचर्या जो लैंगिक रूढ़ियाँ संप्रेषित करती है"],"explanationHi":"नियमित संदेश जो कभी पाठ के रूप में नहीं कहे जाते, फिर भी बच्चों को ‘लड़के और लड़कियाँ क्या करते हैं’ सिखाते हैं। स्वाभाविक रुचियाँ मान लेना स्वयं रूढ़ि है।"},
  {"id":"cdp-pedagogy-subjects-883","question":"During the mid-day meal, some Class 4 children refuse to sit next to a classmate because of her caste. The teacher’s best response is to:","options":["make sure all children eat together, and discuss equality and dignity with them and their parents","seat the classmate separately for now, so that the meal goes on without any conflict","ignore it, since it is a matter of family belief that the school should not interfere in","punish the children who refused, without any discussion, so that it does not happen again"],"answer":0,"explanation":"Untouchability is prohibited by the Constitution, and EVS seeks concern for equality; the teacher must act and also help children and parents rethink. Separate seating endorses the discrimination.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"मध्याह्न भोजन के दौरान कक्षा 4 के कुछ बच्चे जाति के कारण एक सहपाठी के पास बैठने से मना करते हैं। शिक्षक की सबसे अच्छी प्रतिक्रिया है:","optionsHi":["सुनिश्चित करना कि सभी बच्चे साथ खाएँ, और उनसे तथा उनके अभिभावकों से समानता और गरिमा पर चर्चा करना","फ़िलहाल सहपाठी को अलग बैठाना, ताकि भोजन बिना किसी टकराव के चले","इसे अनदेखा करना, क्योंकि यह पारिवारिक मान्यता का मामला है जिसमें विद्यालय को हस्तक्षेप नहीं करना चाहिए","बिना किसी चर्चा के मना करने वाले बच्चों को दंडित करना, ताकि ऐसा दोबारा न हो"],"explanationHi":"संविधान अस्पृश्यता को निषिद्ध करता है, और EVS समानता के प्रति चिंता चाहता है; शिक्षक को कार्रवाई करनी चाहिए और बच्चों तथा अभिभावकों को पुनर्विचार करने में भी मदद करनी चाहिए। अलग बैठक भेदभाव का समर्थन करती है।"},
  {"id":"cdp-pedagogy-subjects-884","question":"A Class 5 boy notices that the girls’ toilet in the school has no water and raises it in the class meeting, asking that it be fixed. In NCERT’s list of EVS learning indicators, this behaviour mainly shows:","options":["Observation and recording","Cooperation","Concern for justice and equality","Experimentation"],"answer":2,"explanation":"Sensitivity to an unfair situation faced by others, and speaking up about it, is concern for justice and equality. Noticing alone would be observation, but the concern and action go further.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 5 का एक लड़का देखता है कि विद्यालय के लड़कियों के शौचालय में पानी नहीं है और कक्षा की बैठक में इसे उठाता है, यह माँग करते हुए कि इसे ठीक किया जाए। NCERT की EVS अधिगम संकेतकों की सूची में यह व्यवहार मुख्यतः क्या दर्शाता है?","optionsHi":["अवलोकन और अभिलेखन","सहयोग","न्याय और समानता के प्रति चिंता","प्रयोग करना"],"explanationHi":"दूसरों के सामने आई अनुचित स्थिति के प्रति संवेदनशीलता और उस पर आवाज़ उठाना न्याय और समानता के प्रति चिंता है। केवल ध्यान देना अवलोकन होता, पर चिंता और कार्रवाई उससे आगे जाती है।"},
  {"id":"cdp-pedagogy-subjects-885","question":"Some Class 4 children call a classmate from Manipur ‘Chinese’. The teacher’s most appropriate response is to:","options":["ignore it, since children say such things casually and do not really mean any harm by them","address it at once, discuss how it hurts and how diverse India is, and learn about Manipur together","move the child from Manipur to another section where she is less likely to be teased","tell the child from Manipur not to mind such jokes, since they will soon stop if she simply ignores them"],"answer":1,"explanation":"Such labels deny a child her identity and belonging. Addressing them immediately and building knowledge about the North-East is what EVS sensitivity requires.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 के कुछ बच्चे मणिपुर की एक सहपाठी को ‘चीनी’ कहकर बुलाते हैं। शिक्षक की सबसे उपयुक्त प्रतिक्रिया है:","optionsHi":["इसे अनदेखा करना, क्योंकि बच्चे ऐसी बातें यूँ ही कह देते हैं और उनसे वास्तव में कोई नुकसान नहीं चाहते","तुरंत इसे संबोधित करना, चर्चा करना कि यह कैसे आहत करता है और भारत कितना विविध है, और साथ मिलकर मणिपुर के बारे में सीखना","मणिपुर की बच्ची को दूसरे खंड में भेजना जहाँ उसे चिढ़ाए जाने की संभावना कम हो","मणिपुर की बच्ची से कहना कि ऐसे मज़ाक का बुरा न माने, क्योंकि यदि वह बस अनदेखा करे तो वे जल्द रुक जाएँगे"],"explanationHi":"ऐसे लेबल बच्ची की पहचान और अपनत्व को नकारते हैं। उन्हें तुरंत संबोधित करना और पूर्वोत्तर के बारे में ज्ञान बनाना वही है जो EVS संवेदनशीलता की माँग करती है।"},
  {"id":"cdp-pedagogy-subjects-886","question":"A Class 4 child with low vision is in an EVS class. Which adaptation is LEAST appropriate?","options":["Using real objects and tactile models that she can handle and explore","Giving her large-print material and seating her close to the board","Pairing her with a peer who describes what is seen during observation tasks","Exempting her from all observation activities so that she is not burdened"],"answer":3,"explanation":"Inclusion means adapting the task, not removing the child from it; observation can use touch, sound and smell. Exemption denies her the learning.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 4 की कम दृष्टि वाली एक बच्ची EVS कक्षा में है। कौन-सा अनुकूलन सबसे कम उपयुक्त है?","optionsHi":["असली वस्तुओं और स्पर्शीय मॉडलों का प्रयोग जिन्हें वह सँभाल और खोज सके","उसे बड़े अक्षरों वाली सामग्री देना और बोर्ड के निकट बैठाना","उसे ऐसे साथी के साथ जोड़ना जो अवलोकन कार्यों में जो दिखता है उसका वर्णन करे","उसे सभी अवलोकन गतिविधियों से छूट देना ताकि उस पर बोझ न पड़े"],"explanationHi":"समावेशन का अर्थ कार्य को अनुकूलित करना है, बच्चे को उससे हटाना नहीं; अवलोकन स्पर्श, ध्वनि और गंध का भी प्रयोग कर सकता है। छूट उसे सीखने से वंचित करती है।"},
  {"id":"cdp-pedagogy-subjects-887","question":"While discussing an EVS story about a girl who works at a tea stall, a Class 5 child says, ‘My cousin works at a dhaba because his family needs money.’ The teacher should best:","options":["acknowledge it without shaming anyone, and discuss every child's right to school and the help available","tell the child that his family is breaking the law and must be reported to the authorities","change the topic quickly, since it is a personal matter that may embarrass the child","ask the child to bring his cousin to school the next day to talk to the class about his work"],"answer":0,"explanation":"The aim is understanding and concern, not blame. Talking about rights and support, without shaming a family in hardship, keeps the child safe and the discussion honest.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक चाय की दुकान पर काम करने वाली लड़की की EVS कहानी पर चर्चा करते हुए कक्षा 5 का एक बच्चा कहता है, ‘मेरा चचेरा भाई ढाबे पर काम करता है क्योंकि उसके परिवार को पैसों की ज़रूरत है।’ शिक्षक को सबसे अच्छा क्या करना चाहिए?","optionsHi":["किसी को शर्मिंदा किए बिना इसे स्वीकार करना, और हर बच्चे के विद्यालय के अधिकार तथा उपलब्ध सहायता पर चर्चा करना","बच्चे को बताना कि उसका परिवार कानून तोड़ रहा है और उसकी अधिकारियों को सूचना दी जानी चाहिए","विषय जल्दी बदल देना, क्योंकि यह निजी मामला है जो बच्चे को शर्मिंदा कर सकता है","बच्चे से अगले दिन अपने चचेरे भाई को विद्यालय लाने को कहना ताकि वह कक्षा को अपने काम के बारे में बताए"],"explanationHi":"उद्देश्य समझ और चिंता है, दोष नहीं। अधिकारों और सहायता पर बात करना, कठिनाई में पड़े परिवार को शर्मिंदा किए बिना, बच्चे को सुरक्षित और चर्चा को ईमानदार रखता है।"},
  {"id":"cdp-pedagogy-subjects-888","question":"In a lesson on ‘Work and Play’, which question best helps Class 3 children reflect on gender?","options":["Name five games played in different parts of India, and say where each is played.","Which game do you like best, and what do you enjoy most about playing it?","Which games do boys and girls play in your area? Are some games not allowed for girls? Why?","How many players are there in a kabaddi team, and how is the game scored?"],"answer":2,"explanation":"Only this question asks children to notice and question a gendered pattern in their own lives. The others ask for lists, preferences or facts.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"‘काम और खेल’ के पाठ में कौन-सा प्रश्न कक्षा 3 के बच्चों को लिंग पर चिंतन करने में सबसे अच्छी तरह मदद करता है?","optionsHi":["भारत के अलग-अलग भागों में खेले जाने वाले पाँच खेलों के नाम बताओ, और कहाँ कौन-सा खेला जाता है।","तुम्हें कौन-सा खेल सबसे अच्छा लगता है, और उसे खेलने में तुम्हें सबसे अधिक क्या पसंद है?","तुम्हारे इलाके में लड़के और लड़कियाँ कौन-से खेल खेलते हैं? क्या कुछ खेल लड़कियों के लिए मना हैं? क्यों?","कबड्डी की टीम में कितने खिलाड़ी होते हैं, और खेल में अंक कैसे दिए जाते हैं?"],"explanationHi":"केवल यही प्रश्न बच्चों से अपने जीवन में लैंगिक पैटर्न पर ध्यान देने और प्रश्न उठाने को कहता है। अन्य सूचियाँ, पसंद या तथ्य माँगते हैं।"},
  {"id":"cdp-pedagogy-subjects-889","question":"A teacher believes that ‘being sensitive’ means not talking about poverty, caste or gender in EVS, so that no child feels uncomfortable. The best critique of this view is that:","options":["such topics should be left to secondary school social science, when children are older","avoiding them leaves prejudice unchallenged; the aim is to take them up with care so all feel respected","children at this age are not affected by these issues and do not notice them at all","the view is correct, since EVS should deal only with nature, plants, animals and the wider physical environment"],"answer":1,"explanation":"Silence protects existing prejudice; NCF 2005 asks EVS to address social realities sensitively. EVS is not limited to nature.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक शिक्षक मानता है कि ‘संवेदनशील होना’ का अर्थ EVS में गरीबी, जाति या लिंग के बारे में बात न करना है, ताकि कोई बच्चा असहज न हो। इस विचार की सबसे अच्छी आलोचना यह है कि:","optionsHi":["ऐसे विषय माध्यमिक विद्यालय के सामाजिक विज्ञान के लिए छोड़ देने चाहिए, जब बच्चे बड़े हों","इनसे बचना पूर्वाग्रह को अचुनौतीपूर्ण छोड़ देता है; उद्देश्य इन्हें सावधानी से उठाना है ताकि सभी सम्मानित महसूस करें","इस आयु के बच्चे इन मुद्दों से प्रभावित नहीं होते और इन्हें बिल्कुल नहीं देखते","यह विचार सही है, क्योंकि EVS को केवल प्रकृति, पौधों, जानवरों और व्यापक भौतिक पर्यावरण से निपटना चाहिए"],"explanationHi":"चुप्पी मौजूदा पूर्वाग्रह की रक्षा करती है; NCF 2005 EVS से सामाजिक वास्तविकताओं को संवेदनशीलता से संबोधित करने को कहता है। EVS प्रकृति तक सीमित नहीं है।"},
  {"id":"cdp-pedagogy-subjects-890","question":"In a discussion on ‘Shelter’, a Class 4 child mentions that her family sleeps on the footpath near the railway station. The teacher should:","options":["ask her to describe her life in detail to the whole class, as a real-life example","tell the class that people without homes have usually not worked hard enough","quickly change the subject, so that she is spared any embarrassment in front of her classmates","ensure no one mocks her, and discuss why some people lack homes, without singling her out"],"answer":3,"explanation":"Sensitivity means protecting the child’s dignity while helping the class understand homelessness as a social issue. Making her an exhibit or silencing her both harm her.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"‘आश्रय’ पर चर्चा में कक्षा 4 की एक बच्ची बताती है कि उसका परिवार रेलवे स्टेशन के पास फुटपाथ पर सोता है। शिक्षक को चाहिए कि:","optionsHi":["उससे पूरी कक्षा को अपने जीवन का विस्तार से वर्णन करने को कहे, वास्तविक जीवन के उदाहरण के रूप में","कक्षा को बताए कि बेघर लोगों ने आमतौर पर पर्याप्त मेहनत नहीं की होती","जल्दी विषय बदल दे, ताकि सहपाठियों के सामने उसे किसी शर्मिंदगी से बचाया जा सके","सुनिश्चित करे कि कोई उसका मज़ाक न उड़ाए, और उसे अलग से चिह्नित किए बिना चर्चा करे कि कुछ लोगों के पास घर क्यों नहीं होते"],"explanationHi":"संवेदनशीलता का अर्थ है बच्ची की गरिमा की रक्षा करना और साथ ही कक्षा को बेघरपन को सामाजिक मुद्दे के रूप में समझने में मदद करना। उसे प्रदर्शन-वस्तु बनाना या चुप कराना दोनों उसे हानि पहुँचाते हैं।"},
  {"id":"cdp-pedagogy-subjects-891","question":"Assertion (A): An EVS teacher should actively encourage girls to take part in experiments and outdoor fieldwork. Reason (R): Girls are naturally less interested in science than boys. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"Encouraging girls counters social barriers, but there is no natural difference in interest; such gaps are produced by stereotypes and opportunity. R is false.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"अभिकथन (A): EVS शिक्षक को लड़कियों को प्रयोगों और बाहरी क्षेत्र-कार्य में भाग लेने के लिए सक्रिय रूप से प्रोत्साहित करना चाहिए। कारण (R): लड़कियाँ स्वाभाविक रूप से लड़कों की तुलना में विज्ञान में कम रुचि रखती हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"लड़कियों को प्रोत्साहित करना सामाजिक बाधाओं का प्रतिरोध करता है, पर रुचि में कोई स्वाभाविक अंतर नहीं है; ऐसे अंतर रूढ़ियों और अवसरों से पैदा होते हैं। R असत्य है।"},
  {"id":"cdp-pedagogy-subjects-892","question":"Match each term with its example: 1. Stereotype 2. Prejudice 3. Discrimination 4. Inclusion. a. Refusing a child a seat because of her community. b. Believing that all girls are poor at using tools. c. Disliking a group without knowing any of its members. d. Planning an activity so that every child, including one with a disability, can take part.","options":["1-c, 2-b, 3-a, 4-d","1-b, 2-a, 3-c, 4-d","1-a, 2-c, 3-b, 4-d","1-b, 2-c, 3-a, 4-d"],"answer":3,"explanation":"A stereotype is a fixed generalisation (b), prejudice is a negative attitude (c), discrimination is unfair action (a), and inclusion is planning for everyone’s participation (d).","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"प्रत्येक पद का मिलान उसके उदाहरण से कीजिए: 1. रूढ़ि 2. पूर्वाग्रह 3. भेदभाव 4. समावेशन। a. किसी बच्ची को उसके समुदाय के कारण सीट देने से इनकार करना। b. यह मानना कि सभी लड़कियाँ औज़ार चलाने में कमज़ोर होती हैं। c. किसी समूह के किसी सदस्य को जाने बिना उसे नापसंद करना। d. गतिविधि की ऐसी योजना बनाना कि दिव्यांग बच्चे सहित हर बच्चा भाग ले सके।","optionsHi":["1-c, 2-b, 3-a, 4-d","1-b, 2-a, 3-c, 4-d","1-a, 2-c, 3-b, 4-d","1-b, 2-c, 3-a, 4-d"],"explanationHi":"रूढ़ि एक निश्चित सामान्यीकरण है (b), पूर्वाग्रह नकारात्मक दृष्टिकोण है (c), भेदभाव अनुचित कार्य है (a), और समावेशन सबकी भागीदारी की योजना बनाना है (d)।"},
  {"id":"cdp-pedagogy-subjects-893","question":"While reviewing an old EVS chart, a teacher finds that all the doctors shown are men and all the nurses are women. The best use of the chart is to:","options":["ask whether this is always so, and share examples of women doctors and men nurses","throw it away quietly and never mention it, so that children are not exposed to the bias","use it as it is, since it shows the usual pattern seen in most hospitals","tell children that this shows which jobs suit men and which suit women"],"answer":0,"explanation":"Using biased material critically teaches children to read pictures with a questioning eye and to see counter-examples. Discarding it silently loses that chance.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"एक पुराने EVS चार्ट की समीक्षा करते हुए एक शिक्षक पाता है कि दिखाए गए सभी डॉक्टर पुरुष हैं और सभी नर्सें महिलाएँ। चार्ट का सबसे अच्छा उपयोग है:","optionsHi":["पूछना कि क्या ऐसा हमेशा होता है, और महिला डॉक्टरों तथा पुरुष नर्सों के उदाहरण साझा करना","इसे चुपचाप फेंक देना और कभी उल्लेख न करना, ताकि बच्चे पूर्वाग्रह के संपर्क में न आएँ","इसे जैसा है वैसा प्रयोग करना, क्योंकि यह अधिकांश अस्पतालों में देखा जाने वाला सामान्य पैटर्न दिखाता है","बच्चों को बताना कि यह दिखाता है कि कौन-से काम पुरुषों के और कौन-से महिलाओं के लिए उपयुक्त हैं"],"explanationHi":"पक्षपाती सामग्री का आलोचनात्मक उपयोग बच्चों को प्रश्न करने वाली दृष्टि से चित्र पढ़ना और विपरीत उदाहरण देखना सिखाता है। उसे चुपचाप हटाना वह अवसर खो देता है।"},
  {"id":"cdp-pedagogy-subjects-894","question":"After reading about how Gandhiji asked everyone to clean toilets in his ashram, a Class 5 teacher plans the school cleaning duties. The practice most in line with the spirit of the lesson is to:","options":["give cleaning duties to children whose families already do such work","ask only the girls to clean, since they are usually neater and more careful","rotate cleaning duties among all children, regardless of caste or gender","leave all cleaning to the school sweeper, so that children can study"],"answer":2,"explanation":"Rotating duties among everyone puts dignity of labour into practice and breaks caste and gender links with cleaning. The other options reinforce those links.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"यह पढ़ने के बाद कि गांधीजी ने अपने आश्रम में सबसे शौचालय साफ करवाए, कक्षा 5 की एक शिक्षिका विद्यालय की सफाई के कर्तव्यों की योजना बनाती है। पाठ की भावना के सबसे अनुरूप प्रथा है:","optionsHi":["सफाई के कर्तव्य उन बच्चों को देना जिनके परिवार पहले से ऐसा काम करते हैं","केवल लड़कियों से सफाई करवाना, क्योंकि वे आमतौर पर अधिक साफ-सुथरी और सावधान होती हैं","जाति या लिंग का ध्यान किए बिना सफाई के कर्तव्यों का सभी बच्चों में चक्रीकरण करना","सारी सफाई विद्यालय के सफाईकर्मी पर छोड़ देना, ताकि बच्चे पढ़ सकें"],"explanationHi":"सबमें कर्तव्यों का चक्रीकरण श्रम की गरिमा को व्यवहार में लाता है और सफाई से जाति और लिंग के संबंध को तोड़ता है। अन्य विकल्प उन संबंधों को पुष्ट करते हैं।"},
  {"id":"cdp-pedagogy-subjects-895","question":"A Class 5 teacher plans a household survey on toilets and sanitation. Some children’s families have no toilet at home. The teacher should:","options":["drop the survey altogether, since the topic may embarrass some of the children","keep individual answers private, and discuss patterns in the community and their reasons","read out each child's answer in class, so that the class gets complete and accurate data","ask only children from families with toilets to take part, so that nobody is embarrassed"],"answer":1,"explanation":"Sensitive surveys protect privacy while still letting children analyse social issues. Public exposure shames children; dropping or restricting the survey loses learning.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 5 की एक शिक्षिका शौचालयों और स्वच्छता पर घरेलू सर्वेक्षण की योजना बनाती है। कुछ बच्चों के परिवारों के घर में शौचालय नहीं है। शिक्षिका को चाहिए कि:","optionsHi":["सर्वेक्षण पूरी तरह छोड़ दे, क्योंकि विषय कुछ बच्चों को शर्मिंदा कर सकता है","व्यक्तिगत उत्तर निजी रखे, और समुदाय के पैटर्न और उनके कारणों पर चर्चा करे","प्रत्येक बच्चे का उत्तर कक्षा में पढ़कर सुनाए, ताकि कक्षा को पूर्ण और सटीक आँकड़े मिलें","केवल उन बच्चों से भाग लेने को कहे जिनके परिवारों में शौचालय हैं, ताकि कोई शर्मिंदा न हो"],"explanationHi":"संवेदनशील सर्वेक्षण गोपनीयता की रक्षा करते हैं और फिर भी बच्चों को सामाजिक मुद्दों का विश्लेषण करने देते हैं। सार्वजनिक प्रकटीकरण बच्चों को शर्मिंदा करता है; सर्वेक्षण छोड़ने या सीमित करने से सीखना खो जाता है।"},
  {"id":"cdp-pedagogy-subjects-896","question":"A Class 3 teacher plans a chart with two columns: ‘Mother’s work’ and ‘Father’s work’. A more sensitive way to frame the same activity is:","options":["‘Work done by women’ and ‘Work done by men’","‘Easy work’ and ‘Hard work’","‘Indoor work’ and ‘Outdoor work’","‘Who does what work in your family?’"],"answer":3,"explanation":"The open question does not assume that roles are fixed by gender or that every family has a mother and a father. The other frames still sort work in assumed or ranked categories.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की एक शिक्षिका दो स्तंभों ‘माँ का काम’ और ‘पिता का काम’ वाला चार्ट बनाने की योजना बनाती है। उसी गतिविधि को ढालने का अधिक संवेदनशील तरीका है:","optionsHi":["‘महिलाओं द्वारा किया गया काम’ और ‘पुरुषों द्वारा किया गया काम’","‘आसान काम’ और ‘कठिन काम’","‘घर के भीतर का काम’ और ‘घर के बाहर का काम’","‘तुम्हारे परिवार में कौन-सा काम कौन करता है?’"],"explanationHi":"खुला प्रश्न यह नहीं मानता कि भूमिकाएँ लिंग से तय हैं या हर परिवार में माँ और पिता हैं। अन्य ढाँचे अब भी काम को मानी हुई या क्रमबद्ध श्रेणियों में छाँटते हैं।"},
  {"id":"cdp-pedagogy-subjects-897","question":"Which of the following are in line with NCF 2005’s view of EVS? I. It should reflect diverse lives, including those of marginalised groups. II. It should present the urban middle-class family as the normal family. III. It should allow children to question unfair practices around them.","options":["I and III only","I and II only","II and III only","I, II and III"],"answer":0,"explanation":"NCF 2005 asks for diversity and critical engagement with injustice; treating one kind of family as normal excludes many children, so II is wrong.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"निम्नलिखित में से कौन EVS के बारे में NCF 2005 के दृष्टिकोण के अनुरूप हैं? I. उसे हाशिये के समूहों सहित विविध जीवनों को प्रतिबिंबित करना चाहिए। II. उसे शहरी मध्यवर्गीय परिवार को सामान्य परिवार के रूप में प्रस्तुत करना चाहिए। III. उसे बच्चों को अपने आसपास की अनुचित प्रथाओं पर प्रश्न उठाने देना चाहिए।","optionsHi":["केवल I और III","केवल I और II","केवल II और III","I, II और III"],"explanationHi":"NCF 2005 विविधता और अन्याय के साथ आलोचनात्मक जुड़ाव माँगता है; एक प्रकार के परिवार को सामान्य मानना अनेक बच्चों को बाहर करता है, इसलिए II गलत है।"},
  {"id":"cdp-pedagogy-subjects-898","question":"Which observation best shows ‘concern for justice and equality’ in a Class 4 child?","options":["She draws a very neat and detailed chart of the animals found near her home, labelling each one","She asks many thoughtful questions about how different birds build their nests and from what","In a game, she makes sure a classmate in a wheelchair gets a role, changing the rules so he can play","She correctly sorts a large collection of leaves into groups by their shapes"],"answer":2,"explanation":"Acting so that a disadvantaged peer is included is the core of this indicator. The others show recording, questioning and classification.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 4 की बच्ची में ‘न्याय और समानता के प्रति चिंता’ को कौन-सा अवलोकन सबसे अच्छी तरह दर्शाता है?","optionsHi":["वह अपने घर के पास पाए जाने वाले जानवरों का बहुत साफ और विस्तृत चार्ट बनाती है, प्रत्येक को नामांकित करती है","वह इस बारे में अनेक विचारशील प्रश्न पूछती है कि अलग-अलग पक्षी अपने घोंसले कैसे और किससे बनाते हैं","खेल में वह सुनिश्चित करती है कि व्हीलचेयर वाले सहपाठी को भूमिका मिले, और नियम बदलती है ताकि वह खेल सके","वह पत्तियों के बड़े संग्रह को उनके आकार के आधार पर सही ढंग से समूहों में छाँटती है"],"explanationHi":"इस प्रकार काम करना कि वंचित साथी शामिल हो, इस संकेतक का मर्म है। अन्य अभिलेखन, प्रश्न पूछना और वर्गीकरण दर्शाते हैं।"},
  {"id":"cdp-pedagogy-subjects-899","question":"In the ‘Food’ theme, Class 5 children ask why some people do not get enough to eat when farmers grow so much grain. The best way for the teacher to handle this is to:","options":["explain that people who are poor usually do not work hard enough to buy enough food","open an inquiry into causes such as income, storage and distribution, and schemes like ration shops","tell children the question is too complex for their age and will be taken up later","ask children to donate food to the needy and close the discussion on a positive note"],"answer":1,"explanation":"The question invites real analysis of a social issue; exploring causes and public schemes builds understanding without blaming the poor. Brushing it aside or reducing it to charity stops the thinking.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"‘भोजन’ विषय में कक्षा 5 के बच्चे पूछते हैं कि जब किसान इतना अनाज उगाते हैं तब भी कुछ लोगों को पर्याप्त खाने को क्यों नहीं मिलता। शिक्षक के इसे सँभालने का सबसे अच्छा तरीका है:","optionsHi":["समझाना कि जो लोग गरीब हैं वे आमतौर पर पर्याप्त भोजन खरीदने लायक मेहनत नहीं करते","आय, भंडारण और वितरण जैसे कारणों तथा राशन की दुकानों जैसी योजनाओं की जाँच शुरू करना","बच्चों को बताना कि प्रश्न उनकी आयु के लिए बहुत जटिल है और बाद में लिया जाएगा","बच्चों से ज़रूरतमंदों के लिए भोजन दान करने को कहना और चर्चा को सकारात्मक बात पर बंद करना"],"explanationHi":"प्रश्न एक सामाजिक मुद्दे के वास्तविक विश्लेषण को आमंत्रित करता है; कारणों और सार्वजनिक योजनाओं की खोज गरीबों को दोष दिए बिना समझ बनाती है। इसे टाल देना या दान तक सीमित कर देना सोच को रोकता है।"},
  {"id":"cdp-pedagogy-subjects-900","question":"Match each misconception with the activity best suited to challenge it. P. A bulb uses up current  Q. Plants get their food from the soil  R. Heavier objects fall faster  S. A sweater produces heat. 1. Keeping a thermometer inside a folded sweater for an hour  2. Placing identical ammeters on both sides of a bulb  3. Discussing van Helmont's willow tree experiment  4. Dropping two balls of the same size but different mass together","options":["P-2, Q-3, R-4, S-1","P-2, Q-4, R-3, S-1","P-1, Q-3, R-4, S-2","P-3, Q-2, R-4, S-1"],"answer":0,"explanation":"Equal ammeter readings counter 'used-up current'; the willow gaining mass from almost no soil counters 'food from soil'; equal fall times counter 'heavier falls faster'; an unchanged thermometer counters 'sweater produces heat'.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"प्रत्येक भ्रांति का मिलान उसे चुनौती देने के लिए सबसे उपयुक्त गतिविधि से कीजिए। P. बल्ब धारा को खर्च कर देता है  Q. पौधे अपना भोजन मिट्टी से लेते हैं  R. भारी वस्तुएँ तेज़ गिरती हैं  S. स्वेटर ऊष्मा उत्पन्न करता है। 1. एक घंटे तक तापमापी को मोड़े हुए स्वेटर के अंदर रखना  2. बल्ब के दोनों ओर एक जैसे ऐमीटर लगाना  3. वान हेल्मोंट के विलो वृक्ष के प्रयोग पर चर्चा करना  4. एक ही आकार पर भिन्न द्रव्यमान वाली दो गेंदों को साथ गिराना","optionsHi":["P-2, Q-3, R-4, S-1","P-2, Q-4, R-3, S-1","P-1, Q-3, R-4, S-2","P-3, Q-2, R-4, S-1"],"explanationHi":"समान ऐमीटर पाठ्यांक ‘खर्च होती धारा’ का खंडन करते हैं; विलो का लगभग बिना मिट्टी घटाए द्रव्यमान बढ़ना ‘मिट्टी से भोजन’ का; समान गिरने का समय ‘भारी तेज़ गिरता है’ का; और अपरिवर्तित तापमापी ‘स्वेटर ऊष्मा उत्पन्न करता है’ का।"},
  {"id":"cdp-pedagogy-subjects-901","question":"How many of the following are integrated (not basic) science process skills? Controlling variables, interpreting data, classifying, formulating models, measuring.","options":["Two","Four","Three","Five"],"answer":2,"explanation":"Controlling variables, interpreting data and formulating models are integrated process skills. Classifying and measuring are basic process skills.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"निम्नलिखित में से कितने समाकलित (मूल नहीं) विज्ञान प्रक्रिया कौशल हैं? चरों को नियंत्रित करना, आँकड़ों की व्याख्या करना, वर्गीकरण करना, मॉडल बनाना, मापना।","optionsHi":["दो","चार","तीन","पाँच"],"explanationHi":"चरों को नियंत्रित करना, आँकड़ों की व्याख्या करना और मॉडल बनाना समाकलित प्रक्रिया कौशल हैं। वर्गीकरण और मापन मूल प्रक्रिया कौशल हैं।"},
  {"id":"cdp-pedagogy-subjects-902","question":"After an investigation supports her hypothesis, a Class 8 student writes, 'My experiment has proved my hypothesis true for ever.' The teacher should help her understand that:","options":["One supporting experiment is enough to turn a hypothesis into a scientific law","Evidence can support a hypothesis, but further tests could still challenge it","A hypothesis can never be supported by an experiment, so her result means nothing","Her experiment proved nothing because school experiments are not real science"],"answer":1,"explanation":"Scientific claims are tentative: supporting evidence increases confidence, but new evidence may require revision. Calling it proved for ever ignores this, and dismissing school experiments is equally wrong.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"एक जाँच के उसकी परिकल्पना का समर्थन करने के बाद कक्षा 8 की एक विद्यार्थी लिखती है, ‘मेरे प्रयोग ने मेरी परिकल्पना को हमेशा के लिए सही सिद्ध कर दिया।’ शिक्षक को उसे क्या समझने में मदद करनी चाहिए?","optionsHi":["एक समर्थक प्रयोग परिकल्पना को वैज्ञानिक नियम में बदलने के लिए पर्याप्त है","साक्ष्य किसी परिकल्पना का समर्थन कर सकता है, पर आगे के परीक्षण उसे फिर भी चुनौती दे सकते हैं","परिकल्पना का समर्थन कोई प्रयोग कभी नहीं कर सकता, इसलिए उसके परिणाम का कोई अर्थ नहीं","उसके प्रयोग ने कुछ सिद्ध नहीं किया क्योंकि विद्यालय के प्रयोग असली विज्ञान नहीं हैं"],"explanationHi":"वैज्ञानिक दावे अस्थायी होते हैं: समर्थक साक्ष्य विश्वास बढ़ाता है, पर नया साक्ष्य संशोधन माँग सकता है। उसे हमेशा के लिए सिद्ध कहना इसे अनदेखा करता है, और विद्यालय के प्रयोगों को खारिज करना भी उतना ही गलत है।"},
  {"id":"cdp-pedagogy-subjects-903","question":"Two Class 8 students look at the same onion peel slide under a microscope. One reports 'brick-like cells with a dark dot in each'; the other, who has never seen cells, reports 'some lines and bubbles'. This best illustrates that:","options":["The second student's microscope was not focused or working properly","The first student must have copied the description from the textbook","Observations are shaped by what the observer already knows and looks for","Microscopes give slightly different images to the different people looking through them"],"answer":2,"explanation":"Observation is not purely passive; knowing what cells and nuclei look like guides what one notices and how one describes it. Teachers therefore need to guide observation, not just say 'look'.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा 8 के दो विद्यार्थी सूक्ष्मदर्शी के नीचे प्याज़ के छिलके की एक ही स्लाइड देखते हैं। एक बताता है ‘ईंट जैसी कोशिकाएँ जिनमें हर एक में एक गहरा बिंदु’; दूसरा, जिसने कभी कोशिकाएँ नहीं देखीं, बताता है ‘कुछ रेखाएँ और बुलबुले’। यह सबसे अच्छी तरह क्या दर्शाता है?","optionsHi":["दूसरे विद्यार्थी का सूक्ष्मदर्शी फ़ोकस में नहीं था या ठीक से काम नहीं कर रहा था","पहले विद्यार्थी ने वर्णन पाठ्यपुस्तक से उतारा होगा","अवलोकन इस बात से आकार पाते हैं कि अवलोकनकर्ता पहले से क्या जानता है और क्या खोजता है","सूक्ष्मदर्शी देखने वाले अलग-अलग लोगों को थोड़ी भिन्न छवियाँ देते हैं"],"explanationHi":"अवलोकन पूरी तरह निष्क्रिय नहीं होता; कोशिकाएँ और केंद्रक कैसे दिखते हैं यह जानना निर्देशित करता है कि व्यक्ति क्या नोटिस करता है और उसका वर्णन कैसे करता है। इसलिए शिक्षकों को अवलोकन का मार्गदर्शन करना चाहिए, केवल ‘देखो’ नहीं कहना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-904","question":"A student brings a phone message claiming that 'drinking hot water every hour cures all infections'. The teacher uses it in class. Which line of questioning best develops students' scientific thinking?","options":["'Who sent the message? If it came from someone older and educated, it must be true.'","'How many people have shared it? If so many have shared it, it must surely be true.'","'Does it sound sensible to us? If it does, we can safely accept it as true without checking.'","'What evidence supports it? Was it compared with people who did not drink hot water?'"],"answer":3,"explanation":"Scientific thinking judges claims by evidence and fair comparison, not by authority, popularity or plausibility. This builds the media literacy that science education should give citizens.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs","questionHi":"एक विद्यार्थी फ़ोन संदेश लाता है जो दावा करता है कि ‘हर घंटे गर्म पानी पीने से सभी संक्रमण ठीक हो जाते हैं’। शिक्षक इसे कक्षा में प्रयोग करता है। प्रश्न करने की कौन-सी पंक्ति विद्यार्थियों के वैज्ञानिक चिंतन को सबसे अच्छी तरह विकसित करती है?","optionsHi":["‘संदेश किसने भेजा? यदि किसी बड़े और शिक्षित व्यक्ति ने भेजा है, तो यह सच होगा।’","‘इसे कितने लोगों ने साझा किया है? यदि इतने लोगों ने साझा किया है, तो यह निश्चित रूप से सच होगा।’","‘क्या यह हमें समझदारी भरा लगता है? यदि लगता है, तो हम बिना जाँचे इसे सच मान सकते हैं।’","‘इसका समर्थन कौन-सा साक्ष्य करता है? क्या इसकी तुलना उन लोगों से की गई जिन्होंने गर्म पानी नहीं पिया?’"],"explanationHi":"वैज्ञानिक चिंतन दावों को साक्ष्य और उचित तुलना से परखता है, अधिकार, लोकप्रियता या संभाव्यता से नहीं। यह वह मीडिया साक्षरता बनाता है जो विज्ञान शिक्षा को नागरिकों को देनी चाहिए।"},
  {"id":"cdp-pedagogy-subjects-905","question":"Consider these statements about the 5E model. 1. The Engage phase should bring out students' prior ideas and raise curiosity. 2. In the Explore phase, the teacher first gives formal definitions for students to verify. 3. The Explain phase builds on what students experienced during exploration. 4. Assessment can happen throughout, though the Evaluate phase formally checks understanding. Which are correct?","options":["1, 3 and 4 only","1 and 2 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"In 5E, formal explanations come after exploration, so statement 2 reverses the model. The others correctly describe Engage, Explain and the role of assessment.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"5E मॉडल के बारे में इन कथनों पर विचार कीजिए। 1. संलग्नता (Engage) चरण को विद्यार्थियों के पूर्व विचार सामने लाने और जिज्ञासा जगानी चाहिए। 2. अन्वेषण (Explore) चरण में शिक्षक पहले विद्यार्थियों के सत्यापन के लिए औपचारिक परिभाषाएँ देता है। 3. व्याख्या (Explain) चरण उस पर आधारित होता है जो विद्यार्थियों ने अन्वेषण के दौरान अनुभव किया। 4. आकलन पूरे समय हो सकता है, यद्यपि मूल्यांकन (Evaluate) चरण औपचारिक रूप से समझ की जाँच करता है। कौन-से सही हैं?","optionsHi":["केवल 1, 3 और 4","केवल 1 और 2","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"5E में औपचारिक व्याख्याएँ अन्वेषण के बाद आती हैं, इसलिए कथन 2 मॉडल को उलट देता है। अन्य संलग्नता, व्याख्या और आकलन की भूमिका का सही वर्णन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-906","question":"Which opening is most suitable for the Engage phase of a Class 8 lesson on rusting?","options":["Writing the chemical equation for rusting on the board for students to copy","Asking why people paint iron gates before the monsoon, and showing a rusted and a new nail","Dictating the definition of rusting and the methods of its prevention","Giving a short test on the previous chapter to check what students remember"],"answer":1,"explanation":"Engage should connect to everyday experience and raise a question worth investigating. An equation or definition at the outset belongs, if at all, to the Explain phase.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा 8 के जंग लगने के पाठ के संलग्नता चरण के लिए कौन-सी शुरुआत सबसे उपयुक्त है?","optionsHi":["बोर्ड पर जंग लगने का रासायनिक समीकरण लिखना ताकि विद्यार्थी उतारें","पूछना कि लोग मानसून से पहले लोहे के फाटक क्यों रंगते हैं, और जंग लगी तथा नई कील दिखाना","जंग लगने की परिभाषा और उसके रोकथाम के तरीके श्रुतलेख में लिखवाना","पिछले अध्याय पर एक छोटी परीक्षा लेना यह जाँचने के लिए कि विद्यार्थियों को क्या याद है"],"explanationHi":"संलग्नता को दैनिक अनुभव से जुड़ना चाहिए और जाँच-योग्य प्रश्न उठाना चाहिए। आरंभ में समीकरण या परिभाषा, यदि कहीं, तो व्याख्या चरण की है।"},
  {"id":"cdp-pedagogy-subjects-907","question":"In which of the following situations is the lecture-cum-demonstration method more suitable than individual laboratory work? 1. Only one set of costly apparatus is available. 2. The aim is to develop each student's skill in handling apparatus. 3. The experiment involves a hazard. 4. The class is large and time is short.","options":["1 and 2 only","2 and 4 only","1, 2, 3 and 4","1, 3 and 4 only"],"answer":3,"explanation":"Demonstrations suit costly, scarce or hazardous experiments and situations with large classes and little time. Developing each student's manipulative skill requires students to handle the apparatus themselves.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"निम्नलिखित में से किन स्थितियों में व्यक्तिगत प्रयोगशाला कार्य की तुलना में व्याख्यान-सह-प्रदर्शन विधि अधिक उपयुक्त है? 1. केवल एक महँगा उपकरण-सेट उपलब्ध है। 2. उद्देश्य प्रत्येक विद्यार्थी का उपकरण सँभालने का कौशल विकसित करना है। 3. प्रयोग में कोई खतरा है। 4. कक्षा बड़ी है और समय कम है।","optionsHi":["केवल 1 और 2","केवल 2 और 4","1, 2, 3 और 4","केवल 1, 3 और 4"],"explanationHi":"प्रदर्शन महँगे, दुर्लभ या खतरनाक प्रयोगों और बड़ी कक्षाओं तथा कम समय की स्थितियों के लिए उपयुक्त हैं। प्रत्येक विद्यार्थी के हस्तकौशल के विकास के लिए विद्यार्थियों को स्वयं उपकरण सँभालना आवश्यक है।"},
  {"id":"cdp-pedagogy-subjects-908","question":"Which objective of science teaching can be achieved only poorly through teacher demonstrations and needs students to do laboratory work themselves?","options":["Developing skill in handling apparatus and taking accurate readings","Arousing interest and curiosity at the start of a new topic","Showing a hazardous reaction safely to the whole class","Saving time and material when apparatus is limited or costly"],"answer":0,"explanation":"Manipulative skills are developed only through one's own practice with apparatus. The other aims are in fact strengths of the demonstration method.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"विज्ञान शिक्षण का कौन-सा उद्देश्य शिक्षक के प्रदर्शनों से केवल खराब ढंग से प्राप्त हो सकता है और विद्यार्थियों को प्रयोगशाला कार्य स्वयं करने की आवश्यकता है?","optionsHi":["उपकरण सँभालने और सटीक पाठ्यांक लेने में कौशल का विकास","किसी नए विषय की शुरुआत में रुचि और जिज्ञासा जगाना","पूरी कक्षा को खतरनाक अभिक्रिया सुरक्षित रूप से दिखाना","जब उपकरण सीमित या महँगे हों तब समय और सामग्री बचाना"],"explanationHi":"हस्तकौशल केवल उपकरण के साथ अपने अभ्यास से विकसित होते हैं। अन्य उद्देश्य वास्तव में प्रदर्शन विधि की शक्तियाँ हैं।"},
  {"id":"cdp-pedagogy-subjects-909","question":"During a class debate on farmers burning crop stubble, students hold sharply different views. The most appropriate role for the science teacher is to:","options":["Tell students the right opinion, so that the debate ends quickly and no one is confused","Avoid the topic altogether, since it is controversial and may upset some families","Ensure evidence from different perspectives is examined and students give reasons for their views","Let students say whatever they like, without asking for evidence, so that all feel heard"],"answer":2,"explanation":"For socio-scientific issues the teacher facilitates evidence-based reasoning across perspectives (farmers' costs, air quality, health), rather than imposing her own view or leaving claims unexamined.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"किसानों द्वारा फ़सल के ठूँठ जलाने पर कक्षा बहस के दौरान विद्यार्थियों के विचार तीव्र रूप से भिन्न हैं। विज्ञान शिक्षक की सबसे उपयुक्त भूमिका है:","optionsHi":["विद्यार्थियों को सही राय बताना, ताकि बहस जल्दी समाप्त हो और कोई भ्रमित न हो","विषय से पूरी तरह बचना, क्योंकि यह विवादास्पद है और कुछ परिवारों को आहत कर सकता है","सुनिश्चित करना कि विभिन्न दृष्टिकोणों के साक्ष्यों की जाँच हो और विद्यार्थी अपने विचारों के कारण दें","विद्यार्थियों को बिना साक्ष्य माँगे जो चाहें कहने देना, ताकि सभी सुना हुआ महसूस करें"],"explanationHi":"सामाजिक-वैज्ञानिक मुद्दों के लिए शिक्षक विभिन्न दृष्टिकोणों (किसानों की लागत, वायु गुणवत्ता, स्वास्थ्य) में साक्ष्य-आधारित तर्क को सुगम बनाता है, अपना मत थोपने या दावों को अजाँचा छोड़ने के बजाय।"},
  {"id":"cdp-pedagogy-subjects-910","question":"While teaching the rotation of the earth, a teacher tells Class 7 how Aryabhata proposed that the earth spins on its axis, and how this idea was received and debated in later centuries. This element of the lesson mainly serves:","options":["Ethical validity","Environmental validity","Cognitive validity","Historical validity"],"answer":3,"explanation":"Showing how an idea was proposed, debated and accepted over time gives a historical perspective on science, which is historical validity.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"पृथ्वी के घूर्णन को पढ़ाते हुए एक शिक्षक कक्षा 7 को बताता है कि आर्यभट ने कैसे प्रस्तावित किया कि पृथ्वी अपनी धुरी पर घूमती है, और बाद की शताब्दियों में इस विचार का स्वागत और बहस कैसे हुई। पाठ का यह तत्त्व मुख्यतः किसकी पूर्ति करता है?","optionsHi":["नैतिक वैधता","पर्यावरणीय वैधता","संज्ञानात्मक वैधता","ऐतिहासिक वैधता"],"explanationHi":"यह दिखाना कि कोई विचार समय के साथ कैसे प्रस्तावित, बहसित और स्वीकृत हुआ, विज्ञान का ऐतिहासिक परिप्रेक्ष्य देता है, जो ऐतिहासिक वैधता है।"},
  {"id":"cdp-pedagogy-subjects-911","question":"Before introducing the word 'force', a Class 6 teacher lets students push and pull objects in games such as tug-of-war and football and describe what happens to them. This choice is based mainly on:","options":["Content validity, since force must first be defined accurately before it is used in games","Cognitive validity, since concepts should grow from experiences children can handle","Ethical validity, since team games teach cooperation and fair play","Historical validity, since such games have been played for centuries"],"answer":1,"explanation":"Starting from concrete experience suited to the learner's level before formal terms is the essence of cognitive validity at the upper primary stage.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"‘बल’ शब्द प्रस्तुत करने से पहले कक्षा 6 का एक शिक्षक विद्यार्थियों को रस्साकशी और फुटबॉल जैसे खेलों में वस्तुओं को धकेलने और खींचने देता है और बताने को कहता है कि उनके साथ क्या होता है। यह चुनाव मुख्यतः किस पर आधारित है?","optionsHi":["विषयवस्तु वैधता, क्योंकि खेलों में प्रयोग से पहले बल की सटीक परिभाषा दी जानी चाहिए","संज्ञानात्मक वैधता, क्योंकि संप्रत्यय उन अनुभवों से उगने चाहिए जिन्हें बच्चे सँभाल सकते हैं","नैतिक वैधता, क्योंकि टीम के खेल सहयोग और निष्पक्ष खेल सिखाते हैं","ऐतिहासिक वैधता, क्योंकि ऐसे खेल सदियों से खेले जाते रहे हैं"],"explanationHi":"औपचारिक शब्दों से पहले शिक्षार्थी के स्तर के अनुकूल मूर्त अनुभव से शुरू करना उच्च प्राथमिक स्तर पर संज्ञानात्मक वैधता का सार है।"},
  {"id":"cdp-pedagogy-subjects-912","question":"Which simplified statement for a Class 6 chapter on magnets still keeps content validity?","options":["Magnets attract all metals, such as iron, copper and aluminium, but not plastic or wood.","Magnets attract some materials, such as iron and nickel, but not others, such as copper.","A magnet's attraction works only on objects that are actually touching it.","Breaking a bar magnet in two gives one piece with a north pole and one with a south pole."],"answer":1,"explanation":"A simplification is valid if it is incomplete but not wrong. 'Attracts all metals', 'only on contact' and separate poles on breaking are all common misconceptions; each broken piece has both poles.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा 6 के चुंबकों के अध्याय के लिए कौन-सा सरलीकृत कथन अब भी विषयवस्तु वैधता को बनाए रखता है?","optionsHi":["चुंबक सभी धातुओं, जैसे लोहा, ताँबा और ऐल्युमिनियम को आकर्षित करते हैं, पर प्लास्टिक या लकड़ी को नहीं।","चुंबक कुछ पदार्थों, जैसे लोहा और निकल को आकर्षित करते हैं, पर अन्य, जैसे ताँबे, को नहीं।","चुंबक का आकर्षण केवल उन वस्तुओं पर काम करता है जो वास्तव में उसे छू रही हों।","छड़ चुंबक को दो भागों में तोड़ने पर एक टुकड़ा उत्तरी ध्रुव वाला और एक दक्षिणी ध्रुव वाला मिलता है।"],"explanationHi":"सरलीकरण तब वैध है जब वह अपूर्ण हो पर गलत नहीं। ‘सभी धातुओं को आकर्षित करता है’, ‘केवल संपर्क पर’ और टूटने पर अलग ध्रुव सभी आम भ्रांतियाँ हैं; प्रत्येक टूटे टुकड़े में दोनों ध्रुव होते हैं।"},
  {"id":"cdp-pedagogy-subjects-913","question":"A teacher plans remedial classes for all 'slow learners' in science, giving them the same worksheet without first finding out what each of them finds difficult. The main flaw in this plan is that:","options":["Remedial teaching should be given to all students in the class, not only to slow learners","Worksheets should never be used in remedial teaching, only oral explanation","Remedial teaching must rest on diagnosing each learner's specific difficulties","Slow learners should be taught only through lectures, not through worksheets"],"answer":2,"explanation":"Diagnosis precedes remediation: different learners struggle for different reasons, so a single worksheet may miss their actual difficulties.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"एक शिक्षिका विज्ञान में सभी ‘धीमे सीखने वालों’ के लिए उपचारात्मक कक्षाएँ योजनाबद्ध करती है, उन्हें एक ही कार्यपत्रिका देकर, यह पता लगाए बिना कि उनमें से प्रत्येक को क्या कठिन लगता है। इस योजना की मुख्य कमी यह है कि:","optionsHi":["उपचारात्मक शिक्षण कक्षा के सभी विद्यार्थियों को दिया जाना चाहिए, केवल धीमे सीखने वालों को नहीं","उपचारात्मक शिक्षण में कार्यपत्रिकाओं का कभी प्रयोग नहीं होना चाहिए, केवल मौखिक व्याख्या","उपचारात्मक शिक्षण प्रत्येक शिक्षार्थी की विशिष्ट कठिनाइयों के निदान पर आधारित होना चाहिए","धीमे सीखने वालों को केवल व्याख्यानों से पढ़ाना चाहिए, कार्यपत्रिकाओं से नहीं"],"explanationHi":"निदान उपचार से पहले आता है: अलग-अलग शिक्षार्थी अलग कारणों से संघर्ष करते हैं, इसलिए एक ही कार्यपत्रिका उनकी वास्तविक कठिनाइयों को चूक सकती है।"},
  {"id":"cdp-pedagogy-subjects-914","question":"In a Class 7 class, students who understood the concept of conduction explain it to classmates who are struggling, using their own words and examples. As a remedial strategy this is useful mainly because:","options":["It lets the teacher rest while students take charge of teaching each other","It is the only practical way to deal with very large classes in schools","It removes the need for the teacher to diagnose each struggling learner's difficulties","Peers often explain in words and examples closer to struggling learners' thinking"],"answer":3,"explanation":"Peer tutoring works partly because peers share a similar frame of reference; it also deepens the tutor's own understanding. It complements, not replaces, the teacher's diagnosis.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा 7 की एक कक्षा में जिन विद्यार्थियों ने चालन की अवधारणा समझ ली है, वे संघर्ष कर रहे सहपाठियों को अपने शब्दों और उदाहरणों से उसे समझाते हैं। उपचारात्मक युक्ति के रूप में यह मुख्यतः उपयोगी इसलिए है कि:","optionsHi":["यह शिक्षक को आराम करने देता है जबकि विद्यार्थी एक-दूसरे को पढ़ाने का भार सँभालते हैं","विद्यालयों में बहुत बड़ी कक्षाओं से निपटने का यही एकमात्र व्यावहारिक तरीका है","यह शिक्षक के लिए हर संघर्ष कर रहे शिक्षार्थी की कठिनाइयों का निदान करने की आवश्यकता समाप्त कर देता है","साथी अक्सर ऐसे शब्दों और उदाहरणों में समझाते हैं जो संघर्ष कर रहे शिक्षार्थियों की सोच के अधिक निकट होते हैं"],"explanationHi":"सहपाठी-शिक्षण इसलिए भी काम करता है कि साथियों का संदर्भ-ढाँचा समान होता है; यह शिक्षक की अपनी समझ को भी गहरा करता है। यह शिक्षक के निदान का पूरक है, उसका स्थान नहीं लेता।"},
  {"id":"cdp-pedagogy-subjects-915","question":"Assertion (A): A well-designed open-book test in science can assess higher-order thinking. Reason (R): Its questions require students to apply and analyse information rather than simply locate it in the book.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because the information is available, a well-designed open-book test must ask students to use it, which is what lets it assess application and analysis rather than recall.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"अभिकथन (A): विज्ञान में एक सुअभिकल्पित खुली-पुस्तक परीक्षा उच्च-स्तरीय चिंतन का आकलन कर सकती है। कारण (R): उसके प्रश्न विद्यार्थियों से जानकारी को केवल पुस्तक में खोजने के बजाय उसे लागू करने और विश्लेषित करने को कहते हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"क्योंकि जानकारी उपलब्ध है, सुअभिकल्पित खुली-पुस्तक परीक्षा को विद्यार्थियों से उसका उपयोग करवाना होता है, जो उसे स्मरण के बजाय अनुप्रयोग और विश्लेषण का आकलन करने देता है।"},
  {"id":"cdp-pedagogy-subjects-916","question":"A teacher asks Class 8 students to design a method of keeping drinking water cool in summer without a refrigerator, using only local materials. In the revised Bloom's taxonomy, this task is mainly at the level of:","options":["Remembering","Applying","Creating","Understanding"],"answer":2,"explanation":"Designing a new product or plan is creating, the highest level of the revised taxonomy. Applying would be using a known procedure in a familiar situation.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"एक शिक्षक कक्षा 8 के विद्यार्थियों से केवल स्थानीय सामग्री का उपयोग करके गर्मियों में बिना रेफ्रिजरेटर के पीने के पानी को ठंडा रखने की विधि बनाने को कहता है। ब्लूम के संशोधित वर्गीकरण में यह कार्य मुख्यतः किस स्तर का है?","optionsHi":["याद करना","अनुप्रयोग","सृजन","समझना"],"explanationHi":"किसी नए उत्पाद या योजना का अभिकल्पन सृजन है, जो संशोधित वर्गीकरण का उच्चतम स्तर है। अनुप्रयोग किसी परिचित स्थिति में ज्ञात प्रक्रिया का उपयोग होता।"},
  {"id":"cdp-pedagogy-subjects-917","question":"A teacher shows a magnet picking up iron nails, pins and a steel spoon, and the class concludes that 'magnets attract all metals'. What should the teacher have done to prevent this over-generalisation?","options":["Used a stronger magnet, so that the attraction was clearer to the whole class","Included non-examples such as a copper coin, aluminium foil and a brass key","Told students the definition of magnetic materials before the demonstration","Shown more iron objects, so that the pattern was clearer and more convincing"],"answer":1,"explanation":"Concepts form from both examples and non-examples. Showing only iron-based objects invites the wrong rule; non-magnetic metals mark the true boundary of the concept.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs","questionHi":"एक शिक्षक चुंबक को लोहे की कीलें, पिनें और स्टील का चम्मच उठाते हुए दिखाता है, और कक्षा निष्कर्ष निकालती है कि ‘चुंबक सभी धातुओं को आकर्षित करते हैं’। इस अति-सामान्यीकरण को रोकने के लिए शिक्षक को क्या करना चाहिए था?","optionsHi":["अधिक शक्तिशाली चुंबक प्रयोग करना, ताकि पूरी कक्षा को आकर्षण अधिक स्पष्ट हो","ताँबे का सिक्का, ऐल्युमिनियम की पन्नी और पीतल की चाबी जैसे गैर-उदाहरण शामिल करना","प्रदर्शन से पहले विद्यार्थियों को चुंबकीय पदार्थों की परिभाषा बताना","और अधिक लोहे की वस्तुएँ दिखाना, ताकि पैटर्न अधिक स्पष्ट और विश्वसनीय हो"],"explanationHi":"संप्रत्यय उदाहरणों और गैर-उदाहरणों दोनों से बनते हैं। केवल लोहे पर आधारित वस्तुएँ दिखाना गलत नियम को आमंत्रित करता है; अचुंबकीय धातुएँ संप्रत्यय की वास्तविक सीमा चिह्नित करती हैं।"},
  {"id":"cdp-pedagogy-subjects-918","question":"A Class 6 teacher wants her students to classify materials around them. Which instruction best develops the skill of classification?","options":["Copy the table of materials from the textbook and learn the groups it shows","Group the objects any way you like, name the property used, then regroup by another","Put all the shiny objects in one place and all the dull objects in another","Write the names of ten materials found at home and say what each one of them is used for"],"answer":1,"explanation":"Real classification means choosing a property, grouping consistently by it, and seeing that the same objects can be grouped differently by different properties. Copying or following a single given rule does not develop the skill.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा 6 की एक शिक्षिका चाहती है कि उसके विद्यार्थी अपने आसपास के पदार्थों का वर्गीकरण करें। कौन-सा निर्देश वर्गीकरण के कौशल को सबसे अच्छी तरह विकसित करता है?","optionsHi":["पाठ्यपुस्तक से पदार्थों की सारणी उतारो और उसमें दिखाए समूह सीख लो","वस्तुओं को जैसे चाहो वैसे समूहबद्ध करो, प्रयुक्त गुण का नाम बताओ, फिर किसी दूसरे गुण से पुनः समूहबद्ध करो","सभी चमकीली वस्तुओं को एक जगह और सभी फीकी वस्तुओं को दूसरी जगह रखो","घर में पाए जाने वाले दस पदार्थों के नाम लिखो और बताओ कि उनमें से प्रत्येक किस काम आता है"],"explanationHi":"वास्तविक वर्गीकरण का अर्थ है कोई गुण चुनना, उसके अनुसार संगत रूप से समूह बनाना, और देखना कि वही वस्तुएँ अलग-अलग गुणों से अलग तरह समूहबद्ध हो सकती हैं। उतारना या कोई एक दिया नियम मानना कौशल विकसित नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-919","question":"While teaching sources of energy, a teacher asks students to survey which fuels are used in their homes, why, and with what effects on health and money, and then to discuss what alternatives are available locally. This approach is best called:","options":["Lecture-cum-demonstration approach","Rote memorisation approach","Programmed instruction approach","Science-Technology-Society approach"],"answer":3,"explanation":"Starting from a real-life issue in the learners' community and linking scientific ideas to technology and social effects is the STS approach.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"ऊर्जा के स्रोत पढ़ाते हुए एक शिक्षक विद्यार्थियों से सर्वेक्षण करवाता है कि उनके घरों में कौन-से ईंधन प्रयोग होते हैं, क्यों, और स्वास्थ्य तथा पैसे पर क्या प्रभाव पड़ते हैं, और फिर स्थानीय रूप से उपलब्ध विकल्पों पर चर्चा करवाता है। इस उपागम को सबसे अच्छी तरह क्या कहा जाता है?","optionsHi":["व्याख्यान-सह-प्रदर्शन उपागम","रटंत उपागम","अभिक्रमित अनुदेशन उपागम","विज्ञान-प्रौद्योगिकी-समाज उपागम"],"explanationHi":"शिक्षार्थियों के समुदाय के किसी वास्तविक मुद्दे से शुरू करना और वैज्ञानिक विचारों को प्रौद्योगिकी और सामाजिक प्रभावों से जोड़ना STS उपागम है।"},
  {"id":"cdp-pedagogy-subjects-920","question":"A teacher notices that in her classes, the same three students answer every question while the rest stay silent. Which strategy is most likely to involve the whole class in thinking about a science question?","options":["Asking only the three students, since they usually know the answers","Letting students think alone, discuss in pairs, then share with the class","Asking the question and then answering it herself after a short pause","Punishing students who do not answer, so that all of them pay closer attention"],"answer":1,"explanation":"Think-pair-share gives every student time to think and a low-risk chance to voice ideas before speaking to the whole class. Relying on volunteers or punishment shrinks participation.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"एक शिक्षिका देखती है कि उसकी कक्षाओं में वही तीन विद्यार्थी हर प्रश्न का उत्तर देते हैं जबकि बाकी चुप रहते हैं। विज्ञान के प्रश्न के बारे में सोचने में पूरी कक्षा को शामिल करने की सबसे अधिक संभावना किस युक्ति में है?","optionsHi":["केवल उन तीन विद्यार्थियों से पूछना, क्योंकि उन्हें आमतौर पर उत्तर पता होते हैं","विद्यार्थियों को अकेले सोचने देना, जोड़ों में चर्चा करने देना, फिर कक्षा के साथ साझा करने देना","प्रश्न पूछना और थोड़े ठहराव के बाद स्वयं उत्तर दे देना","उत्तर न देने वाले विद्यार्थियों को दंड देना, ताकि वे सभी अधिक ध्यान दें"],"explanationHi":"सोचो-जोड़ी बनाओ-साझा करो (Think-pair-share) हर विद्यार्थी को सोचने का समय और पूरी कक्षा से बोलने से पहले विचार रखने का कम जोखिम वाला अवसर देता है। स्वयंसेवकों पर निर्भर रहना या दंड देना भागीदारी घटाता है।"},
  {"id":"cdp-pedagogy-subjects-921","question":"A student says that a bigger magnet is always stronger than a smaller one. The best way to address this is to:","options":["Agree with the student, since size and strength of magnets generally go together","Tell the student to read the chapter on magnets again more carefully","Have students compare how many pins magnets of different sizes and kinds can lift","Show the student a picture of a large magnet lifting a heavy load"],"answer":2,"explanation":"Testing the claim with evidence, for instance a small strong magnet lifting more pins than a large weak one, lets students discover that strength does not depend on size alone.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"एक विद्यार्थी कहता है कि बड़ा चुंबक हमेशा छोटे चुंबक से अधिक शक्तिशाली होता है। इसे संबोधित करने का सबसे अच्छा तरीका है:","optionsHi":["विद्यार्थी से सहमत होना, क्योंकि चुंबकों का आकार और शक्ति सामान्यतः साथ चलते हैं","विद्यार्थी से चुंबकों का अध्याय और ध्यान से फिर पढ़ने को कहना","विद्यार्थियों से अलग-अलग आकार और प्रकार के चुंबकों द्वारा उठाई जा सकने वाली पिनों की संख्या की तुलना करवाना","विद्यार्थी को भारी भार उठाते बड़े चुंबक का चित्र दिखाना"],"explanationHi":"दावे को साक्ष्य से परखना, जैसे छोटे शक्तिशाली चुंबक का बड़े कमज़ोर चुंबक से अधिक पिनें उठाना, विद्यार्थियों को खोजने देता है कि शक्ति केवल आकार पर निर्भर नहीं करती।"},
  {"id":"cdp-pedagogy-subjects-922","question":"Consider these practices of a Class 7 science teacher. 1. She asks students to explain their reasoning even when their answer is correct. 2. She treats wrong answers as clues to students' thinking. 3. She tells students that every question has exactly one right answer given in the textbook. 4. She encourages students to question each other's explanations politely. Which practices support conceptual understanding?","options":["1, 2 and 4 only","1 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"Asking for reasoning, using errors diagnostically and encouraging respectful argument all help build understanding. Treating the textbook as the only authority discourages thinking.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा 7 की एक विज्ञान शिक्षिका के इन अभ्यासों पर विचार कीजिए। 1. वह विद्यार्थियों से उत्तर सही होने पर भी अपना तर्क समझाने को कहती है। 2. वह गलत उत्तरों को विद्यार्थियों की सोच के संकेत मानती है। 3. वह विद्यार्थियों को बताती है कि हर प्रश्न का ठीक एक सही उत्तर होता है जो पाठ्यपुस्तक में दिया है। 4. वह विद्यार्थियों को एक-दूसरे की व्याख्याओं पर शिष्टता से प्रश्न उठाने को प्रोत्साहित करती है। कौन-से अभ्यास अवधारणात्मक समझ का समर्थन करते हैं?","optionsHi":["केवल 1, 2 और 4","केवल 1 और 3","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"तर्क माँगना, त्रुटियों का निदानात्मक उपयोग और सम्मानजनक तर्क-वितर्क को प्रोत्साहित करना, सभी समझ बनाने में मदद करते हैं। पाठ्यपुस्तक को एकमात्र प्राधिकार मानना चिंतन को हतोत्साहित करता है।"},
  {"id":"cdp-pedagogy-subjects-923","question":"A Class 8 teacher finds that students easily state that 'friction opposes motion' but believe that friction is always harmful. Which teaching move best corrects the second idea?","options":["Repeating the definition of friction several times until students know it well","Listing ways to reduce friction in machines, such as oiling and ball bearings","Telling students to memorise a list of the advantages of friction for the coming unit test","Let students walk on a soapy floor and write on glass, and discuss what friction allows"],"answer":3,"explanation":"Experiencing how hard walking and writing become with little friction shows that friction is necessary as well as wasteful. Memorised lists rarely change a belief.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"कक्षा 8 की एक शिक्षिका पाती है कि विद्यार्थी आसानी से कह देते हैं कि ‘घर्षण गति का विरोध करता है’ पर मानते हैं कि घर्षण हमेशा हानिकारक होता है। दूसरे विचार को कौन-सा शिक्षण कदम सबसे अच्छी तरह सुधारता है?","optionsHi":["घर्षण की परिभाषा कई बार दोहराना जब तक विद्यार्थी उसे अच्छी तरह न जान लें","मशीनों में घर्षण घटाने के तरीकों की सूची बनाना, जैसे तेल लगाना और बॉल बेयरिंग","विद्यार्थियों से आगामी इकाई परीक्षा के लिए घर्षण के लाभों की सूची रटने को कहना","विद्यार्थियों को साबुन वाले फ़र्श पर चलने और काँच पर लिखने देना, और चर्चा करना कि घर्षण क्या संभव बनाता है"],"explanationHi":"यह अनुभव करना कि कम घर्षण के साथ चलना और लिखना कितना कठिन हो जाता है, दिखाता है कि घर्षण आवश्यक भी है और अपव्ययी भी। रटी हुई सूचियाँ विश्वास को कम ही बदलती हैं।"},
  {"id":"cdp-pedagogy-subjects-924","question":"A science teacher wants to judge whether her students can transfer the idea of conduction to new situations. Which question is most suitable?","options":["Define conduction and give one example of it from the textbook.","Name two good conductors and two poor conductors of heat.","Why do cooks hold a hot pan with a folded cloth rather than with bare hands?","Draw a labelled diagram showing conduction of heat in a metal rod."],"answer":2,"explanation":"Explaining an unfamiliar, everyday case requires students to apply the concept (cloth is a poor conductor, so it slows heat flow to the hand). Definitions, lists and textbook diagrams can be recalled.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"एक विज्ञान शिक्षिका परखना चाहती है कि उसके विद्यार्थी चालन के विचार को नई स्थितियों में स्थानांतरित कर सकते हैं या नहीं। कौन-सा प्रश्न सबसे उपयुक्त है?","optionsHi":["चालन की परिभाषा दीजिए और पाठ्यपुस्तक से उसका एक उदाहरण दीजिए।","ऊष्मा के दो अच्छे चालकों और दो अचालकों के नाम बताइए।","रसोइए गर्म तवे को खाली हाथों के बजाय तह किए कपड़े से क्यों पकड़ते हैं?","धातु की छड़ में ऊष्मा के चालन को दर्शाने वाला नामांकित आरेख बनाइए।"],"explanationHi":"किसी अपरिचित, रोज़मर्रा की स्थिति की व्याख्या के लिए विद्यार्थियों को संप्रत्यय लागू करना पड़ता है (कपड़ा कुचालक है, इसलिए हाथ तक ऊष्मा का प्रवाह धीमा करता है)। परिभाषाएँ, सूचियाँ और पाठ्यपुस्तक के आरेख याद किए जा सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-925","question":"After studying two water-saving schemes in their village, Class VII students in Sikar are asked: 'Which of the two schemes would you recommend to the gram panchayat, and why?' In Bloom's revised taxonomy, this question is mainly at the level of:","options":["Analyse","Create","Apply","Evaluate"],"answer":3,"explanation":"Judging between options against criteria and justifying a recommendation is Evaluate. Analysing would stop at breaking the schemes into parts and comparing them; nothing new is being designed, so it is not Create.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"अपने गाँव की दो जल-बचत योजनाओं का अध्ययन करने के बाद सीकर के कक्षा VII के विद्यार्थियों से पूछा जाता है: ‘दोनों योजनाओं में से आप ग्राम पंचायत को किसकी अनुशंसा करेंगे, और क्यों?’ ब्लूम के संशोधित वर्गीकरण में यह प्रश्न मुख्यतः किस स्तर का है?","optionsHi":["विश्लेषण","सृजन","अनुप्रयोग","मूल्यांकन"],"explanationHi":"मानदंडों के आधार पर विकल्पों के बीच निर्णय करना और अनुशंसा को उचित ठहराना मूल्यांकन है। विश्लेषण योजनाओं को भागों में तोड़ने और तुलना करने तक रुकता; कुछ नया डिज़ाइन नहीं हो रहा, इसलिए यह सृजन नहीं है।"},
  {"id":"cdp-pedagogy-subjects-926","question":"A Class V teacher asks four questions about a fable: P. 'Write a new ending in which the crow outsmarts the fox.' Q. 'Was it fair of the fox to trick the crow? Give reasons.' R. 'How are the fox's reasons for flattering different from the crow's reasons for singing?' S. 'What was the crow holding in its beak?' Arrange them from the lowest to the highest level of Bloom's revised taxonomy.","options":["S, R, Q, P","S, Q, R, P","S, R, P, Q","R, S, Q, P"],"answer":0,"explanation":"S is Remember, R is Analyse (comparing motives), Q is Evaluate (judging fairness) and P is Create (producing something new). In the revised taxonomy Create sits above Evaluate.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा V की एक शिक्षिका एक दंतकथा पर चार प्रश्न पूछती है: P. ‘एक नया अंत लिखो जिसमें कौआ लोमड़ी को मात दे।’ Q. ‘क्या लोमड़ी का कौए को धोखा देना उचित था? कारण दो।’ R. ‘लोमड़ी के चापलूसी के कारण कौए के गाने के कारणों से कैसे भिन्न हैं?’ S. ‘कौए की चोंच में क्या था?’ इन्हें ब्लूम के संशोधित वर्गीकरण के निम्नतम से उच्चतम स्तर के क्रम में लगाइए।","optionsHi":["S, R, Q, P","S, Q, R, P","S, R, P, Q","R, S, Q, P"],"explanationHi":"S याद करना है, R विश्लेषण (उद्देश्यों की तुलना), Q मूल्यांकन (निष्पक्षता का निर्णय) और P सृजन (कुछ नया रचना) है। संशोधित वर्गीकरण में सृजन मूल्यांकन से ऊपर है।"},
  {"id":"cdp-pedagogy-subjects-927","question":"Consider the following statements about the revision of Bloom's taxonomy by Anderson and Krathwohl (2001): 1. The cognitive categories are named with verbs such as remember, understand and apply. 2. Synthesis was renamed Create and placed at the highest level, above Evaluate. 3. A separate knowledge dimension was added with factual, conceptual, procedural and metacognitive knowledge. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 and 3 only"],"answer":2,"explanation":"All three are features of the revised taxonomy: nouns became verbs, Create replaced Synthesis at the top, and the two-dimensional taxonomy table pairs cognitive processes with four types of knowledge.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"एंडरसन और क्रैथवोल (2001) द्वारा ब्लूम के वर्गीकरण के संशोधन के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. संज्ञानात्मक श्रेणियों को याद करना, समझना और अनुप्रयोग जैसी क्रियाओं से नाम दिया गया है। 2. संश्लेषण का नाम बदलकर सृजन कर दिया गया और उसे मूल्यांकन के ऊपर उच्चतम स्तर पर रखा गया। 3. तथ्यात्मक, संप्रत्ययात्मक, प्रक्रियात्मक और अधिबोधात्मक ज्ञान के साथ एक अलग ज्ञान आयाम जोड़ा गया। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","1, 2 और 3","केवल 1 और 3"],"explanationHi":"तीनों संशोधित वर्गीकरण की विशेषताएँ हैं: संज्ञाएँ क्रियाएँ बनीं, सृजन ने संश्लेषण की जगह शीर्ष पर ली, और द्विआयामी वर्गीकरण सारणी संज्ञानात्मक प्रक्रियाओं को चार प्रकार के ज्ञान से जोड़ती है।"},
  {"id":"cdp-pedagogy-subjects-928","question":"While revising for a test, Class VIII student Tanvi realises, 'I always mix up area and perimeter, so I will check the units of every answer before writing it.' In the knowledge dimension of Bloom's revised taxonomy, this is an example of:","options":["Procedural knowledge","Metacognitive knowledge","Conceptual knowledge","Factual knowledge"],"answer":1,"explanation":"Knowing one's own typical errors and choosing a strategy to monitor them is metacognitive knowledge. The checking steps might look procedural, but the source is awareness of her own thinking.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"परीक्षा की तैयारी करते हुए कक्षा VIII की विद्यार्थी तन्वी को एहसास होता है, ‘मैं हमेशा क्षेत्रफल और परिमाप को उलझा देती हूँ, इसलिए लिखने से पहले हर उत्तर की इकाइयाँ जाँचूँगी।’ ब्लूम के संशोधित वर्गीकरण के ज्ञान आयाम में यह किसका उदाहरण है?","optionsHi":["प्रक्रियात्मक ज्ञान","अधिबोधात्मक ज्ञान","संप्रत्ययात्मक ज्ञान","तथ्यात्मक ज्ञान"],"explanationHi":"अपनी विशिष्ट त्रुटियों को जानना और उनकी निगरानी के लिए युक्ति चुनना अधिबोधात्मक ज्ञान है। जाँचने के चरण प्रक्रियात्मक लग सकते हैं, पर स्रोत उसकी अपनी सोच की जागरूकता है।"},
  {"id":"cdp-pedagogy-subjects-929","question":"A Class VI task says: 'Use the steps of long division to divide 4,356 by 12.' In the two-dimensional table of Bloom's revised taxonomy, this task fits best at:","options":["Understand x Conceptual knowledge","Remember x Factual knowledge","Analyse x Procedural knowledge","Apply x Procedural knowledge"],"answer":3,"explanation":"Carrying out a known algorithm on a familiar type of problem is Apply (executing), and the knowledge involved is the method itself, which is procedural.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VI का एक कार्य कहता है: ‘4,356 को 12 से भाग देने के लिए लंबे भाग के चरणों का प्रयोग कीजिए।’ ब्लूम के संशोधित वर्गीकरण की द्विआयामी सारणी में यह कार्य सबसे अच्छी तरह कहाँ बैठता है?","optionsHi":["समझना x संप्रत्ययात्मक ज्ञान","याद करना x तथ्यात्मक ज्ञान","विश्लेषण x प्रक्रियात्मक ज्ञान","अनुप्रयोग x प्रक्रियात्मक ज्ञान"],"explanationHi":"किसी परिचित प्रकार की समस्या पर ज्ञात कलन-विधि का निष्पादन अनुप्रयोग (executing) है, और इसमें शामिल ज्ञान स्वयं विधि है, जो प्रक्रियात्मक है।"},
  {"id":"cdp-pedagogy-subjects-930","question":"Assertion (A): After asking a thinking question, a teacher should wait at least three seconds before calling on a student. Reason (R): Longer wait time has been found to increase the length and quality of student answers and the number of students who respond.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Mary Budd Rowe's research on wait time found that pausing about three seconds or more produced longer, better-reasoned answers and more participation; that is the reason for A.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"अभिकथन (A): चिंतन-प्रश्न पूछने के बाद शिक्षक को किसी विद्यार्थी को बुलाने से पहले कम से कम तीन सेकंड प्रतीक्षा करनी चाहिए। कारण (R): यह पाया गया है कि लंबा प्रतीक्षा-समय विद्यार्थियों के उत्तरों की लंबाई और गुणवत्ता तथा उत्तर देने वाले विद्यार्थियों की संख्या बढ़ाता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"मैरी बड रोव के प्रतीक्षा-समय पर शोध ने पाया कि लगभग तीन सेकंड या अधिक रुकने से लंबे, बेहतर तर्कयुक्त उत्तर और अधिक भागीदारी मिली; यही A का कारण है।"},
  {"id":"cdp-pedagogy-subjects-931","question":"After a Class IV child answers, the teacher does not immediately say 'Good' or 'Wrong' but pauses silently for a few seconds. The child then adds an example, and another child builds on it. What is this pause called and what does it achieve?","options":["Wait time after the question; it gives children time to frame an answer before anyone is called","Planned ignoring; it discourages children from giving attention-seeking answers","Wait time after the response (wait time II); it invites elaboration and lets others respond","Redirecting; it shifts the question silently to another student to answer"],"answer":2,"explanation":"Wait time II is the pause after a student's answer; it keeps thinking open so the student elaborates and peers join in. Wait time I is the pause after the teacher's question.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा IV के बच्चे के उत्तर देने के बाद शिक्षक तुरंत ‘अच्छा’ या ‘गलत’ नहीं कहता बल्कि कुछ सेकंड चुपचाप रुकता है। बच्चा फिर एक उदाहरण जोड़ता है, और एक दूसरा बच्चा उस पर आगे बढ़ता है। इस ठहराव को क्या कहते हैं और यह क्या हासिल करता है?","optionsHi":["प्रश्न के बाद का प्रतीक्षा-समय; यह बच्चों को किसी को बुलाए जाने से पहले उत्तर बनाने का समय देता है","नियोजित अनदेखी; यह बच्चों को ध्यान आकर्षित करने वाले उत्तर देने से हतोत्साहित करती है","उत्तर के बाद का प्रतीक्षा-समय (प्रतीक्षा-समय II); यह विस्तार को आमंत्रित करता है और दूसरों को प्रतिक्रिया देने देता है","पुनर्निर्देशन; यह प्रश्न को चुपचाप किसी अन्य विद्यार्थी को उत्तर देने के लिए बदल देता है"],"explanationHi":"प्रतीक्षा-समय II विद्यार्थी के उत्तर के बाद का ठहराव है; यह सोच को खुला रखता है ताकि विद्यार्थी विस्तार करे और साथी जुड़ें। प्रतीक्षा-समय I शिक्षक के प्रश्न के बाद का ठहराव है।"},
  {"id":"cdp-pedagogy-subjects-932","question":"Which of these questions in a Class V EVS lesson is most clearly a divergent question?","options":["Which gas do plants take in from the air during photosynthesis?","What might happen to our town if all the roadside trees were cut down?","How many legs does an insect have, and how many body parts?","Name the river that flows through our city and where it begins."],"answer":1,"explanation":"Divergent questions have many acceptable answers and invite imagination and reasoning about possibilities. The others have one correct answer and are convergent.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा V के EVS पाठ में इनमें से कौन-सा प्रश्न सबसे स्पष्ट रूप से अपसारी प्रश्न है?","optionsHi":["प्रकाश संश्लेषण के दौरान पौधे हवा से कौन-सी गैस लेते हैं?","यदि सड़क किनारे के सभी पेड़ काट दिए जाएँ तो हमारे कस्बे का क्या हो सकता है?","एक कीट के कितने पैर होते हैं, और शरीर के कितने भाग होते हैं?","हमारे शहर से बहने वाली नदी का नाम बताइए और वह कहाँ से शुरू होती है।"],"explanationHi":"अपसारी प्रश्नों के अनेक स्वीकार्य उत्तर होते हैं और वे संभावनाओं के बारे में कल्पना और तर्क को आमंत्रित करते हैं। अन्य का एक ही सही उत्तर है और वे अभिसारी हैं।"},
  {"id":"cdp-pedagogy-subjects-933","question":"Match each teacher move with the questioning technique it shows. P. 'Can you tell me more about why you think so?' Q. 'Neha, do you agree with Ravi's answer?' R. 'Think about what happens to ice when you keep it in the sun...' S. Asking the question to the whole class, pausing, and only then naming a student. Techniques: 1. Prompting; 2. Probing; 3. Redirecting; 4. Pose-pause-pick (keeping the whole group alert).","options":["P-1, Q-3, R-2, S-4","P-2, Q-4, R-1, S-3","P-3, Q-2, R-1, S-4","P-2, Q-3, R-1, S-4"],"answer":3,"explanation":"Probing pushes a student to go deeper, redirecting passes the question to another student, prompting gives a hint to a stuck student, and pose-pause-pick keeps everyone thinking until a name is called.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"प्रत्येक शिक्षक-कदम का मिलान उस प्रश्न-तकनीक से कीजिए जो वह दर्शाता है। P. ‘क्या तुम मुझे और बता सकते हो कि तुम ऐसा क्यों सोचते हो?’ Q. ‘नेहा, क्या तुम रवि के उत्तर से सहमत हो?’ R. ‘सोचो कि जब तुम बर्फ़ को धूप में रखते हो तो उसका क्या होता है...’ S. प्रश्न पूरी कक्षा से पूछना, ठहरना, और तभी किसी विद्यार्थी का नाम लेना। तकनीकें: 1. संकेत देना (Prompting); 2. गहराई से जाँचना (Probing); 3. पुनर्निर्देशन (Redirecting); 4. प्रश्न-ठहराव-चयन (पूरे समूह को सतर्क रखना)।","optionsHi":["P-1, Q-3, R-2, S-4","P-2, Q-4, R-1, S-3","P-3, Q-2, R-1, S-4","P-2, Q-3, R-1, S-4"],"explanationHi":"गहराई से जाँचना विद्यार्थी को और गहरे जाने को प्रेरित करता है, पुनर्निर्देशन प्रश्न को दूसरे विद्यार्थी को देता है, संकेत देना अटके विद्यार्थी को सुराग देता है, और प्रश्न-ठहराव-चयन नाम लिए जाने तक सबको सोचते रखता है।"},
  {"id":"cdp-pedagogy-subjects-934","question":"A Class VI teacher usually says the student's name first and then the question: 'Rahul, what is the capital of Odisha?' Why is this a weaker practice than asking the question first?","options":["Naming a student first tells the rest they are not being asked, so they may stop thinking","It is impolite to use a student's name in class before asking a question","It makes the question too easy for the named student, who gets extra time","It takes longer than asking the question first, which wastes class time"],"answer":0,"explanation":"Posing the question to all, pausing and then naming someone keeps every student mentally engaged. Naming first lets everyone else switch off.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VI का एक शिक्षक आमतौर पर पहले विद्यार्थी का नाम और फिर प्रश्न बोलता है: ‘राहुल, ओडिशा की राजधानी क्या है?’ यह प्रश्न पहले पूछने से कमज़ोर अभ्यास क्यों है?","optionsHi":["पहले विद्यार्थी का नाम लेना बाकी को बताता है कि उनसे नहीं पूछा जा रहा, इसलिए वे सोचना बंद कर सकते हैं","प्रश्न पूछने से पहले कक्षा में विद्यार्थी का नाम लेना अशिष्ट है","यह नामित विद्यार्थी के लिए प्रश्न को बहुत आसान बना देता है, जिसे अतिरिक्त समय मिलता है","यह प्रश्न पहले पूछने से अधिक समय लेता है, जो कक्षा का समय बर्बाद करता है"],"explanationHi":"प्रश्न सबसे पूछना, ठहरना और फिर किसी का नाम लेना हर विद्यार्थी को मानसिक रूप से संलग्न रखता है। पहले नाम लेने से बाकी सब बंद हो जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-935","question":"In a Class IV English lesson, which teacher question is a referential question that invites real communication rather than a display question?","options":["'What colour is the bus in the picture?'","'What is the past tense of go?'","'What did you do with your family last Sunday?'","'Who wrote this poem? It is written below the title.'"],"answer":2,"explanation":"A referential question asks for information the teacher does not already know, so the child has something real to say. Display questions only check known answers.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा IV के अंग्रेज़ी पाठ में शिक्षक का कौन-सा प्रश्न संदर्भात्मक प्रश्न है जो प्रदर्शन-प्रश्न के बजाय वास्तविक संप्रेषण को आमंत्रित करता है?","optionsHi":["‘चित्र में बस का रंग क्या है?’","‘go का भूतकाल क्या है?’","‘पिछले रविवार को तुमने अपने परिवार के साथ क्या किया?’","‘यह कविता किसने लिखी? यह शीर्षक के नीचे लिखा है।’"],"explanationHi":"संदर्भात्मक प्रश्न ऐसी जानकारी माँगता है जो शिक्षक को पहले से नहीं पता, इसलिए बच्चे के पास कहने को कुछ वास्तविक होता है। प्रदर्शन-प्रश्न केवल ज्ञात उत्तरों की जाँच करते हैं।"},
  {"id":"cdp-pedagogy-subjects-936","question":"A Class VII teacher writes a test item: 'List three differences between a plant cell and an animal cell.' The three differences were listed in a table in the textbook and copied in notes. At which level of Bloom's revised taxonomy is this item really working?","options":["Analyse, because students must compare two kinds of cells and find differences","Remember, because students only recall a list they have already studied","Evaluate, because students must judge which differences are the most important","Create, because students produce their own list of differences in the answer"],"answer":1,"explanation":"The level of a question depends on what students must actually do; if the comparison was already made and taught, recalling it is Remember. It would be Analyse only if students had to work out the differences themselves.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VII की एक शिक्षिका परीक्षा-प्रश्न लिखती है: ‘पादप कोशिका और जंतु कोशिका के बीच तीन अंतर सूचीबद्ध कीजिए।’ तीनों अंतर पाठ्यपुस्तक की सारणी में सूचीबद्ध थे और नोट्स में उतारे गए थे। ब्लूम के संशोधित वर्गीकरण के किस स्तर पर यह प्रश्न वास्तव में काम कर रहा है?","optionsHi":["विश्लेषण, क्योंकि विद्यार्थियों को दो प्रकार की कोशिकाओं की तुलना करनी है और अंतर खोजने हैं","याद करना, क्योंकि विद्यार्थी केवल उस सूची को याद करते हैं जिसे वे पहले पढ़ चुके हैं","मूल्यांकन, क्योंकि विद्यार्थियों को निर्णय करना है कि कौन-से अंतर सबसे महत्त्वपूर्ण हैं","सृजन, क्योंकि विद्यार्थी उत्तर में अंतरों की अपनी सूची बनाते हैं"],"explanationHi":"प्रश्न का स्तर इस पर निर्भर करता है कि विद्यार्थियों को वास्तव में क्या करना है; यदि तुलना पहले ही की और पढ़ाई जा चुकी है, तो उसे याद करना ‘याद करना’ है। यह विश्लेषण तभी होता जब विद्यार्थियों को अंतर स्वयं निकालने पड़ते।"},
  {"id":"cdp-pedagogy-subjects-937","question":"A Class VIII science teacher gives this task: 'Plan an experiment to find out whether the amount of sunlight affects how fast moong seeds sprout. Say what you will change, what you will keep the same and what you will measure.' At which level of Bloom's revised taxonomy is this task?","options":["Create","Apply","Understand","Remember"],"answer":0,"explanation":"Designing an investigation that did not exist before is planning, which falls under Create. It is not just Apply, because students are not carrying out a given procedure but devising one.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VIII का एक विज्ञान शिक्षक यह कार्य देता है: ‘यह पता लगाने के लिए प्रयोग की योजना बनाइए कि सूर्य के प्रकाश की मात्रा मूँग के बीजों के अंकुरित होने की गति को प्रभावित करती है या नहीं। बताइए कि आप क्या बदलेंगे, क्या समान रखेंगे और क्या मापेंगे।’ ब्लूम के संशोधित वर्गीकरण के किस स्तर का यह कार्य है?","optionsHi":["सृजन","अनुप्रयोग","समझना","याद करना"],"explanationHi":"ऐसी जाँच का अभिकल्पन करना जो पहले नहीं थी, योजना बनाना है, जो सृजन के अंतर्गत आता है। यह केवल अनुप्रयोग नहीं है, क्योंकि विद्यार्थी दी गई प्रक्रिया नहीं कर रहे बल्कि उसे बना रहे हैं।"},
  {"id":"cdp-pedagogy-subjects-938","question":"A Class VII student says that heavier objects always fall faster. Instead of correcting him, the teacher asks: 'If you tie a heavy stone and a light stone together, should the pair fall faster or slower than the heavy stone alone? Why?' What is the main purpose of this style of questioning?","options":["To embarrass the student into silence so that the lesson can continue as planned","To check whether the student remembers the textbook definition and the law of gravity","To lead the student to examine his own assumption and find the contradiction in it","To redirect the question to another student who may know the correct answer"],"answer":2,"explanation":"Socratic questioning uses a chain of questions that makes the learner test his belief and notice where it breaks, so understanding is built rather than told. It is not a recall check or a redirection.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VII का एक विद्यार्थी कहता है कि भारी वस्तुएँ हमेशा तेज़ गिरती हैं। उसे सुधारने के बजाय शिक्षक पूछता है: ‘यदि तुम एक भारी पत्थर और हल्के पत्थर को साथ बाँध दो, तो क्या जोड़ी अकेले भारी पत्थर से तेज़ गिरेगी या धीमी? क्यों?’ इस प्रश्न-शैली का मुख्य उद्देश्य क्या है?","optionsHi":["विद्यार्थी को शर्मिंदा करके चुप कराना ताकि पाठ योजना के अनुसार चलता रहे","यह जाँचना कि विद्यार्थी को पाठ्यपुस्तक की परिभाषा और गुरुत्व का नियम याद है या नहीं","विद्यार्थी को अपनी धारणा की जाँच करने और उसमें विरोधाभास खोजने की ओर ले जाना","प्रश्न को किसी अन्य विद्यार्थी की ओर मोड़ना जो सही उत्तर जानता हो"],"explanationHi":"सुकराती प्रश्न-विधि प्रश्नों की श्रृंखला का उपयोग करती है जो शिक्षार्थी को अपने विश्वास की जाँच करने और यह देखने को प्रेरित करती है कि वह कहाँ टूटता है, ताकि समझ बताई नहीं बल्कि बनाई जाती है। यह स्मरण की जाँच या पुनर्निर्देशन नहीं है।"},
  {"id":"cdp-pedagogy-subjects-939","question":"During a Class III lesson on vegetables, a child asks, 'Why do onions make us cry?' The question is not part of the plan. What is the best response?","options":["Tell the child to ask only questions about the lesson, so that the class stays on track","Ignore the question and continue, so as not to lose time from the planned lesson","Give the full scientific explanation at once, even if the lesson is delayed by half an hour","Welcome the question, note it on the class question wall, and explore it together later"],"answer":3,"explanation":"Children's own questions show curiosity, which NCF wants to nurture; recording and returning to them values the question without derailing the lesson. Dismissing questions teaches children to stop asking.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"सब्ज़ियों पर कक्षा III के पाठ के दौरान एक बच्चा पूछता है, ‘प्याज़ हमें क्यों रुलाती है?’ प्रश्न योजना का हिस्सा नहीं है। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["बच्चे को कहना कि केवल पाठ के बारे में प्रश्न पूछे, ताकि कक्षा पटरी पर रहे","प्रश्न को अनदेखा करके जारी रखना, ताकि नियोजित पाठ का समय न खोए","पाठ आधा घंटा विलंबित हो जाए तब भी तुरंत पूरी वैज्ञानिक व्याख्या देना","प्रश्न का स्वागत करना, उसे कक्षा की प्रश्न-दीवार पर नोट करना, और बाद में साथ मिलकर उसकी खोज करना"],"explanationHi":"बच्चों के अपने प्रश्न जिज्ञासा दिखाते हैं, जिसे NCF पोषित करना चाहता है; उन्हें दर्ज करना और लौटना पाठ को पटरी से उतारे बिना प्रश्न को महत्त्व देता है। प्रश्नों को खारिज करना बच्चों को पूछना बंद करना सिखाता है।"},
  {"id":"cdp-pedagogy-subjects-940","question":"After explaining fractions, a Class IV teacher asks, 'Did everyone understand?' Most children say 'Yes', yet many fail a later task. What is the most useful change to her questioning?","options":["Ask 'Did everyone understand?' twice, and more firmly, to make sure of the answer","Ask children to show or explain, e.g. 'Fold this paper to show three-quarters and say why'","Ask only the best students to confirm that they understood, as they speak honestly","Give the class a written test every day so that gaps show up in the marks"],"answer":1,"explanation":"Yes/no questions about understanding are unreliable because children say 'yes' to avoid embarrassment. Asking them to show or explain gives real evidence of understanding.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"भिन्न समझाने के बाद कक्षा IV की शिक्षिका पूछती है, ‘क्या सबको समझ आया?’ अधिकांश बच्चे ‘हाँ’ कहते हैं, फिर भी कई बाद में एक कार्य में विफल रहते हैं। उसके प्रश्न करने में सबसे उपयोगी परिवर्तन क्या है?","optionsHi":["‘क्या सबको समझ आया?’ दो बार और अधिक दृढ़ता से पूछना, उत्तर पक्का करने के लिए","बच्चों से दिखाने या समझाने को कहना, जैसे ‘इस कागज़ को तह करके तीन-चौथाई दिखाओ और कारण बताओ’","केवल सबसे अच्छे विद्यार्थियों से पुष्टि करवाना कि उन्होंने समझा, क्योंकि वे ईमानदारी से बोलते हैं","कक्षा को रोज़ लिखित परीक्षा देना ताकि अंकों में कमियाँ दिखें"],"explanationHi":"समझ के बारे में हाँ/नहीं प्रश्न अविश्वसनीय होते हैं क्योंकि बच्चे शर्मिंदगी से बचने के लिए ‘हाँ’ कह देते हैं। उनसे दिखाने या समझाने को कहना समझ का वास्तविक साक्ष्य देता है।"},
  {"id":"cdp-pedagogy-subjects-941","question":"A Class VI teacher asks a challenging question, waits two seconds and, hearing no answer, gives the answer herself. This happens several times each period. What is the most likely long-term effect?","options":["Students learn that the teacher will supply the answer, so they stop thinking","Students' scores improve, because they hear the correct answers more often","Students begin to ask more questions of their own during lessons","Students' answers become longer and more detailed over the year"],"answer":0,"explanation":"Answering one's own questions teaches students to wait rather than think, and lowers participation. Extending wait time and using think-pair-share would encourage thinking.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VI की एक शिक्षिका चुनौतीपूर्ण प्रश्न पूछती है, दो सेकंड प्रतीक्षा करती है और कोई उत्तर न सुनकर स्वयं उत्तर दे देती है। यह हर पीरियड में कई बार होता है। सबसे संभावित दीर्घकालिक प्रभाव क्या है?","optionsHi":["विद्यार्थी सीखते हैं कि शिक्षिका उत्तर दे देगी, इसलिए वे सोचना बंद कर देते हैं","विद्यार्थियों के अंक सुधरते हैं, क्योंकि वे सही उत्तर अधिक बार सुनते हैं","विद्यार्थी पाठों के दौरान अपने अधिक प्रश्न पूछने लगते हैं","वर्ष भर में विद्यार्थियों के उत्तर लंबे और अधिक विस्तृत हो जाते हैं"],"explanationHi":"अपने प्रश्नों का स्वयं उत्तर देना विद्यार्थियों को सोचने के बजाय प्रतीक्षा करना सिखाता है और भागीदारी घटाता है। प्रतीक्षा-समय बढ़ाना और सोचो-जोड़ी बनाओ-साझा करो चिंतन को प्रोत्साहित करते।"},
  {"id":"cdp-pedagogy-subjects-942","question":"In a Class V class, the same five children raise their hands and answer every question. Which change best spreads thinking and participation across the whole class?","options":["Continue taking answers only from volunteers, since calling on others creates anxiety and fear in them","Ask questions only to the five confident children, so that the lesson moves faster","Punish children who never raise their hands, so that they learn to take part","Use think-pair-share, then call on students at random (e.g. with name sticks) in a supportive way"],"answer":3,"explanation":"Thinking time with a partner gives every child something to say, and random selection means everyone must prepare; a supportive tone keeps it safe. Relying on volunteers leaves most children passive.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा V की एक कक्षा में वही पाँच बच्चे हाथ उठाते हैं और हर प्रश्न का उत्तर देते हैं। कौन-सा परिवर्तन सोच और भागीदारी को पूरी कक्षा में सबसे अच्छी तरह फैलाता है?","optionsHi":["केवल स्वयंसेवकों से उत्तर लेते रहना, क्योंकि दूसरों को बुलाना उनमें चिंता और भय पैदा करता है","केवल पाँच आत्मविश्वासी बच्चों से प्रश्न पूछना, ताकि पाठ तेज़ चले","जो बच्चे कभी हाथ नहीं उठाते उन्हें दंड देना, ताकि वे भाग लेना सीखें","सोचो-जोड़ी बनाओ-साझा करो का प्रयोग करना, फिर सहयोगी ढंग से विद्यार्थियों को यादृच्छिक रूप से (जैसे नाम की पर्चियों से) बुलाना"],"explanationHi":"साथी के साथ सोचने का समय हर बच्चे को कहने को कुछ देता है, और यादृच्छिक चयन का अर्थ है कि सबको तैयारी करनी होती है; सहयोगी स्वर इसे सुरक्षित रखता है। स्वयंसेवकों पर निर्भर रहना अधिकांश बच्चों को निष्क्रिय छोड़ देता है।"},
  {"id":"cdp-pedagogy-subjects-943","question":"A Class VII EVS teacher wants a question that genuinely requires the Analyse level. Which question should she choose?","options":["'From this table of rainfall and wheat yield in two villages, what pattern do you see, and why?'","'Define rainfall and write two sentences about how the monsoon reaches your state.'","'Which state of India receives the highest rainfall, and in which months does it fall?'","'Draw the symbol used for rainfall on weather maps and label it.'"],"answer":0,"explanation":"Finding patterns and relationships in unfamiliar data and looking for causes is Analyse. The other questions only ask for recall or reproduction of known information.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VII की एक EVS शिक्षिका ऐसा प्रश्न चाहती है जो वास्तव में विश्लेषण स्तर की माँग करे। उसे कौन-सा प्रश्न चुनना चाहिए?","optionsHi":["‘दो गाँवों में वर्षा और गेहूँ की उपज की इस सारणी से तुम कौन-सा पैटर्न देखते हो, और क्यों?’","‘वर्षा की परिभाषा दीजिए और अपने राज्य में मानसून कैसे पहुँचता है, इस पर दो वाक्य लिखिए।’","‘भारत के किस राज्य में सबसे अधिक वर्षा होती है, और किन महीनों में?’","‘मौसम मानचित्रों पर वर्षा के लिए प्रयुक्त चिह्न बनाइए और उसे नामांकित कीजिए।’"],"explanationHi":"अपरिचित आँकड़ों में पैटर्न और संबंध खोजना और कारण ढूँढ़ना विश्लेषण है। अन्य प्रश्न केवल ज्ञात जानकारी का स्मरण या पुनरुत्पादन माँगते हैं।"},
  {"id":"cdp-pedagogy-subjects-944","question":"Consider the following statements about using Bloom's revised taxonomy in teaching: 1. Its categories are treated as a less rigid hierarchy than the original, so they can overlap. 2. Higher-order questions are suitable for primary-school children as well. 3. Questions at the Remember level have no place in good teaching. Which of these are correct?","options":["2 and 3 only","1 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"The revised taxonomy relaxes the strict cumulative hierarchy, and even young children can analyse and evaluate at their level. Recall still has a role (facts feed higher thinking), so statement 3 is false.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"शिक्षण में ब्लूम के संशोधित वर्गीकरण के प्रयोग के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसकी श्रेणियों को मूल से कम कठोर पदानुक्रम माना जाता है, इसलिए वे एक-दूसरे से ओवरलैप हो सकती हैं। 2. उच्च-स्तरीय प्रश्न प्राथमिक विद्यालय के बच्चों के लिए भी उपयुक्त हैं। 3. ‘याद करना’ स्तर के प्रश्नों का अच्छे शिक्षण में कोई स्थान नहीं है। इनमें से कौन-से सही हैं?","optionsHi":["केवल 2 और 3","केवल 1 और 3","केवल 1 और 2","1, 2 और 3"],"explanationHi":"संशोधित वर्गीकरण कठोर संचयी पदानुक्रम को ढीला करता है, और छोटे बच्चे भी अपने स्तर पर विश्लेषण और मूल्यांकन कर सकते हैं। स्मरण की अब भी भूमिका है (तथ्य उच्च चिंतन को पोषित करते हैं), इसलिए कथन 3 असत्य है।"},
  {"id":"cdp-pedagogy-subjects-945","question":"In a Class VI art-and-science project, students use a rubric to judge a partner's poster on 'clarity of the diagram' and 'accuracy of labels' and give reasons for each score. The task is mainly at which level of Bloom's revised taxonomy?","options":["Create","Analyse","Evaluate","Understand"],"answer":2,"explanation":"Judging work against given criteria and justifying the judgement (checking, critiquing) is Evaluate. Students are not producing something new, so it is not Create.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VI की कला-और-विज्ञान परियोजना में विद्यार्थी साथी के पोस्टर को ‘आरेख की स्पष्टता’ और ‘नामांकन की सटीकता’ पर आँकने के लिए रूब्रिक का प्रयोग करते हैं और प्रत्येक अंक के कारण देते हैं। यह कार्य ब्लूम के संशोधित वर्गीकरण के मुख्यतः किस स्तर का है?","optionsHi":["सृजन","विश्लेषण","मूल्यांकन","समझना"],"explanationHi":"दिए गए मानदंडों के आधार पर कार्य को आँकना और निर्णय को उचित ठहराना (जाँचना, आलोचना करना) मूल्यांकन है। विद्यार्थी कुछ नया नहीं बना रहे, इसलिए यह सृजन नहीं है।"},
  {"id":"cdp-pedagogy-subjects-946","question":"A teacher believes: 'Weak students cannot handle why and how questions; I ask them only what and who questions until they master the basics.' Which response is best supported by research and NCF?","options":["The teacher is right, because thinking questions only confuse and discourage weak students","All students gain from higher-order questions with support; restricting some to recall lowers expectations","The teacher is right, because a child must fully master recall before any higher-order thinking","Higher-order questions should be asked only in written tests, never in class, where weak students feel exposed"],"answer":1,"explanation":"Limiting low achievers to recall denies them the thinking that builds understanding and signals low expectations. With scaffolds such as examples and think time, they can and should reason too.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"एक शिक्षक मानता है: ‘कमज़ोर विद्यार्थी क्यों और कैसे वाले प्रश्न नहीं सँभाल सकते; मैं उनसे केवल क्या और कौन वाले प्रश्न पूछता हूँ जब तक वे बुनियादी बातें न सीख लें।’ शोध और NCF द्वारा कौन-सी प्रतिक्रिया सबसे अच्छी तरह समर्थित है?","optionsHi":["शिक्षक सही है, क्योंकि चिंतन-प्रश्न कमज़ोर विद्यार्थियों को केवल भ्रमित और हतोत्साहित करते हैं","सहारे के साथ उच्च-स्तरीय प्रश्नों से सभी विद्यार्थी लाभान्वित होते हैं; कुछ को स्मरण तक सीमित रखना अपेक्षाएँ घटाता है","शिक्षक सही है, क्योंकि किसी भी उच्च-स्तरीय चिंतन से पहले बच्चे को स्मरण में पूरी तरह निपुण होना चाहिए","उच्च-स्तरीय प्रश्न केवल लिखित परीक्षाओं में पूछे जाने चाहिए, कभी कक्षा में नहीं, जहाँ कमज़ोर विद्यार्थी उजागर महसूस करते हैं"],"explanationHi":"कम उपलब्धि वालों को स्मरण तक सीमित करना उन्हें उस चिंतन से वंचित करता है जो समझ बनाता है और निम्न अपेक्षाओं का संकेत देता है। उदाहरण और सोचने के समय जैसे सहारे के साथ वे भी तर्क कर सकते हैं और उन्हें करना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-947","question":"A Class VIII student explains to her group: 'Iron nails rust faster in coastal Mumbai than in dry Jaipur because there is more moisture in the air there.' In Bloom's revised taxonomy, this explanation is best placed at:","options":["Remember x Factual knowledge","Understand x Conceptual knowledge","Create x Procedural knowledge","Evaluate x Metacognitive knowledge"],"answer":1,"explanation":"Explaining a cause-and-effect relation in a new example is Understand (explaining), and the knowledge is a principle about rusting, which is conceptual. She is not judging, creating or recalling a stand-alone fact.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VIII की एक विद्यार्थी अपने समूह को समझाती है: ‘लोहे की कीलें तटीय मुंबई में सूखे जयपुर की तुलना में तेज़ी से जंग खाती हैं क्योंकि वहाँ हवा में अधिक नमी है।’ ब्लूम के संशोधित वर्गीकरण में यह व्याख्या सबसे अच्छी तरह कहाँ रखी जाती है?","optionsHi":["याद करना x तथ्यात्मक ज्ञान","समझना x संप्रत्ययात्मक ज्ञान","सृजन x प्रक्रियात्मक ज्ञान","मूल्यांकन x अधिबोधात्मक ज्ञान"],"explanationHi":"नए उदाहरण में कारण-प्रभाव संबंध समझाना समझना (व्याख्या करना) है, और ज्ञान जंग लगने के बारे में सिद्धांत है, जो संप्रत्ययात्मक है। वह निर्णय नहीं कर रही, सृजन नहीं कर रही, या कोई अकेला तथ्य याद नहीं कर रही।"},
  {"id":"cdp-pedagogy-subjects-948","question":"Assertion (A): A question that begins with 'Why' is always a higher-order question. Reason (R): The level of a question depends on the thinking students must do to answer it, not only on its opening word.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"'Why did the Mughal empire decline?' is only recall if students learnt a list of reasons by heart. Since level depends on the actual cognitive work, R is true and it shows A is false.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"अभिकथन (A): जो प्रश्न ‘क्यों’ से शुरू होता है वह हमेशा उच्च-स्तरीय प्रश्न होता है। कारण (R): प्रश्न का स्तर इस पर निर्भर करता है कि उसका उत्तर देने के लिए विद्यार्थियों को कैसा चिंतन करना पड़ता है, केवल उसके आरंभिक शब्द पर नहीं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"‘मुग़ल साम्राज्य का पतन क्यों हुआ?’ केवल स्मरण है यदि विद्यार्थियों ने कारणों की सूची रट रखी हो। चूँकि स्तर वास्तविक संज्ञानात्मक कार्य पर निर्भर करता है, R सत्य है और दिखाता है कि A असत्य है।"},
  {"id":"cdp-pedagogy-subjects-949","question":"In a Class V maths lesson, the teacher shows that 3/4 and 6/8 are equal and asks: 'Can you find two other fractions equal to 3/4 and explain how you know?' Which feature makes this a good question for learning?","options":["It has only one correct answer, which makes marking quick, simple and fair for every child in class","It is really a yes/no question, which saves time and keeps the lesson moving","It asks children to recall a rule exactly as it is written in the textbook","It allows many correct answers and asks children to justify them, revealing their understanding"],"answer":3,"explanation":"Open questions with several answers and a call for justification show whether children grasp the idea of equivalence, not just a memorised rule. This makes their thinking visible to the teacher.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा V के गणित के पाठ में शिक्षक दिखाता है कि 3/4 और 6/8 बराबर हैं और पूछता है: ‘क्या तुम 3/4 के बराबर दो अन्य भिन्नें खोज सकते हो और बता सकते हो कि तुम यह कैसे जानते हो?’ कौन-सी विशेषता इसे अधिगम के लिए अच्छा प्रश्न बनाती है?","optionsHi":["इसका केवल एक सही उत्तर है, जिससे कक्षा के हर बच्चे के लिए जाँचना तेज़, सरल और निष्पक्ष हो जाता है","यह वास्तव में हाँ/नहीं प्रश्न है, जो समय बचाता है और पाठ को चलता रखता है","यह बच्चों से पाठ्यपुस्तक में लिखे अनुसार ठीक वैसा ही नियम याद करने को कहता है","यह अनेक सही उत्तरों की अनुमति देता है और बच्चों से उन्हें उचित ठहराने को कहता है, जिससे उनकी समझ प्रकट होती है"],"explanationHi":"अनेक उत्तरों और औचित्य की माँग वाले खुले प्रश्न दिखाते हैं कि बच्चे तुल्यता का विचार समझते हैं, केवल रटा हुआ नियम नहीं। इससे उनकी सोच शिक्षक को दृश्य होती है।"},
  {"id":"cdp-pedagogy-subjects-950","question":"The NCF 2005 position paper on teaching mathematics names some core problems of school mathematics in India. Which of these is NOT one of them?","options":["A sense of fear and failure about mathematics among a majority of school children","Crude methods of assessment that make mathematics look like mechanical computation","Too much time on concrete materials and activities in the upper primary classes","Inadequate preparation of, and support for, mathematics teachers in schools"],"answer":2,"explanation":"The paper lists fear and failure, a curriculum that disappoints both the talented and the non-participating majority, crude assessment, and inadequate teacher preparation. It argues for more activity, not less.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"गणित शिक्षण पर NCF 2005 का स्थिति-पत्र भारत में विद्यालयी गणित की कुछ मूल समस्याओं के नाम बताता है। इनमें से कौन-सी उनमें से एक नहीं है?","optionsHi":["अधिकांश विद्यालयी बच्चों में गणित के प्रति भय और विफलता की भावना","आकलन की भोंडी विधियाँ जो गणित को यांत्रिक गणना जैसा दिखाती हैं","उच्च प्राथमिक कक्षाओं में मूर्त सामग्री और गतिविधियों पर बहुत अधिक समय","विद्यालयों में गणित शिक्षकों की अपर्याप्त तैयारी और सहयोग"],"explanationHi":"पत्र भय और विफलता, ऐसी पाठ्यचर्या जो प्रतिभाशाली और गैर-भागीदार बहुसंख्यक दोनों को निराश करती है, भोंडा आकलन, और शिक्षकों की अपर्याप्त तैयारी गिनाता है। वह कम नहीं, अधिक गतिविधि के पक्ष में तर्क देता है।"},
  {"id":"cdp-pedagogy-subjects-951","question":"NCF 2005 recommends shifting the focus from mathematical content to a learning environment where processes come first. Which classroom best fits this?","options":["Students estimate the school's daily water use, choose a method, check their reasoning and present it","The teacher completes the syllabus early so that there is more time for revision and tests","Students copy solved examples from the board and then do similar exercises on their own","Students practise timed speed tests on all the formulae every day to build fluency"],"answer":0,"explanation":"Estimation, representation, reasoning and communication are among the processes NCF 2005 puts ahead of covering content. The other options focus on finishing content or on mechanical practice.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"NCF 2005 गणितीय विषयवस्तु से ध्यान हटाकर ऐसे अधिगम परिवेश की ओर ले जाने की अनुशंसा करता है जहाँ प्रक्रियाएँ पहले आएँ। कौन-सी कक्षा इसके सबसे अनुकूल है?","optionsHi":["विद्यार्थी विद्यालय के दैनिक जल उपयोग का अनुमान लगाते हैं, विधि चुनते हैं, अपना तर्क जाँचते हैं और उसे प्रस्तुत करते हैं","शिक्षक पाठ्यक्रम जल्दी पूरा कर देता है ताकि दोहराने और परीक्षाओं के लिए अधिक समय मिले","विद्यार्थी बोर्ड से हल किए उदाहरण उतारते हैं और फिर अपने से वैसे ही अभ्यास करते हैं","विद्यार्थी प्रवाह बनाने के लिए प्रतिदिन सभी सूत्रों पर समयबद्ध गति-परीक्षाओं का अभ्यास करते हैं"],"explanationHi":"आकलन, निरूपण, तर्क और संप्रेषण उन प्रक्रियाओं में हैं जिन्हें NCF 2005 विषयवस्तु पूरी करने से आगे रखता है। अन्य विकल्प विषयवस्तु पूरी करने या यांत्रिक अभ्यास पर केंद्रित हैं।"},
  {"id":"cdp-pedagogy-subjects-952","question":"Which of these statements match the NCF 2005 position on mathematics at the primary stage? I. A positive attitude towards, and liking for, mathematics is as important as cognitive skills, if not more. II. Games, puzzles and stories help children develop this attitude. III. The primary stage should concentrate on speed in written algorithms.","options":["I only","I and II only","II and III only","I, II and III"],"answer":1,"explanation":"NCF 2005 says that liking mathematics at the primary stage matters as much as cognitive skills, and that games, puzzles and stories help build it. It does not ask for a focus on speed in algorithms.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs","questionHi":"प्राथमिक स्तर पर गणित पर NCF 2005 की स्थिति से इनमें से कौन-से कथन मेल खाते हैं? I. गणित के प्रति सकारात्मक दृष्टिकोण और लगाव संज्ञानात्मक कौशलों जितना, यदि अधिक नहीं तो, महत्त्वपूर्ण है। II. खेल, पहेलियाँ और कहानियाँ बच्चों में यह दृष्टिकोण विकसित करने में मदद करती हैं। III. प्राथमिक स्तर को लिखित कलन-विधियों में गति पर ध्यान केंद्रित करना चाहिए।","optionsHi":["केवल I","केवल I और II","केवल II और III","I, II और III"],"explanationHi":"NCF 2005 कहता है कि प्राथमिक स्तर पर गणित के प्रति लगाव संज्ञानात्मक कौशलों जितना ही मायने रखता है, और खेल, पहेलियाँ और कहानियाँ उसे बनाने में मदद करती हैं। वह कलन-विधियों में गति पर ध्यान की माँग नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-953","question":"Assertion (A): NCF 2005 recommends changing assessment in mathematics so that it tests students' ability to mathematise rather than only procedural knowledge. Reason (R): Crude assessment encourages children and teachers to see mathematics as mechanical computation.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"NCF 2005 names crude assessment as a core problem precisely because it shapes what is taught and learnt as mechanical computation; changing assessment is its remedy. R explains A.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): NCF 2005 गणित में आकलन बदलने की अनुशंसा करता है ताकि वह केवल प्रक्रियात्मक ज्ञान के बजाय विद्यार्थियों की गणितीकरण की योग्यता परखे। कारण (R): भोंडा आकलन बच्चों और शिक्षकों को गणित को यांत्रिक गणना के रूप में देखने को प्रोत्साहित करता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"NCF 2005 भोंडे आकलन को मूल समस्या ठीक इसलिए गिनाता है कि वह तय करता है कि यांत्रिक गणना के रूप में क्या पढ़ाया और सीखा जाता है; आकलन बदलना उसका उपाय है। R, A की व्याख्या करता है।"},
  {"id":"cdp-pedagogy-subjects-954","question":"A Class 1 child, after counting 3 mangoes, 3 claps and 3 days of the week, says, ‘They are different things, but it is always three.’ Which feature of mathematics has she begun to grasp?","options":["Precision of language, since she uses the word ‘three’ correctly each time","Deductive proof, since she has proved a rule from her own examples","Measurement, since she has measured three different kinds of things","Abstraction, since number is a property shared by all sets of that size"],"answer":3,"explanation":"Seeing ‘three’ as separate from mangoes, claps or days is abstraction, a basic feature of mathematics that lets one idea apply to countless situations.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"3 आम, 3 तालियाँ और सप्ताह के 3 दिन गिनने के बाद कक्षा 1 की एक बच्ची कहती है, ‘ये अलग-अलग चीज़ें हैं, पर यह हमेशा तीन ही होता है।’ गणित की कौन-सी विशेषता उसने समझना शुरू की है?","optionsHi":["भाषा की सटीकता, क्योंकि वह हर बार ‘तीन’ शब्द का सही प्रयोग करती है","निगमनात्मक उपपत्ति, क्योंकि उसने अपने उदाहरणों से एक नियम सिद्ध किया है","मापन, क्योंकि उसने तीन अलग प्रकार की चीज़ों को मापा है","अमूर्तन, क्योंकि संख्या उस आकार के सभी समुच्चयों की साझा विशेषता है"],"explanationHi":"‘तीन’ को आमों, तालियों या दिनों से अलग देखना अमूर्तन है, जो गणित की मूल विशेषता है और एक विचार को असंख्य स्थितियों पर लागू होने देती है।"},
  {"id":"cdp-pedagogy-subjects-955","question":"A teacher shows several examples, asks Class 7 students to spot the rule that the exterior angle of a triangle equals the sum of the two opposite interior angles, and then proves it for any triangle. This lesson moves from:","options":["the deductive method to the inductive method","the analytic method to the synthetic method","the inductive method to the deductive method","the lecture method to the project method"],"answer":2,"explanation":"Finding a rule from examples is inductive; proving it for every case from known facts is deductive. Moving from the first to the second gives understanding and then certainty.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"एक शिक्षक कई उदाहरण दिखाता है, कक्षा 7 के विद्यार्थियों से यह नियम पहचानने को कहता है कि त्रिभुज का बहिष्कोण दो सम्मुख अंतःकोणों के योग के बराबर होता है, और फिर किसी भी त्रिभुज के लिए उसे सिद्ध करता है। यह पाठ किससे किसकी ओर जाता है?","optionsHi":["निगमन विधि से आगमन विधि की ओर","विश्लेषण विधि से संश्लेषण विधि की ओर","आगमन विधि से निगमन विधि की ओर","व्याख्यान विधि से परियोजना विधि की ओर"],"explanationHi":"उदाहरणों से नियम खोजना आगमनात्मक है; ज्ञात तथ्यों से हर स्थिति के लिए उसे सिद्ध करना निगमनात्मक है। पहले से दूसरे की ओर जाना समझ और फिर निश्चितता देता है।"},
  {"id":"cdp-pedagogy-subjects-956","question":"A child reads a word problem and at once adds all the numbers in it. Which of Pólya's problem-solving stages has she skipped?","options":["Understanding the problem","Devising a plan","Carrying out the plan","Looking back"],"answer":0,"explanation":"Before planning, a solver must know what is given and what is asked. Asking her to retell the problem in her own words or draw it addresses the skipped first stage.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"एक बच्ची शब्द-समस्या पढ़ती है और तुरंत उसकी सभी संख्याएँ जोड़ देती है। पोल्या के समस्या-समाधान के चरणों में से उसने कौन-सा चरण छोड़ दिया है?","optionsHi":["समस्या को समझना","योजना बनाना","योजना को क्रियान्वित करना","पीछे मुड़कर देखना"],"explanationHi":"योजना बनाने से पहले हल करने वाले को पता होना चाहिए कि क्या दिया है और क्या पूछा गया है। उससे समस्या अपने शब्दों में फिर बताने या उसका चित्र बनाने को कहना छूटे हुए पहले चरण को संबोधित करता है।"},
  {"id":"cdp-pedagogy-subjects-957","question":"‘Ravi spent half his pocket money on a book and then ₹20 on snacks. He had ₹30 left. How much did he start with?’ Which strategy is the most efficient for this problem?","options":["Guess and check","Work backwards","Make a table","Look for a pattern"],"answer":1,"explanation":"The end amount and the steps are known, so undoing them in reverse order gives the start: (30 + 20) × 2 = ₹100. Guessing works but is slower.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"‘रवि ने अपनी आधी जेब-खर्ची एक किताब पर और फिर ₹20 नाश्ते पर खर्च किए। उसके पास ₹30 बचे। उसके पास शुरू में कितने थे?’ इस समस्या के लिए सबसे कुशल युक्ति कौन-सी है?","optionsHi":["अनुमान लगाओ और जाँचो","पीछे की ओर काम करना","सारणी बनाना","पैटर्न खोजना"],"explanationHi":"अंतिम राशि और चरण ज्ञात हैं, इसलिए उन्हें उलटे क्रम में पलटने पर आरंभ मिलता है: (30 + 20) × 2 = ₹100। अनुमान लगाना काम करता है पर धीमा है।"},
  {"id":"cdp-pedagogy-subjects-958","question":"After proving that the angles of a triangle add up to 180°, a teacher asks, ‘What if the shape had four sides? What if the triangle were drawn on a ball?’ This is an example of:","options":["drill and practice, applying a known result to new figures","the lecture method, extending the proof through explanation","problem posing, by asking ‘what if not?’ about a known result","remedial teaching for students who could not follow the proof"],"answer":2,"explanation":"Changing one condition of a known result to create new questions is the ‘what if not?’ strategy of problem posing. It develops curiosity and the habit of asking mathematical questions.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"यह सिद्ध करने के बाद कि त्रिभुज के कोणों का योग 180° होता है, एक शिक्षक पूछता है, ‘यदि आकृति की चार भुजाएँ हों तो? यदि त्रिभुज किसी गेंद पर खींचा जाए तो?’ यह किसका उदाहरण है?","optionsHi":["अभ्यास और पुनरावृत्ति, ज्ञात परिणाम को नई आकृतियों पर लागू करना","व्याख्यान विधि, व्याख्या से उपपत्ति को बढ़ाना","समस्या-निर्माण, ज्ञात परिणाम के बारे में ‘यदि नहीं तो?’ पूछकर","उन विद्यार्थियों के लिए उपचारात्मक शिक्षण जो उपपत्ति नहीं समझ पाए"],"explanationHi":"किसी ज्ञात परिणाम की एक शर्त बदलकर नए प्रश्न बनाना समस्या-निर्माण की ‘यदि नहीं तो?’ युक्ति है। यह जिज्ञासा और गणितीय प्रश्न पूछने की आदत विकसित करता है।"},
  {"id":"cdp-pedagogy-subjects-959","question":"A teacher shows a ration shop's price list and asks Class 4 children to make up their own questions from it. What is the main value of this task?","options":["It saves the teacher's time and effort in setting fresh questions for the class","It replaces the need for textbook exercises, since children make their own","It is mainly a test of how fast children can read the items on a price list","Posing problems deepens grasp of the operations and reveals what children understand"],"answer":3,"explanation":"To pose a sensible problem a child must understand what each operation means. The questions children make, and the mistakes in them, show the teacher their understanding.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षक राशन की दुकान की मूल्य-सूची दिखाता है और कक्षा 4 के बच्चों से उससे अपने प्रश्न बनाने को कहता है। इस कार्य का मुख्य मूल्य क्या है?","optionsHi":["यह कक्षा के लिए नए प्रश्न बनाने में शिक्षक का समय और प्रयास बचाता है","यह पाठ्यपुस्तक के अभ्यासों की आवश्यकता की जगह ले लेता है, क्योंकि बच्चे अपने प्रश्न बनाते हैं","यह मुख्यतः यह परीक्षा है कि बच्चे मूल्य-सूची की वस्तुएँ कितनी तेज़ पढ़ सकते हैं","समस्याएँ बनाना संक्रियाओं की समझ गहरी करता है और प्रकट करता है कि बच्चे क्या समझते हैं"],"explanationHi":"कोई समझदार समस्या बनाने के लिए बच्चे को समझना होता है कि प्रत्येक संक्रिया का क्या अर्थ है। बच्चों के बनाए प्रश्न, और उनमें की गलतियाँ, शिक्षक को उनकी समझ दिखाते हैं।"},
  {"id":"cdp-pedagogy-subjects-960","question":"‘Some birds were on a tree. 5 flew away and 8 are left. How many were there at first?’ A Class 2 child writes 8 − 5 = 3, saying ‘left means take away’. What is the best response?","options":["Act it out or draw a part-whole picture, showing that birds gone and birds left make up the start","Give the children a list of key words with the operation that goes with each word","Tell the child that the word ‘left’ means add in this problem, and to remember it","Ask the child to read the problem again more slowly and then try the subtraction again"],"answer":0,"explanation":"Acting out or drawing shows the start is 5 + 8 = 13. Key-word lists cause exactly this error, since the same word can signal different operations.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"‘कुछ पक्षी एक पेड़ पर थे। 5 उड़ गए और 8 बचे हैं। पहले कितने थे?’ कक्षा 2 की एक बच्ची 8 − 5 = 3 लिखती है, यह कहते हुए कि ‘बचे का मतलब घटाना’। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["इसे अभिनीत करना या भाग-पूर्ण चित्र बनाना, दिखाते हुए कि गए हुए पक्षी और बचे हुए पक्षी मिलकर आरंभ बनाते हैं","बच्चों को कुंजी-शब्दों की सूची देना जिसमें हर शब्द के साथ संबंधित संक्रिया हो","बच्ची को बताना कि इस समस्या में ‘बचे’ शब्द का अर्थ जोड़ना है, और उसे याद रखे","बच्ची से समस्या को और धीरे फिर पढ़ने और घटाव को फिर आज़माने को कहना"],"explanationHi":"अभिनय या चित्र दिखाता है कि आरंभ 5 + 8 = 13 है। कुंजी-शब्द सूचियाँ ठीक यही त्रुटि पैदा करती हैं, क्योंकि एक ही शब्द अलग-अलग संक्रियाओं का संकेत दे सकता है।"},
  {"id":"cdp-pedagogy-subjects-961","question":"Asked ‘Is 7 an odd number?’, a child says, ‘No, 7 is a normal number. Odd means strange.’ How should the teacher understand and respond?","options":["The child is being cheeky and should be warned not to joke during the lesson","It is a language issue: discuss how everyday and mathematical meanings of ‘odd’ differ","The child has not yet learnt to count up to 7 and needs much more practice in counting","The child should be told to avoid such everyday words when doing mathematics"],"answer":1,"explanation":"Many words (odd, difference, product, volume, table) have different everyday and mathematical meanings. Building the mathematical register through talk is part of teaching mathematics.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"‘क्या 7 विषम संख्या है?’ पूछे जाने पर एक बच्चा कहता है, ‘नहीं, 7 तो सामान्य संख्या है। विषम का मतलब अजीब होता है।’ शिक्षक को इसे कैसे समझना और प्रतिक्रिया देनी चाहिए?","optionsHi":["बच्चा शरारत कर रहा है और उसे पाठ के दौरान मज़ाक न करने की चेतावनी देनी चाहिए","यह भाषा का मुद्दा है: चर्चा करें कि ‘odd’ के रोज़मर्रा और गणितीय अर्थ कैसे भिन्न हैं","बच्चे ने अभी 7 तक गिनना नहीं सीखा है और उसे गिनती का बहुत और अभ्यास चाहिए","बच्चे से कहना चाहिए कि गणित करते समय ऐसे रोज़मर्रा के शब्दों से बचे"],"explanationHi":"अनेक शब्दों (विषम, अंतर, गुणनफल, आयतन, सारणी) के रोज़मर्रा और गणितीय अर्थ अलग होते हैं। बातचीत के माध्यम से गणितीय भाषा-प्रयुक्ति बनाना गणित शिक्षण का हिस्सा है।"},
  {"id":"cdp-pedagogy-subjects-962","question":"A Class 3 child can write 3 × 4 = 12 correctly but cannot draw a picture or make up a story for it. What does this suggest?","options":["Her understanding is already complete, since she writes both the symbols and the answer correctly","She has a language problem that is not related to her understanding of mathematics","Her understanding is limited; she needs tasks linking objects, pictures, words and symbols","She should do more written practice of tables until she is fully fluent with them"],"answer":2,"explanation":"Understanding shows in the ability to translate between representations, such as objects, pictures, spoken language and symbols. Knowing only the symbol form suggests rote learning.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की एक बच्ची 3 × 4 = 12 सही लिख सकती है पर उसका चित्र नहीं बना सकती या कहानी नहीं गढ़ सकती। यह क्या सुझाता है?","optionsHi":["उसकी समझ पहले से पूर्ण है, क्योंकि वह प्रतीक और उत्तर दोनों सही लिखती है","उसे भाषा की समस्या है जिसका गणित की उसकी समझ से कोई संबंध नहीं","उसकी समझ सीमित है; उसे वस्तुओं, चित्रों, शब्दों और प्रतीकों को जोड़ने वाले कार्य चाहिए","उसे पहाड़ों का और लिखित अभ्यास करना चाहिए जब तक वह उनमें पूरी तरह धाराप्रवाह न हो जाए"],"explanationHi":"समझ निरूपणों, जैसे वस्तुओं, चित्रों, बोली गई भाषा और प्रतीकों, के बीच अनुवाद करने की योग्यता में दिखती है। केवल प्रतीक रूप जानना रटंत अधिगम का संकेत है।"},
  {"id":"cdp-pedagogy-subjects-963","question":"A child says, ‘I think you can't take 8 from 3.’ The teacher replies, ‘So you are saying that 3 − 8 has no answer. Who agrees or disagrees, and why?’ This talk move is called:","options":["wait time, giving the child more time to rethink","telling, by giving the class the correct answer","closing the discussion with the right answer","revoicing, then inviting others to respond"],"answer":3,"explanation":"Revoicing restates the child's idea clearly and checks it, and asking others to agree or disagree turns it into a class discussion. It neither tells the answer nor closes the talk.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"एक बच्चा कहता है, ‘मुझे लगता है तुम 3 में से 8 नहीं ले सकते।’ शिक्षक उत्तर देता है, ‘तो तुम कह रहे हो कि 3 − 8 का कोई उत्तर नहीं है। कौन सहमत या असहमत है, और क्यों?’ इस बातचीत की चाल को क्या कहते हैं?","optionsHi":["प्रतीक्षा-समय, बच्चे को पुनर्विचार का अधिक समय देना","बताना, कक्षा को सही उत्तर देकर","सही उत्तर के साथ चर्चा बंद करना","पुनर्कथन (revoicing), फिर दूसरों को प्रतिक्रिया देने को आमंत्रित करना"],"explanationHi":"पुनर्कथन बच्चे के विचार को स्पष्ट रूप से दोहराता और जाँचता है, और दूसरों से सहमत या असहमत होने को कहना उसे कक्षा-चर्चा बना देता है। यह न उत्तर बताता है, न बातचीत बंद करता है।"},
  {"id":"cdp-pedagogy-subjects-964","question":"A teacher asks ‘Why does this method work?’ and calls on the first hand raised within a second. Which change would most improve participation and reasoning?","options":["Wait several seconds, or let pairs discuss first, before taking any answers","Ask easier questions that need no explanation, so more hands go up","Call on the best student first, so that the others hear a model answer","Give the answer herself if no hand goes up at once, to save time"],"answer":0,"explanation":"Longer wait time and pair talk give every child time to think and rehearse an explanation, leading to more and better answers. Calling on the quickest child shuts the others out.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"एक शिक्षक पूछती है ‘यह विधि क्यों काम करती है?’ और एक सेकंड के भीतर उठे पहले हाथ वाले को बुला लेती है। कौन-सा परिवर्तन भागीदारी और तर्क को सबसे अधिक सुधारेगा?","optionsHi":["कोई भी उत्तर लेने से पहले कई सेकंड प्रतीक्षा करना, या जोड़ों को पहले चर्चा करने देना","आसान प्रश्न पूछना जिनमें व्याख्या की आवश्यकता न हो, ताकि अधिक हाथ उठें","सबसे अच्छे विद्यार्थी को पहले बुलाना, ताकि बाकी आदर्श उत्तर सुनें","यदि तुरंत कोई हाथ न उठे तो स्वयं उत्तर दे देना, समय बचाने के लिए"],"explanationHi":"लंबा प्रतीक्षा-समय और जोड़ी में बातचीत हर बच्चे को सोचने और व्याख्या का पूर्वाभ्यास करने का समय देते हैं, जिससे अधिक और बेहतर उत्तर आते हैं। सबसे तेज़ बच्चे को बुलाना दूसरों को बाहर कर देता है।"},
  {"id":"cdp-pedagogy-subjects-965","question":"A teacher puts up sentence frames such as ‘I agree with ___ because ___’ and ‘My method is different because ___’ during maths discussions. The main purpose is to:","options":["make children copy the sentences neatly into their notebooks as practice","help all children, including those learning the language, to explain their reasoning","replace the teacher's explanation, since children can now explain everything to each other","keep the class quiet during group work by giving children fixed things to say"],"answer":1,"explanation":"Frames give a structure for mathematical argument, such as agreeing, disagreeing and justifying, so that more children take part in reasoning, especially those less fluent in the language of instruction.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"गणित चर्चाओं के दौरान एक शिक्षिका ‘मैं ___ से सहमत हूँ क्योंकि ___’ और ‘मेरी विधि अलग है क्योंकि ___’ जैसे वाक्य-ढाँचे लगाती है। मुख्य उद्देश्य है:","optionsHi":["बच्चों से अभ्यास के लिए वाक्यों को अपनी कॉपियों में साफ-साफ उतरवाना","सभी बच्चों की, भाषा सीखने वाले बच्चों सहित, अपने तर्क समझाने में मदद करना","शिक्षिका की व्याख्या की जगह लेना, क्योंकि बच्चे अब एक-दूसरे को सब कुछ समझा सकते हैं","समूह कार्य के दौरान बच्चों को कहने के लिए निश्चित बातें देकर कक्षा को शांत रखना"],"explanationHi":"ढाँचे गणितीय तर्क, जैसे सहमत होना, असहमत होना और औचित्य देना, के लिए संरचना देते हैं ताकि अधिक बच्चे तर्क में भाग लें, विशेषकर वे जो शिक्षण-भाषा में कम धाराप्रवाह हैं।"},
  {"id":"cdp-pedagogy-subjects-966","question":"In a Class 1 classroom in a tribal area, children count fluently in their home language but are shy to answer in Hindi. What is the most suitable approach?","options":["Insist on Hindi number words only, so that children learn the school language much faster","Postpone number work until the children have learnt enough Hindi to follow it","Let them count in their home language, then link those words to the school number names","Teach only the written numerals, without using number words in any language"],"answer":2,"explanation":"NCF 2005 and NEP 2020 treat children's home language as a resource. Building on what they know, and bridging to the school language, keeps the focus on mathematical thinking.","difficulty":"hard","source":"CTET Paper 1 · state TETs · KVS PRT","questionHi":"एक जनजातीय क्षेत्र की कक्षा 1 में बच्चे अपनी घर की भाषा में धाराप्रवाह गिनते हैं पर हिंदी में उत्तर देने में झिझकते हैं। सबसे उपयुक्त उपागम क्या है?","optionsHi":["केवल हिंदी संख्या-शब्दों पर ज़ोर देना, ताकि बच्चे विद्यालय की भाषा बहुत तेज़ी से सीखें","संख्या कार्य को तब तक टाल देना जब तक बच्चे उसे समझने लायक हिंदी न सीख लें","उन्हें घर की भाषा में गिनने देना, फिर उन शब्दों को विद्यालय के संख्या-नामों से जोड़ना","केवल लिखित अंक सिखाना, किसी भी भाषा में संख्या-शब्दों का प्रयोग किए बिना"],"explanationHi":"NCF 2005 और NEP 2020 बच्चों की घर की भाषा को संसाधन मानते हैं। जो वे जानते हैं उस पर निर्माण करना, और विद्यालय की भाषा तक सेतु बनाना, ध्यान को गणितीय चिंतन पर रखता है।"},
  {"id":"cdp-pedagogy-subjects-967","question":"Which statement reflects the NCF 2005 vision of how children should experience mathematics?","options":["Children should see mathematics mainly as a set of procedures to be practised until fluent","Mathematics should be done individually and silently, so that children do not copy","Children should talk about mathematics only after they have written the correct answer","Children should see mathematics as something to talk about, discuss and work on together"],"answer":3,"explanation":"NCF 2005's vision includes children seeing mathematics as something to talk about, communicate through, discuss and work on together, along with enjoying mathematics, posing and solving problems, and seeing structure.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"कौन-सा कथन इस NCF 2005 दृष्टि को दर्शाता है कि बच्चों को गणित का अनुभव कैसे करना चाहिए?","optionsHi":["बच्चों को गणित को मुख्यतः ऐसी प्रक्रियाओं के समूह के रूप में देखना चाहिए जिनका तब तक अभ्यास हो जब तक वे धाराप्रवाह न हों","गणित व्यक्तिगत और चुपचाप होना चाहिए, ताकि बच्चे नकल न करें","बच्चों को गणित के बारे में तभी बात करनी चाहिए जब वे सही उत्तर लिख चुके हों","बच्चों को गणित को ऐसी चीज़ के रूप में देखना चाहिए जिसके बारे में बात की जाए, चर्चा हो और साथ मिलकर काम किया जाए"],"explanationHi":"NCF 2005 की दृष्टि में बच्चों का गणित को ऐसी चीज़ के रूप में देखना शामिल है जिसके बारे में बात की जाए, जिससे संप्रेषण हो, चर्चा हो और साथ मिलकर काम किया जाए, साथ ही गणित का आनंद लेना, समस्याएँ बनाना और हल करना, और संरचना देखना।"},
  {"id":"cdp-pedagogy-subjects-968","question":"A Class 4 child says, ‘Odd plus odd is always even, because each odd number has one left over after making pairs, and the two left-overs make another pair.’ How should the teacher regard this?","options":["As a general argument that shows why it holds for all odd numbers, a proof in words","As a guess that still needs many more examples before it can be accepted","As wrong, because a real proof needs algebra and cannot be in words","As correct only for the small numbers that she has been able to try"],"answer":0,"explanation":"The child's reasoning covers every odd number, not just the ones she tried, so it is a valid general argument. Young children can reason deductively with pictures and words, which NCF 2005 encourages.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कक्षा 4 की एक बच्ची कहती है, ‘विषम जमा विषम हमेशा सम होता है, क्योंकि जोड़े बनाने के बाद हर विषम संख्या में एक बचा रहता है, और दोनों बचे हुए मिलकर एक और जोड़ा बना लेते हैं।’ शिक्षक को इसे कैसे देखना चाहिए?","optionsHi":["एक सामान्य तर्क के रूप में जो दिखाता है कि यह सभी विषम संख्याओं के लिए क्यों सही है, शब्दों में उपपत्ति","अनुमान के रूप में जिसे स्वीकार करने से पहले अभी और बहुत उदाहरण चाहिए","गलत के रूप में, क्योंकि असली उपपत्ति के लिए बीजगणित चाहिए और वह शब्दों में नहीं हो सकती","केवल उन छोटी संख्याओं के लिए सही के रूप में जिन्हें वह आज़मा पाई है"],"explanationHi":"बच्ची का तर्क हर विषम संख्या को समेटता है, केवल उन्हें नहीं जिन्हें उसने आज़माया, इसलिए यह वैध सामान्य तर्क है। छोटे बच्चे चित्रों और शब्दों से निगमनात्मक तर्क कर सकते हैं, जिसे NCF 2005 प्रोत्साहित करता है।"},
  {"id":"cdp-pedagogy-subjects-969","question":"A Class 6 student claims, ‘All prime numbers are odd.’ What is the best response?","options":["Tell her she is right, since nearly all the prime numbers she will meet are odd","Ask her to look for a prime that breaks the rule, since one counterexample disproves a claim","Ask her to list the first ten odd primes, so that she can confirm the claim holds","Tell her to check her claim carefully with all the primes from 3 to 50"],"answer":1,"explanation":"2 is prime and even, so the claim is false. Checking more cases that agree cannot prove a general claim, but a single counterexample disproves it; this is an important idea about the nature of mathematics.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक विद्यार्थी दावा करती है, ‘सभी अभाज्य संख्याएँ विषम होती हैं।’ सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["उसे बताना कि वह सही है, क्योंकि उसे मिलने वाली लगभग सभी अभाज्य संख्याएँ विषम होंगी","उससे ऐसी अभाज्य संख्या खोजने को कहना जो नियम तोड़े, क्योंकि एक प्रतिउदाहरण दावे को गलत सिद्ध कर देता है","उससे पहली दस विषम अभाज्य संख्याओं की सूची बनाने को कहना, ताकि वह पुष्टि कर सके कि दावा सही है","उससे कहना कि 3 से 50 तक की सभी अभाज्य संख्याओं से अपना दावा ध्यान से जाँचे"],"explanationHi":"2 अभाज्य और सम है, इसलिए दावा असत्य है। सहमत होने वाले और मामले जाँचना सामान्य दावे को सिद्ध नहीं कर सकता, पर एक प्रतिउदाहरण उसे गलत सिद्ध कर देता है; यह गणित की प्रकृति के बारे में महत्त्वपूर्ण विचार है।"},
  {"id":"cdp-pedagogy-subjects-970","question":"Children agree on the claim, ‘Multiplying a number by itself always gives a bigger number.’ What should the teacher do next?","options":["Agree, and write it on the class chart of rules for future reference","Correct it at once by telling them the right rule for squares","Have them test it with 1, 0 and 1/2, and then refine the claim","Tell them the claim is true for whole numbers only, from Class 6 on"],"answer":2,"explanation":"1 × 1 = 1, 0 × 0 = 0 and 1/2 × 1/2 = 1/4 break the claim. Testing and refining their own conjecture teaches how mathematics works: claims are checked, not accepted on agreement.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"बच्चे इस दावे पर सहमत होते हैं, ‘किसी संख्या को स्वयं से गुणा करने पर हमेशा बड़ी संख्या मिलती है।’ शिक्षक को आगे क्या करना चाहिए?","optionsHi":["सहमत होना, और भविष्य के संदर्भ के लिए उसे नियमों के कक्षा चार्ट पर लिखना","वर्गों का सही नियम बताकर तुरंत सुधारना","उनसे 1, 0 और 1/2 से परखवाना, और फिर दावे को परिष्कृत करवाना","उन्हें बताना कि दावा केवल पूर्ण संख्याओं के लिए सही है, कक्षा 6 से"],"explanationHi":"1 × 1 = 1, 0 × 0 = 0 और 1/2 × 1/2 = 1/4 दावे को तोड़ते हैं। अपनी अटकल को परखना और परिष्कृत करना सिखाता है कि गणित कैसे काम करता है: दावे जाँचे जाते हैं, सहमति पर स्वीकार नहीं किए जाते।"},
  {"id":"cdp-pedagogy-subjects-971","question":"Before teaching 2-digit by 2-digit multiplication, a Class 5 teacher gives a short check on place value and multiplication facts. This reflects which feature of mathematics?","options":["Its abstract nature, which makes it difficult for many children","Its use of symbols in place of words, which must be learnt first","Its practical use in daily life, such as in shopping, cooking and measuring","Its sequential structure, in which new concepts build on earlier ones"],"answer":3,"explanation":"Mathematics builds in layers, so gaps in earlier ideas block later learning. A readiness check finds the gaps before the new topic is taught.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"2-अंकीय संख्या को 2-अंकीय संख्या से गुणा करना सिखाने से पहले कक्षा 5 की एक शिक्षिका स्थानीय मान और गुणन तथ्यों की एक छोटी जाँच देती है। यह गणित की किस विशेषता को दर्शाता है?","optionsHi":["इसका अमूर्त स्वरूप, जो इसे अनेक बच्चों के लिए कठिन बनाता है","शब्दों के स्थान पर प्रतीकों का प्रयोग, जिन्हें पहले सीखना होता है","दैनिक जीवन में इसका व्यावहारिक उपयोग, जैसे खरीदारी, खाना पकाने और मापने में","इसकी क्रमिक संरचना, जिसमें नए संप्रत्यय पहले वालों पर बनते हैं"],"explanationHi":"गणित परतों में बनता है, इसलिए पहले के विचारों में कमियाँ बाद के अधिगम को रोकती हैं। तत्परता-जाँच नया विषय पढ़ाने से पहले कमियाँ खोजती है।"},
  {"id":"cdp-pedagogy-subjects-972","question":"Class 5 children use a village map to find the shortest route for a postman to visit four houses and return to the post office. Which mathematical process is mainly being developed?","options":["Optimisation, finding the best of several possible solutions","Memorisation of the symbols and colours used on village maps","Rote computation of distances using a formula","Measurement of distances with standard units only"],"answer":0,"explanation":"Comparing routes to find the shortest one is optimisation, listed in NCF 2005 among the processes of mathematics along with estimation, visualisation and reasoning.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के बच्चे गाँव के मानचित्र का उपयोग करके डाकिए के चार घरों में जाकर डाकघर लौटने का सबसे छोटा मार्ग खोजते हैं। मुख्यतः कौन-सी गणितीय प्रक्रिया विकसित हो रही है?","optionsHi":["इष्टतमीकरण, कई संभव हलों में से सर्वश्रेष्ठ खोजना","गाँव के मानचित्रों पर प्रयुक्त चिह्नों और रंगों को याद करना","सूत्र से दूरियों की रटंत गणना","केवल मानक इकाइयों से दूरियों का मापन"],"explanationHi":"सबसे छोटा खोजने के लिए मार्गों की तुलना इष्टतमीकरण है, जिसे NCF 2005 गणित की प्रक्रियाओं में आकलन, दृश्यीकरण और तर्क के साथ गिनाता है।"},
  {"id":"cdp-pedagogy-subjects-973","question":"Which of these statements about the language of mathematics in school are correct? I. Symbols such as ‘=’ and ‘<’ should come after children have expressed the ideas in their own words. II. Word problems test only computation. III. Children's informal language should be linked to formal terms gradually. IV. Precise language matters in mathematics.","options":["I and II only","I, III and IV","II, III and IV","I, II, III and IV"],"answer":1,"explanation":"Word problems also test reading, comprehension and modelling, so II is false. The rest describe good practice: ideas first in words, then symbols, building towards precise mathematical language.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"विद्यालय में गणित की भाषा के बारे में इनमें से कौन-से कथन सही हैं? I. ‘=’ और ‘<’ जैसे प्रतीक बच्चों द्वारा विचारों को अपने शब्दों में व्यक्त करने के बाद आने चाहिए। II. शब्द-समस्याएँ केवल गणना की परीक्षा लेती हैं। III. बच्चों की अनौपचारिक भाषा को औपचारिक शब्दों से धीरे-धीरे जोड़ा जाना चाहिए। IV. गणित में सटीक भाषा मायने रखती है।","optionsHi":["केवल I और II","I, III और IV","II, III और IV","I, II, III और IV"],"explanationHi":"शब्द-समस्याएँ पठन, बोध और मॉडलिंग की भी परीक्षा लेती हैं, इसलिए II असत्य है। शेष अच्छे अभ्यास का वर्णन करते हैं: पहले शब्दों में विचार, फिर प्रतीक, सटीक गणितीय भाषा की ओर बढ़ते हुए।"},
  {"id":"cdp-pedagogy-subjects-974","question":"Match each problem with the most suitable strategy. 1. ‘Half my money went on a book and ₹20 on snacks; ₹30 is left. How much did I start with?’ 2. ‘How many handshakes happen when 20 people each shake hands once?’ 3. ‘Two numbers add up to 20 and multiply to 96. Find them.’ 4. ‘A frog climbs 3 m up a 10 m well each day and slips back 2 m each night. When does it get out?’; a. Draw a diagram b. Guess and check c. Solve simpler cases and look for a pattern d. Work backwards","options":["1-d, 2-b, 3-c, 4-a","1-a, 2-c, 3-b, 4-d","1-d, 2-c, 3-b, 4-a","1-b, 2-c, 3-d, 4-a"],"answer":2,"explanation":"Known end with known steps suggests working backwards; handshakes with 2, 3 and 4 people show a pattern; small number pairs can be checked quickly; and a diagram of the well avoids the trap of answering 10 days (it gets out on day 8).","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"प्रत्येक समस्या का मिलान सबसे उपयुक्त युक्ति से कीजिए। 1. ‘मेरे आधे पैसे किताब पर और ₹20 नाश्ते पर गए; ₹30 बचे हैं। मेरे पास शुरू में कितने थे?’ 2. ‘20 लोग प्रत्येक एक बार हाथ मिलाएँ तो कितने हाथ मिलाने होंगे?’ 3. ‘दो संख्याओं का योग 20 है और गुणनफल 96। उन्हें खोजिए।’ 4. ‘एक मेंढक 10 m गहरे कुएँ में प्रतिदिन 3 m ऊपर चढ़ता है और हर रात 2 m फिसल जाता है। वह कब बाहर निकलता है?’; a. आरेख बनाना b. अनुमान लगाओ और जाँचो c. सरल स्थितियाँ हल करना और पैटर्न खोजना d. पीछे की ओर काम करना","optionsHi":["1-d, 2-b, 3-c, 4-a","1-a, 2-c, 3-b, 4-d","1-d, 2-c, 3-b, 4-a","1-b, 2-c, 3-d, 4-a"],"explanationHi":"ज्ञात अंत और ज्ञात चरण पीछे की ओर काम करने का संकेत देते हैं; 2, 3 और 4 लोगों के साथ हाथ मिलाना पैटर्न दिखाता है; संख्याओं के छोटे जोड़े जल्दी जाँचे जा सकते हैं; और कुएँ का आरेख 10 दिन उत्तर देने के जाल से बचाता है (वह आठवें दिन बाहर निकल जाता है)।"},
  {"id":"cdp-pedagogy-subjects-975","question":"Asked why her mother keeps the drinking-water matka covered, a Class 3 child says, ‘So that dust and flies do not fall in, otherwise we will fall ill.’ In NCERT’s list of EVS learning indicators, this answer mainly shows:","options":["Observation and recording","Explanation","Expression","Classification"],"answer":1,"explanation":"The child links a practice to its reason and consequence, which is the indicator ‘Explanation’ (reasoning, making logical connections). Merely noticing the cover would be observation.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"यह पूछे जाने पर कि उसकी माँ पीने के पानी का मटका ढककर क्यों रखती हैं, कक्षा 3 की एक बच्ची कहती है, ‘ताकि धूल और मक्खियाँ अंदर न गिरें, नहीं तो हम बीमार पड़ जाएँगे।’ NCERT की EVS अधिगम संकेतकों की सूची में यह उत्तर मुख्यतः क्या दर्शाता है?","optionsHi":["अवलोकन और अभिलेखन","व्याख्या","अभिव्यक्ति","वर्गीकरण"],"explanationHi":"बच्ची एक प्रथा को उसके कारण और परिणाम से जोड़ती है, जो ‘व्याख्या’ संकेतक है (तर्क करना, तार्किक संबंध बनाना)। केवल ढक्कन पर ध्यान देना अवलोकन होता।"},
  {"id":"cdp-pedagogy-subjects-976","question":"While making a model of a village in groups, a Class 5 child takes the lead in dividing the work, makes sure everyone gets a turn with the scissors and helps a slower member finish his part. The EVS indicator best shown is:","options":["Concern for justice and equality","Expression","Questioning","Cooperation"],"answer":3,"explanation":"Taking responsibility and initiative, sharing and working together are the sub-indicators of Cooperation. Fair turns can look like ‘justice’, but the behaviour centres on teamwork within the group.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"समूहों में गाँव का मॉडल बनाते समय कक्षा 5 का एक बच्चा काम बाँटने में नेतृत्व करता है, सुनिश्चित करता है कि कैंची की बारी सबको मिले, और एक धीमे सदस्य को उसका भाग पूरा करने में मदद करता है। सबसे अच्छी तरह दर्शाया गया EVS संकेतक है:","optionsHi":["न्याय और समानता के प्रति चिंता","अभिव्यक्ति","प्रश्न पूछना","सहयोग"],"explanationHi":"ज़िम्मेदारी और पहल करना, बाँटना और साथ मिलकर काम करना सहयोग के उप-संकेतक हैं। उचित बारी ‘न्याय’ जैसी दिख सकती है, पर यह व्यवहार समूह के भीतर टीमवर्क पर केंद्रित है।"},
  {"id":"cdp-pedagogy-subjects-977","question":"Before an activity, a Class 5 child says, ‘The bread kept in the damp tin will grow fungus sooner than the bread in the dry tin, because fungus likes moisture.’ This statement mainly shows the EVS indicator:","options":["Analysis","Experimentation","Discussion","Observation and recording"],"answer":0,"explanation":"Predicting and hypothesising with a reason fall under Analysis. Experimentation would be setting up and doing the test, which has not happened yet.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"किसी गतिविधि से पहले कक्षा 5 का एक बच्चा कहता है, ‘नम डिब्बे में रखी ब्रेड सूखे डिब्बे वाली ब्रेड से जल्दी फफूँद पकड़ेगी, क्योंकि फफूँद को नमी पसंद है।’ यह कथन मुख्यतः किस EVS संकेतक को दर्शाता है?","optionsHi":["विश्लेषण","प्रयोग करना","चर्चा","अवलोकन और अभिलेखन"],"explanationHi":"कारण सहित पूर्वानुमान और परिकल्पना बनाना विश्लेषण के अंतर्गत आता है। प्रयोग करना परीक्षण स्थापित करना और करना होता, जो अभी हुआ नहीं है।"},
  {"id":"cdp-pedagogy-subjects-978","question":"Without being asked, a Class 5 child makes a simple filter from a cut plastic bottle, sand and gravel, and pours muddy water through it to see whether it comes out cleaner. This best shows the EVS indicator:","options":["Classification","Expression","Experimentation","Discussion"],"answer":2,"explanation":"Improvising apparatus and testing an idea is Experimentation. Making something by hand might suggest Expression, but the purpose here is to try out and check.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"बिना कहे कक्षा 5 का एक बच्चा कटी हुई प्लास्टिक की बोतल, रेत और बजरी से एक सरल फ़िल्टर बनाता है और उसमें मटमैला पानी डालकर देखता है कि क्या वह साफ निकलता है। यह सबसे अच्छी तरह किस EVS संकेतक को दर्शाता है?","optionsHi":["वर्गीकरण","अभिव्यक्ति","प्रयोग करना","चर्चा"],"explanationHi":"उपकरण जुटाना और विचार को परखना प्रयोग करना है। हाथ से कुछ बनाना अभिव्यक्ति का संकेत दे सकता है, पर यहाँ उद्देश्य आज़माना और जाँचना है।"},
  {"id":"cdp-pedagogy-subjects-979","question":"After a visit to the river near her village, a Class 4 child writes a short poem about it and, with friends, makes up a dance about the rain. The EVS indicator mainly shown is:","options":["Analysis","Explanation","Observation and recording","Expression"],"answer":3,"explanation":"Creative writing, drawing, body movement and similar forms belong to Expression. No reasoning or prediction is involved.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"अपने गाँव के पास की नदी की यात्रा के बाद कक्षा 4 की एक बच्ची उस पर एक छोटी कविता लिखती है और दोस्तों के साथ बारिश पर एक नृत्य बनाती है। मुख्यतः दर्शाया गया EVS संकेतक है:","optionsHi":["विश्लेषण","व्याख्या","अवलोकन और अभिलेखन","अभिव्यक्ति"],"explanationHi":"रचनात्मक लेखन, चित्रांकन, शारीरिक गति और ऐसे ही रूप अभिव्यक्ति के हैं। इसमें कोई तर्क या पूर्वानुमान शामिल नहीं है।"},
  {"id":"cdp-pedagogy-subjects-980","question":"A Class 4 child asks, ‘Why does the water from the hand pump feel warm in winter and cool in summer?’ This mainly reflects the EVS indicator:","options":["Questioning","Analysis","Classification","Cooperation"],"answer":0,"explanation":"Expressing curiosity and framing her own question is Questioning. She is not yet predicting or reasoning, so it is not Analysis.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 की एक बच्ची पूछती है, ‘हैंडपंप का पानी सर्दियों में गर्म और गर्मियों में ठंडा क्यों लगता है?’ यह मुख्यतः किस EVS संकेतक को दर्शाता है?","optionsHi":["प्रश्न पूछना","विश्लेषण","वर्गीकरण","सहयोग"],"explanationHi":"जिज्ञासा व्यक्त करना और अपना प्रश्न बनाना प्रश्न पूछना है। वह अभी पूर्वानुमान या तर्क नहीं कर रही, इसलिए यह विश्लेषण नहीं है।"},
  {"id":"cdp-pedagogy-subjects-981","question":"During a talk on how to save water, a Class 5 child listens to a classmate and then says, ‘I do not agree with Ravi. I think we waste more water while washing utensils.’ The EVS indicator best shown is:","options":["Explanation","Concern for justice and equality","Discussion","Expression"],"answer":2,"explanation":"Listening to others, talking, expressing an opinion and finding out from others are the sub-indicators of Discussion.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"जल बचाने के तरीकों पर बातचीत के दौरान कक्षा 5 की एक बच्ची एक सहपाठी की बात सुनती है और फिर कहती है, ‘मैं रवि से सहमत नहीं हूँ। मुझे लगता है हम बर्तन धोते समय अधिक पानी बर्बाद करते हैं।’ सबसे अच्छी तरह दर्शाया गया EVS संकेतक है:","optionsHi":["व्याख्या","न्याय और समानता के प्रति चिंता","चर्चा","अभिव्यक्ति"],"explanationHi":"दूसरों की सुनना, बोलना, राय व्यक्त करना और दूसरों से पता लगाना चर्चा के उप-संकेतक हैं।"},
  {"id":"cdp-pedagogy-subjects-982","question":"Which of the following are among the indicators NCERT suggests for assessing learning in EVS? I. Classification II. Memorisation of facts III. Concern for justice and equality IV. Handwriting","options":["I, II and III","II and IV","I and IV","I and III"],"answer":3,"explanation":"NCERT’s indicators include classification and concern for justice and equality; memorisation and handwriting are not EVS indicators.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"निम्नलिखित में से कौन-से NCERT द्वारा EVS में अधिगम के आकलन के लिए सुझाए गए संकेतकों में हैं? I. वर्गीकरण II. तथ्यों को याद करना III. न्याय और समानता के प्रति चिंता IV. लिखावट","optionsHi":["I, II और III","II और IV","I और IV","I और III"],"explanationHi":"NCERT के संकेतकों में वर्गीकरण और न्याय तथा समानता के प्रति चिंता शामिल हैं; रटना और लिखावट EVS के संकेतक नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-983","question":"Match each EVS indicator with its sub-skills: 1. Observation and recording 2. Classification 3. Analysis 4. Cooperation. a. Predicting, hypothesising, inferring. b. Reporting, narrating, drawing, making tables. c. Grouping, comparing and contrasting. d. Sharing, taking initiative, working together.","options":["1-c, 2-b, 3-a, 4-d","1-b, 2-c, 3-a, 4-d","1-b, 2-a, 3-c, 4-d","1-a, 2-c, 3-b, 4-d"],"answer":1,"explanation":"Reporting and drawing record observations; grouping and comparing classify; predicting and inferring analyse; sharing and initiative show cooperation.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"प्रत्येक EVS संकेतक का मिलान उसके उप-कौशलों से कीजिए: 1. अवलोकन और अभिलेखन 2. वर्गीकरण 3. विश्लेषण 4. सहयोग। a. पूर्वानुमान, परिकल्पना, अनुमान लगाना। b. प्रतिवेदन, वर्णन, चित्रांकन, सारणी बनाना। c. समूह बनाना, तुलना और विरोध करना। d. बाँटना, पहल करना, साथ मिलकर काम करना।","optionsHi":["1-c, 2-b, 3-a, 4-d","1-b, 2-c, 3-a, 4-d","1-b, 2-a, 3-c, 4-d","1-a, 2-c, 3-b, 4-d"],"explanationHi":"प्रतिवेदन और चित्रांकन अवलोकनों को दर्ज करते हैं; समूह बनाना और तुलना करना वर्गीकरण है; पूर्वानुमान और अनुमान लगाना विश्लेषण है; बाँटना और पहल करना सहयोग दर्शाते हैं।"},
  {"id":"cdp-pedagogy-subjects-984","question":"A Class 4 teacher wants to assess the indicator ‘Cooperation’. The most suitable tool is:","options":["observation during group work, recorded as anecdotal notes over weeks","a written test with questions on teamwork and sharing in groups","an oral quiz in which children explain the meaning and value of cooperation","a homework essay on ‘Why we should cooperate’, marked for ideas"],"answer":0,"explanation":"Cooperation is a behaviour, so it must be seen in action and recorded over time. Tests and essays measure what a child can say about it, not what she does.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 का एक शिक्षक संकेतक ‘सहयोग’ का आकलन करना चाहता है। सबसे उपयुक्त साधन है:","optionsHi":["समूह कार्य के दौरान अवलोकन, जिसे सप्ताहों में उपाख्यानात्मक नोट्स के रूप में दर्ज किया जाए","समूहों में टीमवर्क और बाँटने पर प्रश्नों वाली लिखित परीक्षा","मौखिक प्रश्नोत्तरी जिसमें बच्चे सहयोग का अर्थ और मूल्य समझाएँ","‘हमें सहयोग क्यों करना चाहिए’ पर गृहकार्य निबंध, जिसे विचारों के लिए जाँचा जाए"],"explanationHi":"सहयोग एक व्यवहार है, इसलिए उसे कार्य में देखा और समय के साथ दर्ज किया जाना चाहिए। परीक्षाएँ और निबंध यह मापते हैं कि बच्चा उसके बारे में क्या कह सकता है, वह क्या करता है यह नहीं।"},
  {"id":"cdp-pedagogy-subjects-985","question":"After noticing that many Class 3 children cannot group animals by where they live, a teacher drops her plan for the next chapter and adds more sorting activities with real examples. This is an example of:","options":["assessment of learning used only for grading","summative assessment carried out at the end of the term","assessment for learning, used to adapt teaching","norm-referenced testing to rank children"],"answer":2,"explanation":"Using information about learning to change teaching is formative assessment, or assessment for learning. No grade or ranking is involved.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"यह देखने के बाद कि कक्षा 3 के कई बच्चे जानवरों को उनके रहने की जगह के आधार पर समूहबद्ध नहीं कर पाते, एक शिक्षिका अगले अध्याय की अपनी योजना छोड़ देती है और असली उदाहरणों के साथ और छाँटने की गतिविधियाँ जोड़ती है। यह किसका उदाहरण है?","optionsHi":["अधिगम का आकलन जिसका उपयोग केवल ग्रेड देने के लिए होता है","सत्रांत में किया गया योगात्मक आकलन","अधिगम के लिए आकलन, जिसका उपयोग शिक्षण को अनुकूलित करने में होता है","बच्चों को श्रेणीबद्ध करने के लिए मानक-संदर्भित परीक्षण"],"explanationHi":"अधिगम के बारे में सूचना का उपयोग शिक्षण बदलने के लिए करना रचनात्मक आकलन, या अधिगम के लिए आकलन है। इसमें कोई ग्रेड या श्रेणीकरण शामिल नहीं है।"},
  {"id":"cdp-pedagogy-subjects-986","question":"Which question is best suited to assessing the EVS indicator ‘Analysis’ in Class 5?","options":["Name three trees found near your school and say which of them is the tallest.","Draw any tree you like and colour its leaves, flowers and fruits.","Which tree gives us mangoes, and in which season does it fruit?","If all the trees around our school were cut down, what changes might we notice? Why?"],"answer":3,"explanation":"Predicting consequences and giving reasons is analysis. The others call for recall or expression.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 में EVS संकेतक ‘विश्लेषण’ के आकलन के लिए कौन-सा प्रश्न सबसे उपयुक्त है?","optionsHi":["अपने विद्यालय के पास मिलने वाले तीन पेड़ों के नाम बताओ और कहो कि उनमें सबसे ऊँचा कौन-सा है।","अपनी पसंद का कोई भी पेड़ बनाओ और उसकी पत्तियों, फूलों और फलों में रंग भरो।","कौन-सा पेड़ हमें आम देता है, और किस ऋतु में उसमें फल लगते हैं?","यदि हमारे विद्यालय के आसपास के सभी पेड़ काट दिए जाएँ, तो हमें क्या परिवर्तन दिखेंगे? क्यों?"],"explanationHi":"परिणामों का पूर्वानुमान और कारण देना विश्लेषण है। अन्य स्मरण या अभिव्यक्ति माँगते हैं।"},
  {"id":"cdp-pedagogy-subjects-987","question":"A Class 2 teacher plans a written test on ‘Our surroundings’. The best advice for her is that:","options":["written tests should be given weekly from Class 1 to prepare children for later exams","at this stage, observing children's talk, drawings and activities tells more than written tests","only oral tests should be given at this stage, with marks awarded for every answer","no assessment of any kind should be done in Classes I and II, since the children are far too young"],"answer":1,"explanation":"In the early classes assessment should be informal and observation-based. That does not mean no assessment at all, and oral tests with marks for every answer are just exams in another form.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 2 की एक शिक्षिका ‘हमारे आसपास’ पर लिखित परीक्षा की योजना बनाती है। उसके लिए सबसे अच्छी सलाह यह है कि:","optionsHi":["बाद की परीक्षाओं के लिए तैयार करने के लिए कक्षा 1 से हर सप्ताह लिखित परीक्षाएँ दी जानी चाहिए","इस अवस्था में बच्चों की बातचीत, चित्रों और गतिविधियों का अवलोकन लिखित परीक्षाओं से अधिक बताता है","इस अवस्था में केवल मौखिक परीक्षाएँ दी जानी चाहिए, हर उत्तर के लिए अंक देकर","कक्षा I और II में किसी भी प्रकार का आकलन नहीं होना चाहिए, क्योंकि बच्चे बहुत छोटे हैं"],"explanationHi":"आरंभिक कक्षाओं में आकलन अनौपचारिक और अवलोकन-आधारित होना चाहिए। इसका अर्थ यह नहीं कि कोई आकलन ही न हो, और हर उत्तर के लिए अंक वाली मौखिक परीक्षाएँ दूसरे रूप में परीक्षा ही हैं।"},
  {"id":"cdp-pedagogy-subjects-988","question":"Which of these is NOT a feature of a good EVS portfolio?","options":["It holds only the child’s best final products, chosen by the teacher","It contains dated samples of the child's work collected over a period","It includes the child’s own reflections on her work and progress","It contains varied forms of work such as drawings, survey sheets and notes"],"answer":0,"explanation":"A portfolio documents growth over time and the child’s own reflection; a teacher-selected showcase of best products hides the process.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"इनमें से कौन-सा अच्छे EVS पोर्टफोलियो की विशेषता नहीं है?","optionsHi":["इसमें केवल बच्चे के सर्वश्रेष्ठ अंतिम उत्पाद होते हैं, जो शिक्षक द्वारा चुने जाते हैं","इसमें एक अवधि में एकत्र किए गए बच्चे के कार्य के दिनांकित नमूने होते हैं","इसमें बच्चे के अपने कार्य और प्रगति पर उसका अपना चिंतन शामिल होता है","इसमें चित्र, सर्वेक्षण-पत्र और नोट्स जैसे विविध प्रकार के कार्य होते हैं"],"explanationHi":"पोर्टफोलियो समय के साथ विकास और बच्चे के अपने चिंतन का दस्तावेज़ बनाता है; सर्वश्रेष्ठ उत्पादों का शिक्षक-चयनित प्रदर्शन प्रक्रिया को छिपा देता है।"},
  {"id":"cdp-pedagogy-subjects-989","question":"A teacher prepares a rubric for a Class 5 project with criteria such as questions raised, information collected, explanation and presentation, and shares it with children before they begin. The main advantage of sharing it in advance is that children:","options":["can finish the project faster, with less effort and fewer mistakes","can compare their marks with children in other sections","know what good work looks like and can judge their own progress","need no further help or guidance from the teacher"],"answer":2,"explanation":"Transparent criteria let children aim at quality and judge their own work, which is the core of assessment for learning. Speed and comparison are not the point.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक शिक्षिका कक्षा 5 की परियोजना के लिए उठाए गए प्रश्न, एकत्र की गई जानकारी, व्याख्या और प्रस्तुति जैसे मानदंडों वाला रूब्रिक तैयार करती है और बच्चों के शुरू करने से पहले उनके साथ साझा करती है। इसे पहले से साझा करने का मुख्य लाभ यह है कि बच्चे:","optionsHi":["परियोजना कम प्रयास और कम गलतियों के साथ तेज़ी से पूरी कर सकते हैं","अपने अंकों की तुलना अन्य खंडों के बच्चों से कर सकते हैं","जानते हैं कि अच्छा कार्य कैसा दिखता है और अपनी प्रगति स्वयं आँक सकते हैं","उन्हें शिक्षिका से और मदद या मार्गदर्शन की आवश्यकता नहीं रहती"],"explanationHi":"पारदर्शी मानदंड बच्चों को गुणवत्ता का लक्ष्य रखने और अपने कार्य को आँकने देते हैं, जो अधिगम के लिए आकलन का मर्म है। गति और तुलना मुद्दा नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-990","question":"Assertion (A): Peer assessment in EVS group projects can help children reflect on their own work. Reason (R): Marks given by peers are always accurate and can replace the teacher’s assessment. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"Judging others’ work against criteria sharpens children’s view of their own, but peer marks are not always accurate and complement rather than replace teacher assessment.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): EVS समूह परियोजनाओं में सहपाठी-आकलन बच्चों को अपने कार्य पर चिंतन करने में मदद कर सकता है। कारण (R): साथियों द्वारा दिए गए अंक हमेशा सटीक होते हैं और शिक्षक के आकलन की जगह ले सकते हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"मानदंडों के आधार पर दूसरों के कार्य को आँकना बच्चों की अपने कार्य की दृष्टि को तीक्ष्ण करता है, पर साथियों के अंक हमेशा सटीक नहीं होते और शिक्षक के आकलन के पूरक हैं, उसकी जगह नहीं लेते।"},
  {"id":"cdp-pedagogy-subjects-991","question":"Which remark in a Class 4 child’s EVS report is most useful for the child and parents?","options":["Ravi is weak in EVS and must pay more attention in class.","Ravi scored 12 out of 25, which is below the class average.","Ravi should work harder and revise all his EVS lessons regularly at home.","Ravi records observations well but needs help giving reasons for them."],"answer":3,"explanation":"Descriptive feedback names strengths and a specific next step tied to the indicators. Labels, bare marks and general exhortations give no direction.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 4 के बच्चे की EVS रिपोर्ट में कौन-सी टिप्पणी बच्चे और अभिभावकों के लिए सबसे उपयोगी है?","optionsHi":["रवि EVS में कमज़ोर है और उसे कक्षा में अधिक ध्यान देना चाहिए।","रवि को 12 अंक मिले (कुल 25), जो कक्षा के औसत से कम हैं।","रवि को और मेहनत करनी चाहिए और घर पर अपने सभी EVS पाठों को नियमित रूप से दोहराना चाहिए।","रवि अवलोकन अच्छी तरह दर्ज करता है पर उनके कारण देने में उसे मदद चाहिए।"],"explanationHi":"वर्णनात्मक प्रतिपुष्टि संकेतकों से जुड़ी शक्तियों और विशिष्ट अगले कदम का नाम लेती है। ठप्पे, केवल अंक और सामान्य उपदेश कोई दिशा नहीं देते।"},
  {"id":"cdp-pedagogy-subjects-992","question":"A Class 5 child’s written EVS answer has several spelling mistakes, but her reasoning about why the pond dries up in summer is correct. When assessing EVS, the teacher should:","options":["deduct marks for each spelling mistake, since accuracy matters in every subject","credit her EVS understanding and note the spelling for language support separately","ask her to rewrite the answer neatly and correctly before it is assessed","give no marks, since an answer with so many errors cannot be accepted"],"answer":1,"explanation":"EVS assessment should judge the EVS learning (here, explanation). Penalising language errors would mix two different things and discourage children who are still learning to write.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक बच्ची के लिखित EVS उत्तर में वर्तनी की कई गलतियाँ हैं, पर गर्मियों में तालाब क्यों सूखता है, इस पर उसका तर्क सही है। EVS का आकलन करते समय शिक्षक को चाहिए कि:","optionsHi":["हर वर्तनी की गलती पर अंक काटे, क्योंकि शुद्धता हर विषय में मायने रखती है","उसकी EVS समझ को श्रेय दे और वर्तनी को भाषा सहयोग के लिए अलग से नोट करे","आकलन से पहले उससे उत्तर साफ और सही ढंग से फिर लिखवाए","कोई अंक न दे, क्योंकि इतनी गलतियों वाला उत्तर स्वीकार नहीं किया जा सकता"],"explanationHi":"EVS के आकलन को EVS अधिगम (यहाँ, व्याख्या) को आँकना चाहिए। भाषा की त्रुटियों को दंडित करना दो अलग चीज़ों को मिलाना होगा और उन बच्चों को हतोत्साहित करेगा जो अभी लिखना सीख रहे हैं।"},
  {"id":"cdp-pedagogy-subjects-993","question":"During an activity with bottles holding different amounts of water, which observation should the teacher record under the indicator ‘Experimentation’?","options":["Ruchi varied the water level herself to see how the sound changed","Ruchi drew all the bottles neatly in her notebook with labels","Ruchi helped her group clean up carefully after the activity","Ruchi told the class a story about a musician who played on glass bottles"],"answer":0,"explanation":"Changing a condition to see its effect is experimentation. Drawing is recording, helping is cooperation and storytelling is expression.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"अलग-अलग मात्रा में पानी वाली बोतलों की गतिविधि के दौरान शिक्षक को कौन-सा अवलोकन संकेतक ‘प्रयोग करना’ के अंतर्गत दर्ज करना चाहिए?","optionsHi":["रुचि ने स्वयं पानी का स्तर बदला यह देखने के लिए कि ध्वनि कैसे बदलती है","रुचि ने अपनी कॉपी में सभी बोतलों को नामांकन सहित साफ-साफ बनाया","रुचि ने गतिविधि के बाद अपने समूह को सावधानी से सफाई करने में मदद की","रुचि ने कक्षा को काँच की बोतलों पर बजाने वाले एक संगीतकार की कहानी सुनाई"],"explanationHi":"प्रभाव देखने के लिए कोई शर्त बदलना प्रयोग है। चित्रांकन अभिलेखन है, मदद करना सहयोग है और कहानी सुनाना अभिव्यक्ति है।"},
  {"id":"cdp-pedagogy-subjects-994","question":"Which statements about assessment in EVS are correct? I. It should be woven into the teaching–learning process. II. Questions should leave room for many correct answers drawn from children’s experience. III. Values such as concern and cooperation should be assessed through written tests only. IV. Children’s errors give useful information for teaching.","options":["I and II only","I, II and IV only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"Continuous, open and diagnostic assessment is the NCERT view. Values are seen in behaviour, so written tests alone cannot assess them; III is wrong.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"EVS में आकलन के बारे में कौन-से कथन सही हैं? I. इसे शिक्षण–अधिगम प्रक्रिया में बुना जाना चाहिए। II. प्रश्नों में बच्चों के अनुभव से निकले अनेक सही उत्तरों की गुंजाइश होनी चाहिए। III. चिंता और सहयोग जैसे मूल्यों का आकलन केवल लिखित परीक्षाओं से होना चाहिए। IV. बच्चों की त्रुटियाँ शिक्षण के लिए उपयोगी जानकारी देती हैं।","optionsHi":["केवल I और II","केवल I, II और IV","केवल II, III और IV","I, II, III और IV"],"explanationHi":"सतत, खुला और निदानात्मक आकलन NCERT का दृष्टिकोण है। मूल्य व्यवहार में दिखते हैं, इसलिए अकेली लिखित परीक्षाएँ उनका आकलन नहीं कर सकतीं; III गलत है।"},
  {"id":"cdp-pedagogy-subjects-995","question":"A teacher shows a picture of a crowded railway platform and asks Class 3 children to tell what they see and what the people might be doing. Under NCERT’s EVS indicators, picture reading is a sub-skill of:","options":["Classification","Analysis","Concern for justice and equality","Observation and recording"],"answer":3,"explanation":"NCERT lists picture reading, along with reporting, narrating and drawing, under Observation and recording.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षक भीड़ भरे रेलवे प्लेटफ़ॉर्म का चित्र दिखाता है और कक्षा 3 के बच्चों से बताने को कहता है कि वे क्या देखते हैं और लोग क्या कर रहे होंगे। NCERT के EVS संकेतकों में चित्र-पठन किसका उप-कौशल है?","optionsHi":["वर्गीकरण","विश्लेषण","न्याय और समानता के प्रति चिंता","अवलोकन और अभिलेखन"],"explanationHi":"NCERT चित्र-पठन को, प्रतिवेदन, वर्णन और चित्रांकन के साथ, अवलोकन और अभिलेखन के अंतर्गत सूचीबद्ध करता है।"},
  {"id":"cdp-pedagogy-subjects-996","question":"Which of these EVS questions tests memory rather than understanding?","options":["Name the animal that sleeps for about 17 hours a day.","Why do you think animals in very cold places have thick fur?","How is a camel suited to living in a desert, compared with a fish in a river?","What might happen to a field if there were no earthworms in it?"],"answer":0,"explanation":"The first can only be answered by recalling a fact. The others ask children to reason, compare or predict.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"इनमें से कौन-सा EVS प्रश्न समझ के बजाय स्मृति की जाँच करता है?","optionsHi":["उस जानवर का नाम बताइए जो दिन में लगभग 17 घंटे सोता है।","आपको क्या लगता है बहुत ठंडी जगहों के जानवरों के मोटे फर क्यों होते हैं?","नदी की मछली की तुलना में ऊँट रेगिस्तान में रहने के लिए कैसे अनुकूल है?","यदि किसी खेत में केंचुए न हों तो उसका क्या हो सकता है?"],"explanationHi":"पहले का उत्तर केवल तथ्य याद करके दिया जा सकता है। अन्य बच्चों से तर्क करने, तुलना करने या पूर्वानुमान लगाने को कहते हैं।"},
  {"id":"cdp-pedagogy-subjects-997","question":"A teacher collects Class 5 project files, keeps them for a month and returns them with only a mark written on the cover. The main weakness of this practice is that:","options":["projects should never be marked, only displayed in the class","a month is too short a time for proper checking of projects","the feedback comes late and gives no guidance on improving","children should mark their own files instead of the teacher"],"answer":2,"explanation":"Feedback helps learning only when it is timely and descriptive. A late bare mark tells the child nothing about what to do next.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षक कक्षा 5 की परियोजना फ़ाइलें इकट्ठा करता है, उन्हें एक महीने रखता है और केवल कवर पर लिखे अंक के साथ लौटाता है। इस अभ्यास की मुख्य कमज़ोरी यह है कि:","optionsHi":["परियोजनाओं को कभी अंक नहीं देने चाहिए, केवल कक्षा में प्रदर्शित करनी चाहिए","परियोजनाओं की उचित जाँच के लिए एक महीना बहुत कम समय है","प्रतिपुष्टि देर से आती है और सुधार के लिए कोई मार्गदर्शन नहीं देती","शिक्षक के बजाय बच्चों को अपनी फ़ाइलें स्वयं अंकित करनी चाहिए"],"explanationHi":"प्रतिपुष्टि अधिगम में तभी मदद करती है जब वह समय पर और वर्णनात्मक हो। देर से आया केवल अंक बच्चे को नहीं बताता कि आगे क्या करना है।"},
  {"id":"cdp-pedagogy-subjects-998","question":"Class 4 children make a table comparing a village house and a city flat in terms of materials, space and source of water. In NCERT’s list of EVS indicators, this mainly shows:","options":["Analysis","Classification","Expression","Experimentation"],"answer":1,"explanation":"Comparing and contrasting are sub-skills of Classification. Analysis would involve predicting or inferring from the comparison.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 4 के बच्चे सामग्री, स्थान और पानी के स्रोत की दृष्टि से गाँव के घर और शहर के फ़्लैट की तुलना करती सारणी बनाते हैं। NCERT के EVS संकेतकों की सूची में यह मुख्यतः क्या दर्शाता है?","optionsHi":["विश्लेषण","वर्गीकरण","अभिव्यक्ति","प्रयोग करना"],"explanationHi":"तुलना और विरोध करना वर्गीकरण के उप-कौशल हैं। विश्लेषण में तुलना से पूर्वानुमान या अनुमान लगाना शामिल होता।"},
  {"id":"cdp-pedagogy-subjects-999","question":"A teacher notes that a Class 5 child ‘measured the shadow of a stick at 9, 12 and 3 o’clock, put the readings in a table, and said the shadow is shortest at noon because the sun is highest in the sky then’. Which two indicators does this record show, in that order?","options":["Observation and recording, then Explanation","Classification, then Expression","Experimentation, then Concern for justice and equality","Questioning, then Discussion"],"answer":0,"explanation":"Measuring and tabulating is observation and recording; linking short shadows to the sun’s height is explanation.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षक नोट करता है कि कक्षा 5 के एक बच्चे ने ‘9, 12 और 3 बजे एक डंडे की छाया मापी, रीडिंग सारणी में रखीं, और कहा कि छाया दोपहर में सबसे छोटी होती है क्योंकि तब सूर्य आकाश में सबसे ऊँचा होता है’। यह अभिलेख किन दो संकेतकों को, उसी क्रम में, दर्शाता है?","optionsHi":["अवलोकन और अभिलेखन, फिर व्याख्या","वर्गीकरण, फिर अभिव्यक्ति","प्रयोग करना, फिर न्याय और समानता के प्रति चिंता","प्रश्न पूछना, फिर चर्चा"],"explanationHi":"मापना और सारणीबद्ध करना अवलोकन और अभिलेखन है; छोटी छायाओं को सूर्य की ऊँचाई से जोड़ना व्याख्या है।"},
  {"id":"cdp-pedagogy-subjects-1000","question":"Which of the following is an open-ended question for a Class VIII unit on local government?","options":["How many members are there in your gram panchayat, and who elects them?","At your gram sabha, which village problem would you raise, and why?","Who presides over the gram sabha, and how often must it meet?","In which year was the 73rd Amendment passed, and what did it set up?"],"answer":1,"explanation":"An open-ended question allows many valid answers and asks students to reason and justify. The others have one fixed answer to be recalled.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"स्थानीय शासन पर कक्षा VIII की इकाई के लिए इनमें से कौन-सा खुला प्रश्न है?","optionsHi":["आपकी ग्राम पंचायत में कितने सदस्य हैं, और उन्हें कौन चुनता है?","आपकी ग्राम सभा में आप गाँव की कौन-सी समस्या उठाएँगे, और क्यों?","ग्राम सभा की अध्यक्षता कौन करता है, और उसकी कितनी बार बैठक होनी चाहिए?","73वाँ संशोधन किस वर्ष पारित हुआ, और उसने क्या स्थापित किया?"],"explanationHi":"खुला प्रश्न अनेक वैध उत्तरों की अनुमति देता है और विद्यार्थियों से तर्क करने और औचित्य देने को कहता है। अन्य का एक निश्चित उत्तर है जिसे याद करना है।"},
  {"id":"cdp-pedagogy-subjects-1001","question":"A Class IX teacher shares a rubric with students before they start their project on local livelihoods, with criteria for use of sources, analysis, presentation and teamwork, each described at four levels. What is the main advantage?","options":["It lets the teacher award every student the same marks, so no one feels judged unfairly","It ensures that all projects reach the same conclusion about local livelihoods","It removes the need for the teacher to read each project in full before marking","It makes expectations clear, marking more consistent and feedback more specific"],"answer":3,"explanation":"A rubric shared in advance tells students what quality looks like, makes grading fairer across students, and gives a language for feedback. It does not standardise conclusions or replace reading the work.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा IX का एक शिक्षक स्थानीय आजीविका पर परियोजना शुरू करने से पहले विद्यार्थियों के साथ एक रूब्रिक साझा करता है, जिसमें स्रोतों के उपयोग, विश्लेषण, प्रस्तुति और टीम-कार्य के मानदंड चार स्तरों पर वर्णित हैं। इसका मुख्य लाभ क्या है?","optionsHi":["यह शिक्षक को हर विद्यार्थी को समान अंक देने देता है, ताकि कोई अनुचित आकलन महसूस न करे","यह सुनिश्चित करता है कि सभी परियोजनाएँ स्थानीय आजीविका के बारे में एक ही निष्कर्ष पर पहुँचें","यह अंक देने से पहले शिक्षक को हर परियोजना को पूरा पढ़ने की आवश्यकता से मुक्त कर देता है","यह अपेक्षाओं को स्पष्ट करता है, अंकन को अधिक सुसंगत बनाता है और प्रतिपुष्टि को अधिक विशिष्ट बनाता है"],"explanationHi":"पहले से साझा किया गया रूब्रिक विद्यार्थियों को बताता है कि गुणवत्ता कैसी होती है, विद्यार्थियों के बीच अंकन को अधिक निष्पक्ष बनाता है और प्रतिपुष्टि के लिए एक भाषा देता है। यह निष्कर्षों को एक जैसा नहीं बनाता और न ही कार्य को पढ़ने की जगह लेता है।"},
  {"id":"cdp-pedagogy-subjects-1002","question":"Assertion (A): Open-book examinations in social science can be used to test higher-order thinking.\nReason (R): When the book is open, questions that need only recall of facts become pointless, so questions must demand application and analysis.","options":["Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"An open-book test only makes sense when its questions cannot be answered by locating a line in the book. That forces questions of application, analysis and evaluation, which is why such tests can assess higher-order thinking.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"अभिकथन (A): सामाजिक विज्ञान में खुली पुस्तक परीक्षाओं का उपयोग उच्च-स्तरीय चिंतन की जाँच के लिए किया जा सकता है।\nकारण (R): जब पुस्तक खुली हो, तो केवल तथ्यों के स्मरण वाले प्रश्न निरर्थक हो जाते हैं, इसलिए प्रश्नों में अनुप्रयोग और विश्लेषण की माँग होनी चाहिए।","optionsHi":["A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"खुली पुस्तक परीक्षा तभी सार्थक है जब उसके प्रश्नों का उत्तर पुस्तक में कोई पंक्ति खोजकर न दिया जा सके। इससे अनुप्रयोग, विश्लेषण और मूल्यांकन के प्रश्न बनाना आवश्यक हो जाता है, इसीलिए ऐसी परीक्षाएँ उच्च-स्तरीय चिंतन का आकलन कर सकती हैं।"},
  {"id":"cdp-pedagogy-subjects-1003","question":"At the end of each lesson on the Indian Constitution, a teacher collects slips on which students write one thing they understood and one question they still have. How should these slips be used?","options":["To find gaps and confusions and adjust the next lesson accordingly","To award marks that count towards each student's final term grade","To identify students who should be punished for not paying attention","To send parents a written report on their child's weaknesses each week"],"answer":0,"explanation":"Exit slips are a formative tool: assessment for learning. Their value lies in guiding teaching, not in grading or blaming students.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"भारतीय संविधान पर प्रत्येक पाठ के अंत में एक शिक्षक पर्चियाँ एकत्र करता है, जिन पर विद्यार्थी एक बात जो उन्होंने समझी और एक प्रश्न जो अब भी उनके मन में है, लिखते हैं। इन पर्चियों का उपयोग कैसे किया जाना चाहिए?","optionsHi":["कमियों और भ्रांतियों का पता लगाने और उसी के अनुसार अगले पाठ को समायोजित करने के लिए","ऐसे अंक देने के लिए जो प्रत्येक विद्यार्थी के अंतिम सत्र-ग्रेड में जुड़ें","उन विद्यार्थियों की पहचान करने के लिए जिन्हें ध्यान न देने पर दंड दिया जाना चाहिए","अभिभावकों को हर सप्ताह उनके बच्चे की कमज़ोरियों की लिखित रिपोर्ट भेजने के लिए"],"explanationHi":"निर्गम पर्चियाँ एक रचनात्मक उपकरण हैं, अर्थात अधिगम के लिए आकलन। इनका मूल्य शिक्षण को दिशा देने में है, ग्रेड देने या विद्यार्थियों को दोषी ठहराने में नहीं।"},
  {"id":"cdp-pedagogy-subjects-1004","question":"A Class VIII teacher asks each student to keep a portfolio of maps they drew, a field-trip report, a source analysis and short reflections, collected over the year. What is the main strength of this method?","options":["It shows growth and a range of skills over time, not just one day's performance","It replaces the need for regular feedback, since the work speaks for itself","It is the quickest way to grade a large class, as one mark covers the whole file","It lets students include only their best test papers, which raises their marks"],"answer":0,"explanation":"Portfolios capture development across tasks and time and encourage reflection. A single test shows performance on one occasion and in one format.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा VIII का एक शिक्षक प्रत्येक विद्यार्थी से कहता है कि वह वर्ष भर में बनाए गए मानचित्रों, एक क्षेत्र-भ्रमण रिपोर्ट, एक स्रोत-विश्लेषण और संक्षिप्त चिंतनों का एक पोर्टफोलियो रखे। इस विधि की मुख्य शक्ति क्या है?","optionsHi":["यह एक दिन के प्रदर्शन के बजाय समय के साथ विकास और कौशलों की विविधता को दिखाती है","यह नियमित प्रतिपुष्टि की आवश्यकता को समाप्त कर देती है, क्योंकि कार्य स्वयं बोलता है","यह बड़ी कक्षा को ग्रेड देने का सबसे तेज़ तरीका है, क्योंकि पूरी फ़ाइल के लिए एक ही अंक पर्याप्त है","यह विद्यार्थियों को केवल अपने सबसे अच्छे परीक्षा-पत्र शामिल करने देती है, जिससे उनके अंक बढ़ते हैं"],"explanationHi":"पोर्टफोलियो विभिन्न कार्यों और समय के दौरान हुए विकास को दर्ज करते हैं और चिंतन को प्रोत्साहित करते हैं। एक परीक्षा केवल एक अवसर पर और एक प्रारूप में प्रदर्शन दिखाती है।"},
  {"id":"cdp-pedagogy-subjects-1005","question":"Which test item best assesses map skills in Class VII rather than memory?","options":["Mark Delhi, Mumbai, Kolkata and Chennai on the outline map of India and write the state each lies in.","Name the states through which the Tropic of Cancer passes, listing them in order from west to east.","Use the scale on a map of an unfamiliar district to find the distance between two villages and the river's flow direction.","List all the countries that share a land border with India and write the capital city of each one."],"answer":2,"explanation":"Applying scale, direction and symbols to an unfamiliar map tests whether students can actually use a map. Locating well-known cities or listing countries can be done from memory.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा VII में कौन-सा परीक्षा-प्रश्न स्मृति के बजाय मानचित्र-कौशल का सबसे अच्छा आकलन करता है?","optionsHi":["भारत के रेखा-मानचित्र पर दिल्ली, मुंबई, कोलकाता और चेन्नई को अंकित कीजिए और प्रत्येक जिस राज्य में स्थित है उसका नाम लिखिए।","उन राज्यों के नाम बताइए जिनसे कर्क रेखा गुज़रती है, उन्हें पश्चिम से पूर्व के क्रम में सूचीबद्ध कीजिए।","किसी अपरिचित ज़िले के मानचित्र पर पैमाने का उपयोग करके दो गाँवों के बीच की दूरी और नदी के बहाव की दिशा ज्ञात कीजिए।","उन सभी देशों की सूची बनाइए जिनकी भारत के साथ स्थल-सीमा लगती है और प्रत्येक की राजधानी लिखिए।"],"explanationHi":"किसी अपरिचित मानचित्र पर पैमाने, दिशा और संकेतों का अनुप्रयोग यह जाँचता है कि विद्यार्थी वास्तव में मानचित्र का उपयोग कर सकते हैं या नहीं। जाने-माने शहरों को ढूँढना या देशों की सूची बनाना स्मृति से किया जा सकता है।"},
  {"id":"cdp-pedagogy-subjects-1006","question":"A Class X question paper includes an extract from a 1920s pamphlet followed by questions such as 'What does the writer fear?' and 'Why might a peasant reader disagree?'. What do such source-based questions mainly assess?","options":["The ability to reproduce the textbook paragraph on the national movement accurately","The ability to memorise the pamphlet's author, date and place of publication","Reading speed, since students must finish a long extract within the time","The ability to interpret evidence, infer meaning and consider other perspectives"],"answer":3,"explanation":"Source-based questions place students in the historian's role: reading evidence, drawing inferences and comparing viewpoints. Such skills cannot be shown by reproducing textbook text.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा X के प्रश्न-पत्र में 1920 के दशक के एक पर्चे का अंश दिया गया है, जिसके बाद 'लेखक को किस बात का भय है?' और 'कोई किसान पाठक असहमत क्यों हो सकता है?' जैसे प्रश्न हैं। इस प्रकार के स्रोत-आधारित प्रश्न मुख्यतः क्या आकलन करते हैं?","optionsHi":["राष्ट्रीय आंदोलन पर पाठ्यपुस्तक के अनुच्छेद को सटीक रूप से पुनः प्रस्तुत करने की क्षमता","पर्चे के लेखक, तिथि और प्रकाशन-स्थान को याद रखने की क्षमता","पढ़ने की गति, क्योंकि विद्यार्थियों को समय में एक लंबा अंश पूरा करना होता है","साक्ष्य की व्याख्या करने, अर्थ का अनुमान लगाने और अन्य दृष्टिकोणों पर विचार करने की क्षमता"],"explanationHi":"स्रोत-आधारित प्रश्न विद्यार्थियों को इतिहासकार की भूमिका में रखते हैं: साक्ष्य पढ़ना, अनुमान लगाना और दृष्टिकोणों की तुलना करना। ऐसे कौशल पाठ्यपुस्तक का पाठ दोहराकर नहीं दिखाए जा सकते।"},
  {"id":"cdp-pedagogy-subjects-1007","question":"A teacher wants to assess whether Class VIII students show respect for differing views during discussions. Which tool is most appropriate?","options":["A written test question asking, 'Why should we respect others' views?'","A multiple-choice quiz on tolerance and respect, given once at the end of the unit","Observing discussions over several weeks, using a checklist and anecdotal notes","A one-time oral question asked by the principal during a class visit"],"answer":2,"explanation":"Attitudes show up in behaviour, so they are assessed by observing it over time. A written question tests whether students know the right answer, not whether they act on it.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"एक शिक्षक यह आकलन करना चाहता है कि कक्षा VIII के विद्यार्थी चर्चाओं के दौरान भिन्न विचारों के प्रति सम्मान दिखाते हैं या नहीं। कौन-सा उपकरण सबसे उपयुक्त है?","optionsHi":["एक लिखित परीक्षा-प्रश्न, जैसे 'हमें दूसरों के विचारों का सम्मान क्यों करना चाहिए?'","इकाई के अंत में एक बार दी जाने वाली सहिष्णुता और सम्मान पर बहुविकल्पीय प्रश्नोत्तरी","कई सप्ताहों तक चर्चाओं का अवलोकन, जाँच-सूची और घटनात्मक टिप्पणियों का उपयोग करते हुए","कक्षा-भ्रमण के दौरान प्रधानाचार्य द्वारा पूछा गया एक बार का मौखिक प्रश्न"],"explanationHi":"अभिवृत्तियाँ व्यवहार में प्रकट होती हैं, इसलिए उनका आकलन समय के साथ व्यवहार के अवलोकन से किया जाता है। लिखित प्रश्न यह जाँचता है कि विद्यार्थी सही उत्तर जानते हैं या नहीं, यह नहीं कि वे उस पर अमल करते हैं या नहीं।"},
  {"id":"cdp-pedagogy-subjects-1008","question":"After group presentations on 'Our local market', students use the class rubric to assess another group's work and give one suggestion. What is the main benefit of this peer assessment?","options":["It saves the teacher from having to assess any of the presentations herself","It helps students grasp the quality criteria and reflect on their own work","It ensures that every group gets high marks, since friends will mark generously","It replaces the need for a rubric, since students judge by their own standards"],"answer":1,"explanation":"Applying criteria to others' work helps students internalise what good work looks like and improve their own. The teacher still moderates, and the rubric is what makes peer judgements meaningful.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"'हमारा स्थानीय बाज़ार' पर समूह-प्रस्तुतियों के बाद विद्यार्थी कक्षा के रूब्रिक का उपयोग करके दूसरे समूह के कार्य का आकलन करते हैं और एक सुझाव देते हैं। इस सहपाठी आकलन का मुख्य लाभ क्या है?","optionsHi":["यह शिक्षिका को किसी भी प्रस्तुति का स्वयं आकलन करने से बचा लेता है","यह विद्यार्थियों को गुणवत्ता के मानदंड समझने और अपने कार्य पर चिंतन करने में मदद करता है","यह सुनिश्चित करता है कि प्रत्येक समूह को उच्च अंक मिलें, क्योंकि मित्र उदारता से अंक देंगे","यह रूब्रिक की आवश्यकता को समाप्त कर देता है, क्योंकि विद्यार्थी अपने स्वयं के मानकों से निर्णय करते हैं"],"explanationHi":"दूसरों के कार्य पर मानदंड लागू करने से विद्यार्थी आत्मसात करते हैं कि अच्छा कार्य कैसा दिखता है और अपने कार्य को सुधारते हैं। शिक्षक फिर भी संतुलन बनाए रखता है, और रूब्रिक ही सहपाठी-निर्णयों को सार्थक बनाता है।"},
  {"id":"cdp-pedagogy-subjects-1009","question":"Which question tests understanding rather than recall in a Class VI chapter on early farming?","options":["Name two crops grown by early farmers and the tools they used to harvest them.","Which animal was domesticated first by early humans, and in which region?","Why might people who began farming also have started living in one place?","Where was the site of Mehrgarh located, and in which present-day country is it?"],"answer":2,"explanation":"Explaining the link between farming and settled life requires reasoning about cause and effect. The other questions can be answered by recalling a fact.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"प्रारंभिक कृषि पर कक्षा VI के अध्याय में कौन-सा प्रश्न स्मरण के बजाय समझ की जाँच करता है?","optionsHi":["प्रारंभिक किसानों द्वारा उगाई जाने वाली दो फ़सलों के नाम और फ़सल काटने के लिए उनके औज़ार बताइए।","आदिमानवों द्वारा सबसे पहले कौन-सा पशु पालतू बनाया गया और किस क्षेत्र में?","जिन लोगों ने खेती शुरू की, वे एक ही स्थान पर रहने क्यों लगे होंगे?","मेहरगढ़ का स्थल कहाँ स्थित था और वह वर्तमान में किस देश में है?"],"explanationHi":"खेती और स्थायी जीवन के बीच संबंध को समझाने के लिए कारण और परिणाम पर तर्क करना पड़ता है। अन्य प्रश्नों का उत्तर किसी तथ्य को याद करके दिया जा सकता है।"},
  {"id":"cdp-pedagogy-subjects-1010","question":"A Class VII student's project report on 'Weekly markets' gets back comments. Which comment is the most useful feedback?","options":["'Good work, 7/10. The report is well organised and your title page is neatly and colourfully presented.'","'Your handwriting needs improvement; please rewrite the whole report more neatly by Monday.'","'Very nice, keep it up! You are one of the best students in the class.'","'Your vendor interviews are strong. Next, compare their answers and explain why they differ.'"],"answer":3,"explanation":"Good feedback says what was done well and gives a specific, actionable next step tied to the learning goal. A score or general praise tells the student nothing about how to improve.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा VII के एक विद्यार्थी की 'साप्ताहिक बाज़ार' पर परियोजना रिपोर्ट पर टिप्पणियाँ लौटाई जाती हैं। कौन-सी टिप्पणी सबसे उपयोगी प्रतिपुष्टि है?","optionsHi":["'अच्छा कार्य, 7/10। रिपोर्ट सुव्यवस्थित है और तुम्हारा शीर्षक-पृष्ठ साफ़ और रंगीन ढंग से प्रस्तुत किया गया है।'","'तुम्हारी लिखावट में सुधार की आवश्यकता है; कृपया सोमवार तक पूरी रिपोर्ट अधिक साफ़-सुथरी लिखकर दोबारा दो।'","'बहुत अच्छे, ऐसे ही लगे रहो! तुम कक्षा के सबसे अच्छे विद्यार्थियों में से हो।'","'विक्रेताओं के साथ तुम्हारे साक्षात्कार सशक्त हैं। अब उनके उत्तरों की तुलना करो और समझाओ कि वे भिन्न क्यों हैं।'"],"explanationHi":"अच्छी प्रतिपुष्टि बताती है कि क्या अच्छा किया गया और अधिगम-लक्ष्य से जुड़ा एक विशिष्ट, क्रियान्वित करने योग्य अगला कदम देती है। केवल अंक या सामान्य प्रशंसा विद्यार्थी को यह नहीं बताती कि सुधार कैसे करे।"},
  {"id":"cdp-pedagogy-subjects-1011","question":"A short quiz given before a chapter on Parliament reveals that many Class VIII students think 'Parliament' is the Prime Minister's house. What is the best use of this finding?","options":["Record the scores in the report card so that parents can see the starting level of each child","Plan lessons that directly address this misconception about what Parliament is","Repeat the same quiz every day until all students give the right answer","Ignore it, since the chapter itself will correct the misconception anyway"],"answer":1,"explanation":"A diagnostic assessment is meant to shape teaching. Knowing the misconception lets the teacher target it, rather than hoping it disappears or grading it.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"संसद पर अध्याय से पहले दी गई एक छोटी प्रश्नोत्तरी से पता चलता है कि कक्षा VIII के कई विद्यार्थी सोचते हैं कि 'संसद' प्रधानमंत्री का निवास है। इस निष्कर्ष का सबसे अच्छा उपयोग क्या है?","optionsHi":["अंकों को रिपोर्ट कार्ड में दर्ज करना, ताकि अभिभावक प्रत्येक बच्चे का आरंभिक स्तर देख सकें","ऐसे पाठ योजनाबद्ध करना जो संसद क्या है, इस भ्रांति को सीधे संबोधित करें","वही प्रश्नोत्तरी हर दिन दोहराना जब तक सभी विद्यार्थी सही उत्तर न दें","इसकी उपेक्षा करना, क्योंकि अध्याय स्वयं ही इस भ्रांति को दूर कर देगा"],"explanationHi":"निदानात्मक आकलन का उद्देश्य शिक्षण को दिशा देना है। भ्रांति का पता चलने पर शिक्षक उसे लक्षित कर सकता है, इस आशा में नहीं बैठता कि वह अपने आप मिट जाएगी, और न ही उस पर ग्रेड देता है।"},
  {"id":"cdp-pedagogy-subjects-1012","question":"A Class VI geography test includes: 'Describe your last holiday trip to a hill station and the changes in climate you noticed.' What is the main problem with this question?","options":["It is too easy for Class VI, since any child can write about a holiday trip","It asks about climate change, which is not part of the Class VI geography syllabus at all","It tests history rather than geography, because it asks about a past event","It assumes every child has visited a hill station, which disadvantages poorer children"],"answer":3,"explanation":"Questions that assume particular experiences are socio-economically biased: they test access, not learning. A fair question lets every child show the same skill, for example through a given description or picture.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा VI के भूगोल के एक परीक्षा-पत्र में प्रश्न है: 'किसी पर्वतीय स्थल की अपनी पिछली छुट्टी की यात्रा का वर्णन कीजिए और जो जलवायु-परिवर्तन आपने देखे उन्हें लिखिए।' इस प्रश्न की मुख्य समस्या क्या है?","optionsHi":["यह कक्षा VI के लिए बहुत आसान है, क्योंकि कोई भी बच्चा छुट्टी की यात्रा के बारे में लिख सकता है","यह जलवायु परिवर्तन के बारे में पूछता है, जो कक्षा VI के भूगोल पाठ्यक्रम का हिस्सा ही नहीं है","यह इतिहास की जाँच करता है, भूगोल की नहीं, क्योंकि यह अतीत की घटना के बारे में पूछता है","यह मानकर चलता है कि हर बच्चे ने किसी पर्वतीय स्थल की यात्रा की है, जिससे गरीब बच्चे वंचित रह जाते हैं"],"explanationHi":"जो प्रश्न विशेष अनुभवों को मानकर चलते हैं वे सामाजिक-आर्थिक रूप से पक्षपाती होते हैं: वे अधिगम की नहीं, पहुँच की जाँच करते हैं। निष्पक्ष प्रश्न प्रत्येक बच्चे को वही कौशल दिखाने देता है, उदाहरण के लिए किसी दिए गए विवरण या चित्र के माध्यम से।"},
  {"id":"cdp-pedagogy-subjects-1013","question":"A teacher sets an open-ended question: 'What could your town do to reduce waste?' She then gives full marks only to answers that match her own model answer. What is the main flaw?","options":["Open-ended questions should not be marked at all, only discussed in class","She should give everyone full marks for trying, since there is no right answer","Several answers can be valid; she should judge reasoning and evidence instead","She should have set a multiple-choice question, which is easier to mark fairly"],"answer":2,"explanation":"Marking open-ended work against one answer defeats its purpose and penalises original thinking. Criteria about reasoning and evidence keep the marking fair while allowing varied answers.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"एक शिक्षिका खुला प्रश्न पूछती है: 'आपका कस्बा कचरा कम करने के लिए क्या कर सकता है?' फिर वह पूरे अंक केवल उन्हीं उत्तरों को देती है जो उसके अपने आदर्श उत्तर से मेल खाते हैं। मुख्य दोष क्या है?","optionsHi":["खुले प्रश्नों पर अंक बिल्कुल नहीं दिए जाने चाहिए, उन पर केवल कक्षा में चर्चा होनी चाहिए","उसे प्रयास के लिए सभी को पूरे अंक दे देने चाहिए, क्योंकि कोई सही उत्तर नहीं होता","कई उत्तर वैध हो सकते हैं; उसे इसके बजाय तर्क और साक्ष्य के आधार पर निर्णय करना चाहिए","उसे बहुविकल्पीय प्रश्न पूछना चाहिए था, जिसे निष्पक्ष रूप से अंकित करना आसान है"],"explanationHi":"खुले कार्य को एक ही उत्तर के विरुद्ध अंकित करना उसके उद्देश्य को विफल कर देता है और मौलिक चिंतन को दंडित करता है। तर्क और साक्ष्य संबंधी मानदंड अंकन को निष्पक्ष रखते हैं और विविध उत्तरों की अनुमति भी देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1014","question":"Assertion (A): Continuous assessment in social science should include skills such as map reading, data interpretation and participation in discussion, not only written tests.\nReason (R): Paper-and-pencil tests capture every aspect of learning in social science.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"Many important outcomes, such as collaboration, inquiry and practical map use, do not show up fully on paper, which is why varied tools are needed. R is false, and it would in fact argue against A.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS","questionHi":"अभिकथन (A): सामाजिक विज्ञान में सतत आकलन में केवल लिखित परीक्षाएँ नहीं, बल्कि मानचित्र पढ़ना, आँकड़ों की व्याख्या और चर्चा में सहभागिता जैसे कौशल भी शामिल होने चाहिए।\nकारण (R): कागज़-पेंसिल परीक्षाएँ सामाजिक विज्ञान में अधिगम के हर पक्ष को माप लेती हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"सहयोग, जिज्ञासा-आधारित अन्वेषण और मानचित्र के व्यावहारिक उपयोग जैसे कई महत्त्वपूर्ण परिणाम कागज़ पर पूरी तरह प्रकट नहीं होते, इसीलिए विविध उपकरणों की आवश्यकता है। R असत्य है और वास्तव में A के विरुद्ध तर्क देगा।"},
  {"id":"cdp-pedagogy-subjects-1015","question":"A Class VII test gives a table of rainfall and main crops for three districts, then asks which crop a fourth district with similar rainfall might grow and why. At which level of Bloom's revised taxonomy is this question?","options":["Remembering","Applying and analysing","Creating and evaluating","Understanding only"],"answer":1,"explanation":"Students must use the pattern in the data and apply it to a new case, explaining their reasoning, which is application with analysis. The answer is not in the table to be recalled.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VII की एक परीक्षा में तीन ज़िलों के लिए वर्षा और मुख्य फ़सलों की एक तालिका दी गई है, फिर पूछा गया है कि समान वर्षा वाला चौथा ज़िला कौन-सी फ़सल उगा सकता है और क्यों। यह प्रश्न ब्लूम के संशोधित वर्गीकरण के किस स्तर पर है?","optionsHi":["स्मरण","अनुप्रयोग और विश्लेषण","सृजन और मूल्यांकन","केवल समझ"],"explanationHi":"विद्यार्थियों को आँकड़ों के प्रतिरूप का उपयोग करके उसे नए मामले पर लागू करना होता है और अपना तर्क समझाना होता है, जो विश्लेषण सहित अनुप्रयोग है। उत्तर तालिका में स्मरण करने के लिए मौजूद नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1016","question":"Class VIII students draw concept maps linking 'democracy', 'elections', 'rights', 'representation' and 'accountability'. As an assessment tool, what can such maps reveal best?","options":["How neatly students can draw the diagrams and label them within the time allowed","Whether students can recite the textbook definitions of each term","How many difficult political words each student knows and can spell","How students link ideas, and where their understanding is missing or wrong"],"answer":3,"explanation":"The links students draw, and the ones they miss or get wrong, show the structure of their understanding. That diagnostic information is hard to get from a definition test.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा VIII के विद्यार्थी 'लोकतंत्र', 'चुनाव', 'अधिकार', 'प्रतिनिधित्व' और 'जवाबदेही' को जोड़ने वाले संकल्पना-मानचित्र बनाते हैं। आकलन उपकरण के रूप में ऐसे मानचित्र सबसे अच्छी तरह क्या प्रकट कर सकते हैं?","optionsHi":["विद्यार्थी आरेख कितनी साफ़ी से बना सकते हैं और दिए गए समय में उन पर लेबल लगा सकते हैं","क्या विद्यार्थी प्रत्येक पद की पाठ्यपुस्तकीय परिभाषाएँ सुना सकते हैं","प्रत्येक विद्यार्थी कितने कठिन राजनीतिक शब्द जानता है और उनकी वर्तनी लिख सकता है","विद्यार्थी विचारों को कैसे जोड़ते हैं, और उनकी समझ कहाँ अधूरी या गलत है"],"explanationHi":"विद्यार्थी जो संबंध बनाते हैं, और जिन्हें वे छोड़ देते हैं या गलत बनाते हैं, उनकी समझ की संरचना दिखाते हैं। परिभाषा-आधारित परीक्षा से ऐसी निदानात्मक जानकारी पाना कठिन है।"},
  {"id":"cdp-pedagogy-subjects-1017","question":"Which assessment practice best matches the vision of NEP 2020 for social science?","options":["Year-end examinations that test memorised content from the whole textbook","Competency-based tasks on analysis and application, with a holistic progress card","Ranking students on a single test at the end of each term to motivate them","Assessing only through objective-type questions, which are quick and highly reliable"],"answer":1,"explanation":"NEP 2020 calls for a shift from rote, summative testing to regular, competency-based assessment of higher-order skills and a holistic, 360-degree progress card.","difficulty":"hard","source":"CTET Paper 2 · state TETs · KVS","questionHi":"सामाजिक विज्ञान के लिए NEP 2020 की परिकल्पना से कौन-सी आकलन-पद्धति सबसे अधिक मेल खाती है?","optionsHi":["वर्ष-अंत की परीक्षाएँ जो पूरी पाठ्यपुस्तक की रटी हुई सामग्री की जाँच करती हैं","विश्लेषण और अनुप्रयोग पर योग्यता-आधारित कार्य, साथ में समग्र प्रगति-पत्र","प्रेरित करने के लिए प्रत्येक सत्र के अंत में एक ही परीक्षा पर विद्यार्थियों की रैंकिंग","केवल वस्तुनिष्ठ प्रश्नों से आकलन, जो त्वरित और अत्यधिक विश्वसनीय होते हैं"],"explanationHi":"NEP 2020 रटंत और योगात्मक परीक्षण से हटकर उच्च-स्तरीय कौशलों के नियमित, योग्यता-आधारित आकलन और समग्र, 360-डिग्री प्रगति-पत्र की ओर बढ़ने का आह्वान करती है।"},
  {"id":"cdp-pedagogy-subjects-1018","question":"Which of the following statements about open-ended questions in social science are correct?\n1. They allow more than one acceptable answer.\n2. They cannot be assessed reliably, so they should be avoided in tests.\n3. Clear criteria help teachers assess them fairly.","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Open-ended questions invite varied, reasoned answers, and clear criteria such as relevance, reasoning and evidence make marking them consistent. Statement 2 confuses 'harder to mark' with 'impossible to mark'.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"सामाजिक विज्ञान में खुले प्रश्नों के बारे में निम्नलिखित में से कौन-से कथन सही हैं?\n1. वे एक से अधिक स्वीकार्य उत्तरों की अनुमति देते हैं।\n2. उनका विश्वसनीय रूप से आकलन नहीं किया जा सकता, इसलिए परीक्षाओं में उनसे बचना चाहिए।\n3. स्पष्ट मानदंड शिक्षकों को उनका निष्पक्ष आकलन करने में मदद करते हैं।","optionsHi":["केवल 1 और 3","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"खुले प्रश्न विविध, तर्कपूर्ण उत्तरों को आमंत्रित करते हैं, और प्रासंगिकता, तर्क और साक्ष्य जैसे स्पष्ट मानदंड उनका अंकन सुसंगत बनाते हैं। कथन 2 'अंकन में कठिन' को 'अंकन असंभव' समझ लेता है।"},
  {"id":"cdp-pedagogy-subjects-1019","question":"A teacher assesses a Class VIII role play on a Lok Sabha debate. Which criterion is most appropriate?","options":["How loudly and confidently each student spoke, as in a real Lok Sabha debate","Whether students wore suitable costumes and looked convincing as real members of parliament","How well their arguments reflected their character's view and parliamentary procedure","How long each student spoke, since longer speeches show more preparation"],"answer":2,"explanation":"The role play was a means of learning about parliamentary procedure and perspectives, so assessment should look at that understanding. Acting skill, costumes or speaking time are not the learning objective.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"एक शिक्षक लोकसभा की बहस पर कक्षा VIII के भूमिका-निर्वाह का आकलन करता है। कौन-सा मानदंड सबसे उपयुक्त है?","optionsHi":["प्रत्येक विद्यार्थी कितनी ज़ोर से और आत्मविश्वास से बोला, जैसा असली लोकसभा की बहस में होता है","क्या विद्यार्थियों ने उपयुक्त वेशभूषा पहनी और वे वास्तविक सांसदों जैसे विश्वसनीय लगे","उनके तर्क अपने पात्र के दृष्टिकोण और संसदीय प्रक्रिया को कितनी अच्छी तरह दर्शाते थे","प्रत्येक विद्यार्थी कितनी देर बोला, क्योंकि लंबे भाषण अधिक तैयारी दिखाते हैं"],"explanationHi":"भूमिका-निर्वाह संसदीय प्रक्रिया और दृष्टिकोणों के बारे में सीखने का साधन था, इसलिए आकलन उसी समझ को देखना चाहिए। अभिनय-कौशल, वेशभूषा या बोलने का समय अधिगम-उद्देश्य नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-1020","question":"During group work, a teacher notes: 'Riya linked the rise in onion prices at the haat to transport costs after the floods.' Notes like this, kept over time, are called:","options":["Anecdotal records","Rating scales","Cumulative scores","Achievement tests"],"answer":0,"explanation":"Anecdotal records are brief factual notes of significant behaviour or learning observed in context. They show how a child thinks in real situations, which tests often miss.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT","questionHi":"समूह-कार्य के दौरान एक शिक्षक लिखता है: 'रिया ने हाट में प्याज़ के दामों में वृद्धि को बाढ़ के बाद परिवहन-लागत से जोड़ा।' समय के साथ रखे गए ऐसे नोट कहलाते हैं:","optionsHi":["घटनात्मक अभिलेख","निर्धारण मापनियाँ","संचयी अंक","उपलब्धि परीक्षण"],"explanationHi":"घटनात्मक अभिलेख संदर्भ में देखे गए महत्त्वपूर्ण व्यवहार या अधिगम के संक्षिप्त तथ्यात्मक नोट होते हैं। वे दिखाते हैं कि बच्चा वास्तविक परिस्थितियों में कैसे सोचता है, जिसे परीक्षाएँ अक्सर छोड़ देती हैं।"},
  {"id":"cdp-pedagogy-subjects-1021","question":"A Class VIII question asks: 'If printed books and newspapers had not spread in 19th-century India, how might the social reform movements have been affected?' What mainly does this question test?","options":["Recall of the dates when the first printing presses were set up in India","Knowledge of the names of social reformers and the newspapers they ran","The ability to summarise the chapter on print culture in their own words","Reasoning about causes and consequences through a hypothetical situation"],"answer":3,"explanation":"A counterfactual question forces students to think about how one factor, print, shaped others, such as the spread of reform ideas. It cannot be answered by recall of names or dates.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा VIII का एक प्रश्न पूछता है: 'यदि 19वीं सदी के भारत में मुद्रित पुस्तकों और समाचार-पत्रों का प्रसार न हुआ होता, तो सामाजिक सुधार आंदोलन कैसे प्रभावित होते?' यह प्रश्न मुख्यतः क्या जाँचता है?","optionsHi":["भारत में पहले छापाखाने कब स्थापित हुए, उन तिथियों का स्मरण","समाज-सुधारकों और उनके द्वारा चलाए गए समाचार-पत्रों के नामों की जानकारी","मुद्रण-संस्कृति के अध्याय का अपने शब्दों में सारांश बनाने की क्षमता","काल्पनिक स्थिति के माध्यम से कारणों और परिणामों पर तर्क करना"],"explanationHi":"प्रतितथ्यात्मक प्रश्न विद्यार्थियों को यह सोचने पर विवश करता है कि मुद्रण जैसे एक कारक ने सुधार-विचारों के प्रसार जैसे अन्य कारकों को कैसे आकार दिया। इसका उत्तर नामों या तिथियों को याद करके नहीं दिया जा सकता।"},
  {"id":"cdp-pedagogy-subjects-1022","question":"After a field trip to a textile mill, how should a Class IX teacher assess what students learnt?","options":["By asking for a reflective report linking what they saw to concepts studied in class","By asking students to write the name of the mill, its owner and the year it was set up","By marking attendance on the trip, since being present shows participation","By giving marks for good behaviour on the bus and during the mill visit"],"answer":0,"explanation":"Assessment of a field trip should check whether students connected observation with concepts. Attendance, behaviour or factual details about the mill say little about learning.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कपड़ा मिल के क्षेत्र-भ्रमण के बाद कक्षा IX के शिक्षक को विद्यार्थियों ने क्या सीखा, इसका आकलन कैसे करना चाहिए?","optionsHi":["एक चिंतनशील रिपोर्ट माँगकर, जो उन्होंने जो देखा उसे कक्षा में पढ़ी गई संकल्पनाओं से जोड़ती हो","विद्यार्थियों से मिल का नाम, उसके मालिक का नाम और उसकी स्थापना का वर्ष लिखवाकर","भ्रमण में उपस्थिति दर्ज करके, क्योंकि उपस्थित होना सहभागिता दिखाता है","बस में और मिल-भ्रमण के दौरान अच्छे व्यवहार के लिए अंक देकर"],"explanationHi":"क्षेत्र-भ्रमण के आकलन में यह जाँचना चाहिए कि विद्यार्थियों ने अवलोकन को संकल्पनाओं से जोड़ा या नहीं। उपस्थिति, व्यवहार या मिल के बारे में तथ्यात्मक विवरण अधिगम के बारे में बहुत कम बताते हैं।"},
  {"id":"cdp-pedagogy-subjects-1023","question":"A Class IX teacher's test asks, 'Write ten causes of the decline of the Mughal Empire.' Which revision would best turn it into a question that assesses historical thinking?","options":["Ask for fifteen causes instead of ten, to cover the topic more completely","Ask students to write the causes in a table, with one cause in each row","Ask students to pick the cause that mattered most and justify it with evidence","Ask students to write the causes in exactly the same order as the textbook gives them"],"answer":2,"explanation":"Weighing causes, explaining their working and using evidence are the core of historical reasoning. Listing more causes or arranging them differently still only tests memory.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा IX के एक शिक्षक की परीक्षा में प्रश्न है, 'मुग़ल साम्राज्य के पतन के दस कारण लिखिए।' कौन-सा संशोधन इसे ऐतिहासिक चिंतन का आकलन करने वाले प्रश्न में सबसे अच्छी तरह बदलेगा?","optionsHi":["विषय को अधिक पूर्णता से समेटने के लिए दस के बजाय पंद्रह कारण माँगना","विद्यार्थियों से कारणों को तालिका में लिखने को कहना, प्रत्येक पंक्ति में एक कारण","विद्यार्थियों से सबसे महत्त्वपूर्ण कारण चुनने और साक्ष्य के साथ उसका औचित्य सिद्ध करने को कहना","विद्यार्थियों से कारणों को ठीक उसी क्रम में लिखने को कहना जिस क्रम में पाठ्यपुस्तक देती है"],"explanationHi":"कारणों का तुलनात्मक महत्त्व आँकना, अपने तर्क को समझाना और साक्ष्य का उपयोग करना ऐतिहासिक तर्क का मूल है। अधिक कारण सूचीबद्ध करवाना या उन्हें अलग क्रम में रखवाना फिर भी केवल स्मृति की जाँच करता है।"},
  {"id":"cdp-pedagogy-subjects-1024","question":"Which of the following are suitable tools for assessing a Class VII group project on 'Water sources in our locality'?\n1. A rubric covering planning, data collection, analysis and presentation\n2. Students' self-reflection on their contribution\n3. A viva in which each member explains part of the findings\n4. Marks based only on the decoration of the final chart","options":["1, 2 and 3 only","1 and 4 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"A rubric, self-reflection and an individual viva together capture both the process and each student's understanding. Marking decoration rewards appearance rather than learning.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"'हमारे इलाके के जल-स्रोत' पर कक्षा VII की समूह-परियोजना के आकलन के लिए निम्नलिखित में से कौन-से उपकरण उपयुक्त हैं?\n1. योजना, आँकड़ा-संग्रह, विश्लेषण और प्रस्तुति को समेटने वाला रूब्रिक\n2. विद्यार्थियों द्वारा अपने योगदान पर आत्म-चिंतन\n3. मौखिक परीक्षा, जिसमें प्रत्येक सदस्य निष्कर्षों का एक भाग समझाता है\n4. केवल अंतिम चार्ट की सजावट पर आधारित अंक","optionsHi":["केवल 1, 2 और 3","केवल 1 और 4","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"रूब्रिक, आत्म-चिंतन और व्यक्तिगत मौखिक परीक्षा मिलकर प्रक्रिया और प्रत्येक विद्यार्थी की समझ, दोनों को पकड़ते हैं। सजावट पर अंक देना अधिगम के बजाय दिखावे को पुरस्कृत करता है।"},
  {"id":"cdp-pedagogy-subjects-1025","question":"A Class 9 student writes, ‘I did a mistake in the test because of the strong rain outside.’ The grammar is fine, but the word combinations are unnatural. The area the teacher should work on, and a suitable activity, is:","options":["Spelling; dictation of commonly misspelt words from the lesson, such as ‘mistake’","Tense; practice of the simple past through sentence transformation drills","Collocation; noticing word partners like ‘make a mistake’ and ‘heavy rain’ in texts","Pronunciation; reading the sentences aloud with correct word stress and natural intonation"],"answer":2,"explanation":"Collocations are words that habitually go together; ‘do a mistake’ and ‘strong rain’ are grammatical but not what users say. Noticing and recording chunks from texts builds this knowledge.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 9 का एक विद्यार्थी लिखता है, ‘I did a mistake in the test because of the strong rain outside.’ व्याकरण ठीक है, पर शब्द-संयोजन अस्वाभाविक हैं। शिक्षक को जिस क्षेत्र पर कार्य करना चाहिए और उपयुक्त गतिविधि है:","optionsHi":["वर्तनी; पाठ से आम तौर पर गलत लिखे जाने वाले शब्दों, जैसे ‘mistake’, का श्रुतलेख","काल; वाक्य-रूपांतरण अभ्यासों द्वारा सरल भूतकाल का अभ्यास","सहप्रयोग (collocation); पाठों में ‘make a mistake’ और ‘heavy rain’ जैसे शब्द-साथियों पर ध्यान देना","उच्चारण; सही बलाघात और स्वाभाविक अनुतान के साथ वाक्यों को ज़ोर से पढ़ना"],"explanationHi":"सहप्रयोग वे शब्द हैं जो आदतन साथ आते हैं; ‘do a mistake’ और ‘strong rain’ व्याकरणिक हैं, पर प्रयोगकर्ता ऐसा नहीं कहते। पाठों से शब्द-समूहों पर ध्यान देने और उन्हें दर्ज करने से यह ज्ञान बनता है।"},
  {"id":"cdp-pedagogy-subjects-1026","question":"A teacher writes ‘monsoon’ in the middle of the board and children add connected words on branches: clouds, umbrella, puddle, farmer, flood, sowing. The main value of this semantic map is that it:","options":["Teaches the spelling of each word through repeated copying from the board","Links new words to related ideas, which aids understanding and recall","Replaces the need for children to read about the monsoon in the textbook","Tests how many words each child already knows by the end of the lesson"],"answer":1,"explanation":"Words are stored and recalled in networks of meaning; mapping a topic connects new words to known ones and to each other, which supports retention and use.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"एक शिक्षक बोर्ड के बीच में ‘monsoon’ लिखता है और बच्चे शाखाओं पर जुड़े शब्द जोड़ते हैं: clouds, umbrella, puddle, farmer, flood, sowing। इस अर्थगत मानचित्र का मुख्य मूल्य यह है कि यह:","optionsHi":["बोर्ड से बार-बार नकल करवाकर प्रत्येक शब्द की वर्तनी सिखाता है","नए शब्दों को संबंधित विचारों से जोड़ता है, जिससे समझ और स्मरण में सहायता मिलती है","बच्चों को पाठ्यपुस्तक में मानसून के बारे में पढ़ने की आवश्यकता को समाप्त कर देता है","पाठ के अंत तक प्रत्येक बच्चा कितने शब्द पहले से जानता है, इसकी जाँच करता है"],"explanationHi":"शब्द अर्थ के जालों में संगृहीत और याद किए जाते हैं; किसी विषय का मानचित्र बनाने से नए शब्द ज्ञात शब्दों से और आपस में जुड़ते हैं, जो धारण और प्रयोग में सहायक होता है।"},
  {"id":"cdp-pedagogy-subjects-1027","question":"A Class 7 student understands ‘reluctant’ whenever she meets it in reading but never uses it in her own speech or writing. To move the word into her productive vocabulary, the teacher should:","options":["Make her copy its dictionary meaning five times so it stays in memory","Give her a list of twenty more difficult synonyms to learn by heart","Ask her to underline the word each time it appears in her reading, to notice it more","Set speaking and writing tasks that need the word, so she uses it repeatedly"],"answer":3,"explanation":"Receptive knowledge becomes productive through repeated, meaningful use. Copying definitions or noticing the word again keeps it receptive.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 7 की एक विद्यार्थी ‘reluctant’ शब्द को पढ़ते समय जब भी देखती है तो समझ लेती है, पर अपनी बोली या लेखन में उसका प्रयोग कभी नहीं करती। इस शब्द को उसकी उत्पादक शब्दावली में लाने के लिए शिक्षक को चाहिए कि वह:","optionsHi":["उससे इसका शब्दकोशीय अर्थ पाँच बार लिखवाए ताकि वह याद रहे","उसे सीखने के लिए बीस और कठिन समानार्थी शब्दों की सूची दे जिन्हें वह रट ले","जब भी यह शब्द उसके पठन में आए, उसे रेखांकित करने को कहे, ताकि वह उस पर अधिक ध्यान दे","ऐसे बोलने और लिखने के कार्य दे जिनमें इस शब्द की आवश्यकता हो, ताकि वह उसे बार-बार प्रयोग करे"],"explanationHi":"ग्रहणशील ज्ञान बार-बार के सार्थक प्रयोग से उत्पादक बनता है। परिभाषाएँ लिखना या शब्द पर दोबारा ध्यान देना उसे ग्रहणशील ही बनाए रखता है।"},
  {"id":"cdp-pedagogy-subjects-1028","question":"Consider these statements about vocabulary learning: I. Meeting a word’s dictionary meaning once is usually enough to learn it. II. Knowing a word includes its form, meaning, usual partners and the situations it suits. III. Words met in meaningful contexts are generally retained better than words in isolated lists. Which are correct?","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":1,"explanation":"Word knowledge is multi-dimensional and builds up over many encounters in varied contexts, so a single meeting with a definition is rarely enough.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"शब्दावली-अधिगम के बारे में इन कथनों पर विचार कीजिए: I. किसी शब्द का शब्दकोशीय अर्थ एक बार देख लेना उसे सीखने के लिए प्रायः पर्याप्त है। II. किसी शब्द को जानने में उसका रूप, अर्थ, सामान्य साथी शब्द और वे परिस्थितियाँ शामिल हैं जिनमें वह उपयुक्त होता है। III. सार्थक संदर्भों में मिले शब्द अलग-अलग सूचियों में दिए शब्दों की तुलना में सामान्यतः बेहतर याद रहते हैं। कौन-से सही हैं?","optionsHi":["केवल I और II","केवल II और III","केवल I और III","I, II और III"],"explanationHi":"शब्द-ज्ञान बहुआयामी होता है और विविध संदर्भों में अनेक बार मिलने से बनता है, इसलिए परिभाषा से एक बार मिलना शायद ही पर्याप्त होता है।"},
  {"id":"cdp-pedagogy-subjects-1029","question":"Reading ‘The boat drifted towards the bank of the river’, a Class 6 student looks up ‘bank’ and copies the first meaning: ‘an organisation that keeps money’. The teacher should mainly help him to:","options":["Stop using the dictionary, since it only confuses learners at this stage","Always copy the first meaning, as dictionaries list the most common one first","Pick the meaning that fits the context, as many words have several meanings","Learn the spelling of ‘bank’ thoroughly before checking any of its meanings"],"answer":2,"explanation":"Dictionary skills include handling polysemy, scanning the entries and testing each meaning against the context of the sentence.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"‘The boat drifted towards the bank of the river’ पढ़ते समय कक्षा 6 का एक विद्यार्थी ‘bank’ को शब्दकोश में देखता है और पहला अर्थ उतार लेता है: ‘an organisation that keeps money’। शिक्षक को मुख्य रूप से उसकी किसमें सहायता करनी चाहिए:","optionsHi":["शब्दकोश का प्रयोग बंद करने में, क्योंकि इस स्तर पर यह केवल भ्रमित करता है","हमेशा पहला अर्थ उतारने में, क्योंकि शब्दकोश सबसे आम अर्थ पहले देते हैं","संदर्भ में फिट बैठने वाला अर्थ चुनने में, क्योंकि कई शब्दों के अनेक अर्थ होते हैं","‘bank’ की वर्तनी अच्छी तरह सीखने में, इसके किसी भी अर्थ को देखने से पहले"],"explanationHi":"शब्दकोश-कौशल में बहुअर्थता को सँभालना, प्रविष्टियों को देखना और प्रत्येक अर्थ को वाक्य के संदर्भ में परखना शामिल है।"},
  {"id":"cdp-pedagogy-subjects-1030","question":"A teacher writes ‘thin’, ‘slim’, ‘skinny’ and ‘bony’ on cards, and Class 8 students arrange them on a line from the most flattering to the most unflattering, then discuss when each could be used. This activity mainly develops awareness of:","options":["Spelling patterns in English adjectives that describe body shape","The grammatical class of each word and how it is used in a sentence","Pronunciation and stress patterns of two-syllable English adjectives","Connotation, the shades of feeling that separate near-synonyms"],"answer":3,"explanation":"Placing near-synonyms on a cline makes learners notice that words with similar meanings carry different feelings and suit different situations.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"एक शिक्षक कार्डों पर ‘thin’, ‘slim’, ‘skinny’ और ‘bony’ लिखता है, और कक्षा 8 के विद्यार्थी उन्हें सबसे प्रशंसात्मक से सबसे अप्रशंसात्मक तक एक रेखा पर व्यवस्थित करते हैं, फिर चर्चा करते हैं कि प्रत्येक का प्रयोग कब हो सकता है। यह गतिविधि मुख्यतः किसकी जागरूकता विकसित करती है:","optionsHi":["शारीरिक बनावट का वर्णन करने वाले अंग्रेज़ी विशेषणों के वर्तनी-प्रतिरूप","प्रत्येक शब्द का व्याकरणिक वर्ग और वाक्य में उसका प्रयोग","दो-अक्षर वाले अंग्रेज़ी विशेषणों के उच्चारण और बलाघात के प्रतिरूप","अर्थ-सहचर (connotation), यानी वे भावनात्मक छटाएँ जो निकट-समानार्थी शब्दों को अलग करती हैं"],"explanationHi":"निकट-समानार्थी शब्दों को एक क्रमिक रेखा पर रखने से अधिगमकर्ता ध्यान देते हैं कि समान अर्थ वाले शब्द अलग भावनाएँ रखते हैं और अलग परिस्थितियों में उपयुक्त होते हैं।"},
  {"id":"cdp-pedagogy-subjects-1031","question":"What is the most effective way to teach the abstract word ‘honesty’ to Class 4 children?","options":["Through a story, then discussing examples and non-examples from their lives","Writing the dictionary definition on the board and having children learn it","Giving its Hindi equivalent, ‘imaandari’, and moving on to the next word","Showing a picture of an honest person and saying the word several times"],"answer":0,"explanation":"Abstract words cannot be pointed to; meaning is built through situations, examples and contrasts that children can relate to. A single picture of a person cannot show honesty.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 4 के बच्चों को ‘honesty’ जैसा अमूर्त शब्द सिखाने का सबसे प्रभावी तरीका क्या है?","optionsHi":["कहानी के माध्यम से, फिर उनके जीवन से उदाहरणों और अनुदाहरणों पर चर्चा करके","बोर्ड पर शब्दकोशीय परिभाषा लिखकर और बच्चों से उसे याद करवाकर","इसका हिंदी पर्याय ‘imaandari’ बताकर और अगले शब्द पर बढ़ जाकर","किसी ईमानदार व्यक्ति का चित्र दिखाकर और शब्द को कई बार बोलकर"],"explanationHi":"अमूर्त शब्दों की ओर इशारा नहीं किया जा सकता; अर्थ उन परिस्थितियों, उदाहरणों और विरोधाभासों से बनता है जिनसे बच्चे जुड़ सकें। किसी व्यक्ति का एक चित्र ईमानदारी नहीं दिखा सकता।"},
  {"id":"cdp-pedagogy-subjects-1032","question":"Read the sentence: ‘The arid region, which receives almost no rainfall, supports very few crops.’ The clue that helps a reader work out the meaning of ‘arid’ is of which type?","options":["Contrast clue","Example clue","Definition or restatement clue","Clue from the reader’s general knowledge only"],"answer":2,"explanation":"The relative clause ‘which receives almost no rainfall’ restates the meaning of ‘arid’ directly. A contrast clue would signal an opposite with words like ‘unlike’ or ‘but’.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"वाक्य पढ़िए: ‘The arid region, which receives almost no rainfall, supports very few crops.’ पाठक को ‘arid’ का अर्थ निकालने में मदद करने वाला संकेत किस प्रकार का है?","optionsHi":["विरोध-संकेत","उदाहरण-संकेत","परिभाषा या पुनःकथन-संकेत","केवल पाठक के सामान्य ज्ञान से मिलने वाला संकेत"],"explanationHi":"सापेक्ष उपवाक्य ‘which receives almost no rainfall’ सीधे ‘arid’ का अर्थ दोहराता है। विरोध-संकेत ‘unlike’ या ‘but’ जैसे शब्दों से विपरीत का संकेत देता।"},
  {"id":"cdp-pedagogy-subjects-1033","question":"A Class 7 teacher introduces ‘a piece of cake’ and ‘once in a blue moon’. Which approach is most effective?","options":["Avoid idioms until Class 10, since younger learners cannot understand them","List twenty idioms with meanings for students to learn by heart for the test","Explain each word of the idiom separately so that its literal meaning becomes clear first","Use them in a story, discuss their non-literal meaning and compare Hindi idioms"],"answer":3,"explanation":"Idioms are fixed expressions whose meaning is not the sum of their words; context and comparison with equivalents like ‘baayen haath ka khel’ make their figurative sense clear.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 7 का एक शिक्षक ‘a piece of cake’ और ‘once in a blue moon’ का परिचय देता है। कौन-सा उपागम सबसे प्रभावी है?","optionsHi":["कक्षा 10 तक मुहावरों से बचना, क्योंकि छोटे अधिगमकर्ता उन्हें नहीं समझ सकते","परीक्षा के लिए रटने हेतु अर्थों सहित बीस मुहावरों की सूची देना","मुहावरे के प्रत्येक शब्द को अलग-अलग समझाना, ताकि पहले उसका शाब्दिक अर्थ स्पष्ट हो जाए","उन्हें कहानी में प्रयोग करना, उनके अलाक्षणिक अर्थ पर चर्चा करना और हिंदी मुहावरों से तुलना करना"],"explanationHi":"मुहावरे स्थिर अभिव्यक्तियाँ हैं जिनका अर्थ उनके शब्दों के योग से नहीं बनता; संदर्भ और ‘baayen haath ka khel’ जैसे समतुल्यों से तुलना उनके लाक्षणिक अर्थ को स्पष्ट करती है।"},
  {"id":"cdp-pedagogy-subjects-1034","question":"Class 7 pairs are planning a poster for a task. One student keeps saying ‘more better’ while they compare designs. The teacher briefly points out ‘better, not more better’ and lets them continue the task. This is an example of:","options":["Focus on form: brief attention to a form while the focus stays on meaning","Focus on forms: teaching grammar items one by one from a structural syllabus","The grammar-translation method, since a grammatical rule is being corrected","The audio-lingual method, since the error is corrected immediately as a habit"],"answer":0,"explanation":"Long distinguished ‘focus on form’, brief attention to language arising during meaning-focused work, from ‘focus on forms’, a syllabus of discrete grammar items taught in isolation.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 7 की जोड़ियाँ किसी कार्य के लिए पोस्टर की योजना बना रही हैं। डिज़ाइनों की तुलना करते समय एक विद्यार्थी बार-बार ‘more better’ कहता है। शिक्षक संक्षेप में बताता है ‘better, not more better’ और उन्हें कार्य जारी रखने देता है। यह किसका उदाहरण है:","optionsHi":["रूप पर ध्यान (focus on form): किसी रूप पर संक्षिप्त ध्यान, जबकि मुख्य ध्यान अर्थ पर बना रहता है","रूपों पर ध्यान (focus on forms): संरचनात्मक पाठ्यक्रम से व्याकरण की इकाइयों को एक-एक करके पढ़ाना","व्याकरण-अनुवाद विधि, क्योंकि व्याकरण के नियम को सुधारा जा रहा है","श्रव्य-भाषिक विधि, क्योंकि त्रुटि को आदत के रूप में तुरंत सुधारा जा रहा है"],"explanationHi":"लॉन्ग ने ‘focus on form’, यानी अर्थ-केंद्रित कार्य के दौरान उभरने वाली भाषा पर संक्षिप्त ध्यान, को ‘focus on forms’ से अलग बताया, जो अलग-थलग पढ़ाई जाने वाली व्याकरणिक इकाइयों का पाठ्यक्रम है।"},
  {"id":"cdp-pedagogy-subjects-1035","question":"A teacher gives Class 8 pairs a set of sentences using ‘since’ and ‘for’ (‘since 2019’, ‘for three years’) and asks them to work out when each is used. They are not asked to produce new sentences. This is best described as:","options":["A transformation drill that builds automatic habits through repetition","A consciousness-raising task that helps learners notice and understand a rule","A free production activity that develops fluency with the present perfect","A dictation exercise that tests listening and the accurate spelling of time words"],"answer":1,"explanation":"Consciousness-raising tasks (Ellis) lead learners to discover a grammatical feature from data, building explicit understanding that can later help them notice it in input.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"एक शिक्षक कक्षा 8 की जोड़ियों को ‘since’ और ‘for’ वाले वाक्यों का एक समूह (‘since 2019’, ‘for three years’) देता है और उनसे यह पता लगाने को कहता है कि प्रत्येक का प्रयोग कब होता है। उनसे नए वाक्य बनाने को नहीं कहा जाता। इसका सबसे अच्छा वर्णन है:","optionsHi":["रूपांतरण अभ्यास, जो पुनरावृत्ति से स्वचालित आदतें बनाता है","चेतना-जागरण कार्य (consciousness-raising task), जो अधिगमकर्ताओं को किसी नियम पर ध्यान देने और उसे समझने में मदद करता है","मुक्त उत्पादन गतिविधि, जो पूर्ण वर्तमान काल के साथ प्रवाह विकसित करती है","श्रुतलेख अभ्यास, जो श्रवण और समय-सूचक शब्दों की सही वर्तनी की जाँच करता है"],"explanationHi":"चेतना-जागरण कार्य (एलिस) अधिगमकर्ताओं को आँकड़ों से किसी व्याकरणिक विशेषता की खोज कराते हैं, जिससे स्पष्ट समझ बनती है जो बाद में उसे निवेश (input) में पहचानने में सहायक हो सकती है।"},
  {"id":"cdp-pedagogy-subjects-1036","question":"A Class 6 student says, ‘She don’t like milk.’ Match each teacher response with the type of corrective feedback: 1. ‘Oh, she doesn’t like milk? Why not?’ 2. ‘Sorry? Could you say that again?’ 3. ‘Is “don’t” right with “she”? What do we use with he, she and it?’ 4. ‘She…?’ (pausing for the student to finish); a. Clarification request b. Metalinguistic feedback c. Elicitation d. Recast","options":["1-d, 2-a, 3-b, 4-c","1-a, 2-d, 3-b, 4-c","1-d, 2-a, 3-c, 4-b","1-b, 2-a, 3-d, 4-c"],"answer":0,"explanation":"A recast reformulates the error correctly within the conversation; a clarification request signals a problem; metalinguistic feedback comments on the rule; elicitation prompts the learner to supply the form.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 6 का एक विद्यार्थी कहता है, ‘She don’t like milk.’ शिक्षक की प्रत्येक प्रतिक्रिया को सुधारात्मक प्रतिपुष्टि के प्रकार से मिलाइए: 1. ‘Oh, she doesn’t like milk? Why not?’ 2. ‘Sorry? Could you say that again?’ 3. ‘Is “don’t” right with “she”? What do we use with he, she and it?’ 4. ‘She…?’ (विद्यार्थी के वाक्य पूरा करने के लिए रुकते हुए); a. स्पष्टीकरण अनुरोध b. भाषा-विषयक प्रतिपुष्टि c. उद्भावन (elicitation) d. पुनःप्रस्तुति (recast)","optionsHi":["1-d, 2-a, 3-b, 4-c","1-a, 2-d, 3-b, 4-c","1-d, 2-a, 3-c, 4-b","1-b, 2-a, 3-d, 4-c"],"explanationHi":"पुनःप्रस्तुति बातचीत के भीतर ही त्रुटि को सही रूप में दोहराती है; स्पष्टीकरण अनुरोध समस्या का संकेत देता है; भाषा-विषयक प्रतिपुष्टि नियम पर टिप्पणी करती है; उद्भावन अधिगमकर्ता को सही रूप स्वयं बोलने के लिए प्रेरित करता है।"},
  {"id":"cdp-pedagogy-subjects-1037","question":"Which plan for teaching the passive voice to Class 8 is most in line with teaching grammar in context?","options":["Write the rule for changing active to passive and give twenty sentences for students to convert","Teach all twelve tenses in the passive voice in a single period using a chart","Read a text on tea processing, notice the passives and discuss why the doer is omitted","Ask students to memorise the passive forms of the verb ‘to write’ in every tense"],"answer":2,"explanation":"Process descriptions and news reports use the passive naturally; seeing it in such texts shows its function (the doer is unknown or unimportant), which mechanical conversion exercises do not.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 8 को कर्मवाच्य पढ़ाने की कौन-सी योजना संदर्भ में व्याकरण पढ़ाने के सबसे अनुरूप है?","optionsHi":["कर्तृवाच्य से कर्मवाच्य बदलने का नियम लिखना और विद्यार्थियों को बदलने के लिए बीस वाक्य देना","एक ही कालांश में चार्ट की सहायता से सभी बारह कालों में कर्मवाच्य पढ़ाना","चाय-प्रसंस्करण पर एक पाठ पढ़ना, कर्मवाच्य के प्रयोगों को पहचानना और चर्चा करना कि कर्ता को क्यों छोड़ा जाता है","विद्यार्थियों से हर काल में ‘to write’ क्रिया के कर्मवाच्य रूप याद करवाना"],"explanationHi":"प्रक्रिया-विवरण और समाचार-रिपोर्टों में कर्मवाच्य स्वाभाविक रूप से आता है; ऐसे पाठों में उसे देखने से उसका प्रकार्य (कर्ता अज्ञात या महत्त्वहीन है) स्पष्ट होता है, जो यांत्रिक रूपांतरण अभ्यासों से नहीं होता।"},
  {"id":"cdp-pedagogy-subjects-1038","question":"A Class 3 teacher spends many periods making children define ‘noun’, ‘pronoun’ and ‘adjective’ and classify nouns as common, proper, collective and abstract. In the light of NCF 2005, the main problem is that:","options":["Class 3 is too late to start such classification; it should begin in Class 1 itself","Learning grammar terms at this stage does little for children’s actual language use","Grammar should never be part of a primary language syllabus in any form","These definitions should be taught in the mother tongue, not in English"],"answer":1,"explanation":"Young learners develop grammar through rich input and use; definitions and labels add little to their ability to speak, read or write. Grammar is not banned, but taught through meaningful use.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 3 का एक शिक्षक कई कालांश बच्चों से ‘noun’, ‘pronoun’ और ‘adjective’ की परिभाषा बुलवाने और संज्ञाओं को सामान्य, व्यक्तिवाचक, समूहवाचक और भाववाचक में वर्गीकृत करवाने में लगाता है। NCF 2005 के आलोक में मुख्य समस्या यह है कि:","optionsHi":["कक्षा 3 ऐसे वर्गीकरण के लिए बहुत देर है; यह कक्षा 1 से ही शुरू होना चाहिए","इस अवस्था में व्याकरण के पद सीखने से बच्चों के वास्तविक भाषा-प्रयोग में बहुत कम सहायता मिलती है","प्राथमिक भाषा पाठ्यक्रम में व्याकरण किसी भी रूप में कभी शामिल नहीं होना चाहिए","इन परिभाषाओं को अंग्रेज़ी में नहीं, मातृभाषा में पढ़ाया जाना चाहिए"],"explanationHi":"छोटे अधिगमकर्ता समृद्ध निवेश और प्रयोग से व्याकरण विकसित करते हैं; परिभाषाएँ और नामपट्टिकाएँ उनकी बोलने, पढ़ने या लिखने की क्षमता में बहुत कम जोड़ती हैं। व्याकरण निषिद्ध नहीं है, पर उसे सार्थक प्रयोग के माध्यम से पढ़ाया जाना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1039","question":"A teacher shows a picture of dark clouds and says, ‘It is going to rain.’ Students then repeat and practise similar sentences with picture cues, and finally talk freely in pairs about their plans for the weekend. This lesson follows the:","options":["Test–teach–test model","Task-based language teaching framework","Grammar-translation model","Present–practise–produce model"],"answer":3,"explanation":"PPP presents a form in a situation, gives controlled practice, then moves to freer production. In a task-based lesson the task would come first and form-focus afterwards.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"एक शिक्षक काले बादलों का चित्र दिखाता है और कहता है, ‘It is going to rain.’ फिर विद्यार्थी चित्र-संकेतों के साथ ऐसे ही वाक्य दोहराते और अभ्यास करते हैं, और अंत में जोड़ियों में सप्ताहांत की अपनी योजनाओं के बारे में स्वतंत्र रूप से बात करते हैं। यह पाठ किसका अनुसरण करता है:","optionsHi":["परीक्षा–शिक्षण–परीक्षा (test–teach–test) मॉडल","कार्य-आधारित भाषा शिक्षण की रूपरेखा","व्याकरण-अनुवाद मॉडल","प्रस्तुति–अभ्यास–उत्पादन (present–practise–produce) मॉडल"],"explanationHi":"PPP में किसी रूप को परिस्थिति में प्रस्तुत किया जाता है, नियंत्रित अभ्यास दिया जाता है, फिर अधिक स्वतंत्र उत्पादन की ओर बढ़ा जाता है। कार्य-आधारित पाठ में कार्य पहले आता और रूप पर ध्यान बाद में दिया जाता।"},
  {"id":"cdp-pedagogy-subjects-1040","question":"A teacher first asks Class 7 students to compare two cities using whatever language they have, notes the problems they have with comparatives, teaches those forms, and then gives a similar comparison task. This lesson design is called:","options":["Test–teach–test","Present–practise–produce","Grammar-translation","Total Physical Response"],"answer":0,"explanation":"Test–teach–test starts by finding out what learners can already do, teaches what is missing, and checks again, so teaching responds to actual needs.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"एक शिक्षक पहले कक्षा 7 के विद्यार्थियों से कहता है कि उनके पास जो भी भाषा है उसी से दो शहरों की तुलना करें, तुलनात्मक रूपों में उन्हें होने वाली समस्याओं को नोट करता है, वे रूप सिखाता है, और फिर वैसा ही तुलना-कार्य देता है। इस पाठ-रचना को कहते हैं:","optionsHi":["परीक्षा–शिक्षण–परीक्षा (test–teach–test)","प्रस्तुति–अभ्यास–उत्पादन (present–practise–produce)","व्याकरण-अनुवाद","पूर्ण शारीरिक प्रतिक्रिया (Total Physical Response)"],"explanationHi":"परीक्षा–शिक्षण–परीक्षा पहले यह पता लगाता है कि अधिगमकर्ता पहले से क्या कर सकते हैं, जो कमी है उसे सिखाता है, और फिर जाँचता है, इस प्रकार शिक्षण वास्तविक आवश्यकताओं के अनुरूप चलता है।"},
  {"id":"cdp-pedagogy-subjects-1041","question":"While reading a story, a Class 8 teacher asks, ‘Why did the writer say “It might rain” here and not “It will rain”? What difference does it make?’ The teacher is mainly treating grammar as:","options":["A system of choices that writers use to express meaning","A set of rules to be memorised for examinations","A list of errors that students must avoid","Something that should be taught only through translation"],"answer":0,"explanation":"Asking why a writer chose a form treats grammar functionally, as a resource for making meaning, here degrees of certainty, rather than as rules in isolation.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कहानी पढ़ते समय कक्षा 8 का शिक्षक पूछता है, ‘लेखक ने यहाँ “It might rain” क्यों कहा, “It will rain” क्यों नहीं? इससे क्या अंतर पड़ता है?’ शिक्षक मुख्यतः व्याकरण को किस रूप में देख रहा है:","optionsHi":["विकल्पों की एक व्यवस्था, जिसका उपयोग लेखक अर्थ व्यक्त करने के लिए करते हैं","परीक्षाओं के लिए याद किए जाने वाले नियमों का एक समूह","त्रुटियों की एक सूची जिनसे विद्यार्थियों को बचना चाहिए","ऐसी चीज़ जिसे केवल अनुवाद के माध्यम से पढ़ाया जाना चाहिए"],"explanationHi":"यह पूछना कि लेखक ने कोई रूप क्यों चुना, व्याकरण को प्रकार्यात्मक रूप से, अर्थ-निर्माण के संसाधन के रूप में (यहाँ निश्चितता की मात्रा), देखना है, न कि अलग-थलग नियमों के रूप में।"},
  {"id":"cdp-pedagogy-subjects-1042","question":"A Class 9 student writes, ‘I am knowing him since my childhood.’ Which analysis of the sentence is most accurate?","options":["Only a spelling error: ‘knowing’ should be written with a double ‘n’","Only a preposition error: ‘since’ should be ‘from’, as in ‘from my childhood days’","Two errors: stative ‘know’ in the progressive, and present for present perfect","Only an article error: ‘the’ should replace ‘my’ before ‘childhood’"],"answer":2,"explanation":"‘Know’ is a stative verb not normally used in the progressive, and a state continuing from the past to now needs the present perfect: ‘I have known him since my childhood’. ‘Since’ is correct.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 9 का एक विद्यार्थी लिखता है, ‘I am knowing him since my childhood.’ इस वाक्य का कौन-सा विश्लेषण सबसे सटीक है?","optionsHi":["केवल वर्तनी की त्रुटि: ‘knowing’ में ‘n’ दोहरा लिखा जाना चाहिए","केवल पूर्वसर्ग की त्रुटि: ‘since’ के स्थान पर ‘from’ होना चाहिए, जैसे ‘from my childhood days’","दो त्रुटियाँ: अवस्थावाचक (stative) ‘know’ का सतत रूप में प्रयोग, और पूर्ण वर्तमान के स्थान पर वर्तमान","केवल उपपद की त्रुटि: ‘childhood’ से पहले ‘my’ के स्थान पर ‘the’ आना चाहिए"],"explanationHi":"‘Know’ अवस्थावाचक क्रिया है जिसका प्रायः सतत रूप में प्रयोग नहीं होता, और अतीत से अब तक चली आ रही अवस्था के लिए पूर्ण वर्तमान चाहिए: ‘I have known him since my childhood’। ‘Since’ सही है।"},
  {"id":"cdp-pedagogy-subjects-1043","question":"In a ‘Find someone who…’ activity, Class 6 students move around asking, ‘Have you ever visited the Taj Mahal?’ and ‘Have you ever eaten a jackfruit?’ to fill in a survey sheet with names. This activity mainly shows that:","options":["Grammar can only be practised properly through written exercises","A structure can be practised through purposeful communication","Question forms should be taught through translation into Hindi","Speaking practice is useful only for advanced learners of English"],"answer":1,"explanation":"Learners repeat the present perfect question many times, but for a real purpose (finding people), combining practice of form with meaningful interaction.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"‘Find someone who…’ गतिविधि में कक्षा 6 के विद्यार्थी नामों के साथ सर्वेक्षण-पत्र भरने के लिए घूम-घूमकर पूछते हैं, ‘Have you ever visited the Taj Mahal?’ और ‘Have you ever eaten a jackfruit?’ यह गतिविधि मुख्यतः क्या दर्शाती है:","optionsHi":["व्याकरण का ठीक से अभ्यास केवल लिखित अभ्यासों से ही हो सकता है","किसी संरचना का अभ्यास उद्देश्यपूर्ण संप्रेषण के माध्यम से किया जा सकता है","प्रश्न-रूप हिंदी में अनुवाद के माध्यम से पढ़ाए जाने चाहिए","बोलने का अभ्यास केवल अंग्रेज़ी के उन्नत अधिगमकर्ताओं के लिए उपयोगी है"],"explanationHi":"अधिगमकर्ता पूर्ण वर्तमान का प्रश्न कई बार दोहराते हैं, पर वास्तविक उद्देश्य (लोगों को खोजना) के लिए, जिससे रूप के अभ्यास और सार्थक अंतःक्रिया का मेल होता है।"},
  {"id":"cdp-pedagogy-subjects-1044","question":"A Hindi-speaking Class 5 child says, ‘Please open the light’ and ‘Close the fan.’ These errors most likely arise from:","options":["Overgeneralisation of an English grammar rule","Lack of knowledge of the English tense system","A slip of the tongue that the child can self-correct","Transfer of word combinations from the home language"],"answer":3,"explanation":"Hindi uses ‘kholna’ and ‘band karna’ with lights and fans; the child transfers these collocations into English. Teaching ‘switch on / switch off’ as chunks addresses it.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 5 का एक हिंदी-भाषी बच्चा कहता है, ‘Please open the light’ और ‘Close the fan.’ ये त्रुटियाँ सबसे अधिक संभावना से किससे उत्पन्न होती हैं:","optionsHi":["अंग्रेज़ी व्याकरण के किसी नियम का अतिसामान्यीकरण","अंग्रेज़ी काल-व्यवस्था के ज्ञान का अभाव","जीभ की फिसलन, जिसे बच्चा स्वयं सुधार सकता है","घर की भाषा से शब्द-संयोजनों का अंतरण (transfer)"],"explanationHi":"हिंदी में बत्ती और पंखे के साथ ‘खोलना’ और ‘बंद करना’ का प्रयोग होता है; बच्चा इन सहप्रयोगों को अंग्रेज़ी में अंतरित कर देता है। ‘switch on / switch off’ को शब्द-समूह के रूप में सिखाने से इसका समाधान होता है।"},
  {"id":"cdp-pedagogy-subjects-1045","question":"A Class 3 teacher asks children to say ‘butterfly’ in their own languages (titli, prajapati, phulpakhru…) and makes a multilingual word chart. Which is the main pedagogical value?","options":["It mainly helps the teacher learn the children’s languages for later use","It values children’s languages and links the new word to known concepts","It replaces the need to teach the English word, since children know the concept","It is useful only in classes where every child speaks a different language"],"answer":1,"explanation":"Using home languages as a resource validates children’s identities, anchors the English word to a known concept and builds awareness of how languages compare.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"कक्षा 3 की एक शिक्षिका बच्चों से ‘butterfly’ को उनकी अपनी भाषाओं में कहने को कहती है (titli, prajapati, phulpakhru…) और एक बहुभाषी शब्द-चार्ट बनाती है। मुख्य शैक्षणिक मूल्य क्या है?","optionsHi":["यह मुख्यतः शिक्षिका को बाद में उपयोग के लिए बच्चों की भाषाएँ सीखने में मदद करता है","यह बच्चों की भाषाओं को महत्त्व देता है और नए शब्द को ज्ञात संकल्पनाओं से जोड़ता है","यह अंग्रेज़ी शब्द सिखाने की आवश्यकता को समाप्त कर देता है, क्योंकि बच्चे संकल्पना जानते हैं","यह केवल उन कक्षाओं में उपयोगी है जहाँ हर बच्चा अलग भाषा बोलता है"],"explanationHi":"घर की भाषाओं को संसाधन के रूप में उपयोग करना बच्चों की पहचान को मान्यता देता है, अंग्रेज़ी शब्द को ज्ञात संकल्पना से जोड़ता है और भाषाओं की तुलना की जागरूकता बनाता है।"},
  {"id":"cdp-pedagogy-subjects-1046","question":"Which task best shows whether a Class 8 student can actually use the word ‘reluctant’?","options":["Describing a situation in which someone felt reluctant and why","Matching ‘reluctant’ with ‘unwilling’ in a list of synonym pairs","Writing the dictionary meaning of ‘reluctant’ accurately from memory","Spelling ‘reluctant’ correctly in a dictation of new words"],"answer":0,"explanation":"Describing a situation requires using the word appropriately in context, which tests productive knowledge; definitions and matching test only recognition.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कौन-सा कार्य सबसे अच्छी तरह दिखाता है कि कक्षा 8 का विद्यार्थी ‘reluctant’ शब्द का वास्तव में प्रयोग कर सकता है या नहीं?","optionsHi":["ऐसी स्थिति का वर्णन करना जिसमें किसी को reluctant महसूस हुआ और क्यों","समानार्थी जोड़ों की सूची में ‘reluctant’ को ‘unwilling’ से मिलाना","स्मृति से ‘reluctant’ का शब्दकोशीय अर्थ सही-सही लिखना","नए शब्दों के श्रुतलेख में ‘reluctant’ की सही वर्तनी लिखना"],"explanationHi":"किसी स्थिति का वर्णन करने के लिए शब्द का संदर्भ में उपयुक्त प्रयोग करना पड़ता है, जो उत्पादक ज्ञान की जाँच करता है; परिभाषाएँ और मिलान केवल पहचान की जाँच करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1047","question":"Class 4 children play ‘word antakshari’, in which each child says an English word that begins with the last letter of the previous word. Which statement about this game is most accurate?","options":["It is pure entertainment and has no real value for learning a language","It mainly develops reading comprehension of long texts in an enjoyable way","It builds vocabulary recall and attention to spelling in a low-anxiety way","It mainly develops handwriting, as children must write each word quickly"],"answer":2,"explanation":"The game makes children retrieve known words quickly and attend to how words end and begin, in an enjoyable setting; it does not involve reading texts or writing.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"कक्षा 4 के बच्चे ‘word antakshari’ खेलते हैं, जिसमें प्रत्येक बच्चा ऐसा अंग्रेज़ी शब्द बोलता है जो पिछले शब्द के अंतिम अक्षर से शुरू होता है। इस खेल के बारे में कौन-सा कथन सबसे सटीक है?","optionsHi":["यह केवल मनोरंजन है और भाषा सीखने के लिए इसका कोई वास्तविक मूल्य नहीं है","यह मुख्यतः रोचक ढंग से लंबे पाठों की पठन-बोध क्षमता विकसित करता है","यह कम चिंता वाले ढंग से शब्दावली-स्मरण और वर्तनी पर ध्यान विकसित करता है","यह मुख्यतः लिखावट विकसित करता है, क्योंकि बच्चों को हर शब्द जल्दी से लिखना होता है"],"explanationHi":"यह खेल बच्चों से ज्ञात शब्दों को तेज़ी से याद करवाता है और शब्दों के अंत और आरंभ पर ध्यान दिलवाता है, एक आनंददायक वातावरण में; इसमें पाठ पढ़ना या लिखना शामिल नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1048","question":"A structure such as the past tense is introduced in Class 3 in simple stories, revisited in Class 5 with irregular verbs, and again in Class 7 with the past continuous and past perfect. This organisation of grammar is called:","options":["A linear syllabus, where each item is completed once and never revisited","A lexical syllabus, organised only around high-frequency words","A notional-functional syllabus, organised only around language functions","A spiral approach, returning to items with growing depth and complexity"],"answer":3,"explanation":"A spiral curriculum (Bruner) returns to topics at increasing levels of complexity, matching how language is acquired gradually rather than mastered in one go.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"भूतकाल जैसी किसी संरचना को कक्षा 3 में सरल कहानियों में प्रस्तुत किया जाता है, कक्षा 5 में अनियमित क्रियाओं के साथ पुनः लिया जाता है, और कक्षा 7 में अपूर्ण भूतकाल और पूर्ण भूतकाल के साथ फिर लिया जाता है। व्याकरण के इस संगठन को कहते हैं:","optionsHi":["रैखिक पाठ्यक्रम, जिसमें प्रत्येक इकाई एक बार पूरी की जाती है और फिर कभी दोहराई नहीं जाती","शब्दकोशीय पाठ्यक्रम, जो केवल उच्च-आवृत्ति वाले शब्दों के इर्द-गिर्द संगठित होता है","संकल्पनात्मक-प्रकार्यात्मक पाठ्यक्रम, जो केवल भाषा के प्रकार्यों के इर्द-गिर्द संगठित होता है","सर्पिल उपागम, जिसमें बढ़ती गहराई और जटिलता के साथ इकाइयों पर लौटा जाता है"],"explanationHi":"सर्पिल पाठ्यचर्या (ब्रूनर) विषयों पर बढ़ते जटिलता-स्तरों के साथ लौटती है, जो इस बात से मेल खाता है कि भाषा धीरे-धीरे अर्जित होती है, एक बार में नहीं सीख ली जाती।"},
  {"id":"cdp-pedagogy-subjects-1049","question":"Read the sentence: ‘Unlike his timid brother, Raju was audacious and spoke up before the whole village.’ The clue that helps a reader guess ‘audacious’ is mainly a:","options":["Definition clue, since the word is defined in the sentence","Synonym clue, since a word with the same meaning appears","Example clue, since an example of the word is listed","Contrast clue, since ‘unlike’ sets it against ‘timid’"],"answer":3,"explanation":"‘Unlike his timid brother’ signals the opposite of timid, and the action of speaking up confirms it; the word itself is never defined.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"वाक्य पढ़िए: ‘Unlike his timid brother, Raju was audacious and spoke up before the whole village.’ पाठक को ‘audacious’ का अनुमान लगाने में मदद करने वाला संकेत मुख्यतः है:","optionsHi":["परिभाषा-संकेत, क्योंकि शब्द की परिभाषा वाक्य में दी गई है","पर्याय-संकेत, क्योंकि समान अर्थ वाला शब्द आया है","उदाहरण-संकेत, क्योंकि शब्द का एक उदाहरण सूचीबद्ध है","विरोध-संकेत, क्योंकि ‘unlike’ उसे ‘timid’ के विरुद्ध रखता है"],"explanationHi":"‘Unlike his timid brother’ timid के विपरीत का संकेत देता है, और खुलकर बोलने की क्रिया उसकी पुष्टि करती है; शब्द की परिभाषा कहीं नहीं दी गई है।"},
  {"id":"cdp-pedagogy-subjects-1050","question":"A Class 7 student writes: 'Camels grew humps because they needed to store water in the desert.' Which misconceptions does this sentence contain? 1. An animal develops a feature because it needs it. 2. The camel's hump is a store of water. 3. Animals have features suited to where they live.","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The 'need causes the trait' idea is a common teleological misconception, and the hump actually stores fat, not water. Statement 3 is the correct idea of adaptation, not a misconception.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा 7 का एक विद्यार्थी लिखता है: 'ऊँटों के कूबड़ इसलिए उग आए क्योंकि उन्हें रेगिस्तान में पानी जमा करने की आवश्यकता थी।' इस वाक्य में कौन-सी भ्रांतियाँ हैं? 1. कोई जंतु कोई विशेषता इसलिए विकसित करता है क्योंकि उसे उसकी आवश्यकता होती है। 2. ऊँट का कूबड़ पानी का भंडार है। 3. जंतुओं में वे विशेषताएँ होती हैं जो उनके निवास के अनुकूल होती हैं।","optionsHi":["केवल 1","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"'आवश्यकता से लक्षण बनता है' का विचार एक सामान्य उद्देश्यवादी भ्रांति है, और कूबड़ वास्तव में वसा जमा करता है, पानी नहीं। कथन 3 अनुकूलन का सही विचार है, भ्रांति नहीं।"},
  {"id":"cdp-pedagogy-subjects-1051","question":"Drawing a food chain, many students draw the arrow from the lion to the deer, 'because the lion eats the deer'. The best way for the teacher to deal with this is to:","options":["Mark it wrong and tell them to reverse all the arrows before the next class","Accept it, since the direction of the arrows does not matter in a food chain","Discuss what the arrow means, energy flowing from eaten to eater, and let them redraw","Avoid arrows altogether and ask students to write the animals as a simple list in order"],"answer":2,"explanation":"The error comes from reading the arrow as 'eats' rather than 'is eaten by / energy goes to'. Making the meaning of the symbol explicit fixes the confusion at its root.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"खाद्य श्रृंखला बनाते समय कई विद्यार्थी तीर शेर से हिरण की ओर बनाते हैं, 'क्योंकि शेर हिरण को खाता है'। शिक्षक के लिए इससे निपटने का सबसे अच्छा तरीका है:","optionsHi":["इसे गलत चिह्नित करना और अगली कक्षा से पहले सभी तीर उलटने को कहना","इसे स्वीकार कर लेना, क्योंकि खाद्य श्रृंखला में तीरों की दिशा मायने नहीं रखती","इस पर चर्चा करना कि तीर का क्या अर्थ है, ऊर्जा का खाए जाने वाले से खाने वाले की ओर प्रवाह, और उन्हें दोबारा बनाने देना","तीरों का प्रयोग बिल्कुल छोड़ देना और विद्यार्थियों से जंतुओं को क्रम में एक सरल सूची के रूप में लिखने को कहना"],"explanationHi":"त्रुटि तीर को 'खाता है' के रूप में पढ़ने से आती है, 'द्वारा खाया जाता है / ऊर्जा जाती है' के रूप में नहीं। प्रतीक का अर्थ स्पष्ट करने से भ्रम उसकी जड़ से ठीक होता है।"},
  {"id":"cdp-pedagogy-subjects-1052","question":"Many Class 8 students believe that all microorganisms are harmful. Which activity would best help them revise this belief?","options":["Showing pictures of diseases caused by bacteria, viruses and fungi and how they spread","Setting milk to curd and dough to rise, and discussing what caused the changes","Asking students to memorise a list of useful microbes and the products they make","Telling students that only some microbes cause disease"],"answer":1,"explanation":"Making curd and raising dough lets students see microbes doing useful work. Pictures of disease would only confirm the misconception, and a list is easy to forget.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा 8 के कई विद्यार्थी मानते हैं कि सभी सूक्ष्मजीव हानिकारक होते हैं। इस धारणा को संशोधित करने में कौन-सी गतिविधि उनकी सबसे अच्छी मदद करेगी?","optionsHi":["बैक्टीरिया, वायरस और कवकों से होने वाले रोगों और उनके फैलने के चित्र दिखाना","दूध से दही और आटे से खमीर उठवाना, और चर्चा करना कि परिवर्तन किससे हुए","विद्यार्थियों से उपयोगी सूक्ष्मजीवों और उनसे बनने वाले उत्पादों की सूची याद करवाना","विद्यार्थियों को बताना कि केवल कुछ सूक्ष्मजीव ही रोग फैलाते हैं"],"explanationHi":"दही जमाने और आटा फुलाने से विद्यार्थी सूक्ष्मजीवों को उपयोगी कार्य करते देखते हैं। रोगों के चित्र केवल भ्रांति की पुष्टि करेंगे, और सूची आसानी से भुला दी जाती है।"},
  {"id":"cdp-pedagogy-subjects-1053","question":"Students say that water left in a saucer in the sun 'disappears' and 'is destroyed'. Which activity most directly shows them where it goes?","options":["Measuring how long the water takes to disappear on a hot sunny day and on a cool cloudy day","Repeating the activity with salt water and seeing what is left behind","Keeping a second saucer in the shade and comparing how quickly it dries","Covering water in the sun with an inverted glass and watching droplets form inside it"],"answer":3,"explanation":"Droplets on the inner surface show that the water has turned into vapour and can condense back. Measuring time or changing conditions does not show where the water goes.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"विद्यार्थी कहते हैं कि धूप में तश्तरी में छोड़ा गया पानी 'गायब हो जाता है' और 'नष्ट हो जाता है'। कौन-सी गतिविधि उन्हें सबसे सीधे दिखाती है कि वह कहाँ जाता है?","optionsHi":["यह मापना कि गर्म धूप वाले दिन और ठंडे बादल वाले दिन पानी को गायब होने में कितना समय लगता है","नमकीन पानी के साथ गतिविधि दोहराना और देखना कि पीछे क्या बचता है","दूसरी तश्तरी को छाया में रखना और तुलना करना कि वह कितनी जल्दी सूखती है","धूप में रखे पानी को उलटे काँच के गिलास से ढकना और उसके अंदर बूँदें बनते देखना"],"explanationHi":"भीतरी सतह पर बूँदें दिखाती हैं कि पानी वाष्प में बदल गया है और फिर संघनित हो सकता है। समय मापने या परिस्थितियाँ बदलने से यह नहीं दिखता कि पानी कहाँ जाता है।"},
  {"id":"cdp-pedagogy-subjects-1054","question":"Students believe that when a candle burns, the wax 'just disappears'. Which pair of activities best shows that it turns into other substances?","options":["Holding a cold glass over the flame to see droplets, and testing the gases with lime water","Weighing the candle before and after burning to see how much mass is lost","Lighting a second, identical candle to see whether it burns in the same way and for as long","Putting out the flame with an inverted glass and watching the smoke rise"],"answer":0,"explanation":"Water droplets and milky lime water show that burning produces water vapour and carbon dioxide, so the wax has changed into gases. Weighing only confirms the candle got lighter, which fits 'disappears'.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"विद्यार्थी मानते हैं कि जब मोमबत्ती जलती है तो मोम 'बस गायब हो जाता है'। गतिविधियों का कौन-सा जोड़ा सबसे अच्छी तरह दिखाता है कि वह अन्य पदार्थों में बदल जाता है?","optionsHi":["लौ के ऊपर ठंडा गिलास पकड़कर बूँदें देखना, और चूने के पानी से गैसों की जाँच करना","जलने से पहले और बाद में मोमबत्ती को तौलकर देखना कि कितना द्रव्यमान घटा","एक दूसरी, समान मोमबत्ती जलाकर देखना कि वह उसी प्रकार और उतनी ही देर जलती है या नहीं","उलटे गिलास से लौ बुझाना और धुएँ को ऊपर उठते देखना"],"explanationHi":"पानी की बूँदें और दूधिया चूने का पानी दिखाते हैं कि जलने से जलवाष्प और कार्बन डाइऑक्साइड बनती हैं, यानी मोम गैसों में बदल गया है। तौलने से केवल इतना पुष्ट होता है कि मोमबत्ती हल्की हो गई, जो 'गायब हो जाता है' से मेल खाता है।"},
  {"id":"cdp-pedagogy-subjects-1055","question":"Some students argue that dissolving salt in water is a chemical change because 'the salt disappears and cannot be seen'. Which activity best helps them reconsider?","options":["Dissolving more salt to find out how much the water can hold","Tasting the solution to check that the salt is still there","Evaporating the solution and getting the salt back","Adding sugar to another glass of water and comparing"],"answer":2,"explanation":"Recovering the same salt by evaporation shows that no new substance was formed, which is the test of a physical change. Tasting shows that salt is present but does not address whether it changed.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"कुछ विद्यार्थी तर्क देते हैं कि पानी में नमक का घुलना रासायनिक परिवर्तन है क्योंकि 'नमक गायब हो जाता है और दिखाई नहीं देता'। कौन-सी गतिविधि उन्हें पुनर्विचार में सबसे अच्छी तरह मदद करती है?","optionsHi":["और नमक घोलना, यह जानने के लिए कि पानी कितना नमक सँभाल सकता है","विलयन को चखना, यह जाँचने के लिए कि नमक अब भी वहाँ है","विलयन को वाष्पित करके नमक वापस प्राप्त करना","दूसरे गिलास पानी में चीनी मिलाना और तुलना करना"],"explanationHi":"वाष्पन द्वारा वही नमक वापस मिलना दिखाता है कि कोई नया पदार्थ नहीं बना, जो भौतिक परिवर्तन की कसौटी है। चखने से पता चलता है कि नमक मौजूद है, पर यह नहीं कि वह बदला या नहीं।"},
  {"id":"cdp-pedagogy-subjects-1056","question":"A student believes that a shadow is 'the reflection of the object on the ground'. Which observation best challenges this idea?","options":["A shadow becomes longer in the evening when the sun is low in the sky","A red ball's shadow is dark, not red, and falls on the side away from the light","A shadow is formed only when there is a source of light shining directly on the object","The shadow of a tall tree is larger than that of a small plant nearby"],"answer":1,"explanation":"A reflection would show the object's colour; a shadow is dark because the opaque object blocks light. Its position, opposite the source, also shows it is caused by blocked light.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"एक विद्यार्थी मानता है कि परछाईं 'वस्तु का भूमि पर प्रतिबिंब' है। कौन-सा अवलोकन इस विचार को सबसे अच्छी तरह चुनौती देता है?","optionsHi":["शाम को जब सूर्य आकाश में नीचा होता है, परछाईं लंबी हो जाती है","लाल गेंद की परछाईं लाल नहीं, गहरी होती है और प्रकाश से दूर की ओर पड़ती है","परछाईं तभी बनती है जब वस्तु पर सीधे चमकता हुआ प्रकाश-स्रोत हो","लंबे पेड़ की परछाईं पास के छोटे पौधे की परछाईं से बड़ी होती है"],"explanationHi":"प्रतिबिंब वस्तु का रंग दिखाता, जबकि परछाईं गहरी इसलिए होती है कि अपारदर्शी वस्तु प्रकाश को रोकती है। स्रोत के विपरीत उसकी स्थिति भी दिखाती है कि वह रुके हुए प्रकाश के कारण बनती है।"},
  {"id":"cdp-pedagogy-subjects-1057","question":"Most Class 7 students think that the image in a plane mirror is formed on the surface of the mirror. Which activity best helps them locate the image correctly?","options":["Drawing the image on the surface of the mirror with a marker to fix its position","Measuring the size of the mirror and comparing it with the size of the image","Telling them clearly that the image is formed behind the mirror, not on it","Placing a lit candle before a glass sheet and moving an unlit one behind it until it seems lit"],"answer":3,"explanation":"The unlit candle seems to burn only when it sits where the image is, behind the glass at the same distance as the object. This gives direct evidence of the image's position.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा 7 के अधिकांश विद्यार्थी सोचते हैं कि समतल दर्पण में प्रतिबिंब दर्पण की सतह पर बनता है। कौन-सी गतिविधि उन्हें प्रतिबिंब का स्थान सही ढंग से पता करने में सबसे अच्छी मदद करती है?","optionsHi":["स्थिति निश्चित करने के लिए मार्कर से दर्पण की सतह पर प्रतिबिंब बनाना","दर्पण का आकार मापना और उसकी तुलना प्रतिबिंब के आकार से करना","उन्हें स्पष्ट रूप से बताना कि प्रतिबिंब दर्पण के पीछे बनता है, उस पर नहीं","काँच की पट्टिका के सामने जलती मोमबत्ती रखना और उसके पीछे बिना जली मोमबत्ती तब तक खिसकाना जब तक वह जलती हुई न दिखे"],"explanationHi":"बिना जली मोमबत्ती तभी जलती दिखती है जब वह उस जगह हो जहाँ प्रतिबिंब है, यानी काँच के पीछे वस्तु के बराबर दूरी पर। इससे प्रतिबिंब की स्थिति का प्रत्यक्ष साक्ष्य मिलता है।"},
  {"id":"cdp-pedagogy-subjects-1058","question":"Students in Class 8 think that sound can travel through empty space, because 'we can hear the thunder from the sky'. Which activity or resource best addresses this?","options":["A string telephone, then a bell-in-a-jar demonstration as the air is pumped out","Listening to thunder and counting the seconds after the lightning flash to find its distance","Measuring the loudness of different sounds with a sound-level app","Asking students to memorise the rule that sound needs a medium"],"answer":0,"explanation":"The string telephone shows sound travels through a material, and the bell jar shows sound fading as air is removed. Thunder reaches us through air, not empty space.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा 8 के विद्यार्थी सोचते हैं कि ध्वनि रिक्त स्थान से गुज़र सकती है, क्योंकि 'हम आकाश से बादलों की गड़गड़ाहट सुन सकते हैं'। इसे संबोधित करने के लिए कौन-सी गतिविधि या संसाधन सबसे अच्छा है?","optionsHi":["धागा-टेलीफ़ोन, फिर जार में घंटी का प्रदर्शन जब हवा बाहर निकाली जाती है","गड़गड़ाहट सुनना और बिजली की चमक के बाद सेकंड गिनकर उसकी दूरी ज्ञात करना","ध्वनि-स्तर ऐप से विभिन्न ध्वनियों की तीव्रता मापना","विद्यार्थियों से यह नियम याद करवाना कि ध्वनि को माध्यम चाहिए"],"explanationHi":"धागा-टेलीफ़ोन दिखाता है कि ध्वनि किसी पदार्थ से होकर चलती है, और घंटी-जार दिखाता है कि हवा निकालने पर ध्वनि क्षीण हो जाती है। गड़गड़ाहट हम तक हवा से पहुँचती है, रिक्त स्थान से नहीं।"},
  {"id":"cdp-pedagogy-subjects-1059","question":"A student insists that stars are smaller than the moon, 'because they look so tiny'. Which activity is most helpful?","options":["Showing a chart of the planets in order of their distance from the Sun","Comparing a nearby torch with a distant street lamp at night","Telling students that stars are very far away and so look small","Showing a photograph of the night sky with the moon and many stars"],"answer":1,"explanation":"Seeing that a large, distant lamp can look smaller than a small, nearby torch helps students understand that apparent size depends on distance, so stars can be huge yet look tiny.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"एक विद्यार्थी ज़ोर देकर कहता है कि तारे चंद्रमा से छोटे होते हैं, 'क्योंकि वे इतने नन्हे दिखते हैं'। कौन-सी गतिविधि सबसे अधिक सहायक है?","optionsHi":["ग्रहों का सूर्य से दूरी के क्रम में चार्ट दिखाना","रात में पास की टॉर्च की तुलना दूर की स्ट्रीट लाइट से करना","विद्यार्थियों को बताना कि तारे बहुत दूर हैं इसलिए छोटे दिखते हैं","चंद्रमा और अनेक तारों वाले रात्रि-आकाश का चित्र दिखाना"],"explanationHi":"यह देखना कि बड़ा, दूर का लैंप छोटी, पास की टॉर्च से छोटा दिख सकता है, विद्यार्थियों को समझने में मदद करता है कि आभासी आकार दूरी पर निर्भर करता है, इसलिए तारे विशाल होकर भी नन्हे दिख सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-1060","question":"Students say that pressure depends only on how hard you push. Which activity is most suitable to show the role of area?","options":["Pushing a heavy box and then a light box across the same floor with the same effort","Pushing a ball gently and then hard to see how far it rolls","Pressing a pin into a board point-first and then head-first, with the same effort","Pulling a rope in tug-of-war with two teams of different strength"],"answer":2,"explanation":"The same force pushes the pointed end in but not the flat head, so the effect depends on area as well as force. The other activities show force but not area.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"विद्यार्थी कहते हैं कि दाब केवल इस पर निर्भर करता है कि आप कितनी ज़ोर से धक्का देते हैं। क्षेत्रफल की भूमिका दिखाने के लिए कौन-सी गतिविधि सबसे उपयुक्त है?","optionsHi":["उसी फ़र्श पर एक भारी बक्से और फिर एक हल्के बक्से को उतने ही प्रयास से खिसकाना","एक गेंद को पहले धीरे और फिर ज़ोर से धक्का देकर देखना कि वह कितनी दूर लुढ़कती है","पिन को बोर्ड में पहले नोक की ओर से और फिर सिर की ओर से उतने ही प्रयास से दबाना","रस्साकशी में अलग-अलग बल वाली दो टीमों द्वारा रस्सी खींचना"],"explanationHi":"वही बल नुकीले सिरे को अंदर धकेल देता है पर चपटे सिर को नहीं, इसलिए प्रभाव बल के साथ क्षेत्रफल पर भी निर्भर करता है। अन्य गतिविधियाँ बल दिखाती हैं, क्षेत्रफल नहीं।"},
  {"id":"cdp-pedagogy-subjects-1061","question":"Many students think that respiration happens only in the lungs and is the same as breathing. Which activity best challenges this idea?","options":["Counting breaths per minute before and after exercise and drawing a bar graph","Drawing and labelling the human respiratory system from the textbook diagram","Blowing into lime water through a straw to show that breathed-out air turns it milky","Keeping yeast in sugar solution and passing the gas it gives off through lime water"],"answer":3,"explanation":"Yeast has no lungs, yet it respires and releases carbon dioxide; this shows respiration is a cellular process, while breathing is only gas exchange in animals with lungs.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कई विद्यार्थी सोचते हैं कि श्वसन केवल फेफड़ों में होता है और साँस लेने के समान है। कौन-सी गतिविधि इस विचार को सबसे अच्छी तरह चुनौती देती है?","optionsHi":["व्यायाम से पहले और बाद में प्रति मिनट साँसें गिनना और स्तंभ-आलेख बनाना","पाठ्यपुस्तक के आरेख से मानव श्वसन तंत्र बनाना और उस पर नाम लिखना","स्ट्रॉ से चूने के पानी में फूँकना, यह दिखाने के लिए कि छोड़ी गई साँस उसे दूधिया कर देती है","चीनी के घोल में खमीर रखना और उसके द्वारा छोड़ी गई गैस को चूने के पानी में प्रवाहित करना"],"explanationHi":"खमीर में फेफड़े नहीं होते, फिर भी वह श्वसन करता है और कार्बन डाइऑक्साइड छोड़ता है; इससे पता चलता है कि श्वसन एक कोशिकीय प्रक्रिया है, जबकि साँस लेना फेफड़ों वाले जंतुओं में केवल गैस-विनिमय है।"},
  {"id":"cdp-pedagogy-subjects-1062","question":"A Class 6 student says a dry seed is non-living because 'it does not move or eat'. The best response from the teacher is to:","options":["Have students keep soaked seeds on moist cotton and observe them for a week","Tell the student firmly that seeds are living and ask him to note it in his notebook","Agree with the student, since a dry seed shows none of the signs of life","Ask the student to draw a seed and label its parts, such as the coat and embryo"],"answer":0,"explanation":"Watching a seed germinate shows that it was alive in a dormant state. Students' own observations give stronger reasons to revise the idea than the teacher's statement.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा 6 का एक विद्यार्थी कहता है कि सूखा बीज निर्जीव है क्योंकि 'वह न हिलता है, न खाता है'। शिक्षक की सबसे अच्छी प्रतिक्रिया है:","optionsHi":["विद्यार्थियों को भीगे बीज नम रुई पर रखवाना और एक सप्ताह तक उनका अवलोकन करवाना","विद्यार्थी को दृढ़ता से बताना कि बीज सजीव हैं और उसे अपनी कॉपी में लिखने को कहना","विद्यार्थी से सहमत होना, क्योंकि सूखे बीज में जीवन के कोई लक्षण नहीं दिखते","विद्यार्थी से बीज का चित्र बनाने और बीज-चोल तथा भ्रूण जैसे उसके भागों पर नाम लिखने को कहना"],"explanationHi":"बीज को अंकुरित होते देखना दिखाता है कि वह सुप्त अवस्था में जीवित था। शिक्षक के कथन से अधिक, विद्यार्थियों के अपने अवलोकन उन्हें विचार बदलने के प्रबल कारण देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1063","question":"Students in Class 8 believe that all metals are hard solids. Which teaching step best widens their concept?","options":["Showing more iron, copper and aluminium objects and asking students to tap them","Asking them to memorise the properties of metals listed in the textbook","Showing mercury, a liquid, and sodium, soft enough to cut with a knife","Telling them that most metals are hard, so their idea is basically right"],"answer":2,"explanation":"Examples that do not fit the narrow idea, such as liquid mercury and soft sodium, show that hardness is not a defining property of metals.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"कक्षा 8 के विद्यार्थी मानते हैं कि सभी धातुएँ कठोर ठोस होती हैं। कौन-सा शिक्षण-चरण उनकी संकल्पना को सबसे अच्छी तरह विस्तृत करता है?","optionsHi":["लोहे, ताँबे और ऐलुमिनियम की और वस्तुएँ दिखाना और विद्यार्थियों से उन्हें थपथपाने को कहना","उनसे पाठ्यपुस्तक में सूचीबद्ध धातुओं के गुण याद करवाना","द्रव पारा और चाकू से काटे जा सकने वाले मुलायम सोडियम को दिखाना","उन्हें बताना कि अधिकांश धातुएँ कठोर होती हैं, इसलिए उनका विचार मूलतः सही है"],"explanationHi":"जो उदाहरण संकीर्ण विचार में फिट नहीं बैठते, जैसे द्रव पारा और मुलायम सोडियम, दिखाते हैं कि कठोरता धातुओं का परिभाषित करने वाला गुण नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1064","question":"Students believe that all acids are dangerous and burn the skin. Which activity best broadens their idea?","options":["Showing a video of acid burns so that students learn to handle acids safely","Testing lemon juice, curd, vinegar and tamarind with a natural indicator","Asking them to memorise a list of acids found in the school laboratory","Telling them that only strong acids such as sulphuric acid are dangerous"],"answer":1,"explanation":"Finding that foods they eat every day are acidic shows that acids differ in strength and many are safe. The video would only confirm the misconception.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"विद्यार्थी मानते हैं कि सभी अम्ल खतरनाक होते हैं और त्वचा जला देते हैं। कौन-सी गतिविधि उनके विचार को सबसे अच्छी तरह व्यापक बनाती है?","optionsHi":["अम्ल से जलने का वीडियो दिखाना, ताकि विद्यार्थी अम्लों को सुरक्षित रूप से सँभालना सीखें","नींबू का रस, दही, सिरका और इमली की प्राकृतिक सूचक से जाँच करना","उनसे विद्यालय की प्रयोगशाला में पाए जाने वाले अम्लों की सूची याद करवाना","उन्हें बताना कि केवल सल्फ्यूरिक अम्ल जैसे प्रबल अम्ल ही खतरनाक होते हैं"],"explanationHi":"यह पाना कि वे जो भोजन रोज़ खाते हैं वह अम्लीय है, दिखाता है कि अम्लों की प्रबलता भिन्न होती है और कई सुरक्षित हैं। वीडियो केवल भ्रांति की पुष्टि करता।"},
  {"id":"cdp-pedagogy-subjects-1065","question":"Students say that water that looks clear is always safe to drink. Which approach best addresses this belief?","options":["Showing that alum makes muddy water clear, which proves clear water is safe","Telling them to drink only bottled water, whatever its source or appearance","Testing the water with litmus paper to find out whether it is safe to drink","Explaining that germs are invisible, so clear water may still need boiling"],"answer":3,"explanation":"Clarity removes only visible particles; invisible microbes can remain. Alum or litmus does not show whether water is free from germs.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS","questionHi":"विद्यार्थी कहते हैं कि जो पानी साफ़ दिखता है वह हमेशा पीने के लिए सुरक्षित होता है। कौन-सा उपागम इस विश्वास को सबसे अच्छी तरह संबोधित करता है?","optionsHi":["यह दिखाना कि फिटकरी गंदे पानी को साफ़ कर देती है, जो सिद्ध करता है कि साफ़ पानी सुरक्षित है","उन्हें बताना कि स्रोत या दिखावट चाहे जो हो, केवल बोतलबंद पानी पिएँ","लिटमस पत्र से पानी की जाँच करना कि वह पीने के लिए सुरक्षित है या नहीं","समझाना कि कीटाणु अदृश्य होते हैं, इसलिए साफ़ पानी को भी उबालने की आवश्यकता हो सकती है"],"explanationHi":"स्वच्छता केवल दिखाई देने वाले कणों को हटाती है; अदृश्य सूक्ष्मजीव बने रह सकते हैं। फिटकरी या लिटमस से पता नहीं चलता कि पानी कीटाणुओं से मुक्त है।"},
  {"id":"cdp-pedagogy-subjects-1066","question":"A student says that an elephant must have much bigger cells than an ant because it is a much bigger animal. Which statement should the teacher help the student reach?","options":["Size depends mainly on the number of cells, not on the size of each cell","Bigger animals have bigger cells in all their organs, in proportion to body size","All cells in all organisms are exactly the same size, whatever the organism","Larger animals have fewer but much larger cells, which makes them stronger"],"answer":0,"explanation":"Cells of large and small animals are of broadly similar size; a large animal is large because it has far more cells. This links cell theory to students' everyday reasoning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"एक विद्यार्थी कहता है कि हाथी की कोशिकाएँ चींटी की कोशिकाओं से बहुत बड़ी होनी चाहिए क्योंकि वह बहुत बड़ा जंतु है। शिक्षक को विद्यार्थी को किस कथन तक पहुँचने में मदद करनी चाहिए?","optionsHi":["आकार मुख्यतः कोशिकाओं की संख्या पर निर्भर करता है, प्रत्येक कोशिका के आकार पर नहीं","बड़े जंतुओं की सभी अंगों में कोशिकाएँ शरीर के आकार के अनुपात में बड़ी होती हैं","सभी जीवों की सभी कोशिकाएँ ठीक एक ही आकार की होती हैं, जीव चाहे जो हो","बड़े जंतुओं में कम पर बहुत बड़ी कोशिकाएँ होती हैं, जिससे वे अधिक मज़बूत होते हैं"],"explanationHi":"बड़े और छोटे जंतुओं की कोशिकाएँ मोटे तौर पर समान आकार की होती हैं; बड़ा जंतु इसलिए बड़ा होता है कि उसमें कहीं अधिक कोशिकाएँ होती हैं। इससे कोशिका-सिद्धांत विद्यार्थियों के दैनिक तर्क से जुड़ता है।"},
  {"id":"cdp-pedagogy-subjects-1067","question":"To find out how children think about force, a researcher shows a series of pictures (a book on a table, a ball in flight, a car parked on a slope) and asks the child at each picture, 'Is there a force here? Why?' This diagnostic technique is called:","options":["Concept cartoon discussion","Interview-about-instances","Free word association test","Sociometry"],"answer":1,"explanation":"In the interview-about-instances technique, a learner is asked to explain whether a concept applies in each of a set of pictured situations. It reveals the reasoning behind their answers.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"बच्चे बल के बारे में कैसे सोचते हैं, यह जानने के लिए एक शोधकर्ता चित्रों की श्रृंखला दिखाता है (मेज़ पर रखी किताब, उड़ान में गेंद, ढलान पर खड़ी कार) और प्रत्येक चित्र पर बच्चे से पूछता है, 'क्या यहाँ बल है? क्यों?' इस निदानात्मक तकनीक को कहते हैं:","optionsHi":["संकल्पना-कार्टून चर्चा","उदाहरणों के विषय में साक्षात्कार (interview-about-instances)","मुक्त शब्द-साहचर्य परीक्षण","समाजमिति (sociometry)"],"explanationHi":"उदाहरणों के विषय में साक्षात्कार तकनीक में अधिगमकर्ता से चित्रित स्थितियों के समूह में प्रत्येक के लिए समझाने को कहा जाता है कि संकल्पना लागू होती है या नहीं। इससे उनके उत्तरों के पीछे का तर्क प्रकट होता है।"},
  {"id":"cdp-pedagogy-subjects-1068","question":"Assertion (A): Children's alternative conceptions in science should be treated as starting points for teaching rather than as mistakes to be penalised. Reason (R): Such ideas are often based on everyday experience and have their own internal logic.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because alternative conceptions make sense to children in terms of their experience, they must be engaged with and reshaped; penalising them simply drives them underground.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"अभिकथन (A): बच्चों की वैकल्पिक संकल्पनाओं को विज्ञान में दंडित की जाने वाली गलतियों के बजाय शिक्षण के आरंभ-बिंदु के रूप में देखा जाना चाहिए। कारण (R): ऐसे विचार प्रायः दैनिक अनुभव पर आधारित होते हैं और उनका अपना आंतरिक तर्क होता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"चूँकि वैकल्पिक संकल्पनाएँ बच्चों के अनुभव के अनुसार उन्हें सार्थक लगती हैं, उनसे जुड़ना और उन्हें नया रूप देना आवश्यक है; उन्हें दंडित करना उन्हें केवल छिपा देता है।"},
  {"id":"cdp-pedagogy-subjects-1069","question":"While teaching weather, a teacher hears students say, 'Clouds are made of smoke' and 'Rain falls because clouds get holes in them.' What should she do first?","options":["Give the correct explanation at once so that the wrong ideas do not spread","Ignore these ideas, since they are not in the textbook and will confuse others","Ask for their reasons and record the ideas on the board as hypotheses to test","Tell students to read the textbook chapter on weather and correct themselves"],"answer":2,"explanation":"Eliciting and recording students' ideas as hypotheses respects their thinking and gives the class something to test, for example by making a 'cloud' with warm water and ice and seeing what condenses.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"मौसम पढ़ाते समय एक शिक्षिका सुनती है कि विद्यार्थी कहते हैं, 'बादल धुएँ से बने होते हैं' और 'बादलों में छेद हो जाने से बारिश गिरती है।' उसे सबसे पहले क्या करना चाहिए?","optionsHi":["तुरंत सही व्याख्या दे देनी चाहिए ताकि गलत विचार फैलें नहीं","इन विचारों की उपेक्षा करनी चाहिए, क्योंकि ये पाठ्यपुस्तक में नहीं हैं और दूसरों को भ्रमित करेंगे","उनके कारण पूछने चाहिए और विचारों को परिकल्पनाओं के रूप में बोर्ड पर दर्ज करना चाहिए ताकि उनकी जाँच हो सके","विद्यार्थियों से मौसम पर पाठ्यपुस्तक का अध्याय पढ़ने और स्वयं को सुधारने को कहना चाहिए"],"explanationHi":"विद्यार्थियों के विचारों को प्रकट करना और परिकल्पनाओं के रूप में दर्ज करना उनके चिंतन का सम्मान करता है और कक्षा को परखने के लिए कुछ देता है, उदाहरण के लिए गर्म पानी और बर्फ से 'बादल' बनाकर देखना कि क्या संघनित होता है।"},
  {"id":"cdp-pedagogy-subjects-1070","question":"A student claims that a heavier object always floats less well than a lighter one. Which pair of experiences best challenges this?","options":["A heavy steel ship floats, but a light steel nail sinks","A leaf floats and a stone sinks when both are put in water","A wooden block and a plastic button both float in a bucket","A feather and a pin are dropped in the air from the same height"],"answer":0,"explanation":"The heavy ship floats because its shape displaces a large volume of water, while the small nail sinks; this breaks the link between weight alone and floating.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"एक विद्यार्थी दावा करता है कि भारी वस्तु हमेशा हल्की वस्तु से कम अच्छी तरह तैरती है। अनुभवों का कौन-सा जोड़ा इसे सबसे अच्छी तरह चुनौती देता है?","optionsHi":["भारी इस्पात का जहाज़ तैरता है, पर हल्की इस्पात की कील डूब जाती है","पत्ती तैरती है और पत्थर डूबता है, जब दोनों को पानी में डाला जाए","लकड़ी का टुकड़ा और प्लास्टिक का बटन दोनों बाल्टी में तैरते हैं","पंख और पिन को हवा में एक ही ऊँचाई से गिराया जाता है"],"explanationHi":"भारी जहाज़ इसलिए तैरता है कि उसकी आकृति बड़ी मात्रा में पानी विस्थापित करती है, जबकि छोटी कील डूब जाती है; यह केवल भार और तैरने के बीच के संबंध को तोड़ता है।"},
  {"id":"cdp-pedagogy-subjects-1071","question":"Students say that winter clothes are made of 'warm' materials and summer clothes of 'cool' materials. Which investigation best tests this idea?","options":["Feeling woollen and cotton cloth with the hand to judge which is warmer","Wrapping hot-water bottles in wool and cotton and timing how fast each cools","Asking parents which clothes keep them warm in winter and cool in summer months","Reading the labels of sweaters and shirts to see what each is made of"],"answer":1,"explanation":"Comparing cooling rates shows that wool slows heat loss better (it traps air), rather than being 'warm' itself. A fair, measured test is better evidence than touch, which feels temperature differences unreliably.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"विद्यार्थी कहते हैं कि सर्दी के कपड़े 'गर्म' पदार्थों से और गर्मी के कपड़े 'ठंडे' पदार्थों से बने होते हैं। कौन-सी जाँच इस विचार को सबसे अच्छी तरह परखती है?","optionsHi":["ऊनी और सूती कपड़े को हाथ से छूकर तय करना कि कौन-सा अधिक गर्म है","गर्म पानी की बोतलों को ऊन और सूत में लपेटना और समय मापना कि प्रत्येक कितनी तेज़ी से ठंडी होती है","माता-पिता से पूछना कि कौन-से कपड़े उन्हें सर्दी में गर्म और गर्मी में ठंडे रखते हैं","स्वेटरों और कमीज़ों के लेबल पढ़ना कि प्रत्येक किससे बना है"],"explanationHi":"ठंडा होने की दरों की तुलना दिखाती है कि ऊन ऊष्मा-हानि को बेहतर ढंग से धीमा करती है (वह हवा को फँसाती है), न कि स्वयं 'गर्म' है। निष्पक्ष, मापा हुआ परीक्षण स्पर्श से बेहतर साक्ष्य है, जो तापमान के अंतर को अविश्वसनीय रूप से महसूस कराता है।"},
  {"id":"cdp-pedagogy-subjects-1072","question":"A Class 7 teacher finds that students who can explain why metals feel cold also claim that a woollen blanket 'gives out heat'. What does this pattern suggest for her teaching?","options":["The students are careless, so they should simply be tested more often","Wool and metal must be taught in separate years so the ideas do not mix","The two ideas are unrelated, so each must be memorised as a separate fact","They lack a general idea of heat flow that they can apply to both cases"],"answer":3,"explanation":"Students often hold context-bound ideas; the same principle (heat flows from hot to cold, at rates set by conductors and insulators) explains both cases, and the teacher should help them see that link.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा 7 की एक शिक्षिका पाती है कि जो विद्यार्थी समझा सकते हैं कि धातुएँ ठंडी क्यों लगती हैं, वही यह भी कहते हैं कि ऊनी कंबल 'ऊष्मा देता है'। यह पैटर्न उसके शिक्षण के लिए क्या सुझाता है?","optionsHi":["विद्यार्थी लापरवाह हैं, इसलिए उनकी बस अधिक बार परीक्षा ली जानी चाहिए","ऊन और धातु को अलग-अलग वर्षों में पढ़ाना चाहिए ताकि विचार आपस में न मिलें","दोनों विचार असंबंधित हैं, इसलिए प्रत्येक को अलग तथ्य के रूप में याद करना होगा","उनके पास ऊष्मा-प्रवाह का कोई सामान्य विचार नहीं है जिसे वे दोनों स्थितियों में लागू कर सकें"],"explanationHi":"विद्यार्थी प्रायः संदर्भ-बद्ध विचार रखते हैं; वही सिद्धांत (ऊष्मा गर्म से ठंडे की ओर बहती है, दर चालकों और विद्युतरोधी पदार्थों से तय होती है) दोनों स्थितियों को समझाता है, और शिक्षिका को उन्हें वह संबंध देखने में मदद करनी चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1073","question":"Students believe that a plant's mass comes from the water and minerals it takes from the soil. Which question, discussed after the willow tree story, would push their thinking further?","options":["'How much water does a plant need every day to stay healthy?'","'Which minerals do plants get from the soil, and in what amounts?'","'What does the plant take in from the air that adds to its mass?'","'Why do plants need sunlight to stay green and grow taller?'"],"answer":2,"explanation":"Most of a plant's dry mass comes from carbon dioxide taken from the air during photosynthesis. Directing attention to the air opens up the key idea students usually miss.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"विद्यार्थी मानते हैं कि पौधे का द्रव्यमान उस पानी और खनिजों से आता है जो वह मिट्टी से लेता है। विलो वृक्ष की कहानी के बाद चर्चा किया गया कौन-सा प्रश्न उनके चिंतन को आगे बढ़ाएगा?","optionsHi":["'स्वस्थ रहने के लिए पौधे को प्रतिदिन कितने पानी की आवश्यकता होती है?'","'पौधे मिट्टी से कौन-से खनिज लेते हैं, और कितनी मात्रा में?'","'पौधा हवा से क्या ग्रहण करता है जो उसके द्रव्यमान में जुड़ता है?'","'पौधों को हरा रहने और अधिक ऊँचा बढ़ने के लिए सूर्य के प्रकाश की आवश्यकता क्यों होती है?'"],"explanationHi":"पौधे के शुष्क द्रव्यमान का अधिकांश भाग प्रकाश-संश्लेषण के दौरान हवा से ली गई कार्बन डाइऑक्साइड से आता है। हवा की ओर ध्यान दिलाना वह मुख्य विचार खोलता है जिसे विद्यार्थी प्रायः चूक जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1074","question":"A Class VII teacher in Nagpur divides a chapter on India's major soils into four parts. Each member of a home group takes one part, meets with members of other groups who have the same part, and then returns to teach it to the home group. What is the main purpose of the meeting with members who share the same part?","options":["To let fast learners finish early and rest while others catch up","To decide which of the home groups will get the highest marks for the chapter","To master their part together and plan how to teach it to their home group","To copy notes from the best student in that meeting, word for word"],"answer":2,"explanation":"In the jigsaw method, the 'expert group' meeting lets students master their piece through discussion and prepare to teach it, so every home group gets accurate content. It is not a competition or a copying session.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"नागपुर में कक्षा VII का एक शिक्षक भारत की प्रमुख मृदाओं के अध्याय को चार भागों में बाँटता है। प्रत्येक गृह-समूह का एक सदस्य एक भाग लेता है, उसी भाग वाले अन्य समूहों के सदस्यों से मिलता है, और फिर लौटकर अपने गृह-समूह को उसे पढ़ाता है। एक ही भाग वाले सदस्यों से मिलने का मुख्य उद्देश्य क्या है?","optionsHi":["तेज़ सीखने वालों को जल्दी पूरा करने और आराम करने देना जबकि अन्य पकड़ बनाएँ","यह तय करना कि अध्याय के लिए कौन-सा गृह-समूह सर्वाधिक अंक पाएगा","अपने भाग में साथ मिलकर निपुण होना और योजना बनाना कि उसे अपने गृह-समूह को कैसे पढ़ाएँ","उस बैठक के सबसे अच्छे विद्यार्थी के नोट्स शब्दशः नकल करना"],"explanationHi":"जिगसॉ विधि में 'विशेषज्ञ समूह' की बैठक विद्यार्थियों को चर्चा के माध्यम से अपने भाग में निपुण होने और उसे पढ़ाने की तैयारी करने देती है, ताकि हर गृह-समूह को सटीक सामग्री मिले। यह प्रतियोगिता या नकल का सत्र नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1075","question":"In a Class VI group project on 'Our local market', Shalini did almost all the work while three others did nothing, yet all four got the same marks. According to Johnson and Johnson, which essential element of cooperative learning was mainly missing?","options":["Individual accountability","Heterogeneous grouping","Competition between groups","Teacher lecture before group work"],"answer":0,"explanation":"Individual accountability means each member's contribution and learning is checked, for example through individual tasks or random reporting. Without it, 'free riders' can hide behind one hard worker.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"'हमारा स्थानीय बाज़ार' पर कक्षा VI की समूह-परियोजना में शालिनी ने लगभग सारा काम किया जबकि तीन अन्य ने कुछ नहीं किया, फिर भी चारों को समान अंक मिले। जॉनसन और जॉनसन के अनुसार सहकारी अधिगम का कौन-सा आवश्यक तत्त्व मुख्यतः अनुपस्थित था?","optionsHi":["व्यक्तिगत जवाबदेही","विषमजातीय समूहीकरण","समूहों के बीच प्रतियोगिता","समूह-कार्य से पहले शिक्षक का व्याख्यान"],"explanationHi":"व्यक्तिगत जवाबदेही का अर्थ है कि प्रत्येक सदस्य के योगदान और अधिगम की जाँच हो, उदाहरण के लिए व्यक्तिगत कार्यों या यादृच्छिक रिपोर्टिंग के माध्यम से। इसके बिना 'मुफ़्तख़ोर' एक मेहनती सदस्य के पीछे छिप सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-1076","question":"For a Class V maths puzzle, a teacher gives each of four group members a different clue card; no one is allowed to show their card, only read it aloud, and the puzzle cannot be solved without all four clues. This design mainly builds:","options":["Group processing","Individual competitiveness","Positive interdependence","Social loafing"],"answer":2,"explanation":"When the group can succeed only if every member contributes, members depend on one another in a positive way. Group processing is reflection on how the group worked, which happens after the task.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा V की गणित की एक पहेली के लिए एक शिक्षक चार समूह-सदस्यों में से प्रत्येक को अलग संकेत-कार्ड देता है; कोई अपना कार्ड दिखा नहीं सकता, केवल ज़ोर से पढ़ सकता है, और पहेली चारों संकेतों के बिना हल नहीं हो सकती। यह रचना मुख्यतः क्या विकसित करती है?","optionsHi":["समूह-प्रक्रमण (group processing)","व्यक्तिगत प्रतिस्पर्धा","सकारात्मक अंतर-निर्भरता","सामाजिक आलस्य (social loafing)"],"explanationHi":"जब समूह तभी सफल हो सकता है जब हर सदस्य योगदान दे, तब सदस्य एक-दूसरे पर सकारात्मक रूप से निर्भर होते हैं। समूह-प्रक्रमण इस पर चिंतन है कि समूह ने कैसे कार्य किया, जो कार्य के बाद होता है।"},
  {"id":"cdp-pedagogy-subjects-1077","question":"In Student Teams-Achievement Divisions (STAD), team scores are based on how much each member improves over his or her own past performance rather than on raw marks. What is the main reason for this rule?","options":["It makes marking quicker, since the teacher only records improvement","It ensures that the team with the highest-scoring students always wins the prize","It allows weaker students to be left out of the team score entirely","Every member, whatever their ability, can contribute equally to the team score"],"answer":3,"explanation":"Improvement points mean a low achiever who improves a lot helps the team as much as a high achiever, which creates equal opportunity for success and makes the team care about everyone's learning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"विद्यार्थी टीम-उपलब्धि विभाजन (STAD) में टीम के अंक कच्चे अंकों के बजाय इस पर आधारित होते हैं कि प्रत्येक सदस्य ने अपने पिछले प्रदर्शन से कितना सुधार किया। इस नियम का मुख्य कारण क्या है?","optionsHi":["यह अंकन को तेज़ बनाता है, क्योंकि शिक्षक को केवल सुधार दर्ज करना होता है","यह सुनिश्चित करता है कि सबसे अधिक अंक पाने वाले विद्यार्थियों वाली टीम ही हमेशा पुरस्कार जीते","यह कमज़ोर विद्यार्थियों को टीम के अंकों से पूरी तरह बाहर रखने देता है","प्रत्येक सदस्य, अपनी योग्यता चाहे जो हो, टीम के अंकों में समान रूप से योगदान दे सकता है"],"explanationHi":"सुधार-अंकों का अर्थ है कि जो कम उपलब्धि वाला विद्यार्थी बहुत सुधार करता है वह टीम की उतनी ही मदद करता है जितनी उच्च उपलब्धि वाला, जिससे सफलता का समान अवसर मिलता है और टीम हर किसी के अधिगम की परवाह करती है।"},
  {"id":"cdp-pedagogy-subjects-1078","question":"A Class IV teacher asks, 'Why do you think birds build nests in trees?', gives everyone a minute to think silently, then lets them discuss with a partner, and finally invites a few pairs to share. What is the main advantage of this structure?","options":["It reduces the number of questions the teacher must ask during a lesson","All children get time to think and rehearse, so even shy ones can contribute","It makes sure that only correct answers are shared with the whole class","It replaces the need for whole-class discussion, as pairs settle the answer themselves"],"answer":1,"explanation":"Think-pair-share builds in individual thinking time and a safe rehearsal with a partner, which raises the quality and spread of participation. It leads into, not replaces, whole-class discussion.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा IV का एक शिक्षक पूछता है, 'तुम्हें क्या लगता है पक्षी पेड़ों पर घोंसले क्यों बनाते हैं?', सबको एक मिनट चुपचाप सोचने का समय देता है, फिर उन्हें साथी के साथ चर्चा करने देता है, और अंत में कुछ जोड़ियों को साझा करने के लिए आमंत्रित करता है। इस रचना का मुख्य लाभ क्या है?","optionsHi":["यह पाठ के दौरान शिक्षक को पूछे जाने वाले प्रश्नों की संख्या घटा देती है","सभी बच्चों को सोचने और अभ्यास करने का समय मिलता है, इसलिए संकोची बच्चे भी योगदान दे सकते हैं","यह सुनिश्चित करती है कि केवल सही उत्तर ही पूरी कक्षा के साथ साझा हों","यह पूरी कक्षा की चर्चा की आवश्यकता को समाप्त कर देती है, क्योंकि जोड़ियाँ उत्तर स्वयं तय कर लेती हैं"],"explanationHi":"सोचो-जोड़ी बनाओ-साझा करो (think-pair-share) में व्यक्तिगत चिंतन का समय और साथी के साथ सुरक्षित अभ्यास शामिल होता है, जिससे भागीदारी की गुणवत्ता और विस्तार बढ़ता है। यह पूरी कक्षा की चर्चा तक ले जाता है, उसकी जगह नहीं लेता।"},
  {"id":"cdp-pedagogy-subjects-1079","question":"At the end of a group activity, a Class VIII teacher asks each group to discuss: 'What did we do well as a team today? What should we do differently next time?' This reflects which element of cooperative learning?","options":["Positive interdependence","Individual accountability","Promotive interaction","Group processing"],"answer":3,"explanation":"Group processing is the group's reflection on how well it worked together and how to improve; it is what lets cooperative skills grow over time.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"समूह-गतिविधि के अंत में कक्षा VIII का एक शिक्षक प्रत्येक समूह से चर्चा करने को कहता है: 'आज हमने एक टीम के रूप में क्या अच्छा किया? अगली बार हमें क्या अलग करना चाहिए?' यह सहकारी अधिगम के किस तत्त्व को दर्शाता है?","optionsHi":["सकारात्मक अंतर-निर्भरता","व्यक्तिगत जवाबदेही","संवर्धक अंतःक्रिया (promotive interaction)","समूह-प्रक्रमण (group processing)"],"explanationHi":"समूह-प्रक्रमण समूह का इस पर चिंतन है कि उसने साथ मिलकर कितना अच्छा कार्य किया और सुधार कैसे करें; इसी से सहकारी कौशल समय के साथ बढ़ते हैं।"},
  {"id":"cdp-pedagogy-subjects-1080","question":"Assertion (A): Seating students in groups of four and giving each group a worksheet is enough to ensure cooperative learning. Reason (R): Cooperative learning needs deliberately structured interdependence, individual accountability and social skills.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is false, but R is true","A is true, but R is false"],"answer":2,"explanation":"Sitting together is only group seating; without structure, one child may do the work while others watch. R names what turns group work into cooperative learning, and so shows that A is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"अभिकथन (A): विद्यार्थियों को चार-चार के समूहों में बिठाना और प्रत्येक समूह को एक कार्य-पत्र देना सहकारी अधिगम सुनिश्चित करने के लिए पर्याप्त है। कारण (R): सहकारी अधिगम को सोची-समझी रूप से संरचित अंतर-निर्भरता, व्यक्तिगत जवाबदेही और सामाजिक कौशलों की आवश्यकता होती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A असत्य है, परंतु R सत्य है","A सत्य है, परंतु R असत्य है"],"explanationHi":"साथ बैठना केवल समूह में बैठना है; संरचना के बिना एक बच्चा काम कर सकता है जबकि बाकी देखते रहें। R बताता है कि समूह-कार्य को सहकारी अधिगम क्या बनाता है, और इस प्रकार दिखाता है कि A असत्य है।"},
  {"id":"cdp-pedagogy-subjects-1081","question":"Consider the following statements about forming groups for cooperative learning: 1. Mixed-ability (heterogeneous) groups are generally recommended for most cooperative tasks. 2. Groups should always be formed by letting friends sit together, so that there is no conflict. 3. Groups may occasionally be formed by interest or need for a specific purpose. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Heterogeneous groups bring diverse ideas and peer support, and purpose-based groups have their place. Always grouping by friendship tends to exclude some children and reinforce cliques, so statement 2 is wrong.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"सहकारी अधिगम के लिए समूह बनाने के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. अधिकांश सहकारी कार्यों के लिए मिश्रित-योग्यता (विषमजातीय) समूह सामान्यतः अनुशंसित हैं। 2. समूह हमेशा मित्रों को साथ बैठने देकर बनाए जाने चाहिए, ताकि कोई संघर्ष न हो। 3. विशिष्ट उद्देश्य के लिए समूह कभी-कभी रुचि या आवश्यकता के आधार पर बनाए जा सकते हैं। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"विषमजातीय समूह विविध विचार और सहपाठी सहायता लाते हैं, और उद्देश्य-आधारित समूहों का भी अपना स्थान है। हमेशा मित्रता के आधार पर समूह बनाने से कुछ बच्चे बाहर रह जाते हैं और गुटबाज़ी को बल मिलता है, इसलिए कथन 2 गलत है।"},
  {"id":"cdp-pedagogy-subjects-1082","question":"A Class VI teacher finds that in group work some students let others do everything. Which combination of steps best reduces this 'free rider' problem?","options":["Make groups larger, so that there is more help available for everyone","Rotating roles, a short individual quiz and choosing the presenter at random","Give the group mark only to the group leader, who then shares it out","Stop group work and return to individual seatwork for the rest of the school term"],"answer":1,"explanation":"Clear roles, individual checks and random reporting all make each person's learning visible. Larger groups make loafing easier, not harder.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VI की एक शिक्षिका पाती है कि समूह-कार्य में कुछ विद्यार्थी दूसरों को सब कुछ करने देते हैं। इस 'मुफ़्तख़ोरी' की समस्या को सबसे अच्छी तरह कम करने वाले चरणों का कौन-सा संयोजन है?","optionsHi":["समूहों को बड़ा बनाना, ताकि सबके लिए अधिक सहायता उपलब्ध हो","भूमिकाओं को बदलते रहना, एक छोटी व्यक्तिगत प्रश्नोत्तरी और प्रस्तुतकर्ता को यादृच्छिक रूप से चुनना","समूह के अंक केवल समूह-नायक को देना, जो फिर उन्हें बाँट देता है","समूह-कार्य बंद करके शेष सत्र के लिए व्यक्तिगत सीट-कार्य पर लौटना"],"explanationHi":"स्पष्ट भूमिकाएँ, व्यक्तिगत जाँच और यादृच्छिक रिपोर्टिंग, ये सब हर व्यक्ति के अधिगम को दृश्यमान बनाते हैं। बड़े समूह आलस्य को कठिन नहीं, आसान बनाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1083","question":"In a Class V class, a teacher assigns group roles of reader, recorder, timekeeper and reporter. She notices that girls are always chosen as recorders and boys as reporters. What should she do?","options":["Keep the same roles all year, since children work best in the role they are good at","Remove all roles, since roles create stereotypes","Assign roles herself and rotate them regularly, so every child practises every role","Allow only boys to be timekeepers and only girls to be readers"],"answer":2,"explanation":"Rotating roles lets each child develop all the skills and breaks gender stereotyping. Fixed roles lock children into patterns, while removing roles loses the structure they provide.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"कक्षा V की एक कक्षा में शिक्षिका पाठक, अभिलेखक, समयपाल और प्रतिवेदक की समूह-भूमिकाएँ देती है। वह देखती है कि लड़कियाँ हमेशा अभिलेखक और लड़के प्रतिवेदक चुने जाते हैं। उसे क्या करना चाहिए?","optionsHi":["पूरे वर्ष वही भूमिकाएँ रखनी चाहिए, क्योंकि बच्चे उस भूमिका में सबसे अच्छा कार्य करते हैं जिसमें वे कुशल हों","सभी भूमिकाएँ हटा देनी चाहिए, क्योंकि भूमिकाएँ रूढ़ियाँ बनाती हैं","स्वयं भूमिकाएँ सौंपनी चाहिए और उन्हें नियमित रूप से बदलना चाहिए, ताकि हर बच्चा हर भूमिका का अभ्यास करे","केवल लड़कों को समयपाल और केवल लड़कियों को पाठक बनने देना चाहिए"],"explanationHi":"भूमिकाएँ बदलने से हर बच्चा सभी कौशल विकसित कर पाता है और लैंगिक रूढ़िबद्धता टूटती है। स्थिर भूमिकाएँ बच्चों को ढर्रों में बाँध देती हैं, जबकि भूमिकाएँ हटाने से वह संरचना खो जाती है जो वे देती हैं।"},
  {"id":"cdp-pedagogy-subjects-1084","question":"Assertion (A): In peer tutoring, the tutor also gains academically, not only the tutee. Reason (R): Explaining a concept to someone else makes the tutor organise, clarify and fill gaps in his or her own understanding.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Teaching requires structuring knowledge, anticipating questions and finding examples, which deepens the tutor's understanding. This is why tutors benefit, as R explains.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"अभिकथन (A): सहपाठी शिक्षण (peer tutoring) में न केवल शिक्षार्थी, बल्कि शिक्षक-विद्यार्थी को भी शैक्षणिक लाभ होता है। कारण (R): किसी दूसरे को संकल्पना समझाने से शिक्षक-विद्यार्थी को अपनी समझ को व्यवस्थित करना, स्पष्ट करना और उसकी कमियाँ भरनी पड़ती हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"पढ़ाने के लिए ज्ञान को संरचित करना, प्रश्नों का पूर्वानुमान लगाना और उदाहरण खोजना पड़ता है, जिससे शिक्षक-विद्यार्थी की समझ गहरी होती है। इसीलिए वह लाभान्वित होता है, जैसा R समझाता है।"},
  {"id":"cdp-pedagogy-subjects-1085","question":"A Class III teacher pairs Kiran, who can solve simple subtraction with borrowing, with Babli, who can almost do it but needs help at one step. Babli then solves the next problems on her own. Which idea best explains why this pairing worked?","options":["Piaget's view that children learn only through solitary exploration of objects","Skinner's idea that each correct answer must be reinforced with a reward","Kohler's idea of insight, which comes suddenly without any help from others","Vygotsky's idea that a more able peer can scaffold a child within her ZPD"],"answer":3,"explanation":"Babli was within her ZPD: able with help, not yet alone. A more knowledgeable other (here a peer) scaffolded the step until she could manage independently.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा III की एक शिक्षिका किरण को, जो उधार लेकर सरल घटाव हल कर सकती है, बबली के साथ जोड़ी बनाती है, जो उसे लगभग कर सकती है पर एक चरण में सहायता चाहिए। फिर बबली अगले प्रश्न स्वयं हल करती है। यह जोड़ी क्यों सफल रही, इसे कौन-सा विचार सबसे अच्छी तरह समझाता है?","optionsHi":["पियाजे का मत कि बच्चे केवल वस्तुओं की एकाकी खोज से सीखते हैं","स्किनर का विचार कि प्रत्येक सही उत्तर को पुरस्कार से पुनर्बलित किया जाना चाहिए","कोहलर का अंतर्दृष्टि का विचार, जो दूसरों की किसी भी सहायता के बिना अचानक आती है","वाइगोत्स्की का विचार कि अधिक सक्षम सहपाठी बच्चे को उसके ZPD के भीतर पाड़ (scaffolding) दे सकता है"],"explanationHi":"बबली अपने ZPD के भीतर थी: सहायता से सक्षम, अभी अकेले नहीं। अधिक जानकार अन्य (यहाँ एक सहपाठी) ने उस चरण में पाड़ दिया जब तक वह स्वतंत्र रूप से सँभाल न सकी।"},
  {"id":"cdp-pedagogy-subjects-1086","question":"In a Class VI reading group, students take turns leading discussion of a passage using four strategies: predicting what comes next, asking questions, clarifying difficult words or ideas, and summarising. The teacher models first and then gradually hands over. This approach is known as:","options":["Jigsaw","Reciprocal teaching","Round-robin reading","Programmed instruction"],"answer":1,"explanation":"Reciprocal teaching (Palincsar and Brown) uses the four strategies of predicting, questioning, clarifying and summarising, with the teacher's role passing gradually to students. Round-robin reading is simply reading aloud in turns.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VI के पठन-समूह में विद्यार्थी बारी-बारी से चार युक्तियों का प्रयोग करके किसी गद्यांश की चर्चा का नेतृत्व करते हैं: आगे क्या होगा इसका पूर्वानुमान, प्रश्न पूछना, कठिन शब्दों या विचारों का स्पष्टीकरण, और सारांश बनाना। शिक्षक पहले आदर्श प्रस्तुत करता है और फिर धीरे-धीरे सौंप देता है। इस उपागम को कहते हैं:","optionsHi":["जिगसॉ","पारस्परिक शिक्षण (reciprocal teaching)","क्रमवार पठन (round-robin reading)","अभिक्रमित अनुदेशन"],"explanationHi":"पारस्परिक शिक्षण (पैलिंक्सर और ब्राउन) पूर्वानुमान, प्रश्न, स्पष्टीकरण और सारांश की चार युक्तियों का उपयोग करता है, जिसमें शिक्षक की भूमिका धीरे-धीरे विद्यार्थियों को सौंपी जाती है। क्रमवार पठन केवल बारी-बारी से ज़ोर से पढ़ना है।"},
  {"id":"cdp-pedagogy-subjects-1087","question":"A Class VII teacher holds a quiz where only the top-scoring group gets a prize, and groups hide answers from each other. Which statement best evaluates this structure?","options":["It is cooperative learning, since students work together within their groups","It is the best structure for all learning, since competition always increases effort","It is individualistic learning, since each student's marks are recorded separately","It is competitive; occasional contests are fine, but relying on them blocks sharing"],"answer":3,"explanation":"When one group's success means others' failure, the goal structure is competitive even if students sit in groups. Constant competition tends to demotivate those who rarely win and reduce helping.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VII का एक शिक्षक प्रश्नोत्तरी कराता है जिसमें केवल सबसे अधिक अंक पाने वाले समूह को पुरस्कार मिलता है, और समूह एक-दूसरे से उत्तर छिपाते हैं। इस रचना का मूल्यांकन करने वाला कौन-सा कथन सबसे अच्छा है?","optionsHi":["यह सहकारी अधिगम है, क्योंकि विद्यार्थी अपने समूहों के भीतर साथ मिलकर कार्य करते हैं","यह सभी अधिगम के लिए सर्वोत्तम रचना है, क्योंकि प्रतिस्पर्धा हमेशा प्रयास बढ़ाती है","यह व्यक्तिवादी अधिगम है, क्योंकि प्रत्येक विद्यार्थी के अंक अलग-अलग दर्ज होते हैं","यह प्रतिस्पर्धात्मक है; कभी-कभार प्रतियोगिताएँ ठीक हैं, पर उन पर निर्भर रहना साझा करने को अवरुद्ध करता है"],"explanationHi":"जब एक समूह की सफलता का अर्थ दूसरों की विफलता हो, तो लक्ष्य-संरचना प्रतिस्पर्धात्मक होती है, भले ही विद्यार्थी समूहों में बैठे हों। निरंतर प्रतिस्पर्धा उन विद्यार्थियों को हतोत्साहित करती है जो कभी-कभार ही जीतते हैं और सहायता करना घटाती है।"},
  {"id":"cdp-pedagogy-subjects-1088","question":"For a complex Class VIII science investigation, a teacher forms groups of ten students each so that 'more heads are better than one'. What problem is she most likely to face?","options":["Social loafing, since in large groups some members contribute little","Too much individual accountability, since every member is closely watched","Lack of diverse ideas, since large groups tend to think alike","Excessive competition among members of the same group for the leader's role"],"answer":0,"explanation":"Effort per person tends to drop as group size grows (social loafing), and with ten members many get no real role. Groups of about three to five usually work best for such tasks.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VIII के एक जटिल विज्ञान-अन्वेषण के लिए एक शिक्षिका दस-दस विद्यार्थियों के समूह बनाती है, क्योंकि 'एक से भले दो'। उसके सामने सबसे अधिक संभावना किस समस्या की है?","optionsHi":["सामाजिक आलस्य (social loafing), क्योंकि बड़े समूहों में कुछ सदस्य बहुत कम योगदान देते हैं","अत्यधिक व्यक्तिगत जवाबदेही, क्योंकि प्रत्येक सदस्य पर बारीकी से नज़र रखी जाती है","विविध विचारों का अभाव, क्योंकि बड़े समूह एक जैसा सोचते हैं","नायक की भूमिका के लिए एक ही समूह के सदस्यों के बीच अत्यधिक प्रतिस्पर्धा"],"explanationHi":"समूह का आकार बढ़ने पर प्रति व्यक्ति प्रयास घटता है (सामाजिक आलस्य), और दस सदस्यों में बहुतों को कोई वास्तविक भूमिका नहीं मिलती। ऐसे कार्यों के लिए लगभग तीन से पाँच के समूह सामान्यतः सबसे अच्छे रहते हैं।"},
  {"id":"cdp-pedagogy-subjects-1089","question":"During a group task in Class VI, two members argue strongly about which explanation of the phases of the moon is correct. What is the most appropriate teacher action?","options":["Separate the two students immediately and put them in different groups for the rest of the task","Tell them the correct answer at once so that the argument ends and work continues","Help them test both ideas with a ball-and-torch model and argue about ideas, not people","Give both students a low mark for not cooperating, to discourage such arguments"],"answer":2,"explanation":"Disagreement about ideas can drive learning (constructive controversy) when students are guided to use evidence and respectful talk. Splitting them, ending it with the answer or penalising them wastes the opportunity.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VI में एक समूह-कार्य के दौरान दो सदस्य इस बात पर ज़ोरदार बहस करते हैं कि चंद्रमा की कलाओं की कौन-सी व्याख्या सही है। शिक्षक की सबसे उपयुक्त कार्रवाई क्या है?","optionsHi":["दोनों विद्यार्थियों को तुरंत अलग करके शेष कार्य के लिए अलग समूहों में रख देना","उन्हें तुरंत सही उत्तर बता देना ताकि बहस समाप्त हो और कार्य जारी रहे","गेंद-और-टॉर्च के मॉडल से दोनों विचारों को परखने में उनकी मदद करना और व्यक्तियों पर नहीं, विचारों पर बहस करवाना","सहयोग न करने के लिए दोनों विद्यार्थियों को कम अंक देना, ताकि ऐसी बहसें हतोत्साहित हों"],"explanationHi":"विचारों पर असहमति अधिगम को आगे बढ़ा सकती है (रचनात्मक विवाद) जब विद्यार्थियों को साक्ष्य और सम्मानजनक संवाद का उपयोग करने के लिए निर्देशित किया जाए। उन्हें अलग करना, उत्तर देकर बात खत्म करना या दंडित करना इस अवसर को व्यर्थ कर देता है।"},
  {"id":"cdp-pedagogy-subjects-1090","question":"Tara, a Class V student who uses a wheelchair and is excellent at drawing, is in a group making a poster about local birds. How should the teacher plan her participation?","options":["Let Tara watch the group, since moving around the room is difficult for her","Let her draw the birds, using her strengths, and keep materials within her reach","Give Tara a separate individual task so that she is not a burden on the rest of the group","Ask the group to complete the poster and then add Tara's name to it as well"],"answer":1,"explanation":"Inclusive cooperative learning gives every member a real, valued role and removes physical barriers. Watching, separate work or token credit all exclude her from genuine participation.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"कक्षा V की विद्यार्थी तारा, जो व्हीलचेयर का उपयोग करती है और चित्रकला में उत्कृष्ट है, स्थानीय पक्षियों पर पोस्टर बनाने वाले समूह में है। शिक्षक को उसकी भागीदारी की योजना कैसे बनानी चाहिए?","optionsHi":["तारा को समूह को देखने देना, क्योंकि कमरे में घूमना उसके लिए कठिन है","उसे अपनी शक्तियों का उपयोग करते हुए पक्षियों के चित्र बनाने देना, और सामग्री उसकी पहुँच के भीतर रखना","तारा को अलग व्यक्तिगत कार्य देना, ताकि वह समूह के बाकी सदस्यों पर बोझ न बने","समूह से पोस्टर पूरा करवाना और फिर उस पर तारा का नाम भी जोड़ देना"],"explanationHi":"समावेशी सहकारी अधिगम हर सदस्य को वास्तविक, मूल्यवान भूमिका देता है और भौतिक बाधाएँ हटाता है। देखना, अलग कार्य या प्रतीकात्मक श्रेय, ये सब उसे वास्तविक भागीदारी से बाहर रखते हैं।"},
  {"id":"cdp-pedagogy-subjects-1091","question":"How should a Class VII teacher assess a cooperative group project fairly?","options":["Give the same mark to everyone in the group, since they worked as a single team","Give marks only for how neat and attractive the final product looks on display","Allow the group leader alone to decide each member's marks, since she saw the work","Combine a group mark for the product with checks of each student's own learning"],"answer":3,"explanation":"Fair assessment of group work values both the joint product and each member's learning, keeping individual accountability. A single shared mark or a leader's judgement can hide free riders or bias.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VII के शिक्षक को सहकारी समूह-परियोजना का निष्पक्ष आकलन कैसे करना चाहिए?","optionsHi":["समूह में सभी को समान अंक देना, क्योंकि उन्होंने एक ही टीम के रूप में कार्य किया","केवल इस आधार पर अंक देना कि अंतिम उत्पाद प्रदर्शन में कितना साफ़ और आकर्षक दिखता है","समूह-नायक को अकेले प्रत्येक सदस्य के अंक तय करने देना, क्योंकि उसने कार्य देखा","उत्पाद के लिए समूह के अंकों को प्रत्येक विद्यार्थी के अपने अधिगम की जाँच के साथ जोड़ना"],"explanationHi":"समूह-कार्य का निष्पक्ष आकलन संयुक्त उत्पाद और प्रत्येक सदस्य के अधिगम, दोनों को महत्त्व देता है और व्यक्तिगत जवाबदेही बनाए रखता है। एक साझा अंक या नायक का निर्णय मुफ़्तख़ोरों या पक्षपात को छिपा सकता है।"},
  {"id":"cdp-pedagogy-subjects-1092","question":"Before group work, a Class IV teacher draws a chart with two columns, 'Looks like' and 'Sounds like', and asks children to suggest what 'listening to your partner' looks and sounds like (eyes on speaker; 'I agree because...'). What is she doing?","options":["Explicitly teaching a social skill needed for cooperative learning","Wasting time that should be used for content","Assessing children's knowledge of the lesson content","Creating a competition between children who listen and those who do not"],"answer":0,"explanation":"Cooperative skills such as listening and disagreeing politely must be taught deliberately; a T-chart makes the skill concrete. Johnson and Johnson list social skills as an essential element.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"समूह-कार्य से पहले कक्षा IV की शिक्षिका दो स्तंभों वाला चार्ट बनाती है, 'दिखता है' और 'सुनाई देता है', और बच्चों से सुझाव माँगती है कि 'अपने साथी की बात सुनना' कैसा दिखता और सुनाई देता है (नज़र वक्ता पर; 'मैं सहमत हूँ क्योंकि...')। वह क्या कर रही है?","optionsHi":["सहकारी अधिगम के लिए आवश्यक सामाजिक कौशल को स्पष्ट रूप से सिखा रही है","उस समय को व्यर्थ कर रही है जो विषय-वस्तु के लिए प्रयोग होना चाहिए","पाठ की विषय-वस्तु के बारे में बच्चों के ज्ञान का आकलन कर रही है","सुनने वाले और न सुनने वाले बच्चों के बीच प्रतियोगिता बना रही है"],"explanationHi":"सुनना और विनम्रता से असहमत होना जैसे सहकारी कौशल सोच-समझकर सिखाए जाने चाहिए; T-चार्ट कौशल को मूर्त बनाता है। जॉनसन और जॉनसन सामाजिक कौशलों को एक आवश्यक तत्त्व बताते हैं।"},
  {"id":"cdp-pedagogy-subjects-1093","question":"In a Class V maths class, each group member gets a number from 1 to 4. Groups discuss a problem until all members can explain the answer, and then the teacher calls out a number at random; that member from each group answers. What does this strategy mainly ensure?","options":["Only the brightest child in each group needs to understand the problem","The group with the fastest and brightest member always wins the round","Every member must understand, since anyone may be called to answer","Children do not need to discuss with one another before answering"],"answer":2,"explanation":"Numbered Heads Together combines group support with individual accountability: because the reporter is random, the group must make sure everyone understands.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा V की गणित कक्षा में प्रत्येक समूह-सदस्य को 1 से 4 तक की संख्या दी जाती है। समूह तब तक किसी प्रश्न पर चर्चा करते हैं जब तक सभी सदस्य उत्तर समझा न सकें, और फिर शिक्षिका यादृच्छिक रूप से एक संख्या बोलती है; प्रत्येक समूह का वह सदस्य उत्तर देता है। यह युक्ति मुख्यतः क्या सुनिश्चित करती है?","optionsHi":["प्रत्येक समूह में केवल सबसे तेज़ बच्चे को प्रश्न समझने की आवश्यकता है","सबसे तेज़ और प्रतिभाशाली सदस्य वाला समूह हमेशा चरण जीतता है","प्रत्येक सदस्य को समझना ही होगा, क्योंकि किसी को भी उत्तर देने के लिए बुलाया जा सकता है","उत्तर देने से पहले बच्चों को एक-दूसरे से चर्चा करने की आवश्यकता नहीं है"],"explanationHi":"क्रमांकित सिर साथ-साथ (Numbered Heads Together) समूह की सहायता को व्यक्तिगत जवाबदेही के साथ जोड़ता है: प्रतिवेदक यादृच्छिक होने के कारण समूह को सुनिश्चित करना पड़ता है कि सभी समझें।"},
  {"id":"cdp-pedagogy-subjects-1094","question":"Class VI students are giving feedback on each other's story drafts. Which instruction from the teacher is most likely to make peer feedback useful?","options":["'Give each story a mark out of ten and write the mark at the top.'","'Write whatever you like about your friend's story, as long as it is honest.'","'Point out all the spelling and punctuation mistakes you can find in it.'","'Using the checklist, name one strength and one specific way to improve it.'"],"answer":3,"explanation":"Peer feedback works when it is guided by criteria and is specific, kind and actionable. Marks alone or error hunting give little help for revision.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VI के विद्यार्थी एक-दूसरे की कहानी के मसौदों पर प्रतिपुष्टि दे रहे हैं। शिक्षक का कौन-सा निर्देश सहपाठी प्रतिपुष्टि को उपयोगी बनाने की सबसे अधिक संभावना रखता है?","optionsHi":["'प्रत्येक कहानी को दस में से अंक दो और अंक ऊपर लिख दो।'","'अपने मित्र की कहानी के बारे में जो चाहो लिखो, बशर्ते वह ईमानदार हो।'","'उसमें जितनी वर्तनी और विराम-चिह्न की गलतियाँ मिलें, सब बताओ।'","'जाँच-सूची का उपयोग करके एक शक्ति और सुधार का एक विशिष्ट तरीका बताओ।'"],"explanationHi":"सहपाठी प्रतिपुष्टि तब कारगर होती है जब वह मानदंडों से निर्देशित हो और विशिष्ट, दयालु तथा क्रियान्वित करने योग्य हो। केवल अंक या गलतियाँ ढूँढ़ना संशोधन के लिए कम मदद देता है।"},
  {"id":"cdp-pedagogy-subjects-1095","question":"A school in Nashik sets up a programme in which Class VII students, including some who are themselves weak readers, read with Class III children twice a week. Which outcome is most likely, according to research on cross-age tutoring?","options":["Only the Class III children benefit, since the Class VII students already know how to read","Both gain: younger children get attention, and tutors gain practice and confidence","Neither group benefits, since only trained teachers can teach reading well","The older weak readers will feel embarrassed and should be removed from the programme"],"answer":1,"explanation":"Cross-age tutoring gives tutees individual support, while tutors (even low achievers) practise skills at an easy level in a respected role, which builds esteem. Excluding weaker older readers removes those gains.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"नाशिक का एक विद्यालय ऐसा कार्यक्रम शुरू करता है जिसमें कक्षा VII के विद्यार्थी, जिनमें कुछ स्वयं कमज़ोर पाठक भी हैं, सप्ताह में दो बार कक्षा III के बच्चों के साथ पढ़ते हैं। आयु-मिश्रित शिक्षण (cross-age tutoring) पर शोध के अनुसार कौन-सा परिणाम सबसे संभावित है?","optionsHi":["केवल कक्षा III के बच्चों को लाभ होगा, क्योंकि कक्षा VII के विद्यार्थी पहले से पढ़ना जानते हैं","दोनों को लाभ होगा: छोटे बच्चों को ध्यान मिलता है, और शिक्षक-विद्यार्थियों को अभ्यास और आत्मविश्वास","किसी भी समूह को लाभ नहीं होगा, क्योंकि केवल प्रशिक्षित शिक्षक ही पढ़ना अच्छी तरह सिखा सकते हैं","बड़े कमज़ोर पाठक शर्मिंदगी महसूस करेंगे और उन्हें कार्यक्रम से हटा देना चाहिए"],"explanationHi":"आयु-मिश्रित शिक्षण शिक्षार्थियों को व्यक्तिगत सहायता देता है, जबकि शिक्षक-विद्यार्थी (निम्न उपलब्धि वाले भी) सम्मानित भूमिका में आसान स्तर पर कौशलों का अभ्यास करते हैं, जिससे आत्म-सम्मान बनता है। कमज़ोर बड़े पाठकों को बाहर करने से ये लाभ समाप्त हो जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1096","question":"Match each classroom move with the element of cooperative learning it builds. P. The group cannot finish unless each member contributes a part. Q. The teacher randomly picks one member to explain the group's answer. R. Groups reflect on how well they cooperated. S. The teacher models how to disagree politely. Elements: 1. Social skills; 2. Group processing; 3. Individual accountability; 4. Positive interdependence.","options":["P-4, Q-3, R-2, S-1","P-3, Q-4, R-2, S-1","P-4, Q-3, R-1, S-2","P-4, Q-2, R-3, S-1"],"answer":0,"explanation":"Needing every member's part is positive interdependence; random reporting is individual accountability; reflecting on teamwork is group processing; modelling polite disagreement teaches social skills.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"प्रत्येक कक्षा-क्रिया को सहकारी अधिगम के उस तत्त्व से मिलाइए जिसे वह निर्मित करती है। P. समूह तब तक पूरा नहीं कर सकता जब तक प्रत्येक सदस्य एक भाग का योगदान न दे। Q. शिक्षक यादृच्छिक रूप से एक सदस्य को समूह का उत्तर समझाने के लिए चुनता है। R. समूह इस पर चिंतन करते हैं कि उन्होंने कितना अच्छा सहयोग किया। S. शिक्षक आदर्श प्रस्तुत करता है कि विनम्रता से असहमति कैसे जताएँ। तत्त्व: 1. सामाजिक कौशल; 2. समूह-प्रक्रमण; 3. व्यक्तिगत जवाबदेही; 4. सकारात्मक अंतर-निर्भरता।","optionsHi":["P-4, Q-3, R-2, S-1","P-3, Q-4, R-2, S-1","P-4, Q-3, R-1, S-2","P-4, Q-2, R-3, S-1"],"explanationHi":"प्रत्येक सदस्य के भाग की आवश्यकता सकारात्मक अंतर-निर्भरता है; यादृच्छिक रिपोर्टिंग व्यक्तिगत जवाबदेही है; टीम-कार्य पर चिंतन समूह-प्रक्रमण है; विनम्र असहमति का आदर्श प्रस्तुत करना सामाजिक कौशल सिखाता है।"},
  {"id":"cdp-pedagogy-subjects-1097","question":"A Class VIII teacher deliberately mixes students of different castes, religions and genders in cooperative groups working towards a common goal, with each having an equal role. What outcome does research on intergroup contact predict?","options":["More conflict, since mixing different social groups always creates tension","No change in attitudes, since prejudice is learnt only at home and cannot really shift","Better academic marks only, with no effect on how students view each other","Reduced prejudice, since the contact is between equals working towards shared goals"],"answer":3,"explanation":"Allport's contact hypothesis holds that contact reduces prejudice when groups have equal status, common goals, cooperation and support from authority, conditions that cooperative learning provides.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VIII का एक शिक्षक साझा लक्ष्य की ओर कार्य करने वाले सहकारी समूहों में विभिन्न जातियों, धर्मों और लिंगों के विद्यार्थियों को सोच-समझकर मिलाता है, और प्रत्येक की भूमिका समान होती है। अंतर-समूह संपर्क पर शोध किस परिणाम की भविष्यवाणी करता है?","optionsHi":["अधिक संघर्ष, क्योंकि विभिन्न सामाजिक समूहों को मिलाना हमेशा तनाव पैदा करता है","अभिवृत्तियों में कोई परिवर्तन नहीं, क्योंकि पूर्वाग्रह केवल घर पर सीखा जाता है और वास्तव में बदल नहीं सकता","केवल बेहतर शैक्षणिक अंक, विद्यार्थी एक-दूसरे को कैसे देखते हैं इस पर कोई प्रभाव नहीं","पूर्वाग्रह में कमी, क्योंकि संपर्क साझा लक्ष्यों की ओर कार्य करने वाले समान लोगों के बीच है"],"explanationHi":"ऑलपोर्ट की संपर्क परिकल्पना कहती है कि संपर्क तब पूर्वाग्रह घटाता है जब समूहों की स्थिति समान हो, साझा लक्ष्य हों, सहयोग हो और अधिकारी का समर्थन हो, ये शर्तें सहकारी अधिगम पूरी करता है।"},
  {"id":"cdp-pedagogy-subjects-1098","question":"While groups in a Class V class work on a task, what should the teacher mainly be doing?","options":["Moving among groups, observing, asking questions and helping without taking over","Sitting at her desk checking notebooks, since the children are working on their own","Standing at the front and explaining the answer so that groups do not make mistakes","Leaving the room, since group work runs itself and children work better alone"],"answer":0,"explanation":"During group work the teacher monitors and intervenes judiciously as a facilitator, gathering evidence of learning and supporting progress. Withdrawing or giving answers both undermine the activity.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"जब कक्षा V की कक्षा में समूह किसी कार्य पर काम कर रहे हों, तब शिक्षिका को मुख्यतः क्या करना चाहिए?","optionsHi":["समूहों के बीच घूमना, अवलोकन करना, प्रश्न पूछना और कार्य अपने हाथ में लिए बिना सहायता करना","अपनी मेज़ पर बैठकर कॉपियाँ जाँचना, क्योंकि बच्चे अपने आप कार्य कर रहे हैं","आगे खड़े होकर उत्तर समझाना ताकि समूह गलतियाँ न करें","कमरा छोड़कर चले जाना, क्योंकि समूह-कार्य अपने आप चलता है और बच्चे अकेले बेहतर कार्य करते हैं"],"explanationHi":"समूह-कार्य के दौरान शिक्षक सुगमकर्ता के रूप में निगरानी करता है और विवेकपूर्वक हस्तक्षेप करता है, अधिगम का साक्ष्य जुटाता है और प्रगति में सहायता देता है। पीछे हट जाना या उत्तर दे देना, दोनों गतिविधि को कमज़ोर करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1099","question":"A classroom model of the solar system shows the sun and the planets as balls of similar size placed a few centimetres apart. The most important point for the teacher to keep in mind is that:","options":["models confuse children and should never be used to teach EVS topics","the model is accurate, so children can rely on it fully for sizes","it cannot show real sizes and distances, so its limits must be discussed","only a costly model would show the correct sizes and distances of the planets"],"answer":2,"explanation":"Every model simplifies; a model at true scale would not fit in a room. Discussing what the model shows and what it distorts prevents children taking its sizes and distances literally.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा में सौरमंडल का एक मॉडल सूर्य और ग्रहों को समान आकार की गेंदों के रूप में कुछ सेंटीमीटर की दूरी पर रखकर दिखाता है। शिक्षक को सबसे महत्त्वपूर्ण बात क्या ध्यान में रखनी चाहिए?","optionsHi":["मॉडल बच्चों को भ्रमित करते हैं और EVS के विषय पढ़ाने के लिए उनका कभी उपयोग नहीं करना चाहिए","मॉडल सटीक है, इसलिए बच्चे आकारों के लिए उस पर पूरा भरोसा कर सकते हैं","वह वास्तविक आकार और दूरियाँ नहीं दिखा सकता, इसलिए उसकी सीमाओं पर चर्चा की जानी चाहिए","केवल महँगा मॉडल ही ग्रहों के सही आकार और दूरियाँ दिखा सकता है"],"explanationHi":"प्रत्येक मॉडल सरलीकरण करता है; वास्तविक पैमाने का मॉडल एक कमरे में समा नहीं सकता। यह चर्चा करना कि मॉडल क्या दिखाता है और क्या विकृत करता है, बच्चों को उसके आकारों और दूरियों को शब्दशः लेने से रोकता है।"},
  {"id":"cdp-pedagogy-subjects-1100","question":"A Class 4 teacher teaches the parts of a flower only with a printed chart. The main limitation of this approach is that:","options":["children cannot handle real flowers or see their variety and 3-D form","charts are not allowed in EVS classes under the NCF 2005 guidelines","charts are too colourful and distract children from the lesson's content","the chart will make the lesson too long for a single forty-minute period"],"answer":0,"explanation":"A chart shows one idealised flower in two dimensions. Real flowers of different kinds give first-hand, multisensory observation, which a chart can only supplement.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 4 का एक शिक्षक फूल के भाग केवल छपे हुए चार्ट से पढ़ाता है। इस उपागम की मुख्य सीमा यह है कि:","optionsHi":["बच्चे वास्तविक फूलों को छू नहीं सकते और उनकी विविधता और 3-D रूप नहीं देख सकते","NCF 2005 के दिशानिर्देशों के अंतर्गत EVS की कक्षाओं में चार्ट की अनुमति नहीं है","चार्ट बहुत रंगीन होते हैं और बच्चों का ध्यान पाठ की विषय-वस्तु से भटकाते हैं","चार्ट के कारण पाठ चालीस मिनट के एक कालांश के लिए बहुत लंबा हो जाएगा"],"explanationHi":"चार्ट एक आदर्शीकृत फूल को दो आयामों में दिखाता है। विभिन्न प्रकार के वास्तविक फूल प्रत्यक्ष, बहु-संवेदी अवलोकन देते हैं, जिसकी चार्ट केवल पूरक हो सकता है।"},
  {"id":"cdp-pedagogy-subjects-1101","question":"Looking at a wall map of India, a Class 5 child says that Jammu and Kashmir is at the ‘top’ so it must be the highest place, while Tamil Nadu is ‘at the bottom’ and therefore low. This idea mainly arises from:","options":["a lack of interest in maps and geography lessons","a lack of the drawing skill needed to copy maps","the map being too small to show the heights of places clearly","treating ‘north’ on a map as meaning ‘up’ or higher"],"answer":3,"explanation":"A map’s top is a convention for direction, not height. Children often confuse north with ‘up’; the teacher should make that convention explicit.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"भारत का दीवार-मानचित्र देखते हुए कक्षा 5 का एक बच्चा कहता है कि जम्मू और कश्मीर 'ऊपर' है इसलिए वह सबसे ऊँचा स्थान होगा, जबकि तमिलनाडु 'नीचे' है इसलिए नीचा है। यह विचार मुख्यतः किससे उत्पन्न होता है:","optionsHi":["मानचित्रों और भूगोल के पाठों में रुचि की कमी","मानचित्र की नकल करने के लिए आवश्यक चित्रकला-कौशल की कमी","मानचित्र का बहुत छोटा होना, जो स्थानों की ऊँचाई स्पष्ट नहीं दिखाता","मानचित्र पर 'उत्तर' को 'ऊपर' या ऊँचा समझ लेना"],"explanationHi":"मानचित्र का ऊपरी भाग दिशा की परिपाटी है, ऊँचाई की नहीं। बच्चे प्रायः उत्तर को 'ऊपर' समझ लेते हैं; शिक्षक को उस परिपाटी को स्पष्ट करना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1102","question":"What is the strongest reason for children to grow seeds in class rather than only watch a time-lapse video of germination?","options":["Videos are not allowed in primary schools under most state guidelines","It gives first-hand observation over real time, which a video compresses","Seeds are cheaper than a projector, so growing them saves the school money","Children cannot understand videos at all until they reach upper primary"],"answer":1,"explanation":"Direct observation across days builds patience, recording and questioning, and gives a true sense of time. A video is useful, but it is second-hand and can distort how long change takes.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"बच्चों के कक्षा में बीज उगाने के लिए, केवल अंकुरण का टाइम-लैप्स वीडियो देखने के बजाय, सबसे प्रबल कारण क्या है?","optionsHi":["अधिकांश राज्य-दिशानिर्देशों के अंतर्गत प्राथमिक विद्यालयों में वीडियो की अनुमति नहीं है","यह वास्तविक समय में प्रत्यक्ष अवलोकन देता है, जिसे वीडियो संकुचित कर देता है","बीज प्रोजेक्टर से सस्ते हैं, इसलिए उन्हें उगाने से विद्यालय का पैसा बचता है","बच्चे उच्च प्राथमिक स्तर तक पहुँचने से पहले वीडियो बिल्कुल नहीं समझ सकते"],"explanationHi":"दिनों तक प्रत्यक्ष अवलोकन धैर्य, अभिलेखन और प्रश्न पूछने की क्षमता बनाता है और समय की सच्ची समझ देता है। वीडियो उपयोगी है, पर वह द्वितीयक है और परिवर्तन में कितना समय लगता है, इसे विकृत कर सकता है।"},
  {"id":"cdp-pedagogy-subjects-1103","question":"Consider these statements about ICT in primary EVS: I. It can bring distant environments, such as deserts and oceans, into the classroom. II. It should replace direct experience wherever it is available. III. Images taken uncritically from the internet can carry stereotypes. Which are correct?","options":["I only","II and III only","I and III only","I, II and III"],"answer":2,"explanation":"ICT widens access to what children cannot see directly, but it complements rather than replaces first-hand experience, and its images need critical selection.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"प्राथमिक EVS में ICT के बारे में इन कथनों पर विचार कीजिए: I. यह रेगिस्तान और महासागर जैसे दूर के पर्यावरणों को कक्षा में ला सकता है। II. जहाँ प्रत्यक्ष अनुभव उपलब्ध हो वहाँ इसे उसकी जगह ले लेनी चाहिए। III. इंटरनेट से बिना सोचे-समझे लिए गए चित्र रूढ़ियाँ ले जा सकते हैं। कौन-से सही हैं?","optionsHi":["केवल I","केवल II और III","केवल I और III","I, II और III"],"explanationHi":"ICT उन चीज़ों तक पहुँच बढ़ाता है जिन्हें बच्चे सीधे नहीं देख सकते, पर वह प्रत्यक्ष अनुभव का पूरक है, उसकी जगह नहीं लेता, और उसके चित्रों का आलोचनात्मक चयन आवश्यक है।"},
  {"id":"cdp-pedagogy-subjects-1104","question":"Assertion (A): Teaching–learning material should be used with a clear learning purpose. Reason (R): Material alone, however attractive, does not ensure that children learn. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Because learning depends on what children do with the material, it must be chosen and used for a specific purpose. R explains A.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): शिक्षण-अधिगम सामग्री का उपयोग स्पष्ट अधिगम-उद्देश्य के साथ किया जाना चाहिए। कारण (R): केवल सामग्री, चाहे कितनी भी आकर्षक हो, यह सुनिश्चित नहीं करती कि बच्चे सीखें। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"चूँकि अधिगम इस पर निर्भर करता है कि बच्चे सामग्री के साथ क्या करते हैं, उसे किसी विशिष्ट उद्देश्य के लिए चुना और उपयोग किया जाना चाहिए। R, A की व्याख्या करता है।"},
  {"id":"cdp-pedagogy-subjects-1105","question":"A school receives a costly science kit, and the head teacher keeps it locked in the office so that it does not get damaged. The best critique is that:","options":["the kit should be returned, since primary children cannot use such expensive equipment","the kit should be shown to children only on inspection days, to keep it new","only the teacher should touch the kit, during demonstrations at the front","material is meant to be handled; children should learn to use the kit with care"],"answer":3,"explanation":"Unused material teaches nothing. Children can be taught to handle equipment responsibly, and some wear is expected.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"एक विद्यालय को महँगी विज्ञान-किट मिलती है, और प्रधानाध्यापक उसे कार्यालय में बंद रखता है ताकि वह खराब न हो। सबसे अच्छी आलोचना यह है कि:","optionsHi":["किट लौटा दी जानी चाहिए, क्योंकि प्राथमिक बच्चे इतने महँगे उपकरण का उपयोग नहीं कर सकते","किट को बच्चों को केवल निरीक्षण के दिनों में दिखाना चाहिए, ताकि वह नई बनी रहे","केवल शिक्षक को ही सामने प्रदर्शन के दौरान किट छूनी चाहिए","सामग्री हाथ में लेने के लिए होती है; बच्चों को किट का सावधानी से उपयोग करना सिखाया जाना चाहिए"],"explanationHi":"अप्रयुक्त सामग्री कुछ नहीं सिखाती। बच्चों को उपकरण ज़िम्मेदारी से सँभालना सिखाया जा सकता है, और कुछ घिसाव अपेक्षित है।"},
  {"id":"cdp-pedagogy-subjects-1106","question":"In one 40-minute EVS period, a teacher displays fifteen different charts about animals. The main problem is that:","options":["charts should be used only in language classes, never in EVS periods","too many materials overload children, so none can be used meaningfully","the charts should all be about one animal so children are not confused","children should have drawn all fifteen charts themselves beforehand"],"answer":1,"explanation":"More material is not better; each item should serve a purpose and leave time for children to observe and talk. Fifteen charts in one period crowd out thinking.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"40 मिनट के एक EVS कालांश में एक शिक्षक जंतुओं के बारे में पंद्रह अलग-अलग चार्ट प्रदर्शित करता है। मुख्य समस्या यह है कि:","optionsHi":["चार्ट का उपयोग केवल भाषा की कक्षाओं में होना चाहिए, EVS कालांशों में कभी नहीं","बहुत अधिक सामग्री बच्चों पर बोझ डालती है, इसलिए कोई भी सार्थक रूप से उपयोग नहीं हो पाती","सभी चार्ट एक ही जंतु के बारे में होने चाहिए ताकि बच्चे भ्रमित न हों","बच्चों को पहले से सभी पंद्रह चार्ट स्वयं बनाने चाहिए थे"],"explanationHi":"अधिक सामग्री बेहतर नहीं होती; प्रत्येक वस्तु का कोई उद्देश्य होना चाहिए और बच्चों के अवलोकन और बातचीत के लिए समय बचना चाहिए। एक कालांश में पंद्रह चार्ट चिंतन को दबा देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1107","question":"A Class 4 teacher plans to have children catch butterflies and pin them on a board for a display. A better alternative that also meets the EVS aim of concern for living things is to:","options":["observe butterflies in the school garden, record what they do, and leave them free","buy dead butterflies from a shop so that no butterfly is killed by the class","show the finished pinned board without telling children how the butterflies were caught","ask children to catch the insects at home instead of in the school garden"],"answer":0,"explanation":"Observing live animals in their setting supports learning and care for living beings. Killing animals for display goes against the concern EVS aims to build.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 4 का एक शिक्षक बच्चों से तितलियाँ पकड़वाकर प्रदर्शन के लिए बोर्ड पर पिन करवाने की योजना बनाता है। एक बेहतर विकल्प, जो जीवित प्राणियों के प्रति संवेदनशीलता के EVS लक्ष्य को भी पूरा करता है, यह है:","optionsHi":["विद्यालय के बगीचे में तितलियों का अवलोकन करना, वे क्या करती हैं यह दर्ज करना, और उन्हें मुक्त छोड़ देना","दुकान से मृत तितलियाँ खरीदना ताकि कक्षा द्वारा कोई तितली न मारी जाए","बच्चों को बताए बिना कि तितलियाँ कैसे पकड़ी गईं, तैयार पिन किया हुआ बोर्ड दिखाना","बच्चों से कीट विद्यालय के बगीचे के बजाय घर पर पकड़ने को कहना"],"explanationHi":"जीवित जंतुओं का उनके परिवेश में अवलोकन अधिगम और जीवों के प्रति संवेदनशीलता का समर्थन करता है। प्रदर्शन के लिए जंतुओं को मारना उस संवेदनशीलता के विरुद्ध है जिसे EVS बनाना चाहता है।"},
  {"id":"cdp-pedagogy-subjects-1108","question":"A Class 3 teacher gives groups picture cards showing wheat growing in a field, harvesting, threshing, grinding at a chakki and a roti being made, and asks them to arrange the cards in order and say who does each step. The main learning here is:","options":["memorising the names of farm tools such as the sickle, the plough and the chakki","drawing skills, since children later copy the pictures on the cards","the sequence from field to plate and how many people we depend on for food","the price of wheat in the market and how it changes with seasons"],"answer":2,"explanation":"Sequencing the cards builds an understanding of process and of the interdependence of farmers, workers and families, which is central to the ‘Food’ theme.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की एक शिक्षिका समूहों को चित्र-कार्ड देती है जिनमें खेत में गेहूँ उगना, कटाई, दँवरी, चक्की में पीसना और रोटी बनना दिखाया गया है, और उनसे कार्डों को क्रम में लगाने और यह बताने को कहती है कि प्रत्येक चरण कौन करता है। यहाँ मुख्य अधिगम है:","optionsHi":["हँसिया, हल और चक्की जैसे कृषि-औज़ारों के नाम याद करना","चित्रकला-कौशल, क्योंकि बच्चे बाद में कार्डों के चित्र नकल करते हैं","खेत से थाली तक का क्रम और भोजन के लिए हम कितने लोगों पर निर्भर हैं","बाज़ार में गेहूँ का मूल्य और वह मौसमों के साथ कैसे बदलता है"],"explanationHi":"कार्डों को क्रम में लगाने से प्रक्रिया की और किसानों, श्रमिकों और परिवारों की अंतर-निर्भरता की समझ बनती है, जो 'भोजन' विषय का केंद्र है।"},
  {"id":"cdp-pedagogy-subjects-1109","question":"For a Class 3 lesson on food, children bring small samples of grains and pulses from home. Which statement about this is most accurate?","options":["Pictures would be better, since real grains create a mess in class","It works only in rural schools, where grains are easily available at home","It is useful only for children whose families grow these crops","Real objects allow multisensory learning and link the lesson to home"],"answer":3,"explanation":"Children can touch, smell and compare real grains, and the material comes from their own kitchens. This works in any school.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"भोजन पर कक्षा 3 के पाठ के लिए बच्चे घर से अनाज और दालों के छोटे नमूने लाते हैं। इस बारे में कौन-सा कथन सबसे सटीक है?","optionsHi":["चित्र बेहतर होंगे, क्योंकि वास्तविक अनाज कक्षा में गंदगी फैलाते हैं","यह केवल ग्रामीण विद्यालयों में कारगर है, जहाँ घर पर अनाज आसानी से उपलब्ध होता है","यह केवल उन बच्चों के लिए उपयोगी है जिनके परिवार ये फ़सलें उगाते हैं","वास्तविक वस्तुएँ बहु-संवेदी अधिगम की अनुमति देती हैं और पाठ को घर से जोड़ती हैं"],"explanationHi":"बच्चे वास्तविक अनाज को छू, सूँघ और तुलना कर सकते हैं, और सामग्री उनकी अपनी रसोई से आती है। यह किसी भी विद्यालय में कारगर है।"},
  {"id":"cdp-pedagogy-subjects-1110","question":"A diorama of a forest bought for a Class 4 class shows a tiger, a deer, a camel and a penguin together. The most appropriate response is that:","options":["it is fine, since children only need to see a variety of animals together in one place","material must be checked for accuracy, as mixed habitats create misconceptions","the diorama should be kept in the classroom but used only for decoration","the penguin and camel can be ignored, since children will not notice them"],"answer":1,"explanation":"Inaccurate material teaches errors; camels and penguins do not share a forest with tigers. Teachers must check what material conveys before using it.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 के लिए खरीदा गया जंगल का एक डायोरामा बाघ, हिरण, ऊँट और पेंगुइन को एक साथ दिखाता है। सबसे उपयुक्त प्रतिक्रिया यह है कि:","optionsHi":["यह ठीक है, क्योंकि बच्चों को केवल एक स्थान पर अनेक प्रकार के जंतु साथ देखने की आवश्यकता है","सामग्री की सटीकता जाँची जानी चाहिए, क्योंकि मिश्रित आवास भ्रांतियाँ पैदा करते हैं","डायोरामा को कक्षा में रखा जाए, पर केवल सजावट के लिए उपयोग किया जाए","पेंगुइन और ऊँट की उपेक्षा की जा सकती है, क्योंकि बच्चे उन पर ध्यान नहीं देंगे"],"explanationHi":"गलत सामग्री त्रुटियाँ सिखाती है; ऊँट और पेंगुइन बाघों के साथ जंगल में नहीं रहते। शिक्षकों को उपयोग से पहले जाँचना चाहिए कि सामग्री क्या संप्रेषित करती है।"},
  {"id":"cdp-pedagogy-subjects-1111","question":"Children in a Class 3 class in southern Rajasthan speak Bhili at home, while the EVS textbook is in standard Hindi. Which statement best describes this situation?","options":["The textbook’s language may be a barrier, so the teacher should bridge it via Bhili","The textbook should be withdrawn from these schools until a Bhili one is printed","Children should be told to speak only Hindi in class so they learn it faster","The language of the textbook makes no real difference to how well children learn EVS"],"answer":0,"explanation":"A textbook in an unfamiliar language limits access; NCF 2005 asks teachers to use the home language as a resource. Banning it or ignoring the gap harms understanding.","difficulty":"hard","source":"CTET Paper 1 · REET Level 1","questionHi":"दक्षिणी राजस्थान की कक्षा 3 के बच्चे घर पर भीली बोलते हैं, जबकि EVS की पाठ्यपुस्तक मानक हिंदी में है। इस स्थिति का सबसे अच्छा वर्णन कौन-सा कथन करता है?","optionsHi":["पाठ्यपुस्तक की भाषा बाधा हो सकती है, इसलिए शिक्षक को भीली के माध्यम से सेतु बनाना चाहिए","भीली की पाठ्यपुस्तक छपने तक इन विद्यालयों से पाठ्यपुस्तक वापस ले ली जानी चाहिए","बच्चों से कक्षा में केवल हिंदी बोलने को कहा जाना चाहिए ताकि वे उसे जल्दी सीखें","पाठ्यपुस्तक की भाषा से इस पर कोई वास्तविक फ़र्क़ नहीं पड़ता कि बच्चे EVS कितनी अच्छी तरह सीखते हैं"],"explanationHi":"अपरिचित भाषा की पाठ्यपुस्तक पहुँच को सीमित करती है; NCF 2005 शिक्षकों से घर की भाषा को संसाधन के रूप में उपयोग करने को कहती है। उसे प्रतिबंधित करना या अंतर की उपेक्षा करना समझ को हानि पहुँचाता है।"},
  {"id":"cdp-pedagogy-subjects-1112","question":"Which worksheet task best supports EVS learning in Class 3?","options":["Fill in the blanks with words from the chapter on plants around us.","Match the names of plants with the descriptions given in the chapter, as in a key.","Look at two plants in your courtyard, draw them and write how they differ.","Copy the first paragraph of the chapter neatly into your notebook."],"answer":2,"explanation":"The task sends children to observe, draw and compare real plants. The others only rework the text.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 3 में EVS के अधिगम को कौन-सा कार्य-पत्र कार्य सबसे अच्छी तरह समर्थन देता है?","optionsHi":["'हमारे आस-पास के पौधे' अध्याय के शब्दों से रिक्त स्थान भरिए।","अध्याय में दिए गए विवरणों से पौधों के नामों का मिलान कीजिए, जैसे किसी कुंजी में।","अपने आँगन के दो पौधों को देखिए, उनके चित्र बनाइए और लिखिए कि वे कैसे भिन्न हैं।","अध्याय का पहला अनुच्छेद अपनी कॉपी में साफ़-साफ़ उतारिए।"],"explanationHi":"यह कार्य बच्चों को वास्तविक पौधों को देखने, चित्र बनाने और तुलना करने के लिए भेजता है। अन्य कार्य केवल पाठ को दोहराते हैं।"},
  {"id":"cdp-pedagogy-subjects-1113","question":"What is the best reason for Class 4 children to make their own charts of birds seen around the school, instead of the teacher buying a printed chart?","options":["It saves the school money that would be spent on printed charts","Children’s charts are always more accurate than those printed by publishers","Printed charts are not allowed in primary classrooms under NCF 2005","Observing, choosing what to show and organising it is itself the learning"],"answer":3,"explanation":"The process of making the chart, which involves observing, deciding and arranging, builds understanding. Cost is a side benefit; accuracy is not guaranteed.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 के बच्चों के शिक्षक द्वारा छपा हुआ चार्ट खरीदने के बजाय विद्यालय के आस-पास देखे गए पक्षियों के अपने चार्ट बनाने का सबसे अच्छा कारण क्या है?","optionsHi":["इससे विद्यालय का वह पैसा बचता है जो छपे चार्टों पर खर्च होता","बच्चों के चार्ट प्रकाशकों द्वारा छापे गए चार्टों से हमेशा अधिक सटीक होते हैं","NCF 2005 के अंतर्गत प्राथमिक कक्षाओं में छपे चार्ट की अनुमति नहीं है","अवलोकन करना, क्या दिखाना है यह चुनना और उसे व्यवस्थित करना स्वयं अधिगम है"],"explanationHi":"चार्ट बनाने की प्रक्रिया, जिसमें अवलोकन, निर्णय और व्यवस्था शामिल है, समझ का निर्माण करती है। लागत एक अतिरिक्त लाभ है; सटीकता की गारंटी नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1114","question":"Which use of flashcards in EVS is LEAST in line with NCF 2005?","options":["Sorting picture cards of animals into groups and explaining the groups","Flashing animal names again and again until children can repeat them","Using picture cards to tell a story about a journey","Arranging cards of a plant’s growth in sequence"],"answer":1,"explanation":"Rapid drilling of names is rote memorisation. The other uses ask children to classify, narrate or sequence.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"EVS में फ़्लैशकार्ड का कौन-सा उपयोग NCF 2005 के सबसे कम अनुरूप है?","optionsHi":["जंतुओं के चित्र-कार्डों को समूहों में छाँटना और समूहों को समझाना","जंतुओं के नाम बार-बार दिखाना जब तक बच्चे उन्हें दोहरा न सकें","यात्रा के बारे में कहानी सुनाने के लिए चित्र-कार्डों का उपयोग करना","पौधे की वृद्धि के कार्डों को क्रम में लगाना"],"explanationHi":"नामों का तेज़ अभ्यास रटंत स्मरण है। अन्य उपयोग बच्चों से वर्गीकरण, वर्णन या क्रमबद्धता करवाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1115","question":"Consider these statements about teaching materials for children with special needs in EVS: I. Materials should be adapted to the needs of each child. II. The same material works equally well for all children. III. Low-cost tactile materials can be made locally. Which are correct?","options":["I and III only","I and II only","II only","I, II and III"],"answer":0,"explanation":"Inclusive teaching adapts materials, and tactile materials need not be costly. Assuming one material suits all ignores differences, so II is wrong.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"EVS में विशेष आवश्यकता वाले बच्चों के लिए शिक्षण सामग्री के बारे में इन कथनों पर विचार कीजिए: I. सामग्री प्रत्येक बच्चे की आवश्यकताओं के अनुसार अनुकूलित होनी चाहिए। II. एक ही सामग्री सभी बच्चों के लिए समान रूप से कारगर होती है। III. कम लागत वाली स्पर्श-आधारित सामग्री स्थानीय रूप से बनाई जा सकती है। कौन-से सही हैं?","optionsHi":["केवल I और III","केवल I और II","केवल II","I, II और III"],"explanationHi":"समावेशी शिक्षण सामग्री को अनुकूलित करता है, और स्पर्श-आधारित सामग्री का महँगा होना आवश्यक नहीं। यह मान लेना कि एक सामग्री सबके लिए उपयुक्त है, भिन्नताओं की उपेक्षा करना है, इसलिए II गलत है।"},
  {"id":"cdp-pedagogy-subjects-1116","question":"Class 5 children are making a collection of leaves of trees around the school. Which instruction best combines learning with concern for the environment?","options":["Pluck one fresh leaf from every tree you see on the way to school","Bring as many leaves as possible; the biggest collection wins a prize","Collect fallen leaves, note each one’s tree, and press them in old newspaper","Buy printed pictures of leaves from the market and paste them neatly in a project file"],"answer":2,"explanation":"Using fallen leaves avoids harming trees while still allowing observation and recording. A competition for quantity encourages damage.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के बच्चे विद्यालय के आस-पास के पेड़ों की पत्तियों का संग्रह बना रहे हैं। कौन-सा निर्देश अधिगम को पर्यावरण के प्रति संवेदनशीलता के साथ सबसे अच्छी तरह जोड़ता है?","optionsHi":["विद्यालय के रास्ते में दिखने वाले हर पेड़ से एक ताज़ा पत्ती तोड़ो","जितनी अधिक पत्तियाँ हो सकें लाओ; सबसे बड़ा संग्रह पुरस्कार जीतेगा","गिरी हुई पत्तियाँ इकट्ठा करो, प्रत्येक के पेड़ को नोट करो, और उन्हें पुराने अख़बार में दबाओ","बाज़ार से पत्तियों के छपे चित्र खरीदो और उन्हें प्रोजेक्ट फ़ाइल में साफ़-सुथरे ढंग से चिपकाओ"],"explanationHi":"गिरी हुई पत्तियों का उपयोग पेड़ों को हानि पहुँचाए बिना अवलोकन और अभिलेखन की अनुमति देता है। संख्या की प्रतियोगिता नुकसान को प्रोत्साहित करती है।"},
  {"id":"cdp-pedagogy-subjects-1117","question":"While a teacher shows day and night with a globe and a torch, a Class 5 child asks, ‘Then why don’t people at the bottom fall off?’ The best response recognises that:","options":["the question is off-topic and should be left for a higher class","the child has misunderstood the globe and should look at it again","globes are misleading and should not be used for this topic","the model cannot show gravity, so its limits should be discussed"],"answer":3,"explanation":"Every model leaves things out; acknowledging the limits and taking up the child’s question turns a gap in the model into a learning opportunity.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"जब शिक्षक ग्लोब और टॉर्च से दिन और रात दिखा रहा है, तब कक्षा 5 का एक बच्चा पूछता है, 'तो नीचे के लोग गिर क्यों नहीं जाते?' सबसे अच्छी प्रतिक्रिया इस बात को पहचानती है कि:","optionsHi":["प्रश्न विषय से बाहर है और उसे ऊँची कक्षा के लिए छोड़ देना चाहिए","बच्चे ने ग्लोब को गलत समझा है और उसे फिर से देखना चाहिए","ग्लोब भ्रामक होते हैं और इस विषय के लिए उनका उपयोग नहीं करना चाहिए","मॉडल गुरुत्व नहीं दिखा सकता, इसलिए उसकी सीमाओं पर चर्चा की जानी चाहिए"],"explanationHi":"प्रत्येक मॉडल कुछ बातें छोड़ देता है; सीमाओं को स्वीकार करना और बच्चे के प्रश्न को लेना मॉडल की कमी को अधिगम के अवसर में बदल देता है।"},
  {"id":"cdp-pedagogy-subjects-1118","question":"A Class 5 teacher says, ‘The heart is like a pump.’ A child asks whether the heart has a motor and runs on electricity. This shows that:","options":["the child is being mischievous and should be asked to stay on topic","analogies help but have limits, which the teacher should discuss","analogies should never be used in EVS, as they always confuse","the child is not ready to learn about the heart until a later class"],"answer":1,"explanation":"Children may carry every feature of an analogy over to the real thing. Discussing its limits keeps the analogy useful without creating new misconceptions.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 5 की एक शिक्षिका कहती है, 'हृदय एक पंप जैसा है।' एक बच्चा पूछता है कि क्या हृदय में मोटर है और वह बिजली से चलता है। यह दर्शाता है कि:","optionsHi":["बच्चा शरारत कर रहा है और उसे विषय पर बने रहने को कहा जाना चाहिए","सादृश्य सहायक होते हैं पर उनकी सीमाएँ होती हैं, जिन पर शिक्षक को चर्चा करनी चाहिए","EVS में सादृश्यों का कभी उपयोग नहीं करना चाहिए, क्योंकि वे हमेशा भ्रमित करते हैं","बच्चा हृदय के बारे में सीखने के लिए तब तक तैयार नहीं है जब तक वह बाद की कक्षा में न पहुँचे"],"explanationHi":"बच्चे सादृश्य की हर विशेषता को वास्तविक वस्तु पर ले जा सकते हैं। उसकी सीमाओं पर चर्चा करने से सादृश्य उपयोगी बना रहता है और नई भ्रांतियाँ नहीं बनतीं।"},
  {"id":"cdp-pedagogy-subjects-1119","question":"A Class 5 teacher uses newspaper reports about floods in the region during the ‘Water’ theme. The most important caution is to:","options":["choose age-suitable content and discuss where the information comes from","use only national newspapers, since local papers are often less reliable on floods","avoid newspapers, because they are not textbooks approved for EVS","read the reports aloud in full without stopping for discussion"],"answer":0,"explanation":"Newspapers bring real, local issues into class but can carry disturbing images or errors; age-appropriateness and critical reading are the key cautions.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 5 की एक शिक्षिका 'जल' विषय के दौरान क्षेत्र में बाढ़ के बारे में अख़बार की रिपोर्टों का उपयोग करती है। सबसे महत्त्वपूर्ण सावधानी यह है कि:","optionsHi":["आयु-उपयुक्त सामग्री चुनी जाए और चर्चा की जाए कि जानकारी कहाँ से आती है","केवल राष्ट्रीय समाचार-पत्रों का उपयोग किया जाए, क्योंकि स्थानीय पत्र बाढ़ पर प्रायः कम विश्वसनीय होते हैं","अख़बारों से बचा जाए, क्योंकि वे EVS के लिए अनुमोदित पाठ्यपुस्तकें नहीं हैं","रिपोर्टों को चर्चा के लिए रुके बिना पूरा ज़ोर से पढ़ा जाए"],"explanationHi":"समाचार-पत्र वास्तविक, स्थानीय मुद्दों को कक्षा में लाते हैं, पर उनमें विचलित करने वाले चित्र या त्रुटियाँ हो सकती हैं; आयु-उपयुक्तता और आलोचनात्मक पठन मुख्य सावधानियाँ हैं।"},
  {"id":"cdp-pedagogy-subjects-1120","question":"Assertion (A): An EVS lesson without any teaching–learning material can never be effective. Reason (R): Children also learn through talk, questions and their own experiences. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"Discussion of children’s experiences can be very effective without material; so A is false while R is true, and R in fact argues against A.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): बिना किसी शिक्षण-अधिगम सामग्री के EVS का पाठ कभी प्रभावी नहीं हो सकता। कारण (R): बच्चे बातचीत, प्रश्नों और अपने अनुभवों से भी सीखते हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"बच्चों के अनुभवों पर चर्चा सामग्री के बिना भी बहुत प्रभावी हो सकती है; इसलिए A असत्य है जबकि R सत्य है, और R वास्तव में A के विरुद्ध तर्क देता है।"},
  {"id":"cdp-pedagogy-subjects-1121","question":"Class 5 children make a rain gauge from a cut plastic bottle and a ruler instead of using a bought one. The main benefit is that:","options":["a bought rain gauge is inaccurate for measuring local rainfall","bought instruments are not permitted in government primary schools for safety","it is cheap, and making it shows children how the measurement works","it can be thrown away after one use, so nothing needs storing"],"answer":2,"explanation":"Improvised apparatus is low-cost and transparent: children see why the reading means what it means. Bought instruments are not inaccurate or banned.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 5 के बच्चे खरीदे हुए वर्षामापी के बजाय कटी प्लास्टिक की बोतल और एक पैमाने से वर्षामापी बनाते हैं। मुख्य लाभ यह है कि:","optionsHi":["खरीदा हुआ वर्षामापी स्थानीय वर्षा मापने के लिए अशुद्ध होता है","सुरक्षा के कारण सरकारी प्राथमिक विद्यालयों में खरीदे हुए उपकरणों की अनुमति नहीं है","यह सस्ता है, और इसे बनाने से बच्चों को दिखता है कि माप कैसे काम करता है","इसे एक उपयोग के बाद फेंका जा सकता है, इसलिए कुछ रखने की आवश्यकता नहीं"],"explanationHi":"तात्कालिक उपकरण कम लागत वाले और पारदर्शी होते हैं: बच्चे देखते हैं कि पाठ्यांक का वह अर्थ क्यों है। खरीदे हुए उपकरण न अशुद्ध होते हैं, न प्रतिबंधित।"},
  {"id":"cdp-pedagogy-subjects-1122","question":"A Class 2 teacher performs a puppet show on cleanliness while children watch. How can she get the most learning from the puppets?","options":["Perform the same show every day so that children remember the message well","Let children make puppets and perform short scenes from their own lives","Use only ready-made puppets from the market, as they look more real","Ask children to write a summary of the show in their notebooks"],"answer":1,"explanation":"Children learn more by creating and performing than by watching. Repetition or written summaries keep them passive.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 2 की एक शिक्षिका स्वच्छता पर कठपुतली-प्रदर्शन करती है जबकि बच्चे देखते हैं। वह कठपुतलियों से अधिकतम अधिगम कैसे प्राप्त कर सकती है?","optionsHi":["वही प्रदर्शन हर दिन करना ताकि बच्चे संदेश को अच्छी तरह याद रखें","बच्चों को कठपुतलियाँ बनाने और अपने जीवन के छोटे दृश्य प्रस्तुत करने देना","केवल बाज़ार की तैयार कठपुतलियाँ उपयोग करना, क्योंकि वे अधिक वास्तविक दिखती हैं","बच्चों से अपनी कॉपियों में प्रदर्शन का सारांश लिखने को कहना"],"explanationHi":"बच्चे देखने की तुलना में रचने और प्रस्तुत करने से अधिक सीखते हैं। दोहराव या लिखित सारांश उन्हें निष्क्रिय बनाए रखते हैं।"},
  {"id":"cdp-pedagogy-subjects-1123","question":"Match each material with the purpose it serves best: 1. Real seeds 2. Map of the locality 3. Time-lapse video 4. Role-play props. a. Showing slow changes that cannot be seen within class time. b. First-hand observation of texture and germination. c. Understanding locations and routes. d. Taking on the viewpoints of different people.","options":["1-b, 2-c, 3-a, 4-d","1-a, 2-c, 3-b, 4-d","1-b, 2-d, 3-a, 4-c","1-c, 2-b, 3-a, 4-d"],"answer":0,"explanation":"Real seeds give direct observation, a map shows place and route, time-lapse shows slow change, and props support taking on roles.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"प्रत्येक सामग्री को उस उद्देश्य से मिलाइए जिसकी वह सबसे अच्छी पूर्ति करती है: 1. वास्तविक बीज 2. इलाके का मानचित्र 3. टाइम-लैप्स वीडियो 4. भूमिका-निर्वाह की सामग्री। a. धीमे परिवर्तन दिखाना जो कक्षा के समय में नहीं दिख सकते। b. बनावट और अंकुरण का प्रत्यक्ष अवलोकन। c. स्थानों और मार्गों को समझना। d. विभिन्न लोगों के दृष्टिकोण अपनाना।","optionsHi":["1-b, 2-c, 3-a, 4-d","1-a, 2-c, 3-b, 4-d","1-b, 2-d, 3-a, 4-c","1-c, 2-b, 3-a, 4-d"],"explanationHi":"वास्तविक बीज प्रत्यक्ष अवलोकन देते हैं, मानचित्र स्थान और मार्ग दिखाता है, टाइम-लैप्स धीमा परिवर्तन दिखाता है, और सामग्री भूमिकाएँ अपनाने में सहायक होती है।"},
  {"id":"cdp-pedagogy-subjects-1124","question":"A teacher teaches 46 + 27 first with base-ten blocks, then with drawings of sticks and dots, and finally with the written algorithm, which children write next to their drawings. Why should the drawings stay beside the written steps at this last stage?","options":["So that each written step, like the carried 1, links to the action it records","So that slow learners can copy the answer from the drawing whenever they get stuck","Because drawings are more accurate than written numbers for young children","Because the written algorithm should not be used on its own until Class 5"],"answer":0,"explanation":"In the concrete–pictorial–abstract sequence the bridge is the key: linking each symbol to the action it records gives the algorithm meaning. Without the link children learn the symbols as rote steps.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"एक शिक्षक 46 + 27 को पहले दहाई-इकाई ब्लॉकों से, फिर डंडियों और बिंदुओं के चित्रों से, और अंत में लिखित एल्गोरिदम से पढ़ाता है, जिसे बच्चे अपने चित्रों के बगल में लिखते हैं। इस अंतिम चरण में चित्र लिखित चरणों के बगल में क्यों रहने चाहिए?","optionsHi":["ताकि प्रत्येक लिखित चरण, जैसे हासिल का 1, उस क्रिया से जुड़े जिसे वह दर्ज करता है","ताकि धीमे सीखने वाले जब भी अटकें, चित्र से उत्तर नकल कर सकें","क्योंकि छोटे बच्चों के लिए चित्र लिखित संख्याओं से अधिक सटीक होते हैं","क्योंकि लिखित एल्गोरिदम का उपयोग कक्षा 5 तक अकेले नहीं किया जाना चाहिए"],"explanationHi":"मूर्त–चित्रात्मक–अमूर्त क्रम में सेतु ही मुख्य है: प्रत्येक प्रतीक को उस क्रिया से जोड़ना जिसे वह दर्ज करता है, एल्गोरिदम को अर्थ देता है। इस जुड़ाव के बिना बच्चे प्रतीकों को रटे हुए चरणों के रूप में सीखते हैं।"},
  {"id":"cdp-pedagogy-subjects-1125","question":"Children follow the teacher's instructions step by step with base-ten blocks and get correct answers, but cannot say why they exchanged ten ones for a ten. What does this show?","options":["Base-ten blocks are unsuitable for primary children and should be dropped","Blocks alone do not carry the idea; children must talk about what their actions mean","The children need much more time with the blocks before any talk about them","The teacher should switch to the written method at once, since the blocks have failed"],"answer":1,"explanation":"Materials used mechanically become another rote procedure. Understanding comes when children think and talk about why they act, for example why ten ones can be swapped for one ten.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"बच्चे दहाई-इकाई ब्लॉकों के साथ शिक्षक के निर्देशों का चरण-दर-चरण पालन करते हैं और सही उत्तर पाते हैं, पर यह नहीं बता पाते कि उन्होंने दस इकाइयों को एक दहाई से क्यों बदला। यह क्या दर्शाता है?","optionsHi":["दहाई-इकाई ब्लॉक प्राथमिक बच्चों के लिए अनुपयुक्त हैं और उन्हें छोड़ देना चाहिए","केवल ब्लॉक विचार को नहीं ले जाते; बच्चों को इस पर बात करनी चाहिए कि उनकी क्रियाओं का क्या अर्थ है","बच्चों को उनके बारे में किसी भी बात से पहले ब्लॉकों के साथ बहुत अधिक समय चाहिए","शिक्षक को तुरंत लिखित विधि पर आ जाना चाहिए, क्योंकि ब्लॉक विफल हो चुके हैं"],"explanationHi":"यांत्रिक रूप से उपयोग की गई सामग्री एक और रटी हुई प्रक्रिया बन जाती है। समझ तब आती है जब बच्चे इस पर सोचते और बात करते हैं कि वे क्यों कार्य करते हैं, उदाहरण के लिए दस इकाइयों को एक दहाई से क्यों बदला जा सकता है।"},
  {"id":"cdp-pedagogy-subjects-1126","question":"A Class 3 child still counts out counters for 7 + 8. Which approach is most suitable?","options":["Take the counters away at once so that she is forced to work out sums mentally from now on","Let her keep using counters for every addition fact, however long it takes, until Class 5","Keep counters but teach derived facts from doubles, so she needs them less","Give her a list of addition facts to memorise at home, with a test every Monday"],"answer":2,"explanation":"Materials should be faded gradually as children develop mental strategies. Removing them suddenly causes anxiety, while relying on them for ever holds the child back; derived facts from doubles are the bridge.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की एक बच्ची 7 + 8 के लिए अब भी गिनतियाँ गिनकर निकालती है। कौन-सा उपागम सबसे उपयुक्त है?","optionsHi":["गिनतियाँ तुरंत हटा लेना ताकि वह अब से योग मन में निकालने को विवश हो","उसे हर योग-तथ्य के लिए गिनतियों का उपयोग करने देना, चाहे कितना भी समय लगे, कक्षा 5 तक","गिनतियाँ रखना पर दुगुने से व्युत्पन्न तथ्य सिखाना, ताकि उसे उनकी कम आवश्यकता पड़े","उसे घर पर याद करने के लिए योग-तथ्यों की सूची देना, हर सोमवार को परीक्षा के साथ"],"explanationHi":"बच्चों में मानसिक युक्तियाँ विकसित होने पर सामग्री को धीरे-धीरे हटाया जाना चाहिए। अचानक हटाना चिंता पैदा करता है, जबकि हमेशा उन पर निर्भर रहना बच्चे को पीछे रखता है; दुगुनों से व्युत्पन्न तथ्य सेतु हैं।"},
  {"id":"cdp-pedagogy-subjects-1127","question":"To build the concept of a parallelogram, a teacher shows many parallelograms that differ in side lengths, angle sizes and position on the page. Which of Dienes's principles is she applying?","options":["Perceptual variability (multiple embodiment)","Dynamic principle","Constructivity principle","Mathematical variability"],"answer":3,"explanation":"Mathematical variability means varying the features that are not essential to the concept (side lengths, angles) while keeping the essential ones (two pairs of parallel sides). Perceptual variability means using different materials for the same concept.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"समांतर चतुर्भुज की संकल्पना बनाने के लिए एक शिक्षिका भुजाओं की लंबाई, कोणों के माप और पृष्ठ पर स्थिति में भिन्न अनेक समांतर चतुर्भुज दिखाती है। वह डीन्स के किस सिद्धांत को लागू कर रही है?","optionsHi":["प्रत्यक्षण-विविधता (बहु-मूर्तन) का सिद्धांत","गत्यात्मक सिद्धांत","रचनात्मकता का सिद्धांत","गणितीय विविधता"],"explanationHi":"गणितीय विविधता का अर्थ है संकल्पना के लिए अनावश्यक विशेषताओं (भुजाओं की लंबाई, कोण) को बदलना और आवश्यक विशेषताओं (समांतर भुजाओं के दो युग्म) को स्थिर रखना। प्रत्यक्षण-विविधता का अर्थ है एक ही संकल्पना के लिए अलग-अलग सामग्री का उपयोग।"},
  {"id":"cdp-pedagogy-subjects-1128","question":"A teacher in a government school with very few materials wants to use hands-on activities in maths. Which approach best reflects good practice?","options":["Use low-cost local items like seeds, bottle caps and sticks for clear maths purposes","Wait until the school buys commercial maths kits, since home-made aids give inaccurate ideas","Use only the textbook and blackboard, since real activities always need expensive aids","Ask each child to buy a set of base-ten blocks so that every child can handle them"],"answer":0,"explanation":"A teaching aid's value lies in how purposefully it is used, not in its cost. NCERT and NCF 2005 encourage locally available, low-cost materials.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"बहुत कम सामग्री वाले एक सरकारी विद्यालय का शिक्षक गणित में हाथ से करने वाली गतिविधियों का उपयोग करना चाहता है। कौन-सा उपागम अच्छे अभ्यास को सबसे अच्छी तरह दर्शाता है?","optionsHi":["स्पष्ट गणितीय उद्देश्यों के लिए बीज, बोतल के ढक्कन और डंडियों जैसी कम लागत वाली स्थानीय वस्तुओं का उपयोग करना","विद्यालय के व्यावसायिक गणित-किट खरीदने तक प्रतीक्षा करना, क्योंकि घर के बने साधन गलत धारणाएँ देते हैं","केवल पाठ्यपुस्तक और श्यामपट्ट का उपयोग करना, क्योंकि वास्तविक गतिविधियों के लिए हमेशा महँगे साधन चाहिए","प्रत्येक बच्चे से दहाई-इकाई ब्लॉकों का एक सेट खरीदने को कहना ताकि हर बच्चा उन्हें सँभाल सके"],"explanationHi":"शिक्षण-साधन का मूल्य इसमें है कि उसका कितने उद्देश्यपूर्ण ढंग से उपयोग हुआ, उसकी लागत में नहीं। NCERT और NCF 2005 स्थानीय रूप से उपलब्ध, कम लागत वाली सामग्री को प्रोत्साहित करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1129","question":"To compare 2/3 and 3/5, which material most directly supports the reasoning?","options":["Two paper circles of different sizes, one cut into thirds and the other cut into fifths","Equal-length fraction strips cut into thirds and fifths, placed one below the other","Counters arranged in two separate piles of 2 and 3, to compare the numerators","A clock face showing 2 o'clock and 3 o'clock to compare parts of an hour"],"answer":1,"explanation":"Comparing fractions needs the same whole; equal-length strips lined up show that 2/3 reaches further than 3/5. Circles of different sizes break the equal-whole condition.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"2/3 और 3/5 की तुलना करने के लिए कौन-सी सामग्री तर्क का सबसे सीधे समर्थन करती है?","optionsHi":["अलग-अलग आकार के दो कागज़ी वृत्त, एक तिहाई में और दूसरा पाँचवें भागों में कटा हुआ","तिहाई और पाँचवें भागों में कटी समान लंबाई की भिन्न-पट्टियाँ, एक के नीचे दूसरी रखी हुई","अंशों की तुलना के लिए 2 और 3 की अलग-अलग ढेरियों में रखी गिनतियाँ","घंटे के भागों की तुलना के लिए 2 बजे और 3 बजे दिखाता घड़ी का चेहरा"],"explanationHi":"भिन्नों की तुलना के लिए समान पूर्ण चाहिए; समान लंबाई की पट्टियाँ पास-पास रखने पर दिखाती हैं कि 2/3, 3/5 से आगे तक पहुँचता है। अलग आकार के वृत्त समान पूर्ण की शर्त तोड़ देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1130","question":"A Class 7 student solves problems well at home but goes blank in timed maths tests. What is the best response from the teacher?","options":["Give her many more timed tests so that she slowly gets used to the pressure of exams","Tell her parents that she is not putting in enough effort to prepare for tests","See it as maths anxiety and use untimed, low-stakes checks of her reasoning","Move her to an easier section of the class, where tests are shorter and simpler"],"answer":2,"explanation":"Anxiety takes up the working memory needed for problem solving, so performance drops under pressure. Low-stakes, untimed assessment and attention to process help her show and build what she knows.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक विद्यार्थी घर पर प्रश्न अच्छी तरह हल करती है पर समयबद्ध गणित परीक्षाओं में उसे कुछ नहीं सूझता। शिक्षक की सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["उसे बहुत अधिक समयबद्ध परीक्षाएँ देना ताकि वह धीरे-धीरे परीक्षा के दबाव की आदी हो जाए","उसके अभिभावकों को बताना कि वह परीक्षाओं की तैयारी में पर्याप्त प्रयास नहीं कर रही","इसे गणित-चिंता मानना और उसके तर्क की बिना समय-सीमा वाली, कम दाँव वाली जाँच करना","उसे कक्षा के आसान अनुभाग में भेज देना, जहाँ परीक्षाएँ छोटी और सरल होती हैं"],"explanationHi":"चिंता कार्यकारी स्मृति को घेर लेती है जो समस्या-समाधान के लिए आवश्यक है, इसलिए दबाव में प्रदर्शन गिरता है। कम दाँव वाला, बिना समय-सीमा का आकलन और प्रक्रिया पर ध्यान उसे अपना ज्ञान दिखाने और बनाने में मदद करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1131","question":"Which statement about a teacher's own attitude to mathematics is best supported?","options":["A teacher's attitude has no effect on children as long as the syllabus is covered","Only the textbook shapes children's attitude to mathematics, not the teacher","Teachers who dislike maths are always stricter, which improves children's results","An anxious teacher can pass on the idea that maths ability is a fixed talent"],"answer":3,"explanation":"Children pick up the beliefs and feelings their teachers show. An anxious teacher may avoid discussion and signal that maths is for the gifted, which increases children's anxiety.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"गणित के प्रति शिक्षक के अपने दृष्टिकोण के बारे में कौन-सा कथन सबसे अच्छी तरह समर्थित है?","optionsHi":["शिक्षक के दृष्टिकोण का बच्चों पर कोई प्रभाव नहीं पड़ता जब तक पाठ्यक्रम पूरा हो जाए","गणित के प्रति बच्चों के दृष्टिकोण को केवल पाठ्यपुस्तक आकार देती है, शिक्षक नहीं","जो शिक्षक गणित को नापसंद करते हैं वे हमेशा अधिक सख़्त होते हैं, जिससे बच्चों के परिणाम सुधरते हैं","चिंतित शिक्षक यह विचार दे सकता है कि गणित की योग्यता एक स्थिर प्रतिभा है"],"explanationHi":"बच्चे अपने शिक्षकों की दिखाई हुई मान्यताएँ और भावनाएँ ग्रहण करते हैं। चिंतित शिक्षक चर्चा से बच सकता है और संकेत दे सकता है कि गणित प्रतिभाशालियों के लिए है, जिससे बच्चों की चिंता बढ़ती है।"},
  {"id":"cdp-pedagogy-subjects-1132","question":"Which feedback is most likely to build a growth mindset in a child who has just solved a hard problem?","options":["‘When the first method failed, you tried another. That is how problems get solved.’","‘You are so clever; maths just comes naturally to you, as it does to all toppers.’","‘Well done, you are easily the best in the class and nobody else could have solved it.’","‘Good, but your friend did it faster, so try to beat her time on the next one.’"],"answer":0,"explanation":"Praising effort and strategy tells the child that ability grows with work. Praising fixed cleverness or comparing with others makes children afraid of failing later.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"जिस बच्चे ने अभी एक कठिन प्रश्न हल किया है, उसमें विकासोन्मुख मानसिकता (growth mindset) बनाने की सबसे अधिक संभावना कौन-सी प्रतिपुष्टि रखती है?","optionsHi":["‘जब पहली विधि विफल हुई, तुमने दूसरी आज़माई। इसी तरह प्रश्न हल होते हैं।’","‘तुम कितने होशियार हो; गणित तुम्हारे लिए स्वाभाविक है, जैसे सभी टॉपरों के लिए।’","‘शाबाश, तुम निश्चित रूप से कक्षा में सबसे अच्छे हो और कोई और इसे हल नहीं कर सकता था।’","‘अच्छा, पर तुम्हारी सहेली ने इसे तेज़ किया, इसलिए अगले में उसका समय हराने की कोशिश करो।’"],"explanationHi":"प्रयास और युक्ति की प्रशंसा बच्चे को बताती है कि योग्यता परिश्रम से बढ़ती है। स्थिर बुद्धिमत्ता की प्रशंसा या दूसरों से तुलना बच्चों को बाद में विफलता से भयभीत बनाती है।"},
  {"id":"cdp-pedagogy-subjects-1133","question":"A student's mistake on the blackboard makes the class laugh. What is the best response from the teacher?","options":["Ask the student to sit down and call someone who knows the correct method","Say, ‘Let's see what she was thinking. Which part of her method is right?’","Ignore the mistake, quietly write the correct answer and continue the lesson","Warn the class not to laugh and move on quickly to the next question"],"answer":1,"explanation":"Treating errors as information for learning protects the child and helps the whole class understand. Public embarrassment is a known cause of maths anxiety.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"श्यामपट्ट पर एक विद्यार्थी की गलती से कक्षा हँस पड़ती है। शिक्षक की सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["विद्यार्थी को बैठने को कहना और सही विधि जानने वाले किसी को बुलाना","कहना, 'देखते हैं कि यह क्या सोच रही थी। इसकी विधि का कौन-सा भाग सही है?'","गलती की उपेक्षा करना, चुपचाप सही उत्तर लिख देना और पाठ जारी रखना","कक्षा को हँसने से चेतावनी देना और जल्दी से अगले प्रश्न पर बढ़ जाना"],"explanationHi":"त्रुटियों को अधिगम की जानकारी के रूप में लेना बच्चे की रक्षा करता है और पूरी कक्षा को समझने में मदद करता है। सार्वजनिक शर्मिंदगी गणित-चिंता का ज्ञात कारण है।"},
  {"id":"cdp-pedagogy-subjects-1134","question":"A teacher remarks, ‘Girls are good at neat work; boys are better at maths.’ What does this most likely lead to?","options":["Better results for girls, who will try harder to prove the teacher wrong","No effect, since children ignore such remarks made in passing by teachers","Lower confidence and participation in maths among girls over time","More interest in maths among both boys and girls, since it sparks competition"],"answer":2,"explanation":"Stereotypes shape children's beliefs about who can do maths. NCF 2005 calls for gender-fair classrooms in which all children get the same opportunities and expectations.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"एक शिक्षक टिप्पणी करता है, 'लड़कियाँ साफ़-सुथरे काम में अच्छी होती हैं; लड़के गणित में बेहतर होते हैं।' इसका सबसे अधिक संभावित परिणाम क्या होगा?","optionsHi":["लड़कियों के बेहतर परिणाम, जो शिक्षक को गलत सिद्ध करने के लिए अधिक प्रयास करेंगी","कोई प्रभाव नहीं, क्योंकि बच्चे शिक्षकों की ऐसी चलते-चलते कही गई टिप्पणियों की उपेक्षा करते हैं","समय के साथ लड़कियों में गणित के प्रति आत्मविश्वास और भागीदारी में कमी","लड़कों और लड़कियों दोनों में गणित के प्रति अधिक रुचि, क्योंकि इससे प्रतिस्पर्धा जगती है"],"explanationHi":"रूढ़ियाँ बच्चों की इस धारणा को आकार देती हैं कि कौन गणित कर सकता है। NCF 2005 लैंगिक-निष्पक्ष कक्षाओं का आह्वान करती है, जिनमें सभी बच्चों को समान अवसर और अपेक्षाएँ मिलें।"},
  {"id":"cdp-pedagogy-subjects-1135","question":"Assertion (A): Timed drills of number facts can increase anxiety in some children. Reason (R): Fluency with number facts has no importance in mathematics.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Time pressure can raise anxiety, so A is true. But fluency with facts does matter; it frees working memory for problem solving and is better built through games and strategies. R is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"अभिकथन (A): संख्या-तथ्यों के समयबद्ध अभ्यास कुछ बच्चों में चिंता बढ़ा सकते हैं। कारण (R): गणित में संख्या-तथ्यों में प्रवाह का कोई महत्त्व नहीं है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"समय का दबाव चिंता बढ़ा सकता है, इसलिए A सत्य है। पर तथ्यों में प्रवाह मायने रखता है; वह समस्या-समाधान के लिए कार्यकारी स्मृति को मुक्त करता है और खेलों तथा युक्तियों से बेहतर बनता है। R असत्य है।"},
  {"id":"cdp-pedagogy-subjects-1136","question":"A teacher writes multiple-choice items in which each wrong option matches a known misconception, for example choosing ‘0.25’ as larger than ‘0.5’. What is the main use of such items?","options":["Ranking children by their total marks to decide who goes into the top section","Making the test harder for bright students by adding tempting wrong options","Saving time in checking copies, since every item has a single fixed answer","Finding which misconception each child holds so re-teaching can target it"],"answer":3,"explanation":"Options built from real errors make the test diagnostic: a child's choice shows what she thinks, not just that she is wrong, so the teacher knows what to re-teach.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षक ऐसे बहुविकल्पीय प्रश्न लिखता है जिनमें प्रत्येक गलत विकल्प किसी ज्ञात भ्रांति से मेल खाता है, जैसे ‘0.25’ को ‘0.5’ से बड़ा चुनना। ऐसे प्रश्नों का मुख्य उपयोग क्या है?","optionsHi":["बच्चों को उनके कुल अंकों के आधार पर क्रमित करना ताकि तय हो कि कौन शीर्ष अनुभाग में जाएगा","आकर्षक गलत विकल्प जोड़कर प्रतिभाशाली विद्यार्थियों के लिए परीक्षा कठिन बनाना","कॉपियाँ जाँचने में समय बचाना, क्योंकि प्रत्येक प्रश्न का एक निश्चित उत्तर होता है","यह पता लगाना कि प्रत्येक बच्चे में कौन-सी भ्रांति है ताकि पुनः शिक्षण लक्षित हो सके"],"explanationHi":"वास्तविक त्रुटियों से बने विकल्प परीक्षा को निदानात्मक बनाते हैं: बच्चे का चुनाव दिखाता है कि वह क्या सोचती है, केवल यह नहीं कि वह गलत है, ताकि शिक्षक जान सके कि क्या दोबारा पढ़ाना है।"},
  {"id":"cdp-pedagogy-subjects-1137","question":"Which evidence tells a teacher the most about a child's understanding of subtraction with regrouping?","options":["The child uses base-ten blocks to explain why 52 − 27 needs a ten broken up","The child's total marks in the unit test on subtraction with regrouping","Whether the child finished the subtraction worksheet before everyone else","The parents' report that all subtraction homework was done correctly at home"],"answer":0,"explanation":"An explanation with materials shows the reasoning behind the procedure. Marks, speed and parental reports show results or effort, not understanding.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कौन-सा साक्ष्य शिक्षक को पुनर्समूहन सहित घटाव की बच्चे की समझ के बारे में सबसे अधिक बताता है?","optionsHi":["बच्चा दहाई-इकाई ब्लॉकों से समझाता है कि 52 − 27 में एक दहाई को क्यों तोड़ना पड़ता है","पुनर्समूहन सहित घटाव पर इकाई परीक्षा में बच्चे के कुल अंक","क्या बच्चे ने घटाव का कार्य-पत्र सबसे पहले पूरा किया","अभिभावकों की रिपोर्ट कि घटाव का सारा गृहकार्य घर पर सही किया गया"],"explanationHi":"सामग्री के साथ दिया गया स्पष्टीकरण प्रक्रिया के पीछे का तर्क दिखाता है। अंक, गति और अभिभावकों की रिपोर्टें परिणाम या प्रयास दिखाती हैं, समझ नहीं।"},
  {"id":"cdp-pedagogy-subjects-1138","question":"A Class 5 teacher keeps a portfolio for each child with drafts, solved problems, mistakes later corrected, and short reflections. What is its main value?","options":["It reduces the number of tests the teacher must set for the report card","It shows the child's growth in understanding over time","It is mainly for showing parents the neatest work their child has done","It replaces the need for any classroom observation of how children work"],"answer":1,"explanation":"A portfolio collects evidence of learning across time, including revisions and reflection, which a single test cannot show. It supports both the teacher's and the child's view of progress.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक शिक्षिका प्रत्येक बच्चे के लिए पोर्टफोलियो रखती है जिसमें मसौदे, हल किए गए प्रश्न, बाद में सुधारी गई गलतियाँ और संक्षिप्त चिंतन हैं। इसका मुख्य मूल्य क्या है?","optionsHi":["यह रिपोर्ट कार्ड के लिए शिक्षिका को जो परीक्षाएँ बनानी पड़ती हैं, उनकी संख्या घटाता है","यह समय के साथ बच्चे की समझ में विकास दिखाता है","यह मुख्यतः अभिभावकों को उनके बच्चे का सबसे साफ़-सुथरा कार्य दिखाने के लिए है","यह बच्चे कैसे कार्य करते हैं, इसके कक्षा-अवलोकन की किसी भी आवश्यकता को समाप्त कर देता है"],"explanationHi":"पोर्टफोलियो समय के दौरान अधिगम का साक्ष्य एकत्र करता है, संशोधनों और चिंतन सहित, जो एक परीक्षा नहीं दिखा सकती। यह प्रगति के बारे में शिक्षक और बच्चे दोनों के दृष्टिकोण का समर्थन करता है।"},
  {"id":"cdp-pedagogy-subjects-1139","question":"For an open-ended maths problem, a teacher uses a rubric with criteria such as understanding of the problem, choice of strategy, explanation and accuracy. Why is this better than marking only the final answer?","options":["It allows the teacher to give everyone full marks just for attempting the problem","It is quicker to use than checking each final answer in a large class of forty","It credits different valid approaches and gives specific feedback on each part","It removes the need for children to reach an answer, as only the method counts"],"answer":2,"explanation":"Open-ended problems have many valid routes. A rubric values reasoning and communication as well as accuracy and tells the child what to improve; it does not ignore the answer.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"किसी खुले गणित-प्रश्न के लिए शिक्षक रूब्रिक का उपयोग करता है जिसमें समस्या की समझ, युक्ति का चयन, स्पष्टीकरण और शुद्धता जैसे मानदंड हैं। केवल अंतिम उत्तर पर अंक देने की तुलना में यह बेहतर क्यों है?","optionsHi":["यह शिक्षक को केवल प्रश्न का प्रयास करने पर सभी को पूरे अंक देने की अनुमति देता है","चालीस की बड़ी कक्षा में प्रत्येक अंतिम उत्तर जाँचने की तुलना में इसका उपयोग तेज़ है","यह विभिन्न वैध उपागमों को श्रेय देता है और प्रत्येक भाग पर विशिष्ट प्रतिपुष्टि देता है","यह बच्चों के उत्तर तक पहुँचने की आवश्यकता को समाप्त करता है, क्योंकि केवल विधि मायने रखती है"],"explanationHi":"खुले प्रश्नों के कई वैध मार्ग होते हैं। रूब्रिक तर्क और संप्रेषण को शुद्धता के साथ महत्त्व देता है और बच्चे को बताता है कि क्या सुधारना है; यह उत्तर की उपेक्षा नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-1140","question":"Two children each score 7 out of 10 on a fractions test. All of Arun's errors are copying slips; all of Bina's come from believing that a bigger denominator means a bigger fraction. What should the teacher conclude?","options":["Both need exactly the same revision work, since their scores on the test are equal","Arun needs more help than Bina, since careless slips are harder to fix than ideas","Both should repeat the whole chapter on fractions from the beginning with the class","Equal scores hide different needs: Bina needs re-teaching, Arun needs to check work"],"answer":3,"explanation":"A total score hides what lies behind it. Error analysis shows that Bina holds a misconception that will affect later work, while Arun's understanding is sound.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"दो बच्चे भिन्न की परीक्षा में 10 में से 7 अंक पाते हैं। अरुण की सभी त्रुटियाँ नकल करने की चूकें हैं; बीना की सभी त्रुटियाँ इस विश्वास से आती हैं कि बड़ा हर (denominator) बड़ी भिन्न बनाता है। शिक्षक को क्या निष्कर्ष निकालना चाहिए?","optionsHi":["दोनों को ठीक एक जैसे पुनरावृत्ति-कार्य की आवश्यकता है, क्योंकि परीक्षा में उनके अंक बराबर हैं","अरुण को बीना से अधिक सहायता की आवश्यकता है, क्योंकि असावधानी की चूकें विचारों से अधिक कठिनाई से ठीक होती हैं","दोनों को कक्षा के साथ भिन्न का पूरा अध्याय आरंभ से दोहराना चाहिए","समान अंक अलग-अलग आवश्यकताओं को छिपाते हैं: बीना को पुनः शिक्षण चाहिए, अरुण को अपना कार्य जाँचना चाहिए"],"explanationHi":"कुल अंक उसके पीछे की बात छिपा देते हैं। त्रुटि-विश्लेषण दिखाता है कि बीना में एक भ्रांति है जो आगे के कार्य को प्रभावित करेगी, जबकि अरुण की समझ ठोस है।"},
  {"id":"cdp-pedagogy-subjects-1141","question":"Children swap their solutions and write ‘two stars and a wish’, two things done well and one thing to improve, on a partner's work. What is the main purpose?","options":["To learn to judge work against criteria and to learn from other methods","To reduce the teacher's work of checking every child's notebook after class","To find out who is the best in the class by comparing the stars received","To give marks for the report card based on what partners write"],"answer":0,"explanation":"Peer assessment helps children understand what good work looks like and to see other strategies, so they become better at checking their own work.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"बच्चे अपने हल आपस में बदलते हैं और साथी के कार्य पर ‘दो सितारे और एक इच्छा’ लिखते हैं, यानी अच्छी तरह किए गए दो कार्य और सुधार की एक बात। इसका मुख्य उद्देश्य क्या है?","optionsHi":["कार्य को मानदंडों के विरुद्ध आँकना सीखना और दूसरी विधियों से सीखना","कक्षा के बाद शिक्षक के हर बच्चे की कॉपी जाँचने के कार्य को घटाना","मिले सितारों की तुलना करके पता लगाना कि कक्षा में सबसे अच्छा कौन है","साथियों के लिखे के आधार पर रिपोर्ट कार्ड के लिए अंक देना"],"explanationHi":"सहपाठी आकलन बच्चों को समझने में मदद करता है कि अच्छा कार्य कैसा दिखता है और दूसरी युक्तियाँ देखने में, जिससे वे अपना कार्य जाँचने में बेहतर बनते हैं।"},
  {"id":"cdp-pedagogy-subjects-1142","question":"A child writes 3/4 + 1/2 = 4/6. Which written feedback best supports learning?","options":["‘Wrong. Fractions cannot be added like this. See me after class with your notebook.’","‘You added tops and bottoms. Shade 3/4 and then 1/2 of one strip. How much is shaded?’","‘Good try! Keep practising fraction sums and you will surely get them right next time.’","‘0/1. Revise the chapter on fractions and redo all the exercise questions at home.’"],"answer":1,"explanation":"Useful feedback names the error and gives a next step the child can act on; shading shows the answer is 5/4. ‘Good try’ or a grade alone tells the child nothing about what to change.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"एक बच्चा लिखता है 3/4 + 1/2 = 4/6। कौन-सी लिखित प्रतिपुष्टि अधिगम का सबसे अच्छा समर्थन करती है?","optionsHi":["‘गलत। भिन्नों को ऐसे नहीं जोड़ा जा सकता। कक्षा के बाद अपनी कॉपी के साथ मुझसे मिलो।’","‘तुमने ऊपर वालों और नीचे वालों को जोड़ दिया। एक पट्टी के 3/4 और फिर 1/2 पर छाया करो। कितना छायांकित है?’","‘अच्छा प्रयास! भिन्न के योग का अभ्यास करते रहो, अगली बार ज़रूर सही होगा।’","‘0/1। भिन्न का अध्याय दोहराओ और घर पर अभ्यास के सारे प्रश्न फिर से करो।’"],"explanationHi":"उपयोगी प्रतिपुष्टि त्रुटि का नाम बताती है और ऐसा अगला कदम देती है जिस पर बच्चा अमल कर सके; छायांकन दिखाता है कि उत्तर 5/4 है। ‘अच्छा प्रयास’ या केवल ग्रेड बच्चे को यह नहीं बताता कि क्या बदलना है।"},
  {"id":"cdp-pedagogy-subjects-1143","question":"Which statement about assessment reflects NEP 2020?","options":["Assessment should mainly test how much of the prescribed textbook a student remembers","Board examinations should be removed altogether and replaced by school-based tests","Assessment should test competencies such as analysis rather than rote memory","Assessment should be done only at the end of the year, to reduce pressure on students"],"answer":2,"explanation":"NEP 2020 calls for regular, formative, competency-based assessment that tests higher-order skills. It keeps board exams but wants them to test core understanding rather than memorisation.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"आकलन के बारे में कौन-सा कथन NEP 2020 को दर्शाता है?","optionsHi":["आकलन को मुख्यतः यह जाँचना चाहिए कि विद्यार्थी को निर्धारित पाठ्यपुस्तक का कितना याद है","बोर्ड परीक्षाएँ पूरी तरह हटाकर विद्यालय-आधारित परीक्षणों से बदल दी जानी चाहिए","आकलन को रटंत स्मृति के बजाय विश्लेषण जैसी योग्यताओं की जाँच करनी चाहिए","विद्यार्थियों पर दबाव घटाने के लिए आकलन केवल वर्ष के अंत में किया जाना चाहिए"],"explanationHi":"NEP 2020 नियमित, रचनात्मक, योग्यता-आधारित आकलन का आह्वान करती है जो उच्च-स्तरीय कौशलों की जाँच करे। यह बोर्ड परीक्षाएँ बनाए रखती है पर चाहती है कि वे रटने के बजाय मूल समझ की जाँच करें।"},
  {"id":"cdp-pedagogy-subjects-1144","question":"A teacher sits with one child, gives her a task, and keeps asking ‘How did you do that?’ and ‘What if…?’ without correcting her. What is the main purpose of this one-to-one interview?","options":["To teach the correct method privately, away from the rest of the class","To test how quickly the child can solve the task without any help","To give the child a mark in private so that she is not embarrassed in class","To find out how the child thinks and the strategies behind her answers"],"answer":3,"explanation":"A task-based (clinical) interview is diagnostic: by probing without correcting, the teacher learns the child's reasoning, which written answers alone often hide.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षिका एक बच्ची के साथ बैठती है, उसे कार्य देती है, और उसे सुधारे बिना बार-बार पूछती रहती है 'तुमने यह कैसे किया?' और 'अगर… तो?' इस एक-से-एक साक्षात्कार का मुख्य उद्देश्य क्या है?","optionsHi":["शेष कक्षा से दूर, निजी तौर पर सही विधि सिखाना","यह जाँचना कि बच्ची बिना किसी सहायता के कार्य को कितनी जल्दी हल कर सकती है","बच्ची को निजी तौर पर अंक देना ताकि वह कक्षा में शर्मिंदा न हो","यह पता लगाना कि बच्ची कैसे सोचती है और उसके उत्तरों के पीछे कौन-सी युक्तियाँ हैं"],"explanationHi":"कार्य-आधारित (नैदानिक) साक्षात्कार निदानात्मक होता है: सुधारे बिना गहराई से पूछने पर शिक्षिका बच्ची का तर्क जान जाती है, जिसे लिखित उत्तर प्रायः छिपा देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1145","question":"Which question best tests a Class 4 child's understanding of place value rather than recall?","options":["Make the largest and smallest 4-digit numbers using 3, 0, 8 and 5 once; explain why","In the number 4,732, write the place value and the face value of the digit 7","Write the number 4,732 in words, and then write it again in its expanded form","Write the numbers that come just before and just after 4,732, and the number ten more"],"answer":0,"explanation":"The task needs reasoning about how a digit's position changes its value, including where 0 can go (the smallest is 3,058, not 0,358). The other questions can be answered by routine.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कौन-सा प्रश्न कक्षा 4 के बच्चे की स्थानमान की समझ को स्मरण के बजाय सबसे अच्छी तरह जाँचता है?","optionsHi":["4 अंकों की सबसे बड़ी और सबसे छोटी संख्याएँ बनाइए, जिनमें 3, 0, 8 और 5 प्रत्येक अंक एक-एक बार आए; कारण समझाइए","संख्या 4,732 में अंक 7 का स्थानीय मान और अंकित मान (face value) लिखिए","संख्या 4,732 को शब्दों में लिखिए, और फिर उसे विस्तारित रूप में दोबारा लिखिए","4,732 से ठीक पहले और ठीक बाद की संख्याएँ, और दस अधिक वाली संख्या लिखिए"],"explanationHi":"इस कार्य के लिए इस पर तर्क करना पड़ता है कि अंक की स्थिति उसका मान कैसे बदलती है, जिसमें यह भी शामिल है कि 0 कहाँ आ सकता है (सबसे छोटी 3,058 है, 0,358 नहीं)। अन्य प्रश्नों का उत्तर नियमित प्रक्रिया से दिया जा सकता है।"},
  {"id":"cdp-pedagogy-subjects-1146","question":"A Class 4 maths test for a village school has many word problems about metro cards and shopping malls. What is the main concern?","options":["The numbers used in such problems are too large for Class 4 children","Unfamiliar contexts test background knowledge as much as maths skill","Word problems should not be used in Class 4, as reading is still weak","The questions should be in English only, to match city schools' papers"],"answer":1,"explanation":"Children may fail because the situation is strange to them, not because they lack the maths. Fair assessment uses contexts from children's lives, as NCF 2005 recommends.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"एक ग्रामीण विद्यालय के लिए कक्षा 4 की गणित-परीक्षा में मेट्रो कार्ड और शॉपिंग मॉल के बारे में कई शाब्दिक प्रश्न हैं। मुख्य चिंता क्या है?","optionsHi":["ऐसे प्रश्नों में प्रयुक्त संख्याएँ कक्षा 4 के बच्चों के लिए बहुत बड़ी हैं","अपरिचित संदर्भ गणित-कौशल की उतनी ही जाँच करते हैं जितनी पृष्ठभूमि-ज्ञान की","कक्षा 4 में शाब्दिक प्रश्नों का उपयोग नहीं होना चाहिए, क्योंकि पठन अभी कमज़ोर है","प्रश्न केवल अंग्रेज़ी में होने चाहिए, ताकि शहरी विद्यालयों के प्रश्न-पत्रों से मेल खाएँ"],"explanationHi":"बच्चे इसलिए विफल हो सकते हैं कि परिस्थिति उनके लिए अजीब है, इसलिए नहीं कि उनमें गणित की कमी है। निष्पक्ष आकलन बच्चों के जीवन के संदर्भों का उपयोग करता है, जैसा NCF 2005 अनुशंसा करती है।"},
  {"id":"cdp-pedagogy-subjects-1147","question":"A diagnostic test shows that six children cannot regroup in subtraction. The teacher works with them in a small group using base-ten blocks while the others do extension problems. This is best described as:","options":["streaming children into fixed ability groups for the rest of the year","summative assessment followed by a grade for each group","remedial teaching based on diagnosis, within differentiated instruction","drill and repeated practice of the subtraction algorithm with the weaker group"],"answer":2,"explanation":"Diagnosis followed by targeted re-teaching of a specific gap is remedial teaching; doing it alongside extension work for others differentiates instruction. It is a temporary, flexible grouping, not permanent streaming.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक निदानात्मक परीक्षण दिखाता है कि छह बच्चे घटाव में पुनर्समूहन नहीं कर सकते। शिक्षिका उनके साथ छोटे समूह में दहाई-इकाई ब्लॉकों के साथ कार्य करती है, जबकि अन्य विस्तार-प्रश्न करते हैं। इसका सबसे अच्छा वर्णन है:","optionsHi":["बच्चों को शेष वर्ष के लिए स्थिर योग्यता-समूहों में बाँटना","योगात्मक आकलन, जिसके बाद प्रत्येक समूह के लिए ग्रेड","निदान पर आधारित उपचारात्मक शिक्षण, विभेदित अनुदेशन के भीतर","कमज़ोर समूह के साथ घटाव के एल्गोरिदम का अभ्यास और बार-बार दोहराव"],"explanationHi":"किसी विशिष्ट कमी का निदान और फिर लक्षित पुनः शिक्षण उपचारात्मक शिक्षण है; इसे दूसरों के विस्तार-कार्य के साथ करना अनुदेशन को विभेदित करता है। यह अस्थायी, लचीला समूहीकरण है, स्थायी श्रेणीकरण नहीं।"},
  {"id":"cdp-pedagogy-subjects-1148","question":"Which of these statements about manipulatives in mathematics are correct? I. Manipulatives are useful only for slow learners. II. Children need to reflect on and talk about what they do with materials. III. The same concept should be shown with several different materials. IV. Materials should be withdrawn gradually as children link actions to symbols.","options":["I and II only","I, III and IV","II and III only","II, III and IV"],"answer":3,"explanation":"Materials help all learners, including the most able, so I is false. Reflection, multiple embodiments and gradual fading towards symbols describe sound use of manipulatives.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"गणित में हस्तचालित सामग्री (manipulatives) के बारे में इनमें से कौन-से कथन सही हैं? I. हस्तचालित सामग्री केवल धीमे सीखने वालों के लिए उपयोगी है। II. बच्चों को इस पर चिंतन करने और बात करने की आवश्यकता है कि वे सामग्री के साथ क्या करते हैं। III. एक ही संकल्पना को कई अलग-अलग सामग्रियों से दिखाया जाना चाहिए। IV. जब बच्चे क्रियाओं को प्रतीकों से जोड़ने लगें तो सामग्री को धीरे-धीरे हटाया जाना चाहिए।","optionsHi":["केवल I और II","I, III और IV","केवल II और III","II, III और IV"],"explanationHi":"सामग्री सभी अधिगमकर्ताओं की, सबसे योग्य सहित, सहायता करती है, इसलिए I असत्य है। चिंतन, बहु-मूर्तन और प्रतीकों की ओर धीरे-धीरे हटाना हस्तचालित सामग्री के सही उपयोग का वर्णन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1149","question":"A Class 7 science test for Hindi-medium students is set in complex English, and many students who explain the concepts well orally score poorly. The main problem with the test is that:","options":["Its reliability is low, because students' scores would change a lot if it were retaken","Its validity is low: it measures English reading, not understanding of science","Its objectivity is low, because different examiners would mark the answers differently","Its practicability is low, because it takes far too long to administer and mark"],"answer":1,"explanation":"A test is valid if it measures what it claims to measure. Here language skill, not science understanding, is driving the scores, so the inferences drawn from them are invalid even if the marking is consistent.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"हिंदी-माध्यम के विद्यार्थियों के लिए कक्षा 7 का विज्ञान परीक्षण जटिल अंग्रेज़ी में बनाया गया है, और कई विद्यार्थी जो संकल्पनाएँ मौखिक रूप से अच्छी तरह समझाते हैं, कम अंक पाते हैं। परीक्षण की मुख्य समस्या यह है कि:","optionsHi":["इसकी विश्वसनीयता कम है, क्योंकि दोबारा देने पर विद्यार्थियों के अंक बहुत बदल जाएँगे","इसकी वैधता कम है: यह विज्ञान की समझ नहीं, अंग्रेज़ी पठन को मापता है","इसकी वस्तुनिष्ठता कम है, क्योंकि अलग-अलग परीक्षक उत्तरों को अलग ढंग से अंकित करेंगे","इसकी व्यावहारिकता कम है, क्योंकि इसे लेने और जाँचने में बहुत अधिक समय लगता है"],"explanationHi":"परीक्षण तब वैध होता है जब वह वही मापे जो वह मापने का दावा करता है। यहाँ अंकों को विज्ञान की समझ नहीं, भाषा-कौशल संचालित कर रहा है, इसलिए उनसे निकाले गए निष्कर्ष अवैध हैं, भले ही अंकन सुसंगत हो।"},
  {"id":"cdp-pedagogy-subjects-1150","question":"Two science teachers mark the same set of project reports and their marks differ widely for the same reports. The most effective step to reduce this problem is to:","options":["Let only the senior teacher mark the reports, since she has more experience","Use a common rubric and discuss a few sample reports together before marking","Give every report the average of the two teachers' marks and move on","Replace project work with written tests, which are easier to mark consistently"],"answer":1,"explanation":"Wide differences between markers show low inter-rater reliability; shared criteria and moderation with samples make marking consistent without giving up the value of project work.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"दो विज्ञान शिक्षक परियोजना-रिपोर्टों के एक ही समूह को अंकित करते हैं और एक ही रिपोर्ट पर उनके अंक बहुत भिन्न हैं। इस समस्या को घटाने का सबसे प्रभावी कदम है:","optionsHi":["केवल वरिष्ठ शिक्षिका को रिपोर्टें अंकित करने देना, क्योंकि उसे अधिक अनुभव है","अंकन से पहले एक सामान्य रूब्रिक का उपयोग करना और कुछ नमूना रिपोर्टों पर साथ मिलकर चर्चा करना","प्रत्येक रिपोर्ट को दोनों शिक्षकों के अंकों का औसत देकर आगे बढ़ जाना","परियोजना-कार्य को लिखित परीक्षाओं से बदल देना, जिन्हें सुसंगत रूप से अंकित करना आसान है"],"explanationHi":"जाँचकर्ताओं के बीच बड़े अंतर कम अंतर-निर्णायक विश्वसनीयता दिखाते हैं; साझा मानदंड और नमूनों के साथ संयमन अंकन को सुसंगत बनाते हैं, परियोजना-कार्य का मूल्य छोड़े बिना।"},
  {"id":"cdp-pedagogy-subjects-1151","question":"A teacher checks whether each student can set up a circuit in which two bulbs glow, marking each student simply as 'can do' or 'not yet', regardless of how others perform. This assessment is:","options":["Norm-referenced, because it compares each student's performance with the others","Summative, because it is a final grade awarded for the whole year","Criterion-referenced, because performance is judged against a fixed standard","Diagnostic, because it is used to identify students with learning disabilities"],"answer":2,"explanation":"Judging each student against a set standard of performance, not against classmates, is criterion-referenced assessment.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"एक शिक्षक जाँचता है कि क्या प्रत्येक विद्यार्थी ऐसा परिपथ बना सकता है जिसमें दो बल्ब जलें, और प्रत्येक विद्यार्थी को केवल 'कर सकता है' या 'अभी नहीं' अंकित करता है, इस पर ध्यान दिए बिना कि दूसरे कैसा प्रदर्शन करते हैं। यह आकलन है:","optionsHi":["मानक-संदर्भित, क्योंकि यह प्रत्येक विद्यार्थी के प्रदर्शन की दूसरों से तुलना करता है","योगात्मक, क्योंकि यह पूरे वर्ष के लिए दिया गया अंतिम ग्रेड है","कसौटी-संदर्भित, क्योंकि प्रदर्शन को एक निश्चित मानक के विरुद्ध आँका जाता है","निदानात्मक, क्योंकि इसका उपयोग अधिगम अक्षमता वाले विद्यार्थियों की पहचान के लिए होता है"],"explanationHi":"प्रत्येक विद्यार्थी को सहपाठियों के विरुद्ध नहीं, प्रदर्शन के निर्धारित मानक के विरुद्ध आँकना कसौटी-संदर्भित आकलन है।"},
  {"id":"cdp-pedagogy-subjects-1152","question":"In a Class 8 practical examination, the viva consists only of questions such as 'Name this apparatus' and 'What is the formula of water?' Which change would most improve it?","options":["Asking more questions of the same type, so that the viva covers all the apparatus","Removing the viva altogether, since the written record shows enough","Asking students to read out their written records to the examiner","Asking students why they got their result and what they would change next time"],"answer":3,"explanation":"A viva should probe understanding of the experiment, such as how the result relates to the method and sources of error; naming apparatus tests only recall.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा 8 की प्रायोगिक परीक्षा में मौखिक परीक्षा केवल 'इस उपकरण का नाम बताइए' और 'पानी का सूत्र क्या है?' जैसे प्रश्नों से बनी है। कौन-सा परिवर्तन इसे सबसे अधिक सुधारेगा?","optionsHi":["इसी प्रकार के और प्रश्न पूछना, ताकि मौखिक परीक्षा सभी उपकरणों को समेट ले","मौखिक परीक्षा को पूरी तरह हटा देना, क्योंकि लिखित अभिलेख पर्याप्त दिखाता है","विद्यार्थियों से परीक्षक को अपने लिखित अभिलेख पढ़कर सुनाने को कहना","विद्यार्थियों से पूछना कि उन्हें अपना परिणाम क्यों मिला और अगली बार वे क्या बदलेंगे"],"explanationHi":"मौखिक परीक्षा को प्रयोग की समझ की जाँच करनी चाहिए, जैसे परिणाम का विधि से क्या संबंध है और त्रुटि के स्रोत; उपकरणों के नाम पूछना केवल स्मरण की जाँच करता है।"},
  {"id":"cdp-pedagogy-subjects-1153","question":"Before setting a term test in science, a teacher prepares a blueprint, a table showing how many marks go to each chapter, each learning objective and each type of question. The main purpose of the blueprint is to:","options":["Make sure the test covers content and objectives in the planned proportions","Make the test more difficult by including questions from every single chapter","Allow students to predict the questions and prepare for them in advance","Reduce the number of questions the teacher has to set and mark"],"answer":0,"explanation":"A blueprint is a plan that ensures the test samples the content and objectives as intended, which improves its content validity and balance.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"विज्ञान में सत्र-परीक्षा बनाने से पहले एक शिक्षिका ब्लूप्रिंट तैयार करती है, एक तालिका जो दर्शाती है कि प्रत्येक अध्याय, प्रत्येक अधिगम-उद्देश्य और प्रत्येक प्रकार के प्रश्न को कितने अंक मिलेंगे। ब्लूप्रिंट का मुख्य उद्देश्य है:","optionsHi":["यह सुनिश्चित करना कि परीक्षा विषय-वस्तु और उद्देश्यों को नियोजित अनुपात में समेटे","प्रत्येक अध्याय से प्रश्न शामिल करके परीक्षा को अधिक कठिन बनाना","विद्यार्थियों को प्रश्नों का अनुमान लगाने और पहले से उनकी तैयारी करने देना","शिक्षिका को जितने प्रश्न बनाने और जाँचने पड़ते हैं उनकी संख्या घटाना"],"explanationHi":"ब्लूप्रिंट एक योजना है जो सुनिश्चित करती है कि परीक्षा विषय-वस्तु और उद्देश्यों का इच्छित रूप से प्रतिचयन करे, जिससे उसकी विषय-वस्तु वैधता और संतुलन सुधरते हैं।"},
  {"id":"cdp-pedagogy-subjects-1154","question":"A Class 7 teacher often skips activities to 'finish the syllabus'. Which guiding principle of NCF 2005 most directly argues against this practice?","options":["Making examinations more rigid and centralised so that all schools follow one standard","Shifting learning away from rote methods and connecting it to life outside school","Increasing the number of chapters in each textbook to cover more science","Giving more homework so that the full syllabus is covered on time"],"answer":1,"explanation":"NCF 2005 calls for learning connected to life outside school and away from rote methods; activities are how this happens in science, not an optional extra after the syllabus.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"कक्षा 7 की एक शिक्षिका 'पाठ्यक्रम पूरा करने' के लिए अक्सर गतिविधियाँ छोड़ देती है। NCF 2005 का कौन-सा मार्गदर्शक सिद्धांत इस प्रथा के विरुद्ध सबसे सीधे तर्क देता है?","optionsHi":["परीक्षाओं को अधिक कठोर और केंद्रीकृत बनाना ताकि सभी विद्यालय एक मानक का पालन करें","अधिगम को रटंत विधियों से हटाकर विद्यालय के बाहर के जीवन से जोड़ना","विज्ञान को अधिक समेटने के लिए प्रत्येक पाठ्यपुस्तक में अध्यायों की संख्या बढ़ाना","अधिक गृहकार्य देना ताकि पूरा पाठ्यक्रम समय पर पूरा हो"],"explanationHi":"NCF 2005 विद्यालय के बाहर के जीवन से जुड़े और रटंत विधियों से दूर अधिगम का आह्वान करती है; विज्ञान में यह गतिविधियों से ही होता है, पाठ्यक्रम पूरा होने के बाद का वैकल्पिक अतिरिक्त नहीं।"},
  {"id":"cdp-pedagogy-subjects-1155","question":"Which features should a good upper primary science textbook have, in the spirit of NCF 2005? 1. Activities followed by open-ended questions. 2. The answers to every activity printed beside it. 3. Examples drawn from different regions and communities of India. 4. Boxes inviting students to think, discuss and find out more.","options":["1 and 2 only","2, 3 and 4 only","1, 3 and 4 only","1, 2, 3 and 4"],"answer":2,"explanation":"Printing the answers beside each activity turns it into confirmation and discourages students from thinking about their own observations. The other features support inquiry and inclusion.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"NCF 2005 की भावना में एक अच्छी उच्च प्राथमिक विज्ञान पाठ्यपुस्तक में कौन-सी विशेषताएँ होनी चाहिए? 1. गतिविधियाँ, जिनके बाद खुले प्रश्न हों। 2. प्रत्येक गतिविधि के बगल में छपे उसके उत्तर। 3. भारत के विभिन्न क्षेत्रों और समुदायों से लिए गए उदाहरण। 4. ऐसे बॉक्स जो विद्यार्थियों को सोचने, चर्चा करने और और जानने के लिए आमंत्रित करें।","optionsHi":["केवल 1 और 2","केवल 2, 3 और 4","केवल 1, 3 और 4","1, 2, 3 और 4"],"explanationHi":"प्रत्येक गतिविधि के बगल में उत्तर छापना उसे पुष्टि में बदल देता है और विद्यार्थियों को अपने अवलोकनों के बारे में सोचने से हतोत्साहित करता है। अन्य विशेषताएँ अन्वेषण और समावेशन का समर्थन करती हैं।"},
  {"id":"cdp-pedagogy-subjects-1156","question":"A school library keeps children's science magazines and story books about science in Hindi and English, and a teacher encourages students to read them. The main purpose of such supplementary reading is to:","options":["Replace the textbook as the main source of questions for the examination","Increase the number of facts students must memorise for the term tests","Keep students busy and quiet during free periods in the library","Encourage curiosity and reading about science beyond the textbook"],"answer":3,"explanation":"Supplementary materials widen exposure, build reading habits and nurture curiosity; they complement the textbook and are not meant for rote learning.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"एक विद्यालय का पुस्तकालय हिंदी और अंग्रेज़ी में बच्चों की विज्ञान-पत्रिकाएँ और विज्ञान पर कहानी की किताबें रखता है, और एक शिक्षक विद्यार्थियों को उन्हें पढ़ने के लिए प्रोत्साहित करता है। ऐसे पूरक पठन का मुख्य उद्देश्य है:","optionsHi":["परीक्षा के प्रश्नों के मुख्य स्रोत के रूप में पाठ्यपुस्तक की जगह लेना","सत्र-परीक्षाओं के लिए विद्यार्थियों को जो तथ्य याद करने होते हैं उनकी संख्या बढ़ाना","पुस्तकालय के खाली कालांशों में विद्यार्थियों को व्यस्त और शांत रखना","पाठ्यपुस्तक से आगे विज्ञान के बारे में जिज्ञासा और पठन को प्रोत्साहित करना"],"explanationHi":"पूरक सामग्री संपर्क को व्यापक बनाती है, पठन की आदतें बनाती है और जिज्ञासा का पोषण करती है; वह पाठ्यपुस्तक की पूरक है और रटने के लिए नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1157","question":"Students build a working periscope from cardboard and two mirrors. Compared with studying a chart of a periscope, this is more effective mainly because:","options":["It involves students actively and shows how the mirrors' angles make it work","It takes more time than a chart, and so keeps students busy for the whole period","It is less expensive than buying a printed chart of a periscope from the market","It needs no explanation from the teacher, since the model explains itself"],"answer":0,"explanation":"Making a working model engages hands and minds: students must place the mirrors correctly, and adjusting them reveals the principle of reflection.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"विद्यार्थी गत्ते और दो दर्पणों से कार्यशील परिदर्शी (periscope) बनाते हैं। परिदर्शी के चार्ट का अध्ययन करने की तुलना में यह मुख्यतः अधिक प्रभावी क्यों है?","optionsHi":["इसमें विद्यार्थी सक्रिय रूप से शामिल होते हैं और यह दिखाता है कि दर्पणों के कोण इसे कैसे कार्य कराते हैं","इसमें चार्ट से अधिक समय लगता है, इसलिए यह विद्यार्थियों को पूरे कालांश में व्यस्त रखता है","यह बाज़ार से परिदर्शी का छपा चार्ट खरीदने से कम खर्चीला है","इसके लिए शिक्षक से किसी स्पष्टीकरण की आवश्यकता नहीं, क्योंकि मॉडल स्वयं समझाता है"],"explanationHi":"कार्यशील मॉडल बनाना हाथों और मन दोनों को संलग्न करता है: विद्यार्थियों को दर्पण सही ढंग से लगाने पड़ते हैं, और उन्हें समायोजित करने से परावर्तन का सिद्धांत प्रकट होता है।"},
  {"id":"cdp-pedagogy-subjects-1158","question":"At the school science exhibition, students explain their projects to parents and the local community. Apart from showing their work, the main educational value of this is that it:","options":["Allows the school to rank students for prizes in front of their parents","Saves the teacher the effort of assessing each project separately herself","Builds communication skills and links school science with the community","Is required by the examination board as part of the final science marks"],"answer":2,"explanation":"Explaining work to an outside audience builds communication and confidence, and brings science into the community, which NCF 2005 encourages.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"विद्यालय के विज्ञान-प्रदर्शनी में विद्यार्थी अपनी परियोजनाएँ अभिभावकों और स्थानीय समुदाय को समझाते हैं। अपना कार्य दिखाने के अलावा, इसका मुख्य शैक्षिक मूल्य यह है कि यह:","optionsHi":["विद्यालय को अभिभावकों के सामने पुरस्कारों के लिए विद्यार्थियों को क्रमित करने देता है","शिक्षिका को प्रत्येक परियोजना का अलग-अलग स्वयं आकलन करने के प्रयास से बचाता है","संप्रेषण-कौशल बनाता है और विद्यालयी विज्ञान को समुदाय से जोड़ता है","परीक्षा बोर्ड द्वारा विज्ञान के अंतिम अंकों के भाग के रूप में आवश्यक है"],"explanationHi":"बाहरी श्रोताओं को अपना कार्य समझाने से संप्रेषण और आत्मविश्वास बनता है, और विज्ञान समुदाय में पहुँचता है, जिसे NCF 2005 प्रोत्साहित करती है।"},
  {"id":"cdp-pedagogy-subjects-1159","question":"A group of Class 8 students plan a two-month project on whether the water quality of a local pond changes after a festival. Which actions of the teacher are appropriate? 1. Helping them sharpen the question and decide what to measure. 2. Doing the measurements for them to save time. 3. Helping them plan how to record and present data. 4. Writing the conclusion so that it matches the expected result.","options":["1 and 3 only","1, 2 and 3 only","2 and 4 only","1, 3 and 4 only"],"answer":0,"explanation":"In project work, the teacher is a facilitator who guides the framing, planning and recording; doing measurements or writing conclusions for students takes the learning away from them.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा 8 के विद्यार्थियों का एक समूह दो महीने की परियोजना की योजना बनाता है कि क्या किसी त्योहार के बाद स्थानीय तालाब के पानी की गुणवत्ता बदलती है। शिक्षक की कौन-सी क्रियाएँ उचित हैं? 1. उन्हें प्रश्न को धार देने और क्या मापना है यह तय करने में मदद करना। 2. समय बचाने के लिए उनके स्थान पर माप स्वयं करना। 3. उन्हें आँकड़े दर्ज और प्रस्तुत करने की योजना बनाने में मदद करना। 4. निष्कर्ष इस प्रकार लिखना कि वह अपेक्षित परिणाम से मेल खाए।","optionsHi":["केवल 1 और 3","केवल 1, 2 और 3","केवल 2 और 4","केवल 1, 3 और 4"],"explanationHi":"परियोजना-कार्य में शिक्षक सुगमकर्ता होता है जो प्रश्न गढ़ने, योजना बनाने और अभिलेखन में मार्गदर्शन करता है; विद्यार्थियों के लिए माप करना या निष्कर्ष लिखना उनसे अधिगम छीन लेता है।"},
  {"id":"cdp-pedagogy-subjects-1160","question":"Assertion (A): Virtual laboratories should completely replace hands-on practical work at the upper primary stage. Reason (R): Virtual laboratories allow experiments to be repeated many times safely.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Virtual labs have real advantages, such as safe repetition, but they cannot develop handling skills or the experience of real materials, so they should supplement, not replace, hands-on work.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"अभिकथन (A): उच्च प्राथमिक स्तर पर आभासी प्रयोगशालाओं को हाथ से किए जाने वाले प्रायोगिक कार्य की पूरी तरह जगह ले लेनी चाहिए। कारण (R): आभासी प्रयोगशालाएँ प्रयोगों को सुरक्षित रूप से कई बार दोहराने की अनुमति देती हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"आभासी प्रयोगशालाओं के वास्तविक लाभ हैं, जैसे सुरक्षित दोहराव, पर वे उपकरण सँभालने के कौशल या वास्तविक सामग्री के अनुभव को विकसित नहीं कर सकतीं, इसलिए उन्हें हाथ से किए जाने वाले कार्य का पूरक होना चाहिए, विकल्प नहीं।"},
  {"id":"cdp-pedagogy-subjects-1161","question":"A teacher plays a 20-minute video on the digestive system without stopping, and then moves to the next topic. Which change would make the video most effective for learning?","options":["Playing a longer video with more information so that nothing is left out","Playing it twice in a row so that students remember the details better","Pausing for prediction and discussion, and following it with an activity","Asking students to copy the narration into their notebooks while it plays"],"answer":2,"explanation":"Video becomes a learning tool when it is used actively, with pauses for prediction, questions and discussion; passive viewing is little better than a lecture.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"एक शिक्षक पाचन तंत्र पर 20 मिनट का वीडियो बिना रोके चलाता है और फिर अगले विषय पर चला जाता है। कौन-सा परिवर्तन वीडियो को अधिगम के लिए सबसे प्रभावी बनाएगा?","optionsHi":["अधिक जानकारी वाला लंबा वीडियो चलाना ताकि कुछ छूट न जाए","उसे लगातार दो बार चलाना ताकि विद्यार्थी विवरण बेहतर याद रखें","पूर्वानुमान और चर्चा के लिए रुकना, और उसके बाद कोई गतिविधि कराना","वीडियो चलते समय विद्यार्थियों से वर्णन को अपनी कॉपियों में उतारने को कहना"],"explanationHi":"वीडियो तब अधिगम का साधन बनता है जब उसका सक्रिय उपयोग हो, पूर्वानुमान, प्रश्नों और चर्चा के लिए रुकते हुए; निष्क्रिय देखना व्याख्यान से बहुत बेहतर नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1162","question":"A student says that a ball rolls down a slope 'because of gravity'. The teacher responds, 'What do you mean by gravity here? Would the ball roll if the slope were on the moon?' This kind of question is best described as a:","options":["Rhetorical question","Leading question","Closed recall question","Probing question"],"answer":3,"explanation":"A probing question follows up an answer to make the student clarify, justify or extend it, revealing whether the term 'gravity' is understood or only named.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"एक विद्यार्थी कहता है कि गेंद ढलान पर 'गुरुत्व के कारण' लुढ़कती है। शिक्षक प्रतिक्रिया देता है, 'यहाँ गुरुत्व से तुम्हारा क्या अर्थ है? क्या गेंद लुढ़कती यदि ढलान चंद्रमा पर होती?' इस प्रकार के प्रश्न का सबसे अच्छा वर्णन है:","optionsHi":["वाक्-चातुर्य प्रश्न (rhetorical question)","प्रेरक प्रश्न (leading question)","बंद स्मरण प्रश्न","गहन पड़ताल वाला प्रश्न (probing question)"],"explanationHi":"गहन पड़ताल वाला प्रश्न उत्तर के आगे का होता है जो विद्यार्थी को स्पष्ट करने, औचित्य देने या विस्तार करने को कहता है, यह प्रकट करते हुए कि 'गुरुत्व' शब्द समझा गया है या केवल नाम लिया गया है।"},
  {"id":"cdp-pedagogy-subjects-1163","question":"Which homework task is most in line with the aims of upper primary science teaching?","options":["Observing the moon each night for a week and drawing its shape","Copying the answers to all the chapter's exercises neatly from a guide book","Writing the definitions of ten new terms five times each to fix them in memory","Learning the chapter's summary by heart for a test the next day"],"answer":0,"explanation":"Observation-based homework extends inquiry beyond the classroom and builds skills of observing and recording; copying or memorising builds rote habits.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"उच्च प्राथमिक विज्ञान शिक्षण के उद्देश्यों के सबसे अनुरूप कौन-सा गृहकार्य है?","optionsHi":["एक सप्ताह तक हर रात चंद्रमा का अवलोकन करना और उसका आकार बनाना","किसी कुंजी-पुस्तिका से अध्याय के सभी अभ्यासों के उत्तर साफ़-साफ़ उतारना","दस नए शब्दों की परिभाषाएँ याद रखने के लिए प्रत्येक को पाँच-पाँच बार लिखना","अगले दिन की परीक्षा के लिए अध्याय का सारांश कंठस्थ करना"],"explanationHi":"अवलोकन-आधारित गृहकार्य जिज्ञासा-आधारित अन्वेषण को कक्षा से बाहर बढ़ाता है और देखने तथा दर्ज करने के कौशल बनाता है; नकल या कंठस्थीकरण रटने की आदतें बनाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1164","question":"While teaching 'water', a teacher uses rainfall data to make graphs, discusses who controls water in the village and how it is shared, and studies the water cycle and water-borne diseases. This approach is best called:","options":["Disciplinary, subject-centred approach","Spiral curriculum approach","Thematic, interdisciplinary approach","Programmed instruction approach"],"answer":2,"explanation":"Organising learning around a theme that draws on several subjects (science, mathematics, social science) is the thematic, interdisciplinary approach. A spiral approach revisits a topic at increasing depth across years.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"'जल' पढ़ाते समय एक शिक्षक वर्षा के आँकड़ों से आलेख बनवाता है, चर्चा करता है कि गाँव में जल पर किसका नियंत्रण है और वह कैसे बाँटा जाता है, और जल-चक्र तथा जलजनित रोगों का अध्ययन करता है। इस उपागम को सबसे अच्छी तरह कहा जाएगा:","optionsHi":["अनुशासनात्मक, विषय-केंद्रित उपागम","सर्पिल पाठ्यचर्या उपागम","विषयवस्तु-आधारित (थीमैटिक), अंतरविषयक उपागम","अभिक्रमित अनुदेशन उपागम"],"explanationHi":"किसी विषयवस्तु के इर्द-गिर्द अधिगम को संगठित करना जो कई विषयों (विज्ञान, गणित, सामाजिक विज्ञान) से लेता है, विषयवस्तु-आधारित, अंतरविषयक उपागम है। सर्पिल उपागम वर्षों में बढ़ती गहराई के साथ किसी विषय पर लौटता है।"},
  {"id":"cdp-pedagogy-subjects-1165","question":"A science teacher realises during a lesson that she herself has believed that 'heavier objects fall faster'. The most professional response is to:","options":["Avoid teaching falling objects in future so that she does not mislead students","Continue to teach her belief, since students will not notice the difference","Ask a colleague to teach the topic every year in her place","Test the idea, read about it, discuss it with peers and correct her teaching"],"answer":3,"explanation":"Teachers often share students' misconceptions; reflective practice means checking one's ideas with evidence and updating one's teaching, which also models a scientific attitude.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"एक विज्ञान शिक्षिका को पाठ के दौरान एहसास होता है कि वह स्वयं मानती रही है कि 'भारी वस्तुएँ तेज़ गिरती हैं'। सबसे पेशेवर प्रतिक्रिया है:","optionsHi":["भविष्य में गिरती वस्तुओं को पढ़ाने से बचना ताकि वह विद्यार्थियों को भ्रमित न करे","अपनी मान्यता को पढ़ाना जारी रखना, क्योंकि विद्यार्थी अंतर नहीं देखेंगे","किसी सहकर्मी से हर वर्ष अपनी जगह इस विषय को पढ़ाने को कहना","विचार का परीक्षण करना, उसके बारे में पढ़ना, साथियों से चर्चा करना और अपने शिक्षण को सुधारना"],"explanationHi":"शिक्षक प्रायः विद्यार्थियों की भ्रांतियाँ साझा करते हैं; चिंतनशील अभ्यास का अर्थ है अपने विचारों को साक्ष्य से जाँचना और अपने शिक्षण को अद्यतन करना, जो वैज्ञानिक अभिवृत्ति का आदर्श भी प्रस्तुत करता है।"},
  {"id":"cdp-pedagogy-subjects-1166","question":"A teacher notices that many students read the measuring cylinder wrongly. She decides to investigate systematically. Arrange the steps of action research in order: P. Plan and carry out a new way of teaching the reading  Q. Identify the problem clearly  R. Evaluate whether the readings have improved  S. Form hypotheses about the causes, such as the eye not being level with the liquid","options":["Q, P, S, R","S, Q, P, R","Q, S, R, P","Q, S, P, R"],"answer":3,"explanation":"Action research moves from identifying a classroom problem, to hypothesising causes, to trying a planned action, to evaluating its effect, which may lead to another cycle.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"एक शिक्षिका देखती है कि कई विद्यार्थी मापन-सिलिंडर का पाठ्यांक गलत पढ़ते हैं। वह व्यवस्थित रूप से जाँच करने का निर्णय लेती है। क्रियात्मक अनुसंधान के चरणों को क्रम में लगाइए: P. पाठ्यांक पढ़ना सिखाने का नया तरीका योजनाबद्ध करना और लागू करना Q. समस्या की स्पष्ट पहचान करना R. मूल्यांकन करना कि पाठ्यांक सुधरे या नहीं S. कारणों के बारे में परिकल्पनाएँ बनाना, जैसे आँख का द्रव के समतल पर न होना","optionsHi":["Q, P, S, R","S, Q, P, R","Q, S, R, P","Q, S, P, R"],"explanationHi":"क्रियात्मक अनुसंधान कक्षा की समस्या की पहचान से कारणों की परिकल्पना, फिर नियोजित कार्रवाई आज़माने, और फिर उसके प्रभाव के मूल्यांकन की ओर बढ़ता है, जो एक और चक्र की ओर ले जा सकता है।"},
  {"id":"cdp-pedagogy-subjects-1167","question":"A teacher wants to find out whether her lesson actually changed students' ideas about plants' food. Which design gives the best evidence?","options":["Giving the same diagnostic questions, with reasons, before and after the lesson","Asking students at the end of the lesson whether they understood it well","Counting how many students completed all of the lesson's activities","Giving a single test only at the end of the term on the whole chapter on plants"],"answer":0,"explanation":"Comparing the same items before and after, with students' reasons, shows whether their ideas actually shifted. Self-reports and participation counts say little about conceptual change.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"एक शिक्षिका यह जानना चाहती है कि क्या उसके पाठ ने वास्तव में पौधों के भोजन के बारे में विद्यार्थियों के विचार बदले। कौन-सी रूपरेखा सबसे अच्छा साक्ष्य देती है?","optionsHi":["पाठ से पहले और बाद में कारण सहित वही निदानात्मक प्रश्न देना","पाठ के अंत में विद्यार्थियों से पूछना कि क्या उन्होंने उसे अच्छी तरह समझा","गिनना कि कितने विद्यार्थियों ने पाठ की सभी गतिविधियाँ पूरी कीं","पौधों के पूरे अध्याय पर सत्र के अंत में केवल एक परीक्षा देना"],"explanationHi":"वही प्रश्न पहले और बाद में, विद्यार्थियों के कारणों सहित, तुलना करना दिखाता है कि उनके विचार वास्तव में बदले या नहीं। स्व-रिपोर्ट और सहभागिता की गिनती संकल्पनात्मक परिवर्तन के बारे में बहुत कम बताती है।"},
  {"id":"cdp-pedagogy-subjects-1168","question":"Which feedback on a student's lab report is most likely to improve her learning?","options":["'Good work. 7/10. Your diagram is neat and your handwriting has improved a lot.'","'Your conclusion ignores trial 3. What does that result suggest about it?'","'Poor. Write more neatly next time and underline all the headings in red.'","'Wrong conclusion. See the textbook and copy the correct conclusion from page 42.'"],"answer":1,"explanation":"Effective feedback is specific, refers to the work and guides the next step, prompting the student to think. Marks or general remarks do not tell her how to improve.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"एक विद्यार्थी की प्रयोगशाला-रिपोर्ट पर कौन-सी प्रतिपुष्टि उसके अधिगम को सुधारने की सबसे अधिक संभावना रखती है?","optionsHi":["'अच्छा कार्य। 7/10। तुम्हारा आरेख साफ़ है और तुम्हारी लिखावट में बहुत सुधार हुआ है।'","'तुम्हारा निष्कर्ष परीक्षण 3 की उपेक्षा करता है। वह परिणाम उसके बारे में क्या सुझाता है?'","'खराब। अगली बार अधिक साफ़ लिखो और सभी शीर्षकों को लाल रंग से रेखांकित करो।'","'गलत निष्कर्ष। पाठ्यपुस्तक देखो और पृष्ठ 42 से सही निष्कर्ष उतार लो।'"],"explanationHi":"प्रभावी प्रतिपुष्टि विशिष्ट होती है, कार्य का संदर्भ देती है और अगले कदम का मार्गदर्शन करती है, विद्यार्थी को सोचने के लिए प्रेरित करते हुए। अंक या सामान्य टिप्पणियाँ उसे नहीं बतातीं कि सुधार कैसे करे।"},
  {"id":"cdp-pedagogy-subjects-1169","question":"A teacher allows students to pursue their own questions during science periods but finds that many questions cannot be investigated in school. Which is the best way to handle this?","options":["Forbid students from asking questions that are not covered anywhere in the textbook","Answer all such questions herself so that no class time is wasted on them","Help turn the questions into testable ones and keep the rest for later research","Ignore such questions, since they cannot be answered with school equipment"],"answer":2,"explanation":"Turning a broad question ('Why do plants grow?') into a testable one ('Do bean seeds grow taller in light or in the dark?') teaches an important inquiry skill, while other questions can be kept for reading or research.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"एक शिक्षक विज्ञान के कालांशों में विद्यार्थियों को अपने प्रश्नों का अनुसरण करने देता है, पर पाता है कि कई प्रश्नों की विद्यालय में जाँच नहीं हो सकती। इसे सँभालने का सबसे अच्छा तरीका क्या है?","optionsHi":["विद्यार्थियों को ऐसे प्रश्न पूछने से रोकना जो पाठ्यपुस्तक में कहीं नहीं हैं","ऐसे सभी प्रश्नों का उत्तर स्वयं दे देना ताकि उन पर कक्षा का समय व्यर्थ न हो","प्रश्नों को परीक्षण-योग्य बनाने में मदद करना और शेष को बाद के शोध के लिए रखना","ऐसे प्रश्नों की उपेक्षा करना, क्योंकि उनका उत्तर विद्यालय के उपकरणों से नहीं दिया जा सकता"],"explanationHi":"किसी व्यापक प्रश्न ('पौधे क्यों बढ़ते हैं?') को परीक्षण-योग्य प्रश्न ('क्या सेम के बीज प्रकाश में अधिक ऊँचे बढ़ते हैं या अँधेरे में?') में बदलना एक महत्त्वपूर्ण जिज्ञासा-आधारित अन्वेषण कौशल सिखाता है, जबकि अन्य प्रश्न पठन या शोध के लिए रखे जा सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-1170","question":"A teacher's science class consists of first-generation learners whose parents work as farm labourers. Which strategy is most likely to make science meaningful to them?","options":["Using examples from urban homes shown in the textbook, to widen exposure","Starting from their experience of farming, soil, seeds and weather","Giving extra notes to memorise, since they get little help at home","Teaching only the basic definitions, since they lack exposure to science"],"answer":1,"explanation":"Children's own experiences are rich resources; linking science to farming and weather they know well makes it meaningful and values their knowledge, in line with NCF 2005.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"एक शिक्षक की विज्ञान कक्षा में पहली पीढ़ी के अधिगमकर्ता हैं जिनके माता-पिता खेत-मज़दूर हैं। कौन-सी रणनीति विज्ञान को उनके लिए सार्थक बनाने की सबसे अधिक संभावना रखती है?","optionsHi":["पाठ्यपुस्तक में दिखाए गए शहरी घरों के उदाहरणों का उपयोग करना, ताकि संपर्क बढ़े","उनके खेती, मिट्टी, बीज और मौसम के अनुभव से आरंभ करना","याद करने के लिए अतिरिक्त नोट्स देना, क्योंकि उन्हें घर पर कम सहायता मिलती है","केवल मूल परिभाषाएँ पढ़ाना, क्योंकि उन्हें विज्ञान का संपर्क कम है"],"explanationHi":"बच्चों के अपने अनुभव समृद्ध संसाधन हैं; विज्ञान को उस खेती और मौसम से जोड़ना जिन्हें वे अच्छी तरह जानते हैं, उसे सार्थक बनाता है और उनके ज्ञान को महत्त्व देता है, जो NCF 2005 के अनुरूप है।"},
  {"id":"cdp-pedagogy-subjects-1171","question":"A teacher wants to check what students already know about electricity before starting the chapter. Which tool is most suitable?","options":["A short questionnaire asking students to predict and explain simple circuits","The end-of-chapter test from the textbook, given on the very first day of the chapter","A list of definitions to be learnt by heart before the chapter begins","A project report on all the electrical appliances in their homes"],"answer":0,"explanation":"A pre-assessment asking for predictions and explanations reveals prior knowledge and misconceptions, so teaching can start from where students are.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS","questionHi":"एक शिक्षक अध्याय शुरू करने से पहले जाँचना चाहता है कि विद्यार्थी बिजली के बारे में पहले से क्या जानते हैं। कौन-सा उपकरण सबसे उपयुक्त है?","optionsHi":["एक छोटी प्रश्नावली जो विद्यार्थियों से सरल परिपथों का पूर्वानुमान और स्पष्टीकरण माँगे","पाठ्यपुस्तक का अध्याय-अंत परीक्षण, जो अध्याय के बिल्कुल पहले दिन दिया जाए","परिभाषाओं की सूची जिन्हें अध्याय शुरू होने से पहले कंठस्थ करना हो","उनके घरों के सभी विद्युत उपकरणों पर परियोजना रिपोर्ट"],"explanationHi":"पूर्वानुमान और स्पष्टीकरण माँगने वाला पूर्व-आकलन पूर्व ज्ञान और भ्रांतियों को प्रकट करता है, ताकि शिक्षण वहीं से आरंभ हो जहाँ विद्यार्थी हैं।"},
  {"id":"cdp-pedagogy-subjects-1172","question":"Which of the following is a genuine limitation of using only paper-pencil tests in science? 1. They cannot directly assess skills of handling apparatus. 2. They cannot assess any higher-order thinking. 3. They give little evidence of scientific attitudes such as cooperation. 4. They can be badly affected by students' reading level.","options":["1 and 2 only","2 and 3 only","1, 2, 3 and 4","1, 3 and 4 only"],"answer":3,"explanation":"Well-designed written questions can assess higher-order thinking, so 2 is false. But they cannot show manipulative skills or attitudes directly, and reading difficulties can distort them.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"विज्ञान में केवल कागज़-पेंसिल परीक्षाओं के उपयोग की वास्तविक सीमा निम्नलिखित में से कौन-सी है? 1. वे उपकरण सँभालने के कौशलों का सीधे आकलन नहीं कर सकतीं। 2. वे किसी भी उच्च-स्तरीय चिंतन का आकलन नहीं कर सकतीं। 3. वे सहयोग जैसी वैज्ञानिक अभिवृत्तियों के बारे में बहुत कम साक्ष्य देती हैं। 4. वे विद्यार्थियों के पठन-स्तर से बुरी तरह प्रभावित हो सकती हैं।","optionsHi":["केवल 1 और 2","केवल 2 और 3","1, 2, 3 और 4","केवल 1, 3 और 4"],"explanationHi":"अच्छी तरह बनाए गए लिखित प्रश्न उच्च-स्तरीय चिंतन का आकलन कर सकते हैं, इसलिए 2 असत्य है। पर वे संचालन-कौशल या अभिवृत्तियों को सीधे नहीं दिखा सकते, और पठन-कठिनाइयाँ उन्हें विकृत कर सकती हैं।"},
  {"id":"cdp-pedagogy-subjects-1173","question":"Which of the following are commonly identified problems in the teaching of social science in Indian schools?\n1. It is often seen as a 'soft' subject of lesser value than science.\n2. Textbooks and teaching are loaded with information to be memorised.\n3. Most schools devote too much time to field work and projects.\n4. Content is often taught without connection to children's lives.","options":["1, 2 and 3 only","2, 3 and 4 only","1, 2 and 4 only","1 and 3 only"],"answer":2,"explanation":"Low status, information overload and disconnection from children's lives are widely noted problems, including in NCF 2005. The reality is the reverse of statement 3: field work and projects are usually too rare, not too frequent.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"भारतीय विद्यालयों में सामाजिक विज्ञान के शिक्षण की सामान्यतः पहचानी गई समस्याओं में से कौन-सी हैं?\n1. इसे प्रायः विज्ञान से कम मूल्य का 'नरम' विषय माना जाता है।\n2. पाठ्यपुस्तकें और शिक्षण याद किए जाने वाली जानकारी से लदे हुए हैं।\n3. अधिकांश विद्यालय क्षेत्र-कार्य और परियोजनाओं पर बहुत अधिक समय लगाते हैं।\n4. विषय-वस्तु प्रायः बच्चों के जीवन से जोड़े बिना पढ़ाई जाती है।","optionsHi":["केवल 1, 2 और 3","केवल 2, 3 और 4","केवल 1, 2 और 4","केवल 1 और 3"],"explanationHi":"निम्न स्थिति, जानकारी का अतिभार और बच्चों के जीवन से विच्छेद, NCF 2005 सहित, व्यापक रूप से नोट की गई समस्याएँ हैं। वास्तविकता कथन 3 के विपरीत है: क्षेत्र-कार्य और परियोजनाएँ प्रायः बहुत कम होती हैं, बहुत अधिक नहीं।"},
  {"id":"cdp-pedagogy-subjects-1174","question":"Assertion (A): Teaching centred on board examinations is a major cause of rote learning in social science.\nReason (R): When examinations reward reproducing textbook answers, teachers and students concentrate on memorisation.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"What examinations reward shapes what is taught and learnt. If recall earns marks, memorisation becomes the rational strategy, so R explains A.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): बोर्ड परीक्षाओं पर केंद्रित शिक्षण सामाजिक विज्ञान में रटंत अधिगम का एक प्रमुख कारण है।\nकारण (R): जब परीक्षाएँ पाठ्यपुस्तक के उत्तरों को पुनः प्रस्तुत करने को पुरस्कृत करती हैं, तो शिक्षक और विद्यार्थी स्मरण पर ध्यान केंद्रित करते हैं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"परीक्षाएँ जिसे पुरस्कृत करती हैं वही पढ़ाया और सीखा जाता है। यदि स्मरण से अंक मिलते हैं, तो रटना तर्कसंगत रणनीति बन जाता है, इसलिए R, A की व्याख्या करता है।"},
  {"id":"cdp-pedagogy-subjects-1175","question":"A teacher in a government school in Uttar Pradesh has 62 students in Class VII and wants everyone to take part in a discussion on 'Why do some families migrate to cities?'. Which strategy suits her situation best?","options":["Drop the discussion, since it is impossible to manage in such a large class","Use think-pair-share and small groups with roles, then take one point from each","Let only the front-bench students discuss while the rest listen and take notes","Hold the discussion only with the toppers after school, when the room is quieter"],"answer":1,"explanation":"Large classes call for structures that let everyone think and speak at once, such as pairs and small groups, before sharing with the whole class. Limiting discussion to a few students leaves most of the class out.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"उत्तर प्रदेश के एक सरकारी विद्यालय की शिक्षिका की कक्षा VII में 62 विद्यार्थी हैं और वह चाहती है कि 'कुछ परिवार शहरों में प्रवास क्यों करते हैं?' पर चर्चा में सभी भाग लें। कौन-सी रणनीति उसकी स्थिति के सबसे अनुकूल है?","optionsHi":["चर्चा छोड़ देना, क्योंकि इतनी बड़ी कक्षा में उसे सँभालना असंभव है","सोचो-जोड़ी बनाओ-साझा करो और भूमिकाओं वाले छोटे समूहों का उपयोग करना, फिर प्रत्येक से एक बिंदु लेना","केवल अगली बेंच के विद्यार्थियों को चर्चा करने देना जबकि बाकी सुनें और नोट्स लें","चर्चा केवल टॉपरों के साथ विद्यालय के बाद करना, जब कमरा अधिक शांत हो"],"explanationHi":"बड़ी कक्षाओं के लिए ऐसी संरचनाएँ चाहिए जो सभी को एक साथ सोचने और बोलने दें, जैसे जोड़ियाँ और छोटे समूह, फिर पूरी कक्षा के साथ साझा करना। चर्चा को कुछ विद्यार्थियों तक सीमित करने से अधिकांश कक्षा छूट जाती है।"},
  {"id":"cdp-pedagogy-subjects-1176","question":"A village school in Jharkhand has no wall maps, projector or library. Which plan best uses low-cost resources to teach Class VI students about their district?","options":["Wait until the school receives a government grant for wall maps and a projector","Ask students to buy atlases from the city so that each child has a proper printed map","Teach the topic only from the textbook, since resources are not available","Draw a ground map with chalk, use old newspapers and invite local elders to share"],"answer":3,"explanation":"The community and local surroundings are rich, free resources. A ground map, newspapers and local resource persons make learning concrete even without equipment.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"झारखंड के एक ग्रामीण विद्यालय में कोई दीवार-मानचित्र, प्रोजेक्टर या पुस्तकालय नहीं है। कक्षा VI के विद्यार्थियों को उनके ज़िले के बारे में पढ़ाने के लिए कौन-सी योजना कम लागत वाले संसाधनों का सबसे अच्छा उपयोग करती है?","optionsHi":["विद्यालय को दीवार-मानचित्रों और प्रोजेक्टर के लिए सरकारी अनुदान मिलने तक प्रतीक्षा करना","विद्यार्थियों से शहर से एटलस खरीदने को कहना ताकि प्रत्येक बच्चे के पास उचित छपा मानचित्र हो","विषय को केवल पाठ्यपुस्तक से पढ़ाना, क्योंकि संसाधन उपलब्ध नहीं हैं","चाक से भूमि पर मानचित्र बनाना, पुराने अख़बारों का उपयोग करना और स्थानीय बुज़ुर्गों को अनुभव साझा करने के लिए आमंत्रित करना"],"explanationHi":"समुदाय और स्थानीय परिवेश समृद्ध, निःशुल्क संसाधन हैं। भूमि पर बना मानचित्र, अख़बार और स्थानीय संसाधन-व्यक्ति उपकरणों के बिना भी अधिगम को मूर्त बनाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1177","question":"To introduce federalism in Class X, a teacher compares the country to a school in which the principal, the house captains and the class monitors each handle certain matters. Which evaluation of this analogy is most accurate?","options":["It is a useful start, but she must also show where the comparison breaks down","It is a perfect explanation of federalism and needs no further discussion","It is wrong, since analogies should never be used in teaching social science topics","It is useful only for primary classes, as Class X needs formal definitions"],"answer":0,"explanation":"Analogies help bridge to abstract ideas, but every analogy breaks somewhere. In a school the principal can override monitors; in a federation, powers are constitutionally guaranteed. Pointing out the limits completes the learning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा X में संघवाद का परिचय देने के लिए एक शिक्षिका देश की तुलना एक विद्यालय से करती है जिसमें प्रधानाचार्य, सदन-कप्तान और कक्षा-मॉनिटर प्रत्येक कुछ विषय सँभालते हैं। इस सादृश्य का कौन-सा मूल्यांकन सबसे सटीक है?","optionsHi":["यह एक उपयोगी आरंभ है, पर उसे यह भी दिखाना चाहिए कि तुलना कहाँ टूटती है","यह संघवाद की एकदम सही व्याख्या है और इस पर आगे चर्चा की आवश्यकता नहीं","यह गलत है, क्योंकि सामाजिक विज्ञान के विषयों के शिक्षण में सादृश्यों का कभी उपयोग नहीं करना चाहिए","यह केवल प्राथमिक कक्षाओं के लिए उपयोगी है, क्योंकि कक्षा X को औपचारिक परिभाषाएँ चाहिए"],"explanationHi":"सादृश्य अमूर्त विचारों तक पुल बनाने में मदद करते हैं, पर हर सादृश्य कहीं टूटता है। विद्यालय में प्रधानाचार्य मॉनिटरों को अधिभावी कर सकता है; संघ में शक्तियाँ संवैधानिक रूप से सुनिश्चित हैं। सीमाएँ बताना अधिगम को पूरा करता है।"},
  {"id":"cdp-pedagogy-subjects-1178","question":"Which of the following are reasons why many students find social science boring?\n1. It is often taught as a set of facts to be memorised.\n2. Lessons are seldom connected with students' own lives and surroundings.\n3. The subject by its nature cannot be made engaging.","options":["1 and 3 only","2 and 3 only","1, 2 and 3","1 and 2 only"],"answer":3,"explanation":"Boredom comes from the way social science is often taught, by rote and disconnected from life, not from the subject itself. Inquiry, discussion and local study regularly make it lively.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कई विद्यार्थी सामाजिक विज्ञान को उबाऊ क्यों पाते हैं, इसके कारणों में से कौन-से हैं?\n1. इसे प्रायः याद किए जाने वाले तथ्यों के समूह के रूप में पढ़ाया जाता है।\n2. पाठ शायद ही कभी विद्यार्थियों के अपने जीवन और परिवेश से जुड़े होते हैं।\n3. विषय अपनी प्रकृति से रोचक नहीं बनाया जा सकता।","optionsHi":["केवल 1 और 3","केवल 2 और 3","1, 2 और 3","केवल 1 और 2"],"explanationHi":"ऊब इस ढंग से आती है जिससे सामाजिक विज्ञान प्रायः पढ़ाया जाता है, रटंत और जीवन से कटा हुआ, विषय से नहीं। जिज्ञासा-आधारित अन्वेषण, चर्चा और स्थानीय अध्ययन उसे नियमित रूप से जीवंत बनाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1179","question":"A social science teacher realises that she always praises the achievements of her own community's historical figures at length and passes quickly over those of others. What is the most appropriate step?","options":["Continue, since teachers naturally know more about their own community's history","Avoid discussing any historical figures at all, so as to remain neutral","Reflect on her own bias, use varied sources and balance different communities","Ask students from other communities to teach the class about their own figures"],"answer":2,"explanation":"Teachers bring their own social positions into class. Reflection and deliberate use of diverse sources are needed for fair teaching. Omitting all figures or handing the job to students does not address the bias.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"एक सामाजिक विज्ञान शिक्षिका को एहसास होता है कि वह अपने समुदाय के ऐतिहासिक व्यक्तित्वों की उपलब्धियों की हमेशा विस्तार से प्रशंसा करती है और दूसरों की उपलब्धियों से जल्दी निकल जाती है। सबसे उपयुक्त कदम क्या है?","optionsHi":["जारी रखना, क्योंकि शिक्षक स्वाभाविक रूप से अपने समुदाय का इतिहास अधिक जानते हैं","तटस्थ रहने के लिए किसी भी ऐतिहासिक व्यक्तित्व पर चर्चा से बचना","अपने पूर्वाग्रह पर चिंतन करना, विविध स्रोतों का उपयोग करना और विभिन्न समुदायों को संतुलित करना","अन्य समुदायों के विद्यार्थियों से कक्षा को अपने व्यक्तित्वों के बारे में पढ़ाने को कहना"],"explanationHi":"शिक्षक अपनी सामाजिक स्थितियाँ कक्षा में लाते हैं। निष्पक्ष शिक्षण के लिए चिंतन और विविध स्रोतों का सोचा-समझा उपयोग आवश्यक है। सभी व्यक्तित्वों को छोड़ देना या काम विद्यार्थियों को सौंपना पूर्वाग्रह को संबोधित नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-1180","question":"A Class VII social science teacher and the mathematics teacher plan a joint lesson in which students tabulate monthly rainfall data for their town, draw bar graphs and explain the pattern of the monsoon. What is the main benefit?","options":["The social science teacher can skip the chapter on climate in her own class","Students use maths on a real geographical question and see subjects as linked","Students can be given marks in both subjects for one task, which saves teachers time","The mathematics syllabus becomes lighter, since data handling is covered"],"answer":1,"explanation":"Cross-curricular work uses skills from one subject to understand another, making both meaningful. The chapter is still taught; this is a richer way of teaching it.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VII की सामाजिक विज्ञान शिक्षिका और गणित शिक्षक एक संयुक्त पाठ की योजना बनाते हैं जिसमें विद्यार्थी अपने कस्बे की मासिक वर्षा के आँकड़े सारणीबद्ध करते हैं, स्तंभ-आलेख बनाते हैं और मानसून के प्रतिरूप को समझाते हैं। मुख्य लाभ क्या है?","optionsHi":["सामाजिक विज्ञान शिक्षिका अपनी कक्षा में जलवायु का अध्याय छोड़ सकती है","विद्यार्थी वास्तविक भौगोलिक प्रश्न पर गणित का उपयोग करते हैं और विषयों को जुड़ा हुआ देखते हैं","एक कार्य के लिए विद्यार्थियों को दोनों विषयों में अंक दिए जा सकते हैं, जिससे शिक्षकों का समय बचता है","गणित का पाठ्यक्रम हल्का हो जाता है, क्योंकि आँकड़ा-संचालन समेटा जा चुका है"],"explanationHi":"अंतर-पाठ्यचर्या कार्य एक विषय के कौशलों को दूसरे को समझने में प्रयोग करता है, जिससे दोनों सार्थक बनते हैं। अध्याय फिर भी पढ़ाया जाता है; यह उसे पढ़ाने का अधिक समृद्ध तरीका है।"},
  {"id":"cdp-pedagogy-subjects-1181","question":"Class VI students keep confusing latitudes with longitudes. Which approach is likely to work best?","options":["Ask them to repeat 'latitudes run east-west, longitudes run north-south' daily","Give them a list of the latitudes and longitudes of major cities to memorise","Skip the topic until Class IX, when students are mature enough for it","Use a globe or orange with lines drawn on it, and link the grid to graph paper"],"answer":3,"explanation":"Handling a model and linking the grid to familiar coordinates on graph paper builds the concept spatially. Chanting a phrase can still leave students confused about which lines are which.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"कक्षा VI के विद्यार्थी अक्षांशों और देशांतरों को बार-बार गड़बड़ाते हैं। कौन-सा उपागम सबसे अच्छा काम करने की संभावना रखता है?","optionsHi":["उनसे प्रतिदिन 'अक्षांश पूर्व-पश्चिम चलते हैं, देशांतर उत्तर-दक्षिण' दोहरवाना","उन्हें याद करने के लिए प्रमुख शहरों के अक्षांशों और देशांतरों की सूची देना","इस विषय को कक्षा IX तक छोड़ देना, जब विद्यार्थी इसके लिए पर्याप्त परिपक्व हों","रेखाओं वाला ग्लोब या संतरा उपयोग करना, और ग्रिड को ग्राफ़ पेपर से जोड़ना"],"explanationHi":"मॉडल को हाथ में लेना और ग्रिड को ग्राफ़ पेपर पर परिचित निर्देशांकों से जोड़ना संकल्पना को स्थानिक रूप से बनाता है। वाक्यांश दोहराने से विद्यार्थी फिर भी भ्रमित रह सकते हैं कि कौन-सी रेखाएँ कौन-सी हैं।"},
  {"id":"cdp-pedagogy-subjects-1182","question":"A Class VI child says, 'Day and night happen because the sun goes around the earth.' What is the best first step for the teacher?","options":["Tell the child the correct answer and ask her to write it five times","Darken the room and let children rotate a globe in front of a torch","Say that this is a science question and not part of social science","Show a written definition of rotation and ask the child to memorise it"],"answer":1,"explanation":"A torch-and-globe model lets children see that the earth's rotation produces day and night, which directly confronts the misconception. Telling or defining does not change the child's mental model.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VI की एक बच्ची कहती है, 'दिन और रात इसलिए होते हैं क्योंकि सूर्य पृथ्वी के चारों ओर घूमता है।' शिक्षक के लिए सबसे अच्छा पहला कदम क्या है?","optionsHi":["बच्ची को सही उत्तर बताना और उससे उसे पाँच बार लिखने को कहना","कमरे को अँधेरा करना और बच्चों को टॉर्च के सामने ग्लोब घुमाने देना","यह कहना कि यह विज्ञान का प्रश्न है, सामाजिक विज्ञान का भाग नहीं","घूर्णन की लिखित परिभाषा दिखाना और बच्ची से उसे कंठस्थ करने को कहना"],"explanationHi":"टॉर्च-और-ग्लोब मॉडल बच्चों को देखने देता है कि पृथ्वी का घूर्णन दिन और रात उत्पन्न करता है, जो सीधे भ्रांति का सामना करता है। बताने या परिभाषा देने से बच्ची का मानसिक मॉडल नहीं बदलता।"},
  {"id":"cdp-pedagogy-subjects-1183","question":"Many Class VI students believe it is hot in summer because the earth is then closer to the sun. Which piece of evidence best challenges this belief?","options":["India and Australia, about equally far from the sun, have opposite seasons","The sun looks bigger and brighter at noon than it does in the evening sky","Hill stations are cooler than the plains in summer because of their height","Deserts are hot during the day and cold at night, even in the summer months"],"answer":0,"explanation":"If distance caused seasons, both hemispheres would have summer together. Opposite seasons in the two hemispheres show that the tilt of the earth's axis, which changes the angle of sunlight and the length of the day, is the cause.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा VI के कई विद्यार्थी मानते हैं कि गर्मियों में गर्मी इसलिए होती है कि तब पृथ्वी सूर्य के अधिक निकट होती है। कौन-सा साक्ष्य इस विश्वास को सबसे अच्छी तरह चुनौती देता है?","optionsHi":["भारत और ऑस्ट्रेलिया, सूर्य से लगभग समान दूरी पर, में विपरीत ऋतुएँ होती हैं","दोपहर में सूर्य शाम के आकाश की तुलना में बड़ा और अधिक चमकीला दिखता है","पर्वतीय स्थल गर्मियों में अपनी ऊँचाई के कारण मैदानों से ठंडे होते हैं","रेगिस्तान दिन में गर्म और रात में ठंडे होते हैं, गर्मी के महीनों में भी"],"explanationHi":"यदि दूरी ऋतुएँ लाती, तो दोनों गोलार्धों में एक साथ गर्मी होती। दोनों गोलार्धों में विपरीत ऋतुएँ दिखाती हैं कि कारण पृथ्वी की धुरी का झुकाव है, जो सूर्य-प्रकाश का कोण और दिन की लंबाई बदलता है।"},
  {"id":"cdp-pedagogy-subjects-1184","question":"Class VIII students say 'the government' means only the Prime Minister and the ministers in Delhi. Which activity best widens their understanding?","options":["Ask them to memorise the list of Union ministers and their departments","Find out who repairs their street lights and runs their school, and at what level","Show a video of Parliament in session and discuss what the ministers said in the debate","Tell them that government is too large a topic for Class VIII students"],"answer":1,"explanation":"Tracing everyday services to the panchayat or municipality, the state and the union reveals the levels of government through students' own experience.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VIII के विद्यार्थी कहते हैं कि 'सरकार' का अर्थ केवल दिल्ली में प्रधानमंत्री और मंत्री हैं। कौन-सी गतिविधि उनकी समझ को सबसे अच्छी तरह व्यापक बनाती है?","optionsHi":["उनसे केंद्रीय मंत्रियों और उनके विभागों की सूची याद करवाना","पता लगाना कि उनकी गली की बत्तियाँ कौन ठीक करता है और उनका विद्यालय कौन चलाता है, और किस स्तर पर","संसद की कार्यवाही का वीडियो दिखाना और चर्चा करना कि मंत्रियों ने बहस में क्या कहा","उन्हें बताना कि सरकार कक्षा VIII के विद्यार्थियों के लिए बहुत बड़ा विषय है"],"explanationHi":"रोज़मर्रा की सेवाओं को पंचायत या नगरपालिका, राज्य और संघ तक खोजने से विद्यार्थियों के अपने अनुभव के माध्यम से सरकार के स्तर प्रकट होते हैं।"},
  {"id":"cdp-pedagogy-subjects-1185","question":"A Class X teacher asks groups to list what 'development' would mean for a landless rural labourer, a prosperous farmer, an urban unemployed youth and a girl from a well-off family. What is the main purpose?","options":["To show that development means only higher income for every group of people","To prove that one group's view of development is the correct one for India","To show that different people can have different, even conflicting, goals","To teach how to calculate per capita income for each of the four people"],"answer":2,"explanation":"Comparing these goals reveals that development is plural and contested: more days of work for one, freedom or dignity for another, and sometimes one person's development harms another's. Income alone does not capture it.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा X की एक शिक्षिका समूहों से सूची बनवाती है कि 'विकास' का अर्थ एक भूमिहीन ग्रामीण मज़दूर, एक संपन्न किसान, एक शहरी बेरोज़गार युवा और एक संपन्न परिवार की लड़की के लिए क्या होगा। मुख्य उद्देश्य क्या है?","optionsHi":["यह दिखाना कि विकास का अर्थ हर समूह के लोगों के लिए केवल अधिक आय है","यह सिद्ध करना कि विकास का एक समूह का दृष्टिकोण भारत के लिए सही है","यह दिखाना कि भिन्न लोगों के भिन्न, यहाँ तक कि परस्पर विरोधी, लक्ष्य हो सकते हैं","चारों व्यक्तियों में से प्रत्येक के लिए प्रति व्यक्ति आय की गणना करना सिखाना"],"explanationHi":"इन लक्ष्यों की तुलना प्रकट करती है कि विकास बहुवचन और विवादित है: एक के लिए अधिक दिनों का काम, दूसरे के लिए स्वतंत्रता या गरिमा, और कभी एक का विकास दूसरे को हानि पहुँचाता है। केवल आय इसे नहीं पकड़ती।"},
  {"id":"cdp-pedagogy-subjects-1186","question":"Several Class VIII students say 'secular' means 'against religion'. Which response best builds the correct understanding?","options":["Tell them that secularism means people should give up religion in public life","Ask them to memorise that India is a secular state, as the Preamble of the Constitution says","Avoid the topic, since it relates to religion and may upset some families","Discuss cases where the state favours no religion yet protects religious freedom"],"answer":3,"explanation":"Indian secularism keeps a principled distance from all religions while protecting religious freedom and equality. Cases make this concrete; the 'anti-religion' idea is the misconception to be replaced.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा VIII के कई विद्यार्थी कहते हैं कि 'धर्मनिरपेक्ष' का अर्थ 'धर्म के विरुद्ध' है। कौन-सी प्रतिक्रिया सही समझ को सबसे अच्छी तरह बनाती है?","optionsHi":["उन्हें बताना कि धर्मनिरपेक्षता का अर्थ है कि लोगों को सार्वजनिक जीवन में धर्म त्याग देना चाहिए","उनसे याद करवाना कि भारत एक धर्मनिरपेक्ष राज्य है, जैसा संविधान की उद्देशिका कहती है","विषय से बचना, क्योंकि यह धर्म से संबंधित है और कुछ परिवारों को आहत कर सकता है","उन मामलों पर चर्चा करना जिनमें राज्य किसी धर्म का पक्ष नहीं लेता फिर भी धार्मिक स्वतंत्रता की रक्षा करता है"],"explanationHi":"भारतीय धर्मनिरपेक्षता सभी धर्मों से सैद्धांतिक दूरी रखती है जबकि धार्मिक स्वतंत्रता और समानता की रक्षा करती है। मामले इसे मूर्त बनाते हैं; 'धर्म-विरोधी' का विचार वह भ्रांति है जिसे बदला जाना है।"},
  {"id":"cdp-pedagogy-subjects-1187","question":"A Class VII teacher uses satellite imagery software to show students the land use around their school, then zooms out to the district and the state. What should she do to make this most useful?","options":["Let students explore the software freely without any particular task","Set questions to answer, such as where farmland is turning into housing and why","Use the tool mainly to impress students with how modern the technology is","Replace all map work with satellite images, since they are more accurate than drawn maps"],"answer":1,"explanation":"Technology helps learning when tied to guiding questions. Satellite views make change in land use visible, but without a task students simply browse.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा VII की एक शिक्षिका विद्यार्थियों को उनके विद्यालय के आस-पास का भूमि-उपयोग दिखाने के लिए उपग्रह-चित्र सॉफ़्टवेयर का उपयोग करती है, फिर ज़िले और राज्य तक ज़ूम आउट करती है। इसे सबसे उपयोगी बनाने के लिए उसे क्या करना चाहिए?","optionsHi":["विद्यार्थियों को बिना किसी विशेष कार्य के सॉफ़्टवेयर को स्वतंत्र रूप से खोजने देना","उत्तर देने के लिए प्रश्न देना, जैसे कि कृषि-भूमि आवासों में कहाँ और क्यों बदल रही है","साधन का उपयोग मुख्यतः विद्यार्थियों को प्रभावित करने के लिए करना कि तकनीक कितनी आधुनिक है","सभी मानचित्र-कार्य को उपग्रह-चित्रों से बदल देना, क्योंकि वे बनाए गए मानचित्रों से अधिक सटीक हैं"],"explanationHi":"तकनीक तब अधिगम में सहायक होती है जब वह मार्गदर्शक प्रश्नों से जुड़ी हो। उपग्रह-दृश्य भूमि-उपयोग में परिवर्तन को दृश्यमान बनाते हैं, पर कार्य के बिना विद्यार्थी केवल ब्राउज़ करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1188","question":"A Class VIII teacher shows a popular feature film about the freedom struggle. What should accompany the screening?","options":["Nothing; the film is accurate because it is about real people and events","A test on the names of the actors and the characters they played","A discussion comparing scenes with sources and why films dramatise events","A ban on discussing the film so that students are not misled by it"],"answer":2,"explanation":"Films shape popular memory. Comparing them with sources teaches students the difference between dramatisation and history and why such changes are made.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VIII का एक शिक्षक स्वतंत्रता संग्राम पर एक लोकप्रिय फ़ीचर फ़िल्म दिखाता है। प्रदर्शन के साथ क्या होना चाहिए?","optionsHi":["कुछ नहीं; फ़िल्म सटीक है क्योंकि वह वास्तविक लोगों और घटनाओं के बारे में है","अभिनेताओं और उनके द्वारा निभाए गए पात्रों के नामों पर एक परीक्षा","स्रोतों से दृश्यों की तुलना और इस पर चर्चा कि फ़िल्में घटनाओं का नाटकीकरण क्यों करती हैं","फ़िल्म पर चर्चा पर रोक, ताकि विद्यार्थी उससे भ्रमित न हों"],"explanationHi":"फ़िल्में लोकप्रिय स्मृति को आकार देती हैं। उन्हें स्रोतों से तुलना करना विद्यार्थियों को नाटकीकरण और इतिहास के अंतर, और ऐसे परिवर्तन क्यों किए जाते हैं, यह सिखाता है।"},
  {"id":"cdp-pedagogy-subjects-1189","question":"Class VI students in a Chennai school write that 'all people in Rajasthan live in the desert and ride camels'. What is the best way to correct this over-generalisation?","options":["Show images of Rajasthan's cities, hills and farms and let students revise it","Tell them they are wrong and give them the correct sentence to copy","Say that the statement is mostly true, so it can be accepted as it is","Skip the topic, since students in Tamil Nadu do not need to know about Rajasthan"],"answer":0,"explanation":"Evidence of variety within a region lets students revise the stereotype themselves. Simply correcting or accepting the statement leaves the habit of over-generalising unchallenged.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"चेन्नई के एक विद्यालय में कक्षा VI के विद्यार्थी लिखते हैं कि 'राजस्थान के सभी लोग रेगिस्तान में रहते हैं और ऊँट की सवारी करते हैं।' इस अतिसामान्यीकरण को सुधारने का सबसे अच्छा तरीका क्या है?","optionsHi":["राजस्थान के शहरों, पहाड़ियों और खेतों के चित्र दिखाना और विद्यार्थियों को उसे संशोधित करने देना","उन्हें बताना कि वे गलत हैं और सही वाक्य नकल करने को देना","कहना कि कथन अधिकांशतः सत्य है, इसलिए उसे जैसा है वैसा स्वीकार किया जा सकता है","विषय छोड़ देना, क्योंकि तमिलनाडु के विद्यार्थियों को राजस्थान के बारे में जानने की आवश्यकता नहीं"],"explanationHi":"किसी क्षेत्र के भीतर विविधता का साक्ष्य विद्यार्थियों को रूढ़ि स्वयं संशोधित करने देता है। कथन को केवल सुधारना या स्वीकारना अतिसामान्यीकरण की आदत को चुनौती-रहित छोड़ देता है।"},
  {"id":"cdp-pedagogy-subjects-1190","question":"In many schools a social science period consists of the teacher reading the chapter aloud, explaining difficult words and dictating question-answers. What is the main problem with this practice?","options":["It takes too long and makes it hard to finish the syllabus on time","It keeps students passive, with no chance to inquire or connect ideas to life","It is too difficult for students to follow without a guide book","It uses too many teaching aids, which distract students from the text of the chapter"],"answer":1,"explanation":"Reading and dictation turn social science into transfer of information, with no room for questioning or thinking. This is one of the main problems NCF 2005 identifies.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कई विद्यालयों में सामाजिक विज्ञान का कालांश शिक्षक द्वारा अध्याय को ज़ोर से पढ़ने, कठिन शब्द समझाने और प्रश्नोत्तर लिखवाने से बनता है। इस प्रथा की मुख्य समस्या क्या है?","optionsHi":["इसमें बहुत समय लगता है और पाठ्यक्रम समय पर पूरा करना कठिन हो जाता है","यह विद्यार्थियों को निष्क्रिय रखता है, जिज्ञासा-आधारित अन्वेषण या विचारों को जीवन से जोड़ने का कोई अवसर नहीं देता","कुंजी-पुस्तिका के बिना विद्यार्थियों के लिए इसका अनुसरण करना बहुत कठिन है","यह बहुत अधिक शिक्षण-साधन उपयोग करता है, जो विद्यार्थियों को अध्याय के पाठ से भटकाते हैं"],"explanationHi":"पढ़ना और श्रुतलेख सामाजिक विज्ञान को सूचना के हस्तांतरण में बदल देते हैं, प्रश्न करने या सोचने के लिए कोई स्थान नहीं छोड़ते। यह NCF 2005 द्वारा चिह्नित मुख्य समस्याओं में से एक है।"},
  {"id":"cdp-pedagogy-subjects-1191","question":"A school in Delhi does not allow off-campus trips because of safety rules. How can a Class VII teacher still give students first-hand experience of local institutions?","options":["Tell students that first-hand experience is not really needed for this chapter","Show the textbook pictures of the post office, bank and municipal office instead","Invite local resource persons and take a supervised walk around the neighbourhood","Give students a list of local institutions and their functions to memorise"],"answer":2,"explanation":"Resource persons and short supervised walks bring the community into learning within safety limits. Textbook pictures alone do not provide first-hand engagement.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT","questionHi":"दिल्ली का एक विद्यालय सुरक्षा नियमों के कारण परिसर के बाहर यात्राओं की अनुमति नहीं देता। कक्षा VII का शिक्षक फिर भी विद्यार्थियों को स्थानीय संस्थाओं का प्रत्यक्ष अनुभव कैसे दे सकता है?","optionsHi":["विद्यार्थियों को बताना कि इस अध्याय के लिए प्रत्यक्ष अनुभव वास्तव में आवश्यक नहीं है","इसके बजाय डाकघर, बैंक और नगरपालिका कार्यालय के पाठ्यपुस्तक चित्र दिखाना","स्थानीय संसाधन-व्यक्तियों को आमंत्रित करना और पड़ोस में पर्यवेक्षित सैर पर ले जाना","विद्यार्थियों को स्थानीय संस्थाओं और उनके कार्यों की सूची देना जिसे वे याद करें"],"explanationHi":"संसाधन-व्यक्ति और छोटी पर्यवेक्षित सैर सुरक्षा-सीमाओं के भीतर समुदाय को अधिगम में लाती हैं। केवल पाठ्यपुस्तक के चित्र प्रत्यक्ष जुड़ाव नहीं देते।"},
  {"id":"cdp-pedagogy-subjects-1192","question":"Assertion (A): A visit to a district court helps Class VIII students understand the working of the judiciary.\nReason (R): The Supreme Court is the highest court of appeal in India.","options":["Both A and R are true and R is the correct explanation of A","A is true but R is false","A is false but R is true","Both A and R are true but R is not the correct explanation of A"],"answer":3,"explanation":"Both statements are true. But the value of the visit comes from seeing proceedings first-hand, not from the position of the Supreme Court, so R does not explain A.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"अभिकथन (A): ज़िला न्यायालय का भ्रमण कक्षा VIII के विद्यार्थियों को न्यायपालिका की कार्यप्रणाली समझने में मदद करता है।\nकारण (R): उच्चतम न्यायालय भारत में अपील का सर्वोच्च न्यायालय है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है"],"explanationHi":"दोनों कथन सत्य हैं। पर भ्रमण का मूल्य कार्यवाही को प्रत्यक्ष देखने से आता है, उच्चतम न्यायालय की स्थिति से नहीं, इसलिए R, A की व्याख्या नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-1193","question":"A Class IX teacher finds that most students think democracy simply means 'voting in elections'. Which activity would best deepen their understanding?","options":["Ask them to memorise Abraham Lincoln's famous definition of democracy word for word","Count how many general and state elections India has held since independence","Ask them to write an essay on why every citizen must vote in each election","Study cases of a free press, courts protecting rights and officials held to account"],"answer":3,"explanation":"Elections are necessary but not sufficient; rights, rule of law, free media and accountability are also essential. Cases make these features visible, whereas a definition or an essay on voting keeps the narrow view.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा IX की एक शिक्षिका पाती है कि अधिकांश विद्यार्थी सोचते हैं कि लोकतंत्र का अर्थ बस 'चुनावों में मतदान' है। कौन-सी गतिविधि उनकी समझ को सबसे अच्छी तरह गहरा करेगी?","optionsHi":["उनसे अब्राहम लिंकन की लोकतंत्र की प्रसिद्ध परिभाषा शब्दशः याद करवाना","गिनना कि स्वतंत्रता के बाद से भारत ने कितने आम और राज्य चुनाव कराए हैं","उनसे निबंध लिखवाना कि प्रत्येक नागरिक को हर चुनाव में मतदान क्यों करना चाहिए","स्वतंत्र प्रेस, अधिकारों की रक्षा करने वाले न्यायालयों और जवाबदेह ठहराए गए अधिकारियों के मामलों का अध्ययन करना"],"explanationHi":"चुनाव आवश्यक हैं पर पर्याप्त नहीं; अधिकार, विधि का शासन, स्वतंत्र मीडिया और जवाबदेही भी आवश्यक हैं। मामले इन विशेषताओं को दृश्यमान बनाते हैं, जबकि परिभाषा या मतदान पर निबंध संकीर्ण दृष्टि को बनाए रखते हैं।"},
  {"id":"cdp-pedagogy-subjects-1194","question":"Class VI students complain that history has 'too many dates'. Which response best addresses this?","options":["Remove all dates from history teaching so that students focus on stories","Insist that students memorise every date in the chapter, since dates are history","Use timelines for sequence and duration, and expect only key landmark dates","Give extra marks to students who remember the most dates in each test"],"answer":2,"explanation":"Chronology matters, but as a framework for understanding change, not a list to memorise. Timelines and a few key landmarks give that framework; removing dates altogether would destroy the sense of time.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VI के विद्यार्थी शिकायत करते हैं कि इतिहास में 'बहुत अधिक तिथियाँ' हैं। कौन-सी प्रतिक्रिया इसे सबसे अच्छी तरह संबोधित करती है?","optionsHi":["इतिहास शिक्षण से सभी तिथियाँ हटा देना ताकि विद्यार्थी कहानियों पर ध्यान दें","आग्रह करना कि विद्यार्थी अध्याय की प्रत्येक तिथि याद करें, क्योंकि तिथियाँ ही इतिहास हैं","क्रम और अवधि के लिए समय-रेखाओं का उपयोग करना, और केवल प्रमुख मील-पत्थर तिथियों की अपेक्षा करना","प्रत्येक परीक्षा में सबसे अधिक तिथियाँ याद रखने वाले विद्यार्थियों को अतिरिक्त अंक देना"],"explanationHi":"कालक्रम मायने रखता है, पर परिवर्तन को समझने की रूपरेखा के रूप में, याद करने की सूची के रूप में नहीं। समय-रेखाएँ और कुछ प्रमुख मील-पत्थर वह रूपरेखा देते हैं; तिथियाँ पूरी तरह हटाने से समय का बोध नष्ट हो जाएगा।"},
  {"id":"cdp-pedagogy-subjects-1195","question":"The social science periods in a Class VIII section are being taken by a teacher trained in physical education because of a vacancy. Which outcome is most likely, and what does it point to?","options":["Teaching will become more activity-based automatically, given his PE background","There is no effect, since anyone can read the textbook aloud to the class","Students will learn more because a physical education teacher is strict","Textbook-reading may take over, showing a shortage of trained subject teachers"],"answer":3,"explanation":"Without subject and pedagogical training, teachers tend to rely on the textbook and question-answer drill. A shortage of trained teachers is a recognised problem in social science teaching.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"रिक्ति के कारण कक्षा VIII के एक अनुभाग के सामाजिक विज्ञान के कालांश शारीरिक शिक्षा में प्रशिक्षित एक शिक्षक ले रहा है। कौन-सा परिणाम सबसे संभावित है, और यह किस ओर इशारा करता है?","optionsHi":["शिक्षण अपने आप अधिक गतिविधि-आधारित हो जाएगा, क्योंकि उसकी पृष्ठभूमि शारीरिक शिक्षा की है","कोई प्रभाव नहीं, क्योंकि कोई भी कक्षा को पाठ्यपुस्तक ज़ोर से पढ़कर सुना सकता है","विद्यार्थी अधिक सीखेंगे क्योंकि शारीरिक शिक्षा का शिक्षक सख़्त होता है","पाठ्यपुस्तक-पठन हावी हो सकता है, जो प्रशिक्षित विषय-शिक्षकों की कमी दिखाता है"],"explanationHi":"विषय और शिक्षणशास्त्रीय प्रशिक्षण के बिना शिक्षक पाठ्यपुस्तक और प्रश्नोत्तर अभ्यास पर निर्भर रहते हैं। प्रशिक्षित शिक्षकों की कमी सामाजिक विज्ञान शिक्षण की एक मान्य समस्या है।"},
  {"id":"cdp-pedagogy-subjects-1196","question":"Which of the following statements on making social science meaningful for children are correct?\n1. Local examples help, but must be linked to wider concepts and regions.\n2. Abstract concepts are best introduced through definitions, followed by examples if time permits.\n3. Children's questions can become the starting point of an inquiry.","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Linking local examples to larger ideas and building on children's questions make learning meaningful. Starting from definitions, with examples as an optional extra, reverses the concrete-to-abstract order.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"बच्चों के लिए सामाजिक विज्ञान को सार्थक बनाने के बारे में निम्नलिखित में से कौन-से कथन सही हैं?\n1. स्थानीय उदाहरण मदद करते हैं, पर उन्हें व्यापक संकल्पनाओं और क्षेत्रों से जोड़ा जाना चाहिए।\n2. अमूर्त संकल्पनाएँ परिभाषाओं के माध्यम से सबसे अच्छी तरह प्रस्तुत की जाती हैं, समय हो तो उदाहरण बाद में।\n3. बच्चों के प्रश्न किसी अन्वेषण का आरंभ-बिंदु बन सकते हैं।","optionsHi":["केवल 1 और 3","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"स्थानीय उदाहरणों को बड़े विचारों से जोड़ना और बच्चों के प्रश्नों पर आगे बढ़ना अधिगम को सार्थक बनाता है। परिभाषाओं से शुरू करना, उदाहरणों को वैकल्पिक अतिरिक्त मानकर, मूर्त से अमूर्त के क्रम को उलट देता है।"},
  {"id":"cdp-pedagogy-subjects-1197","question":"Many Class VII students think a 'market' is only a place with shops. The teacher wants them to see that a market can also be a chain of relations, including online sales and wholesale trading. Which activity best achieves this?","options":["Trace a shirt from cotton field to buyer, noting each buyer and seller","Ask students to draw and label all the shops of their local weekly bazaar","Give them the dictionary definition of 'market' to copy and learn by heart","Ask them to list their favourite shops in town and what each one sells"],"answer":0,"explanation":"Following a product through the chain shows that markets link many buyers and sellers across places, some not physical shops at all. Drawing local shops reinforces the narrow idea.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा VII के कई विद्यार्थी सोचते हैं कि 'बाज़ार' केवल दुकानों वाला स्थान है। शिक्षक चाहता है कि वे देखें कि बाज़ार संबंधों की एक शृंखला भी हो सकता है, जिसमें ऑनलाइन बिक्री और थोक व्यापार शामिल हैं। कौन-सी गतिविधि इसे सबसे अच्छी तरह पूरा करती है?","optionsHi":["कपास के खेत से खरीदार तक एक कमीज़ का पीछा करना, प्रत्येक खरीदार और विक्रेता को नोट करते हुए","विद्यार्थियों से अपने स्थानीय साप्ताहिक बाज़ार की सभी दुकानें बनाने और उन पर नाम लिखने को कहना","उन्हें 'बाज़ार' की शब्दकोशीय परिभाषा नकल करने और कंठस्थ करने को देना","उनसे शहर की अपनी पसंदीदा दुकानें और प्रत्येक क्या बेचती है, इसकी सूची बनाने को कहना"],"explanationHi":"किसी उत्पाद का शृंखला में पीछा करना दिखाता है कि बाज़ार स्थानों के पार अनेक खरीदारों और विक्रेताओं को जोड़ते हैं, कुछ तो भौतिक दुकानें भी नहीं होते। स्थानीय दुकानें बनाना संकीर्ण विचार को पुष्ट करता है।"},
  {"id":"cdp-pedagogy-subjects-1198","question":"Class VIII students in Kochi write reports on local fishing, share them online with a partner class in Ladakh, comment on each other's drafts and jointly publish a comparison of the two communities' livelihoods. In the SAMR model, this use of technology is best described as:","options":["Substitution","Augmentation","Modification","Redefinition"],"answer":3,"explanation":"Real-time collaboration and publishing with a distant class creates a task that was not possible without the technology, which is Redefinition. Simply typing the report would be Substitution, and adding spell-check would be Augmentation.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कोच्चि में कक्षा VIII के विद्यार्थी स्थानीय मत्स्य-पालन पर रिपोर्ट लिखते हैं, उन्हें लद्दाख की साझेदार कक्षा के साथ ऑनलाइन साझा करते हैं, एक-दूसरे के मसौदों पर टिप्पणी करते हैं और दोनों समुदायों की आजीविकाओं की तुलना संयुक्त रूप से प्रकाशित करते हैं। SAMR मॉडल में प्रौद्योगिकी के इस उपयोग का सबसे अच्छा वर्णन है:","optionsHi":["प्रतिस्थापन (Substitution)","संवर्धन (Augmentation)","संशोधन (Modification)","पुनर्परिभाषा (Redefinition)"],"explanationHi":"दूर की कक्षा के साथ वास्तविक समय में सहयोग और प्रकाशन ऐसा कार्य बनाता है जो प्रौद्योगिकी के बिना संभव नहीं था, यह पुनर्परिभाषा है। रिपोर्ट को केवल टाइप करना प्रतिस्थापन होता, और वर्तनी-जाँच जोड़ना संवर्धन होता।"},
  {"id":"cdp-pedagogy-subjects-1199","question":"A Class VI teacher is excellent with computers and knows her science content, but she uses an impressive 3D animation that runs for the whole period while children watch silently, and they learn little. Which framework best explains the gap?","options":["TPACK, since technology, pedagogy and content knowledge must work together","SAMR, because the use was at the Redefinition level, which is too advanced","Bloom's taxonomy, because the animation was pitched at the Create level","Dale's cone, because animations sit at the top of the cone of experience"],"answer":0,"explanation":"TPACK (Mishra and Koehler) holds that effective teaching with technology needs the intersection of technological, pedagogical and content knowledge. Here the pedagogical part (active learning, interaction) was missing.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VI की एक शिक्षिका कंप्यूटर में निपुण है और अपने विज्ञान-विषय को जानती है, पर वह एक प्रभावशाली 3D एनिमेशन पूरे कालांश चलाती है जबकि बच्चे चुपचाप देखते हैं, और वे बहुत कम सीखते हैं। कौन-सी रूपरेखा इस अंतर को सबसे अच्छी तरह समझाती है?","optionsHi":["TPACK, क्योंकि प्रौद्योगिकी, शिक्षणशास्त्र और विषय-ज्ञान को साथ मिलकर काम करना चाहिए","SAMR, क्योंकि उपयोग पुनर्परिभाषा के स्तर पर था, जो बहुत उन्नत है","ब्लूम का वर्गीकरण, क्योंकि एनिमेशन सृजन के स्तर पर रखा गया था","डेल का शंकु, क्योंकि एनिमेशन अनुभव के शंकु के शीर्ष पर होते हैं"],"explanationHi":"TPACK (मिश्रा और कोहलर) मानता है कि प्रौद्योगिकी के साथ प्रभावी शिक्षण के लिए प्रौद्योगिकीय, शिक्षणशास्त्रीय और विषय-ज्ञान के प्रतिच्छेदन की आवश्यकता है। यहाँ शिक्षणशास्त्रीय भाग (सक्रिय अधिगम, अंतःक्रिया) अनुपस्थित था।"},
  {"id":"cdp-pedagogy-subjects-1200","question":"A Class VII teacher shows text-heavy slides from the projector and reads them aloud for the whole period while students copy them. Which evaluation is most accurate?","options":["This is ideal ICT integration, since the projector is used in every period","The projector merely replaces the blackboard, and students stay passive","Projectors should never be used in classrooms, since they distract students","The slides should have even more text so that students get complete notes"],"answer":1,"explanation":"Technology adds value only when it changes what students can do or understand; reading slides is a lecture in a new medium. The problem is the pedagogy, not the projector.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VII की एक शिक्षिका प्रोजेक्टर से पाठ-बहुल स्लाइडें दिखाती है और पूरे कालांश उन्हें ज़ोर से पढ़ती है जबकि विद्यार्थी उन्हें उतारते हैं। कौन-सा मूल्यांकन सबसे सटीक है?","optionsHi":["यह आदर्श ICT एकीकरण है, क्योंकि प्रोजेक्टर हर कालांश में उपयोग होता है","प्रोजेक्टर केवल श्यामपट्ट की जगह लेता है, और विद्यार्थी निष्क्रिय बने रहते हैं","कक्षाओं में प्रोजेक्टर का कभी उपयोग नहीं करना चाहिए, क्योंकि वे विद्यार्थियों को भटकाते हैं","स्लाइडों में और भी अधिक पाठ होना चाहिए ताकि विद्यार्थियों को पूर्ण नोट्स मिलें"],"explanationHi":"प्रौद्योगिकी तभी मूल्य जोड़ती है जब वह बदले कि विद्यार्थी क्या कर या समझ सकते हैं; स्लाइडें पढ़ना नए माध्यम में व्याख्यान है। समस्या शिक्षणशास्त्र की है, प्रोजेक्टर की नहीं।"},
  {"id":"cdp-pedagogy-subjects-1201","question":"In a Class X school without enough electrical equipment, a teacher uses a free circuit simulation in which students change resistances and watch the current change. Which statement best describes the appropriate place of such a simulation?","options":["Simulations are always better than real experiments and should replace practical work","Simulations should never be used, because children must handle real objects only","They are useful when real kits are lacking, alongside hands-on work where possible","Simulations should be shown only after the final examination, as revision"],"answer":2,"explanation":"Simulations let students test many variables quickly and visualise what cannot be seen, which is valuable; but they complement rather than replace real experience with materials and measurement.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"पर्याप्त विद्युत उपकरणों के बिना कक्षा X के एक विद्यालय में शिक्षक एक निःशुल्क परिपथ-अनुकरण (सिमुलेशन) का उपयोग करता है जिसमें विद्यार्थी प्रतिरोध बदलते हैं और धारा को बदलते देखते हैं। ऐसे अनुकरण के उपयुक्त स्थान का सबसे अच्छा वर्णन कौन-सा कथन करता है?","optionsHi":["अनुकरण हमेशा वास्तविक प्रयोगों से बेहतर होते हैं और उन्हें प्रायोगिक कार्य की जगह ले लेनी चाहिए","अनुकरणों का कभी उपयोग नहीं करना चाहिए, क्योंकि बच्चों को केवल वास्तविक वस्तुएँ सँभालनी चाहिए","जब वास्तविक किट उपलब्ध न हों तो वे उपयोगी हैं, जहाँ संभव हो हाथ से किए जाने वाले कार्य के साथ","अनुकरण केवल अंतिम परीक्षा के बाद, पुनरावृत्ति के रूप में दिखाए जाने चाहिए"],"explanationHi":"अनुकरण विद्यार्थियों को कई चरों का शीघ्र परीक्षण करने और जो नहीं दिखता उसे कल्पित करने देते हैं, जो मूल्यवान है; पर वे सामग्री और मापन के वास्तविक अनुभव के पूरक हैं, उसकी जगह नहीं लेते।"},
  {"id":"cdp-pedagogy-subjects-1202","question":"A Class VI teacher in a small town assigns all homework through an online app. She later learns that a third of her students share one phone with their family or have no internet. What should she do?","options":["Continue with the app, since students must learn to manage technology somehow","Give lower marks to students who do not submit online, to encourage regular work","Ask parents to buy smartphones and data packs so that every child can use the app","Offer offline options, such as printed sheets, so no child depends on home internet"],"answer":3,"explanation":"ICT must not widen inequality; a digital divide calls for alternatives so that every child can do the work. Penalising students for lack of access is unfair.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"एक छोटे कस्बे की कक्षा VI की शिक्षिका सारा गृहकार्य एक ऑनलाइन ऐप से देती है। बाद में उसे पता चलता है कि उसके एक-तिहाई विद्यार्थी अपने परिवार के साथ एक ही फ़ोन साझा करते हैं या उनके पास इंटरनेट नहीं है। उसे क्या करना चाहिए?","optionsHi":["ऐप के साथ जारी रखना, क्योंकि विद्यार्थियों को प्रौद्योगिकी सँभालना किसी तरह सीखना ही होगा","जो विद्यार्थी ऑनलाइन जमा नहीं करते उन्हें कम अंक देना, ताकि नियमित कार्य को प्रोत्साहन मिले","अभिभावकों से स्मार्टफ़ोन और डेटा पैक खरीदने को कहना ताकि हर बच्चा ऐप का उपयोग कर सके","ऑफ़लाइन विकल्प देना, जैसे छपे हुए पत्रक, ताकि कोई बच्चा घर के इंटरनेट पर निर्भर न रहे"],"explanationHi":"ICT को असमानता नहीं बढ़ानी चाहिए; डिजिटल विभाजन विकल्पों की माँग करता है ताकि हर बच्चा कार्य कर सके। पहुँच की कमी के लिए विद्यार्थियों को दंडित करना अनुचित है।"},
  {"id":"cdp-pedagogy-subjects-1203","question":"A Class VII student tells his teacher that he shared his email password with a 'friend' he met in an online game and has sent him photos of himself. What is the most appropriate response by the teacher?","options":["Scold him in front of the class so that the others learn from his mistake","Take it seriously: help him stop contact, inform parents and teach online safety","Ignore it, since what happens online outside school is not the teacher's concern","Ban the student from using the computer lab for the rest of the year"],"answer":1,"explanation":"Online safety is part of digital citizenship that schools must teach; the child needs protective action and support, not shame or punishment. Possible grooming must be escalated to parents and authorities.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VII का एक विद्यार्थी अपने शिक्षक को बताता है कि उसने ऑनलाइन खेल में मिले एक 'मित्र' के साथ अपना ईमेल पासवर्ड साझा किया है और उसे अपनी तस्वीरें भेजी हैं। शिक्षक की सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["उसे कक्षा के सामने डाँटना ताकि बाकी उसकी गलती से सीखें","इसे गंभीरता से लेना: उसे संपर्क बंद करने में मदद करना, अभिभावकों को सूचित करना और ऑनलाइन सुरक्षा सिखाना","इसकी उपेक्षा करना, क्योंकि विद्यालय के बाहर ऑनलाइन जो होता है वह शिक्षक की चिंता नहीं है","विद्यार्थी को शेष वर्ष के लिए कंप्यूटर प्रयोगशाला के उपयोग से प्रतिबंधित करना"],"explanationHi":"ऑनलाइन सुरक्षा डिजिटल नागरिकता का भाग है जो विद्यालयों को सिखानी चाहिए; बच्चे को सुरक्षात्मक कार्रवाई और सहारे की आवश्यकता है, शर्मिंदगी या दंड की नहीं। संभावित शोषण (grooming) को अभिभावकों और अधिकारियों तक पहुँचाना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1204","question":"For a Class VIII project, students copy whatever the first search result says, including some false claims about a 'miracle cure'. Which teaching response is best?","options":["Teach them to check the author, date and evidence, and compare with reliable sources","Ban internet use for all projects, since online information cannot be trusted","Tell students to use only the first three search results, which are the most reliable","Allow copying as long as students paste the website link at the end"],"answer":0,"explanation":"Information literacy means evaluating sources for authority, currency, evidence and corroboration. Banning the internet or limiting to top results does not build this skill, and copying with a link is still plagiarism.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VIII की एक परियोजना के लिए विद्यार्थी पहले खोज-परिणाम में जो भी लिखा है उसे नकल कर लेते हैं, जिसमें किसी 'चमत्कारी इलाज' के कुछ झूठे दावे भी हैं। कौन-सी शिक्षण-प्रतिक्रिया सबसे अच्छी है?","optionsHi":["उन्हें लेखक, तिथि और साक्ष्य जाँचना और विश्वसनीय स्रोतों से तुलना करना सिखाना","सभी परियोजनाओं के लिए इंटरनेट का उपयोग प्रतिबंधित करना, क्योंकि ऑनलाइन जानकारी पर भरोसा नहीं किया जा सकता","विद्यार्थियों से केवल पहले तीन खोज-परिणामों का उपयोग करने को कहना, जो सबसे विश्वसनीय हैं","नकल की अनुमति देना जब तक विद्यार्थी अंत में वेबसाइट की कड़ी चिपका दें"],"explanationHi":"सूचना-साक्षरता का अर्थ है स्रोतों का अधिकार, सामयिकता, साक्ष्य और पुष्टि के लिए मूल्यांकन करना। इंटरनेट पर रोक या शीर्ष परिणामों तक सीमित करना यह कौशल नहीं बनाता, और कड़ी के साथ नकल करना भी साहित्यिक चोरी है।"},
  {"id":"cdp-pedagogy-subjects-1205","question":"Consider the following statements about using digital resources in a Class VII project: 1. Students should acknowledge the sources of text and images they use. 2. Any image found online can be freely used in any way, because it is on the internet. 3. Openly licensed resources (for example Creative Commons) can be reused within their stated conditions. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 and 3 only"],"answer":3,"explanation":"Being online does not make content free to use; copyright still applies unless a licence allows reuse. Teaching attribution and open licences builds ethical digital habits, so 1 and 3 are correct.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VII की परियोजना में डिजिटल संसाधनों के उपयोग के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. विद्यार्थियों को जिन पाठों और चित्रों का वे उपयोग करते हैं उनके स्रोतों को स्वीकार करना चाहिए। 2. ऑनलाइन मिला कोई भी चित्र किसी भी तरह स्वतंत्र रूप से उपयोग किया जा सकता है, क्योंकि वह इंटरनेट पर है। 3. खुले रूप से लाइसेंस प्राप्त संसाधनों (उदाहरण के लिए क्रिएटिव कॉमन्स) का उनकी बताई शर्तों के भीतर पुनः उपयोग किया जा सकता है। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","1, 2 और 3","केवल 1 और 3"],"explanationHi":"ऑनलाइन होने से सामग्री उपयोग के लिए मुक्त नहीं हो जाती; कॉपीराइट तब तक लागू रहता है जब तक लाइसेंस पुनः उपयोग की अनुमति न दे। श्रेय देना और खुले लाइसेंस सिखाना नैतिक डिजिटल आदतें बनाता है, इसलिए 1 और 3 सही हैं।"},
  {"id":"cdp-pedagogy-subjects-1206","question":"The head of a pre-primary school in Pune plans to give every four-year-old a tablet for one hour of learning apps each day, cutting outdoor and pretend play. What is the most appropriate professional advice?","options":["Support the plan, since early use of technology gives children a head start","Ban all screens completely, since technology has no place in early childhood","Support the plan, but extend tablet time to two hours for faster learning","Keep screen use short and adult-guided, and never let it replace active play"],"answer":3,"explanation":"Young children learn mainly through play, movement, talk and real objects, as NCF-FS 2022 stresses; screens can support this in small, mediated doses but should not replace it. A blanket ban ignores useful, guided uses.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"पुणे के एक पूर्व-प्राथमिक विद्यालय का प्रधानाध्यापक हर चार वर्षीय बच्चे को प्रतिदिन एक घंटे के अधिगम-ऐप के लिए एक टैबलेट देने की योजना बनाता है, जिससे बाहरी और अभिनय-खेल कम हो जाएँगे। सबसे उपयुक्त पेशेवर सलाह क्या है?","optionsHi":["योजना का समर्थन करना, क्योंकि प्रौद्योगिकी का प्रारंभिक उपयोग बच्चों को आगे की शुरुआत देता है","सभी स्क्रीन पूरी तरह प्रतिबंधित करना, क्योंकि प्रारंभिक बाल्यावस्था में प्रौद्योगिकी का कोई स्थान नहीं है","योजना का समर्थन करना, पर तेज़ अधिगम के लिए टैबलेट का समय दो घंटे तक बढ़ा देना","स्क्रीन का उपयोग छोटा और वयस्क-निर्देशित रखना, और उसे सक्रिय खेल की जगह कभी न लेने देना"],"explanationHi":"छोटे बच्चे मुख्यतः खेल, गति, बातचीत और वास्तविक वस्तुओं से सीखते हैं, जैसा NCF-FS 2022 बल देती है; स्क्रीन छोटी, मध्यस्थता वाली मात्रा में इसका समर्थन कर सकती हैं पर उसकी जगह नहीं लेनी चाहिए। पूर्ण प्रतिबंध उपयोगी, निर्देशित उपयोगों की उपेक्षा करता है।"},
  {"id":"cdp-pedagogy-subjects-1207","question":"Consider the following statements about the DIKSHA platform: 1. QR codes printed in many textbooks link to related digital content on DIKSHA. 2. DIKSHA is meant only for students and has no material for teachers. 3. Content on DIKSHA is available in several Indian languages. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"DIKSHA was launched as a national platform for teachers and later expanded to students, with QR-coded 'energised' textbooks and multilingual content. Statement 2 is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"DIKSHA प्लेटफ़ॉर्म के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. कई पाठ्यपुस्तकों में छपे QR कोड DIKSHA पर संबंधित डिजिटल सामग्री से जुड़ते हैं। 2. DIKSHA केवल विद्यार्थियों के लिए है और इसमें शिक्षकों के लिए कोई सामग्री नहीं है। 3. DIKSHA पर सामग्री कई भारतीय भाषाओं में उपलब्ध है। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"DIKSHA शिक्षकों के लिए एक राष्ट्रीय प्लेटफ़ॉर्म के रूप में आरंभ हुआ और बाद में विद्यार्थियों तक विस्तृत हुआ, QR-कोड वाली 'ऊर्जित' पाठ्यपुस्तकों और बहुभाषी सामग्री के साथ। कथन 2 असत्य है।"},
  {"id":"cdp-pedagogy-subjects-1208","question":"Match each learner with the assistive technology most suited to his or her need. P. Sanya, who is blind; Q. Vikram, who has dyslexia and reads very slowly; R. Moin, who has limited hand movement due to cerebral palsy; S. Elsa, who has a severe hearing impairment. Technologies: 1. Captioned videos; 2. Screen reader software; 3. Text-to-speech and audiobooks; 4. Speech-to-text or adapted switches.","options":["P-3, Q-2, R-4, S-1","P-2, Q-3, R-1, S-4","P-2, Q-3, R-4, S-1","P-2, Q-4, R-3, S-1"],"answer":2,"explanation":"A screen reader turns on-screen text into speech or braille for a blind user; text-to-speech and audiobooks reduce the decoding load in dyslexia; speech-to-text or switches replace fine hand movements; captions give access to spoken content for a deaf learner.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"प्रत्येक अधिगमकर्ता को उसकी आवश्यकता के सबसे उपयुक्त सहायक प्रौद्योगिकी से मिलाइए। P. सान्या, जो दृष्टिहीन है; Q. विक्रम, जिसे डिस्लेक्सिया है और जो बहुत धीरे पढ़ता है; R. मोइन, जिसकी प्रमस्तिष्क पक्षाघात के कारण हाथ की गति सीमित है; S. एल्सा, जिसे गंभीर श्रवण-बाधा है। प्रौद्योगिकियाँ: 1. उपशीर्षक (कैप्शन) वाले वीडियो; 2. स्क्रीन रीडर सॉफ़्टवेयर; 3. टेक्स्ट-टू-स्पीच और ऑडियोबुक; 4. स्पीच-टू-टेक्स्ट या अनुकूलित स्विच।","optionsHi":["P-3, Q-2, R-4, S-1","P-2, Q-3, R-1, S-4","P-2, Q-3, R-4, S-1","P-2, Q-4, R-3, S-1"],"explanationHi":"स्क्रीन रीडर दृष्टिहीन उपयोगकर्ता के लिए स्क्रीन के पाठ को वाणी या ब्रेल में बदलता है; टेक्स्ट-टू-स्पीच और ऑडियोबुक डिस्लेक्सिया में विकोडन का भार घटाते हैं; स्पीच-टू-टेक्स्ट या स्विच हाथ की सूक्ष्म गतियों की जगह लेते हैं; उपशीर्षक बधिर अधिगमकर्ता को बोली गई सामग्री तक पहुँच देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1209","question":"A Class IX teacher asks students to watch a short video on photosynthesis at home and uses the class period for experiments, problem-solving and clearing doubts. Which statement about this 'flipped classroom' is most accurate?","options":["Its main benefit is that teachers no longer need to plan their lessons in detail","It frees class time for active work, but fails if students lack video access","It works only for students who already know the topic before the class","It means students teach themselves entirely, with no role for the teacher"],"answer":1,"explanation":"Flipping reserves class time for application and interaction, where the teacher's help matters most. It depends on access and on students actually viewing the material, so planning for equity is essential.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा IX की एक शिक्षिका विद्यार्थियों से घर पर प्रकाश-संश्लेषण पर एक छोटा वीडियो देखने को कहती है और कक्षा के कालांश का उपयोग प्रयोगों, समस्या-समाधान और शंकाओं के निवारण के लिए करती है। इस 'फ़्लिप्ड कक्षा' के बारे में कौन-सा कथन सबसे सटीक है?","optionsHi":["इसका मुख्य लाभ यह है कि शिक्षकों को अब अपने पाठों की विस्तृत योजना बनाने की आवश्यकता नहीं रहती","यह कक्षा का समय सक्रिय कार्य के लिए मुक्त करता है, पर यदि विद्यार्थियों के पास वीडियो की पहुँच न हो तो विफल हो जाता है","यह केवल उन विद्यार्थियों के लिए कारगर है जो कक्षा से पहले विषय को पहले से जानते हैं","इसका अर्थ है कि विद्यार्थी पूरी तरह स्वयं सीखते हैं, शिक्षक की कोई भूमिका नहीं"],"explanationHi":"फ़्लिपिंग कक्षा का समय अनुप्रयोग और अंतःक्रिया के लिए आरक्षित करती है, जहाँ शिक्षक की मदद सबसे अधिक मायने रखती है। यह पहुँच पर और विद्यार्थियों के वास्तव में सामग्री देखने पर निर्भर करती है, इसलिए समता की योजना आवश्यक है।"},
  {"id":"cdp-pedagogy-subjects-1210","question":"A Class VI teacher runs a short online quiz at the end of a lesson, and the dashboard shows that 70% of students chose the same wrong option on question 3. What is the best use of this information?","options":["Re-teach the idea, targeting the misconception that the wrong option reveals","Ignore it, since this quick quiz does not count towards the term marks at all","Remove question 3 from future quizzes, since it was clearly too difficult for them","Report the scores to parents as the term result for each child"],"answer":0,"explanation":"Instant data is valuable formative assessment: a popular wrong option points to a shared misconception, which should shape the next lesson. Ignoring or deleting it wastes the evidence.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VI की एक शिक्षिका पाठ के अंत में एक छोटी ऑनलाइन प्रश्नोत्तरी कराती है, और डैशबोर्ड दिखाता है कि 70% विद्यार्थियों ने प्रश्न 3 पर एक ही गलत विकल्प चुना। इस जानकारी का सबसे अच्छा उपयोग क्या है?","optionsHi":["विचार को दोबारा पढ़ाना, उस भ्रांति को लक्षित करते हुए जो गलत विकल्प प्रकट करता है","इसकी उपेक्षा करना, क्योंकि यह त्वरित प्रश्नोत्तरी सत्र के अंकों में बिल्कुल नहीं गिनी जाती","भविष्य की प्रश्नोत्तरियों से प्रश्न 3 हटा देना, क्योंकि वह स्पष्टतः उनके लिए बहुत कठिन था","प्रत्येक बच्चे के सत्र-परिणाम के रूप में अंक अभिभावकों को बताना"],"explanationHi":"तुरंत मिला आँकड़ा मूल्यवान रचनात्मक आकलन है: लोकप्रिय गलत विकल्प साझा भ्रांति की ओर इशारा करता है, जिसे अगले पाठ को आकार देना चाहिए। इसकी उपेक्षा या इसे हटाना साक्ष्य को व्यर्थ करता है।"},
  {"id":"cdp-pedagogy-subjects-1211","question":"Assertion (A): Adding more technology to a lesson automatically improves students' learning. Reason (R): The effect of technology on learning depends on how it is used to support pedagogy and content.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Technology is a tool; learning depends on the pedagogical design around it. R is true, and it explains why more technology does not by itself guarantee better learning.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"अभिकथन (A): किसी पाठ में अधिक प्रौद्योगिकी जोड़ने से विद्यार्थियों का अधिगम स्वतः सुधरता है। कारण (R): अधिगम पर प्रौद्योगिकी का प्रभाव इस पर निर्भर करता है कि उसका उपयोग शिक्षणशास्त्र और विषय-वस्तु का समर्थन करने के लिए कैसे किया जाता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"प्रौद्योगिकी एक साधन है; अधिगम उसके चारों ओर की शिक्षणशास्त्रीय रचना पर निर्भर करता है। R सत्य है, और यह समझाता है कि अधिक प्रौद्योगिकी अपने आप बेहतर अधिगम की गारंटी क्यों नहीं देती।"},
  {"id":"cdp-pedagogy-subjects-1212","question":"A Class VII teacher has students enter two months of daily temperature data into a spreadsheet and produce line graphs, and then spends most of the period on discussing patterns. Which statement best evaluates this?","options":["It is wrong, since students must always draw every graph by hand, without exception","It is good only because it saves the teacher time in checking students' graphs","It moves time from plotting to interpreting, though graph-building must be learnt too","It is suitable only for computer classes, not for mathematics or science periods"],"answer":2,"explanation":"Spreadsheets handle repetitive plotting so that time goes to interpretation, which is the higher-level goal. Students still need to know how scales and axes work so the tool does not become a black box.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VII की एक शिक्षिका विद्यार्थियों से दो महीने के दैनिक तापमान के आँकड़े स्प्रेडशीट में डलवाती है और रेखा-आलेख बनवाती है, फिर कालांश का अधिकांश समय प्रतिरूपों पर चर्चा में बिताती है। इसका सबसे अच्छा मूल्यांकन क्या है?","optionsHi":["यह गलत है, क्योंकि विद्यार्थियों को हमेशा हर आलेख हाथ से बनाना चाहिए, बिना किसी अपवाद के","यह केवल इसलिए अच्छा है कि इससे शिक्षिका का विद्यार्थियों के आलेख जाँचने का समय बचता है","यह समय को आलेख बनाने से व्याख्या की ओर ले जाता है, यद्यपि आलेख बनाना भी सीखना चाहिए","यह केवल कंप्यूटर कक्षाओं के लिए उपयुक्त है, गणित या विज्ञान के कालांशों के लिए नहीं"],"explanationHi":"स्प्रेडशीट दोहराव वाले आलेखन को सँभालती है ताकि समय व्याख्या में लगे, जो उच्च-स्तरीय लक्ष्य है। विद्यार्थियों को फिर भी जानना चाहिए कि पैमाने और अक्ष कैसे काम करते हैं ताकि साधन एक काली पेटी न बन जाए।"},
  {"id":"cdp-pedagogy-subjects-1213","question":"A Class VIII teacher plays a 40-minute documentary on the Indian freedom struggle without any pause, and then begins the next topic. How could she best use this video?","options":["Show the whole video twice in a row so that students remember more of it","Show short segments with a clear purpose, pause for questions, then discuss","Ask students to copy notes from the video while it plays, for revision","Play the video only on days when she is absent, to keep the class busy"],"answer":1,"explanation":"Video supports learning when it is purposeful, chunked and followed by discussion; continuous passive viewing leads to low retention. Note-copying while watching splits attention.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VIII की एक शिक्षिका भारतीय स्वतंत्रता संग्राम पर 40 मिनट की वृत्तचित्र फ़िल्म बिना रोके चलाती है, और फिर अगला विषय शुरू करती है। वह इस वीडियो का सबसे अच्छा उपयोग कैसे कर सकती थी?","optionsHi":["पूरा वीडियो लगातार दो बार दिखाना ताकि विद्यार्थी उसका अधिक भाग याद रखें","स्पष्ट उद्देश्य के साथ छोटे खंड दिखाना, प्रश्नों के लिए रुकना, फिर चर्चा करना","विद्यार्थियों से वीडियो चलते समय पुनरावृत्ति के लिए नोट्स उतारने को कहना","वीडियो केवल उन दिनों चलाना जब वह अनुपस्थित हो, ताकि कक्षा व्यस्त रहे"],"explanationHi":"वीडियो तब अधिगम में सहायक होता है जब वह उद्देश्यपूर्ण, खंडों में बँटा हो और उसके बाद चर्चा हो; लगातार निष्क्रिय देखना कम धारण की ओर ले जाता है। देखते समय नोट्स उतारना ध्यान को बाँट देता है।"},
  {"id":"cdp-pedagogy-subjects-1214","question":"In a Class I classroom in a Santhali-speaking area, the teacher uses a low-cost device to play recorded folk stories in Santhali and later in the regional language, with children retelling and acting them. Which statement best supports this practice?","options":["Recorded stories in the home language are useful only for entertainment","ICT should be used only in English, since it is the language of technology","Audio devices are not suitable for children below Class V, who need a teacher","ICT can help bridge home and school languages when followed by talk and activity"],"answer":3,"explanation":"Familiar-language audio stories build listening comprehension and oral language, and the follow-up retelling makes it active. Technology serves multilingual education here rather than displacing the home language.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"संथाली-भाषी क्षेत्र की कक्षा I में शिक्षक एक कम लागत वाले उपकरण का उपयोग करके संथाली में और बाद में क्षेत्रीय भाषा में रिकॉर्ड की गई लोक-कहानियाँ चलाता है, और बच्चे उन्हें फिर से सुनाते और अभिनय करते हैं। इस प्रथा का सबसे अच्छा समर्थन कौन-सा कथन करता है?","optionsHi":["घर की भाषा में रिकॉर्ड की गई कहानियाँ केवल मनोरंजन के लिए उपयोगी हैं","ICT का उपयोग केवल अंग्रेज़ी में होना चाहिए, क्योंकि वह प्रौद्योगिकी की भाषा है","ऑडियो उपकरण कक्षा V से नीचे के बच्चों के लिए उपयुक्त नहीं हैं, जिन्हें शिक्षक चाहिए","ICT घर और विद्यालय की भाषाओं के बीच सेतु बनाने में मदद कर सकता है, जब उसके बाद बातचीत और गतिविधि हो"],"explanationHi":"परिचित भाषा की ऑडियो कहानियाँ श्रवण-बोध और मौखिक भाषा बनाती हैं, और बाद में पुनः सुनाना उसे सक्रिय बनाता है। यहाँ प्रौद्योगिकी घर की भाषा को विस्थापित करने के बजाय बहुभाषी शिक्षा की सेवा करती है।"},
  {"id":"cdp-pedagogy-subjects-1215","question":"Several Class VIII students have been mocking a classmate in a class WhatsApp group with edited photos. The classmate has stopped coming to school. What is the most appropriate response?","options":["Treat it as cyberbullying, support the victim and act under school policy","Ignore it, since it happened in a private group outside school hours and premises","Advise the victim to leave the WhatsApp group and simply ignore the messages","Ban the whole class from using phones and WhatsApp for the rest of the year"],"answer":0,"explanation":"Cyberbullying affects safety and attendance at school, so the school must respond: protect the victim, hold perpetrators accountable and build digital citizenship. Telling the victim to leave or a blanket ban does not address the behaviour.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VIII के कई विद्यार्थी कक्षा के WhatsApp समूह में संपादित तस्वीरों के साथ एक सहपाठी का मज़ाक उड़ाते रहे हैं। उस सहपाठी ने विद्यालय आना बंद कर दिया है। सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["इसे साइबर-धमकी (cyberbullying) मानना, पीड़ित का समर्थन करना और विद्यालय की नीति के अंतर्गत कार्रवाई करना","इसकी उपेक्षा करना, क्योंकि यह विद्यालय के समय और परिसर के बाहर एक निजी समूह में हुआ","पीड़ित को सलाह देना कि वह WhatsApp समूह छोड़ दे और संदेशों की बस उपेक्षा करे","पूरी कक्षा को शेष वर्ष के लिए फ़ोन और WhatsApp के उपयोग से प्रतिबंधित करना"],"explanationHi":"साइबर-धमकी विद्यालय में सुरक्षा और उपस्थिति को प्रभावित करती है, इसलिए विद्यालय को प्रतिक्रिया देनी चाहिए: पीड़ित की रक्षा, दोषियों को उत्तरदायी ठहराना और डिजिटल नागरिकता बनाना। पीड़ित को छोड़ने को कहना या पूर्ण प्रतिबंध व्यवहार को संबोधित नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-1216","question":"A Class III teacher uses a game-based app in which children answer addition facts quickly to earn stars. Which use of the app is most appropriate?","options":["Use the app instead of teaching the concept of addition with real objects","Use the app as the only maths activity every day, since children enjoy it","Use it for fluency practice after the concept is built with objects","Avoid it, since games have no place in a serious mathematics lesson"],"answer":2,"explanation":"Drill apps help with fluency and motivation, but cannot build the underlying concept, which needs concrete experience and talk. They work as a supplement, not a replacement.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा III की एक शिक्षिका खेल-आधारित ऐप का उपयोग करती है जिसमें बच्चे सितारे पाने के लिए जोड़ के तथ्यों का तेज़ी से उत्तर देते हैं। ऐप का कौन-सा उपयोग सबसे उपयुक्त है?","optionsHi":["वास्तविक वस्तुओं से जोड़ की संकल्पना सिखाने के स्थान पर ऐप का उपयोग करना","ऐप को हर दिन एकमात्र गणित-गतिविधि के रूप में उपयोग करना, क्योंकि बच्चों को वह पसंद है","वस्तुओं से संकल्पना बन जाने के बाद प्रवाह के अभ्यास के लिए उसका उपयोग करना","उससे बचना, क्योंकि गंभीर गणित के पाठ में खेलों का कोई स्थान नहीं है"],"explanationHi":"अभ्यास-ऐप प्रवाह और प्रेरणा में मदद करते हैं, पर अंतर्निहित संकल्पना नहीं बना सकते, जिसके लिए मूर्त अनुभव और बातचीत चाहिए। वे पूरक के रूप में कारगर हैं, विकल्प के रूप में नहीं।"},
  {"id":"cdp-pedagogy-subjects-1217","question":"A Class VI teacher is choosing a free learning app for fractions. Which set of criteria is most important?","options":["The app has bright colours, many advertisements and the most downloads in its category","It fits the outcome, needs real thinking, uses a familiar language and protects data","The app has the most levels and rewards, regardless of what content it teaches","The app is in English only, so that children improve their English along with maths"],"answer":1,"explanation":"Educational value (alignment, interactivity), accessibility (language) and safety (data privacy, no inappropriate ads) matter most. Popularity and rewards are not evidence of learning.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VI की एक शिक्षिका भिन्नों के लिए कोई निःशुल्क अधिगम-ऐप चुन रही है। कौन-सा मानदंड-समूह सबसे महत्त्वपूर्ण है?","optionsHi":["ऐप में चटक रंग, कई विज्ञापन और अपनी श्रेणी में सबसे अधिक डाउनलोड हों","वह परिणाम के अनुरूप हो, वास्तविक चिंतन माँगे, परिचित भाषा उपयोग करे और डेटा की रक्षा करे","ऐप में सबसे अधिक स्तर और पुरस्कार हों, चाहे वह कौन-सी विषय-वस्तु सिखाता हो","ऐप केवल अंग्रेज़ी में हो, ताकि बच्चे गणित के साथ अपनी अंग्रेज़ी सुधारें"],"explanationHi":"शैक्षिक मूल्य (अनुरूपता, अंतःक्रियात्मकता), सुगम्यता (भाषा) और सुरक्षा (डेटा-गोपनीयता, अनुचित विज्ञापन न हों) सबसे अधिक मायने रखते हैं। लोकप्रियता और पुरस्कार अधिगम के साक्ष्य नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-1218","question":"In a hill village of Uttarakhand with no internet but electricity and a TV in the school, which ICT choice is most appropriate for supporting learning?","options":["Postpone all ICT use until high-speed internet finally reaches the village school","Ask students to travel to the nearest town for online classes on weekends","Use educational TV, radio and offline content, followed by discussion","Use only the school's mobile data for live streaming of city classrooms"],"answer":2,"explanation":"ICT is broader than the internet; broadcast and offline media can bring good content to low-connectivity areas, and teacher-led follow-up makes it active learning. Waiting or demanding travel denies access.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"उत्तराखंड के एक पहाड़ी गाँव में, जहाँ इंटरनेट नहीं है पर बिजली और विद्यालय में टीवी है, अधिगम का समर्थन करने के लिए कौन-सा ICT विकल्प सबसे उपयुक्त है?","optionsHi":["सभी ICT उपयोग तब तक स्थगित करना जब तक तेज़ गति का इंटरनेट विद्यालय तक न पहुँच जाए","विद्यार्थियों से सप्ताहांत में ऑनलाइन कक्षाओं के लिए निकटतम कस्बे की यात्रा करने को कहना","शैक्षिक टीवी, रेडियो और ऑफ़लाइन सामग्री का उपयोग करना, उसके बाद चर्चा","शहरी कक्षाओं की लाइव स्ट्रीमिंग के लिए केवल विद्यालय के मोबाइल डेटा का उपयोग करना"],"explanationHi":"ICT इंटरनेट से व्यापक है; प्रसारण और ऑफ़लाइन माध्यम कम-संपर्क वाले क्षेत्रों में अच्छी सामग्री ला सकते हैं, और शिक्षक-निर्देशित अनुवर्तन इसे सक्रिय अधिगम बनाता है। प्रतीक्षा करना या यात्रा की माँग करना पहुँच से वंचित करता है।"},
  {"id":"cdp-pedagogy-subjects-1219","question":"Class V students create a short digital story with their own drawings, recorded narration and background sounds about a local festival. Which set of learnings does this mainly develop?","options":["Typing speed alone, since the whole story has to be entered on a computer","Recall of textbook facts alone, since festivals are covered in the EVS book","Language, sequencing, creativity and digital skills, rooted in their culture","Drawing skills alone, since all the rest is done automatically by the software"],"answer":2,"explanation":"Digital storytelling integrates language, planning, art and technology, with children as creators rather than consumers. It is a good example of ICT used for expression.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा V के विद्यार्थी स्थानीय त्योहार के बारे में अपने चित्रों, रिकॉर्ड की गई कथा-वाचन और पृष्ठभूमि ध्वनियों के साथ एक छोटी डिजिटल कहानी बनाते हैं। यह मुख्यतः किन अधिगमों का विकास करता है?","optionsHi":["केवल टाइपिंग की गति, क्योंकि पूरी कहानी कंप्यूटर पर दर्ज करनी होती है","केवल पाठ्यपुस्तक के तथ्यों का स्मरण, क्योंकि त्योहार EVS की पुस्तक में आते हैं","भाषा, क्रमबद्धता, रचनात्मकता और डिजिटल कौशल, उनकी संस्कृति में निहित","केवल चित्रकला-कौशल, क्योंकि बाकी सब सॉफ़्टवेयर स्वतः कर देता है"],"explanationHi":"डिजिटल कथा-वाचन भाषा, योजना, कला और प्रौद्योगिकी को जोड़ता है, जिसमें बच्चे उपभोक्ता नहीं, रचयिता होते हैं। यह अभिव्यक्ति के लिए ICT के उपयोग का अच्छा उदाहरण है।"},
  {"id":"cdp-pedagogy-subjects-1220","question":"A teacher posts photographs of her Class IV students on public social media with their full names and their test marks, to show parents the class's progress. What is the most accurate evaluation?","options":["It is acceptable, since parents like to see their children's progress online","It is acceptable as long as only the toppers' names and marks are posted online","It is acceptable, since the children's faces are already known in the town","It violates children's privacy; names and marks should never be posted publicly"],"answer":3,"explanation":"Publicly linking identities with marks can shame children and exposes personal data. Responsible ICT use protects children's privacy and needs consent; posting only toppers adds comparison and humiliation.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"एक शिक्षिका माता-पिता को कक्षा की प्रगति दिखाने के लिए अपनी कक्षा IV के विद्यार्थियों की तस्वीरें उनके पूरे नाम और परीक्षा-अंकों के साथ सार्वजनिक सोशल मीडिया पर डालती है। सबसे सटीक मूल्यांकन क्या है?","optionsHi":["यह स्वीकार्य है, क्योंकि माता-पिता अपने बच्चों की प्रगति ऑनलाइन देखना पसंद करते हैं","यह तब तक स्वीकार्य है जब तक केवल टॉपरों के नाम और अंक ऑनलाइन डाले जाएँ","यह स्वीकार्य है, क्योंकि बच्चों के चेहरे कस्बे में पहले से जाने-पहचाने हैं","यह बच्चों की गोपनीयता का उल्लंघन है; नाम और अंक कभी सार्वजनिक रूप से नहीं डालने चाहिए"],"explanationHi":"पहचान को अंकों से सार्वजनिक रूप से जोड़ना बच्चों को लज्जित कर सकता है और व्यक्तिगत डेटा उजागर करता है। ज़िम्मेदार ICT उपयोग बच्चों की गोपनीयता की रक्षा करता है और सहमति माँगता है; केवल टॉपरों को डालने से तुलना और अपमान जुड़ता है।"},
  {"id":"cdp-pedagogy-subjects-1221","question":"A Class VI teacher uses a word processor so that students can type essays (P); then she switches on spell-check and a thesaurus to help them revise (Q); later students turn essays into hyperlinked multimedia presentations with audio for a new audience (R). In the SAMR model, P, Q and R are respectively:","options":["Substitution, Augmentation, Modification","Augmentation, Substitution, Redefinition","Substitution, Modification, Augmentation","Substitution, Augmentation, Redefinition"],"answer":0,"explanation":"Typing replaces handwriting with no functional change (Substitution); spell-check adds a functional improvement (Augmentation); redesigning the task as multimedia changes it significantly (Modification). Redefinition would need a task impossible without technology, such as live collaboration with a distant audience.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VI की एक शिक्षिका वर्ड प्रोसेसर का उपयोग करती है ताकि विद्यार्थी निबंध टाइप कर सकें (P); फिर वह संशोधन में मदद के लिए वर्तनी-जाँच और पर्याय-कोश चालू करती है (Q); बाद में विद्यार्थी निबंधों को नए श्रोताओं के लिए ऑडियो सहित हाइपरलिंक वाली बहुमाध्यम प्रस्तुतियों में बदलते हैं (R)। SAMR मॉडल में P, Q और R क्रमशः हैं:","optionsHi":["प्रतिस्थापन, संवर्धन, संशोधन","संवर्धन, प्रतिस्थापन, पुनर्परिभाषा","प्रतिस्थापन, संशोधन, संवर्धन","प्रतिस्थापन, संवर्धन, पुनर्परिभाषा"],"explanationHi":"टाइपिंग हस्तलेखन की जगह लेती है बिना किसी प्रकार्यात्मक परिवर्तन के (प्रतिस्थापन); वर्तनी-जाँच प्रकार्यात्मक सुधार जोड़ती है (संवर्धन); कार्य को बहुमाध्यम के रूप में पुनः डिज़ाइन करना उसे महत्त्वपूर्ण रूप से बदलता है (संशोधन)। पुनर्परिभाषा के लिए प्रौद्योगिकी के बिना असंभव कार्य चाहिए, जैसे दूर के श्रोताओं के साथ लाइव सहयोग।"},
  {"id":"cdp-pedagogy-subjects-1222","question":"Consider the following statements about ICT in the classroom: 1. Technology can help teachers reach diverse learners through multiple formats such as audio, video and text. 2. Technology removes the need for teacher planning and judgement. 3. Using ICT without attention to access can widen the gap between advantaged and disadvantaged students. Which of these are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"ICT supports multiple means of representation and can be inclusive, but it still depends on the teacher's planning; unequal access can deepen inequality. Statement 2 is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा में ICT के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. प्रौद्योगिकी ऑडियो, वीडियो और पाठ जैसे अनेक रूपों के माध्यम से शिक्षकों को विविध अधिगमकर्ताओं तक पहुँचने में मदद कर सकती है। 2. प्रौद्योगिकी शिक्षक की योजना और विवेक की आवश्यकता को समाप्त कर देती है। 3. पहुँच पर ध्यान दिए बिना ICT का उपयोग सुविधासंपन्न और वंचित विद्यार्थियों के बीच की खाई को बढ़ा सकता है। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"ICT प्रस्तुति के अनेक साधनों का समर्थन करता है और समावेशी हो सकता है, पर वह फिर भी शिक्षक की योजना पर निर्भर करता है; असमान पहुँच असमानता को गहरा सकती है। कथन 2 असत्य है।"},
  {"id":"cdp-pedagogy-subjects-1223","question":"Class 5 children listen to a recorded railway announcement only to find out the platform number of the Rajdhani Express. The listening sub-skill being practised is:","options":["Listening for the gist of the whole announcement","Listening for specific information","Inferring the speaker’s attitude from intonation","Discriminating between similar sounds"],"answer":1,"explanation":"Listening for one particular detail while ignoring the rest is listening for specific information, the listening counterpart of scanning. Gist means the overall idea.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"कक्षा 5 के बच्चे रेलवे की रिकॉर्ड की गई उद्घोषणा केवल यह जानने के लिए सुनते हैं कि राजधानी एक्सप्रेस का प्लेटफ़ॉर्म नंबर क्या है। जिस श्रवण-उप-कौशल का अभ्यास हो रहा है वह है:","optionsHi":["पूरी उद्घोषणा के सार के लिए सुनना","विशिष्ट जानकारी के लिए सुनना","स्वर-अनुतान से वक्ता के रुख का अनुमान लगाना","समान ध्वनियों के बीच भेद करना"],"explanationHi":"शेष की उपेक्षा करते हुए किसी विशेष विवरण के लिए सुनना विशिष्ट जानकारी के लिए सुनना है, जो स्कैनिंग का श्रवण-समकक्ष है। सार का अर्थ है समग्र विचार।"},
  {"id":"cdp-pedagogy-subjects-1224","question":"A teacher plays an audio story once and asks only, ‘Who are the main characters and what is the problem?’ She then plays it again with five detailed questions. The best justification for this staging is that:","options":["Children forget stories quickly, so every recording must always be played exactly twice","Detailed questions are always easier than general ones, so they should come second","Listening first for gist and then for detail avoids overload and builds understanding","It mainly gives the teacher time to prepare the next activity while the audio plays"],"answer":2,"explanation":"Staged tasks let learners build an overall framework first and then attend to details; asking for everything at once overloads working memory during real-time listening.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"एक शिक्षिका एक ऑडियो कहानी एक बार चलाती है और केवल पूछती है, 'मुख्य पात्र कौन हैं और समस्या क्या है?' फिर वह उसे पाँच विस्तृत प्रश्नों के साथ दोबारा चलाती है। इस चरणबद्धता का सबसे अच्छा औचित्य है कि:","optionsHi":["बच्चे कहानियाँ जल्दी भूल जाते हैं, इसलिए हर रिकॉर्डिंग हमेशा ठीक दो बार चलानी चाहिए","विस्तृत प्रश्न हमेशा सामान्य प्रश्नों से आसान होते हैं, इसलिए उन्हें बाद में आना चाहिए","पहले सार के लिए और फिर विवरण के लिए सुनना अतिभार से बचाता है और समझ बनाता है","यह मुख्यतः शिक्षिका को ऑडियो चलते समय अगली गतिविधि तैयार करने का समय देता है"],"explanationHi":"चरणबद्ध कार्य अधिगमकर्ताओं को पहले समग्र रूपरेखा बनाने और फिर विवरणों पर ध्यान देने देते हैं; सब कुछ एक साथ माँगना वास्तविक समय के श्रवण में कार्यकारी स्मृति पर अतिभार डालता है।"},
  {"id":"cdp-pedagogy-subjects-1225","question":"A Class 8 student understands every word when the teacher speaks slowly, but loses track in natural speech, where ‘What do you want to do?’ sounds like ‘Whaddya wanna do?’. The most useful help is practice with:","options":["Reading the transcript silently before every listening task begins","Listening only to slow, carefully read recordings until he is completely ready","Memorising the spellings of all the words used in each recording","Features of connected speech such as linking, weak forms and elision"],"answer":3,"explanation":"His word knowledge is fine; his bottom-up decoding of fast connected speech is the problem. Raising awareness of how words merge and reduce helps him segment natural speech.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 8 का एक विद्यार्थी हर शब्द तब समझता है जब शिक्षक धीरे बोलता है, पर स्वाभाविक बोली में भटक जाता है, जहाँ ‘What do you want to do?’ ‘Whaddya wanna do?’ जैसा सुनाई देता है। सबसे उपयोगी मदद किस अभ्यास की है:","optionsHi":["हर श्रवण-कार्य शुरू होने से पहले प्रतिलेख (transcript) को चुपचाप पढ़ने की","केवल धीमी, सावधानी से पढ़ी गई रिकॉर्डिंग सुनने की जब तक वह पूरी तरह तैयार न हो","प्रत्येक रिकॉर्डिंग में प्रयुक्त सभी शब्दों की वर्तनी याद करने की","जुड़ी हुई बोली की विशेषताओं की, जैसे संयोजन (linking), दुर्बल रूप (weak forms) और लोप (elision)"],"explanationHi":"उसका शब्द-ज्ञान ठीक है; समस्या तेज़, जुड़ी हुई बोली के उसके निम्न-से-उच्च विकोडन (bottom-up decoding) की है। शब्द कैसे मिलते और घटते हैं, इसकी जागरूकता बढ़ाने से वह स्वाभाविक बोली को खंडों में बाँट पाता है।"},
  {"id":"cdp-pedagogy-subjects-1226","question":"To test listening comprehension, a Class 5 teacher plays a long recording once and asks children to write full-sentence answers to long questions while they listen. What is the main flaw in this test?","options":["The recording should have been in the mother tongue, since listening tests must avoid English","The heavy writing load contaminates the test, so it no longer measures just listening","Listening cannot be tested in a classroom at all, so only reading should be assessed","Children should first read the transcript, since unprepared listening is unfair"],"answer":1,"explanation":"A valid listening test should keep demands from other skills low, for example ticking, numbering or drawing. Here weak writers would score low even if they understood well.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"श्रवण-बोध की जाँच के लिए कक्षा 5 की एक शिक्षिका एक लंबी रिकॉर्डिंग एक बार चलाती है और बच्चों से सुनते समय लंबे प्रश्नों के पूर्ण-वाक्य उत्तर लिखने को कहती है। इस परीक्षण का मुख्य दोष क्या है?","optionsHi":["रिकॉर्डिंग मातृभाषा में होनी चाहिए थी, क्योंकि श्रवण परीक्षणों में अंग्रेज़ी से बचना चाहिए","लेखन का भारी भार परीक्षण को दूषित करता है, इसलिए वह केवल श्रवण को नहीं मापता","कक्षा में श्रवण की जाँच हो ही नहीं सकती, इसलिए केवल पठन का आकलन होना चाहिए","बच्चों को पहले प्रतिलेख पढ़ना चाहिए, क्योंकि बिना तैयारी का श्रवण अनुचित है"],"explanationHi":"वैध श्रवण परीक्षण में अन्य कौशलों की माँगें कम रखनी चाहिए, उदाहरण के लिए सही का निशान लगाना, क्रमांकन या चित्र बनाना। यहाँ कमज़ोर लेखक कम अंक पाते, भले ही उन्होंने अच्छी तरह समझा हो।"},
  {"id":"cdp-pedagogy-subjects-1227","question":"A teacher uses a short real radio cricket commentary in a Class 9 listening lesson instead of the scripted textbook dialogue. The best reason for this choice is that real recordings:","options":["Are always easier to follow than scripted ones, because the topic is familiar to students","Follow a strict grammatical sequence, so they fit the order of the English syllabus","Have natural speed, hesitations and overlaps that learners must cope with outside class","Remove the need for pre-listening work, because students already know about cricket"],"answer":2,"explanation":"Authentic listening prepares learners for real speech; with suitable tasks even demanding material becomes manageable, though it is not easier than scripted dialogue.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"एक शिक्षक कक्षा 9 के श्रवण पाठ में पटकथा-बद्ध पाठ्यपुस्तक संवाद के बजाय रेडियो पर क्रिकेट की एक छोटी असली कमेंट्री का उपयोग करता है। इस चयन का सबसे अच्छा कारण यह है कि असली रिकॉर्डिंग:","optionsHi":["पटकथा-बद्ध रिकॉर्डिंग से हमेशा अधिक सरल होती हैं, क्योंकि विषय विद्यार्थियों के लिए परिचित है","एक कठोर व्याकरणिक क्रम का पालन करती हैं, इसलिए अंग्रेज़ी पाठ्यक्रम के क्रम में बैठती हैं","स्वाभाविक गति, हिचकिचाहट और अतिव्यापन रखती हैं जिनसे अधिगमकर्ताओं को कक्षा के बाहर निपटना होता है","पूर्व-श्रवण कार्य की आवश्यकता समाप्त कर देती हैं, क्योंकि विद्यार्थी क्रिकेट के बारे में पहले से जानते हैं"],"explanationHi":"प्रामाणिक श्रवण अधिगमकर्ताओं को वास्तविक बोली के लिए तैयार करता है; उपयुक्त कार्यों के साथ कठिन सामग्री भी सँभालने योग्य बन जाती है, यद्यपि वह पटकथा-बद्ध संवाद से आसान नहीं होती।"},
  {"id":"cdp-pedagogy-subjects-1228","question":"Assertion (A): Children in Class 1 can understand stories read aloud that are well beyond the level they can read on their own. Reason (R): In the early years, listening comprehension usually runs well ahead of reading comprehension.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Young children are still learning to decode, so their understanding of spoken language is far ahead of what they can read; read-alouds use this gap to build vocabulary and comprehension.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"अभिकथन (A): कक्षा 1 के बच्चे ज़ोर से पढ़ी गई ऐसी कहानियाँ समझ सकते हैं जो उस स्तर से बहुत आगे हैं जिसे वे स्वयं पढ़ सकते हैं। कारण (R): प्रारंभिक वर्षों में श्रवण-बोध सामान्यतः पठन-बोध से काफ़ी आगे चलता है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"छोटे बच्चे अभी विकोडन सीख रहे होते हैं, इसलिए बोली गई भाषा की उनकी समझ उनके पढ़ने की क्षमता से बहुत आगे होती है; ज़ोर से पढ़कर सुनाना इस अंतर का उपयोग शब्दावली और बोध बनाने में करता है।"},
  {"id":"cdp-pedagogy-subjects-1229","question":"Which activity is mainly fluency-focused rather than accuracy-focused?","options":["A group discussion on banning homework, with no correction during it","Reading a set dialogue aloud with careful attention to intonation","Changing sentences orally from the present into the past tense","Repeating pairs of words such as ‘ship’ and ‘sheep’ after the teacher"],"answer":0,"explanation":"Fluency activities put meaning and the flow of communication first; the others focus on producing correct forms.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"कौन-सी गतिविधि मुख्यतः शुद्धता-केंद्रित के बजाय प्रवाह-केंद्रित है?","optionsHi":["गृहकार्य पर प्रतिबंध पर समूह-चर्चा, जिसके दौरान कोई सुधार नहीं","स्वर-अनुतान पर सावधानी से ध्यान देते हुए एक निर्धारित संवाद को ज़ोर से पढ़ना","वाक्यों को मौखिक रूप से वर्तमान काल से भूतकाल में बदलना","शिक्षक के बाद ‘ship’ और ‘sheep’ जैसे शब्द-युग्मों को दोहराना"],"explanationHi":"प्रवाह की गतिविधियाँ अर्थ और संप्रेषण के प्रवाह को पहले रखती हैं; अन्य सही रूप उत्पन्न करने पर केंद्रित हैं।"},
  {"id":"cdp-pedagogy-subjects-1230","question":"Many Class 6 students in a Bihar school say ‘wery’ for ‘very’ and ‘vest’ for ‘west’. Which activity most directly targets the problem?","options":["Writing each confused word ten times with the correct spelling","Reading a long passage aloud quickly, without stopping at all","Minimal-pair work: hearing and saying ‘vine–wine’, ‘vest–west’","Learning the dictionary meanings of the words they confuse"],"answer":2,"explanation":"The learners’ home languages do not separate /v/ and /w/, so they need to hear and produce the contrast. Minimal pairs isolate exactly that difference.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"बिहार के एक विद्यालय में कक्षा 6 के कई विद्यार्थी ‘very’ को ‘wery’ और ‘west’ को ‘vest’ कहते हैं। कौन-सी गतिविधि इस समस्या को सबसे सीधे लक्षित करती है?","optionsHi":["प्रत्येक भ्रमित शब्द को सही वर्तनी में दस बार लिखना","एक लंबा गद्यांश तेज़ी से ज़ोर से पढ़ना, बिल्कुल रुके बिना","न्यूनतम-युग्म (minimal-pair) कार्य: ‘vine–wine’, ‘vest–west’ सुनना और बोलना","जिन शब्दों को वे भ्रमित करते हैं उनके शब्दकोशीय अर्थ सीखना"],"explanationHi":"अधिगमकर्ताओं की घर की भाषाएँ /v/ और /w/ को अलग नहीं करतीं, इसलिए उन्हें यह अंतर सुनना और बोलना चाहिए। न्यूनतम युग्म ठीक उसी अंतर को अलग करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1231","question":"What is the most realistic goal for teaching English pronunciation to students in Indian schools?","options":["A British accent, since Received Pronunciation is the world standard","Clear, intelligible speech and confidence, not a foreign accent","An American accent, since it is the variety heard most in the media","No attention to pronunciation, since only writing is examined"],"answer":1,"explanation":"English is used worldwide in many varieties; the realistic aim is intelligibility to a wide range of listeners, with attention to the sounds and stress that affect understanding.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"भारतीय विद्यालयों में विद्यार्थियों को अंग्रेज़ी उच्चारण सिखाने का सबसे यथार्थवादी लक्ष्य क्या है?","optionsHi":["ब्रिटिश उच्चारण-शैली, क्योंकि रिसीव्ड प्रोनंसिएशन विश्व का मानक है","स्पष्ट, बोधगम्य वाणी और आत्मविश्वास, विदेशी उच्चारण-शैली नहीं","अमेरिकी उच्चारण-शैली, क्योंकि वह मीडिया में सबसे अधिक सुनी जाने वाली किस्म है","उच्चारण पर कोई ध्यान नहीं, क्योंकि केवल लेखन की परीक्षा होती है"],"explanationHi":"अंग्रेज़ी विश्व भर में अनेक किस्मों में उपयोग होती है; यथार्थवादी लक्ष्य श्रोताओं की विस्तृत श्रेणी के लिए बोधगम्यता है, उन ध्वनियों और बलाघात पर ध्यान देते हुए जो समझ को प्रभावित करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1232","question":"Class 7 students get role cards: the shopkeeper’s card lists prices and the lowest acceptable price; the customer’s card gives a budget and items needed. They then bargain. The main purpose of this role play is to:","options":["Check whether students can recall a model dialogue word for word","Teach the spellings of all the vegetables and fruits named on the role cards","Improve students’ handwriting as they note down prices and items","Practise language for a real-life function, with an information gap"],"answer":3,"explanation":"Role cards with different information give a reason to communicate, and bargaining practises the language of a real social function such as offering, refusing and persuading.","difficulty":"moderate","source":"CTET Paper II · State TETs","questionHi":"कक्षा 7 के विद्यार्थियों को भूमिका-कार्ड मिलते हैं: दुकानदार के कार्ड पर दाम और स्वीकार्य न्यूनतम दाम लिखे हैं; ग्राहक के कार्ड पर बजट और आवश्यक वस्तुएँ दी हैं। फिर वे मोल-भाव करते हैं। इस भूमिका-निर्वाह का मुख्य उद्देश्य है:","optionsHi":["यह जाँचना कि विद्यार्थी एक आदर्श संवाद शब्दशः याद कर सकते हैं या नहीं","भूमिका-कार्डों पर नामित सभी सब्ज़ियों और फलों की वर्तनी सिखाना","विद्यार्थियों की लिखावट सुधारना जब वे दाम और वस्तुएँ लिखते हैं","सूचना-अंतराल के साथ वास्तविक जीवन के प्रकार्य के लिए भाषा का अभ्यास करना"],"explanationHi":"भिन्न जानकारी वाले भूमिका-कार्ड संवाद करने का कारण देते हैं, और मोल-भाव प्रस्ताव देने, मना करने और राज़ी करने जैसे वास्तविक सामाजिक प्रकार्य की भाषा का अभ्यास कराता है।"},
  {"id":"cdp-pedagogy-subjects-1233","question":"When a teacher asks a question to the whole class, few children answer. She switches to ‘think–pair–share’: children think alone, discuss with a partner and then share with the class. The main reason this increases participation is that it:","options":["Gives children time to rehearse ideas and lowers the fear of speaking","Lets the teacher call only on the confident children who know the answer","Cuts down the amount of speaking that each child is expected to do","Shows children the correct answer before they are asked to speak"],"answer":0,"explanation":"Thinking time and a low-risk partner rehearsal reduce anxiety and give every child something to say, so more children are ready to speak in front of the class.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"जब एक शिक्षिका पूरी कक्षा से प्रश्न पूछती है, तो कुछ ही बच्चे उत्तर देते हैं। वह ‘सोचो–जोड़ी बनाओ–साझा करो’ पर आती है: बच्चे अकेले सोचते हैं, साथी के साथ चर्चा करते हैं और फिर कक्षा के साथ साझा करते हैं। इससे भागीदारी बढ़ने का मुख्य कारण यह है कि यह:","optionsHi":["बच्चों को विचारों का पूर्वाभ्यास करने का समय देता है और बोलने का भय कम करता है","शिक्षिका को केवल आत्मविश्वासी बच्चों को बुलाने देता है जो उत्तर जानते हैं","प्रत्येक बच्चे से बोलने की अपेक्षित मात्रा घटा देता है","बच्चों को बोलने के लिए कहे जाने से पहले उन्हें सही उत्तर दिखा देता है"],"explanationHi":"सोचने का समय और कम जोखिम वाला साथी-पूर्वाभ्यास चिंता घटाता है और हर बच्चे को कुछ कहने को देता है, इसलिए अधिक बच्चे कक्षा के सामने बोलने के लिए तैयार होते हैं।"},
  {"id":"cdp-pedagogy-subjects-1234","question":"A teacher asks, ‘Why do you think the old man gave away his land?’ and calls on a child within a second; if there is no answer she gives it herself. Research on wait time suggests that if she waits three to five seconds, the most likely result is:","options":["Students will lose interest and the pace of the whole lesson will suffer","Only the brightest few will answer, and the rest will stay silent","No change at all, since wait time affects only written answers","Longer, more thoughtful answers from more students willing to speak"],"answer":3,"explanation":"Mary Budd Rowe found that longer wait time after a question led to longer, better-reasoned answers and more participation, especially for higher-order questions like this one.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"एक शिक्षक पूछता है, ‘तुम्हें क्या लगता है बूढ़े आदमी ने अपनी ज़मीन क्यों दे दी?’ और एक सेकंड के भीतर किसी बच्चे को बुला लेता है; यदि उत्तर नहीं आता तो वह स्वयं दे देता है। प्रतीक्षा-समय पर शोध सुझाता है कि यदि वह तीन से पाँच सेकंड प्रतीक्षा करे, तो सबसे संभावित परिणाम होगा:","optionsHi":["विद्यार्थी रुचि खो देंगे और पूरे पाठ की गति प्रभावित होगी","केवल कुछ सबसे प्रतिभाशाली उत्तर देंगे, और बाकी चुप रहेंगे","कोई परिवर्तन नहीं, क्योंकि प्रतीक्षा-समय केवल लिखित उत्तरों को प्रभावित करता है","बोलने के लिए इच्छुक अधिक विद्यार्थियों से लंबे, अधिक विचारशील उत्तर"],"explanationHi":"मैरी बड रो ने पाया कि प्रश्न के बाद अधिक प्रतीक्षा-समय से लंबे, बेहतर तर्कयुक्त उत्तर और अधिक भागीदारी मिलती है, विशेषकर इस प्रकार के उच्च-स्तरीय प्रश्नों के लिए।"},
  {"id":"cdp-pedagogy-subjects-1235","question":"In a 40-minute Class 6 English period, the teacher talks for about 35 minutes, explaining the lesson in detail. From the point of view of language learning, the main problem is that:","options":["Any errors in the teacher’s English will be copied by all the students","The teacher will fall behind and fail to finish the syllabus on time","Students get almost no chance to use the language themselves","Such detailed explanations will be far too simple for the students"],"answer":2,"explanation":"Learners develop speaking through their own use of language; when teacher talk dominates, student talking time and opportunities for output almost disappear.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"कक्षा 6 के 40 मिनट के अंग्रेज़ी कालांश में शिक्षिका लगभग 35 मिनट बोलती है और पाठ को विस्तार से समझाती है। भाषा-अधिगम की दृष्टि से मुख्य समस्या यह है कि:","optionsHi":["शिक्षिका की अंग्रेज़ी की कोई भी त्रुटि सभी विद्यार्थी नकल कर लेंगे","शिक्षिका पिछड़ जाएगी और पाठ्यक्रम समय पर पूरा नहीं कर पाएगी","विद्यार्थियों को स्वयं भाषा का उपयोग करने का लगभग कोई अवसर नहीं मिलता","इतने विस्तृत स्पष्टीकरण विद्यार्थियों के लिए बहुत अधिक सरल होंगे"],"explanationHi":"अधिगमकर्ता अपनी भाषा-प्रयोग से बोलना विकसित करते हैं; जब शिक्षक की बातचीत हावी होती है, तो विद्यार्थियों के बोलने का समय और उत्पादन के अवसर लगभग समाप्त हो जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1236","question":"In a ‘show and tell’ session, each Class 1 child brings something from home, such as a toy or a photo, and talks about it to the class. The main value of this activity is that it:","options":["Builds confidence in speaking about familiar things to an audience","Teaches children the correct grammar of long and complex English sentences","Tests how well children can read difficult words from the board","Gives children practice in writing short paragraphs about objects"],"answer":0,"explanation":"Talking about something personal gives children content and motivation, links home and school, and develops speaking for an audience in a supportive setting.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"‘शो एंड टेल’ सत्र में कक्षा 1 का प्रत्येक बच्चा घर से कोई चीज़, जैसे खिलौना या फ़ोटो, लाता है और कक्षा के सामने उसके बारे में बात करता है। इस गतिविधि का मुख्य मूल्य यह है कि यह:","optionsHi":["श्रोताओं के सामने परिचित चीज़ों के बारे में बोलने का आत्मविश्वास बनाती है","बच्चों को लंबे और जटिल अंग्रेज़ी वाक्यों का सही व्याकरण सिखाती है","जाँचती है कि बच्चे बोर्ड से कठिन शब्द कितनी अच्छी तरह पढ़ सकते हैं","बच्चों को वस्तुओं के बारे में छोटे अनुच्छेद लिखने का अभ्यास देती है"],"explanationHi":"किसी निजी चीज़ के बारे में बात करना बच्चों को विषय-वस्तु और प्रेरणा देता है, घर और विद्यालय को जोड़ता है, और सहयोगी वातावरण में श्रोताओं के लिए बोलना विकसित करता है।"},
  {"id":"cdp-pedagogy-subjects-1237","question":"Two teachers listen to the same recorded speaking task of a Class 8 student; one gives 8/10 and the other 4/10. The best step to make speaking assessment more consistent is to:","options":["Stop assessing speaking altogether, since it can never be marked fairly","Use a shared rubric with clear descriptors and compare sample ratings","Simply average the two marks and move on to the next student","Replace the speaking task with a written grammar test that is easy to mark"],"answer":1,"explanation":"Inter-rater reliability improves when raters share explicit criteria and calibrate on samples; abandoning or replacing the task would lose validity.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"दो शिक्षक कक्षा 8 के एक विद्यार्थी का एक ही रिकॉर्ड किया हुआ बोलने का कार्य सुनते हैं; एक 8/10 देता है और दूसरा 4/10। बोलने के आकलन को अधिक सुसंगत बनाने का सबसे अच्छा कदम है:","optionsHi":["बोलने का आकलन पूरी तरह बंद करना, क्योंकि उसे कभी निष्पक्ष रूप से अंकित नहीं किया जा सकता","स्पष्ट वर्णकों वाला साझा रूब्रिक उपयोग करना और नमूना रेटिंगों की तुलना करना","दोनों अंकों का केवल औसत लेकर अगले विद्यार्थी पर चले जाना","बोलने के कार्य को लिखित व्याकरण परीक्षा से बदल देना जिसे अंकित करना आसान है"],"explanationHi":"जब मूल्यांकनकर्ता स्पष्ट मानदंड साझा करते हैं और नमूनों पर अंशांकन करते हैं, तो अंतर-निर्णायक विश्वसनीयता सुधरती है; कार्य को छोड़ने या बदलने से वैधता खो जाएगी।"},
  {"id":"cdp-pedagogy-subjects-1238","question":"After listening to a story, Class 3 children are asked to retell it in their own words to a partner. As an assessment task, story retelling mainly shows the child’s:","options":["Handwriting and spelling of the story’s key words and names","Listening comprehension and oral expression together","Knowledge of grammatical terms used in the story","Speed of silent reading compared with classmates"],"answer":1,"explanation":"Retelling needs understanding of the story (listening) and the ability to organise and express it (speaking), so it integrates both skills in one task.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कहानी सुनने के बाद कक्षा 3 के बच्चों से कहा जाता है कि वे उसे साथी को अपने शब्दों में दोबारा सुनाएँ। आकलन-कार्य के रूप में कहानी का पुनःकथन मुख्यतः बच्चे की क्या दिखाता है:","optionsHi":["कहानी के मुख्य शब्दों और नामों की लिखावट और वर्तनी","श्रवण-बोध और मौखिक अभिव्यक्ति, दोनों साथ-साथ","कहानी में प्रयुक्त व्याकरणिक पदों का ज्ञान","सहपाठियों की तुलना में मौन पठन की गति"],"explanationHi":"पुनःकथन के लिए कहानी की समझ (श्रवण) और उसे व्यवस्थित करने और व्यक्त करने की क्षमता (बोलना) चाहिए, इसलिए यह एक कार्य में दोनों कौशलों को जोड़ता है।"},
  {"id":"cdp-pedagogy-subjects-1239","question":"Which of the following is NOT a sound principle of language teaching in the spirit of NCF 2005?","options":["Accuracy must be fully achieved before children are allowed to communicate","Children need rich and varied exposure to the language, spoken and written","Language is best learnt through its use in meaningful contexts","Errors are a natural and informative part of learning a language"],"answer":0,"explanation":"Insisting on accuracy before communication delays use and raises anxiety; NCF 2005 favours meaningful use with errors treated as signs of learning.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"NCF 2005 की भावना में भाषा शिक्षण का निम्नलिखित में से कौन-सा एक सही सिद्धांत नहीं है?","optionsHi":["बच्चों को संप्रेषण की अनुमति देने से पहले शुद्धता पूरी तरह प्राप्त होनी चाहिए","बच्चों को भाषा का समृद्ध और विविध संपर्क चाहिए, बोली और लिखी, दोनों","भाषा सबसे अच्छी तरह सार्थक संदर्भों में उसके प्रयोग से सीखी जाती है","त्रुटियाँ भाषा सीखने का स्वाभाविक और सूचनाप्रद अंग हैं"],"explanationHi":"संप्रेषण से पहले शुद्धता पर ज़ोर देना प्रयोग को टालता है और चिंता बढ़ाता है; NCF 2005 सार्थक प्रयोग का पक्ष लेती है, जिसमें त्रुटियों को सीखने के संकेत माना जाता है।"},
  {"id":"cdp-pedagogy-subjects-1240","question":"Assertion (A): Listening is a passive skill, so it develops automatically and need not be taught. Reason (R): Listening involves only hearing sounds and not interpreting meaning.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","Both A and R are false"],"answer":3,"explanation":"Listening is an active, receptive skill in which the listener decodes sounds and builds meaning using context and prior knowledge, so it benefits from teaching. Both statements are false.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"अभिकथन (A): श्रवण एक निष्क्रिय कौशल है, इसलिए वह स्वतः विकसित होता है और उसे सिखाने की आवश्यकता नहीं। कारण (R): श्रवण में केवल ध्वनियाँ सुनना शामिल है, अर्थ की व्याख्या नहीं।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A और R दोनों असत्य हैं"],"explanationHi":"श्रवण एक सक्रिय, ग्रहणशील कौशल है जिसमें श्रोता ध्वनियों का विकोडन करता है और संदर्भ तथा पूर्व ज्ञान का उपयोग करके अर्थ बनाता है, इसलिए उसे सिखाने से लाभ होता है। दोनों कथन असत्य हैं।"},
  {"id":"cdp-pedagogy-subjects-1241","question":"Consider these statements: I. Listening and reading are receptive skills. II. Receptive skills involve no active mental processing by the learner. III. Speaking and writing are productive skills. Which are correct?","options":["I and II only","II and III only","I, II and III","I and III only"],"answer":3,"explanation":"‘Receptive’ means taking in language, not being passive; listeners and readers actively predict, infer and interpret. So II is false.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"इन कथनों पर विचार कीजिए: I. श्रवण और पठन ग्रहणशील कौशल हैं। II. ग्रहणशील कौशलों में अधिगमकर्ता की कोई सक्रिय मानसिक प्रक्रिया शामिल नहीं होती। III. बोलना और लिखना उत्पादक कौशल हैं। कौन-से सही हैं?","optionsHi":["केवल I और II","केवल II और III","I, II और III","केवल I और III"],"explanationHi":"‘ग्रहणशील’ का अर्थ है भाषा को ग्रहण करना, निष्क्रिय होना नहीं; श्रोता और पाठक सक्रिय रूप से पूर्वानुमान, अनुमान और व्याख्या करते हैं। इसलिए II असत्य है।"},
  {"id":"cdp-pedagogy-subjects-1242","question":"A Class 1 teacher often has the whole class repeat new rhymes and sentence patterns together. Which evaluation of choral repetition is most accurate?","options":["It should never be used, because it comes from behaviourist drilling","It is enough by itself to develop children’s spoken language fully and quickly","It gives shy children safe practice but needs balancing with individual talk","It is useful only for teaching the spelling of new rhyme words"],"answer":2,"explanation":"Choral work builds confidence and familiarity with sounds and rhythm without singling anyone out, but it does not let children express their own meanings, so it needs to be balanced.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कक्षा 1 की एक शिक्षिका प्रायः पूरी कक्षा से नई तुकबंदियाँ और वाक्य-प्रतिरूप साथ-साथ दोहरवाती है। समवेत पुनरावृत्ति का कौन-सा मूल्यांकन सबसे सटीक है?","optionsHi":["इसका कभी उपयोग नहीं करना चाहिए, क्योंकि यह व्यवहारवादी अभ्यास से आती है","यह अकेले ही बच्चों की बोली जाने वाली भाषा को पूर्णतः और शीघ्र विकसित करने के लिए पर्याप्त है","यह संकोची बच्चों को सुरक्षित अभ्यास देती है पर उसे व्यक्तिगत बातचीत के साथ संतुलित करना चाहिए","यह केवल नई तुकबंदी वाले शब्दों की वर्तनी सिखाने के लिए उपयोगी है"],"explanationHi":"समवेत कार्य किसी को अलग किए बिना ध्वनियों और लय के साथ आत्मविश्वास और परिचय बनाता है, पर वह बच्चों को अपने अर्थ व्यक्त करने नहीं देता, इसलिए उसे संतुलित करना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1243","question":"In a recording, a girl spills tea on her new dress and says flatly, ‘Oh, great!’ Students are asked how she feels. This question tests the ability to:","options":["Infer a speaker’s attitude from intonation and context","Listen for the gist, the overall idea of a long recording","Listen for specific information such as names, times and numbers","Discriminate between minimal pairs of similar sounds"],"answer":0,"explanation":"The words are positive but the tone and situation show annoyance; understanding sarcasm requires inferring attitude from intonation and context, not just decoding words.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"एक रिकॉर्डिंग में एक लड़की अपनी नई पोशाक पर चाय गिरा देती है और सपाट स्वर में कहती है, ‘Oh, great!’ विद्यार्थियों से पूछा जाता है कि वह कैसा महसूस करती है। यह प्रश्न किस क्षमता की जाँच करता है:","optionsHi":["स्वर-अनुतान और संदर्भ से वक्ता के रुख का अनुमान लगाना","सार के लिए सुनना, यानी लंबी रिकॉर्डिंग का समग्र विचार","नाम, समय और संख्याएँ जैसी विशिष्ट जानकारी के लिए सुनना","समान ध्वनियों के न्यूनतम युग्मों में भेद करना"],"explanationHi":"शब्द सकारात्मक हैं पर स्वर और परिस्थिति झुँझलाहट दिखाते हैं; व्यंग्य को समझने के लिए केवल शब्दों का विकोडन नहीं, स्वर-अनुतान और संदर्भ से रुख का अनुमान लगाना पड़ता है।"},
  {"id":"cdp-pedagogy-subjects-1244","question":"A Class 9 teacher teaches phrases such as ‘Sorry to interrupt, but…’, ‘Could you say that again?’ and ‘Let me add to what Priya said…’ before a group discussion. The main purpose is to help students:","options":["Memorise polite sentences that can be reproduced in the written examination","Improve the spelling of common phrases that students often get wrong","Manage talk: take turns, ask for clarification and build on others’ ideas","Keep their turns short so that the discussion finishes within the period"],"answer":2,"explanation":"Such phrases are tools for managing interaction, part of discourse and strategic competence, which help learners take part in real discussions.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 9 का एक शिक्षक समूह-चर्चा से पहले ‘Sorry to interrupt, but…’, ‘Could you say that again?’ और ‘Let me add to what Priya said…’ जैसे वाक्यांश सिखाता है। मुख्य उद्देश्य विद्यार्थियों की मदद करना है:","optionsHi":["विनम्र वाक्य याद करने में जिन्हें लिखित परीक्षा में पुनः प्रस्तुत किया जा सके","सामान्य वाक्यांशों की वर्तनी सुधारने में जिन्हें विद्यार्थी प्रायः गलत लिखते हैं","बातचीत को सँभालने में: बारी लेना, स्पष्टीकरण माँगना और दूसरों के विचारों पर आगे बढ़ना","अपनी बारियाँ छोटी रखने में ताकि चर्चा कालांश के भीतर समाप्त हो जाए"],"explanationHi":"ऐसे वाक्यांश अंतःक्रिया को सँभालने के साधन हैं, जो प्रवचन और युक्तिपरक सक्षमता का भाग हैं, और अधिगमकर्ताओं को वास्तविक चर्चाओं में भाग लेने में मदद करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1245","question":"To assess the speaking skill of Class 3 children, a teacher asks each child to recite a poem learnt by heart. What is the main weakness of this assessment?","options":["Poems are too difficult for Class 3, so most children will fail the task","It mainly tests memory and recitation, not spontaneous speaking","It takes too little time per child to give any useful information","It actually tests writing, since the poem was first copied in notebooks"],"answer":1,"explanation":"Speaking ability means expressing one’s own meanings; recitation shows memory and pronunciation of a fixed text. Picture talk or a short conversation would be more valid.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 3 के बच्चों के बोलने के कौशल का आकलन करने के लिए एक शिक्षिका प्रत्येक बच्चे से कंठस्थ की गई कविता सुनाने को कहती है। इस आकलन की मुख्य कमज़ोरी क्या है?","optionsHi":["कविताएँ कक्षा 3 के लिए बहुत कठिन हैं, इसलिए अधिकांश बच्चे कार्य में विफल होंगे","यह मुख्यतः स्मृति और पाठ की जाँच करता है, सहज बोली की नहीं","प्रत्येक बच्चे पर यह इतना कम समय लेता है कि कोई उपयोगी जानकारी नहीं दे सकता","यह वास्तव में लेखन की जाँच करता है, क्योंकि कविता पहले कॉपियों में उतारी गई थी"],"explanationHi":"बोलने की क्षमता का अर्थ है अपने अर्थ व्यक्त करना; पाठ एक निश्चित पाठ की स्मृति और उच्चारण दिखाता है। चित्र पर बातचीत या छोटा संवाद अधिक वैध होगा।"},
  {"id":"cdp-pedagogy-subjects-1246","question":"Before a recorded talk, a Class 9 teacher points out phrases such as ‘firstly’, ‘on the other hand’ and ‘to sum up’, and asks students to note what follows each. The main purpose is to help students:","options":["Learn the spellings of linking words that often appear in examinations","Translate the talk into their mother tongue while they listen","Skip the details of the talk and listen only to its last part","Use signposting phrases to follow the structure of a long talk"],"answer":3,"explanation":"Discourse markers signal how a talk is organised, such as new points, contrasts and conclusions, so attending to them helps listeners follow the argument and take organised notes.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"रिकॉर्ड की गई वार्ता से पहले कक्षा 9 का एक शिक्षक ‘firstly’, ‘on the other hand’ और ‘to sum up’ जैसे वाक्यांश बताता है और विद्यार्थियों से नोट करने को कहता है कि प्रत्येक के बाद क्या आता है। मुख्य उद्देश्य विद्यार्थियों की मदद करना है:","optionsHi":["उन संयोजक शब्दों की वर्तनी सीखने में जो प्रायः परीक्षाओं में आते हैं","सुनते समय वार्ता का अपनी मातृभाषा में अनुवाद करने में","वार्ता के विवरणों को छोड़कर केवल उसके अंतिम भाग को सुनने में","संकेतक वाक्यांशों का उपयोग करके लंबी वार्ता की संरचना का अनुसरण करने में"],"explanationHi":"प्रवचन-चिह्नक संकेत देते हैं कि वार्ता कैसे संगठित है, जैसे नए बिंदु, विरोध और निष्कर्ष, इसलिए उन पर ध्यान देने से श्रोताओं को तर्क का अनुसरण करने और व्यवस्थित नोट्स लेने में मदद मिलती है।"},
  {"id":"cdp-pedagogy-subjects-1247","question":"A teacher says, ‘I bought you a PREsent’ and then ‘Let me preSENT the winners’, and asks Class 8 students what changed besides the meaning. The point being taught is that:","options":["English spelling always shows clearly where the stress falls","Stress can change the word class and meaning of some words","Stress makes no difference at all to meaning in English","Only nouns carry stress in English words and sentences"],"answer":1,"explanation":"In pairs like ‘PREsent’ (noun) and ‘preSENT’ (verb), stress shifts with word class; spelling does not show this, so it needs explicit attention in speaking and listening.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"एक शिक्षक कहता है, ‘I bought you a PREsent’ और फिर ‘Let me preSENT the winners’, और कक्षा 8 के विद्यार्थियों से पूछता है कि अर्थ के अलावा क्या बदला। जो बात सिखाई जा रही है वह यह है कि:","optionsHi":["अंग्रेज़ी वर्तनी हमेशा स्पष्ट दिखाती है कि बलाघात कहाँ पड़ता है","बलाघात कुछ शब्दों का शब्द-वर्ग और अर्थ बदल सकता है","अंग्रेज़ी में बलाघात से अर्थ में बिल्कुल कोई अंतर नहीं पड़ता","अंग्रेज़ी शब्दों और वाक्यों में केवल संज्ञाओं पर बलाघात होता है"],"explanationHi":"‘PREsent’ (संज्ञा) और ‘preSENT’ (क्रिया) जैसे युग्मों में बलाघात शब्द-वर्ग के साथ बदलता है; वर्तनी यह नहीं दिखाती, इसलिए बोलने और सुनने में उस पर स्पष्ट ध्यान चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1248","question":"Under the theme ‘Shelter’, a Class 4 EVS lesson looks at nests, burrows and anthills as well as human houses. The main reason for including animal homes is to help children:","options":["learn the names of animal homes for the end-of-term examination","see shelter as a need of all living beings, shaped by surroundings","understand that animals build stronger and better homes than humans do","fill the theme with interesting pictures to hold their attention"],"answer":1,"explanation":"Seeing that all living beings need shelter, and that homes suit surroundings, builds connections across the living world. Naming homes is recall; comparing who builds ‘better’ misses the point.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"‘आश्रय’ विषय के अंतर्गत कक्षा 4 का एक EVS पाठ घोंसलों, बिलों और दीमक की बाँबियों के साथ-साथ मानव घरों को भी देखता है। जंतुओं के घर शामिल करने का मुख्य कारण बच्चों की मदद करना है:","optionsHi":["सत्र-अंत परीक्षा के लिए जंतुओं के घरों के नाम सीखने में","आश्रय को सभी जीवों की आवश्यकता के रूप में देखने में, जो परिवेश से आकार लेती है","यह समझने में कि जंतु मनुष्यों से अधिक मज़बूत और बेहतर घर बनाते हैं","ध्यान बनाए रखने के लिए विषय को रोचक चित्रों से भरने में"],"explanationHi":"यह देखना कि सभी जीवों को आश्रय चाहिए, और घर परिवेश के अनुकूल होते हैं, जीवित जगत के पार संबंध बनाता है। घरों के नाम बताना स्मरण है; यह तुलना करना कि कौन 'बेहतर' बनाता है, मुद्दा चूक जाना है।"},
  {"id":"cdp-pedagogy-subjects-1249","question":"Class 5 children keep pieces of chapati in a dry box, a damp box and an open plate, and observe them for a week. Which question from the teacher best guides careful observation?","options":["Which of the three chapatis is the best one to eat at the end of the week?","Have you seen spoilt food at home before, and what did your family do?","What changes do you see each day in colour, smell and texture, and where?","Do you like chapati, and how many do you usually eat at each meal at home?"],"answer":2,"explanation":"The question points children to specific, comparable features over time, which is the heart of observation and recording. The others invite opinion or yes/no answers.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 5 के बच्चे चपाती के टुकड़े सूखे डिब्बे, नम डिब्बे और खुली थाली में रखते हैं और एक सप्ताह तक उनका अवलोकन करते हैं। शिक्षक का कौन-सा प्रश्न सावधानीपूर्ण अवलोकन का सबसे अच्छा मार्गदर्शन करता है?","optionsHi":["सप्ताह के अंत में तीनों चपातियों में से खाने के लिए सबसे अच्छी कौन-सी है?","क्या तुमने पहले घर पर खराब भोजन देखा है, और तुम्हारे परिवार ने क्या किया?","रंग, गंध और बनावट में तुम्हें हर दिन क्या परिवर्तन दिखते हैं, और कहाँ?","क्या तुम्हें चपाती पसंद है, और घर पर हर भोजन में तुम आमतौर पर कितनी खाते हो?"],"explanationHi":"प्रश्न बच्चों को समय के साथ विशिष्ट, तुलनीय विशेषताओं की ओर ले जाता है, जो अवलोकन और अभिलेखन का सार है। अन्य प्रश्न मत या हाँ/नहीं उत्तर आमंत्रित करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1250","question":"A Class 4 teacher wants children to understand that water is not shared equally. Which activity best achieves this?","options":["A role play giving some ‘families’ far more water than others, then a discussion","Reading the textbook paragraph on water scarcity aloud, with the teacher explaining","Writing an essay on ‘Save Water’ for the school wall magazine","Learning a slogan on water conservation by heart for the assembly"],"answer":0,"explanation":"Experiencing unfair distribution in a role play, then reflecting on it, builds understanding and empathy. Essays and slogans stay at the level of words.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 का एक शिक्षक चाहता है कि बच्चे समझें कि पानी समान रूप से नहीं बँटा है। कौन-सी गतिविधि इसे सबसे अच्छी तरह प्राप्त करती है?","optionsHi":["कुछ 'परिवारों' को दूसरों से कहीं अधिक पानी देने वाला भूमिका-निर्वाह, फिर चर्चा","पाठ्यपुस्तक का जल-संकट वाला अनुच्छेद ज़ोर से पढ़ना, शिक्षक द्वारा समझाते हुए","विद्यालय की दीवार-पत्रिका के लिए 'जल बचाओ' पर निबंध लिखना","सभा के लिए जल-संरक्षण का नारा कंठस्थ करना"],"explanationHi":"भूमिका-निर्वाह में अनुचित वितरण का अनुभव करना, फिर उस पर चिंतन करना, समझ और सहानुभूति बनाता है। निबंध और नारे शब्दों के स्तर पर ही रहते हैं।"},
  {"id":"cdp-pedagogy-subjects-1251","question":"Class 5 children interview elders about journeys they made fifty years ago: how they travelled, how long it took and who could afford to travel. Besides change in transport over time, this activity helps children see that:","options":["older modes of transport were always better and more comfortable than today’s","travel habits have hardly changed at all in the last fifty years","only modern, faster transport is really worth studying in EVS","who could travel depended on money, place and social factors"],"answer":3,"explanation":"Asking ‘who could travel’ draws out the social side of travel, linking history with equity. The other options are either false or narrow.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 5 के बच्चे बुज़ुर्गों से पचास वर्ष पहले की उनकी यात्राओं के बारे में साक्षात्कार करते हैं: वे कैसे गए, कितना समय लगा और कौन यात्रा का खर्च उठा सकता था। समय के साथ परिवहन में परिवर्तन के अलावा, यह गतिविधि बच्चों को क्या देखने में मदद करती है:","optionsHi":["पुराने परिवहन-साधन हमेशा आज के साधनों से बेहतर और अधिक आरामदायक थे","पिछले पचास वर्षों में यात्रा की आदतें लगभग बिल्कुल नहीं बदली हैं","EVS में केवल आधुनिक, तेज़ परिवहन का अध्ययन ही वास्तव में सार्थक है","कौन यात्रा कर सकता था यह धन, स्थान और सामाजिक कारकों पर निर्भर था"],"explanationHi":"‘कौन यात्रा कर सकता था’ पूछना यात्रा के सामाजिक पक्ष को सामने लाता है, जो इतिहास को समता से जोड़ता है। अन्य विकल्प या तो असत्य हैं या संकीर्ण।"},
  {"id":"cdp-pedagogy-subjects-1252","question":"Which question, asked under the theme ‘Things We Make and Do’, best moves children from the product to the people behind it?","options":["How many bricks are needed to build one room of a house like ours?","Who makes our bricks, and what is their work like?","What colours and sizes are the bricks used in our school building?","Are bricks heavier than stones of the same size, and why is that?"],"answer":1,"explanation":"The theme aims at valuing workers and their conditions as well as processes. Asking about the brick-kiln workers brings that in; the others stay with the object.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"‘हम जो बनाते और करते हैं’ विषय के अंतर्गत पूछा गया कौन-सा प्रश्न बच्चों को उत्पाद से उसके पीछे के लोगों की ओर सबसे अच्छी तरह ले जाता है?","optionsHi":["हमारे जैसे घर का एक कमरा बनाने के लिए कितनी ईंटें चाहिए?","हमारी ईंटें कौन बनाता है, और उनका कार्य कैसा होता है?","हमारे विद्यालय-भवन में प्रयुक्त ईंटें किन रंगों और आकारों की हैं?","क्या ईंटें समान आकार के पत्थरों से भारी होती हैं, और ऐसा क्यों?"],"explanationHi":"विषय का उद्देश्य प्रक्रियाओं के साथ श्रमिकों और उनकी परिस्थितियों को महत्त्व देना भी है। ईंट-भट्ठे के श्रमिकों के बारे में पूछना इसे सामने लाता है; अन्य प्रश्न वस्तु तक ही सीमित रहते हैं।"},
  {"id":"cdp-pedagogy-subjects-1253","question":"A Class 3 teacher plans to have every child draw a family tree showing parents and grandparents. Some children in the class are living with relatives or in a children’s home. The most sensitive way to frame the task is:","options":["Draw your father’s and mother’s families, going back to grandparents.","Draw only the people who live with you in your house right now.","Draw the people who care for you and matter in your life.","Leave out the children who do not have parents, to spare them."],"answer":2,"explanation":"The open framing lets every child represent her real circle of care without exposure or exclusion. The others assume a standard family or single out some children.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 3 की एक शिक्षिका प्रत्येक बच्चे से माता-पिता और दादा-दादी को दर्शाने वाला वंश-वृक्ष बनवाने की योजना बनाती है। कक्षा के कुछ बच्चे रिश्तेदारों के साथ या बाल-गृह में रहते हैं। कार्य को प्रस्तुत करने का सबसे संवेदनशील तरीका है:","optionsHi":["अपने पिता और माता के परिवार बनाओ, दादा-दादी तक जाते हुए।","केवल उन्हीं लोगों को बनाओ जो अभी तुम्हारे साथ तुम्हारे घर में रहते हैं।","उन लोगों को बनाओ जो तुम्हारी देखभाल करते हैं और तुम्हारे जीवन में मायने रखते हैं।","जिन बच्चों के माता-पिता नहीं हैं उन्हें छोड़ दो, ताकि उन्हें बचाया जा सके।"],"explanationHi":"खुला प्रस्तुतीकरण हर बच्चे को बिना उजागर हुए या बहिष्कृत हुए अपना वास्तविक देखभाल-दायरा दिखाने देता है। अन्य एक मानक परिवार मान लेते हैं या कुछ बच्चों को अलग कर देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1254","question":"A Class 3 teacher asks groups to invent a new game using only a ball and chalk, set its rules and teach it to another group. Under the sub-theme ‘Work and Play’, this activity mainly develops:","options":["cooperation, making and following rules, and expression","speed and accuracy in running, catching and throwing the ball","knowledge of the official rules of well-known national games","competition among children to find out who the best player is"],"answer":0,"explanation":"Designing and teaching a game requires working together, negotiating rules and explaining them. Athletic speed and official rules are not the aim.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की एक शिक्षिका समूहों से कहती है कि केवल एक गेंद और चाक से नया खेल बनाएँ, उसके नियम तय करें और उसे दूसरे समूह को सिखाएँ। 'काम और खेल' उप-विषय के अंतर्गत यह गतिविधि मुख्यतः विकसित करती है:","optionsHi":["सहयोग, नियम बनाना और उनका पालन करना, और अभिव्यक्ति","गेंद को दौड़ने, पकड़ने और फेंकने में गति और शुद्धता","प्रसिद्ध राष्ट्रीय खेलों के आधिकारिक नियमों का ज्ञान","बच्चों के बीच यह पता लगाने की प्रतियोगिता कि सबसे अच्छा खिलाड़ी कौन है"],"explanationHi":"खेल बनाने और सिखाने के लिए साथ काम करना, नियमों पर बातचीत करना और उन्हें समझाना पड़ता है। एथलेटिक गति और आधिकारिक नियम उद्देश्य नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-1255","question":"In a Class 4 lesson on animals that work with people, which question best develops concern for animals?","options":["Name five animals that carry loads for people in our area.","How much weight can a bullock pull compared with a horse?","Which working animal is the strongest, and how do we know?","How are cart bullocks in our area treated, and is it fair?"],"answer":3,"explanation":"Asking children to look at how working animals are treated, and to judge it, builds empathy and ethical concern. The others are recall or facts.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"मनुष्यों के साथ काम करने वाले जंतुओं पर कक्षा 4 के पाठ में कौन-सा प्रश्न जंतुओं के प्रति संवेदनशीलता को सबसे अच्छी तरह विकसित करता है?","optionsHi":["हमारे क्षेत्र में लोगों के लिए बोझ ढोने वाले पाँच जंतुओं के नाम बताओ।","एक बैल घोड़े की तुलना में कितना भार खींच सकता है?","कौन-सा काम करने वाला जंतु सबसे मज़बूत है, और हम कैसे जानते हैं?","हमारे क्षेत्र में गाड़ी खींचने वाले बैलों के साथ कैसा व्यवहार होता है, और क्या यह उचित है?"],"explanationHi":"बच्चों से यह देखने को कहना कि काम करने वाले जंतुओं के साथ कैसा व्यवहार होता है और उसका आकलन करना, सहानुभूति और नैतिक संवेदनशीलता बनाता है। अन्य प्रश्न स्मरण या तथ्यों के हैं।"},
  {"id":"cdp-pedagogy-subjects-1256","question":"Class 3 children list the plants used in their homes for food, medicine, festivals and building. The main learning from this activity is:","options":["the correct botanical names and families of the plants they listed","how closely people’s daily and cultural life depends on plants","which of these common plants are poisonous and should be avoided","how to grow these useful plants at home in pots and beds"],"answer":1,"explanation":"Listing uses across food, health, ritual and construction shows the many ties between people and plants. Botanical names and gardening are not the focus.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 के बच्चे अपने घरों में भोजन, औषधि, त्योहारों और निर्माण में काम आने वाले पौधों की सूची बनाते हैं। इस गतिविधि से मुख्य अधिगम है:","optionsHi":["उनके द्वारा सूचीबद्ध पौधों के सही वानस्पतिक नाम और कुल","लोगों का दैनिक और सांस्कृतिक जीवन पौधों पर कितना निकटता से निर्भर है","इन सामान्य पौधों में से कौन-से विषैले हैं और उनसे बचना चाहिए","इन उपयोगी पौधों को घर पर गमलों और क्यारियों में कैसे उगाएँ"],"explanationHi":"भोजन, स्वास्थ्य, अनुष्ठान और निर्माण में उपयोगों की सूची बनाना लोगों और पौधों के बीच के अनेक संबंध दिखाता है। वानस्पतिक नाम और बागवानी इसका केंद्र नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-1257","question":"A teacher uses an old chart showing separate zones of the tongue for sweet, salty, sour and bitter tastes. A child puts a little sugar on the ‘bitter’ zone and says it still tastes sweet. The best response of the teacher is to:","options":["tell the child she placed the sugar on the wrong part of her tongue","ask her to repeat it carefully until she gets the result shown on the chart","accept the evidence, let others test it, and discuss why the chart is wrong","ignore it, since a chart printed by a publisher is more reliable than one child"],"answer":2,"explanation":"The ‘tongue map’ is a well-known error; taste buds for all basic tastes are spread across the tongue. Letting evidence correct printed material teaches a central habit of inquiry.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"एक शिक्षिका मीठे, नमकीन, खट्टे और कड़वे स्वादों के लिए जीभ के अलग-अलग क्षेत्र दिखाने वाला पुराना चार्ट उपयोग करती है। एक बच्चा 'कड़वे' क्षेत्र पर थोड़ी चीनी रखता है और कहता है कि वह फिर भी मीठी लगती है। शिक्षिका की सबसे अच्छी प्रतिक्रिया है:","optionsHi":["बच्चे को बताना कि उसने चीनी जीभ के गलत भाग पर रखी","उससे सावधानी से दोहराने को कहना जब तक चार्ट में दिखाया परिणाम न आए","साक्ष्य स्वीकार करना, दूसरों को भी परखने देना और चर्चा करना कि चार्ट गलत क्यों है","उपेक्षा करना, क्योंकि प्रकाशक का छपा चार्ट एक बच्चे से अधिक विश्वसनीय है"],"explanationHi":"‘जीभ का मानचित्र’ एक प्रसिद्ध त्रुटि है; सभी मूल स्वादों के स्वाद-कलिकाएँ पूरी जीभ में फैली होती हैं। साक्ष्य को छपी सामग्री को सुधारने देना जिज्ञासा-आधारित अन्वेषण की एक केंद्रीय आदत सिखाता है।"},
  {"id":"cdp-pedagogy-subjects-1258","question":"NCERT EVS chapters on water include stories of stepwells, community tanks and disputes over water. The main reason for including them is to:","options":["present water as a shared resource tied to community and fairness","teach children the architecture and building methods of old stepwells","prepare children for history questions that may come in later classes","show that water shortages and disputes belong only to the distant past"],"answer":0,"explanation":"The theme treats water not only as a natural substance but as something people build, share and fight over, connecting it to equity and community.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"जल पर NCERT के EVS अध्यायों में बावड़ियों, सामुदायिक तालाबों और पानी पर विवादों की कहानियाँ शामिल हैं। इन्हें शामिल करने का मुख्य कारण है:","optionsHi":["जल को समुदाय और निष्पक्षता से जुड़े साझा संसाधन के रूप में प्रस्तुत करना","बच्चों को पुरानी बावड़ियों की वास्तुकला और निर्माण-विधियाँ सिखाना","बच्चों को बाद की कक्षाओं में आने वाले इतिहास के प्रश्नों के लिए तैयार करना","यह दिखाना कि जल-संकट और विवाद केवल दूर के अतीत के हैं"],"explanationHi":"यह विषय जल को केवल एक प्राकृतिक पदार्थ नहीं, बल्कि ऐसी चीज़ मानता है जिसे लोग बनाते, साझा करते और जिस पर लड़ते हैं, जिससे वह समता और समुदाय से जुड़ता है।"},
  {"id":"cdp-pedagogy-subjects-1259","question":"A Class 4 teacher asks groups to design and build, with clay and paper, a house suited to a place with heavy snowfall, and to explain their design choices. This task mainly asks children to:","options":["copy the picture of a snow house given in the textbook as neatly as possible","recall the names of the traditional houses found in different states","practise colouring, decoration and neat handwork with clay and paper","apply what they understand about climate to design something new"],"answer":3,"explanation":"Designing for given conditions and justifying choices is application and creation, a higher-order task. It goes well beyond recall or decoration.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 की एक शिक्षिका समूहों से मिट्टी और कागज़ से भारी हिमपात वाले स्थान के अनुकूल घर बनाने और अपने डिज़ाइन-चयन समझाने को कहती है। यह कार्य मुख्यतः बच्चों से क्या करने को कहता है?","optionsHi":["पाठ्यपुस्तक में दिए बर्फ़ के घर का चित्र यथासंभव साफ़-सुथरा नकल करना","विभिन्न राज्यों में पाए जाने वाले पारंपरिक घरों के नाम याद करना","मिट्टी और कागज़ से रंगाई, सजावट और साफ़ हस्तकला का अभ्यास करना","जलवायु के बारे में जो समझते हैं उसे कुछ नया डिज़ाइन करने में लागू करना"],"explanationHi":"दी गई परिस्थितियों के लिए डिज़ाइन करना और चयनों का औचित्य देना अनुप्रयोग और सृजन है, जो उच्च-स्तरीय कार्य है। यह स्मरण या सजावट से कहीं आगे है।"},
  {"id":"cdp-pedagogy-subjects-1260","question":"Class 5 children have a simple map of their town with a scale. Which question can be answered only by using the map, not from memory?","options":["What is the name of your town, and which district is it in?","Which is your favourite place in town, and why do you like it?","Using the scale, how far is the station from school, and by which roads?","Have you ever been to the railway station, and who took you there that day?"],"answer":2,"explanation":"Measuring distance with the scale and planning a route needs the map. The others rely on memory or opinion.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 5 के बच्चों के पास पैमाने वाला अपने कस्बे का एक सरल मानचित्र है। कौन-सा प्रश्न केवल मानचित्र के उपयोग से हल हो सकता है, स्मृति से नहीं?","optionsHi":["तुम्हारे कस्बे का नाम क्या है, और वह किस ज़िले में है?","कस्बे में तुम्हारा पसंदीदा स्थान कौन-सा है, और वह तुम्हें क्यों पसंद है?","पैमाने का उपयोग करके बताओ कि स्टेशन विद्यालय से कितनी दूर है, और किन सड़कों से?","क्या तुम कभी रेलवे स्टेशन गए हो, और उस दिन तुम्हें वहाँ कौन ले गया?"],"explanationHi":"पैमाने से दूरी मापने और मार्ग की योजना बनाने के लिए मानचित्र चाहिए। अन्य प्रश्न स्मृति या मत पर निर्भर हैं।"},
  {"id":"cdp-pedagogy-subjects-1261","question":"A teacher includes the lives of pastoral communities such as the Bakarwals and Gaddis, who move with their herds, in the theme ‘Travel’. The main purpose is to:","options":["show that nomadic life is backward and that settling down is a sign of progress","show travel for livelihood and respect diverse ways of life as equally normal","teach children the exact routes shepherds use in the hills each season","encourage children to take up herding as a career when they grow up"],"answer":1,"explanation":"Such examples widen children’s idea of travel and of normal life, building respect for diversity. Calling nomadic life backward is a prejudice EVS aims to question.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षिका ‘यात्रा’ विषय में बकरवाल और गद्दी जैसे चरवाहा समुदायों के जीवन को शामिल करती है, जो अपने पशुओं के साथ घूमते हैं। मुख्य उद्देश्य है:","optionsHi":["यह दिखाना कि घुमंतू जीवन पिछड़ा है और बस जाना प्रगति का चिह्न है","आजीविका के लिए यात्रा दिखाना और जीवन के विविध तरीकों का समान रूप से सामान्य मानकर सम्मान करना","बच्चों को वे सटीक मार्ग सिखाना जिनका उपयोग चरवाहे हर ऋतु में पहाड़ों में करते हैं","बच्चों को बड़े होकर चरवाही को आजीविका के रूप में अपनाने के लिए प्रोत्साहित करना"],"explanationHi":"ऐसे उदाहरण यात्रा और सामान्य जीवन के बारे में बच्चों के विचार को व्यापक बनाते हैं और विविधता के प्रति सम्मान बनाते हैं। घुमंतू जीवन को पिछड़ा कहना एक पूर्वाग्रह है जिसे EVS प्रश्नांकित करना चाहता है।"},
  {"id":"cdp-pedagogy-subjects-1262","question":"Class 4 children list ways in which food is preserved at home, such as pickling, drying papad and sun-drying vegetables. The main pedagogical value of this is that it:","options":["links home practices with ideas about why food spoils and how to keep it","teaches children traditional recipes that they can write in the examination","shows children that the methods used at home are old and unscientific","makes observation and experiments on spoilage unnecessary in class"],"answer":0,"explanation":"Starting from household practices helps children ask why salt, oil or drying keep food from spoiling, which can then be explored by observation.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 4 के बच्चे उन तरीकों की सूची बनाते हैं जिनसे घर पर भोजन संरक्षित किया जाता है, जैसे अचार डालना, पापड़ सुखाना और धूप में सब्ज़ियाँ सुखाना। इसका मुख्य शिक्षणशास्त्रीय मूल्य यह है कि यह:","optionsHi":["घर की प्रथाओं को इस विचार से जोड़ता है कि भोजन क्यों खराब होता है और उसे कैसे बचाया जाए","बच्चों को पारंपरिक व्यंजन-विधियाँ सिखाता है जिन्हें वे परीक्षा में लिख सकें","बच्चों को दिखाता है कि घर पर उपयोग की जाने वाली विधियाँ पुरानी और अवैज्ञानिक हैं","कक्षा में खराब होने पर अवलोकन और प्रयोगों को अनावश्यक बना देता है"],"explanationHi":"घरेलू प्रथाओं से आरंभ करना बच्चों को यह पूछने में मदद करता है कि नमक, तेल या सुखाना भोजन को खराब होने से क्यों रोकते हैं, जिसे फिर अवलोकन से खोजा जा सकता है।"},
  {"id":"cdp-pedagogy-subjects-1263","question":"A Class 4 child says, ‘Water that looks clear is always safe to drink.’ The teacher’s best response is to:","options":["agree, since visible dirt is the only thing that can make water unsafe to drink","tell the child that only sealed bottled water from a shop is safe to drink","say clearly that the statement is wrong and move on to the next topic","discuss that clear water can carry unseen germs, and why we boil or filter it"],"answer":3,"explanation":"The idea equates visible dirt with danger. Talking about invisible germs and everyday ways of making water safe extends it. Bottled water is no general solution.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 का एक बच्चा कहता है, ‘जो पानी साफ़ दिखता है वह हमेशा पीने के लिए सुरक्षित होता है।’ शिक्षक की सबसे अच्छी प्रतिक्रिया है:","optionsHi":["सहमत होना, क्योंकि दिखाई देने वाली गंदगी ही पानी को असुरक्षित बना सकती है","बच्चे को बताना कि केवल दुकान का सील बंद बोतलबंद पानी ही पीने के लिए सुरक्षित है","स्पष्ट कहना कि कथन गलत है और अगले विषय पर बढ़ जाना","चर्चा करना कि साफ़ पानी में अदृश्य कीटाणु हो सकते हैं, और हम उसे उबालते या छानते क्यों हैं"],"explanationHi":"यह विचार दिखाई देने वाली गंदगी को ही खतरे के बराबर मानता है। अदृश्य कीटाणुओं और पानी को सुरक्षित बनाने के रोज़मर्रा के तरीकों पर बात करने से यह विचार आगे बढ़ता है। बोतलबंद पानी कोई सामान्य समाधान नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1264","question":"Class 5 children ask their grandparents what games they played, what they ate as children and what they now find difficult in daily life. The main aim of this activity is to:","options":["collect old family recipes so that the school can publish a cookbook","show children that life in the past was simpler, healthier and better than today","build understanding across generations and sensitivity to older people’s needs","test children’s writing skills through a long report on the interviews"],"answer":2,"explanation":"Learning about elders’ childhoods and present difficulties builds connection and empathy. It is not meant to idealise the past.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 5 के बच्चे अपने दादा-दादी से पूछते हैं कि वे कौन-से खेल खेलते थे, बचपन में क्या खाते थे और अब दैनिक जीवन में उन्हें क्या कठिन लगता है। इस गतिविधि का मुख्य उद्देश्य है:","optionsHi":["पुरानी पारिवारिक व्यंजन-विधियाँ एकत्र करना ताकि विद्यालय एक पाक-पुस्तक प्रकाशित कर सके","बच्चों को दिखाना कि अतीत का जीवन आज से अधिक सरल, स्वस्थ और बेहतर था","पीढ़ियों के बीच समझ और बुज़ुर्गों की आवश्यकताओं के प्रति संवेदनशीलता बनाना","साक्षात्कारों पर लंबी रिपोर्ट के माध्यम से बच्चों के लेखन-कौशल की जाँच करना"],"explanationHi":"बुज़ुर्गों के बचपन और वर्तमान कठिनाइयों के बारे में जानना जुड़ाव और सहानुभूति बनाता है। इसका उद्देश्य अतीत को आदर्श बनाना नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1265","question":"Class 5 children build a bridge of paper between two books and test how many coins it can hold; one group’s bridge collapses quickly. Which question from the teacher best promotes design thinking?","options":["Why did your group fail when the other groups did better than you?","What could you change so it holds more coins? Try it and see.","Which group has made the best bridge, and who should get the prize?","Should we stop here, since paper is simply too weak for bridges?"],"answer":1,"explanation":"Inviting children to modify and retest treats failure as information, which is how design and experimentation work. Blame or ranking discourages trying again.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के बच्चे दो किताबों के बीच कागज़ का पुल बनाते हैं और परखते हैं कि वह कितने सिक्के सँभाल सकता है; एक समूह का पुल जल्दी गिर जाता है। शिक्षिका का कौन-सा प्रश्न डिज़ाइन-चिंतन को सबसे अच्छी तरह बढ़ावा देता है?","optionsHi":["तुम्हारा समूह क्यों विफल हुआ जबकि अन्य समूहों ने तुमसे बेहतर किया?","तुम क्या बदल सकते हो ताकि वह अधिक सिक्के सँभाले? करके देखो।","किस समूह ने सबसे अच्छा पुल बनाया है, और पुरस्कार किसे मिलना चाहिए?","क्या हमें यहीं रुक जाना चाहिए, क्योंकि कागज़ पुलों के लिए बस बहुत कमज़ोर है?"],"explanationHi":"बच्चों को संशोधित करने और फिर परखने के लिए आमंत्रित करना विफलता को जानकारी मानता है, जैसे डिज़ाइन और प्रयोग काम करते हैं। दोषारोपण या क्रमांकन दोबारा प्रयास करने को हतोत्साहित करता है।"},
  {"id":"cdp-pedagogy-subjects-1266","question":"A Class 3 child says, ‘Birds live in their nests just as we live in our houses.’ Which response best helps the child refine this idea?","options":["Have children watch birds near school to find out when nests are actually used","Tell the child she is correct, since a nest is simply a bird’s house","Tell the child that birds never use nests and always sleep out on open branches","Ask the child to draw a bird sitting inside its nest, like a family at home"],"answer":0,"explanation":"Most birds build nests for laying eggs and raising young, not as permanent homes. Observation can lead children to this, which neither agreement nor denial would.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 3 की एक बच्ची कहती है, ‘पक्षी अपने घोंसलों में उसी तरह रहते हैं जैसे हम अपने घरों में रहते हैं।’ कौन-सी प्रतिक्रिया बच्ची को इस विचार को परिष्कृत करने में सबसे अच्छी मदद करती है?","optionsHi":["बच्चों से विद्यालय के पास पक्षियों का अवलोकन करवाना ताकि पता चले कि घोंसले वास्तव में कब उपयोग होते हैं","बच्ची को बताना कि वह सही है, क्योंकि घोंसला बस पक्षी का घर है","बच्ची को बताना कि पक्षी कभी घोंसलों का उपयोग नहीं करते और हमेशा खुली डालियों पर सोते हैं","बच्ची से अपने घोंसले के अंदर बैठे पक्षी का चित्र बनाने को कहना, जैसे घर पर कोई परिवार"],"explanationHi":"अधिकांश पक्षी अंडे देने और बच्चे पालने के लिए घोंसले बनाते हैं, स्थायी घर के रूप में नहीं। अवलोकन बच्चों को इस तक ले जा सकता है, जो न सहमति से होता, न खंडन से।"},
  {"id":"cdp-pedagogy-subjects-1267","question":"For a week, Class 4 children record what is served in the mid-day meal each day and then discuss the variety. This activity is a good example of:","options":["checking whether the school cook is doing her job properly every day","teaching children to complain politely when they dislike the food served","comparing nearby schools to find out which one serves the best meal","using a daily school experience as a resource for learning about food"],"answer":3,"explanation":"The mid-day meal is part of children’s daily life and can be observed, recorded and discussed, which suits the ‘Food’ theme. It is not an inspection or a complaint exercise.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"एक सप्ताह तक कक्षा 4 के बच्चे हर दिन दर्ज करते हैं कि मध्याह्न भोजन में क्या परोसा गया और फिर उसकी विविधता पर चर्चा करते हैं। यह गतिविधि किसका अच्छा उदाहरण है:","optionsHi":["यह जाँचना कि विद्यालय की रसोइया प्रतिदिन अपना कार्य ठीक से कर रही है या नहीं","बच्चों को सिखाना कि जब उन्हें परोसा गया भोजन पसंद न आए तो विनम्रता से शिकायत कैसे करें","पास के विद्यालयों की तुलना करके पता लगाना कि कौन सबसे अच्छा भोजन देता है","भोजन के बारे में सीखने के संसाधन के रूप में दैनिक विद्यालयी अनुभव का उपयोग करना"],"explanationHi":"मध्याह्न भोजन बच्चों के दैनिक जीवन का भाग है और उसका अवलोकन, अभिलेखन और चर्चा हो सकती है, जो ‘भोजन’ विषय के अनुकूल है। यह निरीक्षण या शिकायत का अभ्यास नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1268","question":"After a walk, Class 5 children write a letter to the gram panchayat about a broken hand pump in their village, describing the problem and suggesting a solution. This activity best shows:","options":["a pure language exercise in letter-writing that is unrelated to EVS","the teacher handing over her own civic responsibility to the children","EVS joined with language, with children acting as responsible citizens","a punishment for the children who first complained about the hand pump"],"answer":2,"explanation":"Children use language for a real purpose while engaging with local governance and a shared resource, joining EVS, language and citizenship.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक पैदल भ्रमण के बाद कक्षा 5 के बच्चे अपने गाँव के टूटे हैंडपंप के बारे में ग्राम पंचायत को पत्र लिखते हैं, जिसमें समस्या का वर्णन और समाधान का सुझाव है। यह गतिविधि सबसे अच्छी तरह दर्शाती है:","optionsHi":["पत्र-लेखन का शुद्ध भाषा-अभ्यास जो EVS से असंबंधित है","शिक्षिका द्वारा अपनी नागरिक ज़िम्मेदारी बच्चों को सौंप देना","EVS का भाषा से जुड़ना, जिसमें बच्चे उत्तरदायी नागरिकों के रूप में कार्य करते हैं","उन बच्चों के लिए दंड जिन्होंने पहले हैंडपंप की शिकायत की"],"explanationHi":"बच्चे वास्तविक उद्देश्य के लिए भाषा का प्रयोग करते हैं जबकि स्थानीय शासन और साझा संसाधन से जुड़ते हैं, जो EVS, भाषा और नागरिकता को जोड़ता है।"},
  {"id":"cdp-pedagogy-subjects-1269","question":"Most children in a Class 3 class in a remote village have never left the village. For the theme ‘Travel’, the teacher’s best strategy is to:","options":["start from people who come to the village, like vendors, then widen with stories","skip the theme until the children have had a chance to travel themselves","show only pictures of aeroplanes and fast trains so that the children get excited","ask children to imagine long journeys on their own, without any support"],"answer":0,"explanation":"Even without travelling, children see people who travel to them; starting there and widening with stories keeps the known-to-unknown principle.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"एक दूरस्थ गाँव की कक्षा 3 के अधिकांश बच्चे कभी गाँव से बाहर नहीं गए। ‘यात्रा’ विषय के लिए शिक्षक की सबसे अच्छी रणनीति है:","optionsHi":["गाँव में आने वाले लोगों, जैसे फेरीवालों, से आरंभ करना, फिर कहानियों से विस्तार करना","विषय तब तक छोड़ देना जब तक बच्चों को स्वयं यात्रा का अवसर न मिले","केवल हवाई जहाज़ों और तेज़ रेलगाड़ियों के चित्र दिखाना ताकि बच्चे उत्साहित हों","बच्चों से बिना किसी सहायता के स्वयं लंबी यात्राओं की कल्पना करने को कहना"],"explanationHi":"यात्रा न करने पर भी बच्चे उन लोगों को देखते हैं जो उनके पास यात्रा करके आते हैं; वहीं से आरंभ करना और कहानियों से विस्तार करना ज्ञात से अज्ञात के सिद्धांत को बनाए रखता है।"},
  {"id":"cdp-pedagogy-subjects-1270","question":"Class 5 children collect seeds from around the school and group them by how they think each seed travels, by wind, water or animals, giving reasons from the seeds’ shapes. The main process skill being developed is:","options":["memorising the common and local names of different seeds","inferring how something works from its structure","measuring the length and mass of seeds accurately","copying the seed classification given in the textbook"],"answer":1,"explanation":"Children reason from features such as wings, hooks or a fibrous coat to a likely way of dispersal, which is inference. It is neither recall nor measurement.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के बच्चे विद्यालय के आस-पास से बीज इकट्ठा करते हैं और उन्हें इस आधार पर समूहित करते हैं कि उनके विचार में प्रत्येक बीज कैसे यात्रा करता है, हवा, पानी या जंतुओं द्वारा, बीजों के आकारों से कारण देते हुए। जो प्रक्रिया-कौशल विकसित हो रहा है वह है:","optionsHi":["विभिन्न बीजों के सामान्य और स्थानीय नाम याद करना","संरचना से अनुमान लगाना कि कोई वस्तु कैसे कार्य करती है","बीजों की लंबाई और द्रव्यमान को सटीक रूप से मापना","पाठ्यपुस्तक में दिया गया बीज-वर्गीकरण नकल करना"],"explanationHi":"बच्चे पंख, काँटे या रेशेदार आवरण जैसी विशेषताओं से प्रकीर्णन के संभावित तरीके तक तर्क करते हैं, जो अनुमान है। यह न स्मरण है, न मापन।"},
  {"id":"cdp-pedagogy-subjects-1271","question":"Assertion (A): The theme ‘Things We Make and Do’ includes building, crafts and other activities people carry out around the child. Reason (R): The theme aims to help children appreciate processes, materials and the skills of people around them. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Activities such as building and crafts are included precisely so that children understand processes and value the skills and labour involved.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"अभिकथन (A): ‘हम जो बनाते और करते हैं’ विषय में निर्माण, शिल्प और अन्य गतिविधियाँ शामिल हैं जो बच्चे के आस-पास के लोग करते हैं। कारण (R): विषय का उद्देश्य बच्चों को अपने आस-पास के लोगों की प्रक्रियाओं, सामग्रियों और कौशलों की सराहना करने में मदद करना है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"निर्माण और शिल्प जैसी गतिविधियाँ इसीलिए शामिल की गई हैं ताकि बच्चे प्रक्रियाओं को समझें और उनमें लगे कौशल और श्रम को महत्त्व दें।"},
  {"id":"cdp-pedagogy-subjects-1272","question":"Which of these are good practices in teaching ‘Shelter’ in Class 4? I. Comparing houses in different climates and the reasons for their design. II. Discussing who builds houses and their working conditions. III. Telling children that pucca houses are always better than kachcha houses. IV. Looking at the homes of animals.","options":["I and II only","II and III only","I, III and IV only","I, II and IV only"],"answer":3,"explanation":"Kachcha houses of mud and bamboo are often well suited to local climate; calling pucca houses ‘always better’ is a value judgement EVS should question. The other three are sound practices.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 में ‘आश्रय’ पढ़ाने में इनमें से कौन-सी अच्छी प्रथाएँ हैं? I. विभिन्न जलवायु में घरों और उनके डिज़ाइन के कारणों की तुलना करना। II. इस पर चर्चा करना कि घर कौन बनाता है और उनकी कार्य-परिस्थितियाँ। III. बच्चों को बताना कि पक्के घर हमेशा कच्चे घरों से बेहतर होते हैं। IV. जंतुओं के घरों को देखना।","optionsHi":["केवल I और II","केवल II और III","केवल I, III और IV","केवल I, II और IV"],"explanationHi":"मिट्टी और बाँस के कच्चे घर प्रायः स्थानीय जलवायु के अनुकूल होते हैं; पक्के घरों को ‘हमेशा बेहतर’ कहना एक मूल्य-निर्णय है जिसे EVS को प्रश्नांकित करना चाहिए। अन्य तीन उचित प्रथाएँ हैं।"},
  {"id":"cdp-pedagogy-subjects-1273","question":"A teacher gives each group a sealed box containing an unknown object. Students may tilt, shake and weigh the box but never open it, and must describe what they think is inside and why. The main idea about the nature of science this activity teaches is that:","options":["Scientists can always check their answers by looking directly at the thing studied","Scientists often build models from indirect evidence, open to revision","Guessing is the same as scientific inference, so any idea is as good as another","There is always one right answer, and the teacher already knows it"],"answer":1,"explanation":"Like ideas about the atom or the earth's interior, students' ideas about the box rest on indirect evidence and stay tentative. The teacher should not open the box, so that the point is not lost.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"एक शिक्षक प्रत्येक समूह को एक बंद डिब्बा देता है जिसमें कोई अज्ञात वस्तु है। विद्यार्थी डिब्बे को झुका, हिला और तौल सकते हैं पर कभी खोल नहीं सकते, और उन्हें बताना है कि उनके विचार में अंदर क्या है और क्यों। यह गतिविधि विज्ञान की प्रकृति के बारे में कौन-सा मुख्य विचार सिखाती है:","optionsHi":["वैज्ञानिक अपने उत्तर हमेशा अध्ययन की जा रही वस्तु को सीधे देखकर जाँच सकते हैं","वैज्ञानिक प्रायः अप्रत्यक्ष साक्ष्य से मॉडल बनाते हैं, जो संशोधन के लिए खुले होते हैं","अनुमान लगाना वैज्ञानिक अनुमान (inference) के समान है, इसलिए कोई भी विचार दूसरे जितना अच्छा है","हमेशा एक ही सही उत्तर होता है, और शिक्षक उसे पहले से जानता है"],"explanationHi":"परमाणु या पृथ्वी के आंतरिक भाग के बारे में विचारों की तरह, डिब्बे के बारे में विद्यार्थियों के विचार अप्रत्यक्ष साक्ष्य पर टिके होते हैं और अस्थायी रहते हैं। शिक्षक को डिब्बा नहीं खोलना चाहिए, ताकि मुद्दा खो न जाए।"},
  {"id":"cdp-pedagogy-subjects-1274","question":"A student asks why astronomy is taught as a science but astrology is not. Which reason should the teacher help students arrive at?","options":["Astronomy is much older than astrology and has a far longer written history","Astronomy is taught in universities, so it must be a proper science","Astronomy makes testable claims and changes them when evidence disagrees","Astrology uses no mathematics at all, while astronomy uses a great deal"],"answer":2,"explanation":"Science is marked by testable claims and revision in the light of evidence. Age, prestige or the use of mathematics are not what make a field scientific.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"एक विद्यार्थी पूछता है कि खगोलशास्त्र को विज्ञान के रूप में क्यों पढ़ाया जाता है पर ज्योतिष को क्यों नहीं। शिक्षक को विद्यार्थियों को किस कारण तक पहुँचने में मदद करनी चाहिए?","optionsHi":["खगोलशास्त्र ज्योतिष से बहुत पुराना है और उसका लिखित इतिहास कहीं लंबा है","खगोलशास्त्र विश्वविद्यालयों में पढ़ाया जाता है, इसलिए वह उचित विज्ञान होगा","खगोलशास्त्र परीक्षण-योग्य दावे करता है और साक्ष्य असहमत होने पर उन्हें बदल देता है","ज्योतिष में बिल्कुल गणित का प्रयोग नहीं होता, जबकि खगोलशास्त्र में बहुत होता है"],"explanationHi":"विज्ञान की पहचान परीक्षण-योग्य दावे और साक्ष्य के प्रकाश में संशोधन है। आयु, प्रतिष्ठा या गणित का उपयोग किसी क्षेत्र को वैज्ञानिक नहीं बनाते।"},
  {"id":"cdp-pedagogy-subjects-1275","question":"In the 1840s, a doctor showed that deaths of mothers in a hospital fell sharply when doctors washed their hands, yet many colleagues rejected his findings for years. A teacher uses this story mainly to show students that:","options":["Doctors in the past did not care about their patients’ lives at all","Hand-washing is useful mainly in hospitals and not in daily life","Good evidence always convinces scientists immediately, whatever they believe","Acceptance of scientific ideas can be shaped by beliefs and social factors"],"answer":3,"explanation":"Semmelweis's evidence was resisted partly because it clashed with doctors' beliefs and there was no germ theory yet to explain it. The story shows science as a human, social enterprise, which is historical validity.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"1840 के दशक में एक चिकित्सक ने दिखाया कि जब डॉक्टर हाथ धोते थे तो एक अस्पताल में माताओं की मृत्यु तेज़ी से घटी, फिर भी उसके कई सहकर्मियों ने वर्षों तक उसके निष्कर्षों को अस्वीकार किया। एक शिक्षिका इस कहानी का उपयोग मुख्यतः विद्यार्थियों को यह दिखाने के लिए करती है कि:","optionsHi":["अतीत के डॉक्टर अपने रोगियों के जीवन की बिल्कुल परवाह नहीं करते थे","हाथ धोना मुख्यतः अस्पतालों में उपयोगी है, दैनिक जीवन में नहीं","अच्छा साक्ष्य हमेशा वैज्ञानिकों को तुरंत राज़ी कर देता है, उनकी मान्यताएँ चाहे जो हों","वैज्ञानिक विचारों की स्वीकृति मान्यताओं और सामाजिक कारकों से आकार ले सकती है"],"explanationHi":"सेमेल्विस के साक्ष्य का प्रतिरोध आंशिक रूप से इसलिए हुआ कि वह डॉक्टरों की मान्यताओं से टकराता था और उसे समझाने के लिए अभी कीटाणु-सिद्धांत नहीं था। कहानी विज्ञान को मानवीय, सामाजिक उद्यम के रूप में दिखाती है, जो ऐतिहासिक वैधता है।"},
  {"id":"cdp-pedagogy-subjects-1276","question":"Class 6 students fix a stick upright in the school ground and mark the tip of its shadow every hour from morning till afternoon. Which process skill does this activity develop most directly?","options":["Using space-time relationships","Classifying objects into groups","Forming and testing hypotheses","Controlling variables in a fair test"],"answer":0,"explanation":"Tracking how the position and length of the shadow change with time is the basic process skill of using space-time relationships, along with observing and recording.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा 6 के विद्यार्थी विद्यालय के मैदान में एक छड़ी सीधी गाड़ते हैं और सुबह से दोपहर तक हर घंटे उसकी परछाईं की नोक को चिह्नित करते हैं। यह गतिविधि सबसे सीधे कौन-सा प्रक्रिया-कौशल विकसित करती है?","optionsHi":["स्थान-काल संबंधों का उपयोग करना","वस्तुओं को समूहों में वर्गीकृत करना","परिकल्पनाएँ बनाना और उनका परीक्षण करना","निष्पक्ष परीक्षण में चरों को नियंत्रित करना"],"explanationHi":"समय के साथ परछाईं की स्थिति और लंबाई कैसे बदलती है, इसका पीछा करना, अवलोकन और अभिलेखन के साथ, स्थान-काल संबंधों के उपयोग का मूल प्रक्रिया-कौशल है।"},
  {"id":"cdp-pedagogy-subjects-1277","question":"Students are shown a picture of two sets of animal footprints in mud that come together, become confused, and then only one set continues. Groups give different stories of what happened. The main purpose of the activity is to show that:","options":["Only one story can be correct, and the teacher will reveal it at the end","The same observations can support more than one reasonable inference","Footprints are not useful evidence because they can be read in many ways","Students should avoid making inferences and only state what they observe"],"answer":1,"explanation":"What is seen (the tracks) is the same for all; the stories are inferences. Different reasonable inferences from the same data show why scientists look for more evidence before deciding.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"विद्यार्थियों को कीचड़ में जंतुओं के पदचिह्नों के दो समूहों का चित्र दिखाया जाता है जो एक साथ आते हैं, उलझ जाते हैं, और फिर केवल एक समूह आगे जाता है। समूह यह कहानी अलग-अलग बताते हैं कि क्या हुआ। गतिविधि का मुख्य उद्देश्य यह दिखाना है कि:","optionsHi":["केवल एक कहानी सही हो सकती है, और शिक्षक अंत में उसे बताएगा","एक ही अवलोकन एक से अधिक उचित अनुमानों का समर्थन कर सकते हैं","पदचिह्न उपयोगी साक्ष्य नहीं हैं क्योंकि उन्हें कई तरह से पढ़ा जा सकता है","विद्यार्थियों को अनुमान लगाने से बचना चाहिए और केवल वही बताना चाहिए जो वे देखते हैं"],"explanationHi":"जो देखा गया (पदचिह्न) सबके लिए समान है; कहानियाँ अनुमान हैं। एक ही आँकड़े से भिन्न उचित अनुमान दिखाते हैं कि निर्णय से पहले वैज्ञानिक अधिक साक्ष्य क्यों खोजते हैं।"},
  {"id":"cdp-pedagogy-subjects-1278","question":"To find the time period of a pendulum, the teacher asks students to time 20 oscillations and divide by 20, rather than timing just one. The main reason is that:","options":["One oscillation is too fast for students to count and time properly","Twenty oscillations make the pendulum settle and swing more regularly","It reduces the effect of errors in starting and stopping the watch","Timing more swings increases the time period of the pendulum"],"answer":2,"explanation":"The reaction-time error in starting and stopping the watch is about the same for 1 or 20 oscillations, so spreading it over 20 makes the error per oscillation much smaller.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"किसी लोलक का आवर्तकाल ज्ञात करने के लिए शिक्षक विद्यार्थियों से केवल एक दोलन के बजाय 20 दोलनों का समय नापने और 20 से भाग देने को कहता है। मुख्य कारण यह है कि:","optionsHi":["एक दोलन इतना तेज़ होता है कि विद्यार्थी उसे ठीक से गिन और नाप नहीं सकते","बीस दोलन करने से लोलक स्थिर होता है और अधिक नियमित रूप से झूलता है","यह घड़ी को शुरू और बंद करने की त्रुटियों के प्रभाव को घटाता है","अधिक झूलों का समय नापने से लोलक का आवर्तकाल बढ़ जाता है"],"explanationHi":"घड़ी को शुरू और बंद करने की प्रतिक्रिया-समय त्रुटि 1 या 20 दोलनों के लिए लगभग समान होती है, इसलिए उसे 20 पर बाँटने से प्रति दोलन त्रुटि बहुत कम हो जाती है।"},
  {"id":"cdp-pedagogy-subjects-1279","question":"Students investigate whether the length of a pendulum affects the time of one oscillation. Which of the following must they keep the same as a controlled variable?","options":["The length of the thread, so that each trial is a fair test","The time taken for one oscillation, so results can be compared","The number of students timing the swings in each group","The mass of the bob and the angle from which it is released"],"answer":3,"explanation":"Length is the independent variable and the time of an oscillation is the dependent variable; the bob's mass and the release angle must be kept constant so that only length changes.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"विद्यार्थी जाँच करते हैं कि क्या लोलक की लंबाई एक दोलन के समय को प्रभावित करती है। निम्नलिखित में से कौन-सा उन्हें नियंत्रित चर के रूप में समान रखना होगा?","optionsHi":["धागे की लंबाई, ताकि प्रत्येक परीक्षण निष्पक्ष हो","एक दोलन में लगा समय, ताकि परिणामों की तुलना हो सके","प्रत्येक समूह में झूलों का समय नापने वाले विद्यार्थियों की संख्या","गोलक का द्रव्यमान और वह कोण जिससे उसे छोड़ा जाता है"],"explanationHi":"लंबाई स्वतंत्र चर है और एक दोलन का समय आश्रित चर; गोलक का द्रव्यमान और छोड़ने का कोण स्थिर रखे जाने चाहिए ताकि केवल लंबाई बदले।"},
  {"id":"cdp-pedagogy-subjects-1280","question":"Each group tested one plant with fertiliser and one without; in one group the fertilised plant grew taller, and that group concluded that 'fertiliser makes all plants grow taller'. The main weakness in this conclusion is that:","options":["Only one plant was used in each condition, so chance could explain it","Fertiliser should never be used in school experiments with plants","The group should have chosen a faster-growing kind of plant for the test","The plants should have been measured only once, at the very end"],"answer":0,"explanation":"With one plant per condition, natural variation can produce a difference. Repeating with many plants, and comparing results across groups, makes the conclusion more reliable.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"प्रत्येक समूह ने एक पौधे को उर्वरक के साथ और एक को उसके बिना परखा; एक समूह में उर्वरक वाला पौधा अधिक ऊँचा बढ़ा, और उस समूह ने निष्कर्ष निकाला कि 'उर्वरक सभी पौधों को ऊँचा बढ़ाता है'। इस निष्कर्ष की मुख्य कमज़ोरी यह है कि:","optionsHi":["प्रत्येक स्थिति में केवल एक पौधा उपयोग हुआ, इसलिए संयोग इसे समझा सकता है","विद्यालय के प्रयोगों में पौधों के साथ उर्वरक का कभी उपयोग नहीं करना चाहिए","समूह को परीक्षण के लिए तेज़ी से बढ़ने वाली किस्म का पौधा चुनना चाहिए था","पौधों को केवल एक बार, बिल्कुल अंत में मापना चाहिए था"],"explanationHi":"प्रत्येक स्थिति में एक पौधे के साथ, प्राकृतिक विचलन अंतर पैदा कर सकता है। अनेक पौधों के साथ दोहराना, और समूहों के परिणामों की तुलना करना, निष्कर्ष को अधिक विश्वसनीय बनाता है।"},
  {"id":"cdp-pedagogy-subjects-1281","question":"Students note that in summer both the sale of cold drinks and the number of cases of heat-stroke go up. One student concludes that cold drinks cause heat-stroke. Which is the best response?","options":["Agreeing with the student, since the two rise together every summer","Asking if a third factor, such as hot weather, could cause both","Telling the student to stop drinking cold drinks during the hot months","Saying that data of this kind cannot tell us anything useful at all"],"answer":1,"explanation":"Two things rising together does not show that one causes the other; both can depend on a third factor. This teaches the difference between correlation and cause.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"विद्यार्थी देखते हैं कि गर्मियों में शीतल पेयों की बिक्री और लू लगने के मामलों की संख्या, दोनों बढ़ जाती हैं। एक विद्यार्थी निष्कर्ष निकालता है कि शीतल पेय लू का कारण बनते हैं। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["विद्यार्थी से सहमत होना, क्योंकि दोनों हर गर्मी में साथ बढ़ते हैं","पूछना कि क्या कोई तीसरा कारक, जैसे गर्म मौसम, दोनों का कारण हो सकता है","विद्यार्थी से कहना कि गर्मी के महीनों में शीतल पेय पीना बंद कर दे","कहना कि इस प्रकार के आँकड़े हमें कुछ भी उपयोगी नहीं बता सकते"],"explanationHi":"दो चीज़ों का साथ बढ़ना यह नहीं दिखाता कि एक दूसरे का कारण है; दोनों किसी तीसरे कारक पर निर्भर हो सकते हैं। इससे सहसंबंध और कारण का अंतर सिखाया जाता है।"},
  {"id":"cdp-pedagogy-subjects-1282","question":"During an investigation a student asks the teacher, 'Is my answer right?' The response that best supports inquiry is:","options":["'Yes, it is right; you can move on to the next step now.'","'No, it is wrong; check the answer given in the textbook.'","'What does your evidence show? How could you check it?'","'Ask the class topper whether she got the same answer.'"],"answer":2,"explanation":"In inquiry the evidence, not the teacher's authority, decides; turning the question back helps the student evaluate her own results.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"किसी जाँच के दौरान एक विद्यार्थी शिक्षक से पूछता है, 'क्या मेरा उत्तर सही है?' जिज्ञासा-आधारित अन्वेषण का सबसे अच्छा समर्थन करने वाली प्रतिक्रिया है:","optionsHi":["'हाँ, यह सही है; अब तुम अगले चरण पर जा सकते हो।'","'नहीं, यह गलत है; पाठ्यपुस्तक में दिया उत्तर जाँचो।'","'तुम्हारा साक्ष्य क्या दिखाता है? तुम इसे कैसे जाँच सकते हो?'","'कक्षा की टॉपर से पूछो कि क्या उसे भी यही उत्तर मिला।'"],"explanationHi":"जिज्ञासा-आधारित अन्वेषण में निर्णय शिक्षक के अधिकार से नहीं, साक्ष्य से होता है; प्रश्न को लौटाने से विद्यार्थी अपने परिणामों का स्वयं मूल्यांकन करने में सहायता पाता है।"},
  {"id":"cdp-pedagogy-subjects-1283","question":"While teaching crop production, a Class 8 teacher wants students to understand the Green Revolution in a balanced way. Which approach is most suitable?","options":["Presenting it only as a great success that put an end to India’s food shortages","Presenting it only as a disaster for soil, water and the environment","Asking students to memorise the year it began and the crops it involved","Weighing evidence on higher yields against harms such as falling groundwater"],"answer":3,"explanation":"A science-technology-society issue should be examined using evidence on both benefits and costs, helping students weigh trade-offs rather than adopting a one-sided view.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"फ़सल-उत्पादन पढ़ाते समय कक्षा 8 का शिक्षक चाहता है कि विद्यार्थी हरित क्रांति को संतुलित ढंग से समझें। कौन-सा उपागम सबसे उपयुक्त है?","optionsHi":["इसे केवल एक महान सफलता के रूप में प्रस्तुत करना जिसने भारत की खाद्य कमी को समाप्त कर दिया","इसे केवल मिट्टी, पानी और पर्यावरण के लिए आपदा के रूप में प्रस्तुत करना","विद्यार्थियों से वह वर्ष जब यह शुरू हुई और इसमें शामिल फ़सलें याद करवाना","भू-जल गिरने जैसी हानियों के विरुद्ध अधिक उपज के साक्ष्य को तौलना"],"explanationHi":"विज्ञान-प्रौद्योगिकी-समाज के किसी मुद्दे को लाभों और लागतों, दोनों के साक्ष्य के आधार पर परखा जाना चाहिए, जिससे विद्यार्थी एकपक्षीय दृष्टिकोण अपनाने के बजाय समझौतों को तौलना सीखते हैं।"},
  {"id":"cdp-pedagogy-subjects-1284","question":"A teacher keeps a 'science corner' with toys students made from waste, such as straw whistles, matchbox pull-carts and balloon-powered cars. The main value of this practice is that it:","options":["Shows science can be joyful with everyday materials and invites tinkering","Replaces the need for textbooks and written work in science lessons","Prepares students for the practical questions in competitive examinations","Keeps the classroom decorated and attractive for visitors and inspectors"],"answer":0,"explanation":"Toys from trash let students explore principles such as sound, friction and air pressure at little cost, and encourage tinkering and innovation.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"एक शिक्षक ‘विज्ञान कोना’ रखता है जिसमें विद्यार्थियों द्वारा कचरे से बनाए खिलौने हैं, जैसे तिनके की सीटियाँ, माचिस की डिब्बी की खींचने वाली गाड़ियाँ और गुब्बारे से चलने वाली कारें। इस प्रथा का मुख्य मूल्य यह है कि यह:","optionsHi":["दिखाती है कि विज्ञान रोज़मर्रा की सामग्री से आनंददायक हो सकता है और छेड़छाड़ (tinkering) को आमंत्रित करती है","विज्ञान के पाठों में पाठ्यपुस्तकों और लिखित कार्य की आवश्यकता को समाप्त कर देती है","प्रतियोगी परीक्षाओं में व्यावहारिक प्रश्नों के लिए विद्यार्थियों को तैयार करती है","आगंतुकों और निरीक्षकों के लिए कक्षा को सजी और आकर्षक रखती है"],"explanationHi":"कचरे से बने खिलौने विद्यार्थियों को कम लागत पर ध्वनि, घर्षण और वायु-दाब जैसे सिद्धांतों की खोज करने देते हैं, और छेड़छाड़ तथा नवाचार को प्रोत्साहित करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1285","question":"A Class 7 student has already mastered the concept of acids and bases while others are still working. What should the teacher provide?","options":["The same worksheet once more, to make sure that her learning is really secure","Nothing extra, so that she waits quietly for the others to finish","Enrichment, such as her own investigation of local flowers as indicators","The next chapter’s notes, so she can start memorising them early"],"answer":2,"explanation":"Enrichment deepens and extends learning for those who have mastered the basics, through open-ended, challenging tasks rather than repetition or idle waiting.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा 7 की एक विद्यार्थी अम्ल और क्षारक की संकल्पना में पहले ही निपुण हो चुकी है जबकि दूसरे अभी कार्य कर रहे हैं। शिक्षक को क्या उपलब्ध कराना चाहिए?","optionsHi":["वही कार्य-पत्र एक बार फिर, यह सुनिश्चित करने के लिए कि उसका अधिगम वास्तव में पक्का है","कुछ अतिरिक्त नहीं, ताकि वह दूसरों के समाप्त करने तक चुपचाप प्रतीक्षा करे","संवर्धन, जैसे सूचकों के रूप में स्थानीय फूलों की उसकी अपनी जाँच","अगले अध्याय के नोट्स, ताकि वह उन्हें जल्दी याद करना शुरू कर सके"],"explanationHi":"संवर्धन उन विद्यार्थियों के अधिगम को गहरा और विस्तृत करता है जिन्होंने मूल बातों में निपुणता पा ली है, दोहराव या निष्क्रिय प्रतीक्षा के बजाय खुले, चुनौतीपूर्ण कार्यों के माध्यम से।"},
  {"id":"cdp-pedagogy-subjects-1286","question":"Assertion (A): A teacher should begin teaching electric circuits from students' experience of torches and household switches. Reason (R): Learning proceeds best from the known to the unknown.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Torches and switches are familiar to students, so starting from them follows the maxim 'from known to unknown', which explains why the teacher should begin there.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"अभिकथन (A): शिक्षक को विद्युत परिपथ पढ़ाना टॉर्च और घरेलू स्विचों के विद्यार्थियों के अनुभव से आरंभ करना चाहिए। कारण (R): अधिगम सबसे अच्छी तरह ज्ञात से अज्ञात की ओर बढ़ता है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"टॉर्च और स्विच विद्यार्थियों के लिए परिचित हैं, इसलिए उनसे आरंभ करना 'ज्ञात से अज्ञात' के सूत्र का पालन करता है, जो समझाता है कि शिक्षक को वहीं से क्यों आरंभ करना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1287","question":"Match each method with its example. P. Project method  Q. Heuristic method  R. Lecture-demonstration  S. Problem-solving method. 1. The teacher shows a reaction of a small piece of sodium with water while explaining it  2. Students, with minimal hints, find out for themselves how to separate sand, salt and iron filings  3. The class sets up and runs a school weather station over a whole term  4. Students take up 'Why does tube-well water in our village taste salty?', form hypotheses and test them","options":["P-3, Q-4, R-1, S-2","P-4, Q-2, R-1, S-3","P-3, Q-2, R-4, S-1","P-3, Q-2, R-1, S-4"],"answer":3,"explanation":"A term-long purposeful real-life undertaking is a project; finding out with minimal guidance is heuristic; the teacher showing and explaining is lecture-demonstration; working systematically on a felt problem through hypotheses is problem-solving.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"प्रत्येक विधि को उसके उदाहरण से मिलाइए। P. परियोजना विधि Q. अन्वेषण विधि (heuristic method) R. व्याख्यान-प्रदर्शन S. समस्या-समाधान विधि। 1. शिक्षक सोडियम के छोटे टुकड़े की पानी के साथ अभिक्रिया दिखाता है और साथ में समझाता है 2. विद्यार्थी, न्यूनतम संकेतों के साथ, स्वयं पता लगाते हैं कि रेत, नमक और लौह-चूर्ण को कैसे अलग करें 3. कक्षा पूरे सत्र में विद्यालय का मौसम-केंद्र स्थापित करती और चलाती है 4. विद्यार्थी 'हमारे गाँव के नलकूप का पानी खारा क्यों है?' लेते हैं, परिकल्पनाएँ बनाते हैं और उनका परीक्षण करते हैं","optionsHi":["P-3, Q-4, R-1, S-2","P-4, Q-2, R-1, S-3","P-3, Q-2, R-4, S-1","P-3, Q-2, R-1, S-4"],"explanationHi":"सत्र भर चलने वाला उद्देश्यपूर्ण वास्तविक जीवन का उपक्रम परियोजना है; न्यूनतम मार्गदर्शन से खोजना अन्वेषण विधि है; शिक्षक का दिखाना और समझाना व्याख्यान-प्रदर्शन है; किसी अनुभव की गई समस्या पर परिकल्पनाओं के माध्यम से व्यवस्थित रूप से कार्य करना समस्या-समाधान है।"},
  {"id":"cdp-pedagogy-subjects-1288","question":"A teacher writes 'All metals expand on heating' on the board, and then shows the ring-and-ball experiment to illustrate it. This lesson follows:","options":["Inductive approach, moving from examples to a rule","Deductive approach, moving from a rule to examples","Heuristic approach, where students discover the rule","Project approach, where students plan their own work"],"answer":1,"explanation":"Stating a general rule first and then showing particular cases is deduction. An inductive lesson would begin with several cases and let students arrive at the rule.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"एक शिक्षक बोर्ड पर लिखता है 'सभी धातुएँ गर्म करने पर प्रसारित होती हैं', और फिर उसे स्पष्ट करने के लिए छल्ला-और-गोला प्रयोग दिखाता है। यह पाठ किसका अनुसरण करता है:","optionsHi":["आगमनात्मक उपागम, जो उदाहरणों से नियम की ओर बढ़ता है","निगमनात्मक उपागम, जो नियम से उदाहरणों की ओर बढ़ता है","अन्वेषण (heuristic) उपागम, जहाँ विद्यार्थी नियम की खोज करते हैं","परियोजना उपागम, जहाँ विद्यार्थी अपना कार्य स्वयं योजनाबद्ध करते हैं"],"explanationHi":"पहले सामान्य नियम बताना और फिर विशेष उदाहरण दिखाना निगमन है। आगमनात्मक पाठ कई उदाहरणों से आरंभ होता और विद्यार्थियों को स्वयं नियम तक पहुँचने देता।"},
  {"id":"cdp-pedagogy-subjects-1289","question":"Students believe that air has no weight because 'we cannot feel it pressing down'. Which activity gives them the most direct evidence?","options":["Fanning air towards their faces and feeling it push on the skin","Blowing up a balloon and letting it go so that it flies across the room","Balancing two blown-up balloons on a stick, then pricking one","Watching leaves and branches move about in a strong wind"],"answer":2,"explanation":"When one balloon loses its air, the balance tilts towards the still-inflated balloon, showing that the air inside it has weight. The other activities show that air moves, not that it has weight.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"विद्यार्थी मानते हैं कि हवा का कोई भार नहीं होता क्योंकि 'हम उसका दबना महसूस नहीं कर सकते'। कौन-सी गतिविधि उन्हें सबसे सीधा साक्ष्य देती है?","optionsHi":["हवा को अपने चेहरे की ओर झलना और त्वचा पर उसका धक्का महसूस करना","गुब्बारे को फुलाकर छोड़ देना ताकि वह कमरे में उड़ जाए","दो फुलाए गुब्बारों को छड़ी पर संतुलित करना, फिर एक में सुई चुभोना","तेज़ हवा में पत्तियों और डालियों को हिलते देखना"],"explanationHi":"जब एक गुब्बारे की हवा निकल जाती है, तो तराजू अब भी फूले हुए गुब्बारे की ओर झुकता है, जो दिखाता है कि उसके अंदर की हवा का भार है। अन्य गतिविधियाँ दिखाती हैं कि हवा चलती है, यह नहीं कि उसका भार है।"},
  {"id":"cdp-pedagogy-subjects-1290","question":"A teacher fills a glass to the brim with water, covers it with a postcard and turns it upside down; the card stays in place. Which student idea is this demonstration most likely to challenge?","options":["Water is heavier than the same volume of air","Liquids take the shape of the container they are in","Water always flows downwards when nothing holds it","Air pushes only downwards, not upwards or sideways"],"answer":3,"explanation":"The card is held up by air pressing upward on it, which contradicts the common idea that air pressure acts only downwards. Air pressure acts in all directions.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"एक शिक्षक काँच को पानी से लबालब भरता है, उसे पोस्टकार्ड से ढकता है और उलट देता है; कार्ड अपनी जगह टिका रहता है। यह प्रदर्शन विद्यार्थियों के किस विचार को सबसे अधिक चुनौती देने की संभावना रखता है?","optionsHi":["पानी उसी आयतन की हवा से भारी होता है","द्रव जिस पात्र में हों उसका आकार ले लेते हैं","जब कुछ न रोके तो पानी हमेशा नीचे की ओर बहता है","हवा केवल नीचे की ओर दबाव डालती है, ऊपर या बगल की ओर नहीं"],"explanationHi":"कार्ड को हवा ऊपर की ओर दबाकर थामे रखती है, जो इस सामान्य विचार का खंडन करता है कि वायु-दाब केवल नीचे की ओर कार्य करता है। वायु-दाब सभी दिशाओं में कार्य करता है।"},
  {"id":"cdp-pedagogy-subjects-1291","question":"A Class 6 student argues that fire is a living thing because 'it grows, moves and needs air'. The most productive way for the teacher to use this is to:","options":["Have the class test fire against other signs of life, like cells and reproduction","Tell the student firmly that fire is not a living thing and move on to the next topic","Accept the argument, since every feature the student mentioned is correct","Avoid the question, since it may confuse other students before the exam"],"answer":0,"explanation":"The argument uses some real features of life; testing fire against the full set of characteristics refines the concept of 'living' for the whole class.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"कक्षा 6 का एक विद्यार्थी तर्क देता है कि आग एक सजीव वस्तु है क्योंकि 'वह बढ़ती है, चलती है और उसे हवा चाहिए'। शिक्षक के इसका सबसे उत्पादक उपयोग करने का तरीका है:","optionsHi":["कक्षा से आग को जीवन के अन्य लक्षणों, जैसे कोशिकाओं और जनन, के विरुद्ध परखवाना","विद्यार्थी को दृढ़ता से बताना कि आग सजीव नहीं है और अगले विषय पर बढ़ जाना","तर्क को स्वीकार करना, क्योंकि विद्यार्थी द्वारा बताई हर विशेषता सही है","प्रश्न से बचना, क्योंकि वह परीक्षा से पहले दूसरे विद्यार्थियों को भ्रमित कर सकता है"],"explanationHi":"यह तर्क जीवन की कुछ वास्तविक विशेषताओं का उपयोग करता है; आग को लक्षणों के पूरे समूह के विरुद्ध परखना पूरी कक्षा के लिए 'सजीव' की संकल्पना को परिष्कृत करता है।"},
  {"id":"cdp-pedagogy-subjects-1292","question":"A Class 8 lesson on water purification has students test local purification methods they designed themselves, explains how chlorination came into use, and uses simple language suited to them. Which NCF 2005 criterion does the lesson NOT clearly address, as described?","options":["Process validity","Historical validity","Ethical validity","Cognitive validity"],"answer":2,"explanation":"Designing tests serves process validity, the history of chlorination serves historical validity, and suitable language serves cognitive validity. Nothing in the description deals with values such as honesty or concern for life.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा 8 का जल-शोधन पर एक पाठ विद्यार्थियों से उनके अपने बनाए स्थानीय शोधन-तरीकों का परीक्षण करवाता है, बताता है कि क्लोरीनीकरण का उपयोग कैसे आरंभ हुआ, और उनके अनुकूल सरल भाषा का उपयोग करता है। जैसा वर्णित है, यह पाठ NCF 2005 के किस मानदंड को स्पष्ट रूप से संबोधित नहीं करता?","optionsHi":["प्रक्रिया-वैधता","ऐतिहासिक वैधता","नैतिक वैधता","संज्ञानात्मक वैधता"],"explanationHi":"परीक्षण बनाना प्रक्रिया-वैधता को पूरा करता है, क्लोरीनीकरण का इतिहास ऐतिहासिक वैधता को, और उपयुक्त भाषा संज्ञानात्मक वैधता को। वर्णन में ईमानदारी या जीवन के प्रति चिंता जैसे मूल्यों से संबंधित कुछ नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1293","question":"Students say that the moon gives out its own light. Which observation, discussed in class, best challenges this idea?","options":["The moon looks much bigger when it is low near the horizon at night","The moon can sometimes be seen clearly in the daytime sky","The moon's lit side always faces the sun, and its lit part changes","The moon is much closer to the earth than any of the stars"],"answer":2,"explanation":"If the moon made its own light, the whole disc would always glow. The lit side facing the sun, and the changing lit part, shows that it reflects sunlight.","difficulty":"hard","source":"CTET Paper 2 · state TETs · KVS","questionHi":"विद्यार्थी कहते हैं कि चंद्रमा अपना प्रकाश स्वयं देता है। कक्षा में चर्चित कौन-सा अवलोकन इस विचार को सबसे अच्छी तरह चुनौती देता है?","optionsHi":["रात में जब चंद्रमा क्षितिज के पास नीचा होता है तो वह बहुत बड़ा दिखता है","चंद्रमा कभी-कभी दिन के आकाश में स्पष्ट देखा जा सकता है","चंद्रमा का प्रकाशित पक्ष हमेशा सूर्य की ओर होता है, और उसका प्रकाशित भाग बदलता रहता है","चंद्रमा किसी भी तारे की तुलना में पृथ्वी के बहुत निकट है"],"explanationHi":"यदि चंद्रमा अपना प्रकाश स्वयं बनाता, तो पूरी तश्तरी हमेशा चमकती। सूर्य की ओर का प्रकाशित पक्ष और बदलता प्रकाशित भाग दिखाते हैं कि वह सूर्य के प्रकाश को परावर्तित करता है।"},
  {"id":"cdp-pedagogy-subjects-1294","question":"Which of the following practices is most likely to create the misconception that science is only done by people in laboratories?","options":["Inviting a local farmer to explain how she decides the right time to sow","Taking students to watch a potter at work and discussing the changes in the clay","Asking students to investigate questions that arise in their own homes","Teaching science only through textbook lab experiments, unlinked to outside work"],"answer":3,"explanation":"Linking science to everyday work and life shows that scientific thinking is used widely. Confining it to laboratory experiments alone reinforces the narrow image.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"निम्नलिखित में से कौन-सी प्रथा यह भ्रांति पैदा करने की सबसे अधिक संभावना रखती है कि विज्ञान केवल प्रयोगशालाओं में काम करने वाले लोग करते हैं?","optionsHi":["स्थानीय किसान को आमंत्रित करना कि वह बताए कि बुवाई का सही समय कैसे तय करती है","विद्यार्थियों को कुम्हार का कार्य देखने ले जाना और मिट्टी में होने वाले परिवर्तनों पर चर्चा करना","विद्यार्थियों से उन प्रश्नों की जाँच करवाना जो उनके अपने घरों में उठते हैं","विज्ञान को केवल पाठ्यपुस्तक के प्रयोगशाला-प्रयोगों से पढ़ाना, बाहर के कार्य से जोड़े बिना"],"explanationHi":"विज्ञान को रोज़मर्रा के कार्य और जीवन से जोड़ना दिखाता है कि वैज्ञानिक चिंतन का उपयोग व्यापक रूप से होता है। उसे केवल प्रयोगशाला-प्रयोगों तक सीमित रखना संकीर्ण छवि को पुष्ट करता है।"},
  {"id":"cdp-pedagogy-subjects-1295","question":"Which activity best shows students the role of controlled conditions in scientific investigation?","options":["Comparing a test where two variables changed at once with one where only one did","Copying the steps of a well-known experiment from the board neatly into notebooks","Watching a video on a famous experiment and noting down its main result","Writing a report on the life and discoveries of a famous scientist"],"answer":0,"explanation":"Comparing a confounded test with a fair one shows students that when two things change together, it is impossible to say which caused the result.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"कौन-सी गतिविधि विद्यार्थियों को वैज्ञानिक जाँच में नियंत्रित स्थितियों की भूमिका सबसे अच्छी तरह दिखाती है?","optionsHi":["उस परीक्षण की तुलना करना जिसमें दो चर एक साथ बदले, उस परीक्षण से जिसमें केवल एक बदला","किसी प्रसिद्ध प्रयोग के चरण बोर्ड से अपनी कॉपियों में साफ़-साफ़ नकल करना","किसी प्रसिद्ध प्रयोग पर वीडियो देखना और उसका मुख्य परिणाम लिख लेना","किसी प्रसिद्ध वैज्ञानिक के जीवन और खोजों पर रिपोर्ट लिखना"],"explanationHi":"गड़बड़ाए हुए (confounded) परीक्षण की निष्पक्ष परीक्षण से तुलना विद्यार्थियों को दिखाती है कि जब दो चीज़ें साथ बदलती हैं, तो यह कहना असंभव है कि परिणाम किसने किया।"},
  {"id":"cdp-pedagogy-subjects-1296","question":"Consider these statements about inquiry-based science. 1. Students' questions can drive the investigation. 2. Students use evidence to construct explanations. 3. The teacher acts mainly as a facilitator. 4. Every investigation must end with the result given in the textbook. Which are correct?","options":["1 and 4 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"Inquiry puts students' questions and evidence at the centre, with the teacher as a guide. Insisting on a predetermined textbook result reduces inquiry to confirmation.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"जिज्ञासा-आधारित (inquiry-based) विज्ञान के बारे में इन कथनों पर विचार कीजिए। 1. विद्यार्थियों के प्रश्न जाँच को आगे बढ़ा सकते हैं। 2. विद्यार्थी साक्ष्य का उपयोग करके व्याख्याएँ बनाते हैं। 3. शिक्षक मुख्यतः सुगमकर्ता के रूप में कार्य करता है। 4. प्रत्येक जाँच का अंत पाठ्यपुस्तक में दिए परिणाम के साथ होना चाहिए। कौन-से सही हैं?","optionsHi":["केवल 1 और 4","केवल 1, 2 और 3","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"जिज्ञासा-आधारित अन्वेषण विद्यार्थियों के प्रश्नों और साक्ष्य को केंद्र में रखता है, शिक्षक को मार्गदर्शक के रूप में। पूर्वनिर्धारित पाठ्यपुस्तक-परिणाम पर ज़ोर देना जिज्ञासा-आधारित अन्वेषण को पुष्टि तक सीमित कर देता है।"},
  {"id":"cdp-pedagogy-subjects-1297","question":"A teacher finds that students in her class think rainbows are 'objects in the sky' at a fixed place. Which activity best helps them revise the idea?","options":["Drawing a rainbow in the sky with all seven colours in the correct order","Making a ‘rainbow’ with a water spray and noticing it moves as they move","Memorising VIBGYOR so that the order of colours is never forgotten","Reading and discussing a poem about how rainbows appear in the sky"],"answer":1,"explanation":"A spray rainbow appears only at a certain angle between the sun, the drops and the observer, and it shifts as the observer moves, which shows it is an effect of light, not an object.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"एक शिक्षिका पाती है कि उसकी कक्षा के विद्यार्थी सोचते हैं कि इंद्रधनुष एक निश्चित स्थान पर 'आकाश में वस्तुएँ' हैं। कौन-सी गतिविधि उन्हें इस विचार को संशोधित करने में सबसे अच्छी मदद करती है?","optionsHi":["आकाश में सभी सात रंगों को सही क्रम में लेकर इंद्रधनुष बनाना","पानी की फुहार से 'इंद्रधनुष' बनाना और ध्यान देना कि वह उनके चलने के साथ हिलता है","VIBGYOR याद करना ताकि रंगों का क्रम कभी न भूलें","एक कविता पढ़ना और उस पर चर्चा करना कि आकाश में इंद्रधनुष कैसे प्रकट होते हैं"],"explanationHi":"फुहार का इंद्रधनुष केवल सूर्य, बूँदों और प्रेक्षक के बीच एक निश्चित कोण पर दिखता है, और प्रेक्षक के चलने पर खिसकता है, जो दिखाता है कि वह प्रकाश का प्रभाव है, वस्तु नहीं।"},
  {"id":"cdp-pedagogy-subjects-1298","question":"Match each teaching method with the classroom example that best fits it.\nMethods: (P) Source method (Q) Survey (R) Simulation (S) Case study\nExamples: (1) Students hold a mock gram sabha on a drainage problem (2) Students read an extract from a 1930s petition and answer questions on it (3) Students study in depth one farmer's experience of taking a loan (4) Students ask 40 households how they get drinking water","options":["P-2, Q-4, R-1, S-3","P-3, Q-4, R-1, S-2","P-2, Q-1, R-4, S-3","P-4, Q-2, R-3, S-1"],"answer":0,"explanation":"Working with an original extract is the source method; collecting data from many households is a survey; a mock gram sabha simulates a real process; studying one farmer's situation in depth is a case study.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"प्रत्येक शिक्षण-विधि को उस कक्षा-उदाहरण से मिलाइए जो उसके सबसे अनुरूप हो।\nविधियाँ: (P) स्रोत विधि (Q) सर्वेक्षण (R) अनुकरण (S) केस अध्ययन\nउदाहरण: (1) विद्यार्थी जल-निकासी की समस्या पर नकली ग्राम सभा करते हैं (2) विद्यार्थी 1930 के दशक की एक याचिका का अंश पढ़ते हैं और उस पर प्रश्नों के उत्तर देते हैं (3) विद्यार्थी ऋण लेने के एक किसान के अनुभव का गहराई से अध्ययन करते हैं (4) विद्यार्थी 40 परिवारों से पूछते हैं कि उन्हें पीने का पानी कैसे मिलता है","optionsHi":["P-2, Q-4, R-1, S-3","P-3, Q-4, R-1, S-2","P-2, Q-1, R-4, S-3","P-4, Q-2, R-3, S-1"],"explanationHi":"मूल अंश के साथ कार्य करना स्रोत विधि है; अनेक परिवारों से आँकड़े एकत्र करना सर्वेक्षण है; नकली ग्राम सभा एक वास्तविक प्रक्रिया का अनुकरण है; एक किसान की स्थिति का गहराई से अध्ययन केस अध्ययन है।"},
  {"id":"cdp-pedagogy-subjects-1299","question":"After keeping a weather diary for June, a Class VII student writes, 'Our town has a rainy climate, because it rained on 22 days this month.' What should the teacher help the student understand?","options":["That the conclusion is correct, since rain on 22 days is a large number","That a weather diary is not a valid activity in the study of geography","That rainfall has nothing to do with climate, which depends only on temperature","That one month’s record shows weather; climate is the pattern over many years"],"answer":3,"explanation":"Weather is the day-to-day state of the atmosphere; climate is the long-term pattern. Generalising from one monsoon month confuses the two. The diary itself is a valuable activity; the inference needs correcting.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · NVS","questionHi":"जून का मौसम-दैनिकी रखने के बाद कक्षा VII का एक विद्यार्थी लिखता है, 'हमारे कस्बे की जलवायु वर्षा वाली है, क्योंकि इस महीने 22 दिन बारिश हुई।' शिक्षक को विद्यार्थी को क्या समझने में मदद करनी चाहिए?","optionsHi":["कि निष्कर्ष सही है, क्योंकि 22 दिन बारिश होना बड़ी संख्या है","कि भूगोल के अध्ययन में मौसम-दैनिकी वैध गतिविधि नहीं है","कि वर्षा का जलवायु से कोई संबंध नहीं है, जो केवल तापमान पर निर्भर है","कि एक महीने का अभिलेख मौसम दिखाता है; जलवायु अनेक वर्षों का प्रतिरूप है"],"explanationHi":"मौसम वायुमंडल की दिन-प्रतिदिन की अवस्था है; जलवायु दीर्घकालिक प्रतिरूप है। एक मानसूनी महीने से सामान्यीकरण दोनों को भ्रमित करता है। दैनिकी स्वयं मूल्यवान गतिविधि है; अनुमान को सुधारने की आवश्यकता है।"},
  {"id":"cdp-pedagogy-subjects-1300","question":"Class VII students in a Maharashtra village collect soil from a riverbank, a field and a hill slope and compare their colour, texture and how fast they absorb water. What is the main aim of this field work?","options":["To learn the scientific names of the different minerals present in each soil","To see first-hand that soils differ from place to place, and ask why","To collect soil samples for use in the school’s science laboratory","To prepare an attractive decorative display for the annual day"],"answer":1,"explanation":"Geography field work develops observation and inquiry: noticing differences in the real environment and asking what causes them. Naming minerals is not the aim at this stage.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"महाराष्ट्र के एक गाँव के कक्षा VII के विद्यार्थी नदी-तट, खेत और पहाड़ी ढलान से मिट्टी इकट्ठा करते हैं और उनके रंग, बनावट और पानी सोखने की गति की तुलना करते हैं। इस क्षेत्र-कार्य का मुख्य उद्देश्य क्या है?","optionsHi":["प्रत्येक मिट्टी में मौजूद विभिन्न खनिजों के वैज्ञानिक नाम सीखना","प्रत्यक्ष रूप से देखना कि मिट्टियाँ स्थान-स्थान पर भिन्न होती हैं, और पूछना कि क्यों","विद्यालय की विज्ञान प्रयोगशाला में उपयोग के लिए मिट्टी के नमूने एकत्र करना","वार्षिकोत्सव के लिए आकर्षक सजावटी प्रदर्शन तैयार करना"],"explanationHi":"भूगोल का क्षेत्र-कार्य अवलोकन और जिज्ञासा-आधारित अन्वेषण विकसित करता है: वास्तविक पर्यावरण में अंतर देखना और पूछना कि उनका कारण क्या है। इस अवस्था में खनिजों के नाम बताना उद्देश्य नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1301","question":"A Class VIII teacher asks groups to take each key word of the Preamble, such as justice, liberty, equality and fraternity, and find an example from school or community life where it is respected or violated. What does this approach achieve?","options":["It helps students memorise the whole Preamble word for word","It removes the need to study the rest of the Constitution in detail","It links abstract constitutional ideals to situations students know","It shows students that the Preamble has no legal value in courts"],"answer":2,"explanation":"Applying each ideal to real situations turns abstract words into lived meaning and invites judgement about whether ideals are realised. Memorisation is not the aim.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा VIII की एक शिक्षिका समूहों से उद्देशिका के प्रत्येक मुख्य शब्द, जैसे न्याय, स्वतंत्रता, समता और बंधुता, को लेकर विद्यालय या समुदाय के जीवन से ऐसा उदाहरण खोजने को कहती है जहाँ उसका सम्मान किया गया हो या उल्लंघन हुआ हो। यह उपागम क्या प्राप्त करता है?","optionsHi":["यह विद्यार्थियों को पूरी उद्देशिका शब्दशः याद करने में मदद करता है","यह संविधान के शेष भाग का विस्तार से अध्ययन करने की आवश्यकता को समाप्त करता है","यह अमूर्त संवैधानिक आदर्शों को उन परिस्थितियों से जोड़ता है जिन्हें विद्यार्थी जानते हैं","यह विद्यार्थियों को दिखाता है कि उद्देशिका का न्यायालयों में कोई वैधानिक मूल्य नहीं है"],"explanationHi":"प्रत्येक आदर्श को वास्तविक परिस्थितियों पर लागू करना अमूर्त शब्दों को जिए गए अर्थ में बदलता है और इस पर निर्णय के लिए आमंत्रित करता है कि आदर्श साकार हुए या नहीं। रटना उद्देश्य नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1302","question":"Class VIII students argue that the freedom of speech means 'we can say anything about anyone, anywhere'. Which response best develops a correct understanding?","options":["Discuss cases showing the right is protected but has reasonable limits","Agree with the students, since fundamental rights can never be limited","Tell them that free speech is not really a protected right in India","Ask them to memorise the article number of the right for the exam"],"answer":0,"explanation":"Fundamental rights are vital but not absolute; the Constitution allows reasonable restrictions on grounds such as defamation, public order and incitement. Cases show why such limits exist and how they are judged.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा VIII के विद्यार्थी तर्क देते हैं कि वाक्-स्वातंत्र्य का अर्थ है 'हम किसी के बारे में, कहीं भी, कुछ भी कह सकते हैं'। कौन-सी प्रतिक्रिया सही समझ को सबसे अच्छी तरह विकसित करती है?","optionsHi":["उन मामलों पर चर्चा करना जो दिखाते हैं कि अधिकार संरक्षित है पर उसकी उचित सीमाएँ हैं","विद्यार्थियों से सहमत होना, क्योंकि मौलिक अधिकार कभी सीमित नहीं किए जा सकते","उन्हें बताना कि भारत में वाक्-स्वातंत्र्य वास्तव में संरक्षित अधिकार नहीं है","उनसे परीक्षा के लिए उस अधिकार का अनुच्छेद-संख्या याद करने को कहना"],"explanationHi":"मौलिक अधिकार महत्त्वपूर्ण हैं पर निरपेक्ष नहीं; संविधान मानहानि, लोक व्यवस्था और उकसावे जैसे आधारों पर उचित निर्बंधन की अनुमति देता है। मामले दिखाते हैं कि ऐसी सीमाएँ क्यों हैं और उनका निर्णय कैसे होता है।"},
  {"id":"cdp-pedagogy-subjects-1303","question":"Class X students interview working people in their area and classify each job by whether it offers a regular salary, paid leave and job security. Which economic concept does this activity mainly help them understand?","options":["Per capita income and how it is worked out for a whole region","The difference between the organised and unorganised sectors","Inflation and how rising prices affect the wages of workers","Foreign trade and how it creates jobs in the local area"],"answer":1,"explanation":"Job security, paid leave and regular wages are the features that distinguish organised from unorganised employment. Real interviews make the distinction, and the vulnerability of unorganised workers, concrete.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS","questionHi":"कक्षा X के विद्यार्थी अपने क्षेत्र के कामकाजी लोगों का साक्षात्कार करते हैं और प्रत्येक काम को इस आधार पर वर्गीकृत करते हैं कि उसमें नियमित वेतन, सवेतन अवकाश और रोज़गार-सुरक्षा है या नहीं। यह गतिविधि उन्हें मुख्यतः किस आर्थिक संकल्पना को समझने में मदद करती है?","optionsHi":["प्रति व्यक्ति आय और उसे पूरे क्षेत्र के लिए कैसे निकाला जाता है","संगठित और असंगठित क्षेत्रकों का अंतर","मुद्रास्फीति और बढ़ती कीमतें श्रमिकों की मज़दूरी को कैसे प्रभावित करती हैं","विदेशी व्यापार और वह स्थानीय क्षेत्र में रोज़गार कैसे बनाता है"],"explanationHi":"रोज़गार-सुरक्षा, सवेतन अवकाश और नियमित मज़दूरी वे विशेषताएँ हैं जो संगठित को असंगठित रोज़गार से अलग करती हैं। वास्तविक साक्षात्कार अंतर और असंगठित श्रमिकों की असुरक्षितता को मूर्त बनाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1304","question":"A Class VII teacher asks, 'In what ways are weekly markets today like the markets of medieval times, and in what ways are they different?' Which historical concept is she developing?","options":["Causation","Chronology","Historical significance","Change and continuity"],"answer":3,"explanation":"Asking what has changed and what has stayed the same over time develops the concept of change and continuity. Causation would ask why something happened.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VII की एक शिक्षिका पूछती है, 'आज के साप्ताहिक बाज़ार मध्यकाल के बाज़ारों से किन बातों में समान हैं, और किन बातों में भिन्न?' वह किस ऐतिहासिक संकल्पना को विकसित कर रही है?","optionsHi":["कारणता","कालक्रम","ऐतिहासिक महत्त्व","परिवर्तन और निरंतरता"],"explanationHi":"यह पूछना कि समय के साथ क्या बदला और क्या वैसा ही रहा, परिवर्तन और निरंतरता की संकल्पना को विकसित करता है। कारणता पूछती कि कोई चीज़ क्यों हुई।"},
  {"id":"cdp-pedagogy-subjects-1305","question":"A Class VIII student writes, 'The British won the Battle of Plassey only because Mir Jafar betrayed Siraj-ud-daulah.' What should the teacher encourage?","options":["Accept the answer as complete, since the betrayal is a historical fact","Mark it wrong, since Mir Jafar’s betrayal is only a popular myth","Ask the student to memorise the date of the battle instead","Explore other causes too, like Company ambitions and court rivalries"],"answer":3,"explanation":"The betrayal was real, but historical events usually have several interacting causes. Moving from a single cause to multiple causes is a key step in historical reasoning; rejecting the fact would be wrong.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा VIII का एक विद्यार्थी लिखता है, 'अंग्रेज़ों ने प्लासी का युद्ध केवल इसलिए जीता क्योंकि मीर जाफ़र ने सिराजुद्दौला को धोखा दिया।' शिक्षक को क्या प्रोत्साहित करना चाहिए?","optionsHi":["उत्तर को पूर्ण स्वीकार करना, क्योंकि विश्वासघात एक ऐतिहासिक तथ्य है","इसे गलत अंकित करना, क्योंकि मीर जाफ़र का विश्वासघात केवल एक लोकप्रिय मिथक है","विद्यार्थी से इसके बजाय युद्ध की तिथि याद करने को कहना","अन्य कारणों की भी पड़ताल करना, जैसे कंपनी की महत्त्वाकांक्षाएँ और दरबारी प्रतिद्वंद्विताएँ"],"explanationHi":"विश्वासघात वास्तविक था, पर ऐतिहासिक घटनाओं के प्रायः कई परस्पर क्रिया करने वाले कारण होते हैं। एक कारण से अनेक कारणों की ओर बढ़ना ऐतिहासिक तर्क का मुख्य कदम है; तथ्य को अस्वीकार करना गलत होगा।"},
  {"id":"cdp-pedagogy-subjects-1306","question":"Class VIII students trace where their town's electricity comes from: a power station, coal from a mine in another state, and the railway that brings it. What understanding does this activity mainly build?","options":["Regions depend on each other, and resource use in one place affects others","Electricity used in a town is always produced inside the limits of that same town","Coal is a renewable resource that can be mined without any limit","Every region produces all the resources that its own people need"],"answer":0,"explanation":"Tracing a resource reveals interdependence between regions and the hidden costs of consumption, such as mining in faraway areas. The distractors are factual errors or the opposite of what the activity shows.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VIII के विद्यार्थी पता लगाते हैं कि उनके कस्बे की बिजली कहाँ से आती है: एक बिजलीघर, दूसरे राज्य की खदान से कोयला, और उसे लाने वाली रेलवे। यह गतिविधि मुख्यतः कौन-सी समझ बनाती है?","optionsHi":["क्षेत्र एक-दूसरे पर निर्भर हैं, और एक स्थान पर संसाधन का उपयोग दूसरों को प्रभावित करता है","कस्बे में उपयोग होने वाली बिजली हमेशा उसी कस्बे की सीमाओं के भीतर उत्पन्न होती है","कोयला एक नवीकरणीय संसाधन है जिसे बिना किसी सीमा के खनन किया जा सकता है","प्रत्येक क्षेत्र वे सभी संसाधन उत्पन्न करता है जो उसके अपने लोगों को चाहिए"],"explanationHi":"किसी संसाधन का पीछा करना क्षेत्रों के बीच अंतर-निर्भरता और उपभोग की छिपी लागतों, जैसे दूर क्षेत्रों में खनन, को प्रकट करता है। अन्य विकल्प तथ्यात्मक त्रुटियाँ हैं या गतिविधि जो दिखाती है उसके विपरीत हैं।"},
  {"id":"cdp-pedagogy-subjects-1307","question":"For a Class X lesson on consumer rights, students bring packets from home and examine the MRP, the expiry date, quality certification marks and the address for complaints. This approach is best described as:","options":["Lecture-based learning led mainly by the teacher","Rote learning of the main consumer protection laws","Experiential learning linked to everyday life","Programmed learning in small, fixed steps"],"answer":2,"explanation":"Examining real products lets students discover consumer information for themselves and links rights to their own purchases. That is experiential, life-linked learning.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"उपभोक्ता अधिकारों पर कक्षा X के पाठ के लिए विद्यार्थी घर से पैकेट लाते हैं और MRP, समाप्ति तिथि, गुणवत्ता-प्रमाणन चिह्न और शिकायत के पते की जाँच करते हैं। इस उपागम का सबसे अच्छा वर्णन है:","optionsHi":["शिक्षक द्वारा मुख्यतः संचालित व्याख्यान-आधारित अधिगम","मुख्य उपभोक्ता संरक्षण कानूनों का रटंत अधिगम","दैनिक जीवन से जुड़ा अनुभवात्मक अधिगम","छोटे, निश्चित चरणों में अभिक्रमित अधिगम"],"explanationHi":"वास्तविक उत्पादों की जाँच विद्यार्थियों को उपभोक्ता जानकारी स्वयं खोजने देती है और अधिकारों को उनकी अपनी खरीदारी से जोड़ती है। यह अनुभवात्मक, जीवन से जुड़ा अधिगम है।"},
  {"id":"cdp-pedagogy-subjects-1308","question":"A Class IX teacher plans a lesson on earthquake safety. Which activity is most effective?","options":["Reading aloud the textbook section on the causes of earthquakes","Students map safe spots and exits in their school, then hold a mock drill","Memorising the Richter scale readings of major past earthquakes","Writing a long essay describing the terrible destruction caused by earthquakes"],"answer":1,"explanation":"Disaster preparedness is practical knowledge. Mapping one's own school and practising a drill builds skills students can use; reading or essays alone do not.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"कक्षा IX का एक शिक्षक भूकंप-सुरक्षा पर पाठ की योजना बनाता है। कौन-सी गतिविधि सबसे प्रभावी है?","optionsHi":["भूकंप के कारणों पर पाठ्यपुस्तक के खंड को ज़ोर से पढ़ना","विद्यार्थी अपने विद्यालय में सुरक्षित स्थानों और निकास का मानचित्र बनाएँ, फिर नकली अभ्यास (मॉक ड्रिल) करें","पिछले प्रमुख भूकंपों के रिक्टर पैमाने के पाठ्यांक याद करना","भूकंप से होने वाले भयानक विनाश का वर्णन करता लंबा निबंध लिखना"],"explanationHi":"आपदा-तैयारी व्यावहारिक ज्ञान है। अपने विद्यालय का मानचित्र बनाना और अभ्यास करना ऐसे कौशल बनाता है जिन्हें विद्यार्थी उपयोग कर सकते हैं; केवल पढ़ना या निबंध नहीं।"},
  {"id":"cdp-pedagogy-subjects-1309","question":"A Class VI teacher holds a mock election for class monitor, with nomination, campaign speeches, a secret ballot and counting. What must follow to make it a social science lesson rather than just a class event?","options":["Announce the winner and then continue with the next chapter from the textbook","Give prizes to all the candidates so that no one feels left out","Ask students to memorise the names and symbols of all the candidates","Discuss how it compares with real elections and what makes an election fair"],"answer":3,"explanation":"The simulation provides an experience; the debrief links it to concepts such as secret ballot, fair competition and representation. Without it, students remember a contest, not democratic principles.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"कक्षा VI की एक शिक्षिका कक्षा-नायक के लिए नकली चुनाव कराती है, जिसमें नामांकन, प्रचार-भाषण, गुप्त मतदान और मतगणना है। इसे केवल कक्षा-कार्यक्रम के बजाय सामाजिक विज्ञान का पाठ बनाने के लिए इसके बाद क्या होना चाहिए?","optionsHi":["विजेता की घोषणा करना और फिर पाठ्यपुस्तक के अगले अध्याय पर चलना","सभी प्रत्याशियों को पुरस्कार देना ताकि कोई छूटा हुआ महसूस न करे","विद्यार्थियों से सभी प्रत्याशियों के नाम और चिह्न याद करने को कहना","चर्चा करना कि यह वास्तविक चुनावों से कैसे तुलनीय है और चुनाव को निष्पक्ष क्या बनाता है"],"explanationHi":"अनुकरण अनुभव देता है; पुनरावलोकन उसे गुप्त मतदान, निष्पक्ष प्रतिस्पर्धा और प्रतिनिधित्व जैसी संकल्पनाओं से जोड़ता है। इसके बिना विद्यार्थी एक प्रतियोगिता याद रखते हैं, लोकतांत्रिक सिद्धांत नहीं।"},
  {"id":"cdp-pedagogy-subjects-1310","question":"Assertion (A): A social science teacher should present the history of the students' own region as superior to that of other regions, to build local pride.\nReason (R): NCF 2005 recommends connecting learning with the local context of children.","options":["Both A and R are true and R is the correct explanation of A","A is false but R is true","A is true but R is false","Both A and R are true but R is not the correct explanation of A"],"answer":1,"explanation":"Using local context is recommended, but the aim is understanding, not ranking regions. Presenting one region as superior breeds prejudice and goes against social science's commitment to respect for diversity.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"अभिकथन (A): सामाजिक विज्ञान के शिक्षक को स्थानीय गर्व बनाने के लिए विद्यार्थियों के अपने क्षेत्र के इतिहास को अन्य क्षेत्रों के इतिहास से श्रेष्ठ बताना चाहिए।\nकारण (R): NCF 2005 बच्चों के स्थानीय संदर्भ से अधिगम को जोड़ने की अनुशंसा करती है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A असत्य है परंतु R सत्य है","A सत्य है परंतु R असत्य है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है"],"explanationHi":"स्थानीय संदर्भ का उपयोग अनुशंसित है, पर उद्देश्य समझ है, क्षेत्रों की रैंकिंग नहीं। एक क्षेत्र को श्रेष्ठ बताना पूर्वाग्रह पैदा करता है और विविधता के सम्मान की सामाजिक विज्ञान की प्रतिबद्धता के विरुद्ध है।"},
  {"id":"cdp-pedagogy-subjects-1311","question":"Assertion (A): Map work in the early classes should begin with the child's immediate surroundings.\nReason (R): Children's understanding of space develops from familiar to more distant places.","options":["Both A and R are true but R is not the correct explanation of A","A is true but R is false","Both A and R are true and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"Spatial understanding grows outward from the classroom, home and neighbourhood to wider regions, which is precisely why map work should begin locally.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT","questionHi":"अभिकथन (A): प्रारंभिक कक्षाओं में मानचित्र-कार्य बच्चे के निकटतम परिवेश से आरंभ होना चाहिए।\nकारण (R): स्थान की बच्चों की समझ परिचित से अधिक दूर के स्थानों की ओर विकसित होती है।","optionsHi":["A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A असत्य है परंतु R सत्य है"],"explanationHi":"स्थानिक समझ कक्षा, घर और पड़ोस से व्यापक क्षेत्रों की ओर बाहर की ओर बढ़ती है, इसीलिए मानचित्र-कार्य स्थानीय स्तर से आरंभ होना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1312","question":"A Class VIII teacher in Kanpur plans a lesson on livelihoods. Some students' parents are sanitation workers. Which approach is most appropriate?","options":["Present sanitation work as a pitiable job so that students feel sympathy","Leave sanitation work out of the lesson to avoid any embarrassment","Treat it as essential, dignified work and discuss its pay, risks and caste bias","Ask the children of sanitation workers to describe their parents' work in front of the class"],"answer":2,"explanation":"Discussing the work with dignity and examining its structural problems avoids both pity and erasure. Putting particular children on the spot without their consent can expose and hurt them.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"कानपुर की कक्षा VIII का एक शिक्षक आजीविकाओं पर पाठ की योजना बनाता है। कुछ विद्यार्थियों के माता-पिता सफ़ाई-कर्मी हैं। कौन-सा उपागम सबसे उपयुक्त है?","optionsHi":["सफ़ाई के कार्य को दयनीय काम के रूप में प्रस्तुत करना ताकि विद्यार्थियों को सहानुभूति हो","किसी भी शर्मिंदगी से बचने के लिए सफ़ाई-कार्य को पाठ से छोड़ देना","इसे आवश्यक, गरिमापूर्ण कार्य मानना और इसके वेतन, जोखिमों और जातिगत पूर्वाग्रह पर चर्चा करना","सफ़ाई-कर्मियों के बच्चों से कक्षा के सामने अपने माता-पिता के कार्य का वर्णन करने को कहना"],"explanationHi":"कार्य पर गरिमा के साथ चर्चा करना और उसकी संरचनात्मक समस्याओं की जाँच करना दया और मिटा देने, दोनों से बचाता है। विशेष बच्चों को उनकी सहमति के बिना सबके सामने खड़ा करना उन्हें उजागर और आहत कर सकता है।"},
  {"id":"cdp-pedagogy-subjects-1313","question":"A Class VIII student in a Bundelkhand village asks, 'Why is there no secondary school in our village?' What is the most valuable response?","options":["Tell the student politely that such questions are for adults, not for children","Answer briefly that the government has no money for more schools","Note it down for a discussion at the end of the year, after exams","Turn it into a class inquiry on how schools are sanctioned and who decides"],"answer":3,"explanation":"A genuine question from the child's life is an ideal starting point for learning about government, policy and citizens' participation. Quick answers or postponement waste this opportunity.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"बुंदेलखंड के एक गाँव की कक्षा VIII का एक विद्यार्थी पूछता है, 'हमारे गाँव में माध्यमिक विद्यालय क्यों नहीं है?' सबसे मूल्यवान प्रतिक्रिया क्या है?","optionsHi":["विद्यार्थी को विनम्रता से बताना कि ऐसे प्रश्न बड़ों के लिए हैं, बच्चों के लिए नहीं","संक्षेप में उत्तर देना कि सरकार के पास और विद्यालयों के लिए पैसा नहीं है","इसे परीक्षाओं के बाद, वर्ष के अंत में चर्चा के लिए नोट कर लेना","इसे कक्षा-जाँच में बदलना कि विद्यालय कैसे स्वीकृत होते हैं और कौन निर्णय लेता है"],"explanationHi":"बच्चे के जीवन से आया वास्तविक प्रश्न सरकार, नीति और नागरिकों की भागीदारी के बारे में सीखने का आदर्श आरंभ-बिंदु है। त्वरित उत्तर या स्थगन इस अवसर को व्यर्थ करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1314","question":"Which of the following classroom practices are learner-centred?\n1. Students frame their own questions to interview a panchayat member.\n2. The teacher dictates notes for students to copy.\n3. Students compare two accounts of the same event and decide which is more reliable.","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Framing questions and evaluating accounts put students at the centre of building knowledge. Dictation makes the teacher the only active participant.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"निम्नलिखित कक्षा-प्रथाओं में से कौन-सी शिक्षार्थी-केंद्रित हैं?\n1. विद्यार्थी पंचायत-सदस्य का साक्षात्कार करने के लिए अपने प्रश्न स्वयं बनाते हैं।\n2. शिक्षक नोट्स बोलकर लिखवाता है जिन्हें विद्यार्थी उतारते हैं।\n3. विद्यार्थी एक ही घटना के दो विवरणों की तुलना करते हैं और तय करते हैं कि कौन अधिक विश्वसनीय है।","optionsHi":["केवल 1 और 2","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"प्रश्न बनाना और विवरणों का मूल्यांकन करना विद्यार्थियों को ज्ञान-निर्माण के केंद्र में रखता है। श्रुतलेख शिक्षक को एकमात्र सक्रिय भागीदार बनाता है।"},
  {"id":"cdp-pedagogy-subjects-1315","question":"A teacher plans a Class VI lesson on rural livelihoods using the 5E model (Engage, Explore, Explain, Elaborate, Evaluate). Which sequence of her planned steps follows the first four phases?\nP: Students share what their families do for a living\nQ: The teacher introduces concepts such as 'landless labourer' and 'debt'\nR: Groups read case studies of families in a farming village\nS: Students compare the case studies with their own village","options":["Q, P, R, S","Q, R, S, P","P, R, Q, S","R, Q, P, S"],"answer":2,"explanation":"Sharing family work engages prior knowledge, case studies let students explore, the teacher then explains the concepts arising from them, and comparing with their own village elaborates and applies them.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"एक शिक्षिका 5E मॉडल (संलग्न करना, खोजना, समझाना, विस्तार करना, मूल्यांकन करना) का उपयोग करके ग्रामीण आजीविकाओं पर कक्षा VI के पाठ की योजना बनाती है। उसके नियोजित चरणों का कौन-सा क्रम पहले चार चरणों का अनुसरण करता है?\nP: विद्यार्थी साझा करते हैं कि उनके परिवार आजीविका के लिए क्या करते हैं\nQ: शिक्षिका 'भूमिहीन मज़दूर' और 'ऋण' जैसी संकल्पनाएँ प्रस्तुत करती है\nR: समूह खेती वाले गाँव के परिवारों के केस अध्ययन पढ़ते हैं\nS: विद्यार्थी केस अध्ययनों की तुलना अपने गाँव से करते हैं","optionsHi":["Q, P, R, S","Q, R, S, P","P, R, Q, S","R, Q, P, S"],"explanationHi":"परिवार के कार्य साझा करना पूर्व ज्ञान को संलग्न करता है, केस अध्ययन विद्यार्थियों को खोजने देते हैं, फिर शिक्षिका उनसे उत्पन्न संकल्पनाएँ समझाती है, और अपने गाँव से तुलना उन्हें विस्तार देती और लागू करती है।"},
  {"id":"cdp-pedagogy-subjects-1316","question":"Several Class VIII students believe that judges make the laws of the country. Which activity best corrects this?","options":["Trace one law, such as the RTE Act, from Parliament to government to the courts","Ask students to memorise and keep repeating the sentence ‘Parliament makes laws’","Show a large picture of the Supreme Court building and name its present judges","Tell students that courts have no role at all in matters of law"],"answer":0,"explanation":"Following one law through its life shows the distinct roles of the legislature, the executive and the judiciary. Saying courts have no role overcorrects, since courts interpret laws and can strike them down.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा VIII के कई विद्यार्थी मानते हैं कि देश के कानून न्यायाधीश बनाते हैं। कौन-सी गतिविधि इसे सबसे अच्छी तरह सुधारती है?","optionsHi":["RTE अधिनियम जैसे एक कानून का संसद से सरकार और फिर न्यायालयों तक पीछा करना","विद्यार्थियों से 'संसद कानून बनाती है' वाक्य याद करवाना और बार-बार दोहरवाना","उच्चतम न्यायालय भवन का बड़ा चित्र दिखाना और उसके वर्तमान न्यायाधीशों के नाम बताना","विद्यार्थियों को बताना कि कानून के मामलों में न्यायालयों की कोई भूमिका नहीं है"],"explanationHi":"एक कानून को उसके जीवन में आगे बढ़ते देखना विधायिका, कार्यपालिका और न्यायपालिका की अलग-अलग भूमिकाएँ दिखाता है। यह कहना कि न्यायालयों की कोई भूमिका नहीं, अति-सुधार है, क्योंकि न्यायालय कानूनों की व्याख्या करते हैं और उन्हें रद्द कर सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-1317","question":"A Class VIII teacher uses a folk song from her district about a famine in the colonial period as a source. What caution should she help students apply?","options":["Folk songs cannot be used as sources, since they were never written down","Folk songs are fully accurate because ordinary people sang them as they lived","Oral songs may change over time and are hard to date, so check other evidence","Only the tune of the song has historical value, not the words it contains"],"answer":2,"explanation":"Folk songs can preserve the experience of ordinary people, but oral transmission alters them and dating is uncertain. Like any source, they need corroboration, neither rejection nor blind trust.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा VIII की एक शिक्षिका औपनिवेशिक काल के अकाल पर अपने ज़िले के एक लोकगीत को स्रोत के रूप में उपयोग करती है। उसे विद्यार्थियों को कौन-सी सावधानी बरतने में मदद करनी चाहिए?","optionsHi":["लोकगीतों को स्रोत के रूप में उपयोग नहीं किया जा सकता, क्योंकि वे कभी लिखे नहीं गए","लोकगीत पूर्णतः सटीक होते हैं क्योंकि आम लोगों ने उन्हें अपने जीवन के साथ गाया","मौखिक गीत समय के साथ बदल सकते हैं और उनका काल-निर्धारण कठिन है, इसलिए अन्य साक्ष्य जाँचो","केवल गीत की धुन का ऐतिहासिक मूल्य है, उसके शब्दों का नहीं"],"explanationHi":"लोकगीत आम लोगों के अनुभव को सुरक्षित रख सकते हैं, पर मौखिक संचरण उन्हें बदल देता है और काल-निर्धारण अनिश्चित होता है। किसी भी स्रोत की तरह उन्हें पुष्टि चाहिए, न अस्वीकृति, न अंधविश्वास।"},
  {"id":"cdp-pedagogy-subjects-1318","question":"Match the concept with the activity that develops it.\nConcepts: (P) Chronological thinking (Q) Spatial thinking (R) Economic reasoning (S) Civic reasoning\nActivities: (1) Comparing the cost of a government and a private hospital for the same treatment (2) Arranging pictures of means of transport from different periods in order (3) Debating whether a new rule in school treats all students fairly (4) Locating on a map the places from which a city gets its vegetables","options":["P-2, Q-1, R-4, S-3","P-3, Q-4, R-1, S-2","P-2, Q-4, R-3, S-1","P-2, Q-4, R-1, S-3"],"answer":3,"explanation":"Ordering transport pictures builds a sense of time; mapping supply sources is spatial; comparing costs of services is economic reasoning; judging a rule's fairness is civic reasoning.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"संकल्पना को उस गतिविधि से मिलाइए जो उसे विकसित करती है।\nसंकल्पनाएँ: (P) कालक्रमिक चिंतन (Q) स्थानिक चिंतन (R) आर्थिक तर्क (S) नागरिक तर्क\nगतिविधियाँ: (1) एक ही उपचार के लिए सरकारी और निजी अस्पताल की लागत की तुलना करना (2) विभिन्न कालों के परिवहन-साधनों के चित्रों को क्रम में लगाना (3) बहस करना कि क्या विद्यालय का कोई नया नियम सभी विद्यार्थियों के साथ निष्पक्ष है (4) मानचित्र पर वे स्थान खोजना जहाँ से किसी शहर को सब्ज़ियाँ आती हैं","optionsHi":["P-2, Q-1, R-4, S-3","P-3, Q-4, R-1, S-2","P-2, Q-4, R-3, S-1","P-2, Q-4, R-1, S-3"],"explanationHi":"परिवहन के चित्रों को क्रम में लगाना समय का बोध बनाता है; आपूर्ति-स्रोतों को मानचित्र पर अंकित करना स्थानिक है; सेवाओं की लागत की तुलना आर्थिक तर्क है; किसी नियम की निष्पक्षता का निर्णय नागरिक तर्क है।"},
  {"id":"cdp-pedagogy-subjects-1319","question":"In a Class VII lesson on medieval temple towns, a student from a Christian family asks why the textbook has nothing about the churches of Goa or Kerala. What is the best response?","options":["Tell the student that the question is irrelevant to the chapter being taught now","Value the question, explain the chapter’s scope and invite an inquiry into it","Say that Christian history in India began only in the colonial period","Promise to answer it later, when the class reaches Class XII history"],"answer":1,"explanation":"Valuing the question, explaining the textbook's scope and opening an inquiry respects the student and widens everyone's understanding. Christianity in Kerala is much older than colonial rule, so that reply would also be wrong.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · NVS","questionHi":"मध्यकालीन मंदिर-नगरों पर कक्षा VII के पाठ में एक ईसाई परिवार का विद्यार्थी पूछता है कि पाठ्यपुस्तक में गोवा या केरल के गिरजाघरों के बारे में कुछ क्यों नहीं है। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["विद्यार्थी को बताना कि प्रश्न अभी पढ़ाए जा रहे अध्याय के लिए अप्रासंगिक है","प्रश्न को महत्त्व देना, अध्याय का दायरा समझाना और उस पर अन्वेषण के लिए आमंत्रित करना","कहना कि भारत में ईसाई इतिहास केवल औपनिवेशिक काल में शुरू हुआ","वादा करना कि जब कक्षा XII का इतिहास आएगा तब इसका उत्तर देंगे"],"explanationHi":"प्रश्न को महत्त्व देना, पाठ्यपुस्तक का दायरा समझाना और अन्वेषण खोलना विद्यार्थी का सम्मान करता है और सभी की समझ को व्यापक बनाता है। केरल में ईसाई धर्म औपनिवेशिक शासन से बहुत पुराना है, इसलिए वह उत्तर गलत भी होता।"},
  {"id":"cdp-pedagogy-subjects-1320","question":"A Class VI teacher wants students to understand why the Harappan cities had planned drains and streets. Which question best starts an inquiry?","options":["What do the drains, wells and streets tell us about how people lived?","Who discovered Harappa, and in which year was the site first excavated?","Name four Harappan cities and the rivers on which they were located.","Write a definition of ‘town planning’ and learn it by heart."],"answer":0,"explanation":"Asking what material remains reveal about society invites inference from evidence. The other questions call for recall of names, dates or definitions.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VI की एक शिक्षिका चाहती है कि विद्यार्थी समझें कि हड़प्पा के नगरों में योजनाबद्ध नालियाँ और सड़कें क्यों थीं। कौन-सा प्रश्न जिज्ञासा-आधारित अन्वेषण की सबसे अच्छी शुरुआत करता है?","optionsHi":["नालियाँ, कुएँ और सड़कें हमें बताती हैं कि लोग कैसे रहते थे?","हड़प्पा की खोज किसने की, और स्थल की पहली खुदाई किस वर्ष हुई?","चार हड़प्पा नगरों के नाम बताइए और वे किन नदियों पर स्थित थे।","'नगर नियोजन' की परिभाषा लिखिए और उसे कंठस्थ कीजिए।"],"explanationHi":"यह पूछना कि भौतिक अवशेष समाज के बारे में क्या प्रकट करते हैं, साक्ष्य से अनुमान लगाने को आमंत्रित करता है। अन्य प्रश्न नामों, तिथियों या परिभाषाओं के स्मरण की माँग करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1321","question":"Which of the following statements about using the local community as a resource in social science are correct?\n1. Elders can serve as sources for oral history.\n2. Local institutions such as the post office, bank or panchayat can be studied directly.\n3. Community examples should replace national and global content.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The community offers living sources and institutions to study. But local study is a starting point that leads to wider understanding, not a replacement for national and global content.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"सामाजिक विज्ञान में स्थानीय समुदाय को संसाधन के रूप में उपयोग करने के बारे में निम्नलिखित कथनों में से कौन-से सही हैं?\n1. बुज़ुर्ग मौखिक इतिहास के स्रोत हो सकते हैं।\n2. डाकघर, बैंक या पंचायत जैसी स्थानीय संस्थाओं का सीधे अध्ययन किया जा सकता है।\n3. सामुदायिक उदाहरणों को राष्ट्रीय और वैश्विक विषय-वस्तु की जगह ले लेनी चाहिए।","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"समुदाय अध्ययन के लिए जीवित स्रोत और संस्थाएँ देता है। पर स्थानीय अध्ययन व्यापक समझ की ओर ले जाने वाला आरंभ-बिंदु है, राष्ट्रीय और वैश्विक विषय-वस्तु का प्रतिस्थापन नहीं।"},
  {"id":"cdp-pedagogy-subjects-1322","question":"Match each pre-school activity with the pre-number skill it builds. 1. Sorting leaves by shape 2. Arranging sticks from shortest to longest 3. Putting one plate in front of each doll 4. Saying a bead string still has the same number of beads after it is stretched; a. conservation b. one-to-one correspondence c. seriation d. classification","options":["1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a"],"answer":0,"explanation":"Sorting by a property is classification, ordering by size is seriation, pairing plate with doll is one-to-one correspondence, and recognising that number does not change with arrangement is conservation.","difficulty":"hard","source":"CTET Paper 1 · state TETs · KVS PRT","questionHi":"प्रत्येक पूर्व-प्राथमिक गतिविधि को उस पूर्व-संख्या कौशल से मिलाइए जिसे वह बनाती है। 1. पत्तियों को आकार के अनुसार छाँटना 2. डंडियों को सबसे छोटी से सबसे लंबी तक व्यवस्थित करना 3. प्रत्येक गुड़िया के सामने एक थाली रखना 4. यह कहना कि मोतियों की डोरी खींचने के बाद भी उसमें उतने ही मोती हैं; a. संरक्षण b. एक-एक का संगतता (one-to-one correspondence) c. क्रमबद्धता (seriation) d. वर्गीकरण","optionsHi":["1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a"],"explanationHi":"किसी गुण के आधार पर छाँटना वर्गीकरण है, आकार के क्रम में लगाना क्रमबद्धता है, थाली को गुड़िया से जोड़ना एक-एक की संगतता है, और यह पहचानना कि संख्या व्यवस्था बदलने पर नहीं बदलती संरक्षण है।"},
  {"id":"cdp-pedagogy-subjects-1323","question":"A four-year-old always counts ‘one, two, three, five, six’, the same way every time, and gives the last word as the total (‘six’). Which is the most accurate description?","options":["She does not yet follow any of the counting principles, standard or otherwise","She uses stable order and cardinality but not the standard number-word list","She follows only the one-to-one principle and none of the others","She shows a counting disability and needs referral to a specialist at once"],"answer":1,"explanation":"Stable order means using the same list in the same order each time, even if it is not the standard list; giving the last word as the total is the cardinal principle. What is missing is the conventional sequence, which comes with practice.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"एक चार वर्षीय बच्ची हर बार एक ही तरह गिनती है ‘एक, दो, तीन, पाँच, छह’, और अंतिम शब्द को कुल संख्या के रूप में बताती है (‘छह’)। सबसे सटीक वर्णन कौन-सा है?","optionsHi":["वह अभी किसी भी गणना-सिद्धांत का पालन नहीं करती, मानक या अन्यथा","वह स्थिर क्रम और गणनांक (cardinality) का उपयोग करती है, पर मानक संख्या-नाम सूची का नहीं","वह केवल एक-एक संगतता सिद्धांत का पालन करती है, बाकी का नहीं","वह गणना की अक्षमता दिखाती है और उसे तुरंत किसी विशेषज्ञ के पास भेजने की आवश्यकता है"],"explanationHi":"स्थिर क्रम का अर्थ है हर बार एक ही सूची उसी क्रम में प्रयोग करना, भले ही वह मानक सूची न हो; अंतिम शब्द को कुल बताना गणनांक सिद्धांत है। जो अनुपस्थित है वह पारंपरिक क्रम है, जो अभ्यास से आता है।"},
  {"id":"cdp-pedagogy-subjects-1324","question":"A child counts a row of five blocks from the left and gets 5. Asked how many there will be if she counts from the right, she says, ‘I don't know; let me count.’ Which counting principle has she not yet grasped?","options":["Stable order","One-to-one correspondence","Order irrelevance","Abstraction"],"answer":2,"explanation":"Order irrelevance means the total does not depend on where counting starts. A child who must recount to be sure has not yet grasped it, even though her counting itself is correct.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक बच्ची पाँच ब्लॉकों की पंक्ति को बाईं ओर से गिनती है और 5 पाती है। पूछे जाने पर कि दाईं ओर से गिनने पर कितने होंगे, वह कहती है, 'मुझे नहीं पता; गिनकर देखती हूँ।' उसने गणना का कौन-सा सिद्धांत अभी नहीं समझा है?","optionsHi":["स्थिर क्रम","एक-एक संगतता","क्रम की अप्रासंगिकता (order irrelevance)","अमूर्तन"],"explanationHi":"क्रम की अप्रासंगिकता का अर्थ है कि कुल संख्या इस पर निर्भर नहीं करती कि गिनती कहाँ से शुरू होती है। जिस बच्ची को निश्चित होने के लिए दोबारा गिनना पड़ता है उसने इसे अभी नहीं समझा, भले ही उसकी गिनती स्वयं सही है।"},
  {"id":"cdp-pedagogy-subjects-1325","question":"Asked to count a pencil, a cup and a ball together, a child says they cannot be counted ‘because they are different things’. Which counting principle is she missing?","options":["Cardinality, that the last number names the total","Stable order, that number words come in a fixed order","One-to-one correspondence, one number word for each object","Abstraction, that any collection of things can be counted"],"answer":3,"explanation":"The abstraction principle says counting applies to any set, whether the things are alike or not, and even to sounds or actions. The child thinks only similar objects can be counted together.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"एक पेंसिल, एक कप और एक गेंद को साथ गिनने को कहे जाने पर एक बच्ची कहती है कि उन्हें गिना नहीं जा सकता 'क्योंकि वे अलग-अलग चीज़ें हैं'। उसमें गणना का कौन-सा सिद्धांत अनुपस्थित है?","optionsHi":["गणनांक, कि अंतिम संख्या कुल को नाम देती है","स्थिर क्रम, कि संख्या-नाम निश्चित क्रम में आते हैं","एक-एक संगतता, प्रत्येक वस्तु के लिए एक संख्या-नाम","अमूर्तन, कि वस्तुओं के किसी भी संग्रह को गिना जा सकता है"],"explanationHi":"अमूर्तन सिद्धांत कहता है कि गणना किसी भी समुच्चय पर लागू होती है, चाहे वस्तुएँ समान हों या नहीं, यहाँ तक कि ध्वनियों या क्रियाओं पर भी। बच्ची सोचती है कि केवल समान वस्तुएँ साथ गिनी जा सकती हैं।"},
  {"id":"cdp-pedagogy-subjects-1326","question":"A Class 1 child can recite numbers from 1 to 50 but cannot give the teacher 7 seeds from a heap when asked. Which activity should the teacher focus on?","options":["‘Give me 7’ tasks with real objects, moving each one and stopping at 7","More daily practice in reciting the number names in order all the way up to 100","Writing the numerals 1 to 50 neatly in the notebook several times","Learning several number rhymes and songs by heart with actions"],"answer":0,"explanation":"Reciting is rote counting; giving a set of a given size needs rational counting (one-to-one matching and knowing when to stop). Practice with real objects builds this.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 1 का एक बच्चा 1 से 50 तक संख्याएँ दोहरा सकता है पर माँगे जाने पर ढेर से शिक्षक को 7 बीज नहीं दे सकता। शिक्षक को किस गतिविधि पर ध्यान देना चाहिए?","optionsHi":["वास्तविक वस्तुओं के साथ 'मुझे 7 दो' कार्य, प्रत्येक को खिसकाते हुए और 7 पर रुकते हुए","क्रम में संख्या-नाम 100 तक दोहराने का और अधिक दैनिक अभ्यास","कॉपी में अंक 1 से 50 कई बार साफ़-साफ़ लिखना","कई संख्या-तुकबंदियाँ और गीत हाव-भाव के साथ कंठस्थ करना"],"explanationHi":"दोहराना रटंत गणना है; दिए गए आकार का समूह देने के लिए तर्कसंगत गणना (एक-एक मिलान और कब रुकना है यह जानना) चाहिए। वास्तविक वस्तुओं के साथ अभ्यास यह बनाता है।"},
  {"id":"cdp-pedagogy-subjects-1327","question":"A child counts beads arranged in a circle and keeps counting some beads twice because she cannot tell where she started. What is the best help?","options":["Tell her to count faster so that she does not lose track of where she began","Show her a tracking strategy, like moving each counted bead aside","Give her only beads arranged in a straight line from now on","Tell her the correct answer and move on to the next activity"],"answer":1,"explanation":"Keeping counted and uncounted objects apart is a key part of accurate counting. Teaching a tracking strategy helps with any arrangement; avoiding circles only hides the difficulty.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक बच्ची गोले में रखे मोतियों को गिनती है और कुछ मोतियों को दो बार गिनती रहती है क्योंकि वह नहीं बता पाती कि उसने कहाँ से शुरू किया था। सबसे अच्छी मदद क्या है?","optionsHi":["उसे तेज़ गिनने को कहना ताकि वह न भूले कि कहाँ से शुरू किया","उसे अनुसरण की युक्ति दिखाना, जैसे गिना हुआ प्रत्येक मोती अलग कर देना","अब से उसे केवल सीधी रेखा में रखे मोती देना","उसे सही उत्तर बता देना और अगली गतिविधि पर बढ़ जाना"],"explanationHi":"गिनी हुई और बिना गिनी हुई वस्तुओं को अलग रखना सटीक गणना का मुख्य भाग है। अनुसरण की युक्ति सिखाना किसी भी व्यवस्था में मदद करता है; गोलों से बचना कठिनाई को केवल छिपाता है।"},
  {"id":"cdp-pedagogy-subjects-1328","question":"A closed box with two sections holds 5 beans. The child shakes it, opens one side, sees 3 beans and says, ‘So 2 are hiding.’ What is this activity mainly building?","options":["Rote counting of number names in the right order","Writing numerals correctly and in the right sequence","Part-whole understanding of numbers (number bonds)","Measurement of length using non-standard units"],"answer":2,"explanation":"Knowing that 5 can be split into 3 and 2, and finding a missing part, is part-whole thinking. It is the basis for flexible addition and subtraction, and for missing-addend problems.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"दो खंडों वाले एक बंद डिब्बे में 5 सेम के बीज हैं। बच्चा उसे हिलाता है, एक ओर खोलता है, 3 बीज देखता है और कहता है, 'तो 2 छिपे हैं।' यह गतिविधि मुख्यतः क्या बना रही है?","optionsHi":["सही क्रम में संख्या-नामों की रटंत गणना","अंकों को सही ढंग से और सही क्रम में लिखना","संख्याओं की भाग-पूर्ण समझ (संख्या-बंध)","गैर-मानक इकाइयों से लंबाई का मापन"],"explanationHi":"यह जानना कि 5 को 3 और 2 में बाँटा जा सकता है, और लुप्त भाग खोजना, भाग-पूर्ण चिंतन है। यह लचीले जोड़ और घटाव और लुप्त-योज्य (missing-addend) समस्याओं का आधार है।"},
  {"id":"cdp-pedagogy-subjects-1329","question":"Why is a ten-frame (a 2 × 5 grid) more useful for early number work than counters in a random heap?","options":["It looks bright and colourful, so children pay more attention to it","It is cheaper and quicker to make than a set of loose counters","It is needed so that children can practise rote counting up to 10","It shows numbers against 5 and 10, so 7 is seen as ‘5 and 2’"],"answer":3,"explanation":"The structure of the frame lets children see quantities without counting one by one and links them to 5 and 10, which supports strategies such as ‘make ten’.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"प्रारंभिक संख्या-कार्य के लिए बेतरतीब ढेर में गिनतियों की तुलना में दस-फ़्रेम (2 × 5 का ग्रिड) अधिक उपयोगी क्यों है?","optionsHi":["यह चमकीला और रंगीन दिखता है, इसलिए बच्चे उस पर अधिक ध्यान देते हैं","यह ढीली गिनतियों के सेट से सस्ता और बनाने में तेज़ है","यह इसलिए आवश्यक है कि बच्चे 10 तक रटंत गणना का अभ्यास कर सकें","यह संख्याओं को 5 और 10 के सापेक्ष दिखाता है, इसलिए 7 को '5 और 2' के रूप में देखा जाता है"],"explanationHi":"फ़्रेम की संरचना बच्चों को एक-एक गिने बिना मात्राएँ देखने देती है और उन्हें 5 और 10 से जोड़ती है, जो 'दस बनाओ' जैसी युक्तियों का समर्थन करती है।"},
  {"id":"cdp-pedagogy-subjects-1330","question":"Which of these statements about NEP 2020 are correct? I. The foundational stage covers ages 3 to 8. II. It includes three years of preschool or Anganwadi and Grades 1 and 2. III. It calls achieving foundational literacy and numeracy for all children an urgent national mission. IV. It requires a board examination at the end of Grade 2 to test numeracy.","options":["I, II and III","I and III only","II, III and IV","I, II, III and IV"],"answer":0,"explanation":"NEP 2020 has a 5-year foundational stage (ages 3–8: three years of preschool plus Grades 1 and 2) and makes foundational literacy and numeracy an urgent national mission. There is no board exam at Grade 2.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"NEP 2020 के बारे में इनमें से कौन-से कथन सही हैं? I. आधारभूत चरण 3 से 8 वर्ष की आयु को समेटता है। II. इसमें तीन वर्ष का पूर्व-विद्यालय या आँगनवाड़ी और कक्षा 1 तथा 2 शामिल हैं। III. यह सभी बच्चों के लिए आधारभूत साक्षरता और संख्याज्ञान प्राप्त करने को एक अत्यावश्यक राष्ट्रीय मिशन कहती है। IV. यह संख्याज्ञान की जाँच के लिए कक्षा 2 के अंत में बोर्ड परीक्षा अनिवार्य करती है।","optionsHi":["I, II और III","केवल I और III","II, III और IV","I, II, III और IV"],"explanationHi":"NEP 2020 में 5 वर्ष का आधारभूत चरण है (3–8 वर्ष की आयु: तीन वर्ष का पूर्व-विद्यालय और कक्षा 1 तथा 2) और वह आधारभूत साक्षरता और संख्याज्ञान को अत्यावश्यक राष्ट्रीय मिशन बनाती है। कक्षा 2 पर कोई बोर्ड परीक्षा नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1331","question":"Asked to mark 10 on a 0–100 number line, a Class 1 child places it near the middle. What does this show, and what helps?","options":["She cannot count up to 100 yet and should practise counting aloud every day","Her number line crowds large numbers; benchmarks and straight-track games help","She has simply confused 10 with 100 and needs to read the numerals more carefully","She is careless and should be told to pay more attention to the task"],"answer":1,"explanation":"Young children space small numbers widely and crowd larger ones, as on a log scale. Experience with benchmarks and with board games numbered in a straight line helps them build a linear sense of number size.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"0–100 की संख्या-रेखा पर 10 अंकित करने को कहे जाने पर कक्षा 1 का एक बच्चा उसे लगभग बीच में रखता है। यह क्या दिखाता है, और क्या मदद करता है?","optionsHi":["वह अभी 100 तक गिन नहीं सकती और उसे प्रतिदिन ज़ोर से गिनने का अभ्यास करना चाहिए","उसकी संख्या-रेखा बड़ी संख्याओं को ठूँस देती है; मानक-बिंदु (benchmarks) और सीधी पटरी वाले खेल मदद करते हैं","उसने बस 10 को 100 से भ्रमित कर दिया है और उसे अंक अधिक सावधानी से पढ़ने चाहिए","वह लापरवाह है और उसे कार्य पर अधिक ध्यान देने को कहा जाना चाहिए"],"explanationHi":"छोटे बच्चे छोटी संख्याओं को दूर-दूर और बड़ी संख्याओं को पास-पास रखते हैं, जैसे लघुगणकीय पैमाने पर। मानक-बिंदुओं का अनुभव और सीधी रेखा में क्रमांकित बोर्ड खेल उन्हें संख्या-आकार की रैखिक समझ बनाने में मदद करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1332","question":"Why are board games with numbered squares in a straight line, such as a simple snakes-and-ladders board, especially helpful in early numeracy?","options":["They teach children to win and to lose gracefully in front of their friends","They are mainly useful for practising reading the words on the board","Moving along numbered squares links each number to a position and distance","They replace the need for counting real objects in the early classes"],"answer":2,"explanation":"A straight numbered track gives children many experiences of ‘larger numbers are further along’, and studies show such games improve number-line estimation and comparison.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"सीधी रेखा में क्रमांकित वर्गों वाले बोर्ड खेल, जैसे साधारण साँप-सीढ़ी का बोर्ड, प्रारंभिक संख्याज्ञान में विशेष रूप से सहायक क्यों हैं?","optionsHi":["वे बच्चों को अपने मित्रों के सामने शालीनता से जीतना और हारना सिखाते हैं","वे मुख्यतः बोर्ड पर लिखे शब्द पढ़ने के अभ्यास के लिए उपयोगी हैं","क्रमांकित वर्गों पर चलना प्रत्येक संख्या को स्थिति और दूरी से जोड़ता है","वे प्रारंभिक कक्षाओं में वास्तविक वस्तुओं को गिनने की आवश्यकता को समाप्त कर देते हैं"],"explanationHi":"सीधी क्रमांकित पटरी बच्चों को 'बड़ी संख्याएँ आगे होती हैं' के अनेक अनुभव देती है, और अध्ययन दिखाते हैं कि ऐसे खेल संख्या-रेखा के अनुमान और तुलना में सुधार करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1333","question":"A Class 1 child compares two pencils whose left ends are not lined up and says the one sticking out further on the right is longer. What has she not yet understood?","options":["How to place a ruler correctly and read its centimetre marks","That length is always measured in standard units like centimetres","That pencils of the same colour are always the same length","That lengths must be compared from a common starting line"],"answer":3,"explanation":"Direct comparison needs both objects to start at the same baseline. Without it, the one that ends further right only looks longer. Lining up ends comes before any unit measurement.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 1 की एक बच्ची दो पेंसिलों की तुलना करती है जिनके बाएँ सिरे संरेखित नहीं हैं, और कहती है कि दाईं ओर अधिक बाहर निकली पेंसिल लंबी है। उसने अभी क्या नहीं समझा है?","optionsHi":["पैमाना सही ढंग से कैसे रखें और उसके सेंटीमीटर चिह्न कैसे पढ़ें","कि लंबाई हमेशा सेंटीमीटर जैसी मानक इकाइयों में मापी जाती है","कि एक ही रंग की पेंसिलें हमेशा एक ही लंबाई की होती हैं","कि लंबाइयों की तुलना एक उभयनिष्ठ आरंभ-रेखा से की जानी चाहिए"],"explanationHi":"प्रत्यक्ष तुलना के लिए दोनों वस्तुओं को एक ही आधार-रेखा से शुरू होना चाहिए। इसके बिना, जो दाईं ओर आगे तक जाती है वह बस लंबी दिखती है। सिरों को संरेखित करना किसी भी इकाई-मापन से पहले आता है।"},
  {"id":"cdp-pedagogy-subjects-1334","question":"Which of these problems is usually the hardest for Class 1 children?","options":["‘Rani had some bangles. Her aunt gave her 3 more. Now she has 8. How many did she have at first?’","‘Rani had 5 bangles. Her aunt gave her 3 more. How many does she have now?’","‘Rani had 5 bangles. Her aunt gave her some more. Now she has 8. How many bangles did her aunt give?’","‘Rani has 5 red bangles and 3 green bangles. How many bangles does she have?’"],"answer":0,"explanation":"When the starting amount is unknown, children cannot simply act the story out from the beginning, so ‘start unknown’ problems are the hardest. Result-unknown and part-part-whole problems are the easiest.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"इनमें से कौन-सी समस्या कक्षा 1 के बच्चों के लिए प्रायः सबसे कठिन होती है?","optionsHi":["'रानी के पास कुछ चूड़ियाँ थीं। उसकी मौसी ने उसे 3 और दीं। अब उसके पास 8 हैं। शुरू में उसके पास कितनी थीं?'","'रानी के पास 5 चूड़ियाँ थीं। उसकी मौसी ने उसे 3 और दीं। अब उसके पास कितनी हैं?'","'रानी के पास 5 चूड़ियाँ थीं। उसकी मौसी ने उसे कुछ और दीं। अब उसके पास 8 हैं। मौसी ने कितनी चूड़ियाँ दीं?'","'रानी के पास 5 लाल चूड़ियाँ और 3 हरी चूड़ियाँ हैं। उसके पास कुल कितनी चूड़ियाँ हैं?'"],"explanationHi":"जब आरंभिक मात्रा अज्ञात हो, तो बच्चे कहानी को शुरू से अभिनीत नहीं कर सकते, इसलिए 'आरंभ अज्ञात' समस्याएँ सबसे कठिन हैं। परिणाम-अज्ञात और भाग-भाग-पूर्ण समस्याएँ सबसे आसान हैं।"},
  {"id":"cdp-pedagogy-subjects-1335","question":"A teacher wants Class 2 children to become fluent with addition facts without rote memorisation. Which approach is best?","options":["Daily timed tests of all the facts, with the fastest children praised before the class","Strategies such as doubles, near doubles and making ten, practised through games","Writing each addition fact ten times in the notebook every evening","Allowing only finger counting until the children reach Class 4"],"answer":1,"explanation":"Facts learnt through reasoning strategies are remembered better and can be rebuilt if forgotten. Games give the practice without the anxiety of timed tests.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक शिक्षक चाहता है कि कक्षा 2 के बच्चे बिना रटे जोड़ के तथ्यों में प्रवाहमय हों। कौन-सा उपागम सबसे अच्छा है?","optionsHi":["सभी तथ्यों की प्रतिदिन समयबद्ध परीक्षाएँ, कक्षा के सामने सबसे तेज़ बच्चों की प्रशंसा के साथ","दुगुने, लगभग-दुगुने और दस बनाने जैसी युक्तियाँ, खेलों के माध्यम से अभ्यास की गईं","हर शाम कॉपी में प्रत्येक जोड़ का तथ्य दस बार लिखना","बच्चों के कक्षा 4 तक पहुँचने तक केवल उँगली से गिनने की अनुमति देना"],"explanationHi":"तर्क-आधारित युक्तियों से सीखे तथ्य बेहतर याद रहते हैं और भूलने पर दोबारा बनाए जा सकते हैं। खेल समयबद्ध परीक्षाओं की चिंता के बिना अभ्यास देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1336","question":"A Class 2 child cannot use the ‘make ten’ strategy for 8 + 5 (8 + 2 + 3). Which prerequisite is she most likely missing?","options":["Knowing the multiplication table of 2 by heart without mistakes","Being able to read and write all the numbers up to 100 correctly","Knowing pairs that make 10 and splitting 5 into 2 and 3","Being able to write numerals neatly and in the correct direction"],"answer":2,"explanation":"‘Make ten’ needs the child to know that 8 needs 2 more to make 10 and to split 5 into 2 and 3. Ten-frames and number bonds build both skills.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 2 की एक बच्ची 8 + 5 (8 + 2 + 3) के लिए 'दस बनाओ' युक्ति का उपयोग नहीं कर पाती। उसमें कौन-सी पूर्वापेक्षा सबसे अधिक अनुपस्थित है?","optionsHi":["2 का पहाड़ा बिना गलती के कंठस्थ होना","100 तक सभी संख्याओं को सही ढंग से पढ़ने और लिखने में सक्षम होना","10 बनाने वाले जोड़े जानना और 5 को 2 और 3 में बाँटना","अंकों को साफ़-साफ़ और सही दिशा में लिखने में सक्षम होना"],"explanationHi":"'दस बनाओ' के लिए बच्ची को यह जानना चाहिए कि 8 को 10 बनाने के लिए 2 और चाहिए और 5 को 2 और 3 में बाँटना है। दस-फ़्रेम और संख्या-बंध दोनों कौशल बनाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1337","question":"A Class 2 child counts the four symbols beside ‘Mangoes’ in a pictograph and says 4 children like mangoes. The key says each symbol stands for 2 children. What is the best next step?","options":["Ask her to read the key and work out what four symbols stand for","Tell her that the right answer is 8 and move on to the next row","Use only pictographs where one symbol stands for one child from now on","Ask her to count the symbols again, slowly and carefully this time"],"answer":0,"explanation":"She counted symbols without using the scale. Asking her to read and apply the key (4 × 2 = 8) builds the habit of reading a graph's key; avoiding scaled graphs would hide the difficulty.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 2 की एक बच्ची चित्र-आलेख में 'आम' के बगल के चार प्रतीकों को गिनती है और कहती है कि 4 बच्चों को आम पसंद हैं। कुंजी कहती है कि प्रत्येक प्रतीक 2 बच्चों को दर्शाता है। सबसे अच्छा अगला कदम क्या है?","optionsHi":["उससे कुंजी पढ़ने और यह निकालने को कहना कि चार प्रतीक किसके बराबर हैं","उसे बताना कि सही उत्तर 8 है और अगली पंक्ति पर बढ़ जाना","अब से केवल वे चित्र-आलेख उपयोग करना जिनमें एक प्रतीक एक बच्चे को दर्शाता है","उससे इस बार धीरे और सावधानी से प्रतीक फिर से गिनने को कहना"],"explanationHi":"उसने पैमाने का उपयोग किए बिना प्रतीक गिन लिए। उससे कुंजी पढ़वाना और लागू करवाना (4 × 2 = 8) आलेख की कुंजी पढ़ने की आदत बनाता है; पैमाने वाले आलेखों से बचना कठिनाई को छिपाएगा।"},
  {"id":"cdp-pedagogy-subjects-1338","question":"In a pretend shop, a Class 2 child says five ₹1 coins are worth more than one ₹10 note ‘because there are more of them’. What has she not yet understood?","options":["How to count a set of coins one by one without missing or repeating any","That the value of money depends on the number of notes and coins","That notes and coins have values, so one ₹10 note equals ten ₹1 coins","That coins are always more valuable than notes because they are metal"],"answer":2,"explanation":"She judges by the number of items, not by value. Exchanging coins for notes in the pretend shop (ten ₹1 coins for one ₹10 note) builds the idea of value, much like trading ones for a ten.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"एक नकली दुकान में कक्षा 2 की एक बच्ची कहती है कि पाँच ₹1 के सिक्के एक ₹10 के नोट से अधिक मूल्य के हैं 'क्योंकि वे संख्या में अधिक हैं'। उसने अभी क्या नहीं समझा है?","optionsHi":["सिक्कों के समूह को एक-एक करके बिना छोड़े या दोहराए कैसे गिनें","कि पैसे का मूल्य नोटों और सिक्कों की संख्या पर निर्भर करता है","कि नोटों और सिक्कों का मूल्य होता है, इसलिए एक ₹10 का नोट दस ₹1 के सिक्कों के बराबर है","कि सिक्के हमेशा नोटों से अधिक मूल्यवान होते हैं क्योंकि वे धातु के होते हैं"],"explanationHi":"वह मूल्य से नहीं, वस्तुओं की संख्या से निर्णय करती है। नकली दुकान में सिक्कों को नोटों से बदलना (दस ₹1 के सिक्के एक ₹10 के नोट से) मूल्य का विचार बनाता है, इकाइयों को दहाई से बदलने की तरह।"},
  {"id":"cdp-pedagogy-subjects-1339","question":"A child continues the pattern red-blue-blue, red-blue-blue as red-blue, red-blue, red-blue. What is the best way to help her?","options":["Tell her the correct colours to use for the next few beads in the row","Give her only easier ABAB patterns from now on so she does not fail","Ask her to circle the repeating part and say it aloud before going on","Ask her to count all the beads in the pattern and write the total"],"answer":2,"explanation":"Seeing the repeating unit (red-blue-blue) is the key to any repeating pattern. Circling and saying it lets her find the unit herself; telling her the answer does not build the skill.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक बच्ची लाल-नीला-नीला, लाल-नीला-नीला प्रतिरूप को लाल-नीला, लाल-नीला, लाल-नीला के रूप में आगे बढ़ाती है। उसकी मदद करने का सबसे अच्छा तरीका क्या है?","optionsHi":["उसे पंक्ति में अगले कुछ मोतियों के सही रंग बता देना","अब से उसे केवल आसान ABAB प्रतिरूप देना ताकि वह विफल न हो","उससे दोहराए जाने वाले भाग पर गोला लगाने और आगे बढ़ने से पहले उसे ज़ोर से बोलने को कहना","उससे प्रतिरूप के सभी मोतियों को गिनने और कुल लिखने को कहना"],"explanationHi":"दोहराई जाने वाली इकाई (लाल-नीला-नीला) को देखना किसी भी दोहराव वाले प्रतिरूप की कुंजी है। गोला लगाना और बोलना उसे इकाई स्वयं खोजने देता है; उत्तर बता देना कौशल नहीं बनाता।"},
  {"id":"cdp-pedagogy-subjects-1340","question":"Which set of signs, persisting despite good teaching over time, would most justify referring a child for assessment for dyscalculia?","options":["Occasional slips in carrying when doing long addition under time pressure","Disliking maths homework and finishing it slowly, often at the last minute","Making errors only in word problems written in a second language she is learning","Great difficulty seeing small quantities at a glance and comparing two numbers"],"answer":3,"explanation":"Dyscalculia is a persistent difficulty with basic number sense, such as subitising and comparing magnitudes. Occasional slips, dislike or language problems are not signs of it.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"अच्छे शिक्षण के बावजूद समय के साथ बने रहने वाले संकेतों का कौन-सा समूह बच्चे को डिस्कैल्कुलिया के आकलन के लिए भेजने को सबसे अधिक उचित ठहराएगा?","optionsHi":["समय के दबाव में लंबे जोड़ में हासिल लगाने पर कभी-कभार की चूकें","गणित का गृहकार्य नापसंद करना और उसे धीरे, प्रायः अंतिम समय में, पूरा करना","केवल उस दूसरी भाषा में लिखे शाब्दिक प्रश्नों में त्रुटियाँ करना जो वह सीख रही है","छोटी मात्राओं को एक नज़र में देखने और दो संख्याओं की तुलना करने में बहुत कठिनाई"],"explanationHi":"डिस्कैल्कुलिया मूल संख्या-बोध, जैसे एक नज़र में मात्रा पहचानना (subitising) और परिमाणों की तुलना, में स्थायी कठिनाई है। कभी-कभार की चूकें, नापसंद या भाषा की समस्याएँ इसके संकेत नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-1341","question":"A teacher in a multigrade school has Classes 1, 2 and 3 together for maths. Which plan works best?","options":["A shared theme, like a class shop, with tasks at a different level for each class","Teaching each class separately in turn while the other two classes sit quietly and wait","Teaching only the Class 3 syllabus to everyone so nobody is left behind","Giving all three classes the same worksheet so that marking is easier"],"answer":0,"explanation":"A shared context with tiered tasks keeps all children engaged at their own level and lets older children help younger ones, which suits the multigrade classrooms common in India.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"एक बहु-श्रेणी विद्यालय के शिक्षक के पास गणित के लिए कक्षा 1, 2 और 3 साथ हैं। कौन-सी योजना सबसे अच्छी काम करती है?","optionsHi":["एक साझा विषय, जैसे कक्षा की दुकान, जिसमें प्रत्येक कक्षा के लिए अलग स्तर के कार्य हों","प्रत्येक कक्षा को बारी-बारी से अलग पढ़ाना जबकि अन्य दो कक्षाएँ चुपचाप प्रतीक्षा करें","सभी को केवल कक्षा 3 का पाठ्यक्रम पढ़ाना ताकि कोई पीछे न रहे","तीनों कक्षाओं को एक ही कार्य-पत्र देना ताकि अंकन आसान हो"],"explanationHi":"स्तरित कार्यों के साथ साझा संदर्भ सभी बच्चों को अपने स्तर पर संलग्न रखता है और बड़े बच्चों को छोटों की मदद करने देता है, जो भारत में आम बहु-श्रेणी कक्षाओं के अनुकूल है।"},
  {"id":"cdp-pedagogy-subjects-1342","question":"A Class 3 teacher teaches several speed tricks for multiplication without explaining why they work. What is the main pedagogical concern?","options":["Tricks are too difficult for Class 3 children to remember correctly","Tricks without understanding are easily misapplied and build no number sense","Tricks are not part of Indian mathematics and so do not belong in the syllabus","Tricks take too long to teach when the syllabus has to be finished"],"answer":1,"explanation":"Speed is not the aim at this stage; a trick without understanding is just another rule to forget or misapply. If tricks are used, children should explore why they work.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 3 का एक शिक्षक गुणा के लिए कई गति-चालें (speed tricks) बिना यह समझाए सिखाता है कि वे क्यों काम करती हैं। मुख्य शिक्षणशास्त्रीय चिंता क्या है?","optionsHi":["कक्षा 3 के बच्चों के लिए चालें सही ढंग से याद रखना बहुत कठिन है","बिना समझ की चालों का आसानी से गलत उपयोग होता है और वे संख्या-बोध नहीं बनातीं","चालें भारतीय गणित का हिस्सा नहीं हैं और इसलिए पाठ्यक्रम में नहीं आतीं","जब पाठ्यक्रम पूरा करना हो तो चालें सिखाने में बहुत समय लगता है"],"explanationHi":"इस अवस्था में गति लक्ष्य नहीं है; बिना समझ की चाल बस एक और नियम है जिसे भुलाया या गलत उपयोग किया जा सकता है। यदि चालों का उपयोग हो, तो बच्चों को खोजना चाहिए कि वे क्यों काम करती हैं।"},
  {"id":"cdp-pedagogy-subjects-1343","question":"Assertion (A): Children who can recite number names up to 100 no longer need to count real objects. Reason (R): Reciting number names and understanding quantity are different abilities.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Reciting is a verbal sequence; understanding quantity needs one-to-one counting, cardinality and comparison, which develop through counting real objects. So R is true and it shows why A is false.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"अभिकथन (A): जो बच्चे 100 तक संख्या-नाम दोहरा सकते हैं उन्हें अब वास्तविक वस्तुएँ गिनने की आवश्यकता नहीं। कारण (R): संख्या-नाम दोहराना और मात्रा समझना भिन्न क्षमताएँ हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"दोहराना एक मौखिक अनुक्रम है; मात्रा समझने के लिए एक-एक गणना, गणनांक और तुलना चाहिए, जो वास्तविक वस्तुओं को गिनने से विकसित होती है। इसलिए R सत्य है और वह दिखाता है कि A असत्य क्यों है।"},
  {"id":"cdp-pedagogy-subjects-1344","question":"Which of these statements about early numeracy are correct? I. Recognising small quantities at a glance (subitising) is a foundation for number sense. II. Counting should always begin with written numerals. III. Number names, numerals and quantities should be linked to one another. IV. Children must master counting to 100 before any addition.","options":["I, II and III","II and IV only","I and III only","I, III and IV"],"answer":2,"explanation":"Number work begins with objects and spoken names, not written numerals, and simple addition through stories and objects starts long before counting to 100. I and III describe sound practice.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"प्रारंभिक संख्याज्ञान के बारे में इनमें से कौन-से कथन सही हैं? I. छोटी मात्राओं को एक नज़र में पहचानना (subitising) संख्या-बोध की नींव है। II. गणना हमेशा लिखित अंकों से शुरू होनी चाहिए। III. संख्या-नाम, अंक और मात्राएँ एक-दूसरे से जुड़ी होनी चाहिए। IV. किसी भी जोड़ से पहले बच्चों को 100 तक गिनने में निपुण होना चाहिए।","optionsHi":["I, II और III","केवल II और IV","केवल I और III","I, III और IV"],"explanationHi":"संख्या-कार्य वस्तुओं और बोले गए नामों से शुरू होता है, लिखित अंकों से नहीं, और कहानियों तथा वस्तुओं के माध्यम से सरल जोड़ 100 तक गिनने से बहुत पहले शुरू होता है। I और III सही अभ्यास का वर्णन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1345","question":"Writing numbers in order, a Class 1 child writes ‘…37, 38, 39, 310, 311’. What does this most clearly show?","options":["She has trouble holding the pencil and forming the digits correctly","She has not yet learnt to write the digit 4, so she avoids it and writes 3 again","She is copying from a neighbour who has made the same mistake","She carries on counting ones past 9, not seeing that ten ones make a new ten"],"answer":3,"explanation":"After 39 the ones are full, so they make one more ten: 40. Writing 310 shows the ten-and-ones structure is not yet understood; bundling sticks at 39 + 1 makes it visible.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"संख्याओं को क्रम में लिखते हुए कक्षा 1 की एक बच्ची लिखती है ‘…37, 38, 39, 310, 311’। यह सबसे स्पष्ट रूप से क्या दिखाता है?","optionsHi":["उसे पेंसिल पकड़ने और अंक सही बनाने में कठिनाई है","उसने अभी अंक 4 लिखना नहीं सीखा, इसलिए वह उससे बचती है और 3 फिर लिख देती है","वह पड़ोसी से नकल कर रही है जिसने वही गलती की है","वह 9 के आगे इकाइयाँ गिनती जाती है, यह नहीं देखती कि दस इकाइयाँ एक नई दहाई बनाती हैं"],"explanationHi":"39 के बाद इकाइयाँ भर जाती हैं, इसलिए वे एक और दहाई बनाती हैं: 40। 310 लिखना दिखाता है कि दहाई-और-इकाई की संरचना अभी समझी नहीं गई; 39 + 1 पर डंडियों के बंडल बनाने से यह दृश्यमान होता है।"},
  {"id":"cdp-pedagogy-subjects-1346","question":"For 6 + 9, a Class 1 child says ‘six…’ and then counts on nine more, raising a finger for each word, and stops at ‘fifteen’. Which next step would make her strategy more efficient?","options":["Go back to counting both sets from one with objects, to be sure of the total","Count on 6 from 9, the larger number, since the order does not change the sum","Memorise 6 + 9 = 15 by repeating it aloud several times every day","Stop using fingers to keep track, since finger counting is a bad habit to break"],"answer":1,"explanation":"She already counts on and keeps track of the second number, a real step beyond counting all. Starting from the larger addend (using commutativity) shortens the count from nine steps to six.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"6 + 9 के लिए कक्षा 1 की एक बच्ची कहती है ‘छह…’ और फिर प्रत्येक शब्द के लिए एक उँगली उठाते हुए नौ और आगे गिनती है, और ‘पंद्रह’ पर रुकती है। कौन-सा अगला कदम उसकी युक्ति को अधिक कुशल बनाएगा?","optionsHi":["सुनिश्चित होने के लिए वस्तुओं के साथ दोनों समूहों को एक से गिनने पर लौटना","6 आगे गिनना, बड़ी संख्या 9 से शुरू करके, क्योंकि क्रम से योग नहीं बदलता","बार-बार प्रतिदिन ज़ोर से दोहराकर 6 + 9 = 15 याद करना","गिनती का हिसाब रखने के लिए उँगलियों का उपयोग बंद करना, क्योंकि उँगली से गिनना छोड़ने योग्य बुरी आदत है"],"explanationHi":"वह पहले से आगे गिनती (counting on) करती है और दूसरी संख्या का हिसाब रखती है, जो सब गिनने से वास्तविक आगे का कदम है। बड़ी योज्य संख्या से शुरू करना (क्रमविनिमेयता का उपयोग) गिनती को नौ चरणों से छह चरणों तक घटा देता है।"},
  {"id":"cdp-pedagogy-subjects-1347","question":"A Class VI teacher plans a unit using backward design (Wiggins and McTighe). Which order of planning steps should she follow?","options":["Choose interesting activities, then write objectives, then prepare a test","Write the test first, then choose the activities, then write the objectives","Set the desired results, then decide the evidence, then plan the activities","Plan the learning experiences, then identify the results, then decide on evidence"],"answer":2,"explanation":"Backward design starts from the goal, then defines acceptable evidence (assessment), and only then plans activities, so that activities serve the goal rather than the other way round.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VI की एक शिक्षिका पश्चगामी डिज़ाइन (विगिन्स और मैकटाइ) का उपयोग करके एक इकाई की योजना बनाती है। उसे योजना-चरणों के किस क्रम का पालन करना चाहिए?","optionsHi":["रोचक गतिविधियाँ चुनना, फिर उद्देश्य लिखना, फिर परीक्षा तैयार करना","पहले परीक्षा लिखना, फिर गतिविधियाँ चुनना, फिर उद्देश्य लिखना","वांछित परिणाम तय करना, फिर साक्ष्य तय करना, फिर गतिविधियाँ योजनाबद्ध करना","अधिगम-अनुभव योजनाबद्ध करना, फिर परिणाम पहचानना, फिर साक्ष्य तय करना"],"explanationHi":"पश्चगामी डिज़ाइन लक्ष्य से शुरू होता है, फिर स्वीकार्य साक्ष्य (आकलन) निर्धारित करता है, और उसके बाद ही गतिविधियाँ योजनाबद्ध करता है, ताकि गतिविधियाँ लक्ष्य की सेवा करें, उलटा नहीं।"},
  {"id":"cdp-pedagogy-subjects-1348","question":"Which of these is the best-stated learning outcome for a Class II lesson on measurement?","options":["The teacher will explain the concept of length with several examples","Children will understand measurement and appreciate its importance in life","Children will do the activity given on page 34 of the textbook","Children will compare two lengths using hand spans and give reasons"],"answer":3,"explanation":"A good learning outcome states what the child will be able to do in observable terms. The others describe teacher actions, a vague state ('understand') or an activity rather than learning.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"माप पर कक्षा II के पाठ के लिए इनमें से सबसे अच्छी तरह कहा गया अधिगम-परिणाम कौन-सा है?","optionsHi":["शिक्षक कई उदाहरणों के साथ लंबाई की संकल्पना समझाएगा","बच्चे माप को समझेंगे और जीवन में उसके महत्त्व की सराहना करेंगे","बच्चे पाठ्यपुस्तक के पृष्ठ 34 पर दी गई गतिविधि करेंगे","बच्चे बित्ते (hand spans) से दो लंबाइयों की तुलना करेंगे और कारण देंगे"],"explanationHi":"अच्छा अधिगम-परिणाम बताता है कि बच्चा अवलोकनीय रूप में क्या कर सकेगा। अन्य शिक्षक की क्रियाओं, अस्पष्ट अवस्था ('समझना') या अधिगम के बजाय गतिविधि का वर्णन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1349","question":"Consider the following statements about the class-wise learning outcomes developed by NCERT for the elementary stage: 1. They describe what children should be able to do by the end of each class in each subject. 2. They prescribe a single teaching method that every teacher must follow. 3. Along with the outcomes, suggested pedagogical processes are given to help achieve them. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"NCERT's learning outcomes are competency benchmarks for each class, accompanied by suggested pedagogical processes. They guide teaching and assessment but do not mandate one method, so statement 2 is false.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"प्रारंभिक चरण के लिए NCERT द्वारा विकसित कक्षावार अधिगम-प्रतिफलों के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. वे बताते हैं कि प्रत्येक विषय में प्रत्येक कक्षा के अंत तक बच्चों को क्या कर पाना चाहिए। 2. वे एक ही शिक्षण-विधि निर्धारित करते हैं जिसका प्रत्येक शिक्षक को पालन करना चाहिए। 3. प्रतिफलों के साथ उन्हें प्राप्त करने में मदद के लिए सुझाई गई शिक्षणशास्त्रीय प्रक्रियाएँ दी गई हैं। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"NCERT के अधिगम-प्रतिफल प्रत्येक कक्षा के लिए योग्यता-मानदंड हैं, जिनके साथ सुझाई गई शिक्षणशास्त्रीय प्रक्रियाएँ हैं। वे शिक्षण और आकलन का मार्गदर्शन करते हैं पर एक विधि अनिवार्य नहीं करते, इसलिए कथन 2 असत्य है।"},
  {"id":"cdp-pedagogy-subjects-1350","question":"In the Herbartian lesson plan as commonly used in Indian teacher education, which is the correct sequence of the five formal steps?","options":["Presentation, Preparation, Generalisation, Association, Application","Preparation, Presentation, Association, Generalisation, Application","Preparation, Association, Presentation, Application, Generalisation","Preparation, Presentation, Generalisation, Association, Application"],"answer":1,"explanation":"The steps move from preparing the mind and presenting new material to comparing and associating it, drawing a general rule, and finally applying it. Generalisation needs association first.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"भारतीय शिक्षक-शिक्षा में सामान्यतः प्रयुक्त हर्बार्टीय पाठ-योजना में पाँच औपचारिक चरणों का सही क्रम कौन-सा है?","optionsHi":["प्रस्तुतीकरण, प्रस्तावना, सामान्यीकरण, साहचर्य, अनुप्रयोग","प्रस्तावना, प्रस्तुतीकरण, साहचर्य, सामान्यीकरण, अनुप्रयोग","प्रस्तावना, साहचर्य, प्रस्तुतीकरण, अनुप्रयोग, सामान्यीकरण","प्रस्तावना, प्रस्तुतीकरण, सामान्यीकरण, साहचर्य, अनुप्रयोग"],"explanationHi":"चरण मन को तैयार करने और नई सामग्री प्रस्तुत करने से, उसकी तुलना और साहचर्य करने, सामान्य नियम निकालने, और अंत में उसे लागू करने की ओर बढ़ते हैं। सामान्यीकरण के लिए पहले साहचर्य चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1351","question":"A Class VII science teacher using the 5E model has already engaged students, let them explore floating and sinking, and helped them explain it with the idea of density. Now she asks them to predict whether an egg will float in salt water and test it. Which phase is this?","options":["Engage","Explain","Elaborate","Evaluate"],"answer":2,"explanation":"Elaborate extends and applies the newly explained concept to a new situation. Evaluate is where understanding is assessed, though assessment can occur throughout.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"5E मॉडल का उपयोग करने वाली कक्षा VII की एक विज्ञान शिक्षिका विद्यार्थियों को पहले ही संलग्न कर चुकी है, उन्हें तैरने और डूबने की खोज करने दे चुकी है, और घनत्व के विचार से उसे समझाने में उनकी मदद कर चुकी है। अब वह उनसे पूर्वानुमान लगाने को कहती है कि अंडा नमकीन पानी में तैरेगा या नहीं और उसे परखने को। यह कौन-सा चरण है?","optionsHi":["संलग्न करना (Engage)","समझाना (Explain)","विस्तार करना (Elaborate)","मूल्यांकन करना (Evaluate)"],"explanationHi":"विस्तार करना नई समझाई गई संकल्पना को नई परिस्थिति में बढ़ाता और लागू करता है। मूल्यांकन वह है जहाँ समझ का आकलन होता है, यद्यपि आकलन पूरे समय हो सकता है।"},
  {"id":"cdp-pedagogy-subjects-1352","question":"Ten minutes into her planned Class IV lesson on multiplication, Ms Joshi realises most children have not understood repeated addition, which the lesson assumes. What should she do?","options":["Continue with the plan so that the syllabus stays on schedule","Abandon the topic altogether and move on to the next chapter","Give extra homework on multiplication so children practise at home","Adapt the plan to revisit repeated addition with concrete objects"],"answer":3,"explanation":"A lesson plan is a guide, not a script; responding to evidence of children's understanding is what good teaching requires. Pushing ahead builds on a weak foundation.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"गुणा पर अपने नियोजित कक्षा IV के पाठ के दस मिनट बाद, सुश्री जोशी को एहसास होता है कि अधिकांश बच्चों ने बार-बार जोड़ को नहीं समझा, जिसे पाठ मानकर चलता है। उसे क्या करना चाहिए?","optionsHi":["योजना के साथ जारी रखना ताकि पाठ्यक्रम समय पर रहे","विषय को पूरी तरह छोड़ देना और अगले अध्याय पर चले जाना","गुणा पर अतिरिक्त गृहकार्य देना ताकि बच्चे घर पर अभ्यास करें","योजना को अनुकूलित करना और बार-बार जोड़ को ठोस वस्तुओं के साथ फिर से देखना"],"explanationHi":"पाठ-योजना एक मार्गदर्शक है, पटकथा नहीं; बच्चों की समझ के साक्ष्य का उत्तर देना ही अच्छे शिक्षण की माँग है। आगे बढ़ते जाना कमज़ोर नींव पर निर्माण करता है।"},
  {"id":"cdp-pedagogy-subjects-1353","question":"A Class III teacher starts a lesson on floating and sinking by asking, 'What things have you seen floating in the pond or in a bucket of water? What sinks?' What is the main purpose of this step?","options":["To draw out children’s prior ideas so new learning links to them","To fill the first few minutes while the children settle down","To test the children quickly and give them marks for their answers","To show children that their everyday ideas are usually wrong"],"answer":0,"explanation":"Eliciting prior knowledge links the lesson to experience and reveals alternative conceptions the teacher must address. It is diagnostic and motivating, not a graded test.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा III की एक शिक्षिका तैरने और डूबने पर पाठ यह पूछकर शुरू करती है, 'तुमने तालाब या पानी की बाल्टी में कौन-सी चीज़ें तैरती देखी हैं? कौन-सी डूबती हैं?' इस चरण का मुख्य उद्देश्य क्या है?","optionsHi":["बच्चों के पूर्व विचारों को निकालना ताकि नया अधिगम उनसे जुड़े","पहले कुछ मिनट भरना जब बच्चे बैठकर शांत हो जाएँ","बच्चों की जल्दी परीक्षा लेना और उनके उत्तरों पर अंक देना","बच्चों को दिखाना कि उनके रोज़मर्रा के विचार प्रायः गलत होते हैं"],"explanationHi":"पूर्व ज्ञान को निकालना पाठ को अनुभव से जोड़ता है और वैकल्पिक संकल्पनाओं को प्रकट करता है जिन्हें शिक्षक को संबोधित करना है। यह निदानात्मक और प्रेरक है, अंक वाली परीक्षा नहीं।"},
  {"id":"cdp-pedagogy-subjects-1354","question":"Consider the following statements about planning: 1. A unit plan organises several lessons around a coherent theme or set of learning outcomes. 2. A year plan helps a teacher distribute units across the session, keeping in mind holidays and local events. 3. Once a unit plan is made, individual lesson plans are unnecessary. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Year, unit and lesson plans work at different levels and support each other; daily lessons still need specific plans for activities and checks. Statement 3 is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"योजना के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इकाई-योजना एक सुसंगत विषय या अधिगम-प्रतिफलों के समूह के इर्द-गिर्द कई पाठों को संगठित करती है। 2. वार्षिक योजना शिक्षक को छुट्टियों और स्थानीय आयोजनों को ध्यान में रखते हुए सत्र भर में इकाइयाँ बाँटने में मदद करती है। 3. एक बार इकाई-योजना बन जाने पर अलग-अलग पाठ-योजनाएँ अनावश्यक हैं। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"वार्षिक, इकाई और पाठ योजनाएँ अलग-अलग स्तरों पर कार्य करती हैं और एक-दूसरे का समर्थन करती हैं; दैनिक पाठों को फिर भी गतिविधियों और जाँचों की विशिष्ट योजनाएँ चाहिए। कथन 3 असत्य है।"},
  {"id":"cdp-pedagogy-subjects-1355","question":"Which Class V lesson plan opening best reflects a constructivist approach to teaching about why some foods spoil faster?","options":["The teacher reads out the definition of food spoilage and children copy it","The teacher writes ten causes of food spoilage on the board for children to learn","Children say why roti spoils before pickle, share ideas and plan a test","The teacher shows pictures of spoiled food and tells children never to eat it"],"answer":2,"explanation":"Constructivist lessons begin from a puzzling, real question and children's own ideas, which they then test. The other openings transmit conclusions and leave children passive.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कुछ खाद्य पदार्थ तेज़ी से क्यों खराब होते हैं, इस पर पढ़ाने के लिए कक्षा V की कौन-सी पाठ-योजना की शुरुआत रचनावादी उपागम को सबसे अच्छी तरह दर्शाती है?","optionsHi":["शिक्षक खाद्य-ह्रास की परिभाषा पढ़कर सुनाता है और बच्चे उसे उतारते हैं","शिक्षक बोर्ड पर खाद्य-ह्रास के दस कारण लिखता है जिन्हें बच्चे सीखें","बच्चे बताते हैं कि रोटी अचार से पहले क्यों खराब होती है, विचार साझा करते हैं और परीक्षण की योजना बनाते हैं","शिक्षक खराब भोजन के चित्र दिखाता है और बच्चों से कहता है कि उसे कभी न खाएँ"],"explanationHi":"रचनावादी पाठ एक पेचीदा, वास्तविक प्रश्न और बच्चों के अपने विचारों से शुरू होते हैं, जिन्हें वे फिर परखते हैं। अन्य शुरुआतें निष्कर्ष प्रेषित करती हैं और बच्चों को निष्क्रिय छोड़ देती हैं।"},
  {"id":"cdp-pedagogy-subjects-1356","question":"At the end of a Class VI lesson on factors, a teacher gives each student a slip asking: 'Write all factors of 18' and 'Is 1 a factor of every number? Why?' She sorts the slips before planning the next class. What is the main purpose?","options":["To collect marks from every student for the end-of-term report card","To check each student’s understanding and plan the next lesson from it","To catch and punish the students who did not pay attention during the lesson","To keep the students busy and quiet until the bell rings for recess"],"answer":1,"explanation":"An exit ticket is a quick formative check; sorting responses shows who needs support or extension, so the next lesson is planned from evidence.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"गुणनखंडों पर कक्षा VI के पाठ के अंत में एक शिक्षिका प्रत्येक विद्यार्थी को पर्ची देती है जिसमें पूछा गया है: '18 के सभी गुणनखंड लिखिए' और 'क्या 1 प्रत्येक संख्या का गुणनखंड है? क्यों?' वह अगली कक्षा की योजना बनाने से पहले पर्चियों को छाँटती है। मुख्य उद्देश्य क्या है?","optionsHi":["सत्र-अंत के रिपोर्ट कार्ड के लिए प्रत्येक विद्यार्थी के अंक एकत्र करना","प्रत्येक विद्यार्थी की समझ जाँचना और उसी से अगला पाठ योजनाबद्ध करना","पाठ के दौरान ध्यान न देने वाले विद्यार्थियों को पकड़ना और दंड देना","घंटी बजने तक विद्यार्थियों को व्यस्त और शांत रखना"],"explanationHi":"निर्गम-पर्ची एक त्वरित रचनात्मक जाँच है; प्रतिक्रियाओं को छाँटना दिखाता है कि किसे सहायता या विस्तार चाहिए, इसलिए अगला पाठ साक्ष्य से योजनाबद्ध होता है।"},
  {"id":"cdp-pedagogy-subjects-1357","question":"A Class VII learning outcome states: 'The learner explains why seasons change in a year.' The unit test has one question: 'Name the four seasons in India.' What is the main problem?","options":["The question is far too difficult for most Class VII students to answer","There is no problem, since the question is about seasons as well","The outcome itself is too simple for Class VII and should be deleted","The item checks recall of names, not the ability to explain the cause"],"answer":3,"explanation":"Assessment must match the cognitive demand of the outcome. 'Explain why' needs an item about the tilt of the Earth's axis and its revolution, not a recall list.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VII का एक अधिगम-प्रतिफल कहता है: 'शिक्षार्थी समझाता है कि वर्ष में ऋतुएँ क्यों बदलती हैं।' इकाई-परीक्षा में एक प्रश्न है: 'भारत की चार ऋतुओं के नाम बताइए।' मुख्य समस्या क्या है?","optionsHi":["प्रश्न कक्षा VII के अधिकांश विद्यार्थियों के लिए उत्तर देने में बहुत कठिन है","कोई समस्या नहीं है, क्योंकि प्रश्न भी ऋतुओं के बारे में है","प्रतिफल स्वयं कक्षा VII के लिए बहुत सरल है और उसे हटा देना चाहिए","प्रश्न नामों के स्मरण की जाँच करता है, कारण समझाने की क्षमता की नहीं"],"explanationHi":"आकलन को प्रतिफल की संज्ञानात्मक माँग से मेल खाना चाहिए। 'क्यों समझाइए' के लिए पृथ्वी की धुरी के झुकाव और उसकी परिक्रमा पर प्रश्न चाहिए, स्मरण की सूची नहीं।"},
  {"id":"cdp-pedagogy-subjects-1358","question":"Ms Kumari teaches Classes I, II and III together in one room in a single-teacher school in Jharkhand. Which planning approach suits this multigrade setting best?","options":["Teach Class III while Classes I and II sit silently, then rotate the classes each day","A common theme with tiered tasks, peer support and self-learning materials","Combine all three classes and teach the Class III syllabus to everyone","Teach only the class that has an important examination coming up soon"],"answer":1,"explanation":"Multigrade teaching works through common themes, differentiated tasks, peer learning and graded self-learning materials. Keeping groups idle or teaching one level to all wastes learning time.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"सुश्री कुमारी झारखंड के एकल-शिक्षक विद्यालय में कक्षा I, II और III को एक ही कमरे में साथ पढ़ाती हैं। कौन-सा योजना-उपागम इस बहु-श्रेणी स्थिति के सबसे अनुकूल है?","optionsHi":["कक्षा III को पढ़ाना जबकि कक्षा I और II चुपचाप बैठें, फिर हर दिन कक्षाओं को बदलना","एक साझा विषय, जिसमें स्तरित कार्य, सहपाठी सहायता और स्व-अधिगम सामग्री हो","तीनों कक्षाओं को मिलाकर सबको कक्षा III का पाठ्यक्रम पढ़ाना","केवल उस कक्षा को पढ़ाना जिसकी कोई महत्त्वपूर्ण परीक्षा जल्दी आ रही हो"],"explanationHi":"बहु-श्रेणी शिक्षण साझा विषयों, विभेदित कार्यों, सहपाठी अधिगम और श्रेणीबद्ध स्व-अधिगम सामग्री के माध्यम से काम करता है। समूहों को निष्क्रिय रखना या सबको एक ही स्तर पढ़ाना अधिगम का समय व्यर्थ करता है।"},
  {"id":"cdp-pedagogy-subjects-1359","question":"A Class VI objective reads: 'Given an outline map of India, students will locate at least 8 of the 10 major rivers.' In the ABCD format of writing objectives, the phrase 'at least 8 of the 10' is the:","options":["Audience","Behaviour","Condition","Degree"],"answer":3,"explanation":"ABCD stands for Audience (students), Behaviour (locate), Condition (given an outline map) and Degree (the criterion for success, here at least 8 of 10).","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VI का एक उद्देश्य है: 'भारत का रेखा-मानचित्र दिए जाने पर, विद्यार्थी 10 प्रमुख नदियों में से कम से कम 8 को अंकित करेंगे।' उद्देश्य लिखने के ABCD प्रारूप में, वाक्यांश '10 में से कम से कम 8' है:","optionsHi":["श्रोता (Audience)","व्यवहार (Behaviour)","परिस्थिति (Condition)","मात्रा/स्तर (Degree)"],"explanationHi":"ABCD का अर्थ है Audience (विद्यार्थी), Behaviour (अंकित करना), Condition (रेखा-मानचित्र दिए जाने पर) और Degree (सफलता की कसौटी, यहाँ 10 में से कम से कम 8)।"},
  {"id":"cdp-pedagogy-subjects-1360","question":"A Class V teacher says proudly, 'I always finish the textbook by January.' Yet a test shows most of her students cannot read a simple bar graph, which is a Class V learning outcome. What does this most strongly suggest?","options":["Her planning aimed at covering chapters, not at learning outcomes","The learning outcome is too difficult for Class V and should be removed","Her students did not study at home or revise what was taught","Textbooks should be finished even earlier, by December, to allow revision"],"answer":0,"explanation":"Learning-outcome-based planning asks whether children can do what was intended, not whether pages were covered. Finishing early without learning shows a coverage mindset.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कक्षा V की एक शिक्षिका गर्व से कहती है, 'मैं पाठ्यपुस्तक हमेशा जनवरी तक पूरी कर लेती हूँ।' फिर भी एक परीक्षा दिखाती है कि उसके अधिकांश विद्यार्थी सरल स्तंभ-आलेख नहीं पढ़ सकते, जो कक्षा V का अधिगम-प्रतिफल है। यह सबसे अधिक क्या सुझाता है?","optionsHi":["उसकी योजना का लक्ष्य अधिगम-प्रतिफल नहीं, अध्याय पूरे करना था","अधिगम-प्रतिफल कक्षा V के लिए बहुत कठिन है और उसे हटा देना चाहिए","उसके विद्यार्थियों ने घर पर अध्ययन या जो पढ़ाया गया उसकी पुनरावृत्ति नहीं की","पाठ्यपुस्तकें और भी पहले, दिसंबर तक, पूरी होनी चाहिए ताकि पुनरावृत्ति के लिए समय मिले"],"explanationHi":"अधिगम-प्रतिफल-आधारित योजना पूछती है कि क्या बच्चे वह कर सकते हैं जो अभिप्रेत था, यह नहीं कि पृष्ठ पूरे हुए या नहीं। अधिगम के बिना जल्दी पूरा करना कवरेज की मानसिकता दिखाता है।"},
  {"id":"cdp-pedagogy-subjects-1361","question":"Which way of closing a Class IV lesson on food chains is most effective for learning?","options":["The teacher carefully summarises the whole lesson herself and then gives homework","The lesson ends when the bell rings, wherever the teacher happens to be","Children sum up in their own words, raise a question, and she links it ahead","The teacher asks ‘Any questions?’ and moves on if no one speaks up at once"],"answer":2,"explanation":"Closure that has learners consolidate and articulate their own understanding, and connect forward, helps memory and shows the teacher what was learnt. Teacher-only summaries keep children passive.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"खाद्य श्रृंखलाओं पर कक्षा IV के पाठ को समाप्त करने का कौन-सा तरीका अधिगम के लिए सबसे प्रभावी है?","optionsHi":["शिक्षिका पूरे पाठ का स्वयं ध्यानपूर्वक सारांश देती है और फिर गृहकार्य देती है","पाठ तब समाप्त होता है जब घंटी बजती है, शिक्षिका जहाँ भी हो","बच्चे अपने शब्दों में सारांश देते हैं, प्रश्न उठाते हैं, और वह उसे आगे से जोड़ती है","शिक्षिका पूछती है 'कोई प्रश्न?' और यदि तुरंत कोई न बोले तो आगे बढ़ जाती है"],"explanationHi":"ऐसा समापन जिसमें अधिगमकर्ता अपनी समझ को समेकित और व्यक्त करें, और आगे से जोड़ें, स्मृति में सहायक होता है और शिक्षक को दिखाता है कि क्या सीखा गया। केवल शिक्षक का सारांश बच्चों को निष्क्रिय रखता है।"},
  {"id":"cdp-pedagogy-subjects-1362","question":"While writing objectives for a Class VII lesson, which verb gives the most observable and measurable objective?","options":["Know","Appreciate","Classify","Understand"],"answer":2,"explanation":"'Classify' names an action a teacher can see and check. 'Know', 'understand' and 'appreciate' describe inner states that need to be turned into observable behaviours before they can be assessed.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VII के पाठ के उद्देश्य लिखते समय, कौन-सी क्रिया सबसे अधिक अवलोकनीय और मापने योग्य उद्देश्य देती है?","optionsHi":["जानना","सराहना करना","वर्गीकृत करना","समझना"],"explanationHi":"'वर्गीकृत करना' ऐसी क्रिया का नाम है जिसे शिक्षक देख और जाँच सकता है। 'जानना', 'समझना' और 'सराहना करना' आंतरिक अवस्थाओं का वर्णन करते हैं जिन्हें आकलन से पहले अवलोकनीय व्यवहारों में बदलना पड़ता है।"},
  {"id":"cdp-pedagogy-subjects-1363","question":"A teacher in a Chennai city school uses a textbook example of 'counting cattle in the village' for Class II subtraction. Her students live in flats and have never seen cattle closely. What would be the best adaptation while planning?","options":["Use local examples, like buses at a stop, keeping the same maths","Keep the textbook example, since textbooks must be followed exactly","Skip subtraction until the students can visit a village on a trip","Ask students to memorise the textbook example word for word"],"answer":0,"explanation":"Contextualising examples to children's lives makes the concept meaningful while keeping the learning goal unchanged; NCF encourages linking school knowledge to children's experiences.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"चेन्नई के एक शहरी विद्यालय की शिक्षिका कक्षा II के घटाव के लिए 'गाँव में पशु गिनना' का पाठ्यपुस्तक-उदाहरण उपयोग करती है। उसके विद्यार्थी फ़्लैटों में रहते हैं और उन्होंने पशुओं को कभी निकट से नहीं देखा। योजना बनाते समय सबसे अच्छा अनुकूलन क्या होगा?","optionsHi":["स्थानीय उदाहरण, जैसे बस-स्टॉप पर बसें, उपयोग करना, गणित वही रखते हुए","पाठ्यपुस्तक का उदाहरण रखना, क्योंकि पाठ्यपुस्तकों का ठीक पालन होना चाहिए","घटाव तब तक छोड़ देना जब तक विद्यार्थी यात्रा पर गाँव न जा सकें","विद्यार्थियों से पाठ्यपुस्तक का उदाहरण शब्दशः याद करवाना"],"explanationHi":"उदाहरणों को बच्चों के जीवन के अनुसार संदर्भित करना अधिगम-लक्ष्य को बदले बिना संकल्पना को सार्थक बनाता है; NCF विद्यालयी ज्ञान को बच्चों के अनुभवों से जोड़ने को प्रोत्साहित करती है।"},
  {"id":"cdp-pedagogy-subjects-1364","question":"Consider the following statements about the NIPUN Bharat Mission launched in 2021: 1. Its aim is that every child attains foundational literacy and numeracy by the end of Grade 3. 2. It covers children in the age group of 3 to 9 years. 3. It requires that early literacy be taught only in English. Which of these are correct?","options":["1 and 3 only","2 and 3 only","1, 2 and 3","1 and 2 only"],"answer":3,"explanation":"NIPUN Bharat aims at universal FLN by the end of Grade 3 for children aged 3-9, and in line with NEP 2020 it encourages learning in the home or local language. Statement 3 is false.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"2021 में आरंभ किए गए निपुण भारत मिशन के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. इसका लक्ष्य है कि प्रत्येक बच्चा कक्षा 3 के अंत तक आधारभूत साक्षरता और संख्याज्ञान प्राप्त करे। 2. यह 3 से 9 वर्ष के आयु-वर्ग के बच्चों को समेटता है। 3. यह माँग करता है कि प्रारंभिक साक्षरता केवल अंग्रेज़ी में पढ़ाई जाए। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 2 और 3","1, 2 और 3","केवल 1 और 2"],"explanationHi":"निपुण भारत का लक्ष्य 3-9 वर्ष के बच्चों के लिए कक्षा 3 के अंत तक सार्वभौमिक FLN है, और NEP 2020 के अनुरूप वह घर या स्थानीय भाषा में अधिगम को प्रोत्साहित करता है। कथन 3 असत्य है।"},
  {"id":"cdp-pedagogy-subjects-1365","question":"A Class III teacher plans a two-week theme on 'Water': children measure water use at home (maths), write a poem on rain (language), and survey water sources (EVS). What is the main strength of this plan?","options":["It reduces the number of separate subjects that the teacher must plan and teach","It joins subjects around a meaningful theme so children see connections","It allows the teacher to avoid using the prescribed textbooks entirely","It ensures that every child in the class scores the same marks in tests"],"answer":1,"explanation":"Thematic, integrated planning mirrors how children experience the world and lets skills from different subjects support each other, as NCF recommends for the early years.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा III की एक शिक्षिका 'जल' पर दो सप्ताह के विषय की योजना बनाती है: बच्चे घर पर जल-उपयोग मापते हैं (गणित), वर्षा पर कविता लिखते हैं (भाषा), और जल-स्रोतों का सर्वेक्षण करते हैं (EVS)। इस योजना की मुख्य शक्ति क्या है?","optionsHi":["यह उन अलग-अलग विषयों की संख्या घटाती है जिनकी शिक्षिका को योजना बनानी और पढ़ाना पड़ता है","यह विषयों को एक सार्थक विषयवस्तु के इर्द-गिर्द जोड़ती है ताकि बच्चे संबंध देखें","यह शिक्षिका को निर्धारित पाठ्यपुस्तकों के उपयोग से पूरी तरह बचने देती है","यह सुनिश्चित करती है कि कक्षा का हर बच्चा परीक्षाओं में समान अंक पाए"],"explanationHi":"विषयवस्तु-आधारित, समेकित योजना इस बात को दर्शाती है कि बच्चे दुनिया को कैसे अनुभव करते हैं और विभिन्न विषयों के कौशलों को एक-दूसरे का समर्थन करने देती है, जैसा NCF प्रारंभिक वर्षों के लिए अनुशंसा करती है।"},
  {"id":"cdp-pedagogy-subjects-1366","question":"A teacher keeps a column called 'Reflection after the lesson' in her plan book, where she notes what worked, which children struggled and what she will change. What does this mainly support?","options":["Reflective practice that uses lesson evidence to improve teaching","Completing the official records that are checked during inspection","Comparing her lessons with colleagues’ lessons to decide promotions","Recording students’ marks and attendance for the report card"],"answer":0,"explanation":"Post-lesson reflection turns each lesson into data for improvement, the core of being a reflective practitioner. It is not mainly an administrative or grading record.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"एक शिक्षिका अपनी योजना-पुस्तिका में 'पाठ के बाद चिंतन' नाम का स्तंभ रखती है, जहाँ वह नोट करती है कि क्या कारगर रहा, किन बच्चों को कठिनाई हुई और वह क्या बदलेगी। यह मुख्यतः किसका समर्थन करता है?","optionsHi":["चिंतनशील अभ्यास, जो शिक्षण को सुधारने के लिए पाठ के साक्ष्य का उपयोग करता है","निरीक्षण के समय जाँचे जाने वाले आधिकारिक अभिलेखों को पूरा करना","पदोन्नति तय करने के लिए अपने पाठों की सहकर्मियों के पाठों से तुलना करना","रिपोर्ट कार्ड के लिए विद्यार्थियों के अंक और उपस्थिति दर्ज करना"],"explanationHi":"पाठ के बाद का चिंतन प्रत्येक पाठ को सुधार के लिए आँकड़ा बनाता है, जो चिंतनशील व्यवसायी होने का मूल है। यह मुख्यतः प्रशासनिक या ग्रेडिंग अभिलेख नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1367","question":"A Class II teacher writes the objective: 'Children will show willingness to share play materials with others.' To which domain does this objective belong?","options":["Cognitive","Psychomotor","Affective","Metacognitive"],"answer":2,"explanation":"Willingness, attitudes and values belong to the affective domain (Krathwohl). Cognitive deals with knowledge and thinking, and psychomotor with physical skills.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा II की एक शिक्षिका उद्देश्य लिखती है: 'बच्चे दूसरों के साथ खेल-सामग्री बाँटने की इच्छा दिखाएँगे।' यह उद्देश्य किस क्षेत्र का है?","optionsHi":["संज्ञानात्मक","मनो-गामक (psychomotor)","भावात्मक","अधिसंज्ञानात्मक"],"explanationHi":"इच्छा, अभिवृत्तियाँ और मूल्य भावात्मक क्षेत्र (क्रेथवोहल) के हैं। संज्ञानात्मक क्षेत्र ज्ञान और चिंतन से और मनो-गामक शारीरिक कौशलों से संबंधित है।"},
  {"id":"cdp-pedagogy-subjects-1368","question":"In a village school in Punjab, attendance drops sharply during the wheat harvest, and many children help in the fields. How should the class teacher plan her year?","options":["Keep the year plan unchanged and mark the absent children as failing the term","Plan key topics around the harvest, use it as context, and plan catch-up","Give double homework during the harvest so that no work is lost","Report the parents of absent children to the education authorities"],"answer":1,"explanation":"Planning that takes the local calendar into account reduces learning loss and connects school to children's lives. Penalising children for a community reality is neither fair nor effective.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs","questionHi":"पंजाब के एक ग्रामीण विद्यालय में गेहूँ की कटाई के दौरान उपस्थिति तेज़ी से गिरती है, क्योंकि कई बच्चे खेतों में मदद करते हैं। कक्षा-शिक्षिका को अपने वर्ष की योजना कैसे बनानी चाहिए?","optionsHi":["वार्षिक योजना को अपरिवर्तित रखना और अनुपस्थित बच्चों को सत्र में अनुत्तीर्ण अंकित करना","प्रमुख विषयों को कटाई के इर्द-गिर्द योजनाबद्ध करना, उसे संदर्भ के रूप में उपयोग करना, और पूर्ति (catch-up) की योजना बनाना","कटाई के दौरान दोगुना गृहकार्य देना ताकि कोई कार्य न छूटे","अनुपस्थित बच्चों के माता-पिता की शिक्षा अधिकारियों से शिकायत करना"],"explanationHi":"स्थानीय कैलेंडर को ध्यान में रखने वाली योजना अधिगम की हानि घटाती है और विद्यालय को बच्चों के जीवन से जोड़ती है। किसी सामुदायिक वास्तविकता के लिए बच्चों को दंडित करना न उचित है, न प्रभावी।"},
  {"id":"cdp-pedagogy-subjects-1369","question":"At the start of a Class VI writing task, the teacher shares a short list: 'A good letter here will: have a clear greeting and closing; give two reasons for the request; use polite words.' Students later check their own letters against it. What is the main benefit?","options":["It saves the teacher from having to read or correct any of the students’ letters","It ensures that all the letters written in the class are identical","It is useful only for the teacher’s own marking at the end of the task","Students see what success looks like and can improve their own work"],"answer":3,"explanation":"Shared success criteria make the target clear and enable self- and peer-assessment, a key practice of assessment for learning. They guide quality without forcing identical products.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VI के लेखन-कार्य के आरंभ में शिक्षिका एक छोटी सूची साझा करती है: 'यहाँ एक अच्छे पत्र में होगा: स्पष्ट संबोधन और समापन; अनुरोध के दो कारण; विनम्र शब्दों का प्रयोग।' विद्यार्थी बाद में अपने पत्र इसके विरुद्ध जाँचते हैं। मुख्य लाभ क्या है?","optionsHi":["यह शिक्षिका को विद्यार्थियों के किसी भी पत्र को पढ़ने या सुधारने से बचा लेता है","यह सुनिश्चित करता है कि कक्षा में लिखे गए सभी पत्र एक जैसे हों","यह केवल कार्य के अंत में शिक्षिका के अपने अंकन के लिए उपयोगी है","विद्यार्थी देखते हैं कि सफलता कैसी दिखती है और अपना कार्य स्वयं सुधार सकते हैं"],"explanationHi":"साझा सफलता-मानदंड लक्ष्य को स्पष्ट करते हैं और स्व-आकलन तथा सहपाठी-आकलन को संभव बनाते हैं, जो अधिगम के लिए आकलन की एक मुख्य प्रथा है। वे एक जैसे उत्पाद बनवाए बिना गुणवत्ता का मार्गदर्शन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1370","question":"Assertion (A): A good teacher follows the written lesson plan exactly, whatever happens in class. Reason (R): Planning gives direction and structure to teaching.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Planning does give direction, but good teachers adjust to evidence of learning, children's questions and unforeseen events. So R is true while A is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): अच्छा शिक्षक लिखित पाठ-योजना का ठीक पालन करता है, कक्षा में चाहे जो हो। कारण (R): योजना शिक्षण को दिशा और संरचना देती है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"योजना दिशा अवश्य देती है, पर अच्छे शिक्षक अधिगम के साक्ष्य, बच्चों के प्रश्नों और अप्रत्याशित घटनाओं के अनुसार समायोजन करते हैं। इसलिए R सत्य है जबकि A असत्य है।"},
  {"id":"cdp-pedagogy-subjects-1371","question":"In Gagné's nine events of instruction, which three events come first, in order?","options":["Gaining attention, stating the objective, recalling prior learning","Presenting the content, gaining attention, providing feedback","Stating the objective, presenting the content, assessing performance","Recalling prior learning, gaining attention, eliciting performance"],"answer":0,"explanation":"Gagné's sequence begins by gaining attention, telling learners the objective and stimulating recall of prior learning, before presenting content, guiding learning, eliciting performance, giving feedback, assessing and enhancing retention and transfer.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"गैग्ने की अनुदेशन की नौ घटनाओं में, पहली तीन घटनाएँ क्रम से कौन-सी हैं?","optionsHi":["ध्यान आकर्षित करना, उद्देश्य बताना, पूर्व अधिगम का स्मरण कराना","विषय-वस्तु प्रस्तुत करना, ध्यान आकर्षित करना, प्रतिपुष्टि देना","उद्देश्य बताना, विषय-वस्तु प्रस्तुत करना, प्रदर्शन का आकलन करना","पूर्व अधिगम का स्मरण कराना, ध्यान आकर्षित करना, प्रदर्शन उत्पन्न करवाना"],"explanationHi":"गैग्ने का क्रम ध्यान आकर्षित करने, अधिगमकर्ताओं को उद्देश्य बताने और पूर्व अधिगम के स्मरण को उत्प्रेरित करने से शुरू होता है, उसके बाद विषय-वस्तु प्रस्तुत करना, अधिगम का मार्गदर्शन, प्रदर्शन उत्पन्न करवाना, प्रतिपुष्टि देना, आकलन करना और धारण तथा अंतरण को बढ़ाना आता है।"},
  {"id":"cdp-pedagogy-subjects-1372","question":"A Class 4 teacher asks, ‘Why do many trees shed their leaves before summer?’ and, when no hand goes up within two seconds, answers it herself. The most useful advice for her is to:","options":["ask only easy questions that children can answer at once without pausing","put the question directly to the brightest child so the lesson moves on","give more wait time, and let children talk in pairs before answering","give the answer first and then ask the question to check memory"],"answer":2,"explanation":"Thinking questions need wait time; research shows longer pauses produce more and better answers. Answering herself teaches children to wait rather than think.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 की एक शिक्षिका पूछती है, ‘कई पेड़ गर्मी से पहले अपनी पत्तियाँ क्यों गिराते हैं?’ और जब दो सेकंड के भीतर कोई हाथ नहीं उठता, तो वह स्वयं उत्तर दे देती है। उसके लिए सबसे उपयोगी सलाह है:","optionsHi":["केवल आसान प्रश्न पूछना जिनका उत्तर बच्चे बिना रुके तुरंत दे सकें","प्रश्न सीधे सबसे तेज़ बच्चे से पूछना ताकि पाठ आगे बढ़े","अधिक प्रतीक्षा-समय देना, और उत्तर से पहले बच्चों को जोड़ियों में बात करने देना","पहले उत्तर देना और फिर स्मृति जाँचने के लिए प्रश्न पूछना"],"explanationHi":"चिंतन वाले प्रश्नों को प्रतीक्षा-समय चाहिए; शोध दिखाता है कि लंबे विराम अधिक और बेहतर उत्तर देते हैं। स्वयं उत्तर देना बच्चों को सोचने के बजाय प्रतीक्षा करना सिखाता है।"},
  {"id":"cdp-pedagogy-subjects-1373","question":"Which pair shows a closed question followed by an open question?","options":["What would you like to know about bats? / Is a bat a bird?","Is a bat a bird? / What would you like to know about bats?","Where do bats live? / Name two other animals that can fly.","How many legs does a bat have? / Does a bat have wings?"],"answer":1,"explanation":"‘Is a bat a bird?’ has one short answer; ‘What would you like to know about bats?’ invites children’s own questions. The first option reverses the order, and the others are both closed.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कौन-सा जोड़ा बंद प्रश्न के बाद खुला प्रश्न दर्शाता है?","optionsHi":["तुम चमगादड़ों के बारे में क्या जानना चाहोगे? / क्या चमगादड़ पक्षी है?","क्या चमगादड़ पक्षी है? / तुम चमगादड़ों के बारे में क्या जानना चाहोगे?","चमगादड़ कहाँ रहते हैं? / उड़ने वाले दो अन्य जंतुओं के नाम बताओ।","चमगादड़ के कितने पैर होते हैं? / क्या चमगादड़ के पंख होते हैं?"],"explanationHi":"‘क्या चमगादड़ पक्षी है?’ का एक संक्षिप्त उत्तर है; ‘तुम चमगादड़ों के बारे में क्या जानना चाहोगे?’ बच्चों के अपने प्रश्नों को आमंत्रित करता है। पहला विकल्प क्रम उलट देता है, और बाकी दोनों बंद हैं।"},
  {"id":"cdp-pedagogy-subjects-1374","question":"Which question best encourages divergent thinking in a Class 5 lesson on waste?","options":["What is the colour of the dustbin used for dry waste in our school?","Is plastic biodegradable, or does it stay in the soil for years?","Where is the garbage collected from our town finally dumped?","In how many different ways could we reuse a plastic bottle at home?"],"answer":3,"explanation":"Divergent questions have many acceptable answers and invite original ideas. The others have a single correct answer.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कचरे पर कक्षा 5 के पाठ में कौन-सा प्रश्न अपसारी चिंतन को सबसे अच्छी तरह प्रोत्साहित करता है?","optionsHi":["हमारे विद्यालय में सूखे कचरे के लिए प्रयुक्त कूड़ेदान का रंग क्या है?","क्या प्लास्टिक जैव-निम्नीकरणीय है, या वह वर्षों तक मिट्टी में रहता है?","हमारे कस्बे से एकत्र किया गया कचरा अंततः कहाँ डाला जाता है?","घर पर हम प्लास्टिक की बोतल का कितने अलग-अलग तरीकों से पुनः उपयोग कर सकते हैं?"],"explanationHi":"अपसारी प्रश्नों के अनेक स्वीकार्य उत्तर होते हैं और वे मौलिक विचारों को आमंत्रित करते हैं। अन्य प्रश्नों का एक ही सही उत्तर है।"},
  {"id":"cdp-pedagogy-subjects-1375","question":"A Class 5 child asks, ‘Why do fireflies glow?’ and the teacher does not know the answer. The best response is to:","options":["admit she does not know and plan with the children how to find out","tell the child that the question is not in the syllabus for this year","give a confident guess as if it were the correct scientific answer","ask the child not to ask such difficult questions in the middle of class"],"answer":0,"explanation":"Admitting not knowing and finding out together models inquiry and values the child’s curiosity. Guessing as fact or dismissing the question damages both.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 5 का एक बच्चा पूछता है, ‘जुगनू क्यों चमकते हैं?’ और शिक्षिका को उत्तर नहीं पता। सबसे अच्छी प्रतिक्रिया है:","optionsHi":["स्वीकार करना कि वह नहीं जानती और बच्चों के साथ योजना बनाना कि कैसे पता लगाएँ","बच्चे को बताना कि प्रश्न इस वर्ष के पाठ्यक्रम में नहीं है","आत्मविश्वास से अनुमान देना जैसे वही सही वैज्ञानिक उत्तर हो","बच्चे से कक्षा के बीच में ऐसे कठिन प्रश्न न पूछने को कहना"],"explanationHi":"न जानने को स्वीकार करना और साथ मिलकर पता लगाना जिज्ञासा-आधारित अन्वेषण का आदर्श प्रस्तुत करता है और बच्चे की जिज्ञासा को महत्त्व देता है। अनुमान को तथ्य बताना या प्रश्न को खारिज करना दोनों को हानि पहुँचाता है।"},
  {"id":"cdp-pedagogy-subjects-1376","question":"Which sequence best represents an inquiry cycle in an EVS lesson?","options":["Observe → record → predict → ask a question → explain to others","Explain → test → ask a question → predict → record","Question → predict → test → observe and record → explain","Plan → ask a question → predict → explain → observe"],"answer":2,"explanation":"Inquiry starts with a question, moves to a prediction and a test, then to recorded observation and finally explanation and sharing.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"EVS पाठ में जिज्ञासा-चक्र (inquiry cycle) का सबसे अच्छा प्रतिनिधित्व कौन-सा क्रम करता है?","optionsHi":["अवलोकन → अभिलेखन → पूर्वानुमान → प्रश्न पूछना → दूसरों को समझाना","समझाना → परखना → प्रश्न पूछना → पूर्वानुमान → अभिलेखन","प्रश्न → पूर्वानुमान → परीक्षण → अवलोकन और अभिलेखन → व्याख्या","योजना → प्रश्न पूछना → पूर्वानुमान → व्याख्या → अवलोकन"],"explanationHi":"जिज्ञासा-आधारित अन्वेषण प्रश्न से शुरू होता है, पूर्वानुमान और परीक्षण की ओर बढ़ता है, फिर दर्ज किए अवलोकन और अंत में व्याख्या तथा साझा करने की ओर।"},
  {"id":"cdp-pedagogy-subjects-1377","question":"Which of the following are process skills that EVS aims to develop? I. Observation II. Classification III. Measurement IV. Rote recall of definitions","options":["I and II only","I, II and III only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"Observing, classifying and measuring are process skills used in inquiry. Rote recall of definitions is not a process skill and is discouraged in EVS.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"निम्नलिखित में से कौन-से प्रक्रिया-कौशल हैं जिन्हें EVS विकसित करना चाहता है? I. अवलोकन II. वर्गीकरण III. मापन IV. परिभाषाओं का रटंत स्मरण","optionsHi":["केवल I और II","केवल I, II और III","केवल II, III और IV","I, II, III और IV"],"explanationHi":"अवलोकन, वर्गीकरण और मापन जिज्ञासा-आधारित अन्वेषण में प्रयुक्त प्रक्रिया-कौशल हैं। परिभाषाओं का रटंत स्मरण प्रक्रिया-कौशल नहीं है और EVS में हतोत्साहित है।"},
  {"id":"cdp-pedagogy-subjects-1378","question":"Which is the best-written learning objective for a Class 4 EVS lesson on houses?","options":["Children will know all about the different kinds of houses.","The teacher will cover pages 45 to 50 of the textbook in two periods.","Children will appreciate the many kinds of houses and the people who build them.","Children will explain, with two reasons, how local houses suit the weather."],"answer":3,"explanation":"A good objective states observable learning by children with a clear standard. ‘Know’ and ‘appreciate’ are vague, and covering pages is the teacher’s task, not a learning outcome.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"घरों पर कक्षा 4 के EVS पाठ के लिए सबसे अच्छा लिखा गया अधिगम-उद्देश्य कौन-सा है?","optionsHi":["बच्चे विभिन्न प्रकार के घरों के बारे में सब कुछ जानेंगे।","शिक्षक दो कालांशों में पाठ्यपुस्तक के पृष्ठ 45 से 50 पूरे करेगा।","बच्चे अनेक प्रकार के घरों और उन्हें बनाने वाले लोगों की सराहना करेंगे।","बच्चे दो कारणों के साथ समझाएँगे कि स्थानीय घर मौसम के अनुकूल कैसे हैं।"],"explanationHi":"अच्छा उद्देश्य बच्चों के अवलोकनीय अधिगम को स्पष्ट मानक के साथ बताता है। ‘जानना’ और ‘सराहना करना’ अस्पष्ट हैं, और पृष्ठ पूरे करना शिक्षक का कार्य है, अधिगम-प्रतिफल नहीं।"},
  {"id":"cdp-pedagogy-subjects-1379","question":"Which classroom best reflects a constructivist approach to EVS?","options":["The teacher starts from children’s ideas, which they test and revise","The teacher explains the chapter clearly and children underline important lines","Children copy notes from the board and learn them for a test","The teacher reads the chapter aloud and asks the questions at the end"],"answer":0,"explanation":"Constructivism has learners build knowledge by working on their own ideas through activity and discussion. The others are transmission models.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कौन-सी कक्षा EVS के प्रति रचनावादी उपागम को सबसे अच्छी तरह दर्शाती है?","optionsHi":["शिक्षक बच्चों के विचारों से शुरू करता है, जिन्हें वे परखते और संशोधित करते हैं","शिक्षक अध्याय को स्पष्टता से समझाता है और बच्चे महत्त्वपूर्ण पंक्तियों को रेखांकित करते हैं","बच्चे बोर्ड से नोट्स उतारते हैं और परीक्षा के लिए उन्हें याद करते हैं","शिक्षक अध्याय ज़ोर से पढ़ता है और अंत के प्रश्न पूछता है"],"explanationHi":"रचनावाद में अधिगमकर्ता गतिविधि और चर्चा के माध्यम से अपने ही विचारों पर कार्य करके ज्ञान का निर्माण करते हैं। अन्य प्रेषण मॉडल हैं।"},
  {"id":"cdp-pedagogy-subjects-1380","question":"Class 5 children judge which of two proposed sites is better for a new hand pump in their village, considering distance, drainage and who would use it, and defend their choice. In Bloom’s revised taxonomy, this task is mainly at the level of:","options":["Remembering","Understanding","Evaluating","Applying"],"answer":2,"explanation":"Making and defending a judgement using criteria is evaluating, near the top of the revised taxonomy. It goes beyond recall, explanation or applying a known procedure.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 5 के बच्चे अपने गाँव में नए हैंडपंप के लिए दो प्रस्तावित स्थलों में से कौन-सा बेहतर है, इसका निर्णय दूरी, जल-निकासी और कौन उसका उपयोग करेगा इस पर विचार करके करते हैं, और अपने चयन का बचाव करते हैं। ब्लूम के संशोधित वर्गीकरण में यह कार्य मुख्यतः किस स्तर का है:","optionsHi":["स्मरण","समझना","मूल्यांकन करना","अनुप्रयोग"],"explanationHi":"मानदंडों के आधार पर निर्णय लेना और उसका बचाव करना मूल्यांकन है, जो संशोधित वर्गीकरण के शीर्ष के निकट है। यह स्मरण, व्याख्या या किसी ज्ञात प्रक्रिया को लागू करने से आगे है।"},
  {"id":"cdp-pedagogy-subjects-1381","question":"Which homework task is most in the spirit of EVS for Class 3?","options":["Learn the answers to all the questions at the end of the chapter by heart for a test","Find out from family which animals visit your house at night, and how you know","Copy the whole chapter neatly in your notebook with the headings underlined","Write the names of ten animals five times each in neat handwriting"],"answer":1,"explanation":"The task sends children to observe and talk with family, making home a site of inquiry. The others are rote.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 के लिए EVS की भावना के सबसे अनुरूप गृहकार्य कौन-सा है?","optionsHi":["परीक्षा के लिए अध्याय के अंत के सभी प्रश्नों के उत्तर कंठस्थ करना","परिवार से पता लगाना कि रात में कौन-से जंतु तुम्हारे घर आते हैं, और तुम कैसे जानते हो","पूरा अध्याय कॉपी में शीर्षकों को रेखांकित करते हुए साफ़-साफ़ उतारना","दस जंतुओं के नाम साफ़ लिखावट में पाँच-पाँच बार लिखना"],"explanationHi":"यह कार्य बच्चों को अवलोकन करने और परिवार से बात करने भेजता है, घर को जिज्ञासा-आधारित अन्वेषण का स्थल बनाता है। अन्य रटंत हैं।"},
  {"id":"cdp-pedagogy-subjects-1382","question":"Class 3 children make leaf prints with paint. What makes this an EVS learning activity and not only an art activity?","options":["Children compare the shapes and vein patterns and discuss how leaves differ","Children use bright colours and mix new shades for each of the prints","The finished prints are displayed on the classroom wall for visitors","The teacher gives marks for neatness and for the best arrangement of prints"],"answer":0,"explanation":"The EVS learning lies in close observation and comparison, which the art activity makes possible. Colour, display and neatness do not make it EVS.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 3 के बच्चे रंग से पत्तियों की छाप बनाते हैं। इसे केवल कला-गतिविधि नहीं, EVS अधिगम-गतिविधि क्या बनाता है?","optionsHi":["बच्चे आकारों और शिराओं के प्रतिरूपों की तुलना करते हैं और चर्चा करते हैं कि पत्तियाँ कैसे भिन्न होती हैं","बच्चे चटक रंगों का उपयोग करते हैं और प्रत्येक छाप के लिए नए रंग मिलाते हैं","तैयार छापें आगंतुकों के लिए कक्षा की दीवार पर प्रदर्शित की जाती हैं","शिक्षिका सफ़ाई और छापों की सबसे अच्छी व्यवस्था के लिए अंक देती है"],"explanationHi":"EVS अधिगम निकट अवलोकन और तुलना में है, जिसे कला-गतिविधि संभव बनाती है। रंग, प्रदर्शन और सफ़ाई उसे EVS नहीं बनाते।"},
  {"id":"cdp-pedagogy-subjects-1383","question":"A Class 4 child gives a wrong answer about why the pond dries up in summer. The teacher responds, ‘Interesting! What made you think so?’ The main purpose of this response is to:","options":["embarrass the child gently in front of the class so she is more careful","delay giving the correct answer so that the lesson can move faster","show the class that wrong answers are acceptable as final answers","understand the child’s reasoning and keep it safe to share ideas"],"answer":3,"explanation":"Probing reveals the thinking behind an answer, which the teacher can then work with, and children learn that ideas are welcome. The wrong answer is not accepted as final.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 का एक बच्चा गर्मियों में तालाब के सूखने के कारण के बारे में गलत उत्तर देता है। शिक्षिका प्रतिक्रिया देती है, ‘रोचक! तुम्हें ऐसा क्यों लगा?’ इस प्रतिक्रिया का मुख्य उद्देश्य है:","optionsHi":["बच्चे को कक्षा के सामने धीरे से शर्मिंदा करना ताकि वह अधिक सावधान हो","सही उत्तर देने में देरी करना ताकि पाठ तेज़ी से आगे बढ़े","कक्षा को दिखाना कि गलत उत्तर अंतिम उत्तर के रूप में स्वीकार्य हैं","बच्चे का तर्क समझना और विचार साझा करना सुरक्षित बनाए रखना"],"explanationHi":"गहन पड़ताल उत्तर के पीछे की सोच प्रकट करती है, जिस पर शिक्षिका फिर कार्य कर सकती है, और बच्चे सीखते हैं कि उनके विचारों का स्वागत है। गलत उत्तर अंतिम के रूप में स्वीकार नहीं किया जाता।"},
  {"id":"cdp-pedagogy-subjects-1384","question":"A Class 5 teacher has 60 children and wants all of them to think about why the village pond is shrinking. The most effective strategy is to:","options":["ask the whole class and take answers from the first two hands that go up","use think–pair–share, so each child thinks alone and then with a partner","ask the children to write down the answer given in the textbook","call the children one by one to the front of the class to answer"],"answer":1,"explanation":"Think–pair–share gets every child thinking and talking even in a large class. Taking answers from a few lets most children opt out.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 5 की एक शिक्षिका के पास 60 बच्चे हैं और वह चाहती है कि सभी इस पर सोचें कि गाँव का तालाब क्यों सिकुड़ रहा है। सबसे प्रभावी रणनीति है:","optionsHi":["पूरी कक्षा से पूछना और जो पहले दो हाथ उठें उनसे उत्तर लेना","सोचो-जोड़ी बनाओ-साझा करो का उपयोग करना, ताकि प्रत्येक बच्चा पहले अकेले और फिर साथी के साथ सोचे","बच्चों से पाठ्यपुस्तक में दिया उत्तर लिखने को कहना","बच्चों को एक-एक करके कक्षा के आगे उत्तर देने के लिए बुलाना"],"explanationHi":"सोचो-जोड़ी बनाओ-साझा करो बड़ी कक्षा में भी हर बच्चे को सोचने और बात करने पर लगाता है। कुछ से ही उत्तर लेने से अधिकांश बच्चे बाहर हो जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1385","question":"In a one-room school, a single teacher handles Classes 3, 4 and 5 together. How does a thematic approach to EVS help her?","options":["She can teach the Class 5 lesson to all, since harder content stretches younger ones","She can take each class in turn for EVS while the other two do silent seatwork","All three classes explore one theme, like ‘Water’, with tasks at different levels","She can give one common worksheet on a theme to all three classes, for fairness"],"answer":2,"explanation":"A shared theme allows common discussion while tasks are graded for each class, which suits multi-grade teaching. Taking classes in turn is a common multi-grade routine but is not a thematic approach, and one worksheet for all ignores differences in level.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक कमरे वाले विद्यालय में एक शिक्षिका कक्षा 3, 4 और 5 को साथ संभालती है। EVS के प्रति विषयवस्तु-आधारित उपागम उसकी कैसे मदद करता है?","optionsHi":["वह सबको कक्षा 5 का पाठ पढ़ा सकती है, क्योंकि कठिन सामग्री छोटों को खींचती है","वह EVS के लिए बारी-बारी से प्रत्येक कक्षा ले सकती है जबकि अन्य दो चुपचाप सीट-कार्य करें","तीनों कक्षाएँ एक विषयवस्तु, जैसे ‘जल’, की खोज करती हैं, अलग-अलग स्तर के कार्यों के साथ","वह निष्पक्षता के लिए तीनों कक्षाओं को एक विषयवस्तु पर एक ही साझा कार्य-पत्र दे सकती है"],"explanationHi":"साझा विषयवस्तु साझा चर्चा की अनुमति देती है जबकि कार्य प्रत्येक कक्षा के लिए श्रेणीबद्ध होते हैं, जो बहु-श्रेणी शिक्षण के अनुकूल है। बारी-बारी से कक्षाएँ लेना एक आम बहु-श्रेणी दिनचर्या है पर विषयवस्तु-आधारित उपागम नहीं, और सबके लिए एक कार्य-पत्र स्तर के अंतर की उपेक्षा करता है।"},
  {"id":"cdp-pedagogy-subjects-1386","question":"A Class 4 chapter says that the rainy season begins in June. Children in a Chennai school say that in their city the heaviest rain comes in October and November. The teacher should:","options":["value their experience and explore why rain comes at different times in India","tell them that the textbook is correct and that they must be remembering it wrongly","ask them to write the textbook answer in the examination anyway","skip the topic, since it is confusing and may mislead the other children"],"answer":0,"explanation":"Tamil Nadu gets much of its rain from the north-east monsoon in October–December. Children’s observations are correct, and the difference is a rich starting point for inquiry.","difficulty":"very-hard","source":"CTET Paper 1 · TNTET","questionHi":"कक्षा 4 का एक अध्याय कहता है कि वर्षा ऋतु जून में शुरू होती है। चेन्नई के एक विद्यालय के बच्चे कहते हैं कि उनके शहर में सबसे अधिक वर्षा अक्टूबर और नवंबर में होती है। शिक्षिका को चाहिए कि:","optionsHi":["उनके अनुभव को महत्त्व दे और खोजे कि भारत में वर्षा अलग-अलग समय पर क्यों आती है","उन्हें बताए कि पाठ्यपुस्तक सही है और वे उसे गलत याद कर रहे होंगे","उनसे परीक्षा में फिर भी पाठ्यपुस्तक का उत्तर लिखने को कहे","विषय छोड़ दे, क्योंकि वह भ्रमित करने वाला है और अन्य बच्चों को गुमराह कर सकता है"],"explanationHi":"तमिलनाडु की अधिकांश वर्षा अक्टूबर–दिसंबर में उत्तर-पूर्वी मानसून से होती है। बच्चों के अवलोकन सही हैं, और यह अंतर जिज्ञासा-आधारित अन्वेषण का समृद्ध आरंभ-बिंदु है।"},
  {"id":"cdp-pedagogy-subjects-1387","question":"Assertion (A): An EVS teacher should welcome children’s questions even when they seem unrelated to the lesson of the day. Reason (R): Children’s questions reveal their curiosity and thinking and can be used to guide teaching. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Questions show what children wonder about and how they think, which is why they should be welcomed, noted and taken up when possible.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"अभिकथन (A): EVS शिक्षक को बच्चों के प्रश्नों का स्वागत करना चाहिए, भले ही वे उस दिन के पाठ से असंबंधित लगें। कारण (R): बच्चों के प्रश्न उनकी जिज्ञासा और चिंतन को प्रकट करते हैं और शिक्षण का मार्गदर्शन करने में उपयोग किए जा सकते हैं। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"प्रश्न दिखाते हैं कि बच्चे किस बारे में सोचते हैं और कैसे सोचते हैं, इसीलिए उनका स्वागत होना चाहिए, उन्हें नोट किया जाना चाहिए और संभव होने पर आगे बढ़ाया जाना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1388","question":"After a visit to the fish market, a teacher notes in her diary that the children asked many questions about how much the fish seller earns and how early he wakes up, but few about the fish. The best use of this note is to:","options":["scold the children for asking off-topic questions instead of studying the fish","repeat the visit with a strict worksheet that keeps attention on the fish","conclude that these children are simply not interested in learning EVS","plan the next lessons around livelihoods, building on the children’s interest"],"answer":3,"explanation":"Reflective teachers use children’s responses to plan; livelihood is itself an EVS concern. Calling the questions off-topic misses a genuine entry point.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"मछली-बाज़ार के भ्रमण के बाद एक शिक्षिका अपनी डायरी में नोट करती है कि बच्चों ने इस बारे में बहुत प्रश्न पूछे कि मछली-विक्रेता कितना कमाता है और कितनी जल्दी उठता है, पर मछलियों के बारे में कम। इस नोट का सबसे अच्छा उपयोग है:","optionsHi":["बच्चों को मछलियों का अध्ययन करने के बजाय विषय से बाहर प्रश्न पूछने के लिए डाँटना","कठोर कार्य-पत्र के साथ भ्रमण दोहराना जो ध्यान मछलियों पर रखे","यह निष्कर्ष निकालना कि इन बच्चों की EVS सीखने में रुचि ही नहीं है","बच्चों की रुचि पर आधारित करते हुए आगे के पाठ आजीविकाओं के इर्द-गिर्द योजनाबद्ध करना"],"explanationHi":"चिंतनशील शिक्षक बच्चों की प्रतिक्रियाओं का उपयोग योजना बनाने में करते हैं; आजीविका स्वयं EVS की चिंता है। प्रश्नों को विषय से बाहर कहना एक वास्तविक प्रवेश-बिंदु चूक जाना है।"},
  {"id":"cdp-pedagogy-subjects-1389","question":"The NCERT EVS books end chapters with varied tasks such as ‘Find out’, ‘Discuss’, ‘Draw’ and ‘Tell’, instead of only written questions. The main reason is to:","options":["make the books longer and more attractive for children to look at","engage children in many ways and take learning beyond the classroom","reduce the teacher’s role so that children can manage on their own","prepare children early for the written board examinations of later years"],"answer":1,"explanation":"Varied tasks use talk, drawing, inquiry and writing, and many send children to family and surroundings. That breadth is the design intention.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"NCERT की EVS पुस्तकें अध्यायों का अंत केवल लिखित प्रश्नों के बजाय ‘पता लगाओ’, ‘चर्चा करो’, ‘चित्र बनाओ’ और ‘बताओ’ जैसे विविध कार्यों से करती हैं। मुख्य कारण है:","optionsHi":["पुस्तकों को बच्चों के देखने के लिए अधिक लंबी और आकर्षक बनाना","बच्चों को अनेक तरीकों से संलग्न करना और अधिगम को कक्षा से आगे ले जाना","शिक्षक की भूमिका घटाना ताकि बच्चे स्वयं सँभाल सकें","बच्चों को बाद के वर्षों की लिखित बोर्ड परीक्षाओं के लिए जल्दी तैयार करना"],"explanationHi":"विविध कार्य बातचीत, चित्रकला, जिज्ञासा-आधारित अन्वेषण और लेखन का उपयोग करते हैं, और कई बच्चों को परिवार और परिवेश की ओर भेजते हैं। वह व्यापकता डिज़ाइन का उद्देश्य है।"},
  {"id":"cdp-pedagogy-subjects-1390","question":"A parent complains that EVS homework asks her child to ‘find out from elders’ instead of giving the answers in the book. The teacher’s best explanation is that:","options":["the book has no answers in it because it was printed in a great hurry this year","the teacher has no time in class to give answers to every question","such tasks value family knowledge and help children learn to find things out","the task is only meant to keep children busy at home in the evening"],"answer":2,"explanation":"These tasks are deliberate: they value home knowledge and build the skill of inquiry. They are not a gap in the book or busy work.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक अभिभावक शिकायत करती है कि EVS का गृहकार्य उसके बच्चे से पुस्तक में दिए उत्तरों के बजाय ‘बुज़ुर्गों से पता लगाओ’ कहता है। शिक्षक की सबसे अच्छी व्याख्या है कि:","optionsHi":["पुस्तक में उत्तर नहीं हैं क्योंकि इस वर्ष वह बहुत जल्दबाज़ी में छपी","शिक्षक के पास कक्षा में हर प्रश्न का उत्तर देने का समय नहीं है","ऐसे कार्य परिवार के ज्ञान को महत्त्व देते हैं और बच्चों को चीज़ें खोजना सीखने में मदद करते हैं","कार्य केवल बच्चों को शाम को घर पर व्यस्त रखने के लिए है"],"explanationHi":"ये कार्य जानबूझकर हैं: वे घर के ज्ञान को महत्त्व देते हैं और जिज्ञासा-आधारित अन्वेषण का कौशल बनाते हैं। वे पुस्तक की कमी या समय काटने का कार्य नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-1391","question":"Three groups of Class 3 children sort the same set of animal pictures. One groups them by number of legs, another by what they eat and the third by where they live. The teacher should:","options":["accept all three and ask each group to explain the basis it chose","accept only the grouping by habitat, since that is the one in the textbook","ask all the groups to redo the task by number of legs, so results match","mark the task wrong because the three groupings do not match each other"],"answer":0,"explanation":"Classification depends on the chosen criterion; what matters is applying it consistently and explaining it. Insisting on one basis narrows thinking.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 3 के बच्चों के तीन समूह जंतुओं के चित्रों के एक ही समुच्चय को छाँटते हैं। एक पैरों की संख्या से, दूसरा इस आधार पर कि वे क्या खाते हैं, और तीसरा इस आधार पर कि वे कहाँ रहते हैं। शिक्षक को चाहिए कि:","optionsHi":["तीनों को स्वीकार करे और प्रत्येक समूह से उसके चुने आधार की व्याख्या करने को कहे","केवल आवास के आधार वाला समूहन स्वीकार करे, क्योंकि वही पाठ्यपुस्तक में है","सभी समूहों से कार्य को पैरों की संख्या के आधार पर दोबारा करने को कहे, ताकि परिणाम मेल खाएँ","कार्य को गलत अंकित करे क्योंकि तीनों समूहन एक-दूसरे से मेल नहीं खाते"],"explanationHi":"वर्गीकरण चुने गए मानदंड पर निर्भर करता है; मायने यह रखता है कि उसे सुसंगत रूप से लागू किया जाए और समझाया जाए। एक ही आधार पर ज़ोर देना चिंतन को संकीर्ण करता है।"},
  {"id":"cdp-pedagogy-subjects-1392","question":"Class 5 children will do an activity with a lit candle under a glass. Which is the best approach for the teacher?","options":["Do the activity herself while children watch from a safe distance","Drop the activity altogether because it involves an open flame","Let children do it without instructions, so they discover the risks themselves","Explain safety rules, supervise closely and let small groups do it"],"answer":3,"explanation":"Safety and hands-on work go together: clear rules and supervision let children do the activity themselves. Dropping it or doing it only as a demonstration denies them experience.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के बच्चे काँच के नीचे जलती मोमबत्ती वाली गतिविधि करेंगे। शिक्षिका के लिए सबसे अच्छा उपागम कौन-सा है?","optionsHi":["गतिविधि स्वयं करना जबकि बच्चे सुरक्षित दूरी से देखें","गतिविधि को पूरी तरह छोड़ देना क्योंकि इसमें खुली लौ है","बच्चों को बिना निर्देश के करने देना, ताकि वे जोखिम स्वयं खोजें","सुरक्षा-नियम समझाना, निकट से पर्यवेक्षण करना और छोटे समूहों को करने देना"],"explanationHi":"सुरक्षा और हाथ से किया जाने वाला कार्य साथ चलते हैं: स्पष्ट नियम और पर्यवेक्षण बच्चों को गतिविधि स्वयं करने देते हैं। उसे छोड़ना या केवल प्रदर्शन के रूप में करना उन्हें अनुभव से वंचित करता है।"},
  {"id":"cdp-pedagogy-subjects-1393","question":"A Class 5 survey project on water sources in the village can give the teacher evidence of which indicators? I. Observation and recording II. Discussion III. Analysis IV. Cooperation","options":["I and II only","I, II and III only","I, II, III and IV","II and IV only"],"answer":2,"explanation":"Surveys involve recording data, talking with people and classmates, interpreting patterns and working in groups, so all four indicators can be observed.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"गाँव के जल-स्रोतों पर कक्षा 5 की सर्वेक्षण परियोजना शिक्षिका को किन सूचकों का साक्ष्य दे सकती है? I. अवलोकन और अभिलेखन II. चर्चा III. विश्लेषण IV. सहयोग","optionsHi":["केवल I और II","केवल I, II और III","I, II, III और IV","केवल II और IV"],"explanationHi":"सर्वेक्षण में आँकड़े दर्ज करना, लोगों और सहपाठियों से बात करना, प्रतिरूपों की व्याख्या करना और समूहों में कार्य करना शामिल है, इसलिए चारों सूचकों को देखा जा सकता है।"},
  {"id":"cdp-pedagogy-subjects-1394","question":"Which statement by a teacher best reflects her role as a facilitator in EVS?","options":["‘Listen carefully; I will tell you the correct answer in a minute.’","‘Let us find out together. How could we check your idea?’","‘Copy this diagram carefully; it will come in the test.’","‘Do not ask questions until I have finished the chapter.’"],"answer":1,"explanation":"A facilitator helps children test their own ideas instead of handing out answers. The others place the teacher as the sole source of knowledge.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"किसी शिक्षिका का कौन-सा कथन EVS में सुगमकर्ता के रूप में उसकी भूमिका को सबसे अच्छी तरह दर्शाता है?","optionsHi":["‘ध्यान से सुनो; मैं एक मिनट में सही उत्तर बताऊँगी।’","‘आओ साथ मिलकर पता लगाएँ। हम तुम्हारे विचार को कैसे जाँच सकते हैं?’","‘इस आरेख को ध्यान से नकल करो; यह परीक्षा में आएगा।’","‘जब तक मैं अध्याय समाप्त न कर लूँ, प्रश्न मत पूछो।’"],"explanationHi":"सुगमकर्ता उत्तर बाँटने के बजाय बच्चों को अपने विचार परखने में मदद करता है। अन्य शिक्षक को ज्ञान का एकमात्र स्रोत रखते हैं।"},
  {"id":"cdp-pedagogy-subjects-1395","question":"A Class 4 child cannot define ‘adaptation’ but explains clearly why a duck has webbed feet and a hen does not. From the NCF 2005 point of view, the teacher should conclude that the child:","options":["has understood the idea, which matters more than stating a definition","has not really learnt the topic, since she cannot give the definition","should memorise the definition word for word before moving on","needs remedial teaching in EVS until she can define the key terms"],"answer":0,"explanation":"EVS at this stage avoids definitions and looks for understanding; explaining a real case shows it. Demanding the definition misreads the aim.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 की एक बच्ची ‘अनुकूलन’ की परिभाषा नहीं दे सकती पर स्पष्ट समझाती है कि बत्तख के पैरों में झिल्ली क्यों होती है और मुर्गी के नहीं। NCF 2005 के दृष्टिकोण से शिक्षिका को निष्कर्ष निकालना चाहिए कि बच्ची:","optionsHi":["ने विचार समझ लिया है, जो परिभाषा बताने से अधिक मायने रखता है","ने विषय वास्तव में नहीं सीखा, क्योंकि वह परिभाषा नहीं दे सकती","को आगे बढ़ने से पहले परिभाषा शब्दशः याद करनी चाहिए","को तब तक EVS में उपचारात्मक शिक्षण चाहिए जब तक वह मुख्य शब्दों की परिभाषा न दे सके"],"explanationHi":"इस अवस्था में EVS परिभाषाओं से बचता है और समझ की खोज करता है; किसी वास्तविक मामले को समझाना उसे दिखाता है। परिभाषा माँगना उद्देश्य को गलत पढ़ना है।"},
  {"id":"cdp-pedagogy-subjects-1396","question":"A Class 4 teacher puts up a ‘Wonder Wall’ where children stick slips with questions such as ‘Why do cats’ eyes shine at night?’ The main purpose is to:","options":["keep children quiet during lessons by giving them somewhere to write","decorate the classroom with colourful slips for visitors","find out which children can write neatly and spell correctly","value children’s questions and use them to plan inquiries"],"answer":3,"explanation":"Displaying children’s questions values curiosity and gives the teacher material for future inquiry. Decoration and neatness are not the point.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 4 की एक शिक्षिका 'आश्चर्य-दीवार' (Wonder Wall) लगाती है जिस पर बच्चे ‘बिल्लियों की आँखें रात में क्यों चमकती हैं?’ जैसे प्रश्नों वाली पर्चियाँ चिपकाते हैं। मुख्य उद्देश्य है:","optionsHi":["बच्चों को लिखने के लिए जगह देकर पाठों के दौरान शांत रखना","आगंतुकों के लिए कक्षा को रंगीन पर्चियों से सजाना","यह पता लगाना कि कौन-से बच्चे साफ़ लिख और सही वर्तनी बना सकते हैं","बच्चों के प्रश्नों को महत्त्व देना और उनसे जिज्ञासा-आधारित अन्वेषण की योजना बनाना"],"explanationHi":"बच्चों के प्रश्न प्रदर्शित करना जिज्ञासा को महत्त्व देता है और शिक्षिका को भविष्य के अन्वेषण की सामग्री देता है। सजावट और सफ़ाई मुद्दा नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-1397","question":"Half of a Class 6 section scores below 30% in an English unit test. Before planning any remedial classes, the teacher’s first step should be to:","options":["Repeat the whole unit at the same pace so that everyone revises it","Use a diagnostic test to find what is causing the low scores","Give the low scorers extra homework from the same exercises as before","Inform parents that their children need private tuition in English"],"answer":1,"explanation":"Remedial teaching depends on diagnosis: low scores can come from weak decoding, vocabulary, grammar or test-taking, and each needs a different response. Repeating the same teaching ignores the cause.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 6 के एक अनुभाग के आधे विद्यार्थी अंग्रेज़ी की इकाई-परीक्षा में 30% से कम अंक पाते हैं। किसी भी उपचारात्मक कक्षा की योजना बनाने से पहले शिक्षिका का पहला कदम होना चाहिए:","optionsHi":["पूरी इकाई उसी गति से दोहराना ताकि सब पुनरावृत्ति करें","कम अंकों का कारण जानने के लिए निदानात्मक परीक्षण का उपयोग करना","कम अंक पाने वालों को पहले जैसे ही अभ्यासों से अतिरिक्त गृहकार्य देना","अभिभावकों को सूचित करना कि उनके बच्चों को अंग्रेज़ी में निजी ट्यूशन चाहिए"],"explanationHi":"उपचारात्मक शिक्षण निदान पर निर्भर करता है: कम अंक कमज़ोर विकोडन, शब्दावली, व्याकरण या परीक्षा देने के कौशल से आ सकते हैं, और प्रत्येक को अलग प्रतिक्रिया चाहिए। वही शिक्षण दोहराना कारण की उपेक्षा करता है।"},
  {"id":"cdp-pedagogy-subjects-1398","question":"A Class 3 child understands stories read aloud and speaks with a rich vocabulary, but reads very slowly, confuses ‘b’ and ‘d’, and cannot sound out simple new words despite regular teaching. Which support is most appropriate?","options":["Structured, multisensory phonics, such as tracing letters while saying sounds","Moving her down to a lower class where the reading demands are lighter for now","Making her copy each confused letter fifty times to fix it in memory","Asking her to read aloud before the class daily so that she practises more"],"answer":0,"explanation":"Good oral language with persistent decoding difficulty suggests dyslexia. Explicit, systematic, multisensory phonics, with extra time and audio support, helps; public reading and punitive copying do harm.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कक्षा 3 की एक बच्ची ज़ोर से पढ़ी गई कहानियाँ समझती है और समृद्ध शब्दावली के साथ बोलती है, पर नियमित शिक्षण के बावजूद बहुत धीरे पढ़ती है, ‘b’ और ‘d’ को भ्रमित करती है, और सरल नए शब्दों की ध्वनियाँ जोड़कर पढ़ नहीं पाती। कौन-सा सहारा सबसे उपयुक्त है?","optionsHi":["संरचित, बहु-संवेदी स्वनिम-शिक्षण (phonics), जैसे ध्वनियाँ बोलते हुए अक्षरों को अंगुली से बनाना","उसे निचली कक्षा में भेजना जहाँ पठन की माँगें अभी हल्की हैं","भ्रमित अक्षर को स्मृति में बैठाने के लिए उससे प्रत्येक को पचास बार नकल करवाना","उससे रोज़ कक्षा के सामने ज़ोर से पढ़वाना ताकि वह अधिक अभ्यास करे"],"explanationHi":"अच्छी मौखिक भाषा के साथ विकोडन की स्थायी कठिनाई डिस्लेक्सिया का संकेत देती है। स्पष्ट, व्यवस्थित, बहु-संवेदी स्वनिम-शिक्षण, अतिरिक्त समय और ऑडियो सहारे के साथ, मदद करता है; सबके सामने पढ़ाना और दंडात्मक नकल हानिकर हैं।"},
  {"id":"cdp-pedagogy-subjects-1399","question":"Which of these practices goes against the principles of remedial teaching?","options":["Starting from what the learner can already do and building step by step","Using varied materials and activities suited to the learner’s difficulty","Giving frequent feedback and recording small gains to build confidence","Re-teaching the same content in the same way and at the same pace"],"answer":3,"explanation":"If the original teaching did not work for the child, repeating it unchanged is unlikely to work now. Remedial teaching changes the approach, pace and materials to match the diagnosed need.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"इनमें से कौन-सी प्रथा उपचारात्मक शिक्षण के सिद्धांतों के विरुद्ध है?","optionsHi":["अधिगमकर्ता जो पहले से कर सकता है वहाँ से शुरू करना और चरण-दर-चरण आगे बढ़ना","अधिगमकर्ता की कठिनाई के अनुरूप विविध सामग्री और गतिविधियों का उपयोग करना","बार-बार प्रतिपुष्टि देना और आत्मविश्वास बनाने के लिए छोटे लाभ दर्ज करना","उसी सामग्री को उसी तरीके से और उसी गति से दोबारा पढ़ाना"],"explanationHi":"यदि मूल शिक्षण बच्चे के लिए कारगर नहीं रहा, तो उसे बिना बदले दोहराना अब कारगर होने की संभावना कम है। उपचारात्मक शिक्षण निदान की गई आवश्यकता के अनुरूप उपागम, गति और सामग्री बदलता है।"},
  {"id":"cdp-pedagogy-subjects-1400","question":"A Class 7 teacher collects one composition from each student and sorts the errors: 40% tense, 30% articles, 15% prepositions and 15% others. The main use of this error analysis is to:","options":["Rank students from best to worst for the progress report","Prove to parents that the students have not been studying","Target teaching at the most frequent error patterns","Decide which students should be failed in the term examination"],"answer":2,"explanation":"Error analysis turns scattered mistakes into patterns, so remedial work can target what most learners need. It is a diagnostic tool, not a ranking device.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 7 की एक शिक्षिका प्रत्येक विद्यार्थी की एक रचना एकत्र करती है और त्रुटियाँ छाँटती है: 40% काल, 30% उपपद (articles), 15% पूर्वसर्ग और 15% अन्य। इस त्रुटि-विश्लेषण का मुख्य उपयोग है:","optionsHi":["प्रगति-रिपोर्ट के लिए विद्यार्थियों को सर्वश्रेष्ठ से निकृष्टतम तक क्रमित करना","अभिभावकों को सिद्ध करना कि विद्यार्थी पढ़ाई नहीं कर रहे","सबसे बार-बार आने वाले त्रुटि-प्रतिरूपों पर शिक्षण को लक्षित करना","यह तय करना कि सत्र-परीक्षा में किन विद्यार्थियों को अनुत्तीर्ण किया जाए"],"explanationHi":"त्रुटि-विश्लेषण बिखरी गलतियों को प्रतिरूपों में बदलता है, ताकि उपचारात्मक कार्य उस पर लक्षित हो जो अधिकांश अधिगमकर्ताओं को चाहिए। यह निदानात्मक साधन है, क्रमांकन का नहीं।"},
  {"id":"cdp-pedagogy-subjects-1401","question":"A teacher pairs a Class 5 child who reads fluently with a classmate who struggles, for 15 minutes of paired reading daily. Which statement about this peer tutoring is most accurate?","options":["It helps only the weaker reader; the fluent one gains nothing","It should be avoided, because only trained teachers can help weak readers","It usually benefits both, since tutoring deepens the tutor’s own skills","It works only when both children are of exactly the same reading level"],"answer":2,"explanation":"Peer tutoring gives the struggling reader extra supported practice, and the tutor consolidates skills by modelling and explaining; it also builds a cooperative classroom.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"एक शिक्षिका कक्षा 5 के एक धाराप्रवाह पढ़ने वाले बच्चे को संघर्ष कर रहे सहपाठी के साथ प्रतिदिन 15 मिनट के युग्म-पठन के लिए जोड़ी बनाती है। इस सहपाठी शिक्षण के बारे में कौन-सा कथन सबसे सटीक है?","optionsHi":["यह केवल कमज़ोर पाठक की मदद करता है; धाराप्रवाह पढ़ने वाले को कुछ नहीं मिलता","इससे बचना चाहिए, क्योंकि केवल प्रशिक्षित शिक्षक ही कमज़ोर पाठकों की मदद कर सकते हैं","यह प्रायः दोनों को लाभ पहुँचाता है, क्योंकि पढ़ाना शिक्षक-बच्चे के अपने कौशल गहरे करता है","यह तभी कारगर है जब दोनों बच्चे ठीक एक ही पठन-स्तर के हों"],"explanationHi":"सहपाठी शिक्षण संघर्ष कर रहे पाठक को अतिरिक्त सहायता-प्राप्त अभ्यास देता है, और शिक्षक-बच्चा आदर्श प्रस्तुत करके और समझाकर कौशल समेकित करता है; यह सहकारी कक्षा भी बनाता है।"},
  {"id":"cdp-pedagogy-subjects-1402","question":"A Class 6 student reads at about the Class 2 level. For his remedial reading sessions, the most suitable texts are those that:","options":["Are the Class 2 picture books his younger cousins use, since the level matches","Match his age and interests but use simple language (high-interest, low-level)","Are taken from the Class 6 textbook so that he keeps up with his class","Have long lists of words to be read aloud without any story at all"],"answer":1,"explanation":"Texts meant for small children can embarrass an older learner and lose his interest; material with mature content but accessible language keeps him motivated while matching his reading level.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 6 का एक विद्यार्थी लगभग कक्षा 2 के स्तर पर पढ़ता है। उसके उपचारात्मक पठन-सत्रों के लिए सबसे उपयुक्त पाठ वे हैं जो:","optionsHi":["उसके छोटे चचेरे भाई-बहनों की कक्षा 2 की चित्र-पुस्तकें हैं, क्योंकि स्तर मेल खाता है","उसकी आयु और रुचियों से मेल खाते हैं पर सरल भाषा का उपयोग करते हैं (उच्च-रुचि, निम्न-स्तर)","कक्षा 6 की पाठ्यपुस्तक से लिए गए हैं ताकि वह अपनी कक्षा के साथ चल सके","जिनमें बिना किसी कहानी के ज़ोर से पढ़े जाने वाले शब्दों की लंबी सूचियाँ हों"],"explanationHi":"छोटे बच्चों के लिए बने पाठ बड़े अधिगमकर्ता को शर्मिंदा कर सकते हैं और उसकी रुचि खो सकते हैं; परिपक्व विषय-वस्तु पर सुगम भाषा वाली सामग्री उसे प्रेरित रखती है और उसके पठन-स्तर से मेल खाती है।"},
  {"id":"cdp-pedagogy-subjects-1403","question":"In a government school, for one hour a day children from Classes 3 to 5 are grouped by their actual reading level (letter, word, paragraph, story) instead of by class, and taught with level-appropriate activities; groups change as children progress. This approach is known as:","options":["Streaming children permanently into fixed ability sections","Grammar-translation for multi-grade classes with mixed abilities","Detention of weak children in their present class for another year","Teaching at the Right Level, grouping by level, not grade"],"answer":3,"explanation":"Teaching at the Right Level, developed by Pratham, groups children temporarily by assessed level so that teaching meets them where they are; flexible regrouping avoids permanent labelling.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"एक सरकारी विद्यालय में प्रतिदिन एक घंटे कक्षा 3 से 5 के बच्चों को कक्षा के बजाय उनके वास्तविक पठन-स्तर (अक्षर, शब्द, अनुच्छेद, कहानी) के आधार पर समूहित किया जाता है और स्तर-उपयुक्त गतिविधियों से पढ़ाया जाता है; बच्चों की प्रगति के साथ समूह बदलते रहते हैं। इस उपागम को कहते हैं:","optionsHi":["बच्चों को स्थायी रूप से निश्चित योग्यता-अनुभागों में बाँटना","मिश्रित योग्यता वाली बहु-श्रेणी कक्षाओं के लिए व्याकरण-अनुवाद","कमज़ोर बच्चों को एक और वर्ष के लिए उनकी वर्तमान कक्षा में रोकना","सही स्तर पर शिक्षण (Teaching at the Right Level), कक्षा नहीं, स्तर के आधार पर समूहन"],"explanationHi":"प्रथम (Pratham) द्वारा विकसित सही स्तर पर शिक्षण बच्चों को आकलित स्तर के अनुसार अस्थायी रूप से समूहित करता है ताकि शिक्षण उन्हें वहीं मिले जहाँ वे हैं; लचीला पुनर्समूहन स्थायी लेबल लगाने से बचाता है।"},
  {"id":"cdp-pedagogy-subjects-1404","question":"Consider these statements: I. A diagnostic test aims to locate specific learning difficulties rather than to rank learners. II. An achievement test measures how far learners have mastered what was taught. III. A diagnostic test is usually given only once, at the end of the year. Which are correct?","options":["I and II only","I and III only","II and III only","I, II and III"],"answer":0,"explanation":"Diagnostic tests are used whenever difficulties need to be identified, typically before remedial teaching, not only at year’s end, so III is false.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"इन कथनों पर विचार कीजिए: I. निदानात्मक परीक्षण का उद्देश्य अधिगमकर्ताओं को क्रमित करना नहीं, विशिष्ट अधिगम-कठिनाइयों का पता लगाना है। II. उपलब्धि परीक्षण मापता है कि अधिगमकर्ताओं ने जो पढ़ाया गया उसमें कितनी निपुणता पाई। III. निदानात्मक परीक्षण सामान्यतः केवल एक बार, वर्ष के अंत में दिया जाता है। कौन-से सही हैं?","optionsHi":["केवल I और II","केवल I और III","केवल II और III","I, II और III"],"explanationHi":"निदानात्मक परीक्षण जब भी कठिनाइयों की पहचान आवश्यक हो, सामान्यतः उपचारात्मक शिक्षण से पहले, दिए जाते हैं, केवल वर्ष-अंत में नहीं, इसलिए III असत्य है।"},
  {"id":"cdp-pedagogy-subjects-1405","question":"A Class 4 child writes ‘hopping’ when she means ‘hoping’ and ‘runing’ for ‘running’. The most effective remedial step is to:","options":["Have her write each misspelt word twenty times in her notebook","Ignore the errors, since spelling will correct itself over time","Tell her to avoid words ending in ‘-ing’ in her writing for now","Use word sorts such as hop/hopping and hope/hoping"],"answer":3,"explanation":"The errors show confusion about one rule (short vowel and doubling versus silent ‘e’ dropping). Sorting words like hop/hopping and hope/hoping helps her discover the pattern behind both errors.","difficulty":"very-hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 4 की एक बच्ची ‘hoping’ के अर्थ में ‘hopping’ और ‘running’ के लिए ‘runing’ लिखती है। सबसे प्रभावी उपचारात्मक कदम है:","optionsHi":["उससे प्रत्येक गलत लिखे शब्द को अपनी कॉपी में बीस बार लिखवाना","त्रुटियों की उपेक्षा करना, क्योंकि वर्तनी समय के साथ अपने आप सुधर जाएगी","उसे अभी अपने लेखन में ‘-ing’ पर समाप्त होने वाले शब्दों से बचने को कहना","hop/hopping और hope/hoping जैसे शब्द-छँटाई (word sorts) का उपयोग करना"],"explanationHi":"त्रुटियाँ एक ही नियम के बारे में भ्रम दिखाती हैं (ह्रस्व स्वर और द्वित्व बनाम मूक ‘e’ का लोप)। hop/hopping और hope/hoping जैसे शब्दों को छाँटना उसे दोनों त्रुटियों के पीछे का प्रतिरूप खोजने में मदद करता है।"},
  {"id":"cdp-pedagogy-subjects-1406","question":"At the end of each English lesson, Class 7 students answer two short questions on a slip. The teacher reads the slips that evening and changes the next day’s plan to re-teach what most students found confusing. This is an example of:","options":["Assessment for learning, used to guide teaching","Assessment of learning, used to certify achievement","Norm-referenced testing, used to compare learners","Summative assessment, used for the report card"],"answer":0,"explanation":"Information that is used to adjust ongoing teaching is formative assessment, or assessment for learning; it is not about grading or comparing.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"प्रत्येक अंग्रेज़ी पाठ के अंत में कक्षा 7 के विद्यार्थी एक पर्ची पर दो छोटे प्रश्नों के उत्तर देते हैं। शिक्षिका शाम को पर्चियाँ पढ़ती है और अगले दिन की योजना बदलकर वह दोबारा पढ़ाती है जो अधिकांश विद्यार्थियों को भ्रमित करने वाला लगा। यह किसका उदाहरण है:","optionsHi":["अधिगम के लिए आकलन, जो शिक्षण का मार्गदर्शन करने में उपयोग होता है","अधिगम का आकलन, जो उपलब्धि को प्रमाणित करने में उपयोग होता है","मानक-संदर्भित परीक्षण, जो अधिगमकर्ताओं की तुलना में उपयोग होता है","योगात्मक आकलन, जो रिपोर्ट कार्ड के लिए उपयोग होता है"],"explanationHi":"जो जानकारी चल रहे शिक्षण को समायोजित करने में उपयोग हो वह रचनात्मक आकलन, या अधिगम के लिए आकलन है; यह ग्रेड देने या तुलना करने के बारे में नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1407","question":"Class 8 students use a checklist (‘Does my story have a clear beginning? Have I used paragraphs?’) to review their own drafts, note what they need to improve and set a goal for the next piece. This practice is best described as:","options":["Assessment of learning","Norm-referenced assessment","Assessment as learning","Summative assessment"],"answer":2,"explanation":"Assessment as learning puts students in charge of monitoring and regulating their own learning, building metacognition; assessment for learning is mainly the teacher using information to adjust teaching.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 8 के विद्यार्थी जाँच-सूची (‘क्या मेरी कहानी में स्पष्ट आरंभ है? क्या मैंने अनुच्छेदों का उपयोग किया है?’) का उपयोग करके अपने मसौदों की समीक्षा करते हैं, नोट करते हैं कि उन्हें क्या सुधारना है और अगले लेखन के लिए लक्ष्य बनाते हैं। इस प्रथा का सबसे अच्छा वर्णन है:","optionsHi":["अधिगम का आकलन","मानक-संदर्भित आकलन","अधिगम के रूप में आकलन (assessment as learning)","योगात्मक आकलन"],"explanationHi":"अधिगम के रूप में आकलन विद्यार्थियों को अपने अधिगम की निगरानी और नियमन का दायित्व देता है, जो अधिसंज्ञान बनाता है; अधिगम के लिए आकलन मुख्यतः शिक्षक द्वारा शिक्षण को समायोजित करने के लिए जानकारी का उपयोग है।"},
  {"id":"cdp-pedagogy-subjects-1408","question":"A reading test on a passage about the Taj Mahal includes the question ‘In which city is the Taj Mahal?’, which most students can answer without reading the passage. This mainly lowers the test’s:","options":["Reliability, because scores would differ on another day","Validity, because it does not measure reading","Objectivity, because different markers may disagree","Practicality, because the test takes too long to mark"],"answer":1,"explanation":"If general knowledge alone answers an item, the item does not measure what it claims, namely understanding of the passage; that is a validity problem.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"ताजमहल पर एक गद्यांश की पठन-परीक्षा में प्रश्न शामिल है ‘ताजमहल किस शहर में है?’, जिसका उत्तर अधिकांश विद्यार्थी गद्यांश पढ़े बिना दे सकते हैं। यह मुख्यतः परीक्षण की किसे घटाता है:","optionsHi":["विश्वसनीयता, क्योंकि दूसरे दिन अंक भिन्न होंगे","वैधता, क्योंकि वह पठन को नहीं मापता","वस्तुनिष्ठता, क्योंकि अलग-अलग जाँचकर्ता असहमत हो सकते हैं","व्यावहारिकता, क्योंकि परीक्षण को जाँचने में बहुत समय लगता है"],"explanationHi":"यदि केवल सामान्य ज्ञान से प्रश्न का उत्तर मिल जाए, तो प्रश्न वह नहीं मापता जिसका वह दावा करता है, यानी गद्यांश की समझ; यह वैधता की समस्या है।"},
  {"id":"cdp-pedagogy-subjects-1409","question":"A teacher notices that she gives higher marks to essays she checks in the morning than to similar essays she checks late at night. The problem and its best remedy are:","options":["Low validity; she should set a different and easier essay topic next time","Low reliability; she should mark with a clear rubric and recheck samples","Low practicality; she should give fewer writing tasks to the class","Low objectivity of students; they should write more neatly"],"answer":1,"explanation":"Inconsistent scoring of the same quality of work by the same rater is an intra-rater reliability problem; explicit criteria and rechecking make marking more consistent.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"एक शिक्षिका देखती है कि वह सुबह जाँचे गए निबंधों को रात में देर से जाँचे गए वैसे ही निबंधों से अधिक अंक देती है। समस्या और उसका सबसे अच्छा उपचार हैं:","optionsHi":["कम वैधता; उसे अगली बार भिन्न और आसान निबंध-विषय देना चाहिए","कम विश्वसनीयता; उसे स्पष्ट रूब्रिक से अंकित करना चाहिए और नमूनों की पुनः जाँच करनी चाहिए","कम व्यावहारिकता; उसे कक्षा को कम लेखन-कार्य देने चाहिए","विद्यार्थियों की कम वस्तुनिष्ठता; उन्हें अधिक साफ़ लिखना चाहिए"],"explanationHi":"एक ही मूल्यांकनकर्ता द्वारा एक ही गुणवत्ता के कार्य का असंगत अंकन अंतः-निर्णायक विश्वसनीयता की समस्या है; स्पष्ट मानदंड और पुनः जाँच अंकन को अधिक सुसंगत बनाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1410","question":"A state board English examination contains only grammar multiple-choice questions. Teachers then stop doing speaking and writing activities and spend class time on MCQ practice. This effect of a test on teaching is called:","options":["Positive washback","Halo effect","Negative washback","Test reliability"],"answer":2,"explanation":"Washback is the influence of a test on teaching and learning; when a narrow test pushes teachers to neglect important skills, the washback is negative.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"राज्य बोर्ड की अंग्रेज़ी परीक्षा में केवल व्याकरण के बहुविकल्पीय प्रश्न हैं। फिर शिक्षक बोलने और लिखने की गतिविधियाँ बंद कर देते हैं और कक्षा का समय MCQ अभ्यास पर लगाते हैं। शिक्षण पर परीक्षा के इस प्रभाव को कहते हैं:","optionsHi":["सकारात्मक प्रतिप्रभाव (washback)","प्रभामंडल प्रभाव (halo effect)","नकारात्मक प्रतिप्रभाव (washback)","परीक्षण-विश्वसनीयता"],"explanationHi":"प्रतिप्रभाव शिक्षण और अधिगम पर परीक्षा का प्रभाव है; जब कोई संकीर्ण परीक्षा शिक्षकों को महत्त्वपूर्ण कौशलों की उपेक्षा करने की ओर धकेलती है, तो प्रतिप्रभाव नकारात्मक होता है।"},
  {"id":"cdp-pedagogy-subjects-1411","question":"Which of the following is an integrative rather than a discrete-point language test?","options":["A dictation of a short connected passage","Marking the stressed syllable in a list of single words","Choosing the right preposition in ten unrelated sentences","Choosing the correct article in a list of nouns"],"answer":0,"explanation":"Integrative tests such as dictation and cloze draw on several skills and areas of knowledge at once; discrete-point tests check one item at a time, such as a single preposition.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"निम्नलिखित में से कौन-सा विशिष्ट-बिंदु (discrete-point) के बजाय समेकित (integrative) भाषा-परीक्षण है?","optionsHi":["एक छोटे संबद्ध गद्यांश का श्रुतलेख","एकल शब्दों की सूची में बलाघात वाले अक्षर पर निशान लगाना","दस असंबद्ध वाक्यों में सही पूर्वसर्ग चुनना","संज्ञाओं की सूची में सही उपपद (article) चुनना"],"explanationHi":"श्रुतलेख और क्लोज़ जैसे समेकित परीक्षण एक साथ कई कौशलों और ज्ञान-क्षेत्रों का उपयोग करते हैं; विशिष्ट-बिंदु परीक्षण एक बार में एक मद की जाँच करते हैं, जैसे एक पूर्वसर्ग।"},
  {"id":"cdp-pedagogy-subjects-1412","question":"A teacher checks whether each Class 3 child ‘can read a short story and tell what happened in it’, recording each child as ‘achieved’ or ‘not yet’, without comparing children with one another. This assessment is:","options":["Norm-referenced, since each child is judged against the class","Diagnostic only, since it uses the label ‘not yet’ for some children","Summative only, since it records whether the child achieved it","Criterion-referenced, as each child is judged against an outcome"],"answer":3,"explanation":"Criterion-referenced assessment judges performance against a defined standard or outcome; norm-referenced assessment ranks learners against each other.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"एक शिक्षिका जाँचती है कि क्या कक्षा 3 का प्रत्येक बच्चा ‘कोई छोटी कहानी पढ़ सकता है और बता सकता है कि उसमें क्या हुआ’, प्रत्येक बच्चे को ‘प्राप्त’ या ‘अभी नहीं’ दर्ज करते हुए, बच्चों की एक-दूसरे से तुलना किए बिना। यह आकलन है:","optionsHi":["मानक-संदर्भित, क्योंकि प्रत्येक बच्चे को कक्षा के विरुद्ध आँका जाता है","केवल निदानात्मक, क्योंकि वह कुछ बच्चों के लिए ‘अभी नहीं’ का लेबल उपयोग करता है","केवल योगात्मक, क्योंकि वह दर्ज करता है कि बच्चे ने उसे प्राप्त किया या नहीं","कसौटी-संदर्भित, क्योंकि प्रत्येक बच्चे को एक प्रतिफल के विरुद्ध आँका जाता है"],"explanationHi":"कसौटी-संदर्भित आकलन प्रदर्शन को परिभाषित मानक या प्रतिफल के विरुद्ध आँकता है; मानक-संदर्भित आकलन अधिगमकर्ताओं को एक-दूसरे के विरुद्ध क्रमित करता है।"},
  {"id":"cdp-pedagogy-subjects-1413","question":"A Class 2 teacher gives children a sheet of ‘I can…’ statements (‘I can tell a story from pictures’) with three faces to colour: happy, so-so, not yet. The main purpose is to:","options":["Replace the teacher’s own assessment of the children completely","Rank the children for the term report card","Help children reflect on their own learning in a simple way","Test children’s ability to colour within the lines"],"answer":2,"explanation":"Simple self-assessment helps even young learners become aware of what they can do and what to work on next, building ownership of learning.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"कक्षा 2 की एक शिक्षिका बच्चों को ‘मैं… कर सकता/सकती हूँ’ वाक्यों की पत्रक देती है (‘मैं चित्रों से कहानी सुना सकता/सकती हूँ’) जिसके साथ रंगने के लिए तीन चेहरे हैं: खुश, ठीक-ठाक, अभी नहीं। मुख्य उद्देश्य है:","optionsHi":["बच्चों के शिक्षिका के अपने आकलन को पूरी तरह बदल देना","सत्र के रिपोर्ट कार्ड के लिए बच्चों को क्रमित करना","बच्चों को सरल ढंग से अपने अधिगम पर चिंतन करने में मदद करना","बच्चों की रेखाओं के भीतर रंगने की क्षमता की जाँच करना"],"explanationHi":"सरल स्व-आकलन छोटे अधिगमकर्ताओं को भी यह जागरूक करने में मदद करता है कि वे क्या कर सकते हैं और आगे किस पर कार्य करना है, जिससे अधिगम पर स्वामित्व बनता है।"},
  {"id":"cdp-pedagogy-subjects-1414","question":"Which written comment on a Class 5 story is most likely to help the child improve?","options":["‘Good work. 7/10. Try to make your next story as good as this one.’","‘Great opening! In the middle, add how Meena felt when the dog ran off.’","‘Very nice work! Your handwriting is neat and the story is nice and long.’","‘Too many mistakes. Rewrite the whole story neatly in your notebook.’"],"answer":1,"explanation":"Descriptive feedback names what works and gives a specific, doable next step; grades and general praise or criticism tell the child little about how to improve.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 5 की कहानी पर कौन-सी लिखित टिप्पणी बच्चे को सुधारने में सबसे अधिक मदद करने की संभावना रखती है?","optionsHi":["‘अच्छा कार्य। 7/10। अपनी अगली कहानी को इसी जितनी अच्छी बनाने की कोशिश करो।’","‘शानदार शुरुआत! बीच में यह जोड़ो कि जब कुत्ता भाग गया तो मीना को कैसा लगा।’","‘बहुत अच्छा कार्य! तुम्हारी लिखावट साफ़ है और कहानी अच्छी और लंबी है।’","‘बहुत गलतियाँ हैं। पूरी कहानी अपनी कॉपी में साफ़-साफ़ दोबारा लिखो।’"],"explanationHi":"वर्णनात्मक प्रतिपुष्टि बताती है कि क्या अच्छा है और विशिष्ट, करने योग्य अगला कदम देती है; ग्रेड और सामान्य प्रशंसा या आलोचना बच्चे को सुधार के बारे में बहुत कम बताती है।"},
  {"id":"cdp-pedagogy-subjects-1415","question":"A teacher keeps brief dated notes such as ‘12 Aug: Ravi used “enormous” on his own while describing the elephant in free talk.’ This assessment tool is:","options":["An anecdotal record","A rating scale","A cumulative record","An achievement test"],"answer":0,"explanation":"Anecdotal records are brief factual notes of significant observed behaviour, useful for tracking language development in natural settings. A cumulative record is a long-term school file of overall progress.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"एक शिक्षिका ‘12 Aug: रवि ने मुक्त बातचीत में हाथी का वर्णन करते हुए स्वयं ही “enormous” शब्द का प्रयोग किया।’ जैसे संक्षिप्त दिनांकित नोट रखती है। यह आकलन-साधन है:","optionsHi":["घटनात्मक अभिलेख (anecdotal record)","निर्धारण मापनी (rating scale)","संचयी अभिलेख","उपलब्धि परीक्षण"],"explanationHi":"घटनात्मक अभिलेख देखे गए महत्त्वपूर्ण व्यवहार के संक्षिप्त तथ्यात्मक नोट होते हैं, जो स्वाभाविक परिस्थितियों में भाषा-विकास का पता रखने में उपयोगी हैं। संचयी अभिलेख समग्र प्रगति की दीर्घकालिक विद्यालयी फ़ाइल है।"},
  {"id":"cdp-pedagogy-subjects-1416","question":"As a Class 1 child reads a short book aloud, the teacher ticks each correct word on a copy and codes errors (substitutions, omissions, self-corrections) to see which cues the child is using. This tool, associated with Marie Clay, is a:","options":["Cumulative record","Cloze test","Checklist","Running record"],"answer":3,"explanation":"A running record captures a child’s oral reading in real time and is analysed for accuracy, self-correction and the cues used (meaning, structure, visual).","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"जब कक्षा 1 का एक बच्चा छोटी किताब ज़ोर से पढ़ता है, शिक्षिका प्रतिलिपि पर प्रत्येक सही शब्द पर निशान लगाती है और यह देखने के लिए त्रुटियों (प्रतिस्थापन, लोप, स्व-सुधार) को कोड करती है कि बच्चा किन संकेतों का उपयोग कर रहा है। मैरी क्ले से जुड़ा यह साधन है:","optionsHi":["संचयी अभिलेख","क्लोज़ परीक्षण","जाँच-सूची","चालू अभिलेख (running record)"],"explanationHi":"चालू अभिलेख बच्चे के मौखिक पठन को वास्तविक समय में दर्ज करता है और उसका शुद्धता, स्व-सुधार और प्रयुक्त संकेतों (अर्थ, संरचना, दृश्य) के लिए विश्लेषण किया जाता है।"},
  {"id":"cdp-pedagogy-subjects-1417","question":"An item in a Class 6 test reads: ‘A person who writes poems is called an ______. (a) poet (b) author (c) singer (d) painter’. What is the main flaw in this item?","options":["The ‘an’ in the stem cues ‘author’ and misleads students","It has more than one correct answer, so it is unreliable","It is too easy, since everyone knows what a poet does","It should have been an open-ended question instead"],"answer":0,"explanation":"The intended answer is ‘poet’, but ‘an’ fits only ‘author’, so the stem misleads and test-wise students may choose by grammar alone; stems should not give grammatical cues.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 6 की परीक्षा के एक प्रश्न में लिखा है: ‘A person who writes poems is called an ______. (a) poet (b) author (c) singer (d) painter’. इस प्रश्न की मुख्य कमी क्या है?","optionsHi":["प्रश्न-मूल में ‘an’ ‘author’ का संकेत देता है और विद्यार्थियों को भ्रमित करता है","इसके एक से अधिक सही उत्तर हैं, इसलिए यह अविश्वसनीय है","यह बहुत आसान है, क्योंकि सब जानते हैं कि कवि क्या करता है","इसके बजाय इसे खुला प्रश्न होना चाहिए था"],"explanationHi":"अभिप्रेत उत्तर ‘poet’ है, पर ‘an’ केवल ‘author’ के साथ ठीक बैठता है, इसलिए प्रश्न-मूल भ्रमित करता है और परीक्षा-चतुर विद्यार्थी केवल व्याकरण से चुन सकते हैं; प्रश्न-मूल को व्याकरणिक संकेत नहीं देने चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1418","question":"A school places all children who need extra help in English in a section publicly called the ‘weak group’, which stays fixed for the year. The main problem with this arrangement is that:","options":["Remedial help should never be given in groups, only one to one by a specialist","Children in the group will learn too fast and soon get bored","Fixed public labels lower children’s self-esteem and expectations","It makes planning harder for the teacher of that section"],"answer":2,"explanation":"Labelling can become a self-fulfilling prophecy. Remedial grouping should be need-based, temporary and discreet, with children moving on as they progress.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"एक विद्यालय अंग्रेज़ी में अतिरिक्त सहायता चाहने वाले सभी बच्चों को सार्वजनिक रूप से ‘कमज़ोर समूह’ कहे जाने वाले अनुभाग में रखता है, जो वर्ष भर स्थिर रहता है। इस व्यवस्था की मुख्य समस्या यह है कि:","optionsHi":["उपचारात्मक सहायता कभी समूहों में नहीं दी जानी चाहिए, केवल विशेषज्ञ द्वारा एक-से-एक","समूह के बच्चे बहुत तेज़ सीखेंगे और जल्दी ऊब जाएँगे","स्थिर सार्वजनिक लेबल बच्चों के आत्म-सम्मान और अपेक्षाओं को घटाते हैं","यह उस अनुभाग की शिक्षिका के लिए योजना बनाना कठिन बनाती है"],"explanationHi":"लेबल लगाना स्वतः पूरी होने वाली भविष्यवाणी बन सकता है। उपचारात्मक समूहन आवश्यकता-आधारित, अस्थायी और विवेकपूर्ण होना चाहिए, बच्चे प्रगति के साथ आगे बढ़ें।"},
  {"id":"cdp-pedagogy-subjects-1419","question":"Consider these statements about continuous assessment in language: I. Assessment should be built into everyday teaching and learning. II. Only pen-and-paper tests give reliable information about language ability. III. Observation, conversations, projects and portfolios are valid ways of assessing language. Which are correct?","options":["I and II only","I and III only","II and III only","I, II and III"],"answer":1,"explanation":"Continuous, comprehensive assessment uses many tools in many contexts; restricting assessment to written tests misses listening, speaking and real use of language.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"भाषा में सतत आकलन के बारे में इन कथनों पर विचार कीजिए: I. आकलन को दैनिक शिक्षण और अधिगम में समाहित होना चाहिए। II. केवल कलम-कागज़ परीक्षाएँ ही भाषा-क्षमता की विश्वसनीय जानकारी देती हैं। III. अवलोकन, बातचीत, परियोजनाएँ और पोर्टफोलियो भाषा के आकलन के वैध तरीके हैं। कौन-से सही हैं?","optionsHi":["केवल I और II","केवल I और III","केवल II और III","I, II और III"],"explanationHi":"सतत, व्यापक आकलन कई संदर्भों में कई साधनों का उपयोग करता है; आकलन को केवल लिखित परीक्षाओं तक सीमित करना श्रवण, बोलना और भाषा के वास्तविक प्रयोग को चूक जाता है।"},
  {"id":"cdp-pedagogy-subjects-1420","question":"A Class 7 class averages 85% in a test where students choose the correct verb form in separate sentences, but their free compositions are full of the same verb errors. Which conclusion is best supported?","options":["The test was too difficult, so the scores do not mean much","The students must have copied in the test and should be retested under watch","Free composition is an unfair way to test grammar knowledge","Knowing forms in isolated items does not ensure correct use in writing"],"answer":3,"explanation":"Discrete-point success shows explicit knowledge, but using forms while composing draws on automatic control; assessment must include integrated tasks to show real ability.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 7 की एक कक्षा उस परीक्षा में औसतन 85% अंक पाती है जिसमें विद्यार्थी अलग-अलग वाक्यों में सही क्रिया-रूप चुनते हैं, पर उनकी मुक्त रचनाएँ उन्हीं क्रिया-त्रुटियों से भरी हैं। कौन-सा निष्कर्ष सबसे अच्छी तरह समर्थित है?","optionsHi":["परीक्षा बहुत कठिन थी, इसलिए अंकों का बहुत अर्थ नहीं है","विद्यार्थियों ने परीक्षा में नकल की होगी और निगरानी में उनकी दोबारा परीक्षा होनी चाहिए","व्याकरण-ज्ञान की जाँच के लिए मुक्त रचना एक अनुचित तरीका है","अलग-थलग मदों में रूपों को जानना लेखन में सही प्रयोग सुनिश्चित नहीं करता"],"explanationHi":"विशिष्ट-बिंदु परीक्षा में सफलता स्पष्ट ज्ञान दिखाती है, पर रचना करते समय रूपों का प्रयोग स्वचालित नियंत्रण पर निर्भर करता है; वास्तविक क्षमता दिखाने के लिए आकलन में समेकित कार्य शामिल होने चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1421","question":"A Class 5 child who stammers volunteers to answer in English but gets stuck on the first word. The most helpful teacher response is to:","options":["Finish the word for him quickly so that he is not embarrassed","Avoid asking him questions in the future so that he is not stressed in class","Ask him to stop and try again only after he has calmed down","Wait calmly, keep eye contact and let him finish without time pressure"],"answer":3,"explanation":"Patient listening without completing words or rushing reduces pressure and shows that what he says matters; avoiding him denies him practice and participation.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 5 का एक हकलाने वाला बच्चा अंग्रेज़ी में उत्तर देने के लिए स्वेच्छा से हाथ उठाता है पर पहले ही शब्द पर अटक जाता है। शिक्षक की सबसे सहायक प्रतिक्रिया है:","optionsHi":["शब्द जल्दी से स्वयं पूरा कर देना ताकि वह शर्मिंदा न हो","भविष्य में उससे प्रश्न न पूछना ताकि कक्षा में उसे तनाव न हो","उसे रुकने और शांत होने के बाद ही दोबारा प्रयास करने को कहना","शांति से प्रतीक्षा करना, नज़र मिलाए रखना और बिना समय के दबाव के उसे पूरा करने देना"],"explanationHi":"शब्द पूरे किए बिना या जल्दबाज़ी किए बिना धैर्यपूर्वक सुनना दबाव घटाता है और दिखाता है कि वह जो कहता है वह मायने रखता है; उससे बचना उसे अभ्यास और भागीदारी से वंचित करता है।"},
  {"id":"cdp-pedagogy-subjects-1422","question":"Students have just explored how a balloon fixed on a bottle inflates in hot water and shrinks in cold water. At the start of the Explain phase of the 5E model, the teacher should first:","options":["Have students explain what they saw, then build scientific terms on that","Dictate the textbook explanation of the expansion of gases for students to note","Give a short test to see which students understood the activity","Show a new, unrelated demonstration to keep interest high in the class"],"answer":0,"explanation":"In the Explain phase, students' own explanations come first and the teacher then connects them to formal concepts and vocabulary. Dictation ignores what students made of the exploration.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"विद्यार्थी अभी खोजकर चुके हैं कि बोतल पर लगा गुब्बारा गर्म पानी में फूलता है और ठंडे पानी में सिकुड़ता है। 5E मॉडल के समझाना (Explain) चरण के आरंभ में शिक्षक को पहले क्या करना चाहिए?","optionsHi":["विद्यार्थियों से समझवाना कि उन्होंने क्या देखा, फिर उस पर वैज्ञानिक शब्द बनाना","विद्यार्थियों के नोट करने के लिए गैसों के प्रसार की पाठ्यपुस्तक-व्याख्या बोलकर लिखवाना","छोटी परीक्षा देना ताकि पता चले कि किन विद्यार्थियों ने गतिविधि समझी","कक्षा में रुचि ऊँची रखने के लिए कोई नया, असंबंधित प्रदर्शन दिखाना"],"explanationHi":"समझाना चरण में विद्यार्थियों की अपनी व्याख्याएँ पहले आती हैं और शिक्षक फिर उन्हें औपचारिक संकल्पनाओं और शब्दावली से जोड़ता है। श्रुतलेख इसकी उपेक्षा करता है कि विद्यार्थियों ने खोज से क्या समझा।"},
  {"id":"cdp-pedagogy-subjects-1423","question":"Which task best fits the Evaluate phase of a 5E unit on heat insulation?","options":["Watching a video on how thermos flasks are designed and made in a factory","Reading the textbook section on conductors and insulators aloud","Designing a way to stop ice melting on the way home and justifying it","Listing all the definitions learnt in the unit and learning them by heart"],"answer":2,"explanation":"Evaluate asks students to show understanding by using it in a new situation and justifying their choices. Watching, reading and listing are not evidence of understanding.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"ऊष्मा-रोधन पर 5E इकाई के मूल्यांकन (Evaluate) चरण में कौन-सा कार्य सबसे अच्छा बैठता है?","optionsHi":["कारखाने में थर्मस फ़्लास्क कैसे डिज़ाइन और बनाए जाते हैं, इस पर वीडियो देखना","पाठ्यपुस्तक का चालकों और विद्युतरोधी पदार्थों वाला खंड ज़ोर से पढ़ना","घर जाते समय बर्फ़ को पिघलने से रोकने का तरीका डिज़ाइन करना और उसका औचित्य सिद्ध करना","इकाई में सीखी सभी परिभाषाओं की सूची बनाना और उन्हें कंठस्थ करना"],"explanationHi":"मूल्यांकन में विद्यार्थियों से नई परिस्थिति में समझ का उपयोग करके और अपने चयनों का औचित्य देकर दिखाने को कहा जाता है। देखना, पढ़ना और सूची बनाना समझ के साक्ष्य नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-1424","question":"A teacher asks, 'What will happen to a balloon on the mouth of a bottle if the bottle is put in hot water? Why?' Students write their answers, the teacher does it, and students then try to reconcile what they saw with what they wrote. This strategy is called:","options":["KWL (Know-Want-Learned) chart","Concept cartoon discussion","Jigsaw group work","Predict-Observe-Explain"],"answer":3,"explanation":"Predict-Observe-Explain asks students to predict with reasons, observe, and explain any difference between prediction and observation.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"एक शिक्षक पूछता है, 'यदि बोतल को गर्म पानी में रखा जाए तो उसके मुँह पर लगे गुब्बारे का क्या होगा? क्यों?' विद्यार्थी अपने उत्तर लिखते हैं, शिक्षक प्रयोग करता है, और विद्यार्थी फिर जो देखा और जो लिखा था उसका मेल बिठाने की कोशिश करते हैं। इस रणनीति को कहते हैं:","optionsHi":["KWL (जानते हैं-जानना चाहते हैं-सीखा) चार्ट","संकल्पना-कार्टून चर्चा","जिगसॉ समूह-कार्य","पूर्वानुमान-अवलोकन-व्याख्या (Predict-Observe-Explain)"],"explanationHi":"पूर्वानुमान-अवलोकन-व्याख्या में विद्यार्थी कारण सहित पूर्वानुमान करते हैं, अवलोकन करते हैं, और पूर्वानुमान तथा अवलोकन के किसी अंतर को समझाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1425","question":"Before a unit on soil, a teacher makes a three-column chart with students: what we Know, what we Want to know, and what we Learned. The 'Want to know' column is most useful because it:","options":["Records the answers that students must memorise for the unit test","Gathers students' own questions to guide the unit's investigations","Shows the teacher which students already know the most about soil","Replaces the need for activities, since the questions are answered there"],"answer":1,"explanation":"In a KWL chart, students' questions in the 'W' column give direction and ownership to the inquiry, and are revisited in the 'L' column.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"मिट्टी पर इकाई से पहले एक शिक्षक विद्यार्थियों के साथ तीन स्तंभों का चार्ट बनाता है: हम क्या जानते हैं (Know), क्या जानना चाहते हैं (Want to know), और क्या सीखा (Learned)। 'जानना चाहते हैं' स्तंभ सबसे उपयोगी इसलिए है कि वह:","optionsHi":["वे उत्तर दर्ज करता है जिन्हें विद्यार्थियों को इकाई-परीक्षा के लिए याद करना है","इकाई की जाँचों का मार्गदर्शन करने के लिए विद्यार्थियों के अपने प्रश्न इकट्ठा करता है","शिक्षक को दिखाता है कि कौन-से विद्यार्थी मिट्टी के बारे में सबसे अधिक जानते हैं","गतिविधियों की आवश्यकता को समाप्त करता है, क्योंकि प्रश्नों के उत्तर वहीं मिल जाते हैं"],"explanationHi":"KWL चार्ट में 'W' स्तंभ में विद्यार्थियों के प्रश्न जिज्ञासा-आधारित अन्वेषण को दिशा और स्वामित्व देते हैं, और 'L' स्तंभ में उन पर फिर लौटा जाता है।"},
  {"id":"cdp-pedagogy-subjects-1426","question":"In a lesson on pollution, each member of a group studies one type (air, water, soil or noise) with members of other groups who have the same type, and then returns to teach it to the home group. This cooperative learning structure is:","options":["Think-pair-share","Jigsaw","Brainstorming","Role play"],"answer":1,"explanation":"In Jigsaw, each member becomes an 'expert' on one part with others, then teaches it to the home group, making everyone depend on each other's learning.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"प्रदूषण के पाठ में एक समूह का प्रत्येक सदस्य एक प्रकार (वायु, जल, मिट्टी या ध्वनि) का अध्ययन उसी प्रकार वाले अन्य समूहों के सदस्यों के साथ करता है, और फिर लौटकर उसे अपने गृह-समूह को पढ़ाता है। यह सहकारी अधिगम संरचना है:","optionsHi":["सोचो-जोड़ी बनाओ-साझा करो","जिगसॉ","विचार-मंथन","भूमिका-निर्वाह"],"explanationHi":"जिगसॉ में प्रत्येक सदस्य दूसरों के साथ एक भाग का 'विशेषज्ञ' बनता है, फिर उसे अपने गृह-समूह को पढ़ाता है, जिससे सब एक-दूसरे के अधिगम पर निर्भर होते हैं।"},
  {"id":"cdp-pedagogy-subjects-1427","question":"A Class 8 lesson teaches students to read their household electricity meter, calculate monthly consumption, and learn simple wiring safety, so that they gain skills useful for work. Which NCF 2005 criterion does this lesson serve most clearly?","options":["Historical validity","Process validity","Environmental validity","Ethical validity"],"answer":2,"explanation":"Environmental validity includes equipping learners with knowledge and skills to enter the world of work and placing science in their real surroundings. Reading meters is not mainly about methods of generating knowledge.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा 8 का एक पाठ विद्यार्थियों को घर का बिजली-मीटर पढ़ना, मासिक खपत की गणना करना और सरल वायरिंग-सुरक्षा सिखाता है, ताकि वे कार्य-क्षेत्र के लिए उपयोगी कौशल पाएँ। यह पाठ NCF 2005 के किस मानदंड की सबसे स्पष्ट पूर्ति करता है?","optionsHi":["ऐतिहासिक वैधता","प्रक्रिया-वैधता","पर्यावरणीय वैधता","नैतिक वैधता"],"explanationHi":"पर्यावरणीय वैधता में अधिगमकर्ताओं को कार्य-जगत में प्रवेश के ज्ञान और कौशल से लैस करना और विज्ञान को उनके वास्तविक परिवेश में रखना शामिल है। मीटर पढ़ना मुख्यतः ज्ञान-निर्माण की विधियों के बारे में नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1428","question":"A Class 8 chapter adds a box listing famous inventors and the years of their inventions, to be memorised for the test. Does this achieve historical validity as NCF 2005 means it?","options":["Yes, because any historical information gives historical validity","Yes, because memorising dates develops a strong sense of history","No, because the inventors listed in the box are not Indian","No, because it is about how ideas developed, not names and dates"],"answer":3,"explanation":"Historical validity aims to let learners see science as an evolving social enterprise, how ideas arose, were challenged and changed. A list of names and dates adds rote load without that understanding.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा 8 का एक अध्याय एक बॉक्स जोड़ता है जिसमें प्रसिद्ध आविष्कारकों और उनके आविष्कारों के वर्ष सूचीबद्ध हैं, जिन्हें परीक्षा के लिए याद करना है। क्या यह NCF 2005 के अर्थ में ऐतिहासिक वैधता प्राप्त करता है?","optionsHi":["हाँ, क्योंकि कोई भी ऐतिहासिक जानकारी ऐतिहासिक वैधता देती है","हाँ, क्योंकि तिथियाँ याद करना इतिहास का सशक्त बोध विकसित करता है","नहीं, क्योंकि बॉक्स में सूचीबद्ध आविष्कारक भारतीय नहीं हैं","नहीं, क्योंकि यह इस बारे में है कि विचार कैसे विकसित हुए, नाम और तिथियों के बारे में नहीं"],"explanationHi":"ऐतिहासिक वैधता का उद्देश्य अधिगमकर्ताओं को विज्ञान को विकसित होते सामाजिक उद्यम के रूप में देखने देना है, विचार कैसे उत्पन्न हुए, कैसे चुनौती पाए और बदले। नामों और तिथियों की सूची उस समझ के बिना रटंत का भार जोड़ती है।"},
  {"id":"cdp-pedagogy-subjects-1429","question":"A textbook section reads, 'A bar magnet has two poles, north and south.' Which revision would most improve its process validity?","options":["Adding a large coloured picture of a bar magnet with both its poles labelled","Having students hang a magnet freely and test each end with another magnet","Adding a clear definition of a magnetic pole in a highlighted box","Adding a box on the history of magnets and compasses in ancient China"],"answer":1,"explanation":"Process validity requires that students use the methods of science, observing and testing, to arrive at knowledge. Pictures and definitions merely restate the claim.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"पाठ्यपुस्तक के एक खंड में लिखा है, 'छड़ चुंबक के दो ध्रुव होते हैं, उत्तर और दक्षिण।' कौन-सा संशोधन उसकी प्रक्रिया-वैधता को सबसे अधिक सुधारेगा?","optionsHi":["दोनों ध्रुवों पर नाम लिखे छड़ चुंबक का बड़ा रंगीन चित्र जोड़ना","विद्यार्थियों से चुंबक को स्वतंत्र रूप से लटकाने और दूसरे चुंबक से प्रत्येक सिरे की जाँच करने को कहना","चुंबकीय ध्रुव की स्पष्ट परिभाषा एक उभरे बॉक्स में जोड़ना","प्राचीन चीन में चुंबकों और दिशासूचक का इतिहास बताने वाला बॉक्स जोड़ना"],"explanationHi":"प्रक्रिया-वैधता के लिए आवश्यक है कि विद्यार्थी विज्ञान की विधियों, अवलोकन और परीक्षण, का उपयोग करके ज्ञान तक पहुँचें। चित्र और परिभाषाएँ केवल कथन को दोहराती हैं।"},
  {"id":"cdp-pedagogy-subjects-1430","question":"A group of Class 7 students proposes to find out whether a pesticide harms frogs by spraying it on frogs caught from a pond. What should the teacher do?","options":["Allow it, since it is a real investigation that answers a genuine local question","Allow it, but only with a small number of frogs to limit the harm","Redirect them to a non-harmful study, like observing pond frogs over time","Cancel all investigations involving animals for the rest of the year"],"answer":2,"explanation":"Ethical validity requires concern for life. The teacher can keep the inquiry while protecting the animals, for example by non-harmful observation or using available data.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा 7 के विद्यार्थियों का एक समूह यह जानने का प्रस्ताव रखता है कि क्या कोई कीटनाशक मेंढकों को हानि पहुँचाता है, तालाब से पकड़े गए मेंढकों पर उसका छिड़काव करके। शिक्षक को क्या करना चाहिए?","optionsHi":["अनुमति देना, क्योंकि यह एक वास्तविक जाँच है जो एक वास्तविक स्थानीय प्रश्न का उत्तर देती है","अनुमति देना, पर हानि सीमित करने के लिए केवल कुछ मेंढकों के साथ","उन्हें हानि-रहित अध्ययन की ओर मोड़ना, जैसे समय के साथ तालाब के मेंढकों का अवलोकन","शेष वर्ष के लिए जंतुओं वाली सभी जाँचें रद्द कर देना"],"explanationHi":"नैतिक वैधता के लिए जीवन के प्रति चिंता आवश्यक है। शिक्षक जंतुओं की रक्षा करते हुए जाँच को बनाए रख सकता है, उदाहरण के लिए हानि-रहित अवलोकन या उपलब्ध आँकड़ों से।"},
  {"id":"cdp-pedagogy-subjects-1431","question":"During an activity, a few drops of dilute acid fall on a student's hand. What should the teacher do first?","options":["Wash the area at once with plenty of running water","Apply an ointment directly over the acid","Ask the student to wipe it off with a dry cloth and continue","Send the student to the principal's office"],"answer":0,"explanation":"Immediate washing with plenty of water dilutes and removes the acid; applying ointments over acid or delaying treatment can worsen the injury.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"किसी गतिविधि के दौरान तनु अम्ल की कुछ बूँदें एक विद्यार्थी के हाथ पर गिर जाती हैं। शिक्षक को सबसे पहले क्या करना चाहिए?","optionsHi":["उस स्थान को तुरंत बहुत सारे बहते पानी से धोना","अम्ल के ऊपर सीधे मरहम लगाना","विद्यार्थी से उसे सूखे कपड़े से पोंछने और जारी रखने को कहना","विद्यार्थी को प्रधानाचार्य के कार्यालय भेजना"],"explanationHi":"बहुत सारे पानी से तुरंत धोना अम्ल को तनु करता और हटाता है; अम्ल के ऊपर मरहम लगाना या उपचार में देरी चोट को बिगाड़ सकती है।"},
  {"id":"cdp-pedagogy-subjects-1432","question":"During a demonstration of an electric circuit, the bulb fails to glow. The most educational response from the teacher is to:","options":["Abandon the demonstration and explain the circuit from the textbook","Tell students that the bulb would normally glow and move on","Ask students what might be wrong and check each idea together","Replace the whole set-up quietly without saying anything about it"],"answer":2,"explanation":"Treating the failure as a problem to investigate models scientific troubleshooting: forming hypotheses (loose wire, dead cell, fused bulb) and testing them one by one.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"विद्युत परिपथ के प्रदर्शन के दौरान बल्ब नहीं जलता। शिक्षक की सबसे शैक्षिक प्रतिक्रिया है:","optionsHi":["प्रदर्शन छोड़ देना और पाठ्यपुस्तक से परिपथ समझाना","विद्यार्थियों को बताना कि बल्ब सामान्यतः जलता है और आगे बढ़ जाना","विद्यार्थियों से पूछना कि क्या गलत हो सकता है और हर विचार को साथ मिलकर जाँचना","इसके बारे में कुछ कहे बिना चुपचाप पूरा सेट-अप बदल देना"],"explanationHi":"विफलता को जाँच की समस्या के रूप में लेना वैज्ञानिक समस्या-निवारण का आदर्श प्रस्तुत करता है: परिकल्पनाएँ बनाना (ढीला तार, खराब सेल, फ़्यूज़ बल्ब) और उन्हें एक-एक करके परखना।"},
  {"id":"cdp-pedagogy-subjects-1433","question":"In a school in a hill town, students find that water boils at about 97 °C, not at 100 °C as their textbook says. The best response from the teacher is to:","options":["Tell them to write 100 °C, since that is the correct textbook answer","Tell them that their thermometer must be broken and should be replaced","Ignore the difference, since 3 °C is too small to matter in an experiment","Discuss reasons, like lower air pressure at height, and how to check them"],"answer":3,"explanation":"Unexpected results are opportunities to reason from evidence. Boiling point falls with altitude, and checking the thermometer is also sensible; forcing the textbook value teaches dishonesty.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"एक पहाड़ी कस्बे के विद्यालय में विद्यार्थी पाते हैं कि पानी लगभग 97 °C पर उबलता है, 100 °C पर नहीं जैसा उनकी पाठ्यपुस्तक कहती है। शिक्षक की सबसे अच्छी प्रतिक्रिया है:","optionsHi":["उन्हें 100 °C लिखने को कहना, क्योंकि वही सही पाठ्यपुस्तक-उत्तर है","उन्हें बताना कि उनका तापमापी खराब होगा और उसे बदल देना चाहिए","अंतर की उपेक्षा करना, क्योंकि प्रयोग में 3 °C इतना छोटा है कि मायने नहीं रखता","कारणों, जैसे ऊँचाई पर कम वायु-दाब, पर चर्चा करना और उन्हें जाँचने के तरीके"],"explanationHi":"अप्रत्याशित परिणाम साक्ष्य से तर्क करने के अवसर हैं। ऊँचाई के साथ क्वथनांक घटता है, और तापमापी की जाँच भी समझदारी है; पाठ्यपुस्तक का मान थोपना बेईमानी सिखाता है।"},
  {"id":"cdp-pedagogy-subjects-1434","question":"A Class 6 teacher first asks students to measure the length of the classroom in hand spans, and then compares the different answers they get. The main purpose is to:","options":["Help students see the need for a standard unit of length","Teach that hand spans are the most accurate unit of length","Save time, since hand spans are quicker than using a tape","Test which students have the largest hands in the class"],"answer":0,"explanation":"Different answers from different-sized hands make students feel the need for a common standard unit, which motivates the introduction of standard units.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा 6 की एक शिक्षिका पहले विद्यार्थियों से कक्षा की लंबाई बित्तों (hand spans) में मापने को कहती है, और फिर उन्हें मिलने वाले भिन्न उत्तरों की तुलना करती है। मुख्य उद्देश्य है:","optionsHi":["विद्यार्थियों को लंबाई की मानक इकाई की आवश्यकता देखने में मदद करना","यह सिखाना कि बित्ते लंबाई की सबसे सटीक इकाई हैं","समय बचाना, क्योंकि बित्ते फ़ीते से तेज़ हैं","यह जाँचना कि कक्षा में किसके हाथ सबसे बड़े हैं"],"explanationHi":"अलग-अलग आकार के हाथों से अलग-अलग उत्तर विद्यार्थियों को एक साझा मानक इकाई की आवश्यकता महसूस कराते हैं, जो मानक इकाइयों के परिचय को प्रेरित करता है।"},
  {"id":"cdp-pedagogy-subjects-1435","question":"While teaching adolescence and reproductive health in Class 8, a teacher finds that students are embarrassed and that several hold myths they heard at home. The most suitable approach is to:","options":["Skip the chapter, since it is a sensitive topic for many families","Ask students to read the chapter quietly at home, without any class discussion","Keep a respectful tone, give accurate facts and use an anonymous question box","Tell students not to discuss the subject with anyone, even at home"],"answer":2,"explanation":"NCF 2005 includes reproductive and sexual health at the upper primary stage. A safe, respectful setting, accurate information and anonymous questions help students overcome embarrassment and myths.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"कक्षा 8 में किशोरावस्था और प्रजनन स्वास्थ्य पढ़ाते समय एक शिक्षक पाता है कि विद्यार्थी संकोच में हैं और कई ऐसे मिथक रखते हैं जो उन्होंने घर पर सुने। सबसे उपयुक्त उपागम है:","optionsHi":["अध्याय छोड़ देना, क्योंकि यह कई परिवारों के लिए संवेदनशील विषय है","विद्यार्थियों से अध्याय घर पर चुपचाप पढ़ने को कहना, कक्षा में किसी चर्चा के बिना","सम्मानजनक स्वर रखना, सटीक तथ्य देना और गुमनाम प्रश्न-पेटी का उपयोग करना","विद्यार्थियों से कहना कि इस विषय पर किसी से चर्चा न करें, घर पर भी नहीं"],"explanationHi":"NCF 2005 उच्च प्राथमिक अवस्था में प्रजनन और यौन स्वास्थ्य को शामिल करती है। सुरक्षित, सम्मानजनक वातावरण, सटीक जानकारी और गुमनाम प्रश्न विद्यार्थियों को संकोच और मिथकों से उबरने में मदद करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1436","question":"A student with a hearing impairment is in a Class 8 lesson on sound. Which arrangement best allows her to take part?","options":["Excusing her from the whole lesson, since she cannot hear the sounds being made","Letting her feel vibrations, as on a drum skin, with visual and written cues","Seating her at the back so that the others can hear the teacher better","Giving her extra reading from the textbook in place of the activities"],"answer":1,"explanation":"Sound is caused by vibrations, which can be felt and seen. Multi-sensory activities with visual cues allow full participation in the concept.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा 8 की ध्वनि पर एक पाठ में श्रवण-बाधित विद्यार्थी है। कौन-सी व्यवस्था उसे भाग लेने की सबसे अच्छी अनुमति देती है?","optionsHi":["उसे पूरे पाठ से छूट देना, क्योंकि वह उत्पन्न की जा रही ध्वनियाँ सुन नहीं सकती","उसे कंपन महसूस करने देना, जैसे ढोल की खाल पर, दृश्य और लिखित संकेतों के साथ","उसे पीछे बिठाना ताकि बाकी शिक्षक को बेहतर सुन सकें","गतिविधियों के स्थान पर उसे पाठ्यपुस्तक से अतिरिक्त पठन देना"],"explanationHi":"ध्वनि कंपनों से उत्पन्न होती है, जिन्हें महसूस और देखा जा सकता है। दृश्य संकेतों के साथ बहु-संवेदी गतिविधियाँ संकल्पना में पूर्ण भागीदारी की अनुमति देती हैं।"},
  {"id":"cdp-pedagogy-subjects-1437","question":"Assertion (A): A student's marks in written science tests alone are an inadequate indicator of her scientific ability. Reason (R): Science learning includes process skills and attitudes that written tests rarely capture.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Scientific ability includes observing, experimenting, curiosity and honesty, which written tests capture poorly; that is why marks alone are an incomplete picture.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"अभिकथन (A): किसी विद्यार्थी के केवल लिखित विज्ञान परीक्षाओं के अंक उसकी वैज्ञानिक क्षमता का अपर्याप्त सूचक हैं। कारण (R): विज्ञान अधिगम में प्रक्रिया-कौशल और अभिवृत्तियाँ शामिल हैं जिन्हें लिखित परीक्षाएँ कदाचित् ही पकड़ पाती हैं।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"वैज्ञानिक क्षमता में अवलोकन, प्रयोग, जिज्ञासा और ईमानदारी शामिल हैं, जिन्हें लिखित परीक्षाएँ कम पकड़ती हैं; इसीलिए केवल अंक अधूरी तस्वीर देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1438","question":"Which question best assesses the process skill of interpreting data?","options":["Define solubility and give one example of a soluble substance.","Name two substances that dissolve in water and two that do not.","What is the chemical formula of common salt, and what is its common name?","Using a table of sugar dissolved at 20, 40, 60 °C, estimate it at 50 °C."],"answer":3,"explanation":"Interpreting data means reading patterns in data and making reasoned estimates from them. The other questions test recall only.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कौन-सा प्रश्न आँकड़ों की व्याख्या करने के प्रक्रिया-कौशल का सबसे अच्छा आकलन करता है?","optionsHi":["विलेयता की परिभाषा दीजिए और एक विलेय पदार्थ का उदाहरण दीजिए।","पानी में घुलने वाले दो पदार्थों और न घुलने वाले दो पदार्थों के नाम बताइए।","साधारण नमक का रासायनिक सूत्र क्या है, और उसका प्रचलित नाम क्या है?","20, 40, 60 °C पर घुली चीनी की तालिका का उपयोग करके 50 °C पर उसका अनुमान लगाइए।"],"explanationHi":"आँकड़ों की व्याख्या का अर्थ है आँकड़ों में प्रतिरूप पढ़ना और उनसे तर्कसंगत अनुमान लगाना। अन्य प्रश्न केवल स्मरण की जाँच करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1439","question":"Students believe that plants take in water only to 'drink' it and that they lose none. Which activity best challenges this belief?","options":["Watering a potted plant and watching the soil around it get wet and dark","Covering a leafy branch with a clear plastic bag in sunlight","Measuring the height of the plant every day for a week","Cutting the roots of a plant and seeing whether it wilts"],"answer":1,"explanation":"Droplets inside the bag come from water vapour given out by the leaves (transpiration), showing that plants lose much of the water they absorb.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"विद्यार्थी मानते हैं कि पौधे पानी केवल 'पीने' के लिए लेते हैं और उसमें से कुछ नहीं खोते। कौन-सी गतिविधि इस विश्वास को सबसे अच्छी तरह चुनौती देती है?","optionsHi":["गमले के पौधे में पानी देना और आस-पास की मिट्टी को गीली और गहरी होते देखना","धूप में पत्तेदार डाली को पारदर्शी प्लास्टिक की थैली से ढकना","एक सप्ताह तक हर दिन पौधे की ऊँचाई मापना","किसी पौधे की जड़ें काटना और देखना कि वह मुरझाता है या नहीं"],"explanationHi":"थैली के अंदर की बूँदें पत्तियों द्वारा छोड़ी गई जलवाष्प (वाष्पोत्सर्जन) से आती हैं, जो दिखाती हैं कि पौधे अवशोषित जल का बड़ा भाग खो देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1440","question":"Students often say 'heat rises'. Which statement should the teacher help them reach?","options":["Heat always moves upwards, whatever the material it is passing through may be","Heat moves only by convection, so it must always travel upwards","Heat moves upwards in solids but downwards in liquids and gases","Warm fluids rise, but heat can travel any way by conduction and radiation"],"answer":3,"explanation":"It is warm fluid that rises, carrying heat by convection; heat conducts along a rod in any direction and radiates in all directions. The everyday phrase hides this distinction.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"विद्यार्थी प्रायः कहते हैं 'ऊष्मा ऊपर उठती है'। शिक्षक को उन्हें किस कथन तक पहुँचने में मदद करनी चाहिए?","optionsHi":["ऊष्मा हमेशा ऊपर की ओर जाती है, चाहे वह जिस पदार्थ से गुज़र रही हो","ऊष्मा केवल संवहन से चलती है, इसलिए उसे हमेशा ऊपर ही जाना चाहिए","ऊष्मा ठोसों में ऊपर और द्रवों तथा गैसों में नीचे की ओर जाती है","गर्म तरल ऊपर उठते हैं, पर ऊष्मा चालन और विकिरण से किसी भी ओर जा सकती है"],"explanationHi":"ऊपर वह गर्म तरल उठता है जो संवहन से ऊष्मा ले जाता है; ऊष्मा छड़ में किसी भी दिशा में चालित होती है और सभी दिशाओं में विकिरित होती है। रोज़मर्रा का वाक्यांश इस अंतर को छिपा देता है।"},
  {"id":"cdp-pedagogy-subjects-1441","question":"A student says that water evaporates only when it is heated to 100 °C. Which question best challenges this idea?","options":["'What is the boiling point of water at normal air pressure?'","'Why do wet clothes dry on a line even on a cold winter day?'","'Does water boil faster in a covered pan or an open one?'","'What is the difference between boiling and melting a substance?'"],"answer":1,"explanation":"Clothes drying at ordinary temperatures shows that evaporation occurs at any temperature from the surface of a liquid; 100 °C is the boiling point, not the temperature of evaporation.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"एक विद्यार्थी कहता है कि पानी का वाष्पन केवल तब होता है जब उसे 100 °C तक गर्म किया जाए। कौन-सा प्रश्न इस विचार को सबसे अच्छी तरह चुनौती देता है?","optionsHi":["'सामान्य वायु-दाब पर पानी का क्वथनांक क्या है?'","'ठंडे सर्दी के दिन भी तार पर गीले कपड़े क्यों सूखते हैं?'","'ढके बर्तन में पानी तेज़ उबलता है या खुले बर्तन में?'","'किसी पदार्थ को उबालने और पिघलाने में क्या अंतर है?'"],"explanationHi":"सामान्य तापमान पर कपड़ों का सूखना दिखाता है कि वाष्पन किसी भी तापमान पर द्रव की सतह से होता है; 100 °C क्वथनांक है, वाष्पन का तापमान नहीं।"},
  {"id":"cdp-pedagogy-subjects-1442","question":"Which learning objective in a science lesson plan is stated in the most useful form?","options":["Students will know about magnets and their many uses in daily life.","Students will understand magnets well and enjoy learning about them.","Students will sort objects a magnet attracts and state a rule for them.","Students will appreciate the importance of magnets in modern technology."],"answer":2,"explanation":"An objective stated as observable behaviour (sort, state a rule) tells the teacher what to look for in assessment. 'Know' and 'understand' cannot be observed directly.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"विज्ञान की पाठ-योजना में कौन-सा अधिगम-उद्देश्य सबसे उपयोगी रूप में कहा गया है?","optionsHi":["विद्यार्थी चुंबकों और दैनिक जीवन में उनके अनेक उपयोगों के बारे में जानेंगे।","विद्यार्थी चुंबकों को अच्छी तरह समझेंगे और उनके बारे में सीखने का आनंद लेंगे।","विद्यार्थी चुंबक द्वारा आकर्षित होने वाली वस्तुओं को छाँटेंगे और उनके लिए नियम बताएँगे।","विद्यार्थी आधुनिक प्रौद्योगिकी में चुंबकों के महत्त्व की सराहना करेंगे।"],"explanationHi":"अवलोकनीय व्यवहार (छाँटना, नियम बताना) के रूप में कहा गया उद्देश्य शिक्षक को बताता है कि आकलन में क्या देखना है। 'जानना' और 'समझना' को सीधे नहीं देखा जा सकता।"},
  {"id":"cdp-pedagogy-subjects-1443","question":"While planning a unit on electricity, a teacher draws a concept map of the ideas involved. This is most useful to her because it helps her:","options":["See how concepts link and which ideas students need first","Decide exactly how many periods the unit on electricity will need","Avoid using activities, since the map already shows all the ideas","Choose questions for the final test only, not for daily teaching"],"answer":0,"explanation":"A planning concept map shows how concepts connect and reveals prerequisites, such as a closed path before series circuits, so the unit can be sequenced logically.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"बिजली पर इकाई की योजना बनाते समय एक शिक्षिका शामिल विचारों का संकल्पना-मानचित्र बनाती है। यह उसके लिए सबसे उपयोगी इसलिए है कि वह उसे मदद करता है:","optionsHi":["देखने में कि संकल्पनाएँ कैसे जुड़ती हैं और विद्यार्थियों को कौन-से विचार पहले चाहिए","ठीक-ठीक तय करने में कि बिजली की इकाई को कितने कालांश चाहिए","गतिविधियों से बचने में, क्योंकि मानचित्र पहले ही सभी विचार दिखा देता है","केवल अंतिम परीक्षा के प्रश्न चुनने में, दैनिक शिक्षण के लिए नहीं"],"explanationHi":"योजना का संकल्पना-मानचित्र दिखाता है कि संकल्पनाएँ कैसे जुड़ती हैं और पूर्वापेक्षाएँ प्रकट करता है, जैसे श्रेणी परिपथों से पहले बंद पथ, ताकि इकाई को तार्किक क्रम में रखा जा सके।"},
  {"id":"cdp-pedagogy-subjects-1444","question":"On a nature walk to make a herbarium, students start plucking leaves and flowers from every plant they see. The teacher's best guidance is to:","options":["Allow it, since the herbarium needs as many specimens as possible","Stop the herbarium activity altogether and return to the classroom","Ask them to pluck only from plants in other people's gardens","Ask them to take mostly fallen leaves and only a few fresh samples"],"answer":3,"explanation":"Science activities should respect living things and the environment. Collecting fallen material and minimal samples meets the learning aim while showing concern for life.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"हर्बेरियम बनाने की प्रकृति-सैर पर विद्यार्थी जो भी पौधा दिखता है उसकी पत्तियाँ और फूल तोड़ने लगते हैं। शिक्षक का सबसे अच्छा मार्गदर्शन है:","optionsHi":["अनुमति देना, क्योंकि हर्बेरियम को जितने अधिक नमूने हों उतना अच्छा","हर्बेरियम गतिविधि पूरी तरह रोककर कक्षा में लौट आना","उनसे केवल दूसरों के बगीचों के पौधों से तोड़ने को कहना","उनसे अधिकतर गिरी हुई पत्तियाँ लेने और केवल कुछ ताज़े नमूने लेने को कहना"],"explanationHi":"विज्ञान की गतिविधियों में जीवित प्राणियों और पर्यावरण का सम्मान होना चाहिए। गिरी हुई सामग्री और न्यूनतम नमूने इकट्ठा करना अधिगम-लक्ष्य पूरा करता है और जीवन के प्रति चिंता दिखाता है।"},
  {"id":"cdp-pedagogy-subjects-1445","question":"For laboratory work, a teacher deliberately forms groups that mix students who are more and less confident in science. This is supported mainly by the idea that:","options":["Weaker students should be kept busy by the stronger ones in the group","Learners can go beyond their own level with help from abler peers","Mixed groups make the teacher's job of supervising much easier","Students should compete within groups to see who is the best"],"answer":1,"explanation":"Vygotsky's zone of proximal development suggests that learners achieve more with support from more knowledgeable others, including peers.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"प्रयोगशाला-कार्य के लिए एक शिक्षक जानबूझकर विज्ञान में अधिक और कम आत्मविश्वासी विद्यार्थियों को मिलाकर समूह बनाता है। इसका मुख्य समर्थन किस विचार से होता है:","optionsHi":["कमज़ोर विद्यार्थियों को समूह के मज़बूत विद्यार्थियों द्वारा व्यस्त रखा जाना चाहिए","अधिगमकर्ता अधिक सक्षम सहपाठियों की मदद से अपने स्तर से आगे जा सकते हैं","मिश्रित समूह शिक्षक के पर्यवेक्षण का कार्य बहुत आसान बनाते हैं","विद्यार्थियों को समूहों के भीतर प्रतिस्पर्धा करनी चाहिए कि सबसे अच्छा कौन है"],"explanationHi":"वाइगोत्स्की का निकटस्थ विकास का क्षेत्र सुझाता है कि अधिगमकर्ता अधिक जानकार अन्य, सहपाठियों सहित, के सहारे अधिक प्राप्त करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1446","question":"To help students understand insulation, a teacher wraps one glass of ice in newspaper and leaves another unwrapped. Students predict that the wrapped ice will melt faster, 'because paper makes it warm'. The best follow-up is to:","options":["Tell them clearly that they are wrong and then explain the correct answer","Observe both, compare melting times and discuss why paper slowed it","Skip the observation, since the answer is given in the textbook","Add more ice to the unwrapped glass so that the test is fairer"],"answer":1,"explanation":"Letting the evidence contradict the prediction, then discussing it, helps students see that the paper slows heat flow from the warm air to the ice rather than 'adding warmth'.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · KVS","questionHi":"विद्युतरोधन समझाने के लिए एक शिक्षक बर्फ़ के एक गिलास को अख़बार में लपेटता है और दूसरे को खुला छोड़ देता है। विद्यार्थी पूर्वानुमान लगाते हैं कि लपेटी हुई बर्फ़ तेज़ पिघलेगी, 'क्योंकि कागज़ गर्म बनाता है'। सबसे अच्छा अनुवर्तन है:","optionsHi":["उन्हें स्पष्ट बताना कि वे गलत हैं और फिर सही उत्तर समझाना","दोनों का अवलोकन करना, पिघलने के समय की तुलना करना और चर्चा करना कि कागज़ ने इसे धीमा क्यों किया","अवलोकन छोड़ देना, क्योंकि उत्तर पाठ्यपुस्तक में दिया है","खुले गिलास में और बर्फ़ डालना ताकि परीक्षण अधिक निष्पक्ष हो"],"explanationHi":"साक्ष्य को पूर्वानुमान का खंडन करने देना, फिर चर्चा करना, विद्यार्थियों को देखने में मदद करता है कि कागज़ 'गर्मी जोड़ने' के बजाय गर्म हवा से बर्फ़ की ओर ऊष्मा-प्रवाह को धीमा करता है।"},
  {"id":"cdp-pedagogy-subjects-1447","question":"A teacher gives Class 8 students a choice between preparing for a science quiz and carrying out a month-long investigation of plant growth in different soils. Which better develops inquiry skills, and why?","options":["The quiz, because it covers many more facts in a short time","The quiz, because competition makes students work much harder","The investigation, since students plan, collect and interpret data","Both equally, since both of them involve the subject matter of science"],"answer":2,"explanation":"An investigation engages students in the full process of inquiry; a quiz mainly rewards quick recall of facts.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"एक शिक्षक कक्षा 8 के विद्यार्थियों को विज्ञान प्रश्नोत्तरी की तैयारी और विभिन्न मिट्टियों में पौधों की वृद्धि की माह-भर की जाँच के बीच चुनाव देता है। कौन-सा जिज्ञासा-आधारित अन्वेषण कौशल को बेहतर विकसित करता है, और क्यों?","optionsHi":["प्रश्नोत्तरी, क्योंकि वह थोड़े समय में कहीं अधिक तथ्यों को समेटती है","प्रश्नोत्तरी, क्योंकि प्रतिस्पर्धा विद्यार्थियों को कहीं अधिक मेहनत कराती है","जाँच, क्योंकि विद्यार्थी योजना बनाते, आँकड़े एकत्र करते और व्याख्या करते हैं","दोनों समान रूप से, क्योंकि दोनों में विज्ञान की विषय-वस्तु शामिल है"],"explanationHi":"जाँच विद्यार्थियों को जिज्ञासा-आधारित अन्वेषण की पूरी प्रक्रिया में संलग्न करती है; प्रश्नोत्तरी मुख्यतः तथ्यों के त्वरित स्मरण को पुरस्कृत करती है।"},
  {"id":"cdp-pedagogy-subjects-1448","question":"Four children scored 2, 4, 0 and 6 in a quiz. A Class 7 student finds the mean as 4, saying ‘0 is nothing, so I divided 12 by 3.’ What is the misconception?","options":["She ignores 0 as a data value; the mean is 12 ÷ 4 = 3","She has added the four scores wrongly; the total is really 14","She has found the median of the scores instead of the mean","She has found the mode of the scores instead of the mean"],"answer":0,"explanation":"A score of 0 is still one child's value, so there are four values and the mean is 3. Thinking of the mean as ‘evening out’ the scores, with the 0 child receiving some too, shows why it counts.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"चार बच्चों ने एक प्रश्नोत्तरी में 2, 4, 0 और 6 अंक पाए। कक्षा 7 की एक विद्यार्थी माध्य 4 निकालती है, यह कहकर कि '0 कुछ नहीं है, इसलिए मैंने 12 को 3 से भाग दिया।' भ्रांति क्या है?","optionsHi":["वह 0 को आँकड़े के मान के रूप में नज़रअंदाज़ करती है; माध्य 12 ÷ 4 = 3 है","उसने चारों अंकों का योग गलत जोड़ा है; कुल वास्तव में 14 है","उसने माध्य के बजाय अंकों की माध्यिका निकाली है","उसने माध्य के बजाय अंकों का बहुलक निकाला है"],"explanationHi":"0 अंक भी एक बच्चे का मान है, इसलिए चार मान हैं और माध्य 3 है। माध्य को अंकों को 'बराबर करने' के रूप में सोचना, जिसमें 0 वाले बच्चे को भी कुछ मिलता है, दिखाता है कि वह क्यों गिना जाता है।"},
  {"id":"cdp-pedagogy-subjects-1449","question":"A student gives the median of 7, 2, 9, 4, 5 as 9. What has she done?","options":["Taken the largest value in the list as the median of the data","Picked the middle value without first ordering the data","Found the mean of the values and rounded it up","Taken the value that occurs most often in the list"],"answer":1,"explanation":"9 is the middle entry of the unsorted list. Ordered, the data are 2, 4, 5, 7, 9, so the median is 5. The median depends on order of size, not on the order in which the data were written.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"एक विद्यार्थी 7, 2, 9, 4, 5 की माध्यिका 9 बताती है। उसने क्या किया है?","optionsHi":["सूची के सबसे बड़े मान को आँकड़ों की माध्यिका ले लिया","आँकड़ों को पहले क्रमबद्ध किए बिना बीच का मान चुन लिया","मानों का माध्य निकालकर उसे ऊपर पूर्णांकित कर दिया","सूची में सबसे अधिक बार आने वाला मान ले लिया"],"explanationHi":"9 अक्रमित सूची की मध्य प्रविष्टि है। क्रमबद्ध करने पर आँकड़े 2, 4, 5, 7, 9 हैं, इसलिए माध्यिका 5 है। माध्यिका आकार के क्रम पर निर्भर करती है, इस पर नहीं कि आँकड़े किस क्रम में लिखे गए।"},
  {"id":"cdp-pedagogy-subjects-1450","question":"Which task best assesses a Class 7 student's understanding of the mean, beyond the procedure?","options":["Find the mean of 4, 8, 6 and 2, showing every step of the working clearly","Write down the formula for the mean and name each symbol used in it","Mean sweets for five children is 6; suggest each child’s share and explain","Find the mean of the first ten natural numbers without a calculator"],"answer":2,"explanation":"Working backwards from a mean to possible data needs the idea that the total is 5 × 6 = 30 and can be shared in many ways. Computing a mean only checks the procedure.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कौन-सा कार्य कक्षा 7 के विद्यार्थी की माध्य की समझ का, प्रक्रिया से आगे, सबसे अच्छा आकलन करता है?","optionsHi":["4, 8, 6 और 2 का माध्य निकालिए, प्रत्येक चरण का कार्य स्पष्ट दिखाते हुए","माध्य का सूत्र लिखिए और उसमें प्रयुक्त प्रत्येक प्रतीक का नाम बताइए","पाँच बच्चों के लिए माध्य मिठाइयाँ 6 हैं; प्रत्येक बच्चे का हिस्सा सुझाइए और समझाइए","पहली दस प्राकृत संख्याओं का माध्य बिना कैलकुलेटर के निकालिए"],"explanationHi":"माध्य से पीछे की ओर संभावित आँकड़ों तक जाने के लिए यह विचार चाहिए कि कुल 5 × 6 = 30 है और उसे अनेक तरीकों से बाँटा जा सकता है। माध्य की गणना केवल प्रक्रिया की जाँच करती है।"},
  {"id":"cdp-pedagogy-subjects-1451","question":"A bar graph of two shops' sales has its vertical axis starting at 50. Shop A's bar reaches 60 and Shop B's reaches 80. A student says Shop B sold three times as much as Shop A. What should the teacher help her notice?","options":["She is right, since the bar for Shop B is three times as tall as the bar for A","She has misread the values; they are really 6 and 8 on the scale","Bar graphs cannot be used to compare the sales of two shops","The axis starts at 50, so bar heights exaggerate it; 80 is only 4/3 of 60"],"answer":3,"explanation":"Above the 50 line the bars are 10 and 30 units tall, which looks like 3 times. The actual sales are 60 and 80. Reading axes critically, and spotting misleading graphs, is part of data literacy.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"दो दुकानों की बिक्री के स्तंभ-आलेख की ऊर्ध्वाधर अक्ष 50 से शुरू होती है। दुकान A का स्तंभ 60 तक पहुँचता है और दुकान B का 80 तक। एक विद्यार्थी कहती है कि दुकान B ने दुकान A से तीन गुना बेचा। शिक्षक को उसे क्या देखने में मदद करनी चाहिए?","optionsHi":["वह सही है, क्योंकि दुकान B का स्तंभ A के स्तंभ से तीन गुना ऊँचा है","उसने मान गलत पढ़े हैं; पैमाने पर वे वास्तव में 6 और 8 हैं","स्तंभ-आलेख से दो दुकानों की बिक्री की तुलना नहीं की जा सकती","अक्ष 50 से शुरू होती है, इसलिए स्तंभों की ऊँचाई अतिशयोक्ति करती है; 80 केवल 4/3 गुना है, 60 की तुलना में"],"explanationHi":"50 की रेखा के ऊपर स्तंभ 10 और 30 इकाई ऊँचे हैं, जो 3 गुना दिखता है। वास्तविक बिक्री 60 और 80 है। अक्षों को आलोचनात्मक रूप से पढ़ना, और भ्रामक आलेखों को पहचानना, आँकड़ा-साक्षरता का भाग है।"},
  {"id":"cdp-pedagogy-subjects-1452","question":"A die shows 6 three times in a row. A student says a 6 is now less likely on the next throw ‘because it has come too often’. How should the teacher respond?","options":["Say the die has no memory, so the chance stays 1/6, and test many throws","Agree, since the number 6 has already had more than its fair share of turns","Tell her that a 6 is now more likely, since the die seems to favour it","Tell her that probability cannot be used with dice or other games"],"answer":0,"explanation":"Each throw is independent, so the chance of a 6 stays 1/6. Thinking a result is ‘due’ or ‘used up’ is the gambler's fallacy; collecting real data helps students see that streaks occur naturally.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"एक पासा लगातार तीन बार 6 दिखाता है। एक विद्यार्थी कहती है कि अगली फेंक में 6 अब कम संभावित है 'क्योंकि वह बहुत बार आ चुका है'। शिक्षक को कैसे प्रतिक्रिया देनी चाहिए?","optionsHi":["कहना कि पासे की कोई स्मृति नहीं होती, इसलिए प्रायिकता 1/6 ही रहती है, और अनेक फेंकों से परखना","सहमत होना, क्योंकि संख्या 6 अपनी उचित बारियों से अधिक पा चुकी है","उसे बताना कि अब 6 अधिक संभावित है, क्योंकि पासा उसका पक्ष लेता प्रतीत होता है","उसे बताना कि पासों या अन्य खेलों के साथ प्रायिकता का उपयोग नहीं हो सकता"],"explanationHi":"प्रत्येक फेंक स्वतंत्र है, इसलिए 6 आने की प्रायिकता 1/6 ही रहती है। यह सोचना कि कोई परिणाम 'देय है' या 'खत्म हो गया' जुआरी की भ्रांति है; वास्तविक आँकड़े एकत्र करने से विद्यार्थी देखते हैं कि लगातार परिणाम स्वाभाविक रूप से होते हैं।"},
  {"id":"cdp-pedagogy-subjects-1453","question":"A student says that when two coins are tossed there are three outcomes, two heads, two tails, or one of each, so each has a probability of 1/3. What is the best response?","options":["Agree, since there are three possible results and each is equally likely","Have her list outcomes for a ₹1 and a ₹2 coin, then toss two coins many times","Tell her probability does not apply when two different coins are tossed together","Tell her the answer is 1/2 for each result, since a coin has two sides"],"answer":1,"explanation":"Distinguishing the coins shows four equally likely outcomes, so ‘one of each’ has probability 2/4 = 1/2, and two heads 1/4. Labelling the coins and experimenting expose the error.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक विद्यार्थी कहती है कि जब दो सिक्के उछाले जाते हैं तो तीन परिणाम होते हैं, दो चित, दो पट, या एक-एक, इसलिए प्रत्येक की प्रायिकता 1/3 है। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["सहमत होना, क्योंकि तीन संभावित परिणाम हैं और प्रत्येक समान रूप से संभावित है","उससे ₹1 और ₹2 के सिक्के के परिणामों की सूची बनवाना, फिर दो सिक्कों को कई बार उछालना","उसे बताना कि दो अलग सिक्के साथ उछालने पर प्रायिकता लागू नहीं होती","उसे बताना कि प्रत्येक परिणाम के लिए उत्तर 1/2 है, क्योंकि सिक्के के दो पहलू होते हैं"],"explanationHi":"सिक्कों को अलग करने से चार समान रूप से संभावित परिणाम दिखते हैं, इसलिए 'एक-एक' की प्रायिकता 2/4 = 1/2 है, और दो चित की 1/4। सिक्कों को नाम देना और प्रयोग करना त्रुटि को उजागर करता है।"},
  {"id":"cdp-pedagogy-subjects-1454","question":"Asked to divide ₹40 between Asha and Babu in the ratio 3 : 5, a student gives Asha ₹24, saying ‘3/5 of 40 is 24’. What is the misconception?","options":["She has made an arithmetic slip while working out 3/5 of 40","She has given Asha's share to Babu by reversing the ratio","She reads 3 : 5 as 3/5 of the whole, not 3 of 8 parts","She has used the unitary method wrongly in the last step"],"answer":2,"explanation":"A part-to-part ratio of 3 : 5 means Asha gets 3 of 8 equal parts: 3/8 × 40 = ₹15, and Babu ₹25. Confusing part-part with part-whole is a common ratio error.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"₹40 को आशा और बाबू में 3 : 5 के अनुपात में बाँटने को कहे जाने पर एक विद्यार्थी आशा को ₹24 देती है, यह कहकर कि '40 का 3/5 है 24'। भ्रांति क्या है?","optionsHi":["3/5 × 40 निकालते समय उसने अंकगणितीय चूक की है","उसने अनुपात उलटकर आशा का हिस्सा बाबू को दे दिया है","वह 3 : 5 को पूर्ण का 3/5 पढ़ती है, न कि 3 भाग (कुल 8 भागों में)","उसने अंतिम चरण में ऐकिक विधि का गलत उपयोग किया है"],"explanationHi":"3 : 5 का भाग-भाग अनुपात का अर्थ है कि आशा को 8 समान भागों में से 3 मिलते हैं: 3/8 × 40 = ₹15, और बाबू को ₹25। भाग-भाग को भाग-पूर्ण से भ्रमित करना अनुपात की एक सामान्य त्रुटि है।"},
  {"id":"cdp-pedagogy-subjects-1455","question":"Finding the area of a triangle, a Class 7 student multiplies half the base by the length of a slanting side. What is the best way to address this?","options":["Tell her to always take the longest side of the triangle as its height instead","Give her more triangles with the height already marked on each one","Ask her to learn the formula more carefully and revise it every day","Have her draw the perpendicular to the base and compare it with the slant side"],"answer":3,"explanation":"Height in ½ × base × height must be perpendicular to the base. Drawing it shows it is shorter than the slant side; marking it in advance would hide the very idea she lacks.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"त्रिभुज का क्षेत्रफल निकालते समय कक्षा 7 की एक विद्यार्थी आधार के आधे को तिर्यक भुजा की लंबाई से गुणा करती है। इसे संबोधित करने का सबसे अच्छा तरीका क्या है?","optionsHi":["उसे बताना कि वह त्रिभुज की सबसे लंबी भुजा को हमेशा ऊँचाई के रूप में ले","उसे ऐसे और त्रिभुज देना जिनमें प्रत्येक पर ऊँचाई पहले से अंकित हो","उससे सूत्र को अधिक सावधानी से सीखने और हर दिन दोहराने को कहना","उससे आधार पर लंब खींचवाना और उसकी तिर्यक भुजा से तुलना करवाना"],"explanationHi":"½ × आधार × ऊँचाई में ऊँचाई आधार पर लंबवत होनी चाहिए। उसे खींचना दिखाता है कि वह तिर्यक भुजा से छोटी है; पहले से अंकित कर देना ठीक वही विचार छिपा देता जो उसमें नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1456","question":"A student says that doubling the radius of a circle doubles its area. Which activity best challenges this?","options":["Draw circles of radius 2 cm and 4 cm on squared paper and compare areas","Ask her to learn the formula area = πr² by heart and apply it carefully","Show her that the circumference also doubles when the radius is doubled","Tell her that the area actually becomes three times larger"],"answer":0,"explanation":"Since area depends on r², doubling r multiplies area by 4 (4π against 16π). Counting squares makes this visible. The circumference does double, which is probably where her idea came from.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक विद्यार्थी कहती है कि वृत्त की त्रिज्या दुगुनी करने से उसका क्षेत्रफल दुगुना हो जाता है। कौन-सी गतिविधि इसे सबसे अच्छी तरह चुनौती देती है?","optionsHi":["वर्गांकित कागज़ पर 2 cm और 4 cm त्रिज्या के वृत्त बनाना और क्षेत्रफलों की तुलना करना","उससे सूत्र क्षेत्रफल = πr² कंठस्थ करने और सावधानी से लागू करने को कहना","उसे दिखाना कि त्रिज्या दुगुनी करने पर परिधि भी दुगुनी हो जाती है","उसे बताना कि क्षेत्रफल वास्तव में तीन गुना बड़ा हो जाता है"],"explanationHi":"क्योंकि क्षेत्रफल r² पर निर्भर है, r दुगुना करने से क्षेत्रफल 4 गुना हो जाता है (4π बनाम 16π)। वर्ग गिनने से यह दृश्यमान होता है। परिधि दुगुनी होती है, संभवतः यहीं से उसका विचार आया।"},
  {"id":"cdp-pedagogy-subjects-1457","question":"Students believe that cuboids with the same volume must have the same surface area. Which activity best challenges this?","options":["Giving them the formulae for volume and surface area to memorise and use","Building cuboids from 12 unit cubes and counting their outer faces","Measuring the volume of water in a jug with a measuring cylinder","Showing them that every cube and cuboid has exactly six faces"],"answer":1,"explanation":"Both cuboids have a volume of 12 cubes, but the outside surfaces are 50 and 32 square units. Building and counting shows the two measures are independent.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"विद्यार्थी मानते हैं कि समान आयतन वाले घनाभों का पृष्ठीय क्षेत्रफल भी समान होना चाहिए। कौन-सी गतिविधि इसे सबसे अच्छी तरह चुनौती देती है?","optionsHi":["उन्हें आयतन और पृष्ठीय क्षेत्रफल के सूत्र याद करने और उपयोग करने को देना","12 इकाई घनों से घनाभ बनाना और उनके बाहरी फलक गिनना","मापन सिलिंडर से जग में पानी का आयतन मापना","उन्हें दिखाना कि प्रत्येक घन और घनाभ के ठीक छह फलक होते हैं"],"explanationHi":"दोनों घनाभों का आयतन 12 घन है, पर बाहरी पृष्ठ 50 और 32 वर्ग इकाई हैं। बनाने और गिनने से दिखता है कि दोनों माप स्वतंत्र हैं।"},
  {"id":"cdp-pedagogy-subjects-1458","question":"A Class 7 student divides fractions quickly using ‘invert and multiply’ but cannot say what 3 ÷ 1/2 means, and in a new problem she inverts the wrong fraction. In Skemp's terms, her understanding is:","options":["relational, since she gets most of her answers right quickly","logical, since she follows a fixed procedure step by step","instrumental, since she knows the rule but not why it works","conceptual, since she knows the meaning of division well"],"answer":2,"explanation":"Instrumental understanding is ‘rules without reasons’; it works for familiar tasks but breaks down in new ones. Relational understanding, knowing what to do and why, lets a student rebuild or adapt the method.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक विद्यार्थी 'उलटो और गुणा करो' से भिन्नों का भाग तेज़ी से करती है पर नहीं बता सकती कि 3 ÷ 1/2 का क्या अर्थ है, और नई समस्या में वह गलत भिन्न उलट देती है। स्केम्प की शब्दावली में उसकी समझ है:","optionsHi":["संबंधात्मक, क्योंकि वह अधिकांश उत्तर शीघ्र सही पाती है","तार्किक, क्योंकि वह निश्चित प्रक्रिया का चरण-दर-चरण पालन करती है","यंत्रात्मक (instrumental), क्योंकि वह नियम जानती है पर यह नहीं कि वह क्यों काम करता है","संकल्पनात्मक, क्योंकि वह भाग का अर्थ अच्छी तरह जानती है"],"explanationHi":"यंत्रात्मक समझ 'कारणों के बिना नियम' है; वह परिचित कार्यों में चलती है पर नए में टूट जाती है। संबंधात्मक समझ, क्या करना है और क्यों, विद्यार्थी को विधि को दोबारा बनाने या अनुकूलित करने देती है।"},
  {"id":"cdp-pedagogy-subjects-1459","question":"A Class 6 student computes accurately and quickly but often cannot decide which operation to use in a word problem. Among the strands of mathematical proficiency, which one is weakest?","options":["Procedural fluency","Productive disposition","Adaptive reasoning","Strategic competence"],"answer":3,"explanation":"Strategic competence is the ability to formulate, represent and solve problems, including choosing an operation. Her procedural fluency is strong; that alone does not make her a problem solver.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा 6 की एक विद्यार्थी सटीक और तेज़ गणना करती है पर प्रायः तय नहीं कर पाती कि शाब्दिक प्रश्न में कौन-सी संक्रिया उपयोग करे। गणितीय दक्षता के सूत्रों में से कौन-सा सबसे कमज़ोर है?","optionsHi":["प्रक्रियात्मक प्रवाह","उत्पादक अभिवृत्ति","अनुकूली तर्क","युक्तिपूर्ण सक्षमता (strategic competence)"],"explanationHi":"युक्तिपूर्ण सक्षमता समस्याओं को सूत्रबद्ध करने, निरूपित करने और हल करने की क्षमता है, जिसमें संक्रिया चुनना शामिल है। उसका प्रक्रियात्मक प्रवाह मज़बूत है; केवल वही उसे समस्या-समाधानकर्ता नहीं बनाता।"},
  {"id":"cdp-pedagogy-subjects-1460","question":"Match each strand of mathematical proficiency with its description. 1. Conceptual understanding 2. Procedural fluency 3. Strategic competence 4. Productive disposition; a. seeing mathematics as sensible and worthwhile, and oneself as able to learn it b. carrying out procedures accurately, efficiently and flexibly c. grasping concepts, operations and the relations between them d. formulating, representing and solving problems","options":["1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-c, 2-b, 3-a, 4-d"],"answer":0,"explanation":"These are four of the five interwoven strands described by Kilpatrick and colleagues; the fifth is adaptive reasoning, the capacity for logical thought, explanation and justification.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"गणितीय दक्षता के प्रत्येक सूत्र को उसके वर्णन से मिलाइए। 1. संकल्पनात्मक समझ 2. प्रक्रियात्मक प्रवाह 3. युक्तिपूर्ण सक्षमता 4. उत्पादक अभिवृत्ति; a. गणित को समझदार और सार्थक के रूप में देखना, और स्वयं को उसे सीखने में सक्षम मानना b. प्रक्रियाओं को सटीकता, दक्षता और लचीलेपन से करना c. संकल्पनाओं, संक्रियाओं और उनके संबंधों को समझना d. समस्याओं को सूत्रबद्ध, निरूपित और हल करना","optionsHi":["1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-c, 2-b, 3-a, 4-d"],"explanationHi":"ये किलपैट्रिक और सहकर्मियों द्वारा वर्णित पाँच परस्पर गुँथे सूत्रों में से चार हैं; पाँचवाँ अनुकूली तर्क है, तार्किक चिंतन, स्पष्टीकरण और औचित्य की क्षमता।"},
  {"id":"cdp-pedagogy-subjects-1461","question":"Which of these questions on fractions makes the highest cognitive demand on a Class 6 student?","options":["Work out 3/4 of 8 and show each step of your working clearly","Write a daily-life problem solved by 3/4 × 8 and explain why it fits","Write the fraction that shows 3 parts out of 4 equal parts of a whole","Is 3/4 a proper fraction or an improper one? Give the rule."],"answer":1,"explanation":"Creating a problem that fits a calculation needs the student to understand what ‘3/4 of’ means and to justify the match; it sits at the highest levels of Bloom's taxonomy. The others are recall or routine application.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"भिन्नों पर इन प्रश्नों में से कौन-सा कक्षा 6 के विद्यार्थी पर सबसे अधिक संज्ञानात्मक माँग डालता है?","optionsHi":["3/4 × 8 निकालिए और प्रत्येक चरण का कार्य स्पष्ट दिखाइए","3/4 × 8 से हल होने वाली दैनिक जीवन की समस्या लिखिए और समझाइए कि वह क्यों उपयुक्त है","वह भिन्न लिखिए जो 3 भाग दर्शाती है, किसी पूर्ण के 4 समान भागों में से","क्या 3/4 एक उचित भिन्न है या अनुचित? नियम बताइए।"],"explanationHi":"किसी गणना के अनुरूप समस्या बनाने के लिए विद्यार्थी को समझना पड़ता है कि '3/4 का' क्या अर्थ है और मेल का औचित्य देना पड़ता है; यह ब्लूम के वर्गीकरण के उच्चतम स्तरों पर है। अन्य स्मरण या नियमित अनुप्रयोग हैं।"},
  {"id":"cdp-pedagogy-subjects-1462","question":"Asked to draw the perpendicular bisector of a line segment with ruler and compasses, a Class 7 student measures the midpoint with a ruler and draws a right angle with a protractor. What should the teacher do?","options":["Mark it wrong and return the notebook to her without giving any explanation","Accept it, since the final result looks exactly the same as a construction","Ask her to use compasses and say why equidistant points lie on the bisector","Tell her that protractors must never be used at all in geometry"],"answer":2,"explanation":"Constructions are about reasoning: the compass arcs locate points equidistant from both ends, and those points lie on the perpendicular bisector. Measuring hides that reason, even if the drawing looks right.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"पैमाने और परकार से रेखाखंड का लंब-समद्विभाजक खींचने को कहे जाने पर कक्षा 7 की एक विद्यार्थी पैमाने से मध्य-बिंदु मापती है और चाँदे से समकोण बनाती है। शिक्षक को क्या करना चाहिए?","optionsHi":["इसे गलत अंकित करना और बिना कोई स्पष्टीकरण दिए उसकी कॉपी लौटा देना","इसे स्वीकार करना, क्योंकि अंतिम परिणाम रचना जैसा ही दिखता है","उससे परकार का उपयोग करने और यह बताने को कहना कि समदूरस्थ बिंदु समद्विभाजक पर क्यों होते हैं","उसे बताना कि ज्यामिति में चाँदे का कभी उपयोग नहीं करना चाहिए"],"explanationHi":"रचनाएँ तर्क के बारे में हैं: परकार की चापें वे बिंदु ढूँढती हैं जो दोनों सिरों से समदूरस्थ हैं, और वे बिंदु लंब-समद्विभाजक पर होते हैं। मापन उस कारण को छिपा देता है, भले ही आकृति सही दिखे।"},
  {"id":"cdp-pedagogy-subjects-1463","question":"A Class 7 student says that if the three angles of one triangle equal the three angles of another, the triangles must be congruent. Which response is best?","options":["Agree, since AAA is one of the accepted congruence rules","Tell her to remember only the SSS, SAS, ASA and RHS rules","Ask her to measure the angles again more carefully with a protractor","Ask her to draw two triangles with equal angles but different sizes"],"answer":3,"explanation":"Equal angles fix the shape but not the size, so AAA gives similar triangles, not congruent ones. A counterexample she draws herself is more convincing than a list of rules.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक विद्यार्थी कहती है कि यदि एक त्रिभुज के तीनों कोण दूसरे त्रिभुज के तीनों कोणों के बराबर हों, तो त्रिभुज सर्वांगसम होने चाहिए। कौन-सी प्रतिक्रिया सबसे अच्छी है?","optionsHi":["सहमत होना, क्योंकि AAA स्वीकृत सर्वांगसमता नियमों में से एक है","उसे केवल SSS, SAS, ASA और RHS नियम याद रखने को कहना","उससे चाँदे से कोण और सावधानी से दोबारा मापने को कहना","उससे बराबर कोणों पर भिन्न आकार वाले दो त्रिभुज बनाने को कहना"],"explanationHi":"बराबर कोण आकृति तय करते हैं, आकार नहीं, इसलिए AAA से समरूप त्रिभुज मिलते हैं, सर्वांगसम नहीं। जो प्रति-उदाहरण वह स्वयं बनाए वह नियमों की सूची से अधिक विश्वसनीय है।"},
  {"id":"cdp-pedagogy-subjects-1464","question":"A student uses a² + b² = c² to find a side of a triangle that has no right angle. What is the best way to address this?","options":["Have her test it on a 4, 5, 6 cm triangle and discuss when it holds","Tell her that the formula works for every triangle, whatever its angles","Ask her to memorise the formula again and write it out ten times","Tell her to use the formula only for equilateral triangles from now on"],"answer":0,"explanation":"For sides 4, 5 and 6, 16 + 25 = 41, which is not 36, so the relation fails. Testing shows the condition (a right angle) is essential, not a detail to forget.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक विद्यार्थी ऐसे त्रिभुज की भुजा निकालने के लिए a² + b² = c² का उपयोग करती है जिसमें समकोण नहीं है। इसे संबोधित करने का सबसे अच्छा तरीका क्या है?","optionsHi":["उससे 4, 5, 6 cm वाले त्रिभुज पर इसे परखवाना और चर्चा करना कि यह कब सही है","उसे बताना कि सूत्र हर त्रिभुज के लिए काम करता है, उसके कोण चाहे जो हों","उससे सूत्र को फिर याद करने और दस बार लिखने को कहना","उसे बताना कि अब से सूत्र का उपयोग केवल समबाहु त्रिभुजों के लिए करे"],"explanationHi":"भुजाओं 4, 5 और 6 के लिए, 16 + 25 = 41, जो 36 नहीं है, इसलिए संबंध विफल होता है। परखने से दिखता है कि शर्त (समकोण) आवश्यक है, भूल जाने योग्य ब्योरा नहीं।"},
  {"id":"cdp-pedagogy-subjects-1465","question":"A Class 8 student writes 2⁻³ = −8. Which approach best helps her understand negative exponents?","options":["Tell her that a negative power always gives a negative number as the answer","Continue the pattern 8, 4, 2, 1 by halving, and ask what 2⁻³ must be","Ask her to learn the rule a⁻ⁿ = 1/aⁿ by heart and apply it","Ask her to check the answer on a calculator and correct it"],"answer":1,"explanation":"Each step down divides by 2, so 2⁻³ = 1/8. The pattern makes the definition sensible; the minus sign in the power does not make the value negative.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 की एक विद्यार्थी लिखती है 2⁻³ = −8। कौन-सा उपागम उसे ऋणात्मक घातांक समझने में सबसे अच्छी मदद करता है?","optionsHi":["उसे बताना कि ऋणात्मक घात हमेशा उत्तर के रूप में ऋणात्मक संख्या देती है","8, 4, 2, 1 के प्रतिरूप को आधा करते हुए आगे बढ़ाना और पूछना कि 2⁻³ क्या होना चाहिए","उससे नियम a⁻ⁿ = 1/aⁿ कंठस्थ करने और लागू करने को कहना","उससे उत्तर कैलकुलेटर पर जाँचने और सुधारने को कहना"],"explanationHi":"नीचे के प्रत्येक चरण पर 2 से भाग देना होता है, इसलिए 2⁻³ = 1/8। प्रतिरूप परिभाषा को सार्थक बनाता है; घात में ऋण चिह्न मान को ऋणात्मक नहीं बनाता।"},
  {"id":"cdp-pedagogy-subjects-1466","question":"A student writes √(16 + 9) = √16 + √9 = 7. What is the error, and how can it be shown?","options":["She has found the square roots of 16 and 9 wrongly in her working","She should have squared the numbers instead of taking their roots","She treats roots as spreading over addition; √25 = 5 shows the error","She has added 16 and 9 wrongly before taking the square root of the sum"],"answer":2,"explanation":"√(16 + 9) = √25 = 5, not 7. Like (a + b)² = a² + b², this is an over-generalisation of the distributive law to operations where it does not hold.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक विद्यार्थी लिखती है √(16 + 9) = √16 + √9 = 7। त्रुटि क्या है, और उसे कैसे दिखाया जा सकता है?","optionsHi":["उसने अपने कार्य में 16 और 9 के वर्गमूल गलत निकाले हैं","उसे वर्गमूल लेने के बजाय संख्याओं का वर्ग करना चाहिए था","वह मूलों को योग पर बँटता मानती है; √25 = 5 त्रुटि दिखाता है","उसने योग का वर्गमूल लेने से पहले 16 और 9 को गलत जोड़ा है"],"explanationHi":"√(16 + 9) = √25 = 5, 7 नहीं। (a + b)² = a² + b² की तरह, यह वितरण-नियम का उन संक्रियाओं पर अति-सामान्यीकरण है जहाँ वह लागू नहीं होता।"},
  {"id":"cdp-pedagogy-subjects-1467","question":"The price of a book rises from ₹50 to ₹75. A student says this is a 25% increase. What is the misconception?","options":["She has divided the increase by the new price of ₹75 instead","She has calculated 25% of the new price of ₹75 and given that as the answer","She has mixed up percentage increase and percentage decrease","She took the ₹25 rise as the percentage; it is 50% of the original ₹50"],"answer":3,"explanation":"Percentage increase is the increase divided by the original amount: 25/50 = 50%. Treating the rupee change as a percentage ignores what it is a percentage of.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक किताब की कीमत ₹50 से बढ़कर ₹75 हो जाती है। एक विद्यार्थी कहती है कि यह 25% की वृद्धि है। भ्रांति क्या है?","optionsHi":["उसने वृद्धि को नई कीमत ₹75 से भाग दिया है","उसने 25% की गणना नई कीमत ₹75 पर की है और वही उत्तर दे दिया है","उसने प्रतिशत वृद्धि और प्रतिशत कमी को मिला दिया है","उसने ₹25 की वृद्धि को ही प्रतिशत ले लिया; वह मूल ₹50 का 50% है"],"explanationHi":"प्रतिशत वृद्धि वृद्धि को मूल राशि से भाग देकर निकलती है: 25/50 = 50%। रुपये के परिवर्तन को प्रतिशत मान लेना इसकी उपेक्षा करता है कि वह किसका प्रतिशत है।"},
  {"id":"cdp-pedagogy-subjects-1468","question":"A car goes 120 km to a town at 40 km/h and returns at 60 km/h. A student says the average speed is 50 km/h. What is the best response?","options":["Have her find total distance and total time (240 km, 5 h) and compare","Agree, since the simple average of 40 and 60 is 50, just as she has said","Tell her that average speed cannot be found for a journey out and back","Tell her to use the formula for the mean of two numbers instead"],"answer":0,"explanation":"The trip takes 3 hours out and 2 hours back, so the average speed is 240 ÷ 5 = 48 km/h. The car spends longer at the slower speed, so a simple mean of speeds is wrong.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"एक कार किसी कस्बे तक 120 km की दूरी 40 km/h की चाल से तय करती है और 60 km/h की चाल से लौटती है। एक विद्यार्थी कहती है कि औसत चाल 50 km/h है। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["उससे कुल दूरी और कुल समय (240 km, 5 h) निकलवाना और तुलना करवाना","सहमत होना, क्योंकि 40 और 60 का साधारण औसत 50 है, जैसा उसने कहा","उसे बताना कि आने-जाने की यात्रा के लिए औसत चाल निकाली नहीं जा सकती","उसे दो संख्याओं के माध्य का सूत्र उपयोग करने को कहना"],"explanationHi":"यात्रा में जाने में 3 घंटे और लौटने में 2 घंटे लगते हैं, इसलिए औसत चाल 240 ÷ 5 = 48 km/h है। कार धीमी चाल पर अधिक समय बिताती है, इसलिए चालों का साधारण माध्य गलत है।"},
  {"id":"cdp-pedagogy-subjects-1469","question":"A teacher cuts a paper circle into many equal sectors and arranges them alternately into a shape close to a parallelogram. What is the main purpose?","options":["To teach students how to cut paper accurately into equal sectors","To link the circle’s area to a known shape, giving a reason for πr²","To find the exact value of π by measuring the sides of the rearranged shape","To show students that a circle is really a kind of polygon"],"answer":1,"explanation":"The rearranged shape is nearly a rectangle with length half the circumference (πr) and height r, so its area is πr². It is an informal argument for the formula, not a measurement of π.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षक कागज़ के वृत्त को अनेक समान त्रिज्यखंडों में काटता है और उन्हें एकांतर क्रम में जमाकर समांतर चतुर्भुज के निकट आकृति बनाता है। मुख्य उद्देश्य क्या है?","optionsHi":["विद्यार्थियों को कागज़ को समान त्रिज्यखंडों में सटीकता से काटना सिखाना","वृत्त के क्षेत्रफल को ज्ञात आकृति से जोड़ना, जिससे πr² का कारण मिले","पुनर्व्यवस्थित आकृति की भुजाएँ मापकर π का सटीक मान ज्ञात करना","विद्यार्थियों को दिखाना कि वृत्त वास्तव में एक प्रकार का बहुभुज है"],"explanationHi":"पुनर्व्यवस्थित आकृति लगभग आयत है जिसकी लंबाई परिधि का आधा (πr) और ऊँचाई r है, इसलिए उसका क्षेत्रफल πr² है। यह सूत्र के लिए अनौपचारिक तर्क है, π का मापन नहीं।"},
  {"id":"cdp-pedagogy-subjects-1470","question":"Students count the faces, vertices and edges of many polyhedra and find that F + V − E = 2 every time. The teacher then asks them to check a solid with a hole through it, like a square picture frame. What is the teacher mainly teaching?","options":["That Euler's formula is false and should not be used for any solid at all","How to draw solids and their hidden edges on paper accurately","That rules found from examples may hold only under certain conditions","How to count the edges of complicated solids quickly"],"answer":2,"explanation":"For a solid with a hole, F + V − E = 0, so the pattern fails. Euler's formula holds for polyhedra without holes. Testing the limits of a conjecture is a key part of mathematical reasoning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"विद्यार्थी अनेक बहुफलकों के फलक, शीर्ष और किनारे गिनते हैं और पाते हैं कि हर बार F + V − E = 2 है। फिर शिक्षक उनसे छिद्र वाले ठोस, जैसे वर्गाकार चित्र-फ़्रेम, की जाँच करने को कहता है। शिक्षक मुख्यतः क्या सिखा रहा है?","optionsHi":["कि यूलर का सूत्र गलत है और किसी भी ठोस के लिए उपयोग नहीं करना चाहिए","कागज़ पर ठोसों और उनके छिपे किनारों को सटीकता से कैसे बनाएँ","कि उदाहरणों से मिले नियम केवल कुछ शर्तों के अंतर्गत ही सही हो सकते हैं","जटिल ठोसों के किनारों को शीघ्रता से कैसे गिनें"],"explanationHi":"छिद्र वाले ठोस के लिए F + V − E = 0 होता है, इसलिए प्रतिरूप विफल होता है। यूलर का सूत्र बिना छिद्र वाले बहुफलकों के लिए सही है। किसी अनुमान की सीमाओं को परखना गणितीय तर्क का मुख्य भाग है।"},
  {"id":"cdp-pedagogy-subjects-1471","question":"Assertion (A): Students should explore proportion through real contexts such as recipes and maps before learning cross-multiplication. Reason (R): Cross-multiplication is an incorrect method for solving proportions.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Cross-multiplication is a correct method; the concern is that it is used mechanically without understanding. So A is true (contexts build proportional reasoning) and R is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): विद्यार्थियों को आड़े गुणन (cross-multiplication) सीखने से पहले व्यंजनों और मानचित्रों जैसे वास्तविक संदर्भों के माध्यम से समानुपात की खोज करनी चाहिए। कारण (R): समानुपात हल करने के लिए आड़ा गुणन एक गलत विधि है।","optionsHi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है, परंतु R असत्य है","A असत्य है, परंतु R सत्य है"],"explanationHi":"आड़ा गुणन एक सही विधि है; चिंता यह है कि उसका उपयोग बिना समझ के यांत्रिक रूप से होता है। इसलिए A सत्य है (संदर्भ समानुपातिक तर्क बनाते हैं) और R असत्य है।"},
  {"id":"cdp-pedagogy-subjects-1472","question":"Which of these statements about teaching data handling are correct? I. Students should collect their own data on questions they care about. II. Drawing graphs from textbook tables is enough for data literacy. III. Interpreting and questioning graphs, including misleading ones, is part of data handling. IV. The choice of graph depends on the kind of data.","options":["I and II only","II, III and IV","I, II and IV","I, III and IV"],"answer":3,"explanation":"Data handling includes asking questions, collecting, representing and interpreting data, and choosing suitable graphs. Copying textbook tables into graphs covers only one small part, so II is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"आँकड़ा-संचालन पढ़ाने के बारे में इनमें से कौन-से कथन सही हैं? I. विद्यार्थियों को उन प्रश्नों पर अपने आँकड़े एकत्र करने चाहिए जिनकी उन्हें परवाह है। II. पाठ्यपुस्तक की तालिकाओं से आलेख बनाना आँकड़ा-साक्षरता के लिए पर्याप्त है। III. आलेखों की, भ्रामक आलेखों सहित, व्याख्या करना और उन पर प्रश्न करना आँकड़ा-संचालन का भाग है। IV. आलेख का चुनाव आँकड़ों के प्रकार पर निर्भर करता है।","optionsHi":["केवल I और II","II, III और IV","I, II और IV","I, III और IV"],"explanationHi":"आँकड़ा-संचालन में प्रश्न पूछना, एकत्र करना, निरूपित करना और आँकड़ों की व्याख्या करना, और उपयुक्त आलेख चुनना शामिल है। पाठ्यपुस्तक की तालिकाओं को आलेखों में उतारना केवल एक छोटा भाग समेटता है, इसलिए II असत्य है।"},
  {"id":"cdp-pedagogy-subjects-1473","question":"Which of the following statements fit the NCF 2005 approach to teaching history?\n1. History should help children see links between the past and the present.\n2. History should be presented as completed knowledge that students must accept.\n3. History should include the experience of different regions, not only of capital cities.\n4. Students should get some idea of how historians know what they know.","options":["1, 2 and 3 only","2, 3 and 4 only","1 and 4 only","1, 3 and 4 only"],"answer":3,"explanation":"NCF 2005 wants history linked to the present, regionally plural, and taught with a sense of how historical knowledge is built from evidence. Treating history as finished knowledge to be accepted is what it moves away from.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"इतिहास पढ़ाने के NCF 2005 उपागम के अनुरूप निम्नलिखित में से कौन-से कथन हैं?\n1. इतिहास को बच्चों को अतीत और वर्तमान के बीच संबंध देखने में मदद करनी चाहिए।\n2. इतिहास को पूर्ण ज्ञान के रूप में प्रस्तुत किया जाना चाहिए जिसे विद्यार्थियों को स्वीकार करना है।\n3. इतिहास में केवल राजधानी-नगरों का नहीं, विभिन्न क्षेत्रों का अनुभव शामिल होना चाहिए।\n4. विद्यार्थियों को कुछ अंदाज़ा होना चाहिए कि इतिहासकार जो जानते हैं वह कैसे जानते हैं।","optionsHi":["केवल 1, 2 और 3","केवल 2, 3 और 4","केवल 1 और 4","केवल 1, 3 और 4"],"explanationHi":"NCF 2005 चाहती है कि इतिहास वर्तमान से जुड़ा हो, क्षेत्रीय रूप से बहुल हो, और इस बोध के साथ पढ़ाया जाए कि ऐतिहासिक ज्ञान साक्ष्य से कैसे बनता है। इतिहास को स्वीकार किए जाने वाले तैयार ज्ञान के रूप में देखना वही है जिससे वह दूर जाती है।"},
  {"id":"cdp-pedagogy-subjects-1474","question":"Assertion (A): NCF 2005 suggests that economics at the upper primary stage be introduced through the experiences of ordinary people.\nReason (R): Economic matters have no relevance to children's lives until they become adults.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"Children already live amid buying, selling, wages and prices, which is exactly why economics can start from everyday experience. R is false, and it would actually argue against A.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): NCF 2005 सुझाती है कि उच्च प्राथमिक अवस्था में अर्थशास्त्र का परिचय आम लोगों के अनुभवों के माध्यम से दिया जाए।\nकारण (R): आर्थिक विषयों का बच्चों के जीवन से तब तक कोई संबंध नहीं होता जब तक वे वयस्क न हो जाएँ।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"explanationHi":"बच्चे पहले से ही खरीद-बिक्री, मज़दूरी और कीमतों के बीच जीते हैं, इसीलिए अर्थशास्त्र रोज़मर्रा के अनुभव से शुरू हो सकता है। R असत्य है, और वह वास्तव में A के विरुद्ध तर्क देगा।"},
  {"id":"cdp-pedagogy-subjects-1475","question":"A Class VII teacher includes the Chipko movement, in which village women in the Himalayan foothills hugged trees to stop felling, in a lesson on forests. What is the main value of this example?","options":["It proves that all forest laws made by the government are unjust","It shows ordinary people, including women, acting to protect resources","It shows that only the government can protect forests effectively","It provides an important date and place for students to memorise for the test"],"answer":1,"explanation":"Chipko shows citizens, especially women, as active agents in environmental protection. It is not a claim that all laws are unjust, and its value lies far beyond a date.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VII की एक शिक्षिका वनों पर पाठ में चिपको आंदोलन को शामिल करती है, जिसमें हिमालय की तलहटी की गाँव की महिलाओं ने पेड़ों की कटाई रोकने के लिए उनसे लिपटकर विरोध किया। इस उदाहरण का मुख्य मूल्य क्या है?","optionsHi":["यह सिद्ध करता है कि सरकार द्वारा बनाए गए सभी वन-कानून अन्यायपूर्ण हैं","यह दिखाता है कि आम लोग, महिलाओं सहित, संसाधनों की रक्षा के लिए कार्य करते हैं","यह दिखाता है कि केवल सरकार ही वनों की प्रभावी रक्षा कर सकती है","यह विद्यार्थियों को परीक्षा के लिए याद करने हेतु एक महत्त्वपूर्ण तिथि और स्थान देता है"],"explanationHi":"चिपको नागरिकों, विशेषकर महिलाओं, को पर्यावरण-संरक्षण में सक्रिय कर्ताओं के रूप में दिखाता है। यह इस बात का दावा नहीं है कि सभी कानून अन्यायपूर्ण हैं, और इसका मूल्य किसी तिथि से कहीं आगे है।"},
  {"id":"cdp-pedagogy-subjects-1476","question":"Which of the following is a divergent question for a Class VIII lesson on urban problems?","options":["In how many different ways could our town reduce its traffic jams?","Which ministry of the government is responsible for urban development?","What is the population of our town according to the last census?","Name the metro cities of India and the states they are in."],"answer":0,"explanation":"Divergent questions have many possible answers and encourage creative thinking. Convergent questions have one correct answer, such as a figure, a name or a list.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"शहरी समस्याओं पर कक्षा VIII के पाठ के लिए इनमें से कौन-सा अपसारी प्रश्न है?","optionsHi":["हमारा कस्बा अपने यातायात-जामों को कितने अलग-अलग तरीकों से कम कर सकता है?","शहरी विकास के लिए सरकार का कौन-सा मंत्रालय उत्तरदायी है?","पिछली जनगणना के अनुसार हमारे कस्बे की जनसंख्या कितनी है?","भारत के महानगरों के नाम बताइए और वे किन राज्यों में हैं।"],"explanationHi":"अपसारी प्रश्नों के अनेक संभावित उत्तर होते हैं और वे रचनात्मक चिंतन को प्रोत्साहित करते हैं। अभिसारी प्रश्नों का एक सही उत्तर होता है, जैसे आँकड़ा, नाम या सूची।"},
  {"id":"cdp-pedagogy-subjects-1477","question":"A social science teacher notices that during the mid-day meal some children are made to sit separately because of their caste. What is the most appropriate response?","options":["Ignore it, since the mid-day meal is not part of the social science period at all","Discuss the matter in class only if a parent comes and complains about it","Ask the separated children to move away quietly to avoid any conflict","Stop it, report it to the head and discuss it in class as unequal treatment"],"answer":3,"explanation":"Caste-based discrimination in school violates the Constitution and the dignity of children. The teacher must act and can use the issue to teach equality; staying silent makes the school complicit.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"एक सामाजिक विज्ञान शिक्षिका देखती है कि मध्याह्न भोजन के दौरान कुछ बच्चों को उनकी जाति के कारण अलग बिठाया जाता है। सबसे उपयुक्त प्रतिक्रिया क्या है?","optionsHi":["इसकी उपेक्षा करना, क्योंकि मध्याह्न भोजन सामाजिक विज्ञान के कालांश का हिस्सा बिल्कुल नहीं है","मामले पर कक्षा में तभी चर्चा करना जब कोई अभिभावक आकर शिकायत करे","अलग बिठाए गए बच्चों से चुपचाप हट जाने को कहना ताकि कोई संघर्ष न हो","इसे रोकना, प्रधानाध्यापक को सूचित करना और असमान व्यवहार के रूप में कक्षा में चर्चा करना"],"explanationHi":"विद्यालय में जाति-आधारित भेदभाव संविधान और बच्चों की गरिमा का उल्लंघन है। शिक्षक को कार्रवाई करनी चाहिए और इस मुद्दे का उपयोग समता सिखाने में कर सकती है; चुप रहना विद्यालय को सहभागी बना देता है।"},
  {"id":"cdp-pedagogy-subjects-1478","question":"A Class VI student says, 'India has too many languages and religions; that is why there are problems.' Which response best fits the aims of social science?","options":["Agree, since a single language and religion would make the country stronger","Tell the student not to discuss such sensitive matters in the classroom","Explore coexistence, and how prejudice rather than diversity causes conflict","Ask the student to memorise the number of languages spoken in India"],"answer":2,"explanation":"Social science aims to build respect for diversity. Exploring examples of coexistence and the role of prejudice addresses the misconception directly; silence or agreement leaves it in place.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT","questionHi":"कक्षा VI की एक विद्यार्थी कहती है, 'भारत में बहुत अधिक भाषाएँ और धर्म हैं; इसीलिए समस्याएँ हैं।' सामाजिक विज्ञान के उद्देश्यों के सबसे अनुरूप कौन-सी प्रतिक्रिया है?","optionsHi":["सहमत होना, क्योंकि एक भाषा और धर्म देश को अधिक मज़बूत बनाएगा","विद्यार्थी को बताना कि कक्षा में ऐसे संवेदनशील मामलों पर चर्चा न करे","सह-अस्तित्व की खोज करना, और यह कि संघर्ष विविधता से नहीं, पूर्वाग्रह से होता है","विद्यार्थी से भारत में बोली जाने वाली भाषाओं की संख्या याद करने को कहना"],"explanationHi":"सामाजिक विज्ञान का उद्देश्य विविधता के प्रति सम्मान बनाना है। सह-अस्तित्व के उदाहरणों और पूर्वाग्रह की भूमिका की खोज भ्रांति को सीधे संबोधित करती है; चुप्पी या सहमति उसे वैसे ही छोड़ देती है।"},
  {"id":"cdp-pedagogy-subjects-1479","question":"Class IX students compare three accounts of a 1920s textile mill strike: the management's report, a workers' union pamphlet and a newspaper article. All three agree on the date and number of workers, but they differ sharply on its causes. What should students conclude?","options":["Since the accounts disagree on the causes, none of them can be used","Agreement makes facts secure; disagreement shows the writers’ interests","The newspaper must be correct, since newspapers are always neutral observers","The union pamphlet must be correct, since the workers were the victims"],"answer":1,"explanation":"Corroboration across independent sources strengthens facts, and disagreement reveals perspective. Assuming any one type of source is automatically neutral or true is the error historians try to avoid.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा IX के विद्यार्थी 1920 के दशक की एक कपड़ा-मिल हड़ताल के तीन विवरणों की तुलना करते हैं: प्रबंधन की रिपोर्ट, श्रमिक-संघ का पर्चा और एक समाचार-पत्र का लेख। तीनों तिथि और श्रमिकों की संख्या पर सहमत हैं, पर उसके कारणों पर तीव्र रूप से भिन्न हैं। विद्यार्थियों को क्या निष्कर्ष निकालना चाहिए?","optionsHi":["चूँकि विवरण कारणों पर असहमत हैं, उनमें से किसी का उपयोग नहीं किया जा सकता","सहमति तथ्यों को सुरक्षित करती है; असहमति लेखकों के हित दिखाती है","समाचार-पत्र सही होगा, क्योंकि समाचार-पत्र हमेशा तटस्थ पर्यवेक्षक होते हैं","श्रमिक-संघ का पर्चा सही होगा, क्योंकि श्रमिक पीड़ित थे"],"explanationHi":"स्वतंत्र स्रोतों के बीच पुष्टि तथ्यों को मज़बूत करती है, और असहमति दृष्टिकोण प्रकट करती है। यह मान लेना कि किसी एक प्रकार का स्रोत अपने आप तटस्थ या सत्य है, वही त्रुटि है जिससे इतिहासकार बचना चाहते हैं।"},
  {"id":"cdp-pedagogy-subjects-1480","question":"Class IX students notice that the rainfall map and the population density map of India look broadly similar, and conclude that rainfall alone decides where people live. What should the teacher do next?","options":["Have them look for exceptions, like rainy hills with few people","Confirm the conclusion, since the two maps match closely in most places","Tell them that two maps of different things cannot be compared at all","Ask them to memorise the population density of each state for the test"],"answer":0,"explanation":"Patterns across maps are a good start, but exceptions such as the high-rainfall, thinly populated hills of the north-east show that several factors work together. Hunting for exceptions refines a hasty generalisation.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा IX के विद्यार्थी देखते हैं कि भारत का वर्षा-मानचित्र और जनसंख्या-घनत्व मानचित्र मोटे तौर पर समान दिखते हैं, और निष्कर्ष निकालते हैं कि लोग कहाँ रहते हैं यह केवल वर्षा तय करती है। शिक्षक को आगे क्या करना चाहिए?","optionsHi":["उनसे अपवाद खोजने को कहना, जैसे कम लोगों वाली वर्षा-बहुल पहाड़ियाँ","निष्कर्ष की पुष्टि करना, क्योंकि दोनों मानचित्र अधिकांश स्थानों में निकट रूप से मेल खाते हैं","उन्हें बताना कि अलग-अलग चीज़ों के दो मानचित्रों की तुलना बिल्कुल नहीं हो सकती","उनसे परीक्षा के लिए प्रत्येक राज्य का जनसंख्या-घनत्व याद करने को कहना"],"explanationHi":"मानचित्रों में प्रतिरूप अच्छी शुरुआत हैं, पर पूर्वोत्तर की अधिक वर्षा वाली, विरल आबादी की पहाड़ियों जैसे अपवाद दिखाते हैं कि कई कारक साथ काम करते हैं। अपवाद खोजना जल्दबाज़ी के सामान्यीकरण को परिष्कृत करता है।"},
  {"id":"cdp-pedagogy-subjects-1481","question":"A Class VII teacher reads aloud a story about an Adivasi girl whose family struggles to keep its land. What is the main purpose of using such literature in social science?","options":["To replace the difficult chapter with a story that is easier for students to follow","To improve students' reading speed and pronunciation in class","To build empathy with the human side of an issue the chapter then examines","To give students a clear moral at the end that they can memorise"],"answer":2,"explanation":"Stories let students feel an issue from the inside, which motivates analysis of its causes in the chapter. They complement concepts rather than replace them.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS","questionHi":"कक्षा VII की एक शिक्षिका एक आदिवासी लड़की की कहानी ज़ोर से पढ़ती है जिसका परिवार अपनी ज़मीन बचाने के लिए संघर्ष करता है। सामाजिक विज्ञान में ऐसे साहित्य के उपयोग का मुख्य उद्देश्य क्या है?","optionsHi":["कठिन अध्याय की जगह ऐसी कहानी रखना जिसे विद्यार्थी अधिक आसानी से समझ सकें","कक्षा में विद्यार्थियों की पठन-गति और उच्चारण सुधारना","अध्याय जिस मुद्दे की जाँच करता है उसके मानवीय पक्ष के साथ सहानुभूति बनाना","विद्यार्थियों को अंत में स्पष्ट नैतिक शिक्षा देना जिसे वे याद कर सकें"],"explanationHi":"कहानियाँ विद्यार्थियों को किसी मुद्दे को भीतर से महसूस करने देती हैं, जो अध्याय में उसके कारणों के विश्लेषण को प्रेरित करता है। वे संकल्पनाओं की पूरक हैं, उनकी जगह नहीं लेतीं।"},
  {"id":"cdp-pedagogy-subjects-1482","question":"Which description best fits the role of the social science teacher according to NCF 2005?","options":["A facilitator who helps students inquire, discuss and build understanding","The sole source of correct information that students must accept","A supervisor who ensures that students copy notes accurately and neatly","An examiner whose main task is to prepare students for the board examinations"],"answer":0,"explanation":"NCF 2005 sees the teacher as a facilitator of learning who designs experiences and guides inquiry, not as the only authority or a transmitter of notes.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"NCF 2005 के अनुसार सामाजिक विज्ञान शिक्षक की भूमिका का कौन-सा वर्णन सबसे उपयुक्त है?","optionsHi":["सुगमकर्ता जो विद्यार्थियों को जिज्ञासा-आधारित अन्वेषण, चर्चा और समझ बनाने में मदद करता है","सही जानकारी का एकमात्र स्रोत जिसे विद्यार्थियों को स्वीकार करना है","पर्यवेक्षक जो सुनिश्चित करता है कि विद्यार्थी नोट्स सटीकता और साफ़ाई से उतारें","परीक्षक जिसका मुख्य कार्य विद्यार्थियों को बोर्ड परीक्षाओं के लिए तैयार करना है"],"explanationHi":"NCF 2005 शिक्षक को अधिगम का सुगमकर्ता मानती है जो अनुभव डिज़ाइन करता और जिज्ञासा-आधारित अन्वेषण का मार्गदर्शन करता है, एकमात्र अधिकार या नोट्स का प्रेषक नहीं।"},
  {"id":"cdp-pedagogy-subjects-1483","question":"Assertion (A): Thematic maps, such as rainfall maps, use shades or colours to show variation across an area.\nReason (R): The equator is the line of latitude at 0°.","options":["Both A and R are true and R is the correct explanation of A","A is false but R is true","A is true but R is false","Both A and R are true but R is not the correct explanation of A"],"answer":3,"explanation":"Both statements are correct facts, but the position of the equator has nothing to do with why thematic maps use shading. R therefore does not explain A.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · DSSSB","questionHi":"अभिकथन (A): वर्षा-मानचित्र जैसे विषयगत मानचित्र किसी क्षेत्र में विविधता दिखाने के लिए छायाओं या रंगों का उपयोग करते हैं।\nकारण (R): विषुवत रेखा 0° की अक्षांश रेखा है।","optionsHi":["A और R दोनों सत्य हैं और R, A की सही व्याख्या है","A असत्य है परंतु R सत्य है","A सत्य है परंतु R असत्य है","A और R दोनों सत्य हैं परंतु R, A की सही व्याख्या नहीं है"],"explanationHi":"दोनों कथन सही तथ्य हैं, पर विषुवत रेखा की स्थिति का इससे कोई संबंध नहीं कि विषयगत मानचित्र छायांकन क्यों उपयोग करते हैं। इसलिए R, A की व्याख्या नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-1484","question":"A Class X teacher shows data in which the child sex ratio is much lower in some states than in others and asks students to explain the difference. How should the teacher guide the discussion?","options":["Tell students that the difference is natural and needs no further explanation","Link the data to son preference and sex-selection, discussing them sensitively","Ask students to memorise the sex ratio of each state for the exam","Avoid the topic altogether, since it is too sensitive for Class X students"],"answer":1,"explanation":"Data become meaningful when linked to social causes; here, gender discrimination before birth. Sensitive, informed discussion builds awareness, while avoidance or rote figures lose the point.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा X की एक शिक्षिका आँकड़े दिखाती है जिनमें कुछ राज्यों में बाल लिंगानुपात दूसरों से बहुत कम है और विद्यार्थियों से अंतर समझाने को कहती है। शिक्षिका को चर्चा का मार्गदर्शन कैसे करना चाहिए?","optionsHi":["विद्यार्थियों को बताना कि अंतर स्वाभाविक है और उसे आगे समझाने की आवश्यकता नहीं","आँकड़ों को पुत्र-वरीयता और लिंग-चयन से जोड़ना, संवेदनशीलता से चर्चा करते हुए","विद्यार्थियों से परीक्षा के लिए प्रत्येक राज्य का लिंगानुपात याद करने को कहना","विषय से पूरी तरह बचना, क्योंकि यह कक्षा X के विद्यार्थियों के लिए बहुत संवेदनशील है"],"explanationHi":"आँकड़े तब सार्थक बनते हैं जब सामाजिक कारणों से जुड़ें; यहाँ, जन्म से पहले का लैंगिक भेदभाव। संवेदनशील, सुविज्ञ चर्चा जागरूकता बनाती है, जबकि बचना या रटे आँकड़े मुद्दा खो देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1485","question":"Class IX students visit the local ration shop, record which items are available and at what prices, and talk to card holders. Which topic does this activity best support?","options":["Food security and the public distribution system","Foreign trade and the balance of payments","The history of agriculture and farming in ancient India","International organisations such as the WTO"],"answer":0,"explanation":"A ration shop is where the public distribution system meets people. Observing it and talking to card holders gives first-hand understanding of food security and its problems.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा IX के विद्यार्थी स्थानीय राशन-दुकान जाते हैं, दर्ज करते हैं कि कौन-सी वस्तुएँ किस कीमत पर उपलब्ध हैं, और कार्डधारकों से बात करते हैं। यह गतिविधि किस विषय का सबसे अच्छा समर्थन करती है?","optionsHi":["खाद्य सुरक्षा और सार्वजनिक वितरण प्रणाली","विदेशी व्यापार और भुगतान-संतुलन","प्राचीन भारत में कृषि और खेती का इतिहास","WTO जैसे अंतर्राष्ट्रीय संगठन"],"explanationHi":"राशन की दुकान वह जगह है जहाँ सार्वजनिक वितरण प्रणाली लोगों से मिलती है। उसका अवलोकन करना और कार्डधारकों से बात करना खाद्य सुरक्षा और उसकी समस्याओं की प्रत्यक्ष समझ देता है।"},
  {"id":"cdp-pedagogy-subjects-1486","question":"A Class VIII teacher shows how a textbook from the 1960s and a recent textbook describe the same historical event differently. What is the main learning?","options":["Old textbooks were wrong and should be ignored by students today","The newer textbook is always right because it is more recent","Historical writing changes as new evidence and questions emerge","History cannot be studied seriously, since it keeps changing"],"answer":2,"explanation":"Comparing textbooks shows that history is an ongoing interpretation shaped by evidence and by the questions of each generation. Neither 'old means wrong' nor 'new means right' follows.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा VIII का एक शिक्षक दिखाता है कि 1960 के दशक की पाठ्यपुस्तक और हाल की पाठ्यपुस्तक एक ही ऐतिहासिक घटना का वर्णन अलग-अलग ढंग से कैसे करती हैं। मुख्य अधिगम क्या है?","optionsHi":["पुरानी पाठ्यपुस्तकें गलत थीं और विद्यार्थियों को आज उनकी उपेक्षा करनी चाहिए","नई पाठ्यपुस्तक हमेशा सही है क्योंकि वह अधिक हाल की है","नए साक्ष्य और प्रश्न उभरने पर ऐतिहासिक लेखन बदलता है","इतिहास का गंभीरता से अध्ययन नहीं हो सकता, क्योंकि वह बदलता रहता है"],"explanationHi":"पाठ्यपुस्तकों की तुलना दिखाती है कि इतिहास साक्ष्य और प्रत्येक पीढ़ी के प्रश्नों से आकार लेने वाली निरंतर व्याख्या है। न 'पुराना यानी गलत' और न 'नया यानी सही' निकलता है।"},
  {"id":"cdp-pedagogy-subjects-1487","question":"A Class VII teacher asks, 'Who built the Taj Mahal?' Students reply, 'Shah Jahan.' She then asks, 'Did Shah Jahan cut and carry the marble?' What is she trying to bring out?","options":["That Shah Jahan did not actually order the monument to be built at all","That the answer given in the textbook is wrong and must be corrected","That monuments should not be studied in history at all, only rulers","That the many artisans and labourers, rarely named, also made history"],"answer":3,"explanation":"The question shifts attention from the patron to the workers whose labour made the monument, a 'history from below' perspective. It does not deny Shah Jahan's role as the patron.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VII की एक शिक्षिका पूछती है, 'ताजमहल किसने बनवाया?' विद्यार्थी उत्तर देते हैं, 'शाहजहाँ ने।' फिर वह पूछती है, 'क्या शाहजहाँ ने संगमरमर काटा और ढोया?' वह क्या उजागर करने की कोशिश कर रही है?","optionsHi":["कि शाहजहाँ ने वास्तव में स्मारक बनवाने का आदेश बिल्कुल नहीं दिया था","कि पाठ्यपुस्तक में दिया उत्तर गलत है और उसे सुधारना चाहिए","कि स्मारकों का इतिहास में अध्ययन नहीं होना चाहिए, केवल शासकों का","कि अनेक कारीगरों और श्रमिकों ने, जिनके नाम शायद ही मिलते हैं, भी इतिहास बनाया"],"explanationHi":"यह प्रश्न ध्यान संरक्षक से उन श्रमिकों की ओर ले जाता है जिनके श्रम से स्मारक बना, यह 'नीचे से इतिहास' का दृष्टिकोण है। यह संरक्षक के रूप में शाहजहाँ की भूमिका को नकारता नहीं।"},
  {"id":"cdp-pedagogy-subjects-1488","question":"Class IX students read extracts from the Constituent Assembly debates in which members argued over the national language. What is the main learning?","options":["That the Constitution was copied from other countries without debate","That members of the Assembly agreed on everything right from the very start","That the Constitution emerged from debate, disagreement and compromise","That language has never been an important issue in Indian politics"],"answer":2,"explanation":"Primary debate extracts show that constitutional provisions were argued over and negotiated, a model of democratic deliberation. This counters the idea that the Constitution was simply handed down or copied.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा IX के विद्यार्थी संविधान सभा की बहसों के अंश पढ़ते हैं जिनमें सदस्य राष्ट्रभाषा पर तर्क-वितर्क करते हैं। मुख्य अधिगम क्या है?","optionsHi":["कि संविधान बिना बहस के अन्य देशों से नकल किया गया था","कि सभा के सदस्य शुरू से ही हर बात पर सहमत थे","कि संविधान बहस, असहमति और समझौते से उभरा","कि भाषा भारतीय राजनीति में कभी महत्त्वपूर्ण मुद्दा नहीं रही"],"explanationHi":"प्राथमिक बहस के अंश दिखाते हैं कि संवैधानिक प्रावधानों पर तर्क-वितर्क और वार्ता हुई, जो लोकतांत्रिक विचार-विमर्श का आदर्श है। यह इस विचार का खंडन करता है कि संविधान बस सौंपा गया या नकल किया गया।"},
  {"id":"cdp-pedagogy-subjects-1489","question":"A Class VIII teacher wants to show students the stages through which a bill becomes a law. Which visual aid is most suitable?","options":["A pie chart","A flow chart","A bar graph","A timeline of Indian history"],"answer":1,"explanation":"A flow chart shows a sequence of steps and decision points, which matches the passage of a bill through the Houses and the President's assent. Pie charts and bar graphs show quantities.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VIII का एक शिक्षक विद्यार्थियों को वे चरण दिखाना चाहता है जिनसे कोई विधेयक कानून बनता है। कौन-सा दृश्य साधन सबसे उपयुक्त है?","optionsHi":["वृत्त-आरेख (pie chart)","प्रवाह-चार्ट (flow chart)","स्तंभ-आलेख","भारतीय इतिहास की समय-रेखा"],"explanationHi":"प्रवाह-चार्ट चरणों और निर्णय-बिंदुओं का क्रम दिखाता है, जो विधेयक के सदनों से गुज़रने और राष्ट्रपति की स्वीकृति से मेल खाता है। वृत्त-आरेख और स्तंभ-आलेख मात्राएँ दिखाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1490","question":"Which kinds of questions should a social science test avoid?\n1. Questions that reward reproducing textbook lines\n2. Questions that ask students to evaluate a source\n3. Questions that assume experiences only some students have had","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":2,"explanation":"Questions that reward reproduction encourage rote learning, and questions that assume particular experiences are unfair. Evaluating a source is a valuable higher-order task that tests should include.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS","questionHi":"सामाजिक विज्ञान की परीक्षा में किस प्रकार के प्रश्नों से बचना चाहिए?\n1. ऐसे प्रश्न जो पाठ्यपुस्तक की पंक्तियों को पुनः प्रस्तुत करने को पुरस्कृत करते हैं\n2. ऐसे प्रश्न जो विद्यार्थियों से किसी स्रोत का मूल्यांकन करने को कहते हैं\n3. ऐसे प्रश्न जो ऐसे अनुभव मानकर चलते हैं जो केवल कुछ विद्यार्थियों को हुए हैं","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"जो प्रश्न पुनः प्रस्तुति को पुरस्कृत करते हैं वे रटंत अधिगम को प्रोत्साहित करते हैं, और जो प्रश्न विशेष अनुभव मानकर चलते हैं वे अनुचित हैं। स्रोत का मूल्यांकन एक मूल्यवान उच्च-स्तरीय कार्य है जिसे परीक्षाओं में शामिल करना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1491","question":"A Class VI teacher ends every social science lesson with a moral such as 'We must always obey our elders.' Which critique is most in line with NCF 2005?","options":["Values should be discussed against ideals like justice, not preached","Values have no place at all in social science, which deals only with facts","She should give more morals per lesson so that students remember them","Morals should be taught only in the language class, through stories"],"answer":0,"explanation":"NCF 2005 gives social science a normative role, but through engagement with values, not preaching. An unexamined moral such as unconditional obedience can even conflict with ideas of rights and justice.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा VI की एक शिक्षिका हर सामाजिक विज्ञान पाठ का अंत 'हमें हमेशा बड़ों की आज्ञा माननी चाहिए' जैसी नैतिक शिक्षा से करती है। NCF 2005 के सबसे अनुरूप आलोचना कौन-सी है?","optionsHi":["मूल्यों पर न्याय जैसे आदर्शों के विरुद्ध चर्चा होनी चाहिए, उपदेश नहीं","सामाजिक विज्ञान में मूल्यों का कोई स्थान नहीं है, जो केवल तथ्यों से संबंधित है","उसे प्रति पाठ और अधिक नैतिक शिक्षाएँ देनी चाहिए ताकि विद्यार्थी याद रखें","नैतिक शिक्षाएँ केवल भाषा की कक्षा में कहानियों के माध्यम से पढ़ाई जानी चाहिए"],"explanationHi":"NCF 2005 सामाजिक विज्ञान को मानकीय भूमिका देती है, पर मूल्यों से जुड़ाव के माध्यम से, उपदेश से नहीं। बिना जाँची गई नैतिक शिक्षा, जैसे बिना शर्त आज्ञाकारिता, अधिकारों और न्याय के विचारों से टकरा भी सकती है।"},
  {"id":"cdp-pedagogy-subjects-1492","question":"To teach equality in Class VIII, students survey their own school for ramps, accessible toilets and materials for students with disabilities, and write to the principal with suggestions. What is the main value of this activity?","options":["It replaces the need to read the chapter on equality in the textbook","It shows students that equality applies only to matters of caste and gender","It ensures that the school receives more funds from the government","It extends equality to persons with disabilities and links it to action"],"answer":3,"explanation":"The audit makes equality concrete, widens it to disability, and gives students a constructive civic action. Equality is not limited to caste and gender.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"कक्षा VIII में समता सिखाने के लिए विद्यार्थी अपने विद्यालय में ढलान-मार्गों (ramps), सुगम शौचालयों और दिव्यांग विद्यार्थियों के लिए सामग्री का सर्वेक्षण करते हैं और सुझावों के साथ प्रधानाचार्य को पत्र लिखते हैं। इस गतिविधि का मुख्य मूल्य क्या है?","optionsHi":["यह पाठ्यपुस्तक में समता के अध्याय को पढ़ने की आवश्यकता को समाप्त कर देती है","यह विद्यार्थियों को दिखाती है कि समता केवल जाति और लिंग के मामलों पर लागू होती है","यह सुनिश्चित करती है कि विद्यालय को सरकार से अधिक धन मिले","यह समता को दिव्यांगजनों तक विस्तृत करती है और उसे कार्रवाई से जोड़ती है"],"explanationHi":"यह लेखा-परीक्षण (audit) समता को मूर्त बनाता है, उसे दिव्यांगता तक व्यापक करता है, और विद्यार्थियों को रचनात्मक नागरिक कार्रवाई देता है। समता जाति और लिंग तक सीमित नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1493","question":"Class X students struggle with words like 'sovereign', 'subsidy' and 'federal'. Which strategy builds understanding best?","options":["Give a glossary of all the terms for students to memorise before the chapter","Introduce each term in real contexts and have students use it in sentences","Avoid using these difficult terms in class until the board exam","Ask students to look up each of the words in a good dictionary at home"],"answer":1,"explanation":"Subject vocabulary is learnt by meeting and using words in context. A glossary or dictionary definition alone gives labels without understanding, and avoiding the terms leaves students unable to read the discipline.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा X के विद्यार्थी 'संप्रभु', 'सब्सिडी' और 'संघीय' जैसे शब्दों से जूझते हैं। कौन-सी रणनीति समझ को सबसे अच्छी तरह बनाती है?","optionsHi":["अध्याय से पहले विद्यार्थियों को याद करने के लिए सभी शब्दों की शब्दावली-सूची देना","प्रत्येक शब्द को वास्तविक संदर्भों में प्रस्तुत करना और विद्यार्थियों से वाक्यों में उसका उपयोग करवाना","बोर्ड परीक्षा तक कक्षा में इन कठिन शब्दों का उपयोग टालना","विद्यार्थियों से घर पर किसी अच्छे शब्दकोश में प्रत्येक शब्द देखने को कहना"],"explanationHi":"विषय की शब्दावली संदर्भ में शब्दों से मिलने और उनका प्रयोग करने से सीखी जाती है। केवल शब्दावली-सूची या शब्दकोश की परिभाषा समझ के बिना नामपट्टिकाएँ देती है, और शब्दों से बचना विद्यार्थियों को विषय पढ़ने में असमर्थ छोड़ देता है।"},
  {"id":"cdp-pedagogy-subjects-1494","question":"A teacher plans a Class X debate on the motion 'Industrialisation was good for India'. Which change would most improve the thinking it produces?","options":["Allow only the class toppers to speak, so that the arguments are of high quality","Give marks to the side with more speakers, to encourage participation","Reframe it as ‘For whom, and at what cost, did industrialisation bring change?’","Hold the debate without any preparation, so the arguments are spontaneous"],"answer":2,"explanation":"A yes-or-no motion forces a binary that hides complexity. Asking who gained, who lost and at what cost pushes students to weigh evidence about different groups.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"एक शिक्षक कक्षा X की बहस की योजना बनाता है जिसका प्रस्ताव है 'औद्योगीकरण भारत के लिए अच्छा था'। कौन-सा परिवर्तन उसके द्वारा उत्पन्न चिंतन को सबसे अधिक सुधारेगा?","optionsHi":["केवल कक्षा के टॉपरों को बोलने देना, ताकि तर्क उच्च गुणवत्ता के हों","अधिक वक्ताओं वाले पक्ष को अंक देना, भागीदारी को प्रोत्साहित करने के लिए","इसे इस रूप में पुनः गढ़ना: 'औद्योगीकरण ने किसके लिए, और किस कीमत पर, परिवर्तन लाया?'","बहस को बिना किसी तैयारी के कराना, ताकि तर्क सहज हों"],"explanationHi":"हाँ-या-नहीं का प्रस्ताव द्विआधारी स्थिति थोपता है जो जटिलता छिपाता है। किसे लाभ हुआ, किसे हानि और किस कीमत पर, यह पूछना विद्यार्थियों को विभिन्न समूहों के साक्ष्य तौलने की ओर धकेलता है।"},
  {"id":"cdp-pedagogy-subjects-1495","question":"Class VIII students compare satellite maps of their city from 1995 and 2020 and mark where farmland and lakes have turned into housing. What does this mainly develop?","options":["Reasoning about change in land use over space and time","Memory of the city's ward numbers and their boundaries","Skills in drawing buildings and roads accurately to scale","Knowledge of the history of satellites and space research"],"answer":0,"explanation":"Comparing maps from two dates combines spatial and temporal thinking and raises questions about why land use changed and with what effects.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VIII के विद्यार्थी अपने शहर के 1995 और 2020 के उपग्रह-मानचित्रों की तुलना करते हैं और चिह्नित करते हैं कि कहाँ खेत और झीलें आवासों में बदल गई हैं। यह मुख्यतः क्या विकसित करता है?","optionsHi":["स्थान और समय में भूमि-उपयोग के परिवर्तन पर तर्क करना","शहर के वार्ड-क्रमांकों और उनकी सीमाओं की स्मृति","पैमाने के अनुसार इमारतों और सड़कों को सटीकता से बनाने का कौशल","उपग्रहों और अंतरिक्ष अनुसंधान के इतिहास का ज्ञान"],"explanationHi":"दो तिथियों के मानचित्रों की तुलना स्थानिक और कालिक चिंतन को जोड़ती है और यह प्रश्न उठाती है कि भूमि-उपयोग क्यों बदला और किन प्रभावों के साथ।"},
  {"id":"cdp-pedagogy-subjects-1496","question":"Which of the following is a secondary source for a Class VI student studying the Mauryas?","options":["An inscription of Ashoka carved on a rock or pillar","A punch-marked silver coin from the Mauryan period","A pottery fragment dug up at a Mauryan site","A chapter on the Mauryas in a present-day textbook"],"answer":3,"explanation":"Inscriptions, coins and pottery come from the period itself and are primary. A present-day textbook chapter interprets those sources and is therefore secondary.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"मौर्यों का अध्ययन करने वाले कक्षा VI के विद्यार्थी के लिए इनमें से कौन-सा द्वितीयक स्रोत है?","optionsHi":["चट्टान या स्तंभ पर खुदा अशोक का अभिलेख","मौर्य काल का आहत (punch-marked) चाँदी का सिक्का","मौर्य स्थल पर खुदाई में मिला मिट्टी के बर्तन का टुकड़ा","आज की पाठ्यपुस्तक में मौर्यों पर एक अध्याय"],"explanationHi":"अभिलेख, सिक्के और बर्तन उसी काल से आते हैं और प्राथमिक हैं। आज की पाठ्यपुस्तक का अध्याय उन स्रोतों की व्याख्या करता है, इसलिए द्वितीयक है।"},
  {"id":"cdp-pedagogy-subjects-1497","question":"While teaching a Class IX chapter on pastoralists, the teacher learns that Irfan's family are Bakarwal herders who migrate seasonally. When she asks him to tell the class about it, he looks down and stays silent. What should she do?","options":["Insist that he speak now, since his experience is so valuable for the lesson","Offer choices, like sharing later or in writing, and value his knowledge","Assume he knows nothing about it and move on to the next student","Tell the class about his family’s way of life herself, on his behalf"],"answer":1,"explanation":"Children from marginalised communities may hesitate to be singled out. Offering choices respects his agency while showing that his community's knowledge matters; speaking for him or forcing him can expose him to embarrassment.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा IX के पशुचारकों पर अध्याय को पढ़ाते समय शिक्षिका को पता चलता है कि इरफ़ान का परिवार बकरवाल चरवाहे हैं जो ऋतु के अनुसार प्रवास करते हैं। जब वह उससे कक्षा को इसके बारे में बताने को कहती है, तो वह नीचे देखता है और चुप रहता है। उसे क्या करना चाहिए?","optionsHi":["आग्रह करना कि वह अभी बोले, क्योंकि उसका अनुभव पाठ के लिए बहुत मूल्यवान है","विकल्प देना, जैसे बाद में या लिखकर साझा करना, और उसके ज्ञान को महत्त्व देना","मान लेना कि वह इसके बारे में कुछ नहीं जानता और अगले विद्यार्थी पर बढ़ जाना","उसकी ओर से स्वयं कक्षा को उसके परिवार की जीवन-शैली के बारे में बताना"],"explanationHi":"हाशिए के समुदायों के बच्चे अलग से चिह्नित किए जाने में हिचक सकते हैं। विकल्प देना उसकी स्वायत्तता का सम्मान करता है और दिखाता है कि उसके समुदाय का ज्ञान मायने रखता है; उसकी ओर से बोलना या उसे बाध्य करना उसे शर्मिंदगी के सामने ला सकता है।"},
  {"id":"cdp-pedagogy-subjects-1498","question":"A Class VIII teacher takes the theme of water first at the level of the students' own mohalla, then the state, then the country and finally the world. What is the main value of studying one theme at these different scales?","options":["It shows how one issue differs across scales and how places connect","Students can then avoid studying their own region in great detail","It reduces the total number of themes that students have to learn","It makes social science the same as science, which uses scales too"],"answer":0,"explanation":"Moving from local water use to national and global questions shows the connection between scales and places, a central idea in geography. It neither skips the local nor merely cuts content.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा VIII का एक शिक्षक जल की विषयवस्तु को पहले विद्यार्थियों के अपने मोहल्ले के स्तर पर, फिर राज्य, फिर देश और अंत में विश्व के स्तर पर लेता है। इन विभिन्न पैमानों पर एक विषयवस्तु का अध्ययन करने का मुख्य मूल्य क्या है?","optionsHi":["यह दिखाता है कि एक मुद्दा पैमानों के पार कैसे भिन्न होता है और स्थान कैसे जुड़ते हैं","तब विद्यार्थी अपने क्षेत्र का विस्तार से अध्ययन करने से बच सकते हैं","यह विद्यार्थियों को सीखने वाली कुल विषयवस्तुओं की संख्या घटाता है","यह सामाजिक विज्ञान को विज्ञान जैसा बना देता है, जो पैमाने भी उपयोग करता है"],"explanationHi":"स्थानीय जल-उपयोग से राष्ट्रीय और वैश्विक प्रश्नों की ओर बढ़ना पैमानों और स्थानों के बीच संबंध दिखाता है, जो भूगोल का केंद्रीय विचार है। यह न स्थानीय को छोड़ता है, न केवल सामग्री घटाता है।"},
  {"id":"cdp-pedagogy-subjects-1499","question":"Midway through a Class V lesson on fractions, Ms Iyer sees puzzled faces when she uses a pizza example, so she immediately switches to folding paper strips, which the children know well. In Donald Schön's terms, this is:","options":["Reflection-on-action","Reflection-for-action","Reflection-in-action","Critical incident analysis"],"answer":2,"explanation":"Reflection-in-action is thinking on one's feet and adjusting during the activity itself. Reflection-on-action happens afterwards, looking back on what happened.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा V के भिन्न पर पाठ के बीच में सुश्री अय्यर पिज़्ज़ा का उदाहरण देने पर उलझे चेहरे देखती हैं, इसलिए वह तुरंत काग़ज़ की पट्टियाँ मोड़ने पर आ जाती हैं, जिन्हें बच्चे अच्छी तरह जानते हैं। डोनाल्ड शॉन की शब्दावली में यह है:","optionsHi":["कार्रवाई-पश्चात चिंतन (reflection-on-action)","कार्रवाई-पूर्व चिंतन (reflection-for-action)","कार्रवाई के दौरान चिंतन (reflection-in-action)","महत्त्वपूर्ण घटना-विश्लेषण"],"explanationHi":"कार्रवाई के दौरान चिंतन का अर्थ है मौके पर सोचना और गतिविधि के दौरान ही समायोजन करना। कार्रवाई-पश्चात चिंतन बाद में होता है, जो जो हुआ उस पर पीछे मुड़कर देखना है।"},
  {"id":"cdp-pedagogy-subjects-1500","question":"To understand how her teaching is experienced, a Class VIII teacher asks students to write anonymously at the end of each week: 'When were you most engaged this week? When did you feel most confused?' In Stephen Brookfield's framework of critical reflection, she is using which lens?","options":["The autobiographical lens (her own experience as a learner)","The students' eyes lens","The colleagues' perceptions lens","The theoretical literature lens"],"answer":1,"explanation":"Brookfield's four lenses are the teacher's own autobiography, students' eyes, colleagues' perceptions and theory or research. Anonymous student feedback is the students' lens.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"यह समझने के लिए कि उसका शिक्षण कैसे अनुभव किया जाता है, कक्षा VIII की एक शिक्षिका विद्यार्थियों से प्रत्येक सप्ताह के अंत में गुमनाम रूप से लिखने को कहती है: 'इस सप्ताह तुम कब सबसे अधिक संलग्न थे? कब तुम्हें सबसे अधिक भ्रम हुआ?' स्टीफ़न ब्रुकफ़ील्ड की आलोचनात्मक चिंतन की रूपरेखा में, वह किस लेंस का उपयोग कर रही है?","optionsHi":["आत्मकथात्मक लेंस (अधिगमकर्ता के रूप में उसका अपना अनुभव)","विद्यार्थियों की आँखों का लेंस","सहकर्मियों की धारणाओं का लेंस","सैद्धांतिक साहित्य का लेंस"],"explanationHi":"ब्रुकफ़ील्ड के चार लेंस हैं: शिक्षक की अपनी आत्मकथा, विद्यार्थियों की आँखें, सहकर्मियों की धारणाएँ, और सिद्धांत या शोध। गुमनाम विद्यार्थी प्रतिपुष्टि विद्यार्थियों का लेंस है।"},
  {"id":"cdp-pedagogy-subjects-1501","question":"A Class VI teacher notices that many students do not participate in English speaking activities. She tries pair work before whole-class speaking for three weeks, records how many students speak, and then reflects on the results. According to the action research cycle, what should she do next?","options":["Present the findings as a universal rule that all schools should adopt for English speaking","Stop the study, since one completed cycle of action research gives a final, settled answer","Return to her original method, since three weeks is far too short a time to show any change","Revise the plan using what she learnt and begin a new cycle of action and observation"],"answer":3,"explanation":"Action research is cyclical: plan, act, observe, reflect, and then re-plan. Its findings improve the teacher's own context rather than becoming universal laws.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा VI की एक शिक्षिका देखती है कि बहुत से विद्यार्थी अंग्रेज़ी बोलने की गतिविधियों में भाग नहीं लेते। वह तीन सप्ताह तक पूरी कक्षा के सामने बोलवाने से पहले जोड़ी में कार्य करवाती है, कितने विद्यार्थी बोलते हैं इसका रिकॉर्ड रखती है, और फिर परिणामों पर चिंतन करती है। क्रियात्मक अनुसंधान चक्र के अनुसार उसे आगे क्या करना चाहिए?","optionsHi":["निष्कर्षों को एक सार्वभौमिक नियम के रूप में प्रस्तुत करे कि सभी विद्यालय अंग्रेज़ी बोलने के लिए इसे अपनाएँ","अध्ययन रोक दे, क्योंकि क्रियात्मक अनुसंधान का एक पूरा चक्र अंतिम और निश्चित उत्तर दे देता है","अपनी पुरानी विधि पर लौट जाए, क्योंकि तीन सप्ताह कोई बदलाव दिखाने के लिए बहुत कम समय है","जो सीखा उसके आधार पर योजना को संशोधित करे और क्रिया तथा अवलोकन का नया चक्र शुरू करे"],"explanationHi":"क्रियात्मक अनुसंधान चक्रीय होता है: योजना, क्रिया, अवलोकन, चिंतन और फिर पुनः योजना। इसके निष्कर्ष शिक्षक के अपने संदर्भ को बेहतर बनाते हैं, वे सार्वभौमिक नियम नहीं बन जाते।"},
  {"id":"cdp-pedagogy-subjects-1502","question":"Consider the following statements about action research by teachers: 1. It is carried out by practitioners to improve their own practice in their own setting. 2. Its main aim is to produce general laws that apply to all classrooms. 3. It usually proceeds in cycles of planning, acting, observing and reflecting. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Action research is practical, local and cyclical; it seeks improvement in a particular classroom rather than generalisable laws, so statement 2 is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"शिक्षकों द्वारा किए जाने वाले क्रियात्मक अनुसंधान के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह व्यवसायी (शिक्षक) द्वारा अपने ही परिवेश में अपनी कार्य-पद्धति सुधारने के लिए किया जाता है। 2. इसका मुख्य उद्देश्य ऐसे सामान्य नियम बनाना है जो सभी कक्षाओं पर लागू हों। 3. यह प्रायः योजना बनाने, क्रिया करने, अवलोकन करने और चिंतन करने के चक्रों में चलता है। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"क्रियात्मक अनुसंधान व्यावहारिक, स्थानीय और चक्रीय होता है; यह सामान्यीकरण योग्य नियमों के बजाय किसी विशेष कक्षा में सुधार चाहता है, इसलिए कथन 2 गलत है।"},
  {"id":"cdp-pedagogy-subjects-1503","question":"Which of the following is the most suitable problem for a Class V teacher's action research?","options":["What is the effect of family income on literacy rates across all the states of India?","Why do eight children in my Class V not finish their written work, and how can I help them?","How did the education policy of 1968 influence the adoption of the three-language formula?","Is a child's intelligence mainly inherited from parents or mainly acquired from the environment?"],"answer":1,"explanation":"Action research focuses on a specific, practical problem in the teacher's own classroom that she can act on. The other questions are large-scale, historical or theoretical research topics.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"निम्नलिखित में से कक्षा V के शिक्षक के क्रियात्मक अनुसंधान के लिए सबसे उपयुक्त समस्या कौन-सी है?","optionsHi":["भारत के सभी राज्यों में पारिवारिक आय का साक्षरता दर पर क्या प्रभाव पड़ता है?","मेरी कक्षा V के आठ बच्चे अपना लिखित कार्य पूरा क्यों नहीं करते, और मैं उनकी मदद कैसे कर सकता/सकती हूँ?","1968 की शिक्षा नीति ने त्रिभाषा सूत्र को अपनाने को कैसे प्रभावित किया?","क्या बच्चे की बुद्धि मुख्यतः माता-पिता से मिलती है या मुख्यतः वातावरण से अर्जित होती है?"],"explanationHi":"क्रियात्मक अनुसंधान शिक्षक की अपनी कक्षा की किसी विशिष्ट, व्यावहारिक समस्या पर केंद्रित होता है जिस पर वह कार्य कर सके। अन्य प्रश्न बड़े पैमाने के, ऐतिहासिक या सैद्धांतिक शोध-विषय हैं।"},
  {"id":"cdp-pedagogy-subjects-1504","question":"According to John Dewey, reflective thinking typically begins when a teacher:","options":["follows a routine that has always worked well with her earlier classes","faces a situation of doubt or difficulty that needs resolving","receives a circular from the department asking her to change her methods","memorises the steps of a teaching method given in the teacher's handbook"],"answer":1,"explanation":"For Dewey, reflection starts from a felt difficulty or uncertainty, which leads to inquiry and careful consideration of beliefs and actions. Routine action does not call for reflection.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"जॉन डेवी के अनुसार, चिंतनशील चिंतन (reflective thinking) सामान्यतः तब शुरू होता है जब शिक्षक:","optionsHi":["ऐसी दिनचर्या का पालन करती है जो उसकी पिछली कक्षाओं में हमेशा अच्छी चली है","संदेह या कठिनाई की ऐसी स्थिति का सामना करती है जिसे सुलझाना आवश्यक है","विभाग से ऐसा परिपत्र पाती है जिसमें उसे अपनी विधियाँ बदलने को कहा गया है","शिक्षक-पुस्तिका में दी गई किसी शिक्षण विधि के चरण याद कर लेती है"],"explanationHi":"डेवी के लिए चिंतन किसी अनुभव की गई कठिनाई या अनिश्चितता से शुरू होता है, जो जाँच-पड़ताल और अपनी मान्यताओं तथा कार्यों पर सावधानी से विचार करने की ओर ले जाता है। नियमित दिनचर्या वाले कार्य में चिंतन की आवश्यकता नहीं होती।"},
  {"id":"cdp-pedagogy-subjects-1505","question":"Which classroom practice best shows the teacher acting as a facilitator of learning, as envisaged in NCF 2005?","options":["The teacher explains each answer fully and step by step, so that children never form or carry mistaken ideas about the topic","The teacher dictates clear, well-organised notes that children memorise and revise carefully before each unit test","The teacher asks why shadows in the room change during the day, gives materials and guiding questions, and lets children explore","The teacher reads the textbook aloud with expression while children follow the lines with their fingers and underline key words"],"answer":2,"explanation":"A facilitator designs situations, provides resources and asks questions so that children construct understanding themselves. Explaining every answer or dictating notes keeps the teacher as transmitter.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"NCF 2005 में परिकल्पित अधिगम के सुगमकर्ता (facilitator) के रूप में शिक्षक की भूमिका को कौन-सी कक्षा-गतिविधि सबसे अच्छी तरह दर्शाती है?","optionsHi":["शिक्षक हर उत्तर को पूरी तरह चरण-दर-चरण समझाता है, ताकि बच्चे विषय के बारे में कभी गलत धारणाएँ न बनाएँ या न रखें","शिक्षक स्पष्ट, सुव्यवस्थित नोट्स लिखवाता है जिन्हें बच्चे हर इकाई परीक्षा से पहले याद करते और दोहराते हैं","शिक्षक पूछता है कि कमरे में दिन के दौरान परछाइयाँ क्यों बदलती हैं, सामग्री और मार्गदर्शक प्रश्न देता है, और बच्चों को स्वयं खोजबीन करने देता है","शिक्षक भाव के साथ पाठ्यपुस्तक ज़ोर से पढ़ता है जबकि बच्चे उँगली से पंक्तियाँ देखते हैं और मुख्य शब्दों को रेखांकित करते हैं"],"explanationHi":"सुगमकर्ता ऐसी परिस्थितियाँ रचता है, संसाधन देता है और प्रश्न पूछता है ताकि बच्चे स्वयं समझ का निर्माण करें। हर उत्तर समझाना या नोट्स लिखवाना शिक्षक को केवल ज्ञान का संप्रेषक बनाए रखता है।"},
  {"id":"cdp-pedagogy-subjects-1506","question":"Assertion (A): A teacher acting as a facilitator may still give direct explanations at certain points in a lesson. Reason (R): Constructivism holds that learners actively construct knowledge rather than passively receiving it.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Facilitation does not exclude well-timed explanation, for example after children have explored, so A is true; R is also true. But R explains why the teacher facilitates, not why she sometimes explains directly.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"अभिकथन (A): सुगमकर्ता के रूप में कार्य करने वाला शिक्षक पाठ में कुछ बिंदुओं पर प्रत्यक्ष व्याख्या भी दे सकता है। कारण (R): रचनावाद मानता है कि अधिगमकर्ता ज्ञान का सक्रिय रूप से निर्माण करते हैं, न कि उसे निष्क्रिय रूप से ग्रहण करते हैं।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"सुगमन में सही समय पर दी गई व्याख्या वर्जित नहीं है, जैसे बच्चों के खोजबीन करने के बाद, इसलिए A सही है; R भी सही है। परंतु R यह बताता है कि शिक्षक सुगमन क्यों करता है, यह नहीं कि वह कभी-कभी प्रत्यक्ष व्याख्या क्यों देता है।"},
  {"id":"cdp-pedagogy-subjects-1507","question":"A Class VI teacher invites a colleague to observe her class. Which arrangement is most likely to help her grow professionally?","options":["The colleague drops in without warning, so that he sees her normal teaching, and reports what he saw to the principal","The colleague observes the full lesson and gives her a numerical rating on every aspect of teaching for her service file","The colleague observes and then teaches the next lesson himself, so that she can see the right way to handle it","They agree on one focus beforehand, he records evidence on it, and they discuss it afterwards without judgement"],"answer":3,"explanation":"Peer observation supports reflection when it is collaborative, focused, evidence-based and non-evaluative. Surprise inspections or ratings make it threatening and less useful.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VI की एक शिक्षिका अपनी कक्षा का अवलोकन करने के लिए एक सहकर्मी को आमंत्रित करती है। कौन-सी व्यवस्था उसके व्यावसायिक विकास में सबसे अधिक सहायक होगी?","optionsHi":["सहकर्मी बिना बताए आ जाए, ताकि वह उसका सामान्य शिक्षण देख सके, और जो देखा उसकी रिपोर्ट प्रधानाचार्य को दे","सहकर्मी पूरे पाठ का अवलोकन करे और उसकी सेवा-पुस्तिका के लिए शिक्षण के हर पहलू पर उसे संख्यात्मक अंक दे","सहकर्मी अवलोकन करे और फिर अगला पाठ स्वयं पढ़ाए, ताकि वह देख सके कि उसे सही तरीके से कैसे संभाला जाए","वे पहले से किसी एक केंद्र-बिंदु पर सहमत हों, वह उस पर साक्ष्य दर्ज करे, और बाद में वे बिना किसी निर्णयात्मक रुख के उस पर चर्चा करें"],"explanationHi":"सहकर्मी अवलोकन तब चिंतन में सहायक होता है जब वह सहयोगात्मक, किसी एक बिंदु पर केंद्रित, साक्ष्य-आधारित और मूल्यांकन-रहित हो। अचानक निरीक्षण या अंक देने से वह भयकारी और कम उपयोगी बन जाता है।"},
  {"id":"cdp-pedagogy-subjects-1508","question":"Which reflective journal entry by a Class IV teacher shows the deepest level of reflection?","options":["'Today I taught the lesson on directions using the map in the textbook. The children enjoyed it and the class was lively throughout.'","'The lesson on directions went badly. The children were very noisy, did not listen to my instructions and kept talking among themselves.'","'Many children confused left and right on the map, I think because I faced them while demonstrating. Tomorrow I will stand with my back to them.'","'I completed the chapter on directions as per my lesson plan, covered all the textbook exercises and gave homework from the back of the chapter.'"],"answer":2,"explanation":"Deep reflection describes what happened, analyses why using evidence, and plans a change. The other entries are merely descriptive or blame students without analysis.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा IV की एक शिक्षिका की कौन-सी चिंतन-डायरी प्रविष्टि चिंतन के सबसे गहरे स्तर को दर्शाती है?","optionsHi":["‘आज मैंने पाठ्यपुस्तक के मानचित्र की सहायता से दिशाओं का पाठ पढ़ाया। बच्चों को मज़ा आया और पूरी कक्षा जीवंत रही।’","‘दिशाओं का पाठ ठीक नहीं रहा। बच्चे बहुत शोर कर रहे थे, मेरे निर्देश नहीं सुन रहे थे और आपस में बातें करते रहे।’","‘बहुत से बच्चे मानचित्र पर बाएँ और दाएँ में उलझ गए, शायद इसलिए कि मैंने प्रदर्शन करते समय उनकी ओर मुँह करके खड़ी थी। कल मैं उनकी ओर पीठ करके खड़ी होऊँगी।’","‘मैंने अपनी पाठ-योजना के अनुसार दिशाओं का अध्याय पूरा किया, पाठ्यपुस्तक के सभी अभ्यास करवाए और अध्याय के अंत से गृहकार्य दिया।’"],"explanationHi":"गहरा चिंतन यह वर्णन करता है कि क्या हुआ, साक्ष्य के आधार पर विश्लेषण करता है कि क्यों हुआ, और बदलाव की योजना बनाता है। अन्य प्रविष्टियाँ केवल वर्णनात्मक हैं या बिना विश्लेषण के विद्यार्थियों को दोष देती हैं।"},
  {"id":"cdp-pedagogy-subjects-1509","question":"Listening to an audio recording of her own Class VII lesson, Ms Fernandes notices that she called on boys twice as often as girls and gave boys more follow-up questions. What is the most appropriate next step?","options":["Delete the recording and move on, since calling on boys more often is a natural classroom pattern that cannot be changed","Acknowledge the unconscious bias, use strategies such as random selection and equal wait time, and record another lesson","Ask the girls to raise their hands more often, since the teacher can only call on those who volunteer to answer","Conclude that the boys are more interested in the subject, and plan more challenging questions to keep them engaged"],"answer":1,"explanation":"Recording reveals patterns teachers are unaware of; reflective practice turns this evidence into deliberate change and checks the effect. Blaming the students or ignoring it leaves the bias in place.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VII के अपने पाठ की ऑडियो रिकॉर्डिंग सुनते हुए सुश्री फर्नांडिस देखती हैं कि उन्होंने लड़कियों की तुलना में लड़कों को दो गुना अधिक बार बुलाया और लड़कों से अधिक अनुवर्ती प्रश्न पूछे। सबसे उचित अगला कदम क्या है?","optionsHi":["रिकॉर्डिंग हटाकर आगे बढ़ जाएँ, क्योंकि लड़कों को अधिक बुलाना कक्षा का स्वाभाविक ढर्रा है जिसे बदला नहीं जा सकता","अचेतन पूर्वाग्रह को स्वीकार करें, यादृच्छिक चयन और समान प्रतीक्षा-समय जैसी युक्तियाँ अपनाएँ, और एक और पाठ रिकॉर्ड करें","लड़कियों से कहें कि वे अधिक बार हाथ उठाएँ, क्योंकि शिक्षिका केवल उन्हीं को बुला सकती है जो स्वेच्छा से उत्तर देना चाहते हैं","यह निष्कर्ष निकालें कि लड़कों की विषय में अधिक रुचि है, और उन्हें व्यस्त रखने के लिए अधिक चुनौतीपूर्ण प्रश्न तैयार करें"],"explanationHi":"रिकॉर्डिंग ऐसे ढर्रे उजागर करती है जिनसे शिक्षक अनजान होते हैं; चिंतनशील अभ्यास इस साक्ष्य को सोच-समझकर किए गए बदलाव में बदलता है और उसके प्रभाव की जाँच करता है। विद्यार्थियों को दोष देने या अनदेखी करने से पूर्वाग्रह बना रहता है।"},
  {"id":"cdp-pedagogy-subjects-1510","question":"In her school, Class V teachers meet every two weeks to look at samples of students' written work together, discuss what the work shows about learning, and plan changes in their teaching. This practice is best described as:","options":["A professional learning community, in which teachers learn together from evidence of students' learning","An inspection exercise meant to find out which teacher's section is weakest so that the principal can act on it","An administrative meeting held mainly to complete the school's assessment records and registers on time","A competition between sections to see which class teacher's students produce the neatest written work"],"answer":0,"explanation":"Professional learning communities focus on collaborative inquiry into student learning and shared improvement of teaching. They are developmental, not evaluative or administrative.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"उसके विद्यालय में कक्षा V के शिक्षक हर दो सप्ताह में मिलते हैं, विद्यार्थियों के लिखित कार्य के नमूने साथ देखते हैं, चर्चा करते हैं कि वह कार्य अधिगम के बारे में क्या दर्शाता है, और अपने शिक्षण में बदलावों की योजना बनाते हैं। इस अभ्यास का सबसे उपयुक्त वर्णन है:","optionsHi":["व्यावसायिक अधिगम समुदाय, जिसमें शिक्षक विद्यार्थियों के अधिगम के साक्ष्य से मिलकर सीखते हैं","निरीक्षण की कवायद, जिसका उद्देश्य यह पता लगाना है कि किस शिक्षक का वर्ग सबसे कमज़ोर है ताकि प्रधानाचार्य कार्रवाई कर सकें","मुख्यतः विद्यालय के आकलन अभिलेखों और रजिस्टरों को समय पर पूरा करने के लिए बुलाई गई प्रशासनिक बैठक","यह देखने के लिए वर्गों की प्रतियोगिता कि किस कक्षा-शिक्षक के विद्यार्थी सबसे साफ़-सुथरा लिखित कार्य करते हैं"],"explanationHi":"व्यावसायिक अधिगम समुदाय विद्यार्थियों के अधिगम की सहयोगात्मक जाँच और शिक्षण के साझा सुधार पर केंद्रित होते हैं। वे विकासात्मक होते हैं, मूल्यांकनात्मक या प्रशासनिक नहीं।"},
  {"id":"cdp-pedagogy-subjects-1511","question":"A Class III child says confidently, 'Plants eat soil; that is why they grow in it.' What is the best response from a teacher acting as a facilitator?","options":["'Wrong. Plants make their own food in their leaves. Write the correct answer in your notebook now.'","'Good answer!' and move on to the next child, so as to protect this child's confidence in speaking up","'Ask your parents about it tonight and tell the whole class the right answer when you come tomorrow.'","'Interesting idea. Why do you think so? How could we check if the soil gets less as the plant grows?'"],"answer":3,"explanation":"A facilitator treats children's ideas as starting points, asks for reasoning and helps design a way to test them. Simply correcting or wrongly praising both miss the chance for children to reconstruct their understanding.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा III का एक बच्चा पूरे विश्वास से कहता है, ‘पौधे मिट्टी खाते हैं; इसीलिए वे उसमें उगते हैं।’ सुगमकर्ता के रूप में कार्य करने वाले शिक्षक की सबसे अच्छी प्रतिक्रिया क्या होगी?","optionsHi":["‘गलत। पौधे अपना भोजन अपनी पत्तियों में बनाते हैं। सही उत्तर अभी अपनी कॉपी में लिखो।’","‘अच्छा उत्तर!’ और अगले बच्चे की ओर बढ़ जाना, ताकि इस बच्चे का बोलने का आत्मविश्वास बना रहे","‘आज रात अपने माता-पिता से इसके बारे में पूछो और कल आकर पूरी कक्षा को सही उत्तर बताओ।’","‘रोचक विचार है। तुम ऐसा क्यों सोचते हो? हम कैसे जाँच सकते हैं कि पौधा बढ़ने के साथ मिट्टी कम होती है या नहीं?’"],"explanationHi":"सुगमकर्ता बच्चों के विचारों को शुरुआती बिंदु मानता है, तर्क पूछता है और उन्हें परखने का तरीका बनाने में मदद करता है। केवल सुधार देना या गलत प्रशंसा करना, दोनों ही बच्चों को अपनी समझ का पुनर्निर्माण करने का अवसर गँवा देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1512","question":"Consider the following statements about continuous professional development (CPD) of teachers as envisaged in NEP 2020: 1. Each teacher is expected to take part in at least 50 hours of CPD every year. 2. CPD can only be done through formal degree courses. 3. Teachers should have opportunities to choose CPD according to their own interests and needs. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":2,"explanation":"NEP 2020 expects at least 50 hours of CPD a year, offered in many modes (workshops, online modules) with teacher choice. It is not limited to degree courses, so statement 2 is false.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"NEP 2020 में परिकल्पित शिक्षकों के सतत व्यावसायिक विकास (CPD) के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. प्रत्येक शिक्षक से अपेक्षा है कि वह हर वर्ष कम से कम 50 घंटे के CPD में भाग ले। 2. CPD केवल औपचारिक डिग्री पाठ्यक्रमों के माध्यम से ही किया जा सकता है। 3. शिक्षकों को अपनी रुचियों और आवश्यकताओं के अनुसार CPD चुनने के अवसर मिलने चाहिए। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"NEP 2020 प्रति वर्ष कम से कम 50 घंटे के CPD की अपेक्षा करती है, जो अनेक रूपों (कार्यशालाओं, ऑनलाइन मॉड्यूल) में और शिक्षक की पसंद के साथ दिया जाए। यह केवल डिग्री पाठ्यक्रमों तक सीमित नहीं है, इसलिए कथन 2 गलत है।"},
  {"id":"cdp-pedagogy-subjects-1513","question":"Lawrence Stenhouse argued that curriculum development should rest on the 'teacher as researcher'. Which practice best fits this idea?","options":["Teachers treat curriculum ideas as hypotheses, test them in their own classes and refine their teaching","Teachers deliver the curriculum exactly as designed by subject experts, since any change would weaken it","Teachers leave research to universities and focus their energy on completing the syllabus on time","Teachers conduct large surveys across many districts so that their findings can shape national policy"],"answer":0,"explanation":"Stenhouse saw teachers as inquirers who treat curriculum proposals as hypotheses to be tested in their own classrooms. Passive delivery is the opposite of his view.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"लॉरेंस स्टेनहाउस ने तर्क दिया कि पाठ्यचर्या विकास ‘शोधकर्ता के रूप में शिक्षक’ पर आधारित होना चाहिए। कौन-सा अभ्यास इस विचार के सबसे अनुकूल है?","optionsHi":["शिक्षक पाठ्यचर्या के विचारों को परिकल्पना मानते हैं, उन्हें अपनी कक्षाओं में परखते हैं और अपने शिक्षण को परिष्कृत करते हैं","शिक्षक पाठ्यचर्या को ठीक उसी रूप में लागू करते हैं जैसा विषय-विशेषज्ञों ने बनाया है, क्योंकि कोई भी बदलाव उसे कमज़ोर करेगा","शिक्षक शोध विश्वविद्यालयों पर छोड़ देते हैं और अपनी ऊर्जा पाठ्यक्रम समय पर पूरा करने में लगाते हैं","शिक्षक अनेक ज़िलों में बड़े सर्वेक्षण करते हैं ताकि उनके निष्कर्ष राष्ट्रीय नीति को आकार दे सकें"],"explanationHi":"स्टेनहाउस शिक्षकों को ऐसे जिज्ञासु अन्वेषक मानते थे जो पाठ्यचर्या के प्रस्तावों को अपनी कक्षाओं में परखी जाने वाली परिकल्पनाएँ मानते हैं। निष्क्रिय रूप से पहुँचाना उनके दृष्टिकोण के विपरीत है।"},
  {"id":"cdp-pedagogy-subjects-1514","question":"Many Class VIII students in two sections fail to submit homework. Mr Rao responds by increasing the penalty for missing homework. Ms Das asks herself whether the homework is meaningful, whether students can do it without help at home, and what homework is meant to achieve, and then redesigns it. In Argyris and Schön's terms:","options":["Both teachers are showing double-loop learning","Mr Rao shows double-loop learning and Ms Das shows single-loop learning","Mr Rao shows single-loop learning and Ms Das shows double-loop learning","Neither teacher is reflecting on practice"],"answer":2,"explanation":"Single-loop learning changes actions within existing assumptions (more punishment); double-loop learning questions the underlying assumptions and goals themselves, as Ms Das does.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"दो अनुभागों के कक्षा VIII के कई विद्यार्थी गृहकार्य जमा नहीं करते। श्री राव गृहकार्य न करने का दंड बढ़ाकर प्रतिक्रिया देते हैं। सुश्री दास स्वयं से पूछती हैं कि क्या गृहकार्य सार्थक है, क्या विद्यार्थी घर पर बिना सहायता के उसे कर सकते हैं, और गृहकार्य का उद्देश्य क्या है, और फिर उसे नए सिरे से बनाती हैं। आर्गिरिस और शॉन के शब्दों में:","optionsHi":["दोनों शिक्षक द्वि-पाश अधिगम (double-loop learning) दिखा रहे हैं","श्री राव द्वि-पाश अधिगम और सुश्री दास एकल-पाश अधिगम (single-loop learning) दिखा रहे हैं","श्री राव एकल-पाश अधिगम और सुश्री दास द्वि-पाश अधिगम दिखा रही हैं","कोई भी शिक्षक अपने अभ्यास पर चिंतन नहीं कर रहा है"],"explanationHi":"एकल-पाश अधिगम मौजूदा मान्यताओं के भीतर कार्यों को बदलता है (अधिक दंड); द्वि-पाश अधिगम अंतर्निहित मान्यताओं और लक्ष्यों पर ही प्रश्न उठाता है, जैसा सुश्री दास करती हैं।"},
  {"id":"cdp-pedagogy-subjects-1515","question":"After video-recording a Class VI discussion lesson, a teacher finds that she spoke for about 80% of the time and students' answers were mostly one word. Which change best follows from this reflection?","options":["Speak faster and more clearly so that more of the planned content is covered within the period","Plan open questions, use longer wait time and pair talk, and step back so students talk more","Ask mainly yes/no questions so that every student can answer quickly and nobody feels left out","Stop recording lessons, since the camera makes both the teacher and the students nervous and quiet"],"answer":1,"explanation":"Reducing teacher talk and creating structures for student talk (open questions, wait time, pair discussion) shifts the class toward active learning, which is what the evidence calls for.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VI की एक चर्चा-पाठ की वीडियो रिकॉर्डिंग करने के बाद एक शिक्षिका पाती है कि वह लगभग 80% समय स्वयं बोली और विद्यार्थियों के उत्तर ज़्यादातर एक शब्द के थे। इस चिंतन से कौन-सा बदलाव सबसे उपयुक्त निकलता है?","optionsHi":["अधिक तेज़ और स्पष्ट बोलना, ताकि पीरियड में योजना की अधिक सामग्री पूरी हो सके","खुले प्रश्न तैयार करना, प्रतीक्षा-समय बढ़ाना और जोड़ी में बातचीत करवाना, तथा पीछे हटकर विद्यार्थियों को अधिक बोलने देना","मुख्यतः हाँ/नहीं वाले प्रश्न पूछना, ताकि हर विद्यार्थी जल्दी उत्तर दे सके और कोई छूटा हुआ महसूस न करे","पाठों की रिकॉर्डिंग बंद करना, क्योंकि कैमरा शिक्षिका और विद्यार्थियों दोनों को घबराहट में डालकर चुप कर देता है"],"explanationHi":"शिक्षक का बोलना कम करना और विद्यार्थियों के बोलने के लिए संरचनाएँ बनाना (खुले प्रश्न, प्रतीक्षा-समय, जोड़ी में चर्चा) कक्षा को सक्रिय अधिगम की ओर ले जाता है, जो साक्ष्य की माँग है।"},
  {"id":"cdp-pedagogy-subjects-1516","question":"After a Class IV lesson, a teacher says, 'The lesson went very well; the children were happy and active.' A mentor asks, 'How do you know what they learnt?' Which practice should the teacher adopt?","options":["Rely on her own feeling about the lesson, since an experienced teacher knows her class well","Judge success by how quiet and attentive the class remained while she was explaining the topic","Judge success by whether all the planned textbook pages and exercises were completed on time","Judge the lesson by evidence of learning, such as children's work, answers and exit tasks"],"answer":3,"explanation":"Reflective practitioners evaluate lessons using evidence of learning, not only impressions of enjoyment, quietness or coverage. Activity does not automatically mean learning.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा IV के एक पाठ के बाद शिक्षिका कहती है, ‘पाठ बहुत अच्छा रहा; बच्चे खुश और सक्रिय थे।’ मार्गदर्शक पूछता है, ‘आपको कैसे पता कि उन्होंने क्या सीखा?’ शिक्षिका को कौन-सा अभ्यास अपनाना चाहिए?","optionsHi":["अपनी स्वयं की अनुभूति पर भरोसा करे, क्योंकि अनुभवी शिक्षिका अपनी कक्षा को अच्छी तरह जानती है","इस आधार पर सफलता आँके कि उसके समझाते समय कक्षा कितनी शांत और ध्यानमग्न रही","इस आधार पर सफलता आँके कि योजना के सारे पाठ्यपुस्तक-पृष्ठ और अभ्यास समय पर पूरे हुए या नहीं","अधिगम के साक्ष्य के आधार पर पाठ का आकलन करे, जैसे बच्चों का कार्य, उनके उत्तर और निकास-कार्य (exit tasks)"],"explanationHi":"चिंतनशील व्यवसायी पाठों का आकलन केवल आनंद, शांति या पाठ्यक्रम पूरा होने की छाप से नहीं, बल्कि अधिगम के साक्ष्य से करते हैं। सक्रियता का अर्थ अपने-आप अधिगम नहीं होता।"},
  {"id":"cdp-pedagogy-subjects-1517","question":"A Class VII teacher asks students to keep a learning log in which they write after each lesson: 'What did I learn? What is still confusing? What helped me learn?' What does this mainly develop?","options":["Students' handwriting speed and neatness, through daily writing practice after lessons","Students' metacognition, as they monitor their own learning and strategies","Students' memory of textbook definitions, since they rewrite key points after every lesson","A record of attendance and lesson coverage that the teacher can show during inspections"],"answer":1,"explanation":"Reflecting on what one has understood and what helps one learn builds metacognitive awareness, and the logs also give the teacher feedback for planning.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"कक्षा VII की एक शिक्षिका विद्यार्थियों से अधिगम-डायरी (learning log) रखवाती है जिसमें वे हर पाठ के बाद लिखते हैं: ‘मैंने क्या सीखा? अब भी क्या उलझन में है? मुझे सीखने में किससे मदद मिली?’ यह मुख्यतः क्या विकसित करता है?","optionsHi":["विद्यार्थियों की लिखावट की गति और सफ़ाई, पाठों के बाद रोज़ लिखने के अभ्यास से","विद्यार्थियों का अधिसंज्ञान (metacognition), क्योंकि वे अपने अधिगम और रणनीतियों की निगरानी करते हैं","पाठ्यपुस्तक की परिभाषाओं की स्मृति, क्योंकि वे हर पाठ के बाद मुख्य बिंदु दोबारा लिखते हैं","उपस्थिति और पाठ्यक्रम-कवरेज का ऐसा अभिलेख जिसे शिक्षिका निरीक्षण के समय दिखा सके"],"explanationHi":"इस पर चिंतन करना कि क्या समझा है और किससे सीखने में मदद मिलती है, अधिसंज्ञानात्मक जागरूकता बढ़ाता है, और ये डायरियाँ शिक्षिका को योजना बनाने के लिए प्रतिपुष्टि भी देती हैं।"},
  {"id":"cdp-pedagogy-subjects-1518","question":"Two views of the teacher are being compared. View X: the teacher is a technician who applies methods designed by experts. View Y: the teacher is a reflective practitioner. Which statement best captures View Y?","options":["She makes judgements in complex, uncertain situations by constantly examining her actions, beliefs and their effects","The teacher should follow the methods prescribed in the teacher's manual closely, since they were designed by experts","The teacher's main professional task is to complete the syllabus on time and prepare students well for examinations","Reflection is mainly useful for new teachers in their first year, until they have mastered the standard methods"],"answer":0,"explanation":"Schön's reflective practitioner treats teaching as complex problem-solving informed by ongoing reflection, not mechanical application of fixed methods. Reflection matters throughout a career.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"शिक्षक के दो दृष्टिकोणों की तुलना की जा रही है। दृष्टिकोण X: शिक्षक एक तकनीशियन है जो विशेषज्ञों द्वारा बनाई गई विधियाँ लागू करता है। दृष्टिकोण Y: शिक्षक एक चिंतनशील व्यवसायी है। कौन-सा कथन दृष्टिकोण Y को सबसे अच्छी तरह व्यक्त करता है?","optionsHi":["वह जटिल, अनिश्चित परिस्थितियों में अपने कार्यों, मान्यताओं और उनके प्रभावों की निरंतर जाँच करते हुए निर्णय लेती है","शिक्षक को शिक्षक-पुस्तिका में निर्धारित विधियों का निकटता से पालन करना चाहिए, क्योंकि वे विशेषज्ञों ने बनाई हैं","शिक्षक का मुख्य व्यावसायिक कार्य पाठ्यक्रम समय पर पूरा करना और विद्यार्थियों को परीक्षाओं के लिए अच्छी तरह तैयार करना है","चिंतन मुख्यतः पहले वर्ष के नए शिक्षकों के लिए उपयोगी है, जब तक वे मानक विधियों में निपुण न हो जाएँ"],"explanationHi":"शॉन का चिंतनशील व्यवसायी शिक्षण को निरंतर चिंतन से सूचित जटिल समस्या-समाधान मानता है, निश्चित विधियों का यांत्रिक अनुप्रयोग नहीं। चिंतन पूरे कार्य-जीवन में महत्वपूर्ण रहता है।"},
  {"id":"cdp-pedagogy-subjects-1519","question":"During a Class V science lesson, a student asks a question the teacher cannot answer: 'Why do cats' eyes shine in the dark?' What is the most appropriate response from a teacher who sees herself as a co-learner and facilitator?","options":["Tell the student the question is not in the syllabus, so the class should focus on the chapter","Give a confident answer on the spot, since admitting ignorance would reduce the class's trust in her","Admit she is not sure and plan with the class how to find out, then share the findings later","Ask the student to save such difficult questions for the higher classes, where they will be taught"],"answer":2,"explanation":"Modelling honest inquiry ('let us find out') shows that knowledge is built, not just held by the teacher. Inventing an answer spreads misconceptions and dismissing the question kills curiosity.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा V के विज्ञान पाठ के दौरान एक विद्यार्थी ऐसा प्रश्न पूछता है जिसका उत्तर शिक्षिका नहीं दे पाती: ‘बिल्लियों की आँखें अँधेरे में क्यों चमकती हैं?’ स्वयं को सह-अधिगमकर्ता और सुगमकर्ता मानने वाली शिक्षिका की सबसे उपयुक्त प्रतिक्रिया क्या होगी?","optionsHi":["विद्यार्थी को बताए कि प्रश्न पाठ्यक्रम में नहीं है, इसलिए कक्षा को अध्याय पर ध्यान देना चाहिए","उसी समय आत्मविश्वास से कोई उत्तर दे दे, क्योंकि अज्ञान मान लेने से कक्षा का उस पर भरोसा घट जाएगा","स्वीकार करे कि उसे पक्का पता नहीं है और कक्षा के साथ योजना बनाए कि पता कैसे लगाया जाए, फिर बाद में निष्कर्ष साझा करे","विद्यार्थी से कहे कि ऐसे कठिन प्रश्न ऊँची कक्षाओं के लिए बचाकर रखे, जहाँ वे पढ़ाए जाएँगे"],"explanationHi":"ईमानदार जाँच का आदर्श (‘आओ पता लगाएँ’) दिखाता है कि ज्ञान निर्मित होता है, केवल शिक्षक के पास रखा नहीं होता। उत्तर गढ़ देने से भ्रांतियाँ फैलती हैं और प्रश्न को टाल देने से जिज्ञासा मरती है।"},
  {"id":"cdp-pedagogy-subjects-1520","question":"A teacher in Ajmer feels that the Class IV EVS textbook chapter on 'Houses' shows only city flats and bungalows, while her students live in kuchcha and pucca houses in villages and in temporary shelters. What should she do as a reflective, autonomous teacher?","options":["Teach the chapter as given, then add a line noting that village houses also exist","Write to the SCERT about the gap and wait for a revised edition before teaching the chapter","Replace the chapter with her own lesson on village houses and leave out city homes","Use the textbook as one resource and add children's own homes, materials and shelters"],"answer":3,"explanation":"NCF 2005 treats the textbook as one resource and asks teachers to connect it to children's lives while keeping the wider view. Replacing the chapter with village houses alone is tempting but drops the diversity of homes the topic is meant to show, and a token line or waiting for a new edition fails the learners now.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs","questionHi":"अजमेर की एक शिक्षिका को लगता है कि कक्षा IV की EVS पाठ्यपुस्तक का ‘घर’ अध्याय केवल शहरी फ्लैट और बंगले दिखाता है, जबकि उसके विद्यार्थी गाँवों के कच्चे और पक्के घरों तथा अस्थायी आश्रयों में रहते हैं। एक चिंतनशील, स्वायत्त शिक्षिका के रूप में उसे क्या करना चाहिए?","optionsHi":["अध्याय को जैसा दिया है वैसा पढ़ाए, फिर एक पंक्ति जोड़े कि गाँव के घर भी होते हैं","इस कमी के बारे में SCERT को लिखे और अध्याय पढ़ाने से पहले संशोधित संस्करण की प्रतीक्षा करे","अध्याय को गाँव के घरों के अपने पाठ से बदल दे और शहरी घरों को छोड़ दे","पाठ्यपुस्तक को एक संसाधन के रूप में इस्तेमाल करे और बच्चों के अपने घरों, सामग्रियों और आश्रयों को जोड़े"],"explanationHi":"NCF 2005 पाठ्यपुस्तक को एक संसाधन मानती है और शिक्षकों से कहती है कि वे उसे बच्चों के जीवन से जोड़ें, साथ ही व्यापक दृष्टि बनाए रखें। अध्याय को केवल गाँव के घरों से बदलना आकर्षक लगता है, पर इससे घरों की वह विविधता छूट जाती है जिसे यह विषय दिखाना चाहता है; और एक औपचारिक पंक्ति जोड़ना या नए संस्करण की प्रतीक्षा करना अभी के अधिगमकर्ताओं के साथ न्याय नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1521","question":"Match each reflective activity with what it mainly offers. P. Keeping a teaching journal; Q. Peer observation; R. Collecting anonymous student feedback; S. Reading research on how children learn fractions. Offers: 1. Students' perspective; 2. A colleague's perspective; 3. Theoretical perspective; 4. The teacher's own perspective over time.","options":["P-4, Q-2, R-1, S-3","P-2, Q-4, R-1, S-3","P-4, Q-1, R-2, S-3","P-4, Q-2, R-3, S-1"],"answer":0,"explanation":"These map onto Brookfield's lenses: a journal gives the teacher's own view over time, peer observation a colleague's view, anonymous feedback the students' view, and research the theoretical lens.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"प्रत्येक चिंतनशील गतिविधि का मिलान इस बात से कीजिए कि वह मुख्यतः क्या प्रदान करती है। P. शिक्षण-डायरी रखना; Q. सहकर्मी अवलोकन; R. विद्यार्थियों से गुमनाम प्रतिपुष्टि लेना; S. बच्चे भिन्नों को कैसे सीखते हैं, इस पर शोध पढ़ना। प्रदान करती हैं: 1. विद्यार्थियों का दृष्टिकोण; 2. सहकर्मी का दृष्टिकोण; 3. सैद्धांतिक दृष्टिकोण; 4. समय के साथ शिक्षक का अपना दृष्टिकोण।","optionsHi":["P-4, Q-2, R-1, S-3","P-2, Q-4, R-1, S-3","P-4, Q-1, R-2, S-3","P-4, Q-2, R-3, S-1"],"explanationHi":"ये ब्रुकफ़ील्ड के दृष्टि-लेंसों से मेल खाते हैं: डायरी समय के साथ शिक्षक का अपना दृष्टिकोण देती है, सहकर्मी अवलोकन सहकर्मी का, गुमनाम प्रतिपुष्टि विद्यार्थियों का, और शोध सैद्धांतिक लेंस देता है।"},
  {"id":"cdp-pedagogy-subjects-1522","question":"A Class VI teacher writes after a lesson: 'Two children cried when I returned their test papers in front of everyone.' She later analyses why it happened and what it shows about her assessment practice. This method of reflection is called:","options":["Micro-teaching feedback cycle","Programmed learning","Critical incident analysis","Cooperative team teaching"],"answer":2,"explanation":"Critical incident analysis takes a significant event and examines its causes and meanings to question one's practice. It is a reflection tool, unlike micro-teaching or team teaching, which are teaching formats.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VI की एक शिक्षिका पाठ के बाद लिखती है: ‘जब मैंने सबके सामने परीक्षा-पत्र लौटाए तो दो बच्चे रो पड़े।’ बाद में वह विश्लेषण करती है कि ऐसा क्यों हुआ और यह उसके आकलन-अभ्यास के बारे में क्या दर्शाता है। चिंतन की इस विधि को कहते हैं:","optionsHi":["सूक्ष्म-शिक्षण प्रतिपुष्टि चक्र","अभिक्रमित अधिगम","विशिष्ट घटना विश्लेषण (critical incident analysis)","सहकारी दल शिक्षण"],"explanationHi":"विशिष्ट घटना विश्लेषण किसी महत्वपूर्ण घटना के कारणों और अर्थों की जाँच करके अपने अभ्यास पर प्रश्न उठाता है। यह एक चिंतन-उपकरण है, जबकि सूक्ष्म-शिक्षण या दल शिक्षण शिक्षण के प्रारूप हैं।"},
  {"id":"cdp-pedagogy-subjects-1523","question":"Assertion (A): Reflective practice requires a teacher to examine not only her methods but also the beliefs and assumptions behind them. Reason (R): Unexamined beliefs, for example about which children are 'capable', can shape teaching decisions without the teacher being aware of it.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because hidden assumptions drive choices (whom to call on, what to expect), critical reflection has to look at beliefs as well as techniques. R gives exactly this reason.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"अभिकथन (A): चिंतनशील अभ्यास में शिक्षिका को केवल अपनी विधियों की ही नहीं, बल्कि उनके पीछे की मान्यताओं और धारणाओं की भी जाँच करनी होती है। कारण (R): बिना जाँची गई मान्यताएँ, जैसे कि कौन-से बच्चे ‘सक्षम’ हैं, शिक्षिका को पता चले बिना शिक्षण के निर्णयों को आकार दे सकती हैं।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"क्योंकि छिपी हुई धारणाएँ चुनावों को चलाती हैं (किसे बुलाना है, क्या अपेक्षा रखनी है), इसलिए आलोचनात्मक चिंतन में तकनीकों के साथ मान्यताओं को भी देखना होता है। R ठीक यही कारण देता है।"},
  {"id":"cdp-pedagogy-subjects-1524","question":"Consider these statements about primary EVS in the light of NCF 2005: I. It should help children see links between natural and social phenomena. II. Children’s local knowledge may be used in class only after it is confirmed by the textbook. III. It should develop sensitivity towards the environment and towards people. IV. Learning in EVS should be judged mainly through written term-end tests. Which are correct?","options":["I and II only","III and IV only","I, III and IV only","I and III only"],"answer":3,"explanation":"NCF 2005 treats local knowledge as valid in its own right and favours continuous, varied assessment over term-end tests, so II and IV are wrong; I and III state its aims.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"NCF 2005 के आलोक में प्राथमिक EVS के बारे में निम्नलिखित कथनों पर विचार कीजिए: I. इसे बच्चों को प्राकृतिक और सामाजिक परिघटनाओं के बीच संबंध देखने में मदद करनी चाहिए। II. बच्चों का स्थानीय ज्ञान कक्षा में तभी उपयोग किया जाए जब पाठ्यपुस्तक उसकी पुष्टि कर दे। III. इसे पर्यावरण और लोगों के प्रति संवेदनशीलता विकसित करनी चाहिए। IV. EVS में अधिगम का आकलन मुख्यतः सत्रांत की लिखित परीक्षाओं से किया जाना चाहिए। कौन-से सही हैं?","optionsHi":["केवल I और II","केवल III और IV","केवल I, III और IV","केवल I और III"],"explanationHi":"NCF 2005 स्थानीय ज्ञान को अपने आप में वैध मानती है और सत्रांत परीक्षाओं की तुलना में सतत, विविध आकलन का पक्ष लेती है, इसलिए II और IV गलत हैं; I और III उसके उद्देश्य बताते हैं।"},
  {"id":"cdp-pedagogy-subjects-1525","question":"Assertion (A): Concept maps are useful for assessing children’s understanding in EVS. Reason (R): Concept maps were first developed in the 1970s. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Novak’s team developed concept maps in the 1970s, but their usefulness in assessment comes from showing how a learner links ideas, not from their date of origin.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"अभिकथन (A): EVS में बच्चों की समझ का आकलन करने के लिए संकल्पना मानचित्र (concept maps) उपयोगी हैं। कारण (R): संकल्पना मानचित्र सबसे पहले 1970 के दशक में विकसित किए गए थे। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"नोवाक की टीम ने 1970 के दशक में संकल्पना मानचित्र विकसित किए, पर आकलन में उनकी उपयोगिता इस बात से आती है कि वे दिखाते हैं कि अधिगमकर्ता विचारों को कैसे जोड़ता है, उनके उद्भव की तिथि से नहीं।"},
  {"id":"cdp-pedagogy-subjects-1526","question":"Many Class 5 children in a school in the Little Rann of Kutch come from families that make salt in the salt pans. The richest way to use this in EVS is to:","options":["avoid the topic, since the work is hard and children may feel embarrassed about their parents' jobs","show a video of a modern salt factory in another country, so that children see the latest technology","ask children to learn the chemical name and formula of common salt, since that is the scientific fact","invite parents to explain how salt is made and discuss the working conditions, such as heat and brine"],"answer":3,"explanation":"The families’ work links ‘Water’ and ‘Things We Make and Do’ with livelihood and working conditions, and respects children’s background. Avoiding it or replacing it with distant examples wastes a real resource.","difficulty":"very-hard","source":"CTET Paper 1 · GTET","questionHi":"कच्छ के छोटे रण के एक विद्यालय की कक्षा 5 के बहुत से बच्चे ऐसे परिवारों से आते हैं जो नमक के खेतों (salt pans) में नमक बनाते हैं। EVS में इसका सबसे समृद्ध उपयोग करने का तरीका है:","optionsHi":["इस विषय से बचना, क्योंकि काम कठिन है और बच्चे अपने माता-पिता के पेशे से शर्मिंदा हो सकते हैं","किसी दूसरे देश की आधुनिक नमक फ़ैक्टरी का वीडियो दिखाना, ताकि बच्चे नवीनतम तकनीक देखें","बच्चों से सामान्य नमक का रासायनिक नाम और सूत्र सीखने को कहना, क्योंकि वही वैज्ञानिक तथ्य है","माता-पिता को बुलाकर उनसे नमक बनाने का तरीका समझवाना और कार्य की परिस्थितियों, जैसे गर्मी और खारे पानी (brine), पर चर्चा करना"],"explanationHi":"परिवारों का कार्य ‘जल’ और ‘हम क्या बनाते और करते हैं’ को आजीविका और कार्य-परिस्थितियों से जोड़ता है, तथा बच्चों की पृष्ठभूमि का सम्मान करता है। इससे बचना या दूर के उदाहरण लाना एक वास्तविक संसाधन को व्यर्थ करना है।"},
  {"id":"cdp-pedagogy-subjects-1527","question":"Which of the following is an activity WITHOUT a clear EVS learning purpose?","options":["Children compare the feet of a hen and a duck and guess why they are so different","Children colour a printed outline of a cow, and the teacher moves on without discussion","Children track how the water level of a nearby pond changes over three months of the year","Children ask a local shopkeeper where the vegetables in his shop come from each morning"],"answer":1,"explanation":"Colouring an outline with no observation, discussion or question is busy work. The other activities each involve observing, recording or inquiring.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"निम्नलिखित में से कौन-सी गतिविधि बिना किसी स्पष्ट EVS अधिगम उद्देश्य की है?","optionsHi":["बच्चे मुर्गी और बत्तख के पैरों की तुलना करते हैं और अनुमान लगाते हैं कि वे इतने भिन्न क्यों हैं","बच्चे गाय की छपी हुई रूपरेखा में रंग भरते हैं, और शिक्षक बिना चर्चा के आगे बढ़ जाता है","बच्चे वर्ष के तीन महीनों में पास के तालाब के जलस्तर में आने वाले बदलाव का अनुसरण करते हैं","बच्चे स्थानीय दुकानदार से पूछते हैं कि उसकी दुकान की सब्ज़ियाँ हर सुबह कहाँ से आती हैं"],"explanationHi":"बिना किसी अवलोकन, चर्चा या प्रश्न के रूपरेखा में रंग भरना केवल व्यस्त रखने वाला कार्य है। अन्य गतिविधियों में से प्रत्येक में अवलोकन करना, अभिलेख रखना या पूछताछ करना शामिल है।"},
  {"id":"cdp-pedagogy-subjects-1528","question":"Match each alternative conception with the activity that best challenges it: 1. ‘Sugar is destroyed when it dissolves in water.’ 2. ‘Air has no weight.’ 3. ‘Plants do not need light.’ 4. ‘Seeds are non-living.’ a. Tasting the water and letting some of it dry to see what is left. b. Balancing two blown-up balloons on a stick and bursting one. c. Keeping one potted plant in a dark box and one in light, watering both equally. d. Soaking and sowing seeds and comparing them with dry seeds.","options":["1-b, 2-a, 3-c, 4-d","1-a, 2-b, 3-d, 4-c","1-a, 2-b, 3-c, 4-d","1-d, 2-b, 3-c, 4-a"],"answer":2,"explanation":"Sweet taste and leftover crystals show sugar is still there; the burst balloon side rises, showing air has weight; the dark-box plant tests light alone; germination shows seeds are alive.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"प्रत्येक वैकल्पिक संकल्पना का मिलान उस गतिविधि से कीजिए जो उसे सबसे अच्छी तरह चुनौती देती है: 1. ‘चीनी पानी में घुलने पर नष्ट हो जाती है।’ 2. ‘हवा का कोई भार नहीं होता।’ 3. ‘पौधों को प्रकाश की आवश्यकता नहीं होती।’ 4. ‘बीज निर्जीव होते हैं।’ a. पानी चखना और उसका कुछ भाग सूखने देना ताकि देखा जा सके कि क्या बचता है। b. एक डंडे पर दो फुलाए हुए गुब्बारे संतुलित करना और एक को फोड़ देना। c. एक गमले का पौधा अँधेरे डिब्बे में और एक प्रकाश में रखना, दोनों को बराबर पानी देना। d. बीजों को भिगोकर बोना और उनकी तुलना सूखे बीजों से करना।","optionsHi":["1-b, 2-a, 3-c, 4-d","1-a, 2-b, 3-d, 4-c","1-a, 2-b, 3-c, 4-d","1-d, 2-b, 3-c, 4-a"],"explanationHi":"मीठा स्वाद और बची हुई क्रिस्टल दिखाते हैं कि चीनी अब भी मौजूद है; गुब्बारा फोड़ने पर उसकी ओर का सिरा ऊपर उठता है, जिससे पता चलता है कि हवा का भार होता है; अँधेरे डिब्बे का पौधा केवल प्रकाश को परखता है; अंकुरण दिखाता है कि बीज जीवित होते हैं।"},
  {"id":"cdp-pedagogy-subjects-1529","question":"Which plan for the theme ‘Food’ in Class 4 is the most integrated?","options":["Reading the chapter on food carefully, answering all its questions and drawing a balanced plate in the notebook","A science period on nutrients and their sources, followed by a short written test on the different vitamins","Learning the names of common food grains and pulses in English and Hindi and writing them in a neat chart","Surveying home breakfasts and graphing them, writing a family recipe, discussing who cooks, and planting herbs"],"answer":3,"explanation":"The last plan brings in mathematics, language, gender roles and growing food around one theme, starting from children’s homes. The others stay within one subject or one skill.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 4 में ‘भोजन’ विषय के लिए कौन-सी योजना सबसे अधिक एकीकृत है?","optionsHi":["भोजन वाले अध्याय को ध्यान से पढ़ना, उसके सभी प्रश्नों के उत्तर देना और कॉपी में संतुलित थाली बनाना","पोषक तत्वों और उनके स्रोतों पर विज्ञान का एक पीरियड, उसके बाद विभिन्न विटामिनों पर एक छोटी लिखित परीक्षा","सामान्य अनाजों और दालों के नाम अंग्रेज़ी और हिंदी में सीखना और उन्हें साफ़-सुथरे चार्ट में लिखना","घरों के नाश्ते का सर्वेक्षण करके उनका ग्राफ़ बनाना, पारिवारिक व्यंजन लिखना, चर्चा करना कि खाना कौन बनाता है, और जड़ी-बूटियाँ उगाना"],"explanationHi":"अंतिम योजना बच्चों के घरों से शुरू करके गणित, भाषा, लैंगिक भूमिकाओं और भोजन उगाने को एक ही विषय के आसपास लाती है। अन्य योजनाएँ एक ही विषय या एक ही कौशल तक सीमित रहती हैं।"},
  {"id":"cdp-pedagogy-subjects-1530","question":"A school ranks Class 4 children by their EVS test marks and puts the list on the noticeboard. The strongest criticism of this practice is that it:","options":["takes up noticeboard space that would be better used for displaying children's drawings and project work","encourages comparison and labelling, discouraging many children instead of showing each child's progress","does not give the top-scoring children any reward or certificate beyond seeing their names on the list","is done after every test, when such a ranking list should really be put up only once a year"],"answer":1,"explanation":"Public ranking turns assessment into competition and labels; CCE stresses each child’s progress and descriptive feedback. Doing it less often does not fix the problem.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक विद्यालय कक्षा 4 के बच्चों को उनके EVS परीक्षा-अंकों के आधार पर क्रम देता है और सूची सूचना-पट्ट पर लगा देता है। इस अभ्यास की सबसे कड़ी आलोचना यह है कि यह:","optionsHi":["सूचना-पट्ट की उस जगह को घेरता है जिसका बेहतर उपयोग बच्चों के चित्र और परियोजना कार्य प्रदर्शित करने में होता","तुलना और ठप्पा लगाने को प्रोत्साहित करता है, और हर बच्चे की प्रगति दिखाने के बजाय कई बच्चों को हतोत्साहित करता है","सर्वाधिक अंक पाने वाले बच्चों को सूची में नाम देखने के अलावा कोई पुरस्कार या प्रमाणपत्र नहीं देता","हर परीक्षा के बाद किया जाता है, जबकि ऐसी क्रम-सूची वर्ष में केवल एक बार लगनी चाहिए"],"explanationHi":"सार्वजनिक क्रम-निर्धारण आकलन को प्रतियोगिता और ठप्पों में बदल देता है; CCE हर बच्चे की प्रगति और वर्णनात्मक प्रतिपुष्टि पर बल देता है। इसे कम बार करने से समस्या हल नहीं होती।"},
  {"id":"cdp-pedagogy-subjects-1531","question":"During a lesson on soil, some Class 4 girls refuse to touch earthworms, saying, ‘Girls get scared of such things.’ The teacher’s best response is to:","options":["let only the boys handle the earthworms, since girls are naturally more sensitive and easily frightened by such creatures","tell the girls firmly to handle the earthworms at once, or they will lose marks for the practical activity","handle the earthworms gently herself, invite each child to try at their own pace, and discuss how fears are learnt","skip the earthworm activity altogether, so that no child in the class is made to feel uncomfortable"],"answer":2,"explanation":"The remark repeats a learnt gender script. Modelling, gentle encouragement and discussion challenge it without force; excusing girls or forcing them both reinforce problems.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"मिट्टी पर एक पाठ के दौरान कक्षा 4 की कुछ लड़कियाँ केंचुओं को छूने से मना कर देती हैं और कहती हैं, ‘लड़कियाँ ऐसी चीज़ों से डरती हैं।’ शिक्षिका की सबसे अच्छी प्रतिक्रिया है:","optionsHi":["केंचुओं को केवल लड़कों को छूने देना, क्योंकि लड़कियाँ स्वभाव से अधिक संवेदनशील होती हैं और ऐसे जीवों से आसानी से डर जाती हैं","लड़कियों से दृढ़ता से कहना कि वे तुरंत केंचुए उठाएँ, नहीं तो व्यावहारिक गतिविधि में उनके अंक कट जाएँगे","स्वयं केंचुओं को कोमलता से उठाना, हर बच्चे को अपनी गति से प्रयास करने के लिए आमंत्रित करना, और इस पर चर्चा करना कि डर कैसे सीखे जाते हैं","केंचुओं की गतिविधि को पूरी तरह छोड़ देना, ताकि कक्षा के किसी भी बच्चे को असहज न होना पड़े"],"explanationHi":"यह टिप्पणी सीखी हुई लैंगिक पटकथा को दोहराती है। आदर्श प्रस्तुत करना, कोमल प्रोत्साहन और चर्चा बिना ज़बरदस्ती के उसे चुनौती देते हैं; लड़कियों को छूट देना या उन पर दबाव डालना, दोनों समस्याओं को पुष्ट करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1532","question":"After a visit to a vegetable farm, Class 5 children have made notes of very different quality and depth. The most useful follow-up activity is to:","options":["collect the best notebook and read it aloud to the class, so that everyone knows what a model answer looks like","give a short written test on the farm visit, to check which children paid attention during the trip","ask the children to copy the teacher's summary of the visit, so that all of them have complete and correct notes","let groups pool their observations into a shared chart and list the questions still unanswered"],"answer":3,"explanation":"Pooling lets every child contribute and learn from others, and listing open questions keeps the inquiry going. A model answer or copied summary sidelines most children’s observations.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"सब्ज़ी के खेत की यात्रा के बाद कक्षा 5 के बच्चों ने बहुत अलग-अलग गुणवत्ता और गहराई के नोट्स बनाए हैं। सबसे उपयोगी अनुवर्ती गतिविधि है:","optionsHi":["सबसे अच्छी कॉपी लेकर कक्षा को पढ़कर सुनाना, ताकि सबको पता चले कि आदर्श उत्तर कैसा होता है","खेत की यात्रा पर एक छोटी लिखित परीक्षा लेना, यह जाँचने के लिए कि यात्रा के दौरान किन बच्चों ने ध्यान दिया","बच्चों से शिक्षिका का यात्रा-सारांश उतारने को कहना, ताकि सबके पास पूर्ण और सही नोट्स हों","समूहों को अपने अवलोकन मिलाकर एक साझा चार्ट बनाने देना और अनुत्तरित प्रश्नों की सूची बनाना"],"explanationHi":"अवलोकन मिलाने से हर बच्चा योगदान दे पाता है और दूसरों से सीखता है, तथा खुले प्रश्नों की सूची बनाने से जाँच-पड़ताल जारी रहती है। आदर्श उत्तर या उतारा हुआ सारांश अधिकांश बच्चों के अवलोकनों को किनारे कर देता है।"},
  {"id":"cdp-pedagogy-subjects-1533","question":"Looking at a bird’s nest, a teacher wants to move Class 3 children from observing to reasoning. Which sequence of questions does this best?","options":["Why did the bird build it? → What is it made of? → What is this thing called? → Now draw it neatly in your notebook.","What do you see? → How is it unlike last week's nest? → Why is it built this way? → What if it were on the ground?","Is it a nest? → Is it big or small? → Is it brown or grey? → Is it made of twigs? → Is it up in a tree?","Name the bird that built it. → Name the colour of its eggs. → Name its food. → Name the animals that hunt it for food."],"answer":1,"explanation":"Good questioning moves from observation to comparison to explanation to prediction. The others are disordered, closed or recall-based.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs","questionHi":"चिड़िया का घोंसला देखते हुए एक शिक्षिका कक्षा 3 के बच्चों को अवलोकन से तर्क की ओर ले जाना चाहती है। प्रश्नों का कौन-सा क्रम इसे सबसे अच्छी तरह करता है?","optionsHi":["चिड़िया ने इसे क्यों बनाया? → यह किससे बना है? → इस चीज़ को क्या कहते हैं? → अब इसे अपनी कॉपी में साफ़-सुथरा बनाओ।","तुम्हें क्या दिखता है? → यह पिछले सप्ताह के घोंसले से कैसे अलग है? → इसे इस तरह क्यों बनाया गया है? → अगर यह ज़मीन पर होता तो क्या होता?","क्या यह घोंसला है? → क्या यह बड़ा है या छोटा? → क्या यह भूरा है या स्लेटी? → क्या यह तिनकों से बना है? → क्या यह पेड़ पर ऊपर है?","इसे बनाने वाली चिड़िया का नाम बताओ। → उसके अंडों का रंग बताओ। → उसके भोजन का नाम बताओ। → उन जानवरों के नाम बताओ जो उसका शिकार करके खाते हैं।"],"explanationHi":"अच्छे प्रश्न-कौशल में अवलोकन से तुलना, फिर स्पष्टीकरण और फिर पूर्वानुमान की ओर बढ़ा जाता है। अन्य क्रम अव्यवस्थित, बंद या केवल याद करने वाले हैं।"},
  {"id":"cdp-pedagogy-subjects-1534","question":"A Class 4 child with dyslexia understands EVS ideas well in discussion but scores poorly on written EVS tests. The most appropriate step is to:","options":["give the child extra written tests for practice, since regular writing practice will improve the scores","record in the report card that the child is weak in EVS, so that parents can arrange extra tuition","excuse the child from all EVS assessment, so that the child is not stressed by tasks that are too hard to do","assess the child also through oral answers, drawings and practical tasks, so that EVS learning is measured"],"answer":3,"explanation":"The written test measures reading and writing more than EVS for this child. Varied modes of assessment let the learning show; excusing the child from assessment is not inclusion.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 का डिस्लेक्सिया से ग्रस्त एक बच्चा चर्चा में EVS के विचारों को अच्छी तरह समझता है, पर लिखित EVS परीक्षाओं में कम अंक पाता है। सबसे उचित कदम है:","optionsHi":["बच्चे को अभ्यास के लिए अतिरिक्त लिखित परीक्षाएँ देना, क्योंकि नियमित लेखन-अभ्यास से अंक सुधरेंगे","रिपोर्ट कार्ड में लिखना कि बच्चा EVS में कमज़ोर है, ताकि माता-पिता अतिरिक्त ट्यूशन की व्यवस्था करें","बच्चे को सभी EVS आकलन से छूट देना, ताकि वह बहुत कठिन कार्यों से तनाव में न आए","बच्चे का आकलन मौखिक उत्तरों, चित्रों और व्यावहारिक कार्यों से भी करना, ताकि EVS अधिगम को मापा जा सके"],"explanationHi":"इस बच्चे के लिए लिखित परीक्षा EVS से अधिक पठन और लेखन को मापती है। आकलन के विविध तरीके अधिगम को सामने आने देते हैं; बच्चे को आकलन से छूट देना समावेशन नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1535","question":"Assertion (A): Children’s alternative conceptions in EVS are best removed by giving them the correct definition early. Reason (R): Children can memorise a definition without changing the way they actually think about the idea. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"R is true, and it is exactly why A is false: a memorised definition can sit alongside an unchanged alternative idea. Conceptual change needs experience and reasoning.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"अभिकथन (A): EVS में बच्चों की वैकल्पिक संकल्पनाओं को दूर करने का सबसे अच्छा तरीका उन्हें शुरू में ही सही परिभाषा देना है। कारण (R): बच्चे किसी परिभाषा को रट सकते हैं, जबकि उस विचार के बारे में उनके वास्तविक सोचने का ढंग नहीं बदलता। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"R सही है, और ठीक यही कारण है कि A गलत है: रटी हुई परिभाषा बिना बदली हुई वैकल्पिक धारणा के साथ बनी रह सकती है। संकल्पनात्मक परिवर्तन के लिए अनुभव और तर्क की आवश्यकता होती है।"},
  {"id":"cdp-pedagogy-subjects-1536","question":"Class 3 children, most of whom cannot yet write fluently, are to record the number of birds they see in the school garden each day for a week. The most suitable way is:","options":["writing a paragraph each day about the birds","copying the teacher’s record from the board","making a picture table with tally marks for each kind of bird","remembering the numbers and telling them at the end of the week"],"answer":2,"explanation":"Picture tables with tally marks let young children record accurately without fluent writing, and the data can later be compared. Memory and copying are unreliable or passive.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 3 के बच्चे, जिनमें से अधिकांश अभी धाराप्रवाह नहीं लिख सकते, एक सप्ताह तक हर दिन विद्यालय के बगीचे में दिखने वाले पक्षियों की संख्या दर्ज करेंगे। सबसे उपयुक्त तरीका है:","optionsHi":["हर दिन पक्षियों के बारे में एक अनुच्छेद लिखना","श्यामपट्ट से शिक्षिका का अभिलेख उतारना","हर प्रकार के पक्षी के लिए गिनती-चिह्नों (tally marks) वाली चित्र-सारणी बनाना","संख्याएँ याद रखना और सप्ताह के अंत में बता देना"],"explanationHi":"गिनती-चिह्नों वाली चित्र-सारणियाँ छोटे बच्चों को धाराप्रवाह लेखन के बिना सटीक अभिलेख रखने देती हैं, और आँकड़ों की बाद में तुलना की जा सकती है। स्मृति और उतारना अविश्वसनीय या निष्क्रिय हैं।"},
  {"id":"cdp-pedagogy-subjects-1537","question":"The NCERT EVS books often ask, ‘Look at the picture. What is happening here?’ The main purpose of such picture-based questions is to:","options":["build observation and interpretation, and let children who cannot yet read well take part","fill space in the book attractively, so that young children do not lose interest in the printed text","test children's drawing skills, since they are expected to copy each picture into their notebooks","replace reading in EVS, since pictures are easier for children to understand than written sentences"],"answer":0,"explanation":"Picture reading is itself a sub-skill of observation and recording, and it gives every child a way in regardless of reading level. It does not replace reading.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"NCERT की EVS पुस्तकों में प्रायः पूछा जाता है, ‘चित्र देखो। यहाँ क्या हो रहा है?’ ऐसे चित्र-आधारित प्रश्नों का मुख्य उद्देश्य है:","optionsHi":["अवलोकन और व्याख्या का विकास करना, और जो बच्चे अभी अच्छी तरह पढ़ नहीं सकते उन्हें भाग लेने देना","पुस्तक में जगह को आकर्षक ढंग से भरना, ताकि छोटे बच्चे छपे पाठ में रुचि न खोएँ","बच्चों की चित्रकला का परीक्षण करना, क्योंकि उनसे हर चित्र को अपनी कॉपी में उतारने की अपेक्षा है","EVS में पठन की जगह लेना, क्योंकि चित्र लिखित वाक्यों से अधिक आसानी से समझ आते हैं"],"explanationHi":"चित्र-पठन स्वयं अवलोकन और अभिलेखन का एक उप-कौशल है, और यह पठन-स्तर की परवाह किए बिना हर बच्चे को प्रवेश का रास्ता देता है। यह पठन का स्थान नहीं लेता।"},
  {"id":"cdp-pedagogy-subjects-1538","question":"Which statement best describes the relationship between primary EVS and the separate science and social science subjects taught from Class VI?","options":["EVS covers parts of the Class VI science syllabus early, so that the later classes become easier for children","EVS is unrelated to the later subjects and serves mainly to keep young children engaged and interested in school","EVS lays a foundation of curiosity, process skills and nature-society links, on which the later subjects build","EVS is simply a shortened, simplified version of the Class VI textbooks, with more pictures and fewer words"],"answer":2,"explanation":"EVS is not a compressed version of later subjects; it lays foundations of inquiry and integrated understanding, which the disciplines later develop separately.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"प्राथमिक EVS और कक्षा VI से पढ़ाए जाने वाले अलग-अलग विज्ञान तथा सामाजिक विज्ञान विषयों के बीच संबंध को कौन-सा कथन सबसे अच्छी तरह बताता है?","optionsHi":["EVS कक्षा VI के विज्ञान पाठ्यक्रम के कुछ भाग पहले ही पढ़ा देता है, ताकि आगे की कक्षाएँ बच्चों के लिए आसान हो जाएँ","EVS का बाद के विषयों से कोई संबंध नहीं है और वह मुख्यतः छोटे बच्चों को विद्यालय में व्यस्त और रुचिशील रखने का काम करता है","EVS जिज्ञासा, प्रक्रिया कौशल और प्रकृति-समाज संबंधों की नींव रखता है, जिस पर बाद के विषय आगे बढ़ते हैं","EVS कक्षा VI की पाठ्यपुस्तकों का संक्षिप्त, सरल रूप मात्र है, जिसमें चित्र अधिक और शब्द कम होते हैं"],"explanationHi":"EVS बाद के विषयों का संकुचित रूप नहीं है; वह जाँच-पड़ताल और एकीकृत समझ की नींव रखता है, जिसे अनुशासन बाद में अलग-अलग विकसित करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1539","question":"Once Class 5 children accept that clouds are made of tiny drops of water, the teacher asks them to use the same idea to explain morning fog and the mist on a bathroom mirror. In the conceptual-change model, this step mainly shows children that the new idea is:","options":["intelligible","a cause of dissatisfaction","plausible","fruitful"],"answer":3,"explanation":"An idea is fruitful when it helps explain new situations. Intelligibility concerns understanding it, plausibility concerns believing it, and dissatisfaction concerns the old idea.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के बच्चे जब यह मान लेते हैं कि बादल पानी की बहुत छोटी बूँदों से बने होते हैं, तो शिक्षिका उनसे इसी विचार से सुबह की धुंध और बाथरूम के शीशे पर जमी नमी की व्याख्या करने को कहती है। संकल्पनात्मक परिवर्तन के मॉडल में यह चरण मुख्यतः बच्चों को दिखाता है कि नया विचार है:","optionsHi":["बोधगम्य (intelligible)","असंतोष का कारण","विश्वसनीय (plausible)","फलदायी (fruitful)"],"explanationHi":"कोई विचार तब फलदायी होता है जब वह नई स्थितियों की व्याख्या करने में मदद करता है। बोधगम्यता उसे समझने से, विश्वसनीयता उस पर विश्वास करने से, और असंतोष पुराने विचार से संबंधित है।"},
  {"id":"cdp-pedagogy-subjects-1540","question":"Class 5 children lead Class 3 children on a nature walk around the school, pointing out plants and insects. Which statement about this arrangement is most accurate?","options":["Only the Class 3 children learn; the Class 5 children lose time that should go to their own syllabus","Both groups learn: younger ones get guidance, and older ones deepen understanding by explaining","It works only if the teacher stays silent throughout, so that the older children feel fully in charge","It removes the need for the teacher to plan the walk, since the older children already know the area"],"answer":1,"explanation":"Peer tutoring benefits both sides; explaining makes older children organise and check their own knowledge. The teacher still plans and supports.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 5 के बच्चे कक्षा 3 के बच्चों को विद्यालय के चारों ओर प्रकृति-भ्रमण पर ले जाते हैं और पौधों तथा कीटों की ओर संकेत करते हैं। इस व्यवस्था के बारे में कौन-सा कथन सबसे सटीक है?","optionsHi":["केवल कक्षा 3 के बच्चे सीखते हैं; कक्षा 5 के बच्चों का वह समय बर्बाद होता है जो उनके अपने पाठ्यक्रम को मिलना चाहिए","दोनों समूह सीखते हैं: छोटे बच्चों को मार्गदर्शन मिलता है, और बड़े बच्चे समझाकर अपनी समझ गहरी करते हैं","यह तभी काम करता है जब शिक्षिका पूरे समय चुप रहे, ताकि बड़े बच्चे पूरी तरह प्रभारी महसूस करें","इससे शिक्षिका को भ्रमण की योजना बनाने की आवश्यकता नहीं रहती, क्योंकि बड़े बच्चे क्षेत्र को पहले से जानते हैं"],"explanationHi":"सहपाठी-शिक्षण दोनों पक्षों को लाभ देता है; समझाने से बड़े बच्चे अपने ज्ञान को व्यवस्थित करते और जाँचते हैं। शिक्षिका को फिर भी योजना बनानी और सहयोग देना होता है।"},
  {"id":"cdp-pedagogy-subjects-1541","question":"A textbook picture of ‘an Indian village’ shows only mud huts, a well and a bullock cart. Children in a city school conclude that all villages look like this. The teacher’s best response is to:","options":["agree with them, since the textbook picture has been chosen by experts to show a typical village","tell them that villages no longer look like that, since all of them now have pucca houses and roads","show photographs of many kinds of villages and discuss how villages differ and change","ask them to copy the picture carefully into their notebooks and label each part of the village"],"answer":2,"explanation":"A single picture can become a stereotype. Showing variety and change corrects the generalisation and teaches children to read pictures critically.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"पाठ्यपुस्तक में ‘भारतीय गाँव’ का एक चित्र केवल मिट्टी की झोपड़ियाँ, एक कुआँ और एक बैलगाड़ी दिखाता है। शहरी विद्यालय के बच्चे निष्कर्ष निकालते हैं कि सभी गाँव ऐसे ही दिखते हैं। शिक्षिका की सबसे अच्छी प्रतिक्रिया है:","optionsHi":["उनसे सहमत होना, क्योंकि पाठ्यपुस्तक का चित्र विशेषज्ञों ने एक विशिष्ट गाँव दिखाने के लिए चुना है","उन्हें बताना कि अब गाँव ऐसे नहीं दिखते, क्योंकि उन सबमें अब पक्के घर और सड़कें हैं","अनेक प्रकार के गाँवों की तस्वीरें दिखाना और चर्चा करना कि गाँव कैसे अलग-अलग होते और बदलते हैं","उनसे चित्र को ध्यान से अपनी कॉपी में उतारने और गाँव के हर भाग को नामांकित करने को कहना"],"explanationHi":"एक अकेला चित्र रूढ़ छवि बन सकता है। विविधता और बदलाव दिखाने से सामान्यीकरण सुधरता है और बच्चे चित्रों को आलोचनात्मक ढंग से पढ़ना सीखते हैं।"},
  {"id":"cdp-pedagogy-subjects-1542","question":"For a survey on plastic use, a Class 5 group writes the question, ‘Don’t you think plastic bags are harmful?’ The main problem with this question, and the best fix, is:","options":["it is too long for a survey; shorten it to ‘Plastic bags: harmful?’ so that people answer quickly","it should be asked only to shopkeepers, since they handle far more plastic bags than ordinary families","it is informal; it should be rewritten in English, since survey questions must use formal language","it is a leading question; ask instead, ‘What bag do you usually use for shopping, and why?’"],"answer":3,"explanation":"A leading question pushes people towards one answer and biases the data. A neutral, open question gathers real information about practices and reasons.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"प्लास्टिक के उपयोग पर एक सर्वेक्षण के लिए कक्षा 5 का एक समूह प्रश्न लिखता है, ‘क्या आपको नहीं लगता कि प्लास्टिक की थैलियाँ हानिकारक हैं?’ इस प्रश्न की मुख्य समस्या और सबसे अच्छा सुधार है:","optionsHi":["यह सर्वेक्षण के लिए बहुत लंबा है; इसे छोटा करके ‘प्लास्टिक थैलियाँ: हानिकारक?’ कर दें ताकि लोग जल्दी उत्तर दें","इसे केवल दुकानदारों से पूछा जाना चाहिए, क्योंकि वे सामान्य परिवारों से कहीं अधिक प्लास्टिक थैलियाँ संभालते हैं","यह अनौपचारिक है; इसे अंग्रेज़ी में फिर से लिखा जाना चाहिए, क्योंकि सर्वेक्षण के प्रश्नों में औपचारिक भाषा होनी चाहिए","यह एक प्रेरक (leading) प्रश्न है; इसके बजाय पूछें, ‘आप खरीदारी के लिए सामान्यतः कौन-सा थैला इस्तेमाल करते हैं, और क्यों?’"],"explanationHi":"प्रेरक प्रश्न लोगों को एक ही उत्तर की ओर धकेलता है और आँकड़ों में पक्षपात लाता है। तटस्थ, खुला प्रश्न व्यवहारों और कारणों के बारे में वास्तविक जानकारी जुटाता है।"},
  {"id":"cdp-pedagogy-subjects-1543","question":"Which of these is an example of first-hand (experiential) rather than second-hand learning in EVS?","options":["Watching a close-up video that shows step by step how rice is cooked","Tasting and feeling raw and cooked rice and describing the differences","Reading a story about a rice farmer and his family during the harvest","Listening to the teacher describe a paddy field she visited as a child"],"answer":1,"explanation":"Tasting and handling the rice is direct sensory experience. Video, stories and descriptions are useful but second-hand.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"इनमें से कौन-सा EVS में द्वितीयक अधिगम के बजाय प्रत्यक्ष (अनुभवजन्य) अधिगम का उदाहरण है?","optionsHi":["ऐसा क्लोज़-अप वीडियो देखना जो चरण-दर-चरण दिखाता है कि चावल कैसे पकाया जाता है","कच्चे और पके चावल को चखना, छूना और उनके अंतर का वर्णन करना","फ़सल कटाई के समय एक चावल किसान और उसके परिवार के बारे में कहानी पढ़ना","शिक्षिका को उस धान के खेत का वर्णन करते सुनना जो उसने बचपन में देखा था"],"explanationHi":"चावल को चखना और छूना प्रत्यक्ष संवेदी अनुभव है। वीडियो, कहानियाँ और वर्णन उपयोगी हैं, पर वे द्वितीयक हैं।"},
  {"id":"cdp-pedagogy-subjects-1544","question":"At the end of each EVS lesson, a Class 4 teacher asks children to write or draw on a slip ‘one thing I learnt today’ and ‘one thing I am still wondering about’. This practice mainly serves to:","options":["give the teacher quick feedback on learning and help children reflect","collect marks for each child that can be added up for the term-end report card","keep children quietly busy in the last five minutes before the bell rings","check children’s handwriting and spelling regularly in a low-stress way"],"answer":0,"explanation":"Exit slips are a formative tool: the teacher sees what was understood and what puzzles remain, and children reflect on their own learning.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"हर EVS पाठ के अंत में कक्षा 4 की शिक्षिका बच्चों से एक पर्ची पर ‘आज मैंने एक बात सीखी’ और ‘एक बात के बारे में मैं अब भी सोच रहा/रही हूँ’ लिखने या बनाने को कहती है। यह अभ्यास मुख्यतः किस काम आता है?","optionsHi":["शिक्षिका को अधिगम पर त्वरित प्रतिपुष्टि देना और बच्चों को चिंतन करने में मदद करना","हर बच्चे के अंक जुटाना जिन्हें सत्रांत रिपोर्ट कार्ड के लिए जोड़ा जा सके","घंटी बजने से पहले अंतिम पाँच मिनट में बच्चों को चुपचाप व्यस्त रखना","बच्चों की लिखावट और वर्तनी की नियमित रूप से तनाव-मुक्त ढंग से जाँच करना"],"explanationHi":"निकास-पर्चियाँ एक रचनात्मक उपकरण हैं: शिक्षिका देखती है कि क्या समझा गया और कौन-सी उलझनें बाकी हैं, और बच्चे अपने अधिगम पर चिंतन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1545","question":"A Class 4 child says, ‘All snakes are poisonous, so my father kills every snake he sees.’ The teacher’s best response is to:","options":["agree with the child, since snakes are dangerous and a family has to protect itself from every one of them","say firmly that killing snakes is a crime under wildlife law and that the father should be reported for it","explain that most snakes are not venomous and help farmers by eating rats, while teaching how to stay safe","avoid the topic, since it concerns the child’s family and the teacher should not question parents’ practices"],"answer":2,"explanation":"The response corrects the over-generalisation, shows the snake’s role in the ecosystem and keeps safety in view, without blaming the family.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 4 का एक बच्चा कहता है, ‘सभी साँप ज़हरीले होते हैं, इसलिए मेरे पिताजी जो भी साँप देखते हैं उसे मार देते हैं।’ शिक्षिका की सबसे अच्छी प्रतिक्रिया है:","optionsHi":["बच्चे से सहमत होना, क्योंकि साँप खतरनाक होते हैं और परिवार को उनमें से हर एक से अपनी रक्षा करनी होती है","दृढ़ता से कहना कि साँपों को मारना वन्यजीव कानून के तहत अपराध है और पिता की शिकायत की जानी चाहिए","समझाना कि अधिकांश साँप विषैले नहीं होते और चूहों को खाकर किसानों की मदद करते हैं, साथ ही सुरक्षित रहना सिखाना","इस विषय से बचना, क्योंकि यह बच्चे के परिवार से जुड़ा है और शिक्षिका को माता-पिता के व्यवहारों पर प्रश्न नहीं उठाना चाहिए"],"explanationHi":"यह प्रतिक्रिया अति-सामान्यीकरण को सुधारती है, पारिस्थितिक तंत्र में साँप की भूमिका दिखाती है और सुरक्षा को ध्यान में रखती है, परिवार को दोष दिए बिना।"},
  {"id":"cdp-pedagogy-subjects-1546","question":"Which of these statements about teaching–learning materials in EVS are correct? I. Good material lets children handle and explore it. II. Teacher-made material from local resources can be as effective as bought material. III. Once made, a piece of material can be used for every topic. IV. Material must be checked for accuracy and bias before use.","options":["I and II only","I, II and III only","II, III and IV only","I, II and IV only"],"answer":3,"explanation":"Material is chosen for a purpose and topic, so III is wrong. Hands-on use, the value of local material and checking for accuracy and bias are all sound principles.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"EVS में शिक्षण-अधिगम सामग्री के बारे में इनमें से कौन-से कथन सही हैं? I. अच्छी सामग्री बच्चों को उसे छूने और उसकी खोजबीन करने देती है। II. स्थानीय संसाधनों से शिक्षक द्वारा बनाई सामग्री खरीदी हुई सामग्री जितनी ही प्रभावी हो सकती है। III. एक बार बनने के बाद सामग्री का एक टुकड़ा हर विषय के लिए इस्तेमाल हो सकता है। IV. उपयोग से पहले सामग्री की शुद्धता और पक्षपात की जाँच की जानी चाहिए।","optionsHi":["केवल I और II","केवल I, II और III","केवल II, III और IV","केवल I, II और IV"],"explanationHi":"सामग्री किसी उद्देश्य और विषय के लिए चुनी जाती है, इसलिए III गलत है। हाथों से करके उपयोग, स्थानीय सामग्री का महत्व और शुद्धता तथा पक्षपात की जाँच, ये सभी सही सिद्धांत हैं।"},
  {"id":"cdp-pedagogy-subjects-1547","question":"A Class 5 group submits a beautiful model of a water-harvesting system, and the teacher learns that a parent made most of it. For assessing the project, the best approach is to:","options":["give full marks, since the model is excellent and the children did choose the topic and plan the model themselves","assess the process, such as the children’s records, explanations and participation, and do more work in school","give zero marks to the group and stop project work, since it always ends up being done by the parents","ask the parent to explain the model to the class, since the parent clearly understands the system best"],"answer":1,"explanation":"Assessing the product alone rewards outside help; looking at the process shows what the children learnt. Doing more of the work in school reduces the problem; dropping projects loses their value.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 5 का एक समूह जल-संचयन प्रणाली का सुंदर मॉडल जमा करता है, और शिक्षिका को पता चलता है कि उसका अधिकांश भाग किसी अभिभावक ने बनाया है। परियोजना के आकलन के लिए सबसे अच्छा तरीका है:","optionsHi":["पूरे अंक देना, क्योंकि मॉडल उत्कृष्ट है और बच्चों ने विषय स्वयं चुना तथा मॉडल की योजना स्वयं बनाई","प्रक्रिया का आकलन करना, जैसे बच्चों के अभिलेख, स्पष्टीकरण और भागीदारी, और अधिक कार्य विद्यालय में करवाना","समूह को शून्य अंक देना और परियोजना कार्य बंद कर देना, क्योंकि वह हमेशा अभिभावकों द्वारा ही कर दिया जाता है","अभिभावक से कक्षा को मॉडल समझाने को कहना, क्योंकि अभिभावक प्रणाली को स्पष्ट रूप से सबसे अच्छी तरह समझते हैं"],"explanationHi":"केवल उत्पाद का आकलन बाहरी सहायता को पुरस्कृत करता है; प्रक्रिया को देखने से पता चलता है कि बच्चों ने क्या सीखा। विद्यालय में अधिक कार्य करवाने से समस्या घटती है; परियोजनाएँ छोड़ देने से उनका मूल्य खो जाता है।"},
  {"id":"cdp-pedagogy-subjects-1548","question":"Two Class 5 children submit concept maps on ‘Water’. Riya’s map has many words joined by plain lines with no labels. Sameer’s map has fewer words, but every line carries a linking phrase such as ‘is stored in’ or ‘is used for’. Which conclusion is most justified?","options":["Sameer’s map shows more understanding, because his labelled links state how the ideas are related","Riya’s map shows better understanding, because it covers many more concepts linked to the topic of water","Both maps show the same level of understanding, since both children have connected all their words with lines","Neither map can show understanding, since concept maps really measure only how much a child has memorised"],"answer":0,"explanation":"In a concept map, meaning lies in the propositions made by labelled links. Many unlinked words show recall; fewer words with explicit relationships show understanding.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 5 के दो बच्चे ‘जल’ पर संकल्पना मानचित्र जमा करते हैं। रिया के मानचित्र में बहुत से शब्द हैं जो बिना नाम वाली सादी रेखाओं से जुड़े हैं। समीर के मानचित्र में शब्द कम हैं, पर हर रेखा पर ‘में संचित होता है’ या ‘के लिए उपयोग होता है’ जैसा संयोजक पदबंध है। कौन-सा निष्कर्ष सबसे अधिक उचित है?","optionsHi":["समीर का मानचित्र अधिक समझ दिखाता है, क्योंकि उसके नामांकित संबंध बताते हैं कि विचार आपस में कैसे संबंधित हैं","रिया का मानचित्र बेहतर समझ दिखाता है, क्योंकि उसमें जल के विषय से जुड़ी कहीं अधिक संकल्पनाएँ शामिल हैं","दोनों मानचित्र समान स्तर की समझ दिखाते हैं, क्योंकि दोनों बच्चों ने अपने सभी शब्दों को रेखाओं से जोड़ा है","कोई भी मानचित्र समझ नहीं दिखा सकता, क्योंकि संकल्पना मानचित्र वास्तव में केवल यह मापते हैं कि बच्चे ने कितना रटा है"],"explanationHi":"संकल्पना मानचित्र में अर्थ नामांकित संबंधों से बने कथनों में होता है। बहुत से बिना जुड़े शब्द स्मरण दिखाते हैं; कम शब्द पर स्पष्ट संबंध समझ दिखाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1549","question":"Which of the following pairs are correctly matched? 1. Cognitive validity: language and concepts suited to the learner's age. 2. Content validity: showing how scientific ideas changed over time. 3. Process validity: learning how scientific knowledge is generated and validated. 4. Ethical validity: honesty, objectivity and concern for life.","options":["1, 3 and 4 only","1 and 2 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"Showing how ideas changed over time is historical validity; content validity is about conveying significant and correct science. The other three pairs are correctly matched.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"निम्नलिखित में से कौन-से युग्म सही मिलाए गए हैं? 1. संज्ञानात्मक वैधता: अधिगमकर्ता की आयु के अनुकूल भाषा और संकल्पनाएँ। 2. विषय-वस्तु वैधता: यह दिखाना कि वैज्ञानिक विचार समय के साथ कैसे बदले। 3. प्रक्रिया वैधता: यह सीखना कि वैज्ञानिक ज्ञान कैसे उत्पन्न और प्रमाणित होता है। 4. नैतिक वैधता: ईमानदारी, वस्तुनिष्ठता और जीवन के प्रति चिंता।","optionsHi":["केवल 1, 3 और 4","केवल 1 और 2","केवल 2, 3 और 4","1, 2, 3 और 4"],"explanationHi":"विचारों के समय के साथ बदलने को दिखाना ऐतिहासिक वैधता है; विषय-वस्तु वैधता महत्वपूर्ण और सही विज्ञान पहुँचाने से संबंधित है। अन्य तीन युग्म सही मिलाए गए हैं।"},
  {"id":"cdp-pedagogy-subjects-1550","question":"Assertion (A): Creating cognitive conflict alone is often not enough to bring about conceptual change in science. Reason (R): Learners also need a new idea that they find intelligible and plausible to replace the old one.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Conflict may make a learner dissatisfied, but without an understandable and believable alternative she may explain away the evidence or hold both ideas; that is why conflict alone is not enough.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"अभिकथन (A): विज्ञान में संकल्पनात्मक परिवर्तन लाने के लिए अकेले संज्ञानात्मक द्वंद्व पैदा करना प्रायः पर्याप्त नहीं होता। कारण (R): अधिगमकर्ताओं को पुराने विचार की जगह लेने के लिए एक ऐसे नए विचार की भी आवश्यकता होती है जो उन्हें बोधगम्य और विश्वसनीय लगे।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"द्वंद्व अधिगमकर्ता को असंतुष्ट कर सकता है, पर समझ में आने वाले और विश्वसनीय विकल्प के बिना वह साक्ष्य को समझा-बुझाकर टाल सकता है या दोनों विचार रख सकता है; इसीलिए अकेला द्वंद्व पर्याप्त नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1551","question":"Several Class 6 students say that a switch 'makes the electricity' that lights the bulb. Which activity best addresses this idea?","options":["Showing a picture of a power station and explaining how electricity reaches the classroom switch","Building a circuit with a paper-clip switch and seeing the bulb light only when the clip closes the gap","Telling students clearly that cells make the electricity, not switches, and asking them to write it down","Counting the switches in the classroom and noting which light or fan each one turns on and off"],"answer":1,"explanation":"Making their own switch shows that it only opens or closes the path; the cell drives the current. Telling them is weaker than letting them see the switch's real role.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"कक्षा 6 के कई विद्यार्थी कहते हैं कि स्विच ‘बिजली बनाता है’ जिससे बल्ब जलता है। कौन-सी गतिविधि इस विचार को सबसे अच्छी तरह संबोधित करती है?","optionsHi":["विद्युत गृह का चित्र दिखाना और समझाना कि बिजली कक्षा के स्विच तक कैसे पहुँचती है","पेपर-क्लिप के स्विच वाला परिपथ बनाना और देखना कि बल्ब तभी जलता है जब क्लिप खाली स्थान को बंद करता है","विद्यार्थियों को स्पष्ट रूप से बताना कि बिजली सेल बनाते हैं, स्विच नहीं, और उनसे इसे लिखने को कहना","कक्षा में स्विच गिनना और दर्ज करना कि हर स्विच किस बत्ती या पंखे को चालू और बंद करता है"],"explanationHi":"अपना स्विच बनाने से दिखता है कि वह केवल मार्ग को खोलता या बंद करता है; धारा सेल चलाता है। केवल बता देना, स्विच की वास्तविक भूमिका देखने देने से कमज़ोर है।"},
  {"id":"cdp-pedagogy-subjects-1552","question":"A student says the sun goes round the earth, 'because I can see it rise and set every day'. Which activity best helps her consider another explanation?","options":["Drawing the sun's path across the sky at different times of the day in a notebook","Memorising the statement that the earth goes round the sun, as given in the textbook","Turning slowly on a chair beside a lamp and seeing the lamp seem to 'rise' and 'set'","Watching the sun carefully at noon to see that it is directly overhead and not moving"],"answer":2,"explanation":"Spinning on a chair shows that the same apparent motion can be produced by the observer turning, which makes the earth's rotation a plausible alternative to the sun's movement.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"एक विद्यार्थी कहती है कि सूर्य पृथ्वी के चारों ओर घूमता है, ‘क्योंकि मैं उसे हर दिन उगते और डूबते देखती हूँ’। कौन-सी गतिविधि उसे किसी दूसरे स्पष्टीकरण पर विचार करने में सबसे अधिक मदद करती है?","optionsHi":["कॉपी में दिन के अलग-अलग समय पर आकाश में सूर्य का पथ बनाना","यह कथन रट लेना कि पृथ्वी सूर्य के चारों ओर घूमती है, जैसा पाठ्यपुस्तक में दिया है","दीपक के पास कुर्सी पर धीरे-धीरे घूमना और देखना कि दीपक ‘उगता’ और ‘डूबता’ प्रतीत होता है","दोपहर में सूर्य को ध्यान से देखना कि वह ठीक सिर के ऊपर है और हिल नहीं रहा"],"explanationHi":"कुर्सी पर घूमना दिखाता है कि वही आभासी गति प्रेक्षक के घूमने से भी उत्पन्न हो सकती है, जिससे पृथ्वी का घूर्णन सूर्य की गति का एक विश्वसनीय विकल्प बन जाता है।"},
  {"id":"cdp-pedagogy-subjects-1553","question":"Students say there is no gravity in space, because astronauts float in their spacecraft. Which question best challenges this idea?","options":["'Have you seen a video of astronauts floating freely inside the space station?'","'What is the unit of force, and how do we measure the weight of an astronaut?'","'Is it difficult to walk on the moon, and why do astronauts there wear heavy boots?'","'If there were no gravity in space, what would keep the moon going round the earth?'"],"answer":3,"explanation":"The moon's orbit shows that the earth's gravity reaches far into space; astronauts float because they and their craft are falling round the earth together, not because gravity is absent.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"विद्यार्थी कहते हैं कि अंतरिक्ष में गुरुत्वाकर्षण नहीं होता, क्योंकि अंतरिक्ष यात्री अपने यान में तैरते हैं। कौन-सा प्रश्न इस विचार को सबसे अच्छी तरह चुनौती देता है?","optionsHi":["‘क्या तुमने अंतरिक्ष स्टेशन के अंदर अंतरिक्ष यात्रियों को स्वतंत्र रूप से तैरते हुए वीडियो में देखा है?’","‘बल की इकाई क्या है, और हम अंतरिक्ष यात्री का भार कैसे मापते हैं?’","‘क्या चंद्रमा पर चलना कठिन है, और वहाँ अंतरिक्ष यात्री भारी जूते क्यों पहनते हैं?’","‘अगर अंतरिक्ष में गुरुत्वाकर्षण नहीं होता, तो चंद्रमा को पृथ्वी की परिक्रमा करते रहने से क्या रोकता?’"],"explanationHi":"चंद्रमा की कक्षा दिखाती है कि पृथ्वी का गुरुत्वाकर्षण अंतरिक्ष में बहुत दूर तक पहुँचता है; अंतरिक्ष यात्री इसलिए तैरते हैं क्योंकि वे और उनका यान साथ-साथ पृथ्वी के चारों ओर गिर रहे होते हैं, इसलिए नहीं कि गुरुत्वाकर्षण नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1554","question":"Students believe that friction acts only between solid surfaces. Which activity best widens their idea?","options":["Dropping a flat sheet and a crumpled sheet of paper together and comparing their fall","Rubbing their palms together hard and noticing how warm they become after some time","Sliding a book across the floor and then across a rough mat to compare how far it goes","Rolling a pencil on the table and comparing it with sliding the same pencil along it"],"answer":0,"explanation":"The flat sheet falls more slowly because air opposes its motion more; this shows that air (and water) exert frictional force, not just solid surfaces.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"विद्यार्थी मानते हैं कि घर्षण केवल ठोस सतहों के बीच लगता है। कौन-सी गतिविधि उनके विचार को सबसे अच्छी तरह व्यापक बनाती है?","optionsHi":["कागज़ की समतल शीट और मुड़ी-तुड़ी शीट को साथ गिराना और उनके गिरने की तुलना करना","हथेलियों को ज़ोर से रगड़ना और देखना कि कुछ देर बाद वे कितनी गर्म हो जाती हैं","किताब को फ़र्श पर और फिर खुरदरी चटाई पर सरकाना और तुलना करना कि वह कितनी दूर जाती है","मेज़ पर पेंसिल को लुढ़काना और उसकी तुलना उसी पेंसिल को उस पर सरकाने से करना"],"explanationHi":"समतल शीट धीमे गिरती है क्योंकि हवा उसकी गति का अधिक विरोध करती है; इससे पता चलता है कि हवा (और पानी) भी घर्षण बल लगाते हैं, केवल ठोस सतहें ही नहीं।"},
  {"id":"cdp-pedagogy-subjects-1555","question":"Students believe that every part of a plant makes food. Which activity gives the most direct evidence against this idea?","options":["Testing a root and a stem of the plant for starch, since starch shows where food is present","Testing the green and non-green parts of a variegated croton leaf for starch after sunlight","Measuring the length and area of different leaves to see which parts of the plant are largest","Keeping a whole plant in the dark for a week and then observing whether its leaves turn yellow"],"answer":1,"explanation":"Only the green parts of a variegated leaf turn blue-black with iodine, linking food-making to chlorophyll. Starch in roots or stems could have been stored there, so testing them does not settle the question.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"विद्यार्थी मानते हैं कि पौधे का हर भाग भोजन बनाता है। कौन-सी गतिविधि इस विचार के विरुद्ध सबसे सीधा साक्ष्य देती है?","optionsHi":["पौधे की जड़ और तने में स्टार्च की जाँच करना, क्योंकि स्टार्च दिखाता है कि भोजन कहाँ मौजूद है","धूप के बाद चितकबरी क्रोटन पत्ती के हरे और अहरे भागों में स्टार्च की जाँच करना","अलग-अलग पत्तियों की लंबाई और क्षेत्रफल मापना, यह देखने के लिए कि पौधे के कौन-से भाग सबसे बड़े हैं","पूरे पौधे को एक सप्ताह अँधेरे में रखना और फिर देखना कि उसकी पत्तियाँ पीली पड़ती हैं या नहीं"],"explanationHi":"चितकबरी पत्ती के केवल हरे भाग आयोडीन से नीले-काले होते हैं, जो भोजन बनाने को पर्णहरित से जोड़ता है। जड़ों या तनों में स्टार्च वहाँ संचित हो सकता है, इसलिए उनकी जाँच से प्रश्न तय नहीं होता।"},
  {"id":"cdp-pedagogy-subjects-1556","question":"A Class 6 student argues that a butterfly is not an animal 'because animals have four legs and fur'. The teacher's best response is to:","options":["Tell the student that butterflies are insects, not animals, so the answer is actually correct","Accept the answer, since it is partly correct and correcting it now may discourage the student from speaking up","Ask the student to list all the animals shown in the textbook and learn them as the correct examples","List with the class features all animals share, like feeding on others, and test butterflies, fish and birds"],"answer":3,"explanation":"The student is using a narrow everyday meaning of 'animal' (mammals). Working out the scientific defining features shows that insects, fish and birds are animals too.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"कक्षा 6 का एक विद्यार्थी तर्क देता है कि तितली जंतु नहीं है ‘क्योंकि जंतुओं के चार पैर और फर होते हैं’। शिक्षिका की सबसे अच्छी प्रतिक्रिया है:","optionsHi":["विद्यार्थी को बताना कि तितलियाँ कीट हैं, जंतु नहीं, इसलिए उसका उत्तर वास्तव में सही है","उत्तर स्वीकार करना, क्योंकि वह आंशिक रूप से सही है और अभी सुधारने से विद्यार्थी बोलने से हतोत्साहित हो सकता है","विद्यार्थी से पाठ्यपुस्तक में दिखाए सभी जंतुओं की सूची बनवाना और उन्हें सही उदाहरण मानकर सीखने को कहना","कक्षा के साथ उन विशेषताओं की सूची बनाना जो सभी जंतुओं में समान हैं, जैसे दूसरों को खाना, और तितलियों, मछलियों तथा पक्षियों पर उन्हें परखना"],"explanationHi":"विद्यार्थी ‘जंतु’ के संकीर्ण दैनिक अर्थ (स्तनधारी) का उपयोग कर रहा है। वैज्ञानिक परिभाषित विशेषताओं को निकालने से पता चलता है कि कीट, मछलियाँ और पक्षी भी जंतु हैं।"},
  {"id":"cdp-pedagogy-subjects-1557","question":"In a Class 8 lesson on industrial chemicals, a teacher discusses the 1984 Bhopal gas leak. The most appropriate educational purpose of this discussion is to:","options":["Warn students about the dangers of chemistry, so that they think carefully before choosing it as a career","Show that chemical industries do more harm than good and that all of them should be closed down","Help students see that technology brings responsibility and a need for safety and accountability","Make students memorise the date, the place and the gas involved, since these are often asked in exams"],"answer":2,"explanation":"Using such a case in science teaching helps learners understand the human and environmental costs of unsafe technology and the ethical responsibilities involved, without blanket fear or mere recall.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"औद्योगिक रसायनों पर कक्षा 8 के पाठ में एक शिक्षक 1984 की भोपाल गैस रिसाव दुर्घटना पर चर्चा करता है। इस चर्चा का सबसे उपयुक्त शैक्षिक उद्देश्य है:","optionsHi":["विद्यार्थियों को रसायन विज्ञान के खतरों से चेताना, ताकि वे इसे करियर के रूप में चुनने से पहले सावधानी से सोचें","यह दिखाना कि रासायनिक उद्योग लाभ से अधिक हानि करते हैं और उन सबको बंद कर देना चाहिए","विद्यार्थियों को यह देखने में मदद करना कि प्रौद्योगिकी जिम्मेदारी लाती है और सुरक्षा तथा जवाबदेही की आवश्यकता होती है","विद्यार्थियों से तिथि, स्थान और संबंधित गैस रटवाना, क्योंकि ये परीक्षाओं में अक्सर पूछे जाते हैं"],"explanationHi":"विज्ञान शिक्षण में ऐसे मामले का उपयोग अधिगमकर्ताओं को असुरक्षित प्रौद्योगिकी की मानवीय और पर्यावरणीय कीमत तथा उससे जुड़ी नैतिक जिम्मेदारियाँ समझने में मदद करता है, बिना सामान्य भय या मात्र स्मरण के।"},
  {"id":"cdp-pedagogy-subjects-1558","question":"After meeting a local mechanic who built a low-cost water pump, a Class 8 class decides to design its own device. Arrange the stages of the design process in order: P. Build a prototype  Q. Identify the problem and the needs of users  R. Test the prototype and improve it  S. Generate and choose among ideas","options":["S, Q, P, R","Q, P, S, R","Q, S, P, R","Q, S, R, P"],"answer":2,"explanation":"Design begins by identifying the problem and users' needs, then generating ideas, building a prototype, and testing and improving it, often in repeated cycles.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कम लागत वाला जल-पंप बनाने वाले स्थानीय मिस्त्री से मिलने के बाद कक्षा 8 की एक कक्षा अपना उपकरण स्वयं डिज़ाइन करने का निर्णय लेती है। डिज़ाइन प्रक्रिया के चरणों को क्रम में लगाइए: P. प्रोटोटाइप बनाना  Q. समस्या और उपयोगकर्ताओं की आवश्यकताओं की पहचान करना  R. प्रोटोटाइप का परीक्षण करना और उसे सुधारना  S. विचार उत्पन्न करना और उनमें से चुनना","optionsHi":["S, Q, P, R","Q, P, S, R","Q, S, P, R","Q, S, R, P"],"explanationHi":"डिज़ाइन समस्या और उपयोगकर्ताओं की आवश्यकताओं की पहचान से शुरू होता है, फिर विचार उत्पन्न किए जाते हैं, प्रोटोटाइप बनाया जाता है, और उसका परीक्षण तथा सुधार किया जाता है, प्रायः बार-बार के चक्रों में।"},
  {"id":"cdp-pedagogy-subjects-1559","question":"A teacher brings a newspaper report of a dengue outbreak in the district to a Class 8 class. Which use of the report best develops scientific thinking?","options":["Asking students to check the report's claims against what they know of mosquitoes, then survey sites nearby","Asking students to copy the report neatly into their notebooks and underline the important health facts","Reading the report aloud to the class as a piece of current news, and then moving straight on to the next chapter","Telling students to avoid going out in the evening and to keep well away from the places where mosquitoes gather"],"answer":0,"explanation":"Critically evaluating a real report and acting on it with a local survey connects science to life and builds the habit of checking claims against evidence.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"एक शिक्षक कक्षा 8 में ज़िले में डेंगू के प्रकोप की समाचार-पत्र रिपोर्ट लाता है। रिपोर्ट का कौन-सा उपयोग वैज्ञानिक चिंतन को सबसे अच्छी तरह विकसित करता है?","optionsHi":["विद्यार्थियों से रिपोर्ट के दावों को मच्छरों के बारे में उनकी जानकारी से परखने को कहना, फिर आसपास के स्थानों का सर्वेक्षण करवाना","विद्यार्थियों से रिपोर्ट को साफ़-सुथरे ढंग से अपनी कॉपी में उतारने और स्वास्थ्य के महत्वपूर्ण तथ्यों को रेखांकित करने को कहना","रिपोर्ट को ताज़ा समाचार के रूप में कक्षा को पढ़कर सुनाना, और फिर सीधे अगले अध्याय पर चले जाना","विद्यार्थियों से कहना कि शाम को बाहर जाने से बचें और जहाँ मच्छर इकट्ठा होते हैं उन जगहों से दूर रहें"],"explanationHi":"किसी वास्तविक रिपोर्ट का आलोचनात्मक मूल्यांकन करना और स्थानीय सर्वेक्षण के साथ उस पर कार्य करना विज्ञान को जीवन से जोड़ता है और दावों को साक्ष्य से परखने की आदत विकसित करता है।"},
  {"id":"cdp-pedagogy-subjects-1560","question":"Even after an ammeter activity showed equal current on both sides of a bulb, several students still say the bulb 'uses up' current. What is the most suitable next step?","options":["Repeating the same ammeter activity exactly as before, since seeing it again will eventually convince them","Marking the students' answers wrong in every test until they learn to write the correct statement about current","Moving on to the next chapter, since the activity has already been done and the evidence it gave was very clear","Using another model, such as a loop of moving beads, and discussing that the bulb uses up energy, not current"],"answer":3,"explanation":"Persistent misconceptions need multiple representations and a clear account of what does change (energy) to make the new idea intelligible and plausible; repeating the same activity rarely shifts them.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"अमीटर की गतिविधि में बल्ब के दोनों ओर समान धारा दिखने के बाद भी कई विद्यार्थी कहते हैं कि बल्ब धारा को ‘खर्च कर देता है’। सबसे उपयुक्त अगला कदम क्या है?","optionsHi":["वही अमीटर गतिविधि ठीक पहले की तरह दोहराना, क्योंकि उसे फिर देखने से वे आखिरकार मान जाएँगे","हर परीक्षा में विद्यार्थियों के उत्तर तब तक गलत करना जब तक वे धारा के बारे में सही कथन लिखना न सीख लें","अगले अध्याय पर चले जाना, क्योंकि गतिविधि हो चुकी है और उससे मिला साक्ष्य बहुत स्पष्ट था","गतिशील मनकों के फंदे जैसा कोई दूसरा मॉडल उपयोग करना और चर्चा करना कि बल्ब ऊर्जा खर्च करता है, धारा नहीं"],"explanationHi":"टिकी हुई भ्रांतियों के लिए अनेक निरूपणों और इस स्पष्ट विवरण की आवश्यकता होती है कि वास्तव में क्या बदलता है (ऊर्जा), ताकि नया विचार बोधगम्य और विश्वसनीय बने; वही गतिविधि दोहराने से वे शायद ही बदलती हैं।"},
  {"id":"cdp-pedagogy-subjects-1561","question":"Which entry is the most useful anecdotal record of a student's behaviour during a science activity?","options":["'Ravi is lazy and never works properly in his group; he always lets the others do the work and then copies their results.'","'Ravi is a poor science student who does not seem interested in practical work and will probably struggle in the higher classes.'","'12 March, magnets: Ravi tested five objects alone, noted results, asked why a steel scale was attracted but a spoon was not.'","'Ravi did well today in the magnet activity and seemed much more interested than usual. Good progress this term overall.'"],"answer":2,"explanation":"A good anecdotal record gives a dated, objective description of what the student did and said, kept separate from judgments. Labels such as 'lazy' or 'poor' are interpretations, not records.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"विज्ञान गतिविधि के दौरान किसी विद्यार्थी के व्यवहार का सबसे उपयोगी उपाख्यानात्मक अभिलेख (anecdotal record) कौन-सा है?","optionsHi":["‘रवि आलसी है और अपने समूह में कभी ठीक से काम नहीं करता; वह हमेशा दूसरों से काम करवाता है और फिर उनके परिणाम उतार लेता है।’","‘रवि विज्ञान में कमज़ोर विद्यार्थी है जिसे व्यावहारिक कार्य में रुचि नहीं दिखती और शायद वह ऊँची कक्षाओं में संघर्ष करेगा।’","‘12 मार्च, चुंबक: रवि ने अकेले पाँच वस्तुओं का परीक्षण किया, परिणाम दर्ज किए, और पूछा कि स्टील का स्केल क्यों आकर्षित हुआ पर चम्मच क्यों नहीं।’","‘रवि ने आज चुंबक की गतिविधि में अच्छा किया और सामान्य से कहीं अधिक रुचि लेता दिखा। इस सत्र में कुल मिलाकर अच्छी प्रगति।’"],"explanationHi":"अच्छा उपाख्यानात्मक अभिलेख तारीख सहित, वस्तुनिष्ठ वर्णन देता है कि विद्यार्थी ने क्या किया और कहा, और उसे निर्णयों से अलग रखता है। ‘आलसी’ या ‘कमज़ोर’ जैसे ठप्पे व्याख्याएँ हैं, अभिलेख नहीं।"},
  {"id":"cdp-pedagogy-subjects-1562","question":"A teacher gives the same chapter test to two sections. In Section A she only records the marks; in Section B she studies the errors, regroups students by the kind of mistake and reteaches. What makes the Section B use formative?","options":["The difficulty level of the questions set in the chapter test","How the results are used to improve teaching and learning","The number and type of questions included in the chapter test","The point in the term at which the chapter test was given"],"answer":1,"explanation":"Whether an assessment is formative depends on its use: results used to adjust teaching and support learners make it formative, even when the test itself is identical.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"एक शिक्षिका दो अनुभागों को एक ही अध्याय-परीक्षा देती है। अनुभाग A में वह केवल अंक दर्ज करती है; अनुभाग B में वह त्रुटियों का अध्ययन करती है, विद्यार्थियों को गलती के प्रकार के आधार पर पुनः समूहबद्ध करती है और पुनः पढ़ाती है। अनुभाग B के उपयोग को रचनात्मक क्या बनाता है?","optionsHi":["अध्याय-परीक्षा में पूछे गए प्रश्नों का कठिनाई-स्तर","परिणामों का उपयोग शिक्षण और अधिगम को सुधारने के लिए कैसे किया जाता है","अध्याय-परीक्षा में शामिल प्रश्नों की संख्या और प्रकार","सत्र के किस बिंदु पर अध्याय-परीक्षा ली गई"],"explanationHi":"कोई आकलन रचनात्मक है या नहीं, यह उसके उपयोग पर निर्भर करता है: जिन परिणामों का उपयोग शिक्षण को समायोजित करने और अधिगमकर्ताओं की सहायता के लिए होता है, वे आकलन को रचनात्मक बनाते हैं, भले ही परीक्षा स्वयं एक जैसी हो।"},
  {"id":"cdp-pedagogy-subjects-1563","question":"In a school, science theory is taught in the first term and all practicals are done together in the last month before the examination. The main drawback of this arrangement is that:","options":["Practicals are cut off from the concepts they should help build, so they become rituals","Students spend too much time in the laboratory in one month, which leaves little time for revision","Teachers get very tired in the last month, so the quality of supervision in practicals goes down","There is not enough apparatus for all students to do every practical at the same time of year"],"answer":0,"explanation":"Practical work is most useful when it is woven into teaching, so concepts are formed through activity. Separating them turns practicals into a routine for marks.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"एक विद्यालय में विज्ञान का सैद्धांतिक भाग पहले सत्र में पढ़ाया जाता है और सभी प्रयोग परीक्षा से पहले अंतिम महीने में एक साथ करवाए जाते हैं। इस व्यवस्था की मुख्य कमी यह है कि:","optionsHi":["प्रयोग उन संकल्पनाओं से कट जाते हैं जिन्हें बनाने में उन्हें मदद करनी चाहिए, इसलिए वे कर्मकांड बन जाते हैं","विद्यार्थी एक महीने में प्रयोगशाला में बहुत अधिक समय बिताते हैं, जिससे दोहराने के लिए कम समय बचता है","अंतिम महीने में शिक्षक बहुत थक जाते हैं, इसलिए प्रयोगों में पर्यवेक्षण की गुणवत्ता गिर जाती है","वर्ष के एक ही समय पर सभी विद्यार्थियों के हर प्रयोग करने के लिए पर्याप्त उपकरण नहीं होते"],"explanationHi":"व्यावहारिक कार्य तब सबसे उपयोगी होता है जब वह शिक्षण में पिरोया हो, ताकि गतिविधि से संकल्पनाएँ बनें। उन्हें अलग कर देने से प्रयोग अंकों के लिए एक दिनचर्या बन जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1564","question":"A Class 6 textbook diagram shows the planets close together around the sun. Students take it as a true picture. Which activity best corrects this impression?","options":["Colouring the planets in the diagram carefully, so that students can tell each planet apart easily","Asking students to memorise the order of the planets from the sun with the help of a short rhyme","Making a scale model in the school ground with a ball for the sun and marked planet distances","Showing a bigger, more detailed diagram of the same kind, with labels for each planet and its moons"],"answer":2,"explanation":"Most textbook diagrams are not to scale; a scale model reveals the vast distances between planets, showing the model's limits and building a truer picture.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा 6 की पाठ्यपुस्तक का एक चित्र ग्रहों को सूर्य के चारों ओर पास-पास दिखाता है। विद्यार्थी उसे सच्चा चित्र मान लेते हैं। कौन-सी गतिविधि इस धारणा को सबसे अच्छी तरह सुधारती है?","optionsHi":["चित्र में ग्रहों में ध्यान से रंग भरना, ताकि विद्यार्थी हर ग्रह को आसानी से पहचान सकें","विद्यार्थियों से एक छोटी तुकबंदी की सहायता से सूर्य से ग्रहों का क्रम रटवाना","विद्यालय के मैदान में गेंद को सूर्य मानकर और ग्रहों की दूरियाँ चिह्नित करके पैमाने के अनुसार मॉडल बनाना","उसी प्रकार का बड़ा, अधिक विस्तृत चित्र दिखाना, जिसमें हर ग्रह और उसके चंद्रमाओं के नाम लिखे हों"],"explanationHi":"अधिकांश पाठ्यपुस्तक चित्र पैमाने के अनुसार नहीं होते; पैमाने वाला मॉडल ग्रहों के बीच की विशाल दूरियाँ उजागर करता है, मॉडल की सीमाएँ दिखाता है और अधिक सही चित्र बनाता है।"},
  {"id":"cdp-pedagogy-subjects-1565","question":"In a class investigation on how fast different materials let water through, each group's results vary a little. The teacher pools the data from all groups on the board before conclusions are drawn. This mainly teaches students that:","options":["The results of individual groups are worthless, since only a class average can be trusted in science","Science is a shared activity in which combining and comparing results gives more reliable findings","The group whose results are closest to the textbook value is right and the others made mistakes","Data from different groups should always be identical if each group has done the experiment properly"],"answer":1,"explanation":"Pooling data shows variation is normal and that collaboration and replication strengthen conclusions, which reflects science as a collaborative enterprise.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"विभिन्न पदार्थों से पानी कितनी तेज़ी से निकलता है, इस पर कक्षा की जाँच में हर समूह के परिणाम थोड़े भिन्न आते हैं। निष्कर्ष निकालने से पहले शिक्षिका सभी समूहों के आँकड़े श्यामपट्ट पर एकत्र करती है। यह मुख्यतः विद्यार्थियों को क्या सिखाता है?","optionsHi":["अलग-अलग समूहों के परिणाम व्यर्थ हैं, क्योंकि विज्ञान में केवल कक्षा के औसत पर भरोसा किया जा सकता है","विज्ञान एक साझा गतिविधि है जिसमें परिणामों को मिलाने और तुलना करने से अधिक विश्वसनीय निष्कर्ष मिलते हैं","जिस समूह के परिणाम पाठ्यपुस्तक के मान के सबसे निकट हैं वही सही है और बाकी ने गलतियाँ की हैं","अलग-अलग समूहों के आँकड़े हमेशा समान होने चाहिए, यदि हर समूह ने प्रयोग ठीक से किया है"],"explanationHi":"आँकड़ों को मिलाने से पता चलता है कि विचलन सामान्य है और सहयोग तथा पुनरावृत्ति निष्कर्षों को मज़बूत करते हैं, जो विज्ञान को एक सहयोगात्मक उद्यम के रूप में दर्शाता है।"},
  {"id":"cdp-pedagogy-subjects-1566","question":"While learning about plants, Class 6 students describe roots as 'the plant's legs that hold it'. The teacher's best approach to scientific vocabulary is to:","options":["Ban everyday language and insist on the correct technical terms from the first day, so that wrong ideas do not form","Never introduce technical terms at this stage, since students' own words are enough for understanding plants","Ignore the description and move on, since comparing roots to legs is a childish way of talking about plants","Accept everyday descriptions first, then introduce terms such as 'anchorage' and 'absorption' for ideas they hold"],"answer":3,"explanation":"Technical terms are best learnt as labels for ideas students already understand in their own words; terms imposed first become empty words.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"पौधों के बारे में सीखते समय कक्षा 6 के विद्यार्थी जड़ों का वर्णन ‘पौधे के पैर जो उसे थामे रखते हैं’ के रूप में करते हैं। वैज्ञानिक शब्दावली के प्रति शिक्षिका का सबसे अच्छा दृष्टिकोण है:","optionsHi":["रोज़मर्रा की भाषा पर रोक लगाना और पहले दिन से सही तकनीकी शब्दों पर ज़ोर देना, ताकि गलत विचार न बनें","इस स्तर पर तकनीकी शब्द कभी न लाना, क्योंकि पौधों को समझने के लिए विद्यार्थियों के अपने शब्द पर्याप्त हैं","वर्णन की अनदेखी करके आगे बढ़ना, क्योंकि जड़ों की पैरों से तुलना पौधों के बारे में बचकानी बात है","पहले रोज़मर्रा के वर्णन स्वीकार करना, फिर उनके विचारों के लिए ‘आधार’ और ‘अवशोषण’ जैसे शब्द देना"],"explanationHi":"तकनीकी शब्द सबसे अच्छी तरह उन विचारों के नाम के रूप में सीखे जाते हैं जिन्हें विद्यार्थी अपने शब्दों में पहले से समझते हैं; पहले थोपे गए शब्द खोखले शब्द बन जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1567","question":"Several students submit science fair projects copied from the internet. The teacher's best guidance for future projects is to:","options":["Help students begin from questions about their own surroundings and design their own investigations","Ban the use of the internet for projects, since students cannot be trusted to use it without copying","Award marks mainly for the neatness of the charts, since that part at least has to be done by the students","Assign the same project to everyone, so that copying is easy to spot and the marking is fair to all"],"answer":0,"explanation":"Projects rooted in students' own questions and surroundings encourage originality and real inquiry, and the internet can then be used as a source rather than a copy.","difficulty":"moderate","source":"CTET Paper 2 · state TETs","questionHi":"कई विद्यार्थी इंटरनेट से उतारी हुई विज्ञान मेला परियोजनाएँ जमा करते हैं। भविष्य की परियोजनाओं के लिए शिक्षक का सबसे अच्छा मार्गदर्शन है:","optionsHi":["विद्यार्थियों को अपने आसपास के प्रश्नों से शुरुआत करने और अपनी जाँच स्वयं डिज़ाइन करने में मदद करना","परियोजनाओं के लिए इंटरनेट के उपयोग पर रोक लगाना, क्योंकि विद्यार्थियों पर बिना नकल किए उपयोग करने का भरोसा नहीं किया जा सकता","मुख्यतः चार्टों की साफ़-सफ़ाई पर अंक देना, क्योंकि वह भाग तो कम से कम विद्यार्थियों को ही करना होता है","सभी को एक ही परियोजना देना, ताकि नकल आसानी से पकड़ी जा सके और अंकन सबके लिए निष्पक्ष हो"],"explanationHi":"विद्यार्थियों के अपने प्रश्नों और परिवेश में निहित परियोजनाएँ मौलिकता और वास्तविक जाँच को प्रोत्साहित करती हैं, और तब इंटरनेट को नकल के बजाय स्रोत के रूप में इस्तेमाल किया जा सकता है।"},
  {"id":"cdp-pedagogy-subjects-1568","question":"In a debate on banning single-use plastic bags, which student response shows the best scientific argument?","options":["'Plastic is very bad for the environment. Everyone knows that, and so do all the experts we see on television.'","'My uncle runs a shop and says plastic bags are fine and cheap, so they should certainly not be banned.'","'Plastic bags should be banned, because they look ugly lying everywhere and make our town look dirty.'","'Ban them: our survey found bags blocking three drains near school, and they do not decay, so it will worsen.'"],"answer":3,"explanation":"A strong scientific argument links a claim to evidence (the survey) through reasoning (they do not decompose). The others rest on common belief, authority or appearance.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"एकल-उपयोग प्लास्टिक थैलियों पर प्रतिबंध की बहस में, कौन-सी विद्यार्थी प्रतिक्रिया सबसे अच्छा वैज्ञानिक तर्क दर्शाती है?","optionsHi":["‘प्लास्टिक पर्यावरण के लिए बहुत बुरा है। यह सब जानते हैं, और टेलीविज़न पर दिखने वाले सभी विशेषज्ञ भी।’","‘मेरे चाचा की दुकान है और वे कहते हैं कि प्लास्टिक थैलियाँ ठीक और सस्ती हैं, इसलिए उन पर निश्चित रूप से प्रतिबंध नहीं लगना चाहिए।’","‘प्लास्टिक थैलियों पर प्रतिबंध लगना चाहिए, क्योंकि वे हर जगह पड़ी बदसूरत लगती हैं और हमारे शहर को गंदा दिखाती हैं।’","‘प्रतिबंध लगाइए: हमारे सर्वेक्षण में विद्यालय के पास तीन नालियाँ थैलियों से अवरुद्ध मिलीं, और वे सड़ती नहीं, इसलिए यह और बिगड़ेगा।’"],"explanationHi":"मज़बूत वैज्ञानिक तर्क दावे को साक्ष्य (सर्वेक्षण) से तर्क (वे अपघटित नहीं होतीं) के माध्यम से जोड़ता है। अन्य तर्क आम धारणा, अधिकार या दिखावट पर टिके हैं।"},
  {"id":"cdp-pedagogy-subjects-1569","question":"A teacher could either show a video of a candle burning under a glass or do it live in class. Which is the strongest reason to prefer the live demonstration?","options":["It is quicker than finding and playing a video, so more of the period is left for writing notes","Students see the real event, ask 'what if', and the teacher can change conditions on the spot","It needs no preparation, since a candle and a glass are easily available in every school","Videos are never useful in science, since students only learn from things they see in person"],"answer":1,"explanation":"A live demonstration is authentic and interactive: the teacher can respond to students' questions by changing conditions, such as using a bigger glass. Videos have uses but cannot respond in this way.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"एक शिक्षक काँच के नीचे जलती मोमबत्ती का वीडियो दिखा सकता है या कक्षा में उसे सीधे कर सकता है। सीधे प्रदर्शन को चुनने का सबसे मज़बूत कारण क्या है?","optionsHi":["यह वीडियो खोजने और चलाने से तेज़ है, इसलिए नोट्स लिखने के लिए पीरियड का अधिक समय बचता है","विद्यार्थी वास्तविक घटना देखते हैं, ‘अगर ऐसा हो तो’ पूछते हैं, और शिक्षक मौके पर परिस्थितियाँ बदल सकता है","इसके लिए किसी तैयारी की आवश्यकता नहीं है, क्योंकि मोमबत्ती और काँच हर विद्यालय में आसानी से मिल जाते हैं","विज्ञान में वीडियो कभी उपयोगी नहीं होते, क्योंकि विद्यार्थी केवल उन्हीं चीज़ों से सीखते हैं जो वे स्वयं देखते हैं"],"explanationHi":"सीधा प्रदर्शन प्रामाणिक और अंतःक्रियात्मक होता है: शिक्षक परिस्थितियाँ बदलकर, जैसे बड़ा काँच लेकर, विद्यार्थियों के प्रश्नों का उत्तर दे सकता है। वीडियो के अपने उपयोग हैं, पर वे इस तरह प्रतिक्रिया नहीं दे सकते।"},
  {"id":"cdp-pedagogy-subjects-1570","question":"Students believe that maggots arise on their own from rotting food. Which investigation best tests this idea?","options":["Keeping food in two jars, one covered with fine cloth and one left open, and seeing which gets maggots","Looking closely at maggots under a hand lens to see which part of the rotting food they are coming from","Reading about the life cycle of the housefly in the textbook and drawing each stage carefully","Keeping the food in a refrigerator and checking whether maggots still appear after a few days"],"answer":0,"explanation":"If maggots came from food alone, both jars would develop them. Maggots only in the open jar show they come from eggs laid by flies, a version of Redi's classic test.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs","questionHi":"विद्यार्थी मानते हैं कि सड़ते भोजन में मैगट (इल्लियाँ) अपने आप पैदा हो जाते हैं। कौन-सी जाँच इस विचार को सबसे अच्छी तरह परखती है?","optionsHi":["भोजन को दो जारों में रखना, एक को महीन कपड़े से ढकना और एक खुला छोड़ना, और देखना कि किसमें मैगट आते हैं","हैंड लेंस से मैगट को ध्यान से देखना कि वे सड़ते भोजन के किस भाग से आ रहे हैं","पाठ्यपुस्तक में घरेलू मक्खी का जीवन-चक्र पढ़ना और हर अवस्था को ध्यान से बनाना","भोजन को रेफ्रिजरेटर में रखना और जाँचना कि कुछ दिनों बाद भी मैगट आते हैं या नहीं"],"explanationHi":"यदि मैगट केवल भोजन से आते, तो दोनों जारों में पैदा होते। केवल खुले जार में मैगट होना दिखाता है कि वे मक्खियों द्वारा दिए अंडों से आते हैं, यह रेडी के क्लासिक परीक्षण का एक रूप है।"},
  {"id":"cdp-pedagogy-subjects-1571","question":"Which activity best reflects NCF 2005's suggestion that upper primary students should design simple technological units and modules?","options":["Reading about how large dams generate electricity and listing the parts of a hydroelectric plant","Copying a labelled diagram of a rain gauge from the textbook and learning how it is used","Building a rain gauge from a plastic bottle and using it to record rainfall through the monsoon","Watching a video on weather instruments and noting down how each one is used by scientists"],"answer":2,"explanation":"Designing and using a working device of their own engages students' hands and minds and links technology to everyday life. Reading, copying and watching are passive.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कौन-सी गतिविधि NCF 2005 के इस सुझाव को सबसे अच्छी तरह दर्शाती है कि उच्च प्राथमिक स्तर के विद्यार्थियों को सरल तकनीकी इकाइयाँ और मॉड्यूल डिज़ाइन करने चाहिए?","optionsHi":["यह पढ़ना कि बड़े बाँध बिजली कैसे बनाते हैं और जलविद्युत संयंत्र के भागों की सूची बनाना","पाठ्यपुस्तक से वर्षामापी का नामांकित चित्र उतारना और सीखना कि उसका उपयोग कैसे होता है","प्लास्टिक की बोतल से वर्षामापी बनाना और मानसून के दौरान उससे वर्षा दर्ज करना","मौसम के उपकरणों पर वीडियो देखना और लिखना कि वैज्ञानिक उनमें से प्रत्येक का उपयोग कैसे करते हैं"],"explanationHi":"अपना कार्यशील उपकरण डिज़ाइन करना और उपयोग करना विद्यार्थियों के हाथ और दिमाग को जोड़ता है तथा प्रौद्योगिकी को दैनिक जीवन से जोड़ता है। पढ़ना, उतारना और देखना निष्क्रिय हैं।"},
  {"id":"cdp-pedagogy-subjects-1572","question":"Arrange the steps of a scientific investigation in a logical order: P. Interpret the data and draw a conclusion  Q. Frame a testable question and hypothesis  R. Plan a fair test  S. Collect and record data  T. Communicate the findings","options":["R, Q, S, P, T","Q, R, S, T, P","Q, S, R, P, T","Q, R, S, P, T"],"answer":3,"explanation":"An investigation moves from a testable question and hypothesis to planning a fair test, collecting data, interpreting it and communicating the findings, though real science often loops back.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"वैज्ञानिक जाँच के चरणों को तार्किक क्रम में लगाइए: P. आँकड़ों की व्याख्या करना और निष्कर्ष निकालना  Q. परीक्षण-योग्य प्रश्न और परिकल्पना बनाना  R. निष्पक्ष परीक्षण की योजना बनाना  S. आँकड़े एकत्र करना और दर्ज करना  T. निष्कर्षों को संप्रेषित करना","optionsHi":["R, Q, S, P, T","Q, R, S, T, P","Q, S, R, P, T","Q, R, S, P, T"],"explanationHi":"जाँच परीक्षण-योग्य प्रश्न और परिकल्पना से निष्पक्ष परीक्षण की योजना, आँकड़े एकत्र करने, उनकी व्याख्या करने और निष्कर्षों को संप्रेषित करने की ओर बढ़ती है, यद्यपि वास्तविक विज्ञान में प्रायः पीछे लौटना भी होता है।"},
  {"id":"cdp-pedagogy-subjects-1573","question":"A teacher asks a student to 'think aloud' while she predicts which of several circuits will light a bulb. The main value of this technique is that it:","options":["Reveals the reasoning behind her answers, not just whether they are right","Makes the test faster, since the teacher can hear answers instead of reading them","Lets the teacher correct her immediately and give her the right answer at each step","Replaces practical work, since predicting circuits is as good as building them"],"answer":0,"explanation":"Think-aloud protocols expose a learner's mental model, such as the 'one wire' or 'clashing current' idea, which a right or wrong answer alone would hide.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB","questionHi":"एक शिक्षिका विद्यार्थी से ‘ज़ोर से सोचने’ (think aloud) को कहती है जब वह अनुमान लगाती है कि कई परिपथों में से कौन-सा बल्ब जलाएगा। इस तकनीक का मुख्य मूल्य यह है कि यह:","optionsHi":["उसके उत्तरों के पीछे का तर्क प्रकट करती है, केवल यह नहीं कि वे सही हैं या नहीं","परीक्षा को तेज़ बनाती है, क्योंकि शिक्षिका उत्तर पढ़ने के बजाय सुन सकती है","शिक्षिका को उसे तुरंत सुधारने और हर चरण पर सही उत्तर देने देती है","प्रयोगात्मक कार्य की जगह ले लेती है, क्योंकि परिपथों का अनुमान लगाना उन्हें बनाने जितना ही अच्छा है"],"explanationHi":"ज़ोर से सोचने की विधि अधिगमकर्ता के मानसिक मॉडल को उजागर करती है, जैसे ‘एक तार’ या ‘टकराती धारा’ का विचार, जिसे केवल सही या गलत उत्तर छिपा देता।"},
  {"id":"cdp-pedagogy-subjects-1574","question":"A Class 7 teacher with limited apparatus sets up four tables, each with a different activity on heat (conduction, convection, radiation, insulation), and groups move from table to table every ten minutes. This arrangement mainly helps because:","options":["Students can skip the tables they find hard and spend more time on the activities they like","Every student gets hands-on work at every table with only one set of materials each","The teacher does not need to supervise, since each table has its own written instructions","It removes the need for a discussion afterwards, since each group has done all four activities"],"answer":1,"explanation":"Station rotation makes the most of limited apparatus while giving everyone hands-on time; a closing discussion is still needed to connect the four activities.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS","questionHi":"सीमित उपकरणों वाली कक्षा 7 की एक शिक्षिका चार मेज़ें लगाती है, हर एक पर ऊष्मा पर अलग गतिविधि (चालन, संवहन, विकिरण, रोधन), और समूह हर दस मिनट में एक मेज़ से दूसरी पर जाते हैं। यह व्यवस्था मुख्यतः इसलिए सहायक है कि:","optionsHi":["विद्यार्थी उन मेज़ों को छोड़ सकते हैं जो उन्हें कठिन लगती हैं और अपनी पसंद की गतिविधियों में अधिक समय दे सकते हैं","हर मेज़ पर केवल एक-एक सेट सामग्री के साथ हर विद्यार्थी को हर मेज़ पर हाथों से काम करने को मिलता है","शिक्षिका को पर्यवेक्षण की आवश्यकता नहीं रहती, क्योंकि हर मेज़ पर अपने लिखित निर्देश हैं","बाद में चर्चा की आवश्यकता नहीं रहती, क्योंकि हर समूह ने चारों गतिविधियाँ कर ली हैं"],"explanationHi":"स्टेशन-चक्रण सीमित उपकरणों का अधिकतम उपयोग करता है और सबको हाथ से करने का समय देता है; चारों गतिविधियों को जोड़ने के लिए समापन चर्चा फिर भी आवश्यक है।"},
  {"id":"cdp-pedagogy-subjects-1575","question":"In a Class 6 English lesson in Mumbai, students discuss a story in groups using Hindi, Marathi and English freely, then each group writes its summary in English. The teacher’s deliberate use of all the learners’ languages to make meaning is best described as:","options":["Submersion","Subtractive bilingualism","Translanguaging","Grammar-translation"],"answer":2,"explanation":"Translanguaging treats a learner’s languages as one connected repertoire and uses all of it to understand and produce content. Grammar-translation translates texts to learn rules, which is not happening here.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"मुंबई में कक्षा 6 के अंग्रेज़ी पाठ में विद्यार्थी समूहों में एक कहानी पर चर्चा करते हैं और हिंदी, मराठी तथा अंग्रेज़ी का स्वतंत्र रूप से उपयोग करते हैं, फिर हर समूह अपना सारांश अंग्रेज़ी में लिखता है। अर्थ बनाने के लिए शिक्षिका द्वारा अधिगमकर्ताओं की सभी भाषाओं का सोचा-समझा उपयोग किस रूप में सबसे उपयुक्त ढंग से वर्णित होता है?","optionsHi":["निमज्जन (Submersion)","व्यवकलनात्मक द्विभाषिकता (Subtractive bilingualism)","पारभाषिकता (Translanguaging)","व्याकरण-अनुवाद (Grammar-translation)"],"explanationHi":"पारभाषिकता (translanguaging) अधिगमकर्ता की भाषाओं को एक जुड़े हुए भंडार के रूप में मानती है और विषय-वस्तु को समझने तथा रचने में उस पूरे भंडार का उपयोग करती है। व्याकरण-अनुवाद नियम सीखने के लिए पाठों का अनुवाद करता है, जो यहाँ नहीं हो रहा।"},
  {"id":"cdp-pedagogy-subjects-1576","question":"A school in a Santali-speaking area forbids Santali on the premises, and over a few years children stop using it even at home while their school language stays weak. This outcome is called:","options":["Additive bilingualism, since a new language has been added","Subtractive bilingualism, as the new language replaces the first","Balanced bilingualism, since the two languages are now equal","Code-mixing, since words from both languages are combined"],"answer":1,"explanation":"When a second language is learnt at the cost of the first, bilingualism is subtractive, often with harm to identity and learning. Additive bilingualism adds a language while the first keeps developing.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"संथाली भाषी क्षेत्र का एक विद्यालय परिसर में संथाली पर रोक लगाता है, और कुछ वर्षों में बच्चे घर पर भी उसका उपयोग बंद कर देते हैं जबकि उनकी विद्यालयी भाषा कमज़ोर बनी रहती है। इस परिणाम को कहते हैं:","optionsHi":["योगात्मक द्विभाषिकता, क्योंकि एक नई भाषा जोड़ी गई है","ह्रासी द्विभाषिकता, क्योंकि नई भाषा पहली भाषा की जगह ले लेती है","संतुलित द्विभाषिकता, क्योंकि अब दोनों भाषाएँ बराबर हैं","कोड-मिश्रण, क्योंकि दोनों भाषाओं के शब्द मिला दिए जाते हैं"],"explanationHi":"जब दूसरी भाषा पहली भाषा की कीमत पर सीखी जाती है, तो द्विभाषिकता ह्रासी होती है, जिससे प्रायः पहचान और अधिगम को हानि होती है। योगात्मक द्विभाषिकता एक भाषा जोड़ती है जबकि पहली भाषा विकसित होती रहती है।"},
  {"id":"cdp-pedagogy-subjects-1577","question":"During an English activity, a Class 2 child says, ‘Ma’am, mujhe ek eraser chahiye.’ The most suitable teacher response is to:","options":["Tell the child to ask again only in English, or not at all","Ignore the request until the child asks in correct English","Note it down as a language mistake to discuss with the parents","Give it, saying, ‘Oh, you need an eraser? Here you are.’"],"answer":3,"explanation":"Mixing languages is a normal strategy of bilingual children. Responding to the meaning while modelling the English form keeps communication going and gives useful input without shame.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"अंग्रेज़ी की एक गतिविधि के दौरान कक्षा 2 का एक बच्चा कहता है, ‘Ma’am, mujhe ek eraser chahiye.’ शिक्षिका की सबसे उपयुक्त प्रतिक्रिया है:","optionsHi":["बच्चे से कहना कि केवल अंग्रेज़ी में दोबारा माँगे, या बिल्कुल न माँगे","जब तक बच्चा सही अंग्रेज़ी में न माँगे, अनुरोध की अनदेखी करना","इसे भाषा की गलती के रूप में नोट करना ताकि माता-पिता से चर्चा की जाए","उसे देना, यह कहते हुए, ‘Oh, you need an eraser? Here you are.’"],"explanationHi":"भाषाओं को मिलाना द्विभाषी बच्चों की एक सामान्य युक्ति है। अर्थ का उत्तर देते हुए अंग्रेज़ी का रूप प्रस्तुत करने से संवाद चलता रहता है और बिना शर्मिंदगी के उपयोगी निवेश (input) मिलता है।"},
  {"id":"cdp-pedagogy-subjects-1578","question":"A Class 4 teacher in Delhi has children whose home languages include Bhojpuri, Bengali, Nepali and Urdu, none of which she speaks. Which is the most practical way to use these languages as a resource?","options":["Avoid them, since she cannot check whether they are being used correctly","Allow them only during breaks and never during lesson time in the classroom","Invite children to share words and stories from home and use peer help","Teach entirely in English, so that no one language group is favoured over others"],"answer":2,"explanation":"A teacher need not know every language; children, peers and families are the experts. Inviting their languages into tasks builds inclusion and helps link new English words to known concepts.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"दिल्ली में कक्षा 4 की एक शिक्षिका के बच्चों की घरेलू भाषाओं में भोजपुरी, बांग्ला, नेपाली और उर्दू शामिल हैं, जिनमें से कोई भी वह नहीं बोलती। इन भाषाओं को संसाधन के रूप में उपयोग करने का सबसे व्यावहारिक तरीका कौन-सा है?","optionsHi":["उनसे बचना, क्योंकि वह जाँच नहीं सकती कि उनका सही उपयोग हो रहा है या नहीं","उन्हें केवल अवकाश के समय अनुमति देना और कक्षा में पाठ के समय कभी नहीं","बच्चों को घर से शब्द और कहानियाँ साझा करने के लिए आमंत्रित करना और सहपाठियों की मदद लेना","पूरी तरह अंग्रेज़ी में पढ़ाना, ताकि किसी एक भाषा-समूह को दूसरों से अधिक वरीयता न मिले"],"explanationHi":"शिक्षिका को हर भाषा जानने की आवश्यकता नहीं; बच्चे, सहपाठी और परिवार विशेषज्ञ हैं। उनकी भाषाओं को कार्यों में आमंत्रित करने से समावेशन बनता है और नए अंग्रेज़ी शब्दों को ज्ञात संकल्पनाओं से जोड़ने में मदद मिलती है।"},
  {"id":"cdp-pedagogy-subjects-1579","question":"A teacher writes ‘Raju aam khata hai’ and ‘Raju eats a mango’ on the board and asks Class 5 children where the verb comes in each. The main purpose of this comparison is to:","options":["Show that Hindi grammar is less correct than English grammar","Practise translating Hindi sentences into English word by word","Test whether children know the Hindi word for ‘mango’","Build awareness of how the two languages differ"],"answer":3,"explanation":"Comparing subject–object–verb order in Hindi with subject–verb–object order in English builds metalinguistic awareness and helps children understand errors like ‘Raju mango eats’.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"एक शिक्षिका श्यामपट्ट पर ‘Raju aam khata hai’ और ‘Raju eats a mango’ लिखती है और कक्षा 5 के बच्चों से पूछती है कि हर वाक्य में क्रिया कहाँ आती है। इस तुलना का मुख्य उद्देश्य है:","optionsHi":["यह दिखाना कि हिंदी व्याकरण अंग्रेज़ी व्याकरण से कम सही है","हिंदी वाक्यों का शब्द-दर-शब्द अंग्रेज़ी में अनुवाद करने का अभ्यास कराना","यह जाँचना कि बच्चे ‘आम’ का हिंदी शब्द जानते हैं या नहीं","दोनों भाषाओं के अंतर के बारे में जागरूकता बनाना"],"explanationHi":"हिंदी के कर्ता–कर्म–क्रिया क्रम की अंग्रेज़ी के कर्ता–क्रिया–कर्म क्रम से तुलना भाषाई जागरूकता (metalinguistic awareness) बनाती है और बच्चों को ‘Raju mango eats’ जैसी त्रुटियाँ समझने में मदद करती है।"},
  {"id":"cdp-pedagogy-subjects-1580","question":"Assertion (A): NCF 2005 recommends drawing on children’s home languages in class even when the medium of instruction is English. Reason (R): Children learn best when new knowledge is connected to what they already know, including their own language.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"NCF 2005 treats multilingualism as a resource precisely because learning builds on prior knowledge and the language in which children think and experience the world.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"अभिकथन (A): NCF 2005 अनुशंसा करती है कि शिक्षण का माध्यम अंग्रेज़ी होने पर भी कक्षा में बच्चों की घरेलू भाषाओं का उपयोग किया जाए। कारण (R): बच्चे सबसे अच्छा तब सीखते हैं जब नया ज्ञान उससे जुड़ा हो जो वे पहले से जानते हैं, जिसमें उनकी अपनी भाषा भी शामिल है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"NCF 2005 बहुभाषिकता को संसाधन इसलिए मानती है क्योंकि अधिगम पूर्व ज्ञान और उस भाषा पर आधारित होता है जिसमें बच्चे सोचते और दुनिया को अनुभव करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1581","question":"A school near Mangaluru fines children five rupees each time they are heard speaking Tulu in school. From the point of view of NCF 2005, this practice is:","options":["Justified, as it gives children maximum exposure to English","Harmful, as it devalues identity and wastes a resource","Acceptable, as long as the fine money is used to buy books","Useful, as it improves discipline in the school"],"answer":1,"explanation":"Punishing a home language signals that the child’s culture is inferior and raises anxiety; NCF 2005 asks schools to respect and use children’s languages.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"मंगलुरु के पास का एक विद्यालय बच्चों से हर बार पाँच रुपये जुर्माना लेता है जब उन्हें विद्यालय में तुलु बोलते सुना जाता है। NCF 2005 की दृष्टि से यह प्रथा है:","optionsHi":["उचित, क्योंकि इससे बच्चों को अंग्रेज़ी का अधिकतम संपर्क मिलता है","हानिकारक, क्योंकि यह पहचान का अवमूल्यन करती है और एक संसाधन को व्यर्थ करती है","स्वीकार्य, जब तक जुर्माने की राशि से किताबें खरीदी जाएँ","उपयोगी, क्योंकि इससे विद्यालय में अनुशासन सुधरता है"],"explanationHi":"घरेलू भाषा को दंडित करना संकेत देता है कि बच्चे की संस्कृति हीन है और चिंता बढ़ाता है; NCF 2005 विद्यालयों से बच्चों की भाषाओं का सम्मान और उपयोग करने को कहती है।"},
  {"id":"cdp-pedagogy-subjects-1582","question":"A Class 2 library in Jharkhand has picture books with the same story printed in Santali and English on facing pages. The main benefit for Santali-speaking children is that:","options":["They can skip the English text and read only in Santali","The books save the school money by printing two books in one","They can understand the story in Santali and link it to English","They avoid any need for the teacher to read aloud"],"answer":2,"explanation":"Bilingual texts let children build meaning through the stronger language and then connect it to English words and structures, supporting both literacy and identity.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"झारखंड के कक्षा 2 के एक पुस्तकालय में चित्र-पुस्तकें हैं जिनमें एक ही कहानी आमने-सामने के पृष्ठों पर संथाली और अंग्रेज़ी में छपी है। संथाली भाषी बच्चों के लिए मुख्य लाभ यह है कि:","optionsHi":["वे अंग्रेज़ी पाठ छोड़कर केवल संथाली में पढ़ सकते हैं","पुस्तकें एक में दो किताबें छापकर विद्यालय का पैसा बचाती हैं","वे कहानी को संथाली में समझ सकते हैं और उसे अंग्रेज़ी से जोड़ सकते हैं","उन्हें शिक्षिका के ज़ोर से पढ़ने की आवश्यकता नहीं रहती"],"explanationHi":"द्विभाषी पाठ बच्चों को अपनी अधिक सशक्त भाषा से अर्थ बनाने देते हैं और फिर उसे अंग्रेज़ी शब्दों तथा संरचनाओं से जोड़ने देते हैं, जिससे साक्षरता और पहचान दोनों को सहारा मिलता है।"},
  {"id":"cdp-pedagogy-subjects-1583","question":"Some parents demand that only English be used from Class 1 because the home language ‘spoils’ English. Which response by the teacher is most consistent with research and policy?","options":["Agree, since early exclusive English always produces the best results","Tell the parents that language choices are not their concern","Say that English should not be taught at all until Class 6","Explain that a strong home language supports learning English"],"answer":3,"explanation":"Research on cross-linguistic transfer and NEP 2020’s emphasis on the home language in the early years both show that strong first-language skills support learning a second.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कुछ अभिभावक माँग करते हैं कि कक्षा 1 से केवल अंग्रेज़ी का उपयोग हो क्योंकि घरेलू भाषा अंग्रेज़ी को ‘बिगाड़ती’ है। शिक्षिका की कौन-सी प्रतिक्रिया शोध और नीति के सबसे अनुरूप है?","optionsHi":["सहमत होना, क्योंकि शुरुआती विशुद्ध अंग्रेज़ी हमेशा सर्वोत्तम परिणाम देती है","अभिभावकों से कहना कि भाषा का चुनाव उनकी चिंता का विषय नहीं है","कहना कि कक्षा 6 तक अंग्रेज़ी बिल्कुल नहीं पढ़ाई जानी चाहिए","समझाना कि सशक्त घरेलू भाषा अंग्रेज़ी सीखने में सहायता करती है"],"explanationHi":"भाषाओं के बीच अंतरण पर शोध और NEP 2020 का आरंभिक वर्षों में घरेलू भाषा पर बल, दोनों दिखाते हैं कि सशक्त प्रथम भाषा कौशल दूसरी भाषा सीखने में सहायक होते हैं।"},
  {"id":"cdp-pedagogy-subjects-1584","question":"Knowing that Hindi has no direct equivalent of the English articles ‘a’ and ‘the’, a teacher plans extra work on articles for her Hindi-speaking Class 6 students before errors appear. She is using insights from:","options":["The natural order hypothesis of Krashen","Contrastive analysis of the two languages","Total Physical Response of James Asher","The language experience approach to reading"],"answer":1,"explanation":"Contrastive analysis compares the structures of two languages to predict where learners may struggle; differences such as missing articles are likely trouble spots.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"यह जानते हुए कि हिंदी में अंग्रेज़ी के articles ‘a’ और ‘the’ का कोई सीधा समतुल्य नहीं है, एक शिक्षिका त्रुटियाँ आने से पहले ही अपने हिंदी भाषी कक्षा 6 के विद्यार्थियों के लिए articles पर अतिरिक्त कार्य की योजना बनाती है। वह किसकी अंतर्दृष्टि का उपयोग कर रही है?","optionsHi":["क्रैशेन की स्वाभाविक क्रम परिकल्पना (natural order hypothesis)","दोनों भाषाओं का व्यतिरेकी विश्लेषण (contrastive analysis)","जेम्स आशर की संपूर्ण शारीरिक प्रतिक्रिया (Total Physical Response)","पठन की भाषा-अनुभव उपागम (language experience approach)"],"explanationHi":"व्यतिरेकी विश्लेषण दो भाषाओं की संरचनाओं की तुलना करके अनुमान लगाता है कि अधिगमकर्ताओं को कहाँ कठिनाई हो सकती है; articles के न होने जैसे अंतर संभावित कठिन स्थल होते हैं।"},
  {"id":"cdp-pedagogy-subjects-1585","question":"Class 5 children survey which languages are spoken in their homes and neighbourhood and make a ‘language map’ of the class. The main purpose of this activity is to:","options":["Build respect for the class’s linguistic diversity","Find out which children should be moved to another section","Prove that English is the most important language in the class","Test children’s spelling of the names of languages"],"answer":0,"explanation":"Language mapping makes diversity visible, values every child’s languages and gives the teacher information she can use for planning multilingual activities.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"कक्षा 5 के बच्चे सर्वेक्षण करते हैं कि उनके घरों और पड़ोस में कौन-सी भाषाएँ बोली जाती हैं और कक्षा का ‘भाषा मानचित्र’ बनाते हैं। इस गतिविधि का मुख्य उद्देश्य है:","optionsHi":["कक्षा की भाषाई विविधता के प्रति सम्मान विकसित करना","यह पता लगाना कि किन बच्चों को दूसरे अनुभाग में भेजा जाना चाहिए","यह सिद्ध करना कि कक्षा में अंग्रेज़ी सबसे महत्वपूर्ण भाषा है","बच्चों की भाषाओं के नामों की वर्तनी की जाँच करना"],"explanationHi":"भाषा मानचित्रण विविधता को दृश्य बनाता है, हर बच्चे की भाषाओं को महत्व देता है और शिक्षिका को बहुभाषिक गतिविधियों की योजना बनाने में काम आने वाली जानकारी देता है।"},
  {"id":"cdp-pedagogy-subjects-1586","question":"A Class 2 teacher in a village school without a projector wants to teach ‘sieve’, ‘grater’, ‘ladle’ and ‘rolling pin’. Which teaching–learning material is most effective?","options":["A printed chart of the words with their dictionary definitions","A video on a website that the class cannot access","A list of the words to be copied ten times in notebooks","The real objects, which children can see, handle and use"],"answer":3,"explanation":"Realia make meanings concrete and memorable for young learners, especially for familiar household items, and need no technology.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"प्रोजेक्टर रहित एक गाँव के विद्यालय में कक्षा 2 की एक शिक्षिका ‘sieve’, ‘grater’, ‘ladle’ और ‘rolling pin’ पढ़ाना चाहती है। कौन-सी शिक्षण-अधिगम सामग्री सबसे प्रभावी है?","optionsHi":["शब्दों का छपा चार्ट जिसमें उनकी शब्दकोश-परिभाषाएँ हों","किसी वेबसाइट का वीडियो जिस तक कक्षा की पहुँच नहीं है","शब्दों की सूची जिन्हें कॉपियों में दस-दस बार उतारना है","असली वस्तुएँ, जिन्हें बच्चे देख, छू और उपयोग कर सकते हैं"],"explanationHi":"वास्तविक वस्तुएँ (realia) अर्थों को मूर्त और यादगार बनाती हैं, विशेषकर छोटे अधिगमकर्ताओं के लिए परिचित घरेलू वस्तुओं के संदर्भ में, और उनके लिए किसी प्रौद्योगिकी की आवश्यकता नहीं होती।"},
  {"id":"cdp-pedagogy-subjects-1587","question":"A Class 7 teacher uses the textbook but also brings local folk tales, newspaper cuttings, recipes and songs into her English lessons. Which statement best supports this?","options":["The textbook is useless and should be set aside","Only materials written by native speakers should be used","The textbook is one resource among many; varied texts enrich input","Extra materials should be used only after the syllabus is finished"],"answer":2,"explanation":"NCF 2005 cautions against treating the textbook as the only source of knowledge; diverse, relevant texts widen exposure and engagement.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 7 की एक शिक्षिका पाठ्यपुस्तक का उपयोग करती है, पर अपने अंग्रेज़ी पाठों में स्थानीय लोक-कथाएँ, समाचार-पत्र की कतरनें, व्यंजन-विधियाँ और गीत भी लाती है। इसका सबसे अच्छा समर्थन कौन-सा कथन करता है?","optionsHi":["पाठ्यपुस्तक व्यर्थ है और उसे एक ओर रख देना चाहिए","केवल मूल अंग्रेज़ी भाषियों द्वारा लिखी सामग्री का उपयोग होना चाहिए","पाठ्यपुस्तक अनेक संसाधनों में से एक है; विविध पाठ निवेश को समृद्ध करते हैं","अतिरिक्त सामग्री का उपयोग पाठ्यक्रम समाप्त होने के बाद ही होना चाहिए"],"explanationHi":"NCF 2005 पाठ्यपुस्तक को ज्ञान का एकमात्र स्रोत मानने के प्रति सावधान करती है; विविध और प्रासंगिक पाठ संपर्क और सहभागिता को व्यापक बनाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1588","question":"A shy Class 1 child who never speaks in class begins to talk in English when the teacher gives her a sock puppet and asks, ‘What does Bunny want to say?’ The puppet most likely helps because:","options":["Puppets teach grammar better than teachers do","Speaking as a character lowers her anxiety about mistakes","Puppets make the class noisy, which hides the child’s voice","The child is copying words the puppet maker wrote"],"answer":1,"explanation":"Puppets give a safe persona that lowers the affective filter; the child takes risks with language that she would not take as herself.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कक्षा 1 की एक संकोची बच्ची जो कक्षा में कभी नहीं बोलती, तब अंग्रेज़ी में बोलने लगती है जब शिक्षिका उसे मोज़े की कठपुतली देकर पूछती है, ‘What does Bunny want to say?’ कठपुतली संभवतः इसलिए मदद करती है क्योंकि:","optionsHi":["कठपुतलियाँ शिक्षकों से बेहतर व्याकरण सिखाती हैं","किसी पात्र के रूप में बोलने से उसकी गलतियों की चिंता कम होती है","कठपुतलियाँ कक्षा में शोर करती हैं, जिससे बच्ची की आवाज़ छिप जाती है","बच्ची कठपुतली बनाने वाले द्वारा लिखे शब्दों की नकल कर रही है"],"explanationHi":"कठपुतलियाँ एक सुरक्षित व्यक्तित्व देती हैं जो भावात्मक अवरोध (affective filter) को घटाता है; बच्ची भाषा में वे जोखिम लेती है जो वह अपने रूप में नहीं लेती।"},
  {"id":"cdp-pedagogy-subjects-1589","question":"Class 8 students record themselves giving a one-minute talk on a phone, listen back with a checklist and record a second, improved version. The main value of this use of technology is that it:","options":["Is useful only for testing pronunciation of single words","Replaces the teacher’s role in assessing speaking altogether","Lets students hear and assess their own speaking","Mainly trains students to use mobile phones well"],"answer":2,"explanation":"Recordings make spoken language visible for reflection, supporting self-assessment and rehearsal, which are hard to achieve with live speech alone.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 8 के विद्यार्थी फ़ोन पर एक मिनट का भाषण स्वयं रिकॉर्ड करते हैं, जाँच-सूची के साथ उसे दोबारा सुनते हैं और दूसरा, बेहतर संस्करण रिकॉर्ड करते हैं। प्रौद्योगिकी के इस उपयोग का मुख्य मूल्य यह है कि यह:","optionsHi":["केवल अलग-अलग शब्दों के उच्चारण की जाँच के लिए उपयोगी है","बोलने के आकलन में शिक्षिका की भूमिका को पूरी तरह बदल देता है","विद्यार्थियों को अपने बोलने को सुनने और उसका आकलन करने देता है","मुख्यतः विद्यार्थियों को मोबाइल फ़ोन का अच्छी तरह उपयोग करना सिखाता है"],"explanationHi":"रिकॉर्डिंग मौखिक भाषा को चिंतन के लिए दृश्य बनाती है, जिससे स्व-आकलन और पूर्वाभ्यास को सहारा मिलता है, जो केवल सीधे बोलने से पाना कठिन है।"},
  {"id":"cdp-pedagogy-subjects-1590","question":"A teacher cuts a sentence into word cards (‘every’, ‘morning’, ‘my’, ‘grandmother’, ‘walks’) and asks Class 3 groups to arrange them into a sentence. This low-cost material mainly develops:","options":["Handwriting through copying the cards","Awareness of English word order","Pronunciation of difficult sounds","Speed of silent reading of long texts"],"answer":1,"explanation":"Rebuilding jumbled sentences makes children think about how words combine into grammatical order, in a hands-on and collaborative way.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"एक शिक्षिका एक वाक्य को शब्द-कार्डों (‘every’, ‘morning’, ‘my’, ‘grandmother’, ‘walks’) में काटती है और कक्षा 3 के समूहों से उन्हें वाक्य में सजाने को कहती है। यह कम लागत वाली सामग्री मुख्यतः क्या विकसित करती है?","optionsHi":["कार्डों को उतारकर हस्तलेखन","अंग्रेज़ी शब्द-क्रम के प्रति जागरूकता","कठिन ध्वनियों का उच्चारण","लंबे पाठों को मौन पढ़ने की गति"],"explanationHi":"बिखरे वाक्यों को फिर से बनाने से बच्चे सोचते हैं कि शब्द व्याकरणिक क्रम में कैसे जुड़ते हैं, हाथ से करने और सहयोगात्मक ढंग से।"},
  {"id":"cdp-pedagogy-subjects-1591","question":"Which feature makes a picture book most suitable for emergent readers in Class 1?","options":["Predictable, repetitive text with rhythm, and pictures that support it","Long sentences that introduce many new words on each page to build vocabulary","Small print with few pictures, so that children focus fully on the printed words","A complex plot with many characters and flashbacks to hold children's interest"],"answer":0,"explanation":"Predictable books (‘Brown bear, brown bear, what do you see?’) let children anticipate words through repetition, rhythm and pictures, so they experience success early.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कक्षा 1 के उभरते पाठकों के लिए चित्र-पुस्तक को सबसे उपयुक्त कौन-सी विशेषता बनाती है?","optionsHi":["पूर्वानुमेय, दोहराव वाला, लय-युक्त पाठ और उसका समर्थन करने वाले चित्र","लंबे वाक्य जो शब्दावली बढ़ाने के लिए हर पृष्ठ पर कई नए शब्द लाते हैं","छोटे अक्षर और कम चित्र, ताकि बच्चे पूरी तरह छपे शब्दों पर ध्यान दें","अनेक पात्रों और पुनर्दृश्यों वाली जटिल कथानक, ताकि बच्चों की रुचि बनी रहे"],"explanationHi":"पूर्वानुमेय पुस्तकें (‘Brown bear, brown bear, what do you see?’) बच्चों को दोहराव, लय और चित्रों के सहारे शब्दों का अनुमान लगाने देती हैं, इसलिए उन्हें शुरू में ही सफलता का अनुभव होता है।"},
  {"id":"cdp-pedagogy-subjects-1592","question":"After reading a folk tale, Class 5 children complete a chart with boxes for ‘Setting’, ‘Characters’, ‘Problem’, ‘Main events’ and ‘Solution’. This organiser is called a:","options":["Venn diagram","Timeline of dates","KWL chart","Story map"],"answer":3,"explanation":"A story map shows the elements of a narrative and how they fit together, supporting comprehension, retelling and later story writing.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"एक लोक-कथा पढ़ने के बाद कक्षा 5 के बच्चे ‘स्थान-काल’, ‘पात्र’, ‘समस्या’, ‘मुख्य घटनाएँ’ और ‘समाधान’ के खानों वाला चार्ट पूरा करते हैं। इस आयोजक को कहते हैं:","optionsHi":["वेन आरेख","तिथियों की समय-रेखा","KWL चार्ट","कहानी मानचित्र (Story map)"],"explanationHi":"कहानी मानचित्र कथा के तत्वों और उनके आपस में जुड़ने के ढंग को दिखाता है, जिससे बोध, पुनः-कथन और आगे चलकर कहानी-लेखन में सहायता मिलती है।"},
  {"id":"cdp-pedagogy-subjects-1593","question":"A Class 3 teacher shows a colourful animation for every new word, and children watch passively while she clicks through slides. Which principle of using teaching–learning materials is being ignored?","options":["Materials should always be expensive and digital","Materials should engage children actively, not just decorate","Materials should be used only by the teacher, never by children","Materials should never include pictures"],"answer":1,"explanation":"Teaching aids are tools for learning; if children only watch, the material does not lead them to use language. A simple aid used actively often works better.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 3 की एक शिक्षिका हर नए शब्द के लिए रंगीन एनिमेशन दिखाती है, और बच्चे निष्क्रिय रूप से देखते रहते हैं जबकि वह स्लाइड बदलती जाती है। शिक्षण-अधिगम सामग्री के उपयोग के किस सिद्धांत की अनदेखी हो रही है?","optionsHi":["सामग्री हमेशा महँगी और डिजिटल होनी चाहिए","सामग्री को बच्चों को सक्रिय रूप से जोड़ना चाहिए, केवल सजावट नहीं करनी चाहिए","सामग्री का उपयोग केवल शिक्षिका को करना चाहिए, बच्चों को कभी नहीं","सामग्री में कभी चित्र नहीं होने चाहिए"],"explanationHi":"शिक्षण-सहायक सामग्री अधिगम के उपकरण हैं; यदि बच्चे केवल देखते हैं, तो सामग्री उन्हें भाषा का उपयोग करने तक नहीं ले जाती। सक्रिय रूप से उपयोग की गई सरल सहायक सामग्री प्रायः बेहतर काम करती है।"},
  {"id":"cdp-pedagogy-subjects-1594","question":"Match the dictionary type with the learner and purpose it suits best: 1. Picture dictionary 2. Learner’s dictionary with example sentences 3. Thesaurus 4. Bilingual dictionary; a. A Class 8 student checking how a word is used in a sentence b. A Class 1 child linking words to images c. A Class 9 writer looking for a more precise word d. A beginner checking the meaning of an English word in her home language","options":["1-b, 2-a, 3-c, 4-d","1-b, 2-c, 3-a, 4-d","1-d, 2-a, 3-c, 4-b","1-b, 2-a, 3-d, 4-c"],"answer":0,"explanation":"Picture dictionaries suit young children, learner’s dictionaries show usage, a thesaurus offers words of related meaning, and a bilingual dictionary links the two languages for beginners.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"शब्दकोश के प्रकार का मिलान उस अधिगमकर्ता और उद्देश्य से कीजिए जिसके लिए वह सबसे उपयुक्त है: 1. चित्र शब्दकोश 2. उदाहरण-वाक्यों वाला अधिगमकर्ता शब्दकोश 3. पर्यायवाची कोश (Thesaurus) 4. द्विभाषी शब्दकोश; a. कक्षा 8 का विद्यार्थी जो जाँच रहा है कि कोई शब्द वाक्य में कैसे प्रयुक्त होता है b. कक्षा 1 का बच्चा जो शब्दों को चित्रों से जोड़ रहा है c. कक्षा 9 का लेखक जो अधिक सटीक शब्द खोज रहा है d. शुरुआती अधिगमकर्ता जो किसी अंग्रेज़ी शब्द का अर्थ अपनी घरेलू भाषा में देख रही है","optionsHi":["1-b, 2-a, 3-c, 4-d","1-b, 2-c, 3-a, 4-d","1-d, 2-a, 3-c, 4-b","1-b, 2-a, 3-d, 4-c"],"explanationHi":"चित्र शब्दकोश छोटे बच्चों के लिए उपयुक्त हैं, अधिगमकर्ता शब्दकोश प्रयोग दिखाते हैं, पर्यायवाची कोश संबंधित अर्थ वाले शब्द देता है, और द्विभाषी शब्दकोश शुरुआती अधिगमकर्ताओं के लिए दोनों भाषाओं को जोड़ता है।"},
  {"id":"cdp-pedagogy-subjects-1595","question":"A teacher gives Class 6 students a comic strip with empty speech bubbles and asks them to write what the characters might be saying. This activity mainly develops:","options":["Writing natural dialogue that suits a situation","Copying model sentences from the textbook","Pronunciation of difficult words","Knowledge of the rules for changing to reported speech"],"answer":0,"explanation":"Pictures supply the situation and the bubbles require short, appropriate spoken-style language, combining creativity with awareness of how people talk in context.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"एक शिक्षिका कक्षा 6 के विद्यार्थियों को खाली संवाद-बुलबुलों वाली कॉमिक पट्टी देती है और उनसे लिखने को कहती है कि पात्र क्या कह रहे होंगे। यह गतिविधि मुख्यतः क्या विकसित करती है?","optionsHi":["किसी स्थिति के अनुरूप स्वाभाविक संवाद लिखना","पाठ्यपुस्तक से आदर्श वाक्य उतारना","कठिन शब्दों का उच्चारण","अप्रत्यक्ष कथन (reported speech) में बदलने के नियमों का ज्ञान"],"explanationHi":"चित्र स्थिति देते हैं और बुलबुले छोटी, उपयुक्त बोलचाल-शैली की भाषा माँगते हैं, जो रचनात्मकता को इस जागरूकता से जोड़ती है कि लोग संदर्भ में कैसे बोलते हैं।"},
  {"id":"cdp-pedagogy-subjects-1596","question":"Assertion (A): Placing minority-language children in an English-only classroom with no support often leads to poor learning. Reason (R): Without comprehensible input and support in the first language, children cannot easily connect the new language to meaning.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Such ‘submersion’ gives input that children cannot understand, so little is acquired and content learning also suffers; support in the home language makes input meaningful.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"अभिकथन (A): अल्पसंख्यक भाषा वाले बच्चों को बिना किसी सहायता के केवल अंग्रेज़ी वाली कक्षा में रखने से प्रायः अधिगम कमज़ोर रहता है। कारण (R): बोधगम्य निवेश और प्रथम भाषा में सहायता के बिना बच्चे नई भाषा को अर्थ से आसानी से नहीं जोड़ पाते। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"ऐसा ‘निमज्जन’ (submersion) ऐसा निवेश देता है जिसे बच्चे समझ नहीं सकते, इसलिए बहुत कम अर्जित होता है और विषय-वस्तु का अधिगम भी प्रभावित होता है; घरेलू भाषा में सहायता निवेश को सार्थक बनाती है।"},
  {"id":"cdp-pedagogy-subjects-1597","question":"Consider these statements: I. Code-switching by bilingual speakers usually follows patterns and is not random. II. Using the home language in class always slows down the learning of English. III. Bilingual children often show greater awareness of how language works. Which are correct?","options":["II and III only","I and II only","I and III only","I, II and III"],"answer":2,"explanation":"Code-switching is rule-governed and purposeful, and bilingualism is linked to stronger metalinguistic awareness. Well-planned use of the home language supports, rather than slows, English learning.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"इन कथनों पर विचार कीजिए: I. द्विभाषी वक्ताओं का कोड-स्विचिंग प्रायः पैटर्न का पालन करता है और यादृच्छिक नहीं होता। II. कक्षा में घरेलू भाषा का उपयोग हमेशा अंग्रेज़ी सीखने को धीमा करता है। III. द्विभाषी बच्चे प्रायः इस बारे में अधिक जागरूकता दिखाते हैं कि भाषा कैसे काम करती है। कौन-से सही हैं?","optionsHi":["केवल II और III","केवल I और II","केवल I और III","I, II और III"],"explanationHi":"कोड-स्विचिंग नियम-शासित और उद्देश्यपूर्ण होती है, और द्विभाषिकता सशक्त भाषाई जागरूकता से जुड़ी है। घरेलू भाषा का सुनियोजित उपयोग अंग्रेज़ी सीखने को धीमा करने के बजाय सहारा देता है।"},
  {"id":"cdp-pedagogy-subjects-1598","question":"A teacher puts objects in a cloth ‘feely bag’; a Class 2 child touches one without looking and describes it (‘It is soft… it is round… it is small’) while others guess. This activity mainly develops:","options":["Knowledge of the parts of speech","The spelling of the names of the objects","Silent reading of descriptive passages","Descriptive words linked to the senses"],"answer":3,"explanation":"The guessing game creates a real reason to describe, and touching gives concrete meaning to adjectives such as soft, rough and smooth.","difficulty":"moderate","source":"CTET Paper I · State TETs","questionHi":"एक शिक्षिका वस्तुएँ कपड़े के ‘छूकर पहचानो थैले’ (feely bag) में रखती है; कक्षा 2 का एक बच्चा बिना देखे एक वस्तु को छूकर उसका वर्णन करता है (‘यह मुलायम है… यह गोल है… यह छोटी है’) जबकि बाकी अनुमान लगाते हैं। यह गतिविधि मुख्यतः क्या विकसित करती है?","optionsHi":["शब्द-भेदों का ज्ञान","वस्तुओं के नामों की वर्तनी","वर्णनात्मक गद्यांशों का मौन पठन","इंद्रियों से जुड़े वर्णनात्मक शब्द"],"explanationHi":"अनुमान का खेल वर्णन करने का वास्तविक कारण बनाता है, और छूने से मुलायम, खुरदरा तथा चिकना जैसे विशेषणों को मूर्त अर्थ मिलता है।"},
  {"id":"cdp-pedagogy-subjects-1599","question":"In a Class 10 letter, a student writes, ‘Kindly do the needful and prepone the meeting.’ Which response best reflects a sound understanding of English as used in India?","options":["Mark both expressions as errors that must be removed from Indian students’ English","Explain that these are Indian English usages that some readers abroad may not know","Treat them as fossilised errors that need daily drilling of the British forms","Call them slang that is never acceptable in any kind of formal writing"],"answer":1,"explanation":"‘Prepone’ and ‘do the needful’ are established in Indian English. A sound approach builds awareness of audience, so students can choose forms that readers in different contexts will understand.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 10 के एक पत्र में एक विद्यार्थी लिखता है, ‘Kindly do the needful and prepone the meeting.’ कौन-सी प्रतिक्रिया भारत में प्रयुक्त अंग्रेज़ी की सही समझ को सबसे अच्छी तरह दर्शाती है?","optionsHi":["दोनों अभिव्यक्तियों को गलती मानकर चिह्नित करना जिन्हें भारतीय विद्यार्थियों की अंग्रेज़ी से हटाना ही होगा","समझाना कि ये भारतीय अंग्रेज़ी के प्रयोग हैं जिन्हें विदेश के कुछ पाठक शायद न जानते हों","इन्हें जड़ीभूत (fossilised) त्रुटियाँ मानना जिनके लिए ब्रिटिश रूपों का रोज़ अभ्यास आवश्यक है","इन्हें अपशब्द-शैली (slang) कहना जो किसी भी औपचारिक लेखन में कभी स्वीकार्य नहीं है"],"explanationHi":"‘Prepone’ और ‘do the needful’ भारतीय अंग्रेज़ी में स्थापित हैं। सही दृष्टिकोण पाठक-वर्ग की जागरूकता बनाता है, ताकि विद्यार्थी ऐसे रूप चुन सकें जिन्हें अलग-अलग संदर्भों के पाठक समझ सकें।"},
  {"id":"cdp-pedagogy-subjects-1600","question":"A Class 3 child writes 7 × 0 = 7. Which question best helps her see the error?","options":["‘There are 7 plates with 0 laddoos on each. How many laddoos in all?’","‘What is 7 + 0? Now use that same idea to work out 7 × 0 for me.’","‘Can you say the table of 7 again, slowly, starting from 7 × 1 up to 7 × 10?’","‘What is 0 × 0? And what do you get when you multiply 0 by 1?’"],"answer":0,"explanation":"She is applying the rule for adding 0 to multiplication. A story about 7 groups of nothing shows the total is 0; asking about 7 + 0 would only strengthen the confusion.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की एक बच्ची लिखती है 7 × 0 = 7। कौन-सा प्रश्न उसे त्रुटि देखने में सबसे अच्छी तरह मदद करता है?","optionsHi":["‘7 थालियाँ हैं और हर एक में 0 लड्डू हैं। कुल कितने लड्डू हुए?’","‘7 + 0 कितना होता है? अब उसी विचार से मुझे 7 × 0 निकालकर बताओ।’","‘क्या तुम 7 का पहाड़ा फिर से धीरे-धीरे बोल सकती हो, 7 × 1 से 7 × 10 तक?’","‘0 × 0 कितना होता है? और 0 को 1 से गुणा करने पर क्या मिलता है?’"],"explanationHi":"वह गुणा में 0 जोड़ने का नियम लगा रही है। 7 समूहों के बारे में, जिनमें कुछ नहीं है, कहानी दिखाती है कि कुल 0 है; 7 + 0 के बारे में पूछने से भ्रम और बढ़ेगा।"},
  {"id":"cdp-pedagogy-subjects-1601","question":"A Class 4 child multiplies 305 × 4 and writes 1200. Her working shows: 5 × 4 = 20, write 0, carry 2; then she writes 0 in the tens place; then 3 × 4 = 12. What is the most likely misconception?","options":["She does not know the fact 5 × 4 well, and so gets the very first partial product wrong","She thinks 0 makes everything 0, so she drops the carried 2 when the tens digit is 0","She has carried the 2 into the hundreds place instead of into the tens place","She multiplied 30 by 4 instead of 305 by 4, leaving out the ones digit"],"answer":1,"explanation":"In the tens place, 0 × 4 = 0 and the carried 2 must still be added, giving 2; the answer is 1220. Treating ‘0 makes everything 0’ as a rule wipes out the carry.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"कक्षा 4 की एक बच्ची 305 × 4 करती है और 1200 लिखती है। उसके कार्य में दिखता है: 5 × 4 = 20, 0 लिखो, 2 हासिल; फिर वह दहाई के स्थान पर 0 लिखती है; फिर 3 × 4 = 12। सबसे संभावित भ्रांति क्या है?","optionsHi":["वह 5 × 4 का तथ्य अच्छी तरह नहीं जानती, इसलिए सबसे पहला आंशिक गुणनफल ही गलत कर देती है","वह सोचती है कि 0 सब कुछ 0 कर देता है, इसलिए वह हासिल 2 को छोड़ देती है जब दहाई का अंक 0 होता है","उसने हासिल 2 को दहाई के स्थान के बजाय सैकड़े के स्थान पर ले लिया है","उसने 30 को 4 से गुणा किया, 305 को 4 से नहीं, इकाई का अंक छोड़ दिया"],"explanationHi":"दहाई के स्थान पर 0 × 4 = 0 और हासिल 2 को फिर भी जोड़ना होता है, जिससे 2 मिलता है; उत्तर 1220 है। ‘0 सब कुछ 0 कर देता है’ को नियम मान लेना हासिल को मिटा देता है।"},
  {"id":"cdp-pedagogy-subjects-1602","question":"A Class 3 child writes 400 − 6 = 400, explaining ‘0 take away 6 is nothing’. What is the best response?","options":["Tell her to subtract the smaller digit from the bigger one in each column, so 6 − 0 = 6","Ask her to memorise the rule for subtracting from zero and practise it on ten sums","Ask her to show 400 with bundles and take 6 sticks away, opening a bundle when needed","Give her more subtraction sums without zeros first, and return to zeros much later"],"answer":2,"explanation":"She has a rule that 0 − n = 0. With bundles she must open a hundred into tens and a ten into ones to take 6 away, leaving 394; this shows why regrouping across zeros is needed.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की एक बच्ची लिखती है 400 − 6 = 400, यह समझाते हुए कि ‘0 में से 6 घटाने पर कुछ नहीं बचता’। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["उससे कहना कि हर स्तंभ में छोटे अंक को बड़े में से घटाए, इसलिए 6 − 0 = 6","उससे शून्य में से घटाने का नियम रटने और दस प्रश्नों पर उसका अभ्यास करने को कहना","उससे 400 को गड्डियों से दिखाने और 6 तीलियाँ हटाने को कहना, ज़रूरत होने पर एक गड्डी खोलते हुए","पहले उसे बिना शून्य वाले घटाव के प्रश्न देना और शून्य वाले प्रश्नों पर बहुत बाद में लौटना"],"explanationHi":"उसके पास यह नियम है कि 0 − n = 0। गड्डियों से उसे 6 घटाने के लिए एक सैकड़ा खोलकर दहाइयों में और एक दहाई खोलकर इकाइयों में बदलना होगा, जिससे 394 बचता है; इससे दिखता है कि शून्यों के पार पुनःसमूहन क्यों आवश्यक है।"},
  {"id":"cdp-pedagogy-subjects-1603","question":"A Class 4 child says 12 ÷ 4 and 4 ÷ 12 are the same ‘because the numbers are the same, just like 12 × 4 and 4 × 12’. Which response is best?","options":["Agree with her, since division is the opposite of multiplication and follows the same rules","Tell her that division is never possible when the first number is smaller than the second","Ask her to learn by heart that division is not commutative and write it in her notebook","Ask her to compare sharing 12 rotis among 4 children with sharing 4 rotis among 12"],"answer":3,"explanation":"Sharing 12 among 4 gives 3 each, while 4 among 12 gives 1/3 each. The two situations make it clear that order matters in division, unlike multiplication.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 की एक बच्ची कहती है कि 12 ÷ 4 और 4 ÷ 12 समान हैं ‘क्योंकि संख्याएँ वही हैं, जैसे 12 × 4 और 4 × 12’। कौन-सी प्रतिक्रिया सबसे अच्छी है?","optionsHi":["उससे सहमत होना, क्योंकि भाग गुणा का उलटा है और उन्हीं नियमों का पालन करता है","उससे कहना कि जब पहली संख्या दूसरी से छोटी हो तो भाग कभी संभव नहीं होता","उससे यह रटने को कहना कि भाग क्रम-विनिमेय नहीं है और उसे कॉपी में लिखना","उससे 12 रोटियाँ 4 बच्चों में बाँटने की तुलना 4 रोटियाँ 12 बच्चों में बाँटने से करने को कहना"],"explanationHi":"12 को 4 में बाँटने पर हर एक को 3 मिलता है, जबकि 4 को 12 में बाँटने पर हर एक को 1/3 मिलता है। दोनों स्थितियाँ स्पष्ट करती हैं कि गुणा के विपरीत भाग में क्रम मायने रखता है।"},
  {"id":"cdp-pedagogy-subjects-1604","question":"Class 4 children use every number given in a word problem, even when some are not needed. What is the most useful teaching response?","options":["Give problems with extra information; children cross out what is not needed and say why","Give only problems with exactly the numbers needed, so that children are not confused","Teach key words for each operation, such as 'altogether' for addition and 'left' for subtraction","Tell children to use only the first two numbers in a problem and ignore any others"],"answer":0,"explanation":"Deciding what information is relevant is part of understanding a problem. Problems with extra data build this skill; problems with only the needed numbers let children succeed without reading carefully.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 के बच्चे शाब्दिक प्रश्न में दी गई हर संख्या का उपयोग करते हैं, भले ही कुछ आवश्यक न हों। सबसे उपयोगी शिक्षण-प्रतिक्रिया क्या है?","optionsHi":["अतिरिक्त जानकारी वाले प्रश्न देना; बच्चे जो आवश्यक नहीं उसे काटते हैं और बताते हैं कि क्यों","केवल उतनी ही संख्याओं वाले प्रश्न देना जितनी आवश्यक हों, ताकि बच्चे भ्रमित न हों","हर संक्रिया के लिए कुंजी-शब्द सिखाना, जैसे जोड़ के लिए ‘कुल’ और घटाव के लिए ‘बचे’","बच्चों से कहना कि प्रश्न में केवल पहली दो संख्याएँ इस्तेमाल करें और बाकी की अनदेखी करें"],"explanationHi":"कौन-सी जानकारी प्रासंगिक है, यह तय करना प्रश्न को समझने का हिस्सा है। अतिरिक्त आँकड़ों वाले प्रश्न इस कौशल को बनाते हैं; केवल आवश्यक संख्याओं वाले प्रश्न बच्चों को ध्यान से पढ़े बिना सफल होने देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1605","question":"In a discussion on ‘Is 1 a prime number?’, which student argument is mathematically strongest?","options":["‘No, because my teacher told us so last year, and it is also written in the book.’","‘No, because a prime has exactly two different factors, and 1 has only one.’","‘Yes, because 1 cannot be divided exactly by any other number except itself.’","‘No, because 1 is too small to be prime; primes begin only from the number 2.’"],"answer":1,"explanation":"The strongest argument uses the definition. A prime has exactly two distinct factors, 1 and itself; 1 has only one factor. Answers from authority or size are not mathematical reasons.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"‘क्या 1 अभाज्य संख्या है?’ पर चर्चा में, कौन-सा विद्यार्थी-तर्क गणितीय रूप से सबसे मज़बूत है?","optionsHi":["‘नहीं, क्योंकि हमारे शिक्षक ने पिछले साल हमें ऐसा बताया था, और यह किताब में भी लिखा है।’","‘नहीं, क्योंकि अभाज्य संख्या के ठीक दो भिन्न गुणनखंड होते हैं, और 1 का केवल एक है।’","‘हाँ, क्योंकि 1 को स्वयं के अलावा किसी अन्य संख्या से पूर्णतः विभाजित नहीं किया जा सकता।’","‘नहीं, क्योंकि 1 अभाज्य होने के लिए बहुत छोटा है; अभाज्य संख्याएँ केवल 2 से शुरू होती हैं।’"],"explanationHi":"सबसे मज़बूत तर्क परिभाषा का उपयोग करता है। अभाज्य संख्या के ठीक दो भिन्न गुणनखंड होते हैं, 1 और वह स्वयं; 1 का केवल एक गुणनखंड है। अधिकार या आकार पर आधारित उत्तर गणितीय कारण नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-1606","question":"Asked to write a number sentence for ‘5 less than 12’, a Class 3 child writes 5 − 12. What is the best explanation?","options":["She does not know how to subtract and has not learnt to take away numbers","She does not understand the meaning of the word ‘less’ in a maths question","She writes the numbers in the order she hears them, though it means 12 − 5","She thinks subtraction can be done in any order, just like addition can"],"answer":2,"explanation":"‘5 less than 12’ starts from 12 and takes away 5. Translating word by word reverses the order, a common language difficulty in maths that acting out or drawing can correct.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"‘12 से 5 कम’ के लिए संख्या-वाक्य लिखने को कहे जाने पर कक्षा 3 की एक बच्ची 5 − 12 लिखती है। सबसे अच्छा स्पष्टीकरण क्या है?","optionsHi":["वह घटाना नहीं जानती और संख्याएँ घटाना नहीं सीखा है","वह गणित के प्रश्न में ‘कम’ शब्द का अर्थ नहीं समझती","वह संख्याएँ उसी क्रम में लिखती है जिसमें सुनती है, जबकि अर्थ 12 − 5 है","वह सोचती है कि घटाव किसी भी क्रम में किया जा सकता है, जैसे जोड़ किया जा सकता है"],"explanationHi":"‘12 से 5 कम’ का अर्थ 12 से शुरू करके 5 घटाना है। शब्द-दर-शब्द अनुवाद क्रम उलट देता है, जो गणित में एक आम भाषाई कठिनाई है जिसे अभिनय करके या चित्र बनाकर सुधारा जा सकता है।"},
  {"id":"cdp-pedagogy-subjects-1607","question":"A parent often tells her child, ‘Don't worry, I was also bad at maths.’ How should a teacher see this, and respond?","options":["As helpful, since it removes pressure from the child and makes failure in maths feel normal","As unimportant, since what parents say at home has little effect on learning in school","As a reason to give the child easier work, since the child may have inherited a weakness","As a message that maths ability is fixed; she should share that ability grows with effort"],"answer":3,"explanation":"Well-meant comfort can lower expectations and suggest that maths is a fixed gift. Working with parents to spread a growth view of ability supports the child's effort and confidence.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"एक अभिभावक अक्सर अपने बच्चे से कहती है, ‘चिंता मत करो, मैं भी गणित में कमज़ोर थी।’ शिक्षक को इसे कैसे देखना चाहिए और क्या प्रतिक्रिया देनी चाहिए?","optionsHi":["सहायक के रूप में, क्योंकि यह बच्चे से दबाव हटाता है और गणित में असफलता को सामान्य बना देता है","महत्वहीन के रूप में, क्योंकि घर पर अभिभावक जो कहते हैं उसका विद्यालय के अधिगम पर बहुत कम प्रभाव पड़ता है","बच्चे को आसान कार्य देने के कारण के रूप में, क्योंकि बच्चे को कमज़ोरी विरासत में मिली हो सकती है","इस संदेश के रूप में कि गणित की योग्यता स्थिर है; उसे साझा करना चाहिए कि योग्यता प्रयास से बढ़ती है"],"explanationHi":"अच्छी नीयत से दिया गया सांत्वना-भाव अपेक्षाएँ घटा सकता है और सुझा सकता है कि गणित एक स्थिर उपहार है। अभिभावकों के साथ मिलकर योग्यता के विकासशील दृष्टिकोण (growth view) को फैलाना बच्चे के प्रयास और आत्मविश्वास को सहारा देता है।"},
  {"id":"cdp-pedagogy-subjects-1608","question":"A Class 6 student sorts quadrilaterals correctly by properties such as ‘has parallel sides’ and ‘has right angles’ but says a square cannot be a rhombus. At which Van Hiele level is she reasoning?","options":["Analysis: she uses properties but does not yet relate one class of shapes to another","Visualisation: she judges shapes only by how they look as a whole, not by properties","Informal deduction: she sees how the properties of different shapes are logically linked","Deduction: she can build formal proofs about shapes from axioms and definitions"],"answer":0,"explanation":"Describing shapes by properties is analysis. Seeing that a square has all the properties of a rhombus, and so belongs to that class, needs informal deduction, which she has not yet reached.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक विद्यार्थी चतुर्भुजों को ‘समांतर भुजाएँ हैं’ और ‘समकोण हैं’ जैसे गुणों के आधार पर सही-सही छाँटती है, परंतु कहती है कि वर्ग समचतुर्भुज नहीं हो सकता। वह वैन हील (Van Hiele) के किस स्तर पर तर्क कर रही है?","optionsHi":["विश्लेषण: वह गुणों का उपयोग करती है पर अभी एक आकृति-वर्ग को दूसरे से नहीं जोड़ती","दृश्यीकरण: वह आकृतियों को केवल समग्र रूप से कैसी दिखती हैं उससे आँकती है, गुणों से नहीं","अनौपचारिक निगमन: वह देखती है कि विभिन्न आकृतियों के गुण तार्किक रूप से कैसे जुड़े हैं","निगमन: वह अभिधारणाओं और परिभाषाओं से आकृतियों के बारे में औपचारिक उपपत्तियाँ बना सकती है"],"explanationHi":"आकृतियों का गुणों के आधार पर वर्णन करना विश्लेषण है। यह देखना कि वर्ग में समचतुर्भुज के सभी गुण हैं, और इसलिए वह उसी वर्ग का सदस्य है, अनौपचारिक निगमन माँगता है, जहाँ वह अभी नहीं पहुँची है।"},
  {"id":"cdp-pedagogy-subjects-1609","question":"After learning the properties of a rhombus and a kite, students get the task: ‘Change a rhombus into a kite that is not a rhombus by moving only one vertex. Find as many ways as you can and explain them.’ Which Van Hiele learning phase does this task belong to?","options":["Inquiry (information)","Free orientation","Directed (guided) orientation","Explicitation"],"answer":1,"explanation":"Free orientation gives open, many-step tasks that students solve in their own ways, using properties they already know. Directed orientation uses short, teacher-led steps towards one property.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"समचतुर्भुज और पतंगाकार (kite) के गुण सीखने के बाद विद्यार्थियों को कार्य मिलता है: ‘केवल एक शीर्ष हिलाकर समचतुर्भुज को ऐसे पतंगाकार में बदलो जो समचतुर्भुज न हो। जितने तरीके ढूँढ सको ढूँढो और उन्हें समझाओ।’ यह कार्य वैन हील के किस अधिगम चरण का है?","optionsHi":["जाँच (सूचना)","मुक्त अभिविन्यास","निर्देशित अभिविन्यास","स्पष्टीकरण (Explicitation)"],"explanationHi":"मुक्त अभिविन्यास खुले, बहु-चरणीय कार्य देता है जिन्हें विद्यार्थी अपने ढंग से, पहले से ज्ञात गुणों का उपयोग करके हल करते हैं। निर्देशित अभिविन्यास किसी एक गुण की ओर छोटे, शिक्षक-नेतृत्व वाले चरणों का उपयोग करता है।"},
  {"id":"cdp-pedagogy-subjects-1610","question":"At the end of a unit, students make a chart showing how squares, rectangles, rhombuses, parallelograms and kites are related, and use it to summarise what they learnt. Which Van Hiele phase is this?","options":["Directed orientation","Explicitation","Integration","Free orientation"],"answer":2,"explanation":"In integration, the last phase, students review and pull together what they have learnt into an overall picture. The teacher helps them build this overview but does not add new ideas.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"इकाई के अंत में विद्यार्थी एक चार्ट बनाते हैं जो दिखाता है कि वर्ग, आयत, समचतुर्भुज, समांतर चतुर्भुज और पतंगाकार आपस में कैसे संबंधित हैं, और उससे जो सीखा उसका सारांश बनाते हैं। यह वैन हील का कौन-सा चरण है?","optionsHi":["निर्देशित अभिविन्यास","स्पष्टीकरण","एकीकरण (Integration)","मुक्त अभिविन्यास"],"explanationHi":"अंतिम चरण, एकीकरण में, विद्यार्थी जो सीखा उसकी समीक्षा करके उसे एक समग्र चित्र में जोड़ते हैं। शिक्षक इस अवलोकन को बनाने में मदद करता है पर कोई नया विचार नहीं जोड़ता।"},
  {"id":"cdp-pedagogy-subjects-1611","question":"After a class solves the handshake problem for 10 people, the teacher asks, ‘Could your method work for 50 people? Can you solve it another way?’ In Pólya's model, this is:","options":["understanding the problem","devising a plan","carrying out the plan","looking back"],"answer":3,"explanation":"Looking back means checking the result, trying other methods and extending the solution to new cases. It is the stage most often skipped and the one that builds generalisation.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"जब कक्षा 10 व्यक्तियों के लिए हाथ मिलाने की समस्या हल कर लेती है, तो शिक्षक पूछता है, ‘क्या तुम्हारी विधि 50 व्यक्तियों के लिए भी काम करेगी? क्या तुम इसे किसी और तरह से हल कर सकते हो?’ पोल्या के मॉडल में यह है:","optionsHi":["समस्या को समझना","योजना बनाना","योजना को कार्यान्वित करना","पीछे मुड़कर देखना"],"explanationHi":"पीछे मुड़कर देखने का अर्थ है परिणाम की जाँच करना, अन्य विधियाँ आज़माना और हल को नए मामलों तक विस्तारित करना। यह वह चरण है जो सबसे अधिक छोड़ दिया जाता है और जो सामान्यीकरण बनाता है।"},
  {"id":"cdp-pedagogy-subjects-1612","question":"Asked ‘How many squares are there on a chessboard?’, all students in a Class 6 class answer 64. Which prompt from the teacher is best?","options":["‘Are there squares bigger than one small square on the board?’","‘The answer is actually 204; can you check it and find out why?’","‘Count only the white squares and then double your answer.’","‘64 is correct; well done. Now let us move on to the next problem.’"],"answer":0,"explanation":"The question has a trap: squares of sizes 1 × 1 up to 8 × 8 give 64 + 49 + … + 1 = 204. A prompt that reopens the problem keeps the thinking with the students; giving the answer ends it.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"‘शतरंज के बोर्ड पर कितने वर्ग होते हैं?’ पूछे जाने पर कक्षा 6 के सभी विद्यार्थी 64 उत्तर देते हैं। शिक्षक का कौन-सा संकेत-प्रश्न सबसे अच्छा है?","optionsHi":["‘क्या बोर्ड पर एक छोटे वर्ग से बड़े वर्ग भी हैं?’","‘उत्तर वास्तव में 204 है; क्या तुम इसे जाँचकर पता लगा सकते हो कि क्यों?’","‘केवल सफ़ेद वर्ग गिनो और फिर अपने उत्तर को दोगुना कर दो।’","‘64 सही है; शाबाश। अब आगे अगले प्रश्न पर चलते हैं।’"],"explanationHi":"प्रश्न में एक जाल है: 1 × 1 से 8 × 8 तक के आकार के वर्ग मिलाकर 64 + 49 + … + 1 = 204 देते हैं। जो संकेत समस्या को फिर से खोलता है वह चिंतन विद्यार्थियों के पास रखता है; उत्तर बता देना उसे समाप्त कर देता है।"},
  {"id":"cdp-pedagogy-subjects-1613","question":"A Class 4 child works out 5 hours 10 minutes − 2 hours 40 minutes and writes 2 hours 70 minutes. What has the child most likely done?","options":["Subtracted the hours wrongly, taking 2 from 5 to get 2 instead of 3","Regrouped one hour as 100 minutes instead of 60, as in place value","Added the minutes instead of subtracting them, then adjusted the hours","Read the two times from a clock face wrongly before she subtracted"],"answer":1,"explanation":"Borrowing an hour gives 60 + 10 = 70 minutes, and 70 − 40 = 30, so the answer is 2 hours 30 minutes. Her 110 − 40 = 70 shows she is using base-ten regrouping for time.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"कक्षा 4 की एक बच्ची 5 घंटे 10 मिनट − 2 घंटे 40 मिनट हल करती है और 2 घंटे 70 मिनट लिखती है। बच्ची ने संभवतः क्या किया है?","optionsHi":["घंटों का घटाव गलत किया, 2 को 5 में से घटाकर 2 पाया, 3 नहीं","एक घंटे को 100 मिनट मानकर पुनःसमूहन किया, 60 मिनट के बजाय, स्थानमान की तरह","मिनटों को घटाने के बजाय जोड़ दिया, फिर घंटों को समायोजित किया","घटाने से पहले घड़ी के चेहरे से दोनों समय गलत पढ़े"],"explanationHi":"एक घंटा उधार लेने पर 60 + 10 = 70 मिनट मिलते हैं, और 70 − 40 = 30, इसलिए उत्तर 2 घंटे 30 मिनट है। उसका 110 − 40 = 70 दिखाता है कि वह समय के लिए दशमलव-आधारित पुनःसमूहन का उपयोग कर रही है।"},
  {"id":"cdp-pedagogy-subjects-1614","question":"A Class 6 child writes 3 1/2 − 1 3/4 = 2 1/4. What has she done?","options":["Changed both mixed numbers into improper fractions wrongly before subtracting them","Used a wrong common denominator for 1/2 and 3/4, so the fraction parts went wrong","Subtracted wholes, then 1/2 from 3/4 as 1/2 is smaller, instead of regrouping a whole","Added the fractional parts instead of subtracting them, while subtracting the wholes"],"answer":2,"explanation":"Since 1/2 < 3/4, one whole must be regrouped: 2 3/2 − 1 3/4 = 1 3/4. Taking the smaller fraction from the larger is the fraction form of the ‘smaller from larger’ error in whole numbers.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक बच्ची लिखती है 3 1/2 − 1 3/4 = 2 1/4। उसने क्या किया है?","optionsHi":["घटाने से पहले दोनों मिश्र संख्याओं को गलत ढंग से विषम भिन्नों में बदला","1/2 और 3/4 के लिए गलत समान हर का उपयोग किया, इसलिए भिन्न वाले भाग गलत हो गए","पूर्ण संख्याएँ घटाईं, फिर 1/2 को 3/4 में से घटाया क्योंकि 1/2 छोटा है, एक पूर्ण का पुनःसमूहन करने के बजाय","भिन्नात्मक भागों को घटाने के बजाय जोड़ दिया, जबकि पूर्ण संख्याओं को घटाया"],"explanationHi":"चूँकि 1/2 < 3/4, एक पूर्ण का पुनःसमूहन करना होगा: 2 3/2 − 1 3/4 = 1 3/4। छोटे भिन्न को बड़े में से घटाना, पूर्ण संख्याओं में ‘छोटे को बड़े में से घटाने’ वाली त्रुटि का भिन्न-रूप है।"},
  {"id":"cdp-pedagogy-subjects-1615","question":"NCF 2005 calls for engaging every student with a sense of success while also offering challenge. Which task design best fits this?","options":["Separate easy worksheets for weak students and hard ones for bright students throughout the year","The same set of routine exercises for all students, so that everyone gets an equal chance to succeed","Only the textbook's ‘challenge’ problems for everyone, so that all students are stretched to the limit","Easy-to-start tasks that can go far, e.g. ‘Find numbers that are sums of consecutive numbers’"],"answer":3,"explanation":"Low-floor, high-ceiling tasks let every child succeed at some level while the most able go deeper. Permanent labelling with easy and hard sheets limits what some children can reach.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"NCF 2005 हर विद्यार्थी को सफलता की भावना के साथ जोड़ने और साथ ही चुनौती देने का आह्वान करती है। कौन-सा कार्य-डिज़ाइन इसके सबसे अनुकूल है?","optionsHi":["पूरे वर्ष कमज़ोर विद्यार्थियों के लिए अलग आसान कार्यपत्रक और तेज़ विद्यार्थियों के लिए कठिन कार्यपत्रक","सभी विद्यार्थियों के लिए नियमित अभ्यासों का एक ही समूह, ताकि सबको सफलता का समान अवसर मिले","सबके लिए केवल पाठ्यपुस्तक के ‘चुनौती’ वाले प्रश्न, ताकि सभी विद्यार्थी अपनी सीमा तक खिंचें","शुरू करने में आसान, पर दूर तक जा सकने वाले कार्य, जैसे ‘ऐसी संख्याएँ ढूँढो जो क्रमागत संख्याओं के योग हों’"],"explanationHi":"निम्न-आरंभ, उच्च-शिखर वाले कार्य हर बच्चे को किसी न किसी स्तर पर सफल होने देते हैं जबकि सबसे सक्षम गहराई तक जा सकते हैं। आसान और कठिन पत्रकों से स्थायी ठप्पा लगाना कुछ बच्चों की पहुँच को सीमित करता है।"},
  {"id":"cdp-pedagogy-subjects-1616","question":"A Class 6 student says two lines drawn on a page are parallel because they do not meet on the page. What is the best response?","options":["Ask her to extend both lines with a ruler and check whether the gap stays the same","Agree, since lines that do not meet anywhere on the page must be parallel to each other","Tell her to measure the length of each line, since parallel lines must be equal in length","Tell her that parallel lines must be horizontal, like the lines in her ruled notebook"],"answer":0,"explanation":"Lines that look separate on a page may meet when extended. Parallel lines never meet however far they are extended, which means the distance between them stays the same everywhere.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक विद्यार्थी कहती है कि पृष्ठ पर खींची दो रेखाएँ समांतर हैं क्योंकि वे पृष्ठ पर नहीं मिलतीं। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["उससे पटरी से दोनों रेखाओं को बढ़ाने और जाँचने को कहना कि दूरी समान रहती है या नहीं","सहमत होना, क्योंकि जो रेखाएँ पृष्ठ पर कहीं नहीं मिलतीं वे एक-दूसरे के समांतर होनी ही चाहिए","उससे हर रेखा की लंबाई मापने को कहना, क्योंकि समांतर रेखाएँ लंबाई में बराबर होनी चाहिए","उससे कहना कि समांतर रेखाएँ क्षैतिज होनी चाहिए, जैसे उसकी रेखित कॉपी की रेखाएँ"],"explanationHi":"पृष्ठ पर अलग दिखने वाली रेखाएँ बढ़ाने पर मिल सकती हैं। समांतर रेखाएँ कितनी भी बढ़ाने पर कभी नहीं मिलतीं, जिसका अर्थ है कि उनके बीच की दूरी हर जगह समान रहती है।"},
  {"id":"cdp-pedagogy-subjects-1617","question":"A Class 2 child says a big balloon must be heavier than a small stone. Which activity best addresses this?","options":["Tell her clearly that size has nothing to do with weight and ask her to remember it","Let her predict which side will go down, then compare the two on a simple pan balance","Show her pictures of heavy and light things and ask her to sort them into two groups","Ask her to compare the two by looking carefully at their size and shape before deciding"],"answer":1,"explanation":"Young children often judge weight by size. Predicting and then testing on a balance gives direct evidence that big things can be light and small things heavy.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 2 की एक बच्ची कहती है कि बड़ा गुब्बारा छोटे पत्थर से भारी होगा ही। कौन-सी गतिविधि इसे सबसे अच्छी तरह संबोधित करती है?","optionsHi":["उससे स्पष्ट कहना कि आकार का भार से कोई संबंध नहीं है और उसे याद रखने को कहना","उसे अनुमान लगाने देना कि कौन-सा पलड़ा नीचे जाएगा, फिर सरल पलड़ा तराजू पर दोनों की तुलना करना","उसे भारी और हल्की चीज़ों के चित्र दिखाना और दो समूहों में छाँटने को कहना","उससे निर्णय लेने से पहले दोनों के आकार और रूप को ध्यान से देखकर तुलना करने को कहना"],"explanationHi":"छोटे बच्चे प्रायः आकार से भार का निर्णय करते हैं। अनुमान लगाना और फिर तराजू पर परखना प्रत्यक्ष साक्ष्य देता है कि बड़ी चीज़ें हल्की और छोटी चीज़ें भारी हो सकती हैं।"},
  {"id":"cdp-pedagogy-subjects-1618","question":"A teacher asks, ‘The answer is 24. What could the question be?’ What is the main value of this kind of question for assessment?","options":["It is quick to mark, since every child's answer will be the same number, 24","It tests only multiplication facts, since 24 is best reached through the tables","Children give many different answers, showing the range and depth of understanding","It is suitable only for gifted children, since others cannot handle an open question"],"answer":2,"explanation":"An open question lets each child respond at her own level, from 20 + 4 to 1/2 of 48 or 4 × 6. The variety shows the teacher what each child understands.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"एक शिक्षिका पूछती है, ‘उत्तर 24 है। प्रश्न क्या हो सकता है?’ आकलन के लिए इस प्रकार के प्रश्न का मुख्य मूल्य क्या है?","optionsHi":["इसे जाँचना तेज़ है, क्योंकि हर बच्चे का उत्तर वही संख्या, 24, होगा","यह केवल गुणा के तथ्यों की परीक्षा लेता है, क्योंकि 24 तक पहाड़ों से ही सबसे अच्छी तरह पहुँचा जाता है","बच्चे अनेक अलग-अलग उत्तर देते हैं, जो समझ की सीमा और गहराई दिखाते हैं","यह केवल प्रतिभाशाली बच्चों के लिए उपयुक्त है, क्योंकि बाकी खुला प्रश्न नहीं सँभाल सकते"],"explanationHi":"खुला प्रश्न हर बच्चे को अपने स्तर पर उत्तर देने देता है, 20 + 4 से लेकर 48 का 1/2 या 4 × 6 तक। यह विविधता शिक्षिका को दिखाती है कि हर बच्चा क्या समझता है।"},
  {"id":"cdp-pedagogy-subjects-1619","question":"A Class 5 child with dyscalculia understands problems well but makes many calculation errors. In a word-problem test, which accommodation best lets her show her reasoning?","options":["Removing word problems from her test, since they need calculation that she finds hard","Giving her the same test with no support, so that her result is fair compared with others","Giving her only easier sums with small numbers, so that she can get more answers right","Allowing a number line or calculator, with extra time, while she shows her reasoning"],"answer":3,"explanation":"Accommodations should remove the barrier, not the learning goal. Support for computation lets her show her problem-solving and reasoning, which is what the test is meant to measure.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"कक्षा 5 की डिस्कैल्कुलिया (dyscalculia) से ग्रस्त एक बच्ची प्रश्नों को अच्छी तरह समझती है पर गणना में बहुत त्रुटियाँ करती है। शाब्दिक प्रश्नों की परीक्षा में कौन-सी सुविधा उसे अपना तर्क दिखाने में सबसे अच्छी तरह मदद करती है?","optionsHi":["उसकी परीक्षा से शाब्दिक प्रश्न हटाना, क्योंकि उनमें गणना चाहिए जो उसे कठिन लगती है","उसे वही परीक्षा बिना किसी सहायता के देना, ताकि उसका परिणाम दूसरों से तुलना में निष्पक्ष रहे","उसे केवल छोटी संख्याओं वाले आसान प्रश्न देना, ताकि वह अधिक उत्तर सही कर सके","संख्या-रेखा या कैलकुलेटर और अतिरिक्त समय की अनुमति देना, जबकि वह अपना तर्क दिखाती है"],"explanationHi":"सुविधाओं को अवरोध हटाना चाहिए, अधिगम का लक्ष्य नहीं। गणना में सहायता उसे अपनी समस्या-समाधान क्षमता और तर्क दिखाने देती है, जिसे मापना ही परीक्षा का उद्देश्य है।"},
  {"id":"cdp-pedagogy-subjects-1620","question":"A Class 5 child finishes every maths task quickly and then becomes restless. What is the best response from the teacher?","options":["Give her richer problems that go deeper, such as investigating patterns or posing her own","Give her more sums of the same kind, so that she gets extra practice and stays busy","Make her help the teacher with chores such as distributing notebooks and cleaning the board","Ask her to sit quietly and read until the others finish, so the class is not disturbed"],"answer":0,"explanation":"Enrichment through depth and challenge keeps able learners engaged and growing. More of the same work only punishes speed and does not develop her thinking.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक बच्ची गणित का हर कार्य जल्दी पूरा कर लेती है और फिर बेचैन हो जाती है। शिक्षिका की सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["उसे अधिक समृद्ध, गहरे प्रश्न देना, जैसे पैटर्न की जाँच करना या अपने प्रश्न स्वयं बनाना","उसे उसी प्रकार के और प्रश्न देना, ताकि उसे अतिरिक्त अभ्यास मिले और वह व्यस्त रहे","उससे शिक्षिका की मदद करवाना, जैसे कॉपियाँ बाँटना और श्यामपट्ट साफ़ करना","उससे चुपचाप बैठकर पढ़ने को कहना जब तक बाकी पूरा न कर लें, ताकि कक्षा में व्यवधान न हो"],"explanationHi":"गहराई और चुनौती के माध्यम से समृद्धि सक्षम अधिगमकर्ताओं को जुड़ा हुआ और विकसित होता रखती है। उसी तरह का और काम केवल गति को दंडित करता है और उसकी सोच को विकसित नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-1621","question":"Assertion (A): Errors in children's mathematical work should be treated as windows into their thinking. Reason (R): Many errors are systematic, coming from a consistent but incorrect rule the child applies.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because many errors follow a rule the child believes in, studying them shows what the child thinks and what to teach. R explains why A is good practice.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): बच्चों के गणितीय कार्य की त्रुटियों को उनकी सोच की खिड़कियों के रूप में देखा जाना चाहिए। कारण (R): बहुत-सी त्रुटियाँ व्यवस्थित होती हैं, जो बच्चे द्वारा लगाए गए किसी सुसंगत पर गलत नियम से आती हैं।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"क्योंकि बहुत-सी त्रुटियाँ किसी ऐसे नियम का पालन करती हैं जिस पर बच्चा विश्वास करता है, उनका अध्ययन दिखाता है कि बच्चा क्या सोचता है और क्या सिखाना है। R बताता है कि A अच्छा अभ्यास क्यों है।"},
  {"id":"cdp-pedagogy-subjects-1622","question":"Assertion (A): Mathematical games at the primary stage are meant only for fun and do not support learning. Reason (R): Games can give purposeful practice and help children think about strategy.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Well-chosen games give repeated practice in a motivating way and build reasoning about strategy, so R is true and it shows why A is false. NCF 2005 recommends games at the primary stage.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"अभिकथन (A): प्राथमिक स्तर पर गणितीय खेल केवल मनोरंजन के लिए होते हैं और अधिगम में सहायक नहीं होते। कारण (R): खेल उद्देश्यपूर्ण अभ्यास दे सकते हैं और बच्चों को रणनीति के बारे में सोचने में मदद कर सकते हैं।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"भली-भाँति चुने गए खेल प्रेरक ढंग से बार-बार अभ्यास देते हैं और रणनीति के बारे में तर्क-शक्ति बनाते हैं, इसलिए R सही है और वह दिखाता है कि A गलत क्यों है। NCF 2005 प्राथमिक स्तर पर खेलों की अनुशंसा करती है।"},
  {"id":"cdp-pedagogy-subjects-1623","question":"Which of these statements about maths anxiety are correct? I. It can affect children who are otherwise capable in maths. II. Publicly comparing marks can increase it. III. It is best tackled by giving more timed tests. IV. Collaborative, low-stakes tasks can reduce it.","options":["I and III only","I, II and IV","II, III and IV","I, II, III and IV"],"answer":1,"explanation":"Maths anxiety is not the same as low ability, and public comparison and time pressure make it worse. Collaborative, low-stakes work helps; more timed tests usually increase it, so III is false.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"गणित-चिंता (maths anxiety) के बारे में इनमें से कौन-से कथन सही हैं? I. यह उन बच्चों को भी प्रभावित कर सकती है जो गणित में अन्यथा सक्षम हैं। II. अंकों की सार्वजनिक तुलना इसे बढ़ा सकती है। III. इससे निपटने का सबसे अच्छा तरीका अधिक समय-सीमित परीक्षाएँ देना है। IV. सहयोगात्मक, कम-जोखिम वाले कार्य इसे घटा सकते हैं।","optionsHi":["केवल I और III","I, II और IV","II, III और IV","I, II, III और IV"],"explanationHi":"गणित-चिंता का अर्थ कम योग्यता नहीं है, और सार्वजनिक तुलना तथा समय का दबाव इसे और बिगाड़ते हैं। सहयोगात्मक, कम-जोखिम वाला कार्य मदद करता है; अधिक समय-सीमित परीक्षाएँ प्रायः इसे बढ़ाती हैं, इसलिए III गलत है।"},
  {"id":"cdp-pedagogy-subjects-1624","question":"A Class 3 child writes 34 × 5 = 1520. Her working shows 4 × 5 = 20 and 3 × 5 = 15 written side by side. What is the error?","options":["She does not know the 5 times table well, so both of her partial products come out wrong","She multiplied the tens digit by 10 first and then by 5, adding an extra zero","She writes partial products 20 and 15 side by side, ignoring place value and regrouping","She added the digits instead of multiplying them, getting a much bigger number"],"answer":2,"explanation":"34 × 5 = 150 + 20 = 170. Writing ‘15’ and ‘20’ side by side ignores place value and regrouping; an area model with 30 × 5 and 4 × 5 makes the two parts and their sum visible.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की एक बच्ची लिखती है 34 × 5 = 1520। उसके कार्य में 4 × 5 = 20 और 3 × 5 = 15 साथ-साथ लिखे दिखते हैं। त्रुटि क्या है?","optionsHi":["वह 5 का पहाड़ा अच्छी तरह नहीं जानती, इसलिए उसके दोनों आंशिक गुणनफल गलत आते हैं","उसने दहाई के अंक को पहले 10 से और फिर 5 से गुणा किया, जिससे एक अतिरिक्त शून्य आ गया","वह आंशिक गुणनफल 20 और 15 को साथ-साथ लिखती है, स्थानमान और पुनःसमूहन की अनदेखी करते हुए","उसने अंकों को गुणा करने के बजाय जोड़ दिया, जिससे बहुत बड़ी संख्या मिली"],"explanationHi":"34 × 5 = 150 + 20 = 170। ‘15’ और ‘20’ को साथ-साथ लिखना स्थानमान और पुनःसमूहन की अनदेखी करता है; 30 × 5 और 4 × 5 वाला क्षेत्रफल मॉडल दोनों भागों और उनके योग को दृश्य बना देता है।"},
  {"id":"cdp-pedagogy-subjects-1625","question":"Assertion (A): Role play can sometimes reinforce stereotypes instead of challenging them.\nReason (R): When portraying characters, students may draw on stereotyped ideas unless the teacher prepares them and debriefs afterwards.","options":["Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"Students tend to act out the images they already carry, such as a 'villager' or a 'tribal', which can harden stereotypes. That is why preparation and debriefing matter; R explains A.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"अभिकथन (A): भूमिका-निर्वाह (role play) कभी-कभी रूढ़ छवियों को चुनौती देने के बजाय उन्हें पुष्ट कर सकता है। कारण (R): पात्रों का अभिनय करते समय विद्यार्थी रूढ़ विचारों का सहारा ले सकते हैं, जब तक शिक्षक उन्हें तैयार न करे और बाद में चर्चा न करे।","optionsHi":["A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है","A और R दोनों सही हैं और R, A की सही व्याख्या है"],"explanationHi":"विद्यार्थी वही छवियाँ अभिनीत करते हैं जो वे पहले से लिए रहते हैं, जैसे ‘ग्रामीण’ या ‘आदिवासी’, जो रूढ़ छवियों को कठोर बना सकती हैं। इसीलिए तैयारी और बाद की चर्चा महत्वपूर्ण हैं; R, A को समझाता है।"},
  {"id":"cdp-pedagogy-subjects-1626","question":"Which of the following are features of the approach of NCERT's Social and Political Life textbooks for Classes VI to VIII?\n1. They use narratives and case studies of individual people.\n2. They avoid discussing inequality, to keep children comfortable.\n3. They ask students to relate concepts to their own experience.","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"These books build concepts through stories of people and repeatedly ask students to connect them with their lives. They deal openly with inequality, discrimination and marginalisation rather than avoiding it.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VI से VIII के लिए NCERT की ‘सामाजिक एवं राजनीतिक जीवन’ पाठ्यपुस्तकों की पद्धति की विशेषताएँ कौन-सी हैं? 1. वे व्यक्तिगत लोगों के आख्यानों और केस अध्ययनों का उपयोग करती हैं। 2. वे बच्चों को सहज रखने के लिए असमानता की चर्चा से बचती हैं। 3. वे विद्यार्थियों से संकल्पनाओं को अपने अनुभव से जोड़ने को कहती हैं।","optionsHi":["केवल 1 और 3","केवल 1 और 2","केवल 2 और 3","1, 2 और 3"],"explanationHi":"ये पुस्तकें लोगों की कहानियों के माध्यम से संकल्पनाएँ बनाती हैं और बार-बार विद्यार्थियों से उन्हें अपने जीवन से जोड़ने को कहती हैं। वे असमानता, भेदभाव और हाशियाकरण से बचने के बजाय उनसे खुलकर निपटती हैं।"},
  {"id":"cdp-pedagogy-subjects-1627","question":"Class VII students believe that the Mughal Empire began only after the Vijayanagara kingdom had ended. Which activity best corrects this?","options":["Ask students to memorise the founding year of each kingdom and arrange them in order","Tell them the two kingdoms were in different regions, so their dates do not matter at all","Draw both kingdoms as parallel bars on one timeline to show the decades they coexisted","Rearrange the chapters in the textbook so that the Mughal chapter comes after Vijayanagara"],"answer":2,"explanation":"The Mughals were established in the north in 1526, while Vijayanagara remained powerful in the south until its defeat in 1565. Parallel bars make this overlap visible, correcting the idea that history is a single line of succession.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा VII के विद्यार्थी मानते हैं कि मुग़ल साम्राज्य विजयनगर राज्य के समाप्त होने के बाद ही शुरू हुआ। कौन-सी गतिविधि इसे सबसे अच्छी तरह सुधारती है?","optionsHi":["विद्यार्थियों से हर राज्य की स्थापना का वर्ष रटवाना और उन्हें क्रम में लगवाना","उन्हें बताना कि दोनों राज्य अलग-अलग क्षेत्रों में थे, इसलिए उनकी तिथियाँ बिल्कुल मायने नहीं रखतीं","एक ही समय-रेखा पर दोनों राज्यों को समांतर पट्टियों के रूप में बनाना ताकि दिखे कि वे कितने दशकों तक साथ-साथ रहे","पाठ्यपुस्तक के अध्यायों का क्रम बदलना ताकि मुग़ल अध्याय विजयनगर के बाद आए"],"explanationHi":"मुग़ल 1526 में उत्तर में स्थापित हुए, जबकि विजयनगर 1565 में अपनी पराजय तक दक्षिण में शक्तिशाली रहा। समांतर पट्टियाँ इस अतिव्यापन को दृश्य बनाती हैं, और इस धारणा को सुधारती हैं कि इतिहास उत्तराधिकार की एक ही रेखा है।"},
  {"id":"cdp-pedagogy-subjects-1628","question":"A Class VI student's map of her route from home to school is neatly drawn but has no north arrow and no key for the symbols she used. What should the teacher's feedback focus on?","options":["Praising the neat drawing, since neatness is the main quality of a good map","Asking her to colour the map more brightly so that each place stands out","Asking her to redraw it on a larger sheet so that more detail can be shown","Adding a direction arrow and a key, so that others can read and use the map"],"answer":3,"explanation":"Direction and a legend are what turn a drawing into a usable map. Neatness or colour matter far less than the elements that make a map readable by someone else.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"कक्षा VI की एक विद्यार्थी का घर से विद्यालय तक के मार्ग का मानचित्र साफ़-सुथरा बना है, पर उसमें उत्तर-तीर नहीं है और उसके प्रयुक्त चिह्नों की कोई कुंजी (key) भी नहीं है। शिक्षिका की प्रतिपुष्टि किस पर केंद्रित होनी चाहिए?","optionsHi":["साफ़-सुथरे चित्र की प्रशंसा पर, क्योंकि अच्छे मानचित्र का मुख्य गुण साफ़-सफ़ाई है","उससे मानचित्र में अधिक चटक रंग भरने को कहने पर, ताकि हर स्थान उभरकर दिखे","उससे उसे बड़े कागज़ पर दोबारा बनाने को कहने पर, ताकि अधिक विवरण दिखाए जा सकें","दिशा-तीर और कुंजी जोड़ने पर, ताकि दूसरे उसे पढ़ और उपयोग कर सकें"],"explanationHi":"दिशा और संकेत-सूची (legend) ही चित्र को उपयोगी मानचित्र बनाती हैं। साफ़-सफ़ाई या रंग उन तत्वों से बहुत कम मायने रखते हैं जो मानचित्र को किसी और के पढ़ने योग्य बनाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1629","question":"Class VII students read an English translation of a Persian chronicle. One asks, 'Is this translation still a primary source?' Which answer is most accurate?","options":["No; once a text is translated it becomes a secondary source, and so it is of little real use to a historian","The original is primary; the translation lets us read it, but the translator's choices shape its meaning","Yes; a good translation is exactly the same as the original in every way, so nothing changes","No; a primary source must be read in its original language, or it cannot be used at all"],"answer":1,"explanation":"Historians use translations all the time, but translation involves interpretation. Students should treat the content as coming from the original while noting that the translator's choices mediate it.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा VII के विद्यार्थी एक फ़ारसी इतिवृत्त (chronicle) का अंग्रेज़ी अनुवाद पढ़ते हैं। एक पूछता है, ‘क्या यह अनुवाद अब भी प्राथमिक स्रोत है?’ कौन-सा उत्तर सबसे सटीक है?","optionsHi":["नहीं; अनुवादित होते ही पाठ द्वितीयक स्रोत बन जाता है, और इसलिए इतिहासकार के लिए उसका वास्तविक उपयोग कम है","मूल प्रति प्राथमिक है; अनुवाद हमें उसे पढ़ने देता है, पर अनुवादक के चुनाव उसके अर्थ को आकार देते हैं","हाँ; अच्छा अनुवाद हर तरह से मूल के बिल्कुल बराबर होता है, इसलिए कुछ नहीं बदलता","नहीं; प्राथमिक स्रोत को उसकी मूल भाषा में ही पढ़ा जाना चाहिए, वरना उसका उपयोग हो ही नहीं सकता"],"explanationHi":"इतिहासकार अनुवादों का उपयोग हमेशा करते हैं, पर अनुवाद में व्याख्या शामिल होती है। विद्यार्थियों को विषय-वस्तु को मूल से आया मानना चाहिए, साथ ही यह ध्यान रखना चाहिए कि अनुवादक के चुनाव उसमें मध्यस्थता करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1630","question":"In a village in Andhra Pradesh, families are divided over a proposal to open a liquor shop, and students bring the issue to their Class VIII social science period. What is the most appropriate approach?","options":["Study the decision process, the gram sabha's role and each side's case, with ground rules and a neutral teacher","Refuse to discuss it in class, since the issue divides parents and could lead to quarrels among students","Tell students which side is morally right, since teachers should guide children on such social questions","Ask students to hold a vote and announce the class result to the gram sabha as the voice of the village's youth"],"answer":0,"explanation":"A live local controversy is an ideal way to learn about local democracy when handled fairly: process, institutions and arguments, with the teacher facilitating rather than campaigning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"आंध्र प्रदेश के एक गाँव में शराब की दुकान खोलने के प्रस्ताव पर परिवार बँटे हुए हैं, और विद्यार्थी यह मुद्दा कक्षा VIII के सामाजिक विज्ञान के पीरियड में ले आते हैं। सबसे उपयुक्त तरीका क्या है?","optionsHi":["निर्णय की प्रक्रिया, ग्राम सभा की भूमिका और हर पक्ष के तर्क का अध्ययन करना, बुनियादी नियमों और तटस्थ शिक्षक के साथ","कक्षा में इस पर चर्चा से इनकार करना, क्योंकि मुद्दा अभिभावकों को बाँटता है और विद्यार्थियों के बीच झगड़े हो सकते हैं","विद्यार्थियों को बताना कि नैतिक रूप से कौन-सा पक्ष सही है, क्योंकि शिक्षकों को ऐसे सामाजिक प्रश्नों पर बच्चों का मार्गदर्शन करना चाहिए","विद्यार्थियों से मतदान करवाना और कक्षा का परिणाम गाँव के युवाओं की आवाज़ के रूप में ग्राम सभा को सुनाना"],"explanationHi":"जीवंत स्थानीय विवाद, निष्पक्षता से सँभाला जाए तो, स्थानीय लोकतंत्र सीखने का आदर्श माध्यम है: प्रक्रिया, संस्थाएँ और तर्क, जिसमें शिक्षक अभियान चलाने के बजाय सुगमन करता है।"},
  {"id":"cdp-pedagogy-subjects-1631","question":"A Class VII teacher points out that the only hand pump in a village was installed in the hamlet of the landowning families, and asks, 'Who decided this, and who is left out?' What is she mainly helping students understand?","options":["How hand pumps work and why they are needed where piped water is not available","That access to public facilities can reflect power and inequality in a community","That government facilities are always placed fairly, according to each hamlet's need","That villages do not really need hand pumps if they have wells and ponds nearby"],"answer":1,"explanation":"The question links a physical facility to social power: who decides where public resources go and who loses out. That is a core concern of social science teaching on equality.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा VII की एक शिक्षिका बताती है कि एक गाँव का एकमात्र हैंडपंप भूस्वामी परिवारों की बस्ती में लगाया गया था, और पूछती है, ‘यह किसने तय किया, और कौन छूट गया?’ वह विद्यार्थियों को मुख्यतः क्या समझने में मदद कर रही है?","optionsHi":["हैंडपंप कैसे काम करते हैं और जहाँ पाइप से पानी उपलब्ध नहीं है वहाँ उनकी आवश्यकता क्यों है","कि सार्वजनिक सुविधाओं तक पहुँच किसी समुदाय में शक्ति और असमानता को प्रतिबिंबित कर सकती है","कि सरकारी सुविधाएँ हमेशा हर बस्ती की आवश्यकता के अनुसार निष्पक्ष रूप से लगाई जाती हैं","कि गाँवों को हैंडपंप की वास्तव में आवश्यकता नहीं है यदि पास में कुएँ और तालाब हों"],"explanationHi":"प्रश्न एक भौतिक सुविधा को सामाजिक शक्ति से जोड़ता है: सार्वजनिक संसाधन कहाँ जाएँगे यह कौन तय करता है और किसे हानि होती है। यह समानता पर सामाजिक विज्ञान शिक्षण की केंद्रीय चिंता है।"},
  {"id":"cdp-pedagogy-subjects-1632","question":"A Class VIII teacher notices a memorial in the town square with the names of people who died in a local event of the freedom struggle. Which activity makes best use of it?","options":["Ask students to copy all the names into their notebooks so that the martyrs are never forgotten","Take a group photograph at the memorial for the school magazine, with a short caption about the freedom struggle","Have students find out who these people were and how the event is remembered, from family memories and records","Ignore it, since the event is not in the textbook and will not be asked in the board examination"],"answer":2,"explanation":"Local memorials are entry points into local history and into how communities remember the past. Investigating them builds research skills and connects national history to the students' own place.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"कक्षा VIII का एक शिक्षक कस्बे के चौक में एक स्मारक देखता है जिस पर स्वतंत्रता संग्राम की एक स्थानीय घटना में मरने वालों के नाम हैं। कौन-सी गतिविधि इसका सबसे अच्छा उपयोग करती है?","optionsHi":["विद्यार्थियों से सभी नाम अपनी कॉपियों में उतारने को कहना, ताकि शहीदों को कभी भुलाया न जाए","स्कूल की पत्रिका के लिए स्मारक पर समूह-चित्र लेना, स्वतंत्रता संग्राम पर एक छोटे शीर्षक के साथ","विद्यार्थियों से पारिवारिक स्मृतियों और अभिलेखों से पता लगवाना कि ये लोग कौन थे और उस घटना को कैसे याद किया जाता है","इसकी अनदेखी करना, क्योंकि घटना पाठ्यपुस्तक में नहीं है और बोर्ड परीक्षा में नहीं पूछी जाएगी"],"explanationHi":"स्थानीय स्मारक स्थानीय इतिहास और समुदाय अतीत को कैसे याद करते हैं, इसमें प्रवेश-द्वार हैं। उनकी जाँच शोध-कौशल बनाती है और राष्ट्रीय इतिहास को विद्यार्थियों के अपने स्थान से जोड़ती है।"},
  {"id":"cdp-pedagogy-subjects-1633","question":"Class IX students in a Kerala school are asked to frame questions for a local history project. Which question is the most suitable for inquiry?","options":["When exactly was our town founded, and who was the ruler of the area at that time in history?","Who is the present MLA of our constituency, and which party has won the seat most often since 1957?","How many schools, hospitals and post offices are there in our town today, according to official records?","Why did many families here migrate to the Gulf in the 1970s and 1980s, and how did it change our town?"],"answer":3,"explanation":"A 'why' and 'how' question about change invites investigation of causes and effects using interviews, records and data. The others have single factual answers.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"केरल के एक विद्यालय में कक्षा IX के विद्यार्थियों से स्थानीय इतिहास परियोजना के लिए प्रश्न बनाने को कहा जाता है। जाँच के लिए कौन-सा प्रश्न सबसे उपयुक्त है?","optionsHi":["हमारा कस्बा ठीक कब बसा था, और उस समय इतिहास में इस क्षेत्र का शासक कौन था?","हमारे निर्वाचन क्षेत्र का वर्तमान विधायक (MLA) कौन है, और 1957 से अब तक किस दल ने यह सीट सबसे अधिक बार जीती है?","आधिकारिक अभिलेखों के अनुसार आज हमारे कस्बे में कितने विद्यालय, अस्पताल और डाकघर हैं?","1970 और 1980 के दशकों में यहाँ के बहुत-से परिवार खाड़ी देशों में क्यों गए, और उससे हमारे कस्बे में क्या बदला?"],"explanationHi":"बदलाव के बारे में ‘क्यों’ और ‘कैसे’ वाला प्रश्न साक्षात्कारों, अभिलेखों और आँकड़ों से कारणों और प्रभावों की जाँच को आमंत्रित करता है। अन्य प्रश्नों के एकल तथ्यात्मक उत्तर हैं।"},
  {"id":"cdp-pedagogy-subjects-1634","question":"During a Class VII discussion of a sad story about a family that lost its land, a boy's eyes fill with tears and others laugh, saying, 'Boys don't cry.' How should the teacher use this moment?","options":["Tell the boy quietly to control himself, so that he is not teased further by the class later","Ignore the laughter so that the lesson can continue and the boy is not embarrassed further","Scold the class sharply for laughing and move on with the story without any discussion","Stop the mockery gently and help the class see 'boys don't cry' as a norm that limits all"],"answer":3,"explanation":"The incident is a live example of gender norms, which social science teaches are socially constructed. Addressing it protects the child and turns the moment into learning, instead of suppressing it.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"एक परिवार के अपनी ज़मीन खो देने की दुखद कहानी पर कक्षा VII की चर्चा के दौरान एक लड़के की आँखें भर आती हैं और बाकी हँसकर कहते हैं, ‘लड़के नहीं रोते।’ शिक्षिका को इस क्षण का उपयोग कैसे करना चाहिए?","optionsHi":["लड़के से चुपचाप कहना कि वह खुद को सँभाले, ताकि बाद में कक्षा उसे और न चिढ़ाए","हँसी की अनदेखी करना ताकि पाठ चलता रहे और लड़का और शर्मिंदा न हो","कक्षा को हँसने पर कड़ी डाँट देना और बिना किसी चर्चा के कहानी आगे बढ़ाना","उपहास को शांति से रोकना और कक्षा को यह देखने में मदद करना कि ‘लड़के नहीं रोते’ एक ऐसा मानदंड है जो सबको सीमित करता है"],"explanationHi":"यह घटना लैंगिक मानदंडों का जीवंत उदाहरण है, जिनके बारे में सामाजिक विज्ञान सिखाता है कि वे सामाजिक रूप से निर्मित होते हैं। इसे संबोधित करने से बच्चे की रक्षा होती है और इस क्षण को दबाने के बजाय अधिगम में बदला जाता है।"},
  {"id":"cdp-pedagogy-subjects-1635","question":"While teaching about floods in Class VIII, the teacher asks, 'Who suffers most in a flood, and why?' Which understanding is this question meant to build?","options":["That floods affect everyone living in the area equally, since rising water does not choose whom it harms","That a disaster's impact depends on people's situation, such as poverty, housing, gender and disability","That floods are caused only by heavy rain, so their effects cannot be prevented by people","That only governments can reduce the effects of floods, through dams and relief camps"],"answer":1,"explanation":"Disasters strike unevenly: the poor in fragile housing, women, the elderly and persons with disabilities often face the worst effects. The question shifts students from seeing disasters as purely natural to seeing their social dimension.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा VIII में बाढ़ पढ़ाते समय शिक्षिका पूछती है, ‘बाढ़ में सबसे अधिक कष्ट किसे होता है, और क्यों?’ यह प्रश्न कौन-सी समझ बनाने के लिए है?","optionsHi":["कि बाढ़ उस क्षेत्र में रहने वाले सभी को समान रूप से प्रभावित करती है, क्योंकि चढ़ता पानी यह नहीं चुनता कि किसे हानि पहुँचाए","कि आपदा का प्रभाव लोगों की स्थिति पर निर्भर करता है, जैसे गरीबी, आवास, लिंग और दिव्यांगता","कि बाढ़ केवल भारी वर्षा से होती है, इसलिए लोग उसके प्रभावों को रोक नहीं सकते","कि केवल सरकारें ही बाँधों और राहत शिविरों के माध्यम से बाढ़ के प्रभावों को कम कर सकती हैं"],"explanationHi":"आपदाएँ असमान रूप से आती हैं: कमज़ोर आवासों में रहने वाले गरीब, महिलाएँ, बुज़ुर्ग और दिव्यांगजन प्रायः सबसे बुरे प्रभाव झेलते हैं। प्रश्न विद्यार्थियों को आपदाओं को पूर्णतः प्राकृतिक देखने से उनके सामाजिक आयाम को देखने की ओर ले जाता है।"},
  {"id":"cdp-pedagogy-subjects-1636","question":"A Class X teacher presents two countries, each with five citizens. In Country A, each earns ₹10,000 a month. In Country B, four earn ₹500 each and one earns ₹48,000. What should students conclude?","options":["Both have the same average income of ₹10,000, but the average hides the extreme inequality in B","Country B is richer, because one of its citizens earns ₹48,000, far more than anyone in Country A","Country A is poorer, because no one there earns a high income and its people have no rich class","Both are equally developed, since average income is the best measure of how well people live"],"answer":0,"explanation":"Country B's average is (4 × 500 + 48,000) ÷ 5 = ₹10,000, the same as A. The example shows why averages must be read alongside distribution when judging development.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"कक्षा X की एक शिक्षिका दो देश प्रस्तुत करती है, जिनमें प्रत्येक के पाँच नागरिक हैं। देश A में हर एक की मासिक आय ₹10,000 है। देश B में चार की आय ₹500 प्रत्येक और एक की ₹48,000 है। विद्यार्थियों को क्या निष्कर्ष निकालना चाहिए?","optionsHi":["दोनों की औसत आय समान ₹10,000 है, पर औसत B की चरम असमानता को छिपा देता है","देश B अधिक धनी है, क्योंकि उसके एक नागरिक की आय ₹48,000 है, जो देश A में किसी की भी आय से कहीं अधिक है","देश A अधिक गरीब है, क्योंकि वहाँ किसी की आय ऊँची नहीं है और वहाँ के लोगों का कोई धनी वर्ग नहीं है","दोनों समान रूप से विकसित हैं, क्योंकि औसत आय ही यह मापने का सबसे अच्छा तरीका है कि लोग कितना अच्छा जीवन जीते हैं"],"explanationHi":"देश B का औसत (4 × 500 + 48,000) ÷ 5 = ₹10,000 है, A के समान। यह उदाहरण दिखाता है कि विकास का मूल्यांकन करते समय औसत को वितरण के साथ पढ़ना क्यों आवश्यक है।"},
  {"id":"cdp-pedagogy-subjects-1637","question":"A Class VI teacher asks students to mark on a map where their parents and grandparents were born, if they wish to share it. What is the main learning, and why is sharing optional?","options":["It mainly tests map-reading skills; sharing is optional so that the activity does not take too long","It shows that mostly rural people migrate; sharing is optional because migration can be embarrassing","Migration runs through many family histories and wider patterns; sharing is optional for privacy","It ranks families by how far they have moved; sharing is optional so that no family feels left behind"],"answer":2,"explanation":"Family migration maps make migration personal and reveal patterns across the class. Some families may have painful or private histories, such as displacement, so participation must be voluntary.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VI की एक शिक्षिका विद्यार्थियों से, यदि वे साझा करना चाहें, मानचित्र पर चिह्नित करने को कहती है कि उनके माता-पिता और दादा-दादी कहाँ जन्मे थे। मुख्य अधिगम क्या है, और साझा करना वैकल्पिक क्यों है?","optionsHi":["यह मुख्यतः मानचित्र-पठन कौशल की परीक्षा लेता है; साझा करना वैकल्पिक है ताकि गतिविधि में बहुत समय न लगे","यह दिखाता है कि मुख्यतः ग्रामीण लोग प्रवास करते हैं; साझा करना वैकल्पिक है क्योंकि प्रवास शर्मिंदगी भरा हो सकता है","प्रवास अनेक पारिवारिक इतिहासों और व्यापक पैटर्नों में चलता है; साझा करना निजता के लिए वैकल्पिक है","यह परिवारों को इस आधार पर क्रम देता है कि वे कितनी दूर गए हैं; साझा करना वैकल्पिक है ताकि कोई परिवार पीछे छूटा न लगे"],"explanationHi":"पारिवारिक प्रवास मानचित्र प्रवास को व्यक्तिगत बनाते हैं और पूरी कक्षा में पैटर्न उजागर करते हैं। कुछ परिवारों के दर्दनाक या निजी इतिहास हो सकते हैं, जैसे विस्थापन, इसलिए भागीदारी स्वैच्छिक होनी चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1638","question":"Which of the following classroom activities is a simulation?","options":["Students take the roles of judge, lawyers and witnesses in a mock trial","Students read the chapter on the judiciary silently and underline key terms","Students answer a quiz on the names and levels of courts in India","Students write an essay on why courts are important in a democracy"],"answer":0,"explanation":"A simulation recreates a real process in which students take roles and act it out. Reading, quizzes and essays do not involve modelling the process.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"निम्नलिखित कक्षा-गतिविधियों में से कौन-सी अनुकरण (simulation) है?","optionsHi":["विद्यार्थी नकली मुकदमे (mock trial) में न्यायाधीश, वकील और गवाह की भूमिकाएँ निभाते हैं","विद्यार्थी न्यायपालिका का अध्याय मौन पढ़ते हैं और मुख्य शब्दों को रेखांकित करते हैं","विद्यार्थी भारत में न्यायालयों के नाम और स्तरों पर प्रश्नोत्तरी हल करते हैं","विद्यार्थी निबंध लिखते हैं कि लोकतंत्र में न्यायालय क्यों महत्वपूर्ण हैं"],"explanationHi":"अनुकरण किसी वास्तविक प्रक्रिया को फिर से रचता है जिसमें विद्यार्थी भूमिकाएँ लेकर उसे अभिनीत करते हैं। पढ़ना, प्रश्नोत्तरी और निबंध में प्रक्रिया का मॉडल बनाना शामिल नहीं होता।"},
  {"id":"cdp-pedagogy-subjects-1639","question":"A Class VIII teacher asks, 'Don't you all agree that the British only harmed India?' What is the main problem with this question?","options":["It is too difficult for Class VIII students, who cannot yet judge colonial rule as a whole","It is about history, not political science, so it does not belong in a civics lesson","It has too many correct answers, so students will not be able to agree on a single one","It is a leading question that signals the answer wanted, so students do not weigh evidence"],"answer":3,"explanation":"Leading questions close inquiry by telling students what to think. An open question, such as 'In what ways did colonial rule affect different groups?', invites evidence-based reasoning.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा VIII की एक शिक्षिका पूछती है, ‘क्या आप सब सहमत नहीं हैं कि अंग्रेज़ों ने भारत को केवल हानि पहुँचाई?’ इस प्रश्न की मुख्य समस्या क्या है?","optionsHi":["यह कक्षा VIII के विद्यार्थियों के लिए बहुत कठिन है, जो अभी औपनिवेशिक शासन का समग्र रूप से निर्णय नहीं कर सकते","यह इतिहास के बारे में है, राजनीति विज्ञान के बारे में नहीं, इसलिए नागरिक शास्त्र के पाठ में नहीं आता","इसके बहुत से सही उत्तर हैं, इसलिए विद्यार्थी किसी एक उत्तर पर सहमत नहीं हो पाएँगे","यह एक प्रेरक प्रश्न है जो वांछित उत्तर का संकेत देता है, इसलिए विद्यार्थी साक्ष्य को तौलते नहीं"],"explanationHi":"प्रेरक प्रश्न विद्यार्थियों को क्या सोचना है यह बताकर जाँच को बंद कर देते हैं। ‘औपनिवेशिक शासन ने विभिन्न समूहों को किन तरीकों से प्रभावित किया?’ जैसा खुला प्रश्न साक्ष्य-आधारित तर्क को आमंत्रित करता है।"},
  {"id":"cdp-pedagogy-subjects-1640","question":"Before starting a unit on the Constitution, a teacher has Class VIII students fill the first two columns of a chart: what they already know and what they want to know. The third column, what they learnt, is filled at the end. What is the main purpose?","options":["To keep students busy and quiet while the teacher prepares the materials for the unit","To activate prior knowledge, give students ownership of questions and aid reflection","To check students' handwriting and spelling before they begin writing longer answers","To replace the unit test, since the chart already shows what each student has learnt"],"answer":1,"explanation":"A KWL chart connects new learning to what students know, turns their questions into goals for the unit and prompts reflection at the end.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"संविधान पर इकाई शुरू करने से पहले एक शिक्षिका कक्षा VIII के विद्यार्थियों से चार्ट के पहले दो स्तंभ भरवाती है: वे पहले से क्या जानते हैं और वे क्या जानना चाहते हैं। तीसरा स्तंभ, उन्होंने क्या सीखा, अंत में भरा जाता है। मुख्य उद्देश्य क्या है?","optionsHi":["विद्यार्थियों को व्यस्त और शांत रखना जबकि शिक्षिका इकाई की सामग्री तैयार करती है","पूर्व ज्ञान को सक्रिय करना, विद्यार्थियों को अपने प्रश्नों का स्वामित्व देना और चिंतन में सहायता करना","लंबे उत्तर लिखना शुरू करने से पहले विद्यार्थियों की लिखावट और वर्तनी की जाँच करना","इकाई परीक्षा की जगह लेना, क्योंकि चार्ट पहले ही दिखा देता है कि हर विद्यार्थी ने क्या सीखा"],"explanationHi":"KWL चार्ट नए अधिगम को उससे जोड़ता है जो विद्यार्थी जानते हैं, उनके प्रश्नों को इकाई के लक्ष्यों में बदलता है और अंत में चिंतन को प्रेरित करता है।"},
  {"id":"cdp-pedagogy-subjects-1641","question":"Assertion (A): Memorising the textbook's list of the causes of the Revolt of 1857 develops historical understanding.\nReason (R): Historical understanding requires analysing how causes are connected and weighing the evidence for them.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is false but R is true","A is true but R is false"],"answer":2,"explanation":"R correctly describes historical understanding, and that is exactly what a memorised list does not provide. A is false.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"अभिकथन (A): 1857 के विद्रोह के कारणों की पाठ्यपुस्तक की सूची को रटना ऐतिहासिक समझ विकसित करता है। कारण (R): ऐतिहासिक समझ के लिए यह विश्लेषण करना आवश्यक है कि कारण आपस में कैसे जुड़े हैं और उनके साक्ष्यों को तौलना।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A गलत है परंतु R सही है","A सही है परंतु R गलत है"],"explanationHi":"R ऐतिहासिक समझ का सही वर्णन करता है, और रटी हुई सूची ठीक वही नहीं देती। A गलत है।"},
  {"id":"cdp-pedagogy-subjects-1642","question":"Looking at a population density map, Class IX students say Kerala must have more people than Rajasthan because Kerala is shaded much darker. What should the teacher clarify?","options":["The students are right, since darker shading on any map always means a larger total population","Shading on such maps is mainly decorative and is used to make the states easier to tell apart","Shading shows density (people per sq km); Rajasthan is less dense but much larger, with more people","Population cannot really be shown accurately on maps, so students should use only the census tables"],"answer":2,"explanation":"Density is a ratio, not a total. Kerala is densely populated but small; Rajasthan has a lower density over a much larger area and a larger total population. Confusing density with total is a common map-reading error.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB","questionHi":"जनसंख्या घनत्व मानचित्र देखते हुए कक्षा IX के विद्यार्थी कहते हैं कि केरल में राजस्थान से अधिक लोग होंगे क्योंकि केरल अधिक गहरे रंग में छायांकित है। शिक्षिका को क्या स्पष्ट करना चाहिए?","optionsHi":["विद्यार्थी सही हैं, क्योंकि किसी भी मानचित्र पर गहरी छाया का अर्थ हमेशा अधिक कुल जनसंख्या होता है","ऐसे मानचित्रों पर छाया मुख्यतः सजावटी होती है और राज्यों को आसानी से अलग पहचानने के लिए उपयोग होती है","छाया घनत्व (प्रति वर्ग किमी व्यक्ति) दिखाती है; राजस्थान कम सघन पर बहुत बड़ा है, और वहाँ अधिक लोग हैं","मानचित्रों पर जनसंख्या को वास्तव में सही-सही नहीं दिखाया जा सकता, इसलिए विद्यार्थियों को केवल जनगणना सारणियाँ उपयोग करनी चाहिए"],"explanationHi":"घनत्व एक अनुपात है, कुल नहीं। केरल सघन आबादी वाला पर छोटा है; राजस्थान का घनत्व बहुत बड़े क्षेत्र पर कम है और उसकी कुल जनसंख्या अधिक है। घनत्व को कुल संख्या समझना मानचित्र-पठन की आम त्रुटि है।"},
  {"id":"cdp-pedagogy-subjects-1643","question":"A Class VII section runs a monthly wall magazine on which students publish short reports on local issues, such as a broken road or a new bus route, with interviews and photographs. What does this activity mainly develop?","options":["Inquiry, communication and civic engagement with the local community","Decorative and display skills that make the classroom walls look attractive","Memorisation of textbook answers through repeated writing on local topics","Competition between sections, since the best magazine wins a school prize"],"answer":0,"explanation":"Researching, interviewing and reporting on local issues builds inquiry and communication skills and an active interest in community affairs, all central aims of social science.","difficulty":"hard","source":"CTET Paper 2 · state TETs","questionHi":"कक्षा VII का एक अनुभाग मासिक दीवार-पत्रिका चलाता है जिसमें विद्यार्थी साक्षात्कारों और तस्वीरों के साथ स्थानीय मुद्दों, जैसे टूटी सड़क या नए बस मार्ग, पर छोटी रिपोर्टें प्रकाशित करते हैं। यह गतिविधि मुख्यतः क्या विकसित करती है?","optionsHi":["स्थानीय समुदाय के साथ जाँच, संप्रेषण और नागरिक सहभागिता","सजावट और प्रदर्शन कौशल जो कक्षा की दीवारों को आकर्षक बनाते हैं","स्थानीय विषयों पर बार-बार लिखने के माध्यम से पाठ्यपुस्तक के उत्तरों का स्मरण","अनुभागों के बीच प्रतिस्पर्धा, क्योंकि सबसे अच्छी पत्रिका को विद्यालय का पुरस्कार मिलता है"],"explanationHi":"स्थानीय मुद्दों पर शोध करना, साक्षात्कार लेना और रिपोर्ट करना जाँच तथा संप्रेषण कौशल और सामुदायिक मामलों में सक्रिय रुचि बनाता है, जो सामाजिक विज्ञान के सभी केंद्रीय उद्देश्य हैं।"},
  {"id":"cdp-pedagogy-subjects-1644","question":"A Class IX student writes accurate facts in history answers but never explains how one event led to another. Which remedial strategy is most effective?","options":["Ask her to write much longer answers, since more words will give the examiner more points to mark","Give her more facts to memorise, since a richer store of facts will naturally lead to better explanations","Tell her that explanation is not really needed in history, as long as her facts are accurate","Model explanations with words like 'because' and 'as a result', and practise linking causes and effects"],"answer":3,"explanation":"The student lacks the skill of causal explanation, not knowledge. Modelling and scaffolded practice with linking language build that skill directly; length or more facts do not.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS","questionHi":"कक्षा IX की एक विद्यार्थी इतिहास के उत्तरों में सटीक तथ्य लिखती है पर कभी नहीं समझाती कि एक घटना दूसरी तक कैसे पहुँची। कौन-सी उपचारात्मक रणनीति सबसे प्रभावी है?","optionsHi":["उससे बहुत लंबे उत्तर लिखने को कहना, क्योंकि अधिक शब्द परीक्षक को अंक देने के लिए अधिक बिंदु देंगे","उसे याद करने के लिए और अधिक तथ्य देना, क्योंकि तथ्यों का समृद्ध भंडार स्वाभाविक रूप से बेहतर स्पष्टीकरण की ओर ले जाएगा","उससे कहना कि इतिहास में स्पष्टीकरण की वास्तव में आवश्यकता नहीं है, जब तक उसके तथ्य सटीक हैं","‘क्योंकि’ और ‘परिणामस्वरूप’ जैसे शब्दों के साथ स्पष्टीकरण का आदर्श प्रस्तुत करना, और कारणों तथा प्रभावों को जोड़ने का अभ्यास कराना"],"explanationHi":"विद्यार्थी में ज्ञान की नहीं, कारणात्मक स्पष्टीकरण के कौशल की कमी है। आदर्श प्रस्तुत करना और जोड़ने वाली भाषा के साथ पाड़-सहित (scaffolded) अभ्यास सीधे वह कौशल बनाते हैं; लंबाई या अधिक तथ्य नहीं।"},
  {"id":"cdp-pedagogy-subjects-1645","question":"A Class VIII student with dyslexia understands social science discussions well but scores poorly in written tests. Which adjustment is most appropriate?","options":["Lower the expectations for the student permanently, so that the student does not feel pressured","Give audio-visual materials and extra time, and allow some assessment orally or through diagrams","Ask the student to copy the chapter daily, since copying will improve reading and writing skills","Exempt the student from social science, so that more time can be spent on reading practice"],"answer":1,"explanation":"Inclusive practice removes barriers to showing learning while keeping the same goals. Alternative modes of access and assessment let the student's understanding show; lower expectations or exemption are discriminatory.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा VIII का डिस्लेक्सिया से ग्रस्त एक विद्यार्थी सामाजिक विज्ञान की चर्चाओं को अच्छी तरह समझता है पर लिखित परीक्षाओं में कम अंक पाता है। कौन-सा समायोजन सबसे उपयुक्त है?","optionsHi":["विद्यार्थी की अपेक्षाएँ स्थायी रूप से घटा देना, ताकि उस पर दबाव न पड़े","श्रव्य-दृश्य सामग्री और अतिरिक्त समय देना, और कुछ आकलन मौखिक रूप से या आरेखों के माध्यम से होने देना","विद्यार्थी से प्रतिदिन अध्याय उतारने को कहना, क्योंकि उतारने से पठन और लेखन कौशल सुधरेंगे","विद्यार्थी को सामाजिक विज्ञान से छूट देना, ताकि पठन-अभ्यास में अधिक समय दिया जा सके"],"explanationHi":"समावेशी अभ्यास समान लक्ष्य रखते हुए अधिगम दिखाने की बाधाएँ हटाता है। पहुँच और आकलन के वैकल्पिक तरीके विद्यार्थी की समझ को सामने आने देते हैं; अपेक्षाएँ घटाना या छूट देना भेदभावपूर्ण हैं।"},
  {"id":"cdp-pedagogy-subjects-1646","question":"Which of the following describe what 'multiple perspectives' means in social science?\n1. Comparing how different groups experienced the same event\n2. Accepting every claim as valid even without evidence\n3. Recognising the position of the author of a source","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":2,"explanation":"Multiple perspectives means attending to different groups' experiences and to who is speaking in a source. It does not mean that every claim is equally valid regardless of evidence.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"निम्नलिखित में से कौन-से सामाजिक विज्ञान में ‘बहुल दृष्टिकोण’ (multiple perspectives) का अर्थ बताते हैं? 1. एक ही घटना को विभिन्न समूहों ने कैसे अनुभव किया, इसकी तुलना करना 2. साक्ष्य के बिना भी हर दावे को वैध मान लेना 3. किसी स्रोत के लेखक की स्थिति को पहचानना","optionsHi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"explanationHi":"बहुल दृष्टिकोण का अर्थ है विभिन्न समूहों के अनुभवों और यह ध्यान देना कि किसी स्रोत में कौन बोल रहा है। इसका अर्थ यह नहीं कि साक्ष्य की परवाह किए बिना हर दावा समान रूप से वैध है।"},
  {"id":"cdp-pedagogy-subjects-1647","question":"Which learning objective is best framed for a Class VI lesson on rural livelihoods?","options":["Students will know about rural life and the many different occupations found in Indian villages.","Students will appreciate villages and develop respect for the hard work done by rural people.","Students will compare the work, income and security of a landless labourer and a landowner.","Students will understand the chapter on rural livelihoods fully and answer all its questions."],"answer":2,"explanation":"A good objective names a specific, observable performance, here comparing on stated aspects using given material. 'Know', 'appreciate' and 'understand fully' are vague and cannot be checked.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कक्षा VI के ग्रामीण आजीविका पर पाठ के लिए कौन-सा अधिगम उद्देश्य सबसे अच्छी तरह तैयार किया गया है?","optionsHi":["विद्यार्थी ग्रामीण जीवन और भारतीय गाँवों में पाए जाने वाले अनेक विभिन्न व्यवसायों के बारे में जानेंगे।","विद्यार्थी गाँवों की सराहना करेंगे और ग्रामीण लोगों द्वारा किए जाने वाले कठिन परिश्रम के प्रति सम्मान विकसित करेंगे।","विद्यार्थी एक भूमिहीन मज़दूर और एक भूस्वामी के कार्य, आय और सुरक्षा की तुलना करेंगे।","विद्यार्थी ग्रामीण आजीविका के अध्याय को पूरी तरह समझेंगे और उसके सभी प्रश्नों के उत्तर देंगे।"],"explanationHi":"अच्छा उद्देश्य किसी विशिष्ट, देखने योग्य निष्पादन को नाम देता है, यहाँ दी गई सामग्री से बताए गए पहलुओं पर तुलना करना। ‘जानना’, ‘सराहना’ और ‘पूरी तरह समझना’ अस्पष्ट हैं और उनकी जाँच नहीं की जा सकती।"},
  {"id":"cdp-pedagogy-subjects-1648","question":"A Class X teacher asks students to say whatever comes to mind when they hear 'globalisation' and writes every response on the board without comment. Which technique is she using, and what is its purpose?","options":["Brainstorming, to generate ideas freely and reveal what students already know","Lecture, to explain the concept step by step, using students' own words as examples","Drill, to fix the correct definition of globalisation through repetition","Debate, to decide which of the responses is right and which are wrong"],"answer":0,"explanation":"Brainstorming collects many ideas quickly without judging them, revealing what students already know and think. Sorting and evaluating the ideas comes afterwards.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"कक्षा X की एक शिक्षिका विद्यार्थियों से ‘वैश्वीकरण’ सुनकर जो भी मन में आए वह बोलने को कहती है और हर उत्तर बिना टिप्पणी के श्यामपट्ट पर लिखती जाती है। वह कौन-सी तकनीक उपयोग कर रही है, और उसका उद्देश्य क्या है?","optionsHi":["मंथन (Brainstorming), विचारों को स्वतंत्र रूप से उत्पन्न करना और यह प्रकट करना कि विद्यार्थी पहले से क्या जानते हैं","व्याख्यान, संकल्पना को चरण-दर-चरण समझाना, विद्यार्थियों के अपने शब्दों को उदाहरण के रूप में लेकर","अभ्यास-कवायद (Drill), दोहराव से वैश्वीकरण की सही परिभाषा को पक्का करना","वाद-विवाद, यह तय करना कि कौन-से उत्तर सही हैं और कौन-से गलत"],"explanationHi":"मंथन बिना आँके तेज़ी से बहुत-से विचार इकट्ठे करता है, जिससे पता चलता है कि विद्यार्थी पहले से क्या जानते और सोचते हैं। विचारों को छाँटना और परखना बाद में होता है।"},
  {"id":"cdp-pedagogy-subjects-1649","question":"Which test item best assesses whether Class VIII students can apply the concept of representation?","options":["Define representation in your own words and give one example of it from the textbook chapter.","Your class of 40 must pick four members to meet the principal. Suggest a fair method that represents all groups.","Name the number of members in the Lok Sabha and state how many of its seats are reserved for SC and ST candidates.","Write two lines on the importance of representation in a democracy, using the key terms from the chapter."],"answer":1,"explanation":"Applying a concept means using it in a new situation. Designing a fair selection for a class committee requires students to think about who is represented and how, which a definition or a fact cannot show.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB","questionHi":"कौन-सा परीक्षा-प्रश्न इसका सबसे अच्छा आकलन करता है कि कक्षा VIII के विद्यार्थी प्रतिनिधित्व की संकल्पना को लागू कर सकते हैं या नहीं?","optionsHi":["प्रतिनिधित्व को अपने शब्दों में परिभाषित कीजिए और पाठ्यपुस्तक के अध्याय से उसका एक उदाहरण दीजिए।","आपकी 40 विद्यार्थियों की कक्षा को प्रधानाचार्य से मिलने के लिए चार सदस्य चुनने हैं। सभी समूहों का प्रतिनिधित्व करने वाली एक निष्पक्ष विधि सुझाइए।","लोकसभा के सदस्यों की संख्या बताइए और यह बताइए कि उसकी कितनी सीटें SC और ST उम्मीदवारों के लिए आरक्षित हैं।","लोकतंत्र में प्रतिनिधित्व के महत्व पर अध्याय के मुख्य शब्दों का उपयोग करते हुए दो पंक्तियाँ लिखिए।"],"explanationHi":"किसी संकल्पना को लागू करने का अर्थ है उसे नई स्थिति में उपयोग करना। कक्षा समिति के लिए निष्पक्ष चयन की रचना करने में विद्यार्थियों को सोचना पड़ता है कि किसका प्रतिनिधित्व होता है और कैसे, जो परिभाषा या तथ्य नहीं दिखा सकता।"},
  {"id":"cdp-pedagogy-subjects-1650","question":"A Class VIII teacher wants students to work with a primary source in a lesson on the Salt Satyagraha. Which material should she choose?","options":["The summary of the Salt March given in the current textbook","A newspaper report of the march published in 1930","A quiz on the dates of the march prepared by the teacher","A documentary on the march made in 2015, with a modern narrator"],"answer":1,"explanation":"A newspaper report printed during the march was produced at the time of the event, so it is a primary source. A present-day textbook summary and a recent documentary interpret the event later and are secondary.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS","questionHi":"कक्षा VIII की एक शिक्षिका चाहती है कि विद्यार्थी नमक सत्याग्रह पर पाठ में प्राथमिक स्रोत के साथ कार्य करें। उसे कौन-सी सामग्री चुननी चाहिए?","optionsHi":["वर्तमान पाठ्यपुस्तक में दिया गया नमक यात्रा का सारांश","1930 में प्रकाशित यात्रा की समाचार-पत्र रिपोर्ट","शिक्षिका द्वारा तैयार की गई यात्रा की तिथियों पर प्रश्नोत्तरी","2015 में बनी यात्रा पर एक वृत्तचित्र, जिसमें आधुनिक वाचक है"],"explanationHi":"यात्रा के दौरान छपी समाचार-पत्र रिपोर्ट घटना के समय बनी थी, इसलिए वह प्राथमिक स्रोत है। आज की पाठ्यपुस्तक का सारांश और हाल का वृत्तचित्र घटना की बाद में व्याख्या करते हैं और द्वितीयक हैं।"},
  {"id":"cdp-pedagogy-subjects-1651","question":"A Class II teacher plans a week of reading: P. children read a new levelled book on their own; Q. the teacher reads a big book aloud, thinking aloud about how she works out a hard word; R. a small group reads a book with the teacher's prompts and support; S. the whole class reads the big book together with the teacher. Following the gradual release of responsibility, what is the right order?","options":["S, Q, R, P","Q, R, S, P","Q, S, R, P","P, R, S, Q"],"answer":2,"explanation":"Responsibility moves from teacher to child: modelling (Q, 'I do'), shared reading (S, 'we do'), guided reading (R, 'you do with help') and independent reading (P, 'you do alone').","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा II की एक शिक्षिका पढ़ने के एक सप्ताह की योजना बनाती है: P. बच्चे स्वयं एक नई स्तरित (levelled) पुस्तक पढ़ते हैं; Q. शिक्षिका एक बड़ी किताब ज़ोर से पढ़ती है, यह ज़ोर से सोचते हुए कि वह किसी कठिन शब्द को कैसे समझती है; R. एक छोटा समूह शिक्षिका के संकेतों और सहायता से एक पुस्तक पढ़ता है; S. पूरी कक्षा शिक्षिका के साथ मिलकर बड़ी किताब पढ़ती है। उत्तरदायित्व के क्रमिक हस्तांतरण के अनुसार सही क्रम क्या है?","optionsHi":["S, Q, R, P","Q, R, S, P","Q, S, R, P","P, R, S, Q"],"explanationHi":"उत्तरदायित्व शिक्षिका से बच्चे की ओर जाता है: आदर्श प्रस्तुत करना (Q, ‘मैं करती हूँ’), साझा पठन (S, ‘हम करते हैं’), निर्देशित पठन (R, ‘तुम सहायता से करते हो’) और स्वतंत्र पठन (P, ‘तुम अकेले करते हो’)।"},
  {"id":"cdp-pedagogy-subjects-1652","question":"In a Class I classroom in Mandla, the teacher starts each day with a circle time in which children talk about what they saw on the way to school, in whatever language they are comfortable with. Which outcome is this practice most directly designed to support?","options":["Completing the textbook faster, since children are already settled and ready when the lesson starts","Oral language development and confidence, which form the base for reading and writing","Testing children's general knowledge about their surroundings and the events of the day","Keeping children calm and quiet before the first period of formal teaching begins"],"answer":1,"explanation":"Rich daily conversation builds vocabulary, listening and speaking, and a sense of belonging, all of which underpin early literacy. NCF-FS 2022 gives conversation a central place for this reason.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"मंडला की कक्षा I में शिक्षिका हर दिन गोला-समय (circle time) से शुरू करती है, जिसमें बच्चे विद्यालय आते समय जो देखा उसके बारे में अपनी सहज किसी भी भाषा में बात करते हैं। यह अभ्यास सबसे सीधे किस परिणाम को सहारा देने के लिए बनाया गया है?","optionsHi":["पाठ्यपुस्तक जल्दी पूरी करना, क्योंकि पाठ शुरू होते समय बच्चे पहले से स्थिर और तैयार होते हैं","मौखिक भाषा विकास और आत्मविश्वास, जो पठन और लेखन का आधार बनते हैं","बच्चों के अपने परिवेश और दिन की घटनाओं के बारे में सामान्य ज्ञान की परीक्षा लेना","औपचारिक शिक्षण के पहले पीरियड से पहले बच्चों को शांत और चुप रखना"],"explanationHi":"प्रतिदिन की समृद्ध बातचीत शब्दावली, श्रवण और वाचन तथा अपनेपन की भावना बनाती है, जो सभी प्रारंभिक साक्षरता के आधार हैं। NCF-FS 2022 इसी कारण संवाद को केंद्रीय स्थान देती है।"},
  {"id":"cdp-pedagogy-subjects-1653","question":"A Class III teacher wants children's writing to be purposeful rather than copying from the board. Which task best meets this aim?","options":["Copying the textbook lesson neatly in notebooks, so that children learn correct spelling and sentences","Writing the same sentence ten times, so that handwriting becomes neat and letters are well formed","Writing answers to questions from the guidebook, so that children have correct material to revise","Writing a letter to the gram panchayat about the broken handpump near school, after discussing it"],"answer":3,"explanation":"Writing for a real audience and purpose gives children a reason to organise ideas and use language meaningfully. Copying and repetition practise form but not composition.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा III की एक शिक्षिका चाहती है कि बच्चों का लेखन श्यामपट्ट से उतारने के बजाय उद्देश्यपूर्ण हो। कौन-सा कार्य इस लक्ष्य को सबसे अच्छी तरह पूरा करता है?","optionsHi":["पाठ्यपुस्तक का पाठ कॉपियों में साफ़-सुथरा उतारना, ताकि बच्चे सही वर्तनी और वाक्य सीखें","एक ही वाक्य दस बार लिखना, ताकि लिखावट साफ़ हो और अक्षर सही बनें","गाइड-पुस्तक के प्रश्नों के उत्तर लिखना, ताकि बच्चों के पास दोहराने के लिए सही सामग्री हो","विद्यालय के पास टूटे हैंडपंप के बारे में चर्चा के बाद ग्राम पंचायत को पत्र लिखना"],"explanationHi":"वास्तविक पाठक और उद्देश्य के लिए लिखना बच्चों को विचारों को व्यवस्थित करने और भाषा का सार्थक उपयोग करने का कारण देता है। उतारना और दोहराना रूप का अभ्यास कराते हैं, रचना का नहीं।"},
  {"id":"cdp-pedagogy-subjects-1654","question":"Four-year-old Pinky fills a page with wavy lines and a few letter-like shapes, then 'reads' it to her teacher: 'Milk, bread, sugar.' Which interpretation is most accurate?","options":["She shows emergent writing: she knows writing carries a message, before using conventional letters","She is only scribbling, which has no real connection to writing and will simply stop as she grows","She is confused about writing, because she cannot actually read what she wrote and is only pretending","She should be taught to trace letters properly before she is allowed to 'write' on her own again"],"answer":0,"explanation":"Assigning meaning to marks shows an understanding that print carries messages, a key emergent literacy milestone. Treating it as meaningless scribble or forcing tracing undervalues this development.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"चार वर्ष की पिंकी एक पन्ने को लहरदार रेखाओं और कुछ अक्षर-जैसी आकृतियों से भर देती है, फिर अपनी शिक्षिका को उसे ‘पढ़कर’ सुनाती है: ‘दूध, डबलरोटी, चीनी।’ कौन-सी व्याख्या सबसे सटीक है?","optionsHi":["वह उभरता लेखन (emergent writing) दिखाती है: वह जानती है कि लेखन में संदेश होता है, प्रचलित अक्षरों का उपयोग करने से पहले ही","वह केवल घसीट रही है, जिसका लेखन से कोई वास्तविक संबंध नहीं है और जो बड़े होने पर अपने-आप रुक जाएगा","वह लेखन के बारे में भ्रमित है, क्योंकि वह वास्तव में अपना लिखा पढ़ नहीं सकती और केवल नाटक कर रही है","उसे अक्षरों को ठीक से उतारना सिखाया जाना चाहिए, इससे पहले कि उसे फिर से अपने आप ‘लिखने’ दिया जाए"],"explanationHi":"चिह्नों को अर्थ देना यह समझ दिखाता है कि छपे चिह्न संदेश देते हैं, जो प्रारंभिक साक्षरता की एक प्रमुख उपलब्धि है। इसे निरर्थक घसीट मानना या अक्षर उतारने के लिए बाध्य करना इस विकास को कम आँकना है।"},
  {"id":"cdp-pedagogy-subjects-1655","question":"A Class III teacher measures her students' reading only by words read correctly per minute and praises the fastest readers. Many fast readers cannot say what the passage was about. Which conclusion is most appropriate?","options":["Speed is the most reliable measure of reading ability, since fast readers will understand more in time","The passage was too easy, so children raced through it without needing to think about the meaning","Fluency matters as a support for comprehension; assessment must check understanding, not just speed","Comprehension cannot be properly assessed as early as Class III, so speed is the best measure available"],"answer":2,"explanation":"Fluency is a bridge to comprehension, not the goal itself. Rewarding speed alone encourages 'barking at print' without meaning-making.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा III की एक शिक्षिका अपने विद्यार्थियों के पठन को केवल प्रति मिनट सही पढ़े गए शब्दों से मापती है और सबसे तेज़ पाठकों की प्रशंसा करती है। बहुत-से तेज़ पाठक बता नहीं पाते कि गद्यांश किस बारे में था। कौन-सा निष्कर्ष सबसे उपयुक्त है?","optionsHi":["गति पठन-क्षमता का सबसे विश्वसनीय माप है, क्योंकि तेज़ पाठक समय के साथ अधिक समझेंगे","गद्यांश बहुत आसान था, इसलिए बच्चे अर्थ पर सोचे बिना उसे दौड़ाकर पढ़ गए","प्रवाह बोध की सहायता के रूप में महत्वपूर्ण है; आकलन में समझ की जाँच होनी चाहिए, केवल गति की नहीं","कक्षा III में इतनी जल्दी बोध का ठीक से आकलन नहीं किया जा सकता, इसलिए गति ही उपलब्ध सर्वश्रेष्ठ माप है"],"explanationHi":"प्रवाह बोध तक पहुँचने का पुल है, स्वयं लक्ष्य नहीं। केवल गति को पुरस्कृत करना अर्थ-निर्माण के बिना ‘छपे शब्दों पर भौंकने’ (barking at print) को प्रोत्साहित करता है।"},
  {"id":"cdp-pedagogy-subjects-1656","question":"Assertion (A): Well-planned, engaging lessons prevent much classroom misbehaviour. Reason (R): Students who are actively involved in meaningful tasks have fewer reasons and opportunities to go off task.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Preventive classroom management relies on engagement, clear routines and pace; much disruption comes from boredom, confusion or idle time, as R explains.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"अभिकथन (A): भली-भाँति नियोजित, रोचक पाठ कक्षा के बहुत-से कुव्यवहार को रोकते हैं। कारण (R): जो विद्यार्थी सार्थक कार्यों में सक्रिय रूप से लगे होते हैं, उनके पास कार्य से भटकने के कम कारण और अवसर होते हैं।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"निवारक कक्षा-प्रबंधन सहभागिता, स्पष्ट दिनचर्याओं और गति पर निर्भर करता है; बहुत-सा व्यवधान ऊब, भ्रम या खाली समय से आता है, जैसा R समझाता है।"},
  {"id":"cdp-pedagogy-subjects-1657","question":"While rushing in a Class II art activity, Mohit spills paint across a table. Which teacher response is an example of a logical consequence rather than a punishment?","options":["Making Mohit stand in the corner for the rest of the period to think about his carelessness","Taking away his recess for two days, so that he learns to be careful with class materials","Writing a note in his diary so that his parents know about the mess and can talk to him","Asking Mohit to help clean the table and to carry paint more carefully next time"],"answer":3,"explanation":"A logical consequence (Dreikurs) is directly and reasonably related to the behaviour and teaches responsibility. Standing in a corner or losing recess have no link to the spill and are punitive.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"कक्षा II की कला-गतिविधि में जल्दबाज़ी करते हुए मोहित मेज़ पर रंग गिरा देता है। शिक्षिका की कौन-सी प्रतिक्रिया दंड के बजाय तार्किक परिणाम (logical consequence) का उदाहरण है?","optionsHi":["मोहित को पीरियड के बाकी समय कोने में खड़ा करना ताकि वह अपनी लापरवाही पर सोचे","उसकी दो दिन की आधी छुट्टी (recess) छीन लेना, ताकि वह कक्षा की सामग्री के प्रति सावधान रहना सीखे","उसकी डायरी में नोट लिखना ताकि उसके माता-पिता को गंदगी का पता चले और वे उससे बात कर सकें","मोहित से मेज़ साफ़ करने में मदद करने और अगली बार रंग अधिक सावधानी से ले जाने को कहना"],"explanationHi":"तार्किक परिणाम (ड्रेइकर्स) व्यवहार से सीधे और उचित रूप से जुड़ा होता है और उत्तरदायित्व सिखाता है। कोने में खड़ा करना या आधी छुट्टी छिनना रंग गिरने से असंबंधित और दंडात्मक हैं।"},
  {"id":"cdp-pedagogy-subjects-1658","question":"Two Class V boys get into a fight after one breaks the other's model. Which approach reflects restorative practice?","options":["Bring them together to talk about what happened, how each was affected and how to repair the harm","Suspend both boys for a day, so that the rest of the school learns that fighting is not tolerated","Find out who started the fight and punish only him, since the other boy was only defending himself","Separate the two boys for the rest of the year, so that they get no further chance to quarrel"],"answer":0,"explanation":"Restorative practice focuses on understanding harm, taking responsibility and repairing relationships, rather than only assigning blame and punishment.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs","questionHi":"कक्षा V के दो लड़के तब झगड़ पड़ते हैं जब एक दूसरे का मॉडल तोड़ देता है। कौन-सा तरीका पुनर्स्थापनात्मक (restorative) अभ्यास को दर्शाता है?","optionsHi":["उन्हें साथ बुलाकर बात करना कि क्या हुआ, हर एक पर क्या प्रभाव पड़ा और हानि की मरम्मत कैसे हो","दोनों लड़कों को एक दिन के लिए निलंबित करना, ताकि बाकी विद्यालय सीखे कि झगड़ा सहन नहीं किया जाएगा","पता लगाना कि झगड़ा किसने शुरू किया और केवल उसे दंड देना, क्योंकि दूसरा लड़का केवल अपना बचाव कर रहा था","दोनों लड़कों को वर्ष के बाकी समय के लिए अलग कर देना, ताकि उन्हें आगे झगड़ने का मौका न मिले"],"explanationHi":"पुनर्स्थापनात्मक अभ्यास केवल दोष तय करने और दंड देने के बजाय हानि को समझने, उत्तरदायित्व लेने और संबंधों की मरम्मत करने पर केंद्रित होता है।"},
  {"id":"cdp-pedagogy-subjects-1659","question":"A Class VI teacher in a crowded government school has 62 students and a small room. Which set of strategies is most likely to keep the class productive?","options":["Clear, well-paced lectures, a strict silence rule, and a short question slot at the very end","Clear routines and signals, small groups with rotating leaders, materials ready, pair talk","Ability-based rows, extra time for the weaker rows, and a monitor to keep others quiet","One whole-class activity at a time, with each student called up to the board in turn"],"answer":1,"explanation":"Routines, signals and organised groups and pairs make active learning possible even with 62 students. Well-paced lectures keep order but leave most students passive, and ability rows label learners.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs","questionHi":"भीड़भाड़ वाले सरकारी विद्यालय में कक्षा VI की एक शिक्षिका के पास 62 विद्यार्थी और एक छोटा कमरा है। कौन-से उपायों का समूह कक्षा को उत्पादक बनाए रखने की सबसे अधिक संभावना रखता है?","optionsHi":["स्पष्ट, उचित गति वाले व्याख्यान, कड़ा मौन नियम, और बिल्कुल अंत में प्रश्न पूछने का छोटा समय","स्पष्ट दिनचर्याएँ और संकेत, बारी-बारी से नेता बनने वाले छोटे समूह, तैयार सामग्री, जोड़ी में बातचीत","योग्यता-आधारित पंक्तियाँ, कमज़ोर पंक्तियों को अतिरिक्त समय, और बाकी को शांत रखने के लिए एक निगरानीकर्ता","एक बार में एक ही पूरी-कक्षा गतिविधि, जिसमें हर विद्यार्थी को बारी-बारी से श्यामपट्ट पर बुलाया जाए"],"explanationHi":"दिनचर्याएँ, संकेत और संगठित समूह तथा जोड़ियाँ 62 विद्यार्थियों के साथ भी सक्रिय अधिगम को संभव बनाते हैं। उचित गति वाले व्याख्यान व्यवस्था रखते हैं पर अधिकांश विद्यार्थियों को निष्क्रिय छोड़ देते हैं, और योग्यता-पंक्तियाँ अधिगमकर्ताओं पर ठप्पा लगाती हैं।"},
  {"id":"cdp-pedagogy-subjects-1660","question":"In a pre-primary class, three-year-olds Anu and Babu sit side by side, each building with blocks, sometimes copying each other but not building together. Their teacher is worried that they are 'not playing together'. According to Parten's stages of play, what should she conclude?","options":["They have a social development problem and should be referred to a counsellor for support","They should be made to build one tower together, so that they learn to cooperate early","This is parallel play, which is normal at this age and leads on to cooperative play","This is solitary play, which shows that they do not like each other and prefer to be alone"],"answer":2,"explanation":"Parten found that playing alongside others with similar materials (parallel play) is common in young preschoolers and precedes associative and cooperative play. It is not a sign of a problem.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"पूर्व-प्राथमिक कक्षा में तीन वर्ष के अनु और बाबू साथ-साथ बैठे हैं, हर एक ब्लॉकों से कुछ बना रहा है, कभी एक-दूसरे की नकल करते हैं पर साथ मिलकर नहीं बना रहे। उनकी शिक्षिका चिंतित है कि वे ‘साथ नहीं खेल रहे’। पार्टेन (Parten) के खेल के चरणों के अनुसार उसे क्या निष्कर्ष निकालना चाहिए?","optionsHi":["उन्हें सामाजिक विकास की समस्या है और सहायता के लिए परामर्शदाता के पास भेजा जाना चाहिए","उन्हें एक ही मीनार साथ बनाने को बाध्य करना चाहिए, ताकि वे जल्दी सहयोग करना सीखें","यह समानांतर खेल है, जो इस आयु में सामान्य है और सहकारी खेल की ओर ले जाता है","यह एकाकी खेल है, जो दिखाता है कि वे एक-दूसरे को पसंद नहीं करते और अकेले रहना पसंद करते हैं"],"explanationHi":"पार्टेन ने पाया कि समान सामग्री के साथ दूसरों के बगल में खेलना (समानांतर खेल) छोटे पूर्व-विद्यालयी बच्चों में आम है और साहचर्य तथा सहकारी खेल से पहले आता है। यह किसी समस्या का संकेत नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1661","question":"Match each type of play described by Piaget with the example: P. A baby repeatedly shaking a rattle to hear the sound; Q. A four-year-old using a leaf as a plate for 'feeding' her doll; R. Eight-year-olds playing kho-kho by agreed rules. Types: 1. Games with rules; 2. Practice (functional) play; 3. Symbolic play.","options":["P-3, Q-2, R-1","P-2, Q-3, R-1","P-2, Q-1, R-3","P-1, Q-3, R-2"],"answer":1,"explanation":"Practice play repeats actions for their own sake (sensorimotor years), symbolic play uses one thing to stand for another (preoperational years), and games with rules emerge strongly in middle childhood.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"पियाजे द्वारा वर्णित प्रत्येक प्रकार के खेल का उदाहरण से मिलान कीजिए: P. शिशु का आवाज़ सुनने के लिए बार-बार झुनझुना हिलाना; Q. चार वर्ष की बच्ची का पत्ते को थाली बनाकर अपनी गुड़िया को ‘खिलाना’; R. आठ वर्ष के बच्चों का तय नियमों से खो-खो खेलना। प्रकार: 1. नियमों वाले खेल; 2. अभ्यास (क्रियात्मक) खेल; 3. प्रतीकात्मक खेल।","optionsHi":["P-3, Q-2, R-1","P-2, Q-3, R-1","P-2, Q-1, R-3","P-1, Q-3, R-2"],"explanationHi":"अभ्यास खेल क्रियाओं को उन्हीं के लिए दोहराता है (संवेदी-गामक वर्ष), प्रतीकात्मक खेल एक वस्तु को दूसरी के प्रतीक के रूप में उपयोग करता है (पूर्व-संक्रियात्मक वर्ष), और नियमों वाले खेल मध्य बाल्यावस्था में प्रबल रूप से उभरते हैं।"},
  {"id":"cdp-pedagogy-subjects-1662","question":"Consider the following statements about experiential and vocational exposure in NEP 2020: 1. It suggests '10 bagless days' during Grades 6 to 8, when students intern with local vocational experts such as carpenters, gardeners or potters. 2. It treats vocational exposure as only for students who are weak in academics. 3. It aims to reduce the hard separation between academic and vocational streams. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 and 3 only"],"answer":3,"explanation":"NEP 2020 proposes bagless days with local vocational experts for all students in Grades 6-8 and seeks to remove hard separations between academic and vocational learning. Statement 2 contradicts this.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"NEP 2020 में अनुभवात्मक और व्यावसायिक अनुभव के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. यह कक्षा 6 से 8 के दौरान ‘10 बिना बस्ते के दिन’ (bagless days) सुझाती है, जब विद्यार्थी बढ़ई, माली या कुम्हार जैसे स्थानीय व्यावसायिक विशेषज्ञों के साथ प्रशिक्षण करते हैं। 2. यह व्यावसायिक अनुभव को केवल उन विद्यार्थियों के लिए मानती है जो पढ़ाई में कमज़ोर हैं। 3. इसका उद्देश्य शैक्षणिक और व्यावसायिक धाराओं के बीच कठोर विभाजन को कम करना है। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 2 और 3","1, 2 और 3","केवल 1 और 3"],"explanationHi":"NEP 2020 कक्षा 6-8 के सभी विद्यार्थियों के लिए स्थानीय व्यावसायिक विशेषज्ञों के साथ बिना बस्ते के दिन प्रस्तावित करती है और शैक्षणिक तथा व्यावसायिक अधिगम के बीच कठोर विभाजन हटाना चाहती है। कथन 2 इसके विपरीत है।"},
  {"id":"cdp-pedagogy-subjects-1663","question":"In a Class VI comprehension lesson, a teacher asks: 'The passage says the farmer's crops failed twice, and in the last paragraph he joins a self-help group. Using both parts, why do you think he made that decision?' In Raphael's Question-Answer Relationships (QAR), this question is of which type?","options":["Right There","On My Own","Think and Search","Author and Me"],"answer":2,"explanation":"Think and Search questions have answers in the text, but the reader must pull together information from different parts. 'Right There' answers sit in one sentence, and 'Author and Me' needs the reader's own knowledge as well as the text.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VI के बोध-पाठ में एक शिक्षिका पूछती है: ‘गद्यांश कहता है कि किसान की फ़सलें दो बार विफल हुईं, और अंतिम अनुच्छेद में वह एक स्वयं सहायता समूह से जुड़ जाता है। दोनों भागों का उपयोग करके बताओ कि तुम्हारे विचार में उसने यह निर्णय क्यों लिया?’ रैफ़ेल के प्रश्न-उत्तर संबंध (QAR) में यह प्रश्न किस प्रकार का है?","optionsHi":["ठीक वहीं (Right There)","मेरे अपने से (On My Own)","सोचो और खोजो (Think and Search)","लेखक और मैं (Author and Me)"],"explanationHi":"‘सोचो और खोजो’ प्रश्नों के उत्तर पाठ में होते हैं, पर पाठक को विभिन्न भागों की जानकारी जोड़नी पड़ती है। ‘ठीक वहीं’ के उत्तर एक वाक्य में होते हैं, और ‘लेखक और मैं’ में पाठ के साथ पाठक का अपना ज्ञान भी चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1664","question":"Assertion (A): Jigsaw classrooms tend to reduce hostility and prejudice among students from different social groups. Reason (R): In jigsaw, each student holds information others need, so students must depend on and listen to each other.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Aronson’s jigsaw cuts prejudice because every member’s piece is needed, so students must cooperate and come to value one another; this interdependence is exactly why hostility falls, so R explains A.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"अभिकथन (A): जिगसॉ (jigsaw) कक्षाएँ विभिन्न सामाजिक समूहों के विद्यार्थियों के बीच शत्रुता और पूर्वाग्रह को घटाने की प्रवृत्ति रखती हैं। कारण (R): जिगसॉ में हर विद्यार्थी के पास ऐसी जानकारी होती है जो दूसरों को चाहिए, इसलिए विद्यार्थियों को एक-दूसरे पर निर्भर रहना और एक-दूसरे की सुनना पड़ता है।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"एरोनसन का जिगसॉ पूर्वाग्रह घटाता है क्योंकि हर सदस्य का भाग आवश्यक होता है, इसलिए विद्यार्थियों को सहयोग करना पड़ता है और वे एक-दूसरे को महत्व देने लगते हैं; यही परस्पर निर्भरता शत्रुता घटने का कारण है, इसलिए R, A को समझाता है।"},
  {"id":"cdp-pedagogy-subjects-1665","question":"Before moving on in a Class VII lesson on fractions, a teacher asks one carefully chosen multiple-choice question where each wrong option matches a known misconception, and all students hold up their answer cards at once. What is the main purpose of this step?","options":["To collect a grade for every student that can be entered in the term's assessment record","To fill the remaining minutes of the period with a quick and enjoyable whole-class activity","To see at once who has the key idea and which misconceptions remain, before moving on","To make the lesson more competitive, since students enjoy seeing who gets the answer first"],"answer":2,"explanation":"Such a 'hinge' question gives instant evidence from every student at a decision point in the lesson; diagnostic distractors show exactly what to re-teach.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VII के भिन्नों के पाठ में आगे बढ़ने से पहले एक शिक्षिका एक सावधानी से चुना बहुविकल्पीय प्रश्न पूछती है जिसमें हर गलत विकल्प किसी ज्ञात भ्रांति से मेल खाता है, और सभी विद्यार्थी एक साथ अपने उत्तर-कार्ड उठाते हैं। इस चरण का मुख्य उद्देश्य क्या है?","optionsHi":["हर विद्यार्थी का ऐसा अंक इकट्ठा करना जिसे सत्र के आकलन अभिलेख में दर्ज किया जा सके","पीरियड के बचे मिनटों को एक त्वरित और आनंददायक पूरी-कक्षा गतिविधि से भरना","आगे बढ़ने से पहले एक नज़र में देखना कि किसे मुख्य विचार समझ आया है और कौन-सी भ्रांतियाँ बाकी हैं","पाठ को अधिक प्रतिस्पर्धात्मक बनाना, क्योंकि विद्यार्थियों को देखना अच्छा लगता है कि उत्तर सबसे पहले किसे मिलता है"],"explanationHi":"ऐसा ‘कब्ज़ा’ (hinge) प्रश्न पाठ के निर्णय-बिंदु पर हर विद्यार्थी से तुरंत साक्ष्य देता है; निदानात्मक विकर्षक (distractors) ठीक बताते हैं कि क्या दोबारा पढ़ाना है।"},
  {"id":"cdp-pedagogy-subjects-1666","question":"While teaching Class IV children to write a paragraph, a teacher first gives sentence starters and a word bank, then only a word bank, and finally asks them to write without any support. What is she doing?","options":["Reducing support step by step as children gain competence (fading the scaffold)","Lowering her expectations of the class, since many children could not write paragraphs","Making the task harder each time, as a way of pushing the class to work faster","Testing whether children can remember the word bank without seeing it any more"],"answer":0,"explanation":"Scaffolding is temporary support that is withdrawn as learners become independent; fading it gradually transfers responsibility to the child.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा IV के बच्चों को अनुच्छेद लिखना सिखाते समय एक शिक्षिका पहले वाक्य-आरंभ और शब्द-बैंक देती है, फिर केवल शब्द-बैंक, और अंत में बिना किसी सहायता के लिखने को कहती है। वह क्या कर रही है?","optionsHi":["बच्चों की क्षमता बढ़ने के साथ सहायता को चरण-दर-चरण घटाना (पाड़ को धीरे-धीरे हटाना)","कक्षा से अपनी अपेक्षाएँ घटाना, क्योंकि बहुत-से बच्चे अनुच्छेद नहीं लिख सके","हर बार कार्य को कठिन बनाना, कक्षा को तेज़ी से काम करने के लिए धकेलने के तरीके के रूप में","यह जाँचना कि बच्चे शब्द-बैंक को बिना देखे याद रख सकते हैं या नहीं"],"explanationHi":"पाड़ (scaffolding) अस्थायी सहायता है जो अधिगमकर्ताओं के स्वतंत्र होने के साथ हटा ली जाती है; उसे धीरे-धीरे हटाना उत्तरदायित्व बच्चे को सौंपता है।"},
  {"id":"cdp-pedagogy-subjects-1667","question":"Biswajit, an Odia-speaking child, joins a Class II in Raipur where the medium is Hindi. Which step by the teacher is most likely to help him settle and learn?","options":["Seat him alone near the teacher, so that he can concentrate fully on learning Hindi without distraction","Pair him with a buddy who knows Odia and Hindi, accept Odia responses, and use pictures and gestures","Tell him to speak only Hindi from the first day, since that is the fastest way to learn it","Place him in Class I for a year until his Hindi is good enough for the Class II textbooks"],"answer":1,"explanation":"A bilingual peer buddy offers emotional and language support, and accepting his language keeps him learning while Hindi develops. Isolation, a language ban or demotion all set him back.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"उड़िया भाषी बच्चा बिस्वजीत रायपुर की कक्षा II में आता है जहाँ माध्यम हिंदी है। शिक्षिका का कौन-सा कदम उसे सहज होने और सीखने में सबसे अधिक मदद करेगा?","optionsHi":["उसे शिक्षिका के पास अकेले बिठाना, ताकि वह बिना विचलन के पूरी तरह हिंदी सीखने पर ध्यान दे सके","उसे ऐसे साथी के साथ जोड़ना जो उड़िया और हिंदी जानता हो, उसके उड़िया उत्तर स्वीकार करना, और चित्रों तथा हाव-भाव का उपयोग करना","उससे पहले दिन से केवल हिंदी बोलने को कहना, क्योंकि यही उसे सीखने का सबसे तेज़ तरीका है","उसे एक वर्ष के लिए कक्षा I में रखना जब तक उसकी हिंदी कक्षा II की पाठ्यपुस्तकों के लिए पर्याप्त न हो जाए"],"explanationHi":"द्विभाषी साथी भावनात्मक और भाषाई सहारा देता है, और उसकी भाषा को स्वीकार करने से हिंदी विकसित होने के दौरान उसका सीखना जारी रहता है। अलग-थलग करना, भाषा पर प्रतिबंध या पदावनति, सब उसे पीछे धकेलते हैं।"},
  {"id":"cdp-pedagogy-subjects-1668","question":"Aarav, a Class II child on the autism spectrum, becomes very upset when the timetable changes unexpectedly. Which classroom strategy is most helpful?","options":["Avoid telling him about changes in advance, so that he does not spend the day worrying","Change routines often and without warning, so that he gradually gets used to change","Use a visual schedule, warn him in advance of any change, and keep routines predictable","Take him out of the class whenever the routine changes, until he has calmed down fully"],"answer":2,"explanation":"Many autistic children rely on predictability; visual schedules and advance warning of changes reduce anxiety and help them participate. Surprises and frequent changes increase distress.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा II का ऑटिज़्म स्पेक्ट्रम पर आने वाला बच्चा आरव समय-सारणी में अचानक बदलाव होने पर बहुत परेशान हो जाता है। कक्षा की कौन-सी रणनीति सबसे सहायक है?","optionsHi":["उसे बदलावों के बारे में पहले से न बताना, ताकि वह पूरा दिन चिंता में न बिताए","दिनचर्याएँ अक्सर और बिना चेतावनी बदलना, ताकि वह धीरे-धीरे बदलाव का आदी हो जाए","दृश्य सारणी का उपयोग करना, किसी भी बदलाव की उसे पहले से चेतावनी देना, और दिनचर्याओं को पूर्वानुमेय रखना","जब भी दिनचर्या बदले उसे कक्षा से बाहर ले जाना, जब तक वह पूरी तरह शांत न हो जाए"],"explanationHi":"बहुत-से ऑटिस्टिक बच्चे पूर्वानुमेयता पर निर्भर करते हैं; दृश्य सारणियाँ और बदलावों की पूर्व चेतावनी चिंता घटाती हैं और उन्हें भाग लेने में मदद करती हैं। आश्चर्य और बार-बार बदलाव कष्ट बढ़ाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1669","question":"In a B.Ed. micro-teaching session, a trainee teaches a 5-minute lesson focused only on the skill of probing questions, receives feedback, re-plans, and re-teaches to a new small group. What is the main reason for this design?","options":["To cover a large part of the syllabus in a short time through many very short lessons","To evaluate the trainee for final certification, since each re-teach is graded separately","To replace real classroom practice teaching, which is too difficult for most trainees","To practise one skill at a time in a simple setting, with feedback and repeated attempts"],"answer":3,"explanation":"Micro-teaching scales down time, class size and content so that a single skill can be practised, observed and refined through the teach-feedback-reteach cycle.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"बी.एड. के सूक्ष्म-शिक्षण सत्र में एक प्रशिक्षु केवल अन्वेषी प्रश्नों (probing questions) के कौशल पर केंद्रित 5 मिनट का पाठ पढ़ाता है, प्रतिपुष्टि पाता है, पुनः योजना बनाता है, और एक नए छोटे समूह को दोबारा पढ़ाता है। इस रचना का मुख्य कारण क्या है?","optionsHi":["बहुत-से बहुत छोटे पाठों से कम समय में पाठ्यक्रम का बड़ा भाग पूरा करना","अंतिम प्रमाणन के लिए प्रशिक्षु का मूल्यांकन करना, क्योंकि हर पुनः-शिक्षण का अलग अंकन होता है","वास्तविक कक्षा-शिक्षण अभ्यास की जगह लेना, जो अधिकांश प्रशिक्षुओं के लिए बहुत कठिन है","सरल परिवेश में एक समय में एक कौशल का अभ्यास करना, प्रतिपुष्टि और बार-बार प्रयासों के साथ"],"explanationHi":"सूक्ष्म-शिक्षण समय, कक्षा का आकार और विषय-वस्तु को घटा देता है ताकि पढ़ाओ-प्रतिपुष्टि-पुनः पढ़ाओ चक्र के माध्यम से किसी एक कौशल का अभ्यास, अवलोकन और परिष्कार किया जा सके।"},
  {"id":"cdp-pedagogy-subjects-1670","question":"A Class I teacher in Meerut replaces all the Hindi and local rhymes her children know with English nursery rhymes, believing this will speed up English learning. What is the most valid concern?","options":["English rhymes are too long and too fast for Class I children to learn and remember easily on their own","It drops familiar rhymes that build sound awareness, and signals that the home language matters less","Rhymes have no real role in early literacy, so the time would be better spent on letters","Children cannot learn more than one language at a time, so English rhymes will confuse them"],"answer":1,"explanation":"Rhymes in a language children understand develop sensitivity to sounds and rhythm, which supports reading in any language. Dropping them devalues the home language and removes meaningful input. Children can learn several languages.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"मेरठ में कक्षा I की एक शिक्षिका अपने बच्चों की जानी हुई सारी हिंदी और स्थानीय तुकबंदियाँ अंग्रेज़ी नर्सरी राइम्स से बदल देती है, यह मानकर कि इससे अंग्रेज़ी सीखना तेज़ होगा। सबसे वैध चिंता क्या है?","optionsHi":["अंग्रेज़ी तुकबंदियाँ कक्षा I के बच्चों के लिए अपने आप आसानी से सीखने और याद रखने के हिसाब से बहुत लंबी और तेज़ हैं","यह उन परिचित तुकबंदियों को छोड़ देता है जो ध्वनि-जागरूकता बनाती हैं, और संकेत देता है कि घरेलू भाषा कम महत्वपूर्ण है","तुकबंदियों की प्रारंभिक साक्षरता में कोई वास्तविक भूमिका नहीं है, इसलिए समय अक्षरों पर बेहतर लगता","बच्चे एक समय में एक से अधिक भाषा नहीं सीख सकते, इसलिए अंग्रेज़ी तुकबंदियाँ उन्हें भ्रमित करेंगी"],"explanationHi":"जिस भाषा को बच्चे समझते हैं उसमें तुकबंदियाँ ध्वनियों और लय के प्रति संवेदनशीलता विकसित करती हैं, जो किसी भी भाषा में पठन को सहारा देती है। उन्हें छोड़ना घरेलू भाषा का अवमूल्यन है और सार्थक निवेश हटाता है। बच्चे कई भाषाएँ सीख सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-1671","question":"A Class IV teacher holds a weekly class meeting in which children raise problems (for example, 'the ball is always taken by the same group at recess'), suggest solutions and agree on one to try. What does this mainly develop?","options":["Dependence on the teacher, who finally decides which solution the class should follow","Competition between groups of children to see whose solution gets the most votes","Skills of democratic participation, problem-solving and shared responsibility","Children's habit of complaining about each other instead of settling matters themselves"],"answer":2,"explanation":"Class meetings give children a voice in managing their community and teach negotiation and responsibility, a democratic approach to classroom management. The teacher facilitates rather than imposes.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs","questionHi":"कक्षा IV की एक शिक्षिका साप्ताहिक कक्षा-सभा करती है जिसमें बच्चे समस्याएँ उठाते हैं (जैसे, ‘आधी छुट्टी में गेंद हमेशा वही समूह ले लेता है’), समाधान सुझाते हैं और एक आज़माने पर सहमत होते हैं। यह मुख्यतः क्या विकसित करता है?","optionsHi":["शिक्षिका पर निर्भरता, जो अंत में तय करती है कि कक्षा को कौन-सा समाधान अपनाना है","बच्चों के समूहों के बीच प्रतिस्पर्धा, यह देखने के लिए कि किसके समाधान को सबसे अधिक मत मिलते हैं","लोकतांत्रिक भागीदारी, समस्या-समाधान और साझा उत्तरदायित्व के कौशल","बच्चों में मामले स्वयं सुलझाने के बजाय एक-दूसरे की शिकायत करने की आदत"],"explanationHi":"कक्षा-सभाएँ बच्चों को अपने समुदाय के प्रबंधन में आवाज़ देती हैं और बातचीत तथा उत्तरदायित्व सिखाती हैं, जो कक्षा-प्रबंधन का लोकतांत्रिक तरीका है। शिक्षिका थोपने के बजाय सुगमन करती है।"},
  {"id":"cdp-pedagogy-subjects-1672","question":"To assess speaking in a Class IV English class, the teacher records each child's 1-minute talk about a favourite food on her phone and listens later with a rubric, sharing the recording with the child. Which advantage is most important?","options":["It allows careful, repeated listening for fair marking, and the child can hear herself and see progress","It removes the need for a rubric, since the teacher can simply compare children's recordings","It allows the teacher to post the recordings publicly, so parents can see what children can do","It replaces the need to talk with children during class, since all speaking can now be recorded at home"],"answer":0,"explanation":"Recordings make oral assessment more reliable and give learners concrete feedback and evidence of growth. Privacy still matters, so recordings should not be posted publicly.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs","questionHi":"कक्षा IV की अंग्रेज़ी कक्षा में बोलने का आकलन करने के लिए शिक्षिका हर बच्चे का पसंदीदा भोजन पर 1 मिनट का भाषण अपने फ़ोन पर रिकॉर्ड करती है और बाद में रूब्रिक के साथ सुनती है, रिकॉर्डिंग बच्चे के साथ साझा करती है। सबसे महत्वपूर्ण लाभ कौन-सा है?","optionsHi":["यह निष्पक्ष अंकन के लिए ध्यान से, बार-बार सुनने की सुविधा देता है, और बच्चा स्वयं को सुन सकती है और प्रगति देख सकती है","यह रूब्रिक की आवश्यकता समाप्त कर देता है, क्योंकि शिक्षिका केवल बच्चों की रिकॉर्डिंग की तुलना कर सकती है","यह शिक्षिका को रिकॉर्डिंग सार्वजनिक रूप से डालने देता है, ताकि अभिभावक देख सकें कि बच्चे क्या कर सकते हैं","यह कक्षा में बच्चों से बात करने की आवश्यकता की जगह लेता है, क्योंकि सारा बोलना अब घर पर रिकॉर्ड हो सकता है"],"explanationHi":"रिकॉर्डिंग मौखिक आकलन को अधिक विश्वसनीय बनाती है और अधिगमकर्ताओं को ठोस प्रतिपुष्टि तथा विकास का साक्ष्य देती है। निजता अब भी मायने रखती है, इसलिए रिकॉर्डिंग सार्वजनिक रूप से नहीं डालनी चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1673","question":"A Class V teacher believes, 'If I let children talk to each other during a task, I lose control of the class.' Which response best reflects current understanding of classroom management and learning?","options":["She is right; a silent class is a well-managed class, and talk should wait until the task is finished","She should allow talk only during recess and games, when it cannot disturb the learning of others","Talk should be allowed only in language periods, where speaking is itself the skill being taught","Structured, purposeful talk aids learning; good management means routines and focus, not silence"],"answer":3,"explanation":"Learning is social, and productive noise during structured tasks is a sign of engagement. Management aims at an environment where learning happens, not at silence for its own sake.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB","questionHi":"कक्षा V की एक शिक्षिका मानती है, ‘अगर मैं बच्चों को किसी कार्य के दौरान आपस में बात करने दूँ, तो कक्षा पर मेरा नियंत्रण छूट जाता है।’ कक्षा-प्रबंधन और अधिगम की वर्तमान समझ को कौन-सी प्रतिक्रिया सबसे अच्छी तरह दर्शाती है?","optionsHi":["वह सही है; शांत कक्षा ही सुप्रबंधित कक्षा है, और बातचीत कार्य पूरा होने के बाद होनी चाहिए","उसे बातचीत की अनुमति केवल आधी छुट्टी और खेल में देनी चाहिए, जब वह दूसरों के अधिगम में बाधा न डाल सके","बातचीत की अनुमति केवल भाषा के पीरियडों में होनी चाहिए, जहाँ बोलना ही सिखाया जा रहा कौशल है","संरचित, उद्देश्यपूर्ण बातचीत अधिगम में सहायक है; अच्छे प्रबंधन का अर्थ दिनचर्याएँ और ध्यान है, चुप्पी नहीं"],"explanationHi":"अधिगम सामाजिक होता है, और संरचित कार्यों के दौरान उत्पादक शोर सहभागिता का चिह्न है। प्रबंधन का लक्ष्य ऐसा वातावरण है जहाँ अधिगम हो, चुप्पी के लिए चुप्पी नहीं।"},
  {"id":"cdp-pedagogy-subjects-1674","question":"Consider the following statements about using local toys and games in the foundational stage: 1. They can be made from low-cost local materials, sometimes by children themselves. 2. They connect school learning to children's culture and home experience. 3. They are useful only for physical development and not for language or number. Which of these are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Local toys and games are affordable, culturally rooted and rich contexts for language, counting, patterns and social skills, so statement 3 is false.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"आधारभूत चरण में स्थानीय खिलौनों और खेलों के उपयोग के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. उन्हें कम लागत की स्थानीय सामग्री से बनाया जा सकता है, कभी-कभी बच्चे स्वयं भी बना सकते हैं। 2. वे विद्यालयी अधिगम को बच्चों की संस्कृति और घरेलू अनुभव से जोड़ते हैं। 3. वे केवल शारीरिक विकास के लिए उपयोगी हैं, भाषा या संख्या के लिए नहीं। इनमें से कौन-से सही हैं?","optionsHi":["केवल 1 और 2","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"],"explanationHi":"स्थानीय खिलौने और खेल किफ़ायती, सांस्कृतिक रूप से जड़ें रखने वाले और भाषा, गिनती, पैटर्न तथा सामाजिक कौशल के लिए समृद्ध संदर्भ हैं, इसलिए कथन 3 गलत है।"},
  {"id":"cdp-pedagogy-subjects-1675","question":"A Class VIII teacher wants her students to evaluate, not just recall, after a lesson on renewable energy. Which task best does this?","options":["‘List five sources of renewable energy and say which of them are used in your own state.’","‘Define solar energy in your own words and give two examples of its use in everyday life.’","‘Draw a neat, labelled diagram of a windmill and name the main parts that help it make electricity.’","‘Solar panels or a biogas plant for our school? Recommend one, judging cost, local needs and benefits.’"],"answer":3,"explanation":"Making and defending a judgement using criteria is Evaluate. Listing and defining are Remember and Understand, and drawing a known diagram is reproduction.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा VIII की एक शिक्षिका चाहती है कि नवीकरणीय ऊर्जा के पाठ के बाद उसके विद्यार्थी केवल स्मरण नहीं, मूल्यांकन करें। कौन-सा कार्य यह सबसे अच्छी तरह करता है?","optionsHi":["‘नवीकरणीय ऊर्जा के पाँच स्रोत सूचीबद्ध कीजिए और बताइए कि इनमें से कौन-से आपके अपने राज्य में उपयोग होते हैं।’","‘सौर ऊर्जा को अपने शब्दों में परिभाषित कीजिए और दैनिक जीवन में उसके उपयोग के दो उदाहरण दीजिए।’","‘पवन चक्की का साफ़-सुथरा, नामांकित आरेख बनाइए और बिजली बनाने में मदद करने वाले मुख्य भागों के नाम बताइए।’","‘हमारे विद्यालय के लिए सौर पैनल या बायोगैस संयंत्र? लागत, स्थानीय आवश्यकताओं और लाभों को आँकते हुए एक की सिफ़ारिश कीजिए।’"],"explanationHi":"मानदंडों का उपयोग करके निर्णय लेना और उसका बचाव करना मूल्यांकन (Evaluate) है। सूचीबद्ध करना और परिभाषित करना स्मरण और समझ हैं, और ज्ञात आरेख बनाना पुनरुत्पादन है।"},
  {"id":"cdp-pedagogy-subjects-1676","question":"A Class 9 teacher has students collect and practise whole expressions such as ‘by the way’, ‘I was wondering if…’, ‘make a decision’ and ‘as far as I know’, treating them as ready-made units rather than building them word by word from rules. This reflects:","options":["The audio-lingual method, which drills single sentence patterns","The grammar-translation method, which works through word lists","The lexical approach, which sees language largely as chunks","The silent way, which builds sentences with coloured rods"],"answer":2,"explanation":"Michael Lewis’s lexical approach holds that much fluent language consists of prefabricated chunks and collocations, so learners should notice and store them as wholes.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 9 के एक शिक्षक विद्यार्थियों से ‘by the way’, ‘I was wondering if…’, ‘make a decision’ और ‘as far as I know’ जैसी पूरी अभिव्यक्तियाँ एकत्र और अभ्यास करवाते हैं, उन्हें नियमों से शब्द-दर-शब्द बनाने के बजाय बने-बनाए खंड मानते हुए। यह किसे दर्शाता है?","optionsHi":["श्रव्य-भाषिक विधि (audio-lingual method), जो अकेले वाक्य-प्रतिरूपों का अभ्यास कराती है","व्याकरण-अनुवाद विधि, जो शब्द-सूचियों पर काम करती है","शाब्दिक उपागम (lexical approach), जो भाषा को बड़े पैमाने पर खंडों (chunks) के रूप में देखता है","मौन मार्ग (silent way), जो रंगीन छड़ों से वाक्य बनाता है"],"explanationHi":"माइकल लुईस का शाब्दिक उपागम मानता है कि प्रवाहपूर्ण भाषा का बड़ा भाग पूर्व-निर्मित खंडों और सहपदों (collocations) से बना होता है, इसलिए अधिगमकर्ताओं को उन्हें पूरे रूप में देखना और संजोना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1677","question":"A Class 8 English course is organised into units titled ‘Making requests’, ‘Apologising’, ‘Giving directions’ and ‘Expressing opinions’, rather than ‘Present tense’ or ‘Passive voice’. This is a:","options":["Structural syllabus, ordered by grammar items","Notional-functional syllabus, ordered by functions","Lexical syllabus, ordered by how often words occur","Procedural syllabus, ordered by a fixed list of tasks"],"answer":1,"explanation":"A notional-functional syllabus, linked with Wilkins and early communicative teaching, organises content around what learners need to do with language rather than grammatical forms.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 8 का अंग्रेज़ी पाठ्यक्रम ‘Present tense’ या ‘Passive voice’ के बजाय ‘अनुरोध करना’, ‘क्षमा माँगना’, ‘दिशा बताना’ और ‘राय व्यक्त करना’ शीर्षक वाली इकाइयों में व्यवस्थित है। यह है एक:","optionsHi":["संरचनात्मक पाठ्यक्रम, जो व्याकरण की मदों के क्रम में है","संकल्पनात्मक-प्रकार्यात्मक पाठ्यक्रम (notional-functional syllabus), जो प्रकार्यों के क्रम में है","शाब्दिक पाठ्यक्रम, जो शब्दों के आने की बारंबारता के क्रम में है","प्रक्रियात्मक पाठ्यक्रम, जो कार्यों की निश्चित सूची के क्रम में है"],"explanationHi":"संकल्पनात्मक-प्रकार्यात्मक पाठ्यक्रम, जो विल्किन्स और आरंभिक संप्रेषणात्मक शिक्षण से जुड़ा है, विषय-वस्तु को इस आधार पर व्यवस्थित करता है कि अधिगमकर्ताओं को भाषा से क्या करना है, न कि व्याकरणिक रूपों पर।"},
  {"id":"cdp-pedagogy-subjects-1678","question":"Teacher P teaches grammar first and then gives communicative activities to practise it. Teacher Q gives communicative tasks from the start and expects language to develop through using it. In the debate on communicative language teaching, these are known respectively as the:","options":["Strong version and weak version of CLT","Grammar-translation and direct method","Structural approach and audio-lingual method","Weak version and strong version of CLT"],"answer":3,"explanation":"The ‘weak’ version (Howatt) adds communicative practice to a taught syllabus — learning to use English; the ‘strong’ version claims language is acquired through communication — using English to learn it.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"शिक्षक P पहले व्याकरण पढ़ाता है और फिर उसका अभ्यास कराने के लिए संप्रेषणात्मक गतिविधियाँ देता है। शिक्षक Q शुरू से ही संप्रेषणात्मक कार्य देता है और अपेक्षा करता है कि भाषा उसके उपयोग से विकसित होगी। संप्रेषणात्मक भाषा शिक्षण (CLT) की बहस में इन्हें क्रमशः क्या कहा जाता है?","optionsHi":["CLT का प्रबल संस्करण और दुर्बल संस्करण","व्याकरण-अनुवाद और प्रत्यक्ष विधि","संरचनात्मक उपागम और श्रव्य-भाषिक विधि","CLT का दुर्बल संस्करण और प्रबल संस्करण"],"explanationHi":"‘दुर्बल’ संस्करण (हॉवैट) पढ़ाए गए पाठ्यक्रम में संप्रेषणात्मक अभ्यास जोड़ता है, यानी अंग्रेज़ी का उपयोग करना सीखना; ‘प्रबल’ संस्करण दावा करता है कि भाषा संप्रेषण से अर्जित होती है, यानी सीखने के लिए अंग्रेज़ी का उपयोग करना।"},
  {"id":"cdp-pedagogy-subjects-1679","question":"Assertion (A): Learners taught only by the grammar-translation method often read and translate texts well but struggle to hold a conversation. Reason (R): The grammar-translation method gives priority to reading, writing and accuracy, and very little to spoken communication.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"What a method practises is what learners become good at; GTM’s focus on written texts and rules explains its learners’ weak speaking.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"अभिकथन (A): केवल व्याकरण-अनुवाद विधि से पढ़े अधिगमकर्ता प्रायः पाठों को पढ़ने और अनुवाद करने में अच्छे होते हैं, पर बातचीत करने में संघर्ष करते हैं। कारण (R): व्याकरण-अनुवाद विधि पठन, लेखन और शुद्धता को प्राथमिकता देती है, और मौखिक संप्रेषण को बहुत कम। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"कोई विधि जिसका अभ्यास कराती है, अधिगमकर्ता उसी में अच्छे बनते हैं; GTM का लिखित पाठों और नियमों पर ध्यान उसके अधिगमकर्ताओं के कमज़ोर बोलने की व्याख्या करता है।"},
  {"id":"cdp-pedagogy-subjects-1680","question":"Consider these statements about the direct method: I. The mother tongue is used to explain difficult words. II. Oral skills are given priority. III. Grammar is taught inductively through examples. Which are correct?","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":1,"explanation":"The direct method bans the mother tongue and conveys meaning through demonstration and context, so I is false; it puts speech first and lets learners infer rules from examples.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"प्रत्यक्ष विधि (direct method) के बारे में इन कथनों पर विचार कीजिए: I. कठिन शब्दों को समझाने के लिए मातृभाषा का उपयोग किया जाता है। II. मौखिक कौशलों को प्राथमिकता दी जाती है। III. व्याकरण उदाहरणों के माध्यम से आगमनात्मक रूप से पढ़ाया जाता है। कौन-से सही हैं?","optionsHi":["केवल I और II","केवल II और III","केवल I और III","I, II और III"],"explanationHi":"प्रत्यक्ष विधि मातृभाषा पर रोक लगाती है और प्रदर्शन तथा संदर्भ से अर्थ पहुँचाती है, इसलिए I गलत है; वह बोलने को पहले रखती है और अधिगमकर्ताओं को उदाहरणों से नियम अनुमान लगाने देती है।"},
  {"id":"cdp-pedagogy-subjects-1681","question":"A Class 5 EVS lesson is taught in English to children still learning it. The teacher uses pictures, real objects, simplified sentences and a list of key words, and plans aims for both the science content and the language needed to talk about it. This approach is best described as:","options":["Immersion with no support, so that learners sink or swim","The grammar-translation method applied to a science lesson","Content and language integrated learning, with dual aims","Teaching EVS through the mother tongue alone, without English"],"answer":2,"explanation":"CLIL integrates subject learning with language learning, using scaffolds such as visuals and key vocabulary so that both content and language develop together.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 5 का एक EVS पाठ उन बच्चों को अंग्रेज़ी में पढ़ाया जाता है जो अभी अंग्रेज़ी सीख रहे हैं। शिक्षिका चित्रों, वास्तविक वस्तुओं, सरल वाक्यों और मुख्य शब्दों की सूची का उपयोग करती है, और विज्ञान की विषय-वस्तु तथा उसके बारे में बात करने के लिए आवश्यक भाषा, दोनों के लिए उद्देश्य बनाती है। इस उपागम का सबसे अच्छा वर्णन है:","optionsHi":["बिना सहायता का निमज्जन, जिसमें अधिगमकर्ता डूबें या तैरें","विज्ञान पाठ पर लागू की गई व्याकरण-अनुवाद विधि","विषय और भाषा का एकीकृत अधिगम (CLIL), दोहरे उद्देश्यों के साथ","केवल मातृभाषा के माध्यम से EVS पढ़ाना, अंग्रेज़ी के बिना"],"explanationHi":"CLIL विषय के अधिगम को भाषा के अधिगम के साथ एकीकृत करता है, दृश्य सामग्री और मुख्य शब्दावली जैसे पाड़ों का उपयोग करते हुए ताकि विषय-वस्तु और भाषा दोनों साथ-साथ विकसित हों।"},
  {"id":"cdp-pedagogy-subjects-1682","question":"While doing a jigsaw puzzle alone, a five-year-old mutters, ‘This blue one… no, not here… the corner piece goes first.’ According to Vygotsky, this talk:","options":["Is egocentric speech that shows the child cannot yet think logically","Is mere imitation of adult speech without any purpose","Is a sign of a language disorder that needs a specialist’s attention","Is private speech that helps the child guide and regulate her action"],"answer":3,"explanation":"Vygotsky saw private speech as social speech turned inward to plan and guide behaviour, a step towards inner speech; Piaget, by contrast, called such talk egocentric.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"अकेले जिगसॉ पहेली हल करते हुए पाँच वर्ष का बच्चा बुदबुदाता है, ‘यह नीला वाला… नहीं, यहाँ नहीं… कोने का टुकड़ा पहले लगेगा।’ वाइगोत्स्की के अनुसार यह बोल:","optionsHi":["अहंकेंद्रित वाणी है जो दिखाती है कि बच्चा अभी तार्किक रूप से नहीं सोच सकता","वयस्कों की वाणी की बिना किसी उद्देश्य के मात्र नकल है","भाषा-विकार का संकेत है जिसके लिए विशेषज्ञ के ध्यान की आवश्यकता है","निजी वाणी (private speech) है जो बच्चे को अपनी क्रिया को निर्देशित और नियंत्रित करने में मदद करती है"],"explanationHi":"वाइगोत्स्की निजी वाणी को भीतर की ओर मुड़ी सामाजिक वाणी मानते थे जो व्यवहार की योजना बनाने और निर्देशित करने के लिए है, आंतरिक वाणी की ओर एक कदम; इसके विपरीत पियाजे ऐसे बोल को अहंकेंद्रित कहते थे।"},
  {"id":"cdp-pedagogy-subjects-1683","question":"A Class 7 student who normally uses past tenses correctly makes several tense errors when speaking nervously during the school assembly. In Chomsky’s terms, these errors are best described as reflecting:","options":["Limits of performance, not of competence","A gap in her linguistic competence","An error in her language acquisition device","Fossilisation of her interlanguage"],"answer":0,"explanation":"Competence is the underlying knowledge of language; performance is its use in real conditions, affected by nerves, fatigue or memory. Her usual accuracy shows the knowledge is there.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 7 की एक विद्यार्थी जो सामान्यतः भूतकाल का सही उपयोग करती है, विद्यालय की सभा में घबराहट से बोलते समय कई काल-संबंधी त्रुटियाँ करती है। चॉम्स्की की शब्दावली में इन त्रुटियों का सबसे अच्छा वर्णन किसे दर्शाने के रूप में होगा?","optionsHi":["निष्पादन (performance) की सीमाएँ, सक्षमता (competence) की नहीं","उसकी भाषाई सक्षमता में कमी","उसके भाषा अर्जन युक्ति (language acquisition device) में त्रुटि","उसकी अंतर्भाषा (interlanguage) का जड़ीभवन (fossilisation)"],"explanationHi":"सक्षमता भाषा का अंतर्निहित ज्ञान है; निष्पादन वास्तविक परिस्थितियों में उसका उपयोग है, जो घबराहट, थकान या स्मृति से प्रभावित होता है। उसकी सामान्य शुद्धता दिखाती है कि ज्ञान मौजूद है।"},
  {"id":"cdp-pedagogy-subjects-1684","question":"A teacher reads that, according to the critical period hypothesis, it becomes harder to acquire native-like pronunciation after puberty. The most sound conclusion for teaching Class 9 beginners is that:","options":["They can no longer learn English, so teaching should focus on Hindi","They should learn only through grammar rules, since acquisition stops at puberty","They can still reach high proficiency, though a home-language accent may remain","They will learn faster than young children in every area of language"],"answer":2,"explanation":"Age effects mainly concern ultimate pronunciation; adolescents often learn rules and vocabulary quickly and can become highly proficient, so neither giving up nor a rules-only approach follows.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"एक शिक्षक पढ़ता है कि क्रांतिक अवधि परिकल्पना (critical period hypothesis) के अनुसार यौवनारंभ के बाद मूल भाषी जैसा उच्चारण अर्जित करना कठिन हो जाता है। कक्षा 9 के आरंभिक अधिगमकर्ताओं को पढ़ाने के लिए सबसे उचित निष्कर्ष क्या है?","optionsHi":["वे अब अंग्रेज़ी नहीं सीख सकते, इसलिए शिक्षण हिंदी पर केंद्रित होना चाहिए","उन्हें केवल व्याकरण के नियमों से सीखना चाहिए, क्योंकि यौवनारंभ पर अर्जन रुक जाता है","वे अब भी उच्च दक्षता प्राप्त कर सकते हैं, यद्यपि घरेलू भाषा का लहजा बना रह सकता है","वे भाषा के हर क्षेत्र में छोटे बच्चों से तेज़ सीखेंगे"],"explanationHi":"आयु के प्रभाव मुख्यतः अंतिम उच्चारण से संबंधित हैं; किशोर प्रायः नियम और शब्दावली जल्दी सीखते हैं और अत्यंत दक्ष हो सकते हैं, इसलिए न तो हार मानना और न केवल नियमों वाला उपागम इससे निकलता है।"},
  {"id":"cdp-pedagogy-subjects-1685","question":"Anil studies English to clear a job interview at a bank. Fatima studies English because she loves English novels and wants to make friends with her pen pals in other countries. In Gardner’s terms, their motivation is respectively:","options":["Integrative and instrumental","Integrative and integrative","Intrinsic and extrinsic","Instrumental and integrative"],"answer":3,"explanation":"Instrumental motivation is learning a language for practical gain such as a job; integrative motivation is the wish to connect with the language’s speakers and culture.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"अनिल बैंक में नौकरी का साक्षात्कार पास करने के लिए अंग्रेज़ी पढ़ता है। फ़ातिमा अंग्रेज़ी इसलिए पढ़ती है क्योंकि उसे अंग्रेज़ी उपन्यास पसंद हैं और वह दूसरे देशों के अपने पत्र-मित्रों से दोस्ती करना चाहती है। गार्डनर की शब्दावली में उनकी अभिप्रेरणा क्रमशः है:","optionsHi":["समाकलनात्मक और साधनात्मक","समाकलनात्मक और समाकलनात्मक","आंतरिक और बाह्य","साधनात्मक और समाकलनात्मक"],"explanationHi":"साधनात्मक (instrumental) अभिप्रेरणा किसी व्यावहारिक लाभ, जैसे नौकरी, के लिए भाषा सीखना है; समाकलनात्मक (integrative) अभिप्रेरणा उस भाषा के वक्ताओं और संस्कृति से जुड़ने की इच्छा है।"},
  {"id":"cdp-pedagogy-subjects-1686","question":"A Class 6 teacher lets students choose their own books for weekly reading from a class library and share why they liked them. The main motivational principle behind this is that:","options":["Choice and personal interest build intrinsic motivation to read","Marks for reading increase the effort that students put in","Reading is enjoyable only when it is free of any discussion","Students read more when the teacher selects every book for them"],"answer":0,"explanation":"Autonomy and interest are key sources of intrinsic motivation; choosing books and sharing responses makes reading personally meaningful rather than a task done for marks.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 6 की एक शिक्षिका विद्यार्थियों को साप्ताहिक पठन के लिए कक्षा-पुस्तकालय से अपनी पुस्तकें स्वयं चुनने देती है और उन्हें यह बताने देती है कि उन्हें वे क्यों अच्छी लगीं। इसके पीछे का मुख्य अभिप्रेरणात्मक सिद्धांत है कि:","optionsHi":["पसंद और व्यक्तिगत रुचि पढ़ने की आंतरिक अभिप्रेरणा बनाते हैं","पढ़ने के अंक विद्यार्थियों द्वारा किए गए प्रयास को बढ़ाते हैं","पढ़ना तभी आनंददायक होता है जब वह किसी चर्चा से मुक्त हो","विद्यार्थी तब अधिक पढ़ते हैं जब शिक्षिका उनके लिए हर पुस्तक चुनती है"],"explanationHi":"स्वायत्तता और रुचि आंतरिक अभिप्रेरणा के प्रमुख स्रोत हैं; पुस्तकें चुनना और प्रतिक्रियाएँ साझा करना पठन को अंकों के लिए किए जाने वाले कार्य के बजाय व्यक्तिगत रूप से सार्थक बनाता है।"},
  {"id":"cdp-pedagogy-subjects-1687","question":"A Class 8 student keeps a vocabulary notebook of words she meets outside class, sets herself a weekly goal and checks her progress with an online quiz. These habits mainly show:","options":["Dependence on the teacher for all decisions about learning","Learner autonomy: taking charge of her own learning","A lack of interest in the classroom English lesson","Memorisation without any understanding of the words"],"answer":1,"explanation":"Autonomous learners set goals, choose strategies and monitor progress; teachers foster this because language learning continues far beyond the classroom.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 8 की एक विद्यार्थी कक्षा के बाहर मिले शब्दों की शब्दावली-कॉपी रखती है, अपने लिए साप्ताहिक लक्ष्य तय करती है और ऑनलाइन प्रश्नोत्तरी से अपनी प्रगति जाँचती है। ये आदतें मुख्यतः क्या दर्शाती हैं?","optionsHi":["अधिगम के बारे में सभी निर्णयों के लिए शिक्षक पर निर्भरता","अधिगमकर्ता स्वायत्तता: अपने अधिगम की बागडोर स्वयं सँभालना","कक्षा के अंग्रेज़ी पाठ में रुचि की कमी","शब्दों की समझ के बिना रटना"],"explanationHi":"स्वायत्त अधिगमकर्ता लक्ष्य तय करते हैं, रणनीतियाँ चुनते हैं और प्रगति की निगरानी करते हैं; शिक्षक इसे बढ़ावा देते हैं क्योंकि भाषा सीखना कक्षा से कहीं आगे तक चलता है।"},
  {"id":"cdp-pedagogy-subjects-1688","question":"To remember the English word ‘pane’, a Hindi-speaking student imagines rain water (‘paani’) streaming down a window pane. This is an example of:","options":["Learning through grammar-translation","Guessing meaning from context while reading","The keyword method, a memory strategy","Overgeneralising a rule of English"],"answer":2,"explanation":"The keyword method links a new word to a similar-sounding known word through a vivid image; Oxford classes such mnemonics as memory strategies.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"अंग्रेज़ी शब्द ‘pane’ याद रखने के लिए एक हिंदी भाषी विद्यार्थी कल्पना करती है कि वर्षा का पानी (‘paani’) खिड़की के शीशे (window pane) से बह रहा है। यह उदाहरण है:","optionsHi":["व्याकरण-अनुवाद से सीखने का","पढ़ते समय संदर्भ से अर्थ का अनुमान लगाने का","कुंजी-शब्द विधि (keyword method) का, जो एक स्मृति-रणनीति है","अंग्रेज़ी के किसी नियम के अति-सामान्यीकरण का"],"explanationHi":"कुंजी-शब्द विधि किसी नए शब्द को समान ध्वनि वाले ज्ञात शब्द से एक सजीव छवि के माध्यम से जोड़ती है; ऑक्सफ़ोर्ड ऐसी स्मरण-युक्तियों को स्मृति-रणनीतियों में वर्गीकृत करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1689","question":"Class 5 children read a play script aloud in parts with expression, using voice rather than costumes or memorised lines, and then perform it for another class. This technique, called readers’ theatre, mainly develops:","options":["Silent reading speed and quick scanning skills","Fluent, expressive reading through rehearsal","Memorisation of long passages for examinations","Handwriting through copying the play script"],"answer":1,"explanation":"Rehearsing a script for an audience gives a real reason for repeated reading, which builds fluency, phrasing and expression without the pressure of memorising.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कक्षा 5 के बच्चे नाटक की पटकथा को भावों के साथ भूमिकाओं में बाँटकर ज़ोर से पढ़ते हैं, वेशभूषा या रटे संवादों के बजाय आवाज़ का उपयोग करते हुए, और फिर उसे दूसरी कक्षा के सामने प्रस्तुत करते हैं। पाठकों का रंगमंच (readers' theatre) नामक यह तकनीक मुख्यतः क्या विकसित करती है?","optionsHi":["मौन पठन की गति और तेज़ी से सरसरी नज़र डालने के कौशल","पूर्वाभ्यास के माध्यम से धाराप्रवाह, भावपूर्ण पठन","परीक्षाओं के लिए लंबे गद्यांशों का स्मरण","नाटक की पटकथा उतारकर हस्तलेखन"],"explanationHi":"श्रोताओं के लिए पटकथा का पूर्वाभ्यास बार-बार पढ़ने का वास्तविक कारण देता है, जो रटने के दबाव के बिना प्रवाह, पदबंध-विभाजन और अभिव्यक्ति बनाता है।"},
  {"id":"cdp-pedagogy-subjects-1690","question":"After reading a short story about a girl who leaves her village for the city, a Class 9 teacher first asks, ‘How did the ending make you feel? Has anyone in your family made a similar move?’ This reflects:","options":["A translation approach that renders the story into Hindi","A grammar-based approach that uses the story to teach tenses","A biographical approach that studies the author’s life","A reader-response approach that values personal response"],"answer":3,"explanation":"Reader-response approaches start from the reader’s own engagement and experience, making literature personally meaningful before close analysis.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"एक ऐसी लड़की की छोटी कहानी पढ़ने के बाद जो अपना गाँव छोड़कर शहर जाती है, कक्षा 9 का शिक्षक पहले पूछता है, ‘अंत ने तुम्हें कैसा महसूस कराया? क्या तुम्हारे परिवार में किसी ने ऐसा स्थानांतरण किया है?’ यह किसे दर्शाता है?","optionsHi":["अनुवाद उपागम, जो कहानी को हिंदी में रूपांतरित करता है","व्याकरण-आधारित उपागम, जो कहानी का उपयोग कालों को पढ़ाने के लिए करता है","जीवनी-आधारित उपागम, जो लेखक के जीवन का अध्ययन करता है","पाठक-प्रतिक्रिया उपागम (reader-response approach), जो व्यक्तिगत प्रतिक्रिया को महत्व देता है"],"explanationHi":"पाठक-प्रतिक्रिया उपागम पाठक की अपनी सहभागिता और अनुभव से शुरू होते हैं, जिससे गहन विश्लेषण से पहले साहित्य व्यक्तिगत रूप से सार्थक बन जाता है।"},
  {"id":"cdp-pedagogy-subjects-1691","question":"A teacher tells Class 8 students, ‘Never begin a sentence with “And” or end one with a preposition.’ A linguist would say this rule reflects:","options":["A prescriptive view, saying how people should use the language","A descriptive view, recording how people actually use the language","A universal rule found in the grammar of all human languages","A rule of pronunciation rather than of grammar"],"answer":0,"explanation":"Prescriptive rules state what is considered correct, often by tradition; descriptive grammar records actual usage, in which such sentences are common in good writing.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"एक शिक्षक कक्षा 8 के विद्यार्थियों से कहता है, ‘कभी वाक्य ‘And’ से शुरू मत करो या किसी वाक्य का अंत पूर्वसर्ग (preposition) पर मत करो।’ भाषाविद् कहेगा कि यह नियम दर्शाता है:","optionsHi":["निर्देशात्मक (prescriptive) दृष्टिकोण, जो कहता है कि लोगों को भाषा का उपयोग कैसे करना चाहिए","वर्णनात्मक (descriptive) दृष्टिकोण, जो दर्ज करता है कि लोग वास्तव में भाषा का उपयोग कैसे करते हैं","सभी मानव भाषाओं के व्याकरण में पाया जाने वाला सार्वभौमिक नियम","व्याकरण का नहीं, बल्कि उच्चारण का नियम"],"explanationHi":"निर्देशात्मक नियम बताते हैं कि क्या सही माना जाता है, प्रायः परंपरा से; वर्णनात्मक व्याकरण वास्तविक प्रयोग दर्ज करता है, जिसमें अच्छे लेखन में ऐसे वाक्य आम हैं।"},
  {"id":"cdp-pedagogy-subjects-1692","question":"A Class 3 child who reads Hindi fluently writes English words exactly as they sound, such as ‘nite’ for ‘night’ and ‘sed’ for ‘said’. The most likely reason is that:","options":["Devanagari is spelt far more regularly than English","She has a learning disability affecting her memory for words","She has not learnt the English alphabet and letter names properly","She is careless and does not check her work"],"answer":0,"explanation":"Devanagari is largely phonetic, so she expects one spelling for each sound; English spelling is far less regular, so its patterns need explicit teaching.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कक्षा 3 की एक बच्ची जो हिंदी धाराप्रवाह पढ़ती है, अंग्रेज़ी शब्दों को ठीक वैसे ही लिखती है जैसे वे सुनाई देते हैं, जैसे ‘night’ के लिए ‘nite’ और ‘said’ के लिए ‘sed’। सबसे संभावित कारण है कि:","optionsHi":["देवनागरी की वर्तनी अंग्रेज़ी से कहीं अधिक नियमित है","उसे सीखने की ऐसी अक्षमता है जो शब्दों की उसकी स्मृति को प्रभावित करती है","उसने अंग्रेज़ी वर्णमाला और अक्षरों के नाम ठीक से नहीं सीखे हैं","वह लापरवाह है और अपना कार्य जाँचती नहीं"],"explanationHi":"देवनागरी काफ़ी हद तक ध्वन्यात्मक है, इसलिए वह हर ध्वनि के लिए एक वर्तनी की अपेक्षा करती है; अंग्रेज़ी की वर्तनी कहीं कम नियमित है, इसलिए उसके पैटर्नों को स्पष्ट रूप से पढ़ाना पड़ता है।"},
  {"id":"cdp-pedagogy-subjects-1693","question":"Many Class 9 students give every syllable of an English sentence almost equal weight, which makes their speech hard to follow for some listeners. The teacher plans work on sentence stress and weak forms. The best explanation of the difficulty is that:","options":["Indian learners cannot hear differences in loudness between syllables","English has fewer vowel sounds than most Indian languages, so all sound alike","English is stress-timed; many Indian languages are syllable-timed","The students have not been taught enough grammar to group words into phrases"],"answer":2,"explanation":"English rhythm depends on stressed syllables with unstressed ones reduced; carrying over a more syllable-timed rhythm affects intelligibility, so stress and weak forms need attention.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 9 के बहुत-से विद्यार्थी अंग्रेज़ी वाक्य के हर शब्दांश को लगभग समान बल देते हैं, जिससे उनका बोलना कुछ श्रोताओं के लिए समझना कठिन हो जाता है। शिक्षिका वाक्य-बलाघात (sentence stress) और दुर्बल रूपों (weak forms) पर काम की योजना बनाती है। इस कठिनाई की सबसे अच्छी व्याख्या है कि:","optionsHi":["भारतीय अधिगमकर्ता शब्दांशों के बीच ज़ोर के अंतर को सुन नहीं सकते","अंग्रेज़ी में अधिकांश भारतीय भाषाओं से कम स्वर ध्वनियाँ हैं, इसलिए सब एक-सी लगती हैं","अंग्रेज़ी बलाघात-समयबद्ध (stress-timed) है; अनेक भारतीय भाषाएँ शब्दांश-समयबद्ध (syllable-timed) हैं","विद्यार्थियों को शब्दों को पदबंधों में समूहित करने लायक पर्याप्त व्याकरण नहीं पढ़ाया गया है"],"explanationHi":"अंग्रेज़ी की लय बलयुक्त शब्दांशों पर निर्भर करती है जिनमें बलहीन शब्दांश घट जाते हैं; अधिक शब्दांश-समयबद्ध लय को साथ ले आना बोधगम्यता को प्रभावित करता है, इसलिए बलाघात और दुर्बल रूपों पर ध्यान चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1694","question":"In a Class 7 section of 55 students, the teacher wants to assess speaking regularly. Which practice is most feasible and valid?","options":["Giving a written test on spoken English phrases","Observing a few groups each week with a checklist","Asking each student to recite a poem once a year","Assessing speaking only through the final examination"],"answer":1,"explanation":"Rotating observation of group work with clear criteria gives continuous, valid information on real speaking in a large class; written tests and recitations do not assess spontaneous speaking.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 7 के 55 विद्यार्थियों के अनुभाग में शिक्षिका बोलने का नियमित आकलन करना चाहती है। कौन-सा अभ्यास सबसे व्यावहारिक और वैध है?","optionsHi":["बोली जाने वाली अंग्रेज़ी के पदबंधों पर लिखित परीक्षा देना","हर सप्ताह कुछ समूहों का जाँच-सूची के साथ अवलोकन करना","हर विद्यार्थी से वर्ष में एक बार कविता सुनवाना","बोलने का आकलन केवल अंतिम परीक्षा से करना"],"explanationHi":"स्पष्ट मानदंडों के साथ समूह-कार्य का बारी-बारी से अवलोकन बड़ी कक्षा में वास्तविक बोलने के बारे में सतत, वैध जानकारी देता है; लिखित परीक्षाएँ और कविता-पाठ स्वतःस्फूर्त बोलने का आकलन नहीं करते।"},
  {"id":"cdp-pedagogy-subjects-1695","question":"A Class 6 teacher sets up a weekly ‘book talk’ in which students briefly recommend a book they enjoyed and classmates may ask questions. Besides speaking practice, the main benefit is that it:","options":["Lets the teacher rank students by how many books they read","Tests students’ memory of the book’s exact words","Replaces the need for any reading in class","Builds a reading culture through peers’ recommendations"],"answer":3,"explanation":"Peer recommendations are powerful motivators; talking about books makes reading social and visible, encouraging others to pick up books.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 6 की एक शिक्षिका साप्ताहिक ‘पुस्तक चर्चा’ आयोजित करती है जिसमें विद्यार्थी संक्षेप में कोई ऐसी पुस्तक सुझाते हैं जो उन्हें अच्छी लगी और सहपाठी प्रश्न पूछ सकते हैं। बोलने के अभ्यास के अलावा मुख्य लाभ यह है कि यह:","optionsHi":["शिक्षिका को इस आधार पर विद्यार्थियों को क्रम देने देता है कि उन्होंने कितनी पुस्तकें पढ़ीं","पुस्तक के सटीक शब्दों की विद्यार्थियों की स्मृति की परीक्षा लेता है","कक्षा में किसी भी पठन की आवश्यकता की जगह ले लेता है","सहपाठियों की अनुशंसाओं से पठन-संस्कृति बनाता है"],"explanationHi":"सहपाठियों की अनुशंसाएँ शक्तिशाली अभिप्रेरक होती हैं; पुस्तकों के बारे में बात करना पठन को सामाजिक और दृश्य बनाता है, जिससे दूसरे पुस्तकें उठाने को प्रोत्साहित होते हैं।"},
  {"id":"cdp-pedagogy-subjects-1696","question":"Consider these statements comparing Krashen’s ‘i+1’ and Vygotsky’s ‘zone of proximal development’: I. Both suggest that learning happens just beyond the learner’s current level. II. The ZPD stresses help from a more knowledgeable other, while i+1 stresses comprehensible input. III. Both see the learner as a passive receiver of knowledge. Which are correct?","options":["II and III only","I and II only","I and III only","I, II and III"],"answer":1,"explanation":"Both ideas place learning slightly above present ability, but Vygotsky emphasises assisted performance in social interaction and Krashen emphasises understood input. Neither sees the learner as passive.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"क्रैशेन के ‘i+1’ और वाइगोत्स्की के ‘निकटस्थ विकास का क्षेत्र’ की तुलना करने वाले इन कथनों पर विचार कीजिए: I. दोनों सुझाते हैं कि अधिगम अधिगमकर्ता के वर्तमान स्तर से ठीक आगे होता है। II. ZPD अधिक जानकार व्यक्ति की सहायता पर बल देता है, जबकि i+1 बोधगम्य निवेश पर बल देता है। III. दोनों अधिगमकर्ता को ज्ञान का निष्क्रिय ग्राही मानते हैं। कौन-से सही हैं?","optionsHi":["केवल II और III","केवल I और II","केवल I और III","I, II और III"],"explanationHi":"दोनों विचार अधिगम को वर्तमान क्षमता से थोड़ा ऊपर रखते हैं, पर वाइगोत्स्की सामाजिक अंतःक्रिया में सहायता-प्राप्त निष्पादन पर बल देते हैं और क्रैशेन समझे गए निवेश पर। दोनों में से कोई अधिगमकर्ता को निष्क्रिय नहीं मानता।"},
  {"id":"cdp-pedagogy-subjects-1697","question":"A lesson in the prescribed Class 6 reader is long and difficult for students in a rural school. Which adaptation is most appropriate?","options":["Build background, gloss key words and split the text into parts","Skip the lesson, since it is not suited to these students","Read the lesson aloud and dictate the answers to all the questions","Translate the whole lesson into the home language and teach only that"],"answer":0,"explanation":"Teachers adapt materials to learners: building background, supporting vocabulary and chunking keep the text and its learning while making it accessible.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"ग्रामीण विद्यालय के विद्यार्थियों के लिए निर्धारित कक्षा 6 की पाठ्यपुस्तक का एक पाठ लंबा और कठिन है। कौन-सा अनुकूलन सबसे उपयुक्त है?","optionsHi":["पृष्ठभूमि बनाना, मुख्य शब्दों के अर्थ देना और पाठ को भागों में बाँटना","पाठ को छोड़ देना, क्योंकि वह इन विद्यार्थियों के अनुकूल नहीं है","पाठ को ज़ोर से पढ़ना और सभी प्रश्नों के उत्तर लिखवा देना","पूरे पाठ का घरेलू भाषा में अनुवाद करना और केवल वही पढ़ाना"],"explanationHi":"शिक्षक सामग्री को अधिगमकर्ताओं के अनुसार ढालते हैं: पृष्ठभूमि बनाना, शब्दावली में सहायता देना और पाठ को खंडों में बाँटना पाठ और उसके अधिगम को बनाए रखते हुए उसे सुलभ बनाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1698","question":"In a programme for tribal children in Odisha, children begin literacy in their home language (such as Kui or Saora), then gradually move into Odia and later English, using what they know to learn the new. This model is:","options":["Submersion education in the state language","Subtractive bilingual education","Mother-tongue-based multilingual education","English-only immersion from Class 1"],"answer":2,"explanation":"MTB-MLE starts with the language children understand, builds strong literacy in it and then bridges to other languages, applying the principle of moving from the known to the unknown.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"ओडिशा में आदिवासी बच्चों के एक कार्यक्रम में बच्चे अपनी घरेलू भाषा (जैसे कुई या सौरा) में साक्षरता शुरू करते हैं, फिर धीरे-धीरे ओड़िया और बाद में अंग्रेज़ी की ओर बढ़ते हैं, जो वे जानते हैं उसका उपयोग नया सीखने के लिए करते हुए। यह मॉडल है:","optionsHi":["राज्य की भाषा में निमज्जन शिक्षा","ह्रासी द्विभाषी शिक्षा","मातृभाषा-आधारित बहुभाषी शिक्षा (MTB-MLE)","कक्षा 1 से केवल अंग्रेज़ी में निमज्जन"],"explanationHi":"MTB-MLE उस भाषा से शुरू होती है जो बच्चे समझते हैं, उसमें सशक्त साक्षरता बनाती है और फिर अन्य भाषाओं तक सेतु बनाती है, ज्ञात से अज्ञात की ओर बढ़ने के सिद्धांत को लागू करते हुए।"},
  {"id":"cdp-pedagogy-subjects-1699","question":"A Class 1 teacher writes a thank-you letter to the school gardener on chart paper while the children suggest what to say; she thinks aloud about spacing, capital letters and spelling as she writes their words. This practice is called:","options":["Guided writing","Independent writing","Copy writing","Shared writing"],"answer":3,"explanation":"In shared writing children compose together and the teacher acts as scribe, modelling the conventions of writing; in guided writing children hold the pen with teacher support.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कक्षा 1 की एक शिक्षिका चार्ट पेपर पर विद्यालय के माली को धन्यवाद-पत्र लिखती है जबकि बच्चे सुझाते हैं कि क्या कहना है; वह बच्चों के शब्द लिखते समय दूरी, बड़े अक्षरों और वर्तनी के बारे में ज़ोर से सोचती है। इस अभ्यास को क्या कहते हैं?","optionsHi":["निर्देशित लेखन (Guided writing)","स्वतंत्र लेखन (Independent writing)","उतारकर लेखन (Copy writing)","साझा लेखन (Shared writing)"],"explanationHi":"साझा लेखन में बच्चे मिलकर रचना करते हैं और शिक्षिका लेखक का काम करती है, लेखन की परिपाटियों का आदर्श प्रस्तुत करते हुए; निर्देशित लेखन में बच्चे शिक्षिका की सहायता से स्वयं कलम पकड़ते हैं।"},
  {"id":"cdp-pedagogy-subjects-1700","question":"A Class 1 teacher splits ‘cat’ into /k/ + ‘at’ and then makes ‘hat’, ‘mat’ and ‘bat’ by changing only the first sound. The units she is working with are:","options":["Syllables","Morphemes","Consonant digraphs","Onset and rime"],"answer":3,"explanation":"The onset is the first consonant sound(s) of a syllable and the rime is the vowel with what follows; word families like -at use rime patterns to read many words quickly.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कक्षा 1 की एक शिक्षिका ‘cat’ को /k/ + ‘at’ में बाँटती है और फिर केवल पहली ध्वनि बदलकर ‘hat’, ‘mat’ और ‘bat’ बनाती है। वह जिन इकाइयों के साथ काम कर रही है वे हैं:","optionsHi":["शब्दांश (Syllables)","रूपिम (Morphemes)","व्यंजन युग्म (Consonant digraphs)","आरंभ और अंत्य (Onset and rime)"],"explanationHi":"onset किसी शब्दांश की पहली व्यंजन ध्वनि(याँ) है और rime स्वर तथा उसके बाद का भाग है; -at जैसे शब्द-परिवार बहुत-से शब्दों को जल्दी पढ़ने के लिए rime के पैटर्नों का उपयोग करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1701","question":"A Class 5 child reads 4,05,000 as ‘four lakh five hundred’. What does this most likely show?","options":["She misread the 5's place; it is in thousands, so the number is four lakh five thousand","She does not know the word ‘lakh’ and uses it for any number with six digits","She has mixed up the Indian and international systems of numeration and their commas","She is careless and needs to read each number more slowly, pointing to every single digit"],"answer":0,"explanation":"In 4,05,000 the 5 is in the thousands place, so the number is four lakh five thousand. A place-value chart with lakhs, ten thousands and thousands helps her read each period by place.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक बच्ची 4,05,000 को ‘चार लाख पाँच सौ’ पढ़ती है। यह सबसे संभावित रूप से क्या दर्शाता है?","optionsHi":["उसने 5 का स्थान गलत पढ़ा; वह हज़ार में है, इसलिए संख्या चार लाख पाँच हज़ार है","वह ‘लाख’ शब्द नहीं जानती और उसे छह अंकों वाली किसी भी संख्या के लिए इस्तेमाल करती है","उसने संख्या-पद्धति की भारतीय और अंतर्राष्ट्रीय प्रणालियों और उनके अल्पविरामों को आपस में मिला दिया है","वह लापरवाह है और उसे हर संख्या को धीरे पढ़ना चाहिए, हर अंक की ओर इशारा करते हुए"],"explanationHi":"4,05,000 में 5 हज़ार के स्थान पर है, इसलिए संख्या चार लाख पाँच हज़ार है। लाख, दस हज़ार और हज़ार वाली स्थानमान सारणी उसे हर अवधि को स्थान के अनुसार पढ़ने में मदद करती है।"},
  {"id":"cdp-pedagogy-subjects-1702","question":"A Class 4 child says 9,999 is greater than 10,001 ‘because 9 is bigger than 1’. What has the child not understood?","options":["How to read four-digit and five-digit numbers aloud using their place names","That numbers are compared first by number of digits, then place by place from the left","The names of the places, such as thousands and ten thousands, in large numbers","That numbers must be compared digit by digit starting from the ones place on the right"],"answer":1,"explanation":"A five-digit number is always greater than a four-digit number. Comparing first digits works only when both numbers have the same number of digits.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 का एक बच्चा कहता है कि 9,999, 10,001 से बड़ा है ‘क्योंकि 9, 1 से बड़ा है’। बच्चे ने क्या नहीं समझा है?","optionsHi":["चार अंकों और पाँच अंकों की संख्याओं को उनके स्थान-नामों के साथ ज़ोर से कैसे पढ़ा जाता है","कि संख्याओं की तुलना पहले अंकों की संख्या से, फिर बाईं ओर से स्थान-दर-स्थान की जाती है","बड़ी संख्याओं में हज़ार और दस हज़ार जैसे स्थानों के नाम","कि संख्याओं की तुलना दाईं ओर इकाई के स्थान से शुरू करके अंक-दर-अंक करनी होती है"],"explanationHi":"पाँच अंकों की संख्या हमेशा चार अंकों की संख्या से बड़ी होती है। पहले अंकों की तुलना तभी काम करती है जब दोनों संख्याओं में अंकों की संख्या समान हो।"},
  {"id":"cdp-pedagogy-subjects-1703","question":"Rounding 346 to the nearest hundred, a Class 5 child first rounds it to 350 and then rounds 350 to 400. What is the best response?","options":["Accept it, since each step follows the rounding rule correctly and the final answer is a hundred","Tell her to always round up whenever a 5 appears at any stage of the rounding","Ask her to place 346 on a number line between 300 and 400 and see which it is nearer","Ask her to learn the rounding rule again and write it ten times in her notebook"],"answer":2,"explanation":"346 is 46 away from 300 and 54 away from 400, so it rounds to 300. Rounding in steps (chain rounding) adds error; the number line shows what ‘nearest’ means.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"346 को निकटतम सैकड़े में पूर्णांकित करते हुए कक्षा 5 की एक बच्ची पहले उसे 350 करती है और फिर 350 को 400 करती है। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["इसे स्वीकार करना, क्योंकि हर चरण पूर्णांकन-नियम का सही पालन करता है और अंतिम उत्तर सैकड़ा है","उससे कहना कि पूर्णांकन के किसी भी चरण में जब भी 5 आए तो हमेशा ऊपर पूर्णांकित करे","उससे 346 को संख्या-रेखा पर 300 और 400 के बीच रखने को कहना और देखना कि वह किसके निकट है","उससे पूर्णांकन का नियम फिर से सीखने और अपनी कॉपी में दस बार लिखने को कहना"],"explanationHi":"346, 300 से 46 दूर और 400 से 54 दूर है, इसलिए वह 300 पर पूर्णांकित होता है। चरणों में पूर्णांकन (शृंखला पूर्णांकन) त्रुटि जोड़ता है; संख्या-रेखा दिखाती है कि ‘निकटतम’ का क्या अर्थ है।"},
  {"id":"cdp-pedagogy-subjects-1704","question":"A Class 5 child works out 99 × 7 in her head as ‘700 − 7 = 693’. What is the best response from the teacher?","options":["Ask her to use the standard written algorithm instead, since it is safer and easier to check","Tell her that mental methods are not allowed in exams, so she must always show working","Mark it correct and move on without comment, since the answer she got is right","Ask her to explain her method and link it to (100 − 1) × 7, the distributive property"],"answer":3,"explanation":"Her strategy rests on the distributive property. Making it explicit helps her and the class use it on purpose, and lays groundwork for algebra.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"कक्षा 5 की एक बच्ची 99 × 7 को मन ही मन ‘700 − 7 = 693’ के रूप में हल करती है। शिक्षिका की सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["उससे इसके बजाय मानक लिखित विधि का उपयोग करने को कहना, क्योंकि वह अधिक सुरक्षित और जाँचने में आसान है","उससे कहना कि परीक्षाओं में मानसिक विधियाँ अनुमत नहीं हैं, इसलिए उसे हमेशा कार्य दिखाना होगा","बिना टिप्पणी के सही चिह्नित करके आगे बढ़ जाना, क्योंकि उसे जो उत्तर मिला वह सही है","उससे अपनी विधि समझाने और उसे (100 − 1) × 7, यानी वितरण गुण (distributive property), से जोड़ने को कहना"],"explanationHi":"उसकी रणनीति वितरण गुण पर टिकी है। उसे स्पष्ट करने से उसे और कक्षा को उसे सोच-समझकर उपयोग करने में मदद मिलती है, और बीजगणित की नींव पड़ती है।"},
  {"id":"cdp-pedagogy-subjects-1705","question":"A Class 5 child writes 1/3 + 1/3 + 1/3 = 3/9 = 1/3. Which question is most likely to create a useful conflict in her thinking?","options":["‘How many thirds of a roti make one whole roti?’","‘What is the LCM of 3 and 9, and how do you use it here?’","‘Can you simplify 3/9 again to check your final answer?’","‘What is 1/3 + 1/3? Write it the same way as before.’"],"answer":0,"explanation":"She knows that three thirds make a whole, yet her method gives one third. Facing that contradiction pushes her to rethink adding tops and bottoms, more than repeating the rule would.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक बच्ची लिखती है 1/3 + 1/3 + 1/3 = 3/9 = 1/3। कौन-सा प्रश्न उसकी सोच में उपयोगी द्वंद्व पैदा करने की सबसे अधिक संभावना रखता है?","optionsHi":["‘एक रोटी के कितने तिहाई मिलकर एक पूरी रोटी बनाते हैं?’","‘3 और 9 का LCM क्या है, और तुम इसे यहाँ कैसे उपयोग करती हो?’","‘क्या तुम अपने अंतिम उत्तर की जाँच के लिए 3/9 को फिर सरल कर सकती हो?’","‘1/3 + 1/3 कितना है? इसे वैसे ही लिखो जैसे पहले लिखा था।’"],"explanationHi":"वह जानती है कि तीन तिहाई मिलकर पूर्ण बनाते हैं, फिर भी उसकी विधि एक तिहाई देती है। उस विरोधाभास का सामना करना उसे अंश और हर जोड़ने पर पुनर्विचार करने के लिए धकेलता है, नियम दोहराने से कहीं अधिक।"},
  {"id":"cdp-pedagogy-subjects-1706","question":"A Class 2 child says a tall, thin glass holds more water than a short, wide bowl ‘because it is taller’. What is the most suitable activity?","options":["Tell her clearly that height does not matter and that wide containers hold more","Let her predict, then fill the glass and pour it into the bowl to compare","Show her the capacity marks on a measuring jug and explain what millilitres mean","Ask her to draw both containers carefully side by side and compare the drawings"],"answer":1,"explanation":"Young children judge capacity by height. Predicting and then pouring from one into the other gives direct evidence and builds the idea of capacity as the amount a container holds.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 2 की एक बच्ची कहती है कि लंबे, पतले गिलास में छोटे, चौड़े कटोरे से अधिक पानी आता है ‘क्योंकि वह ज़्यादा ऊँचा है’। सबसे उपयुक्त गतिविधि क्या है?","optionsHi":["उससे स्पष्ट कहना कि ऊँचाई मायने नहीं रखती और चौड़े बर्तनों में अधिक आता है","उसे अनुमान लगाने देना, फिर गिलास भरकर कटोरे में उँडेलकर तुलना करना","उसे मापक जग पर धारिता के निशान दिखाना और समझाना कि मिलीलीटर का क्या अर्थ है","उससे दोनों बर्तनों को साथ-साथ ध्यान से बनाने और चित्रों की तुलना करने को कहना"],"explanationHi":"छोटे बच्चे धारिता को ऊँचाई से आँकते हैं। अनुमान लगाना और फिर एक से दूसरे में उँडेलना प्रत्यक्ष साक्ष्य देता है और धारिता के विचार को, यानी बर्तन जितना भरता है उसकी मात्रा के रूप में, बनाता है।"},
  {"id":"cdp-pedagogy-subjects-1707","question":"To find the time from 9:40 to 11:15, which tool best supports Class 4 children's reasoning?","options":["A rule to subtract 9:40 from 11:15 directly, as children do with decimal numbers","A clock with only an hour hand, so that children can count the hours that pass","An open number line jumping from 9:40 to 10:00, then to 11:00, then to 11:15","A calendar on which children mark the start and end times and count the gaps"],"answer":2,"explanation":"Jumping to the next hour gives 20 + 60 + 15 = 95 minutes, which is 1 hour 35 minutes. Treating times as decimals (11.15 − 9.40) gives a wrong answer because an hour has 60 minutes, not 100.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"9:40 से 11:15 तक का समय निकालने में कक्षा 4 के बच्चों की तर्क-शक्ति को कौन-सा उपकरण सबसे अच्छी तरह सहारा देता है?","optionsHi":["9:40 को 11:15 में से सीधे घटाने का नियम, जैसा बच्चे दशमलव संख्याओं के साथ करते हैं","केवल घंटे की सुई वाली घड़ी, ताकि बच्चे बीतने वाले घंटे गिन सकें","खुली संख्या-रेखा जिस पर 9:40 से 10:00, फिर 11:00, फिर 11:15 तक छलाँगें हों","कैलेंडर जिस पर बच्चे आरंभ और अंत के समय चिह्नित करें और अंतर गिनें"],"explanationHi":"अगले घंटे तक छलाँग लगाने से 20 + 60 + 15 = 95 मिनट मिलते हैं, यानी 1 घंटा 35 मिनट। समय को दशमलव मानने (11.15 − 9.40) से गलत उत्तर आता है क्योंकि एक घंटे में 60 मिनट होते हैं, 100 नहीं।"},
  {"id":"cdp-pedagogy-subjects-1708","question":"The morning temperature in Drass is −12 °C and it rises by 7 °C by noon. A Class 6 student says the noon temperature is −19 °C. Which response is best?","options":["Tell her to subtract the smaller number from the bigger number and keep the minus sign","Tell her that a rise always makes the number bigger, so the answer must be +19 °C","Ask her to add 12 and 7 again carefully and check her addition on her fingers","Ask her to start at −12 on a thermometer drawn as a number line and move 7 up"],"answer":3,"explanation":"Rising by 7 from −12 moves towards zero, reaching −5 °C. She added the sizes and kept the minus sign. A vertical number line makes the direction of change clear.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"द्रास में सुबह का तापमान −12 °C है और दोपहर तक वह 7 °C बढ़ जाता है। कक्षा 6 की एक विद्यार्थी कहती है कि दोपहर का तापमान −19 °C है। कौन-सी प्रतिक्रिया सबसे अच्छी है?","optionsHi":["उससे कहना कि छोटी संख्या को बड़ी में से घटाए और ऋण चिह्न रखे","उससे कहना कि बढ़ने पर संख्या हमेशा बड़ी होती है, इसलिए उत्तर +19 °C होना चाहिए","उससे 12 और 7 को फिर ध्यान से जोड़ने और उँगलियों पर अपना जोड़ जाँचने को कहना","उससे संख्या-रेखा के रूप में बने थर्मामीटर पर −12 से शुरू करके 7 ऊपर जाने को कहना"],"explanationHi":"−12 से 7 बढ़ने पर शून्य की ओर बढ़ते हुए −5 °C आता है। उसने आकार जोड़ दिए और ऋण चिह्न रख लिया। ऊर्ध्वाधर संख्या-रेखा परिवर्तन की दिशा स्पष्ट करती है।"},
  {"id":"cdp-pedagogy-subjects-1709","question":"Before setting a Class 7 maths test, a teacher prepares a blueprint. What is its main purpose?","options":["To balance the test across content, objectives, question types and marks","To decide the pass marks and the grade boundaries before the test is set","To list the students who will take the test and their seating arrangement","To make the test as difficult as possible so that only the best can score full"],"answer":0,"explanation":"A blueprint is a planning grid that ensures a test covers the intended content and objectives in the right proportion, which supports the test's validity.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की गणित परीक्षा बनाने से पहले शिक्षिका एक ब्लूप्रिंट (नीलपत्र) तैयार करती है। इसका मुख्य उद्देश्य क्या है?","optionsHi":["परीक्षा को विषय-वस्तु, उद्देश्यों, प्रश्न-प्रकारों और अंकों में संतुलित करना","परीक्षा बनाने से पहले उत्तीर्ण अंक और ग्रेड-सीमाएँ तय करना","परीक्षा देने वाले विद्यार्थियों और उनकी बैठक-व्यवस्था की सूची बनाना","परीक्षा को यथासंभव कठिन बनाना ताकि केवल सर्वश्रेष्ठ ही पूरे अंक पा सकें"],"explanationHi":"ब्लूप्रिंट एक योजना-सारणी है जो सुनिश्चित करती है कि परीक्षा इच्छित विषय-वस्तु और उद्देश्यों को सही अनुपात में समेटे, जो परीक्षा की वैधता में सहायक है।"},
  {"id":"cdp-pedagogy-subjects-1710","question":"A Class 3 maths test has long word problems in complex English. A child in a Hindi-medium school scores poorly, but solves the same problems orally in Hindi. Which quality of the test is most affected?","options":["Its reliability, because the papers were marked by different teachers in the school","Its validity as a maths test, since it measures English reading more than maths","Its objectivity, because the word problems were open-ended and hard to mark","Its practicality, because the long problems took too much time to set and mark"],"answer":1,"explanation":"A test is valid when it measures what it intends to measure. Heavy language demands mean the scores reflect reading ability, not maths understanding.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"कक्षा 3 की एक गणित परीक्षा में जटिल अंग्रेज़ी में लंबे शाब्दिक प्रश्न हैं। हिंदी माध्यम के विद्यालय का एक बच्चा कम अंक पाता है, पर वही प्रश्न हिंदी में मौखिक रूप से हल कर लेता है। परीक्षा का कौन-सा गुण सबसे अधिक प्रभावित है?","optionsHi":["उसकी विश्वसनीयता, क्योंकि विद्यालय में अलग-अलग शिक्षकों ने उत्तर-पत्र जाँचे","गणित की परीक्षा के रूप में उसकी वैधता, क्योंकि वह गणित से अधिक अंग्रेज़ी पठन को मापती है","उसकी वस्तुनिष्ठता, क्योंकि शाब्दिक प्रश्न खुले और जाँचने में कठिन थे","उसकी व्यावहारिकता, क्योंकि लंबे प्रश्न बनाने और जाँचने में बहुत समय लगा"],"explanationHi":"परीक्षा तब वैध होती है जब वह वही मापे जो मापना चाहती है। भाषा की भारी माँगों का अर्थ है कि अंक गणित की समझ के बजाय पठन-क्षमता दर्शाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1711","question":"Two teachers give very different marks to the same student's answer on an open-ended maths problem. Which step would most improve the reliability of marking?","options":["Giving only multiple-choice questions from now on, so that marking is automatic","Letting the more senior teacher's marks count, since she has more experience","Agreeing on a rubric with clear criteria and sample answers before marking","Averaging the two marks without any discussion, so that neither teacher is overruled"],"answer":2,"explanation":"Reliability means consistent scores across markers and occasions. A shared rubric with examples reduces differences between markers while keeping open-ended tasks.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"दो शिक्षक एक खुले गणित-प्रश्न पर एक ही विद्यार्थी के उत्तर को बहुत भिन्न अंक देते हैं। कौन-सा कदम अंकन की विश्वसनीयता को सबसे अधिक सुधारेगा?","optionsHi":["अब से केवल बहुविकल्पीय प्रश्न देना, ताकि अंकन स्वचालित हो","वरिष्ठ शिक्षिका के अंकों को मान्य करना, क्योंकि उसे अधिक अनुभव है","अंकन से पहले स्पष्ट मानदंडों और नमूना-उत्तरों वाले रूब्रिक पर सहमत होना","बिना चर्चा के दोनों अंकों का औसत लेना, ताकि किसी शिक्षक की बात न कटे"],"explanationHi":"विश्वसनीयता का अर्थ है अंकनकर्ताओं और अवसरों में सुसंगत अंक। उदाहरणों वाला साझा रूब्रिक खुले कार्यों को बनाए रखते हुए अंकनकर्ताओं के बीच अंतर घटाता है।"},
  {"id":"cdp-pedagogy-subjects-1712","question":"A Class 9 student proves that the diagonals of a parallelogram bisect each other using congruent triangles, and explains how a definition differs from a theorem. At which Van Hiele level is she working?","options":["Analysis","Informal deduction","Rigour","Deduction"],"answer":3,"explanation":"Building formal proofs within an axiomatic system, and understanding the roles of definitions and theorems, marks the deduction level. Rigour involves comparing different axiomatic systems.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 9 की एक विद्यार्थी सर्वांगसम त्रिभुजों का उपयोग करके सिद्ध करती है कि समांतर चतुर्भुज के विकर्ण एक-दूसरे को समद्विभाजित करते हैं, और समझाती है कि परिभाषा प्रमेय से कैसे भिन्न है। वह वैन हील के किस स्तर पर कार्य कर रही है?","optionsHi":["विश्लेषण","अनौपचारिक निगमन","कठोरता (Rigour)","निगमन (Deduction)"],"explanationHi":"अभिगृहीत-पद्धति के भीतर औपचारिक उपपत्तियाँ बनाना, और परिभाषाओं तथा प्रमेयों की भूमिकाओं को समझना निगमन-स्तर का चिह्न है। कठोरता में विभिन्न अभिगृहीत-पद्धतियों की तुलना शामिल है।"},
  {"id":"cdp-pedagogy-subjects-1713","question":"A Class 11 student compares triangles drawn on a flat sheet with triangles drawn on a ball and explains why their angle sums differ, depending on the axioms each geometry uses. This reasoning belongs to which Van Hiele level?","options":["Rigour","Deduction","Informal deduction","Analysis"],"answer":0,"explanation":"At rigour, the highest level, students compare different axiomatic systems, such as Euclidean and spherical geometry. School geometry seldom goes beyond deduction.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 11 का एक विद्यार्थी समतल पन्ने पर खींचे त्रिभुजों की तुलना गेंद पर खींचे त्रिभुजों से करता है और समझाता है कि उनके कोणों के योग भिन्न क्यों हैं, प्रत्येक ज्यामिति द्वारा प्रयुक्त अभिगृहीतों पर निर्भर करते हुए। यह तर्क वैन हील के किस स्तर का है?","optionsHi":["कठोरता (Rigour)","निगमन (Deduction)","अनौपचारिक निगमन","विश्लेषण"],"explanationHi":"कठोरता के सर्वोच्च स्तर पर विद्यार्थी विभिन्न अभिगृहीत-पद्धतियों, जैसे यूक्लिडीय और गोलीय ज्यामिति, की तुलना करते हैं। विद्यालयी ज्यामिति शायद ही कभी निगमन से आगे जाती है।"},
  {"id":"cdp-pedagogy-subjects-1714","question":"According to the NCF 2005 position paper on mathematics, the school mathematics curriculum ‘disappoints’ which groups?","options":["Only the children who are weak in mathematics and keep failing to clear the examinations","Only the teachers, who must complete a heavy syllabus within the academic year","Both a talented few who are not challenged and a majority who find it hard and drop out","Only the parents, who want their children to score higher marks in board exams"],"answer":2,"explanation":"The paper describes a curriculum that fails both the able few, who find it unchallenging, and the many who drop out of meaningful engagement. Both are among its core problems.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT","questionHi":"गणित पर NCF 2005 के स्थिति-पत्र के अनुसार, विद्यालयी गणित पाठ्यचर्या किन समूहों को ‘निराश’ करती है?","optionsHi":["केवल उन बच्चों को जो गणित में कमज़ोर हैं और परीक्षाएँ पास करने में बार-बार असफल रहते हैं","केवल शिक्षकों को, जिन्हें शैक्षणिक वर्ष के भीतर भारी पाठ्यक्रम पूरा करना होता है","दोनों को: प्रतिभाशाली कुछ को जिन्हें चुनौती नहीं मिलती और बहुसंख्यकों को जिन्हें यह कठिन लगता है और जो पढ़ाई छोड़ देते हैं","केवल अभिभावकों को, जो चाहते हैं कि उनके बच्चे बोर्ड परीक्षाओं में अधिक अंक पाएँ"],"explanationHi":"यह पत्र ऐसी पाठ्यचर्या का वर्णन करता है जो सक्षम कुछ को, जिन्हें वह चुनौतीहीन लगती है, और अनेकों को, जो सार्थक सहभागिता से बाहर हो जाते हैं, दोनों को विफल करती है। दोनों इसकी मूल समस्याओं में हैं।"},
  {"id":"cdp-pedagogy-subjects-1715","question":"How does NCF 2005 describe the role of mathematics at the upper primary stage?","options":["Students mainly practise the four operations on much larger numbers and in longer word problems","Students first taste the power of maths through abstractions like algebra that compress earlier work","Students should begin learning formal two-column proofs in geometry, as is done in later classes","Students should study mathematics as a separate discipline with its own formal structure"],"answer":1,"explanation":"NCF 2005 sees the upper primary stage as the point where abstract ideas like algebraic notation start to summarise and extend earlier arithmetic. Seeing mathematics as a discipline with its own structure belongs to the secondary stage.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"NCF 2005 उच्च प्राथमिक स्तर पर गणित की भूमिका का वर्णन कैसे करती है?","optionsHi":["विद्यार्थी मुख्यतः बहुत बड़ी संख्याओं और लंबे शाब्दिक प्रश्नों पर चार संक्रियाओं का अभ्यास करते हैं","विद्यार्थी गणित की शक्ति का पहला स्वाद बीजगणित जैसे अमूर्तनों से लेते हैं जो पहले के कार्य को संघनित करते हैं","विद्यार्थियों को ज्यामिति में औपचारिक दो-स्तंभीय उपपत्तियाँ सीखना आरंभ करना चाहिए, जैसा बाद की कक्षाओं में होता है","विद्यार्थियों को गणित का अध्ययन अपनी औपचारिक संरचना वाले अलग अनुशासन के रूप में करना चाहिए"],"explanationHi":"NCF 2005 उच्च प्राथमिक स्तर को वह बिंदु मानती है जहाँ बीजगणितीय संकेतन जैसे अमूर्त विचार पहले के अंकगणित का सारांश बनाने और उसे विस्तार देने लगते हैं। गणित को अपनी संरचना वाले अनुशासन के रूप में देखना माध्यमिक स्तर का है।"},
  {"id":"cdp-pedagogy-subjects-1716","question":"A Class 4 child in Bihar solves a word problem correctly when the teacher tells it in Bhojpuri, but gets the written Hindi version wrong. What should the teacher infer?","options":["The child has a learning disability in mathematics and should be assessed by a specialist","The child probably copied the oral answer from a friend who understood the Bhojpuri version","The child should be given only plain number sums from now on, and no word problems in any language","The barrier is reading, not maths; reading problems aloud and allowing the home language can help"],"answer":3,"explanation":"Correct oral solutions show the mathematical reasoning is in place. The barrier is language and reading, which needs separate support so it does not hide her mathematical ability.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"बिहार में कक्षा 4 का एक बच्चा शाब्दिक प्रश्न तब सही हल करता है जब शिक्षिका उसे भोजपुरी में सुनाती है, पर लिखित हिंदी रूप गलत करता है। शिक्षिका को क्या निष्कर्ष निकालना चाहिए?","optionsHi":["बच्चे को गणित में सीखने की अक्षमता है और उसका किसी विशेषज्ञ से आकलन होना चाहिए","बच्चे ने संभवतः मौखिक उत्तर किसी ऐसे दोस्त से उतार लिया जिसने भोजपुरी रूप समझा था","बच्चे को अब से केवल सादे संख्या-प्रश्न देने चाहिए, किसी भी भाषा में शाब्दिक प्रश्न नहीं","बाधा पठन की है, गणित की नहीं; प्रश्नों को ज़ोर से पढ़ना और घरेलू भाषा की अनुमति देना मदद कर सकता है"],"explanationHi":"सही मौखिक हल दिखाते हैं कि गणितीय तर्क मौजूद है। बाधा भाषा और पठन की है, जिसके लिए अलग सहायता चाहिए ताकि वह उसकी गणितीय क्षमता को न छिपाए।"},
  {"id":"cdp-pedagogy-subjects-1717","question":"To find 6 + 4 + 3, a Class 3 child writes ‘6 + 4 = 10 + 3 = 13’. What is the problem with this?","options":["6 + 4 = 10 + 3 is false; she uses ‘=’ to mean ‘and then’, not ‘is equal to’","There is no problem, since each step is correct and the final answer, 13, is right","She should have added 4 and 3 first, since addition must go from right to left","She has added the numbers in the wrong order; 3 should have been added before 4"],"answer":0,"explanation":"Read as written, the line claims 6 + 4 = 13. Such run-on number sentences reveal an operational view of ‘=’, which causes difficulty later in algebra; writing 6 + 4 = 10 and 10 + 3 = 13 fixes it.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT","questionHi":"6 + 4 + 3 निकालने के लिए कक्षा 3 की एक बच्ची लिखती है ‘6 + 4 = 10 + 3 = 13’। इसमें समस्या क्या है?","optionsHi":["6 + 4 = 10 + 3 गलत है; वह ‘=’ का उपयोग ‘और फिर’ के अर्थ में करती है, ‘के बराबर है’ के अर्थ में नहीं","कोई समस्या नहीं है, क्योंकि हर चरण सही है और अंतिम उत्तर, 13, सही है","उसे पहले 4 और 3 जोड़ने चाहिए थे, क्योंकि जोड़ दाएँ से बाएँ होना चाहिए","उसने संख्याएँ गलत क्रम में जोड़ी हैं; 3 को 4 से पहले जोड़ना चाहिए था"],"explanationHi":"जैसा लिखा है, पंक्ति दावा करती है कि 6 + 4 = 13। ऐसे लगातार चलने वाले संख्या-वाक्य ‘=’ के संक्रियात्मक दृष्टिकोण को प्रकट करते हैं, जो आगे बीजगणित में कठिनाई देता है; 6 + 4 = 10 और 10 + 3 = 13 लिखना इसे ठीक करता है।"},
  {"id":"cdp-pedagogy-subjects-1718","question":"A Class 5 child writes 1/2 × 6 = 1/12. Which question best helps her?","options":["‘What is 6 × 2? Is it 12?’","‘What is half of 6 rotis?’","‘Can you write 6 as 6/6?’","‘What is 1/2 + 6 rotis?’"],"answer":1,"explanation":"She multiplied the denominator by 6. Half of 6 rotis is clearly 3 rotis, which shows that 1/2 × 6 = 6/2 = 3; writing 6 as 6/1 is what makes the rule work.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक बच्ची लिखती है 1/2 × 6 = 1/12। कौन-सा प्रश्न उसकी सबसे अच्छी मदद करता है?","optionsHi":["‘6 × 2 कितना है? क्या वह 12 है?’","‘6 रोटियों का आधा कितना है?’","‘क्या तुम 6 को 6/6 के रूप में लिख सकती हो?’","‘1/2 + 6 रोटियाँ कितना है?’"],"explanationHi":"उसने हर को 6 से गुणा कर दिया। 6 रोटियों का आधा स्पष्ट रूप से 3 रोटियाँ है, जो दिखाता है कि 1/2 × 6 = 6/2 = 3; 6 को 6/1 के रूप में लिखना ही नियम को काम करने लायक बनाता है।"},
  {"id":"cdp-pedagogy-subjects-1719","question":"A Class 5 child says 7.08 and 7.8 are equal ‘because zero has no value’. What is the best response?","options":["Agree, since zeros in decimals have no value and can always be removed","Tell her that 7.08 is larger, because it has more digits after the point","Ask her to show both on a metre stick, as 7 m 8 cm and 7 m 80 cm","Ask her to learn by heart that zero is a number and does have a value"],"answer":2,"explanation":"The 0 in 7.08 holds the tenths place, so the 8 means 8 hundredths, while in 7.8 it means 8 tenths. A trailing zero (7.80) can be dropped; a zero between digits cannot.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक बच्ची कहती है कि 7.08 और 7.8 बराबर हैं ‘क्योंकि शून्य का कोई मान नहीं होता’। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["सहमत होना, क्योंकि दशमलव में शून्यों का कोई मान नहीं होता और उन्हें हमेशा हटाया जा सकता है","उससे कहना कि 7.08 बड़ा है, क्योंकि उसमें बिंदु के बाद अधिक अंक हैं","उससे दोनों को मीटर-छड़ी पर 7 m 8 cm और 7 m 80 cm के रूप में दिखाने को कहना","उससे यह रटने को कहना कि शून्य एक संख्या है और उसका मान होता है"],"explanationHi":"7.08 में 0 दशांश का स्थान लेता है, इसलिए 8 का अर्थ 8 सौवाँ है, जबकि 7.8 में इसका अर्थ 8 दशांश है। अंत का शून्य (7.80) हटाया जा सकता है; अंकों के बीच का शून्य नहीं।"},
  {"id":"cdp-pedagogy-subjects-1720","question":"A Class 7 student writes 0.5% = 1/2. What is the misconception?","options":["She does not know that 1/2 is the same as 0.5 when written as a decimal","She has confused percentage with ratio, reading 0.5% as the ratio 1 : 2","She has made a small slip in copying the question and wrote % by mistake","She ignored the % sign: 0.5% means 0.5 per hundred, or 1/200; 1/2 is 50%"],"answer":3,"explanation":"0.5% = 0.5/100 = 0.005 = 1/200. She has read 0.5% as the decimal 0.5. Small percentages like this are often confused with the decimal written before the % sign.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक विद्यार्थी लिखती है 0.5% = 1/2। भ्रांति क्या है?","optionsHi":["वह नहीं जानती कि दशमलव के रूप में लिखे जाने पर 1/2, 0.5 के बराबर होता है","उसने प्रतिशत को अनुपात से उलझा दिया है, 0.5% को अनुपात 1 : 2 पढ़ते हुए","उसने प्रश्न उतारने में छोटी चूक की और गलती से % लिख दिया","उसने % चिह्न की अनदेखी की: 0.5% का अर्थ है प्रति सौ 0.5, या 1/200; 1/2 बराबर 50% है"],"explanationHi":"0.5% = 0.5/100 = 0.005 = 1/200। उसने 0.5% को दशमलव 0.5 पढ़ लिया है। ऐसे छोटे प्रतिशत प्रायः % चिह्न से पहले लिखे दशमलव से उलझा दिए जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1721","question":"Class 5 children each draw a map of the route from school to the bus stop, but their maps do not match in size or distances. What is the best next step?","options":["Use the mismatch to discuss why maps need a common scale, e.g. 1 cm for 10 steps","Ask the children to copy the teacher's map, so that everyone has the same correct one","Tell them that only official maps are correct, since children's maps are just drawings","Ask them to draw the maps again more neatly and with a ruler, so that they match better"],"answer":0,"explanation":"The differences give a real reason for the idea of scale. Children who feel the need for a common scale understand it far better than those simply told about it.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के बच्चे हर एक विद्यालय से बस-स्टॉप तक के मार्ग का मानचित्र बनाते हैं, पर उनके मानचित्र आकार या दूरियों में मेल नहीं खाते। सबसे अच्छा अगला कदम क्या है?","optionsHi":["बेमेल का उपयोग यह चर्चा करने में करना कि मानचित्रों को उभयनिष्ठ पैमाना क्यों चाहिए, जैसे 1 cm के लिए 10 कदम","बच्चों से शिक्षिका का मानचित्र उतारने को कहना, ताकि सबके पास वही सही मानचित्र हो","उन्हें बताना कि केवल आधिकारिक मानचित्र सही होते हैं, बच्चों के मानचित्र केवल चित्र हैं","उनसे मानचित्र अधिक साफ़-सुथरे ढंग से और पटरी की सहायता से फिर बनाने को कहना, ताकि वे बेहतर मेल खाएँ"],"explanationHi":"अंतर पैमाने के विचार का वास्तविक कारण देते हैं। जिन बच्चों को उभयनिष्ठ पैमाने की आवश्यकता महसूस होती है वे उसे केवल बता दिए जाने वालों से कहीं बेहतर समझते हैं।"},
  {"id":"cdp-pedagogy-subjects-1722","question":"Assertion (A): In Classes 1 and 2, the ‘+’ sign should be introduced only after children have solved many joining stories orally and with objects. Reason (R): Symbols have meaning for children only when they stand for experiences the children already have.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Symbols record ideas; introduced before the experiences they stand for, they become marks to manipulate without meaning. R gives the reason for A.","difficulty":"hard","source":"CTET Paper 1 · state TETs","questionHi":"अभिकथन (A): कक्षा 1 और 2 में, ‘+’ चिह्न तभी परिचित कराया जाना चाहिए जब बच्चे मौखिक रूप से और वस्तुओं के साथ जोड़ने वाली अनेक कहानियाँ हल कर चुके हों। कारण (R): प्रतीक बच्चों के लिए तभी अर्थपूर्ण होते हैं जब वे बच्चों के पूर्व अनुभवों का प्रतिनिधित्व करते हों।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"प्रतीक विचारों को दर्ज करते हैं; जिन अनुभवों का वे प्रतिनिधित्व करते हैं, उनसे पहले परिचित कराने पर वे ऐसे अर्थहीन चिह्न बन जाते हैं जिनसे बस यांत्रिक हेरफेर किया जाता है। R, A का कारण देता है।"},
  {"id":"cdp-pedagogy-subjects-1723","question":"Assertion (A): Since Van Hiele levels depend on age, all children in Class 8 reason at the deduction level. Reason (R): Progress through the Van Hiele levels depends mainly on instruction and experience.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Van Hiele levels are not tied to age; they depend on experience and teaching, so Class 8 students may be at different levels, many below deduction. A is false and R is true.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अभिकथन (A): चूँकि वैन हील के स्तर आयु पर निर्भर करते हैं, इसलिए कक्षा 8 के सभी बच्चे निगमन-स्तर पर तर्क करते हैं। कारण (R): वैन हील के स्तरों में प्रगति मुख्यतः शिक्षण और अनुभव पर निर्भर करती है।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"वैन हील के स्तर आयु से बँधे नहीं हैं; वे अनुभव और शिक्षण पर निर्भर करते हैं, इसलिए कक्षा 8 के विद्यार्थी अलग-अलग स्तरों पर हो सकते हैं, बहुत-से निगमन से नीचे। A गलत है और R सही है।"},
  {"id":"cdp-pedagogy-subjects-1724","question":"Which of these statements about number sense are correct? I. It includes thinking flexibly about numbers, for example seeing 8 as 5 + 3, 10 − 2 or 4 + 4. II. Children who count quickly always have good number sense. III. Estimation is part of number sense. IV. Number sense grows through rich talk and experience, not only drill.","options":["I and II only","I, III and IV","II, III and IV","I, II, III and IV"],"answer":1,"explanation":"Fast counting is a procedural skill and does not guarantee number sense, so II is false. Flexibility, estimation and growth through experience and talk describe number sense.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"संख्या-बोध (number sense) के बारे में इनमें से कौन-से कथन सही हैं? I. इसमें संख्याओं के बारे में लचीले ढंग से सोचना शामिल है, जैसे 8 को 5 + 3, 10 − 2 या 4 + 4 के रूप में देखना। II. जो बच्चे तेज़ी से गिनते हैं उनमें हमेशा अच्छा संख्या-बोध होता है। III. आकलन (estimation) संख्या-बोध का हिस्सा है। IV. संख्या-बोध समृद्ध बातचीत और अनुभव से बढ़ता है, केवल अभ्यास-कवायद से नहीं।","optionsHi":["केवल I और II","I, III और IV","II, III और IV","I, II, III और IV"],"explanationHi":"तेज़ गिनती एक प्रक्रियात्मक कौशल है और संख्या-बोध की गारंटी नहीं देती, इसलिए II गलत है। लचीलापन, आकलन और अनुभव तथा बातचीत से विकास संख्या-बोध का वर्णन करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1725","question":"Two equal paper squares are each cut in half, one along a diagonal (two triangles) and one down the middle (two rectangles). A child says a triangle and a rectangle cannot both be halves ‘because they are different shapes’. What does the child need to understand?","options":["That only rectangles can be halves of a square, since a square has straight sides","That triangles are always smaller than rectangles cut from the same square","That a half means equal size relative to the same whole, not a particular shape","That the squares were not cut correctly, since halves must always look the same"],"answer":2,"explanation":"Each piece is half the area of an equal square, so both are halves. Drawing both on squared paper and counting squares shows that the triangle and the rectangle cover the same area.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"दो बराबर कागज़ी वर्ग प्रत्येक आधे-आधे काटे जाते हैं, एक विकर्ण के अनुदिश (दो त्रिभुज) और एक बीच से सीधे (दो आयत)। एक बच्चा कहता है कि त्रिभुज और आयत दोनों आधे नहीं हो सकते ‘क्योंकि वे अलग आकृतियाँ हैं’। बच्चे को क्या समझना आवश्यक है?","optionsHi":["कि वर्ग के आधे केवल आयत हो सकते हैं, क्योंकि वर्ग की भुजाएँ सीधी होती हैं","कि त्रिभुज हमेशा उसी वर्ग से काटे गए आयतों से छोटे होते हैं","कि आधे का अर्थ उसी पूर्ण के सापेक्ष समान आकार है, कोई विशेष आकृति नहीं","कि वर्ग ठीक से नहीं काटे गए थे, क्योंकि आधे हमेशा एक जैसे दिखने चाहिए"],"explanationHi":"प्रत्येक टुकड़ा बराबर वर्ग के क्षेत्रफल का आधा है, इसलिए दोनों आधे हैं। दोनों को वर्गाकार कागज़ पर बनाकर वर्ग गिनना दिखाता है कि त्रिभुज और आयत समान क्षेत्रफल घेरते हैं।"},
  {"id":"cdp-pedagogy-subjects-1726","question":"A Class 5 teacher plans a story lesson in three stages: pre-reading, while-reading and post-reading. Which activity belongs to the post-reading stage?","options":["Predicting the story from its title and the cover picture","Answering a question at the end of each section while they read","Writing a letter from one character to another about the events","Discussing key words needed to follow the first page"],"answer":2,"explanation":"Post-reading tasks use the understood text for extension and personal response, such as writing in role; prediction and key words come before reading, and section questions during it.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 5 की एक शिक्षिका कहानी के पाठ की योजना तीन चरणों में बनाती है: पठन-पूर्व, पठन-दौरान और पठन-पश्चात्। कौन-सी गतिविधि पठन-पश्चात् चरण की है?","optionsHi":["कहानी का शीर्षक और आवरण-चित्र देखकर उसका पूर्वानुमान लगाना","पढ़ते समय हर खंड के अंत में एक प्रश्न का उत्तर देना","एक पात्र की ओर से दूसरे को घटनाओं के बारे में पत्र लिखना","पहले पृष्ठ को समझने के लिए आवश्यक मुख्य शब्दों पर चर्चा करना"],"explanationHi":"पठन-पश्चात् कार्य समझे गए पाठ का उपयोग विस्तार और व्यक्तिगत प्रतिक्रिया के लिए करते हैं, जैसे भूमिका में लिखना; पूर्वानुमान और मुख्य शब्द पढ़ने से पहले आते हैं, और खंड के प्रश्न उसके दौरान।"},
  {"id":"cdp-pedagogy-subjects-1727","question":"Teaching a poem about the monsoon to Class 8, which approach best develops appreciation of figurative language?","options":["Giving definitions of simile and metaphor for students to learn by heart","Asking students to find images and discuss what each makes them feel","Listing all the figures of speech in the poem with their names for copying","Asking students to write the meanings of difficult words from a guidebook"],"answer":1,"explanation":"Appreciation grows from noticing how images work and responding to their effect; naming devices without engaging with them turns poetry into labelling.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 8 को मानसून पर कविता पढ़ाते समय कौन-सा उपागम अलंकारिक भाषा की सराहना को सबसे अच्छी तरह विकसित करता है?","optionsHi":["उपमा और रूपक की परिभाषाएँ देना जिन्हें विद्यार्थी रट लें","विद्यार्थियों से बिंब खोजने और चर्चा करने को कहना कि हर एक उन्हें कैसा महसूस कराता है","कविता के सभी अलंकारों की उनके नामों सहित सूची बनाना जिसे उतारा जाए","विद्यार्थियों से गाइड-पुस्तक से कठिन शब्दों के अर्थ लिखने को कहना"],"explanationHi":"सराहना इस पर ध्यान देने से बढ़ती है कि बिंब कैसे काम करते हैं और उनके प्रभाव पर प्रतिक्रिया देने से; उनसे जुड़े बिना युक्तियों के नाम देना कविता को ठप्पा लगाने में बदल देता है।"},
  {"id":"cdp-pedagogy-subjects-1728","question":"A Class 6 teacher’s daily homework is ‘Write the meanings of 20 words from the dictionary.’ Which homework would build vocabulary more effectively?","options":["Writing the meanings of 40 words instead, so that more words are covered","Copying the same 20 words five times each to remember their spellings well","Learning the dictionary entries for words that begin with one letter","Reading a story of their choice and noting three new words in context"],"answer":3,"explanation":"Words met in meaningful reading, noted with their context and chosen by the learner, are retained and understood better than lists copied from a dictionary.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 6 की एक शिक्षिका का दैनिक गृहकार्य है ‘शब्दकोश से 20 शब्दों के अर्थ लिखो।’ कौन-सा गृहकार्य शब्दावली को अधिक प्रभावी ढंग से बनाएगा?","optionsHi":["इसके बजाय 40 शब्दों के अर्थ लिखना, ताकि अधिक शब्द कवर हों","उन्हीं 20 शब्दों को पाँच-पाँच बार उतारना, ताकि उनकी वर्तनी अच्छी तरह याद रहे","किसी एक अक्षर से शुरू होने वाले शब्दों की शब्दकोश-प्रविष्टियाँ सीखना","अपनी पसंद की कहानी पढ़ना और संदर्भ में तीन नए शब्द नोट करना"],"explanationHi":"सार्थक पठन में मिले, संदर्भ सहित नोट किए गए और अधिगमकर्ता द्वारा चुने गए शब्द शब्दकोश से उतारी सूचियों की तुलना में बेहतर याद रहते और समझे जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1729","question":"Class 7 students produce a monthly class newspaper: they interview staff and classmates, write reports and reviews, edit each other’s pieces and read the finished issue. Which statement about this project is most accurate?","options":["It mainly develops handwriting, since the paper is written by hand","It integrates all four skills through real, purposeful tasks","It is a writing task only, since the outcome is a written newspaper","It is useful only for students who already write very well"],"answer":1,"explanation":"Interviewing involves speaking and listening, reports involve writing, and editing and reading the issue involve reading; the real audience gives every skill a purpose.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 7 के विद्यार्थी मासिक कक्षा-समाचार पत्र बनाते हैं: वे कर्मचारियों और सहपाठियों के साक्षात्कार लेते हैं, रिपोर्टें और समीक्षाएँ लिखते हैं, एक-दूसरे की रचनाएँ संपादित करते हैं और तैयार अंक पढ़ते हैं। इस परियोजना के बारे में कौन-सा कथन सबसे सटीक है?","optionsHi":["यह मुख्यतः हस्तलेखन विकसित करती है, क्योंकि पत्र हाथ से लिखा जाता है","यह वास्तविक, उद्देश्यपूर्ण कार्यों के माध्यम से सभी चारों कौशलों को एकीकृत करती है","यह केवल लेखन कार्य है, क्योंकि परिणाम एक लिखित समाचार-पत्र है","यह केवल उन विद्यार्थियों के लिए उपयोगी है जो पहले से बहुत अच्छा लिखते हैं"],"explanationHi":"साक्षात्कार में बोलना और सुनना शामिल है, रिपोर्टों में लेखन, और संपादन तथा अंक पढ़ने में पठन; वास्तविक श्रोता-वर्ग हर कौशल को उद्देश्य देता है।"},
  {"id":"cdp-pedagogy-subjects-1730","question":"Many Class 9 students memorise answers to textbook questions from guidebooks and reproduce them in tests. Which step by the teacher would best encourage genuine understanding?","options":["Banning guidebooks and searching bags regularly to enforce the ban","Setting the same textbook questions but awarding marks only for exact wording","Asking for personal responses and applications that no guidebook contains","Giving more questions from the guidebook so that students practise them better"],"answer":2,"explanation":"Questions that ask students to interpret, relate the text to their lives or apply ideas cannot be answered by memorised guide answers, which shifts effort towards real comprehension.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 9 के बहुत-से विद्यार्थी गाइड-पुस्तकों से पाठ्यपुस्तक के प्रश्नों के उत्तर रट लेते हैं और परीक्षाओं में उन्हें दोहरा देते हैं। शिक्षक का कौन-सा कदम वास्तविक समझ को सबसे अच्छी तरह प्रोत्साहित करेगा?","optionsHi":["गाइड-पुस्तकों पर प्रतिबंध लगाना और प्रतिबंध लागू करने के लिए नियमित रूप से बैग की तलाशी लेना","वही पाठ्यपुस्तक के प्रश्न देना पर अंक केवल सटीक शब्दावली पर देना","व्यक्तिगत प्रतिक्रियाएँ और अनुप्रयोग माँगना जो किसी गाइड-पुस्तक में नहीं हैं","गाइड-पुस्तक से और प्रश्न देना ताकि विद्यार्थी उनका बेहतर अभ्यास करें"],"explanationHi":"जो प्रश्न विद्यार्थियों से व्याख्या करने, पाठ को अपने जीवन से जोड़ने या विचारों को लागू करने को कहते हैं, उनके उत्तर रटे गाइड-उत्तरों से नहीं दिए जा सकते, जिससे प्रयास वास्तविक बोध की ओर जाता है।"},
  {"id":"cdp-pedagogy-subjects-1731","question":"To teach ‘in’, ‘on’ and ‘under’ to Class 2, which activity is most effective?","options":["Writing the definitions of the three words for children to copy","Making children memorise a list of sentences using each word","Asking children to underline ‘in’, ‘on’ and ‘under’ in a long passage","Children placing a ball in, on and under a box on command"],"answer":3,"explanation":"Acting out spatial relationships links each preposition directly to its meaning through movement, in the spirit of Total Physical Response.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 2 को ‘in’, ‘on’ और ‘under’ पढ़ाने के लिए कौन-सी गतिविधि सबसे प्रभावी है?","optionsHi":["तीनों शब्दों की परिभाषाएँ लिखना जिन्हें बच्चे उतारें","बच्चों से हर शब्द वाले वाक्यों की सूची रटवाना","बच्चों से लंबे गद्यांश में ‘in’, ‘on’ और ‘under’ को रेखांकित करने को कहना","बच्चों का आदेश पर गेंद को डिब्बे के अंदर, ऊपर और नीचे रखना"],"explanationHi":"स्थानिक संबंधों का अभिनय करना प्रत्येक पूर्वसर्ग को गति के माध्यम से सीधे उसके अर्थ से जोड़ता है, संपूर्ण शारीरिक प्रतिक्रिया (Total Physical Response) की भावना में।"},
  {"id":"cdp-pedagogy-subjects-1732","question":"A teacher with 60 students in Class 6 avoids pair work because she fears noise and loss of control. Which advice is most practical?","options":["Demonstrate first, set a time limit and agree on a signal to stop","Avoid pair work altogether, since large classes need lecture teaching","Use pair work only with the best students, while the rest copy notes","Allow pair work only in the last five minutes when noise matters less"],"answer":0,"explanation":"Pair work multiplies speaking time in large classes; careful set-up, demonstration, time limits and an agreed signal keep it purposeful and manageable.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 6 में 60 विद्यार्थियों वाली एक शिक्षिका शोर और नियंत्रण खोने के डर से जोड़ी में कार्य से बचती है। कौन-सी सलाह सबसे व्यावहारिक है?","optionsHi":["पहले प्रदर्शन करना, समय-सीमा तय करना और रुकने के लिए संकेत पर सहमत होना","जोड़ी में कार्य से पूरी तरह बचना, क्योंकि बड़ी कक्षाओं को व्याख्यान-शिक्षण चाहिए","जोड़ी में कार्य केवल सर्वश्रेष्ठ विद्यार्थियों के साथ करना, जबकि बाकी नोट्स उतारें","जोड़ी में कार्य केवल अंतिम पाँच मिनट में अनुमति देना जब शोर कम मायने रखता है"],"explanationHi":"जोड़ी में कार्य बड़ी कक्षाओं में बोलने का समय बढ़ाता है; सावधानी से तैयारी, प्रदर्शन, समय-सीमा और तय संकेत उसे उद्देश्यपूर्ण और प्रबंधनीय रखते हैं।"},
  {"id":"cdp-pedagogy-subjects-1733","question":"A Class 3 teacher gives a long instruction in English for a game, and most children start doing different things. What should she do next time?","options":["Repeat the same instruction louder and more slowly","Give the instruction in writing on the board for children to read","Use short steps, demonstrate the game and check understanding first","Skip the game, since Class 3 children cannot follow English instructions"],"answer":2,"explanation":"Instructions work when they are brief, shown as well as told, and checked with simple questions such as ‘Who goes first?’; repeating a confusing instruction louder does not help.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 3 की एक शिक्षिका एक खेल के लिए अंग्रेज़ी में लंबा निर्देश देती है, और अधिकांश बच्चे अलग-अलग चीज़ें करने लगते हैं। अगली बार उसे क्या करना चाहिए?","optionsHi":["वही निर्देश अधिक ज़ोर से और धीरे दोहराना","निर्देश को श्यामपट्ट पर लिखकर देना ताकि बच्चे पढ़ सकें","छोटे चरणों का उपयोग करना, खेल का प्रदर्शन करना और पहले समझ की जाँच करना","खेल छोड़ देना, क्योंकि कक्षा 3 के बच्चे अंग्रेज़ी निर्देश नहीं समझ सकते"],"explanationHi":"निर्देश तब काम करते हैं जब वे संक्षिप्त हों, बताए ही नहीं दिखाए भी जाएँ, और ‘पहले कौन जाएगा?’ जैसे सरल प्रश्नों से जाँचे जाएँ; भ्रमित करने वाले निर्देश को ज़ोर से दोहराना मदद नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-1734","question":"After presenting ‘I used to live in Patna’, a teacher asks, ‘Do I live in Patna now?’ and ‘Did I live there for a long time?’ The main purpose of these questions is to:","options":["Test whether students can spell ‘Patna’ correctly","Find out where the students themselves used to live","Practise forming questions in the simple present tense","Check that students understand what ‘used to’ means"],"answer":3,"explanation":"Concept-checking questions test understanding of meaning, here a past habit or state that is no longer true, without relying on students repeating the form.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"‘I used to live in Patna’ प्रस्तुत करने के बाद शिक्षक पूछता है, ‘Do I live in Patna now?’ और ‘Did I live there for a long time?’ इन प्रश्नों का मुख्य उद्देश्य है:","optionsHi":["यह जाँचना कि विद्यार्थी ‘Patna’ की वर्तनी सही लिख सकते हैं या नहीं","यह पता लगाना कि विद्यार्थी स्वयं कहाँ रहा करते थे","सरल वर्तमान काल में प्रश्न बनाने का अभ्यास कराना","यह जाँचना कि विद्यार्थी समझते हैं कि ‘used to’ का क्या अर्थ है"],"explanationHi":"संकल्पना-जाँच प्रश्न अर्थ की समझ की परीक्षा लेते हैं, यहाँ अतीत की ऐसी आदत या स्थिति जो अब सच नहीं है, विद्यार्थियों के रूप दोहराने पर निर्भर हुए बिना।"},
  {"id":"cdp-pedagogy-subjects-1735","question":"Before introducing the word ‘well’, a teacher shows a picture and asks, ‘What is this? What do people in your village use it for?’ The main purpose of this elicitation is to:","options":["Draw on children's knowledge and involve them before giving the word","Find out which children do not know the word, so they can be corrected","Save time by avoiding the need to teach the word at all","Test children’s knowledge for the term report card"],"answer":0,"explanation":"Elicitation activates prior knowledge and gets learners thinking and talking, so the new word attaches to an existing concept instead of being simply announced.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"‘well’ शब्द परिचित कराने से पहले एक शिक्षिका चित्र दिखाती है और पूछती है, ‘यह क्या है? तुम्हारे गाँव के लोग इसका उपयोग किसलिए करते हैं?’ इस निष्कर्षण (elicitation) का मुख्य उद्देश्य है:","optionsHi":["शब्द देने से पहले बच्चों के ज्ञान का उपयोग करना और उन्हें जोड़ना","यह पता लगाना कि किन बच्चों को शब्द नहीं आता, ताकि उन्हें सुधारा जा सके","शब्द पढ़ाने की आवश्यकता से बचकर समय बचाना","सत्रांत रिपोर्ट कार्ड के लिए बच्चों के ज्ञान की परीक्षा लेना"],"explanationHi":"निष्कर्षण पूर्व ज्ञान को सक्रिय करता है और अधिगमकर्ताओं को सोचने और बोलने में लगाता है, ताकि नया शब्द केवल घोषित किए जाने के बजाय पहले से मौजूद संकल्पना से जुड़े।"},
  {"id":"cdp-pedagogy-subjects-1736","question":"In a ‘listen and draw’ activity, a teacher describes a picture (‘There is a big tree on the left. A cat is sitting under it…’) and Class 3 children draw what they hear. This activity mainly assesses and develops:","options":["Drawing ability, since the outcome is a picture","Listening comprehension, shown without speaking or writing","Speaking fluency, since children talk about their drawings","Reading skills, since children read the description"],"answer":1,"explanation":"Drawing gives children a way to show understanding of spoken language without needing to speak or write, which suits young learners.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"‘सुनो और बनाओ’ गतिविधि में शिक्षिका एक चित्र का वर्णन करती है (‘बाईं ओर एक बड़ा पेड़ है। उसके नीचे एक बिल्ली बैठी है…’) और कक्षा 3 के बच्चे जो सुनते हैं वह बनाते हैं। यह गतिविधि मुख्यतः किसका आकलन और विकास करती है?","optionsHi":["चित्रकला की क्षमता, क्योंकि परिणाम एक चित्र है","श्रवण बोध, जो बोले या लिखे बिना दिखाया जाता है","बोलने की प्रवाहशीलता, क्योंकि बच्चे अपने चित्रों के बारे में बात करते हैं","पठन कौशल, क्योंकि बच्चे वर्णन पढ़ते हैं"],"explanationHi":"चित्र बनाना बच्चों को बोले बिना या लिखे बिना बोली गई भाषा की समझ दिखाने का तरीका देता है, जो छोटे अधिगमकर्ताओं के अनुकूल है।"},
  {"id":"cdp-pedagogy-subjects-1737","question":"A Class 8 teacher gives an open-book English test in which students may use their textbook. What is this kind of test best suited to assess?","options":["Memorisation of passages and answers","Speed of handwriting under examination conditions","Locating, interpreting and applying information","Knowledge of the author’s biography"],"answer":2,"explanation":"Since the text is available, open-book questions must go beyond recall and assess higher-order skills such as finding, interpreting and using information.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 8 का एक शिक्षक खुली-पुस्तक (open-book) अंग्रेज़ी परीक्षा देता है जिसमें विद्यार्थी अपनी पाठ्यपुस्तक का उपयोग कर सकते हैं। इस प्रकार की परीक्षा किसका आकलन करने के लिए सबसे उपयुक्त है?","optionsHi":["गद्यांशों और उत्तरों का स्मरण","परीक्षा की परिस्थितियों में लिखावट की गति","जानकारी को खोजना, उसकी व्याख्या करना और उसे लागू करना","लेखक की जीवनी का ज्ञान"],"explanationHi":"चूँकि पाठ उपलब्ध है, खुली-पुस्तक प्रश्नों को स्मरण से आगे जाकर जानकारी खोजने, उसकी व्याख्या करने और उपयोग करने जैसे उच्च-स्तरीय कौशलों का आकलन करना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1738","question":"Assertion (A): During a storytelling session, a Class 1 teacher should not correct every pronunciation slip a child makes. Reason (R): Constant correction can raise anxiety and discourage children from speaking.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"In a meaning-focused activity, over-correction shifts attention to form and raises the affective filter; that is exactly why selective, later feedback is preferred.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"अभिकथन (A): कहानी सुनाने के सत्र में कक्षा 1 की शिक्षिका को बच्चे की हर उच्चारण-चूक नहीं सुधारनी चाहिए। कारण (R): लगातार सुधार चिंता बढ़ा सकता है और बच्चों को बोलने से हतोत्साहित कर सकता है। सही विकल्प चुनिए।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"अर्थ-केंद्रित गतिविधि में अति-सुधार ध्यान को रूप की ओर ले जाता है और भावात्मक अवरोध (affective filter) बढ़ाता है; ठीक इसीलिए चयनित, बाद की प्रतिपुष्टि को वरीयता दी जाती है।"},
  {"id":"cdp-pedagogy-subjects-1739","question":"Preparing Class 4 children for a visit to the railway station, the teacher introduces ‘ticket counter’, ‘platform’, ‘coach’, ‘porter’ and ‘announcement’ with a picture of a station and role play. Why is this an effective way to teach vocabulary?","options":["The words are taught in alphabetical order, which aids memory","The words form a set linked to a real situation they will meet","The words are short and easy to spell","The words are taught without any context, which avoids confusion"],"answer":1,"explanation":"Grouping words around a situation the children will experience gives them context, makes connections between words and offers an immediate use for them.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"कक्षा 4 के बच्चों को रेलवे स्टेशन की यात्रा के लिए तैयार करते हुए शिक्षिका स्टेशन के चित्र और भूमिका-निर्वाह के साथ ‘ticket counter’, ‘platform’, ‘coach’, ‘porter’ और ‘announcement’ परिचित कराती है। शब्दावली पढ़ाने का यह तरीका प्रभावी क्यों है?","optionsHi":["शब्द वर्णानुक्रम में पढ़ाए जाते हैं, जो स्मृति में सहायक है","शब्द एक ऐसी वास्तविक स्थिति से जुड़ा समूह बनाते हैं जिसका वे सामना करेंगे","शब्द छोटे और वर्तनी में आसान हैं","शब्द बिना किसी संदर्भ के पढ़ाए जाते हैं, जिससे भ्रम से बचाव होता है"],"explanationHi":"शब्दों को ऐसी स्थिति के आसपास समूहबद्ध करना जिसका बच्चे अनुभव करेंगे, उन्हें संदर्भ देता है, शब्दों के बीच संबंध बनाता है और उनके लिए तत्काल उपयोग देता है।"},
  {"id":"cdp-pedagogy-subjects-1740","question":"Consider these factors: I. Long sentences with many clauses. II. An unfamiliar topic for which children have little background. III. Many abstract or rare words. Which can make a text harder for Class 5 readers?","options":["I only","I and III only","II and III only","I, II and III"],"answer":3,"explanation":"Text difficulty depends on sentence complexity and vocabulary, and also on the reader’s background knowledge of the topic; all three raise the load.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"इन कारकों पर विचार कीजिए: I. अनेक उपवाक्यों वाले लंबे वाक्य। II. अपरिचित विषय जिसकी बच्चों को बहुत कम पृष्ठभूमि है। III. अनेक अमूर्त या दुर्लभ शब्द। इनमें से कौन-से कक्षा 5 के पाठकों के लिए पाठ को कठिन बना सकते हैं?","optionsHi":["केवल I","केवल I और III","केवल II और III","I, II और III"],"explanationHi":"पाठ की कठिनाई वाक्य की जटिलता और शब्दावली पर, और विषय के बारे में पाठक के पृष्ठभूमि-ज्ञान पर भी निर्भर करती है; तीनों भार बढ़ाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1741","question":"A Class 6 teacher includes folk tales from Assam, Kerala and Africa in her English reading lessons. Apart from language, the main benefit is that children:","options":["Develop empathy and awareness of other cultures","Learn the exact geography of each place in the tales","Memorise more stories for examinations","Learn that all stories have the same ending"],"answer":0,"explanation":"Literature from varied cultures lets children see the world through other eyes, fostering empathy and respect for diversity, while also giving rich language input.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 6 की एक शिक्षिका अपने अंग्रेज़ी पठन-पाठों में असम, केरल और अफ़्रीका की लोक-कथाएँ शामिल करती है। भाषा के अलावा मुख्य लाभ यह है कि बच्चे:","optionsHi":["सहानुभूति और अन्य संस्कृतियों के प्रति जागरूकता विकसित करते हैं","कथाओं में आए प्रत्येक स्थान का सटीक भूगोल सीखते हैं","परीक्षाओं के लिए अधिक कहानियाँ रटते हैं","सीखते हैं कि सभी कहानियों का अंत एक जैसा होता है"],"explanationHi":"विविध संस्कृतियों का साहित्य बच्चों को दुनिया को दूसरों की आँखों से देखने देता है, सहानुभूति और विविधता के सम्मान को बढ़ावा देता है, साथ ही समृद्ध भाषा-निवेश भी देता है।"},
  {"id":"cdp-pedagogy-subjects-1742","question":"A school measures each Class 3 child’s oral reading fluency as words read correctly per minute. Which interpretation is most accurate?","options":["It indicates fluency but needs pairing with comprehension checks","A high score proves that the child fully understands what she reads","It measures only the child’s pronunciation of difficult words","It is useless and should never be used in schools"],"answer":0,"explanation":"Fluency is closely linked to comprehension, but a child can read fast without understanding; fluency measures need to be paired with comprehension tasks.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"एक विद्यालय कक्षा 3 के हर बच्चे की मौखिक पठन प्रवाहशीलता को प्रति मिनट सही पढ़े गए शब्दों के रूप में मापता है। कौन-सी व्याख्या सबसे सटीक है?","optionsHi":["यह प्रवाह को इंगित करता है, पर इसे बोध-जाँच के साथ जोड़ना आवश्यक है","उच्च अंक सिद्ध करता है कि बच्ची जो पढ़ती है उसे पूरी तरह समझती है","यह केवल कठिन शब्दों के बच्ची के उच्चारण को मापता है","यह निरर्थक है और विद्यालयों में कभी उपयोग नहीं होना चाहिए"],"explanationHi":"प्रवाह बोध से निकटता से जुड़ा है, पर बच्चा बिना समझे भी तेज़ पढ़ सकता है; प्रवाह के माप को बोध-कार्यों के साथ जोड़ना आवश्यक है।"},
  {"id":"cdp-pedagogy-subjects-1743","question":"In communicative language teaching, the teacher’s role is best described as:","options":["The main source of knowledge who lectures and corrects every error","A silent observer who never takes part in the activities","A facilitator who sets up communication and monitors and guides","A drill leader who models sentences for repetition"],"answer":2,"explanation":"CLT moves the teacher from transmitter to facilitator, needs analyst and sometimes co-communicator, organising activities in which learners use language meaningfully.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"संप्रेषणात्मक भाषा शिक्षण में शिक्षक की भूमिका का सबसे अच्छा वर्णन है:","optionsHi":["ज्ञान का मुख्य स्रोत जो व्याख्यान देता है और हर त्रुटि सुधारता है","मौन पर्यवेक्षक जो गतिविधियों में कभी भाग नहीं लेता","सुगमकर्ता जो संप्रेषण की व्यवस्था करता है, तथा निगरानी और मार्गदर्शन करता है","अभ्यास-कवायद का नेता जो दोहराने के लिए वाक्यों का आदर्श प्रस्तुत करता है"],"explanationHi":"CLT शिक्षक को संप्रेषक से सुगमकर्ता, आवश्यकता-विश्लेषक और कभी-कभी सह-संप्रेषक की ओर ले जाता है, ऐसी गतिविधियाँ आयोजित करते हुए जिनमें अधिगमकर्ता भाषा का सार्थक उपयोग करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1744","question":"A Class 4 child with attention difficulties finds it hard to sit through a 40-minute English lesson and often disturbs others. Which classroom adjustment is most suitable?","options":["Making him sit at the back so that he disturbs fewer children","Breaking tasks into short steps with movement breaks and clear routines","Excusing him from English lessons until he can sit still","Giving him the same long tasks as others but with punishment for disturbance"],"answer":1,"explanation":"Short, structured tasks, predictable routines and chances to move help children with attention difficulties stay engaged; isolation and punishment do not.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"ध्यान संबंधी कठिनाइयों वाले कक्षा 4 के एक बच्चे को 40 मिनट का अंग्रेज़ी पाठ पूरा बैठकर सुनना कठिन लगता है और वह प्रायः दूसरों को बाधित करता है। कक्षा का कौन-सा समायोजन सबसे उपयुक्त है?","optionsHi":["उसे पीछे बिठाना ताकि वह कम बच्चों को बाधित करे","कार्यों को छोटे चरणों में बाँटना, गतिविधि-विराम और स्पष्ट दिनचर्याओं के साथ","जब तक वह स्थिर बैठना न सीख ले उसे अंग्रेज़ी पाठों से छूट देना","उसे दूसरों जैसे ही लंबे कार्य देना, पर बाधा डालने पर दंड के साथ"],"explanationHi":"छोटे, संरचित कार्य, पूर्वानुमेय दिनचर्याएँ और हिलने-डुलने के अवसर ध्यान की कठिनाइयों वाले बच्चों को जुड़े रहने में मदद करते हैं; अलग-थलग करना और दंड नहीं।"},
  {"id":"cdp-pedagogy-subjects-1745","question":"A Class 7 student finishes every English task quickly and accurately and has started to look bored. The most appropriate step is to:","options":["Give her more exercises of the same type to keep her busy","Make her correct the work of all her classmates every day","Ask her to sit quietly until the others finish","Offer extension tasks like writing a sequel to the story"],"answer":3,"explanation":"Enrichment should deepen and broaden learning with challenging, creative tasks, not simply add more of the same or turn the student into an assistant.","difficulty":"hard","source":"CTET Paper II · State TETs","questionHi":"कक्षा 7 की एक विद्यार्थी अंग्रेज़ी के हर कार्य को जल्दी और सटीक पूरा करती है और ऊबने लगी है। सबसे उपयुक्त कदम है:","optionsHi":["उसे व्यस्त रखने के लिए उसी प्रकार के और अभ्यास देना","उससे हर दिन अपने सभी सहपाठियों का कार्य सुधरवाना","उससे चुपचाप बैठने को कहना जब तक बाकी पूरा न कर लें","विस्तार-कार्य देना, जैसे कहानी का अगला भाग लिखना"],"explanationHi":"समृद्धि को चुनौतीपूर्ण, रचनात्मक कार्यों से अधिगम को गहरा और व्यापक करना चाहिए, केवल उसी का और देना या विद्यार्थी को सहायक बना देना नहीं।"},
  {"id":"cdp-pedagogy-subjects-1746","question":"Class 8 students compare a Hindi poem with its published English translation and discuss which images or sounds were lost or changed. The main purpose of this activity is to:","options":["Prove that English translations are always inferior to the original","Notice how each language carries meaning and culture differently","Train students to translate word by word for examinations","Replace the reading of English poems in the syllabus"],"answer":1,"explanation":"Comparing an original with its translation sharpens sensitivity to how languages encode meaning, rhythm and culture, using translation as a resource for language awareness.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB","questionHi":"कक्षा 8 के विद्यार्थी एक हिंदी कविता की उसके प्रकाशित अंग्रेज़ी अनुवाद से तुलना करते हैं और चर्चा करते हैं कि कौन-से बिंब या ध्वनियाँ खो गईं या बदल गईं। इस गतिविधि का मुख्य उद्देश्य है:","optionsHi":["यह सिद्ध करना कि अंग्रेज़ी अनुवाद हमेशा मूल से हीन होते हैं","इस पर ध्यान देना कि हर भाषा अर्थ और संस्कृति को अलग ढंग से कैसे वहन करती है","विद्यार्थियों को परीक्षाओं के लिए शब्द-दर-शब्द अनुवाद करना सिखाना","पाठ्यक्रम में अंग्रेज़ी कविताओं के पठन की जगह लेना"],"explanationHi":"मूल की उसके अनुवाद से तुलना इस संवेदनशीलता को पैना करती है कि भाषाएँ अर्थ, लय और संस्कृति को कैसे संकेतित करती हैं, अनुवाद को भाषा-जागरूकता के संसाधन के रूप में उपयोग करते हुए।"},
  {"id":"cdp-pedagogy-subjects-1747","question":"A Class 1 child reads ‘ship’ as ‘s–h–i–p’, saying a separate sound for ‘s’ and ‘h’. The teacher should next teach that:","options":["‘sh’ is a digraph: two letters that stand for one sound","‘ship’ must be memorised as a sight word","The child should spell the word aloud before reading it","‘s’ and ‘h’ are silent letters in this word"],"answer":0,"explanation":"Digraphs such as ‘sh’, ‘ch’ and ‘th’ represent single sounds; knowing them lets the child blend correctly (/ʃ/–/ɪ/–/p/). ‘Ship’ is perfectly decodable once the digraph is known.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"कक्षा 1 का एक बच्चा ‘ship’ को ‘s–h–i–p’ पढ़ता है, ‘s’ और ‘h’ के लिए अलग-अलग ध्वनि बोलते हुए। शिक्षिका को आगे क्या सिखाना चाहिए?","optionsHi":["‘sh’ एक अक्षर-युग्म (digraph) है: दो अक्षर जो एक ध्वनि के लिए हैं","‘ship’ को दृष्टि-शब्द (sight word) के रूप में याद करना होगा","बच्चे को पढ़ने से पहले शब्द की वर्तनी ज़ोर से बोलनी चाहिए","इस शब्द में ‘s’ और ‘h’ मौन अक्षर हैं"],"explanationHi":"‘sh’, ‘ch’ और ‘th’ जैसे अक्षर-युग्म एकल ध्वनियों को निरूपित करते हैं; उन्हें जानने से बच्चा सही मिलान कर पाता है (/ʃ/–/ɪ/–/p/)। अक्षर-युग्म ज्ञात होने पर ‘ship’ पूरी तरह विसंकेतन-योग्य है।"},
  {"id":"cdp-pedagogy-subjects-1748","question":"Each morning a Class 1 teacher writes a short message on the board (‘Good morning! Today is Monday. We will plant seeds.’) and reads it with the children, pointing to the words. The main value of this routine is that it:","options":["Replaces the need for storybooks in the classroom","Tests which children can read the date correctly","Gives meaningful daily reading and models writing","Mainly teaches children the days of the week"],"answer":2,"explanation":"A ‘morning message’ is real, predictable text about the children’s own day, so it builds concepts of print, sight words and the idea that writing carries meaning.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS","questionHi":"हर सुबह कक्षा 1 की शिक्षिका श्यामपट्ट पर एक छोटा संदेश लिखती है (‘Good morning! Today is Monday. We will plant seeds.’) और शब्दों की ओर संकेत करते हुए बच्चों के साथ उसे पढ़ती है। इस दिनचर्या का मुख्य मूल्य यह है कि यह:","optionsHi":["कक्षा में कहानी की किताबों की आवश्यकता की जगह लेती है","जाँचती है कि कौन-से बच्चे तारीख सही पढ़ सकते हैं","सार्थक दैनिक पठन देती है और लेखन का आदर्श प्रस्तुत करती है","मुख्यतः बच्चों को सप्ताह के दिन सिखाती है"],"explanationHi":"‘सुबह का संदेश’ बच्चों के अपने दिन के बारे में वास्तविक, पूर्वानुमेय पाठ है, इसलिए यह छपाई की अवधारणाएँ, दृष्टि-शब्द और यह विचार बनाता है कि लेखन में अर्थ होता है।"},
  {"id":"cdp-pedagogy-subjects-1749","question":"A teacher wants Class 3 children to learn ‘at’, ‘on’ and ‘in’ with time expressions. Which plan teaches them in a meaningful context?","options":["Giving the rule and 20 unrelated blanks to fill in","Correcting children’s mistakes with these words in their notebooks only","Asking children to memorise lists of times, days and months","Using the timetable and a festival calendar (‘Diwali is in November’)"],"answer":3,"explanation":"The timetable and calendar give real, familiar contexts in which the contrast (at with clock times, on with days and dates, in with months) is needed and used.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"एक शिक्षिका चाहती है कि कक्षा 3 के बच्चे समय की अभिव्यक्तियों के साथ ‘at’, ‘on’ और ‘in’ सीखें। कौन-सी योजना उन्हें सार्थक संदर्भ में सिखाती है?","optionsHi":["नियम देना और भरने के लिए 20 असंबद्ध रिक्त स्थान देना","बच्चों की कॉपियों में इन शब्दों की गलतियाँ केवल सुधारना","बच्चों से समयों, दिनों और महीनों की सूचियाँ रटवाना","समय-सारणी और त्योहार-कैलेंडर का उपयोग करना (‘Diwali is in November’)"],"explanationHi":"समय-सारणी और कैलेंडर वास्तविक, परिचित संदर्भ देते हैं जिनमें अंतर (घड़ी के समय के साथ at, दिनों और तारीखों के साथ on, महीनों के साथ in) की आवश्यकता होती है और उसका उपयोग होता है।"},
  {"id":"cdp-pedagogy-subjects-1750","question":"After each group presentation, Class 6 students give peer feedback as ‘two stars and a wish’: two things that worked well and one thing to improve. The main value of this format is that it:","options":["Replaces the teacher’s feedback completely","Lets students give marks to each other for the term report card","Avoids any mention of weaknesses so that nobody gets upset","Makes feedback specific and balanced, so it is easy to act on"],"answer":3,"explanation":"Naming strengths alongside one clear target keeps feedback constructive and focused, and teaches students to look at work against criteria.","difficulty":"hard","source":"CTET Paper I · State TETs","questionHi":"हर समूह प्रस्तुति के बाद कक्षा 6 के विद्यार्थी सहपाठी प्रतिपुष्टि ‘दो सितारे और एक इच्छा’ के रूप में देते हैं: दो बातें जो अच्छी रहीं और एक जिसमें सुधार हो। इस प्रारूप का मुख्य मूल्य यह है कि यह:","optionsHi":["शिक्षिका की प्रतिपुष्टि को पूरी तरह बदल देता है","विद्यार्थियों को सत्रांत रिपोर्ट कार्ड के लिए एक-दूसरे को अंक देने देता है","कमज़ोरियों का कोई ज़िक्र ही नहीं करता ताकि कोई परेशान न हो","प्रतिपुष्टि को विशिष्ट और संतुलित बनाता है, जिससे उस पर कार्य करना आसान होता है"],"explanationHi":"एक स्पष्ट लक्ष्य के साथ शक्तियों का नाम लेना प्रतिपुष्टि को रचनात्मक और केंद्रित रखता है, और विद्यार्थियों को कार्य को मानदंडों के आधार पर देखना सिखाता है।"},
  {"id":"cdp-pedagogy-subjects-1751","question":"In a Hindi writing task, a Class I child writes ‘मेर नम सत ह’ for ‘मेरा नाम सीता है’. Every consonant is right and in the right order, but no matras are written. What does this most likely show?","options":["A visual-processing difficulty, because she drops the small marks written above, below and beside letters","That she copies letter shapes from memory and has not yet linked the printed letters with sounds","A systematic early stage: she hears each akshar and writes its base consonant, but has yet to mark vowels","That she does not yet hear the vowel sounds in spoken words and needs hearing and speech screening"],"answer":2,"explanation":"Writing the right consonant for each syllable, in order, shows she is mapping sounds to print; the vowel signs are the next layer to build, as with invented spelling. Because the letters match the sounds, it is not rote copying or a disorder.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"हिंदी लेखन कार्य में कक्षा I की एक बच्ची ‘मेरा नाम सीता है’ के लिए ‘मेर नम सत ह’ लिखती है। हर व्यंजन सही और सही क्रम में है, पर कोई मात्रा नहीं लिखी गई। यह संभवतः क्या दर्शाता है?","optionsHi":["दृश्य-संसाधन की कठिनाई, क्योंकि वह अक्षरों के ऊपर, नीचे और बगल में लिखे छोटे चिह्न छोड़ देती है","कि वह अक्षरों के आकार स्मृति से उतारती है और अभी छपे अक्षरों को ध्वनियों से नहीं जोड़ पाई है","एक व्यवस्थित आरंभिक अवस्था: वह हर अक्षर को सुनती है और उसका आधार व्यंजन लिखती है, पर अभी स्वरों को चिह्नित करना बाकी है","कि वह अभी बोले गए शब्दों में स्वर ध्वनियाँ नहीं सुन पाती और उसे श्रवण तथा वाक् जाँच की आवश्यकता है"],"explanationHi":"क्रम में हर शब्दांश के लिए सही व्यंजन लिखना दिखाता है कि वह ध्वनियों को छपाई से जोड़ रही है; स्वर-चिह्न अगली परत हैं जिन्हें बनाना है, जैसा आविष्कृत वर्तनी में होता है। क्योंकि अक्षर ध्वनियों से मेल खाते हैं, यह रटकर उतारना या विकार नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1752","question":"During a Class 4 maths lesson taught in Hindi, a child reads ‘अंश 3, हर 4’ and asks, ‘हर का मतलब तो हर एक होता है न?’ Which idea from language across the curriculum best describes what the teacher must now do?","options":["Treat ‘हर’ as a subject-register word whose special meaning must be built explicitly, in context, in the maths class","Switch to English terms such as ‘denominator’, because technical words in English carry only a single meaning","Send the child to the Hindi teacher, since the confusion reveals a gap in general vocabulary for the language period","Give the class a glossary of all fraction terms to memorise before any further work on fractions is attempted"],"answer":0,"explanation":"Every subject has its own register, and everyday words used with a special meaning (हर = denominator) must be taught by the subject teacher in context. Language learning is every teacher's job, and memorised glossaries do not build meaning.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"हिंदी में पढ़ाए जा रहे कक्षा 4 के गणित पाठ में एक बच्चा पढ़ता है ‘अंश 3, हर 4’ और पूछता है, ‘हर का मतलब तो हर एक होता है न?’ पाठ्यचर्या में भाषा के किस विचार से सबसे अच्छी तरह वर्णित होता है कि शिक्षिका को अब क्या करना चाहिए?","optionsHi":["‘हर’ को विषय-प्रयुक्ति (register) का शब्द मानना जिसका विशेष अर्थ गणित की कक्षा में संदर्भ सहित स्पष्ट रूप से बनाना होगा","‘denominator’ जैसे अंग्रेज़ी शब्दों पर चले जाना, क्योंकि अंग्रेज़ी में तकनीकी शब्दों का केवल एक अर्थ होता है","बच्चे को हिंदी शिक्षिका के पास भेजना, क्योंकि यह उलझन सामान्य शब्दावली की कमी दिखाती है जो भाषा के पीरियड के लिए है","भिन्नों पर आगे कोई काम करने से पहले कक्षा को सभी भिन्न-शब्दों की शब्द-सूची रटने के लिए देना"],"explanationHi":"हर विषय की अपनी प्रयुक्ति होती है, और विशेष अर्थ के साथ प्रयुक्त रोज़मर्रा के शब्द (हर = denominator) विषय-शिक्षक द्वारा संदर्भ में पढ़ाए जाने चाहिए। भाषा सीखना हर शिक्षक का काम है, और रटी गई शब्द-सूचियाँ अर्थ नहीं बनातीं।"},
  {"id":"cdp-pedagogy-subjects-1753","question":"A three-and-a-half-year-old Hindi-speaking child says, ‘कल मैं नानी के घर जाया था।’ No adult around her uses ‘जाया’. The best interpretation is that she:","options":["is copying a non-standard form heard at home, showing that speech is learnt mainly by imitation","has a vocabulary delay, because by this age children should know the past forms of common verbs","is confusing the present and past tenses, which children usually sort out only after starting school","is applying the regular past-tense pattern (-या) to an irregular verb, a sign of active rule-making"],"answer":3,"explanation":"‘जाया’ follows the regular pattern (खाया, आया) and is not heard from adults, so it cannot be imitation; it shows the child has extracted a rule and over-applied it, just like ‘goed’ in English.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"साढ़े तीन वर्ष की एक हिंदी भाषी बच्ची कहती है, ‘कल मैं नानी के घर जाया था।’ उसके आसपास कोई वयस्क ‘जाया’ का उपयोग नहीं करता। सबसे अच्छी व्याख्या यह है कि वह:","optionsHi":["घर में सुने किसी अमानक रूप की नकल कर रही है, जो दिखाता है कि वाणी मुख्यतः अनुकरण से सीखी जाती है","उसकी शब्दावली में देरी है, क्योंकि इस आयु तक बच्चों को सामान्य क्रियाओं के भूतकाल रूप आ जाने चाहिए","वर्तमान और भूतकाल को उलझा रही है, जिन्हें बच्चे प्रायः विद्यालय जाने के बाद ही अलग कर पाते हैं","अनियमित क्रिया पर नियमित भूतकाल पैटर्न (-या) लागू कर रही है, जो सक्रिय नियम-निर्माण का संकेत है"],"explanationHi":"‘जाया’ नियमित पैटर्न (खाया, आया) का पालन करता है और वयस्कों से नहीं सुना जाता, इसलिए यह अनुकरण नहीं हो सकता; यह दिखाता है कि बच्ची ने नियम निकाल लिया है और उसे अति-लागू किया है, ठीक अंग्रेज़ी के ‘goed’ की तरह।"},
  {"id":"cdp-pedagogy-subjects-1754","question":"Moumita, whose home language is Bengali (which has no grammatical gender), joins a Hindi-medium Class 3 and says ‘मेरा किताब’ and ‘बस आया’. Which response by the teacher is most sound?","options":["Teach the rule that nouns ending in -ई are feminine and those ending in -आ are masculine, so that she can work out the gender of new nouns","Give rich, meaningful exposure and recast her sentences naturally, as Hindi noun gender is learnt word by word through use","Correct each gender error the moment it occurs, so that the wrong forms do not settle into fixed habits","Explain that gender follows meaning, so objects linked with women or softness take the feminine forms"],"answer":1,"explanation":"Hindi noun gender is largely arbitrary (पानी and दही are masculine, किताब and बस are feminine), so the -ई/-आ rule misleads and the meaning rule is false. It is acquired through plenty of meaningful input and gentle recasts, not constant interruption.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"मौमिता, जिसकी घरेलू भाषा बांग्ला है (जिसमें व्याकरणिक लिंग नहीं होता), हिंदी माध्यम की कक्षा 3 में आती है और कहती है ‘मेरा किताब’ और ‘बस आया’। शिक्षिका की कौन-सी प्रतिक्रिया सबसे सही है?","optionsHi":["यह नियम पढ़ाना कि -ई से अंत होने वाले संज्ञा स्त्रीलिंग और -आ से अंत होने वाले पुल्लिंग होते हैं, ताकि वह नए संज्ञाओं का लिंग निकाल सके","समृद्ध, सार्थक संपर्क देना और उसके वाक्यों को स्वाभाविक रूप से दोहराकर सुधारना (recast), क्योंकि हिंदी संज्ञाओं का लिंग शब्द-दर-शब्द प्रयोग के माध्यम से सीखा जाता है","हर लिंग-त्रुटि को होते ही सुधारना, ताकि गलत रूप पक्की आदत न बन जाएँ","समझाना कि लिंग अर्थ का अनुसरण करता है, इसलिए स्त्रियों या कोमलता से जुड़ी वस्तुएँ स्त्रीलिंग रूप लेती हैं"],"explanationHi":"हिंदी में संज्ञा का लिंग बड़ी हद तक मनमाना है (पानी और दही पुल्लिंग हैं, किताब और बस स्त्रीलिंग), इसलिए -ई/-आ वाला नियम भ्रामक है और अर्थ वाला नियम गलत है। यह बहुत-से सार्थक निवेश और कोमल पुनःरूपण से अर्जित होता है, लगातार टोकने से नहीं।"},
  {"id":"cdp-pedagogy-subjects-1755","question":"In a Kendriya Vidyalaya in Chennai, Class 7 learners of Hindi write both ‘मैं कल फ़िल्म देखा’ and ‘राम ने घर गया’. What do these two errors, taken together, most strongly suggest?","options":["The learners have not yet been taught the past tense and are guessing forms from the present tense","The errors are careless slips, because a learner who knew no rule would not make two opposite mistakes","The learners know that ‘ने’ exists but are unsure when it applies, a normal interlanguage stage","The learners are carrying Tamil word order into Hindi, so the subject, object and verb end up in the wrong positions"],"answer":2,"explanation":"‘ने’ is needed with transitive verbs in the perfective (मैंने फ़िल्म देखी) but not with intransitive ones (राम घर गया). Leaving it out in one and over-using it in the other shows a partly formed rule; Tamil, like Hindi, is verb-final, so word order is not the issue.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2","questionHi":"चेन्नई के एक केंद्रीय विद्यालय में हिंदी सीखने वाले कक्षा 7 के विद्यार्थी ‘मैं कल फ़िल्म देखा’ और ‘राम ने घर गया’ दोनों लिखते हैं। ये दोनों त्रुटियाँ मिलाकर सबसे प्रबल रूप से क्या सुझाती हैं?","optionsHi":["विद्यार्थियों को अभी भूतकाल नहीं पढ़ाया गया है और वे वर्तमान काल से रूपों का अनुमान लगा रहे हैं","त्रुटियाँ लापरवाही की चूकें हैं, क्योंकि जिसे कोई नियम नहीं आता वह दो विपरीत गलतियाँ नहीं करेगा","विद्यार्थी जानते हैं कि ‘ने’ होता है पर अनिश्चित हैं कि वह कब लगता है, जो अंतर्भाषा की सामान्य अवस्था है","विद्यार्थी तमिल का शब्द-क्रम हिंदी में ले आ रहे हैं, इसलिए कर्ता, कर्म और क्रिया गलत स्थानों पर आ जाते हैं"],"explanationHi":"‘ने’ पूर्ण भूतकाल में सकर्मक क्रियाओं के साथ आवश्यक है (मैंने फ़िल्म देखी) पर अकर्मक के साथ नहीं (राम घर गया)। एक में छोड़ना और दूसरे में अति-प्रयोग करना आंशिक रूप से बना नियम दिखाता है; तमिल, हिंदी की तरह, क्रिया-अंत भाषा है, इसलिए शब्द-क्रम मुद्दा नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1756","question":"A Class 3 Hindi teacher writes the prose meaning (भावार्थ) of each line of a बालगीत on the board and has children memorise it for the test. Which criticism is most accurate?","options":["It turns the poem into a prose passage, losing the rhythm, images and personal response that poetry at this stage aims to build","The real problem is that children should memorise the poem itself, since recitation rather than meaning is the aim of poetry","Prose meanings are useful, but only after children have first memorised a word list of every difficult word in the poem","The method is sound, because written tests at this stage mainly check whether children know the meaning of each line"],"answer":0,"explanation":"At the primary stage poetry is for enjoyment: rhythm, sound, imagery and the child's own response. Line-by-line paraphrase for memorising kills that, while mere recitation without engagement is not the aim either.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 3 की एक हिंदी शिक्षिका श्यामपट्ट पर बालगीत की हर पंक्ति का गद्य अर्थ (भावार्थ) लिखती है और बच्चों से परीक्षा के लिए उसे रटवाती है। कौन-सी आलोचना सबसे सटीक है?","optionsHi":["यह कविता को गद्यांश में बदल देता है, जिससे लय, बिंब और व्यक्तिगत प्रतिक्रिया खो जाती है जिन्हें इस स्तर पर कविता बनाना चाहती है","वास्तविक समस्या यह है कि बच्चों को कविता स्वयं रटनी चाहिए, क्योंकि कविता का उद्देश्य अर्थ नहीं, सस्वर पाठ है","गद्य-अर्थ उपयोगी हैं, पर तभी जब बच्चे पहले कविता के हर कठिन शब्द की शब्द-सूची रट लें","यह तरीका सही है, क्योंकि इस स्तर पर लिखित परीक्षाएँ मुख्यतः यह जाँचती हैं कि बच्चे हर पंक्ति का अर्थ जानते हैं या नहीं"],"explanationHi":"प्राथमिक स्तर पर कविता आनंद के लिए है: लय, ध्वनि, बिंब और बच्चे की अपनी प्रतिक्रिया। रटने के लिए पंक्ति-दर-पंक्ति भावार्थ उसे मार देता है, जबकि बिना जुड़ाव के केवल सस्वर पाठ भी उद्देश्य नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1757","question":"A Class 3 child's dictation shows ‘दीन’ for ‘दिन’, ‘पुरा’ for ‘पूरा’ and ‘कीताब’ for ‘किताब’, though every consonant is correct. Which plan most directly targets this pattern?","options":["Daily choral chanting of the full बारहखड़ी until every vowel sign can be recited in order without a single mistake","Copying each misspelt word correctly ten times, so that the right visual form becomes fixed in memory","Teaching the rule that ‘ि’ is written before the consonant and ‘ी’ after it, with daily practice in placing each sign","Oral games contrasting short and long vowels in meaningful pairs (दिन–दीन, कुल–कूल), then linking each to its matra"],"answer":3,"explanation":"The errors are all short/long vowel (ह्रस्व–दीर्घ) confusions, so the child needs to hear and contrast vowel length in meaningful words and then link it to the sign. The position of ‘ि’ is not her problem, and chanting or copying does not build the distinction.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"कक्षा 3 के एक बच्चे के श्रुतलेख में ‘दिन’ के लिए ‘दीन’, ‘पूरा’ के लिए ‘पुरा’ और ‘किताब’ के लिए ‘कीताब’ दिखता है, यद्यपि हर व्यंजन सही है। कौन-सी योजना इस पैटर्न को सबसे सीधे लक्षित करती है?","optionsHi":["पूरी बारहखड़ी का दैनिक सामूहिक पाठ, जब तक हर स्वर-चिह्न बिना एक भी गलती के क्रम से बोला न जा सके","हर गलत वर्तनी वाले शब्द को सही-सही दस बार उतारना, ताकि सही दृश्य रूप स्मृति में पक्का हो जाए","यह नियम पढ़ाना कि ‘ि’ व्यंजन से पहले और ‘ी’ उसके बाद लिखी जाती है, हर चिह्न को रखने के दैनिक अभ्यास के साथ","सार्थक युग्मों (दिन–दीन, कुल–कूल) में ह्रस्व और दीर्घ स्वरों की तुलना वाले मौखिक खेल, फिर हर एक को उसकी मात्रा से जोड़ना"],"explanationHi":"सभी त्रुटियाँ ह्रस्व–दीर्घ स्वर की उलझनें हैं, इसलिए बच्चे को सार्थक शब्दों में स्वर की लंबाई को सुनना और तुलना करना और फिर उसे चिह्न से जोड़ना आवश्यक है। ‘ि’ की स्थिति उसकी समस्या नहीं है, और सामूहिक पाठ या उतारना भेद नहीं बनाते।"},
  {"id":"cdp-pedagogy-subjects-1758","question":"Hindi-medium Class 7 students can recite that ‘वाष्पोत्सर्जन पत्तियों से होता है’ but cannot explain it. What should the science teacher do first?","options":["Replace the Hindi terms with the English ones, which students will need anyway in higher classes","Build the idea through observation (a bag tied over a leafy twig), then give the term and its parts, वाष्प + उत्सर्जन","Ask the Hindi teacher to teach such words as examples of sandhi in the grammar period, so that their meaning becomes clear","Start each chapter with a list of new terms and their meanings, and test the list before the lesson begins"],"answer":1,"explanation":"The concept must come before the label: once students have seen water collect in a bag around a leafy twig, the technical word, broken into meaningful parts, names something they understand. Switching language or memorising glossaries leaves the concept unbuilt.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"हिंदी माध्यम की कक्षा 7 के विद्यार्थी दोहरा सकते हैं कि ‘वाष्पोत्सर्जन पत्तियों से होता है’ पर उसे समझा नहीं सकते। विज्ञान शिक्षक को सबसे पहले क्या करना चाहिए?","optionsHi":["हिंदी शब्दों की जगह अंग्रेज़ी शब्द देना, जिनकी विद्यार्थियों को ऊँची कक्षाओं में वैसे भी आवश्यकता होगी","अवलोकन से विचार बनाना (पत्तेदार टहनी पर बँधी थैली), फिर शब्द और उसके भाग देना, वाष्प + उत्सर्जन","हिंदी शिक्षक से कहना कि ऐसे शब्द व्याकरण के पीरियड में संधि के उदाहरण के रूप में पढ़ाए ताकि उनका अर्थ स्पष्ट हो","हर अध्याय की शुरुआत नए शब्दों और उनके अर्थों की सूची से करना, और पाठ शुरू होने से पहले उस सूची की परीक्षा लेना"],"explanationHi":"संकल्पना नाम से पहले आनी चाहिए: जब विद्यार्थी पत्तेदार टहनी के चारों ओर थैली में पानी इकट्ठा होते देख लेते हैं, तो अर्थपूर्ण भागों में विभाजित तकनीकी शब्द किसी ऐसी चीज़ का नाम होता है जिसे वे समझते हैं। भाषा बदलना या शब्द-सूचियाँ रटना संकल्पना को अनिर्मित छोड़ देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1759","question":"Consider these statements about languages in the NCF for School Education 2023: 1. R1 is ideally the child's home language or a familiar language, used for early literacy. 2. R2 can be any language other than R1, including English. 3. All three languages, R1, R2 and R3, must be native to India. 4. R3 is generally introduced in the Middle Stage. Which are correct?","options":["1 and 3 only","2, 3 and 4 only","1, 2 and 4 only","1, 2, 3 and 4"],"answer":2,"explanation":"Following NEP 2020, at least two of the three languages must be native to India, not all three, so statement 3 is wrong; English can be R2 or R3, and R3 usually begins in the Middle Stage.","difficulty":"hard","source":"CTET · KVS · NVS · DSSSB","questionHi":"स्कूली शिक्षा के लिए NCF 2023 में भाषाओं के बारे में निम्नलिखित कथनों पर विचार कीजिए: 1. R1 आदर्श रूप से बच्चे की घरेलू भाषा या परिचित भाषा है, जिसका उपयोग प्रारंभिक साक्षरता के लिए होता है। 2. R2 R1 के अलावा कोई भी भाषा हो सकती है, अंग्रेज़ी सहित। 3. तीनों भाषाएँ, R1, R2 और R3, भारत की मूल भाषाएँ होनी चाहिए। 4. R3 सामान्यतः मध्य चरण में आरंभ की जाती है। कौन-से सही हैं?","optionsHi":["केवल 1 और 3","केवल 2, 3 और 4","केवल 1, 2 और 4","1, 2, 3 और 4"],"explanationHi":"NEP 2020 के अनुसार, तीन में से कम से कम दो भाषाएँ भारत की मूल भाषाएँ होनी चाहिए, तीनों नहीं, इसलिए कथन 3 गलत है; अंग्रेज़ी R2 या R3 हो सकती है, और R3 सामान्यतः मध्य चरण में शुरू होती है।"},
  {"id":"cdp-pedagogy-subjects-1760","question":"Class 6 students in a Bengaluru school, learning Hindi as a second language, understand spoken Hindi from films and songs but cannot read Devanagari. Which starting point makes best use of what they bring?","options":["Use songs and dialogues they already know orally as first reading texts, so decoding rests on familiar language","Begin with the full varnamala chart in order, since reading cannot really start until every single letter is known","Write Hindi in the Roman script at first, since the students can already read English letters","Teach the main grammar rules of Hindi first, so that reading later becomes simply a matter of applying them to texts"],"answer":0,"explanation":"Texts whose language children already know orally let them check their decoding against meaning, which speeds up learning the script. Romanised Hindi delays the script, and grammar-first or alphabet-first ignores their oral strength.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2","questionHi":"बेंगलुरु के एक विद्यालय में द्वितीय भाषा के रूप में हिंदी सीख रहे कक्षा 6 के विद्यार्थी फ़िल्मों और गानों से बोली जाने वाली हिंदी समझते हैं पर देवनागरी नहीं पढ़ सकते। कौन-सा आरंभ-बिंदु उनके पास जो है उसका सबसे अच्छा उपयोग करता है?","optionsHi":["उन गानों और संवादों को पहले पठन-पाठों के रूप में उपयोग करना जिन्हें वे मौखिक रूप से जानते हैं, ताकि विसंकेतन परिचित भाषा पर टिके","क्रम में पूरे वर्णमाला चार्ट से शुरू करना, क्योंकि पठन तब तक वास्तव में शुरू नहीं हो सकता जब तक हर अक्षर ज्ञात न हो","शुरू में हिंदी को रोमन लिपि में लिखना, क्योंकि विद्यार्थी पहले से अंग्रेज़ी अक्षर पढ़ सकते हैं","पहले हिंदी के मुख्य व्याकरण-नियम पढ़ाना, ताकि बाद में पठन केवल उन्हें पाठों पर लागू करने की बात हो"],"explanationHi":"जिन पाठों की भाषा बच्चे मौखिक रूप से जानते हैं, वे उन्हें अपने विसंकेतन को अर्थ से जाँचने देते हैं, जिससे लिपि सीखना तेज़ होता है। रोमन हिंदी लिपि को टालती है, और व्याकरण-पहले या वर्णमाला-पहले उनकी मौखिक शक्ति की अनदेखी करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1761","question":"Asked to write a Hindi essay on ‘मेरा प्रिय त्योहार’, almost all 40 students in a Class 8 submit near-identical essays memorised from a guidebook. Which change to the task would best assess their real writing ability?","options":["Have them write on the same topic again in class under close supervision, with guidebooks kept away","Cut marks for any essay longer than 150 words, so that long memorised passages become pointless","Mark only spelling and grammar, since the content of the essays is identical and so cannot be compared fairly","Set a situation from their own lives, such as a letter to a cousin about last Eid or Diwali in your lane"],"answer":3,"explanation":"A specific, personal situation cannot be met with a memorised text, so it shows how students actually organise ideas and use language. Supervision does not stop recall of a memorised essay, and marking only accuracy ignores expression.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"‘मेरा प्रिय त्योहार’ पर हिंदी निबंध लिखने को कहे जाने पर कक्षा 8 के लगभग सभी 40 विद्यार्थी गाइड-पुस्तक से रटे लगभग समान निबंध जमा करते हैं। कार्य में कौन-सा बदलाव उनकी वास्तविक लेखन-क्षमता का सबसे अच्छा आकलन करेगा?","optionsHi":["उन्हें उसी विषय पर कक्षा में निकट पर्यवेक्षण में फिर लिखवाना, गाइड-पुस्तकों को दूर रखते हुए","150 शब्दों से लंबे किसी भी निबंध के अंक काटना, ताकि लंबे रटे गद्यांश निरर्थक हो जाएँ","केवल वर्तनी और व्याकरण पर अंक देना, क्योंकि निबंधों की विषय-वस्तु समान है और इसलिए उनकी निष्पक्ष तुलना नहीं हो सकती","उनके अपने जीवन की कोई स्थिति देना, जैसे पिछली ईद या दिवाली के बारे में अपने चचेरे भाई को पत्र, अपनी गली में"],"explanationHi":"कोई विशिष्ट, व्यक्तिगत स्थिति रटे पाठ से पूरी नहीं हो सकती, इसलिए वह दिखाती है कि विद्यार्थी वास्तव में विचारों को कैसे व्यवस्थित करते और भाषा का उपयोग कैसे करते हैं। पर्यवेक्षण रटे निबंध के स्मरण को नहीं रोकता, और केवल शुद्धता पर अंक देना अभिव्यक्ति की अनदेखी करता है।"},
  {"id":"cdp-pedagogy-subjects-1762","question":"A Class I Hindi teacher says, ‘कमल में से ‘क’ हटा दो, क्या बचा?’ and children answer ‘मल’. The game is done only orally. It mainly builds:","options":["phonics, because children link the letter ‘क’ with the sound it stands for","phonological awareness at the akshar (syllable) level","phonemic awareness at the level of single consonant sounds","concepts of print, since children learn where a word begins"],"answer":1,"explanation":"‘क’ here is the whole syllable /ka/, and removing it from ‘कमल’ leaves ‘मल’; the task is oral syllable deletion. No print is involved, so it is not phonics or print awareness, and no single phoneme is isolated.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा I की एक हिंदी शिक्षिका कहती है, ‘कमल में से ‘क’ हटा दो, क्या बचा?’ और बच्चे उत्तर देते हैं ‘मल’। यह खेल केवल मौखिक रूप से होता है। यह मुख्यतः क्या बनाता है?","optionsHi":["वर्ण-ध्वनि संबंध (phonics), क्योंकि बच्चे अक्षर ‘क’ को उसकी ध्वनि से जोड़ते हैं","अक्षर (शब्दांश) के स्तर पर ध्वनि-जागरूकता (phonological awareness)","एकल व्यंजन ध्वनियों के स्तर पर स्वनिम-जागरूकता (phonemic awareness)","छपाई की अवधारणाएँ, क्योंकि बच्चे सीखते हैं कि शब्द कहाँ से शुरू होता है"],"explanationHi":"यहाँ ‘क’ पूरा शब्दांश /ka/ है, और उसे ‘कमल’ से हटाने पर ‘मल’ बचता है; कार्य मौखिक शब्दांश-लोप है। इसमें कोई छपाई शामिल नहीं है, इसलिए यह phonics या छपाई-जागरूकता नहीं है, और कोई एकल स्वनिम अलग नहीं किया गया है।"},
  {"id":"cdp-pedagogy-subjects-1763","question":"NCERT's ‘बरखा’ series of graded storybooks for Classes 1 and 2 is designed mainly so that children:","options":["learn the varnamala one letter at a time, with each book built around a new letter","practise neat copying, since every page gives a model sentence for children to trace","read on their own, for pleasure and meaning, through short everyday stories graded by level","learn moral values, as every story ends with a clearly stated lesson for class discussion"],"answer":2,"explanation":"Barkha is a supplementary graded reading series of short stories from children's everyday lives in natural language, meant to help them become independent readers who read with enjoyment and understanding.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 1 और 2 के लिए NCERT की ‘बरखा’ श्रृंखला की श्रेणीबद्ध कहानी-पुस्तकें मुख्यतः इसलिए बनाई गई हैं ताकि बच्चे:","optionsHi":["एक-एक अक्षर करके वर्णमाला सीखें, हर पुस्तक एक नए अक्षर पर बनी हो","साफ़-सुथरी नकल का अभ्यास करें, क्योंकि हर पृष्ठ पर एक आदर्श वाक्य है जिसे बच्चे दोहराएँ","स्तर के अनुसार श्रेणीबद्ध छोटी रोज़मर्रा की कहानियों के माध्यम से आनंद और अर्थ के लिए स्वयं पढ़ें","नैतिक मूल्य सीखें, क्योंकि हर कहानी कक्षा-चर्चा के लिए स्पष्ट रूप से कही गई सीख के साथ समाप्त होती है"],"explanationHi":"बरखा बच्चों के रोज़मर्रा के जीवन की प्राकृतिक भाषा में छोटी कहानियों की पूरक श्रेणीबद्ध पठन-श्रृंखला है, जो उन्हें आनंद और समझ के साथ पढ़ने वाले स्वतंत्र पाठक बनने में मदद करने के लिए है।"},
  {"id":"cdp-pedagogy-subjects-1764","question":"A Class 2 child writes ‘परेम’ for ‘प्रेम’ and ‘करम’ for ‘कर्म’. What does this most likely reveal?","options":["She hears every sound but writes each as a full akshar, not yet knowing how clusters are joined (half letters, रेफ)","She cannot hear the /r/ sound inside such words and needs listening drills on that sound before more writing","She is confusing ‘र’ with the vowel ‘ऋ’, which is why she adds an extra syllable","She is carrying the spelling patterns of English words into Hindi, so she adds a vowel between the two consonants"],"answer":0,"explanation":"Both spellings contain every sound in the right order; she simply writes a vowel-bearing full letter where Hindi writes a cluster (प्र, र्म). She needs to learn the conjunct conventions through familiar words, not hearing drills.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 2 की एक बच्ची ‘प्रेम’ के लिए ‘परेम’ और ‘कर्म’ के लिए ‘करम’ लिखती है। यह संभवतः क्या प्रकट करता है?","optionsHi":["वह हर ध्वनि सुनती है पर हर एक को पूरे अक्षर के रूप में लिखती है, अभी यह नहीं जानती कि संयुक्ताक्षर कैसे जुड़ते हैं (आधे अक्षर, रेफ)","वह ऐसे शब्दों के भीतर /r/ ध्वनि नहीं सुन सकती और अधिक लेखन से पहले उस ध्वनि पर श्रवण-अभ्यास की आवश्यकता है","वह ‘र’ को स्वर ‘ऋ’ से उलझा रही है, इसीलिए वह एक अतिरिक्त शब्दांश जोड़ती है","वह अंग्रेज़ी शब्दों की वर्तनी के पैटर्न हिंदी में ला रही है, इसलिए दो व्यंजनों के बीच एक स्वर जोड़ती है"],"explanationHi":"दोनों वर्तनियों में हर ध्वनि सही क्रम में है; वह केवल वहाँ स्वर-युक्त पूरा अक्षर लिखती है जहाँ हिंदी संयुक्ताक्षर (प्र, र्म) लिखती है। उसे परिचित शब्दों के माध्यम से संयुक्ताक्षर की परिपाटियाँ सीखनी हैं, श्रवण-अभ्यास नहीं।"},
  {"id":"cdp-pedagogy-subjects-1765","question":"Which way of teaching ‘विशेषण’ to Class 6 best reflects a contextual, inductive approach to grammar?","options":["Give the definition with five examples, then set an exercise in which students underline the adjectives in sentences","Have students learn the kinds of विशेषण (गुणवाचक, संख्यावाचक and so on) with two examples of each","Define ‘विशेषण’ first and then ask students to find adjectives in the lesson they have just read","Children describe objects from a bag, list the describing words they used, notice their job, then get the term"],"answer":3,"explanation":"Inductive grammar moves from use to noticing to naming: children first use describing words for real, then see what they do, and only then get the label. The other options all start from the definition.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 को ‘विशेषण’ पढ़ाने का कौन-सा तरीका व्याकरण के संदर्भगत, आगमनात्मक उपागम को सबसे अच्छी तरह दर्शाता है?","optionsHi":["पाँच उदाहरणों के साथ परिभाषा देना, फिर ऐसा अभ्यास देना जिसमें विद्यार्थी वाक्यों में विशेषणों को रेखांकित करें","विद्यार्थियों से विशेषण के भेद (गुणवाचक, संख्यावाचक आदि) हर एक के दो उदाहरणों के साथ सीखवाना","पहले ‘विशेषण’ को परिभाषित करना और फिर विद्यार्थियों से अभी पढ़े पाठ में विशेषण खोजने को कहना","बच्चों का थैले से निकाली वस्तुओं का वर्णन करना, प्रयुक्त वर्णन-शब्दों की सूची बनाना, उनके कार्य पर ध्यान देना, फिर शब्द पाना"],"explanationHi":"आगमनात्मक व्याकरण प्रयोग से ध्यान देने और फिर नामकरण की ओर बढ़ता है: बच्चे पहले वर्णन-शब्दों का वास्तविक उपयोग करते हैं, फिर देखते हैं कि वे क्या करते हैं, और केवल तब उन्हें नाम मिलता है। अन्य सभी विकल्प परिभाषा से शुरू करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1766","question":"Class 7 students memorise 50 मुहावरे with meanings from a guide, yet in their writing they misuse them, for example ‘उसने आँखें चुराकर किताब पढ़ी’ to mean ‘he read carefully’. What is the best way forward?","options":["Double the list so that they meet more idioms, and test the meanings every week through matching exercises","Let them meet idioms in stories and talk, discuss when and why speakers use them, and then use them in situations","Ask them to avoid idioms in their own writing until they are confident of every meaning on the list","Have them write each idiom's meaning ten times, since the misuse shows that the meanings were never properly learnt"],"answer":1,"explanation":"An idiom's meaning depends on context and connotation (आँखें चुराना = to avoid someone's eyes), which isolated lists cannot give. Meeting idioms in real discourse and using them for a purpose builds that sense.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 7 के विद्यार्थी गाइड से अर्थ सहित 50 मुहावरे रट लेते हैं, फिर भी अपने लेखन में उनका गलत प्रयोग करते हैं, जैसे ‘उसने आँखें चुराकर किताब पढ़ी’ का अर्थ ‘उसने ध्यान से पढ़ी’ लेना। आगे बढ़ने का सबसे अच्छा तरीका क्या है?","optionsHi":["सूची को दोगुना कर देना ताकि वे अधिक मुहावरों से मिलें, और हर सप्ताह मिलान अभ्यासों से अर्थों की परीक्षा लेना","उन्हें कहानियों और बातचीत में मुहावरों से मिलने देना, चर्चा करना कि वक्ता उनका प्रयोग कब और क्यों करते हैं, और फिर स्थितियों में उनका प्रयोग करवाना","उनसे कहना कि सूची के हर अर्थ पर विश्वास होने तक अपने लेखन में मुहावरों से बचें","हर मुहावरे का अर्थ दस बार लिखवाना, क्योंकि गलत प्रयोग दिखाता है कि अर्थ कभी ठीक से सीखे नहीं गए"],"explanationHi":"मुहावरे का अर्थ संदर्भ और अभिप्राय पर निर्भर करता है (आँखें चुराना = किसी की आँखों से बचना), जो अलग-थलग सूचियाँ नहीं दे सकतीं। वास्तविक संवाद में मुहावरों से मिलना और उद्देश्य के साथ उनका प्रयोग करना वह समझ बनाता है।"},
  {"id":"cdp-pedagogy-subjects-1767","question":"A Class 2 child in a Bhili-speaking area writes a lively Hindi story about her goat, using several Bhili words where she does not know the Hindi ones. In assessing this piece, what should get the most weight?","options":["The number of Bhili words used, which shows how far she still is from writing in standard Hindi","The neatness of her handwriting and the correct use of the headline (शिरोरेखा)","Her ideas, sequence and expression, while the teacher notes the Hindi words she can learn next","Her spelling of the Hindi words, since accuracy is the main aim of writing at Class 2"],"answer":2,"explanation":"Drawing on her home language to say what she means is a strength, not a fault; assessment should value meaning and organisation, and the Bhili words show the teacher exactly which Hindi vocabulary to build next.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"भीली भाषी क्षेत्र की कक्षा 2 की एक बच्ची अपनी बकरी के बारे में जीवंत हिंदी कहानी लिखती है, जहाँ उसे हिंदी शब्द नहीं आते वहाँ कई भीली शब्द प्रयोग करती है। इस रचना के आकलन में किसे सबसे अधिक महत्व मिलना चाहिए?","optionsHi":["प्रयुक्त भीली शब्दों की संख्या, जो दिखाती है कि वह मानक हिंदी में लिखने से अभी कितनी दूर है","उसकी लिखावट की साफ़-सफ़ाई और शिरोरेखा का सही प्रयोग","उसके विचार, क्रम और अभिव्यक्ति, जबकि शिक्षिका उन हिंदी शब्दों को नोट करती है जो वह आगे सीख सकती है","उसकी हिंदी शब्दों की वर्तनी, क्योंकि कक्षा 2 में लेखन का मुख्य उद्देश्य शुद्धता है"],"explanationHi":"जो वह कहना चाहती है उसे कहने के लिए अपनी घरेलू भाषा का सहारा लेना एक शक्ति है, दोष नहीं; आकलन में अर्थ और संगठन को महत्व मिलना चाहिए, और भीली शब्द शिक्षिका को ठीक दिखाते हैं कि आगे कौन-सी हिंदी शब्दावली बनानी है।"},
  {"id":"cdp-pedagogy-subjects-1768","question":"Class 1 children chant the whole बारहखड़ी (क का कि की…) perfectly every morning, yet stumble over ‘काम’ and ‘कील’ in a new sentence. The most accurate explanation is that:","options":["they know a chanted sequence but cannot yet recognise akshars out of order and blend them into words","the chanting has not gone on long enough, and fluent reading will follow once the chant is perfect and quick","the बारहखड़ी is the wrong unit altogether, since Hindi must be taught only as separate phonemes from the start","they cannot read new words until they have learnt all the conjunct letters as well"],"answer":0,"explanation":"Recitation is serial memory: a child can say ‘का’ after ‘क’ without recognising ‘का’ alone. Reading needs recognising akshars in any order and blending them into meaningful words, which must be practised with real text.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"कक्षा 1 के बच्चे हर सुबह पूरी बारहखड़ी (क का कि की…) बिल्कुल सही दोहराते हैं, फिर भी नए वाक्य में ‘काम’ और ‘कील’ पर अटक जाते हैं। सबसे सटीक व्याख्या यह है कि:","optionsHi":["वे एक दोहराया गया क्रम जानते हैं पर अभी क्रम से बाहर अक्षरों को पहचानकर शब्दों में जोड़ नहीं पाते","सस्वर पाठ पर्याप्त देर तक नहीं चला, और पाठ के बिल्कुल सही और तेज़ होने पर धाराप्रवाह पठन आ जाएगा","बारहखड़ी बिल्कुल गलत इकाई है, क्योंकि हिंदी को शुरू से केवल अलग-अलग स्वनिमों के रूप में पढ़ाया जाना चाहिए","वे नए शब्द तब तक नहीं पढ़ सकते जब तक सभी संयुक्ताक्षर भी न सीख लें"],"explanationHi":"सस्वर पाठ क्रमिक स्मृति है: बच्चा ‘क’ के बाद ‘का’ बोल सकता है बिना ‘का’ को अकेले पहचाने। पठन के लिए किसी भी क्रम में अक्षरों को पहचानना और उन्हें सार्थक शब्दों में जोड़ना आवश्यक है, जिसका अभ्यास वास्तविक पाठ के साथ करना होगा।"},
  {"id":"cdp-pedagogy-subjects-1769","question":"A Class 8 social science teacher in a Hindi-medium school has students rewrite the textbook section on drought as a short news report for a village notice board. Viewed as language across the curriculum, the main value of the task is that:","options":["it gives the Hindi teacher fewer writing tasks to set, since the subject teachers share that load","it lets the teacher check spelling and grammar in social science as well as in Hindi","it keeps students busy with writing so that they do not need the teacher's explanation","students reshape subject content for a new audience, which deepens understanding and builds a genre"],"answer":3,"explanation":"Transforming information into a different genre for a real audience makes students select, explain and organise the content, so language and subject learning feed each other; checking mechanics or sharing workload is not the point.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"हिंदी माध्यम विद्यालय में कक्षा 8 की सामाजिक विज्ञान शिक्षिका विद्यार्थियों से सूखे पर पाठ्यपुस्तक के खंड को गाँव के सूचना-पट्ट के लिए छोटी समाचार-रिपोर्ट के रूप में फिर से लिखवाती है। पाठ्यचर्या में भाषा की दृष्टि से, इस कार्य का मुख्य मूल्य यह है कि:","optionsHi":["यह हिंदी शिक्षिका को कम लेखन-कार्य देने देता है, क्योंकि विषय-शिक्षक वह बोझ बाँट लेते हैं","यह शिक्षिका को सामाजिक विज्ञान में भी वर्तनी और व्याकरण जाँचने देता है, हिंदी की तरह","यह विद्यार्थियों को लेखन में व्यस्त रखता है ताकि उन्हें शिक्षिका की व्याख्या की आवश्यकता न रहे","विद्यार्थी विषय-वस्तु को नए श्रोताओं के लिए ढालते हैं, जो समझ गहरी करता है और एक विधा बनाता है"],"explanationHi":"जानकारी को वास्तविक श्रोताओं के लिए किसी अलग विधा में बदलना विद्यार्थियों से विषय-वस्तु चुनवाता, समझवाता और व्यवस्थित करवाता है, इसलिए भाषा और विषय का अधिगम एक-दूसरे को पोषित करते हैं; वर्तनी जाँचना या कार्य-भार बाँटना मुद्दा नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1770","question":"A Class 4 teacher crosses out ‘किताब’ and ‘दरवाज़ा’ in a child's composition and writes ‘पुस्तक’ and ‘द्वार’ as the ‘शुद्ध हिंदी’ forms. The best evaluation of this is:","options":["Correct, because examinations reward tatsam words, and children should learn to use them from an early age","Mistaken, because such everyday words are standard Hindi, and replacing them devalues her language","Partly correct: such words are fine in speech but should be replaced by tatsam forms in writing","Correct, because Sanskrit-based words are more precise and formal than everyday words of Persian origin"],"answer":1,"explanation":"‘किताब’ and ‘दरवाज़ा’ are part of standard Hindi in speech and writing. Treating them as errors narrows the child's language and sends the message that her natural Hindi is wrong.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 4 की एक शिक्षिका एक बच्चे की रचना में ‘किताब’ और ‘दरवाज़ा’ को काटकर ‘शुद्ध हिंदी’ रूपों के रूप में ‘पुस्तक’ और ‘द्वार’ लिखती है। इसका सबसे अच्छा मूल्यांकन है:","optionsHi":["सही, क्योंकि परीक्षाएँ तत्सम शब्दों को पुरस्कृत करती हैं, और बच्चों को उनका प्रयोग कम उम्र से सीखना चाहिए","गलत, क्योंकि ऐसे रोज़मर्रा के शब्द मानक हिंदी हैं, और उन्हें बदलना उसकी भाषा का अवमूल्यन करता है","आंशिक रूप से सही: ऐसे शब्द बोलचाल में ठीक हैं पर लेखन में तत्सम रूपों से बदले जाने चाहिए","सही, क्योंकि संस्कृत-आधारित शब्द फ़ारसी मूल के रोज़मर्रा शब्दों से अधिक सटीक और औपचारिक हैं"],"explanationHi":"‘किताब’ और ‘दरवाज़ा’ बोलचाल और लेखन दोनों में मानक हिंदी का हिस्सा हैं। उन्हें त्रुटि मानना बच्चे की भाषा को संकुचित करता है और यह संदेश देता है कि उसकी स्वाभाविक हिंदी गलत है।"},
  {"id":"cdp-pedagogy-subjects-1771","question":"A Class 1 child writing ‘दिन’ and ‘किताब’ puts the short-i sign (ि) to the right of the consonant it belongs to, in the order the sounds are heard. The rest of each word is correct. What is the most likely explanation?","options":["She has a visual-motor difficulty that makes her reverse marks around letters, so she should be screened for dyslexia at once","She cannot yet hear the short /i/ sound in these words and is only guessing where the vowel sign should go","She is confusing the short-i sign with the long-i sign (ी), which really is written to the right of the consonant","She is following the spoken order of sounds, which clashes with the script's convention for ‘ि’; this needs explicit teaching"],"answer":3,"explanation":"In speech /i/ comes after the consonant, but Devanagari writes ‘ि’ before it. A child who places it after is being logical about sound order; she hears the vowel and knows it is short, so she needs the visual convention pointed out and practised.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"कक्षा 1 की एक बच्ची ‘दिन’ और ‘किताब’ लिखते हुए छोटी इ की मात्रा (ि) को उस व्यंजन के दाईं ओर रखती है जिससे वह जुड़ी है, ध्वनियाँ जिस क्रम में सुनी जाती हैं उसी क्रम में। हर शब्द का बाकी भाग सही है। सबसे संभावित व्याख्या क्या है?","optionsHi":["उसे दृश्य-गामक कठिनाई है जो अक्षरों के आसपास चिह्नों को उलट देती है, इसलिए उसकी तुरंत डिस्लेक्सिया की जाँच होनी चाहिए","वह अभी इन शब्दों में छोटी /i/ ध्वनि नहीं सुन पाती और केवल अनुमान लगा रही है कि स्वर-चिह्न कहाँ जाए","वह छोटी इ की मात्रा को बड़ी ई की मात्रा (ी) से उलझा रही है, जो वास्तव में व्यंजन के दाईं ओर लिखी जाती है","वह ध्वनियों के बोले गए क्रम का अनुसरण कर रही है, जो ‘ि’ की लिपि-परिपाटी से टकराता है; इसके लिए स्पष्ट शिक्षण चाहिए"],"explanationHi":"बोलने में /i/ व्यंजन के बाद आता है, पर देवनागरी ‘ि’ को उससे पहले लिखती है। जो बच्ची उसे बाद में रखती है वह ध्वनि-क्रम के बारे में तर्कसंगत है; वह स्वर सुनती है और जानती है कि वह छोटा है, इसलिए उसे दृश्य परिपाटी बतानी और उसका अभ्यास कराना है।"},
  {"id":"cdp-pedagogy-subjects-1772","question":"Decoding ‘कमल’ akshar by akshar, a Class 1 child says ‘क-म-ल… कमला?’ and does not recognise the word, although she knows the flower कमल well. What should the teacher do?","options":["Explain that every Hindi word ends in a consonant sound with no vowel after it, and drill this rule on lists of words","Model blending the akshars into a word she knows, so she learns to check her decoding against familiar spoken words","Send her back to the letter chart, since she has clearly not yet mastered the sounds of क, म and ल","Have her memorise common words as whole shapes, since decoding akshar by akshar misleads readers of Hindi"],"answer":1,"explanation":"Spoken Hindi often drops the inherent अ at the end of a word (कमल is said kamal), which the script does not show. Readers learn this by matching decoded strings to words they know; the ‘rule’ in the first option is false, and she already knows the letters.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"‘कमल’ को अक्षर-दर-अक्षर विसंकेतित करते हुए कक्षा 1 की एक बच्ची कहती है ‘क-म-ल… कमला?’ और शब्द नहीं पहचानती, यद्यपि वह कमल के फूल को अच्छी तरह जानती है। शिक्षिका को क्या करना चाहिए?","optionsHi":["समझाना कि हर हिंदी शब्द व्यंजन ध्वनि पर समाप्त होता है जिसके बाद कोई स्वर नहीं होता, और शब्द-सूचियों पर इस नियम का अभ्यास कराना","अक्षरों को शब्द में जोड़ने का आदर्श प्रस्तुत करना, ऐसे शब्द पर जिसे वह जानती है, ताकि वह अपने विसंकेतन को परिचित बोले गए शब्दों से जाँचना सीखे","उसे वर्णमाला चार्ट पर वापस भेजना, क्योंकि स्पष्ट है कि उसने अभी क, म और ल की ध्वनियाँ पूरी तरह नहीं सीखीं","उससे सामान्य शब्दों को पूरे आकार के रूप में याद करवाना, क्योंकि अक्षर-दर-अक्षर विसंकेतन हिंदी के पाठकों को भ्रमित करता है"],"explanationHi":"बोली जाने वाली हिंदी में प्रायः शब्द के अंत का अंतर्निहित अ गिर जाता है (कमल ‘कमल्’ बोला जाता है), जिसे लिपि नहीं दिखाती। पाठक यह विसंकेतित शृंखलाओं को ज्ञात शब्दों से मिलाकर सीखते हैं; पहले विकल्प का ‘नियम’ गलत है, और वह अक्षर पहले से जानती है।"},
  {"id":"cdp-pedagogy-subjects-1773","question":"Which feature of Devanagari makes the akshar a natural unit for early reading instruction in Hindi?","options":["Each akshar usually stands for a consonant with its vowel, a unit children hear easily, and spelling is fairly regular","Devanagari letters have no fixed sounds, so each akshar must be learnt as a separate picture without reference to sound","The headline (शिरोरेखा) joins all the letters of a word, so children must learn whole words before they meet any letters","Vowel sounds are not written at all in Devanagari, so each akshar on the page holds only a single consonant sound"],"answer":0,"explanation":"Devanagari is an alphasyllabary: an akshar is a syllable-sized unit (consonant plus vowel sign), and sound–symbol mapping is fairly regular, so children can learn akshars and blend them. Vowels are written, as matras or full letters.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"देवनागरी की कौन-सी विशेषता अक्षर को हिंदी में प्रारंभिक पठन-शिक्षण के लिए स्वाभाविक इकाई बनाती है?","optionsHi":["हर अक्षर प्रायः स्वर सहित एक व्यंजन के लिए होता है, जो बच्चे आसानी से सुनते हैं, और वर्तनी काफ़ी नियमित है","देवनागरी के अक्षरों की कोई निश्चित ध्वनियाँ नहीं हैं, इसलिए हर अक्षर को ध्वनि के संदर्भ के बिना अलग चित्र के रूप में सीखना होगा","शिरोरेखा किसी शब्द के सभी अक्षरों को जोड़ती है, इसलिए बच्चों को कोई अक्षर मिलने से पहले पूरे शब्द सीखने होंगे","देवनागरी में स्वर ध्वनियाँ बिल्कुल नहीं लिखी जातीं, इसलिए पृष्ठ पर हर अक्षर केवल एक व्यंजन ध्वनि रखता है"],"explanationHi":"देवनागरी एक अक्षरात्मक वर्णमाला (alphasyllabary) है: अक्षर शब्दांश-आकार की इकाई है (व्यंजन और स्वर-चिह्न), और ध्वनि–प्रतीक मानचित्रण काफ़ी नियमित है, इसलिए बच्चे अक्षर सीख सकते हैं और उन्हें जोड़ सकते हैं। स्वर लिखे जाते हैं, मात्राओं या पूर्ण वर्णों के रूप में।"},
  {"id":"cdp-pedagogy-subjects-1774","question":"Shreya, a Marathi-speaking child, joins a Hindi-medium Class 3. Within a week she reads Hindi passages aloud almost fluently but understands little of them. What best explains this?","options":["She has a specific comprehension disability that should be formally assessed before any further teaching","She reads too fast and should be told to slow down and point to each word as she reads aloud in class","Decoding transfers because both use Devanagari, but understanding needs Hindi words and grammar she is still acquiring","She is reading Hindi with a Marathi pronunciation, and these wrong sounds are blocking her understanding of the whole text"],"answer":2,"explanation":"Because Marathi and Hindi share the script, her decoding skill carries over at once, but comprehension depends on knowing the language. She needs oral Hindi and vocabulary support, not a disability label or slower reading.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"श्रेया, एक मराठी भाषी बच्ची, हिंदी माध्यम की कक्षा 3 में आती है। एक सप्ताह के भीतर वह हिंदी गद्यांश लगभग धाराप्रवाह ज़ोर से पढ़ लेती है पर उनमें से कम ही समझती है। इसकी सबसे अच्छी व्याख्या क्या है?","optionsHi":["उसे कोई विशिष्ट बोध-अक्षमता है जिसका आगे कोई शिक्षण देने से पहले औपचारिक आकलन होना चाहिए","वह बहुत तेज़ पढ़ती है और उसे धीमे पढ़ने और कक्षा में ज़ोर से पढ़ते समय हर शब्द की ओर संकेत करने को कहा जाना चाहिए","विसंकेतन अंतरित हो जाता है क्योंकि दोनों देवनागरी का उपयोग करती हैं, पर समझ के लिए उन हिंदी शब्दों और व्याकरण की आवश्यकता है जो वह अभी अर्जित कर रही है","वह हिंदी को मराठी उच्चारण से पढ़ रही है, और ये गलत ध्वनियाँ पूरे पाठ को समझने में बाधा बन रही हैं"],"explanationHi":"क्योंकि मराठी और हिंदी की लिपि एक है, उसका विसंकेतन कौशल तुरंत साथ आ जाता है, पर बोध भाषा को जानने पर निर्भर करता है। उसे मौखिक हिंदी और शब्दावली में सहायता चाहिए, अक्षमता का ठप्पा या धीमा पठन नहीं।"},
  {"id":"cdp-pedagogy-subjects-1775","question":"Ramkali, fluent and expressive in Bundeli at home, says little in a Class 4 Hindi speaking test in which the teacher insists on ‘standard Hindi’, and is marked low. Which change would make the assessment more valid?","options":["Give her extra marks to make up for her disadvantage, since she comes from a rural home and is not to blame for it","Assess how she communicates ideas in tasks where she may use her own variety, and track standard Hindi separately","Excuse her from oral assessment until her standard Hindi is good enough to be assessed in a fair manner","Assess her only through written work, where differences of pronunciation and dialect do not show up at all"],"answer":1,"explanation":"A speaking assessment should capture the ability to express and organise ideas; forcing an unfamiliar variety measures dialect, not speaking skill. Growth in standard Hindi can be recorded separately without silencing her.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"रामकली, जो घर पर बुंदेली में धाराप्रवाह और अभिव्यक्तिपूर्ण है, कक्षा 4 की हिंदी बोलने की परीक्षा में कम बोलती है जिसमें शिक्षिका ‘मानक हिंदी’ पर ज़ोर देती है, और उसे कम अंक मिलते हैं। कौन-सा बदलाव आकलन को अधिक वैध बनाएगा?","optionsHi":["उसकी हानि की भरपाई के लिए उसे अतिरिक्त अंक देना, क्योंकि वह ग्रामीण घर से आती है और इसके लिए दोषी नहीं है","उन कार्यों में आकलन करना कि वह विचार कैसे संप्रेषित करती है जहाँ वह अपनी बोली का उपयोग कर सके, और मानक हिंदी को अलग से दर्ज करना","जब तक उसकी मानक हिंदी निष्पक्ष ढंग से आकलन-योग्य न हो जाए उसे मौखिक आकलन से छूट देना","उसका आकलन केवल लिखित कार्य से करना, जहाँ उच्चारण और बोली के अंतर बिल्कुल नहीं दिखते"],"explanationHi":"बोलने का आकलन विचारों को व्यक्त और व्यवस्थित करने की क्षमता पकड़ना चाहिए; अपरिचित बोली थोपना बोली को मापता है, बोलने के कौशल को नहीं। मानक हिंदी में विकास को उसे चुप कराए बिना अलग से दर्ज किया जा सकता है।"},
  {"id":"cdp-pedagogy-subjects-1776","question":"Consider these statements: I. A dialect such as Bhojpuri or Awadhi is a fully rule-governed language system. II. Standard Hindi owes its status mainly to social and historical factors, not to linguistic superiority. III. A child's home variety should be replaced as early as possible so that it does not interfere with standard Hindi. IV. The ability to move between a home variety and standard Hindi is a valuable skill. Which are correct?","options":["I and III only","II and IV only","I, II, III and IV","I, II and IV only"],"answer":3,"explanation":"All varieties are systematic, and a standard is a social choice, not a better language; so I, II and IV hold. Replacing the home variety (III) harms the child's confidence and loses a resource for learning.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"इन कथनों पर विचार कीजिए: I. भोजपुरी या अवधी जैसी बोली पूरी तरह नियम-शासित भाषा-प्रणाली है। II. मानक हिंदी का दर्जा मुख्यतः सामाजिक और ऐतिहासिक कारकों से है, भाषाई श्रेष्ठता से नहीं। III. बच्चे की घरेलू बोली को जितनी जल्दी हो सके बदल देना चाहिए ताकि वह मानक हिंदी में हस्तक्षेप न करे। IV. घरेलू बोली और मानक हिंदी के बीच आसानी से आना-जाना एक मूल्यवान कौशल है। कौन-से सही हैं?","optionsHi":["केवल I और III","केवल II और IV","I, II, III और IV","केवल I, II और IV"],"explanationHi":"सभी बोलियाँ व्यवस्थित होती हैं, और मानक एक सामाजिक चुनाव है, बेहतर भाषा नहीं; इसलिए I, II और IV सही हैं। घरेलू बोली को बदलना (III) बच्चे के आत्मविश्वास को हानि पहुँचाता है और अधिगम का एक संसाधन खो देता है।"},
  {"id":"cdp-pedagogy-subjects-1777","question":"To make Class 7 students sensitive to register, a Hindi teacher takes ‘पानी’, ‘जल’ and ‘नीर’. Which activity serves this aim best?","options":["Students find where each is used, at home, in a science book or a poem, and discuss why it fits there","Students learn the three words as exact synonyms and then write one sentence of their own using each","Students rank the three words from the most correct to the least correct form, with reasons for the order","Students look up the origin of each word in a dictionary and note which language each one came from"],"answer":0,"explanation":"Register is about which word suits which context: पानी in everyday talk, जल in formal or scientific writing, नीर in poetry. Seeing the words in use and discussing the fit builds this; treating them as exact synonyms or ranking them as ‘correct’ misses it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 के विद्यार्थियों को प्रयुक्ति (register) के प्रति संवेदनशील बनाने के लिए एक हिंदी शिक्षिका ‘पानी’, ‘जल’ और ‘नीर’ लेती है। कौन-सी गतिविधि इस लक्ष्य को सबसे अच्छी तरह पूरा करती है?","optionsHi":["विद्यार्थी खोजते हैं कि हर एक कहाँ प्रयुक्त होता है, घर में, विज्ञान की पुस्तक में या कविता में, और चर्चा करते हैं कि वह वहाँ क्यों फबता है","विद्यार्थी तीनों शब्दों को सटीक पर्यायवाची के रूप में सीखते हैं और फिर हर एक का उपयोग करके अपना एक वाक्य लिखते हैं","विद्यार्थी तीनों शब्दों को सबसे सही से सबसे कम सही रूप तक क्रम देते हैं, क्रम के कारणों सहित","विद्यार्थी शब्दकोश में हर शब्द की उत्पत्ति देखते हैं और नोट करते हैं कि प्रत्येक किस भाषा से आया"],"explanationHi":"प्रयुक्ति का संबंध है कि कौन-सा शब्द किस संदर्भ में उपयुक्त है: रोज़मर्रा की बात में पानी, औपचारिक या वैज्ञानिक लेखन में जल, कविता में नीर। शब्दों को प्रयोग में देखना और उपयुक्तता पर चर्चा करना यह बनाता है; उन्हें सटीक पर्यायवाची मानना या ‘सही’ के रूप में क्रम देना इसे चूक जाता है।"},
  {"id":"cdp-pedagogy-subjects-1778","question":"A Class 5 teacher in a Hindi-medium school has children write in a ‘गणित डायरी’ how they solved a problem and where they got stuck. From a language-across-the-curriculum view, the main value is that:","options":["it gives extra handwriting practice, for which the Hindi period has very little time left","it lets the teacher mark children's Hindi spelling at the same time as their mathematics","putting their reasoning into words clarifies children's thinking and shows the teacher how they reason","it removes the need for written maths tests, since the diary already shows every child's answers and working"],"answer":2,"explanation":"Writing to learn makes children organise and examine their own reasoning, and the teacher gains a window into it. Spelling, handwriting or replacing tests are not the purpose.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"हिंदी माध्यम विद्यालय में कक्षा 5 की एक शिक्षिका बच्चों से ‘गणित डायरी’ में लिखवाती है कि उन्होंने कोई प्रश्न कैसे हल किया और कहाँ अटके। पाठ्यचर्या में भाषा की दृष्टि से, मुख्य मूल्य यह है कि:","optionsHi":["यह अतिरिक्त हस्तलेखन अभ्यास देता है, जिसके लिए हिंदी पीरियड में बहुत कम समय बचा है","यह शिक्षिका को बच्चों की गणित के साथ-साथ हिंदी वर्तनी भी जाँचने देता है","अपने तर्क को शब्दों में रखना बच्चों की सोच को स्पष्ट करता है और शिक्षिका को दिखाता है कि वे कैसे तर्क करते हैं","यह लिखित गणित परीक्षाओं की आवश्यकता समाप्त कर देता है, क्योंकि डायरी पहले ही हर बच्चे के उत्तर और कार्य दिखा देती है"],"explanationHi":"सीखने के लिए लिखना बच्चों से अपने तर्क को व्यवस्थित करवाता और जँचवाता है, और शिक्षिका को उसकी एक खिड़की मिलती है। वर्तनी, हस्तलेखन या परीक्षाओं की जगह लेना उद्देश्य नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1779","question":"A Class 4 teacher uses a short tool to find whether each child can read akshars, words, a short paragraph or a story, then groups children by that level rather than by class for part of the day, re-testing every few weeks. This is the core idea of:","options":["ability tracking, in which weaker readers are placed permanently in a separate section of the class","Teaching at the Right Level, with short-term level-based groups that are regrouped often","norm-referenced testing, in which each child is ranked against the class average","mastery learning, in which no child moves on until the whole class passes a unit"],"answer":1,"explanation":"Teaching at the Right Level groups children by current reading level for focused instruction, reassesses them and moves them up quickly. Permanent tracking, ranking and whole-class mastery gates are different ideas.","difficulty":"hard","source":"KVS PRT · NVS PRT · DSSSB PRT","questionHi":"कक्षा 4 की एक शिक्षिका एक छोटे उपकरण से यह पता लगाती है कि हर बच्चा अक्षर, शब्द, छोटा अनुच्छेद या कहानी पढ़ सकता है या नहीं, फिर दिन के कुछ भाग में कक्षा के बजाय उस स्तर के अनुसार बच्चों को समूहों में बाँटती है, और हर कुछ सप्ताह में पुनः परीक्षण करती है। यह किसका केंद्रीय विचार है?","optionsHi":["क्षमता-अनुसार वर्गीकरण (ability tracking), जिसमें कमज़ोर पाठकों को कक्षा के अलग अनुभाग में स्थायी रूप से रखा जाता है","सही स्तर पर शिक्षण (Teaching at the Right Level), अल्पकालिक स्तर-आधारित समूहों के साथ जिन्हें बार-बार पुनर्गठित किया जाता है","मानक-संदर्भित परीक्षण, जिसमें हर बच्चे को कक्षा के औसत के विरुद्ध क्रम दिया जाता है","पूर्णता अधिगम (mastery learning), जिसमें जब तक पूरी कक्षा इकाई पास न कर ले कोई बच्चा आगे नहीं बढ़ता"],"explanationHi":"सही स्तर पर शिक्षण बच्चों को उनके वर्तमान पठन-स्तर के आधार पर केंद्रित शिक्षण के लिए समूहबद्ध करता है, उनका पुनः आकलन करता है और उन्हें जल्दी ऊपर ले जाता है। स्थायी वर्गीकरण, क्रम-निर्धारण और पूरी कक्षा की पूर्णता-द्वार अलग विचार हैं।"},
  {"id":"cdp-pedagogy-subjects-1780","question":"A Class 2 teacher holds regular sessions of Hindi पहेलियाँ (riddles), in which children guess the answer from playful clues. These sessions mainly develop children's:","options":["memory, because riddles and their answers are learnt by heart and then recited","knowledge of grammar, since riddles are always phrased in complete and correct sentences","pronunciation, because riddles use difficult sounds that children must repeat aloud","ability to infer from clues and play with word meanings, a form of thinking in language"],"answer":3,"explanation":"Riddles make children hold several clues in mind, infer and notice double meanings, which builds reasoning through language and awareness of words. They are not mainly memory, grammar or pronunciation drills.","difficulty":"moderate","source":"CTET Paper 1 · state TETs","questionHi":"कक्षा 2 की एक शिक्षिका हिंदी पहेलियों के नियमित सत्र आयोजित करती है, जिनमें बच्चे खेल-भरे संकेतों से उत्तर का अनुमान लगाते हैं। ये सत्र मुख्यतः बच्चों की किस क्षमता को विकसित करते हैं?","optionsHi":["स्मृति, क्योंकि पहेलियाँ और उनके उत्तर याद किए जाते हैं और फिर सुनाए जाते हैं","व्याकरण का ज्ञान, क्योंकि पहेलियाँ हमेशा पूर्ण और सही वाक्यों में कही जाती हैं","उच्चारण, क्योंकि पहेलियों में कठिन ध्वनियाँ होती हैं जिन्हें बच्चों को ज़ोर से दोहराना पड़ता है","संकेतों से अनुमान लगाने और शब्दों के अर्थों से खेलने की क्षमता, जो भाषा में सोचने का एक रूप है"],"explanationHi":"पहेलियाँ बच्चों से कई संकेत मन में रखवाती हैं, अनुमान लगवाती हैं और दोहरे अर्थों पर ध्यान दिलाती हैं, जो भाषा के माध्यम से तर्क-शक्ति और शब्दों के प्रति जागरूकता बनाता है। ये मुख्यतः स्मृति, व्याकरण या उच्चारण की कवायद नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-1781","question":"Class 6 students learning Hindi as R2 in a Kochi school collect Hindi words from railway signs, wrappers and posters and build a class wall chart. The main value of this activity is that:","options":["it shows Hindi as a language in real use around them and gives familiar, meaningful print to read","it can replace the textbook, which is far too hard for second-language learners at this early stage","it trains them in translation, since each word on the chart must carry its Malayalam meaning","it improves their handwriting, since they copy printed letters from many different fonts"],"answer":0,"explanation":"Environmental print links the new script to real contexts the children already know, so reading starts from meaningful, motivating material. It supplements rather than replaces the textbook.","difficulty":"hard","source":"KVS TGT · CTET Paper 2","questionHi":"कोच्चि के एक विद्यालय में R2 के रूप में हिंदी सीख रहे कक्षा 6 के विद्यार्थी रेलवे के संकेत-पट्टों, आवरणों और पोस्टरों से हिंदी शब्द एकत्र करते हैं और कक्षा का दीवार चार्ट बनाते हैं। इस गतिविधि का मुख्य मूल्य यह है कि:","optionsHi":["यह हिंदी को उनके आसपास वास्तविक उपयोग में आने वाली भाषा के रूप में दिखाती है और पढ़ने के लिए परिचित, सार्थक छपाई देती है","यह पाठ्यपुस्तक की जगह ले सकती है, जो इस आरंभिक चरण में द्वितीय भाषा के अधिगमकर्ताओं के लिए बहुत कठिन है","यह उन्हें अनुवाद में प्रशिक्षित करती है, क्योंकि चार्ट के हर शब्द के साथ उसका मलयालम अर्थ होना चाहिए","यह उनकी लिखावट सुधारती है, क्योंकि वे अनेक अलग-अलग फ़ॉन्ट के छपे अक्षर उतारते हैं"],"explanationHi":"परिवेशी छपाई नई लिपि को उन वास्तविक संदर्भों से जोड़ती है जो बच्चे पहले से जानते हैं, इसलिए पठन सार्थक, प्रेरक सामग्री से शुरू होता है। यह पाठ्यपुस्तक की जगह नहीं लेती, उसकी पूरक है।"},
  {"id":"cdp-pedagogy-subjects-1782","question":"Class 4 children write long Hindi stories with almost no पूर्ण विराम (।). Which approach is most likely to help?","options":["Give twenty unpunctuated sentences to correct every day for a week, with answers checked by the teacher","Teach the definitions of all the punctuation marks and have the children learn them by heart for a class test","Each child reads her story aloud to a partner, notices where a thought ends and she pauses, and marks it","Deduct a mark for every missing full stop so that children learn to take punctuation more seriously"],"answer":2,"explanation":"Punctuation marks units of meaning; hearing their own text aloud lets children notice where a thought ends and mark it in their real writing. Isolated drills and penalties rarely transfer.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 4 के बच्चे लगभग बिना पूर्ण विराम (।) के लंबी हिंदी कहानियाँ लिखते हैं। कौन-सा तरीका सबसे अधिक मदद करेगा?","optionsHi":["एक सप्ताह तक हर दिन बीस बिना विराम-चिह्न के वाक्य सुधारने को देना, शिक्षिका द्वारा उत्तर जाँचे जाने के साथ","सभी विराम-चिह्नों की परिभाषाएँ पढ़ाना और बच्चों से कक्षा-परीक्षा के लिए उन्हें कंठस्थ करवाना","हर बच्ची का अपनी कहानी एक साथी को ज़ोर से पढ़कर सुनाना, यह ध्यान देना कि विचार कहाँ समाप्त होता है और वह कहाँ रुकती है, और उसे चिह्नित करना","हर छूटे पूर्ण विराम पर एक अंक काटना ताकि बच्चे विराम-चिह्नों को अधिक गंभीरता से लेना सीखें"],"explanationHi":"विराम-चिह्न अर्थ की इकाइयों को चिह्नित करते हैं; अपने ही पाठ को ज़ोर से सुनने से बच्चे देख पाते हैं कि विचार कहाँ समाप्त होता है और उसे अपने वास्तविक लेखन में चिह्नित कर पाते हैं। अलग-थलग अभ्यास और दंड शायद ही अंतरित होते हैं।"},
  {"id":"cdp-pedagogy-subjects-1783","question":"In a Class 2 of 55 children, a teacher relies almost entirely on chorus reading of the Hindi textbook. What is the most serious limitation of this practice?","options":["It is noisy for the neighbouring classes and disturbs the work of the rest of the school","Choral work has no place at all in early literacy and should be dropped from the class","It tires children out, because reading aloud takes more effort than reading silently","It hides which children are decoding and which are only following others' voices"],"answer":3,"explanation":"In a chorus, children can echo stronger readers or recite from memory, so the teacher cannot see who actually reads. Some choral reading is useful, but used alone it masks individual difficulties.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"55 बच्चों वाली कक्षा 2 में एक शिक्षिका हिंदी पाठ्यपुस्तक के सामूहिक पठन पर लगभग पूरी तरह निर्भर करती है। इस अभ्यास की सबसे गंभीर सीमा क्या है?","optionsHi":["यह पड़ोसी कक्षाओं के लिए शोरगुल भरा है और विद्यालय के बाकी कार्य में बाधा डालता है","सामूहिक कार्य का प्रारंभिक साक्षरता में कोई स्थान नहीं है और उसे कक्षा से हटा देना चाहिए","यह बच्चों को थका देता है, क्योंकि ज़ोर से पढ़ने में मौन पढ़ने से अधिक प्रयास लगता है","यह छिपा देता है कि कौन-से बच्चे विसंकेतन कर रहे हैं और कौन केवल दूसरों की आवाज़ों का अनुसरण कर रहे हैं"],"explanationHi":"समूह-स्वर में बच्चे सशक्त पाठकों की प्रतिध्वनि बना सकते हैं या स्मृति से दोहरा सकते हैं, इसलिए शिक्षिका नहीं देख पाती कि वास्तव में कौन पढ़ता है। कुछ सामूहिक पठन उपयोगी है, पर अकेले प्रयुक्त होने पर वह व्यक्तिगत कठिनाइयों को ढक देता है।"},
  {"id":"cdp-pedagogy-subjects-1784","question":"A Class 3 child writes ‘वह ज़ोर से हंस रहा है’. What is the teacher's most useful response?","options":["Mark it wrong and have her copy the correct form ‘हँस’ ten times in her notebook","Show the pair हंस (swan) and हँस (laugh), say both aloud, and let her hear how the sign changes meaning","Ignore it, since chandrabindu and anusvara are fully interchangeable in all modern Hindi writing","Teach her the complete set of rules for using anusvara and chandrabindu before she writes any more"],"answer":1,"explanation":"Here the sign changes meaning (swan vs laugh), so a heard and meaningful contrast is the clearest lesson. Anusvara replaces chandrabindu only in some contexts (such as a matra above the headline), so they are not freely interchangeable.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT","questionHi":"कक्षा 3 की एक बच्ची लिखती है ‘वह ज़ोर से हंस रहा है’। शिक्षिका की सबसे उपयोगी प्रतिक्रिया क्या है?","optionsHi":["इसे गलत चिह्नित करना और उससे सही रूप ‘हँस’ अपनी कॉपी में दस बार उतरवाना","हंस (पक्षी) और हँस (हँसना) का जोड़ा दिखाना, दोनों को ज़ोर से बोलना, और उसे सुनने देना कि चिह्न अर्थ कैसे बदलता है","इसकी अनदेखी करना, क्योंकि आधुनिक हिंदी लेखन में चंद्रबिंदु और अनुस्वार पूरी तरह एक-दूसरे के स्थान पर आते हैं","उसे और लिखने देने से पहले अनुस्वार और चंद्रबिंदु के प्रयोग के पूरे नियम सिखाना"],"explanationHi":"यहाँ चिह्न अर्थ बदलता है (पक्षी बनाम हँसना), इसलिए सुना हुआ और सार्थक अंतर सबसे स्पष्ट पाठ है। अनुस्वार चंद्रबिंदु की जगह केवल कुछ संदर्भों में आता है (जैसे शिरोरेखा के ऊपर मात्रा हो), इसलिए वे स्वतंत्र रूप से अदल-बदल नहीं हो सकते।"},
  {"id":"cdp-pedagogy-subjects-1785","question":"Which activity best builds morphological awareness among Class 5 Hindi learners?","options":["Building word families such as सफल → असफल, सफलता and noticing how each added part changes meaning","Memorising lists of prefixes (उपसर्ग) with their definitions and examples for a written test","Taking dictation of long and difficult words chosen from the textbook lessons of the term","Arranging lists of words in dictionary order as quickly as possible"],"answer":0,"explanation":"Morphological awareness is sensitivity to meaningful parts of words; building and comparing word families makes children notice how prefixes and suffixes change meaning. Memorised lists do not develop that sensitivity.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के हिंदी अधिगमकर्ताओं में रूप-विज्ञान संबंधी जागरूकता (morphological awareness) को कौन-सी गतिविधि सबसे अच्छी तरह बनाती है?","optionsHi":["सफल → असफल, सफलता जैसे शब्द-परिवार बनाना और ध्यान देना कि हर जोड़ा गया भाग अर्थ कैसे बदलता है","लिखित परीक्षा के लिए उपसर्गों की परिभाषाओं और उदाहरणों सहित सूचियाँ रटना","सत्र के पाठ्यपुस्तक-पाठों से चुने लंबे और कठिन शब्दों का श्रुतलेख लेना","शब्दों की सूचियों को यथासंभव जल्दी शब्दकोश-क्रम में लगाना"],"explanationHi":"रूप-विज्ञान संबंधी जागरूकता शब्दों के अर्थपूर्ण भागों के प्रति संवेदनशीलता है; शब्द-परिवार बनाना और उनकी तुलना करना बच्चों को ध्यान दिलाता है कि उपसर्ग और प्रत्यय अर्थ कैसे बदलते हैं। रटी हुई सूचियाँ वह संवेदनशीलता नहीं बनातीं।"},
  {"id":"cdp-pedagogy-subjects-1786","question":"A Class 2 child who has been deaf from birth joins a Hindi-medium inclusive class. Which approach is most in line with current understanding and NEP 2020?","options":["Rely only on lip-reading and speech training, so that she learns to speak Hindi like her classmates","Seat her near the window for good light and teach her exactly as the hearing children are taught","Support her through Indian Sign Language as a first language, with written Hindi learnt alongside","Delay reading and writing until she has acquired enough spoken Hindi through her hearing aids"],"answer":2,"explanation":"A full first language (Indian Sign Language, which NEP 2020 asks to be standardised and used) gives her a base for thinking and for learning written Hindi. Relying only on speech or delaying literacy leaves her without full access to language.","difficulty":"hard","source":"CTET · KVS PRT · DSSSB","questionHi":"जन्म से बधिर कक्षा 2 की एक बच्ची हिंदी माध्यम की समावेशी कक्षा में आती है। कौन-सा उपागम वर्तमान समझ और NEP 2020 के सबसे अनुरूप है?","optionsHi":["केवल ओष्ठ-पठन और वाक्-प्रशिक्षण पर निर्भर रहना, ताकि वह अपने सहपाठियों की तरह हिंदी बोलना सीखे","उसे अच्छी रोशनी के लिए खिड़की के पास बिठाना और उसे ठीक वैसे ही पढ़ाना जैसे सुन सकने वाले बच्चों को पढ़ाया जाता है","भारतीय सांकेतिक भाषा के माध्यम से उसे प्रथम भाषा के रूप में सहारा देना, साथ में लिखित हिंदी सीखना","पठन और लेखन को तब तक टालना जब तक वह अपने श्रवण-यंत्रों से पर्याप्त बोली जाने वाली हिंदी अर्जित न कर ले"],"explanationHi":"पूर्ण प्रथम भाषा (भारतीय सांकेतिक भाषा, जिसे NEP 2020 मानकीकृत और प्रयुक्त करने को कहती है) उसे सोचने और लिखित हिंदी सीखने का आधार देती है। केवल वाणी पर निर्भर रहना या साक्षरता टालना उसे भाषा तक पूर्ण पहुँच के बिना छोड़ देता है।"},
  {"id":"cdp-pedagogy-subjects-1787","question":"Class 7 students often write ‘उसने कहा की वह आएगा’. Which explanation and response is most accurate?","options":["It is a careless slip, and reminding students to check their spellings before they hand in work will solve it","‘कि’ and ‘की’ sound alike in quick speech; students need to notice their different jobs across many sentences","Students are confusing the tatsam and tadbhav forms of one word, which should be taught to them as pairs","‘की’ is simply the older spelling of ‘कि’, so students are using an outdated but still acceptable form"],"answer":1,"explanation":"‘कि’ is a conjunction introducing a clause; ‘की’ is the feminine possessive marker. Because they sound alike in connected speech, students must learn to tell them apart by function, which needs attention in context, not a general reminder.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 7 के विद्यार्थी अक्सर लिखते हैं ‘उसने कहा की वह आएगा’। कौन-सी व्याख्या और प्रतिक्रिया सबसे सटीक है?","optionsHi":["यह लापरवाही की चूक है, और विद्यार्थियों को कार्य जमा करने से पहले वर्तनी जाँचने की याद दिलाने से हल हो जाएगी","तेज़ बोलचाल में ‘कि’ और ‘की’ एक जैसे सुनाई देते हैं; विद्यार्थियों को अनेक वाक्यों में उनके अलग-अलग कार्यों पर ध्यान देना होगा","विद्यार्थी एक शब्द के तत्सम और तद्भव रूपों को उलझा रहे हैं, जिन्हें उन्हें जोड़ियों के रूप में पढ़ाया जाना चाहिए","‘की’ बस ‘कि’ की पुरानी वर्तनी है, इसलिए विद्यार्थी अप्रचलित पर अब भी स्वीकार्य रूप का प्रयोग कर रहे हैं"],"explanationHi":"‘कि’ उपवाक्य लाने वाला संयोजक है; ‘की’ स्त्रीलिंग संबंध-सूचक है। जुड़े हुए बोलचाल में एक-से सुनाई देने के कारण विद्यार्थियों को कार्य के आधार पर उनमें भेद करना सीखना होगा, जिसके लिए संदर्भ में ध्यान चाहिए, सामान्य याद दिलाना नहीं।"},
  {"id":"cdp-pedagogy-subjects-1788","question":"During a Class 6 Hindi discussion in a Mumbai school, a student says, ‘मेरे को भी बोलना है।’ What is the best response?","options":["Let the talk flow, and later build awareness that ‘मुझे’ is expected in formal speech and writing, without faulting her","Stop her immediately and have her repeat the sentence with ‘मुझे’ before she is allowed to continue","Ignore it entirely, since in a speaking activity a teacher should never draw any attention to form, either now or later on","Ask the class to vote on whether ‘मेरे को’ or ‘मुझे’ is correct, so that they discover the rule for themselves"],"answer":0,"explanation":"‘मेरे को’ is common in colloquial Hindi; the aim is to keep the discussion going and later build awareness of the formal register. Interrupting silences her, voting does not settle usage, and ignoring form forever leaves a gap for formal writing.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"मुंबई के एक विद्यालय में कक्षा 6 की हिंदी चर्चा के दौरान एक विद्यार्थी कहती है, ‘मेरे को भी बोलना है।’ सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["बातचीत को बहने देना, और बाद में जागरूकता बनाना कि औपचारिक बोलचाल और लेखन में ‘मुझे’ अपेक्षित है, उसे दोषी ठहराए बिना","उसे तुरंत रोकना और आगे बोलने देने से पहले वाक्य को ‘मुझे’ के साथ दोहरवाना","इसकी पूरी तरह अनदेखी करना, क्योंकि बोलने की गतिविधि में शिक्षिका को न अभी, न बाद में, रूप की ओर कोई ध्यान नहीं दिलाना चाहिए","कक्षा से मतदान करवाना कि ‘मेरे को’ सही है या ‘मुझे’, ताकि वे नियम स्वयं खोजें"],"explanationHi":"‘मेरे को’ बोलचाल की हिंदी में आम है; उद्देश्य चर्चा को चलाए रखना और बाद में औपचारिक प्रयुक्ति के प्रति जागरूकता बनाना है। बीच में रोकना उसे चुप कर देता है, मतदान प्रयोग तय नहीं करता, और रूप की सदा अनदेखी औपचारिक लेखन के लिए कमी छोड़ देती है।"},
  {"id":"cdp-pedagogy-subjects-1789","question":"A Class 6 Hindi teacher collects anonymised sentences with agreement errors from students' compositions (‘लड़कियाँ खेल रहा है’), and the class works out together what is wrong and why. The main strength of this practice is that:","options":["students find out which classmates make the most errors and can offer them extra help","it covers the grammar syllabus much faster than working through the exercises given in the textbook","it removes the need for the teacher to give each student individual feedback","the rules discovered come from learners' own language, so they address their real errors"],"answer":3,"explanation":"Using learners' own errors makes grammar relevant and lets students reason out agreement rules they actually need. Anonymity protects them, so it is not about identifying weak students, and it does not replace individual feedback.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT","questionHi":"कक्षा 6 की एक हिंदी शिक्षिका विद्यार्थियों की रचनाओं से अन्वय (agreement) की त्रुटियों वाले अनाम वाक्य एकत्र करती है (‘लड़कियाँ खेल रहा है’), और कक्षा मिलकर पता लगाती है कि क्या गलत है और क्यों। इस अभ्यास की मुख्य शक्ति यह है कि:","optionsHi":["विद्यार्थी पता लगाते हैं कि कौन-से सहपाठी सबसे अधिक त्रुटियाँ करते हैं और उन्हें अतिरिक्त मदद दे सकते हैं","यह व्याकरण पाठ्यक्रम को पाठ्यपुस्तक में दिए अभ्यासों पर काम करने से कहीं जल्दी पूरा करता है","यह शिक्षिका को हर विद्यार्थी को व्यक्तिगत प्रतिपुष्टि देने की आवश्यकता से मुक्त कर देता है","खोजे गए नियम अधिगमकर्ताओं की अपनी भाषा से आते हैं, इसलिए वे उनकी वास्तविक त्रुटियों को संबोधित करते हैं"],"explanationHi":"अधिगमकर्ताओं की अपनी त्रुटियों का उपयोग व्याकरण को प्रासंगिक बनाता है और विद्यार्थियों को वे अन्वय-नियम तर्क से निकालने देता है जिनकी उन्हें वास्तव में आवश्यकता है। अनामता उनकी रक्षा करती है, इसलिए यह कमज़ोर विद्यार्थियों की पहचान के बारे में नहीं है, और यह व्यक्तिगत प्रतिपुष्टि की जगह नहीं लेता।"},
  {"id":"cdp-pedagogy-subjects-1790","question":"Before reading a Hindi story aloud, a Class 1 teacher spends a few minutes on the cover picture: ‘चित्र में क्या हो रहा है? आगे क्या होगा?’ This mainly helps children to:","options":["learn the names of the letters printed on the page alongside the picture on the cover","memorise the story in advance so that they can later recite it without the text","build oral language and expectations about the story, which support making meaning","practise sitting quietly and paying attention before the actual reading starts"],"answer":2,"explanation":"Picture talk activates children's experience and language and sets up predictions, so they listen and later read for meaning. It is not about letter names or memorising the story.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"हिंदी कहानी ज़ोर से पढ़ने से पहले कक्षा 1 की शिक्षिका आवरण-चित्र पर कुछ मिनट बिताती है: ‘चित्र में क्या हो रहा है? आगे क्या होगा?’ यह मुख्यतः बच्चों को किसमें मदद करता है?","optionsHi":["आवरण के चित्र के साथ पृष्ठ पर छपे अक्षरों के नाम सीखना","कहानी को पहले से याद करना ताकि वे बाद में पाठ के बिना उसे सुना सकें","मौखिक भाषा और कहानी के बारे में अपेक्षाएँ बनाना, जो अर्थ निर्माण में सहायक हैं","वास्तविक पठन शुरू होने से पहले चुपचाप बैठने और ध्यान देने का अभ्यास करना"],"explanationHi":"चित्र-वार्ता बच्चों के अनुभव और भाषा को सक्रिय करती है और पूर्वानुमान तैयार करती है, इसलिए वे सुनते और बाद में अर्थ के लिए पढ़ते हैं। यह अक्षरों के नाम या कहानी याद करने के बारे में नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1791","question":"Class 7 students claim that when two dice are rolled, a total of 12 and a total of 7 are equally likely, ‘because each is just one number’. Which activity best challenges this idea?","options":["Roll one die many times to show that every face comes up about equally often, then extend the result to two dice","List all 36 ordered outcomes in a 6 × 6 table and count how many give each total, then compare with pooled class rolls","Roll two dice ten times and see which total turns up more often, so that the evidence comes from the students","Tell them that 7 is the most likely total and ask them to remember this fact for any questions on dice that come in the final test"],"answer":1,"explanation":"Six of the 36 equally likely outcomes give 7, but only (6, 6) gives 12. Listing the sample space shows why, and a large pooled experiment confirms it; ten rolls are too few, and one die hides the issue.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 के विद्यार्थी दावा करते हैं कि दो पासे फेंकने पर कुल 12 और कुल 7 समान रूप से संभावित हैं, ‘क्योंकि हर एक बस एक संख्या है’। कौन-सी गतिविधि इस विचार को सबसे अच्छी तरह चुनौती देती है?","optionsHi":["एक पासे को कई बार फेंककर दिखाना कि हर फलक लगभग बराबर बार आता है, फिर परिणाम को दो पासों तक बढ़ाना","सभी 36 क्रमित परिणाम 6 × 6 सारणी में सूचीबद्ध करना और गिनना कि हर कुल कितने परिणामों से मिलता है, फिर कक्षा के मिलाए गए फेंकों से तुलना करना","दो पासे दस बार फेंकना और देखना कि कौन-सा कुल अधिक बार आता है, ताकि साक्ष्य विद्यार्थियों से आए","उन्हें बताना कि 7 सबसे संभावित कुल है और उनसे इस तथ्य को अंतिम परीक्षा में पासों से जुड़े किसी भी प्रश्न के लिए याद रखने को कहना"],"explanationHi":"36 समान रूप से संभावित परिणामों में से छह से 7 मिलता है, पर 12 केवल (6, 6) से। प्रतिदर्श-समष्टि की सूची दिखाती है कि क्यों, और बड़ा मिलाया गया प्रयोग उसकी पुष्टि करता है; दस फेंक बहुत कम हैं, और एक पासा मुद्दे को छिपा देता है।"},
  {"id":"cdp-pedagogy-subjects-1792","question":"A Class 5 child writes 48 × 52 = 24,960 and moves on. Which habit would most quickly have shown her that the answer cannot be right?","options":["Estimating first: about 50 × 50 = 2,500, so an answer near 25,000 is ten times too big","Checking that the answer is even, since both the numbers being multiplied are even","Checking that the answer is larger than both of the numbers that were multiplied","Copying the numbers again neatly in columns and seeing that each digit is in its place"],"answer":0,"explanation":"48 × 52 = 2,496, close to the estimate 2,500, so 24,960 is off by a factor of ten. The evenness and ‘bigger than both’ checks are both passed by the wrong answer, and recopying checks nothing.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक बच्ची लिखती है 48 × 52 = 24,960 और आगे बढ़ जाती है। कौन-सी आदत उसे सबसे जल्दी दिखा देती कि उत्तर सही नहीं हो सकता?","optionsHi":["पहले आकलन करना: लगभग 50 × 50 = 2,500, इसलिए 25,000 के आसपास का उत्तर दस गुना बड़ा है","जाँचना कि उत्तर सम है, क्योंकि गुणा की जा रही दोनों संख्याएँ सम हैं","जाँचना कि उत्तर गुणा की गई दोनों संख्याओं से बड़ा है","संख्याओं को स्तंभों में साफ़-सुथरे ढंग से फिर उतारना और देखना कि हर अंक अपने स्थान पर है"],"explanationHi":"48 × 52 = 2,496, आकलन 2,500 के निकट, इसलिए 24,960 दस गुना अधिक है। सम होने और ‘दोनों से बड़ा’ होने की जाँचें गलत उत्तर से भी पास हो जाती हैं, और दोबारा उतारने से कुछ जाँचा नहीं जाता।"},
  {"id":"cdp-pedagogy-subjects-1793","question":"Four children have 3, 7, 2 and 8 marbles. Before giving the formula for the mean, which activity best builds its meaning?","options":["Arrange the numbers in order and pick the middle value, which shows the typical amount each child has","Practise finding ‘total ÷ number of children’ for many such data sets until the steps become automatic","Build cube towers of 3, 7, 2 and 8 and move cubes from tall towers to short ones until all are equal","Find the number that appears most often, since the mean tells us the value that is most common"],"answer":2,"explanation":"Levelling the towers (each becomes 5) shows the mean as a fair share, which later explains why we add and divide. Picking the middle value is the median and the most common value is the mode.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"चार बच्चों के पास 3, 7, 2 और 8 कंचे हैं। माध्य का सूत्र देने से पहले कौन-सी गतिविधि उसका अर्थ सबसे अच्छी तरह बनाती है?","optionsHi":["संख्याओं को क्रम में लगाना और मध्य मान चुनना, जो दिखाता है कि हर बच्चे के पास प्रारूपिक मात्रा क्या है","कई ऐसे आँकड़ा-समूहों के लिए ‘कुल ÷ बच्चों की संख्या’ निकालने का अभ्यास करना जब तक चरण स्वचालित न हो जाएँ","3, 7, 2 और 8 के घन-मीनारें बनाना और ऊँची मीनारों से घन छोटी मीनारों पर तब तक ले जाना जब तक सब बराबर न हो जाएँ","वह संख्या ढूँढना जो सबसे अधिक बार आती है, क्योंकि माध्य हमें वह मान बताता है जो सबसे आम है"],"explanationHi":"मीनारों को बराबर करना (हर एक 5 हो जाती है) माध्य को उचित हिस्से के रूप में दिखाता है, जो बाद में समझाता है कि हम जोड़कर भाग क्यों देते हैं। मध्य मान चुनना माध्यिका है और सबसे आम मान बहुलक है।"},
  {"id":"cdp-pedagogy-subjects-1794","question":"For data on the favourite fruits of a Class 6 class (mango 12, banana 8, apple 5, guava 9), a student draws a line graph joining the four points. What does this choice most reveal?","options":["She should have chosen a pictograph instead, because all the numbers in the data are small","Her only mistake is that the vertical axis of the graph does not begin at zero as it should","Line graphs cannot show values above ten, so the scale she chose for the vertical axis is the real problem here","She has not grasped that a line implies change between ordered values, which separate fruits do not have"],"answer":3,"explanation":"Joining points suggests a continuous trend, as with temperature over time; fruits are separate categories with no order, so a bar graph fits. The axis and scale are side issues.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक कक्षा के पसंदीदा फलों के आँकड़ों (आम 12, केला 8, सेब 5, अमरूद 9) के लिए एक विद्यार्थी चारों बिंदुओं को जोड़ने वाला रेखा-आलेख बनाती है। यह चुनाव सबसे अधिक क्या प्रकट करता है?","optionsHi":["उसे इसके बजाय चित्र-आलेख चुनना चाहिए था, क्योंकि आँकड़ों की सभी संख्याएँ छोटी हैं","उसकी एकमात्र गलती यह है कि आलेख का ऊर्ध्वाधर अक्ष शून्य से शुरू नहीं होता जैसा होना चाहिए","रेखा-आलेख दस से ऊपर के मान नहीं दिखा सकते, इसलिए ऊर्ध्वाधर अक्ष के लिए उसका चुना पैमाना ही असली समस्या है","उसने यह नहीं समझा कि रेखा क्रमित मानों के बीच परिवर्तन का संकेत देती है, जो अलग-अलग फलों में नहीं होता"],"explanationHi":"बिंदुओं को जोड़ना सतत प्रवृत्ति का सुझाव देता है, जैसे समय के साथ तापमान; फल अलग श्रेणियाँ हैं जिनमें कोई क्रम नहीं, इसलिए दंड-आलेख उपयुक्त है। अक्ष और पैमाना गौण मुद्दे हैं।"},
  {"id":"cdp-pedagogy-subjects-1795","question":"A Class 7 student insists that ‘π is exactly 22/7, because that is what we use in every sum’. Which response is most appropriate?","options":["Reassure her that 22/7 is accurate enough for school sums, and that the difference matters only in advanced science","Have her compare 22/7 = 3.1428… with π = 3.1415… and discuss 22/7 as a convenient approximation for calculation","Explain that π is really 3.14, and that 22/7 is simply the same value written as a fraction to make division easier","Have her measure and divide the circumference by the diameter of several round objects to discover the true ratio herself"],"answer":1,"explanation":"Comparing decimals shows directly that 22/7 and π differ from the third decimal place, so 22/7 is an approximation and π has no exact fraction form. Measuring round objects is tempting, but measurement error is far larger than that difference, so it cannot settle the question and may even seem to confirm 22/7.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2","questionHi":"कक्षा 7 की एक विद्यार्थी ज़ोर देती है कि ‘π ठीक 22/7 है, क्योंकि हम हर प्रश्न में यही प्रयोग करते हैं’। कौन-सी प्रतिक्रिया सबसे उपयुक्त है?","optionsHi":["उसे आश्वस्त करना कि 22/7 विद्यालयी प्रश्नों के लिए पर्याप्त सटीक है, और अंतर केवल उन्नत विज्ञान में मायने रखता है","उससे 22/7 = 3.1428… की तुलना π = 3.1415… से करवाना और 22/7 पर गणना के लिए सुविधाजनक सन्निकटन के रूप में चर्चा करना","समझाना कि π वास्तव में 3.14 है, और 22/7 उसी मान को भिन्न के रूप में लिखा है ताकि भाग आसान हो","उससे कई गोल वस्तुओं की परिधि को व्यास से नापकर और भाग देकर सही अनुपात स्वयं खोजने को कहना"],"explanationHi":"दशमलवों की तुलना सीधे दिखाती है कि 22/7 और π तीसरे दशमलव स्थान से भिन्न हैं, इसलिए 22/7 एक सन्निकटन है और π का कोई सटीक भिन्न रूप नहीं है। गोल वस्तुएँ नापना आकर्षक है, पर माप की त्रुटि उस अंतर से कहीं बड़ी है, इसलिए वह प्रश्न तय नहीं कर सकता और 22/7 की पुष्टि करता भी लग सकता है।"},
  {"id":"cdp-pedagogy-subjects-1796","question":"A Class 6 student claims, ‘If a number is divisible by both 4 and 6, it must be divisible by 24.’ What is the best response?","options":["Agree, because 4 × 6 = 24, and being divisible by two numbers always means being divisible by their product as well","Show that 48 is divisible by 4, 6 and 24, which confirms that the claim holds for every such number","Ask her to test 12, then discuss why the product rule holds only when the two divisors have no common factor","Tell her that the rule works only for even numbers, which explains why it fails for some of them"],"answer":2,"explanation":"12 is divisible by 4 and 6 but not 24; the least common multiple of 4 and 6 is 12. Divisibility by two numbers implies divisibility by their product only when they are co-prime (such as 3 and 8). One confirming example proves nothing.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक विद्यार्थी दावा करती है, ‘यदि कोई संख्या 4 और 6 दोनों से विभाज्य है, तो वह 24 से विभाज्य होगी ही।’ सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["सहमत होना, क्योंकि 4 × 6 = 24, और दो संख्याओं से विभाज्य होने का अर्थ हमेशा उनके गुणनफल से भी विभाज्य होना है","दिखाना कि 48, 4, 6 और 24 से विभाज्य है, जो पुष्टि करता है कि दावा ऐसी हर संख्या के लिए सही है","उससे 12 को जाँचने को कहना, फिर चर्चा करना कि गुणनफल का नियम तभी लागू होता है जब दोनों भाजकों का कोई उभयनिष्ठ गुणनखंड न हो","उससे कहना कि नियम केवल सम संख्याओं पर काम करता है, जो समझाता है कि वह कुछ पर क्यों विफल होता है"],"explanationHi":"12, 4 और 6 से विभाज्य है पर 24 से नहीं; 4 और 6 का लघुत्तम समापवर्त्य (LCM) 12 है। दो संख्याओं से विभाज्यता उनके गुणनफल से विभाज्यता तभी सूचित करती है जब वे सह-अभाज्य हों (जैसे 3 और 8)। एक पुष्टिकारक उदाहरण कुछ सिद्ध नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-1797","question":"A Class 7 teacher lets students use calculators to write 1/7, 2/7, 3/7 and so on as decimals and look for patterns. What is the best justification for this?","options":["The calculator does the long divisions, so attention goes to the repeating cycle 142857 and why it appears","Calculators give the exact decimal value of every fraction, so students see the true answer every single time","Students who find long division hard need not learn it at all once calculators are allowed in class","The main gain is practice in keying numbers quickly and accurately into a calculator for later use"],"answer":0,"explanation":"Here the calculator frees students from tedious work so they can notice that every ‘sevenths’ decimal uses the same cycle 142857 and reason about remainders. Calculators truncate rather than give exact values, and division still has to be learnt.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक शिक्षिका विद्यार्थियों को कैलकुलेटर से 1/7, 2/7, 3/7 आदि को दशमलव के रूप में लिखने और पैटर्न खोजने देती है। इसका सबसे अच्छा औचित्य क्या है?","optionsHi":["कैलकुलेटर लंबा भाग करता है, इसलिए ध्यान आवर्ती चक्र 142857 और उसके आने के कारण पर जाता है","कैलकुलेटर हर भिन्न का सटीक दशमलव मान देते हैं, इसलिए विद्यार्थी हर बार वास्तविक उत्तर देखते हैं","जिन विद्यार्थियों को लंबा भाग कठिन लगता है, उन्हें कक्षा में कैलकुलेटर की अनुमति मिलने पर उसे सीखने की आवश्यकता ही नहीं रहती","मुख्य लाभ कैलकुलेटर में संख्याएँ तेज़ी से और सटीक डालने का अभ्यास है, जो बाद में काम आएगा"],"explanationHi":"यहाँ कैलकुलेटर विद्यार्थियों को उबाऊ काम से मुक्त करता है ताकि वे देख सकें कि हर ‘सातवाँ’ का दशमलव वही चक्र 142857 प्रयोग करता है, और शेषफलों के बारे में तर्क कर सकें। कैलकुलेटर सटीक मान देने के बजाय संख्या काट देते हैं, और भाग फिर भी सीखना पड़ता है।"},
  {"id":"cdp-pedagogy-subjects-1798","question":"In dynamic geometry software, student P places four points by eye to make a square and joins them; student Q builds a square using perpendicular lines and a circle for equal sides. When the teacher drags a vertex, what is the main learning point?","options":["Both figures stay squares, since the software automatically corrects any small inaccuracy in drawing","Q's figure keeps its properties under dragging as they were built in; P's only looked like a square","P's figure is better, since freehand placement develops a feel for shapes that construction does not","Dragging distorts both figures in exactly the same way, so dragging is of little use in judging any figure"],"answer":1,"explanation":"The drag test separates a figure that merely looks right from one defined by its properties. Seeing P's ‘square’ collapse pushes students from appearance-based to property-based thinking.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2","questionHi":"गतिशील ज्यामिति सॉफ़्टवेयर में विद्यार्थी P वर्ग बनाने के लिए चार बिंदु आँख से रखता है और उन्हें जोड़ता है; विद्यार्थी Q लंब रेखाओं और बराबर भुजाओं के लिए एक वृत्त से वर्ग बनाता है। जब शिक्षिका एक शीर्ष को खींचती है, तो मुख्य अधिगम-बिंदु क्या है?","optionsHi":["दोनों आकृतियाँ वर्ग बनी रहती हैं, क्योंकि सॉफ़्टवेयर स्वतः चित्रण की किसी भी छोटी अशुद्धि को सुधार देता है","Q की आकृति खींचने पर अपने गुण बनाए रखती है क्योंकि वे उसमें निर्मित हैं; P की केवल वर्ग जैसी दिखती थी","P की आकृति बेहतर है, क्योंकि स्वतंत्र हाथ से रखना आकृतियों की वह समझ विकसित करता है जो रचना नहीं करती","खींचना दोनों आकृतियों को ठीक एक ही तरह बिगाड़ता है, इसलिए किसी भी आकृति को आँकने में खींचना बहुत कम काम का है"],"explanationHi":"खींचने की परीक्षा उस आकृति को जो केवल सही दिखती है उससे अलग करती है जो अपने गुणों से परिभाषित है। P के ‘वर्ग’ का बिखरना विद्यार्थियों को रूप-आधारित सोच से गुण-आधारित सोच की ओर ले जाता है।"},
  {"id":"cdp-pedagogy-subjects-1799","question":"Ravi recites every multiplication table up to 10 perfectly, but to find 7 × 8 he starts from ‘seven ones are seven’ and recites up. What should the teacher build next?","options":["More daily recitation of the tables, so that he can reach any fact in the sequence more quickly","Timed flash-card drills in random order until he can answer each fact within three seconds","Permission to use a calculator for all facts above 5 × 5, since he already knows the tables","Links among facts, such as 7 × 8 = 5 × 8 + 2 × 8, so that facts can be reached out of sequence"],"answer":3,"explanation":"His facts are stored as a chant, not as connected knowledge. Derived-fact strategies use what he knows to reach any fact directly and build understanding; more chanting strengthens the sequence, and timed drills add pressure without meaning.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"रवि 10 तक के सभी पहाड़े बिल्कुल सही सुनाता है, पर 7 × 8 निकालने के लिए वह ‘सात एकम सात’ से शुरू करके ऊपर बोलता जाता है। शिक्षिका को आगे क्या बनाना चाहिए?","optionsHi":["पहाड़ों का और रोज़ाना पाठ, ताकि वह क्रम में किसी भी तथ्य तक अधिक जल्दी पहुँच सके","यादृच्छिक क्रम में समयबद्ध फ़्लैश-कार्ड अभ्यास, जब तक वह हर तथ्य का उत्तर तीन सेकंड में न दे सके","5 × 5 से ऊपर के सभी तथ्यों के लिए कैलकुलेटर की अनुमति, क्योंकि वह पहाड़े पहले से जानता है","तथ्यों के बीच संबंध, जैसे 7 × 8 = 5 × 8 + 2 × 8, ताकि तथ्य क्रम से बाहर भी पहुँचे जा सकें"],"explanationHi":"उसके तथ्य सस्वर पाठ के रूप में संगृहीत हैं, जुड़े हुए ज्ञान के रूप में नहीं। व्युत्पन्न-तथ्य रणनीतियाँ उसके ज्ञात का उपयोग करके किसी भी तथ्य तक सीधे पहुँचती हैं और समझ बनाती हैं; और अधिक सस्वर पाठ क्रम को मज़बूत करता है, और समयबद्ध अभ्यास अर्थ के बिना दबाव जोड़ते हैं।"},
  {"id":"cdp-pedagogy-subjects-1800","question":"Consider these statements about a mathematics laboratory in school: I. It is mainly a room equipped with costly instruments. II. Its activities can use low-cost material such as paper folding, geoboards and beads. III. Its activities help students form conjectures and test them. IV. At the secondary stage it removes the need for proof. Which are correct?","options":["I and II only","I, III and IV only","II and III only","II, III and IV only"],"answer":2,"explanation":"A maths lab is an approach to exploring and conjecturing with simple materials, not a costly room (I is wrong). Activities can suggest and check results, but they do not replace proof (IV is wrong).","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"विद्यालय में गणित प्रयोगशाला के बारे में इन कथनों पर विचार कीजिए: I. यह मुख्यतः महँगे उपकरणों से सुसज्जित कमरा है। II. इसकी गतिविधियाँ कागज़ मोड़ने, ज्यामिति-पट्ट (geoboards) और मनकों जैसी कम लागत की सामग्री का उपयोग कर सकती हैं। III. इसकी गतिविधियाँ विद्यार्थियों को अनुमान (conjecture) बनाने और उन्हें परखने में मदद करती हैं। IV. माध्यमिक स्तर पर यह उपपत्ति की आवश्यकता समाप्त कर देती है। कौन-से सही हैं?","optionsHi":["केवल I और II","केवल I, III और IV","केवल II और III","केवल II, III और IV"],"explanationHi":"गणित प्रयोगशाला सरल सामग्री से खोजबीन और अनुमान लगाने का एक उपागम है, महँगा कमरा नहीं (I गलत है)। गतिविधियाँ परिणाम सुझा और जाँच सकती हैं, पर वे उपपत्ति की जगह नहीं लेतीं (IV गलत है)।"},
  {"id":"cdp-pedagogy-subjects-1801","question":"Class 4 children's estimates of the weight of a pumpkin range from 200 g to 50 kg. Which activity is most likely to improve their estimation?","options":["Let them lift benchmarks such as a 1 kg salt packet and a 500 g packet, and compare by hand before weighing","Teach them to convert grams into kilograms and back again, so that all their estimates use the right units","Give a small prize to the child whose guess comes closest each time, so that all the children try harder to estimate","Weigh every object on the scale straight away, so that children only work with exact values"],"answer":0,"explanation":"Good estimation rests on personal referents; handling a known 1 kg mass gives a reference to compare against. Unit conversion and prizes do not build a sense of weight, and weighing everything skips estimation entirely.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 के बच्चों के कद्दू के भार के अनुमान 200 g से 50 kg तक फैले हैं। कौन-सी गतिविधि उनके आकलन को सुधारने की सबसे अधिक संभावना रखती है?","optionsHi":["उन्हें 1 kg के नमक के पैकेट और 500 g के पैकेट जैसे मानक-बिंदु (benchmarks) उठाने देना, और तौलने से पहले हाथ से तुलना करना","उन्हें ग्राम को किलोग्राम और फिर वापस बदलना सिखाना, ताकि उनके सभी अनुमान सही इकाइयों में हों","हर बार जिसका अनुमान सबसे निकट हो उसे छोटा पुरस्कार देना, ताकि सभी बच्चे अनुमान लगाने में अधिक प्रयास करें","हर वस्तु को तुरंत तराजू पर तौलना, ताकि बच्चे केवल सटीक मानों के साथ काम करें"],"explanationHi":"अच्छा आकलन व्यक्तिगत संदर्भ-बिंदुओं पर टिका होता है; ज्ञात 1 kg द्रव्यमान को उठाना तुलना के लिए संदर्भ देता है। इकाई-परिवर्तन और पुरस्कार भार का बोध नहीं बनाते, और सब कुछ तौलना आकलन को पूरी तरह छोड़ देता है।"},
  {"id":"cdp-pedagogy-subjects-1802","question":"Class 7 students find that squares and regular hexagons tile a floor but regular pentagons do not. Which question best leads them towards the reason?","options":["Since a pentagon has an odd number of sides, can any shape with an odd number of sides tile a floor?","Are all the sides of the pentagon the same length as those of the hexagon and the square?","Is the regular pentagon a symmetrical shape, like the square and the regular hexagon?","What is each interior angle, and can copies of that angle meet at a point to make exactly 360°?"],"answer":3,"explanation":"A regular pentagon's angle is 108°, which does not divide 360°, so copies cannot fit around a point; 90° and 120° do. The odd-sides idea is a trap, since triangles tile, and symmetry or side length is not the issue.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 के विद्यार्थी पाते हैं कि वर्ग और समषट्भुज फ़र्श पर जड़ सकते हैं (टाइलिंग) पर समपंचभुज नहीं। कौन-सा प्रश्न उन्हें कारण की ओर सबसे अच्छी तरह ले जाता है?","optionsHi":["चूँकि पंचभुज की भुजाओं की संख्या विषम है, तो क्या विषम भुजाओं वाली कोई भी आकृति फ़र्श पर जड़ सकती है?","क्या पंचभुज की सभी भुजाएँ षट्भुज और वर्ग की भुजाओं के बराबर लंबाई की हैं?","क्या समपंचभुज एक सममित आकृति है, जैसे वर्ग और समषट्भुज?","हर आंतरिक कोण कितना है, और क्या उस कोण की प्रतिलिपियाँ एक बिंदु पर मिलकर ठीक 360° बना सकती हैं?"],"explanationHi":"समपंचभुज का कोण 108° है, जो 360° को विभाजित नहीं करता, इसलिए प्रतिलिपियाँ एक बिंदु के चारों ओर नहीं बैठ सकतीं; 90° और 120° बैठ सकते हैं। विषम भुजाओं वाला विचार एक जाल है, क्योंकि त्रिभुज जड़ते हैं, और सममिति या भुजा की लंबाई मुद्दा नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1803","question":"A teacher gives Class 6 students straws of 3 cm, 4 cm and 9 cm and asks them to make a triangle. They cannot. The main purpose of the task is for students to:","options":["practise measuring straws accurately to the nearest millimetre with a ruler","discover that the two shorter sides together must be longer than the third","learn that a triangle can be made only from three straws of equal length","see that triangles cannot be made from straws of three different lengths"],"answer":1,"explanation":"3 + 4 = 7 is less than 9, so the short straws cannot meet; trying different sets leads to the triangle inequality. Triangles with unequal sides are common, so the other conclusions are false.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षिका कक्षा 6 के विद्यार्थियों को 3 cm, 4 cm और 9 cm की स्ट्रॉ देती है और उनसे त्रिभुज बनाने को कहती है। वे नहीं बना पाते। इस कार्य का मुख्य उद्देश्य है कि विद्यार्थी:","optionsHi":["पटरी से स्ट्रॉ को निकटतम मिलीमीटर तक सटीक नापने का अभ्यास करें","खोजें कि दो छोटी भुजाओं का योग तीसरी से अधिक होना चाहिए","सीखें कि त्रिभुज केवल तीन बराबर लंबाई की स्ट्रॉ से ही बन सकता है","देखें कि तीन अलग-अलग लंबाइयों की स्ट्रॉ से त्रिभुज नहीं बन सकते"],"explanationHi":"3 + 4 = 7, जो 9 से कम है, इसलिए छोटी स्ट्रॉ मिल नहीं सकतीं; अलग-अलग समूह आज़माने से त्रिभुज असमिका तक पहुँचा जाता है। असमान भुजाओं वाले त्रिभुज आम हैं, इसलिए अन्य निष्कर्ष गलत हैं।"},
  {"id":"cdp-pedagogy-subjects-1804","question":"A shopkeeper asks Class 7 students which shoe size he should stock most. One student finds the mean of the sizes sold last month, 6.4, and recommends ‘size 6.4’. What is the best response?","options":["Accept it, since the mean is always the best single value to represent any set of data","Suggest using the range instead, since it shows how widely the sizes sold were spread","Point out that no shoe is sized 6.4; the mode, the size sold most often, answers his question","Suggest using the median instead, since it is not affected by a few unusually large or small sizes"],"answer":2,"explanation":"The question is which size is most in demand, which is the mode; a mean can give a value that does not exist in the data. Choosing an average means matching it to the question.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"एक दुकानदार कक्षा 7 के विद्यार्थियों से पूछता है कि उसे कौन-सा जूते का नाप सबसे अधिक रखना चाहिए। एक विद्यार्थी पिछले महीने बिके नापों का माध्य, 6.4, निकालती है और ‘नाप 6.4’ की सिफ़ारिश करती है। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["इसे स्वीकार करना, क्योंकि माध्य हमेशा किसी भी आँकड़ा-समूह को दर्शाने वाला सर्वश्रेष्ठ एकल मान होता है","इसके बजाय परिसर (range) का उपयोग सुझाना, क्योंकि वह दिखाता है कि बिके नाप कितने फैले थे","इंगित करना कि कोई जूता 6.4 नाप का नहीं होता; बहुलक (mode), यानी सबसे अधिक बिकने वाला नाप, उसके प्रश्न का उत्तर देता है","इसके बजाय माध्यिका (median) का उपयोग सुझाना, क्योंकि वह कुछ असामान्य रूप से बड़े या छोटे नापों से प्रभावित नहीं होती"],"explanationHi":"प्रश्न है कि कौन-सा नाप सबसे अधिक माँग में है, जो बहुलक है; माध्य ऐसा मान दे सकता है जो आँकड़ों में है ही नहीं। औसत चुनने का अर्थ है उसे प्रश्न से मिलाना।"},
  {"id":"cdp-pedagogy-subjects-1805","question":"A Class 8 student says, ‘A price cannot rise by 150%, because 100% is the whole thing.’ What is the most accurate response?","options":["A part of a whole cannot exceed 100%, but a rise is compared with the base: ₹40 up 150% is ₹100","Agree, since a percentage is always some part of a whole and so can never be more than one hundred","Percentages above 100 occur only in sports figures and need not be considered in ordinary arithmetic","Say that 150% is simply another way of writing 1.5 and that this point settles the student's doubt"],"answer":0,"explanation":"‘100% is the whole’ holds for part-of-whole situations. A percentage change compares with the starting value: 150% of ₹40 is ₹60, so the new price is ₹100. Converting 150% to 1.5 does not address the confusion.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 की एक विद्यार्थी कहती है, ‘किसी कीमत में 150% की वृद्धि नहीं हो सकती, क्योंकि 100% पूरी चीज़ है।’ सबसे सटीक प्रतिक्रिया क्या है?","optionsHi":["पूर्ण का कोई भाग 100% से अधिक नहीं हो सकता, पर वृद्धि की तुलना आधार से होती है: ₹40 में 150% की वृद्धि ₹100 है","सहमत होना, क्योंकि प्रतिशत हमेशा पूर्ण का कोई भाग होता है और इसलिए कभी एक सौ से अधिक नहीं हो सकता","100 से अधिक प्रतिशत केवल खेल के आँकड़ों में आते हैं और साधारण अंकगणित में उन पर विचार करने की आवश्यकता नहीं","कहना कि 150% बस 1.5 लिखने का दूसरा तरीका है और इस बात से विद्यार्थी का संदेह दूर हो जाता है"],"explanationHi":"‘100% पूरी चीज़ है’ भाग-पूर्ण की स्थितियों के लिए सही है। प्रतिशत परिवर्तन आरंभिक मान से तुलना करता है: ₹40 का 150% ₹60 है, इसलिए नई कीमत ₹100 है। 150% को 1.5 में बदलना उलझन को संबोधित नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-1806","question":"A Class 6 student evaluates 12 ÷ 3 × 2 as 2, explaining, ‘BODMAS says M comes before D.’ What is the best diagnosis?","options":["The student is right, since in the word BODMAS multiplication is written before division","The expression is ambiguous without brackets, so both 2 and 8 should be accepted","The student should have done 3 × 2 first, since the multiplication sign sits closer to the 3","Division and multiplication have equal priority and are done left to right, so the answer is 8"],"answer":3,"explanation":"(12 ÷ 3) × 2 = 8. The letter order in the mnemonic misleads students into ranking M above D; the convention is equal priority, worked left to right, which makes the expression unambiguous.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT","questionHi":"कक्षा 6 की एक विद्यार्थी 12 ÷ 3 × 2 का मान 2 निकालती है, यह समझाते हुए, ‘BODMAS कहता है कि M, D से पहले आता है।’ सबसे अच्छा निदान क्या है?","optionsHi":["विद्यार्थी सही है, क्योंकि BODMAS शब्द में गुणा भाग से पहले लिखा है","कोष्ठक के बिना व्यंजक अस्पष्ट है, इसलिए 2 और 8 दोनों स्वीकार किए जाने चाहिए","विद्यार्थी को पहले 3 × 2 करना चाहिए था, क्योंकि गुणा का चिह्न 3 के अधिक निकट है","भाग और गुणा की प्राथमिकता बराबर है और वे बाएँ से दाएँ किए जाते हैं, इसलिए उत्तर 8 है"],"explanationHi":"(12 ÷ 3) × 2 = 8। स्मरण-सूत्र में अक्षरों का क्रम विद्यार्थियों को M को D से ऊपर रखने के लिए भ्रमित करता है; परिपाटी बराबर प्राथमिकता और बाएँ से दाएँ की है, जो व्यंजक को अस्पष्टता-रहित बनाती है।"},
  {"id":"cdp-pedagogy-subjects-1807","question":"Which representation shows most clearly why 23 × 14 needs four partial products?","options":["A number line with fourteen jumps of 23, each labelled with the running total","A 23 by 14 rectangle split into 20 × 10, 20 × 4, 3 × 10 and 3 × 4 parts","The lattice method, with digits written in diagonal cells and added along diagonals","Writing 23 fourteen times in a column and adding them two at a time"],"answer":1,"explanation":"The area model shows 200 + 80 + 30 + 12 = 322: each part is one place-value product. Repeated addition and number-line jumps give the answer but hide the structure; the lattice gives the steps without their meaning.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कौन-सा निरूपण सबसे स्पष्ट रूप से दिखाता है कि 23 × 14 के लिए चार आंशिक गुणनफल क्यों चाहिए?","optionsHi":["संख्या-रेखा जिस पर 23 की चौदह छलाँगें हों, हर एक पर चालू योग लिखा हो","23 गुणा 14 का आयत जो 20 × 10, 20 × 4, 3 × 10 और 3 × 4 भागों में बँटा हो","जाली विधि (lattice method), जिसमें अंक विकर्णी खानों में लिखे जाते हैं और विकर्णों के अनुदिश जोड़े जाते हैं","23 को स्तंभ में चौदह बार लिखना और दो-दो करके जोड़ना"],"explanationHi":"क्षेत्रफल मॉडल 200 + 80 + 30 + 12 = 322 दिखाता है: हर भाग एक स्थानमान गुणनफल है। बार-बार जोड़ और संख्या-रेखा की छलाँगें उत्तर देती हैं पर संरचना छिपाती हैं; जाली विधि चरण देती है पर उनका अर्थ नहीं।"},
  {"id":"cdp-pedagogy-subjects-1808","question":"A Class 5 child thinks an angle is ‘the pointed corner’ and cannot decide which of two clock positions shows the bigger angle. Which activity best builds the missing idea?","options":["Measuring many angles drawn on paper with a protractor and recording their sizes","Memorising the names acute, obtuse, right and reflex angle, with a neat drawing of each kind","Turning their bodies, opening scissors and moving clock hands to compare amounts of turn","Drawing many angles with long arms so that the size of each angle is easy to see"],"answer":2,"explanation":"The child lacks the idea of an angle as an amount of turn. Turning activities build it directly; protractor work and names assume it, and long arms feed the arm-length misconception.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 का एक बच्चा सोचता है कि कोण ‘नुकीला कोना’ है और तय नहीं कर पाता कि घड़ी की दो स्थितियों में से कौन-सी बड़ा कोण दिखाती है। कौन-सी गतिविधि छूटे हुए विचार को सबसे अच्छी तरह बनाती है?","optionsHi":["कागज़ पर खींचे अनेक कोणों को चाँदे से नापना और उनके माप दर्ज करना","न्यून, अधिक, समकोण और प्रतिवर्ती कोण के नाम याद करना, हर प्रकार के साफ़-सुथरे चित्र के साथ","अपने शरीर को घुमाना, कैंची खोलना और घड़ी की सुइयाँ चलाना ताकि घुमाव की मात्राओं की तुलना हो","लंबी भुजाओं वाले अनेक कोण बनाना ताकि हर कोण का आकार आसानी से दिखे"],"explanationHi":"बच्चे में कोण को घुमाव की मात्रा के रूप में समझने का विचार नहीं है। घुमाने की गतिविधियाँ उसे सीधे बनाती हैं; चाँदे का काम और नाम उसे मानकर चलते हैं, और लंबी भुजाएँ भुजा-लंबाई वाली भ्रांति को पोषित करती हैं।"},
  {"id":"cdp-pedagogy-subjects-1809","question":"A Class 6 child says the volume of a stone cannot be found ‘because a stone has no length, breadth and height’. What is the best response?","options":["Let her lower the stone into a measuring cylinder of water and see how much the level rises","Have her treat the stone as a cuboid, measure its longest edges and multiply the three","Have her weigh the stone, since weight and volume are the same thing for solid objects","Agree that the volume of an irregular object is not defined until much higher classes"],"answer":0,"explanation":"Volume is the space an object takes up; water displacement measures it directly, and the formula l × b × h is just one method for cuboids. Treating the stone as a cuboid gives only a rough figure, and weight is a different quantity.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक बच्ची कहती है कि पत्थर का आयतन नहीं निकाला जा सकता ‘क्योंकि पत्थर की कोई लंबाई, चौड़ाई और ऊँचाई नहीं होती’। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["उसे पत्थर को पानी से भरे मापक सिलेंडर में डालने देना और देखना कि स्तर कितना बढ़ता है","उससे पत्थर को घनाभ मानने, उसके सबसे लंबे किनारे नापने और तीनों का गुणा करने को कहना","उससे पत्थर को तौलने को कहना, क्योंकि ठोस वस्तुओं के लिए भार और आयतन एक ही चीज़ हैं","सहमत होना कि अनियमित वस्तु का आयतन बहुत ऊँची कक्षाओं तक परिभाषित नहीं है"],"explanationHi":"आयतन वह स्थान है जो कोई वस्तु घेरती है; जल-विस्थापन उसे सीधे मापता है, और सूत्र l × b × h घनाभों के लिए केवल एक विधि है। पत्थर को घनाभ मानने से केवल मोटा मान मिलता है, और भार एक अलग राशि है।"},
  {"id":"cdp-pedagogy-subjects-1810","question":"A child is stuck on a word problem. The teacher asks, ‘What is 3 × 4? Good, 12. And what do we do with the 12 now? Add or subtract? Yes, subtract. So what is 20 − 12?’ The child gets the answer. Which description is most accurate?","options":["It is Socratic dialogue, which builds deep understanding through a chain of questions","It is scaffolding in the zone of proximal development, which will soon fade out on its own","It is focusing questioning, which brings the child's own reasoning into the open","It is funnelling: the teacher does the thinking, and the child only fills in small gaps"],"answer":3,"explanation":"Each question narrows the path until the child supplies only a trivial step, so the reasoning stays with the teacher. Focusing questions ask the child to explain what she notices and why; real scaffolding hands over thinking rather than taking it.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"एक बच्चा शाब्दिक प्रश्न पर अटका है। शिक्षिका पूछती है, ‘3 × 4 कितना है? अच्छा, 12। और अब इस 12 का हम क्या करें? जोड़ें या घटाएँ? हाँ, घटाएँ। तो 20 − 12 कितना है?’ बच्चा उत्तर पा लेता है। कौन-सा वर्णन सबसे सटीक है?","optionsHi":["यह सुकराती संवाद है, जो प्रश्नों की शृंखला से गहरी समझ बनाता है","यह निकटस्थ विकास के क्षेत्र में पाड़ (scaffolding) है, जो जल्दी ही अपने आप हट जाएगा","यह केंद्रित प्रश्न-विधि है, जो बच्चे के अपने तर्क को खुले में लाती है","यह फ़नलिंग (funnelling) है: शिक्षिका सोचने का काम करती है, और बच्चा केवल छोटी रिक्तियाँ भरता है"],"explanationHi":"हर प्रश्न मार्ग को तब तक संकरा करता है जब तक बच्चा केवल मामूली चरण देता है, इसलिए तर्क शिक्षिका के पास रहता है। केंद्रित प्रश्न बच्ची से समझाने को कहते हैं कि उसने क्या देखा और क्यों; वास्तविक पाड़ सोचना छीनने के बजाय सौंपता है।"},
  {"id":"cdp-pedagogy-subjects-1811","question":"For 302 − 297, child A uses the column method, borrows across the zero and gets 15; child B says, ‘297 to 300 is 3, and 2 more is 5.’ What should the teacher take from this?","options":["Child A has followed the correct standard method and only needs more practice in borrowing across zeros","Child B chose a strategy that suits these numbers, showing stronger number sense than the column method","Child B's method is a shortcut that works only for easy numbers and should be discouraged","Both children should be taught to use only the column method so that answers are consistent"],"answer":1,"explanation":"Seeing that 302 and 297 are close and counting up (difference = 5) is efficient and shows number sense; the column method across zeros is error-prone here. Flexible strategy choice should be encouraged, not replaced by one method.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"302 − 297 के लिए बच्चा A स्तंभ विधि अपनाता है, शून्य के पार उधार लेता है और 15 पाता है; बच्चा B कहता है, ‘297 से 300 तक 3 है, और 2 और, यानी 5।’ शिक्षिका को इससे क्या लेना चाहिए?","optionsHi":["बच्चा A ने सही मानक विधि अपनाई है और उसे केवल शून्यों के पार उधार लेने का और अभ्यास चाहिए","बच्चा B ने ऐसी रणनीति चुनी जो इन संख्याओं के अनुकूल है, जो स्तंभ विधि से अधिक मज़बूत संख्या-बोध दिखाता है","बच्चा B की विधि एक शॉर्टकट है जो केवल आसान संख्याओं पर काम करती है और उसे हतोत्साहित किया जाना चाहिए","दोनों बच्चों को केवल स्तंभ विधि सिखाई जानी चाहिए ताकि उत्तर सुसंगत हों"],"explanationHi":"यह देखना कि 302 और 297 पास-पास हैं और ऊपर गिनना (अंतर = 5) कुशल है और संख्या-बोध दिखाता है; यहाँ शून्यों के पार स्तंभ विधि त्रुटि-प्रवण है। लचीली रणनीति के चुनाव को प्रोत्साहित किया जाना चाहिए, एक विधि से बदला नहीं जाना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1812","question":"Finding the area of a leaf traced on squared paper, a Class 5 child counts every square the outline touches, even thin slivers, as a whole square. Which advice best fixes the method?","options":["Count only the squares that lie completely inside the outline, and leave out all the others","Measure the length and the breadth of the leaf and multiply them, as for a rectangle","Count squares more than half covered as whole ones and ignore those less than half covered","Use larger squares, so that fewer partial squares need to be counted along the edge"],"answer":2,"explanation":"Counting every partial square overestimates, and counting only full squares underestimates. The ‘more than half’ convention lets the over- and under-counts roughly balance; length × breadth suits only rectangles.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"वर्गाकार कागज़ पर बनाई पत्ती का क्षेत्रफल निकालते हुए कक्षा 5 का एक बच्चा रूपरेखा को छूने वाले हर वर्ग को, पतली कतरनों तक को, पूरा वर्ग गिन लेता है। कौन-सी सलाह विधि को सबसे अच्छी तरह ठीक करती है?","optionsHi":["केवल उन वर्गों को गिनना जो रूपरेखा के पूरी तरह भीतर हैं, और बाकी छोड़ देना","पत्ती की लंबाई और चौड़ाई नापना और आयत की तरह गुणा करना","आधे से अधिक ढके वर्गों को पूरा गिनना और आधे से कम ढके वर्गों की अनदेखी करना","बड़े वर्गों का उपयोग करना, ताकि किनारे पर कम आंशिक वर्ग गिनने पड़ें"],"explanationHi":"हर आंशिक वर्ग को गिनना अधिक आकलन देता है, और केवल पूरे वर्ग गिनना कम। ‘आधे से अधिक’ की परिपाटी अधिक और कम गिनती को लगभग संतुलित करती है; लंबाई × चौड़ाई केवल आयतों के लिए उपयुक्त है।"},
  {"id":"cdp-pedagogy-subjects-1813","question":"In the repeating pattern ▲ ■ ■ ▲ ■ ■ …, which answer and reasoning for the 20th shape is correct?","options":["■, because 20 leaves remainder 2 when divided by 3, and the 2nd shape of each unit is ■","▲, because 20 is an even number and the triangles come at the even positions","■, because the pattern has twice as many squares as triangles, so squares are likelier","▲, because 18 is a multiple of 3, so a new unit of the pattern begins at the 20th place"],"answer":0,"explanation":"The unit has 3 shapes; positions 19, 20, 21 are ▲, ■, ■ since 18 ends a unit. 20 = 3 × 6 + 2, so it is the 2nd shape, ■. Option C has the right shape but no valid reasoning.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"दोहराए जाने वाले पैटर्न ▲ ■ ■ ▲ ■ ■ … में 20वीं आकृति के लिए कौन-सा उत्तर और तर्क सही है?","optionsHi":["■, क्योंकि 20 पर शेषफल 2 बचता है जब उसे 3 से भाग दिया जाता है, और हर इकाई की दूसरी (2nd) आकृति ■ है","▲, क्योंकि 20 एक सम संख्या है और त्रिभुज सम स्थानों पर आते हैं","■, क्योंकि पैटर्न में त्रिभुजों से दोगुने वर्ग हैं, इसलिए वर्ग अधिक संभावित हैं","▲, क्योंकि 18, 3 का गुणज है, इसलिए पैटर्न की नई इकाई 20वें स्थान पर शुरू होती है"],"explanationHi":"इकाई में 3 आकृतियाँ हैं; स्थान 19, 20, 21 पर ▲, ■, ■ हैं क्योंकि 18 पर एक इकाई समाप्त होती है। 20 = 3 × 6 + 2, इसलिए यह दूसरी आकृति, ■ है। विकल्प C में आकृति सही है पर कोई वैध तर्क नहीं।"},
  {"id":"cdp-pedagogy-subjects-1814","question":"A Class 8 teacher asks, ‘About how many rotis are eaten in our school every day?’ Groups decide what to assume, estimate and compare answers. The main value of this task is that it:","options":["gives practice in multiplying large numbers quickly and accurately with no help","leads to an exact answer once the groups have surveyed every family in the school","checks whether students remember facts about nutrition learnt in science lessons","builds mathematical modelling: making assumptions, estimating and refining them"],"answer":3,"explanation":"Such Fermi problems have no single exact answer; their worth lies in choosing assumptions, estimating and judging how reasonable the result is, which is the modelling cycle.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 की एक शिक्षिका पूछती है, ‘हमारे विद्यालय में हर दिन लगभग कितनी रोटियाँ खाई जाती हैं?’ समूह तय करते हैं कि क्या मानें, अनुमान लगाते हैं और उत्तरों की तुलना करते हैं। इस कार्य का मुख्य मूल्य यह है कि यह:","optionsHi":["बिना सहायता के बड़ी संख्याओं को तेज़ी से और सटीक गुणा करने का अभ्यास देता है","समूहों द्वारा विद्यालय के हर परिवार का सर्वेक्षण कर लेने पर एक सटीक उत्तर तक ले जाता है","जाँचता है कि विद्यार्थियों को विज्ञान के पाठों में सीखे पोषण के तथ्य याद हैं या नहीं","गणितीय प्रतिरूपण (modelling) बनाता है: मान्यताएँ बनाना, अनुमान लगाना और उन्हें परिष्कृत करना"],"explanationHi":"ऐसे फ़र्मी (Fermi) प्रश्नों का कोई एक सटीक उत्तर नहीं होता; उनका मूल्य मान्यताएँ चुनने, अनुमान लगाने और परिणाम की उचितता का निर्णय करने में है, जो प्रतिरूपण-चक्र है।"},
  {"id":"cdp-pedagogy-subjects-1815","question":"Class 4 children measure the area of a tabletop by covering it with one-rupee coins, while one group uses bangles; the counts make little sense. What is the teacher's best follow-up?","options":["Ask every group to use the same coins, since the problem is only that the units differed","Discuss the gaps circles leave and find shapes, such as squares, that cover without gaps or overlaps","Ask them to measure the length and breadth of the table in centimetres instead of covering it","Give them bigger coins so that fewer coins are needed and the counting becomes easier"],"answer":1,"explanation":"A unit of area must tile the surface; circles leave gaps whatever their size, so even identical coins give a poor measure. Standardising alone does not fix this, and length and breadth skip the idea of covering.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 के बच्चे मेज़ के ऊपरी भाग का क्षेत्रफल एक-एक रुपये के सिक्कों से ढककर नापते हैं, जबकि एक समूह चूड़ियों का उपयोग करता है; गिनतियाँ बहुत कम अर्थपूर्ण हैं। शिक्षिका की सबसे अच्छी अनुवर्ती कार्रवाई क्या है?","optionsHi":["हर समूह से वही सिक्के उपयोग करने को कहना, क्योंकि समस्या केवल यह है कि इकाइयाँ अलग थीं","चर्चा करना कि वृत्त कौन-से खाली स्थान छोड़ते हैं और ऐसी आकृतियाँ खोजना, जैसे वर्ग, जो बिना खाली स्थान या अतिव्यापन के ढकती हैं","उनसे ढकने के बजाय मेज़ की लंबाई और चौड़ाई सेंटीमीटर में नापने को कहना","उन्हें बड़े सिक्के देना ताकि कम सिक्कों की आवश्यकता हो और गिनती आसान हो"],"explanationHi":"क्षेत्रफल की इकाई को सतह को पूरी तरह ढकना चाहिए (tile); वृत्त चाहे जैसे हों खाली स्थान छोड़ते हैं, इसलिए एक जैसे सिक्के भी खराब माप देते हैं। केवल मानकीकरण इसे ठीक नहीं करता, और लंबाई-चौड़ाई ढकने के विचार को छोड़ देती है।"},
  {"id":"cdp-pedagogy-subjects-1816","question":"Tossing a coin 10 times, a Class 7 child gets 7 heads and says the coin must be unfair. What is the best response?","options":["Pool all the class's tosses, hundreds in all, see what fraction are heads, and discuss small samples","Agree, since a fair coin always gives exactly 5 heads in 10 tosses and this coin did not","Ask her to toss the same coin 10 more times and decide from whichever result she gets","Tell her the chance of heads is exactly 1/2, so her result must have come from a mistake in counting the tosses"],"answer":0,"explanation":"Small samples vary a lot; 7 heads in 10 is quite common for a fair coin. Pooling many tosses shows the proportion settling near 1/2. Another 10 tosses is still a small sample.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"सिक्का 10 बार उछालने पर कक्षा 7 की एक बच्ची को 7 चित (heads) मिलते हैं और वह कहती है कि सिक्का अनुचित होगा। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["कक्षा के सभी उछाल, कुल सैकड़ों, मिलाना, देखना कि उनमें से कितना अंश चित है, और छोटे नमूनों पर चर्चा करना","सहमत होना, क्योंकि उचित सिक्का हमेशा ठीक 5 चित देता है 10 उछालों में और इस सिक्के ने नहीं दिया","उससे उसी सिक्के को 10 बार और उछालने को कहना और जो भी परिणाम मिले उससे निर्णय करना","उसे बताना कि चित की प्रायिकता ठीक 1/2 है, इसलिए उसका परिणाम उछालों की गिनती में किसी गलती से आया होगा"],"explanationHi":"छोटे नमूनों में बहुत विचलन होता है; उचित सिक्के के लिए 10 में 7 चित काफ़ी सामान्य है। बहुत-से उछाल मिलाने पर अनुपात 1/2 के निकट स्थिर होता दिखता है। 10 और उछाल अब भी छोटा नमूना है।"},
  {"id":"cdp-pedagogy-subjects-1817","question":"A Class 6 child plots the point (3, 5) by going 5 across and 3 up. Which response best helps her see why the order matters?","options":["Treat it as a spatial-reasoning difficulty and give her extra practice in copying shapes on square grids","Teach the trick that x comes before y in the alphabet, so the first number is always x","A partner game of calling and marking points, where mismatches show why an agreed order is needed","Have her plot twenty more points from the textbook exercise until the method becomes a habit"],"answer":2,"explanation":"The order of coordinates is a convention, and its purpose shows when two people must locate the same point. The game makes the need for an agreement felt; a mnemonic or drill fixes the habit without the reason.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक बच्ची बिंदु (3, 5) को 5 आड़े और 3 ऊपर जाकर आलेखित करती है। कौन-सी प्रतिक्रिया उसे यह देखने में सबसे अच्छी तरह मदद करती है कि क्रम क्यों मायने रखता है?","optionsHi":["इसे स्थानिक-तर्क की कठिनाई मानना और उसे वर्गाकार जालों पर आकृतियाँ उतारने का अतिरिक्त अभ्यास देना","यह युक्ति सिखाना कि x वर्णमाला में y से पहले आता है, इसलिए पहली संख्या हमेशा x है","बिंदु बोलने और चिह्नित करने का साथी-खेल, जहाँ बेमेल दिखाते हैं कि सहमत क्रम की आवश्यकता क्यों है","उससे पाठ्यपुस्तक के अभ्यास से बीस और बिंदु आलेखित करवाना जब तक विधि आदत न बन जाए"],"explanationHi":"निर्देशांकों का क्रम एक परिपाटी है, और उसका उद्देश्य तब दिखता है जब दो लोगों को एक ही बिंदु ढूँढना हो। खेल सहमति की आवश्यकता को महसूस कराता है; युक्ति या अभ्यास कारण के बिना आदत पक्की करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1818","question":"For a totally blind Class 4 child in an inclusive class, which tool is most suitable for doing arithmetic calculations?","options":["A large-print number chart placed close to her desk for easy reference","A talking calculator, so that she never needs to work through any steps","A Braille slate and stylus to copy sums down in the same layout as others","A Cranmer abacus, whose beads stay in place and can be read by touch"],"answer":3,"explanation":"The Cranmer abacus lets a blind learner set and read numbers by touch while working through the steps of a calculation. Large print helps low vision, not total blindness; a talking calculator skips the learning, and a slate is for writing.","difficulty":"moderate","source":"CTET · KVS PRT · DSSSB PRT","questionHi":"समावेशी कक्षा में कक्षा 4 की पूर्णतः दृष्टिहीन बच्ची के लिए अंकगणितीय गणनाएँ करने का कौन-सा उपकरण सबसे उपयुक्त है?","optionsHi":["उसके डेस्क के पास संदर्भ के लिए रखा बड़े अक्षरों वाला संख्या-चार्ट","बोलने वाला कैलकुलेटर, ताकि उसे कभी किसी चरण से गुज़रना न पड़े","ब्रेल स्लेट और स्टाइलस, दूसरों जैसी ही रचना में योग लिख लेने के लिए","क्रैनमर अबेकस (Cranmer abacus), जिसके मनके अपनी जगह रहते हैं और स्पर्श से पढ़े जा सकते हैं"],"explanationHi":"क्रैनमर अबेकस दृष्टिहीन अधिगमकर्ता को गणना के चरणों से गुज़रते हुए स्पर्श से संख्याएँ रखने और पढ़ने देता है। बड़े अक्षर कम दृष्टि में मदद करते हैं, पूर्ण दृष्टिहीनता में नहीं; बोलने वाला कैलकुलेटर सीखने को छोड़ देता है, और स्लेट लिखने के लिए है।"},
  {"id":"cdp-pedagogy-subjects-1819","question":"A Class 7 teacher introduces negative numbers through Brahmagupta's rules, stated in terms of ‘fortunes’ and ‘debts’. The main value of this is that it:","options":["shows that the ancient rules were more accurate than the rules for integers taught in schools today","gives integers a meaningful context and presents mathematics as a human, historical activity","replaces the number line, which is no longer needed once the rules are known","is mainly meant to build national pride rather than any mathematical understanding"],"answer":1,"explanation":"Brahmagupta's 7th-century rules framed positive and negative numbers as fortunes and debts, a context that makes operations meaningful and shows mathematics as developed by people over time. It complements the number line rather than replacing it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक शिक्षिका ऋणात्मक संख्याओं को ब्रह्मगुप्त के नियमों के माध्यम से परिचित कराती है, जो ‘धन’ (fortunes) और ‘ऋण’ (debts) के रूप में कहे गए हैं। इसका मुख्य मूल्य यह है कि यह:","optionsHi":["दिखाता है कि प्राचीन नियम आज विद्यालयों में पढ़ाए जाने वाले पूर्णांक-नियमों से अधिक सटीक थे","पूर्णांकों को सार्थक संदर्भ देता है और गणित को मानवीय, ऐतिहासिक गतिविधि के रूप में प्रस्तुत करता है","संख्या-रेखा की जगह लेता है, जिसकी नियम पता होने पर कोई आवश्यकता नहीं रहती","मुख्यतः किसी गणितीय समझ के बजाय राष्ट्रीय गौरव बनाने के लिए है"],"explanationHi":"ब्रह्मगुप्त के 7वीं सदी के नियमों ने धनात्मक और ऋणात्मक संख्याओं को धन और ऋण के रूप में रखा, जो संक्रियाओं को सार्थक बनाता है और दिखाता है कि गणित लोगों ने समय के साथ विकसित किया। यह संख्या-रेखा की जगह नहीं लेता, उसका पूरक है।"},
  {"id":"cdp-pedagogy-subjects-1820","question":"A child works out 25 × 16 as 50 × 8 = 100 × 4 = 400. Which explanation correctly justifies the method?","options":["Doubling one factor and halving the other keeps the product, since (25 × 2) × (16 ÷ 2) = 25 × 16","It works only because 25 and 16 are both perfect squares, so it would fail for most other numbers","It works because multiplication is commutative, which means 25 × 16 is the same as 16 × 25","It works only when one of the factors ends in 5, which is what makes doubling it possible"],"answer":0,"explanation":"Multiplying one factor by 2 and dividing the other by 2 leaves the product unchanged, for any numbers. Being perfect squares or ending in 5 is irrelevant, and commutativity is true but does not explain the steps.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक बच्चा 25 × 16 को 50 × 8 = 100 × 4 = 400 के रूप में निकालता है। कौन-सी व्याख्या विधि को सही ठहराती है?","optionsHi":["एक गुणक को दोगुना और दूसरे को आधा करने से गुणनफल बना रहता है, क्योंकि (25 × 2) × (16 ÷ 2) = 25 × 16","यह केवल इसलिए काम करता है कि 25 और 16 दोनों पूर्ण वर्ग हैं, इसलिए यह अधिकांश अन्य संख्याओं के लिए विफल होगा","यह इसलिए काम करता है कि गुणा क्रम-विनिमेय है, जिसका अर्थ है कि 25 × 16, 16 × 25 के समान है","यह तभी काम करता है जब कोई गुणक 5 पर समाप्त हो, जो उसे दोगुना करना संभव बनाता है"],"explanationHi":"एक गुणक को 2 से गुणा और दूसरे को 2 से भाग देने पर गुणनफल किन्हीं भी संख्याओं के लिए अपरिवर्तित रहता है। पूर्ण वर्ग होना या 5 पर समाप्त होना अप्रासंगिक है, और क्रम-विनिमेयता सत्य है पर चरणों की व्याख्या नहीं करती।"},
  {"id":"cdp-pedagogy-subjects-1821","question":"Class 3 children watch ants walking in a line to a sugar crystal, and most say the ants ‘can see the sugar from far away’. Which activity best tests this idea?","options":["Show a video of ants carrying food, so that children can watch how ants walk in a line to the food and back to the nest","Tell them that ants have poor eyesight and find food mainly by smell, and have them write this down in their notebooks","Wipe a finger across the ants' trail, watch what the ants do at the break, and discuss what they might be following","Count the ants in the line every five minutes and draw a bar graph showing how their number changes over time"],"answer":2,"explanation":"Breaking the trail and seeing the ants lose their way lets children gather evidence that the ants follow something on the ground (a scent), not something seen. Telling or watching a video gives no test, and counting ants does not address the idea.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 के बच्चे चींटियों को चीनी के क्रिस्टल की ओर पंक्ति में चलते देखते हैं, और अधिकांश कहते हैं कि चींटियाँ ‘दूर से चीनी देख सकती हैं’। कौन-सी गतिविधि इस विचार को सबसे अच्छी तरह परखती है?","optionsHi":["चींटियों के भोजन ले जाने का वीडियो दिखाना, ताकि बच्चे देख सकें कि चींटियाँ भोजन तक और वापस घोंसले तक पंक्ति में कैसे चलती हैं","उन्हें बताना कि चींटियों की दृष्टि कमज़ोर होती है और वे भोजन मुख्यतः गंध से ढूँढती हैं, और उनसे इसे अपनी कॉपियों में लिखवाना","चींटियों के मार्ग पर उँगली फेरना, देखना कि टूटी जगह पर चींटियाँ क्या करती हैं, और चर्चा करना कि वे किसका अनुसरण कर रही होंगी","पंक्ति में हर पाँच मिनट पर चींटियाँ गिनना और उनकी संख्या समय के साथ कैसे बदलती है उसका दंड-आलेख बनाना"],"explanationHi":"मार्ग तोड़ना और चींटियों को रास्ता भटकते देखना बच्चों को साक्ष्य इकट्ठा करने देता है कि चींटियाँ ज़मीन पर किसी चीज़ (गंध) का अनुसरण करती हैं, देखी हुई किसी चीज़ का नहीं। बताना या वीडियो देखना कोई परीक्षण नहीं देता, और चींटियाँ गिनना इस विचार को संबोधित नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-1822","question":"Class 5 children want to find which of three seeds (cotton, winged drumstick and mango) travels farthest in the wind. Which plan is a fair test?","options":["Drop each seed from the same height in front of the same fan setting, measure the distance, and repeat several times","Let each child throw a seed by hand as far as possible and measure how far each seed lands from the starting line","Let three groups test one seed each outdoors, at whatever time of day suits each group, and compare their distances","Drop each seed once from the classroom window and record which one lands farthest from the wall of the building"],"answer":0,"explanation":"Only the kind of seed should change; height and wind must stay the same, and repeating trials allows for chance. Throwing adds force, outdoor tests at different times vary the wind, and a single trial is unreliable.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के बच्चे यह पता लगाना चाहते हैं कि तीन बीजों (कपास, सहजन और आम) में से कौन-सा हवा में सबसे दूर जाता है। कौन-सी योजना निष्पक्ष परीक्षण है?","optionsHi":["हर बीज को पंखे की उसी सेटिंग के सामने उसी ऊँचाई से गिराना, दूरी नापना, और कई बार दोहराना","हर बच्चे को बीज हाथ से यथासंभव दूर फेंकने देना और नापना कि हर बीज शुरुआती रेखा से कितनी दूर गिरता है","तीन समूहों को बाहर एक-एक बीज परखने देना, दिन के उस समय जो हर समूह को अनुकूल लगे, और उनकी दूरियों की तुलना करना","हर बीज को कक्षा की खिड़की से एक बार गिराना और दर्ज करना कि इमारत की दीवार से कौन-सा सबसे दूर गिरता है"],"explanationHi":"केवल बीज का प्रकार बदलना चाहिए; ऊँचाई और हवा समान रहनी चाहिए, और परीक्षणों को दोहराने से संयोग का ध्यान रखा जाता है। फेंकने में बल जुड़ता है, अलग-अलग समय पर बाहरी परीक्षण हवा बदल देते हैं, और एक ही परीक्षण अविश्वसनीय है।"},
  {"id":"cdp-pedagogy-subjects-1823","question":"For the theme on waste, Class 5 children weigh and sort the school's dry and wet waste every day for a week and present suggestions to the principal. The strongest reason this beats a lecture on the 3Rs is that:","options":["it keeps children busy outside the classroom, which reduces noise and indiscipline during the EVS period","it covers the whole waste chapter faster than reading and discussing the textbook in the classroom","children handle waste with their hands, which is the main skill that EVS aims to build at this stage","children collect their own evidence on a real problem and act on it, linking knowledge to action"],"answer":3,"explanation":"Gathering data on their own school's waste and proposing changes makes the problem real and connects understanding with responsible action, a core aim of EVS. Covering the syllabus or keeping children busy is not the point.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"कचरे के विषय पर कक्षा 5 के बच्चे एक सप्ताह तक हर दिन विद्यालय का सूखा और गीला कचरा तौलते और छाँटते हैं और प्रधानाचार्य को सुझाव प्रस्तुत करते हैं। यह 3R पर व्याख्यान से बेहतर क्यों है, इसका सबसे मज़बूत कारण है कि:","optionsHi":["यह बच्चों को कक्षा के बाहर व्यस्त रखता है, जिससे EVS के पीरियड में शोर और अनुशासनहीनता घटती है","यह पाठ्यपुस्तक को कक्षा में पढ़ने और चर्चा करने से अधिक जल्दी पूरा कचरा-अध्याय कवर कर लेता है","बच्चे कचरे को हाथों से संभालते हैं, जो इस चरण में EVS द्वारा बनाया जाने वाला मुख्य कौशल है","बच्चे किसी वास्तविक समस्या पर अपना साक्ष्य स्वयं जुटाते हैं और उस पर कार्य करते हैं, ज्ञान को कार्य से जोड़ते हुए"],"explanationHi":"अपने ही विद्यालय के कचरे पर आँकड़े जुटाना और बदलाव सुझाना समस्या को वास्तविक बनाता है और समझ को उत्तरदायी कार्य से जोड़ता है, जो EVS का मूल उद्देश्य है। पाठ्यक्रम पूरा करना या बच्चों को व्यस्त रखना मुद्दा नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1824","question":"To show how a bird's beak suits its food, a teacher has children pick up grains, water and ‘worms’ (rubber bands) using tweezers, spoons and clothes pegs. After the activity, what is it most important for the teacher to do?","options":["Award marks to the fastest group, since speed shows which children best understood the beak shapes","Discuss how the model differs from real birds, which also use their tongue, neck and behaviour to feed","Move straight on to the next chapter, since the activity has already made the point clear to children","Ask children to memorise the names of birds with each beak type, so that they can answer test questions"],"answer":1,"explanation":"Every model is simplified; without discussing its limits, children may think beaks are rigid tools working alone. Drawing out the comparison turns a game into understanding.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"यह दिखाने के लिए कि पक्षी की चोंच उसके भोजन के अनुकूल कैसे होती है, एक शिक्षिका बच्चों से चिमटी, चम्मच और कपड़े की चिमटियों से अनाज, पानी और ‘कीड़े’ (रबर बैंड) उठवाती है। गतिविधि के बाद शिक्षिका के लिए सबसे महत्वपूर्ण क्या करना है?","optionsHi":["सबसे तेज़ समूह को अंक देना, क्योंकि गति दिखाती है कि किन बच्चों ने चोंच के आकार सबसे अच्छी तरह समझे","चर्चा करना कि मॉडल असली पक्षियों से कैसे भिन्न है, जो भोजन के लिए जीभ, गर्दन और व्यवहार का भी उपयोग करते हैं","सीधे अगले अध्याय पर चले जाना, क्योंकि गतिविधि ने बच्चों के लिए बात पहले ही स्पष्ट कर दी है","बच्चों से हर चोंच के प्रकार वाले पक्षियों के नाम रटवाना, ताकि वे परीक्षा-प्रश्नों के उत्तर दे सकें"],"explanationHi":"हर मॉडल सरलीकृत होता है; उसकी सीमाओं पर चर्चा के बिना बच्चे सोच सकते हैं कि चोंचें अकेले काम करने वाले कठोर उपकरण हैं। तुलना को सामने लाना खेल को समझ में बदलता है।"},
  {"id":"cdp-pedagogy-subjects-1825","question":"In the NCF for School Education 2023, the curricular area for Grades 3 to 5 that continues the integrated approach of EVS is called:","options":["The World Around Us","Science and Social Life","Our Environment and Science","Integrated General Studies"],"answer":0,"explanation":"NCF-SE 2023 names ‘The World Around Us’ as the integrated curricular area for the Preparatory Stage (Grades 3–5), drawing on science, social science and environmental education.","difficulty":"moderate","source":"CTET · KVS PRT · NVS PRT","questionHi":"स्कूली शिक्षा के लिए NCF 2023 में कक्षा 3 से 5 के लिए वह पाठ्यचर्या-क्षेत्र, जो EVS के एकीकृत उपागम को जारी रखता है, कहलाता है:","optionsHi":["हमारे आसपास की दुनिया (The World Around Us)","विज्ञान और सामाजिक जीवन (Science and Social Life)","हमारा पर्यावरण और विज्ञान (Our Environment and Science)","एकीकृत सामान्य अध्ययन (Integrated General Studies)"],"explanationHi":"NCF-SE 2023 प्रारंभिक चरण (कक्षा 3–5) के लिए एकीकृत पाठ्यचर्या-क्षेत्र का नाम ‘The World Around Us’ रखती है, जो विज्ञान, सामाजिक विज्ञान और पर्यावरण शिक्षा पर आधारित है।"},
  {"id":"cdp-pedagogy-subjects-1826","question":"On a morning walk, Class 4 children say: P. ‘The ground near the tap is wet.’ Q. ‘Someone must have left the tap open.’ R. ‘There are a dog's footprints in the mud.’ S. ‘The dog came here to drink water.’ Which of these are inferences rather than observations?","options":["P and R","Q and R","Q and S","P, Q and S"],"answer":2,"explanation":"P and R report what can be seen directly; Q and S go beyond what is seen to explain it, so they are inferences that might be wrong (rain, or a dog passing by). Separating the two is a key EVS process skill.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"सुबह की सैर पर कक्षा 4 के बच्चे कहते हैं: P. ‘नल के पास की ज़मीन गीली है।’ Q. ‘किसी ने नल खुला छोड़ दिया होगा।’ R. ‘कीचड़ में कुत्ते के पैरों के निशान हैं।’ S. ‘कुत्ता यहाँ पानी पीने आया था।’ इनमें से कौन-से अवलोकन के बजाय अनुमान (inferences) हैं?","optionsHi":["P और R","Q और R","Q और S","P, Q और S"],"explanationHi":"P और R वह बताते हैं जो सीधे देखा जा सकता है; Q और S जो देखा गया उससे आगे जाकर उसकी व्याख्या करते हैं, इसलिए वे अनुमान हैं जो गलत हो सकते हैं (वर्षा, या कुत्ते का गुज़रना)। दोनों को अलग करना EVS का एक प्रमुख प्रक्रिया-कौशल है।"},
  {"id":"cdp-pedagogy-subjects-1827","question":"A Class 3 child says an ‘empty’ bottle has nothing in it. Which activity best helps her rethink this?","options":["Show the textbook picture of air drawn inside a bottle and ask her to colour the air in it carefully","Push the bottle mouth-down into a bucket of water, then tilt it and watch the bubbles escape","Tell her that air is everywhere even though we cannot see it, and repeat this every day","Weigh the empty bottle on a kitchen scale to show that it weighs more than nothing at all"],"answer":1,"explanation":"Water cannot fill the inverted bottle until bubbles escape, which shows something was taking up the space. A kitchen scale cannot detect the air, and telling or colouring gives no evidence.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की एक बच्ची कहती है कि ‘खाली’ बोतल में कुछ नहीं होता। कौन-सी गतिविधि उसे इस पर पुनर्विचार करने में सबसे अच्छी तरह मदद करती है?","optionsHi":["पाठ्यपुस्तक में बोतल के अंदर हवा का चित्र दिखाना और उससे उसमें हवा में ध्यान से रंग भरने को कहना","बोतल को मुँह नीचे करके पानी की बाल्टी में दबाना, फिर उसे तिरछा करना और बुलबुलों को निकलते देखना","उसे बताना कि हवा हर जगह है भले ही हम उसे देख नहीं सकते, और इसे हर दिन दोहराना","खाली बोतल को रसोई के तराजू पर तौलना यह दिखाने के लिए कि उसका भार बिल्कुल शून्य से अधिक है"],"explanationHi":"औंधी बोतल को पानी तब तक नहीं भर सकता जब तक बुलबुले न निकलें, जो दिखाता है कि कोई चीज़ जगह घेर रही थी। रसोई का तराजू हवा का पता नहीं लगा सकता, और बताना या रंग भरना कोई साक्ष्य नहीं देते।"},
  {"id":"cdp-pedagogy-subjects-1828","question":"Looking at a globe, a Class 5 child asks, ‘Why don't people at the bottom fall off?’ Which response best addresses the idea behind the question?","options":["Explain that people in those places feel a little lighter, which is why they do not notice being upside down","Turn the globe so that India is at the bottom, to show that no place on earth is really at the bottom","Tell the child that gravity holds the people at the bottom on to the earth, and then move on with the lesson","Stick small figures all over the globe and discuss that ‘down’ for everyone means towards the earth's centre"],"answer":3,"explanation":"The question assumes one fixed ‘down’ for the whole universe. Showing figures standing everywhere, with ‘down’ always towards the centre, replaces that idea; turning the globe helps but does not explain ‘down’, and naming gravity explains nothing.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"ग्लोब देखते हुए कक्षा 5 का एक बच्चा पूछता है, ‘नीचे वाले लोग गिर क्यों नहीं जाते?’ कौन-सी प्रतिक्रिया प्रश्न के पीछे के विचार को सबसे अच्छी तरह संबोधित करती है?","optionsHi":["समझाना कि उन स्थानों पर लोग थोड़ा हल्का महसूस करते हैं, इसीलिए उन्हें उलटा होने का पता नहीं चलता","ग्लोब को घुमाकर भारत को नीचे करना, यह दिखाने के लिए कि पृथ्वी पर कोई भी स्थान वास्तव में नीचे नहीं है","बच्चे को बताना कि गुरुत्वाकर्षण नीचे के लोगों को पृथ्वी से थामे रखता है, और फिर पाठ आगे बढ़ाना","ग्लोब पर चारों ओर छोटी आकृतियाँ चिपकाना और चर्चा करना कि सबके लिए ‘नीचे’ का अर्थ पृथ्वी के केंद्र की ओर है"],"explanationHi":"प्रश्न पूरे ब्रह्मांड के लिए एक स्थिर ‘नीचे’ मान लेता है। हर जगह खड़ी आकृतियाँ दिखाना, जिनके लिए ‘नीचे’ हमेशा केंद्र की ओर है, उस विचार की जगह लेता है; ग्लोब घुमाना मदद करता है पर ‘नीचे’ को समझाता नहीं, और गुरुत्वाकर्षण का नाम लेना कुछ नहीं समझाता।"},
  {"id":"cdp-pedagogy-subjects-1829","question":"Class 5 children ask what would happen if all the frogs near a paddy field were caught for sale. Which line of thinking should the teacher encourage?","options":["Tracing links both ways: more insects that frogs eat, less food for frog-eating snakes and birds, harm to the crop","Concluding that nothing much would change, since frogs are small animals that do not eat the paddy crop","Concluding that only the snakes would be affected, since frogs are food for snakes and for no other animal","Memorising a food chain from the textbook that includes frogs, so that such questions can be answered well in the exam"],"answer":0,"explanation":"Removing one organism affects both what it eats and what eats it, and these effects spread through the web, here to insect pests and the crop. Single-link thinking misses the system.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के बच्चे पूछते हैं कि यदि धान के खेत के पास के सभी मेंढक बेचने के लिए पकड़ लिए जाएँ तो क्या होगा। शिक्षिका को चिंतन की कौन-सी दिशा प्रोत्साहित करनी चाहिए?","optionsHi":["दोनों ओर कड़ियाँ खोजना: मेंढकों द्वारा खाए जाने वाले अधिक कीट, मेंढक खाने वाले साँपों और पक्षियों के लिए कम भोजन, फ़सल को हानि","यह निष्कर्ष निकालना कि कुछ खास नहीं बदलेगा, क्योंकि मेंढक छोटे जंतु हैं जो धान की फ़सल नहीं खाते","यह निष्कर्ष निकालना कि केवल साँप प्रभावित होंगे, क्योंकि मेंढक साँपों का भोजन हैं और किसी अन्य जंतु का नहीं","पाठ्यपुस्तक से मेंढक वाली एक खाद्य शृंखला रटना, ताकि परीक्षा में ऐसे प्रश्नों के उत्तर अच्छी तरह दिए जा सकें"],"explanationHi":"किसी एक जीव को हटाने से उसका भोजन और उसे खाने वाले दोनों प्रभावित होते हैं, और ये प्रभाव जाल में फैलते हैं, यहाँ कीट-नाशकों और फ़सल तक। एकल-कड़ी वाली सोच तंत्र को चूक जाती है।"},
  {"id":"cdp-pedagogy-subjects-1830","question":"To assess Class 4 children's ‘concern for animals’, a teacher sets the written question, ‘Should we be kind to stray dogs? Give two reasons.’ What is the main problem with this?","options":["The question is too difficult for Class 4, since it demands two separate and well-argued reasons from each child","Attitudes cannot be assessed at all, so they should be kept out of EVS records altogether","Children tend to write the expected answer, so observing how they actually treat animals is more valid","The question should have been set as multiple choice, so that the marking is fully objective"],"answer":2,"explanation":"Written questions on values invite the ‘right’ answer and say little about real attitudes. Observations of behaviour over time (on walks, with class pets, during discussions) are the valid evidence.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"कक्षा 4 के बच्चों की ‘पशुओं के प्रति चिंता’ का आकलन करने के लिए एक शिक्षिका लिखित प्रश्न रखती है, ‘क्या हमें आवारा कुत्तों के प्रति दयालु होना चाहिए? दो कारण दीजिए।’ इसकी मुख्य समस्या क्या है?","optionsHi":["प्रश्न कक्षा 4 के लिए बहुत कठिन है, क्योंकि वह हर बच्चे से दो अलग और भली-भाँति तर्कित कारण माँगता है","अभिवृत्तियों का आकलन बिल्कुल नहीं हो सकता, इसलिए उन्हें EVS अभिलेखों से बाहर रखना चाहिए","बच्चे अपेक्षित उत्तर लिख देते हैं, इसलिए यह देखना कि वे वास्तव में पशुओं के साथ कैसा व्यवहार करते हैं अधिक वैध है","प्रश्न बहुविकल्पीय होना चाहिए था, ताकि अंकन पूरी तरह वस्तुनिष्ठ हो"],"explanationHi":"मूल्यों पर लिखित प्रश्न ‘सही’ उत्तर को आमंत्रित करते हैं और वास्तविक अभिवृत्तियों के बारे में बहुत कम बताते हैं। समय के साथ व्यवहार का अवलोकन (सैर पर, कक्षा के पालतू जीवों के साथ, चर्चाओं के दौरान) वैध साक्ष्य है।"},
  {"id":"cdp-pedagogy-subjects-1831","question":"A Class 3 teacher teaches ‘evaporation, condensation and precipitation’ with a printed cycle diagram that children must label. Which criticism is most in line with the NCERT EVS approach?","options":["The diagram should be replaced by a video, since moving pictures make the whole cycle easier to remember for tests","Abstract terms come before children have experienced and talked about the processes, such as wet clothes drying","Water is not part of the EVS syllabus in Class 3, so this topic should be left for later classes","The terms are correct, but children should also learn their written definitions by heart for revision"],"answer":1,"explanation":"Primary EVS builds from experience and the child's own words; technical terms and formal diagrams before that are abstract labels without meaning. Water is in fact a recurring EVS theme from Class 3.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की एक शिक्षिका ‘वाष्पीकरण, संघनन और अवक्षेपण’ को छपे चक्र-आरेख के साथ पढ़ाती है जिसे बच्चों को नामांकित करना है। NCERT के EVS उपागम के सबसे अनुरूप आलोचना कौन-सी है?","optionsHi":["आरेख की जगह वीडियो होना चाहिए, क्योंकि चलचित्र परीक्षाओं के लिए पूरे चक्र को याद रखना आसान बनाते हैं","अमूर्त शब्द इससे पहले आ जाते हैं कि बच्चों ने प्रक्रियाओं, जैसे गीले कपड़ों का सूखना, का अनुभव और उन पर बात की हो","पानी कक्षा 3 में EVS पाठ्यक्रम का हिस्सा नहीं है, इसलिए यह विषय बाद की कक्षाओं के लिए छोड़ना चाहिए","शब्द सही हैं, पर बच्चों को दोहराने के लिए उनकी लिखित परिभाषाएँ भी कंठस्थ करनी चाहिए"],"explanationHi":"प्राथमिक EVS अनुभव और बच्चे के अपने शब्दों से बनता है; उससे पहले तकनीकी शब्द और औपचारिक आरेख अर्थहीन अमूर्त नाम हैं। पानी वास्तव में कक्षा 3 से EVS का बार-बार आने वाला विषय है।"},
  {"id":"cdp-pedagogy-subjects-1832","question":"Class 4 children count their breaths per minute before and after running. After running, counts range from 25 to 45, and one child says, ‘Mine must be wrong, because it isn't the same as Priya's.’ What is the best response?","options":["Ask everyone to count again and again until all the counts in the class match each other","Take the class average as the correct value and change each child's sheet so that it matches the average","Discard the highest and the lowest counts, since these are probably counting errors","Discuss that bodies differ, so counts vary; what matters is that every child's count went up"],"answer":3,"explanation":"Natural variation is real data, not error. The pattern that matters is the rise in every child's breathing rate after exercise; forcing counts to agree or deleting extremes teaches children to distrust honest observation.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 के बच्चे दौड़ने से पहले और बाद में प्रति मिनट अपनी साँसें गिनते हैं। दौड़ने के बाद गिनतियाँ 25 से 45 तक फैली हैं, और एक बच्चा कहता है, ‘मेरी गलत होगी, क्योंकि वह प्रिया की जैसी नहीं है।’ सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["सभी से बार-बार गिनने को कहना जब तक कक्षा की सभी गिनतियाँ आपस में मेल न खा जाएँ","कक्षा के औसत को सही मान लेना और हर बच्चे की पर्ची बदल देना ताकि वह औसत से मेल खाए","सबसे अधिक और सबसे कम गिनतियाँ हटा देना, क्योंकि ये शायद गिनती की गलतियाँ हैं","चर्चा करना कि शरीर अलग-अलग होते हैं, इसलिए गिनतियाँ भिन्न होती हैं; महत्वपूर्ण यह है कि हर बच्चे की गिनती बढ़ी"],"explanationHi":"प्राकृतिक विचलन वास्तविक आँकड़ा है, त्रुटि नहीं। जो पैटर्न मायने रखता है वह व्यायाम के बाद हर बच्चे की साँस की दर में वृद्धि है; गिनतियों को मिलाने के लिए बाध्य करना या चरम हटाना बच्चों को ईमानदार अवलोकन पर अविश्वास करना सिखाता है।"},
  {"id":"cdp-pedagogy-subjects-1833","question":"A Class 4 child says that a black cat crossing the road brings bad luck, and several others agree. Which response best fits the aims of EVS?","options":["Ask where they heard it and how they could check it, e.g. noting what happens on days a cat crosses, without mocking","Explain the scientific facts about cats, and ask the children to tell their families at home that the belief is wrong","Avoid the topic, since beliefs from home lie outside the scope of EVS and may upset some parents","Leave the belief unchallenged in class, but present the scientific view separately in the next lesson"],"answer":0,"explanation":"EVS aims to build the habit of asking for evidence while respecting children's homes. Inviting them to think about how to check the claim does this; telling them to correct their families sets school against home.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 का एक बच्चा कहता है कि सड़क पार करती काली बिल्ली अपशकुन लाती है, और कई अन्य सहमत होते हैं। EVS के उद्देश्यों के सबसे अनुरूप प्रतिक्रिया कौन-सी है?","optionsHi":["पूछना कि उन्होंने यह कहाँ सुना और वे इसे कैसे जाँच सकते हैं, जैसे उन दिनों क्या होता है जब बिल्ली रास्ता काटती है, यह दर्ज करना, बिना उपहास किए","बिल्लियों के बारे में वैज्ञानिक तथ्य समझाना, और बच्चों से घर पर अपने परिवारों को बताने को कहना कि यह मान्यता गलत है","विषय से बचना, क्योंकि घर की मान्यताएँ EVS के दायरे से बाहर हैं और कुछ अभिभावकों को नाराज़ कर सकती हैं","कक्षा में मान्यता को चुनौती न देना, पर अगले पाठ में वैज्ञानिक दृष्टिकोण को अलग से प्रस्तुत करना"],"explanationHi":"EVS का उद्देश्य बच्चों के घरों का सम्मान करते हुए साक्ष्य माँगने की आदत बनाना है। उन्हें इस पर सोचने के लिए आमंत्रित करना कि दावा कैसे जाँचा जाए, यह करता है; उनसे अपने परिवारों को सुधारने को कहना विद्यालय को घर के विरुद्ध खड़ा करता है।"},
  {"id":"cdp-pedagogy-subjects-1834","question":"Class 4 children compare how much water sand, clay and garden soil hold, by pouring water through each in a funnel and measuring what drips out. What must be kept the same in each trial?","options":["Only the amount of water poured, since the soils themselves are meant to be different","The type of soil used in each funnel, so that the results can be compared fairly","The amount of soil, the amount of water and the same kind of funnel and filter","Only the time of day at which each trial is done, so that the room temperature is equal"],"answer":2,"explanation":"Soil type is what is being changed; everything else that could affect the result, the quantity of soil, the water poured and the funnel and filter, must be the same. Keeping only one factor fixed leaves the test unfair.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 के बच्चे तुलना करते हैं कि रेत, चिकनी मिट्टी और बगीचे की मिट्टी कितना पानी रोकती हैं, हर एक में कीप से पानी डालकर और जो टपके उसे नापकर। हर परीक्षण में क्या समान रखना चाहिए?","optionsHi":["केवल डाले गए पानी की मात्रा, क्योंकि मिट्टियाँ स्वयं भिन्न होनी हैं","हर कीप में प्रयुक्त मिट्टी का प्रकार, ताकि परिणामों की निष्पक्ष तुलना हो सके","मिट्टी की मात्रा, पानी की मात्रा और उसी प्रकार की कीप और छन्ना","केवल दिन का वह समय जिस पर हर परीक्षण किया जाता है, ताकि कमरे का तापमान बराबर हो"],"explanationHi":"मिट्टी का प्रकार वही है जो बदला जा रहा है; बाकी सब कुछ जो परिणाम को प्रभावित कर सकता है, मिट्टी की मात्रा, डाला गया पानी और कीप तथा छन्ना, समान होना चाहिए। केवल एक कारक को स्थिर रखने से परीक्षण अनुचित रहता है।"},
  {"id":"cdp-pedagogy-subjects-1835","question":"With eyes closed and noses pinched, many children cannot tell small pieces of apple from raw potato. The activity mainly shows that:","options":["the tongue cannot detect any taste at all when the eyes are kept closed","what we call flavour depends largely on smell working along with taste","apple and potato contain the same substances, so they taste the same","the tongue has separate zones, and pinching the nose blocks the sweet zone"],"answer":1,"explanation":"Much of what we experience as flavour comes from smell; blocking the nose leaves only basic tastes and texture. The ‘tongue zones’ map is a myth.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"आँखें बंद और नाक दबाकर बहुत-से बच्चे सेब और कच्चे आलू के छोटे टुकड़ों में अंतर नहीं बता पाते। यह गतिविधि मुख्यतः दिखाती है कि:","optionsHi":["आँखें बंद रखने पर जीभ किसी भी स्वाद का पता नहीं लगा सकती","जिसे हम स्वाद-सुगंध (flavour) कहते हैं वह बड़े हद तक स्वाद के साथ-साथ गंध के काम करने पर निर्भर है","सेब और आलू में समान पदार्थ हैं, इसलिए उनका स्वाद एक-सा है","जीभ में अलग-अलग क्षेत्र हैं, और नाक दबाने से मीठा क्षेत्र अवरुद्ध हो जाता है"],"explanationHi":"जिसे हम स्वाद-सुगंध के रूप में अनुभव करते हैं उसका बड़ा भाग गंध से आता है; नाक बंद करने पर केवल मूल स्वाद और बनावट बचते हैं। ‘जीभ के क्षेत्रों’ का नक्शा एक मिथक है।"},
  {"id":"cdp-pedagogy-subjects-1836","question":"A Class 5 child insists that bats are birds ‘because they fly’. Which approach best helps her?","options":["Tell her that bats are mammals and ask her to learn the full definition of a mammal by heart for the test","Point out that some birds, such as the ostrich, cannot fly, so flying is not a good test","Ask her to list all animals that fly, including insects, and to group them by flying alone","Compare features such as fur or feathers and milk or eggs, and discuss which features decide the group"],"answer":3,"explanation":"Grouping depends on a set of shared features, not one; comparing them shows why bats are with mammals. The ostrich example shows flight is not needed to be a bird, but not why bats are not birds.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक बच्ची आग्रह करती है कि चमगादड़ पक्षी हैं ‘क्योंकि वे उड़ते हैं’। कौन-सा उपागम उसकी सबसे अच्छी मदद करता है?","optionsHi":["उसे बताना कि चमगादड़ स्तनधारी हैं और उससे परीक्षा के लिए स्तनधारी की पूरी परिभाषा रटने को कहना","इंगित करना कि कुछ पक्षी, जैसे शुतुरमुर्ग, उड़ नहीं सकते, इसलिए उड़ना अच्छी कसौटी नहीं है","उससे सभी उड़ने वाले जंतुओं की सूची बनाने को कहना, कीटों सहित, और उन्हें केवल उड़ने के आधार पर समूहबद्ध करना","फर या पंख और दूध या अंडे जैसी विशेषताओं की तुलना करना, और चर्चा करना कि कौन-सी विशेषताएँ समूह तय करती हैं"],"explanationHi":"समूहन साझा विशेषताओं के एक समूह पर निर्भर करता है, किसी एक पर नहीं; उनकी तुलना दिखाती है कि चमगादड़ स्तनधारियों के साथ क्यों हैं। शुतुरमुर्ग का उदाहरण दिखाता है कि पक्षी होने के लिए उड़ना आवश्यक नहीं, पर यह नहीं कि चमगादड़ पक्षी क्यों नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-1837","question":"Class 4 children adopt one tree and, over several weeks, record every living thing they find on or around it. This activity is best suited to develop:","options":["sustained observation and the idea of a tree as a home and food source for many living things","the ability to draw a tree accurately, with all of its parts and branches clearly and neatly labelled","memory for the scientific names of the insects and birds that live on different trees","speed in collecting leaves and bark samples to add to the class herbarium collection"],"answer":0,"explanation":"Repeated observation of one tree reveals birds, insects, lichens and more, and shows interdependence in a habitat. Drawing, naming or collecting are not the main purpose.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 के बच्चे एक पेड़ को अपनाते हैं और कई सप्ताहों में उस पर या उसके आसपास पाए जाने वाले हर जीव को दर्ज करते हैं। यह गतिविधि सबसे अधिक किसे विकसित करने के लिए उपयुक्त है?","optionsHi":["सतत अवलोकन और पेड़ को अनेक जीवों के घर और भोजन-स्रोत के रूप में देखने का विचार","पेड़ को उसके सभी भागों और शाखाओं के साफ़-सुथरे नामांकन सहित सटीक बनाने की क्षमता","अलग-अलग पेड़ों पर रहने वाले कीटों और पक्षियों के वैज्ञानिक नामों की स्मृति","कक्षा के पादप-संग्रह में जोड़ने के लिए पत्तियाँ और छाल के नमूने इकट्ठा करने की गति"],"explanationHi":"एक पेड़ का बार-बार अवलोकन पक्षियों, कीटों, लाइकेन और अधिक को प्रकट करता है, और आवास में पारस्परिक निर्भरता दिखाता है। चित्र बनाना, नाम याद करना या इकट्ठा करना मुख्य उद्देश्य नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-1838","question":"Many Class 5 children in a city school say water ‘comes from the tap’. Which activity best extends their thinking?","options":["Show a chart of the water cycle and explain evaporation, condensation and rainfall to them in detail","Ask them to list all the uses of water at home and record them neatly in a table","Trace back from the tap to the tank, pipes, treatment plant and river or lake, with a visit or a map","Give them a reading passage about the rivers of India and set questions on it for homework"],"answer":2,"explanation":"Following the actual route of their water links the familiar tap to sources and systems they cannot see, which builds on their experience. A general water-cycle chart or a reading on rivers does not connect to the tap.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"शहरी विद्यालय के कक्षा 5 के बहुत-से बच्चे कहते हैं कि पानी ‘नल से आता है’। कौन-सी गतिविधि उनकी सोच को सबसे अच्छी तरह विस्तार देती है?","optionsHi":["जल-चक्र का चार्ट दिखाना और उन्हें वाष्पीकरण, संघनन और वर्षा विस्तार से समझाना","उनसे घर में पानी के सभी उपयोगों की सूची बनाने और उन्हें साफ़ सारणी में दर्ज करने को कहना","नल से टंकी, पाइपों, उपचार संयंत्र और नदी या झील तक पीछे की ओर मार्ग खोजना, यात्रा या मानचित्र के साथ","उन्हें भारत की नदियों पर एक पठन-गद्यांश देना और गृहकार्य के रूप में उस पर प्रश्न रखना"],"explanationHi":"उनके पानी के वास्तविक मार्ग का अनुसरण परिचित नल को उन स्रोतों और प्रणालियों से जोड़ता है जो वे देख नहीं सकते, जो उनके अनुभव पर निर्मित होता है। सामान्य जल-चक्र चार्ट या नदियों पर पठन नल से नहीं जुड़ता।"},
  {"id":"cdp-pedagogy-subjects-1839","question":"After an EVS chapter about a visually challenged child, a teacher has children walk blindfolded around the school for five minutes. Which follow-up makes the activity most meaningful?","options":["Ask them to describe how difficult it was, so that they understand how hard life must be for all blind people","Discuss what helped or blocked them, then audit the school for access and meet people about their abilities","Repeat the activity every week, so that children become skilled at moving about with their eyes covered","Have them write an essay on ‘If I were blind’ in the language period as a piece of creative writing"],"answer":1,"explanation":"A short simulation can leave only fear and pity (a deficit view). Turning it towards barriers in the environment and the abilities of visually challenged people shifts the focus to access and respect.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"दृष्टि-बाधित बच्चे के बारे में EVS अध्याय के बाद एक शिक्षिका बच्चों से पाँच मिनट तक आँखों पर पट्टी बाँधकर विद्यालय में चलवाती है। कौन-सी अनुवर्ती गतिविधि इसे सबसे अर्थपूर्ण बनाती है?","optionsHi":["उनसे वर्णन करने को कहना कि यह कितना कठिन था, ताकि वे समझें कि सभी नेत्रहीनों का जीवन कितना कठिन होता होगा","चर्चा करना कि क्या मदद या बाधा बना, फिर विद्यालय का पहुँच-संबंधी लेखा-जोखा करना और लोगों से उनकी क्षमताओं के बारे में मिलना","गतिविधि को हर सप्ताह दोहराना, ताकि बच्चे आँखें ढककर चलने में कुशल हो जाएँ","उनसे भाषा के पीरियड में रचनात्मक लेखन के रूप में ‘अगर मैं नेत्रहीन होता’ पर निबंध लिखवाना"],"explanationHi":"एक छोटा अनुकरण केवल भय और दया (अभाव-दृष्टि) छोड़ सकता है। उसे परिवेश की बाधाओं और दृष्टि-बाधित लोगों की क्षमताओं की ओर मोड़ना ध्यान को पहुँच और सम्मान पर ले जाता है।"},
  {"id":"cdp-pedagogy-subjects-1840","question":"Class 4 children say all insects are harmful and should be killed. Which response is most effective?","options":["Agree in the case of mosquitoes and houseflies, and move on, since the rest is beyond the syllabus for Class 4","Tell them that only a few insects bite, so most insects are neither harmful nor useful to us","Ask them to memorise a list of useful insects and the uses of each one for the unit test","Have them find out what bees, silkworms, ladybirds and dung beetles do, and imagine life without them"],"answer":3,"explanation":"Finding out the roles of pollinators, silk producers, pest-eaters and decomposers gives children evidence that challenges the generalisation and builds an idea of interdependence. A memorised list does not change their view.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 के बच्चे कहते हैं कि सभी कीट हानिकारक हैं और उन्हें मार देना चाहिए। कौन-सी प्रतिक्रिया सबसे प्रभावी है?","optionsHi":["मच्छरों और घरेलू मक्खियों के मामले में सहमत होना, और आगे बढ़ जाना, क्योंकि बाकी कक्षा 4 के पाठ्यक्रम से परे है","उन्हें बताना कि केवल कुछ कीट काटते हैं, इसलिए अधिकांश कीट हमारे लिए न हानिकारक हैं न उपयोगी","उनसे इकाई-परीक्षा के लिए उपयोगी कीटों की सूची और हर एक के उपयोग रटने को कहना","उनसे पता लगवाना कि मधुमक्खियाँ, रेशम के कीट, लेडीबर्ड और गोबरैले क्या करते हैं, और उनके बिना जीवन की कल्पना करवाना"],"explanationHi":"परागणकों, रेशम बनाने वालों, कीट-खाने वालों और अपघटकों की भूमिकाएँ खोजना बच्चों को वह साक्ष्य देता है जो सामान्यीकरण को चुनौती देता है और पारस्परिक निर्भरता का विचार बनाता है। रटी हुई सूची उनका दृष्टिकोण नहीं बदलती।"},
  {"id":"cdp-pedagogy-subjects-1841","question":"After a day of heavy rain in Jaisalmer, a Class 5 child says, ‘So Rajasthan is not a dry place after all.’ Which response best addresses her reasoning?","options":["Compare rainfall records over many years, showing that one rainy day does not change a long-term pattern","Agree with her, since the heavy rain proves that the textbook was wrong about the climate of that whole region","Explain that it never rains in deserts, so the news report she heard must have been a mistake","Ask her to read the textbook chapter on deserts again and to underline the important points"],"answer":0,"explanation":"Her error is judging climate (a long-term pattern) from one weather event. Records over years make the difference clear; saying deserts never get rain is itself false.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"जैसलमेर में एक दिन भारी वर्षा के बाद कक्षा 5 की एक बच्ची कहती है, ‘तो राजस्थान आखिर सूखी जगह नहीं है।’ कौन-सी प्रतिक्रिया उसके तर्क को सबसे अच्छी तरह संबोधित करती है?","optionsHi":["कई वर्षों के वर्षा अभिलेखों की तुलना करना, यह दिखाते हुए कि एक वर्षा का दिन दीर्घकालिक पैटर्न नहीं बदलता","उससे सहमत होना, क्योंकि भारी वर्षा सिद्ध करती है कि पाठ्यपुस्तक उस पूरे क्षेत्र की जलवायु के बारे में गलत थी","समझाना कि मरुस्थलों में कभी वर्षा नहीं होती, इसलिए उसने जो समाचार-रिपोर्ट सुनी वह गलत रही होगी","उससे मरुस्थलों वाला पाठ्यपुस्तक अध्याय फिर पढ़ने और महत्वपूर्ण बिंदुओं को रेखांकित करने को कहना"],"explanationHi":"उसकी त्रुटि एक मौसम की घटना से जलवायु (दीर्घकालिक पैटर्न) का निर्णय करना है। वर्षों के अभिलेख अंतर को स्पष्ट करते हैं; यह कहना कि मरुस्थलों में कभी वर्षा नहीं होती, स्वयं गलत है।"},
  {"id":"cdp-pedagogy-subjects-1842","question":"Facing her friend across a table, a Class 4 child gives directions on a map: ‘From the gate, turn right to the well.’ Her friend, holding the map the other way round, goes the wrong way. What should the teacher help children build?","options":["Memory for the four cardinal directions, recited daily in a chant until every child knows them by heart","Taking another's viewpoint, and using landmarks or fixed directions (north, east), not just ‘left’ and ‘right’","The habit of always holding maps with the written labels upright, whichever way one happens to be facing at the time","The skill of drawing larger maps with brighter colours, so that routes are easier to follow"],"answer":1,"explanation":"‘Left’ and ‘right’ depend on which way one faces; giving directions others can follow needs perspective-taking and fixed references. Holding labels upright ignores the reader's real orientation.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"मेज़ के आर-पार अपनी सहेली के सामने बैठी कक्षा 4 की एक बच्ची मानचित्र पर दिशाएँ देती है: ‘फाटक से दाएँ मुड़ो, कुएँ तक।’ उसकी सहेली, मानचित्र को उलटी ओर पकड़े हुए, गलत दिशा में चली जाती है। शिक्षिका को बच्चों में क्या बनाने में मदद करनी चाहिए?","optionsHi":["चार मुख्य दिशाओं की स्मृति, जिन्हें हर बच्चे के कंठस्थ होने तक रोज़ सस्वर पढ़ाया जाए","दूसरे के दृष्टिकोण को लेना, और केवल ‘बाएँ’ और ‘दाएँ’ नहीं, बल्कि स्थलचिह्नों या निश्चित दिशाओं (उत्तर, पूर्व) का उपयोग करना","मानचित्रों को हमेशा लिखित नामों को सीधा रखकर पकड़ने की आदत, चाहे उस समय कोई किसी भी ओर मुँह करके हो","चटक रंगों से बड़े मानचित्र बनाने का कौशल, ताकि मार्ग आसानी से दिखें"],"explanationHi":"‘बाएँ’ और ‘दाएँ’ इस पर निर्भर करते हैं कि कोई किस ओर मुँह करके है; दूसरों के अनुसरण योग्य दिशाएँ देने के लिए दृष्टिकोण-ग्रहण और निश्चित संदर्भ चाहिए। नाम सीधे रखना पाठक के वास्तविक अभिविन्यास की अनदेखी करता है।"},
  {"id":"cdp-pedagogy-subjects-1843","question":"A Class 5 child classifies the potato as a root ‘because it grows underground’. Which approach is best?","options":["Tell her that the potato is really a stem and ask her to memorise it along with other such examples","Agree with her, since all the parts of a plant that grow underground are its roots","Let her sprout the ‘eyes’ (buds) of a potato, compare with a carrot, and discuss what buds suggest","Show a labelled diagram of a plant and ask her to copy it neatly into her notebook"],"answer":2,"explanation":"Potato eyes are buds, which grow on stems; sprouting them gives evidence that the potato is an underground stem, unlike the carrot, a root. Growing underground is not what makes a part a root.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक बच्ची आलू को जड़ के रूप में वर्गीकृत करती है ‘क्योंकि वह ज़मीन के नीचे उगता है’। सबसे अच्छा उपागम कौन-सा है?","optionsHi":["उसे बताना कि आलू वास्तव में तना है और उससे इसे ऐसे ही अन्य उदाहरणों के साथ रटने को कहना","उससे सहमत होना, क्योंकि पौधे के ज़मीन के नीचे उगने वाले सभी भाग उसकी जड़ें होते हैं","उसे आलू की ‘आँखों’ (कलियों) को अंकुरित करने देना, गाजर से तुलना करना, और चर्चा करना कि कलियाँ क्या सुझाती हैं","पौधे का नामांकित आरेख दिखाना और उससे उसे अपनी कॉपी में साफ़ उतारने को कहना"],"explanationHi":"आलू की आँखें कलियाँ हैं, जो तनों पर उगती हैं; उन्हें अंकुरित करना साक्ष्य देता है कि आलू भूमिगत तना है, गाजर के विपरीत जो जड़ है। ज़मीन के नीचे उगना किसी भाग को जड़ नहीं बनाता।"},
  {"id":"cdp-pedagogy-subjects-1844","question":"Class 5 children join a bird count, recording the birds they see near school every week and sending the data to a nationwide project. The greatest value of this is that:","options":["they learn the names of all the birds of India for the inter-school quiz held every winter","it replaces textbook reading, which children find dull at this stage","the birds near the school will be protected because they have been counted","they take part in real science, adding data and seeing patterns such as winter visitors"],"answer":3,"explanation":"Contributing to a citizen-science project gives children authentic observation and recording, a sense that their data matters, and patterns such as seasonal migration they can see for themselves.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के बच्चे पक्षी-गणना में भाग लेते हैं, हर सप्ताह विद्यालय के पास दिखने वाले पक्षियों को दर्ज करते हैं और आँकड़े राष्ट्रव्यापी परियोजना को भेजते हैं। इसका सबसे बड़ा मूल्य यह है कि:","optionsHi":["वे हर सर्दी में होने वाली अंतर-विद्यालय प्रश्नोत्तरी के लिए भारत के सभी पक्षियों के नाम सीखते हैं","यह पाठ्यपुस्तक-पठन की जगह लेता है, जो बच्चों को इस चरण में नीरस लगता है","विद्यालय के पास के पक्षी इसलिए सुरक्षित होंगे क्योंकि उनकी गिनती हो चुकी है","वे वास्तविक विज्ञान में भाग लेते हैं, आँकड़े जोड़ते हैं और शीतकालीन अतिथियों जैसे पैटर्न देखते हैं"],"explanationHi":"नागरिक-विज्ञान (citizen-science) परियोजना में योगदान बच्चों को प्रामाणिक अवलोकन और अभिलेखन, इस भावना कि उनके आँकड़े मायने रखते हैं, और मौसमी प्रवास जैसे पैटर्न जो वे स्वयं देख सकते हैं, देता है।"},
  {"id":"cdp-pedagogy-subjects-1845","question":"Children in a city school say they see only a few stars at night, while their cousins in a village see many. What is the best use of this observation?","options":["Investigate why together, comparing dark and lit spots, and discuss how artificial light hides faint stars","Explain that there are far fewer stars in the sky above cities than there are above villages and forests","Tell them that in cities the stars can be seen clearly only during the cold and dry winter months of the year","Ask them to memorise the names and shapes of the main constellations instead"],"answer":0,"explanation":"Children's own observations are a starting point for inquiry; comparing locations leads to the idea of light pollution. The same stars are above both places, so the second option is false.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"शहरी विद्यालय के बच्चे कहते हैं कि वे रात में केवल कुछ तारे देखते हैं, जबकि गाँव में उनके चचेरे भाई-बहन बहुत-से देखते हैं। इस अवलोकन का सबसे अच्छा उपयोग क्या है?","optionsHi":["मिलकर जाँच करना कि ऐसा क्यों है, अँधेरे और रोशनी वाले स्थानों की तुलना करना, और चर्चा करना कि कृत्रिम प्रकाश धुँधले तारों को कैसे छिपा देता है","समझाना कि शहरों के ऊपर के आकाश में गाँवों और जंगलों के ऊपर की तुलना में कहीं कम तारे होते हैं","उन्हें बताना कि शहरों में तारे केवल वर्ष के ठंडे और शुष्क सर्दी के महीनों में ही साफ़ दिखते हैं","उनसे इसके बजाय मुख्य तारामंडलों के नाम और आकार रटने को कहना"],"explanationHi":"बच्चों के अपने अवलोकन जाँच का आरंभ-बिंदु हैं; स्थानों की तुलना प्रकाश-प्रदूषण के विचार तक ले जाती है। दोनों स्थानों के ऊपर वही तारे हैं, इसलिए दूसरा विकल्प गलत है।"},
  {"id":"cdp-pedagogy-subjects-1846","question":"For an EVS model, a teacher asks every child to buy chart paper, sketch pens and thermocol. Several children come empty-handed and are scolded. What is the best change?","options":["Exempt the poorer children from the project so that they are not embarrassed in class","Plan with waste and local materials (cartons, clay, leaves) shared in groups, so all can take part","Let each group share one set of bought materials while keeping the same model design","Ask all the parents to pay a fixed amount into a class fund from which the materials are then bought"],"answer":1,"explanation":"Using freely available materials removes the cost barrier and the stigma, and is closer to the spirit of EVS. Exemption excludes children, and pooled buying or fees still burden poorer families.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"EVS मॉडल के लिए एक शिक्षिका हर बच्चे से चार्ट पेपर, स्केच पेन और थर्मोकोल खरीदने को कहती है। कई बच्चे खाली हाथ आते हैं और उन्हें डाँटा जाता है। सबसे अच्छा बदलाव क्या है?","optionsHi":["गरीब बच्चों को परियोजना से छूट देना ताकि वे कक्षा में शर्मिंदा न हों","बेकार और स्थानीय सामग्री (गत्ते के डिब्बे, मिट्टी, पत्ते) से योजना बनाना, समूहों में साझा करके, ताकि सब भाग ले सकें","हर समूह को खरीदी गई सामग्री का एक ही सेट साझा करने देना और मॉडल का डिज़ाइन वही रखना","सभी अभिभावकों से कक्षा-कोष में निश्चित राशि जमा करने को कहना जिससे फिर सामग्री खरीदी जाए"],"explanationHi":"आसानी से उपलब्ध सामग्री का उपयोग लागत की बाधा और कलंक को हटाता है, और EVS की भावना के अधिक निकट है। छूट बच्चों को बाहर करती है, और साझा खरीद या शुल्क फिर भी गरीब परिवारों पर बोझ डालते हैं।"},
  {"id":"cdp-pedagogy-subjects-1847","question":"For the theme on work, a teacher's homework asks children to write their parents' monthly income and the value of their house. What is the most serious problem?","options":["The amounts are too large for children of this age to write correctly in figures","Many parents may not know the exact figures, so the answers will not be accurate","It intrudes on family privacy and can shame poorer children; questions about the work itself serve the aim","Family income is not part of the EVS syllabus at this stage, so it cannot be discussed in the classroom at all"],"answer":2,"explanation":"The theme is about kinds of work and how people do it; asking for income and property exposes families and invites comparison and shame. Sensitive framing is part of good EVS planning.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"‘काम’ विषय के लिए एक शिक्षिका का गृहकार्य बच्चों से अपने माता-पिता की मासिक आय और अपने घर का मूल्य लिखने को कहता है। सबसे गंभीर समस्या क्या है?","optionsHi":["इस आयु के बच्चों के लिए राशियाँ अंकों में सही-सही लिखने के लिहाज़ से बहुत बड़ी हैं","कई अभिभावकों को सटीक आँकड़े पता नहीं होंगे, इसलिए उत्तर सटीक नहीं होंगे","यह पारिवारिक निजता में दखल है और गरीब बच्चों को शर्मिंदा कर सकता है; काम के बारे में ही प्रश्न उद्देश्य की पूर्ति करते हैं","पारिवारिक आय इस चरण में EVS पाठ्यक्रम का हिस्सा नहीं है, इसलिए कक्षा में उस पर चर्चा हो ही नहीं सकती"],"explanationHi":"विषय काम के प्रकारों और लोग उसे कैसे करते हैं, इसके बारे में है; आय और संपत्ति पूछना परिवारों को उजागर करता है और तुलना तथा शर्म को आमंत्रित करता है। संवेदनशील ढंग से प्रस्तुत करना अच्छी EVS योजना का हिस्सा है।"},
  {"id":"cdp-pedagogy-subjects-1848","question":"Many Class 3 children say ‘the fox is cunning and the crow is foolish’, citing stories. What is the best response?","options":["Explain that animals act on instinct, so words like cunning and foolish describe people rather than animals","Read them other fables in which the fox is foolish and the crow is clever, so that they hear both sides","Ask each child to draw the fox and the crow and write beneath each picture the trait it shows in the story","Enjoy the fables as stories, then compare them with what real foxes and crows are observed to do"],"answer":3,"explanation":"The EVS task is to help children separate story traits from observed behaviour while still valuing fables as stories; real crows, for instance, solve problems well. Reading counter-fables is tempting, but it swaps one story stereotype for another instead of turning children to evidence.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 के बहुत-से बच्चे कहानियों का हवाला देकर कहते हैं ‘लोमड़ी चालाक है और कौआ मूर्ख’। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["समझाना कि जंतु सहज-प्रवृत्ति से काम करते हैं, इसलिए चालाक और मूर्ख जैसे शब्द जानवरों के बजाय लोगों का वर्णन करते हैं","उन्हें ऐसी अन्य दंतकथाएँ पढ़कर सुनाना जिनमें लोमड़ी मूर्ख और कौआ चतुर है, ताकि वे दोनों पक्ष सुनें","हर बच्चे से लोमड़ी और कौए का चित्र बनाने और हर चित्र के नीचे कहानी में दिखने वाला गुण लिखने को कहना","दंतकथाओं का कहानियों के रूप में आनंद लेना, फिर उनकी तुलना उससे करना जो असली लोमड़ियों और कौओं को करते देखा गया है"],"explanationHi":"EVS का कार्य बच्चों को कहानी के गुणों को देखे गए व्यवहार से अलग करने में मदद करना है, साथ ही दंतकथाओं को कहानियों के रूप में महत्व देना; उदाहरण के लिए असली कौए समस्याएँ अच्छी तरह सुलझाते हैं। उलटी दंतकथाएँ पढ़ना आकर्षक है, पर वह बच्चों को साक्ष्य की ओर मोड़ने के बजाय एक कहानी की रूढ़ि को दूसरी से बदल देता है।"},
  {"id":"cdp-pedagogy-subjects-1849","question":"A Class 4 child says water in a matka stays cool ‘because clay is a cold material’. Which activity best helps?","options":["Wrap one bottle in a wet cloth and one in a dry cloth, keep both in a breeze, and compare after an hour","Explain the term ‘evaporation’ in detail and have children copy its definition into their notebooks for revision","Have children touch a clay pot and a steel pot to find out which material feels colder to the hand","Ask them to draw a matka and label its parts, then write two lines about its uses at home"],"answer":0,"explanation":"The wet-cloth bottle cools because water evaporating from the surface takes away heat, which is what the porous matka does. Touching pots tests the child's idea on her own terms and may simply confirm it.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 4 का एक बच्चा कहता है कि मटके का पानी ठंडा रहता है ‘क्योंकि मिट्टी ठंडा पदार्थ है’। कौन-सी गतिविधि सबसे अधिक मदद करती है?","optionsHi":["एक बोतल को गीले कपड़े में और एक को सूखे कपड़े में लपेटना, दोनों को हवा में रखना, और एक घंटे बाद तुलना करना","‘वाष्पीकरण’ शब्द को विस्तार से समझाना और बच्चों से दोहराने के लिए उसकी परिभाषा अपनी कॉपियों में उतारने को कहना","बच्चों से मिट्टी के बर्तन और स्टील के बर्तन को छूने को कहना ताकि पता चले कि कौन-सा पदार्थ हाथ को अधिक ठंडा लगता है","उनसे मटके का चित्र बनाने और उसके भागों को नामांकित करने, फिर घर में उसके उपयोगों के बारे में दो पंक्तियाँ लिखने को कहना"],"explanationHi":"गीले कपड़े वाली बोतल इसलिए ठंडी होती है कि सतह से वाष्पित होता पानी ऊष्मा ले जाता है, जो छिद्रयुक्त मटका करता है। बर्तनों को छूना बच्चे के विचार को उसकी अपनी शर्तों पर परखता है और केवल उसकी पुष्टि कर सकता है।"},
  {"id":"cdp-pedagogy-subjects-1850","question":"A Class 3 child says fish do not need air because they live in water. Which starting point is best?","options":["Explain that fish breathe by taking the oxygen that is part of each water molecule (H₂O) through their gills","Watch a fish in a bowl, noting its moving gill covers, and ask why fish gulp at the surface in stale water","Show her a video of a whale rising to breathe at the surface, to show that water animals also need air","Tell her that fish breathe through gills and ask her to label the gills on a diagram of a fish in her notebook"],"answer":1,"explanation":"Observing gill movement and surface gulping in stale water lets the child see that fish take something from the water, leading to the idea of air dissolved in it. The whale video is tempting, but a whale is a mammal with lungs, so it says nothing about how fish get air; and fish use dissolved oxygen, not the oxygen bound in H₂O.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की एक बच्ची कहती है कि मछलियों को हवा की आवश्यकता नहीं होती क्योंकि वे पानी में रहती हैं। कौन-सा आरंभ-बिंदु सबसे अच्छा है?","optionsHi":["समझाना कि मछलियाँ प्रत्येक जल अणु (H₂O) का भाग ऑक्सीजन अपने गलफड़ों से लेकर साँस लेती हैं","कटोरे में मछली को देखना, उसके हिलते गलफड़ों के ढक्कनों को नोट करना, और पूछना कि बासी पानी में मछलियाँ सतह पर क्यों हाँफती हैं","उसे व्हेल का सतह पर साँस लेने के लिए उठने का वीडियो दिखाना, यह दिखाने के लिए कि जल के जंतुओं को भी हवा चाहिए","उसे बताना कि मछलियाँ गलफड़ों से साँस लेती हैं और उससे मछली के आरेख पर अपनी कॉपी में गलफड़े नामांकित करने को कहना"],"explanationHi":"गलफड़ों की गति और बासी पानी में सतह पर हाँफने का अवलोकन बच्ची को देखने देता है कि मछलियाँ पानी से कुछ लेती हैं, जो उसमें घुली हवा के विचार तक ले जाता है। व्हेल का वीडियो आकर्षक है, पर व्हेल फेफड़ों वाली स्तनधारी है, इसलिए वह मछलियों को हवा कैसे मिलती है इस बारे में कुछ नहीं बताता; और मछलियाँ घुली हुई ऑक्सीजन का उपयोग करती हैं, H₂O में बँधी ऑक्सीजन का नहीं।"},
  {"id":"cdp-pedagogy-subjects-1851","question":"During a Class 10 lesson, a student dismisses evolution as ‘just a theory, not a proven fact’. Which response best addresses the misunderstanding?","options":["Agree that it is only a theory, and say that it will become a law once it has been fully proved by experiments","Explain that in science a theory is a well-tested explanation backed by many lines of evidence, not a guess","Avoid the point, since students are free to believe whatever they like about the origin of living things","Tell the student that every scientist accepts evolution, so the student should accept it on their authority"],"answer":1,"explanation":"The objection mixes the everyday sense of ‘theory’ (a hunch) with the scientific sense (a well-substantiated explanation). Theories do not turn into laws; laws describe patterns, theories explain them. Appeal to authority is not the scientific way to settle it.","difficulty":"very-hard","source":"KVS TGT · NVS TGT · CTET Paper 2","questionHi":"कक्षा 10 के पाठ के दौरान एक विद्यार्थी विकासवाद को ‘बस एक सिद्धांत, सिद्ध तथ्य नहीं’ कहकर खारिज करता है। कौन-सी प्रतिक्रिया इस गलतफहमी को सबसे अच्छी तरह संबोधित करती है?","optionsHi":["सहमत होना कि वह केवल सिद्धांत है, और कहना कि प्रयोगों से पूरी तरह सिद्ध होने पर वह नियम बन जाएगा","समझाना कि विज्ञान में सिद्धांत अनेक साक्ष्यों से समर्थित, भली-भाँति परखा हुआ स्पष्टीकरण है, अनुमान नहीं","बात से बचना, क्योंकि जीवों की उत्पत्ति के बारे में विद्यार्थी जो चाहें मान सकते हैं","विद्यार्थी को बताना कि हर वैज्ञानिक विकासवाद को स्वीकार करता है, इसलिए विद्यार्थी को उनके अधिकार पर उसे स्वीकार करना चाहिए"],"explanationHi":"आपत्ति ‘सिद्धांत’ के रोज़मर्रा के अर्थ (अनुमान) को वैज्ञानिक अर्थ (भली-भाँति प्रमाणित स्पष्टीकरण) से मिला देती है। सिद्धांत नियम नहीं बन जाते; नियम पैटर्न का वर्णन करते हैं, सिद्धांत उनकी व्याख्या करते हैं। अधिकार का सहारा लेना इसे तय करने का वैज्ञानिक तरीका नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1852","question":"After pushing the plunger of a sealed syringe of air, Class 9 students draw the particles inside as smaller circles than before. What is the best teaching response?","options":["Praise the drawing, since squeezing a gas really does make each of its particles shrink a little","Tell them to draw the same number of particles, which is the only problem in the drawing","Have them repeat the activity with water, which they will find compresses just as easily","Ask what is between the particles and whether the particles or the gaps between them change"],"answer":3,"explanation":"Compression reduces the empty space between particles; the particles themselves do not shrink. Students often transfer bulk changes (smaller volume) to the particles, so questioning what changes helps them refine the model.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"हवा से भरी बंद सिरिंज का प्लंजर दबाने के बाद कक्षा 9 के विद्यार्थी भीतर के कणों को पहले से छोटे वृत्तों के रूप में बनाते हैं। सबसे अच्छी शिक्षण-प्रतिक्रिया क्या है?","optionsHi":["चित्र की प्रशंसा करना, क्योंकि गैस को दबाने से उसका हर कण वास्तव में थोड़ा सिकुड़ जाता है","उनसे कणों की उतनी ही संख्या बनाने को कहना, जो चित्र की एकमात्र समस्या है","उनसे यही गतिविधि पानी के साथ दोहराने को कहना, जो उन्हें उतनी ही आसानी से संपीड़ित होता मिलेगा","पूछना कि कणों के बीच क्या है और क्या कण बदलते हैं या उनके बीच की खाली जगहें"],"explanationHi":"संपीड़न कणों के बीच की खाली जगह घटाता है; कण स्वयं नहीं सिकुड़ते। विद्यार्थी प्रायः स्थूल परिवर्तनों (घटा आयतन) को कणों पर आरोपित कर देते हैं, इसलिए यह पूछना कि क्या बदलता है उन्हें मॉडल को परिष्कृत करने में मदद करता है।"},
  {"id":"cdp-pedagogy-subjects-1853","question":"Asked to predict, most Class 8 students say steel wool will weigh less after burning, ‘as burnt things become ash’. When it is burnt on a balance, the mass goes up. How should the teacher use this result?","options":["As a puzzle to explain: the iron has combined with oxygen from the air, so the product has more mass","As a sign that the balance was faulty, since burning always makes a substance lighter than before","As an exception to note quickly, since steel wool behaves unusually and is rarely burnt in daily life","As proof that mass is not conserved in chemical reactions, which the textbook should have said clearly"],"answer":0,"explanation":"The surprise creates cognitive conflict: the gain comes from oxygen joining the iron, so mass is conserved once all reactants are counted. Wood seems to lose mass because its products escape as gases.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"अनुमान लगाने को कहे जाने पर कक्षा 8 के अधिकांश विद्यार्थी कहते हैं कि जलने के बाद स्टील वूल का भार कम होगा, ‘क्योंकि जली चीज़ें राख बन जाती हैं’। जब उसे तराजू पर जलाया जाता है, तो द्रव्यमान बढ़ जाता है। शिक्षिका को इस परिणाम का उपयोग कैसे करना चाहिए?","optionsHi":["एक पहेली के रूप में जिसे समझाया जाए: लोहे ने हवा की ऑक्सीजन के साथ संयोग किया है, इसलिए उत्पाद का द्रव्यमान अधिक है","इस संकेत के रूप में कि तराजू दोषपूर्ण था, क्योंकि जलने से पदार्थ हमेशा पहले से हल्का हो जाता है","एक अपवाद के रूप में जिसे जल्दी नोट कर लिया जाए, क्योंकि स्टील वूल असामान्य व्यवहार करती है और रोज़मर्रा में शायद ही जलाई जाती है","इस सबूत के रूप में कि रासायनिक अभिक्रियाओं में द्रव्यमान संरक्षित नहीं रहता, जो पाठ्यपुस्तक को स्पष्ट रूप से कहना चाहिए था"],"explanationHi":"आश्चर्य संज्ञानात्मक द्वंद्व पैदा करता है: बढ़ोतरी लोहे में ऑक्सीजन के जुड़ने से आती है, इसलिए सभी अभिकारकों को गिनने पर द्रव्यमान संरक्षित रहता है। लकड़ी का द्रव्यमान घटता लगता है क्योंकि उसके उत्पाद गैसों के रूप में निकल जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1854","question":"A Class 7 teacher has students make turmeric paper and test soap solution, lemon juice and water with it. The soap solution turns the paper red. The main value of this activity is that:","options":["it replaces the need to learn about litmus and other indicators used in laboratories","it proves that turmeric is the most accurate indicator available for any substance","it uses everyday materials to show how indicators reveal bases, linking lab ideas to home","it shows that all yellow substances turn red when they are mixed with any kitchen liquid at all"],"answer":2,"explanation":"Turmeric turns red in a basic solution such as soap; making indicators from kitchen materials makes the concept concrete and cheap. It complements, not replaces, standard indicators, and does not show turmeric is the best one.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक शिक्षिका विद्यार्थियों से हल्दी का कागज़ बनवाती है और उससे साबुन के घोल, नींबू के रस और पानी की जाँच करवाती है। साबुन का घोल कागज़ को लाल कर देता है। इस गतिविधि का मुख्य मूल्य यह है कि:","optionsHi":["यह लिटमस और प्रयोगशालाओं में प्रयुक्त अन्य सूचकों के बारे में सीखने की आवश्यकता की जगह लेती है","यह सिद्ध करती है कि हल्दी किसी भी पदार्थ के लिए उपलब्ध सबसे सटीक सूचक है","यह रोज़मर्रा की सामग्री का उपयोग करके दिखाती है कि सूचक क्षारों को कैसे प्रकट करते हैं, प्रयोगशाला के विचारों को घर से जोड़ते हुए","यह दिखाती है कि सभी पीले पदार्थ रसोई के किसी भी तरल के साथ मिलाने पर लाल हो जाते हैं"],"explanationHi":"हल्दी साबुन जैसे क्षारीय घोल में लाल हो जाती है; रसोई की सामग्री से सूचक बनाना संकल्पना को मूर्त और सस्ता बनाता है। यह मानक सूचकों का पूरक है, उनकी जगह नहीं लेती, और यह नहीं दिखाती कि हल्दी सर्वश्रेष्ठ है।"},
  {"id":"cdp-pedagogy-subjects-1855","question":"A Class 8 student says that whenever she has a cold, her family gives her an antibiotic ‘to kill the germs’. In a lesson on microorganisms, what is the most useful response?","options":["Explain that colds are mostly viral, antibiotics act only on bacteria, and needless use breeds resistance","Explain that antibiotics are best kept for severe colds, such as those with a high fever lasting several days","Explain that antibiotics do work on colds but must be taken for the full course so that the germs do not return","Suggest that she ask her doctor about a vaccine for the common cold instead, since prevention is better than cure"],"answer":0,"explanation":"Colds are caused mainly by viruses, which antibiotics do not affect, and needless use breeds resistant bacteria. The 'full course' advice is tempting because it is sound for bacterial infections, but here it endorses using antibiotics on a viral illness; there is also no vaccine for the common cold.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 की एक विद्यार्थी कहती है कि जब भी उसे सर्दी-ज़ुकाम होता है, उसका परिवार उसे ‘कीटाणु मारने के लिए’ एंटीबायोटिक देता है। सूक्ष्मजीवों के पाठ में सबसे उपयोगी प्रतिक्रिया क्या है?","optionsHi":["समझाना कि सर्दी-ज़ुकाम मुख्यतः वायरल होते हैं, एंटीबायोटिक केवल जीवाणुओं पर काम करते हैं, और अनावश्यक उपयोग प्रतिरोध पैदा करता है","समझाना कि एंटीबायोटिक गंभीर सर्दी-ज़ुकाम के लिए सबसे अच्छे रखे जाते हैं, जैसे जिनमें कई दिन तक तेज़ बुखार रहता है","समझाना कि एंटीबायोटिक सर्दी-ज़ुकाम पर काम करते हैं पर उन्हें पूरा कोर्स लेना चाहिए ताकि कीटाणु वापस न आएँ","सुझाना कि वह इसके बजाय अपने डॉक्टर से सामान्य सर्दी के टीके के बारे में पूछे, क्योंकि रोकथाम इलाज से बेहतर है"],"explanationHi":"सर्दी-ज़ुकाम मुख्यतः वायरस से होते हैं, जिन पर एंटीबायोटिक असर नहीं करते, और अनावश्यक उपयोग प्रतिरोधी जीवाणु पैदा करता है। ‘पूरा कोर्स’ वाली सलाह आकर्षक है क्योंकि वह जीवाणु संक्रमणों के लिए सही है, पर यहाँ वह वायरल बीमारी पर एंटीबायोटिक के उपयोग का समर्थन करती है; सामान्य सर्दी का कोई टीका भी नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1856","question":"After a lesson on food chains, a Class 10 student writes, ‘Energy goes round and round in an ecosystem, just like water and carbon.’ Which statement should the teacher help the student reach?","options":["Energy and matter both cycle, but energy cycles much more slowly than carbon","Energy is used up completely at each level, so none is left for decomposers","Matter cycles, but energy flows one way, entering as light and leaving as heat","Energy cycles only in water ecosystems, where it is carried by the water cycle"],"answer":2,"explanation":"Nutrients such as carbon are recycled by decomposers, but energy enters as sunlight, passes along food chains with large losses as heat at every step, and is not reused. Decomposers do get energy from dead matter, so the second option is wrong.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"खाद्य शृंखलाओं के पाठ के बाद कक्षा 10 का एक विद्यार्थी लिखता है, ‘पारितंत्र में ऊर्जा चक्र में घूमती है, ठीक जल और कार्बन की तरह।’ शिक्षिका को विद्यार्थी को कौन-से कथन तक पहुँचाने में मदद करनी चाहिए?","optionsHi":["ऊर्जा और पदार्थ दोनों चक्रित होते हैं, पर ऊर्जा कार्बन से बहुत अधिक धीरे चक्रित होती है","ऊर्जा हर स्तर पर पूरी तरह खप जाती है, इसलिए अपघटकों के लिए कुछ नहीं बचता","पदार्थ चक्रित होता है, पर ऊर्जा एक ही दिशा में प्रवाहित होती है, प्रकाश के रूप में प्रवेश करती और ऊष्मा के रूप में निकल जाती है","ऊर्जा केवल जलीय पारितंत्रों में चक्रित होती है, जहाँ उसे जल-चक्र वहन करता है"],"explanationHi":"कार्बन जैसे पोषक तत्व अपघटकों द्वारा पुनर्चक्रित होते हैं, पर ऊर्जा सूर्य-प्रकाश के रूप में प्रवेश करती है, खाद्य शृंखलाओं में हर चरण पर ऊष्मा के रूप में बड़ी हानि के साथ आगे बढ़ती है, और दोबारा उपयोग नहीं होती। अपघटकों को मृत पदार्थ से ऊर्जा मिलती है, इसलिए दूसरा विकल्प गलत है।"},
  {"id":"cdp-pedagogy-subjects-1857","question":"Class 9 students plot distance against time for a toy car and join every point with short straight lines, giving a zig-zag graph. What should the teacher help them understand?","options":["The zig-zag is the most honest graph possible, because it passes through each and every measured point","They should have used a bar graph, since each reading is a separate measurement taken at a separate time","Graphs should be drawn freehand without a ruler, so that they look smoother and closer to real motion","Every reading has some error, so a smooth line of best fit shows the trend better than joining the dots"],"answer":3,"explanation":"Measured points scatter because of measurement error; a best-fit line or curve shows the underlying relation and lets students judge outliers. Joining every dot treats each error as real motion.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"कक्षा 9 के विद्यार्थी खिलौना-कार की दूरी बनाम समय का आलेख बनाते हैं और हर बिंदु को छोटी सीधी रेखाओं से जोड़ देते हैं, जिससे टेढ़ा-मेढ़ा (zig-zag) आलेख बनता है। शिक्षिका को उन्हें क्या समझने में मदद करनी चाहिए?","optionsHi":["टेढ़ा-मेढ़ा आलेख सबसे ईमानदार संभव आलेख है, क्योंकि वह हर मापे गए बिंदु से गुज़रता है","उन्हें दंड-आलेख इस्तेमाल करना चाहिए था, क्योंकि हर पाठ्यांक अलग समय पर लिया गया अलग माप है","आलेख बिना पटरी के हाथ से बनाने चाहिए, ताकि वे अधिक चिकने और वास्तविक गति के निकट दिखें","हर पाठ्यांक में कुछ त्रुटि होती है, इसलिए चिकनी सर्वोत्तम-बैठ (best fit) रेखा प्रवृत्ति को बिंदु जोड़ने से बेहतर दिखाती है"],"explanationHi":"मापे गए बिंदु मापन-त्रुटि के कारण बिखरते हैं; सर्वोत्तम-बैठ रेखा या वक्र अंतर्निहित संबंध दिखाता है और विद्यार्थियों को विचलित मानों (outliers) का निर्णय करने देता है। हर बिंदु को जोड़ना हर त्रुटि को वास्तविक गति मान लेता है।"},
  {"id":"cdp-pedagogy-subjects-1858","question":"In a Class 8 school, every student's practical record has an identical ‘Aim, Apparatus, Procedure, Result’ copied from a guide, with no data of their own. Which change best improves learning from practicals?","options":["Check the records more strictly for neatness and completeness, and deduct marks for any copied page","Have students record their own data and write, in their own words, what they found and why","Give students a printed format for every experiment so that the writing is quicker and more uniform","Drop written records entirely and assess practicals only through the viva held at the end of the year"],"answer":1,"explanation":"A practical record is meant to capture what students actually observed and how they interpreted it. Recording their own data and reasoning makes the write-up part of thinking; stricter checking or fixed formats keep it a copying exercise.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 के एक विद्यालय में हर विद्यार्थी की प्रायोगिक कॉपी में गाइड से उतारे एक जैसे ‘उद्देश्य, उपकरण, विधि, परिणाम’ हैं, और अपना कोई आँकड़ा नहीं है। प्रयोगों से सीखने को कौन-सा बदलाव सबसे अच्छी तरह सुधारता है?","optionsHi":["कॉपियों की साफ़-सफ़ाई और पूर्णता की अधिक कड़ाई से जाँच करना, और किसी उतारे हुए पन्ने पर अंक काटना","विद्यार्थियों से अपने आँकड़े दर्ज करवाना और अपने शब्दों में लिखवाना कि उन्होंने क्या पाया और क्यों","हर प्रयोग के लिए छपा प्रारूप देना ताकि लेखन तेज़ और अधिक एकरूप हो","लिखित अभिलेख पूरी तरह छोड़ देना और प्रयोगों का आकलन केवल वर्ष के अंत की मौखिकी (viva) से करना"],"explanationHi":"प्रायोगिक कॉपी का उद्देश्य यह दर्ज करना है कि विद्यार्थियों ने वास्तव में क्या देखा और उसकी व्याख्या कैसे की। अपने आँकड़े और तर्क दर्ज करना लेखन को सोचने का हिस्सा बनाता है; कड़ी जाँच या निश्चित प्रारूप उसे उतारने का अभ्यास बनाए रखते हैं।"},
  {"id":"cdp-pedagogy-subjects-1859","question":"A teacher asks Class 8 groups to answer ‘Does salt make ice melt faster?’ as a claim, the evidence for it and the reasoning linking the two. Which group's answer best fits this format?","options":["‘Salt melts ice faster. Everyone knows that salt is spread on icy roads in cold countries to clear them in winter.’","‘Salt makes ice melt. We think this is because salt is a very strong and hot chemical.’","‘Salt makes ice melt faster: salted cubes melted in 6 minutes, plain in 11; salt lowers the melting point.’","‘Our salted ice cubes melted in 6 minutes and the plain ones in 11 minutes.’"],"answer":2,"explanation":"Claim–evidence–reasoning needs all three: a claim, the group's own data and a scientific reason linking them. The others give common knowledge instead of evidence, a wrong reason without data, or data with no claim or reasoning.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षिका कक्षा 8 के समूहों से ‘क्या नमक बर्फ़ को तेज़ी से पिघलाता है?’ का उत्तर दावे, उसके साक्ष्य और दोनों को जोड़ने वाले तर्क के रूप में देने को कहती है। किस समूह का उत्तर इस प्रारूप में सबसे अच्छा बैठता है?","optionsHi":["‘नमक बर्फ़ को तेज़ी से पिघलाता है। सब जानते हैं कि ठंडे देशों में सर्दियों में बर्फ़ीली सड़कें साफ़ करने के लिए नमक बिखेरा जाता है।’","‘नमक बर्फ़ को पिघलाता है। हमारे विचार से यह इसलिए है कि नमक बहुत तेज़ और गर्म रसायन है।’","‘नमक बर्फ़ को तेज़ी से पिघलाता है: नमक वाले टुकड़े 6 मिनट में पिघले, सादे 11 में; नमक गलनांक घटाता है।’","‘हमारे नमक वाले बर्फ़ के टुकड़े 6 मिनट में पिघले और सादे वाले 11 मिनट में।’"],"explanationHi":"दावा–साक्ष्य–तर्क में तीनों चाहिए: दावा, समूह के अपने आँकड़े और उन्हें जोड़ने वाला वैज्ञानिक कारण। अन्य उत्तर साक्ष्य के बजाय सामान्य ज्ञान, आँकड़ों के बिना गलत कारण, या दावे और तर्क के बिना आँकड़े देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1860","question":"While teaching about plate movements, a teacher tells how Wegener's idea of drifting continents was largely rejected for decades and accepted only after new evidence from the ocean floor. The main purpose of telling this story is to show that:","options":["scientific knowledge can change with new evidence, and acceptance also depends on explaining how something works","scientists usually reject new ideas only out of jealousy, so new ideas should be trusted more than old ones","Wegener's idea was wrong when he proposed it and became right only later because the continents changed","history of science is useful mainly to make lessons interesting, and has little to do with understanding science"],"answer":0,"explanation":"Continental drift lacked a convincing mechanism until sea-floor spreading and plate tectonics supplied one. The story shows science as tentative and evidence-driven, without suggesting that new ideas are always right.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS TGT","questionHi":"प्लेट-संचलन पढ़ाते समय एक शिक्षिका बताती है कि वेगेनर का महाद्वीपों के खिसकने का विचार दशकों तक बड़ी हद तक अस्वीकार किया गया और केवल समुद्र-तल से नए साक्ष्य मिलने के बाद स्वीकार हुआ। यह कहानी बताने का मुख्य उद्देश्य यह दिखाना है कि:","optionsHi":["वैज्ञानिक ज्ञान नए साक्ष्य से बदल सकता है, और स्वीकृति इस पर भी निर्भर करती है कि कोई चीज़ कैसे काम करती है, यह समझाया जाए","वैज्ञानिक प्रायः नए विचारों को केवल ईर्ष्या के कारण अस्वीकार करते हैं, इसलिए नए विचारों पर पुराने से अधिक भरोसा करना चाहिए","वेगेनर का विचार तब गलत था जब उन्होंने प्रस्ताव रखा और बाद में केवल इसलिए सही हुआ कि महाद्वीप बदल गए","विज्ञान का इतिहास मुख्यतः पाठों को रोचक बनाने के लिए उपयोगी है, और विज्ञान को समझने से उसका बहुत कम संबंध है"],"explanationHi":"महाद्वीपीय विस्थापन में कोई विश्वसनीय क्रियाविधि नहीं थी जब तक समुद्र-तल प्रसरण और प्लेट विवर्तनिकी ने उसे नहीं दिया। कहानी विज्ञान को अस्थायी और साक्ष्य-चालित दिखाती है, बिना यह सुझाए कि नए विचार हमेशा सही होते हैं।"},
  {"id":"cdp-pedagogy-subjects-1861","question":"To find out what rusting needs, a Class 7 teacher sets up three tubes with iron nails: one in tap water, one in boiled water covered with a layer of oil, and one in dry air over a drying agent. What is the job of the oil layer?","options":["It keeps the boiled water warm, so that the nail in that tube stays hot through the whole test period","It stops air from dissolving back into the boiled water, so that nail meets water but no air","It coats the nail, showing that oil and grease protect iron objects from rusting","It makes the boiled water heavier so that the nail stays completely under the water"],"answer":1,"explanation":"Boiling drives out dissolved air, and the oil keeps air out afterwards, so that tube tests water without air; the dry tube tests air without water. Only the nail with both rusts. The oil is not meant to coat the nail.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"जंग लगने के लिए क्या चाहिए, यह जानने के लिए कक्षा 7 की एक शिक्षिका लोहे की कीलों वाली तीन नलियाँ लगाती है: एक नल के पानी में, एक उबले पानी में जिस पर तेल की परत है, और एक सुखाने वाले पदार्थ के ऊपर सूखी हवा में। तेल की परत का क्या कार्य है?","optionsHi":["यह उबले पानी को गर्म रखती है, ताकि उस नली की कील पूरी परीक्षण-अवधि में गर्म रहे","यह हवा को उबले पानी में फिर से घुलने से रोकती है, ताकि कील को पानी मिले पर हवा नहीं","यह कील पर परत चढ़ाती है, यह दिखाते हुए कि तेल और ग्रीस लोहे की वस्तुओं को जंग से बचाते हैं","यह उबले पानी को भारी बनाती है ताकि कील पूरी तरह पानी में डूबी रहे"],"explanationHi":"उबालने से घुली हवा निकल जाती है, और तेल बाद में हवा को बाहर रखता है, इसलिए वह नली हवा के बिना पानी की जाँच करती है; सूखी नली पानी के बिना हवा की जाँच करती है। केवल वही कील जंग खाती है जिसे दोनों मिलें। तेल का उद्देश्य कील पर परत चढ़ाना नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1862","question":"Germinating seeds kept in a thermos flask with a thermometer warm up over a day. A teacher sets up a second flask with boiled (dead) seeds. Why is the second flask needed?","options":["To show that boiled seeds germinate more slowly than raw seeds kept in exactly the same conditions","To provide a supply of warm seeds in case the first flask cools during the night","To give the class a second reading, so that the average of the two can be taken","To show that the rise in temperature comes from living seeds and not from the flask itself"],"answer":3,"explanation":"The control has everything the same except that the seeds are dead. If only the living seeds warm up, the heat must come from their respiration. Boiled seeds do not germinate at all.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"थर्मस फ़्लास्क में थर्मामीटर के साथ रखे अंकुरित होते बीज एक दिन में गर्म हो जाते हैं। शिक्षिका उबले (मृत) बीजों वाला दूसरा फ़्लास्क लगाती है। दूसरे फ़्लास्क की आवश्यकता क्यों है?","optionsHi":["यह दिखाने के लिए कि उबले बीज ठीक उसी स्थिति में रखे कच्चे बीजों से धीमे अंकुरित होते हैं","रात में पहला फ़्लास्क ठंडा हो जाए तो गर्म बीजों की आपूर्ति के लिए","कक्षा को दूसरा पाठ्यांक देने के लिए, ताकि दोनों का औसत लिया जा सके","यह दिखाने के लिए कि तापमान में वृद्धि जीवित बीजों से आती है, फ़्लास्क से स्वयं नहीं"],"explanationHi":"नियंत्रण में सब कुछ वैसा ही है सिवाय इसके कि बीज मृत हैं। यदि केवल जीवित बीज गर्म होते हैं, तो ऊष्मा उनके श्वसन से आई होगी। उबले बीज बिल्कुल अंकुरित नहीं होते।"},
  {"id":"cdp-pedagogy-subjects-1863","question":"In a lesson on materials, Class 8 students say that ‘chemical-free’ products are always safe and that anything with ‘chemicals’ is harmful. Which response is most accurate?","options":["Agree, since natural substances are safe in any amount, while man-made chemicals are always toxic to the body","Agree only partly, since some chemicals are safe in food but all of them are harmful in cosmetics","Avoid the point, because advertising and products are outside the scope of a science lesson","Show that everything, even water and salt, is made of chemicals, and harm depends on substance and dose"],"answer":3,"explanation":"All matter is chemical; whether something is harmful depends on what it is and how much of it is taken. ‘Chemical-free’ is a marketing phrase, and natural substances can also be toxic.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"पदार्थों के पाठ में कक्षा 8 के विद्यार्थी कहते हैं कि ‘रसायन-मुक्त’ उत्पाद हमेशा सुरक्षित होते हैं और ‘रसायनों’ वाली कोई भी चीज़ हानिकारक है। कौन-सी प्रतिक्रिया सबसे सटीक है?","optionsHi":["सहमत होना, क्योंकि प्राकृतिक पदार्थ किसी भी मात्रा में सुरक्षित हैं, जबकि मानव-निर्मित रसायन शरीर के लिए हमेशा विषैले हैं","आंशिक रूप से सहमत होना, क्योंकि कुछ रसायन भोजन में सुरक्षित हैं पर सभी सौंदर्य-प्रसाधन में हानिकारक हैं","बात से बचना, क्योंकि विज्ञापन और उत्पाद विज्ञान के पाठ के दायरे से बाहर हैं","दिखाना कि हर चीज़, पानी और नमक तक, रसायनों से बनी है, और हानि पदार्थ और मात्रा पर निर्भर है"],"explanationHi":"सारा पदार्थ रासायनिक है; कोई चीज़ हानिकारक है या नहीं यह इस पर निर्भर है कि वह क्या है और कितनी मात्रा में ली जाती है। ‘रसायन-मुक्त’ एक विपणन-वाक्यांश है, और प्राकृतिक पदार्थ भी विषैले हो सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-1864","question":"A teacher gives Class 8 students the question ‘How does the length of a pendulum affect its swing time?’ and a step-by-step procedure, but not the expected result. In Banchi and Bell's levels of inquiry, this is:","options":["confirmation inquiry, since the students follow a procedure to check a known result","structured inquiry, since the question and procedure are given but not the result","guided inquiry, since the teacher guides students by giving them the research question","open inquiry, since the students collect their own data and draw their own conclusion"],"answer":1,"explanation":"Confirmation gives the result too; structured gives question and procedure; guided gives only the question, with students designing the method; open leaves the question to students. Here the method is supplied, so it is structured.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"एक शिक्षिका कक्षा 8 के विद्यार्थियों को प्रश्न ‘लोलक की लंबाई उसके दोलन-काल को कैसे प्रभावित करती है?’ और चरण-दर-चरण विधि देती है, पर अपेक्षित परिणाम नहीं। बैंची और बेल के पूछताछ-स्तरों में यह है:","optionsHi":["पुष्टि-पूछताछ (confirmation inquiry), क्योंकि विद्यार्थी ज्ञात परिणाम की जाँच के लिए विधि का पालन करते हैं","संरचित पूछताछ (structured inquiry), क्योंकि प्रश्न और विधि दी गई है पर परिणाम नहीं","निर्देशित पूछताछ (guided inquiry), क्योंकि शिक्षिका शोध-प्रश्न देकर विद्यार्थियों का मार्गदर्शन करती है","खुली पूछताछ (open inquiry), क्योंकि विद्यार्थी अपने आँकड़े स्वयं जुटाते और अपना निष्कर्ष स्वयं निकालते हैं"],"explanationHi":"पुष्टि में परिणाम भी दिया जाता है; संरचित में प्रश्न और विधि; निर्देशित में केवल प्रश्न, विद्यार्थी विधि स्वयं बनाते हैं; खुली में प्रश्न भी विद्यार्थियों पर छोड़ा जाता है। यहाँ विधि दी गई है, इसलिए यह संरचित है।"},
  {"id":"cdp-pedagogy-subjects-1865","question":"To help Class 7 students see that digestion begins in the mouth, which activity is most suitable?","options":["Have students chew a piece of plain roti for a few minutes and notice that it begins to taste sweet","Show a labelled chart of the digestive system and trace the path of food from mouth to stomach","Ask students to memorise the names of the digestive juices and the organs that make each of them","Have students count how many times they chew each bite during lunch and record the count in a table"],"answer":0,"explanation":"Saliva begins breaking down starch into sugar, so roti chewed for long starts to taste sweet: direct evidence that digestion starts in the mouth. A chart or list only states the fact.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 के विद्यार्थियों को यह देखने में मदद करने के लिए कि पाचन मुँह में शुरू होता है, कौन-सी गतिविधि सबसे उपयुक्त है?","optionsHi":["विद्यार्थियों से सादी रोटी का एक टुकड़ा कुछ मिनट चबवाना और ध्यान देना कि वह मीठी लगने लगती है","पाचन-तंत्र का नामांकित चार्ट दिखाना और भोजन के मुँह से आमाशय तक के मार्ग का अनुसरण करना","विद्यार्थियों से पाचक रसों के नाम और हर एक को बनाने वाले अंग रटने को कहना","विद्यार्थियों से दोपहर के भोजन में हर कौर को कितनी बार चबाते हैं यह गिनवाना और सारणी में दर्ज करना"],"explanationHi":"लार स्टार्च को शर्करा में तोड़ना शुरू करती है, इसलिए देर तक चबाई रोटी मीठी लगने लगती है: यह प्रत्यक्ष साक्ष्य है कि पाचन मुँह में शुरू होता है। चार्ट या सूची केवल तथ्य बताते हैं।"},
  {"id":"cdp-pedagogy-subjects-1866","question":"Class 7 students say we ‘suck’ juice up a straw. The teacher fits a straw through a hole in an airtight bottle lid, sealing the gap, and students find they cannot drink. What should this lead them to?","options":["That the straw was too narrow, so the juice could not travel up it with enough speed","That sucking works only with open bottles, because closed bottles hold the juice inside them more tightly","That air pushing on the juice's surface drives it up when pressure inside the straw is lowered","That the bottle had too little juice in it, so the straw could not reach the liquid properly"],"answer":2,"explanation":"Drinking through a straw lowers the pressure inside the straw; atmospheric pressure on the liquid's surface pushes it up. Sealing the bottle removes that outside air push, so the drink does not rise.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 के विद्यार्थी कहते हैं कि हम स्ट्रॉ से रस ‘चूसकर’ ऊपर खींचते हैं। शिक्षिका एक वायुरोधी बोतल के ढक्कन के छेद में स्ट्रॉ लगाकर खाली जगह को बंद कर देती है, और विद्यार्थी पाते हैं कि वे पी नहीं सकते। यह उन्हें किस ओर ले जाना चाहिए?","optionsHi":["कि स्ट्रॉ बहुत पतली थी, इसलिए रस पर्याप्त गति से उसमें ऊपर नहीं जा सका","कि चूसना केवल खुली बोतलों के साथ काम करता है, क्योंकि बंद बोतलें रस को अपने अंदर अधिक कसकर रखती हैं","कि जब स्ट्रॉ के अंदर दाब घटता है तो रस की सतह पर पड़ने वाली हवा उसे ऊपर धकेलती है","कि बोतल में रस बहुत कम था, इसलिए स्ट्रॉ तरल तक ठीक से नहीं पहुँच सका"],"explanationHi":"स्ट्रॉ से पीना स्ट्रॉ के अंदर का दाब घटाता है; तरल की सतह पर वायुमंडलीय दाब उसे ऊपर धकेलता है। बोतल को बंद करने से बाहरी हवा का वह धक्का हट जाता है, इसलिए पेय ऊपर नहीं चढ़ता।"},
  {"id":"cdp-pedagogy-subjects-1867","question":"A Class 9 teacher shows a conceptual multiple-choice question, has students vote individually, then asks them to convince a neighbour and vote again. Correct answers rise from 40% to 75%. This technique is known as:","options":["the jigsaw method, since each student holds one part of the answer and must teach it to the others","peer instruction, in which discussion of a conceptual question between votes builds understanding","the think-aloud protocol, since students say aloud their thinking while answering the question","the Socratic method, since the teacher leads every student to the answer by careful questioning"],"answer":1,"explanation":"Eric Mazur's peer instruction uses conceptual questions, individual votes, peer discussion and revotes; students who have just understood often explain well to classmates. The teacher here does not lead each student by questions.","difficulty":"hard","source":"KVS TGT · NVS TGT","questionHi":"कक्षा 9 की एक शिक्षिका संकल्पनात्मक बहुविकल्पीय प्रश्न दिखाती है, विद्यार्थियों से व्यक्तिगत रूप से मत डलवाती है, फिर उनसे पड़ोसी को मनाने को कहती है और दोबारा मत डलवाती है। सही उत्तर 40% से बढ़कर 75% हो जाते हैं। यह तकनीक किस नाम से जानी जाती है?","optionsHi":["जिगसॉ विधि, क्योंकि हर विद्यार्थी के पास उत्तर का एक भाग है और उसे दूसरों को पढ़ाना है","सहपाठी निर्देशन (peer instruction), जिसमें मतों के बीच संकल्पनात्मक प्रश्न पर चर्चा समझ बनाती है","ज़ोर से सोचने की विधि (think-aloud protocol), क्योंकि विद्यार्थी प्रश्न का उत्तर देते समय अपनी सोच ज़ोर से बोलते हैं","सुकराती विधि, क्योंकि शिक्षिका सावधान प्रश्न-विधि से हर विद्यार्थी को उत्तर तक ले जाती है"],"explanationHi":"एरिक माज़ुर का सहपाठी निर्देशन संकल्पनात्मक प्रश्नों, व्यक्तिगत मतों, सहपाठी चर्चा और पुनः-मतदान का उपयोग करता है; जिन्होंने अभी-अभी समझा है वे प्रायः सहपाठियों को अच्छी तरह समझाते हैं। यहाँ शिक्षिका प्रश्नों से हर विद्यार्थी का नेतृत्व नहीं करती।"},
  {"id":"cdp-pedagogy-subjects-1868","question":"A Class 8 student classifies a mushroom as a plant ‘because it grows from the ground and doesn't move’. What is the best response?","options":["Compare it with a green plant on colour and how it gets food, then discuss why mushrooms are fungi","Agree for now, since mushrooms are simple plants and the details of fungi are taught only in higher classes","Tell her that mushrooms are animals because they cannot make their own food, unlike green plants","Ask her to learn the textbook list of fungi, so that she can recognise them in the examination"],"answer":0,"explanation":"Fungi lack chlorophyll and absorb food from dead matter, unlike plants; comparing features gives her reasons for the grouping. They are not animals either, and not moving is not a defining feature.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 की एक विद्यार्थी मशरूम को पौधा वर्गीकृत करती है ‘क्योंकि वह ज़मीन से उगता है और हिलता नहीं’। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["उसकी तुलना हरे पौधे से रंग और भोजन प्राप्त करने के ढंग पर करना, फिर चर्चा करना कि मशरूम कवक (fungi) क्यों हैं","फ़िलहाल सहमत होना, क्योंकि मशरूम सरल पौधे हैं और कवक के विवरण ऊँची कक्षाओं में पढ़ाए जाते हैं","उसे बताना कि मशरूम जंतु हैं क्योंकि वे हरे पौधों के विपरीत अपना भोजन स्वयं नहीं बना सकते","उससे पाठ्यपुस्तक की कवकों की सूची सीखने को कहना, ताकि वह परीक्षा में उन्हें पहचान सके"],"explanationHi":"कवकों में पर्णहरित नहीं होता और वे मृत पदार्थ से भोजन अवशोषित करते हैं, पौधों के विपरीत; विशेषताओं की तुलना उसे समूहन के कारण देती है। वे जंतु भी नहीं हैं, और न हिलना कोई परिभाषित विशेषता नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1869","question":"Many Class 7 students believe blood in veins is blue and turns red only when it meets air. Which evidence best challenges this?","options":["The veins on our wrists look blue through the skin, which shows that the blood inside them is blue","A diagram in which veins are coloured blue and arteries red, as in most textbooks","Blood drawn from a vein into a closed syringe is already dark red, before any air reaches it","Blood that flows from a small cut turns darker after a while as it is exposed to air"],"answer":2,"explanation":"Blood collected from a vein into a sealed tube is already dark red, so it is never blue; veins look bluish because of how skin absorbs and scatters light. Textbook colour codes add to the misconception.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 के बहुत-से विद्यार्थी मानते हैं कि शिराओं का रक्त नीला होता है और केवल हवा से मिलने पर लाल होता है। कौन-सा साक्ष्य इसे सबसे अच्छी तरह चुनौती देता है?","optionsHi":["हमारी कलाई की शिराएँ त्वचा के पार नीली दिखती हैं, जो दिखाता है कि उनके अंदर का रक्त नीला है","एक आरेख जिसमें शिराएँ नीली और धमनियाँ लाल रंगी हैं, जैसा अधिकांश पाठ्यपुस्तकों में होता है","शिरा से बंद सिरिंज में खींचा गया रक्त हवा के पहुँचने से पहले ही गहरा लाल होता है","छोटे कट से बहने वाला रक्त कुछ देर बाद हवा के संपर्क में आने से गहरा हो जाता है"],"explanationHi":"शिरा से बंद नली में एकत्र किया गया रक्त पहले से गहरा लाल होता है, इसलिए वह कभी नीला नहीं होता; शिराएँ इसलिए नीली दिखती हैं कि त्वचा प्रकाश को कैसे अवशोषित और प्रकीर्णित करती है। पाठ्यपुस्तकों के रंग-संकेत भ्रांति को बढ़ाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1870","question":"A Class 8 student says louder sounds travel faster than soft ones. Which everyday observation best challenges this?","options":["We hear a loud sound from farther away than a soft sound from the same place","Thunder is heard after we see the lightning, which shows that light travels much faster than sound","A loud shout makes the window glass shake, which a soft voice does not do","At a distance, the loud drums and soft flutes of a band reach us in step with each other"],"answer":3,"explanation":"If loudness affected speed, a distant band's loud and soft notes would arrive out of step; they do not. Hearing a loud sound farther away concerns energy, not speed, and thunder compares light with sound.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 की एक विद्यार्थी कहती है कि तेज़ ध्वनियाँ धीमी ध्वनियों से तेज़ चलती हैं। कौन-सा रोज़मर्रा का अवलोकन इसे सबसे अच्छी तरह चुनौती देता है?","optionsHi":["हम एक ही स्थान से धीमी ध्वनि की तुलना में तेज़ ध्वनि को अधिक दूर से सुनते हैं","बिजली चमकने के बाद बादल की गरज सुनाई देती है, जो दिखाता है कि प्रकाश ध्वनि से बहुत तेज़ चलता है","ज़ोर की चीख से खिड़की का काँच हिलता है, जो धीमी आवाज़ से नहीं होता","दूरी पर, बैंड के तेज़ ढोल और धीमी बाँसुरियाँ हमारे पास एक साथ, एक ही लय में पहुँचते हैं"],"explanationHi":"यदि तीव्रता गति को प्रभावित करती, तो दूर के बैंड के तेज़ और धीमे स्वर बेमेल पहुँचते; वे नहीं पहुँचते। तेज़ ध्वनि को अधिक दूर से सुनना ऊर्जा की बात है, गति की नहीं, और गरज प्रकाश की ध्वनि से तुलना है।"},
  {"id":"cdp-pedagogy-subjects-1871","question":"Class 8 students light an LED with a ‘potato battery’ of copper and zinc strips and say, ‘The potato has electricity inside it.’ How should the teacher refine this?","options":["The energy comes from a chemical reaction at the metal strips; the potato's juice lets charges move between them","Agree, since potatoes store electricity from the sunlight that the plant absorbed while it grew in the field","Say the LED glowed only because of static charge on the students' hands while they handled the strips","Agree, but add that potatoes store far less electricity than lemons, which is why lemon batteries are used more often"],"answer":0,"explanation":"The zinc reacts chemically, and the potato's juice acts as the electrolyte linking the two metals; replace the strips with two copper pieces and the cell fails. The potato is not a store of electricity.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2","questionHi":"कक्षा 8 के विद्यार्थी ताँबे और जस्ते की पट्टियों वाली ‘आलू बैटरी’ से एक LED जलाते हैं और कहते हैं, ‘आलू के अंदर बिजली है।’ शिक्षिका को इसे कैसे परिष्कृत करना चाहिए?","optionsHi":["ऊर्जा धातु की पट्टियों पर रासायनिक अभिक्रिया से आती है; आलू का रस आवेशों को उनके बीच चलने देता है","सहमत होना, क्योंकि आलू उस सूर्य-प्रकाश से बिजली संचित करते हैं जो पौधे ने खेत में उगते समय अवशोषित किया","कहना कि LED केवल इसलिए चमका क्योंकि पट्टियाँ संभालते समय विद्यार्थियों के हाथों पर स्थिर आवेश था","सहमत होना, पर जोड़ना कि आलू नींबू से बहुत कम बिजली संचित करते हैं, इसीलिए नींबू की बैटरियाँ अधिक उपयोग होती हैं"],"explanationHi":"जस्ता रासायनिक रूप से अभिक्रिया करता है, और आलू का रस दोनों धातुओं को जोड़ने वाले विद्युत-अपघट्य का काम करता है; पट्टियों की जगह दो ताँबे के टुकड़े रख दें तो सेल विफल हो जाता है। आलू बिजली का भंडार नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1872","question":"A Class 10 teacher places a compass under a wire and switches on a current; the needle swings, and swings the other way when the current is reversed. The best next question is:","options":["‘What is the name of the scientist who first discovered this effect, and when did he do so?’","‘How many times did the needle move during our whole demonstration today?’","‘Which colour of wire would make the needle move more strongly than this one?’","‘What does this tell us about what surrounds a wire carrying a current?’"],"answer":3,"explanation":"The deflection shows a magnetic field around the current-carrying wire whose direction depends on the current. Asking students to infer this extends the observation; names, counts or wire colour do not.","difficulty":"hard","source":"KVS TGT · NVS TGT","questionHi":"कक्षा 10 की एक शिक्षिका तार के नीचे कम्पास रखती है और धारा चालू करती है; सुई घूम जाती है, और धारा उलटने पर दूसरी ओर घूमती है। सबसे अच्छा अगला प्रश्न है:","optionsHi":["‘उस वैज्ञानिक का नाम क्या है जिसने सबसे पहले यह प्रभाव खोजा, और कब?’","‘आज हमारे पूरे प्रदर्शन के दौरान सुई कितनी बार हिली?’","‘किस रंग का तार इस तार से अधिक ज़ोर से सुई को हिलाएगा?’","‘यह हमें धारावाही तार के चारों ओर क्या है इसके बारे में क्या बताता है?’"],"explanationHi":"विक्षेप धारावाही तार के चारों ओर चुंबकीय क्षेत्र दिखाता है जिसकी दिशा धारा पर निर्भर करती है। विद्यार्थियों से यह अनुमान लगवाना अवलोकन को विस्तार देता है; नाम, गिनती या तार का रंग नहीं।"},
  {"id":"cdp-pedagogy-subjects-1873","question":"A Class 7 student writes, ‘In respiration our body produces energy from food.’ What is the most accurate refinement?","options":["Correct as written, since producing energy from food is exactly what respiration does in every cell","Energy is not produced; respiration releases energy stored in food so the body can use it","Respiration produces oxygen, which then gives the body the energy it needs to move","Energy is produced only during exercise, when respiration happens in the muscles"],"answer":1,"explanation":"Energy cannot be created; respiration breaks down food (glucose) with oxygen and releases stored chemical energy. Precise language here prepares students for the conservation of energy.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 का एक विद्यार्थी लिखता है, ‘श्वसन में हमारा शरीर भोजन से ऊर्जा उत्पन्न करता है।’ सबसे सटीक परिष्कार क्या है?","optionsHi":["जैसा लिखा है सही है, क्योंकि भोजन से ऊर्जा उत्पन्न करना ही हर कोशिका में श्वसन करता है","ऊर्जा उत्पन्न नहीं होती; श्वसन भोजन में संचित ऊर्जा को मुक्त करता है ताकि शरीर उसका उपयोग कर सके","श्वसन ऑक्सीजन उत्पन्न करता है, जो फिर शरीर को चलने के लिए आवश्यक ऊर्जा देती है","ऊर्जा केवल व्यायाम के दौरान उत्पन्न होती है, जब श्वसन मांसपेशियों में होता है"],"explanationHi":"ऊर्जा रची नहीं जा सकती; श्वसन भोजन (ग्लूकोज़) को ऑक्सीजन के साथ तोड़ता है और संचित रासायनिक ऊर्जा मुक्त करता है। यहाँ सटीक भाषा विद्यार्थियों को ऊर्जा संरक्षण के लिए तैयार करती है।"},
  {"id":"cdp-pedagogy-subjects-1874","question":"A Class 10 student asks why a bird sitting on a single live wire does not get a shock. Which explanation should the teacher guide students towards?","options":["Birds' feet are covered with a special insulating skin that stops any current from entering their bodies","The current in overhead wires is too weak to affect any animal, however large it is","Both feet are on one wire at almost the same potential, so very little current flows through the bird","Birds are too light for the current to flow through them down to the ground beneath"],"answer":2,"explanation":"Current flows only when there is a potential difference across a path; between two points close together on one wire, it is almost zero. Touching a second wire or an earthed pole would complete a path, which is why birds are killed that way.","difficulty":"hard","source":"KVS TGT · NVS TGT","questionHi":"कक्षा 10 की एक विद्यार्थी पूछती है कि एक अकेले जीवित तार पर बैठे पक्षी को झटका क्यों नहीं लगता। शिक्षिका को विद्यार्थियों को किस स्पष्टीकरण की ओर ले जाना चाहिए?","optionsHi":["पक्षियों के पैर एक विशेष विद्युतरोधी त्वचा से ढके होते हैं जो किसी भी धारा को उनके शरीर में आने से रोकती है","ऊपरी तारों में धारा इतनी कमज़ोर है कि वह किसी भी जानवर पर असर नहीं करती, चाहे वह कितना भी बड़ा हो","दोनों पैर एक ही तार पर लगभग समान विभव पर हैं, इसलिए पक्षी में से बहुत कम धारा बहती है","पक्षी इतने हल्के हैं कि धारा उनमें से होकर नीचे ज़मीन तक नहीं बह सकती"],"explanationHi":"धारा तभी बहती है जब किसी पथ के आर-पार विभवांतर हो; एक ही तार पर पास-पास के दो बिंदुओं के बीच यह लगभग शून्य होता है। दूसरे तार या भू-संपर्कित खंभे को छूना पथ पूरा कर देता है, इसीलिए पक्षी इस तरह मारे जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1875","question":"Class 9 students debate growing Bt cotton. Which of these questions can be answered mainly by scientific evidence?","options":["Should farmers be free to choose seeds even if seed companies earn large profits?","Does Bt cotton reduce bollworm damage in fields compared with non-Bt cotton?","Is it right for a few companies to own the patents on genetically changed seeds?","Should the government decide which crops farmers in a district may grow?"],"answer":1,"explanation":"Whether Bt cotton reduces bollworm damage is an empirical question that field data can test. The others are about values, fairness and policy, which evidence informs but cannot settle; separating the two is key in socio-scientific debates.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"कक्षा 9 के विद्यार्थी बीटी कपास (Bt cotton) उगाने पर बहस करते हैं। इनमें से कौन-से प्रश्न का उत्तर मुख्यतः वैज्ञानिक साक्ष्य से दिया जा सकता है?","optionsHi":["क्या बीज कंपनियों के बड़े लाभ कमाने पर भी किसानों को बीज चुनने की स्वतंत्रता होनी चाहिए?","क्या बीटी कपास गैर-बीटी कपास की तुलना में खेतों में सूँडी (bollworm) की क्षति घटाता है?","क्या आनुवंशिक रूप से परिवर्तित बीजों के पेटेंट का कुछ कंपनियों के स्वामित्व में होना उचित है?","क्या सरकार को तय करना चाहिए कि किसी ज़िले के किसान कौन-सी फ़सलें उगा सकते हैं?"],"explanationHi":"बीटी कपास सूँडी की क्षति घटाता है या नहीं, यह अनुभवजन्य प्रश्न है जिसे खेत के आँकड़े परख सकते हैं। अन्य मूल्यों, निष्पक्षता और नीति के बारे में हैं, जिन्हें साक्ष्य सूचित कर सकता है पर तय नहीं कर सकता; दोनों को अलग करना सामाजिक-वैज्ञानिक बहसों में मुख्य है।"},
  {"id":"cdp-pedagogy-subjects-1876","question":"Two Class 6 groups measure the same table with metre tapes and get 1.52 m and 1.53 m. One group insists the other must be wrong. What should the teacher help them understand?","options":["Every measurement has some uncertainty, so readings this close agree within what tapes can show","The group with the higher reading must be wrong, since cloth tapes tend to stretch and give larger values","Only the teacher's own reading can be trusted, so both groups should copy that value","They must keep measuring until both groups get exactly the same value to the millimetre"],"answer":0,"explanation":"Small differences come from reading the scale, placing the tape and judging ends; a difference of 1 cm here is within reasonable uncertainty. Understanding this is part of understanding how measurement works.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 के दो समूह मीटर-फ़ीतों से एक ही मेज़ को नापते हैं और 1.52 m तथा 1.53 m पाते हैं। एक समूह आग्रह करता है कि दूसरा गलत होगा। शिक्षिका को उन्हें क्या समझने में मदद करनी चाहिए?","optionsHi":["हर माप में कुछ अनिश्चितता होती है, इसलिए इतने निकट पाठ्यांक उस सीमा के भीतर सहमत हैं जो फ़ीते दिखा सकते हैं","अधिक पाठ्यांक वाला समूह गलत होगा, क्योंकि कपड़े के फ़ीते खिंचने और बड़े मान देने की प्रवृत्ति रखते हैं","केवल शिक्षिका के अपने पाठ्यांक पर भरोसा किया जा सकता है, इसलिए दोनों समूहों को वही मान उतारना चाहिए","उन्हें तब तक नापते रहना चाहिए जब तक दोनों समूह मिलीमीटर तक बिल्कुल वही मान न पाएँ"],"explanationHi":"छोटे अंतर पैमाना पढ़ने, फ़ीता रखने और सिरों का निर्णय करने से आते हैं; यहाँ 1 cm का अंतर उचित अनिश्चितता के भीतर है। इसे समझना यह समझने का हिस्सा है कि माप कैसे काम करता है।"},
  {"id":"cdp-pedagogy-subjects-1877","question":"A Class 8 student finds that tap water lights a bulb in a conduction tester and concludes, ‘Water is a good conductor of electricity.’ How should the teacher take this further?","options":["Agree, and add that this is why all water must be kept away from electrical appliances at home","Tell her that the tester was faulty, since water does not conduct electricity under any conditions","Ask her to repeat the test with the same tap water several times to make the result more reliable","Test distilled water too, and then distilled water with a pinch of salt, and discuss what changed"],"answer":3,"explanation":"Distilled water barely conducts; tap water conducts because of dissolved salts. Comparing the three refines her over-general conclusion, which repeating the same test cannot do.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 की एक विद्यार्थी पाती है कि नल का पानी चालकता-परीक्षक में बल्ब जलाता है और निष्कर्ष निकालती है, ‘पानी बिजली का अच्छा चालक है।’ शिक्षिका को इसे आगे कैसे ले जाना चाहिए?","optionsHi":["सहमत होना, और जोड़ना कि इसीलिए घर में सारा पानी विद्युत उपकरणों से दूर रखना चाहिए","उसे बताना कि परीक्षक दोषपूर्ण था, क्योंकि पानी किसी भी स्थिति में बिजली का चालन नहीं करता","उससे परिणाम को अधिक विश्वसनीय बनाने के लिए उसी नल के पानी से परीक्षण कई बार दोहराने को कहना","आसुत जल की भी जाँच करना, और फिर चुटकी भर नमक वाले आसुत जल की, और चर्चा करना कि क्या बदला"],"explanationHi":"आसुत जल मुश्किल से चालन करता है; नल का पानी घुले लवणों के कारण चालन करता है। तीनों की तुलना उसके अति-सामान्य निष्कर्ष को परिष्कृत करती है, जो वही परीक्षण दोहराने से नहीं हो सकता।"},
  {"id":"cdp-pedagogy-subjects-1878","question":"A Class 9 teacher displays ‘The Scientific Method: Observe → Hypothesise → Experiment → Conclude’ and tells students that all scientists follow these steps in this order. What is the main problem?","options":["The steps are in the wrong order, since experiments must always be done before any hypothesis is made","Scientists work in varied, often looping ways, and fields such as astronomy rarely run experiments","The poster leaves out the step of publishing results, which is the most important step of all","The poster is accurate, but such a detailed method is too difficult for students of Class 9"],"answer":1,"explanation":"There is no single fixed sequence; scientists move back and forth between ideas and evidence, and observational sciences test ideas without controlled experiments. Presenting one rigid method misrepresents the nature of science.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"कक्षा 9 की एक शिक्षिका ‘वैज्ञानिक विधि: अवलोकन → परिकल्पना → प्रयोग → निष्कर्ष’ प्रदर्शित करती है और विद्यार्थियों को बताती है कि सभी वैज्ञानिक इन चरणों का इसी क्रम में पालन करते हैं। मुख्य समस्या क्या है?","optionsHi":["चरण गलत क्रम में हैं, क्योंकि प्रयोग हमेशा किसी भी परिकल्पना से पहले किए जाने चाहिए","वैज्ञानिक विविध, प्रायः लूप जैसे तरीकों से काम करते हैं, और खगोल विज्ञान जैसे क्षेत्र शायद ही प्रयोग करते हैं","पोस्टर परिणाम प्रकाशित करने का चरण छोड़ देता है, जो सबसे महत्वपूर्ण चरण है","पोस्टर सही है, पर इतनी विस्तृत विधि कक्षा 9 के विद्यार्थियों के लिए बहुत कठिन है"],"explanationHi":"कोई एक निश्चित अनुक्रम नहीं है; वैज्ञानिक विचारों और साक्ष्य के बीच आगे-पीछे चलते हैं, और प्रेक्षणात्मक विज्ञान नियंत्रित प्रयोगों के बिना विचारों को परखते हैं। एक कठोर विधि प्रस्तुत करना विज्ञान की प्रकृति को गलत दिखाता है।"},
  {"id":"cdp-pedagogy-subjects-1879","question":"A teacher wants a Predict–Observe–Explain task that will most surprise Class 8 students and open a discussion on heat transfer. Which is best?","options":["Ice cubes in air and in water at the same room temperature: which melt faster?","Will ice placed in the sun melt faster than ice kept in the shade of a tree nearby?","Will hot tea cool faster in an open cup than in a covered steel tumbler?","Will a candle melt faster if it is lit than if it is left unlit on the table?"],"answer":0,"explanation":"Most students predict that ice melts faster in air, but water transfers heat to ice far better, so the cubes in water melt first. A good POE task targets a likely wrong prediction; the others have obvious answers.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षिका ऐसा पूर्वानुमान–अवलोकन–व्याख्या (Predict–Observe–Explain) कार्य चाहती है जो कक्षा 8 के विद्यार्थियों को सबसे अधिक चौंकाए और ऊष्मा-स्थानांतरण पर चर्चा खोले। कौन-सा सबसे अच्छा है?","optionsHi":["एक ही कमरे के तापमान पर हवा में और पानी में रखे बर्फ़ के टुकड़े: कौन-से तेज़ पिघलते हैं?","क्या धूप में रखी बर्फ़ पास के पेड़ की छाया में रखी बर्फ़ से तेज़ पिघलेगी?","क्या गर्म चाय खुले कप में ढके स्टील के गिलास से तेज़ ठंडी होगी?","क्या मोमबत्ती जलाने पर मेज़ पर बिना जलाए छोड़ने से तेज़ पिघलेगी?"],"explanationHi":"अधिकांश विद्यार्थी अनुमान लगाते हैं कि बर्फ़ हवा में तेज़ पिघलती है, पर पानी बर्फ़ को ऊष्मा कहीं बेहतर स्थानांतरित करता है, इसलिए पानी वाले टुकड़े पहले पिघलते हैं। अच्छा POE कार्य किसी संभावित गलत पूर्वानुमान को लक्षित करता है; अन्यों के उत्तर स्पष्ट हैं।"},
  {"id":"cdp-pedagogy-subjects-1880","question":"A Class 6 student argues that a tomato is a vegetable ‘because we cook it in sabzi, not eat it like a mango’. What is the best response?","options":["Tell her she is wrong, since tomatoes are fruits, and kitchen names have no value in any science discussion","Agree, since the way we use a food in the kitchen is how science decides whether it is a fruit","Explain that botanically a fruit grows from a flower and holds seeds, while in cooking ‘vegetable’ means use","Avoid the question, since such borderline cases are only a matter of opinion with no right answer"],"answer":2,"explanation":"Everyday and scientific classifications serve different purposes: botanically, a tomato is a fruit because it develops from the flower and contains seeds, while in cooking it is used as a vegetable. Both labels make sense in their own context.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक विद्यार्थी तर्क देती है कि टमाटर सब्ज़ी है ‘क्योंकि हम उसे सब्ज़ी में पकाते हैं, आम की तरह नहीं खाते’। सबसे अच्छी प्रतिक्रिया क्या है?","optionsHi":["उसे बताना कि वह गलत है, क्योंकि टमाटर फल हैं, और रसोई के नामों का किसी भी विज्ञान चर्चा में कोई मूल्य नहीं है","सहमत होना, क्योंकि रसोई में किसी खाद्य का उपयोग कैसे होता है, इसी से विज्ञान तय करता है कि वह फल है या नहीं","समझाना कि वनस्पति-विज्ञान में फल फूल से बनता है और बीज रखता है, जबकि पकाने में ‘सब्ज़ी’ का अर्थ उपयोग है","प्रश्न से बचना, क्योंकि ऐसे सीमांत मामले केवल राय की बात हैं जिनका कोई सही उत्तर नहीं है"],"explanationHi":"रोज़मर्रा और वैज्ञानिक वर्गीकरण अलग उद्देश्यों की पूर्ति करते हैं: वनस्पति-विज्ञान में टमाटर फल है क्योंकि वह फूल से विकसित होता है और बीज रखता है, जबकि पकाने में वह सब्ज़ी की तरह प्रयुक्त होता है। दोनों नाम अपने-अपने संदर्भ में सार्थक हैं।"},
  {"id":"cdp-pedagogy-subjects-1881","question":"Asked why the Revolt of 1857 happened, most Class 8 students write only, ‘Because of the greased cartridges.’ Which task best deepens their understanding of historical causation?","options":["Have them memorise a numbered list of the ten main causes of the revolt from the textbook for the coming unit test","Ask them to find out who made the cartridges and whether the rumour about the grease was true or false","Sort causes into long-term grievances (annexations, revenue, sepoys' terms) and the immediate trigger, then link them","Ask them to write a dramatic diary entry of a sepoy on the day he refused to use the new cartridges"],"answer":2,"explanation":"The cartridges were the trigger; the revolt grew from long-standing grievances such as annexation of Awadh, revenue demands and sepoys' conditions. Distinguishing and linking long-term causes and the spark builds causal reasoning; a memorised list does not.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"यह पूछे जाने पर कि 1857 का विद्रोह क्यों हुआ, कक्षा 8 के अधिकांश विद्यार्थी केवल लिखते हैं, ‘चर्बी लगे कारतूसों के कारण।’ कौन-सा कार्य ऐतिहासिक कार्य-कारण की उनकी समझ को सबसे अच्छी तरह गहरा करता है?","optionsHi":["उनसे आगामी इकाई-परीक्षा के लिए पाठ्यपुस्तक से विद्रोह के दस मुख्य कारणों की क्रमांकित सूची रटवाना","उनसे पता लगाने को कहना कि कारतूस किसने बनाए और चर्बी की अफ़वाह सच थी या झूठ","कारणों को दीर्घकालिक शिकायतों (विलय, राजस्व, सिपाहियों की सेवा-शर्तें) और तात्कालिक कारण में छाँटना, फिर उन्हें जोड़ना","उनसे नए कारतूस इस्तेमाल करने से इनकार करने के दिन एक सिपाही की नाटकीय डायरी-प्रविष्टि लिखने को कहना"],"explanationHi":"कारतूस तात्कालिक कारण थे; विद्रोह अवध के विलय, राजस्व की माँगों और सिपाहियों की स्थितियों जैसी लंबे समय की शिकायतों से उपजा। दीर्घकालिक कारणों और चिंगारी को अलग करना और जोड़ना कारणात्मक तर्क बनाता है; रटी हुई सूची नहीं।"},
  {"id":"cdp-pedagogy-subjects-1882","question":"Class 9 students cannot make sense of contour lines on a topographical sheet. Which activity best builds the idea?","options":["Make a clay hill, slice it at equal heights and trace each slice from above to see lines crowd on steep sides","Have them memorise the rule that closely spaced contours show steep slopes and widely spaced ones show gentle slopes","Have them copy the contour lines from the sheet into their notebooks using a different colour for each height","Show them photographs of hills and valleys and ask them to describe the landforms seen in each of the pictures"],"answer":0,"explanation":"Slicing a model at equal heights and viewing the outlines from above shows directly how a 3-D slope becomes 2-D lines, so the spacing rule makes sense. Memorising or copying gives the rule without the idea.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 9 के विद्यार्थी स्थलाकृतिक शीट पर समोच्च रेखाओं (contour lines) को नहीं समझ पाते। कौन-सी गतिविधि विचार को सबसे अच्छी तरह बनाती है?","optionsHi":["मिट्टी की पहाड़ी बनाना, उसे समान ऊँचाइयों पर काटना और हर कतरन को ऊपर से रेखांकित करना, देखने के लिए कि खड़ी ढलानों पर रेखाएँ पास-पास आ जाती हैं","उनसे यह नियम रटवाना कि पास-पास की समोच्च रेखाएँ तीव्र ढाल और दूर-दूर की मंद ढाल दिखाती हैं","उनसे शीट की समोच्च रेखाओं को हर ऊँचाई के लिए अलग रंग से अपनी कॉपी में उतारना","उन्हें पहाड़ियों और घाटियों की तस्वीरें दिखाना और हर तस्वीर में दिखने वाली भू-आकृतियों का वर्णन करने को कहना"],"explanationHi":"किसी मॉडल को समान ऊँचाइयों पर काटना और रूपरेखाओं को ऊपर से देखना सीधे दिखाता है कि 3-D ढलान 2-D रेखाओं में कैसे बदलती है, जिससे दूरी का नियम समझ में आता है। रटना या उतारना विचार के बिना नियम देता है।"},
  {"id":"cdp-pedagogy-subjects-1883","question":"Students in Itanagar and in Dwarka compare notes and find that the sun rises almost two hours earlier in Itanagar, though both use the same clock time. Which explanation should the teacher guide them to?","options":["Arunachal is closer to the sun than Gujarat, so the sunlight reaches it sooner every morning","Itanagar lies at a greater height above sea level, so the sun appears above the hills there much sooner","Clocks in Arunachal are set differently by custom, though the official time is the same","India spans about 30° of longitude, yet one standard time (82.5° E) is used across the country"],"answer":3,"explanation":"The earth turns 15° an hour, so places about 29° apart in longitude see sunrise about two hours apart, yet Indian Standard Time is the same everywhere. Distance from the sun has nothing to do with it.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2","questionHi":"ईटानगर और द्वारका के विद्यार्थी नोट्स मिलाते हैं और पाते हैं कि ईटानगर में सूर्योदय लगभग दो घंटे पहले होता है, जबकि दोनों एक ही घड़ी-समय का उपयोग करते हैं। शिक्षिका को उन्हें किस स्पष्टीकरण की ओर ले जाना चाहिए?","optionsHi":["अरुणाचल गुजरात से सूर्य के अधिक निकट है, इसलिए सूर्य-प्रकाश हर सुबह वहाँ पहले पहुँचता है","ईटानगर समुद्र-तल से अधिक ऊँचाई पर है, इसलिए वहाँ पहाड़ियों के ऊपर सूर्य बहुत पहले दिखता है","अरुणाचल में घड़ियाँ रिवाज़ से अलग ढंग से लगाई जाती हैं, यद्यपि आधिकारिक समय वही है","भारत लगभग 30° देशांतर में फैला है, फिर भी पूरे देश में एक मानक समय (82.5° E) प्रयुक्त होता है"],"explanationHi":"पृथ्वी प्रति घंटे 15° घूमती है, इसलिए देशांतर में लगभग 29° दूर स्थान लगभग दो घंटे के अंतर पर सूर्योदय देखते हैं, फिर भी भारतीय मानक समय हर जगह एक है। सूर्य से दूरी का इससे कोई संबंध नहीं।"},
  {"id":"cdp-pedagogy-subjects-1884","question":"A Class 8 student argues that groundwater can never run out ‘because water is a renewable resource’. Which response best addresses this?","options":["Agree, since the water cycle always returns all the water that is taken from the ground every year","It is renewable only while use does not exceed recharge; look at falling water-table data for the district","Tell him that groundwater is a non-renewable resource, just like coal and petroleum, and will soon be used up","Explain that rain refills wells within a few days, so heavy pumping makes no real difference over time"],"answer":1,"explanation":"Groundwater is renewed by recharge, but when pumping exceeds recharge the water table falls, as in many Indian districts. Calling it non-renewable is also inaccurate; the key idea is the rate of use versus renewal.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 का एक विद्यार्थी तर्क देता है कि भूजल कभी समाप्त नहीं हो सकता ‘क्योंकि पानी एक नवीकरणीय संसाधन है’। कौन-सी प्रतिक्रिया इसे सबसे अच्छी तरह संबोधित करती है?","optionsHi":["सहमत होना, क्योंकि जल-चक्र हर वर्ष ज़मीन से लिया गया सारा पानी लौटा देता है","वह तभी नवीकरणीय है जब उपयोग पुनर्भरण (recharge) से अधिक न हो; ज़िले के जल-स्तर के गिरने के आँकड़े देखना","उसे बताना कि भूजल कोयले और पेट्रोलियम की तरह अनवीकरणीय संसाधन है और जल्दी ही समाप्त हो जाएगा","समझाना कि वर्षा कुछ दिनों में कुओं को फिर भर देती है, इसलिए भारी पंपिंग से समय के साथ कोई वास्तविक अंतर नहीं पड़ता"],"explanationHi":"भूजल पुनर्भरण से नवीकृत होता है, पर जब पंपिंग पुनर्भरण से अधिक हो जाती है तो जल-स्तर गिरता है, जैसा भारत के अनेक ज़िलों में है। इसे अनवीकरणीय कहना भी गलत है; मुख्य विचार उपयोग की दर बनाम नवीकरण है।"},
  {"id":"cdp-pedagogy-subjects-1885","question":"In a Class 7 lesson on advertising, students analyse a soap advertisement. Which question best develops critical thinking about it?","options":["What feelings and values does the advertisement link to the soap, and whose lives does it show or leave out?","How many times does the brand name appear in the advertisement, and in which colour is it printed?","Which famous actor appears in the advertisement, and in how many films has the actor worked?","Is the soap shown in the advertisement better than the one used in your home, and why exactly do you think so?"],"answer":0,"explanation":"Advertisements sell through feelings and images of a ‘good life’; asking which values are attached and who is shown or left out lets students read ads critically. The other questions stay with surface details or personal preference.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 के विज्ञापन पर पाठ में विद्यार्थी साबुन के विज्ञापन का विश्लेषण करते हैं। कौन-सा प्रश्न उसके बारे में आलोचनात्मक चिंतन को सबसे अच्छी तरह विकसित करता है?","optionsHi":["विज्ञापन साबुन से कौन-सी भावनाओं और मूल्यों को जोड़ता है, और वह किनके जीवन दिखाता है या छोड़ देता है?","विज्ञापन में ब्रांड का नाम कितनी बार आता है, और वह किस रंग में छपा है?","विज्ञापन में कौन-सा प्रसिद्ध अभिनेता है, और उसने कितनी फ़िल्मों में काम किया है?","क्या विज्ञापन में दिखाया साबुन तुम्हारे घर में प्रयुक्त साबुन से बेहतर है, और तुम ऐसा ठीक-ठीक क्यों सोचते हो?"],"explanationHi":"विज्ञापन भावनाओं और ‘अच्छे जीवन’ की छवियों के माध्यम से बेचते हैं; यह पूछना कि कौन-से मूल्य जुड़े हैं और कौन दिखाया या छोड़ा गया है, विद्यार्थियों को विज्ञापनों को आलोचनात्मक ढंग से पढ़ने देता है। अन्य प्रश्न सतही विवरणों या व्यक्तिगत पसंद तक सीमित रहते हैं।"},
  {"id":"cdp-pedagogy-subjects-1886","question":"NCERT's Class 8 history book discusses James Mill's division of Indian history into ‘Hindu’, ‘Muslim’ and ‘British’ periods. Why does the book question this periodisation?","options":["Because Mill wrote his history in English rather than in an Indian language, so it is less authentic as a source","Because the dates Mill gave for the start and end of each period were later shown to be wrong","Because it treats the rulers' religion as the main marker of an era and paints British rule as civilising","Because the British period was too short, compared with the other two, to be called a separate period"],"answer":2,"explanation":"Mill's scheme reduces whole eras to the religion of rulers, ignores the diversity of life within them and presents British rule as bringing progress. The objection is to the logic of the division, not to dates or language.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"NCERT की कक्षा 8 की इतिहास की पुस्तक जेम्स मिल द्वारा भारतीय इतिहास को ‘हिंदू’, ‘मुस्लिम’ और ‘ब्रिटिश’ कालों में बाँटने की चर्चा करती है। पुस्तक इस कालविभाजन पर प्रश्न क्यों उठाती है?","optionsHi":["क्योंकि मिल ने अपना इतिहास किसी भारतीय भाषा के बजाय अंग्रेज़ी में लिखा, इसलिए वह स्रोत के रूप में कम प्रामाणिक है","क्योंकि मिल द्वारा दी गई हर काल की शुरुआत और अंत की तिथियाँ बाद में गलत सिद्ध हुईं","क्योंकि यह शासकों के धर्म को किसी युग का मुख्य चिह्न मानता है और ब्रिटिश शासन को सभ्य बनाने वाला दिखाता है","क्योंकि ब्रिटिश काल अन्य दो की तुलना में इतना छोटा था कि उसे अलग काल नहीं कहा जा सकता"],"explanationHi":"मिल की योजना पूरे युगों को शासकों के धर्म तक सीमित कर देती है, उनके भीतर जीवन की विविधता की अनदेखी करती है और ब्रिटिश शासन को प्रगति लाने वाला प्रस्तुत करती है। आपत्ति विभाजन के तर्क पर है, तिथियों या भाषा पर नहीं।"},
  {"id":"cdp-pedagogy-subjects-1887","question":"A Class 8 teacher uses a Premchand story about a peasant in debt to discuss rural life under colonial rule. Which caution should accompany its use as a source?","options":["Fiction has no value in history lessons, so the story should be read only in the Hindi period","The story should be treated as a full factual record, since Premchand lived through the same period himself","Only the dates and place names in the story should be used, since everything else is invented","It conveys how people experienced the period, but should be read alongside records such as revenue reports"],"answer":3,"explanation":"Literature written in a period reveals attitudes and lived experience, but it is shaped by the author's purpose and imagination, so it is best corroborated with other sources. Dismissing it or treating it as a record both misuse it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 का एक शिक्षक औपनिवेशिक शासन में ग्रामीण जीवन पर चर्चा के लिए कर्ज़ में डूबे एक किसान के बारे में प्रेमचंद की कहानी का उपयोग करता है। स्रोत के रूप में इसके उपयोग के साथ कौन-सी सावधानी होनी चाहिए?","optionsHi":["इतिहास के पाठों में कथा-साहित्य का कोई मूल्य नहीं है, इसलिए कहानी केवल हिंदी के पीरियड में पढ़ी जानी चाहिए","कहानी को पूर्ण तथ्यात्मक अभिलेख मानना चाहिए, क्योंकि प्रेमचंद स्वयं उसी काल में जिए थे","कहानी की केवल तिथियों और स्थान-नामों का उपयोग करना चाहिए, क्योंकि बाकी सब कल्पित है","यह बताती है कि लोगों ने उस काल का अनुभव कैसे किया, पर इसे राजस्व रिपोर्टों जैसे अभिलेखों के साथ पढ़ा जाना चाहिए"],"explanationHi":"किसी काल में लिखा साहित्य दृष्टिकोणों और जिए गए अनुभव को प्रकट करता है, पर वह लेखक के उद्देश्य और कल्पना से आकार पाता है, इसलिए उसे अन्य स्रोतों से पुष्ट करना सबसे अच्छा है। उसे खारिज करना या अभिलेख मानना, दोनों उसका दुरुपयोग हैं।"},
  {"id":"cdp-pedagogy-subjects-1888","question":"A teacher shows Class 9 a set of cases marked ‘Yes’ (countries where leaders are chosen in free elections and can be voted out) and ‘No’ (a monarchy, a military rule, a one-party state). Students compare them and work out the essential features of democracy. This follows:","options":["the advance organiser model, since the cases give students a framework before the lesson begins","the concept attainment model, where learners infer a concept's attributes from examples and non-examples","the jurisprudential inquiry model, since students judge whether the governments are fair or unfair","the mastery learning model, since no student may move on until every one of them can define democracy correctly"],"answer":1,"explanation":"Concept attainment (Bruner) presents labelled examples and non-examples so that learners infer the defining attributes themselves. An advance organiser is a framework given before new material.","difficulty":"very-hard","source":"KVS TGT · NVS TGT · DSSSB TGT","questionHi":"एक शिक्षिका कक्षा 9 को ‘हाँ’ (ऐसे देश जहाँ नेता स्वतंत्र चुनावों में चुने जाते हैं और हटाए जा सकते हैं) और ‘नहीं’ (एक राजतंत्र, एक सैन्य शासन, एक एकदलीय राज्य) चिह्नित मामलों का समूह दिखाती है। विद्यार्थी उनकी तुलना करते हैं और लोकतंत्र की आवश्यक विशेषताएँ निकालते हैं। यह किसका अनुसरण करता है?","optionsHi":["अग्र-आयोजक मॉडल (advance organiser model), क्योंकि मामले पाठ शुरू होने से पहले विद्यार्थियों को ढाँचा देते हैं","संकल्पना-प्राप्ति मॉडल (concept attainment model), जहाँ अधिगमकर्ता उदाहरणों और अनुदाहरणों से संकल्पना के गुण निकालते हैं","न्यायशास्त्रीय पूछताछ मॉडल, क्योंकि विद्यार्थी आँकते हैं कि सरकारें उचित हैं या अनुचित","पूर्णता अधिगम मॉडल, क्योंकि कोई विद्यार्थी तब तक आगे नहीं बढ़ सकता जब तक हर कोई लोकतंत्र को सही परिभाषित न कर ले"],"explanationHi":"संकल्पना-प्राप्ति (ब्रूनर) नामित उदाहरण और अनुदाहरण प्रस्तुत करता है ताकि अधिगमकर्ता परिभाषित गुण स्वयं निकालें। अग्र-आयोजक नई सामग्री से पहले दिया गया ढाँचा है।"},
  {"id":"cdp-pedagogy-subjects-1889","question":"Before a chapter on the Mughal administration, a teacher gives Class 7 a brief overview showing how ideas such as ‘ranks’, ‘revenue’ and ‘provinces’ connect, so that new details can be fitted into it. This is an example of:","options":["a concept map drawn by students after the chapter to show what they have learnt","an anticipation guide, in which students agree or disagree with given statements beforehand","an advance organiser, which gives a framework for linking new material to what is known","a K-W-L chart, in which students note what they know and want to learn before reading"],"answer":2,"explanation":"Ausubel's advance organiser is a short, general framework presented before new learning, so that details can be anchored meaningfully. A concept map drawn afterwards, an anticipation guide or a K-W-L chart serve other purposes.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT","questionHi":"मुग़ल प्रशासन के अध्याय से पहले एक शिक्षिका कक्षा 7 को संक्षिप्त अवलोकन देती है जो दिखाता है कि ‘मनसब’, ‘राजस्व’ और ‘सूबे’ जैसे विचार कैसे जुड़ते हैं, ताकि नए विवरण उसमें बैठाए जा सकें। यह उदाहरण है:","optionsHi":["विद्यार्थियों द्वारा अध्याय के बाद बनाए गए संकल्पना मानचित्र का, जो दिखाए कि उन्होंने क्या सीखा","अपेक्षा-मार्गदर्शिका (anticipation guide) का, जिसमें विद्यार्थी पहले से दिए कथनों से सहमत या असहमत होते हैं","अग्र-आयोजक (advance organiser) का, जो नई सामग्री को ज्ञात से जोड़ने का ढाँचा देता है","K-W-L चार्ट का, जिसमें विद्यार्थी पढ़ने से पहले नोट करते हैं कि वे क्या जानते हैं और क्या सीखना चाहते हैं"],"explanationHi":"ऑसुबेल का अग्र-आयोजक नए अधिगम से पहले दिया गया संक्षिप्त, सामान्य ढाँचा है, ताकि विवरण सार्थक ढंग से टिक सकें। बाद में बनाया संकल्पना मानचित्र, अपेक्षा-मार्गदर्शिका या K-W-L चार्ट अन्य उद्देश्यों की पूर्ति करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1890","question":"Class 7 students walk in a straight line from the village centre to the fields and river, noting land use, houses and vegetation every 100 metres, and then draw a cross-section. This activity is called a:","options":["transect walk, which shows how land use changes across an area","heritage walk, which records the historical buildings of a village","nature trail, which is meant mainly to identify plants and birds","traverse survey, which measures exact distances for a land record"],"answer":0,"explanation":"A transect walk records features at intervals along a line, revealing patterns such as how land use changes from the settlement to the fields and river. It is a standard geography fieldwork method.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 के विद्यार्थी गाँव के केंद्र से खेतों और नदी तक सीधी रेखा में चलते हैं, हर 100 मीटर पर भूमि-उपयोग, घर और वनस्पति नोट करते हैं, और फिर अनुप्रस्थ काट (cross-section) बनाते हैं। इस गतिविधि को कहते हैं:","optionsHi":["अनुप्रस्थ-चलन (transect walk), जो दिखाता है कि किसी क्षेत्र में भूमि-उपयोग कैसे बदलता है","विरासत-भ्रमण, जो गाँव की ऐतिहासिक इमारतें दर्ज करता है","प्रकृति-पथ, जो मुख्यतः पौधों और पक्षियों को पहचानने के लिए है","चल-सर्वेक्षण (traverse survey), जो भूमि-अभिलेख के लिए सटीक दूरियाँ मापता है"],"explanationHi":"अनुप्रस्थ-चलन एक रेखा के अनुदिश अंतरालों पर विशेषताएँ दर्ज करता है, जो बस्ती से खेतों और नदी तक भूमि-उपयोग के बदलाव जैसे पैटर्न प्रकट करता है। यह भूगोल का एक मानक क्षेत्र-कार्य तरीका है।"},
  {"id":"cdp-pedagogy-subjects-1891","question":"Most Class 9 students define ‘monsoon’ simply as ‘heavy rain in July and August’. Which idea should the teacher help them add?","options":["The monsoon is a cyclone that forms over the Bay of Bengal every year towards the end of June","The monsoon is rain that falls only on the western coast of India, brought there by the Western Ghats","The monsoon is the season when the earth comes closest to the sun and heats up the land","The monsoon is a seasonal reversal of winds, which brings rain in one season and dry air in another"],"answer":3,"explanation":"The word comes from the Arabic for ‘season’; the defining feature is the seasonal reversal of wind direction, which brings the wet south-west monsoon and the drier north-east winds. Rain is a result, not the definition.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2","questionHi":"कक्षा 9 के अधिकांश विद्यार्थी ‘मानसून’ को बस ‘जुलाई और अगस्त की भारी वर्षा’ के रूप में परिभाषित करते हैं। शिक्षिका को उन्हें कौन-सा विचार जोड़ने में मदद करनी चाहिए?","optionsHi":["मानसून एक चक्रवात है जो हर वर्ष जून के अंत की ओर बंगाल की खाड़ी में बनता है","मानसून वह वर्षा है जो केवल भारत के पश्चिमी तट पर गिरती है, जिसे वहाँ पश्चिमी घाट लाते हैं","मानसून वह ऋतु है जब पृथ्वी सूर्य के सबसे निकट आती है और भूमि को गर्म करती है","मानसून पवनों का मौसमी उलटाव है, जो एक ऋतु में वर्षा और दूसरी में शुष्क हवा लाता है"],"explanationHi":"यह शब्द ‘ऋतु’ के लिए अरबी शब्द से आया है; परिभाषित विशेषता पवन-दिशा का मौसमी उलटाव है, जो आर्द्र दक्षिण-पश्चिम मानसून और अधिक शुष्क उत्तर-पूर्वी पवनें लाता है। वर्षा एक परिणाम है, परिभाषा नहीं।"},
  {"id":"cdp-pedagogy-subjects-1892","question":"A Class 10 student says a ₹500 note has value ‘because the government keeps gold worth ₹500 for every note’. What should the teacher help the student understand?","options":["The student is right, since every note issued in India is backed by gold of exactly equal value","Modern currency is accepted because it is authorised by the government and trusted in exchange","Notes have value only because of the cost of the special paper, threads and ink used to print them","Notes have value only when they are deposited in a bank, which then pays out their worth"],"answer":1,"explanation":"Rupee notes are not exchangeable for gold; they are legal tender issued under government authority, and people accept them because they trust others will too. The cost of printing is far below a note's value.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2","questionHi":"कक्षा 10 की एक विद्यार्थी कहती है कि ₹500 के नोट का मूल्य है ‘क्योंकि सरकार हर नोट के लिए ₹500 मूल्य का सोना रखती है’। शिक्षिका को विद्यार्थी को क्या समझने में मदद करनी चाहिए?","optionsHi":["विद्यार्थी सही है, क्योंकि भारत में जारी हर नोट ठीक बराबर मूल्य के सोने से समर्थित है","आधुनिक मुद्रा इसलिए स्वीकार की जाती है कि वह सरकार द्वारा अधिकृत है और विनिमय में विश्वसनीय है","नोटों का मूल्य केवल इसलिए है कि उन्हें छापने में प्रयुक्त विशेष कागज़, धागों और स्याही की लागत है","नोटों का मूल्य तभी है जब उन्हें बैंक में जमा किया जाए, जो फिर उनका मूल्य चुकाता है"],"explanationHi":"रुपये के नोट सोने से बदले नहीं जा सकते; वे सरकारी अधिकार के तहत जारी वैध मुद्रा (legal tender) हैं, और लोग उन्हें इसलिए स्वीकार करते हैं कि उन्हें भरोसा है कि दूसरे भी करेंगे। छपाई की लागत नोट के मूल्य से बहुत कम है।"},
  {"id":"cdp-pedagogy-subjects-1893","question":"A Class 8 student says, ‘Only rich people pay taxes, so the poor don't pay for roads and schools.’ Which activity best challenges this?","options":["Have students look at shop bills from home for GST and discuss who pays such taxes when buying goods","Explain the difference between direct and indirect taxes and have students learn both definitions by heart","Ask students to find out the income-tax rates for different income groups from the internet","Tell students that everyone pays taxes, and ask them to write this point in their notebooks"],"answer":0,"explanation":"Indirect taxes such as GST are included in the price of goods everyone buys, so the poor also pay taxes. Finding GST on their own family's bills turns a definition into evidence.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 का एक विद्यार्थी कहता है, ‘कर केवल अमीर लोग देते हैं, इसलिए गरीब सड़कों और स्कूलों के लिए भुगतान नहीं करते।’ कौन-सी गतिविधि इसे सबसे अच्छी तरह चुनौती देती है?","optionsHi":["विद्यार्थियों से घर के दुकान-बिलों में GST देखने को कहना और चर्चा करना कि सामान खरीदते समय ऐसे कर कौन देता है","प्रत्यक्ष और अप्रत्यक्ष करों का अंतर समझाना और विद्यार्थियों से दोनों परिभाषाएँ कंठस्थ करवाना","विद्यार्थियों से इंटरनेट से विभिन्न आय-वर्गों के आयकर की दरें पता करने को कहना","विद्यार्थियों को बताना कि हर कोई कर देता है, और उनसे यह बात अपनी कॉपियों में लिखने को कहना"],"explanationHi":"GST जैसे अप्रत्यक्ष कर उन वस्तुओं के मूल्य में शामिल होते हैं जो सब खरीदते हैं, इसलिए गरीब भी कर देते हैं। अपने परिवार के बिलों पर GST ढूँढना परिभाषा को साक्ष्य में बदल देता है।"},
  {"id":"cdp-pedagogy-subjects-1894","question":"For a project on ‘The history of our school’, Class 6 students look at old admission registers and photographs and interview retired teachers. What is the main learning from this project?","options":["The exact founding date of the school, which is the main fact that local history projects aim to find","The names of past principals, so that students can show respect to those who served the school","How historians build an account from varied sources, and how memories and records may differ","How to make an attractive scrapbook, since presentation is the main skill in a history project"],"answer":2,"explanation":"Working with registers, photographs and interviews gives students first-hand experience of historical method: collecting, comparing and interpreting sources that may not agree.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"‘हमारे विद्यालय का इतिहास’ परियोजना के लिए कक्षा 6 के विद्यार्थी पुराने प्रवेश-रजिस्टर और तस्वीरें देखते हैं और सेवानिवृत्त शिक्षकों के साक्षात्कार लेते हैं। इस परियोजना का मुख्य अधिगम क्या है?","optionsHi":["विद्यालय की स्थापना की सटीक तिथि, जो स्थानीय इतिहास परियोजनाओं का मुख्य तथ्य होता है","पूर्व प्रधानाचार्यों के नाम, ताकि विद्यार्थी विद्यालय की सेवा करने वालों के प्रति सम्मान दिखा सकें","इतिहासकार विविध स्रोतों से विवरण कैसे बनाते हैं, और स्मृतियाँ तथा अभिलेख कैसे भिन्न हो सकते हैं","आकर्षक स्क्रैपबुक कैसे बनाएँ, क्योंकि इतिहास परियोजना में प्रस्तुति ही मुख्य कौशल है"],"explanationHi":"रजिस्टरों, तस्वीरों और साक्षात्कारों के साथ काम विद्यार्थियों को ऐतिहासिक विधि का प्रत्यक्ष अनुभव देता है: ऐसे स्रोतों को इकट्ठा करना, तुलना करना और व्याख्या करना जो सहमत न हों।"},
  {"id":"cdp-pedagogy-subjects-1895","question":"To teach disguised unemployment, a teacher describes a family of eight working on a small plot that four people could manage. Students say, ‘But they are all employed; they all work on the farm.’ Which question best moves them on?","options":["How many hours a day does each member of the family work on the farm in the busy season?","If four of them found other jobs, would the farm's output fall?","What crops does the family grow, and how much land would it need to grow more of them?","How much income does the family earn from selling the crops in the market every year?"],"answer":1,"explanation":"Disguised unemployment means more people are engaged than the work needs, so removing some does not reduce output. The question targets exactly that test; hours, crops or income do not.","difficulty":"hard","source":"KVS TGT · CTET Paper 2","questionHi":"प्रच्छन्न बेरोज़गारी पढ़ाने के लिए एक शिक्षिका आठ सदस्यों वाले परिवार का वर्णन करती है जो एक छोटे भूखंड पर काम करता है जिसे चार लोग सँभाल सकते हैं। विद्यार्थी कहते हैं, ‘पर वे सब नियोजित हैं; वे सब खेत पर काम करते हैं।’ कौन-सा प्रश्न उन्हें सबसे अच्छी तरह आगे बढ़ाता है?","optionsHi":["व्यस्त मौसम में परिवार का हर सदस्य खेत पर प्रतिदिन कितने घंटे काम करता है?","यदि उनमें से चार को अन्य काम मिल जाएँ, तो क्या खेत का उत्पादन घटेगा?","परिवार कौन-सी फ़सलें उगाता है, और उनमें से और उगाने के लिए कितनी भूमि चाहिए?","परिवार हर वर्ष बाज़ार में फ़सलें बेचकर कितनी आय अर्जित करता है?"],"explanationHi":"प्रच्छन्न बेरोज़गारी का अर्थ है कि काम की आवश्यकता से अधिक लोग लगे हैं, इसलिए कुछ को हटाने से उत्पादन नहीं घटता। प्रश्न ठीक उसी परीक्षण को लक्षित करता है; घंटे, फ़सलें या आय नहीं।"},
  {"id":"cdp-pedagogy-subjects-1896","question":"Class 9 students see that Mumbai receives far more rainfall than Pune, about 150 km away. Which approach best helps them explain the difference?","options":["Tell them that Pune is farther from the sea and so is drier, and have them note this point","Ask them to memorise the definition of a rain-shadow area with Pune as the main example","Have them compare the populations of the two cities to see whether rainfall depends on a city's size","Give a relief map with the Western Ghats and the monsoon winds' path, and have them reason it out"],"answer":3,"explanation":"Moist winds rise over the Western Ghats and drop most of their rain on the windward side (Mumbai), leaving the leeward side (Pune) in a rain shadow. Reasoning from relief and wind data builds understanding; distance from the sea alone does not explain it.","difficulty":"hard","source":"KVS TGT · CTET Paper 2","questionHi":"कक्षा 9 के विद्यार्थी देखते हैं कि लगभग 150 km दूर पुणे की तुलना में मुंबई में कहीं अधिक वर्षा होती है। कौन-सा उपागम उन्हें अंतर समझाने में सबसे अच्छी तरह मदद करता है?","optionsHi":["उन्हें बताना कि पुणे समुद्र से दूर है और इसलिए शुष्क है, और उनसे यह बिंदु नोट करवाना","उनसे पुणे को मुख्य उदाहरण मानकर वृष्टिछाया (rain-shadow) क्षेत्र की परिभाषा रटवाना","उनसे शहरों की जनसंख्याओं की तुलना करवाना ताकि देखें कि वर्षा शहर के आकार पर निर्भर करती है या नहीं","पश्चिमी घाट और मानसूनी पवनों के पथ वाला उच्चावच (relief) मानचित्र देना, और उनसे तर्क करके पता लगवाना"],"explanationHi":"आर्द्र पवनें पश्चिमी घाट के ऊपर उठती हैं और अपनी अधिकांश वर्षा पवनाभिमुख ओर (मुंबई) गिरा देती हैं, जिससे पवन-विमुख ओर (पुणे) वृष्टिछाया में रह जाती है। उच्चावच और पवन के आँकड़ों से तर्क करना समझ बनाता है; अकेले समुद्र से दूरी इसे नहीं समझाती।"},
  {"id":"cdp-pedagogy-subjects-1897","question":"Studying a medieval kingdom, a Class 7 student says, ‘Women did nothing important then, because the court chronicles hardly mention them.’ What should the teacher help her see?","options":["She is right, since the court chronicles recorded everything important that happened at the time","Women's lives in that period are simply unknowable, so the topic should not be studied","Silence in sources reflects who wrote them and for whom; other sources may show women's roles","Chronicles are unreliable in every respect and should never be used to study the period"],"answer":2,"explanation":"Court chroniclers wrote about rulers and battles for patrons; their silence says more about their purpose than about women's lives. Other evidence, such as inscriptions, grants, songs or paintings, can reveal women's roles.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"किसी मध्यकालीन राज्य का अध्ययन करते हुए कक्षा 7 की एक विद्यार्थी कहती है, ‘उस समय स्त्रियों ने कुछ महत्वपूर्ण नहीं किया, क्योंकि दरबारी इतिवृत्त उनका शायद ही उल्लेख करते हैं।’ शिक्षिका को उसे क्या देखने में मदद करनी चाहिए?","optionsHi":["वह सही है, क्योंकि दरबारी इतिवृत्तों ने उस समय की हर महत्वपूर्ण घटना दर्ज की","उस काल में स्त्रियों का जीवन अज्ञेय ही है, इसलिए विषय का अध्ययन नहीं होना चाहिए","स्रोतों में मौन इसे दर्शाता है कि उन्हें किसने और किसके लिए लिखा; अन्य स्रोत स्त्रियों की भूमिकाएँ दिखा सकते हैं","इतिवृत्त हर दृष्टि से अविश्वसनीय हैं और उस काल के अध्ययन के लिए कभी उपयोग नहीं होने चाहिए"],"explanationHi":"दरबारी इतिवृत्तकारों ने संरक्षकों के लिए शासकों और युद्धों के बारे में लिखा; उनका मौन स्त्रियों के जीवन से अधिक उनके उद्देश्य के बारे में बताता है। अन्य साक्ष्य, जैसे शिलालेख, अनुदान, गीत या चित्र, स्त्रियों की भूमिकाएँ प्रकट कर सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-1898","question":"In a Class 8 discussion, a student says only educated people should be allowed to vote. Which teacher response best develops understanding of universal adult franchise?","options":["Ask what the right to vote rests on, and what happened when voting was limited by property or education","Tell the student firmly that this view is undemocratic and must not be expressed again in the classroom","Agree that educated voters may choose better, but explain that the Constitution does not allow such a limit","Hold a vote in the class on the proposal and accept whatever result the majority produces"],"answer":0,"explanation":"Universal adult franchise rests on equal citizenship, not ability; examining history (restricted franchise under colonial rule) lets students see whose voices were excluded. Shutting the student down or putting rights to a class vote avoids the reasoning.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 की चर्चा में एक विद्यार्थी कहता है कि केवल शिक्षित लोगों को ही मतदान की अनुमति होनी चाहिए। शिक्षिका की कौन-सी प्रतिक्रिया सार्वभौमिक वयस्क मताधिकार की समझ को सबसे अच्छी तरह विकसित करती है?","optionsHi":["पूछना कि मतदान का अधिकार किस पर आधारित है, और जब मतदान संपत्ति या शिक्षा से सीमित था तब क्या हुआ","विद्यार्थी से दृढ़ता से कहना कि यह दृष्टिकोण अलोकतांत्रिक है और कक्षा में दोबारा व्यक्त नहीं किया जाना चाहिए","सहमत होना कि शिक्षित मतदाता बेहतर चुन सकते हैं, पर समझाना कि संविधान ऐसी सीमा की अनुमति नहीं देता","प्रस्ताव पर कक्षा में मतदान करवाना और बहुमत का जो भी परिणाम आए उसे स्वीकार करना"],"explanationHi":"सार्वभौमिक वयस्क मताधिकार समान नागरिकता पर आधारित है, योग्यता पर नहीं; इतिहास की जाँच (औपनिवेशिक शासन में सीमित मताधिकार) विद्यार्थियों को देखने देती है कि किनकी आवाज़ें बाहर रखी गईं। विद्यार्थी को चुप कराना या अधिकारों को कक्षा के मतदान पर रखना तर्क से बचना है।"},
  {"id":"cdp-pedagogy-subjects-1899","question":"NCERT social science books often open a topic with the story of one person, such as a farmer or a domestic worker. What is the main caution a teacher should take when using such a case?","options":["Cases should be avoided, since a story makes students emotional and distracts them from facts","The case should be read aloud only once, so that students do not remember the person's name","The teacher should treat the case as true for every person in India, so that it is easy to learn and remember","Students should test how far the case represents a wider pattern before drawing general conclusions"],"answer":3,"explanation":"A case makes abstract ideas concrete, but one life is not the whole picture; students should ask how typical it is and look at wider evidence before generalising.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"NCERT की सामाजिक विज्ञान पुस्तकें प्रायः किसी एक व्यक्ति, जैसे किसान या घरेलू कामगार, की कहानी से विषय शुरू करती हैं। ऐसे मामले का उपयोग करते समय शिक्षिका को मुख्य सावधानी क्या रखनी चाहिए?","optionsHi":["मामलों से बचना चाहिए, क्योंकि कहानी विद्यार्थियों को भावुक बनाती है और तथ्यों से ध्यान भटकाती है","मामला केवल एक बार ज़ोर से पढ़ना चाहिए, ताकि विद्यार्थी व्यक्ति का नाम याद न रखें","शिक्षिका को मामले को भारत के हर व्यक्ति के लिए सत्य मानना चाहिए, ताकि वह सीखने और याद रखने में आसान हो","सामान्य निष्कर्ष निकालने से पहले विद्यार्थियों को परखना चाहिए कि मामला किस हद तक व्यापक पैटर्न का प्रतिनिधित्व करता है"],"explanationHi":"मामला अमूर्त विचारों को मूर्त बनाता है, पर एक जीवन पूरी तस्वीर नहीं है; विद्यार्थियों को पूछना चाहिए कि वह कितना प्रतिनिधिक है और सामान्यीकरण से पहले व्यापक साक्ष्य देखना चाहिए।"},
  {"id":"cdp-pedagogy-subjects-1900","question":"To introduce how archaeologists date finds, a teacher buries objects in layers of different coloured sand in a glass box and lets students ‘excavate’ them. What principle does this mainly teach?","options":["That the deepest objects are always the most valuable, since they must have been buried with great care","That lower layers are usually older than the layers above them, unless they have been disturbed","That every object found in one layer must have been made in exactly the same year","That the colour of the soil in a layer tells archaeologists the exact age of the objects"],"answer":1,"explanation":"The principle of superposition says layers below are generally older, which gives relative dates; the ‘unless disturbed’ condition matters, as pits and burrows mix layers. Layers do not give exact years.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"पुरातत्वविद् खोजों की तिथि कैसे निर्धारित करते हैं, यह बताने के लिए एक शिक्षिका काँच के डिब्बे में अलग रंगों की रेत की परतों में वस्तुएँ दबाती है और विद्यार्थियों को उनका ‘उत्खनन’ करने देती है। यह मुख्यतः कौन-सा सिद्धांत सिखाता है?","optionsHi":["कि सबसे गहरी वस्तुएँ हमेशा सबसे मूल्यवान होती हैं, क्योंकि उन्हें बड़ी सावधानी से दबाया गया होगा","कि निचली परतें प्रायः ऊपर की परतों से पुरानी होती हैं, जब तक कि वे अस्त-व्यस्त न की गई हों","कि एक परत में मिली हर वस्तु ठीक एक ही वर्ष में बनी होगी","कि परत की मिट्टी का रंग पुरातत्वविदों को वस्तुओं की सटीक आयु बताता है"],"explanationHi":"अध्यारोपण (superposition) का सिद्धांत कहता है कि नीचे की परतें सामान्यतः पुरानी होती हैं, जो सापेक्ष तिथियाँ देता है; ‘जब तक अस्त-व्यस्त न हों’ की शर्त मायने रखती है, क्योंकि गड्ढे और बिल परतों को मिला देते हैं। परतें सटीक वर्ष नहीं देतीं।"},
  {"id":"cdp-pedagogy-subjects-1901","question":"Class 6 students examine pictures of coins of one ancient dynasty showing deities from several different traditions. Which conclusion is most reasonable?","options":["The rulers probably sought support from people of varied beliefs, though coins cannot show what all believed","All the people of that kingdom must have followed every one of the religions shown on the coins of their rulers","The rulers must have had no religion of their own, since they used images from many traditions","The coins were most likely made by foreign traders, since rulers would show only their own gods"],"answer":0,"explanation":"Coins tell us what rulers chose to show, suggesting they sought support from people of varied faiths or ruled a diverse area; they cannot reveal what each subject believed. The other options go beyond the evidence.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 के विद्यार्थी एक प्राचीन राजवंश के सिक्कों के चित्र देखते हैं जिन पर कई अलग परंपराओं के देवता दिखते हैं। कौन-सा निष्कर्ष सबसे उचित है?","optionsHi":["शासकों ने संभवतः विविध आस्थाओं वाले लोगों का समर्थन चाहा, यद्यपि सिक्के यह नहीं दिखा सकते कि सब क्या मानते थे","उस राज्य के सभी लोग अपने शासकों के सिक्कों पर दिखाए गए हर धर्म का पालन करते होंगे","शासकों का अपना कोई धर्म नहीं रहा होगा, क्योंकि उन्होंने अनेक परंपराओं की प्रतिमाओं का उपयोग किया","सिक्के संभवतः विदेशी व्यापारियों ने बनाए, क्योंकि शासक केवल अपने ही देवता दिखाते"],"explanationHi":"सिक्के यह बताते हैं कि शासकों ने क्या दिखाना चुना, जो सुझाता है कि उन्होंने विविध आस्थाओं के लोगों का समर्थन चाहा या विविध क्षेत्र पर शासन किया; वे यह नहीं बता सकते कि हर प्रजा क्या मानती थी। अन्य विकल्प साक्ष्य से आगे जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1902","question":"Before reading extracts from Ibn Battuta's account of 14th-century Delhi, what is the most important point for Class 7 students to keep in mind?","options":["His account is fully reliable, since a foreign visitor has no reason to favour any group in India over another","His account is worthless, since he did not know the local languages and stayed only briefly","As an outsider he noted what seemed strange to him, and he wrote much of it later, from memory","His account should be checked only against the textbook, which has already decided what happened"],"answer":2,"explanation":"Travellers' accounts are valuable because they record what locals took for granted, but they reflect the writer's background, purpose and audience. Reading them critically means neither accepting nor rejecting them wholesale.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"14वीं शताब्दी की दिल्ली के बारे में इब्न बतूता के वृत्तांत के अंश पढ़ने से पहले, कक्षा 7 के विद्यार्थियों को कौन-सी बात सबसे महत्वपूर्ण रूप से ध्यान में रखनी चाहिए?","optionsHi":["उसका वृत्तांत पूरी तरह विश्वसनीय है, क्योंकि विदेशी आगंतुक के पास भारत में किसी समूह का पक्ष लेने का कोई कारण नहीं है","उसका वृत्तांत व्यर्थ है, क्योंकि वह स्थानीय भाषाएँ नहीं जानता था और केवल थोड़े समय रुका","एक बाहरी व्यक्ति के रूप में उसने वह नोट किया जो उसे अजीब लगा, और उसने उसका बहुत कुछ बाद में, स्मृति से लिखा","उसके वृत्तांत की जाँच केवल पाठ्यपुस्तक से होनी चाहिए, जिसने पहले ही तय कर लिया है कि क्या हुआ"],"explanationHi":"यात्रियों के वृत्तांत इसलिए मूल्यवान हैं कि वे वह दर्ज करते हैं जिसे स्थानीय लोग सहज मानते हैं, पर वे लेखक की पृष्ठभूमि, उद्देश्य और श्रोता को प्रतिबिंबित करते हैं। उन्हें आलोचनात्मक ढंग से पढ़ने का अर्थ है उन्हें न पूरी तरह स्वीकारना न अस्वीकारना।"},
  {"id":"cdp-pedagogy-subjects-1903","question":"A Class 7 teacher asks students to find which items in their family's thali, such as chillies, potatoes and tomatoes, came to India from the Americas after 1500. The main purpose is to:","options":["prove that Indian food today is not really Indian, since many of its ingredients came from abroad","link history to students' daily lives and show how contact and trade change everyday culture","teach students the botanical names of vegetables and the regions in which each is grown today","prepare a list of foreign foods which students should avoid, since local foods are healthier"],"answer":1,"explanation":"Tracing familiar foods to their origins shows that culture is shaped by contact and exchange over time, and that history is present in daily life. It does not make the food ‘less Indian’.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 की एक शिक्षिका विद्यार्थियों से पता लगाने को कहती है कि उनके परिवार की थाली की कौन-सी वस्तुएँ, जैसे मिर्च, आलू और टमाटर, 1500 के बाद अमेरिका महाद्वीपों से भारत आईं। मुख्य उद्देश्य है:","optionsHi":["यह सिद्ध करना कि आज का भारतीय भोजन वास्तव में भारतीय नहीं है, क्योंकि उसकी अनेक सामग्रियाँ विदेश से आईं","इतिहास को विद्यार्थियों के दैनिक जीवन से जोड़ना और दिखाना कि संपर्क और व्यापार रोज़मर्रा की संस्कृति को कैसे बदलते हैं","विद्यार्थियों को सब्ज़ियों के वानस्पतिक नाम और वे क्षेत्र सिखाना जहाँ आज हर एक उगाई जाती है","विदेशी खाद्य पदार्थों की ऐसी सूची तैयार करना जिनसे विद्यार्थियों को बचना चाहिए, क्योंकि स्थानीय खाद्य अधिक स्वास्थ्यकर हैं"],"explanationHi":"परिचित खाद्य पदार्थों को उनके मूल तक खोजना दिखाता है कि संस्कृति समय के साथ संपर्क और आदान-प्रदान से आकार पाती है, और इतिहास दैनिक जीवन में मौजूद है। इससे भोजन ‘कम भारतीय’ नहीं हो जाता।"},
  {"id":"cdp-pedagogy-subjects-1904","question":"In a Class 9 lesson, five students discuss a question in an inner circle while the rest sit around them, noting how arguments are built and giving feedback afterwards; roles then rotate. This structure is called a:","options":["jigsaw, in which each group becomes expert on one part","think-pair-share, in which pairs talk before sharing","panel discussion, in which experts answer questions","fishbowl discussion, with an inner and outer circle"],"answer":3,"explanation":"In a fishbowl, an inner group discusses while an outer group observes the discussion process and later reflects on it, which builds both content understanding and discussion skills.","difficulty":"moderate","source":"KVS TGT · CTET Paper 2","questionHi":"कक्षा 9 के पाठ में पाँच विद्यार्थी अंदर के घेरे में किसी प्रश्न पर चर्चा करते हैं जबकि बाकी उनके चारों ओर बैठकर नोट करते हैं कि तर्क कैसे बनाए जाते हैं और बाद में प्रतिपुष्टि देते हैं; फिर भूमिकाएँ बदलती हैं। इस संरचना को कहते हैं:","optionsHi":["जिगसॉ, जिसमें हर समूह एक भाग का विशेषज्ञ बनता है","सोचो-जोड़ी बनाओ-साझा करो (think-pair-share), जिसमें जोड़ियाँ साझा करने से पहले बात करती हैं","पैनल चर्चा, जिसमें विशेषज्ञ प्रश्नों के उत्तर देते हैं","मछलीघर चर्चा (fishbowl discussion), जिसमें भीतरी और बाहरी घेरा होता है"],"explanationHi":"फ़िशबोल में भीतरी समूह चर्चा करता है जबकि बाहरी समूह चर्चा की प्रक्रिया का अवलोकन करता है और बाद में उस पर चिंतन करता है, जो विषय-वस्तु की समझ और चर्चा के कौशल दोनों बनाता है।"},
  {"id":"cdp-pedagogy-subjects-1905","question":"A Class 10 teacher runs a barter game in which each student must trade a card for what she needs without using money, and many fail to complete a trade. What concept does the game mainly bring out?","options":["That barter was never really used in any society, since it is impossible in practice","That traders in a barter system cheat more often than traders who use money","The double coincidence of wants, which money removes as a medium of exchange","That the value of goods in a barter system is always fixed by the government"],"answer":2,"explanation":"In barter both people must want what the other has; when that rarely happens, trades fail. Money solves this by acting as an accepted medium of exchange, which the game lets students feel directly.","difficulty":"hard","source":"KVS TGT · CTET Paper 2","questionHi":"कक्षा 10 की एक शिक्षिका वस्तु-विनिमय (barter) का खेल कराती है जिसमें हर विद्यार्थी को बिना पैसे के अपनी ज़रूरत की चीज़ के लिए एक कार्ड का सौदा करना है, और बहुत-से सौदा पूरा नहीं कर पाते। खेल मुख्यतः कौन-सी संकल्पना सामने लाता है?","optionsHi":["कि वस्तु-विनिमय किसी भी समाज में कभी वास्तव में उपयोग नहीं हुआ, क्योंकि वह व्यवहार में असंभव है","कि वस्तु-विनिमय प्रणाली में व्यापारी मुद्रा का उपयोग करने वाले व्यापारियों से अधिक धोखा देते हैं","आवश्यकताओं का दोहरा संयोग (double coincidence of wants), जिसे मुद्रा विनिमय के माध्यम के रूप में हटा देती है","कि वस्तु-विनिमय प्रणाली में वस्तुओं का मूल्य हमेशा सरकार तय करती है"],"explanationHi":"वस्तु-विनिमय में दोनों लोगों को वह चाहिए जो दूसरे के पास है; जब यह बहुत कम होता है, तो सौदे विफल होते हैं। मुद्रा इसे विनिमय के स्वीकृत माध्यम के रूप में हल करती है, जिसे खेल विद्यार्थियों को सीधे महसूस करने देता है।"},
  {"id":"cdp-pedagogy-subjects-1906","question":"Looking at a map of India, several Class 6 students say rivers always flow ‘from the top of the map to the bottom’. Which evidence best challenges this?","options":["The Narmada and Tapi flow west to the Arabian Sea: rivers follow the land's slope, not map direction","The Ganga flows from the Himalayas towards the south-east, which proves that all rivers flow south","Rivers in the southern hemisphere flow northward, which shows that a river's direction depends on its hemisphere","Rivers on maps are drawn only roughly, so their direction on a map cannot really be trusted at all"],"answer":0,"explanation":"Rivers flow downhill from higher to lower land in whatever compass direction that takes them; the westward Narmada and Tapi show this. ‘Top of the map’ is north, not uphill.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"भारत का मानचित्र देखते हुए कक्षा 6 के कई विद्यार्थी कहते हैं कि नदियाँ हमेशा ‘मानचित्र के ऊपर से नीचे’ बहती हैं। कौन-सा साक्ष्य इसे सबसे अच्छी तरह चुनौती देता है?","optionsHi":["नर्मदा और ताप्ती अरब सागर की ओर पश्चिम में बहती हैं: नदियाँ भूमि की ढाल का अनुसरण करती हैं, मानचित्र की दिशा का नहीं","गंगा हिमालय से दक्षिण-पूर्व की ओर बहती है, जो सिद्ध करता है कि सभी नदियाँ दक्षिण में बहती हैं","दक्षिणी गोलार्ध की नदियाँ उत्तर की ओर बहती हैं, जो दिखाता है कि नदी की दिशा उसके गोलार्ध पर निर्भर करती है","मानचित्रों पर नदियाँ केवल मोटे तौर पर बनाई जाती हैं, इसलिए मानचित्र पर उनकी दिशा पर बिल्कुल भरोसा नहीं किया जा सकता"],"explanationHi":"नदियाँ ऊँची से नीची भूमि की ओर बहती हैं, चाहे वह जिस दिशा में ले जाए; पश्चिम की ओर बहती नर्मदा और ताप्ती यह दिखाती हैं। ‘मानचित्र का ऊपर’ उत्तर है, ऊँचाई नहीं।"},
  {"id":"cdp-pedagogy-subjects-1907","question":"Class 10 students study why sugar mills are usually located close to sugarcane fields. Which explanation should the teacher guide them towards?","options":["Sugar mills need very little electricity, so they can be built anywhere in a rural area of the country","Sugarcane is bulky and loses sugar after cutting, so it must be crushed soon, near the fields","Sugar is consumed mainly in villages, so mills are placed close to the people who buy the sugar","The government requires every sugar mill to be built inside the village where the cane is grown"],"answer":1,"explanation":"A heavy, perishable raw material that loses weight in processing pulls industry towards its source; sugarcane loses sucrose if haulage is delayed. Reasoning from the nature of the raw material is the key idea.","difficulty":"hard","source":"KVS TGT · CTET Paper 2","questionHi":"कक्षा 10 के विद्यार्थी अध्ययन करते हैं कि चीनी मिलें प्रायः गन्ने के खेतों के निकट क्यों स्थित होती हैं। शिक्षिका को उन्हें किस स्पष्टीकरण की ओर ले जाना चाहिए?","optionsHi":["चीनी मिलों को बहुत कम बिजली चाहिए, इसलिए उन्हें देश के किसी भी ग्रामीण क्षेत्र में बनाया जा सकता है","गन्ना भारी होता है और कटने के बाद शर्करा खोने लगता है, इसलिए उसे खेतों के पास जल्दी पेरना होता है","चीनी मुख्यतः गाँवों में खपत होती है, इसलिए मिलें चीनी खरीदने वालों के निकट लगाई जाती हैं","सरकार हर चीनी मिल को उस गाँव में बनाने की अनिवार्यता रखती है जहाँ गन्ना उगाया जाता है"],"explanationHi":"भारी, शीघ्र नाशवान कच्चा माल जो प्रसंस्करण में भार खोता है, उद्योग को अपने स्रोत की ओर खींचता है; ढुलाई में देरी होने पर गन्ना सुक्रोज़ खो देता है। कच्चे माल की प्रकृति से तर्क करना मुख्य विचार है।"},
  {"id":"cdp-pedagogy-subjects-1908","question":"Before a unit on the Constitution, a teacher has Class 8 play a game with no agreed rules; arguments break out and the strongest players take over. Students then frame rules together. The main purpose is to help students see that:","options":["games without any rules are more fun, so societies should have as few laws as they possibly can","the teacher's authority is needed to settle every dispute that arises in the class","agreed rules limit the power of the strong and give everyone a fair basis to take part","the students who argued most during the game should not be chosen to frame the rules"],"answer":2,"explanation":"The breakdown shows why a society needs agreed rules that bind everyone, protect the weaker and limit power, which is what a constitution does. The point is not reliance on the teacher.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"संविधान पर एक इकाई से पहले एक शिक्षिका कक्षा 8 से बिना तय नियमों वाला खेल खिलवाती है; बहस छिड़ जाती है और सबसे ताकतवर खिलाड़ी कब्ज़ा कर लेते हैं। फिर विद्यार्थी मिलकर नियम बनाते हैं। मुख्य उद्देश्य विद्यार्थियों को यह देखने में मदद करना है कि:","optionsHi":["बिना किसी नियम के खेल अधिक मज़ेदार होते हैं, इसलिए समाजों में जितने कम कानून हों उतना अच्छा","कक्षा में उठने वाले हर विवाद को सुलझाने के लिए शिक्षक का अधिकार आवश्यक है","तय नियम ताकतवर की शक्ति सीमित करते हैं और सबको भाग लेने का निष्पक्ष आधार देते हैं","खेल के दौरान सबसे अधिक बहस करने वाले विद्यार्थियों को नियम बनाने के लिए नहीं चुना जाना चाहिए"],"explanationHi":"बिखराव दिखाता है कि समाज को ऐसे तय नियम क्यों चाहिए जो सबको बाँधें, कमज़ोर की रक्षा करें और शक्ति को सीमित करें, जो संविधान करता है। मुद्दा शिक्षक पर निर्भरता नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1909","question":"A Class 9 student says a map with a scale of 1:1,000,000 is a ‘large-scale map’ because the number is bigger than in 1:50,000. What is the correct idea?","options":["She is right, since the larger the second number of a scale, the larger the scale of the map","Both maps have the same scale, since each represents real distances on a reduced sheet","Scale cannot be compared unless both maps are drawn on sheets of exactly the same size","1:50,000 is the larger scale; it shows a smaller area in more detail than 1:1,000,000"],"answer":3,"explanation":"1/50,000 is a larger fraction than 1/1,000,000, so 1:50,000 is the larger scale, used for detailed maps of small areas. Students often judge by the size of the second number, which reverses the idea.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2","questionHi":"कक्षा 9 की एक विद्यार्थी कहती है कि 1:1,000,000 पैमाने वाला मानचित्र ‘बड़े पैमाने का मानचित्र’ है क्योंकि 1:50,000 की तुलना में संख्या बड़ी है। सही विचार क्या है?","optionsHi":["वह सही है, क्योंकि पैमाने की दूसरी संख्या जितनी बड़ी हो, मानचित्र का पैमाना उतना ही बड़ा होता है","दोनों मानचित्रों का पैमाना समान है, क्योंकि हर एक छोटे किए गए पन्ने पर वास्तविक दूरियाँ दर्शाता है","पैमानों की तुलना तभी की जा सकती है जब दोनों मानचित्र बिल्कुल एक ही आकार के पन्नों पर बने हों","1:50,000 बड़ा पैमाना है; यह 1:1,000,000 की तुलना में छोटा क्षेत्र अधिक विस्तार से दिखाता है"],"explanationHi":"1/50,000, 1/1,000,000 से बड़ा भिन्न है, इसलिए 1:50,000 बड़ा पैमाना है, जो छोटे क्षेत्रों के विस्तृत मानचित्रों के लिए प्रयुक्त होता है। विद्यार्थी प्रायः दूसरी संख्या के आकार से आँकते हैं, जो विचार को उलट देता है।"},
  {"id":"cdp-pedagogy-subjects-1910","question":"For a geography project on urban housing, Class 9 students plan to photograph people in a nearby basti and post the pictures online. What should the teacher insist on first?","options":["Asking people's consent, respecting refusals and avoiding images that show them as objects of pity","Choosing the most striking photographs, since vivid images make the project more convincing","Taking the photographs quickly and quietly, so that people do not change how they behave","Posting the photographs only after removing the school's name, so that the school cannot be blamed later"],"answer":0,"explanation":"Fieldwork involving people requires consent and respect for their dignity; images taken without permission or chosen for shock value exploit the people being studied.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT","questionHi":"शहरी आवास पर भूगोल परियोजना के लिए कक्षा 9 के विद्यार्थी पास की बस्ती में लोगों की तस्वीरें खींचने और उन्हें ऑनलाइन डालने की योजना बनाते हैं। शिक्षिका को सबसे पहले किस पर ज़ोर देना चाहिए?","optionsHi":["लोगों की सहमति लेना, इनकार का सम्मान करना और ऐसी छवियों से बचना जो उन्हें दया की वस्तु के रूप में दिखाएँ","सबसे प्रभावशाली तस्वीरें चुनना, क्योंकि सजीव छवियाँ परियोजना को अधिक विश्वसनीय बनाती हैं","तस्वीरें जल्दी और चुपचाप लेना, ताकि लोग अपना व्यवहार न बदलें","तस्वीरें विद्यालय का नाम हटाने के बाद ही डालना, ताकि विद्यालय को बाद में दोषी न ठहराया जा सके"],"explanationHi":"लोगों से जुड़े क्षेत्र-कार्य के लिए सहमति और उनकी गरिमा के सम्मान की आवश्यकता होती है; बिना अनुमति ली गई या सनसनी के लिए चुनी गई छवियाँ अध्ययन किए जा रहे लोगों का शोषण करती हैं।"},
  {"id":"cdp-pedagogy-subjects-1911","question":"Many Class 7 students say ‘ship’ and ‘sheep’, and ‘live’ and ‘leave’, the same way, which causes confusion in speech. Which activity most directly targets this?","options":["Have them read the lesson aloud daily, with the teacher correcting each word they say wrongly as they go along","Teach the phonetic symbols for every English vowel and have students transcribe whole passages with them","Have them copy lists of words containing ‘ee’ and ‘i’ and learn the spelling rules for each of the two vowels","Minimal-pair games: they hear a word and point to the right picture, then say pairs for a partner to identify"],"answer":3,"explanation":"Students first need to hear the long/short vowel contrast before they can produce it; minimal-pair listening and speaking games focus on exactly that, in meaningful pairs. Spelling rules and full transcription do not train the ear.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 के बहुत-से विद्यार्थी ‘ship’ और ‘sheep’, तथा ‘live’ और ‘leave’ को एक ही तरह बोलते हैं, जिससे बोलचाल में भ्रम होता है। कौन-सी गतिविधि इसे सबसे सीधे लक्षित करती है?","optionsHi":["उनसे रोज़ पाठ ज़ोर से पढ़वाना, और जो शब्द वे गलत बोलें उसे शिक्षिका के साथ-साथ सुधारते जाना","अंग्रेज़ी के हर स्वर के ध्वन्यात्मक प्रतीक सिखाना और विद्यार्थियों से पूरे गद्यांश उनमें लिप्यंतरित करवाना","उनसे ‘ee’ और ‘i’ वाले शब्दों की सूचियाँ उतरवाना और दोनों स्वरों के लिए वर्तनी-नियम सीखवाना","लघुतम-युग्म (minimal-pair) खेल: वे शब्द सुनकर सही चित्र की ओर इशारा करते हैं, फिर साथी के पहचानने के लिए युग्म बोलते हैं"],"explanationHi":"विद्यार्थियों को पहले दीर्घ/ह्रस्व स्वर के अंतर को सुनना होगा, तभी वे उसे बोल सकते हैं; लघुतम-युग्म सुनने और बोलने के खेल ठीक उसी पर सार्थक युग्मों में केंद्रित होते हैं। वर्तनी-नियम और पूर्ण लिप्यंतरण कान को प्रशिक्षित नहीं करते।"},
  {"id":"cdp-pedagogy-subjects-1912","question":"Class 9 students keep writing ‘do a mistake’ and ‘make homework’. The teacher gives them printed lines from real texts, each showing ‘make’ or ‘do’ with the words around it, and asks them to find patterns. This approach:","options":["lets learners discover collocations from real usage, so the patterns stick better than a rule","is too advanced for school, since only trained linguists can learn anything useful from such lines","replaces vocabulary teaching, so the teacher need never explain any word meaning again","mainly practises reading speed, since the lines are short and can be read very quickly"],"answer":0,"explanation":"Concordance lines show how words actually combine (make a mistake, do homework), and discovering these patterns is data-driven learning. Collocations are largely conventional, so seeing many real examples works better than a rule.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"कक्षा 9 के विद्यार्थी बार-बार ‘do a mistake’ और ‘make homework’ लिखते हैं। शिक्षिका उन्हें वास्तविक पाठों से छपी पंक्तियाँ देती है, जिनमें से हर एक आसपास के शब्दों के साथ ‘make’ या ‘do’ दिखाती है, और उनसे पैटर्न खोजने को कहती है। यह उपागम:","optionsHi":["अधिगमकर्ताओं को वास्तविक प्रयोग से सहपद (collocations) खोजने देता है, इसलिए पैटर्न नियम से बेहतर टिकते हैं","विद्यालय के लिए बहुत उन्नत है, क्योंकि ऐसी पंक्तियों से केवल प्रशिक्षित भाषाविद् ही कुछ उपयोगी सीख सकते हैं","शब्दावली शिक्षण की जगह ले लेता है, इसलिए शिक्षिका को कभी किसी शब्द का अर्थ समझाने की आवश्यकता नहीं रहती","मुख्यतः पठन की गति का अभ्यास कराता है, क्योंकि पंक्तियाँ छोटी हैं और बहुत जल्दी पढ़ी जा सकती हैं"],"explanationHi":"संगति-पंक्तियाँ (concordance lines) दिखाती हैं कि शब्द वास्तव में कैसे मिलते हैं (make a mistake, do homework), और इन पैटर्नों को खोजना आँकड़ा-चालित अधिगम है। सहपद बड़ी हद तक रूढ़ होते हैं, इसलिए अनेक वास्तविक उदाहरण देखना नियम से बेहतर काम करता है।"},
  {"id":"cdp-pedagogy-subjects-1913","question":"Class 8 students find phrasal verbs such as ‘eat up’, ‘use up’, ‘fill up’ and ‘cheer up’ hard to remember. Which approach is most helpful?","options":["Learn an alphabetical list of a hundred phrasal verbs with their meanings, ten new verbs each day","Avoid phrasal verbs in class, since students can always use one-word verbs such as ‘consume’ instead","Group them by the particle's meaning (‘up’ for completion or increase) and meet them in context","Translate each phrasal verb into the mother tongue and test the translations every Friday"],"answer":2,"explanation":"Many particles carry a core meaning (‘up’ = completely or more), so grouping by particle makes phrasal verbs less arbitrary, and context shows their use. Long lists and avoidance do not build usable knowledge.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 के विद्यार्थियों को ‘eat up’, ‘use up’, ‘fill up’ और ‘cheer up’ जैसे पदबंध-क्रियाएँ (phrasal verbs) याद रखना कठिन लगता है। कौन-सा उपागम सबसे अधिक सहायक है?","optionsHi":["अर्थ सहित सौ पदबंध-क्रियाओं की वर्णानुक्रम सूची सीखना, हर दिन दस नई क्रियाएँ","कक्षा में पदबंध-क्रियाओं से बचना, क्योंकि विद्यार्थी ‘consume’ जैसी एक-शब्द क्रियाओं का उपयोग कर सकते हैं","उन्हें कण (particle) के अर्थ के अनुसार समूहबद्ध करना (‘up’ पूर्णता या वृद्धि के लिए) और संदर्भ में उनसे मिलना","हर पदबंध-क्रिया का मातृभाषा में अनुवाद करना और हर शुक्रवार अनुवादों की परीक्षा लेना"],"explanationHi":"अनेक कणों का एक मूल अर्थ होता है (‘up’ = पूरी तरह या अधिक), इसलिए कण के अनुसार समूहन पदबंध-क्रियाओं को कम मनमाना बनाता है, और संदर्भ उनका प्रयोग दिखाता है। लंबी सूचियाँ और परहेज़ प्रयोग-योग्य ज्ञान नहीं बनाते।"},
  {"id":"cdp-pedagogy-subjects-1914","question":"To teach report writing, a Class 8 teacher first analyses model reports with the class, then writes one together with them on the board, and only then has students write their own. This sequence follows:","options":["the grammar-translation method, in which model texts are studied, translated and then copied closely","the genre-based teaching–learning cycle: deconstruction, joint construction, then independent writing","the audio-lingual method, in which correct models are drilled until habits are formed","the direct method, in which writing is taught only through speech and never through models"],"answer":1,"explanation":"The genre-based cycle moves from analysing how a text type works, to building one jointly, to independent writing, so support is gradually withdrawn. Students study models to understand them, not to copy them.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"रिपोर्ट-लेखन सिखाने के लिए कक्षा 8 की एक शिक्षिका पहले कक्षा के साथ आदर्श रिपोर्टों का विश्लेषण करती है, फिर श्यामपट्ट पर उनके साथ मिलकर एक लिखती है, और तभी विद्यार्थियों से अपनी लिखवाती है। यह क्रम किसका अनुसरण करता है?","optionsHi":["व्याकरण-अनुवाद विधि, जिसमें आदर्श पाठों का अध्ययन, अनुवाद और फिर निकटता से नकल की जाती है","विधा-आधारित शिक्षण-अधिगम चक्र: विखंडन (deconstruction), संयुक्त निर्माण, फिर स्वतंत्र लेखन","श्रव्य-भाषिक विधि, जिसमें सही आदर्शों का तब तक अभ्यास किया जाता है जब तक आदतें न बन जाएँ","प्रत्यक्ष विधि, जिसमें लेखन केवल वाणी से सिखाया जाता है, आदर्शों से कभी नहीं"],"explanationHi":"विधा-आधारित चक्र पाठ-प्रकार कैसे काम करता है उसके विश्लेषण से, संयुक्त रूप से एक बनाने, फिर स्वतंत्र लेखन की ओर बढ़ता है, इसलिए सहायता धीरे-धीरे हटाई जाती है। विद्यार्थी आदर्शों का अध्ययन उन्हें समझने के लिए करते हैं, नकल करने के लिए नहीं।"},
  {"id":"cdp-pedagogy-subjects-1915","question":"A Class 6 teacher teaches 15 new words each Monday and tests them on Friday; by the next month students have forgotten most of them. Which change is most likely to help retention?","options":["Teach 30 new words each week instead, so that more of them remain after the usual amount of forgetting","Bring the words back in new activities after a day, a week and a month, at growing intervals","Give a harder test on Friday so that students take the weekly word lists more seriously","Ask students to copy each new word twenty times on Monday when it is first introduced"],"answer":1,"explanation":"Memory for words strengthens with repeated retrieval spread out over time (spaced repetition), ideally in varied contexts. Cramming many words or copying them in one sitting leads to quick forgetting.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक शिक्षिका हर सोमवार 15 नए शब्द पढ़ाती है और शुक्रवार को उनकी परीक्षा लेती है; अगले महीने तक विद्यार्थी उनमें से अधिकांश भूल जाते हैं। कौन-सा बदलाव याद रखने में सबसे अधिक मदद करेगा?","optionsHi":["इसके बजाय हर सप्ताह 30 नए शब्द पढ़ाना, ताकि भूलने की सामान्य मात्रा के बाद भी अधिक शब्द बचें","शब्दों को एक दिन, एक सप्ताह और एक महीने बाद, बढ़ते अंतरालों पर, नई गतिविधियों में वापस लाना","शुक्रवार को कठिन परीक्षा देना ताकि विद्यार्थी साप्ताहिक शब्द-सूचियों को अधिक गंभीरता से लें","विद्यार्थियों से सोमवार को जब शब्द पहली बार आए तब हर नया शब्द बीस बार उतारने को कहना"],"explanationHi":"शब्दों की स्मृति समय में फैले बार-बार पुनःप्राप्ति (अंतरालित पुनरावृत्ति) से मज़बूत होती है, आदर्शतः विविध संदर्भों में। एक साथ बहुत-से शब्द रटना या उन्हें एक बैठक में उतारना जल्दी भूलने की ओर ले जाता है।"},
  {"id":"cdp-pedagogy-subjects-1916","question":"After reading a short story with Class 8, a teacher dictates ‘the central idea’ and marks students' own interpretations wrong if they differ. Which approach would better develop literary response?","options":["Give students a guidebook's summary of the story so that their answers match the expected one","Ask students to memorise the teacher's central idea, since examinations reward one single correct answer to such questions","Avoid discussing meaning at all and focus only on the new words and grammar in the story","Invite personal responses and interpretations, asking students to support each with evidence from the text"],"answer":3,"explanation":"A reader-response approach values students' own readings while requiring them to ground interpretations in the text; this builds independent thinking about literature. A single dictated meaning shuts that down.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 के साथ एक छोटी कहानी पढ़ने के बाद एक शिक्षक ‘केंद्रीय भाव’ लिखवाता है और विद्यार्थियों की अपनी व्याख्याओं को, यदि वे भिन्न हों, गलत चिह्नित करता है। कौन-सा उपागम साहित्यिक प्रतिक्रिया को बेहतर विकसित करेगा?","optionsHi":["विद्यार्थियों को कहानी का गाइड-पुस्तक का सारांश देना ताकि उनके उत्तर अपेक्षित उत्तर से मेल खाएँ","विद्यार्थियों से शिक्षक का केंद्रीय भाव रटवाना, क्योंकि परीक्षाएँ ऐसे प्रश्नों के एक ही सही उत्तर को पुरस्कृत करती हैं","अर्थ पर बिल्कुल चर्चा न करना और केवल कहानी के नए शब्दों और व्याकरण पर ध्यान देना","व्यक्तिगत प्रतिक्रियाओं और व्याख्याओं को आमंत्रित करना, और विद्यार्थियों से हर एक का पाठ से साक्ष्य सहित समर्थन करवाना"],"explanationHi":"पाठक-प्रतिक्रिया उपागम विद्यार्थियों के अपने पठन को महत्व देता है, साथ ही उनसे व्याख्याओं को पाठ में आधारित करने की माँग करता है; यह साहित्य के बारे में स्वतंत्र चिंतन बनाता है। एक ही लिखवाया हुआ अर्थ उसे बंद कर देता है।"},
  {"id":"cdp-pedagogy-subjects-1917","question":"Before a Class 6 reading lesson, a teacher prints all the past-tense verbs in a story in bold, without saying anything about them, and students later begin using these forms more accurately. Which idea best explains this?","options":["Input enhancement draws learners' attention to forms, and noticing them helps acquisition","The affective filter rises when text is printed in bold, which makes those forms easier to learn","Bold printing is a form of explicit grammar teaching that replaces the need for rules","Students learn only what is tested, and bold words tell them what will be on the test"],"answer":0,"explanation":"Schmidt's noticing hypothesis holds that learners acquire forms they notice in input; typographic enhancement makes forms more noticeable without explicit teaching. Bold type does not lower or raise the affective filter.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"कक्षा 6 के पठन-पाठ से पहले एक शिक्षिका कहानी के सभी भूतकाल के क्रिया-रूपों को बिना उनके बारे में कुछ कहे मोटे अक्षरों में छाप देती है, और विद्यार्थी बाद में इन रूपों का अधिक सटीक प्रयोग करने लगते हैं। कौन-सा विचार इसे सबसे अच्छी तरह समझाता है?","optionsHi":["निवेश-संवर्धन (input enhancement) अधिगमकर्ताओं का ध्यान रूपों की ओर खींचता है, और उन पर ध्यान देना अर्जन में सहायक है","पाठ को मोटे अक्षरों में छापने पर भावात्मक अवरोध बढ़ता है, जिससे वे रूप सीखना आसान हो जाता है","मोटे अक्षरों में छापना स्पष्ट व्याकरण-शिक्षण का एक रूप है जो नियमों की आवश्यकता की जगह लेता है","विद्यार्थी केवल वही सीखते हैं जिसकी परीक्षा होती है, और मोटे शब्द उन्हें बताते हैं कि परीक्षा में क्या आएगा"],"explanationHi":"श्मिट की ध्यानाकर्षण परिकल्पना (noticing hypothesis) कहती है कि अधिगमकर्ता वे रूप अर्जित करते हैं जिन पर वे निवेश में ध्यान देते हैं; टंकण-संवर्धन स्पष्ट शिक्षण के बिना रूपों को अधिक ध्यान देने योग्य बनाता है। मोटा टाइप भावात्मक अवरोध को न घटाता है न बढ़ाता है।"},
  {"id":"cdp-pedagogy-subjects-1918","question":"During a discussion about a school trip, a student says, ‘We goed to the zoo.’ The teacher replies, ‘Oh, you went to the zoo? What did you see?’ and the talk continues. This is an example of:","options":["focus on forms, in which grammar points are taught one by one in a planned sequence","error avoidance, in which the teacher ignores all errors so that fluency is never disturbed","focus on form, in which attention to a form arises briefly within meaningful communication","explicit correction, in which the teacher states the rule and asks the student to repeat it"],"answer":2,"explanation":"Focus on form draws attention to language briefly during communication, here through a recast. Focus on forms is the planned, item-by-item grammar syllabus, and the teacher did not ignore the error or state a rule.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"स्कूल की यात्रा पर चर्चा के दौरान एक विद्यार्थी कहता है, ‘We goed to the zoo.’ शिक्षिका उत्तर देती है, ‘Oh, you went to the zoo? What did you see?’ और बातचीत चलती रहती है। यह उदाहरण है:","optionsHi":["रूपों पर ध्यान (focus on forms) का, जिसमें व्याकरण के बिंदु योजनाबद्ध क्रम में एक-एक करके पढ़ाए जाते हैं","त्रुटि-परिहार का, जिसमें शिक्षिका सभी त्रुटियों की अनदेखी करती है ताकि प्रवाह कभी बाधित न हो","रूप पर ध्यान (focus on form) का, जिसमें किसी रूप की ओर ध्यान सार्थक संप्रेषण के भीतर संक्षेप में आता है","स्पष्ट सुधार का, जिसमें शिक्षिका नियम बताती है और विद्यार्थी से उसे दोहराने को कहती है"],"explanationHi":"रूप पर ध्यान संप्रेषण के दौरान भाषा की ओर संक्षेप में ध्यान खींचता है, यहाँ पुनःरूपण (recast) के माध्यम से। रूपों पर ध्यान योजनाबद्ध, मद-दर-मद व्याकरण पाठ्यक्रम है, और शिक्षिका ने न त्रुटि की अनदेखी की न नियम बताया।"},
  {"id":"cdp-pedagogy-subjects-1919","question":"Before an English test, a Class 9 student decides which sections to revise first, sets herself a timetable and, after each practice, checks which errors she still makes. These are mainly:","options":["cognitive strategies, since they work directly on the language material being learnt","social strategies, since they involve working with others to learn the language","metacognitive strategies, since she plans, monitors and evaluates her own learning","compensation strategies, since they help her make up for gaps in her knowledge"],"answer":2,"explanation":"Planning, monitoring and evaluating one's own learning are metacognitive strategies. Cognitive strategies act on the material itself (practising, note-making), social ones involve others, and compensation strategies cover gaps in use.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"अंग्रेज़ी परीक्षा से पहले कक्षा 9 की एक विद्यार्थी तय करती है कि पहले किन भागों को दोहराना है, अपने लिए समय-सारणी बनाती है और हर अभ्यास के बाद जाँचती है कि वह अब भी कौन-सी त्रुटियाँ करती है। ये मुख्यतः हैं:","optionsHi":["संज्ञानात्मक रणनीतियाँ, क्योंकि वे सीखी जा रही भाषा-सामग्री पर सीधे काम करती हैं","सामाजिक रणनीतियाँ, क्योंकि उनमें भाषा सीखने के लिए दूसरों के साथ काम करना शामिल है","अधिसंज्ञानात्मक (metacognitive) रणनीतियाँ, क्योंकि वह अपने अधिगम की योजना बनाती, निगरानी करती और मूल्यांकन करती है","क्षतिपूर्ति रणनीतियाँ, क्योंकि वे उसे अपने ज्ञान की कमियों की भरपाई में मदद करती हैं"],"explanationHi":"अपने अधिगम की योजना बनाना, निगरानी करना और मूल्यांकन करना अधिसंज्ञानात्मक रणनीतियाँ हैं। संज्ञानात्मक रणनीतियाँ सामग्री पर ही कार्य करती हैं (अभ्यास, नोट बनाना), सामाजिक में दूसरे शामिल होते हैं, और क्षतिपूर्ति रणनीतियाँ प्रयोग में कमियों को ढकती हैं।"},
  {"id":"cdp-pedagogy-subjects-1920","question":"Class 9 students give a talk on the same topic three times to three different partners, first in 4 minutes, then in 3, then in 2. The main purpose of this activity is to develop:","options":["accuracy, since each partner corrects every error before the student moves on to the next round","fluency, since repeating the same content under time pressure speeds up speech","vocabulary, since students must use new words in each version of their talk","listening, since students mainly sit and listen to what their partners say"],"answer":1,"explanation":"In the 4/3/2 activity, content stays the same while time shrinks, so learners retrieve language faster and speak more smoothly; it is a fluency activity, not an accuracy or vocabulary one.","difficulty":"hard","source":"KVS TGT · CTET Paper 2","questionHi":"कक्षा 9 के विद्यार्थी एक ही विषय पर तीन अलग साथियों को तीन बार भाषण देते हैं, पहले 4 मिनट में, फिर 3 में, फिर 2 में। इस गतिविधि का मुख्य उद्देश्य किसे विकसित करना है?","optionsHi":["शुद्धता, क्योंकि हर साथी विद्यार्थी के अगले चरण पर जाने से पहले हर त्रुटि सुधार देता है","प्रवाह, क्योंकि समय के दबाव में वही विषय-वस्तु दोहराने से बोलने की गति बढ़ती है","शब्दावली, क्योंकि विद्यार्थियों को अपने भाषण के हर संस्करण में नए शब्दों का प्रयोग करना होता है","श्रवण, क्योंकि विद्यार्थी मुख्यतः बैठकर अपने साथियों की बात सुनते हैं"],"explanationHi":"4/3/2 गतिविधि में विषय-वस्तु वही रहती है जबकि समय घटता जाता है, इसलिए अधिगमकर्ता भाषा को तेज़ी से पुनःप्राप्त करते हैं और अधिक सहज बोलते हैं; यह प्रवाह की गतिविधि है, शुद्धता या शब्दावली की नहीं।"},
  {"id":"cdp-pedagogy-subjects-1921","question":"To learn spellings, a Class 4 teacher has children look at a word, say it, cover it, write it from memory and then check it against the original. The main strength of this routine is that it:","options":["requires no practice at home, since a single go is enough to learn every word","teaches the meaning of each word, which is the main reason children learn spellings at this stage","replaces reading, since children no longer need to meet the words in any texts","makes children recall the word from memory and check it, rather than merely copy it"],"answer":3,"explanation":"Look–say–cover–write–check builds a visual memory of the word through active recall and self-checking, which copying does not. It is a spelling routine, not a way of teaching meaning.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"वर्तनी सीखने के लिए कक्षा 4 की एक शिक्षिका बच्चों से शब्द को देखने, बोलने, ढकने, स्मृति से लिखने और फिर मूल से जाँचने को कहती है। इस दिनचर्या की मुख्य शक्ति यह है कि यह:","optionsHi":["घर पर अभ्यास की आवश्यकता समाप्त कर देती है, क्योंकि एक बार का प्रयास हर शब्द सीखने के लिए पर्याप्त है","हर शब्द का अर्थ सिखाती है, जो इस चरण में वर्तनी सीखने का मुख्य कारण है","पठन की जगह ले लेती है, क्योंकि बच्चों को अब किसी पाठ में शब्दों से मिलने की आवश्यकता नहीं रहती","बच्चों से शब्द को स्मृति से याद करवाती और जाँचवाती है, केवल उतारने के बजाय"],"explanationHi":"देखो–बोलो–ढको–लिखो–जाँचो सक्रिय पुनःस्मरण और स्व-जाँच से शब्द की दृश्य स्मृति बनाता है, जो उतारना नहीं करता। यह वर्तनी की दिनचर्या है, अर्थ सिखाने का तरीका नहीं।"},
  {"id":"cdp-pedagogy-subjects-1922","question":"In a Class 7 English reader, a story shows the mother cooking and the father reading the newspaper on every page. To develop critical literacy, which question should the teacher ask?","options":["Whose work is shown and whose is missing, and how could the story be retold differently?","What did the mother cook in the story, and how many members were there in the family?","Which new words did you find in the story, and what is the meaning of each of them?","Which part of the story did you like the most, and would you recommend it to a friend? Why or why not?"],"answer":0,"explanation":"Critical literacy asks how a text represents people, whose roles are visible or hidden and what alternatives exist. Recall, vocabulary or liking questions do not examine the text's assumptions.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 7 के अंग्रेज़ी पाठ्य-पुस्तक में एक कहानी हर पृष्ठ पर माँ को खाना पकाते और पिता को अख़बार पढ़ते दिखाती है। आलोचनात्मक साक्षरता को विकसित करने के लिए शिक्षिका को कौन-सा प्रश्न पूछना चाहिए?","optionsHi":["किसका काम दिखाया गया है और किसका छूटा है, और कहानी को अलग ढंग से कैसे दोबारा सुनाया जा सकता है?","कहानी में माँ ने क्या पकाया, और परिवार में कितने सदस्य थे?","तुम्हें कहानी में कौन-से नए शब्द मिले, और उनमें से हर एक का अर्थ क्या है?","कहानी का कौन-सा भाग तुम्हें सबसे अच्छा लगा, और क्या तुम इसे किसी मित्र को सुझाओगे? क्यों या क्यों नहीं?"],"explanationHi":"आलोचनात्मक साक्षरता पूछती है कि कोई पाठ लोगों का निरूपण कैसे करता है, किनकी भूमिकाएँ दिखाई या छिपाई गई हैं और कौन-से विकल्प हैं। स्मरण, शब्दावली या पसंद के प्रश्न पाठ की मान्यताओं की जाँच नहीं करते।"},
  {"id":"cdp-pedagogy-subjects-1923","question":"Reader P knows every word in a passage about a cricket match but cannot follow it, having never seen cricket. Reader Q, a keen cricket fan, guesses the story from the first line and ignores what the text actually says. What does the interactive view of reading suggest?","options":["Reading combines decoding the text and using background knowledge; P lacks the second and Q neglects the first","P is the better reader, since reading is only the accurate decoding of each word and every sentence on the page","Q is the better reader, since reading is only guessing meaning from what one already knows about a topic","Neither is reading at all, since reading begins only once a reader knows every word and the whole topic"],"answer":0,"explanation":"Interactive models combine bottom-up processing (decoding words) with top-down processing (using schema). P has the first without the second; Q over-relies on the second and ignores the text.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"पाठक P क्रिकेट मैच के गद्यांश का हर शब्द जानता है पर उसे समझ नहीं पाता, क्योंकि उसने कभी क्रिकेट नहीं देखा। पाठक Q, जो क्रिकेट का शौकीन है, पहली पंक्ति से कहानी का अनुमान लगा लेता है और पाठ वास्तव में जो कहता है उसकी अनदेखी करता है। पठन का अंतःक्रियात्मक दृष्टिकोण क्या सुझाता है?","optionsHi":["पठन में पाठ का विसंकेतन और पृष्ठभूमि-ज्ञान का उपयोग दोनों मिलते हैं; P में दूसरा नहीं है और Q पहले की उपेक्षा करता है","P बेहतर पाठक है, क्योंकि पठन केवल पृष्ठ पर हर शब्द और हर वाक्य का सटीक विसंकेतन है","Q बेहतर पाठक है, क्योंकि पठन केवल उसी से अर्थ का अनुमान लगाना है जो कोई किसी विषय के बारे में पहले से जानता है","दोनों में से कोई पठन ही नहीं कर रहा, क्योंकि पठन तभी शुरू होता है जब पाठक हर शब्द और पूरा विषय जानता हो"],"explanationHi":"अंतःक्रियात्मक मॉडल नीचे-से-ऊपर प्रक्रिया (शब्दों का विसंकेतन) को ऊपर-से-नीचे प्रक्रिया (स्कीमा का उपयोग) के साथ जोड़ते हैं। P के पास पहली है, दूसरी नहीं; Q दूसरी पर अति-निर्भर है और पाठ की अनदेखी करता है।"},
  {"id":"cdp-pedagogy-subjects-1924","question":"In a one-to-one writing conference with a Class 6 student about her story draft, what should the teacher do first?","options":["Correct all the spelling and grammar errors in the draft so the student can copy them","Read out a model story by a famous author so that she can see how a good story should be written and organised","Ask what she is trying to say and what she likes most, then talk about one part that could be clearer","Give the draft a grade so that she knows where she stands before she begins her revision"],"answer":2,"explanation":"Conferences work best when they start from the writer's intentions and focus on meaning and one or two revisions; correcting everything or grading makes the student passive and shifts attention to surface errors.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 की एक विद्यार्थी के साथ उसकी कहानी के मसौदे पर आमने-सामने के लेखन-परामर्श में शिक्षिका को सबसे पहले क्या करना चाहिए?","optionsHi":["मसौदे की सभी वर्तनी और व्याकरण की त्रुटियाँ सुधार देना ताकि विद्यार्थी उन्हें उतार ले","किसी प्रसिद्ध लेखक की आदर्श कहानी पढ़कर सुनाना ताकि वह देखे कि अच्छी कहानी कैसे लिखी और संगठित की जाती है","पूछना कि वह क्या कहना चाहती है और उसे सबसे अधिक क्या पसंद है, फिर एक ऐसे भाग पर बात करना जो अधिक स्पष्ट हो सकता है","मसौदे को ग्रेड देना ताकि वह संशोधन शुरू करने से पहले जान सके कि वह कहाँ खड़ी है"],"explanationHi":"परामर्श तब सबसे अच्छा काम करते हैं जब वे लेखक के इरादों से शुरू हों और अर्थ तथा एक-दो संशोधनों पर केंद्रित हों; सब कुछ सुधारना या ग्रेड देना विद्यार्थी को निष्क्रिय बनाता है और ध्यान सतही त्रुटियों पर ले जाता है।"},
  {"id":"cdp-pedagogy-subjects-1925","question":"While writing an email to a pen-friend, a Class 8 student realises she does not know how to say ‘I am looking forward to meeting you’ and asks the teacher. Which idea from second-language research best explains the value of such moments?","options":["The input hypothesis, which says that only listening and reading lead to acquisition","The output hypothesis, which says that producing language makes learners notice gaps in what they know","The critical period hypothesis, which says that language is learnt best before puberty","The monitor hypothesis, which says that consciously learnt rules are used only to edit what we say or write"],"answer":1,"explanation":"Swain's output hypothesis holds that trying to produce language pushes learners to notice what they cannot yet say and to seek the form, which aids learning. Krashen's input hypothesis would give output little role.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"पत्र-मित्र को ईमेल लिखते हुए कक्षा 8 की एक विद्यार्थी को एहसास होता है कि वह ‘I am looking forward to meeting you’ कहना नहीं जानती और शिक्षिका से पूछती है। द्वितीय भाषा अनुसंधान का कौन-सा विचार ऐसे क्षणों के मूल्य को सबसे अच्छी तरह समझाता है?","optionsHi":["निवेश परिकल्पना (input hypothesis), जो कहती है कि केवल सुनना और पढ़ना ही अर्जन की ओर ले जाते हैं","निर्गत परिकल्पना (output hypothesis), जो कहती है कि भाषा का उत्पादन अधिगमकर्ताओं को उनके ज्ञान की कमियाँ दिखाता है","क्रांतिक अवधि परिकल्पना, जो कहती है कि भाषा यौवनारंभ से पहले सबसे अच्छी सीखी जाती है","निगरानी परिकल्पना (monitor hypothesis), जो कहती है कि सचेत रूप से सीखे नियम केवल हमारे बोले या लिखे को संपादित करने के लिए प्रयुक्त होते हैं"],"explanationHi":"स्वेन की निर्गत परिकल्पना कहती है कि भाषा उत्पन्न करने का प्रयास अधिगमकर्ताओं को यह देखने के लिए प्रेरित करता है कि वे अभी क्या नहीं कह सकते और रूप खोजने के लिए, जो अधिगम में सहायक है। क्रैशेन की निवेश परिकल्पना निर्गत को बहुत कम भूमिका देती।"},
  {"id":"cdp-pedagogy-subjects-1926","question":"Class 8 stories keep telling feelings flatly: ‘She was very sad.’ Which approach most effectively helps students write more vividly?","options":["Build a class word wall of precise feeling words such as gloomy, crushed and uneasy, and encourage students to use them","Have students keep a daily journal about their own feelings to build fluency and confidence in expressing emotion","Return each draft with every flat sentence marked and a livelier version suggested in the margin for students to copy","Read passages where writers show a feeling through actions and detail, then have students revise one of their own lines"],"answer":3,"explanation":"Mentor texts let students see how skilled writers show emotion through action and detail, then practise that craft on their own lines. A word wall is tempting, but swapping 'sad' for 'gloomy' still tells the feeling rather than showing it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 8 की कहानियों में भावनाएँ सपाट ढंग से बताई जाती हैं: ‘She was very sad.’ कौन-सा उपागम विद्यार्थियों को अधिक सजीव लिखने में सबसे प्रभावी रूप से मदद करता है?","optionsHi":["कक्षा की शब्द-दीवार बनाना जिसमें gloomy, crushed और uneasy जैसे सटीक भाव-शब्द हों, और विद्यार्थियों को उनके प्रयोग के लिए प्रोत्साहित करना","विद्यार्थियों से अपनी भावनाओं के बारे में दैनिक डायरी रखवाना, भावनाएँ व्यक्त करने में प्रवाह और आत्मविश्वास बनाने के लिए","हर मसौदा लौटाना जिसमें हर सपाट वाक्य चिह्नित हो और हाशिये में अधिक जीवंत संस्करण सुझाया हो, जिसे विद्यार्थी उतारें","ऐसे गद्यांश पढ़ना जहाँ लेखक क्रियाओं और विवरण से भाव दिखाते हैं, फिर विद्यार्थियों से अपनी एक पंक्ति को संशोधित करवाना"],"explanationHi":"आदर्श पाठ (mentor texts) विद्यार्थियों को देखने देते हैं कि कुशल लेखक क्रिया और विवरण से भावना कैसे दिखाते हैं, फिर वे अपनी पंक्तियों पर वह शिल्प अभ्यास करते हैं। शब्द-दीवार आकर्षक है, पर ‘sad’ को ‘gloomy’ से बदलना अब भी भावना को दिखाने के बजाय बताता है।"},
  {"id":"cdp-pedagogy-subjects-1927","question":"A Class 4 child with dyslexia struggles to link English letters with sounds despite much reading practice. Which approach is best supported for her?","options":["Giving her more silent reading of long passages, so that she meets words more often","Excusing her from reading and writing in English until she grows out of the difficulty","Having her copy each spelling list neatly several times, since dyslexia is mainly a difficulty with handwriting","Structured, multisensory phonics in which she sees, says, hears and traces letters and sounds"],"answer":3,"explanation":"Explicit, systematic phonics using several senses together (as in Orton–Gillingham-based methods) is well supported for dyslexia. More unsupported reading or copying does not address the decoding difficulty.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT","questionHi":"कक्षा 4 की डिस्लेक्सिया से ग्रस्त एक बच्ची बहुत पठन-अभ्यास के बावजूद अंग्रेज़ी अक्षरों को ध्वनियों से जोड़ने में संघर्ष करती है। उसके लिए कौन-सा उपागम सबसे अच्छी तरह समर्थित है?","optionsHi":["उसे लंबे गद्यांशों का और मौन पठन देना, ताकि वह शब्दों से अधिक बार मिले","उसे अंग्रेज़ी में पठन और लेखन से तब तक छूट देना जब तक वह कठिनाई से उबर न जाए","उससे हर वर्तनी-सूची को कई बार साफ़-सुथरे ढंग से उतरवाना, क्योंकि डिस्लेक्सिया मुख्यतः हस्तलेखन की कठिनाई है","संरचित, बहु-संवेदी (multisensory) वर्ण-ध्वनि शिक्षण, जिसमें वह अक्षरों और ध्वनियों को देखती, बोलती, सुनती और उँगली से बनाती है"],"explanationHi":"कई इंद्रियों को साथ जोड़ने वाला स्पष्ट, व्यवस्थित वर्ण-ध्वनि शिक्षण (जैसे ऑर्टन–गिलिंघम पर आधारित विधियों में) डिस्लेक्सिया के लिए अच्छी तरह समर्थित है। अधिक बिना सहायता का पठन या उतारना विसंकेतन की कठिनाई को संबोधित नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-1928","question":"Taught that ‘a verb is a doing word’, a Class 6 student labels ‘swimming’ in ‘Swimming is good exercise’ as a verb. What does this show?","options":["A meaning-based definition misleads; word class depends on how a word functions in the sentence","The student is right, since every word ending in ‘-ing’ is a verb in all sentences","The student is careless and should learn the definition of a verb more thoroughly","The sentence is ungrammatical, since a verb cannot be used as the subject of a sentence in English"],"answer":0,"explanation":"Here ‘swimming’ is the subject and works as a noun (a gerund). Defining word classes by meaning (doing word, naming word) fails such cases; students should look at the job the word does.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT","questionHi":"यह सिखाए जाने पर कि ‘क्रिया करने वाला शब्द है’, कक्षा 6 की एक विद्यार्थी ‘Swimming is good exercise’ में ‘swimming’ को क्रिया (verb) के रूप में चिह्नित करती है। यह क्या दिखाता है?","optionsHi":["अर्थ-आधारित परिभाषा भ्रमित करती है; शब्द-भेद इस पर निर्भर है कि शब्द वाक्य में कैसे कार्य करता है","विद्यार्थी सही है, क्योंकि ‘-ing’ में समाप्त होने वाला हर शब्द सभी वाक्यों में क्रिया होता है","विद्यार्थी लापरवाह है और उसे क्रिया की परिभाषा अधिक अच्छी तरह सीखनी चाहिए","वाक्य व्याकरण-विरुद्ध है, क्योंकि अंग्रेज़ी में क्रिया वाक्य का कर्ता नहीं हो सकती"],"explanationHi":"यहाँ ‘swimming’ कर्ता है और संज्ञा (gerund) की तरह कार्य करता है। शब्द-भेदों को अर्थ से परिभाषित करना (क्रिया-शब्द, नाम-शब्द) ऐसे मामलों में विफल होता है; विद्यार्थियों को देखना चाहिए कि शब्द कौन-सा कार्य करता है।"},
  {"id":"cdp-pedagogy-subjects-1929","question":"Class 6 students write only in short, choppy sentences such as ‘I have a dog. The dog is brown. It is playful.’ Which activity best builds more mature sentences?","options":["Ban short sentences in all their writing, so that students are forced to write longer ones","Teach the definitions of simple, compound and complex sentences for a test the following week","Give sets of short sentences to combine in different ways, using ‘and’, ‘which’ and ‘because’","Ask students to copy long sentences from the textbook into their notebooks every day"],"answer":2,"explanation":"Sentence-combining practice lets students try out ways of joining ideas and compare the results, which develops syntactic maturity. Definitions, bans or copying do not give that practice.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 6 के विद्यार्थी केवल छोटे, कटे-कटे वाक्यों में लिखते हैं, जैसे ‘I have a dog. The dog is brown. It is playful.’ कौन-सी गतिविधि अधिक परिपक्व वाक्य बनाने में सबसे अच्छी मदद करती है?","optionsHi":["उनके सभी लेखन में छोटे वाक्यों पर रोक लगाना, ताकि विद्यार्थी लंबे वाक्य लिखने को बाध्य हों","सरल, संयुक्त और मिश्र वाक्यों की परिभाषाएँ पढ़ाना जिनकी अगले सप्ताह परीक्षा होगी","छोटे वाक्यों के समूह देना जिन्हें ‘and’, ‘which’ और ‘because’ का प्रयोग करके अलग-अलग तरीकों से जोड़ना है","विद्यार्थियों से हर दिन पाठ्यपुस्तक के लंबे वाक्य अपनी कॉपियों में उतारने को कहना"],"explanationHi":"वाक्य-संयोजन का अभ्यास विद्यार्थियों को विचारों को जोड़ने के तरीके आज़माने और परिणामों की तुलना करने देता है, जो वाक्य-रचना की परिपक्वता विकसित करता है। परिभाषाएँ, प्रतिबंध या उतारना वह अभ्यास नहीं देते।"},
  {"id":"cdp-pedagogy-subjects-1930","question":"A Class 6 English teacher has limited time for explicit vocabulary teaching. Which words should get the most class time?","options":["Rare literary words from the textbook poems, since these are the most impressive ones to use in essays","High-frequency words that cover most of everyday texts, since these give the greatest return","Words that are spelt in unusual ways, since these cause the most errors in written tests","Technical words from science and maths, since every other subject needs them most often"],"answer":1,"explanation":"A small set of high-frequency words makes up most of the running words in ordinary texts, so teaching them well pays off the most; rarer words are better left to context and dictionaries.","difficulty":"hard","source":"KVS TGT · CTET Paper 2","questionHi":"कक्षा 6 की एक अंग्रेज़ी शिक्षिका के पास स्पष्ट शब्दावली-शिक्षण के लिए सीमित समय है। किन शब्दों को कक्षा का सबसे अधिक समय मिलना चाहिए?","optionsHi":["पाठ्यपुस्तक की कविताओं के दुर्लभ साहित्यिक शब्द, क्योंकि निबंधों में प्रयोग के लिए ये सबसे प्रभावशाली हैं","उच्च-बारंबारता वाले शब्द जो रोज़मर्रा के अधिकांश पाठों को कवर करते हैं, क्योंकि इनसे सबसे अधिक प्रतिफल मिलता है","असामान्य ढंग से लिखे जाने वाले शब्द, क्योंकि ये लिखित परीक्षाओं में सबसे अधिक त्रुटियाँ कराते हैं","विज्ञान और गणित के तकनीकी शब्द, क्योंकि अन्य हर विषय को इनकी सबसे अधिक बार आवश्यकता होती है"],"explanationHi":"उच्च-बारंबारता वाले शब्दों का एक छोटा समूह साधारण पाठों के अधिकांश चालू शब्द बनाता है, इसलिए उन्हें अच्छी तरह पढ़ाना सबसे अधिक फल देता है; दुर्लभ शब्द संदर्भ और शब्दकोशों के लिए छोड़ देना बेहतर है।"},
  {"id":"cdp-pedagogy-subjects-1931","question":"A Class 3 child writes ‘jumpt’, ‘playd’ and ‘wantid’. What is the best teaching response?","options":["Mark the words wrong and have her copy each correct spelling ten times in her notebook","Show that ‘-ed’ is written the same for every past-tense verb, whatever sound it makes","Teach her to spell by sound alone, since English spelling closely follows the way words are pronounced","Tell her to avoid past-tense verbs in her writing until she knows how to spell them"],"answer":1,"explanation":"She spells by sound, and the past-tense ending is pronounced /t/, /d/ or /ɪd/; English keeps one spelling, ‘-ed’, for the meaning. Teaching this morpheme pattern fixes all three errors at once.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की एक बच्ची ‘jumpt’, ‘playd’ और ‘wantid’ लिखती है। सबसे अच्छी शिक्षण-प्रतिक्रिया क्या है?","optionsHi":["शब्दों को गलत चिह्नित करना और उससे हर सही वर्तनी अपनी कॉपी में दस बार उतरवाना","दिखाना कि ‘-ed’ हर भूतकाल क्रिया के लिए एक ही तरह लिखा जाता है, चाहे वह कोई भी ध्वनि दे","उसे केवल ध्वनि से वर्तनी लिखना सिखाना, क्योंकि अंग्रेज़ी की वर्तनी शब्दों के उच्चारण का निकटता से अनुसरण करती है","उससे कहना कि जब तक वह उनकी वर्तनी लिखना न जान ले तब तक अपने लेखन में भूतकाल क्रियाओं से बचे"],"explanationHi":"वह ध्वनि से वर्तनी लिखती है, और भूतकाल का अंत /t/, /d/ या /ɪd/ बोला जाता है; अंग्रेज़ी अर्थ के लिए एक ही वर्तनी ‘-ed’ रखती है। इस रूपिम-पैटर्न को सिखाना तीनों त्रुटियाँ एक साथ ठीक करता है।"},
  {"id":"cdp-pedagogy-subjects-1932","question":"A teacher shows Class 5 that answers can be ‘Right There’ in one sentence, found by ‘Think and Search’ across the text, worked out with ‘Author and Me’, or come ‘On My Own’. The main aim of teaching this framework is to help students:","options":["remember the names of four question types for a test on reading comprehension","answer only those questions that can be found directly in a single sentence of the text they have read","avoid using their own experience, since answers should always come from the text","know where to look for an answer, so they combine text and their own knowledge as needed"],"answer":3,"explanation":"Question–Answer Relationships teach students that some answers are stated, some must be pieced together, and some need their own knowledge with the text; knowing this improves how they search for and build answers.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"एक शिक्षिका कक्षा 5 को दिखाती है कि उत्तर एक वाक्य में ‘ठीक वहीं’ (Right There) हो सकते हैं, पाठ भर में ‘सोचो और खोजो’ (Think and Search) से मिल सकते हैं, ‘लेखक और मैं’ (Author and Me) से निकाले जा सकते हैं, या ‘मेरे अपने से’ (On My Own) आ सकते हैं। इस ढाँचे को पढ़ाने का मुख्य उद्देश्य विद्यार्थियों की मदद करना है कि वे:","optionsHi":["पठन-बोध की परीक्षा के लिए चार प्रश्न-प्रकारों के नाम याद रखें","केवल उन्हीं प्रश्नों का उत्तर दें जो उनके पढ़े पाठ के एक वाक्य में सीधे मिल सकते हैं","अपने अनुभव का उपयोग करने से बचें, क्योंकि उत्तर हमेशा पाठ से आने चाहिए","जानें कि उत्तर के लिए कहाँ देखना है, ताकि वे आवश्यकतानुसार पाठ और अपने ज्ञान को जोड़ें"],"explanationHi":"प्रश्न–उत्तर संबंध विद्यार्थियों को सिखाते हैं कि कुछ उत्तर कहे गए होते हैं, कुछ जोड़कर बनाने पड़ते हैं, और कुछ में पाठ के साथ उनके अपने ज्ञान की आवश्यकता होती है; यह जानना उनके उत्तर खोजने और बनाने के तरीके को सुधारता है।"},
  {"id":"cdp-pedagogy-subjects-1933","question":"In a Class 7 English class, small groups read the same novel; each member has a rotating role such as discussion leader, word finder or connector, and groups meet weekly. This is called:","options":["literature circles","guided reading","round-robin reading","shared reading"],"answer":0,"explanation":"Literature circles are student-led discussion groups reading the same book, with rotating roles to structure talk. Guided reading is teacher-led small-group instruction, and round-robin reading is turn-taking aloud.","difficulty":"moderate","source":"KVS TGT · CTET Paper 2","questionHi":"कक्षा 7 की अंग्रेज़ी कक्षा में छोटे समूह एक ही उपन्यास पढ़ते हैं; हर सदस्य की चर्चा-नेता, शब्द-खोजी या संयोजक जैसी बारी-बारी की भूमिका होती है, और समूह साप्ताहिक रूप से मिलते हैं। इसे कहते हैं:","optionsHi":["साहित्य-मंडल (literature circles)","निर्देशित पठन (guided reading)","बारी-बारी पठन (round-robin reading)","साझा पठन (shared reading)"],"explanationHi":"साहित्य-मंडल विद्यार्थी-नेतृत्व वाले चर्चा-समूह हैं जो एक ही पुस्तक पढ़ते हैं, बातचीत को संरचित करने के लिए बारी-बारी की भूमिकाओं के साथ। निर्देशित पठन शिक्षक-नेतृत्व वाला छोटा-समूह शिक्षण है, और बारी-बारी पठन ज़ोर से बारी लेना है।"},
  {"id":"cdp-pedagogy-subjects-1934","question":"Which of these shows the deepest knowledge of the word ‘heavy’ by a Class 8 student?","options":["She can spell ‘heavy’ correctly and give its exact meaning in her mother tongue and in Hindi","She can pick out ‘heavy’ from four options in a matching test of meanings","She uses ‘heavy rain’ and ‘heavy traffic’ correctly, but says ‘strong tea’, not ‘heavy tea’","She can say that ‘heavy’ is an adjective and that ‘light’ is its antonym"],"answer":2,"explanation":"Knowing a word fully includes its collocations and limits of use, not just form and meaning. Using ‘heavy’ with the right partners shows that depth; spelling, translation or matching show only basic knowledge.","difficulty":"hard","source":"KVS TGT · CTET Paper 2","questionHi":"इनमें से कौन-सा कक्षा 8 की एक विद्यार्थी के ‘heavy’ शब्द के सबसे गहरे ज्ञान को दर्शाता है?","optionsHi":["वह ‘heavy’ की सही वर्तनी लिख सकती है और उसका सटीक अर्थ अपनी मातृभाषा और हिंदी में दे सकती है","वह अर्थों के मिलान की परीक्षा में चार विकल्पों में से ‘heavy’ को चुन सकती है","वह ‘heavy rain’ और ‘heavy traffic’ का सही प्रयोग करती है, पर ‘heavy tea’ नहीं, ‘strong tea’ कहती है","वह कह सकती है कि ‘heavy’ विशेषण है और ‘light’ उसका विलोम है"],"explanationHi":"किसी शब्द को पूरी तरह जानने में उसके सहपद और प्रयोग की सीमाएँ शामिल हैं, केवल रूप और अर्थ नहीं। ‘heavy’ का सही साथियों के साथ प्रयोग वह गहराई दिखाता है; वर्तनी, अनुवाद या मिलान केवल बुनियादी ज्ञान दिखाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1935","question":"When a Class 4 teacher asks a child, ‘Can you open the window?’, the child says ‘Yes, I can’ and stays seated. The child is most likely still developing:","options":["vocabulary, since he does not know the meaning of the word ‘window’","pronunciation, since he could not say the word ‘open’ clearly enough to be understood","pragmatic understanding, since the question is really a polite request","listening, since he did not hear the teacher's question properly"],"answer":2,"explanation":"He answered the literal question about ability, missing that ‘Can you…?’ is a polite request. Understanding such indirect meanings is pragmatic competence, built through use in real situations.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"जब कक्षा 4 की एक शिक्षिका बच्चे से पूछती है, ‘Can you open the window?’, तो बच्चा कहता है ‘Yes, I can’ और बैठा रहता है। बच्चा संभवतः अभी किसे विकसित कर रहा है?","optionsHi":["शब्दावली, क्योंकि वह ‘window’ शब्द का अर्थ नहीं जानता","उच्चारण, क्योंकि वह ‘open’ शब्द को इतना स्पष्ट नहीं बोल पाया कि समझा जा सके","प्रयोगपरक (pragmatic) समझ, क्योंकि प्रश्न वास्तव में एक विनम्र अनुरोध है","श्रवण, क्योंकि उसने शिक्षिका का प्रश्न ठीक से नहीं सुना"],"explanationHi":"उसने क्षमता के बारे में शाब्दिक प्रश्न का उत्तर दिया, यह चूकते हुए कि ‘Can you…?’ एक विनम्र अनुरोध है। ऐसे अप्रत्यक्ष अर्थों को समझना प्रयोगपरक सक्षमता है, जो वास्तविक स्थितियों में प्रयोग से बनती है।"},
  {"id":"cdp-pedagogy-subjects-1936","question":"A Class 5 teacher first writes a paragraph on the board while thinking aloud, then writes the next one with the class's suggestions, then has pairs write one, and finally each child writes alone. This sequence reflects:","options":["gradual release of responsibility: I do, we do, you do together, you do alone","the grammar-translation method, in which a model is translated and then copied","free writing, in which children write without any planning or support at all","the audio-lingual method, in which correct forms are drilled through repetition"],"answer":0,"explanation":"In gradual release, the teacher models, then shares the task, then supports pairs, and finally hands over to independent work, so responsibility shifts step by step to the learner.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 की एक शिक्षिका पहले ज़ोर से सोचते हुए श्यामपट्ट पर एक अनुच्छेद लिखती है, फिर कक्षा के सुझावों से अगला लिखती है, फिर जोड़ियों से एक लिखवाती है, और अंत में हर बच्चा अकेला लिखता है। यह क्रम किसे दर्शाता है?","optionsHi":["उत्तरदायित्व का क्रमिक हस्तांतरण: मैं करती हूँ, हम करते हैं, तुम साथ करते हो, तुम अकेले करते हो","व्याकरण-अनुवाद विधि, जिसमें आदर्श का अनुवाद किया जाता है और फिर नकल की जाती है","स्वतंत्र लेखन, जिसमें बच्चे बिना किसी योजना या सहायता के लिखते हैं","श्रव्य-भाषिक विधि, जिसमें सही रूपों का दोहराव से अभ्यास किया जाता है"],"explanationHi":"क्रमिक हस्तांतरण में शिक्षिका आदर्श प्रस्तुत करती है, फिर कार्य साझा करती है, फिर जोड़ियों को सहायता देती है, और अंत में स्वतंत्र कार्य सौंप देती है, इसलिए उत्तरदायित्व चरण-दर-चरण अधिगमकर्ता की ओर जाता है।"},
  {"id":"cdp-pedagogy-subjects-1937","question":"Class 5 children often mix up ‘there’, ‘their’ and ‘they're’ in writing. Which activity is most likely to help?","options":["Write the three words on a chart and have children say them aloud in chorus every day","Tell children to use only ‘there’ in their writing until they are older and more careful","Give the dictionary definitions of the three words and ask children to learn them by heart","Sort sentences from their own writing by meaning, with a picture cue for each word"],"answer":3,"explanation":"The words sound alike, so saying them aloud does not help; children need to link each spelling with its meaning and use, and sorting their own sentences makes that link. Avoidance and definitions alone do not.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 5 के बच्चे अक्सर लेखन में ‘there’, ‘their’ और ‘they're’ को मिला देते हैं। कौन-सी गतिविधि सबसे अधिक मदद करेगी?","optionsHi":["तीनों शब्द चार्ट पर लिखना और बच्चों से हर दिन सामूहिक रूप से ज़ोर से बोलवाना","बच्चों से कहना कि जब तक वे बड़े और अधिक सावधान न हों, केवल ‘there’ का प्रयोग करें","तीनों शब्दों की शब्दकोश-परिभाषाएँ देना और बच्चों से उन्हें कंठस्थ करने को कहना","उनके अपने लेखन के वाक्यों को अर्थ के अनुसार छाँटना, हर शब्द के लिए चित्र-संकेत के साथ"],"explanationHi":"शब्दों की ध्वनि एक-सी है, इसलिए उन्हें ज़ोर से बोलना मदद नहीं करता; बच्चों को हर वर्तनी को उसके अर्थ और प्रयोग से जोड़ना होगा, और अपने वाक्यों को छाँटना वह जोड़ बनाता है। परहेज़ और परिभाषाएँ अकेले नहीं।"},
  {"id":"cdp-pedagogy-subjects-1938","question":"Class 9 essays arguing that mobile phones should be allowed in school give only reasons in favour. Which step most improves their argumentative writing?","options":["Ask students to make the essays longer by adding many more reasons in favour of their own side of the issue","Teach them to state and answer the strongest counter-argument, which makes their case more convincing","Ask students to write only on topics they personally feel very strongly and deeply about","Give them a list of persuasive linking words to put at the start of every paragraph"],"answer":1,"explanation":"A strong argument anticipates and rebuts opposing views; adding counter-arguments shows awareness of the issue and strengthens persuasion. More one-sided reasons or connectors do not.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"कक्षा 9 के निबंध जो तर्क देते हैं कि विद्यालय में मोबाइल फ़ोन की अनुमति होनी चाहिए, केवल पक्ष के कारण देते हैं। कौन-सा कदम उनके तर्क-लेखन को सबसे अधिक सुधारता है?","optionsHi":["विद्यार्थियों से अपने पक्ष में और बहुत-से कारण जोड़कर निबंध लंबे बनाने को कहना","उन्हें सबसे मज़बूत प्रति-तर्क को कहना और उसका उत्तर देना सिखाना, जो उनके पक्ष को अधिक विश्वसनीय बनाता है","विद्यार्थियों से केवल उन्हीं विषयों पर लिखने को कहना जिन पर वे व्यक्तिगत रूप से बहुत ज़ोर से और गहराई से महसूस करते हैं","उन्हें प्रेरक संयोजक शब्दों की सूची देना जिन्हें हर अनुच्छेद की शुरुआत में रखना है"],"explanationHi":"मज़बूत तर्क विरोधी मतों का पूर्वानुमान और खंडन करता है; प्रति-तर्क जोड़ना मुद्दे की जागरूकता दिखाता है और अनुनय को मज़बूत करता है। अधिक एकतरफ़ा कारण या संयोजक नहीं।"},
  {"id":"cdp-pedagogy-subjects-1939","question":"A Class 2 English teacher uses action songs every day. Which is the strongest reason for this?","options":["Songs give repeated, enjoyable exposure to chunks and rhythm with little anxiety","Songs are the only way to teach English grammar to children of this age group","Songs keep children quiet and seated, which makes managing a large class of young children easier","Songs replace the need for any reading or writing in the early English classes"],"answer":0,"explanation":"Action songs give much repetition of whole phrases with rhythm and movement in a relaxed setting, which suits young learners. They are one useful tool, not the only way to teach grammar or a substitute for literacy.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 2 की एक अंग्रेज़ी शिक्षिका हर दिन क्रिया-गीतों (action songs) का उपयोग करती है। इसका सबसे मज़बूत कारण क्या है?","optionsHi":["गीत खंडों और लय का कम चिंता के साथ बार-बार, आनंददायक संपर्क देते हैं","इस आयु-वर्ग के बच्चों को अंग्रेज़ी व्याकरण सिखाने का गीत ही एकमात्र तरीका है","गीत बच्चों को शांत और बैठा रखते हैं, जिससे छोटे बच्चों की बड़ी कक्षा सँभालना आसान होता है","गीत प्रारंभिक अंग्रेज़ी कक्षाओं में किसी भी पठन या लेखन की आवश्यकता की जगह ले लेते हैं"],"explanationHi":"क्रिया-गीत आरामदेह वातावरण में लय और गति के साथ पूरे वाक्यांशों का बहुत दोहराव देते हैं, जो छोटे अधिगमकर्ताओं के अनुकूल है। वे एक उपयोगी उपकरण हैं, व्याकरण सिखाने का एकमात्र तरीका या साक्षरता का विकल्प नहीं।"},
  {"id":"cdp-pedagogy-subjects-1940","question":"A teacher cuts a short story into its sentences, gives one strip to each student in a group, and the group must put the story in order by reading strips aloud, without showing them. The activity mainly develops:","options":["handwriting, since each student must later copy out the whole story neatly from the strips","dictionary skills, since students must look up each unknown word before they can begin","awareness of how texts hang together, through clues such as time words and pronouns","silent reading speed, since each student must read every strip as fast as possible"],"answer":2,"explanation":"To order the strips, students must notice cohesive clues (then, after that, she, it) and the logic of events, while talking to each other. It builds discourse awareness and speaking, not handwriting or speed.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT","questionHi":"एक शिक्षिका एक छोटी कहानी को उसके वाक्यों में काटती है, समूह के हर विद्यार्थी को एक पट्टी देती है, और समूह को बिना पट्टियाँ दिखाए, उन्हें ज़ोर से पढ़कर कहानी को क्रम में लगाना है। गतिविधि मुख्यतः क्या विकसित करती है?","optionsHi":["हस्तलेखन, क्योंकि हर विद्यार्थी को बाद में पट्टियों से पूरी कहानी साफ़-सुथरे ढंग से उतारनी है","शब्दकोश कौशल, क्योंकि शुरू करने से पहले विद्यार्थियों को हर अज्ञात शब्द देखना है","समय-सूचक शब्दों और सर्वनामों जैसे संकेतों के माध्यम से पाठ कैसे जुड़े होते हैं, इसकी जागरूकता","मौन पठन की गति, क्योंकि हर विद्यार्थी को हर पट्टी यथासंभव तेज़ पढ़नी है"],"explanationHi":"पट्टियों को क्रम में लगाने के लिए विद्यार्थियों को एक-दूसरे से बात करते हुए संसक्ति के संकेतों (then, after that, she, it) और घटनाओं के तर्क को देखना होता है। यह प्रवचन-जागरूकता और बोलना बनाता है, हस्तलेखन या गति नहीं।"},
  {"id":"cdp-pedagogy-subjects-1941","question":"In the first weeks of Class 1, a teacher uses each child's own name for many literacy games: finding it on a chart, spotting its first letter in other names, building it from letter cards. Why is the child's name such a useful starting point?","options":["It is personally meaningful, so children attend closely to its letters and use it as an anchor for others","Names are always spelt regularly, so they are the easiest words for children to sound out letter by letter","It saves the teacher from preparing any other reading material during the first months of the session","Names are the words most often tested in early reading assessments, so learning them improves scores"],"answer":0,"explanation":"A child's name is the first word that matters to her; she attends to its letters, recognises them elsewhere and uses them to work out other words. Many names are not phonically regular, so that is not the reason.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 1 के पहले सप्ताहों में एक शिक्षिका साक्षरता के अनेक खेलों के लिए हर बच्चे के अपने नाम का उपयोग करती है: उसे चार्ट पर ढूँढना, दूसरे नामों में उसका पहला अक्षर पहचानना, अक्षर-कार्डों से उसे बनाना। बच्चे का नाम इतना उपयोगी आरंभ-बिंदु क्यों है?","optionsHi":["वह व्यक्तिगत रूप से सार्थक है, इसलिए बच्चे उसके अक्षरों पर ध्यान से ध्यान देते हैं और उसे दूसरों के लिए आधार बनाते हैं","नामों की वर्तनी हमेशा नियमित होती है, इसलिए वे बच्चों के लिए अक्षर-दर-अक्षर ध्वनि निकालने के सबसे आसान शब्द हैं","यह शिक्षिका को सत्र के पहले महीनों में कोई अन्य पठन-सामग्री तैयार करने से बचाता है","नाम प्रारंभिक पठन-आकलनों में सबसे अधिक परखे जाने वाले शब्द हैं, इसलिए उन्हें सीखने से अंक सुधरते हैं"],"explanationHi":"बच्चे का नाम उसके लिए मायने रखने वाला पहला शब्द है; वह उसके अक्षरों पर ध्यान देती है, उन्हें अन्यत्र पहचानती है और उनसे अन्य शब्द निकालती है। अनेक नाम ध्वन्यात्मक रूप से नियमित नहीं होते, इसलिए वह कारण नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1942","question":"A four-year-old confidently ‘reads’ the word on a familiar biscuit packet, but cannot read the same word when it is printed in plain black letters on a card. This most likely shows that she:","options":["has a visual memory problem that needs to be screened by a specialist before any reading begins","has learnt to decode the word but forgets it when the colours are changed","is reading the logo as a picture from its colours and shape, not from the letters","is pretending, since she has no knowledge at all about print or its meaning"],"answer":2,"explanation":"At the earliest, logographic phase children recognise words by context and visual features such as colour and design, not by letters. It is a normal step showing she knows print carries meaning, not decoding or a disorder.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"चार वर्ष की एक बच्ची परिचित बिस्कुट के पैकेट पर लिखे शब्द को आत्मविश्वास से ‘पढ़ती’ है, पर वही शब्द सादे काले अक्षरों में कार्ड पर छपा हो तो नहीं पढ़ पाती। यह संभवतः क्या दिखाता है कि वह:","optionsHi":["दृश्य-स्मृति की समस्या से ग्रस्त है जिसकी पठन शुरू होने से पहले विशेषज्ञ से जाँच होनी चाहिए","शब्द का विसंकेतन करना सीख चुकी है पर रंग बदलने पर उसे भूल जाती है","लोगो को अक्षरों से नहीं, बल्कि उसके रंगों और आकार से चित्र की तरह पढ़ रही है","नाटक कर रही है, क्योंकि उसे छपाई या उसके अर्थ के बारे में कोई ज्ञान नहीं है"],"explanationHi":"सबसे आरंभिक, लोगोग्राफ़िक अवस्था में बच्चे शब्दों को संदर्भ और रंग तथा डिज़ाइन जैसी दृश्य विशेषताओं से पहचानते हैं, अक्षरों से नहीं। यह एक सामान्य चरण है जो दिखाता है कि वह जानती है कि छपाई में अर्थ होता है, न कि विसंकेतन या कोई विकार।"},
  {"id":"cdp-pedagogy-subjects-1943","question":"A five-year-old writes ‘LFNT’ for ‘elephant’ and ‘BK’ for ‘bake’. What strategy is she using?","options":["She is copying words from a wall chart and simply leaving out the letters she cannot remember","She uses letter names for sounds: ‘L’, ‘F’, ‘N’ and ‘K’ sound like parts of the words","She has a hearing difficulty that stops her from hearing the vowel sounds in words","She is writing in a code of her own that has no link with the sounds of the words"],"answer":1,"explanation":"Letter-name spelling is a normal early stage: the name ‘el’ stands for the first syllable of ‘elephant’, ‘ef’ for /f/, ‘en’ for /n/. It shows real phonological analysis, the base for learning conventional spelling.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"पाँच वर्ष की एक बच्ची ‘elephant’ के लिए ‘LFNT’ और ‘bake’ के लिए ‘BK’ लिखती है। वह कौन-सी रणनीति अपना रही है?","optionsHi":["वह दीवार-चार्ट से शब्द उतार रही है और जो अक्षर उसे याद नहीं आते उन्हें छोड़ देती है","वह ध्वनियों के लिए अक्षरों के नाम का उपयोग करती है: ‘L’, ‘F’, ‘N’ और ‘K’ शब्दों के भागों जैसे सुनाई देते हैं","उसे श्रवण-कठिनाई है जो उसे शब्दों में स्वर ध्वनियाँ सुनने से रोकती है","वह अपने ही किसी कूट में लिख रही है जिसका शब्दों की ध्वनियों से कोई संबंध नहीं है"],"explanationHi":"अक्षर-नाम से वर्तनी एक सामान्य आरंभिक अवस्था है: नाम ‘el’ ‘elephant’ के पहले शब्दांश के लिए खड़ा होता है, ‘ef’ /f/ के लिए, ‘en’ /n/ के लिए। यह वास्तविक स्वनिक विश्लेषण दिखाता है, जो प्रचलित वर्तनी सीखने का आधार है।"},
  {"id":"cdp-pedagogy-subjects-1944","question":"While reading a picture book with a small group, a teacher asks a child what is happening, praises the answer, adds a little more language (‘Yes, the dog is chasing the cat up the tall tree’) and asks the child to say it again. This technique is known as:","options":["round-robin reading, in which each child reads one line aloud in turn","guided reading, in which children read a levelled text on their own with the teacher's support","choral reading, in which the group reads the same text aloud together","dialogic reading, in which the adult prompts, evaluates, expands and repeats"],"answer":3,"explanation":"Dialogic reading turns the child into the storyteller through the PEER sequence (prompt, evaluate, expand, repeat), which builds oral language. Here the children are not decoding text, so it is not guided, choral or round-robin reading.","difficulty":"very-hard","source":"KVS PRT · NVS PRT","questionHi":"छोटे समूह के साथ चित्र-पुस्तक पढ़ते हुए एक शिक्षिका बच्चे से पूछती है कि क्या हो रहा है, उत्तर की प्रशंसा करती है, थोड़ी और भाषा जोड़ती है (‘Yes, the dog is chasing the cat up the tall tree’) और बच्चे से उसे दोबारा कहने को कहती है। यह तकनीक कहलाती है:","optionsHi":["बारी-बारी पठन, जिसमें हर बच्चा बारी से एक पंक्ति ज़ोर से पढ़ता है","निर्देशित पठन, जिसमें बच्चे शिक्षिका की सहायता से स्तरित पाठ स्वयं पढ़ते हैं","सामूहिक पठन (choral reading), जिसमें समूह एक ही पाठ साथ-साथ ज़ोर से पढ़ता है","संवादात्मक पठन (dialogic reading), जिसमें वयस्क प्रेरित करता, मूल्यांकन करता, विस्तार देता और दोहरवाता है"],"explanationHi":"संवादात्मक पठन बच्चे को PEER क्रम (प्रेरणा, मूल्यांकन, विस्तार, पुनरावृत्ति) के माध्यम से कथावाचक बनाता है, जो मौखिक भाषा बनाता है। यहाँ बच्चे पाठ का विसंकेतन नहीं कर रहे, इसलिए यह निर्देशित, सामूहिक या बारी-बारी पठन नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1945","question":"A Class 1 teacher uses two kinds of small books: some with repeated patterns (‘I see a red bird. I see a blue bird…’) and some made mostly of words using letter-sounds already taught (‘Sam sat on a mat’). What is the best reason for using both?","options":["Patterned books should be used only for children who cannot learn phonics at all","Patterned books suit weaker readers, while phonic books are for stronger readers","Phonic books should be used only for testing decoding, while patterned books are kept for enjoyment","Patterned books build confidence and print concepts; phonic books let children practise decoding"],"answer":3,"explanation":"Predictable texts let beginners join in and learn about print and fluency, while decodable texts let them apply taught letter-sound knowledge. Each does a different job, so they work best together.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 1 की एक शिक्षिका दो प्रकार की छोटी पुस्तकों का उपयोग करती है: कुछ में दोहराए जाने वाले पैटर्न (‘I see a red bird. I see a blue bird…’) और कुछ ऐसे शब्दों से बनी जो पहले पढ़ाई गई अक्षर-ध्वनियों का प्रयोग करते हैं (‘Sam sat on a mat’)। दोनों के उपयोग का सबसे अच्छा कारण क्या है?","optionsHi":["पैटर्न वाली पुस्तकें केवल उन बच्चों के लिए होनी चाहिए जो वर्ण-ध्वनि बिल्कुल नहीं सीख सकते","पैटर्न वाली पुस्तकें कमज़ोर पाठकों के लिए हैं, और ध्वनि-आधारित पुस्तकें तेज़ पाठकों के लिए","ध्वनि-आधारित पुस्तकें केवल विसंकेतन की जाँच के लिए होनी चाहिए, और पैटर्न वाली पुस्तकें आनंद के लिए रखी जाएँ","पैटर्न वाली पुस्तकें आत्मविश्वास और छपाई की अवधारणाएँ बनाती हैं; ध्वनि-आधारित पुस्तकें बच्चों को विसंकेतन का अभ्यास करने देती हैं"],"explanationHi":"पूर्वानुमेय पाठ शुरुआती पाठकों को शामिल होने और छपाई तथा प्रवाह के बारे में सीखने देते हैं, जबकि विसंकेतन-योग्य पाठ उन्हें पढ़ाए गए अक्षर-ध्वनि ज्ञान को लागू करने देते हैं। हर एक का काम अलग है, इसलिए वे साथ मिलकर सबसे अच्छा काम करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1946","question":"After a class trip, a Class 1 teacher writes a group message on chart paper, but children take turns holding the marker to write letters and words they know while the teacher writes the rest. This is called:","options":["shared writing, in which the teacher alone holds the pen while the children only suggest the words","interactive writing, in which teacher and children share the pen to compose the text together","guided writing, in which each child writes on her own with help from the teacher at her desk","copy writing, in which children copy the teacher's finished text into their own notebooks"],"answer":1,"explanation":"In interactive writing children ‘share the pen’, contributing what they can; in shared writing the teacher scribes the children's ideas. Both model composing, but interactive writing gives practice in letter formation and spelling too.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा की यात्रा के बाद कक्षा 1 की एक शिक्षिका चार्ट पेपर पर समूह-संदेश लिखती है, पर बच्चे बारी-बारी से मार्कर पकड़कर वे अक्षर और शब्द लिखते हैं जो वे जानते हैं, जबकि शेष शिक्षिका लिखती है। इसे कहते हैं:","optionsHi":["साझा लेखन (shared writing), जिसमें केवल शिक्षिका कलम पकड़ती है और बच्चे केवल शब्द सुझाते हैं","अंतःक्रियात्मक लेखन (interactive writing), जिसमें शिक्षिका और बच्चे पाठ साथ रचने के लिए कलम साझा करते हैं","निर्देशित लेखन (guided writing), जिसमें हर बच्चा अपने डेस्क पर शिक्षिका की मदद से अकेले लिखता है","उतारकर लेखन (copy writing), जिसमें बच्चे शिक्षिका का तैयार पाठ अपनी कॉपियों में उतारते हैं"],"explanationHi":"अंतःक्रियात्मक लेखन में बच्चे ‘कलम साझा’ करते हैं, जो वे कर सकते हैं उसमें योगदान देते हुए; साझा लेखन में शिक्षिका बच्चों के विचार लिखती है। दोनों रचना का आदर्श प्रस्तुत करते हैं, पर अंतःक्रियात्मक लेखन अक्षर-निर्माण और वर्तनी का भी अभ्यास देता है।"},
  {"id":"cdp-pedagogy-subjects-1947","question":"A pre-primary teacher often uses wordless picture books with her group. What is their main value for early literacy?","options":["Children tell the story in their own words, building narrative and oral language skills","They prepare children for spelling tests, since children name the objects in each picture","They are meant only for children who cannot yet read, and have no use once reading starts","They keep children quiet, since there are no words to be read aloud during the session"],"answer":0,"explanation":"Without printed words, children must create the narrative: sequencing events, describing and inferring. This builds the oral language and story sense that later reading comprehension depends on.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक पूर्व-प्राथमिक शिक्षिका अपने समूह के साथ प्रायः शब्द-रहित चित्र-पुस्तकों का उपयोग करती है। प्रारंभिक साक्षरता के लिए इनका मुख्य मूल्य क्या है?","optionsHi":["बच्चे कहानी को अपने शब्दों में सुनाते हैं, जिससे कथा और मौखिक भाषा कौशल बनते हैं","वे बच्चों को वर्तनी की परीक्षाओं के लिए तैयार करती हैं, क्योंकि बच्चे हर चित्र की वस्तुओं के नाम बताते हैं","वे केवल उन बच्चों के लिए हैं जो अभी पढ़ नहीं सकते, और पठन शुरू होने पर उनका कोई उपयोग नहीं","वे बच्चों को शांत रखती हैं, क्योंकि सत्र के दौरान ज़ोर से पढ़ने के लिए कोई शब्द नहीं होते"],"explanationHi":"छपे शब्दों के बिना बच्चों को कथा स्वयं रचनी पड़ती है: घटनाओं को क्रम देना, वर्णन करना और अनुमान लगाना। इससे वह मौखिक भाषा और कहानी-बोध बनता है जिस पर बाद का पठन-बोध निर्भर करता है।"},
  {"id":"cdp-pedagogy-subjects-1948","question":"Many parents of children in a Class 1 village classroom cannot read. Which advice best supports the children's literacy at home?","options":["Ask parents to hire tutors, since they cannot help with reading themselves","Ask older siblings to make the child copy all the alphabet letters neatly every evening after school","Encourage parents to tell stories, sing songs and talk with the child about picture books","Tell parents to leave literacy entirely to the school, since they cannot read"],"answer":2,"explanation":"Oral storytelling, songs and talk about pictures build vocabulary, narrative and love of books, which matter as much as decoding; non-reading parents can do all of this. Copying drills or giving up on home support help far less.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 1 के एक गाँव की कक्षा के बहुत-से बच्चों के माता-पिता पढ़ नहीं सकते। घर पर बच्चों की साक्षरता को कौन-सी सलाह सबसे अच्छी तरह सहारा देती है?","optionsHi":["माता-पिता से ट्यूटर रखने को कहना, क्योंकि वे स्वयं पठन में मदद नहीं कर सकते","बड़े भाई-बहनों से कहना कि हर शाम स्कूल के बाद बच्चे से वर्णमाला के सभी अक्षर साफ़-सुथरे उतरवाएँ","माता-पिता को कहानियाँ सुनाने, गीत गाने और बच्चे के साथ चित्र-पुस्तकों के बारे में बात करने के लिए प्रोत्साहित करना","माता-पिता से कहना कि साक्षरता पूरी तरह विद्यालय पर छोड़ दें, क्योंकि वे पढ़ नहीं सकते"],"explanationHi":"मौखिक कहानी, गीत और चित्रों के बारे में बातचीत शब्दावली, कथा और पुस्तकों के प्रति प्रेम बनाते हैं, जो विसंकेतन जितने ही महत्वपूर्ण हैं; न पढ़ने वाले माता-पिता यह सब कर सकते हैं। उतारने की कवायद या घर के सहयोग को छोड़ देना बहुत कम मदद करता है।"},
  {"id":"cdp-pedagogy-subjects-1949","question":"A Class 1 teacher teaches the sound of ‘s’ as ‘suh’ and of ‘t’ as ‘tuh’; children then blend ‘suh-a-tuh’ and say ‘suhatuh’ instead of ‘sat’. What should she change?","options":["Teach the letter names instead of sounds, since names are easier for children to blend into words","Stop blending altogether and teach every word as a whole shape for children to memorise","Pronounce sounds as purely as possible, stretching ones like ‘sss’ without an added ‘uh’","Teach the children to blend only words with two letters until they are in Class 2 or later"],"answer":2,"explanation":"Adding a vowel to each consonant (‘suh’) inserts extra sounds that make blending fail. Pure sounds, especially continuous ones that can be stretched (sss, mmm), blend smoothly into words.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 1 की एक शिक्षिका ‘s’ की ध्वनि ‘suh’ और ‘t’ की ‘tuh’ सिखाती है; बच्चे फिर ‘suh-a-tuh’ जोड़ते हैं और ‘sat’ के बजाय ‘suhatuh’ बोलते हैं। उसे क्या बदलना चाहिए?","optionsHi":["ध्वनियों के बजाय अक्षरों के नाम सिखाना, क्योंकि नाम बच्चों के लिए शब्दों में जोड़ना आसान है","जोड़ना (blending) पूरी तरह रोक देना और हर शब्द को बच्चों के याद करने के लिए पूरे आकार के रूप में सिखाना","ध्वनियों का यथासंभव शुद्ध उच्चारण करना, ‘sss’ जैसी ध्वनियों को बिना जोड़े गए ‘uh’ के खींचकर बोलना","बच्चों को केवल दो अक्षरों वाले शब्द जोड़ना सिखाना जब तक वे कक्षा 2 या बाद में न पहुँच जाएँ"],"explanationHi":"हर व्यंजन में स्वर जोड़ना (‘suh’) अतिरिक्त ध्वनियाँ डालता है जिससे जोड़ना विफल हो जाता है। शुद्ध ध्वनियाँ, विशेषकर निरंतर वाली जिन्हें खींचा जा सकता है (sss, mmm), शब्दों में सहजता से जुड़ती हैं।"},
  {"id":"cdp-pedagogy-subjects-1950","question":"Children who read well early read more, gain vocabulary and knowledge, and pull further ahead, while weak readers read less and fall further behind. This pattern, described by Keith Stanovich, is known as:","options":["the Matthew effect in reading","the halo effect in assessment","the Pygmalion effect in teaching","the recency effect in memory"],"answer":0,"explanation":"The Matthew effect (‘the rich get richer’) describes how early reading differences widen over time through differences in reading volume. It is a strong argument for early identification and support.","difficulty":"very-hard","source":"KVS PRT · NVS PRT · DSSSB PRT","questionHi":"जो बच्चे जल्दी अच्छा पढ़ते हैं वे अधिक पढ़ते हैं, शब्दावली और ज्ञान पाते हैं, और आगे निकल जाते हैं, जबकि कमज़ोर पाठक कम पढ़ते हैं और और पिछड़ जाते हैं। कीथ स्टैनोविच द्वारा वर्णित इस पैटर्न को कहते हैं:","optionsHi":["पठन में मैथ्यू प्रभाव (Matthew effect)","आकलन में प्रभामंडल प्रभाव (halo effect)","शिक्षण में पिग्मेलियन प्रभाव (Pygmalion effect)","स्मृति में नवीनता प्रभाव (recency effect)"],"explanationHi":"मैथ्यू प्रभाव (‘अमीर और अमीर होता है’) वर्णन करता है कि पठन की मात्रा में अंतर के कारण आरंभिक पठन के अंतर समय के साथ कैसे बढ़ते हैं। यह प्रारंभिक पहचान और सहायता के लिए एक मज़बूत तर्क है।"},
  {"id":"cdp-pedagogy-subjects-1951","question":"A Class 3 child decodes every word correctly but so slowly and effortfully that she remembers little of what she read. Which explanation best fits?","options":["She does not yet know enough letter-sound links, which is why her decoding is accurate but very slow","She has a memory disorder, since a normal child would remember what she has just read","She is reading carelessly and needs to be told to pay attention to the meaning of the text","Decoding takes up most of her attention, leaving little for comprehension; she needs fluency practice"],"answer":3,"explanation":"Automaticity theory (LaBerge and Samuels) holds that attention is limited: when decoding is effortful, little is left for meaning. Repeated reading and practice make decoding automatic, freeing attention for comprehension.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 3 की एक बच्ची हर शब्द का सही विसंकेतन करती है पर इतना धीमे और प्रयासपूर्वक कि जो पढ़ा उसका बहुत कम याद रख पाती है। कौन-सी व्याख्या सबसे अच्छी तरह बैठती है?","optionsHi":["वह अभी पर्याप्त अक्षर-ध्वनि संबंध नहीं जानती, इसीलिए उसका विसंकेतन सही पर बहुत धीमा है","उसे स्मृति-विकार है, क्योंकि सामान्य बच्चा अभी पढ़ा हुआ याद रखता","वह लापरवाही से पढ़ रही है और उसे पाठ के अर्थ पर ध्यान देने को कहा जाना चाहिए","विसंकेतन उसका अधिकांश ध्यान ले लेता है, जिससे बोध के लिए कम बचता है; उसे प्रवाह के अभ्यास की आवश्यकता है"],"explanationHi":"स्वचालिता सिद्धांत (लाबर्ज और सैमुअल्स) कहता है कि ध्यान सीमित है: जब विसंकेतन प्रयासपूर्ण होता है, अर्थ के लिए कम बचता है। बार-बार पठन और अभ्यास विसंकेतन को स्वचालित बनाते हैं, ध्यान को बोध के लिए मुक्त करते हैं।"},
  {"id":"cdp-pedagogy-subjects-1952","question":"According to the ‘simple view of reading’, reading comprehension is the product of decoding and language comprehension. What follows for a child who decodes perfectly but understands little even when the same text is read aloud to her?","options":["Her difficulty is in decoding, so she needs much more phonics practice to fix the problem","Her difficulty is language comprehension, so she needs vocabulary and oral language work","She has no difficulty, since accurate decoding is the same thing as reading","She needs only to read faster, since speed will bring comprehension with it"],"answer":1,"explanation":"If she cannot understand the text even when it is read to her, the gap is in language comprehension, not decoding. Because the two multiply, strength in one cannot make up for weakness in the other.","difficulty":"very-hard","source":"KVS PRT · NVS PRT","questionHi":"‘पठन के सरल दृष्टिकोण’ (simple view of reading) के अनुसार पठन-बोध विसंकेतन और भाषा-बोध का गुणनफल है। उस बच्ची के लिए क्या निष्कर्ष निकलता है जो पूरी तरह विसंकेतन करती है पर कम समझती है, तब भी जब वही पाठ उसे पढ़कर सुनाया जाए?","optionsHi":["उसकी कठिनाई विसंकेतन में है, इसलिए समस्या ठीक करने के लिए उसे कहीं अधिक वर्ण-ध्वनि अभ्यास चाहिए","उसकी कठिनाई भाषा-बोध में है, इसलिए उसे शब्दावली और मौखिक भाषा पर कार्य चाहिए","उसे कोई कठिनाई नहीं है, क्योंकि सटीक विसंकेतन और पठन एक ही चीज़ हैं","उसे केवल तेज़ पढ़ना है, क्योंकि गति बोध को साथ ले आएगी"],"explanationHi":"यदि वह पाठ तब भी नहीं समझ पाती जब वह उसे पढ़कर सुनाया जाए, तो कमी भाषा-बोध में है, विसंकेतन में नहीं। क्योंकि दोनों गुणा होते हैं, एक में शक्ति दूसरे की कमज़ोरी की भरपाई नहीं कर सकती।"},
  {"id":"cdp-pedagogy-subjects-1953","question":"In a Class 1 journal period, children draw a picture and tell the teacher about it; she writes their exact words under the drawing and reads them back. The main value of this practice is that:","options":["it saves time, since children do not need to write anything at all in Class 1","children see their own spoken words turned into print, linking talk and writing","it gives the teacher a record of each child's handwriting for assessment","it lets the teacher correct the grammar of what the children say before writing"],"answer":1,"explanation":"Scribing a child's own words shows that what we say can be written and read back, a key insight for emergent literacy. Writing their exact words, not corrected ones, keeps ownership with the child.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 1 के डायरी-पीरियड में बच्चे एक चित्र बनाते हैं और शिक्षिका को उसके बारे में बताते हैं; वह उनके सटीक शब्द चित्र के नीचे लिखती है और उन्हें वापस पढ़कर सुनाती है। इस अभ्यास का मुख्य मूल्य यह है कि:","optionsHi":["यह समय बचाता है, क्योंकि कक्षा 1 में बच्चों को कुछ भी लिखने की आवश्यकता नहीं है","बच्चे अपने बोले शब्दों को छपाई में बदलते देखते हैं, जो बोलने और लेखन को जोड़ता है","यह शिक्षिका को आकलन के लिए हर बच्चे की लिखावट का अभिलेख देता है","यह शिक्षिका को लिखने से पहले बच्चों के कहे का व्याकरण सुधारने देता है"],"explanationHi":"बच्चे के अपने शब्दों को लिखना दिखाता है कि जो हम कहते हैं वह लिखा और वापस पढ़ा जा सकता है, जो प्रारंभिक साक्षरता की एक प्रमुख अंतर्दृष्टि है। उनके सटीक शब्द लिखना, सुधारे हुए नहीं, स्वामित्व बच्चे के पास रखता है।"},
  {"id":"cdp-pedagogy-subjects-1954","question":"Consider these statements: I. Children should begin learning about print only after a fixed ‘readiness’ age. II. Literacy development begins long before formal instruction, through everyday experiences with print and talk. III. Scribbling and pretend reading are part of literacy development. IV. Oral language has little link with later reading. Which match the emergent literacy view?","options":["I and IV only","I, II and III only","II, III and IV only","II and III only"],"answer":3,"explanation":"The emergent literacy view rejects a fixed readiness age (I) and sees literacy growing from early experiences, including scribbling and pretend reading (II, III). Oral language is a strong foundation for reading, so IV is wrong.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"इन कथनों पर विचार कीजिए: I. बच्चों को छपाई के बारे में सीखना केवल किसी निश्चित ‘तत्परता’ आयु के बाद शुरू करना चाहिए। II. साक्षरता का विकास औपचारिक शिक्षण से बहुत पहले छपाई और बातचीत के रोज़मर्रा के अनुभवों से शुरू हो जाता है। III. घसीटना और नाटक में पढ़ना साक्षरता-विकास का हिस्सा हैं। IV. मौखिक भाषा का बाद के पठन से बहुत कम संबंध है। कौन-से उभरती साक्षरता (emergent literacy) के दृष्टिकोण से मेल खाते हैं?","optionsHi":["केवल I और IV","केवल I, II और III","केवल II, III और IV","केवल II और III"],"explanationHi":"उभरती साक्षरता का दृष्टिकोण निश्चित तत्परता-आयु (I) को अस्वीकार करता है और साक्षरता को प्रारंभिक अनुभवों से बढ़ता देखता है, जिनमें घसीटना और नाटक में पढ़ना शामिल हैं (II, III)। मौखिक भाषा पठन की मज़बूत नींव है, इसलिए IV गलत है।"},
  {"id":"cdp-pedagogy-subjects-1955","question":"A Class 1 teacher teaches letters c, a, d, g and o together in handwriting lessons. Why is this a sensible grouping?","options":["They are all vowels, so children learn the vowels together before the consonants","They come one after another in the alphabet, so the order is easy to remember","They all start with the same anticlockwise curve, so one movement is practised","They are the letters children use most often in their own names and words"],"answer":2,"explanation":"These letters share a starting stroke, an anticlockwise ‘c’ curve; grouping letters by movement builds correct formation habits. Only a and o are vowels, and they are not consecutive in the alphabet.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 1 की एक शिक्षिका हस्तलेखन के पाठों में अक्षर c, a, d, g और o साथ-साथ सिखाती है। यह समूहन विवेकपूर्ण क्यों है?","optionsHi":["वे सब स्वर हैं, इसलिए बच्चे व्यंजनों से पहले स्वर साथ सीखते हैं","वे वर्णमाला में एक के बाद एक आते हैं, इसलिए क्रम याद रखना आसान है","वे सब एक ही वामावर्त मोड़ से शुरू होते हैं, इसलिए एक ही गति का अभ्यास होता है","वे अक्षर हैं जो बच्चे अपने नामों और शब्दों में सबसे अधिक बार उपयोग करते हैं"],"explanationHi":"इन अक्षरों में एक ही आरंभिक रेखा है, वामावर्त ‘c’ का मोड़; गति के आधार पर अक्षरों का समूहन सही बनावट की आदतें बनाता है। केवल a और o स्वर हैं, और वे वर्णमाला में क्रमागत नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-1956","question":"A pre-primary child asks for the same picture book to be read every day for two weeks. What is the best way for the teacher to view this?","options":["As valuable, since rereading lets the child notice more, predict and join in with the language","As a sign the child is not ready for books, so reading to her should be postponed for a while","As a habit to discourage, since children should hear a new book every single day","As a sign of a learning difficulty, since normal children want variety in their books"],"answer":0,"explanation":"Repeated reading of a favourite book builds familiarity with its language, lets the child predict and ‘read along’, and deepens understanding; it is typical and useful at this age, alongside new books.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"एक पूर्व-प्राथमिक बच्चा दो सप्ताह तक हर दिन वही चित्र-पुस्तक पढ़वाने को कहता है। शिक्षिका को इसे सबसे अच्छी तरह कैसे देखना चाहिए?","optionsHi":["मूल्यवान के रूप में, क्योंकि दोबारा पढ़ना बच्चे को अधिक ध्यान देने, अनुमान लगाने और भाषा में शामिल होने देता है","इस संकेत के रूप में कि बच्चा पुस्तकों के लिए तैयार नहीं है, इसलिए उसे पढ़कर सुनाना कुछ समय के लिए टाल देना चाहिए","हतोत्साहित की जाने वाली आदत के रूप में, क्योंकि बच्चों को हर दिन एक नई पुस्तक सुननी चाहिए","सीखने की कठिनाई के संकेत के रूप में, क्योंकि सामान्य बच्चे अपनी पुस्तकों में विविधता चाहते हैं"],"explanationHi":"पसंदीदा पुस्तक को बार-बार पढ़ना उसकी भाषा से परिचय बनाता है, बच्चे को अनुमान लगाने और ‘साथ पढ़ने’ देता है, और समझ गहरी करता है; नई पुस्तकों के साथ-साथ यह इस आयु में सामान्य और उपयोगी है।"},
  {"id":"cdp-pedagogy-subjects-1957","question":"To check Class 1 children's decoding, a teacher asks them to read made-up words such as ‘mip’, ‘tob’ and ‘sut’. Why use such words?","options":["They test decoding itself, since children cannot have memorised them as sight words","They are easier than real words, so all children can feel successful and confident in the test","They teach new vocabulary, since children learn the meaning of each made-up word","They test spelling, since children must write each word after reading it aloud"],"answer":0,"explanation":"Pseudo-words cannot be recognised from memory or guessed from meaning, so reading them shows whether a child can apply letter-sound knowledge. They carry no meaning and are not easier than familiar words.","difficulty":"very-hard","source":"KVS PRT · NVS PRT","questionHi":"कक्षा 1 के बच्चों के विसंकेतन की जाँच के लिए एक शिक्षिका उनसे ‘mip’, ‘tob’ और ‘sut’ जैसे बनाए हुए शब्द पढ़ने को कहती है। ऐसे शब्द क्यों उपयोग किए जाते हैं?","optionsHi":["वे विसंकेतन की ही परीक्षा लेते हैं, क्योंकि बच्चों ने उन्हें दृष्टि-शब्द के रूप में याद नहीं किया हो सकता","वे असली शब्दों से आसान हैं, इसलिए परीक्षा में सभी बच्चे सफल और आत्मविश्वासी महसूस कर सकते हैं","वे नई शब्दावली सिखाते हैं, क्योंकि बच्चे हर बनाए हुए शब्द का अर्थ सीखते हैं","वे वर्तनी की परीक्षा लेते हैं, क्योंकि बच्चों को ज़ोर से पढ़ने के बाद हर शब्द लिखना होता है"],"explanationHi":"छद्म-शब्दों (pseudo-words) को स्मृति से पहचाना या अर्थ से अनुमानित नहीं किया जा सकता, इसलिए उन्हें पढ़ना दिखाता है कि बच्चा अक्षर-ध्वनि ज्ञान लागू कर सकता है या नहीं। उनका कोई अर्थ नहीं होता और वे परिचित शब्दों से आसान नहीं हैं।"},
  {"id":"cdp-pedagogy-subjects-1958","question":"A pre-primary teacher stocks the play corner, set up as a clinic, with appointment cards, a notepad for ‘prescriptions’, a calendar and a sign saying ‘Doctor is in’. The main purpose is to:","options":["teach children the names of medicines and diseases before they reach Class 1","keep children busy with paper while she works with a small reading group","let children use reading and writing for real purposes within their play","test which children can already write words correctly without any help"],"answer":2,"explanation":"Literacy props in dramatic play let children use print as people really do, pretending to write prescriptions and read signs, which builds an understanding of what literacy is for.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक पूर्व-प्राथमिक शिक्षिका क्लिनिक के रूप में सजाए खेल-कोने में अपॉइंटमेंट कार्ड, ‘नुस्ख़ों’ के लिए नोटपैड, कैलेंडर और ‘Doctor is in’ वाला संकेत रखती है। मुख्य उद्देश्य है:","optionsHi":["बच्चों को कक्षा 1 में पहुँचने से पहले दवाओं और बीमारियों के नाम सिखाना","बच्चों को कागज़ में व्यस्त रखना जबकि वह एक छोटे पठन समूह के साथ काम करती है","बच्चों को अपने खेल के भीतर पठन और लेखन को वास्तविक उद्देश्यों के लिए उपयोग करने देना","यह परखना कि कौन-से बच्चे पहले से बिना सहायता के शब्द सही लिख सकते हैं"],"explanationHi":"नाटकीय खेल में साक्षरता-सामग्री बच्चों को छपाई का उपयोग वैसे करने देती है जैसे लोग वास्तव में करते हैं, नुस्ख़े लिखने और संकेत पढ़ने का अभिनय करते हुए, जो समझ बनाता है कि साक्षरता किसलिए है।"},
  {"id":"cdp-pedagogy-subjects-1959","question":"A four-year-old says ‘wabbit’ for ‘rabbit’ and ‘fank you’ for ‘thank you’, while her speech is otherwise clear and fluent. What should the teacher do?","options":["Make her repeat each word correctly several times whenever she says it wrongly","Refer her at once to a speech therapist, since such errors at this age clearly show a speech disorder","Ask her classmates to correct her whenever she uses these words in class","Model the words naturally in talk, without making her repeat them; these sounds often develop later"],"answer":3,"explanation":"Sounds such as /r/ and /th/ are among the last to develop, and such substitutions are common at four. Natural modelling is enough; repeated correction can make children self-conscious, though persistent difficulty later may need referral.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT","questionHi":"चार वर्ष की एक बच्ची ‘rabbit’ के लिए ‘wabbit’ और ‘thank you’ के लिए ‘fank you’ कहती है, जबकि उसकी वाणी बाकी स्पष्ट और धाराप्रवाह है। शिक्षिका को क्या करना चाहिए?","optionsHi":["जब भी वह गलत कहे उससे हर शब्द सही ढंग से कई बार दोहरवाना","तुरंत उसे वाक्-चिकित्सक के पास भेजना, क्योंकि इस आयु में ऐसी त्रुटियाँ स्पष्ट रूप से वाक्-विकार दिखाती हैं","सहपाठियों से कहना कि जब भी वह कक्षा में ये शब्द बोले उसे सुधारें","शब्दों को बातचीत में स्वाभाविक रूप से प्रस्तुत करना, उसे दोहराने को कहे बिना; ये ध्वनियाँ प्रायः बाद में विकसित होती हैं"],"explanationHi":"/r/ और /th/ जैसी ध्वनियाँ सबसे देर से विकसित होने वालों में हैं, और ऐसे प्रतिस्थापन चार वर्ष की आयु में सामान्य हैं। स्वाभाविक प्रस्तुति पर्याप्त है; बार-बार सुधार बच्चों को आत्म-सचेत बना सकता है, यद्यपि बाद में लगातार कठिनाई के लिए संदर्भित करना आवश्यक हो सकता है।"},
  {"id":"cdp-pedagogy-subjects-1960","question":"Reading a memorised big-book line aloud and pointing to each word, a Class 1 child points to two words while saying ‘ba-by’ and ends up pointing at the wrong word. What does this show?","options":["She has not memorised the line well and should repeat it more often","She is still forming the concept of a written word, matching each spoken syllable to a printed word","She has an eye-movement problem that makes her finger move ahead of her eyes on the page of text","She is careless while pointing and should be asked to read more slowly and quietly"],"answer":1,"explanation":"Matching voice to print depends on knowing that a written word may hold several syllables. Her syllable-by-syllable pointing shows that this concept of word is still forming, an important step before decoding.","difficulty":"very-hard","source":"KVS PRT · NVS PRT","questionHi":"याद की हुई बड़ी किताब की पंक्ति को ज़ोर से पढ़ते और हर शब्द की ओर संकेत करते हुए कक्षा 1 की एक बच्ची ‘ba-by’ बोलते समय दो शब्दों की ओर इशारा करती है और गलत शब्द पर पहुँच जाती है। यह क्या दिखाता है?","optionsHi":["उसने पंक्ति अच्छी तरह याद नहीं की है और उसे और बार दोहराना चाहिए","वह अभी लिखित शब्द की संकल्पना बना रही है, हर बोले गए शब्दांश को छपे शब्द से मिलाते हुए","उसे आँखों की गति की समस्या है जिससे पाठ के पृष्ठ पर उसकी उँगली उसकी आँखों से आगे चली जाती है","वह इशारा करते समय लापरवाह है और उसे धीमे और चुपचाप पढ़ने को कहा जाना चाहिए"],"explanationHi":"आवाज़ को छपाई से मिलाना यह जानने पर निर्भर करता है कि एक लिखित शब्द में कई शब्दांश हो सकते हैं। उसका शब्दांश-दर-शब्दांश इशारा दिखाता है कि शब्द की यह संकल्पना अभी बन रही है, जो विसंकेतन से पहले का एक महत्वपूर्ण चरण है।"},
  {"id":"cdp-pedagogy-subjects-1961","question":"A five-year-old often writes ‘b’ for ‘d’ and sometimes writes her name in mirror image, but is learning letters well otherwise. What is the most appropriate view?","options":["These are clear signs of dyslexia, and she should be referred for formal testing immediately","Such reversals are common at this age; teach formation and give practice, and watch over time","She should stop writing for a few months until her brain matures enough to stop reversing","Reversals show poor eyesight, and she needs an eye test before any further writing work"],"answer":1,"explanation":"Letter reversals are normal in young writers, since objects stay the same when flipped but letters do not. Clear formation teaching and time usually resolve them; concern arises only if they persist with other difficulties.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"पाँच वर्ष की एक बच्ची अक्सर ‘d’ के लिए ‘b’ लिखती है और कभी-कभी अपना नाम दर्पण-प्रतिबिंब में लिखती है, पर अन्यथा अक्षर अच्छी तरह सीख रही है। सबसे उपयुक्त दृष्टिकोण क्या है?","optionsHi":["ये डिस्लेक्सिया के स्पष्ट संकेत हैं, और उसे तुरंत औपचारिक परीक्षण के लिए भेजा जाना चाहिए","इस आयु में ऐसे उलटाव आम हैं; बनावट सिखाएँ और अभ्यास दें, और समय के साथ देखें","उसे कुछ महीने लिखना बंद कर देना चाहिए जब तक उसका मस्तिष्क इतना परिपक्व न हो जाए कि उलटना बंद कर दे","उलटाव कमज़ोर नज़र दिखाते हैं, और आगे लेखन-कार्य से पहले उसे आँखों की जाँच की आवश्यकता है"],"explanationHi":"छोटे लेखकों में अक्षरों के उलटाव सामान्य हैं, क्योंकि वस्तुएँ पलटने पर वही रहती हैं पर अक्षर नहीं। स्पष्ट बनावट-शिक्षण और समय प्रायः उन्हें हल कर देते हैं; चिंता तभी होती है जब वे अन्य कठिनाइयों के साथ बने रहें।"},
  {"id":"cdp-pedagogy-subjects-1962","question":"A pre-primary teacher often asks children to talk about things not in front of them: ‘What did you do at your nani's house?’ ‘What will we need for tomorrow's picnic?’ Why does such talk especially support later reading?","options":["It builds the language needed to describe things beyond the here and now, as written texts do","It checks whether parents are taking their children to visit relatives and friends on the weekends","It trains children's memory, which is the main skill needed for reading later","It replaces story reading, since children learn more from their own talk"],"answer":0,"explanation":"Decontextualised talk about past, future or absent things uses explicit, connected language much like written text, and children skilled in it tend to comprehend books better.","difficulty":"very-hard","source":"KVS PRT · NVS PRT","questionHi":"एक पूर्व-प्राथमिक शिक्षिका अक्सर बच्चों से उन चीज़ों के बारे में बात करने को कहती है जो उनके सामने नहीं हैं: ‘तुमने नानी के घर क्या किया?’ ‘कल की पिकनिक के लिए हमें क्या चाहिए होगा?’ ऐसी बातचीत बाद के पठन को विशेष रूप से क्यों सहारा देती है?","optionsHi":["यह यहाँ-और-अभी से परे की चीज़ों का वर्णन करने के लिए आवश्यक भाषा बनाती है, जैसा लिखित पाठ करते हैं","यह जाँचती है कि अभिभावक सप्ताहांत में बच्चों को रिश्तेदारों और मित्रों से मिलाने ले जाते हैं या नहीं","यह बच्चों की स्मृति को प्रशिक्षित करती है, जो बाद में पठन के लिए आवश्यक मुख्य कौशल है","यह कहानी पढ़ने की जगह लेती है, क्योंकि बच्चे अपनी बातचीत से अधिक सीखते हैं"],"explanationHi":"अतीत, भविष्य या अनुपस्थित चीज़ों के बारे में संदर्भ-मुक्त बातचीत स्पष्ट, जुड़ी हुई भाषा का उपयोग करती है जो लिखित पाठ जैसी होती है, और इसमें कुशल बच्चे पुस्तकों को बेहतर समझते हैं।"},
  {"id":"cdp-pedagogy-subjects-1963","question":"Before reading a story aloud to Class 2, a teacher chooses a few words to teach. Following Beck's tiers of vocabulary, which set should she focus on?","options":["‘the’, ‘is’ and ‘and’, since children will meet these words most often in texts","‘photosynthesis’, ‘isotope’ and ‘mitosis’, since technical words are always the hardest ones","‘enormous’, ‘grumble’ and ‘curious’, useful words found more in books than in talk","Every new word in the story, since all unknown words are equally important"],"answer":2,"explanation":"Tier 2 words are high-utility words of mature language that appear across texts but less in everyday talk, so teaching them gives the most benefit. Tier 1 words are already known, and Tier 3 words are subject-specific.","difficulty":"hard","source":"KVS PRT · CTET Paper 1","questionHi":"कक्षा 2 को कहानी ज़ोर से पढ़ने से पहले एक शिक्षिका पढ़ाने के लिए कुछ शब्द चुनती है। बेक के शब्दावली-स्तरों (tiers) के अनुसार उसे किस समूह पर ध्यान देना चाहिए?","optionsHi":["‘the’, ‘is’ और ‘and’, क्योंकि बच्चे ये शब्द पाठों में सबसे अधिक बार देखेंगे","‘photosynthesis’, ‘isotope’ और ‘mitosis’, क्योंकि तकनीकी शब्द हमेशा सबसे कठिन होते हैं","‘enormous’, ‘grumble’ और ‘curious’, उपयोगी शब्द जो बातचीत की तुलना में पुस्तकों में अधिक मिलते हैं","कहानी का हर नया शब्द, क्योंकि सभी अज्ञात शब्द समान रूप से महत्वपूर्ण हैं"],"explanationHi":"स्तर 2 (Tier 2) के शब्द परिपक्व भाषा के उच्च-उपयोगिता वाले शब्द हैं जो पाठों में आते हैं पर रोज़मर्रा की बातचीत में कम, इसलिए उन्हें पढ़ाने से सबसे अधिक लाभ होता है। स्तर 1 के शब्द पहले से ज्ञात हैं, और स्तर 3 के शब्द विषय-विशिष्ट हैं।"},
  {"id":"cdp-pedagogy-subjects-1964","question":"At the end of a Class 2 writing period, one child sits in a special chair and reads out her piece, and classmates say what they liked and ask questions. The main purpose of this ‘author's chair’ is to:","options":["grade the best writer in the class publicly, which motivates the others to try harder","let the teacher correct the child's errors in front of the class for everyone's benefit","fill the last few minutes of the period with an activity that needs no planning","give children a real audience and help them see themselves as writers"],"answer":3,"explanation":"Sharing with listeners who respond and ask questions makes writing purposeful and builds identity as authors; it also models how readers react. It is not a public correction or ranking.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 2 के लेखन-पीरियड के अंत में एक बच्ची विशेष कुर्सी पर बैठकर अपनी रचना पढ़ती है, और सहपाठी बताते हैं कि उन्हें क्या अच्छा लगा और प्रश्न पूछते हैं। इस ‘लेखक की कुर्सी’ (author's chair) का मुख्य उद्देश्य है:","optionsHi":["कक्षा के सबसे अच्छे लेखक को सार्वजनिक रूप से ग्रेड देना, जो बाकी को अधिक प्रयास करने के लिए प्रेरित करता है","शिक्षिका को सबके लाभ के लिए कक्षा के सामने बच्चे की त्रुटियाँ सुधारने देना","पीरियड के अंतिम कुछ मिनटों को ऐसी गतिविधि से भरना जिसकी कोई योजना नहीं चाहिए","बच्चों को वास्तविक श्रोता-वर्ग देना और उन्हें स्वयं को लेखक के रूप में देखने में मदद करना"],"explanationHi":"प्रतिक्रिया देने और प्रश्न पूछने वाले श्रोताओं के साथ साझा करना लेखन को उद्देश्यपूर्ण बनाता है और लेखक के रूप में पहचान बनाता है; यह पाठक कैसे प्रतिक्रिया देते हैं उसका भी आदर्श है। यह सार्वजनिक सुधार या क्रम-निर्धारण नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1965","question":"A teacher listens to a Class 2 child read a short text and finds she reads about 92 words correctly out of 100. For guided reading with teacher support, this text is best described as being at her:","options":["independent level, so she should read it alone at home","frustration level, so it should be put away at once","listening level, so it should only be read aloud to her","instructional level, suitable for reading with support"],"answer":3,"explanation":"Commonly used guides treat about 95% or more accuracy as independent, about 90–95% as instructional, and below about 90% as frustration level. At 92% the text suits teacher-supported reading.","difficulty":"very-hard","source":"KVS PRT · NVS PRT","questionHi":"एक शिक्षिका कक्षा 2 की एक बच्ची को छोटा पाठ पढ़ते सुनती है और पाती है कि वह 100 में से लगभग 92 शब्द सही पढ़ती है। शिक्षिका की सहायता से निर्देशित पठन के लिए, यह पाठ उसके किस स्तर का सबसे अच्छी तरह वर्णित है?","optionsHi":["स्वतंत्र स्तर, इसलिए उसे इसे घर पर अकेले पढ़ना चाहिए","हताशा स्तर (frustration level), इसलिए इसे तुरंत रख देना चाहिए","श्रवण स्तर, इसलिए इसे केवल उसे पढ़कर सुनाया जाना चाहिए","अनुदेशात्मक स्तर (instructional level), सहायता के साथ पढ़ने के लिए उपयुक्त"],"explanationHi":"आमतौर पर प्रयुक्त मार्गदर्शिकाएँ लगभग 95% या अधिक शुद्धता को स्वतंत्र, लगभग 90–95% को अनुदेशात्मक, और लगभग 90% से कम को हताशा स्तर मानती हैं। 92% पर पाठ शिक्षिका-सहायता प्राप्त पठन के उपयुक्त है।"},
  {"id":"cdp-pedagogy-subjects-1966","question":"Which statement best describes systematic phonics teaching?","options":["Letter sounds are taught only when a child happens to ask about a word while reading","Children are left to discover letter-sound links on their own from wide and varied reading","Letter-sound links are taught explicitly in a planned sequence and applied in reading","Children memorise whole words by shape, and letters are introduced only in Class 3"],"answer":2,"explanation":"Systematic phonics follows a planned sequence of letter-sound relationships taught directly, with practice in blending and reading. Incidental or discovery approaches leave gaps for many children.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कौन-सा कथन व्यवस्थित वर्ण-ध्वनि शिक्षण (systematic phonics) का सबसे अच्छा वर्णन करता है?","optionsHi":["अक्षर-ध्वनियाँ केवल तब सिखाई जाती हैं जब पढ़ते समय बच्चा संयोग से किसी शब्द के बारे में पूछे","बच्चों को व्यापक और विविध पठन से अक्षर-ध्वनि संबंध अपने आप खोजने के लिए छोड़ दिया जाता है","अक्षर-ध्वनि संबंध योजनाबद्ध क्रम में स्पष्ट रूप से सिखाए जाते हैं और पठन में लागू किए जाते हैं","बच्चे पूरे आकार से शब्द याद करते हैं, और अक्षर केवल कक्षा 3 में परिचित कराए जाते हैं"],"explanationHi":"व्यवस्थित वर्ण-ध्वनि शिक्षण अक्षर-ध्वनि संबंधों के योजनाबद्ध क्रम का पालन करता है जो सीधे सिखाए जाते हैं, जोड़ने और पढ़ने के अभ्यास के साथ। आकस्मिक या खोज-आधारित उपागम बहुत-से बच्चों के लिए कमियाँ छोड़ देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1967","question":"A Class 1 child writes ‘Iwenttothepark’ with no spaces. Which support is most useful?","options":["Have her read it back while pointing, find where words begin, and leave a finger space","Rewrite the sentence correctly for her and ask her to copy it ten times into her notebook","Ignore it, since spacing will appear on its own once she starts Class 3","Mark the sentence wrong so that she learns to take more care next time"],"answer":0,"explanation":"Spacing depends on the concept of a written word; reading back while pointing helps her find word boundaries, and a finger spacer gives a practical tool. Copying or marking wrong does not build the concept.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 1 की एक बच्ची ‘Iwenttothepark’ बिना किसी रिक्ति के लिखती है। कौन-सी सहायता सबसे उपयोगी है?","optionsHi":["उससे इसे इशारा करते हुए वापस पढ़वाना, पता करना कि शब्द कहाँ शुरू होते हैं, और उँगली भर की जगह छोड़ना","उसके लिए वाक्य सही लिख देना और उससे उसे अपनी कॉपी में दस बार उतारने को कहना","अनदेखी करना, क्योंकि कक्षा 3 शुरू होने पर रिक्ति अपने आप आ जाएगी","वाक्य को गलत चिह्नित करना ताकि वह अगली बार अधिक सावधान रहना सीखे"],"explanationHi":"रिक्ति लिखित शब्द की संकल्पना पर निर्भर करती है; इशारा करते हुए वापस पढ़ना उसे शब्दों की सीमाएँ खोजने में मदद करता है, और उँगली-रिक्तिदर्शक एक व्यावहारिक उपकरण देता है। उतारना या गलत चिह्नित करना संकल्पना नहीं बनाता।"},
  {"id":"cdp-pedagogy-subjects-1968","question":"While reading a story aloud, a Class 2 teacher pauses and says, ‘Close your eyes. What do you see in the old woman's kitchen? What can you smell?’ This mainly develops:","options":["phonemic awareness, since children listen for the sounds in the words","visualisation, a comprehension strategy of building mental images","fluency, since children practise reading the text more quickly","spelling, since children picture how each word is written"],"answer":1,"explanation":"Asking children to form mental images from the text is the visualising strategy, which helps them engage with and remember what they hear or read. It is not about sounds, speed or spelling.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कहानी ज़ोर से पढ़ते हुए कक्षा 2 की एक शिक्षिका रुकती है और कहती है, ‘आँखें बंद करो। बुढ़िया की रसोई में तुम्हें क्या दिखता है? तुम्हें कौन-सी गंध आती है?’ यह मुख्यतः क्या विकसित करता है?","optionsHi":["स्वनिम-जागरूकता, क्योंकि बच्चे शब्दों में ध्वनियाँ सुनते हैं","दृश्यीकरण (visualisation), मानसिक छवियाँ बनाने की बोध-रणनीति","प्रवाह, क्योंकि बच्चे पाठ को अधिक जल्दी पढ़ने का अभ्यास करते हैं","वर्तनी, क्योंकि बच्चे कल्पना करते हैं कि हर शब्द कैसे लिखा जाता है"],"explanationHi":"बच्चों से पाठ से मानसिक छवियाँ बनाने को कहना दृश्यीकरण की रणनीति है, जो उन्हें जो सुनते या पढ़ते हैं उससे जुड़ने और उसे याद रखने में मदद करती है। यह ध्वनियों, गति या वर्तनी के बारे में नहीं है।"},
  {"id":"cdp-pedagogy-subjects-1969","question":"A Class 2 child reads ‘city’ as ‘kitty’. What is the best teaching response?","options":["Tell her she guessed and ask her to look carefully at every letter","Ask her to learn ‘city’ as a sight word, since it breaks all the rules","Show that ‘c’ often says /s/ before e, i or y, and check meaning","Teach her that the letter ‘c’ always makes the sound /k/ in English"],"answer":2,"explanation":"She applied the most common sound of ‘c’; the next step is the pattern that ‘c’ is usually soft before e, i and y, together with checking that the word makes sense. ‘c’ does not always say /k/.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 2 की एक बच्ची ‘city’ को ‘kitty’ पढ़ती है। सबसे अच्छी शिक्षण-प्रतिक्रिया क्या है?","optionsHi":["उसे बताना कि उसने अनुमान लगाया और उससे हर अक्षर को ध्यान से देखने को कहना","उससे ‘city’ को दृष्टि-शब्द के रूप में सीखने को कहना, क्योंकि वह सभी नियम तोड़ता है","दिखाना कि ‘c’ प्रायः e, i या y से पहले /s/ बोलता है, और अर्थ की जाँच करना","उसे सिखाना कि अंग्रेज़ी में अक्षर ‘c’ हमेशा /k/ ध्वनि देता है"],"explanationHi":"उसने ‘c’ की सबसे आम ध्वनि लागू की; अगला चरण यह पैटर्न है कि ‘c’ प्रायः e, i और y से पहले कोमल होता है, साथ ही जाँचना कि शब्द अर्थपूर्ण है। ‘c’ हमेशा /k/ नहीं बोलता।"},
  {"id":"cdp-pedagogy-subjects-1970","question":"A Class 1 child sometimes reads ‘was’ as ‘saw’ and ‘on’ as ‘no’. What is the most useful response?","options":["Encourage her to track left to right with a finger and check whether the sentence makes sense","Refer her for dyslexia testing, since such reversals happen only in children with that difficulty","Remove these words from her reading books until she is older and more careful","Have her copy both words ten times each so that their shapes become fixed"],"answer":0,"explanation":"Such reversals are common in beginners still building left-to-right scanning. Tracking with a finger and checking meaning (‘I saw a dog’ vs ‘I was a dog’) helps her self-correct.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"कक्षा 1 की एक बच्ची कभी-कभी ‘was’ को ‘saw’ और ‘on’ को ‘no’ पढ़ती है। सबसे उपयोगी प्रतिक्रिया क्या है?","optionsHi":["उसे उँगली से बाएँ से दाएँ अनुसरण करने और जाँचने के लिए प्रोत्साहित करना कि वाक्य अर्थपूर्ण है या नहीं","उसे डिस्लेक्सिया परीक्षण के लिए भेजना, क्योंकि ऐसे उलटाव केवल उसी कठिनाई वाले बच्चों में होते हैं","जब तक वह बड़ी और अधिक सावधान न हो जाए ये शब्द उसकी पठन-पुस्तकों से हटा देना","उससे दोनों शब्द दस-दस बार उतरवाना ताकि उनके आकार पक्के हो जाएँ"],"explanationHi":"ऐसे उलटाव उन शुरुआती पाठकों में आम हैं जो अभी बाएँ-से-दाएँ स्कैन करना बना रहे हैं। उँगली से अनुसरण करना और अर्थ जाँचना (‘I saw a dog’ बनाम ‘I was a dog’) उसे स्वयं सुधारने में मदद करता है।"},
  {"id":"cdp-pedagogy-subjects-1971","question":"In the SAMR model of technology use, which of these is an example of ‘redefinition’ rather than ‘substitution’?","options":["Students type the same essay on a computer instead of writing it by hand in their notebooks","Students in two schools co-create a survey of local birds online and map their data together","The teacher shares the textbook chapter as a PDF so students can read it on a tablet at home","Students answer the usual worksheet questions in an online form instead of on printed paper"],"answer":1,"explanation":"Redefinition means technology makes possible a task that could not be done before, such as real-time collaboration and shared mapping across schools. Typing, PDFs and online forms simply replace paper (substitution).","difficulty":"very-hard","source":"KVS TGT · NVS TGT · DSSSB","questionHi":"प्रौद्योगिकी उपयोग के SAMR मॉडल में, इनमें से कौन-सा ‘प्रतिस्थापन’ के बजाय ‘पुनर्परिभाषा’ (redefinition) का उदाहरण है?","optionsHi":["विद्यार्थी कॉपी में हाथ से लिखने के बजाय वही निबंध कंप्यूटर पर टाइप करते हैं","दो विद्यालयों के विद्यार्थी स्थानीय पक्षियों का सर्वेक्षण ऑनलाइन साथ बनाते हैं और अपने आँकड़े साथ मानचित्रित करते हैं","शिक्षिका पाठ्यपुस्तक का अध्याय PDF के रूप में साझा करती है ताकि विद्यार्थी उसे घर पर टैबलेट पर पढ़ सकें","विद्यार्थी छपे कागज़ के बजाय ऑनलाइन फ़ॉर्म में सामान्य कार्यपत्रक के प्रश्नों के उत्तर देते हैं"],"explanationHi":"पुनर्परिभाषा का अर्थ है कि प्रौद्योगिकी ऐसा कार्य संभव बनाती है जो पहले नहीं हो सकता था, जैसे विद्यालयों के बीच वास्तविक समय का सहयोग और साझा मानचित्रण। टाइप करना, PDF और ऑनलाइन फ़ॉर्म केवल कागज़ की जगह लेते हैं (प्रतिस्थापन)।"},
  {"id":"cdp-pedagogy-subjects-1972","question":"For a project, Class 8 students find a polished website with striking claims about a health remedy. Which habit best helps them judge its reliability?","options":["Trust it if it looks professional and has many pictures, graphs and colourful charts","Trust it if it appears at the top of the search results, since search engines rank by accuracy","Read the whole site carefully from start to end, since a site explains its own reliability best","Leave the site and check what other trusted sources say about it and its claims"],"answer":3,"explanation":"Lateral reading, checking what independent sources say about a site and its claims, is what skilled fact-checkers do. Appearance, ranking or the site's own description of itself are poor guides.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"एक परियोजना के लिए कक्षा 8 के विद्यार्थियों को एक स्वास्थ्य उपाय के बारे में आकर्षक दावों वाली चमकदार वेबसाइट मिलती है। कौन-सी आदत उन्हें उसकी विश्वसनीयता आँकने में सबसे अच्छी तरह मदद करती है?","optionsHi":["यदि वह पेशेवर दिखती है और उसमें बहुत-से चित्र, आलेख और रंगीन चार्ट हैं तो उस पर भरोसा करना","यदि वह खोज परिणामों में सबसे ऊपर आती है तो उस पर भरोसा करना, क्योंकि खोज-इंजन शुद्धता के आधार पर क्रम देते हैं","पूरी साइट को शुरू से अंत तक ध्यान से पढ़ना, क्योंकि कोई साइट अपनी विश्वसनीयता सबसे अच्छी तरह स्वयं समझाती है","साइट छोड़कर यह जाँचना कि अन्य विश्वसनीय स्रोत उसके और उसके दावों के बारे में क्या कहते हैं"],"explanationHi":"पार्श्विक पठन (lateral reading), यानी यह जाँचना कि स्वतंत्र स्रोत किसी साइट और उसके दावों के बारे में क्या कहते हैं, वही है जो कुशल तथ्य-जाँचकर्ता करते हैं। दिखावट, क्रम या साइट का अपना विवरण खराब मार्गदर्शक हैं।"},
  {"id":"cdp-pedagogy-subjects-1973","question":"A Class 9 student wants to use a photograph marked with a Creative Commons ‘CC BY’ licence in her school presentation. What must she do?","options":["Use it and credit the creator, as the licence requires attribution","Ask the website to pay her for using it, since it is free content","Avoid it entirely, since all images found online are always illegal to use","Use it freely without any credit, since Creative Commons means no rights"],"answer":0,"explanation":"CC BY allows reuse, including adaptation, as long as the creator is credited. Creative Commons licences keep some rights, and many online images can be used lawfully when their licence terms are followed.","difficulty":"hard","source":"KVS TGT · CTET Paper 2","questionHi":"कक्षा 9 की एक विद्यार्थी अपनी विद्यालय की प्रस्तुति में क्रिएटिव कॉमन्स ‘CC BY’ लाइसेंस वाली तस्वीर का उपयोग करना चाहती है। उसे क्या करना चाहिए?","optionsHi":["उसे उपयोग करे और निर्माता को श्रेय दे, क्योंकि लाइसेंस श्रेय (attribution) माँगता है","वेबसाइट से कहे कि वह उसके उपयोग के लिए उसे भुगतान करे, क्योंकि यह निःशुल्क सामग्री है","उससे पूरी तरह बचे, क्योंकि ऑनलाइन मिलने वाली सभी छवियों का उपयोग हमेशा अवैध है","बिना किसी श्रेय के स्वतंत्र रूप से उपयोग करे, क्योंकि क्रिएटिव कॉमन्स का अर्थ कोई अधिकार नहीं"],"explanationHi":"CC BY रूपांतरण सहित पुनर्प्रयोग की अनुमति देता है, जब तक निर्माता को श्रेय दिया जाए। क्रिएटिव कॉमन्स लाइसेंस कुछ अधिकार रखते हैं, और अनेक ऑनलाइन छवियाँ तब वैध रूप से उपयोग की जा सकती हैं जब उनके लाइसेंस की शर्तों का पालन किया जाए।"},
  {"id":"cdp-pedagogy-subjects-1974","question":"Many students in a district have no internet at home but have a television with a DTH connection. Which resource best fits this situation?","options":["Live video classes on a paid conferencing platform that needs good bandwidth at home","Daily homework set only through a messaging app on the parents' smartphones","Government educational channels broadcast over DTH, such as Swayam Prabha","Asking students to visit a cyber café daily to download that day's materials"],"answer":2,"explanation":"Swayam Prabha offers free educational channels over DTH, which reach homes without internet. Options needing data, smartphones or cyber cafés exclude the very students the teacher wants to reach.","difficulty":"moderate","source":"KVS · NVS · DSSSB","questionHi":"एक ज़िले के बहुत-से विद्यार्थियों के घर पर इंटरनेट नहीं है पर DTH कनेक्शन वाला टेलीविज़न है। कौन-सा संसाधन इस स्थिति के सबसे अनुकूल है?","optionsHi":["सशुल्क सम्मेलन-मंच पर लाइव वीडियो कक्षाएँ जिनके लिए घर पर अच्छी बैंडविड्थ चाहिए","अभिभावकों के स्मार्टफ़ोन पर केवल मैसेजिंग ऐप के माध्यम से दिया गया दैनिक गृहकार्य","DTH पर प्रसारित सरकारी शैक्षिक चैनल, जैसे स्वयं प्रभा (Swayam Prabha)","विद्यार्थियों से उस दिन की सामग्री डाउनलोड करने के लिए हर दिन साइबर कैफ़े जाने को कहना"],"explanationHi":"स्वयं प्रभा DTH पर निःशुल्क शैक्षिक चैनल देता है, जो बिना इंटरनेट वाले घरों तक पहुँचते हैं। जिन विकल्पों में डेटा, स्मार्टफ़ोन या साइबर कैफ़े चाहिए वे ठीक उन्हीं विद्यार्थियों को बाहर कर देते हैं जिन तक शिक्षिका पहुँचना चाहती है।"},
  {"id":"cdp-pedagogy-subjects-1975","question":"A Class 8 student shares a dramatic photograph said to show a recent flood in their town. Which step best teaches students how to check whether it really shows this flood?","options":["Read the comments under the post to see whether people who live in the town confirm that it shows the flood","Do a reverse image search to find where and when the photograph first appeared online","Examine the image closely for signs of editing such as blurred edges, odd shadows or mismatched lighting","Check the date and location stored in the file information of the copy that was shared with them"],"answer":1,"explanation":"Most misleading flood photos are genuine images recycled from another time or place, and a reverse image search reveals where they first appeared. Looking for signs of editing is tempting, but an unedited old photo passes that test, and file details are usually stripped or reset when images are forwarded.","difficulty":"hard","source":"KVS TGT · CTET Paper 2","questionHi":"कक्षा 8 का एक विद्यार्थी नाटकीय तस्वीर साझा करता है जिसके बारे में कहा जाता है कि वह उनके शहर की हाल की बाढ़ दिखाती है। कौन-सा कदम विद्यार्थियों को सबसे अच्छी तरह सिखाता है कि जाँचें कि वह वास्तव में इसी बाढ़ को दिखाती है या नहीं?","optionsHi":["पोस्ट के नीचे की टिप्पणियाँ पढ़ना यह देखने के लिए कि शहर में रहने वाले लोग पुष्टि करते हैं कि वह बाढ़ को दिखाती है","उलटी छवि-खोज (reverse image search) करना यह पता लगाने के लिए कि तस्वीर ऑनलाइन पहली बार कहाँ और कब आई","छवि को ध्यान से देखना कि संपादन के संकेत हैं या नहीं, जैसे धुँधले किनारे, अजीब छायाएँ या बेमेल रोशनी","उनके साथ साझा की गई प्रति की फ़ाइल-जानकारी में संग्रहीत तिथि और स्थान जाँचना"],"explanationHi":"अधिकांश भ्रामक बाढ़ की तस्वीरें किसी अन्य समय या स्थान की असली छवियाँ होती हैं जिन्हें दोबारा प्रयोग किया गया है, और उलटी छवि-खोज प्रकट करती है कि वे पहले कहाँ आईं। संपादन के संकेत देखना आकर्षक है, पर बिना संपादित पुरानी तस्वीर वह परीक्षा पास कर लेती है, और छवियाँ आगे भेजे जाने पर फ़ाइल-विवरण प्रायः हटा या रीसेट हो जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1976","question":"A school buys animated e-storybooks for Class 1 with games, sound effects and pop-ups on every page. Teachers find children remember the stories less well than with print books. The most likely reason is that:","options":["the extra features pull attention away from the story and the talk around it","young children's eyes tire quickly on screens, so they stop following midway","the e-books read the words aloud, so children stop attending to the text","children turn print pages more slowly, which gives them time to absorb more"],"answer":0,"explanation":"Games, sound effects and pop-ups unrelated to the story compete for young children's limited attention and cut down adult–child talk about the book. Narration is tempting as a cause, but Class 1 recall depends on following the story, not on decoding print, and read-aloud supports that.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT","questionHi":"एक विद्यालय कक्षा 1 के लिए हर पृष्ठ पर खेलों, ध्वनि-प्रभावों और पॉप-अप वाली एनिमेटेड ई-कहानी पुस्तकें खरीदता है। शिक्षक पाते हैं कि बच्चे छपी पुस्तकों की तुलना में कहानियाँ कम याद रखते हैं। सबसे संभावित कारण यह है कि:","optionsHi":["अतिरिक्त सुविधाएँ ध्यान को कहानी और उसके आसपास की बातचीत से खींच लेती हैं","छोटे बच्चों की आँखें स्क्रीन पर जल्दी थक जाती हैं, इसलिए वे बीच में अनुसरण करना छोड़ देते हैं","ई-पुस्तकें शब्दों को ज़ोर से पढ़ती हैं, इसलिए बच्चे पाठ पर ध्यान देना बंद कर देते हैं","बच्चे छपे पृष्ठ धीरे पलटते हैं, जिससे उन्हें अधिक आत्मसात् करने का समय मिलता है"],"explanationHi":"कहानी से असंबंधित खेल, ध्वनि-प्रभाव और पॉप-अप छोटे बच्चों के सीमित ध्यान से होड़ करते हैं और पुस्तक के बारे में वयस्क–बच्चे की बातचीत कम कर देते हैं। वाचन को कारण मानना आकर्षक है, पर कक्षा 1 में स्मरण कहानी का अनुसरण करने पर निर्भर है, छपाई के विसंकेतन पर नहीं, और ज़ोर से पढ़ना उसे सहारा देता है।"},
  {"id":"cdp-pedagogy-subjects-1977","question":"Class 5 children, without computers, write exact step-by-step instructions for a partner to draw a shape, then fix the steps when the drawing goes wrong. This activity mainly develops:","options":["typing speed, which children will later need in order to write programs on a computer","drawing skills, since children must draw shapes accurately from instructions","memory, since children must remember long sets of instructions given orally","computational thinking: writing precise algorithms, testing and debugging them"],"answer":3,"explanation":"Unplugged activities build the core ideas of computing, precise sequencing, testing and debugging, without devices. The drawing is only a vehicle for checking whether the algorithm works.","difficulty":"hard","source":"KVS · NVS · CTET Paper 2","questionHi":"कक्षा 5 के बच्चे, बिना कंप्यूटर के, साथी के लिए कोई आकृति बनाने के सटीक चरण-दर-चरण निर्देश लिखते हैं, फिर चित्र गलत होने पर चरणों को ठीक करते हैं। यह गतिविधि मुख्यतः क्या विकसित करती है?","optionsHi":["टाइपिंग की गति, जिसकी बच्चों को बाद में कंप्यूटर पर प्रोग्राम लिखने के लिए आवश्यकता होगी","चित्रकला कौशल, क्योंकि बच्चों को निर्देशों से आकृतियाँ सटीक बनानी होती हैं","स्मृति, क्योंकि बच्चों को मौखिक रूप से दिए गए निर्देशों के लंबे समूह याद रखने होते हैं","कंप्यूटेशनल चिंतन: सटीक एल्गोरिद्म लिखना, उन्हें परखना और डीबग करना"],"explanationHi":"बिना उपकरण वाली गतिविधियाँ कंप्यूटिंग के मूल विचार, सटीक क्रम, परीक्षण और डीबगिंग, बिना उपकरणों के बनाती हैं। चित्र केवल यह जाँचने का माध्यम है कि एल्गोरिद्म काम करता है या नहीं।"},
  {"id":"cdp-pedagogy-subjects-1978","question":"A teacher wants to use a free quiz app that asks students to sign in with their phone numbers and photographs. What should she check first?","options":["Whether the app has the brightest colours and the most game features available","Whether most other teachers in the city are already using the app with their classes","What data the app collects, how it uses it, and whether parents' consent is needed","Whether the app has an option to show students' scores publicly on a leaderboard"],"answer":2,"explanation":"Children's personal data needs protection; teachers should read the privacy terms, collect only what is needed and get consent. Popularity, features or leaderboards say nothing about safety.","difficulty":"hard","source":"KVS · NVS · DSSSB","questionHi":"एक शिक्षिका एक निःशुल्क प्रश्नोत्तरी ऐप का उपयोग करना चाहती है जो विद्यार्थियों से फ़ोन नंबर और तस्वीरों से साइन इन करवाता है। उसे सबसे पहले क्या जाँचना चाहिए?","optionsHi":["क्या ऐप में सबसे चटक रंग और सबसे अधिक खेल-सुविधाएँ उपलब्ध हैं","क्या शहर के अधिकांश अन्य शिक्षक अपनी कक्षाओं के साथ पहले से ऐप का उपयोग कर रहे हैं","ऐप कौन-सा डेटा एकत्र करता है, उसका उपयोग कैसे करता है, और क्या अभिभावकों की सहमति आवश्यक है","क्या ऐप में विद्यार्थियों के अंक लीडरबोर्ड पर सार्वजनिक रूप से दिखाने का विकल्प है"],"explanationHi":"बच्चों के व्यक्तिगत आँकड़ों को सुरक्षा चाहिए; शिक्षकों को गोपनीयता की शर्तें पढ़नी चाहिए, केवल आवश्यक आँकड़े एकत्र करने चाहिए और सहमति लेनी चाहिए। लोकप्रियता, सुविधाएँ या लीडरबोर्ड सुरक्षा के बारे में कुछ नहीं बताते।"},
  {"id":"cdp-pedagogy-subjects-1979","question":"A teacher's video on the water cycle shows an animation, a voice-over, and the full voice-over text printed on screen at the same time. According to Mayer's multimedia principles, the main problem is:","options":["redundancy: the same words in speech and on screen overload learners and reduce learning","the video uses pictures, which distract from the words and so should be removed from it entirely","the video has a voice-over, which is less effective than reading printed text alone","there is no problem, since giving the same information three ways always helps"],"answer":0,"explanation":"Mayer's redundancy principle: learners do better with graphics and narration than with graphics, narration and identical on-screen text, which competes for visual attention. Pictures with narration are themselves effective.","difficulty":"very-hard","source":"KVS TGT · NVS TGT","questionHi":"एक शिक्षिका का जल-चक्र पर वीडियो एक साथ एनिमेशन, वॉइस-ओवर और पूरा वॉइस-ओवर पाठ स्क्रीन पर छपा दिखाता है। मेयर के बहुमाध्यम सिद्धांतों के अनुसार मुख्य समस्या है:","optionsHi":["अतिरेक (redundancy): वही शब्द वाणी और स्क्रीन पर अधिगमकर्ताओं पर बोझ डालते हैं और अधिगम घटाते हैं","वीडियो चित्रों का उपयोग करता है, जो शब्दों से ध्यान भटकाते हैं और इसलिए उससे पूरी तरह हटाए जाने चाहिए","वीडियो में वॉइस-ओवर है, जो अकेले छपे पाठ को पढ़ने से कम प्रभावी है","कोई समस्या नहीं है, क्योंकि वही जानकारी तीन तरीकों से देना हमेशा मदद करता है"],"explanationHi":"मेयर का अतिरेक सिद्धांत: अधिगमकर्ता चित्रों और वर्णन के साथ बेहतर सीखते हैं, चित्रों, वर्णन और समान स्क्रीन-पाठ के साथ नहीं, जो दृश्य ध्यान से होड़ करता है। वर्णन के साथ चित्र स्वयं प्रभावी हैं।"},
  {"id":"cdp-pedagogy-subjects-1980","question":"Several Class 10 students submit essays generated entirely by an AI chatbot. Which response by the teacher is most sound?","options":["Ban all digital tools at home and set only handwritten homework from now on","Redesign tasks around drafts, personal context and discussion, and teach critical use of AI","Accept the essays, since using available tools is a skill students will need later","Give zero marks to all essays that look very well written, since they are probably made by AI tools"],"answer":1,"explanation":"Process-based tasks with drafts, local or personal content and oral discussion make learning visible, while teaching students that chatbots can be wrong builds responsible use. Bans are unenforceable and guessing from quality is unfair.","difficulty":"very-hard","source":"KVS · NVS · DSSSB","questionHi":"कक्षा 10 के कई विद्यार्थी पूरी तरह AI चैटबॉट से बनाए निबंध जमा करते हैं। शिक्षिका की कौन-सी प्रतिक्रिया सबसे सही है?","optionsHi":["घर पर सभी डिजिटल उपकरणों पर रोक लगाना और अब से केवल हस्तलिखित गृहकार्य देना","कार्यों को मसौदों, व्यक्तिगत संदर्भ और चर्चा के आसपास फिर से बनाना, और AI के आलोचनात्मक उपयोग को सिखाना","निबंध स्वीकार करना, क्योंकि उपलब्ध उपकरणों का उपयोग वह कौशल है जिसकी विद्यार्थियों को बाद में आवश्यकता होगी","बहुत अच्छे लिखे दिखने वाले सभी निबंधों को शून्य अंक देना, क्योंकि वे संभवतः AI उपकरणों से बने हैं"],"explanationHi":"मसौदों, स्थानीय या व्यक्तिगत सामग्री और मौखिक चर्चा वाले प्रक्रिया-आधारित कार्य अधिगम को दृश्य बनाते हैं, जबकि विद्यार्थियों को सिखाना कि चैटबॉट गलत हो सकते हैं उत्तरदायी उपयोग बनाता है। प्रतिबंध लागू नहीं हो सकते और गुणवत्ता से अनुमान लगाना अनुचित है।"},
  {"id":"cdp-pedagogy-subjects-1981","question":"A teacher notices that some quiet Class 8 students who rarely speak in class write thoughtful posts in the class's online discussion forum. The most likely reason is that:","options":["online forums are always better than classroom discussion for every kind of student","quiet students are lazy in class and work hard only when they are at home","the forum lets students copy each other's ideas without being noticed","the forum gives them time to think and write without speaking in front of peers"],"answer":3,"explanation":"Asynchronous discussion allows time to reflect and removes the pressure of speaking aloud, so some students participate more fully. It complements rather than replaces classroom talk.","difficulty":"moderate","source":"KVS TGT · CTET Paper 2","questionHi":"एक शिक्षिका देखती है कि कक्षा 8 के कुछ शांत विद्यार्थी जो कक्षा में कम बोलते हैं, कक्षा के ऑनलाइन चर्चा-मंच पर विचारशील पोस्ट लिखते हैं। सबसे संभावित कारण यह है कि:","optionsHi":["ऑनलाइन मंच हर प्रकार के विद्यार्थी के लिए कक्षा-चर्चा से हमेशा बेहतर होते हैं","शांत विद्यार्थी कक्षा में आलसी होते हैं और केवल घर पर होने पर ही मेहनत करते हैं","मंच विद्यार्थियों को बिना ध्यान में आए एक-दूसरे के विचार उतारने देता है","मंच उन्हें सहपाठियों के सामने बोले बिना सोचने और लिखने का समय देता है"],"explanationHi":"असमकालिक चर्चा चिंतन का समय देती है और ज़ोर से बोलने का दबाव हटाती है, इसलिए कुछ विद्यार्थी अधिक पूर्ण रूप से भाग लेते हैं। यह कक्षा की बातचीत का पूरक है, उसकी जगह नहीं लेता।"},
  {"id":"cdp-pedagogy-subjects-1982","question":"A Class 7 teacher has each student keep an e-portfolio of drafts, recordings and final work across the year. Its main advantage for assessment is that it:","options":["replaces the need for the teacher to give students any feedback on their work","lets the teacher rank students more precisely at the end of the year","shows growth over time and lets students reflect on their own progress","takes less storage space than paper files kept in the school office"],"answer":2,"explanation":"A portfolio collects evidence over time, showing development and inviting self-reflection, which a single test cannot. Storage or ranking is not its purpose, and it supports rather than replaces feedback.","difficulty":"moderate","source":"KVS TGT · CTET Paper 2","questionHi":"कक्षा 7 की एक शिक्षिका हर विद्यार्थी से पूरे वर्ष भर के मसौदों, रिकॉर्डिंग और अंतिम कार्य का ई-पोर्टफ़ोलियो रखवाती है। आकलन के लिए इसका मुख्य लाभ यह है कि यह:","optionsHi":["शिक्षिका को विद्यार्थियों के कार्य पर कोई प्रतिपुष्टि देने की आवश्यकता से मुक्त कर देता है","शिक्षिका को वर्ष के अंत में विद्यार्थियों को अधिक सटीकता से क्रम देने देता है","समय के साथ विकास दिखाता है और विद्यार्थियों को अपनी प्रगति पर चिंतन करने देता है","विद्यालय कार्यालय में रखी कागज़ की फ़ाइलों से कम भंडारण-स्थान लेता है"],"explanationHi":"पोर्टफ़ोलियो समय के साथ साक्ष्य एकत्र करता है, विकास दिखाता है और आत्म-चिंतन को आमंत्रित करता है, जो एक अकेली परीक्षा नहीं कर सकती। भंडारण या क्रम-निर्धारण इसका उद्देश्य नहीं है, और यह प्रतिपुष्टि की जगह नहीं, उसका समर्थन करता है।"},
  {"id":"cdp-pedagogy-subjects-1983","question":"A Class 9 teacher has students move a slider for ‘m’ in y = mx + c on graphing software and describe what happens to the line. The main value of this is that students:","options":["see how changing one parameter changes the graph, and form general ideas from it","no longer need to plot any graphs by hand or to understand coordinates at all","can avoid learning the meaning of slope, since the software shows it","can finish the chapter much faster, since the software does all of the work for them"],"answer":0,"explanation":"Dynamic software lets students vary a parameter and observe its effect instantly, leading them to generalise about slope. It builds understanding of slope rather than replacing it.","difficulty":"hard","source":"KVS TGT · NVS TGT","questionHi":"कक्षा 9 की एक शिक्षिका विद्यार्थियों से आलेखन सॉफ़्टवेयर में y = mx + c के ‘m’ के लिए स्लाइडर हिलवाती है और वर्णन करवाती है कि रेखा का क्या होता है। इसका मुख्य मूल्य यह है कि विद्यार्थी:","optionsHi":["देखते हैं कि एक प्राचल (parameter) बदलने से आलेख कैसे बदलता है, और उससे सामान्य विचार बनाते हैं","अब हाथ से कोई आलेख बनाने या निर्देशांकों को समझने की आवश्यकता से मुक्त हो जाते हैं","ढाल का अर्थ सीखने से बच सकते हैं, क्योंकि सॉफ़्टवेयर उसे दिखाता है","अध्याय बहुत तेज़ पूरा कर सकते हैं, क्योंकि सॉफ़्टवेयर उनके लिए सारा काम कर देता है"],"explanationHi":"गतिशील सॉफ़्टवेयर विद्यार्थियों को एक प्राचल बदलने और उसका प्रभाव तुरंत देखने देता है, जो उन्हें ढाल के बारे में सामान्यीकरण की ओर ले जाता है। यह ढाल की समझ बनाता है, उसकी जगह नहीं लेता।"},
  {"id":"cdp-pedagogy-subjects-1984","question":"A Class 7 student with dyslexia understands science well but reads slowly. In a science test, the teacher lets her use text-to-speech to hear the questions. Is this fair?","options":["No, because it gives her an advantage over the other students in the same test","Yes, because the test measures science, and this removes a barrier unrelated to it","No, because she should learn to overcome her reading difficulty without any special help","Yes, but only if every other student in the class is also allowed to use the tool"],"answer":1,"explanation":"An accommodation is fair when it removes a barrier unrelated to what is assessed; here reading speed is not the construct, science understanding is. It does not lower the standard of the test.","difficulty":"very-hard","source":"KVS · NVS · DSSSB","questionHi":"कक्षा 7 की डिस्लेक्सिया से ग्रस्त एक विद्यार्थी विज्ञान अच्छी तरह समझती है पर धीमे पढ़ती है। विज्ञान की परीक्षा में शिक्षिका उसे प्रश्न सुनने के लिए टेक्स्ट-टू-स्पीच का उपयोग करने देती है। क्या यह उचित है?","optionsHi":["नहीं, क्योंकि यह उसे उसी परीक्षा में अन्य विद्यार्थियों पर बढ़त देता है","हाँ, क्योंकि परीक्षा विज्ञान को मापती है, और यह उससे असंबंधित बाधा को हटाता है","नहीं, क्योंकि उसे बिना किसी विशेष सहायता के अपनी पठन-कठिनाई से उबरना सीखना चाहिए","हाँ, पर केवल तभी जब कक्षा के अन्य सभी विद्यार्थियों को भी उपकरण का उपयोग करने की अनुमति हो"],"explanationHi":"कोई सुविधा तब उचित होती है जब वह आकलित की जा रही चीज़ से असंबंधित बाधा हटाती है; यहाँ पठन-गति नहीं, विज्ञान की समझ मापी जानी है। यह परीक्षा का मानक नहीं घटाती।"},
  {"id":"cdp-pedagogy-subjects-1985","question":"For a group report written in a shared online document, how can a teacher best judge each member's contribution?","options":["Give the same mark to every member, since group work should always be marked jointly","Ask the group leader alone to report who did the most work and mark on that basis","Mark only the final document's quality, since contributions cannot be known","Use the document's version history along with each student's short reflection"],"answer":3,"explanation":"Version history shows who wrote and revised what, and individual reflections add each student's account; together they support fair individual assessment within group work.","difficulty":"hard","source":"KVS TGT · CTET Paper 2","questionHi":"साझा ऑनलाइन दस्तावेज़ में लिखी समूह-रिपोर्ट के लिए, शिक्षिका हर सदस्य के योगदान को सबसे अच्छी तरह कैसे आँक सकती है?","optionsHi":["हर सदस्य को समान अंक देना, क्योंकि समूह-कार्य का अंकन हमेशा संयुक्त होना चाहिए","केवल समूह-नेता से ही बताने को कहना कि किसने सबसे अधिक काम किया, और उसी आधार पर अंक देना","केवल अंतिम दस्तावेज़ की गुणवत्ता पर अंक देना, क्योंकि योगदान जाने नहीं जा सकते","दस्तावेज़ के संस्करण-इतिहास (version history) का हर विद्यार्थी के छोटे चिंतन के साथ उपयोग करना"],"explanationHi":"संस्करण-इतिहास दिखाता है कि किसने क्या लिखा और संशोधित किया, और व्यक्तिगत चिंतन हर विद्यार्थी का विवरण जोड़ते हैं; साथ मिलकर वे समूह-कार्य के भीतर निष्पक्ष व्यक्तिगत आकलन को सहारा देते हैं।"},
  {"id":"cdp-pedagogy-subjects-1986","question":"After a Class 6 teacher firmly but calmly corrects one student for teasing, she notices several others who were about to tease also stop. Kounin called this:","options":["withitness","overlapping","the ripple effect","smoothness of momentum"],"answer":2,"explanation":"Kounin's ripple effect is the influence of a teacher's response to one student on the behaviour of others who see it. Withitness is awareness of everything happening; overlapping is handling two things at once.","difficulty":"very-hard","source":"KVS · NVS · DSSSB","questionHi":"कक्षा 6 की एक शिक्षिका जब एक विद्यार्थी को चिढ़ाने के लिए दृढ़ता पर शांति से सुधारती है, तो वह देखती है कि चिढ़ाने वाले कई अन्य भी रुक जाते हैं। कौनिन (Kounin) ने इसे कहा:","optionsHi":["सर्वज्ञता (withitness)","अतिव्यापन (overlapping)","लहर प्रभाव (ripple effect)","गति की सहजता (smoothness of momentum)"],"explanationHi":"कौनिन का लहर प्रभाव एक विद्यार्थी के प्रति शिक्षक की प्रतिक्रिया का उसे देखने वाले अन्य विद्यार्थियों के व्यवहार पर प्रभाव है। सर्वज्ञता हर होती चीज़ की जागरूकता है; अतिव्यापन एक साथ दो चीज़ें सँभालना है।"},
  {"id":"cdp-pedagogy-subjects-1987","question":"A Class 5 student carelessly tears a library book. Which response is a logical consequence rather than a punishment?","options":["He repairs the book with tape and helps the librarian mend other books for a period","He loses his recess for a whole week, so that he understands how serious his action was","He is made to stand at the back of the class during the next library period","He writes ‘I will take care of books’ a hundred times in his notebook"],"answer":0,"explanation":"A logical consequence is related to the behaviour and helps put things right, here repairing the damage. Losing recess, standing or writing lines are unrelated punishments that teach little about care for books.","difficulty":"hard","source":"CTET · KVS PRT · DSSSB PRT","questionHi":"कक्षा 5 का एक विद्यार्थी लापरवाही से पुस्तकालय की पुस्तक फाड़ देता है। कौन-सी प्रतिक्रिया दंड के बजाय तार्किक परिणाम है?","optionsHi":["वह टेप से पुस्तक की मरम्मत करता है और एक पीरियड तक पुस्तकालयाध्यक्ष की अन्य पुस्तकें ठीक करने में मदद करता है","वह पूरे एक सप्ताह की आधी छुट्टी खो देता है, ताकि वह समझे कि उसका कार्य कितना गंभीर था","उसे अगले पुस्तकालय पीरियड में कक्षा के पीछे खड़ा किया जाता है","वह अपनी कॉपी में ‘मैं पुस्तकों का ध्यान रखूँगा’ सौ बार लिखता है"],"explanationHi":"तार्किक परिणाम व्यवहार से संबंधित होता है और चीज़ें ठीक करने में मदद करता है, यहाँ क्षति की मरम्मत। आधी छुट्टी खोना, खड़ा होना या पंक्तियाँ लिखना असंबंधित दंड हैं जो पुस्तकों की देखभाल के बारे में कम सिखाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1988","question":"A school starts giving stickers for every book read. Children who used to read eagerly now read only short books to collect stickers, and stop reading when the scheme ends. This illustrates:","options":["the halo effect, in which one good trait colours the view of others","the overjustification effect, in which rewards weaken intrinsic interest","the Pygmalion effect, in which teachers' expectations shape students' performance","the recency effect, in which the last items learnt are best remembered"],"answer":1,"explanation":"Rewarding an activity that is already enjoyed can shift the reason for doing it to the reward, so interest drops when rewards stop. Rewards fit better for tasks with little initial interest.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"एक विद्यालय हर पढ़ी पुस्तक के लिए स्टिकर देना शुरू करता है। जो बच्चे पहले उत्सुकता से पढ़ते थे वे अब स्टिकर जुटाने के लिए केवल छोटी पुस्तकें पढ़ते हैं, और योजना खत्म होने पर पढ़ना बंद कर देते हैं। यह दर्शाता है:","optionsHi":["प्रभामंडल प्रभाव (halo effect), जिसमें एक अच्छा गुण दूसरों के बारे में दृष्टिकोण को रंग देता है","अति-औचित्य प्रभाव (overjustification effect), जिसमें पुरस्कार आंतरिक रुचि को कमज़ोर करते हैं","पिग्मेलियन प्रभाव (Pygmalion effect), जिसमें शिक्षकों की अपेक्षाएँ विद्यार्थियों के प्रदर्शन को आकार देती हैं","नवीनता प्रभाव (recency effect), जिसमें सीखी गई अंतिम चीज़ें सबसे अच्छी याद रहती हैं"],"explanationHi":"ऐसी गतिविधि को पुरस्कृत करना जो पहले से आनंददायक है, उसे करने का कारण पुरस्कार पर ले जा सकता है, इसलिए पुरस्कार रुकने पर रुचि घटती है। पुरस्कार उन कार्यों के लिए बेहतर बैठते हैं जिनमें आरंभ में बहुत कम रुचि हो।"},
  {"id":"cdp-pedagogy-subjects-1989","question":"A Class 7 teacher wants a whole-class discussion in which students respond to each other, not only to her. Which seating arrangement suits this best?","options":["Rows facing the board, so that all students can see the teacher clearly","Students seated in separate rows by ability, so similar students sit together","Single desks spaced far apart, as arranged for an examination in the hall","A U-shape or circle, so that students can see and talk to one another"],"answer":3,"explanation":"When students can see each other's faces, they address one another, which supports discussion. Rows direct talk to the teacher, and exam spacing discourages interaction.","difficulty":"moderate","source":"CTET · KVS","questionHi":"कक्षा 7 की एक शिक्षिका पूरी कक्षा की ऐसी चर्चा चाहती है जिसमें विद्यार्थी केवल उसे नहीं, एक-दूसरे को भी उत्तर दें। कौन-सी बैठक-व्यवस्था इसके लिए सबसे उपयुक्त है?","optionsHi":["पंक्तियाँ जो श्यामपट्ट की ओर हों, ताकि सभी विद्यार्थी शिक्षिका को स्पष्ट देख सकें","क्षमता के अनुसार अलग-अलग पंक्तियों में बैठे विद्यार्थी, ताकि समान विद्यार्थी साथ बैठें","अलग-अलग दूर-दूर रखे एकल डेस्क, जैसे हॉल में परीक्षा के लिए लगाए जाते हैं","U-आकार या वृत्त, ताकि विद्यार्थी एक-दूसरे को देख और उनसे बात कर सकें"],"explanationHi":"जब विद्यार्थी एक-दूसरे के चेहरे देख सकते हैं, तो वे एक-दूसरे को संबोधित करते हैं, जो चर्चा का सहारा बनता है। पंक्तियाँ बातचीत को शिक्षिका की ओर मोड़ती हैं, और परीक्षा की दूरी अंतःक्रिया को हतोत्साहित करती है।"},
  {"id":"cdp-pedagogy-subjects-1990","question":"A Class 3 teacher wastes several minutes each time she tries to get the class's attention during group work. Which practice is most likely to help?","options":["Shouting louder each time, so that every group can hear her clearly over all the noise","Stopping group work altogether, since it always makes the class too noisy","Teaching and practising a signal, such as a raised hand, until it is a routine","Punishing the noisiest group each time, so that the others learn from it"],"answer":2,"explanation":"Routines must be taught and rehearsed; an agreed attention signal practised until automatic saves time without raising voices. Abandoning group work or punishing groups does not build the routine.","difficulty":"moderate","source":"CTET · KVS PRT","questionHi":"कक्षा 3 की एक शिक्षिका समूह-कार्य के दौरान कक्षा का ध्यान खींचने की कोशिश में हर बार कई मिनट गँवाती है। कौन-सा अभ्यास सबसे अधिक मदद करेगा?","optionsHi":["हर बार और ज़ोर से चिल्लाना, ताकि हर समूह सारे शोर के बीच उसे स्पष्ट सुन सके","समूह-कार्य को पूरी तरह रोक देना, क्योंकि वह हमेशा कक्षा को बहुत शोरगुल वाला बना देता है","एक संकेत, जैसे उठा हुआ हाथ, सिखाना और उसका तब तक अभ्यास करना जब तक वह दिनचर्या न बन जाए","हर बार सबसे शोर करने वाले समूह को दंड देना, ताकि अन्य उससे सीखें"],"explanationHi":"दिनचर्याएँ सिखाई और दोहराई जानी चाहिए; तब तक अभ्यास किया गया तय ध्यान-संकेत स्वचालित हो जाता है और आवाज़ ऊँची किए बिना समय बचाता है। समूह-कार्य छोड़ना या समूहों को दंडित करना दिनचर्या नहीं बनाता।"},
  {"id":"cdp-pedagogy-subjects-1991","question":"A Class 4 teacher's homework often needs parents to explain new concepts. First-generation learners regularly return it incomplete. What is the best change?","options":["Set tasks that practise what was learnt in class and that children can do on their own","Give more homework to those particular children, so that they can catch up with the others","Ask parents to attend evening classes so that they can help with homework","Stop checking the homework of those children, since it is not their fault"],"answer":0,"explanation":"Homework should consolidate classroom learning and be within the child's independent reach; tasks that depend on parents' schooling disadvantage first-generation learners. More homework or excusing them does not help.","difficulty":"hard","source":"CTET · KVS PRT · DSSSB PRT","questionHi":"कक्षा 4 की एक शिक्षिका के गृहकार्य में प्रायः माता-पिता से नई संकल्पनाएँ समझाने की आवश्यकता होती है। प्रथम-पीढ़ी के अधिगमकर्ता नियमित रूप से उसे अधूरा लौटाते हैं। सबसे अच्छा बदलाव क्या है?","optionsHi":["ऐसे कार्य देना जो कक्षा में सीखे का अभ्यास कराएँ और जिन्हें बच्चे स्वयं कर सकें","उन्हीं बच्चों को और अधिक गृहकार्य देना, ताकि वे दूसरों के बराबर आ सकें","माता-पिता से संध्या-कक्षाओं में आने को कहना ताकि वे गृहकार्य में मदद कर सकें","उन बच्चों का गृहकार्य जाँचना बंद कर देना, क्योंकि यह उनकी गलती नहीं है"],"explanationHi":"गृहकार्य को कक्षा के अधिगम को पक्का करना चाहिए और बच्चे की स्वतंत्र पहुँच में होना चाहिए; माता-पिता की शिक्षा पर निर्भर कार्य प्रथम-पीढ़ी के अधिगमकर्ताओं को हानि पहुँचाते हैं। अधिक गृहकार्य या छूट देना मदद नहीं करता।"},
  {"id":"cdp-pedagogy-subjects-1992","question":"In a lesson on perimeter, a Class 5 teacher gives three groups tasks of differing complexity: finding perimeters of drawn rectangles, of irregular shapes, and designing a garden with a given perimeter. This is an example of:","options":["ability tracking, since children are permanently placed in fixed groups","tiered tasks: one concept with different levels of challenge","mastery learning, since all children must pass before moving on","peer tutoring, since stronger children teach weaker ones"],"answer":1,"explanation":"Tiered tasks keep the same learning goal (perimeter) while varying complexity so each child is challenged appropriately. Groups can change by task, unlike permanent tracking.","difficulty":"hard","source":"CTET · KVS","questionHi":"परिमाप के पाठ में कक्षा 5 की एक शिक्षिका तीन समूहों को अलग जटिलता के कार्य देती है: बने हुए आयतों के परिमाप निकालना, अनियमित आकृतियों के, और दिए परिमाप वाला बगीचा डिज़ाइन करना। यह उदाहरण है:","optionsHi":["क्षमता-अनुसार वर्गीकरण (ability tracking) का, क्योंकि बच्चे स्थायी रूप से निश्चित समूहों में रखे जाते हैं","स्तरित कार्यों (tiered tasks) का: एक संकल्पना, भिन्न चुनौती-स्तरों के साथ","पूर्णता अधिगम का, क्योंकि आगे बढ़ने से पहले सभी बच्चों को उत्तीर्ण होना होता है","सहपाठी-शिक्षण का, क्योंकि सशक्त बच्चे कमज़ोर बच्चों को पढ़ाते हैं"],"explanationHi":"स्तरित कार्य अधिगम का लक्ष्य वही रखते हैं (परिमाप) जबकि जटिलता बदलते हैं ताकि हर बच्चे को उपयुक्त चुनौती मिले। स्थायी वर्गीकरण के विपरीत, समूह कार्य के अनुसार बदल सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-1993","question":"A teacher presents a lesson through a story, a diagram and a demonstration, lets students choose to show their learning by writing, drawing or speaking, and offers choices of topic. This planning follows:","options":["the Herbartian steps, which give one fixed sequence of steps for every lesson taught","programmed instruction, which breaks the content into small frames with quick feedback","the grammar-translation method, adapted for content subjects","Universal Design for Learning: many ways to represent, express and engage"],"answer":3,"explanation":"UDL builds flexibility into planning from the start through multiple means of representation, action and expression, and engagement, so more learners, including those with disabilities, can access the lesson.","difficulty":"very-hard","source":"KVS · NVS · DSSSB","questionHi":"एक शिक्षिका पाठ को कहानी, आरेख और प्रदर्शन के माध्यम से प्रस्तुत करती है, विद्यार्थियों को लिखकर, चित्र बनाकर या बोलकर अपना अधिगम दिखाने का विकल्प देती है, और विषय के विकल्प भी देती है। यह योजना किसका अनुसरण करती है?","optionsHi":["हरबर्टीय सोपान (Herbartian steps), जो पढ़ाए जाने वाले हर पाठ के लिए चरणों का एक निश्चित क्रम देते हैं","अभिक्रमित अनुदेशन (programmed instruction), जो विषय-वस्तु को छोटे फ़्रेमों में तोड़ता है और त्वरित प्रतिपुष्टि देता है","व्याकरण-अनुवाद विधि, जिसे विषय-वस्तु वाले विषयों के लिए अनुकूलित किया गया है","अधिगम का सार्वभौमिक डिज़ाइन (Universal Design for Learning): निरूपण, अभिव्यक्ति और सहभागिता के अनेक तरीके"],"explanationHi":"UDL आरंभ से ही निरूपण, क्रिया और अभिव्यक्ति, तथा सहभागिता के अनेक साधनों के माध्यम से योजना में लचीलापन बनाता है, ताकि विकलांगता वाले सहित अधिक अधिगमकर्ता पाठ तक पहुँच सकें।"},
  {"id":"cdp-pedagogy-subjects-1994","question":"Midway through a lesson, a teacher asks one carefully designed multiple-choice question and checks all students' answers at once on fingers raised, deciding whether to move on or reteach. Such a question is called a:","options":["summative test item, recorded towards the final term grade","rhetorical question, which does not need any reply","hinge question, which decides the lesson's next step","closed recall question, which checks only memory"],"answer":2,"explanation":"A hinge question is placed at a key point of a lesson to quickly check whole-class understanding, with wrong options that reveal misconceptions; the responses decide whether to proceed or reteach.","difficulty":"hard","source":"KVS · NVS","questionHi":"पाठ के बीच में एक शिक्षिका एक सावधानी से बनाया बहुविकल्पीय प्रश्न पूछती है और सभी विद्यार्थियों के उत्तर एक साथ उठी उँगलियों से जाँचती है, तय करते हुए कि आगे बढ़ना है या फिर पढ़ाना है। ऐसे प्रश्न को कहते हैं:","optionsHi":["योगात्मक परीक्षा-प्रश्न, जो अंतिम सत्र के ग्रेड में दर्ज होता है","अलंकारिक प्रश्न, जिसके किसी उत्तर की आवश्यकता नहीं होती","निर्णायक प्रश्न (hinge question), जो पाठ का अगला चरण तय करता है","बंद स्मरण प्रश्न, जो केवल स्मृति की जाँच करता है"],"explanationHi":"निर्णायक प्रश्न (hinge question) पाठ के किसी मुख्य बिंदु पर पूरी कक्षा की समझ को जल्दी जाँचने के लिए रखा जाता है, गलत विकल्पों के साथ जो भ्रांतियाँ प्रकट करते हैं; उत्तर तय करते हैं कि आगे बढ़ना है या फिर पढ़ाना।"},
  {"id":"cdp-pedagogy-subjects-1995","question":"Research by Ruth Butler compared feedback as grades only, comments only, and grades with comments. Which result is most relevant for teachers?","options":["Comments alone led to more improvement; adding grades reduced attention to comments","Grades alone led to the most improvement, since students mainly want to earn higher marks","Grades with comments led to most improvement, since students get both","All three types of feedback led to the same amount of improvement"],"answer":0,"explanation":"Students given comments only improved most; when grades were added, they focused on the grade and largely ignored the comments. This supports descriptive feedback in formative assessment.","difficulty":"very-hard","source":"KVS · NVS · DSSSB","questionHi":"रूथ बटलर के अनुसंधान ने केवल ग्रेड, केवल टिप्पणियाँ, और ग्रेड सहित टिप्पणियों के रूप में प्रतिपुष्टि की तुलना की। शिक्षकों के लिए कौन-सा परिणाम सबसे अधिक प्रासंगिक है?","optionsHi":["केवल टिप्पणियों से अधिक सुधार हुआ; ग्रेड जोड़ने से टिप्पणियों पर ध्यान घटा","केवल ग्रेड से सबसे अधिक सुधार हुआ, क्योंकि विद्यार्थी मुख्यतः ऊँचे अंक पाना चाहते हैं","ग्रेड सहित टिप्पणियों से सबसे अधिक सुधार हुआ, क्योंकि विद्यार्थियों को दोनों मिलते हैं","तीनों प्रकार की प्रतिपुष्टि से सुधार की मात्रा समान रही"],"explanationHi":"केवल टिप्पणियाँ पाने वाले विद्यार्थियों में सबसे अधिक सुधार हुआ; जब ग्रेड जोड़े गए, तो उन्होंने ग्रेड पर ध्यान दिया और टिप्पणियों की बड़ी हद तक अनदेखी की। यह रचनात्मक आकलन में वर्णनात्मक प्रतिपुष्टि का समर्थन करता है।"},
  {"id":"cdp-pedagogy-subjects-1996","question":"In Bloom's mastery learning, what happens after a formative test shows that some students have not mastered a unit?","options":["They are moved to a lower section of the class, so that the rest of the class can move ahead","They receive corrective teaching through different methods and are tested again","They repeat the year, since mastery cannot be gained later on","They get lower grades, and the class moves on to the next unit"],"answer":1,"explanation":"Mastery learning follows formative tests with correctives, alternative ways of teaching the same content, and then a second test, while others do enrichment. It assumes most students can master content given time and suitable help.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"ब्लूम के पूर्णता अधिगम (mastery learning) में, जब रचनात्मक परीक्षा दिखाती है कि कुछ विद्यार्थियों ने इकाई में पूर्णता प्राप्त नहीं की है, तो क्या होता है?","optionsHi":["उन्हें कक्षा के निचले अनुभाग में भेजा जाता है, ताकि शेष कक्षा आगे बढ़ सके","उन्हें विभिन्न विधियों से उपचारात्मक शिक्षण मिलता है और उनकी फिर परीक्षा ली जाती है","वे वर्ष दोहराते हैं, क्योंकि पूर्णता बाद में प्राप्त नहीं हो सकती","उन्हें कम ग्रेड मिलते हैं, और कक्षा अगली इकाई पर बढ़ जाती है"],"explanationHi":"पूर्णता अधिगम रचनात्मक परीक्षाओं के बाद उपचारात्मक शिक्षण, उसी विषय-वस्तु को पढ़ाने के वैकल्पिक तरीके, और फिर दूसरी परीक्षा करता है, जबकि अन्य समृद्धि-कार्य करते हैं। यह मानता है कि अधिकांश विद्यार्थी समय और उपयुक्त सहायता मिलने पर विषय-वस्तु में पूर्णता पा सकते हैं।"},
  {"id":"cdp-pedagogy-subjects-1997","question":"A Class 4 classroom has walls covered with bought charts that never change. Another teacher keeps a ‘working wall’ showing the current topic's key words, examples and children's attempts, updated each week. The main advantage of the working wall is that:","options":["it looks more colourful and impresses visitors to the school","it saves money, since no charts need to be bought for the class","it covers more of the syllabus at once than ordinary charts do","it supports current learning, and children use it as they work"],"answer":3,"explanation":"Displays help when they connect with current learning and are used as a resource; a working wall changes with the topic and includes children's own work. Permanent decorative charts soon become invisible.","difficulty":"moderate","source":"CTET · KVS PRT","questionHi":"कक्षा 4 के एक कमरे की दीवारें खरीदे गए चार्टों से ढकी हैं जो कभी नहीं बदलते। एक दूसरी शिक्षिका ‘कार्य-दीवार’ (working wall) रखती है जो वर्तमान विषय के मुख्य शब्द, उदाहरण और बच्चों के प्रयास दिखाती है, और हर सप्ताह अद्यतन होती है। कार्य-दीवार का मुख्य लाभ यह है कि:","optionsHi":["यह अधिक रंगीन दिखती है और विद्यालय के आगंतुकों को प्रभावित करती है","यह पैसे बचाती है, क्योंकि कक्षा के लिए कोई चार्ट नहीं खरीदने पड़ते","यह साधारण चार्टों की तुलना में एक साथ अधिक पाठ्यक्रम को कवर करती है","यह वर्तमान अधिगम का समर्थन करती है, और बच्चे काम करते समय उसका उपयोग करते हैं"],"explanationHi":"प्रदर्शन तब मदद करते हैं जब वे वर्तमान अधिगम से जुड़ते हैं और संसाधन के रूप में उपयोग होते हैं; कार्य-दीवार विषय के साथ बदलती है और बच्चों का अपना कार्य शामिल करती है। स्थायी सजावटी चार्ट जल्दी अदृश्य हो जाते हैं।"},
  {"id":"cdp-pedagogy-subjects-1998","question":"At a parent–teacher meeting, which way of sharing a Class 3 child's progress is most useful?","options":["Telling parents only the child's rank in class, since it is easy to understand","Giving parents a list of all the mistakes the child made in the term","Showing samples of the child's work, describing strengths and next steps","Comparing the child with the best student in class, to motivate the family"],"answer":2,"explanation":"Descriptive reporting with work samples shows parents what the child can do and how to help next, in line with continuous assessment. Ranks, mistake lists and comparisons give little guidance.","difficulty":"hard","source":"CTET · KVS PRT","questionHi":"अभिभावक–शिक्षक बैठक में कक्षा 3 के बच्चे की प्रगति साझा करने का कौन-सा तरीका सबसे उपयोगी है?","optionsHi":["अभिभावकों को केवल कक्षा में बच्चे का क्रम बताना, क्योंकि वह समझने में आसान है","अभिभावकों को सत्र में बच्चे की की गई सभी गलतियों की सूची देना","बच्चे के कार्य के नमूने दिखाना, शक्तियों और अगले चरणों का वर्णन करना","परिवार को प्रेरित करने के लिए बच्चे की तुलना कक्षा के सर्वश्रेष्ठ विद्यार्थी से करना"],"explanationHi":"कार्य-नमूनों के साथ वर्णनात्मक प्रतिवेदन अभिभावकों को दिखाता है कि बच्चा क्या कर सकता है और आगे कैसे मदद करनी है, सतत आकलन के अनुरूप। क्रम, गलतियों की सूची और तुलनाएँ बहुत कम मार्गदर्शन देती हैं।"},
  {"id":"cdp-pedagogy-subjects-1999","question":"In anti-bullying work with Class 7, a teacher focuses on the students who watch bullying without joining in. Why does she give bystanders so much attention?","options":["Bystanders often decide whether bullying goes on; their support for the target can stop it","Bystanders are usually the hidden bullies, so they should be punished along with the main bully","Bystanders are not affected by bullying, so they make the most neutral witnesses","Bystanders should be told to keep away, since any action by them makes matters worse"],"answer":0,"explanation":"Bullying often depends on an audience; when peers refuse to laugh and support the target or seek help, it frequently stops. Teaching safe bystander action is a key part of prevention.","difficulty":"hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 7 के साथ धमकाने-विरोधी कार्य में एक शिक्षिका उन विद्यार्थियों पर ध्यान केंद्रित करती है जो धमकाने को देखते हैं पर उसमें शामिल नहीं होते। वह दर्शकों (bystanders) को इतना ध्यान क्यों देती है?","optionsHi":["दर्शक प्रायः तय करते हैं कि धमकाना चलता रहेगा या नहीं; लक्ष्य के प्रति उनका समर्थन उसे रोक सकता है","दर्शक प्रायः छिपे धमकाने वाले होते हैं, इसलिए उन्हें मुख्य धमकाने वाले के साथ दंडित किया जाना चाहिए","दर्शक धमकाने से प्रभावित नहीं होते, इसलिए वे सबसे तटस्थ गवाह बनते हैं","दर्शकों से कहा जाना चाहिए कि दूर रहें, क्योंकि उनकी कोई भी कार्रवाई स्थिति को और बिगाड़ती है"],"explanationHi":"धमकाना प्रायः श्रोता-वर्ग पर निर्भर करता है; जब सहपाठी हँसने से इनकार करते हैं और लक्ष्य का समर्थन करते या सहायता माँगते हैं, तो वह प्रायः रुक जाता है। सुरक्षित दर्शक-कार्रवाई सिखाना रोकथाम का एक प्रमुख हिस्सा है।"},
  {"id":"cdp-pedagogy-subjects-2000","question":"A Class 5 child clowns around and interrupts often; he stops briefly when the teacher reacts, then starts again. Following Dreikurs, the most likely goal of this behaviour, and the best response, is:","options":["revenge, so the teacher should avoid him and let his classmates handle the matter themselves","attention, so the teacher should give attention for positive behaviour, not the clowning","power, so the teacher should win a contest of wills by punishing him firmly","inadequacy, so the teacher should excuse him from all tasks he finds difficult"],"answer":1,"explanation":"Behaviour that stops when noticed and then resumes points to attention-seeking; the remedy is to minimise attention to the misbehaviour and give it generously for appropriate behaviour.","difficulty":"very-hard","source":"CTET · KVS · DSSSB","questionHi":"कक्षा 5 का एक बच्चा जोकर बनता और अक्सर बीच में बोलता है; जब शिक्षिका प्रतिक्रिया देती है तो वह थोड़ी देर रुकता है, फिर फिर शुरू कर देता है। ड्रेइकर्स के अनुसार, इस व्यवहार का सबसे संभावित लक्ष्य और सबसे अच्छी प्रतिक्रिया है:","optionsHi":["बदला, इसलिए शिक्षिका को उससे बचना चाहिए और मामला उसके सहपाठियों को स्वयं सँभालने देना चाहिए","ध्यान, इसलिए शिक्षिका को जोकरपन के बजाय सकारात्मक व्यवहार पर ध्यान देना चाहिए","शक्ति, इसलिए शिक्षिका को उसे कठोरता से दंडित करके इच्छाशक्ति की होड़ जीतनी चाहिए","अपर्याप्तता, इसलिए शिक्षिका को उसे उन सभी कार्यों से छूट देनी चाहिए जो उसे कठिन लगते हैं"],"explanationHi":"जो व्यवहार ध्यान दिए जाने पर रुकता है और फिर शुरू हो जाता है, वह ध्यान-प्राप्ति की ओर इशारा करता है; उपाय है कुव्यवहार पर ध्यान कम से कम करना और उचित व्यवहार पर उदारता से देना।"},
];

export default questions;
